 } from './primitives/InlineError';\nexport { Aviso, useAviso, type AvisoProps, type TonoAviso } from './primitives/Aviso';\nexport { EmptyState, type EmptyStateProps } from './primitives/EmptyState';\nexport { MasOpciones, type MasOpcionesProps } from './primitives/MasOpciones';\nexport { haptico, type TipoHaptico } from './feedback/hapticos';\nexport { anunciar } from './feedback/anuncios';\nexport { StepHeader, type StepState } from './primitives/StepHeader';\n/* `ScreenHeader` NO es `StepHeader`: aquel es la cabecera de un paso de flujo (barra de progreso\n   segmentada, sin volver), y este es la fila de pantalla con volver, título y acción. Se llaman\n   distinto a propósito, aunque Bernardo pidió el nombre `StepHeader`: ese nombre ya estaba tomado\n   por el de KYC (5 pantallas lo importan), y dos componentes distintos con el mismo nombre en el\n   mismo barrel es un error de importación esperando a ocurrir. */\nexport { ScreenHeader, type ScreenHeaderProps } from './primitives/ScreenHeader';\nexport { PrimaryButton, GhostButton } from './primitives/PrimaryButton';\nexport { Tactil, type TactilProps } from './primitives/Tactil';\nexport { DocumentChoiceTree, type DocOptionItem } from './primitives/DocumentChoiceTree';\nexport { KycStatusBanner } from './primitives/KycStatusBanner';\nexport { CameraCapture, type CaptureVariant } from './primitives/CameraCapture';\nexport { LivenessChallengeView, type LivenessMethodT } from './primitives/LivenessChallengeView';\nexport { EstadoDinero, type EstadoDineroProps, type EtapaDinero } from './primitives/EstadoDinero';\nexport {\n  Precio,\n  type PrecioProps,\n  type PrecioTamano,\n  type PrecioForma,\n} from './primitives/Precio';\n\n/* Micro-interacciones. Ver `micro/index.ts` para qué sustituye cada una y cuáles NO se portan. */\nexport * from './micro';\n","/**\n * TOKENS DE COLOR OFICIALES — EG Route Plan (viven en @egrouteplan/ui-kit).\n * Semántica estricta: azul=acción principal · naranja=servicios/proceso ·\n * verde=éxito · rojo=SOLO emergencia. Modo oscuro sin negro puro (#17171A).\n * WCAG AA para sol directo y nocturno.\n */\n\n/**\n * DECISIÓN DEL DUEÑO (17/09/2026) — A1 + B1:\n *   · A1: el azul es la ACCIÓN principal; el naranja CLASIFICA (categoría, sello, servicio).\n *   · B1: estos valores están oscurecidos para que el texto BLANCO encima cumpla AA (4,5:1).\n *     Antes el naranja daba 2,57 y el azul 3,66: las etiquetas de los botones no se leían al sol.\n */\nexport const brand = {\n  primary: '#0066CC',\n  primaryPressed: '#00529E',\n  secondary: '#C2410C',\n  secondaryPressed: '#9A3412',\n  success: '#1E7A45',\n  successPressed: '#176035',\n  danger: '#C62828',\n  dangerPressed: '#A31F1F',\n  /**\n   * AVISO — ámbar. Destino de los 16 ámbares distintos que había repartidos por la app\n   * (`#F59E0B`, `#F6B100`, `#F5B50A`, `#F5B800`, `#F5A623`…). Cuatro de ellos estaban a menos\n   * de 3° de matiz entre sí: indistinguibles en pantalla y aun así cuatro valores.\n   */\n  warning: '#F59E0B',\n  warningPressed: '#D97706',\n  /** Texto sobre `warning`: oscuro, porque el blanco sobre ámbar no llega a AA (2,1:1). */\n  onWarning: '#451A03',\n  /** INFORMACIÓN — azul de aviso, deliberadamente distinto del azul de ACCIÓN (`primary`). */\n  info: '#0EA5E9',\n  infoPressed: '#0284C7',\n  /** Texto sobre `info`: oscuro, por la misma razón que en `warning`. */\n  onInfo: '#082F49',\n  /**\n   * «ME GUSTA» / favorito. NO es un error: el rojo de error es `danger`, reservado a lo crítico.\n   * Antes había tres rojos distintos para el mismo corazón (`#FF2442`, `#FF3B5C`, `#EF4444`).\n   * Uso gráfico (icono): cumple el 3:1 de componentes, no el 4,5:1 de texto.\n   */\n  like: '#FF2442',\n  likePressed: '#E01E39',\n  /** Marca de WhatsApp para el botón de contacto. Uso gráfico, nunca como texto. */\n  whatsapp: '#25D366',\n  /**\n   * NEUTRO — estado sin carga emocional (cancelado, expirado, revertido). Es el gris que sí\n   * cumple AA sobre blanco (4,76:1), a diferencia de `textSecondary`.\n   */\n  neutral: '#64748B',\n  neutralPressed: '#475569',\n  /**\n   * Variantes OSCURAS para texto sobre fondo claro. Faltaban: el código usaba #991B1B y\n   * #78350F a mano justamente porque danger (3,4:1) y warning no llegan a AA como texto.\n   * Con estos tokens, el rojo de un aviso se puede leer y sigue siendo rojo.\n   */\n  dangerText: '#991B1B',\n  warningText: '#78350F',\n  /* ---------------------------------------------------------------------------------------------\n     TEXTO DE MARCA SOBRE FONDO OSCURO.\n     POR QUÉ EXISTEN: los colores de marca de arriba se diseñaron para LLEVAR texto blanco encima, y\n     ahí cumplen (blanco sobre #0066CC = 5,57). Pero usados como TEXTO o icono sobre el fondo oscuro\n     #17171A suspenden el mínimo AA de 4,5:1 — medido el 23/09/2026: primary 3,21 · success 3,34 ·\n     danger 3,18 · secondary 3,45 · neutral 3,76.\n     El kit ya tenía la variante del caso contrario (dangerText y warningText, «para texto sobre fondo\n     claro»); lo que faltaba era ésta. Estos seis cierran el hueco.\n     REGLA: los tokens base NO se tocan — se usan como RELLENO o con texto blanco encima. Estos, SOLO\n     como texto o icono sobre fondo oscuro. Contraste medido sobre #17171A / #1E1E23 / #232329.\n     --------------------------------------------------------------------------------------------- */\n  primaryDark: '#4D9AEB', // 6,08 · 5,31\n  successDark: '#45B87A', // 7,15 · 6,24\n  dangerDark: '#F26D6D', // 6,12 · 5,35\n  secondaryDark: '#F08A4B', // 7,19 · 6,28\n  neutralDark: '#B0B8C4', // 8,94 · 8,30 · 7,81\n  warningDark: '#F5B942', // 10,14 · 8,86\n  /** Blanco de superficie. Destino de las 554 ocurrencias de blanco escrito a mano. */\n  white: '#FFFFFF',\n} as const;\n\nexport interface ThemeColors {\n  primary: string;\n  primaryPressed: string;\n  secondary: string;\n  secondaryPressed: string;\n  success: string;\n  successPressed: string;\n  danger: string;\n  dangerPressed: string;\n  /** Tokens añadidos en la Fase 1 de la auditoría de diseño: existían en el código, no en el kit. */\n  warning: string;\n  warningPressed: string;\n  onWarning: string;\n  info: string;\n  infoPressed: string;\n  onInfo: string;\n  like: string;\n  likePressed: string;\n  whatsapp: string;\n  dangerText: string;\n  warningText: string;\n  neutral: string;\n  neutralPressed: string;\n  /** Solo para usar como TEXTO o icono sobre fondo oscuro. Ver el bloque en `brand`. */\n  primaryDark: string;\n  successDark: string;\n  dangerDark: string;\n  secondaryDark: string;\n  neutralDark: string;\n  warningDark: string;\n  white: string;\n  textPrimary: string;\n  textSecondary: string;\n  background: string;\n  surface: string;\n  card: string;\n  /** 4.º nivel de superficie: la HOJA que se abre SOBRE una tarjeta. Antes no existía y se usaba `card`,\n   *  así que una hoja sobre una tarjeta no se distinguía de lo que tapaba. */\n  sheet: string;\n  border: string;\n  overlay: string;\n  shadow: string;\n}\n\nexport const lightColors: ThemeColors = {\n  ...brand,\n  textPrimary: '#1D2129',\n  /**\n   * 4,76:1 sobre blanco (antes 3,24:1, por debajo del mínimo AA de 4,5 para texto normal).\n   * Auditoría de diseño, D-30: el texto secundario se lee, o no es texto.\n   */\n  textSecondary: '#6B7280',\n  background: '#FFFFFF',\n  surface: '#F5F7FA',\n  card: '#FFFFFF',\n  /** Hoja en claro: mismo blanco que la tarjeta — lo que la separa es la sombra, no el color. */\n  sheet: '#FFFFFF',\n  border: 'rgba(29, 33, 41, 0.08)',\n  overlay: 'rgba(23, 23, 26, 0.45)',\n  shadow: '#17171A',\n};\n\nexport const darkColors: ThemeColors = {\n  ...brand,\n  textPrimary: '#F2F3F5',\n  textSecondary: '#A9AEB8',\n  background: '#17171A',\n  surface: '#1E1E23',\n  card: '#232329',\n  /** 4.º nivel: la hoja se abre SOBRE la tarjeta (#232329) y tiene que distinguirse de ella. */\n  sheet: '#2E3338',\n  border: 'rgba(255, 255, 255, 0.08)',\n  overlay: 'rgba(0, 0, 0, 0.55)',\n  shadow: '#000000',\n};\n\n/**\n * ELEVACIÓN — tres niveles, no doce.\n * Antes había 12 valores de `elevation` y 11 de `shadowOpacity` escritos a mano en 16 archivos:\n * dos tarjetas del mismo nivel se veían distintas y la interfaz perdía el orden.\n * Uso: `style={[styles.card, elevation.md]}` (con `useTheme().isDark` → `elevationDark`).\n */\nexport interface ElevationStyle {\n  shadowColor: string;\n  shadowOffset: { width: number; height: number };\n  shadowOpacity: number;\n  shadowRadius: number;\n  elevation: number;\n}\n\nexport const elevation: Record<'sm' | 'md' | 'lg', ElevationStyle> = {\n  sm: { shadowColor: '#17171A', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.06, shadowRadius: 2, elevation: 1 },\n  md: { shadowColor: '#17171A', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.1, shadowRadius: 6, elevation: 3 },\n  lg: { shadowColor: '#17171A', shadowOffset: { width: 0, height: 6 }, shadowOpacity: 0.16, shadowRadius: 16, elevation: 8 },\n};\n\n/** El mismo sistema en tema oscuro: la sombra es negra y más opaca para leerse sobre el fondo. */\nexport const elevationDark: Record<'sm' | 'md' | 'lg', ElevationStyle> = {\n  sm: { shadowColor: '#000000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.24, shadowRadius: 2, elevation: 1 },\n  md: { shadowColor: '#000000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.32, shadowRadius: 6, elevation: 3 },\n  lg: { shadowColor: '#000000', shadowOffset: { width: 0, height: 6 }, shadowOpacity: 0.44, shadowRadius: 16, elevation: 8 },\n};\n\n/**\n * RAMPA DE NEUTROS.\n *\n * POR QUÉ EXISTE: el kit tenía `textPrimary`, `textSecondary`, `border` y `surface` sueltos y **ninguna\n * rampa**. Faltaba color para tres cosas reales: el borde en modo oscuro, los estados apagados\n * (deshabilitado, cancelado) y los separadores internos de una tarjeta.\n *\n * AVISO, y está medido: **`n600` NO vale como texto secundario sobre fondo claro** — da 3,27 y suspende\n * el 4,5:1 de AA. Para eso se queda `textSecondary` (#6B7280, 4,83). La rampa es para **bordes,\n * separadores y rellenos apagados**, no para texto.\n *\n * Y `n1100` **no es el fondo de la app**: el fondo oscuro es `#17171A` por decisión del dueño\n * («modo oscuro sin negro puro»). La rampa no lo sustituye.\n */\nexport const neutro = {\n  n100: '#FAFAFA',\n  n200: '#F2F2F2',\n  n300: '#E5E5E6',\n  n400: '#D0D1D2',\n  n500: '#B1B2B4',\n  n600: '#898B8F',\n  n700: '#686A6F',\n  n800: '#4F5155',\n  n900: '#3B3C40',\n  n1000: '#2C2D30',\n  n1100: '#18191B',\n} as const;\n\n/** Tintes con alfa (RN no soporta color-mix). */\nexport function alpha(hex: string, opacity: number): string {\n  let h = hex.replace('#', '').trim();\n  // Acepta la forma corta (`#FFFFFF` → `ffffff`): en el código había 387 usos de `#FFFFFF`.\n  if (h.length === 3) h = h.split('').map((c) => c + c).join('');\n  // Un valor inesperado devuelve el color tal cual en vez de `rgba(NaN, …)`, que rompía el estilo.\n  if (h.length !== 6) return hex;\n  const r = parseInt(h.slice(0, 2), 16);\n  const g = parseInt(h.slice(2, 4), 16);\n  const b = parseInt(h.slice(4, 6), 16);\n  return `rgba(${r}, ${g}, ${b}, ${opacity})`;\n}\n","/**\n * ThemeContext (ui-kit) — modo claro/oscuro con override manual.\n * Consumo: const { colors, isDark } = useTheme();\n */\n\nimport React, { createContext, useContext, useMemo, useState, type ReactNode } from 'react';\nimport { useColorScheme } from 'react-native';\nimport { lightColors, darkColors, type ThemeColors } from './colors';\n\nexport type ThemeMode = 'system' | 'light' | 'dark';\n\ninterface ThemeValue {\n  colors: ThemeColors;\n  isDark: boolean;\n  mode: ThemeMode;\n  setMode: (mode: ThemeMode) => void;\n}\n\nconst ThemeContext = createContext<ThemeValue>(null as unknown as ThemeValue);\n\nexport function ThemeProvider({ children }: { children: ReactNode }) {\n  const system = useColorScheme();\n  const [mode, setMode] = useState<ThemeMode>('system');\n\n  const value = useMemo<ThemeValue>(() => {\n    const isDark = mode === 'system' ? system === 'dark' : mode === 'dark';\n    return { colors: isDark ? darkColors : lightColors, isDark, mode, setMode };\n  }, [mode, system]);\n\n  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;\n}\n\nexport function useTheme(): ThemeValue {\n  return useContext(ThemeContext);\n}\n","/**\n * ESCALAS ÚNICAS — auditoría de diseño, Fase 2.\n *\n * POR QUÉ EXISTEN: la app tenía **37 tamaños de letra** distintos en 2.801 usos (con valores\n * fraccionarios como 12.5 y 11.5, señal de ajuste a ojo pantalla por pantalla), **46 espaciados**\n * —solo el 47 % múltiplos de 4— y **42 radios** distintos. Sin escala, ninguna pantalla se parece\n * a otra y cada ajuste se rehace.\n *\n * Cómo se usa:\n *   <Text style={{ fontSize: tipografia.body, fontWeight: peso.fuerte }}>…\n *   <View style={{ padding: espaciado.e16, gap: espaciado.e8, borderRadius: radios.md }}>…\n *\n * Los nombres son de intención, no de tamaño: `body` es el cuerpo, no «14».\n */\n\n/** Tamaños de letra. El cuerpo de la app sube a 14 (antes vivía entre 11 y 13 px). */\nexport const tipografia = {\n  /**\n   * Textos de apoyo, sellos y avisos. **10,5, no 11** (decisión del 24/09/2026, propuesta A).\n   * POR QUÉ: medido sobre 664 literales, `10,5` es el SEGUNDO valor más escrito del proyecto (110\n   * veces) y `10` el quinto (44). La escala decía `micro: 11`, que el código apenas usa. Poner 10,5\n   * alinea los 154 literales de 10 y 10,5 y mueve los usos del token **−0,5 px**, imperceptible.\n   */\n  micro: 10.5,\n  /**\n   * RÓTULO DE CELDA DENSA — el peldaño que existe por un problema de ANCHO, no de jerarquía.\n   *\n   * Lo pidió la rejilla de categorías del Mercado: el nombre de la familia va debajo de su miniatura,\n   * cuatro celdas por fila en 360 dp, así que al rótulo le quedan **80 dp** (medido en un teléfono de\n   * 1080 px a 480 dpi = 3 px por dp exactos). El rótulo mediano de ese árbol mide 14 caracteres y\n   * muchos son de tres palabras, así que el ancho es la restricción de verdad.\n   *\n   * A `micro` (11) caben 8 caracteres por línea y **20 de los 110 rótulos** no entran en dos líneas\n   * (45 en una rejilla de 5 columnas, que es como empezó esto). A 9 —**10,35 dp reales** con el\n   * `font_scale` 1,15 del móvil de referencia— caben 12 por línea y **no se corta ninguno de los 110**.\n   * Por debajo de 8 la letra deja de leerse en pantalla densa, así que este es el suelo de la escala.\n   *\n   * CÓMO SE MIDIÓ, porque el número importa: con **7,9 dp por carácter a `micro`**, que es la\n   * calibración sacada del teléfono —«Supermercados» (13 caracteres) NO cabe en 80 dp y «Servicios\n   * del» (13, letras más estrechas) SÍ—. Un medidor que use 7,2 dp dirá que ambos caben y que no hay\n   * problema: es la diferencia entre medir y suponer. El barrido está en\n   * `_c9-medir-letra-rejilla.cjs`, y en la rejilla la letra solo sirve de algo con **tres líneas**\n   * (`LINEAS_ROTULO` en `app/ecomerse.tsx`): con dos, cinco rótulos seguirían perdiendo texto.\n   */\n  rotulo: 9,\n  /** Etiquetas y notas al pie. */\n  caption: 12,\n  /** Cuerpo de texto: el tamaño por defecto de la app. */\n  body: 14,\n  /**\n   * CUERPO DESTACADO — el peldaño que el código pedía a gritos (decisión del 24/09/2026, propuesta A).\n   * `15` es **el valor más escrito a mano del proyecto entero: 151 literales**, y no estaba en la\n   * escala (que saltaba de 14 a 16). Se declara para que esos 151 sitios tengan casa sin moverse.\n   */\n  cuerpo: 15,\n  /** Subtítulos y cifras destacadas. */\n  subtitle: 16,\n  /**\n   * CABECERA DE SECCIÓN — 83 literales escritos a mano en `17`, y la escala saltaba de 16 a 20.\n   * Igual que `cuerpo`: se declara el valor que el producto ya usa.\n   */\n  subCabecera: 17,\n  /** Título de pantalla. */\n  title: 20,\n  /**\n   * Cifras grandes (saldo, precio). **26, no 28** (decisión del 24/09/2026, propuesta A).\n   * POR QUÉ: el código escribe 26 (18 veces) y 22 (16) mucho más que 28, y la propuesta generada de\n   * escala situaba el peldaño equivalente en ~24-26. Baja 2 px y es el único cambio VISIBLE de la\n   * propuesta A — afecta a cifras hero, que aguantan el ajuste.\n   */\n  display: 26,\n} as const;\n\n/**\n * Pesos. Antes solo había 500–900: **no existía el 400**, así que todo estaba en semibold o más y\n * nada destacaba. `normal` es el nuevo texto base; las cifras y los títulos siguen en `fuerte`.\n */\nexport const peso = {\n  normal: '400',\n  medio: '500',\n  fuerte: '700',\n  /**\n   * MÁXIMO — 800. El peldaño que faltaba, y es el valor **más escrito a mano del proyecto: 727\n   * literales** (auditoría del 23/09/2026). Sin él no se podía migrar: no se migra a una escala donde\n   * el valor más frecuente no existe.\n   * Con este peldaño, **1.759 de los 1.975 literales de `fontWeight` pasan a token sin mover un píxel**\n   * (800→maximo, 900→titulo, 700→fuerte, 500→medio). Los 214 de `600` bajaron a `medio` por decisión\n   * del 24/09/2026: el kit añadió `normal 400` justificándose en que «todo estaba en semibold o más y\n   * nada destacaba», y bajar el 600 crea por fin la franja ligera (500 · 700 · 800 · 900).\n   */\n  maximo: '800',\n  titulo: '900',\n} as const;\n\n/**\n * ESPACIADO — el CONJUNTO DE VALORES EN USO, nombrado y contado.\n *\n * PRIMERA VERSIÓN (24/09/2026, base 2, 11 peldaños) Y SU CORRECCIÓN, porque el error merece quedar\n * escrito: se declaró una base 2 (2/4/6/8/10/12/14/16/20/24/32) y **82,3 % de los literales entraron**.\n * Faltaba ver qué quedaba fuera, y lo que queda fuera de una base 2 son, por definición, **los impares**:\n *\n *   valor   literales   |   valor   literales\n *     3        181      |    9         79\n *     7        168      |   13         57\n *     5        101      |   11         90\n *\n * Sumaban **450 literales** con uso alto y ninguno era capricho: en una rejilla densa de marketplace\n * (celdas de 80 dp a 360 dp) el hueco entre el icono y su rótulo, o el aire dentro de un chip, se\n * resuelve en 3, 5 o 7 — no en 4 ni en 8. Declarar base 2 y dejar 450 usos fuera era repetir el error\n * original con otro número: **declarar una base que el producto no usa.**\n *\n * Con los impares y los dos anchos de contenedor (18 y 22) dentro, la cobertura medida sube:\n *\n *   escala declarada               cubre      fuera\n *   base 4 (la original)           43,9 %     3.686\n *   base 2 (1.ª versión)           82,3 %     1.160\n *   base 2 + impares + 18/22       95,7 %       282   ← la que está aplicada\n *\n * Y de los 282 que siguen fuera: **77 son `1`** (un nudo de alineación, no un hueco) y el resto son\n * anchos de contenedor grandes (26, 28, 30, 40, 48, 60, hasta 130) que **no son «espaciado» sino\n * tamaño de caja** y deben ir a su familia cuando exista.\n *\n * CONCLUSIÓN QUE HAY QUE DECIR EN VOZ ALTA: esto ya **no es una progresión, es el conjunto de los\n * valores en uso, con nombre y contados uno a uno.** Es deliberado. El valor de nombrarlos no es\n * restringir —no restringe—, es que **se pueden contar y cambiar en un sitio**, que es justo lo que la\n * guardia no podía hacer mientras eran literales sueltos.\n *\n * Por qué el nombre es el número: en espaciado el número ES la intención — nadie dice «un hueco\n * semántico de 10». Renombrar aquí sigue siendo lo más barato de las familias. Las claves viejas\n * (`xs`, `sm`, `md`, `lg`, `xl`, `xxl`) apuntaban a 4/8/12/16/24/32 y se sustituyeron por los `eN`.\n */\nexport const espaciado = {\n  e2: 2,\n  /** Nudo corto: entre un icono y su etiqueta dentro de un chip. 181 literales. */\n  e3: 3,\n  e4: 4,\n  /** Separación mínima dentro de una fila densa de la rejilla. 101 literales. */\n  e5: 5,\n  e6: 6,\n  /** El aire del rótulo bajo la miniatura. 168 literales. */\n  e7: 7,\n  e8: 8,\n  e9: 9,\n  e10: 10,\n  e11: 11,\n  e12: 12,\n  e13: 13,\n  e14: 14,\n  e16: 16,\n  /** Ancho de contenedor: margen de una tarjeta ancha. 151 literales. */\n  e18: 18,\n  e20: 20,\n  e22: 22,\n  e24: 24,\n  /**\n   * LOS TRES PELDAÑOS DEL HUECO 24–32 — decisión de Bernardo, 24/09/2026 (opción A).\n   * POR QUÉ: la escala saltaba de 24 a 32 y en ese hueco vivían 26 (12 usos), 28 (19) y 30 (27) =\n   * **58 usos** que se escribían a mano. Los otros 8 sueltos de esa franja (15, 17, 3,5, 2,5) se\n   * revisan uno a uno, que son ocho.\n   * LA ALTERNATIVA ERA UNIFICAR A 28, y se descartó: convertía tres valores en uno y **movía 39\n   * sitios**. Esto no mueve ninguno — es la misma clase de decisión que los impares de `e3/e5/e7`:\n   * nombrar lo que ya se escribe, no corregirlo. Con ellos la escala cubre el 99,8 % de los huecos.\n   */\n  e26: 26,\n  /** Separación entre bloques de una ficha. 19 literales. */\n  e28: 28,\n  /** Aire de un bloque de contenido ancho. 27 literales. */\n  e30: 30,\n  e32: 32,\n} as const;\n\n/**\n * RADIOS — cuatro formas para todo (antes 42 valores distintos).\n *\n * AMPLIACIÓN DEL 24/09/2026: `radios` está BIEN adoptada (702 usos en 168 ficheros, la segunda mejor\n * del kit), así que **los cuatro valores existentes no se han tocado**. Lo que faltaba eran los dos\n * valores que el código más escribe a mano y que la escala no contenía:\n *   · `14` → **168 literales**, el valor más escrito del proyecto.\n *   · `10` → **142 literales**.\n * Más `6` (60 literales entre 4 y 6) y `20` (99 entre 18, 20 y 22). Los nombres siguen la regla del\n * kit —intención, no tamaño— y son `marca`, `chip`, `campo` y `tarjeta`.\n */\nexport const radios = {\n  /** Micro-marca: un punto, un contador de aviso. 6 px. */\n  marca: 6,\n  /** Sellos, chips y etiquetas pequeñas. */\n  sm: 8,\n  /** Chip de filtro. 10 px. */\n  chip: 10,\n  /** Campos de formulario y tarjetas pequeñas. */\n  md: 12,\n  /** Campo, caja o contenedor de contenido. 14 px. */\n  campo: 14,\n  /** Tarjetas y hojas. */\n  lg: 16,\n  /** Tarjeta con foto. 20 px. */\n  tarjeta: 20,\n  /** Píldoras y círculos. */\n  full: 999,\n} as const;\n\nexport type TamanoTexto = keyof typeof tipografia;\nexport type Espaciado = keyof typeof espaciado;\nexport type Radio = keyof typeof radios;\n\n/**\n * GROSORES DE TRAZO — auditoría de micro-interacciones, Fase 0.\n *\n * POR QUÉ EXISTE: la auditoría midió **nueve grosores distintos** escritos a mano entre bordes e\n * iconos: `StyleSheet.hairlineWidth`, 1, 1.5, 2, 3 (como borde) y 1.8, 2, 2.2, 3 (como `strokeWidth`\n * de icono). Un icono con 1.8 junto a otro con 2.2 en la misma fila se nota, aunque no se sepa decir\n * por qué.\n *\n * REGLA: el grosor **no** es decoración, dice jerarquía. Un borde que separa es `fino`; uno que\n * delimita un control es `base`; uno que marca algo elegido es `fuerte`.\n */\nexport const trazo = {\n  /** Separadores y líneas de lista. Antes `StyleSheet.hairlineWidth` o 1 según el fichero. */\n  fino: 1,\n  /** Borde de un control: campo, casilla, celda de código. Antes 1.5 en el kit y 1 en las pantallas. */\n  base: 1.5,\n  /** Borde de algo elegido o marcado. */\n  fuerte: 2,\n  /** Trazo de un elemento activo sobre fondo con contraste (iconos de estado). */\n  marcado: 2.5,\n} as const;\n\n/**\n * GROSORES DE TRAZO DE ICONO (`strokeWidth` de un SVG).\n *\n * POR QUÉ EXISTE: la escala de arriba es la del BORDE, y el kit la declaró a medias. El producto usa\n * además **cuatro grosores como trazo de icono** escritos a mano —`1.8`, `2`, `2.2`, `3`— y no estaban\n * en ningún sitio. Un icono con 1.8 junto a otro con 2.2 en la misma fila se nota, aunque no se sepa\n * decir por qué.\n *\n * La escala del borde NO sirve para esto: 1.5 y 2.5 son valores de borde, no de dibujo de icono. Son\n * dos escalas distintas porque miden cosas distintas, igual que `tipografia` e `icono`.\n */\nexport const trazoIcono = {\n  /** Icono pequeño y denso. */\n  fino: 1.8,\n  /** Icono de fila o de botón: el caso más común. */\n  base: 2,\n  /** Icono de acción principal. */\n  fuerte: 2.2,\n  /** Icono de estado o de acento. */\n  marcado: 3,\n} as const;\n\n/**\n * ALTURAS TÁCTILES.\n *\n * El mínimo de `punto` no es un valor estético: **44 dp** es el mínimo que pide la plataforma\n * (Apple HIG) y 48 el que recomienda Android.\n *\n * ── CENSO REAL DE BLANCOS TÁCTILES PEQUEÑOS (24/09/2026, Fase 2) ────────────────────────────────\n * Aquí había escrito antes que la auditoría había encontrado «la casilla del carrito (21) y el\n * micrófono del buscador (28)». **El micrófono no existía**: era una nota sin comprobar. El censo\n * de verdad, medido sobre los `StyleSheet` del proyecto, es:\n *\n *   · **152 objetos de estilo** con `width` y `height` explícitos por debajo de 44 dp.\n *   · **39 con nombre de control** (el resto son decoración: avatares, puntos, banderas).\n *   · `lifebook` concentra **15** de esos 39; el Mercado, ninguno.\n *\n * Y el censo trae la conclusión que ahora manda: **casi todos viven en una fila con `gap`**, y ahí\n * subir la caja a 44 NO es gratis — el `gap` se mide entre las cajas, así que la separación visible\n * crece sola (de 8 a 24 en el caso medido). Solo el control SUELTO admite el patrón que sí funciona:\n *\n *   `Pressable` a `altura.punto` (44) con el visual centrado dentro → el dedo gana, el diseño no\n *   cambia. Aplicado a la casilla del carrito (`lifebook-carrito.tsx`): 44 de dedo, 21 de ojo.\n *\n * En una fila con `gap` la decisión es del dueño del producto, control a control, mirando la\n * pantalla. Hasta que se decida, la medida honesta es `hitSlop` **por lado**, que lleva el área\n * táctil a 44 sin mover un píxel: mejora sin disfrazar el problema.\n */\nexport const altura = {\n  /** Mínimo tocable. Por debajo de esto, el dedo falla. */\n  punto: 44,\n  /** Celda de código, casilla grande, botón de icono. */\n  control: 46,\n  /** Campo de formulario. Lo usa `FormField.tsx` (caja de una línea). */\n  campo: 50,\n  /** Botón principal. Lo usa `PrimaryButton.tsx`. */\n  boton: 52,\n} as const;\n\n/**\n * TAMAÑOS DE ICONO.\n *\n * La auditoría encontró **18 tamaños entre 9 y 92** sin escala. Estos cinco cubren los usos reales;\n * los grandes de verdad (un corazón de doble toque a 76-92 px) son **decorativos y van aparte**, en\n * el componente que los usa, porque no son «el tamaño de un icono» sino el de un efecto.\n */\nexport const icono = {\n  /** Dentro de texto o junto a una etiqueta pequeña. */\n  micro: 12,\n  /** Icono de fila, chip o botón compacto. */\n  sm: 16,\n  /** Icono de botón estándar y de barra inferior. */\n  md: 20,\n  /** Icono de acción principal o de cabecera. */\n  lg: 24,\n  /** Icono de un estado vacío. */\n  hero: 32,\n} as const;\n\n/**\n * TAMAÑOS DE ILUSTRACIÓN.\n *\n * POR QUÉ EXISTE: un emoji no es texto ni es icono, y al no tener escala propia se escribía suelto.\n * El módulo Mercado tenía **ocho tamaños distintos —18, 22, 30, 34, 36, 38, 40 y 56— para la MISMA\n * pieza**: el emoji de un estado vacío y el sustituto de la foto de un producto. Ninguna de las dos\n * escalas vecinas sirve para medirlo: `tipografia` tiene su techo en `display` (28) y es para\n * CIFRAS —un emoji de 56 no es «letra grande»—, e `icono` llega a 32 y mide trazo SVG, no un glifo\n * que dibuja el sistema operativo.\n *\n * REGLA: el sujeto manda. Si el emoji ES la pantalla (estado vacío, hueco sin foto) va `md`; si va\n * en línea, dentro de una fila o una etiqueta, va `sm`; si sustituye a una foto grande, `lg`.\n *\n * Nota de rumbo: la fase 5 del plan de diseño sustituye el emoji por un set propio. Esta escala\n * sobrevive a ese cambio —lo que mide es el hueco, no el dibujo—, pero los valores se revisarán\n * entonces.\n */\nexport const ilustracion = {\n  /** Emoji en línea, dentro de una fila o una etiqueta. */\n  sm: 20,\n  /** Estado vacío, o hueco de foto de una tarjeta. */\n  md: 36,\n  /** Sustituto de una foto grande (la ficha de un producto). */\n  lg: 56,\n} as const;\n\nexport type Trazo = keyof typeof trazo;\nexport type TrazoIcono = keyof typeof trazoIcono;\nexport type Altura = keyof typeof altura;\nexport type Icono = keyof typeof icono;\nexport type Ilustracion = keyof typeof ilustracion;\n","/**\n * MOVIMIENTO — tokens de animación. Auditoría de micro-interacciones, Fase 0.\n *\n * POR QUÉ EXISTE ESTE FICHERO\n * La guarda de diseño (`pruebas/verifica-diseno.cjs`) vigila tres cosas: hex, `fontSize` y\n * `borderRadius`. **No vigila duraciones, curvas, opacidades, grosores de trazo ni umbrales de gesto.**\n * Y ahí es justo donde estaba el desmadre: antes de este fichero convivían en el código\n * **nueve opacidades distintas para el mismo gesto de pulsar** (0,4 · 0,45 · 0,5 · 0,6 · 0,7 · 0,85 ·\n * 0,9 · 0,92 · 0,98) y la misma curva `Easing.bezier(0.33, 1, 0.68, 1)` **copiada literal** en dos\n * ficheros. Sin tokens, la próxima micro-interacción añade el décimo valor.\n *\n * LAS DOS FAMILIAS DE DURACIÓN — y por qué no hay una sola\n * La guía pide **≤200 ms** para cambios de estado (Rauno Freiberg) y **<300 ms** para\n * micro-interacciones (Emil Kowalski). Pero un efecto que se MIRA —un relleno que entra, un trazo que\n * se dibuja por etapas— necesita más tiempo o no se llega a ver.\n * Un número único obligaría a elegir entre que un interruptor vaya lento o que un relleno no se vea.\n * Por eso hay dos familias, y cada efecto declara a cuál pertenece:\n *\n *   duracion.toque / cambio / salida   →  estado.  Nada por encima de 200 ms.\n *   duracion.escenificado / dibujado   →  escenificado.  300-500 ms, solo para lo que se contempla.\n *\n * Regla práctica: si el usuario tiene que ESPERAR a que acabe para seguir, es de `estado`.\n * Si puede seguir haciendo otra cosa mientras se ve, es de `escenificado`.\n *\n * Los nombres son de intención, no de valor: `cambio` es «algo ha cambiado de estado», no «180».\n * Es el mismo criterio que `escalas.ts:13` («los nombres son de intención, no de tamaño»).\n */\n\nimport { Easing } from 'react-native-reanimated';\n\n/**\n * Duraciones, en milisegundos.\n *\n * `toque` es el acuse inmediato de que el dedo ha entrado: por debajo de 100 ms se percibe como\n * instantáneo, y por encima de 150 ms empieza a parecer que la app va lenta.\n */\nexport const duracion = {\n  /** Acuse de pulsación. El más corto de todos: el dedo tiene que notarlo YA. */\n  toque: 120,\n  /** Un cambio de estado: marcar, desmarcar, elegir, cambiar de pestaña. */\n  cambio: 180,\n  /** Salida: cuando algo se va, puede ir algo más rápido que cuando entra. */\n  salida: 160,\n  /** Entrada de algo efímero (un aviso). Ya existe `Aviso.tsx` a 180 ms: este es ese valor. */\n  entrada: 180,\n  /** Efecto que se contempla: un relleno, una cascada, un asentamiento. 300-500 ms. */\n  escenificado: 320,\n  /** Dibujado por etapas (un trazo que se dibuja, un relleno largo). Es lo más lento que se permite. */\n  dibujado: 420,\n  /** Cadencia de un elemento que late o respira. No es una transición: es un ciclo. */\n  latido: 900,\n} as const;\n\n/**\n * Curvas.\n *\n * `salida` es la del efecto de relleno ya probado en el banco: arranca rápido y frena al final, que es\n * lo que hace que un movimiento parezca que «llega» en vez de que «se corta».\n */\nexport const curva = {\n  /** Arranca rápido y frena. La del efecto de relleno. Para entradas y cambios de estado. */\n  salida: Easing.bezier(0.33, 1, 0.68, 1),\n  /** Arranca lento y acelera. Para salidas: lo que se va, se va. */\n  entrada: Easing.bezier(0.32, 0, 0.67, 0),\n  /** Suave por los dos lados. Para cambios que no deben llamar la atención. */\n  suave: Easing.inOut(Easing.quad),\n  /** Lineal. Solo para bucles (giros, latidos) donde una curva se notaría al repetirse. */\n  lineal: Easing.linear,\n} as const;\n\n/**\n * Opacidades de estado.\n *\n * Antes de esto había **nueve valores distintos** para el mismo gesto de pulsar según el fichero.\n * Estos son los tres registros que la propia casa ya usaba, con nombre:\n *   · `pulsado`       — el de `Tactil.tsx:27` (filas y controles de pantalla).\n *   · `pulsadoBotón`  — el que acompaña al `scale: 0.98` de `PrimaryButton.tsx` (acciones).\n *   · `deshabilitado` — el de `PrimaryButton.tsx:55`.\n */\nexport const opacidad = {\n  /** Fila o control pulsado (`Tactil`). */\n  pulsado: 0.6,\n  /** Acción pulsada, junto al `scale` de 0.98. */\n  pulsadoBoton: 0.9,\n  /** Deshabilitado o cargando. */\n  deshabilitado: 0.45,\n  /** Elemento apagado del todo (una estrella sin puntuar, un punto inactivo). */\n  apagado: 0.22,\n  /** Velo sobre algo que está detrás de un diálogo. */\n  velo: 0.45,\n} as const;\n\n/**\n * Umbrales de gesto, en píxeles o milisegundos.\n *\n * Los valores salen de los gestos que la app YA resuelve bien, no de la nada:\n * `SelectorDeVariante.tsx:229` (deslizar para cerrar) y `lifebook-videos.tsx:973`\n * (mantener pulsado para pausar) son la referencia.\n */\nexport const umbral = {\n  /** Cuánto hay que deslizar para que cuente como deslizamiento y no como toque. */\n  deslizamiento: 70,\n  /** Movimiento mínimo para decidir la intención de un gesto (si es horizontal o vertical). */\n  intencion: 6,\n  /** Cuánto hay que mantener pulsado para que cuente. */\n  mantener: 450,\n  /**\n   * Mantener pulsado en un sitio que además se desplaza (una lista, un vídeo).\n   * Más corto que `mantener` a propósito: si se espera más, el dedo se mueve antes y el gesto no entra.\n   */\n  mantenerEnLista: 280,\n} as const;\n\n/**\n * Muelles, para `withSpring`.\n *\n * La app **no tenía ni una sola animación con física de muelle** (`withSpring` aparecía 0 veces).\n * Todo era `timing`. Estos son los tres comportamientos que hacen falta:\n *   · `asentar`  — llega y se queda. Para una marca que aparece.\n *   · `rebotar`  — pasa de largo y vuelve. Para un latido, un pulso de confirmación.\n *   · `seguir`   — sigue al dedo sin pasarse. Para algo que se arrastra.\n */\nexport const resorte = {\n  /** Llega a su sitio y se queda, con un asentamiento apenas perceptible. */\n  asentar: { damping: 18, stiffness: 220, mass: 0.9 },\n  /** Pasa de largo y vuelve: es lo que hace que un efecto se sien