 *   first argument.\n * @see https://docs.swmansion.com/react-native-reanimated/docs/threading/runOnJS\n */\nexport function runOnJS<Args extends unknown[], ReturnValue>(\n  fun:\n    | ((...args: Args) => ReturnValue)\n    | RemoteFunction<Args, ReturnValue>\n    | WorkletFunction<Args, ReturnValue>\n): (...args: Args) => void {\n  'worklet';\n  type FunDevRemote = Extract<typeof fun, DevRemoteFunction<Args, ReturnValue>>;\n  if (SHOULD_BE_USE_WEB || !_WORKLET) {\n    // if we are already on the JS thread, we just schedule the worklet on the JS queue\n    return (...args) =>\n      queueMicrotask(\n        args.length\n          ? () => (fun as (...args: Args) => ReturnValue)(...args)\n          : (fun as () => ReturnValue)\n      );\n  }\n  if (isWorkletFunction<Args, ReturnValue>(fun)) {\n    // If `fun` is a worklet, we schedule a call of a remote function `runWorkletOnJS`\n    // and pass the worklet as a first argument followed by original arguments.\n\n    return (...args) =>\n      runOnJS(runWorkletOnJS<Args, ReturnValue>)(\n        fun as WorkletFunction<Args, ReturnValue>,\n        ...args\n      );\n  }\n  if ((fun as FunDevRemote).__remoteFunction) {\n    // In development mode the function provided as `fun` throws an error message\n    // such that when someone accidentally calls it directly on the UI runtime, they\n    // see that they should use `runOnJS` instead. To facilitate that we put the\n    // reference to the original remote function in the `__remoteFunction` property.\n    fun = (fun as FunDevRemote).__remoteFunction;\n  }\n\n  const scheduleOnJS =\n    typeof fun === 'function'\n      ? global._scheduleHostFunctionOnJS\n      : global._scheduleRemoteFunctionOnJS;\n\n  return (...args) => {\n    scheduleOnJS(\n      fun as\n        | ((...args: Args) => ReturnValue)\n        | WorkletFunction<Args, ReturnValue>,\n      args.length > 0\n        ? // TODO TYPESCRIPT this cast is terrible but will be fixed\n          (makeShareableCloneOnUIRecursive(args) as unknown as unknown[])\n        : undefined\n    );\n  };\n}\n","'use strict';\nimport type {\n  ImageStyle,\n  TextStyle,\n  TransformsStyle,\n  ViewStyle,\n} from 'react-native';\n\nimport type { EasingFunctionFactory } from './Easing';\nimport type { ReanimatedModuleProxy } from './ReanimatedModule';\nimport type { WorkletsModuleProxy } from './worklets';\n\nexport interface IWorkletsModule extends WorkletsModuleProxy {}\n\nexport interface IReanimatedModule\n  extends Omit<ReanimatedModuleProxy, 'getViewProp'> {\n  getViewProp<TValue>(\n    viewTag: number,\n    propName: string,\n    component: React.Component | undefined,\n    callback?: (result: TValue) => void\n  ): Promise<TValue>;\n}\n\nexport type LayoutAnimationsOptions =\n  | 'originX'\n  | 'originY'\n  | 'width'\n  | 'height'\n  | 'borderRadius'\n  | 'globalOriginX'\n  | 'globalOriginY';\n\ntype CurrentLayoutAnimationsValues = {\n  [K in LayoutAnimationsOptions as `current${Capitalize<string & K>}`]: number;\n};\n\ntype TargetLayoutAnimationsValues = {\n  [K in LayoutAnimationsOptions as `target${Capitalize<string & K>}`]: number;\n};\n\ninterface WindowDimensions {\n  windowWidth: number;\n  windowHeight: number;\n}\n\nexport interface KeyframeProps extends StyleProps {\n  easing?: EasingFunction | EasingFunctionFactory;\n}\n\ntype FirstFrame =\n  | {\n      0: KeyframeProps & { easing?: never };\n      from?: never;\n    }\n  | {\n      0?: never;\n      from: KeyframeProps & { easing?: never };\n    };\n\ntype LastFrame =\n  | { 100?: KeyframeProps; to?: never }\n  | { 100?: never; to: KeyframeProps };\n\nexport type ValidKeyframeProps = FirstFrame &\n  LastFrame &\n  Record<number, KeyframeProps>;\n\nexport type MaybeInvalidKeyframeProps = Record<number, KeyframeProps> & {\n  to?: KeyframeProps;\n  from?: KeyframeProps;\n};\n\nexport type LayoutAnimation = {\n  initialValues: StyleProps;\n  animations: StyleProps;\n  callback?: (finished: boolean) => void;\n};\n\nexport type Animati