oOklab,\n    toRgb: convertOklabToRgb,\n  },\n};\n","'use strict';\n\n/*\n * The vast majority of the code exported by this module is a direct copy of the code from the culori package (see\n * https://culorijs.org/), which deserves full credit for it. In particular, code from the following path has been used:\n * - https://github.com/Evercoder/culori/tree/v4.0.1/src/lrgb\n */\n\n// TODO Remove once we have the option to get a workletized version of the culori package\n//   https://github.com/software-mansion/react-native-reanimated/pull/6782#pullrequestreview-2488830278\n\nimport type { RgbColor } from './Colors';\n\nconst channelFromLrgb = (c = 0) => {\n  'worklet';\n  const abs = Math.abs(c);\n  if (abs > 0.0031308) {\n    return (Math.sign(c) || 1) * (1.055 * Math.pow(abs, 1 / 2.4) - 0.055);\n  }\n  return c * 12.92;\n};\n\nconst convertLrgbToRgb = ({ r, g, b, alpha }: RgbColor): RgbColor => {\n  'worklet';\n  return {\n    r: channelFromLrgb(r),\n    g: channelFromLrgb(g),\n    b: channelFromLrgb(b),\n    alpha,\n  };\n};\n\nconst channelToLrgb = (c = 0) => {\n  'worklet';\n  const abs = Math.abs(c);\n  if (abs <= 0.04045) {\n    return c / 12.92;\n  }\n  return (Math.sign(c) || 1) * Math.pow((abs + 0.055) / 1.055, 2.4);\n};\n\nconst convertRgbToLrgb = ({ r, g, b, alpha }: RgbColor) => {\n  'worklet';\n  return {\n    r: channelToLrgb(r),\n    g: channelToLrgb(g),\n    b: channelToLrgb(b),\n    alpha,\n  };\n};\n\nexport default {\n  convert: {\n    fromRgb: convertRgbToLrgb,\n    toRgb: convertLrgbToRgb,\n  },\n};\n","'use strict';\n\nimport { ReanimatedError } from './errors';\n\n/**\n * Extrapolation type.\n *\n * @param IDENTITY - Returns the provided value as is.\n * @param CLAMP - Clamps the value to the edge of the output range.\n * @param EXTEND - Predicts the values beyond the output range.\n */\nexport enum Extrapolation {\n  IDENTITY = 'identity',\n  CLAMP = 'clamp',\n  EXTEND = 'extend',\n}\n\n/** Represents the possible values for extrapolation as a string. */\ntype ExtrapolationAsString = 'identity' | 'clamp' | 'extend';\n\ninterface InterpolationNarrowedInput {\n  leftEdgeInput: number;\n  rightEdgeInput: number;\n  leftEdgeOutput: number;\n  rightEdgeOutput: number;\n}\n\n/** Allows to specify extrapolation for left and right edge of the interpolation. */\nexport interface ExtrapolationConfig {\n  extrapolateLeft?: Extrapolation | string;\n  extrapolateRight?: Extrapolation | string;\n}\n\ninterface RequiredExtrapolationConfig {\n  extrapolateLeft: Extrapolation;\n  extrapolateRight: Extrapolation;\n}\n\n/** Configuration options for extrapolation. */\nexport type ExtrapolationType =\n  | ExtrapolationConfig\n  | Extrapolation\n  | ExtrapolationAsString\n  | undefined;\n\nfunction getVal(\n  type: Extrapolation,\n  coef: number,\n  val: number,\n  leftEdgeOutput: number,\n  rightEdgeOutput: number,\n  x: number\n): number {\n  'worklet';\n\n  switch (type) {\n    case Extrapolation.IDENTITY:\n      return x;\n    case Extrapolation.CLAMP:\n      if (coef * val < coef * leftEdgeOutput) {\n        return leftEdgeOutput;\n      }\n      return rightEdgeOutput;\n    case Extrapolation.EXTEND:\n    default:\n      return val;\n  }\n}\n\nfunction isExtrapolate(value: string): value is Extrapolation {\n  'worklet';\n\n  return (\n    /* eslint-disable @typescript-eslint/no-unsafe-enum-comparison */\n    value === Extrapolation.EXTEND ||\n    value === Extrapolation.CLAMP ||\n    value === Extrapolation.IDENTITY\n    /* eslint-enable @typescript-eslint/no-unsafe-enum-comparison */\n  );\n}\n\n// validates extrapolations type\n// if type is correct, converts it to ExtrapolationConfig\nfunction validateType(type: ExtrapolationType): RequiredExtrapolationConfig {\n  'worklet';\n  // initialize extrapolationConfig with default extrapolation\n  const extrapolationConfig: RequiredExtrapolationConfig = {\n    extrapolateLeft: Extrapolation.EXTEND,\n    extrapolateRight: Extrapolation.EXTEND,\n  };\n\n  if (!type) {\n    return extrapolationConfig;\n  }\n\n  if (typeof type === 'string') {\n    if (!isExtrapolate(type)) {\n      throw new ReanimatedError(\n        `Unsupported value for \"interpolate\" \\nSupported values: [\"extend\", \"clamp\", \"identity\", Extrapolatation.CLAMP, Extrapolatation.EXTEND, Extrapolatation.IDENTITY]\\n Valid example:\n        interpolate(value, [inputRange], [outputRange], \"clamp\")`\n      );\n    }\n    extrapolationConfig.extrapolateLeft = type;\n    extrapolationConfig.extrapolateRight = type;\n    return extrapolationConfig;\n  }\n\n  // otherwise type is extrapolation config object\n  if (\n    (type.extrapolateLeft && !isExtrapolate(type.extrapolateLeft)) ||\n    (type.extrapolateRight && !isExtrapolate(type.extrapolateRight))\n  ) {\n    throw new ReanimatedError(\n      `Unsupported value for \"interpolate\" \\nSupported values: [\"extend\", \"clamp\", \"identity\", Extrapolatation.CLAMP, Extrapolatation.EXTEND, Extrapolatation.IDENTITY]\\n Valid example:\n      interpolate(value, [inputRange], [outputRange], {\n        extrapolateLeft: Extrapolation.CLAMP,\n        extrapolateRight: Extrapolation.IDENTITY\n      }})`\n    );\n  }\n\n  Object.assign(extrapolationConfig, type);\n  return extrapolationConfig;\n}\n\nfunction internalInterpolate(\n  x: number,\n  narrowedInput: InterpolationNarrowedInput,\n  extrapolationConfig: RequiredExtrapolationConfig\n) {\n  'worklet';\n  const { leftEdgeInput, rightEdgeInput, leftEdgeOutput, rightEdgeOutput } =\n    narrowedInput;\n  if (rightEdgeInput - leftEdgeInput === 0) {\n    return leftEdgeOutput;\n  }\n  const progress = (x - leftEdgeInput) / (rightEdgeInput - leftEdgeInput);\n  const val = leftEdgeOutput + progress * (rightEdgeOutput - leftEdgeOutput);\n  const coef = rightEdgeOutput >= leftEdgeOutput ? 1 : -1;\n\n  if (coef * val < coef * leftEdgeOutput) {\n    return getVal(\n      extrapolationConfig.extrapolateLeft,\n      coef,\n      val,\n      leftEdgeOutput,\n      rightEdgeOutput,\n      x\n    );\n  } else if (coef * val > coef * rightEdgeOutput) {\n    return getVal(\n      extrapolationConfig.extrapolateRight,\n      coef,\n      val,\n      leftEdgeOutput,\n      rightEdgeOutput,\n      x\n    );\n  }\n\n  return val;\n}\n\n/**\n * Lets you map a value from one range to another using linear interpolation.\n *\n * @param value - A number from the `input` range that is going to be mapped to\n *   the `output` range.\n * @param inputRange - An array of numbers specifying the input range of the\n *   interpolation.\n * @param outputRange - An array of numbers specifying the output range of the\n *   interpolation.\n * @param extrapolate - Determines what happens when the `value` goes beyond the\n *   `input` range. Defaults to `Extrapolation.EXTEND` -\n *   {@link ExtrapolationType}.\n * @returns A mapped value within the output range.\n * @see https://docs.swmansion.com/react-native-reanimated/docs/utilities/interpolate\n */\nexport function interpolate(\n  x: number,\n  inputRange: readonly number[],\n  outputRange: readonly number[],\n  type?: ExtrapolationType\n): number {\n  'worklet';\n  if (inputRange.length < 2 || outputRange.length < 2) {\n    throw new ReanimatedError(\n      'Interpolation input and output ranges should contain at least two values.'\n    );\n  }\n\n  const extrapolationConfig = validateType(type);\n  const length = inputRange.length;\n  const narrowedInput: InterpolationNarrowedInput = {\n    leftEdgeInput: inputRange[0],\n    rightEdgeInput: inputRange[1],\n    leftEdgeOutput: outputRange[0],\n    rightEdgeOutput: outputRange[1],\n  };\n  if (length > 2) {\n    if (x > inputRange[length - 1]) {\n      narrowedInput.leftEdgeInput = inputRange[length - 2];\n      narrowedInput.rightEdgeInput = inputRange[length - 1];\n      narrowedInput.leftEdgeOutput = outputRange[length - 2];\n      narrowedInput.rightEdgeOutput = outputRange[length - 1];\n    } else {\n      for (let i = 1; i < length; ++i) {\n        if (x <= inputRange[i]) {\n          narrowedInput.leftEdgeInput = inputRange[i - 1];\n          narrowedInput.rightEdgeInput = inputRange[i];\n          narrowedInput.leftEdgeOutput = outputRange[i - 1];\n          narrowedInput.rightEdgeOutput = outputRange[i];\n          break;\n        }\n      }\n    }\n  }\n\n  return internalInterpolate(x, narrowedInput, extrapolationConfig);\n}\n\n/**\n * Lets you limit a value within a specified range.\n *\n * @param value - A number that will be returned as long as the provided value\n *   is in range between `min` and `max`.\n * @param min - A number which will be returned when provided `value` is lower\n *   than `min`.\n * @param max - A number which will be returned when provided `value` is higher\n *   than `max`.\n * @returns A number between min and max bounds.\n * @see https://docs.swmansion.com/react-native-reanimated/docs/utilities/clamp/\n */\nexport function clamp(value: number, min: number, max: number) {\n  'worklet';\n  return Math.min(Math.max(value, min), max);\n}\n","/* eslint-disable @typescript-eslint/no-namespace */\n'use strict';\n\nimport type { ReactTestInstance } from 'react-test-renderer';\n\nimport type {\n  AnimatedComponentProps,\n  AnimatedProps,\n  IAnimatedComponentInternal,\n  InitialComponentProps,\n} from './createAnimatedComponent/commonTypes';\nimport { ReanimatedError } from './errors';\nimport type { DefaultStyle } from './hook/commonTypes';\nimport { isJest } from './PlatformChecker';\n\ndeclare global {\n  namespace jest {\n    interface Matchers<R> {\n      toHaveAnimatedStyle(\n        style: Record<string, unknown>[] | Record<string, unknown>,\n        config?: {\n          shouldMatchAllProps?: boolean;\n        }\n      ): R;\n      toHaveAnimatedProps(props: Record<string, unknown>): R;\n    }\n  }\n}\n\nconst defaultFramerateConfig = {\n  fps: 60,\n};\n\nconst isEmpty = (obj: object | undefined) =>\n  !obj || Object.keys(obj).length === 0;\nconst getStylesFromObject = (obj: object) => {\n  return obj === undefined\n    ? {}\n    : Object.fromEntries(\n        Object.entries(obj).map(([property, value]) => [\n          property,\n          value._isReanimatedSharedValue ? value.value : value,\n        ])\n      );\n};\n\ntype StyleValue = { value: unknown };\ntype JestInlineStyle =\n  | {\n      [s: string]: StyleValue;\n    }\n  | ArrayLike<StyleValue>;\n\nconst getCurrentProps = (\n  component: TestComponent\n): Partial<AnimatedComponentProps<AnimatedProps>> => {\n  const propsObject = component.props.jestAnimatedProps?.value;\n\n  return propsObject ? { ...propsObject } : {};\n};\n\nconst getCurrentStyle = (component: TestComponent): DefaultStyle => {\n  const styleObject = component.props.style;\n\n  let currentStyle = {};\n\n  if (Array.isArray(styleObject)) {\n    // It is possible that style may contain nested arrays. Currently, neither `StyleSheet.flatten` nor `flattenArray` solve this issue.\n    // Hence, we're not handling nested arrays at the moment - this is a known limitation of the current implementation.\n    styleObject.forEach((style) => {\n      currentStyle = {\n        ...currentStyle,\n        ...style,\n      };\n    });\n  }\n\n  const jestInlineStyles = component.props.jestInlineStyle as JestInlineStyle;\n  const jestAnimatedStyleValue = component.props.jestAnimatedStyle?.value;\n\n  if (Array.isArray(jestInlineStyles)) {\n    for (const obj of jestInlineStyles) {\n      if ('jestAnimatedValues' in obj) {\n        continue;\n      }\n\n      const inlineStyles = getStylesFromObject(obj);\n\n      currentStyle = {\n        ...currentStyle,\n        ...inlineStyles,\n      };\n    }\n\n    currentStyle = {\n      ...currentStyle,\n      ...jestAnimatedStyleValue,\n    };\n\n    return currentStyle;\n  }\n\n  const inlineStyles = getStylesFromObject(jestInlineStyles);\n\n  currentStyle = isEmpty(jestAnimatedStyleValue as object | undefined)\n    ? { ...inlineStyles }\n    : { ...jestAnimatedStyleValue };\n\n  return currentStyle;\n};\n\nconst checkEqual = <Value>(current: Value, expected: Value) => {\n  if (Array.isArray(expected)) {\n    if (!Array.isArray(current) || expected.length !== current.length) {\n      return false;\n    }\n    for (let i = 0; i < current.length; i++) {\n      if (!checkEqual(current[i], expected[i])) {\n        return false;\n      }\n    }\n  } else if (typeof current === 'object' && current) {\n    if (typeof expected !== 'object' || !expected) {\n      return false;\n    }\n    for (const property in expected) {\n      if (!checkEqual(current[property], expected[property])) {\n        return false;\n      }\n    }\n  } else {\n    return current === expected;\n  }\n  return true;\n};\n\nconst findStyleDiff = (\n  current: DefaultStyle | Partial<AnimatedComponentProps<AnimatedProps>>,\n  expected: DefaultStyle | Partial<AnimatedComponentProps<AnimatedProps>>,\n  shouldMatchAllProps?: boolean\n) => {\n  const diffs = [];\n  let isEqual = true;\n  let property: keyof DefaultStyle;\n  for (property in expected) {\n    if (!checkEqual(current[property], expected[property])) {\n      isEqual = false;\n      diffs.push({\n        property,\n        current: current[property],\n        expect: expected[property],\n      });\n    }\n  }\n\n  if (\n    shouldMatchAllProps &&\n    Object.keys(current).length !== Object.keys(expected).length\n  ) {\n    isEqual = false;\n    // eslint-disable-next-line @typescript-eslint/no-shadow\n    let property: keyof DefaultStyle;\n    for (property in current) {\n      if (expected[property] === undefined) {\n        diffs.push({\n          property,\n          current: current[property],\n          expect: expected[property],\n        });\n      }\n    }\n  }\n\n  return { isEqual, diffs };\n};\n\nconst compareAndFormatDifferences = (\n  currentValues: Partial<AnimatedComponentProps<AnimatedProps>> | DefaultStyle,\n  expectedValues: Partial<AnimatedComponentProps<AnimatedProps>> | DefaultStyle,\n  shouldMatchAllProps: boolean = false\n): { message: () => string; pass: boolean } => {\n  const { isEqual, diffs } = findStyleDiff(\n    currentValues,\n    expectedValues,\n    shouldMatchAllProps\n  );\n\n  if (isEqual) {\n    return { message: () => 'ok', pass: true };\n  }\n\n  const currentValuesStr = JSON.stringify(currentValues);\n  const expectedValuesStr = JSON.stringify(expectedValues);\n  const differences = diffs\n    .map(\n      (diff) =>\n        `- '${diff.property}' should be ${JSON.stringify(diff.expect)}, but is ${JSON.stringify(diff.current)}`\n    )\n    .join('\\n');\n\n  return {\n    message: () =>\n      `Expected: ${expectedValuesStr}\\nReceived: ${currentValuesStr}\\n\\nDifferences:\\n${differences}`,\n    pass: false,\n  };\n};\n\nconst compareProps = (\n  component: TestComponent,\n  expectedProps: Partial<AnimatedComponentProps<AnimatedProps>>\n) => {\n  if (\n    component.props.jestAnimatedProps &&\n    Object.keys(component.props.jestAnimatedProps.value).length === 0\n  ) {\n    return { message: () => `Component doesn't have props.`, pass: false };\n  }\n\n  const currentProps = getCurrentProps(component);\n\n  return compareAndFormatDifferences(currentProps, expectedProps);\n};\n\nconst compareStyle = (\n  component: TestComponent,\n  expectedStyle: DefaultStyle,\n  config: ToHaveAnimatedStyleConfig\n) => {\n  if (!component.props.style) {\n    return { message: () => `Component doesn't have a style.`, pass: false };\n  }\n  const { shouldMatchAllProps } = config;\n  const currentStyle = getCurrentStyle(component);\n\n  return compareAndFormatDifferences(\n    currentStyle,\n    expectedStyle,\n    shouldMatchAllProps\n  );\n};\n\nlet frameTime = Math.round(1000 / defaultFramerateConfig.fps);\n\nconst beforeTest = () => {\n  jest.useFakeTimers();\n};\n\nconst afterTest = () => {\n  jest.runOnlyPendingTimers();\n  jest.useRealTimers();\n};\n\nexport const withReanimatedTimer = (animationTest: () => void) => {\n  console.warn(\n    'This method is deprecated, you should define your own before and after test hooks to enable jest.useFakeTimers(). Check out the documentation for details on testing'\n  );\n  beforeTest();\n  animationTest();\n  afterTest();\n};\n\nexport const advanceAnimationByTime = (time = frameTime) => {\n  console.warn(\n    'This method is deprecated, use jest.advanceTimersByTime directly'\n  );\n  jest.advanceTimersByTime(time);\n  jest.runOnlyPendingTimers();\n};\n\nexport const advanceAnimationByFrame = (count: number) => {\n  console.warn(\n    'This method is deprecated, use jest.advanceTimersByTime directly'\n  );\n  jest.advanceTimersByTime(count * frameTime);\n  jest.runOnlyPendingTimers();\n};\n\nconst requireFunction = isJest()\n  ? require\n  : () => {\n      throw new ReanimatedError(\n        '`setUpTests` is available only in Jest environment.'\n      );\n    };\n\ntype ToHaveAnimatedStyleConfig = {\n  shouldMatchAllProps?: boolean;\n};\n\nexport const setUpTests = (userFramerateConfig = {}) => {\n  let expect: jest.Expect = (global as typeof global & { expect: jest.Expect })\n    .expect;\n  if (expect === undefined) {\n    const expectModule = requireFunction('expect');\n    expect = expectModule;\n    // Starting from Jest 28, \"expect\" package uses named exports instead of default export.\n    // So, requiring \"expect\" package doesn't give direct access to \"expect\" function anymore.\n    // It gives access to the module object instead.\n    // We use this info to detect if the project uses Jest 28 or higher.\n    if (typeof expect === 'object') {\n      const jestGlobals = requireFunction('@jest/globals');\n      expect = jestGlobals.expect;\n    }\n    if (expect === undefined || expect.extend === undefined) {\n      expect = expectModule.default;\n    }\n  }\n\n  const framerateConfig = {\n    ...defaultFramerateConfig,\n    ...userFramerateConfig,\n  };\n  frameTime = Math.round(1000 / framerateConfig.fps);\n\n  expect.extend({\n    toHaveAnimatedProps(\n      component: React.Compon