creenTransitionConfig: ScreenTransitionConfig,\n  lockAxis?: LockAxis\n) {\n  'worklet';\n  const screenDimensions = screenTransitionConfig.screenDimensions;\n  const startTimestamp = _getAnimationTimestamp();\n  const { isTransitionCanceled } = screenTransitionConfig;\n  const startingPosition = {\n    x: event.translationX,\n    y: event.translationY,\n  };\n  const direction = {\n    x: Math.sign(event.translationX),\n    y: Math.sign(event.translationY),\n  };\n  const finalPosition = isTransitionCanceled\n    ? { x: 0, y: 0 }\n    : {\n        x: direction.x * screenDimensions.width,\n        y: direction.y * screenDimensions.height,\n      };\n  const distance = {\n    x: Math.abs(finalPosition.x - startingPosition.x),\n    y: Math.abs(finalPosition.y - startingPosition.y),\n  };\n  const didScreenReachDestination = {\n    x: false,\n    y: false,\n  };\n  const velocity = { x: BASE_VELOCITY, y: BASE_VELOCITY };\n  if (lockAxis === 'x') {\n    velocity.y = 0;\n    velocity.x +=\n      (ADDITIONAL_VELOCITY_FACTOR_X * distance.x) / screenDimensions.width;\n  } else if (lockAxis === 'y') {\n    velocity.x = 0;\n    velocity.y +=\n      (ADDITIONAL_VELOCITY_FACTOR_Y * distance.y) / screenDimensions.height;\n  } else {\n    const euclideanDistance = Math.sqrt(distance.x ** 2 + distance.y ** 2);\n    const screenDiagonal = Math.sqrt(\n      screenDimensions.width ** 2 + screenDimensions.height ** 2\n    );\n    const velocityVectorLength =\n      BASE_VELOCITY +\n      (ADDITIONAL_VELOCITY_FACTOR_XY * euclideanDistance) / screenDiagonal;\n    if (Math.abs(startingPosition.x) > Math.abs(startingPosition.y)) {\n      velocity.x = velocityVectorLength;\n      velocity.y =\n        velocityVectorLength *\n        Math.abs(startingPosition.y / startingPosition.x);\n    } else {\n      velocity.x =\n        velocityVectorLength *\n        Math.abs(startingPosition.x / startingPosition.y);\n      velocity.y = velocityVectorLength;\n    }\n  }\n\n  if (isTransitionCanceled) {\n    function didScreenReachDestinationCheck() {\n      if (lockAxis === 'x') {\n        return didScreenReachDestination.x;\n      } else if (lockAxis === 'y') {\n        return didScreenReachDestination.y;\n      } else {\n        return didScreenReachDestination.x && didScreenReachDestination.y;\n      }\n    }\n\n    function restoreOriginalStyleForBelowTopScreen() {\n      event.translationX = direction.x * screenDimensions.width;\n      event.translationY = direction.y * screenDimensions.height;\n      applyStyleForBelowTopScreen(screenTransitionConfig, event);\n    }\n\n    const computeFrame = () => {\n      const progress = {\n        x: computeEasingProgress(startTimestamp, distance.x, velocity.x),\n        y: computeEasingProgress(startTimestamp, distance.y, velocity.y),\n      };\n      event.translationX =\n        startingPosition.x - direction.x * distance.x * easing(progress.x);\n      event.translationY =\n        startingPosition.y - direction.y * distance.y * easing(progress.y);\n      if (direction.x > 0) {\n        if (event.translationX <= 0) {\n          didScreenReachDestination.x = true;\n          event.translationX = 0;\n        }\n      } else {\n        if (event.translationX >= 0) {\n          didScreenReachDestination.x = true;\n          event.translationX = 0;\n        }\n      }\n      if (direction.y > 0) {\n        if (event.translationY <= 0) {\n          didScreenReachDestination.y = true;\n          event.translationY = 0;\n        }\n      } else {\n        if (event.translationY >= 0) {\n          didScreenReachDestination.y = true;\n          event.translationY = 0;\n        }\n      }\n      applyStyle(screenTransitionConfig, event);\n      const finished = didScreenReachDestinationCheck();\n      if (finished) {\n        restoreOriginalStyleForBelowTopScreen();\n      }\n      maybeScheduleNextFrame(\n        computeFrame,\n        finished,\n        screenTransitionConfig,\n        event,\n        isTransitionCanceled\n      );\n    };\n    return computeFrame;\n  } else {\n    const computeFrame = () => {\n      const progress = {\n        x: computeEasingProgress(startTimestamp, distance.x, velocity.x),\n        y: computeEasingProgress(startTimestamp, distance.y, velocity.y),\n      };\n      event.translationX =\n        startingPosition.x + direction.x * distance.x * easing(progress.x);\n      event.translationY =\n        startingPosition.y + direction.y * distance.y * easing(progress.y);\n      if (direction.x > 0) {\n        if (event.translationX >= screenDimensions.width) {\n          didScreenReachDestination.x = true;\n          event.translationX = screenDimensions.width;\n        }\n      } else {\n        if (event.translationX <= -screenDimensions.width) {\n          didScreenReachDestination.x = true;\n          event.translationX = -screenDimensions.width;\n        }\n      }\n      if (direction.y > 0) {\n        if (event.translationY >= screenDimensions.height) {\n          didScreenReachDestination.y = true;\n          event.translationY = screenDimensions.height;\n        }\n      } else {\n        if (event.translationY <= -screenDimensions.height) {\n          didScreenReachDestination.y = true;\n          event.translationY = -screenDimensions.height;\n        }\n      }\n      applyStyle(screenTransitionConfig, event);\n      maybeScheduleNextFrame(\n        computeFrame,\n        didScreenReachDestination.x || didScreenReachDestination.y,\n        screenTransitionConfig,\n        event,\n        isTransitionCanceled\n      );\n    };\n    return computeFrame;\n  }\n}\n","'use strict';\nimport { logger } from '../logger';\nimport type { RNScreensTurboModuleType } from './commonTypes';\n\nfunction noopFactory<T>(defaultReturnValue?: T): () => T {\n  return () => {\n    'worklet';\n    logger.warn(\n      'RNScreensTurboModule has not been found. Check that you have installed `react-native-screens@3.30.0` or newer in your project and rebuilt your app.'\n    );\n    return defaultReturnValue as T;\n  };\n}\n\ntype TransactionConfig = {\n  topScreenId: number;\n  belowTopScreenId: number;\n  canStartTransition: boolean;\n};\n\nexport const RNScreensTurboModule: RNScreensTurboModuleType =\n  global.RNScreensTurboModule || {\n    startTransition: noopFactory<TransactionConfig>({\n      topScreenId: -1,\n      belowTopScreenId: -1,\n      canStartTransition: false,\n    }),\n    updateTransition: noopFactory(),\n    finishTransition: noopFactory(),\n  };\n","'use strict';\n\nimport type { AnimatedScreenTransition } from './commonTypes';\n\nconst SwipeRight: AnimatedScreenTransition = {\n  topScreenStyle: (event) => {\n    'worklet';\n    return {\n      transform: [{ translateX: event.translationX }],\n    };\n  },\n  belowTopScreenStyle: (event, screenSize) => {\n    'worklet';\n    return {\n      transform: [\n        { translateX: (event.translationX - screenSize.width) * 0.3 },\n      ],\n    };\n  },\n};\n\nconst SwipeLeft: AnimatedScreenTransition = {\n  topScreenStyle: (event) => {\n    'worklet';\n    return {\n      transform: [{ translateX: event.translationX }],\n    };\n  },\n  belowTopScreenStyle: (event, screenSize) => {\n    'worklet';\n    return {\n      transform: [\n        { translateX: (event.translationX + screenSize.width) * 0.3 },\n      ],\n    };\n  },\n};\n\nconst SwipeDown: AnimatedScreenTransition = {\n  topScreenStyle: (event) => {\n    'worklet';\n    return {\n      transform: [{ translateY: event.translationY }],\n    };\n  },\n  belowTopScreenStyle: (event, screenSize) => {\n    'worklet';\n    return {\n      transform: [\n        { translateY: (event.translationY - screenSize.height) * 0.3 },\n      ],\n    };\n  },\n};\n\nconst SwipeUp: AnimatedScreenTransition = {\n  topScreenStyle: (event) => {\n    'worklet';\n    return {\n      transform: [{ translateY: event.translationY }],\n    };\n  },\n  belowTopScreenStyle: (event, screenSize) => {\n    'worklet';\n    return {\n      transform: [\n        { translateY: (event.translationY + screenSize.height) * 0.3 },\n      ],\n    };\n  },\n};\n\nconst TwoDimensional: AnimatedScreenTransition = {\n  topScreenStyle: (event, _screenSize) => {\n    'worklet';\n    return {\n      transform: [\n        { translateX: event.translationX },\n        { translateY: event.translationY },\n      ],\n    };\n  },\n  belowTopScreenStyle: (_event, _screenSize) => {\n    'worklet';\n    return {};\n  },\n};\n\nconst Horizontal: AnimatedScreenTransition = {\n  topScreenStyle: (event, _screenSize) => {\n    'worklet';\n    return {\n      transform: [{ translateX: event.translationX }],\n    };\n  },\n  belowTopScreenStyle: (_event, _screenSize) => {\n    'worklet';\n    return {};\n  },\n};\n\nconst Vertical: AnimatedScreenTransition = {\n  topScreenStyle: (event, _screenSize) => {\n    'worklet';\n    return {\n      transform: [{ translateY: event.translationY }],\n    };\n  },\n  belowTopScreenStyle: (_event, _screenSize) => {\n    'worklet';\n    return {};\n  },\n};\n\nconst SwipeRightFade: AnimatedScreenTransition = {\n  topScreenStyle: (event, screenSize) => {\n    'worklet';\n    return {\n      opacity: 1 - Math.abs(event.translationX / screenSize.width),\n    };\n  },\n  belowTopScreenStyle: (_event, _screenSize) => {\n    'worklet';\n    return {};\n  },\n};\n\nexport const ScreenTransition = {\n  SwipeRight,\n  SwipeLeft,\n  SwipeDown,\n  SwipeUp,\n  Horizontal,\n  Vertical,\n  TwoDimensional,\n  SwipeRightFade,\n};\n","/**\n * MOVIMIENTO REDUCIDO — la preferencia del sistema que la app ignoraba.\n *\n * POR QUÉ EXISTE\n * La auditoría de diseño (D-15, informe del 17/09/2026) lo dejó escrito: **0 referencias a\n * `isReduceMotionEnabled`, `prefers-reduced-motion` o `AccessibilityInfo`** en toda la app. Y la\n * auditoría de micro-interacciones lo confirmó fichero a fichero. O sea: quien tiene sensibilidad al\n * movimiento —o simplemente ha activado la opción en su teléfono— **no puede desactivar nada**.\n * Eso incumple WCAG 2.3.3 y, con la app llena de rebotes a partir de ahora, era el bloqueante número\n * uno antes de escribir un solo efecto.\n *\n * CÓMO SE USA\n *   const movReducido = useMovimientoReducido();\n *   … if (movReducido) { /* estado final, sin animar *\\/ }\n *\n * LA REGLA QUE GOBIERNA ESTO (y que no es «quitar todo»)\n * Con movimiento reducido **solo se apaga lo puramente decorativo**. Todo lo demás **degrada a su\n * estado final**, no desaparece: el color cambia, el texto cambia, `accessibilityState` cambia. El\n * motivo es que hoy no hay ningún canal alternativo que comunique el cambio: los anuncios activos son\n * dos en todo el repositorio. Quitar el rebote de una casilla está bien; dejar la casilla sin marcar\n * visualmente sería peor que el problema que se arregla.\n *\n * Se lee UNA vez por componente y no una vez por app a propósito: la preferencia puede cambiar con la\n * app abierta (el usuario la activa desde los ajustes del sistema), y hay que reaccionar sin reiniciar.\n */\nimport { useEffect, useState } from 'react';\nimport { AccessibilityInfo, Platform } from 'react-native';\n\nexport function useMovimientoReducido(): boolean {\n  /* Se empieza en `false` (animar) y se corrige en cuanto se sabe. El motivo de no empezar en `true`\n     es que la consulta es asíncrona: arrancar en `true` haría que TODO apareciera de golpe en el\n     primer fotograma, también para quien no ha pedido movimiento reducido. */\n  const [reducido, setReducido] = useState(false);\n\n  useEffect(() => {\n    // En web `AccessibilityInfo` puede no traer estos métodos: se comprueba antes de usarlos.\n    const leer = () => {\n      try {\n        const p = AccessibilityInfo.isReduceMotionEnabled?.();\n        // Devuelve promesa en las versiones recientes y booleano en las antiguas.\n        if (typeof p === 'boolean') setReducido(p);\n        else void p?.then((v) => setReducido(!!v)).catch(() => {});\n      } catch {\n        /* si no se puede leer, se anima: es el comportamiento por defecto de siempre */\n      }\n    };\n    leer();\n\n    /* Suscripción al cambio en caliente. En web no existe: se degrada a no escuchar. */\n    let suscripcion: { remove?: () => void } | undefined;\n    try {\n      if (Platform.OS !== 'web') {\n        suscripcion = AccessibilityInfo.addEventListener?.('reduceMotionChanged', (v) => setReducido(!!v));\n      }\n    } catch {\n      /* sin suscripción: se queda con el valor leído al montar */\n    }\n\n    return () => {\n      try {\n        suscripcion?.remove?.();\n      } catch {\n        /* nada que limpiar */\n      }\n    };\n  }, []);\n\n  return reducido;\n}\n","/**\n * MONEDA — el formateo del franco CFA, en un solo sitio.\n *\n * POR QUÉ EXISTE: `formatXAF` vivía en `app/utils/formatHelpers.ts` y devolvía\n * `${n.toLocaleString('es-GQ')} XAF`, con **un espacio normal entre la cifra y la unidad**. Un\n * espacio normal es un punto de corte válido para el motor de texto, así que en cuanto la caja se\n * quedaba estrecha el precio se partía en dos líneas: «6.500» arriba y «XAF» debajo. Se vio en el\n * carrusel de recomendados del Mercado, donde la tarjeta mide 92 dp de ancho.\n *\n * El defecto no era de esa tarjeta: era del formateo, y por eso se copiaba a cada sitio que\n * pintaba un precio con poco ancho. Aquí se arregla donde nace.\n *\n * DOS DECISIONES:\n *\n * 1. **Espacio duro (U+00A0) en vez de espacio normal.** La cifra y la unidad son una sola cosa:\n *    «6.500 XAF» no es «6.500» y «XAF», es un importe. Con espacio duro, ningún contenedor puede\n *    separarlas, ni siquiera el texto corrido de un pedido.\n *\n * 2. **El separador de miles se calcula, no se pide al sistema.** `toLocaleString('es-GQ')` depende\n *    del ICU que traiga el motor de JavaScript del dispositivo; en un móvil sin ese juego de datos\n *    el resultado cambia de «6.500» a «6,500» sin avisar. Como XAF no tiene céntimos en la práctica\n *    (la unidad mínima es 1 franco), el formato es siempre el mismo: entero, punto cada tres cifras.\n *    Escribirlo así quita una dependencia del entorno a cambio de nada.\n *\n * Uso:\n *   formateaXAF(250000)   → '250.000\\u00A0XAF'   (una sola pieza, incapaz de partirse)\n *   formateaXAF(null)     → '—\\u00A0XAF'\n *   partesXAF(250000)     → { numero: '250.000', unidad: 'XAF' }\n *\n * `partesXAF` existe para quien necesite pintar la unidad en cuerpo menor —el patrón habitual del\n * comercio, y lo que hace `primitives/Precio.tsx`—, en vez de componer a mano sobre la cadena ya\n * formateada.\n */\n\n/**\n * Espacio duro: impide el salto de línea y no se colapsa. Se exporta porque los textos de producto\n * que juntan una cifra y una palabra («6.500 XAF / unidad») necesitan el mismo pegamento.\n */\nexport const ESPACIO_DURO = '\\u00A0';\n\n/** Código ISO de la moneda local. La app lo usa en toda la interfaz; cambiarlo es una decisión de producto. */\nexport const MONEDA_XAF = 'XAF';\n\n/** Texto que se muestra cuando no hay importe. */\nexport const SIN_IMPORTE = '—' + ESPACIO_DURO + MONEDA_XAF;\n\nexport interface PartesMoneda {\n  /** Cifra ya formateada con separador de miles, sin unidad y sin espacios. */\n  numero: string;\n  /** Unidad, sin espacio delante. */\n  unidad: string;\n}\n\n/**\n * Convierte un importe en sus dos partes. Devuelve `null` si no hay un número utilizable, para que\n * quien pinte decida qué enseñar en su lugar.\n */\nexport function partesXAF(valor: number | string | null | undefined): PartesMoneda | null {\n  const n = typeof valor === 'string' ? Number(valor) : Number(valor);\n  if (valor == null || !Number.isFinite(n)) return null;\n  const redondeado = Math.round(n);\n  const signo = redondeado < 0 ? '-' : '';\n  const digitos = String(Math.abs(redondeado)).replace(/\\B(?=(\\d{3})+(?!\\d))/g, '.');\n  return { numero: signo + digitos, unidad: MONEDA_XAF };\n}\n\n/** Importe completo, en una sola pieza indivisible. */\nexport function formateaXAF(valor: number | string | null | undefined): string {\n  const p = partesXAF(valor);\n  if (!p) return SIN_IMPORTE;\n  return p.numero + ESPACIO_DURO + p.unidad;\n}\n","/**\n * useScreenGuard — prevención global de capturas de pantalla.\n *\n * Estándar de seguridad del Design System: cualquier pantalla/primitivo que\n * maneje secretos (PIN, OTP, documentos KYC, saldos) lo activa. Usa\n * `expo-screen-capture` con clave de pila ('egrp-guard'), de modo que varios\n * consumidores puedan anidarse sin pisarse.\n *\n *   · Android: FLAG_SECURE (bloquea capturas y grabación + miniatura en recents).\n *   · iOS:     oculta el contenido en grabación de pantalla; la prevención de\n *              captura estática no existe en iOS — la app debe evitar mostrar\n *              secretos en campos estáticos (regla ya aplicada en el kit).\n */\n\nimport { useEffect } from 'react';\nimport * as ScreenCapture from 'expo-screen-capture';\n\nconst GUARD_KEY = 'egrp-guard';\n\nexport function useScreenGuard(active = true): void {\n  useEffect(() => {\n    if (!active) return;\n    let mounted = true;\n\n    ScreenCapture.preventScreenCaptureAsync(GUARD_KEY).catch(() => {\n      // Módulo no disponible (web/dev): degradación silenciosa, la pantalla sigue funcionando.\n    });\n\n    return () => {\n      if (mounted) {\n        ScreenCapture.allowScreenCaptureAsync(GUARD_KEY).catch(() => {});\n      }\n      mounted = false;\n    };\n  }, [active]);\n}\n","import { UnavailabilityError, PermissionStatus, createPermissionHook, } from 'expo-modules-core';\nimport { useEffect } from 'react';\nimport ExpoScreenCapture from './ExpoScreenCapture';\nconst activeTags = new Set();\nconst onScreenshotEventName = 'onScreenshot';\n// @needsAudit\n/**\n * Returns whether the Screen Capture API is available on the current device.\n *\n * @returns A promise that resolves to a `boolean` indicating whether the Screen Capture API is available on the current\n * device.\n */\nexport async function isAvailableAsync() {\n    return !!ExpoScreenCapture.preventScreenCapture && !!ExpoScreenCapture.allowScreenCapture;\n}\n// @needsAudit\n/**\n * Prevents screenshots and screen recordings until `allowScreenCaptureAsync` is called or the app is restarted. If you are\n * already preventing screen capture, this method does nothing (unless you pass a new and unique `key`).\n *\n * > On iOS, this prevents screen recordings and screenshots, and is only available on iOS 11+ (recordings) and iOS 13+ (screenshots). On older\n * iOS versions, this method does nothing.\n *\n * @param key Optional. If provided, this will help prevent multiple instances of the `preventScreenCaptureAsync`\n * and `allowScreenCaptureAsync` methods (and `usePreventScreenCapture` hook) from conflicting with each other.\n * When using multiple keys, you'll have to re-allow each one in order to re-enable screen capturing.\n *\n * @platform android\n * @platform ios\n */\nexport async function preventScreenCaptureAsync(key = 'default') {\n    if (!ExpoScreenCapture.preventScreenCapture) {\n        throw new UnavailabilityError('ScreenCapture', 'preventScreenCaptureAsync');\n    }\n    if (!activeTags.has(key)) {\n        activeTags.add(key);\n        await ExpoScreenCapture.preventScreenCapture();\n    }\n}\n// @needsAudit\n/**\n * Re-allows the user to screen record or screenshot your app. If you haven't called\n * `preventScreenCapture()` yet, this method does nothing.\n *\n * @param key This will prevent multiple instances of the `preventScreenCaptureAsync` and\n * `allowScreenCaptureAsync` methods from conflicting with each other. If provided, the value must\n * be the same as the key passed to `preventScreenCaptureAsync` in order to re-enable screen\n * capturing.\n */\nexport async function allowScreenCaptureAsync(key = 'default') {\n    if (!ExpoScreenCapture.preventScreenCapture) {\n        throw new UnavailabilityError('ScreenCapture', 'allowScreenCaptureAsync');\n    }\n    activeTags.delete(key);\n    if (activeTags.size === 0) {\n        await ExpoScreenCapture.allowScreenCapture();\n    }\n}\n// @needsAudit\n/**\n * A React hook to prevent screen capturing for as long as the owner component is mounted.\n *\n * @param key If provided, this will prevent multiple instances of this hook or the\n * `preventScreenCaptureAsync` and `allowScreenCaptureAsync` methods from conflicting with each other.\n * This argument is useful if you have multiple active components using the `allowScreenCaptureAsync`\n * hook.\n */\nexport function usePreventScreenCapture(key = 'default') {\n    useEffect(() => {\n        preventScreenCaptureAsync(key);\n        return () => {\n            allowScreenCaptureAsync(key);\n        };\n    }, [key]);\n}\n// @needsAudit\n/**\n * Enables a privacy protection blur overlay that hides sensitive content when the app is not in focus.\n * The overlay applies a customizable blur effect when the app is in the app switcher, background, or during interruptions\n * (calls, Siri, Control Center, etc.), and automatically removes it when the app becomes active again.\n *\n * This provides visual privacy protection by preventing sensitive app content from being visible in:\n * - App switcher previews\n * - Background app snapshots\n * - Screenshots taken during inactive states\n *\n * For Android, app switcher protection is automatically provided by `preventScreenCaptureAsync()`\n * using the FLAG_SECURE window flag, which shows a blank screen in the recent apps preview.\n *\n * @param blurIntensity The intensity of the blur effect, from 0.0 (no blur) to 1.0 (maximum blur). Default is 0.5.\n *\n * @platform ios\n *\n */\nexport async function enableAppSwitcherProtectionAsync(blurIntensity = 0.5) {\n    if (!ExpoScreenCapture.enableAppSwitcherProtection) {\n        throw new UnavailabilityError('ScreenCapture', 'enableAppSwitcherProtectionAsync');\n    }\n    await ExpoScreenCapture.enableAppSwitcherProtection(blurIntensity);\n}\n// @needsAudit\n/**\n * Disables the privacy protection overlay that was previously enabled with `enableAppSwitcherProtectionAsync`.\n *\n * @platform ios\n */\nexport async function disableAppSwitcherProtectionAsync() {\n    if (!ExpoScreenCapture.disableAppSwitcherProtection) {\n        throw new UnavailabilityError('ScreenCapture', 'disableAppSwitcherProtectionAsync');\n    }\n    await ExpoScreenCapture.disableAppSwitcherProtection();\n}\n// @needsAudit\n/**\n * Adds a listener that will fire whenever the user takes a screenshot while the app is foregrounded.\n * On Android, this method requires the `READ_EXTERNAL_STORAGE` permission. You can request this\n * with [`MediaLibrary.requestPermissionsAsync()`](./media-library/#medialibraryrequestpermissionsasync).\n *\n * @param listener The function that will be executed when the user takes a screenshot.\n * This function accepts no arguments.\n *\n * @return A `Subscription` object that you can use to unregister the listener, either by calling\n * `remove()` or passing it to `removeScreenshotListener`.\n */\nexport function addScreenshotListener(listener) {\n    return ExpoScreenCapture.addListener(onScreenshotEventName, listener);\n}\n// @needsAudit\n/**\n * Removes the subscription you provide, so that you are no longer listening for screenshots.\n * You can also call `remove()` on that `Subscription` object.\n *\n * @param subscription Subscription returned by `addScreenshotListener`.\n *\n * @example\n * ```ts\n * let mySubscription = addScreenshotListener(() => {\n *   console.log(\"You took a screenshot!\");\n * });\n * ...\n * mySubscription.remove();\n * // OR\n * removeScreenshotListener(mySubscription);\n * ```\n */\nexport function removeScreenshotListener(subscription) {\n    subscription.remove();\n}\n/**\n * Checks user's permissions for detecting when a screenshot is taken.\n * > Only Android requires additional permissions to detect screenshots. On iOS devices, this method will always resolve to a `granted` permission response.\n * @return A promise that resolves to a [`PermissionResponse`](#permissionresponse) object.\n */\nexport async function getPermissionsAsync() {\n    if (ExpoScreenCapture.getPermissionsAsync) {\n        return ExpoScreenCapture.getPermissionsAsync();\n    }\n    return defaultPermissionsResponse;\n}\n/**\n * Asks the user to grant permissions necessary for detecting when a screenshot is taken.\n * > Only Android requires additional permissions to detect screenshots. On iOS devices, this method will always resolve to a `granted` permission response.\n * @return A promise that resolves to a [`PermissionResponse`](#permissionresponse) object.\n * */\nexport async function requestPermissionsAsync() {\n    if (ExpoScreenCapture.requestPermissionsAsync) {\n        return ExpoScreenCapture.requestPermissionsAsync();\n    }\n    return defaultPermissionsResponse;\n}\n/**\n * Check or request permissions necessary for detecting when a screenshot is taken.\n * This uses both [`requestPermissionsAsync`](#screencapturerequestpermissionsasync) and [`getPermissionsAsync`](#screencapturegetpermissionsasync) to interact with the permissions.\n *\n * @example\n * ```js\n * const [status, requestPermission] = ScreenCapture.usePermissions();\n * ```\n */\nexport const usePermissions = createPermissionHook({\n    getMethod: getPermissionsAsync,\n    requestMethod: requestPermissionsAsync,\n});\nconst defaultPermissionsResponse = {\n    granted: true,\n    expires: 'never',\n    canAskAgain: true,\n    status: PermissionStatus.GRANTED,\n};\nexport { PermissionStatus, };\n//# sourceMappingURL=ScreenCapture.js.map","import { requireNativeModule } from 'expo-modules-core';\nexport default requireNativeModule('ExpoScreenCapture');\n//# sourceMappingURL=ExpoScreenCapture.js.map","/**\n * FormField — input de formulario del Design System.\n * Fondo surface, borde redondeado, FOCO AZUL PRIMARIO, error rojo de 1 línea.\n * Regla del kit: todo input de producto se construye con este componente.\n *\n * ── CORRECCIÓN (UX): el campo MULTILÍNEA vivía dentro de una caja de `height: 50` ──\n *\n * `box` tiene 50 px de alto fijo, así que un `multiline` (normas del hotel, descripción de\n * la tienda, notas) quedaba **encerrado en 50 px**: el usuario escribía cinco líneas y veía\n * una y media, con el resto oculto tras un scroll interno invisible. Eso es exactamente\n * «la tarjeta esconde lo que escribes».\n *\n * Se nota que era una trampa del kit porque otras pantallas la esquivaban a mano, con su\n * propio `<TextInput multiline style={s.area}>` (`alquiler-publicar`, `work-publish`,\n * `ecomerse-seller`). Ahora el propio FormField tiene el modo área: caja alta, alineación\n * arriba y `textAlignVertical: 'top'` (sin eso, en Android el texto se centra).\n */\nimport React, { useState } from 'react';\nimport { StyleSheet, Text, TextInput, View, type TextInputProps } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { altura, espaciado, peso, radios, tipografia, trazo } from '../theme/escalas';\n\nexport function FormField({\n  label,\n  error,\n  icon,\n  ...inputProps\n}: {\n  label?: string;\n  error?: string;\n  icon?: React.ReactNode;\n} & TextInputProps) {\n  const { colors } = useTheme();\n  const [focused, setFocused] = useState(false);\n  const area = inputProps.multiline === true;\n\n  return (\n    <View style={styles.wrap}>\n      {label ? (\n        <Text style={[styles.label, { color: colors.textSecondary }]}>{label}</Text>\n      ) : null}\n      <View\n        style={[\n          styles.boxBase,\n          area ? styles.boxArea : styles.box,\n          {\n            backgroundColor: colors.surface,\n            borderColor: error ? colors.danger : focused ? colors.primary : 'transparent',\n          },\n        ]}\n      >\n        {icon ? <View style={styles.icon}>{icon}</View> : null}\n        <TextInput\n          placeholderTextColor={colors.textSecondary}\n          {...(area ? { textAlignVertical: 'top' as const } : {})}\n          style={[styles.input, area ? styles.inputArea : null, { color: colors.textPrimary }]}\n          onFocus={(e) => {\n            setFocused(true);\n            inputProps.onFocus?.(e);\n          }}\n          onBlur={(e) => {\n            setFocused(false);\n            inputProps.onBlur?.(e);\n          }}\n          {...inputProps}\n        />\n      </View>\n      {error ? (\n        <Text style={[styles.error, { color: colors.danger }]} accessibilityLiveRegion=\"polite\" numberOfLines={1}>\n          {error}\n        </Text>\n      ) : null}\n    </View>\n  );\n}\n\n/**\n * Los cuatro números de forma salen de las escalas del kit (`altura`, `radios`, `trazo`, `espaciado`).\n * Antes eran literales sueltos y por eso el campo medía lo que medía: **`altura.campo` (50) no se usaba\n * ni una vez en toda la app** aunque existía para esto exacto (auditoría del 23/09/2026).\n *\n * DOS LITERALES QUE SE QUEDAN, y se dice por qué:\n *   · `input.fontSize: 15` → ya es `tipografia.cuerpo` (15), migrado sin mover un píxel.\n *   · `input.fontWeight: '600'` → **se queda a propósito**. Pasa a `peso.medio` (500) por la decisión\n *     del 24/09/2026, pero eso es la migración de la familia `fontWeight` (214 literales en total), y\n *     es Fase 3. Aquí no se adelanta: un cambio de peso en TODOS los formularios de la app se verifica\n *     con su propia tanda, no colado dentro de la de alturas.\n */\nconst styles = StyleSheet.create({\n  wrap: { width: '100%' },\n  label: {\n    fontSize: tipografia.caption,\n    fontWeight: peso.fuerte,\n    marginBottom: espaciado.e6,\n    marginLeft: espaciado.e4,\n  },\n  boxBase: {\n    flexDirection: 'row',\n    borderWidth: trazo.base,\n    borderRadius: radios.campo,\n    paddingHorizontal: espaciado.e14,\n  },\n  /** Una línea: alto fijo, como estaba — pero el número sale de `altura.campo`. */\n  box: { alignItems: 'center', height: altura.campo },\n  /** Varias líneas: caja alta y contenido alineado arriba. */\n  boxArea: {\n    alignItems: 'flex-start',\n    minHeight: 108,\n    paddingTop: espaciado.e12,\n    paddingBottom: espaciado.e12,\n  },\n  icon: { marginRight: espaciado.e10 },\n  input: { flex: 1, fontSize: tipografia.cuerpo, fontWeight: '600', paddingVertical: 0 },\n  inputArea: { minHeight: 84 },\n  error: {\n    /* 11,5 no tiene peldaño en `tipografia` (salta de `micro` 10,5 a `caption` 12). Es 1 de los\n       literales fraccionarios que la Fase 3 tiene que decidir; hoy no se toca. */\n    fontSize: 11.5,\n    fontWeight: peso.fuerte,\n    marginTop: espaciado.e5,\n    marginLeft: espaciado.e4,\n  },\n});\n\n","/**\n * OtpInput — 6 celdas OTP con auto-avance (input oculto accesible).\n * La celda activa tiene borde azul primario; error en rojo de 1 línea.\n *\n * Uso:\n *   <OtpInput value={code} onChange={setCode} onComplete={verify} error={err} />\n */\n\nimport React, { useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useScreenGuard } from '../security/useScreenGuard';\n\nexport function OtpInput({\n  value,\n  onChange,\n  onComplete,\n  length = 6,\n  error,\n  autoFocus = true,\n}: {\n  value: string;\n  onChange: (code: string) => void;\n  onComplete?: (code: string) => void;\n  length?: number;\n  error?: string;\n  autoFocus?: boolean;\n}) {\n  const { colors } = useTheme();\n  const inputRef = useRef<TextInput>(null);\n  const [focused, setFocused] = useState(false);\n\n  // Los códigos OTP también son secretos en pantalla.\n  useScreenGuard(true);\n\n  const handleChange = (text: string) => {\n    const clean = text.replace(/\\D/g, '').slice(0, length);\n    onChange(clean);\n    if (clean.length === length) onComplete?.(clean);\n  };\n\n  return (\n    <View>\n      <Pressable\n        style={styles.cells}\n        onPress={() => inputRef.current?.focus()}\n        accessibilityLabel={`Código de verificación de ${length} dígitos`}\n      >\n        {Array.from({ length }).map((_, i) => {\n          const digit = value[i] ?? '';\n          const isActive = focused && i === Math.min(value.length, length - 1);\n          return (\n            <View\n              key={i}\n              style={[\n                styles.cell,\n                {\n                  backgroundColor: colors.surface,\n                  borderColor: error\n                    ? colors.danger\n                    : isActive\n                      ? colors.primary\n                      : colors.border,\n                },\n              ]}\n            >\n              <Text style={[styles.digit, { color: colors.textPrimary }]}>{digit}</Text>\n            </View>\n          );\n        })}\n      </Pressable>\n\n      <TextInput\n        ref={inputRef}\n        value={value}\n        onChangeText={handleChange}\n        keyboardType=\"number-pad\"\n        textContentType=\"oneTimeCode\"\n        autoComplete=\"sms-otp\"\n        maxLength={length}\n        autoFocus={autoFocus}\n        onFocus={() => setFocused(true)}\n        onBlur={() => setFocused(false)}\n        style={styles.hiddenInput}\n        caretHidden\n        accessibilityLabel=\"Introduce el código OTP\"\n      />\n\n      {error ? (\n        <Text style={[styles.error, { color: colors.danger }]} accessibilityLiveRegion=\"polite\">\n          {error}\n        </Text>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cells: { flexDirection: 'row', justifyContent: 'center', gap: 10 },\n  cell: {\n    width: 46,\n    height: 54,\n    borderRadius: 14,\n    borderWidth: 1.5,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  digit: { fontSize: 22, fontWeight: '800' },\n  hiddenInput: {\n    position: 'absolute',\n    opacity: 0,\n    height: 1,\n    width: 1,\n  },\n  error: { fontSize: 12, fontWeight: '700', marginTop: 10, textAlign: 'center' },\n});\n","/**\n * PinSheet — LA hoja de PIN del monedero (oficial desde la Fase 1 de la auditoría de diseño).\n *\n * POR QUÉ VIVE EN EL KIT: había **tres** implementaciones de PIN en el proyecto — este componente\n * (usado por 6 pantallas), un `PinPad` del kit que no lo usaba nadie y un `PinPadModal` suelto\n * dentro de `conductor.tsx`. Tener tres sitios donde se escribe el PIN significa que un arreglo de\n * bloqueo, de intentos o de mensaje de error no llega a los otros dos. Este es el que se adopta;\n * `PinPad` se retiró.\n *\n * Incluye lo que la auditoría señaló como lo más grave de accesibilidad:\n *   · El campo del PIN tiene nombre y pista (antes solo tenía el marcador «••••••»).\n *   · El error se ANUNCIA: en Android con `accessibilityLiveRegion`, en iOS a mano con\n *     `announceForAccessibility` (que en toda la app eran 0 llamadas).\n *   · El foco queda atrapado en la hoja (`accessibilityViewIsModal`).\n *   · Vibra al confirmar y avisa con una vibración distinta cuando el PIN falla.\n *\n * Uso:\n *   <PinSheet visible={…} title=\"Recargar 5.000 XAF\" subtitle=\"…\"\n *     busy={…} error={…} onClose={…} onConfirm={(pin, pwd) => …} />\n * onConfirm recibe (pin, password?) — password solo llega en modo alta.\n */\nimport React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, Modal, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { PrimaryButton, GhostButton } from './PrimaryButton';\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand } from '../theme/colors';\nimport { haptico } from '../feedback/hapticos';\nimport { anunciar } from '../feedback/anuncios';\n\nexport interface PinSheetProps {\n  visible: boolean;\n  title: string;\n  subtitle?: string;\n  busy: boolean;\n  error?: string | null;\n  /** true = pedir también la contraseña (alta del PIN en el primer uso). */\n  needPassword?: boolean;\n  confirmLabel?: string;\n  onClose: () => void;\n  onConfirm: (pin: string, password?: string) => void;\n}\n\nexport function PinSheet({\n  visible, title, subtitle, busy, error, needPassword = false,\n  confirmLabel = 'Confirmar', onClose, onConfirm,\n}: PinSheetProps) {\n  const { colors } = useTheme();\n  const [pin, setPin] = useState('');\n  const [pwd, setPwd] = useState('');\n\n  useEffect(() => {\n    if (visible) { setPin(''); setPwd(''); }\n  }, [visible]);\n\n  /**\n   * El error del PIN tiene que LLEGAR al usuario que usa lector de pantalla.\n   * En Android basta `accessibilityLiveRegion`; en iOS hay que anunciarlo a mano, y en toda la\n   * app había 0 llamadas a `announceForAccessibility`: no se anunciaba nada.\n   */\n  useEffect(() => {\n    if (!error) return;\n    // Antes esto solo se anunciaba en Android: en iOS el error del PIN no llegaba a nadie (D-48).\n    anunciar(error);\n    haptico('aviso');\n  }, [error]);\n\n  const listo = pin.length === 6 && (!needPassword || pwd.length >= 4);\n\n  return (\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={() => { if (!busy) onClose(); }}>\n      <View style={styles.overlay}>\n        <View\n          style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}\n          accessibilityViewIsModal\n        >\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}>{title}</Text>\n          {subtitle ? (\n            <Text style={{ color: colors.textSecondary, fontSize: 13.5, textAlign: 'center', marginTop: 4 }}>{subtitle}</Text>\n          ) : null}\n          {needPassword && (\n            <TextInput\n              style={[styles.input, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary, marginTop: 12 }]}\n              placeholder=\"Contraseña de tu cuenta\"\n              placeholderTextColor={colors.textSecondary}\n              value={pwd}\n              onChangeText={setPwd}\n              secureTextEntry\n              autoCorrect={false}\n              editable={!busy}\n              accessibilityLabel=\"Contraseña de tu cuenta\"\n            />\n          )}\n          <TextInput\n            style={[styles.input, {\n              backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary,\n              marginTop: needPassword ? 8 : 12, textAlign: 'center', fontSize: 22, letterSpacing: 8,\n            }]}\n            placeholder=\"••••••\"\n            placeholderTextColor={colors.textSecondary}\n            value={pin}\n            onChangeText={(t) => setPin(t.replace(/\\D/g, '').slice(0, 6))}\n            secureTextEntry\n            keyboardType=\"number-pad\"\n            maxLength={6}\n            editable={!busy}\n            autoFocus\n            accessibilityLabel=\"PIN del monedero, 6 dígitos\"\n            accessibilityHint=\"Se confirma al escribir los seis dígitos\"\n          />\n          {error ? (\n            <Text\n              accessibilityLiveRegion=\"assertive\"\n              accessibilityRole=\"alert\"\n              style={{ color: brand.danger, fontSize: 13, textAlign: 'center', marginTop: 8 }}\n            >{error}</Text>\n          ) : null}\n          {busy ? (\n            <ActivityIndicator color={colors.primary} style={{ marginVertical: 18 }} accessibilityLabel=\"Comprobando el PIN\" />\n          ) : (\n            <View style={{ gap: 10, marginTop: 14 }}>\n              <PrimaryButton\n                title={confirmLabel}\n                onPress={() => { haptico('toque'); onConfirm(pin, pwd || undefined); }}\n                disabled={!listo}\n              />\n              <GhostButton title=\"Volver\" onPress={onClose} />\n            </View>\n          )}\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  overlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'center', padding: 24 },\n  card: { borderRadius: 20, borderWidth: 1, padding: 20 },\n  input: { borderWidth: 1, borderRadius: 12, paddingHorizontal: 14, paddingVertical: 10, fontSize: 14 },\n});\n","/**\n * PrimaryButton / GhostButton — sistema de acciones del Design System.\n * Regla: UN SOLO CTA azul por pantalla; acciones secundarias sin relleno.\n */\n\nimport React from 'react';\nimport { ActivityIndicator, Pressable, StyleSheet, Text } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { haptico } from '../feedback/hapticos';\nimport { altura, espaciado, peso, radios, tipografia } from '../theme/escalas';\nimport { brand } from '../theme/colors';\n\ntype Variant = 'primary' | 'danger' | 'success';\n\nconst variantColor = {\n  primary: 'primary',\n  danger: 'danger',\n  success: 'success',\n} as const;\n\nexport function PrimaryButton({\n  title,\n  onPress,\n  variant = 'primary',\n  loading = false,\n  disabled = false,\n  accessibilityLabel,\n  testID,\n  haptic = true,\n}: {\n  title: string;\n  onPress: () => void;\n  variant?: Variant;\n  loading?: boolean;\n  disabled?: boolean;\n  accessibilityLabel?: string;\n  testID?: string;\n  /** Vibra al pulsar. Se puede apagar donde moleste. */\n  haptic?: boolean;\n}) {\n  const { colors } = useTheme();\n  const bg = colors[variantColor[variant]];\n  const isDisabled = disabled || loading;\n\n  return (\n    <Pressable\n      onPress={() => { if (haptic) haptico('toque'); onPress(); }}\n      disabled={isDisabled}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel ?? title}\n      accessibilityState={{ disabled: isDisabled, busy: loading }}\n      style={({ pressed }) => [\n        styles.base,\n        {\n          backgroundColor: bg,\n          opacity: isDisabled ? 0.45 : pressed ? 0.9 : 1,\n          transform: [{ scale: pressed && !isDisabled ? 0.98 : 1 }],\n        },\n      ]}\n    >\n      {loading ? (\n        <ActivityIndicator color={brand.white} size=\"small\" />\n      ) : (\n        <Text style={styles.text}>{title}</Text>\n      )}\n    </Pressable>\n  );\n}\n\nexport function GhostButton({\n  title,\n  onPress,\n  disabled = false,\n  accessibilityLabel,\n  accessibilityHint,\n  testID,\n}: {\n  title: string;\n  onPress: () => void;\n  disabled?: boolean;\n  accessibilityLabel?: string;\n  accessibilityHint?: string;\n  testID?: string;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      disabled={disabled}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel ?? title}\n      accessibilityHint={accessibilityHint}\n      style={({ pressed }) => [styles.ghost, { opacity: disabled ? 0.4 : pressed ? 0.6 : 1 }]}\n    >\n      <Text style={[styles.ghostText, { color: colors.primary }]}>{title}</Text>\n    </Pressable>\n  );\n}\n\n/**\n * LAS MEDIDAS SALEN DE LAS ESCALAS DEL KIT, no de literales.\n *\n * `altura.boton` (52) es el peldaño que existía **para este botón** y que este botón no usaba: el\n * comentario de la escala decía «es el que ya usa `PrimaryButton.tsx:102`» mientras la línea 102\n * escribía `52` a mano (auditoría del 23/09/2026). Lo mismo `radios.lg` (16), `peso.maximo` (800) y\n * el `paddingVertical` del ghost (12 → `espaciado.e12`): mismo valor, ahora con nombre.\n *\n * UN LITERAL QUE SE QUEDA: `text.fontSize: 15.5`. No tiene peldaño — `tipografia` va de `cuerpo` (15)\n * a `subtitle` (16) — y hay **18 usos más** de 15,5 en la app. Es una decisión de la Fase 3 (declarar\n * el peldaño o bajarlo a 15), no un descuido.\n */\nconst styles = StyleSheet.create({\n  base: {\n    height: altura.boton,\n    borderRadius: radios.lg,\n    alignItems: 'center',\n    justifyContent: 'center',\n    width: '100%',\n  },\n  text: { color: brand.white, fontSize: 15.5, fontWeight: peso.maximo, letterSpacing: 0.2 },\n  ghost: { alignItems: 'center', paddingVertical: espaciado.e12 },\n  ghostText: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n});\n","/**\n * HÁPTICOS — la app no tenía ninguno.\n *\n * `expo-haptics` no estaba instalado y el único archivo que lo mencionaba lo hacía justo para\n * aclarar que no vibraba (auditoría de diseño, D-14). Se centraliza aquí por dos razones:\n *   1. El día que se cambie de librería, se cambia en un sitio.\n *   2. Ninguna llamada puede tumbar una pantalla: si el dispositivo no tiene motor o el módulo\n *      falla, el pago sigue funcionando igual. Un háptico es un adorno, no un requisito.\n *\n * Uso: `haptico('exito')` al confirmar un cobro, `haptico('aviso')` cuando algo no cuadra.\n */\nimport { Platform } from 'react-native';\nimport * as Haptics from 'expo-haptics';\n\nexport type TipoHaptico = 'toque' | 'exito' | 'aviso' | 'error';\n\nexport function haptico(tipo: TipoHaptico = 'toque'): void {\n  // En web no hay motor de vibración y en algunos dispositivos va desactivado por el usuario.\n  if (Platform.OS === 'web') return;\n  try {\n    const p =\n      tipo === 'exito'\n        ? Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success)\n        : tipo === 'aviso'\n          ? Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning)\n          : tipo === 'error'\n            ? Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error)\n            : Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);\n    // `notificationAsync` devuelve una promesa: rechazarla en silencio evita un unhandled rejection.\n    void p?.catch?.(() => {});\n  } catch {\n    /* sin motor de vibración o módulo ausente: se ignora a propósito */\n  }\n}\n","import { Platform, UnavailabilityError } from 'expo-modules-core';\n\nimport ExpoHaptics from './ExpoHaptics';\nimport { NotificationFeedbackType, ImpactFeedbackStyle, AndroidHaptics } from './Haptics.types';\n\n// @needsAudit\n/**\n * The kind of notification response used in the feedback.\n * @param type A notification feedback type that on Android is simulated using [`Vibrator`](https://developer.android.com/reference/android/os/Vibrator)\n * and iOS is directly mapped to [`UINotificationFeedbackType`](https://developer.apple.com/documentation/uikit/uinotificationfeedbacktype).\n * You can use one of `Haptics.NotificationFeedbackType.{Success, Warning, Error}`.\n * @return A `Promise` which fulfils once native size haptics functionality is triggered.\n */\nexport async function notificationAsync(\n  type: NotificationFeedbackType = NotificationFeedbackType.Success\n): Promise<void> {\n  if (!ExpoHaptics?.notificationAsync) {\n    throw new UnavailabilityError('Haptics', 'notificationAsync');\n  }\n  await ExpoHaptics.notificationAsync(type);\n}\n\n// @needsAudit\n/**\n * @param style A collision indicator that on Android is simulated using [`Vibrator`](https://developer.android.com/reference/android/os/Vibrator)\n * and on iOS, it is directly mapped to [`UIImpactFeedbackStyle`](https://developer.apple.com/documentation/uikit/uiimpactfeedbackgenerator/feedbackstyle).\n * You can use one of `Haptics.ImpactFeedbackStyle.{Light, Medium, Heavy, Rigid, Soft}`.\n * @return A `Promise` which fulfils once native size haptics functionality is triggered.\n */\nexport async function impactAsync(\n  style: ImpactFeedbackStyle = ImpactFeedbackStyle.Medium\n): Promise<void> {\n  if (!ExpoHaptics?.impactAsync) {\n    throw new UnavailabilityError('Haptic', 'impactAsync');\n  }\n  await ExpoHaptics.impactAsync(style);\n}\n\n// @needsAudit\n/**\n * Used to let a user know when a selection change has been registered.\n * @return A `Promise` which fulfils once native size haptics functionality is triggered.\n */\nexport async function selectionAsync(): Promise<void> {\n  if (!ExpoHaptics?.selectionAsync) {\n    throw new UnavailabilityError('Haptic', 'selectionAsync');\n  }\n  await ExpoHaptics.selectionAsync();\n}\n\n/**\n * Use the device haptics engine to provide physical feedback to the user.\n *\n * @platform android\n */\nexport async function performAndroidHapticsAsync(type: AndroidHaptics) {\n  if (Platform.OS !== 'android') {\n    return;\n  }\n  ExpoHaptics.performHapticsAsync(type);\n}\n\nexport { NotificationFeedbackType, ImpactFeedbackStyle, AndroidHaptics };\n","import { requireOptionalNativeModule } from 'expo';\n\nexport default requireOptionalNativeModule('ExpoHaptics');\n","// @needsAudit\n/**\n * The type of notification feedback generated by a `UINotificationFeedbackGenerator` object.\n * [`UINotificationFeedbackType`](https://developer.apple.com/documentation/uikit/uinotificationfeedbackgenerator/feedbacktype).\n */\nexport enum NotificationFeedbackType {\n  /**\n   * A notification feedback type indicating that a task has completed successfully.\n   */\n  Success = 'success',\n  /**\n   * A notification feedback type indicating that a task has produced a warning.\n   */\n  Warning = 'warning',\n  /**\n   * A notification feedback type indicating that a task has failed.\n   */\n  Error = 'error',\n}\n\n// @needsAudit\n/**\n * The mass of the objects in the collision simulated by a `UIImpactFeedbackGenerator` object\n * [`UINotificationFeedbackStyle`](https://developer.apple.com/documentation/uikit/uiimpactfeedbackgenerator/feedbackstyle).\n */\nexport enum ImpactFeedbackStyle {\n  /**\n   * A collision between small, light user interface elements.\n   */\n  Light = 'light',\n  /**\n   * A collision between moderately sized user interface elements.\n   */\n  Medium = 'medium',\n  /**\n   * A collision between large, heavy user interface elements.\n   */\n  Heavy = 'heavy',\n  /**\n   * A collision between user interface elements that are soft, exhibiting a large amount of compression or elasticity.\n   */\n  Soft = 'soft',\n  /**\n   * A collision between user interface elements that are rigid, exhibiting a small amount of compression or elasticity.\n   */\n  Rigid = 'rigid',\n}\n\n/**\n * @platform android\n */\nexport enum AndroidHaptics {\n  /**\n   * A haptic effect to signal the confirmation or successful completion of a user interaction.\n   */\n  Confirm = 'confirm',\n  /**\n   * A haptic effect to signal the rejection or failure of a user interaction.\n   */\n  Reject = 'reject',\n  /**\n   * The user has started a gesture (for example, on the soft keyboard).\n   */\n  Gesture_Start = 'gesture-start',\n  /**\n   * The user has finished a gesture (for example, on the soft keyboard).\n   */\n  Gesture_End = 'gesture-end',\n  /**\n   * The user has toggled a switch or button into the on position.\n   */\n  Toggle_On = 'toggle-on',\n  /**\n   * The user has toggled a switch or button into the off position.\n   */\n  Toggle_Off = 'toggle-off',\n  /**\n   * The user has pressed either an hour or minute tick of a Clock.\n   */\n  Clock_Tick = 'clock-tick',\n  /**\n   * The user has performed a context click on an object.\n   */\n  Context_Click = 'context-click',\n  /**\n   * The user has started a drag-and-drop gesture. The drag target has just been \"picked up\".\n   */\n  Drag_Start = 'drag-start',\n  /**\n   * The user has pressed a soft keyboard key.\n   */\n  Keyboard_Tap = 'keyboard-tap',\n  /**\n   * The user has pressed a virtual or software keyboard key.\n   */\n  Keyboard_Press = 'keyboard-press',\n  /**\n   * The user has released a virtual keyboard key.\n   */\n  Keyboard_Release = 'keyboard-release',\n  /**\n   * The user has performed a long press on an object that results in an action being performed.\n   */\n  Long_Press = 'long-press',\n  /**\n   * The user has pressed on a virtual on-screen key.\n   */\n  Virtual_Key = 'virtual-key',\n  /**\n   * The user has released a virtual key.\n   */\n  Virtual_Key_Release = 'virtual-key-release',\n  /**\n   * No haptic feedback should be performed.\n   */\n  No_Haptics = 'no-haptics',\n  /**\n   * The user is switching between a series of potential choices. For example, items in a list or discrete points on a slider.\n   */\n  Segment_Tick = 'segment-tick',\n  /**\n   * The user is switching between a series of many potential choices. For example, minutes on a clock face or individual percentages.\n   * This constant is expected to be very soft, so as not to be uncomfortable when performed a lot in quick succession.\n   * If the device can't make a suitably soft vibration, then it may not make any vibration.\n   */\n  Segment_Frequent_Tick = 'segment-frequent-tick',\n  /**\n   * The user has performed a selection/insertion handle move on text field.\n   */\n  Text_Handle_Move = 'text-handle-move',\n}\n","/**\n * ANUNCIOS PARA LECTORES DE PANTALLA.\n *\n * POR QUÉ EXISTE: la app tenía 4 anuncios escritos con la llamada que solo funciona en Android, y\n * **cero** que funcionaran en iOS (`announceForAccessibilityWithOptions` no se usaba en ningún\n * sitio). Un aviso que no se anuncia es un aviso que no existe para quien no ve la pantalla.\n *\n * Uso: `anunciar('PIN incorrecto, te quedan 2 intentos')`.\n * En Android basta esta llamada; en iOS hay que usar la variante con opciones.\n */\nimport { AccessibilityInfo, Platform } from 'react-native';\n\nexport function anunciar(mensaje: string): void {\n  if (!mensaje) return;\n  try {\n    const conOpciones = AccessibilityInfo as unknown as {\n      announceForAccessibilityWithOptions?: (m: string, o: { queue?: boolean }) => void;\n    };\n    if (Platform.OS === 'ios' && typeof conOpciones.announceForAccessibilityWithOptions === 'function') {\n      // `queue: true` para que no corte el anuncio que esté sonando.\n      conOpciones.announceForAccessibilityWithOptions(mensaje, { queue: true });\n    } else {\n      AccessibilityInfo.announceForAccessibility(mensaje);\n    }\n  } catch {\n    /* Un anuncio que falla no puede romper la pantalla. */\n  }\n}\n","/**\n * Sheet — la hoja de diálogo ÚNICA del kit.\n *\n * POR QUÉ EXISTE: en la app había **51 archivos** que escribían su propio `<Modal>` (y solo una\n * referencia a una hoja inferior). Cada uno decidía por su cuenta el fondo oscurecido, la posición,\n * el cierre al tocar fuera y —lo más importante— **si el lector de pantalla lo anunciaba**. Por eso\n * la accesibilidad de los diálogos era irregular: no había un sitio único donde arreglarla.\n *\n * Trae lo que hace falta para que un diálogo esté bien sin pensarlo:\n *   · Cierre al tocar fuera y con el botón físico de atrás (`onRequestClose`).\n *   · El foco queda DENTRO de la hoja (`accessibilityViewIsModal`), que en iOS es la diferencia\n *     entre un diálogo usable y uno que deja al usuario perdido detrás.\n *   · Título con rol de cabecera y el resto del contenido etiquetado por él.\n *   · No se puede cerrar mientras `busy` (no se abandona un pago a medias por un toque fuera).\n *\n * Uso:\n *   <Sheet visible={x} title=\"¿Cancelar el pedido?\" onClose={cerrar}>\n *     <Text>…</Text>\n *     <PrimaryButton title=\"Sí, cancelar\" onPress={…} />\n *   </Sheet>\n */\nimport React, { type ReactNode } from 'react';\nimport { Modal, Platform, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { haptico } from '../feedback/hapticos';\n\nexport interface SheetProps {\n  visible: boolean;\n  /** Cabecera del diálogo. Se anuncia como cabecera al lector de pantalla. */\n  title: string;\n  subtitle?: string;\n  /** Si está ocupado, no se cierra ni tocando fuera ni con el botón de atrás. */\n  busy?: boolean;\n  /** `center` para confirmaciones cortas; `bottom` para hojas de acción. */\n  position?: 'center' | 'bottom';\n  onClose: () => void;\n  children?: ReactNode;\n}\n\nexport function Sheet({\n  visible, title, subtitle, busy = false, position = 'center', onClose, children,\n}: SheetProps) {\n  const { colors } = useTheme();\n  const cerrar = () => { if (!busy) onClose(); };\n\n  return (\n    <Modal\n      visible={visible}\n      transparent\n      animationType={position === 'bottom' ? 'slide' : 'fade'}\n      onRequestClose={cerrar}\n      // En Android el botón atrás dispara `onRequestClose`; en iOS el gesto de cierre.\n      statusBarTranslucent\n    >\n      <View style={[styles.overlay, position === 'bottom' ? styles.abajo : styles.centro]}>\n        {/* Tocar fuera cierra: es lo que espera cualquiera. */}\n        <Pressable\n          style={StyleSheet.absoluteFill}\n          onPress={cerrar}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Cerrar\"\n          // El fondo no debe robar el foco del diálogo.\n          importantForAccessibility=\"no\"\n        />\n        <View\n          accessibilityViewIsModal\n          style={[\n            styles.hoja,\n            position === 'bottom' ? styles.hojaAbajo : styles.hojaCentro,\n            { backgroundColor: colors.card, borderColor: colors.border },\n          ]}\n        >\n          <Text\n            accessibilityRole=\"header\"\n            style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}\n          >\n            {title}\n          </Text>\n          {subtitle ? (\n            <Text style={{ color: colors.textSecondary, fontSize: 13.5, textAlign: 'center', marginTop: 4 }}>\n              {subtitle}\n            </Text>\n          ) : null}\n          <View style={{ marginTop: 14, gap: 10 }}>{children}</View>\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  overlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' },\n  centro: { justifyContent: 'center', padding: 24 },\n  abajo: { justifyContent: 'flex-end' },\n  hoja: { borderWidth: 1, padding: 20 },\n  hojaCentro: { borderRadius: 20 },\n  hojaAbajo: {\n    borderTopLeftRadius: 24,\n    borderTopRightRadius: 24,\n    borderBottomWidth: 0,\n    paddingBottom: Platform.OS === 'ios' ? 34 : 22,\n    /*\n      Tope de altura para la hoja de abajo. Sin esto, una hoja con una lista larga (el selector de\n      ciudad, 24 filas) crece hasta ocupar la pantalla entera y deja de parecer una hoja: lo encontró\n      la comprobación EN EL APARATO, no el compilador. Con el tope, lo de dentro desplaza — que es lo\n      que hacía el modal escrito a mano con su `maxHeight: '75%'`.\n    */\n    maxHeight: '80%',\n  },\n});\n","/**\n * InlineError — el error EN LA PANTALLA, no encima de ella.\n *\n * POR QUÉ EXISTE: la app comunicaba el error con **411 `Alert.alert` repartidos en 71 archivos**\n * (auditoría de diseño, D-03). Un modal bloqueante corta el flujo: el usuario pierde el contexto de\n * lo que estaba haciendo y tiene que cerrar una ventana para volver a intentarlo. En una pantalla de\n * dinero eso es exactamente lo que no queremos.\n *\n * Este componente dice qué pasó, delante de la vista y sin robar el toque. Se anuncia al lector de\n * pantalla (en las dos plataformas) y vibra al aparecer: quien no mira la pantalla también se entera.\n *\n * Uso: <InlineError mensaje={error} onReintentar={() => void pagar()} />\n */\nimport React, { useEffect } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { alpha, brand } from '../theme/colors';\nimport { AlertTriangle } from 'lucide-react-native';\nimport { anunciar } from '../feedback/anuncios';\nimport { haptico } from '../feedback/hapticos';\n\nexport interface InlineErrorProps {\n  mensaje?: string | null;\n  /** Si se pasa, aparece un botón de reintento: el error dice cómo salir, no solo que hay error. */\n  onReintentar?: () => void;\n  /** Texto del botón de reintento. */\n  etiquetaReintento?: string;\n  /**\n   * Para pantallas que fuerzan fondo OSCURO (el feed de vídeo es negro a propósito): el mensaje y el\n   * reintento usan los colores del TEMA, y sobre negro el tema claro daría texto oscuro sobre oscuro.\n   */\n  sobreOscuro?: boolean;\n}\n\nexport function InlineError({\n  mensaje, onReintentar, etiquetaReintento = 'Reintentar', sobreOscuro = false,\n}: InlineErrorProps) {\n  const { colors } = useTheme();\n\n  useEffect(() => {\n    if (!mensaje) return;\n    anunciar(mensaje);\n    haptico('aviso');\n  }, [mensaje]);\n\n  if (!mensaje) return null;\n\n  return (\n    <View\n      accessibilityLiveRegion=\"assertive\"\n      accessibilityRole=\"alert\"\n      style={[\n        styles.caja,\n        sobreOscuro\n          ? { backgroundColor: alpha(brand.white, 0.08), borderColor: alpha(brand.white, 0.35) }\n          : { backgroundColor: alpha(colors.danger, 0.08), borderColor: alpha(colors.danger, 0.3) },\n      ]}\n    >\n      <AlertTriangle size={16} color={sobreOscuro ? brand.warning : colors.danger} />\n      <Text style={{ flex: 1, color: sobreOscuro ? brand.white : colors.textPrimary, fontSize: 13.5, lineHeight: 19 }}>{mensaje}</Text>\n      {onReintentar ? (\n        <Pressable onPress={onReintentar} hitSlop={8} accessibilityRole=\"button\">\n          <Text style={{ color: sobreOscuro ? brand.white : colors.primary, fontSize: 13.5, fontWeight: '800' }}>{etiquetaReintento}</Text>\n        </Pressable>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  caja: {\n    flexDirection: 'row', alignItems: 'center', gap: 10,\n    borderWidth: 1, borderRadius: 12, paddingHorizontal: 12, paddingVertical: 10,\n  },\n});\n","/**\n * @license lucide-react-native v0.525.0 - ISC\n *\n * This source code is licensed under the ISC license.\n * See the LICENSE file in the root directory of this source tree.\n */\n\nimport * as index from './icons/index.js';\nexport { index as icons };\nexport { default as AlarmCheck, default as AlarmCheckIcon, default as AlarmClockCheck, default as AlarmClockCheckIcon, default as LucideAlarmCheck, default as LucideAlarmClockCheck } from './icons/alarm-clock-check.js';\nexport { default as AlarmClockMinus, default as AlarmClockMinusIcon, default as AlarmMinus, default as AlarmMinusIcon, default as LucideAlarmClockMinus, default as LucideAlarmMinus } from './icons/alarm-clock-minus.js';\nexport { default as AlarmClockPlus, default as AlarmClockPlusIcon, default as AlarmPlus, default as AlarmPlusIcon, default as LucideAlarmClockPlus, default as LucideAlarmPlus } from './icons/alarm-clock-plus.js';\nexport { default as ArrowDownAZ, default as ArrowDownAZIcon, default as ArrowDownAz, default as ArrowDownAzIcon, default as LucideArrowDownAZ, default as LucideArrowDownAz } from './icons/arrow-down-a-z.js';\nexport { default as ArrowDownWideNarrow, default as ArrowDownWideNarrowIcon, default as LucideArrowDownWideNarrow, default as LucideSortDesc, default as SortDesc, default as SortDescIcon } from './icons/arrow-down-wide-narrow.js';\nexport { default as ArrowDownZA, default as ArrowDownZAIcon, default as ArrowDownZa, default as ArrowDownZaIcon, default as LucideArrowDownZA, default as LucideArrowDownZa } from './icons/arrow-down-z-a.js';\nexport { default as ArrowUpAZ, default as ArrowUpAZIcon, default as ArrowUpAz, default as ArrowUpAzIcon, default as LucideArrowUpAZ, default as LucideArrowUpAz } from './icons/arrow-up-a-z.js';\nexport { default as ArrowUpNarrowWide, default as ArrowUpNarrowWideIcon, default as LucideArrowUpNarrowWide, default as LucideSortAsc, default as SortAsc, default as SortAscIcon } from './icons/arrow-up-narrow-wide.js';\nexport { default as ArrowUpZA, default as ArrowUpZAIcon, default as ArrowUpZa, default as ArrowUpZaIcon, default as LucideArrowUpZA, default as LucideArrowUpZa } from './icons/arrow-up-z-a.js';\nexport { default as Axis3D, default as Axis3DIcon, default as Axis3d, default as Axis3dIcon, default as LucideAxis3D, default as LucideAxis3d } from './icons/axis-3d.js';\nexport { default as BadgeCheck, default as BadgeCheckIcon, default as LucideBadgeCheck, default as LucideVerified, default as Verified, default as VerifiedIcon } from './icons/badge-check.js';\nexport { default as BadgeHelp, default as BadgeHelpIcon, default as BadgeQuestionMark, default as BadgeQuestionMarkIcon, default as LucideBadgeHelp, default as LucideBadgeQuestionMark } from './icons/badge-question-mark.js';\nexport { default as BetweenHorizonalEnd, default as BetweenHorizonalEndIcon, default as BetweenHorizontalEnd, default as BetweenHo