from './elements/filters/Filter';\n\nexport {\n  Circle,\n  ClipPath,\n  Defs,\n  Ellipse,\n  FeBlend,\n  FeColorMatrix,\n  FeComponentTransfer,\n  FeComposite,\n  FeConvolveMatrix,\n  FeDiffuseLighting,\n  FeDisplacementMap,\n  FeDistantLight,\n  FeDropShadow,\n  FeFlood,\n  FeFuncA,\n  FeFuncB,\n  FeFuncG,\n  FeFuncR,\n  FeGaussianBlur,\n  FeImage,\n  FeMerge,\n  FeMergeNode,\n  FeMorphology,\n  FeOffset,\n  FePointLight,\n  FeSpecularLighting,\n  FeSpotLight,\n  FeTile,\n  FeTurbulence,\n  Filter,\n  ForeignObject,\n  G,\n  Image,\n  Line,\n  LinearGradient,\n  Marker,\n  Mask,\n  Path,\n  Pattern,\n  Polygon,\n  Polyline,\n  RadialGradient,\n  Rect,\n  Stop,\n  Svg,\n  Symbol,\n  Text,\n  TextPath,\n  TSpan,\n  Use,\n};\n\nexport default Svg;\n","import * as React from 'react';\nimport { extract } from '../lib/extract/extractProps';\nimport type { CommonPathProps, NumberProp } from '../lib/extract/types';\nimport Shape from './Shape';\nimport RNSVGCircle from '../fabric/CircleNativeComponent';\nimport type { NativeMethods } from 'react-native';\n\nexport interface CircleProps extends CommonPathProps {\n  cx?: NumberProp;\n  cy?: NumberProp;\n  opacity?: NumberProp;\n  r?: NumberProp;\n}\n\nexport default class Circle extends Shape<CircleProps> {\n  static displayName = 'Circle';\n\n  static defaultProps = {\n    cx: 0,\n    cy: 0,\n    r: 0,\n  };\n\n  render() {\n    const { props } = this;\n    const { cx, cy, r } = props;\n    const circleProps = { ...extract(this, props), cx, cy, r };\n\n    return (\n      <RNSVGCircle\n        ref={(ref) => this.refMethod(ref as (Circle & NativeMethods) | null)}\n        {...circleProps}\n      />\n    );\n  }\n}\n","import extractFill from './extractFill';\nimport extractStroke from './extractStroke';\nimport extractTransform from './extractTransform';\nimport extractResponder from './extractResponder';\nimport extractOpacity from './extractOpacity';\nimport { idPattern } from '../util';\nimport type {\n  ClipProps,\n  ColorProps,\n  extractedProps,\n  FillProps,\n  NumberProp,\n  ResponderProps,\n  StrokeProps,\n  TransformProps,\n} from './types';\n\nconst clipRules: { evenodd: number; nonzero: number } = {\n  evenodd: 0,\n  nonzero: 1,\n};\n\nexport function propsAndStyles(props: object & { style?: [] | unknown }) {\n  const { style } = props;\n  return !style\n    ? props\n    : {\n        ...(Array.isArray(style) ? Object.assign({}, ...style) : style),\n        ...props,\n      };\n}\n\nfunction getMarker(marker?: string) {\n  if (!marker) {\n    return undefined;\n  }\n  const matched = marker.match(idPattern);\n  return matched ? matched[1] : undefined;\n}\n\nexport default function extractProps(\n  props: {\n    id?: string;\n    mask?: string;\n    filter?: string;\n    marker?: string;\n    markerStart?: string;\n    markerMid?: string;\n    markerEnd?: string;\n    clipPath?: string;\n    display?: string;\n    opacity?: NumberProp;\n    onLayout?: () => void;\n    testID?: string;\n    accessibilityLabel?: string;\n    accessible?: boolean;\n  } & TransformProps &\n    ResponderProps &\n    StrokeProps &\n    FillProps &\n    ColorProps &\n    ClipProps,\n  ref: object\n) {\n  const {\n    id,\n    opacity,\n    onLayout,\n    clipPath,\n    clipRule,\n    display,\n    mask,\n    filter,\n    marker,\n    markerStart = marker,\n    markerMid = marker,\n    markerEnd = marker,\n    testID,\n    accessibilityLabel,\n    accessible,\n  } = props;\n  const extracted: extractedProps = {};\n\n  const inherited: string[] = [];\n  extractResponder(extracted, props, ref);\n  extractFill(extracted, props, inherited);\n  extractStroke(extracted, props, inherited);\n\n  if (props.color) {\n    extracted.color = props.color;\n  }\n\n  if (inherited.length) {\n    extracted.propList = inherited;\n  }\n\n  const matrix = extractTransform(props);\n  if (matrix !== null) {\n    extracted.matrix = matrix;\n  }\n\n  if (opacity != null) {\n    extracted.opacity = extractOpacity(opacity);\n  }\n\n  if (display != null) {\n    extracted.display = display === 'none' ? 'none' : undefined;\n  }\n\n  if (onLayout) {\n    extracted.onLayout = onLayout;\n  }\n\n  if (markerStart) {\n    extracted.markerStart = getMarker(markerStart);\n  }\n  if (markerMid) {\n    extracted.markerMid = getMarker(markerMid);\n  }\n  if (markerEnd) {\n    extracted.markerEnd = getMarker(markerEnd);\n  }\n\n  if (id) {\n    extracted.name = String(id);\n  }\n\n  if (testID) {\n    extracted.testID = testID;\n  }\n\n  if (accessibilityLabel) {\n    extracted.accessibilityLabel = accessibilityLabel;\n  }\n\n  if (accessible) {\n    extracted.accessible = accessible;\n  }\n\n  if (clipRule) {\n    extracted.clipRule = clipRules[clipRule] === 0 ? 0 : 1;\n  }\n  if (clipPath) {\n    const matched = clipPath.match(idPattern);\n    if (matched) {\n      extracted.clipPath = matched[1];\n    } else {\n      console.warn(\n        'Invalid `clipPath` prop, expected a clipPath like \"#id\", but got: \"' +\n          clipPath +\n          '\"'\n      );\n    }\n  }\n\n  if (mask) {\n    const matched = mask.match(idPattern);\n\n    if (matched) {\n      extracted.mask = matched[1];\n    } else {\n      console.warn(\n        'Invalid `mask` prop, expected a mask like \"#id\", but got: \"' +\n          mask +\n          '\"'\n      );\n    }\n  }\n\n  if (filter) {\n    const matched = filter.match(idPattern);\n\n    if (matched) {\n      extracted.filter = matched[1];\n    } else {\n      console.warn(\n        'Invalid `filter` prop, expected a filter like \"#id\", but got: \"' +\n          filter +\n          '\"'\n      );\n    }\n  }\n\n  return extracted;\n}\n\nexport function extract(\n  instance: object,\n  props: object & { style?: [] | unknown }\n) {\n  return extractProps(propsAndStyles(props), instance);\n}\n\nexport function withoutXY(\n  instance: object,\n  props: object & { style?: [] | unknown }\n) {\n  return extractProps({ ...propsAndStyles(props), x: null, y: null }, instance);\n}\n","import extractBrush from './extractBrush';\nimport extractOpacity from './extractOpacity';\nimport type { extractedProps, FillProps } from './types';\nimport { processColor } from 'react-native';\n\nconst fillRules: { evenodd: number; nonzero: number } = {\n  evenodd: 0,\n  nonzero: 1,\n};\n\nconst defaultFill = { type: 0, payload: processColor('black') };\n\nexport default function extractFill(\n  o: extractedProps,\n  props: FillProps,\n  inherited: string[],\n) {\n  const { fill, fillRule, fillOpacity } = props;\n  if (fill != null) {\n    inherited.push('fill');\n    o.fill =\n      !fill && typeof fill !== 'number' ? defaultFill : extractBrush(fill);\n  } else {\n    // we want the default value of fill to be black to match the spec\n    o.fill = defaultFill;\n  }\n  if (fillOpacity != null) {\n    inherited.push('fillOpacity');\n    o.fillOpacity = extractOpacity(fillOpacity);\n  }\n  if (fillRule != null) {\n    inherited.push('fillRule');\n    o.fillRule = fillRule && fillRules[fillRule] === 0 ? 0 : 1;\n  }\n}\n","import type { NumberProp } from './types';\n\nexport default function extractOpacity(opacity: NumberProp | void) {\n  const value =\n    typeof opacity === 'string' && opacity.trim().endsWith('%')\n      ? +opacity.slice(0, -1) / 100\n      : +opacity;\n  return isNaN(value) || value > 1 ? 1 : Math.max(value, 0);\n}\n","import extractBrush from './extractBrush';\nimport extractOpacity from './extractOpacity';\nimport extractLengthList from './extractLengthList';\nimport type { extractedProps, StrokeProps } from './types';\n\nconst caps = {\n  butt: 0,\n  square: 2,\n  round: 1,\n};\n\nconst joins = {\n  miter: 0,\n  bevel: 2,\n  round: 1,\n};\n\nconst vectorEffects = {\n  none: 0,\n  default: 0,\n  nonScalingStroke: 1,\n  'non-scaling-stroke': 1,\n  inherit: 2,\n  uri: 3,\n};\n\nexport default function extractStroke(\n  o: extractedProps,\n  props: StrokeProps,\n  inherited: string[]\n) {\n  const {\n    stroke,\n    strokeOpacity,\n    strokeLinecap,\n    strokeLinejoin,\n    strokeDasharray,\n    strokeWidth,\n    strokeDashoffset,\n    strokeMiterlimit,\n    vectorEffect,\n  } = props;\n\n  if (stroke != null) {\n    inherited.push('stroke');\n    o.stroke = extractBrush(stroke);\n  }\n  if (strokeWidth != null) {\n    inherited.push('strokeWidth');\n    o.strokeWidth = strokeWidth;\n  }\n  if (strokeOpacity != null) {\n    inherited.push('strokeOpacity');\n    o.strokeOpacity = extractOpacity(strokeOpacity);\n  }\n  if (strokeDasharray != null) {\n    inherited.push('strokeDasharray');\n    const strokeDash =\n      !strokeDasharray || strokeDasharray === 'none'\n        ? null\n        : extractLengthList(strokeDasharray);\n    o.strokeDasharray =\n      strokeDash && strokeDash.length % 2 === 1\n        ? strokeDash.concat(strokeDash)\n        : strokeDash;\n  }\n  if (strokeDashoffset != null) {\n    inherited.push('strokeDashoffset');\n    o.strokeDashoffset =\n      strokeDasharray && strokeDashoffset ? +strokeDashoffset || 0 : null;\n  }\n  if (strokeLinecap != null) {\n    inherited.push('strokeLinecap');\n    o.strokeLinecap = (strokeLinecap && caps[strokeLinecap]) || 0;\n  }\n  if (strokeLinejoin != null) {\n    inherited.push('strokeLinejoin');\n    o.strokeLinejoin = (strokeLinejoin && joins[strokeLinejoin]) || 0;\n  }\n  if (strokeMiterlimit != null) {\n    inherited.push('strokeMiterlimit');\n    o.strokeMiterlimit =\n      (strokeMiterlimit && typeof strokeMiterlimit !== 'number'\n        ? parseFloat(strokeMiterlimit)\n        : strokeMiterlimit) || 4;\n  }\n  if (vectorEffect != null) {\n    o.vectorEffect = (vectorEffect && vectorEffects[vectorEffect]) || 0;\n  }\n}\n","import type { NumberProp } from './types';\n\nconst spaceReg = /\\s+/;\nconst commaReg = /,/g;\n\nexport default function extractLengthList(\n  lengthList?: readonly NumberProp[] | NumberProp\n): readonly NumberProp[] {\n  if (Array.isArray(lengthList)) {\n    return lengthList as NumberProp[];\n  } else if (typeof lengthList === 'number') {\n    return [lengthList];\n  } else if (typeof lengthList === 'string') {\n    return lengthList.trim().replace(commaReg, ' ').split(spaceReg);\n  } else {\n    return [];\n  }\n}\n","import type { TransformsStyle } from 'react-native';\nimport { append, appendTransform, identity, reset, toArray } from '../Matrix2D';\nimport { parse } from './transform';\nimport { parse as parseTransformSvgToRnStyle } from './transformToRn';\nimport type {\n  ColumnMajorTransformMatrix,\n  NumberProp,\n  TransformedProps,\n  TransformProps,\n} from './types';\n\nexport type TransformsStyleArray = Exclude<\n  TransformsStyle['transform'],\n  string\n>;\n\nfunction appendTransformProps(props: TransformedProps) {\n  const { x, y, originX, originY, scaleX, scaleY, rotation, skewX, skewY } =\n    props;\n  appendTransform(\n    x + originX,\n    y + originY,\n    scaleX,\n    scaleY,\n    rotation,\n    skewX,\n    skewY,\n    originX,\n    originY\n  );\n}\n\nfunction universal2axis(\n  universal: NumberProp | NumberProp[] | undefined,\n  axisX: NumberProp | void,\n  axisY: NumberProp | void,\n  defaultValue?: number\n): [number, number] {\n  let x;\n  let y;\n  if (typeof universal === 'number') {\n    x = y = universal;\n  } else if (typeof universal === 'string') {\n    const coords = universal.split(/\\s*,\\s*/);\n    if (coords.length === 2) {\n      x = +coords[0];\n      y = +coords[1];\n    } else if (coords.length === 1) {\n      x = y = +coords[0];\n    }\n  } else if (Array.isArray(universal)) {\n    if (universal.length === 2) {\n      x = +universal[0];\n      y = +universal[1];\n    } else if (universal.length === 1) {\n      x = y = +universal[0];\n    }\n  }\n\n  axisX = +axisX;\n  if (!isNaN(axisX)) {\n    x = axisX;\n  }\n\n  axisY = +axisY;\n  if (!isNaN(axisY)) {\n    y = axisY;\n  }\n\n  return [x || defaultValue || 0, y || defaultValue || 0];\n}\n\nexport function transformsArrayToProps(\n  transformObjectsArray: TransformsStyleArray\n) {\n  const props: TransformProps = {};\n  transformObjectsArray?.forEach((transformObject) => {\n    const keys = Object.keys(transformObject);\n    if (keys.length !== 1) {\n      console.error(\n        'You must specify exactly one property per transform object.'\n      );\n    }\n    const key = keys[0] as keyof TransformProps;\n    const value = transformObject[key as keyof typeof transformObject];\n    // @ts-expect-error FIXME\n    props[key] = value;\n  });\n  return props;\n}\n\nexport function props2transform(\n  props: TransformProps | undefined\n): TransformedProps | null {\n  if (!props) {\n    return null;\n  }\n  const {\n    rotation,\n    translate,\n    translateX,\n    translateY,\n    origin,\n    originX,\n    originY,\n    scale,\n    scaleX,\n    scaleY,\n    skew,\n    skewX,\n    skewY,\n    x,\n    y,\n  } = props;\n  if (\n    rotation == null &&\n    translate == null &&\n    translateX == null &&\n    translateY == null &&\n    origin == null &&\n    originX == null &&\n    originY == null &&\n    scale == null &&\n    scaleX == null &&\n    scaleY == null &&\n    skew == null &&\n    skewX == null &&\n    skewY == null &&\n    x == null &&\n    y == null\n  ) {\n    return null;\n  }\n\n  if (Array.isArray(x) || Array.isArray(y)) {\n    console.warn(\n      'Passing SvgLengthList to x or y attribute where SvgLength expected'\n    );\n  }\n  const tr = universal2axis(\n    translate,\n    translateX || (Array.isArray(x) ? x[0] : x),\n    translateY || (Array.isArray(y) ? y[0] : y)\n  );\n  const or = universal2axis(origin, originX, originY);\n  const sc = universal2axis(scale, scaleX, scaleY, 1);\n  const sk = universal2axis(skew, skewX, skewY);\n\n  return {\n    rotation: rotation == null ? 0 : +rotation || 0,\n    originX: or[0],\n    originY: or[1],\n    scaleX: sc[0],\n    scaleY: sc[1],\n    skewX: sk[0],\n    skewY: sk[1],\n    x: tr[0],\n    y: tr[1],\n  };\n}\n\nexport function transformToMatrix(\n  props: TransformedPro