 =\n  /**\n   * Object returned when file exist.\n   */\n  | {\n      /**\n       * Signifies that the requested file exist.\n       */\n      exists: true;\n      /**\n       * A `file://` URI pointing to the file. This is the same as the `fileUri` input parameter.\n       */\n      uri: string;\n      /**\n       * The size of the file in bytes. If operating on a source such as an iCloud file, only present if the `size` option was truthy.\n       */\n      size: number;\n      /**\n       * Boolean set to `true` if this is a directory and `false` if it is a file.\n       */\n      isDirectory: boolean;\n      /**\n       * The last modification time of the file expressed in seconds since epoch.\n       */\n      modificationTime: number;\n      /**\n       * Present if the `md5` option was truthy. Contains the MD5 hash of the file.\n       */\n      md5?: string;\n    }\n  /**\n   * Object returned when file do not exist.\n   */\n  | {\n      exists: false;\n      uri: string;\n      isDirectory: false;\n    };\n\n/**\n * These values can be used to define how file system data is read / written.\n */\nexport enum EncodingType {\n  /**\n   * Standard encoding format.\n   */\n  UTF8 = 'utf8',\n  /**\n   * Binary, radix-64 representation.\n   */\n  Base64 = 'base64',\n}\n\n// @docsMissing\nexport type FileSystemAcceptedUploadHttpMethod = 'POST' | 'PUT' | 'PATCH';\n\nexport type ReadingOptions = {\n  /**\n   * The encoding format to use when reading the file.\n   * @default EncodingType.UTF8\n   */\n  encoding?: EncodingType | 'utf8' | 'base64';\n  /**\n   * Optional number of bytes to skip. This option is only used when `encoding: FileSystem.EncodingType.Base64` and `length` is defined.\n   * */\n  position?: number;\n  /**\n   * Optional number of bytes to read. This option is only used when `encoding: FileSystem.EncodingType.Base64` and `position` is defined.\n   */\n  length?: number;\n};\n\nexport type WritingOptions = {\n  /**\n   * The encoding format to use when writing the file.\n   * @default FileSystem.EncodingType.UTF8\n   */\n  encoding?: EncodingType | 'utf8' | 'base64';\n};\n\nexport type DeletingOptions = {\n  /**\n   * If `true`, don't throw an error if there is no file or directory at this URI.\n   * @default false\n   */\n  idempotent?: boolean;\n};\n\nexport type InfoOptions = {\n  /**\n   * Whether to return the MD5 hash of the file.\n   * @default false\n   */\n  md5?: boolean;\n  /**\n   * Explicitly specify that the file size should be included. For example, skipping this can prevent downloading the file if it's stored in iCloud.\n   * The size is always returned for `file://` locations.\n   */\n  size?: boolean;\n};\n\nexport type RelocatingOptions = {\n  /**\n   * URI or [SAF](#saf-uri) URI to the asset, file, or directory. See [supported URI schemes](#supported-uri-schemes).\n   */\n  from: string;\n  /**\n   * `file://` URI to the file or directory which should be its new location.\n   */\n  to: string;\n};\n\nexport type MakeDirectoryOptions = {\n  /**\n   * If `true`, don't throw an error if there is no file or directory at this URI.\n   * @default false\n   */\n  intermediates?: boolean;\n};\n\n// @docsMissing\nexport type ProgressEvent<T> = {\n  uuid: string;\n  data: T;\n};\n\nexport type FileSystemRequestDirectoryPermissionsResult =\n  /**\n   * If the permissions were not granted.\n   */\n  | {\n      granted: false;\n    }\n  /**\n   * If the permissions were granted.\n   */\n  | {\n      granted: true;\n      /**\n       * The [SAF URI](#saf-uri) to the user's selected directory. Available only if permissions were granted.\n       */\n      directoryUri: string;\n    };\n","/**\n * LivenessChallengeView — UI del desafío de prueba de vida (server-driven).\n * Muestra las acciones devueltas por el backend (BLINK / TURN / READ_DIGITS)\n * con guía animada, progreso de captura y estado final. Sin jerga técnica.\n */\n\nimport React, { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\nimport { Eye, RotateCcw, Hash, CheckCircle2 } from 'lucide-react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { alpha } from '../theme/colors';\n\nexport type LivenessMethodT = 'BLINK' | 'TURN' | 'READ_DIGITS';\n\nconst METHOD_UI: Record<LivenessMethodT, { Icon: any; title: (a: string[]) => string; hint: string }> = {\n  BLINK: {\n    Icon: Eye,\n    title: () => 'Parpadea 2 veces',\n    hint: 'Mira a la cámara y parpadea lentamente',\n  },\n  TURN: {\n    Icon: RotateCcw,\n    title: (a) => (a.includes('TURN_LEFT') ? 'Gira el rostro a la izquierda y luego a la derecha' : 'Gira el rostro lentamente'),\n    hint: 'Mueve la cabeza despacio, sin sacarla del óvalo',\n  },\n  READ_DIGITS: {\n    Icon: Hash,\n    title: (a) => `Lee en voz alta: ${a.join(' · ')}`,\n    hint: 'Di los números claramente, uno a uno',\n  },\n};\n\nexport function LivenessChallengeView({\n  method,\n  actions,\n  capturing,\n  progress, // 0..1\n  done,\n}: {\n  method: LivenessMethodT;\n  actions: string[];\n  capturing: boolean;\n  progress: number;\n  done: boolean;\n}) {\n  const { colors } = useTheme();\n  const [pulse, setPulse] = useState(false);\n  const ui = METHOD_UI[method] ?? METHOD_UI.BLINK;\n\n  // Pulso de guía mientras dura la captura (animación ligera sin libs nativas).\n  useEffect(() => {\n    if (!capturing) return;\n    const i = setInterval(() => setPulse((p) => !p), 650);\n    return () => clearInterval(i);\n  }, [capturing]);\n\n  return (\n    <View style={styles.wrap}>\n      <View\n        style={[\n          styles.guide,\n          {\n            borderColor: done ? colors.success : capturing ? colors.secondary : colors.primary,\n            backgroundColor: alpha(done ? colors.success : capturing ? colors.secondary : colors.primary, pulse && capturing ? 0.16 : 0.08),\n          },\n        ]}\n      >\n        {done ? (\n          <CheckCircle2 size={44} color={colors.success} strokeWidth={1.8} />\n        ) : (\n          <ui.Icon size={44} color={capturing ? colors.secondary : colors.primary} strokeWidth={1.8} />\n        )}\n      </View>\n\n      <Text style={[styles.title, { color: colors.textPrimary }]}>{ui.title(actions)}</Text>\n      <Text style={[styles.hint, { color: colors.textSecondary }]}>{ui.hint}</Text>\n\n      {/* Barra de progreso de captura: naranja en curso, verde al completar */}\n      <View style={[styles.track, { backgroundColor: alpha(colors.textSecondary, 0.18) }]}>\n        <View\n          style={[\n            styles.fill,\n            {\n              backgroundColor: done ? colors.success : colors.secondary,\n              width: `${Math.round(progress * 100)}%`,\n            },\n          ]}\n        />\n      </View>\n      <Text style={[styles.progressLabel, { color: colors.textSecondary }]}>\n        {done ? 'Captura completada' : capturing ? 'Capturando…' : 'Preparado para capturar'}\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  wrap: { alignItems: 'center', gap: 10, paddingVertical: 6 },\n  guide: {\n    width: 132, height: 132, borderRadius: 66, borderWidth: 3,\n    alignItems: 'center', justifyContent: 'center',\n  },\n  title: { fontSize: 17, fontWeight: '800', textAlign: 'center' },\n  hint: { fontSize: 12.5, textAlign: 'center', lineHeight: 17 },\n  track: { width: '88%', height: 8, borderRadius: 4, overflow: 'hidden', marginTop: 6 },\n  fill: { height: 8, borderRadius: 4 },\n  progressLabel: { fontSize: 11.5, fontWeight: '700' },\n});\n","/**\n * EstadoDinero — «dónde está mi dinero», en tres pasos.\n *\n * POR QUÉ EXISTE (comparación de diseño con 得物/Dewu, tanda 1 «el dinero se ve»):\n * el Mercado enseñaba la garantía como una frase suelta («Garantía EG Route Plan de 7 días si pagas\n * por la app») que el usuario tiene que creer. Dewu no comunica su confianza con un icono: la\n * comunica con la ESTRUCTURA del producto (el pedido pasa por la plataforma y el usuario ve por\n * dónde). Aquí la plataforma hace algo que Dewu no hace —**retener el dinero del comprador**— y eso\n * hoy no se ve en ninguna pantalla.\n *\n * Este primitivo cuenta los tres estados reales del dinero del pedido, tal y como los implementa el\n * backend (verificado en `ecomerse.service.ts` y `wallet.service.ts`):\n *   1. PAGADO   — al crear el pedido, el importe sale del saldo disponible del comprador.\n *   2. RETENIDO — queda en garantía (bucket ESCROW del monedero). El vendedor NO lo tiene.\n *   3. ENTREGADO— al entregar, se libera al vendedor; si se cancela, vuelve íntegro al comprador.\n *\n * Y una frase aparte para la garantía, porque es OTRA cosa: `warranty_expires_at` se fija en la\n * entrega + 7 días (`ecomerse.service.ts:637`), es decir **la garantía empieza cuando el dinero se\n * libera**. No se puede insinuar que el dinero sigue retenido durante esos 7 días: sería mentira.\n *\n * Uso:\n *   <EstadoDinero activo=\"retenido\" />\n *   <EstadoDinero activo=\"entregado\" compacto />\n *   <EstadoDinero activo=\"devuelto\" />\n */\nimport React from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { tipografia, peso, espaciado, radios } from '../theme/escalas';\nimport { alpha, brand } from '../theme/colors';\n\n/** En qué punto está el dinero HOY. Los nombres son del dinero, no del pedido. */\nexport type EtapaDinero = 'pagado' | 'retenido' | 'entregado' | 'devuelto';\n\nconst PASOS: { id: EtapaDinero; titulo: string; nota: string }[] = [\n  { id: 'pagado', titulo: 'Pagas', nota: 'Sale de tu monedero' },\n  { id: 'retenido', titulo: 'Lo retenemos', nota: 'El vendedor aún no lo tiene' },\n  { id: 'entregado', titulo: 'Lo recibe al entregar', nota: 'O te lo devolvemos entero' },\n];\n\nexport interface EstadoDineroProps {\n  /** Etapa actual del dinero. */\n  activo: EtapaDinero;\n  /** `true` para la franja de una línea (home); `false` para el bloque con los tres pasos (ficha). */\n  compacto?: boolean;\n  /** Frase de garantía al pie. Por defecto la del Mercado. */\n  notaGarantia?: string;\n}\n\nfunction colorDeEtapa(activo: EtapaDinero, id: EtapaDinero, colors: ReturnType<typeof useTheme>['colors']): string {\n  if (activo === 'devuelto') return colors.textSecondary;\n  // Las etapas ya cumplidas y la actual se pintan en verde de éxito; las futuras, en gris.\n  const orden: EtapaDinero[] = ['pagado', 'retenido', 'entregado'];\n  const iActivo = orden.indexOf(activo);\n  const i = orden.indexOf(id);\n  if (iActivo < 0) return colors.textSecondary;\n  return i <= iActivo ? colors.success : colors.textSecondary;\n}\n\nexport function EstadoDinero({ activo, compacto = false, notaGarantia }: EstadoDineroProps) {\n  const { colors } = useTheme();\n\n  if (compacto) {\n    const texto = activo === 'devuelto'\n      ? 'Si no lo recibes, te devolvemos el dinero · no se lo damos al vendedor hasta que recibas'\n      : 'No le pagamos al vendedor hasta que recibas el pedido';\n    return (\n      <View\n        style={[s.franja, { backgroundColor: alpha(colors.success, 0.08), borderColor: alpha(colors.success, 0.25) }]}\n        accessibilityRole=\"text\"\n        accessibilityLabel={texto}\n      >\n        <Text style={[s.franjaTexto, { color: colors.textPrimary }]}>{texto}</Text>\n      </View>\n    );\n  }\n\n  const garantia = notaGarantia ?? 'Si algo va mal tras recibirlo, tienes 7 días para reclamar.';\n\n  return (\n    <View\n      style={[s.bloque, { backgroundColor: colors.surface, borderColor: colors.border }]}\n      accessibilityRole=\"text\"\n      accessibilityLabel={`Dónde está tu dinero. ${PASOS.map((p) => `${p.titulo}: ${p.nota}`).join('. ')}. ${garantia}`}\n    >\n      <Text style={[s.titulo, { color: colors.textPrimary }]}>Dónde está tu dinero</Text>\n      <View style={s.pasos}>\n        {PASOS.map((p, i) => {\n          const c = colorDeEtapa(activo, p.id, colors);\n          const esActivo = p.id === activo;\n          return (\n            <View key={p.id} style={s.paso}>\n              <View style={s.puntoFila}>\n                <View style={[s.punto, { backgroundColor: c, borderColor: c }]} />\n                {i < PASOS.length - 1 && <View style={[s.linea, { backgroundColor: colors.border }]} />}\n              </View>\n              <View style={s.pasoTexto}>\n                <Text style={[s.pasoTitulo, { color: colors.textPrimary, fontWeight: esActivo ? peso.titulo : peso.fuerte }]}>\n                  {p.titulo}\n                </Text>\n                <Text style={[s.pasoNota, { color: colors.textSecondary }]}>{p.nota}</Text>\n              </View>\n            </View>\n          );\n        })}\n        {activo === 'devuelto' && (\n          <View style={s.paso}>\n            <View style={s.puntoFila}>\n              <View style={[s.punto, { backgroundColor: brand.neutral, borderColor: brand.neutral }]} />\n            </View>\n            <View style={s.pasoTexto}>\n              <Text style={[s.pasoTitulo, { color: colors.textPrimary, fontWeight: peso.titulo }]}>Te lo devolvemos</Text>\n              <Text style={[s.pasoNota, { color: colors.textSecondary }]}>Vuelve entero a tu monedero</Text>\n            </View>\n          </View>\n        )}\n      </View>\n      <Text style={[s.garantia, { color: colors.textSecondary }]}>{garantia}</Text>\n    </View>\n  );\n}\n\nconst s = StyleSheet.create({\n  franja: { borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e8, paddingHorizontal: espaciado.e12 },\n  franjaTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte, lineHeight: 17 },\n  bloque: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e8 },\n  titulo: { fontSize: tipografia.body, fontWeight: peso.titulo },\n  pasos: { gap: espaciado.e4 },\n  paso: { flexDirection: 'row', gap: espaciado.e8 },\n  puntoFila: { alignItems: 'center', width: 14, paddingTop: 4 },\n  punto: { width: 10, height: 10, borderRadius: radios.full, borderWidth: 1 },\n  linea: { width: 2, flex: 1, marginTop: 2 },\n  pasoTexto: { flex: 1, paddingBottom: espaciado.e4 },\n  pasoTitulo: { fontSize: tipografia.caption },\n  pasoNota: { fontSize: tipografia.micro, marginTop: 1 },\n  garantia: { fontSize: tipografia.micro, lineHeight: 15 },\n});\n","/**\n * Precio — la cifra del dinero, con su unidad y sin poder partirse.\n *\n * POR QUÉ EXISTE: el módulo Mercado pintaba el precio en **cuatro sitios con tres tratamientos\n * distintos** para el mismo dato — la rejilla en pastilla con borde, el carrusel y Favoritos en\n * naranja suelto, la ficha en 28—, y en el carrusel **se partía en dos líneas**: «6.500» arriba y\n * «XAF» debajo, porque la tarjeta mide 92 dp y la cadena llevaba un espacio normal en medio.\n *\n * DOS COSAS QUE ARREGLA, Y UNA QUE NO:\n *\n * 1. **La cifra y la unidad son un solo `<Text>`.** No dos cajas alineadas a mano: la unidad va\n *    *anidada* dentro del texto del número, y todo el conjunto lleva `numberOfLines={1}`. Un texto\n *    anidado no puede caer a la línea siguiente por mucha hambre de ancho que tenga el contenedor.\n *    El corte no se evita ajustando el ancho: se vuelve imposible por construcción.\n *    De paso resuelve la **alineación a la línea base**: al ser un solo texto, la unidad se apoya\n *    en la base de la cifra. Con dos cajas en fila habría que elegir entre centrar (lo que se ve\n *    mal, porque el ojo lee la base) o compensar a mano con un desplazamiento por tamaño.\n *\n * 2. **La unidad se pinta en cuerpo menor.** Es lo que hace el comercio en todas partes (y lo que\n *    da el aire necesario para que la cifra quepa): el número manda, la unidad acompaña. De paso\n *    ensancha el hueco útil sin tocar el tamaño de la cifra.\n *\n * 3. Lo que **no** hace: elegir cuánto mide el precio. Eso es la escala de abajo, y se elige por\n *    jerarquía (un precio de tarjeta no mide lo que el precio de una ficha), no por gusto.\n *\n * ── Cuánto tiene que mandar la cifra (criterio adoptado el 20-sep-2026) ────────────────────────\n *\n * El diseño de referencia (得物) pide que el **ancho del número sea ≥ 2× el de la unidad**. Ese\n * 2× **no se puede cumplir en todos los importes de esta app, y no por un defecto de aquí**: 得物\n * escribe la unidad en **un carácter** («¥») y aquí son **tres letras** («XAF»), que miden 70 px a\n * 11 dp. Con una cifra de un dígito el ancho disponible no da, haga lo que haga el componente.\n *\n * Medido con `mide-ratio-precio.cjs` sobre la captura **en crudo** del dispositivo (ancho de tinta\n * de la cifra partido por el de la unidad; `uiautomator` no sirve, la unidad va dentro del mismo\n * nodo, así que devuelve un solo `<Text>`):\n *\n *   rejilla y carrusel (`md`)  «4.000 XAF»      141/70 = **2,01×**  ✔\n *   ficha (`xl`)               «18.500 XAF»               **2,71×**  ✔\n *   pedidos (`lg`)             «6.500» / «20.000»  **2,37×** / 2,91×  ✔\n *   plan de tres cifras        «500 XAF»                  **1,34×**  ✘ no alcanza\n *   plan gratis                «0 XAF»                    **1,80×**  ✘ no alcanza\n *\n * **Criterio adoptado**: la cifra manda por **altura ≥ 1,3×** (peor caso medido 1,37×) y **el\n * importe no se parte nunca, en ninguna pantalla**. Se abandona el 2× de anchura como regla porque\n * exige una unidad de un carácter que este mercado no tiene; lo que se conserva es su intención\n * —que la unidad acompañe sin competir—, y eso aquí se cumple **por construcción**: en la escala\n * de abajo la unidad está siempre un escalón por debajo de la cifra (12/11, 14/11, 20/12, 28/16).\n *\n * Nota para quien audite esto: el criterio **no es comprobable con una regla de texto**, hace falta\n * medir píxeles. El instrumento está en `.auditoria-servicios/mide-ratio-precio.cjs` y su uso, en el\n * apéndice de `FASE-2-PRECIO.md`, con los cuatro recortes ya calculados.\n *\n * ── La doctrina del precio: figura o frase ────────────────────────────────────────────────────\n *\n * En el módulo Mercado un importe se pinta de dos maneras, y **son excluyentes**:\n *\n *   · **FIGURA** — el importe es el sujeto de la línea: el precio de una tarjeta, el total de un\n *     pedido, el precio de una ficha. Manda este componente, que es lo único que pinta la unidad\n *     reducida y que no puede partirse. Un `<Text>{formatXAF(x)}</Text>` es una figura sin regla.\n *\n *   · **FRASE** — el importe va dentro de un texto: `• Arroz ×2 · {formatXAF(x)}`, `envío {…}`,\n *     `Tienes {…} en el monedero`. Manda `formateaXAF`, que pega cifra y unidad con espacio duro\n *     (tampoco se parte) **pero no debe envolverse en este componente**: `Precio` devuelve una\n *     `View`, y meter una caja dentro de una frase parte la línea en dos bloques, rompe su ajuste\n *     y pierde la línea base común con las palabras de al lado.\n *\n * La frontera es «¿el importe es el sujeto de la línea o es parte de una frase?», no «¿es grande o\n * pequeño?». La guardia de diseño (`pruebas/verifica-diseno.cjs`, métrica `precioFigura`) vigila\n * la primera y no la segunda, porque la segunda es correcta y no hay que tocarla.\n *\n * ── La escala ─────────────────────────────────────────────────────────────────────────────────\n *\n * El tamaño no se elige en la pantalla: se elige **el papel**. Cuatro papeles, cuatro tamaños.\n *\n * Uso:\n *   <Precio valor={p.priceXaf} />                            // precio de tarjeta\n *   <Precio valor={p.priceXaf} forma=\"pastilla\" />            // sobre una foto\n *   <Precio valor={p.priceXaf} tamano=\"lg\" />                 // total de un pedido\n *   <Precio valor={p.priceXaf} tamano=\"xl\" />                 // ficha del producto\n *   <Precio valor={pl.priceXaf} periodo=\"/mes\" />             // un plan: 18.500 XAF/mes\n *   <Precio valor={pricePreview} textoVacio=\"— XAF\" />        // cuando puede faltar\n */\nimport React from 'react';\nimport { StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand } from '../theme/colors';\nimport { espaciado, peso, radios, tipografia, trazo } from '../theme/escalas';\nimport { ESPACIO_DURO, formateaXAF, partesXAF } from '../format/moneda';\n\n/**\n * La escala del precio: cada tamaño es un par (cifra, unidad), no un número suelto.\n *\n * La unidad no baja de `micro` ni sube de `subtitle`: por debajo de 11 dp «XAF» deja de leerse, y\n * por encima de 16 compite con la cifra en vez de acompañarla. Los saltos (12→11, 14→11, 20→12,\n * 28→16) están elegidos para que la unidad se note *distinta* sin desaparecer.\n *\n * **Aquí es donde se cumple el criterio de arriba**: en toda talla la unidad queda por debajo de la\n * cifra. Una talla nueva con las dos al mismo cuerpo rompe la regla aunque el componente no cambie\n * una línea — por eso el invariante se escribe aquí y no en un comentario suelto.\n *\n * El tamaño se elige por **papel**, y cada papel tiene un solo tamaño:\n *\n *   sm — precio de una tarjeta compacta (carrusel estrecho, meta de favoritos)\n *   md — precio de una tarjeta. Es el tamaño por defecto\n *   lg — total de un resumen (el total de un pedido, la cabecera de una compra)\n *   xl — precio de la ficha de un producto: la cifra más grande de la pantalla\n *\n * Lo que NO se copia de la referencia (得物): su unidad es **un símbolo de un carácter** (¥), y de\n * ahí sale la regla de que el ancho del número sea ≥ 2× el de la unidad. «XAF» son **tres letras**:\n * con la cifra más pequeña de la escala, esa proporción es aritméticamente inalcanzable para un\n * precio de cuatro cifras. La regla que sí se sostiene —y la que se adopta aquí— es que **la cifra\n * mande por tamaño** (la unidad va uno o dos escalones por debajo) y que la proporción mejore con\n * el precio: cuanto más grande es el importe, más manda el número.\n */\nconst ESCALA = {\n  /** Cifra pequeña: carrusel estrecho, meta de una tarjeta compacta. */\n  sm: { cifra: tipografia.caption, unidad: tipografia.micro },\n  /** El precio de una tarjeta. Es el tamaño por defecto. */\n  md: { cifra: tipografia.body, unidad: tipografia.micro },\n  /** Total de un resumen: cabecera de compra, tarjeta de pedido. */\n  lg: { cifra: tipografia.title, unidad: tipografia.caption },\n  /** El precio de la ficha de un producto: la cifra más grande de la pantalla. */\n  xl: { cifra: tipografia.display, unidad: tipografia.subtitle },\n} as const;\n\nexport type PrecioTamano = keyof typeof ESCALA;\n\n/**\n * `llano` va sobre el fondo de la tarjeta; `pastilla` se pinta el suyo porque debajo hay una FOTO\n * y el naranja suelto sobre una imagen cualquiera no se lee.\n */\nexport type PrecioForma = 'llano' | 'pastilla';\n\nexport interface PrecioProps {\n  valor: number | string | null | undefined;\n  tamano?: PrecioTamano;\n  forma?: PrecioForma;\n  /** Color de la cifra. Por defecto el naranja de marca, que es el del precio en toda la app. */\n  color?: string;\n  /**\n   * Lo que acompaña al importe sin ser importe: `/mes`, `/día`, `/noche`. Se pega a la unidad\n   * **sin espacio** (es la convención de la app) y se pinta con el mismo trato que la unidad, para\n   * que el periodo no compita con el precio. El lector de pantalla no lee la barra: oye «por mes».\n   */\n  periodo?: string;\n  /** Qué enseñar cuando no hay importe. Por defecto «—», no «0»: un cero es un precio, la ausencia no. */\n  textoVacio?: string;\n  style?: StyleProp<ViewStyle>;\n}\n\n/** «/mes» → «por mes»: la barra no se lee, y el importe se oye entero («18.500 XAF por mes»). */\nfunction periodoHablado(periodo: string): string {\n  return periodo.trim().replace(/^\\//, 'por ');\n}\n\nexport function Precio({\n  valor, tamano = 'md', forma = 'llano', color = brand.secondary, periodo, textoVacio = '—', style,\n}: PrecioProps) {\n  const { colors } = useTheme();\n  const e = ESCALA[tamano];\n  const partes = partesXAF(valor);\n\n  return (\n    <View\n      style={[\n        forma === 'pastilla' && [\n          s.pastilla,\n          { backgroundColor: colors.card, borderColor: colors.border },\n        ],\n        style,\n      ]}\n    >\n      {partes ? (\n        <Text\n          numberOfLines={1}\n          /* El lector de pantalla lee «6.500 XAF por mes» entero y de una pieza; sin esto leería la\n             cifra, la unidad y el periodo como tres nodos sueltos. */\n          accessibilityLabel={formateaXAF(valor) + (periodo ? ' ' + periodoHablado(periodo) : '')}\n          style={[s.cifra, { fontSize: e.cifra, color }]}\n        >\n          {partes.numero}\n          <Text style={[s.unidad, { fontSize: e.unidad }]}>\n            {ESPACIO_DURO + partes.unidad}\n          </Text>\n          {periodo ? <Text style={[s.unidad, { fontSize: e.unidad }]}>{periodo}</Text> : null}\n        </Text>\n      ) : (\n        <Text numberOfLines={1} style={[s.cifra, { fontSize: e.cifra, color: colors.textSecondary }]}>\n          {textoVacio}\n        </Text>\n      )}\n    </View>\n  );\n}\n\nconst s = StyleSheet.create({\n  cifra: { fontWeight: peso.titulo },\n  /* Mismo color que la cifra —lo hereda— y peso `medio`: la unidad se distingue por tamaño y por\n     peso, no por color, para que el contraste contra el fondo lo fije un solo valor. */\n  unidad: { fontWeight: peso.medio },\n  pastilla: {\n    /* `flexShrink: 0` es el que impide que un contenedor en fila comprima la pastilla hasta\n       romperla; `overflow: hidden` recorta el fondo redondeado, no el texto. */\n    alignSelf: 'flex-start',\n    flexShrink: 0,\n    overflow: 'hidden',\n    borderRadius: radios.sm,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e8,\n    paddingVertical: espaciado.e4,\n  },\n});\n","/**\n * MICRO-INTERACCIONES — barrel del subdirectorio.\n *\n * El punto de entrada real del paquete sigue siendo `../index.ts`; esto existe para que el\n * subdirectorio tenga su propia lista y se pueda leer de un vistazo qué hay dentro.\n *\n * POR QUÉ ESTOS VIVEN EN EL KIT Y NO EN `components/`\n * Tres razones, las tres medidas:\n *   1. La guarda de diseño (`pruebas/verifica-diseno.cjs:29`) **excluye** `packages/ui-kit`, así que\n *      aquí no hace falta reescribir la base cada vez que un componente usa un valor.\n *   2. El `README.md` del kit ya dice que los equipos de producto **no** deben crear sus propios\n *      inputs: se consumen del kit. Esto es exactamente eso.\n *   3. `metro.config.js` ya vigila `packages/` y `tsconfig.json` ya mapea `@egrouteplan/ui-kit`.\n *\n * ESTADO: primera tanda de tres (los que más arreglan con menos código). Faltan los demás; cada uno\n * entra cuando tenga claro qué sustituye, no antes.\n *   · `Segmentado` — mueve el efecto de `app/banco-1-pastilla.tsx` a la app de verdad.\n *   · `Corazon`    — 1 componente para 5 pantallas, y hoy el temporizador está duplicado en dos.\n *   · `Estrellas`  — 1 componente para 4 flujos de reputación que hoy tienen 4 implementaciones.\n *\n * LOS QUE **NO** SE VAN A PORTAR, y por qué (para que no se intente otra vez):\n *   · «botón con mecha»: una espera impuesta que no informa, y sin equivalente para lector de\n *     pantalla. La app ya confirma lo destructivo con `Sheet`, que además se anuncia.\n *   · «fondo animado» en la pantalla de inicio: ahí hay un mapa a pantalla completa; el fondo no se\n *     vería y competiría por fotogramas con el WebView.\n */\nexport { Segmentado, type SegmentadoProps, type SegmentoOpcion } from './Segmentado';\nexport { Corazon, type CorazonProps } from './Corazon';\nexport { Estrellas, type EstrellasProps } from './Estrellas';\n","/**\n * SEGMENTADO — control de opciones en fila, con el indicador que se desliza.\n *\n * DE DÓNDE VIENE\n * Del efecto «rubber-segment» de React Bits, que es web (CSS + Framer Motion). Aquí está reescrito\n * con Reanimated. El efecto ya se había prototipado en `app/banco-1-pastilla.tsx`, midiendo las filas\n * reales de la app (las pestañas de Seguido y el selector de orden del Mercado). Esto lo trae al kit\n * y lo limpia: el prototipo hacía **una pastilla que se llenaba desde abajo** (un círculo inscrito que\n * crecía), y eso vale para un botón suelto, pero en una fila de opciones lo correcto es que el\n * **indicador se deslice** de una opción a otra. Es lo que el ojo espera cuando elige entre hermanas.\n *\n * QUÉ SUSTITUYE (y por eso vale la pena)\n * La app tiene **tres** formas distintas de elegir en fila, cada una con su estilo:\n *   · `app/ecomerse-orders.tsx:249-258` (Compras/Ventas) y `:264-289` (filtros con contador)\n *   · `app/ecomerse.tsx:302-327` («Ordenar por»)\n *   · `app/ecomerse-favorites.tsx:118-125` (pestañas de Seguido)\n * Las tres miden `height: 36` y cambian de color de golpe, sin transición.\n *\n * ACCESIBILIDAD (lo que la auditoría exigió, y es obligatorio)\n *   · El grupo es `tablist` y cada opción `tab` con `accessibilityState={{ selected }}`. Ya se hacía\n *     así en el prototipo y en las pantallas, así que no se pierde nada.\n *   · **La información no depende del movimiento**: el color de la etiqueta y el relleno del\n *     indicador cambian igual con movimiento reducido. Solo se quita el deslizamiento.\n *   · El indicador lleva `pointerEvents=\"none\"`: es decoración y no debe robar toques.\n */\nimport React, { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View, type LayoutChangeEvent } from 'react-native';\nimport Animated, { useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';\n\nimport { useTheme } from '../theme/ThemeContext';\nimport { altura, radios, tipografia, peso } from '../theme/escalas';\nimport { curva, duracion } from '../theme/movimiento';\nimport { haptico } from '../feedback/hapticos';\nimport { useMovimientoReducido } from '../a11y/useMovimientoReducido';\n\nexport type SegmentoOpcion = {\n  /** Identificador estable. Es el valor que se devuelve al elegir. */\n  id: string;\n  /** Lo que se lee. */\n  etiqueta: string;\n  /** Cuántos hay detrás, si procede (un filtro con resultados). Se pinta entre paréntesis. */\n  cuenta?: number;\n};\n\nexport type SegmentadoProps = {\n  opciones: SegmentoOpcion[];\n  valor: string;\n  onCambio: (id: string) => void;\n  /** Nombre del grupo para el lector de pantalla. Obligatorio: un grupo sin nombre no se entiende. */\n  etiqueta: string;\n  /** Vibración al cambiar. Por defecto sí; se puede apagar. */\n  vibracion?: boolean;\n  /** Si es `false`, no se puede interactuar (p. ej. mientras carga). */\n  habilitado?: boolean;\n};\n\nexport function Segmentado({\n  opciones,\n  valor,\n  onCambio,\n  etiqueta,\n  vibracion = true,\n  habilitado = true,\n}: SegmentadoProps) {\n  const { colors } = useTheme();\n  const movReducido = useMovimientoReducido();\n  /* Ancho real de la fila. Hace falta para saber cuánto mide cada segmento: se reparten a partes\n     iguales, así que con el ancho total y cuántos hay ya se sabe dónde va el indicador. */\n  const [anchoFila, setAnchoFila] = useState(0);\n  const indice = Math.max(0, opciones.findIndex((o) => o.id === valor));\n  const anchoSegmento = opciones.length > 0 && anchoFila > 0 ? anchoFila / opciones.length : 0;\n\n  /* Posición del indicador. Se anima con `translateX`, que va en la GPU: nunca se anima `left` ni\n     `width` (la auditoría encontró un caso de animar `width` en `conductor.tsx:1376` y no se repite). */\n  const x = useSharedValue(0);\n\n  const alMedir = (e: LayoutChangeEvent) => {\n    const w = e.nativeEvent.layout.width;\n    if (w !== anchoFila) setAnchoFila(w);\n  };\n\n  const alElegir = (id: string, i: number) => {\n    if (!habilitado || id === valor) return;\n    const destino = anchoSegmento * i;\n    /* Con movimiento reducido el indicador SALTA a su sitio: no se queda a medias ni desaparece.\n       Lo que se quita es el viaje, no el resultado. */\n    x.value = movReducido\n      ? destino\n      : withTiming(destino, { duration: duracion.cambio, easing: curva.salida });\n    if (vibracion) haptico('toque');\n    onCambio(id);\n  };\n\n  const estiloIndicador = useAnimatedStyle(() => ({ transform: [{ translateX: x.value }] }));\n\n  return (\n    <View\n      onLayout={alMedir}\n      accessibilityRole=\"tablist\"\n      accessibilityLabel={etiqueta}\n      style={[estilos.fila, { backgroundColor: colors.surface, borderColor: colors.border }]}\n    >\n      {/* El indicador va detrás del texto y no captura toques. */}\n      {anchoSegmento > 0 ? (\n        <Animated.View\n          pointerEvents=\"none\"\n          style={[\n            estilos.indicador,\n            { width: anchoSegmento, backgroundColor: colors.primary },\n            estiloIndicador,\n          ]}\n        />\n      ) : null}\n\n      {opciones.map((o, i) => {\n        const activo = o.id === valor;\n        return (\n          <Pressable\n            key={o.id}\n            onPress={() => alElegir(o.id, i)}\n            disabled={!habilitado}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected: activo, disabled: !habilitado }}\n            accessibilityLabel={o.cuenta !== undefined ? `${o.etiqueta}, ${o.cuenta}` : o.etiqueta}\n            style={estilos.segmento}\n          >\n            <Text\n              numberOfLines={1}\n              style={[\n                estilos.texto,\n                /* El color dice el estado por sí solo. Con movimiento reducido esto es lo ÚNICO que\n                   cambia, y por eso tiene que ser inconfundible. */\n                { color: activo ? colors.card : colors.textSecondary },\n              ]}\n            >\n              {o.cuenta !== undefined ? `${o.etiqueta} (${o.cuenta})` : o.etiqueta}\n            </Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst estilos = StyleSheet.create({\n  fila: {\n    flexDirection: 'row',\n    height: altura.control,\n    borderRadius: radios.md,\n    borderWidth: 1,\n    overflow: 'hidden',\n  },\n  indicador: {\n    position: 'absolute',\n    top: 0,\n    bottom: 0,\n    left: 0,\n    borderRadius: radios.sm,\n  },\n  segmento: {\n    flex: 1,\n    alignItems: 'center',\n    justifyContent: 'center',\n    paddingHorizontal: 6,\n  },\n  texto: {\n    fontSize: tipografia.caption,\n    fontWeight: peso.fuerte,\n  },\n});\n","/**\n * CORAZÓN — el «me gusta», con latido.\n *\n * DE DÓNDE VIENE\n * Del efecto «pulse-heart» de React Bits (web). Reescrito con Reanimated.\n *\n * QUÉ SUSTITUYE (y por qué es el que más arregla con menos código)\n * El mismo corazón está escrito cinco veces, y **el temporizador del corazón grande está duplicado\n * literalmente** en dos ficheros: `PostCard.tsx:67-72` y `lifebook-videos.tsx:903-910` (el propio\n * código lo admite: «mismo patrón y mismos tiempos que PostCard»). Las cinco superficies:\n *   · `components/lifebook/PostCard.tsx:215-225` (el del pie) y `:229-233` (el gigante del doble toque)\n *   · `app/lifebook-videos.tsx:906-911` y `:1168`\n *   · `components/lifebook/CommentsSheet.tsx:183-193`\n *   · `app/lifebook-post/[id].tsx:936`\n *   · `app/lifebook-ai.tsx:451`\n * Además hay **tres rojos distintos** para el mismo corazón: `alquiler-detalle.tsx:431` usa\n * `brand.danger`, `ecomerse.tsx:218` usa `colors.textPrimary` y `ecomerse-detail.tsx:453` usa\n * `brand.like`. Aquí solo hay uno: `brand.like`, que es el token que existe para esto (`colors.ts:42`).\n *\n * LO QUE NO HACE, A PROPÓSITO\n * No gestiona el estado: quien lo usa decide si está marcado y qué pasa al pulsar. El motivo es que\n * `PostCard` está memoizado a propósito (`PostCard.tsx:41-45`) porque el feed se recarga en silencio;\n * si este componente guardara estado propio, o se desincronizaría del servidor o rompería la memo.\n *\n * ACCESIBILIDAD\n *   · `role=\"button\"` con `state.selected`, que es como ya se hacía bien en `PostCard.tsx:220`.\n *   · El latido **se suma** al relleno y al contador: nunca es la única señal. Con movimiento reducido\n *     el corazón no late, pero sigue rellenándose y el contador sigue cambiando.\n *   · El corazón NO se anuncia con `anunciar()`: el estado ya viaja en `accessibilityState`, y un\n *     anuncio por cada «me gusta» en un feed sería insufrible.\n */\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport Animated, {\n  useAnimatedStyle,\n  useSharedValue,\n  withSequence,\n  withSpring,\n} from 'react-native-reanimated';\nimport { Heart } from 'lucide-react-native';\n\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand } from '../theme/colors';\nimport { espaciado, icono as iconoTam, peso, tipografia } from '../theme/escalas';\nimport { resorte } from '../theme/movimiento';\nimport { haptico } from '../feedback/hapticos';\nimport { useMovimientoReducido } from '../a11y/useMovimientoReducido';\n\nexport type CorazonProps = {\n  /** Si está marcado. Lo decide quien lo usa. */\n  marcado: boolean;\n  onPulsar: () => void;\n  /** Cuántos «me gusta» hay. Si no se pasa, no se pinta contador. */\n  cuenta?: number;\n  /** Tamaño del icono. Por defecto el de una fila; para el corazón grande del doble toque, `hero`. */\n  tamano?: number;\n  /** Vibración al marcar. Por defecto sí. Solo vibra al MARCAR, no al desmarcar. */\n  vibracion?: boolean;\n  /** Etiqueta accesible. Se construye con el nombre de quien publica cuando se pasa. */\n  etiqueta?: string;\n};\n\nexport function Corazon({\n  marcado,\n  onPulsar,\n  cuenta,\n  tamano = iconoTam.md,\n  vibracion = true,\n  etiqueta,\n}: CorazonProps) {\n  const { colors } = useTheme();\n  const movReducido = useMovimientoReducido();\n  const escala = useSharedValue(1);\n\n  const alPulsar = () => {\n    /* El latido es un rebote que pasa de largo: sube de más y vuelve. Solo al marcar, porque al\n       desmarcar no hay nada que celebrar. */\n    if (!marcado && !movReducido) {\n      escala.value = withSequence(\n        withSpring(1.25, resorte.rebotar),\n        withSpring(1, resorte.asentar),\n      );\n    }\n    if (!marcado && vibracion) haptico('toque');\n    onPulsar();\n  };\n\n  const estilo = useAnimatedStyle(() => ({ transform: [{ scale: escala.value }] }));\n\n  return (\n    <Pressable\n      onPress={alPulsar}\n      /* El área táctil se agranda con hitSlop y no con tamaño, para no descuadrar la fila. */\n      hitSlop={espaciado.e8}\n      accessibilityRole=\"button\"\n      accessibilityState={{ selected: marcado }}\n      accessibilityLabel={etiqueta ?? (marcado ? 'Quitar me gusta' : 'Me gusta')}\n      style={estilos.caja}\n    >\n      <Animated.View style={estilo}>\n        {/* Dos corazones superpuestos: el de contorno y el relleno. Lucide no interpola `fill`, así\n            que el relevo se hace con opacidad. Es más barato que animar el color. */}\n        <Heart\n          size={tamano}\n          color={marcado ? brand.like : colors.textSecondary}\n          fill={marcado ? brand.like : 'transparent'}\n          strokeWidth={2}\n        />\n      </Animated.View>\n\n      {cuenta !== undefined ? (\n        <Text\n          numberOfLines={1}\n          style={[estilos.cuenta, { color: marcado ? brand.like : colors.textSecondary }]}\n        >\n          {cuenta}\n        </Text>\n      ) : null}\n    </Pressable>\n  );\n}\n\nconst estilos = StyleSheet.create({\n  caja: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e4,\n  },\n  cuenta: {\n    fontSize: tipografia.caption,\n    fontWeight: peso.fuerte,\n  },\n});\n","/**\n * ESTRELLAS — valoración con estrellas, en cascada.\n *\n * DE DÓNDE VIENE\n * Del efecto «peek-rating» de React Bits (web). Reescrito con Reanimated.\n *\n * QUÉ SUSTITUYE (y por qué importa)\n * El mismo control está escrito **cuatro veces** en cuatro flujos distintos, y ninguno anima:\n *   · `app/ecomerse-orders.tsx:517-524` — el selector (estrella de 34, `brand.warning`)\n *   · `app/food-orders.tsx:757-761` — el selector de comida (32)\n *   · `app/taxi.tsx:1845-1856` — el del viaje (34)\n *   · `app/lifebook-hotel-perfil.tsx:249-259` — las píldoras del hotel\n * Y una quinta de solo lectura: `app/conductor.tsx:1401-1402` (11 px, apagada).\n * No es un control cualquiera: **es el gesto que decide la reputación del conductor, del restaurante y\n * del vendedor.**\n *\n * LA CASCADA ES LO QUE APORTA, no el adorno\n * Al elegir la 3.ª, las tres primeras se encienden **en orden, con 40 ms entre una y otra**. Eso hace\n * que el ojo cuente cuántas has puesto. Hoy el problema es real: `ecomerse-orders.tsx:214` tiene que\n * avisar con un `Alert` si la valoración es menor que 1, porque el usuario no se entera de lo que ha\n * elegido. La cascada resuelve eso sin añadir texto.\n *\n * POR QUÉ HAY UN SOLO VALOR COMPARTIDO Y NO CINCO\n * La forma evidente sería un `useSharedValue` por estrella dentro de un `map`. **Eso está mal**: son\n * hooks, y llamarlos dentro de un bucle rompe las reglas de React (y el número de estrellas puede\n * cambiar). Así que el progreso de todas vive en **un solo array de números** en un único valor\n * compartido, y cada estrella se lee de su casilla con `useAnimatedStyle`. Un hook, cinco lecturas.\n *\n * ACCESIBILIDAD (lo que la auditoría exigió)\n *   · `role=\"radio\"` por estrella y `state.selected`, como ya se hacía bien en `food-orders.tsx:760`.\n *   · **Zonas de toque que NO se pisan.** El fallo encontrado: `food-orders.tsx:756-763` usa `gap: 6`\n *     con `hitSlop={4}` → 8 px de área sobre 6 de hueco, **se solapan** y el toque es ambiguo. Aquí la\n *     separación es de 8 px y el `hitSlop` solo se agranda cuando la estrella es pequeña.\n *   · **El color no es la única señal**: el relleno cambia y el texto de al lado dice el número.\n */\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport Animated, {\n  useAnimatedStyle,\n  useSharedValue,\n  withDelay,\n  withSequence,\n  withSpring,\n  withTiming,\n} from 'react-native-reanimated';\nimport { Star } from 'lucide-react-native';\n\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand } from '../theme/colors';\nimport { espaciado, peso, tipografia } from '../theme/escalas';\nimport { curva, duracion, resorte } from '../theme/movimiento';\nimport { haptico } from '../feedback/hapticos';\nimport { useMovimientoReducido } from '../a11y/useMovimientoReducido';\n\n/** Retardo entre una estrella y la siguiente de la cascada. */\nconst PASO_CASCADA = 40;\n\nexport type EstrellasProps = {\n  /** Cuántas estrellas hay puestas (0 = ninguna). */\n  valor: number;\n  /** Se llama con la estrella elegida. */\n  onElegir: (n: number) => void;\n  /** Cuántas estrellas como máximo. Cinco por defecto. */\n  total?: number;\n  /** Tamaño de cada estrella. */\n  tamano?: number;\n  /** Si es `false`, solo se lee (para mostrar una valoración ya dada). */\n  interactivo?: boolean;\n  /** Texto bajo las estrellas. Si no se pasa, no se pinta. */\n  texto?: string;\n  /** Nombre de lo que se valora, para el lector de pantalla («Valorar a Juan»). */\n  queSeValora?: string;\n};\n\nexport function Estrellas({\n  valor,\n  onElegir,\n  total = 5,\n  tamano = 32,\n  interactivo = true,\n  texto,\n  queSeValora,\n}: EstrellasProps) {\n  const { colors } = useTheme();\n  const movReducido = useMovimientoReducido();\n\n  /* UN solo valor compartido con la escala de cada estrella. Ver la cabecera: un hook por estrella\n     dentro de un `map` rompería las reglas de React. */\n  const escalas = useSharedValue<number[]>(new Array(total).fill(1));\n\n  const alElegir = (n: number) => {\n    if (!interactivo) return;\n    if (!movReducido) {\n      /* La cascada: cada estrella hasta la elegida rebota con PASO_CASCADA de retardo sobre la\n         anterior; las demás vuelven a su sitio. Se reconstruye el array entero (no se muta) porque un\n         valor compartido solo se anima si se le ASIGNA algo nuevo. */\n      const siguiente = new Array(total).fill(1).map((_, i) => {\n        if (i >= n) return withTiming(1, { duration: duracion.cambio, easing: curva.salida });\n        return withSequence(\n          withDelay(i * PASO_CASCADA, withSpring(1.2, resorte.rebotar)),\n          withSpring(1, resorte.asentar),\n        );\n      });\n      escalas.value = siguiente;\n    }\n    haptico('toque');\n    onElegir(n);\n  };\n\n  return (\n    <View\n      accessibilityRole={interactivo ? 'radiogroup' : 'none'}\n      accessibilityLabel={queSeValora ? `Valorar ${queSeValora}` : undefined}\n      style={estilos.caja}\n    >\n      <View style={estilos.fila}>\n        {Array.from({ length: total }, (_, i) => (\n          <Estrella\n            key={i}\n            indice={i}\n            total={total}\n            puesta={valor >= i + 1}\n            escalas={escalas}\n            tamano={tamano}\n            interactivo={interactivo}\n            movReducido={movReducido}\n            colorPuesta={brand.warning}\n            colorApagada={colors.border}\n            queSeValora={queSeValora}\n            onElegir={alElegir}\n          />\n        ))}\n      </View>\n      {texto ? (\n        <Text style={[estilos.texto, { color: colors.textSecondary }]} numberOfLines={2}>\n          {texto}\n        </Text>\n      ) : null}\n    </View>\n  );\n}\n\nfunction Estrella({\n  indice,\n  total,\n  puesta,\n  escalas,\n  tamano,\n  interactivo,\n  movReducido,\n  colorPuesta,\n  colorApagada,\n  queSeValora,\n  onElegir,\n}: {\n  indice: number;\n  total: number;\n  puesta: boolean;\n  escalas: { value: number[] };\n  tamano: number;\n  interactivo: boolean;\n  movReducido: boolean;\n  colorPuesta: string;\n  colorApagada: string;\n  queSeValora?: string;\n  onElegir: (n: number) => void;\n}) {\n  const n = indice + 1;\n\n  /* Cada estrella se lee de SU casilla del array. El rebote se dispara cambiando el array desde el\n     padre, así que aquí solo se traduce a un `scale`. */\n  const estilo = useAnimatedStyle(() => {\n    const v = escalas.value[indice];\n    return { transform: [{ scale: typeof v === 'number' ? v : 1 }] };\n  });\n\n  return (\n    <Pressable\n      onPress={() => onElegir(n)}\n      disabled={!interactivo}\n      /* El área táctil: si la estrella es pequeña se agranda SIN invadir la vecina (separación de 8,\n         hitSlop de 4). Es el fallo que la auditoría encontró y aquí no se repite. */\n      hitSlop={tamano >= 32 ? 0 : espaciado.e4}\n      accessibilityRole={interactivo ? 'radio' : 'image'}\n      accessibilityState={interactivo ? { selected: puesta } : undefined}\n      accessibilityLabel={\n        interactivo\n          ? `${n} de ${total}${queSeValora ? `, valorar ${queSeValora}` : ''}`\n          : `${n} de ${total} estrellas`\n      }\n    >\n      <Animated.View style={estilo}>\n        <Star\n          size={tamano}\n          color={puesta ? colorPuesta : colorApagada}\n          fill={puesta ? colorPuesta : 'transparent'}\n          strokeWidth={2}\n        />\n      </Animated.View>\n    </Pressable>\n  );\n}\n\nconst estilos = StyleSheet.create({\n  caja: { alignItems: 'flex-start' },\n  /* La separación es de 8 y no de 6 a propósito: es el hueco mínimo entre objetivos que pide la guía\n     de plataforma, y es lo que permite agrandar el área táctil sin pisar la estrella vecina. */\n  fila: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 },\n  texto: { fontSize: tipografia.caption, fontWeight: peso.medio, marginTop: espaciado.e4 },\n});\n","/**\n * MAPA DE RUTAS — la única lista de rutas de la app (generado, no escrito a mano).\n *\n * POR QUÉ EXISTE: la auditoría (`pruebas/auditar-rutas.cjs`) encontró que el sistema de\n * navegación fallaba en silencio: **1 enlace a una pantalla que no existe** (`/emergencia`),\n * **6 pantallas que nadie abría** y **204 navegaciones con `as never`**, que apagan el\n * comprobador de tipos. Por eso un destino mal escrito no lo veía ni TypeScript: se descubría en\n * el teléfono, delante del usuario.\n *\n * CÓMO SE USA:\n *   import { ir } from '../constants/rutas';\n *   ir.a.producto(id);                  // comprueba que la ruta y sus parámetros existen\n *   ir.libre('/lifebook-catalog');      // para rutas de listas/menús que vienen como texto\n *\n * El ayudante NUNCA navega a ciegas: si la ruta no está en este mapa, o si falta un parámetro\n * obligatorio (o llega vacío), manda a `/ruta-fallida`, que lo explica y da salida. Un botón\n * que no hace nada es peor que un aviso.\n *\n * REGENERAR: node pruebas/generar-mapa-rutas.cjs\n */\nimport { router } from 'expo-router';\n\nexport interface DefinicionRuta {\n  ruta: string;\n  /** Parámetros que NO pueden faltar ni llegar vacíos. */\n  params: string[];\n}\n\nexport const RUTAS = {\n  inicio: { ruta: '/', params: [] },\n  agente: { ruta: '/agente', params: [] },\n  agenteEscaner: { ruta: '/agente-escaner', params: [] },\n  alquiler: { ruta: '/alquiler', params: [] },\n  alquilerDetalle: { ruta: '/alquiler-detalle', params: [] },\n  alquilerPlanes: { ruta: '/alquiler-planes', params: [] },\n  alquilerPublicar: { ruta: '/alquiler-publicar', params: [] },\n  auth: { ruta: '/auth', params: [] },\n  billingCheckout: { ruta: '/billing-checkout', params: [] },\n  billingStatus: { ruta: '/billing-status', params: [] },\n  buscar: { ruta: '/buscar', params: [] },\n  conductor: { ruta: '/conductor', params: [] },\n  conductorHub: { ruta: '/conductor-hub', params: [] },\n  documents: { ruta: '/documents', params: [] },\n  driverOnboarding: { ruta: '/driver-onboarding', params: [] },\n  driverProfile: { ruta: '/driver-profile', params: [] },\n  ecomerse: { ruta: '/ecomerse', params: [] },\n  ecomerseCheckout: { ruta: '/ecomerse-checkout', params: [] },\n  ecomerseDetail: { ruta: '/ecomerse-detail', params: [] },\n  ecomerseDireccion: { ruta: '/ecomerse-direccion', params: [] },\n  ecomerseDirecciones: { ruta: '/ecomerse-direcciones', params: [] },\n  ecomerseDocs: { ruta: '/ecomerse-docs', params: [] },\n  ecomerseFavorites: { ruta: '/ecomerse-favorites', params: [] },\n  ecomerseMensajes: { ruta: '/ecomerse-mensajes', params: [] },\n  ecomerseMensajesAvisos: { ruta: '/ecomerse-mensajes-avisos', params: [] },\n  ecomerseMensajesChat: { ruta: '/ecomerse-mensajes-chat', params: [] },\n  ecomerseOrders: { ruta: '/ecomerse-orders', params: [] },\n  ecomersePerfil: { ruta: '/ecomerse-perfil', params: [] },\n  ecomersePerfilReembolso: { ruta: '/ecomerse-perfil-reembolso', params: [] },\n  ecomersePerfilReembolsos: { ruta: '/ecomerse-perfil-reembolsos', params: [] },\n  ecomersePerfilTiendas: { ruta: '/ecomerse-perfil-tiendas', params: [] },\n  ecomersePlanes: { ruta: '/ecomerse-planes', params: [] },\n  ecomerseSeller: { ruta: '/ecomerse-seller', params: [] },\n  ecomerseSubcategoria: { ruta: '/ecomerse-subcategoria', params: [] },\n  ecomerseTienda: { ruta: '/ecomerse-tienda', params: [] },\n  ecomerseTiendas: { ruta: '/ecomerse-tiendas', params: [] },\n  editProfile: { ruta: '/edit-profile', params: [] },\n  emergencia: { ruta: '/emergencia', params: [] },\n  food: { ruta: '/food', params: [] },\n  foodCheckout: { ruta: '/food-checkout', params: [] },\n  foodMenu: { ruta: '/food-menu', params: [] },\n  foodOrders: { ruta: '/food-orders', params: [] },\n  foodOwner: { ruta: '/food-owner', params: [] },\n  foodRider: { ruta: '/food-rider', params: [] },\n  intercity: { ruta: '/intercity', params: [] },\n  intercityPlanes: { ruta: '/intercity-planes', params: [] },\n  intercityPublish: { ruta: '/intercity-publish', params: [] },\n  kyc: { ruta: '/kyc', params: [] },\n  kycCapture: { ruta: '/kyc/capture', params: [] },\n  kycLiveness: { ruta: '/kyc/liveness', params: [] },\n  kycStatus: { ruta: '/kyc/status', params: [] },\n  landlordProfile: { ruta: '/landlord-profile', params: [] },\n  lifebook: { ruta: '/lifebook', params: [] },\n  lifebookAi: { ruta: '/lifebook-ai', params: [] },\n  lifebookBlocks: { ruta: '/lifebook-blocks', params: [] },\n  lifebookCarrito: { ruta: '/lifebook-carrito', params: [] },\n  lifebookCarritoCheckout: { ruta: '/lifebook-carrito-checkout', params: [] },\n  lifebookCatalog: { ruta: '/lifebook-catalog', params: [] },\n  lifebookChatId: { ruta: '/lifebook-chat/[id]', params: ['id'] },\n  lifebookCheckout: { ruta: '/lifebook-checkout', params: [] },\n  lifebookCompose: { ruta: '/lifebook-compose', params: [] },\n  lifebookDinero: { ruta: '/lifebook-dinero', params: [] },\n  lifebookExplore: { ruta: '/lifebook-explore', params: [] },\n  lifebookGroupCreate: { ruta: '/lifebook-group-create', params: [] },\n  lifebookGroups: { ruta: '/lifebook-groups', params: [] },\n  lifebookGuardados: { ruta: '/lifebook-guardados', params: [] },\n  lifebookHotel: { ruta: '/lifebook-hotel', params: [] },\n  lifebookHotelCalendario: { ruta: '/lifebook-hotel-calendario', params: [] },\n  lifebookHotelDetalle: { ruta: '/lifebook-hotel-detalle', params: [] },\n  lifebookHotelFechas: { ruta: '/lifebook-hotel-fechas', params: [] },\n  lifebookHotelGestion: { ruta: '/lifebook-hotel-gestion', params: [] },\n  lifebookHotelHabitacion: { ruta: '/lifebook-hotel-habitacion', params: [] },\n  lifebookHotelHabitaciones: { ruta: '/lifebook-hotel-habitaciones', params: [] },\n  lifebookHotelPanel: { ruta: '/lifebook-hotel-panel', params: [] },\n  lifebookHotelPerfil: { ruta: '/lifebook-hotel-perfil', params: [] },\n  lifebookHotelReserva: { ruta: '/lifebook-hotel-reserva', params: [] },\n  lifebookHotelReservar: { ruta: '/lifebook-hotel-reservar', params: [] },\n  lifebookHotelReservas: { ruta: '/lifebook-hotel-reservas', params: [] },\n  lifebookHotelResultados: { ruta: '/lifebook-hotel-resultados', params: [] },\n  lifebookInbox: { ruta: '/lifebook-inbox', params: [] },\n  lifebookInboxComments: { ruta: '/lifebook-inbox-comments', params: [] },\n  lifebookInboxFollowers: { ruta: '/lifebook-inbox-followers', params: [] },\n  lifebookInboxLikes: { ruta: '/lifebook-inbox-likes', params: [] },\n  lifebookMedia: { ruta: '/lifebook-media', params: [] },\n  lifebookMerchant: { ruta: '/lifebook-merchant', params: [] },\n  lifebookMerchantGestion: { ruta: '/lifebook-merchant-gestion', params: [] },\n  lifebookMerchantProducts: { ruta: '/lifebook-merchant-products', params: [] },\n  lifebookMerchantSettings: { ruta: '/lifebook-merchant-settings', params: [] },\n  lifebookMessageSearch: { ruta: '/lifebook-message-search', params: [] },\n  lifebookMessages: { ruta: '/lifebook-messages', params: [] },\n  lifebookOrderId: { ruta: '/lifebook-order/[id]', params: ['id'] },\n  lifebookOrders: { ruta: '/lifebook-orders', params: [] },\n  lifebookPlayer: { ruta: '/lifebook-player', params: [] },\n  lifebookPostId: { ruta: '/lifebook-post/[id]', params: ['id'] },\n  lifebookProductId: { ruta: '/lifebook-product/[id]', params: ['id'] },\n  lifebookScan: { ruta: '/lifebook-scan', params: [] },\n  lifebookSearch: { ruta: '/lifebook-search', params: [] },\n  lifebookSell: { ruta: '/lifebook-sell', params: [] },\n  lifebookShopId: { ruta: '/lifebook-shop/[id]', params: ['id'] },\n  lifebookStore: { ruta: '/lifebook-store', params: [] },\n  lifebookUser: { ruta: '/lifebook-user', params: [] },\n  lifebookVideos: { ruta: '/lifebook-videos', params: [] },\n  lifebookVistos: { ruta: '/lifebook-vistos', params: [] },\n  monedero: { ruta: '/monedero', params: [] },\n  monederoMovimientos: { ruta: '/monedero-movimientos', params: [] },\n  monederoPin: { ruta: '/monedero-pin', params: [] },\n  monederoRecargar: { ruta: '/monedero-recargar', params: [] },\n  monederoRetirar: { ruta: '/monedero-retirar', params: [] },\n  myTickets: { ruta: '/my-tickets', params: [] },\n  profile: { ruta: '/profile', params: [] },\n  promoId: { ruta: '/promo/[id]', params: ['id'] },\n  reserva: { ruta: '/reserva', params: [] },\n  rutaFallida: { ruta: '/ruta-fallida', params: [] },\n  scanner: { ruta: '/scanner', params: [] },\n  serviceId: { ruta: '/service/[id]', params: ['id'] },\n  settings: { ruta: '/settings', params: [] },\n  status: { ruta: '/status', params: [] },\n  taxi: { ruta: '/taxi', params: [] },\n  tienda: { ruta: '/tienda', params: [] },\n  tiendaAnuncios: { ruta: '/tienda/anuncios', params: [] },\n  tiendaCombinaciones: { ruta: '/tienda/combinaciones', params: [] },\n  tiendaPedidos: { ruta: '/tienda/pedidos', params: [] },\n  tiendaPerfil: { ruta: '/tienda/perfil', params: [] },\n  tiendaPublicar: { ruta: '/tienda/publicar', params: [] },\n  tripsHistory: { ruta: '/trips-history', params: [] },\n  work: { ruta: '/work', params: [] },\n  workDetail: { ruta: '/work-detail', params: [] },\n  workGestion: { ruta: '/work-gestion', params: [] },\n  workPanel: { ruta: '/work-panel', params: [] },\n  workPlanes: { ruta: '/work-planes', params: [] },\n  workPublish: { ruta: '/work-publish', params: [] },\n} as const satisfies Record<string, DefinicionRuta>;\n\nexport type NombreRuta = keyof typeof RUTAS;\n\n/** Pantalla que explica que algo no se pudo abrir. */\nexport const RUTA_FALLIDA = '/ruta-fallida';\n/** Inicio: la salida limpia que siempre funciona. */\nexport const RUTA_INICIO = '/';\n\nconst vacio = (v: unknown) => v === undefined || v === null || String(v).trim() === '';\n\n/**\n * Comprueba una ruta antes de navegar. Devuelve el motivo si NO se puede, o null si está bien.\n * Se exporta para poder probarlo (y para avisar sin navegar, si algún día hace falta).\n */\nexport function problemaDeRuta(ruta: string, params?: Record<string, unknown>): string | null {\n  if (vacio(ruta)) return 'La ruta llegó vacía.';\n  const def = (RUTAS as Record<string, DefinicionRuta>)[Object.keys(RUTAS).find(\n    (k) => (RUTAS as Record<string, DefinicionRuta>)[k].ruta === ruta,\n  ) ?? ''];\n  if (!def) return `La ruta \"${ruta}\" no existe en el mapa de rutas.`;\n  const faltan = def.params.filter((p) => vacio(params?.[p]));\n  if (faltan.length) return `A \"${ruta}\" le falta ${faltan.length === 1 ? 'el dato' : 'los datos'}: ${faltan.join(', ')}.`;\n  // Rutas con parámetro pero sin ninguno declarado: se comprueba en la propia dirección.\n  if (/\\[|:/.test(ruta) && !def.params.length) return `La ruta \"${ruta}\" tiene un hueco sin rellenar.`;\n  return null;\n}\n\nfunction navegar(ruta: string, params?: Record<string, unknown>, reemplazar = false) {\n  const problema = problemaDeRuta(ruta, params);\n  if (problema) {\n    // Se avisa en consola (para el desarrollo) y se lleva a la pantalla que lo explica, con el\n    // motivo y el destino, en vez de dejar la pulsación sin efecto.\n    console.warn('[rutas]', problema, { ruta, params });\n    router[reemplazar ? 'replace' : 'push']({\n      pathname: RUTA_FALLIDA,\n      params: { motivo: problema, destino: ruta },\n    } as never);\n    return;\n  }  const destino = (Object.values(RUTAS) as DefinicionRuta[]).find((d) => d.ruta === ruta);\n  if (destino && destino.params.length) {\n    router[reemplazar ? 'replace' : 'push']({ pathname: ruta, params: params ?? {} } as never);\n  } else if (params && Object.keys(params).length) {\n    router[reemplazar ? 'replace' : 'push']({ pathname: ruta, params } as never);\n  } else {\n    router[reemplazar ? 'replace' : 'push'](ruta as never);\n  }\n}\n\n/**\n * Lleva a la pantalla que explica el problema. Se usa cuando lo que falla NO es una ruta\n * (por ejemplo: no se pudo resolver el perfil porque la sesión venía a medias). Antes esos\n * casos dejaban la pulsación sin ningún efecto.\n */\nfunction explicar(motivo: string, destino = '') {\n  console.warn('[rutas]', motivo, { destino });\n  router.push({ pathname: RUTA_FALLIDA, params: { motivo, destino } } as never);\n}\n\n/**\n * El ayudante. Tres formas, para que no haya excusa para navegar a ciegas:\n *   ir.a.producto(id)         → ruta conocida con su parámetro (lo comprueba)\n *   ir.libre('/lo-que-sea')   → cuando la ruta viene de una lista/menú (la valida igual)\n *   ir.destino({...})         → destinos ya construidos como objeto\n *   ir.inicio()               → la salida que siempre funciona\n */\nexport const ir = {\n  /** Navega a una ruta del mapa, comprobando que sus parámetros vienen. */\n  a: (nombreRuta: NombreRuta, params?: Record<string, unknown>, reemplazar = false) => {\n    navegar(RUTAS[nombreRuta].ruta, params, reemplazar);\n  },\n  /** Navega a una ruta escrita como texto (listas, menús, ajustes). Se valida igual. */\n  libre: (ruta: string, params?: Record<string, unknown>, reemplazar = false) => {\n    navegar(ruta, params, reemplazar);\n  },\n  /** Siempre disponible: el inicio. */\n  inicio: (reemplazar = false) => navegar(RUTA_INICIO, undefined, reemplazar),\n  /**\n   * Para destinos que ya vienen construidos como objeto (`{ pathname, params }`), que es lo que\n   * devuelven varios ayudantes de la app (`destinoMiPerfilLifeBook`, menús, etc.). Se valida su\n   * `pathname` y sus parámetros igual que los demás.\n   */\n  destino: (destino: string | { pathname?: string; params?: Record<string, unknown> } | null | undefined,\n            motivoSiFalta = 'No se pudo resolver a dónde ir.') => {\n    if (destino === null || destino === undefined) { explicar(motivoSiFalta, ''); return; }\n    if (typeof destino === 'string') { navegar(destino); return; }\n    const ruta = String(destino.pathname ?? '');\n    const problema = problemaDeRuta(ruta, destino.params);\n    if (problema) { explicar(problema, ruta); return; }\n    navegar(ruta, destino.params);\n  },\n  /** Lleva a la pantalla que explica el problema (para casos que no son una ruta). */\n  explicar,\n  /** Vuelve atrás si se puede; si no (se abrió por enlace), va al inicio. */\n  atras: () => {\n    try {\n      if (router.canGoBack()) router.back();\n      else navegar(RUTA_INICIO, undefined, true);\n    } catch {\n      navegar(RUTA_INICIO, undefined, true);\n    }\n  },\n};\n","/**\n * Raíz Expo Router — GestureHandlerRootView (requerido por bottom-sheet),\n * ThemeProvider (claro/oscuro) y Stack sin cabeceras nativas.\n *\n * ── EL DESTELLO BLANCO (arreglado el 2026-09-12, y por qué estaba) ─────────────\n * Medido con pantallazos al arrancar en modo oscuro: los dos primeros fotogramas salían con **luma\n * 246 de 255** (casi blanco) y el resto con 40 (la app oscura). Ese 246 es exactamente `#F5F7FA`, que\n * era el `backgroundColor` de `app.json` y el `android:windowBackground` del tema nativo: Android pinta\n * la ventana con ese color **desde que arranca la actividad hasta que la app dibuja**. En luz no se\n * notaba (claro sobre claro); en oscuro era un fogonazo.\n * El arreglo tiene dos capas:\n *   1. **Nativa**: `android/app/src/main/res/values-night/colors.xml` (existía VACÍO) con el color del\n *      tema oscuro, para que la ventana nazca oscura cuando el móvil está en modo noche.\n *   2. **Del navegador** (aquí abajo): el `Stack` se envuelve en el tema de React Navigation y se le da\n *      `contentStyle` con el fondo del tema, para que las transiciones no pinten el fondo claro por\n *      defecto mientras la pantalla nueva dibuja lo suyo.\n */\n\nimport 'react-native-gesture-handler';\nimport React, { useEffect, useMemo } from 'react';\nimport { Linking, View } from 'react-native';\nimport { GestureHandlerRootView } from 'react-native-gesture-handler';\nimport { Stack, useRouter } from 'expo-router';\nimport { StatusBar } from 'expo-status-bar';\nimport {\n  DarkTheme, DefaultTheme, ThemeProvider as NavThemeProvider, type Theme as NavTheme,\n} from '@react-navigation/native';\nimport { ThemeProvider, useTheme } from '../theme/ThemeContext';\nimport { SessionProvider } from '../state/session';\nimport { StatusProvider } from '../state/statusStore';\nimport { CrashShield } from '../core/diagnostics';\nimport { runNetProbe } from '../api/netprobe';\nimport BotonCucucul from '../components/lifebook/BotonCucucul';\n\n// Diagnóstico temporal de red (logcat). Eliminar junto a api/netprobe.ts.\nif (typeof globalThis !== 'undefined') {\n  runNetProbe();\n}\n\n// Arranque en Life Book (decisión del dueño): SOLO en el primer montaje de la\n// sesión y con un pequeño retardo, porque navegar antes de que el Stack raíz\n// esté montado revienta la app (\"Attempted to navigate before mounting the\n// Root Layout\"). Al volver con la pestaña Inicio NO se redirige de nuevo.\nlet bootRedirected = false;\n\n/**\n * ¿La app se ha abierto por un ENLACE (no por el icono)?\n *\n * 🔒 Defecto que esto arregla: abrir `egrouteplan://lifebook-hotel-reserva?id=…` con la app\n * CERRADA dejaba al usuario en el muro de Life Book. El enlace SÍ se resolvía, pero 400 ms\n * después esto hacía `router.replace('/lifebook')` y lo pisaba. Con la app ya abierta no\n * pasaba, porque la bandera `bootRedirected` ya valía `true` — por eso se coló: la prueba\n * normal (app abierta) salía bien.\n *\n * Consecuencia real: a un huésped que le llega por WhatsApp el enlace de su reserva, con la\n * app cerrada, le aparecía el muro y no su reserva.\n */\nasync function abrioPorEnlace(): Promise<boolean> {\n  try {\n    const url = await Linking.getInitialURL();\n    if (!url) return false;\n    // `egrouteplan://lifebook-hotel-reserva?id=…` → `lifebook-hotel-reserva`\n    const camino = url.replace(/^[a-z0-9+.-]+:\\/\\//i, '').split('?')[0].replace(/\\/+$/, '');\n    return camino.length > 0 && camino !== 'index';\n  } catch {\n    return false;\n  }\n}\n\nfunction BootRedirect() {\n  const router = useRouter();\n  useEffect(() => {\n    if (bootRedirected) return;\n    bootRedirected = true;\n    let vivo = true;\n    const t = setTimeout(() => {\n      void (async () => {\n        if (!vivo) return;\n        // Un enlace directo MANDA sobre el arranque por defecto: si alguien abrió la app\n        // para ver su reserva, no se le lleva a otro sitio.\n        if (await abrioPorEnlace()) return;\n        if (!vivo) return;\n        try { router.replace('/lifebook' as never); } catch { /* sin navegación */ }\n      })();\n    }, 400);\n    return () => { vivo = false; clearTimeout(t); };\n  }, [router]);\n  return null;\n}\n\n/**\n * La navegación, con el fondo del TEMA.\n *\n * React Navigation pinta su propio fondo durante las transiciones (y detrás de cada pantalla mientras\n * dibuja). Sin esto usaba el de su tema por defecto —claro—, así que en modo oscuro se colaba un\n * fogonazo en cada pantalla nueva. `contentStyle` y los colores del tema se sacan de nuestros tokens,\n * para que la ventana, el navegador y las pantallas sean el MISMO color.\n */\nfunction NavegacionConTema() {\n  const { colors, isDark } = useTheme();\n  const navTheme: NavTheme = useMemo(() => {\n    const base = isDark ? DarkTheme : DefaultTheme;\n    return {\n      ...base,\n      dark: isDark,\n      colors: {\n        ...base.colors,\n        primary: colors.primary,\n        background: colors.background,\n        // `card` es el fondo que pinta el navegador detrás de cada pantalla: tiene que ser el del tema.\n        card: colors.background,\n        text: colors.textPrimary,\n        border: colors.border,\n        notification: colors.secondary,\n      },\n    };\n  }, [colors, isDark]);\n\n  return (\n    <NavThemeProvider value={navTheme}>\n      <View style={{ flex: 1, backgroundColor: colors.background }}>\n        <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: colors.background } }}>\n          <Stack.Screen name=\"index\" options={{ animation: 'none' }} />\n          <Stack.Screen name=\"lifebook\" options={{ animation: 'none' }} />\n          <Stack.Screen name=\"lifebook-messages\" options={{ animation: 'none' }} />\n          <Stack.Screen name=\"taxi\" options={{ animation: 'none' }} />\n          <Stack.Screen name=\"profile\" options={{ animation: 'none' }} />\n        </Stack>\n        {/*\n          TANDA N — CUCUCUL EN TODA LA APP.\n\n          Se pidió «en toda la app» y el dock es `FloatingFooter.tsx`, que no se toca (regla del\n          proyecto). Así que el botón se pinta aquí, POR ENCIMA de las pantallas: aparece en\n          cualquiera sin meter mano en la navegación. Él mismo decide dónde NO salir (su chat, la\n          autenticación y el vídeo a pantalla completa).\n        */}\n        <BotonCucucul />\n      </View>\n    </NavThemeProvider>\n  );\n}\n\nexport default function RootLayout() {\n  return (\n    <CrashShield>\n      <GestureHandlerRootView style={{ flex: 1 }}>\n        <ThemeProvider>\n          <SessionProvider>\n            <StatusProvider>\n              <StatusBar style=\"auto\" />\n              <BootRedirect />\n              <NavegacionConTema />\n            </StatusProvider>\n          </SessionProvider>\n        </ThemeProvider>\n      </GestureHandlerRootView>\n    </CrashShield>\n  );\n}\n","import { initialize } from './init';\n\nexport { Directions } from './Directions';\nexport { State } from './State';\nexport { PointerType } from './PointerType';\nexport { default as gestureHandlerRootHOC } from './components/gestureHandlerRootHOC';\nexport { default as GestureHandlerRootView } from './components/GestureHandlerRootView';\nexport type {\n  // Event types\n  GestureEvent,\n  HandlerStateChangeEvent,\n  // Event payloads types\n  GestureEventPayload,\n  HandlerStateChangeEventPayload,\n  // Pointer events\n  GestureTouchEvent,\n  TouchData,\n  // New api event types\n  GestureUpdateEvent,\n  GestureStateChangeEvent,\n} from './handlers/gestureHandlerCommon';\nexport { MouseButton } from './handlers/gestureHandlerCommon';\nexport type { GestureType } from './handlers/gestures/gesture';\nexport type {\n  TapGestureHandlerEventPayload,\n  ForceTouchGestureHandlerEventPayload,\n  LongPressGestureHandlerEventPayload,\n  PanGestureHandlerEventPayload,\n  PinchGestureHandlerEventPayload,\n  RotationGestureHandlerEventPayload,\n  NativeViewGestureHandlerPayload,\n  FlingGestureHandlerEventPayload,\n} from './handlers/GestureHandlerEventPayload';\nexport type { TapGestureHandlerProps } from './handlers/TapGestureHandler';\nexport type { ForceTouchGestureHandlerProps } from './handlers/ForceTouchGestureHandler';\nexport type { ForceTouchGestureChangeEventPayload } from './handlers/gestures/forceTouchGesture';\nexport type { LongPressGestureHandlerProps } from './handlers/LongPressGestureHandler';\nexport type { PanGestureHandlerProps } from './handlers/PanGestureHandler';\nexport type { PanGestureChangeEventPayload } from './handlers/gestures/panGesture';\nexport type { PinchGestureHandlerProps } from './handlers/PinchGestureHandler';\nexport type { PinchGestureChangeEventPayload } from './handlers/gestures/pinchGesture';\nexport type { RotationGestureHandlerProps } from './handlers/RotationGestureHandler';\nexport type { FlingGestureHandlerProps } from './handlers/FlingGestureHandler';\nexport { TapGestureHandler } from './handlers/TapGestureHandler';\nexport { ForceTouchGestureHandler } from './handlers/ForceTouchGestureHandler';\nexport { LongPressGestureHandler } from './handlers/LongPressGestureHandler';\nexport { PanGestureHandler } from './handlers/PanGestureHandler';\nexport { PinchGestureHandler } from './handlers/PinchGestureHandler';\nexport { RotationGestureHandler } from './handlers/RotationGestureHandler';\nexport { FlingGestureHandler } from './handlers/FlingGestureHandler';\nexport { default as createNativeWrapper } from './handlers/createNativeWrapper';\nexport type { NativeViewGestureHandlerProps } from './handlers/NativeViewGestureHandler';\nexport { GestureDetector } from './handlers/gestures/GestureDetector';\nexport { GestureObjects as Gesture } from './handlers/gestures/gestureObjects';\nexport type { TapGestureType as TapGesture } from './handlers/gestures/tapGesture';\nexport type { PanGestureType as PanGesture } from './handlers/gestures/panGesture';\nexport type { FlingGestureType as FlingGesture } from './handlers/gestures/flingGesture';\nexport type { LongPressGestureType as LongPressGesture } from './handlers/gestures/longPressGesture';\nexport type { PinchGestureType as PinchGesture } from './handlers/gestures/pinchGesture';\nexport type { RotationGestureType as RotationGesture } from './handlers/gestures/rotationGesture';\nexport type { ForceTouchGestureType as ForceTouchGesture } from './handlers/gestures/forceTouchGesture';\nexport type { NativeGestureType as NativeGesture } from './handlers/gestures/nativeGesture';\nexport type { ManualGestureType as ManualGesture } from './handlers/gestures/manualGesture';\nexport type { HoverGestureType as HoverGesture } from './handlers/gestures/hoverGesture';\nexport type {\n  ComposedGestureType as ComposedGesture,\n  RaceGestureType as RaceGesture,\n  SimultaneousGestureType as SimultaneousGesture,\n  ExclusiveGestureType as ExclusiveGesture,\n} from './handlers/gestures/gestureComposition';\nexport type { GestureStateManagerType as GestureStateManager } from './handlers/gestures/gestureStateManager';\nexport { NativeViewGestureHandler } from './handlers/NativeViewGestureHandler';\nexport type {\n  RawButtonProps,\n  BaseButtonProps,\n  RectButtonProps,\n  BorderlessButtonProps,\n} from './components/GestureButtonsProps';\nexport {\n  RawButton,\n  BaseButton,\n  RectButton,\n  BorderlessButton,\n  PureNativeButton,\n} from './components/GestureButtons';\nexport type {\n  TouchableHighlightProps,\n  TouchableOpacityProps,\n  TouchableWithoutFeedbackProps,\n} from './components/touchables';\nexport {\n  TouchableHighlight,\n  TouchableNativeFeedback,\n  TouchableOpacity,\n  TouchableWithoutFeedback,\n} from './components/touchables';\nexport {\n  ScrollView,\n  Switch,\n  TextInput,\n  DrawerLayoutAndroid,\n  FlatList,\n  RefreshControl,\n} from './components/GestureComponents';\nexport { Text } from './components/Text';\nexport { HoverEffect } from './handlers/gestures/hoverGesture';\nexport type {\n  // Events\n  GestureHandlerGestureEvent,\n  GestureHandlerStateChangeEvent,\n  // Event payloads\n  GestureHandlerGestureEventNativeEvent,\n  GestureHandlerStateChangeNativeEvent,\n  NativeViewGestureHandlerGestureEvent,\n  NativeViewGestureHandlerStateChangeEvent,\n  TapGestureHandlerGestureEvent,\n  TapGestureHandlerStateChangeEvent,\n  ForceTouchGestureHandlerGestureEvent,\n  ForceTouchGestureHandlerStateChangeEvent,\n  LongPressGestureHandlerGestureEvent,\n  LongPressGestureHandlerStateChangeEvent,\n  PanGestureHandlerGestureEvent,\n  PanGestureHandlerStateChangeEvent,\n  PinchGestureHandlerGestureEvent,\n  PinchGestureHandlerStateChangeEvent,\n  RotationGestureHandlerGestureEvent,\n  RotationGestureHandlerStateChangeEvent,\n  FlingGestureHandlerGestureEvent,\n  FlingGestureHandlerStateChangeEvent,\n  // Handlers props\n  NativeViewGestureHandlerProperties,\n  TapGestureHandlerProperties,\n  LongPressGestureHandlerProperties,\n  PanGestureHandlerProperties,\n  PinchGestureHandlerProperties,\n  RotationGestureHandlerProperties,\n  FlingGestureHandlerProperties,\n  ForceTouchGestureHandlerProperties,\n  // Buttons props\n  RawButtonProperties,\n  BaseButtonProperties,\n  RectButtonProperties,\n  BorderlessButtonProperties,\n} from './handlers/gestureHandlerTypesCompat';\n\nexport type { SwipeableProps } from './components/Swipeable';\nexport { default as Swipeable } from './components/Swipeable';\nexport type {\n  PressableProps,\n  PressableStateCallbackType,\n} from './components/Pressable';\nexport { default as Pressable } from './components/Pressable';\n\nexport type {\n  DrawerLayoutProps,\n  DrawerPosition,\n  DrawerState,\n  DrawerType,\n  DrawerLockMode,\n  DrawerKeyboardDismissMode,\n} from './components/DrawerLayout';\nexport { default as DrawerLayout } from './components/DrawerLayout';\n\nexport {\n  enableExperimentalWebImplementation,\n  enableLegacyWebImplementation,\n} from './EnableNewWebImplementation';\n\ninitialize();\n","import { startListening } from './handlers/gestures/eventReceiver';\nimport RNGestureHandlerModule from './RNGestureHandlerModule';\nimport { isFabric } from './utils';\n\nlet fabricInitialized = false;\n\nexport function initialize() {\n  startListening();\n}\n\n// Since isFabric() may give wrong results before the first render, we call this\n// method during render of GestureHandlerRootView\nexport function maybeInitializeFabric() {\n  if (isFabric() && !fabricInitialized) {\n    RNGestureHandlerModule.install();\n    fabricInitialized = true;\n  }\n}\n","import { DeviceEventEmitter, EmitterSubscription } from 'react-native';\nimport { State } from '../../State';\nimport { TouchEventType } from '../../TouchEventType';\nimport {\n  GestureTouchEvent,\n  GestureUpdateEvent,\n  GestureStateChangeEvent,\n} from '../gestureHandlerCommon';\nimport { findHandler, findOldGestureHandler } from '../handlersRegistry';\nimport { BaseGesture } from './gesture';\nimport {\n  GestureStateManager,\n  GestureStateManagerType,\n} from './gestureStateManager';\n\nlet gestureHandlerEventSubscription: EmitterSubscription | null = null;\nlet gestureHandlerStateChangeEventSubscription: EmitterSubscription | null =\n  null;\n\nconst gestureStateManagers: Map<number, GestureStateManagerType> = new Map<\n  number,\n  GestureStateManagerType\n>();\n\nconst lastUpdateEvent: (GestureUpdateEvent | undefined)[] = [];\n\nfunction isStateChangeEvent(\n  event: GestureUpdateEvent | GestureStateChangeEvent | GestureTouchEvent\n): event is GestureStateChangeEvent {\n  // @ts-ignore oldState doesn't exist on GestureTouchEvent and that's the point\n  return event.oldState != null;\n}\n\nfunction isTouchEvent(\n  event: GestureUpdateEvent | GestureStateChangeEvent | GestureTouchEvent\n): event is GestureTouchEvent {\n  return event.eventType != null;\n}\n\nexport function onGestureHandlerEvent(\n  event: GestureUpdateEvent | GestureStateChangeEvent | GestureTouchEvent\n) {\n  const handler = findHandler(event.handlerTag) as BaseGesture<\n    Record<string, unknown>\n  >;\n\n  if (handler) {\n    if (isStateChangeEvent(event)) {\n      if (\n        event.oldState === State.UNDETERMINED &&\n        event.state === State.BEGAN\n      ) {\n        handler.handlers.onBegin?.(event);\n      } else if (\n        (event.oldState === State.BEGAN ||\n          event.oldState === 