o, useRef, useState, type ReactNode } from 'react';\nimport * as SecureStore from 'expo-secure-store';\nimport { API_BASE } from '../api/config';\nimport { biometricAvailable, biometricVerify } from '../core/biometric';\n\nconst ACCESS_KEY = 'egrp.access_token';\nconst REFRESH_KEY = 'egrp.refresh_token';\nconst PHONE_KEY = 'egrp.phone';\n\ntype Role = 'PASSENGER' | 'DRIVER' | 'ADMIN';\n\nfunction decodeClaim(token: string | null, claim: string): any {\n  if (!token) return null;\n  try {\n    const payload = JSON.parse(atob(token.split('.')[1]));\n    return payload[claim];\n  } catch {\n    return null;\n  }\n}\n\ninterface SessionValue {\n  hydrated: boolean;\n  isAuthenticated: boolean; // hay sesión recordada (refresh_token)\n  isUnlocked: boolean;       // access_token disponible esta sesión\n  token: string | null;      // access_token en memoria (null si locked)\n  role: Role;\n  phone: string | null;\n  /** Desbloqueo biométrico para usuarios con sesión recordada. */\n  unlockBiometric: () => Promise<boolean>;\n  /** Establece tokens tras login/OTP/registro (cierra el modal de auth). */\n  login: (accessToken: string, refreshToken: string, phone?: string) => Promise<void>;\n  /** Logout total: SecureStore + memoria + marca WebView para limpieza. */\n  logout: () => Promise<void>;\n  /** Se incrementa para forzar limpieza/recarga del WebView al hacer logout. */\n  webviewLogoutNonce: number;\n}\n\nconst SessionCtx = createContext<SessionValue>(null as unknown as SessionValue);\n\nexport function SessionProvider({ children }: { children: ReactNode }) {\n  const [hydrated, setHydrated] = useState(false);\n  const [refreshToken, setRefreshToken] = useState<string | null>(null);\n  const [accessToken, setAccessToken] = useState<string | null>(null);\n  const [phone, setPhone] = useState<string | null>(null);\n  const [webviewLogoutNonce, setWebviewLogoutNonce] = useState(0);\n\n  // Refs para que el holder del httpClient vea siempre el valor más reciente.\n  const accessRef = useRef<string | null>(null);\n  const refreshRef = useRef<string | null>(null);\n  accessRef.current = accessToken;\n  refreshRef.current = refreshToken;\n\n  useEffect(() => {\n    (async () => {\n      const [rt, ph] = await Promise.all([\n        SecureStore.getItemAsync(REFRESH_KEY).catch(() => null),\n        SecureStore.getItemAsync(PHONE_KEY).catch(() => null),\n      ]);\n\n      // Conecta el interceptor HTTP con este provider.\n      const { configureHttpAuth } = await import('../api/httpClient');\n      configureHttpAuth({\n        getAccessToken: () => accessRef.current,\n        getRefreshToken: () => refreshRef.current,\n        setTokens: async (a, r) => {\n          await SecureStore.setItemAsync(ACCESS_KEY, a).catch(() => {});\n          await SecureStore.setItemAsync(REFRESH_KEY, r).catch(() => {});\n          setAccessToken(a);\n          setRefreshToken(r);\n        },\n        onAuthLost: async () => {\n          await SecureStore.deleteItemAsync(ACCESS_KEY).catch(() => {});\n          await SecureStore.deleteItemAsync(REFRESH_KEY).catch(() => {});\n          setAccessToken(null);\n          setRefreshToken(null);\n          setWebviewLogoutNonce((n) => n + 1);\n        },\n      });\n\n      // Sesión recordada → refresco silencioso (sin PIN ni biometría).\n      // Restaura el access token ANTES de hidratar para que AuthGate\n      // (Perfil/Monedero) desbloquee solo al reiniciar la app.\n      let restoredAccess: string | null = null;\n      if (rt) {\n        const savedAccess = await SecureStore.getItemAsync(ACCESS_KEY).catch(() => null);\n        restoredAccess = savedAccess ?? (await refreshInternal(rt));\n      }\n\n      // Fija TODO el estado y recién entonces marca hydrated (sin carreras).\n      if (rt) setRefreshToken(rt);\n      if (ph) setPhone(ph);\n      if (restoredAccess) setAccessToken(restoredAccess);\n      setHydrated(true);\n    })();\n  }, []);\n\n  /** Canje silencioso refresh→access (interno, reutilizable en hidratación y unlock). */\n  const refreshInternal = async (rt: string): Promise<string | null> => {\n    try {\n      const res = await fetch(`${API_BASE}/mobility/auth/refresh`, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ refreshToken: rt }),\n      });\n      if (!res.ok) return null;\n      const data = await res.json();\n      const a: string | undefined = data.accessToken;\n      const r: string | undefined = data.refreshToken;\n      if (!a || !r) return null;\n      await SecureStore.setItemAsync(ACCESS_KEY, a).catch(() => {});\n      await SecureStore.setItemAsync(REFRESH_KEY, r).catch(() => {});\n      return a;\n    } catch {\n      return null;\n    }\n  };\n\n  /** Canje silencioso refresh→access. Devuelve el nuevo access token o null. */\n  const refresh = async (): Promise<string | null> => {\n    const rt = refreshRef.current;\n    if (!rt) return null;\n    const a = await refreshInternal(rt);\n    if (a) {\n      setAccessToken(a);\n      setRefreshToken(rt);\n    }\n    return a;\n  };\n\n  const unlockBiometric = async (): Promise<boolean> => {\n    // SIN PIN ni biometría: la sesión recordada se desbloquea sola (refresh).\n    if (!refreshRef.current) return false;\n    const a = await refresh();\n    return !!a;\n  };\n\n  const login = async (a: string, r: string, ph?: string) => {\n    await SecureStore.setItemAsync(ACCESS_KEY, a).catch(() => {});\n    await SecureStore.setItemAsync(REFRESH_KEY, r).catch(() => {});\n    if (ph) {\n      await SecureStore.setItemAsync(PHONE_KEY, ph).catch(() => {});\n      setPhone(ph);\n    }\n    setAccessToken(a);\n    setRefreshToken(r);\n  };\n\n  const logout = async () => {\n    await SecureStore.deleteItemAsync(ACCESS_KEY).catch(() => {});\n    await SecureStore.deleteItemAsync(REFRESH_KEY).catch(() => {});\n    // Conservamos el teléfono para un re-login cómodo (no es secreto).\n    setAccessToken(null);\n    setRefreshToken(null);\n    setWebviewLogoutNonce((n) => n + 1); // avisa al WebView para limpiar localStorage\n  };\n\n  const value = useMemo<SessionValue>(\n    () => ({\n      hydrated,\n      isAuthenticated: !!refreshToken,\n      isUnlocked: !!accessToken,\n      token: accessToken,\n      role: (decodeClaim(refreshToken, 'role') as Role) ?? 'PASSENGER',\n      phone,\n      unlockBiometric,\n      login,\n      logout,\n      webviewLogoutNonce,\n    }),\n    [hydrated, refreshToken, accessToken, phone, webviewLogoutNonce],\n  );\n\n  return <SessionCtx.Provider value={value}>{children}</SessionCtx.Provider>;\n}\n\nexport const useSession = () => useContext(SessionCtx);\n","import ExpoSecureStore from './ExpoSecureStore';\nimport { byteCountOverLimit, VALUE_BYTES_LIMIT } from './byteCounter';\n// @needsAudit\n/**\n * The data in the keychain item cannot be accessed after a restart until the device has been\n * unlocked once by the user. This may be useful if you need to access the item when the phone\n * is locked.\n */\nexport const AFTER_FIRST_UNLOCK = ExpoSecureStore.AFTER_FIRST_UNLOCK;\n// @needsAudit\n/**\n * Similar to `AFTER_FIRST_UNLOCK`, except the entry is not migrated to a new device when restoring\n * from a backup.\n */\nexport const AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY = ExpoSecureStore.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY;\n// @needsAudit\n/**\n * The data in the keychain item can always be accessed regardless of whether the device is locked.\n * This is the least secure option.\n *\n * @deprecated Use an accessibility level that provides some user protection, such as `AFTER_FIRST_UNLOCK`.\n */\nexport const ALWAYS = ExpoSecureStore.ALWAYS;\n// @needsAudit\n/**\n * Similar to `WHEN_UNLOCKED_THIS_DEVICE_ONLY`, except the user must have set a passcode in order to\n * store an entry. If the user removes their passcode, the entry will be deleted.\n */\nexport const WHEN_PASSCODE_SET_THIS_DEVICE_ONLY = ExpoSecureStore.WHEN_PASSCODE_SET_THIS_DEVICE_ONLY;\n// @needsAudit\n/**\n * Similar to `ALWAYS`, except the entry is not migrated to a new device when restoring from a backup.\n *\n * @deprecated Use an accessibility level that provides some user protection, such as `AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY`.\n */\nexport const ALWAYS_THIS_DEVICE_ONLY = ExpoSecureStore.ALWAYS_THIS_DEVICE_ONLY;\n// @needsAudit\n/**\n * The data in the keychain item can be accessed only while the device is unlocked by the user.\n */\nexport const WHEN_UNLOCKED = ExpoSecureStore.WHEN_UNLOCKED;\n// @needsAudit\n/**\n * Similar to `WHEN_UNLOCKED`, except the entry is not migrated to a new device when restoring from\n * a backup.\n */\nexport const WHEN_UNLOCKED_THIS_DEVICE_ONLY = ExpoSecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY;\n// @needsAudit\n/**\n * Returns whether the SecureStore API is enabled on the current device. This does not check the app\n * permissions.\n *\n * @return Promise which fulfils with a `boolean`, indicating whether the SecureStore API is available\n * on the current device. Currently, this resolves `true` on Android and iOS only.\n */\nexport async function isAvailableAsync() {\n    return !!ExpoSecureStore.getValueWithKeyAsync;\n}\n// @needsAudit\n/**\n * Delete the value associated with the provided key.\n *\n * @param key The key that was used to store the associated value.\n * @param options An [`SecureStoreOptions`](#securestoreoptions) object.\n *\n * @return A promise that rejects if the value can't be deleted.\n */\nexport async function deleteItemAsync(key, options = {}) {\n    ensureValidKey(key);\n    await ExpoSecureStore.deleteValueWithKeyAsync(key, options);\n}\n// @needsAudit\n/**\n * Reads the stored value associated with the provided key.\n *\n * @param key The key that was used to store the associated value.\n * @param options An [`SecureStoreOptions`](#securestoreoptions) object.\n *\n * @return A promise that resolves to the previously stored value. It resolves with `null` if there is no entry\n * for the given