hePolicy = options.cachePolicy ?? cachePolicy;\n        headers = options.headers;\n        break;\n    }\n\n    return ImageModule.prefetch(Array.isArray(urls) ? urls : [urls], cachePolicy, headers);\n  }\n\n  /**\n   * Asynchronously clears all images stored in memory.\n   * @platform android\n   * @platform ios\n   * @return A promise resolving to `true` when the operation succeeds.\n   * It may resolve to `false` on Android when the activity is no longer available.\n   * Resolves to `false` on Web.\n   */\n  static async clearMemoryCache(): Promise<boolean> {\n    return await ImageModule.clearMemoryCache();\n  }\n\n  /**\n   * Asynchronously clears all images from the disk cache.\n   * @platform android\n   * @platform ios\n   * @return A promise resolving to `true` when the operation succeeds.\n   * It may resolve to `false` on Android when the activity is no longer available.\n   * Resolves to `false` on Web.\n   */\n  static async clearDiskCache(): Promise<boolean> {\n    return await ImageModule.clearDiskCache();\n  }\n\n  /**\n   * Asynchronously checks if an image exists in the disk cache and resolves to\n   * the path of the cached image if it does.\n   * @param cacheKey - The cache key for the requested image. Unless you have set\n   * a custom cache key, this will be the source URL of the image.\n   * @platform android\n   * @platform ios\n   * @return A promise resolving to the path of the cached image. It will resolve\n   * to `null` if the image does not exist in the cache.\n   */\n  static async getCachePathAsync(cacheKey: string): Promise<string | null> {\n    return await ImageModule.getCachePathAsync(cacheKey);\n  }\n\n  /**\n   * Asynchronously generates a [Blurhash](https://blurha.sh) from an image.\n   * @param url - The URL of the image to generate a blurhash from.\n   * @param numberOfComponents - The number of components to encode the blurhash with.\n   * Must be between 1 and 9. Defaults to `[4, 3]`.\n   * @platform ios\n   * @return A promise resolving to the blurhash string.\n   */\n  static async generateBlurhashAsync(\n    url: string,\n    numberOfComponents: [number, number] | { width: number; height: number }\n  ): Promise<string | null> {\n    return await ImageModule.generateBlurhashAsync(url, numberOfComponents);\n  }\n\n  /**\n   * Asynchronously starts playback of the view's image if it is animated.\n   * @platform android\n   * @platform ios\n   */\n  async startAnimating(): Promise<void> {\n    await this.nativeViewRef.current?.startAnimating();\n  }\n\n  /**\n   * Asynchronously stops the playback of the view's image if it is animated.\n   * @platform android\n   * @platform ios\n   */\n  async stopAnimating(): Promise<void> {\n    await this.nativeViewRef.current?.stopAnimating();\n  }\n\n  /**\n   * Prevents the resource from being reloaded by locking it.\n   * @platform android\n   * @platform ios\n   */\n  async lockResourceAsync(): Promise<void> {\n    await this.nativeViewRef.current?.lockResourceAsync();\n  }\n\n  /**\n   * Releases the lock on the resource, allowing it to be reloaded.\n   * @platform android\n   * @platform ios\n   */\n  async unlockResourceAsync(): Promise<void> {\n    await this.nativeViewRef.current?.unlockResourceAsync();\n  }\n\n  /**\n   * Reloads the resource, ignoring lock.\n   * @platform android\n   * @platform ios\n   */\n  async reloadAsync(): Promise<void> {\n    await this.nativeViewRef.current?.reloadAsync();\n  }\n\n  /**\n   * Loads an image from the given source to memory and resolves to\n   * an object that references the native image instance.\n   * @platform android\n   * @platform ios\n   * @platform web\n   */\n  static async loadAsync(\n    source: ImageSource | string | number,\n    options?: ImageLoadOptions\n  ): Promise<ImageRef> {\n    const resolvedSource = resolveSource(source) as ImageSource;\n    return await ImageModule.loadAsync(resolvedSource, options);\n  }\n\n  render() {\n    const {\n      style,\n      source,\n      placeholder,\n      contentFit,\n      contentPosition,\n      transition,\n      fadeDuration,\n      resizeMode: resizeModeProp,\n      defaultSource,\n      loadingIndicatorSource,\n      ...restProps\n    } = this.props;\n\n    const { resizeMode: resizeModeStyle, ...restStyle } = StyleSheet.flatten(style) || {};\n    const resizeMode = resizeModeProp ?? resizeModeStyle;\n\n    if ((defaultSource || loadingIndicatorSource) && !loggedDefaultSourceDeprecationWarning) {\n      console.warn(\n        '[expo-image]: `defaultSource` and `loadingIndicatorSource` props are deprecated, use `placeholder` instead'\n      );\n      loggedDefaultSourceDeprecationWarning = true;\n    }\n    // @ts-expect-error\n    if (restProps.children && !loggedRenderingChildrenWarning) {\n      console.warn(\n        'The <Image> component does not support children. If you want to render content on top of the image, consider using the <ImageBackground> component or absolute positioning.'\n      );\n      loggedRenderingChildrenWarning = true;\n    }\n    return (\n      <ExpoImage\n        {...restProps}\n        style={restStyle}\n        source={resolveSources(source)}\n        placeholder={resolveSources(placeholder ?? defaultSource ?? loadingIndicatorSource)}\n        contentFit={resolveContentFit(contentFit, resizeMode)}\n        contentPosition={resolveContentPosition(contentPosition)}\n        transition={resolveTransition(transition, fadeDuration)}\n        nativeViewRef={this.nativeViewRef}\n        containerViewRef={this.containerViewRef}\n      />\n    );\n  }\n}\n","import { requireNativeViewManager } from 'expo-modules-core';\nimport React from 'react';\nimport { NativeSyntheticEvent, StyleSheet, Platform, processColor } from 'react-native';\n\nimport {\n  ImageErrorEventData,\n  ImageLoadEventData,\n  ImageNativeProps,\n  ImageProgressEventData,\n} from './Image.types';\n\nconst NativeExpoImage = requireNativeViewManager('ExpoImage');\n\nfunction withDeprecatedNativeEvent<NativeEvent>(\n  event: NativeSyntheticEvent<NativeEvent>\n): NativeEvent {\n  Object.defineProperty(event.nativeEvent, 'nativeEvent', {\n    get() {\n      console.warn(\n        '[expo-image]: Accessing event payload through \"nativeEvent\" is deprecated, it is now part of the event object itself'\n      );\n      return event.nativeEvent;\n    },\n  });\n  return event.nativeEvent;\n}\n\nclass ExpoImage extends React.PureComponent<ImageNativeProps> {\n  // NOTE(@kitten): native methods\n  startAnimating!: () => Promise<unknown> | unknown;\n  stopAnimating!: () => Promise<unknown> | unknown;\n  lockResourceAsync!: () => Promise<void>;\n  unlockResourceAsync!: () => Promise<void>;\n  reloadAsync!: () => Promise<void>;\n\n  onLoadStart = () => {\n    this.props.onLoadStart?.();\n  };\n\n  onLoad = (event: NativeSyntheticEvent<ImageLoadEventData>) => {\n    this.props.onLoad?.(withDeprecatedNativeEvent(event));\n    this.onLoadEnd();\n  };\n\n  onProgress = (event: NativeSyntheticEvent<ImageProgressEventData>) => {\n    this.props.onProgress?.(withDeprecatedNativeEvent(event));\n  };\n\n  onError = (event: NativeSyntheticEvent<ImageErrorEventData>) => {\n    this.props.onError?.(withDeprecatedNativeEvent(event));\n    this.onLoadEnd();\n  };\n\n  onLoadEnd = () => {\n    this.props.onLoadEnd?.();\n  };\n\n  render() {\n    const { style, accessibilityLabel, alt, ...props } = this.props;\n    const resolvedStyle = StyleSheet.flatten(style);\n\n    // Shadows behave different on iOS, Android & Web.\n    // Android uses the `elevation` prop, whereas iOS\n    // and web use the regular `shadow...` props.\n    if (Platform.OS === 'android') {\n      delete resolvedStyle.shadowColor;\n      delete resolvedStyle.shadowOffset;\n      delete resolvedStyle.shadowOpacity;\n      delete resolvedStyle.shadowRadius;\n    } else {\n      // @ts-expect-error\n      delete resolvedStyle.elevation;\n    }\n\n    // @ts-ignore\n    const backgroundColor = processColor(resolvedStyle.backgroundColor);\n    // On Android, we have to set the `backgroundColor` directly on the correct component.\n    // So we have to remove it from styles. Otherwise, the background color won't take into consideration the border-radius.\n    if (Platform.OS === 'android') {\n      delete resolvedStyle.backgroundColor;\n    }\n\n    const tintColor = processColor(props.tintColor || resolvedStyle.tintColor);\n\n    const borderColor = processColor(resolvedStyle.borderColor);\n    // @ts-ignore\n    const borderStartColor = processColor(resolvedStyle.borderStartColor);\n    // @ts-ignore\n    const borderEndColor = processColor(resolvedStyle.borderEndColor);\n    // @ts-ignore\n    const borderLeftColor = processColor(resolvedStyle.borderLeftColor);\n    // @ts-ignore\n    const borderRightColor = processColor(resolvedStyle.borderRightColor);\n    // @ts-ignore\n    const borderTopColor = processColor(resolvedStyle.borderTopColor);\n    // @ts-ignore\n    const borderBottomColor = processColor(resolvedStyle.borderBottomColor);\n\n    return (\n      <NativeExpoImage\n        {...props}\n        {...resolvedStyle}\n        accessibilityLabel={accessibilityLabel ?? alt}\n        style={resolvedStyle}\n        onLoadStart={this.onLoadStart}\n        onLoad={this.onLoad}\n        onProgress={this.onProgress}\n        onError={this.onError}\n        tintColor={tintColor}\n        borderColor={borderColor}\n        borderLeftColor={borderLeftColor}\n        borderRightColor={borderRightColor}\n        borderTopColor={borderTopColor}\n        borderBottomColor={borderBottomColor}\n        borderStartColor={borderStartColor}\n        borderEndColor={borderEndColor}\n        backgroundColor={backgroundColor}\n        ref={props.nativeViewRef}\n      />\n    );\n  }\n}\n\nexport default ExpoImage;\n","import { requireNativeModule } from 'expo';\n\nimport type { ImageNativeModule } from './Image.types';\n\nexport default requireNativeModule<ImageNativeModule>('ExpoImage');\n","import { SharedRef } from 'expo';\nimport type { SharedRefType } from 'expo';\nimport { type ImageResizeMode } from 'react-native';\n\nimport {\n  ImageContentFit,\n  ImageContentPosition,\n  ImageContentPositionObject,\n  ImageContentPositionString,\n  ImageProps,\n  ImageTransition,\n} from './Image.types';\n\nlet loggedResizeModeDeprecationWarning = false;\nlet loggedRepeatDeprecationWarning = false;\nlet loggedFadeDurationDeprecationWarning = false;\n\n/**\n * If the `contentFit` is not provided, it's resolved from the equivalent `resizeMode` prop\n * that we support to provide compatibility with React Native Image.\n */\nexport function resolveContentFit(\n  contentFit?: ImageContentFit,\n  resizeMode?: ImageResizeMode\n): ImageContentFit {\n  if (contentFit) {\n    return contentFit;\n  }\n  if (resizeMode) {\n    if (!loggedResizeModeDeprecationWarning) {\n      console.log('[expo-image]: Prop \"resizeMode\" is deprecated, use \"contentFit\" instead');\n      loggedResizeModeDeprecationWarning = true;\n    }\n\n    switch (resizeMode) {\n      case 'contain':\n      case 'cover':\n      case 'none':\n        return resizeMode;\n      case 'stretch':\n        return 'fill';\n      case 'center':\n        return 'scale-down';\n      case 'repeat':\n        if (!loggedRepeatDeprecationWarning) {\n          console.log('[expo-image]: Resize mode \"repeat\" is no longer supported');\n          loggedRepeatDeprecationWarning = true;\n        }\n        return 'cover';\n      default: {\n        const exhaustiveCheck: never = resizeMode;\n        throw new Error(`Unhandled resizeMode case: ${exhaustiveCheck}`);\n      }\n    }\n  }\n  return 'cover';\n}\n\n/**\n * It resolves a stringified form of the `contentPosition` prop to an object,\n * which is the only form supported in the native code.\n */\nexport function resolveContentPosition(\n  contentPosition?: ImageContentPosition\n): ImageContentPositionObject {\n  if (typeof contentPosition === 'string') {\n    const contentPositionStringMappings: Record<\n      ImageContentPositionString,\n      ImageContentPositionObject\n    > = {\n      center: { top: '50%', left: '50%' },\n      top: { top: 0, left: '50%' },\n      right: { top: '50%', right: 0 },\n      bottom: { bottom: 0, left: '50%' },\n      left: { top: '50%', left: 0 },\n      'top center': { top: 0, left: '50%' },\n      'top right': { top: 0, right: 0 },\n      'top left': { top: 0, left: 0 },\n      'right center': { top: '50%', right: 0 },\n      'right top': { top: 0, right: 0 },\n      'right bottom': { bottom: 0, right: 0 },\n      'bottom center': { bottom: 0, left: '50%' },\n      'bottom right': { bottom: 0, right: 0 },\n      'bottom left': { bottom: 0, left: 0 },\n      'left center': { top: '50%', left: 0 },\n      'left top': { top: 0, left: 0 },\n      'left bottom': { bottom: 0, left: 0 },\n    };\n    const contentPositionObject = contentPositionStringMappings[contentPosition];\n\n    if (!contentPositionObject) {\n      console.warn(`[expo-image]: Content position \"${contentPosition}\" is invalid`);\n      return contentPositionStringMappings.center;\n    }\n    return contentPositionObject;\n  }\n  return contentPosition ?? { top: '50%', left: '50%' };\n}\n\n/**\n * If `transition` or `fadeDuration` is a number, it's resolved to a cross dissolve transition with the given duration.\n * When `fadeDuration` is used, it logs an appropriate deprecation warning.\n */\nexport function resolveTransition(\n  transition?: ImageProps['transition'],\n  fadeDuration?: ImageProps['fadeDuration']\n): ImageTransition | null {\n  if (typeof transition === 'number') {\n    return { duration: transition };\n  }\n  if (!transition && typeof fadeDuration === 'number') {\n    if (!loggedFadeDurationDeprecationWarning) {\n      console.warn('[expo-image]: Prop \"fadeDuration\" is deprecated, use \"transition\" instead');\n      loggedFadeDurationDeprecationWarning = true;\n    }\n    return { duration: fadeDuration };\n  }\n  return transition ?? null;\n}\n\n/**\n * Checks whether the given value is an instance of the `SharedRef<'image'>` class.\n */\nexport function isImageRef(value: any): value is SharedRefType<'image'> {\n  return value instanceof SharedRef && value.nativeRefType === 'image';\n}\n","import { Platform } from 'expo-modules-core';\n\nimport resolveAssetSource from './resolveAssetSource';\nimport { resolveBlurhashString, resolveThumbhashString } from './resolveHashString';\nimport { ImageNativeProps, ImageProps, ImageSource } from '../Image.types';\nimport { isImageRef } from '../utils';\n\nexport function isBlurhashString(str: string): boolean {\n  return /^(blurhash:\\/)+[\\w#$%*+,\\-.:;=?@[\\]^_{}|~]+(\\/[\\d.]+)*$/.test(str);\n}\n\n// Base64 strings will be recognized as blurhash by default (to keep compatibility),\n// interpret as thumbhash only if correct uri scheme is provided\nexport function isThumbhashString(str: string): boolean {\n  return str.startsWith('thumbhash:/');\n}\n\nexport function resolveSource(source?: ImageSource | string | number | null): ImageSource | null {\n  if (typeof source === 'string') {\n    if (isBlurhashString(source)) {\n      return resolveBlurhashString(source);\n    } else if (isThumbhashString(source)) {\n      return resolveThumbhashString(source);\n    }\n    return { uri: source };\n  }\n  if (typeof source === 'number') {\n    return resolveAssetSource(source);\n  }\n  if (typeof source === 'object' && (source?.blurhash || source?.thumbhash)) {\n    const { blurhash, thumbhash, ...restSource } = source;\n    const resolved = thumbhash\n      ? resolveThumbhashString(thumbhash)\n      : resolveBlurhashString(blurhash as string);\n    return {\n      ...resolved,\n      ...restSource,\n    };\n  }\n  return source ?? null;\n}\n\n/**\n * Resolves provided `source` prop to an array of objects expected by the native implementation.\n */\nexport function resolveSources(sources?: ImageProps['source']): ImageNativeProps['source'] {\n  if (Array.isArray(sources)) {\n    return sources.map(resolveSource).filter(Boolean) as ImageSource[];\n  }\n  if (isImageRef(sources)) {\n    if (Platform.OS === 'web') {\n      return sources;\n    }\n    // @ts-expect-error\n    return sources.__expo_shared_object_id__;\n  }\n  return [resolveSource(sources)].filter(Boolean) as ImageSource[];\n}\n","import resolveAssetSource from 'react-native/Libraries/Image/resolveAssetSource';\n\nexport default resolveAssetSource;\n","import { ImageSource } from '../Image.types';\n\ntype ImageHashType = 'blurhash' | 'thumbhash';\n\nfunction hashToUri(type: ImageHashType, hash: string): string {\n  const encodedBlurhash = encodeURI(hash).replace(/#/g, '%23').replace(/\\?/g, '%3F');\n  return `${type}:/${encodedBlurhash}`;\n}\n\n/**\n * Converts a blurhash string (`blurhash:/<hash>/<width>/<height>` or <hash>/<width>/<height>) into an `ImageSource`.\n *\n * @return An ImageSource representing the provided blurhash.\n * */\nexport function resolveBlurhashString(str: string): ImageSource {\n  const [blurhash, width, height] = str.replace(/^blurhash:\\//, '').split('/');\n  return {\n    uri: hashToUri('blurhash', blurhash),\n    width: parseInt(width, 10) || 16,\n    height: parseInt(height, 10) || 16,\n  };\n}\n\n/**\n * Converts a thumbhash string (`thumbhash:/<hash>` or `<hash>`) into an `ImageSource`.\n *\n * @return An ImageSource representing the provided thumbhash.\n * */\nexport function resolveThumbhashString(str: string): ImageSource {\n  // ThumbHash may contain slashes that could break the url when the slash is at the beginning.\n  // We replace slashes with backslashes to make sure we don't break the url's path.\n  const thumbhash = str.replace(/^thumbhash:\\//, '').replace(/\\//g, '\\\\');\n  return {\n    uri: hashToUri('thumbhash', thumbhash),\n  };\n}\n","'use client';\n\nimport React from 'react';\nimport { View, StyleSheet } from 'react-native';\n\nimport { Image } from './Image';\nimport { ImageBackgroundProps } from './Image.types';\n\nexport function ImageBackground({ style, imageStyle, children, ...props }: ImageBackgroundProps) {\n  return (\n    <View style={style}>\n      <Image {...props} style={[StyleSheet.absoluteFill, imageStyle]} />\n      {children}\n    </View>\n  );\n}\n","'use client';\n\nimport { DependencyList, useEffect, useRef, useState } from 'react';\n\nimport { Image } from './Image';\nimport type { ImageLoadOptions, ImageRef, ImageSource } from './Image.types';\nimport { resolveSource } from './utils/resolveSources';\n\n/**\n * A hook that loads an image from the given source and returns a reference\n * to the native image instance, or `null` until the first image is successfully loaded.\n *\n * It loads a new image every time the `uri` of the provided source changes.\n * To trigger reloads in some other scenarios, you can provide an additional dependency list.\n * @platform android\n * @platform ios\n * @platform web\n *\n * @example\n * ```ts\n * import { useImage, Image } from 'expo-image';\n * import { Text } from 'react-native';\n *\n * export default function MyImage() {\n *   const image = useImage('https://picsum.photos/1000/800', {\n *     maxWidth: 800,\n *     onError(error, retry) {\n *       console.error('Loading failed:', error.message);\n *     }\n *   });\n *\n *   if (!image) {\n *     return <Text>Image is loading...</Text>;\n *   }\n *\n *   return <Image source={image} style={{ width: image.width / 2, height: image.height / 2 }} />;\n * }\n * ```\n */\nexport function useImage(\n  source: ImageSource | string | number,\n  options: ImageLoadOptions = {},\n  dependencies: DependencyList = []\n): ImageRef | null {\n  const resolvedSource = resolveSource(source) as ImageSource;\n  const [image, setImage] = useState<ImageRef | null>(null);\n\n  // Since options are not dependencies of the below effect, we store them in a ref.\n  // Once the image is asynchronously loaded, the effect will use the most recent options,\n  // instead of the captured ones (especially important for callbacks that may change in subsequent renders).\n  const optionsRef = useRef<ImageLoadOptions>(options);\n  optionsRef.current = options;\n\n  useEffect(() => {\n    // We're doing some asynchronous action in this effect, so we should keep track\n    // if the effect was already cleaned up. In that case, the async action shouldn't change the state.\n    let isEffectValid = true;\n\n    function loadImage() {\n      Image.loadAsync(resolvedSource, options)\n        .then((image) => {\n          if (isEffectValid) {\n            setImage(image);\n          }\n        })\n        .catch((error) => {\n          if (!isEffectValid) {\n            return;\n          }\n          if (optionsRef.current.onError) {\n            optionsRef.current.onError(error, loadImage);\n          } else {\n            // Print unhandled errors to the console.\n            console.error(\n              `Loading an image from '${resolvedSource.uri}' failed, use 'onError' option to handle errors and suppress this message`\n            );\n            console.error(error);\n          }\n        });\n    }\n\n    loadImage();\n\n    return () => {\n      // Invalidate the effect and release the shared object to free up memory.\n      isEffectValid = false;\n      image?.release();\n    };\n  }, [resolvedSource.uri, ...dependencies]);\n\n  return image;\n}\n","/**\n * Badges de monetización del kit (rental): FeaturedBadge, PremiumBadge,\n * VerificationBadge (niveles 1-3). Construidos sobre el Badge genérico.\n */\n\nimport React from 'react';\nimport { Badge } from './Badge';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport function FeaturedBadge({ size = 'normal' }: { size?: 'normal' | 'small' }) {\n  return (\n    <Badge\n      label=\"★ Destacado\"\n      backgroundColor={brand.warning}\n      textColor={brand.warningText}\n      size={size}\n      accessibilityLabel=\"Anuncio destacado\"\n    />\n  );\n}\n\nexport function PremiumBadge({ size = 'normal' }: { size?: 'normal' | 'small' }) {\n  return (\n    <Badge\n      label=\"♛ Premium\"\n      backgroundColor={brand.warningPressed}\n      textColor={brand.white}\n      size={size}\n      accessibilityLabel=\"Anuncio premium\"\n    />\n  );\n}\n\nexport const VERIFICATION_LEVELS = {\n  PHONE_ONLY: 1,\n  VERIFIED: 2,\n  ADVANCED: 3,\n} as const;\n\nconst getVerificationConfig = (level: number) => {\n  switch (level) {\n    case VERIFICATION_LEVELS.VERIFIED:\n      return {\n        label: '✓ Verificado',\n        backgroundColor: brand.infoPressed,\n        textColor: brand.white,\n        accessibilityLabel: 'Anunciante verificado',\n      };\n    case VERIFICATION_LEVELS.ADVANCED:\n      return {\n        label: '✓✓ Verificación avanzada',\n        backgroundColor: brand.success,\n        textColor: brand.white,\n        accessibilityLabel: 'Anunciante con verificación avanzada',\n      };\n    case VERIFICATION_LEVELS.PHONE_ONLY:\n    default:\n      return {\n        label: 'Teléfono',\n        backgroundColor: '#e2e8f0',\n        textColor: '#334155',\n        accessibilityLabel: 'Anunciante con teléfono registrado',\n      };\n  }\n};\n\nexport function VerificationBadge({\n  level = VERIFICATION_LEVELS.PHONE_ONLY,\n  size = 'normal',\n  minLevel = VERIFICATION_LEVELS.PHONE_ONLY,\n}: {\n  level?: number;\n  size?: 'normal' | 'small';\n  minLevel?: number;\n}) {\n  if (level < minLevel) return null;\n  const config = getVerificationConfig(level);\n  return (\n    <Badge\n      label={config.label}\n      backgroundColor={config.backgroundColor}\n      textColor={config.textColor}\n      size={size}\n      accessibilityLabel={config.accessibilityLabel}\n    />\n  );\n}\n","/**\n * Badge — etiqueta genérica del kit (rental), adaptada a TS + useTheme.\n * backgroundColor/textColor configurables; tamaño normal | small.\n */\n\nimport React from 'react';\nimport { StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\n\nexport function Badge({\n  label,\n  backgroundColor,\n  textColor,\n  size = 'normal',\n  style,\n  accessibilityLabel,\n}: {\n  label: string;\n  backgroundColor?: string;\n  textColor?: string;\n  size?: 'normal' | 'small';\n  style?: StyleProp<ViewStyle>;\n  accessibilityLabel?: string;\n}) {\n  const { colors } = useTheme();\n  const isSmall = size === 'small';\n  return (\n    <View\n      style={[\n        styles.badge,\n        { backgroundColor: backgroundColor ?? colors.surface },\n        isSmall && styles.badgeSmall,\n        style,\n      ]}\n      accessibilityRole=\"text\"\n      accessibilityLabel={accessibilityLabel || label}\n    >\n      <Text\n        style={[\n          styles.text,\n          { color: textColor ?? colors.textPrimary },\n          isSmall && styles.textSmall,\n        ]}\n        numberOfLines={1}\n        adjustsFontSizeToFit\n      >\n        {label}\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  badge: {\n    paddingHorizontal: espaciado.e8,\n    paddingVertical: espaciado.e4,\n    borderRadius: 6,\n    alignSelf: 'flex-start',\n    flexDirection: 'row',\n    alignItems: 'center',\n  },\n  badgeSmall: { paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2, borderRadius: 5 },\n  text: { fontSize: tipografia.micro, fontWeight: '700', lineHeight: 14 },\n  textSmall: { fontSize: 10, lineHeight: 12 },\n});\n","/**\n * PriceCalculator — calculadora de coste mensual real (kit rental).\n * Renta + estimaciones de electricidad (por tamaño y personas), agua,\n * internet y generador/apoyo energético. Solo para largo plazo con renta;\n * no aplica a terrenos ni corto plazo exclusivo.\n */\n\nimport React, { useMemo, useState } from 'react';\nimport { Pressable, StyleSheet, Text, TextInput, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport type { RentalProperty } from '../../api/rental';\nimport { formatXAF, isLandType } from '../../utils/formatHelpers';\n\nconst MIN_PEOPLE = 1;\nconst MAX_PEOPLE = 10;\n\nconst UTILITY_ESTIMATES = {\n  electricityBase: 15000,\n  electricityMedium: 25000,\n  electricityLarge: 35000,\n  electricityPerExtraPerson: 4000,\n  waterBase: 8000,\n  waterPerExtraPerson: 2000,\n  internet: 25000,\n  generatorNormal: 12000,\n  generatorHigh: 30000,\n  noGeneratorHighSupport: 45000,\n  defaultSize: 60,\n};\n\nconst safeNumber = (value: unknown, fallback = 0): number => {\n  const parsed = Number(value);\n  return Number.isFinite(parsed) ? parsed : fallback;\n};\n\nconst clampPeople = (value: string): number => {\n  const parsed = parseInt(value, 10);\n  if (Number.isNaN(parsed)) return MIN_PEOPLE;\n  return Math.min(MAX_PEOPLE, Math.max(MIN_PEOPLE, parsed));\n};\n\nconst Row = ({ label, value }: { label: string; value: string }) => {\n  const { colors } = useTheme();\n  return (\n    <View style={[rowStyles.row, { borderBottomColor: colors.border }]}>\n      <Text style={[rowStyles.label, { color: colors.textSecondary }]}>{label}</Text>\n      <Text style={[rowStyles.value, { color: colors.textPrimary }]}>{value}</Text>\n    </View>\n  );\n};\n\nexport function PriceCalculator({ property, style }: { property: RentalProperty; style?: StyleProp<ViewStyle> }) {\n  const { colors } = useTheme();\n  const config = UTILITY_ESTIMATES;\n\n  const rent = safeNumber(property?.price?.monthlyRent, 0);\n  const isLand = isLandType(property?.type ?? '');\n  const isShortTermOnly = property?.rentalType === 'short_term';\n  const hasGenerator = Boolean(property?.essentialServices?.generator);\n  const initialInternet = Boolean(property?.essentialServices?.internet ?? false);\n\n  const [peopleInput, setPeopleInput] = useState('2');\n  const [includeInternet, setIncludeInternet] = useState(initialInternet);\n  const [highEnergyUse, setHighEnergyUse] = useState(false);\n\n  const people = clampPeople(peopleInput);\n\n  const estimates = useMemo(() => {\n    const size = safeNumber(property?.size ?? property?.landSize, config.defaultSize);\n\n    let electricity = config.electricityBase;\n    if (size > 150) electricity = config.electricityLarge;\n    else if (size > 100) electricity = config.electricityMedium;\n    electricity += (people - 1) * config.electricityPerExtraPerson;\n\n    const water = config.waterBase + (people - 1) * config.waterPerExtraPerson;\n    const internet = includeInternet ? config.internet : 0;\n\n    let energySupport = 0;\n    if (hasGenerator) energySupport = highEnergyUse ? config.generatorHigh : config.generatorNormal;\n    else if (highEnergyUse) energySupport = config.noGeneratorHighSupport;\n\n    return { electricity, water, internet, energySupport, total: rent + electricity + water + internet + energySupport };\n  }, [property?.size, property?.landSize, people, includeInternet, highEnergyUse, hasGenerator, rent, config]);\n\n  if (!property || isLand || isShortTermOnly || rent <= 0) return null;\n\n  const handlePeopleChange = (text: string) => {\n    const cleaned = text.replace(/[^0-9]/g, '');\n    setPeopleInput(cleaned.slice(0, 2));\n  };\n\n  const s = styles(colors);\n  return (\n    <View style={[s.container, { borderColor: colors.border }, style]}>\n      <Text style={[s.title, { color: colors.textPrimary }]}>Calcula tu coste mensual real</Text>\n      <Text style={[s.subtitle, { color: colors.textSecondary }]}>Estimación orientativa para Malabo / Bata</Text>\n\n      {/* Controles */}\n      <View style={s.controls}>\n        <View style={s.controlRow}>\n          <Text style={[s.controlLabel, { color: colors.textPrimary }]}>Personas en la vivienda</Text>\n          <TextInput\n            style={[s.input, { backgroundColor: colors.card, borderColor: colors.border, color: colors.textPrimary }]}\n            value={peopleInput}\n            onChangeText={handlePeopleChange}\n            keyboardType=\"numeric\"\n            maxLength={2}\n            accessibilityLabel=\"Número de personas en la vivienda\"\n          />\n        </View>\n\n        <ToggleRow\n          label=\"Incluir Internet\"\n          value={includeInternet}\n          onPress={() => setIncludeInternet((p) => !p)}\n          activeText=\"Sí\"\n          inactiveText=\"No\"\n        />\n\n        <ToggleRow\n          label={hasGenerator ? 'Uso frecuente de generador' : 'Apoyo energético por cortes'}\n          value={highEnergyUse}\n          onPress={() => setHighEnergyUse((p) => !p)}\n          activeText=\"Alto\"\n          inactiveText=\"Normal\"\n        />\n      </View>\n\n      {/* Desglose */}\n      <View style={[s.breakdown, { backgroundColor: colors.card }]}>\n        <Row label=\"Renta\" value={formatXAF(rent)} />\n        <Row label=\"Electricidad (estimada)\" value={formatXAF(estimates.electricity)} />\n        <Row label=\"Agua\" value={formatXAF(estimates.water)} />\n        <Row label=\"Internet\" value={formatXAF(estimates.internet)} />\n        <Row\n          label={hasGenerator ? 'Generador / combustible' : 'Apoyo energético (estimado)'}\n          value={formatXAF(estimates.energySupport)}\n        />\n        <View style={[s.totalRow, { borderTopColor: colors.border }]}>\n          <Text style={[s.totalLabel, { color: colors.textPrimary }]}>Total estimado / mes</Text>\n          <Text style={[s.totalValue, { color: colors.primary }]}>{formatXAF(estimates.total)}</Text>\n        </View>\n      </View>\n\n      <Text style={[s.disclaimer, { color: colors.textSecondary }]}>\n        * Los valores de luz, agua e internet son estimaciones medias. Pueden variar según consumo real, zona y tarifas del proveedor.\n      </Text>\n    </View>\n  );\n}\n\nfunction ToggleRow({ label, value, onPress, activeText, inactiveText }: { label: string; value: boolean; onPress: () => void; activeText: string; inactiveText: string }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable style={({ pressed }) => [s2.toggleRow, pressed && { opacity: 0.7 }]} onPress={onPress} accessibilityRole=\"switch\" accessibilityState={{ checked: value }}>\n      <Text style={[s2.controlLabel, { color: colors.textPrimary }]}>{label}</Text>\n      <View style={[s2.toggle, { backgroundColor: value ? colors.primary : colors.border }]}>\n        <Text style={[s2.toggleText, !value && { color: colors.textSecondary }]}>{value ? activeText : inactiveText}</Text>\n      </View>\n    </Pressable>\n  );\n}\n\nconst s2 = StyleSheet.create({\n  toggleRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: espaciado.e10 },\n  controlLabel: { fontSize: tipografia.body, flex: 1, marginRight: espaciado.e12 },\n  toggle: { paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, borderRadius: 20, minWidth: 64, alignItems: 'center' },\n  toggleText: { fontSize: tipografia.body, fontWeight: '600', color: brand.white },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  container: { borderRadius: 14, padding: espaciado.e16, marginBottom: espaciado.e20, borderWidth: 1, backgroundColor: c.surface },\n  title: { fontSize: tipografia.subtitle, fontWeight: '700', marginBottom: espaciado.e4 },\n  subtitle: { fontSize: tipografia.caption, marginBottom: espaciado.e14 },\n  controls: { marginBottom: espaciado.e16 },\n  controlRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: espaciado.e12 },\n  controlLabel: { fontSize: tipografia.body, flex: 1, marginRight: espaciado.e12 },\n  input: { borderWidth: 1, borderRadius: radios.sm, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, width: 60, textAlign: 'center', fontSize: 15, fontWeight: '600' },\n  breakdown: { borderRadius: 10, padding: espaciado.e14 },\n  totalRow: { flexDirection: 'row', justifyContent: 'space-between', paddingTop: espaciado.e12, marginTop: espaciado.e4, gap: espaciado.e12, borderTopWidth: 1 },\n  totalLabel: { fontSize: 15, fontWeight: '700', flex: 1 },\n  totalValue: { fontSize: tipografia.subtitle, fontWeight: '800' },\n  disclaimer: { fontSize: tipografia.micro, marginTop: espaciado.e12, lineHeight: 16 },\n});\n\nconst rowStyles = StyleSheet.create({\n  row: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: espaciado.e8, borderBottomWidth: 1, gap: espaciado.e12 },\n  label: { fontSize: tipografia.body, flex: 1 },\n  value: { fontSize: tipografia.body, fontWeight: '600' },\n});\n","/**\n * formatHelpers — utilidades de formato del kit (rental).\n * formatXAF, getTimeAgo, getPropertyTypeLabel, getWhatsAppUrl,\n * formatDate, formatDateTime, getInitials, formatDistanceKm, normalizePhone.\n */\n\nconst MONTHS_SHORT = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];\n\n/** Normaliza un teléfono: quita prefijo, espacios y guiones (solo dígitos). */\nexport function normalizePhone(phone: string | null | undefined): string {\n  return String(phone ?? '').replace(/\\D/g, '');\n}\n\n/** Fecha completa corta: 12 mar 2026. */\nexport function formatDate(date: string | Date | null | undefined): string {\n  if (!date) return '';\n  const d = new Date(date);\n  if (isNaN(d.getTime())) return '';\n  return `${d.getDate()} ${MONTHS_SHORT[d.getMonth()]} ${d.getFullYear()}`;\n}\n\n/** Fecha y hora: 12 mar 2026, 14:30. */\nexport function formatDateTime(date: string | Date | null | undefined): string {\n  if (!date) return '';\n  const d = new Date(date);\n  if (isNaN(d.getTime())) return '';\n  const hh = String(d.getHours()).padStart(2, '0');\n  const mm = String(d.getMinutes()).padStart(2, '0');\n  return `${formatDate(d)}, ${hh}:${mm}`;\n}\n\n/** Iniciales para avatares (máx. 2): \"Pedro Obiang\" → \"PO\". */\nexport function getInitials(name: string | null | undefined): string {\n  const parts = String(name ?? '').trim().split(/\\s+/).filter(Boolean);\n  if (parts.length === 0) return '?';\n  if (parts.length === 1) return parts[0].charAt(0).toUpperCase();\n  return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();\n}\n\n/** Distancia formateada: 1.2 km. */\nexport function formatDistanceKm(distance: number | string | null | undefined): string {\n  const n = typeof distance === 'string' ? parseFloat(distance) : Number(distance ?? NaN);\n  if (isNaN(n)) return '';\n  if (n < 1) return `${Math.round(n * 1000)} m`;\n  return `${n.toFixed(1)} km`;\n}\n\n/**\n * Importe en francos CFA. La regla de formato vive ahora en el kit (`format/moneda.ts`) y aquí solo\n * se reexporta con el nombre de siempre para no tocar las decenas de sitios que la importan.\n *\n * POR QUÉ SE MOVIÓ: este fichero formateaba por su cuenta con un espacio NORMAL entre la cifra y la\n * unidad, y un espacio normal es un punto de corte válido: en cualquier caja estrecha el precio se\n * partía en dos líneas («6.500» / «XAF»). Se vio en el carrusel de recomendados del Mercado. La\n * unidad y la cifra son un solo importe, así que van unidas con espacio duro y la regla se escribe\n * una vez.\n *\n * Se importa Y se reexporta: `getWhatsAppUrl` lo usa más abajo, y un `export … from` no trae el\n * nombre al ámbito de este módulo. Reexportar sin importar dejó dos llamadas sin resolver.\n */\nimport { formateaXAF as formatXAF } from '@egrouteplan/ui-kit';\nexport { formatXAF };\n\nexport function getTimeAgo(date: string | Date | null | undefined): string {\n  if (!date) return '';\n  const ms = Date.now() - new Date(date).getTime();\n  const minutes = Math.floor(ms / 60000);\n  if (minutes < 1) return 'ahora';\n  if (minutes < 60) return `hace ${minutes} min`;\n  const hours = Math.floor(minutes / 60);\n  if (hours < 24) return `hace ${hours} h`;\n  const days = Math.floor(hours / 24);\n  if (days < 30) return `hace ${days} d`;\n  const months = Math.floor(days / 30);\n  if (months < 12) return `hace ${months} mes${months > 1 ? 'es' : ''}`;\n  const years = Math.floor(months / 12);\n  return `hace ${years} año${years > 1 ? 's' : ''}`;\n}\n\nconst TYPE_LABELS: Record<string, { label: string; emoji: string }> = {\n  apartment: { label: 'Apartamento', emoji: '🏢' },\n  house: { label: 'Casa', emoji: '🏠' },\n  room: { label: 'Habitación', emoji: '🚪' },\n  villa: { label: 'Villa', emoji: '🏡' },\n  studio: { label: 'Estudio', emoji: '🛋️' },\n  office: { label: 'Oficina', emoji: '🏢' },\n  commercial: { label: 'Local comercial', emoji: '🏬' },\n  bar: { label: 'Bar / Terraza', emoji: '🍻' },\n  nightclub: { label: 'Discoteca', emoji: '🎵' },\n  land_agriculture: { label: 'Terreno agrícola', emoji: '🌱' },\n  land_workshop: { label: 'Terreno taller', emoji: '🔧' },\n  land_other: { label: 'Otro terreno', emoji: '⛰️' },\n};\n\nexport function getPropertyTypeLabel(type: string): string {\n  return TYPE_LABELS[type]?.label ?? type;\n}\n\nexport function getPropertyTypeEmoji(type: string): string {\n  return TYPE_LABELS[type]?.emoji ?? '🏠';\n}\n\nexport function isLandType(type: string): boolean {\n  return type === 'land_agriculture' || type === 'land_workshop' || type === 'land_other';\n}\n\nexport function isCommercialSpecial(type: string): boolean {\n  return type === 'bar' || type === 'nightclub';\n}\n\n/** URL de WhatsApp con mensaje pre-rellenado sobre la propiedad (kit). */\nexport function getWhatsAppUrl(phone: string | null | undefined, property: { title?: string; location?: { neighborhood?: string; cityName?: string }; price?: { monthlyRent?: number | null; pricePerNight?: number | null; } } | null | undefined): string {\n  const p = normalizePhone(phone);\n  if (!p) return 'https://wa.me/';\n  let msg = 'Hola, vi este anuncio en EG Route Plan';\n  if (property?.title) msg += `: ${property.title}`;\n  if (property?.location?.neighborhood) msg += ` (${property.location.neighborhood}${property.location.cityName ? ', ' + property.location.cityName : ''})`;\n  if (property?.price?.monthlyRent) msg += ` — ${formatXAF(property.price.monthlyRent)}/mes`;\n  else if (property?.price?.pricePerNight) msg += ` — ${formatXAF(property.price.pricePerNight)}/noche`;\n  return `https://wa.me/${p}?text=${encodeURIComponent(msg)}`;\n}\n","/**\n * LandlordCard — tarjeta del arrendador (kit rental), variantes detail | compact.\n * Avatar (foto o iniciales), verificación, rating, stats (respuesta/anuncios/\n * miembro desde), bio, acciones (ver perfil / llamar / WhatsApp) y nota de\n * confianza. Adaptada: useTheme, getInitials/formatDate, isAgency (no type).\n */\n\nimport React from 'react';\nimport { Alert, Image, Linking, Pressable, StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { VerificationBadge } from './Badges';\nimport { getInitials } from '../../utils/formatHelpers';\nimport type { RentalProperty } from '../../api/rental';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport interface LandlordCardData {\n  id?: string | null;\n  name?: string | null;\n  photo?: string | null;\n  avatarUrl?: string | null;\n  photoUrl?: string | null;\n  isAgency?: boolean;\n  type?: string;\n  rating?: number | null;\n  reviewsCount?: number | null;\n  reviews?: number | null;\n  responseTimeHours?: number | null;\n  listingsCount?: number | null;\n  activeListingsCount?: number | null;\n  propertiesCount?: number | null;\n  memberSince?: string | null;\n  joinedAt?: string | null;\n  verificationLevel?: number;\n  phone?: string | null;\n  whatsapp?: string | null;\n  bio?: string | null;\n  description?: string | null;\n  agencyName?: string | null;\n}\n\nconst DEFAULT_TEXTS = {\n  defaultName: 'Anunciante',\n  landlord: 'Propietario',\n  agency: 'Agencia',\n  view: 'Ver',\n  viewProfile: 'Ver perfil',\n  call: 'Llamar',\n  whatsapp: 'WhatsApp',\n  response: 'Respuesta',\n  listings: 'Anuncios',\n  memberSince: 'Miembro',\n  responds: 'Responde',\n  unavailablePhone: 'Este anunciante no tiene teléfono disponible.',\n  unavailableWhatsApp: 'Este anunciante no tiene WhatsApp disponible.',\n  callError: 'No se pudo realizar la llamada.',\n  whatsappError: 'No se pudo abrir WhatsApp.',\n  trustNote: 'Consejo de seguridad: verifica la propiedad y evita pagos fuera de la plataforma.',\n};\n\nconst normalizePhone = (phone: string | null | undefined): string => String(phone ?? '').replace(/\\D/g, '');\n\nconst buildWhatsAppUrl = (phone: string | null | undefined, message: string): string | null => {\n  const clean = normalizePhone(phone);\n  if (!clean) return null;\n  return `https://wa.me/${clean}?text=${encodeURIComponent(message)}`;\n};\n\nconst getMemberSinceLabel = (value: string | null | undefined): string | null => {\n  if (!value) return null;\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) return null;\n  const currentYear = new Date().getFullYear();\n  const year = date.getFullYear();\n  return currentYear === year ? 'Este año' : `Desde ${year}`;\n};\n\nconst getResponseValue = (hours: number | null | undefined): string => {\n  if (hours == null) return '—';\n  const value = Number(hours);\n  if (!Number.isFinite(value)) return '—';\n  if (value <= 0.5) return 'Min';\n  if (value < 1) return '< 1 h';\n  return `~${Math.round(value)} h`;\n};\n\nconst Stat = ({ value, label }: { value: string; label: string }) => {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.statItem}>\n      <Text style={[styles.statValue, { color: colors.textPrimary }]}>{value ?? '—'}</Text>\n      <Text style={[styles.statLabel, { color: colors.textSecondary }]}>{label}</Text>\n    </View>\n  );\n};\n\nexport function LandlordCard({\n  landlord,\n  property,\n  variant = 'detail',\n  showViewProfile = true,\n  showContactActions = false,\n  onViewProfile,\n  onCall,\n  onWhatsApp,\n  texts = {},\n  style,\n}: {\n  landlord: LandlordCardData | null;\n  property?: RentalProperty | null;\n  variant?: 'detail' | 'compact';\n  showViewProfile?: boolean;\n  showContactActions?: boolean;\n  onViewProfile?: (landlord: LandlordCardData) => void;\n  onCall?: (landlord: LandlordCardData) => void;\n  onWhatsApp?: (landlord: LandlordCardData) => void;\n  texts?: Partial<typeof DEFAULT_TEXTS>;\n  style?: StyleProp<ViewStyle>;\n}) {\n  const { colors } = useTheme();\n  if (!landlord) return null;\n\n  const t = { ...DEFAULT_TEXTS, ...texts };\n  const name = landlord.name || t.defaultName;\n  const subtitle = landlord.isAgency || landlord.type === 'agency' ? (landlord.agencyName ?? t.agency) : t.landlord;\n  const initials = getInitials(name);\n  const avatarUri = landlord.avatarUrl || landlord.photoUrl || landlord.photo || null;\n\n  const rating = typeof landlord.rating === 'number' ? landlord.rating.toFixed(1) : null;\n  const reviewsCount = landlord.reviewsCount ?? landlord.reviews ?? null;\n  const listingsCount = landlord.listingsCount ?? landlord.activeListingsCount ?? landlord.propertiesCount ?? null;\n  const memberSince = getMemberSinceLabel(landlord.memberSince ?? landlord.joinedAt);\n  const responseValue = getResponseValue(landlord.responseTimeHours);\n\n  const canViewProfile = Boolean(onViewProfile);\n  const canCall = Boolean(onCall || landlord.phone);\n  const canWhatsApp = Boolean(onWhatsApp || landlord.whatsapp || landlord.phone);\n\n  const handleViewProfile = () => onViewProfile?.(landlord);\n\n  const handleCall = () => {\n    if (onCall) { onCall(landlord); return; }\n    const phone = landlord.phone;\n    if (!phone) { Alert.alert(t.call, t.unavailablePhone); return; }\n    Linking.openURL(`tel:${String(phone).trim()}`).catch(() => Alert.alert(t.call, t.callError));\n  };\n\n  const handleWhatsApp = () => {\n    if (onWhatsApp) { onWhatsApp(landlord); return; }\n    const phone = landlord.whatsapp || landlord.phone;\n    if (!phone) { Alert.alert(t.whatsapp, t.unavailableWhatsApp); return; }\n    const message = `Hola, estoy interesado en \"${property?.title || 'tu anuncio'}\".`;\n    const url = buildWhatsAppUrl(phone, message);\n    if (!url) { Alert.alert(t.whatsapp, t.unavailableWhatsApp); return; }\n    Linking.openURL(url).catch(() => Alert.alert(t.whatsapp, t.whatsappError));\n  };\n\n  if (variant === 'compact') {\n    return (\n      <View style={[styles.compactContainer, { backgroundColor: colors.surface, borderColor: colors.border }, style]}>\n        {avatarUri ? (\n          <Image source={{ uri: avatarUri }} style={[styles.compactAvatar, { backgroundColor: colors.surface }]} accessibilityLabel={`Foto de ${name}`} />\n        ) : (\n          <View style={[styles.compactAvatarInitials, { backgroundColor: colors.primary }]}>\n            <Text style={styles.compactAvatarText}>{initials}</Text>\n          </View>\n        )}\n        <View style={styles.compactInfo}>\n          <Text style={[styles.compactName, { color: colors.textPrimary }]} numberOfLines={1}>{name}</Text>\n          <View style={styles.compactMeta}>\n            {rating ? <Text style={[styles.compactRating, { color: colors.textSecondary }]}>⭐ {rating}</Text> : null}\n            <VerificationBadge level={landlord.verificationLevel ?? 1} size=\"small\" minLevel={2} />\n          </View>\n        </View>\n        {showViewProfile ? (\n          <Pressable style={[styles.compactButton, { backgroundColor: colors.border }, !canViewProfile && styles.disabledButton]} onPress={handleViewProfile} disabled={!canViewProfile} accessibilityRole=\"button\" accessibilityLabel={`Ver perfil de ${name}`}>\n            <Text style={[styles.compactButtonText, { color: colors.textPrimary }]}>{t.view}</Text>\n          </Pressable>\n        ) : null}\n      </View>\n    );\n  }\n\n  return (\n    <View style={[styles.container, { backgroundColor: colors.surface, borderColor: colors.border }, style]}>\n      {/* Header */}\n      <View style={styles.header}>\n        {avatarUri ? (\n          <Image source={{ uri: avatarUri }} style={[styles.avatar, { backgroundColor: colors.surface }]} accessibilityLabel={`Foto de ${name}`} />\n        ) : (\n          <View style={[styles.avatarInitials, { backgroundColor: colors.primary }]}>\n            <Text style={styles.avatarText}>{initials}</Text>\n          </View>\n        )}\n        <View style={styles.headerInfo}>\n          <Text style={[styles.name, { color: colors.textPrimary }]} numberOfLines={1}>{name}</Text>\n          <Text style={[styles.subtitle, { color: colors.textSecondary }]} numberOfLines={1}>{subtitle}</Text>\n          <View style={styles.badgeRow}>\n            <VerificationBadge level={landlord.verificationLevel ?? 1} size=\"small\" />\n          </View>\n        </View>\n      </View>\n\n      {/* Meta rápida */}\n      {rating || landlord.responseTimeHours != null ? (\n        <View style={styles.metaRow}>\n          {rating ? <Text style={[styles.ratingText, { color: colors.textPrimary }]}>⭐ {rating}{reviewsCount ? ` (${reviewsCount})` : ''}</Text> : null}\n          {landlord.responseTimeHours != null ? <Text style={[styles.responseText, { color: colors.textSecondary }]}>{t.responds}: {responseValue}</Text> : null}\n        </View>\n      ) : null}\n\n      {/* Stats */}\n      <View style={[styles.statsRow, { backgroundColor: colors.card, borderColor: colors.border }]}>\n        <Stat value={responseValue} label={t.response} />\n        <Stat value={listingsCount != null ? String(listingsCount) : '—'} label={t.listings} />\n        <Stat value={memberSince ?? '—'} label={t.memberSince} />\n      </View>\n\n      {/* Bio opcional */}\n      {landlord.bio || landlord.description ? (\n        <Text style={[styles.description, { color: colors.textSecondary }]} numberOfLines={3}>{landlord.bio || landlord.description}</Text>\n      ) : null}\n\n      {/* Acciones */}\n      {showViewProfile || showContactActions ? (\n        <View style={styles.actionsContainer}>\n          {showViewProfile ? (\n            <Pressable style={[styles.fullButton, styles.secondaryButton, { backgroundColor: colors.card, borderColor: colors.border }, !canViewProfile && styles.disabledButton]} onPress={handleViewProfile} disabled={!canViewProfile} accessibilityRole=\"button\" accessibilityLabel={`Ver perfil de ${name}`}>\n              <Text style={[styles.secondaryButtonText, { color: colors.textPrimary }]}>{t.viewProfile}</Text>\n            </Pressable>\n          ) : null}\n          {showContactActions ? (\n            <View style={styles.contactRow}>\n              <Pressable style={[styles.contactButton, styles.callButton, { backgroundColor: colors.border }, !canCall && styles.disabledButton]} onPress={handleCall} disabled={!canCall} accessibilityRole=\"button\" accessibilityLabel={`Llamar a ${name}`}>\n                <Text style={[styles.callButtonText, { color: colors.textPrimary }]}>{t.call}</Text>\n              </Pressable>\n              <Pressable style={[styles.contactButton, styles.whatsappButton, !canWhatsApp && styles.disabledButton]} onPress={handleWhatsApp} disabled={!canWhatsApp} accessibilityRole=\"button\" accessibilityLabel={`Enviar WhatsApp a ${name}`}>\n                <Text style={styles.whatsappButtonText}>{t.whatsapp}</Text>\n              </Pressable>\n            </View>\n          ) : null}\n        </View>\n      ) : null}\n\n      {/* Nota de confianza */}\n      <Text style={[styles.trustNote, { color: colors.textSecondary }]}>{t.trustNote}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { borderRadius: 14, padding: espaciado.e16, borderWidth: 1 },\n  header: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 },\n  avatar: { width: 52, height: 52, borderRadius: 26 },\n  avatarInitials: { width: 52, height: 52, borderRadius: 26, justifyContent: 'center', alignItems: 'center' },\n  avatarText: { color: brand.white, fontSize: tipografia.title, fontWeight: '700' },\n  headerInfo: { flex: 1 },\n  name: { fontSize: tipografia.subtitle, fontWeight: '700' },\n  subtitle: { fontSize: tipografia.body, marginTop: espaciado.e2 },\n  badgeRow: { flexDirection: 'row', marginTop: espaciado.e6, gap: espaciado.e6 },\n  metaRow: { marginTop: espaciado.e12, flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10 },\n  ratingText: { fontSize: tipografia.body, fontWeight: '600' },\n  responseText: { fontSize: tipografia.body },\n  statsRow: { flexDirection: 'row', borderRadius: radios.md, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e10, marginTop: espaciado.e14, gap: espaciado.e8, borderWidth: 1 },\n  statItem: { flex: 1, alignItems: 'center' },\n  statValue: { fontSize: 15, fontWeight: '700' },\n  statLabel: { fontSize: tipografia.micro, marginTop: espaciado.e3 },\n  description: { marginTop: espaciado.e14, fontSize: tipografia.body, lineHeight: 20 },\n  actionsContainer: { marginTop: espaciado.e16 },\n  fullButton: { borderRadius: radios.md, paddingVertical: espaciado.e13, alignItems: 'center', marginBottom: espaciado.e8 },\n  secondaryButton: { borderWidth: 1 },\n  secondaryButtonText: { fontSize: tipografia.body, fontWeight: '700' },\n  contactRow: { flexDirection: 'row', gap: espaciado.e8 },\n  contactButton: { flex: 1, borderRadius: radios.md, paddingVertical: espaciado.e13, alignItems: 'center' },\n  callButton: {},\n  callButtonText: { fontSize: tipografia.body, fontWeight: '700' },\n  whatsappButton: { backgroundColor: brand.whatsapp },\n  whatsappButtonText: { fontSize: tipografia.body, fontWeight: '700', color: brand.white },\n  disabledButton: { opacity: 0.5 },\n  trustNote: { marginTop: espaciado.e14, fontSize: tipografia.micro, lineHeight: 16 },\n  compactContainer: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, padding: espaciado.e12, gap: espaciado.e10, borderWidth: 1 },\n  compactAvatar: { width: 40, height: 40, borderRadius: 20 },\n  compactAvatarInitials: { width: 40, height: 40, borderRadius: 20, justifyContent: 'center', alignItems: 'center' },\n  compactAvatarText: { color: brand.white, fontSize: tipografia.subtitle, fontWeight: '700' },\n  compactInfo: { flex: 1 },\n  compactName: { fontSize: tipografia.body, fontWeight: '700' },\n  compactMeta: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e4 },\n  compactRating: { fontSize: tipografia.caption, fontWeight: '600' },\n  compactButton: { borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8 },\n  compactButtonText: { fontSize: tipografia.caption, fontWeight: '700' },\n});\n","/**\n * MapBackground — contenedor de mapa reutilizable.\n *\n * Desde 2026-09-03 el mapa es MapLibre GL JS en WebView (packages/map), que\n * funciona en Expo Go Y en el APK release (tiles/style self-hosted en\n * egrouteplan.com/maps). Por eso aquí SIEMPRE se renderiza el EgMapView\n * (WebView) — ya no existe rama \"placeholder requiere build de desarrollo\".\n *\n * Coordenadas [lon, lat] (GeoJSON). Tiles propios en /maps/tiles.\n *\n * v4 (rediseño DiDi 2026-09-04):\n *  · Se elimina el gateo por hasNativeMapLibre(): el módulo nativo ya no existe\n *    y el WebView es el mapa real también en release.\n *  · Acepta `style` (tamaño/posición controlados por el padre) y `children`\n *    (marcadores, polylines…) que se renderizan DENTRO del EgMapView.\n *  · onMapPress → toque con coordenadas; pin → marcador naranja extra.\n *  · `initialCamera` → cámara con la que ABRE la pantalla (p. ej. la dirección\n *    real de la ciudad). Sin ella se usa ISLAND_CENTER (vista país/isla).\n *  · Carga: overlay hasta onMapLoaded; timeout 12 s → error con Reintentar\n *    (remount vía key).\n */\n\nimport React, { forwardRef, useCallback, useEffect, useRef, useState, type ReactNode } from 'react';\nimport { ActivityIndicator, Pressable, StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { MapPin, RefreshCw } from 'lucide-react-native';\nimport {\n  EgMapView, EgCamera, EgUserLocation, EgMarkers,\n  type EgMapViewHandle, type Coord,\n} from '../packages/map';\nimport { useTheme } from '../theme/ThemeContext';\nimport { ISLAND_CENTER, ISLAND_ZOOM } from '../constants/geo';\nimport { brand, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\nconst LOAD_TIMEOUT_MS = 12000;\n\nexport interface MapPressMeta {\n  drag?: boolean;\n  kind?: string;\n}\n\ninterface MapBackgroundProps {\n  /** Contenido extra dentro del mapa (EgMarkers, EgRoutePolyline…). */\n  children?: ReactNode;\n  /** Tamaño/posición del contenedor (por defecto flex:1). */\n  style?: StyleProp<ViewStyle>;\n  /** Toque en el mapa (o fin de arrastre de un pin → meta.drag/kind). */\n  onMapPress?: (coord: Coord, meta?: MapPressMeta) => void;\n  /** Zona sensible detectada cerca del coche (conductor): escuela/hospital… */\n  onHazard?: (h: { kind: string; name: string; distM: number }) => void;\n  pin?: Coord | null;\n  /** Cámara inicial con la que abrir el mapa ([lon,lat] + zoom). */\n  initialCamera?: { centerCoordinate: Coord; zoomLevel?: number };\n}\n\nconst MapBackground = forwardRef<EgMapViewHandle, MapBackgroundProps>(function MapBackground(\n  { children, style, onMapPress, onHazard, pin, initialCamera },\n  ref,\n) {\n  const { colors, isDark } = useTheme();\n  const [ready, setReady] = useState(false);\n  const [timedOut, setTimedOut] = useState(false);\n  const [attempt, setAttempt] = useState(0);\n  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n  const clearTimer = () => {\n    if (timeoutRef.current) { clearTimeout(timeoutRef.current); timeoutRef.current = null; }\n  };\n\n  useEffect(() => {\n    setReady(false);\n    setTimedOut(false);\n    clearTimer();\n    timeoutRef.current = setTimeout(() => setTimedOut(true), LOAD_TIMEOUT_MS);\n    return clearTimer;\n  }, [attempt]);\n\n  const handleLoaded = useCallback(() => {\n    clearTimer();\n    setReady(true);\n    setTimedOut(false);\n  }, []);\n\n  const retry = useCallback(() => setAttempt((a) => a + 1), []);\n\n  return (\n    <View style={[styles.fill, style]} testID=\"map-background\">\n      {/* Mapa WebView + overlays de carga/error */}\n      <EgMapView\n        key={attempt}\n        ref={ref}\n        style={StyleSheet.absoluteFill}\n        rotateEnabled={false}\n        pitchEnabled={false}\n        compassEnabled={false}\n        attributionEnabled\n        onMapLoaded={handleLoaded}\n        onPress={onMapPress}\n        onHazard={onHazard}\n      >\n        <EgCamera\n          centerCoordinate={initialCamera?.centerCoordinate ?? ISLAND_CENTER}\n          zoomLevel={initialCamera?.zoomLevel ?? ISLAND_ZOOM}\n          animationMode=\"moveTo\"\n        />\n        <EgUserLocation visible />\n        {pin ? <EgMarkers id=\"map-pin\" markers={[{ id: 'map-pin', coordinate: pin, kind: 'destination' }]} /> : null}\n        {children}\n      </EgMapView>\n\n      {!ready && !timedOut && (\n        <View style={[styles.overlay, { backgroundColor: isDark ? '#0B1220' : '#E9EEF4' }]} pointerEvents=\"none\">\n          <ActivityIndicator size=\"large\" color={colors.primary} />\n          <Text style={{ marginTop: espaciado.e12, color: colors.textSecondary, fontSize: tipografia.body }}>Cargando mapa…</Text>\n        </View>\n      )}\n\n      {timedOut && (\n        <View style={[styles.overlay, { backgroundColor: isDark ? '#0B1220' : '#E9EEF4' }]}>\n          <MapPin size={26} color={colors.danger} />\n          <Text style={[styles.errTitle, { color: colors.textPrimary }]}>No se pudo cargar el mapa</Text>\n          <Text style={[styles.errHint, { color: colors.textSecondary }]}>\n            Comprueba tu conexión o que el servidor de mapas esté disponible.\n          </Text>\n          <Pressable\n            onPress={retry}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Reintentar cargar el mapa\"\n            style={({ pressed }) => [styles.retryBtn, { backgroundColor: colors.primary, opacity: pressed ? 0.85 : 1 }]}\n          >\n            <RefreshCw size={16} color={brand.white} />\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body, marginLeft: espaciado.e6 }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      )}\n    </View>\n  );\n});\n\nexport default MapBackground;\n\nconst styles = StyleSheet.create({\n  fill: { flex: 1, overflow: 'hidden' },\n  overlay: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 40 },\n  errTitle: { fontSize: tipografia.title, fontWeight: '700', letterSpacing: 0.3, textAlign: 'center' },\n  errHint: { fontSize: tipografia.body, textAlign: 'center', lineHeight: 18, marginTop: espaciado.e4 },\n  retryBtn: { flexDirection: 'row', alignItems: 'center', marginTop: espaciado.e16, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e11, borderRadius: radios.md },\n});\n","/**\n * Paquete de mapas EG Route Plan — versión compatible con Expo Go.\n *\n * El mapa se renderiza con MapLibre GL JS dentro de un WebView (react-native-webview,\n * incluido en Expo Go) consumiendo tiles/style/glyphs self-hosted de egrouteplan.com.\n * NO usa @maplibre/maplibre-react-native (módulo nativo que crashea en Expo Go):\n * ese código queda reservado para un futuro development build (ver native.ts).\n *\n * Coordenadas: WGS84 [longitude, latitude].\n */\n\nexport { EgMapViewWeb as EgMapView, type EgMapViewHandle } from './mapWeb';\nexport { EgMapCamera as EgCamera, type EgCameraHandle } from './mapWeb';\nexport { EgMapMarkers as EgMarkers, EgMapUserLocation as EgUserLocation } from './mapWeb';\nexport { EgRoutePolyline } from './mapWeb';\nexport { MAP_STYLE_LIGHT, MAP_STYLE_DARK } from './styles';\nexport { loadMapLibre, hasNativeMapLibre, forceNativeMap } from './native';\nexport { MAP_COLORS, type Coord, type MapMarker, type MarkerKind, type RouteSegment, type CameraBounds } from './types';\n","/**\n * Proveedor de mapa WebView + MapLibre GL JS (funciona en Expo Go y producción).\n * Consume tiles/style/glyphs self-hosted de egrouteplan.com. Sin módulos nativos.\n * Misma API: EgMapView (ref setCamera/fitBounds), EgCamera, EgMarkers,\n * EgUserLocation (config serializada al WebView). Polylines: no-op seguro por ahora.\n */\n\nimport React, { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';\nimport { StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { WebView, type WebViewMessageEvent } from 'react-native-webview';\nimport type { Coord, MapMarker } from './types';\n\nexport interface EgMapViewHandle {\n  setCamera: (opts: { centerCoordinate?: Coord; zoomLevel?: number; durationMs?: number }) => void;\n  fitBounds: (coords: unknown, opts?: { bottomFrac?: number }) => void;\n  /** Cámara de navegación: centro + zoom + rumbo (bearing) + inclinación (pitch). */\n  setNavView?: (o: { lng: number; lat: number; zoom: number; bearing?: number; pitch?: number; durationMs?: number; carLng?: number; carLat?: number }) => void;\n  /** Modo \"coche siempre hacia arriba\" (el mapa rota con el movimiento). */\n  setHeadingUp?: (up: boolean) => void;\n  /** Guía del conductor: NO-OP de limpieza (la línea blanca de predicción fue\n   *  cancelada el 2026-09-05: tapaba la ruta y borraba las flechas animadas). */\n  setGuide?: (coords: Coord[]) => void;\n  /** Modo navegación: 'drive' (conductor, paleta Amap, gestos bloqueados),\n   *  'passenger' (pasajero, MISMA paleta Amap pero con pan libre y pitch 0)\n   *  o 'normal' (colores claros, gestos libres). */\n  setNavMode?: (mode: 'drive' | 'passenger' | 'normal') => void;\n  /** PASAJERO: coche en vivo animado (rAF + ease-in-out 2 s DENTRO de la\n   *  página). heading: rumbo GPS o calculado entre 2 últimas posiciones\n   *  (null → lo deriva la página); stale → gris; follow → cámara 2D sigue. */\n  setCarLive?: (o: { lng: number; lat: number; heading?: number | null; stale?: boolean; durationMs?: number; follow?: boolean }) => void;\n  /** Quita el coche en vivo y detiene su animación. */\n  clearCarLive?: () => void;\n  /** CONDUCTOR: cuerda ROJA fina tipo DiDi que une SU coche (lng1,lat1) con la\n   *  recogida (lng2,lat2). null → quitarla. Se refresca con cada fix. */\n  setRope?: (lng1: number | null, lat1: number | null, lng2: number | null, lat2: number | null) => void;\n  /** PASAJERO: ruta REAL por calles del conductor → recogida (DiDi muestra al\n   *  pasajero el camino exacto que recorrerá su conductor). vacío → quitarla. */\n  setApproach?: (coords: Coord[]) => void;\n  /** 'Conductor en camino' (accepted): la ruta azul pasa a GRIS tenue para que\n   *  la línea roja del conductor sea la protagonista. false → azul normal. */\n  setRouteDim?: (on: boolean) => void;\n  /** Modo noche FORZADO por horario de Guinea Ecuatorial (UTC+1): true=fondo\n   *  oscuro aunque el dispositivo esté en otro huso. */\n  setNight?: (night: boolean) => void;\n  /** P3 ZONAS CALIENTES (SIMULACIÓN VISUAL, sin demanda real aún): círculos\n   *  rojo/amarillo/azul en el WebView 2D. [] o undefined → limpiar. */\n  setHeatZones?: (zones: Array<{ lat: number; lng: number; rM: number; level: 'high' | 'mid' | 'low' }>) => void;\n}\n\nconst ORIGIN = 'https://hk.egrouteplan.com';\n// Página canónica servida por HTTPS real (no HTML inline): MapLibre necesita un\n// origen https para operar workers/CORS y descargar los tiles .mvt.\n// map-v2: sin caché agresiva (el alias /assets/ es immutable 1 año) y ready por\n// polling. El sufijo ?v fuerza a descargar la versión con navCam (bearing/pitch\n// para 3D y heading-up) si el WebView tuviera cacheada una página anterior.\nconst MAP_PAGE_URL = `${ORIGIN}/assets/map-v2.html?v=20260909d`;\n\n/** Ejecuta una llamada JS en la página del mapa (más fiable que postMessage en Android). */\nfunction injectJS(webRef: React.RefObject<WebView | null>, code: string) {\n  webRef.current?.injectJavaScript(`(function(){ try { ${code} } catch(e){ if(window.ReactNativeWebView) ReactNativeWebView.postMessage(JSON.stringify({type:'status',s:'js-err:'+e.message})); } })(); true;`);\n}\n\ninterface PressMeta {\n  drag?: boolean;\n  kind?: string;\n}\n\ninterface WebMapProps {\n  style?: StyleProp<ViewStyle>;\n  onMapPress?: (coord: Coord, meta?: PressMeta) => void;\n  /** Alias del mapa nativo (MapBackground usa onPress). */\n  onPress?: (coord: Coord, meta?: PressMeta) => void;\n  onMapLoaded?: () => void;\n  /** El mapa devuelve rumbo/inclinación reales (verificación 3D) y cy: la\n   *  fracción (0..1) de la altura de pantalla donde proyecta el coche, para\n   *  que el conductor ajuste el look-ahead y lo mantenga en el tercio inferior. */\n  onNavState?: (s: { bearing: number; pitch: number; zoom: number; cy?: number }) => void;\n  /** Zona sensible detectada cerca del coche (conductor): p. ej. escuela →\n   *  la voz avisa \"cuidado\". kind='school' | name | distM. */\n  onHazard?: (h: { kind: string; name: string; distM: number }) => void;\n  children?: React.ReactNode;\n  rotateEnabled?: boolean;\n  pitchEnabled?: boolean;\n  compassEnabled?: boolean;\n  attributionEnabled?: boolean;\n  animationDuration?: number;\n}\n\nexport const EgMapViewWeb = forwardRef<EgMapViewHandle, WebMapProps>(function EgMapViewWeb(\n  { style, onMapPress, onMapLoaded, onNavState, onHazard, children, onPress },\n  ref,\n) {\n  const webRef = useRef<WebView>(null);\n  const [ready, setReady] = useState(false);\n  const readyRef = useRef(false);\n  const lastMarkersRef = useRef<string | null>(null);\n  const lastRouteRef = useRef<string | null>(null);\n  // Cámara inicial: solo se envía cuando su VALOR cambia (no en cada re-render\n  // del padre). ConductorScreen se re-renderiza cada 250 ms en la simulación;\n  // si re-enviáramos setView(Malabo z13) en cada render, cancelaría la easeTo\n  // de navCam a medio camino → pitch/bearing congelados (~21°/−18°) y zoom\n  // tirando a 13, tal como se observó en el dispositivo.\n  const lastInitialCamRef = useRef<string | null>(null);\n  const pressRef = useRef(onMapPress ?? onPress);\n  pressRef.current = onMapPress ?? onPress;\n  const navStateRef = useRef(onNavState);\n  navStateRef.current = onNavState;\n  const hazardRef = useRef(onHazard);\n  hazardRef.current = onHazard;\n  const loadedRef = useRef(onMapLoaded);\n  loadedRef.current = onMapLoaded;\n\n  const cfg = useMemo(() => {\n    let camera: Coord | null = null;\n    let zoom = 13;\n    let route: Coord[] = [];\n    const markers: Array<{ lng: number; lat: number; kind: string; label?: string; drag?: boolean; heading?: number }> = [];\n    const walk = (node: React.ReactNode) => {\n      if (!React.isValidElement(node)) return;\n      const type = (node.type as { name?: string })?.name ?? '';\n      const p: any = node.props;\n      if (type === 'EgMapCamera') {\n        if (Array.isArray(p.centerCoordinate)) { camera = [p.centerCoordinate[0], p.centerCoordinate[1]]; zoom = p.zoomLevel ?? zoom; }\n      } else if (type === 'EgMapMarkers') {\n        (Array.isArray(p.markers) ? p.markers : []).forEach((m: MapMarker) => {\n          if (m && Array.isArray(m.coordinate)) {\n            markers.push({ lng: m.coordinate[0], lat: m.coordinate[1], kind: m.kind, label: m.label, drag: m.draggable === true, heading: m.heading });\n          }\n        });\n      } else if (type === 'EgRoutePolyline' && Array.isArray(p.coordinates)) {\n        route = p.coordinates.map((c: Coord) => [c[0], c[1]]);\n      } else if (Array.isArray(p.children)) {\n        p.children.forEach((c: React.ReactNode) => walk(c));\n      }\n    };\n    React.Children.forEach(children, walk);\n    return { camera, zoom, markers, route };\n  }, [children]);\n\n  useEffect(() => {\n    if (!ready || !cfg.camera) return;\n    // Una sola vez por valor de cámara inicial (el padre re-renderiza con\n    // frecuencia; NO queremos cancelar la cámara de navegación en cada tick).\n    const cam = cfg.camera as Coord;\n    const sig = `${cam[0].toFixed(6)},${cam[1].toFixed(6)},z${cfg.zoom}`;\n    if (lastInitialCamRef.current === sig) return;\n    lastInitialCamRef.current = sig;\n    injectJS(webRef, `if (typeof setView === 'function') setView(${cam[0]}, ${cam[1]}, ${cfg.zoom}, 600);`);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [ready, cfg.camera]);\n\n  useEffect(() => {\n    if (!ready) return;\n    const j = JSON.stringify(cfg.route);\n    if (lastRouteRef.current === j) return;\n    lastRouteRef.current = j;\n    injectJS(webRef, `if (typeof setRoute === 'function') setRoute(${j});`);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [ready, cfg.route]);\n\n  useEffect(() => {\n    if (!ready) return;\n    const markers = JSON.stringify(cfg.markers);\n    if (lastMarkersRef.current === markers) return; // no re-dibujar pins DOM si no cambian\n    lastMarkersRef.current = markers;\n    injectJS(webRef, `if (typeof setMarkers === 'function') setMarkers(${markers});`);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [ready, cfg.markers]);\n\n  useImperativeHandle(ref, () => ({\n    setCamera: ({ centerCoordinate, zoomLevel, durationMs }) => {\n      if (centerCoordinate) {\n        console.warn(`[map-web] enviar-view ${centerCoordinate[0].toFixed(4)},${centerCoordinate[1].toFixed(4)} z=${zoomLevel ?? 13}`);\n        injectJS(webRef, `if (typeof setView === 'function') setView(${centerCoordinate[0]}, ${centerCoordinate[1]}, ${zoomLevel ?? 13}, ${durationMs ?? 600});`);\n      }\n    },\n    fitBounds: (coords, opts?: { bottomFrac?: number }) => {\n      const flat: Coord[] = [];\n      (Array.isArray(coords) ? coords : []).forEach((c: any) => {\n        if (Array.isArray(c) && Array.isArray(c[0])) (c as Coord[]).forEach((p) => flat.push(p));\n        else if (Array.isArray(c)) flat.push(c as unknown as Coord);\n      });\n      if (flat.length) {\n        console.warn(`[map-web] enviar-fit ${flat.length} pts`);\n        const pts = JSON.stringify(flat);\n        const frac = opts?.bottomFrac ?? 0.38;\n        injectJS(webRef, `if (typeof fit === 'function') fit(${pts}, {bottomFrac:${frac}});`);\n      }\n    },\n    setNavView: (o) => {\n      console.warn(`[map-web] navcam z${o.zoom} b=${o.bearing ?? '-'} p=${o.pitch ?? '-'}`);\n      // Prioridad: navCam (bearing/pitch/3D). Si la página cargada aún no lo\n      // tiene, setView garantiza que la cámara SIGA al coche (nunca perderlo).\n      injectJS(\n        webRef,\n        `if (typeof navCam === 'function') { navCam(${o.lng}, ${o.lat}, ${o.zoom}, ${o.bearing ?? 'null'}, ${o.pitch ?? 'null'}, ${o.durationMs ?? 800}, ${o.carLng ?? 'null'}, ${o.carLat ?? 'null'}); } else if (typeof setView === 'function') { setView(${o.lng}, ${o.lat}, ${o.zoom}, ${o.durationMs ?? 800}); }`,\n      );\n    },\n    setHeadingUp: (up) => {\n      injectJS(webRef, `if (typeof setHeadingUp === 'function') setHeadingUp(${up ? 'true' : 'false'});`);\n    },\n    setGuide: (coords) => {\n      const pts = JSON.stringify(coords || []);\n      injectJS(webRef, `if (typeof setGuide === 'function') setGuide(${pts});`);\n    },\n    setNavMode: (mode) => {\n      injectJS(webRef, `if (typeof navMode === 'function') navMode('${mode}');`);\n    },\n    setCarLive: (o) => {\n      if (!Number.isFinite(o.lng) || !Number.isFinite(o.lat)) return;\n      const hd = (typeof o.heading === 'number' && Number.isFinite(o.heading)) ? o.heading.toFixed(1) : 'null';\n      injectJS(\n        webRef,\n        `if (typeof setCarLive === 'function') setCarLive(${o.lng}, ${o.lat}, ${hd}, ${o.stale ? 'true' : 'false'}, ${o.durationMs ?? 2000}, ${o.follow === false ? 'false' : 'true'});`,\n      );\n    },\n    clearCarLive: () => {\n      injectJS(webRef, `if (typeof clearCarLive === 'function') clearCarLive();`);\n    },\n    setRope: (lng1, lat1, lng2, lat2) => {\n      injectJS(webRef, `if (typeof setRope === 'function') setRope(${lng1 ?? 'null'}, ${lat1 ?? 'null'}, ${lng2 ?? 'null'}, ${lat2 ?? 'null'});`);\n    },\n    setApproach: (coords) => {\n      const pts = JSON.stringify(coords || []);\n      injectJS(webRef, `if (typeof setApproach === 'function') setApproach(${pts});`);\n    },\n    setRouteDim: (on) => {\n      injectJS(webRef, `if (typeof setRouteDim === 'function') setRouteDim(${on ? 'true' : 'false'});`);\n    },\n    setNight: (night) => {\n      injectJS(webRef, `if (typeof setNightOverride === 'function') setNightOverride(${night ? 'true' : 'false'});`);\n    },\n    setHeatZones: (zones) => {\n      const j = JSON.stringify(zones || []);\n      injectJS(webRef, `if (typeof setHeatZones === 'function') setHeatZones(${j});`);\n    },\n  }), []);\n\n  const onMessage = useCallback((e: WebViewMessageEvent) => {\n    let msg: any = null;\n    try { msg = JSON.parse(e.nativeEvent.data); } catch { return; }\n    if (!msg) return;\n    if (msg.type === 'ready') {\n      if (!readyRef.current) {\n        readyRef.current = true;\n        setReady(true);\n        loadedRef.current?.();\n      }\n    } else if (msg.type === 'press') {\n      pressRef.current?.([msg.lng, msg.lat]);\n    } else if (msg.type === 'press-drag') {\n      // Fin del arrastre de un pin (DiDi: sueltas el punto y la ruta se recalcula).\n      pressRef.current?.([msg.lng, msg.lat], { drag: true, kind: msg.kind });\n    } else if (msg.type === 'status') {\n      console.warn(`[map-web] ${msg.s}`);\n    } else if (msg.type === 'navstate') {\n      navStateRef.current?.({ bearing: Number(msg.bearing), pitch: Number(msg.pitch), zoom: Number(msg.zoom), cy: typeof msg.cy === 'number' ? Number(msg.cy) : undefined });\n    } else if (msg.type === 'hazard') {\n      hazardRef.current?.({ kind: String(msg.kind ?? 'school'), name: String(msg.name ?? ''), distM: Number(msg.distM) });\n    }\n  }, []);\n\n  return (\n    <View style={[StyleSheet.absoluteFill, style]} pointerEvents=\"auto\">\n      <WebView\n        ref={webRef}\n        source={{ uri: MAP_PAGE_URL }}\n        originWhitelist={['*']}\n        javaScriptEnabled\n        domStorageEnabled\n        onMessage={onMessage}\n        style={{ backgroundColor: 'transparent' }}\n      />\n    </View>\n  );\n});\n\nexport type EgCameraHandle = {\n  setCamera: (o: { centerCoordinate?: Coord; zoomLevel?: number; durationMs?: number }) => void;\n};\n\n/** Componentes \"config\": no pintan nada en RN; EgMapViewWeb los lee por nombre. */\nexport function EgMapCamera(props: { centerCoordinate?: Coord; zoomLevel?: number; [k: string]: unknown }) { return null; }\nexport function EgMapMarkers(props: { markers?: MapMarker[]; id?: string; [k: string]: unknown }) { return null; }\nexport function EgMapUserLocation(props: { visible?: boolean; [k: string]: unknown }) { return null; }\n/** Línea de ruta (taxi): se serializa desde EgMapViewWeb como GeoJSON. */\nexport function EgRoutePolyline(props: { coordinates?: Coord[]; [k: string]: unknown }) { return null; }\n","import WebView from './WebView';\n\nexport { WebView };\nexport default WebView;\n","import React, {\n  forwardRef,\n  ReactElement,\n  useCallback,\n  useEffect,\n  useImperativeHandle,\n  useRef,\n} from 'react';\n\nimport { Image, View, ImageSourcePropType, HostComponent } from 'react-native';\n\nimport BatchedBridge from 'react-native/Libraries/BatchedBridge/BatchedBridge';\nimport EventEmitter from 'react-native/Libraries/vendor/emitter/EventEmitter';\n\nimport invariant from 'invariant';\n\nimport RNCWebView, { Commands, NativeProps } from './RNCWebViewNativeComponent';\nimport RNCWebViewModule from './NativeRNCWebViewModule';\nimport {\n  defaultOriginWhitelist,\n  defaultRenderError,\n  defaultRenderLoading,\n  useWebViewLogic,\n} from './WebViewShared';\nimport {\n  AndroidWebViewProps,\n  WebViewSourceUri,\n  type WebViewMessageEvent,\n  type ShouldStartLoadRequestEvent,\n} from './WebViewTypes';\n\nimport styles from './WebView.styles';\n\nconst { resolveAssetSource } = Image;\n\nconst directEventEmitter = new EventEmitter();\n\nconst registerCallableModule: (name: string, module: Object) => void =\n  // `registerCallableModule()` is available in React Native 0.74 and above.\n  // Fallback to use `BatchedBridge.registerCallableModule()` for older versions.\n\n  require('react-native').registerCallableModule ??\n  BatchedBridge.registerCallableModule.bind(BatchedBridge);\n\nregisterCallableModule('RNCWebViewMessagingModule', {\n  onShouldStartLoadWithRequest: (\n    event: ShouldStartLoadRequestEvent & { messagingModuleName?: string }\n  ) => {\n    directEventEmitter.emit('onShouldStartLoadWithRequest', event);\n  },\n  onMessage: (\n    event: WebViewMessageEvent & { messagingModuleName?: string }\n  ) => {\n    directEventEmitter.emit('onMessage', event);\n  },\n});\n\n/**\n * A simple counter to uniquely identify WebView instances. Do not use this for anything else.\n */\nlet uniqueRef = 0;\n\nconst WebViewComponent = forwardRef<{}, AndroidWebViewProps>(\n  (\n    {\n      overScrollMode = 'always',\n      javaScriptEnabled = true,\n      thirdPartyCookiesEnabled = true,\n      scalesPageToFit = true,\n      allowsFullscreenVideo = false,\n      allowFileAccess = false,\n      saveFormDataDisabled = false,\n      cacheEnabled = true,\n      androidLayerType = 'none',\n      originWhitelist = defaultOriginWhitelist,\n      setSupportMultipleWindows = true,\n      setBuiltInZoomControls = true,\n      setDisplayZoomControls = false,\n      nestedScrollEnabled = false,\n      startInLoadingState,\n      onNavigationStateChange,\n      onLoadStart,\n      onError,\n      onLoad,\n      onLoadEnd,\n      onLoadProgress,\n      onHttpError: onHttpErrorProp,\n      onRenderProcessGone: onRenderProcessGoneProp,\n      onMessage: onMessageProp,\n      onOpenWindow: onOpenWindowProp,\n      renderLoading,\n      renderError,\n      style,\n      containerStyle,\n      source,\n      nativeConfig,\n      onShouldStartLoadWithRequest: onShouldStartLoadWithRequestProp,\n      injectedJavaScriptObject,\n      ...otherProps\n    },\n    ref\n  ) => {\n    const messagingModuleName = useRef<string>(\n      `WebViewMessageHandler${(uniqueRef += 1)}`\n    ).current;\n    const webViewRef = useRef<React.ComponentRef<\n      HostComponent<NativeProps>\n    > | null>(null);\n\n    const onShouldStartLoadWithRequestCallback = useCallback(\n      (shouldStart: boolean, url: string, lockIdentifier?: number) => {\n        if (lockIdentifier) {\n          RNCWebViewModule.shouldStartLoadWithLockIdentifier(\n            shouldStart,\n            lockIdentifier\n          );\n        } else if (shouldStart && webViewRef.current) {\n          Commands.loadUrl(webViewRef.current, url);\n        }\n      },\n      []\n    );\n\n    const {\n      onLoadingStart,\n      onShouldStartLoadWithRequest,\n      onMessage,\n      viewState,\n      setViewState,\n      lastErrorEvent,\n      onHttpError,\n      onLoadingError,\n      onLoadingFinish,\n      onLoadingProgress,\n      onOpenWindow,\n      onRenderProcessGone,\n    } = useWebViewLogic({\n      onNavigationStateChange,\n      onLoad,\n      onError,\n      onHttpErrorProp,\n      onLoadEnd,\n      onLoadProgress,\n      onLoadStart,\n      onRenderProcessGoneProp,\n      onMessageProp,\n      onOpenWindowProp,\n      startInLoadingState,\n      originWhitelist,\n      onShouldStartLoadWithRequestProp,\n      onShouldStartLoadWithRequestCallback,\n    });\n\n    useImperativeHandle(\n      ref,\n      () => ({\n        goForward: () =>\n          webViewRef.current && Commands.goForward(webViewRef.current),\n        goBack: () => webViewRef.current && Commands.goBack(webViewRef.current),\n        reload: () => {\n          setViewState('LOADING');\n          if (webViewRef.current) {\n            Commands.reload(webViewRef.current);\n          }\n        },\n        stopLoading: () =>\n          webViewRef.current && Commands.stopLoading(webViewRef.current),\n        postMessage: (data: string) =>\n          webViewRef.current && Commands.postMessage(webViewRef.current, data),\n        injectJavaScript: (data: string) =>\n          webViewRef.current &&\n          Commands.injectJavaScript(webViewRef.current, data),\n        requestFocus: () =>\n          webViewRef.current && Commands.requestFocus(webViewRef.current),\n        clearFormData: () =>\n          webViewRef.current && Commands.clearFormData(webViewRef.current),\n        clearCache: (includeDiskFiles: boolean) =>\n          webViewRef.current &&\n          Commands.clearCache(webViewRef.current, includeDiskFiles),\n        clearHistory: () =>\n          webViewRef.current && Commands.clearHistory(webViewRef.current),\n      }),\n      [setViewState, webViewRef]\n    );\n\n    useEffect(() => {\n      const onShouldStartLoadWithRequestSubscription =\n        directEventEmitter.addListener(\n          'onShouldStartLoadWithRequest',\n          (\n            event: ShouldStartLoadRequestEvent & {\n              messagingModuleName?: string;\n            }\n          ) => {\n            if (event.messagingModuleName === messagingModuleName) {\n              // eslint-disable-next-line @typescript-eslint/no-unused-vars\n              const { messagingModuleName: _, ...rest } = event;\n              onShouldStartLoadWithRequest(rest);\n            }\n          }\n        );\n\n      const onMessageSubscription = directEventEmitter.addListener(\n        'onMessage',\n        (event: WebViewMessageEvent & { messagingModuleName?: string }) => {\n          if (event.messagingModuleName === messagingModuleName) {\n            // eslint-disable-next-line @typescript-eslint/no-unused-vars\n            const { messagingModuleName: _, ...rest } = event;\n            onMessage(rest);\n          }\n        }\n      );\n\n      return () => {\n        onShouldStartLoadWithRequestSubscription.remove();\n        onMessageSubscription.remove();\n      };\n    }, [messagingModuleName, onMessage, onShouldStartLoadWithRequest]);\n\n    let otherView: ReactElement | undefined;\n    if (viewState === 'LOADING') {\n      otherView = (renderLoading || defaultRenderLoading)();\n    } else if (viewState === 'ERROR') {\n      invariant(\n        lastErrorEvent != null,\n        'lastErrorEvent expected to be non-null'\n      );\n      if (lastErrorEvent) {\n        otherView = (renderError || defaultRenderError)(\n          lastErrorEvent.domain,\n          lastErrorEvent.code,\n          lastErrorEvent.description\n        );\n      }\n    } else if (viewState !== 'IDLE') {\n      console.error(`RNCWebView invalid state encountered: ${viewState}`);\n    }\n\n    const webViewStyles = [styles.container, styles.webView, style];\n    const webViewContainerStyle = [styles.container, containerStyle];\n\n    if (typeof source !== 'number' && source && 'method' in source) {\n      if (source.method === 'POST' && source.headers) {\n        console.warn(\n          'WebView: `source.headers` is not supported when using POST.'\n        );\n      } else if (source.method === 'GET' && source.body) {\n        console.warn('WebView: `source.body` is not supported when using GET.');\n      }\n    }\n\n    const NativeWebView =\n      (nativeConfig?.component as typeof RNCWebView | undefined) || RNCWebView;\n\n    const sourceResolved = resolveAssetSource(source as ImageSourcePropType);\n    const newSource =\n      typeof sourceResolved === 'object'\n        ? Object.entries(sourceResolved as WebViewSourceUri).reduce(\n            (prev, [currKey, currValue]) => {\n              return {\n                ...prev,\n                [currKey]:\n                  currKey === 'headers' &&\n                  currValue &&\n                  typeof currValue === 'object'\n                    ? Object.entries(currValue).map(([key, value]) => {\n                        return {\n                          name: key,\n                          value,\n                        };\n                      })\n                    : currValue,\n              };\n            },\n            {}\n          )\n        : sourceResolved;\n\n    const webView = (\n      <NativeWebView\n        key=\"webViewKey\"\n        {...otherProps}\n        messagingEnabled={typeof onMessageProp === 'function'}\n        messagingModuleName={messagingModuleName}\n        hasOnScroll={!!otherProps.onScroll}\n        onLoadingError={onLoadingError}\n        onLoadingFinish={onLoadingFinish}\n        onLoadingProgress={onLoadingProgress}\n        onLoadingStart={onLoadingStart}\n        onHttpError={onHttpError}\n        onRenderProcessGone={onRenderProcessGone}\n        onMessage={onMessage}\n        onOpenWindow={onOpenWindow}\n        hasOnOpenWindowEvent={onOpenWindowProp !== undefined}\n        onShouldStartLoadWithRequest={onShouldStartLoadWithRequest}\n        ref={webViewRef}\n        // TODO: find a better way to type this.\n        // @ts-expect-error source is old arch\n        source={sourceResolved}\n        newSource={newSource}\n        style={webViewStyles}\n        overScrollMode={overScrollMode}\n        javaScriptEnabled={javaScriptEnabled}\n        thirdPartyCookiesEnabled={thirdPartyCookiesEnabled}\n        scalesPageToFit={scalesPageToFit}\n        allowsFullscreenVideo={allowsFullscreenVideo}\n        allowFileAccess={allowFileAccess}\n        saveFormDataDisabled={saveFormDataDisabled}\n        cacheEnabled={cacheEnabled}\n        androidLayerType={androidLayerType}\n        setSupportMultipleWindows={setSupportMultipleWindows}\n        setBuiltInZoomControls={setBuiltInZoomControls}\n        setDisplayZoomControls={setDisplayZoomControls}\n        nestedScrollEnabled={nestedScrollEnabled}\n        injectedJavaScriptObject={JSON.stringify(injectedJavaScriptObject)}\n        {...nativeConfig?.props}\n      />\n    );\n\n    return (\n      <View style={webViewContainerStyle}>\n        {webView}\n        {otherView}\n      </View>\n    );\n  }\n);\n\n// native implementation should return \"true\" only for Android 5+\nconst { isFileUploadSupported } = RNCWebViewModule;\n\nconst WebView = Object.assign(WebViewComponent, { isFileUploadSupported });\n\nexport default WebView;\n","import type { HostComponent, ViewProps } from 'react-native';\nimport codegenNativeComponent from 'react-native/Libraries/Utilities/codegenNativeComponent';\nimport {\n  DirectEventHandler,\n  Double,\n  Int32,\n  WithDefault,\n} from 'react-native/Libraries/Types/CodegenTypes';\nimport codegenNativeCommands from 'react-native/Libraries/Utilities/codegenNativeCommands';\n\nexport type WebViewNativeEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n}>;\nexport type WebViewCustomMenuSelectionEvent = Readonly<{\n  label: string;\n  key: string;\n  selectedText: string;\n}>;\nexport type WebViewMessageEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n  data: string;\n}>;\nexport type WebViewOpenWindowEvent = Readonly<{\n  targetUrl: string;\n}>;\nexport type WebViewHttpErrorEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n  description: string;\n  statusCode: Int32;\n}>;\n\nexport type WebViewErrorEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n  domain?: string;\n  code: Int32;\n  description: string;\n}>;\n\nexport type WebViewNativeProgressEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n  progress: Double;\n}>;\n\nexport type WebViewNavigationEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n  navigationType:\n    | 'click'\n    | 'formsubmit'\n    | 'backforward'\n    | 'reload'\n    | 'formresubmit'\n    | 'other';\n  mainDocumentURL?: string;\n}>;\n\nexport type ShouldStartLoadRequestEvent = Readonly<{\n  url: string;\n  loading: boolean;\n  title: string;\n  canGoBack: boolean;\n  canGoForward: boolean;\n  lockIdentifier: Double;\n  navigationType:\n    | 'click'\n    | 'formsubmit'\n    | 'backforward'\n    | 'reload'\n    | 'formresubmit'\n    | 'other';\n  mainDocumentURL?: string;\n  isTopFrame: boolean;\n}>;\n\ntype ScrollEvent = Readonly<{\n  contentInset: {\n    bottom: Double;\n    left: Double;\n    right: Double;\n    top: Double;\n  };\n  contentOffset: {\n    y: Double;\n    x: Double;\n  };\n  contentSize: {\n    height: Double;\n    width: Double;\n  };\n  layoutMeasurement: {\n    height: Double;\n    width: Double;\n  };\n  targetContentOffset?: {\n    y: Double;\n    x: Double;\n  };\n  velocity?: {\n    y: Double;\n    x: Double;\n  };\n  zoomScale?: Double;\n  responderIgnoreScroll?: boolean;\n}>;\n\ntype WebViewRenderProcessGoneEvent = Readonly<{\n  didCrash: boolean;\n}>;\n\ntype WebViewDownloadEvent = Readonly<{\n  downloadUrl: string;\n}>;\n\n// type MenuItem = Readonly<{label: string, key: string}>;\n\nexport interface NativeProps extends ViewProps {\n  // Android only\n  allowFileAccess?: boolean;\n  allowsProtectedMedia?: boolean;\n  allowsFullscreenVideo?: boolean;\n  androidLayerType?: WithDefault<'none' | 'software' | 'hardware', 'none'>;\n  cacheMode?: WithDefault<\n    | 'LOAD_DEFAULT'\n    | 'LOAD_CACHE_ELSE_NETWORK'\n    | 'LOAD_NO_CACHE'\n    | 'LOAD_CACHE_ONLY',\n    'LOAD_DEFAULT'\n  >;\n  domStorageEnabled?: boolean;\n  downloadingMessage?: string;\n  forceDarkOn?: boolean;\n  geolocationEnabled?: boolean;\n  lackPermissionToDownloadMessage?: string;\n  messagingModuleName: string;\n  minimumFontSize?: Int32;\n  mixedContentMode?: WithDefault<'never' | 'always' | 'compatibility', 'never'>;\n  nestedScrollEnabled?: boolean;\n  onContentSizeChange?: DirectEventHandler<WebViewNativeEvent>;\n  onRenderProcessGone?: DirectEventHandler<WebViewRenderProcessGoneEvent>;\n  overScrollMode?: string;\n  saveFormDataDisabled?: boolean;\n  scalesPageToFit?: WithDefault<boolean, true>;\n  setBuiltInZoomControls?: WithDefault<boolean, true>;\n  setDisplayZoomControls?: boolean;\n  setSupportMultipleWindows?: WithDefault<boolean, true>;\n  textZoom?: Int32;\n  thirdPartyCookiesEnabled?: WithDefault<boolean, true>;\n  // Workaround to watch if listener if defined\n  hasOnScroll?: boolean;\n  // !Android only\n\n  // iOS only\n  allowingReadAccessToURL?: string;\n  allowsBackForwardNavigationGestures?: boolean;\n  allowsInlineMediaPlayback?: boolean;\n  allowsPictureInPictureMediaPlayback?: boolean;\n  allowsAirPlayForMediaPlayback?: boolean;\n  allowsLinkPreview?: WithDefault<boolean, true>;\n  automaticallyAdjustContentInsets?: WithDefault<boolean, true>;\n  autoManageStatusBarEnabled?: WithDefault<boolean, true>;\n  bounces?: WithDefault<boolean, true>;\n  contentInset?: Readonly<{\n    top?: Double;\n    left?: Double;\n    bottom?: Double;\n    right?: Double;\n  }>;\n  contentInsetAdjustmentBehavior?: WithDefault<\n    'never' | 'automatic' | 'scrollableAxes' | 'always',\n    'never'\n  >;\n  contentMode?: WithDefault<\n    'recommended' | 'mobile' | 'desktop',\n    'recommended'\n  >;\n  dataDetectorTypes?: WithDefault<\n    ReadonlyArray<\n      | 'address'\n      | 'link'\n      | 'calendarEvent'\n      | 'trackingNumber'\n      | 'flightNumber'\n      | 'lookupSuggestion'\n      | 'phoneNumber'\n      | 'all'\n      | 'none'\n    >,\n    'phoneNumber'\n  >;\n  decelerationRate?: Double;\n  directionalLockEnabled?: WithDefault<boolean, true>;\n  enableApplePay?: boolean;\n  hideKeyboardAccessoryView?: boolean;\n  keyboardDisplayRequiresUserAction?: WithDefault<boolean, true>;\n  limitsNavigationsToAppBoundDomains?: boolean;\n  mediaCapturePermissionGrantType?: WithDefault<\n    | 'prompt'\n    | 'grant'\n    | 'deny'\n    | 'grantIfSameHostElsePrompt'\n    | 'grantIfSameHostElseDeny',\n    'prompt'\n  >;\n  pagingEnabled?: boolean;\n  pullToRefreshEnabled?: boolean;\n  refreshControlLightMode?: boolean;\n  scrollEnabled?: WithDefault<boolean, true>;\n  sharedCookiesEnabled?: boolean;\n  textInteractionEnabled?: WithDefault<boolean, true>;\n  useSharedProcessPool?: WithDefault<boolean, true>;\n  onContentProcessDidTerminate?: DirectEventHandler<WebViewNativeEvent>;\n  onCustomMenuSelection?: DirectEventHandler<WebViewCustomMenuSelectionEvent>;\n  onFileDownload?: DirectEventHandler<WebViewDownloadEvent>;\n\n  menuItems?: ReadonlyArray<Readonly<{ label: string; key: string }>>;\n  suppressMenuItems?: Readonly<string>[];\n  // Workaround to watch if listener if defined\n  hasOnFileDownload?: boolean;\n  fraudulentWebsiteWarningEnabled?: WithDefault<boolean, true>;\n  // !iOS only\n\n  allowFileAccessFromFileURLs?: boolean;\n  allowUniversalAccessFromFileURLs?: boolean;\n  applicationNameForUserAgent?: string;\n  basicAuthCredential?: Readonly<{\n    username: string;\n    password: string;\n  }>;\n  cacheEnabled?: WithDefault<boolean, true>;\n  incognito?: boolean;\n  injectedJavaScript?: string;\n  injectedJavaScriptBeforeContentLoaded?: string;\n  injectedJavaScriptForMainFrameOnly?: WithDefault<boolean, true>;\n  injectedJavaScriptBeforeContentLoadedForMainFrameOnly?: WithDefault<\n    boolean,\n    true\n  >;\n  javaScriptCanOpenWindowsAutomatically?: boolean;\n  javaScriptEnabled?: WithDefault<boolean, true>;\n  webviewDebuggingEnabled?: boolean;\n  mediaPlaybackRequiresUserAction?: WithDefault<boolean, true>;\n  messagingEnabled: boolean;\n  onLoadingError: DirectEventHandler<WebViewErrorEvent>;\n  onLoadingFinish: DirectEventHandler<WebViewNavigationEvent>;\n  onLoadingProgress: DirectEventHandler<WebViewNativeProgressEvent>;\n  onLoadingStart: DirectEventHandler<WebViewNavigationEvent>;\n  onHttpError: DirectEventHandler<WebViewHttpErrorEvent>;\n  onMessage: DirectEventHandler<WebViewMessageEvent>;\n  onOpenWindow?: DirectEventHandler<WebViewOpenWindowEvent>;\n  hasOnOpenWindowEvent?: boolean;\n  onScroll?: DirectEventHandler<ScrollEvent>;\n  onShouldStartLoadWithRequest: DirectEventHandler<ShouldStartLoadRequestEvent>;\n  showsHorizontalScrollIndicator?: WithDefault<boolean, true>;\n  showsVerticalScrollIndicator?: WithDefault<boolean, true>;\n  newSource: Readonly<{\n    uri?: string;\n    method?: string;\n    body?: string;\n\n    headers?: ReadonlyArray<Readonly<{ name: string; value: string }>>;\n    html?: string;\n    baseUrl?: string;\n  }>;\n  userAgent?: string;\n  injectedJavaScriptObject?: string;\n}\n\nexport interface NativeCommands {\n  goBack: (viewRef: React.ElementRef<HostComponent<NativeProps>>) => void;\n  goForward: (viewRef: React.ElementRef<HostComponent<NativeProps>>) => void;\n  reload: (viewRef: React.ElementRef<HostComponent<NativeProps>>) => void;\n  stopLoading: (viewRef: React.ElementRef<HostComponent<NativeProps>>) => void;\n  injectJavaScript: (\n    viewRef: React.ElementRef<HostComponent<NativeProps>>,\n    javascript: string\n  ) => void;\n  requestFocus: (viewRef: React.ElementRef<HostComponent<NativeProps>>) => void;\n  postMessage: (\n    viewRef: React.ElementRef<HostComponent<NativeProps>>,\n    data: string\n  ) => void;\n  // Android Only\n  loadUrl: (\n    viewRef: React.ElementRef<HostComponent<NativeProps>>,\n    url: string\n  ) => void;\n  clearFormData: (\n    viewRef: React.ElementRef<HostComponent<NativeProps>>\n  ) => void;\n  clearCache: (\n    viewRef: React.ElementRef<HostComponent<NativeProps>>,\n    includeDiskFiles: boolean\n  ) => void;\n  clearHistory: (viewRef: React.ElementRef<HostComponent<NativeProps>>) => void;\n  // !Android Only\n}\n\nexport const Commands = codegenNativeCommands<NativeCommands>({\n  supportedCommands: [\n    'goBack',\n    'goForward',\n    'reload',\n    'stopLoading',\n    'injectJavaScript',\n    'requestFocus',\n    'postMessage',\n    'loadUrl',\n    'clearFormData',\n    'clearCache',\n    'clearHistory',\n  ],\n});\n\nexport default codegenNativeComponent<NativeProps>(\n  'RNCWebView'\n) as HostComponent<NativeProps>;\n","import type { TurboModule } from 'react-native';\nimport { TurboModuleRegistry } from 'react-native';\nimport { Double } from 'react-native/Libraries/Types/CodegenTypes';\n\nexport interface Spec extends TurboModule {\n  isFileUploadSupported(): Promise<boolean>;\n  shouldStartLoadWithLockIdentifier(\n    shouldStart: boolean,\n    lockIdentifier: Double\n  ): void;\n}\n\nexport default TurboModuleRegistry.getEnforcing<Spec>('RNCWebViewModule');\n","import escapeStringRegexp from 'escape-string-regexp';\nimport React, { useCallback, useMemo, useRef, useState } from 'react';\nimport { Linking, View, ActivityIndicator, Text, Platform } from 'react-native';\nimport {\n  OnShouldStartLoadWithRequest,\n  ShouldStartLoadRequestEvent,\n  WebViewError,\n  WebViewErrorEvent,\n  WebViewHttpErrorEvent,\n  WebViewMessageEvent,\n  WebViewNavigation,\n  WebViewNavigationEvent,\n  WebViewOpenWindowEvent,\n  WebViewProgressEvent,\n  WebViewRenderProcessGoneEvent,\n  WebViewTerminatedEvent,\n} from './WebViewTypes';\nimport styles from './WebView.styles';\n\nconst defaultOriginWhitelist = ['http://*', 'https://*'] as const;\n\nconst extractOrigin = (url: string): string => {\n  const result = /^[A-Za-z][A-Za-z0-9+\\-.]+:(\\/\\/)?[^/]*/.exec(url);\n  return result === null ? '' : result[0];\n};\n\nconst originWhitelistToRegex = (originWhitelist: string): string =>\n  `^${escapeStringRegexp(originWhitelist).replace(/\\\\\\*/g, '.*')}`;\n\nconst passesWhitelist = (compiledWhitelist: readonly string[], url: string) => {\n  const origin = extractOrigin(url);\n  return compiledWhitelist.some((x) => new RegExp(x).test(origin));\n};\n\nconst compileWhitelist = (\n  originWhitelist: readonly string[]\n): readonly string[] =>\n  ['about:blank', ...(originWhitelist || [])].map(originWhitelistToRegex);\n\nconst createOnShouldStartLoadWithRequest = (\n  loadRequest: (\n    shouldStart: boolean,\n    url: string,\n    lockIdentifier: number\n  ) => void,\n  originWhitelist: readonly string[],\n  onShouldStartLoadWithRequest?: OnShouldStartLoadWithRequest\n) => {\n  return ({ nativeEvent }: ShouldStartLoadRequestEvent) => {\n    let shouldStart = true;\n    const { url, lockIdentifier } = nativeEvent;\n\n    if (!passesWhitelist(compileWhitelist(originWhitelist), url)) {\n      Linking.canOpenURL(url)\n        .then((supported) => {\n          if (supported) {\n            return Linking.openURL(url);\n          }\n          console.warn(`Can't open url: ${url}`);\n          return undefined;\n        })\n        .catch((e) => {\n          console.warn('Error opening URL: ', e);\n        });\n      shouldStart = false;\n    } else if (onShouldStartLoadWithRequest) {\n      shouldStart = onShouldStartLoadWithRequest(nativeEvent);\n    }\n\n    loadRequest(shouldStart, url, lockIdentifier);\n  };\n};\n\nconst defaultRenderLoading = () => (\n  <View style={styles.loadingOrErrorView}>\n    <ActivityIndicator />\n  </View>\n);\nconst defaultRenderError = (\n  errorDomain: string | undefined,\n  errorCode: number,\n  errorDesc: string\n) => (\n  <View style={styles.loadingOrErrorView}>\n    <Text style={styles.errorTextTitle}>Error loading page</Text>\n    <Text style={styles.errorText}>{`Domain: ${errorDomain}`}</Text>\n    <Text style={styles.errorText}>{`Error Code: ${errorCode}`}</Text>\n    <Text style={styles.errorText}>{`Description: ${errorDesc}`}</Text>\n  </View>\n);\n\nexport {\n  defaultOriginWhitelist,\n  createOnShouldStartLoadWithRequest,\n  defaultRenderLoading,\n  defaultRenderError,\n};\n\nexport const useWebViewLogic = ({\n  startInLoadingState,\n  onNavigationStateChange,\n  onLoadStart,\n  onLoad,\n  onLoadProgress,\n  onLoadEnd,\n  onError,\n  onHttpErrorProp,\n  onMessageProp,\n  onOpenWindowProp,\n  onRenderProcessGoneProp,\n  onContentProcessDidTerminateProp,\n  originWhitelist,\n  onShouldStartLoadWithRequestProp,\n  onShouldStartLoadWithRequestCallback,\n}: {\n  startInLoadingState?: boolean;\n  onNavigationStateChange?: (event: WebViewNavigation) => void;\n  onLoadStart?: (event: WebViewNavigationEvent) => void;\n  onLoad?: (event: WebViewNavigationEvent) => void;\n  onLoadProgress?: (event: WebViewProgressEvent) => void;\n  onLoadEnd?: (event: WebViewNavigationEvent | WebViewErrorEvent) => void;\n  onError?: (event: WebViewErrorEvent) => void;\n  onHttpErrorProp?: (event: WebViewHttpErrorEvent) => void;\n  onMessageProp?: (event: WebViewMessageEvent) => void;\n  onOpenWindowProp?: (event: WebViewOpenWindowEvent) => void;\n  onRenderProcessGoneProp?: (event: WebViewRenderProcessGoneEvent) => void;\n  onContentProcessDidTerminateProp?: (event: WebViewTerminatedEvent) => void;\n  originWhitelist: readonly string[];\n  onShouldStartLoadWithRequestProp?: OnShouldStartLoadWithRequest;\n  onShouldStartLoadWithRequestCallback: (\n    shouldStart: boolean,\n    url: string,\n    lockIdentifier?: number | undefined\n  ) => void;\n}) => {\n  const [viewState, setViewState] = useState<'IDLE' | 'LOADING' | 'ERROR'>(\n    startInLoadingState ? 'LOADING' : 'IDLE'\n  );\n  const [lastErrorEvent, setLastErrorEvent] = useState<WebViewError | null>(\n    null\n  );\n  const startUrl = useRef<string | null>(null);\n\n  const updateNavigationState = useCallback(\n    (event: WebViewNavigationEvent) => {\n      onNavigationStateChange?.(event.nativeEvent);\n    },\n    [onNavigationStateChange]\n  );\n\n  const onLoadingStart = useCallback(\n    (event: WebViewNavigationEvent) => {\n      // Needed for android\n      startUrl.current = event.nativeEvent.url;\n      // !Needed for android\n\n      onLoadStart?.(event);\n      updateNavigationState(event);\n    },\n    [onLoadStart, updateNavigationState]\n  );\n\n  const onLoadingError = useCallback(\n    (event: WebViewErrorEvent) => {\n      event.persist();\n      if (onError) {\n        onError(event);\n      } else {\n        console.warn('Encountered an error loading page', event.nativeEvent);\n      }\n      onLoadEnd?.(event);\n      if (event.isDefaultPrevented()) {\n        return;\n      }\n      setViewState('ERROR');\n      setLastErrorEvent(event.nativeEvent);\n    },\n    [onError, onLoadEnd]\n  );\n\n  const onHttpError = useCallback(\n    (event: WebViewHttpErrorEvent) => {\n      onHttpErrorProp?.(event);\n    },\n    [onHttpErrorProp]\n  );\n\n  // Android Only\n  const onRenderProcessGone = useCallback(\n    (event: WebViewRenderProcessGoneEvent) => {\n      onRenderProcessGoneProp?.(event);\n    },\n    [onRenderProcessGoneProp]\n  );\n  // !Android Only\n\n  // iOS Only\n  const onContentProcessDidTerminate = useCallback(\n    (event: WebViewTerminatedEvent) => {\n      onContentProcessDidTerminateProp?.(event);\n    },\n    [onContentProcessDidTerminateProp]\n  );\n  // !iOS Only\n\n  const onLoadingFinish = useCallback(\n    (event: WebViewNavigationEvent) => {\n      onLoad?.(event);\n      onLoadEnd?.(event);\n      const {\n        nativeEvent: { url },\n      } = event;\n      // on Android, only if url === startUrl\n      if (Platform.OS !== 'android' || url === startUrl.current) {\n        setViewState('IDLE');\n      }\n      // !on Android, only if url === startUrl\n      updateNavigationState(event);\n    },\n    [onLoad, onLoadEnd, updateNavigationState]\n  );\n\n  const onMessage = useCallback(\n    (event: WebViewMessageEvent) => {\n      onMessageProp?.(event);\n    },\n    [onMessageProp]\n  );\n\n  const onLoadingProgress = useCallback(\n    (event: WebViewProgressEvent) => {\n      const {\n        nativeEvent: { progress },\n      } = event;\n      // patch for Android only\n      if (Platform.OS === 'android' && progress === 1) {\n        setViewState((prevViewState) =>\n          prevViewState === 'LOADING' ? 'IDLE' : prevViewState\n        );\n      }\n      // !patch for Android only\n      onLoadProgress?.(event);\n    },\n    [onLoadProgress]\n  );\n\n  const onShouldStartLoadWithRequest = useMemo(\n    () =>\n      createOnShouldStartLoadWithRequest(\n        onShouldStartLoadWithRequestCallback,\n        originWhitelist,\n        onShouldStartLoadWithRequestProp\n      ),\n    [\n      originWhitelist,\n      onShouldStartLoadWithRequestProp,\n      onShouldStartLoadWithRequestCallback,\n    ]\n  );\n\n  const onOpenWindow = useCallback(\n    (event: WebViewOpenWindowEvent) => {\n      onOpenWindowProp?.(event);\n    },\n    [onOpenWindowProp]\n  );\n\n  return {\n    onShouldStartLoadWithRequest,\n    onLoadingStart,\n    onLoadingProgress,\n    onLoadingError,\n    onLoadingFinish,\n    onHttpError,\n    onRenderProcessGone,\n    onContentProcessDidTerminate,\n    onMessage,\n    onOpenWindow,\n    viewState,\n    setViewState,\n    lastErrorEvent,\n  };\n};\n","import { StyleSheet } from 'react-native';\n\nconst styles = StyleSheet.create({\n  container: {\n    flex: 1,\n    overflow: 'hidden',\n  },\n  loadingOrErrorView: {\n    position: 'absolute',\n    flex: 1,\n    justifyContent: 'center',\n    alignItems: 'center',\n    height: '100%',\n    width: '100%',\n    backgroundColor: 'white',\n  },\n  loadingProgressBar: {\n    height: 20,\n  },\n  errorText: {\n    fontSize: 14,\n    textAlign: 'center',\n    marginBottom: 2,\n  },\n  errorTextTitle: {\n    fontSize: 15,\n    fontWeight: '500',\n    marginBottom: 10,\n  },\n  webView: {\n    backgroundColor: '#ffffff',\n  },\n  flexStart: {\n    alignSelf: 'flex-start',\n  },\n  colorRed: {\n    color: 'red',\n  },\n});\n\nexport default styles;\n","/**\n * Estilos MapLibre — URLs a los JSON de estilo servidos desde el servidor propio.\n *\n * Los estilos viven en https://egrouteplan.com/maps/style-light.json y\n * style-dark.json. Definen las capas (background, water, roads, buildings,\n * places) con la paleta corporativa Eg Route Plan.\n *\n * Los tiles vectoriales provienen de Protomaps PMTiles servidos por\n * pmtiles-server en el mismo dominio (/maps/tiles/).\n *\n * No hay claves API externas. Todo es auto-hospedado.\n */\n\nimport { MAP_STYLE_LIGHT, MAP_STYLE_DARK } from '../../../api/config';\n\nexport { MAP_STYLE_LIGHT, MAP_STYLE_DARK };\n","/**\n * Detección del mapa NATIVO (@maplibre/maplibre-react-native).\n *\n * Desde 2026-09-03 el paquete renderiza el mapa con MapLibre GL JS dentro de un\n * WebView (compatible con Expo Go). El módulo nativo solo existe en builds con\n * la librería compilada (development/production build); en Expo Go NO existe y\n * un import estático crashea la app.\n *\n * Modo nativo (opcional, futuro dev-build): forzar con forceNativeMap(true)\n * desde el código de arranque de un dev-build; mientras tanto hasNativeMapLibre\n * devuelve false y todo el flujo usa el WebView.\n */\n\nlet nativeForced = false;\n\n/** Activar manualmente desde un dev-build para usar el módulo nativo real. */\nexport function forceNativeMap(enabled: boolean) {\n  nativeForced = enabled;\n}\n\nexport function hasNativeMapLibre(): boolean {\n  return nativeForced;\n}\n\nexport function loadMapLibre(): null {\n  return null;\n}\n","/**\n * Tipos compartidos del paquete de mapas.\n * MapLibre usa coordenadas [longitude, latitude] (convención GeoJSON).\n * react-native-maps usaba {latitude, longitude} — esto es un cambio clave\n * de la migración: todos los componentes usan [lon, lat] en WGS84.\n */\n\n/** Coordenada WGS84 en formato GeoJSON: [longitude, latitude] */\nexport type Coord = [number, number];\n\nexport type MarkerKind = 'origin' | 'destination' | 'taxi' | 'driver' | 'user' | 'poi';\n\nexport interface MapMarker {\n  id: string;\n  coordinate: Coord;\n  kind: MarkerKind;\n  label?: string;\n  /** Datos extra para mostrar en el callout (opcional) */\n  subtitle?: string;\n  /** Si true el pin se puede ARRASTRAR en el mapa (DiDi: ajustar punto y la\n   *  ruta se recalcula). Por defecto false. */\n  draggable?: boolean;\n  /** Rumbo (grados, 0=norte) para marcadores con rotación propia, p. ej. el\n   *  coche del conductor: la página dibuja la flecha con (rumbo − bearing del\n   *  mapa) para que apunte siempre al frente en pantalla (estilo Amap). */\n  heading?: number;\n}\n\nexport interface RouteSegment {\n  coordinates: Coord[];\n  /** Color de la polyline (#0084FF para ruta principal) */\n  color?: string;\n  /** Grosor en px (6 por defecto, estilo DiDi) */\n  width?: number;\n}\n\nexport interface CameraBounds {\n  ne: Coord;  // esquina noreste\n  sw: Coord;  // esquina suroeste\n  padding?: number;\n}\n\n/** Colores corporativos Eg Route Plan */\nexport const MAP_COLORS = {\n  primary: '#0084FF',      // polyline ruta, pin origen, botones\n  secondary: '#FF7D00',    // pin destino, taxis disponibles\n  success: '#27AE60',      // conductor asignado\n  danger: '#F53F3F',       // errores\n  cardBg: '#F5F7FA',       // fondo tarjetas flotantes\n  sheetBg: '#FFFFFF',      // fondo bottom-sheet\n  textPrimary: '#1D2129',\n  textSecondary: '#86909C',\n} as const;\n","/**\n * MALABO_CENTER — Centro de Malabo en WGS84 [lon, lat] (convención GeoJSON).\n * MapLibre usa [longitude, latitude], NO {latitude, longitude} como\n * react-native-maps. Sin transformación GCJ-02 — GPS nativo del dispositivo.\n *\n * Bounding box aproximado de Guinea Ecuatorial (para descarga OSM):\n *   N=4.0, S=-1.7, W=5.4, E=11.4\n */\nexport const MALABO_CENTER: [number, number] = [8.7371, 3.7504];\nexport const MALABO_ZOOM = 12;\n\n/** Vista que muestra la isla de Bioko completa con mar alrededor (zoom ~8). */\nexport const ISLAND_CENTER: [number, number] = [8.72, 3.5];\nexport const ISLAND_ZOOM = 8.2;\n\n/** Vista que muestra todo el país (Bioko + Río Muni) con contexto. */\nexport const COUNTRY_CENTER: [number, number] = [9.35, 1.55];\nexport const COUNTRY_ZOOM = 7.6;\n\n/** Centro de Bata (continental, Río Muni) */\nexport const BATA_CENTER: [number, number] = [9.7741, 1.8618];\n\n/**\n * Centros por ciudad (WGS84 [lon, lat]) para CENTRAR LA CÁMARA al elegir\n * ciudad en la Home o al volar con un toque en el mapa.\n * Aproximaciones de localidad (o de la capital de provincia para localidades\n * menores) — valen para centrado/contexto, NO para navegación ni rutas.\n */\nexport const CITY_CENTERS: Record<string, [number, number]> = {\n  // Bioko Norte\n  malabo: [8.7371, 3.7504],\n  rebola: [8.84, 3.72],\n  baney: [8.94, 3.72],\n  // Bioko Sur\n  luba: [8.55, 3.46],\n  riaba: [8.77, 3.37],\n  // Annobón\n  pale: [5.632, -1.406],\n  // Litoral (Río Muni)\n  bata: [9.7741, 1.8618],\n  cogo: [9.69, 1.08],\n  mbini: [9.70, 1.55],\n  machinda: [9.95, 1.70],\n  bitica: [9.62, 1.43],\n  corisco: [9.33, 1.00],\n  // Kié-Ntem\n  ebebia: [11.335, 2.151],\n  nsang: [10.94, 2.02],\n  micomeseng: [10.62, 2.10],\n  // Centro Sur\n  evinayong: [10.57, 1.74],\n  niefang: [10.25, 1.85],\n  aconibe: [10.94, 1.30],\n  acurenam: [10.65, 1.03],\n  // Wele-Nzas\n  mongomo: [11.317, 1.628],\n  anisok: [10.77, 1.86],\n  nsok: [11.27, 1.13],\n  ayene: [10.70, 1.88],\n  // Djibloho\n  paz: [10.88, 1.58],\n};\n\n/** Zoom al volar a una ciudad seleccionada (contexto regional). */\nexport const CITY_ZOOM = 11;\n\n/** Bounding box de Guinea Ecuatorial para consultas PostGIS */\nexport const GE_BBOX = {\n  minLon: 5.4,\n  minLat: -1.7,\n  maxLon: 11.4,\n  maxLat: 4.0,\n} as const;\n","/**\n * constantes del módulo Buscar Alquiler (labels compartidos UI/web).\n */\nexport const SERVICE_LABELS: Record<string, string> = {\n  electricity: 'Electricidad', generator: 'Generador', waterTank: 'Depósito de agua',\n  internet: 'Internet', airConditioning: 'Aire acondicionado',\n};\n","/**\n * AlquilerPlanesScreen — Planes de suscripción (kit SubscriptionPlansScreen) v2.\n * Auditoría aplicada:\n *  · Plan Gratis SIN checkout (lo gestiona el admin); planes de pago → billing-checkout.\n *  · Guard de arrendador: si no estás aprobado, aviso con navegación al alta.\n *  · Advertencia de límite: propiedades activas > maxProperties del plan destino.\n *  · Cargas separadas (plans/landlord) con error + reintento individuales, focus reload\n *    (useFocusEffect) y pull-to-refresh.\n *  · Tarjeta = View (sin Pressable anidado): solo el botón actúa; plan actual resaltado.\n *  · a11y completa, spinner por plan, features genéricas (núm/bool/string), tokens del\n *    tema, fallback de plan.color y copy de pago real (2–24 h).\n * Ruta: /alquiler-planes\n */\n\nimport React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Check, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { rentalApi, type RentalPlan, type LandlordMe } from '../api/rental';\nimport { billingApi } from '../api/billing';\nimport { formatXAF } from '../utils/formatHelpers';\n\nconst FEATURE_LABELS: Array<{ key: string; label: string }> = [\n  { key: 'maxProperties', label: 'Propiedades' },\n  { key: 'maxPhotos', label: 'Fotos por anuncio' },\n  { key: 'featuredSlots', label: 'Anuncios destacados' },\n  { key: 'priorityInSearch', label: 'Prioridad en búsquedas' },\n  { key: 'verifiedBadge', label: 'Insignia de verificado' },\n  { key: 'analytics', label: 'Estadísticas' },\n  { key: 'canPublishCommercial', label: 'Bares, discotecas y terrenos' },\n  { key: 'canPublishShortTerm', label: 'Alquiler por noches' },\n];\n\nconst PLAN_ORDER = ['free', 'verified', 'agency_pro', 'premium'];\nconst PLAN_CODES: Record<string, string> = {\n  verified: 'rental_verified', agency_pro: 'rental_agency_pro', premium: 'rental_premium',\n};\n\nconst maxPropsOf = (plan?: RentalPlan) => Number(plan?.features?.maxProperties ?? 0);\n\nexport default function AlquilerPlanesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n\n  const [plans, setPlans] = useState<RentalPlan[]>([]);\n  const [landlord, setLandlord] = useState<LandlordMe | null>(null);\n  const [plansLoading, setPlansLoading] = useState(true);\n  const [landlordLoading, setLandlordLoading] = useState(true);\n  const [plansError, setPlansError] = useState<string | null>(null);\n  const [landlordError, setLandlordError] = useState<string | null>(null);\n  const [processingPlan, setProcessingPlan] = useState<string | null>(null);\n\n  const loadPlans = useCallback(async () => {\n    setPlansLoading(true);\n    setPlansError(null);\n    try {\n      setPlans(await rentalApi.plans());\n    } catch (e) {\n      setPlansError(e instanceof Error ? e.message : 'No se pudieron cargar los planes');\n    } finally {\n      setPlansLoading(false);\n    }\n  }, []);\n\n  const loadLandlord = useCallback(async () => {\n    setLandlordLoading(true);\n    setLandlordError(null);\n    try {\n      setLandlord(await rentalApi.landlordMe());\n    } catch (e) {\n      setLandlordError(e instanceof Error ? e.message : 'No se pudo cargar tu estado de arrendador');\n    } finally {\n      setLandlordLoading(false);\n    }\n  }, []);\n\n  // Recarga al montar y al volver del checkout (plan recién aprobado).\n  useFocusEffect(\n    useCallback(() => {\n      void loadPlans();\n      void loadLandlord();\n    }, [loadPlans, loadLandlord]),\n  );\n\n  const currentSubscription = landlord?.subscription ?? 'free';\n  const approved = !!landlord?.exists && landlord?.status === 'approved';\n  const activeProps = landlord?.propertiesCount ?? 0;\n  const ordered = PLAN_ORDER\n    .map((k) => plans.find((p) => p.key === k))\n    .filter((p): p is RentalPlan => Boolean(p));\n\n  const goCheckout = async (planKey: string) => {\n    const code = PLAN_CODES[planKey];\n    setProcessingPlan(planKey);\n    try {\n      if (!code) throw new Error('Plan no disponible en el catálogo de pago');\n      const billingPlans = await billingApi.plans('rental');\n      const bp = billingPlans.find((p) => p.code === code);\n      if (!bp) throw new Error('Plan no disponible en el catálogo de pago');\n      router.push({ pathname: '/billing-checkout', params: { planId: bp.id, module: 'rental', targetType: 'user' } } as never);\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo iniciar la compra');\n    } finally {\n      setProcessingPlan(null);\n    }\n  };\n\n  const handleSelectPlan = (planKey: string) => {\n    if (planKey === currentSubscription) {\n      Alert.alert('Plan actual', 'Ya tienes este plan activo.');\n      return;\n    }\n    if (landlordLoading && !landlord) {\n      Alert.alert('Un momento', 'Todavía estamos cargando tu estado de arrendador.');\n      return;\n    }\n    const targetPlan = plans.find((p) => p.key === planKey);\n\n    // Plan Gratis no tiene checkout: lo gestiona el administrador.\n    if (planKey === 'free') {\n      Alert.alert(\n        'Cambiar a plan Gratis',\n        'Perderás los beneficios de tu plan actual. El cambio a Gratis lo gestiona el administrador: escríbenos desde soporte y lo aplicaremos.',\n        [{ text: 'Entendido' }],\n      );\n      return;\n    }\n\n    // Guard de arrendador (planes de pago requieren landlord aprobado).\n    if (!approved) {\n      Alert.alert(\n        'Arrendador no verificado',\n        landlord?.status === 'pending'\n          ? 'Tu solicitud de arrendador está pendiente de revisión. Podrás contratar un plan cuando esté aprobada.'\n          : landlord?.status === 'rejected'\n            ? 'Tu solicitud de arrendador fue rechazada. Corrige los datos y vuelve a enviarla.'\n            : 'Para contratar un plan de pago primero debes darte de alta y ser aprobado como arrendador.',\n        [\n          { text: 'Cancelar', style: 'cancel' },\n          { text: 'Ir al alta', onPress: () => router.push('/alquiler-publicar' as never) },\n        ],\n      );\n      return;\n    }\n\n    // Advertencia: propiedades activas por encima del límite del plan destino.\n    const targetMax = maxPropsOf(targetPlan);\n    if (targetMax > 0 && activeProps > targetMax) {\n      Alert.alert(\n        'Ojo con tu límite',\n        `Tienes ${activeProps} propiedades activas, pero «${targetPlan?.name ?? planKey}» permite ${targetMax}. Podrás mantenerlas hasta cerrarlas, pero no podrás publicar nuevas hasta bajar de ese número o subir de plan. ¿Continuar al pago?`,\n        [\n          { text: 'Cancelar', style: 'cancel' },\n          { text: 'Continuar', onPress: () => { void goCheckout(planKey); } },\n        ],\n      );\n      return;\n    }\n\n    // Confirmación de bajada entre planes de pago (se pierden features).\n    const curIdx = PLAN_ORDER.indexOf(currentSubscription);\n    const dstIdx = PLAN_ORDER.indexOf(planKey);\n    if (dstIdx >= 0 && dstIdx < curIdx) {\n      Alert.alert(\n        'Cambiar a un plan inferior',\n        `Pasarás de «${currentSubscription}» a «${targetPlan?.name ?? planKey}» y perderás sus ventajas. Puedes volver a subir cuando quieras.`,\n        [\n          { text: 'Cancelar', style: 'cancel' },\n          { text: 'Continuar', onPress: () => { void goCheckout(planKey); } },\n        ],\n      );\n      return;\n    }\n\n    void goCheckout(planKey);\n  };\n\n  const renderFeature = (plan: RentalPlan, key: string) => {\n    const features = plan.features as unknown as Record<string, unknown>;\n    const v = features[key];\n    const label = FEATURE_LABELS.find((f) => f.key === key)?.label ?? key;\n    if (typeof v === 'number') {\n      return (\n        <View style={s.featureRow} key={key}>\n          <Text style={s.featureLabel}>{label}</Text>\n          <Text style={s.featureValue}>{v <= 0 ? '—' : String(v)}</Text>\n        </View>\n      );\n    }\n    if (typeof v === 'boolean') {\n      return (\n        <View style={s.featureRow} key={key}>\n          <Text style={s.featureLabel}>{label}</Text>\n          <View accessible={false}>\n            {v ? <Check size={16} color={colors.success} strokeWidth={3} /> : <X size={16} color={colors.textSecondary} strokeWidth={3} />}\n          </View>\n        </View>\n      );\n    }\n    if (v != null) {\n      return (\n        <View style={s.featureRow} key={key}>\n          <Text style={s.featureLabel}>{label}</Text>\n          <Text style={s.featureValue}>{String(v)}</Text>\n        </View>\n      );\n    }\n    return null;\n  };\n\n  const s = styles(colors);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera del kit desde el 24/09/2026 (unificación de las 21 cabeceras). La clave local\n          `header` se retira; el título sube de 700 a `peso.maximo` y el icono de 24 se queda igual. */}\n      <ScreenHeader\n        titulo=\"Planes de suscripción\"\n        alVolver={() => router.back()}\n      />\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 40 }}\n        showsVerticalScrollIndicator={false}\n        refreshControl={<RefreshControl refreshing={plansLoading || landlordLoading} onRefresh={() => { void loadPlans(); void loadLandlord(); }} tintColor={colors.primary} colors={[colors.primary]} />}\n      >\n        <Text style={s.title}>Planes de suscripción</Text>\n        <Text style={s.subtitle}>\n          Publica gratis 1 propiedad. Con un plan de pago publicas más, destacas en la búsqueda y vendes por noches. Pago por transferencia o Mobile Money; el administrador aprueba tu comprobante (2–24 h).\n        </Text>\n\n        {plansError && (\n          <View style={{ marginBottom: espaciado.e12, backgroundColor: alpha(colors.danger, 0.06), padding: espaciado.e10, borderRadius: 10 }}>\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption }}>{plansError}</Text>\n            <Pressable onPress={() => void loadPlans()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar cargar planes\" hitSlop={6}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>Reintentar planes</Text>\n            </Pressable>\n          </View>\n        )}\n        {landlordError && (\n          <View style={{ marginBottom: espaciado.e12, backgroundColor: alpha(colors.danger, 0.06), padding: espaciado.e10, borderRadius: 10 }}>\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption }}>{landlordError}</Text>\n            <Pressable onPress={() => void loadLandlord()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar cargar estado de arrendador\" hitSlop={6}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>Reintentar mi estado</Text>\n            </Pressable>\n          </View>\n        )}\n\n        {plansLoading && ordered.length === 0 && (\n          <View style={{ alignItems: 'center', marginVertical: espaciado.e30 }}>\n            <ActivityIndicator color={colors.primary} />\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e8 }}>Cargando planes…</Text>\n          </View>\n        )}\n        {!plansLoading && ordered.length === 0 && !plansError && (\n          <Text style={{ textAlign: 'center', color: colors.textSecondary, marginTop: espaciado.e30 }}>No hay planes disponibles en este momento.</Text>\n        )}\n\n        {ordered.map((plan) => {\n          const isCurrent = plan.key === currentSubscription;\n          const planColor = plan.color || colors.primary;\n          const isProcessing = processingPlan === plan.key;\n          const isPaid = plan.price > 0;\n          return (\n            <View key={plan.key} style={[s.planCard, { borderColor: isCurrent ? planColor : colors.border }, isCurrent && { backgroundColor: alpha(planColor, 0.06) }]}>\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: espaciado.e14 }}>\n                <View style={{ flex: 1, paddingRight: espaciado.e8 }}>\n                  <Text style={[s.planName, { color: planColor }]}>{plan.name}</Text>\n                  {isCurrent && (\n                    <View style={[s.currentBadge, { backgroundColor: planColor }]}>\n                      <Text style={s.currentBadgeText}>Plan actual</Text>\n                    </View>\n                  )}\n                </View>\n                <View style={{ alignItems: 'flex-end' }}>\n                  <Text style={s.price}>{plan.price === 0 ? 'Gratis' : formatXAF(plan.price)}</Text>\n                  {plan.period && <Text style={s.period}>/{plan.period}</Text>}\n                </View>\n              </View>\n\n              <View style={{ marginBottom: espaciado.e14 }}>\n                {FEATURE_LABELS.map((f) => renderFeature(plan, f.key))}\n              </View>\n\n              <Pressable\n                onPress={() => handleSelectPlan(plan.key)}\n                disabled={processingPlan !== null}\n                accessibilityRole=\"button\"\n                accessibilityLabel={isCurrent ? `Plan actual: ${plan.name}` : plan.price === 0 ? 'Cambiar al plan Gratis' : `Elegir el plan ${plan.name}`}\n                accessibilityState={{ disabled: processingPlan !== null, selected: isCurrent }}\n                style={({ pressed }) => [\n                  s.selectButton,\n                  { backgroundColor: isCurrent ? colors.border : planColor, opacity: processingPlan !== null ? 0.6 : pressed ? 0.85 : 1 },\n                ]}\n              >\n                {isProcessing ? (\n                  <ActivityIndicator color={brand.white} />\n                ) : (\n                  <Text style={[s.selectButtonText, isCurrent && { color: colors.textSecondary }]}>\n                    {isCurrent ? 'Plan activo' : !isPaid ? 'Cambiar a Gratis' : 'Elegir este plan'}\n                  </Text>\n                )}\n              </Pressable>\n            </View>\n          );\n        })}\n\n        {/* Nota de pago */}\n        <View style={[s.paymentNote, { borderColor: colors.border }]}>\n          <Text style={s.paymentNoteTitle}>Cómo funciona</Text>\n          <Text style={s.paymentNoteText}>\n            1. Elige el plan y confirma la compra.{'\\n'}\n            2. Paga por transferencia o Mobile Money y sube el comprobante.{'\\n'}\n            3. El administrador aprueba y tu plan se activa (2–24 h).{'\\n'}\n            {'\\n'}\n            ¿Bajar a Gratis? Escríbenos desde soporte y lo gestionamos por ti.\n          </Text>\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  title: { fontSize: 22, fontWeight: '800', color: c.textPrimary, marginBottom: espaciado.e6 },\n  subtitle: { fontSize: tipografia.body, color: c.textSecondary, lineHeight: 19, marginBottom: espaciado.e18 },\n  planCard: { backgroundColor: c.card, borderRadius: radios.lg, padding: espaciado.e18, marginBottom: espaciado.e16, borderWidth: 1 },\n  planName: { fontSize: 18, fontWeight: '700' },\n  currentBadge: { paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: 6, marginTop: espaciado.e6, alignSelf: 'flex-start' },\n  currentBadgeText: { color: brand.white, fontSize: tipografia.micro, fontWeight: '600' },\n  price: { fontSize: tipografia.title, fontWeight: '800', color: c.textPrimary },\n  period: { fontSize: tipografia.body, color: c.textSecondary },\n  featureRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: espaciado.e6, borderBottomWidth: 1, borderBottomColor: c.border },\n  featureLabel: { fontSize: tipografia.body, color: c.textSecondary, flex: 1 },\n  featureValue: { fontSize: tipografia.body, fontWeight: '600', color: c.textPrimary },\n  selectButton: { borderRadius: 10, paddingVertical: espaciado.e14, alignItems: 'center' },\n  selectButtonText: { color: brand.white, fontSize: 15, fontWeight: '700' },\n  paymentNote: { backgroundColor: c.card, borderRadius: radios.md, padding: espaciado.e16, marginTop: espaciado.e8, borderWidth: 1 },\n  paymentNoteTitle: { fontSize: 15, fontWeight: '700', color: c.textPrimary, marginBottom: espaciado.e8 },\n  paymentNoteText: { fontSize: tipografia.body, color: c.textSecondary, lineHeight: 22 },\n});\n","/**\n * Cliente del módulo Billing/Payments Core — backend unificado.\n * Base ABSOLUTA: /api/billing/*. Manual-first: orden → comprobante →\n * admin aprueba → entitlement.\n */\n\nimport { http, httpRequest } from './httpClient';\n\nimport { API_HOST } from './config';\nexport const BILLING_API = `${API_HOST}/api`;\nconst b = (p: string) => `${BILLING_API}${p}`;\n\nexport interface BillingPlan {\n  id: string; module: string; code: string; name: string; description: string | null;\n  priceXaf: number; currency: string; interval: string | null; durationDays: number;\n  features: Record<string, unknown>; paymentInstructions: string | null; active: boolean;\n}\n\nexport interface BillingOrder {\n  id: string; planId: string; planCode: string; planName: string;\n  paymentInstructions: string | null;\n  module: string; targetType: string; targetId: string | null;\n  amountXaf: number; planPrice: number; currency: string;\n  status: string; paymentMethod: string | null; rejectionReason: string | null;\n  expiresAt: string | null; createdAt: string;\n  refundStatus?: string | null; cancellationReason?: string | null; reversalReason?: string | null;\n  proofs: Array<{ id: string; fileType: string; fileSize: number; declaredAmountXaf: number | null; declaredReference: string | null; createdAt: string }>;\n}\n\nexport interface BillingEntitlement {\n  id: string; module: string; code: string; targetType: string; targetId: string | null;\n  startsAt: string; expiresAt: string | null; status: string; active: boolean;\n  expiringSoonAt?: string | null; graceUntil?: string | null;\n  syncStatus?: string; lastSyncError?: string | null; daysLeft?: number | null;\n}\n\nexport const billingApi = {\n  plans: (module?: string) => http.get<BillingPlan[]>(b(`/billing/plans${module ? '?module=' + module : ''}`), false),\n  createOrder: (body: { planId: string; targetType?: string; targetId?: string }) =>\n    http.post<{ message: string; order?: BillingOrder; orderId?: string }>(b('/billing/orders'), body, true),\n  order: (id: string) => http.get<BillingOrder>(b(`/billing/orders/${id}`), true),\n  myOrders: () => http.get<Array<{ id: string; planCode: string; planName: string; amountXaf: number; status: string; createdAt: string; rejectionReason: string | null; refundStatus?: string | null; cancellationReason?: string | null; reversalReason?: string | null }>>(b('/billing/orders'), true),\n  /** Comprobante de pago como ARCHIVO (multipart): jpg/png/pdf, máx 5 MB. */\n  submitProof: (id: string, form: FormData) =>\n    httpRequest<{ message: string; status: string }>(b(`/billing/orders/${id}/proof`), { method: 'POST', auth: true, form }),\n  myEntitlements: () => http.get<BillingEntitlement[]>(b('/billing/entitlements/me'), true),\n  cancelOrder: (id: string, reason: string) =>\n    http.post<{ message: string; order?: BillingOrder }>(b(`/billing/orders/${id}/cancel`), { reason }, true),\n  settleCommissions: () =>\n    http.post<{ message: string; orderId?: string }>(b('/billing/commissions/settle'), {}, true),\n};\n","/**\n * AlquilerPublicarScreen — publicar propiedad + mis propiedades (arrendador) v2.\n * Auditoría aplicada:\n *  · Errores separados (applyError/publishError), landlord con carga + error + Reintentar.\n *  · Límite del plan PROACTIVO (antes de rellenar el formulario) + aviso de destacados.\n *  · Fotos/DIP comprimidos en el picker (quality 0.4) + límite ~700 KB base64 por foto\n *    (el backend ya sube base64→MinIO; así no se supera el body de 10 MB de nginx).\n *  · Fix renta 'both': pide y valida precio por noche Y renta mensual.\n *  · Selector de ubicación en mapa OPCIONAL (coordenadas reales; si no, barrio).\n *  · SafeArea, a11y completa, maxLength/contadores, miniatura real del DIP,\n *    reset completo del formulario, imports muertos eliminados.\n * Ruta: /alquiler-publicar\n */\n\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, Image, Pressable, ScrollView, StyleSheet, Switch, Text, TextInput, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport * as ImagePicker from 'expo-image-picker';\nimport { ImageIcon, X } from 'lucide-react-native';\nimport { alpha, brand, EmptyState, espaciado, FormField, GhostButton, InlineError, PrimaryButton, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport MapBackground from '../components/MapBackground';\nimport { rentalApi, type LandlordMe, type RentalProperty, type RentalCatalog } from '../api/rental';\nimport { formatXAF } from '../utils/formatHelpers';\n\nconst PLAN_LABELS: Record<string, string> = { free: 'Gratis', verified: 'Verificado', agency_pro: 'Agencia Pro', premium: 'Premium' };\nconst PLAN_FEATURES: Record<string, { photos: number; properties: number; canFeature: boolean }> = {\n  free: { photos: 5, properties: 1, canFeature: false },\n  verified: { photos: 10, properties: 3, canFeature: false },\n  agency_pro: { photos: 20, properties: 50, canFeature: true },\n  premium: { photos: 30, properties: 200, canFeature: true },\n};\nconst MAX_PHOTO_B64_KB = 700;\nconst MAX_TITLE = 160;\nconst MAX_DESC = 2000;\nconst DIGITS = (t: string) => t.replace(/[^0-9.]/g, '').slice(0, 12);\n\n/** bytes reales de un string base64 (con o sin prefijo data:) */\nconst b64SizeKB = (s: string | null | undefined) => {\n  const b64 = (s || '').split(',')[1] || s || '';\n  return Math.round((b64.length * 3) / 4 / 1024);\n};\n\nexport default function AlquilerPublicarScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [tab, setTab] = useState<'publish' | 'mine'>('publish');\n  const [cat, setCat] = useState<RentalCatalog | null>(null);\n  const [landlord, setLandlord] = useState<LandlordMe | null>(null);\n  const [mine, setMine] = useState<RentalProperty[]>([]);\n  const [loadingLandlord, setLoadingLandlord] = useState(true);\n  const [landlordError, setLandlordError] = useState<string | null>(null);\n  const [applyError, setApplyError] = useState<string | null>(null);\n  const [publishError, setPublishError] = useState<string | null>(null);\n  const [closingId, setClosingId] = useState<string | null>(null);\n  const mountedRef = useRef(true);\n  useEffect(() => () => { mountedRef.current = false; }, []);\n\n  // Alta de arrendador\n  const [applyOpen, setApplyOpen] = useState(false);\n  const [llName, setLlName] = useState('');\n  const [llDocType, setLlDocType] = useState<'dip' | 'passport' | 'residence_permit'>('dip');\n  const [llDocNumber, setLlDocNumber] = useState('');\n  const [llDocPhoto, setLlDocPhoto] = useState<string | null>(null);\n  const [llBusy, setLlBusy] = useState(false);\n\n  // Formulario de publicación\n  const [title, setTitle] = useState('');\n  const [description, setDescription] = useState('');\n  const [type, setType] = useState('apartment');\n  const [rentalType, setRentalType] = useState<'long_term' | 'short_term' | 'both'>('long_term');\n  const [cityId, setCityId] = useState('malabo');\n  const [neighborhood, setNeighborhood] = useState('');\n  const [address, setAddress] = useState('');\n  const [coords, setCoords] = useState<[number, number] | null>(null); // [lng, lat]\n  const [size, setSize] = useState('');\n  const [landSize, setLandSize] = useState('');\n  const [rooms, setRooms] = useState('');\n  const [bathrooms, setBathrooms] = useState('');\n  const [monthlyRent, setMonthlyRent] = useState('');\n  const [pricePerNight, setPricePerNight] = useState('');\n  const [depositMonths, setDepositMonths] = useState('1');\n  const [agencyFee, setAgencyFee] = useState('');\n  const [agencyFeePayer, setAgencyFeePayer] = useState<'tenant' | 'landlord' | 'shared' | ''>('');\n  const [essential, setEssential] = useState<string[]>([]);\n  const [amenities, setAmenities] = useState<string[]>([]);\n  const [photos, setPhotos] = useState<string[]>([]);\n  const [isFeatured, setIsFeatured] = useState(false);\n  const [isSocialHousing, setIsSocialHousing] = useState(false);\n  const [busy, setBusy] = useState(false);\n\n  const isLand = type === 'land_agriculture' || type === 'land_workshop' || type === 'land_other';\n  const subscription = landlord?.subscription ?? 'free';\n  const plan = PLAN_FEATURES[subscription] ?? PLAN_FEATURES.free;\n  const planLabel = PLAN_LABELS[subscription] ?? 'Gratis';\n  const exists = !!landlord?.exists;\n  const approved = exists && landlord?.status === 'approved' && Number(landlord?.verificationLevel) >= 2;\n  const activeProps = landlord?.propertiesCount ?? mine.filter((p) => p.status === 'open').length;\n  const atPlanLimit = approved && activeProps >= plan.properties;\n  const canFeaturePlan = plan.canFeature;\n\n  const loadLandlord = useCallback(async () => {\n    setLoadingLandlord(true);\n    setLandlordError(null);\n    try {\n      const [me, catalog] = await Promise.all([rentalApi.landlordMe(), rentalApi.catalog()]);\n      if (!mountedRef.current) return;\n      setLandlord(me);\n      setCat(catalog);\n      if (me.exists && me.status === 'approved' && Number(me.verificationLevel) >= 2) {\n        const r = await rentalApi.myProperties();\n        if (mountedRef.current) setMine(r.properties ?? []);\n      }\n    } catch (e) {\n      if (mountedRef.current) setLandlordError(e instanceof Error ? e.message : 'No se pudieron cargar tus datos. Comprueba tu conexión.');\n    } finally {\n      if (mountedRef.current) setLoadingLandlord(false);\n    }\n  }, []);\n\n  useEffect(() => { void loadLandlord(); }, [loadLandlord]);\n\n  const pickPhoto = async () => {\n    const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: 'images', quality: 0.4, base64: true });\n    if (res.canceled || !res.assets?.[0]) return;\n    const b64 = res.assets[0].base64 ?? null;\n    if (!b64) { Alert.alert('Imagen', 'No se pudo leer la imagen. Prueba con otra.'); return; }\n    if (photos.length >= plan.photos) { Alert.alert('Límite de fotos', `Tu plan ${planLabel} permite ${plan.photos} fotos. Mejora tu plan para subir más.`); return; }\n    const sizeKB = b64SizeKB(b64);\n    if (sizeKB > MAX_PHOTO_B64_KB) {\n      Alert.alert('Foto demasiado pesada', `La foto pesa ~${sizeKB} KB. Máximo ${MAX_PHOTO_B64_KB} KB para poder publicarla (se comprime al elegirla; prueba con otra o edítala antes).`);\n      return;\n    }\n    setPhotos((p) => [...p, `data:image/jpeg;base64,${b64}`]);\n  };\n\n  const removePhoto = (idx: number) => setPhotos((p) => p.filter((_, i) => i !== idx));\n\n  const pickDocPhoto = async () => {\n    const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: 'images', quality: 0.4, base64: true });\n    if (res.canceled || !res.assets?.[0]) return;\n    const b64 = res.assets[0].base64 ?? null;\n    if (!b64) return;\n    const sizeKB = b64SizeKB(b64);\n    if (sizeKB > MAX_PHOTO_B64_KB) {\n      Alert.alert('Documento demasiado pesado', `El documento pesa ~${sizeKB} KB. Máximo ${MAX_PHOTO_B64_KB} KB para enviarlo.`);\n      return;\n    }\n    setLlDocPhoto(`data:image/jpeg;base64,${b64}`);\n  };\n\n  const submitApply = async () => {\n    if (!llName.trim() || !llDocNumber.trim()) { setApplyError('Nombre y número de documento son obligatorios'); return; }\n    if (llDocPhoto === null) { setApplyError('Adjunta una foto legible del documento.'); return; }\n    setLlBusy(true); setApplyError(null);\n    try {\n      const r = await rentalApi.applyLandlord({ name: llName.trim(), docType: llDocType, docNumber: llDocNumber.trim(), docPhoto: llDocPhoto, isAgency: false });\n      Alert.alert('Solicitud enviada', r.message);\n      setApplyOpen(false);\n      setLlName(''); setLlDocNumber(''); setLlDocPhoto(null); setLlDocType('dip');\n      await loadLandlord();\n    } catch (e) { setApplyError(e instanceof Error ? e.message : 'No se pudo enviar la solicitud'); }\n    finally { setLlBusy(false); }\n  };\n\n  const resetForm = () => {\n    setTitle(''); setDescription(''); setType('apartment'); setRentalType('long_term');\n    setCityId('malabo'); setNeighborhood(''); setAddress(''); setCoords(null);\n    setSize(''); setLandSize(''); setRooms(''); setBathrooms('');\n    setMonthlyRent(''); setPricePerNight(''); setDepositMonths('1');\n    setAgencyFee(''); setAgencyFeePayer(''); setEssential([]); setAmenities([]);\n    setPhotos([]); setIsFeatured(false); setIsSocialHousing(false);\n  };\n\n  const chooseType = (t: string) => {\n    setType(t);\n    const land = t === 'land_agriculture' || t === 'land_workshop' || t === 'land_other';\n    if (land) { setRooms(''); setBathrooms(''); } else { setLandSize(''); }\n    setCoords(null);\n  };\n  const chooseRentalType = (t: 'long_term' | 'short_term' | 'both') => {\n    setRentalType(t);\n    if (t === 'long_term') setPricePerNight('');\n    if (t === 'short_term') setMonthlyRent('');\n  };\n  const chooseCity = (id: string) => { setCityId(id); setNeighborhood(''); setCoords(null); };\n\n  const publish = async () => {\n    if (!approved) return;\n    if (!title.trim() || !neighborhood.trim()) { setPublishError('Título y barrio son obligatorios.'); return; }\n    if (atPlanLimit) {\n      setPublishError(`Alcanzaste el límite de tu plan (${plan.properties} anuncio(s) activo(s)). Mejora tu plan para publicar más.`);\n      return;\n    }\n    const needsMonthly = rentalType === 'long_term' || rentalType === 'both';\n    const needsNightly = rentalType === 'short_term' || rentalType === 'both';\n    if (needsMonthly && !monthlyRent) { setPublishError('Indica la renta mensual.'); return; }\n    if (needsNightly && !pricePerNight) { setPublishError('Indica el precio por noche.'); return; }\n    if (rentalType === 'both' && Number(monthlyRent) > 0 && Number(pricePerNight) * 28 <= Number(monthlyRent)) {\n      setPublishError('Revisa los precios: por noche × 28 debería superar la renta mensual.'); return;\n    }\n    setBusy(true); setPublishError(null);\n    try {\n      const body: Record<string, unknown> = {\n        title: title.trim().slice(0, MAX_TITLE), description: description.trim() || undefined, type, rentalType,\n        cityId, neighborhood: neighborhood.trim(), address: address.trim().slice(0, 200) || undefined,\n        lat: coords ? coords[1] : null, lng: coords ? coords[0] : null,\n        size: size ? Number(size) : undefined, landSize: landSize ? Number(landSize) : undefined,\n        rooms: !isLand && rooms ? Number(rooms) : undefined, bathrooms: !isLand && bathrooms ? Number(bathrooms) : undefined,\n        monthlyRent: monthlyRent ? Number(monthlyRent) : undefined, pricePerNight: pricePerNight ? Number(pricePerNight) : undefined,\n        depositMonths: Number(depositMonths) || 1, agencyFee: agencyFee ? Number(agencyFee) : undefined,\n        agencyFeePayer: agencyFeePayer || undefined,\n        essentialServices: Object.fromEntries(essential.map((k) => [k, true])),\n        amenities: Object.fromEntries(amenities.map((k) => [k, true])),\n        photos, isFeatured, isSocialHousing,\n      };\n      const r = await rentalApi.publish(body);\n      Alert.alert('Publicado', r.message);\n      resetForm();\n      setTab('mine');\n      await loadLandlord();\n    } catch (e) { setPublishError(e instanceof Error ? e.message : 'No se pudo publicar'); }\n    finally { setBusy(false); }\n  };\n\n  const closeProp = (id: string) => {\n    Alert.alert('Cerrar anuncio', 'Dejará de ser visible para los buscadores. ¿Continuar?', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Cerrar', style: 'destructive',\n        onPress: async () => {\n          if (closingId) return;\n          setClosingId(id);\n          try {\n            const r = await rentalApi.close(id);\n            Alert.alert('Anuncio cerrado', r.message);\n            await loadLandlord();\n          } catch (e) { Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo cerrar el anuncio'); }\n          finally { setClosingId(null); }\n        },\n      },\n    ]);\n  };\n\n  const toggleChip = (setter: React.Dispatch<React.SetStateAction<string[]>>, id: string) =>\n    setter((arr) => (arr.includes(id) ? arr.filter((x) => x !== id) : [...arr, id]));\n\n  const s = styles(colors);\n\n  // ---------- Carga inicial ----------\n  if (loadingLandlord) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center', paddingTop: insets.top }}>\n        <ActivityIndicator size=\"large\" color={colors.primary} />\n        <Text style={{ marginTop: espaciado.e12, color: colors.textSecondary, fontWeight: '700' }}>Cargando tus datos…</Text>\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera del kit desde el 24/09/2026 (unificación de las 21 cabeceras). */}\n      <ScreenHeader\n        titulo=\"Buscar Alquiler\"\n        alVolver={() => router.back()}\n      />\n\n      <View style={{ flexDirection: 'row', paddingHorizontal: espaciado.e16, gap: espaciado.e8, marginVertical: espaciado.e12 }}>\n        <TabBtn active={tab === 'publish'} label=\"Publicar\" onPress={() => setTab('publish')} />\n        <TabBtn active={tab === 'mine'} label={`Mis anuncios (${mine.length})`} onPress={() => setTab('mine')} />\n      </View>\n\n      {landlordError && !landlord ? (\n        <View style={{ alignItems: 'center', paddingVertical: 50, paddingHorizontal: espaciado.e24 }}>\n          <Text style={{ color: colors.danger, fontWeight: '700', textAlign: 'center' }}>No se pudieron cargar tus datos.</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6, marginBottom: espaciado.e14 }}>{landlordError}</Text>\n          <Pressable onPress={() => void loadLandlord()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\"\n            style={({ pressed }) => [{ paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e10, borderRadius: 10, backgroundColor: colors.primary, opacity: pressed ? 0.85 : 1 }]}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingBottom: insets.bottom + 48 }} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n          {/* Banner de plan */}\n          <View style={[s.planBanner, { backgroundColor: colors.textPrimary }]}>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: brand.white, fontSize: 15, fontWeight: '700' }}>Plan actual: {planLabel}</Text>\n              <Text style={{ color: '#94a3b8', fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                {activeProps}/{plan.properties} propiedades · {photos.length}/{plan.photos} fotos\n                {landlord?.verificationLevel ? ` · Nivel ${landlord.verificationLevel}` : ''}\n              </Text>\n            </View>\n            <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n              <Pressable onPress={() => router.push('/billing-status' as never)} accessibilityRole=\"button\" accessibilityLabel=\"Mis compras\"\n                style={({ pressed }) => [{ backgroundColor: brand.success, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e8, borderRadius: radios.sm, opacity: pressed ? 0.85 : 1 }]}>\n                <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '700' }}>Mis compras</Text>\n              </Pressable>\n              <Pressable onPress={() => router.push('/alquiler-planes' as never)} accessibilityRole=\"button\" accessibilityLabel=\"Mejorar plan\"\n                style={({ pressed }) => [{ backgroundColor: colors.primary, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderRadius: radios.sm, opacity: pressed ? 0.85 : 1 }]}>\n                <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '700' }}>Mejorar plan</Text>\n              </Pressable>\n            </View>\n          </View>\n\n          {approved && atPlanLimit && (\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, backgroundColor: alpha(colors.danger, 0.08), padding: espaciado.e12, borderRadius: 10, marginBottom: espaciado.e14 }}>\n              <Text style={{ flex: 1, fontSize: tipografia.caption, color: colors.danger, fontWeight: '600', lineHeight: 17 }}>\n                Has alcanzado el límite de tu plan ({plan.properties} anuncio(s) activos). Cierra alguno o mejora tu plan para seguir publicando.\n              </Text>\n            </View>\n          )}\n\n          {tab === 'publish' ? (\n            !approved ? (\n              <View style={{ gap: espaciado.e12 }}>\n                {applyOpen ? (\n                  <>\n                    <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary, marginTop: espaciado.e8 }}>Alta de arrendador</Text>\n                    <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, lineHeight: 17 }}>\n                      Para publicar necesitas verificar tu identidad (DIP/pasaporte). El administrador la revisará.\n                    </Text>\n                    <Text style={s.label}>Nombre completo *</Text>\n                    <FormField value={llName} onChangeText={(t) => setLlName(t.slice(0, 120))} placeholder=\"Tu nombre\" />\n                    <Text style={s.label}>Tipo de documento *</Text>\n                    <View style={{ flexDirection: 'row', gap: espaciado.e6, flexWrap: 'wrap' }}>\n                      {([['dip', 'DIP'], ['passport', 'Pasaporte'], ['residence_permit', 'Permiso de residencia']] as const).map(([v, l]) => (\n                        <Chip key={v} label={l} active={llDocType === v} onPress={() => setLlDocType(v)} />\n                      ))}\n                    </View>\n                    <Text style={s.label}>Número de documento *</Text>\n                    <FormField value={llDocNumber} onChangeText={(t) => setLlDocNumber(t.slice(0, 50))} placeholder=\"Ej: DIP-123456\" />\n                    <Text style={s.label}>Foto del documento *</Text>\n                    {llDocPhoto ? (\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\n                        <View style={{ width: 64, height: 64, borderRadius: radios.sm, overflow: 'hidden', backgroundColor: colors.surface }}>\n                          <Image source={{ uri: llDocPhoto }} style={{ width: '100%', height: '100%' }} resizeMode=\"cover\" />\n                        </View>\n                        <View style={{ flex: 1 }}>\n                          <Text style={{ fontSize: tipografia.caption, color: colors.success, fontWeight: '700' }}>Documento adjunto</Text>\n                          <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e2 }}>~{b64SizeKB(llDocPhoto)} KB</Text>\n                        </View>\n                        <GhostButton title=\"Cambiar\" onPress={() => void pickDocPhoto()} />\n                        <Pressable onPress={() => setLlDocPhoto(null)} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Quitar documento\"><X size={18} color={colors.danger} /></Pressable>\n                      </View>\n                    ) : (\n                      <Pressable\n                        onPress={() => void pickDocPhoto()}\n                        accessibilityRole=\"button\" accessibilityLabel=\"Subir foto del documento\"\n                        style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, backgroundColor: colors.surface, padding: espaciado.e14, borderRadius: 10, borderWidth: 1, borderColor: colors.border, opacity: pressed ? 0.85 : 1 }]}\n                      >\n                        <ImageIcon size={18} color={colors.primary} /><Text style={{ fontSize: tipografia.body, color: colors.primary, fontWeight: '600' }}>Subir foto del documento</Text>\n                      </Pressable>\n                    )}\n                    <Text style={{ fontSize: 10.5, color: colors.textSecondary }}>Máx. ~{MAX_PHOTO_B64_KB} KB (se comprime al elegirla).</Text>\n                    {applyError ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={applyError} /></View> : null}\n                    <PrimaryButton title={llBusy ? 'Enviando…' : 'Enviar solicitud'} onPress={submitApply} disabled={llBusy} />\n                  </>\n                ) : (\n                  <View style={{ alignItems: 'center', gap: espaciado.e10, marginTop: espaciado.e30 }}>\n                    <Text style={{ fontSize: 40 }}>🏠</Text>\n                    <Text style={{ fontSize: 15, fontWeight: '700', color: colors.textPrimary, textAlign: 'center' }}>\n                      {landlord?.status === 'pending' ? 'Tu solicitud de arrendador está pendiente de revisión' : 'Necesitas verificar tu identidad para publicar'}\n                    </Text>\n                    <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', paddingHorizontal: espaciado.e20, lineHeight: 18 }}>\n                      {landlord?.status === 'pending'\n                        ? 'El administrador revisará tu DIP/pasaporte. Te avisaremos en cuanto esté aprobado.'\n                        : landlord?.status === 'rejected'\n                          ? 'Tu solicitud fue rechazada. Puedes volver a enviarla.'\n                          : 'Completa el alta con tu DIP o pasaporte para empezar a publicar.'}\n                    </Text>\n                    <PrimaryButton title={landlord?.status === 'rejected' ? 'Reenviar solicitud' : 'Verificar mi identidad'} onPress={() => { setApplyOpen(true); setApplyError(null); }} />\n                  </View>\n                )}\n              </View>\n            ) : (\n              <>\n                <Text style={s.label}>Título del anuncio *</Text>\n                <FormField value={title} onChangeText={(t) => setTitle(t.slice(0, MAX_TITLE))} placeholder=\"Ej: Apartamento 2 hab. en Paraíso\" />\n\n                <Text style={s.label}>Tipo de propiedad *</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  {(cat?.propertyTypes ?? []).map((t) => <Chip key={t.id} label={t.label} active={type === t.id} onPress={() => chooseType(t.id)} />)}\n                </View>\n\n                <Text style={s.label}>Tipo de alquiler *</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  {(cat?.rentalTypes ?? []).map((t) => (\n                    <Chip key={t.id} label={t.label} active={rentalType === t.id} onPress={() => chooseRentalType(t.id as 'long_term' | 'short_term' | 'both')} />\n                  ))}\n                </View>\n\n                <Text style={s.label}>{rentalType === 'short_term' ? 'Precio por noche (XAF) *' : rentalType === 'both' ? 'Precio por noche (XAF) *' : 'Renta mensual (XAF) *'}</Text>\n                {(rentalType === 'short_term' || rentalType === 'both') && (\n                  <FormField value={pricePerNight} onChangeText={setPricePerNight} placeholder=\"25000\" keyboardType=\"decimal-pad\" />\n                )}\n                {rentalType === 'both' && (\n                  <>\n                    <Text style={s.label}>Renta mensual (XAF) *</Text>\n                    <FormField value={monthlyRent} onChangeText={setMonthlyRent} placeholder=\"250000\" keyboardType=\"decimal-pad\" />\n                    <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e2 }}>Por noche × 28 debería superar la renta mensual (así no se contradicen).</Text>\n                  </>\n                )}\n                {rentalType === 'long_term' && (\n                  <FormField value={monthlyRent} onChangeText={setMonthlyRent} placeholder=\"250000\" keyboardType=\"decimal-pad\" />\n                )}\n\n                <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n                  <View style={{ flex: 1 }}><Text style={s.label}>Fianza (meses)</Text><FormField value={depositMonths} onChangeText={(t) => setDepositMonths(DIGITS(t) || '1')} placeholder=\"1\" keyboardType=\"decimal-pad\" /></View>\n                  <View style={{ flex: 1 }}><Text style={s.label}>Honorarios (XAF)</Text><FormField value={agencyFee} onChangeText={setAgencyFee} placeholder=\"25000\" keyboardType=\"decimal-pad\" /></View>\n                </View>\n                {agencyFee ? (\n                  <>\n                    <Text style={s.label}>Paga los honorarios</Text>\n                    <View style={{ flexDirection: 'row', gap: espaciado.e6, flexWrap: 'wrap' }}>\n                      {([['tenant', 'Inquilino'], ['landlord', 'Propietario'], ['shared', 'Compartido']] as const).map(([v, l]) => (\n                        <Chip key={v} label={l} active={agencyFeePayer === v} onPress={() => setAgencyFeePayer(agencyFeePayer === v ? '' : v)} />\n                      ))}\n                    </View>\n                  </>\n                ) : null}\n\n                <Text style={s.label}>Ciudad *</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  {(cat?.cities ?? []).map((c) => <Chip key={c.id} label={c.label} active={cityId === c.id} onPress={() => chooseCity(c.id)} />)}\n                </View>\n\n                <Text style={s.label}>Barrio *</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  {(cat?.neighborhoods ?? []).filter((n) => n.cityId === cityId).map((n) => (\n                    <Chip key={`${n.cityId}:${n.name}`} label={n.name} active={neighborhood === n.name} onPress={() => { setNeighborhood(n.name); setCoords(null); }} />\n                  ))}\n                </View>\n                <Text style={s.label}>Dirección (opcional)</Text>\n                <FormField value={address} onChangeText={(t) => setAddress(t.slice(0, 200))} placeholder=\"Calle, referencia…\" />\n\n                <Text style={s.label}>Ubicación en el mapa (opcional)</Text>\n                <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginBottom: espaciado.e6 }}>\n                  Toca el mapa para fijar la vivienda. Si no lo haces, usaremos el centro del barrio.\n                </Text>\n                <View style={{ height: 160, borderRadius: 14, overflow: 'hidden', marginBottom: espaciado.e6 }}>\n                  <MapBackground onMapPress={(c) => setCoords([c[0], c[1]])} pin={coords} />\n                </View>\n                <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\n                  {coords ? (\n                    <Text style={{ fontSize: tipografia.micro, color: colors.success, fontWeight: '700' }}>Punto fijado ✓</Text>\n                  ) : (\n                    <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>Sin punto (usará el barrio)</Text>\n                  )}\n                  {coords && (\n                    <Pressable onPress={() => setCoords(null)} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Quitar el punto del mapa\">\n                      <Text style={{ fontSize: tipografia.micro, color: colors.danger, fontWeight: '700' }}>Quitar punto</Text>\n                    </Pressable>\n                  )}\n                </View>\n\n                <Text style={s.label}>{isLand ? 'Superficie del terreno (m²)' : 'Superficie (m²)'}</Text>\n                <FormField value={isLand ? landSize : size} onChangeText={isLand ? setLandSize : setSize} placeholder=\"85\" keyboardType=\"decimal-pad\" />\n\n                {!isLand && (\n                  <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n                    <View style={{ flex: 1 }}><Text style={s.label}>Habitaciones</Text><FormField value={rooms} onChangeText={(t) => setRooms(DIGITS(t))} placeholder=\"2\" keyboardType=\"number-pad\" /></View>\n                    <View style={{ flex: 1 }}><Text style={s.label}>Baños</Text><FormField value={bathrooms} onChangeText={(t) => setBathrooms(DIGITS(t))} placeholder=\"1\" keyboardType=\"number-pad\" /></View>\n                  </View>\n                )}\n\n                <Text style={s.label}>Servicios esenciales</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  {(cat?.essentialServices ?? []).map((e) => <Chip key={e.id} label={e.label} active={essential.includes(e.id)} onPress={() => toggleChip(setEssential, e.id)} />)}\n                </View>\n\n                <Text style={s.label}>Comodidades</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  {(cat?.amenities ?? []).map((a) => <Chip key={a.id} label={a.label} active={amenities.includes(a.id)} onPress={() => toggleChip(setAmenities, a.id)} />)}\n                </View>\n\n                <Text style={s.label}>Descripción</Text>\n                <TextInput multiline maxLength={MAX_DESC} style={s.area} placeholder=\"Describe el inmueble, servicios, entorno…\" placeholderTextColor={colors.textSecondary} value={description} onChangeText={setDescription} />\n                <Text style={s.counter}>{description.length}/{MAX_DESC}</Text>\n\n                <Text style={s.label}>Fotos ({photos.length}/{plan.photos})</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10, marginTop: espaciado.e6 }}>\n                  {photos.map((p, i) => (\n                    <View key={i} style={{ width: 74, height: 74, borderRadius: radios.sm, overflow: 'hidden', backgroundColor: colors.surface }}>\n                      <Image source={{ uri: p }} style={{ width: '100%', height: '100%' }} resizeMode=\"cover\" />\n                      <Pressable onPress={() => removePhoto(i)} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Quitar foto ${i + 1}`}\n                        style={{ position: 'absolute', top: 2, right: 2, backgroundColor: 'rgba(16,24,40,0.65)', borderRadius: 9, padding: espaciado.e2 }}>\n                        <X size={12} color={brand.white} />\n                      </Pressable>\n                    </View>\n                  ))}\n                  {photos.length < plan.photos && (\n                    <Pressable onPress={() => void pickPhoto()} accessibilityRole=\"button\" accessibilityLabel=\"Añadir foto\"\n                      style={({ pressed }) => [{ width: 74, height: 74, borderRadius: radios.sm, borderWidth: 2, borderColor: colors.border, borderStyle: 'dashed', alignItems: 'center', justifyContent: 'center', opacity: pressed ? 0.7 : 1 }]}>\n                      <Text style={{ fontSize: 26, color: colors.textSecondary }}>+</Text>\n                    </Pressable>\n                  )}\n                </View>\n                <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e4 }}>Se comprimen al elegirlas. Máx. ~{MAX_PHOTO_B64_KB} KB cada una.</Text>\n\n                <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: espaciado.e16, backgroundColor: colors.surface, padding: espaciado.e14, borderRadius: 10 }}>\n                  <View style={{ flex: 1, paddingRight: espaciado.e8 }}>\n                    <Text style={{ fontSize: tipografia.body, color: colors.textPrimary, fontWeight: '600' }}>Marcar como destacado</Text>\n                    {!canFeaturePlan && <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e2 }}>Requiere plan Agencia Pro o Premium.</Text>}\n                  </View>\n                  <Switch\n                    value={isFeatured} onValueChange={setIsFeatured} disabled={!canFeaturePlan}\n                    trackColor={{ true: colors.primary, false: colors.border }}\n                    accessibilityRole=\"switch\" accessibilityLabel=\"Marcar como destacado\" accessibilityState={{ checked: isFeatured, disabled: !canFeaturePlan }}\n                  />\n                </View>\n                <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: espaciado.e8, backgroundColor: colors.surface, padding: espaciado.e14, borderRadius: 10 }}>\n                  <Text style={{ flex: 1, fontSize: tipografia.body, color: colors.textPrimary, fontWeight: '600' }}>Vivienda social / asequible</Text>\n                  <Switch value={isSocialHousing} onValueChange={setIsSocialHousing} trackColor={{ true: colors.primary, false: colors.border }}\n                    accessibilityRole=\"switch\" accessibilityLabel=\"Vivienda social o asequible\" accessibilityState={{ checked: isSocialHousing }} />\n                </View>\n\n                {publishError ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={publishError} /></View> : null}\n                <View style={{ marginTop: espaciado.e20 }}>\n                  <PrimaryButton title={busy ? 'Publicando…' : atPlanLimit ? 'Límite del plan alcanzado' : 'Publicar anuncio'}\n                    onPress={atPlanLimit ? () => { setPublishError('Cierra un anuncio o mejora tu plan para publicar.'); router.push('/alquiler-planes' as never); } : publish}\n                    disabled={busy} />\n                </View>\n              </>\n            )\n          ) : (\n            <>\n              {mine.length === 0 && (\n                /* Vacío con salida (D-17) con el componente del kit, en su forma compacta:\n                   vive dentro de la pantalla de publicar, así que no compite con el formulario. */\n                <EmptyState\n                  compacto\n                  icono={<Text style={{ fontSize: tipografia.display }}>📦</Text>}\n                  titulo=\"Aún no has publicado anuncios\"\n                  texto=\"Cuando publiques uno aparecerá aquí, con su estado y sus visitas.\"\n                />\n              )}\n              {mine.map((p) => (\n                <View key={p.id} style={{ backgroundColor: colors.surface, borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e12 }}>\n                  <Pressable\n                    onPress={() => router.push({ pathname: '/alquiler-detalle', params: { id: p.id } } as never)}\n                    accessibilityRole=\"button\" accessibilityLabel={`Ver anuncio: ${p.title}`}\n                    style={({ pressed }) => [{ opacity: pressed ? 0.85 : 1 }]}\n                  >\n                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n                      <View style={{ flex: 1, paddingRight: espaciado.e8 }}>\n                        <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>{p.title}</Text>\n                        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }} numberOfLines={1}>\n                          {p.location.neighborhood}, {p.location.cityName} · {p.price.monthlyRent ? formatXAF(p.price.monthlyRent) + '/mes' : formatXAF(p.price.pricePerNight) + '/noche'}\n                        </Text>\n                      </View>\n                      <Text style={{ fontSize: tipografia.micro, fontWeight: '700', color: p.status === 'closed' ? colors.danger : colors.success }}>{p.status === 'closed' ? 'Cerrado' : 'Activo'}</Text>\n                    </View>\n                    <View style={{ flexDirection: 'row', gap: espaciado.e16, marginTop: espaciado.e10, borderTopWidth: 1, borderTopColor: colors.border, paddingTop: espaciado.e10, alignItems: 'center' }}>\n                      <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>👁 {p.viewsCount} vistas</Text>\n                      <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>⭐ {p.favoritesCount} favs</Text>\n                      <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>📞 {p.contactClicks} contactos</Text>\n                      {p.status !== 'closed' && (\n                        <Pressable onPress={() => closeProp(p.id)} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Cerrar anuncio ${p.title}`} style={{ marginLeft: 'auto' }}>\n                          {closingId === p.id ? <ActivityIndicator size=\"small\" color={colors.danger} /> : <Text style={{ fontSize: tipografia.micro, color: colors.danger, fontWeight: '700' }}>Cerrar</Text>}\n                        </Pressable>\n                      )}\n                    </View>\n                  </Pressable>\n                </View>\n              ))}\n            </>\n          )}\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nfunction TabBtn({ active, label, onPress }: { active: boolean; label: string; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityState={{ selected: active }} accessibilityLabel={label}\n      style={({ pressed }) => [{ flex: 1, paddingVertical: espaciado.e9, borderRadius: radios.sm, alignItems: 'center', backgroundColor: active ? colors.primary : colors.surface, opacity: pressed ? 0.85 : 1 }]}>\n      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: active ? brand.white : colors.textSecondary }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nfunction Chip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityState={{ selected: active }} accessibilityLabel={label}\n      style={({ pressed }) => [{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderRadius: radios.lg, backgroundColor: active ? colors.primary : colors.surface, borderWidth: 1, borderColor: active ? colors.primary : colors.border, opacity: pressed ? 0.85 : 1 }]}>\n      <Text style={{ fontSize: tipografia.caption, fontWeight: active ? '700' : '500', color: active ? brand.white : colors.textPrimary }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  planBanner: { borderRadius: radios.md, padding: espaciado.e14, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: espaciado.e16 },\n  label: { fontSize: tipografia.caption, fontWeight: '700', color: c.textPrimary, marginTop: espaciado.e14, marginBottom: espaciado.e6 },\n  counter: { fontSize: 10, color: c.textSecondary, textAlign: 'right', marginBottom: espaciado.e4 },\n  area: { minHeight: 90, borderRadius: 10, borderWidth: 1, borderColor: c.border, backgroundColor: c.surface, color: c.textPrimary, padding: espaciado.e10, fontSize: tipografia.body, textAlignVertical: 'top' },\n});\n","/**\n * AlquilerScreen — Buscar Alquiler. Vista BUSCADOR v2.\n * Auditoría aplicada:\n *  · Error de red ≠ \"no hay anuncios\": estado de error dedicado con Reintentar\n *    y banner no intrusivo si hay datos previos y el refresco falla.\n *  · Modal de filtros con BORRADOR local: \"Aplicar\"/\"Cancelar\" de verdad\n *    (los chips no aplican en vivo) y \"Limpiar\" sobre el borrador.\n *  · SafeArea (insets.top/bottom), a11y completa (role/label/state),\n *    chips de filtro extraídos con key estable, chips activos para\n *    rentalType y minVerificationLevel, colores del tema en el aviso.\n *  · Catálogo en carga → spinner dentro del modal. Filtrado client-side\n *    (migración server-side anotada como mejora futura >200 anuncios).\n * Ruta: /alquiler\n */\n\nimport React, { useState } from 'react';\nimport { ActivityIndicator, FlatList, Modal, Pressable, ScrollView, StyleSheet, Switch, Text, TextInput, View, RefreshControl } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Plus, SlidersHorizontal, Check, X, ShieldAlert, MapPin, RefreshCw, WifiOff } from 'lucide-react-native';\nimport { alpha, brand, espaciado, GhostButton, PrimaryButton, radios, ScreenHeader, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { PropertyCard } from '../components/rental/PropertyCard';\nimport { usePropertySearch } from '../hooks/rental/usePropertySearch';\nimport type { SortOrder } from '../hooks/rental/usePropertyFilters';\nimport { DEFAULT_FILTERS, type PropertyFilters } from '../utils/propertyFilters';\n\nconst SORT_LABELS: Record<SortOrder, string> = { relevance: 'Relevancia', price_asc: 'Menor precio', price_desc: 'Mayor precio', newest: 'Más recientes', biggest: 'Más grandes' };\ntype RentalTypeId = NonNullable<PropertyFilters['rentalType']>;\nconst asRentalType = (id: string) => id as RentalTypeId;\n\nexport default function AlquilerScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n\n  const {\n    catalog, loading, error,\n    query, setQuery, filters, setFilters, toggle, reset, activeCount,\n    sortBy, setSortBy, filtered, visibleCount, loadMore,\n    onRefresh, refreshing, reload, properties,\n  } = usePropertySearch();\n\n  const [filterVisible, setFilterVisible] = useState(false);\n  const [draft, setDraft] = useState<PropertyFilters | null>(null);\n\n  const s = styles(colors);\n  const cityLabel = (id: string) => catalog?.cities.find((c) => c.id === id)?.label ?? id;\n  const typeLabel = (id: string) => catalog?.propertyTypes.find((x) => x.id === id)?.label ?? id;\n  const serviceLabel = (id: string) => catalog?.essentialServices.find((x) => x.id === id)?.label ?? id;\n  const rentalTypeLabel = (id: string) => catalog?.rentalTypes.find((x) => x.id === id)?.label ?? id;\n\n  /** Abre el modal copiando el estado aplicado como borrador. */\n  const openFilters = () => {\n    setDraft({ ...filters });\n    setFilterVisible(true);\n  };\n  const applyDraft = () => {\n    if (draft) setFilters(draft);\n    setFilterVisible(false);\n  };\n  const cancelDraft = () => { setDraft(null); setFilterVisible(false); };\n  const clearDraft = () => setDraft({ ...DEFAULT_FILTERS });\n\n  const toggleDraft = (field: 'neighborhoods' | 'types' | 'essentialServices', id: string) =>\n    setDraft((d) => (d ? { ...d, [field]: d[field].includes(id) ? d[field].filter((x) => x !== id) : [...d[field], id] } : d));\n\n  const anyResult = filtered.length > 0;\n  const hasSearchOrFilters = activeCount > 0 || query.trim().length > 0;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera del kit desde el 24/09/2026 (unificación de las 21 cabeceras).\n          `lineasTitulo={2}` porque «Alquileres en Guinea Ecuatorial» son 31 caracteres y el ancho\n          útil del título es 280 dp (~22,9 caracteres a `subCabecera`): en una línea se corta. */}\n      <ScreenHeader\n        titulo=\"Alquileres en Guinea Ecuatorial\"\n        subtitulo={`${filtered.length} anuncios`}\n        alVolver={() => router.back()}\n        lineasTitulo={2}\n        accion={\n          <Tactil onPress={() => router.push('/alquiler-publicar' as never)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Publicar propiedad\">\n            <Plus size={22} color={colors.primary} />\n          </Tactil>\n        }\n      />\n\n      {/* Buscador + botón filtros */}\n      <View style={{ paddingHorizontal: espaciado.e16, gap: espaciado.e8, marginBottom: espaciado.e6 }}>\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n          <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', backgroundColor: colors.surface, borderRadius: 10, paddingHorizontal: espaciado.e12, borderWidth: 1, borderColor: colors.border }}>\n            <TextInput\n              value={query}\n              onChangeText={setQuery}\n              placeholder=\"Buscar por título, barrio o dirección…\"\n              placeholderTextColor={colors.textSecondary}\n              accessibilityLabel=\"Buscar alquileres\"\n              style={{ flex: 1, paddingVertical: espaciado.e10, fontSize: tipografia.body, color: colors.textPrimary }}\n            />\n          </View>\n          <Pressable\n            onPress={openFilters}\n            accessibilityRole=\"button\"\n            accessibilityLabel={activeCount ? `Filtros aplicados (${activeCount})` : 'Abrir filtros'}\n            accessibilityState={{ selected: activeCount > 0 }}\n            style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, backgroundColor: activeCount ? colors.primary : colors.surface, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, borderRadius: 10, borderWidth: 1, borderColor: activeCount ? colors.primary : colors.border, opacity: pressed ? 0.85 : 1 }]}\n          >\n            <SlidersHorizontal size={15} color={activeCount ? brand.white : colors.textPrimary} />\n            {activeCount > 0 && <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: brand.white }}>{activeCount}</Text>}\n          </Pressable>\n        </View>\n        {/* Orden */}\n        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e6 }} accessibilityLabel=\"Ordenar resultados\">\n          {Object.entries(SORT_LABELS).map(([k, label]) => (\n            <Pressable\n              key={k}\n              onPress={() => setSortBy(k as SortOrder)}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Ordenar por ${label}`}\n              accessibilityState={{ selected: sortBy === k }}\n              style={({ pressed }) => [{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, borderRadius: radios.lg, backgroundColor: sortBy === k ? colors.primary : colors.surface, opacity: pressed ? 0.85 : 1 }]}\n            >\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: sortBy === k ? brand.white : colors.textSecondary }}>{label}</Text>\n            </Pressable>\n          ))}\n        </ScrollView>\n      </View>\n\n      {/* Aviso anti-estafa (tokens del tema) */}\n      <View style={{ marginHorizontal: espaciado.e16, marginBottom: espaciado.e8, flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, backgroundColor: alpha(colors.danger, 0.08), paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, borderRadius: 10 }}>\n        <ShieldAlert size={16} color={colors.danger} />\n        <Text style={{ flex: 1, fontSize: tipografia.caption, color: colors.danger, fontWeight: '600', lineHeight: 16 }}>\n          No pagues por adelantado ni envíes DNI antes de ver el inmueble. Denuncia anuncios sospechosos.\n        </Text>\n      </View>\n\n      {/* Banner de datos desactualizados (refresco fallido con datos previos) */}\n      {!loading && error && anyResult && (\n        <View style={{ marginHorizontal: espaciado.e16, marginBottom: espaciado.e8, flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, backgroundColor: alpha(colors.danger, 0.07), paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderRadius: 10 }}>\n          <WifiOff size={14} color={colors.danger} />\n          <Text style={{ flex: 1, fontSize: tipografia.micro, color: colors.danger, fontWeight: '600' }}>No se pudo actualizar: mostrando datos anteriores.</Text>\n          <Pressable onPress={() => void reload()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar actualizar\" hitSlop={8}>\n            <Text style={{ fontSize: tipografia.micro, color: colors.danger, fontWeight: '800' }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      )}\n\n      {/* Chips de filtros activos */}\n      {activeCount > 0 && (\n        <View style={{ paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e6 }}>\n          <ScrollView horizontal showsHorizontalScrollIndicator={false}>\n            {filters.cityId ? <ActiveChip label={`📍 ${cityLabel(filters.cityId)}`} onRemove={() => setFilters((f) => ({ ...f, cityId: undefined }))} /> : null}\n            {filters.rentalType ? <ActiveChip label={rentalTypeLabel(filters.rentalType)} onRemove={() => setFilters((f) => ({ ...f, rentalType: undefined }))} /> : null}\n            {filters.neighborhoods.map((n) => <ActiveChip key={n} label={n} onRemove={() => toggle('neighborhoods', n)} />)}\n            {filters.types.map((t) => <ActiveChip key={t} label={typeLabel(t)} onRemove={() => toggle('types', t)} />)}\n            {filters.essentialServices.map((e) => <ActiveChip key={e} label={serviceLabel(e)} onRemove={() => toggle('essentialServices', e)} />)}\n            {filters.isSocialHousingOnly ? <ActiveChip label=\"Vivienda social\" onRemove={() => setFilters((f) => ({ ...f, isSocialHousingOnly: false }))} /> : null}\n            {filters.hasTerrace ? <ActiveChip label=\"Con terraza\" onRemove={() => setFilters((f) => ({ ...f, hasTerrace: false }))} /> : null}\n            {filters.isLand ? <ActiveChip label=\"Terrenos\" onRemove={() => setFilters((f) => ({ ...f, isLand: false, landUse: [] }))} /> : null}\n            {(filters.minVerificationLevel ?? 0) >= 2 ? <ActiveChip label=\"Solo verificados\" onRemove={() => setFilters((f) => ({ ...f, minVerificationLevel: undefined }))} /> : null}\n          </ScrollView>\n        </View>\n      )}\n\n      <FlatList\n        data={filtered.slice(0, visibleCount)}\n        keyExtractor={(item) => String(item.id)}\n        contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingBottom: insets.bottom + 40 }}\n        refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.primary} colors={[colors.primary]} />}\n        renderItem={({ item }) => (\n          <PropertyCard\n            property={item}\n            onPress={() => router.push({ pathname: '/alquiler-detalle', params: { id: item.id } } as never)}\n            onViewLandlord={(l) => router.push({ pathname: '/landlord-profile', params: { landlordId: l.id ?? '' } } as never)}\n          />\n        )}\n        ListEmptyComponent={\n          loading && properties.length === 0 ? (\n            <View style={{ alignItems: 'center', marginTop: 60 }}>\n              <ActivityIndicator size=\"large\" color={colors.primary} />\n              <Text style={{ marginTop: espaciado.e12, color: colors.textSecondary, fontWeight: '700' }}>Cargando alquileres…</Text>\n            </View>\n          ) : !loading && error && properties.length === 0 ? (\n            <View style={{ alignItems: 'center', marginTop: 50, paddingHorizontal: espaciado.e30 }}>\n              <View style={[s.errIcon, { backgroundColor: alpha(colors.danger, 0.1) }]}><WifiOff size={28} color={colors.danger} /></View>\n              <Text style={{ fontSize: 15, fontWeight: '800', color: colors.textPrimary, textAlign: 'center' }}>No pudimos cargar los alquileres</Text>\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, marginBottom: espaciado.e14 }}>{error}</Text>\n              <Pressable\n                onPress={() => void reload()}\n                accessibilityRole=\"button\" accessibilityLabel=\"Reintentar cargar alquileres\"\n                style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e10, borderRadius: 10, backgroundColor: colors.primary, opacity: pressed ? 0.85 : 1 }]}\n              >\n                <RefreshCw size={15} color={brand.white} /><Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body, marginLeft: espaciado.e6 }}>Reintentar</Text>\n              </Pressable>\n            </View>\n          ) : (\n            <View style={{ alignItems: 'center', marginTop: 50, paddingHorizontal: espaciado.e30 }}>\n              <View style={[s.errIcon, { backgroundColor: colors.surface }]}><MapPin size={30} color={colors.textSecondary} /></View>\n              <Text style={{ fontSize: 15, fontWeight: '800', color: colors.textPrimary, textAlign: 'center' }}>\n                {hasSearchOrFilters ? 'Sin resultados con estos filtros' : 'Aún no hay alquileres publicados'}\n              </Text>\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 }}>\n                {hasSearchOrFilters ? 'Prueba a quitar filtros o cambiar la búsqueda.' : 'Vuelve más tarde; publicamos nuevos anuncios cada día.'}\n              </Text>\n              {hasSearchOrFilters && <View style={{ marginTop: espaciado.e14 }}><GhostButton title=\"Limpiar filtros\" onPress={reset} /></View>}\n            </View>\n          )\n        }\n        ListFooterComponent={\n          visibleCount < filtered.length ? (\n            <Pressable\n              onPress={loadMore}\n              accessibilityRole=\"button\" accessibilityLabel=\"Cargar más anuncios\"\n              style={({ pressed }) => [{ paddingVertical: espaciado.e14, borderRadius: 10, backgroundColor: colors.surface, alignItems: 'center', opacity: pressed ? 0.7 : 1 }]}\n            >\n              <Text style={{ fontSize: tipografia.caption, color: colors.primary, fontWeight: '700' }}>Cargar más anuncios</Text>\n            </Pressable>\n          ) : null\n        }\n      />\n\n      {/* Modal de filtros (borrador local + Aplicar/Cancelar) */}\n      <Modal visible={filterVisible} transparent animationType=\"slide\" onRequestClose={cancelDraft}>\n        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' }}>\n          <View style={{ backgroundColor: colors.background, borderTopLeftRadius: 20, borderTopRightRadius: 20, maxHeight: '92%', padding: espaciado.e20, paddingBottom: Math.max(insets.bottom, 16) }}>\n            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: espaciado.e12 }}>\n              <Text style={{ fontSize: 17, fontWeight: '800', color: colors.textPrimary }}>Filtros</Text>\n              <Pressable onPress={cancelDraft} hitSlop={10} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar filtros\">\n                <X size={22} color={colors.textPrimary} />\n              </Pressable>\n            </View>\n\n            {loading && !catalog ? (\n              <View style={{ alignItems: 'center', paddingVertical: 50 }}>\n                <ActivityIndicator color={colors.primary} />\n                <Text style={{ marginTop: espaciado.e10, color: colors.textSecondary, fontSize: tipografia.caption }}>Cargando catálogo…</Text>\n              </View>\n            ) : draft ? (\n              <ScrollView showsVerticalScrollIndicator={false}>\n                <Text style={s.fLabel}>Ciudad</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>\n                  {(catalog?.cities ?? []).map((c) => (\n                    <FilterChip key={c.id} label={c.label} selected={draft.cityId === c.id} onPress={() => setDraft((d) => (d ? { ...d, cityId: d.cityId === c.id ? undefined : c.id } : d))} />\n                  ))}\n                </View>\n\n                <Text style={s.fLabel}>Tipo de propiedad</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>\n                  {(catalog?.propertyTypes ?? []).map((t) => (\n                    <FilterChip key={t.id} label={t.label} selected={draft.types.includes(t.id)} onPress={() => toggleDraft('types', t.id)} />\n                  ))}\n                </View>\n\n                <Text style={s.fLabel}>Tipo de alquiler</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>\n                  {(catalog?.rentalTypes ?? []).map((t) => (\n                    <FilterChip key={t.id} label={t.label} selected={draft.rentalType === asRentalType(t.id)} onPress={() => setDraft((d) => (d ? { ...d, rentalType: d.rentalType === asRentalType(t.id) ? undefined : asRentalType(t.id) } : d))} />\n                  ))}\n                </View>\n\n                <Text style={s.fLabel}>Barrio</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>\n                  {(catalog?.neighborhoods ?? []).filter((n) => !draft.cityId || n.cityId === draft.cityId).map((n) => (\n                    <FilterChip key={`${n.cityId}:${n.name}`} label={n.name} selected={draft.neighborhoods.includes(n.name)} onPress={() => toggleDraft('neighborhoods', n.name)} />\n                  ))}\n                </View>\n\n                <Text style={s.fLabel}>Servicios esenciales</Text>\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>\n                  {(catalog?.essentialServices ?? []).map((e) => (\n                    <FilterChip key={e.id} label={e.label} selected={draft.essentialServices.includes(e.id)} onPress={() => toggleDraft('essentialServices', e.id)} />\n                  ))}\n                </View>\n\n                <Text style={s.fLabel}>Otras opciones</Text>\n                <View style={{ gap: espaciado.e10, marginBottom: espaciado.e12 }}>\n                  <SwitchRow label=\"Solo vivienda social\" value={draft.isSocialHousingOnly} onChange={(v) => setDraft((d) => (d ? { ...d, isSocialHousingOnly: v } : d))} />\n                  <SwitchRow label=\"Con terraza\" value={draft.hasTerrace ?? false} onChange={(v) => setDraft((d) => (d ? { ...d, hasTerrace: v } : d))} />\n                  <SwitchRow label=\"Solo terrenos\" value={draft.isLand ?? false} onChange={(v) => setDraft((d) => (d ? { ...d, isLand: v, landUse: v ? d.landUse : [] } : d))} />\n                  <SwitchRow label=\"Solo verificados (nivel 2+)\" value={(draft.minVerificationLevel ?? 0) >= 2} onChange={(v) => setDraft((d) => (d ? { ...d, minVerificationLevel: v ? 2 : undefined } : d))} />\n                </View>\n              </ScrollView>\n            ) : null}\n\n            <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n              <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={cancelDraft} /></View>\n              <View style={{ flex: 1 }}><GhostButton title=\"Limpiar\" onPress={clearDraft} /></View>\n              <View style={{ flex: 1.4 }}><PrimaryButton title=\"Aplicar\" onPress={applyDraft} /></View>\n            </View>\n          </View>\n        </View>\n      </Modal>\n    </View>\n  );\n}\n\n/** Chip de filtro con key estable y a11y (rol/estado/label). */\nfunction FilterChip({ label, selected, onPress }: { label: string; selected: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityState={{ selected }}\n      accessibilityLabel={label}\n      style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderRadius: 20, marginRight: espaciado.e8, marginBottom: espaciado.e8, backgroundColor: selected ? colors.primary : colors.surface, borderWidth: 1, borderColor: selected ? colors.primary : colors.border, opacity: pressed ? 0.85 : 1 }]}\n    >\n      <Text style={{ fontSize: tipografia.caption, color: selected ? brand.white : colors.textPrimary, fontWeight: selected ? '700' : '500' }}>{label}</Text>\n      {selected && <Check size={12} color={brand.white} style={{ marginLeft: espaciado.e4 }} />}\n    </Pressable>\n  );\n}\n\nfunction ActiveChip({ label, onRemove }: { label: string; onRemove: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onRemove}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`Quitar filtro: ${label}`}\n      style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', backgroundColor: colors.surface, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5, borderRadius: 14, borderWidth: 1, borderColor: colors.primary, marginRight: espaciado.e6, opacity: pressed ? 0.7 : 1 }]}\n    >\n      <Text style={{ fontSize: tipografia.micro, color: colors.primary, fontWeight: '600' }}>{label}</Text>\n      <X size={12} color={colors.primary} style={{ marginLeft: espaciado.e4 }} />\n    </Pressable>\n  );\n}\n\nfunction SwitchRow({ label, value, onChange }: { label: string; value: boolean; onChange: (v: boolean) => void }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n      <Text style={{ fontSize: tipografia.body, color: colors.textPrimary, fontWeight: '600' }}>{label}</Text>\n      <Switch\n        value={value}\n        onValueChange={onChange}\n        trackColor={{ true: colors.primary, false: colors.border }}\n        accessibilityRole=\"switch\"\n        accessibilityLabel={label}\n        accessibilityState={{ checked: value }}\n      />\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  fLabel: { fontSize: tipografia.caption, fontWeight: '800', color: c.textPrimary, marginTop: espaciado.e14, marginBottom: espaciado.e8 },\n  errIcon: { width: 64, height: 64, borderRadius: 32, alignItems: 'center', justifyContent: 'center', marginBottom: espaciado.e14 },\n});\n","/**\n * PropertyCard — tarjeta de propiedad (adaptación del kit PropertyCard.jsx).\n * Usa useTheme + LazyImage + badges propios. Muestra precio condicional,\n * tamaño condicional (landSize vs size) y características según tipo.\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { alpha, brand, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { LazyImage } from './LazyImage';\nimport { FeaturedBadge, PremiumBadge, VerificationBadge } from './Badges';\nimport { LandlordCard, type LandlordCardData } from './LandlordCard';\nimport { formatXAF, getTimeAgo, getPropertyTypeLabel, isLandType, isCommercialSpecial } from '../../utils/formatHelpers';\nimport type { RentalProperty } from '../../api/rental';\n\nexport function PropertyCard({ property, onPress, onViewLandlord }: {\n  property: RentalProperty;\n  onPress: () => void;\n  onViewLandlord?: (landlord: LandlordCardData) => void;\n}) {\n  const { colors } = useTheme();\n  const isLand = isLandType(property.type);\n  const isCommercialSpecialType = isCommercialSpecial(property.type);\n\n  const displayPrice = () => {\n    if (property.rentalType === 'short_term' && property.price.pricePerNight) {\n      return `${formatXAF(property.price.pricePerNight)}/noche`;\n    }\n    return `${formatXAF(property.price.monthlyRent)}/mes`;\n  };\n\n  const displaySize = () => {\n    if (isLand && property.landSize) return `${property.landSize} m²`;\n    return property.size ? `${property.size} m²` : null;\n  };\n\n  const s = styles(colors);\n  return (\n    <Pressable onPress={onPress} style={({ pressed }) => [s.card, { borderColor: colors.border }, pressed && { opacity: 0.85 }]}>\n      {/* Imagen */}\n      <View style={s.imageContainer}>\n        <LazyImage\n          source={{ uri: property.photos?.[0]?.url }}\n          thumbnailSource={{ uri: property.photos?.[0]?.thumbnailUrl }}\n          style={s.image}\n        />\n        <View style={s.badgesTop}>\n          {property.isFeatured && <FeaturedBadge />}\n          {property.isPremium && <PremiumBadge />}\n          {property.isSocialHousing && <View style={s.socialBadge}><Text style={s.socialText}>Social</Text></View>}\n        </View>\n        {(isLand || isCommercialSpecialType) && (\n          <View style={s.typeBadge}><Text style={s.typeText}>{getPropertyTypeLabel(property.type)}</Text></View>\n        )}\n        {property.rentalType === 'short_term' && (\n          <View style={s.shortTermBadge}><Text style={s.shortTermText}>Por noche</Text></View>\n        )}\n      </View>\n\n      {/* Contenido */}\n      <View style={s.content}>\n        <View style={s.priceRow}>\n          <Text style={s.price}>{displayPrice()}</Text>\n          <VerificationBadge level={property.verificationLevel} minLevel={2} />\n        </View>\n        <Text style={s.title} numberOfLines={2}>{property.title}</Text>\n        <Text style={s.location} numberOfLines={1}>📍 {property.location.neighborhood}, {property.location.cityName}</Text>\n\n        <View style={s.featuresRow}>\n          {!isLand && property.rooms !== undefined && <Text style={s.feature}>🛏️ {property.rooms}</Text>}\n          {!isLand && property.bathrooms !== undefined && <Text style={s.feature}>🚿 {property.bathrooms}</Text>}\n          {displaySize() && <Text style={s.feature}>📐 {displaySize()}</Text>}\n          {property.amenities.terrace && <Text style={s.feature}>☀️ Terraza</Text>}\n          {property.type === 'land_agriculture' && <Text style={s.feature}>🌱 Agrícola</Text>}\n          {property.type === 'land_workshop' && <Text style={s.feature}>🔧 Taller</Text>}\n          {property.type === 'bar' && <Text style={s.feature}>🍻 Bar</Text>}\n          {property.type === 'nightclub' && <Text style={s.feature}>🎵 Disco</Text>}\n          {property.essentialServices.generator && <Text style={s.feature}>⚡</Text>}\n        </View>\n\n        <View style={[s.footer, { borderTopColor: colors.border }]}>\n          <LandlordCard\n            landlord={property.landlord}\n            variant=\"compact\"\n            showViewProfile={true}\n            onViewProfile={(l) => {\n              if (onViewLandlord) onViewLandlord(l);\n            }}\n          />\n          <Text style={s.freshness}>{getTimeAgo(property.lastUpdated)}</Text>\n        </View>      </View>\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  card: { borderRadius: 14, borderWidth: 1, marginBottom: espaciado.e12, overflow: 'hidden', backgroundColor: c.card },\n  imageContainer: { position: 'relative', height: 180 },\n  image: { width: '100%', height: '100%' },\n  badgesTop: { position: 'absolute', top: 8, left: 8, flexDirection: 'row', gap: espaciado.e4 },\n  socialBadge: { backgroundColor: brand.success, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4, borderRadius: 6 },\n  socialText: { color: brand.white, fontSize: 10, fontWeight: '700' },\n  typeBadge: { position: 'absolute', top: 8, right: 8, backgroundColor: 'rgba(15,23,42,0.85)', paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4, borderRadius: 6 },\n  typeText: { color: brand.white, fontSize: tipografia.micro, fontWeight: '600' },\n  shortTermBadge: { position: 'absolute', bottom: 8, left: 8, backgroundColor: 'rgba(0,0,0,0.75)', paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4, borderRadius: 6 },\n  shortTermText: { color: brand.white, fontSize: tipografia.micro, fontWeight: '600' },\n  content: { padding: espaciado.e12 },\n  priceRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: espaciado.e6 },\n  price: { fontSize: 17, fontWeight: '700', color: c.textPrimary },\n  title: { fontSize: tipografia.body, fontWeight: '600', color: c.textSecondary, marginBottom: espaciado.e4 },\n  location: { fontSize: tipografia.caption, color: c.textSecondary, marginBottom: espaciado.e8 },\n  featuresRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10, marginBottom: espaciado.e8 },\n  feature: { fontSize: tipografia.caption, color: c.textPrimary },\n  footer: { paddingTop: espaciado.e10, borderTopWidth: 1, gap: espaciado.e6 },\n  freshness: { fontSize: tipografia.micro, color: c.textSecondary, alignSelf: 'flex-end' },\n});\n","/**\n * usePropertySearch — orquesta el buscador completo de alquiler:\n * carga (lista + catálogo), refresh, debounce de la búsqueda, filtros,\n * ordenación y paginación por lotes (visibleCount). Compone los hooks\n * del módulo: useDebounce + usePropertyFilters + useFilteredProperties.\n */\n\nimport { useCallback, useEffect, useState } from 'react';\nimport { rentalApi, type RentalCatalog, type RentalProperty } from '../../api/rental';\nimport { useDebounce } from './useDebounce';\nimport { usePropertyFilters } from './usePropertyFilters';\nimport { useFilteredProperties } from './useFilteredProperties';\n\nconst PAGE_SIZE = 10;\n\nexport function usePropertySearch() {\n  const { filters, setFilters, toggle, reset, activeCount, sortBy, setSortBy } = usePropertyFilters();\n\n  const [properties, setProperties] = useState<RentalProperty[]>([]);\n  const [catalog, setCatalog] = useState<RentalCatalog | null>(null);\n  const [query, setQuery] = useState('');\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE);\n\n  const load = useCallback(async () => {\n    try {\n      const [list, cat] = await Promise.all([rentalApi.properties(), rentalApi.catalog()]);\n      setProperties(list);\n      setCatalog(cat);\n      setError(null);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Error de red');\n    } finally {\n      setLoading(false);\n      setRefreshing(false);\n    }\n  }, []);\n\n  useEffect(() => { load(); }, [load]);\n\n  const debouncedQuery = useDebounce(query.trim().toLowerCase(), 300);\n  const filtered = useFilteredProperties(properties, filters, debouncedQuery, sortBy);\n\n  const onRefresh = useCallback(() => { setRefreshing(true); load(); }, [load]);\n\n  const loadMore = useCallback(() => setVisibleCount((c) => c + PAGE_SIZE), []);\n  const resetVisible = useCallback(() => setVisibleCount(PAGE_SIZE), []);\n\n  return {\n    // datos\n    properties, catalog, loading, refreshing, error,\n    // búsqueda y filtros\n    query, setQuery, debouncedQuery, filters, setFilters, toggle, reset, activeCount,\n    // orden y paginación\n    sortBy, setSortBy, filtered, visibleCount, loadMore, resetVisible,\n    // acciones\n    onRefresh, reload: load,\n  };\n}\n","/**\n * useDebounce — retrasa la propagación de un valor (búsqueda en vivo).\n * Uso: const debounced = useDebounce(query, 300);\n */\n\nimport { useEffect, useState } from 'react';\n\nexport function useDebounce<T>(value: T, delay = 300): T {\n  const [debounced, setDebounced] = useState(value);\n\n  useEffect(() => {\n    const t = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(t);\n  }, [value, delay]);\n\n  return debounced;\n}\n","/**\n * usePropertyFilters — estado de filtros del buscador de alquiler.\n * Gestiona PropertyFilters (kit) con toggles por lista, reset y contador\n * de filtros activos. Ordenación incluida (relevance | price_asc | ...).\n */\n\nimport { useMemo, useState } from 'react';\nimport { DEFAULT_FILTERS, type PropertyFilters } from '../../utils/propertyFilters';\n\nexport type SortOrder = 'relevance' | 'price_asc' | 'price_desc' | 'newest' | 'biggest';\n\nexport function usePropertyFilters(initial: PropertyFilters = DEFAULT_FILTERS) {\n  const [filters, setFilters] = useState<PropertyFilters>({ ...initial });\n  const [sortBy, setSortBy] = useState<SortOrder>('relevance');\n\n  /** Alterna un id dentro de una lista del filtro (neighborhoods|types|essentialServices|landUse). */\n  const toggle = (field: 'neighborhoods' | 'types' | 'essentialServices' | 'landUse', id: string) =>\n    setFilters((f) => ({\n      ...f,\n      [field]: (f[field] as string[]).includes(id)\n        ? (f[field] as string[]).filter((x) => x !== id)\n        : [...(f[field] as string[]), id],\n    }));\n\n  const reset = () => setFilters({ ...DEFAULT_FILTERS });\n\n  const activeCount = useMemo(() => {\n    let n = 0;\n    if (filters.cityId) n += 1;\n    n += filters.neighborhoods.length + filters.types.length + filters.essentialServices.length + (filters.landUse?.length ?? 0);\n    if (filters.rentalType) n += 1;\n    if (filters.isSocialHousingOnly) n += 1;\n    if (filters.hasTerrace) n += 1;\n    if (filters.isLand) n += 1;\n    if ((filters.minVerificationLevel ?? 0) >= 2) n += 1;\n    return n;\n  }, [filters]);\n\n  return { filters, setFilters, toggle, reset, activeCount, sortBy, setSortBy };\n}\n","/**\n * propertyFilters — filtros y ordenación en cliente (adaptación del kit).\n * Consume la forma normalizada del backend (RentalProperty).\n */\n\nimport type { RentalProperty } from '../api/rental';\nimport { isLandType } from './formatHelpers';\n\nexport interface PropertyFilters {\n  searchText?: string;\n  cityId?: string;\n  neighborhoods: string[];\n  rentalType?: 'long_term' | 'short_term' | 'both';\n  priceRange: { min: number; max: number };\n  types: string[];\n  rooms: { min: number; max: number };\n  essentialServices: string[];\n  isSocialHousingOnly: boolean;\n  minVerificationLevel?: number;\n  acceptsShortTerm: boolean;\n  acceptsLongTerm: boolean;\n  hasTerrace?: boolean;\n  isLand?: boolean;\n  landUse?: ('agriculture' | 'workshop' | 'other')[];\n}\n\nexport const DEFAULT_FILTERS: PropertyFilters = {\n  neighborhoods: [],\n  priceRange: { min: 0, max: 2000000 },\n  types: [],\n  rooms: { min: 0, max: 15 },\n  essentialServices: [],\n  isSocialHousingOnly: false,\n  acceptsShortTerm: true,\n  acceptsLongTerm: true,\n  hasTerrace: false,\n  isLand: false,\n  landUse: [],\n};\n\nexport function applyPropertyFilters(properties: RentalProperty[], filters: PropertyFilters): RentalProperty[] {\n  return properties.filter((p) => {\n    if (filters.searchText) {\n      const text = filters.searchText.toLowerCase();\n      const matches =\n        p.title.toLowerCase().includes(text) ||\n        p.description.toLowerCase().includes(text) ||\n        p.location.neighborhood.toLowerCase().includes(text) ||\n        p.location.address.toLowerCase().includes(text);\n      if (!matches) return false;\n    }\n\n    if (filters.cityId && p.location.cityId !== filters.cityId) return false;\n\n    if (filters.neighborhoods.length > 0 && !filters.neighborhoods.includes(p.location.neighborhood)) return false;\n\n    if (filters.rentalType && p.rentalType !== 'both' && p.rentalType !== filters.rentalType) return false;\n\n    if (!filters.acceptsShortTerm && p.rentalType === 'short_term') return false;\n    if (!filters.acceptsLongTerm && p.rentalType === 'long_term') return false;\n\n    const priceToCompare =\n      p.rentalType === 'short_term' && p.price.pricePerNight ? p.price.pricePerNight * 30 : p.price.monthlyRent ?? 0;\n    if (priceToCompare < filters.priceRange.min || priceToCompare > filters.priceRange.max) return false;\n\n    if (filters.types.length > 0 && !filters.types.includes(p.type)) return false;\n\n    if (p.rooms !== undefined && (p.rooms < filters.rooms.min || p.rooms > filters.rooms.max)) return false;\n\n    if (filters.isSocialHousingOnly && !p.isSocialHousing) return false;\n\n    if (filters.minVerificationLevel && p.verificationLevel < filters.minVerificationLevel) return false;\n\n    for (const service of filters.essentialServices) {\n      if (!p.essentialServices[service]) return false;\n    }\n\n    if (filters.hasTerrace && !p.amenities.terrace) return false;\n\n    if (filters.isLand && !isLandType(p.type)) return false;\n\n    if (filters.landUse && filters.landUse.length > 0) {\n      const matches = filters.landUse.some((use) => {\n        if (use === 'agriculture') return p.type === 'land_agriculture';\n        if (use === 'workshop') return p.type === 'land_workshop';\n        if (use === 'other') return p.type === 'land_other';\n        return false;\n      });\n      if (!matches) return false;\n    }\n\n    return true;\n  });\n}\n\nfunction searchScore(p: RentalProperty): number {\n  return p.searchScore ?? 0;\n}\n\nexport function sortProperties(\n  properties: RentalProperty[],\n  order: 'relevance' | 'price_asc' | 'price_desc' | 'newest' | 'biggest',\n): RentalProperty[] {\n  const sorted = [...properties];\n  switch (order) {\n    case 'relevance':\n      return sorted.sort((a, b) => searchScore(b) - searchScore(a));\n    case 'price_asc':\n      return sorted.sort((a, b) => (a.price.monthlyRent ?? 0) - (b.price.monthlyRent ?? 0));\n    case 'price_desc':\n      return sorted.sort((a, b) => (b.price.monthlyRent ?? 0) - (a.price.monthlyRent ?? 0));\n    case 'newest':\n      return sorted.sort((a, b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime());\n    case 'biggest':\n      return sorted.sort((a, b) => ((b.landSize ?? b.size ?? 0) - (a.landSize ?? a.size ?? 0)));\n    default:\n      return sorted;\n  }\n}\n","/**\n * useFilteredProperties — aplica applyPropertyFilters + sortProperties\n * (kit) sobre una lista, memoizado. El texto de búsqueda debe venir ya\n * debounced desde el consumidor (ver useDebounce).\n */\n\nimport { useMemo } from 'react';\nimport { applyPropertyFilters, sortProperties, type PropertyFilters } from '../../utils/propertyFilters';\nimport type { RentalProperty } from '../../api/rental';\nimport type { SortOrder } from './usePropertyFilters';\n\nexport function useFilteredProperties(\n  properties: RentalProperty[],\n  filters: PropertyFilters,\n  searchText: string,\n  order: SortOrder,\n): RentalProperty[] {\n  return useMemo(\n    () => sortProperties(applyPropertyFilters(properties, { ...filters, searchText }), order),\n    [properties, filters, searchText, order],\n  );\n}\n","/**\r\n * OnboardingAuthScreen — flujo de cuenta SIN PIN (EG Route Plan).\r\n * Modos:\r\n *   · 'terms'   → aceptar Términos de Uso (primer paso al usar un servicio).\r\n *   · 'phone'   → introducir teléfono (+240) → registrar (o reenviar OTP).\r\n *   · 'otp'     → código de verificación por SMS.\r\n *   · 'password'→ fijar contraseña de la cuenta (vinculada al teléfono).\r\n *   · 'login'   → entrar con teléfono + contraseña (cuentas existentes).\r\n * Tras completar → router.back() al servicio que lo solicitó.\r\n */\r\n\r\nimport React, { useEffect, useState } from 'react';\r\nimport { KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { espaciado, FormField, GhostButton, OtpInput, PrimaryButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { ArrowLeft, ShieldCheck } from 'lucide-react-native';\r\nimport { authApi, ApiError } from '../api/auth';\r\nimport { useSession } from '../state/session';\r\n\r\nconst PHONE_RE = /^\\+240\\d{9}$/;\r\nconst PWD_MIN = 6;\r\n\r\ntype Mode = 'terms' | 'phone' | 'otp' | 'password' | 'login';\r\n\r\nexport default function OnboardingAuthScreen() {\r\n  const { colors } = useTheme();\r\n  const insets = useSafeAreaInsets();\r\n  const router = useRouter();\r\n  const params = useLocalSearchParams<{ mode?: string }>();\r\n  const { login: sessionLogin, isAuthenticated } = useSession();\r\n\r\n  const [mode, setMode] = useState<Mode>(params.mode === 'login' ? 'login' : 'terms');\r\n  /**\r\n   * true mientras se está CREANDO la cuenta (ya hay sesión, pero falta la contraseña).\r\n   * Sin esta bandera, el efecto de abajo lanzaba `router.replace('/')` en cuanto el OTP era\r\n   * válido y la pantalla «Crea tu contraseña» quedaba sustituida antes de poder usarse: la cuenta\r\n   * se quedaba SIN contraseña (auditoría de diseño, D-34).\r\n   */\r\n  const [creandoCuenta, setCreandoCuenta] = useState(false);\r\n\r\n  // Si ya hay sesión, no mostrar el onboarding como pantalla inicial.\r\n  useEffect(() => {\r\n    if (isAuthenticated && !creandoCuenta) router.replace('/');\r\n    // eslint-disable-next-line react-hooks/exhaustive-deps\r\n  }, [isAuthenticated, creandoCuenta]);\r\n  const [busy, setBusy] = useState(false);\r\n  const [fullName, setFullName] = useState('');\r\n  const [phone, setPhone] = useState('+240');\r\n  const [otp, setOtp] = useState('');\r\n  const [password, setPassword] = useState('');\r\n  const [password2, setPassword2] = useState('');\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  const phoneOk = PHONE_RE.test(phone);\r\n  const pwdOk = password.length >= PWD_MIN;\r\n  const pwdMatch = password === password2 && pwdOk;\r\n\r\n  const fail = (e: unknown, fallback: string) => {\r\n    if (e instanceof ApiError) setError(e.message);\r\n    else if (e instanceof Error) setError(`${fallback}: ${e.message}`);\r\n    else setError(fallback);\r\n    console.error('[auth] error:', e);\r\n  };\r\n\r\n  const done = () => router.back();\r\n\r\n  // Paso 1: aceptar términos → pedir teléfono\r\n  const acceptTerms = () => { setError(null); setMode('phone'); };\r\n\r\n  // Paso 2: teléfono → registrar (o reenviar OTP si ya existe)\r\n  const submitPhone = async () => {\r\n    if (!phoneOk || busy) return;\r\n    setBusy(true); setError(null);\r\n    try {\r\n      await authApi.register(phone, fullName.trim() || undefined);\r\n      setMode('otp');\r\n    } catch (e) {\r\n      const code = e instanceof ApiError ? e.code : '';\r\n      if (code === 'PHONE_TAKEN') {\r\n        // Cuenta existente: reenviar OTP y verificar el mismo flujo.\r\n        try { await authApi.resendOtp(phone); setMode('otp'); }\r\n        catch (e2) { fail(e2, 'No se pudo enviar el código'); }\r\n      } else {\r\n        fail(e, 'No se pudo crear la cuenta');\r\n      }\r\n    } finally { setBusy(false); }\r\n  };\r\n\r\n  // Paso 3: OTP → verifica y emite sesión → pedir contraseña\r\n  const submitOtp = async (code: string) => {\r\n    if (busy) return;\r\n    setBusy(true); setError(null);\r\n    try {\r\n      const tokens = await authApi.verifyPhone(phone, code);\r\n      // La bandera va ANTES de iniciar sesión: el efecto mira `isAuthenticated` en cuanto cambie.\r\n      setCreandoCuenta(true);\r\n      await sessionLogin(tokens.accessToken, tokens.refreshToken, phone);\r\n      setMode('password');\r\n    } catch (e) {\r\n      fail(e, 'Código incorrecto');\r\n      setOtp('');\r\n    } finally { setBusy(false); }\r\n  };\r\n\r\n  // Paso 4: fijar contraseña → listo\r\n  const submitPassword = async () => {\r\n    if (!pwdMatch || busy) return;\r\n    setBusy(true); setError(null);\r\n    try {\r\n      await authApi.setPassword(password);\r\n      // Contraseña creada: ahora sí puede redirigir el efecto (y la cuenta queda completa).\r\n      setCreandoCuenta(false);\r\n      done();\r\n    } catch (e) {\r\n      fail(e, 'No se pudo guardar la contraseña');\r\n    } finally { setBusy(false); }\r\n  };\r\n\r\n  // Login: teléfono + contraseña\r\n  const submitLogin = async () => {\r\n    if (!phoneOk || !pwdOk || busy) return;\r\n    setBusy(true); setError(null);\r\n    try {\r\n      const tokens = await authApi.login(phone, password);\r\n      await sessionLogin(tokens.accessToken, tokens.refreshToken, phone);\r\n      done();\r\n    } catch (e) {\r\n      fail(e, 'No se pudo iniciar sesión');\r\n    } finally { setBusy(false); }\r\n  };\r\n\r\n  const switchToLogin = () => { setError(null); setMode('login'); setPassword(''); };\r\n  const switchToRegister = () => { setError(null); setMode('phone'); setPassword(''); };\r\n\r\n  return (\r\n    <KeyboardAvoidingView style={{ flex: 1, backgroundColor: colors.background }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\r\n      <ScrollView contentContainerStyle={[styles.content, { paddingTop: insets.top + 8, paddingBottom: insets.bottom + 24 }]} keyboardShouldPersistTaps=\"handled\">\r\n        <View style={styles.header}>\r\n          <Pressable onPress={() => (mode === 'terms' ? router.back() : setMode('terms'))} hitSlop={12} style={{ padding: espaciado.e4 }}>\r\n            <ArrowLeft size={22} color={colors.textPrimary} />\r\n          </Pressable>\r\n          <Text style={[styles.headerTitle, { color: colors.textPrimary }]}>\r\n            {mode === 'terms' ? 'Bienvenido' : mode === 'login' ? 'Iniciar sesión' : 'Crea tu cuenta'}\r\n          </Text>\r\n          <View style={{ width: 30 }} />\r\n        </View>\r\n\r\n        {error ? (\r\n          <Text style={[styles.error, { color: colors.danger }]}>{error}</Text>\r\n        ) : null}\r\n\r\n        {mode === 'terms' && (\r\n          <View style={styles.block}>\r\n            <View style={[styles.iconWrap, { backgroundColor: colors.primary + '1A' }]}>\r\n              <ShieldCheck size={40} color={colors.primary} />\r\n            </View>\r\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Términos de uso</Text>\r\n            <Text style={[styles.body, { color: colors.textSecondary }]}>\r\n              Para usar los servicios de Eg Route Plan necesitas aceptar los términos de uso y la política de privacidad.\r\n              Tu teléfono será la clave de tu cuenta y recibirás un código de verificación por SMS.\r\n            </Text>\r\n            <View style={styles.actions}>\r\n              <GhostButton title=\"No acepto\" onPress={() => router.back()} />\r\n              <PrimaryButton title=\"Aceptar\" onPress={acceptTerms} />\r\n            </View>\r\n          </View>\r\n        )}\r\n\r\n        {mode === 'phone' && (\r\n          <View style={styles.block}>\r\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Tu número de teléfono</Text>\r\n            <Text style={[styles.body, { color: colors.textSecondary }]}>\r\n              Es la condición para tener tu cuenta. Te enviaremos un código de verificación por SMS.\r\n            </Text>\r\n            <FormField\r\n              label=\"Nombre completo (opcional)\"\r\n              placeholder=\"María Nsue Obiang\"\r\n              value={fullName}\r\n              onChangeText={setFullName}\r\n              autoCapitalize=\"words\"\r\n            />\r\n            <View style={styles.gap} />\r\n            <FormField\r\n              label=\"Teléfono\"\r\n              placeholder=\"+240222000066\"\r\n              value={phone}\r\n              onChangeText={(t) => setPhone(t.replace(/[^0-9+]/g, '').slice(0, 13))}\r\n              keyboardType=\"phone-pad\"\r\n              error={phone.length > 4 && !phoneOk ? 'Formato: +240 seguido de 9 dígitos' : undefined}\r\n            />\r\n            <View style={styles.gap} />\r\n            <PrimaryButton title={busy ? 'Enviando…' : 'Recibir código'} onPress={submitPhone} disabled={!phoneOk || busy} loading={busy} />\r\n            <GhostButton title=\"¿Ya tienes cuenta? Inicia sesión\" onPress={switchToLogin} />\r\n          </View>\r\n        )}\r\n\r\n        {mode === 'otp' && (\r\n          <View style={styles.block}>\r\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Verifica tu teléfono</Text>\r\n            <Text style={[styles.body, { color: colors.textSecondary }]}>\r\n              Hemos enviado un código por SMS a {phone}\r\n            </Text>\r\n            <OtpInput value={otp} onChange={(c) => { setOtp(c); if (c.length === 6) submitOtp(c); }} />\r\n            <GhostButton title=\"Reenviar código\" onPress={async () => { try { await authApi.resendOtp(phone); setError(null); } catch (e) { fail(e, 'No se pudo reenviar'); } }} />\r\n            <GhostButton title=\"← Cambiar teléfono\" onPress={() => { setMode('phone'); setOtp(''); }} />\r\n          </View>\r\n        )}\r\n\r\n        {mode === 'password' && (\r\n          <View style={styles.block}>\r\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Crea tu contraseña</Text>\r\n            <Text style={[styles.body, { color: colors.textSecondary }]}>\r\n              Vinculada a tu teléfono {phone}. La usarás para entrar en la app.\r\n            </Text>\r\n            <FormField label=\"Contraseña\" placeholder=\"Mínimo 6 caracteres\" value={password} onChangeText={setPassword} secureTextEntry />\r\n            <View style={styles.gap} />\r\n            <FormField label=\"Repite la contraseña\" placeholder=\"Repite tu contraseña\" value={password2} onChangeText={setPassword2} secureTextEntry />\r\n            <View style={styles.gap} />\r\n            <PrimaryButton title={busy ? 'Guardando…' : 'Guardar y continuar'} onPress={submitPassword} disabled={!pwdMatch || busy} loading={busy} />\r\n          </View>\r\n        )}\r\n\r\n        {mode === 'login' && (\r\n          <View style={styles.block}>\r\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Iniciar sesión</Text>\r\n            <Text style={[styles.body, { color: colors.textSecondary }]}>Entra con tu teléfono y contraseña.</Text>\r\n            <FormField\r\n              label=\"Teléfono\"\r\n              placeholder=\"+240222000066\"\r\n              value={phone}\r\n              onChangeText={(t) => setPhone(t.replace(/[^0-9+]/g, '').slice(0, 13))}\r\n              keyboardType=\"phone-pad\"\r\n              error={phone.length > 4 && !phoneOk ? 'Formato: +240 seguido de 9 dígitos' : undefined}\r\n            />\r\n            <View style={styles.gap} />\r\n            <FormField label=\"Contraseña\" placeholder=\"Tu contraseña\" value={password} onChangeText={setPassword} secureTextEntry />\r\n            <View style={styles.gap} />\r\n            <PrimaryButton title={busy ? 'Entrando…' : 'Entrar'} onPress={submitLogin} disabled={!phoneOk || !pwdOk || busy} loading={busy} />\r\n            <GhostButton title=\"¿No tienes cuenta? Crea una\" onPress={switchToRegister} />\r\n          </View>\r\n        )}\r\n      </ScrollView>\r\n    </KeyboardAvoidingView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  content: { padding: espaciado.e24, paddingBottom: 48, gap: espaciado.e16 },\r\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: espaciado.e8 },\r\n  headerTitle: { fontSize: 17, fontWeight: '800' },\r\n  block: { gap: espaciado.e12, alignItems: 'stretch' },\r\n  iconWrap: { width: 80, height: 80, borderRadius: 40, alignItems: 'center', justifyContent: 'center', alignSelf: 'center', marginTop: espaciado.e12 },\r\n  title: { fontSize: tipografia.title, fontWeight: '800', textAlign: 'center' },\r\n  body: { fontSize: tipografia.body, lineHeight: 20, textAlign: 'center', fontWeight: '600' },\r\n  actions: { gap: espaciado.e10, marginTop: espaciado.e8 },\r\n  gap: { height: 8 },\r\n  error: { fontSize: tipografia.body, fontWeight: '700', textAlign: 'center' },\r\n});\r\n","/**\n * Cliente de autenticación unificada (mobility.users maestra).\n * Flujo SIN PIN: registro (teléfono) → OTP → verify → set-password → login\n * con contraseña. Usa httpClient (sesión inyectada + refresco 401 silencioso).\n */\n\nimport { http, ApiError } from './httpClient';\n\nexport { ApiError };\n\nexport interface AuthTokens {\n  accessToken: string;\n  refreshToken: string;\n}\n\nexport interface RegisterResult {\n  sent: boolean;\n  expiresIn: number;\n  devCode?: string; // solo entorno no-producción\n}\n\nexport interface ProfileLink {\n  /**\n   * `group` NO es una dirección: `value` es el CÓDIGO del grupo (6 caracteres). Se elige\n   * de mis grupos con el selector, no se escribe a mano. El código caduca a los 7 días,\n   * y el perfil público lo comprueba antes de pintar la tarjeta.\n   */\n  kind: 'link' | 'email' | 'phone' | 'social' | 'group';\n  label: string;\n  value: string;\n  /**\n   * Enlace FIJADO: se enseña arriba y con 📌 en el perfil público. Máximo 3 (lo aplica\n   * el servidor: si llegan más, mantiene los tres primeros y desfija el resto).\n   */\n  pinned?: boolean;\n}\n\nexport interface MeProfile {\n  id: string;\n  phone: string;\n  fullName: string;\n  role: 'PASSENGER' | 'DRIVER' | 'ADMIN';\n  status: string;\n  ratingAvg: number;\n  /** P7 perfil vivo: viajes completados (taxi) y foto de avatar. */\n  completedTrips: number;\n  avatarUrl?: string | null;\n  /** P8: portada + datos personales/profesionales + widgets + enlaces. */\n  coverUrl?: string | null;\n  bio?: string;\n  gender?: string;\n  birthDate?: string;\n  country?: string;\n  countryCode?: string;\n  city?: string;\n  profession?: string;\n  school?: string;\n  originalCreator?: string;\n  /** Color del nombre elegido por el usuario (portadas/tarjetas). */\n  nameColor?: string;\n  widgets?: Record<string, unknown>;\n  links?: ProfileLink[];\n  memberSince?: string;\n  kycLevel: number;\n}\n\n/** Preferencias por defecto de widgets (qué ven los visitantes). */\nexport const DEFAULT_WIDGETS = {\n  lifebookPublic: true,\n  showStats: true,\n  showStore: false,\n  showContact: true,\n  showQR: true,\n} as const;\n\n/** Payload completo del editor de perfil (P8). */\nexport interface UpdateProfilePayload {\n  fullName?: string;\n  avatar?: string;      // dataURL nueva (solo si cambió)\n  cover?: string;       // dataURL nueva portada (solo si cambió)\n  bio?: string;\n  gender?: string;\n  birthDate?: string;\n  country?: string;\n  countryCode?: string;\n  city?: string;\n  profession?: string;\n  school?: string;\n  originalCreator?: string;\n  nameColor?: string;\n  widgets?: Record<string, unknown>;\n  links?: ProfileLink[];\n}\n\nexport const authApi = {\n  /** Crea la cuenta (teléfono) y envía el OTP. Si ya existe → PHONE_TAKEN (usa resendOtp). */\n  register: (phone: string, fullName?: string) =>\n    http.post<RegisterResult>('/mobility/auth/register', { phone, fullName }, false),\n\n  resendOtp: (phone: string) =>\n    http.post<RegisterResult>('/mobility/auth/resend-otp', { phone }, false),\n\n  /** Verifica el OTP → emite la sesión (access + refresh). */\n  verifyPhone: (phone: string, otp: string) =>\n    http.post<AuthTokens>('/mobility/auth/verify-phone', { phone, otp }, false),\n\n  /** Fija la contraseña de la cuenta (requiere la sesión recién emitida). */\n  setPassword: (password: string) =>\n    http.post<{ ok: true }>('/mobility/auth/set-password', { password }, true),\n\n  /** Entra con teléfono + contraseña. */\n  login: (phone: string, password: string) =>\n    http.post<AuthTokens>('/mobility/auth/login', { phone, password }, false),\n\n  me: () => http.get<MeProfile>('/mobility/auth/me', true),\n\n  /** Actualiza el perfil (P7/P8: nombre, avatar, portada, bio, género, fecha,\n   *  país/ciudad, profesión, escuela, original, widgets y enlaces). */\n  updateMe: (data: UpdateProfilePayload) =>\n    http.patch<MeProfile>('/mobility/auth/me', data, true),\n};\n","// egrouteplan-app/app/billing-checkout.tsx\r\n/**\r\n * BillingCheckoutScreen — comprar un plan (Billing/Payments Core).\r\n * Crea la orden (precio SIEMPRE del servidor), instrucciones de pago, subida de\r\n * comprobante MULTIPART (cámara/galería, jpg/png, máx 5 MB) con monto y\r\n * referencia declarados, y estado de la orden.\r\n *\r\n * Auditoría senior (2026-09-02, v3 final — fusionada con la revisión del usuario):\r\n *  · LoadingState único ('idle'|'loading'|'creating'|'submitting'|'refreshing')\r\n *    — sin flags inconsistentes.\r\n *  · validación de monto con regla anti-monto-bajo (≥50% del precio del plan\r\n *    cuando el plan tiene precio) + error inline.\r\n *  · Permisos de cámara/galería explícitos con \"Abrir ajustes\" si se deniegan.\r\n *  · Comprobante MULTIPART (no base64): preview real, cambiar/quitar, 5 MB.\r\n *  · canSubmit SOLO pending_payment|rejected (endurecido igual que el backend:\r\n *    no se sobrescribe durante la revisión).\r\n *  · Fecha con 'es-GQ' + hora (sin bugs de timezone del dispositivo).\r\n *  · KeyboardAvoidingView, testIDs, a11y, error recoverable con Reintentar,\r\n *    refresco al volver (useFocusEffect) y manual.\r\n * Ruta: /billing-checkout?planId= | ?orderId=\r\n */\r\n\r\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\r\nimport {\r\n  ActivityIndicator, Alert, Image as RNImage, KeyboardAvoidingView, Linking, Platform,\r\n  Pressable, ScrollView, StyleSheet, Text, View,\r\n} from 'react-native';\r\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport * as ImagePicker from 'expo-image-picker';\r\nimport { Camera, Check, Info, RefreshCw, X, XCircle } from 'lucide-react-native';\r\nimport { alpha, espaciado, FormField, GhostButton, PrimaryButton, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { billingApi, BillingOrder, BillingPlan } from '../api/billing';\r\nimport { formatXAF } from '../utils/formatHelpers';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\nconst STATUS_LABELS: Record<string, { label: string; color: string }> = {\r\n  pending_payment: { label: 'Pendiente de pago', color: brand.warning },\r\n  proof_submitted: { label: 'Comprobante recibido — en revisión (2–24 h)', color: brand.info },\r\n  under_review: { label: 'En revisión', color: brand.info },\r\n  approved: { label: 'Aprobado · derecho activo', color: brand.success },\r\n  rejected: { label: 'Rechazado', color: brand.danger },\r\n  cancelled: { label: 'Cancelado', color: brand.neutral },\r\n  expired: { label: 'Expirado', color: brand.neutral },\r\n  refunded: { label: 'Reembolsado', color: brand.info },\r\n};\r\nconst MAX_PROOF_MB = 5;\r\ntype LoadingState = 'idle' | 'loading' | 'creating' | 'submitting' | 'refreshing';\r\n\r\nexport default function BillingCheckoutScreen() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const { planId, orderId, module: moduleParam, targetType, targetId } = useLocalSearchParams<{\r\n    planId: string; orderId?: string; module?: string; targetType?: string; targetId?: string;\r\n  }>();\r\n  const targetModule = moduleParam || 'rental';\r\n\r\n  const [plan, setPlan] = useState<BillingPlan | null>(null);\r\n  const [order, setOrder] = useState<BillingOrder | null>(null);\r\n  const [loadingState, setLoadingState] = useState<LoadingState>('loading');\r\n  const [error, setError] = useState<string | null>(null);\r\n  const [proofUri, setProofUri] = useState<string | null>(null);\r\n  const [proofMime, setProofMime] = useState('image/jpeg');\r\n  const [declaredAmount, setDeclaredAmount] = useState('');\r\n  const [amountError, setAmountError] = useState<string | null>(null);\r\n  const [declaredRef, setDeclaredRef] = useState('');\r\n  const busyRef = useRef(false);\r\n\r\n  const load = useCallback(async (mode: 'initial' | 'quiet' = 'initial') => {\r\n    let alive = true;\r\n    if (mode === 'initial') { setLoadingState('loading'); setError(null); }\r\n    try {\r\n      if (orderId) {\r\n        const o = await billingApi.order(orderId);\r\n        if (!alive) return;\r\n        setOrder(o);\r\n        const plans = await billingApi.plans(o.module || targetModule);\r\n        if (!alive) return;\r\n        setPlan(plans.find((x) => x.id === o.planId) ?? null);\r\n      } else if (planId) {\r\n        const plans = await billingApi.plans(targetModule);\r\n        if (!alive) return;\r\n        setPlan(plans.find((x) => x.id === planId) ?? null);\r\n      } else {\r\n        setError('No se especificó un plan u orden.');\r\n      }\r\n    } catch {\r\n      if (alive && mode === 'initial') {\r\n        setError('No pudimos cargar el plan. Revisa tu conexión e inténtalo de nuevo.');\r\n      }\r\n    } finally {\r\n      if (alive && mode === 'initial') setLoadingState('idle');\r\n    }\r\n    return () => { alive = false; };\r\n  }, [planId, orderId, targetModule]);\r\n\r\n  useEffect(() => { load('initial'); }, [load]);\r\n\r\n  // Refresco silencioso al volver (el admin puede haber aprobado/rechazado).\r\n  useFocusEffect(\r\n    useCallback(() => {\r\n      if (order && loadingState === 'idle') load('quiet').catch(() => undefined);\r\n      // eslint-disable-next-line react-hooks/exhaustive-deps\r\n    }, [load]),\r\n  );\r\n\r\n  /* ── Validación del monto (opcional, entero > 0, anti monto-bajo ≥50% del plan) */\r\n  const amountStatus = useMemo(() => {\r\n    const t = declaredAmount.trim();\r\n    if (t === '') return 'empty' as const;\r\n    const n = Number(t);\r\n    if (!Number.isInteger(n) || n <= 0) return 'invalid' as const;\r\n    if (n > 50_000_000) return 'invalid' as const;\r\n    if (plan && plan.priceXaf > 0 && n < plan.priceXaf * 0.5) return 'low' as const;\r\n    return 'ok' as const;\r\n  }, [declaredAmount, plan]);\r\n\r\n  const validateAmount = useCallback((): boolean => {\r\n    if (amountStatus === 'empty') { setAmountError(null); return true; }\r\n    if (amountStatus === 'low') {\r\n      setAmountError(`El monto parece bajo. El precio del plan es ${formatXAF(plan?.priceXaf ?? 0)}.`);\r\n      return false;\r\n    }\r\n    if (amountStatus === 'invalid') {\r\n      setAmountError('El monto debe ser un número entero mayor que 0 (máx 50.000.000).');\r\n      return false;\r\n    }\r\n    setAmountError(null);\r\n    return true;\r\n  }, [amountStatus, plan]);\r\n\r\n  /* ── Crear orden ── */\r\n  const createOrder = async () => {\r\n    if (!planId || loadingState === 'creating' || busyRef.current) return;\r\n    busyRef.current = true;\r\n    setLoadingState('creating');\r\n    setError(null);\r\n    try {\r\n      const body: Record<string, string> = { planId };\r\n      if (targetModule !== 'rental') body.module = targetModule;\r\n      if (targetType) body.targetType = targetType;\r\n      else if (targetModule !== 'rental') body.targetType = 'user';\r\n      else body.targetType = 'landlord';\r\n      if (targetId) body.targetId = targetId;\r\n      const r = await billingApi.createOrder(body as any);\r\n      setOrder(r.order ?? null);\r\n      Alert.alert('Orden creada', r.message);\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : 'No se pudo crear la orden');\r\n    } finally {\r\n      busyRef.current = false;\r\n      setLoadingState('idle');\r\n    }\r\n  };\r\n\r\n  const refreshOrder = async () => {\r\n    if (!order || loadingState === 'refreshing') return;\r\n    setLoadingState('refreshing');\r\n    try {\r\n      setOrder(await billingApi.order(order.id));\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : 'No se pudo actualizar el estado');\r\n    } finally {\r\n      setLoadingState('idle');\r\n    }\r\n  };\r\n\r\n  /* ── Permisos + cámara/galería ── */\r\n  const pickProof = () => {\r\n    Alert.alert('Subir comprobante', 'Foto del comprobante (jpg/png, máx 5 MB):', [\r\n      { text: 'Cancelar', style: 'cancel' },\r\n      { text: '📷 Cámara', onPress: () => pickFrom('camera') },\r\n      { text: '🖼️ Galería', onPress: () => pickFrom('gallery') },\r\n    ]);\r\n  };\r\n\r\n  const pickFrom = async (source: 'gallery' | 'camera') => {\r\n    try {\r\n      let granted = false;\r\n      if (source === 'camera') {\r\n        const p = await ImagePicker.requestCameraPermissionsAsync();\r\n        granted = p.granted;\r\n      } else {\r\n        const p = await ImagePicker.requestMediaLibraryPermissionsAsync();\r\n        granted = p.granted;\r\n      }\r\n      if (!granted) {\r\n        Alert.alert('Permiso requerido', `Necesitamos acceso a tu ${source === 'camera' ? 'cámara' : 'galería'} para subir el comprobante.`, [\r\n          { text: 'Cancelar', style: 'cancel' },\r\n          { text: 'Abrir ajustes', onPress: () => Linking.openSettings() },\r\n        ]);\r\n        return;\r\n      }\r\n      const res = source === 'camera'\r\n        ? await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.7 })\r\n        : await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7 });\r\n      if (res.canceled || !res.assets?.[0]) return;\r\n      const a = res.assets[0];\r\n      if ((a.fileSize ?? 0) > MAX_PROOF_MB * 1024 * 1024) {\r\n        Alert.alert('Archivo demasiado pesado', `El comprobante debe pesar menos de ${MAX_PROOF_MB} MB.`);\r\n        return;\r\n      }\r\n      const type = a.mimeType ?? 'image/jpeg';\r\n      if (!type.startsWith('image/')) { Alert.alert('Archivo no válido', 'Sube una imagen (jpg o png).'); return; }\r\n      setProofUri(a.uri);\r\n      setProofMime(type === 'image/png' ? 'image/png' : 'image/jpeg');\r\n    } catch { /* picker cancelado por el sistema */ }\r\n  };\r\n\r\n  /* ── Enviar comprobante MULTIPART ── */\r\n  const submitProof = async () => {\r\n    if (!order || !proofUri || loadingState === 'submitting' || busyRef.current) return;\r\n    if (!validateAmount()) return;\r\n    busyRef.current = true;\r\n    setLoadingState('submitting');\r\n    setError(null);\r\n    try {\r\n      const form = new FormData();\r\n      form.append('file', { uri: proofUri, name: `comprobante.${proofMime === 'image/png' ? 'png' : 'jpg'}`, type: proofMime } as unknown as Blob);\r\n      if (amountStatus === 'ok') form.append('declaredAmountXaf', String(Number(declaredAmount)));\r\n      if (declaredRef.trim()) form.append('declaredReference', declaredRef.trim());\r\n      const r = await billingApi.submitProof(order.id, form);\r\n      Alert.alert('Comprobante enviado', r.message);\r\n      setProofUri(null);\r\n      setDeclaredAmount('');\r\n      setDeclaredRef('');\r\n      setAmountError(null);\r\n      await refreshOrder();\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : 'No se pudo subir el comprobante');\r\n    } finally {\r\n      busyRef.current = false;\r\n      setLoadingState('idle');\r\n    }\r\n  };\r\n\r\n  const canSubmit = !!order\r\n    && (order.status === 'pending_payment' || order.status === 'rejected')\r\n    && !!proofUri\r\n    && amountStatus !== 'invalid'\r\n    && amountStatus !== 'low';\r\n\r\n  const st = STATUS_LABELS[order?.status ?? ''] ?? { label: order?.status ?? '', color: colors.textSecondary };\r\n  const s = styles(colors);\r\n\r\n  if (loadingState === 'loading') {\r\n    return (\r\n      <View style={[s.center, { backgroundColor: colors.background }]}>\r\n        <ActivityIndicator size=\"large\" color={colors.primary} />\r\n        <Text style={{ marginTop: espaciado.e12, color: colors.textSecondary }}>Cargando…</Text>\r\n      </View>\r\n    );\r\n  }\r\n  if (error && !plan) {\r\n    return (\r\n      <View style={[s.center, { backgroundColor: colors.background, padding: espaciado.e24 }]}>\r\n        <XCircle size={48} color={colors.danger} />\r\n        <Text style={{ color: colors.danger, fontWeight: '700', marginTop: espaciado.e12, textAlign: 'center' }}>{error}</Text>\r\n        <View style={{ marginTop: espaciado.e16 }}><GhostButton title=\"Reintentar\" onPress={() => load('initial')} /></View>\r\n        <View style={{ marginTop: espaciado.e8 }}><GhostButton title=\"Volver\" onPress={() => router.back()} /></View>\r\n      </View>\r\n    );\r\n  }\r\n  if (!plan) {\r\n    return (\r\n      <View style={[s.center, { backgroundColor: colors.background, padding: espaciado.e24 }]}>\r\n        <Text style={{ color: colors.danger, fontWeight: '700' }}>Plan no encontrado</Text>\r\n        <GhostButton title=\"Volver\" onPress={() => router.back()} />\r\n      </View>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <KeyboardAvoidingView\r\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\r\n      style={{ flex: 1, backgroundColor: colors.background }}\r\n    >\r\n      {/* Cabecera del kit desde el 24/09/2026. El `paddingTop` de la zona segura va por `style`,\r\n          que es exactamente para lo que el componente lo admite. */}\r\n      <ScreenHeader\r\n        titulo=\"Checkout\"\r\n        alVolver={() => router.back()}\r\n        style={{ paddingTop: insets.top }}\r\n      />\r\n\r\n      <ScrollView\r\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e24 + insets.bottom }}\r\n        showsVerticalScrollIndicator={false}\r\n        keyboardShouldPersistTaps=\"handled\"\r\n      >\r\n        {error && (\r\n          <View style={[s.card, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06), marginBottom: espaciado.e12 }]}>\r\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\r\n              <XCircle size={16} color={colors.danger} />\r\n              <Text style={{ flex: 1, color: colors.danger, fontWeight: '600', fontSize: tipografia.body }}>{error}</Text>\r\n            </View>\r\n            <Pressable onPress={() => load('initial')} style={{ marginTop: espaciado.e8, alignSelf: 'flex-start' }} accessibilityRole=\"button\">\r\n              <Text style={{ color: colors.primary, fontWeight: '700', fontSize: tipografia.caption }}>Reintentar</Text>\r\n            </Pressable>\r\n          </View>\r\n        )}\r\n\r\n        {/* Plan */}\r\n        <View style={[s.card, { borderColor: colors.border }]}>\r\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e8 }}>\r\n            <Text style={{ fontSize: tipografia.subtitle, fontWeight: '700', color: colors.textPrimary, flex: 1 }}>{plan.name}</Text>\r\n            <Text style={{ fontSize: 18, fontWeight: '800', color: colors.primary }}>{formatXAF(plan.priceXaf)}</Text>\r\n          </View>\r\n          {plan.description ? <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e4 }}>{plan.description}</Text> : null}\r\n        </View>\r\n\r\n        {/* Orden */}\r\n        {!order ? (\r\n          <View style={{ marginTop: espaciado.e16, gap: espaciado.e10 }}>\r\n            <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, lineHeight: 18 }}>\r\n              Al confirmar se creará tu orden de compra. El precio lo calcula el servidor (no es editable). Después recibirás las instrucciones de pago y podrás subir el comprobante.\r\n            </Text>\r\n            <PrimaryButton title={loadingState === 'creating' ? 'Creando orden…' : 'Confirmar compra'} onPress={createOrder}\r\n              disabled={loadingState === 'creating'} loading={loadingState === 'creating'} testID=\"billing-create-order\" />\r\n          </View>\r\n        ) : (\r\n          <>\r\n            {/* Estado */}\r\n            <View style={[s.card, { borderColor: st.color, backgroundColor: alpha(st.color, 0.06), marginTop: espaciado.e14 }]}>\r\n              <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: st.color }}>{st.label}</Text>\r\n              <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e4 }}>\r\n                Orden {order.id.slice(0, 8)}… · {formatXAF(order.amountXaf)} · vence{' '}\r\n                {order.expiresAt\r\n                  ? new Date(order.expiresAt).toLocaleString('es-GQ', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })\r\n                  : '—'}\r\n              </Text>\r\n              {order.rejectionReason ? (\r\n                <View style={{ marginTop: espaciado.e8, flexDirection: 'row', alignItems: 'flex-start', gap: espaciado.e6 }}>\r\n                  <XCircle size={14} color={brand.danger} />\r\n                  <Text style={{ flex: 1, fontSize: tipografia.caption, color: brand.danger, fontWeight: '600' }}>Motivo: {order.rejectionReason}</Text>\r\n                </View>\r\n              ) : null}\r\n            </View>\r\n\r\n            {/* Instrucciones de pago */}\r\n            {(order.status === 'pending_payment' || order.status === 'rejected') && (\r\n              <View style={[s.card, { borderColor: colors.border, marginTop: espaciado.e12 }]}>\r\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginBottom: espaciado.e6 }}>\r\n                  <Info size={14} color={colors.primary} />\r\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>Instrucciones de pago</Text>\r\n                </View>\r\n                <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, lineHeight: 18 }}>\r\n                  {order.paymentInstructions ?? 'Paga por transferencia u Orange Money y sube el comprobante.'}\r\n                </Text>\r\n              </View>\r\n            )}\r\n\r\n            {/* Subir comprobante */}\r\n            {(order.status === 'pending_payment' || order.status === 'rejected') && (\r\n              <View style={{ marginTop: espaciado.e16, gap: espaciado.e10 }}>\r\n                <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>\r\n                  {order.status === 'rejected' ? 'Sube un nuevo comprobante' : 'Sube tu comprobante de pago'}\r\n                </Text>\r\n                {proofUri ? (\r\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\r\n                    <RNImage source={{ uri: proofUri }} style={{ width: 56, height: 56, borderRadius: radios.sm, backgroundColor: colors.surface }} />\r\n                    <View style={{ flex: 1 }}>\r\n                      <Text style={{ fontSize: tipografia.caption, color: colors.textPrimary, fontWeight: '700' }}>Comprobante adjunto</Text>\r\n                      <Text style={{ fontSize: 10.5, color: colors.textSecondary }}>jpg/png · máx 5 MB</Text>\r\n                    </View>\r\n                    <GhostButton title=\"Cambiar\" onPress={pickProof} />\r\n                    <Pressable onPress={() => setProofUri(null)} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Quitar comprobante\" testID=\"billing-remove-proof\">\r\n                      <X size={18} color={colors.textSecondary} />\r\n                    </Pressable>\r\n                  </View>\r\n                ) : (\r\n                  <Pressable\r\n                    onPress={pickProof}\r\n                    accessibilityRole=\"button\"\r\n                    accessibilityLabel=\"Subir foto del comprobante\"\r\n                    accessibilityHint=\"Abre cámara o galería\"\r\n                    testID=\"billing-pick-proof\"\r\n                    style={({ pressed }) => [s.proofBox, { backgroundColor: colors.surface, borderColor: colors.border, opacity: pressed ? 0.8 : 1 }]}\r\n                  >\r\n                    <Camera size={18} color={colors.primary} />\r\n                    <Text style={{ fontSize: tipografia.body, color: colors.primary, fontWeight: '700', marginLeft: espaciado.e8 }}>Foto del comprobante (cámara o galería)</Text>\r\n                  </Pressable>\r\n                )}\r\n\r\n                <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>Monto pagado (XAF) — opcional pero recomendado</Text>\r\n                <FormField\r\n                  value={declaredAmount}\r\n                  onChangeText={(t) => { setDeclaredAmount(t.replace(/[^\\d]/g, '').slice(0, 8)); if (amountError) setAmountError(null); }}\r\n                  onBlur={validateAmount}\r\n                  placeholder={String(plan.priceXaf)}\r\n                  keyboardType=\"number-pad\"\r\n                  accessibilityLabel=\"Monto pagado\"\r\n                  accessibilityHint=\"Introduce el monto que pagaste\"\r\n                  error={amountError ?? undefined}\r\n                />\r\n                <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>Referencia de la transferencia</Text>\r\n                <FormField\r\n                  value={declaredRef}\r\n                  onChangeText={setDeclaredRef}\r\n                  placeholder=\"Ej: transferencia 12:45, ref. 3456\"\r\n                  maxLength={120}\r\n                  accessibilityLabel=\"Referencia de transferencia\"\r\n                  accessibilityHint=\"Introduce la referencia del pago\"\r\n                />\r\n                <PrimaryButton\r\n                  title={loadingState === 'submitting' ? 'Enviando…' : 'Enviar comprobante'}\r\n                  onPress={submitProof}\r\n                  disabled={!canSubmit || loadingState === 'submitting'}\r\n                  loading={loadingState === 'submitting'}\r\n                  testID=\"billing-submit-proof\"\r\n                />\r\n                {!proofUri && (\r\n                  <Text style={{ textAlign: 'center', fontSize: tipografia.micro, color: colors.textSecondary }}>\r\n                    Añade la foto del comprobante para poder enviarlo.\r\n                  </Text>\r\n                )}\r\n              </View>\r\n            )}\r\n\r\n            {(order.status === 'proof_submitted' || order.status === 'under_review') && (\r\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e12, textAlign: 'center', lineHeight: 16 }}>\r\n                Tu comprobante está en revisión (2–24 h). Cuando lo aprueben, tu derecho quedará activo aquí mismo.\r\n              </Text>\r\n            )}\r\n\r\n            {order.status === 'approved' && (\r\n              <View style={{ marginTop: espaciado.e16 }}>\r\n                <PrimaryButton title=\"Ver mis derechos\" onPress={() => router.push('/billing-status' as any)} testID=\"billing-view-rights\" />\r\n              </View>\r\n            )}\r\n\r\n            {/* Refrescar estado */}\r\n            <Pressable\r\n              onPress={refreshOrder}\r\n              disabled={loadingState === 'refreshing'}\r\n              accessibilityRole=\"button\"\r\n              accessibilityLabel=\"Actualizar estado de la orden\"\r\n              testID=\"billing-refresh\"\r\n              style={[s.refreshRow, { opacity: loadingState === 'refreshing' ? 0.6 : 1 }]}\r\n            >\r\n              {loadingState === 'refreshing'\r\n                ? <ActivityIndicator size=\"small\" color={colors.textSecondary} />\r\n                : <RefreshCw size={14} color={colors.textSecondary} />}\r\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, fontWeight: '600' }}>\r\n                {loadingState === 'refreshing' ? 'Actualizando…' : 'Actualizar estado'}\r\n              </Text>\r\n            </Pressable>\r\n          </>\r\n        )}\r\n      </ScrollView>\r\n    </KeyboardAvoidingView>\r\n  );\r\n}\r\n\r\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\r\n  StyleSheet.create({\r\n    card: { borderRadius: radios.md, padding: espaciado.e14, borderWidth: 1 },\r\n    proofBox: { flexDirection: 'row', alignItems: 'center', padding: espaciado.e14, borderRadius: 10, borderWidth: 1 },\r\n    refreshRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, marginTop: espaciado.e16, paddingVertical: espaciado.e8 },\r\n    center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\r\n  });\r\n","// egrouteplan-app/app/billing-status.tsx\r\n/**\r\n * BillingStatusScreen — mis órdenes y derechos activos (Billing Core).\r\n *\r\n * Auditoría senior (2026-09-02, v2 — luz verde):\r\n *  · Carga con skeleton / error + Reintentar / pull-to-refresh (nunca\r\n *    \"No tienes derechos\" por un fallo de red).\r\n *  · Renovar/Reactivar/Contratar navega a la pantalla de planes del MÓDULO\r\n *    correcto (rental/work/ecomerse/intercity) — adiós al hardcode de Alquiler.\r\n *  · Copy de ciclo de vida con fecha y días restantes exactos (win-back).\r\n *  · Órdenes y derechos sin slugs: labels completos + módulo visible; fallback\r\n *    humanizado si el código no está mapeado (nunca un id en inglés).\r\n *  · Tipos sin `as any` (reason fields tipados); fechas `es-GQ`.\r\n *  · Cancelar solo en pending_payment con confirmación; SafeArea; a11y.\r\n * Ruta: /billing-status\r\n */\r\n\r\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\r\nimport { ActivityIndicator, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\r\nimport { useRouter } from 'expo-router';\r\nimport { SOPORTE, whatsappSoporte } from '../constants/soporte';\r\nimport { mensajeDeError } from '../constants/errores';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { BadgeCheck, Clock, Package, Receipt, XCircle } from 'lucide-react-native';\r\nimport { alpha, Aviso, EmptyState, espaciado, GhostButton, PrimaryButton, radios, ScreenHeader, Sheet, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { billingApi, BillingEntitlement } from '../api/billing';\r\nimport { formatDate, formatXAF } from '../utils/formatHelpers';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\nimport { ir } from '../constants/rutas';\r\n\r\nconst STATUS_LABELS: Record<string, { label: string; color: string }> = {\r\n  pending_payment: { label: 'Pendiente de pago', color: brand.warning },\r\n  proof_submitted: { label: 'Comprobante en revisión', color: brand.info },\r\n  under_review: { label: 'En revisión', color: brand.info },\r\n  approved: { label: 'Aprobado', color: brand.success },\r\n  rejected: { label: 'Rechazado', color: brand.danger },\r\n  cancelled: { label: 'Cancelada', color: brand.neutral },\r\n  reversed: { label: 'Reversada', color: brand.neutral },\r\n  refunded: { label: 'Reembolsada', color: brand.info },\r\n  expired: { label: 'Expirado', color: brand.neutral },\r\n  refund_status_partial: { label: 'Aprobada · reembolso parcial', color: brand.warning },\r\n};\r\n\r\nconst MODULE_LABEL: Record<string, string> = {\r\n  rental: 'Alquiler', work: 'Work', ecomerse: 'Mercado', intercity: 'Ciudad a Ciudad', food: 'Comida Rápida',\r\n};\r\n\r\n/** Nombre legible de un plan desde su código (evita slugs en inglés). */\r\nfunction entitlementLabel(code: string, module?: string | null): string {\r\n  const known: Record<string, string> = {\r\n    rental_verified: 'Plan Propietario Verificado',\r\n    rental_agency_pro: 'Plan Agencia Pro',\r\n    rental_premium: 'Plan Premium',\r\n    property_featured: 'Destacar propiedad',\r\n    landlord_premium: 'Badge premium del arrendador',\r\n    work_pro: 'Work Pro',\r\n    work_business: 'Work Business',\r\n    work_job_featured: 'Destacar oferta',\r\n    intercity_driver_pro: 'Intercity Pro',\r\n    intercity_driver_basic: 'Intercity Gratis',\r\n    ecomerse_shop_pro_max: 'Tienda Pro Max',\r\n    ecomerse_shop_pro: 'Tienda Pro',\r\n    ecomerse_shop_flash: 'Tienda Flash',\r\n    ecomerse_shop_basic: 'Tienda Gratis',\r\n    ecomerse_featured_lite: 'Destacar anuncio',\r\n    ecomerse_featured: 'Destacar anuncio',\r\n    food_purchase: 'Pago de pedido',\r\n  };\r\n  if (known[code]) return known[code];\r\n  if (code.includes('featured')) return 'Destacar anuncio';\r\n  const mod = MODULE_LABEL[module ?? moduleOf(code)] ?? 'Plan';\r\n  return `${mod} · ${code.replace(/^(rental|work|ecomerse|intercity|food)_/, '').replace(/_/g, ' ')}`;\r\n}\r\n\r\n/** Módulo inferido del código (si el entitlement no lo trae). */\r\nfunction moduleOf(code: string): string {\r\n  if (code.startsWith('rental') || code.startsWith('landlord') || code.startsWith('property')) return 'rental';\r\n  if (code.startsWith('work')) return 'work';\r\n  if (code.startsWith('ecomerse')) return 'ecomerse';\r\n  if (code.startsWith('intercity')) return 'intercity';\r\n  if (code.startsWith('food')) return 'food';\r\n  return 'rental';\r\n}\r\n\r\n/** Pantalla de planes por módulo (Renovar/Reactivar/Contratar). */\r\nconst MODULE_ROUTES: Record<string, string> = {\r\n  rental: '/alquiler-planes',\r\n  work: '/work-planes',\r\n  ecomerse: '/ecomerse-planes',\r\n  intercity: '/intercity-planes',\r\n};\r\n\r\ninterface OrderRow {\r\n  id: string; planCode: string; planName: string; module?: string | null; amountXaf: number;\r\n  status: string; createdAt: string; rejectionReason: string | null;\r\n  cancellationReason?: string | null; reversalReason?: string | null; refundStatus?: string | null;\r\n}\r\n\r\nexport default function BillingStatusScreen() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const [orders, setOrders] = useState<OrderRow[]>([]);\r\n  const [entitlements, setEntitlements] = useState<BillingEntitlement[]>([]);\r\n  const [loading, setLoading] = useState(true);\r\n  const [refreshing, setRefreshing] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n  const [cancellingOrderId, setCancellingOrderId] = useState<string | null>(null);\r\n  /**\r\n   * Confirmación con HOJA, no con modal del sistema (auditoría de diseño, D-03/D-20): el usuario ve\r\n   * el importe y el contexto mientras decide, y el botón de atrás no le deja a medias.\r\n   */\r\n  const [ordenACancelar, setOrdenACancelar] = useState<string | null>(null);\r\n  /** Aviso que aparece y se va: para informar, no para interrumpir. */\r\n  const [aviso, setAviso] = useState<string | null>(null);\r\n\r\n  const load = useCallback(async (mode: 'initial' | 'refresh' = 'initial') => {\r\n    if (mode === 'initial') { setLoading(true); setError(null); }\r\n    if (mode === 'refresh') setRefreshing(true);\r\n    try {\r\n      const [o, e] = await Promise.all([billingApi.myOrders(), billingApi.myEntitlements()]);\r\n      setOrders(o as OrderRow[]);\r\n      setEntitlements(e);\r\n      setError(null);\r\n    } catch {\r\n      if (mode === 'initial') setError('No pudimos cargar tus compras y derechos. Revisa tu conexión e inténtalo de nuevo.');\r\n    } finally {\r\n      setLoading(false);\r\n      setRefreshing(false);\r\n    }\r\n  }, []);\r\n\r\n  useEffect(() => { load(); }, [load]);\r\n\r\n  /** Renovar/Reactivar en la pantalla de planes del módulo correcto. */\r\n  const goRenew = (e: BillingEntitlement) => {\r\n    const mod = e.module || moduleOf(e.code);\r\n    const route = MODULE_ROUTES[mod];\r\n    if (route) {\r\n      router.push(route as any);\r\n    } else {\r\n      Alert.alert('Contacta soporte', `Este derecho no tiene plan de renovación en la app. Escríbenos: ${SOPORTE.email} · WhatsApp ${SOPORTE.telefono}`, [\r\n        { text: 'Cerrar', style: 'cancel' },\r\n        { text: 'WhatsApp', onPress: () => { void whatsappSoporte('Hola, necesito renovar un derecho de mi plan.'); } },\r\n      ]);\r\n    }\r\n  };\r\n\r\n  const cancelOrder = (orderId: string) => {\r\n    if (cancellingOrderId) return; // sin doble cancelación\r\n    // Abre la hoja: la confirmación se hace en pantalla, no en un modal del sistema.\r\n    setOrdenACancelar(orderId);\r\n  };\r\n\r\n  /** Cancela de verdad, ya confirmado en la hoja. */\r\n  const cancelarDeVerdad = async (orderId: string) => {\r\n    setOrdenACancelar(null);\r\n    setCancellingOrderId(orderId);\r\n    try {\r\n      await billingApi.cancelOrder(orderId, 'Cancelada por el usuario');\r\n      setAviso('Orden cancelada. Si ya pagaste, pide el reembolso con el botón de abajo.');\r\n      await load('refresh');\r\n    } catch (e) {\r\n      Alert.alert('Error', mensajeDeError(e, 'No se pudo cancelar la orden'));\r\n    } finally {\r\n      setCancellingOrderId(null);\r\n    }\r\n  };\r\n\r\n  // Filtros memoizados (no se recalculan en cada render).\r\n  const activeEnt = useMemo(() => entitlements.filter((e) => e.active), [entitlements]);\r\n  const expiringEnt = useMemo(\r\n    () => entitlements.filter((e) => e.status === 'expiring_soon' || (e.daysLeft != null && e.daysLeft <= 7)),\r\n    [entitlements],\r\n  );\r\n  const graceEnt = useMemo(() => entitlements.filter((e) => e.status === 'grace'), [entitlements]);\r\n  const expiredEnt = useMemo(() => entitlements.filter((e) => e.status === 'expired'), [entitlements]);\r\n\r\n  const daysCopy = (e: BillingEntitlement) => {\r\n    if (e.daysLeft != null && e.daysLeft >= 0) return `quedan ${e.daysLeft} día${e.daysLeft === 1 ? '' : 's'}`;\r\n    return 'muy pronto';\r\n  };\r\n\r\n  const s = styles(colors);\r\n\r\n  if (loading) {\r\n    return (\r\n      <View style={[s.root, { paddingTop: insets.top }]}>\r\n        <SkeletonHeader colors={colors} />\r\n        <View style={{ padding: espaciado.e16, gap: espaciado.e10 }}>\r\n          {[0, 1, 2].map((i) => (\r\n            <View key={i} style={{ height: 86, borderRadius: radios.md, backgroundColor: colors.border, width: i === 1 ? '90%' : '100%' }} />\r\n          ))}\r\n        </View>\r\n      </View>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <View style={[s.root, { paddingTop: insets.top }]}>\r\n      {/* Cabecera del kit desde el 24/09/2026. Aquí el volver es `ir.atras()` (el ayudante), no\r\n          `router.back()`: son las dos formas que convivían en las 21 copias. */}\r\n      <ScreenHeader\r\n        titulo=\"Mis compras y derechos\"\r\n        alVolver={() => ir.atras()}\r\n      />\r\n\r\n      {error ? (\r\n        <View style={{ alignItems: 'center', paddingTop: 60, paddingHorizontal: espaciado.e28 }}>\r\n          <Text style={{ fontSize: 38, marginBottom: espaciado.e8 }}>📡</Text>\r\n          <Text style={{ fontSize: 15, fontWeight: '800', color: colors.textPrimary, textAlign: 'center' }}>Algo salió mal</Text>\r\n          <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 }}>{error}</Text>\r\n          <Pressable onPress={() => load('initial')} accessibilityRole=\"button\" style={{ marginTop: espaciado.e18, backgroundColor: brand.secondary, paddingHorizontal: espaciado.e24, paddingVertical: espaciado.e11, borderRadius: 22 }}>\r\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\r\n          </Pressable>\r\n        </View>\r\n      ) : (\r\n        <ScrollView\r\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e32 + insets.bottom }}\r\n          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => load('refresh')} tintColor={colors.primary} />}\r\n        >\r\n          {/* Avisos de ciclo de vida */}\r\n          {expiringEnt[0] && (\r\n            <RenewCard\r\n              tone=\"warn\"\r\n              icon={<Clock size={16} color={brand.warningPressed} />}\r\n              title={expiringEnt[0].code.includes('featured') ? 'Tu destacado vence pronto' : 'Tu plan vence pronto'}\r\n              body={expiringEnt[0].expiresAt\r\n                ? `Vence el ${formatDate(expiringEnt[0].expiresAt)} · ${daysCopy(expiringEnt[0])}. Renueva para no perderlo.`\r\n                : 'Renueva para no perderlo.'}\r\n              cta=\"Renovar ahora\"\r\n              onPress={() => goRenew(expiringEnt[0])}\r\n              testID=\"billing-renew-expiring\"\r\n            />\r\n          )}\r\n          {graceEnt[0] && (\r\n            <RenewCard\r\n              tone=\"danger\"\r\n              icon={<XCircle size={16} color={brand.danger} />}\r\n              title=\"Tu plan venció — periodo de gracia\"\r\n              body={graceEnt[0].graceUntil\r\n                ? `Reactiva antes del ${formatDate(graceEnt[0].graceUntil)} (${daysCopy(graceEnt[0])}) para conservar tus beneficios.`\r\n                : 'Reactiva pronto para conservar tus beneficios.'}\r\n              cta=\"Reactivar ahora\"\r\n              onPress={() => goRenew(graceEnt[0])}\r\n              testID=\"billing-renew-grace\"\r\n            />\r\n          )}\r\n          {expiredEnt[0] && (\r\n            <RenewCard\r\n              tone=\"neutral\"\r\n              icon={<XCircle size={16} color={colors.textSecondary} />}\r\n              title=\"Tu plan venció\"\r\n              body=\"Contrata de nuevo para volver a disfrutar de los beneficios.\"\r\n              cta=\"Contratar de nuevo\"\r\n              onPress={() => goRenew(expiredEnt[0])}\r\n              testID=\"billing-renew-expired\"\r\n            />\r\n          )}\r\n\r\n          {/* Derechos activos */}\r\n          <Text style={s.sectionTitle}>Derechos activos</Text>\r\n          {activeEnt.length === 0 ? (\r\n            /*\r\n              Vacío con salida (D-17) con el componente del kit. `ModulePlans` se queda DEBAJO\r\n              y fuera: el kit no tiene hueco para hijos sueltos, así que una acción con varias\r\n              opciones vive fuera. De paso, los textos pasan del 14/12 escritos a mano al 15/13,5\r\n              del kit — ese 12 rompía el suelo de 13 px de las pantallas de dinero (Fase 1).\r\n            */\r\n            <>\r\n              <EmptyState\r\n                icono={<Package size={40} color={colors.textSecondary} />}\r\n                titulo=\"Sin derechos activos\"\r\n                texto=\"Compra un plan para activar tus derechos (publicar, destacar, tienda…).\"\r\n              />\r\n              <ModulePlans />\r\n            </>\r\n          ) : (\r\n            activeEnt.map((e) => {\r\n              const mod = e.module || moduleOf(e.code);\r\n              return (\r\n                <View key={e.id} style={[s.entitleCard, { borderColor: brand.success, backgroundColor: alpha(brand.success, 0.06) }]}>\r\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\r\n                    <BadgeCheck size={16} color={brand.success} />\r\n                    <Text style={{ flex: 1, fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>\r\n                      {entitlementLabel(e.code, e.module)}\r\n                    </Text>\r\n                  </View>\r\n                  <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e4 }}>\r\n                    {MODULE_LABEL[mod] ?? 'Plan'}{e.expiresAt ? ` · vence el ${formatDate(e.expiresAt)}${e.daysLeft != null ? ` (${e.daysLeft} días)` : ''}` : ' · vigencia permanente'}\r\n                  </Text>\r\n                </View>\r\n              );\r\n            })\r\n          )}\r\n\r\n          {/* Órdenes */}\r\n          <Text style={[s.sectionTitle, { marginTop: espaciado.e20 }]}>Mis órdenes</Text>\r\n          {orders.length === 0 ? (\r\n            <EmptyState\r\n              compacto\r\n              icono={<Receipt size={26} color={colors.textSecondary} />}\r\n              titulo=\"Todavía no has comprado nada\"\r\n              texto=\"Aquí aparecerá cada compra de plan, con su estado y su reembolso si lo hubiera.\"\r\n            />\r\n          ) : (\r\n            orders.map((o) => {\r\n              const stKey = o.status === 'approved' && o.refundStatus === 'partially_refunded' ? 'refund_status_partial' : o.status;\r\n              const st = STATUS_LABELS[stKey] ?? { label: o.status, color: colors.textSecondary };\r\n              const mod = o.module || moduleOf(o.planCode);\r\n              const reason = o.status === 'cancelled' ? o.cancellationReason\r\n                : o.status === 'reversed' ? o.reversalReason\r\n                : o.status === 'refunded' ? 'Se aplicó un reembolso sobre esta orden.'\r\n                : null;\r\n              return (\r\n                <View key={o.id} style={[s.orderCard, { borderColor: colors.border }]}>\r\n                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e8 }}>\r\n                    <View style={{ flex: 1 }}>\r\n                      <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>{o.planName}</Text>\r\n                      <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>\r\n                        {MODULE_LABEL[mod] ?? ''} · {formatXAF(o.amountXaf)} · {new Date(o.createdAt).toLocaleDateString('es-GQ')}\r\n                      </Text>\r\n                    </View>\r\n                    <View style={{ paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4, borderRadius: 6, backgroundColor: alpha(st.color, 0.12) }}>\r\n                      <Text style={{ fontSize: 10.5, fontWeight: '700', color: st.color }}>{st.label}</Text>\r\n                    </View>\r\n                  </View>\r\n                  {o.status === 'rejected' && o.rejectionReason ? (\r\n                    <Text style={{ fontSize: tipografia.micro, color: brand.danger, fontWeight: '600', marginTop: espaciado.e8 }}>Motivo: {o.rejectionReason}</Text>\r\n                  ) : null}\r\n                  {reason ? (\r\n                    <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, fontWeight: '600', marginTop: espaciado.e8 }}>{reason}</Text>\r\n                  ) : null}\r\n                  {(o.status === 'pending_payment' || o.status === 'rejected') && (\r\n                    <View style={{ marginTop: espaciado.e10, gap: espaciado.e8 }}>\r\n                      <PrimaryButton\r\n                        title=\"Ir al pago / re-subir comprobante\"\r\n                        onPress={() => router.push({ pathname: '/billing-checkout', params: { orderId: o.id } } as any)}\r\n                      />\r\n                      {o.status === 'pending_payment' && (\r\n                        <Pressable\r\n                          onPress={() => cancelOrder(o.id)}\r\n                          disabled={!!cancellingOrderId}\r\n                          accessibilityRole=\"button\"\r\n                          accessibilityLabel=\"Cancelar orden\"\r\n                          testID={`billing-cancel-order-${o.id.slice(0, 8)}`}\r\n                          style={{ paddingVertical: espaciado.e10, alignItems: 'center', opacity: cancellingOrderId ? 0.6 : 1 }}\r\n                        >\r\n                          {cancellingOrderId === o.id ? (\r\n                            <ActivityIndicator size=\"small\" color={colors.danger} />\r\n                          ) : (\r\n                            <Text style={{ fontSize: tipografia.caption, color: colors.danger, fontWeight: '700' }}>Cancelar orden</Text>\r\n                          )}\r\n                        </Pressable>\r\n                      )}\r\n                    </View>\r\n                  )}\r\n                </View>\r\n              );\r\n            })\r\n          )}\r\n        </ScrollView>\r\n      )}\r\n      {/* Confirmación en HOJA (antes: modal del sistema) */}\r\n      <Sheet\r\n        visible={!!ordenACancelar}\r\n        title=\"¿Cancelar esta orden?\"\r\n        subtitle=\"Se cancelará la orden pendiente de pago. Si ya hiciste una transferencia, escríbenos para el reembolso.\"\r\n        busy={!!cancellingOrderId}\r\n        onClose={() => setOrdenACancelar(null)}\r\n      >\r\n        <PrimaryButton\r\n          title=\"Sí, cancelar\"\r\n          variant=\"danger\"\r\n          onPress={() => { if (ordenACancelar) void cancelarDeVerdad(ordenACancelar); }}\r\n        />\r\n        <GhostButton title=\"No, dejarla como está\" onPress={() => setOrdenACancelar(null)} />\r\n      </Sheet>\r\n\r\n      {/* Aviso que aparece y se va */}\r\n      <Aviso\r\n        visible={!!aviso}\r\n        mensaje={aviso ?? ''}\r\n        tono=\"exito\"\r\n        onOcultar={() => setAviso(null)}\r\n      />\r\n\r\n      {/* Reembolso: cuando se ha cancelado algo, el camino para pedirlo está a la vista */}\r\n      {aviso ? (\r\n        <View style={{ position: 'absolute', left: 24, right: 24, bottom: 104 }}>\r\n          <GhostButton\r\n            title=\"Pedir el reembolso por WhatsApp\"\r\n            onPress={() => { void whatsappSoporte('Hola, cancelé una orden y ya había pagado. Quiero el reembolso.'); }}\r\n          />\r\n        </View>\r\n      ) : null}\r\n    </View>\r\n\r\n  );\r\n}\r\n\r\n// ---------------------------------------------------------------------------\r\n// Componentes\r\n// ---------------------------------------------------------------------------\r\n\r\n/** Accesos rápidos a las pantallas de planes por módulo (vacíos y CTAs). */\r\nfunction ModulePlans() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  return (\r\n    <View style={{ flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', gap: espaciado.e8, marginTop: espaciado.e14 }}>\r\n      {Object.entries(MODULE_ROUTES).map(([mod, route]) => (\r\n        <Pressable\r\n          key={mod}\r\n          onPress={() => router.push(route as any)}\r\n          accessibilityRole=\"button\"\r\n          accessibilityLabel={`Ver planes de ${MODULE_LABEL[mod] ?? mod}`}\r\n          testID={`billing-plans-${mod}`}\r\n          style={({ pressed }) => [\r\n            s_card.planChip,\r\n            { backgroundColor: colors.surface, borderColor: colors.border, opacity: pressed ? 0.7 : 1 },\r\n          ]}\r\n        >\r\n          <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>{MODULE_LABEL[mod] ?? mod}</Text>\r\n        </Pressable>\r\n      ))}\r\n    </View>\r\n  );\r\n}\r\n\r\nfunction RenewCard({ tone, icon, title, body, cta, onPress, testID }: {\r\n  tone: 'warn' | 'danger' | 'neutral'; icon: React.ReactNode; title: string; body: string; cta: string; onPress: () => void; testID?: string;\r\n}) {\r\n  const { colors } = useTheme();\r\n  const border = tone === 'warn' ? brand.warning : tone === 'danger' ? brand.danger : colors.border;\r\n  const bg = tone === 'warn' ? alpha(brand.warning, 0.08) : tone === 'danger' ? alpha(brand.danger, 0.07) : colors.surface;\r\n  const titleColor = tone === 'warn' ? brand.warningText : tone === 'danger' ? brand.dangerText : colors.textPrimary;\r\n  const bodyColor = tone === 'danger' ? brand.dangerText : colors.textSecondary;\r\n  return (\r\n    <View style={[s_card.entitleCard, { borderColor: border, backgroundColor: bg, marginBottom: espaciado.e10 }]}>\r\n      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\r\n        {icon}\r\n        <Text style={{ flex: 1, fontSize: tipografia.body, fontWeight: '700', color: titleColor }}>{title}</Text>\r\n      </View>\r\n      <Text style={{ fontSize: tipografia.caption, color: bodyColor, marginTop: espaciado.e4 }}>{body}</Text>\r\n      <View style={{ marginTop: espaciado.e8 }}><PrimaryButton title={cta} onPress={onPress} testID={testID} /></View>\r\n    </View>\r\n  );\r\n}\r\n\r\nfunction SkeletonHeader({ colors }: { colors: ReturnType<typeof useTheme>['colors'] }) {\r\n  return (\r\n    <View style={{ height: 46, justifyContent: 'center', paddingHorizontal: espaciado.e16 }}>\r\n      <View style={{ height: 16, borderRadius: 4, backgroundColor: colors.border, width: '55%', alignSelf: 'center' }} />\r\n    </View>\r\n\r\n  );\r\n}\r\n\r\nconst s_card = StyleSheet.create({\r\n  entitleCard: { borderRadius: radios.md, padding: espaciado.e14, borderWidth: 1 },\r\n  planChip: { paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, borderRadius: 18, borderWidth: 1 },\r\n});\r\n\r\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\r\n  StyleSheet.create({\r\n    root: { flex: 1, backgroundColor: c.background },\r\n    sectionTitle: { fontSize: 15, fontWeight: '800', color: c.textPrimary, marginBottom: espaciado.e10 },\r\n    empty: { fontSize: tipografia.caption, color: c.textSecondary, textAlign: 'center', marginVertical: espaciado.e16 },\r\n    entitleCard: { borderRadius: radios.md, padding: espaciado.e14, borderWidth: 1, marginBottom: espaciado.e8 },\r\n    orderCard: { borderRadius: radios.md, padding: espaciado.e14, borderWidth: 1, marginBottom: espaciado.e10 },\r\n  });\r\n","/**\n * SOPORTE — el único sitio donde vive el contacto real.\n *\n * POR QUÉ EXISTE: la app remitía a «contacta soporte» en tres pantallas de dinero (reembolsos y\n * KYC) y en Ajustes los cuatro enlaces respondían «Próximamente». Es decir: prometía un canal que\n * no existía. Auditoría de diseño, D-37.\n *\n * REGLA: si mañana cambia el teléfono o el correo, se cambia AQUÍ y cambia en toda la app.\n * Nada de números repartidos por las pantallas.\n *\n * Datos facilitados por el dueño del producto (17/09/2026).\n */\nimport { Linking } from 'react-native';\n\nexport const SOPORTE = {\n  /** Correo de soporte. */\n  email: 'egrouteplan@gmail.com',\n  /** Teléfono de soporte, tal y como lo dio el dueño (incluye prefijo internacional). */\n  telefono: '+8615504426087',\n  /** El mismo número sin «+» ni espacios, que es lo que espera el enlace de WhatsApp. */\n  whatsapp: '8615504426087',\n} as const;\n\n/** Abre el correo con el asunto ya puesto. Devuelve false si el móvil no tiene ninguna app de correo. */\nexport async function escribirASoporte(asunto = 'Ayuda con EG Route Plan', cuerpo = ''): Promise<boolean> {\n  const url = `mailto:${SOPORTE.email}?subject=${encodeURIComponent(asunto)}${cuerpo ? `&body=${encodeURIComponent(cuerpo)}` : ''}`;\n  return abrir(url);\n}\n\n/** Abre WhatsApp con el número de soporte y el mensaje ya escrito. */\nexport async function whatsappSoporte(mensaje = 'Hola, necesito ayuda con EG Route Plan.'): Promise<boolean> {\n  const url = `https://wa.me/${SOPORTE.whatsapp}?text=${encodeURIComponent(mensaje)}`;\n  return abrir(url);\n}\n\n/** Llama al teléfono de soporte. */\nexport async function llamarASoporte(): Promise<boolean> {\n  return abrir(`tel:${SOPORTE.telefono}`);\n}\n\n/**\n * Abre un enlace EXTERNO sin poder tumbar la pantalla: si no hay app que lo atienda, se devuelve\n * false y quien llama decide qué decir. En una pantalla de dinero, un enlace roto no puede ser un\n * error silencioso.\n */\nasync function abrir(url: string): Promise<boolean> {\n  try {\n    await Linking.openURL(url);\n    return true;\n  } catch {\n    return false;\n  }\n}\n","/**\n * ERRORES EN LENGUA HUMANA — un solo sitio donde un código del servidor se convierte en una frase.\n *\n * POR QUÉ EXISTE (auditoría de diseño, D-16/D-42): las pantallas hacían `setError(e.message)`, así\n * que al usuario le llegaban cosas como «Error de red (ENOTFOUND): Network request failed» o\n * «DAILY_LIMIT_EXCEEDED». Un código no le dice a nadie qué hacer a continuación.\n *\n * REGLA: cada mensaje dice **qué pasó** y **qué puede hacer ahora**. Si un código no está en el mapa,\n * se limpia el ruido técnico y se ofrece una salida genérica honesta.\n */\nimport { ApiError } from '../api/auth';\n\n/** Mensajes por código. Los códigos son los que devuelve el backend. */\nconst POR_CODIGO: Record<string, string> = {\n  KYC_REQUIRED: 'Para mover dinero necesitas verificar tu identidad antes.',\n  PIN_INVALID: 'El PIN no es correcto. Vuelve a intentarlo.',\n  PIN_LOCKED: 'El PIN está bloqueado por intentos fallidos. Espera unos minutos o escríbenos.',\n  PIN_REQUIRED: 'Falta el PIN del monedero.',\n  AMOUNT_REQUIRED: 'Falta el importe.',\n  AMOUNT_MISMATCH: 'El importe cambió mientras pagabas. Vuelve a intentarlo.',\n  INSUFFICIENT_FUNDS: 'No tienes saldo suficiente en el monedero. Recarga y vuelve a intentarlo.',\n  DAILY_LIMIT_EXCEEDED: 'Has llegado al límite de hoy. Podrás seguir mañana o reducir el importe.',\n  LIMIT_EXCEEDED: 'Has llegado al límite permitido. Prueba con un importe menor.',\n  NOT_FOUND: 'Eso ya no existe: puede que lo hayan quitado o vendido.',\n  OUT_OF_STOCK: 'Se agotó mientras mirabas. Quita ese producto para seguir.',\n  CONFLICT: 'Alguien cambió esto a la vez que tú. Actualiza la pantalla y repite.',\n  TOO_MANY_REQUESTS: 'Demasiados intentos seguidos. Espera un minuto.',\n  UNAUTHORIZED: 'Tu sesión ha caducado. Vuelve a entrar.',\n  FORBIDDEN: 'Tu cuenta no tiene permiso para esto.',\n  VALIDATION_ERROR: 'Alguno de los datos no es válido. Revísalos y vuelve a intentarlo.',\n};\n\n/** Señales de que el problema está en la red del usuario, no en el servidor. */\nconst ES_RED = /ENOTFOUND|ECONNREFUSED|ETIMEDOUT|ECONNRESET|Network request failed|network|timeout|Failed to fetch/i;\n\nexport function mensajeDeError(e: unknown, alternativa = 'No se pudo completar la operación.'): string {\n  if (e instanceof ApiError) {\n    const codigo = String((e as { code?: string }).code ?? '');\n    if (codigo && POR_CODIGO[codigo]) return POR_CODIGO[codigo];\n    const texto = e.message ?? '';\n    if (ES_RED.test(texto)) return 'No hay conexión. Comprueba tus datos y vuelve a intentarlo.';\n    return limpiar(texto) || alternativa;\n  }\n  if (e instanceof Error) {\n    if (ES_RED.test(e.message)) return 'No hay conexión. Comprueba tus datos y vuelve a intentarlo.';\n    return limpiar(e.message) || alternativa;\n  }\n  if (typeof e === 'string' && e.trim()) return limpiar(e) || alternativa;\n  return alternativa;\n}\n\n/**\n * Quita el ruido técnico que no debe llegar a la pantalla: el código entre paréntesis y los sufijos\n * en inglés de las librerías («Network request failed»). Si al limpiar no queda nada, devuelve ''.\n */\nfunction limpiar(texto: string): string {\n  return texto\n    .replace(/\\(([A-Z_]{4,})\\)/g, '')\n    .replace(/\\bNetwork request failed\\b/gi, '')\n    .replace(/\\s{2,}/g, ' ')\n    .trim();\n}\n","/**\n * BuscarScreen — búsqueda estilo DiDi con geocoder local (calles/avenidas/POIs).\n *  · Input gigante con autofoco + resultados en vivo del geocoder.\n *  · Chips de atajos: 🏠 Casa · 💼 Trabajo · ✈️ Aeropuerto (guardados) ·\n *    📍 Mi ubicación · Ciudades.\n *  · Modo: ?mode=destino (por defecto) o ?mode=origen — la selección vuelve\n *    a Taxi vía geoPick (singleton) para fijar origen o destino.\n * Ruta: /buscar?city=Malabo&mode=destino\n */\n\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  FlatList, KeyboardAvoidingView, Platform, Pressable, StyleSheet, Text,\n  TextInput, View, ActivityIndicator, Alert,\n} from 'react-native';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowLeft, Briefcase, Home, MapPin, Navigation, Plane, Search, X,\n} from 'lucide-react-native';\nimport { CITIES, SERVICES, type City } from '../constants/data';\nimport { alpha } from '../constants/colors';\nimport { espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { geocode, type GeoPlace } from '../api/geocode';\nimport { setGeoPick } from '../state/geoPick';\nimport { brand } from '@egrouteplan/ui-kit';\n\ntype Suggestion =\n  | { kind: 'place'; place: GeoPlace }\n  | { kind: 'city'; city: City }\n  | { kind: 'service'; id: string; label: string; route: string; emoji?: string }\n  | { kind: 'origin'; label: string };\n\nconst SAVED_KEYS = {\n  casa: 'geo.saved.home',\n  trabajo: 'geo.saved.work',\n  aeropuerto: 'geo.saved.airport',\n} as const;\n\nconst norm = (s: string) =>\n  s.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, '');\n\nconst TITLE_CASE = (s: string) =>\n  s.replace(/\\b\\w/g, (ch) => ch.toUpperCase());\n\nconst KIND_LABEL: Record<string, string> = { road: 'Calle / avenida', poi: 'Lugar' };\n\ninterface SavedPlace { label: string; lat: number; lon: number; }\n\nexport default function BuscarScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { city: originCity, mode } = useLocalSearchParams<{ city?: string; mode?: string }>();\n  const isOriginMode = mode === 'origen';\n  const inputRef = useRef<TextInput>(null);\n  const [q, setQ] = useState('');\n  const [places, setPlaces] = useState<GeoPlace[]>([]);\n  const [searching, setSearching] = useState(false);\n  const [saved, setSaved] = useState<Partial<Record<keyof typeof SAVED_KEYS, SavedPlace>>>({});\n\n  // Cargar destinos guardados (casa/trabajo/aeropuerto).\n  useEffect(() => {\n    (async () => {\n      const out: typeof saved = {};\n      for (const key of Object.keys(SAVED_KEYS) as Array<keyof typeof SAVED_KEYS>) {\n        try {\n          const raw = await AsyncStorage.getItem(SAVED_KEYS[key]);\n          if (raw) out[key] = JSON.parse(raw);\n        } catch { /* ignore */ }\n      }\n      setSaved(out);\n    })();\n  }, []);\n\n  // Geocoder en vivo con debounce suave.\n  useEffect(() => {\n    const query = q.trim();\n    if (norm(query).length < 2) { setPlaces([]); setSearching(false); return; }\n    setSearching(true);\n    const t = setTimeout(async () => {\n      const r = await geocode(query);\n      setPlaces(r);\n      setSearching(false);\n    }, 300);\n    return () => clearTimeout(t);\n  }, [q]);\n\n  const pickPlace = (place: GeoPlace, saveKey?: keyof typeof SAVED_KEYS) => {\n    const label = TITLE_CASE(place.name);\n    const coord = [place.lon, place.lat] as [number, number];\n    if (saveKey) {\n      const sp: SavedPlace = { label, lat: place.lat, lon: place.lon };\n      AsyncStorage.setItem(SAVED_KEYS[saveKey], JSON.stringify(sp)).catch(() => {});\n      setSaved((prev) => ({ ...prev, [saveKey]: sp }));\n      Alert.alert('Guardado', `${label} guardado como ${saveKey === 'casa' ? 'Casa' : saveKey === 'trabajo' ? 'Trabajo' : 'Aeropuerto'}.`);\n      return;\n    }\n    // Vuelve a Taxi con el punto elegido (origen o destino).\n    setGeoPick({ mode: (isOriginMode ? 'origen' : 'destino') as never, coord, label, ts: Date.now() });\n    router.back();\n  };\n\n  const staticSuggestions = useMemo<Suggestion[]>(() => {\n    const out: Suggestion[] = [];\n    const query = norm(q.trim());\n    if (originCity) out.push({ kind: 'origin', label: originCity });\n    if (!query) {\n      for (const city of CITIES.slice(0, 5)) out.push({ kind: 'city', city });\n      return out;\n    }\n    const svc = SERVICES.find(\n      (s) => !s.comingSoon && (norm(s.label).includes(query) || query.includes(norm(s.label))),\n    );\n    if (svc) out.push({ kind: 'service', id: svc.id, label: svc.label, route: svc.route });\n    for (const city of CITIES) {\n      if (norm(city.name).includes(query) || norm(city.region).includes(query)) {\n        out.push({ kind: 'city', city });\n        if (out.filter((o) => o.kind === 'city').length >= 8) break;\n      }\n    }\n    return out;\n  }, [q, originCity]);\n\n  const suggestions = useMemo<Suggestion[]>(() => {\n    const withPlaces: Suggestion[] = places.map((place) => ({ kind: 'place', place }));\n    return [...withPlaces, ...staticSuggestions];\n  }, [places, staticSuggestions]);\n\n  const goSaved = async (key: keyof typeof SAVED_KEYS) => {\n    const sp = saved[key];\n    if (!sp) {\n      // Sin guardado: busca un lugar típico y sugiere guardarlo.\n      const term = key === 'casa' ? 'residencial' : key === 'trabajo' ? 'empresa' : 'aeropuerto';\n      const r = await geocode(term);\n      if (r.length) {\n        Alert.alert(\n          `Elige tu ${key === 'casa' ? 'Casa' : key === 'trabajo' ? 'Trabajo' : 'Aeropuerto'}`,\n          `Usamos \"${TITLE_CASE(r[0].name)}\". Toca un resultado para guardarlo como ${key === 'casa' ? 'Casa' : key === 'trabajo' ? 'Trabajo' : 'Aeropuerto'}.`,\n          [{ text: 'OK' }],\n        );\n        setQ(r[0].name);\n        setPlaces(r);\n      }\n      return;\n    }\n    setGeoPick({ mode: key as never, coord: [sp.lon, sp.lat], label: sp.label, ts: Date.now() });\n    router.back();\n  };\n\n  const pick = (s: Suggestion) => {\n    if (s.kind === 'place') { pickPlace(s.place); return; }\n    if (s.kind === 'service') { router.push(s.route as never); return; }\n    if (s.kind === 'origin') {\n      setGeoPick({ mode: 'origen', coord: originCity ? [0, 0] : [0, 0], label: originCity ?? 'Mi ubicación', ts: Date.now() } as never);\n      router.push({ pathname: '/taxi', params: { city: originCity ?? 'Malabo' } } as never);\n      return;\n    }\n    router.push({ pathname: '/taxi', params: { city: s.city.name } } as never);\n  };\n\n  const renderRow = ({ item }: { item: Suggestion }) => {\n    const c = colors;\n    if (item.kind === 'place') {\n      return (\n        <Pressable\n          onPress={() => pick(item)}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`${isOriginMode ? 'Origen' : 'Destino'}: ${item.place.name}`}\n          style={({ pressed }) => [styles.row, { opacity: pressed ? 0.6 : 1 }]}\n        >\n          <View style={[styles.iconWrap, { backgroundColor: alpha(c.primary, 0.12) }]}>\n            <MapPin size={18} color={isOriginMode ? brand.success : brand.danger} />\n          </View>\n          <View style={styles.rowBody}>\n            <Text style={[styles.rowTitle, { color: c.textPrimary }]} numberOfLines={1}>\n              {TITLE_CASE(item.place.name)}\n            </Text>\n            <Text style={[styles.rowSub, { color: c.textSecondary }]}>\n              {KIND_LABEL[item.place.kind] ?? 'Lugar'} · {item.place.lat.toFixed(4)}, {item.place.lon.toFixed(4)}\n            </Text>\n          </View>\n        </Pressable>\n      );\n    }\n    if (item.kind === 'service') {\n      return (\n        <Pressable\n          onPress={() => pick(item)}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Ir a ${item.label}`}\n          style={({ pressed }) => [styles.row, { opacity: pressed ? 0.6 : 1 }]}\n        >\n          <View style={[styles.iconWrap, { backgroundColor: alpha(c.secondary, 0.12) }]}>\n            <Text style={{ fontSize: 18 }}>{item.emoji ?? '🔎'}</Text>\n          </View>\n          <View style={styles.rowBody}>\n            <Text style={[styles.rowTitle, { color: c.textPrimary }]} numberOfLines={1}>{item.label}</Text>\n            <Text style={[styles.rowSub, { color: c.textSecondary }]}>Abrir servicio</Text>\n          </View>\n        </Pressable>\n      );\n    }\n    if (item.kind === 'origin') {\n      return (\n        <Pressable\n          onPress={() => pick(item)}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Desde mi ubicación: ${item.label}`}\n          style={({ pressed }) => [styles.row, { opacity: pressed ? 0.6 : 1 }]}\n        >\n          <View style={[styles.iconWrap, { backgroundColor: alpha(c.primary, 0.12) }]}>\n            <MapPin size={18} color={brand.success} />\n          </View>\n          <View style={styles.rowBody}>\n            <Text style={[styles.rowTitle, { color: c.textPrimary }]} numberOfLines={1}>{item.label} · Ubicación actual</Text>\n            <Text style={[styles.rowSub, { color: c.textSecondary }]}>Salir desde aquí</Text>\n          </View>\n        </Pressable>\n      );\n    }\n    const city = item.city;\n    return (\n      <Pressable\n        onPress={() => pick(item)}\n        accessibilityRole=\"button\"\n        accessibilityLabel={`Ir a ${city.name}, ${city.region}`}\n        style={({ pressed }) => [styles.row, { opacity: pressed ? 0.6 : 1 }]}\n      >\n        <View style={[styles.iconWrap, { backgroundColor: alpha(c.primary, 0.1) }]}>\n          <Navigation size={18} color={c.primary} />\n        </View>\n        <View style={styles.rowBody}>\n          <Text style={[styles.rowTitle, { color: c.textPrimary }]} numberOfLines={1}>{city.name}</Text>\n          <Text style={[styles.rowSub, { color: c.textSecondary }]} numberOfLines={1}>{city.region}</Text>\n        </View>\n      </Pressable>\n    );\n  };\n\n  const shortcutBtn = (key: keyof typeof SAVED_KEYS, label: string, Icon: any, color: string) => (\n    <Pressable\n      key={key}\n      onPress={() => goSaved(key)}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`Atajo: ${label}`}\n      style={({ pressed }) => [styles.shortcut, { backgroundColor: colors.card, borderColor: colors.border, opacity: pressed ? 0.7 : 1 }]}\n    >\n      <View style={[styles.shortcutIcon, { backgroundColor: alpha(color, 0.14) }]}>\n        <Icon size={19} color={color} />\n      </View>\n      <Text style={[styles.shortcutLabel, { color: colors.textPrimary }]}>{label}</Text>\n    </Pressable>\n  );\n\n  return (\n    <KeyboardAvoidingView\n      style={[styles.root, { backgroundColor: colors.background }]}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      <View style={[styles.header, { paddingTop: insets.top + 8, backgroundColor: colors.background }]}>\n        <Pressable\n          onPress={() => router.back()}\n          hitSlop={10}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Volver\"\n          style={({ pressed }) => [styles.backBtn, { opacity: pressed ? 0.6 : 1 }]}\n        >\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <View style={[styles.searchBox, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n          <Search size={18} color={colors.textSecondary} />\n          <TextInput\n            ref={inputRef}\n            value={q}\n            onChangeText={setQ}\n            placeholder={isOriginMode ? '¿Dónde estás?' : originCity ? `¿A dónde vas en ${originCity}?` : '¿A dónde vas?'}\n            placeholderTextColor={colors.textSecondary}\n            style={[styles.input, { color: colors.textPrimary }]}\n            returnKeyType=\"search\"\n            autoFocus\n            autoCorrect={false}\n            accessibilityLabel=\"Buscar dirección\"\n          />\n          {searching ? (\n            <ActivityIndicator size=\"small\" color={colors.textSecondary} />\n          ) : q.length > 0 ? (\n            <Pressable onPress={() => setQ('')} hitSlop={10} accessibilityRole=\"button\" accessibilityLabel=\"Limpiar búsqueda\">\n              <X size={18} color={colors.textSecondary} />\n            </Pressable>\n          ) : null}\n        </View>\n      </View>\n\n      {/* Atajos rápidos (DiDi: casa/trabajo/aeropuerto con iconos) */}\n      <View style={[styles.shortcuts, { borderBottomColor: colors.border }]}>\n        {shortcutBtn('casa', saved.casa ? saved.casa.label.split(' ').slice(0, 2).join(' ') : 'Casa', Home, brand.success)}\n        {shortcutBtn('trabajo', saved.trabajo ? saved.trabajo.label.split(' ').slice(0, 2).join(' ') : 'Trabajo', Briefcase, brand.primary)}\n        {shortcutBtn('aeropuerto', 'Aeropuerto', Plane, brand.danger)}\n      </View>\n\n      <FlatList\n        data={suggestions}\n        keyExtractor={(s, i) => `${s.kind}-${i}`}\n        renderItem={renderRow}\n        keyboardShouldPersistTaps=\"handled\"\n        contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingBottom: insets.bottom + 24 }}\n        ListHeaderComponent={\n          <Text style={[styles.sectionTitle, { color: colors.textSecondary }]}>\n            {q.trim() ? 'Resultados' : 'Para ti'}\n          </Text>\n        }\n        ListEmptyComponent={\n          <Text style={{ textAlign: 'center', marginTop: 40, color: colors.textSecondary, fontSize: tipografia.body }}>\n            {searching ? 'Buscando…' : `Sin resultados para \"${q}\"`}\n          </Text>\n        }\n      />\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  header: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e8 },\n  backBtn: { padding: espaciado.e4 },\n  searchBox: {\n    flex: 1, flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e12, height: 48,\n  },\n  input: { flex: 1, fontSize: tipografia.subtitle, fontWeight: '600', paddingVertical: 0 },\n  shortcuts: { flexDirection: 'row', gap: espaciado.e10, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth },\n  shortcut: { flex: 1, flexDirection: 'row', alignItems: 'center', gap: espaciado.e7, borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e9 },\n  shortcutIcon: { width: 30, height: 30, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\n  shortcutLabel: { fontSize: tipografia.caption, fontWeight: '800', flexShrink: 1 },\n  sectionTitle: { fontSize: tipografia.caption, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: espaciado.e6, marginTop: espaciado.e8, marginLeft: espaciado.e4 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingVertical: espaciado.e10 },\n  iconWrap: { width: 42, height: 42, borderRadius: 14, alignItems: 'center', justifyContent: 'center' },\n  rowBody: { flex: 1 },\n  rowTitle: { fontSize: 15, fontWeight: '700' },\n  rowSub: { fontSize: tipografia.caption, marginTop: 1 },\n});\n","/**\n * Datos estáticos de la Home — servicios, promos, contactos de emergencia\n * y ciudades de Guinea Ecuatorial. Las rutas apuntan a PANTALLAS REALES;\n * los servicios sin producto aún se marcan `comingSoon` (celda deshabilitada\n * \"Próximamente\", nunca un stub).\n */\n\nimport type { LucideIcon } from 'lucide-react-native';\nimport {\n  CarTaxiFront, Car, Package, KeyRound, Truck, Siren, Briefcase, Users, Route, UserRound,\n  Utensils, ShoppingCart, Store, Wallet, BedDouble,\n} from 'lucide-react-native';\n\n// ---------------------------------------------------------------- Servicios\n\nexport type ServiceTone = 'service' | 'emergency';\n\nexport interface ServiceItem {\n  id: string;\n  label: string;\n  icon: LucideIcon;\n  tone: ServiceTone; // 'service' → naranja secundario · 'emergency' → rojo crítico\n  route: string;     // ruta real (emergencia abre modal, no ruta)\n  /** Sin producto aún: la celda se muestra deshabilitada (\"Próximamente\"). */\n  comingSoon?: boolean;\n}\n\nexport const SERVICES: ServiceItem[] = [\n  { id: 'taxi',      label: 'Llamar Taxi',     icon: CarTaxiFront, tone: 'service', route: '/taxi' },\n  { id: 'intercity', label: 'Ciudad a Ciudad', icon: Route,        tone: 'service', route: '/intercity' },\n  { id: 'conductor', label: 'Ser Conductor',   icon: UserRound,    tone: 'service', route: '/conductor-hub' },\n  { id: 'reservar',  label: 'Reservar Coche',  icon: Car,          tone: 'service', route: '/reserva' },\n  { id: 'monedero',  label: 'Monedero',        icon: Wallet,       tone: 'service', route: '/monedero' },\n  { id: 'food',      label: 'Comida Rápida',   icon: Utensils,     tone: 'service', route: '/food' },\n  { id: 'ecomerse',  label: 'Mercado',         icon: ShoppingCart, tone: 'service', route: '/ecomerse' },\n  /* «Mi tienda» es la puerta del COMERCIANTE, contigua a Mercado a propósito: son las dos caras del\n     mismo mercado y el vendedor no tiene que buscarla en un menú. Lleva a la zona (`/tienda`), que\n     es un modo aparte con barra propia — antes la venta era un desvío dentro de Mercado (ver\n     `constants/roles.ts`). El rótulo es el que la pantalla ya usa en su cabecera. */\n  { id: 'tienda',    label: 'Mi tienda',       icon: Store,        tone: 'service', route: '/tienda' },\n  { id: 'alquiler',  label: 'Buscar Alquiler', icon: KeyRound,     tone: 'service', route: '/alquiler' },\n  // Módulo hotelero: reservas por noches, con calendario de disponibilidad y pago\n  // parcial (señal ahora + resto al llegar).\n  { id: 'hotel',     label: 'Hoteles',         icon: BedDouble,    tone: 'service', route: '/lifebook-hotel' },\n  { id: 'work',      label: 'Buscar Work',     icon: Briefcase,    tone: 'service', route: '/work' },\n  { id: 'mudanza',   label: 'Mudanza',         icon: Truck,        tone: 'service', route: '/service/mudanza', comingSoon: true },\n  { id: 'paquete',   label: 'Enviar Paquete',  icon: Package,      tone: 'service', route: '/service/paquete', comingSoon: true },\n  { id: 'lifebook',  label: 'Life Book',       icon: Users,        tone: 'service', route: '/lifebook' },\n  { id: 'emergencia',label: 'Emergencia',      icon: Siren,        tone: 'emergency', route: '/emergencia' },\n];\n\n// ------------------------------------------------------------------ Promos\n\nexport interface Promo {\n  id: string;\n  title: string;\n  subtitle: string;\n  cta: string;\n  emoji: string;\n  /** Destino REAL del banner (nunca un stub). */\n  route: string;\n}\n\nexport const PROMOS: Promo[] = [\n  { id: 'comida',    title: 'Comida Rápida',            subtitle: 'Pide y recoge o recibe en casa', cta: 'Pedir ahora',  emoji: '🍔', route: '/food' },\n  { id: 'mercado',   title: 'Mercado',                  subtitle: 'Móviles, ropa y más de tu ciudad', cta: 'Ver ofertas', emoji: '🛍️', route: '/ecomerse' },\n  { id: 'trabajos',  title: 'Buscar Work',              subtitle: 'Nuevas vacantes esta semana',    cta: 'Postularme',  emoji: '💼', route: '/work' },\n  { id: 'alquileres', title: 'Buscar Alquiler',         subtitle: 'Casas y locales en tu ciudad',   cta: 'Explorar',    emoji: '🏠', route: '/alquiler' },\n];\n\n// -------------------------------------------------------------- Emergencia\n\nexport interface EmergencyContact {\n  id: string;\n  label: string;\n  number: string;   // marcación directa con Linking tel:\n  note: string;\n}\n\nexport const EMERGENCY_CONTACTS: EmergencyContact[] = [\n  { id: 'policia',  label: 'Policía Nacional',      number: '114', note: 'Emergencias de seguridad' },\n  { id: 'hospital', label: 'Hospital / Ambulancia', number: '116', note: 'Emergencias médicas' },\n];\n\n// ---------------------------------------------------------------- Ciudades\n\nexport interface City {\n  id: string;\n  name: string;\n  region: string;\n}\n\nexport const CITIES: City[] = [\n  // Bioko Norte\n  { id: 'malabo',  name: 'Malabo',   region: 'Bioko Norte' },\n  { id: 'rebola',  name: 'Rebola',   region: 'Bioko Norte' },\n  { id: 'baney',   name: 'Baney',    region: 'Bioko Norte' },\n  // Bioko Sur\n  { id: 'luba',    name: 'Luba',     region: 'Bioko Sur' },\n  { id: 'riaba',   name: 'Riaba',    region: 'Bioko Sur' },\n  // Annobón\n  { id: 'pale',    name: 'San Antonio de Palé', region: 'Annobón' },\n  // Litoral (Río Muni)\n  { id: 'bata',    name: 'Bata',     region: 'Litoral' },\n  { id: 'cogo',    name: 'Cogo',     region: 'Litoral' },\n  { id: 'mbini',   name: 'Mbini',    region: 'Litoral' },\n  { id: 'machinda', name: 'Machinda', region: 'Litoral' },\n  { id: 'bitica',  name: 'Bitica',   region: 'Litoral' },\n  { id: 'corisco', name: 'Corisco',  region: 'Litoral' },\n  // Kié-Ntem\n  { id: 'ebebia',  name: 'Ebebiyín', region: 'Kié-Ntem' },\n  { id: 'nsang',   name: 'Nsang',    region: 'Kié-Ntem' },\n  { id: 'micomeseng', name: 'Micomeseng', region: 'Kié-Ntem' },\n  // Centro Sur\n  { id: 'evinayong', name: 'Evinayong', region: 'Centro Sur' },\n  { id: 'niefang',   name: 'Niefang',   region: 'Centro Sur' },\n  { id: 'aconibe',   name: 'Aconibe',   region: 'Centro Sur' },\n  { id: 'acurenam',  name: 'Acurenam',  region: 'Centro Sur' },\n  // Wele-Nzas\n  { id: 'mongomo', name: 'Mongomo',  region: 'Wele-Nzas' },\n  { id: 'anisok',  name: 'Añisok',   region: 'Wele-Nzas' },\n  { id: 'nsok',    name: 'Nsok',     region: 'Wele-Nzas' },\n  { id: 'ayene',   name: 'Ayene',    region: 'Wele-Nzas' },\n  // Djibloho\n  { id: 'paz',     name: 'Ciudad de la Paz', region: 'Djibloho' },\n];\n\n/**\n * Región inicial del mapa — migrada a constants/geo.ts (formato [lon, lat]).\n * Ver MALABO_CENTER y MALABO_ZOOM en constants/geo.ts.\n */\n","/**\n * SHIM de compatibilidad — los tokens viven en @egrouteplan/ui-kit.\n * Este archivo solo re-exporta para no tocar los componentes existentes.\n * Código nuevo: importar directamente de '@egrouteplan/ui-kit'.\n */\nexport {\n  tipografia,\n  peso,\n  espaciado,\n  radios,\n  brand,\n  lightColors,\n  darkColors,\n  alpha,\n  elevation,\n  elevationDark,\n  type ThemeColors,\n  type ElevationStyle,\n} from '@egrouteplan/ui-kit';\n","/**\n * Cliente del geocoder local (calles/avenidas/POIs de OSM, mirror HK).\n * Endpoints servidos por el mbtiles-server :8081 vía nginx /maps/tiles/:\n *   · /geocode?q=...   — búsqueda por nombre\n *   · /reverse?lon=&lat= — nombre del punto al tocar/arrastrar el mapa\n */\n\nimport { API_HOST } from './config';\n\nexport interface GeoPlace {\n  name: string;\n  kind: string;\n  lon: number;\n  lat: number;\n}\n\nexport interface ReversePlace extends GeoPlace {\n  distanceM: number;\n}\n\nexport const GEOCODE_URL = `${API_HOST}/maps/tiles/geocode`;\nexport const REVERSE_URL = `${API_HOST}/maps/tiles/reverse`;\n\nexport async function geocode(q: string): Promise<GeoPlace[]> {\n  const query = q.trim().toLowerCase();\n  if (query.length < 2) return [];\n  try {\n    const res = await fetch(`${GEOCODE_URL}?q=${encodeURIComponent(query)}`);\n    if (!res.ok) return [];\n    const data = await res.json();\n    return (data?.results ?? []) as GeoPlace[];\n  } catch {\n    return [];\n  }\n}\n\n/** Nombre real del lugar en (lon,lat) — p. ej. al fijar destino tocando el mapa. */\nexport async function reverseGeocode(lon: number, lat: number): Promise<ReversePlace[]> {\n  if (!Number.isFinite(lon) || !Number.isFinite(lat)) return [];\n  try {\n    const res = await fetch(`${REVERSE_URL}?lon=${lon.toFixed(6)}&lat=${lat.toFixed(6)}`);\n    if (!res.ok) return [];\n    const data = await res.json();\n    return (data?.results ?? []) as ReversePlace[];\n  } catch {\n    return [];\n  }\n}\n\n/** Kinds de calle: si el punto está en una vía, su nombre es la \"dirección\". */\nconst ROAD_KINDS = new Set([\n  'road', 'residential', 'primary', 'secondary', 'tertiary', 'motorway', 'trunk',\n  'unclassified', 'service', 'living_street', 'pedestrian', 'path', 'steps',\n]);\n\n/**\n * Elige la mejor etiqueta para un punto del mapa: prefiere la calle más\n * cercana (< 600 m) y, si no hay, el POI/lugar más cercano.\n */\nexport function pickReverseLabel(results: ReversePlace[]): string | null {\n  if (!results || results.length === 0) return null;\n  const road = results.find((r) => ROAD_KINDS.has(r.kind) && r.distanceM <= 600);\n  if (road) return road.name;\n  const near = results.find((r) => r.distanceM <= 600);\n  if (near) return near.name;\n  return results[0]?.name ?? null;\n}\n","/**\n * geoPick — selección compartida de un punto origen/destino entre Buscar y Taxi.\n * (expo-router no permite callbacks fáciles en params de vuelta; un singleton\n * efímero es suficiente: Buscar escribe, Taxi lee al recuperar el foco.)\n */\nimport { Coord } from '../packages/map';\n\nexport type GeoPickMode = 'origen' | 'destino' | 'casa' | 'trabajo' | 'aeropuerto';\n\nexport interface GeoPickValue {\n  mode: GeoPickMode;\n  coord: Coord;\n  label: string;\n  ts: number;\n}\n\nlet current: GeoPickValue | null = null;\n\nexport function setGeoPick(v: GeoPickValue) {\n  current = v;\n}\n\nexport function takeGeoPick(): GeoPickValue | null {\n  const v = current;\n  current = null;\n  return v;\n}\n","/**\n * ConductorHubScreen — \"Ser Conductor\": hub del conductor (EG Route Plan).\n * Tras completar el alta (documentos + aprobación), aquí elige qué función\n * desempeñará hoy. La elección se guarda como modo del día en el backend\n * (work-mode: city / intercity), que decide qué solicitudes recibe.\n *\n *  · 🚕 Taxi urbano       → modo 'city'      → /conductor (panel en línea)\n *  · 🚌 Ciudad a Ciudad   → modo 'intercity' → /intercity-publish\n *  · 🚚 Mudanza           → próximamente (sin producto aún, nunca stub)\n *\n * Ruta: /conductor-hub\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Bus, CarTaxiFront, ChevronRight, Circle, ShieldCheck, Truck } from 'lucide-react-native';\nimport { alpha, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useSession } from '../state/session';\nimport { driverApi } from '../api/driver';\nimport { brand } from '@egrouteplan/ui-kit';\n\ntype DriverStatus = 'none' | 'pending' | 'approved' | 'rejected' | 'checking';\n\n/** Pasos del alta (checklist estilo Uber Driver, ref-uber-driver.png). */\nconst ONBOARD_STEPS: Array<{ label: string; hint: string }> = [\n  { label: 'Crea tu perfil', hint: 'Datos personales y contacto' },\n  { label: 'Sube tu licencia', hint: 'Carné de conducir vigente' },\n  { label: 'Verifica tu identidad', hint: 'DIP y selfie (KYC)' },\n  { label: 'Registra tu vehículo', hint: 'Tipo, modelo y matrícula' },\n  { label: 'Espera la aprobación', hint: 'Revisión del administrador' },\n];\n\nexport default function ConductorHubScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const { isAuthenticated } = useSession();\n\n  const [status, setStatus] = useState<DriverStatus>('checking');\n  const [mode, setMode] = useState<'city' | 'intercity' | 'both' | null>(null);\n  const [vehicle, setVehicle] = useState<string>('');\n  const [busy, setBusy] = useState(false);\n\n  useEffect(() => {\n    if (!isAuthenticated) { setStatus('none'); return; }\n    let alive = true;\n    driverApi\n      .status()\n      .then((st) => {\n        if (!alive) return;\n        setStatus(st.status === 'none' && st.driver ? 'pending' : (st.status as DriverStatus));\n        if (st.driver) {\n          setMode((st.driver.work_mode as 'city' | 'intercity' | 'both') ?? null);\n          const parts = [st.driver.vehicle_type, st.driver.vehicle_model, st.driver.vehicle_plate].filter(Boolean);\n          setVehicle(parts.join(' · '));\n        }\n      })\n      .catch(() => alive && setStatus('none'));\n    return () => { alive = false; };\n  }, [isAuthenticated]);\n\n  /** Elige la función del día: guarda el modo y navega a su pantalla. */\n  const choose = useCallback(async (m: 'city' | 'intercity', route: string) => {\n    if (busy) return;\n    setBusy(true);\n    try { await driverApi.setWorkMode(m); } catch { /* offline: se navega igual, el modo se ajusta luego */ }\n    router.push(route as any);\n  }, [busy, router]);\n\n  const s = styles(colors);\n\n  const goAuth = () => router.push('/auth' as any);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      {/* Cabecera */}\n      <View style={s.topBar}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.title}>Ser Conductor</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      {!isAuthenticated || status === 'none' || status === 'checking' ? (\n        <ScrollView contentContainerStyle={[s.onboard, { paddingTop: insets.top + 16, paddingBottom: insets.bottom + 20 }]} showsVerticalScrollIndicator={false}>\n          {status === 'checking' && isAuthenticated ? (\n            <View style={s.center}>\n              <ActivityIndicator size=\"large\" color={colors.primary} />\n            </View>\n          ) : (\n            <>\n              {/* Bienvenida estilo Uber Driver (ref-uber-driver.png) */}\n              <View style={[s.welcomeCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                <View style={[s.statusIcon, { backgroundColor: alpha(colors.primary, 0.14) }]}>\n                  <CarTaxiFront size={26} color={colors.primary} />\n                </View>\n                <Text style={[s.welcomeTitle, { color: colors.textPrimary }]}>\n                  {isAuthenticated ? 'Te damos la bienvenida, conductor' : 'Zona del conductor'}\n                </Text>\n                <Text style={[s.welcomeSub, { color: colors.textSecondary }]}>\n                  Completa los pasos para comenzar a generar ganancias.\n                </Text>\n              </View>\n\n              {/* Checklist de onboarding */}\n              <View style={[s.checklistCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                <View style={[s.checklistHeader, { borderBottomColor: colors.border }]}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>Alta de conductor</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                    {isAuthenticated ? '0 de 5 completados' : 'Inicia sesión para empezar'}\n                  </Text>\n                </View>\n                {ONBOARD_STEPS.map((stp, i) => (\n                  <View key={stp.label} style={[s.checkRow, { borderBottomColor: colors.border }]}>\n                    <Circle size={18} color={colors.textSecondary} strokeWidth={2} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>{stp.label}</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>{stp.hint}</Text>\n                    </View>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '800' }}>Paso {i + 1}</Text>\n                  </View>\n                ))}\n              </View>\n\n              <GhostButton\n                title={isAuthenticated ? 'Empezar mi alta · crear perfil y documentos' : 'Iniciar sesión'}\n                onPress={() => (isAuthenticated ? router.push('/driver-onboarding' as any) : goAuth())}\n              />\n              <Text style={{ textAlign: 'center', color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e4 }}>\n                Aprobación por el administrador · Licencia, DIP y selfie\n              </Text>\n            </>\n          )}\n        </ScrollView>\n      ) : status === 'pending' ? (\n        <View style={s.center}>\n          <ShieldCheck size={42} color={colors.secondary} />\n          <Text style={[s.big, { color: colors.textPrimary }]}>Documentos en revisión</Text>\n          <Text style={[s.body, { color: colors.textSecondary }]}>\n            El administrador está revisando tu alta. Te avisaremos en cuanto estés aprobado para empezar a recibir funciones.\n          </Text>\n          <GhostButton title=\"Ver mi alta\" onPress={() => router.push('/driver-onboarding' as any)} />\n        </View>\n      ) : status === 'rejected' ? (\n        <View style={s.center}>\n          <ShieldCheck size={42} color={colors.danger} />\n          <Text style={[s.big, { color: colors.danger }]}>Alta rechazada</Text>\n          <Text style={[s.body, { color: colors.textSecondary }]}>\n            Algunos documentos no fueron aceptados. Revisa tu alta y vuelve a enviarlos.\n          </Text>\n          <GhostButton title=\"Revisar mi alta\" onPress={() => router.push('/driver-onboarding' as any)} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={[s.content, { paddingTop: insets.top + 20, paddingBottom: insets.bottom + 20 }]} showsVerticalScrollIndicator={false}>\n          {/* Estado del conductor */}\n          <View style={[s.statusCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <View style={[s.statusIcon, { backgroundColor: alpha(colors.success, 0.15) }]}>\n              <ShieldCheck size={20} color={colors.success} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.success, fontWeight: '900', fontSize: tipografia.body }}>Conductor aprobado</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e2 }}>\n                {vehicle || 'Vehículo no registrado'} · Modo actual: {mode === 'intercity' ? 'Ciudad a Ciudad' : mode === 'city' ? 'Taxi urbano' : 'Ambos'}\n              </Text>\n            </View>\n          </View>\n\n          <Text style={[s.question, { color: colors.textPrimary }]}>¿Qué vas a hacer hoy?</Text>\n          <Text style={[s.sub, { color: colors.textSecondary }]}>\n            Elige tu función. Lo recordamos como tu modo del día: en Taxi urbano recibirás solicitudes de ciudad; en Ciudad a Ciudad no.\n          </Text>\n\n          {/* 🚕 Taxi urbano */}\n          <Pressable\n            onPress={() => choose('city', '/conductor')}\n            disabled={busy}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Taxi urbano: salir en línea y aceptar carreras de ciudad\"\n            style={({ pressed }) => [s.opt, { backgroundColor: colors.card, borderColor: colors.border, opacity: busy ? 0.6 : pressed ? 0.85 : 1 }]}\n          >\n            <View style={[s.optIcon, { backgroundColor: alpha(brand.success, 0.14) }]}>\n              <CarTaxiFront size={24} color={brand.success} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>Taxi urbano</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 16 }}>\n                Sal en línea, recibe solicitudes en la ciudad y gestiona tus carreras.\n              </Text>\n            </View>\n            <ChevronRight size={18} color={colors.textSecondary} />\n          </Pressable>\n\n          {/* 🚌 Ciudad a Ciudad */}\n          <Pressable\n            onPress={() => choose('intercity', '/intercity-publish')}\n            disabled={busy}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Ciudad a Ciudad: publicar y gestionar viajes interurbanos\"\n            style={({ pressed }) => [s.opt, { backgroundColor: colors.card, borderColor: colors.border, opacity: busy ? 0.6 : pressed ? 0.85 : 1 }]}\n          >\n            <View style={[s.optIcon, { backgroundColor: alpha(brand.primary, 0.14) }]}>\n              <Bus size={24} color={brand.primary} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>Ciudad a Ciudad</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 16 }}>\n                Publica viajes interurbanos (Malabo ↔ Bata, etc.), reservas y cobros.\n              </Text>\n            </View>\n            <ChevronRight size={18} color={colors.textSecondary} />\n          </Pressable>\n\n          {/* 🚚 Mudanza (próximamente, sin stub) */}\n          <View style={[s.opt, { backgroundColor: colors.card, borderColor: colors.border, opacity: 0.55 }]}>\n            <View style={[s.optIcon, { backgroundColor: alpha(colors.textSecondary, 0.12) }]}>\n              <Truck size={24} color={colors.textSecondary} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>Mudanza</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 16 }}>\n                Traslados de carga y mudanzas. Llegará pronto a tu zona.\n              </Text>\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: 9, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.4 }}>\n              Próximamente\n            </Text>\n          </View>\n\n          <GhostButton title=\"Perfil del conductor · ganancias y documentos\" onPress={() => router.push('/driver-profile' as any)} />\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e6 },\n    title: { fontSize: 18, fontWeight: '800', color: c.textPrimary },\n    center: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e28, gap: espaciado.e12 },\n    big: { fontSize: tipografia.title, fontWeight: '900', textAlign: 'center' },\n    body: { fontSize: tipografia.body, lineHeight: 20, textAlign: 'center', fontWeight: '600' },\n    content: { padding: espaciado.e20, gap: espaciado.e12 },\n    statusCard: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderRadius: radios.lg, borderWidth: 1.5, padding: espaciado.e14 },\n    statusIcon: { width: 40, height: 40, borderRadius: 20, alignItems: 'center', justifyContent: 'center' },\n    question: { fontSize: 17, fontWeight: '900', marginTop: espaciado.e8 },\n    sub: { fontSize: tipografia.caption, lineHeight: 18, fontWeight: '600', marginTop: -6 },\n    opt: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e14, borderRadius: 18, borderWidth: 1.5, padding: espaciado.e16 },\n    optIcon: { width: 52, height: 52, borderRadius: radios.lg, alignItems: 'center', justifyContent: 'center' },\n    // Checklist onboarding (estilo Uber Driver)\n    onboard: { padding: espaciado.e16, gap: espaciado.e12, flexGrow: 1 },\n    welcomeCard: { alignItems: 'center', borderRadius: 18, borderWidth: 1, padding: espaciado.e20, gap: espaciado.e6 },\n    welcomeTitle: { fontSize: 19, fontWeight: '900', textAlign: 'center', marginTop: espaciado.e6 },\n    welcomeSub: { fontSize: tipografia.body, color: c.textSecondary, textAlign: 'center', lineHeight: 18, fontWeight: '600' },\n    checklistCard: { borderRadius: 18, borderWidth: 1, paddingHorizontal: espaciado.e16, overflow: 'hidden' },\n    checklistHeader: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: espaciado.e12, borderBottomWidth: 1 },\n    checkRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth },\n  });\n","/**\n * Cliente de alta de conductor (backend unificado /wallet/api/v1/mobility).\n * Documentos (licencia f/r + DIP + selfie), vehículo y re-verificación online.\n */\n\nimport { http } from './httpClient';\n\nexport interface DriverStatus {\n  status: 'none' | 'pending' | 'approved' | 'rejected';\n  verified?: boolean;\n  driver?: {\n    id: string;\n    vehicle_type?: string;\n    vehicle_plate?: string;\n    vehicle_model?: string;\n    vehicle_color?: string;          // P1a: color del coche\n    vehicle_photo_url?: string | null; // P1a: foto real del coche (URL interna)\n    status?: string;\n    resting?: boolean;              // DESCANSO: activo pero sin solicitudes\n    cash_blocked_at?: string | null; // cobro sin confirmar (P4)\n    cash_blocked_trip?: string | null;\n    work_mode?: string;\n    nationality?: string;\n  };\n}\n\nexport interface DocRequirementApi {\n  code: string;\n  label: string;\n  isRequired: boolean;\n  photos: 1 | 2;\n  note: string | null;\n  hasExpiry: boolean;\n  submitted: boolean;\n  frontUrl: string | null;\n  backUrl: string | null;\n  expiresAt: string | null;\n  status: string;\n}\n\nexport interface DocExpiry {\n  docType: string;\n  label: string;\n  expiresAt: string;\n  daysLeft: number;\n  status: 'expired' | 'expiring' | 'ok';\n}\n\nexport interface DocCategoryApi {\n  code: string;\n  title: string;\n  docs: DocRequirementApi[];\n}\n\nexport interface DriverDocProgress {\n  categories: DocCategoryApi[];\n  vehicle: {\n    vehicle_type?: string; vehicle_plate?: string; vehicle_model?: string; license_number?: string;\n    vehicle_color?: string; vehicle_photo_url?: string | null; // P1a\n  } | null;\n}\n\nexport const driverApi = {\n  /** Estado del perfil de conductor. */\n  status: () => http.get<DriverStatus>('/mobility/driver/status', true),\n\n  /** Envía documentos + vehículo → queda PENDING (revisión admin). */\n  submitDocuments: (body: {\n    licenseFront: string; licenseBack: string; dipFront: string; selfie: string;\n    licenseNumber?: string; vehicleType?: string; vehiclePlate?: string; vehicleModel?: string;\n  }) => http.post<{ status: string; message: string }>('/mobility/driver/documents', body, true),\n\n  /** Catálogo de requisitos + progreso del alta (wizard). */\n  requirements: () => http.get<DriverDocProgress>('/mobility/driver/documents/requirements', true),\n\n  /** Guarda un paso del alta (una categoría de documentos; 'vehiculo' incluye datos del vehículo). */\n  submitStep: (body: {\n    category: string;\n    nationality?: string;\n    vehicle?: {\n      vehicleType?: string; vehiclePlate?: string; vehicleModel?: string; licenseNumber?: string;\n      vehicleColor?: string;        // P1a: color del coche\n      vehiclePhoto?: string;        // P1a: foto real (dataURL/captured://)\n    };\n    docs: Array<{ code: string; front?: string; back?: string; expiresAt?: string }>;\n  }) => http.post<{ status: string; message: string }>('/mobility/driver/documents/step', body, true),\n\n  /** Avisos de caducidad de documentos (expired / próxima a caducar). */\n  expiries: () => http.get<{ expiries: DocExpiry[] }>('/mobility/driver/documents/expiries', true),\n\n  /** Modo de trabajo del día: 'city' | 'intercity' | 'both'. */\n  setWorkMode: (mode: 'city' | 'intercity' | 'both') =>\n    http.put<{ workMode: string; message: string }>('/mobility/driver/work-mode', { mode }, true),\n\n  /** Selfie de identidad (paso final del alta). */\n  submitSelfie: (selfie: string) =>\n    http.post<{ status: string; message: string }>('/mobility/driver/documents/selfie', { selfie }, true),\n\n  /** Re-verificación de identidad (selfie) para ponerse en línea. */\n  goOnline: (selfie: string) =>\n    http.post<{ online: boolean; message: string }>('/mobility/driver/online', { selfie }, true),\n\n  /** DESCANSO (decisión del dueño): estado propio 'resting' en backend; volver\n   *  a trabajar es UN TOQUE sin selfie (rest=false). */\n  setRest: (rest: boolean) =>\n    http.post<{ resting: boolean; status: string; message: string }>('/mobility/driver/rest', { rest }, true),\n};\n","/**\n * ConductorScreen — pantalla principal del conductor (Uber Driver · EG Route Plan).\n * Estado A: oferta entrante (15 s, badge modalidad, ganancia neta −10%,\n *           elegir precio, botón gigante aceptar).\n * Estado B: en ruta (panel pasajero + llamar/WhatsApp + terminar viaje).\n * Backend unificado: /wallet/api/v1/mobility/trips/driver + accept + status.\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { ActivityIndicator, Animated, Easing, Linking, Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { sayNavigation, stopAllVoice } from '../api/voice';\nimport {\n  ArrowLeft, BadgeCheck, Banknote, Box, Bus, Camera, CarFront, CheckCircle2, ChevronDown, ChevronUp, Compass, Flag, MessageCircle, Navigation, Phone, ShieldCheck, Star, Tag,\n  Users, User, UserRound, MapPin, Siren, Volume2, VolumeX, X,\n} from 'lucide-react-native';\nimport { alpha, altura, CameraCapture, elevation, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport EmergencyModal from '../components/EmergencyModal';\nimport DriverHomeSheet, { type HomeTab } from '../components/DriverHomeSheet';\nimport { EgMapView, EgCamera, EgMarkers, EgRoutePolyline, type EgMapViewHandle, type Coord } from '../packages/map';\nimport { taxiApi } from '../api/taxi';\nimport { settlementApi } from '../api/settlement';\nimport { driverApi } from '../api/driver';\nimport { getGqPositionIfAllowed } from '../api/locate';\nimport { isNightGq } from '../api/nightMode';\nimport { MALABO_CENTER } from '../constants/geo';\nimport { heatZonesNear } from '../constants/heatZones';\n\nimport { OSRM_BASE } from '../api/config';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst OSRM = OSRM_BASE;\nconst COMMISSION = 0.10; // 10% comisión de la app\nconst OFFER_SECONDS = 15;\n/** Velocidad de la SIMULACIÓN de avance cuando no hay GPS real (pruebas). */\nconst SIM_KMH = 45;\n\n/** Distancia aproximada en metros entre dos [lon,lat] (equirrectangular). */\nfunction distM(a: Coord, b: Coord): number {\n  const dLat = (b[1] - a[1]) * 111320;\n  const dLon = (b[0] - a[0]) * 111320 * Math.cos((a[1] * Math.PI) / 180);\n  return Math.sqrt(dLat * dLat + dLon * dLon);\n}\n\n/** Punto de la ruta a `meters` del inicio (interpolado entre vértices). */\nfunction pointAt(coords: Coord[], cum: number[], meters: number): Coord {\n  const total = cum[cum.length - 1];\n  let m = Math.max(0, Math.min(meters, total));\n  let i = 1;\n  while (i < cum.length - 1 && cum[i] < m) i++;\n  const segLen = cum[i] - cum[i - 1] || 1;\n  const f = (m - cum[i - 1]) / segLen;\n  const a = coords[i - 1];\n  const b = coords[i];\n  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];\n}\n\n/** Metros recorridos desde el inicio hasta el punto de la polilínea más\n *  cercano al vehículo (proyección sobre los vértices). */\nfunction alongAt(coords: Coord[], cum: number[], pt: Coord): number {\n  let best = 0;\n  let bestD = Infinity;\n  for (let i = 0; i < coords.length; i++) {\n    const d = distM(coords[i], pt);\n    if (d < bestD) { bestD = d; best = cum[i]; }\n  }\n  return best;\n}\n\n/** Rumbo (0=norte, 90=este) entre dos puntos, en grados. */\nfunction headingDeg(a: Coord, b: Coord): number {\n  const dLng = (b[0] - a[0]) * Math.cos((a[1] * Math.PI) / 180);\n  const dLat = b[1] - a[1];\n  if (Math.abs(dLng) < 1e-9 && Math.abs(dLat) < 1e-9) return NaN;\n  return (Math.atan2(dLng, dLat) * 180) / Math.PI;\n}\n\n/** Punto desplazado `meters` hacia adelante según el rumbo (grados, 0=norte).\n *  Con heading-up, centramos la cámara POR DELANTE del coche para que el\n *  coche quede en el tercio inferior de la pantalla (vista \"sumergida\", no\n *  aérea centrada). */\nfunction pointShift(p: Coord, heading: number, meters: number): Coord {\n  const r = (heading * Math.PI) / 180;\n  const dLat = (meters * Math.cos(r)) / 111320;\n  const dLng = (meters * Math.sin(r)) / (111320 * Math.cos((p[1] * Math.PI) / 180));\n  return [p[0] + dLng, p[1] + dLat];\n}\n\n/** Zoom de conducción \"sumergido\" según velocidad: en ciudad MUY cerca\n *  (16.4–17.0), solo en vía rápida/carretera se abre (14.2) para ver la salida.\n *  NUNCA se ve toda la ciudad: el conductor mira la calle, no el mapa. */\nfunction navZoomBySpeed(speedKmh: number): number {\n  if (speedKmh >= 75) return 14.2;\n  if (speedKmh >= 50) return 15.6;\n  if (speedKmh >= 25) return 16.4;\n  return 17.0;\n}\n\n/** Metros a los que colocamos el centro de la cámara POR DELANTE del coche\n *  (look-ahead) para que el coche quede en el TERCIO INFERIOR de la pantalla.\n *  Se ajusta en bucle cerrado con el cy que devuelve la página (ver navTick\n *  y onNavState): con pitch 60° un look-ahead fijo proyecta el coche fuera\n *  del borde inferior. */\nfunction navLookAheadMeters(zoom: number): number {\n  if (zoom >= 16.6) return 260;\n  if (zoom >= 16.3) return 300;\n  if (zoom >= 16.0) return 340;\n  if (zoom >= 15.5) return 420;\n  return 520;\n}\nfunction clampLookAhead(v: number): number {\n  return Math.min(900, Math.max(90, Math.round(v)));\n}\n\n/** Emoji/icono legible de la maniobra para el cajetín. */\nfunction turnGlyph(type: string, modifier: string): string {\n  const m = (modifier || '').toLowerCase();\n  const t = (type || '').toLowerCase();\n  if (t === 'depart' || t === 'arrive' || t === 'end of road') return t === 'depart' ? '🚗' : t === 'arrive' ? '🏁' : '↗️';\n  if (t === 'roundabout' || t === 'rotary' || t === 'exit roundabout') return '↻';\n  if (t === 'merge' || t === 'fork' || t === 'on ramp' || t === 'off ramp') return t.indexOf('ramp') > 0 ? '↗️' : '↔️';\n  if (m.indexOf('uturn') >= 0 || m.indexOf('u-turn') >= 0) return '🔃';\n  if (m === 'sharp left') return '↰';\n  if (m === 'sharp right') return '↱';\n  if (m === 'slight left' || m === 'left') return '⬅️';\n  if (m === 'slight right' || m === 'right') return '➡️';\n  if (m === 'straight' || t === 'new name' || t === 'continue') return '⬆️';\n  return '🔄';\n}\n\n/** Frase hablada en español para una maniobra (turn-by-turn).\n *  · distMeters >= 150 → frase LARGA con la distancia (\"En 300 metros…\").\n *  · distMeters < 150  → frase CORTA al acercarse (\"Gira a la izquierda…\").\n *  OJO (auditoría voz 2026-09-08): 'end of road' NO es \"llegar al destino\":\n *  es una maniobra normal (la vía acaba y hay que girar) → se guía por su\n *  modifier (izquierda/derecha). El destino real solo llega con type 'arrive',\n *  que se maneja aparte (según tramo: recogida vs destino). */\nfunction turnVoice(type: string, modifier: string, name: string, distMeters: number): string {\n  const m = (modifier || '').toLowerCase();\n  const t = (type || '').toLowerCase();\n  let action = '';\n  if (m.indexOf('uturn') >= 0) action = 'haz un cambio de sentido';\n  else if (m === 'sharp left' || m === 'left' || m === 'slight left') action = 'gira a la izquierda';\n  else if (m === 'sharp right' || m === 'right' || m === 'slight right') action = 'gira a la derecha';\n  else if (m === 'straight' || t === 'continue' || t === 'new name') action = 'continúa recto';\n  else if (t === 'end of road') {\n    action = m.indexOf('left') >= 0\n      ? 'gira a la izquierda al final de la vía'\n      : m.indexOf('right') >= 0\n        ? 'gira a la derecha al final de la vía'\n        : 'al final de la vía, gira';\n  }\n  else if (t === 'rotary' || t === 'roundabout' || t === 'exit roundabout') action = 'toma la rotonda';\n  else if (t.indexOf('ramp') >= 0) action = 'incorpórate a la vía';\n  else if (t === 'depart') action = 'comienza la ruta';\n  else action = 'sigue las indicaciones';\n  const street = (name || '').trim();\n  let sentence = '';\n  if (distMeters >= 150) sentence = `En ${Math.round(distMeters)} metros, ${action}`;\n  else sentence = action;\n  if (street) sentence += ` por ${street}`;\n  return sentence.charAt(0).toUpperCase() + sentence.slice(1);\n}\n\n/** PIN de confirmación (últimos 4 dígitos del teléfono del pasajero). */\nfunction pinLast4(p?: string | null): string {\n  const d = (p || '').replace(/\\D/g, '');\n  return d.length >= 4 ? d.slice(-4) : d.padStart(4, '0');\n}\n\ninterface Offer {\n  id: string;\n  pickup_lat: string; pickup_lng: string; pickup_address?: string;\n  dropoff_lat: string; dropoff_lng: string; dropoff_address?: string;\n  modality?: string;\n  requested_price?: string;\n  algorithm_price?: string;\n  final_price?: string;\n  // P1-c liquidación: qué se pactó y cuánto se cobra neto al cerrar.\n  city?: string | null;\n  settlement_kind?: string | null;\n  payment_locked_at?: string | null;\n  fee_info?: { fee?: number; scope?: string } | null;\n  arrived_at?: string | null;\n  status: string;\n  passenger_name?: string;\n  passenger_rating?: string;\n  passenger_phone?: string;\n  // P2: historial y confianza del pasajero + nº de asientos pedidos.\n  passenger_trips?: string | number | null;\n  passenger_trust?: string | number | null;\n  is_pool?: boolean;\n  max_pool_seats?: string | number | null;\n}\n\n/** Radar de búsqueda del conductor (rediseño): PIN central + ondas de radar y\n *  un barrido girando 360° a su alrededor. Compacto, translúcido, sobre el mapa. */\nfunction SearchSpin({ color }: { color: string }) {\n  const r = useRef(new Animated.Value(0)).current;\n  useEffect(() => {\n    const l = Animated.loop(Animated.timing(r, { toValue: 1, duration: 3200, easing: Easing.linear, useNativeDriver: true }));\n    l.start();\n    return () => l.stop();\n  }, [r]);\n  const spin = r.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '360deg'] });\n  const S = 84; // contenedor del barrido\n  return (\n    <View style={{ width: S, height: S, alignItems: 'center', justifyContent: 'center' }}>\n      {/* ondas de radar estáticas */}\n      <View style={{ position: 'absolute', width: S * 0.72, height: S * 0.72, borderRadius: S * 0.36, borderWidth: 1, borderColor: color + '59' }} />\n      <View style={{ position: 'absolute', width: S, height: S, borderRadius: S / 2, borderWidth: 1, borderColor: color + '2E' }} />\n      {/* barrido 360° (línea desde el centro hacia el borde, rotando) */}\n      <Animated.View style={{ position: 'absolute', width: S, height: S, transform: [{ rotate: spin }] }}>\n        <View style={{ position: 'absolute', left: S / 2, top: S / 2 - 1, width: S / 2, height: 2, backgroundColor: color, opacity: 0.85 }} />\n      </Animated.View>\n      {/* PIN central (la zona de búsqueda) */}\n      <View style={{ width: 34, height: 34, borderRadius: 17, backgroundColor: color, alignItems: 'center', justifyContent: 'center', elevation: 4 }}>\n        <MapPin size={17} color={brand.white} strokeWidth={2.6} />\n      </View>\n    </View>\n  );\n}\n\nexport default function ConductorScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const mapRef = useRef<EgMapViewHandle>(null);\n\n  const [offers, setOffers] = useState<Offer[]>([]);\n  const [current, setCurrent] = useState<Offer | null>(null); // oferta en pantalla\n  const [phase, setPhase] = useState<'waiting' | 'offer' | 'ruta'>('waiting');\n  const [chosenPrice, setChosenPrice] = useState<number | null>(null);\n  const [routeCoords, setRouteCoords] = useState<Coord[]>([]);\n  const [eta, setEta] = useState('—');\n  const [km, setKm] = useState('—');\n  // ── Navegación: posición del vehículo, progreso y seguimiento de cámara ──\n  const [vehiclePos, setVehiclePos] = useState<Coord | null>(null);\n  const [navKmLeft, setNavKmLeft] = useState<number | null>(null);\n  const [navMinLeft, setNavMinLeft] = useState<number | null>(null);\n  const [followNav, setFollowNav] = useState(true);\n  // Tarjetas compactas por defecto: el mapa debe seguir siendo protagonista.\n  const [cardExpanded, setCardExpanded] = useState(false);\n  const [leg, setLeg] = useState<'approach' | 'trip'>('approach');\n  const anchorRef = useRef<Coord>(MALABO_CENTER);\n  const tripPolyRef = useRef<Coord[]>([]);\n  // ── Vista de conducción ──\n  const [navSpeed, setNavSpeed] = useState(0);            // km/h\n  const [navDist, setNavDist] = useState<number>(0);      // metros hasta siguiente maniobra\n  const [navTurn, setNavTurn] = useState<{ name: string; dist: number; type: string; modifier: string } | null>(null);\n  const [navTurn2, setNavTurn2] = useState<{ name: string; dist: number; type: string; modifier: string } | null>(null);\n  const [navRoad, setNavRoad] = useState(''); // calle actual (\"Estás en …\")\n  const [headingUp, setHeadingUp] = useState(true);\n  // 2.5D AUTOMÁTICO al conducir (aprobado): pitch ~55 (más horizonte: se\n  // aprecian los carriles lejanos) + heading-up + zoom 16.0-16.5.\n  const [pitch3D, setPitch3D] = useState(true);\n  const NAV_PITCH = 55; // inclinación 2.5D (0 = cenital)\n  const [voiceOn, setVoiceOn] = useState(true);\n  const lastHeadingRef = useRef<number | undefined>(undefined);\n  const smoothHeadingRef = useRef<number | undefined>(undefined);\n  const lastCenterRef = useRef<Coord | null>(null);\n  const lastLocReportRef = useRef(0);\n  const lastCamSentRef = useRef(0);\n  const userZoomRef = useRef<number | undefined>(undefined);\n  const [navDbg, setNavDbg] = useState<{ bearing: number; pitch: number; zoom: number; cy?: number } | null>(null);\n  // Look-ahead ADAPTATIVO: la página reporta cy (posición vertical 0..1 donde\n  // proyecta el coche); con pitch 60° un valor fijo lo saca del borde inferior,\n  // así que se corrige en cada navstate para mantener el coche en el tercio\n  // inferior (cy objetivo ≈ 0.78–0.86).\n  const lookAheadRef = useRef<number>(navLookAheadMeters(16.2));\n  const stepsRef = useRef<Array<{ dist: number; name: string; type: string; modifier: string }>>([]);\n  // spokenRef: índice anunciado. spokenStage: 0=nada, 1=ya se anunció LEJOS\n  // (con distancia), 2=ya se anunció CERCA (\"gira ya\") → máximo 2 avisos por\n  // maniobra (patrón DiDi: \"gira en 300 m\" → \"gira a la izquierda\").\n  const spokenRef = useRef(-1);\n  const spokenStage = useRef<Record<number, number>>({});\n  const lastFixRef = useRef<{ p: Coord; t: number } | null>(null);\n  const cumRef = useRef<number[]>([]);\n  const totalRef = useRef(0);\n  const simTravRef = useRef(0);\n  const [error, setError] = useState<string | null>(null);\n  // Aviso NO-error (p. ej. \"El pasajero canceló el viaje\"): pill temporal.\n  const [rutaNotice, setRutaNotice] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [driverStatus, setDriverStatus] = useState<'none' | 'pending' | 'approved' | 'rejected' | 'checking'>('checking');\n  const [online, setOnline] = useState(false);\n  const [resting, setResting] = useState(false); // DESCANSO: sin solicitudes, sin selfie al volver\n  const [selfieOpen, setSelfieOpen] = useState(false);\n  const [selfieErr, setSelfieErr] = useState<string | null>(null);\n  const [emergencyOpen, setEmergencyOpen] = useState(false);\n  const [workMode, setWorkMode] = useState<'city' | 'intercity' | 'both'>('both');\n  const [expiryWarnings, setExpiryWarnings] = useState<string[]>([]);\n  // ── P4 EFECTIVO: bloqueo por cobro no confirmado al terminar el viaje ─────\n  const [cashOpen, setCashOpen] = useState(false);          // modal \"¿Recibiste el dinero?\"\n  const [blockedCash, setBlockedCash] = useState(false);    // cobro pendiente → sin solicitudes\n  const [blockedCashTrip, setBlockedCashTrip] = useState<string | null>(null);\n  const [fareTotal, setFareTotal] = useState(0);            // precio final aceptado (sello)\n  const [tripExpanded, setTripExpanded] = useState(false);  // tarjeta del viaje: \"Más\"\n  // ── P1 HOME conductor: bottom-sheet de 3 pestañas ─────────────────────────\n  const [homeOpen, setHomeOpen] = useState(false);\n  const [homeTab, setHomeTab] = useState<HomeTab>('flujo');\n  // ── P3 ZONAS CALIENTES (simulación visual) ────────────────────────────────\n  const [heatOn, setHeatOn] = useState(false);\n  // ── Código del pasajero en la RECOGIDA (validación de 4 dígitos) ─────────\n  const [pinOpen, setPinOpen] = useState(false);\n\n  /** Activa/desactiva las zonas calientes simuladas (círculos de demanda).\n   *  SOLO visual por ahora (decisión del dueño): sin datos reales aún. */\n  const toggleHeat = () => {\n    const nv = !heatOn;\n    setHeatOn(nv);\n    const base = anchorRef.current ?? MALABO_CENTER;\n    mapRef.current?.setHeatZones?.(nv ? heatZonesNear(base[0], base[1]) : []);\n  };\n\n  // Gate: primero el alta (cuenta + documentos) y luego la identidad al salir en línea.\n  useEffect(() => {\n    (async () => {\n      try {\n        const st = await driverApi.status();\n        setDriverStatus(st.status);\n        // En línea SOLO si status active y NO en descanso (resting es columna\n        // propia: status sigue 'active' por el CHECK de la tabla).\n        setOnline(!!st.driver && st.driver.status === 'active');\n        setResting(!!st.driver?.resting);\n        setWorkMode((st.driver?.work_mode as 'city' | 'intercity' | 'both') ?? 'both');\n        // P4: si hay un cobro sin confirmar en el servidor → bloqueado.\n        const blocked = !!(st.driver as any)?.cash_blocked_at;\n        setBlockedCash(blocked);\n        if (blocked) setBlockedCashTrip(((st.driver as any)?.cash_blocked_trip as string) ?? null);\n      } catch { setDriverStatus('none'); }\n      driverApi.expiries().then((r) => {\n        const warn = r.expiries\n          .filter((e) => e.status !== 'ok')\n          .map((e) => `${e.label}: ${e.status === 'expired' ? 'VENCIDO' : `caduca en ${e.daysLeft} días`}`);\n        setExpiryWarnings(warn);\n      }).catch(() => {});\n    })();\n  }, []);\n\n  // Countdown 15s (barra de progreso)\n  const countdown = useRef(new Animated.Value(1)).current;\n  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);\n\n  const startCountdown = useCallback(() => {\n    countdown.setValue(1);\n    Animated.timing(countdown, { toValue: 0, duration: OFFER_SECONDS * 1000, useNativeDriver: false }).start();\n    if (countdownRef.current) clearInterval(countdownRef.current);\n    // Al expirar → la oferta desaparece (queda en backend para otros conductores)\n    countdownRef.current = setInterval(() => {\n      setPhase('waiting');\n      setCurrent(null);\n      clearInterval(countdownRef.current!);\n    }, OFFER_SECONDS * 1000);\n  }, [countdown]);\n\n  // Polling de solicitudes\n  const load = useCallback(async () => {\n    if (workMode === 'intercity') return; // hoy no recibe solicitudes de ciudad\n    if (!online) {\n      // Desconectado: no procesar ofertas (solo estado \"No estás en línea\").\n      setPhase('waiting');\n      setCurrent(null);\n      setOffers([]);\n      return;\n    }\n    if (blockedCash) {\n      // P4: cobro sin confirmar → el servidor rechaza aceptar; no mostramos ofertas.\n      setPhase('waiting');\n      setCurrent(null);\n      setOffers([]);\n      return;\n    }\n    try {\n      const list = await taxiApi.driverTrips();\n      const trips = (Array.isArray(list) ? list : []) as Offer[];\n      setOffers(trips);\n      // CANCELACIÓN REMOTA (pasajero): si estamos en ruta con un viaje propio\n      // y el servidor ya lo marca 'cancelled' (el pasajero canceló desde su\n      // app), salimos de la ruta de inmediato con un aviso.\n      if (phase === 'ruta' && current) {\n        const own = trips.find((t) => t.id === current.id);\n        if (own && String(own.status) === 'cancelled') {\n          setPhase('waiting'); setCurrent(null); setRouteCoords([]);\n          setLeg('approach'); setVehiclePos(null); setTripExpanded(false); setFareTotal(0);\n          setRutaNotice('El pasajero canceló el viaje.');\n          return;\n        }\n        // P1-c: viaje con monedero BLOQUEADO mientras estamos en ruta (el\n        // pasajero confirma el precio con PIN tarde) → fusionamos los campos de\n        // liquidación para que el botón cambie a «He llegado» sin reiniciar nada.\n        if (own) {\n          const o = own as any; const c = current as any;\n          if (o.payment_locked_at !== c.payment_locked_at || o.arrived_at !== c.arrived_at\n            || o.settlement_kind !== c.settlement_kind || String(o.status) !== String(c.status)\n            || String(o.final_price ?? '') !== String(c.final_price ?? '')) {\n            setCurrent((prev) => (prev ? { ...prev,\n              status: o.status, payment_locked_at: o.payment_locked_at, arrived_at: o.arrived_at,\n              settlement_kind: o.settlement_kind, fee_info: o.fee_info, final_price: o.final_price } as Offer : prev));\n          }\n        }\n        // P1-c: viaje de monedero LIQUIDADO (el pasajero confirmó la llegada o\n        // cerró solo a los 10 min) → salir de la ruta anunciando el neto cobrado.\n        if (own && String(own.status) === 'completed') {\n          const bruto = Number((current as any).final_price ?? 0);\n          const comi = Number(((current as any).fee_info?.fee ?? (own as any).fee_info?.fee ?? 0));\n          setPhase('waiting'); setCurrent(null); setRouteCoords([]);\n          setLeg('approach'); setVehiclePos(null); setTripExpanded(false); setFareTotal(0);\n          setRutaNotice(comi > 0\n            ? `Viaje cerrado y liquidado: ${Math.max(0, bruto - comi).toLocaleString('es')} XAF netos (comisión ${comi.toLocaleString('es')} XAF).`\n            : 'Viaje cerrado: cobra en efectivo al pasajero.');\n          return;\n        }\n      }\n      // Estado A: oferta entrante (la más reciente 'requested')\n      if (phase !== 'ruta') {\n        const open = trips.find((t) => t.status === 'requested');\n        if (open && (!current || current.id !== open.id)) {\n          setCurrent(open);\n          setChosenPrice(Number(open.algorithm_price) ?? Number(open.requested_price) ?? null);\n          setPhase('offer');\n          startCountdown();\n          fetchRoute(open);\n        } else if (!open && phase === 'offer') {\n          setPhase('waiting');\n          setCurrent(null);\n        }\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Error de red');\n    }\n  }, [phase, current, startCountdown, workMode, online, blockedCash]);\n\n  useEffect(() => {\n    load();\n    const t = setInterval(load, 4000);\n    return () => { clearInterval(t); if (countdownRef.current) clearInterval(countdownRef.current); };\n  }, [load]);\n\n  // El aviso (p. ej. \"El pasajero canceló el viaje\") se auto-borra a los 6 s.\n  useEffect(() => {\n    if (!rutaNotice) return;\n    const t = setTimeout(() => setRutaNotice(null), 6000);\n    return () => clearTimeout(t);\n  }, [rutaNotice]);\n\n  // Ruta OSRM desde las coordenadas de la oferta\n  const fetchRoute = useCallback(async (o: Offer) => {\n    const from: Coord = [Number(o.pickup_lng), Number(o.pickup_lat)];\n    const to: Coord = [Number(o.dropoff_lng), Number(o.dropoff_lat)];\n    if (!from[0] || !to[0]) return;\n    try { mapRef.current?.fitBounds([from, to], { bottomFrac: 0.3 }); } catch { /* noop */ }\n    try {\n      const res = await fetch(`${OSRM}/driving/${from[0]},${from[1]};${to[0]},${to[1]}?overview=full&geometries=geojson`);\n      if (!res.ok) return;\n      const data = await res.json();\n      const route = data?.routes?.[0];\n      if (route) {\n        const coords = (route.geometry?.coordinates ?? []) as Coord[];\n        if (coords.length >= 2) {\n          tripPolyRef.current = coords; // ruta REAL del viaje: recogida → destino\n          setRouteCoords(coords);\n          setKm(`${Math.round((route.distance / 1000) * 10) / 10} km`);\n          setEta(`${Math.round(route.duration / 60)} min`);\n        }\n      }\n    } catch { /* sin ruta */ }\n  }, []);\n\n  // Longitudes acumuladas de la polilínea (para simular/proyectar avance).\n  useEffect(() => {\n    if (routeCoords.length < 2) { cumRef.current = []; totalRef.current = 0; return; }\n    const cum = [0];\n    let t = 0;\n    for (let i = 1; i < routeCoords.length; i++) {\n      t += distM(routeCoords[i - 1], routeCoords[i]);\n      cum.push(t);\n    }\n    cumRef.current = cum;\n    totalRef.current = t;\n  }, [routeCoords]);\n\n  const setNavFromRemaining = useCallback((remainingM: number) => {\n    const rem = Math.max(0, remainingM);\n    setNavKmLeft(rem / 1000);\n    setNavMinLeft(Math.max(1, Math.ceil((rem / 1000) / (SIM_KMH) * 60)));\n  }, []);\n\n  /** Un \"tick\" de la vista de conducción: velocidad, rumbo, cámara nav\n   *  (heading-up/2D-3D/zoom por velocidad), maniobra actual y voz. */\n  /** Zoom efectivo 2.5D: fijo 16.0–16.5 (perspectiva sumergida sin perder las\n   *  manzanas). Respeta el zoom del conductor solo dentro de ese rango. */\n  const camZoom = (): number => {\n    const uz = userZoomRef.current;\n    const z = uz != null ? uz : 16.2;\n    return Math.min(16.5, Math.max(16.0, z));\n  };\n\n  const navTick = useCallback((\n    pos: Coord,\n    travelledM: number,\n    dtMs: number,\n    stepM: number,\n    tangentHeading: number | undefined,\n  ) => {\n    // Velocidad (km/h): simulación usa SIM_KMH; GPS real por delta de tiempo.\n    let speed = SIM_KMH;\n    if (dtMs > 0 && stepM > 0) speed = (stepM / (dtMs / 1000)) * 3.6;\n    if (!Number.isFinite(speed) || speed <= 0) speed = 0;\n    setNavSpeed(Math.round(speed));\n\n    let heading = tangentHeading;\n    if (!Number.isFinite(heading ?? NaN) && lastFixRef.current) {\n      heading = headingDeg(lastFixRef.current.p, pos);\n    }\n    if (Number.isFinite(heading ?? NaN)) {\n      const target = heading as number;\n      lastHeadingRef.current = target;\n      // Suavizado de rumbo (sin giros bruscos): lerp por el camino más corto.\n      const prev = smoothHeadingRef.current;\n      if (prev == null) smoothHeadingRef.current = target;\n      else {\n        let d = ((target - prev) % 360 + 540) % 360 - 180;\n        smoothHeadingRef.current = (prev + d * 0.5 + 360) % 360;\n      }\n    }\n    lastCenterRef.current = pos;\n    lastFixRef.current = { p: pos, t: Date.now() };\n\n    if (followNav) {\n      // Resuelve el rumbo SIEMPRE (fallback al último conocido, nunca se salta\n      // el comando): así bearing/pitch llegan en cada tick.\n      const camHeading = headingUp ? (smoothHeadingRef.current ?? 0) : 0;\n      const zoom = camZoom();\n      // \"Sumergido\": en 3D heading-up la cámara mira por delante del coche,\n      // así el coche queda en el tercio inferior (como DiDi/Uber), no aéreo.\n      const fwd = pitch3D && headingUp ? pointShift(pos, camHeading, lookAheadRef.current) : pos;\n      // Envío de cámara cada ~700 ms (una sola easeTo canónica en la página):\n      // llamar a cada tick cancelaba las transiciones y dejaba el mapa plano.\n      const nowCam = Date.now();\n      if (nowCam - lastCamSentRef.current >= 700) {\n        lastCamSentRef.current = nowCam;\n        mapRef.current?.setNavView?.({\n          lng: fwd[0], lat: fwd[1], zoom,\n          bearing: camHeading,\n          pitch: pitch3D ? NAV_PITCH : 0,\n          durationMs: 700,\n          // Posición REAL del coche: la página la usa para reportar cy.\n          carLng: pos[0], carLat: pos[1],\n        });\n        // Línea de guía: ya no se dibuja nada encima del azul (2026-09-05 el\n        // dueño pidió CANCELAR la línea blanca de predicción: tapaba la ruta y\n        // \"borraba\" las flechas animadas). setGuide queda como no-op de limpieza.\n        mapRef.current?.setGuide?.([]);\n      }\n    }\n\n    // Maniobras (turn-by-turn) según los pasos OSRM y lo recorrido.\n    // AUDITORÍA VOZ 2026-09-08 (bug \"dice 'has llegado a tu destino' al\n    // empezar\"): la llegada SOLO se anuncia cuando quedan ≤60 m Y es el ÚLTIMO\n    // paso del tramo. Antes se anunciaba con d1≤420 en tramos cortos (rutas\n    // con 1-2 pasos: a los pocos metros ya hablaba \"llegaste\") y 'end of road'\n    // se trataba como llegada. Además el texto distingue tramo: a la RECOGIDA\n    // se dice \"punto de recogida\", al DESTINO se dice \"tu destino\".\n    const steps = stepsRef.current;\n    if (steps.length) {\n      let idx = -1;\n      for (let i = 0; i < steps.length; i++) {\n        if (steps[i].dist >= travelledM - 4) { idx = i; break; }\n      }\n      if (idx < 0) idx = steps.length - 1;\n      const cur = steps[idx];\n      if (cur) {\n        const d1 = Math.max(0, cur.dist - travelledM);\n        const isLast = idx === steps.length - 1;\n        setNavDist(d1);\n        setNavTurn({ name: cur.name, dist: d1, type: cur.type, modifier: cur.modifier });\n        const n2 = steps[idx + 1];\n        setNavTurn2(n2 ? { name: n2.name, dist: Math.max(0, n2.dist - travelledM), type: n2.type, modifier: n2.modifier } : null);\n        if (voiceOn) {\n          const speakable = cur.type === 'turn' || cur.type === 'roundabout' || cur.type === 'exit roundabout' || cur.type === 'merge' || cur.type === 'new name' || cur.type === 'end of road' || cur.type === 'arrive';\n          if (speakable && cur.type === 'arrive' && isLast && d1 <= Math.min(60, Math.max(14, totalRef.current * 0.2))) {\n            if ((spokenStage.current[idx] ?? 0) < 2) {\n              spokenStage.current[idx] = 2; spokenRef.current = idx;\n              sayEs(leg === 'approach' ? 'Has llegado al punto de recogida. Espera al pasajero.' : 'Has llegado a tu destino');\n            }\n          } else if (speakable && cur.type !== 'arrive') {\n            const stage = spokenStage.current[idx] ?? 0;\n            // Fase 1 (lejos, con distancia) y fase 2 (cerca, corta): DiDi no\n            // repite la distancia a 30 m; con \"gira ya\" es más natural.\n            if (stage === 0 && d1 <= 420) {\n              spokenStage.current[idx] = 1; spokenRef.current = idx;\n              sayEs(turnVoice(cur.type, cur.modifier, cur.name, d1));\n            } else if (stage === 1 && d1 <= 120) {\n              spokenStage.current[idx] = 2; spokenRef.current = idx;\n              sayEs(turnVoice(cur.type, cur.modifier, cur.name, 0)); // sin metros\n            }\n          }\n        }\n        // Calle actual (\"Estás en …\"): la del tramo en el que vamos antes del giro.\n        let road = '';\n        for (let j = idx - 1; j >= 0; j--) { if (steps[j].name) { road = steps[j].name; break; } }\n        if (!road && cur.name) road = cur.name;\n        setNavRoad(road);\n      }\n    }\n    // ETA con la velocidad real.\n    if (totalRef.current > 0 && speed > 6) {\n      const restM = Math.max(0, totalRef.current - travelledM);\n      setNavMinLeft(Math.max(1, Math.ceil((restM / 1000) / (speed / 60))));\n      setNavKmLeft(restM / 1000);\n    }\n  }, [headingUp, pitch3D, voiceOn, followNav, routeCoords, leg]);\n\n  // Carga los pasos OSRM (maniobras) del tramo activo para el turn-by-turn.\n  useEffect(() => {\n    if (phase !== 'ruta' || !current) return;\n    const pickup: Coord = [Number(current.pickup_lng), Number(current.pickup_lat)];\n    const dropoff: Coord = [Number(current.dropoff_lng), Number(current.dropoff_lat)];\n    const from = leg === 'approach' ? anchorRef.current : pickup;\n    const to = leg === 'approach' ? pickup : dropoff;\n    if (!from[0] || !to[0]) return;\n    spokenRef.current = -1;\n    spokenStage.current = {};\n    (async () => {\n      try {\n        const res = await fetch(`${OSRM}/driving/${from[0]},${from[1]};${to[0]},${to[1]}?overview=false&steps=true`);\n        const data = await res.json();\n        const steps = (data?.routes?.[0]?.legs ?? []).flatMap((lg: any) => lg.steps || []);\n        let run = 0;\n        const list: Array<{ dist: number; name: string; type: string; modifier: string }> = [];\n        for (const s of steps) {\n          list.push({ dist: run, name: s.name || '', type: s.maneuver?.type || '', modifier: s.maneuver?.modifier || '' });\n          run += s.distance || 0;\n        }\n        if (list.length) {\n          stepsRef.current = list;\n          // Anuncio de SALIDA del tramo (una vez por viaje+tramo, como DiDi):\n          // al ir a RECOGER → \"de camino al pasajero\"; con pasajero a bordo →\n          // \"de camino al destino\". Solo si la voz está activa.\n          if (voiceOn) {\n            try {\n              if (leg === 'approach') void sayEs('De camino a recoger al pasajero.');\n              else void sayEs('Pasajero recogido. De camino al destino.');\n            } catch { /* voz opcional */ }\n          }\n        }\n      } catch { /* sin instrucciones */ }\n    })();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [phase, current?.id, leg]);\n\n  // Cada fase/oferta empieza con la tarjeta COMPACTA (el mapa visible).\n  useEffect(() => { setCardExpanded(false); }, [phase, current?.id]);\n\n  // Detiene la voz si se sale del conductor.\n  useEffect(() => () => { stopAllVoice(); }, []);\n\n  // Nota: NO usamos getAvailableVoicesAsync(): en algunos motores TTS (p. ej.\n  // el de Oplus/ColorOS) ese método crashea la app (LanguageUtils). La voz\n  // PRINCIPAL es Qwen3 cloud (voz Cherry, proxy backend) con FALLBACK local\n  // es-ES si no hay red: sayNavigation nunca lanza y siempre habla algo.\n  const sayEs = useCallback((text: string) => { if (!voiceOn) return;\n    void sayNavigation(text, { forceLocal: false });\n  }, [voiceOn]);\n\n  // Aplica la cámara INMEDIATAMENTE al pulsar 3D/Norte (aunque el coche esté\n  // parado): rumbo (heading-up/norte) + inclinación (3D) sobre la posición.\n  useEffect(() => {\n    if (phase !== 'ruta' || !vehiclePos) return;\n    lastCenterRef.current = vehiclePos;\n    // No forzar rumbo 0 antes del primer movimiento: si aún no hay rumbo y\n    // vamos en heading-up, esperamos al primer tick de navegación.\n    if (headingUp && !Number.isFinite(lastHeadingRef.current ?? NaN)) return;\n    const h = headingUp ? (smoothHeadingRef.current ?? 0) : 0;\n    const zoom = camZoom();\n    const fwd = pitch3D && headingUp ? pointShift(vehiclePos, h || 0, lookAheadRef.current) : vehiclePos;\n    mapRef.current?.setNavView?.({\n      lng: fwd[0], lat: fwd[1], zoom,\n      bearing: h,\n      pitch: pitch3D ? NAV_PITCH : 0,\n      durationMs: 600,\n      carLng: vehiclePos[0], carLat: vehiclePos[1],\n    });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [pitch3D, headingUp, phase]);\n\n  // Fuera de la ruta (esperando/oferta) el mapa vuelve a 2D plano.\n  useEffect(() => {\n    mapRef.current?.setNavMode?.(phase === 'ruta' ? 'drive' : 'normal');\n    if (phase === 'ruta') return;\n    if (lastCenterRef.current) {\n      mapRef.current?.setNavView?.({\n        lng: lastCenterRef.current[0], lat: lastCenterRef.current[1],\n        zoom: 13, bearing: 0, pitch: 0, durationMs: 500,\n      });\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [phase]);\n\n  // Modo NOCHE del mapa por horario de Guinea Ecuatorial (UTC+1): se aplica al\n  // montar y se re-evalúa cada minuto (cruzar 19:00/06:00 cambia la paleta en\n  // vivo, sin recargar el mapa).\n  useEffect(() => {\n    let nightNow = isNightGq();\n    mapRef.current?.setNight?.(nightNow);\n    const t = setInterval(() => {\n      const n = isNightGq();\n      if (n !== nightNow) { nightNow = n; mapRef.current?.setNight?.(n); }\n    }, 60000);\n    return () => clearInterval(t);\n  }, []);\n\n  // Heartbeat: reporta la posición del conductor cada ~3 s para que el\n  // pasajero vea el coche acercándose en su mapa.\n  useEffect(() => {\n    if (phase !== 'ruta' || !current || !vehiclePos) return;\n    const now = Date.now();\n    if (now - lastLocReportRef.current < 3000) return;\n    lastLocReportRef.current = now;\n    taxiApi.reportLocation(current.id, vehiclePos[1], vehiclePos[0]).catch(() => {});\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [vehiclePos, phase, current?.id]);\n\n  // CUERDA ROJA del CONDUCTOR (DiDi, lado conductor): línea fina que une SU\n  // coche con el OBJETIVO del tramo — al RECOGER (leg 'approach') con el punto\n  // de recogida; llevando al pasajero (leg 'trip') con el DESTINO FINAL. Se\n  // refresca ~cada 0,8 s con la posición en vivo.\n  const lastRopeRef = useRef(0);\n  useEffect(() => {\n    if (phase !== 'ruta' || !current || !vehiclePos) {\n      mapRef.current?.setRope?.(null, null, null, null);\n      return;\n    }\n    const now = Date.now();\n    if (now - lastRopeRef.current < 800) return;\n    lastRopeRef.current = now;\n    const targetLng = leg === 'trip'\n      ? Number(current.dropoff_lng)\n      : Number(current.pickup_lng);\n    const targetLat = leg === 'trip'\n      ? Number(current.dropoff_lat)\n      : Number(current.pickup_lat);\n    mapRef.current?.setRope?.(\n      vehiclePos[0], vehiclePos[1],\n      targetLng, targetLat,\n    );\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [phase, current?.id, leg, vehiclePos]);\n\n  // ── Motor de navegación (fase 'ruta', por TRAMOS):\n  //    · leg 'approach': ruta = posición del conductor → punto de recogida.\n  //    · leg 'trip':      ruta = recogida → destino (igual que ve el pasajero).\n  //    · GPS real dentro de GQ → posición en vivo cada 3 s y cámara que sigue.\n  //    · Sin GPS real (pruebas fuera del país) → AVANCE SIMULADO por la ruta.\n  useEffect(() => {\n    if (phase !== 'ruta' || routeCoords.length < 2) return;\n    let timer: ReturnType<typeof setInterval> | null = null;\n    let alive = true;\n    simTravRef.current = 0;\n    lastFixRef.current = null;\n    setVehiclePos(routeCoords[0]);\n    setNavFromRemaining(totalRef.current);\n    const tangentAt = (trav: number): number | undefined => {\n      const a = pointAt(routeCoords, cumRef.current, trav);\n      const b = pointAt(routeCoords, cumRef.current, Math.min(trav + 3, totalRef.current));\n      const h = headingDeg(a, b);\n      return Number.isFinite(h) ? h : undefined;\n    };\n    (async () => {\n      // GPS real SOLO si el permiso ya está concedido (nunca mostramos el\n      // diálogo de permisos al conducir: eso congelaba la aceptación en\n      // algunos Android). Si no → simulación inmediata.\n      const gps = await getGqPositionIfAllowed(2500);\n      if (!alive) return;\n      if (gps) {\n        const push = async (first: boolean) => {\n          const g = await getGqPositionIfAllowed(2500);\n          if (!alive || !g) return;\n          const prev = lastFixRef.current;\n          const stepM = prev ? distM(prev.p, g) : 0;\n          const along = alongAt(routeCoords, cumRef.current, g);\n          setVehiclePos(g);\n          // Rumbo por la GEOMETRÍA de la ruta (no por el GPS/brújula): la\n          // cámara mira SIEMPRE hacia donde va la carretera.\n          const tg = tangentAt(along);\n          navTick(g, along, first || !prev ? 3000 : Date.now() - prev.t, stepM, tg);\n        };\n        push(true);\n        timer = setInterval(() => push(false), 3000);\n      } else {\n        // Simulación: avanza a SIM_KMH sobre la polilínea del tramo actual.\n        // Tick de 250 ms → movimiento SUAVE del coche. Si la app estuvo en\n        // segundo plano (temporizadores suspendidos), al volver RECUPERA el\n        // tiempo transcurrido y coloca el coche donde debería estar.\n        let lastRun = Date.now();\n        let done = false;\n        timer = setInterval(() => {\n          if (!alive) return;\n          const now = Date.now();\n          const dtS = Math.min((now - lastRun) / 1000, 180); // recupera hasta 3 min de pausa\n          lastRun = now;\n          const before = simTravRef.current;\n          const stepM = (SIM_KMH / 3.6) * dtS;\n          const next = Math.min(before + stepM, totalRef.current);\n          simTravRef.current = next;\n          const p = pointAt(routeCoords, cumRef.current, next);\n          const moved = next - before;\n          if (moved > 0.01) {\n            // Al volver de un salto grande (fondo) no se anuncian maniobras sueltas.\n            if (dtS > 5) { spokenRef.current = 9999; spokenStage.current = {}; }\n            setVehiclePos((prev) => {\n              if (prev && Math.abs(prev[0] - p[0]) < 0.00001 && Math.abs(prev[1] - p[1]) < 0.00001) return prev;\n              return p;\n            });\n            navTick(p, next, dtS * 1000, moved, tangentAt(next));\n          } else if (!done) {\n            done = true; // llegó al final del tramo: última actualización de UI\n            navTick(p, next, 250, 0, tangentAt(next));\n            setNavSpeed(0);\n            setNavFromRemaining(0);\n            // Mantén la cámara 2.5D en reposo (zoom 16.0-16.5, rumbo, pitch).\n            const hz = Number.isFinite(lastHeadingRef.current ?? NaN) ? (lastHeadingRef.current as number) : 0;\n            mapRef.current?.setNavView?.({\n              lng: p[0], lat: p[1], zoom: camZoom(),\n              bearing: headingUp ? hz : 0,\n              pitch: pitch3D ? NAV_PITCH : 0,\n              durationMs: 600,\n            });\n          }\n        }, 250);\n      }\n    })();\n    return () => { alive = false; if (timer) clearInterval(timer); };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [phase, current?.id, leg, routeCoords]);\n\n  const algoPrice = current ? Number(current.algorithm_price) : 0;\n  const userPrice = current ? Number(current.requested_price) : 0;\n  // P1-c: la comisión ya NO es un 10 % fijo — es POR CIUDAD (Malabo 20 % con\n  // tope, Bata 50 plano) y la fija el servidor según su política en BD. La app\n  // pregunta el neto real por SSE ciudad+precio; mientras llega, estima (≈).\n  const [netQuote, setNetQuote] = useState<Record<string, number>>({});\n  const netCity = String((current as any)?.city ?? '') || 'Malabo';\n  const netOf = (p: number) => {\n    if (!Number.isFinite(p) || p <= 0) return 0;\n    const hit = netQuote[`${netCity}:${p}`];\n    return hit ?? Math.round(p * (1 - COMMISSION));\n  };\n  const netExact = (p: number) => Number.isFinite(p) && p > 0 && netQuote[`${netCity}:${p}`] != null;\n  useEffect(() => {\n    if (phase !== 'offer' || !current) return;\n    const city = String((current as any).city ?? '') || 'Malabo';\n    const prices = [algoPrice, userPrice].filter((p) => Number.isFinite(p) && p > 0);\n    let alive = true;\n    for (const p of prices) {\n      const key = `${city}:${p}`;\n      if (netQuote[key] != null) continue;\n      settlementApi.quote(city, p)\n        .then((q) => { if (alive) setNetQuote((prev) => ({ ...prev, [key]: q.net })); })\n        .catch(() => { /* sin cuota: se queda la estimación ≈ */ });\n    }\n    return () => { alive = false; };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [phase, current?.id, algoPrice, userPrice]);\n  const isCompartido = current?.modality === 'compartido' || current?.modality === 'minibus';\n  // ── P2: perfil del pasajero en la tarjeta de solicitud ────────────────────\n  // nº de pasajeros = asientos pedidos (pool) o 1 en privado; historial =\n  // completed_trips; \"verificado\" = cuenta con historial o puntos de confianza.\n  const paxCount = current\n    ? current.is_pool\n      ? Math.max(1, Math.min(6, Number(current.max_pool_seats) || 1))\n      : 1\n    : 1;\n  const paxTrips = Math.max(0, Number(current?.passenger_trips) || 0);\n  const paxTrust = Math.max(0, Number(current?.passenger_trust) || 0);\n  const paxVerified = paxTrips > 0 || paxTrust > 0;\n  const paxInitial = (current?.passenger_name || 'P').trim().charAt(0).toUpperCase();\n\n  // FASE 3 DiDi: doble botón grande — el conductor elige con qué precio acepta\n  // (algoritmo naranja o presupuesto del usuario azul) y el viaje arranca.\n  const aceptar = async (price?: number) => {\n    const p = price ?? chosenPrice;\n    if (!current || p == null || !(p > 0) || busy) return;\n    setChosenPrice(p);\n    setFareTotal(p); // P4: precio FINAL sellado que se cobra en efectivo\n    setTripExpanded(false);\n    setBusy(true); setError(null);\n    const offer = current; // captura la oferta aceptada\n    try {\n      // 1) Aceptar en backend (rápido). Si el servidor confirma, PASAMOS a\n      //    'ruta' YA: el GPS o el cálculo de la ruta de acercamiento NO pueden\n      //    congelar la pantalla (eran awaits bloqueantes sin timeout: en\n      //    algunos Android el diálogo de permisos o el fix GPS cuelgan).\n      await taxiApi.acceptTrip(offer.id, p);\n      // Tras aceptar, la solicitud pasa a ser \"viaje propio\" y el backend\n      // expone el TELÉFONO del pasajero (para WhatsApp/llamada/PIN). Lo\n      // fusionamos en la oferta en pantalla.\n      (async () => {\n        try {\n          const upd = await taxiApi.driverTrips();\n          const own = Array.isArray(upd)\n            ? (upd as Offer[]).find((x) => x.id === offer.id && x.status !== 'requested')\n            : null;\n          if (own) setCurrent((prev) => (prev ? { ...prev, ...own } : prev));\n        } catch { /* sin red: reintentará en el próximo estado */ }\n      })();\n      if (countdownRef.current) clearInterval(countdownRef.current);\n      setPhase('ruta');\n      // 2) Acercamiento en PARALELO con timeouts (sin bloquear la UI):\n      //    · GPS real solo si el permiso YA existe (≤2,5 s).\n      //    · OSRM con AbortController (≤8 s).\n      //    Si algo falla → tramo directo al destino (tripPolyRef de la oferta).\n      (async () => {\n        const from: Coord = [Number(offer.pickup_lng), Number(offer.pickup_lat)];\n        const to: Coord = [Number(offer.dropoff_lng), Number(offer.dropoff_lat)];\n        try {\n          const gps = await getGqPositionIfAllowed(2500);\n          if (gps) anchorRef.current = gps;\n        } catch { /* sin GPS → ancla por defecto */ }\n        if (!from[0] || !to[0]) { setLeg('trip'); if (tripPolyRef.current.length >= 2) setRouteCoords(tripPolyRef.current); return; }\n        try {\n          const ctrl = new AbortController();\n          const toFall = setTimeout(() => ctrl.abort(), 8000);\n          const res = await fetch(`${OSRM}/driving/${anchorRef.current[0]},${anchorRef.current[1]};${from[0]},${from[1]}?overview=full&geometries=geojson`, { signal: ctrl.signal });\n          clearTimeout(toFall);\n          const data = await res.json();\n          const coords = (data?.routes?.[0]?.geometry?.coordinates ?? []) as Coord[];\n          if (coords.length >= 2) {\n            setLeg('approach');\n            setRouteCoords(coords);\n          } else {\n            setLeg('trip');\n            if (tripPolyRef.current.length >= 2) setRouteCoords(tripPolyRef.current);\n          }\n        } catch {\n          // Red lenta/OSRM caído: NO congelamos; arrancamos el tramo directo.\n          setLeg('trip');\n          if (tripPolyRef.current.length >= 2) setRouteCoords(tripPolyRef.current);\n        }\n      })();\n      // 3) Forzar la cámara \"sumergida\" al aceptar (zoom cerca + pitch 60).\n      setTimeout(() => {\n        const p0 = anchorRef.current;\n        mapRef.current?.setNavView?.({\n          lng: p0[0], lat: p0[1], zoom: 16.5,\n          bearing: 0, pitch: pitch3D ? NAV_PITCH : 0, durationMs: 900,\n        });\n      }, 150);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo aceptar');\n    } finally { setBusy(false); }\n  };\n\n  /** Recoger pasajero: pasa a 'in_progress' (viaje en marcha). */\n  const avanzar = async (status: 'in_progress') => {\n    if (!current || busy) return;\n    setBusy(true); setError(null);\n    try {\n      await taxiApi.updateStatus(current.id, status);\n      // TRAMO 2: recogida → destino (ruta REAL del viaje, la del pasajero).\n      setLeg('trip');\n      if (tripPolyRef.current.length >= 2) setRouteCoords(tripPolyRef.current);\n      setKm('');\n      setEta('');\n      setTimeout(() => {\n        const c = tripPolyRef.current[0] ?? MALABO_CENTER;\n        mapRef.current?.setNavView?.({\n          lng: c[0], lat: c[1], zoom: 16.5, bearing: 0, pitch: pitch3D ? NAV_PITCH : 0, durationMs: 900,\n        });\n      }, 150);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Error al actualizar');\n    } finally { setBusy(false); }\n  };\n\n  /** P1-c: «He llegado» — abre la ventana de confirmación del pasajero\n   *  (auto-cierre del servidor a los 10 min). Solo para viajes PAGADOS CON\n   *  MONEDERO: los de efectivo siguen usando «Terminar viaje y cobrar». */\n  const heLlegado = async () => {\n    if (!current || busy) return;\n    setBusy(true); setError(null);\n    try {\n      await settlementApi.arrival(current.id);\n      setCurrent((prev) => (prev ? { ...prev, status: 'arrived', arrived_at: new Date().toISOString() } as Offer : prev));\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo avisar de la llegada');\n    } finally { setBusy(false); }\n  };\n\n  /** P4 TERMINAR VIAJE: completa en el servidor e informa si cobró en efectivo.\n   *  cashOk=false ⇒ el backend BLOQUEA al conductor (cash_blocked_at) hasta que\n   *  confirme desde la tarjeta \"Confirmar cobro\" (decisión del dueño 2026-09-08).\n   *  P1-c: si el viaje está PAGADO con monedero el servidor responde\n   *  SETTLEMENT_REQUIRED: aquí NO se cierra — usa «He llegado» y espera. */\n  const terminarViaje = async (cashOk: boolean) => {\n    const offer = current;\n    if (!offer || busy) return;\n    setBusy(true); setError(null);\n    try {\n      await taxiApi.updateStatus(offer.id, 'completed', cashOk);\n      if (!cashOk) {\n        setBlockedCash(true);\n        setBlockedCashTrip(offer.id);\n      }\n      setPhase('waiting'); setCurrent(null); setRouteCoords([]);\n      setLeg('approach'); setVehiclePos(null); setTripExpanded(false); setFareTotal(0);\n      setCashOpen(false);\n    } catch (e) {\n      const code = (e as { code?: string })?.code;\n      if (code === 'SETTLEMENT_REQUIRED') {\n        setError('Este viaje lo pagó el pasajero con el monedero: pulsa «He llegado» y él confirmará el cierre (se cierra solo a los 10 min).');\n      } else {\n        setError(e instanceof Error ? e.message : 'Error al terminar el viaje');\n      }\n    } finally { setBusy(false); }\n  };\n\n  /** Confirmar el cobro pendiente → desbloquea en servidor y vuelve a trabajar. */\n  const confirmarCobro = async () => {\n    const id = blockedCashTrip ?? current?.id;\n    if (!id || busy) return;\n    setBusy(true); setError(null);\n    try {\n      await taxiApi.confirmCash(id);\n      setBlockedCash(false);\n      setBlockedCashTrip(null);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo confirmar el cobro');\n    } finally { setBusy(false); }\n  };\n\n  /** DESCANSO (decisión del dueño revisada 2026-09-08): es SOLO una marca\n   *  'resting' en backend. El conductor SIGUE en línea y SIGUE recibiendo\n   *  solicitudes: aceptar o no es SIEMPRE su elección. No pide selfie. */\n  const descansar = async (rest: boolean) => {\n    if (busy) return;\n    setBusy(true); setError(null);\n    try {\n      await driverApi.setRest(rest);\n      setResting(rest);\n      if (!rest) load();\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cambiar el estado');\n    } finally { setBusy(false); }\n  };\n\n  /** Emergencia en ruta: cancela el viaje actual y abre la marcación 24/7. */\n  const alertCancel = async () => {\n    if (!current || busy) return;\n    setBusy(true); setError(null);\n    try {\n      // P1-c: con el fare bloqueado la cancelación va por LIQUIDACIÓN:\n      // reembolso total al pasajero + falta (3 en 7 días → suspensión).\n      if ((current as any).payment_locked_at || (current as any).settlement_kind === 'WALLET') {\n        const r = await settlementApi.driverCancel(current.id, 'emergencia en ruta');\n        if (r.suspension?.suspended_until) {\n          setRutaNotice(`Has cancelado 3 viajes en 7 días: cuenta suspendida hasta ${new Date(r.suspension.suspended_until).toLocaleString('es')}.`);\n        }\n      } else {\n        await taxiApi.updateStatus(current.id, 'cancelled' as any);\n      }\n      setPhase('waiting'); setCurrent(null); setRouteCoords([]);\n      setLeg('approach'); setVehiclePos(null); setTripExpanded(false); setFareTotal(0);\n      setEmergencyOpen(true);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cancelar');\n    } finally { setBusy(false); }\n  };\n\n  const stars = useMemo(() => {\n    const r = Number(current?.passenger_rating) || 5;\n    return Array.from({ length: 5 }, (_, i) => i < Math.round(r));\n  }, [current]);\n\n  const s = styles(colors);\n  const pickup = current?.pickup_address || 'Origen';\n  const dropoff = current?.dropoff_address || 'Destino';\n  // P1-c: viaje pagado con el monedero → el cierre lo confirma el PASAJERO\n  // (o el servidor solo). El conductor avisa de llegada y cobra el NETO.\n  const walletRide = !!(current as any)?.payment_locked_at;\n  const rideArrived = !!(current as any)?.arrived_at || String(current?.status ?? '') === 'arrived';\n  const netRide = Math.max(0, Number((current as any)?.final_price ?? 0) - Number((current as any)?.fee_info?.fee ?? 0));\n\n  // HUD de carriles (cuadraditos azules con flechas) desde la maniobra actual.\n  const laneChips: string[] = (() => {\n    const m = (navTurn?.modifier || '').toLowerCase();\n    const t = (navTurn?.type || '').toLowerCase();\n    const chips = ['⬆️'];\n    if (m.indexOf('uturn') >= 0) chips.push('🔃');\n    else if (m.indexOf('right') >= 0 || t.indexOf('roundabout') >= 0) chips.push('➡️');\n    else if (m.indexOf('left') >= 0) chips.push('⬅️');\n    return chips;\n  })();\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cargando estado del conductor */}\n      {driverStatus === 'checking' && (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e10 }}>\n          <ActivityIndicator color={colors.primary} />\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, fontWeight: '600' }}>Comprobando tu cuenta de conductor…</Text>\n        </View>\n      )}\n      {/* GATE: sin alta de conductor → onboarding (cuenta + documentos) */}\n      {(driverStatus === 'none' || driverStatus === 'pending' || driverStatus === 'rejected') && (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24, gap: espaciado.e12 }}>\n          <ShieldCheck size={44} color={colors.primary} />\n          <Text style={{ fontSize: tipografia.title, fontWeight: '900', color: colors.textPrimary, textAlign: 'center' }}>\n            {driverStatus === 'pending' ? 'Documentos en revisión' : driverStatus === 'rejected' ? 'Alta rechazada' : 'Aún no eres conductor'}\n          </Text>\n          <Text style={{ fontSize: tipografia.body, textAlign: 'center', color: colors.textSecondary, lineHeight: 20 }}>\n            {driverStatus === 'pending'\n              ? 'El administrador está revisando tus documentos. Vuelve pronto.'\n              : 'Para aceptar viajes necesitas el alta de conductor: crea tu cuenta si no la tienes y sube licencia, DIP y selfie.'}\n          </Text>\n          {driverStatus !== 'pending' && (\n            <Pressable onPress={() => router.push('/driver-onboarding')} style={{ backgroundColor: colors.primary, borderRadius: radios.full, paddingVertical: espaciado.e14, paddingHorizontal: espaciado.e32 }}>\n              <Text style={{ color: brand.white, fontSize: tipografia.subtitle, fontWeight: '800' }}>Completar alta de conductor</Text>\n            </Pressable>\n          )}\n          <GhostButton title=\"Volver\" onPress={() => router.back()} />\n        </View>\n      )}\n\n      {driverStatus === 'approved' && workMode === 'intercity' && !online && null}\n      {driverStatus === 'approved' && !online && workMode !== 'intercity' && null}\n\n      {selfieOpen && (\n        <View style={[StyleSheet.absoluteFill, { backgroundColor: '#000000', zIndex: 20 }]}>\n          <CameraCapture variant=\"selfie\" instruction=\"Pon tu cara dentro del óvalo, con buena luz y sin gorra ni gafas\" onCapture={async (photo) => {\n            setBusy(true); setSelfieErr(null);\n            try {\n              // Selfie REAL en base64 para el match facial 1:1.\n              const payload = photo.base64 ? `data:image/jpeg;base64,${photo.base64}` : `captured://selfie/online/${Date.now()}`;\n              const res = await driverApi.goOnline(payload);\n              if (res.online) {\n                setSelfieOpen(false);\n                setOnline(true); setDriverStatus('approved');\n                setError(null);\n              } else {\n                // No cerramos la cámara: el conductor reintenta con la guía.\n                setSelfieErr('No se pudo confirmar la identidad. Reintenta mirando de frente, con buena luz.');\n              }\n            } catch (e) {\n              const msg = e instanceof Error ? e.message : '';\n              setSelfieErr(\n                /coincide|iluminaci|detect|selfie|face|identidad/i.test(msg)\n                  ? msg\n                  : 'No se pudo confirmar la identidad. Revisa tu conexión y reintenta.',\n              );\n            } finally { setBusy(false); }\n          }} />\n          {busy && (\n            <View style={{ position: 'absolute', top: 64, alignSelf: 'center', backgroundColor: 'rgba(0,0,0,0.75)', borderRadius: radios.full, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e9 }}>\n              <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Verificando identidad…</Text>\n            </View>\n          )}\n          {selfieErr && !busy && (\n            <View style={{ position: 'absolute', bottom: 120, alignSelf: 'center', backgroundColor: 'rgba(245,63,63,0.92)', borderRadius: 14, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e12, marginHorizontal: espaciado.e24 }}>\n              <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body, textAlign: 'center' }}>{selfieErr}</Text>\n              <Text style={{ color: brand.white, opacity: 0.9, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6 }}>\n                Pulsa el botón blanco para reintentar.\n              </Text>\n            </View>\n          )}\n        </View>\n      )}\n\n      {/* ───────── UI DEL CONDUCTOR (aprobado): mapa + tarjetas ───────── */}\n      {driverStatus === 'approved' && (\n        <>\n          {/* Cabecera */}\n          <View style={s.topBar}>\n            <Pressable onPress={() => router.back()} hitSlop={12} style={{ padding: espaciado.e4 }} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n              <ArrowLeft size={22} color={colors.textPrimary} />\n            </Pressable>\n            <Text style={s.title}>👨‍✈️ Conductor</Text>\n            <View style={{ flexDirection: 'row', gap: espaciado.e14 }}>\n              {/* Perfil (P1): abre el bottom-sheet en la pestaña Perfil. El\n                  logout SOLO vive dentro de ese Perfil (decisión del dueño). */}\n              <Pressable onPress={() => { setHomeTab('perfil'); setHomeOpen(true); }} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Perfil y opciones\">\n                <UserRound size={20} color={colors.textPrimary} />\n              </Pressable>\n              <Pressable onPress={() => setEmergencyOpen(true)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Emergencia\">\n                <Siren size={20} color={colors.danger} />\n              </Pressable>\n            </View>\n          </View>\n\n          {/* Avisos compactos (1 línea, no roban mapa) */}\n          {expiryWarnings.length > 0 && (\n            <View style={s.warnStrip}>\n              <Siren size={13} color={colors.danger} />\n              <Text style={{ color: colors.danger, fontWeight: '700', fontSize: tipografia.caption, flex: 1 }} numberOfLines={1}>\n                {expiryWarnings[0]}{expiryWarnings.length > 1 ? ` (+${expiryWarnings.length - 1} más)` : ''}\n              </Text>\n            </View>\n          )}\n          {error && <Text style={[s.error, { color: colors.danger }]}>{error}</Text>}\n          {/* Aviso de cancelación remota (pasajero): pill temporal en espera */}\n          {rutaNotice && phase === 'waiting' && (\n            <View style={[s.rutaNoticePill, { borderColor: '#F5A62366' }]}>\n              <Text style={{ color: brand.warning, fontWeight: '800', fontSize: tipografia.body }}>🚫 {rutaNotice}</Text>\n            </View>\n          )}\n\n          {/* Mapa ocupa el resto de la pantalla (flex) */}\n          <View style={s.mapArea}>\n            <EgMapView ref={mapRef} style={StyleSheet.absoluteFill}\n              onMapPress={(c) => {\n                // P1: en espera, un toque mueve la ZONA de búsqueda (ancla visual).\n                if (phase === 'waiting' && offers.length === 0 && !heatOn) {\n                  anchorRef.current = c;\n                  mapRef.current?.setCamera({ centerCoordinate: c, zoomLevel: 15, durationMs: 500 });\n                }\n              }}\n              onHazard={(h) => {\n              // ZONAS SENSIBLES + SEMÁFOROS/PASOS/STOP: aviso por DISTANCIA en\n              // metros (la página escanea ≤300 m y deduplica por coordenada).\n              // Sin simular color del semáforo (no hay datos reales en GQ).\n              if (phase !== 'ruta' || !voiceOn) return;\n              const d = (h && typeof h.distM === 'number') ? h.distM : 999;\n              if (!h || d <= 0) return;\n              if (h.kind === 'school' && d <= 260) {\n                const nm = h.name ? ` de ${h.name}` : '';\n                void sayNavigation(d >= 100\n                  ? `Cuidado, hay una escuela cerca${nm ? ' ' + nm : ''} a ${d} metros. Reduce la velocidad.`\n                  : `Cuidado, hay una escuela cerca${nm ? ' ' + nm : ''}. Reduce la velocidad.`, { forceLocal: false });\n              } else if (h.kind === 'signal' && d <= 300) {\n                void sayNavigation(d >= 100\n                  ? `Semáforo a ${d} metros. Prepárate para detenerte.`\n                  : 'Semáforo próximo. Prepárate para detenerte.', { forceLocal: false });\n              } else if (h.kind === 'zebra' && d <= 180) {\n                void sayNavigation(d >= 100\n                  ? `Paso de peatones a ${d} metros. Reduce la velocidad.`\n                  : 'Paso de peatones. Reduce la velocidad.', { forceLocal: false });\n              } else if (h.kind === 'stop' && d <= 160) {\n                void sayNavigation(d >= 100\n                  ? `Señal de stop a ${d} metros. Prepárate para detenerte.`\n                  : 'Señal de stop. Prepárate para detenerte.', { forceLocal: false });\n              }\n            }} onNavState={(s) => {\n              userZoomRef.current = s.zoom || userZoomRef.current;\n              setNavDbg(s);\n              // Look-ahead ADAPTATIVO (bucle cerrado): la página reporta cy\n              // (0..1 = altura donde proyecta el coche). Objetivo: tercio\n              // inferior ≈ 0.80. Si el coche se sale por abajo (cy≥1) o va\n              // muy arriba (cy bajo), corregimos la distancia de la cámara.\n              // cy<0 = página sin posición de coche (no ajustar).\n              if (phase === 'ruta' && typeof s.cy === 'number' && Number.isFinite(s.cy) && s.cy >= 0.05) {\n                const cy = s.cy;\n                let la = lookAheadRef.current;\n                if (cy >= 1) la = clampLookAhead(la * 0.78);      // fuera por abajo → acercar\n                else if (cy > 0.90) la = clampLookAhead(la * 0.9);\n                else if (cy < 0.68) la = clampLookAhead(la * 1.12);  // demasiado alto → alejar\n                else if (cy < 0.76) la = clampLookAhead(la * 1.06);\n                else if (cy > 0.86) la = clampLookAhead(la * 0.94);\n                if (la !== lookAheadRef.current) lookAheadRef.current = la;\n              }\n            }}>\n              <EgCamera centerCoordinate={MALABO_CENTER} zoomLevel={13} animationMode=\"moveTo\" />\n              <EgMarkers\n                markers={[\n                  ...(phase !== 'ruta' && current && current.pickup_lat ? [{ id: 'o', coordinate: [Number(current.pickup_lng), Number(current.pickup_lat)] as Coord, kind: 'origin' as const, label: pickup }] : []),\n                  ...(phase !== 'ruta' && current && current.dropoff_lat ? [{ id: 'd', coordinate: [Number(current.dropoff_lng), Number(current.dropoff_lat)] as Coord, kind: 'destination' as const, label: dropoff }] : []),\n                  ...(vehiclePos ? [{ id: 'car', coordinate: vehiclePos, kind: 'driver' as const, heading: smoothHeadingRef.current ?? undefined }] : []),\n                ]}\n              />\n              {routeCoords.length >= 2 && <EgRoutePolyline coordinates={routeCoords} />}\n            </EgMapView>\n\n            {/* Badge de modalidad (solo en la OFERTA; en ruta el mapa es el foco) */}\n            {phase === 'offer' && current && (\n              <View style={[s.badge, { backgroundColor: isCompartido ? brand.primary : brand.warning }]}>\n                <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.caption }}>\n                  {isCompartido ? `COMPARTIDO · ${current.modality === 'minibus' ? 'MINI BUS (CIEN-CIEN)' : '500 XAF Malabo / 300 XAF Bata por asiento'}` : 'CARRERA PRIVADA'}\n                </Text>\n              </View>\n            )}\n\n            {/* Tarjeta(s) inferiores superpuestas al mapa (no compiten en el layout) */}\n            <View style={[s.overlayWrap, { paddingBottom: insets.bottom + 12 }]} pointerEvents=\"box-none\">\n              {/* DESCONECTADO: tarjeta limpia para ponerse en línea */}\n              {!online && (\n                <View style={[s.bottomCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                  <View style={s.statusRow}>\n                    <View style={[s.statusDot, { backgroundColor: colors.danger }]} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle }}>No estás en línea</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                        {workMode === 'intercity'\n                          ? 'Estás en modo Ciudad a Ciudad: no recibirás solicitudes de taxi. Publica tus viajes interurbanos.'\n                          : 'Conéctate para recibir solicitudes de taxi en la ciudad.'}\n                      </Text>\n                    </View>\n                  </View>\n                  {workMode === 'intercity' ? (\n                    <>\n                      <Pressable onPress={() => router.push('/intercity-publish' as any)} style={[s.goOnlineBtn, { backgroundColor: colors.primary }]}>\n                        <Text style={s.goOnlineText}>🚌 Publicar viaje interurbano</Text>\n                      </Pressable>\n                      <GhostButton title=\"Cambiar modo del día\" onPress={() => router.push('/driver-profile' as any)} />\n                    </>\n                  ) : (\n                    <Pressable onPress={() => setSelfieOpen(true)} style={s.goOnlineBtn}>\n                      <Text style={s.goOnlineText}>Conectarse (selfie rápida)</Text>\n                      <Text style={{ color: 'rgba(255,255,255,0.85)', fontSize: tipografia.caption, fontWeight: '600' }}>\n                        {driverStatus === 'approved' ? 'Confirmas tu identidad y entras en línea' : ''}\n                      </Text>\n                    </Pressable>\n                  )}\n                </View>\n              )}\n\n              {/* P4 EFECTIVO: cobro pendiente → no se reciben solicitudes hasta\n                  confirmar (bloqueo también EN SERVIDOR: el accept devuelve 403). */}\n              {online && blockedCash && (\n                <View style={[s.bottomCard, { backgroundColor: colors.card, borderColor: '#F5A62366' }]}>\n                  <View style={s.statusRow}>\n                    <View style={[s.statusDot, { backgroundColor: brand.warning }]} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>Cobro pendiente de confirmar</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                        No recibirás solicitudes nuevas hasta confirmar que cobraste el último viaje en efectivo.\n                      </Text>\n                    </View>\n                  </View>\n                  <Pressable onPress={confirmarCobro} disabled={busy} style={[s.goOnlineBtn, { backgroundColor: brand.success, opacity: busy ? 0.6 : 1 }]}>\n                    {busy ? <ActivityIndicator color={brand.white} /> : <Text style={s.goOnlineText}>✓ Confirmar cobro y seguir trabajando</Text>}\n                  </Pressable>\n                </View>\n              )}\n\n              {/* BUSCANDO SOLICITUDES: PIN + radar 360° DENTRO del mapa.\n                  Descanso NO bloquea: se sigue recibiendo y aceptar es elección\n                  del conductor. Toca el mapa para fijar la zona (ancla visual). */}\n              {online && phase === 'waiting' && (\n                <View pointerEvents=\"box-none\" style={s.waitRadarWrap}>\n                  <View pointerEvents=\"none\" style={[s.waitRadarCard, { borderColor: 'rgba(255,255,255,0.14)' }]}>\n                    <SearchSpin color={resting ? brand.warning : brand.secondary} />\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e8 }}>\n                      {resting && <Text style={{ fontSize: tipografia.caption }}>☕</Text>}\n                      <Text style={{ color: 'rgba(255,255,255,0.92)', fontSize: tipografia.caption, fontWeight: '800' }}>\n                        {resting ? 'En descanso · sigues recibiendo solicitudes' : 'Buscando solicitudes…'}\n                      </Text>\n                    </View>\n                    <Text style={{ color: 'rgba(255,255,255,0.55)', fontSize: 10.5, fontWeight: '600', marginTop: espaciado.e2 }}>\n                      Toca el mapa para fijar tu zona\n                    </Text>\n                  </View>\n                  <Pressable\n                    onPress={() => descansar(!resting)}\n                    disabled={busy}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={resting ? 'Volver a trabajar' : 'Descansar (sigues recibiendo solicitudes)'}\n                    style={[s.restPill, { borderColor: 'rgba(255,255,255,0.22)', backgroundColor: resting ? 'rgba(245,166,35,0.9)' : 'rgba(15,20,28,0.45)' }]}\n                  >\n                    {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Text style={{ color: resting ? '#141414' : 'rgba(255,255,255,0.9)', fontSize: tipografia.caption, fontWeight: '800' }}>\n                      {resting ? 'Volver a trabajar' : '☕ Descansar'}\n                    </Text>}\n                  </Pressable>\n                </View>\n              )}\n\n              {/* OFERTA (15 s) — P2 DiDi: tarjeta OSCURA y flotante sobre el\n                  mapa (independiente del tema claro/oscuro de la app). */}\n              {online && phase === 'offer' && current && (\n                <View style={[s.bottomCard, { backgroundColor: 'rgba(20,25,32,0.97)', borderColor: 'rgba(255,255,255,0.12)' }]}>\n                  <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={s.offerContent}>\n                    {/* Countdown */}\n                    <View style={s.countRow}>\n                      <Text style={PK.countTxt}>⏱ {OFFER_SECONDS} s para aceptar</Text>\n                      <View style={[s.countTrack, { backgroundColor: 'rgba(255,255,255,0.12)' }]}>\n                        <Animated.View style={[s.countFill, { width: countdown.interpolate({ inputRange: [0, 1], outputRange: ['0%', '100%'] }) as any }]} />\n                      </View>\n                    </View>\n\n                    {/* Pasajero: nombre GRANDE + check de verificación + historial */}\n                    <View style={PK.paxRow}>\n                      <View style={PK.avatar}>\n                        <Text style={PK.avatarTxt}>{paxInitial}</Text>\n                      </View>\n                      <View style={{ flex: 1 }}>\n                        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e7 }}>\n                          <Text style={PK.name} numberOfLines={1}>{current.passenger_name || 'Pasajero'}</Text>\n                          {paxVerified ? (\n                            <View style={PK.badgeGreen}>\n                              <BadgeCheck size={12} color={brand.success} />\n                              <Text style={PK.badgeGreenTxt}>Verificado</Text>\n                            </View>\n                          ) : (\n                            <View style={PK.badgeGray}>\n                              <UserRound size={11} color=\"rgba(255,255,255,0.6)\" />\n                              <Text style={PK.badgeGrayTxt}>Cuenta nueva</Text>\n                            </View>\n                          )}\n                        </View>\n                        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginTop: espaciado.e3 }}>\n                          {stars.map((on, i) => (\n                            <Star key={i} size={11} color={on ? brand.warning : 'rgba(255,255,255,0.22)'} fill={on ? brand.warning : 'transparent'} />\n                          ))}\n                          <Text style={[PK.metaTxt, { marginLeft: espaciado.e3 }]}>\n                            {Number(current.passenger_rating) > 0 ? Number(current.passenger_rating).toFixed(1) : '—'}\n                            {' · '}{paxTrips} viajes · {paxCount} {paxCount === 1 ? 'pasajero' : 'pasajeros'}\n                          </Text>\n                        </View>\n                      </View>\n                    </View>\n\n                    {/* Trayecto origen → destino + distancia/tiempo */}\n                    <View style={s.routeInfo}>\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e7 }}>\n                        <MapPin size={14} color={brand.success} />\n                        <Text style={[s.routeText, { color: brand.white }]} numberOfLines={1}>{pickup}</Text>\n                      </View>\n                      <View style={{ paddingLeft: espaciado.e13 }}>\n                        <View style={PK.vLine} />\n                      </View>\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e7 }}>\n                        <Flag size={14} color={brand.secondary} />\n                        <Text style={[s.routeText, { color: brand.white }]} numberOfLines={1}>{dropoff}</Text>\n                      </View>\n                      <Text style={[s.meta, { color: 'rgba(255,255,255,0.62)' }]}>📏 {km} · ⏱ {eta} (OSRM)</Text>\n                    </View>\n\n                    {/* Doble botón GRANDE (P2 DiDi): naranja = ALGORITMO, azul =\n                        PRESUPUESTO del pasajero. Tocar uno = precio FINAL sellado. */}\n                    <Pressable\n                      onPress={() => aceptar(algoPrice)}\n                      disabled={busy || !(algoPrice > 0)}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={`Aceptar por el precio del algoritmo, ${algoPrice.toLocaleString('es')} XAF`}\n                      style={[s.bigAccept, { backgroundColor: brand.secondary }, (busy || !(algoPrice > 0)) && { opacity: 0.55 }]}\n                    >\n                      <Text style={s.bigAcceptTop}>{algoPrice > 0 ? `Aceptar por ${algoPrice.toLocaleString('es')} XAF` : 'Precio no disponible'}</Text>\n                      <Text style={s.bigAcceptSub}>Precio del algoritmo · ganas {netExact(algoPrice) ? '' : '≈ '}{netOf(algoPrice).toLocaleString('es')} XAF</Text>\n                    </Pressable>\n                    {userPrice > 0 && (\n                      <Pressable\n                        onPress={() => aceptar(userPrice)}\n                        disabled={busy}\n                        accessibilityRole=\"button\"\n                        accessibilityLabel={`Aceptar por el presupuesto del pasajero, ${userPrice.toLocaleString('es')} XAF`}\n                        style={[s.bigAccept, { backgroundColor: brand.primary }, busy && { opacity: 0.55 }]}\n                      >\n                        <Text style={s.bigAcceptTop}>Aceptar por {userPrice.toLocaleString('es')} XAF</Text>\n                        <Text style={s.bigAcceptSub}>Presupuesto del pasajero · ganas {netExact(userPrice) ? '' : '≈ '}{netOf(userPrice).toLocaleString('es')} XAF</Text>\n                      </Pressable>\n                    )}\n                    {busy && <ActivityIndicator color={brand.secondary} style={{ marginTop: espaciado.e8 }} />}\n                  </ScrollView>\n                </View>\n              )}\n\n              {/* EN RUTA = VISTA DE CONDUCCIÓN (interfaz mínima, mapa protagonista).\n                  El panel se muestra SIEMPRE en ruta (independiente de current). */}\n              {online && phase === 'ruta' && (\n                <View pointerEvents=\"box-none\" style={StyleSheet.absoluteFill}>\n                  {/* Estado + pasajero (chip) */}\n                  <View pointerEvents=\"none\" style={[s.dvState, { alignSelf: 'flex-start', marginTop: espaciado.e4 }]}>\n                    <Text style={[s.dvStateText, { backgroundColor: colors.card, color: colors.textPrimary, borderColor: colors.border }]}>\n                      {leg === 'trip' ? `Viaje en progreso · ${current?.passenger_name || 'Pasajero'}` : 'Yendo a por el pasajero'}\n                    </Text>\n                  </View>\n                  {navRoad ? (\n                    <View pointerEvents=\"none\" style={[s.dvState, { alignSelf: 'flex-start' }]}>\n                      <Text style={[s.dvStateText, { backgroundColor: 'rgba(0,132,255,0.14)', color: colors.primary, borderColor: 'rgba(0,132,255,0.45)' }]}>\n                        Estás en {navRoad}\n                      </Text>\n                    </View>\n                  ) : null}\n\n                  {/* HUD de carriles: cuadraditos azules con flechas (estilo Amap) */}\n                  <View pointerEvents=\"none\" style={s.dvLanes}>\n                    {laneChips.map((g, i) => (\n                      <View key={i} style={[s.dvLaneChip, { backgroundColor: i === laneChips.length - 1 && laneChips.length > 1 ? brand.primary : 'rgba(10,108,255,0.55)' }]}>\n                        <Text style={s.dvLaneGlyph2}>{g}</Text>\n                      </View>\n                    ))}\n                    <Text style={[s.dvLaneDist2, { backgroundColor: colors.card, color: colors.textPrimary, borderColor: colors.border }]}>\n                      {navDist >= 1000 ? `${(navDist / 1000).toFixed(1)} km` : `${Math.max(0, Math.round(navDist))} m`}\n                    </Text>\n                  </View>\n\n                  {/* Próxima maniobra (estilo Amap: banner compacto oscuro,\n                      centrado ARRIBA — no tapa la carretera por delante) */}\n                  <View pointerEvents=\"none\" style={s.dvMvCard}>\n                    <View style={s.dvMvGlyphBox}>\n                      <Text style={s.dvMvGlyphBig}>{navTurn ? turnGlyph(navTurn.type, navTurn.modifier) : '⬆️'}</Text>\n                    </View>\n                    <View style={{ flex: 1, justifyContent: 'center' }}>\n                      <Text style={s.dvMvDist}>\n                        {navDist >= 1000 ? `${(navDist / 1000).toFixed(1)} km` : `${Math.max(0, Math.round(navDist))} m`}\n                      </Text>\n                      <Text numberOfLines={1} style={s.dvMvName}>\n                        {navTurn?.name || (leg === 'approach' ? 'Hacia el punto de recogida' : 'Hacia el destino')}\n                      </Text>\n                    </View>\n                    {navTurn2 ? (\n                      <View style={s.dvMvNext}>\n                        <Text style={s.dvMvGlyphSmall}>{turnGlyph(navTurn2.type, navTurn2.modifier)}</Text>\n                        <Text numberOfLines={1} style={s.dvMvNextText}>\n                          {navTurn2.name || 'siguiente'}\n                        </Text>\n                      </View>\n                    ) : null}\n                  </View>\n\n                  {/* Controles mínimos: rumbo · 3D · voz */}\n                  <View style={s.dvCtrls} pointerEvents=\"box-none\">\n                    <Pressable onPress={() => setHeadingUp((h) => !h)} accessibilityRole=\"button\" accessibilityLabel={headingUp ? 'Mapa orientado al movimiento (tocar: norte fijo)' : 'Mapa con norte fijo (tocar: seguir rumbo)'} style={[s.dvBtn, { backgroundColor: headingUp ? colors.primary : colors.card, borderColor: colors.border }]}>\n                      <Compass size={18} color={headingUp ? brand.white : colors.textSecondary} />\n                    </Pressable>\n                    <Pressable onPress={() => setPitch3D((p) => !p)} accessibilityRole=\"button\" accessibilityLabel={pitch3D ? 'Desactivar vista 3D' : 'Activar vista 3D'} style={[s.dvBtn, { backgroundColor: pitch3D ? colors.primary : colors.card, borderColor: colors.border }]}>\n                      <Box size={18} color={pitch3D ? brand.white : colors.textSecondary} />\n                    </Pressable>\n                    <Pressable onPress={() => setVoiceOn((prev) => { const nv = !prev; if (!nv) stopAllVoice(); else setTimeout(() => sayEs('Indicaciones por voz activadas'), 150); return nv; })} accessibilityRole=\"button\" accessibilityLabel={voiceOn ? 'Silenciar indicaciones por voz' : 'Activar indicaciones por voz'} style={[s.dvBtn, { backgroundColor: voiceOn ? colors.primary : colors.card, borderColor: colors.border }]}>\n                      {voiceOn ? <Volume2 size={18} color={brand.white} /> : <VolumeX size={18} color={colors.textSecondary} />}\n                    </Pressable>\n                    {/* Descanso SIEMPRE disponible (también en viaje): no bloquea,\n                        solo marca 'resting'; aceptar sigue siendo tu elección. */}\n                    <Pressable\n                      onPress={() => descansar(!resting)}\n                      disabled={busy}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={resting ? 'Volver a trabajar (sin selfie)' : 'Descansar (sigues recibiendo solicitudes)'}\n                      style={[s.dvBtn, { backgroundColor: resting ? brand.warning : alpha(colors.card, 0.92), borderColor: resting ? brand.warning : colors.border }]}\n                    >\n                      {busy ? <ActivityIndicator size=\"small\" color={resting ? '#141414' : colors.textSecondary} /> : <Text style={{ fontSize: 17, color: resting ? '#141414' : colors.textSecondary }}>☕</Text>}\n                    </Pressable>\n                  </View>\n\n                  {/* Estado real del mapa (verificación 3D: b=rumbo p=inclinación) */}\n                  {navDbg && (\n                    <View pointerEvents=\"none\" style={[s.dvDbg, { backgroundColor: pitch3D ? 'rgba(0,132,255,0.18)' : colors.card, borderColor: pitch3D ? colors.primary : colors.border }]}>\n                      <Text style={{ color: pitch3D ? colors.primary : colors.textSecondary, fontSize: 10, fontWeight: '900' }}>\n                        {pitch3D ? '3D ' : ''}b {navDbg.bearing}° · p {navDbg.pitch}° · z{navDbg.zoom}\n                        {typeof navDbg.cy === 'number' ? ` · c${navDbg.cy}` : ''}\n                      </Text>\n                    </View>\n                  )}\n\n                  {/* Velocidad actual (transparente, no tapa el mapa) */}\n                  <View style={[s.dvSpeed, { backgroundColor: 'rgba(15,20,28,0.5)', borderColor: 'rgba(255,255,255,0.16)' }]}>\n                    <Text style={[s.dvSpeedNum, { color: brand.white }]}>{Math.round(navSpeed)}</Text>\n                    <Text style={[s.dvSpeedUnit, { color: 'rgba(255,255,255,0.7)' }]}>km/h</Text>\n                  </View>\n\n                  {/* TARJETA B — Viaje en marcha al DESTINO FINAL (P4): TOTAL en\n                      efectivo + hora + \"Más\". Compacta y translúcida. */}\n                  {leg === 'trip' ? (\n                    <>\n                      <View style={[s.dvTrip, { backgroundColor: 'rgba(15,20,28,0.55)', borderColor: 'rgba(255,255,255,0.14)' }]}>\n                        <View style={{ flex: 1, gap: 1 }}>\n                          <Text style={{ color: 'rgba(255,255,255,0.62)', fontSize: 9.5, fontWeight: '800', letterSpacing: 0.5 }}>\n                            {walletRide ? 'PAGADO CON PIN · TU NETO' : 'TOTAL EFECTIVO'}\n                          </Text>\n                          <Text style={[s.dvTripFare, { color: brand.white }]}>\n                            {walletRide\n                              ? `${netRide.toLocaleString('es')} XAF`\n                              : fareTotal > 0 ? `${fareTotal.toLocaleString('es')} XAF` : '—'}\n                          </Text>\n                          <Text style={{ color: 'rgba(255,255,255,0.85)', fontSize: tipografia.caption, fontWeight: '800' }}>\n                            Llega {new Date(Date.now() + (navMinLeft || 0) * 60000).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })} ·{' '}\n                            {navKmLeft != null ? `${navKmLeft < 1 ? `${Math.round(navKmLeft * 1000)} m` : `${navKmLeft.toFixed(1)} km`} · ${navMinLeft ?? '—'} min` : 'calculando…'}\n                          </Text>\n                        </View>\n                        <Pressable\n                          onPress={() => setTripExpanded((v) => !v)}\n                          hitSlop={8}\n                          accessibilityRole=\"button\"\n                          accessibilityLabel={tripExpanded ? 'Ocultar detalles del viaje' : 'Ver más detalles del viaje'}\n                          style={[s.dvMoreBtn, { borderColor: 'rgba(255,255,255,0.22)' }]}\n                        >\n                          {tripExpanded ? <ChevronDown size={14} color=\"rgba(255,255,255,0.9)\" /> : <ChevronUp size={14} color=\"rgba(255,255,255,0.9)\" />}\n                          <Text style={{ color: 'rgba(255,255,255,0.9)', fontSize: 10, fontWeight: '800' }}>{tripExpanded ? 'Menos' : 'Más'}</Text>\n                        </Pressable>\n                      </View>\n                      {tripExpanded && current && (\n                        <View style={[s.dvTripMore, { backgroundColor: 'rgba(15,20,28,0.62)', borderColor: 'rgba(255,255,255,0.14)' }]}>\n                          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n                            <MapPin size={12} color={brand.success} />\n                            <Text style={{ color: 'rgba(255,255,255,0.85)', fontSize: tipografia.caption, fontWeight: '600', flex: 1 }} numberOfLines={1}>{pickup}</Text>\n                          </View>\n                          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n                            <Flag size={12} color={brand.secondary} />\n                            <Text style={{ color: 'rgba(255,255,255,0.85)', fontSize: tipografia.caption, fontWeight: '600', flex: 1 }} numberOfLines={1}>{dropoff}</Text>\n                          </View>\n                          <Text numberOfLines={1} style={{ color: 'rgba(255,255,255,0.6)', fontSize: 10.5, fontWeight: '600' }}>\n                            👤 {current.passenger_name || 'Pasajero'} · {paxCount} {paxCount === 1 ? 'pasajero' : 'pasajeros'}\n                          </Text>\n                        </View>\n                      )}\n                    </>\n                  ) : (\n                    /* TARJETA A — \"Camino para recoger al pasajero\": dirección +\n                       WhatsApp y teléfono. Transparente y compacta. */\n                    <View pointerEvents=\"box-none\" style={[s.dvCardA, { backgroundColor: 'rgba(15,20,28,0.5)', borderColor: 'rgba(255,255,255,0.14)' }]}>\n                      <View style={{ flex: 1 }}>\n                        <Text style={{ color: brand.success, fontSize: 10, fontWeight: '900', letterSpacing: 0.4 }}>🟢 CAMINO PARA RECOGER AL PASAJERO</Text>\n                        <Text numberOfLines={1} style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e2 }}>{pickup}</Text>\n                        {current?.passenger_name ? (\n                          <Text numberOfLines={1} style={{ color: 'rgba(255,255,255,0.62)', fontSize: tipografia.micro, fontWeight: '600', marginTop: 1 }}>👤 {current.passenger_name}</Text>\n                        ) : null}\n                      </View>\n                      <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n                        <Pressable\n                          onPress={() => { const d = (current?.passenger_phone || '').replace(/\\D/g, ''); if (d) Linking.openURL(`https://wa.me/${d}`).catch(() => {}); }}\n                          disabled={!current?.passenger_phone}\n                          accessibilityRole=\"button\"\n                          accessibilityLabel=\"Escribir al pasajero por WhatsApp\"\n                          style={[s.contactBtn, { backgroundColor: brand.success }]}\n                        >\n                          <MessageCircle size={17} color={brand.white} />\n                        </Pressable>\n                        <Pressable\n                          onPress={() => { const d = (current?.passenger_phone || '').replace(/\\D/g, ''); if (d) Linking.openURL(`tel:${d}`).catch(() => {}); }}\n                          disabled={!current?.passenger_phone}\n                          accessibilityRole=\"button\"\n                          accessibilityLabel=\"Llamar al pasajero\"\n                          style={[s.contactBtn, { backgroundColor: brand.primary }]}\n                        >\n                          <Phone size={17} color={brand.white} />\n                        </Pressable>\n                      </View>\n                    </View>\n                  )}\n\n                  {/* PIN del pasajero (solo al LLEGAR: pídele el código) */}\n                  {leg === 'approach' && (navKmLeft ?? 1) < 0.08 && current?.passenger_phone ? (\n                    <View pointerEvents=\"none\" style={[s.dvPin, { backgroundColor: 'rgba(15,20,28,0.6)', borderColor: 'rgba(43,194,106,0.5)' }]}>\n                      <Text style={{ color: 'rgba(255,255,255,0.7)', fontSize: 10, fontWeight: '800', letterSpacing: 0.4 }}>CÓDIGO DEL PASAJERO</Text>\n                      <Text style={{ color: brand.success, fontSize: 17, fontWeight: '900', letterSpacing: 5 }}>{pinLast4(current.passenger_phone)}</Text>\n                    </View>\n                  ) : null}\n\n                  {/* Botones: Cancelar / Recoger al llegar · Terminar y cobrar */}\n                  <View style={s.dvActions} pointerEvents=\"box-none\">\n                    <Pressable onPress={alertCancel} accessibilityRole=\"button\" accessibilityLabel=\"Cancelar y alertar\" style={[s.dvCancel, { backgroundColor: 'rgba(15,20,28,0.5)', borderColor: 'rgba(255,255,255,0.2)' }]}>\n                      <X size={18} color={brand.danger} />\n                    </Pressable>\n                    <Pressable\n                      onPress={() => {\n                        // RECOGIDA: al llegar, pedir el CÓDIGO de 4 dígitos al\n                        // pasajero (panel profesional) → validado → in_progress.\n                        // P1-c: viaje con monedero → «He llegado» (el cierre lo\n                        // confirma el pasajero o auto a los 10 min). Efectivo:\n                        // Terminar el viaje exige CONFIRMAR el cobro (modal P4).\n                        if (leg === 'approach' && (navKmLeft ?? 1) < 0.08) {\n                          if (!current?.passenger_phone) { avanzar('in_progress'); return; }\n                          setPinOpen(true);\n                        } else if (walletRide && !rideArrived) {\n                          void heLlegado();\n                        } else if (walletRide && rideArrived) {\n                          /* esperando al pasajero: sin acción */\n                        } else {\n                          setCashOpen(true);\n                        }\n                      }}\n                      disabled={busy || (walletRide && rideArrived)}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={leg === 'approach' && (navKmLeft ?? 1) < 0.08 ? 'Recoger pasajero' : walletRide ? (rideArrived ? 'Esperando confirmación del pasajero' : 'Marcar llegada al destino') : 'Terminar viaje y cobrar'}\n                      style={[s.dvMain, {\n                        backgroundColor: leg === 'approach' && (navKmLeft ?? 1) < 0.08\n                          ? brand.success\n                          : walletRide ? (rideArrived ? '#8A8F98' : brand.warning) : brand.danger,\n                      }, busy && { opacity: 0.6 }]}\n                    >\n                      {leg === 'approach' && (navKmLeft ?? 1) < 0.08 ? (\n                        <>\n                          <CheckCircle2 size={18} color={brand.white} />\n                          <Text style={s.dvMainText}>Recoger pasajero</Text>\n                        </>\n                      ) : walletRide ? (\n                        rideArrived ? (\n                          <>\n                            <Text style={{ fontSize: 15 }}>⏳</Text>\n                            <Text style={s.dvMainText}>Esperando confirmación del pasajero</Text>\n                          </>\n                        ) : (\n                          <>\n                            <Flag size={18} color={brand.white} />\n                            <Text style={s.dvMainText}>He llegado al destino</Text>\n                          </>\n                        )\n                      ) : (\n                        <>\n                          <Banknote size={18} color={brand.white} />\n                          <Text style={s.dvMainText}>Terminar viaje y cobrar</Text>\n                        </>\n                      )}\n                    </Pressable>\n                  </View>\n                </View>\n              )}\n            </View>\n\n            {/* P1: botón de PERFIL transparente abajo-derecha (abre el\n                bottom-sheet Home en la pestaña Perfil). Oculto durante la\n                oferta y la conducción para no estorbar. */}\n            {phase !== 'offer' && phase !== 'ruta' && (\n              <>\n                {heatOn && (\n                  <View pointerEvents=\"none\" style={[s.heatChip, { backgroundColor: alpha(brand.warning, 0.92) }]}>\n                    <Text style={{ color: brand.onWarning, fontSize: tipografia.caption, fontWeight: '800' }}>\n                      🔥 Zonas calientes (simulación) · sin demanda real aún\n                    </Text>\n                  </View>\n                )}\n                {/* EMERGENCIA (mapa): marcación directa 24/7 (ícono tipo DiDi SOS) */}\n                <Pressable\n                  onPress={() => setEmergencyOpen(true)}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Emergencia: marcación directa 24/7\"\n                  style={[s.homeFab, { bottom: 216, backgroundColor: 'rgba(245,63,63,0.92)', borderColor: brand.danger }]}\n                >\n                  <Siren size={18} color={brand.white} />\n                </Pressable>\n                <Pressable\n                  onPress={toggleHeat}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={heatOn ? 'Ocultar zonas calientes' : 'Mostrar zonas calientes simuladas'}\n                  accessibilityState={{ selected: heatOn }}\n                  style={[s.homeFab, { bottom: 156, backgroundColor: heatOn ? alpha(brand.warning, 0.9) : alpha(colors.card, 0.55), borderColor: heatOn ? brand.warning : alpha(colors.border, 0.8) }]}\n                >\n                  <Text style={{ fontSize: 19 }}>🔥</Text>\n                </Pressable>\n                <Pressable\n                  onPress={() => { setHomeTab('perfil'); setHomeOpen(true); }}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Abrir perfil y opciones del conductor\"\n                  style={[s.homeFab, { bottom: 96, backgroundColor: alpha(colors.card, 0.55), borderColor: alpha(colors.border, 0.8) }]}\n                >\n                  <UserRound size={21} color={colors.primary} />\n                </Pressable>\n              </>\n            )}\n          </View>\n        </>\n      )}\n\n      <EmergencyModal visible={emergencyOpen} onClose={() => setEmergencyOpen(false)} />\n      <CashFlowModal\n        visible={cashOpen}\n        amount={fareTotal}\n        busy={busy}\n        onYes={() => terminarViaje(true)}\n        onNo={() => terminarViaje(false)}\n        onClose={() => setCashOpen(false)}\n      />\n      <PinPadModal\n        visible={pinOpen}\n        passengerName={current?.passenger_name}\n        busy={busy}\n        onCancel={() => setPinOpen(false)}\n        onOk={async (d) => {\n          // Valida los 4 dígitos contra el PIN derivado del teléfono del pasajero.\n          if (current && pinLast4(current.passenger_phone) === d) {\n            setPinOpen(false);\n            await avanzar('in_progress');\n            return true;\n          }\n          return false;\n        }}\n      />\n      <DriverHomeSheet visible={homeOpen} tab={homeTab} onClose={() => setHomeOpen(false)} />\n    </View>\n  );\n}\n\n/** P4 — Modal \"¿Recibiste el dinero?\" (efectivo) al terminar el viaje.\n *  · SÍ  → se completa y el conductor sigue disponible.\n *  · NO  → se completa y el conductor queda BLOQUEADO (servidor) para nuevas\n *          solicitudes hasta que confirme el cobro desde la tarjeta de espera. */\n/** RECOGIDA — Panel profesional para pedir el CÓDIGO (PIN) al pasajero.\n *  Teclado numérico; con 4 dígitos valida contra onOk (PIN = últimos 4 del\n *  teléfono del pasajero). Acierto → siguiente estado; fallo → error y borra. */\nfunction PinPadModal({ visible, passengerName, busy, onCancel, onOk }: {\n  visible: boolean; passengerName?: string; busy: boolean;\n  onCancel: () => void; onOk: (digits: string) => Promise<boolean>;\n}) {\n  const [digits, setDigits] = useState('');\n  const [err, setErr] = useState(false);\n  const [checking, setChecking] = useState(false);\n\n  useEffect(() => { if (visible) { setDigits(''); setErr(false); setChecking(false); } }, [visible]);\n\n  const press = (k: string) => {\n    if (busy || checking) return;\n    setErr(false);\n    if (k === 'DEL') { setDigits((d) => d.slice(0, -1)); return; }\n    if (digits.length >= 4) return;\n    const next = digits + k;\n    setDigits(next);\n    if (next.length === 4) {\n      setChecking(true);\n      (async () => {\n        const ok = await onOk(next).catch(() => false);\n        if (!ok) { setDigits(''); setErr(true); }\n        setChecking(false);\n      })();\n    }\n  };\n\n  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', 'DEL'];\n  return (\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onCancel}>\n      <View style={pps.overlay}>\n        <View style={pps.card}>\n          <View style={pps.iconCircle}>\n            <ShieldCheck size={26} color={brand.success} />\n          </View>\n          <Text style={pps.title}>Código del pasajero</Text>\n          <Text style={pps.sub} numberOfLines={1}>\n            Pídele a {passengerName || 'el pasajero'} el código de 4 dígitos\n          </Text>\n\n          {/* Cajas del código */}\n          <View style={pps.boxRow}>\n            {[0, 1, 2, 3].map((i) => (\n              <View key={i} style={[pps.box, { borderColor: err ? brand.danger : digits.length > i ? brand.success : '#E5E7EB' }]}>\n                <Text style={{ color: '#111827', fontSize: 26, fontWeight: '900' }}>{digits[i] ?? ''}</Text>\n              </View>\n            ))}\n          </View>\n          {err ? <Text style={pps.errTxt}>Código incorrecto — vuelve a preguntarlo</Text> : null}\n          {checking ? <ActivityIndicator color={brand.success} style={{ marginVertical: espaciado.e6 }} /> : null}\n\n          {/* Teclado */}\n          <View style={pps.pad}>\n            {keys.map((k, idx) =>\n              k === '' ? <View key={idx} style={pps.key} />\n                : (\n                  <Pressable key={idx} onPress={() => press(k)} disabled={busy || checking}\n                    accessibilityRole=\"button\" accessibilityLabel={k === 'DEL' ? 'Borrar dígito' : `Dígito ${k}`}\n                    style={({ pressed }) => [pps.key, { backgroundColor: k === 'DEL' ? '#F53F3F10' : '#F3F4F6', opacity: pressed ? 0.6 : 1 }]}>\n                    {k === 'DEL'\n                      ? <X size={20} color={brand.danger} />\n                      : <Text style={{ color: '#111827', fontSize: 22, fontWeight: '800' }}>{k}</Text>}\n                  </Pressable>\n                ),\n            )}\n          </View>\n\n          <Pressable onPress={onCancel} disabled={busy} accessibilityRole=\"button\" accessibilityLabel=\"Cancelar petición de código\" style={{ marginTop: espaciado.e10 }}>\n            <Text style={{ color: '#6B7280', fontSize: tipografia.body, fontWeight: '700' }}>Cancelar</Text>\n          </Pressable>\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\nconst pps = StyleSheet.create({\n  overlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)', alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 },\n  card: { width: '100%', maxWidth: 360, backgroundColor: brand.white, borderRadius: 24, padding: espaciado.e22, alignItems: 'center', gap: espaciado.e6 },\n  iconCircle: { width: 54, height: 54, borderRadius: 27, backgroundColor: '#27AE6018', alignItems: 'center', justifyContent: 'center', marginBottom: espaciado.e2 },\n  title: { color: '#111827', fontSize: 19, fontWeight: '900', textAlign: 'center' },\n  sub: { color: '#6B7280', fontSize: tipografia.caption, fontWeight: '600', textAlign: 'center' },\n  boxRow: { flexDirection: 'row', gap: espaciado.e12, marginVertical: espaciado.e12 },\n  box: { width: 56, height: 64, borderRadius: radios.md, borderWidth: 2, alignItems: 'center', justifyContent: 'center' },\n  errTxt: { color: brand.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e2 },\n  pad: { width: '100%', flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', gap: espaciado.e8, marginTop: espaciado.e8 },\n  key: { width: 76, height: altura.boton, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n});\n\nfunction CashFlowModal({ visible, amount, busy, onYes, onNo, onClose }: {\n  visible: boolean; amount: number; busy: boolean;\n  onYes: () => void; onNo: () => void; onClose: () => void;\n}) {\n  return (\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose}>\n      <View style={cfm.overlay}>\n        <View style={cfm.card}>\n          <View style={cfm.iconCircle}>\n            <Banknote size={30} color={brand.success} />\n          </View>\n          <Text style={cfm.title}>¿Recibiste el dinero?</Text>\n          <Text style={cfm.sub}>Viaje en efectivo · cobra al pasajero antes de continuar</Text>\n          <Text style={cfm.amount}>{amount > 0 ? `${amount.toLocaleString('es')} XAF` : '— XAF'}</Text>\n          <Pressable\n            onPress={onYes}\n            disabled={busy}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Sí, recibí el dinero en efectivo\"\n            style={[cfm.btnYes, busy && { opacity: 0.6 }]}\n          >\n            {busy ? <ActivityIndicator color={brand.white} /> : <Text style={cfm.btnYesTxt}>Sí, lo recibí ✓</Text>}\n          </Pressable>\n          <Pressable\n            onPress={onNo}\n            disabled={busy}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"No recibí el dinero\"\n            style={[cfm.btnNo, busy && { opacity: 0.6 }]}\n          >\n            <Text style={cfm.btnNoTxt}>No recibí el dinero</Text>\n          </Pressable>\n          <Text style={cfm.note}>\n            Si marcas \"No\", no recibirás solicitudes nuevas hasta confirmar el cobro (bloqueo en servidor).\n          </Text>\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\nconst cfm = StyleSheet.create({\n  overlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)', alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 },\n  card: { width: '100%', maxWidth: 360, backgroundColor: brand.white, borderRadius: 24, padding: espaciado.e22, alignItems: 'center', gap: espaciado.e8 },\n  iconCircle: { width: 60, height: 60, borderRadius: 30, backgroundColor: '#27AE6018', alignItems: 'center', justifyContent: 'center', marginBottom: espaciado.e4 },\n  title: { color: '#111827', fontSize: tipografia.title, fontWeight: '900', textAlign: 'center' },\n  sub: { color: '#6B7280', fontSize: tipografia.body, fontWeight: '600', textAlign: 'center' },\n  amount: { color: '#111827', fontSize: 34, fontWeight: '900', marginVertical: espaciado.e6 },\n  btnYes: { width: '100%', backgroundColor: brand.success, borderRadius: radios.lg, paddingVertical: 15, alignItems: 'center', marginTop: espaciado.e6, elevation: 3 },\n  btnYesTxt: { color: brand.white, fontSize: tipografia.subtitle, fontWeight: '900' },\n  btnNo: { width: '100%', borderWidth: 1.5, borderColor: '#F53F3F55', borderRadius: radios.lg, paddingVertical: espaciado.e12, alignItems: 'center', marginTop: espaciado.e8, backgroundColor: '#F53F3F0C' },\n  btnNoTxt: { color: brand.danger, fontSize: 14.5, fontWeight: '800' },\n  note: { color: '#9CA3AF', fontSize: tipografia.micro, fontWeight: '600', textAlign: 'center', marginTop: espaciado.e6 },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e6 },\n    title: { fontSize: 18, fontWeight: '800', color: c.textPrimary },\n    error: { fontSize: tipografia.caption, fontWeight: '700', textAlign: 'center', marginHorizontal: espaciado.e16 },\n    mapWrap: { height: '50%', position: 'relative' },\n    mapArea: { flex: 1, position: 'relative' },\n    overlayWrap: { position: 'absolute', left: 0, right: 0, bottom: 0, top: 0, justifyContent: 'flex-end', padding: espaciado.e12 },\n    bottomCard: {\n      width: '100%', maxHeight: '36%', borderRadius: 24, borderWidth: 1,\n      padding: espaciado.e14, gap: espaciado.e10,\n      ...elevation.lg,\n    },\n    offerContent: { gap: espaciado.e12, paddingBottom: espaciado.e6 },\n    warnStrip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e7, marginHorizontal: espaciado.e12, marginTop: espaciado.e6, backgroundColor: '#F53F3F14', borderRadius: 10, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6 },\n    rutaNoticePill: {\n      alignSelf: 'center', marginTop: espaciado.e8, borderRadius: radios.full, borderWidth: 1,\n      backgroundColor: 'rgba(15,20,28,0.82)', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8,\n    },\n    statusRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, width: '100%' },\n    statusDot: { width: 12, height: 12, borderRadius: 6 },\n    goOnlineBtn: { width: '100%', backgroundColor: brand.success, borderRadius: 18, paddingVertical: 15, alignItems: 'center', elevation: 4 },\n    goOnlineText: { color: brand.white, fontSize: tipografia.subtitle, fontWeight: '900', letterSpacing: 0.2 },\n    followBtn: { position: 'absolute', top: 8, right: 10, flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, borderRadius: radios.full, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, elevation: 4 },\n    navRow: { flexDirection: 'row', alignItems: 'baseline', gap: espaciado.e6, marginTop: espaciado.e2 },\n    badge: { position: 'absolute', top: 64, alignSelf: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e6, elevation: 4 },\n    panel: { flex: 1, margin: espaciado.e12, borderRadius: 20, borderWidth: 1, padding: espaciado.e16, gap: espaciado.e10, alignItems: 'center', justifyContent: 'center' },\n    waitText: { fontSize: tipografia.body, fontWeight: '600', marginTop: espaciado.e8 },\n    countRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, width: '100%' },\n    countTrack: { flex: 1, height: 6, borderRadius: 3, backgroundColor: c.border, overflow: 'hidden' },\n    countFill: { height: 6, backgroundColor: brand.secondary, borderRadius: 3 },\n    netLabel: { fontSize: tipografia.micro, fontWeight: '700', letterSpacing: 0.4 },\n    netAmount: { fontSize: tipografia.display, fontWeight: '900' },\n    routeInfo: { width: '100%', gap: espaciado.e4, marginTop: espaciado.e4 },\n    routeText: { fontSize: tipografia.body, fontWeight: '700', flex: 1 },\n    meta: { fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e4 },\n    priceRow: { flexDirection: 'row', gap: espaciado.e10, width: '100%' },\n    priceChip: { flex: 1, borderRadius: 14, borderWidth: 1.5, padding: espaciado.e10, alignItems: 'center', gap: espaciado.e2 },\n    acceptBtn: { width: '100%', backgroundColor: brand.success, borderRadius: 18, paddingVertical: 15, alignItems: 'center', gap: espaciado.e2, elevation: 4 },\n    acceptText: { color: brand.white, fontSize: 17, fontWeight: '900' },\n    bigAccept: { width: '100%', borderRadius: radios.lg, paddingVertical: espaciado.e13, paddingHorizontal: espaciado.e14, alignItems: 'center', gap: espaciado.e2, elevation: 3 },\n    bigAcceptTop: { color: brand.white, fontSize: 17, fontWeight: '900' },\n    bigAcceptSub: { color: 'rgba(255,255,255,0.9)', fontSize: tipografia.caption, fontWeight: '600' },\n    headerState: { fontSize: tipografia.subtitle, fontWeight: '800' },\n    passenger: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, width: '100%' },\n    avatar: { width: 46, height: 46, borderRadius: 23, backgroundColor: brand.primary, alignItems: 'center', justifyContent: 'center' },\n    roundBtn: { width: 46, height: 46, borderRadius: 23, alignItems: 'center', justifyContent: 'center' },\n    goBtn: { width: '100%', backgroundColor: brand.primary, borderRadius: radios.lg, paddingVertical: espaciado.e13, alignItems: 'center' },\n    goText: { color: brand.white, fontSize: 15, fontWeight: '800' },\n    endBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, width: '100%', backgroundColor: brand.danger, borderRadius: radios.lg, paddingVertical: espaciado.e14 },\n    endText: { color: brand.white, fontSize: 15, fontWeight: '900' },\n    alertBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, width: '100%', borderWidth: 1, borderColor: '#F53F3F55', borderRadius: 14, paddingVertical: espaciado.e11, backgroundColor: '#F53F3F10' },\n    // ── Vista de conducción ──\n    dvState: { paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e4, marginTop: espaciado.e2 },\n    dvStateText: { fontSize: tipografia.caption, fontWeight: '800', paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, borderRadius: radios.full, borderWidth: 1, overflow: 'hidden' },\n    dvLane: { position: 'absolute', top: 92, left: 12, width: 74, height: 74, borderRadius: 37, alignItems: 'center', justifyContent: 'center', ...elevation.lg },\n    dvLanes: { position: 'absolute', top: 212, left: 0, right: 0, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6 },\n    dvLaneChip: { width: 36, height: 36, borderRadius: 9, alignItems: 'center', justifyContent: 'center', elevation: 4 },\n    dvLaneGlyph2: { color: brand.white, fontSize: 19, fontWeight: '900' },\n    dvLaneDist2: { fontSize: tipografia.caption, fontWeight: '800', paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: radios.sm, borderWidth: 1, color: brand.white, backgroundColor: 'rgba(10,16,28,0.7)', borderColor: 'transparent' },\n    dvLaneGlyph: { color: brand.white, fontSize: 34, fontWeight: '900' },\n    dvLaneDist: { color: brand.white, fontSize: 10.5, fontWeight: '900', marginTop: -4 },\n    dvMvCard: { position: 'absolute', top: 150, alignSelf: 'center', maxWidth: '82%', flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderRadius: radios.full, backgroundColor: 'rgba(10,16,28,0.80)', paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6, ...elevation.lg },\n    dvMvGlyphBox: { width: 42, height: 42, borderRadius: 21, backgroundColor: 'rgba(255,255,255,0.16)', alignItems: 'center', justifyContent: 'center' },\n    dvMvGlyphBig: { fontSize: 24, fontWeight: '900' },\n    dvMvGlyphSmall: { fontSize: 15 },\n    dvMvDist: { fontSize: 21, fontWeight: '900', color: brand.white },\n    dvMvName: { fontSize: tipografia.caption, fontWeight: '700', color: 'rgba(255,255,255,0.85)', marginTop: 1 },\n    dvMvNext: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, borderLeftWidth: 1, borderLeftColor: 'rgba(255,255,255,0.3)', paddingLeft: espaciado.e8, maxWidth: 90 },\n    dvMvNextText: { fontSize: 10.5, fontWeight: '600', color: 'rgba(255,255,255,0.8)' },\n    dvCtrls: { position: 'absolute', top: 8, right: 10, gap: espaciado.e8 },\n    dvDbg: { position: 'absolute', top: 210, right: 10, borderRadius: radios.sm, borderWidth: 1, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4 },\n    dvBtn: { width: 42, height: 42, borderRadius: 21, borderWidth: 1, alignItems: 'center', justifyContent: 'center', elevation: 4 },\n    dvSpeed: { position: 'absolute', bottom: 104, left: 14, width: 74, height: 74, borderRadius: 37, borderWidth: 2, alignItems: 'center', justifyContent: 'center', elevation: 5 },\n    dvSpeedNum: { fontSize: 21, fontWeight: '900' },\n    dvSpeedUnit: { fontSize: 9, fontWeight: '700' },\n    dvEta: { position: 'absolute', bottom: 96, right: 14, borderRadius: 14, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, elevation: 5 },\n    dvEtaClock: { fontSize: tipografia.body, fontWeight: '900' },\n    dvEtaSub: { fontSize: tipografia.micro, fontWeight: '600' },\n    dvActions: { position: 'absolute', bottom: 0, left: 0, right: 0, flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e8 },\n    dvPin: { position: 'absolute', bottom: 172, alignSelf: 'center', alignItems: 'center', borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e5, elevation: 5 },\n    // P4: tarjeta del viaje EN MARCHA (TOTAL efectivo + hora + \"Más\" expandible)\n    dvTrip: {\n      position: 'absolute', bottom: 96, right: 14, left: 118, borderRadius: 14, borderWidth: 1,\n      paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, elevation: 5,\n    },\n    dvTripFare: { fontSize: 17, fontWeight: '900' },\n    dvMoreBtn: { flexDirection: 'column', alignItems: 'center', gap: 1, borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e4 },\n    dvTripMore: {\n      position: 'absolute', bottom: 172, right: 14, left: 118, borderRadius: radios.md, borderWidth: 1,\n      padding: espaciado.e8, gap: espaciado.e5, elevation: 5,\n    },\n    dvCancel: { width: 48, height: 48, borderRadius: 24, borderWidth: 1, alignItems: 'center', justifyContent: 'center', elevation: 5 },\n    dvMain: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, borderRadius: 20, paddingVertical: espaciado.e13, elevation: 6 },\n    dvMainText: { color: brand.white, fontSize: 14.5, fontWeight: '900' },\n    // P1: botón de perfil TRANSPARENTE abajo-derecha sobre el mapa (Home sheet)\n    homeFab: {\n      position: 'absolute', right: 14, width: 48, height: 48, borderRadius: 24,\n      borderWidth: 1.5, alignItems: 'center', justifyContent: 'center',\n      ...elevation.md,\n    },\n    heatChip: {\n      position: 'absolute', top: 10, alignSelf: 'center', borderRadius: radios.full,\n      paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, elevation: 5,\n    },\n    // ── Espera: radar de búsqueda DENTRO del mapa (transparente) ──\n    waitRadarWrap: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', paddingBottom: 60 },\n    waitRadarCard: {\n      alignItems: 'center', borderRadius: 22, borderWidth: 1, paddingHorizontal: espaciado.e22, paddingVertical: espaciado.e14,\n      backgroundColor: 'rgba(15,20,28,0.45)',\n    },\n    restPill: {\n      marginTop: espaciado.e14, borderRadius: radios.full, borderWidth: 1, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8,\n      backgroundColor: 'rgba(15,20,28,0.45)',\n    },\n    // ── Ruta: tarjetas A/B compactas y translúcidas + botones ──\n    dvCardA: {\n      position: 'absolute', bottom: 96, right: 14, left: 118, borderRadius: 14, borderWidth: 1,\n      paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, elevation: 5,\n    },\n    contactBtn: { width: 36, height: 36, borderRadius: 18, alignItems: 'center', justifyContent: 'center', elevation: 3 },\n  });\n\n// ── P2 DiDi: estilos de la tarjeta de SOLICITUD OSCURA (paleta fija, no sigue\n// el tema claro/oscuro de la app). El fondo/borde van inline sobre s.bottomCard. ──\nconst PK = StyleSheet.create({\n  countTxt: { color: 'rgba(255,255,255,0.85)', fontWeight: '700', fontSize: 15 },\n  paxRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e11, width: '100%' },\n  avatar: { width: 46, height: 46, borderRadius: 23, backgroundColor: brand.primary, alignItems: 'center', justifyContent: 'center' },\n  avatarTxt: { color: brand.white, fontSize: tipografia.title, fontWeight: '900' },\n  name: { color: brand.white, fontSize: 19, fontWeight: '900', flexShrink: 1 },\n  badgeGreen: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e3,\n    backgroundColor: 'rgba(43,194,106,0.16)', borderRadius: radios.full, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e2,\n  },\n  badgeGreenTxt: { color: brand.success, fontSize: 10.5, fontWeight: '800' },\n  badgeGray: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e3,\n    backgroundColor: 'rgba(255,255,255,0.10)', borderRadius: radios.full, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e2,\n  },\n  badgeGrayTxt: { color: 'rgba(255,255,255,0.6)', fontSize: 10.5, fontWeight: '700' },\n  metaTxt: { color: 'rgba(255,255,255,0.66)', fontSize: tipografia.caption, fontWeight: '600' },\n  vLine: { width: 2, height: 16, backgroundColor: 'rgba(255,255,255,0.18)', borderRadius: 1, marginVertical: 1 },\n});\n","/**\n * voice.ts — Locuciones del conductor con voz Qwen3 (DashScope) vía el proxy\n * del backend HK, con FALLBACK automático al TTS local del dispositivo.\n *\n * Flujo:\n *  1. POST /wallet/api/v1/tts/speak { text } (JWT inyectado por httpClient)\n *     → { token } (el servidor sintetiza UNA vez por frase y cachea 60 min).\n *  2. Reproducir https://hk.egrouteplan.com/wallet/api/v1/tts/audio/:token\n *     con expo-audio (MP3 streaming).\n *  3. Si la red falla o el backend no responde → Speech.speak es-ES local,\n *     el conductor nunca se queda sin indicación.\n *\n * Un único AudioPlayer reutilizado: si llega una frase nueva mientras suena\n * otra, replace() corta la anterior y arranca la nueva (maniobras secuenciales,\n * nunca solapadas). La voz se detiene al salir del Conductor (stopAllVoice).\n */\n\nimport { http } from './httpClient';\nimport { API_HOST } from './config';\nimport * as Speech from 'expo-speech';\nimport { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';\n\nlet cloudEnabled = true; // conmutable en runtime (pruebas)\nlet player: AudioPlayer | null = null;\n// Secuencia anti-solapamiento (auditoría 2026-09-08): las frases cloud son\n// ASÍNCRONAS — si llegan fuera de orden, una frase vieja podía pisar a la\n// nueva (o un fallback local sonaba DESPUÉS de la cloud). Solo se reproduce la\n// frase con el número de secuencia más reciente; las obsoletas se descartan.\nlet voiceSeq = 0;\n\n/** Habilita/deshabilita la voz cloud (no la local). */\nexport function setCloudVoiceEnabled(v: boolean) {\n  cloudEnabled = v;\n  if (!v) stopCloudVoice();\n}\nexport function isCloudVoiceEnabled() { return cloudEnabled; }\n\n/** Corta cualquier locución en curso (cloud o local). */\nexport function stopAllVoice() {\n  voiceSeq++; // invalida frases en vuelo (no reproducir lo pendiente)\n  try { player?.pause(); } catch { /* noop */ }\n  try { Speech.stop(); } catch { /* noop */ }\n}\n\nexport function stopCloudVoice() {\n  voiceSeq++;\n  try { player?.pause(); } catch { /* noop */ }\n}\n\n/**\n * Locución principal: intenta Qwen3 vía backend; ante cualquier error cae al\n * TTS local del dispositivo (es-ES). Nunca lanza. La secuencia garantiza que\n * si se pide una frase nueva mientras la anterior aún suena/vuela, gana la\n * NUEVA (sin \"copiarse\" con la versión anterior).\n */\nexport async function sayNavigation(text: string, opts: { forceLocal?: boolean } = {}): Promise<void> {\n  const seq = ++voiceSeq;\n  if (opts.forceLocal || !cloudEnabled) { sayLocal(text, seq); return; }\n  try {\n    const res = await http.post<{ token?: string }>('/tts/speak', { text }, true);\n    if (seq !== voiceSeq) return;              // llegó una frase más nueva → descartar\n    const token = res?.token;\n    if (!token) throw new Error('respuesta sin token');\n    const url = `${API_HOST}/wallet/api/v1/tts/audio/${encodeURIComponent(token)}`;\n    await playUrl(url, seq);\n  } catch (e) {\n    if (seq !== voiceSeq) return;\n    if (__DEV__) console.warn(`[voice] cloud fallo → TTS local: ${(e as Error).message}`);\n    sayLocal(text, seq);\n  }\n}\n\n/** Reproduce una URL MP3 solo si sigue siendo la frase más reciente. */\nasync function playUrl(url: string, seq: number): Promise<void> {\n  try {\n    await setAudioModeAsync({ playsInSilentMode: true, interruptionModeAndroid: 'duckOthers' });\n    if (seq !== voiceSeq) return;\n    if (!player) {\n      player = createAudioPlayer({ uri: url });\n    } else {\n      player.replace({ uri: url, headers: { 'Cache-Control': 'public' } });\n    }\n    player.play();\n  } catch (e) {\n    throw new Error(`reproducción: ${(e as Error).message}`);\n  }\n}\n\n/** Voz LOCAL del dispositivo (fallback / sin datos): expo-speech es-ES. */\nfunction sayLocal(text: string, seq: number): void {\n  try {\n    Speech.stop();\n    if (seq !== voiceSeq) return;\n    Speech.speak(text, { language: 'es-ES', rate: 0.95 });\n  } catch { /* motor de voz no disponible */ }\n}\n","import { UnavailabilityError } from 'expo-modules-core';\nimport ExponentSpeech from './ExponentSpeech';\nimport { VoiceQuality } from './Speech.types';\nexport { VoiceQuality };\nconst _CALLBACKS = {};\nlet _nextCallbackId = 1;\nlet _didSetListeners = false;\nfunction _makeCallbackId() {\n    return String(_nextCallbackId++);\n}\nfunction _unregisterListenersIfNeeded() {\n    if (Object.keys(_CALLBACKS).length === 0) {\n        removeSpeakingListener('Exponent.speakingStarted');\n        removeSpeakingListener('Exponent.speakingWillSayNextString');\n        removeSpeakingListener('Exponent.speakingDone');\n        removeSpeakingListener('Exponent.speakingStopped');\n        removeSpeakingListener('Exponent.speakingError');\n        _didSetListeners = false;\n    }\n}\nfunction _registerListenersIfNeeded() {\n    if (_didSetListeners)\n        return;\n    _didSetListeners = true;\n    setSpeakingListener('Exponent.speakingStarted', ({ id }) => {\n        const options = _CALLBACKS[id];\n        if (options && options.onStart) {\n            options.onStart();\n        }\n    });\n    setSpeakingListener('Exponent.speakingWillSayNextString', ({ id, charIndex, charLength }) => {\n        const options = _CALLBACKS[id];\n        if (options && options.onBoundary) {\n            // @ts-expect-error TODO(cedric): type is `SpeechEventCallback` while it should be `NativeBoundaryEventCallback` in this context, resulting in errors around `this` context\n            options.onBoundary({\n                charIndex,\n                charLength,\n            });\n        }\n    });\n    setSpeakingListener('Exponent.speakingDone', ({ id }) => {\n        const options = _CALLBACKS[id];\n        if (options && options.onDone) {\n            options.onDone();\n        }\n        delete _CALLBACKS[id];\n        _unregisterListenersIfNeeded();\n    });\n    setSpeakingListener('Exponent.speakingStopped', ({ id }) => {\n        const options = _CALLBACKS[id];\n        if (options && options.onStopped) {\n            options.onStopped();\n        }\n        delete _CALLBACKS[id];\n        _unregisterListenersIfNeeded();\n    });\n    // @ts-expect-error TODO(cedric): Android does not provide the `error` parameter for the `speakingError` event, while iOS never uses this event at all\n    setSpeakingListener('Exponent.speakingError', ({ id, error }) => {\n        const options = _CALLBACKS[id];\n        if (options && options.onError) {\n            options.onError(new Error(error));\n        }\n        delete _CALLBACKS[id];\n        _unregisterListenersIfNeeded();\n    });\n}\n// @needsAudit\n/**\n * Speak out loud the text given options. Calling this when another text is being spoken adds\n * an utterance to queue.\n * @param text The text to be spoken. Cannot be longer than [`Speech.maxSpeechInputLength`](#speechmaxspeechinputlength).\n * @param options A `SpeechOptions` object.\n */\nexport function speak(text, options = {}) {\n    const id = _makeCallbackId();\n    _CALLBACKS[id] = options;\n    _registerListenersIfNeeded();\n    ExponentSpeech.speak(String(id), text, options);\n}\n// @needsAudit\n/**\n * Returns list of all available voices.\n * @return List of `Voice` objects.\n */\nexport async function getAvailableVoicesAsync() {\n    if (!ExponentSpeech.getVoices) {\n        throw new UnavailabilityError('Speech', 'getVoices');\n    }\n    return ExponentSpeech.getVoices();\n}\n//@needsAudit\n/**\n * Determine whether the Text-to-speech utility is currently speaking. Will return `true` if speaker\n * is paused.\n * @return Returns a Promise that fulfils with a boole