unction setAudioModeAsync(mode) {\n    const audioMode = Platform.OS === 'ios'\n        ? mode\n        : {\n            shouldPlayInBackground: mode.shouldPlayInBackground,\n            shouldRouteThroughEarpiece: mode.shouldRouteThroughEarpiece,\n            interruptionMode: mode.interruptionModeAndroid,\n        };\n    return await AudioModule.setAudioModeAsync(audioMode);\n}\n// @docsMissing\nexport async function requestRecordingPermissionsAsync() {\n    return await AudioModule.requestRecordingPermissionsAsync();\n}\n// @docsMissing\nexport async function getRecordingPermissionsAsync() {\n    return await AudioModule.getRecordingPermissionsAsync();\n}\nexport { AudioModule };\n//# sourceMappingURL=ExpoAudio.js.map","import { requireNativeModule } from 'expo-modules-core';\n/**\n * @hidden\n */\nexport default requireNativeModule('ExpoAudio');\n//# sourceMappingURL=AudioModule.js.map","import { Platform } from 'expo-modules-core';\nexport function createRecordingOptions(options) {\n    let commonOptions = {\n        extension: options.extension,\n        sampleRate: options.sampleRate,\n        numberOfChannels: options.numberOfChannels,\n        bitRate: options.bitRate,\n        isMeteringEnabled: options.isMeteringEnabled ?? false,\n    };\n    if (Platform.OS === 'ios') {\n        commonOptions = {\n            ...commonOptions,\n            ...options.ios,\n        };\n    }\n    else if (Platform.OS === 'android') {\n        commonOptions = {\n            ...commonOptions,\n            ...options.android,\n        };\n    }\n    return commonOptions;\n}\n//# sourceMappingURL=options.js.map","import resolveAssetSource from './resolveAssetSource';\nexport function resolveSource(source) {\n    if (typeof source === 'string') {\n        return { uri: source };\n    }\n    if (typeof source === 'number') {\n        return resolveAssetSource(source);\n    }\n    return source ?? null;\n}\n//# sourceMappingURL=resolveSource.js.map","import resolveAssetSource f