n *   ios: {\n *     outputFormat: IOSOutputFormat.MPEG4AAC,\n *     audioQuality: AudioQuality.MAX,\n *     linearPCMBitDepth: 16,\n *     linearPCMIsBigEndian: false,\n *     linearPCMIsFloat: false,\n *   },\n *   web: {\n *     mimeType: 'audio/webm',\n *     bitsPerSecond: 128000,\n *   },\n * };\n * ```\n *\n * # `LOW_QUALITY`\n * ```ts\n * RecordingPresets.LOW_QUALITY = {\n *   extension: '.m4a',\n *   sampleRate: 44100,\n *   numberOfChannels: 2,\n *   bitRate: 64000,\n *   android: {\n *     extension: '.3gp',\n *     outputFormat: '3gp',\n *     audioEncoder: 'amr_nb',\n *   },\n *   ios: {\n *     audioQuality: AudioQuality.MIN,\n *     outputFormat: IOSOutputFormat.MPEG4AAC,\n *     linearPCMBitDepth: 16,\n *     linearPCMIsBigEndian: false,\n *     linearPCMIsFloat: false,\n *   },\n *   web: {\n *     mimeType: 'audio/webm',\n *     bitsPerSecond: 128000,\n *   },\n * };\n * ```\n */\nexport const RecordingPresets = {\n    HIGH_QUALITY,\n    LOW_QUALITY,\n};\n//# sourceMappingURL=RecordingConstants.js.map","/**\n * EmergencyModal — acción rápida de emergencia: marcación directa a\n * Policía / Hospital / Taxi de emergencia (Linking tel:).\n * Todo el componente usa el ROJO crítico (#F53F3F) según la semántica estricta.\n */\n\nimport React from 'react';\nimport { espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\nimport { Linking, Modal, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { Siren, Phone, X, type LucideIcon } from 'lucide-react-native';\nimport { EMERGENCY_CONTACTS, type EmergencyContact } from '../constants/data';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\n\nconst ICONS: Record<EmergencyContact['id'], LucideIcon> = {\n  policia: Siren,\n  hospital: Phone,\n};\n\nexport default function EmergencyModal({\n  visible,\n  onClose,\n}: {\n  visible: boolean;\n  onClose: () => void;\n}) {\n  const { colors } = useTheme();\n\n  const dial = (number: string) => {\n    Linking.openURL(`tel:${number}`).catch(() => {});\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <View style={[styles.backdrop, { backgroundColor: colors.overlay }]}>\n        <View style={[styles.card, { backgroundColor: colors.card }]}>\n          {/* Cabecera crítica */}\n          <View style={styles.header}>\n            <View style={[styles.sirenWrap, { backgroundColor: alpha(colors.danger, 0.12) }]}>\n              <Siren size={22} color={colors.danger} strokeWidth={2.2} />\n            </View>\n            <View style={styles.headerText}>\n              <Text style={[styles.title, { color: colors.danger }]}>Emergencia</Text>\n              <Text style={[styles.subtitle, { color: colors.textSecondary }]}>\n                Marcación directa · disponible 24/7\n              </Text>\n            </View>\n            <Pressable onPress={onClose} hitSlop={12} accessibilityLabel=\"Cerrar emergencia\">\n              <X size={20} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n\n          {/* Contactos de marcación directa */}\n          {EMERGENCY_CONTACTS.map((contact) => {\n            const Icon = ICONS[contact.id] ?? Phone;\n            return (\n              <Pressable\n                key={contact.id}\n                onPress={() => dial(contact.number)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Llamar a ${contact.label}, ${contact.number}`}\n                style={({ pressed }) => [\n                  styles.contactRow,\n                  {\n                    backgroundColor: pressed ? alpha(colors.danger, 0.08) : alpha(colors.danger, 0.04),\n                    borderColor: alpha(colors.danger, 0.25),\n                  },\n                ]}\n              >\n                <View style={[styles.contactIcon, { backgroundColor: alpha(colors.danger, 0.12) }]}>\n                  <Icon size={18} color={colors.danger} />\n                </View>\n                <View style={styles.contactText}>\n                  <Text style={[styles.contactLabel, { color: colors.textPrimary }]}>{contact.label}</Text>\n                  <Text style={[styles.contactNote, { color: colors.textSecondary }]}>{contact.note}</Text>\n                </View>\n                <Text style={[styles.contactNumber, { color: colors.danger }]}>{contact.number}</Text>\n              </Pressable>\n            );\n          })}\n\n          <Pressable\n            onPress={onClose}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Cancelar\"\n            style={({ pressed }) => [styles.cancelBtn, { backgroundColor: colors.surface, opacity: pressed ? 0.8 : 1 }]}\n          >\n            <Text style={[styles.cancelText, { color: colors.textSecondary }]}>Cancelar</Text>\n          </Pressable>\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { flex: 1, justifyContent: 'flex-end' },\n  card: {\n    borderTopLeftRadius: 26,\n    borderTopRightRadius: 26,\n    paddingHorizontal: espaciado.e20,\n    paddingTop: espaciado.e20,\n    paddingBottom: 34,\n  },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e16 },\n  sirenWrap: { width: 44, height: 44, borderRadius: radios.lg, alignItems: 'center', justifyContent: 'center' },\n  headerText: { flex: 1, marginLeft: espaciado.e12 },\n  title: { fontSize: 19, fontWeight: '800' },\n  subtitle: { fontSize: tipografia.caption, marginTop: espaciado.e2 },\n  contactRow: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    borderWidth: 1,\n    borderRadius: radios.lg,\n    padding: espaciado.e12,\n    marginBottom: espaciado.e10,\n  },\n  contactIcon: { width: 38, height: 38, borderRadius: 13, alignItems: 'center', justifyContent: 'center' },\n  contactText: { flex: 1, marginLeft: espaciado.e12 },\n  contactLabel: { fontSize: 14.5, fontWeight: '800' },\n  contactNote: { fontSize: tipografia.micro, marginTop: 1 },\n  contactNumber: { fontSize: 15, fontWeight: '800' },\n  cancelBtn: { marginTop: espaciado.e6, alignItems: 'center', paddingVertical: espaciado.e13, borderRadius: 14 },\n  cancelText: { fontSize: tipografia.body, fontWeight: '700' },\n});\n","/**\n * DriverHomeSheet — Home del conductor estilo DiDi (P1, aprobado 2026-09-08).\n * Bottom-sheet de 3 pestañas REUTILIZANDO las pantallas existentes:\n *  · FLUJO DIARIO: ganancias hoy/semana/mes + resumen por tipo + enlace al\n *    historial completo (/driver-profile: periodos con rating y puntuación).\n *  · VIDA: comida rápida y comercio con tarjetas horizontales con imagen.\n *  · PERFIL: tema, idioma (ES/FR/EN pendiente por fases, anotado), normas y\n *    términos, y CERRAR SESIÓN (SOLO aquí, fuera del header del conductor).\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Switch, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport {\n  BarChart3, ChevronRight, FileText, Globe, History, LogOut, Moon, ShieldCheck, ShoppingBag, Star,\n  UserRound, Utensils, Wallet,\n} from 'lucide-react-native';\nimport { alpha, elevation, espaciado, GhostButton, InlineError, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useSession } from '../state/session';\nimport { driverApi } from '../api/driver';\nimport { intercityApi } from '../api/intercity';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport type HomeTab = 'flujo' | 'vida' | 'perfil';\n\nconst TABS: Array<{ key: HomeTab; label: string; icon: any }> = [\n  { key: 'flujo', label: 'Flujo diario', icon: BarChart3 },\n  { key: 'vida', label: 'Vida', icon: Utensils },\n  { key: 'perfil', label: 'Perfil', icon: UserRound },\n];\n\nconst PERIODS = [\n  { key: 'today', label: 'Hoy' },\n  { key: 'week', label: 'Semana' },\n  { key: 'month', label: 'Mes' },\n  { key: 'all', label: 'Total' },\n] as const;\n\nconst xaf = (n: number | null | undefined) => `${Number(n || 0).toLocaleString('es')} XAF`;\n\nexport default function DriverHomeSheet({ visible, tab, onClose }: {\n  visible: boolean; tab: HomeTab; onClose: () => void;\n}) {\n  const { colors, isDark, setMode } = useTheme();\n  const router = useRouter();\n  const { logout } = useSession();\n  const [activeTab, setActiveTab] = useState<HomeTab>(tab);\n  const [period, setPeriod] = useState<'today' | 'week' | 'month' | 'all'>('today');\n  const [earnings, setEarnings] = useState<Awaited<ReturnType<typeof intercityApi.earnings>> | null>(null);\n  const [loadingE, setLoadingE] = useState(false);\n  const [errE, setErrE] = useState<string | null>(null);\n  const [driver, setDriver] = useState<{ phone?: string; rating?: number; ratingCount?: number }>({});\n  const [rulesOpen, setRulesOpen] = useState(false);\n\n  useEffect(() => { if (visible) setActiveTab(tab); }, [visible, tab]);\n\n  const loadEarnings = useCallback(async () => {\n    setLoadingE(true); setErrE(null);\n    try {\n      const [e, st] = await Promise.all([intercityApi.earnings(period), driverApi.status()]);\n      setEarnings(e);\n      setDriver({\n        rating: Number((st.driver as any)?.rating_avg) || 0,\n        ratingCount: Number((st.driver as any)?.rating_count) || 0,\n      });\n    } catch (e2) {\n      setErrE(e2 instanceof Error ? e2.message : 'No se pudieron cargar las ganancias');\n    } finally { setLoadingE(false); }\n  }, [period]);\n\n  useEffect(() => { if (visible && activeTab === 'flujo') loadEarnings(); }, [visible, activeTab, loadEarnings]);\n\n  const handleLogout = async () => { await logout(); router.replace('/'); };\n\n  const drRating = driver.rating ?? 0;\n  const s = dhStyles(colors);\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose}>\n      <View style={dh.overlay}>\n        <Pressable style={dh.backdrop} onPress={onClose} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar\" />\n        <View style={[s.sheet, { backgroundColor: colors.background, borderColor: colors.border }]}>\n          {/* Manija */}\n          <View style={[dh.handle, { backgroundColor: colors.border }]} />\n\n          {/* Pestañas */}\n          <View style={[s.tabs, { backgroundColor: alpha(colors.border, 0.28) }]}>\n            {TABS.map((t) => {\n              const Icon = t.icon;\n              const on = activeTab === t.key;\n              return (\n                <Pressable key={t.key} onPress={() => setActiveTab(t.key)} accessibilityRole=\"button\" accessibilityState={{ selected: on }} style={[s.tab, on && { backgroundColor: colors.card, borderColor: colors.primary, borderWidth: 1 }]}>\n                  <Icon size={16} color={on ? colors.primary : colors.textSecondary} />\n                  <Text style={{ color: on ? colors.primary : colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }} numberOfLines={1}>{t.label}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n\n          <ScrollView contentContainerStyle={dh.content} showsVerticalScrollIndicator={false}>\n            {/* ── FLUJO DIARIO ─────────────────────────────────────────── */}\n            {activeTab === 'flujo' && (\n              <View style={{ gap: espaciado.e12 }}>\n                <View style={[s.card, { borderColor: colors.border, gap: espaciado.e10 }]}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n                    <Wallet size={18} color={colors.primary} />\n                    <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle }}>Ganancias</Text>\n                  </View>\n                  <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n                    {PERIODS.map((p) => (\n                      <Pressable key={p.key} onPress={() => setPeriod(p.key)} style={[s.chip, { flex: 1, borderColor: period === p.key ? colors.primary : colors.border, backgroundColor: period === p.key ? alpha(colors.primary, 0.08) : 'transparent' }]}>\n                        <Text style={{ color: period === p.key ? colors.primary : colors.textSecondary, fontWeight: '800', fontSize: tipografia.caption }}>{p.label}</Text>\n                      </Pressable>\n                    ))}\n                  </View>\n                  {loadingE && <ActivityIndicator color={colors.primary} />}\n                  {errE ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={errE} /></View> : null}\n                  {!loadingE && !errE && earnings && (\n                    <>\n                      <View style={{ alignItems: 'center', gap: espaciado.e2 }}>\n                        <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700' }}>NETO ({period === 'all' ? 'total' : period})</Text>\n                        <Text style={{ color: colors.success, fontSize: 30, fontWeight: '900' }}>{xaf(earnings.totalNet)}</Text>\n                      </View>\n                      <View style={[s.statRow, { backgroundColor: alpha(colors.border, 0.2) }]}>\n                        <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>🚕 Taxi ciudad</Text>\n                        <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.body }}>{earnings.city.trips} viajes · {xaf(earnings.city.net)}</Text>\n                      </View>\n                      <View style={[s.statRow, { backgroundColor: alpha(colors.border, 0.2) }]}>\n                        <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>🚌 Ciudad a Ciudad</Text>\n                        <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.body }}>{earnings.intercity.bookings} reservas · {xaf(earnings.intercity.gross)}</Text>\n                      </View>\n                    </>\n                  )}\n                  <GhostButton title=\"Historial completo y puntuación\" onPress={() => { onClose(); router.push('/driver-profile' as any); }} />\n                  {/* P6: historial de viajes del conductor (taxi) */}\n                  <Pressable\n                    onPress={() => { onClose(); router.push('/trips-history' as any); }}\n                    style={[s.linkRow, { borderColor: colors.border }]}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Historial de viajes\"\n                  >\n                    <History size={16} color={colors.primary} />\n                    <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body }}>Historial de viajes</Text>\n                    <ChevronRight size={16} color={colors.textSecondary} style={{ marginLeft: 'auto' }} />\n                  </Pressable>\n                </View>\n\n                {/* Resumen de puntuación (honesto: solo si hay valoraciones) */}\n                <View style={[s.card, { borderColor: colors.border, flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }]}>\n                  <View style={[dh.ratingBox, { backgroundColor: alpha(brand.warning, 0.14) }]}>\n                    <Star size={22} color={brand.warning} fill={brand.warning} />\n                  </View>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>Puntuación</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: 1 }}>\n                      {drRating > 0\n                        ? `${drRating.toFixed(1)} ★ · ${driver.ratingCount} valoración(es)`\n                        : 'Aún no tienes valoraciones suficientes.'}\n                    </Text>\n                  </View>\n                  {drRating > 0 && <Text style={{ color: colors.textPrimary, fontSize: 26, fontWeight: '900' }}>{drRating.toFixed(1)}</Text>}\n                </View>\n              </View>\n            )}\n\n            {/* ── VIDA: comida y comercio (tarjetas con imagen) ─────────── */}\n            {activeTab === 'vida' && (\n              <View style={{ gap: espaciado.e12 }}>\n                <Pressable onPress={() => { onClose(); router.push('/food' as any); }} style={[s.vidaCard, { backgroundColor: brand.secondary }]}>\n                  <View style={dh.vidaTextWrap}>\n                    <Text style={dh.vidaTitle}>🍔 Comida Rápida</Text>\n                    <Text style={dh.vidaSub}>Restaurantes y pedidos en tu ciudad</Text>\n                    <Text style={dh.vidaCta}>Ver restaurantes →</Text>\n                  </View>\n                  <View style={[dh.vidaArt, { backgroundColor: 'rgba(255,255,255,0.16)' }]}>\n                    <Utensils size={40} color={brand.white} />\n                  </View>\n                </Pressable>\n                <Pressable onPress={() => { onClose(); router.push('/ecomerse' as any); }} style={[s.vidaCard, { backgroundColor: '#8B5CF6' }]}>\n                  <View style={dh.vidaTextWrap}>\n                    <Text style={dh.vidaTitle}>🛍️ Ecomerse</Text>\n                    <Text style={dh.vidaSub}>Tiendas y productos de comercio</Text>\n                    <Text style={dh.vidaCta}>Ver tiendas →</Text>\n                  </View>\n                  <View style={[dh.vidaArt, { backgroundColor: 'rgba(255,255,255,0.16)' }]}>\n                    <ShoppingBag size={40} color={brand.white} />\n                  </View>\n                </Pressable>\n                <Pressable onPress={() => { onClose(); router.push('/food' as any); }} style={[s.vidaRow, { borderColor: colors.border }]}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>😋 Ver pedidos recientes de comida</Text>\n                  <ChevronRight size={16} color={colors.textSecondary} />\n                </Pressable>\n              </View>\n            )}\n\n            {/* ── PERFIL: tema · idioma · normas · logout SOLO aquí ─────── */}\n            {activeTab === 'perfil' && (\n              <View style={{ gap: espaciado.e12 }}>\n                <View style={[s.card, { borderColor: colors.border, gap: 0 }]}>\n                  <View style={[dh.row, { borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.border }]}>\n                    <Moon size={18} color={colors.primary} />\n                    <Text style={{ flex: 1, color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Tema oscuro</Text>\n                    <Switch value={isDark} onValueChange={(v) => setMode(v ? 'dark' : 'light')} trackColor={{ true: colors.primary }} />\n                  </View>\n                  <View style={[dh.row, { borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.border }]}>\n                    <Globe size={18} color={colors.primary} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Idioma</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>Español (Guinea Ecuatorial) · ES/FR/EN pendiente por fases</Text>\n                    </View>\n                    <ChevronRight size={16} color={colors.textSecondary} />\n                  </View>\n                  <Pressable onPress={() => setRulesOpen((v) => !v)} accessibilityRole=\"button\" style={dh.row}>\n                    <FileText size={18} color={colors.primary} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Normas y términos</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>{rulesOpen ? 'Toca para ocultar' : 'Toca para leer las normas de la comunidad'}</Text>\n                    </View>\n                    <ChevronRight size={16} color={colors.textSecondary} />\n                  </Pressable>\n                  {rulesOpen && (\n                    <View style={{ padding: espaciado.e12, gap: espaciado.e6 }}>\n                      {[\n                        'Conduce con respeto y prudencia: la seguridad del pasajero es lo primero.',\n                        'Respeta la tarifa de la app (algoritmo o presupuesto del pasajero): es el precio final.',\n                        'Al terminar un viaje en efectivo confirma SIEMPRE que recibiste el dinero.',\n                        'No fumes ni pidas pagos fuera de la app dentro del viaje.',\n                        'En emergencias usa el botón de alerta: marca directamente al 24/7.',\n                        'Mantén tus documentos de conductor al día (aviso automático de caducidad).',\n                      ].map((r) => (\n                        <Text key={r} style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', lineHeight: 18 }}>• {r}</Text>\n                      ))}\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600', marginTop: espaciado.e4 }}>\n                        Al usar EG Route Plan como conductor aceptas estos términos (versión v1.0).\n                      </Text>\n                    </View>\n                  )}\n                </View>\n\n                <View style={[s.card, { borderColor: colors.border, gap: espaciado.e6 }]}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n                    <ShieldCheck size={18} color={colors.primary} />\n                    <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Conductor verificado</Text>\n                  </View>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                    Tu cuenta de conductor está activa{drRating > 0 ? ` con ${drRating.toFixed(1)} ★` : ''}.\n                  </Text>\n                </View>\n\n                <Pressable onPress={handleLogout} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar sesión\" style={[s.card, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06), flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }]}>\n                  <LogOut size={18} color={colors.danger} />\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.danger, fontWeight: '900', fontSize: 15 }}>Cerrar sesión</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>Solo desde aquí (por seguridad)</Text>\n                  </View>\n                  <ChevronRight size={16} color={colors.danger} />\n                </Pressable>\n              </View>\n            )}\n\n            {activeTab === 'perfil' && <Text style={{ color: colors.textSecondary, fontSize: 10.5, textAlign: 'center', fontWeight: '600' }}>EG Route Plan · Conductor · v1.0.0</Text>}\n          </ScrollView>\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\nconst dh = StyleSheet.create({\n  overlay: { flex: 1, justifyContent: 'flex-end' },\n  backdrop: { ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(0,0,0,0.35)' },\n  handle: { width: 44, height: 5, borderRadius: 3, alignSelf: 'center', marginTop: espaciado.e10, marginBottom: espaciado.e4 },\n  content: { padding: espaciado.e16, paddingBottom: 36, gap: espaciado.e12 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingVertical: espaciado.e13 },\n  ratingBox: { width: 44, height: 44, borderRadius: 22, alignItems: 'center', justifyContent: 'center' },\n  vidaTextWrap: { flex: 1, gap: espaciado.e2 },\n  vidaTitle: { color: brand.white, fontSize: 21, fontWeight: '900' },\n  vidaSub: { color: 'rgba(255,255,255,0.85)', fontSize: tipografia.caption, fontWeight: '600' },\n  vidaCta: { color: brand.white, fontSize: tipografia.caption, fontWeight: '800', marginTop: espaciado.e6, textDecorationLine: 'underline' },\n  vidaArt: { width: 72, height: 72, borderRadius: 20, alignItems: 'center', justifyContent: 'center' },\n});\n\nconst dhStyles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    sheet: {\n      borderTopLeftRadius: 26, borderTopRightRadius: 26, borderWidth: 1,\n      maxHeight: '86%', minHeight: 240,\n      ...elevation.lg,\n    },\n    tabs: { flexDirection: 'row', gap: espaciado.e8, marginHorizontal: espaciado.e16, marginTop: espaciado.e8, borderRadius: 14, padding: espaciado.e5 },\n    tab: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, borderRadius: 10, paddingVertical: espaciado.e9 },\n    card: { borderRadius: radios.lg, borderWidth: 1.5, padding: espaciado.e14 },\n    chip: { borderRadius: 10, borderWidth: 1.5, paddingVertical: espaciado.e7, alignItems: 'center' },\n    statRow: { flexDirection: 'row', justifyContent: 'space-between', borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9 },\n    linkRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e12 },\n    vidaCard: {\n      borderRadius: 20, padding: espaciado.e18, flexDirection: 'row', alignItems: 'center', gap: espaciado.e14,\n      ...elevation.md,\n    },\n    vidaRow: { borderRadius: 14, borderWidth: 1.5, padding: espaciado.e13, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },\n  });\n","/**\n * Cliente del servicio Ciudad a Ciudad (intercity) — backend unificado.\n * ⚠️ Base ABSOLUTA: el intercity vive en /api/intercity/* (no bajo /wallet/api/v1).\n * Endpoints públicos: locations, routes, trips, fotos · Autenticados: publicar,\n * mis viajes, estados, edición, reservas (idempotentes), cancelaciones, pago,\n * tarifa y earnings (ganancias del conductor).\n */\n\nimport { http, httpRequest } from './httpClient';\n\nimport { API_HOST } from './config';\nexport const IC_API_BASE = `${API_HOST}/api`;\nconst ic = (p: string) => `${IC_API_BASE}${p}`;\n\nexport interface IcLocation { province: string; district: string; zone: string; }\nexport interface IcRoute {\n  id: string; originCity: string; destinationCity: string;\n  originProvince?: string; originDistrict?: string; originZone?: string;\n  destinationProvince?: string; destinationDistrict?: string; destinationZone?: string;\n  basePrice: string; currency: string; isActive: boolean;\n}\nexport const IC_VEHICLE_TYPES = ['car', 'van', 'minibus', 'truck'] as const;\nexport type IcVehicleType = (typeof IC_VEHICLE_TYPES)[number];\nexport const IC_VEHICLE_LABELS: Record<string, string> = { car: 'Coche', van: 'Furgoneta', minibus: 'Minibús', truck: 'Camión' };\n\nexport interface IcTrip {\n  id: string; routeId: string; vehiclePlate?: string; vehicleModel?: string;\n  vehicleType?: string; rentalPrice?: string | null;\n  totalSeats: number; availableSeats: number; price: string; currency: string;\n  status: string; departureTime: string; arrivalTime?: string;\n  publisherName?: string | null; publisherPhoto?: string | null; route?: IcRoute;\n  publisherBadge?: string | null; priority?: number;\n  photos?: string[];\n  bookings?: Array<{ id: string; seatCount: number; totalPrice?: string | null; status: string; fareStatus: string; paymentStatus: string; payOn?: string; buyerName?: string | null; buyerPhone?: string | null; passenger?: { firstName: string; lastName: string; phone: string } }>;\n}\nexport interface IcBooking {\n  id: string; tripId: string; seatCount: number; totalPrice: string;\n  ticketQrCode: string; shortCode?: string | null; status: string; pickupType: string; pickupAddress?: string;\n  fareStatus: string; paymentStatus: string; payOn?: string;\n  buyerName?: string | null; buyerPhone?: string | null;\n}\n\nexport interface IcTicket {\n  id: string; tripId: string; seatCount: number; totalPrice: string;\n  ticketQrCode: string; shortCode?: string | null; status: string; pickupType: string; pickupAddress?: string;\n  fareStatus: string; paymentStatus: string; payOn?: string;\n  buyerName?: string | null; buyerPhone?: string | null;\n  passenger?: { firstName: string; lastName: string; phone: string };\n  trip?: { id: string; departureTime: string; status: string; price: string; route?: IcRoute };\n}\nexport interface DriverEarnings {\n  period: string;\n  totalGross: number;\n  totalNet: number;\n  city: { gross: number; net: number; trips: number };\n  intercity: { gross: number; bookings: number; pendingCollection: number };\n  commissionDebt?: { pendingXaf: number; entries: number; rateBps: number };\n}\n\nexport interface IcPlan {\n  planCode: string; planName: string; monthlyTrips: number; // -1 = ilimitado\n  monthlyUsed: number; expiresAt: string | null; publisherType: 'driver' | 'agent';\n}\n\nexport const intercityApi = {\n  locations: () => http.get<IcLocation[]>(ic('/intercity/locations'), false),\n  routes: (q: Record<string, string> = {}) => {\n    const qs = new URLSearchParams(q).toString();\n    return http.get<IcRoute[]>(ic(`/intercity/routes${qs ? '?' + qs : ''}`), false);\n  },\n  trips: (routeId?: string, date?: string, vehicleType?: string) => {\n    const p: Record<string, string> = {};\n    if (routeId) p.routeId = routeId;\n    if (date) p.date = date;\n    if (vehicleType) p.vehicleType = vehicleType;\n    const qs = new URLSearchParams(p).toString();\n    return http.get<IcTrip[]>(ic(`/intercity/trips${qs ? '?' + qs : ''}`), false);\n  },\n  publish: (body: {\n    origin: IcLocation; destination: IcLocation;\n    departureTime?: string; departureDays?: string[]; departureTimeOfDay?: string;\n    seats: number; price: number; vehiclePlate?: string; vehicleModel?: string;\n    vehicleType?: string; rentalPrice?: number; photos?: string[];\n  }) => http.post<{ message: string; trips: IcTrip[] }>(ic('/intercity/trips'), body, true),\n  updateTrip: (tripId: string, body: {\n    price?: number; seats?: number; rentalPrice?: number | null;\n    vehiclePlate?: string; vehicleModel?: string; vehicleType?: string; departureTime?: string;\n  }) => http.put<{ message: string; trip: IcTrip }>(ic(`/intercity/trips/${tripId}`), body, true),\n  addTripPhotos: (tripId: string, photos: string[]) =>\n    http.post<{ message: string; photos: string[] }>(ic(`/intercity/trips/${tripId}/photos`), { photos }, true),\n  myTrips: () => http.get<IcTrip[]>(ic('/intercity/trips/mine'), true),\n  myPlan: () => http.get<IcPlan>(ic('/intercity/me/plan'), true),\n  tripStatus: (tripId: string, status: string) =>\n    http.put<{ message: string }>(ic(`/intercity/trips/${tripId}/status`), { status }, true),\n  cancelTrip: (tripId: string) =>\n    http.put<{ message: string }>(ic(`/intercity/trips/${tripId}/cancel`), {}, true),\n  book: (body: {\n    tripId: string; seatCount: number;\n    passenger: { firstName: string; lastName: string; phone: string; nationalityType: string; documentType: string; documentNumber: string; isMinor?: boolean; minorCount?: number; guardianId?: string; guardianName?: string; specialNeeds?: string };\n    pickupType?: string; pickupAddress?: string; passengerFare?: number; rental?: boolean; payOn?: 'boarding' | 'destination';\n  }, idemKey?: string) => httpRequestWithIdem<{ booking: IcBooking; ticketQrCode: string; message: string; fareStatus: string }>(ic('/intercity/bookings'), body, idemKey),\n  cancelBooking: (bookingId: string) =>\n    http.put<{ message: string }>(ic(`/intercity/bookings/${bookingId}/cancel`), {}, true),\n  /** Mis tickets: como comprador o como viajero. */\n  myBookings: () => http.get<IcTicket[]>(ic('/intercity/bookings/mine'), true),\n  markPaid: (bookingId: string) =>\n    http.put<{ message: string }>(ic(`/intercity/bookings/${bookingId}/paid`), {}, true),\n  decideFare: (bookingId: string, action: 'accept' | 'decline') =>\n    http.put<{ message: string }>(ic(`/intercity/bookings/${bookingId}/fare`), { action }, true),\n  /** Ganancias del conductor (ciudad + intercity). period: today|week|month|all. */\n  earnings: (period = 'all') =>\n    http.get<DriverEarnings>(ic(`/intercity/driver/earnings?period=${period}`), true),\n};\n\nasync function httpRequestWithIdem<T>(path: string, body: unknown, idemKey?: string): Promise<T> {\n  return httpRequest<T>(path, {\n    method: 'POST',\n    body,\n    headers: idemKey ? { 'Idempotency-Key': idemKey } : undefined,\n  });\n}\n","/**\n * Cliente de taxi unificado (backend NestJS /wallet/api/v1/mobility).\n * Modalidades con algoritmo de precios + pedir viaje + conductor.\n */\n\nimport { http } from './httpClient';\n\nexport interface TaxiMode {\n  id: string;\n  label: string;\n  icon: string;\n  price: number;\n  etaMin: number;\n}\n\nexport interface TaxiTripPayload {\n  pickupLat: number;\n  pickupLng: number;\n  pickupAddress?: string;\n  dropoffLat: number;\n  dropoffLng: number;\n  dropoffAddress?: string;\n  zoneType?: string;\n  requestedPrice?: number;   // presupuesto elegido por el pasajero\n  algorithmPrice?: number;   // precio del algoritmo (modalidad)\n  modality?: string;\n  isPool?: boolean;\n  maxPoolSeats?: number;\n  passengers?: number;       // nº de pasajeros (1–6)\n  city?: string;             // P1-c: 'Malabo' | 'Bata' — la comisión del viaje es por ciudad\n}\n\nexport const taxiApi = {\n  /** Modalidades con el precio del algoritmo (según ciudad y distancia OSRM). */\n  modes: (city = 'Malabo', distanceKm = 0) =>\n    http.get<{ modes: TaxiMode[] }>(`/mobility/fares/taxi/modes?city=${encodeURIComponent(city)}&distanceKm=${distanceKm}`, false),\n\n  /** Pedir taxi (requiere sesión). */\n  createTrip: (body: TaxiTripPayload) =>\n    http.post<{ id: string; status: string }>('/mobility/trips', body, true),\n\n  /** Estado del viaje (polling del pasajero). */\n  getTrip: (id: string) =>\n    http.get<Record<string, unknown>>(`/mobility/trips/${id}`, true),\n\n  /** Viaje ACTIVO del pasajero (requested/accepted/in_progress) para reanudar\n   *  tras cerrar la app o desde la tarjeta del Perfil. null si no hay. */\n  activeTrip: () =>\n    http.get<Record<string, unknown> | null>('/mobility/trips/active', true),\n\n  /** Solicitudes abiertas + propias (panel del conductor). */\n  driverTrips: () =>\n    http.get<unknown[]>('/mobility/trips/driver', true),\n\n  /** El conductor acepta y elige el precio (final_price). */\n  acceptTrip: (id: string, price?: number) =>\n    http.post<Record<string, unknown>>(`/mobility/trips/${id}/accept`, price != null ? { price } : {}, true),\n\n  /** El conductor avanza estados: in_progress → completed / cancelled.\n   *  P4: cashConfirmed=false al completar ⇒ el servidor BLOQUEA al conductor\n   *  hasta que confirme el cobro (confirmCash). */\n  updateStatus: (id: string, status: 'in_progress' | 'completed' | 'cancelled', cashConfirmed?: boolean) =>\n    http.put<Record<string, unknown>>(`/mobility/trips/${id}/status`, { status, ...(cashConfirmed !== undefined ? { cashConfirmed } : {}) }, true),\n\n  /** P4: el conductor confirma que SÍ cobró el viaje en efectivo → desbloqueo. */\n  confirmCash: (id: string) =>\n    http.post<{ unblocked: boolean; trip?: string }>(`/mobility/trips/${id}/confirm-cash`, {}, true),\n\n  /** Heartbeat del conductor: posición en vivo para que el pasajero lo vea. */\n  reportLocation: (id: string, lat: number, lng: number) =>\n    http.post<{ id: string; driver_lat: number; driver_lng: number }>(\n      `/mobility/trips/${id}/location`, { lat, lng }, true,\n    ),\n\n  /** PASAJERO: rechaza al conductor asignado → el viaje vuelve a \"requested\"\n   *  y se sigue buscando otro conductor (flujo DiDi Fase 2). */\n  rejectDriver: (id: string) =>\n    http.post<{ id: string; status: string }>(`/mobility/trips/${id}/reject`, {}, true),\n\n  /** PASAJERO: cancela (\"rendirse\") antes de iniciar el viaje.\n   *  P1e: acepta el motivo (visible para el admin). */\n  cancelTrip: (id: string, reason?: string) =>\n    http.post<{ id: string; status: string; cancelledReason?: string | null }>(\n      `/mobility/trips/${id}/cancel`, reason ? { reason } : {}, true,\n    ),\n\n  /** P1e: el pasajero puntúa al conductor (1–5) tras completar el viaje. */\n  rateTrip: (id: string, score: number, comment?: string) =>\n    http.post<{ tripId: string; score: number; driverRatingAvg: number; driverRatingCount: number }>(\n      `/mobility/trips/${id}/rate`, { score, ...(comment ? { comment } : {}) }, true,\n    ),\n\n  /** P6: historial de viajes del usuario (conductor o pasajero, según rol). */\n  history: () =>\n    http.get<{ asDriver: boolean; trips: TripHistoryItem[] }>('/mobility/trips/history', true),\n};\n\nexport interface TripHistoryItem {\n  id: string;\n  status: 'completed' | 'cancelled';\n  pickup_address?: string | null;\n  dropoff_address?: string | null;\n  final_price?: string | null;\n  requested_price?: string | null;\n  modality?: string | null;\n  cancelled_reason?: string | null;\n  created_at: string;\n  accepted_at?: string | null;\n  started_at?: string | null;\n  completed_at?: string | null;\n  cancelled_at?: string | null;\n  counterpart_name?: string | null;\n  vehicle_plate?: string | null;\n  vehicle_model?: string | null;\n  my_rating?: number | null;\n  my_comment?: string | null;\n  rated_at?: string | null;\n  // P1-c: liquidación del viaje (viajes nuevos; los viejos vienen sin estas claves).\n  city?: string | null;\n  settlement_kind?: 'WALLET' | 'CASH' | null;\n  fee_info?: { fee?: number; scope?: string; city?: string } | null;\n  settlement?: {\n    kind?: string; fare?: number; fee?: number; net?: number;\n    fee_to_driver?: number; refunded?: number;\n    dispute?: { outcome?: string; note?: string; at?: string; resolved_at?: string };\n  } | null;\n  cancelled_by?: string | null;\n  disputed_at?: string | null;\n}\n","/**\n * Localización real (GPS) para acciones \"ubicarme ahora\" y modo navegación.\n * Regla de negocio: el GPS solo se usa si el dispositivo está DENTRO de Guinea\n * Ecuatorial (bbox). Fuera (p. ej. el dueño probando desde China) devolvemos\n * null y cada pantalla usa su fallback (dirección real de la ciudad activa).\n *\n * ⚠️ NUNCA bloquear el flujo del conductor por el GPS: estas funciones tienen\n * timeout. Si el permiso no está concedido o no hay fix en X ms → null.\n */\n\nimport * as Location from 'expo-location';\nimport { CITIES } from '../constants/data';\nimport { CITY_CENTERS } from '../constants/geo';\n\nexport type LocCoord = [number, number];\n\n/** Bounding box aproximado de Guinea Ecuatorial (incluye islas). */\nexport function isInsideGq(c: LocCoord): boolean {\n  return c[0] >= 5.0 && c[0] <= 11.6 && c[1] >= -1.7 && c[1] <= 4.2;\n}\n\n/** Ciudad (por nombre) más cercana a unas coordenadas, para etiquetas. */\nexport function nearestCityName(coord: LocCoord): string {\n  let best = '';\n  let bestD = Infinity;\n  for (const [id, c] of Object.entries(CITY_CENTERS)) {\n    const d = (c[0] - coord[0]) ** 2 + (c[1] - coord[1]) ** 2;\n    if (d < bestD) { bestD = d; best = id; }\n  }\n  return CITIES.find((c) => c.id === best)?.name ?? '';\n}\n\n/** Resuelve una promesa o devuelve `fallback` pasados `ms` (evita cuelgues). */\nfunction withTimeout<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {\n  return Promise.race([\n    p,\n    new Promise<T>((resolve) => setTimeout(() => resolve(fallback), ms)),\n  ]);\n}\n\n/** Posición GPS fresca si el permiso YA está concedido y hay fix en ≤timeoutMs.\n *  NO muestra el diálogo de permisos (flujo conductor: aceptar un viaje no\n *  puede quedar bloqueado por un diálogo de Android ni por falta de señal). */\nexport async function getGqPositionIfAllowed(timeoutMs = 2500): Promise<LocCoord | null> {\n  try {\n    const perm = await withTimeout(Location.getForegroundPermissionsAsync(), 1200, null);\n    if (!perm || perm.status !== 'granted') return null;\n    const p = await withTimeout(\n      Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced }),\n      timeoutMs,\n      null as never,\n    );\n    if (!p) return null;\n    const c: LocCoord = [p.coords.longitude, p.coords.latitude];\n    return isInsideGq(c) ? c : null;\n  } catch {\n    return null;\n  }\n}\n\n/**\n * Posición GPS FRESCA del dispositivo si está dentro de GQ; null si no hay\n * permiso, falla el GPS o el dispositivo está fuera del país. Esta versión SÍ\n * puede pedir permiso (acciones explícitas del usuario: \"Ubicarme ahora\").\n */\nexport async function getCurrentGqPosition(): Promise<LocCoord | null> {\n  try {\n    const perm = await withTimeout(Location.requestForegroundPermissionsAsync(), 4000, null);\n    if (!perm || perm.status !== 'granted') return null;\n    const p = await withTimeout(\n      Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced }),\n      5000,\n      null as never,\n    );\n    if (!p) return null;\n    const c: LocCoord = [p.coords.longitude, p.coords.latitude];\n    return isInsideGq(c) ? c : null;\n  } catch {\n    return null;\n  }\n}\n","export { PermissionStatus, } from 'expo-modules-core';\nexport { LocationEventEmitter as EventEmitter } from './LocationEventEmitter';\nexport { _getCurrentWatchId } from './LocationSubscribers';\nexport { installWebGeolocationPolyfill } from './GeolocationPolyfill';\nexport * from './Location';\nexport * from './Location.types';\nexport { LocationAccuracy as Accuracy, LocationActivityType as ActivityType, LocationGeofencingEventType as GeofencingEventType, LocationGeofencingRegionState as GeofencingRegionState, } from './Location.types';\n//# sourceMappingURL=index.js.map","import { Legac