\nexports.subscribeWithSelector = subscribeWithSelector;\nexports.unstable_ssrSafe = ssrSafe;\n","/**\n * EcomerseDetailScreen — Ficha de producto estándar Taobao/Xianyu.\n * v2 (auditoría senior): id robusto sin hang, error con Reintentar, rating y\n * verificado honestos (sin 5.0 inventado ni escudo falso), garantía condicional,\n * CTA con precio + Buy Now = addToCart+checkout (mismo snapshot), stepper de\n * cantidad con tope de stock, teléfono GQ estricto con feedback, reportar en\n * Android+iOS (Modal), favorito con sesión, galería sin FlatList anidado,\n * SafeArea y dimensiones reactivas.\n * Ruta: /ecomerse-detail?id=\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  Alert, Dimensions, Linking, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Eye, Flag, Heart, MapPin, ShieldCheck, ShoppingCart, Star } from 'lucide-react-native';\nimport { useTheme, alpha, espaciado, peso, tipografia, radios, trazo, Sheet, EstadoDinero, ilustracion, Precio, ScreenHeader, Tactil } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseProduct, EcomerseProductVariant } from '../api/ecomerse';\nimport { useAccionesProducto } from '../components/ecomerse/useAccionesProducto';\nimport SelectorDeVariante, { type Eleccion, type ModoSelector } from '../components/ecomerse/SelectorDeVariante';\n\n/**\n * Nombres de los documentos tal y como los lee el comprador. El `id` tiene que coincidir con el\n * CHECK de `wallet.ecomerse_product_docs` (migración 019) y con el formulario del vendedor.\n */\nconst DOC_LABEL: Record<string, string> = {\n  factura_compra: 'Factura de compra',\n  certificado_autenticidad: 'Certificado de autenticidad',\n  autorizacion_marca: 'Autorización de marca',\n};\nimport { useEcomerseStore } from '../state/ecomerse';\nimport { useSession } from '../state/session';\nimport { formatXAF } from '../utils/formatHelpers';\nimport { toGqMsisdn } from '../utils/phone';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { CabeceraTienda } from '../components/ecomerse/CabeceraTienda';\nimport { BotonPreguntarTienda } from '../components/ecomerse/BotonPreguntarTienda';\nimport { llamarTelefono } from '../utils/llamar';\n\nasync function openWa(phone: string, text: string) {\n  const cc = toGqMsisdn(phone);\n  if (!cc) {\n    Alert.alert('WhatsApp', 'Este vendedor no tiene un número válido. Usa Comprar ahora.');\n    return;\n  }\n  const url = `https://wa.me/${cc}?text=${encodeURIComponent(text)}`;\n  try {\n    await Linking.openURL(url);\n  } catch {\n    Alert.alert('WhatsApp', 'No se pudo abrir WhatsApp. Instálalo o compra in-app para conservar la garantía.');\n  }\n}\n\nexport default function EcomerseDetailScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const SCREEN_W = Dimensions.get('window').width;\n  const rawId = useLocalSearchParams<{ id?: string | string[] }>().id;\n  const id = Array.isArray(rawId) ? rawId[0] : rawId;\n  const { isAuthenticated } = useSession();\n\n  const [product, setProduct] = useState<EcomerseProduct | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [photoIdx, setPhotoIdx] = useState(0);\n  const [qty, setQty] = useState(1);\n  const [reportOpen, setReportOpen] = useState(false);\n  const [reportReason, setReportReason] = useState('');\n  const [reportBusy, setReportBusy] = useState(false);\n  const addToCart = useEcomerseStore((s) => s.addToCart);\n  const cartCount = useEcomerseStore((s) => s.cart.reduce((a, c) => a + c.qty, 0));\n  /**\n   * EL CORAZÓN Y LOS FAVORITOS VIENEN DEL MÓDULO COMÚN (Fase 2, 24/09/2026).\n   *\n   * Antes esto era la TERCERA copia de la misma regla —sesión, marca optimista y vuelta atrás si la\n   * API falla—, escrita aquí a mano y en otros dos sitios. Ahora es una:\n   * `components/ecomerse/useAccionesProducto.ts`.\n   *\n   * `abrirFicha` y `anadirAlCarrito` del módulo NO se usan en esta pantalla, y es deliberado: la ficha\n   * tiene combinaciones, cantidad y «comprar ahora», y ese flujo es suyo (ver la cabecera del módulo).\n   *\n   * Y llega con algo que esta pantalla no tenía: el módulo sincroniza `favIds` al montar, así que\n   * abrir una ficha por enlace directo —sin pasar por la home— ya no enseña el corazón vacío cuando\n   * el producto sí está guardado.\n   */\n  const { favIds, alternarFavorito } = useAccionesProducto();\n  const fav = favIds.includes(id ?? '');\n\n  /**\n   * ── FASE 4: LA COMBINACIÓN (21-sep-2026) ────────────────────────────────────────────────────────\n   *\n   * Si el anuncio tiene combinaciones, «Añadir» y «Comprar» **no compran**: abren la hoja de\n   * elección, que es el paso que el servidor exige desde la fase 4 (una línea sin combinación en un\n   * anuncio con combinaciones se rechaza). `elegido` recuerda la última elección para que la fila\n   * «Combinación» la enseñe y para que el botón de comprar **no mienta con el precio**: el de la\n   * combinación puede no ser el del anuncio.\n   */\n  const [selectorOpen, setSelectorOpen] = useState(false);\n  const [modoSelector, setModoSelector] = useState<ModoSelector>('comprar');\n  const [elegido, setElegido] = useState<Eleccion | null>(null);\n\n  const load = useCallback(async () => {\n    if (!id) { setError('No encontramos este producto.'); return; }\n    setError(null);\n    try {\n      setProduct(await ecomerseApi.product(id));\n    } catch (e) {\n      setProduct(null);\n      setError(e instanceof Error ? e.message : 'No se pudo cargar');\n    }\n  }, [id]);\n  useEffect(() => { load(); }, [load]);\n\n  const s = styles(colors);\n\n  if (!product && !error) {\n    // Carga: skeleton ligero (sin hang si id inválido: load ya setea error)\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n        {/* Esqueleto: sin `alVolver` el componente deja el hueco del ancho del icono, así que el\n            título sigue centrado exactamente igual que antes. */}\n        <ScreenHeader titulo=\"Producto\" />\n        <View style={{ height: 280, backgroundColor: colors.surface }} />\n        <View style={{ padding: espaciado.e16, gap: espaciado.e10 }}>\n          <View style={{ height: 26, borderRadius: radios.sm, backgroundColor: colors.border, width: '40%' }} />\n          <View style={{ height: 16, borderRadius: radios.sm, backgroundColor: colors.border, width: '85%' }} />\n          <View style={{ height: 12, borderRadius: radios.sm, backgroundColor: colors.border, width: '60%' }} />\n        </View>\n      </View>\n    );\n  }\n\n  if (!product) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e32, paddingTop: insets.top }}>\n        <Text style={{ fontSize: ilustracion.md, marginBottom: espaciado.e8 }}>📦</Text>\n        <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>No pudimos cargar el producto</Text>\n        <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 }}>{error}</Text>\n        <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e18 }}>\n          <Pressable onPress={load} style={{ backgroundColor: brand.secondary, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e11, borderRadius: radios.full }}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Pressable>\n          <Pressable onPress={() => router.back()} style={{ paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e11, borderRadius: radios.full, borderWidth: 1, borderColor: colors.border }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Volver</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  const phone = product.seller?.phoneContact ?? null;\n  const canBuy = product.status === 'active' && product.stock > 0;\n  const soldOut = product.stock <= 0 || product.status === 'sold_out';\n  const photos = product.photos?.length ? product.photos : [null];\n  const isFeat = product.isFeatured;\n  /**\n   * LA TIENDA ES UNA PUERTA (20-sep-2026). Aquí se calculaban a mano la valoración, el texto de\n   * «sin valoraciones» y el escudo, y ese bloque **no llevaba a ninguna parte**: el comprador veía\n   * quién vende y no podía ver qué más vende. Ahora los pinta `CabeceraTienda` —la misma tarjeta\n   * que usan el directorio y la página de tienda— y la pulsación abre la tienda.\n   * Las cuatro líneas se borran en vez de dejarlas: el texto de la valoración vive ya en el\n   * componente, y tenerlo también aquí sería la primera grieta de dos versiones del mismo dato.\n   */\n  const sellerId = product.seller?.id ?? null;\n  /**\n   * FICHA TÉCNICA (tanda 3). El formulario de publicar ya recoge marca, modelo, SKU, talla y color\n   * —y los guarda en `attributes`, que es jsonb—, pero la ficha NO los enseñaba: se recogían para\n   * nada. Aquí se convierten en lo que el comprador necesita para decidir sin preguntar. Se omiten\n   * los que no existan: una tabla con guiones es ruido.\n   */\n  const attrs = (product.attributes ?? {}) as Record<string, unknown>;\n  const attrTxt = (k: string) => (typeof attrs[k] === 'string' && (attrs[k] as string).trim() ? (attrs[k] as string).trim() : null);\n  const ficha: { label: string; valor: string }[] = [\n    { label: 'Estado', valor: attrTxt('estado') ?? '' },\n    { label: 'Marca', valor: attrTxt('marca') ?? '' },\n    { label: 'Modelo', valor: attrTxt('modelo') ?? '' },\n    { label: 'Talla / medida', valor: attrTxt('talla') ?? '' },\n    { label: 'Color', valor: attrTxt('color') ?? '' },\n    { label: 'Código (SKU)', valor: attrTxt('sku') ?? '' },\n    /* Tanda 4: plazo de preparación y devoluciones. Van en la MISMA tabla que los atributos porque\n       son lo mismo para el comprador —datos del artículo y de las condiciones— y separarlos en dos\n       bloques rompería la lectura. El plazo se muestra en horas tal y como lo declara el vendedor;\n       no se convierte a «1 día» porque «en 24 h» es como se pide. */\n    { label: 'Preparación', valor: product.handlingHours ? `En ${product.handlingHours} h` : '' },\n    { label: 'Devoluciones', valor: product.returnsAccepted ? 'Las acepta el vendedor' : '' },\n  ].filter((f) => f.valor);\n  /**\n   * ¿El anuncio se compra por combinaciones? Un anuncio SIN ejes (`variants` vacío o ausente) sigue\n   * funcionando exactamente como antes: cantidad en el cuerpo de la ficha y «Añadir»/«Comprar»\n   * directos. Ese caso es el normal —todos los anuncios hasta hoy—, no una avería.\n   */\n  const combinaciones = product.variants ?? [];\n  const hayCombinaciones = combinaciones.length > 0;\n\n  /* Texto del precio para los BOTONES de la barra de compra. No se usa `<Precio>` aquí: el botón no\n     enseña un importe, enseña una frase («Comprar · 18.500 XAF»), y esa frase tiene su propio\n     defecto pendiente —se parte en dos líneas dentro del botón y deja ver la capa de abajo—, que va\n     con la tanda de la barra de acciones. Se mantiene el mismo texto que había, incluido el\n     «Consultar» del caso sin precio, para no mezclar dos cambios.\n     Lo único que cambia con la fase 4: si hay una combinación elegida manda **su** precio, porque es\n     el que se va a cobrar; un botón que enseñara el del anuncio estaría mintiendo justo cuando el\n     comprador mira. */\n  const precioBoton = elegido?.variant?.priceXaf ?? product.priceXaf;\n  const priceTxt = Number.isFinite(precioBoton) ? formatXAF(precioBoton) : 'Consultar';\n  const createdTs = Date.parse(product.createdAt ?? '');\n  const created = Number.isFinite(createdTs)\n    ? new Date(createdTs).toLocaleDateString('es', { day: 'numeric', month: 'short', year: 'numeric' })\n    : null;\n\n  /**\n   * Mete una línea en el carrito. Con combinación, la línea lleva su id, su nombre, sus atributos y\n   * **su stock** (el tope que de verdad limita la cantidad); sin ella, es el anuncio entero como\n   * siempre. El precio de la línea es el que se va a cobrar.\n   */\n  const pushCart = (n: number, variante?: EcomerseProductVariant | null) => {\n    if (!canBuy) return;\n    addToCart({\n      productId: product.id,\n      title: product.title,\n      priceXaf: variante?.priceXaf ?? product.priceXaf,\n      qty: Math.min(n, variante ? variante.stockQuantity : product.stock),\n      photos: product.photos ?? [],\n      stock: variante ? variante.stockQuantity : product.stock,\n      city: product.city,\n      ...(variante?.id\n        ? {\n            variantId: variante.id,\n            variantName: variante.name,\n            variantAttributes: variante.attributes ?? {},\n            variantImageUrl: variante.imageUrl ?? null,\n          }\n        : {}),\n    });\n  };\n\n  /**\n   * «Comprar». Con carrito vacío añade la línea y va al checkout (que lee el store, mismo snapshot\n   * de precio); con artículos dentro, ofrece pagar **solo este**, y ahí la combinación y la cantidad\n   * viajan por la ruta, porque ese camino no toca el carrito.\n   */\n  const comprar = (variante: EcomerseProductVariant | null, cantidad: number) => {\n    if (!canBuy) return;\n    if (cartCount > 0) {\n      Alert.alert('Tu carrito tiene artículos', '¿Cómo quieres pagar?', [\n        { text: 'Cancelar', style: 'cancel' },\n        {\n          text: 'Pagar solo este',\n          onPress: () => router.push({\n            pathname: '/ecomerse-checkout',\n            params: {\n              productId: product.id,\n              solo: '1',\n              ...(variante?.id ? { variantId: variante.id, qty: String(cantidad) } : {}),\n            },\n          } as any),\n        },\n        { text: 'Añadir y pagar todo', onPress: () => { pushCart(cantidad, variante); router.push('/ecomerse-checkout' as any); } },\n      ]);\n      return;\n    }\n    pushCart(cantidad, variante);\n    router.push('/ecomerse-checkout' as any); // el checkout lee el store (mismo snapshot de precio)\n  };\n\n  const abrirSelector = (modo: ModoSelector) => { setModoSelector(modo); setSelectorOpen(true); };\n\n  /** Lo que devuelve la hoja cuando se elige «Añadir al carrito». */\n  const alCarrito = (e: Eleccion) => {\n    setElegido(e);\n    setSelectorOpen(false);\n    pushCart(e.cantidad, e.variant);\n    Alert.alert('Añadido al carrito', '¿Quieres seguir comprando o ir al carrito?', [\n      { text: 'Seguir', style: 'cancel' },\n      { text: 'Ver carrito', onPress: () => router.push('/ecomerse-checkout' as any) },\n    ]);\n  };\n\n  /** Lo que devuelve la hoja cuando se elige «Comprar ahora». */\n  const alComprar = (e: Eleccion) => {\n    setElegido(e);\n    setSelectorOpen(false);\n    comprar(e.variant, e.cantidad);\n  };\n\n  const addToCartFlow = () => {\n    if (hayCombinaciones) { abrirSelector('carrito'); return; }\n    pushCart(qty);\n    Alert.alert('Añadido al carrito', '¿Quieres seguir comprando o ir al carrito?', [\n      { text: 'Seguir', style: 'cancel' },\n      { text: 'Ver carrito', onPress: () => router.push('/ecomerse-checkout' as any) },\n    ]);\n  };\n\n  const buyNow = () => {\n    if (hayCombinaciones) { abrirSelector('comprar'); return; }\n    comprar(null, qty);\n  };\n\n  /* AQUÍ VIVÍA `toggleFav` — la tercera copia de la regla del corazón. Se retiró el 24/09/2026\n     (Fase 2): ahora es `alternarFavorito` del módulo `useAccionesProducto`, que hace exactamente lo\n     mismo —sesión primero, marca optimista, vuelta atrás con aviso— y además sincroniza `favIds` al\n     montar, cosa que esta pantalla no hacía. Los textos de los dos avisos son idénticos porque son el\n     mismo aviso: no se reescriben, se unifican. */\n\n  const sendReport = async () => {\n    if (reportReason.trim().length < 10) {\n      Alert.alert('Motivo obligatorio', 'Describe el motivo con al menos 10 caracteres.');\n      return;\n    }\n    setReportBusy(true);\n    try {\n      const r = await ecomerseApi.reportProduct(product.id, reportReason.trim());\n      Alert.alert('Reporte enviado', r.message);\n      setReportOpen(false);\n      setReportReason('');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo reportar');\n    } finally {\n      setReportBusy(false);\n    }\n  };\n\n  return (\n    <View style={[stylesRoot(colors).root, { paddingTop: insets.top }]}>\n      {/* Cabecera del kit desde el 24/09/2026. La acción de la derecha es el aviso de reporte. */}\n      <ScreenHeader\n        titulo=\"Producto\"\n        alVolver={() => router.back()}\n        accion={\n          <Tactil onPress={() => setReportOpen(true)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Reportar anuncio\">\n            <Flag size={18} color={colors.textSecondary} />\n          </Tactil>\n        }\n      />\n\n      <ScrollView contentContainerStyle={{ paddingBottom: 130 }} showsVerticalScrollIndicator={false}>\n        {/* Galería swipe (ScrollView paging, sin FlatList anidado) */}\n        <View>\n          {photos[0] ? (\n            <ScrollView\n              horizontal\n              pagingEnabled\n              showsHorizontalScrollIndicator={false}\n              onMomentumScrollEnd={(e) => setPhotoIdx(Math.round(e.nativeEvent.contentOffset.x / SCREEN_W))}\n            >\n              {photos.map((ph, i) => (\n                <Image key={i} source={{ uri: ph! }} style={{ width: SCREEN_W, height: 280, backgroundColor: colors.surface }}\n                  contentFit=\"cover\" transition={200} accessibilityLabel={`Foto ${i + 1} de ${photos.length}`} />\n              ))}\n            </ScrollView>\n          ) : (\n            <View style={{ width: SCREEN_W, height: 280, backgroundColor: alpha(colors.primary, 0.08), alignItems: 'center', justifyContent: 'center' }}>\n              <Text style={{ fontSize: ilustracion.lg }}>{product.categoryIcon ?? '📦'}</Text>\n            </View>\n          )}\n          {photos[0] && (\n            <View style={s.photoCounter}><Text style={{ color: brand.white, fontSize: tipografia.micro, fontWeight: '800' }}>{photoIdx + 1}/{photos.length}</Text></View>\n          )}\n        </View>\n\n        <View style={{ padding: espaciado.e16 }}>\n          {/* Etiquetas */}\n          <View style={{ flexDirection: 'row', gap: espaciado.e6, marginBottom: espaciado.e8 }}>\n            {isFeat && <View style={s.tagFeat}><Text style={s.tagFeatText}>🔥 Destacado</Text></View>}\n            {product.seller?.badge === 'Pro' && <View style={s.tagPro}><Text style={s.tagProText}>Tienda PRO</Text></View>}\n            {product.isNegotiable && <View style={s.tagSoft}><Text style={s.tagSoftText}>💰 Negociable</Text></View>}\n          </View>\n\n          {/* Precio + título */}\n          <Precio valor={product.priceXaf} tamano=\"xl\" textoVacio=\"Consultar\" />\n          <Text style={s.title}>{product.title}</Text>\n\n          {/* Métricas */}\n          <View style={s.metrics}>\n            {product.views > 0 && <Metric icon={<Eye size={12} color={colors.textSecondary} />} label={`${product.views} vistas`} />}\n            {product.favoriteCount > 0 && <Metric icon={<Heart size={12} color={colors.textSecondary} />} label={`${product.favoriteCount} fav`} />}\n            <Metric icon={<ShoppingCart size={12} color={colors.textSecondary} />} label={soldOut ? 'Agotado' : `Stock ${product.stock}`} />\n            <Metric icon={<MapPin size={12} color={colors.textSecondary} />} label={product.city} />\n            {created && <Metric icon={<Text style={{ fontSize: tipografia.micro }}>🗓</Text>} label={created} />}\n          </View>\n          {product.categoryLabel && (\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e6 }}>\n              {product.categoryIcon} {product.categoryLabel}{product.subcategoryLabel ? ` · ${product.subcategoryLabel}` : ''}\n            </Text>\n          )}\n\n          {/* DÓNDE ESTÁ EL DINERO (tanda 1 «el dinero se ve»).\n              Antes: una sola frase («Garantía EG Route Plan de 7 días si pagas por la app…») que\n              el comprador tenía que creer, y colocada a media pantalla. Ahora el bloque de los tres\n              estados reales del dinero, justo encima de la cantidad y del CTA, que es donde la\n              confianza decide. Los estados NO son inventados: los impone el backend\n              (`liberarSiMonederoEc` exige status='delivered'; `devolverSiMonederoEc`, 'cancelled').\n              Si el anuncio no admite compra in-app, se dice eso y nada más: no se promete garantía\n              sobre un camino que no existe. */}\n          {canBuy ? (\n            <EstadoDinero activo=\"retenido\" />\n          ) : (\n            <View style={[s.warranty, { backgroundColor: alpha(colors.primary, 0.06), borderColor: colors.border }]}>\n              <ShieldCheck size={16} color={colors.primary} />\n              <Text style={{ flex: 1, marginLeft: espaciado.e8, fontSize: tipografia.caption, color: colors.textPrimary, fontWeight: '700' }}>\n                Este anuncio no admite compra in-app ahora mismo.\n              </Text>\n            </View>\n          )}\n\n          {/* Cantidad. CON combinaciones la cantidad se elige DENTRO de la hoja, y no por comodidad:\n              es el único sitio donde se conoce el tope real. El `stock` del anuncio es la SUMA de las\n              combinaciones, así que un «máx. 3» aquí puede ser mentira para la combinación que se\n              acabe eligiendo. En su lugar va la puerta a la elección, que además enseña lo elegido. */}\n          {canBuy && (hayCombinaciones ? (\n            <Pressable\n              onPress={() => abrirSelector('comprar')}\n              accessibilityRole=\"button\"\n              accessibilityLabel={elegido?.variant ? `Combinación elegida: ${elegido.variant.name}. Cambiar` : 'Elegir la combinación'}\n              style={[s.qtyRow, {\n                borderRadius: radios.md, borderWidth: trazo.fino, borderColor: colors.border,\n                paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e12,\n              }]}\n            >\n              <Text style={{ fontSize: tipografia.body, fontWeight: peso.fuerte, color: colors.textPrimary }}>Combinación</Text>\n              <Text\n                numberOfLines={1}\n                style={{\n                  flex: 1, marginLeft: espaciado.e8, textAlign: 'right',\n                  fontSize: tipografia.body, fontWeight: peso.fuerte,\n                  color: elegido?.variant ? colors.textPrimary : colors.primary,\n                }}\n              >\n                {elegido?.variant ? `${elegido.variant.name} × ${elegido.cantidad}` : 'Elegir'}\n              </Text>\n            </Pressable>\n          ) : (\n            <View style={s.qtyRow}>\n              <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>Cantidad</Text>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }}>\n                <Pressable onPress={() => setQty((q) => Math.max(1, q - 1))} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Menos\"\n                  style={[s.qtyBtn, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle }}>−</Text>\n                </Pressable>\n                <Text style={{ fontSize: tipografia.subtitle, fontWeight: '900', color: colors.textPrimary, minWidth: 24, textAlign: 'center' }}>{qty}</Text>\n                <Pressable onPress={() => setQty((q) => Math.min(product.stock, q + 1))} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Más\"\n                  style={[s.qtyBtn, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle }}>+</Text>\n                </Pressable>\n                <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>máx. {product.stock}</Text>\n              </View>\n            </View>\n          ))}\n\n          {/* Tienda — y ahora es una PUERTA. Antes este bloque enseñaba quién vende y no dejaba\n              entrar: era el mejor sitio de la app para abrir una tienda y era un callejón sin\n              salida. La tarjeta es el componente compartido (`CabeceraTienda`), el mismo que usan\n              el directorio de tiendas y la página de tienda.\n              La llamada sigue registrando el lead del ANUNCIO (`contactIntent`), que es lo único\n              que distingue esta llamada de la que se hace desde la tienda: aquí se sabe de qué\n              anuncio viene el interés, allí no. Y solo se registra si de verdad se abrió el\n              marcador (`llamarTelefono` devuelve `false` con un número inválido). */}\n          <View style={{ marginTop: espaciado.e18 }}>\n            <Text style={s.sectionTitle}>Tienda</Text>\n            <CabeceraTienda\n              seller={product.seller}\n              onPress={sellerId\n                ? () => router.push({ pathname: '/ecomerse-tienda', params: { id: sellerId, nombre: product.seller?.businessName ?? '' } } as any)\n                : undefined}\n              onLlamar={phone\n                ? () => {\n                    void llamarTelefono(phone).then((abierto) => {\n                      if (abierto && isAuthenticated) ecomerseApi.contactIntent(product.id, 'call').catch(() => undefined);\n                    });\n                  }\n                : undefined}\n            />\n            {/*\n              LA PUERTA AL CHAT (Fase 4 del pie). Va justo debajo de la tarjeta de la tienda y no en\n              la barra de abajo, y eso es una decisión: la barra está ordenada alrededor del DINERO\n              —Comprar manda, Añadir acompaña, y el contacto con WhatsApp bajó a icono discreto a\n              propósito, para que el trato ocurra dentro de la app—. La conversación con la tienda\n              también ocurre dentro de la app: es la pieza que le faltaba al bloque «quién vende»,\n              que ya era puerta a la tienda y ahora es también puerta a hablar con ella.\n              El `productId` viaja para que el primer mensaje cite ESTE anuncio. Que se cite o no lo\n              decide el servidor —sólo si el hilo estaba vacío y el anuncio es de esta tienda—.\n            */}\n            <BotonPreguntarTienda\n              sellerId={sellerId}\n              productId={product.id}\n              nombre={product.seller?.businessName ?? null}\n              telefono={phone}\n              /* El margen lo pone la ficha, no el botón: aquí se separa con `marginTop` y en la\n                 página de tienda con el `gap` de su contenedor. */\n              style={{ marginTop: espaciado.e12 }}\n            />\n          </View>\n\n          {/* FICHA TÉCNICA: lo que el formulario recoge y el comprador necesita saber. Va después de\n              la descripción y antes del vendedor: primero el artículo, después quién lo vende. */}\n          {ficha.length > 0 && (\n            <View style={{ marginTop: espaciado.e18 }}>\n              <Text style={s.sectionTitle}>Características</Text>\n              <View style={{ borderRadius: radios.md, borderWidth: 1, borderColor: colors.border, overflow: 'hidden' }}>\n                {ficha.map((f, i) => (\n                  <View\n                    key={f.label}\n                    style={{\n                      flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e12,\n                      paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9,\n                      borderTopWidth: i === 0 ? 0 : 1, borderTopColor: colors.border,\n                    }}\n                  >\n                    <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>{f.label}</Text>\n                    <Text style={{ flex: 1, textAlign: 'right', fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }} numberOfLines={2}>\n                      {f.valor}\n                    </Text>\n                  </View>\n                ))}\n              </View>\n            </View>\n          )}\n\n          {/* DOCUMENTOS DEL VENDEDOR (tanda 4 · sección 4). Se enseñan CON SU ESTADO, y esa es la\n              decisión importante: el informe de Dewu concluyó que «un badge de verificado sin\n              evidencia consultable es marketing; uno con informe y trazabilidad es un sistema». Aquí\n              el comprador ve si el papel está aprobado por la plataforma o todavía en revisión, en\n              vez de un escudo que promete más de lo que se ha comprobado. */}\n          {(product.docs?.length ?? 0) > 0 && (\n            <View style={{ marginTop: espaciado.e18 }}>\n              <Text style={s.sectionTitle}>Documentación</Text>\n              <View style={{ gap: espaciado.e6 }}>\n                {product.docs!.map((d) => {\n                  const etiqueta = DOC_LABEL[d.docType] ?? d.docType;\n                  const aprobado = d.status === 'approved';\n                  const rechazado = d.status === 'rejected';\n                  const color = aprobado ? colors.success : rechazado ? colors.danger : colors.textSecondary;\n                  return (\n                    <View key={d.id} style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n                      <ShieldCheck size={14} color={color} />\n                      <Text style={{ flex: 1, fontSize: tipografia.caption, color: colors.textPrimary }}>\n                        {etiqueta}\n                        {d.docNumber ? ` · ${d.docNumber}` : ''}\n                        {d.amountXaf !== null && d.amountXaf !== undefined ? ` · ${formatXAF(d.amountXaf)}` : ''}\n                      </Text>\n                      <Text style={{ fontSize: tipografia.micro, fontWeight: '800', color }}>\n                        {aprobado ? 'Revisado' : rechazado ? 'Rechazado' : 'En revisión'}\n                      </Text>\n                    </View>\n                  );\n                })}\n              </View>\n            </View>\n          )}\n\n          {/* Descripción */}\n          {product.description ? (\n            <View style={{ marginTop: espaciado.e18 }}>\n              <Text style={s.sectionTitle}>Descripción</Text>\n              <Text style={{ fontSize: tipografia.body, lineHeight: 20, color: colors.textSecondary }}>{product.description}</Text>\n            </View>\n          ) : null}\n        </View>\n      </ScrollView>\n\n      {/* ACCIÓN PRINCIPAL (tanda 2 de la comparación con 得物/Dewu).\n          Antes había CUATRO acciones del mismo orden (WhatsApp 157x138, Favorito 121x110,\n          Carrito 326x145 y Comprar 302x203): ninguna mandaba, y `WhatsApp` —cuyo trato la propia\n          garantía declara NO cubierto— competía de igual a igual con comprar. La regla del spec de\n          referencia es una acción dominante al pie. Ahora:\n            · Comprar  → CTA principal, ancho y con el precio.\n            · Añadir   → secundaria, contorno (sigue siendo cómoda para varios artículos).\n            · ♥ / 💬   → iconos discretos; el contacto pasa a ser la salida MENOS prominente,\n                         que es donde debe estar si queremos que el dinero pase por la app.\n          Se conservan las cuatro funciones: no se pierde ninguna salida, se ordena su peso. */}\n      <View style={[s.bottomBar, { backgroundColor: colors.card, borderTopColor: colors.border, paddingBottom: Math.max(insets.bottom, 12) }]}>\n        {canBuy && (\n          <Text style={[s.notaFuera, { color: colors.textSecondary }]}>\n            Si compras por WhatsApp, la garantía no cubre el trato.\n          </Text>\n        )}\n        <View style={s.acciones}>\n          <Pressable onPress={() => alternarFavorito(product)} hitSlop={8} accessibilityRole=\"button\"\n            accessibilityLabel={fav ? 'Quitar de favoritos' : 'Añadir a favoritos'}\n            accessibilityState={{ selected: fav }} style={s.iconCol}>\n            <Heart size={22} color={fav ? brand.like : colors.textSecondary} fill={fav ? brand.like : 'transparent'} />\n          </Pressable>\n          <Pressable onPress={() => phone && openWa(phone, 'Hola, me interesa tu anuncio: ' + product.title).then(() => {\n            if (isAuthenticated) ecomerseApi.contactIntent(product.id, 'whatsapp').catch(() => undefined);\n          })} hitSlop={8}\n            accessibilityRole=\"button\" accessibilityLabel=\"Escribir por WhatsApp\" style={s.iconCol}>\n            <Text style={{ fontSize: tipografia.subtitle, opacity: 0.55 }}>💬</Text>\n          </Pressable>\n          <Pressable onPress={addToCartFlow} disabled={!canBuy} accessibilityRole=\"button\" accessibilityState={{ disabled: !canBuy }}\n            accessibilityLabel=\"Añadir al carrito\"\n            style={[s.cartBtn, { borderColor: canBuy ? brand.secondary : colors.border }]}>\n            <Text style={{ color: canBuy ? brand.secondary : colors.textSecondary, fontSize: tipografia.body, fontWeight: '800' }}>Añadir</Text>\n          </Pressable>\n          <Pressable onPress={buyNow} disabled={!canBuy} accessibilityRole=\"button\" accessibilityState={{ disabled: !canBuy }}\n            accessibilityLabel={canBuy ? `Comprar por ${priceTxt}` : 'No disponible'}\n            style={[s.buyBtn, { backgroundColor: canBuy ? brand.secondary : colors.border }]}>\n            <Text style={{ color: brand.white, fontSize: tipografia.subtitle, fontWeight: '900' }}>\n              {canBuy ? `Comprar · ${priceTxt}` : soldOut ? 'Agotado' : 'No disponible'}\n            </Text>\n          </Pressable>\n        </View>\n      </View>\n\n      {/* ── LA ELECCIÓN DE COMBINACIÓN (fase 4) ─────────────────────────────────────────────────────\n          La hoja solo existe si el anuncio tiene ejes; en un anuncio sin ejes ningún camino la abre\n          (los dos botones y la fila de cantidad comprueban `hayCombinaciones`), así que no se monta\n          nada de más y el comportamiento de siempre queda intacto. */}\n      <SelectorDeVariante\n        visible={selectorOpen}\n        product={product}\n        modoInicial={modoSelector}\n        seleccionInicial={elegido?.variant ?? null}\n        onClose={() => setSelectorOpen(false)}\n        onCarrito={alCarrito}\n        onComprar={alComprar}\n      />\n\n      {/*\n        Reportar anuncio. Era un `<Modal>` a mano que repetía lo del `Sheet`; con él se hereda el\n        fondo, el cierre al tocar fuera, el botón de atrás y el título anunciado como cabecera.\n      */}\n      <Sheet\n        visible={reportOpen}\n        position=\"bottom\"\n        busy={reportBusy}\n        title=\"Reportar anuncio\"\n        subtitle=\"Cuéntanos el motivo (fraude, prohibido, estafa…). Lo revisa el equipo de moderación.\"\n        onClose={() => setReportOpen(false)}\n      >\n        <TextInput\n          value={reportReason}\n          onChangeText={setReportReason}\n          placeholder=\"Motivo (mín. 10 caracteres)\"\n          placeholderTextColor={colors.textSecondary}\n          multiline\n          style={[s.reportInput, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n        />\n        <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n          <Pressable onPress={() => setReportOpen(false)} style={[s.modalBtn, { borderWidth: 1, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\n          </Pressable>\n          <Pressable onPress={sendReport} disabled={reportBusy} style={[s.modalBtn, { backgroundColor: colors.danger, flex: 1 }]}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>{reportBusy ? 'Enviando…' : 'Enviar reporte'}</Text>\n          </Pressable>\n\n            </View>\n      </Sheet>\n    </View>\n  );\n}\n\nfunction Metric({ icon, label }: { icon: React.ReactNode; label: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3 }}>\n      {icon}\n      <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>{label}</Text>\n    </View>\n  );\n}\n\nconst stylesRoot = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({ root: { flex: 1, backgroundColor: c.background } });\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  photoCounter: { position: 'absolute', right: 12, bottom: 12, backgroundColor: 'rgba(0,0,0,0.55)', paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: radios.full },\n  tagFeat: { backgroundColor: 'rgba(255,107,53,0.14)', borderRadius: radios.sm, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  tagFeatText: { color: brand.secondary, fontSize: tipografia.micro, fontWeight: '800' },\n  /* `avatar` y `roundBtn` se fueron con el bloque de la tienda: viven en `CabeceraTienda`, que es\n     donde se pintan ahora. Dejar aquí sus copias era garantizar que un día se cambie una sí y otra\n     no. */\n  tagPro: { backgroundColor: 'rgba(0,132,255,0.12)', borderRadius: radios.sm, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  tagProText: { color: brand.primary, fontSize: tipografia.micro, fontWeight: '800' },\n  tagSoft: { backgroundColor: 'rgba(16,185,129,0.12)', borderRadius: radios.sm, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  tagSoftText: { color: brand.success, fontSize: tipografia.micro, fontWeight: '800' },\n  title: { fontSize: tipografia.subtitle, fontWeight: '800', color: c.textPrimary, marginTop: espaciado.e6, lineHeight: 23 },\n  metrics: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e12, marginTop: espaciado.e10 },\n  warranty: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, borderWidth: 1, padding: espaciado.e10, marginTop: espaciado.e12 },\n  qtyRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: espaciado.e14 },\n  qtyBtn: { width: 34, height: 34, borderRadius: radios.md, borderWidth: 1, alignItems: 'center', justifyContent: 'center' },\n  sectionTitle: { fontSize: tipografia.body, fontWeight: '800', color: c.textPrimary, marginBottom: espaciado.e8 },\n  bottomBar: { position: 'absolute', left: 0, right: 0, bottom: 0, paddingHorizontal: espaciado.e14, paddingTop: espaciado.e8, borderTopWidth: 1, gap: espaciado.e6 },\n  /** Nota de alcance de la garantía: encima de las acciones, a sangre dentro de la barra. */\n  notaFuera: { textAlign: 'center', fontSize: tipografia.micro },\n  /** Fila de acciones: antes era la barra entera; ahora la nota va arriba y esto debajo. */\n  acciones: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 },\n  iconCol: { alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e2 },\n  /** Añadir: secundaria de contorno. Antes era un bloque relleno ('#FFD8C4') que pesaba como el CTA. */\n  cartBtn: { borderRadius: radios.md, borderWidth: 1.5, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e16, alignItems: 'center' },\n  /** Comprar: la única acción dominante. Crece para quedarse con el espacio sobrante. */\n  buyBtn: { flex: 1, borderRadius: radios.md, paddingVertical: espaciado.e14, alignItems: 'center' },\n  reportInput: { borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, minHeight: 90, textAlignVertical: 'top', fontSize: tipografia.body },\n  modalBtn: { paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e16, borderRadius: radios.md, alignItems: 'center' },\n});\n","/**\n * useAccionesProducto — lo que hace una tarjeta del Mercado cuando la pulsas, le das al corazón o la\n * añades al carrito.\n *\n * POR QUÉ ES UN MÓDULO Y NO DOS LÍNEAS EN CADA PANTALLA\n * `app/ecomerse.tsx` ya tenía escrita esta frase sobre el corazón: «**en un solo sitio**: ahora lo\n * pulsan la rejilla y el carrusel, y tener la misma regla escrita dos veces es la forma más segura de\n * que un día digan cosas distintas». Era verdad dentro de ese archivo. Al aparecer la pantalla de la\n * subcategoría, que pinta **las mismas tarjetas**, la regla se rompía en cuanto se copiara: el corazón\n * tiene una puerta de sesión, una marca optimista y una vuelta atrás si la API falla, y eso copiado es\n * garantizar que un día una pantalla deje el corazón puesto y la otra no.\n *\n * QUÉ ENTRA\n *   · **El corazón** (`alternarFavorito`): sesión, marca optimista y deshacer + aviso si la API falla.\n *   · **La sincronización de favoritos al montar**: `favIds` vive en el store, así que una pantalla\n *     abierta por enlace directo —sin pasar por la home— enseñaría todos los corazones vacíos.\n *     Se paga una petición de más al entrar en la segunda pantalla; la alternativa era un corazón que\n *     miente, que es peor.\n *   · **Abrir la ficha** y **añadir al carrito**, con la guarda del anuncio con combinaciones.\n *\n * QUÉ NO ENTRA\n *   · **Añadir al carrito desde la FICHA** (`ecomerse-detail.tsx`): la ficha tiene combinaciones,\n *     cantidad y modo «comprar ahora», y ese flujo es suyo. Lo que la ficha sí toma de aquí es el\n *     corazón y la sincronización de `favIds`.\n *   · El botón de WhatsApp y el selector de combinación: son de la ficha y de nadie más.\n *\n * ── CERRADO EL 24/09/2026 (Fase 2): YA NO HAY TRES VERSIONES ────────────────────────────────────\n * Aquí decía, y era verdad entonces: «el corazón de `ecomerse-detail.tsx` y el de `ecomerse-tienda.tsx`\n * **no** pasan por aquí; migrarlos es otra tarea». Se migraron los dos.\n *   · `ecomerse-tienda.tsx` usa el módulo entero: `favIds`, `alternarFavorito`, `abrirFicha` y\n *     `anadirAlCarrito`. Desaparecieron su `useEffect` de favoritos, su `alternarFavorito` propio\n *     **y su copia de la guarda de combinaciones** — que era el peor de los tres duplicados, porque\n *     una guarda copiada es una guarda que un día deja de coincidir.\n *   · `ecomerse-detail.tsx` usa `favIds` y `alternarFavorito` (los otros dos no le sirven: ver\n *     arriba). Y gana algo que no tenía: la sincronización al montar. Antes, abrir una ficha por\n *     enlace directo —sin pasar por la home— enseñaba el corazón vacío aunque el producto estuviera\n *     guardado. Ese era el mismo defecto que este módulo se creó para cerrar, y le quedaba una\n *     puerta abierta.\n */\n\nimport { useCallback, useEffect } from 'react';\nimport { Alert } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { ecomerseApi, EcomerseProduct } from '../../api/ecomerse';\nimport { useEcomerseStore } from '../../state/ecomerse';\nimport { useSession } from '../../state/session';\n\nexport function useAccionesProducto() {\n  const router = useRouter();\n  const { isAuthenticated } = useSession();\n  const { favIds, setFavIds, toggleFavId, addToCart } = useEcomerseStore();\n\n  /** Sincroniza los ids de favoritos del usuario. Silencioso si no hay sesión o si la API falla: los\n   *  corazones simplemente salen vacíos, que es lo que son. */\n  useEffect(() => {\n    let vivo = true;\n    ecomerseApi.favoriteIds().then((ids) => { if (vivo) setFavIds(ids); }).catch(() => undefined);\n    return () => { vivo = false; };\n  }, [setFavIds]);\n\n  const abrirFicha = useCallback((id: string) => {\n    router.push({ pathname: '/ecomerse-detail', params: { id } } as any);\n  }, [router]);\n\n  /** Corazón. Sin sesión no se escribe nada y se dice por qué: un corazón que se queda puesto sin\n   *  guardarse es un favorito que el usuario cree tener y no tiene. */\n  const alternarFavorito = useCallback((item: EcomerseProduct) => {\n    if (!isAuthenticated) {\n      Alert.alert('Inicia sesión', 'Para guardar favoritos entra en tu cuenta.');\n      return;\n    }\n    toggleFavId(item.id);\n    ecomerseApi.favoritesToggle(item.id).catch(() => {\n      toggleFavId(item.id);\n      Alert.alert('Favoritos', 'No se pudo guardar. Inténtalo de nuevo.');\n    });\n  }, [isAuthenticated, toggleFavId]);\n\n  /**\n   * Añadir al carrito desde la tarjeta. **Un anuncio CON combinaciones no se añade desde aquí**: hay\n   * que elegir color y talla, y la tarjeta no tiene dónde. Se manda a la ficha, que es donde se elige.\n   *\n   * La guarda se apoya en `variantCount`, que hoy devuelve `myProducts`; **el catálogo todavía no lo\n   * manda**, así que mientras tanto esta rama no se toma y la línea se retira con su aviso en el\n   * checkout (ver `app/ecomerse-checkout.tsx`).\n   */\n  const anadirAlCarrito = useCallback((item: EcomerseProduct) => {\n    if (item.variantCount) { abrirFicha(item.id); return; }\n    addToCart({\n      productId: item.id,\n      title: item.title,\n      priceXaf: item.priceXaf,\n      qty: 1,\n      photos: item.photos ?? [],\n      stock: item.stock,\n      city: item.city,\n    });\n  }, [abrirFicha, addToCart]);\n\n  return { favIds, abrirFicha, alternarFavorito, anadirAlCarrito };\n}\n","/**\n * components/ecomerse/SelectorDeVariante.tsx — ELEGIR LA COMBINACIÓN ANTES DE COMPRAR (fase 4).\n *\n * EL PROBLEMA QUE CIERRA. Hasta la fase 4, en el Mercado «Comprar» y «Añadir» compraban el anuncio\n * ENTERO: no existía nada que elegir. El formulario del vendedor pedía «talla» y «color» como texto\n * libre y los guardaba en `attributes`, donde no los leía nadie. Con combinaciones en el servidor,\n * comprar sin elegir ya no es una posibilidad: el pedido se rechaza. Esta hoja es el paso que\n * faltaba entre «quiero esto» y «el pedido».\n *\n * ES UN PORTE DEL SELECTOR DE LIFE BOOK (`components/lifebook/SelectorDeVariante.tsx`), y lo es a\n * propósito: los dos mercados comparten las REGLAS del SKU (módulo `opciones-producto.ts` del\n * servidor), así que la forma de los ejes es la misma y las dos fichas tienen que comportarse igual\n * ante el mismo dato. Si un día se cambia una regla de elección, se cambia en los dos sitios.\n *\n * LO QUE **NO** SE PORTA, porque el Mercado no lo tiene (y no se inventa):\n *   · **Nada de «bajo pedido»**: en el Mercado cada combinación tiene su número exacto de unidades.\n *     Life Book tiene modos de stock (`exact` / `on_request` / …); aquí no hay tal cosa.\n *   · **Nada de precio anterior tachado**: el anuncio del Mercado no guarda precio antiguo.\n *   · **Nada de asistente de talla**: eso vive en las tablas de medidas de Life Book y el Mercado no\n *     tiene tablas.\n *   · **Nada de «avísame cuando llegue»**: el endpoint de aviso por combinación es de Life Book. Sin\n *     él, un valor que no se puede elegir no se queda en un callejón: al tocarlo, la hoja **dice por\n *     qué** («no existe» o «agotado») y se puede seguir eligiendo el otro eje.\n *   · **Nada de estado «ocupado»**: en el Mercado el carrito es local y comprar es navegar, así que\n *     no hay ninguna llamada lenta que bloquear y un «cargando» sería decorativo.\n *\n * Y una diferencia de forma deliberada: la hoja la pinta **`Sheet`** del kit, no un `<Modal>` a\n * mano como el de Life Book. Se hereda el fondo, el cierre al tocar fuera, el **botón físico de\n * atrás**, el foco encerrado dentro del diálogo y el tope de altura. Se pierde el «deslizar hacia\n * abajo para cerrar», que es lo que cuesta el `<Modal>` propio — y no compensa: el `Sheet` documenta\n * que 51 ficheros escribiendo su propio modal es justo el problema que existe para no repetir.\n */\nimport React, { useEffect, useMemo, useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { Minus, Plus } from 'lucide-react-native';\nimport {\n  alpha, altura, brand, espaciado, icono, ilustracion, peso, Precio, radios, Sheet, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport type { EcomerseOptionGroup, EcomerseProduct, EcomerseProductVariant } from '../../api/ecomerse';\nimport { formatXAF } from '../../utils/formatHelpers';\n\nexport interface Eleccion {\n  variant: EcomerseProductVariant | null;\n  cantidad: number;\n}\n\n/** De qué botón se abrió: ese queda como principal en la hoja y el otro al lado. */\nexport type ModoSelector = 'carrito' | 'comprar';\n\n/** Compara valores de eje sin depender de mayúsculas ni de espacios sobrantes. */\nconst norm = (v: unknown): string => String(v ?? '').trim().toLowerCase();\n\nexport default function SelectorDeVariante({\n  visible, product, modoInicial = 'comprar', seleccionInicial, onClose, onCarrito, onComprar,\n}: {\n  visible: boolean;\n  product: EcomerseProduct;\n  modoInicial?: ModoSelector;\n  /** Lo que ya se había elegido en la ficha: al volver a abrir, se mantiene. */\n  seleccionInicial?: EcomerseProductVariant | null;\n  onClose: () => void;\n  onCarrito: (e: Eleccion) => void;\n  onComprar: (e: Eleccion) => void;\n}) {\n  const { colors } = useTheme();\n  /**\n   * EL ALTO DE LA LISTA, Y POR QUÉ SE CALCULA.\n   *\n   * `Sheet` topa la hoja al **80 % de la pantalla** (`hojaAbajo.maxHeight`), pero el tope es del\n   * `Sheet`, no de lo de dentro: si el contenido pide más, **desborda** y lo que cae fuera se pierde.\n   * Medido en el emulador (640 dp de alto): con la lista a 300 dp los dos botones acabaron en\n   * `[42,1231][303,1232]`, o sea **fuera de la pantalla** y sin forma de confirmar la compra.\n   *\n   * El cromo que va FUERA de la lista (y que por tanto hay que descontar) es fijo y medido:\n   * relleno de la hoja 20+22, título 24, margen 14, cabecera 104 (foto de 92 o la columna de texto,\n   * lo que sea mayor), dos huecos de 10 y los botones 46 → **250 dp**. Se presupuestan 270 para dejar\n   * margen a un `font_scale` alto. Comprobado en el aparato: con este presupuesto, en el emulador\n   * (640 dp) los botones quedaron en `y 1096..1188`, dentro de la pantalla; antes, en `y 1231`.\n   *\n   * El título del producto va DENTRO de la cabecera con `numberOfLines={1}` a propósito: si fuera el\n   * `subtitle` del `Sheet`, un nombre largo envolvería a dos o tres líneas y volvería a empujar los\n   * botones fuera — que es exactamente el defecto que esto arregla.\n   */\n  const { height: altoPantalla } = useWindowDimensions();\n  const altoLista = Math.max(140, Math.round(altoPantalla * 0.8) - 270);\n  const grupos = useMemo(\n    () => (product.options ?? []).filter((g) => (g.values ?? []).length > 0),\n    [product.options],\n  );\n  const variantes = useMemo(() => (product.variants ?? []).filter((v) => v.id), [product.variants]);\n\n  /** Lo elegido, por código de eje: `{ color: 'Rojo', talla: 'M' }`. */\n  const [sel, setSel] = useState<Record<string, string>>({});\n  const [cant, setCant] = useState(1);\n  /** Valor que NO se puede elegir y que se acaba de tocar, para explicar por qué. */\n  const [nota, setNota] = useState<{ code: string; value: string; agotado: boolean } | null>(null);\n\n  /**\n   * Al abrir: **nada se elige por el comprador**. Dos excepciones honestas: si la ficha ya tenía una\n   * combinación elegida se mantiene, y si el anuncio tiene UNA sola combinación se marca (no hay\n   * nada que decidir). Elegir «la primera» por su cuenta es exactamente el defecto que esta hoja\n   * existe para cerrar.\n   */\n  useEffect(() => {\n    if (!visible) return;\n    setCant(1);\n    setNota(null);\n    const deLaFicha = seleccionInicial?.id && variantes.some((v) => v.id === seleccionInicial.id)\n      ? seleccionInicial : null;\n    const unica = variantes.length === 1 ? variantes[0] : null;\n    const base = deLaFicha ?? unica;\n    setSel(base\n      ? Object.fromEntries(\n        grupos.map((g) => [g.code, String(base.attributes?.[g.code] ?? '')]).filter(([, v]) => v),\n      )\n      : {});\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [visible, product.id]);\n\n  /** ¿Le quedan unidades? En el Mercado el stock de una combinación es siempre un número. */\n  const conStock = (v: EcomerseProductVariant | undefined): boolean =>\n    !!v && Number(v.stockQuantity ?? 0) > 0;\n\n  /** La combinación que corresponde a una elección completa. */\n  const varianteDe = (eleccion: Record<string, string>): EcomerseProductVariant | null => {\n    if (!grupos.length) return variantes[0] ?? null;\n    return variantes.find((v) => grupos.every((g) => norm(v.attributes?.[g.code]) === norm(eleccion[g.code]))) ?? null;\n  };\n\n  /**\n   * ¿EXISTE la combinación con ese valor? (aunque esté agotada) y ¿tiene unidades AHORA?\n   *\n   * Se miran SOLO los ejes ya elegidos, que es como funciona en todas partes: al tocar «Blanco», las\n   * tallas se recalculan y las que no existan para blanco se apagan; al cambiar a «Rojo» se liberan\n   * otras. Si se miraran todos los ejes, ningún valor se podría elegir nunca.\n   */\n  const combosCon = (code: string, value: string) => {\n    const cand = { ...sel, [code]: value };\n    const codigos = grupos.map((g) => g.code).filter((c) => cand[c]);\n    return variantes.filter((v) => codigos.every((c) => norm(v.attributes?.[c]) === norm(cand[c])));\n  };\n  const existeCombo = (code: string, value: string) => !variantes.length || combosCon(code, value).length > 0;\n  const disponible = (code: string, value: string) => !variantes.length || combosCon(code, value).some(conStock);\n\n  const faltan = grupos.filter((g) => !sel[g.code]).map((g) => g.label);\n  const eleccionCompleta = faltan.length === 0;\n  const elegida = eleccionCompleta ? varianteDe(sel) : null;\n  /** La combinación existe pero ahora mismo no tiene unidades. */\n  const agotada = eleccionCompleta && !!elegida && !conStock(elegida);\n\n  /**\n   * El precio: el de la combinación elegida; si hay precios distintos entre combinaciones y todavía\n   * no se ha elegido nada, el RANGO (que es lo honesto: el anuncio no tiene un precio único); si no,\n   * el del anuncio.\n   */\n  const precios = useMemo(() => {\n    const lista = variantes\n      .map((v) => (v.priceXaf ?? product.priceXaf))\n      .filter((n): n is number => typeof n === 'number' && Number.isFinite(n));\n    return [...new Set(lista)].sort((a, b) => a - b);\n  }, [variantes, product.priceXaf]);\n  const precioElegido = elegida?.priceXaf ?? null;\n  const hayRango = !eleccionCompleta && precios.length > 1;\n  const precioSuelto = Number.isFinite(product.priceXaf) ? product.priceXaf : null;\n\n  const tope = elegida ? Number(elegida.stockQuantity ?? 0) : Number(product.stock ?? 0);\n  /** Al cambiar de combinación la cantidad tiene que caber en la nueva: solo se recorta, nunca sube. */\n  useEffect(() => {\n    setCant((c) => Math.min(c, Math.max(1, tope)));\n  }, [tope]);\n  const pocoStock = tope > 0 && tope < 10;\n  const stockTexto = agotada\n    ? 'Agotada en esa combinación'\n    : tope > 0\n      ? (pocoStock ? `Quedan pocas unidades (${tope})` : `Stock: ${tope}`)\n      : 'Sin stock';\n\n  /**\n   * La foto que se enseña: la de la combinación elegida; si no, la del color elegido; si no, la\n   * primera del anuncio. Las dos primeras son URLs del **mismo saco** que `photos` (el servidor\n   * exige que la foto de un color sea una de las fotos del anuncio), así que se usan tal cual, sin\n   * recomponer la ruta.\n   */\n  const foto = useMemo(() => {\n    if (elegida?.imageUrl) return elegida.imageUrl;\n    for (const g of grupos) {\n      if (g.kind !== 'color') continue;\n      const v = (g.values ?? []).find((x) => x.value === sel[g.code]);\n      if (v?.imageUrl) return v.imageUrl;\n    }\n    return (product.photos ?? [])[0] ?? null;\n  }, [elegida, grupos, sel, product.photos]);\n\n  const resumen = grupos.filter((g) => sel[g.code]).map((g) => `${g.label}: ${sel[g.code]}`).join(' · ');\n  const puedeConfirmar = eleccionCompleta && !agotada && tope > 0;\n\n  const principal: ModoSelector = modoInicial;\n  const secundario: ModoSelector = modoInicial === 'carrito' ? 'comprar' : 'carrito';\n  const confirmar = (modo: ModoSelector) => (modo === 'carrito'\n    ? onCarrito({ variant: elegida, cantidad: cant })\n    : onComprar({ variant: elegida, cantidad: cant }));\n\n  /** Un bloque de eje: color con SU foto, o valores como botones. */\n  const Eje = ({ g }: { g: EcomerseOptionGroup }) => (\n    <View style={{ marginTop: espaciado.e12 }}>\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: peso.fuerte, marginBottom: espaciado.e4 }}>\n        {g.label}\n        {sel[g.code]\n          ? <Text style={{ color: colors.textSecondary, fontWeight: peso.medio }}>{`  ${sel[g.code]}`}</Text>\n          : null}\n      </Text>\n      <View style={estilos.valores}>\n        {(g.values ?? []).map((v) => {\n          const activo = sel[g.code] === v.value;\n          const existe = existeCombo(g.code, v.value);\n          /**\n           * AGOTADO = la combinación existe pero no tiene unidades. NO se puede elegir (se ve apagado\n           * y tachado), pero sí tocar para que la hoja explique por qué.\n           */\n          const agotadoAqui = existe && !disponible(g.code, v.value);\n          const libre = existe && !agotadoAqui;\n          const etiqueta = `${g.label} ${v.value}${!existe ? ' (no disponible)' : agotadoAqui ? ' (agotado)' : ''}`;\n          const onPress = () => {\n            if (libre) { setSel((p) => ({ ...p, [g.code]: v.value })); setNota(null); return; }\n            setNota({ code: g.code, value: v.value, agotado: agotadoAqui });\n          };\n          if (g.kind === 'color') {\n            return (\n              <Pressable\n                key={v.value}\n                onPress={onPress}\n                accessibilityLabel={etiqueta}\n                accessibilityState={{ selected: activo, disabled: !libre }}\n                style={[estilos.colorCaja, {\n                  borderColor: activo ? colors.primary : alpha(colors.border, 0.9),\n                  borderWidth: activo ? trazo.fuerte : trazo.fino,\n                  backgroundColor: activo ? alpha(colors.primary, 0.08) : 'transparent',\n                  opacity: libre ? 1 : 0.45,\n                }]}\n              >\n                {/* LA FOTO REAL del anuncio en ese color: no un cuadradito de color. */}\n                {v.imageUrl ? (\n                  <Image\n                    source={v.imageUrl}\n                    style={estilos.colorImg}\n                    contentFit=\"cover\"\n                    cachePolicy=\"memory-disk\"\n                    transition={0}\n                  />\n                ) : (\n                  <View style={[estilos.colorImg, estilos.sinFoto, { backgroundColor: alpha(colors.border, 0.4) }]}>\n                    <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>sin foto</Text>\n                  </View>\n                )}\n                <Text numberOfLines={1} style={{\n                  color: activo ? colors.primary : colors.textPrimary,\n                  fontSize: tipografia.micro, fontWeight: peso.fuerte,\n                  marginTop: espaciado.e4, maxWidth: 68, textAlign: 'center',\n                }}>\n                  {v.value}\n                </Text>\n                {agotadoAqui ? (\n                  <Text style={{ color: colors.danger, fontSize: tipografia.micro, fontWeight: peso.fuerte }}>agotado</Text>\n                ) : null}\n              </Pressable>\n            );\n          }\n          return (\n            <Pressable\n              key={v.value}\n              onPress={onPress}\n              accessibilityLabel={etiqueta}\n              accessibilityState={{ selected: activo, disabled: !libre }}\n              style={[estilos.chip, {\n                borderColor: activo ? colors.primary : alpha(colors.border, 0.9),\n                backgroundColor: activo ? alpha(colors.primary, 0.1) : 'transparent',\n                opacity: libre ? 1 : 0.45,\n              }]}\n            >\n              <Text style={{\n                color: activo ? colors.primary : colors.textPrimary,\n                fontSize: tipografia.caption, fontWeight: peso.fuerte,\n                textDecorationLine: libre ? 'none' : 'line-through',\n              }}>\n                {v.value}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {/* Por qué un valor no se deja elegir. Sustituye al «avísame cuando llegue» de Life Book, que\n          aquí no tiene servidor que lo apunte. Las dos frases valen tanto si el comprador ya ha\n          elegido otro eje como si no: decir «con lo que has elegido» mentiría cuando no hay nada\n          elegido, que es justo el primer toque que recibe la hoja. */}\n      {nota?.code === g.code ? (\n        <View style={[estilos.nota, { borderColor: alpha(colors.danger, 0.5), backgroundColor: alpha(colors.danger, 0.06) }]}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, flex: 1 }}>\n            {nota.agotado\n              ? `«${nota.value}» no tiene unidades disponibles.`\n              : `«${nota.value}» no está disponible en este anuncio.`}\n          </Text>\n          <Pressable onPress={() => setNota(null)} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Entendido\">\n            <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: peso.titulo }}>Entendido</Text>\n          </Pressable>\n        </View>\n      ) : null}\n    </View>\n  );\n\n  return (\n    <Sheet\n      visible={visible}\n      position=\"bottom\"\n      title=\"Elige la combinación\"\n      onClose={onClose}\n    >\n      {/* ── Cabecera: la foto de lo elegido, su precio y su stock ── */}\n      <View style={{ flexDirection: 'row', alignItems: 'flex-start' }}>\n        {foto ? (\n          <Image source={foto} style={[estilos.foto, { borderColor: alpha(colors.border, 0.8) }]} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n        ) : (\n          <View style={[estilos.foto, estilos.sinFoto, { borderColor: alpha(colors.border, 0.8), backgroundColor: alpha(colors.primary, 0.1) }]}>\n            <Text style={{ fontSize: ilustracion.md }}>📦</Text>\n          </View>\n        )}\n        <View style={{ flex: 1, marginLeft: espaciado.e12 }}>\n          {/* El nombre, aquí y a una línea: ver el porqué de `altoLista`. */}\n          <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: peso.fuerte, marginBottom: espaciado.e2 }}>\n            {product.title}\n          </Text>\n          {precioElegido !== null || !hayRango ? (\n            <Precio\n              valor={precioElegido ?? precioSuelto}\n              tamano=\"lg\"\n              textoVacio=\"A consultar\"\n              color={agotada ? colors.textSecondary : undefined}\n            />\n          ) : (\n            /* Un rango no es una cifra: son dos, y el componente de precio pinta una. Va como frase\n               (con `numberOfLines={1}`, que es lo que impide que se parta por la mitad). */\n            <Text numberOfLines={1} style={{ color: colors.primary, fontSize: tipografia.title, fontWeight: peso.titulo }}>\n              {`${formatXAF(precios[0])} – ${formatXAF(precios[precios.length - 1])}`}\n            </Text>\n          )}\n          {/* A UNA línea, y no por estética: si el resumen puede ocupar dos, la columna de texto\n              supera los 92 dp de la foto, la cabecera crece con ella y **vuelve a empujar los\n              botones**. A una línea la cabecera la manda la foto, que es de alto fijo. El resumen\n              tampoco pierde nada: cada eje enseña arriba el valor elegido. */}\n          <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.caption, marginTop: espaciado.e4 }}>\n            {resumen}\n          </Text>\n          <Text style={{ color: agotada ? colors.danger : colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }}>\n            {stockTexto}\n          </Text>\n        </View>\n      </View>\n\n      <ScrollView style={{ maxHeight: altoLista }} showsVerticalScrollIndicator={false}>\n        {grupos.map((g) => <Eje key={g.code} g={g} />)}\n\n        {/* ── Cantidad, con el tope REAL de la combinación (no un 99 inventado) ── */}\n        <View style={{ marginTop: espaciado.e16, flexDirection: 'row', alignItems: 'center' }}>\n          <View style={{ flex: 1 }}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: peso.fuerte }}>Cantidad</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\n              {elegida ? `Máx. ${tope}` : ''}\n            </Text>\n          </View>\n          <View style={[estilos.stepper, { borderColor: alpha(colors.border, 0.9) }]}>\n            <Pressable\n              onPress={() => setCant((c) => Math.max(1, c - 1))}\n              disabled={cant <= 1}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Quitar una unidad\"\n              style={estilos.stepBtn}\n            >\n              <Minus size={icono.sm} color={cant <= 1 ? alpha(colors.textSecondary, 0.5) : colors.textPrimary} />\n            </Pressable>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: peso.fuerte, minWidth: 30, textAlign: 'center' }}>{cant}</Text>\n            <Pressable\n              onPress={() => setCant((c) => Math.min(Math.max(tope, 1), c + 1))}\n              disabled={cant >= Math.max(tope, 1)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Añadir una unidad\"\n              style={estilos.stepBtn}\n            >\n              <Plus size={icono.sm} color={cant >= Math.max(tope, 1) ? alpha(colors.textSecondary, 0.5) : colors.textPrimary} />\n            </Pressable>\n          </View>\n        </View>\n\n        {faltan.length ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>\n            Elige: {faltan.join(' · ')}\n          </Text>\n        ) : null}\n        {agotada ? (\n          <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>\n            Esa combinación está agotada. Prueba otra.\n          </Text>\n        ) : null}\n      </ScrollView>\n\n      {/* ── Los botones: el de la acción con la que se abrió, en grande ── */}\n      <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n        <Pressable\n          onPress={() => confirmar(secundario)}\n          disabled={!puedeConfirmar}\n          accessibilityRole=\"button\"\n          accessibilityLabel={secundario === 'carrito' ? 'Añadir al carrito' : 'Comprar ahora'}\n          accessibilityState={{ disabled: !puedeConfirmar }}\n          style={[estilos.secBtn, { borderColor: colors.primary, opacity: puedeConfirmar ? 1 : 0.45 }]}\n        >\n          <Text numberOfLines={1} style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: peso.titulo }}>\n            {secundario === 'carrito' ? 'Al carrito' : 'Comprar ahora'}\n          </Text>\n        </Pressable>\n        <Pressable\n          onPress={() => confirmar(principal)}\n          disabled={!puedeConfirmar}\n          accessibilityRole=\"button\"\n          accessibilityLabel={principal === 'carrito' ? 'Añadir al carrito' : 'Comprar ahora'}\n          accessibilityState={{ disabled: !puedeConfirmar }}\n          style={[estilos.priBtn, { backgroundColor: puedeConfirmar ? colors.primary : alpha(colors.primary, 0.4) }]}\n        >\n          <Text numberOfLines={1} style={{ color: brand.white, fontSize: tipografia.body, fontWeight: peso.titulo }}>\n            {principal === 'carrito' ? 'Añadir al carrito' : 'Comprar ahora'}\n          </Text>\n        </Pressable>\n      </View>\n    </Sheet>\n  );\n}\n\nconst estilos = StyleSheet.create({\n  foto: { width: 92, height: 92, borderRadius: radios.md, borderWidth: trazo.fino, overflow: 'hidden' },\n  sinFoto: { alignItems: 'center', justifyContent: 'center' },\n  valores: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  colorCaja: { alignItems: 'center', borderRadius: radios.sm, padding: espaciado.e4 },\n  colorImg: { width: 58, height: 58, borderRadius: radios.sm },\n  chip: {\n    borderWidth: trazo.fino, borderRadius: radios.sm,\n    paddingHorizontal: espaciado.e12, minHeight: altura.punto, minWidth: 46,\n    alignItems: 'center', justifyContent: 'center',\n  },\n  stepper: { flexDirection: 'row', alignItems: 'center', borderWidth: trazo.fino, borderRadius: radios.sm, paddingHorizontal: espaciado.e4, minHeight: altura.punto },\n  stepBtn: { width: altura.punto, height: altura.punto, alignItems: 'center', justifyContent: 'center' },\n  nota: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderWidth: trazo.fino, borderRadius: radios.md, padding: espaciado.e8, marginTop: espaciado.e8 },\n  secBtn: { flex: 1, height: altura.control, borderRadius: radios.md, borderWidth: trazo.base, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e8 },\n  priBtn: { flex: 1.4, height: altura.control, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e12 },\n});\n","/**\n * Utilidades de teléfono para Guinea Ecuatorial.\n * Normaliza un número local a MSISDN internacional (240 + 9 dígitos).\n * No adivina: devuelve null ante formatos raros o extranjeros.\n */\nexport function toGqMsisdn(phone: string): string | null {\n  const d = phone.replace(/\\D/g, '');\n  if (d.length === 12 && d.startsWith('240')) return d;\n  if (d.length === 10 && d.startsWith('0')) return `240${d.slice(1)}`;\n  if (d.length === 9) return `240${d}`;\n  return null;\n}\n\n/** ¿El teléfono parece un número de GQ válido? (para avisar sin bloquear). */\nexport function looksLikeGqPhone(phone: string): boolean {\n  return toGqMsisdn(phone) !== null;\n}\n","/**\n * CabeceraTienda — la tarjeta de una tienda: quién vende, con qué respaldo y cómo contactarle.\n *\n * POR QUÉ EXISTE: la ficha ya tenía esta tarjeta, escrita a mano dentro de la pantalla, y la\n * página de tienda necesitaba **la misma**. Escribirla dos veces es exactamente el camino que ya\n * costó caro con el precio —cuatro sitios, tres tratamientos para el mismo dato—, así que aquí hay\n * una definición y dos consumidores.\n *\n * Y HABÍA UN SEGUNDO MOTIVO, MÁS IMPORTANTE QUE EL PRIMERO: en la ficha esta tarjeta **no llevaba\n * a ninguna parte**. El comprador veía quién vende («Abacería E2E v3», PRO, escudo verificado,\n * valoración, ciudad) y no podía ver **qué más vende**. Era el mejor sitio de la app para entrar a\n * una tienda y era un callejón sin salida. `onPress` es esa puerta.\n *\n * QUÉ DECIDE ESTE FICHERO Y QUÉ DECIDEN LOS QUE LO USAN:\n *   · Aquí: qué se enseña de una tienda y con qué jerarquía (nombre, PRO, escudo solo si es real,\n *     valoración solo si hay valoraciones, ciudad, anuncios) y el tratamiento del avatar.\n *   · Fuera: **si la tarjeta es puerta** (`onPress`) y **si se puede llamar** (`onLlamar`). Sin\n *     props, es información y no un botón: la pantalla que no conoce la acción no la inventa.\n *\n * DOS HONESTIDADES QUE SE CONSERVAN DE LA FICHA:\n *   · La valoración **no se inventa**. `★ 5,0 · 0 valoraciones` sobre una tienda sin ninguna era el\n *     defecto original; aquí, sin valoraciones, la línea no se pinta.\n *   · El escudo es de `verified`, que es KYC aprobado de verdad (lo resuelve el servidor). Un sello\n *     que se pinta solo por tener cuenta no es un sello.\n *\n * El **avatar es la inicial**, no una foto: `seller.photoKey` es una clave del almacenamiento y la\n * app no tiene resuelta su URL pública en ninguna pantalla. Inventar aquí un `https://…/photoKey`\n * sería pintar una imagen rota en el peor sitio. El día que exista el resolutor, se cambia solo\n * aquí y lo heredan la ficha y la tienda.\n */\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { ChevronRight, Phone, ShieldCheck } from 'lucide-react-native';\nimport { alpha, brand, espaciado, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport type { EcomerseSellerBrief } from '../../api/ecomerse';\n\nexport interface CabeceraTiendaProps {\n  seller: EcomerseSellerBrief | null | undefined;\n  /** Anuncios activos, si la pantalla los cuenta. Sin el dato no se pinta la cifra: un «0» diría\n   *  que la tienda no vende nada, y no saberlo no es lo mismo que saberlo. */\n  anuncios?: number;\n  /** Con esto la tarjeta es una puerta a la tienda. */\n  onPress?: () => void;\n  /** Con esto aparece el botón de llamar. */\n  onLlamar?: () => void;\n}\n\nexport function CabeceraTienda({ seller, anuncios, onPress, onLlamar }: CabeceraTiendaProps) {\n  const { colors } = useTheme();\n  const s = styles(colors);\n\n  const nombre = seller?.businessName ?? 'Vendedor';\n  const ratingCount = seller?.ratingCount ?? 0;\n  const ratingAvg = seller?.ratingAvg;\n  const verificado = seller?.verified === true;\n  const pro = seller?.badge === 'Pro';\n  const ciudad = seller?.city ?? '—';\n\n  const contenido = (\n    <>\n      <View style={[s.avatar, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n        <Text style={[s.inicial, { color: colors.primary }]}>{nombre.charAt(0).toUpperCase()}</Text>\n      </View>\n\n      <View style={s.textos}>\n        <View style={s.filaNombre}>\n          <Text style={s.nombre} numberOfLines={1}>{nombre}</Text>\n          {pro && <View style={s.tagPro}><Text style={s.tagProText}>PRO</Text></View>}\n          {verificado && <ShieldCheck size={13} color={brand.success} />}\n        </View>\n        <Text style={s.meta}>\n          {ratingCount > 0 && Number.isFinite(ratingAvg)\n            ? `★ ${Number(ratingAvg).toFixed(1)} · ${ratingCount} valoracion${ratingCount === 1 ? '' : 'es'}`\n            /* El texto de «sin valoraciones» NO es nuevo: venía de la ficha, y se conserva tal cual.\n               Un hueco vacío donde iría la valoración se lee como «no ha cargado», y una tienda\n               nueva se lee como «poco fiable». Decir que es nueva es información, y es verdad. */\n            : 'Nuevo en EG · sin valoraciones todavía'}\n        </Text>\n        <Text style={s.meta}>\n          📍 {ciudad}{anuncios !== undefined ? ` · ${anuncios} anuncio${anuncios === 1 ? '' : 's'}` : ''}\n        </Text>\n      </View>\n\n      {onLlamar && (\n        <Pressable\n          onPress={onLlamar}\n          hitSlop={8}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Llamar al vendedor\"\n          style={[s.redondo, { backgroundColor: alpha(colors.primary, 0.1) }]}\n        >\n          <Phone size={16} color={colors.primary} />\n        </Pressable>\n      )}\n\n      {onPress && <ChevronRight size={18} color={colors.textSecondary} />}\n    </>\n  );\n\n  const caja = [s.caja, { backgroundColor: colors.surface, borderColor: colors.border }];\n\n  return onPress ? (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`Ver la tienda ${nombre}`}\n      style={caja}\n    >\n      {contenido}\n    </Pressable>\n  ) : (\n    <View style={caja}>{contenido}</View>\n  );\n}\n\n/**\n * Dos cambios visuales respecto a la versión que ya estaba verificada en la ficha, dichos para que\n * no sorprendan al comparar capturas:\n *   · **Borde.** La tarjeta vivía sobre `surface` sin borde y apenas se distinguía del fondo de la\n *     pantalla; con `borderColor` el bloque se lee como una pieza, que es lo que es.\n *   · **El sello PRO baja de 800 a 700.** El 800 no está en la escala `peso` y meterlo aquí habría\n *     subido la deuda del trinquete para pintar tres letras de 11 dp, donde la diferencia no se ve.\n */\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  caja: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    padding: espaciado.e12,\n  },\n  avatar: { width: 44, height: 44, borderRadius: radios.full, alignItems: 'center', justifyContent: 'center' },\n  inicial: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  textos: { flex: 1, marginLeft: espaciado.e12 },\n  filaNombre: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5 },\n  nombre: { flexShrink: 1, fontSize: tipografia.body, fontWeight: peso.fuerte, color: c.textPrimary },\n  meta: { fontSize: tipografia.micro, color: c.textSecondary, marginTop: espaciado.e2 },\n  tagPro: { backgroundColor: alpha(brand.primary, 0.12), borderRadius: radios.sm, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  /** `fuerte` (700) y no el 800 que llevaba la ficha: el 800 no está en la escala `peso`, y meterlo\n   *  aquí habría subido la deuda del trinquete para pintar tres letras. La diferencia entre 700 y\n   *  800 en un sello de 11 dp no se ve; la deuda, sí. */\n  tagProText: { color: brand.primary, fontSize: tipografia.micro, fontWeight: peso.fuerte },\n  redondo: { width: 34, height: 34, borderRadius: radios.full, alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * BotonPreguntarTienda — la puerta al chat con una tienda desde fuera de Mensajes.\n *\n * ── POR QUÉ ES UN COMPONENTE Y NO DOS BOTONES ─────────────────────────────────────────────────\n * Los dos sitios que la necesitan —la ficha de un anuncio y la página de la tienda— comparten algo\n * más que el dibujo: la SECUENCIA. Abrir el hilo contra `POST /ecomerse/chats/open`, y sólo cuando\n * el servidor contesta, navegar al chat llevando el `conversationId` y los datos de la tienda. Esa\n * secuencia tiene cuatro ramas que se olvidan con facilidad —sin sesión, abriendo, error de red y\n * el caso raro de una tienda que ya no existe—, y escrita dos veces la segunda acabaría con una\n * rama de menos. Es el mismo criterio que ya se aplicó con `CabeceraTienda` y con el precio.\n *\n * ── NO SE NAVEGA «A CIEGAS»: SE ESPERA AL SERVIDOR, Y ESO TIENE UNA VENTAJA ────────────────────\n * La alternativa —entrar al chat con los datos que ya tiene la pantalla y abrir el hilo luego—\n * dejaría al comprador dentro de una conversación sin `conversationId`, que no puede pedir\n * mensajes ni enviarlos: una pantalla muerta por un instante. Esperando, el chat abre con hilo de\n * verdad. Y trae un regalo: el `seller` que devuelve el servidor trae `photoUrl` **ya resuelta**\n * (la clave del almacenamiento convertida en URL), cosa que la ficha no tiene —allí el vendedor\n * llega con `photoKey`—. Por eso la cabecera del chat puede enseñar el LOGO de la tienda abierta\n * desde la ficha, que hasta ahora habría caído a la inicial.\n *\n * ── `productId` ES OPCIONAL, Y SU EFECTO LO DECIDE EL SERVIDOR ────────────────────────────────\n * Con `productId`, el primer mensaje cita el anuncio («me interesa esto») y **sólo** si el hilo\n * estaba vacío y el anuncio es de esa tienda. La pantalla no deduce nada ni compone el texto: las\n * dos condiciones son del servidor, y si se cumplen mandan un mensaje de verdad, firmado por el\n * comprador, que la tienda ve como cualquier otro. Inventarlo aquí sería escribir en nombre de\n * alguien desde el cliente.\n *\n * ── NO REGISTRA `contactIntent`, Y ES DELIBERADO ──────────────────────────────────────────────\n * La ficha registra un lead cuando se llama o se abre WhatsApp porque esas conversaciones ocurren\n * FUERA de la app y no dejan rastro. Un mensaje por el chat no: queda escrito en\n * `lifebook.messages` con su autor y su fecha, que es prueba más fuerte que una fila de lead. Meter\n * además un lead sería contar dos veces el mismo interés —y `contact/intent` sólo conoce los canales\n * `whatsapp` y `call`, así que habría que tocar la restricción de una tabla ya cerrada para anotar\n * algo que la tabla del chat ya dice—.\n *\n * ── EL ESCAPE A WHATSAPP NO DESAPARECE ───────────────────────────────────────────────────────\n * La decisión 5.b del plan es que el chat es la puerta PRINCIPAL y WhatsApp el ESCAPE visible. Esto\n * es la puerta; el escape vive donde se está mirando, que es la cabecera del propio chat, y sigue\n * donde ya estaba en la barra de la ficha. Un escape que no está donde estás no sirve.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { ChevronRight, MessageCircle } from 'lucide-react-native';\nimport { alpha, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi } from '../../api/ecomerse';\nimport { ApiError } from '../../api/httpClient';\nimport { useSession } from '../../state/session';\n\nexport interface BotonPreguntarTiendaProps {\n  /** La TIENDA, no su dueño. El servidor resuelve el interlocutor: el botón no puede escribirle a\n   *  quien no es. */\n  sellerId: string | null | undefined;\n  /** El anuncio del que viene el interés, si se sabe. Sin él, el primer mensaje no cita nada. */\n  productId?: string | null;\n  /** Nombre de reserva para la cabecera del chat mientras el servidor contesta. */\n  nombre?: string | null;\n  /** Teléfono de reserva para el escape a WhatsApp. El del servidor manda si viene. */\n  telefono?: string | null;\n  /** Separación con lo de arriba, si el contenedor del llamante no la da (un `gap`, por ejemplo). */\n  style?: StyleProp<ViewStyle>;\n}\n\nexport function BotonPreguntarTienda({ sellerId, productId, nombre, telefono, style }: BotonPreguntarTiendaProps) {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const { isAuthenticated } = useSession();\n  const [abriendo, setAbriendo] = useState(false);\n  const s = styles(colors);\n\n  const abrir = useCallback(() => {\n    if (!sellerId) return;\n    if (!isAuthenticated) {\n      Alert.alert(\n        'Entra en tu cuenta',\n        'Para escribir a la tienda hace falta sesión: la conversación es tuya y tiene que ir con tu nombre.',\n        [{ text: 'Ahora no', style: 'cancel' }, { text: 'Iniciar sesión', onPress: () => router.push('/auth' as never) }],\n      );\n      return;\n    }\n    void (async () => {\n      setAbriendo(true);\n      try {\n        const abierto = await ecomerseApi.openChat(sellerId, productId ?? null);\n        /* `push` y no `replace`: el comprador entra al chat DESDE la ficha y la flecha tiene que\n           devolverlo a la ficha, no dejarlo en Mensajes. La ruta es la misma que usa la lista de\n           Mensajes (`irAlChatDeTienda`), y a propósito: un solo destino significa que un arreglo en\n           la pantalla del chat vale para las dos entradas. */\n        router.push({\n          pathname: '/ecomerse-mensajes-chat',\n          params: {\n            conv: abierto.conversationId,\n            tienda: abierto.seller.businessName ?? nombre ?? '',\n            foto: abierto.seller.photoUrl ?? '',\n            telefono: abierto.seller.phoneContact ?? telefono ?? '',\n            /* Los parámetros de navegación son texto: un `false` se perdería. */\n            ...(abierto.seller.verified ? { verificado: '1' } : {}),\n          },\n        } as never);\n      } catch (e) {\n        /* EL MOTIVO DEL SERVIDOR SE ENSEÑA, no se tapa con un genérico. Los tres rechazos posibles ya\n           están escritos para que los lea el comprador —«Esa es tu propia tienda.», «No puedes\n           escribir a esta tienda.»— y cambiarlos por «no se pudo abrir» convertiría un caso claro en\n           un misterio. Es el patrón que ya usan `auth.tsx` y la zona de KYC. */\n        const motivo = e instanceof ApiError && e.message\n          ? e.message\n          : 'No se pudo abrir la conversación. Revisa tu conexión e inténtalo otra vez.';\n        Alert.alert('Chat', motivo);\n      } finally {\n        setAbriendo(false);\n      }\n    })();\n  }, [sellerId, productId, nombre, telefono, isAuthenticated, router]);\n\n  /* Sin tienda no hay a quién escribir: no se pinta un botón que no puede llevar a ninguna parte. */\n  if (!sellerId) return null;\n\n  return (\n    <Pressable\n      onPress={abrir}\n      disabled={abriendo}\n      accessibilityRole=\"button\"\n      accessibilityLabel={\n        nombre ? `Preguntar a la tienda ${nombre}` : 'Preguntar a la tienda'\n      }\n      accessibilityHint=\"Abre una conversación con la tienda dentro de la app\"\n      accessibilityState={{ busy: abriendo }}\n      style={({ pressed }) => [s.caja, style, { backgroundColor: colors.surface, opacity: pressed ? 0.75 : 1 }]}\n    >\n      <View style={[s.icono, { backgroundColor: alpha(colors.primary, 0.12) }]}>\n        <MessageCircle size={icono.sm} color={colors.primary} />\n      </View>\n      <View style={s.textos}>\n        <Text style={[s.titulo, { color: colors.textPrimary }]}>\n          {abriendo ? 'Abriendo la conversación…' : 'Preguntar a la tienda'}\n        </Text>\n        <Text style={[s.nota, { color: colors.textSecondary }]}>\n          Te contesta aquí, en Mensajes\n        </Text>\n      </View>\n      {abriendo ? (\n        <ActivityIndicator size=\"small\" color={colors.primary} />\n      ) : (\n        <ChevronRight size={icono.sm} color={colors.textSecondary} />\n      )}\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  /* Sin `marginTop`: la separación con lo de arriba la pone quien lo coloca. La ficha y la página de\n     tienda agrupan a distinto —una con márgenes, otra con `gap`—, y un margen propio aquí se sumaría\n     al `gap` de una de las dos y no a la otra. El componente no sabe quién tiene al lado. */\n  caja: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    borderColor: c.border,\n    padding: espaciado.e12,\n  },\n  icono: {\n    width: 36,\n    height: 36,\n    borderRadius: radios.md,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  textos: { flex: 1 },\n  titulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  nota: { fontSize: tipografia.micro, marginTop: espaciado.e4 },\n});\n","/**\n * Llamar a un vendedor desde cualquier pantalla.\n *\n * POR QUÉ ESTÁ FUERA DE LAS PANTALLAS: la ficha ya tenía su propia copia y la página de tienda\n * necesitaba la misma. Dos copias de un `Linking.openURL('tel:')` no es un drama, pero el número\n * **sí** tiene reglas propias en este país (9 dígitos, prefijo 0 local, 240 internacional) y esas\n * reglas viven en `toGqMsisdn`. Pasarlas por alto en una copia sería abrir el marcador con un\n * número roto; llamándolas desde aquí, no hay copia que se desvíe.\n *\n * No lleva `contactIntent`: eso es un **lead ligado a un anuncio** y solo lo puede registrar la\n * ficha, que es la única que sabe de qué anuncio se trata. La tienda llama y ya.\n */\nimport { Alert, Linking } from 'react-native';\nimport { toGqMsisdn } from './phone';\n\n/**\n * Devuelve `true` **solo si se llegó a abrir el marcador**. Importa: la ficha registra el lead\n * (`contactIntent`) cuando el comprador llama, y registrar una llamada que nunca salió —porque el\n * número estaba mal— sería ensuciar la estadística del vendedor con un intento que no existió.\n */\nexport async function llamarTelefono(phone: string): Promise<boolean> {\n  const cc = toGqMsisdn(phone);\n  if (!cc) {\n    Alert.alert('Llamar', 'Este vendedor no tiene un número válido.');\n    return false;\n  }\n  try {\n    await Linking.openURL(`tel:+${cc}`);\n    return true;\n  } catch {\n    Alert.alert('Llamar', 'No se pudo abrir el marcador.');\n    return false;\n  }\n}\n","/**\n * Formulario de una dirección — alta y edición (Fase 2 del pie del Mercado).\n *\n * UNA PANTALLA PARA LAS DOS COSAS, PORQUE SON LA MISMA COSA\n * Con `?id=` edita y sin él crea. Los campos son los mismos y las reglas también, así que separarlas\n * en dos ficheros garantizaría que un día divergieran (una validaría el teléfono y la otra no).\n *\n * LA CIUDAD NO SE TECLEA, SE ELIGE — Y LAS CIUDADES SALEN DE LAS ZONAS\n * No hay una lista de ciudades escrita a mano en ninguna parte: se piden TODAS las zonas de reparto\n * (`deliveryZones()` sin filtro) y las ciudades son las que aparecen en ellas. Si mañana se abre\n * reparto en otra ciudad, aparece aquí sola. Lo mismo con las zonas: al elegir ciudad se ofrecen\n * SÓLO las suyas, que es lo que el servidor exige (una dirección de Malabo con zona de Bata se\n * rechaza, porque cobraría la tarifa de otra ciudad).\n *\n * LA ZONA ES OPCIONAL, Y SE DICE\n * Se puede guardar la dirección sin zona («te la piden al pagar»). El checkout vuelve a preguntarla\n * en ese caso, en vez de inventarse una tarifa.\n *\n * LA PREDETERMINADA SÓLO SE MARCA, NUNCA SE DESMARCA DESDE AQUÍ\n * Mandar `isDefault: false` dejaría la agenda con direcciones pero sin ninguna elegida, y eso no le\n * sirve a nadie: para cambiar de predeterminada se marca OTRA. Por eso el cuerpo sólo lleva\n * `isDefault` cuando vale `true`, y editar el teléfono no toca la bandera.\n */\n\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Check } from 'lucide-react-native';\nimport {\n  FormField, PrimaryButton, brand, espaciado, icono, peso, radios, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseAddressInput, type EcomerseDeliveryZone } from '../api/ecomerse';\n\nconst ETIQUETAS = ['Casa', 'Trabajo', 'Otro'] as const;\n\nconst mensajeDe = (e: unknown): string =>\n  e instanceof Error && e.message ? e.message : 'No se pudo guardar. Inténtalo otra vez.';\n\nexport default function EcomerseDireccionScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { id } = useLocalSearchParams<{ id?: string }>();\n  const editando = typeof id === 'string' && id.length > 0;\n\n  const [zonas, setZonas] = useState<EcomerseDeliveryZone[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [busy, setBusy] = useState(false);\n\n  const [recipient, setRecipient] = useState('');\n  const [phone, setPhone] = useState('');\n  const [city, setCity] = useState('');\n  const [zoneId, setZoneId] = useState('');\n  const [detail, setDetail] = useState('');\n  const [landmark, setLandmark] = useState('');\n  const [label, setLabel] = useState('');\n  const [isDefault, setIsDefault] = useState(false);\n\n  /** Las ciudades que tienen reparto, derivadas de las zonas. Sin lista escrita a mano. */\n  const ciudades = useMemo(() => {\n    const m = new Map<string, EcomerseDeliveryZone[]>();\n    for (const z of zonas) m.set(z.city, [...(m.get(z.city) ?? []), z]);\n    return [...m.entries()];\n  }, [zonas]);\n\n  const zonasDeCiudad = useMemo(() => ciudades.find(([c]) => c === city)?.[1] ?? [], [ciudades, city]);\n\n  useEffect(() => {\n    let vivo = true;\n    (async () => {\n      try {\n        const [todasZonas, direcciones] = await Promise.all([\n          ecomerseApi.deliveryZones(),\n          editando ? ecomerseApi.addresses() : Promise.resolve([]),\n        ]);\n        if (!vivo) return;\n        setZonas(todasZonas);\n        /* La ciudad por defecto: la de la primera zona que exista. Así el formulario nace usable\n           sin que el comprador tenga que elegir de una lista de una sola opción. */\n        setCity((c) => c || todasZonas[0]?.city || '');\n        if (editando) {\n          const d = direcciones.find((x) => x.id === id);\n          if (!d) {\n            Alert.alert('Dirección no encontrada', 'Puede que la hayas borrado desde otro sitio.', [\n              { text: 'Vale', onPress: () => router.back() },\n            ]);\n            return;\n          }\n          setRecipient(d.recipient); setPhone(d.phone); setCity(d.city);\n          setZoneId(d.zoneId ?? ''); setDetail(d.detail);\n          setLandmark(d.landmark ?? ''); setLabel(d.label ?? ''); setIsDefault(d.isDefault);\n        }\n      } catch (e) {\n        if (vivo) Alert.alert('No se pudo abrir', mensajeDe(e));\n      } finally {\n        if (vivo) setCargando(false);\n      }\n    })();\n    return () => { vivo = false; };\n    // `id` y `editando` son la identidad de la pantalla: no cambian sin remontarla.\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [id]);\n\n  /** Al cambiar de ciudad se suelta la zona si era de la otra: una zona de Bata con ciudad Malabo\n   *  la rechaza el servidor, así que es mejor no dejar construir esa combinación. */\n  const elegirCiudad = (c: string) => {\n    setCity(c);\n    const z = zonas.find((x) => x.id === zoneId);\n    if (z && z.city !== c) setZoneId('');\n  };\n\n  const guardar = useCallback(async () => {\n    const r = recipient.trim(), t = phone.trim(), d = detail.trim();\n    if (r.length < 2) { Alert.alert('Nombre', 'Di quién recibe la entrega (mín. 2 caracteres).'); return; }\n    if (t.length < 6) { Alert.alert('Teléfono', 'El teléfono de contacto es obligatorio.'); return; }\n    if (!city) { Alert.alert('Ciudad', 'Elige la ciudad de la entrega.'); return; }\n    if (d.length < 5) { Alert.alert('Dirección', 'La dirección necesita al menos 5 caracteres.'); return; }\n\n    const body: EcomerseAddressInput = {\n      recipient: r, phone: t, city, zoneId: zoneId || null, detail: d,\n      landmark: landmark.trim() || null, label: label.trim() || null,\n    };\n    /* Sólo viaja cuando vale `true`: ver la cabecera. Editar el teléfono no debe tocar la bandera,\n       y por eso NO se manda `false` en el caso normal. */\n    if (isDefault) body.isDefault = true;\n\n    setBusy(true);\n    try {\n      if (editando) await ecomerseApi.updateAddress(String(id), body);\n      else await ecomerseApi.createAddress(body);\n      router.back();\n    } catch (e) {\n      Alert.alert('No se pudo guardar', mensajeDe(e));\n    } finally {\n      setBusy(false);\n    }\n  }, [recipient, phone, city, zoneId, detail, landmark, label, isDefault, editando, id, router]);\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]}>\n          {editando ? 'Editar dirección' : 'Nueva dirección'}\n        </Text>\n        <View style={{ width: icono.lg }} />\n      </View>\n\n      {cargando ? (\n        <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e32 }} />\n      ) : (\n        <ScrollView\n          contentContainerStyle={[styles.form, { paddingBottom: insets.bottom + espaciado.e32 }]}\n          keyboardShouldPersistTaps=\"handled\"\n        >\n          <FormField\n            label=\"Quién recibe\"\n            value={recipient}\n            onChangeText={setRecipient}\n            placeholder=\"Ej: María Nsue\"\n            maxLength={80}\n          />\n          <FormField\n            label=\"Teléfono de contacto\"\n            value={phone}\n            onChangeText={setPhone}\n            placeholder=\"Ej: +240 222 000 123\"\n            keyboardType=\"phone-pad\"\n            maxLength={24}\n          />\n\n          <Text style={[styles.label, { color: colors.textSecondary }]}>Ciudad</Text>\n          <View style={styles.chips}>\n            {ciudades.map(([c]) => {\n              const activo = c === city;\n              return (\n                <Pressable\n                  key={c}\n                  onPress={() => elegirCiudad(c)}\n                  accessibilityRole=\"radio\"\n                  accessibilityState={{ checked: activo }}\n                  accessibilityLabel={`Ciudad ${c}`}\n                  style={[styles.chip, {\n                    backgroundColor: activo ? colors.primary : colors.surface,\n                    borderColor: activo ? colors.primary : colors.border,\n                  }]}\n                >\n                  <Text style={[styles.chipTexto, { color: activo ? brand.white : colors.textPrimary }]}>{c}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n\n          <Text style={[styles.label, { color: colors.textSecondary }]}>\n            Zona de reparto (opcional — sin ella, te la pedimos al pagar)\n          </Text>\n          <View style={styles.chips}>\n            {zonasDeCiudad.map((z) => {\n              const activo = z.id === zoneId;\n              return (\n                <Pressable\n                  key={z.id}\n                  onPress={() => setZoneId(activo ? '' : z.id)}\n                  accessibilityRole=\"radio\"\n                  accessibilityState={{ checked: activo }}\n                  accessibilityLabel={`Zona ${z.label}`}\n                  style={[styles.chip, {\n                    backgroundColor: activo ? colors.primary : colors.surface,\n                    borderColor: activo ? colors.primary : colors.border,\n                  }]}\n                >\n                  <Text style={[styles.chipTexto, { color: activo ? brand.white : colors.textPrimary }]}>{z.label}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n\n          <FormField\n            label=\"Dirección\"\n            value={detail}\n            onChangeText={setDetail}\n            placeholder=\"Ej: Calle de los Almendros, casa 14\"\n            maxLength={240}\n          />\n          <FormField\n            label=\"Punto de referencia (opcional)\"\n            value={landmark}\n            onChangeText={setLandmark}\n            placeholder=\"Ej: frente al mercado central, portón verde\"\n            maxLength={120}\n          />\n\n          <Text style={[styles.label, { color: colors.textSecondary }]}>Etiqueta (opcional)</Text>\n          <View style={styles.chips}>\n            {ETIQUETAS.map((e) => {\n              const activo = label.trim().toLowerCase() === e.toLowerCase();\n              return (\n                <Pressable\n                  key={e}\n                  onPress={() => setLabel(activo ? '' : e)}\n                  accessibilityRole=\"radio\"\n                  accessibilityState={{ checked: activo }}\n                  accessibilityLabel={`Etiqueta ${e}`}\n                  style={[styles.chip, {\n                    backgroundColor: activo ? colors.primary : colors.surface,\n                    borderColor: activo ? colors.primary : colors.border,\n                  }]}\n                >\n                  <Text style={[styles.chipTexto, { color: activo ? brand.white : colors.textPrimary }]}>{e}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n\n          <Pressable\n            onPress={() => setIsDefault((v) => !v)}\n            accessibilityRole=\"checkbox\"\n            accessibilityState={{ checked: isDefault }}\n            accessibilityLabel=\"Usar esta dirección como predeterminada\"\n            style={[styles.casilla, { borderColor: colors.border, backgroundColor: colors.card }]}\n          >\n            <View style={[styles.marca, {\n              borderColor: isDefault ? colors.primary : colors.border,\n              backgroundColor: isDefault ? colors.primary : 'transparent',\n            }]}>\n              {isDefault ? <Check size={icono.sm} color={brand.white} /> : null}\n            </View>\n            <View style={styles.casillaTexto}>\n              <Text style={[styles.casillaTitulo, { color: colors.textPrimary }]}>Usar como predeterminada</Text>\n              <Text style={[styles.casillaNota, { color: colors.textSecondary }]}>\n                El checkout la propondrá sin preguntarte. Si ya tenías otra, esa dejará de serlo.\n              </Text>\n            </View>\n          </Pressable>\n\n          <View style={styles.pieBoton}>\n            <PrimaryButton\n              title={editando ? 'Guardar cambios' : 'Guardar dirección'}\n              onPress={() => void guardar()}\n              loading={busy}\n              disabled={busy}\n            />\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  form: { paddingHorizontal: espaciado.e16, paddingTop: espaciado.e16, gap: espaciado.e12 },\n  label: { fontSize: tipografia.caption, fontWeight: peso.fuerte, marginBottom: espaciado.e8 },\n  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  chip: {\n    borderRadius: radios.sm,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e8,\n  },\n  chipTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  casilla: {\n    flexDirection: 'row',\n    alignItems: 'flex-start',\n    gap: espaciado.e12,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    padding: espaciado.e12,\n    marginTop: espaciado.e8,\n  },\n  marca: {\n    /* No hay token de «casilla» en la escala: se reutiliza el de icono mediano (20), que es el\n       tamaño natural de una casilla y el que ya usa el kit para sus controles. */\n    width: icono.md,\n    height: icono.md,\n    borderRadius: radios.sm,\n    borderWidth: trazo.base,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  casillaTexto: { flex: 1 },\n  casillaTitulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  casillaNota: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  pieBoton: { marginTop: espaciado.e16 },\n});\n","/**\n * Mis direcciones de entrega — la agenda del comprador (Fase 2 del pie del Mercado).\n *\n * QUÉ RESUELVE\n * La libreta de direcciones que faltaba. Hasta hoy el checkout pedía la dirección en un campo de\n * texto libre y el comprador la re-tecleaba en cada compra. Aquí se guardan, se editan, se borran y\n * una de ellas es la predeterminada: la que el checkout propone sin preguntar.\n *\n * UNA SOLA PREDETERMINADA — Y LO GARANTIZA LA BASE, NO ESTA PANTALLA\n * «Marcar predeterminada» llama al servidor, que desmarca la anterior en la misma transacción; por\n * debajo hay un índice único parcial (`uq_ec_addr_default`) que hace imposible tener dos. Esta\n * pantalla, por tanto, NO vigila esa regla: la cumple quien la escribe, y aquí sólo se pinta lo que\n * el servidor devuelve.\n *\n * POR QUÉ RECARGA AL ENTRAR EN FOCO\n * Volver del formulario no remonta esta pantalla —queda montada en la pila—, así que con un\n * `useEffect` a secas la lista seguiría sin la dirección recién guardada. Mismo `useFocusEffect` que\n * el perfil y las demás listas del proyecto.\n *\n * BORRAR ES DE VERDAD, Y SE PREGUNTA\n * Un `DELETE` real, no un «removed»: aquí no cuelga ningún historial, porque cada pedido guarda su\n * propio texto congelado (`ecomerse_orders.delivery_address`). Aun así se confirma antes, y si la\n * que se borra es la predeterminada el aviso dice quién hereda.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowLeft, Briefcase, Check, Home, MapPin, Pencil, Plus, Tag, Trash2,\n} from 'lucide-react-native';\nimport {\n  EmptyState, PrimaryButton, brand, espaciado, icono, peso, radios, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseAddress } from '../api/ecomerse';\nimport { useSession } from '../state/session';\n\ntype Icono = React.ComponentType<{ size?: number; color?: string }>;\n\n/**\n * El icono de cada etiqueta. `label` es TEXTO LIBRE en la base (el DTO no lo cierra), así que esto\n * es sólo pintura: una etiqueta que no conocemos cae en el alfiler y no se pierde nada.\n */\nconst ICONO_ETIQUETA: Record<string, Icono> = {\n  casa: Home,\n  trabajo: Briefcase,\n  otro: Tag,\n};\n\nconst iconoDeEtiqueta = (label: string | null): Icono =>\n  ICONO_ETIQUETA[(label ?? '').trim().toLowerCase()] ?? MapPin;\n\n/** El texto del error del servidor si lo hay; si no, uno que no miente sobre lo que pasó. */\nconst mensajeDe = (e: unknown): string =>\n  e instanceof Error && e.message ? e.message : 'No se pudo completar. Inténtalo otra vez.';\n\nexport default function EcomerseDireccionesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const [lista, setLista] = useState<EcomerseAddress[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [intentado, setIntentado] = useState(false);\n  const [fallo, setFallo] = useState(false);\n  /** El id de la fila que está hablando con el servidor: bloquea SUS botones, no los de las demás. */\n  const [ocupada, setOcupada] = useState<string | null>(null);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated) { setLista([]); setCargando(false); setIntentado(true); return; }\n    setCargando(true);\n    try {\n      setLista(await ecomerseApi.addresses());\n      setFallo(false);\n    } catch {\n      setFallo(true);\n    } finally {\n      setCargando(false);\n      setIntentado(true);\n    }\n  }, [isAuthenticated]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const marcarPredeterminada = async (d: EcomerseAddress) => {\n    if (d.isDefault || ocupada) return;\n    setOcupada(d.id);\n    try {\n      await ecomerseApi.setDefaultAddress(d.id);\n      await cargar();\n    } catch (e) {\n      Alert.alert('No se pudo marcar', mensajeDe(e));\n    } finally {\n      setOcupada(null);\n    }\n  };\n\n  const confirmarBorrado = async (d: EcomerseAddress) => {\n    setOcupada(d.id);\n    try {\n      await ecomerseApi.deleteAddress(d.id);\n      await cargar();\n    } catch (e) {\n      Alert.alert('No se pudo borrar', mensajeDe(e));\n    } finally {\n      setOcupada(null);\n    }\n  };\n\n  const borrar = (d: EcomerseAddress) => {\n    Alert.alert(\n      '¿Borrar esta dirección?',\n      d.isDefault\n        ? 'Es tu dirección predeterminada: si te queda alguna otra, pasará a serlo.'\n        : 'Los pedidos que ya hiciste guardan su propia copia y no cambian.',\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Borrar', style: 'destructive', onPress: () => void confirmarBorrado(d) },\n      ],\n    );\n  };\n\n  const abrirFormulario = (id?: string) =>\n    router.push((id ? `/ecomerse-direccion?id=${id}` : '/ecomerse-direccion') as never);\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]}>Direcciones de entrega</Text>\n        <Pressable\n          onPress={() => abrirFormulario()}\n          hitSlop={12}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Añadir una dirección\"\n        >\n          <Plus size={icono.lg} color={colors.primary} />\n        </Pressable>\n      </View>\n\n      <ScrollView contentContainerStyle={[styles.lista, { paddingBottom: insets.bottom + espaciado.e32 }]}>\n        {!isAuthenticated ? (\n          <EmptyState\n            emoji=\"🔐\"\n            titulo=\"Inicia sesión\"\n            texto=\"Las direcciones de entrega van con tu cuenta: entra y podrás guardar las que quieras.\"\n          />\n        ) : cargando && !intentado ? (\n          <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e32 }} />\n        ) : fallo ? (\n          <EmptyState\n            emoji=\"📡\"\n            titulo=\"No se pudieron cargar\"\n            texto=\"No hemos podido leer tus direcciones. Toca y lo intentamos otra vez.\"\n            accionLabel=\"Reintentar\"\n            onAccion={() => void cargar()}\n          />\n        ) : lista.length === 0 ? (\n          <EmptyState\n            emoji=\"📍\"\n            titulo=\"Todavía no tienes direcciones\"\n            texto=\"Guarda dónde quieres recibir tus pedidos y el checkout dejará de pedirte que lo escribas cada vez.\"\n            accionLabel=\"Añadir una dirección\"\n            onAccion={() => abrirFormulario()}\n            accionPrimaria\n          />\n        ) : (\n          <>\n            {lista.map((d) => {\n              const Icono = iconoDeEtiqueta(d.label);\n              const trabajando = ocupada === d.id;\n              return (\n                <View\n                  key={d.id}\n                  style={[\n                    styles.tarjeta,\n                    { backgroundColor: colors.card, borderColor: d.isDefault ? colors.primary : colors.border },\n                  ]}\n                >\n                  <View style={styles.filaSuperior}>\n                    <View style={[styles.filaIcono, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                      <Icono size={icono.sm} color={colors.primary} />\n                    </View>\n                    <View style={styles.textoCabecera}>\n                      <View style={styles.nombreFila}>\n                        <Text style={[styles.nombre, { color: colors.textPrimary }]} numberOfLines={1}>\n                          {d.recipient}\n                        </Text>\n                        {d.label ? (\n                          <View style={[styles.sello, { borderColor: colors.border }]}>\n                            <Text style={[styles.selloTexto, { color: colors.textSecondary }]} numberOfLines={1}>\n                              {d.label}\n                            </Text>\n                          </View>\n                        ) : null}\n                        {d.isDefault ? (\n                          <View style={[styles.sello, styles.selloDefault, { backgroundColor: colors.primary, borderColor: colors.primary }]}>\n                            <Text style={[styles.selloTexto, styles.selloTextoDefault]}>Predeterminada</Text>\n                          </View>\n                        ) : null}\n                      </View>\n                      <Text style={[styles.telefono, { color: colors.textSecondary }]} numberOfLines={1}>\n                        {d.phone}\n                      </Text>\n                    </View>\n                  </View>\n\n                  <Text style={[styles.detalle, { color: colors.textPrimary }]}>{d.detail}</Text>\n                  {d.landmark ? (\n                    <Text style={[styles.nota, { color: colors.textSecondary }]}>{d.landmark}</Text>\n                  ) : null}\n                  {/* La ciudad y la zona se pintan juntas: la zona es lo que decide la tarifa del\n                      agente, así que «de dónde es» y «cuánto cuesta» son el mismo dato. */}\n                  <Text style={[styles.nota, { color: colors.textSecondary }]}>\n                    {d.zoneLabel ? `${d.city} · ${d.zoneLabel}` : `${d.city} · sin zona (te la piden al pagar)`}\n                  </Text>\n\n                  <View style={[styles.acciones, { borderTopColor: colors.border }]}>\n                    {d.isDefault ? (\n                      <View style={styles.accion}>\n                        <Check size={icono.sm} color={colors.textSecondary} />\n                        <Text style={[styles.accionTexto, { color: colors.textSecondary }]}>Predeterminada</Text>\n                      </View>\n                    ) : (\n                      <Pressable\n                        onPress={() => void marcarPredeterminada(d)}\n                        disabled={trabajando}\n                        accessibilityRole=\"button\"\n                        accessibilityLabel={`Usar la dirección de ${d.recipient} como predeterminada`}\n                        style={({ pressed }) => [styles.accion, { opacity: pressed || trabajando ? 0.5 : 1 }]}\n                      >\n                        <Check size={icono.sm} color={colors.primary} />\n                        <Text style={[styles.accionTexto, { color: colors.primary }]}>Usar por defecto</Text>\n                      </Pressable>\n                    )}\n\n                    <Pressable\n                      onPress={() => abrirFormulario(d.id)}\n                      disabled={trabajando}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={`Editar la dirección de ${d.recipient}`}\n                      style={({ pressed }) => [styles.accion, { opacity: pressed || trabajando ? 0.5 : 1 }]}\n                    >\n                      <Pencil size={icono.sm} color={colors.textPrimary} />\n                      <Text style={[styles.accionTexto, { color: colors.textPrimary }]}>Editar</Text>\n                    </Pressable>\n\n                    <Pressable\n                      onPress={() => borrar(d)}\n                      disabled={trabajando}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={`Borrar la dirección de ${d.recipient}`}\n                      style={({ pressed }) => [styles.accion, { opacity: pressed || trabajando ? 0.5 : 1 }]}\n                    >\n                      <Trash2 size={icono.sm} color={colors.danger} />\n                      <Text style={[styles.accionTexto, { color: colors.danger }]}>Borrar</Text>\n                    </Pressable>\n                  </View>\n                </View>\n              );\n            })}\n\n            <View style={styles.pieBoton}>\n              <PrimaryButton title=\"Añadir una dirección\" onPress={() => abrirFormulario()} />\n            </View>\n          </>\n        )}\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  lista: { paddingHorizontal: espaciado.e16, paddingTop: espaciado.e16 },\n  tarjeta: {\n    borderRadius: radios.lg,\n    borderWidth: trazo.fino,\n    padding: espaciado.e16,\n    marginBottom: espaciado.e12,\n  },\n  filaSuperior: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 },\n  filaIcono: {\n    width: 36,\n    height: 36,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  textoCabecera: { flex: 1 },\n  nombreFila: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, flexWrap: 'wrap' },\n  nombre: { fontSize: tipografia.body, fontWeight: peso.titulo },\n  sello: {\n    borderRadius: radios.sm,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e8,\n    paddingVertical: espaciado.e4 / 2,\n  },\n  selloDefault: {},\n  selloTexto: { fontSize: tipografia.micro, fontWeight: peso.fuerte },\n  selloTextoDefault: { color: brand.white },\n  telefono: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  detalle: { fontSize: tipografia.body, marginTop: espaciado.e12 },\n  nota: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  acciones: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e16,\n    marginTop: espaciado.e12,\n    paddingTop: espaciado.e12,\n    borderTopWidth: trazo.fino,\n  },\n  accion: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 },\n  accionTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  pieBoton: { marginTop: espaciado.e8 },\n});\n","// egrouteplan-app/app/ecomerse-docs.tsx\n/**\n * EcomerseDocsScreen — moderación de la documentación del Mercado (solo ADMIN).\n *\n * POR QUÉ EXISTE (cierre de la tanda 4):\n * el vendedor sube su factura o su certificado al publicar, y el comprador la ve en la ficha como\n * «En revisión». Pero **no había forma de revisarla desde la app**: el estado solo se cambiaba con un\n * UPDATE a mano en la base. Una cola sin salida es una promesa al comprador que el sistema no puede\n * cumplir, y eso es exactamente lo que el informe de Dewu señala como la diferencia entre un sistema\n * de confianza y un adorno.\n *\n * QUÉ MUESTRA: cada documento pendiente **con su anuncio** (título, precio, ciudad y tienda). Sin\n * eso no se puede comprobar nada: una factura de 6.500 XAF solo se puede validar si se ve el anuncio\n * de 6.500 XAF. Un listado de papeles sueltos no sirve para decidir.\n *\n * CÓMO SE DECIDE: aprobar, o rechazar **con motivo obligatorio** (el vendedor lo verá y sabrá qué\n * corregir). El backend exige el motivo al rechazar; aquí se pide antes de enviar.\n *\n * NOTA DE SEGURIDAD: la pertenencia al rol ADMIN la comprueba el servidor con el rol del token\n * (`@Roles('ADMIN')`). Esta pantalla no decide nada por su cuenta: si la abre alguien que no es\n * admin, la API responde 403 y se muestra el error, no una pantalla vacía que parezca «no hay nada».\n *\n * Ruta: /ecomerse-docs\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, Alert, FlatList, Linking, Pressable, RefreshControl, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, ExternalLink, ShieldCheck, XCircle } from 'lucide-react-native';\nimport { alpha, EmptyState, espaciado, GhostButton, InlineError, PrimaryButton, radios, Sheet, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseDocPendiente } from '../api/ecomerse';\nimport { formatXAF } from '../utils/formatHelpers';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { ir } from '../constants/rutas';\n\nconst DOC_LABEL: Record<string, string> = {\n  factura_compra: 'Factura de compra',\n  certificado_autenticidad: 'Certificado de autenticidad',\n  autorizacion_marca: 'Autorización de marca',\n};\n\nexport default function EcomerseDocsScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [docs, setDocs] = useState<EcomerseDocPendiente[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState<string | null>(null);\n  /** Documento que se está rechazando (para pedir el motivo antes de enviar). */\n  const [rechazando, setRechazando] = useState<EcomerseDocPendiente | null>(null);\n  const [motivo, setMotivo] = useState('');\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      setDocs(await ecomerseApi.adminDocs());\n    } catch (e) {\n      // El 403 se muestra tal cual: si no eres admin, hay que decirlo, no fingir una lista vacía.\n      setError(e instanceof Error ? e.message : 'No pudimos cargar la cola de documentación.');\n      setDocs([]);\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const refresh = async () => {\n    setRefreshing(true);\n    try { setDocs(await ecomerseApi.adminDocs()); setError(null); } catch { /* noop */ }\n    finally { setRefreshing(false); }\n  };\n\n  const decidir = async (doc: EcomerseDocPendiente, approve: boolean, reason?: string) => {\n    if (busy) return;\n    setBusy(doc.id);\n    try {\n      const r = await ecomerseApi.adminDecideDoc(doc.id, approve, reason);\n      Alert.alert('Hecho', r.message);\n      setRechazando(null); setMotivo('');\n      await load();\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo guardar la decisión');\n    } finally { setBusy(null); }\n  };\n\n  const s = styles(colors);\n\n  return (\n    <View style={[s.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      <View style={[s.header, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => ir.atras()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={s.back}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[s.title, { color: colors.textPrimary }]} numberOfLines={1}>Documentación</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, paddingHorizontal: espaciado.e16, paddingTop: espaciado.e10 }}>\n        Revisa los documentos que han subido los vendedores. El comprador los ve como «En revisión» hasta que alguien los mira.\n      </Text>\n\n      {loading ? (\n        <View style={s.centro}><ActivityIndicator color={colors.primary} /></View>\n      ) : error ? (\n        <View style={{ padding: espaciado.e16 }}>\n          <InlineError mensaje={error} onReintentar={load} />\n        </View>\n      ) : (\n        <FlatList\n          data={docs}\n          keyExtractor={(d) => d.id}\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }}\n          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} />}\n          ListEmptyComponent={\n            <EmptyState\n              titulo=\"No hay documentación pendiente\"\n              texto=\"Cuando un vendedor suba una factura o un certificado, aparecerá aquí para que lo revises.\"\n            />\n          }\n          renderItem={({ item }) => (\n            <View style={[s.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              {/* Qué se revisa: el documento Y su anuncio. */}\n              <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>\n                {DOC_LABEL[item.docType] ?? item.docType}\n              </Text>\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e4 }}>\n                {item.producto.title} · {formatXAF(item.producto.priceXaf)} · {item.producto.city}\n              </Text>\n              <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>\n                Tienda: {item.producto.sellerName ?? '—'}\n                {item.docNumber ? ` · Nº ${item.docNumber}` : ''}\n                {item.amountXaf !== null && item.amountXaf !== undefined ? ` · ${formatXAF(item.amountXaf)}` : ''}\n                {item.issuedOn ? ` · ${item.issuedOn}` : ''}\n              </Text>\n              {/* El importe de la factura frente al del anuncio: es la comprobación más útil y la\n                  que no se puede hacer desde un listado de papeles sueltos. */}\n              {item.amountXaf !== null && item.amountXaf !== undefined && item.amountXaf !== item.producto.priceXaf ? (\n                <Text style={{ fontSize: tipografia.micro, color: brand.warningText, fontWeight: '700', marginTop: espaciado.e4 }}>\n                  ⚠ El importe de la factura no coincide con el precio del anuncio.\n                </Text>\n              ) : null}\n\n              <Pressable\n                onPress={() => Linking.openURL(item.url).catch(() => Alert.alert('Documento', 'No se pudo abrir el documento.'))}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Ver el documento\"\n                style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e10 }}\n              >\n                <ExternalLink size={14} color={colors.primary} />\n                <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.primary }}>Ver el documento</Text>\n              </Pressable>\n\n              <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n                <View style={{ flex: 1 }}>\n                  <Pressable\n                    onPress={() => decidir(item, true)}\n                    disabled={busy === item.id}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`Aprobar ${DOC_LABEL[item.docType] ?? item.docType}`}\n                    style={[s.btn, { backgroundColor: busy === item.id ? colors.border : brand.success }]}\n                  >\n                    <ShieldCheck size={15} color={brand.white} />\n                    <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.caption }}>\n                      {busy === item.id ? 'Enviando…' : 'Aprobar'}\n                    </Text>\n                  </Pressable>\n                </View>\n                <View style={{ flex: 1 }}>\n                  <Pressable\n                    onPress={() => { setRechazando(item); setMotivo(''); }}\n                    disabled={busy === item.id}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`Rechazar ${DOC_LABEL[item.docType] ?? item.docType}`}\n                    style={[s.btn, { borderWidth: 1, borderColor: colors.danger }]}\n                  >\n                    <XCircle size={15} color={colors.danger} />\n                    <Text style={{ color: colors.danger, fontWeight: '800', fontSize: tipografia.caption }}>Rechazar</Text>\n                  </Pressable>\n                </View>\n              </View>\n            </View>\n          )}\n        />\n      )}\n\n      {/* Rechazo: el motivo es obligatorio y se pide ANTES de enviar, porque el backend lo exige y el\n          vendedor lo va a leer. */}\n      <Sheet\n        visible={!!rechazando}\n        position=\"bottom\"\n        busy={!!busy}\n        title=\"Rechazar el documento\"\n        subtitle=\"El vendedor verá este motivo y podrá corregirlo.\"\n        onClose={() => setRechazando(null)}\n      >\n        <View style={{ padding: espaciado.e16, gap: espaciado.e12 }}>\n          <TextInput\n            value={motivo}\n            onChangeText={setMotivo}\n            placeholder=\"Motivo (por ejemplo: la factura no corresponde a este artículo)\"\n            placeholderTextColor={colors.textSecondary}\n            multiline\n            style={[s.motivo, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n          />\n          <GhostButton title=\"Cancelar\" onPress={() => setRechazando(null)} />\n          <PrimaryButton\n            title={motivo.trim() ? 'Rechazar con este motivo' : 'Escribe un motivo para rechazar'}\n            onPress={() => rechazando && decidir(rechazando, false, motivo.trim())}\n            disabled={!motivo.trim() || !!busy}\n          />\n        </View>\n      </Sheet>\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1 },\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: 1 },\n  back: { padding: espaciado.e2 },\n  title: { fontSize: tipografia.body, fontWeight: '800' },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  card: { borderRadius: radios.lg, borderWidth: 1, padding: espaciado.e12, marginBottom: espaciado.e12 },\n  btn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, minHeight: 40, borderRadius: radios.md },\n  motivo: { minHeight: 80, borderRadius: radios.md, borderWidth: 1, padding: espaciado.e10, textAlignVertical: 'top' },\n});\n","/**\n * EcomerseFavoritesScreen — \"Seguido\" (estilo Xianyu).\n * Pestañas: Todo · Novedades · Categorías · Comprados · Especiales.\n * v2 (auditoría): errores con Reintentar, favorito con revert si falla, skeleton,\n * grid par, sesión requerida, SafeArea y a11y.\n * Ruta: /ecomerse-favorites\n *\n * ── NOMENCLATURA (2026-09-13) ────────────────────────────────────────────────\n * Las etiquetas de las pestañas estaban EN CHINO (全部 · 上新 · 分类 · 买过 · 特别关注)\n * mientras el resto de la pantalla estaba en español: se habían copiado del diseño de\n * referencia y nunca se tradujeron. La app es para Guinea Ecuatorial y está en español, así\n * que un usuario veía cinco pestañas que no podía leer. Traducidas.\n * Se conserva la referencia al diseño original (Xianyu / 闲鱼) porque explica de dónde\n * salen los cinco apartados, pero el TEXTO que se pinta es el de abajo, en español.\n *\n * ── FASE 1 DEL PIE (22-sep-2026): «Categorías» AGRUPA Y CUENTA ───────────────────\n * La pestaña «Categorías» filtraba por departamento pero NO decía cuántos favoritos hay en cada\n * uno: había que entrar a mirar. La referencia (Pinduoduo, imagen #8) los lista con su cuenta\n * —「男装 69」·「箱包 4」·「鞋靴 5」—, y eso es justo lo que convierte la pestaña en un índice en vez de\n * en una fila de botones a ciegas.\n *\n * DOS REGLAS QUE NO SE PUEDEN SALTAR:\n *  1. **La cuenta sale de la lista COMPLETA, nunca de la filtrada.** Contar sobre lo que se está\n *     pintando daría «男装 69» y «箱包 0» —el número de la categoría que miras—, que no es lo que\n *     nadie espera. Por eso en esta pestaña se piden dos listas: la filtrada para pintar y la\n *     completa para contar.\n *  2. **Sólo se enseñan los departamentos con algo dentro.** Los 18 bloques del árbol, con quince a\n *     cero, serían un carril de ruido. La excepción es el que estás mirando: si se queda a cero\n *     mientras lo miras, su ficha se queda para que sepas por qué la rejilla está vacía.\n */\n\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { Alert, FlatList, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { EmptyState, espaciado, ilustracion, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseCategory, EcomerseProduct } from '../api/ecomerse';\nimport { useEcomerseStore } from '../state/ecomerse';\nimport { useSession } from '../state/session';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { TarjetaProducto, EsqueletoTarjeta } from '../components/ecomerse/TarjetaProducto';\n\ntype Tab = 'all' | 'new' | 'cat' | 'bought' | 'special';\n/** `isSpecial` no está en el tipo del catálogo: lo devuelve solo la lista de Favoritos. */\ntype ProductoFavorito = EcomerseProduct & { isSpecial?: boolean };\n\nconst TABS: Array<{ key: Tab; label: string }> = [\n  { key: 'all', label: 'Todo' },\n  { key: 'new', label: 'Novedades' },\n  { key: 'cat', label: 'Categorías' },\n  { key: 'bought', label: 'Comprados' },\n  { key: 'special', label: 'Especiales' },\n];\n\nconst SKELETONS = [0, 1, 2, 3];\n\n/**\n * Cuántos favoritos hay en cada departamento. Se cuenta sobre la lista COMPLETA y no sobre lo que\n * se está pintando, que es lo que permite que los números no bailen al moverte entre categorías.\n * Un favorito sin departamento no cuenta en ninguno: sumarlo a un cajón «otros» que no existe en el\n * árbol sería inventarse una categoría.\n */\nfunction contarPorDepartamento(lista: EcomerseProduct[]): Record<string, number> {\n  const n: Record<string, number> = {};\n  for (const p of lista) {\n    if (!p.departmentId) continue;\n    n[p.departmentId] = (n[p.departmentId] ?? 0) + 1;\n  }\n  return n;\n}\n\nexport default function EcomerseFavoritesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const { setFavIds, toggleFavId } = useEcomerseStore();\n  const [tab, setTab] = useState<Tab>('all');\n  const [catId, setCatId] = useState('');\n  const [cats, setCats] = useState<EcomerseCategory[]>([]);\n  const [items, setItems] = useState<EcomerseProduct[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  /** Cuántos favoritos hay en cada departamento. Sólo lo usa la pestaña «Categorías». */\n  const [cuentas, setCuentas] = useState<Record<string, number>>({});\n  const [totalFavs, setTotalFavs] = useState(0);\n  /**\n   * Si la lista COMPLETA ya se trajo en esta visita a la pestaña. Es un `ref` y no un estado a\n   * propósito: marca un «ya está hecho» que NO debe provocar un repintado ni entrar en las\n   * dependencias de `load` (haría que la carga se llamara a sí misma).\n   */\n  const completasRef = useRef(false);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const q: Record<string, string> = {};\n      if (tab === 'new') q.sort = 'new';\n      if (tab === 'special') q.special = '1';\n      /* Las fichas de esta pestaña son DEPARTAMENTOS, así que el filtro va por `department`. Con el\n         nombre viejo (`category`) el servidor lo lee como FAMILIA —ese es el alias— y como aquí viaja\n         un id de departamento, la consulta NO falla: devuelve cero. La pestaña se queda en blanco y\n         se lee como «no tienes favoritos», que es la peor forma de romperse. */\n      if (tab === 'cat' && catId) q.department = catId;\n      /* EN «CATEGORÍAS» HACEN FALTA DOS LISTAS. La filtrada se pinta; la COMPLETA es la única que\n         puede contar, porque contar sobre la filtrada daría «男装 69» y «箱包 0» —el número de la\n         categoría que estás mirando—, que no es lo que nadie espera. La completa se pide UNA vez por\n         visita a la pestaña: volver a pedirla en cada toque sería pedir lo mismo para nada. */\n      const pedirCompletas = tab === 'cat' && !completasRef.current;\n      const [list, c, todas] = await Promise.all([\n        tab === 'bought' ? ecomerseApi.myPurchased() : ecomerseApi.myFavorites(q),\n        ecomerseApi.categories(),\n        pedirCompletas ? ecomerseApi.myFavorites({}) : Promise.resolve(null),\n      ]);\n      setItems(list);\n      setCats(c);\n      if (todas) {\n        completasRef.current = true;\n        setCuentas(contarPorDepartamento(todas));\n        setTotalFavs(todas.length);\n      }\n      // Mantiene el store de favoritos al día (corazones de la home)\n      ecomerseApi.favoriteIds().then((ids) => setFavIds(ids)).catch(() => undefined);\n    } catch (e) {\n      setError(e instanceof Error && /sesión|401|token/i.test(e.message)\n        ? 'Inicia sesión para ver tus favoritos.'\n        : 'No pudimos cargar esta lista. Revisa tu conexión.');\n    } finally {\n      setLoading(false);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tab, catId]);\n\n  /* Cambiar de pestaña invalida la lista completa: al volver a «Categorías» hay que recontar, porque\n     el usuario puede haber quitado favoritos en «Todo». Va ANTES del efecto que carga —los efectos\n     corren en orden de declaración— para que el `ref` esté limpio cuando `load` lo consulte. */\n  useEffect(() => { completasRef.current = false; }, [tab]);\n\n  useEffect(() => { load(); }, [load]);\n\n  const removeFav = (id: string) => {\n    const prev = items;\n    const quitado = items.find((x) => x.id === id);\n    toggleFavId(id);\n    setItems((p) => p.filter((x) => x.id !== id));\n    /* El contador del departamento baja A LA VEZ. Si no, quitar un favorito dejaba «男装 69» en 69\n       hasta recargar, y el número es justo lo que esta pestaña viene a decir. */\n    const ajustar = (delta: number) => {\n      const d = quitado?.departmentId;\n      if (!d) return;\n      setCuentas((p) => ({ ...p, [d]: Math.max((p[d] ?? 0) + delta, 0) }));\n      setTotalFavs((t) => Math.max(t + delta, 0));\n    };\n    ajustar(-1);\n    ecomerseApi.favoritesToggle(id).catch(() => {\n      // revert si la API falló\n      toggleFavId(id);\n      setItems(prev);\n      ajustar(1);\n      Alert.alert('Favoritos', 'No se pudo quitar de favoritos. Inténtalo de nuevo.');\n    });\n  };\n\n  const toggleSpecial = (id: string) => {\n    ecomerseApi.favoritesSpecial(id).then((r) => {\n      setItems((prev) => prev.map((p) => (p.id === id ? { ...p, isSpecial: r.special } as EcomerseProduct : p)));\n    }).catch(() => {\n      Alert.alert('Especiales', 'No se pudo cambiar. Inténtalo de nuevo.');\n    });\n  };\n\n  const s = styles(colors);\n\n  const listData: EcomerseProduct[] = (() => {\n    if (loading && items.length === 0) return SKELETONS.map((i) => ({ id: `__sk_${i}` } as EcomerseProduct));\n    return items.length % 2 === 1 ? [...items, { id: '__spacer__' } as EcomerseProduct] : items;\n  })();\n\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      <ScreenHeader titulo=\"Seguido\" alVolver={() => router.back()} />\n\n      {/* Pestañas */}\n      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flexGrow: 0 }} contentContainerStyle={s.tabs}>\n        {TABS.map((t) => (\n          <Pressable key={t.key} onPress={() => setTab(t.key)} accessibilityRole=\"tab\" accessibilityState={{ selected: tab === t.key }}\n            style={[s.tab, tab === t.key && { backgroundColor: colors.primary }]}>\n            <Text style={[s.tabText, { color: tab === t.key ? brand.white : colors.textPrimary }]}>{t.label}</Text>\n          </Pressable>\n        ))}\n      </ScrollView>\n\n      {/* Selector de categoría (pestaña Categorías): AGRUPA Y CUENTA, como la referencia. Sólo salen\n          los departamentos con algo dentro —los 18 bloques del árbol con quince a cero serían un\n          carril de ruido—, más el que estés mirando: si se queda a cero mientras lo miras, su ficha\n          se queda para que se entienda por qué la rejilla está vacía. */}\n      {tab === 'cat' && (\n        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flexGrow: 0 }} contentContainerStyle={s.catRow}>\n          <SubChip label={`Todas${totalFavs ? ` ${totalFavs}` : ''}`} active={catId === ''} onPress={() => setCatId('')} />\n          {cats\n            .filter((c) => (cuentas[c.id] ?? 0) > 0 || c.id === catId)\n            .map((c) => {\n              const n = cuentas[c.id] ?? 0;\n              return (\n                <SubChip\n                  key={c.id}\n                  label={`${c.icon ?? ''} ${c.label}${n ? ` ${n}` : ''}`}\n                  active={catId === c.id}\n                  onPress={() => setCatId(c.id)}\n                />\n              );\n            })}\n        </ScrollView>\n      )}\n\n      <FlatList\n        data={listData}\n        keyExtractor={(item) => item.id}\n        numColumns={2}\n        columnWrapperStyle={{ gap: espaciado.e10, paddingHorizontal: espaciado.e16 }}\n        contentContainerStyle={{ gap: espaciado.e10, paddingBottom: espaciado.e32 }}\n        ListEmptyComponent={\n          error ? (\n            <View style={{ alignItems: 'center', paddingTop: 48, paddingHorizontal: espaciado.e32 }}>\n              <Text style={{ fontSize: ilustracion.md, marginBottom: espaciado.e8 }}>📡</Text>\n              <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>Algo salió mal</Text>\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 }}>{error}</Text>\n              <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e18 }}>\n                <Pressable onPress={() => isAuthenticated ? load() : router.push('/auth' as any)} style={{ backgroundColor: colors.primary, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e11, borderRadius: radios.full }}>\n                  <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>{isAuthenticated ? 'Reintentar' : 'Iniciar sesión'}</Text>\n                </Pressable>\n              </View>\n            </View>\n          ) : loading && items.length === 0 ? null : (\n            <EmptyState\n              emoji={tab === 'bought' ? '🛒' : tab === 'special' ? '⭐' : '💛'}\n              titulo={tab === 'bought' ? 'Todavía no has comprado nada' : tab === 'special' ? 'Sin productos especiales' : 'Sin productos guardados'}\n              texto={tab === 'bought'\n                ? 'Cuando compres en Ecomerse, los productos aparecerán en Comprados.'\n                : tab === 'special'\n                  ? 'Aquí salen los productos que las tiendas marcan como especiales.'\n                  : 'Toca el ❤️ de un producto para guardarlo aquí.'}\n            />\n          )\n        }\n        renderItem={({ item }) =>\n          item.id.startsWith('__sk_') ? (\n            <EsqueletoTarjeta />\n          ) : item.id === '__spacer__' ? (\n            <View key=\"spacer\" style={{ flex: 1 }} />\n          ) : (\n            <TarjetaProducto\n              product={item}\n              /* El contador de interés se apaga aquí: en Favoritos el corazón es TUYO, y un «♥ 3» al\n                 lado se lee como si fuera de otro. La estrella sí, que es lo único que distingue\n                 «Especiales» del resto de pestañas. */\n              mostrarInteres={false}\n              etiqueta={tab === 'bought' ? 'Comprado' : undefined}\n              onPress={() => router.push({ pathname: '/ecomerse-detail', params: { id: item.id } } as any)}\n              onFav={tab === 'bought' ? undefined : () => removeFav(item.id)}\n              onSpecial={tab === 'bought' ? undefined : () => toggleSpecial(item.id)}\n              isSpecial={(item as ProductoFavorito).isSpecial === true}\n            />\n          )\n        }\n      />\n    </View>\n  );\n}\n\nfunction SubChip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityLabel={label}\n      style={{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, borderRadius: radios.full, backgroundColor: active ? colors.primary : colors.surface, borderWidth: 1, borderColor: active ? colors.primary : colors.border }}>\n      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: active ? brand.white : colors.textPrimary }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  tabs: { gap: espaciado.e8, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12 },\n  tab: { paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, borderRadius: radios.lg, backgroundColor: c.surface, borderWidth: 1, borderColor: c.border },\n  tabText: { fontSize: tipografia.caption, fontWeight: '800' },\n  catRow: { gap: espaciado.e8, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e10 },\n});\n","/**\n * TarjetaProducto — **la** tarjeta de producto del Mercado. Una sola, en los tres sitios.\n *\n * POR QUÉ EXISTE: había **tres tarjetas distintas para el mismo dato** — la rejilla del catálogo\n * (foto a sangre, velo, precio en pastilla), el carrusel «Recomendados» (foto de 92 × 92 contenida,\n * precio naranja suelto y partido en dos líneas) y la de Favoritos (foto de 124 de alto, cuerpo\n * blanco debajo, ciudad y acciones dentro del cuerpo)—. Tres lenguajes para decir lo mismo en la\n * misma pantalla. Unificar no es «que se parezcan»: es que **sólo exista una definición**, y que lo\n * que cambia entre sitios sea una prop, no una copia.\n *\n * QUÉ DECIDE ESTE FICHERO Y QUÉ DECIDEN LOS QUE LO USAN:\n *   · Aquí: la **proporción**, el **orden de las capas**, el velo, dónde va cada control y el\n *     tratamiento del precio (siempre pastilla sólida, nunca naranja suelto).\n *   · Fuera: **qué controles** se pasan (`onAdd` / `onFav` / `onSpecial`), **qué ancho** tiene la\n *     tarjeta y **con qué se abre**. Nada más.\n *\n * ── LA PROPORCIÓN: 3:4, y la fija el dispositivo, no el gusto ──────────────────────────────────\n * La decisión está razonada en `DECISION-PROPORCION-TARJETAS.md`; el resumen: el alta de vendedor\n * llama a `launchCameraAsync({ mediaTypes: ['images'], quality: 0.7 })` **sin `allowsEditing` y sin\n * `aspect`**, así que la app no recorta al subir: guarda la foto tal cual sale de la cámara, y las\n * cámaras Android arrancan en **4:3**. Como la tarjeta pinta con `contentFit=\"cover\"`, la proporción\n * del marco decide cuánto se tira:\n *\n *   marco 1:1  → de una foto 3:4 se pierde el 25 %\n *   marco 2:3  → se pierde el 11 % del ancho, en TODAS las fotos\n *   marco 3:4  → **cero recorte**\n *\n * Y lo que cierra el caso: **el vendedor encuadra en el visor (3:4) y ve exactamente lo que verá el\n * comprador**. Con otro marco le estaríamos recortando la foto sin decirle nada.\n *\n * ── EL PRECIO NO SE FIJA DEL VELO ──────────────────────────────────────────────────────────────\n * El velo oscuro hace legible un título blanco sobre cualquier foto, pero no basta para garantizar\n * el contraste de un número suelto: debajo puede haber una foto blanca. Por eso el precio va en\n * **pastilla sólida** —el par fondo/texto sale del tema— y no en naranja suelto como estaba en el\n * carrusel y en Favoritos, donde el naranja sobre una foto clara se perdía.\n *\n * ── LO QUE SALE DE LA TARJETA, Y POR QUÉ ───────────────────────────────────────────────────────\n * La **ciudad** sale de las tres. En la rejilla era redundante (se navega bajo un filtro de ciudad);\n * en el carrusel y en Favoritos era el único texto de meta, pero ocupaba una línea que sobre una\n * foto se paga en dp de imagen. La ficha la sigue enseñando, que es donde el comprador se lo\n * pregunta. El **nombre del vendedor** ya había salido por lo mismo.\n */\nimport React, { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { LinearGradient } from 'expo-linear-gradient';\nimport { Heart, ShoppingCart, Star } from 'lucide-react-native';\nimport {\n  Precio, useTheme, brand, espaciado, ilustracion, peso, radios, tipografia, trazo,\n} from '@egrouteplan/ui-kit';\nimport type { PrecioTamano } from '@egrouteplan/ui-kit';\nimport type { EcomerseProduct } from '../../api/ecomerse';\n\n/**\n * Proporción ancho:alto de TODA tarjeta de producto. Es un valor de `aspectRatio` de React Native,\n * o sea ancho/alto: 3/4 = una tarjeta más alta que ancha, en vertical.\n *\n * Se exporta porque el esqueleto de carga tiene que medir exactamente lo mismo: si el esqueleto\n * midiera distinto, el contenido daría un salto al terminar de cargar.\n */\nexport const PROPORCION_TARJETA = 3 / 4;\n\n/**\n * Ancho de la tarjeta en el carrusel horizontal. No es el de la rejilla (157) a propósito: en un\n * carrusel el ancho lo fija la **densidad** —cuántas tarjetas asoman— y 140 deja ver dos enteras y\n * un asomo claro de la tercera en una pantalla de 360 dp, que es lo que invita a deslizar.\n */\nexport const ANCHO_CARRUSEL = 140;\n\n/**\n * Velo de abajo arriba. Los topes están puestos por cálculo, no a ojo: el título cae al 59 % del\n * alto, donde el velo ya va por 0,80 de opacidad. Con una foto **blanca pura** por debajo, eso deja\n * el contraste del texto blanco en **~14:1**, más del triple del 4,5:1 que pide la norma; incluso en\n * la zona de transición (0,55) sigue en **~5,7:1**.\n */\nconst VELO_COLORES = ['rgba(0,0,0,0)', 'rgba(0,0,0,0.35)', 'rgba(0,0,0,0.82)', 'rgba(0,0,0,0.95)'] as const;\nconst VELO_PARADAS = [0, 0.4, 0.6, 1] as const;\n\nexport interface TarjetaProductoProps {\n  product: EcomerseProduct;\n  /** Abre la ficha. Es el toque de toda la tarjeta salvo los controles. */\n  onPress: () => void;\n  /**\n   * Ancho fijo (carrusel). Si falta, la tarjeta toma `flex: 1` y se reparte el ancho de la fila,\n   * que es lo que necesita una rejilla de dos columnas.\n   */\n  width?: number;\n  /** Proporción ancho:alto. Por defecto la de toda la app; existe para poder medir, no para variar. */\n  aspect?: number;\n  /** Tamaño del precio. Por defecto `md`, el de tarjeta. */\n  precioTamano?: PrecioTamano;\n  /** Estado del corazón. Gobierna también su etiqueta accesible («añadir» / «quitar»). */\n  favorited?: boolean;\n  onFav?: () => void;\n  onAdd?: () => void;\n  onSpecial?: () => void;\n  /** Solo tiene efecto junto a `onSpecial`: pinta la estrella encendida. */\n  isSpecial?: boolean;\n  /**\n   * Texto del contador de interés («♥ 12»). Por defecto se enseña **solo si hay alguien**: un\n   * «0 fav» espanta más de lo que informa. En Favoritos se apaga: ahí el corazón es tuyo y el\n   * contador se lee como si fuera de otro.\n   */\n  mostrarInteres?: boolean;\n  /**\n   * Chip de texto sobre la foto, además de las etiquetas propias del producto (destacado, Pro,\n   * estado del artículo). Es para lo que el sitio de uso sabe y la tarjeta no: «Comprado».\n   */\n  etiqueta?: string;\n  /** Tamaño del icono cuando no hay foto. La rejilla lo quiere grande; el carrusel, menor. */\n  iconoTamano?: number;\n}\n\nexport function TarjetaProducto({\n  product, onPress, width, aspect = PROPORCION_TARJETA, precioTamano = 'md',\n  favorited = false, onFav, onAdd, onSpecial, isSpecial = false,\n  mostrarInteres = true, etiqueta, iconoTamano = ilustracion.lg,\n}: TarjetaProductoProps) {\n  const { colors } = useTheme();\n  /* `fallo` guarda la URI que falló, no un booleano: así, si el producto cambia de foto, el estado\n     se limpia solo y se vuelve a intentar sin efectos ni re-montajes. */\n  const [fallo, setFallo] = useState<string | null>(null);\n\n  const foto = product.photos?.[0] ?? null;\n  const sinFoto = !foto || fallo === foto;\n  const condition = typeof product.attributes?.estado === 'string' ? product.attributes.estado : null;\n  const interes = mostrarInteres && product.favoriteCount > 0 ? product.favoriteCount : 0;\n  const hayEtiquetas = !!product.isFeatured || product.seller?.badge === 'Pro' || !!condition || !!etiqueta;\n  const hayAcciones = interes > 0 || !!onAdd || !!onFav || !!onSpecial;\n\n  return (\n    <View\n      style={[\n        s.card,\n        { aspectRatio: aspect, backgroundColor: colors.card, borderColor: colors.border },\n        width ? { width } : { flex: 1 },\n      ]}\n    >\n      {/*\n        ORDEN DE CAPAS. Importa para los toques, no solo para el dibujo:\n          1 foto · 2 velo · 3 capa de detalle · 4 etiquetas · 5 acciones · 6 contenido.\n        El contenido lleva `none` porque dentro no hay nada interactivo: un toque sobre el título cae\n        en la capa de detalle y abre la ficha, que es lo que se espera. Los controles vivos están en\n        la fila de acciones, fuera del contenido, y por eso no heredan ese `none` — y hay que\n        tenerlo presente, porque en React Native `pointerEvents=\"none\"` desactiva TAMBIÉN los hijos:\n        un botón dentro de una capa desactivada queda de adorno.\n      */}\n      {sinFoto ? (\n        <View style={[StyleSheet.absoluteFill, { backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center' }]}>\n          <Text style={{ fontSize: iconoTamano, opacity: 0.55 }}>{product.categoryIcon ?? '📦'}</Text>\n        </View>\n      ) : (\n        <Image\n          source={{ uri: foto }}\n          style={[StyleSheet.absoluteFill, { backgroundColor: colors.surface }]}\n          contentFit=\"cover\"\n          transition={200}\n          onError={() => setFallo(foto)}\n        />\n      )}\n      <LinearGradient\n        colors={VELO_COLORES}\n        locations={VELO_PARADAS}\n        style={StyleSheet.absoluteFill}\n        pointerEvents=\"none\"\n      />\n      <Pressable\n        style={StyleSheet.absoluteFill}\n        onPress={onPress}\n        accessibilityRole=\"button\"\n        accessibilityLabel={product.title}\n      />\n\n      {/* Etiquetas, arriba a la izquierda, en columna. La caja lleva `right` y `alignItems` a\n          propósito: así queda acotada por la tarjeta y el chip puede pedir `maxWidth: '100%'` sin\n          poder desbordarla nunca. Caen por debajo de la fila de acciones —que ocupa los primeros\n          ~33 dp—, así que no se pisan. */}\n      {hayEtiquetas && (\n        <View style={s.etiquetas} pointerEvents=\"none\">\n          {product.isFeatured && <View style={s.chipNaranja}><Text style={s.chipEmoji}>🔥</Text></View>}\n          {product.seller?.badge === 'Pro' && <View style={s.chipAzul}><Text style={s.chipPro}>PRO</Text></View>}\n          {condition ? (\n            <View style={s.chipOscuro}>\n              <Text numberOfLines={1} style={s.chipTexto}>{condition}</Text>\n            </View>\n          ) : null}\n          {etiqueta ? (\n            <View style={s.chipOscuro}>\n              <Text numberOfLines={1} style={s.chipTexto}>{etiqueta}</Text>\n            </View>\n          ) : null}\n        </View>\n      )}\n\n      {/* Fila de acciones: interés · estrella · carrito · corazón. `box-none` para que el hueco\n          entre botones no se trague el toque que abre la ficha. Todo va sobre fondo oscuro\n          TRASLÚCIDO: es lo que lo mantiene legible sobre una foto cualquiera sin depender del velo,\n          que empieza mucho más abajo. El botón mide 15 del icono + 5 de relleno por lado = 25, y con\n          el `hitSlop` de 8 el blanco táctil pasa de los 44 dp que pide la guía. */}\n      {hayAcciones && (\n        <View style={s.acciones} pointerEvents=\"box-none\">\n          {interes > 0 && <Text style={s.interes}>♥ {interes}</Text>}\n          {onSpecial && (\n            <Pressable onPress={onSpecial} hitSlop={8} accessibilityRole=\"button\"\n              accessibilityLabel={isSpecial ? 'Quitar de especiales' : 'Marcar como especial'} style={s.botonIcono}>\n              <Star size={15} color={isSpecial ? brand.warning : brand.white} fill={isSpecial ? brand.warning : 'rgba(0,0,0,0.35)'} />\n            </Pressable>\n          )}\n          {onAdd && (\n            <Pressable onPress={onAdd} hitSlop={8} accessibilityRole=\"button\"\n              accessibilityLabel={`Añadir ${product.title} al carrito`} style={s.botonIcono}>\n              <ShoppingCart size={15} color={brand.white} />\n            </Pressable>\n          )}\n          {onFav && (\n            <Pressable onPress={onFav} hitSlop={8} accessibilityRole=\"button\"\n              accessibilityLabel={favorited ? 'Quitar de favoritos' : 'Añadir a favoritos'} style={s.botonIcono}>\n              <Heart size={15} color={favorited ? brand.like : brand.white} fill={favorited ? brand.like : 'rgba(0,0,0,0.35)'} />\n            </Pressable>\n          )}\n        </View>\n      )}\n\n      <View style={s.cuerpo} pointerEvents=\"none\">\n        <Text numberOfLines={2} style={s.titulo}>{product.title}</Text>\n        <Precio valor={product.priceXaf} forma=\"pastilla\" tamano={precioTamano} style={s.precio} />\n      </View>\n    </View>\n  );\n}\n\n/**\n * Esqueleto de carga de la tarjeta. Vive aquí, y no en cada pantalla, por la misma razón que la\n * tarjeta: **tiene que medir exactamente lo mismo**. Si el esqueleto midiera distinto, el contenido\n * daría un salto al terminar de cargar. Las barras van al pie, que es donde está el texto de verdad;\n * el resto de la tarjeta es la foto.\n */\nexport function EsqueletoTarjeta({ width, aspect = PROPORCION_TARJETA }: { width?: number; aspect?: number }) {\n  const { colors } = useTheme();\n  return (\n    <View\n      style={[\n        s.card,\n        {\n          aspectRatio: aspect, backgroundColor: colors.surface, borderColor: colors.border,\n          justifyContent: 'flex-end', padding: espaciado.e8, gap: espaciado.e4,\n        },\n        width ? { width } : { flex: 1 },\n      ]}\n    >\n      <View style={{ height: 34, borderRadius: radios.sm, backgroundColor: colors.border, width: '95%' }} />\n      <View style={{ height: 22, borderRadius: radios.sm, backgroundColor: colors.border, width: '60%' }} />\n    </View>\n  );\n}\n\nconst s = StyleSheet.create({\n  /**\n   * La altura NO se declara: sale del ancho por `aspectRatio`. Eso es lo que deja la rejilla\n   * alineada sin cascada y sin tener que conocer la proporción de cada foto. `alignSelf` para que\n   * el `stretch` de la fila no pise la proporción.\n   */\n  card: { alignSelf: 'flex-start', borderRadius: radios.lg, overflow: 'hidden', borderWidth: trazo.fino },\n  etiquetas: { position: 'absolute', top: 8, left: 8, right: 8, alignItems: 'flex-start', gap: espaciado.e4 },\n  chipNaranja: { backgroundColor: 'rgba(255,107,53,0.92)', borderRadius: radios.sm, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2, alignSelf: 'flex-start' },\n  chipEmoji: { fontSize: tipografia.micro },\n  chipAzul: { backgroundColor: 'rgba(0,132,255,0.92)', borderRadius: radios.sm, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2, alignSelf: 'flex-start' },\n  chipPro: { color: brand.white, fontSize: tipografia.micro, fontWeight: peso.titulo, letterSpacing: 0.5 },\n  /* El estado del artículo y la etiqueta del sitio van sobre fondo oscuro TRASLÚCIDO y no con un\n     color del tema: van sobre una foto cualquiera, y es el mismo recurso que el corazón. */\n  chipOscuro: { maxWidth: '100%', alignSelf: 'flex-start', backgroundColor: 'rgba(0,0,0,0.55)', borderRadius: radios.sm, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2 },\n  chipTexto: { color: brand.white, fontSize: tipografia.micro, fontWeight: peso.fuerte },\n  acciones: { position: 'absolute', top: 8, right: 8, flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 },\n  interes: { overflow: 'hidden', fontSize: tipografia.micro, fontWeight: peso.fuerte, color: brand.white, backgroundColor: 'rgba(0,0,0,0.42)', borderRadius: radios.lg, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  botonIcono: { padding: espaciado.e5, borderRadius: radios.full, backgroundColor: 'rgba(0,0,0,0.42)' },\n  /** El contenido, pegado al pie sobre el velo. `none` porque dentro no hay nada interactivo. */\n  cuerpo: { position: 'absolute', left: 0, right: 0, bottom: 0, padding: espaciado.e8 },\n  /** Blanco fijo y no `colors.textPrimary`: el texto va sobre el velo oscuro, en los dos temas. La\n   *  sombra es funcional —la primera línea cae donde el velo todavía es claro—, no adorno.\n   *\n   *  El `800` es el ÚNICO literal de peso que queda aquí, y es a propósito: **la escala `peso` no lo\n   *  contiene** (es 400/500/700/900) mientras es el peso de énfasis dominante de la app, con 766\n   *  usos. Migrarlo a 700 o a 900 cambiaría el aspecto de todos ellos, así que es una decisión de\n   *  diseño pendiente y no una que se tome dentro de un refactor de tarjetas. Todo lo demás de este\n   *  fichero —`peso.titulo`, `peso.fuerte`, `trazo.fino` y cada tamaño y radio— va por token. */\n  titulo: { fontSize: tipografia.body, fontWeight: '800', color: brand.white, textShadowColor: 'rgba(0,0,0,0.5)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 3 },\n  /** Todo lo demás de la pastilla —fondo, borde, radio, relleno y tipografía— lo pone `Precio`, que\n   *  es quien sabe que la cifra y su unidad son una sola pieza y no pueden partirse en dos líneas.\n   *  Aquí sólo el hueco con el título, y en la escala de espaciado. */\n  precio: { marginTop: espaciado.e8 },\n});\n","// Copyright © 2024 650 Industries.\n'use client';\nimport { Component } from 'react';\nimport { Platform, processColor } from 'react-native';\nimport NativeLinearGradient from './NativeLinearGradient';\n/**\n * Renders a native view that transitions between multiple colors in a linear direction.\n */\nexport class LinearGradient extends Component {\n    render() {\n        const { colors, locations, start, end, dither, ...props } = this.props;\n        let resolvedLocations = locations;\n        if (locations && colors.length !== locations.length) {\n            console.warn('LinearGradient colors and locations props should be arrays of the same length');\n            resolvedLocations = locations.slice(0, colors.length);\n        }\n        return (<NativeLinearGradient {...props} colors={Platform.select({\n                web: colors,\n                default: colors.map(processColor),\n            })} dither={Platform.select({ android: dither })} locations={resolvedLocations} startPoint={_normalizePoint(start)} endPoint={_normalizePoint(end)}/>);\n    }\n}\nfunction _normalizePoint(point) {\n    if (!point) {\n        return undefined;\n    }\n    if (Array.isArray(point) && point.length !== 2) {\n        console.warn('start and end props for LinearGradient must be of the format [x,y] or {x, y}');\n        return undefined;\n    }\n    return Array.isArray(point) ? point : [point.x, point.y];\n}\n//# sourceMappingURL=LinearGradient.js.map","import { requireNativeViewManager } from 'expo-modules-core';\nimport * as React from 'react';\nimport { StyleSheet, View } from 'react-native';\nexport default function NativeLinearGradient({ colors, locations, startPoint, endPoint, children, style, dither, ...props }) {\n    // TODO: revisit whether we need to inherit the container's borderRadius since this issue has\n    // been resolved: https://github.com/facebook/react-native/issues/3198\n    const flatStyle = StyleSheet.flatten(style) ?? {};\n    const borderRadius = flatStyle.borderRadius ?? 0;\n    // This is the format from:\n    // https://developer.android.com/reference/android/graphics/Path.html#addRoundRect(android.graphics.RectF,%20float[],%20android.graphics.Path.Direction)\n    const borderRadiiPerCorner = [\n        flatStyle.borderTopLeftRadius ?? borderRadius,\n        flatStyle.borderTopLeftRadius ?? borderRadius,\n        flatStyle.borderTopRightRadius ?? borderRadius,\n        flatStyle.borderTopRightRadius ?? borderRadius,\n        flatStyle.borderBottomRightRadius ?? borderRadius,\n        flatStyle.borderBottomRightRadius ?? borderRadius,\n        flatStyle.borderBottomLeftRadius ?? borderRadius,\n        flatStyle.borderBottomLeftRadius ?? borderRadius,\n    ];\n    return (<View {...props} style={style}>\n      <BaseNativeLinearGradient style={StyleSheet.absoluteFill} colors={colors} startPoint={startPoint} endPoint={endPoint} locations={locations} borderRadii={borderRadiiPerCorner} dither={dither}/>\n      {children}\n    </View>);\n}\nconst BaseNativeLinearGradient = requireNativeViewManager('ExpoLinearGradient');\n//# sourceMappingURL=NativeLinearGradient.android.js.map","/**\n * La pantalla de UN canal de avisos — `/ecomerse-mensajes-avisos?canal=transaction|logistics`.\n *\n * POR QUÉ LA RUTA SE LLAMA ASÍ Y NO `/ecomerse-avisos`\n * Porque el pie decide qué pestaña está activa comparando el **prefijo** del pathname, y «Mensajes»\n * se compara con `/ecomerse-mensajes` (`PieDelMercado.tsx:89`). Una ruta hermana como\n * `/ecomerse-avisos` NO empieza por ese prefijo, así que al abrir el canal la pestaña «Mensajes» se\n * apagaría y no habría ninguna encendida: el usuario estaría dentro de Mensajes con el pie diciendo\n * que está en ninguna parte. Colgando la ruta DEBAJO del prefijo —`/ecomerse-mensajes-avisos`— la\n * regla que ya está escrita sigue valiendo sin tocar el pie. Es la misma trampa que documenta\n * `BarraTienda.tsx:82` con `/tienda`, resuelta por el nombre y no con una excepción.\n *\n * UN CANAL, O LOS DOS\n * Si la URL no trae `canal` —o trae uno que no existe, porque la puede escribir cualquiera—, la\n * pantalla enseña **los dos canales juntos** y lo dice en la cabecera («Todos los avisos»). Tratarlo\n * como un error sería castigar al usuario por una URL rara; inventarse un canal por defecto sería\n * peor: enseñaría avisos que nadie pidió con un título que no les corresponde.\n *\n * TOCAR UN AVISO LO MARCA LEÍDO — y no lleva a ningún sitio\n * El gesto natural de una bandeja es «abrir», pero aquí no hay nada que abrir: el aviso ES el\n * contenido (título, cuerpo y referencia del pedido) y la acción que falta es quitarlo de «sin\n * leer». Así que el toque marca leído y el aviso se queda donde está, con su punto apagado. Si\n * algún día hay ficha de pedido, el toque llevará allí; hoy prometerlo sería mentir.\n *\n * EL CONTADOR SE ACTUALIZA ANTES DE QUE CONTESTE EL SERVIDOR, Y SE CORRIGE SI FALLA\n * Marcar leído es idempotente y no puede fallar por reglas de negocio, así que esperar a la red para\n * apagar un punto sería hacer esperar al dedo por nada. Se pinta el cambio al instante y, si la\n * petición falla, se **vuelve a leer del servidor**: la verdad vuelve sola, sin inventarse un estado\n * intermedio que nadie ha confirmado.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Pressable, RefreshControl, StyleSheet, Text, View,\n} from 'react-native';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, CheckCheck } from 'lucide-react-native';\nimport { EmptyState, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseNotice, type EcomerseNoticeCounts } from '../api/ecomerse';\nimport { getTimeAgo } from '../utils/formatHelpers';\nimport { useSession } from '../state/session';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { buscarCanal } from '../components/ecomerse/canalesAviso';\n/* La tarjeta del artículo. Se llamaba `FichaProductoAviso`; desde la Fase 5 la usan también las\n   reclamaciones, así que el nombre se quedó corto y se generalizó (ver el propio componente). */\nimport { FichaArticulo } from '../components/ecomerse/FichaArticulo';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\n\n/**\n * Lo que un lector de pantalla lee de una fila. Dice los cuatro datos que dan sentido al aviso —si\n * está leído, qué pasó, de qué artículo y de qué pedido— y en ese orden, que es el de la pantalla.\n * Se compone aquí y no en el `renderItem` para que la etiqueta y lo que se pinta no puedan divergir.\n */\nfunction etiquetaDe(a: EcomerseNotice): string {\n  const partes = [\n    a.read ? 'Leído' : 'Sin leer',\n    a.title,\n    a.product ? a.product.title : null,\n    a.orderRef ? `Pedido ${a.orderRef}` : null,\n  ];\n  return partes.filter(Boolean).join('. ') + '.';\n}\n\nexport default function EcomerseAvisosScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const sinLeer = useSinLeerMercado();\n  const { canal: canalParam } = useLocalSearchParams<{ canal?: string }>();\n\n  const canal = buscarCanal(canalParam);\n  const titulo = canal?.label ?? 'Todos los avisos';\n\n  const [avisos, setAvisos] = useState<EcomerseNotice[] | null>(null);\n  const [cuenta, setCuenta] = useState<EcomerseNoticeCounts | null>(null);\n  const [cargando, setCargando] = useState(false);\n  const [refrescando, setRefrescando] = useState(false);\n  /** «Aún no he preguntado» y «pregunté y falló» no son lo mismo. Ver `ecomerse-perfil.tsx`. */\n  const [intentado, setIntentado] = useState(false);\n\n  const leer = useCallback(async () => {\n    const [lista, c] = await Promise.all([\n      ecomerseApi.notices(canal?.id),\n      ecomerseApi.noticeCounts(),\n    ]);\n    setAvisos(lista.items);\n    setCuenta(c);\n  }, [canal?.id]);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated) { setAvisos(null); setCuenta(null); setIntentado(true); return; }\n    setCargando(true);\n    try {\n      await leer();\n    } catch {\n      setAvisos(null);\n      setCuenta(null);\n    } finally {\n      setCargando(false);\n      setIntentado(true);\n    }\n  }, [isAuthenticated, leer]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const refrescar = useCallback(async () => {\n    setRefrescando(true);\n    try { await leer(); } catch { /* se queda lo que había: un tic de red no borra la bandeja */ }\n    finally { setRefrescando(false); }\n  }, [leer]);\n\n  /** Marcar uno. Optimista a propósito (ver la cabecera del fichero); si falla, se relee. */\n  const marcarUno = useCallback(async (aviso: EcomerseNotice) => {\n    if (aviso.read) return;\n    setAvisos((prev) => prev?.map((a) => (a.id === aviso.id ? { ...a, read: true } : a)) ?? prev);\n    try {\n      await ecomerseApi.markNoticeRead(aviso.id);\n      await leer();\n    } catch {\n      await refrescar();\n    }\n  }, [leer, refrescar]);\n\n  const marcarTodo = useCallback(async () => {\n    setAvisos((prev) => prev?.map((a) => ({ ...a, read: true })) ?? prev);\n    try {\n      await ecomerseApi.markAllNoticesRead(canal?.id);\n      await leer();\n    } catch {\n      await refrescar();\n    }\n  }, [canal?.id, leer, refrescar]);\n\n  const sinLeerAqui = canal\n    ? (cuenta?.channels[canal.id].unread ?? 0)\n    : (cuenta?.unread ?? 0);\n  const fallo = isAuthenticated && intentado && !cargando && avisos === null;\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable\n          onPress={() => router.back()}\n          hitSlop={12}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Volver\"\n        >\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]} numberOfLines={1}>\n          {titulo}\n        </Text>\n        {/*\n          «Marcar todo leído» SÓLO aparece si hay algo que marcar: un botón que no hace nada es peor\n          que no tenerlo. Marca los dos canales o sólo éste, según de dónde se haya entrado.\n        */}\n        {sinLeerAqui > 0 ? (\n          <Pressable\n            onPress={() => void marcarTodo()}\n            hitSlop={12}\n            accessibilityRole=\"button\"\n            accessibilityLabel={`Marcar como leído${canal ? ` todo el canal ${canal.label}` : ' todos los avisos'}`}\n            style={({ pressed }) => [styles.accion, { opacity: pressed ? 0.6 : 1 }]}\n          >\n            <CheckCheck size={icono.md} color={colors.primary} />\n            <Text style={[styles.accionTexto, { color: colors.primary }]}>Todo leído</Text>\n          </Pressable>\n        ) : (\n          <View style={styles.hueco} />\n        )}\n      </View>\n\n      {!isAuthenticated ? (\n        <View style={styles.centro}>\n          <EmptyState\n            emoji=\"💬\"\n            titulo=\"Entra para ver tus avisos\"\n            texto=\"Los avisos van con tu cuenta: sin sesión no hay nada que enseñar.\"\n            accionLabel=\"Iniciar sesión\"\n            accionPrimaria\n            onAccion={() => router.push('/auth' as never)}\n          />\n        </View>\n      ) : fallo ? (\n        <View style={styles.centro}>\n          <EmptyState\n            emoji=\"📡\"\n            titulo=\"No se pudieron cargar los avisos\"\n            texto=\"El servidor no contestó. Puede ser la red del aparato: vuelve a intentarlo.\"\n            accionLabel=\"Reintentar\"\n            onAccion={() => void cargar()}\n          />\n        </View>\n      ) : cargando && avisos === null ? (\n        <View style={styles.centro}>\n          <ActivityIndicator color={colors.primary} />\n        </View>\n      ) : (\n        <FlatList\n          data={avisos ?? []}\n          keyExtractor={(a) => a.id}\n          contentContainerStyle={{ paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e24 }}\n          refreshControl={\n            <RefreshControl refreshing={refrescando} onRefresh={() => void refrescar()} tintColor={colors.primary} />\n          }\n          ListEmptyComponent={\n            <View style={styles.centro}>\n              <EmptyState\n                emoji=\"🗒️\"\n                titulo=\"Aquí no hay nada todavía\"\n                /* El vacío dice QUÉ va a aparecer, y con las palabras del canal: es lo único que\n                   distingue «no te ha pasado nada» de «esto no funciona». */\n                texto={canal?.nota ?? 'Los dos canales del sistema: tus pedidos y el viaje del paquete.'}\n              />\n            </View>\n          }\n          renderItem={({ item }) => (\n            <Pressable\n              onPress={() => void marcarUno(item)}\n              accessibilityRole=\"button\"\n              accessibilityLabel={etiquetaDe(item)}\n              style={({ pressed }) => [\n                styles.aviso,\n                { borderBottomColor: colors.border, opacity: pressed ? 0.6 : 1 },\n              ]}\n            >\n              {/*\n                El punto del no leído. Se pinta SIEMPRE el mismo hueco —vacío cuando ya está leído—\n                para que las filas no bailen de sitio al marcar una, que es el tic que hace que una\n                lista parezca rota.\n              */}\n              <View style={styles.puntoCol}>\n                {!item.read && <View style={[styles.punto, { backgroundColor: brand.like }]} />}\n              </View>\n              <View style={styles.avisoTexto}>\n                {/* Cabecera: QUÉ pasó y CUÁNDO, en una línea. El sujeto es la tarjeta de abajo. */}\n                <View style={styles.avisoCabecera}>\n                  <Text\n                    style={[\n                      styles.avisoTitulo,\n                      { color: colors.textPrimary },\n                      !item.read && { fontWeight: peso.titulo },\n                    ]}\n                    numberOfLines={1}\n                  >\n                    {item.title}\n                  </Text>\n                  <Text style={[styles.avisoHora, { color: colors.textSecondary }]}>\n                    {getTimeAgo(item.createdAt)}\n                  </Text>\n                </View>\n\n                {/*\n                  EL SUJETO DEL AVISO ES EL ARTÍCULO. Cuando el pedido trae su línea —que es el caso\n                  normal— se pinta la ficha con foto, título y precio, y el CUERPO DEL AVISO NO SE\n                  PINTA: era un párrafo que repetía en palabras lo que la tarjeta dice de un vistazo\n                  («Cancelado: motivo · stock restaurado · Pedido 94E70807»). El motivo largo sigue en\n                  el hilo del pedido, que es su sitio, y aquí queda la referencia corta para poder\n                  identificar la compra.\n                  Sin artículo (un aviso cuyo pedido no guardó líneas), el cuerpo es lo único que hay\n                  y se pinta recortado a dos líneas: mejor eso que una fila sin sujeto.\n                */}\n                {item.product ? (\n                  <FichaArticulo articulo={item.product} />\n                ) : item.body ? (\n                  <Text style={[styles.avisoCuerpo, { color: colors.textSecondary }]} numberOfLines={2}>\n                    {item.body}\n                  </Text>\n                ) : null}\n\n                {item.orderRef ? (\n                  <Text style={[styles.referencia, { color: colors.textSecondary }]}>\n                    Pedido {item.orderRef}\n                  </Text>\n                ) : null}\n              </View>\n            </Pressable>\n          )}\n        />\n      )}\n\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  /**\n   * El título cede el ancho antes que la acción: con «Asistente de logística» y «Todo leído» en la\n   * misma fila, el que tiene que encogerse es el texto largo, no el botón. `flexShrink` y no\n   * `flex: 1`: con `flex: 1` el título empujaría la acción fuera de la pantalla.\n   */\n  cabeceraTitulo: { flexShrink: 1, fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  accion: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 },\n  accionTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  hueco: { width: icono.lg },\n  centro: { paddingTop: espaciado.e24, paddingHorizontal: espaciado.e16 },\n  aviso: {\n    flexDirection: 'row',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  puntoCol: { width: espaciado.e8, paddingTop: espaciado.e8, alignItems: 'center' },\n  punto: { width: espaciado.e8, height: espaciado.e8, borderRadius: radios.full },\n  avisoTexto: { flex: 1 },\n  /* La cabecera de la fila: el hecho a la izquierda y el tiempo a la derecha, en la misma línea.\n     `baseline` y no `center` para que la hora se apoye en la base del título y no quede flotando. */\n  avisoCabecera: { flexDirection: 'row', alignItems: 'baseline', gap: espaciado.e8 },\n  avisoTitulo: { flex: 1, fontSize: tipografia.body, fontWeight: peso.fuerte },\n  avisoCuerpo: { fontSize: tipografia.caption, marginTop: espaciado.e8, lineHeight: 17 },\n  avisoHora: { fontSize: tipografia.micro },\n  referencia: { fontSize: tipografia.micro, marginTop: espaciado.e8 },\n});\n","/**\n * PieDelMercado — el pie PROPIO del Mercado: Home · Mensajes · Perfil.\n *\n * POR QUÉ EXISTE, Y POR QUÉ ES HERMANO DE `BarraTienda` Y NO DEL DOCK\n * El dock global (`FloatingFooter.tsx`) lo pintan siete pantallas y **ninguna del Mercado**: el\n * Mercado era una excursión de pantalla completa, se entraba por una celda de Inicio y se salía con\n * la flecha de la cabecera. Con la zona del comerciante se tomó la decisión contraria y quedó escrita\n * en `BarraTienda.tsx:9`: un módulo con varias cosas dentro tiene **barra propia**, porque su usuario\n * no sale del módulo para moverse entre ellas. El Mercado está en ese mismo caso desde que tiene\n * tres destinos con datos, así que se le da la misma solución: mismo lenguaje visual, mismos tokens,\n * misma accesibilidad.\n *\n * LAS DOS BARRAS NO SE APILAN. Y no es suerte: el Mercado no pinta el dock, así que aquí hay **una**\n * barra de 62 dp, no dos. Si algún día una pantalla del Mercado pinta el dock, esto se rompe a la\n * vista — y esa es la señal de que alguien no leyó esta cabecera.\n *\n * CÓMO SE SALE DEL MERCADO, que es la pregunta que este pie abre\n * El pie mueve entre los tres destinos, no hacia fuera. La salida al resto de la app sigue siendo la\n * flecha «Volver» de la cabecera del Mercado (`ecomerse.tsx:297`), que ya existía y ya funciona. No\n * se le añade un cuarto destino «Más»: un destino que sólo sirve para irse no es un destino.\n *\n * `accessibilityRole=\"tab\"` y `accessibilityState={{ selected }}` no son adorno: una barra que no\n * comunica en qué pestaña está deja al lector de pantalla sin saber dónde está (mismo criterio que\n * `BarraTienda.tsx:21`).\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Home, MessageCircle, User, type LucideIcon } from 'lucide-react-native';\nimport { brand, elevation, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { usePathname, useRouter } from 'expo-router';\n\n/** Altura del pie sin el área segura. La usan las pantallas como relleno inferior. */\nexport const PIE_MERCADO_H = 62;\n\nexport interface DestinoMercado {\n  id: 'home' | 'mensajes' | 'perfil';\n  label: string;\n  icon: LucideIcon;\n  ruta: string;\n}\n\n/**\n * Orden: donde se compra, donde se habla y quien soy. El mismo que el de las capturas de referencia\n * —el Mercado primero, porque es donde entra el usuario— y el mismo que ya usa el dock de la casa.\n */\nexport const DESTINOS_MERCADO: DestinoMercado[] = [\n  { id: 'home', label: 'Home', icon: Home, ruta: '/ecomerse' },\n  { id: 'mensajes', label: 'Mensajes', icon: MessageCircle, ruta: '/ecomerse-mensajes' },\n  { id: 'perfil', label: 'Perfil', icon: User, ruta: '/ecomerse-perfil' },\n];\n\nexport default function PieDelMercado({\n  /**\n   * Sin leer en Mensajes. **Por defecto 0, y con el contador apagado a propósito**: el contador real\n   * llega en la fase de los avisos, y montar hoy un sondeo de red en tres pantallas para pintar un\n   * cero sería pagar el precio sin el dato. Es el mismo criterio que el `showUnreadBadge = false` del\n   * dock (`FloatingFooter.tsx:48`).\n   */\n  sinLeer = 0,\n}: {\n  sinLeer?: number;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const ruta = usePathname();\n\n  return (\n    <View\n      style={[\n        styles.pie,\n        {\n          backgroundColor: colors.card,\n          borderTopColor: colors.border,\n          paddingBottom: insets.bottom,\n          height: PIE_MERCADO_H + insets.bottom,\n        },\n      ]}\n    >\n      {DESTINOS_MERCADO.map((destino) => {\n        /**\n         * `/ecomerse` es PREFIJO de todas las rutas del Mercado (`/ecomerse-mensajes`,\n         * `/ecomerse-detail`, `/ecomerse-perfil`…), así que comparar con `startsWith` daría Home\n         * activo en todas partes. Es la misma trampa que documenta `BarraTienda.tsx:82` con\n         * `/tienda`, y se resuelve igual: Home se compara exacto, los demás por prefijo.\n         */\n        const activo = destino.ruta === '/ecomerse' ? ruta === '/ecomerse' : ruta.startsWith(destino.ruta);\n        const tinte = activo ? colors.primary : colors.textSecondary;\n        const Icono = destino.icon;\n        const contador = destino.id === 'mensajes' ? sinLeer : 0;\n        return (\n          <Pressable\n            key={destino.id}\n            onPress={() => { if (!activo) router.replace(destino.ruta as never); }}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected: activo }}\n            accessibilityLabel={contador > 0 ? `${destino.label}, ${contador} sin leer` : destino.label}\n            style={({ pressed }) => [styles.item, { opacity: pressed ? 0.6 : 1 }]}\n          >\n            <View>\n              <Icono\n                size={icono.md}\n                color={tinte}\n                strokeWidth={activo ? trazo.marcado : trazo.fuerte}\n              />\n              {contador > 0 && (\n                <View style={[styles.insignia, { borderColor: colors.card }]}>\n                  <Text style={styles.insigniaTexto}>{contador > 9 ? '9+' : contador}</Text>\n                </View>\n              )}\n            </View>\n            <Text style={[styles.label, { color: tinte }, activo && styles.labelActivo]} numberOfLines={1}>\n              {destino.label}\n            </Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  pie: {\n    position: 'absolute',\n    left: 0,\n    right: 0,\n    bottom: 0,\n    zIndex: 40,\n    flexDirection: 'row',\n    alignItems: 'stretch',\n    borderTopWidth: trazo.fino,\n    ...elevation.lg,\n  },\n  item: {\n    flex: 1,\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: espaciado.e4 / 2,\n    paddingVertical: espaciado.e8,\n  },\n  label: { fontSize: tipografia.micro, fontWeight: peso.fuerte },\n  labelActivo: { fontWeight: peso.titulo },\n  /**\n   * El contador. El borde que lo despega del icono sale del **tema** (`colors.card`, el color real\n   * de la barra) y no de `brand.white` como en el dock: allí el borde es blanco fijo, así que en modo\n   * oscuro el aro se ve blanco sobre una barra oscura. Aquí el aro es del color de lo que hay detrás.\n   */\n  insignia: {\n    position: 'absolute',\n    top: -espaciado.e4,\n    right: -espaciado.e8,\n    backgroundColor: brand.like,\n    borderRadius: radios.full,\n    minWidth: espaciado.e16,\n    height: espaciado.e16,\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderWidth: trazo.base,\n    paddingHorizontal: espaciado.e4,\n  },\n  insigniaTexto: { color: brand.white, fontSize: tipografia.micro, fontWeight: peso.titulo },\n});\n","/**\n * LOS DOS CANALES DEL SISTEMA — el contrato compartido (Fase 3 del pie del Mercado, 22-sep-2026).\n *\n * POR QUÉ ESTÁ EN UN MÓDULO Y NO DENTRO DE UNA PANTALLA\n * Exactamente por lo mismo que `seccionesCompra.ts`: el rótulo de un canal y el significado de su id\n * los usan **dos** sitios —la bandeja de Mensajes, que pinta las dos filas con su contador, y la\n * pantalla del canal, que pone ese rótulo en su cabecera y lo manda en la URL—. Si cada uno\n * guardara su copia, un día la fila diría «Avisos de tus pedidos» y la cabecera «Transacciones», y\n * el usuario no tendría forma de saber que son el mismo sitio. **El id es el que viaja en la URL**,\n * y por eso la URL y las dos pantallas hablan del mismo canal por construcción.\n *\n * LA `nota` EXPLICA QUÉ TRAE CADA CANAL, no lo adorna\n * Una fila que sólo dice «Avisos de tus pedidos» no ayuda a decidir cuál abrir; la nota enumerada\n * («cuando pagas, cuando la tienda acepta, cuando se cancela…») sí. Está escrita con los hechos que\n * el servidor produce de verdad —los ocho códigos de `avisoDe()` en `ecomerse.service.ts`— y no con\n * una lista aspiracional: si mañana se añade un hecho, esto se queda corto pero **no miente**.\n *\n * El ORDEN es el del uso: primero lo que pasó con el dinero, después dónde va el paquete. Es el\n * mismo orden en que la bandeja pinta sus filas y en el que el servidor devuelve los contadores.\n */\n\n/** Los dos canales. El tipo vive aquí y el cliente de la API lo importa de aquí. */\nexport type CanalAviso = 'transaction' | 'logistics';\n\nexport interface CanalDef {\n  id: CanalAviso;\n  /** El rótulo de la fila y el título de la pantalla. El mismo texto en los dos sitios, a propósito. */\n  label: string;\n  /** Qué aparece dentro, con los hechos reales. */\n  nota: string;\n}\n\nexport const CANALES_AVISO: CanalDef[] = [\n  {\n    id: 'transaction',\n    label: 'Avisos de tus pedidos',\n    nota: 'Cuando el pedido nace, cuando la tienda lo confirma, cuando se cancela y cuando se abre o se cierra una disputa.',\n  },\n  {\n    id: 'logistics',\n    label: 'Asistente de logística',\n    nota: 'El viaje del paquete: el agente asignado, la salida hacia tu zona y la entrega.',\n  },\n];\n\n/**\n * El canal que pide la URL —`/ecomerse-mensajes-avisos?canal=logistics`—, o `null` si el id no es\n * de ningún canal. Devolver `null` en vez de un canal por defecto es lo que permite que una URL\n * manipulada o vacía se lea como «todos los avisos» en lugar de como un canal que nadie pidió.\n */\nexport const buscarCanal = (id?: string | null): CanalDef | null =>\n  CANALES_AVISO.find((c) => c.id === id) ?? null;\n","/**\n * FichaArticulo — la tarjeta del artículo EMBEBIDA en una fila de lista.\n *\n * DÓNDE SE USA. En la bandeja de avisos y en la lista de reclamaciones. En las dos el sujeto de la\n * fila es **la compra**: «esto es lo que pasó» o «esto es lo que reclamé», siempre con el artículo\n * delante. La foto, el título y el precio son lo que permite reconocer de un vistazo de qué pedido se\n * habla sin leerse el texto.\n *\n * POR QUÉ NO ES `TarjetaProducto`. Porque **no es la misma pieza**: aquélla es la tarjeta de la\n * rejilla —3:4, foto a sangre, velo, precio en pastilla porque debajo hay foto, corazón y carrito— y\n * mide el ancho completo de una columna. Aquí hace falta lo contrario: un bloque horizontal y bajo\n * que quepa dentro de una fila de lista, sin acciones y sin velo, porque el texto va al lado de la\n * foto y no encima. Meter la tarjeta grande aquí sería usar la pieza equivocada y además cargarle\n * props que no tienen sentido (`onFav` dentro de una reclamación no pinta nada).\n *\n * SE LLAMABA `FichaProductoAviso` HASTA LA FASE 5. Al llegar la lista de reclamaciones quedó claro que\n * el nombre mentía: no es «la tarjeta de un aviso», es la tarjeta del artículo de un pedido. Renombrar\n * costaba cuatro líneas; dejar el nombre viejo habría hecho que el siguiente que la reutilizara\n * creyera que está tocando la bandeja de avisos.\n *\n * LO QUE COMPARTE CON LA TARJETA GRANDE, porque son reglas del proyecto y no de la pieza:\n *   · El **precio** se pinta con `Precio` (nunca un texto suelto): una sola forma de escribir XAF.\n *   · La **foto** es `expo-image` con `contentFit=\"cover\"` y un marco de proporción fija, para que\n *     las fotos verticales y las cuadradas no bailen la altura de la fila.\n *   · Cuando no hay foto, se dice con un icono sobre el fondo del tema; **no** se pinta un marco\n *     gris vacío, que se lee como «no ha cargado».\n *\n * LOS COLORES Y LOS GROSORES SALEN DEL TEMA Y DE LAS ESCALAS. Nada a mano: la guardia de diseño\n * (`npm run diseno`) cuenta cada `fontWeight`, `borderRadius` y `borderWidth` suelto del proyecto, y\n * esta pantalla no viene a subir esa cuenta.\n */\n\nimport React from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { Package } from 'lucide-react-native';\nimport { Precio, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport type { EcomerseArticuloPedido } from '../../api/ecomerse';\n\n/** Lado del marco de la foto. Cuadrado y fijo: es lo que mantiene la fila a una altura estable. */\nconst LADO_FOTO = 56;\n\nexport function FichaArticulo({ articulo }: { articulo: EcomerseArticuloPedido }) {\n  const { colors } = useTheme();\n  const foto = articulo.photoUrl || null;\n\n  return (\n    <View style={styles.ficha}>\n      <View style={[styles.marco, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n        {foto ? (\n          <Image source={{ uri: foto }} style={styles.foto} contentFit=\"cover\" />\n        ) : (\n          /* Sin foto: se dice con el icono del Mercado. Nunca un hueco gris, que se lee como error. */\n          <Package size={icono.md} color={colors.textSecondary} />\n        )}\n      </View>\n\n      <View style={styles.texto}>\n        <Text style={[styles.titulo, { color: colors.textPrimary }]} numberOfLines={2}>\n          {articulo.title}\n        </Text>\n        {/* La combinación comprada («Rojo · M») sin la cual no se sabe qué unidad se sirvió. */}\n        {articulo.variantName ? (\n          <Text style={[styles.variante, { color: colors.textSecondary }]} numberOfLines={1}>\n            {articulo.variantName}\n          </Text>\n        ) : null}\n        <View style={styles.precioFila}>\n          <Precio valor={articulo.priceXaf} tamano=\"sm\" />\n          {/* La cantidad sólo se dice cuando es más de uno: «×1» en todas las filas es ruido. */}\n          {articulo.qty > 1 ? (\n            <Text style={[styles.cantidad, { color: colors.textSecondary }]}>×{articulo.qty}</Text>\n          ) : null}\n        </View>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  ficha: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n  },\n  marco: {\n    width: LADO_FOTO,\n    height: LADO_FOTO,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    alignItems: 'center',\n    justifyContent: 'center',\n    overflow: 'hidden',\n  },\n  foto: { width: '100%', height: '100%' },\n  texto: { flex: 1 },\n  titulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  variante: { fontSize: tipografia.micro, marginTop: espaciado.e4 / 2 },\n  /* El precio y la cantidad en la misma línea, alineados por la base: la cifra manda y la cantidad\n     la acompaña, que es el orden en que se leen. */\n  precioFila: {\n    flexDirection: 'row',\n    alignItems: 'baseline',\n    gap: espaciado.e8,\n    marginTop: espaciado.e4,\n  },\n  cantidad: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n});\n","/**\n * useSinLeerMercado — cuántos mensajes sin leer tiene el comprador, para la insignia de «Mensajes».\n *\n * DE DÓNDE SALE EL NÚMERO\n * De **dos** sitios, y se suman: `GET /ecomerse/notices/counts` (los avisos del sistema, que los\n * cuenta la BASE —no se cuentan los de la bandeja, que tiene ventana de 100 y mentiría a la baja—)\n * y el `unread` de `GET /ecomerse/chats` (lo que las TIENDAS le han escrito). Desde la Fase 4\n * Mensajes tiene las dos cosas, y una insignia que sólo contara una sería una insignia a medias: el\n * vendedor podía estar esperando respuesta y la pestaña no lo decía.\n *\n * POR QUÉ ES UN MÓDULO Y NO UNA LÍNEA EN CADA PANTALLA\n * El pie lo pintan TRES pantallas (Home, Mensajes y Perfil) y la insignia tiene que decir lo mismo\n * en las tres. Con la consulta copiada en cada una, un día una pantalla contaría lo de un canal y\n * otra el total, y la insignia parpadearía al cambiar de pestaña sin que hubiera pasado nada.\n * `PieDelMercado.tsx` ya había dejado el hueco —la prop `sinLeer`, apagada a propósito hasta que\n * existiera el dato—; esto es el dato.\n *\n * SE VUELVE A PREGUNTAR AL ENTRAR EN FOCO, NO AL MONTAR\n * La pantalla se queda montada en la pila mientras navegas, así que con un `useEffect` la insignia\n * se quedaría con el número del día que abriste el Mercado: leerías los avisos, volverías, y\n * seguiría ahí. Es el mismo patrón —y el mismo fallo ya corregido— que en `ecomerse-perfil.tsx`.\n *\n * SI UNA CONSULTA FALLA, NO SE LLEVA POR DELANTE A LA OTRA\n * `allSettled` y no `all`: son dos rutas distintas y que una se caiga no borra lo que la otra sí\n * sabía. Sólo si fallan LAS DOS se devuelve 0, que en el pie significa «no hay nada sin leer» — la\n * insignia es un adorno de la navegación y no puede dejar sin pintar el pie, pero tampoco se finge\n * un número: no se inventa, se apaga.\n */\n\nimport { useCallback, useState } from 'react';\nimport { useFocusEffect } from 'expo-router';\nimport { ecomerseApi } from '../../api/ecomerse';\nimport { useSession } from '../../state/session';\n\nexport function useSinLeerMercado(): number {\n  const { isAuthenticated } = useSession();\n  const [sinLeer, setSinLeer] = useState(0);\n\n  const preguntar = useCallback(async () => {\n    if (!isAuthenticated) { setSinLeer(0); return; }\n    const [avisos, chats] = await Promise.allSettled([\n      ecomerseApi.noticeCounts(),\n      ecomerseApi.chats(),\n    ]);\n    if (avisos.status === 'rejected' && chats.status === 'rejected') { setSinLeer(0); return; }\n    const deAvisos = avisos.status === 'fulfilled' ? avisos.value.unread : 0;\n    const deTiendas = chats.status === 'fulfilled'\n      ? chats.value.chats.reduce((n, c) => n + (c.unread || 0), 0)\n      : 0;\n    setSinLeer(deAvisos + deTiendas);\n  }, [isAuthenticated]);\n\n  useFocusEffect(useCallback(() => { void preguntar(); }, [preguntar]));\n\n  return sinLeer;\n}\n","/**\n * La conversación del comprador con una tienda — `/ecomerse-mensajes-chat?conv=<conversationId>`.\n *\n * ── POR QUÉ LA RUTA CUELGA DE `/ecomerse-mensajes` Y NO ES `/ecomerse-chat` ─────────────────────\n * El pie decide qué pestaña está encendida comparando el **prefijo** del pathname\n * (`PieDelMercado.tsx:89`). Una ruta hermana como `/ecomerse-chat` no empieza por `/ecomerse-mensajes`,\n * así que —el día que esta pantalla pinte el pie— la pestaña «Mensajes» se apagaría estando dentro de\n * Mensajes. Colgando la ruta DEBAJO del prefijo, la regla que ya está escrita sigue valiendo sin\n * tocar el pie. Es exactamente la trampa que documenta `ecomerse-mensajes-avisos.tsx:6` con\n * `/ecomerse-avisos`, resuelta por el nombre y no con una excepción.\n *\n * ── ESTA PANTALLA NO PINTA EL PIE, Y A PROPÓSITO ───────────────────────────────────────────────\n * Abajo vive la barra de escribir. El pie del Mercado son 62 dp de cromo fijo, y con la barra de\n * escribir encima se comen media pantalla del hilo justo cuando hay teclado. El camino de vuelta ya\n * existe y es el de siempre: la flecha. (Las otras cuatro pantallas del Mercado sí lo pintan.)\n *\n * ── EL MOTOR DE CHAT NO SE DUPLICA ─────────────────────────────────────────────────────────────\n * Los mensajes, el envío y el «leído» van por `/lifebook/chat/conversations/…`, que es el MISMO hilo\n * que el vendedor tiene en su chat de siempre: la decisión cerrada de la fase (5.c) es que la\n * conversación es una y tiene dos caras —aquí el interlocutor se llama por su tienda, allí por su\n * nombre—. Lo único propio del Mercado es el rótulo, y eso lo da `POST /ecomerse/chats/open`.\n *\n * ── LOS MENSAJES SE PINTAN POR SU TEXTO, SEA CUAL SEA SU TIPO ──────────────────────────────────\n * El motor admite tipos ricos (foto, tarjeta de producto, pedido, votación…). Aquí se pinta el\n * `body`, que el servidor **siempre** rellena con algo legible («📷 Foto», «🛍 <título>») incluso en\n * los tipos ricos. Se elige eso y no una tarjeta a medias porque una tarjeta mal resuelta es peor que\n * una línea de texto correcta: el chat del Mercado enseña **lo que se dijo**, y el adorno de cada\n * tipo llegará con su pantalla.\n */\n\nimport React, { useCallback, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, Image, Pressable, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Send, ShieldCheck } from 'lucide-react-native';\nimport {\n  EmptyState, InlineError, alpha, brand, espaciado, icono, peso, radios, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { lifebookChatApi, type LbMessage } from '../api/lifebook';\nimport { getTimeAgo } from '../utils/formatHelpers';\nimport { useSession } from '../state/session';\nimport { whatsappATienda } from '../utils/whatsapp';\n\n/** Los datos de la tienda que llegan por la URL, para poder pintar la cabecera sin esperar a la red.\n *  Son de conveniencia: si faltan, la cabecera dice «Tienda» y el hilo se carga igual. */\nfunction useParametro(nombre: string): string | null {\n  const raw = useLocalSearchParams<Record<string, string | string[]>>();\n  const v = raw[nombre];\n  return (Array.isArray(v) ? v[0] : v) ?? null;\n}\n\nexport default function EcomerseMensajesChatScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const listaRef = useRef<FlatList<LbMessage>>(null);\n\n  const conv = useParametro('conv');\n  const tienda = useParametro('tienda');\n  const foto = useParametro('foto');\n  const telefono = useParametro('telefono');\n  const verificado = useParametro('verificado') === '1';\n\n  const [mensajes, setMensajes] = useState<LbMessage[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [borrador, setBorrador] = useState('');\n  const [enviando, setEnviando] = useState(false);\n  const [fotoRota, setFotoRota] = useState(false);\n\n  const cargar = useCallback(async () => {\n    if (!conv || !isAuthenticated) { setCargando(false); return; }\n    setCargando(true);\n    setError(null);\n    try {\n      const pagina = await lifebookChatApi.messages(conv, { limit: 50 });\n      setMensajes(pagina.messages);\n      /* Marcar leído al abrir es lo que hace que el contador del pie y el de la lista bajen al\n         entrar. No bloquea el pintado ni se espera su resultado: si falla, el hilo se lee igual y el\n         contador se corrige solo en la siguiente vuelta a la lista. */\n      void lifebookChatApi.markRead(conv).catch(() => undefined);\n    } catch {\n      setError('No se pudo cargar la conversación. Revisa tu conexión e inténtalo de nuevo.');\n    } finally {\n      setCargando(false);\n    }\n  }, [conv, isAuthenticated]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const enviar = useCallback(async () => {\n    const texto = borrador.trim();\n    if (!texto || !conv || enviando) return;\n    setEnviando(true);\n    /* El borrador se vacía YA y se devuelve si el envío falla: escribir, ver que el texto sigue ahí\n       y volver a pulsar es exactamente lo que hace dudar de si se mandó o no. */\n    setBorrador('');\n    try {\n      await lifebookChatApi.send(conv, texto);\n      await cargar();\n    } catch {\n      setBorrador(texto);\n      Alert.alert('Mensaje', 'No se pudo enviar. Inténtalo otra vez.');\n    } finally {\n      setEnviando(false);\n    }\n  }, [borrador, conv, enviando, cargar]);\n\n  const nombre = tienda ?? 'Tienda';\n  const hayFoto = Boolean(foto) && !fotoRota;\n\n  return (\n    <View style={[s.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[s.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <View style={s.cabeceraTienda}>\n          {hayFoto ? (\n            <Image\n              source={{ uri: foto as string }}\n              style={[s.avatar, { borderColor: colors.border }]}\n              onError={() => setFotoRota(true)}\n            />\n          ) : (\n            /* Sin logo —o con la imagen rota— se pinta la inicial, que es lo que ya hace la tarjeta\n               de tienda. Una imagen rota en una cabecera es peor que una letra. */\n            <View style={[s.avatar, s.avatarLetra, { backgroundColor: alpha(colors.primary, 0.15), borderColor: colors.border }]}>\n              <Text style={[s.inicial, { color: colors.primary }]}>{nombre.charAt(0).toUpperCase()}</Text>\n            </View>\n          )}\n          <View style={s.cabeceraTexto}>\n            <View style={s.cabeceraFila}>\n              <Text style={[s.cabeceraTitulo, { color: colors.textPrimary }]} numberOfLines={1}>{nombre}</Text>\n              {verificado && <ShieldCheck size={13} color={brand.success} />}\n            </View>\n            <Text style={[s.cabeceraNota, { color: colors.textSecondary }]} numberOfLines={1}>\n              Conversación con la tienda\n            </Text>\n          </View>\n        </View>\n        {/* EL ESCAPE VISIBLE (decisión 5.b): el chat es la puerta principal, WhatsApp convive. Vive\n            AQUÍ y no sólo en la ficha porque un escape que no está donde estás mirando no sirve\n            cuando el vendedor tarda en contestar. Sin teléfono, el botón no se pinta: no se ofrece\n            un camino que no existe. */}\n        {telefono ? (\n          <Pressable\n            onPress={() => { void whatsappATienda(telefono, `Hola ${nombre}, te escribo desde EG Route Plan.`); }}\n            hitSlop={10}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Escribir a la tienda por WhatsApp\"\n          >\n            <Text style={[s.whatsapp, { color: brand.whatsapp }]}>WhatsApp</Text>\n          </Pressable>\n        ) : (\n          <View style={s.hueco} />\n        )}\n      </View>\n\n      {!isAuthenticated ? (\n        <View style={s.cuerpo}>\n          <EmptyState\n            emoji=\"💬\"\n            titulo=\"Entra para ver la conversación\"\n            texto=\"Los mensajes con la tienda van con tu cuenta: sin sesión no hay nada que enseñar.\"\n            accionLabel=\"Iniciar sesión\"\n            accionPrimaria\n            onAccion={() => router.push('/auth' as never)}\n          />\n        </View>\n      ) : !conv ? (\n        <View style={s.cuerpo}>\n          <EmptyState\n            emoji=\"🔗\"\n            titulo=\"Falta la conversación\"\n            texto=\"Esta pantalla se abre desde Mensajes o desde la ficha de un anuncio. Vuelve y entra por ahí.\"\n            accionLabel=\"Volver\"\n            onAccion={() => router.back()}\n          />\n        </View>\n      ) : error ? (\n        <View style={s.cuerpo}>\n          <InlineError mensaje={error} onReintentar={() => void cargar()} />\n        </View>\n      ) : (\n        <FlatList\n          ref={listaRef}\n          data={mensajes}\n          keyExtractor={(m) => m.id}\n          contentContainerStyle={[s.lista, { paddingBottom: espaciado.e16 }]}\n          onContentSizeChange={() => listaRef.current?.scrollToEnd({ animated: false })}\n          ListEmptyComponent={\n            cargando ? (\n              <View style={s.cargando}><ActivityIndicator color={colors.primary} /></View>\n            ) : (\n              <EmptyState\n                emoji=\"👋\"\n                titulo=\"Todavía no hay mensajes\"\n                texto=\"Escribe abajo para preguntarle a la tienda. Si entraste desde un anuncio, el primer mensaje puede ir con la referencia.\"\n              />\n            )\n          }\n          renderItem={({ item }) => (\n            <View style={[s.burbujaFila, item.mine ? s.burbujaMia : s.burbujaSuya]}>\n              <View\n                style={[\n                  s.burbuja,\n                  item.mine\n                    ? { backgroundColor: colors.primary, borderColor: colors.primary }\n                    : { backgroundColor: colors.card, borderColor: colors.border },\n                ]}\n              >\n                <Text style={[s.burbujaTexto, { color: item.mine ? brand.white : colors.textPrimary }]}>\n                  {item.body}\n                </Text>\n                <Text\n                  style={[\n                    s.burbujaHora,\n                    { color: item.mine ? alpha(brand.white, 0.75) : colors.textSecondary },\n                  ]}\n                >\n                  {item.createdAt ? getTimeAgo(item.createdAt) : ''}\n                </Text>\n              </View>\n            </View>\n          )}\n        />\n      )}\n\n      {isAuthenticated && conv && !error && (\n        <View style={[s.barra, { borderTopColor: colors.border, backgroundColor: colors.card, paddingBottom: insets.bottom + espaciado.e8 }]}>\n          <TextInput\n            value={borrador}\n            onChangeText={setBorrador}\n            placeholder=\"Escribe a la tienda…\"\n            placeholderTextColor={colors.textSecondary}\n            multiline\n            maxLength={1000}\n            accessibilityLabel=\"Mensaje para la tienda\"\n            style={[s.entrada, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n          />\n          <Pressable\n            onPress={() => void enviar()}\n            disabled={!borrador.trim() || enviando}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Enviar mensaje\"\n            style={({ pressed }) => [\n              s.enviar,\n              { backgroundColor: borrador.trim() ? colors.primary : colors.border },\n              { opacity: !borrador.trim() || enviando ? 0.6 : pressed ? 0.85 : 1 },\n            ]}\n          >\n            {enviando ? (\n              <ActivityIndicator size=\"small\" color={brand.white} />\n            ) : (\n              <Send size={icono.sm} color={brand.white} />\n            )}\n          </Pressable>\n        </View>\n      )}\n    </View>\n  );\n}\n\nconst s = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e8,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTienda: { flex: 1, flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 },\n  avatar: { width: 34, height: 34, borderRadius: radios.md, borderWidth: trazo.fino },\n  avatarLetra: { alignItems: 'center', justifyContent: 'center' },\n  inicial: { fontSize: tipografia.body, fontWeight: peso.titulo },\n  cabeceraTexto: { flex: 1 },\n  cabeceraFila: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 },\n  cabeceraTitulo: { fontSize: tipografia.body, fontWeight: peso.titulo, flexShrink: 1 },\n  cabeceraNota: { fontSize: tipografia.micro },\n  whatsapp: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  hueco: { width: icono.sm },\n  cuerpo: { paddingTop: espaciado.e24 },\n  cargando: { alignItems: 'center', paddingTop: espaciado.e24 },\n  lista: { paddingHorizontal: espaciado.e16, paddingTop: espaciado.e16, gap: espaciado.e8 },\n  burbujaFila: { flexDirection: 'row' },\n  burbujaMia: { justifyContent: 'flex-end' },\n  burbujaSuya: { justifyContent: 'flex-start' },\n  burbuja: {\n    maxWidth: '82%',\n    borderRadius: radios.lg,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e8,\n  },\n  burbujaTexto: { fontSize: tipografia.body },\n  burbujaHora: { fontSize: tipografia.micro, marginTop: espaciado.e4, textAlign: 'right' },\n  barra: {\n    flexDirection: 'row',\n    alignItems: 'flex-end',\n    gap: espaciado.e8,\n    paddingHorizontal: espaciado.e16,\n    paddingTop: espaciado.e8,\n    borderTopWidth: trazo.fino,\n  },\n  entrada: {\n    flex: 1,\n    minHeight: 40,\n    maxHeight: 120,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e8,\n    fontSize: tipografia.body,\n  },\n  enviar: {\n    width: 40,\n    height: 40,\n    borderRadius: radios.md,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n});\n","/**\n * lifebook — cliente API del módulo LIFE BOOK (Partes 1-3 backend).\n * Rutas: /lifebook/... sobre el base de httpClient (/wallet/api/v1).\n * Endpoints: posts (nota/venta/servicio/debate), feed por canal, perfil\n * público (users/:id/profile + posts), like/comment/bookmark/follow/report.\n */\n\nimport { http, httpRequest } from './httpClient';\nimport { absUrl } from './config';\nimport { lbCategoryLabel } from '../constants/lifebook';\nimport type { LbVisibility } from '../constants/lifebook';\n\n// ---------------- Tipos (espejo del serializador NestJS) ----------------\n\nexport interface LbAuthor {\n  id: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  role?: string | null;\n  nameColor?: string | null;\n  /** Parte 11: alias corto de `fullName` que ya envía el servidor. */\n  name?: string | null;\n  /** Parte 11: ¿el visor sigue a este autor? (lo calcula el servidor). */\n  followedByMe?: boolean;\n}\n\nexport interface LbMediaItem {\n  id: string;\n  url: string;\n}\n\n/** Enlace a un servicio real (verificado por rol del autor). */\nexport interface LbServiceLink {\n  /**\n   * Tipos reales que envía el servidor: `taxi | food | ecomerse | work |\n   * rental | paquete | tickets | lifebook`. Se aceptan además los alias\n   * `shop` (= ecomerse) y `delivery` (= paquete) por si llegan de otro cliente.\n   */\n  type: 'taxi' | 'food' | 'shop' | 'delivery' | 'work' | 'rental'\n  | 'ecomerse' | 'paquete' | 'tickets' | 'lifebook' | (string & {});\n  /** Puede ser `null`: un enlace `taxi` apunta al servicio, no a un registro. */\n  id: string | null;\n  /** Ruta de la app ya resuelta por el servidor (p. ej. `/taxi`). */\n  route?: string | null;\n}\n\nexport interface LbStats {\n  likes: number;\n  comments: number;\n  bookmarks?: number;\n  likedByMe?: boolean;\n  bookmarkedByMe?: boolean;\n}\n\nexport interface LbPostBase {\n  id: string;\n  type: 'note' | 'sale' | 'service' | 'debate' | string;\n  title: string | null;\n  body: string | null;\n  city: string;\n  barrio: string | null;\n  tone: string | null;\n  topics?: string[];\n  payload: Record<string, unknown>;\n  serviceLink: LbServiceLink | null;\n  media: LbMediaItem[];\n  /** Nº total de fotos del post (la tarjeta solo trae la 1ª). */\n  mediaCount?: number;\n  /** Parte 11: alias de `topics` tal y como lo envía el servidor. */\n  tags?: string[];\n  /** Parte 11: alias plano de `stats.bookmarkedByMe`. */\n  savedByMe?: boolean;\n  /** Nº de guardados de la publicación (Parte 13: lo envía el feed y el detalle). */\n  savedCount?: number;\n  /** Canal del feed por el que salió la publicación (Parte 13; `null` en for_you). */\n  channel?: string | null;\n  createdAt: string | null;\n  author: LbAuthor;\n  stats: LbStats;\n}\n\nexport interface LbDebateInfo {\n  category: string;\n  state: string;\n  allowProposals: boolean;\n  allowVotes: boolean;\n  showApproxLoc: boolean;\n  problem: string | null;\n  /** Parte 14: alias del enunciado (mismo valor que `problem`). */\n  question?: string | null;\n  context: string | null;\n  initialProposal: string | null;\n  resolvedSummary: string | null;\n  resolvedAt: string | null;\n  attentionAt: string | null;\n  closedAt: string | null;\n  /**\n   * Parte 14: **agregado** de los votos de las propuestas\n   * (`agree` → sí · `disagree` → no). No es una votación sí/no del debate:\n   * el voto real vive en cada propuesta.\n   */\n  votesYes?: number;\n  votesNo?: number;\n  myVote?: 'yes' | 'no' | null;\n}\n\nexport interface LbPostDetail extends LbPostBase {\n  visibility: LbVisibility;\n  allowComments: boolean;\n  debate?: LbDebateInfo | null;\n  /** Meta de SERIE (solo type='serie', Parte 4). */\n  serie?: { episodesCount: number; seasons: number; totalSeconds: number } | null;\n  bookmarks?: number;\n}\n\n/** Comentario de una publicación (Parte 14: con `postId`, `likes` y `likedByMe`). */\nexport interface LbComment {\n  id: string;\n  /** Publicación a la que pertenece. */\n  postId?: string;\n  body: string;\n  createdAt: string | null;\n  /** Nº de «me gusta» del comentario. */\n  likes?: number;\n  likedByMe?: boolean;\n  author: { id: string; fullName: string | null; avatarUrl: string | null; role?: string | null };\n  /* ── Parte 23: respuestas y edición ── */\n  /** Si es una respuesta, el comentario al que contesta. */\n  parentId?: string | null;\n  /** Cuántas respuestas tiene (para «Ver N respuestas»). */\n  repliesCount?: number;\n  /** Fecha de la última edición (para poner «editado»). */\n  editedAt?: string | null;\n  /** Nombre de la persona a la que responde (en respuestas). */\n  replyToName?: string | null;\n}\n\n/** Alias antiguo (compatibilidad): el mismo tipo. */\nexport type LbCommentItem = LbComment;\n\nexport interface LbFeedPage {\n  posts: LbPostBase[];\n  nextCursor: string | null;\n}\n\n// ---------------- Modelo de TARJETA (estilo Xiaohongshu) ----------------\n/**\n * LbPostCard — forma que consumen la tarjeta (`components/lifebook/PostCard`)\n * y el masonry del feed. NO es lo que devuelve el backend: se deriva de\n * `LbPostBase` con `toPostCard()`, de modo que la tarjeta trabaja con una\n * sola portada (`media`) y campos planos de social.\n */\nexport interface LbPostCardMedia {\n  /** URL absoluta ya resuelta (absUrl). */\n  url: string;\n  /** Miniatura: el backend aún no genera miniaturas → undefined. */\n  thumbnailUrl?: string;\n  /** ancho/alto — clave del masonry (3:4 por defecto). */\n  aspectRatio?: number;\n}\n\nexport interface LbPostCardAuthor {\n  id: string;\n  name: string;\n  avatarUrl?: string;\n}\n\nexport interface LbPostCard {\n  id: string;\n  /** Título ya resuelto (título real o, si no hay, el cuerpo). Nunca vacío. */\n  title: string;\n  /** Cuerpo de la nota (la tarjeta lo usa cuando la publicación no tiene foto). */\n  body?: string;\n  type: 'note' | 'video' | 'podcast' | 'serie' | 'sale' | 'debate' | 'service' | string;\n  media?: LbPostCardMedia;\n  author?: LbPostCardAuthor;\n  likesCount: number;\n  likedByMe?: boolean;\n  commentsCount?: number;\n  /** Nº de guardados (detalle: stats.bookmarks · feed: savedCount del servidor). */\n  savedCount?: number;\n  savedByMe?: boolean;\n  city?: string;\n  createdAt?: string;\n  /* extras que la tarjeta ya pinta */\n  mediaCount?: number;\n  priceXaf?: number;\n  /* ── PostCard v2: acercar la tarjeta a Xiaohongshu + EG Route Plan ── */\n  /** Chip superior: canal de origen ('Comida', 'Taxi', 'Ventas'…) o categoría/tipo. */\n  category?: string;\n  /** Contexto local: 'Malabo · Malabo Centro'. */\n  locationLabel?: string;\n  /** Primer tema/hashtag de la publicación. */\n  topicLabel?: string;\n  serviceLink?: LbServiceLink | null;\n  durationSec?: number;\n  hasVideo?: boolean;\n  hasAudio?: boolean;\n}\n\n/** Proporción por defecto cuando el post no trae `coverRatio`: 3:4. */\nexport const LB_CARD_DEFAULT_RATIO = 0.75;\n\n/** Acota la proporción para que una foto extrema no rompa la rejilla. */\nexport function lbCardRatio(raw: unknown): number {\n  const n = Number(raw ?? 0);\n  return n > 0 ? Math.min(Math.max(n, 0.6), 1.6) : LB_CARD_DEFAULT_RATIO;\n}\n\n/* Helpers de normalización del adaptador (string/número «limpios»). */\nfunction str(v: unknown): string | undefined {\n  if (typeof v !== 'string') return undefined;\n  const s = v.trim();\n  return s.length > 0 ? s : undefined;\n}\nfunction num(v: unknown): number | undefined {\n  const n = Number(v);\n  return Number.isFinite(n) ? n : undefined;\n}\n\n/** Adapta la respuesta real del backend a la forma de la tarjeta (PostCard v2). */\nexport function toPostCard(post: LbPostBase): LbPostCard {\n  const payload = (post.payload ?? {}) as Record<string, unknown>;\n\n  const coverUrl = str(payload.coverUrl) ? absUrl(payload.coverUrl as string) : '';\n  const firstUrl = post.media?.[0]?.url ? absUrl(post.media[0].url) : '';\n  const url = coverUrl || firstUrl;\n\n  const priceXaf = num(payload.priceXaf);\n  const body = post.body?.trim() ?? '';\n  const realTitle = post.title?.trim() ?? '';\n\n  const city = post.city?.trim();\n  const barrio = post.barrio?.trim();\n  const locationLabel = [city, barrio].filter(Boolean).join(' · ') || undefined;\n\n  const serviceLink = post.serviceLink ?? null;\n  // `category`: canal del feed (lo marca el servidor) → categoría de la venta →\n  // etiqueta del enlace de servicio → tipo de publicación. Se traduce a etiqueta\n  // legible ('food' → 'Comida') para el chip superior.\n  const category = lbCategoryLabel(\n    str(post.channel)\n    ?? str(payload.category)\n    ?? serviceLink?.type\n    ?? (post.type !== 'note' ? post.type : undefined),\n  );\n\n  const savedByMe = post.savedByMe ?? post.stats?.bookmarkedByMe ?? false;\n  // En el detalle llega `stats.bookmarks`; en el feed el servidor manda `savedCount`.\n  const savedCount = num(post.savedCount) ?? num(post.stats?.bookmarks) ?? 0;\n  const durationSec = num(payload.durationSec);\n\n  const hasVideo =\n    Boolean(str(payload.videoUrl)) || post.type === 'video' || post.type === 'serie';\n  const hasAudio = Boolean(str(payload.audioUrl)) || post.type === 'podcast';\n\n  const topicLabel = str(post.topics?.[0]) ?? str(post.tags?.[0]);\n\n  return {\n    id: post.id,\n    title: realTitle || body,\n    body: body || undefined,\n    type: post.type,\n    media: url\n      // El backend NO genera miniaturas: `thumbnailUrl` reutiliza la URL original\n      // (la tarjeta ya cae a `url` cuando no hay miniatura).\n      ? { url, thumbnailUrl: url, aspectRatio: lbCardRatio(payload.coverRatio) }\n      : undefined,\n    author: post.author\n      ? {\n        id: post.author.id,\n        name: post.author.name?.trim() || post.author.fullName?.trim() || 'Usuario',\n        avatarUrl: post.author.avatarUrl ? absUrl(post.author.avatarUrl) : undefined,\n      }\n      : undefined,\n    likesCount: post.stats?.likes ?? 0,\n    likedByMe: !!post.stats?.likedByMe,\n    commentsCount: post.stats?.comments ?? 0,\n    savedCount,\n    savedByMe,\n    city: city || undefined,\n    createdAt: post.createdAt ?? undefined,\n    mediaCount: post.mediaCount ?? post.media?.length ?? 0,\n    priceXaf:\n      (post.type === 'sale' || post.type === 'service') && priceXaf !== undefined\n        ? priceXaf\n        : undefined,\n    category,\n    locationLabel,\n    topicLabel,\n    serviceLink,\n    durationSec,\n    hasVideo,\n    hasAudio,\n  };\n}\n\nexport interface LbProfile {\n  id: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  coverPhotoUrl: string | null;\n  bio: string | null;\n  nameColor: string | null;\n  city: string | null;\n  country: string | null;\n  profession: string | null;\n  school: string | null;\n  links: Array<{ label?: string; url?: string } | string>;\n  ratingAvg: number | null;\n  role: string | null;\n  createdAt: string | null;\n  stats: { posts: number; followers: number; following: number; likes: number };\n  verified: { driver: boolean; food: boolean; seller: boolean; work: boolean; rental: boolean };\n  relation: { isSelf: boolean; isFollowing: boolean; isFollower: boolean };\n}\n\nexport interface LbProfilePosts extends LbFeedPage {}\n\nexport interface LbCreateNoteInput {\n  body: string;\n  title?: string;\n  media?: string[]; // dataURLs\n  city: string;\n  barrio?: string;\n  topics?: string[];\n  tone?: string;\n  visibility?: LbVisibility;\n  /** Proporción (ancho/alto) de la 1ª foto para la cascada 3:4. */\n  coverRatio?: number;\n}\n\n// ---------------- Búsqueda (Parte 9) ----------------\n\nexport interface LbSearchPage extends LbFeedPage {\n  /** Término normalizado que aplicó el servidor (minúsculas, sin acentos). */\n  query: string;\n}\n\nexport interface LbTrend {\n  tag: string;\n  count: number;\n  /** 5 o más publicaciones en la ventana de 30 días. */\n  hot?: boolean;\n  /** `topic` = tema declarado por el autor · `word` = palabra frecuente (relleno). */\n  source?: 'topic' | 'word';\n}\n\nexport interface LbTrendsPage {\n  city: string | null;\n  window: string;\n  trends: LbTrend[];\n  generatedAt?: string;\n}\n\nexport interface LbSuggestion {\n  text: string;\n  type: 'tag' | 'user' | 'general' | string;\n}\n\nconst qs = (q: Record<string, string | undefined>) => {\n  const sp = new URLSearchParams();\n  Object.entries(q).forEach(([k, v]) => { if (v !== undefined && v !== '') sp.set(k, v); });\n  const s = sp.toString();\n  return s ? `?${s}` : '';\n};\n\n/** `curl`-friendly helpers de cada verbo. DELETE no existe en `http`, se usa httpRequest. */\nexport const lifebookApi = {\n  /** Feed por canal (Parte 3). channel=for_you|following|nearby|today|debates|food|taxi|work|rental|sales|culture|music|sports */\n  feed: (channel: string, o: { city?: string; type?: string; cursor?: string; limit?: number } = {}) =>\n    http.get<LbFeedPage>(`/lifebook/posts/feed${qs({\n      channel, city: o.city, type: o.type, cursor: o.cursor,\n      limit: o.limit ? String(o.limit) : undefined,\n    })}`),\n\n  /** Feed \"Para ti\" (alias servidor). */\n  forYou: (o: { cursor?: string; limit?: number } = {}) =>\n    http.get<LbFeedPage>(`/lifebook/posts/for-you${qs({ cursor: o.cursor, limit: o.limit ? String(o.limit) : undefined })}`),\n\n  /** Búsqueda de publicaciones (Parte 9): texto + filtro de tipo/canal + ciudad. */\n  search: (q: string, o: { type?: string; city?: string; cursor?: string; limit?: number } = {}) =>\n    http.get<LbSearchPage>(`/lifebook/search${qs({\n      q, city: o.city, cursor: o.cursor,\n      type: o.type && o.type !== 'all' ? o.type : undefined,\n      limit: o.limit ? String(o.limit) : undefined,\n    })}`),\n\n  /** Tendencias reales de los últimos 30 días (temas + palabras frecuentes). */\n  searchTrends: (o: { city?: string; limit?: number } = {}) =>\n    http.get<LbTrendsPage>(`/lifebook/search/trends${qs({ city: o.city, limit: o.limit ? String(o.limit) : undefined })}`),\n\n  /** Sugerencias en vivo (temas y personas) para el término escrito. */\n  searchSuggest: (q: string, limit = 8) =>\n    http.get<{ suggestions: LbSuggestion[] }>(`/lifebook/search/suggest${qs({ q, limit: String(limit) })}`),\n\n  post: (id: string) => http.get<LbPostDetail>(`/lifebook/posts/${id}`),\n\n  /** Igual que `post()` pero con la forma `{ post }` del contrato del cliente. */\n  postDetail: async (id: string) => ({ post: await http.get<LbPostDetail>(`/lifebook/posts/${id}`) }),\n\n  /**\n   * Comentarios del post: `GET /posts/:id/comments?limit=&cursor=`.\n   * Con `limit`/`cursor` el servidor devuelve `{ comments, nextCursor, total }`\n   * (paginación real por `created_at`); sin parámetros devuelve el array.\n   */\n  postComments: (id: string, opts: { cursor?: string; limit?: number } = {}) =>\n    http.get<{ comments: LbCommentItem[]; nextCursor: string | null; total?: number }>(\n      `/lifebook/posts/${id}/comments${qs({\n        cursor: opts.cursor,\n        limit: opts.limit !== undefined ? String(opts.limit) : '20',\n      })}`,\n    ),\n\n  /** Parte 16: mis guardados (publicaciones que yo marqué). */\n  mySaves: (o: { cursor?: string; limit?: number } = {}) =>\n    http.get<LbFeedPage>(`/lifebook/me/saves${qs({ cursor: o.cursor, limit: o.limit ? String(o.limit) : undefined })}`),\n\n  /* ── Parte 23: respuestas de un comentario · editar · borrar ── */\n\n  /** Respuestas de un comentario (traen `replyToName`: a quién contestan). */\n  commentReplies: (commentId: string, limit = 50) =>\n    http.get<{ parentId: string; replyTo: { id: string; fullName: string | null } | null; total: number; replies: LbCommentItem[] }>(\n      `/lifebook/comments/${commentId}/replies?limit=${limit}`,\n    ),\n\n  /** Edita MI comentario (devuelve el comentario actualizado y `editedAt`). */\n  editComment: (commentId: string, text: string) =>\n    httpRequest<{ ok: boolean; id: string; body: string; editedAt: string | null }>(\n      `/lifebook/comments/${commentId}`, { method: 'PATCH', body: { text } }),\n\n  /** Borra un comentario (el mío, o cualquiera si soy el autor de la publicación). */\n  deleteComment: (commentId: string) =>\n    httpRequest<{ ok: boolean; commentsLeft: number }>(`/lifebook/comments/${commentId}`, { method: 'DELETE' }),\n\n  /** Relacionadas del detalle (Parte 10): mismo tema, tipo o ciudad. */\n  relatedPosts: (id: string, limit = 6) =>\n    http.get<LbFeedPage>(`/lifebook/posts/${id}/related?limit=${limit}`),\n\n  like: (id: string) => http.post<{ liked: boolean; reaction: string }>(`/lifebook/posts/${id}/like`, {}),\n  unlike: (id: string) => httpRequest<{ liked: boolean }>(`/lifebook/posts/${id}/like`, { method: 'DELETE' }),\n  toggleLike: async (id: string, liked: boolean) => (liked ? lifebookApi.unlike(id) : lifebookApi.like(id)),\n\n  comment: (id: string, body: string) => http.post<{ id: string; ok: boolean }>(`/lifebook/posts/${id}/comment`, { body }),\n  comments: (id: string) => http.get<LbCommentItem[]>(`/lifebook/posts/${id}/comments`),\n\n  /* ── Parte 14: «me gusta» en comentarios ── */\n\n  likeComment: (commentId: string) =>\n    http.post<{ liked: boolean }>(`/lifebook/comments/${commentId}/like`, {}),\n  unlikeComment: (commentId: string) =>\n    httpRequest<{ liked: boolean }>(`/lifebook/comments/${commentId}/like`, { method: 'DELETE' }),\n  toggleCommentLike: (commentId: string, liked: boolean) =>\n    (liked ? lifebookApi.unlikeComment(commentId) : lifebookApi.likeComment(commentId)),\n\n  bookmark: (id: string) => http.post<{ bookmarked: boolean }>(`/lifebook/posts/${id}/bookmark`, {}),\n  unbookmark: (id: string) => httpRequest<{ bookmarked: boolean }>(`/lifebook/posts/${id}/bookmark`, { method: 'DELETE' }),\n  toggleBookmark: async (id: string, bookmarked: boolean) => (bookmarked ? lifebookApi.unbookmark(id) : lifebookApi.bookmark(id)),\n\n  follow: (userId: string) => http.post<{ following: boolean }>(`/lifebook/users/${userId}/follow`, {}),\n  unfollow: (userId: string) => httpRequest<{ following: boolean }>(`/lifebook/users/${userId}/follow`, { method: 'DELETE' }),\n\n  /** Perfil público (Parte 3): identidad + contadores + badges + relación. */\n  profile: (userId: string) => http.get<LbProfile>(`/lifebook/users/${userId}/profile`),\n\n  /** Publicaciones de un perfil (pestañas: type=note|sale|service|debate). */\n  userPosts: (userId: string, o: { type?: string; cursor?: string; limit?: number } = {}) =>\n    http.get<LbProfilePosts>(`/lifebook/users/${userId}/posts${qs({\n      type: o.type, cursor: o.cursor, limit: o.limit ? String(o.limit) : undefined,\n    })}`),\n\n  /** Publicar NOTA (texto + hasta 4 fotos + temas + tono + visibilidad). */\n  createNote: (input: LbCreateNoteInput) =>\n    http.post<LbPostDetail>('/lifebook/posts', {\n      body: input.body,\n      ...(input.title?.trim() ? { title: input.title.trim() } : {}),\n      ...(input.media?.length ? { media: input.media } : {}),\n      city: input.city,\n      ...(input.barrio?.trim() ? { barrio: input.barrio.trim() } : {}),\n      ...(input.topics?.length ? { topics: input.topics } : {}),\n      ...(input.coverRatio ? { coverRatio: input.coverRatio } : {}),\n      ...(input.tone ? { tone: input.tone } : {}),\n      visibility: input.visibility ?? 'public',\n    }),\n};\n\nexport type { LbVisibility };\n\n// ---------------- Parte 4: video · podcast · serie ----------------\n\nexport interface LbEpisode {\n  id: string;\n  season: number;\n  episode: number;\n  label: string;\n  title: string | null;\n  body: string | null;\n  videoUrl: string;\n  coverUrl: string | null;\n  durationSec: number | null;\n  allowDownload: boolean;\n  createdAt: string | null;\n}\n\nexport interface LbMediaUploadResult {\n  url: string;\n  kind: 'image' | 'video' | 'audio';\n  bytes: number;\n  contentType: string;\n}\n\nexport interface LbRichMediaInput {\n  title?: string;\n  body?: string;\n  city: string;\n  barrio?: string;\n  allowComments?: boolean;\n  allowDownload?: boolean;\n  visibility?: LbVisibility;\n}\n\nexport interface LbVideoInput extends LbRichMediaInput {\n  title: string;\n  videoUrl: string;\n  coverUrl?: string;\n  durationSec: number;\n}\n\nexport interface LbPodcastInput extends LbRichMediaInput {\n  audioUrl: string;\n  coverUrl: string;\n  durationSec: number;\n}\n\nexport interface LbSerieInput extends LbRichMediaInput {\n  title: string;\n  coverUrl?: string;\n}\n\nexport interface LbEpisodeInput {\n  title?: string;\n  body?: string;\n  videoUrl: string;\n  coverUrl?: string;\n  durationSec: number;\n  season?: number;\n  episode?: number;\n  allowDownload?: boolean;\n}\n\nexport const lifebookMediaApi = {\n  /** Sube un archivo local (uri RN) por multipart → URL pública en MinIO.\n   *  Parte 15: `kind='file'` acepta documentos (pdf, docx, zip…) hasta 25 MB. */\n  async uploadFile(kind: 'image' | 'video' | 'audio' | 'file', file: { uri: string; name: string; mimeType: string }): Promise<LbMediaUploadResult> {\n    const form = new FormData();\n    form.append('file', { uri: file.uri, name: file.name, type: file.mimeType } as unknown as Blob);\n    return httpRequest<LbMediaUploadResult>(`/lifebook/media/upload?kind=${kind}`, { method: 'POST', form });\n  },\n\n  createVideo: (input: LbVideoInput) =>\n    http.post<LbPostDetail>('/lifebook/posts/video', input),\n\n  createPodcast: (input: LbPodcastInput) =>\n    http.post<LbPostDetail>('/lifebook/posts/podcast', input),\n\n  createSerie: (input: LbSerieInput) =>\n    http.post<LbPostDetail>('/lifebook/posts/serie', input),\n\n  serieEpisodes: (serieId: string) =>\n    http.get<LbEpisode[]>(`/lifebook/series/${serieId}/episodes`),\n\n  addEpisode: (serieId: string, input: LbEpisodeInput) =>\n    http.post<{ id: string; season: number; episode: number; label: string; ok: boolean }>(`/lifebook/series/${serieId}/episodes`, input),\n};\n\n// ---------------- Parte 5: chat · pedidos · tienda ----------------\n\nexport interface LbConversation {\n  id: string;\n  other: { id: string; fullName: string | null; avatarUrl: string | null };\n  lastMessage: string | null;\n  lastMessageAt: string | null;\n  unread: number;\n  createdAt: string | null;\n}\n\nexport interface LbMessage {\n  id: string;\n  senderId: string;\n  mine: boolean;\n  body: string;\n  readAt: string | null;\n  createdAt: string | null;\n  sender: { id: string; fullName: string | null; avatarUrl: string | null };\n}\n\nexport interface LbMessagePage {\n  messages: LbMessage[];\n  nextCursor: string | null;\n}\n\nexport type LbOrderStatus = 'requested' | 'accepted' | 'declined' | 'in_transit' | 'delivered' | 'cancelled' | 'disputed';\n\nexport interface LbOrder {\n  id: string;\n  orderNo: string;\n  postId: string;\n  title: string | null;\n  priceXaf: number;\n  negotiable: boolean;\n  message: string | null;\n  contactMode: string;\n  status: LbOrderStatus;\n  createdAt: string | null;\n  buyer: { id: string; fullName: string | null; avatarUrl: string | null };\n  seller: { id: string; fullName: string | null; avatarUrl: string | null };\n  media: LbMediaItem[];\n}\n\nexport interface LbStorePage {\n  store: {\n    id: string;\n    fullName: string | null;\n    avatarUrl: string | null;\n    coverPhotoUrl: string | null;\n    bio: string | null;\n    city: string | null;\n    country: string | null;\n    ratingAvg: number | null;\n    relation: { isSelf: boolean; isFollowing: boolean; isFollower: boolean };\n    verified: LbProfile['verified'];\n    stats: LbProfile['stats'];\n    ecomerse: boolean;\n  };\n  sales: LbPostBase[];\n  nextCursor: string | null;\n}\n\nexport const lifebookChatApi = {\n  conversations: () => http.get<LbConversation[]>('/lifebook/chat/conversations'),\n  unread: () => http.get<{ unread: number }>('/lifebook/chat/unread'),\n  open: (userId: string) => http.post<LbConversation>('/lifebook/chat/open', { userId }),\n  messages: (convId: string, o: { before?: string; limit?: number } = {}) =>\n    http.get<LbMessagePage>(`/lifebook/chat/conversations/${convId}/messages${qs({ before: o.before, limit: o.limit ? String(o.limit) : undefined })}`),\n  send: (convId: string, body: string) => http.post<{ id: string; ok: boolean }>(`/lifebook/chat/conversations/${convId}/messages`, { body }),\n\n  /**\n   * Parte 15: envío con tipo (texto, nota/venta compartida, imagen, archivo).\n   * Parte 24 (G2): además `location` (lat/lng/label) y `vote` (question + options).\n   * Parte 25 (G2-b): `chain` (title/note/slots) y `checkin` (label/lat/lng/at).\n   * Parte 26 (G2-c): `ad` (anuncio de grupo con `priceXaf` y enlace opcional).\n   */\n  sendRich: (convId: string, input: {\n    text?: string; kind?: string; postId?: string; mediaUrl?: string; fileName?: string; fileSize?: number;\n    lat?: number; lng?: number; label?: string; question?: string; options?: string[];\n    title?: string; note?: string; slots?: number; at?: string;\n    priceXaf?: number; linkType?: string; linkId?: string;\n  }) =>\n    http.post<{\n      id: string; conversationId: string; kind: string; body: string; createdAt: string; ok: boolean;\n      /** Solo en `kind='ad'`: anuncios que me quedan hoy. */\n      adsLeftToday?: number; adsLimitToday?: number;\n    }>(\n      `/lifebook/chat/conversations/${convId}/messages`,\n      {\n        body: input.text,\n        kind: input.kind,\n        postId: input.postId,\n        mediaUrl: input.mediaUrl,\n        fileName: input.fileName,\n        fileSize: input.fileSize,\n        lat: input.lat,\n        lng: input.lng,\n        label: input.label,\n        question: input.question,\n        options: input.options,\n        title: input.title,\n        note: input.note,\n        slots: input.slots,\n        at: input.at,\n        priceXaf: input.priceXaf,\n        linkType: input.linkType,\n        linkId: input.linkId,\n      },\n    ),\n\n  /** Parte 26 (G2-c): anuncios de grupo que me quedan hoy (límite 15/día). */\n  adsLeft: () => http.get<{ limit: number; used: number; left: number }>('/lifebook/me/ads-left'),\n\n  /**\n   * Parte 30 (Fase 05): BÚSQUEDA GLOBAL DE MENSAJES en todos mis chats, con\n   * filtro por tipo (`kind`) y por chat (`conversationId`), paginando por fecha.\n   */\n  searchAllMessages: (o: { q?: string; kind?: string; conversationId?: string; before?: string; limit?: number } = {}) =>\n    http.get<{\n      query: string | null; kind: string | null; total: number; nextCursor: string | null;\n      messages: {\n        id: string; conversationId: string; mine: boolean; kind: string; body: string; createdAt: string;\n        readAt?: string | null;\n        sender?: { id: string; fullName: string | null; avatarUrl: string | null };\n        postRef?: { id: string; title: string; priceXaf?: number; coverUrl?: string };\n        imageUrl?: string;\n        fileRef?: { name: string; sizeLabel: string; ext?: string; url?: string };\n        locationRef?: { label: string; lat?: number | null; lng?: number | null };\n        voteRef?: { question: string; options: string[]; counts?: number[]; myVote?: number | null; total?: number };\n        chainRef?: { title: string; note?: string | null; slots?: number | null; joined: number; joinedByMe?: boolean };\n        checkinRef?: { at: string | null; when: string; going: number; goingByMe: boolean };\n        adRef?: { title: string | null; text: string; priceXaf: number | null; imageUrl: string | null; link: unknown };\n        conversation: { id: string; kind: 'direct' | 'group'; title: string; photoUrl: string | null };\n      }[];\n    }>(`/lifebook/me/messages/search${qs({\n      q: o.q, kind: o.kind, conversationId: o.conversationId, before: o.before,\n      limit: o.limit ? String(o.limit) : undefined,\n    })}`),\n\n  /**\n   * Parte 24 (G2): vota en un mensaje de votación. Un voto por persona y\n   * mensaje: volver a votar CAMBIA el voto y devuelve los recuentos nuevos.\n   */\n  vote: (messageId: string, optionIdx: number) =>\n    http.post<{ ok: boolean; messageId: string; optionIdx: number; options: string[]; counts: number[]; myVote: number; total: number }>(\n      `/lifebook/chat/messages/${messageId}/vote`, { optionIdx }),\n\n  /**\n   * Parte 25 (G2-b): me apunto (o me doy de baja con `joined: false`) en una\n   * CADENA o una QUEDADA. Devuelve el recuento y quiénes están apuntados.\n   */\n  join: (messageId: string, joined = true) =>\n    http.post<{\n      ok: boolean; messageId: string; kind: string; joined: boolean; count: number;\n      slots: number | null; members: { id: string; name: string; avatarUrl: string | null }[];\n    }>(`/lifebook/chat/messages/${messageId}/join`, { joined }),\n\n  markRead: (convId: string) => http.post<{ ok: boolean }>(`/lifebook/chat/conversations/${convId}/read`, {}),\n};\n\nexport const lifebookOrdersApi = {\n  create: (postId: string, body: { message?: string; priceXaf?: number } = {}) =>\n    http.post<{ id: string; orderNo: string; status: string; priceXaf: number; negotiable: boolean }>(`/lifebook/posts/${postId}/order`, body),\n  mine: (side: 'buyer' | 'seller') => http.get<LbOrder[]>(`/lifebook/orders?side=${side}`),\n  detail: (orderId: string) => http.get<LbOrder>(`/lifebook/orders/${orderId}`),\n  action: (orderId: string, action: string) => http.post<{ ok: boolean; status: string }>(`/lifebook/orders/${orderId}/action`, { action }),\n};\n\nexport const lifebookStoreApi = {\n  page: (sellerId: string) => http.get<LbStorePage>(`/lifebook/stores/${sellerId}`),\n};\n\n// ---------------- Parte 6: ajustes · bloqueos · reportar · comentarios ----------------\n\nexport interface LbSettings {\n  publish: { defaultVisibility: 'public' | 'followers' | 'private' };\n  privacy: {\n    posts: 'public' | 'followers' | 'private';\n    messages: 'public' | 'followers' | 'private' | 'nobody';\n    location: 'public' | 'followers' | 'nobody';\n    comments: 'public' | 'followers' | 'private';\n    email: 'public' | 'followers' | 'nobody';\n  };\n  notifications: {\n    likes: boolean; comments: boolean; follows: boolean; messages: boolean;\n    orders: boolean; debates: boolean; promotions: boolean; digest: boolean;\n  };\n  content: { sensitiveFilter: boolean; cities: string[] };\n}\n\nexport interface LbBlockedUser {\n  id: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  blockedAt: string | null;\n}\n\nexport const lifebookSettingsApi = {\n  get: () => http.get<LbSettings>('/lifebook/me/settings'),\n  patch: (patch: Partial<Record<keyof LbSettings, Partial<Record<string, unknown>>>>) =>\n    http.patch<LbSettings>('/lifebook/me/settings', patch),\n};\n\nexport const lifebookBlocksApi = {\n  block: (userId: string) => http.post<{ ok: boolean; blocked: boolean }>(`/lifebook/users/${userId}/block`, {}),\n  unblock: (userId: string) => httpRequest<{ ok: boolean; blocked: boolean }>(`/lifebook/users/${userId}/block`, { method: 'DELETE' }),\n  mine: () => http.get<LbBlockedUser[]>('/lifebook/me/blocks'),\n};\n\n/* ── Parte 27 (G3): DESCUBRIR GRUPOS Y UNIRSE ───────────────────────────── */\n\nexport interface LbGroupCardMember {\n  id: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  role?: 'owner' | 'admin' | 'member';\n  joinedAt?: string;\n}\n\n/** Ficha pública de un grupo (lo que se ve antes de unirse). */\nexport interface LbGroupCard {\n  id: string;\n  title: string;\n  photoUrl: string | null;\n  city: string | null;\n  barrio: string | null;\n  category: string | null;\n  description: string | null;\n  topic: string | null;\n  visibility: 'public' | 'private' | 'hidden';\n  joinMode: 'open' | 'approval' | 'question';\n  /** La pregunta de ingreso (la respuesta NUNCA la manda el servidor). */\n  joinQuestion: string | null;\n  ownerId: string | null;\n  ownerName: string | null;\n  ownerAvatarUrl: string | null;\n  membersCount: number;\n  placeName: string | null;\n  createdAt: string | null;\n  /** Si ya soy miembro, con qué rol. */\n  myRole: 'owner' | 'admin' | 'member' | null;\n  /** Estado de mi solicitud para entrar. */\n  requestState: 'pending' | 'approved' | 'rejected' | null;\n  /** Vista previa de miembros (solo en la ficha). */\n  members?: LbGroupCardMember[];\n}\n\nexport interface LbGroupJoinRequest {\n  userId: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  city: string | null;\n  state: 'pending' | 'approved' | 'rejected';\n  answer: string | null;\n  note: string | null;\n  createdAt: string;\n  decidedAt: string | null;\n}\n\nexport const lifebookGroupsApi = {\n  /** Descubrimiento: grupos públicos con filtros. */\n  list: (o: { city?: string; category?: string; q?: string; cursor?: string; limit?: number } = {}) =>\n    http.get<{ groups: LbGroupCard[]; nextCursor: string | null }>(\n      `/lifebook/groups${qs({\n        city: o.city, category: o.category, q: o.q, cursor: o.cursor,\n        limit: o.limit ? String(o.limit) : undefined,\n      })}`),\n  /** Ficha pública de un grupo. */\n  card: (id: string) => http.get<LbGroupCard>(`/lifebook/groups/${id}/card`),\n  /** Unirse: entra directo, deja solicitud o valida la pregunta. */\n  join: (id: string, input: { answer?: string; note?: string } = {}) =>\n    http.post<{ joined: boolean; requested: boolean; state: 'pending' | null; group: LbGroupCard }>(`/lifebook/groups/${id}/join`, input),\n  cancelJoin: (id: string) => httpRequest<{ ok: boolean }>(`/lifebook/groups/${id}/join`, { method: 'DELETE' }),\n  /** Solicitudes del grupo (dueño y administradores). */\n  requests: (id: string) => http.get<{ requests: LbGroupJoinRequest[]; pending: number }>(`/lifebook/groups/${id}/requests`),\n  decide: (id: string, userId: string, action: 'approve' | 'reject') =>\n    http.post<{ requests: LbGroupJoinRequest[]; pending: number }>(`/lifebook/groups/${id}/requests/${userId}`, { action }),\n\n  /* ── Parte 28 (G4): código de ruta (y QR) ── */\n\n  /** Código de invitación del grupo (dueño y administradores). */\n  inviteCode: (id: string) => http.get<{ code: string; title: string | null; link: string }>(`/lifebook/groups/${id}/invite`),\n  /** Grupo al que corresponde un código (entrar sin buscador). */\n  byCode: (code: string) => http.get<LbGroupCard>(`/lifebook/groups/by-code/${encodeURIComponent(code)}`),\n\n  /**\n   * Parte 29 (G4): revisar (o limpiar) los INACTIVOS del grupo. Con `dryRun` solo\n   * devuelve a quién quitaría; `days` permite usar otro umbral.\n   */\n  sweepInactive: (id: string, o: { days?: number; dryRun?: boolean } = {}) =>\n    http.post<{\n      dryRun: boolean; days: number; removed: number;\n      candidates: { userId: string; fullName: string | null; avatarUrl: string | null; lastSeen: string }[];\n    }>(`/lifebook/groups/${id}/sweep-inactive`, o),\n};\n\n/* ── Parte 28 (G4): UBICACIÓN EN VIVO durante la ruta ───────────────────── */\n\nexport interface LbLiveSharer {\n  userId: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  lat: number;\n  lng: number;\n  label: string | null;\n  mine: boolean;\n  updatedAt: string;\n  startedAt: string;\n  expiresAt: string;\n  /** Segundos desde la última actualización. */\n  ageSec: number;\n  /** Minutos que le quedan de compartir. */\n  minutesLeft: number;\n}\n\nexport const lifebookLiveApi = {\n  list: (convId: string) => http.get<{ sharing: LbLiveSharer[] }>(`/lifebook/chat/conversations/${convId}/live`),\n  start: (convId: string, input: { lat: number; lng: number; label?: string; minutes?: number }) =>\n    http.post<{ sharing: LbLiveSharer[] }>(`/lifebook/chat/conversations/${convId}/live`, input),\n  update: (convId: string, input: { lat: number; lng: number }) =>\n    httpRequest<{ sharing: LbLiveSharer[] }>(`/lifebook/chat/conversations/${convId}/live`, { method: 'PATCH', body: input }),\n  stop: (convId: string) =>\n    httpRequest<{ sharing: LbLiveSharer[] }>(`/lifebook/chat/conversations/${convId}/live`, { method: 'DELETE' }),\n};\n\n/* ── Parte 26 (G2-c): PLAZA DE RETOS ─────────────────────────────────────── */\n\nexport interface LbChallengeMember {\n  id: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  note: string | null;\n  joinedAt: string;\n}\n\nexport interface LbChallenge {\n  id: string;\n  title: string;\n  body: string | null;\n  city: string | null;\n  prize: string | null;\n  coverUrl: string | null;\n  author: { id: string; fullName: string | null; avatarUrl: string | null };\n  state: 'open' | 'closed';\n  endsAt: string | null;\n  closedAt: string | null;\n  createdAt: string;\n  entries: number;\n  joinedByMe: boolean;\n  mine: boolean;\n  /** Ranking: participantes por orden de inscripción. */\n  members: LbChallengeMember[];\n}\n\nexport const lifebookChallengesApi = {\n  list: (o: { city?: string; state?: 'open' | 'closed' | 'all'; mine?: boolean; joined?: boolean; limit?: number } = {}) =>\n    http.get<{ challenges: LbChallenge[]; total: number }>(\n      `/lifebook/challenges${qs({\n        city: o.city,\n        state: o.state,\n        mine: o.mine ? '1' : undefined,\n        joined: o.joined ? '1' : undefined,\n        limit: o.limit ? String(o.limit) : undefined,\n      })}`),\n  detail: (id: string) => http.get<LbChallenge>(`/lifebook/challenges/${id}`),\n  create: (dto: { title: string; body?: string; city?: string; prize?: string; endsAt?: string; coverUrl?: string }) =>\n    http.post<LbChallenge>('/lifebook/challenges', dto),\n  join: (id: string, note?: string) => http.post<LbChallenge>(`/lifebook/challenges/${id}/join`, { note }),\n  leave: (id: string) => httpRequest<LbChallenge>(`/lifebook/challenges/${id}/join`, { method: 'DELETE' }),\n  close: (id: string) => http.post<LbChallenge>(`/lifebook/challenges/${id}/close`, {}),\n};\n\nexport const lifebookActionsApi = {\n  report: (contentId: string, contentType: 'post' | 'comment', reason: string, note?: string) =>\n    http.post<{ ok: boolean; quarantined?: boolean }>('/lifebook/report', { contentId, contentType, reason, ...(note?.trim() ? { note: note.trim() } : {}) }),\n  commentsState: (postId: string, enabled: boolean) =>\n    http.post<{ ok: boolean; allowComments: boolean }>(`/lifebook/posts/${postId}/comments-state`, { enabled }),\n\n  /* ── Acciones con el contrato literal del cliente (rutas reales del servidor) ── */\n\n  /** Me gusta / quitar: `POST /posts/:id/like { liked }`. */\n  toggleLike: (postId: string, liked: boolean) =>\n    http.post<{ liked: boolean; reaction?: string }>(`/lifebook/posts/${postId}/like`, { liked }),\n\n  /** Guardar / quitar: `POST /posts/:id/save { saved }` (alias de /bookmark). */\n  toggleSave: (postId: string, saved: boolean) =>\n    http.post<{ bookmarked: boolean }>(`/lifebook/posts/${postId}/save`, { saved }),\n\n  /** Seguir / dejar de seguir: `POST /users/:id/follow { follow }`. */\n  toggleFollow: (userId: string, follow: boolean) =>\n    http.post<{ following: boolean }>(`/lifebook/users/${userId}/follow`, { follow }),\n\n  /** Comentar: `POST /posts/:id/comments { text, parentId? }` → comentario creado. */\n  addComment: (postId: string, text: string, parentId?: string) =>\n    http.post<LbCommentItem>(`/lifebook/posts/${postId}/comments`, { text, ...(parentId ? { parentId } : {}) }),\n\n  /**\n   * Parte 28 (G4): reportar a una PERSONA (un miembro del grupo, el otro en un\n   * 1 a 1). Mismo catálogo de motivos; moderación lo ve como tipo `user`.\n   */\n  reportUser: (userId: string, reason: string, note?: string) =>\n    http.post<{ ok: boolean; reported: string }>(`/lifebook/users/${userId}/report`, { reason, ...(note?.trim() ? { note: note.trim() } : {}) }),\n};\n\n// ---------------- Parte 7: bandeja (iconos del header de Mensajes) ----------------\n\nexport interface LbInboxCounts { likes: number; saves: number; followers: number; comments: number; mentions: number }\n\nexport interface LbPostRef {\n  id: string;\n  type: string;\n  title: string | null;\n  preview: string;\n  thumb: LbMediaItem | null;\n}\n\nexport interface LbInboxUser { id: string; fullName: string | null; avatarUrl: string | null; city?: string | null }\n\nexport interface LbLikeReceived { at: string; reaction: string; user: LbInboxUser; post: LbPostRef }\nexport interface LbSaveReceived { at: string; user: LbInboxUser; post: LbPostRef }\nexport interface LbFollowerItem {\n  at: string; id: string; fullName: string | null; avatarUrl: string | null; city: string | null;\n  followedBack: boolean; posts: number; verified: { driver: boolean; seller: boolean };\n}\nexport interface LbSuggestedUser {\n  id: string; fullName: string | null; avatarUrl: string | null; city: string | null;\n  recentPosts: number; verified: { driver: boolean; seller: boolean; food: boolean }; reason: string;\n}\nexport interface LbCommentReceived { id: string; body: string; at: string; user: LbInboxUser; post: LbPostRef }\nexport interface LbMentionReceived { id: string; snippet: string | null; at: string; read: boolean; user: LbInboxUser; post: LbPostRef | null }\n\nexport const lifebookInboxApi = {\n  counts: () => http.get<LbInboxCounts>('/lifebook/me/inbox-counts'),\n  likes: () => http.get<LbLikeReceived[]>('/lifebook/me/likes-received'),\n  saves: () => http.get<LbSaveReceived[]>('/lifebook/me/saves-received'),\n  followers: () => http.get<LbFollowerItem[]>('/lifebook/me/new-followers'),\n  suggested: () => http.get<LbSuggestedUser[]>('/lifebook/me/suggested-users'),\n  comments: () => http.get<LbCommentReceived[]>('/lifebook/me/comments-received'),\n  mentions: () => http.get<LbMentionReceived[]>('/lifebook/me/mentions'),\n  readMentions: () => http.post<{ ok: boolean }>('/lifebook/me/mentions/read', {}),\n\n  /** Parte 16: marca una bandeja como leída (`likes` · `followers` · `comments`). */\n  markRead: (kind: 'likes' | 'followers' | 'comments') =>\n    http.post<{ ok: boolean; kind: string }>('/lifebook/me/inbox/read', { kind }),\n};\n\n","/**\n * Life Book — constantes de producto (canales del feed, catálogo de temas,\n * tonos, visibilidad, ciudades). Espejo local de DISEÑO-UX-LIFEBOOK-INICIO §2\n * y DISEÑO-UX-LIFEBOOK-PUBLICAR §3.1 (NOTA).\n */\nimport {\n  Briefcase, CarTaxiFront, Heart, Home, MapPin, MessageSquareText, Music,\n  Palette, Sparkles, Sun, Tag, Trophy, Utensils, type LucideIcon,\n} from 'lucide-react-native';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport interface LbChannel {\n  id: string;\n  label: string;\n  /** Color de marca del canal (píldora activa rellena). */\n  color: string;\n  icon: LucideIcon;\n}\n\n/**\n * Canales del feed, en orden.\n *\n * REORGANIZACIÓN (lo que pidió el dueño, con la investigación de Xiaohongshu\n * delante — ver `docs/ORGANIZACION-LIFEBOOK-XIAOHONGSHU.md`):\n *\n *  · Arriba van las tres de siempre pero **con los nombres que se pidieron**:\n *    **Seguidos** (canal `following`, que YA filtraba de verdad por gente que sigues),\n *    **Descubrir** (el antiguo «Para ti», canal `for_you`) y **Ciudad** (el antiguo\n *    «Cerca», canal `nearby`).\n *  · OJO con el nombre: antes había «Para ti» (`for_you`, no filtra) y «Siguiendo»\n *    (`following`, sí filtra). Renombrar «Para ti» a «Seguidos» a secas habría dejado\n *    DOS pestañas que parecen lo mismo y una de ellas mentiría. Por eso «Seguidos» es\n *    el canal que filtra, y el otro pasa a llamarse «Descubrir».\n *  · «Ventas» pasa a llamarse **«Comercio»**, que es como lo pidió el dueño (y el\n *    canal del servidor sigue siendo `sales`).\n *  · Se añaden los cuatro canales de la pestaña de ciudad: `tourism`, `bars`, `party`\n *    y `citywalk`. **Estos cuatro son NUESTROS**, no copiados: ni «City walk», ni\n *    «Bares» ni «Fiesta» aparecen en ninguna fuente sobre Xiaohongshu.\n */\nexport const LB_CHANNELS: LbChannel[] = [\n  // ── Las tres de arriba ──────────────────────────────────────────────────────\n  { id: 'following', label: 'Seguidos',    color: brand.primary, icon: Heart },\n  { id: 'for_you',   label: 'Descubrir',   color: brand.primary, icon: Sparkles },\n  { id: 'nearby',    label: 'Ciudad',      color: brand.primary, icon: MapPin },\n  // ── Chips de temas (debajo de las pestañas) ─────────────────────────────────\n  { id: 'sales',     label: 'Comercio',    color: '#E0439A', icon: Tag },\n  { id: 'debates',   label: 'Debates',     color: brand.secondary, icon: MessageSquareText },\n  { id: 'food',      label: 'Comida',      color: brand.secondary, icon: Utensils },\n  { id: 'culture',   label: 'Cultura',     color: '#8B5CF6', icon: Palette },\n  { id: 'music',     label: 'Música',      color: '#8B5CF6', icon: Music },\n  { id: 'sports',    label: 'Deportes',    color: brand.success, icon: Trophy },\n  { id: 'today',     label: 'Hoy',         color: brand.primary, icon: Sun },\n  { id: 'taxi',      label: 'Taxi',        color: brand.primary, icon: CarTaxiFront },\n  { id: 'work',      label: 'Trabajo',     color: brand.secondary, icon: Briefcase },\n  { id: 'rental',    label: 'Alquiler',    color: brand.secondary, icon: Home },\n  // ── Chips de la pestaña CIUDAD ──────────────────────────────────────────────\n  { id: 'citywalk',  label: 'City walk',   color: brand.success, icon: MapPin },\n  { id: 'tourism',   label: 'Turismo',     color: brand.success, icon: MapPin },\n  { id: 'bars',      label: 'Bares',       color: '#8B5CF6', icon: Utensils },\n  { id: 'party',     label: 'Fiesta',      color: '#8B5CF6', icon: Music },\n];\n\n/** Las tres pestañas de arriba, en orden. El resto del catálogo son chips. */\nexport const LB_TABS: string[] = ['following', 'for_you', 'nearby'];\n\n/**\n * LOS CHIPS DE CADA SECCIÓN.\n *\n * Es lo que pidió el dueño: «cuando estás en Seguidos los que muestran abajo serán\n * distintos de los que hayan en Descubrir o ciudad». Y no es solo el dibujo: el chip\n * **filtra DENTRO de la sección** (el backend se amplió para eso en esta misma ronda),\n * de forma que «Comercio» en Seguidos es el comercio **de la gente que sigo**, no el de\n * todos.\n *\n * Cada chip puede llevar:\n *   · `type`       → filtra por tipo de publicación (`sale`, `video`, `debate`…).\n *   · `conCiudad`  → manda la ciudad al servidor. Solo lo hacen los chips de la\n *                    pestaña Ciudad: los de Descubrir se quedan globales, como estaban.\n */\nexport interface LbChip {\n  label: string;\n  channel: string;\n  type?: string;\n  conCiudad?: boolean;\n}\n\nexport const LB_CHIPS_BY_TAB: Record<string, LbChip[]> = {\n  /** SEGUIDOS: lo de la gente que sigo, por tipo. */\n  following: [\n    { label: 'Todo', channel: 'following' },\n    { label: 'Comercio', channel: 'following', type: 'sale' },\n    { label: 'Vídeos', channel: 'following', type: 'video' },\n    { label: 'Debates', channel: 'following', type: 'debate' },\n  ],\n  /** DESCUBRIR: los temas de siempre, globales (no se manda la ciudad). */\n  for_you: [\n    { label: 'Comercio', channel: 'sales' },\n    { label: 'Debates', channel: 'debates' },\n    { label: 'Comida', channel: 'food' },\n    { label: 'Cultura', channel: 'culture' },\n    { label: 'Música', channel: 'music' },\n    { label: 'Deportes', channel: 'sports' },\n    { label: 'Hoy', channel: 'today' },\n    { label: 'Taxi', channel: 'taxi' },\n    { label: 'Trabajo', channel: 'work' },\n    { label: 'Alquiler', channel: 'rental' },\n  ],\n  /** CIUDAD: dentro de TU ciudad (por eso todos llevan `conCiudad`). */\n  nearby: [\n    { label: 'Recomendado', channel: 'nearby' },\n    { label: 'Comercio', channel: 'nearby', type: 'sale' },\n    { label: 'City walk', channel: 'citywalk', conCiudad: true },\n    { label: 'Comida', channel: 'food', conCiudad: true },\n    { label: 'Turismo', channel: 'tourism', conCiudad: true },\n    { label: 'Bares', channel: 'bars', conCiudad: true },\n    { label: 'Fiesta', channel: 'party', conCiudad: true },\n    { label: 'Cultura', channel: 'culture', conCiudad: true },\n  ],\n};\n\n/* (aquí vivía `LB_VISIBLES`, la lista temporal de la fila única. Se borró al entrar\n   la fila doble: ahora son TRES pestañas arriba —`LB_TABS`— y, debajo, los chips de la\n   sección activa —`LB_CHIPS_BY_TAB`—.) */\n\n/**\n * Chips que se enseñan debajo de las pestañas cuando NO estás en la ciudad: los\n * temas, con «Comercio» el primero (es lo que pidió el dueño).\n */\nexport const LB_TOPIC_CHIPS: string[] = [\n  'sales', 'debates', 'food', 'culture', 'music', 'sports', 'today', 'taxi', 'work', 'rental',\n];\n\n/**\n * Chips de la pestaña **Ciudad**: la ciudad que hayas elegido y, dentro, esto.\n * «Recomendado» es el canal `nearby` (lo de tu ciudad sin filtrar por tema). Los\n * demás son canales por palabras clave, que hoy NO filtran por ciudad en el servidor\n * (van por texto): queda anotado como pendiente, no se disimula.\n */\nexport const LB_CITY_CHIPS: string[] = [\n  'nearby', 'citywalk', 'food', 'tourism', 'bars', 'party', 'culture',\n];\n\n/** Ciudades del selector (DISEÑO-UX-LIFEBOOK-INICIO §1.3). */\n/**\n * LAS CIUDADES DE GUINEA ECUATORIAL.\n *\n * Antes eran solo cinco (Malabo, Bata, Ebebiyín, Mongomo, Luba) y **faltaba casi todo el país**:\n * no estaban Acurenam, Evinayong, Aconibe, Mbini, Niefang, Micomeseng, Riaba, Annobón… y hasta la\n * ciudad del propio perfil del usuario (Acurenam) no se podía elegir en la lista. Se completa con\n * las cabeceras de distrito y las localidades con contenido real.\n */\nexport const LB_CITIES = [\n  // Región Insular\n  'Malabo', 'Luba', 'Riaba', 'San Antonio de Palé', 'Corisco',\n  // Región Continental\n  'Bata', 'Mbini', 'Niefang', 'Micomeseng', 'Ebebiyín', 'Mongomo', 'Evinayong', 'Aconibe',\n  'Acurenam', 'Nsok', 'Oyala', 'Mengomeyén', 'Bidjabidján', 'Cogo',\n] as const;\n\n/**\n * Parte 24 (G2) — etiqueta legible del `kind` que devuelve el geocoder de OSM\n * (`api/geocode.ts`), al compartir una ubicación en el chat.\n */\nexport const LB_PLACE_KIND_LABEL: Record<string, string> = {\n  road: 'Vía', residential: 'Calle', primary: 'Avenida', secondary: 'Avenida',\n  tertiary: 'Calle', motorway: 'Autovía', trunk: 'Carretera', unclassified: 'Camino',\n  service: 'Acceso', living_street: 'Calle', pedestrian: 'Zona peatonal', path: 'Sendero',\n  steps: 'Escaleras', village: 'Poblado', town: 'Localidad', city: 'Ciudad',\n  suburb: 'Barrio', neighbourhood: 'Barrio', peak: 'Cumbre', park: 'Parque',\n  school: 'Colegio', hospital: 'Hospital', restaurant: 'Restaurante', cafe: 'Cafetería',\n  fuel: 'Gasolinera', marketplace: 'Mercado', bus_station: 'Estación de bus',\n  beach: 'Playa', hotel: 'Hotel', bank: 'Banco', pharmacy: 'Farmacia', church: 'Iglesia',\n};\n\n/**\n * Etiqueta para el chip de categoría de la tarjeta (PostCard v2).\n * Cubre los tres espacios de nombres que pueden llegar en `category`:\n * canales del feed (`food`, `taxi`, `sales`…), tipos de enlace de servicio\n * (`food`, `ecomerse`, `work`…) y tipos de publicación (`sale`, `video`…).\n */\nexport const LB_CATEGORY_LABEL: Record<string, string> = {\n  // canales\n  for_you: 'Descubrir', following: 'Seguidos', nearby: 'Ciudad', today: 'Hoy',\n  debates: 'Debates', food: 'Comida', taxi: 'Taxi', work: 'Trabajo',\n  rental: 'Alquiler', sales: 'Comercio', culture: 'Cultura', music: 'Música', sports: 'Deportes',\n  tourism: 'Turismo', bars: 'Bares', party: 'Fiesta', citywalk: 'City walk',\n  // tipos de publicación\n  note: 'Nota', sale: 'Ventas', service: 'Servicio', debate: 'Debate',\n  video: 'Vídeo', podcast: 'Podcast', serie: 'Serie',\n  // tipos de enlace de servicio\n  ecomerse: 'Tienda', shop: 'Tienda', paquete: 'Paquete', delivery: 'Paquete',\n  tickets: 'Entradas', lifebook: 'Life Book',\n};\n\n/** Etiqueta legible de una categoría (chip de la tarjeta). */\nexport function lbCategoryLabel(value: string | null | undefined): string | undefined {\n  const key = String(value ?? '').trim();\n  if (!key) return undefined;\n  return LB_CATEGORY_LABEL[key] ?? key.charAt(0).toUpperCase() + key.slice(1);\n}\n\n/** Catálogo local de temas (PUBLICAR §3.1: hasta 5 + hashtags libres). */\nexport const LB_TOPIC_CATALOG = [\n  'vida', 'familia', 'trabajo', 'estudios', 'salud', 'comida', 'cultura',\n  'musica', 'deportes', 'fiestas', 'tradiciones', 'negocios', 'transporte', 'anuncio',\n];\n\nexport const LB_TONE_OPTIONS = [\n  { value: 'info', label: 'Informativo' },\n  { value: 'opinion', label: 'Opinión' },\n  { value: 'denuncia', label: 'Denuncia' },\n  { value: 'humor', label: 'Humor' },\n  { value: 'pregunta', label: 'Pregunta' },\n] as const;\n\nexport const LB_VISIBILITY_OPTIONS = [\n  { value: 'public', label: 'Todos', hint: 'Lo ve todo el mundo' },\n  { value: 'followers', label: 'Seguidores', hint: 'Solo tus seguidores' },\n  { value: 'private', label: 'Solo yo', hint: 'Nadie más lo ve' },\n] as const;\n\nexport type LbVisibility = 'public' | 'followers' | 'private';\n\n/** Límites (espejo backend + diseño). */\nexport const LB_NOTE_BODY_MAX = 500;\nexport const LB_NOTE_TITLE_MAX = 60; // diseño: máx 60 en nota\nexport const LB_NOTE_MEDIA_MAX = 4;\nexport const LB_NOTE_TOPICS_MAX = 5;\nexport const LB_TAG_MAX_LEN = 24;\n\n/** Etiqueta corta por tipo de contenido (tarjetas/badges). */\nexport function lbTypeLabel(type: string): string {\n  switch (type) {\n    case 'note': return 'NOTA';\n    case 'sale': return 'VENTA';\n    case 'service': return 'SERVICIO';\n    case 'debate': return 'DEBATE';\n    default: return String(type).toUpperCase();\n  }\n}\n\n/** \"hace 5 min\" · \"hace 3 h\" · \"ayer\" · fecha corta. */\nexport function lbTimeAgo(iso: string | null | undefined): string {\n  if (!iso) return '';\n  const t = new Date(iso).getTime();\n  if (Number.isNaN(t)) return '';\n  const diff = Date.now() - t;\n  const min = Math.floor(diff / 60_000);\n  if (min < 1) return 'ahora';\n  if (min < 60) return `hace ${min} min`;\n  const h = Math.floor(min / 60);\n  if (h < 24) return `hace ${h} h`;\n  const d = Math.floor(h / 24);\n  if (d === 1) return 'ayer';\n  if (d < 7) return `hace ${d} días`;\n  return new Date(iso).toLocaleDateString('es-GQ', { day: 'numeric', month: 'short' });\n}\n\n/** Formatea el precio en XAF (1.500 → \"1.500 XAF\"). */\nexport function lbXaf(value: number | null | undefined): string {\n  const n = Number(value ?? 0);\n  if (!Number.isFinite(n)) return '';\n  return `${n.toLocaleString('es-GQ')} XAF`;\n}\n\n/** \"0:45\" · \"12:34\" · \"1:02:03\" (duración en segundos). */\nexport function fmtDur(sec: number | null | undefined): string {\n  const s = Math.max(0, Math.floor(Number(sec ?? 0) || 0));\n  const h = Math.floor(s / 3600);\n  const m = Math.floor((s % 3600) / 60);\n  const r = s % 60;\n  const mm = h > 0 ? String(m).padStart(2, '0') : String(m);\n  const ss = String(r).padStart(2, '0');\n  return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;\n}\n\n/** Metadatos visuales por tipo rico (Parte 4). */\nexport const RICH_TYPE: Record<string, { emoji: string; label: string; color: string }> = {\n  video: { emoji: '🎬', label: 'VIDEO', color: '#7C3AED' },\n  podcast: { emoji: '🎙️', label: 'PODCAST', color: '#E0439A' },\n  serie: { emoji: '📺', label: 'SERIE', color: brand.secondary },\n};\n\n/** Mime/extensiones aceptadas para subir (espejo backend). */\nexport const MEDIA_KIND_ACCEPT: Record<string, { accept: string[]; maxMb: number; maxSec?: number; label: string }> = {\n  image: { accept: ['image/jpeg', 'image/png', 'image/webp'], maxMb: 10, label: 'portada' },\n  // `video` = perfil CORTO (el del feed rápido). El largo tiene su propio perfil abajo.\n  video: { accept: ['video/mp4', 'video/quicktime', 'video/webm'], maxMb: 120, maxSec: 60, label: 'vídeo' },\n  audio: { accept: ['audio/mpeg', 'audio/mp4', 'audio/aac', 'audio/wav', 'audio/ogg'], maxMb: 60, maxSec: 3600, label: 'audio' },\n};\n\n/**\n * PERFILES DE VÍDEO (Parte 50) — espejo exacto del backend:\n *   el servidor tiene `video_short` (60 s / 120 MB) y `video_long` (3000 s = 50 min / 1200 MB),\n *   que salen de `MEDIA_MAX_VIDEO_SHORT_MB`, `MEDIA_MAX_VIDEO_LONG_SEC` y `MEDIA_MAX_VIDEO_LONG_MB`.\n *\n * Por qué DOS perfiles y no uno solo más alto: el corto es el que hace que el feed de Like Book\n * cargue al instante; subir el tope del corto a 50 min estropearía el feed para todos. El largo\n * es una decisión explícita del que publica.\n *\n * ⚠️ El tope REAL lo impone el almacenamiento (MinIO) en la URL firmada, no la app: aquí solo\n * se avisa antes de gastar datos del usuario.\n */\nexport const LB_VIDEO_PERFILES = {\n  short: {\n    id: 'short' as const,\n    maxSec: 60,\n    maxMb: 120,\n    label: 'Vídeo corto',\n    hint: 'hasta 1 min',\n    desc: 'El del feed: se ve al instante.',\n  },\n  long: {\n    id: 'long' as const,\n    maxSec: 3000,   // 50 min\n    maxMb: 1200,\n    label: 'Vídeo largo',\n    hint: 'hasta 50 min',\n    desc: 'Para clases, reportajes, partidos…',\n  },\n};\nexport type LbVideoPerfilId = keyof typeof LB_VIDEO_PERFILES;\nexport type LbVideoPerfil = (typeof LB_VIDEO_PERFILES)[LbVideoPerfilId];\n\n/** Perfil que corresponde a una duración (por defecto, el corto). */\nexport function lbPerfilVideo(durSec: number | null | undefined): LbVideoPerfil {\n  return Number(durSec ?? 0) > LB_VIDEO_PERFILES.short.maxSec ? LB_VIDEO_PERFILES.long : LB_VIDEO_PERFILES.short;\n}\n\n/**\n * Velocidad de subida de REFERENCIA, en MB/s, para poder dar un tiempo ANTES de empezar.\n *\n * Medida en el Poco F5 el 13-sep-2026: **0,21 MB/s**. Es el número PESIMISTA a propósito — esa\n * medición se hizo por el peor camino real (VPN activa y el móvil compartiendo conexión a la\n * vez), y la red del propio móvil declara 0,57 MB/s. Un aviso de tiempo solo sirve si promete\n * de menos y tarda menos; si promete el número optimista, el usuario aprende que la app miente.\n *\n * NO se usa el número del servidor (~0,65 MB/s) porque ese es un techo COMPARTIDO por todos y\n * del mismo orden que la red del móvil: no describe la subida de nadie en particular.\n */\nexport const LB_SUBIDA_MBPS_REFERENCIA = 0.21;\n\n/**\n * Tiempo de subida estimado en texto (\"~45 s\" · \"~24 min\" · \"~1,2 h\") a partir del peso.\n *\n * Es una ESTIMACIÓN con la velocidad de referencia, no una medida: la barra de progreso sí mide.\n * Sirve para decidir ANTES de gastar datos, que es justo cuando el dato hace falta.\n */\nexport function lbTiempoSubida(bytes: number | null | undefined): string {\n  const mb = Math.max(0, Number(bytes ?? 0) || 0) / (1024 * 1024);\n  if (mb <= 0) return '';\n  const seg = mb / LB_SUBIDA_MBPS_REFERENCIA;\n  // Menos de minuto y medio: en segundos se entiende mejor y no asusta con un \"2 min\".\n  if (seg < 90) return `~${Math.max(10, Math.round(seg / 10) * 10)} s`;\n  const min = seg / 60;\n  if (min < 60) return `~${Math.round(min)} min`;\n  return `~${(min / 60).toFixed(1).replace('.', ',')} h`;\n}\n\n/** \"12,4 MB\" · \"1,2 GB\" — para avisar del peso antes de subir. */\nexport function lbPeso(bytes: number | null | undefined): string {\n  const n = Math.max(0, Number(bytes ?? 0) || 0);\n  if (n < 1024 * 1024) return `${Math.max(1, Math.round(n / 1024))} KB`;\n  const mb = n / (1024 * 1024);\n  return mb >= 1024 ? `${(mb / 1024).toFixed(2).replace('.', ',')} GB` : `${mb.toFixed(mb < 10 ? 1 : 0).replace('.', ',')} MB`;\n}\n\nexport function mimeToExt(mime: string): string {\n  const map: Record<string, string> = {\n    'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp',\n    'video/mp4': 'mp4', 'video/quicktime': 'mov', 'video/webm': 'webm',\n    'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac', 'audio/wav': 'wav', 'audio/ogg': 'ogg',\n  };\n  return map[mime] ?? 'bin';\n}\n\n/** Motivos de reporte (catálogo oficial, espejo backend). */\nexport const LB_REPORT_REASONS: Array<{ value: string; label: string }> = [\n  { value: 'spam', label: 'Spam o publicidad no deseada' },\n  { value: 'fraud', label: 'Fraude o estafa' },\n  { value: 'false_content', label: 'Información falsa' },\n  { value: 'harassment', label: 'Acoso' },\n  { value: 'hate', label: 'Discurso de odio' },\n  { value: 'sexual', label: 'Contenido sexual' },\n  { value: 'violence', label: 'Violencia' },\n  { value: 'personal_info', label: 'Datos personales sin permiso' },\n  { value: 'illegal_sale', label: 'Venta ilegal' },\n  { value: 'impersonation', label: 'Suplantación de identidad' },\n  { value: 'false_emergency', label: 'Emergencia falsa' },\n];\n\n/** Etiquetas de visibilidad/privacidad (ajustes + publicar). */\nexport const LB_VIS_LABEL: Record<string, string> = {\n  public: 'Todos', followers: 'Seguidores', private: 'Solo yo', nobody: 'Nadie',\n};\n\n/** Grupos de privacidad de Ajustes (clave → si admite \"Nadie\"). */\nexport const LB_PRIVACY_KEYS: Array<{ key: string; label: string; nobody: boolean }> = [\n  { key: 'posts', label: 'Quién puede ver mis publicaciones', nobody: false },\n  { key: 'messages', label: 'Quién puede enviarme mensajes', nobody: true },\n  { key: 'location', label: 'Quién puede ver mi ubicación', nobody: true },\n  { key: 'comments', label: 'Quién puede comentar', nobody: false },\n  { key: 'email', label: 'Quién puede ver mi correo', nobody: true },\n];\n\n/** Filas de notificaciones (clave → label). */\nexport const LB_NOTIF_ROWS: Array<{ key: string; label: string }> = [\n  { key: 'likes', label: '❤️ Me gusta' },\n  { key: 'comments', label: '💬 Comentarios' },\n  { key: 'follows', label: '👥 Nuevos seguidores' },\n  { key: 'messages', label: '📩 Mensajes' },\n  { key: 'orders', label: '📦 Pedidos' },\n  { key: 'debates', label: '🗣️ Debates' },\n  { key: 'promotions', label: '🎁 Promociones' },\n  { key: 'digest', label: '📋 Resumen diario' },\n];\nexport const LB_ORDER_META: Record<string, { label: string; color: string }> = {\n  requested: { label: 'Pedido enviado', color: brand.primary },\n  accepted: { label: 'Aceptado', color: brand.success },\n  declined: { label: 'Rechazado', color: brand.danger },\n  in_transit: { label: 'En camino', color: brand.secondary },\n  delivered: { label: 'Entregado', color: brand.success },\n  cancelled: { label: 'Cancelado', color: '#86909C' },\n  disputed: { label: 'Disputa', color: '#E0439A' },\n  // Parte 36: estados del COMERCIO (pedido con líneas, tienda y entrega)\n  created: { label: 'Pedido creado', color: brand.primary },\n  confirmed: { label: 'Confirmado por la tienda', color: brand.success },\n  preparing: { label: 'En preparación', color: brand.secondary },\n  ready_pickup: { label: 'Listo para recoger', color: '#7C3AED' },\n};\n\n/** Barra de progreso del pedido del comercio (Parte 36). */\nexport const LB_ORDER_FLOW: { status: string; label: string }[] = [\n  { status: 'created', label: 'Recibido' },\n  { status: 'confirmed', label: 'Confirmado' },\n  { status: 'preparing', label: 'En preparación' },\n  { status: 'in_transit', label: 'En camino' },\n  { status: 'delivered', label: 'Entregado' },\n];\n\n/** Acciones del VENDEDOR según el estado (modelo nuevo del comercio). */\nexport const LB_SELLER_ORDER_ACTIONS: Record<string, string[]> = {\n  created: ['accept', 'decline'],\n  confirmed: ['prepare', 'send'],\n  preparing: ['send', 'ready'],\n  in_transit: ['deliver'],\n  ready_pickup: ['deliver'],\n};\n\n/** Acciones del COMPRADOR según el estado (modelo nuevo). */\nexport const LB_COMMERCE_BUYER_ACTIONS: Record<string, string[]> = {\n  created: ['cancel'],\n  confirmed: ['cancel', 'dispute'],\n  preparing: ['cancel', 'dispute'],\n  in_transit: ['dispute'],\n  ready_pickup: ['dispute'],\n  delivered: ['dispute'],\n};\n\n/** Etiquetas de las acciones nuevas (las antiguas ya están en LB_ORDER_ACTION_LABEL). */\nexport const LB_ORDER_ACTION_LABEL_EXTRA: Record<string, string> = {\n  prepare: 'En preparación',\n  ready: 'Listo para recoger',\n};\n\n\n/** Acciones disponibles según rol y estado (cliente). */\nexport const LB_ORDER_ACTIONS: Record<string, string[]> = {\n  requested: ['accept', 'decline'],\n  accepted: ['send'],\n  in_transit: ['deliver'],\n};\nexport const LB_ORDER_BUYER_ACTIONS: Record<string, string[]> = {\n  requested: ['cancel'],\n  accepted: ['cancel', 'dispute'],\n  in_transit: ['dispute'],\n};\nexport const LB_ORDER_ACTION_LABEL: Record<string, string> = {\n  accept: 'Aceptar pedido', decline: 'Rechazar', send: 'Enviar (en camino)',\n  deliver: 'Entregar', cancel: 'Cancelar pedido', dispute: 'Abrir disputa',\n};\n","/**\n * Escribir por WhatsApp a una tienda desde cualquier pantalla.\n *\n * POR QUÉ ESTÁ FUERA DE LAS PANTALLAS, igual que `llamarTelefono` (`utils/llamar.ts`): la ficha ya\n * tenía su propia construcción de la URL y el chat de tienda —Fase 4 del pie— necesita la misma.\n * Y el número tiene reglas propias en este país (9 dígitos, prefijo 0 local, 240 internacional) que\n * viven en `toGqMsisdn`: construyendo la URL a mano en cada pantalla, la que se saltara esas reglas\n * abriría WhatsApp con un número roto y el mensaje se perdería sin que nadie lo supiera.\n *\n * POR QUÉ CONVIVE CON EL CHAT Y NO ES UN RESTO. La decisión cerrada de la Fase 4 (5.b del plan) es\n * que el chat es la puerta PRINCIPAL y WhatsApp el ESCAPE visible: en Guinea Ecuatorial WhatsApp es\n * por donde se cierra el trato, y taparlo para empujar al chat nuevo costaría ventas del vendedor.\n * Por eso el chat lleva el botón al lado, no en vez.\n *\n * DEVUELVE `true` SÓLO SI SE LLEGÓ A ABRIR. Es la misma regla que `llamarTelefono`, y aquí además\n * sirve para no contar como «contacto» algo que no ocurrió.\n */\nimport { Alert, Linking } from 'react-native';\nimport { toGqMsisdn } from './phone';\n\n/** El mensaje se pre-rellena con el nombre de la tienda o del anuncio: en WhatsApp, un «hola» suelto\n *  de un número desconocido se ignora. */\nexport async function whatsappATienda(\n  phone: string | null | undefined,\n  texto = 'Hola, te escribo desde EG Route Plan.',\n): Promise<boolean> {\n  const cc = toGqMsisdn(String(phone ?? ''));\n  if (!cc) {\n    Alert.alert('WhatsApp', 'Esta tienda no tiene un número válido. Usa el chat.');\n    return false;\n  }\n  const url = `https://wa.me/${cc}?text=${encodeURIComponent(texto.slice(0, 400))}`;\n  try {\n    await Linking.openURL(url);\n    return true;\n  } catch {\n    Alert.alert('WhatsApp', 'No se pudo abrir WhatsApp en este aparato. Usa el chat.');\n    return false;\n  }\n}\n","/**\n * Mensajes del Mercado — segundo destino del pie (`/ecomerse-mensajes`).\n *\n * QUÉ HAY AQUÍ\n * Dos bloques con forma distinta, y la diferencia es deliberada:\n *\n *   · **Las dos filas del sistema** (Fase 3, 22-sep-2026): «Avisos de tus pedidos» (canal\n *     `transaction`) y «Asistente de logística` (canal `logistics`), cada una con su contador de sin\n *     leer. Son DOS CANALES FIJOS, no una lista: existen siempre, y que hoy no tengan nada es\n *     información («no te ha pasado nada con tus pedidos»), no una ausencia de función. Por eso se\n *     pintan aunque estén a cero y el vacío de verdad vive dentro de cada canal.\n *\n *   · **Las conversaciones con tiendas** (Fase 4): esto sí es una LISTA, y crece con el uso. Una por\n *     tienda, con su nombre y su logo, el último mensaje y los sin leer. Es la cara comercial del\n *     MISMO hilo que el vendedor ve desde su chat de siempre (decisión 5.c): por debajo no hay dos\n *     chats, hay uno con dos caras.\n *\n * POR QUÉ LA CINTA «TODAVÍA NO ESTÁ» YA NO ESTÁ\n * En la Fase 3 este hueco lo ocupaba un bloque honesto que decía que las conversaciones con tiendas\n * todavía no existían. Ahora existen, así que un cartel de «todavía no» sería mentira. Lo que queda\n * es su estado vacío —«no hablas con ninguna tienda»—, que es otra cosa: se dice DENTRO de la\n * sección y explica cómo se empieza, en vez de ocupar el sitio de una función que ya está.\n *\n * EL TEXTO DE LAS FILAS DEL SISTEMA NO VIVE AQUÍ\n * El rótulo y la nota de cada canal salen de `components/ecomerse/canalesAviso.ts`, que es también de\n * donde la pantalla del canal saca su título: así la fila y la cabecera no pueden divergir.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, ChevronRight, Receipt, Truck } from 'lucide-react-native';\nimport { EmptyState, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseChat, type EcomerseNoticeCounts } from '../api/ecomerse';\nimport { getTimeAgo } from '../utils/formatHelpers';\nimport { useSession } from '../state/session';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { AvatarTienda } from '../components/ecomerse/AvatarTienda';\nimport { CANALES_AVISO, type CanalAviso } from '../components/ecomerse/canalesAviso';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\n\n/**\n * El icono de cada canal. Va AQUÍ y no en `canalesAviso.ts` porque aquél es el CONTRATO —el id, el\n * rótulo y qué trae dentro— y esto es pintura: que Mensajes cambie de iconos no tiene por qué\n * tocarte el título de la pantalla del canal. Mismo reparto que `ICONO_SECCION` en el perfil.\n */\nconst ICONO_CANAL: Record<CanalAviso, React.ComponentType<{ size?: number; color?: string }>> = {\n  transaction: Receipt,\n  logistics: Truck,\n};\n\n/**\n * Abre la conversación. Se pasan los datos de la tienda por la URL para que la cabecera se pinte al\n * instante —nombre y logo— sin esperar a que llegue el hilo; si alguno faltara, la pantalla del chat\n * sabe vivir sin él. `verificado` viaja como '1'/ausente porque los parámetros de navegación son\n * texto y un `false` se perdería.\n */\nexport function irAlChatDeTienda(router: { push: (r: never) => void }, c: EcomerseChat) {\n  router.push({\n    pathname: '/ecomerse-mensajes-chat',\n    params: {\n      conv: c.conversationId,\n      tienda: c.seller.businessName ?? '',\n      foto: c.seller.photoUrl ?? '',\n      telefono: c.seller.phoneContact ?? '',\n      ...(c.seller.verified ? { verificado: '1' } : {}),\n    },\n  } as never);\n}\n\nexport default function EcomerseMensajesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const sinLeer = useSinLeerMercado();\n  const [cuenta, setCuenta] = useState<EcomerseNoticeCounts | null>(null);\n  const [chats, setChats] = useState<EcomerseChat[] | null>(null);\n  const [cargando, setCargando] = useState(false);\n  /**\n   * «Aún no he preguntado» y «pregunté y falló» no son lo mismo. Sin esta bandera, entre el primer\n   * pintado y el efecto de foco —que corre después— se colaba un fotograma diciendo que había\n   * fallado antes de haber preguntado. Es el mismo fallo que se corrigió en el perfil.\n   */\n  const [intentado, setIntentado] = useState(false);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated) { setCuenta(null); setChats(null); setIntentado(true); return; }\n    setCargando(true);\n    /* `allSettled` y no `all`: son dos secciones independientes y que una se caiga no debe borrar lo\n       que la otra sí sabía. Cada sección dice por su cuenta si falló; lo que no se hace es pintar un\n       cero que nadie ha confirmado. */\n    const [avisos, tiendas] = await Promise.allSettled([\n      ecomerseApi.noticeCounts(),\n      ecomerseApi.chats(),\n    ]);\n    setCuenta(avisos.status === 'fulfilled' ? avisos.value : null);\n    setChats(tiendas.status === 'fulfilled' ? tiendas.value.chats : null);\n    setCargando(false);\n    setIntentado(true);\n  }, [isAuthenticated]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  /* La pantalla entera ha fallado sólo si no hay NADA que enseñar: una sección caída se cuenta en su\n     sitio, con sus palabras, y no se lleva por delante a la otra. */\n  const fallo = isAuthenticated && intentado && !cargando && cuenta === null && chats === null;\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable\n          onPress={() => router.back()}\n          hitSlop={12}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Volver\"\n        >\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]}>Mensajes</Text>\n        {cargando ? (\n          <ActivityIndicator size=\"small\" color={colors.primary} />\n        ) : (\n          <View style={styles.hueco} />\n        )}\n      </View>\n\n      <ScrollView contentContainerStyle={{ paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e24 }}>\n        {!isAuthenticated ? (\n          <View style={styles.cuerpo}>\n            <EmptyState\n              emoji=\"💬\"\n              titulo=\"Entra para ver tus mensajes\"\n              texto=\"Los avisos de tus pedidos, el estado de tus envíos y tus conversaciones con las tiendas van con tu cuenta.\"\n              accionLabel=\"Iniciar sesión\"\n              accionPrimaria\n              onAccion={() => router.push('/auth' as never)}\n            />\n          </View>\n        ) : fallo ? (\n          <View style={styles.cuerpo}>\n            <EmptyState\n              emoji=\"📡\"\n              titulo=\"No se pudieron cargar tus mensajes\"\n              texto=\"El servidor no contestó. Puede ser la red del aparato: vuelve a intentarlo.\"\n              accionLabel=\"Reintentar\"\n              onAccion={() => void cargar()}\n            />\n          </View>\n        ) : (\n          <>\n            {/*\n              LAS DOS FILAS DEL SISTEMA. Van sin encabezado propio: el título de la pantalla ya dice\n              «Mensajes» y meter un rótulo «Del sistema» encima sería una jerarquía que no existe\n              —los dos canales SON la pantalla—. La tarjeta las agrupa y basta.\n            */}\n            <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              {CANALES_AVISO.map((canal, i) => {\n                const Icono = ICONO_CANAL[canal.id];\n                const n = cuenta?.channels[canal.id].unread ?? 0;\n                const total = cuenta?.channels[canal.id].total ?? 0;\n                return (\n                  <Pressable\n                    key={canal.id}\n                    onPress={() => router.push(`/ecomerse-mensajes-avisos?canal=${canal.id}` as never)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={\n                      `${canal.label}. ${n > 0 ? `${n} sin leer` : 'nada sin leer'}, ${total} en total.`\n                    }\n                    style={({ pressed }) => [\n                      styles.fila,\n                      /* La primera fila no lleva raya encima: la tarjeta ya tiene su borde. */\n                      i > 0 && { borderTopWidth: trazo.fino, borderTopColor: colors.border },\n                      { opacity: pressed ? 0.6 : 1 },\n                    ]}\n                  >\n                    <View style={[styles.filaIcono, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                      <Icono size={icono.md} color={colors.primary} />\n                    </View>\n                    <View style={styles.filaTexto}>\n                      <Text style={[styles.filaTitulo, { color: colors.textPrimary }]}>{canal.label}</Text>\n                      <Text style={[styles.filaNota, { color: colors.textSecondary }]}>{canal.nota}</Text>\n                    </View>\n                    {/*\n                      El contador va en PÍLDORA y no en un círculo pegado al icono: aquí hay sitio de\n                      sobra, y un número en una fila se lee mejor que un globo diminuto. Enseña los\n                      SIN LEER, que es la única cifra que pide una acción.\n                    */}\n                    {n > 0 && (\n                      <View style={styles.pildora}>\n                        <Text style={styles.pildoraTexto}>{n > 99 ? '99+' : n}</Text>\n                      </View>\n                    )}\n                    <ChevronRight size={icono.sm} color={colors.textSecondary} />\n                  </Pressable>\n                );\n              })}\n            </View>\n\n            {/*\n              LAS CONVERSACIONES CON TIENDAS. Llevan encabezado con la cuenta porque, a diferencia de\n              los canales, esta lista crece: saber cuántas hay de un vistazo es útil y el número lo da\n              la propia lista (no hay recorte que lo desmienta: el servidor devuelve hasta 100).\n            */}\n            <View style={styles.bloque}>\n              <Text style={[styles.bloqueTitulo, { color: colors.textPrimary }]}>\n                Conversaciones con tiendas{chats && chats.length > 0 ? ` (${chats.length})` : ''}\n              </Text>\n\n              {chats === null ? (\n                <View style={[styles.aviso, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                  <Text style={[styles.avisoTexto, { color: colors.textSecondary }]}>\n                    No se pudieron cargar tus conversaciones con tiendas. Los avisos de arriba siguen ahí.\n                  </Text>\n                </View>\n              ) : chats.length === 0 ? (\n                <View style={[styles.aviso, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                  <Text style={[styles.avisoTexto, { color: colors.textSecondary }]}>\n                    Todavía no hablas con ninguna tienda. Se empieza desde la ficha de un anuncio —«Preguntar a la tienda»—\n                    o desde la página de la tienda, y la conversación aparece aquí.\n                  </Text>\n                </View>\n              ) : (\n                <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                  {chats.map((c, i) => {\n                    const nombre = c.seller.businessName ?? 'Tienda';\n                    const cuando = c.lastMessageAt ? getTimeAgo(c.lastMessageAt) : '';\n                    return (\n                      <Pressable\n                        key={c.conversationId}\n                        onPress={() => irAlChatDeTienda(router, c)}\n                        accessibilityRole=\"button\"\n                        accessibilityLabel={`${nombre}. ${c.unread > 0 ? `${c.unread} sin leer. ` : ''}${c.lastMessage ?? 'Sin mensajes'}`}\n                        style={({ pressed }) => [\n                          styles.fila,\n                          i > 0 && { borderTopWidth: trazo.fino, borderTopColor: colors.border },\n                          { opacity: pressed ? 0.6 : 1 },\n                        ]}\n                      >\n                        <AvatarTienda nombre={nombre} fotoUrl={c.seller.photoUrl} tamano={40} />\n                        <View style={styles.filaTexto}>\n                          <Text style={[styles.filaTitulo, { color: colors.textPrimary }]} numberOfLines={1}>\n                            {nombre}\n                          </Text>\n                          <Text style={[styles.filaNota, { color: colors.textSecondary }]} numberOfLines={1}>\n                            {c.lastMessage ?? 'Sin mensajes todavía'}\n                          </Text>\n                        </View>\n                        <View style={styles.derecha}>\n                          {cuando ? (\n                            <Text style={[styles.filaHora, { color: colors.textSecondary }]}>{cuando}</Text>\n                          ) : null}\n                          {c.unread > 0 && (\n                            <View style={styles.pildora}>\n                              <Text style={styles.pildoraTexto}>{c.unread > 99 ? '99+' : c.unread}</Text>\n                            </View>\n                          )}\n                        </View>\n                      </Pressable>\n                    );\n                  })}\n                </View>\n              )}\n            </View>\n          </>\n        )}\n      </ScrollView>\n\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  hueco: { width: icono.lg },\n  cuerpo: { paddingTop: espaciado.e24 },\n  tarjeta: {\n    marginHorizontal: espaciado.e16,\n    marginTop: espaciado.e16,\n    borderRadius: radios.lg,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e16,\n  },\n  bloque: { paddingHorizontal: espaciado.e16, marginTop: espaciado.e24 },\n  bloqueTitulo: { fontSize: tipografia.body, fontWeight: peso.titulo, marginBottom: espaciado.e8 },\n  aviso: {\n    borderRadius: radios.lg,\n    borderWidth: trazo.fino,\n    padding: espaciado.e16,\n  },\n  avisoTexto: { fontSize: tipografia.caption, lineHeight: 18 },\n  fila: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n    paddingVertical: espaciado.e12,\n  },\n  filaIcono: {\n    width: 36,\n    height: 36,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  filaTexto: { flex: 1 },\n  filaTitulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  filaNota: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  filaHora: { fontSize: tipografia.micro },\n  derecha: { alignItems: 'flex-end', gap: espaciado.e4 },\n  pildora: {\n    backgroundColor: brand.like,\n    borderRadius: radios.full,\n    minWidth: espaciado.e24,\n    paddingHorizontal: espaciado.e8,\n    paddingVertical: espaciado.e4 / 2,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  pildoraTexto: { color: brand.white, fontSize: tipografia.micro, fontWeight: peso.titulo },\n});\n","/**\n * AvatarTienda — el logo de una tienda, o su inicial si no tiene.\n *\n * POR QUÉ ES UN COMPONENTE. Lo pintan DOS sitios desde la Fase 4: la fila de la lista de Mensajes y\n * la cabecera de la conversación. La regla que aplica no es trivial —«si hay `photoUrl` se pinta la\n * foto, y si la imagen falla al cargar se cae a la inicial»— y escrita dos veces se desviaría: una\n * copia acabaría enseñando el marco vacío del `Image` y la otra no. Es el mismo motivo por el que\n * existe `CabeceraTienda.tsx` (una definición, dos consumidores) y el que ya costó caro con el\n * precio, cuatro sitios y tres tratamientos para el mismo dato.\n *\n * POR QUÉ NO SE PINTA LA FOTO DE LA CABECERA DE TIENDA. `CabeceraTienda` sigue con la inicial porque\n * allí el dato llega como `photoKey` —una clave del almacenamiento, sin URL—. Aquí el servidor manda\n * `photoUrl` YA RESUELTA (`EcomerseStorageService.urlDeClave`), que es justo lo que faltaba. Cuando\n * la cabecera reciba también la URL resuelta, le bastará con usar esto.\n *\n * POR QUÉ HAY ESTADO DE FALLO. Una URL rota no avisa: `Image` se queda con el hueco en blanco y la\n * fila parece no haber cargado. Con `onError` se pasa a la inicial, que siempre se puede pintar.\n */\n\nimport React, { useEffect, useState } from 'react';\nimport { Image, StyleSheet, Text, View } from 'react-native';\nimport { alpha, peso, radios, trazo, useTheme } from '@egrouteplan/ui-kit';\n\nexport function AvatarTienda({\n  nombre,\n  fotoUrl,\n  tamano = 36,\n}: {\n  nombre: string | null | undefined;\n  fotoUrl: string | null | undefined;\n  tamano?: number;\n}) {\n  const { colors } = useTheme();\n  const [rota, setRota] = useState(false);\n  /* Si la tienda cambia (la lista se recarga con otro logo), el fallo anterior no la condena. */\n  useEffect(() => { setRota(false); }, [fotoUrl]);\n\n  const letra = (nombre ?? 'T').charAt(0).toUpperCase();\n  const marco = {\n    width: tamano,\n    height: tamano,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    borderColor: colors.border,\n  } as const;\n\n  if (fotoUrl && !rota) {\n    return <Image source={{ uri: fotoUrl }} style={marco} onError={() => setRota(true)} />;\n  }\n  return (\n    <View style={[marco, styles.letra, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n      <Text style={[styles.inicial, { color: colors.primary, fontSize: tamano * 0.45 }]}>{letra}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  letra: { alignItems: 'center', justifyContent: 'center' },\n  inicial: { fontWeight: peso.titulo },\n});\n","/**\n * EcomerseOrdersScreen — Mis pedidos (compras/ventas).\n * v3 (auditoría completa): rol por TOKEN (sin ?as autorizante), toggle\n * Compras/Ventas, actividad y envío embebidos (sin N+1), estados SIEMPRE en\n * español, timeline correcto, desglose con precio ×cantidad y total naranja,\n * garantía condicional (cash = mediación; billing = garantía 7d), disputa solo\n * dentro de la ventana, review con 5 estrellas, lock contra doble tap, SafeArea.\n * Ruta: /ecomerse-orders?as=buyer|seller\n */\n\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { FlatList, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { PackageSearch, ShieldCheck, Star, Truck } from 'lucide-react-native';\nimport { alpha, EmptyState, espaciado, EstadoDinero, GhostButton, ilustracion, Precio, radios, ScreenHeader, Sheet, tipografia, type EtapaDinero, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseOrder } from '../api/ecomerse';\nimport { formatXAF } from '../utils/formatHelpers';\nimport { brand } from '@egrouteplan/ui-kit';\n/* Las cuatro secciones del comprador viven en un módulo compartido porque el PERFIL pinta las\n   mismas: rótulo, estado y contador salen de un solo sitio para que no puedan divergir. */\nimport {\n  buscarSeccion, PAGINA_VALORAR, traerEntregadosSinResena,\n  type EntregadosSinResena, type SeccionId,\n} from '../components/ecomerse/seccionesCompra';\n\nconst STATUS_LABEL: Record<string, { label: string; color: string }> = {\n  pending: { label: 'Pendiente', color: brand.warning },\n  confirmed: { label: 'Confirmado', color: brand.info },\n  in_transit: { label: 'En tránsito', color: brand.info },\n  delivered: { label: 'Entregado', color: brand.success },\n  cancelled: { label: 'Cancelado', color: brand.neutral },\n  disputed: { label: 'En disputa', color: brand.danger },\n  assigned: { label: 'Asignado', color: brand.info },\n  picked_up: { label: 'Recogido', color: brand.info },\n  paused: { label: 'Pausado', color: brand.neutral },\n};\nconst labelOf = (c: string) => STATUS_LABEL[c]?.label ?? 'Actualizado';\nconst colorOf = (c: string) => STATUS_LABEL[c]?.color ?? brand.neutral;\n\n/** Cómo se llama cada forma de pago. Antes esto era `paymentMethod === 'cash' ? 'Efectivo' : 'Billing'`:\n *  cualquier cosa que no fuera efectivo se pintaba como «Billing», así que un pedido pagado con el\n *  MONEDERO —el único cuyo dinero la plataforma retiene— se mostraba como una transferencia. */\nconst PAGO_LABEL: Record<string, string> = {\n  cash: 'Efectivo',\n  billing: 'Billing · transferencia',\n  likebook_wallet: 'Monedero',\n};\nconst pagoLabel = (m: string) => PAGO_LABEL[m] ?? 'Billing · transferencia';\n\n/** ¿El dinero de este pedido pasó por la plataforma? Solo el monedero lo hace. */\nconst esMonedero = (m: string) => m === 'likebook_wallet';\n\n/**\n * DÓNDE ESTÁ EL DINERO de este pedido, según su estado real. No es lo mismo que el estado del\n * pedido: el pedido puede estar «Entregado» y el dinero «liberado», o «En disputa» y el dinero\n * «retenido». Estas dos columnas son las que impone el backend (`ecomerse.service.ts`):\n *   · retenido  — desde que se crea hasta que se entrega o se cancela.\n *   · liberado  — al entregar (`liberarSiMonederoEc` exige status='delivered').\n *   · devuelto  — al cancelar (`devolverSiMonederoEc` exige status='cancelled').\n *   · en disputa— el cierre espera al soporte; el dinero NO se mueve mientras tanto.\n * Devuelve `null` si el pago no pasó por la plataforma: ahí no hay dinero que seguir, y decirlo\n * sería inventarse una garantía.\n */\nfunction dineroDePedido(o: EcomerseOrder): EtapaDinero | null {\n  if (!esMonedero(o.paymentMethod)) return null;\n  if (o.status === 'cancelled') return 'devuelto';\n  if (o.status === 'delivered') return 'entregado';\n  return 'retenido';\n} \n\n\ntype ModalKind = 'cancel' | 'dispute' | 'review' | null;\nconst TIMELINE = ['pending', 'confirmed', 'in_transit', 'delivered'];\n\nconst PAGE = 20;\n\n/**\n * FILTRO POR ESTADO (tanda B — patrón de `OmsPortalOrderController.list` de macrozheng/mall, que\n * filtra con `?status=` sobre cinco estados).\n *\n * Por qué: esta pantalla solo distinguía Compras/Ventas y **traía todos los pedidos sin filtrar ni\n * paginar**. Con veinte pedidos había que recorrerlos a mano.\n *\n * ── FASE 1 DEL PIE (22-sep-2026): las cuatro secciones del COMPRADOR ────────────────────────────\n * El perfil del Mercado manda aquí sus cuatro secciones —待付款 · 打包中 · 待收货 · 评价—, que son\n * las de la referencia (Pinduoduo, imágenes #4 y #6 de las capturas). Eso obliga a que la fila de\n * chips dependa del PAPEL, porque el vendedor no pregunta lo mismo que el comprador:\n *\n *   COMPRADOR   Todos · Por pagar · En preparación · En camino · Por valorar · En disputa\n *   VENDEDOR    Todos · Pendientes · En camino · Entregados · En disputa · Cancelados\n *\n * Las dos filas siguen teniendo SEIS chips, las mismas que había antes de esta fase: la del\n * comprador no crece, sólo cambia de preguntas.\n *\n * DOS DECISIONES QUE CONVIENE NO REABRIR SIN LEERLAS:\n *\n *  1. **`camino` significa cosas distintas en cada papel, así que el comprador NO lo usa.** Para el\n *     vendedor es `confirmed+in_transit` («lo tengo entre manos y va hacia el comprador») y se\n *     queda exactamente como estaba, porque la portada del comerciante lo empuja desde fuera\n *     (`/tienda/pedidos?filtro=camino`) y ese contrato no se toca. Para el comprador, en cambio,\n *     待收货 es SÓLO `in_transit`: `confirmed` ya tiene sección propia (打包中). Reutilizar el id\n *     con dos significados habría hecho que el chip mintiera en silencio, que es la peor forma de\n *     romperse, así que el comprador tiene su propio id: **`enviado`**.\n *\n *  2. **`entregado` y `cancelado` salen de la fila del comprador, y no se pierde nada.** Siguen\n *     alcanzables en «Todos», que es justo lo que hace la referencia (su 我的订单 no tiene pestaña\n *     de entregados ni de cancelados), y el comentario de arriba ya decía que «Cancelado no se\n *     busca, se encuentra». El vendedor los conserva porque su portada los empuja. «En disputa» sí\n *     se queda en las dos filas: es lo único con dinero parado y hay que poder llegar en un toque.\n */\ntype Rol = 'buyer' | 'seller';\n/** Los cuatro del comprador vienen del módulo compartido con el perfil; los demás son de esta fila. */\ntype FiltroId = SeccionId | 'todos' | 'camino' | 'entregado' | 'disputado' | 'cancelado';\n\ninterface FiltroDef {\n  id: FiltroId;\n  /** Lo que dice el chip para el comprador. */\n  label: string;\n  /** Cómo lo llama el vendedor, cuando lo llama de otra forma. */\n  labelVendedor?: string;\n  estados?: string[];\n  roles: Rol[];\n  /** `valorar` (评价): de los entregados, sólo los que todavía no tienen reseña. */\n  sinResena?: boolean;\n}\n\n/**\n * Un chip a partir de una sección COMPARTIDA. Existe para que el rótulo y el estado estén escritos\n * una sola vez: el perfil pinta las mismas cuatro secciones leyendo `SECCIONES_COMPRA`, y si aquí se\n * volvieran a escribir a mano, un día dirían cosas distintas.\n */\nconst comoFiltro = (id: SeccionId, roles: Rol[], labelVendedor?: string): FiltroDef => {\n  const s = buscarSeccion(id)!;\n  return { id: s.id, label: s.label, labelVendedor, estados: [...s.estados], sinResena: s.sinResena, roles };\n};\n\nconst FILTROS: FiltroDef[] = [\n  { id: 'todos', label: 'Todos', roles: ['buyer', 'seller'] },\n  comoFiltro('pendiente', ['buyer', 'seller'], 'Pendientes'),\n  comoFiltro('preparando', ['buyer']),\n  comoFiltro('enviado', ['buyer']),\n  comoFiltro('valorar', ['buyer']),\n  { id: 'camino', label: 'En camino', estados: ['confirmed', 'in_transit'], roles: ['seller'] },\n  { id: 'entregado', label: 'Entregados', estados: ['delivered'], roles: ['seller'] },\n  { id: 'disputado', label: 'En disputa', estados: ['disputed'], roles: ['buyer', 'seller'] },\n  { id: 'cancelado', label: 'Cancelados', estados: ['cancelled'], roles: ['seller'] },\n];\n\n/** Los chips que le tocan a un papel, en orden. */\nconst filtrosDe = (rol: Rol) => FILTROS.filter((f) => f.roles.includes(rol));\n\n/** El nombre del chip según quién mira: el comprador «Por pagar», el vendedor «Pendientes». */\nconst etiqueta = (f: FiltroDef, rol: Rol) => (rol === 'seller' ? f.labelVendedor ?? f.label : f.label);\n\n/**\n * El filtro que pide la URL, PERO sólo si le toca a este papel. Devolver el de otro papel haría\n * que el chip activo no existiera en la fila —un filtro aplicado que no se ve—, así que un id\n * ajeno se trata como si no hubiera llegado.\n */\nconst buscaFiltro = (id: string | undefined, rol: Rol) => filtrosDe(rol).find((f) => f.id === id);\n\n/**\n * El servidor filtra por UN estado, así que los grupos de varios estados se piden por separado y se\n * juntan en el cliente. Es una decisión consciente: ampliar el backend a `status IN (...)` es un\n * cambio de contrato que no compensa para un grupo de dos estados, y así el backend sigue teniendo\n * un contrato simple. Si algún día hay muchos pedidos, se cambia.\n */\nasync function pedirFiltro(role: Rol, f: FiltroId, limit: number, offset: number) {\n  const def = buscaFiltro(f, role);\n  if (!def?.estados) {\n    return ecomerseApi.myOrders(role, { limit, offset });\n  }\n  const partes = await Promise.all(def.estados.map((s) => ecomerseApi.myOrders(role, { status: s, limit, offset })));\n  const orders = partes.flatMap((p) => p.orders).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));\n  return { orders, total: partes.reduce((n, p) => n + p.total, 0), limit, offset };\n}\n\n/**\n * Props SOLO para quien la monta desde la zona del comerciante (`/tienda/pedidos`), que necesita el\n * carril de ventas ya fijado y sin el segmento. Las dos rutas comparten ESTA pantalla —no hay una\n * copia en la zona— porque duplicarla sería duplicar sus veinte arreglos de auditoría (rol por\n * token, actividad embebida, estados en español, timeline, disputa dentro de ventana, doble tap…).\n * Sin props, se comporta exactamente como antes: lee `?as`, `?filtro` y muestra el segmento.\n */\nexport interface EcomerseOrdersProps {\n  rolInicial?: 'buyer' | 'seller';\n  filtroInicial?: string;\n  ocultarSegmento?: boolean;\n}\n\nexport default function EcomerseOrdersScreen({ rolInicial, filtroInicial: filtroProp, ocultarSegmento: ocultarProp }: EcomerseOrdersProps = {}) {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { as, filtro: filtroParam, ocultarSegmento } = useLocalSearchParams<{ as?: string; filtro?: string; ocultarSegmento?: string }>();\n  /** El papel con el que arranca. Se calcula una vez y sirve también para validar el filtro. */\n  const rolDeArranque: Rol = rolInicial ?? (as === 'seller' ? 'seller' : 'buyer');\n  const [role, setRole] = useState<Rol>(rolDeArranque);\n  /*\n    Dentro de la ZONA DEL COMERCIANTE (`/tienda/pedidos`) esta pantalla llega por PROPS: rol de\n    vendedor y sin segmento. Dos razones:\n      · El segmento Compras/Ventas ahí no tiene sentido: quien está en su zona de vendedor no está\n        «en un papel», está en su tienda. Preguntárselo es ruido.\n      · Los contadores de la portada («Por enviar», «En camino»…) tienen que ABRIR ya filtrados, o\n        son números decorativos.\n    Los parámetros de URL siguen funcionando para el caso suelto (`?as=seller&filtro=pendiente`).\n  */\n  const filtroPedido = filtroProp ?? filtroParam;\n  const [filtro, setFiltro] = useState<FiltroId>(buscaFiltro(filtroPedido, rolDeArranque)?.id ?? 'todos');\n  const enZona = ocultarProp === true || ocultarSegmento === '1';\n\n  /**\n   * Cambiar de papel cambia de PREGUNTAS, no sólo de lista: «Por valorar» no existe en la fila del\n   * vendedor. Si al cambiar de segmento se quedara puesto un filtro del otro papel, la lista saldría\n   * filtrada por algo que no se ve en pantalla —el mismo fallo que un contador que no filtra—, así\n   * que un filtro que no le toca al papel nuevo vuelve a «Todos».\n   */\n  const cambiarRol = (r: Rol) => {\n    setRole(r);\n    setFiltro((f) => (buscaFiltro(f, r) ? f : 'todos'));\n  };\n\n  /**\n   * Si el filtro llega por parámetro DESPUÉS de montada (los contadores de la portada empujan a esta\n   * misma ruta con `?filtro=`), el `useState` de arriba ya no lo recogería: el estado inicial solo se\n   * evalúa al montar. Sin esto, pulsar «Por enviar» estando ya en Pedidos no cambiaría nada —un\n   * contador que no filtra es un número decorativo, justo lo que el plan quiere evitar.\n   * Se comprueba contra el papel: un filtro del comprador llegado por URL no activa nada en ventas.\n   */\n  useEffect(() => {\n    const d = buscaFiltro(filtroPedido, role);\n    if (d) setFiltro(d.id);\n  }, [filtroPedido, role]);\n\n  const [orders, setOrders] = useState<EcomerseOrder[]>([]);\n  const [total, setTotal] = useState(0);\n  /** Pedidos por estado, para los contadores de los chips. Una sola consulta agrupada. */\n  const [counts, setCounts] = useState<Record<string, number>>({});\n  const [totalTodos, setTotalTodos] = useState(0);\n  /**\n   * Los entregados sin reseña (评价). Se guardan los PEDIDOS y no sólo el número porque el mismo\n   * viaje sirve para las dos cosas: el contador del chip y la lista cuando ese es el filtro activo.\n   */\n  const [sinResena, setSinResena] = useState<EntregadosSinResena | null>(null);\n  const [cargandoMas, setCargandoMas] = useState(false);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const busyRef = useRef(false);\n  const [modal, setModal] = useState<ModalKind>(null);\n  const [modalOrder, setModalOrder] = useState<EcomerseOrder | null>(null);\n  const [modalText, setModalText] = useState('');\n  const [rating, setRating] = useState(0);\n  const [modalBusy, setModalBusy] = useState(false);\n  const modalBusyRef = useRef(false);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      /* LAS TRES PREGUNTAS VAN A LA VEZ. Antes eran dos llamadas encadenadas (lista y contadores);\n         ahora son tres en paralelo, y el «Por valorar» se mide UNA sola vez por carga porque sirve\n         para dos cosas: el contador del chip y —si ese es el filtro activo— la propia lista.\n         Sólo lo pide el comprador: es el único que valora y el único con esa sección. */\n      const [r, c, v] = await Promise.all([\n        filtro === 'valorar' ? Promise.resolve(null) : pedirFiltro(role, filtro, PAGE, 0),\n        ecomerseApi.orderCounts(role),\n        role === 'buyer' ? traerEntregadosSinResena() : Promise.resolve(null),\n      ]);\n      setSinResena(v);\n      /* Con «Por valorar» como filtro activo, la lista ES lo que ya se trajo para contar. NO pagina:\n         `myOrders` acota a 100 por llamada y filtrar en el cliente DESPUÉS de paginar descuadraría\n         el «quedan N» del botón de ver más. Por eso el total es lo que se ve, y el botón no sale. */\n      if (filtro === 'valorar') {\n        setOrders(v?.orders ?? []);\n        setTotal(v?.orders.length ?? 0);\n      } else {\n        setOrders(r!.orders);\n        setTotal(r!.total);\n      }\n      /* Los contadores de los chips se refrescan con la lista: si un pedido cambia de estado, el\n         número tiene que cambiar a la vez, o las pestañas mentirían. */\n      setCounts(c.porEstado);\n      setTotalTodos(c.total);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar tus pedidos. Revisa la conexión.');\n    } finally {\n      setLoading(false);\n    }\n  }, [role, filtro]);\n  useEffect(() => { load(); }, [load]);\n\n  /**\n   * Una página del filtro activo, por el MISMO camino que la carga inicial. Existe porque\n   * «Por valorar» no lo filtra el servidor —`reviewed` no es un estado— y ir por `pedirFiltro`\n   * traería entregados ya valorados: la lista se contradiría con su propio contador, que es la\n   * forma más silenciosa de mentir que tiene una pantalla.\n   */\n  const traerPagina = async (offset: number) => {\n    if (filtro === 'valorar') {\n      const v = await traerEntregadosSinResena();\n      setSinResena(v);\n      return { orders: v.orders, total: v.orders.length };\n    }\n    const r = await pedirFiltro(role, filtro, PAGE, offset);\n    return { orders: r.orders, total: r.total };\n  };\n\n  /** Trae la página siguiente. El botón solo aparece si el servidor dice que hay más de los que hay. */\n  const cargarMas = async () => {\n    if (cargandoMas) return;\n    setCargandoMas(true);\n    try {\n      const p = await traerPagina(orders.length);\n      setOrders((prev) => [...prev, ...p.orders]);\n      setTotal(p.total);\n    } catch { /* se queda como estaba; el botón sigue ahí para reintentar */ }\n    finally { setCargandoMas(false); }\n  };\n\n  const refresh = async () => {\n    setRefreshing(true);\n    try {\n      const p = await traerPagina(0);\n      setOrders(p.orders);\n      setTotal(p.total);\n    } catch { /* noop */ } finally { setRefreshing(false); }\n  };\n\n  const act = async (id: string, status: string) => {\n    if (busyRef.current) return;\n    busyRef.current = true;\n    try {\n      const r = await ecomerseApi.updateStatus(id, status);\n      Alert.alert('Pedido actualizado', r.message);\n      await load();\n    } catch (e) { Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo actualizar'); }\n    finally { busyRef.current = false; }\n  };\n\n  const confirmAct = (id: string, status: string, title: string, msg: string) => {\n    Alert.alert(title, msg, [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: title, onPress: () => act(id, status) },\n    ]);\n  };\n\n  const advanceShipment = async (id: string, status: string) => {\n    if (busyRef.current) return;\n    busyRef.current = true;\n    try { const r = await ecomerseApi.updateShipment(id, status); Alert.alert('Envío', r.message); await load(); }\n    catch (e) { Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo actualizar'); }\n    finally { busyRef.current = false; }\n  };\n\n  const openModal = (kind: Exclude<ModalKind, null>, o: EcomerseOrder) => {\n    setModal(kind);\n    setModalOrder(o);\n    setModalText('');\n    setRating(0);\n  };\n\n  const sendModal = async () => {\n    if (modalBusyRef.current || !modalOrder || !modal) return;\n    if (modal === 'cancel' && !modalText.trim()) { Alert.alert('Motivo', 'Escribe un motivo (breve) para cancelar.'); return; }\n    if (modal === 'dispute' && modalText.trim().length < 10) { Alert.alert('Motivo', 'Describe el problema con al menos 10 caracteres.'); return; }\n    if (modal === 'review' && rating < 1) { Alert.alert('Valoración', 'Toca de 1 a 5 estrellas.'); return; }\n    modalBusyRef.current = true;\n    setModalBusy(true);\n    try {\n      if (modal === 'cancel') {\n        const r = await ecomerseApi.cancelOrder(modalOrder.id, modalText.trim() || 'Sin motivo');\n        Alert.alert('Cancelado', r.message);\n      } else if (modal === 'dispute') {\n        const r = await ecomerseApi.openDispute(modalOrder.id, modalText.trim());\n        Alert.alert('Disputa abierta', r.message);\n      } else {\n        const r = await ecomerseApi.review(modalOrder.id, rating);\n        Alert.alert('Valoración', r.message);\n      }\n      setModal(null);\n      await load();\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo completar');\n    } finally {\n      modalBusyRef.current = false;\n      setModalBusy(false);\n    }\n  };\n\n  const s = styles(colors);\n\n  return (\n    <View style={[stylesRoot(colors).root, { paddingTop: insets.top }]}>\n      <ScreenHeader titulo={enZona ? 'Pedidos' : 'Mis pedidos'} alVolver={() => router.back()} />\n\n      {/* Toggle Compras / Ventas — se oculta dentro de la zona del comerciante (`ocultarSegmento=1`) */}\n      {!enZona && (\n        <View style={s.seg}>\n          <Pressable onPress={() => cambiarRol('buyer')} accessibilityRole=\"tab\" accessibilityState={{ selected: role === 'buyer' }}\n            style={[s.segBtn, role === 'buyer' && { backgroundColor: colors.primary }]}>\n            <Text style={[s.segText, { color: role === 'buyer' ? brand.white : colors.textPrimary }]}>Compras</Text>\n          </Pressable>\n          <Pressable onPress={() => cambiarRol('seller')} accessibilityRole=\"tab\" accessibilityState={{ selected: role === 'seller' }}\n            style={[s.segBtn, role === 'seller' && { backgroundColor: colors.primary }]}>\n            <Text style={[s.segText, { color: role === 'seller' ? brand.white : colors.textPrimary }]}>Ventas</Text>\n          </Pressable>\n        </View>\n      )}\n\n      {/* FILTRO POR ESTADO (tanda B). Va justo debajo del toggle Compras/Ventas porque son el mismo\n          tipo de decisión («qué parte de mis pedidos quiero ver»), en dos niveles: primero de quién\n          soy, después en qué punto está. Los chips llevan el número de pedidos en cada estado, que\n          es lo que evita abrir pestañas a ciegas.\n\n          La FILA DEPENDE DEL PAPEL (fase 1 del pie): el comprador pregunta por 待付款 · 打包中 ·\n          待收货 · 评价 y el vendedor por su ciclo de trabajo. Ver la cabecera de `FILTROS`. */}\n      <ScrollView\n        horizontal\n        showsHorizontalScrollIndicator={false}\n        style={s.filtros}\n        contentContainerStyle={s.filtrosContenido}\n      >\n        {filtrosDe(role).map((f) => {\n          const on = filtro === f.id;\n          /* El contador de cada grupo. «Por valorar» no sale de `counts` —el servidor agrupa por\n             ESTADO y «sin reseña» no es un estado— sino del viaje propio, y puede venir saturado. */\n          const n = f.sinResena ? sinResena?.n ?? 0 : f.estados ? f.estados.reduce((a, e) => a + (counts[e] ?? 0), 0) : totalTodos;\n          const saturado = f.sinResena && sinResena?.truncado && n > 0;\n          const cifra = n ? ` ${n}${saturado ? '+' : ''}` : '';\n          const nombre = etiqueta(f, role);\n          return (\n            <Pressable\n              key={f.id}\n              onPress={() => setFiltro(f.id)}\n              accessibilityRole=\"tab\"\n              accessibilityState={{ selected: on }}\n              accessibilityLabel={`${nombre}${n ? `, ${saturado ? `más de ${n}` : n} pedidos` : ''}`}\n              style={[s.filtroChip, { backgroundColor: on ? colors.primary : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n            >\n              {/* `numberOfLines={1}`: sin esto, «Pendientes 8» partía en dos líneas y aplastaba el chip. */}\n              <Text numberOfLines={1} style={[s.filtroText, { color: on ? brand.white : colors.textPrimary }]}>\n                {nombre}{cifra}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </ScrollView>\n\n      {/*\n        LISTA VIRTUALIZADA (auditoría de diseño, D-04/D-21): antes un ScrollView con .map(), que\n        pinta y mantiene TODOS los pedidos en memoria. Un vendedor con historial largo se quedaba\n        con la pantalla atascada.\n      */}\n      <FlatList\n        data={orders}\n        keyExtractor={(o) => o.id}\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }}\n        showsVerticalScrollIndicator={false}\n        refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} />}\n        initialNumToRender={8}\n        windowSize={7}\n        removeClippedSubviews\n        ListFooterComponent={\n          /* PAGINACIÓN (tanda B): antes se traían TODOS los pedidos de golpe. Ahora vienen de 20 en\n             20 y el botón solo aparece si el servidor dice que hay más de los que ya se ven. */\n          orders.length < total ? (\n            <Pressable\n              onPress={cargarMas}\n              disabled={cargandoMas}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Cargar más pedidos, quedan ${total - orders.length}`}\n              style={[s.masBtn, { borderColor: colors.border }]}\n            >\n              <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.primary }}>\n                {cargandoMas ? 'Cargando…' : `Ver más (quedan ${total - orders.length})`}\n              </Text>\n            </Pressable>\n          ) : null\n        }\n        ListHeaderComponent={\n          <>\n            {error && (\n              <View style={{ alignItems: 'center', paddingVertical: 40, paddingHorizontal: espaciado.e32 }}>\n                <Text style={{ fontSize: ilustracion.md, marginBottom: espaciado.e8 }}>📡</Text>\n                <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>Algo salió mal</Text>\n                <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 }}>{error}</Text>\n                <Pressable onPress={load} style={{ marginTop: espaciado.e18, backgroundColor: colors.primary, paddingHorizontal: espaciado.e20, paddingVertical: espaciado.e11, borderRadius: radios.full }}>\n                  <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n                </Pressable>\n              </View>\n            )}\n\n            {!error && loading && orders.length === 0 && (\n              <View style={{ gap: espaciado.e12 }}>\n                {[0, 1].map((i) => <View key={i} style={{ height: 140, borderRadius: radios.lg, backgroundColor: colors.border, opacity: 0.5 }} />)}\n              </View>\n            )}\n          </>\n        }\n        ListEmptyComponent={\n          !error && !loading ? (\n            totalTodos > 0 && filtro !== 'todos' ? (\n              /* HAY pedidos, pero ninguno en ESTE grupo. Decir «Todavía no has comprado» aquí sería\n                 sencillamente falso: el comprador ha comprado, lo que pasa es que nada está en\n                 «Por valorar». Y sin salida, un filtro vacío parece una pantalla rota. */\n              <EmptyState\n                emoji=\"🔎\"\n                titulo={`Nada en «${etiqueta(buscaFiltro(filtro, role)!, role)}»`}\n                texto={`Tienes ${totalTodos} ${totalTodos === 1 ? 'pedido' : 'pedidos'}, pero ninguno en este grupo.`}\n                accionLabel=\"Ver todos\"\n                onAccion={() => setFiltro('todos')}\n              />\n            ) : (\n              <EmptyState\n                emoji=\"📦\"\n                titulo={role === 'seller' ? 'Aún no tienes ventas' : 'Todavía no has comprado'}\n                texto={role === 'seller'\n                  ? 'Cuando alguien compre en tu tienda, el pedido aparecerá aquí con su entrega y su cobro.'\n                  : 'Explora el mercado: si pagas por la app, el dinero queda en garantía hasta que recibas.'}\n                accionLabel={role === 'seller' ? 'Ver mis anuncios' : 'Ir al mercado'}\n                /* El rótulo decía «Ver mis productos» y el destino era `/ecomerse`, el MERCADO del\n                   comprador: el botón prometía una cosa y hacía otra. Para el vendedor, sus productos\n                   están en «Anuncios» de su zona. */\n                onAccion={() => router.push((role === 'seller' ? '/tienda/anuncios' : '/ecomerse') as any)}\n              />\n            )\n          ) : null\n        }\n        renderItem={({ item: o }) => {\n          const events = o.events ?? [];\n          const ship = o.shipment ?? null;\n          const multi = (o.items?.length ?? 0) > 1;\n          /* El único artículo, cuando el pedido es de uno solo. Aparte para poder estrechar su tipo:\n             si el título enseña el suyo, la combinación de debajo tiene que ser la MISMA línea. */\n          const unico = multi ? undefined : o.items?.[0];\n          const warrantyMs = o.warrantyExpiresAt ? Date.parse(o.warrantyExpiresAt) : NaN;\n          const warrantyOk = Number.isFinite(warrantyMs) && warrantyMs > Date.now();\n          const canDispute = role === 'buyer' && o.status === 'delivered' && (o.openDisputes ?? 0) === 0 && warrantyOk;\n          const canReview = role === 'buyer' && o.status === 'delivered' && !o.reviewed;\n          const canCancel = ['pending', 'confirmed'].includes(o.status);\n          const closed = o.status === 'cancelled' || o.status === 'disputed';\n          const timelineIdx = TIMELINE.indexOf(o.status);\n          return (\n            <View key={o.id} style={{ backgroundColor: colors.surface, borderRadius: radios.lg, padding: espaciado.e14, marginBottom: espaciado.e12, borderWidth: 1, borderColor: colors.border }}>\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n                <View style={{ flex: 1 }}>\n                  <Text numberOfLines={1} style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>\n                    {multi ? `${o.items?.length} artículos` : (unico?.title ?? 'Pedido')}\n                  </Text>\n                  {/* QUÉ COMBINACIÓN SE COMPRÓ. El servidor la congela con el pedido y sin pintarla el\n                      comprador no sabía qué eligió ni el vendedor qué servir: «Camisa» no dice si era\n                      la roja o la azul. Se pinta como en los pedidos de Life Book (`variantSnapshot`:\n                      línea de apoyo, `caption`, `textSecondary`), para que la misma información se lea\n                      igual en los dos mercados. */}\n                  {unico?.variantName ? (\n                    <Text numberOfLines={1} style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>\n                      {unico.variantName}\n                    </Text>\n                  ) : null}\n                  {multi && (o.items ?? []).slice(0, 3).map((it) => (\n                    /* La clave lleva la combinación: con la Fase 4 el MISMO producto puede ir dos veces\n                       en un pedido (la roja M y la roja L son dos líneas), y con solo el `productId`\n                       las dos se pintaban con la misma clave. */\n                    <Text key={`${it.productId}-${it.variantId ?? ''}`} numberOfLines={1} style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>\n                      • {it.title}{it.variantName ? ` (${it.variantName})` : ''} ×{it.qty} · {formatXAF(it.price * it.qty)}\n                    </Text>\n                  ))}\n                  {multi && (o.items?.length ?? 0) > 3 && (\n                    <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>… y {(o.items?.length ?? 0) - 3} más</Text>\n                  )}\n                </View>\n                <View style={{ backgroundColor: alpha(colorOf(o.status), 0.12), paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: radios.sm }}>\n                  <Text style={{ fontSize: tipografia.micro, fontWeight: '800', color: colorOf(o.status) }}>{labelOf(o.status)}</Text>\n                </View>\n              </View>\n\n              {/* Desglose: total naranja + datos del servicio */}\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: espaciado.e6 }}>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>\n                    {role === 'buyer' ? `Vendedor: ${o.sellerName ?? '—'}` : `Comprador: #${(o.buyerId || '').slice(-4)}`} · {pagoLabel(o.paymentMethod)}\n                  </Text>\n                  {o.deliveryAddress ? <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>📍 {o.deliveryAddress}</Text> : null}\n                  {o.note ? <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>📝 {o.note}</Text> : null}\n                </View>\n                <View style={{ alignItems: 'flex-end' }}>\n                  {o.logisticsFeeXaf > 0 && <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>envío {formatXAF(o.logisticsFeeXaf)}</Text>}\n                  {/* El total es una FIGURA: manda la primitiva, que le pinta la unidad reducida y no\n                      puede partirse. Antes era un `<Text>` a `subtitle` (16) + 900, un tamaño que no\n                      era de ninguna regla sino de esta pantalla. Con el papel de «total de un\n                      resumen» pasa a `lg` (20), que es el escalón que la escala tenía **sin usar**\n                      para exactamente esto. Lo que no cambia: el peso (900) y el color (naranja).\n                      El envío de arriba se queda como frase: va dentro de un texto («envío 300 XAF»),\n                      y ahí el que manda es el formateador, no el componente. */}\n                  <Precio valor={o.totalXaf} tamano=\"lg\" />\n                </View>\n              </View>\n\n              {/* Timeline (solo si no está cerrado) */}\n              {!closed && (\n                <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: espaciado.e14 }}>\n                  {TIMELINE.map((stName, i) => (\n                    <React.Fragment key={stName}>\n                      {i > 0 && <View style={{ flex: 1, height: 2, backgroundColor: i <= timelineIdx ? brand.secondary : colors.border }} />}\n                      <View style={{ width: 10, height: 10, borderRadius: radios.full, backgroundColor: i <= timelineIdx ? brand.secondary : colors.border }} />\n                    </React.Fragment>\n                  ))}\n                </View>\n              )}\n\n              {/* DÓNDE ESTÁ EL DINERO del pedido (tanda 1 «el dinero se ve»).\n                  Antes esta pantalla trataba cualquier pago que no fuera efectivo como «Billing», así\n                  que un pedido pagado con el MONEDERO —el único cuyo dinero retiene la plataforma—\n                  se anunciaba como «Pago en efectivo: sin reembolso por la app». Eso era falso dos\n                  veces (no era efectivo, y sí hay devolución: `devolverSiMonederoEc`). Ahora:\n                    · monedero → se enseña en qué punto está el dinero, con su estado real.\n                    · efectivo → el aviso dice la verdad: no pasa por la app.\n                    · billing → mantiene la garantía de 7 días que ya mostraba. */}\n              <View style={{ marginTop: espaciado.e10 }}>\n                {esMonedero(o.paymentMethod) ? (\n                  <EstadoDinero\n                    activo={dineroDePedido(o) ?? 'retenido'}\n                    notaGarantia={o.status === 'delivered'\n                      ? (warrantyOk\n                          ? `Garantía de 7 días hasta el ${new Date(o.warrantyExpiresAt!).toLocaleDateString('es')}.`\n                          : 'La garantía de 7 días de este pedido ha vencido.')\n                      : undefined}\n                  />\n                ) : o.status === 'delivered' ? (\n                  <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: alpha(o.paymentMethod === 'billing' ? brand.success : brand.warning, 0.08), borderRadius: radios.sm, padding: espaciado.e8 }}>\n                    <ShieldCheck size={14} color={o.paymentMethod === 'billing' ? brand.success : brand.warning} />\n                    <Text style={{ fontSize: tipografia.micro, color: o.paymentMethod === 'billing' ? brand.success : brand.warning, fontWeight: '700', marginLeft: espaciado.e6, flex: 1 }}>\n                      {o.paymentMethod === 'billing'\n                        ? (warrantyOk ? `Garantía de 7 días hasta ${new Date(o.warrantyExpiresAt!).toLocaleDateString('es')}` : 'Garantía vencida.')\n                        : 'Pago en efectivo: EG Route Plan media si hay problema (sin reembolso por la app).'}\n                    </Text>\n                  </View>\n                ) : null}\n              </View>\n\n              {/* Seguimiento de envío (agente) */}\n              {ship && (\n                <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: alpha(colors.primary, 0.08), borderRadius: radios.sm, padding: espaciado.e8, marginTop: espaciado.e10, flexWrap: 'wrap', gap: espaciado.e6 }}>\n                  <Truck size={14} color={colors.primary} />\n                  <Text style={{ fontSize: tipografia.micro, color: colors.primary, fontWeight: '700', flex: 1 }}>\n                    Envío {ship.trackingCode} · {ship.agentName ?? 'agente'} · {labelOf(ship.status)}\n                  </Text>\n                  {role === 'seller' && (\n                    <>\n                      {ship.status === 'assigned' && <GhostButton title=\"Recogido\" onPress={() => advanceShipment(o.id, 'picked_up')} />}\n                      {ship.status === 'picked_up' && <GhostButton title=\"En tránsito\" onPress={() => advanceShipment(o.id, 'in_transit')} />}\n                      {ship.status === 'in_transit' && <GhostButton title=\"Entregado\" onPress={() => advanceShipment(o.id, 'delivered')} />}\n                    </>\n                  )}\n                </View>\n              )}\n\n              {/* Actividad (acotada) */}\n              {events.length > 0 && (\n                <View style={{ marginTop: espaciado.e10, borderTopWidth: 1, borderTopColor: colors.border, paddingTop: espaciado.e8 }}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginBottom: espaciado.e4 }}>\n                    <PackageSearch size={12} color={colors.textSecondary} />\n                    <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, fontWeight: '700' }}>ACTIVIDAD</Text>\n                  </View>\n                  {events.slice(0, 6).map((ev, i) => (\n                    <Text key={i} style={{ fontSize: tipografia.micro, color: colors.textSecondary, lineHeight: 16 }}>\n                      • {new Date(ev.createdAt).toLocaleString('es', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })} — {labelOf(ev.toStatus)}\n                      {ev.note ? ` (${ev.note})` : ''}\n                    </Text>\n                  ))}\n                  {events.length > 6 && <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>… y {events.length - 6} eventos más</Text>}\n                </View>\n              )}\n\n              {/* Acciones */}\n              <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12, flexWrap: 'wrap' }}>\n                {role === 'seller' && o.status === 'pending' && (\n                  <GhostButton title=\"Confirmar\" onPress={() => confirmAct(o.id, 'confirmed', 'Confirmar pedido', 'Confirmas que aceptas el pedido. El comprador recibirá el aviso.')} />\n                )}\n                {role === 'seller' && o.status === 'confirmed' && o.fulfillmentType !== 'agent' && (\n                  <GhostButton title=\"En tránsito\" onPress={() => confirmAct(o.id, 'in_transit', 'Iniciar envío', 'Confirma que el pedido va en camino al comprador.')} />\n                )}\n                {role === 'seller' && o.status === 'in_transit' && o.fulfillmentType !== 'agent' && (\n                  <GhostButton title=\"Marcar entregado\" onPress={() => confirmAct(o.id, 'delivered', 'Marcar entregado', 'Confirma que entregaste el pedido. Se activa la garantía de 7 días.')} />\n                )}\n                {role === 'buyer' && o.status === 'in_transit' && o.fulfillmentType !== 'agent' && (\n                  <GhostButton title=\"Confirmar entrega\" onPress={() => confirmAct(o.id, 'delivered', 'Confirmar entrega', 'Confirma que recibiste el pedido. Se activa la garantía de 7 días.')} />\n                )}\n                {canCancel && <GhostButton title=\"Cancelar\" onPress={() => openModal('cancel', o)} />}\n                {canDispute && <GhostButton title=\"Disputa\" onPress={() => openModal('dispute', o)} />}\n                {canReview && <GhostButton title=\"Valorar\" onPress={() => openModal('review', o)} />}\n                {o.status === 'disputed' && <Text style={{ fontSize: tipografia.caption, color: colors.danger, fontWeight: '700' }}>En revisión por el administrador</Text>}\n              </View>\n            </View>\n          );\n        }}\n      />\n\n      {/*\n        Cancelar / Disputa / Valorar. Era un `<Modal>` escrito a mano que ya hacía justo lo que\n        hace el `Sheet` del kit —cerrar al tocar fuera, respetar el botón de atrás, atrapar el\n        foco y NO cerrarse mientras trabaja—, pero a su manera. Con el `Sheet` se hereda.\n      */}\n      <Sheet\n        visible={modal !== null}\n        position=\"bottom\"\n        busy={modalBusy}\n        title={modal === 'cancel' ? 'Cancelar pedido' : modal === 'dispute' ? 'Abrir disputa' : 'Valorar compra'}\n        subtitle={modal === 'cancel'\n          ? `El stock se restaura.${modalOrder?.paymentMethod === 'billing' ? ' Si pagaste por Billing, el admin revisará el reembolso.' : ''}`\n          : modal === 'dispute' ? 'Describe el problema (mínimo 10 caracteres).' : '¿Cómo fue tu experiencia?'}\n        onClose={() => setModal(null)}\n      >\n        {modal === 'review' ? (\n          <View style={{ flexDirection: 'row', gap: espaciado.e8, justifyContent: 'center', paddingVertical: espaciado.e8 }}>\n            {[1, 2, 3, 4, 5].map((n) => (\n              <Pressable key={n} onPress={() => setRating(n)} accessibilityRole=\"button\" accessibilityLabel={`${n} estrellas`} hitSlop={8}>\n                <Star size={34} color={n <= rating ? brand.warning : colors.border} fill={n <= rating ? brand.warning : 'transparent'} />\n              </Pressable>\n            ))}\n          </View>\n        ) : (\n          <TextInput\n            value={modalText}\n            onChangeText={setModalText}\n            placeholder=\"Escribe aquí…\"\n            placeholderTextColor={colors.textSecondary}\n            multiline\n            accessibilityLabel={modal === 'cancel' ? 'Motivo de cancelación' : 'Motivo de la disputa'}\n            style={[s.modalInput, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n          />\n        )}\n\n        <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n          <Pressable onPress={() => { if (!modalBusyRef.current) setModal(null); }} style={[s.modalBtn, { borderWidth: 1, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\n          </Pressable>\n          <Pressable onPress={sendModal} disabled={modalBusy} accessibilityRole=\"button\" accessibilityLabel=\"Enviar\"\n            style={[s.modalBtn, { backgroundColor: modal === 'review' ? colors.primary : colors.danger, flex: 1, opacity: modalBusy ? 0.6 : 1 }]}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>{modalBusy ? 'Enviando…' : 'Enviar'}</Text>\n          </Pressable>\n\n            </View>\n      </Sheet>\n    </View>\n  );\n}\n\nconst stylesRoot = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({ root: { flex: 1, backgroundColor: c.background } });\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  seg: { flexDirection: 'row', marginHorizontal: espaciado.e16, marginTop: espaciado.e12, backgroundColor: c.surface, borderRadius: radios.md, borderWidth: 1, borderColor: c.border, padding: espaciado.e3 },\n  segBtn: { flex: 1, alignItems: 'center', paddingVertical: espaciado.e8, borderRadius: radios.sm },\n  segText: { fontSize: tipografia.body, fontWeight: '800' },\n  /**\n   * FILA DE CHIPS DE ESTADO (tanda B; corregida DOS veces el 18/09 tras verla en el aparato).\n   *\n   * Fallo 1 — los chips se aplastaban en «Ventas»: al añadir el contador («Pendientes 8») la fila\n   * pasa de ~1000 a ~1340 px de ancho y el carril **comprimía** en vez de desplazar. Medido: el chip\n   * caía de 105x57 a 71x24 px y el texto partía en dos líneas. Se arregló con `numberOfLines={1}`.\n   *\n   * Fallo 2 — al arreglarlo, la fila CRECIÓ (71 → 114 px de chip) y todo el bloque bajó ~55 px, con\n   * un `minHeight` que dejaba el alto a merced del contenido. Un bloque que cambia de alto porque\n   * cambia su texto es un bloque inestable, y se notaba al moverse por la pantalla.\n   *\n   * El arreglo definitivo es **rigidez deliberada**: alto FIJO en el carril, alto FIJO en cada chip\n   * (36 px, el mismo para todos, con o sin contador) y el texto en una línea. Así la fila ocupa\n   * siempre exactamente lo mismo y no se mueve ni al filtrar, ni al cambiar de pestaña, ni cuando\n   * llegan datos. El texto (12 px) cabe de sobra: 36 px es más del doble.\n   */\n  filtros: { height: 56, flexGrow: 0 },\n  filtrosContenido: { gap: espaciado.e8, paddingHorizontal: espaciado.e16, alignItems: 'center' },\n  filtroChip: { height: 36, justifyContent: 'center', paddingHorizontal: espaciado.e12, borderRadius: radios.full, borderWidth: 1 },\n  filtroText: { fontSize: tipografia.caption, fontWeight: '700' },\n  /** Botón de «ver más»: solo aparece si quedan pedidos. */\n  masBtn: { marginTop: espaciado.e14, marginHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderRadius: radios.md, borderWidth: 1, alignItems: 'center' },\n  modalInput: { borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, minHeight: 88, textAlignVertical: 'top', fontSize: tipografia.body },\n  modalBtn: { paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e16, borderRadius: radios.md, alignItems: 'center' },\n});\n","/**\n * LAS CUATRO SECCIONES DEL COMPRADOR, EN UN SOLO SITIO.\n *\n * POR QUÉ EXISTE ESTE FICHERO. La Fase 1 del pie pide que el perfil muestre 我的订单 con sus cuatro\n * secciones —待付款 · 打包中 · 待收货 · 评价, tal como salen en la referencia (Pinduoduo, imágenes #4\n * y #6)— y que cada una ABRA la lista ya filtrada. Eso son dos sitios preguntando lo mismo: el\n * perfil, que pinta el nombre y el número, y `ecomerse-orders.tsx`, que traduce ese nombre a una\n * consulta. Si cada uno guardara su copia del rótulo o del estado, un día el perfil diría «En\n * preparación» y el chip filtraría por otra cosa —y un contador que no filtra lo que promete es un\n * número decorativo, que es justo lo que el proyecto no quiere.\n *\n * POR QUÉ NO HAY TRADUCCIÓN AQUÍ. El id (`pendiente`, `preparando`…) es el que viaja en la URL\n * (`/ecomerse-orders?filtro=preparando`) y el rótulo es el que se lee. Los nombres van en español,\n * como el resto de la app: la app es para Guinea Ecuatorial y el chino de la referencia es la\n * referencia, no el texto que se pinta.\n *\n * LO QUE ESTE FICHERO **NO** ES. No añade ningún endpoint ni ningún estado: los cuatro salen de la\n * máquina de estados que ya existía (`pending / confirmed / in_transit / delivered`). En particular\n * 打包中 («preparando el paquete») NO es un estado nuevo: es `confirmed`, que significa «el vendedor\n * aceptó el pedido» — decisión cerrada en `MERCADO-PIE-PLAN.md` §5.d, y por eso el rótulo se\n * reinterpreta sin tocar el motor del pedido, que ya está probado de punta a punta.\n */\n\nimport { ecomerseApi, type EcomerseOrder } from '../../api/ecomerse';\n\nexport interface SeccionCompra {\n  /** El id que viaja en `/ecomerse-orders?filtro=`. NO se renombra: hay enlaces guardados. */\n  id: 'pendiente' | 'preparando' | 'enviado' | 'valorar';\n  /** Lo que se lee. */\n  label: string;\n  /** Los estados del pedido que caen dentro. */\n  estados: readonly string[];\n  /** `valorar` (评价): de los entregados, sólo los que todavía NO tienen reseña. */\n  sinResena?: boolean;\n}\n\n/**\n * El orden NO es alfabético ni casual: es el del ciclo de vida del pedido visto por quien compra\n * —pago lo que debo, el vendedor lo prepara, va en camino, y cuando llega lo valoro—, que es el\n * mismo orden que usa la referencia.\n */\nexport const SECCIONES_COMPRA: readonly SeccionCompra[] = [\n  { id: 'pendiente', label: 'Por pagar', estados: ['pending'] },\n  { id: 'preparando', label: 'En preparación', estados: ['confirmed'] },\n  { id: 'enviado', label: 'En camino', estados: ['in_transit'] },\n  { id: 'valorar', label: 'Por valorar', estados: ['delivered'], sinResena: true },\n] as const;\n\nexport type SeccionId = SeccionCompra['id'];\n\nexport const buscarSeccion = (id: string) => SECCIONES_COMPRA.find((s) => s.id === id);\n\n/**\n * Tope real de una llamada a `myOrders`: el servicio acota en el servidor con\n * `Math.min(Math.max(Number(limit) || 30, 1), 100)`. Este número es el techo de UNA petición, y es\n * lo que hace que el recuento de abajo pueda venir saturado.\n */\nexport const PAGINA_VALORAR = 100;\n\nexport interface EntregadosSinResena {\n  orders: EcomerseOrder[];\n  /** Cuántos entregados siguen sin reseña (el «评价» de la referencia). */\n  n: number;\n  /** `true` si hay más entregados de los que caben en una página: `n` es un SUELO, no el total. */\n  truncado: boolean;\n}\n\n/**\n * Los entregados que siguen SIN reseña: el 评价 (待评价) de la referencia.\n *\n * POR QUÉ SE CUENTA EN EL CLIENTE. El contador del servidor (`orders/counts`) agrupa por ESTADO, y\n * «sin reseña» no es un estado: es la ausencia de fila en `wallet.ecomerse_reviews`. Añadirlo al\n * backend era cambiar el contrato en una fase que se llama «sin backend nuevo», así que se cuenta\n * aquí sobre los entregados, que sí traen `reviewed` pedido a pedido.\n *\n * LO QUE ESTO NO ES — y por eso devuelve `truncado`. Con más de 100 entregados el número sería un\n * SUELO, no el total, y quien lo pinta tiene que decirlo (`99+`). Un «37» que parece exacto y no lo\n * es hace más daño que un «99+» honesto; es la misma regla que el KPI del comerciante, que avisa\n * cuando calcula sobre una página.\n *\n * CUÁNDO HABRÁ QUE CAMBIARLO. Cuando un comprador pase de 100 pedidos entregados, esto pide un\n * contador en el backend. Mientras, el tope se dice en pantalla en vez de esconderse.\n */\nexport async function traerEntregadosSinResena(): Promise<EntregadosSinResena> {\n  const r = await ecomerseApi.myOrders('buyer', { status: 'delivered', limit: PAGINA_VALORAR });\n  const orders = r.orders.filter((o) => !o.reviewed);\n  return { orders, n: orders.length, truncado: r.total > r.orders.length };\n}\n","/**\n * La ficha de UNA reclamación — `/ecomerse-perfil-reembolso?id=<uuid>`.\n *\n * Cuelga de `/ecomerse-perfil` por el mismo motivo que la lista: el pie enciende «Perfil» comparando\n * el prefijo del pathname (`PieDelMercado.tsx:89`). Ver la cabecera de `ecomerse-perfil-reembolsos.tsx`.\n *\n * PIDE LA FILA, NO LA BUSCA EN LA LISTA\n * Podría traerse las reclamaciones y quedarse con la suya —es lo que hace la pantalla de favoritos—,\n * pero la lista viene recortada a 100: una reclamación propia que cayera fuera de esa ventana se\n * leería como «no existe» teniéndola. `GET /ecomerse/disputes/:id` va a por la fila, sin ventana.\n *\n * EL VEREDICTO SE LEE DEL MISMO SITIO QUE EN LA LISTA\n * El rótulo y el color salen de `veredictoDe()`, del módulo compartido: si la lista y la ficha los\n * calcularan por su cuenta, la misma reclamación podría llamarse «Con reembolso» en una y «Éxito» en\n * la otra. La ficha añade lo que la lista no cabe —el texto del administrador, las fotos de la\n * evidencia y las fechas—, pero no reinterpreta el estado.\n *\n * NO SE INVENTA UN BOTÓN PARA EL PEDIDO\n * No existe una pantalla de pedido suelta a la que enlazar: el detalle del pedido vive dentro de la\n * lista de pedidos. Así que en vez de prometer una ruta que no hay, se ofrece «Ver mis pedidos» y se\n * dice la referencia corta para poder encontrarlo. Un botón que no lleva a donde dice es peor que no\n * tenerlo.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Image } from 'expo-image';\nimport { ArrowLeft, ImageOff } from 'lucide-react-native';\nimport {\n  EmptyState, Precio, espaciado, icono, peso, radios, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseDispute } from '../api/ecomerse';\nimport { formatDateTime } from '../utils/formatHelpers';\nimport { useSession } from '../state/session';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { FichaArticulo } from '../components/ecomerse/FichaArticulo';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\nimport { veredictoDe } from '../components/ecomerse/estadosReclamacion';\n\n/** Una fila «etiqueta — valor». Se repite cinco veces: es lo que justifica que sea una pieza. */\nfunction Dato({ etiqueta, children }: { etiqueta: string; children: React.ReactNode }) {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.dato}>\n      <Text style={[styles.datoEtiqueta, { color: colors.textSecondary }]}>{etiqueta}</Text>\n      <View style={styles.datoValor}>{children}</View>\n    </View>\n  );\n}\n\nexport default function EcomerseReembolsoScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const sinLeer = useSinLeerMercado();\n  const { id } = useLocalSearchParams<{ id?: string }>();\n\n  const [reclamo, setReclamo] = useState<EcomerseDispute | null>(null);\n  const [cargando, setCargando] = useState(false);\n  const [intentado, setIntentado] = useState(false);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated || !id) { setReclamo(null); setIntentado(true); return; }\n    setCargando(true);\n    try {\n      setReclamo(await ecomerseApi.dispute(String(id)));\n    } catch {\n      setReclamo(null);\n    } finally {\n      setCargando(false);\n      setIntentado(true);\n    }\n  }, [isAuthenticated, id]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const def = reclamo ? veredictoDe(reclamo.outcome) : null;\n  /* Sin `id` en la URL no se ha pedido nada: es un caso distinto de «se pidió y no existe», y\n     confundirlos daría un «no encontrada» a quien llegó por un enlace roto. */\n  const sinId = !id;\n  const noExiste = !!id && intentado && !cargando && reclamo === null;\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]} numberOfLines={1}>\n          Reclamación\n        </Text>\n        <View style={styles.hueco} />\n      </View>\n\n      {!isAuthenticated ? (\n        <View style={styles.centro}>\n          <EmptyState\n            emoji=\"🔐\"\n            titulo=\"Entra para ver la reclamación\"\n            texto=\"Las reclamaciones van con tu cuenta: sin sesión no hay nada que enseñar.\"\n            accionLabel=\"Iniciar sesión\"\n            accionPrimaria\n            onAccion={() => router.push('/auth' as never)}\n          />\n        </View>\n      ) : sinId || noExiste ? (\n        <View style={styles.centro}>\n          {/* `noExiste` incluye el caso legítimo de una reclamación AJENA: el servidor contesta 404 y\n              no 403, así que desde aquí no se puede distinguir «no existe» de «no es tuya» — que es\n              justo lo que se quiere, porque a un tercero no le toca saber que existe. */}\n          <EmptyState\n            emoji={sinId ? '🧾' : '🔎'}\n            titulo={sinId ? 'No has elegido ninguna reclamación' : 'Esa reclamación no está a tu nombre'}\n            texto={\n              sinId\n                ? 'Abre una desde la lista de reembolsos.'\n                : 'Puede que se haya abierto desde otra cuenta. Vuelve a la lista para ver las tuyas.'\n            }\n            accionLabel=\"Ver mis reclamaciones\"\n            onAccion={() => router.replace('/ecomerse-perfil-reembolsos' as never)}\n          />\n        </View>\n      ) : cargando && !reclamo ? (\n        <View style={styles.centro}>\n          <ActivityIndicator color={colors.primary} />\n        </View>\n      ) : reclamo && def ? (\n        <ScrollView contentContainerStyle={{ paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e24 }}>\n          {/* El veredicto, con el mismo tratamiento que en la lista: pastilla sólida y un párrafo que\n              dice qué significa. */}\n          <View style={styles.bloqueVeredicto}>\n            <View style={[styles.pastilla, { backgroundColor: colors[def.color] }]}>\n              <Text style={[styles.pastillaTexto, { color: colors[def.colorTexto] }]}>{def.label}</Text>\n            </View>\n            <Text style={[styles.veredictoNota, { color: colors.textSecondary }]}>{def.nota}</Text>\n          </View>\n\n          {/* El sujeto: el artículo reclamado, tal como se compró. */}\n          <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            {reclamo.product ? (\n              <FichaArticulo articulo={reclamo.product} />\n            ) : (\n              /* Sin líneas en el pedido no hay artículo que enseñar, y se dice: un hueco vacío se\n                 leería como un fallo de carga. */\n              <View style={styles.sinArticulo}>\n                <ImageOff size={icono.md} color={colors.textSecondary} />\n                <Text style={[styles.sinArticuloTexto, { color: colors.textSecondary }]}>\n                  Este pedido no guardó el detalle del artículo.\n                </Text>\n              </View>\n            )}\n          </View>\n\n          <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={[styles.tarjetaTitulo, { color: colors.textPrimary }]}>Lo que reclamaste</Text>\n            <Text style={[styles.motivo, { color: colors.textPrimary }]}>{reclamo.reason}</Text>\n            <Text style={[styles.fecha, { color: colors.textSecondary }]}>\n              Abierta el {formatDateTime(reclamo.createdAt)}\n            </Text>\n\n            {/* La evidencia. Si no hay, se dice — no se deja un hueco mudo que parezca no cargado. */}\n            {reclamo.evidence.length > 0 ? (\n              <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.evidencia}>\n                {reclamo.evidence.map((url) => (\n                  <Image key={url} source={{ uri: url }} style={[styles.evidenciaFoto, { borderColor: colors.border }]} contentFit=\"cover\" />\n                ))}\n              </ScrollView>\n            ) : (\n              <Text style={[styles.fecha, { color: colors.textSecondary }]}>\n                No adjuntaste fotos.\n              </Text>\n            )}\n          </View>\n\n          {/* Qué pasó. Mientras está abierta se dice eso y nada más: no hay veredicto que dar. */}\n          <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={[styles.tarjetaTitulo, { color: colors.textPrimary }]}>Qué pasó</Text>\n            {reclamo.status === 'open' ? (\n              <Text style={[styles.motivo, { color: colors.textSecondary }]}>\n                El administrador todavía la está revisando. Te avisaremos cuando decida.\n              </Text>\n            ) : (\n              <>\n                {reclamo.resolution ? (\n                  <Text style={[styles.motivo, { color: colors.textPrimary }]}>{reclamo.resolution}</Text>\n                ) : (\n                  /* Resuelta sin texto del administrador. Se dice tal cual en vez de rellenar con una\n                     frase de plantilla que nadie escribió. */\n                  <Text style={[styles.motivo, { color: colors.textSecondary }]}>\n                    El administrador no dejó una nota.\n                  </Text>\n                )}\n                {reclamo.resolvedAt ? (\n                  <Text style={[styles.fecha, { color: colors.textSecondary }]}>\n                    Resuelta el {formatDateTime(reclamo.resolvedAt)}\n                  </Text>\n                ) : null}\n              </>\n            )}\n          </View>\n\n          {/* Los importes. El total siempre; lo devuelto SÓLO si lo hubo, para no escribir «0 XAF»\n              donde la pregunta no viene al caso. */}\n          <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Dato etiqueta=\"Importe del pedido\">\n              <Precio valor={reclamo.totalXaf} tamano=\"sm\" />\n            </Dato>\n            {reclamo.refundXaf > 0 ? (\n              <Dato etiqueta=\"Importe devuelto\">\n                <Precio valor={reclamo.refundXaf} tamano=\"sm\" />\n              </Dato>\n            ) : null}\n            <Dato etiqueta=\"Pedido\">\n              <Text style={[styles.valorTexto, { color: colors.textPrimary }]}>{reclamo.orderRef}</Text>\n            </Dato>\n            {reclamo.sellerName ? (\n              <Dato etiqueta=\"Tienda\">\n                <Text style={[styles.valorTexto, { color: colors.textPrimary }]} numberOfLines={2}>\n                  {reclamo.sellerName}\n                </Text>\n              </Dato>\n            ) : null}\n          </View>\n\n          <Pressable\n            onPress={() => router.push('/ecomerse-orders' as never)}\n            accessibilityRole=\"button\"\n            accessibilityLabel={`Ver mis pedidos, para encontrar el pedido ${reclamo.orderRef}`}\n            style={({ pressed }) => [styles.boton, { borderColor: colors.border, opacity: pressed ? 0.6 : 1 }]}\n          >\n            <Text style={[styles.botonTexto, { color: colors.primary }]}>Ver mis pedidos</Text>\n          </Pressable>\n        </ScrollView>\n      ) : null}\n\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { flexShrink: 1, fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  hueco: { width: icono.lg },\n  centro: { paddingTop: espaciado.e24, paddingHorizontal: espaciado.e16 },\n  bloqueVeredicto: { paddingHorizontal: espaciado.e16, paddingTop: espaciado.e16, gap: espaciado.e8 },\n  pastilla: {\n    alignSelf: 'flex-start',\n    paddingHorizontal: espaciado.e8,\n    paddingVertical: espaciado.e4,\n    borderRadius: radios.sm,\n  },\n  pastillaTexto: { fontSize: tipografia.micro, fontWeight: peso.titulo },\n  veredictoNota: { fontSize: tipografia.caption, lineHeight: 17 },\n  tarjeta: {\n    marginHorizontal: espaciado.e16,\n    marginTop: espaciado.e12,\n    borderRadius: radios.lg,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    gap: espaciado.e8,\n  },\n  tarjetaTitulo: { fontSize: tipografia.body, fontWeight: peso.titulo },\n  sinArticulo: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 },\n  sinArticuloTexto: { flex: 1, fontSize: tipografia.caption },\n  motivo: { fontSize: tipografia.body, lineHeight: 20 },\n  fecha: { fontSize: tipografia.micro },\n  evidencia: { marginTop: espaciado.e4 },\n  evidenciaFoto: {\n    width: 96,\n    height: 96,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    marginRight: espaciado.e8,\n  },\n  dato: { flexDirection: 'row', alignItems: 'baseline', justifyContent: 'space-between', gap: espaciado.e12 },\n  datoEtiqueta: { fontSize: tipografia.caption },\n  datoValor: { flexShrink: 1, alignItems: 'flex-end' },\n  valorTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  boton: {\n    marginHorizontal: espaciado.e16,\n    marginTop: espaciado.e16,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    paddingVertical: espaciado.e12,\n    alignItems: 'center',\n  },\n  botonTexto: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n});\n","/**\n * LOS VEREDICTOS DE UNA RECLAMACIÓN — el contrato compartido (退款售后, Fase 5 del pie).\n *\n * POR QUÉ ESTÁ EN UN MÓDULO Y NO DENTRO DE UNA PANTALLA\n * Igual que `seccionesCompra.ts` y `canalesAviso.ts`: el rótulo de un veredicto, su color y su\n * significado los usan **dos** pantallas —la lista, que pinta las pestañas y la etiqueta de cada\n * fila, y la ficha, que pone ese rótulo en su cabecera y explica qué pasó—. Si cada una guardara su\n * copia, un día la pestaña diría «Con reembolso» y la ficha «Éxito», y el usuario no tendría forma de\n * saber que son lo mismo. **El id es el que viaja en la URL** (`?filtro=refunded`), así que la URL y\n * las dos pantallas hablan del mismo veredicto por construcción.\n *\n * TRES VEREDICTOS, NO CUATRO — y esto merece explicación porque el plan dice otra cosa\n * `MERCADO-PIE-PLAN.md` §3 escribe «no hay lista del comprador ni estado de 4 valores (待处理/成功/失败)»:\n * dice CUATRO y enumera TRES. La lista de la referencia (`oms_order_return_apply`) sí tiene cuatro\n * —待处理 · 退货中 · 已完成 · 已拒绝—, y el que falta es 退货中 (*devolución en curso*).\n *\n * **No se copia 退货中 porque aquí no existe ese trámite**: la devolución física del artículo no está\n * modelada en ninguna tabla. El reembolso de hoy es un acto del administrador —marca «reembolso sí» y\n * el pedido se cancela—, no un viaje del paquete de vuelta con sus estados. Inventarse la pestaña\n * habría dado una pantalla permanentemente vacía y un estado que ningún código puede activar:\n * exactamente la «etiqueta muerta» que ya se quitó una vez en la migración 020.\n *\n * LOS COLORES SALEN DE LA SEMÁNTICA DEL KIT, no del gusto\n *   · `pending`  → `warning`  (ámbar). El kit lo reserva a lo que está EN CURSO.\n *   · `refunded` → `success`  (verde). Para el comprador que reclamó, que le devuelvan ES el éxito.\n *   · `rejected` → `neutral`  (gris). El kit lo define como «estado sin carga emocional (cancelado,\n *     expirado, revertido)» y una reclamación rechazada es justo eso. **No se usa `danger`**: el kit\n *     lo reserva a emergencias, y que al comprador no le den la razón no es una emergencia.\n *\n * LA ETIQUETA ES UNA PASTILLA SÓLIDA, Y POR ESO NO HAY RAMAS DE TEMA\n * Se probó a tintar el fondo con `alpha(color, 0.14)` y escribir el texto en el color —que es lo que\n * hace el resto de la casa— y **no sirve para estos tres**: el kit sólo trae variantes oscuras de\n * texto para dos de sus colores (`dangerText`, `warningText`), no para `success` ni `neutral`, y en\n * tema oscuro el verde del kit sobre un tinte oscuro no llega a AA (el literal está en el archivo de\n * tokens; aquí no se escribe, la guardia de diseño lo contaría como deuda). La pastilla sólida esquiva el\n * problema entero: el par (fondo, texto) es el mismo en los dos temas y su contraste está garantizado\n * por los tokens —`onWarning` existe precisamente porque el blanco sobre ámbar da 2,1:1—. Menos\n * elegante que un tinte, pero se lee en los dos temas, que es lo que se le pide a un estado.\n */\n\nimport type { EcomerseDisputeOutcome } from '../../api/ecomerse';\n\n/** Los tres veredictos. El tipo canónico vive en el cliente de la API; aquí se reexporta. */\nexport type EstadoReclamacion = EcomerseDisputeOutcome;\n\nexport interface EstadoReclamacionDef {\n  id: EstadoReclamacion;\n  /** El rótulo de la pestaña, de la etiqueta de la fila y de la cabecera de la ficha. El mismo texto. */\n  label: string;\n  /** Qué significa, para el vacío de su pestaña y para el lector de pantalla. */\n  nota: string;\n  /** El token de color del kit. Ver la cabecera para por qué cada uno. */\n  color: 'warning' | 'success' | 'neutral';\n  /**\n   * El token del TEXTO que va sobre esa pastilla. No es siempre blanco: sobre el ámbar el blanco da\n   * 2,1:1 y no llega a AA, y el kit tiene `onWarning` justamente para eso. Ver la cabecera.\n   */\n  colorTexto: 'onWarning' | 'white';\n}\n\nexport const ESTADOS_RECLAMACION: EstadoReclamacionDef[] = [\n  {\n    id: 'pending',\n    label: 'En revisión',\n    nota: 'Reclamaciones abiertas: el administrador todavía no ha decidido.',\n    color: 'warning',\n    colorTexto: 'onWarning',\n  },\n  {\n    id: 'refunded',\n    label: 'Con reembolso',\n    nota: 'Reclamaciones que se resolvieron a tu favor: el importe volvió a ti.',\n    color: 'success',\n    colorTexto: 'white',\n  },\n  {\n    id: 'rejected',\n    label: 'Rechazadas',\n    nota: 'Reclamaciones que se resolvieron a favor del vendedor.',\n    color: 'neutral',\n    colorTexto: 'white',\n  },\n];\n\nexport const buscarEstado = (id?: string | null): EstadoReclamacionDef | null =>\n  ESTADOS_RECLAMACION.find((e) => e.id === id) ?? null;\n\n/**\n * El veredicto que se PINTA a partir de lo que guarda la base.\n *\n * `null` no es un cuarto veredicto: es «no consta». Son las reclamaciones anteriores a la migración\n * 024 cuya resolución no se pudo atribuir con certeza (un pedido con varias reclamaciones y eventos\n * que no dicen a cuál se refieren). Se pintan como «en revisión» porque es lo único honesto que se\n * puede decir de ellas —no se sabe cómo acabaron—, pero **se piden en la pestaña de pendientes**, que\n * es donde el comprador las va a buscar.\n *\n * Se resuelve en UN sitio y no en cada pantalla: si la lista lo pintara de una forma y la ficha de\n * otra, la misma reclamación tendría dos veredictos según por dónde se entre.\n */\nexport const veredictoDe = (outcome: EcomerseDisputeOutcome | null): EstadoReclamacionDef =>\n  buscarEstado(outcome) ?? ESTADOS_RECLAMACION[0];\n\n/** Una pestaña de la lista: «Todas» más los tres veredictos. */\nexport interface FiltroReclamacionDef {\n  id: 'todas' | EstadoReclamacion;\n  label: string;\n}\n\nexport const FILTROS_RECLAMACION: FiltroReclamacionDef[] = [\n  { id: 'todas', label: 'Todas' },\n  ...ESTADOS_RECLAMACION.map((e) => ({ id: e.id, label: e.label })),\n];\n\n/**\n * El filtro que pide la URL, o `'todas'`. Un id que no es de ningún veredicto cae en «Todas» en vez\n * de en un error: la URL la puede escribir cualquiera, y castigar al usuario por una barra mal puesta\n * es peor que enseñarle su lista entera.\n */\nexport const buscarFiltro = (id?: string | null): FiltroReclamacionDef['id'] =>\n  id === 'todas' || buscarEstado(id) ? (id as FiltroReclamacionDef['id']) : 'todas';\n\n/**\n * ¿Esta reclamación entra en esta pestaña?\n *\n * `todas` entra siempre. La de pendientes es la única con truco: recoge también las de veredicto\n * NULO, porque «no consta» se pinta como «en revisión» (ver `veredictoDe`) y dejarlas fuera de las\n * dos pestañas las haría desaparecer de la pantalla sin que el contador lo delatara.\n */\nexport const entraEnFiltro = (\n  outcome: EcomerseDisputeOutcome | null,\n  filtro: FiltroReclamacionDef['id'],\n): boolean => {\n  if (filtro === 'todas') return true;\n  if (filtro === 'pending') return outcome === null || outcome === 'pending';\n  return outcome === filtro;\n};\n","/**\n * Reembolsos y devoluciones — la lista (退款售后), `/ecomerse-perfil-reembolsos`.\n *\n * POR QUÉ LA RUTA CUELGA DE `/ecomerse-perfil` Y NO SE LLAMA `/ecomerse-reembolsos`\n * Porque el pie decide qué pestaña está encendida comparando el **prefijo** del pathname, y «Perfil»\n * se compara con `/ecomerse-perfil` (`PieDelMercado.tsx:89`). Una ruta hermana como\n * `/ecomerse-reembolsos` NO empieza por ese prefijo, así que al abrirla la pestaña «Perfil» se\n * apagaría y no quedaría ninguna encendida: el usuario estaría dentro del perfil con el pie diciendo\n * que no está en ninguna parte. Es exactamente la trampa que documenta `ecomerse-mensajes-avisos.tsx`\n * con `/ecomerse-mensajes`, resuelta igual: por el nombre, sin tocar el pie.\n *\n * LAS PESTAÑAS NO CUENTAN LO QUE VEN\n * El número de cada pestaña sale de `counts`, que lo calcula la BASE sobre todas las reclamaciones.\n * La lista trae hasta 100 filas, así que contar las que llegaron daría un número recortado sin\n * avisar en cuanto hubiera más de 100 — y las pestañas de una lista no pueden mentir en su número.\n * Es la misma separación que en la bandeja de avisos (`notices` / `noticeCounts`).\n *\n * EL FILTRO VIVE EN LA URL, COMO EL DE PEDIDOS Y FAVORITOS\n * `?filtro=pending|refunded|rejected|todas`, y el id sale del módulo compartido\n * (`estadosReclamacion.ts`). Así el perfil puede llevar con un dedo a «las que están en revisión» sin\n * que la lista sepa de qué pantalla viene, y el chip encendido y el filtro aplicado son el mismo dato\n * por construcción —no dos que puedan divergir—.\n *\n * AQUÍ NO SE ABRE NI SE RESUELVE NADA\n * Las dos acciones existen en el servidor (`openDispute` desde la ficha del pedido, y\n * `adminResolveDispute` para el administrador), y ninguna de las dos se duplica aquí. Esta pantalla\n * es de LECTURA: es la que faltaba, porque hasta hoy quien abría una reclamación no tenía dónde\n * consultarla.\n */\n\nimport React, { useCallback, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport {\n  EmptyState, Precio, brand, espaciado, icono, peso, radios, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseDispute, type EcomerseDisputeCounts } from '../api/ecomerse';\nimport { getTimeAgo } from '../utils/formatHelpers';\nimport { useSession } from '../state/session';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { FichaArticulo } from '../components/ecomerse/FichaArticulo';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\nimport {\n  FILTROS_RECLAMACION, buscarFiltro, buscarEstado, entraEnFiltro, veredictoDe,\n  type FiltroReclamacionDef,\n} from '../components/ecomerse/estadosReclamacion';\n\n/** La pastilla del veredicto. Ver la cabecera del módulo: sólida, y con el texto del token correcto. */\nfunction Pastilla({ dispute }: { dispute: EcomerseDispute }) {\n  const { colors } = useTheme();\n  const def = veredictoDe(dispute.outcome);\n  return (\n    <View style={[styles.pastilla, { backgroundColor: colors[def.color] }]}>\n      <Text style={[styles.pastillaTexto, { color: colors[def.colorTexto] }]} numberOfLines={1}>\n        {def.label}\n      </Text>\n    </View>\n  );\n}\n\n/**\n * Lo que un lector de pantalla lee de una fila: el veredicto, el artículo, el motivo y el pedido, en\n * el orden en que se ven. Se compone aquí —y no en el `renderItem`— para que la etiqueta y lo pintado\n * no puedan divergir, igual que en la bandeja de avisos.\n */\nfunction etiquetaDe(d: EcomerseDispute): string {\n  const partes = [\n    veredictoDe(d.outcome).label,\n    d.product ? d.product.title : null,\n    d.reason,\n    `Pedido ${d.orderRef}`,\n    d.refundXaf > 0 ? 'importe devuelto' : null,\n  ];\n  return partes.filter(Boolean).join('. ') + '.';\n}\n\nexport default function EcomerseReembolsosScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const sinLeer = useSinLeerMercado();\n  const { filtro: filtroParam } = useLocalSearchParams<{ filtro?: string }>();\n\n  const filtro = buscarFiltro(filtroParam);\n\n  const [reclamos, setReclamos] = useState<EcomerseDispute[] | null>(null);\n  const [cuenta, setCuenta] = useState<EcomerseDisputeCounts | null>(null);\n  const [total, setTotal] = useState(0);\n  const [cargando, setCargando] = useState(false);\n  const [refrescando, setRefrescando] = useState(false);\n  /** «Aún no he preguntado» y «pregunté y falló» no son lo mismo. Ver `ecomerse-perfil.tsx`. */\n  const [intentado, setIntentado] = useState(false);\n\n  const leer = useCallback(async () => {\n    const r = await ecomerseApi.myDisputes();\n    setReclamos(r.disputes);\n    setCuenta(r.counts);\n    setTotal(r.total);\n  }, []);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated) { setReclamos(null); setCuenta(null); setIntentado(true); return; }\n    setCargando(true);\n    try {\n      await leer();\n    } catch {\n      setReclamos(null);\n      setCuenta(null);\n    } finally {\n      setCargando(false);\n      setIntentado(true);\n    }\n  }, [isAuthenticated, leer]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const refrescar = useCallback(async () => {\n    setRefrescando(true);\n    try { await leer(); } catch { /* se queda lo que había: un tic de red no borra la lista */ }\n    finally { setRefrescando(false); }\n  }, [leer]);\n\n  /** El número de cada pestaña: el de la base, no el que se cuenta en pantalla. */\n  const cuentaDe = (f: FiltroReclamacionDef['id']): number =>\n    f === 'todas' ? total : (cuenta?.[f] ?? 0);\n\n  /**\n   * Las filas que se pintan. El filtro se aplica en el cliente sobre las 100 que llegaron, y eso es\n   * correcto AQUÍ porque el número de la pestaña no sale de esta lista: aunque la ventana recorte,\n   * el chip dice la verdad y la lista enseña lo que tiene. Cuando el problema sea el recorte y no el\n   * filtro, se verá en el contador.\n   */\n  const visibles = useMemo(\n    () => (reclamos ?? []).filter((d) => entraEnFiltro(d.outcome, filtro)),\n    [reclamos, filtro],\n  );\n\n  const estadoActivo = buscarEstado(filtro);\n  const fallo = isAuthenticated && intentado && !cargando && reclamos === null;\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]} numberOfLines={1}>\n          Reembolsos y devoluciones\n        </Text>\n        <View style={styles.hueco} />\n      </View>\n\n      {!isAuthenticated ? (\n        <View style={styles.centro}>\n          <EmptyState\n            emoji=\"🔐\"\n            titulo=\"Entra para ver tus reclamaciones\"\n            texto=\"Las reclamaciones van con tu cuenta: sin sesión no hay nada que enseñar.\"\n            accionLabel=\"Iniciar sesión\"\n            accionPrimaria\n            onAccion={() => router.push('/auth' as never)}\n          />\n        </View>\n      ) : fallo ? (\n        <View style={styles.centro}>\n          <EmptyState\n            emoji=\"📡\"\n            titulo=\"No se pudieron cargar tus reclamaciones\"\n            texto=\"El servidor no contestó. Puede ser la red del aparato: vuelve a intentarlo.\"\n            accionLabel=\"Reintentar\"\n            onAccion={() => void cargar()}\n          />\n        </View>\n      ) : cargando && reclamos === null ? (\n        <View style={styles.centro}>\n          <ActivityIndicator color={colors.primary} />\n        </View>\n      ) : (\n        <>\n          {/*\n            Las pestañas. El carril se desplaza en horizontal y los chips llevan ALTO FIJO: es la\n            lección de la lista de pedidos, donde sin alto fijo la fila se comprimía en vez de\n            desplazarse y el chip aplastaba su texto a dos líneas.\n          */}\n          <ScrollView\n            horizontal\n            showsHorizontalScrollIndicator={false}\n            style={styles.filtros}\n            contentContainerStyle={styles.filtrosContenido}\n          >\n            {FILTROS_RECLAMACION.map((f) => {\n              const on = filtro === f.id;\n              const n = cuentaDe(f.id);\n              return (\n                <Pressable\n                  key={f.id}\n                  onPress={() => router.setParams({ filtro: f.id } as never)}\n                  accessibilityRole=\"tab\"\n                  accessibilityState={{ selected: on }}\n                  accessibilityLabel={`${f.label}${n ? `, ${n} ${n === 1 ? 'reclamación' : 'reclamaciones'}` : ', ninguna'}`}\n                  style={[\n                    styles.filtroChip,\n                    {\n                      backgroundColor: on ? colors.primary : colors.surface,\n                      borderColor: on ? colors.primary : colors.border,\n                    },\n                  ]}\n                >\n                  <Text numberOfLines={1} style={[styles.filtroTexto, { color: on ? brand.white : colors.textPrimary }]}>\n                    {f.label}{n ? ` ${n}` : ''}\n                  </Text>\n                </Pressable>\n              );\n            })}\n          </ScrollView>\n\n          <FlatList\n            data={visibles}\n            keyExtractor={(d) => d.id}\n            contentContainerStyle={{ paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e24 }}\n            refreshControl={\n              <RefreshControl refreshing={refrescando} onRefresh={() => void refrescar()} tintColor={colors.primary} />\n            }\n            ListEmptyComponent={\n              <View style={styles.centro}>\n                <EmptyState\n                  emoji=\"🧾\"\n                  /* El vacío dice QUÉ va a aparecer y con qué palabras. Con un filtro puesto nombra el\n                     veredicto, para que «no hay ninguna» se lea como «no hay ninguna DE ÉSTAS» y no\n                     como «no funciona». */\n                  titulo={estadoActivo ? `Ninguna ${estadoActivo.label.toLowerCase()}` : 'Todavía no has reclamado nada'}\n                  texto={\n                    estadoActivo\n                      ? estadoActivo.nota\n                      : 'Cuando algo vaya mal con un pedido entregado puedes abrir una reclamación desde su ficha, y aparecerá aquí.'\n                  }\n                />\n              </View>\n            }\n            renderItem={({ item }) => (\n              <Pressable\n                onPress={() => router.push(`/ecomerse-perfil-reembolso?id=${item.id}` as never)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={etiquetaDe(item)}\n                style={({ pressed }) => [styles.fila, { borderBottomColor: colors.border, opacity: pressed ? 0.6 : 1 }]}\n              >\n                <View style={styles.filaCabecera}>\n                  <Pastilla dispute={item} />\n                  <Text style={[styles.hora, { color: colors.textSecondary }]}>\n                    {getTimeAgo(item.createdAt)}\n                  </Text>\n                </View>\n\n                {/* El sujeto de la reclamación es EL ARTÍCULO, igual que en la bandeja de avisos. */}\n                {item.product ? <FichaArticulo articulo={item.product} /> : null}\n\n                {/* El motivo que escribió el comprador: es su propia queja, así que se enseña. */}\n                <Text style={[styles.motivo, { color: colors.textSecondary }]} numberOfLines={2}>\n                  {item.reason}\n                </Text>\n\n                <View style={styles.pie}>\n                  <Text style={[styles.referencia, { color: colors.textSecondary }]}>\n                    Pedido {item.orderRef}\n                  </Text>\n                  {/* El importe devuelto SÓLO se dice cuando lo hubo: un «0 XAF» en las otras dos\n                      se leería como «no te devolvieron nada» cuando la pregunta no viene al caso. */}\n                  {item.refundXaf > 0 ? (\n                    <View style={styles.devuelto}>\n                      <Text style={[styles.devueltoTexto, { color: colors.textSecondary }]}>Devuelto </Text>\n                      <Precio valor={item.refundXaf} tamano=\"sm\" />\n                    </View>\n                  ) : null}\n                </View>\n              </Pressable>\n            )}\n          />\n        </>\n      )}\n\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { flexShrink: 1, fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  hueco: { width: icono.lg },\n  centro: { paddingTop: espaciado.e24, paddingHorizontal: espaciado.e16 },\n  filtros: { flexGrow: 0 },\n  /* Alto FIJO en el carril y en cada chip: sin esto la fila se comprime en vez de desplazarse (ver la\n     lista de pedidos, donde se midió). */\n  filtrosContenido: { height: 44, alignItems: 'center', paddingHorizontal: espaciado.e16, gap: espaciado.e8 },\n  filtroChip: { height: 32, justifyContent: 'center', paddingHorizontal: espaciado.e12, borderRadius: radios.full, borderWidth: trazo.fino },\n  filtroTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  fila: {\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n    gap: espaciado.e8,\n  },\n  filaCabecera: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },\n  pastilla: {\n    paddingHorizontal: espaciado.e8,\n    paddingVertical: espaciado.e4,\n    borderRadius: radios.sm,\n  },\n  pastillaTexto: { fontSize: tipografia.micro, fontWeight: peso.titulo },\n  hora: { fontSize: tipografia.micro },\n  motivo: { fontSize: tipografia.caption, lineHeight: 17 },\n  pie: { flexDirection: 'row', alignItems: 'baseline', justifyContent: 'space-between', gap: espaciado.e8 },\n  referencia: { fontSize: tipografia.micro },\n  devuelto: { flexDirection: 'row', alignItems: 'baseline' },\n  devueltoTexto: { fontSize: tipografia.micro },\n});\n","/**\n * Tiendas que sigo — la lista del seguimiento del Mercado (店铺关注), `/ecomerse-perfil-tiendas`.\n *\n * POR QUÉ LA RUTA CUELGA DE `/ecomerse-perfil` Y NO SE LLAMA `/ecomerse-tiendas-seguidas`\n * Porque el pie decide qué pestaña está encendida comparando el **prefijo** del pathname, y «Perfil»\n * se compara con `/ecomerse-perfil` (`PieDelMercado.tsx:89`). Una ruta que no empieza por ese\n * prefijo apagaría la pestaña «Perfil» al abrirse y no quedaría ninguna encendida: el usuario estaría\n * dentro del perfil con el pie diciendo que no está en ninguna parte. Es la trampa que documentan\n * `ecomerse-mensajes-avisos.tsx` y `ecomerse-perfil-reembolsos.tsx`, resuelta igual: por el nombre,\n * sin tocar el pie. OJO: `/ecomerse-tiendas` YA EXISTE y es el DIRECTORIO del Mercado —un nombre más\n * corto habría colisionado con él.\n *\n * LAS FILAS SON TARJETAS DEL CENSO\n * Cada fila se pinta con `CabeceraTienda`, el mismo componente que el directorio y la ficha, porque\n * el servidor devuelve la MISMA forma de tarjeta (`mapTienda` en el backend). Si un día la lista\n * nueva pintara con otro componente, la comparación de las dos pantallas sería la única forma de ver\n * la deriva.\n *\n * DEJAR DE SEGUIR ES DE UN TOQUE, SIN CONFIRMAR\n * A diferencia de borrar una dirección, dejar de seguir no destruye nada que cueste recuperar: la\n * tienda sigue existiendo y volver a seguirla es un toque en la misma fila dentro de su página. Un\n * `Alert` de confirmación aquí sería fricción por una acción reversible, así que se hace directo y se\n * revierte si el servidor dice que no.\n *\n * AQUÍ NO SE SIGUE NADA NUEVO\n * Seguir una tienda se hace desde su página (`BotonSeguirTienda`). Esta pantalla es la lista, la que\n * faltaba: quien seguía tiendas no tenía dónde verlas juntas.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Alert, FlatList, Pressable, RefreshControl, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport { EmptyState, InlineError, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseTiendaSeguida } from '../api/ecomerse';\nimport { useSession } from '../state/session';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { CabeceraTienda } from '../components/ecomerse/CabeceraTienda';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\n\n/** El texto del error del servidor si lo hay; si no, uno que no miente sobre lo que pasó. */\nconst mensajeDe = (e: unknown): string =>\n  e instanceof Error && e.message ? e.message : 'No se pudo completar. Inténtalo otra vez.';\n\nexport default function EcomersePerfilTiendasScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const sinLeer = useSinLeerMercado();\n\n  const [tiendas, setTiendas] = useState<EcomerseTiendaSeguida[] | null>(null);\n  const [cargando, setCargando] = useState(false);\n  const [refrescando, setRefrescando] = useState(false);\n  /** «Aún no he preguntado» y «pregunté y falló» no son lo mismo. Ver `ecomerse-perfil.tsx`. */\n  const [intentado, setIntentado] = useState(false);\n  /** El id de la fila que está hablando con el servidor: bloquea SU botón, no los de las demás. */\n  const [ocupada, setOcupada] = useState<string | null>(null);\n\n  const leer = useCallback(async () => {\n    const r = await ecomerseApi.myStoreFollows();\n    setTiendas(r.sellers);\n  }, []);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated) { setTiendas(null); setIntentado(true); return; }\n    setCargando(true);\n    try {\n      await leer();\n    } catch {\n      setTiendas(null);\n    } finally {\n      setCargando(false);\n      setIntentado(true);\n    }\n  }, [isAuthenticated, leer]);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const refrescar = useCallback(async () => {\n    setRefrescando(true);\n    try { await leer(); } catch { /* un tic de red no borra la lista: se queda lo que había */ }\n    finally { setRefrescando(false); }\n  }, [leer]);\n\n  const dejarDeSeguir = useCallback(async (t: EcomerseTiendaSeguida) => {\n    if (ocupada) return;\n    setOcupada(t.id);\n    /* Optimista: la fila sale YA. Si el servidor dice que no, se recarga y vuelve — y el motivo se\n       enseña, no se tapa con un genérico. */\n    setTiendas((prev) => (prev ?? []).filter((x) => x.id !== t.id));\n    try {\n      await ecomerseApi.followStore(t.id);\n    } catch (e) {\n      Alert.alert('No se pudo actualizar', mensajeDe(e));\n      await leer().catch(() => undefined);\n    } finally {\n      setOcupada(null);\n    }\n  }, [ocupada, leer]);\n\n  const fallo = isAuthenticated && intentado && !cargando && tiendas === null;\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]} numberOfLines={1}>\n          Tiendas que sigo\n        </Text>\n        <View style={styles.hueco} />\n      </View>\n\n      {!isAuthenticated ? (\n        <View style={styles.centro}>\n          <EmptyState\n            emoji=\"🔐\"\n            titulo=\"Entra para ver tus tiendas\"\n            texto=\"Las tiendas que sigues van con tu cuenta: sin sesión no hay lista que enseñar.\"\n            accionLabel=\"Iniciar sesión\"\n            accionPrimaria\n            onAccion={() => router.push('/auth' as never)}\n          />\n        </View>\n      ) : fallo ? (\n        <View style={styles.centro}>\n          <InlineError mensaje=\"No se pudo cargar la lista.\" onReintentar={() => void cargar()} />\n        </View>\n      ) : cargando && tiendas === null ? (\n        <View style={styles.centro}>\n          <ActivityIndicator color={colors.primary} />\n        </View>\n      ) : (\n        <FlatList\n          data={tiendas ?? []}\n          keyExtractor={(t) => t.id}\n          contentContainerStyle={{ paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e24 }}\n          refreshControl={\n            <RefreshControl refreshing={refrescando} onRefresh={() => void refrescar()} tintColor={colors.primary} />\n          }\n          ListEmptyComponent={\n            <View style={styles.centro}>\n              <EmptyState\n                emoji=\"🏪\"\n                titulo=\"Aún no sigues ninguna tienda\"\n                texto=\"Cuando sigas una tienda desde su página, aparecerá aquí para volver a ella rápido.\"\n                accionLabel=\"Explorar el directorio\"\n                onAccion={() => router.push('/ecomerse-tiendas' as never)}\n              />\n            </View>\n          }\n          renderItem={({ item }) => (\n            <View style={[styles.fila, { borderBottomColor: colors.border }]}>\n              {/*\n                LA TARJETA ES PUERTA a la tienda, igual que en el directorio: tocar el nombre o el\n                avatar entra a su página. La acción de dejar de seguir vive APARTE, debajo, para que\n                los dos gestos no compitan por el mismo toque.\n              */}\n              <CabeceraTienda\n                seller={item}\n                anuncios={item.anuncios}\n                onPress={() => router.push({ pathname: '/ecomerse-tienda', params: { id: item.id, nombre: item.businessName ?? '' } } as never)}\n              />\n              <View style={styles.filaPie}>\n                <Text style={[styles.desde, { color: colors.textSecondary }]}>\n                  Siguiéndola desde {item.since ? new Date(item.since).toLocaleDateString('es-ES', { day: 'numeric', month: 'short', year: 'numeric' }) : '—'}\n                </Text>\n                <Pressable\n                  onPress={() => void dejarDeSeguir(item)}\n                  disabled={ocupada === item.id}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`Dejar de seguir la tienda ${item.businessName ?? ''}`}\n                  accessibilityState={{ busy: ocupada === item.id }}\n                  style={({ pressed }) => [styles.dejar, { borderColor: colors.border, opacity: pressed || ocupada === item.id ? 0.6 : 1 }]}\n                >\n                  {ocupada === item.id ? (\n                    <ActivityIndicator size=\"small\" color={colors.textSecondary} />\n                  ) : (\n                    <Text style={[styles.dejarTexto, { color: colors.textSecondary }]}>Dejar de seguir</Text>\n                  )}\n                </Pressable>\n              </View>\n            </View>\n          )}\n        />\n      )}\n\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { flexShrink: 1, fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  hueco: { width: icono.lg },\n  centro: { paddingTop: espaciado.e24, paddingHorizontal: espaciado.e16 },\n  fila: {\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n    gap: espaciado.e8,\n  },\n  filaPie: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e8 },\n  desde: { flex: 1, fontSize: tipografia.micro },\n  dejar: {\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e4,\n    borderRadius: radios.full,\n    borderWidth: trazo.fino,\n    minWidth: 132,\n    alignItems: 'center',\n  },\n  dejarTexto: { fontSize: tipografia.micro, fontWeight: peso.fuerte },\n});\n","/**\n * Perfil del Mercado — tercer destino del pie (`/ecomerse-perfil`).\n *\n * QUÉ ENTRA Y QUÉ NO\n * Se integra **sólo** lo que se pidió del perfil de referencia: la identidad con opción a editar, la\n * dirección, mis pedidos con sus cuatro secciones, los favoritos y los dos accesos de reclamación y\n * seguimiento. De las capturas **no** se traen cupones, tarjeta mensual, historial de navegación,\n * centro de recarga, 拼团中 (compras en grupo) ni niveles de fidelidad: son módulos que aquí no\n * existen y que nadie ha pedido. 拼团中 se cae por su propio peso —no hay compra en grupo en esta\n * app— y por eso las secciones son CUATRO y no cinco.\n *\n * LO QUE YA FUNCIONA SE ENLAZA, LO QUE NO, SE DICE\n * «Mis pedidos», «Favoritos», «Dirección de entrega» (Fase 2) y —desde la Fase 5— «Reembolsos y\n * devoluciones» existen y están probados (`/ecomerse-orders`, `/ecomerse-favorites`,\n * `/ecomerse-direcciones` y `/ecomerse-perfil-reembolsos`), así que se enlazan: esconder una pantalla\n * que funciona para aparentar un perfil completo sería lo contrario de útil. Lo único que sigue sin\n * nada detrás son las tiendas seguidas (Fase 6), y va en un bloque aparte que lo dice, en vez de\n * pintar una fila que no lleva a ningún sitio.\n *\n * LA FILA DE LA DIRECCIÓN DICE CUÁNTAS HAY\n * Su nota sale de la agenda de verdad (`ecomerse_addresses`), no de un texto fijo: si tienes tres\n * guardadas lo dice y nombra la predeterminada, y si no tienes ninguna lo dice también. Una fila\n * que siempre cuenta lo mismo da igual que no estar.\n *\n * LAS CUATRO SECCIONES VIENEN DE UN MÓDULO COMPARTIDO\n * Los rótulos y los estados de 待付款 · 打包中 · 待收货 · 评价 viven en\n * `components/ecomerse/seccionesCompra.ts`, que es también de donde salen los chips de\n * `/ecomerse-orders`. Aquí se pintan, allí se filtran: si cada uno guardara su copia, un día el\n * perfil diría una cosa y la lista filtraría otra. **El id de la sección es el que viaja en la URL\n * del enlace**, que es lo que garantiza que la ficha y la lista hablen del mismo grupo de pedidos.\n *\n * LA IDENTIDAD ES LA MISMA PERSONA\n * El avatar y el nombre salen de la cuenta (`/mobility/auth/me`), no de un perfil propio del\n * Mercado: quien compra es el mismo usuario que pide un taxi o publica en Life Book. Por eso\n * «editar» lleva al editor de perfil que ya existe y no a un formulario nuevo — dos sitios donde\n * cambiar la misma foto acabarían enseñando dos fotos distintas.\n */\n\nimport React, { useCallback, useMemo, useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Image } from 'expo-image';\nimport {\n  ArrowLeft, ChevronRight, CreditCard, Heart, MapPin, Package, RotateCcw, Settings, Star, Store, Truck,\n} from 'lucide-react-native';\nimport { brand, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { authApi, type MeProfile } from '../api/auth';\nimport { ecomerseApi, type EcomerseAddress, type EcomerseDisputeCounts } from '../api/ecomerse';\nimport { useSession } from '../state/session';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\nimport {\n  SECCIONES_COMPRA, buscarSeccion, traerEntregadosSinResena,\n  type EntregadosSinResena, type SeccionId,\n} from '../components/ecomerse/seccionesCompra';\n\n/** Una fila con destino. */\ninterface Acceso {\n  titulo: string;\n  nota: string;\n  icono: React.ComponentType<{ size?: number; color?: string }>;\n  ruta?: string;\n}\n\n/** Lo guardado: hoy solo favoritos. Las tiendas que sigo ya tienen su propia fila viva (abajo). */\nconst GUARDADO: Acceso[] = [\n  {\n    titulo: 'Favoritos',\n    nota: 'Lo que has guardado, con sus categorías y cuántos hay en cada una.',\n    icono: Heart,\n    ruta: '/ecomerse-favorites',\n  },\n];\n\n/**\n * El icono de cada sección. Va AQUÍ y no en el módulo compartido porque aquél es el CONTRATO (el id,\n * el rótulo y el estado) y esto es pintura: si mañana el perfil cambia de iconos, la lista de\n * pedidos no tiene por qué enterarse.\n */\nconst ICONO_SECCION: Record<SeccionId, React.ComponentType<{ size?: number; color?: string }>> = {\n  pendiente: CreditCard,\n  preparando: Package,\n  enviado: Truck,\n  valorar: Star,\n};\n\nexport default function EcomersePerfilScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  /** Los sin leer, para la insignia de «Mensajes» del pie. Ver `useSinLeer.ts`. */\n  const sinLeer = useSinLeerMercado();\n  const [yo, setYo] = useState<MeProfile | null>(null);\n  const [cargando, setCargando] = useState(false);\n  /** Contadores por estado, para las tres primeras secciones. Una sola consulta agrupada. */\n  const [cuenta, setCuenta] = useState<Record<string, number> | null>(null);\n  /** Los entregados sin reseña (评价), que NO salen del contador del servidor. Ver el módulo. */\n  const [valorar, setValorar] = useState<EntregadosSinResena | null>(null);\n  /** La agenda de direcciones, para que su fila diga cuántas hay y cuál es la de por defecto. */\n  const [direcciones, setDirecciones] = useState<EcomerseAddress[] | null>(null);\n  /** Los recuentos de reclamaciones, para que la fila diga cuántas hay y cuántas siguen en revisión. */\n  const [reclamos, setReclamos] = useState<EcomerseDisputeCounts | null>(null);\n  /**\n   * CUÁNTAS TIENDAS SIGUE el comprador (店铺关注). Solo hace falta el número: la fila nombra el\n   * conteo y la lista vive en su propia pantalla. `null` significa «no se pudo preguntar», y entonces\n   * la nota NO afirma un cero — el mismo criterio que la fila de reclamaciones.\n   */\n  const [nTiendas, setNTiendas] = useState<number | null>(null);\n  /**\n   * Si ya se PIDIÓ la carga alguna vez. Sin esto, entre el primer pintado y el efecto de foco —que\n   * corre después— se colaba un fotograma diciendo «No se pudo cargar» antes de que la carga\n   * hubiera empezado siquiera. «Aún no he preguntado» y «pregunté y falló» no son lo mismo.\n   */\n  const [intentado, setIntentado] = useState(false);\n\n  const cargar = useCallback(async () => {\n    if (!isAuthenticated) {\n      setYo(null); setCuenta(null); setValorar(null); setDirecciones(null); setReclamos(null); setNTiendas(null); setIntentado(true); return;\n    }\n    setCargando(true);\n    try {\n      /* SEIS PREGUNTAS A LA VEZ, Y NINGUNA ARRASTRA A LAS OTRAS. Con `Promise.all` un fallo en la\n         cabecera se llevaba por delante los contadores —y con ellos las cuatro secciones—, que es\n         castigar lo que sí funcionaba por lo que no. Con `allSettled` cada una cae sola. */\n      const [perfil, c, v, dir, rec, seg] = await Promise.allSettled([\n        authApi.me(),\n        ecomerseApi.orderCounts('buyer'),\n        traerEntregadosSinResena(),\n        ecomerseApi.addresses(),\n        ecomerseApi.myDisputes(),\n        ecomerseApi.myStoreFollows(),\n      ]);\n      setYo(perfil.status === 'fulfilled' ? perfil.value : null);\n      setCuenta(c.status === 'fulfilled' ? c.value.porEstado : null);\n      setValorar(v.status === 'fulfilled' ? v.value : null);\n      setDirecciones(dir.status === 'fulfilled' ? dir.value : null);\n      setReclamos(rec.status === 'fulfilled' ? rec.value.counts : null);\n      setNTiendas(seg.status === 'fulfilled' ? seg.value.total : null);\n    } finally {\n      setCargando(false);\n      setIntentado(true);\n    }\n  }, [isAuthenticated]);\n\n  /**\n   * CARGA AL ENTRAR EN FOCO, NO SÓLO AL MONTAR. La pantalla se queda MONTADA en la pila mientras\n   * navegas —volver de la lista de pedidos no la reconstruye—, así que con un `useEffect` a secas\n   * el perfil se quedaba con los contadores del día que lo abriste: comprabas, volvías, y seguía\n   * diciendo «Por pagar 0». Con `useFocusEffect` se vuelve a preguntar cada vez que entra en foco.\n   * Es el mismo patrón que ya usan las demás pantallas de lista del proyecto.\n   */\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  /**\n   * Cuántos pedidos hay en una sección. `valorar` no sale de `cuenta` porque «sin reseña» no es un\n   * estado del pedido —es la ausencia de fila en `ecomerse_reviews`— y el contador del servidor\n   * agrupa por estado. Ver `seccionesCompra.ts`.\n   */\n  const nDe = (id: SeccionId): number => {\n    if (id === 'valorar') return valorar?.n ?? 0;\n    const s = buscarSeccion(id);\n    if (!s) return 0;\n    return s.estados.reduce((a, e) => a + (cuenta?.[e] ?? 0), 0);\n  };\n\n  const inicial = (yo?.fullName ?? '').trim().charAt(0).toUpperCase();\n  /**\n   * El teléfono llega de la base YA CON el `+` (`+240222000123`, que es como lo guarda `mobility.users`),\n   * así que anteponerle otro pintaba «++240222000123». Se quita el que traiga y se pone uno solo.\n   */\n  const tel = yo?.phone ? `+${yo.phone.replace(/^\\+/, '')}` : null;\n  /** Se preguntó, ya no se está preguntando y no hay identidad: eso es un fallo, no una carga. */\n  const fallo = isAuthenticated && intentado && !cargando && !yo;\n\n  /**\n   * La fila de la dirección. Su nota sale de la AGENDA, no de un texto fijo: una fila que siempre\n   * cuenta lo mismo da igual que no estar. La predeterminada se nombra por su etiqueta («Casa») y,\n   * cuando no tiene, por el principio de la dirección, recortado para que no rompa la fila.\n   */\n  const entrega: Acceso[] = useMemo(() => {\n    const d = direcciones;\n    const pred = d?.find((x) => x.isDefault) ?? d?.[0] ?? null;\n    const larga = pred ? (pred.label?.trim() || pred.detail) : '';\n    const corta = larga.length > 30 ? `${larga.slice(0, 29)}…` : larga;\n    return [\n      {\n        titulo: 'Dirección de entrega',\n        nota:\n          d === null\n            ? 'Dónde quieres recibir tus pedidos.'\n            : d.length === 0\n              ? 'Todavía no tienes ninguna. Añádela y el checkout dejará de pedirte que la escribas.'\n              : `${d.length} ${d.length === 1 ? 'guardada' : 'guardadas'} · por defecto: ${corta}`,\n        icono: MapPin,\n        ruta: '/ecomerse-direcciones',\n      },\n    ];\n  }, [direcciones]);\n\n  /**\n   * La fila de reclamaciones. Su nota sale de la lista de VERDAD, con el mismo criterio que la de la\n   * dirección: una fila que siempre cuenta lo mismo da igual que no estar. Nombra primero lo que pide\n   * acción —las que siguen sin resolver— y después el total, que es el orden en que se leen.\n   *\n   * `reclamos === null` significa «no se pudo preguntar», y entonces la nota NO afirma un cero: dice\n   * lo que hay detrás. Un «0 reclamaciones» al lado de un fallo de red es una mentira con buena\n   * presentación.\n   */\n  const reembolsos: Acceso[] = useMemo(() => {\n    const r = reclamos;\n    const total = r ? r.pending + r.refunded + r.rejected : 0;\n    const nota =\n      r === null\n        ? 'Las reclamaciones que has abierto y cómo acabaron.'\n        : total === 0\n          ? 'Todavía no has reclamado nada. Se abre una desde la ficha de un pedido entregado.'\n          : r.pending > 0\n            ? `${total} ${total === 1 ? 'reclamación' : 'reclamaciones'} · ${r.pending} en revisión`\n            : `${total} ${total === 1 ? 'reclamación' : 'reclamaciones'} · ninguna en revisión`;\n    return [\n      {\n        titulo: 'Reembolsos y devoluciones',\n        nota,\n        icono: RotateCcw,\n        ruta: '/ecomerse-perfil-reembolsos',\n      },\n    ];\n  }, [reclamos]);\n\n  /**\n   * La fila de las tiendas que sigo (店铺关注). La Fase 1 la dejó muerta —su nota decía «Todavía no\n   * se puede seguir una tienda del Mercado»— porque entonces era la verdad: no había dónde guardar\n   * un seguimiento. La Fase 6 construyó ese sitio (`wallet.ecomerse_store_follows`) y esta fila pasa\n   * a ser viva, con el mismo criterio que las de arriba: el contador sale del servidor, y cuando no\n   * se pudo preguntar la nota no afirma un cero.\n   */\n  const tiendasQueSigo: Acceso[] = useMemo(() => {\n    const nota =\n      nTiendas === null\n        ? 'Las tiendas del Mercado que sigues, juntas en un sitio.'\n        : nTiendas === 0\n          ? 'Todavía no sigues ninguna. Se sigue desde la página de cada tienda.'\n          : `${nTiendas} ${nTiendas === 1 ? 'tienda' : 'tiendas'}`;\n    return [\n      {\n        titulo: 'Tiendas que sigo',\n        nota,\n        icono: Store,\n        ruta: '/ecomerse-perfil-tiendas',\n      },\n    ];\n  }, [nTiendas]);\n\n  return (\n    <View style={[styles.raiz, { paddingTop: insets.top, backgroundColor: colors.background }]}>\n      <View style={[styles.cabecera, { borderBottomColor: colors.border }]}>\n        <Pressable\n          onPress={() => router.back()}\n          hitSlop={12}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Volver\"\n        >\n          <ArrowLeft size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.cabeceraTitulo, { color: colors.textPrimary }]}>Perfil</Text>\n        <Pressable\n          onPress={() => router.push('/edit-profile' as never)}\n          hitSlop={12}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Editar perfil\"\n        >\n          <Settings size={icono.lg} color={colors.textPrimary} />\n        </Pressable>\n      </View>\n\n      <ScrollView contentContainerStyle={{ paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e24 }}>\n        {/* Identidad */}\n        <View style={styles.identidad}>\n          <View style={[styles.avatar, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n            {yo?.avatarUrl ? (\n              <Image source={{ uri: yo.avatarUrl }} style={styles.avatarImg} contentFit=\"cover\" />\n            ) : (\n              <Text style={[styles.avatarLetra, { color: colors.textSecondary }]}>{inicial || '?'}</Text>\n            )}\n          </View>\n          <View style={styles.identidadTexto}>\n            <Text style={[styles.nombre, { color: colors.textPrimary }]} numberOfLines={1}>\n              {yo?.fullName?.trim() || (isAuthenticated ? 'Tu cuenta' : 'Sin sesión')}\n            </Text>\n            {/*\n              EL SUBTÍTULO NO PUEDE DECIR «Cargando…» CUANDO YA NO SE ESTÁ CARGANDO NADA. Antes era\n              `yo?.phone ? tel : isAuthenticated ? 'Cargando tus datos…' : …`, y con eso, si la\n              consulta fallaba —lo típico es abrir la app antes de que el aparato tenga red, que es\n              justo lo que pasó en la primera prueba—, la frase se quedaba ahí PARA SIEMPRE: el\n              perfil parecía estar cargando eternamente en vez de decir que había fallado. Se\n              distinguen los tres estados reales, y el de fallo se puede reintentar.\n            */}\n            {tel ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={1}>{tel}</Text>\n            ) : fallo ? (\n              <Pressable\n                onPress={() => void cargar()}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Reintentar la carga del perfil\"\n              >\n                <Text style={[styles.sub, { color: colors.primary }]} numberOfLines={1}>\n                  No se pudo cargar. Toca para reintentar\n                </Text>\n              </Pressable>\n            ) : (\n              <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={1}>\n                {isAuthenticated ? 'Cargando tus datos…' : 'Inicia sesión para ver tus pedidos'}\n              </Text>\n            )}\n          </View>\n          {cargando && <ActivityIndicator size=\"small\" color={colors.primary} />}\n          {!isAuthenticated && (\n            <Pressable\n              onPress={() => router.push('/auth' as never)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Iniciar sesión\"\n              style={[styles.entrar, { backgroundColor: colors.primary }]}\n            >\n              <Text style={styles.entrarTexto}>Entrar</Text>\n            </Pressable>\n          )}\n        </View>\n\n        {/*\n          MIS PEDIDOS, CON SUS CUATRO SECCIONES. Es lo que en la referencia ocupa la fila de 我的订单\n          (imagen #4): no un enlace a «todos mis pedidos» sino CUATRO puertas, cada una con lo que\n          hay dentro, porque «mis pedidos» no es una lista, son cuatro preguntas distintas. Cada\n          ficha lleva al MISMO sitio con el filtro ya puesto, y ese id sale del módulo compartido.\n        */}\n        <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <View style={styles.tarjetaCabecera}>\n            <Text style={[styles.tarjetaTitulo, { color: colors.textPrimary }]}>Mis pedidos</Text>\n            <Pressable\n              onPress={() => router.push('/ecomerse-orders' as never)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Ver todos los pedidos\"\n              style={({ pressed }) => [styles.verTodos, { opacity: pressed ? 0.6 : 1 }]}\n            >\n              <Text style={[styles.verTodosTexto, { color: colors.primary }]}>Ver todos</Text>\n              <ChevronRight size={icono.sm} color={colors.primary} />\n            </Pressable>\n          </View>\n\n          <View style={styles.secciones}>\n            {SECCIONES_COMPRA.map((s) => {\n              const Icono = ICONO_SECCION[s.id];\n              const n = nDe(s.id);\n              /* El contador del «Por valorar» puede venir SATURADO (el tope de una página de\n                 `myOrders`): se dice con un «+» en vez de enseñar un número que parece exacto. */\n              const saturado = s.id === 'valorar' && valorar?.truncado === true && n > 0;\n              const cifra = n > 99 ? '99+' : `${n}${saturado ? '+' : ''}`;\n              return (\n                <Pressable\n                  key={s.id}\n                  onPress={() => router.push(`/ecomerse-orders?filtro=${s.id}` as never)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`${s.label}: ${n ? `${saturado ? 'más de ' : ''}${n} ${n === 1 ? 'pedido' : 'pedidos'}` : 'ninguno'}. Abre la lista filtrada.`}\n                  style={({ pressed }) => [styles.seccion, { opacity: pressed ? 0.6 : 1 }]}\n                >\n                  <View>\n                    <Icono size={icono.lg} color={colors.textPrimary} />\n                    {n > 0 && (\n                      <View style={[styles.globo, { borderColor: colors.card }]}>\n                        <Text style={styles.globoTexto}>{cifra}</Text>\n                      </View>\n                    )}\n                  </View>\n                  {/* Dos líneas: «En preparación» no cabe en una a este ancho y partirlo a la mitad\n                      («En prepa-/ración») es peor que dejarlo bajar entero. */}\n                  <Text style={[styles.seccionLabel, { color: colors.textSecondary }]} numberOfLines={2}>\n                    {s.label}\n                  </Text>\n                </Pressable>\n              );\n            })}\n          </View>\n        </View>\n\n        <Bloque titulo=\"Entrega\" accesos={entrega} onIr={(r) => router.push(r as never)} />\n        {/* Va antes que «Guardado»: una reclamación abierta es algo que pide atención, y lo que pide\n            atención no se pone debajo de lo que se guarda. */}\n        <Bloque titulo=\"Reclamaciones\" accesos={reembolsos} onIr={(r) => router.push(r as never)} />\n        <Bloque titulo=\"Guardado\" accesos={GUARDADO} onIr={(r) => router.push(r as never)} />\n        {/* Después de «Guardado»: seguir una tienda es otra forma de quedarse con ella, junto a los\n            favoritos. La fila era la última muerta del perfil; con la Fase 6 pasa a la lista viva. */}\n        <Bloque titulo=\"Tiendas\" accesos={tiendasQueSigo} onIr={(r) => router.push(r as never)} />\n      </ScrollView>\n\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\nfunction Bloque({\n  titulo,\n  accesos,\n  onIr,\n}: {\n  titulo: string;\n  accesos: Acceso[];\n  onIr?: (ruta: string) => void;\n}) {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.bloque}>\n      <Text style={[styles.bloqueTitulo, { color: colors.textPrimary }]}>{titulo}</Text>\n      {accesos.map((a) => {\n        const Icono = a.icono;\n        const vivo = !!a.ruta && !!onIr;\n        const contenido = (\n          <>\n            <View style={[styles.filaIcono, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n              <Icono size={icono.sm} color={vivo ? colors.primary : colors.textSecondary} />\n            </View>\n            <View style={styles.filaTexto}>\n              <Text style={[styles.filaTitulo, { color: colors.textPrimary }]}>{a.titulo}</Text>\n              <Text style={[styles.filaNota, { color: colors.textSecondary }]}>{a.nota}</Text>\n            </View>\n            {vivo && <ChevronRight size={icono.sm} color={colors.textSecondary} />}\n          </>\n        );\n        return vivo ? (\n          <Pressable\n            key={a.titulo}\n            onPress={() => onIr!(a.ruta!)}\n            accessibilityRole=\"button\"\n            accessibilityLabel={a.titulo}\n            style={({ pressed }) => [styles.fila, { borderTopColor: colors.border, opacity: pressed ? 0.6 : 1 }]}\n          >\n            {contenido}\n          </Pressable>\n        ) : (\n          <View key={a.titulo} style={[styles.fila, { borderTopColor: colors.border }]}>\n            {contenido}\n          </View>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  cabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino,\n  },\n  cabeceraTitulo: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  identidad: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e16,\n  },\n  avatar: {\n    width: 56,\n    height: 56,\n    borderRadius: radios.full,\n    borderWidth: trazo.fino,\n    alignItems: 'center',\n    justifyContent: 'center',\n    overflow: 'hidden',\n  },\n  avatarImg: { width: '100%', height: '100%' },\n  avatarLetra: { fontSize: tipografia.title, fontWeight: peso.titulo },\n  identidadTexto: { flex: 1 },\n  nombre: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  sub: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  entrar: {\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e8,\n    borderRadius: radios.full,\n  },\n  entrarTexto: { color: brand.white, fontSize: tipografia.caption, fontWeight: peso.titulo },\n  /* La tarjeta de los pedidos: mismo cromo que las tarjetas del Mercado —`colors.card`, un borde\n     fino y una sombra— para que el perfil no parezca de otra app. */\n  tarjeta: {\n    marginHorizontal: espaciado.e16,\n    borderRadius: radios.lg,\n    borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e16,\n    paddingVertical: espaciado.e12,\n  },\n  tarjetaCabecera: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n  },\n  tarjetaTitulo: { fontSize: tipografia.body, fontWeight: peso.titulo },\n  verTodos: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 / 2 },\n  verTodosTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  secciones: {\n    flexDirection: 'row',\n    marginTop: espaciado.e16,\n    marginBottom: espaciado.e8,\n  },\n  seccion: { flex: 1, alignItems: 'center', gap: espaciado.e8 },\n  seccionLabel: { fontSize: tipografia.micro, textAlign: 'center' },\n  /* El globo del contador. El aro sale del TEMA (`colors.card`, el color real de la tarjeta) y no de\n     `brand.white`: así se despega del icono tanto en claro como en oscuro, que es el fallo que ya se\n     corrigió en `PieDelMercado.tsx`. */\n  globo: {\n    position: 'absolute',\n    top: -espaciado.e8,\n    right: -espaciado.e8,\n    backgroundColor: brand.like,\n    borderRadius: radios.full,\n    minWidth: espaciado.e16,\n    height: espaciado.e16,\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderWidth: trazo.base,\n    paddingHorizontal: espaciado.e4,\n  },\n  globoTexto: { color: brand.white, fontSize: tipografia.micro, fontWeight: peso.titulo },\n  bloque: { paddingHorizontal: espaciado.e16, marginTop: espaciado.e16 },\n  bloqueTitulo: { fontSize: tipografia.body, fontWeight: peso.titulo, marginBottom: espaciado.e8 },\n  fila: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n    paddingVertical: espaciado.e12,\n    borderTopWidth: trazo.fino,\n  },\n  filaIcono: {\n    width: 36,\n    height: 36,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  filaTexto: { flex: 1 },\n  filaTitulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  filaNota: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n});\n","/**\n * EcomersePlanesScreen — Tu tienda en Ecomerse (monetización v4.6, auditoría).\n * 4 niveles comparables (misma tabla de features ✓/✗), plan actual con\n * vencimiento, confirmación ANTES de cualquier cargo, destacado con PICKER de\n * producto (nunca [0] silencioso), destacado GRATIS real (sin cobro), duración\n * honesta (~XAF/día), copy sin promesas falsas (MM próximamente, aprobación\n * 2–24 h), estados de carga/error y guard sin tienda.\n * Ruta: /ecomerse-planes\n */\n\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport { Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Check, X } from 'lucide-react-native';\nimport { alpha, brand, EmptyState, espaciado, ilustracion, Precio, PrimaryButton, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseProduct, EcomerseShopPlan } from '../api/ecomerse';\nimport { billingApi, BillingPlan } from '../api/billing';\nimport { formatXAF } from '../utils/formatHelpers';\n\n/** Duración legible sin `else '1 mes'` (nunca miente). */\nfunction formatDuration(days: number | null | undefined): string {\n  const d = Number(days);\n  if (!Number.isFinite(d) || d <= 0) return '';\n  if (d % 30 === 0) return d === 30 ? '1 mes' : `${d / 30} meses`;\n  if (d % 7 === 0) return d === 7 ? '1 semana' : `${d / 7} semanas`;\n  return d === 1 ? '1 día' : `${d} días`;\n}\n\nconst SHOP_QUOTA_LABEL: Record<string, number> = {\n  ecomerse_shop_basic: 8, ecomerse_shop_flash: 16, ecomerse_shop_pro: 32, ecomerse_shop_pro_max: 100,\n};\n\nexport default function EcomersePlanesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  // Destacar llega con productId explícito (desde Mis productos); fallback al más reciente.\n  const rawPid = useLocalSearchParams<{ productId?: string | string[] }>().productId;\n  const presetPid = Array.isArray(rawPid) ? rawPid[0] : rawPid;\n  const [plan, setPlan] = useState<EcomerseShopPlan | null>(null);\n  const [bPlans, setBPlans] = useState<BillingPlan[]>([]);\n  const [myProducts, setMyProducts] = useState<EcomerseProduct[]>([]);\n  const [hasShop, setHasShop] = useState(true);\n  const [productId, setProductId] = useState<string | null>(presetPid ?? null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [busyFree, setBusyFree] = useState(false);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const [p, bp, me] = await Promise.all([\n        ecomerseApi.shopPlan(),\n        billingApi.plans('ecomerse'),\n        ecomerseApi.sellerMe(),\n      ]);\n      setPlan(p);\n      setBPlans(bp);\n      setHasShop(!!me.seller);\n      const products = (me.products ?? [])\n        .filter((x) => x.status === 'active')\n        .sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));\n      setMyProducts(products);\n      setProductId((cur) => cur && products.some((x) => x.id === cur) ? cur : (products[0]?.id ?? null));\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar tu tienda. Revisa la conexión.');\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const shopPlans = useMemo(\n    () => bPlans.filter((x) => x.code.startsWith('ecomerse_shop_') && x.active).sort((a, b) => a.priceXaf - b.priceXaf),\n    [bPlans],\n  );\n  const featPlans = useMemo(\n    () => bPlans.filter((x) => x.code.startsWith('ecomerse_featured') && x.active).sort((a, b) => a.priceXaf - b.priceXaf),\n    [bPlans],\n  );\n\n  const isCurrent = (pl: BillingPlan) => plan?.plan === pl.code;\n  const quotaUsed = plan?.used ?? 0;\n  const quotaLimit = plan?.limit ?? 0;\n  const nearLimit = quotaLimit > 0 && quotaUsed / quotaLimit >= 0.8;\n  const selected = myProducts.find((x) => x.id === productId);\n  const isPro = plan?.badge === true;\n  const expiresTxt = plan?.expiresAt ? new Date(plan.expiresAt).toLocaleDateString('es', { day: 'numeric', month: 'short' }) : null;\n\n  const goCheckout = (planId: string, targetType: string, targetId?: string) => {\n    router.push({ pathname: '/billing-checkout', params: { planId, module: 'ecomerse', targetType, ...(targetId ? { targetId } : {}) } } as any);\n  };\n\n  /** Confirmación SIEMPRE antes de crear un cargo. */\n  const chooseShop = (pl: BillingPlan) => {\n    if (isCurrent(pl) || pl.priceXaf === 0 || loading || error) return;\n    Alert.alert(\n      pl.name,\n      `Se creará un pago de ${formatXAF(pl.priceXaf)} por 30 días.\\n\\nCuando el admin apruebe el comprobante (suele tardar 2–24 h), se activa tu plan.`,\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Continuar', onPress: () => goCheckout(pl.id, 'user') },\n      ],\n    );\n  };\n\n  /** Destacar: PICKER + confirm con producto, duración y monto. */\n  const chooseFeatured = (fp: BillingPlan) => {\n    if (!selected) { Alert.alert('Destacar', 'Publica un anuncio activo primero.'); return; }\n    const extend = selected.isFeatured ? '\\n\\nExtenderá el destacado actual de este anuncio.' : '';\n    Alert.alert(\n      fp.name.replace('Destacar · ', ''),\n      `«${selected.title}» · ${formatDuration(fp.durationDays)} · ${formatXAF(fp.priceXaf)} (≈${formatXAF(Math.round(fp.priceXaf / Math.max(1, fp.durationDays)))}/día)${extend}`,\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Pagar', onPress: () => goCheckout(fp.id, 'product', selected.id) },\n      ],\n    );\n  };\n\n  /** Destacado GRATIS incluido en Pro/Pro Max: sin cobro, consume el crédito. */\n  const useFree = async () => {\n    if (!selected || !plan || (plan.freeFeaturedLeft ?? 0) <= 0 || busyFree) return;\n    setBusyFree(true);\n    try {\n      const r = await ecomerseApi.featureFree(selected.id);\n      Alert.alert('¡Listo!', `«${selected.title}» destacado ${r.days} días sin coste.`);\n      load();\n    } catch (e) {\n      Alert.alert('Destacado gratis', e instanceof Error ? e.message : 'No se pudo aplicar.');\n    } finally {\n      setBusyFree(false);\n    }\n  };\n\n  const s = styles(colors);\n\n  if (loading) {\n    return (\n      <View style={[s.root, { paddingTop: insets.top }]}>\n        {/* Esqueleto: sin `alVolver` el título queda centrado igual. */}\n        <ScreenHeader titulo=\"Tu tienda\" />\n        <View style={{ padding: espaciado.e16, gap: espaciado.e12 }}>\n          {[0, 1, 2, 3].map((i) => (\n            <View key={i} style={{ height: 120, borderRadius: radios.lg, backgroundColor: colors.border, opacity: 0.6 }} />\n          ))}\n        </View>\n      </View>\n    );\n  }\n\n  if (error) {\n    return (\n      <View style={[s.root, { paddingTop: insets.top }]}>\n        <ScreenHeader titulo=\"Tu tienda\" alVolver={() => router.back()} />\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e32 }}>\n          <Text style={{ fontSize: ilustracion.md, marginBottom: espaciado.e8 }}>📡</Text>\n          <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>No pudimos cargar tu tienda</Text>\n          <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 }}>{error}</Text>\n          <Pressable onPress={load} style={{ marginTop: espaciado.e18, backgroundColor: colors.primary, paddingHorizontal: espaciado.e20, paddingVertical: espaciado.e11, borderRadius: radios.full }}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  if (!hasShop) {\n    return (\n      <View style={[s.root, { paddingTop: insets.top }]}>\n        <ScreenHeader titulo=\"Tu tienda\" alVolver={() => router.back()} />\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e32 }}>\n          {/* Al kit. La acción se conserva y va PRIMARIA: es LA acción de esta pantalla. */}\n          <EmptyState\n            emoji=\"🏪\"\n            titulo=\"Todavía no tienes tienda\"\n            texto=\"Da de alta tu negocio (identidad verificada + aprobación del admin) para publicar y acceder a los planes.\"\n            accionLabel=\"Abrir mi tienda\"\n            accionPrimaria\n            onAccion={() => router.push('/ecomerse-seller' as any)}\n          />\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      <ScreenHeader titulo=\"Tu tienda\" alVolver={() => router.back()} />\n\n      <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }} showsVerticalScrollIndicator={false}>\n        {/* Estado actual */}\n        <View style={[s.current, { backgroundColor: alpha(colors.primary, 0.06) }]}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n            <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>🏪 {plan?.name ?? 'Tienda'}</Text>\n            {expiresTxt && <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>Activo hasta {expiresTxt}</Text>}\n          </View>\n          <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e4 }}>\n            {plan ? `${quotaUsed} de ${quotaLimit} publicaciones activas` : ''}\n            {isPro && (plan?.freeFeaturedLeft ?? 0) > 0 ? ` · ⭐ ${plan.freeFeaturedLeft} destacado gratis este mes` : ''}\n          </Text>\n          {nearLimit && (\n            <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: brand.secondary, marginTop: espaciado.e4 }}>\n              Estás al {Math.round((quotaUsed / quotaLimit) * 100)}% del límite: sube de plan para seguir publicando.\n            </Text>\n          )}\n        </View>\n\n        {/* Niveles de tienda (misma tabla de features en los 4) */}\n        <Text style={s.sectionTitle}>Niveles de tienda</Text>\n        <View style={{ gap: espaciado.e10 }}>\n          {shopPlans.map((pl) => {\n            const f = (pl.features ?? {}) as Record<string, unknown>;\n            const current = isCurrent(pl);\n            const isFree = pl.priceXaf === 0;\n            const quota = Number.isFinite(Number(f.shopQuota)) ? Number(f.shopQuota) : (SHOP_QUOTA_LABEL[pl.code] ?? 8);\n            const recommended = pl.code === 'ecomerse_shop_pro';\n            return (\n              <View key={pl.code} style={[s.card, { borderColor: current ? colors.primary : colors.border }]}>\n                <View style={s.cardHead}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, flex: 1, flexWrap: 'wrap' }}>\n                    <Text style={s.cardName}>{pl.name}</Text>\n                    {current && <View style={s.tagCurrent}><Text style={s.tagCurrentText}>Actual</Text></View>}\n                    {recommended && !current && <View style={s.tagRec}><Text style={s.tagRecText}>Recomendado</Text></View>}\n                  </View>\n                  {/* Precio de FIGURA. El `/mes` ya no se construye a mano con un `<Text>` anidado:\n                      es el `periodo` de la primitiva, que lo pinta con el mismo trato que la unidad\n                      (mismo cuerpo, mismo peso) para que el periodo no compita con el importe.\n                      Un plan gratis enseña «0 XAF» y **sin** periodo: el cero es un precio de\n                      verdad, lo que no tiene sentido es decir que cuesta 0 al mes. */}\n                  <Precio\n                    valor={pl.priceXaf}\n                    periodo={isFree ? undefined : '/mes'}\n                  />\n                </View>\n                <FeatureRow ok label={`${quota} publicaciones activas`} />\n                <FeatureRow ok={!!f.shopBadge} label=\"Badge «Tienda Pro» en tus anuncios\" />\n                <FeatureRow ok={!!f.priority} label=\"Prioridad en búsquedas\" />\n                <FeatureRow ok={Number(f.monthlyFeatured) > 0} label={`${Number(f.monthlyFeatured) || 0} destacado gratis al mes`} />\n                {isFree ? (\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textSecondary, marginTop: espaciado.e10 }}>\n                    ✓ Incluida · {quota} publicaciones\n                  </Text>\n                ) : current ? (\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.primary, marginTop: espaciado.e10 }}>\n                    ✓ Plan actual{expiresTxt ? ` · renueva ${expiresTxt}` : ''}\n                  </Text>\n                ) : (\n                  <View style={{ marginTop: espaciado.e10 }}>\n                    <PrimaryButton title={`Pasar a ${pl.name} · ${formatXAF(pl.priceXaf)}/mes`} onPress={() => chooseShop(pl)} />\n                  </View>\n                )}\n              </View>\n            );\n          })}\n        </View>\n        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e8 }}>\n          ¿Quieres bajar de plan o cancelar la renovación? Escribe a soporte y lo gestionamos.\n        </Text>\n\n        {/* Destacar anuncio */}\n        <Text style={[s.sectionTitle, { marginTop: espaciado.e22 }]}>🔥 Destacar un anuncio</Text>\n        <View style={[s.card, { borderColor: colors.border }]}>\n          <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, lineHeight: 17, marginBottom: espaciado.e8 }}>\n            Elige el anuncio y el nivel. Aparece arriba de los resultados y en Recomendados durante la duración.\n          </Text>\n\n          {/* Picker de producto (radios) */}\n          <Text style={[s.label, { marginBottom: espaciado.e4 }]}>1 · Elige el anuncio</Text>\n          {myProducts.length === 0 ? (\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginBottom: espaciado.e8 }}>\n              No tienes anuncios activos. Publica primero para poder destacarlo.\n            </Text>\n          ) : (\n            <View style={{ gap: espaciado.e6, marginBottom: espaciado.e10 }}>\n              {myProducts.map((p) => {\n                const on = productId === p.id;\n                return (\n                  <Pressable key={p.id} onPress={() => setProductId(p.id)} accessibilityRole=\"radio\" accessibilityState={{ checked: on }}\n                    style={[s.prodRow, { borderColor: on ? colors.primary : colors.border, backgroundColor: on ? alpha(colors.primary, 0.06) : colors.surface }]}>\n                    {p.photos?.[0] ? (\n                      <Image source={{ uri: p.photos[0] }} style={{ width: 40, height: 40, borderRadius: radios.sm, backgroundColor: colors.border }} contentFit=\"cover\" />\n                    ) : (\n                      <View style={{ width: 40, height: 40, borderRadius: radios.sm, backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }}>\n                        <Text style={{ fontSize: ilustracion.sm }}>{p.categoryIcon ?? '📦'}</Text>\n                      </View>\n                    )}\n                    <View style={{ flex: 1, marginLeft: espaciado.e8 }}>\n                      <Text numberOfLines={1} style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>{p.title}</Text>\n                      <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>\n                        {p.city}{p.isFeatured ? ' · 🔥 ya destacado (se extiende)' : ''}\n                      </Text>\n                    </View>\n                    <View style={[s.radio, { borderColor: on ? colors.primary : colors.border }]}>\n                      {on && <View style={[s.radioDot, { backgroundColor: colors.primary }]} />}\n                    </View>\n                  </Pressable>\n                );\n              })}\n            </View>\n          )}\n\n          {/* Destacado gratis (sin cobro) */}\n          {isPro && (plan?.freeFeaturedLeft ?? 0) > 0 && selected && (\n            <Pressable onPress={useFree} disabled={busyFree} accessibilityRole=\"button\"\n              accessibilityLabel={`Usar ${plan?.freeFeaturedLeft} destacado gratis en ${selected.title}`}\n              style={[s.freeBtn, { backgroundColor: alpha(brand.secondary, 0.12), borderColor: brand.secondary }]}>\n              <Text style={{ color: brand.secondary, fontSize: tipografia.caption, fontWeight: '900' }}>\n                ⭐ Usar {plan?.freeFeaturedLeft} destacado incluido (7 días, sin coste){busyFree ? '…' : ''}\n              </Text>\n            </Pressable>\n          )}\n\n          {/* Escalera de niveles */}\n          <Text style={[s.label, { marginBottom: espaciado.e4, marginTop: espaciado.e6 }]}>2 · Elige el nivel</Text>\n          <View style={{ gap: espaciado.e4 }}>\n            {featPlans.map((fp) => (\n              <Pressable key={fp.code} onPress={() => chooseFeatured(fp)} disabled={!selected}\n                accessibilityRole=\"button\" accessibilityState={{ disabled: !selected }}\n                accessibilityLabel={`${fp.name} ${formatXAF(fp.priceXaf)} ${formatDuration(fp.durationDays)}`}\n                style={[s.featRow, { borderBottomColor: colors.border, opacity: selected ? 1 : 0.5 }]}>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>{fp.name.replace('Destacar · ', '')}</Text>\n                  <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>\n                    {formatDuration(fp.durationDays)} · ≈{formatXAF(Math.round(fp.priceXaf / Math.max(1, fp.durationDays)))}/día\n                  </Text>\n                </View>\n                <Precio valor={fp.priceXaf} />\n              </Pressable>\n            ))}\n          </View>\n        </View>\n\n        {/* Cómo funciona (sin promesas falsas) */}\n        <Text style={[s.sectionTitle, { marginTop: espaciado.e22 }]}>Cómo funciona</Text>\n        <View style={{ backgroundColor: colors.surface, borderRadius: radios.md, padding: espaciado.e12 }}>\n          <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, lineHeight: 18 }}>\n            1. Eliges tu nivel o un destacado → se crea tu pedido de pago (XAF).{'\\n'}\n            2. Pagas por transferencia ahora (Mobile Money en activación) y subes el comprobante.{'\\n'}\n            3. Te avisamos cuando el admin apruebe (suele tardar 2–24 h); el plan o el destacado se activa.{'\\n'}\n            4. Los planes de tienda se renuevan cada mes; el destacado dura lo elegido.\n          </Text>\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n\nfunction FeatureRow({ ok, label }: { ok: boolean; label: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e3 }}>\n      {ok ? <Check size={14} color={brand.success} /> : <X size={14} color=\"#CBD5E1\" />}\n      <Text style={{ fontSize: tipografia.caption, color: ok ? colors.textPrimary : colors.textSecondary, marginLeft: espaciado.e7, flex: 1 }}>{label}</Text>\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  current: { borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e16 },\n  sectionTitle: { fontSize: tipografia.body, fontWeight: '800', color: c.textPrimary, marginBottom: espaciado.e8 },\n  label: { fontSize: tipografia.caption, fontWeight: '800', color: c.textSecondary },\n  card: { backgroundColor: c.card, borderRadius: radios.lg, borderWidth: 1.5, padding: espaciado.e14 },\n  cardHead: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: espaciado.e8 },\n  cardName: { fontSize: tipografia.body, fontWeight: '900', color: c.textPrimary },\n  /* `cardPrice` y `cardPeriod` se fueron con la primitiva `Precio`: el par cifra+unidad y el\n     `/mes` ya no se escriben aquí. Eran, además, el último sitio del módulo que se construía el\n     periodo a mano. */\n  tagCurrent: { backgroundColor: 'rgba(16,185,129,0.12)', borderRadius: radios.sm, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2 },\n  tagCurrentText: { color: brand.success, fontSize: tipografia.micro, fontWeight: '900' },\n  tagRec: { backgroundColor: 'rgba(255,107,53,0.14)', borderRadius: radios.sm, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2 },\n  tagRecText: { color: brand.secondary, fontSize: tipografia.micro, fontWeight: '900' },\n  prodRow: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, borderWidth: 1, padding: espaciado.e8 },\n  radio: { width: 18, height: 18, borderRadius: radios.full, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center' },\n  radioDot: { width: 10, height: 10, borderRadius: radios.full },\n  freeBtn: { borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e9, alignItems: 'center', marginBottom: espaciado.e8 },\n  featRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: espaciado.e9, borderBottomWidth: 1 },\n});\n","/**\n * `/ecomerse-seller` — PUERTA ANTIGUA de la tienda del comerciante. Redirige a la zona.\n *\n * POR QUÉ SIGUE EXISTIENDO\n * Era la pantalla entera de «Mi tienda»: 1.110 líneas en una sola vista (requisitos + datos del\n * negocio + formulario de seis secciones + mis productos + plan). El 20-sep-2026 se partió en la\n * zona `/tienda`, que es un modo con barra propia, y su contenido se repartió: el formulario en\n * `publicar`, los anuncios en `anuncios`, las ventas en `pedidos` y el negocio en `perfil`.\n *\n * En vez de borrar la ruta —que está escrita en cuatro sitios de la app y en el historial de\n * navegación de los móviles ya instalados—, se deja como **redirección**: quien llegue por un enlace\n * viejo aterriza en la zona, no en un «Unmatched Route» en inglés (el fallo que ya encontramos una\n * vez con `/emergencia`: `components/ServiceGrid.tsx:45-53`).\n */\n\nimport React from 'react';\nimport { Redirect } from 'expo-router';\n\nexport default function EcomerseSellerRedirect() {\n  return <Redirect href={'/tienda' as never} />;\n}\n","/**\n * EcomerseSubcategoriaScreen — la pantalla de una subcategoría del Mercado.\n * Ruta: /ecomerse-subcategoria?id=<familyId>&nombre=<rótulo>\n *\n * ── QUÉ ES, Y QUÉ HABÍA ANTES ────────────────────────────────────────────────────────────────────\n * Es el TERCER ESCALÓN del árbol: departamento → familia → subclase. Se entra tocando una familia en\n * la rejilla de la home (`app/ecomerse.tsx`, `abrirFamilia`).\n *\n * Antes de esto se probaron dos formas que NO son esta, y las dos se vieron en el móvil:\n *   1. una **fila de chips** dentro de la home, con un caret que la abría en el sitio;\n *   2. una **hoja modal** (`<Sheet>` del kit) con el nombre de la familia en el encabezado y sus\n *      clases debajo.\n * Bernardo las corrigió en ese orden: «cada clic en una subcategoría debería abrirse un modal» y\n * después «me equivoqué en decir que el modal, si no que **una pantalla completa**, en la cual en la\n * parte superior se ubica el nombre de la subcategoría y por debajo se irán ubicando cada subclase de\n * la subcategoría **mostrando los productos que efectivamente pertenecen a esta subclase**».\n *\n * El motivo por el que una hoja no valía está en la última frase: **lo que se viene a ver son los\n * productos**. Una hoja sobre el catálogo enseña la lista de subclases y tapa el catálogo; una\n * pantalla puede enseñar las dos cosas —el nombre de la subclase y, debajo, sus productos—, y la\n * familia más larga del árbol vivo tiene 16 subclases (36 familias con 1-3, 66 con 4-6, 3 con 7-9,\n * 4 con 10-14 y 1 con 16), que no caben en ninguna hoja junto con sus productos.\n *\n * ── LENGUAJE: «SUBCATEGORÍA» Y «SUBCLASE» ────────────────────────────────────────────────────────\n * Lo fijó Bernardo y hay que respetarlo, porque el árbol en código usa otro vocabulario:\n *   · en la app, «departamento» (Hombre) y «familia» (Pantalones);\n *   · en su lengua, **la categoría es Hombre, la subcategoría es Pantalones y las subclases son\n *     Vaqueros y las demás**.\n * O sea: esta pantalla se titula con la FAMILIA y sus apartados son las HOJAS. En los comentarios de\n * este archivo se usan los dos nombres a la vez a propósito, para que nadie tenga que traducir.\n *\n * ── DE DÓNDE SALEN LOS DATOS: UNA PETICIÓN, NINGÚN ENDPOINT NUEVO ─────────────────────────────────\n *   · `categories()` da el árbol —el rótulo de la familia y **el orden de sus subclases**—.\n *   · `catalog({ family })` da todos los productos de la familia, y cada producto ya viene con\n *     `leafId` y `leafLabel` (lo comprobó el servidor: `mapProduct` en\n *     `_f6-serv/ecomerse.service.ts`, verificado en vivo con HTTP 200).\n * Con eso, repartir los productos por subclase es agrupar en memoria. **No hay que tocar el backend**\n * y **no hay que pedir la lista otra vez al cambiar de subclase**, que es lo que costaría un filtro\n * por hoja mandado al servidor. Esa comodidad es la razón de que el store ya no tenga `leafFilter`.\n *\n * ── LA SUBCLASE NO ES UN CAMPO OBLIGATORIO DEL ANUNCIO, Y ESO SE VE ───────────────────────────────\n * Medido sobre el catálogo vivo: de 9 productos activos, **5 no tienen subclase** (y uno ni familia).\n * Es un estado legítimo —el vendedor publica y elige subclase si quiere—, así que los productos que\n * no la tienen se agrupan **al final, bajo el nombre de la subcategoría**: pertenecen a ella aunque\n * no pertenezcan a ninguna de sus partes, y esconderlos sería que la pantalla enseñara menos que el\n * catálogo del que se viene. NO llevan ningún aviso ni contador: el encabezado es el nombre de la\n * subcategoría y nada más.\n *\n * Si un día el administrador reordena el árbol, el orden de los apartados cambia solo: sale de\n * `hojas`, no del catálogo. Y si `categories()` falla pero el catálogo llega, los apartados se\n * reconstruyen con el `leafLabel` que trae cada producto —la pantalla se degrada, no se rompe—.\n *\n * ── POR QUÉ UNA LISTA PLANA Y NO UN `SectionList` ────────────────────────────────────────────────\n * Porque React Native 0.79 **no tiene `numColumns` en `SectionList`** (solo en `FlatList`), y las\n * tarjetas del Mercado van a dos columnas. Las salidas eran tres, y las tres se miraron: pintar cada\n * apartado con un `View` de `flexWrap` por dentro pierde la virtualización —una familia con 500\n * productos montaría 500 tarjetas—; un `<ScrollView>` con todo dentro, lo mismo; y `SectionList` a\n * una columna contradice al resto del Mercado. Así que la lista es **una `FlatList` plana cuyos\n * elementos son o una cabecera de subclase o una fila de hasta dos tarjetas** —el truco es de una\n * línea y es el que ya usa la home para su hueco impar—.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport {\n  useTheme, EmptyState, InlineError, espaciado, peso, tipografia, trazo,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseCategory, EcomerseProduct } from '../api/ecomerse';\nimport { TarjetaProducto, EsqueletoTarjeta } from '../components/ecomerse/TarjetaProducto';\nimport { useAccionesProducto } from '../components/ecomerse/useAccionesProducto';\n\n/** El orden del catálogo, el mismo que manda la home: el valor por defecto del servidor, explícito\n *  para que el contrato se lea en la llamada. Un orden distinto aquí haría que la misma familia\n *  saliera ordenada de dos maneras según la pantalla. */\nconst SORT_CATALOGO = 'recommended';\n\n/** Las filas de tarjetas que se pintan mientras carga. Dos filas de dos, como la rejilla del Mercado:\n *  un esqueleto que no mide lo que va a medir el contenido hace saltar la pantalla al llegar. */\nconst FILAS_ESQUELETO = [0, 1];\n\n/** Una fila de la lista: o el nombre de una subclase, o hasta dos tarjetas. */\ntype Fila =\n  | { tipo: 'subclase'; id: string; label: string }\n  | { tipo: 'productos'; id: string; items: EcomerseProduct[] };\n\n/**\n * Reparte los productos de la familia por subclase y los deja en el orden de la lista.\n *\n * El orden de los apartados sale del ÁRBOL (`hojas`), que es el que decidió el administrador, y no\n * del catálogo: si saliera del catálogo, el mismo vendedor publicando cambiaría el orden de la\n * pantalla. Las subclases **sin productos no se pintan** —un apartado vacío es ruido, y hoy hay\n * familias enteras sin un solo producto—.\n */\nfunction repartir(\n  productos: EcomerseProduct[],\n  hojas: { id: string; label: string }[],\n  rotuloFamilia: string,\n): Fila[] {\n  const porSubclase = new Map<string, EcomerseProduct[]>();\n  const sinSubclase: EcomerseProduct[] = [];\n  for (const p of productos) {\n    if (!p.leafId) { sinSubclase.push(p); continue; }\n    const lista = porSubclase.get(p.leafId);\n    if (lista) lista.push(p); else porSubclase.set(p.leafId, [p]);\n  }\n\n  const filas: Fila[] = [];\n  const apartado = (clave: string, label: string, items: EcomerseProduct[]) => {\n    filas.push({ tipo: 'subclase', id: `s_${clave}`, label });\n    for (let i = 0; i < items.length; i += 2) {\n      filas.push({ tipo: 'productos', id: `f_${items[i].id}`, items: items.slice(i, i + 2) });\n    }\n  };\n\n  for (const h of hojas) {\n    const items = porSubclase.get(h.id);\n    if (items?.length) { apartado(h.id, h.label, items); porSubclase.delete(h.id); }\n  }\n  /* Las subclases que traen productos y NO están en el árbol: pasa cuando el árbol no ha llegado (la\n     llamada falló) o cuando el servidor tiene una hoja que el catálogo ya no lista. Se pintan con el\n     rótulo que trae el propio producto, que es mejor que perder el producto. */\n  for (const [clave, items] of porSubclase) {\n    apartado(clave, items[0].leafLabel || rotuloFamilia, items);\n  }\n  if (sinSubclase.length) apartado('sin_subclase', rotuloFamilia, sinSubclase);\n  return filas;\n}\n\nexport default function EcomerseSubcategoriaScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const s = styles(colors);\n  const { favIds, abrirFicha, alternarFavorito, anadirAlCarrito } = useAccionesProducto();\n\n  /* El nombre llega en los parámetros y NO se espera al árbol para poder escribir el encabezado: con\n     el id solo, la cabecera estaría vacía hasta que contestara el servidor. Si la pantalla se abre\n     por enlace directo (sin `nombre`), el rótulo sale del árbol y, en el peor caso, del producto. */\n  const params = useLocalSearchParams<{ id?: string; nombre?: string }>();\n  const id = typeof params.id === 'string' ? params.id : '';\n  const nombreParam = typeof params.nombre === 'string' ? params.nombre : '';\n\n  const [cats, setCats] = useState<EcomerseCategory[]>([]);\n  const [productos, setProductos] = useState<EcomerseProduct[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    if (!id) {\n      setError('No sabemos qué subcategoría abrir.');\n      setLoading(false);\n      return;\n    }\n    setLoading(true);\n    setError(null);\n    try {\n      /* Las dos en paralelo: son independientes y encadenarlas costaba dos viajes de red seguidos. */\n      const [arbol, lista] = await Promise.all([\n        ecomerseApi.categories(),\n        ecomerseApi.catalog({ family: id, sort: SORT_CATALOGO }),\n      ]);\n      setCats(arbol);\n      setProductos(lista);\n    } catch {\n      setError('No pudimos cargar esta subcategoría. Revisa tu conexión e inténtalo de nuevo.');\n      setProductos([]);\n    } finally {\n      setLoading(false);\n    }\n  }, [id]);\n\n  useEffect(() => { void load(); }, [load]);\n\n  /** La familia y sus subclases. Se busca por `id` en el árbol en vez de guardarla: el árbol se\n   *  vuelve a servir en cada carga y un objeto guardado es el que se queda obsoleto. */\n  const familia = useMemo(() => {\n    for (const c of cats) {\n      const f = c.familias?.find((x) => x.id === id);\n      if (f) return f;\n    }\n    return undefined;\n  }, [cats, id]);\n\n  /* El rótulo de la cabecera, por orden de fiabilidad: el árbol (lo que el servidor dice hoy), el\n     parámetro con el que se llegó (lo que decía la rejilla), el del primer producto, y por último\n     una palabra que no engañe a nadie. */\n  const rotulo = familia?.label || nombreParam || productos[0]?.familyLabel || 'Subcategoría';\n\n  const filas = useMemo(\n    () => repartir(productos, familia?.hojas ?? [], rotulo),\n    [productos, familia, rotulo],\n  );\n\n  const hayProductos = filas.length > 0;\n  const cargandoEnSeco = loading && !hayProductos;\n\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* La cabecera: el nombre de la subcategoría y el camino de vuelta. Sin contador y sin aviso —\n          lo pidió explícito: «un aviso no es necesario que pongas». */}\n      <View style={s.header}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.headerTitle} numberOfLines={1}>{rotulo}</Text>\n      </View>\n\n      {cargandoEnSeco ? (\n        <View style={s.esqueleto}>\n          {FILAS_ESQUELETO.map((f) => (\n            <View key={f} style={s.filaEsqueleto}>\n              <EsqueletoTarjeta />\n              <EsqueletoTarjeta />\n            </View>\n          ))}\n        </View>\n      ) : (\n        <FlatList\n          data={filas}\n          keyExtractor={(f) => f.id}\n          contentContainerStyle={[s.lista, { paddingBottom: insets.bottom + espaciado.e32 }]}\n          ListEmptyComponent={\n            error ? (\n              <View style={s.centrado}>\n                <InlineError mensaje={error} onReintentar={load} />\n              </View>\n            ) : (\n              /* El vacío es el estado NORMAL de casi todo el árbol hoy: 107 de las 110 familias no\n                 tienen un solo producto. Se dice sin dramatizar y con la vuelta a mano. */\n              <EmptyState\n                emoji=\"🛍️\"\n                titulo={`Todavía no hay productos en ${rotulo}`}\n                texto=\"Cuando un vendedor publique en esta subcategoría, aparecerá aquí.\"\n                accionLabel=\"← Volver al Mercado\"\n                onAccion={() => router.back()}\n              />\n            )\n          }\n          renderItem={({ item }) => {\n            if (item.tipo === 'subclase') {\n              return <Text style={s.subclase}>{item.label}</Text>;\n            }\n            return (\n              <View style={s.fila}>\n                {item.items.map((p) => (\n                  <TarjetaProducto\n                    key={p.id}\n                    product={p}\n                    favorited={favIds.includes(p.id)}\n                    onPress={() => abrirFicha(p.id)}\n                    onFav={() => alternarFavorito(p)}\n                    onAdd={() => anadirAlCarrito(p)}\n                  />\n                ))}\n                {/* La fila impar se completa con un hueco para que la tarjeta no se estire a lo ancho\n                    de la pantalla. Es el mismo recurso que el `__spacer__` de la home. */}\n                {item.items.length === 1 ? <View style={s.hueco} /> : null}\n              </View>\n            );\n          }}\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  /** El mismo alto y el mismo patrón que el directorio de tiendas: la pantalla se reconoce como\n   *  hermana suya y no como una variante de la home. */\n  header: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino, borderBottomColor: c.border },\n  headerTitle: { flex: 1, fontSize: tipografia.subtitle, fontWeight: peso.titulo, color: c.textPrimary },\n  lista: { paddingTop: espaciado.e8 },\n  /** El nombre de la subclase. `fuerte` (700) y no `titulo` (900) para no competir con la cabecera,\n   *  que también va en `subtitle`: la jerarquía la marca el peso, no el tamaño. */\n  subclase: { fontSize: tipografia.subtitle, fontWeight: peso.fuerte, color: c.textPrimary, paddingHorizontal: espaciado.e16, marginTop: espaciado.e16, marginBottom: espaciado.e8 },\n  fila: { flexDirection: 'row', gap: espaciado.e10, paddingHorizontal: espaciado.e16, marginBottom: espaciado.e10 },\n  hueco: { flex: 1 },\n  esqueleto: { gap: espaciado.e10, paddingTop: espaciado.e8 },\n  filaEsqueleto: { flexDirection: 'row', gap: espaciado.e10, paddingHorizontal: espaciado.e16 },\n  centrado: { paddingTop: 40, paddingHorizontal: espaciado.e32 },\n});\n","/**\n * EcomerseTiendaScreen — la página de una tienda: quién es y todo lo que vende.\n * Ruta: /ecomerse-tienda?id=<sellerId>&nombre=<opcional>\n *\n * POR QUÉ EXISTE: era la salida que faltaba. La ficha enseñaba la tienda y no dejaba entrar; el\n * directorio (`/ecomerse-tiendas`) enseña las tiendas y esta es donde se entra. Con las dos, el\n * Mercado pasa de «productos sueltos» a «productos y quién los vende».\n *\n * ── DE DÓNDE SALE CADA COSA (dos llamadas, cada una a lo suyo) ─────────────────────────────────\n *   · La CABECERA, de `GET /ecomerse/sellers/:id` — la tienda por sí sola.\n *   · Los ANUNCIOS, de `GET /ecomerse/catalog?sellerId=…` — solo los suyos.\n *\n * Antes era **una** llamada: el catálogo entero, filtrado en el cliente por `seller.id`. Eso tenía\n * dos consecuencias, y las dos se han cerrado con los dos endpoints nuevos:\n *   · Se descargaba **todo el Mercado** para pintar una tienda, y con `LIMIT 200` en el servidor los\n *     anuncios de esa tienda que cayeran fuera de esos 200 **desaparecían sin avisar**.\n *   · La cabecera se sacaba del **primer anuncio** encontrado. Una tienda activa **sin anuncios\n *     activos** se quedaba sin nombre, sin ciudad y sin escudo, con un hueco que se lee como «no ha\n *     cargado», y una tienda con anuncios **fuera** de esos 200 también. Ahora la tienda existe por\n *     sí sola y se pregunta aparte.\n *\n * ── LA CUENTA HONESTA DE LOS ANUNCIOS ─────────────────────────────────────────────────────────\n * El servidor cuenta los anuncios activos de la tienda (`anuncios`) y este catálogo sigue llevando\n * `LIMIT 200`. Con un censo de tres cifras, la cabecera puede decir «9 anuncios» y la rejilla\n * enseñar menos. En vez de taparlo, la sección **lo dice**: `Anuncios (N) · mostrando M`. Los dos\n * números son ciertos y se distingue el que manda el servidor del que ha llegado a la pantalla.\n *\n * ── EL PARÁMETRO `nombre` ES SOLO PARA PINTAR MIENTRAS CARGA ───────────────────────────────────\n * El nombre que manda la pantalla anterior es lo que se enseña en la cabecera **hasta que llega el\n * brief del servidor**; en cuanto llega, manda el del servidor. Es un `string` de conveniencia, no\n * un dato de verdad: si viene vacío o miente, se corrige solo en el primer render con datos.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport {\n  useTheme, EmptyState, InlineError, espaciado, peso, tipografia, trazo,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseProduct, EcomerseSellerCard, EcomerseSellerBrief } from '../api/ecomerse';\nimport { TarjetaProducto, EsqueletoTarjeta } from '../components/ecomerse/TarjetaProducto';\nimport { CabeceraTienda } from '../components/ecomerse/CabeceraTienda';\nimport { BotonPreguntarTienda } from '../components/ecomerse/BotonPreguntarTienda';\nimport { BotonSeguirTienda } from '../components/ecomerse/BotonSeguirTienda';\nimport { useAccionesProducto } from '../components/ecomerse/useAccionesProducto';\nimport { llamarTelefono } from '../utils/llamar';\n\nconst ESQUELETOS = [0, 1, 2, 3];\n\nexport default function EcomerseTiendaScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const s = styles(colors);\n  const { favIds, alternarFavorito, abrirFicha, anadirAlCarrito } = useAccionesProducto();\n\n  const raw = useLocalSearchParams<{ id?: string | string[]; nombre?: string | string[] }>();\n  const id = Array.isArray(raw.id) ? raw.id[0] : raw.id;\n  const nombreParam = Array.isArray(raw.nombre) ? raw.nombre[0] : raw.nombre;\n\n  const [productos, setProductos] = useState<EcomerseProduct[]>([]);\n  const [censo, setCenso] = useState<EcomerseSellerCard | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    if (!id) {\n      setError('No sabemos qué tienda abrir.');\n      setLoading(false);\n      return;\n    }\n    setLoading(true);\n    setError(null);\n    try {\n      const [tienda, anuncios] = await Promise.all([\n        /* La tienda por sí sola. Si no está activa contesta 404 y se sigue sin cabecera: la pantalla\n           no se inventa un nombre ni una valoración que el servidor no ha dado. El `catch` es solo\n           para eso — si lo que falla es la red, quien rompe es el catálogo y se cae al error. */\n        ecomerseApi.seller(id).catch(() => null),\n        ecomerseApi.catalog({ sellerId: id }),\n      ]);\n      setCenso(tienda);\n      setProductos(anuncios);\n    } catch {\n      setError('No pudimos cargar la tienda. Revisa tu conexión e inténtalo de nuevo.');\n      setProductos([]);\n      setCenso(null);\n    } finally {\n      setLoading(false);\n    }\n  }, [id]);\n\n  useEffect(() => { load(); }, [load]);\n\n  /* AQUÍ VIVÍAN DOS COPIAS DEL CORAZÓN, y las dos se retiraron el 24/09/2026 (Fase 2):\n       · el `useEffect` que sincronizaba `favIds` al montar, y\n       · `alternarFavorito`, con la sesión, la marca optimista y la vuelta atrás.\n     Las dos están ahora en `useAccionesProducto` y llegan juntas en la línea de arriba. Se van con\n     ellas la guarda de combinaciones que esta pantalla repetía en `onAdd` — y esa era la peor de las\n     tres copias: una guarda duplicada es una guarda que un día deja de coincidir con la otra. */\n\n  /* La cabecera sale de la tienda; el brief del primer anuncio queda como respaldo por si el\n     endpoint de la tienda no contestara (red a medias) — y entonces la cifra vuelve a ser la de la\n     lista cargada, que es lo único que se sabe con certeza. */\n  const seller: EcomerseSellerBrief | null = censo ?? productos[0]?.seller ?? null;\n  const nAnuncios = censo?.anuncios ?? productos.length;\n  const nombre = seller?.businessName ?? nombreParam ?? 'Tienda';\n  const telefono = seller?.phoneContact ?? null;\n  const vacia = !loading && !error && productos.length === 0;\n\n  const datos: EcomerseProduct[] = loading && productos.length === 0\n    ? ESQUELETOS.map((i) => ({ id: `__sk_${i}` } as EcomerseProduct))\n    : productos.length % 2 === 1\n      ? [...productos, { id: '__spacer__' } as EcomerseProduct]\n      : productos;\n\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      <View style={s.header}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.headerTitle} numberOfLines={1}>{nombre}</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <FlatList\n        data={datos}\n        keyExtractor={(item) => item.id}\n        numColumns={2}\n        columnWrapperStyle={s.colWrap}\n        contentContainerStyle={s.lista}\n        refreshing={loading && productos.length > 0}\n        onRefresh={load}\n        ListHeaderComponent={\n          <View style={s.cabecera}>\n            {/* Si no hay brief (tienda sin anuncios activos, o sin sesión de red) no se pinta la\n                tarjeta: la pantalla no se inventa una valoración ni una ciudad que no ha podido\n                leer. */}\n            {seller && (\n              <CabeceraTienda\n                seller={seller}\n                anuncios={nAnuncios}\n                onLlamar={telefono ? () => { void llamarTelefono(telefono); } : undefined}\n              />\n            )}\n            {/*\n              LA PUERTA AL CHAT, en el mismo sitio que en la ficha: debajo de quién vende. Aquí NO se\n              manda `productId` —se ha entrado a la tienda, no a un anuncio, así que no hay ninguno\n              que citar—, y esa diferencia es la razón de que el parámetro sea opcional: el mismo\n              botón sirve para los dos caminos sin una segunda versión del texto.\n              El margen no se pone a mano: el contenedor ya separa a sus hijos con `gap`.\n            */}\n            <BotonPreguntarTienda\n              sellerId={id}\n              nombre={seller?.businessName ?? nombreParam ?? null}\n              telefono={telefono}\n            />\n            {/*\n              EL SEGUIMIENTO (店铺关注), junto a la puerta del chat: las dos maneras de quedarse con\n              la tienda —hablarle ahora, o tenerla a mano después— viven juntas, debajo de quién\n              vende. El botón se encarga de todo (sesión, estado inicial, vuelta atrás); aquí solo se\n              coloca, con el mismo `gap` del contenedor que lo de arriba.\n            */}\n            <BotonSeguirTienda sellerId={id} nombre={seller?.businessName ?? nombreParam ?? null} />\n            {!loading && !error && nAnuncios > 0 && (\n              <Text style={s.tituloSeccion}>\n                Anuncios ({nAnuncios}){productos.length < nAnuncios ? ` · mostrando ${productos.length}` : ''}\n              </Text>\n            )}\n          </View>\n        }\n        ListEmptyComponent={\n          loading ? (\n            <View style={{ alignItems: 'center', paddingTop: 40 }}>\n              <ActivityIndicator color={colors.primary} />\n            </View>\n          ) : error ? (\n            <View style={{ paddingTop: espaciado.e24 }}>\n              <InlineError mensaje={error} onReintentar={load} />\n            </View>\n          ) : vacia ? (\n            <EmptyState\n              emoji=\"🏪\"\n              titulo={nombreParam ? `${nombreParam} no tiene anuncios` : 'Esta tienda no tiene anuncios'}\n              texto=\"La tienda existe, pero ahora mismo no tiene nada publicado. Vuelve a mirar más tarde.\"\n              accionLabel=\"Ver otras tiendas\"\n              onAccion={() => router.push('/ecomerse-tiendas' as any)}\n            />\n          ) : null\n        }\n        renderItem={({ item }) =>\n          item.id.startsWith('__sk_') ? (\n            <EsqueletoTarjeta />\n          ) : item.id === '__spacer__' ? (\n            <View style={{ flex: 1 }} />\n          ) : (\n            <TarjetaProducto\n              product={item}\n              favorited={favIds.includes(item.id)}\n              onPress={() => abrirFicha(item.id)}\n              onFav={() => alternarFavorito(item)}\n              /* Las dos acciones son UNA línea cada una porque el módulo común ya se hace cargo del\n                 resto: `abrirFicha` lleva a la ficha y `anadirAlCarrito` incluye la guarda de\n                 combinaciones (un anuncio con combinaciones no se añade desde la tarjeta: elegir es un\n                 paso que la tarjeta no puede dar). Antes la guarda estaba escrita aquí otra vez. */\n              onAdd={() => anadirAlCarrito(item)}\n            />\n          )\n        }\n      />\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino, borderBottomColor: c.border },\n  headerTitle: { flex: 1, textAlign: 'center', fontSize: tipografia.subtitle, fontWeight: peso.titulo, color: c.textPrimary },\n  colWrap: { gap: espaciado.e8, paddingHorizontal: espaciado.e16 },\n  lista: { gap: espaciado.e8, paddingBottom: espaciado.e32 },\n  cabecera: { paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, gap: espaciado.e12 },\n  tituloSeccion: { fontSize: tipografia.body, fontWeight: peso.titulo, color: c.textPrimary },\n});\n","/**\n * BotonSeguirTienda — seguir / dejar de seguir una tienda del Mercado (店铺关注).\n *\n * ── POR QUÉ ES UN COMPONENTE ──────────────────────────────────────────────────────────────────\n * El mismo botón con la misma secuencia va a vivir en la página de la tienda, y la lógica de un\n * toggle tiene ramas que se olvidan con facilidad: sin sesión, cargando el estado inicial, optimista\n * con vuelta atrás si el servidor dice que no, y el caso raro de que la tienda haya dejado de\n * existir. Escrita dos veces, la segunda acabaría con una rama de menos. Es el mismo criterio que\n * ya se aplicó con `BotonPreguntarTienda`.\n *\n * ── EL ESTADO INICIAL SE PREGUNTA, NO SE SUPONE ───────────────────────────────────────────────\n * El componente no sabe si se sigue la tienda hasta que `followingStoreIds()` contesta, y mientras\n * tanto no pinta un «Seguir» que podría ser mentira en el primer fotograma. Por eso el estado es\n * `null` hasta la primera respuesta, y el botón enseña un indicador en vez de un texto que aún no\n * sabe lo que dice.\n *\n * ── OPTIMISTA, PERO CON VUELTA ATRÁS ──────────────────────────────────────────────────────────\n * El cambio se pinta al instante y el servidor se llama después; si contesta mal, el estado vuelve\n * a lo que era Y el motivo se enseña (no se tapa con un genérico). Es el patrón de\n * `BotonPreguntarTienda` y de los corazones de favoritos: el motivo del servidor —«Esa es tu propia\n * tienda.», «Esa tienda no está disponible ahora mismo.»— ya está escrito para que lo lea quien toca\n * el botón, y cambiarlo por «no se pudo» convertiría un caso claro en un misterio.\n *\n * ── SIN SESIÓN SE EXPLICA, NO SE ROMPE ────────────────────────────────────────────────────────\n * Igual que al escribir a la tienda: sin cuenta no hay seguimiento, y el botón lo dice y ofrece\n * entrar, en vez de fallar en silencio o dejar un toggle que no hace nada.\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { Check, ChevronRight, Store } from 'lucide-react-native';\nimport { alpha, espaciado, icono, peso, radios, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi } from '../../api/ecomerse';\nimport { ApiError } from '../../api/httpClient';\nimport { useSession } from '../../state/session';\n\nexport interface BotonSeguirTiendaProps {\n  /** La TIENDA que se sigue. El servidor es quien decide si existe y si se puede seguir. */\n  sellerId: string | null | undefined;\n  /** Nombre de la tienda, para los textos de accesibilidad y los avisos. */\n  nombre?: string | null;\n  /** Separación con lo de arriba, si el contenedor del llamante no la da (un `gap`, por ejemplo). */\n  style?: StyleProp<ViewStyle>;\n}\n\nexport function BotonSeguirTienda({ sellerId, nombre, style }: BotonSeguirTiendaProps) {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const { isAuthenticated } = useSession();\n  /** `null` = aún no se sabe; `true/false` = lo que dice el servidor. */\n  const [siguiendo, setSiguiendo] = useState<boolean | null>(null);\n  const [trabajando, setTrabajando] = useState(false);\n  const s = styles(colors);\n\n  /**\n   * El estado inicial, SOLO con sesión. Sin sesión no hay seguimiento que preguntar: se queda en\n   * `null` y el botón, al tocarse, explica que hace falta cuenta. El efecto depende de `sellerId`\n   * porque la pantalla puede cambiar de tienda sin desmontar el botón.\n   */\n  useEffect(() => {\n    let vivo = true;\n    setSiguiendo(null);\n    if (!isAuthenticated || !sellerId) return undefined;\n    ecomerseApi.followingStoreIds()\n      .then((ids) => { if (vivo) setSiguiendo(ids.includes(sellerId)); })\n      .catch(() => { if (vivo) setSiguiendo(false); });\n    return () => { vivo = false; };\n  }, [isAuthenticated, sellerId]);\n\n  const alternar = useCallback(() => {\n    if (!sellerId) return;\n    if (!isAuthenticated) {\n      Alert.alert(\n        'Entra en tu cuenta',\n        'Para seguir tiendas hace falta sesión: la lista de «tiendas que sigo» va con tu cuenta.',\n        [{ text: 'Ahora no', style: 'cancel' }, { text: 'Iniciar sesión', onPress: () => router.push('/auth' as never) }],\n      );\n      return;\n    }\n    if (siguiendo === null || trabajando) return;\n    void (async () => {\n      const antes = siguiendo;\n      setSiguiendo(!antes);\n      setTrabajando(true);\n      try {\n        const r = await ecomerseApi.followStore(sellerId);\n        /* El servidor manda el estado REAL resultante; se pinta ese, no el optimista, por si\n           alguien más tocó el botón desde otra parte. */\n        setSiguiendo(r.following);\n      } catch (e) {\n        setSiguiendo(antes);\n        const motivo = e instanceof ApiError && e.message\n          ? e.message\n          : 'No se pudo actualizar. Revisa tu conexión e inténtalo otra vez.';\n        Alert.alert('Tiendas que sigo', motivo);\n      } finally {\n        setTrabajando(false);\n      }\n    })();\n  }, [sellerId, siguiendo, trabajando, isAuthenticated, router]);\n\n  /* Sin tienda no hay a quién seguir: no se pinta un botón que no puede llevar a ninguna parte. */\n  if (!sellerId) return null;\n\n  return (\n    <Pressable\n      onPress={alternar}\n      disabled={trabajando}\n      accessibilityRole=\"button\"\n      accessibilityLabel={\n        siguiendo\n          ? `Dejar de seguir la tienda ${nombre ?? ''}`.trim()\n          : `Seguir la tienda ${nombre ?? ''}`.trim()\n      }\n      accessibilityHint=\"Añade o quita la tienda de tu lista de tiendas que sigues\"\n      accessibilityState={{ busy: trabajando, selected: siguiendo === true }}\n      style={({ pressed }) => [s.caja, style, { backgroundColor: colors.surface, opacity: pressed ? 0.75 : 1 }]}\n    >\n      <View style={[s.icono, { backgroundColor: alpha(colors.primary, siguiendo ? 0.18 : 0.12) }]}>\n        <Store size={icono.sm} color={colors.primary} />\n      </View>\n      <View style={s.textos}>\n        {siguiendo === null ? (\n          <Text style={[s.titulo, { color: colors.textSecondary }]}>Comprobando…</Text>\n        ) : (\n          <>\n            <Text style={[s.titulo, { color: siguiendo ? colors.primary : colors.textPrimary }]}>\n              {siguiendo ? 'Siguiendo' : 'Seguir la tienda'}\n            </Text>\n            <Text style={[s.nota, { color: colors.textSecondary }]}>\n              {siguiendo ? 'Toca para dejar de seguirla' : 'Aparece en tu lista de tiendas que sigues'}\n            </Text>\n          </>\n        )}\n      </View>\n      {trabajando ? (\n        <ActivityIndicator size=\"small\" color={colors.primary} />\n      ) : siguiendo === null ? null : siguiendo ? (\n        <Check size={icono.sm} color={colors.primary} />\n      ) : (\n        <ChevronRight size={icono.sm} color={colors.textSecondary} />\n      )}\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  /* Sin `marginTop`: la separación con lo de arriba la pone quien lo coloca, igual que\n     `BotonPreguntarTienda` —un `gap` del contenedor o un `style` del llamante. */\n  caja: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e12,\n    borderRadius: radios.md,\n    borderWidth: trazo.fino,\n    borderColor: c.border,\n    padding: espaciado.e12,\n  },\n  icono: {\n    width: 36,\n    height: 36,\n    borderRadius: radios.md,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  textos: { flex: 1 },\n  titulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  nota: { fontSize: tipografia.micro, marginTop: espaciado.e4 },\n});\n","/**\n * EcomerseTiendasScreen — el directorio de tiendas del Mercado.\n * Ruta: /ecomerse-tiendas\n *\n * POR QUÉ EXISTE: el Mercado tenía catálogo, ficha, favoritos, pedidos y panel del vendedor, y **no\n * tenía forma de ver las tiendas**. El comprador veía productos sueltos; la única pista de que\n * detrás de cada anuncio hay un negocio con nombre, valoración y ciudad estaba enterrada en la\n * ficha, y encima sin salida. Esta pantalla es la puerta.\n *\n * ── DE DÓNDE SALE LA LISTA: DEL CENSO, NO DEL CATÁLOGO ─────────────────────────────────────────\n * De `GET /ecomerse/sellers`, que es la lista de **tiendas activas** (`wallet.ecomerse_sellers`).\n *\n * Antes esta pantalla **derivaba la lista del catálogo** agrupando por `seller.id`, y eso tenía dos\n * agujeros que estaban escritos en voz alta aquí mismo:\n *   · Una tienda **sin anuncios activos no aparecía**. No había de dónde sacarla: la lista salía de\n *     los anuncios. Por eso el rótulo decía «N tiendas · M anuncios» y **no** prometía un censo.\n *   · El catálogo devuelve `LIMIT 200`: por encima de 200 anuncios activos la lista **se quedaba\n *     corta sin avisar**.\n * Las dos están cerradas. El rótulo ahora sí dice la verdad que el servidor le manda:\n * **`total`** (tiendas que hay, no las que han llegado) y **`anuncios`**, contados sobre todo lo que\n * casa con el filtro. Y si el servidor recorta la página, la pantalla **lo dice** en vez de fingir\n * que esa es la lista entera: `sellers.length < total` es un caso previsto, no un imposible.\n *\n * ── ORDEN ─────────────────────────────────────────────────────────────────────────────────────\n * Lo decide **el servidor**, con el mismo criterio que el catálogo (tiendas de pago primero, luego\n * mejor valoradas, luego más vistas), para que el directorio no contradiga la rejilla que el\n * comprador acaba de ver. Ordenar por «más anuncios» habría sido más vistoso y menos cierto: no\n * sabemos cuánto vende nadie, y el número de anuncios lo mueve el vendedor en una tarde.\n *\n * ── LA FILA ES `CabeceraTienda` ───────────────────────────────────────────────────────────────\n * No hay una fila propia del directorio: cada tienda se pinta con **la misma tarjeta** que la ficha\n * y que la página de tienda. Tres consumidores, una definición — y si mañana se añade el logo de la\n * tienda, aparece en los tres sitios sin tocar ninguno.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, ChevronRight, Store } from 'lucide-react-native';\nimport {\n  useTheme, alpha, EmptyState, InlineError, espaciado, peso, radios, tipografia, trazo,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseSellerCard } from '../api/ecomerse';\nimport { CabeceraTienda } from '../components/ecomerse/CabeceraTienda';\n\nexport default function EcomerseTiendasScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const s = styles(colors);\n\n  const [tiendas, setTiendas] = useState<EcomerseSellerCard[]>([]);\n  /** Las cifras del SERVIDOR: cuántas tiendas hay y cuántos anuncios activos suman. No se derivan\n   *  de `tiendas.length`, que es solo lo que llegó en esta página. */\n  const [total, setTotal] = useState(0);\n  const [anuncios, setAnuncios] = useState(0);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const censo = await ecomerseApi.sellers();\n      setTiendas(censo.sellers);\n      setTotal(censo.total);\n      setAnuncios(censo.anuncios);\n    } catch {\n      setError('No pudimos cargar las tiendas. Revisa tu conexión e inténtalo de nuevo.');\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => { load(); }, [load]);\n\n  const recortada = tiendas.length < total;\n\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      <View style={s.header}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.headerTitle}>Tiendas</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <FlatList\n        data={tiendas}\n        keyExtractor={(t) => t.id}\n        contentContainerStyle={s.lista}\n        refreshing={loading && tiendas.length > 0}\n        onRefresh={load}\n        ListHeaderComponent={\n          <View>\n            {!error && !loading && (\n              <Text style={s.contador}>\n                {total} tienda{total === 1 ? '' : 's'} · {anuncios} anuncio{anuncios === 1 ? '' : 's'}\n                {recortada ? ` · mostrando ${tiendas.length}` : ''}\n              </Text>\n            )}\n\n            {/* La puerta del VENDEDOR. Antes vivía en el icono 🏪 de la cabecera del Mercado, y ese\n                icono es ahora esta pantalla. No se pierde: cambia de sitio y gana explicación — el\n                icono no decía si llevaba a «mi tienda» o a «las tiendas». Aquí dice las dos cosas y\n                cada una a su fila. */}\n            <Pressable\n              onPress={() => router.push('/ecomerse-seller' as any)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Mi tienda, publica y gestiona tus anuncios\"\n              style={[s.miTienda, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.25) }]}\n            >\n              <View style={[s.iconoMiTienda, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n                <Store size={20} color={colors.primary} />\n              </View>\n              <View style={{ flex: 1, marginLeft: espaciado.e12 }}>\n                <Text style={[s.miTiendaTitulo, { color: colors.textPrimary }]}>Mi tienda</Text>\n                <Text style={[s.miTiendaSub, { color: colors.textSecondary }]}>Publica y gestiona tus anuncios</Text>\n              </View>\n              <ChevronRight size={18} color={colors.primary} />\n            </Pressable>\n          </View>\n        }\n        ListEmptyComponent={\n          loading ? (\n            <View style={{ alignItems: 'center', paddingTop: 48 }}>\n              <ActivityIndicator color={colors.primary} />\n              <Text style={[s.miTiendaSub, { color: colors.textSecondary, marginTop: espaciado.e10 }]}>Cargando tiendas…</Text>\n            </View>\n          ) : error ? (\n            <View style={{ paddingTop: espaciado.e24 }}>\n              <InlineError mensaje={error} onReintentar={load} />\n            </View>\n          ) : (\n            <EmptyState\n              emoji=\"🏪\"\n              titulo=\"Todavía no hay tiendas\"\n              texto=\"Aquí aparecerán las tiendas que publiquen anuncios en el Mercado.\"\n              accionLabel=\"Publicar mi primer producto\"\n              accionPrimaria\n              onAccion={() => router.push('/ecomerse-seller' as any)}\n            />\n          )\n        }\n        renderItem={({ item }) => (\n          <CabeceraTienda\n            seller={item}\n            anuncios={item.anuncios}\n            onPress={() => router.push({ pathname: '/ecomerse-tienda', params: { id: item.id, nombre: item.businessName ?? '' } } as any)}\n          />\n        )}\n      />\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino, borderBottomColor: c.border },\n  headerTitle: { fontSize: tipografia.subtitle, fontWeight: peso.titulo, color: c.textPrimary },\n  lista: { gap: espaciado.e8, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e32 },\n  contador: { fontSize: tipografia.caption, color: c.textSecondary, paddingVertical: espaciado.e8 },\n  miTienda: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, borderWidth: trazo.fino, padding: espaciado.e12, marginBottom: espaciado.e8 },\n  iconoMiTienda: { width: 44, height: 44, borderRadius: radios.full, alignItems: 'center', justifyContent: 'center' },\n  miTiendaTitulo: { fontSize: tipografia.body, fontWeight: peso.fuerte },\n  miTiendaSub: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n});\n","/**\n * EcomerseScreen — Home del marketplace \"Mercado\" (estilo Xianyu adaptado GQ).\n * v5 (auditoría senior): error de red con Reintentar (nunca \"no hay productos\"),\n * sin datos stale al filtrar, subcategoría limpia al cambiar de categoría,\n * búsqueda server-side con debounce, favoritos con sesión, carrito siempre\n * navegable, sin teléfonos PII en el feed (WhatsApp solo en detalle), CTA\n * \"Añadir\" en tarjeta, grid par, a11y, pull-to-refresh, SafeArea y skeletons.\n * Ruta: /ecomerse\n */\n\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, Pressable, ScrollView, StyleSheet,\n  Text, TextInput, View,\n} from 'react-native';\nimport * as ImagePicker from 'expo-image-picker';\nimport { Image } from 'expo-image';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Camera, Heart, Search, ShoppingCart, Store } from 'lucide-react-native';\nimport { useTheme, alpha, EmptyState, InlineError, tipografia, radios, trazo, peso, espaciado, ilustracion } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseCategory, EcomerseFamily, EcomerseProduct } from '../api/ecomerse';\nimport { useEcomerseStore } from '../state/ecomerse';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { TarjetaProducto, EsqueletoTarjeta, ANCHO_CARRUSEL } from '../components/ecomerse/TarjetaProducto';\nimport PieDelMercado, { PIE_MERCADO_H } from '../components/ecomerse/PieDelMercado';\nimport { useSinLeerMercado } from '../components/ecomerse/useSinLeer';\nimport { useAccionesProducto } from '../components/ecomerse/useAccionesProducto';\n\n/**\n * LA ZONA DE CATEGORÍAS DE LA HOME — 23-sep-2026. Es la estructura de la referencia (Pinduoduo):\n * **pestañas de departamento pegadas a la barra de búsqueda y, debajo, la rejilla de familias de la\n * pestaña activa**. Sustituye a lo que había antes en este mismo sitio: un carril de ciudad, tres\n * chips de orden y una pila de avatares de categorías. Las tres cosas se retiraron a la vez y por el\n * mismo motivo: la cabecera gastaba cuatro filas en cromo y las categorías —que es a lo que se entra\n * al Mercado— empezaban demasiado abajo.\n *\n * LO QUE SE FUE, y qué se pierde con ello:\n *   · **Ciudad** (📍 + «Quitar filtro»). El filtro por ciudad **sigue existiendo en el servidor y en\n *     el `state`**, pero la home ya no lo ofrece: `catalog()` acepta `city` y el campo sigue en el\n *     store, así que devolverlo es volver a pintar la fila. Se retira de la vista, no del sistema.\n *   · **Chips de orden** (Recomendado · Mejor valorado · Novedades). El servidor **sigue ordenando**\n *     —se le manda `sort: 'recommended'`, que es su valor por defecto— y sigue aceptando los otros\n *     tres valores; lo que desaparece es el selector.\n *   · **Pila de avatares + «Ver todas (18)»**. Con las 18 pestañas a la vista, la hoja «Todas las\n *     categorías» era una segunda puerta al mismo sitio: se retiró con la pila, y con ella\n *     `CatCell`/`GRID_COLS` y su modal.\n *\n * Y EL TERCER ESCALÓN NO VIVE AQUÍ: **esta pantalla tiene los dos primeros** —departamento y familia—\n * y al tocar una familia **navega** a `/ecomerse-subcategoria`, que es donde están sus subclases con\n * los productos de cada una. Se probaron antes las dos formas de hacerlo sin cambiar de pantalla (una\n * fila de chips con un caret, y una hoja modal) y las dos se retiraron: la primera porque el caret no\n * cabía en la celda, la segunda porque una hoja sobre el catálogo no puede enseñar los productos.\n */\n/**\n * COLUMNAS DE LA REJILLA, Y POR QUÉ SON 4. Lo pidió Bernardo mirando la captura del móvil: «puedes\n * volver a hacer las letras un poco más pequeñas para que puedan caber sin usar puntos suspensivos».\n * Aquello se midió en vez de estimarse, y la medición cambió las dos cosas —la letra y las columnas—\n * porque el problema no era solo el tamaño.\n *\n * EL RÓTULO ES LARGO Y ANCHO, Y LAS DOS COSAS NO CABEN A LA VEZ. La referencia (Pinduoduo) usa 5\n * columnas porque sus rótulos miden 2-5 caracteres; los de este árbol miden **14 de mediana y 30 el\n * más largo**, y muchos son de tres y cuatro palabras. En 360 dp, 5 columnas dejan **63,2 dp** de\n * texto por celda. Contado sobre el árbol real (18 departamentos / 110 familias):\n *\n * | Configuración | Texto por celda | Por línea | Rótulos que pierden texto | Alto de celda |\n * |---|---|---|---|---|\n * | 5 col · `micro` (11) · 2 líneas — lo que había | 63,2 dp | 8 car. | **45 de 110 — 41 %** | 88 dp |\n * | 5 col · `rotulo` (9) · 3 líneas | 63,2 dp | 9 car. | 5 de 110 — 5 % | 96 dp |\n * | 5 col · 8,5 · 3 líneas | 63,2 dp | 10 car. | 1 de 110 — 1 % | 93 dp |\n * | **4 col · `rotulo` (9) · 3 líneas — lo que hay** | **80,0 dp** | **12 car.** | **0 de 110** | **96 dp** |\n * | 4 col · `rotulo` (9) · 2 líneas | 80,0 dp | 12 car. | 5 de 110 — 5 % | 82 dp |\n * | 3 col · 8,5 · 2 líneas | 108,0 dp | 17 car. | 1 de 110 | 80 dp |\n *\n * NINGUNA COMBINACIÓN DE 5 COLUMNAS LLEGA A CERO, ni bajando la letra a 8 (8 dp reales, ilegible). El\n * último que se resiste es **«Fontanería y electricidad»**: 25 caracteres en dos palabras de 10 y 12,\n * que a 63,2 dp no caben en tres líneas ni con la letra más pequeña que se puede defender.\n * O dicho al revés: a 5 columnas se puede bajar la letra hasta que el 99 % quepa, pero no el 100 %.\n * La cuarta columna es lo que compra el «sin puntos suspensivos» que se pidió.\n *\n * LO QUE CUESTA LA CUARTA COLUMNA, MEDIDO Y NO SUPUESTO (`_c10-filas-por-departamento.cjs`): 6 de los\n * 18 departamentos ganan una fila, y la rejilla pasa de **142 dp de media a 187** —+45 dp antes del\n * primer producto, y +120 en el peor (Deporte y aire libre, 15 familias)—. Se paga a cambio de que\n * **ninguno de los 110 rótulos pierda una letra**. La letra baja de 11 a 9 (10,35 dp reales con la\n * escala del sistema al 1,15) y sigue leyéndose.\n *\n * POR QUÉ 3 LÍNEAS Y NO 2. Con 2 líneas y letra 9 quedan 5 fuera; la tercera cuesta 14 dp de celda y\n * los deja entrar todos. Una celda más alta es un defecto menor que una palabra cortada, que es el\n * mismo criterio con el que ya se eligió `minHeight` en vez de `height`.\n *\n * LA MEDICIÓN, Y DOS TRAMPAS QUE HAY QUE RECORDAR. La tabla que había aquí antes decía 28 % a 5\n * columnas y venía de `_c6-medir-rotulos.cjs`. El número era falso por dos motivos, y los dos se\n * descubrieron **mirando el móvil**, no razonando:\n *   · aquel medidor **no partía las palabras por la mitad** y Android sí (en la captura se leía\n *     «Chaqu etas y ab…»), así que contaba como si cupieran;\n *   · el ancho por carácter estaba en **7,2 dp a `micro`** y el del teléfono real es **≈7,9**.\n * El bueno es `_c9-medir-letra-rejilla.cjs`: reproduce el píxel en los cuatro rótulos que se usaron de\n * control —«Supermercados» → «Supermercado»+«s» en 2 líneas, «Servicios del hogar» en 2, «Farmacias» y\n * «Abacería» en 1— y da **0 cortes** para lo que hay. La tabla de arriba sale de ahí. Y de paso: el\n * medidor es **conservador**, no exacto — predice 3 líneas para «Calzado infantil y juvenil» y el móvil\n * lo pinta en 2—, que es la dirección en la que conviene equivocarse.\n *\n * **Cambiar de opinión es cambiar esta constante**: nada más del archivo depende de ella\n * (`celda.width` se calcula con `100 / COLUMNAS_REJILLA`).\n */\nconst COLUMNAS_REJILLA = 4;\n/**\n * LÍNEAS DEL RÓTULO. Tres, y la tercera es la que hace falta para los rótulos de tres y cuatro\n * palabras —ver la tabla de `COLUMNAS_REJILLA`—. La celda reserva sitio para las tres aunque la\n * mayoría use dos: un rótulo que pide tres líneas dentro de una celda de dos no se lee, se adivina.\n */\nconst LINEAS_ROTULO = 3;\n/**\n * Diámetro de la miniatura de una familia en la rejilla. 48 dp es el mínimo táctil que recomienda\n * Android y el mismo que usaba el avatar de categoría que esto sustituye.\n *\n * NO SUBE con la cuarta columna, aunque la celda pase de 72 a 90 dp: hoy **109 de las 110 familias no\n * tienen imagen** (la resuelve el servidor desde una tienda de esa familia), así que subirla sería\n * pagar alto en todas las celdas por un hueco que casi nunca se pinta.\n */\nconst DIAM_FOTO_FAMILIA = 48;\n/**\n * ALTO DE LA CELDA, con la cuenta hecha y no estimada: **48 (foto) + 6 (respiro) + 3 líneas de\n * `rotulo` = 48 + 6 + 3 × 14 = 96 dp**. El alto de línea es el natural de Android (≈1,3 × 10,35 dp),\n * porque `celdaRotulo` no fija `lineHeight`.\n *\n * Existe por un caso que hay que resolver mirándolo: **hoy casi ninguna familia tiene imagen**. La\n * imagen la resuelve el servidor a partir de una tienda de esa familia, y con las tiendas que hay\n * eso da una celda con foto por cada 110. Si la celda midiera lo que mide su contenido, una fila con\n * una foto y tres sin ella quedaría a cuatro alturas distintas y el rótulo de las celdas sin foto\n * se pegaría al borde de arriba —se leería como un error de maquetación, no como «todavía no hay\n * logo»—. Con un mínimo común y el rótulo centrado verticalmente, **la celda sin imagen queda como\n * una celda con su nombre**, que es lo que es.\n *\n * ES `minHeight` Y NO `height`, a propósito. 96 dp cubre tres líneas **a la escala de referencia**;\n * con el `font_scale` del sistema al 1,3 esas tres líneas piden 102. Con `height` el rótulo se\n * cortaría; con `minHeight` la fila crece. Una fila más alta es un defecto menor que una palabra\n * cortada. Y como el mínimo es el peor caso real, en la práctica todas las filas miden 96.\n */\nconst ALTO_CELDA_FAMILIA = 96;\nconst MAX_PHOTO_MB = 8;\n/**\n * LA TARJETA SE MUDÓ. El velo, la proporción, las etiquetas y los controles viven ahora en\n * `components/ecomerse/TarjetaProducto.tsx`, porque estaban duplicados en tres sitios (rejilla,\n * carrusel y Favoritos) con tres aspectros distintos.\n *\n * Lo que hay que saber desde aquí, que es la pantalla que la usa:\n *\n * **La proporción la decide la cámara, no el gusto.** El alta de vendedor sube la foto tal cual sale\n * del dispositivo (`launchCameraAsync` sin `allowsEditing` ni `aspect`) y las cámaras Android\n * arrancan en 4:3, así que el catálogo se llena de fotos 3:4. Con el marco 2:3 anterior —más alto\n * que ancho— la tarjeta venía recortando **el 11 % del ancho de todas las fotos** sin avisar a\n * nadie. Con 3:4 el recorte es **cero** y el vendedor ve en el visor exactamente lo que verá el\n * comprador. La decisión completa está en `DECISION-PROPORCION-TARJETAS.md`.\n *\n * Lo que se paga a cambio es altura: la tarjeta baja de 236 a 209 dp, y con ella la imagen limpia de\n * cada una. A cambio entra más catálogo por pantalla.\n */\n\n/**\n * EL ORDEN DEL CATÁLOGO YA NO SE ELIGE DESDE LA HOME (23-sep-2026). Aquí vivía `SORTS` —los tres\n * chips «Recomendado · Mejor valorado · Novedades»—, construidos en la tanda A sobre el `sort` que\n * el servidor acepta desde siempre. Se retiraron con el resto del cromo de la cabecera, y la app\n * manda `sort: 'recommended'` fijo, que es el valor por defecto que el `switch` de\n * `ecomerse.service.ts` ya aplicaba cuando no llegaba nada.\n *\n * NO SE PERDIÓ CAPACIDAD: el servidor sigue aceptando `rating`, `newest`, `price_asc` y\n * `price_desc`, y los ids no cambiaron. Devolver el selector es volver a pintar los chips. Si algún\n * día se recupera, el sitio natural no es la cabecera —donde competía con las categorías— sino el\n * orden de la lista ya filtrada.\n */\nconst SORT_CATALOGO = 'recommended';\n\nconst PLACEHOLDER_CARDS = [0, 1, 2, 3];\n\nexport default function EcomerseScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  /** Los sin leer, para la insignia de «Mensajes» del pie. Ver `useSinLeer.ts`. */\n  const sinLeer = useSinLeerMercado();\n  const {\n    query, setQuery, categoryFilter, setCategoryFilter, subcategoryFilter, setSubcategoryFilter,\n    cart,\n  } = useEcomerseStore();\n  /**\n   * El corazón, la ficha, el carrito y el filtro de sesión de los favoritos. Aquí vivían escritos a\n   * mano; se mudaron a `components/ecomerse/useAccionesProducto.ts` cuando la pantalla de la\n   * subcategoría empezó a pintar **las mismas tarjetas** (ver ese archivo: el corazón tiene puerta de\n   * sesión, marca optimista y vuelta atrás, y eso no se copia).\n   */\n  const { favIds, abrirFicha, alternarFavorito, anadirAlCarrito } = useAccionesProducto();\n\n  const [products, setProducts] = useState<EcomerseProduct[]>([]);\n  const [recommended, setRecommended] = useState<EcomerseProduct[]>([]);\n  const [cats, setCats] = useState<EcomerseCategory[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  /* AQUÍ VIVIÓ `clasesAbiertas`, el estado de la hoja de clases, unas horas del 23-sep-2026. Se\n     retiró con la hoja entera al corregir Bernardo la forma: «me equivoqué en decir que el modal, si\n     no que una pantalla completa». El tercer escalón del árbol ya no se elige en un modal sobre el\n     catálogo, sino en su propia pantalla (`app/ecomerse-subcategoria.tsx`), y esta home solo tiene\n     que **navegar** a ella. Por eso no queda aquí ni el booleano ni la familia: los dos los tiene la\n     pantalla, que además los puede recibir por enlace directo. */\n  const [imageResults, setImageResults] = useState<EcomerseProduct[]>([]);\n  const [imageActive, setImageActive] = useState(false);\n  /* El fallo de la búsqueda por foto se guarda para enseñarlo EN la pantalla: antes se\n     convertía en una lista vacía + un Alert, o sea en un «no hay resultados» falso. */\n  const [imageError, setImageError] = useState<string | null>(null);\n  const [imageBusy, setImageBusy] = useState(false);\n\n  // Carga con debounce: búsqueda server-side + filtros. Nunca datos stale:\n  // se vacían los productos al empezar; recomendados son globales (sin ciudad).\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    setProducts([]);\n    try {\n      const q: Record<string, string> = {};\n      /* El árbol con sus dos nombres. El alias viejo (`category` -> familia) seguiría funcionando,\n         pero mandarlo con el nombre nuevo evita que dentro de seis meses alguien lea `category` y\n         crea que filtra por departamento.\n         El tercer escalón (`leaf`) ya no se manda desde aquí: la subclase se elige en la pantalla de\n         la subcategoría, que pide la familia entera y reparte en memoria. El servidor lo sigue\n         aceptando —no se ha tocado— por si algún día vuelve a hacer falta. */\n      if (categoryFilter) q.department = categoryFilter;\n      if (subcategoryFilter) q.family = subcategoryFilter;\n      const t = query.trim();\n      if (t) q.q = t;\n      /* El orden deja de ser una elección del usuario en la home; se manda el valor por defecto\n         del servidor, explícito, para que el contrato se lea en la llamada. Ver `SORT_CATALOGO`. */\n      q.sort = SORT_CATALOGO;\n      const [p, c, rec] = await Promise.all([\n        ecomerseApi.catalog(q),\n        ecomerseApi.categories(),\n        ecomerseApi.catalog({ sort: 'recommended' }),\n      ]);\n      setProducts(p);\n      setCats(c);\n      setRecommended(rec.slice(0, 8));\n    } catch {\n      setError('No pudimos cargar el mercado. Revisa tu conexión e inténtalo de nuevo.');\n      setProducts([]);\n      setRecommended([]);\n    } finally {\n      setLoading(false);\n    }\n  }, [categoryFilter, subcategoryFilter, query]);\n\n  useEffect(() => {\n    const t = setTimeout(() => { load(); }, 300);\n    return () => clearTimeout(t);\n  }, [load]);\n\n  /* AQUÍ VIVÍAN DOS COSAS QUE SE MUDARON A `useAccionesProducto`, y las dos por el mismo motivo —la\n     pantalla de la subcategoría pinta las mismas tarjetas y las necesita iguales—:\n       · la **sincronización de favoritos** al montar (`favoriteIds()`), que traía los corazones;\n       · `alternarFavorito`, el corazón con puerta de sesión y vuelta atrás si la API falla.\n     Se retiraron de este archivo el 23-sep-2026 junto con las importaciones que solo ellos usaban\n     (`useSession` y el propio `setFavIds`/`toggleFavId` del store). */\n\n  /** Búsqueda por foto: valida, avisa y sube; imageActive se activa al empezar\n   *  para que el banner muestre \"Buscando…\" mientras trabaja. */\n  const searchByPhoto = async () => {\n    try {\n      const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();\n      if (!perm.granted) {\n        Alert.alert('Permiso de fotos', 'Necesitamos acceso a tu galería para buscar por imagen.');\n        return;\n      }\n      const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7 });\n      if (res.canceled || !res.assets?.[0]) return; // cancelado ≠ error\n      const asset = res.assets[0];\n      if ((asset.fileSize ?? 0) > MAX_PHOTO_MB * 1024 * 1024) {\n        Alert.alert('Foto demasiado pesada', `Usa una imagen de menos de ${MAX_PHOTO_MB} MB.`);\n        return;\n      }\n      const type = asset.mimeType ?? 'image/jpeg';\n      if (!type.startsWith('image/')) {\n        Alert.alert('Archivo no válido', 'Selecciona una imagen.');\n        return;\n      }\n      setImageActive(true);\n      setImageBusy(true);\n      setImageError(null);\n      try {\n        const form = new FormData();\n        form.append('image', { uri: asset.uri, name: 'foto.jpg', type } as unknown as Blob);\n        const r = await ecomerseApi.searchImage(form);\n        setImageResults(r.products ?? []);\n      } catch (e) {\n        /*\n          NO se convierte en «sin resultados»: se guarda el fallo y se enseña con `InlineError`\n          (que además lo anuncia al lector de pantalla). Antes esto era `setImageResults([])` +\n          un Alert, y el usuario leía que su foto no servía cuando el problema era otro.\n        */\n        setImageResults([]);\n        setImageError(e instanceof Error && e.message ? e.message : 'No se pudo procesar la imagen. Prueba con otra foto.');\n      } finally {\n        setImageBusy(false);\n      }\n    } catch { /* picker falló por el sistema */ }\n  };\n\n  /* El departamento y la familia activos, que son los dos primeros escalones de la navegación.\n     `activeCat` conserva el nombre viejo —el árbol lo llamaba «categoría»— y lo que hace hoy es\n     **alimentar la rejilla de familias**; `activeFam` es el escalón de en medio y sirve para dos\n     cosas: marcar la celda elegida en la rejilla y escribir su nombre en la línea de resultados.\n     Los dos se buscan por `id` y no se guardan como objeto: el árbol puede recargarse (cambian los\n     filtros y el servidor lo vuelve a servir) y un objeto guardado quedaría obsoleto. */\n  const activeCat = cats.find((c) => c.id === categoryFilter);\n  const activeFam = activeCat?.familias?.find((f) => f.id === subcategoryFilter);\n  /* LA LÍNEA DE RESULTADOS VUELVE A DECIR SOLO LA FAMILIA. Hasta el 23-sep-2026 escribía el camino\n     entero —«Calzado · Zapatos de vestir»— porque la hoja de clases se cerraba al elegir y la clase\n     no se veía en ningún otro sitio. Con la pantalla propia de la subcategoría el tercer escalón ya\n     no se elige aquí, así que el camino que esta línea tiene que explicar es uno: qué familia está\n     filtrando el catálogo que hay debajo. */\n  const caminoFiltro = activeFam?.label ?? '';\n  const cartCount = cart.reduce((a, c) => a + c.qty, 0);\n\n  const listData: EcomerseProduct[] = useMemo(() => {\n    const base = imageActive ? imageResults : products;\n    if (loading && !products.length && !imageActive) return PLACEHOLDER_CARDS.map((i) => ({ id: `__sk_${i}` } as EcomerseProduct));\n    return base.length % 2 === 1 ? [...base, { id: '__spacer__' } as EcomerseProduct] : base;\n  }, [imageActive, imageResults, products, loading]);\n\n  const isPlaceholder = (id: string) => id.startsWith('__sk_');\n\n  const chooseCat = (catId: string) => {\n    const next = categoryFilter === catId ? '' : catId;\n    setCategoryFilter(next);\n    setSubcategoryFilter(''); // nunca arrastrar la familia de otro departamento\n  };\n\n  /**\n   * Tocar una familia: la deja elegida y **abre su pantalla**. Es el tercer escalón del árbol y desde\n   * el 23-sep-2026 tiene pantalla propia (`/ecomerse-subcategoria`), no una hoja sobre el catálogo.\n   *\n   * POR QUÉ SE MARCA LA FAMILIA AQUÍ ADEMÁS DE NAVEGAR: al volver, el catálogo de debajo queda\n   * filtrado por esa familia y la celda sale marcada. Llegar y salir sin rastro convertiría la\n   * pantalla en un sitio del que se vuelve sin saber por dónde se entró.\n   *\n   * SE LE PASA EL NOMBRE EN LOS PARÁMETROS y no es un capricho: la pantalla pinta el nombre de la\n   * subcategoría en su cabecera, y con el id solo tendría que esperar a que llegue el árbol para\n   * poder escribir nada. Con `nombre` el encabezado ya está en el primer fotograma; si la pantalla se\n   * abre por enlace directo (sin nombre), lo saca del árbol o del propio producto.\n   */\n  const abrirFamilia = (f: EcomerseFamily) => {\n    setSubcategoryFilter(f.id);\n    router.push({ pathname: '/ecomerse-subcategoria', params: { id: f.id, nombre: f.label } } as any);\n  };\n\n  const s = styles(colors);\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Header. La barra de búsqueda vive AQUÍ, donde antes estaba el título «Mercado»: el título\n          solo gastaba la fila más valiosa de la pantalla, y la búsqueda se iba hacia arriba con el\n          catálogo (había que volver a subir para corregir una palabra). Es el patrón de Xianyu y de\n          Dewu, y es lo que se pidió.\n          Lo que se paga: la pantalla se queda **sin nombre visible**, y por tanto sin encabezado que\n          el lector de pantalla anuncie al entrar. Se acepta a cambio de la barra fija. Queda dicho\n          como deuda: si algún día se quiere recuperar, el sitio natural no es esta fila sino el\n          `accessibilityLabel` de la pantalla, y hay un desajuste de nombre que arreglar antes —\n          el cajón de servicios llama a esta pantalla «Ecomerse» (`ServicesDrawer.tsx:172`), que es\n          el nombre del módulo en código, no el que usa el resto de la app («Mercado», en\n          `billing-status.tsx:45` y `profile.tsx:431`). */}\n      <View style={s.header}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <View style={s.headerSearch}>\n          <Search size={16} color={colors.textSecondary} />\n          <TextInput\n            value={query}\n            onChangeText={setQuery}\n            /* «Buscar» y no «Buscar productos». El campo mide 126 dp y el texto va a `body`\n               (14 → 16,1 dp con el `font_scale` 1.15 del dispositivo): a 10,08 dp por carácter,\n               «Buscar productos» (16) pide 161 y se cortaba en «Buscar product». No se estrecha\n               nada más para que quepa —los márgenes de la cabecera valen más que el relleno de un\n               marcador—: se acorta el marcador, que es lo único prescindible. El significado entero\n               sigue en el `accessibilityLabel`, que no compite por el ancho. */\n            placeholder=\"Buscar\"\n            placeholderTextColor={colors.textSecondary}\n            accessibilityLabel=\"Buscar productos\"\n            returnKeyType=\"search\"\n            autoCorrect={false}\n            style={s.searchInput}\n          />\n          <Pressable onPress={searchByPhoto} hitSlop={10} disabled={imageBusy} accessibilityRole=\"button\"\n            accessibilityLabel=\"Buscar por foto\">\n            {imageBusy ? <ActivityIndicator size=\"small\" color={colors.primary} /> : <Camera size={18} color={colors.primary} />}\n          </Pressable>\n        </View>\n        <View style={s.headerActions}>\n          <Pressable onPress={() => router.push('/ecomerse-favorites' as any)} hitSlop={12} accessibilityRole=\"button\"\n            accessibilityLabel={favIds.length ? `Favoritos, ${favIds.length}` : 'Favoritos'}>\n            <Heart size={20} color={favIds.length ? brand.like : colors.textPrimary} />\n          </Pressable>\n          <Pressable onPress={() => router.push('/ecomerse-checkout' as any)} hitSlop={12} accessibilityRole=\"button\"\n            accessibilityLabel={cartCount ? `Carrito, ${cartCount} productos` : 'Carrito vacío'}>\n            <ShoppingCart size={20} color={colors.textPrimary} />\n            {cartCount > 0 && (\n              <View style={s.cartBadge}><Text style={s.cartBadgeText}>{cartCount > 9 ? '9+' : cartCount}</Text></View>\n            )}\n          </Pressable>\n          {/* TIENDAS, no «mi tienda». Este icono 🏪 llevaba al panel del vendedor —una pantalla que,\n              sin tienda dada de alta, solo puede decir que no tienes tienda— y no había **ninguna**\n              forma de ver las tiendas de los demás. Ahora abre el directorio (`/ecomerse-tiendas`),\n              y el panel del vendedor vive dentro, en su propia fila «Mi tienda». El icono deja de\n              tener que adivinar si «tienda» es la tuya o las de todos: ahora son las dos, cada una\n              en su fila. */}\n          <Pressable onPress={() => router.push('/ecomerse-tiendas' as any)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Tiendas\">\n            <Store size={20} color={colors.primary} />\n          </Pressable>\n        </View>\n      </View>\n\n      <FlatList\n        data={listData}\n        keyExtractor={(item) => item.id}\n        numColumns={2}\n        columnWrapperStyle={s.colWrap}\n        contentContainerStyle={[s.listContent, { paddingBottom: PIE_MERCADO_H + insets.bottom + espaciado.e32 }]}\n        keyboardShouldPersistTaps=\"handled\"\n        refreshing={loading && products.length > 0}\n        onRefresh={load}\n        ListHeaderComponent={\n          imageActive ? (\n            <View style={[s.photoBanner, { backgroundColor: alpha(colors.primary, 0.08), borderColor: colors.border }]}>\n              <Text style={[s.photoBannerTitle, { color: colors.textPrimary }]}>🔍 Resultados de tu foto</Text>\n              <Text style={[s.photoBannerSub, { color: colors.textSecondary }]}>\n                {imageBusy ? 'Buscando productos similares…' : `${imageResults.length} producto${imageResults.length === 1 ? '' : 's'} similar${imageResults.length === 1 ? '' : 'es'}`}\n              </Text>\n              <Pressable onPress={() => setImageActive(false)} style={s.photoBack} accessibilityRole=\"button\">\n                <Text style={s.photoBackText}>← Volver al catálogo</Text>\n              </Pressable>\n            </View>\n          ) : (\n          <View>\n            {/* PESTAÑAS DE DEPARTAMENTOS — lo primero bajo la barra de búsqueda.\n                Es la estructura de la referencia: el primer nivel son pestañas, la activa se marca\n                con color y subrayado, y la fila **desliza** en vez de aplastarse (18 departamentos\n                no caben en 360 dp, y con una escala de letra grande caben menos todavía).\n                El emoji viaja DELANTE del nombre, y eso no es adorno: el servidor da emoji a los 18\n                departamentos (`icon`), así que la pestaña se reconoce por figura antes de leerse —\n                es lo único del árbol que tiene imagen propia.\n                «Recomendado» es una pestaña más y NO es un departamento: es el estado de partida\n                (sin departamento elegido) el que la deja activa, y al pulsarla se vuelve al feed\n                entero. Va la primera porque es el camino de vuelta, y sin ella la única forma de\n                quitar el filtro sería volver a pulsar la pestaña puesta. */}\n            {loading && cats.length === 0 ? (\n              <PestanasEsqueleto colors={colors} />\n            ) : (\n              <PestanasDepartamentos cats={cats} activeId={categoryFilter} onPick={chooseCat} />\n            )}\n\n            {/* LA REJILLA — las familias del departamento activo, con la imagen del servidor.\n                La imagen **no es de la familia**: la familia no tiene ninguna (0 de 110 tienen\n                `icon`), y el servidor la resuelve a partir de una TIENDA de esa familia —su logo, o\n                si no lo tiene la foto de su anuncio más reciente—. Por eso el rótulo es estable y la\n                imagen no: el día que las tiendas cambien sus fotos, o que se borren las de prueba,\n                la celda se actualiza sola. Sin imagen (`foto: null`) la celda sale con su nombre y\n                centrado: el hueco no se finge con un cuadro vacío, que se leería como avería.\n                Tocar una familia la elige y **abre su pantalla**, donde están sus subclases y los\n                productos de cada una (ver `abrirFamilia`). Volver a tocarla no la quita: el camino de\n                vuelta es la pestaña del departamento —que suelta la familia— y el botón atrás de la\n                pantalla de la subcategoría, que devuelve el catálogo ya filtrado por esa familia. */}\n            {activeCat && (\n              <RejillaFamilias\n                familias={activeCat.familias ?? []}\n                activeId={subcategoryFilter}\n                onPick={abrirFamilia}\n              />\n            )}\n\n            {/* AQUÍ ESTABA EL AVISO. Decía «No le pagamos al vendedor hasta que recibas el pedido»\n                dentro de una franja verde (`<EstadoDinero activo=\"retenido\" compacto />`) y se\n                retiró en la limpieza de cromo. El argumento para quitarlo no es que sobre\n                información, sino que **estaba en el sitio equivocado**: es una promesa sobre el\n                dinero, y el usuario decide si le importa cuando va a pagar, no cuando está mirando\n                categorías. El primitivo sigue vivo, intacto, para la ficha del producto y el\n                checkout, que es donde esa frase cambia una decisión. */}\n\n            {/* AQUÍ VIVÍAN TRES COSAS, Y SE FUERON LAS TRES EL 23-sep-2026 (mismo cambio que las\n                pestañas y la rejilla, quince líneas más arriba):\n                  · los chips de ORDEN («Recomendado · Mejor valorado · Novedades»), con su `SORTS`;\n                  · la pila de AVATARES de categorías con su «Ver todas (18)» y su modal;\n                  · el carril de FAMILIAS en chips, que la rejilla sustituye.\n                El motivo es el mismo en los tres casos: la cabecera gastaba cuatro filas antes de\n                enseñar el primer producto, y las dos primeras —ciudad y orden— no son categorías:\n                son cromo de otra pantalla. Lo que se pierde está anotado arriba, en la cabecera de\n                este fichero, para que no parezca que se perdió por descuido. */}\n\n            {/* AQUÍ VIVIÓ EL CARRIL DE HOJAS, unas horas del 23-sep-2026: una fila de chips con un\n                caret que la abría en el sitio. Duró lo que tardaron dos correcciones seguidas de\n                Bernardo sobre dónde va de verdad el tercer escalón: primero «un modal con el nombre\n                de la subcategoría en el encabezado y sus clases debajo», y después «me equivoqué en\n                decir que el modal, si no que una pantalla completa». Las dos formas se implementaron\n                y se vieron en el móvil; la que queda es la tercera, **una pantalla propia**\n                (`app/ecomerse-subcategoria.tsx`), porque una familia puede tener 16 subclases con\n                productos —la más larga del árbol vivo— y eso no cabe en una hoja sobre el catálogo.\n                Aquí no queda nada que pintar. */}\n\n            {/* Recomendados (globales; no se ocultan al filtrar) */}\n            {recommended.length > 0 && (\n              <>\n                <View style={[s.sectionHead, { marginTop: espaciado.e4 }]}>\n                  <Text style={s.sectionTitle}>🔥 Recomendados</Text>\n                </View>\n                <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e10, paddingRight: espaciado.e16 }}>\n                  {recommended.map((p) => (\n                    <TarjetaProducto\n                      key={p.id}\n                      product={p}\n                      width={ANCHO_CARRUSEL}\n                      iconoTamano={ilustracion.md}\n                      favorited={favIds.includes(p.id)}\n                      onPress={() => router.push({ pathname: '/ecomerse-detail', params: { id: p.id } } as any)}\n                      onFav={() => alternarFavorito(p)}\n                    />\n                  ))}\n                </ScrollView>\n              </>\n            )}\n\n            {/* Contador de resultados, con el CAMINO elegido delante cuando hay filtro de categoría:\n                es donde se ve la clase activa desde que la hoja se cierra al elegirla. Va en esta\n                línea y no en una fila nueva: la cabecera de esta pantalla no admite más cromo. */}\n            {!error && (\n              <Text style={s.resultsLabel}>\n                {loading ? 'Cargando…'\n                  : `${caminoFiltro ? `${caminoFiltro} — ` : ''}${products.length} producto${products.length === 1 ? '' : 's'}`}\n              </Text>\n            )}\n          </View>\n          )\n        }\n        ListEmptyComponent={\n          imageActive ? (\n            /* Tres estados distintos, y antes eran uno: mientras busca se enseña que busca, si\n               falla se dice que falló (con reintento), y solo si de verdad no hay resultados se\n               enseña el vacío. El vacío, además, ahora es el del kit. */\n            imageBusy ? (\n              <View style={{ alignItems: 'center', paddingTop: 48 }}>\n                <ActivityIndicator color={colors.primary} />\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e10 }}>Buscando productos parecidos…</Text>\n              </View>\n            ) : imageError ? (\n              <View style={{ paddingTop: 40, paddingHorizontal: espaciado.e32 }}>\n                <InlineError mensaje={imageError} onReintentar={() => void searchByPhoto()} etiquetaReintento=\"Elegir otra foto\" />\n              </View>\n            ) : (\n              <EmptyState\n                emoji=\"📷\"\n                titulo=\"No encontramos productos parecidos\"\n                texto=\"Prueba con otra foto más nítida, de frente y con buena luz, o busca por texto.\"\n                accionLabel=\"← Volver al catálogo\"\n                onAccion={() => setImageActive(false)}\n              />\n            )\n          ) : error ? (\n            /*\n              El error, con el componente del kit: se anuncia al lector de pantalla, vibra y trae\n              su propio reintento. Era un bloque a mano con 📡 y un botón de estilo propio.\n            */\n            <View style={{ paddingTop: 40, paddingHorizontal: espaciado.e32 }}>\n              <InlineError mensaje={`No pudimos cargar el catálogo. ${error}`} onReintentar={load} />\n            </View>\n          ) : loading ? null : (\n            /* El vacío del kit. Antes este archivo definía el suyo: tres formas de hacer lo\n               mismo en el mismo producto. Las dos caras van en un solo objeto para no repetir\n               cinco veces la condición de «hay filtros». */\n            /* La ciudad salió de esta condición el 23-sep-2026 junto con su carril. No se pierde\n               nada: `cityFilter` sigue en el store pero **nada puede ya escribirlo** —la home no lo\n               pinta y el `partialize` del store solo persiste `cart`—, así que un filtro de ciudad\n               es hoy imposible de tener activo. Y el texto ya no manda «buscar en otra ciudad», que\n               era una salida que esta pantalla no ofrece. */\n            <EmptyState\n              emoji=\"🛍️\"\n              {...((!!categoryFilter || !!subcategoryFilter || !!query.trim())\n                ? {\n                    titulo: 'Sin resultados con estos filtros',\n                    texto: 'Prueba a quitar filtros o a buscar con otras palabras.',\n                    accionLabel: 'Quitar filtros',\n                    onAccion: () => { setCategoryFilter(''); setSubcategoryFilter(''); setQuery(''); },\n                  }\n                : {\n                    titulo: 'Todavía no hay productos',\n                    texto: 'Sé el primero en publicar: identidad verificada + aprobación del administrador.',\n                    accionLabel: 'Publicar mi primer producto',\n                    accionPrimaria: true,\n                    onAccion: () => router.push('/ecomerse-seller' as any),\n                  })}\n            />\n          )\n        }\n        renderItem={({ item }) =>\n          isPlaceholder(item.id) ? (\n            <EsqueletoTarjeta key={item.id} />\n          ) : item.id === '__spacer__' ? (\n            <View key=\"spacer\" style={{ flex: 1 }} />\n          ) : (\n            <TarjetaProducto\n              product={item}\n              favorited={favIds.includes(item.id)}\n              onPress={() => abrirFicha(item.id)}\n              onFav={() => alternarFavorito(item)}\n              onAdd={() => anadirAlCarrito(item)}\n            />\n          )\n        }\n      />\n\n      {/* AQUÍ VIVÍAN DOS MODALES: «Todas las categorías» (la hoja de la pila de avatares) y «Elige tu\n          ciudad». Los dos cayeron con el cromo de la cabecera el 23-sep-2026: las 18 pestañas de\n          departamento ya están todas a la vista —y deslizan—, así que la hoja era una segunda puerta\n          al mismo sitio; y el filtro por ciudad dejó de ofrecerse en la home (el servidor y el\n          `state` lo conservan intacto, ver la cabecera del fichero). */}\n\n      {/* AQUÍ VIVIÓ LA HOJA DE CLASES — el `<Sheet>` del kit con el nombre de la familia en su\n          encabezado y sus clases en chips debajo, que es lo que pidió Bernardo en la primera\n          corrección. Se retiró con la segunda: **el tercer escalón es una pantalla entera**\n          (`/ecomerse-subcategoria`), porque una hoja sobre el catálogo no puede enseñar, además de\n          las subclases, los productos de cada una —y eso es lo que se viene a ver—. Los datos de\n          cuando se midió para dimensionar la hoja siguen valiendo para la pantalla: las familias\n          tienen entre 1 y 16 subclases (36 con 1-3, 66 con 4-6, 3 con 7-9, 4 con 10-14 y 1 con 16).\n          Con la hoja se fue `SubChip`, que solo la pintaba a ella (Favoritos tiene el suyo) — y con\n          él sus dos literales de diseño: un `borderWidth` de 1 y un `fontWeight` de 700 escritos a\n          mano. Ojo con eso al documentar retiradas: **la guardia cuenta los literales que aparecen\n          dentro de los comentarios**, así que escribir aquí el valor exacto lo devuelve a la cuenta. */}\n      {/* El pie del Mercado (Home · Mensajes · Perfil). Va DENTRO del View raíz y al final, como el\n          dock en las pantallas que lo pintan. El hueco que necesita la lista se lo da el\n          `paddingBottom` de arriba: sin él, la última fila de productos quedaría tapada por la barra\n          y no habría forma de llegar a ella. */}\n      <PieDelMercado sinLeer={sinLeer} />\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\n/**\n * PESTAÑAS DE DEPARTAMENTOS — el primer nivel de la home, pegado a la barra de búsqueda.\n *\n * Son 18 y **no caben** en 360 dp, así que la fila **desliza** en vez de repartirse: 18 pestañas\n * comprimidas serían 18 rótulos cortados, que es el defecto que esta pantalla ya arregló una vez.\n *\n * La activa se marca de DOS formas a la vez —color y subrayado—, y no es redundancia: en el tema\n * oscuro el color primario y el texto secundario se distinguen mal, y hay quien no distingue el\n * rojo. El `accessibilityState` lo dice además sin depender de ninguna de las dos.\n *\n * «Recomendado» es la primera y **no es un departamento**: es el estado «sin departamento». Volver a\n * pulsar la pestaña puesta también lo quita (`chooseCat` alterna), pero eso hay que descubrirlo; una\n * pestaña que se llama «Recomendado» se entiende sin manual.\n *\n * EL EMOJI VA DELANTE DEL NOMBRE, y va dentro del MISMO `Text`: es lo único del árbol que tiene\n * imagen propia —los 18 departamentos sí, las 110 familias no—, así que la pestaña se reconoce por\n * figura antes de leerse. En dos `Text` hermanos dentro de una fila la línea base se descuadra en\n * cuanto cambia la escala de letra del sistema.\n */\nfunction PestanasDepartamentos({ cats, activeId, onPick }: {\n  cats: EcomerseCategory[]; activeId: string; onPick: (id: string) => void;\n}) {\n  const { colors } = useTheme();\n  return (\n    <View style={[s_home.pestanasBarra, { borderBottomColor: colors.border }]}>\n      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s_home.pestanasContenido}>\n        <Pestana label=\"Recomendado\" activa={activeId === ''} onPress={() => onPick('')} colors={colors} />\n        {cats.map((c) => (\n          <Pestana\n            key={c.id}\n            label={c.label}\n            emoji={c.icon}\n            activa={activeId === c.id}\n            onPress={() => onPick(c.id)}\n            colors={colors}\n          />\n        ))}\n      </ScrollView>\n    </View>\n  );\n}\n\n/** Una pestaña. Aparte del carril para que el carril no tenga dos ramas de pintado. */\nfunction Pestana({ label, emoji, activa, onPress, colors }: {\n  label: string; emoji?: string | null; activa: boolean;\n  onPress: () => void; colors: ReturnType<typeof useTheme>['colors'];\n}) {\n  return (\n    <Pressable onPress={onPress} hitSlop={6} accessibilityRole=\"tab\"\n      accessibilityState={{ selected: activa }} accessibilityLabel={label} style={s_home.pestana}>\n      <Text numberOfLines={1} style={[s_home.pestanaTexto, { color: activa ? colors.primary : colors.textSecondary }]}>\n        {emoji ? `${emoji} ` : ''}{label}\n      </Text>\n      {/* El subrayado se pinta SIEMPRE (transparente cuando no toca) y no condicionalmente: así la\n          pestaña mide lo mismo activa y no activa, y al cambiar de pestaña no baila el alto. */}\n      <View style={[s_home.subrayado, { backgroundColor: activa ? colors.primary : 'transparent' }]} />\n    </Pressable>\n  );\n}\n\n/**\n * Esqueleto del carril de pestañas: **mismo alto, mismo deslizamiento horizontal, mismo hueco**. Un\n * esqueleto que no mide lo que va a medir el contenido real es una promesa falsa — hace saltar la\n * pantalla cuando llegan los datos. Por eso son barras del alto de una pestaña y no círculos.\n */\nfunction PestanasEsqueleto({ colors }: { colors: ReturnType<typeof useTheme>['colors'] }) {\n  return (\n    <View style={[s_home.pestanasEsqueleto, { borderBottomColor: colors.border }]}>\n      {Array.from({ length: 5 }).map((_, i) => (\n        <View key={i} style={[s_home.pestanaEsqueleto, { backgroundColor: colors.border }]} />\n      ))}\n    </View>\n  );\n}\n\n/**\n * LA REJILLA DE FAMILIAS — el segundo nivel, con la imagen que resuelve el servidor.\n *\n * LA IMAGEN NO ES DE LA FAMILIA, y esto es lo que hay que entender antes de tocar nada: la familia\n * no tiene imagen propia (0 de las 110 traen `icon`), así que el servidor la saca de **una tienda de\n * esa familia** —su logo, o si no lo tiene la foto de su anuncio más reciente—. Consecuencia: el\n * **rótulo es estable y la imagen no**, porque el rótulo sale del árbol y la imagen de las tiendas.\n * El día que las tiendas cambien sus fotos, o que se borren las de prueba, la celda se actualiza\n * sola sin tocar este código.\n *\n * SIN IMAGEN NO SE FINGE NADA. `foto: null` es un estado legítimo —hoy es el de casi todas las\n * celdas, con dos tiendas en el Mercado— y entonces la celda sale **con su nombre, centrado**: no un\n * cuadro vacío, que se leería como una imagen rota, ni el emoji del departamento, que sería idéntico\n * en las quince celdas de una pestaña y no distinguiría nada.\n *\n * El alto de la celda es un MÍNIMO COMÚN (`ALTO_CELDA_FAMILIA`, 96 dp) justo por eso: si midiera lo\n * que mide su contenido, una fila con una foto y tres sin ella quedaría a cuatro alturas y los\n * rótulos quedarían descolgados, que es lo que se lee como error de maquetación.\n *\n * EL RÓTULO VA A TRES LÍNEAS (`numberOfLines={LINEAS_ROTULO}`) Y NO SE CORTA NINGUNO: a 4 columnas y\n * letra `rotulo` (9) los 110 entran enteros —está medido, ver `COLUMNAS_REJILLA`—. El\n * `ellipsizeMode=\"tail\"` se queda puesto como red de seguridad, no como comportamiento esperado: solo\n * se dispararía con una escala de letra del sistema mucho mayor que la de referencia (1,15) o con un\n * rótulo nuevo más largo que «Bolsos y accesorios deportivos» (30 caracteres).\n */\nfunction RejillaFamilias({ familias, activeId, onPick }: {\n  familias: EcomerseFamily[]; activeId: string; onPick: (f: EcomerseFamily) => void;\n}) {\n  const { colors } = useTheme();\n  return (\n    <View style={s_home.rejillaContenido}>\n      {familias.map((f) => {\n        const on = activeId === f.id;\n        return (\n          <Pressable key={f.id} onPress={() => onPick(f)} accessibilityRole=\"button\"\n            accessibilityState={{ selected: on }} accessibilityLabel={f.label} style={s_home.celda}>\n            {f.foto ? (\n              <Image\n                source={{ uri: f.foto }}\n                style={[s_home.celdaFoto, {\n                  backgroundColor: colors.surface,\n                  borderColor: on ? colors.primary : colors.border,\n                  borderWidth: on ? trazo.fuerte : trazo.fino,\n                }]}\n                contentFit=\"cover\"\n                transition={150}\n              />\n            ) : null}\n            <Text numberOfLines={LINEAS_ROTULO} ellipsizeMode=\"tail\"\n              style={[s_home.celdaRotulo, { color: on ? colors.primary : colors.textPrimary }]}>{f.label}</Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst s_home = StyleSheet.create({\n  /* --- pestañas --- */\n  pestanasBarra: { borderBottomWidth: trazo.fino },\n  pestanasContenido: { paddingHorizontal: espaciado.e16, gap: espaciado.e12, alignItems: 'flex-end' },\n  pestana: { alignItems: 'center', paddingTop: espaciado.e8 },\n  /** `caption` (12) y no `body`: con 18 pestañas la fila se recorre deslizando, y un rótulo grande\n   *  convierte cada pestaña en un bloque — se ve menos de la mitad del árbol de un vistazo. */\n  pestanaTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte, paddingBottom: espaciado.e4 },\n  /** `radios.full` y no `1`: el subrayado mide 2 dp de alto, así que el radio máximo lo convierte en\n   *  una barra de extremos redondeados igual que un `1` a mano — pero el `1` era el único valor de\n   *  radio suelto del archivo, y la guardia de diseño (`npm run diseno`) lo cazaba como deuda nueva. */\n  subrayado: { height: 2, width: '100%', borderRadius: radios.full },\n  pestanasEsqueleto: { flexDirection: 'row', gap: espaciado.e12, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino },\n  pestanaEsqueleto: { width: 56, height: 12, borderRadius: radios.sm },\n\n  /* --- rejilla de familias --- */\n  /** `flexWrap` con ancho EXPLÍCITO por celda (`100/COLUMNAS_REJILLA`): con `flex: 1` y base 0 el\n   *  `flexWrap` no llega a partir la fila —las celdas «caben» en teoría y acaban comprimidas—. Es un\n   *  defecto que ya apareció en la rejilla vieja de esta pantalla. */\n  rejillaContenido: { flexDirection: 'row', flexWrap: 'wrap', paddingHorizontal: espaciado.e12, paddingTop: espaciado.e12 },\n  celda: {\n    width: `${100 / COLUMNAS_REJILLA}%`, minHeight: ALTO_CELDA_FAMILIA,\n    alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e2, paddingVertical: espaciado.e4,\n  },\n  celdaFoto: { width: DIAM_FOTO_FAMILIA, height: DIAM_FOTO_FAMILIA, borderRadius: radios.md, marginBottom: espaciado.e6 },\n  /** `rotulo` (9) y no `micro` (11): el peldaño de la escala que existe para esta celda. El porqué\n   *  —80 dp de ancho por celda, 110 rótulos medidos— está contado en `tipografia.rotulo`. */\n  celdaRotulo: { fontSize: tipografia.rotulo, fontWeight: peso.fuerte, textAlign: 'center' },\n});\n\n/* Aquí vivía `SubChip`, el chip de la hoja de clases. Se retiró el 23-sep-2026 con la hoja: el tercer\n   escalón pasó a ser una pantalla (`app/ecomerse-subcategoria.tsx`). Favoritos tiene su propio\n   `SubChip`, que no se toca —es de otra pantalla y de otro filtro—. */\n\n/** Aquí vivieron tres esqueletos de la zona de categorías, y ninguno llegó a tiempo: `CatSkeletonGrid`\n *  (5 cuadrados de 46 en fila) se retiró al pasar la home a la pila de avatares, `AvatarStackEsqueleto`\n *  (los círculos con su solape) al pasar la home a las pestañas + rejilla el 23-sep-2026. El que vive\n *  ahora es `PestanasEsqueleto`, unas barras del ancho de una pestaña: dibuja **lo que va a llegar**\n *  —nombres de departamento— y no una forma que luego no aparece. Regla que sacaron los tres: un\n *  esqueleto que no mide lo mismo que el contenido hace saltar la cabecera al cargar. */\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  /**\n   * Fondo SÓLIDO + elevación: es lo que despega la cabecera del catálogo que se desliza por\n   * debajo. Sin `backgroundColor` la barra era transparente y, al desplazar, la fila de tarjetas\n   * cortada por el borde de la lista se leía pegada al título, sin separación ninguna.\n   * `paddingVertical` bajó de 12 a 8 al mudarse aquí la barra de búsqueda: 8 + 40 + 8 = 56 dp de\n   * cabecera, el alto estándar de una barra de app de Android. Con 12 serían 64 y se comía el\n   * sitio de una tarjeta y media.\n   */\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8, backgroundColor: c.background, borderBottomWidth: trazo.fino, borderBottomColor: c.border, zIndex: 2, elevation: 2 },\n  headerActions: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e14 },\n  cartBadge: { position: 'absolute', top: -6, right: -8, minWidth: 16, height: 16, borderRadius: radios.sm, backgroundColor: brand.like, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e3 },\n  cartBadgeText: { color: brand.white, fontSize: tipografia.micro, fontWeight: peso.titulo },\n  /**\n   * La barra de búsqueda, en la cabecera. `height: 40` en vez de `paddingVertical`: es lo que la\n   * hace caber junto a los tres iconos de acción y quedar centrada con ellos, y evita que el alto\n   * dependa del `font_scale` del usuario (con un `paddingVertical` fijo, a 1.3 de escala la barra\n   * crecía y desalineaba la fila entera). Los 40 dp son de la barra, no del área táctil: la barra\n   * entera es el campo, así que el alto táctil ya es de sobra.\n   */\n  headerSearch: { flex: 1, flexDirection: 'row', alignItems: 'center', marginHorizontal: espaciado.e12, height: 40, paddingHorizontal: espaciado.e12, backgroundColor: c.surface, borderRadius: radios.md, borderWidth: trazo.fino, borderColor: c.border },\n  /** `paddingVertical: 0` es obligatorio en Android: el `TextInput` trae relleno vertical propio y,\n   *  sin quitarlo, desborda los 40 dp de la barra por arriba y por abajo. */\n  searchInput: { flex: 1, color: c.textPrimary, fontSize: tipografia.body, marginLeft: espaciado.e8, paddingVertical: 0 },\n  /* Aquí vivían `cityRow`, `cityPicker`, `cityLabel` y `cityItem` (el carril de ciudad) y `seeAll`\n     («Ver todas (18)», el acceso al modal de categorías). Se retiraron el 23-sep-2026 con el cromo\n     de la cabecera: sus dos pantallas ya no existen, así que eran cinco hojas de estilo que nadie\n     podía aplicar. Un `StyleSheet` con claves muertas no molesta al compilador, pero hace creer que\n     la ciudad y el modal siguen ahí a quien lea el archivo. */\n  sectionHead: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, marginTop: espaciado.e16, marginBottom: espaciado.e8 },\n  sectionTitle: { fontSize: tipografia.body, fontWeight: peso.maximo, color: c.textPrimary },\n  /* Aquí vivía `subRow`, el carril de hojas de la cabecera. Se retiró el 23-sep-2026 junto con el\n     carril entero: las clases de una familia se eligen en la hoja (`<Sheet>`), no en una fila de\n     chips. Dejarla habría sido una hoja de estilo que nadie aplica —el patrón del archivo es que una\n     pieza que se va se lleva sus estilos—. */\n  resultsLabel: { fontSize: tipografia.caption, fontWeight: peso.fuerte, color: c.textSecondary, paddingHorizontal: espaciado.e16, marginTop: espaciado.e16, marginBottom: espaciado.e10 },\n  colWrap: { gap: espaciado.e10, paddingHorizontal: espaciado.e16 },\n  listContent: { paddingBottom: espaciado.e32 },\n  /* `modalWrap`/`modalCard`/`modalHead`/`modalTitle` murieron con los dos modales de la home\n     (ciudad y «Todas las categorías»), retirados el 23-sep-2026. El `Modal` ya no está importado\n     en este archivo: si vuelve a hacer falta un modal, se trae el `Modal` y con él su envoltorio. */\n  photoBanner: { marginHorizontal: espaciado.e16, marginTop: espaciado.e12, borderRadius: radios.md, borderWidth: trazo.fino, padding: espaciado.e14, alignItems: 'center' },\n  photoBannerTitle: { fontSize: tipografia.body, fontWeight: peso.maximo },\n  photoBannerSub: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  photoBack: { marginTop: espaciado.e10, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, borderRadius: radios.lg, backgroundColor: c.primary },\n  photoBackText: { color: brand.white, fontSize: tipografia.caption, fontWeight: peso.maximo },\n});\n","/**\n * EditProfileScreen — /edit-profile · \"Editar perfil\" estilo Xiaohongshu (P8).\n *\n * Pantalla completa (expo-router /edit-profile, protegida por AuthGate).\n *  · Cabecera fija: ‹ Volver · \"Editar perfil\" · Vista previa (modal local).\n *  · Bloque imagen: portada (ImageBackground con absUrl(coverUrl) o capa de\n *    marca) + avatar circular 84 con superposición; foto/portada se eligen con\n *    core/pickImage (galería/cámara robustas, sin base64 inline del picker) y el\n *    botón muestra \"Procesando…\" mientras se procesa; la imagen nueva SOLO se\n *    envía al pulsar Guardar cambios.\n *  · Información básica: nombre + ID de EG Route Plan (de solo lectura; no hay\n *    expo-clipboard instalado, así que no se ofrece copiar).\n *  · Personalización: biografía multilínea con contador 0/300 (FormField del\n *    kit fija su altura en 50 px y no puede alojar 4 líneas; se usa un campo\n *    equivalente con los mismos tokens del tema).\n *  · Datos personales y profesionales: género (chips), fecha de nacimiento\n *    (validación AAAA-MM-DD), ubicación (modal país + ciudades GQ), ocupación\n *    (modal agrupado PROFESSION_GROUPS), escuela e información original.\n *  · Gestión: widgets (Switch desde DEFAULT_WIDGETS) y enlaces/correos\n *    editables (máx. 8).\n *  · Guardar: updateMe() con payload parcial (solo lo que cambió + dataURLs\n *    nuevas + widgets + links) y vuelta a la pantalla anterior.\n *  · Si hay cambios sin guardar, Volver pide confirmación para descartar.\n */\n\nimport React, { useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Image, ImageBackground, Modal, Pressable,\n  ScrollView, StyleSheet, Switch, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowLeft, BadgeCheck, Briefcase, Calendar, Camera, Check, ChevronRight,\n  Globe, ImagePlus, Link2, Mail, MapPin, Phone, Plus, QrCode, School,\n  Sparkles, Store, Trash2, Users, X,\n} from 'lucide-react-native';\nimport { alpha, brand, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { pickImageFromCamera, pickImageFromLibrary } from '../core/pickImage';\nimport { authApi, type MeProfile, type ProfileLink, type UpdateProfilePayload, DEFAULT_WIDGETS } from '../api/auth';\nimport { tallasApi, type LbMisMedidas } from '../api/commerce';\nimport { numeroDeCm } from '../constants/tallas';\nimport { gruposEnlacesApi, type LbMiGrupo } from '../api/lifebookGrupos';\nimport { absUrl } from '../api/config';\nimport { COUNTRIES, GQ_CITIES } from '../constants/countries';\nimport { PROFESSIONS, PROFESSION_GROUPS } from '../constants/professions';\nimport { useStatusStore } from '../state/statusStore';\n\n/** Regex de fecha de nacimiento AAAA-MM-DD. */\nconst BIRTH_RE = /^\\d{4}-\\d{2}-\\d{2}$/;\n\n/** Colores de nombre sugeridos (Home/Perfil). 'Blanco' = sin color (por defecto). */\nconst NAME_COLORS = [\n  { label: 'Azul', hex: brand.primary },\n  { label: 'Cian', hex: brand.info },\n  { label: 'Verde', hex: brand.success },\n  { label: 'Amarillo', hex: brand.warning },\n  { label: 'Naranja', hex: '#FF9F43' },\n  { label: 'Rosa', hex: '#FF7BAC' },\n  { label: 'Morado', hex: '#B57BFF' },\n  { label: 'Rojo', hex: brand.danger },\n] as const;\n\n/** Géneros: se guardan en minúscula/valor corto; la etiqueta se muestra capitalizada. */\nconst GENDER_OPTIONS = [\n  { value: 'femenino', label: 'Femenino' },\n  { value: 'masculino', label: 'Masculino' },\n  { value: 'no_decir', label: 'Prefiero no decirlo' },\n] as const;\n\n/** Tipos de enlace admitidos por el perfil (kind → label y placeholder). */\nconst LINK_KINDS: Array<{ kind: ProfileLink['kind']; label: string; placeholder: string; icon: any }> = [\n  { kind: 'link', label: 'Enlace', placeholder: 'https://…', icon: Link2 },\n  { kind: 'email', label: 'Correo', placeholder: 'nombre@correo.com', icon: Mail },\n  { kind: 'phone', label: 'Teléfono', placeholder: '+240 …', icon: Phone },\n  { kind: 'social', label: 'Social', placeholder: '@usuario', icon: Globe },\n  /* El valor de un enlace de GRUPO es el CÓDIGO (6 caracteres), no una dirección: lo\n     normal es elegir el grupo con el selector, pero aquí también se puede pegar un\n     código que te hayan pasado. */\n  { kind: 'group', label: 'Grupo', placeholder: 'Código del grupo, p. ej. 9TN6RV', icon: Users },\n];\n\n/** Widgets del perfil: clave de DEFAULT_WIDGETS → etiqueta en español + icono. */\nconst WIDGET_ROWS: Array<{ key: keyof typeof DEFAULT_WIDGETS; label: string; icon: any }> = [\n  { key: 'lifebookPublic', label: 'Life Book público', icon: Sparkles },\n  { key: 'showStats', label: 'Mostrar estadísticas', icon: Users },\n  { key: 'showStore', label: 'Mostrar tienda', icon: Store },\n  { key: 'showContact', label: 'Permitir contacto', icon: Mail },\n  { key: 'showQR', label: 'Mostrar código QR', icon: QrCode },\n];\n\n/** Normaliza el valor guardado de género al valor corto esperado por el backend. */\nfunction normGender(g?: string | null): string {\n  const v = (g ?? '').toLowerCase().trim();\n  if (v.includes('femenino')) return 'femenino';\n  if (v.includes('masculino')) return 'masculino';\n  return 'no_decir';\n}\n\n/** Mezcla los widgets del servidor con DEFAULT_WIDGETS (tipado booleano). */\nfunction seedWidgets(p: MeProfile): Record<string, boolean> {\n  const out: Record<string, boolean> = {};\n  (Object.keys(DEFAULT_WIDGETS) as Array<keyof typeof DEFAULT_WIDGETS>).forEach((k) => {\n    const v = p.widgets?.[k];\n    out[k] = typeof v === 'boolean' ? v : DEFAULT_WIDGETS[k];\n  });\n  return out;\n}\n\nexport default function EditProfileScreen() {\n  return (\n    <AuthGate>\n      <EditProfileContent />\n    </AuthGate>\n  );\n}\n\nfunction EditProfileContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { status: myStatus } = useStatusStore();\n\n  // ---- Carga del perfil ----\n  const [profile, setProfile] = useState<MeProfile | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [loadError, setLoadError] = useState<string | null>(null);\n  const [reloadKey, setReloadKey] = useState(0);\n\n  // ---- Formulario (sembrado al cargar el perfil) ----\n  const [fullName, setFullName] = useState('');\n  const [nameColor, setNameColor] = useState('');\n  const [bio, setBio] = useState('');\n  const [gender, setGender] = useState('no_decir');\n  const [birthDate, setBirthDate] = useState('');\n  const [birthErr, setBirthErr] = useState<string | null>(null);\n  const [school, setSchool] = useState('');\n  const [country, setCountry] = useState<string | null>(null); // nombre visible\n  const [countryCode, setCountryCode] = useState('GQ');\n  const [city, setCity] = useState('');\n  const [profession, setProfession] = useState<string | null>(null);\n  const [widgets, setWidgets] = useState<Record<string, boolean>>({});\n  /**\n   * Máximo de enlaces FIJADOS. El servidor aplica el mismo número (3): aquí es para\n   * avisar antes de que alguien fije un cuarto y lo vea desaparecer sin explicación.\n   */\n  const MAX_FIJADOS = 3;\n  const [links, setLinks] = useState<ProfileLink[]>([]);\n\n  // ---- Imágenes nuevas (dataURL; solo se envían si cambian) ----\n  const [newAvatar, setNewAvatar] = useState<string | null>(null);\n  const [newCover, setNewCover] = useState<string | null>(null);\n  const [imageError, setImageError] = useState<string | null>(null);\n  // Origen en curso de core/pickImage (muestra \"Procesando…\" y desactiva acciones).\n  const [picking, setPicking] = useState<'library' | 'camera' | null>(null);\n  const [pickingTarget, setPickingTarget] = useState<'avatar' | 'cover' | null>(null);\n\n  // ---- Estado de la pantalla ----\n  const [dirty, setDirty] = useState(false);\n  const [saving, setSaving] = useState(false);\n  const [saveError, setSaveError] = useState<string | null>(null);\n  const hasStatus24 = !!myStatus;\n\n  // ---- Modales ----\n  const [previewOpen, setPreviewOpen] = useState(false);\n  const [locOpen, setLocOpen] = useState(false);\n  const [profOpen, setProfOpen] = useState(false);\n  const [linkOpen, setLinkOpen] = useState(false);\n  /* P3: selector de «enlazar uno de mis grupos». */\n  const [grupoOpen, setGrupoOpen] = useState(false);\n\n  const mark = () => setDirty(true);\n\n  useEffect(() => {\n    let alive = true;\n    setLoading(true);\n    setLoadError(null);\n    authApi.me()\n      .then((p) => {\n        if (!alive) return;\n        setProfile(p);\n        setFullName(p.fullName ?? '');\n        setNameColor(p.nameColor ?? '');\n        setBio(p.bio ?? '');\n        setGender(normGender(p.gender));\n        setBirthDate(p.birthDate ?? '');\n        setSchool(p.school ?? '');\n        setCountry(p.country ?? null);\n        setCountryCode(p.countryCode ?? 'GQ');\n        setCity(p.city ?? '');\n        setProfession(p.profession ?? null);\n        setWidgets(seedWidgets(p));\n        setLinks((p.links ?? []).map((l) => ({ ...l })));\n        setDirty(false);\n      })\n      .catch((e) => {\n        if (alive) setLoadError(e instanceof Error ? e.message : 'No se pudo cargar tu perfil. Inténtalo de nuevo.');\n      })\n      .finally(() => { if (alive) setLoading(false); });\n    return () => { alive = false; };\n  }, [reloadKey]);\n\n  // ---- Volver con control de cambios sin guardar ----\n  const goBack = () => {\n    if (saving) return;\n    if (dirty) {\n      Alert.alert('Descartar cambios', '¿Descartar los cambios sin guardar?', [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Descartar', style: 'destructive', onPress: () => router.back() },\n      ]);\n    } else {\n      router.back();\n    }\n  };\n\n  // ---- Elegir imagen (avatar o portada) con core/pickImage (cámara/galería) ----\n  const pedirOrigen = (target: 'avatar' | 'cover') => {\n    if (picking !== null) return;\n    Alert.alert(\n      target === 'avatar' ? 'Cambiar foto de perfil' : 'Cambiar portada',\n      'Elige el origen de la imagen',\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Cámara', onPress: () => { void procesarImagen(target, 'camera'); } },\n        { text: 'Galería', onPress: () => { void procesarImagen(target, 'library'); } },\n      ],\n    );\n  };\n\n  const procesarImagen = async (target: 'avatar' | 'cover', origen: 'camera' | 'library') => {\n    if (picking !== null) return;\n    setImageError(null);\n    setPicking(origen);\n    setPickingTarget(target);\n    try {\n      const img = origen === 'camera' ? await pickImageFromCamera() : await pickImageFromLibrary();\n      if (img) {\n        if (target === 'avatar') setNewAvatar(img.dataUrl); else setNewCover(img.dataUrl);\n        mark();\n      }\n    } catch (e) {\n      setImageError(e instanceof Error ? e.message : 'No se pudo obtener la imagen. Inténtalo de nuevo');\n    } finally {\n      setPicking(null);\n      setPickingTarget(null);\n    }\n  };\n\n  // ---- Guardar (payload parcial: solo lo que cambió + dataURLs + widgets/links) ----\n  const save = async () => {\n    const name = fullName.trim();\n    if (!name) { setSaveError('Escribe tu nombre para poder guardar'); return; }\n    const bd = birthDate.trim();\n    if (bd && !BIRTH_RE.test(bd)) {\n      setBirthErr('Usa el formato AAAA-MM-DD');\n      setSaveError('Revisa la fecha de nacimiento');\n      return;\n    }\n    if (!profile) return;\n\n    const payload: UpdateProfilePayload = {};\n\n    if (name !== (profile.fullName ?? '').trim()) payload.fullName = name;\n    if ((nameColor ?? '') !== (profile.nameColor ?? '')) payload.nameColor = nameColor || undefined;\n    if (bio !== (profile.bio ?? '')) payload.bio = bio;\n    if (gender !== normGender(profile.gender)) payload.gender = gender;\n    if (birthDate.trim() !== (profile.birthDate ?? '').trim()) payload.birthDate = birthDate.trim();\n    if (school.trim() !== (profile.school ?? '').trim()) payload.school = school.trim();\n\n    // Ubicación: si cualquiera de los tres cambió, se envían juntos.\n    const cCountry = country ?? '';\n    const cCity = city.trim();\n    if (cCountry !== (profile.country ?? '') || countryCode !== (profile.countryCode ?? 'GQ') || cCity !== (profile.city ?? '').trim()) {\n      payload.country = cCountry;\n      payload.countryCode = countryCode;\n      payload.city = cCity;\n    }\n\n    if ((profession ?? '') !== (profile.profession ?? '')) payload.profession = profession ?? undefined;\n\n    if (newAvatar) payload.avatar = newAvatar;\n    if (newCover) payload.cover = newCover;\n\n    // Widgets y enlaces: siempre se envían con el estado local (objeto limpio).\n    payload.widgets = { ...widgets };\n    payload.links = links.map((l) => ({ ...l }));\n\n    setSaving(true);\n    setSaveError(null);\n    try {\n      await authApi.updateMe(payload);\n      router.back();\n    } catch (e) {\n      setSaveError(e instanceof Error ? e.message : 'No se pudo guardar. Inténtalo de nuevo');\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  // ---- Pantalla de carga ----\n  if (loading) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator size=\"large\" color={colors.primary} />\n      </View>\n    );\n  }\n\n  // ---- Error de carga con reintentar ----\n  if (!profile || loadError) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background, paddingHorizontal: espaciado.e28 }]}>\n        <Text style={{ color: colors.danger, fontWeight: '700', textAlign: 'center', fontSize: tipografia.body }}>No se pudo cargar tu perfil.</Text>\n        {loadError ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6, marginBottom: espaciado.e16 }}>{loadError}</Text> : null}\n        <Pressable\n          onPress={() => setReloadKey((k) => k + 1)}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Reintentar\"\n          style={({ pressed }) => [{ backgroundColor: colors.primary, paddingHorizontal: espaciado.e22, paddingVertical: espaciado.e11, borderRadius: radios.md, opacity: pressed ? 0.85 : 1 }]}\n        >\n          <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  const egId = `EG-${(profile.id.replace(/-/g, '').slice(0, 8)).toUpperCase()}`;\n  const avatarDisplay = newAvatar ?? (profile.avatarUrl ? absUrl(profile.avatarUrl) : null);\n  const coverDisplay = newCover ?? (profile.coverUrl ? absUrl(profile.coverUrl) : null);\n  const initial = (fullName.trim() || profile.fullName || 'U').charAt(0).toUpperCase() || 'U';\n  const cityTxt = city.trim();\n  const locationTxt = `${country ?? 'Guinea Ecuatorial'}${cityTxt ? ` · ${cityTxt}` : ''}`;\n  const bioCount = bio.length;\n  const pickingAvatar = picking !== null && pickingTarget === 'avatar';\n  const pickingCover = picking !== null && pickingTarget === 'cover';\n\n  // Información original (creador): solo lectura.\n  const oc = (profile.originalCreator ?? 'not_verified') as 'verified' | 'pending' | 'not_verified';\n  const ocColor = oc === 'verified' ? colors.success : oc === 'pending' ? colors.secondary : colors.textSecondary;\n  const ocLabel = oc === 'verified' ? 'Verificado' : oc === 'pending' ? 'Pendiente' : 'No verificado';\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background }]}>\n      {/* ============ Cabecera fija ============ */}\n      <View style={[styles.topBar, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={goBack} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={{ width: 72, alignItems: 'flex-start' }}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]} numberOfLines={1}>Editar perfil</Text>\n        <Pressable onPress={() => setPreviewOpen(true)} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Vista previa del perfil\" style={{ width: 72, alignItems: 'flex-end' }}>\n          <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Vista previa</Text>\n        </Pressable>\n      </View>\n\n      <ScrollView\n        contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingBottom: insets.bottom + 32 }}\n        showsVerticalScrollIndicator={false}\n        keyboardShouldPersistTaps=\"handled\"\n      >\n        {/* ============ 1) Bloque imagen (portada + avatar) ============ */}\n        <View style={[styles.imageCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          {coverDisplay ? (\n            <ImageBackground source={{ uri: coverDisplay }} style={styles.cover} imageStyle={styles.coverImg}>\n              <View style={styles.coverScrim} pointerEvents=\"none\" />\n            </ImageBackground>\n          ) : (\n            <View style={[styles.cover, styles.coverFallback, { backgroundColor: alpha(colors.primary, 0.14) }]}>\n              <View style={[styles.coverBlob, { right: -26, top: -34, backgroundColor: alpha(colors.secondary, 0.22) }]} pointerEvents=\"none\" />\n              <View style={[styles.coverBlob, { left: -40, bottom: -46, backgroundColor: alpha(colors.primary, 0.16) }]} pointerEvents=\"none\" />\n              <View style={styles.coverFallbackHint} pointerEvents=\"none\">\n                <ImagePlus size={16} color={alpha(colors.primary, 0.85)} />\n                <Text style={{ color: alpha(colors.primary, 0.9), fontSize: tipografia.micro, fontWeight: '800' }}>Añade una portada</Text>\n              </View>\n            </View>\n          )}\n\n          {/* Avatar superpuesto (borde inferior izquierdo de la portada) */}\n          <View style={[styles.avatarWrap, { backgroundColor: colors.card }]}>\n            {avatarDisplay ? (\n              <Image source={{ uri: avatarDisplay }} style={styles.avatarImg} />\n            ) : (\n              <View style={[styles.avatarEmpty, { backgroundColor: alpha(colors.primary, 0.16) }]}>\n                <Text style={[styles.avatarInitial, { color: colors.primary }]}>{initial}</Text>\n              </View>\n            )}\n          </View>\n\n          {/* Acciones de imagen (a la derecha del hueco que deja el avatar) */}\n          <View style={styles.imageActions}>\n            <MiniAction icon={Camera} label=\"Cambiar foto de perfil\" busy={pickingAvatar} disabled={picking !== null} onPress={() => pedirOrigen('avatar')} />\n            <MiniAction icon={ImagePlus} label=\"Cambiar portada\" busy={pickingCover} disabled={picking !== null} onPress={() => pedirOrigen('cover')} />\n            {imageError ? (\n              <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>{imageError}</Text>\n            ) : null}\n            {(newAvatar || newCover) ? (\n              <Text style={{ color: colors.success, fontSize: tipografia.micro, fontWeight: '700', marginTop: espaciado.e4 }}>\n                Imagen{newAvatar && newCover ? 'es' : ''} nueva elegida · se aplicará al guardar\n              </Text>\n            ) : null}\n          </View>\n        </View>\n\n        {/* ============ 2) Información básica ============ */}\n        <SeccionTitle>Información básica</SeccionTitle>\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <FormField\n            label=\"Nombre\"\n            placeholder=\"Tu nombre completo\"\n            value={fullName}\n            onChangeText={(t) => { setFullName(t.slice(0, 120)); mark(); }}\n            maxLength={120}\n            editable={!saving}\n          />\n          {/* Color del nombre (se muestra en Home y Perfil) */}\n          <View style={{ marginTop: espaciado.e10 }}>\n            <Text style={[styles.fieldLabel, { color: colors.textSecondary }]}>Color de tu nombre</Text>\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e9, marginTop: espaciado.e8 }}>\n              {NAME_COLORS.map((c) => {\n                const active = nameColor === c.hex;\n                return (\n                  <Pressable\n                    key={c.hex}\n                    onPress={() => { setNameColor(active ? '' : c.hex); mark(); }}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ checked: active }}\n                    accessibilityLabel={`Color ${c.label}`}\n                    style={[\n                      styles.nameColorDot,\n                      { backgroundColor: c.hex, borderColor: active ? colors.primary : colors.border },\n                      active && { transform: [{ scale: 1.18 }], borderWidth: 2 },\n                    ]}\n                  />\n                );\n              })}\n              <Pressable\n                onPress={() => { setNameColor(''); mark(); }}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Color por defecto (blanco)\"\n                style={[styles.nameColorReset, { borderColor: colors.border, backgroundColor: colors.surface }]}\n              >\n                <Text style={{ color: colors.textSecondary, fontSize: 10, fontWeight: '800' }}>Blanco</Text>\n              </Pressable>\n            </View>\n            <Text style={[styles.fieldHint, { color: colors.textSecondary }]}>\n              Así se verá tu nombre en la Home y en tu perfil.\n            </Text>\n          </View>\n          <View style={[styles.sep, { backgroundColor: colors.border }]} />\n          {/* Estado 24h: acceso a la pantalla de gestión (☰ también enlaza). */}\n          <View style={{ marginTop: espaciado.e6 }}>\n            <Text style={[styles.fieldLabel, { color: colors.textSecondary }]}>Estado 24h</Text>\n            <Pressable\n              onPress={() => router.push('/status' as never)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Gestionar mi estado 24h\"\n              style={({ pressed }) => [styles.statusRow, { borderColor: colors.border, backgroundColor: colors.surface, opacity: pressed ? 0.75 : 1 }]}\n            >\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n                  {hasStatus24 ? 'Ver y cambiar mi estado' : 'Agregar estado 24h'}\n                </Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: 1 }}>\n                  Comparte qué haces · dura 24 horas y desaparece solo.\n                </Text>\n              </View>\n              <ChevronRight size={16} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n          <View style={[styles.sep, { backgroundColor: colors.border }]} />\n          <View>\n            <Text style={[styles.fieldLabel, { color: colors.textSecondary }]}>ID de EG Route Plan</Text>\n            <View style={[styles.idBox, { backgroundColor: colors.surface }]}>\n              <Text style={[styles.idTxt, { color: colors.textPrimary }]}>{egId}</Text>\n              <BadgeCheck size={17} color={colors.primary} />\n            </View>\n            <Text style={[styles.fieldHint, { color: colors.textSecondary }]}>Tu ID es único y no se puede cambiar.</Text>\n          </View>\n        </View>\n\n        {/* ============ 3) Personalización ============ */}\n        <SeccionTitle>Personalización</SeccionTitle>\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline' }}>\n            <Text style={[styles.fieldLabel, { color: colors.textSecondary }]}>Biografía</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700' }}>{bioCount}/300</Text>\n          </View>\n          <Text style={[styles.fieldHint, { color: colors.textSecondary, marginTop: espaciado.e2 }]}>\n            😀 Cuéntale a la comunidad quién eres · 📍 Puedes mencionar tu ciudad\n          </Text>\n          <CampoBio\n            value={bio}\n            onChangeText={(t) => { setBio(t.slice(0, 300)); mark(); }}\n            placeholder=\"Cuéntale a la comunidad quién eres…\"\n            maxLength={300}\n          />\n        </View>\n\n        {/* ============ 4) Datos personales y profesionales ============ */}\n        <SeccionTitle>Datos personales y profesionales</SeccionTitle>\n\n        {/* Género */}\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <Text style={[styles.fieldLabel, { color: colors.textSecondary }]}>Género</Text>\n          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 }}>\n            {GENDER_OPTIONS.map((g) => (\n              <Chip\n                key={g.value}\n                label={g.label}\n                active={gender === g.value}\n                onPress={() => { setGender(g.value); mark(); }}\n              />\n            ))}\n          </View>\n          <View style={[styles.sep, { backgroundColor: colors.border }]} />\n          <FormField\n            label=\"Fecha de nacimiento\"\n            placeholder=\"AAAA-MM-DD\"\n            value={birthDate}\n            error={birthErr ?? undefined}\n            onChangeText={(t) => {\n              setBirthDate(t);\n              if (birthErr) setBirthErr(t && !BIRTH_RE.test(t.trim()) ? birthErr : null);\n              mark();\n            }}\n            maxLength={10}\n            editable={!saving}\n            icon={<Calendar size={18} color={colors.textSecondary} />}\n          />\n        </View>\n\n        {/* Ubicación */}\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <FilaDeCampo\n            icon={MapPin}\n            label=\"Ubicación actual\"\n            hint={locationTxt}\n            onPress={() => setLocOpen(true)}\n            last\n          />\n        </View>\n\n        {/* Ocupación · Escuela · Información original */}\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <FilaDeCampo\n            icon={Briefcase}\n            label=\"Ocupación / Profesión\"\n            hint={profession ?? 'Añadir'}\n            onPress={() => setProfOpen(true)}\n          />\n          <View style={[styles.sep, { backgroundColor: colors.border }]} />\n          <FormField\n            label=\"Institución educativa\"\n            placeholder=\"Universidad o escuela\"\n            value={school}\n            onChangeText={(t) => { setSchool(t.slice(0, 120)); mark(); }}\n            maxLength={120}\n            editable={!saving}\n            icon={<School size={18} color={colors.textSecondary} />}\n          />\n          <View style={[styles.sep, { backgroundColor: colors.border }]} />\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingVertical: espaciado.e2 }}>\n            <View style={[styles.rowIcon, { backgroundColor: alpha(ocColor, 0.12) }]}>\n              <BadgeCheck size={18} color={ocColor} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>Información original</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: 1 }}>\n                Estado de creador original en Life Book\n              </Text>\n            </View>\n            <View style={[styles.statusPill, { backgroundColor: alpha(ocColor, 0.14) }]}>\n              <Text style={{ color: ocColor, fontSize: 10.5, fontWeight: '900' }}>{ocLabel}</Text>\n            </View>\n          </View>\n        </View>\n\n        {/* ============ 5) Gestión ============ */}\n        <SeccionTitle>Gestión</SeccionTitle>\n\n        {/* Widgets */}\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          {WIDGET_ROWS.map((w, i) => (\n            <FilaDeCampo\n              key={w.key}\n              icon={w.icon}\n              label={w.label}\n              last={i === WIDGET_ROWS.length - 1}\n              right={(\n                <Switch\n                  value={widgets[w.key] === true}\n                  onValueChange={(v) => { setWidgets((prev) => ({ ...prev, [w.key]: v })); mark(); }}\n                  trackColor={{ true: colors.primary, false: colors.border }}\n                  accessibilityLabel={w.label}\n                />\n              )}\n            />\n          ))}\n        </View>\n\n        {/* Medidas para la talla (tanda L): se ven aquí y se borran aquí */}\n        <MisMedidasCard colors={colors} />\n\n        {/* Enlaces y correos */}\n        <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <Pressable\n            onPress={() => setLinkOpen(true)}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Añadir enlace o correo\"\n            style={({ pressed }) => [styles.addLinkRow, { borderColor: colors.border, backgroundColor: colors.surface, opacity: pressed ? 0.75 : 1 }]}\n          >\n            <Plus size={17} color={colors.primary} />\n            <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Añadir enlace o correo</Text>\n            <Text style={{ marginLeft: 'auto', color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>{links.length}/8</Text>\n          </Pressable>\n\n          {/* P3 — ENLAZAR UN GRUPO MÍO. Va aparte del botón de arriba porque aquí no se\n              escribe nada: se elige el grupo y el servidor da su código de invitación. */}\n          <Pressable\n            onPress={() => setGrupoOpen(true)}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Enlazar uno de mis grupos\"\n            style={({ pressed }) => [styles.addLinkRow, { borderColor: colors.border, backgroundColor: colors.surface, opacity: pressed ? 0.75 : 1, marginTop: espaciado.e8 }]}\n          >\n            <Users size={17} color={colors.primary} />\n            <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Enlazar uno de mis grupos</Text>\n          </Pressable>\n\n          {links.length === 0 ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e12, lineHeight: 17 }}>\n              Los enlaces, correos o redes que añadas se mostrarán en tu perfil público (máx. 8). Puedes FIJAR hasta {MAX_FIJADOS} con 📌 para que salgan arriba.\n            </Text>\n          ) : (\n            links.map((l, idx) => {\n              const meta = LINK_KINDS.find((k) => k.kind === l.kind) ?? LINK_KINDS[0];\n              const Icon = meta.icon;\n              return (\n                <View key={`${l.kind}-${idx}`} style={[styles.linkRow, { borderBottomColor: colors.border }, idx === links.length - 1 && { borderBottomWidth: 0 }]}>\n                  <View style={[styles.rowIcon, { backgroundColor: alpha(colors.primary, 0.08) }]}>\n                    <Icon size={18} color={colors.primary} />\n                  </View>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }} numberOfLines={1}>{l.label}</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: 1 }} numberOfLines={1}>{l.value}</Text>\n                  </View>\n                  {/* ── FIJAR ──\n                      Un enlace fijado sale ARRIBA y con 📌 en el perfil público (es lo\n                      que se pidió: poder fijar, por ejemplo, el enlace de un grupo). El\n                      máximo de 3 lo aplica el SERVIDOR; aquí se avisa ANTES para que\n                      nadie fije un cuarto y lo vea desaparecer sin explicación. */}\n                  <Pressable\n                    onPress={() => {\n                      const yaFijados = links.filter((x) => x.pinned).length;\n                      if (!l.pinned && yaFijados >= MAX_FIJADOS) {\n                        Alert.alert(\n                          `Ya tienes ${MAX_FIJADOS} enlaces fijados`,\n                          'Quita el pin de uno para poder fijar otro.',\n                        );\n                        return;\n                      }\n                      setLinks((prev) => prev.map((x, i) => (i === idx ? { ...x, pinned: !x.pinned } : x)));\n                      mark();\n                    }}\n                    hitSlop={10}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={l.pinned ? `Dejar de fijar ${l.label}` : `Fijar ${l.label}`}\n                    style={{ paddingHorizontal: espaciado.e8, opacity: l.pinned ? 1 : 0.3 }}\n                  >\n                    <Text style={{ fontSize: tipografia.subtitle }}>📌</Text>\n                  </Pressable>\n\n                  <Pressable\n                    onPress={() => { setLinks((prev) => prev.filter((_, i) => i !== idx)); mark(); }}\n                    hitSlop={10}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`Eliminar ${l.label}`}\n                  >\n                    <Trash2 size={18} color={colors.danger} />\n                  </Pressable>\n                </View>\n              );\n            })\n          )}\n        </View>\n\n        {/* ============ 6) Pie: Guardar ============ */}\n        {saveError ? (\n          <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', textAlign: 'center', marginTop: espaciado.e18 }}>\n            {saveError}\n          </Text>\n        ) : null}\n        <View style={{ marginTop: saveError ? 10 : 22 }}>\n          <PrimaryButton\n            title={saving ? 'Guardando…' : 'Guardar cambios'}\n            onPress={() => { void save(); }}\n            loading={saving}\n            disabled={saving}\n            accessibilityLabel=\"Guardar cambios del perfil\"\n          />\n        </View>\n        <Text style={[styles.footNote, { color: colors.textSecondary }]}>\n          Tu número de teléfono nunca se muestra en tu perfil público.\n        </Text>\n      </ScrollView>\n\n      {/* ============ Modal: Vista previa ============ */}\n      <Modal visible={previewOpen} transparent animationType=\"fade\" onRequestClose={() => setPreviewOpen(false)} statusBarTranslucent>\n        <View style={[styles.backdrop, { backgroundColor: colors.overlay, alignItems: 'center', justifyContent: 'center' }]}>\n          <Pressable style={StyleSheet.absoluteFill} onPress={() => setPreviewOpen(false)} />\n          <View style={[styles.previewCard, { backgroundColor: colors.card }]}>\n            <View style={styles.modalHeaderRow}>\n              <Text style={[styles.modalTitle, { color: colors.textPrimary }]}>Así te ven los demás</Text>\n              <Pressable onPress={() => setPreviewOpen(false)} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\n            </View>\n\n            {/* Mini-preview */}\n            <View style={[styles.previewMini, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }}>\n                <View style={[styles.previewAvatar, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                  {avatarDisplay ? (\n                    <Image source={{ uri: avatarDisplay }} style={styles.previewAvatarImg} />\n                  ) : (\n                    <Text style={[styles.previewAvatarTxt, { color: colors.primary }]}>{initial}</Text>\n                  )}\n                </View>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ color: nameColor || colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }} numberOfLines={1}>\n                    {fullName.trim() || profile.fullName || 'Usuario'}\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e2 }} numberOfLines={1}>\n                    {profession ?? locationTxt}\n                  </Text>\n                </View>\n              </View>\n              {bio.trim() ? (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', lineHeight: 18, marginTop: espaciado.e10 }} numberOfLines={3}>\n                  {bio}\n                </Text>\n              ) : null}\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600', textAlign: 'center', marginTop: espaciado.e10 }}>\n              Los cambios se aplican cuando pulsas «Guardar cambios».\n            </Text>\n            <View style={{ marginTop: espaciado.e14 }}>\n              <PrimaryButton title=\"Cerrar\" onPress={() => setPreviewOpen(false)} />\n            </View>\n          </View>\n        </View>\n      </Modal>\n\n      {/* ============ Modal: Ubicación (país + ciudad GQ / libre) ============ */}\n      <ModalSelectorPais\n        visible={locOpen}\n        country={country}\n        countryCode={countryCode}\n        city={city}\n        onApply={(loc) => {\n          setCountry(loc.country);\n          setCountryCode(loc.countryCode);\n          setCity(loc.city);\n          mark();\n          setLocOpen(false);\n        }}\n        onClose={() => setLocOpen(false)}\n      />\n\n      {/* ============ Modal: Profesión ============ */}\n      <ModalProfesion\n        visible={profOpen}\n        current={profession}\n        onApply={(p) => { setProfession(p); mark(); setProfOpen(false); }}\n        onClose={() => setProfOpen(false)}\n      />\n\n      {/* ============ Modal: Añadir enlace/correo ============ */}\n      <ModalEnlace\n        visible={linkOpen}\n        onAdd={(l) => {\n          if (links.length >= 8) {\n            Alert.alert('Límite alcanzado', 'Puedes añadir hasta 8 enlaces, correos o redes en tu perfil.');\n            return;\n          }\n          setLinks((prev) => [...prev, l]);\n          mark();\n          setLinkOpen(false);\n        }}\n        onClose={() => setLinkOpen(false)}\n      />\n\n      {/* ============ Modal: Enlazar uno de mis grupos (P3) ============ */}\n      <ModalGrupo\n        visible={grupoOpen}\n        onAdd={(l) => {\n          if (links.length >= 8) {\n            Alert.alert('Límite alcanzado', 'Puedes añadir hasta 8 enlaces, correos o redes en tu perfil.');\n            return;\n          }\n          /* Un enlace de grupo NACE FIJADO si queda sitio: se pidió precisamente para\n             eso, para que el grupo se vea arriba en el perfil. Si ya hay 3 fijados se\n             añade sin fijar (y el usuario decide qué quitar). */\n          const yaFijados = links.filter((x) => x.pinned).length;\n          setLinks((prev) => [...prev, { ...l, pinned: yaFijados < MAX_FIJADOS }]);\n          mark();\n          setGrupoOpen(false);\n        }}\n        onClose={() => setGrupoOpen(false)}\n      />\n    </View>\n  );\n}\n\n/* ====================================================================== *\n *  Componentes auxiliares (mismo archivo)\n * ====================================================================== */\n\n/**\n * MERCADO (tanda L) — MIS MEDIDAS.\n *\n * Son las medidas que usa el asistente de talla: **altura, peso y número de calzado, en un solo\n * juego** (petición del dueño: «van juntos, el guardado será juntos»). Antes había dos bloques, ropa\n * y calzado, y podías tener uno sin el otro; ahora es uno y se borra de una vez.\n *\n * Viven aquí (en el perfil) porque son TUYAS: **la tienda nunca las recibe**, solo la talla que\n * elijas al comprar.\n */\nfunction MisMedidasCard({ colors }: { colors: any }) {\n  const [mias, setMias] = useState<LbMisMedidas | null>(null);\n  const [borrando, setBorrando] = useState(false);\n\n  const cargar = React.useCallback(() => {\n    tallasApi.misMedidas().then(setMias).catch(() => setMias({ body: null, feet: null }));\n  }, []);\n  useEffect(() => { cargar(); }, [cargar]);\n\n  /** El servidor devuelve el mismo juego en las dos claves; `feet` es respaldo de datos antiguos. */\n  const juego = mias?.body ?? mias?.feet ?? null;\n\n  const resumen = (): string => {\n    if (!juego) return 'Sin medidas guardadas';\n    const partes: string[] = [];\n    if (juego.heightCm) partes.push(`${juego.heightCm} cm`);\n    if (juego.weightKg) partes.push(`${juego.weightKg} kg`);\n    if (juego.footLengthCm) partes.push(`calzado ${numeroDeCm(juego.footLengthCm)} (pie ${juego.footLengthCm} cm)`);\n    if (juego.chestCm) partes.push(`pecho ${juego.chestCm}`);\n    if (juego.waistCm) partes.push(`cintura ${juego.waistCm}`);\n    if (juego.hipCm) partes.push(`cadera ${juego.hipCm}`);\n    return partes.length ? partes.join(' · ') : 'Sin medidas guardadas';\n  };\n\n  const borrar = () => {\n    Alert.alert(\n      'Borrar mis medidas',\n      'Se borran todas (altura, peso y número de calzado). La próxima vez que mires una talla te las preguntaremos otra vez.',\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        {\n          text: 'Borrar',\n          style: 'destructive',\n          onPress: async () => {\n            setBorrando(true);\n            try { setMias(await tallasApi.borrarMedidas()); }\n            catch { /* si falla, se queda como estaba */ }\n            finally { setBorrando(false); }\n          },\n        },\n      ],\n    );\n  };\n\n  const texto = resumen();\n\n  return (\n    <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n      <View style={styles.row}>\n        <View style={{ flex: 1 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>Mis medidas</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>{texto}</Text>\n        </View>\n        {texto !== 'Sin medidas guardadas' ? (\n          <Pressable\n            onPress={borrar}\n            disabled={borrando}\n            accessibilityLabel=\"Borrar mis medidas\"\n            style={{ paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e8 }}\n          >\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '800' }}>\n              {borrando ? 'Borrando…' : 'Borrar'}\n            </Text>\n          </Pressable>\n        ) : null}\n      </View>\n    </View>\n  );\n}\n\n/** Título de grupo: mayúsculas 11 #8E8E93 con espaciado. */\nfunction SeccionTitle({ children }: { children: React.ReactNode }) {  return <Text style={styles.groupTitle}>{children}</Text>;\n}\n\n/** Píldora seleccionable (género, chips de ciudad, tipos de enlace…). */\nfunction Chip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityState={{ selected: active }}\n      style={({ pressed }) => [\n        styles.chip,\n        {\n          backgroundColor: active ? alpha(colors.primary, 0.12) : colors.surface,\n          borderColor: active ? colors.primary : colors.border,\n          opacity: pressed ? 0.75 : 1,\n        },\n      ]}\n    >\n      <Text style={{ color: active ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: active ? '900' : '700' }}>{label}</Text>\n    </Pressable>\n  );\n}\n\n/** Fila estándar del formulario: icono en caja alfa + etiqueta + hint/control. */\nfunction FilaDeCampo({ icon: Icon, label, hint, onPress, right, last }: {\n  icon: any;\n  label: string;\n  hint?: string;\n  onPress?: () => void;\n  right?: React.ReactNode;\n  last?: boolean;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      disabled={!onPress}\n      accessibilityRole={onPress ? 'button' : undefined}\n      style={({ pressed }) => [\n        styles.row,\n        { backgroundColor: pressed && onPress ? alpha(colors.primary, 0.05) : 'transparent' },\n        !last && { borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.border },\n      ]}\n    >\n      <View style={[styles.rowIcon, { backgroundColor: alpha(colors.primary, 0.08) }]}>\n        <Icon size={18} color={colors.primary} />\n      </View>\n      <Text style={{ flex: 1, color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }} numberOfLines={1}>{label}</Text>\n      {hint ? (\n        <Text style={[styles.rowHint, { color: colors.textSecondary }]} numberOfLines={1}>{hint}</Text>\n      ) : null}\n      {right ?? (onPress ? <ChevronRight size={16} color={colors.textSecondary} /> : null)}\n    </Pressable>\n  );\n}\n\n/** Acción compacta de imagen (cambiar foto de perfil / cambiar portada).\n *  Mientras core/pickImage procesa (busy) muestra spinner + \"Procesando…\". */\nfunction MiniAction({ icon: Icon, label, onPress, busy = false, disabled = false }: {\n  icon: any;\n  label: string;\n  onPress: () => void;\n  busy?: boolean;\n  disabled?: boolean;\n}) {\n  const { colors } = useTheme();\n  const inactive = busy || disabled;\n  return (\n    <Pressable\n      onPress={onPress}\n      disabled={inactive}\n      accessibilityRole=\"button\"\n      accessibilityLabel={label}\n      accessibilityState={{ busy, disabled: inactive }}\n      style={({ pressed }) => [styles.miniAction, { backgroundColor: colors.surface, borderColor: colors.border, opacity: inactive ? 0.55 : pressed ? 0.7 : 1 }]}\n    >\n      {busy ? (\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n          <ActivityIndicator size=\"small\" color={colors.primary} />\n          <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Procesando…</Text>\n        </View>\n      ) : (\n        <>\n          <Icon size={15} color={colors.primary} />\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', flexShrink: 1 }} numberOfLines={1}>{label}</Text>\n        </>\n      )}\n    </Pressable>\n  );\n}\n\n/**\n * Campo de biografía multilínea. El FormField del kit fija su caja en 50 px de\n * alto, insuficiente para 4 líneas: aquí se replica su lenguaje visual\n * (surface, borde 1.5 redondeado y foco azul) en un área multilínea real.\n */\nfunction CampoBio({ value, onChangeText, placeholder, maxLength }: {\n  value: string;\n  onChangeText: (t: string) => void;\n  placeholder: string;\n  maxLength: number;\n}) {\n  const { colors } = useTheme();\n  const [focused, setFocused] = useState(false);\n  return (\n    <TextInput\n      value={value}\n      onChangeText={onChangeText}\n      placeholder={placeholder}\n      placeholderTextColor={colors.textSecondary}\n      multiline\n      numberOfLines={4}\n      maxLength={maxLength}\n      editable\n      onFocus={() => setFocused(true)}\n      onBlur={() => setFocused(false)}\n      style={[\n        styles.bioInput,\n        {\n          backgroundColor: colors.surface,\n          borderColor: focused ? colors.primary : 'transparent',\n          color: colors.textPrimary,\n          textAlignVertical: 'top',\n        },\n      ]}\n    />\n  );\n}\n\n/** Hoja inferior reutilizable (fondo rgba(0,0,0,.45), tarjeta con radio 24 arriba). */\nfunction HojaInferior({ visible, title, subtitle, onClose, children }: {\n  visible: boolean;\n  title: string;\n  subtitle?: string;\n  onClose: () => void;\n  children: React.ReactNode;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <View style={[styles.sheetRoot, { backgroundColor: colors.overlay }]}>\n        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} />\n        <View style={[styles.sheetCard, { backgroundColor: colors.card, paddingBottom: insets.bottom + 18 }]}>\n          <View style={styles.modalHeaderRow}>\n            <View style={{ flex: 1 }}>\n              <Text style={[styles.modalTitle, { color: colors.textPrimary }]}>{title}</Text>\n              {subtitle ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e2 }}>{subtitle}</Text> : null}\n            </View>\n            <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\"><X size={20} color={colors.textSecondary} /></Pressable>\n          </View>\n          {children}\n        </View>\n      </View>\n    </Modal>\n  );\n}\n\n/** Selector de país + ciudad (Guinea Ecuatorial por defecto). */\nfunction ModalSelectorPais({ visible, country, countryCode, city, onApply, onClose }: {\n  visible: boolean;\n  country: string | null;\n  countryCode: string;\n  city: string;\n  onApply: (loc: { country: string; countryCode: string; city: string }) => void;\n  onClose: () => void;\n}) {\n  const { colors } = useTheme();\n  const [q, setQ] = useState('');\n  const [code, setCode] = useState(countryCode || 'GQ');\n  const [cityV, setCityV] = useState(city ?? '');\n  const [otra, setOtra] = useState(false);\n\n  useEffect(() => {\n    if (visible) {\n      const c = countryCode || 'GQ';\n      const cv = city ?? '';\n      setQ('');\n      setCode(c);\n      setCityV(cv);\n      setOtra(c === 'GQ' && cv.trim().length > 0 && !(GQ_CITIES as readonly string[]).includes(cv.trim()));\n    }\n  }, [visible, countryCode, city]);\n\n  const isGQ = code === 'GQ';\n  const filtered = COUNTRIES.filter(\n    (c) => !q.trim() || c.name.toLowerCase().includes(q.trim().toLowerCase()) || c.code.toLowerCase().includes(q.trim().toLowerCase()),\n  );\n\n  const aplicar = () => {\n    const found = COUNTRIES.find((c) => c.code === code) ?? COUNTRIES[0];\n    onApply({ country: found.name, countryCode: found.code, city: cityV.trim() });\n  };\n\n  return (\n    <HojaInferior visible={visible} title=\"Ubicación\" subtitle=\"País y ciudad que verá tu comunidad\" onClose={onClose}>\n      <FormField\n        label=\"Buscar país (nombre o abreviatura)\"\n        placeholder=\"Ej: Guinea Ecuatorial (GQ)…\"\n        value={q}\n        onChangeText={setQ}\n      />\n      <ScrollView style={{ maxHeight: 236, marginTop: espaciado.e6 }} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n        {filtered.length === 0 ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', paddingVertical: espaciado.e14, textAlign: 'center' }}>\n            Sin resultados para «{q}»\n          </Text>\n        ) : (\n          filtered.map((c) => {\n            const active = c.code === code;\n            return (\n              <Pressable\n                key={c.code}\n                onPress={() => { setCode(c.code); if (c.code !== 'GQ') { setCityV(''); setOtra(false); } }}\n                accessibilityRole=\"button\"\n                accessibilityState={{ selected: active }}\n                style={({ pressed }) => [styles.pickRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n              >\n                <Text style={[styles.pickRowTxt, { color: active ? colors.primary : colors.textPrimary, fontWeight: active ? '900' : '600' }]}>\n                  {c.name}\n                </Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700', marginRight: espaciado.e8 }}>{c.code}</Text>\n                {active ? <Check size={18} color={colors.primary} /> : null}\n              </Pressable>\n            );\n          })\n        )}\n      </ScrollView>\n\n      {isGQ ? (\n        <View style={{ marginTop: espaciado.e10 }}>\n          <Text style={[styles.fieldLabel, { color: colors.textSecondary }]}>Ciudad (Guinea Ecuatorial)</Text>\n          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e7, marginTop: espaciado.e6 }}>\n            {GQ_CITIES.map((c) => {\n              const active = cityV.trim() === c;\n              return (\n                <Pressable\n                  key={c}\n                  onPress={() => { setCityV(active ? '' : c); setOtra(false); }}\n                  style={({ pressed }) => [styles.cityChip, { backgroundColor: active ? alpha(colors.primary, 0.14) : colors.surface, borderColor: active ? colors.primary : colors.border, opacity: pressed ? 0.75 : 1 }]}\n                >\n                  <Text style={{ color: active ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{c}</Text>\n                </Pressable>\n              );\n            })}\n            <Pressable\n              onPress={() => setOtra((o) => !o)}\n              style={({ pressed }) => [styles.cityChip, { backgroundColor: otra ? alpha(colors.primary, 0.14) : colors.surface, borderColor: otra ? colors.primary : colors.border, opacity: pressed ? 0.75 : 1 }]}\n            >\n              <Text style={{ color: otra ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>Otra ciudad…</Text>\n            </Pressable>\n          </View>\n          {otra ? (\n            <View style={{ marginTop: espaciado.e8 }}>\n              <FormField label=\"Otra ciudad\" placeholder=\"Escribe tu ciudad…\" value={cityV} onChangeText={setCityV} />\n            </View>\n          ) : null}\n        </View>\n      ) : (\n        <View style={{ marginTop: espaciado.e10 }}>\n          <FormField label=\"Ciudad\" placeholder=\"Escribe tu ciudad…\" value={cityV} onChangeText={setCityV} />\n        </View>\n      )}\n\n      <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e14 }}>\n        <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={onClose} /></View>\n        <View style={{ flex: 1.4 }}><PrimaryButton title=\"Guardar ubicación\" onPress={aplicar} /></View>\n      </View>\n    </HojaInferior>\n  );\n}\n\n/** Selector de profesión agrupado por categoría (Buscar Work). */\nfunction ModalProfesion({ visible, current, onApply, onClose }: {\n  visible: boolean;\n  current: string | null;\n  onApply: (prof: string) => void;\n  onClose: () => void;\n}) {\n  const { colors } = useTheme();\n  const [sel, setSel] = useState('');\n  const [custom, setCustom] = useState('');\n\n  useEffect(() => {\n    if (visible) {\n      const cur = current ?? '';\n      const known = PROFESSIONS.some((p) => p.label === cur);\n      setSel(known ? cur : '');\n      setCustom(known ? '' : cur);\n    }\n  }, [visible, current]);\n\n  const canSave = sel.length > 0 || custom.trim().length > 0;\n\n  const guardar = () => {\n    const final = custom.trim() || sel;\n    if (!final) return;\n    onApply(final);\n  };\n\n  return (\n    <HojaInferior visible={visible} title=\"Profesión\" subtitle=\"Sincronizada con Buscar Work\" onClose={onClose}>\n      <ScrollView style={{ flexShrink: 1, marginTop: espaciado.e4 }} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n        {PROFESSION_GROUPS.map((g) => (\n          <View key={g.categoryId}>\n            <Text style={[styles.groupHeader, { color: '#8E8E93' }]}>{g.categoryLabel}</Text>\n            {g.items.map((p) => {\n              const active = sel === p.label;\n              return (\n                <Pressable\n                  key={p.id}\n                  onPress={() => setSel(active ? '' : p.label)}\n                  accessibilityRole=\"button\"\n                  accessibilityState={{ selected: active }}\n                  style={({ pressed }) => [styles.pickRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n                >\n                  <Text style={[styles.pickRowTxt, { color: active ? colors.primary : colors.textPrimary, fontWeight: active ? '900' : '600' }]}>\n                    {p.label}\n                  </Text>\n                  {active ? <Check size={18} color={colors.primary} /> : null}\n                </Pressable>\n              );\n            })}\n          </View>\n        ))}\n      </ScrollView>\n\n      <View style={{ marginTop: espaciado.e8 }}>\n        <FormField\n          label=\"Otra profesión…\"\n          placeholder=\"Escribe tu profesión\"\n          value={custom}\n          onChangeText={setCustom}\n          maxLength={80}\n        />\n      </View>\n      <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e10 }}>\n        <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={onClose} /></View>\n        <View style={{ flex: 1.4 }}><PrimaryButton title=\"Guardar profesión\" onPress={guardar} disabled={!canSave} /></View>\n      </View>\n    </HojaInferior>\n  );\n}\n\n/** Añadir enlace / correo / teléfono / red social (hasta 8 en total). */\nfunction ModalEnlace({ visible, onAdd, onClose }: {\n  visible: boolean;\n  onAdd: (l: ProfileLink) => void;\n  onClose: () => void;\n}) {\n  const { colors } = useTheme();\n  const [kind, setKind] = useState<ProfileLink['kind']>('link');\n  const [label, setLabel] = useState('');\n  const [value, setValue] = useState('');\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (visible) { setKind('link'); setLabel(''); setValue(''); setError(null); }\n  }, [visible]);\n\n  const meta = LINK_KINDS.find((k) => k.kind === kind) ?? LINK_KINDS[0];\n\n  const anadir = () => {\n    if (!label.trim()) { setError('Pon un nombre para el enlace (p. ej. Instagram, WhatsApp, Web…)'); return; }\n    if (!value.trim()) {\n      setError(kind === 'email' ? 'Escribe un correo válido' : 'Pega la URL o el usuario');\n      return;\n    }\n    onAdd({ kind, label: label.trim(), value: value.trim() });\n  };\n\n  return (\n    <HojaInferior visible={visible} title=\"Añadir enlace o correo\" subtitle=\"Se mostrará en tu perfil público\" onClose={onClose}>\n      <Text style={[styles.fieldLabel, { color: colors.textSecondary, marginTop: espaciado.e2 }]}>Tipo</Text>\n      <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e6 }}>\n        {LINK_KINDS.map((k) => (\n          <Chip key={k.kind} label={k.label} active={kind === k.kind} onPress={() => { setKind(k.kind); setError(null); }} />\n        ))}\n      </View>\n\n      <View style={{ gap: espaciado.e12, marginTop: espaciado.e14 }}>\n        <FormField\n          label=\"Nombre\"\n          placeholder={kind === 'link' ? 'Mi sitio web' : kind === 'email' ? 'Correo de contacto' : kind === 'phone' ? 'WhatsApp' : 'Instagram'}\n          value={label}\n          onChangeText={setLabel}\n          maxLength={60}\n        />\n        <FormField\n          label=\"Valor\"\n          placeholder={meta.placeholder}\n          value={value}\n          onChangeText={setValue}\n          maxLength={140}\n          autoCapitalize=\"none\"\n          autoCorrect={false}\n        />\n      </View>\n\n      {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e8 }}>{error}</Text> : null}\n\n      <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e14 }}>\n        <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={onClose} /></View>\n        <View style={{ flex: 1.4 }}><PrimaryButton title=\"Añadir\" onPress={anadir} /></View>\n      </View>\n    </HojaInferior>\n  );\n}\n\n/**\n * P3 — ELEGIR UNO DE MIS GRUPOS para enlazarlo en el perfil.\n *\n * El valor del enlace es el CÓDIGO de invitación del grupo, así que no se escribe a\n * mano: se elige. Solo aparecen los grupos donde soy DUEÑO o ADMINISTRADOR, porque son\n * los únicos que pueden sacar el código (el servidor responde 403 a los demás): es mejor\n * no ofrecer algo que va a fallar.\n *\n * El código CADUCA a los 7 días. Eso no se avisa aquí para no llenar la pantalla: el\n * perfil público lo comprueba al pintarlo y, si ya no sirve, lo dice él mismo.\n */\nfunction ModalGrupo({ visible, onAdd, onClose }: {\n  visible: boolean;\n  onAdd: (l: ProfileLink) => void;\n  onClose: () => void;\n}) {\n  const { colors } = useTheme();\n  const [grupos, setGrupos] = useState<LbMiGrupo[] | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  /** Id del grupo cuyo código se está pidiendo (para el girador de esa fila). */\n  const [ocupado, setOcupado] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (!visible) return;\n    let vivo = true;\n    setError(null);\n    setGrupos(null);\n    setOcupado(null);\n    gruposEnlacesApi.misGrupos()\n      .then((g) => { if (vivo) setGrupos(g.filter((x) => x.myRole === 'owner' || x.myRole === 'admin')); })\n      .catch((e) => {\n        if (!vivo) return;\n        setGrupos([]);\n        setError(e instanceof Error ? e.message : 'No se pudieron leer tus grupos');\n      });\n    return () => { vivo = false; };\n  }, [visible]);\n\n  const elegir = async (g: LbMiGrupo) => {\n    setOcupado(g.id);\n    setError(null);\n    try {\n      const r = await gruposEnlacesApi.codigo(g.id);\n      onAdd({ kind: 'group', label: (r.title ?? '').trim() || g.title, value: r.code });\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo crear el enlace del grupo');\n    } finally { setOcupado(null); }\n  };\n\n  return (\n    <HojaInferior\n      visible={visible}\n      title=\"Enlazar un grupo\"\n      subtitle=\"Se verá en tu perfil público, con enlace de invitación\"\n      onClose={onClose}\n    >\n      {grupos === null ? (\n        <View style={{ paddingVertical: espaciado.e28, alignItems: 'center' }}>\n          <ActivityIndicator color={colors.primary} />\n        </View>\n      ) : grupos.length === 0 ? (\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', lineHeight: 18, marginTop: espaciado.e4 }}>\n          {error ?? 'No eres dueño ni administrador de ningún grupo. Solo ellos pueden crear el enlace de invitación.'}\n        </Text>\n      ) : (\n        <ScrollView style={{ maxHeight: 360 }} contentContainerStyle={{ gap: espaciado.e8 }} keyboardShouldPersistTaps=\"handled\">\n          {grupos.map((g) => (\n            <Pressable\n              key={g.id}\n              disabled={!!ocupado}\n              onPress={() => void elegir(g)}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Enlazar el grupo ${g.title}`}\n              style={({ pressed }) => [{\n                flexDirection: 'row' as const, alignItems: 'center' as const, gap: espaciado.e10,\n                backgroundColor: colors.surface, borderRadius: 14, padding: espaciado.e10,\n                borderWidth: 1, borderColor: colors.border,\n                opacity: pressed ? 0.8 : 1,\n              }]}\n            >\n              {g.photoUrl ? (\n                <Image source={{ uri: absUrl(g.photoUrl) }} style={{ width: 42, height: 42, borderRadius: radios.md }} />\n              ) : (\n                <View style={{ width: 42, height: 42, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center', backgroundColor: alpha(colors.primary, 0.12) }}>\n                  <Users size={20} color={colors.primary} />\n                </View>\n              )}\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }} numberOfLines={1}>{g.title}</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', marginTop: 1 }} numberOfLines={1}>\n                  {g.members} {g.members === 1 ? 'miembro' : 'miembros'} · {g.myRole === 'owner' ? 'eres el dueño' : 'eres administrador'}\n                </Text>\n              </View>\n              {ocupado === g.id\n                ? <ActivityIndicator size=\"small\" color={colors.primary} />\n                : <ChevronRight size={18} color={colors.textSecondary} />}\n            </Pressable>\n          ))}\n        </ScrollView>\n      )}\n\n      {error && grupos && grupos.length > 0 ? (\n        <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e10 }}>{error}</Text>\n      ) : null}\n\n      <View style={{ marginTop: espaciado.e14 }}>\n        <GhostButton title=\"Cerrar\" onPress={onClose} />\n      </View>\n    </HojaInferior>\n  );\n}\n\n/* ====================================================================== *\n *  Estilos\n * ====================================================================== */\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n\n  // Cabecera\n  topBar: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  topTitle: { fontSize: 17, fontWeight: '900', flex: 1, textAlign: 'center' },\n\n  // Títulos de grupo\n  groupTitle: {\n    fontSize: tipografia.micro, fontWeight: '800', color: '#8E8E93', letterSpacing: 0.5,\n    textTransform: 'uppercase', marginTop: espaciado.e20, marginBottom: espaciado.e8, marginLeft: espaciado.e4,\n  },\n\n  // Tarjetas de grupo\n  card: {\n    borderRadius: radios.lg, borderWidth: StyleSheet.hairlineWidth,\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e16,\n  },\n  sep: { height: StyleSheet.hairlineWidth, marginVertical: espaciado.e16 },\n  fieldLabel: { fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e6, marginLeft: espaciado.e4 },\n  fieldHint: { fontSize: tipografia.micro, fontWeight: '600', marginTop: espaciado.e5, marginLeft: espaciado.e4, lineHeight: 15 },\n  nameColorDot: {\n    width: 30, height: 30, borderRadius: 15, borderWidth: 1,\n  },\n  nameColorReset: {\n    borderRadius: radios.full, paddingHorizontal: espaciado.e10, justifyContent: 'center',\n    borderWidth: 1, minHeight: 30,\n  },\n  statusRow: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    borderRadius: 14, borderWidth: 1, padding: espaciado.e13, marginTop: espaciado.e8,\n  },\n\n  // Bloque imagen\n  imageCard: {\n    marginTop: espaciado.e14, borderRadius: radios.lg, borderWidth: StyleSheet.hairlineWidth,\n    paddingBottom: espaciado.e14, overflow: 'hidden',\n  },\n  cover: { width: '100%', height: 120, justifyContent: 'flex-end', overflow: 'hidden' },\n  coverImg: { resizeMode: 'cover' },\n  coverScrim: { ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(8,14,24,0.16)' },\n  coverFallback: { overflow: 'hidden', alignItems: 'flex-end', justifyContent: 'flex-end' },\n  coverBlob: { position: 'absolute', width: 150, height: 150, borderRadius: 75 },\n  coverFallbackHint: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e5,\n    paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6, borderRadius: radios.full,\n    backgroundColor: 'rgba(255,255,255,0.75)', margin: espaciado.e8,\n  },\n  avatarWrap: {\n    position: 'absolute', top: 120 - 42, left: 14,\n    width: 84, height: 84, borderRadius: 42, borderWidth: 3,\n    overflow: 'hidden',\n  },\n  avatarImg: { width: '100%', height: '100%' },\n  avatarEmpty: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  avatarInitial: { fontSize: 30, fontWeight: '900' },\n  imageActions: { marginTop: 52, paddingLeft: 116, paddingRight: espaciado.e14, gap: espaciado.e8 },\n  miniAction: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    borderRadius: radios.md, borderWidth: StyleSheet.hairlineWidth,\n    paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10,\n  },\n\n  // Fila genérica\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingVertical: espaciado.e12 },\n  rowIcon: { width: 32, height: 32, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\n  rowHint: { fontSize: tipografia.caption, fontWeight: '600', maxWidth: '46%', textAlign: 'right' },\n\n  // ID de EG Route Plan\n  idBox: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    borderRadius: 14, paddingHorizontal: espaciado.e14, height: 48,\n  },\n  idTxt: { fontSize: 15, fontWeight: '800', letterSpacing: 1 },\n\n  // Chip\n  chip: {\n    borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8,\n  },\n\n  // Biografía\n  bioInput: {\n    borderRadius: 14, borderWidth: 1.5, minHeight: 112,\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e12, fontSize: 14.5, fontWeight: '600', lineHeight: 20,\n  },\n\n  // Enlaces\n  addLinkRow: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e11,\n  },\n  linkRow: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n    paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n\n  // Pie\n  footNote: { textAlign: 'center', fontSize: 10.5, fontWeight: '600', marginTop: espaciado.e10 },\n\n  // Modales\n  backdrop: { flex: 1 },\n  previewCard: {\n    width: '88%', maxWidth: 340, borderRadius: 22,\n    padding: espaciado.e18, paddingBottom: espaciado.e20,\n  },\n  previewMini: {\n    borderRadius: radios.lg, borderWidth: StyleSheet.hairlineWidth,\n    padding: espaciado.e14, marginTop: espaciado.e14,\n  },\n  previewAvatar: {\n    width: 64, height: 64, borderRadius: 32, borderWidth: 2,\n    alignItems: 'center', justifyContent: 'center', overflow: 'hidden',\n  },\n  previewAvatarImg: { width: '100%', height: '100%' },\n  previewAvatarTxt: { fontSize: 24, fontWeight: '900' },\n\n  // Hojas inferiores\n  sheetRoot: { flex: 1, justifyContent: 'flex-end' },\n  sheetCard: {\n    borderTopLeftRadius: 24, borderTopRightRadius: 24,\n    paddingHorizontal: espaciado.e18, paddingTop: espaciado.e18, maxHeight: '86%',\n  },\n  modalHeaderRow: {\n    flexDirection: 'row', alignItems: 'flex-start', justifyContent: 'space-between',\n    marginBottom: espaciado.e6,\n  },\n  modalTitle: { fontSize: 17, fontWeight: '900' },\n\n  // Listas dentro de las hojas\n  groupHeader: { fontSize: tipografia.micro, fontWeight: '800', letterSpacing: 0.5, textTransform: 'uppercase', marginTop: espaciado.e10, marginBottom: espaciado.e2, marginLeft: espaciado.e4 },\n  pickRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e11, paddingHorizontal: espaciado.e4 },\n  pickRowTxt: { flex: 1, fontSize: tipografia.body, fontWeight: '600' },\n  cityChip: { borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\n  statusPill: { borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5 },\n});\n","/**\n * pickImage — utilidad robusta de captura/selección de imagen (perfil, etc.).\n *\n * Por qué NO se usa `base64: true` inline de expo-image-picker: en algunos HAL\n * de Android (p. ej. MediaTek) el retorno con base64 inline se cuelga o vuelve\n * vacío (mismo fallo que tenía la cámara). Aquí se pide solo la URI y el base64\n * se obtiene después con expo-file-system (con respaldo fetch + FileReader),\n * mostrando un estado \"Procesando…\" mientras tanto.\n */\n\nimport * as ImagePicker from 'expo-image-picker';\nimport { readAsStringAsync } from 'expo-file-system';\nimport { Platform } from 'react-native';\n\nexport interface PickedImage {\n  dataUrl: string;      // data:image/jpeg;base64,…\n  uri: string;\n}\n\n/** URI local (file://) → base64 sin depender del base64 inline del picker. */\nexport async function uriToBase64(uri: string): Promise<string | null> {\n  try {\n    return await readAsStringAsync(uri, { encoding: 'base64' });\n  } catch {\n    // Respaldo: fetch + Blob + FileReader.\n    try {\n      const resp = await fetch(uri);\n      const blob = await resp.blob();\n      return await new Promise<string | null>((resolve) => {\n        try {\n          const fr = new FileReader();\n          fr.onload = () => {\n            const s = String(fr.result ?? '');\n            const idx = s.indexOf(',');\n            resolve(idx >= 0 ? s.slice(idx + 1) : s || null);\n          };\n          fr.onerror = () => resolve(null);\n          fr.readAsDataURL(blob);\n        } catch {\n          resolve(null);\n        }\n      });\n    } catch {\n      return null;\n    }\n  }\n}\n\n/**\n * Abre la galería y devuelve la imagen en dataURL.\n * NOTA: NO se usa allowsEditing/aspect en Android: el recorte del sistema\n * (com.android.camera.action.CROP) no existe en muchos dispositivos y hace que\n * el picker vuelva cancelado al instante. El recorte visual lo aplica la UI\n * (avatar circular); la imagen se guarda completa.\n * En Android 13+ el photo picker del sistema no exige permiso de biblioteca\n * (pedirlo devuelve granted=false sin diálogo y bloquea el flujo), así que solo\n * se solicita en Android ≤12 o iOS.\n * Si el usuario cancela devuelve null. Lanza Error con mensaje en español si\n * no hay permiso o no se puede leer el archivo.\n */\nexport async function pickImageFromLibrary(): Promise<PickedImage | null> {\n  const android13plus = Platform.OS === 'android' && Number(Platform.Version ?? 0) >= 33;\n  if (!android13plus) {\n    const perm = await ImagePicker.getMediaLibraryPermissionsAsync().catch(() => null);\n    if (perm && !perm.granted && perm.canAskAgain) {\n      const asked = await ImagePicker.requestMediaLibraryPermissionsAsync().catch(() => null);\n      if (!asked?.granted) throw new Error('Necesitamos permiso para acceder a tus fotos');\n    }\n  }\n  const res = await ImagePicker.launchImageLibraryAsync({\n    mediaTypes: ['images'],\n    quality: 0.55,\n    selectionLimit: 1,\n  });\n  if (res.canceled || !res.assets?.[0]) return null;\n  const asset = res.assets[0];\n  const b64 = await uriToBase64(asset.uri);\n  if (!b64) throw new Error('No se pudo leer la imagen; prueba con otra');\n  return { dataUrl: `data:image/jpeg;base64,${b64}`, uri: asset.uri };\n}\n\n/** Abre la cámara y devuelve la imagen en dataURL (sin recorte, como selfie). */\nexport async function pickImageFromCamera(): Promise<PickedImage | null> {\n  const perm = await ImagePicker.getCameraPermissionsAsync().catch(() => null);\n  if (!perm?.granted) {\n    const asked = await ImagePicker.requestCameraPermissionsAsync().catch(() => null);\n    if (!asked?.granted) throw new Error('Necesitamos permiso para usar la cámara');\n  }\n  const res = await ImagePicker.launchCameraAsync({\n    mediaTypes: ['images'],\n    quality: 0.55,\n    cameraType: ImagePicker.CameraType.back,\n  });\n  if (res.canceled || !res.assets?.[0]) return null;\n  const asset = res.assets[0];\n  const b64 = await uriToBase64(asset.uri);\n  if (!b64) throw new Error('No se pudo leer la foto; prueba de nuevo');\n  return { dataUrl: `data:image/jpeg;base64,${b64}`, uri: asset.uri };\n}\n\n/**\n * Abre la galería en MODO MÚLTIPLE (galería del Estado 24h).\n * Devuelve hasta `max` imágenes en dataURL. En Android 13+ el photo picker del\n * sistema permite selección múltiple sin permiso de biblioteca.\n */\nexport async function pickImagesFromLibrary(max = 4): Promise<PickedImage[]> {\n  const android13plus = Platform.OS === 'android' && Number(Platform.Version ?? 0) >= 33;\n  if (!android13plus) {\n    const perm = await ImagePicker.getMediaLibraryPermissionsAsync().catch(() => null);\n    if (perm && !perm.granted && perm.canAskAgain) {\n      const asked = await ImagePicker.requestMediaLibraryPermissionsAsync().catch(() => null);\n      if (!asked?.granted) throw new Error('Necesitamos permiso para acceder a tus fotos');\n    }\n  }\n  const res = await ImagePicker.launchImageLibraryAsync({\n    mediaTypes: ['images'],\n    quality: 0.55,\n    allowsMultipleSelection: true,\n    selectionLimit: max,\n    orderedSelection: true,\n  });\n  if (res.canceled || !res.assets?.length) return [];\n  const out: PickedImage[] = [];\n  for (const asset of res.assets.slice(0, max)) {\n    const b64 = await uriToBase64(asset.uri);\n    if (b64) out.push({ dataUrl: `data:image/jpeg;base64,${b64}`, uri: asset.uri });\n  }\n  return out;\n}\n","/**\n * api/commerce.ts — cliente del módulo de COMERCIO de Life Book (Parte 33).\n *\n * Rutas reales (mismo montaje que el resto de Life Book):\n *   https://hk.egrouteplan.com/wallet/api/v1/lifebook/commerce/*\n * El producto/servicio vive en la tienda del usuario autenticado: el servidor\n * saca el dueño del token, así que aquí nunca se manda un `ownerId`.\n */\nimport { http, httpRequest } from './httpClient';\n\n// ────────────────────────────── tipos ────────────────────────────────────────\nexport type LbServiceType = 'physical' | 'food' | 'hotel_room' | 'rental' | 'job' | 'local_service';\nexport type LbPriceMode = 'fixed' | 'from' | 'on_request';\nexport type LbStockMode = 'exact' | 'approximate' | 'on_request' | 'unlimited';\nexport type LbCondition = 'new' | 'used' | 'made_to_order';\nexport type LbProductStatus = 'draft' | 'pending' | 'active' | 'rejected' | 'hidden' | 'sold_out';\nexport type LbPayMethod = 'cash_on_delivery' | 'billing' | 'likebook_wallet' | 'in_store' | 'deposit' | 'transfer';\nexport type LbVerificationLevel = 'basic' | 'verified' | 'recommended';\n\n/** Atributo que el formulario debe pintar (viene de la categoría elegida). */\nexport interface LbCategoryAttribute {\n  key: string;\n  label: string;\n  type?: 'text' | 'number' | 'bool' | 'select';\n  options?: string[];\n}\n\nexport interface LbCategory {\n  id: string;\n  code: string;\n  name: string;\n  icon: string | null;\n  serviceType: LbServiceType;\n  defaultAttributes: LbCategoryAttribute[];\n  /**\n   * MERCADO (tanda K) — los EJES DE ELECCIÓN que sugiere la categoría (ropa propone Talla + Color;\n   * calzado, tallas de zapato; teléfonos, almacenamiento + color…). Igual que `defaultAttributes`,\n   * es una sugerencia: el comerciante añade el eje de un toque y luego lo ajusta.\n   *\n   * OJO: aquí los valores vienen como **texto suelto** (`[\"XS\",\"S\",\"M\"]`), porque es lo que hay\n   * guardado en `categories.default_options`; los ejes de un producto ya usan objetos con su foto.\n   * El tipo lo dice para que nadie lea `v.value` de una cadena y publique «undefined».\n   */\n  defaultOptions?: LbOptionSuggestion[];\n  children?: LbCategory[];\n}\n\n/** Un eje SUGERIDO por la categoría: sus valores pueden venir como texto o ya como objeto. */\nexport interface LbOptionSuggestion {\n  code: string;\n  label: string;\n  kind: LbOptionKind;\n  chartKind?: LbSizeKind | null;\n  values?: (string | LbOptionValue)[];\n}\n\n/**\n * MERCADO (tanda K) — LOS EJES DE ELECCIÓN DE UN PRODUCTO.\n *\n * Lo que el comprador elige antes de comprar: «Color», «Talla», «Almacenamiento», «Formato»,\n * «Tono», «Medida»… Hasta ahora la ficha solo podía enseñar el `name` de la variante («Talla 42»)\n * y los botones Comprar/Añadir al carrito compraban DIRECTO con la primera que apareciera.\n *\n * En un eje de color, **cada valor lleva su foto real del producto en ese color** (`imageUrl`): el\n * servidor no admite un color sin foto ni una foto que no sea de ese producto. No es un adorno: es\n * la diferencia entre elegir «Rojo» y ver la prenda roja.\n */\nexport type LbOptionKind = 'color' | 'size' | 'text';\n\nexport interface LbOptionValue {\n  value: string;\n  label?: string | null;\n  imageUrl?: string | null;\n  hex?: string | null;\n}\n\nexport interface LbOptionGroup {\n  id?: string;\n  code: string;\n  label: string;\n  kind: LbOptionKind;\n  /** Solo en los ejes de talla: contra qué tabla se recomienda (top/bottom/dress/shoes/…). */\n  chartKind?: LbSizeKind | null;\n  values: LbOptionValue[];\n}\n\n/** Lo mismo, pero como lo manda la app al publicar o al guardar. */\nexport type LbOptionGroupInput = LbOptionGroup;\n\n/** Tipo de prenda de una tabla de tallas (el mismo vocabulario que el servidor). */\nexport type LbSizeKind = 'top' | 'bottom' | 'dress' | 'shoes' | 'accessory' | 'other';\nexport type LbSizeGender = 'women' | 'men' | 'unisex';\n\n/** Una talla con sus RANGOS en cm/kg (una talla no es un número exacto: es un intervalo). */\nexport interface LbSizeRow {\n  sizeLabel: string;\n  chestMinCm?: number | null;\n  chestMaxCm?: number | null;\n  waistMinCm?: number | null;\n  waistMaxCm?: number | null;\n  hipMinCm?: number | null;\n  hipMaxCm?: number | null;\n  heightMinCm?: number | null;\n  heightMaxCm?: number | null;\n  weightMinKg?: number | null;\n  weightMaxKg?: number | null;\n  footLengthMinCm?: number | null;\n  footLengthMaxCm?: number | null;\n  footWidthMinCm?: number | null;\n  footWidthMaxCm?: number | null;\n}\n\nexport interface LbSizeChart {\n  gender: LbSizeGender;\n  kind: LbSizeKind;\n  notes?: string | null;\n  rows: LbSizeRow[];\n}\n\nexport interface LbProductMedia {\n  url: string;\n  type: 'image' | 'video';\n  position: number;\n  width?: number;\n  height?: number;\n}\n\nexport interface LbProductVariant {\n  id?: string;\n  name: string;\n  priceXaf: number | null;\n  stockQuantity: number;\n  sku?: string | null;\n  imageUrl?: string | null;\n  weightG?: number | null;\n  attributes?: Record<string, string | number | boolean>;\n}\n\nexport interface LbPaymentMethodConfig {\n  method: LbPayMethod;\n  status: 'active' | 'pending_approval' | 'coming_soon' | 'disabled';\n  note?: string | null;\n}\n\nexport interface LbShippingPolicy {\n  id: string;\n  name: string;\n  originCity: string | null;\n  originBarrio?: string | null;\n  originRegion: string | null;\n  coverage: string[];\n  transportModes: string[];\n  estimatedTime: string | null;\n  costMode: 'fixed' | 'calculated' | 'on_request';\n  baseCostXaf: number;\n  perKmXaf?: number;\n  shipsInternational: boolean;\n  internationalNote: string | null;\n}\n\nexport interface LbShop {\n  id: string;\n  ownerId: string;\n  name: string;\n  logoUrl: string | null;\n  coverUrl: string | null;\n  categoryId: string | null;\n  sellerType: 'local' | 'national' | 'international';\n  country: string;\n  city: string | null;\n  barrio: string | null;\n  region: 'continental' | 'insular' | 'other' | null;\n  addressReference: string | null;\n  lat: number | null;\n  lng: number | null;\n  description: string | null;\n  contactMode: string;\n  openingHours: Record<string, unknown>;\n  verificationLevel: LbVerificationLevel;\n  isVerified: boolean;\n  rating: number;\n  ratingCount: number;\n  followersCount: number;\n  isActive: boolean;\n  ecomerse: boolean;\n  createdAt: string;\n  paymentMethods: LbPaymentMethodConfig[];\n  shippingPolicies: LbShippingPolicy[];\n  owner?: { id: string; name: string | null; avatarUrl: string | null; city: string | null };\n  following?: boolean;\n  followedByMe?: boolean;\n  stats?: { products: number; sales: number; services: number; followers: number };\n  activeProducts?: number;\n  pendingProducts?: number;\n}\n\nexport interface LbProduct {\n  id: string;\n  shopId: string;\n  categoryId: string | null;\n  serviceType: LbServiceType;\n  title: string;\n  shortDescription: string | null;\n  longDescription: string | null;\n  priceMode: LbPriceMode;\n  priceXaf: number | null;\n  oldPriceXaf: number | null;\n  currency: string;\n  stockMode: LbStockMode;\n  stockQuantity: number;\n  condition: LbCondition;\n  status: LbProductStatus;\n  rejectionReason: string | null;\n  originCity: string | null;\n  originBarrio: string | null;\n  originRegion: string | null;\n  shipsInternational: boolean;\n  media: LbProductMedia[];\n  tags: string[];\n  rating: number;\n  ratingCount: number;\n  salesCount: number;\n  viewsCount: number;\n  savesCount: number;\n  createdAt: string;\n  publishedAt: string | null;\n  variants: LbProductVariant[];\n  /**\n   * MERCADO (tanda K): los ejes de elección con sus valores (y la foto real de cada color). Vienen\n   * en la MISMA lectura que las variantes, que es lo que el selector necesita a la vez para saber\n   * qué combinación se puede comprar y cuál está agotada.\n   */\n  options?: LbOptionGroup[];\n  attributes: { key: string; value: string }[];\n  shippingPolicy: LbShippingPolicy | null;\n  paymentMethods: LbPaymentMethodConfig[];\n  shop: {\n    id: string;\n    ownerId?: string;\n    name: string;\n    logoUrl: string | null;\n    coverUrl?: string | null;\n    sellerType: string;\n    verificationLevel: LbVerificationLevel;\n    isVerified: boolean;\n    city: string | null;\n    barrio?: string | null;\n    region: string | null;\n    lat?: number | null;\n    lng?: number | null;\n    rating: number;\n    ratingCount: number;\n    followersCount: number;\n  };\n  isMine: boolean;\n  savedByMe: boolean;\n  /**\n   * MERCADO (tanda G): `true` si esta persona pidió que se le avise cuando vuelva el stock\n   * («avísame cuando llegue»). El aviso llega por el chat con la tienda.\n   */\n  watching?: boolean;\n  /**\n   * MERCADO (tanda H): cuántas personas esperan que vuelva a haber stock. **Solo llega al dueño**\n   * (al comprador no se le enseña: es información de la tienda).\n   */\n  waitingCount?: number;\n}\n\n/** Tarjeta del catálogo (más ligera que la ficha). */\nexport interface LbProductCard {\n  id: string;\n  title: string;\n  /**\n   * El subtítulo que el comerciante escribe al publicar (`products.short_description`). Va\n   * en la rejilla del catálogo y en el tab «Productos» del perfil; el texto LARGO no se manda\n   * aquí. El servidor ya lo devolvía: solo faltaba en este tipo.\n   */\n  shortDescription?: string | null;\n  /** Moneda del precio (el servidor manda 'XAF' si no hay otra). */\n  currency?: string;\n  serviceType: LbServiceType;\n  priceMode: LbPriceMode;\n  priceXaf: number | null;\n  oldPriceXaf: number | null;\n  condition: LbCondition;\n  stockMode: LbStockMode;\n  stockQuantity: number;\n  coverUrl: string | null;\n  media: LbProductMedia[];\n  tags: string[];\n  rating: number;\n  ratingCount: number;\n  salesCount: number;\n  originCity: string | null;\n  originRegion: string | null;\n  shipsInternational: boolean;\n  createdAt: string;\n  shop: {\n    id: string;\n    name: string;\n    logoUrl: string | null;\n    city: string | null;\n    region: string | null;\n    isVerified: boolean;\n    verificationLevel: LbVerificationLevel;\n    rating: number;\n    ratingCount: number;\n  };\n}\n\nexport interface LbProductPage {\n  items: LbProductCard[];\n  nextCursor: string | null;\n  total: number;\n}\n\n/** Producto propio en el panel del comerciante (cualquier estado). */\nexport interface LbMyProductCard {\n  id: string;\n  title: string;\n  serviceType: LbServiceType;\n  status: LbProductStatus;\n  rejectionReason: string | null;\n  priceMode: LbPriceMode;\n  priceXaf: number | null;\n  coverUrl: string | null;\n  stockMode: LbStockMode;\n  stockQuantity: number;\n  variants: number;\n  viewsCount: number;\n  savesCount: number;\n  salesCount: number;\n  /**\n   * MERCADO (tanda H): cuánta gente está esperando que vuelva a haber stock. Es el dato que dice\n   * si merece la pena reponer; 0 = nadie espera.\n   */\n  waitingCount?: number;\n  createdAt: string;\n  updatedAt: string;\n}\n\nexport interface LbShopInput {\n  name: string;\n  categoryId?: string | null;\n  sellerType?: 'local' | 'national' | 'international';\n  country?: string;\n  city?: string;\n  barrio?: string;\n  region?: 'continental' | 'insular' | 'other';\n  addressReference?: string;\n  lat?: number;\n  lng?: number;\n  description?: string;\n  logoUrl?: string | null;\n  coverUrl?: string | null;\n  paymentMethods?: LbPayMethod[];\n  shippingPolicy?: {\n    name?: string;\n    coverage?: string[];\n    transportModes?: string[];\n    estimatedTime?: string;\n    costMode?: 'fixed' | 'calculated' | 'on_request';\n    baseCostXaf?: number;\n    perKmXaf?: number;\n    shipsInternational?: boolean;\n    internationalNote?: string;\n  } | null;\n}\n\nexport interface LbProductInput {\n  categoryId?: string | null;\n  serviceType: LbServiceType;\n  title: string;\n  shortDescription?: string | null;\n  longDescription?: string | null;\n  priceMode?: LbPriceMode;\n  priceXaf?: number | null;\n  oldPriceXaf?: number | null;\n  stockMode?: LbStockMode;\n  stockQuantity?: number;\n  condition?: LbCondition;\n  originCity?: string;\n  originBarrio?: string;\n  originRegion?: 'continental' | 'insular' | 'other';\n  shipsInternational?: boolean;\n  shippingPolicyId?: string | null;\n  media?: { url: string; type?: 'image' | 'video'; width?: number; height?: number }[];\n  tags?: string[];\n  variants?: LbProductVariant[];\n  /**\n   * MERCADO (tanda K): los ejes de elección. Si se mandan, cada variante tiene que decir su valor\n   * en CADA eje (`variant.attributes = { color: 'Rojo', talla: 'M' }`): una talla que no existe en\n   * el eje no se puede guardar (el servidor responde 400 y no escribe nada).\n   */\n  options?: LbOptionGroupInput[];\n  attributes?: { key: string; value: string }[];\n}\n\n// ────────────────────────────── cliente ──────────────────────────────────────\nconst BASE = '/lifebook/commerce';\n\nexport const commerceApi = {\n  // Público\n  categories: () => http.get<{ categories: LbCategory[] }>(`${BASE}/categories`),\n  catalog: (opts: {\n    q?: string; city?: string; serviceType?: string; categoryId?: string;\n    priceMin?: number; priceMax?: number; sort?: 'recent' | 'price_asc' | 'price_desc' | 'rating';\n    cursor?: string; limit?: number; shopId?: string;\n  } = {}) => {\n    const qs = new URLSearchParams();\n    Object.entries(opts).forEach(([k, v]) => {\n      if (v !== undefined && v !== null && v !== '') qs.append(k, String(v));\n    });\n    const q = qs.toString();\n    return http.get<LbProductPage>(`${BASE}/catalog${q ? `?${q}` : ''}`);\n  },\n  /** Ficha pública (si hay sesión, además dice si es mía y si la guardé). */\n  product: (id: string) => http.get<{ product: LbProduct }>(`${BASE}/products/${id}`),\n  shop: (id: string) => http.get<{ shop: LbShop }>(`${BASE}/shops/${id}`),\n  shopProducts: (id: string, opts: { cursor?: string; limit?: number; serviceType?: string } = {}) => {\n    const qs = new URLSearchParams();\n    if (opts.cursor) qs.append('cursor', opts.cursor);\n    if (opts.limit) qs.append('limit', String(opts.limit));\n    if (opts.serviceType) qs.append('serviceType', opts.serviceType);\n    const q = qs.toString();\n    return http.get<LbProductPage | { items: LbMyProductCard[] }>(`${BASE}/shops/${id}/products${q ? `?${q}` : ''}`);\n  },\n\n  // Mi tienda\n  myShop: () => http.get<{ shop: LbShop | null }>(`${BASE}/my/shop`),\n  createShop: (input: LbShopInput) => http.post<{ shop: LbShop }>(`${BASE}/shops`, input),\n  updateShop: (input: Partial<LbShopInput>) => http.patch<{ shop: LbShop }>(`${BASE}/my/shop`, input),\n\n  // Productos\n  myProducts: () => http.get<{ items: LbMyProductCard[] }>(`${BASE}/my/products`),\n  /**\n   * Publicar. Parte 34: acepta la **clave de idempotencia** para que un doble\n   * toque o un reintento de red no cree dos productos (el cliente de la app no\n   * la mandaba: solo lo hacía el E2E). Se usa `httpRequest` porque `http.post`\n   * solo admite `auth`, no cabeceras.\n   */\n  createProduct: (input: LbProductInput, idemKey?: string) =>\n    httpRequest<{ product: LbProduct }>(`${BASE}/products`, {\n      method: 'POST',\n      body: input,\n      ...(idemKey ? { headers: { 'Idempotency-Key': idemKey } } : {}),\n    }),\n  updateProduct: (id: string, input: Partial<LbProductInput>) =>\n    http.put<{ product: LbProduct }>(`${BASE}/products/${id}`, input),\n\n  /**\n   * MERCADO (tanda K) — LOS EJES DE UN PRODUCTO.\n   *\n   * Es PÚBLICO porque lo necesita el selector que se abre al pulsar «Comprar» o «Añadir al\n   * carrito»: hasta esta tanda esos dos botones compraban DIRECTO con la primera variante que\n   * apareciera (`p.variants?.[0]`) y nadie elegía talla ni color. Devuelve los ejes con la foto de\n   * cada color y las combinaciones con su precio y su stock, para saber qué está agotado.\n   */\n  options: (id: string) =>\n    http.get<{ options: LbOptionGroup[]; variants: LbProductVariant[] }>(`${BASE}/products/${id}/options`),\n  /**\n   * El comerciante guarda los ejes de SU producto y, si los manda, las combinaciones con su precio\n   * y su stock. **No devuelve la publicación a revisión** (a diferencia de `updateProduct`):\n   * corregir el precio de una talla no puede costar la cola de moderación. Las combinaciones que ya\n   * existían se actualizan en su sitio, así que a nadie se le vacía el carrito.\n   */\n  setOptions: (id: string, input: { options: LbOptionGroupInput[]; variants?: LbProductVariant[] }) =>\n    http.put<{ options: LbOptionGroup[]; variants: LbProductVariant[] }>(`${BASE}/products/${id}/options`, input),\n\n  // Tallas y medidas (tanda J)\n  /** Las tablas de tallas del producto, con sus rangos en cm/kg (público). */\n  sizeChart: (id: string) => http.get<{ charts: LbSizeChart[] }>(`${BASE}/products/${id}/size-chart`),\n  /** El comerciante guarda las tablas de SU producto. Se reemplazan enteras. */\n  setSizeChart: (id: string, charts: LbSizeChart[]) =>\n    http.put<{ charts: LbSizeChart[] }>(`${BASE}/products/${id}/size-chart`, { charts }),\n  /**\n   * Acciones del vendedor sobre su propio producto. Parte 39: se añade\n   * `publish` (enviar a revisión), que es la única forma de volver a publicar\n   * algo rechazado o en borrador — el servidor ya no deja autoaprobarse.\n   */\n  setProductStatus: (id: string, action: 'hide' | 'activate' | 'sold_out' | 'draft' | 'publish') =>\n    http.patch<{ id: string; status: LbProductStatus }>(`${BASE}/products/${id}/status`, { action }),\n  deleteProduct: (id: string) =>\n    httpRequest<{ deleted: boolean; id: string }>(`${BASE}/products/${id}`, { method: 'DELETE' }),\n\n  // Guardados y seguidores\n  toggleSave: (id: string) => http.post<{ saved: boolean }>(`${BASE}/products/${id}/save`, {}),\n  mySaved: () => http.get<{ items: LbProductCard[] }>(`${BASE}/my/saved`),\n  toggleFollow: (shopId: string) => http.post<{ following: boolean }>(`${BASE}/shops/${shopId}/follow`, {}),\n\n  /**\n   * MERCADO (tanda F) — HISTORIAL DE PRODUCTOS.\n   *\n   * Lo que la persona ha mirado, lo último primero, con **la misma tarjeta del catálogo** (el\n   * servidor usa la misma función) más `viewedAt`, `times` y `available`. Los que ya no están a la\n   * venta vienen con `available: false`: se dicen, no se esconden.\n   */\n  misVistos: (limit = 40) => http.get<{ items: LbViewedProduct[]; total: number }>(`${BASE}/my/views?limit=${limit}`),\n  /**\n   * Apuntar que he mirado este producto. Es una llamada PROPIA y con sesión a propósito: la ficha\n   * (`GET products/:id`) es pública, así que con el token caducado salía sin identidad y la visita\n   * se perdía en silencio (visto en el teléfono: un 401 en `my/cart`, un 200 anónimo en la ficha y\n   * la tabla vacía). Con sesión, un 401 dispara el refresco y el reintento que ya existen.\n   */\n  registrarVista: (id: string) => http.post<{ ok: boolean; registrada: boolean; motivo?: string }>(`${BASE}/products/${id}/view`, {}),\n  /** Vaciar mi historial de productos. */\n  borrarVistos: () =>\n    httpRequest<{ ok: boolean; deleted: number }>(`${BASE}/my/views`, { method: 'DELETE' }),\n};\n\n/** Un producto del historial: la tarjeta del catálogo + lo propio del historial. */\nexport interface LbViewedProduct extends LbProductCard {\n  /** Última vez que abrió la ficha. */\n  viewedAt: string;\n  /** Cuántas veces la ha abierto. */\n  times: number;\n  /** `false` si ya no está a la venta: la rejilla lo dice y no deja comprarlo. */\n  available: boolean;\n}\n\n// ────────────────────────────── pedidos ──────────────────────────────────────\nexport type LbOrderStatus = 'created' | 'confirmed' | 'preparing' | 'in_transit' | 'ready_pickup'\n  | 'delivered' | 'cancelled' | 'disputed'\n  // estados del modelo antiguo (pedidos de publicaciones) para no romper la lista\n  | 'requested' | 'accepted' | 'declined';\n\nexport interface LbOrderItem {\n  id: string;\n  productId: string | null;\n  variantId: string | null;\n  titleSnapshot: string;\n  variantSnapshot: string | null;\n  mediaUrl: string | null;\n  quantity: number;\n  unitPriceXaf: number;\n  lineTotalXaf: number;\n}\n\nexport interface LbOrder {\n  id: string;\n  code: string;\n  status: LbOrderStatus;\n  role: 'buyer' | 'seller' | 'admin';\n  paymentMethod: LbPayMethod;\n  paymentStatus: string;\n  deliveryMode: string;\n  deliveryAddress: { city?: string; zone?: string; reference?: string; lat?: number; lng?: number };\n  deliveryCostXaf: number;\n  subtotalXaf: number;\n  /** TANDA Q: lo que quitó el cupón (0 si no se usó ninguno). */\n  discountXaf: number;\n  /** El código del cupón que se aplicó, si hubo. */\n  couponCode: string | null;\n  totalXaf: number;\n  /** 🔒 Solo llega al comprador (es él quien lo entrega al recibir). */\n  deliveryCode: string | null;\n  note: string | null;\n  items: LbOrderItem[];\n  shop: { id: string; name: string; logoUrl: string | null; ownerId: string } | null;\n  buyer?: { id: string; name: string | null; avatarUrl: string | null };\n  createdAt: string;\n  updatedAt?: string;\n  paidAt?: string | null;\n  /**\n   * TANDA R (R.5b): con qué se dio por cobrado cuando lo marca la tienda a mano (transferencia,\n   * facturación, depósito). El justificante es un enlace a la foto ya subida y la nota lleva la\n   * referencia del recibo. Las dos cosas las ven el comprador y la tienda: el rastro es de los dos.\n   */\n  paymentProofUrl?: string | null;\n  paymentNote?: string | null;\n  /**\n   * TANDA T (T.7): la valoración del pedido, si el comprador ya la escribió. Mueve la nota de la tienda\n   * y de los productos del pedido (media ponderada con los votos que ya había).\n   */\n  review?: { id: string; rating: number; comment: string | null; createdAt: string } | null;\n  /**\n   * TANDA T (T.7b): la reclamación del comprador, con su motivo y su fecha. Antes se abría sin guardar\n   * nada y la tienda no sabía qué se le reclamaba.\n   */\n  disputeReason?: string | null;\n  disputedAt?: string | null;\n  deliveredAt?: string | null;\n}\n\n/**\n * EL DINERO DE UNA TIENDA (panel del comerciante; decisión del dueño, 18/09/2026).\n *\n * `pendienteXaf` es lo que **ya se le puede pagar**; `enEsperaXaf` es el dinero de pedidos entregados\n * hace menos de 7 días, que espera a que venza la ventana de reclamación del comprador.\n */\nexport interface LbSaldoTienda {\n  shop: { id: string; name: string };\n  tiendas: { id: string; name: string }[];\n  pedidos: number;\n  facturadoXaf: number;\n  comisionXaf: number;\n  aPagarTotalXaf: number;\n  pendienteXaf: number;\n  pendientePedidos: number;\n  enEsperaXaf: number;\n  enEsperaPedidos: number;\n  liquidaciones: {\n    id: string;\n    desde: string | null;\n    hasta: string;\n    importeXaf: number;\n    pedidos: number;\n    estado: string;\n    pagadoAt: string;\n    nota: string | null;\n  }[];\n}\n\nexport interface LbOrderCard {\n  id: string;\n  code: string;\n  status: LbOrderStatus;\n  paymentMethod: LbPayMethod | null;\n  paymentStatus: string;\n  deliveryMode: string | null;\n  totalXaf: number;\n  deliveryCostXaf: number;\n  itemsCount: number;\n  title: string;\n  mediaUrl: string | null;\n  shop: { id: string; name: string; logoUrl: string | null } | null;\n  buyer?: { id: string; name: string | null };\n  note: string | null;\n  createdAt: string;\n}\n\nexport interface LbCreateOrderInput {\n  items: { productId: string; variantId?: string | null; quantity: number }[];\n  deliveryMode: string;\n  deliveryAddress?: { city?: string; zone?: string; reference?: string; lat?: number; lng?: number };\n  paymentMethod: LbPayMethod;\n  note?: string;\n  /**\n   * TANDA Q: el código del cupón que se quiere aplicar. **El descuento lo calcula el servidor** al\n   * crear el pedido; aquí solo viaja el código (la app no decide dinero).\n   */\n  couponCode?: string | null;\n  /**\n   * MERCADO (tanda E): conversación donde nació la compra. Si es un **grupo** del que el comprador\n   * es miembro, el servidor publica ahí la tarjeta del pedido con el aviso social\n   * («✅ {nombre} compró {producto}»). El chat con la tienda recibe la tarjeta siempre.\n   */\n  conversationId?: string;\n}\n\nconst ORDERS = `${BASE}/orders`;\nconst MERCHANT = '/lifebook/merchant';\n\nexport const commerceOrdersApi = {\n  /**\n   * Crear pedido. La clave de idempotencia la genera quien llama y es OBLIGATORIA.\n   *\n   * `paymentToken` (parche 97): con pago por MONEDERO el servidor exige un token de pago\n   * (PIN, scope ESCROW_LOCK, importe EXACTO del pedido) en `X-Payment-Token`; se consume\n   * al retener el dinero, así que uno robado no sirve dos veces.\n   */\n  create: (input: LbCreateOrderInput, idemKey: string, paymentToken?: string) =>\n    httpRequest<{ order: LbOrder }>(ORDERS, {\n      method: 'POST',\n      body: input,\n      headers: {\n        'Idempotency-Key': idemKey,\n        ...(paymentToken ? { 'X-Payment-Token': paymentToken } : {}),\n      },\n    }),\n  mine: (side: 'buyer' | 'seller' = 'buyer') =>\n    http.get<{ side: string; orders: LbOrderCard[] }>(`${ORDERS}/mine?side=${side}`),\n  detail: (id: string) => http.get<{ order: LbOrder }>(`${ORDERS}/${id}`),\n  /**\n   * Acción sobre el pedido. `reason` solo hace falta para `dispute`: desde la TANDA T (T.7b) el motivo\n   * es obligatorio (mínimo 10 letras) porque una reclamación sin motivo no se puede atender.\n   */\n  action: (id: string, action: 'accept' | 'decline' | 'prepare' | 'send' | 'ready' | 'deliver' | 'cancel' | 'dispute', reason?: string) =>\n    http.patch<{ order: LbOrder }>(`${ORDERS}/${id}/action`, reason ? { action, reason } : { action }),\n  /** El vendedor confirma la entrega con el código que le da el comprador. */\n  confirmCode: (id: string, code: string) =>\n    http.post<{ order: LbOrder }>(`${ORDERS}/${id}/confirm-code`, { code }),\n  /**\n   * «ESCRIBIR A LA TIENDA»: vuelve a poner la **tarjeta de ESE pedido** en el chat comprador↔tienda y\n   * devuelve la conversación, para abrirla directamente.\n   *\n   * POR QUÉ: la tarjeta se publica al crear el pedido, así que en una conversación con varias compras\n   * el comerciante no sabía de cuál se le hablaba — y en un pedido anterior a la tarjeta no había\n   * ninguna. Lo reportó el dueño.\n   */\n  publicarTarjeta: (id: string) =>\n    http.post<{ ok: boolean; conversationId: string }>(`${ORDERS}/${id}/chat-card`, {}),\n  /**\n   * «MARCAR COBRADO» (TANDA R, R.5b): la tienda cierra el cobro de lo que se paga **por fuera** —\n   * transferencia, facturación, depósito—. Contra entrega y pago en tienda ya se cierran solos al\n   * entregar; esto es para lo demás, que si no se quedaba `pending` para siempre y el vendedor no veía\n   * esa caja. Solo lo puede llamar la tienda del pedido.\n   *\n   * El justificante es opcional (puede no haber recibo); se manda el enlace de la foto ya subida.\n   */\n  marcarCobrado: (id: string, body: { proofUrl?: string | null; note?: string | null }) =>\n    http.post<{ order: LbOrder }>(`${ORDERS}/${id}/mark-paid`, body),\n  /**\n   * «VALORAR» (TANDA T, T.7): el comprador puntúa (1-5) un pedido **entregado**, con un comentario\n   * opcional. Una sola vez por pedido: el servidor corta el segundo intento.\n   *\n   * Es lo que enciende `rating`/`rating_count` de la tienda y de los productos, que existían desde\n   * siempre y **no los escribía nadie**.\n   */\n  valorar: (id: string, body: { rating: number; comment?: string | null }) =>\n    http.post<{ order: LbOrder }>(`${ORDERS}/${id}/review`, body),\n  /**\n   * EL DINERO DE MI TIENDA (panel del comerciante, decisión del dueño 18/09/2026).\n   *\n   * Devuelve lo facturado, la comisión de la plataforma, lo que hay que pagarle a la tienda y sus\n   * liquidaciones. **`pendienteXaf` es lo que ya se le puede pagar** y **`enEsperaXaf` lo que todavía\n   * no**: el dinero de los pedidos entregados hace menos de 7 días, porque el comprador aún puede\n   * reclamar (ventana de reclamación).\n   */\n  saldo: (shopId?: string) =>\n    http.get<LbSaldoTienda>(`/lifebook/commerce/money/balance${shopId ? `?shopId=${shopId}` : ''}`),\n  /**\n   * CERRAR EL COSTE DEL REPARTO (decisión del dueño: que el envío entre en el total).\n   *\n   * Cuando la tienda tiene el envío «a acordar» o «según la distancia», el pedido nace con reparto 0 y\n   * ese dinero se movía por fuera y sin rastro. Con esto la tienda lo cierra **antes de entregar**: entra\n   * en el total y, al entregar, queda anotado en el libro como `a_pagar_reparto`.\n   *\n   * El servidor no deja cambiarlo si el pedido ya está cobrado, entregado, cancelado o en reclamación.\n   */\n  cerrarReparto: (id: string, deliveryCostXaf: number) =>\n    http.patch<{ order: LbOrder }>(`${ORDERS}/${id}/delivery-cost`, { deliveryCostXaf }),\n};\n\n// ────────────────────────────── cupones ──────────────────────────────────────\n/**\n * TANDA Q — EL CUPÓN DE UNA TIENDA.\n *\n * El descuento que se cobra lo decide **siempre el servidor** al crear el pedido. Aquí se calcula\n * solo para ENSEÑARLO antes de pagar, con la misma regla y en una sola función\n * (`descuentoDeCupon`), para que la pantalla y el cobro no puedan decir cosas distintas.\n */\nexport interface LbCupon {\n  id: string;\n  code: string;\n  title: string;\n  /** `percent` (tanto por ciento) o `amount` (XAF). */\n  kind: 'percent' | 'amount' | string;\n  value: number;\n  minSubtotalXaf: number;\n  /** De qué tienda es: un cupón solo vale en los pedidos de SU tienda. */\n  shopId?: string | null;\n  shopName?: string | null;\n  /** `false` = no se puede usar ahora mismo; `reason` dice por qué (lo pone el servidor). */\n  usable?: boolean;\n  reason?: string | null;\n  expiresAt?: string | null;\n}\n\n/**\n * El descuento de un cupón sobre un subtotal. MISMA REGLA QUE EL SERVIDOR:\n *  · `percent` → se redondea HACIA ABAJO (el céntimo no se lo queda nadie por redondeo),\n *  · `amount` → el valor tal cual,\n *  · y nunca más que la compra: un cupón no puede dejar el pedido en negativo.\n */\nexport function descuentoDeCupon(c: LbCupon | null | undefined, subtotalXaf: number): number {\n  if (!c) return 0;\n  const valor = Number(c.value ?? 0) || 0;\n  const bruto = String(c.kind) === 'percent' ? Math.floor((subtotalXaf * valor) / 100) : valor;\n  return Math.max(0, Math.min(bruto, subtotalXaf));\n}\n\n/** ¿Sirve este cupón para ESTA compra? Espejo de lo que comprueba el servidor al cobrar. */\nexport function cuponAplicable(c: LbCupon, subtotalXaf: number): { ok: boolean; motivo: string | null } {\n  if (c.usable === false) return { ok: false, motivo: c.reason ?? 'No se puede usar' };\n  const minimo = Number(c.minSubtotalXaf ?? 0) || 0;\n  if (minimo > 0 && subtotalXaf < minimo) return { ok: false, motivo: `Desde ${minimo} XAF` };\n  if (descuentoDeCupon(c, subtotalXaf) <= 0) return { ok: false, motivo: 'No rebaja nada aquí' };\n  return { ok: true, motivo: null };\n}\n\nexport const cuponesApi = {\n  /** MIS cupones recogidos, con el estado real (el servidor ya dice cuáles sirven y por qué no). */\n  mios: () => http.get<{ items: LbCupon[] }>('/lifebook/commerce/my/coupons'),\n  /** Recoger un cupón por su código: queda en mi cuenta (no en el móvil). */\n  recoger: (code: string) =>\n    http.post<{ ok: boolean; alreadyHad: boolean; coupon: LbCupon & { mensaje?: string } }>(\n      '/lifebook/commerce/coupons/claim', { code },\n    ),\n};\n\n// ─────────────────── aviso de reposición («avísame cuando llegue») ───────────\n/**\n * MERCADO (tanda G) — lo que espera a que vuelva el stock.\n *\n * Se apunta por **variante** cuando el producto tiene opciones: quien espera la «Talla 42» no\n * quiere que le avisen por la «Talla 40». El aviso llega por el chat con la tienda, y solo cuando\n * de verdad hay existencias.\n */\nexport const avisoStockApi = {\n  /** Pedir el aviso. Si ya se puede comprar, el servidor lo dice y NO apunta nada. */\n  vigilar: (productId: string, variantId?: string | null) =>\n    http.post<{ ok: boolean; watching: boolean; available: boolean; mensaje?: string }>(\n      `${BASE}/products/${productId}/interest`,\n      { ...(variantId ? { variantId } : {}) },\n    ),\n  /** Dejar de esperar. */\n  dejarDeVigilar: (productId: string) =>\n    httpRequest<{ ok: boolean; watching: boolean; quitadas: number }>(\n      `${BASE}/products/${productId}/interest`,\n      { method: 'DELETE' },\n    ),\n};\n\nexport { ApiError } from './httpClient';\n\n// ─────────────────── tallas: mis medidas y la recomendación ─────────────────\n/**\n * MERCADO (tanda J) — LAS MEDIDAS DE LA PERSONA.\n *\n * Por categoría **independiente**: `body` (ropa) y `feet` (calzado). Tener una no obliga a tener la\n * otra. **Nunca salen de la cuenta**: el comerciante solo ve la talla elegida, jamás las medidas.\n */\nexport type LbMeasureCategory = 'body' | 'feet';\n\nexport interface LbMeasurements {\n  /**\n   * La categoría ya **no hace falta**: desde la tanda L-ter las medidas son un juego único (altura,\n   * peso y número de calzado juntos) y el servidor lo guarda entero cuando no se manda categoría.\n   * Se sigue aceptando `body`/`feet` por compatibilidad.\n   */\n  category?: LbMeasureCategory;\n  gender?: 'women' | 'men' | null;\n  heightCm?: number | null;\n  weightKg?: number | null;\n  chestCm?: number | null;\n  waistCm?: number | null;\n  hipCm?: number | null;\n  footLengthCm?: number | null;\n  footWidthCm?: number | null;\n}\n\nexport interface LbSizeSuggestion {\n  size: string | null;\n  fit?: 'ajustado' | 'perfecto' | 'holgado';\n  reason: string;\n  /** `false` = esa tienda todavía no ha configurado su tabla: no se inventa ninguna talla. */\n  chartAvailable: boolean;\n  matched?: Record<string, boolean | null>;\n}\n\n/**\n * Lo que devuelve el servidor con MIS medidas: **una por categoría**, y `null` si no hay.\n * (`{ body: {...} | null, feet: {...} | null }`.) No es una lista: tener medidas de cuerpo no obliga\n * a tener las del pie, y por eso cada categoría va por su lado.\n */\nexport interface LbMisMedidas {\n  body: LbMeasurements | null;\n  feet: LbMeasurements | null;\n}\n\nexport const tallasApi = {\n  /** Mis medidas guardadas (solo las ve su dueño). */\n  misMedidas: () => http.get<LbMisMedidas>(`${BASE}/my/measurements`),\n  /**\n   * Guardar MIS medidas. **Se manda sin categoría** y el servidor lo guarda como un juego único\n   * (altura, peso y número de calzado juntos): es lo que pidió el dueño — «van juntos, el guardado\n   * será juntos». Basta con una medida para que se guarde.\n   */\n  guardarMedidas: (input: LbMeasurements) => http.put<LbMisMedidas>(`${BASE}/my/measurements`, input),\n  /** Borrar TODAS mis medidas (o las de una categoría antigua, si se dice cuál). */\n  borrarMedidas: (category?: LbMeasureCategory) =>\n    httpRequest<LbMisMedidas & { ok: boolean; deleted: number }>(\n      `${BASE}/my/measurements${category ? `?category=${category}` : ''}`,\n      { method: 'DELETE' },\n    ),\n  /**\n   * La recomendación de talla contra la tabla DEL PRODUCTO. Si esa tienda no la ha configurado, el\n   * servidor lo dice (`chartAvailable: false`) en vez de inventarse una talla.\n   */\n  sugerir: (productId: string, input: {\n    kind: LbSizeKind; gender: 'women' | 'men';\n    heightCm?: number; weightKg?: number; chestCm?: number; waistCm?: number; hipCm?: number;\n    footLengthCm?: number;\n  }) => http.post<LbSizeSuggestion>(`${BASE}/products/${productId}/size-suggestion`, input),\n};\n\n// ───────────────────────── panel de la tienda ────────────────────────────────\n/**\n * Resumen de «Mi tienda» (Parte 39). **Todo lo calcula el servidor**:\n *  · el «hoy» es el de **Malabo** (no UTC);\n *  · `money.paidTodayXaf` es dinero **entregado y cobrado**, no facturación\n *    pendiente (`money.pendingCodXaf` va aparte, «por cobrar»).\n */\nexport interface LbMerchantDashboard {\n  shop: {\n    id: string;\n    name: string;\n    logoUrl: string | null;\n    coverUrl: string | null;\n    city: string | null;\n    barrio: string | null;\n    region: string | null;\n    isActive: boolean;\n    verificationLevel: LbVerificationLevel;\n    rating: number;\n    ratingCount: number;\n    followersCount: number;\n    createdAt: string;\n  } | null;\n  alerts: {\n    newOrders: number;\n    activeOrders: number;\n    disputed: number;\n    pendingProducts: number;\n    rejectedProducts: number;\n    outOfStock: number;\n    unreadMessages: number;\n  } | null;\n  orders: { today: number; active: number; delivered: number; cancelled: number; total: number } | null;\n  money: { currency: 'XAF'; paidTodayXaf: number; paidMonthXaf: number; pendingCodXaf: number } | null;\n  products: {\n    total: number; active: number; pending: number; draft: number;\n    hidden: number; soldOut: number; rejected: number; outOfStock: number;\n  } | null;\n  /** Las opiniones todavía no existen como tabla propia: se dice, no se inventa. */\n  reviews: { available: boolean; rating: number; ratingCount: number } | null;\n  serverDay: string | null;\n  serverTime: string | null;\n  generatedAt: string;\n}\n\nexport interface LbQuickEditInput {\n  priceXaf?: number | null;\n  stockMode?: LbStockMode;\n  stockQuantity?: number;\n}\n\nexport interface LbQuickEditResult {\n  id: string;\n  title: string;\n  status: LbProductStatus;\n  priceMode: LbPriceMode;\n  priceXaf: number | null;\n  stockMode: LbStockMode;\n  stockQuantity: number;\n  /** El estado no cambió: la publicación sigue viva. */\n  statusUnchanged: boolean;\n}\n\n/**\n * Panel de la tienda. El servidor saca la tienda del **token**: aquí no se manda\n * ningún `shopId`, así que es imposible administrar la tienda de otro.\n */\nexport const commerceMerchantApi = {\n  dashboard: () => http.get<LbMerchantDashboard>(`${MERCHANT}/dashboard`),\n  /** Precio y existencias sin devolver el producto a moderación. */\n  quickEdit: (id: string, input: LbQuickEditInput) =>\n    http.patch<LbQuickEditResult>(`${MERCHANT}/products/${id}/quick`, input),\n};\n\n","/**\n * constants/tallas.ts — LA NUMERACIÓN DEL CALZADO (tanda L-bis).\n *\n * POR QUÉ EXISTE Y POR QUÉ ESTÁ EN UN SOLO SITIO.\n *\n * El que compra zapatos **sabe su número**, no cuántos centímetros mide su pie: preguntarle «largo\n * del pie en cm» es pedirle que se mida con una cinta, y casi nadie lo hace. El que vende, en\n * cambio, escribe su tabla en centímetros (es lo que publican las marcas). Así que hacen falta las\n * dos cosas, y **la misma equivalencia en los dos lados**:\n *   · el comerciante rellena sus tallas típicas (36 … 45) con el largo de pie que les corresponde;\n *   · el comprador puede dar SU NÚMERO y el asistente lo convierte a centímetros para compararlo\n *     con esa tabla.\n * Si cada lado usara su propia tabla, el número 42 podría valer 26 cm en un sitio y 27 en otro, y la\n * recomendación saldría mal. De ahí que la equivalencia viva aquí y solo aquí.\n *\n * OJO CON LA HONESTIDAD: la equivalencia entre la numeración europea (Paris point = 2/3 cm) y el\n * largo del pie es **aproximada** (cada marca talla distinto), y la base guarda centímetros\n * ENTEROS, así que los valores van redondeados a 1 cm. Por eso el asistente enseña siempre\n * «Talla 42 ≈ 26 cm» y deja el largo exacto en su propia ruleta: lo que manda es la tabla de la\n * tienda, no esta tabla.\n */\n\n/** La numeración europea y el largo de pie (cm, entero) que le corresponde. */\nexport const TALLAS_CALZADO: { numero: number; cm: number }[] = [\n  { numero: 34, cm: 21 },\n  { numero: 35, cm: 22 },\n  { numero: 36, cm: 22 },\n  { numero: 37, cm: 23 },\n  { numero: 38, cm: 24 },\n  { numero: 39, cm: 24 },\n  { numero: 40, cm: 25 },\n  { numero: 41, cm: 25 },\n  { numero: 42, cm: 26 },\n  { numero: 43, cm: 26 },\n  { numero: 44, cm: 27 },\n  { numero: 45, cm: 28 },\n  { numero: 46, cm: 29 },\n  { numero: 47, cm: 30 },\n];\n\n/** Los números que se pueden elegir en la ruleta del comprador. */\nexport const NUMEROS_CALZADO: number[] = TALLAS_CALZADO.map((t) => t.numero);\n\n/** El largo de pie (cm) de un número de calzado. */\nexport function cmDeNumero(numero: number): number {\n  return TALLAS_CALZADO.find((t) => t.numero === numero)?.cm ?? 26;\n}\n\n/** El número de calzado que corresponde a un largo de pie (el más cercano). */\nexport function numeroDeCm(cm: number): number {\n  let mejor = TALLAS_CALZADO[0];\n  let dist = Infinity;\n  for (const t of TALLAS_CALZADO) {\n    const d = Math.abs(t.cm - cm);\n    if (d < dist) { dist = d; mejor = t; }\n  }\n  return mejor.numero;\n}\n","/**\n * Enlaces a GRUPOS dentro del perfil (P3).\n *\n * Qué resuelve: el dueño de un grupo quiere poner en su perfil un enlace para que la\n * gente entre al grupo. En Telegram/WeChat eso es un enlace de invitación; aquí el\n * «enlace» es el CÓDIGO del grupo, que ya existía (`GET /lifebook/groups/:id/invite`),\n * pero solo se podía enseñar por WhatsApp copiándolo a mano.\n *\n * Tres cosas, y ninguna toca `api/lifebook.ts` (que el dueño pidió no tocar):\n *   · `misGrupos()`  — mis grupos con MI PAPEL, para el selector del perfil. Solo tiene\n *     sentido ofrecer los que puedo invitar (dueño o administrador): el resto daría 403.\n *   · `codigo(id)`   — el código del grupo, CON SU CADUCIDAD (7 días). El servidor lo\n *     rota al pedirlo si el anterior ya caducó.\n *   · `porCodigo(c)` — la ficha del grupo a partir del código. Es lo que permite pintar\n *     la tarjeta en el perfil Y saber si el enlace sigue vivo: un código caducado\n *     responde 400 «ha caducado», así que la app puede decirlo en vez de mentir.\n */\nimport { http } from './httpClient';\nimport type { LbGroupCard } from './lifebook';\n\n/** Un grupo mío, con lo justo para el selector. */\nexport interface LbMiGrupo {\n  id: string;\n  title: string;\n  photoUrl: string | null;\n  members: number;\n  myRole: 'owner' | 'admin' | 'member';\n}\n\n/** El código de invitación de un grupo. `expiresAt` lo pone el servidor (7 días). */\nexport interface LbCodigoDeGrupo {\n  code: string;\n  title: string | null;\n  link: string;\n  expiresAt: string | null;\n  /** Tope de entradas del enlace. `null` = sin tope. */\n  maxUses: number | null;\n  /** Cuántas veces se ha usado ya. */\n  uses: number;\n  /** Cuántas quedan. `null` = sin tope. */\n  usesLeft: number | null;\n}\n\n/** Lo que el servidor añade a la ficha cuando se llega CON el código. */\nexport interface LbInvitacionDeGrupo {\n  expiresAt: string | null;\n  maxUses: number | null;\n  uses: number;\n  usesLeft: number | null;\n}\n\n/**\n * La ficha del grupo **más** lo que se sabe del enlace por el que se ha llegado. El tipo\n * `LbGroupCard` vive en `api/lifebook.ts` (que no se toca), así que el extra se declara\n * aquí y se compone.\n */\nexport type LbGroupCardConEnlace = LbGroupCard & { invite?: LbInvitacionDeGrupo };\n\n/** Forma cruda de `/lifebook/chat/conversations` (solo lo que usamos aquí). */\ninterface ConversacionCruda {\n  id: string;\n  kind?: string;\n  title?: string;\n  photoUrl?: string | null;\n  members?: number;\n  myRole?: 'owner' | 'admin' | 'member';\n}\n\nexport const gruposEnlacesApi = {\n  /**\n   * Mis grupos, con mi papel. Los grupos vienen de la lista de chats (donde ya\n   * aparecen todos los míos) y NO se piden uno por uno para saber el papel: el\n   * servidor lo manda ahora en cada fila (`myRole`).\n   */\n  misGrupos: async (): Promise<LbMiGrupo[]> => {\n    const todas = await http.get<ConversacionCruda[]>('/lifebook/chat/conversations');\n    return (Array.isArray(todas) ? todas : [])\n      .filter((c) => c && c.kind === 'group')\n      .map((c) => ({\n        id: c.id,\n        title: (c.title ?? '').trim() || 'Grupo',\n        photoUrl: c.photoUrl ?? null,\n        members: Number(c.members ?? 0),\n        myRole: c.myRole ?? 'member',\n      }));\n  },\n\n  /**\n   * El código de invitación (solo dueño y administradores; si no, el servidor da 403).\n   *\n   * `opts` fija el **tope de entradas** y los **días** de vida. Ojo con lo que significa:\n   * pedir un tope (o unos días) **crea un enlace NUEVO** y el anterior deja de funcionar\n   * — es la única forma de que el contador empiece de cero y nadie «recargue» un enlace\n   * ya gastado. Sin `opts` se reutiliza el código vivo (y solo se rota si caducó).\n   *   · `maxUses: null` → sin tope (para todo el mundo, hasta que caduque).\n   */\n  codigo: (groupId: string, opts?: { maxUses?: number | null; days?: number }) => {\n    const q: string[] = [];\n    if (opts?.maxUses !== undefined) q.push(`maxUses=${opts.maxUses === null ? 'null' : opts.maxUses}`);\n    if (opts?.days !== undefined) q.push(`days=${opts.days}`);\n    return http.get<LbCodigoDeGrupo>(`/lifebook/groups/${groupId}/invite${q.length ? `?${q.join('&')}` : ''}`);\n  },\n\n  /**\n   * Unirse (o pedir entrar) a un grupo. Es la MISMA ruta que usa `lifebookGroupsApi.join`,\n   * pero pasando por aquí se puede mandar el `code` del enlace: el tipo de `api/lifebook.ts`\n   * no lo admite y ese fichero no se toca. Mandarlo es lo que gasta una entrada del enlace\n   * y lo que hace que su tope se respete de verdad.\n   */\n  unirse: (groupId: string, input: { answer?: string; note?: string; code?: string } = {}) =>\n    http.post<{ joined: boolean; requested: boolean; state: 'pending' | null; group: LbGroupCard }>(\n      `/lifebook/groups/${groupId}/join`, input,\n    ),\n\n  /**\n   * La ficha de un grupo a partir de su código. Lanza error si el código no existe\n   * (404) o si ya ha CADUCADO (400): quien pinte la tarjeta debe distinguir «no se\n   * pudo leer» de «este enlace ya no sirve».\n   */\n  porCodigo: (code: string) =>\n    http.get<LbGroupCardConEnlace>(`/lifebook/groups/by-code/${encodeURIComponent(code.trim().toUpperCase())}`),\n};\n","/**\n * Catálogo de países (ISO 3166-1 alfa-2 + nombre en español) y ciudades de\n * Guinea Ecuatorial para el selector de ubicación del perfil (P8).\n * África Central destacada al principio; el resto ordenado alfabético.\n */\n\nexport interface CountryOption {\n  code: string;    // ISO alfa-2\n  name: string;    // en español\n}\n\nexport const GQ_CITIES = [\n  'Malabo', 'Bata', 'Mongomo', 'Ebebiyín', 'Evinayong', 'Luba', 'Añisoc',\n  'Mbini', 'Acurenam', 'Nsok', 'San Antonio de Palé', 'Riaba', 'Mikomeseng',\n  'Niefang', 'Cogo', 'Bitica', 'Corisco', 'Moca',\n] as const;\n\n/** Países con Guinea Ecuatorial al frente (por ser la app local). */\nexport const COUNTRIES: CountryOption[] = [\n  { code: 'GQ', name: 'Guinea Ecuatorial' },\n  { code: 'CM', name: 'Camerún' },\n  { code: 'GA', name: 'Gabón' },\n  { code: 'ST', name: 'Santo Tomé y Príncipe' },\n  { code: 'CG', name: 'Congo' },\n  { code: 'CD', name: 'República Democrática del Congo' },\n  { code: 'BJ', name: 'Benín' },\n  { code: 'BF', name: 'Burkina Faso' },\n  { code: 'BI', name: 'Burundi' },\n  { code: 'CV', name: 'Cabo Verde' },\n  { code: 'TD', name: 'Chad' },\n  { code: 'CI', name: 'Costa de Marfil' },\n  { code: 'DJ', name: 'Yibuti' },\n  { code: 'EG', name: 'Egipto' },\n  { code: 'ER', name: 'Eritrea' },\n  { code: 'SZ', name: 'Esuatini' },\n  { code: 'ET', name: 'Etiopía' },\n  { code: 'GH', name: 'Ghana' },\n  { code: 'GN', name: 'Guinea' },\n  { code: 'GW', name: 'Guinea-Bisáu' },\n  { code: 'KE', name: 'Kenia' },\n  { code: 'LS', name: 'Lesoto' },\n  { code: 'LR', name: 'Liberia' },\n  { code: 'LY', name: 'Libia' },\n  { code: 'MG', name: 'Madagascar' },\n  { code: 'MW', name: 'Malaui' },\n  { code: 'ML', name: 'Malí' },\n  { code: 'MA', name: 'Marruecos' },\n  { code: 'MR', name: 'Mauritania' },\n  { code: 'MU', name: 'Mauricio' },\n  { code: 'MZ', name: 'Mozambique' },\n  { code: 'NA', name: 'Namibia' },\n  { code: 'NE', name: 'Níger' },\n  { code: 'NG', name: 'Nigeria' },\n  { code: 'RW', name: 'Ruanda' },\n  { code: 'SN', name: 'Senegal' },\n  { code: 'SC', name: 'Seychelles' },\n  { code: 'SL', name: 'Sierra Leona' },\n  { code: 'SO', name: 'Somalia' },\n  { code: 'ZA', name: 'Sudáfrica' },\n  { code: 'SS', name: 'Sudán del Sur' },\n  { code: 'SD', name: 'Sudán' },\n  { code: 'TZ', name: 'Tanzania' },\n  { code: 'TG', name: 'Togo' },\n  { code: 'TN', name: 'Túnez' },\n  { code: 'UG', name: 'Uganda' },\n  { code: 'ZM', name: 'Zambia' },\n  { code: 'ZW', name: 'Zimbabue' },\n  // Internacional (fuera de África) — corto, ampliable.\n  { code: 'ES', name: 'España' },\n  { code: 'FR', name: 'Francia' },\n  { code: 'PT', name: 'Portugal' },\n  { code: 'US', name: 'Estados Unidos' },\n  { code: 'GB', name: 'Reino Unido' },\n  { code: 'CN', name: 'China' },\n  { code: 'DE', name: 'Alemania' },\n  { code: 'IT', name: 'Italia' },\n  { code: 'BE', name: 'Bélgica' },\n  { code: 'CH', name: 'Suiza' },\n  { code: 'BR', name: 'Brasil' },\n  { code: 'MX', name: 'México' },\n  { code: 'AR', name: 'Argentina' },\n  { code: 'PE', name: 'Perú' },\n  { code: 'CO', name: 'Colombia' },\n  { code: 'CU', name: 'Cuba' },\n  { code: 'DO', name: 'República Dominicana' },\n];\n\n/** Países africanos disponibles en el selector de Buscar Work (sin lista de\n *  ciudades en BD: el usuario escribe la ciudad libremente). */\nexport const AFRICAN_COUNTRY_CODES = COUNTRIES.filter((c) => c.code !== 'GQ').map((c) => c.code);\n","/**\n * Catálogo de PROFESIONES del perfil (P8), alineado con el catálogo de\n * Buscar Work: cada profesión pertenece a una categoría de trabajo\n * (constants/work CATEGORIES) para que el perfil preseleccione ofertas afines.\n */\n\nexport interface ProfessionOption {\n  id: string;\n  label: string;        // cómo se muestra en el perfil\n  categoryId: string;   // categoría de Buscar Work (constants/work)\n}\n\nexport const PROFESSIONS: ProfessionOption[] = [\n  // Transporte (conductor)\n  { id: 'conductor', label: 'Conductor', categoryId: 'transporte' },\n  { id: 'taxista', label: 'Taxista', categoryId: 'transporte' },\n  { id: 'conductor_pesado', label: 'Conductor de vehículo pesado', categoryId: 'transporte' },\n  { id: 'rider', label: 'Repartidor / Rider', categoryId: 'transporte' },\n  { id: 'mecanico', label: 'Mecánico', categoryId: 'transporte' },\n  // Construcción\n  { id: 'albanil', label: 'Albañil', categoryId: 'construccion' },\n  { id: 'electricista', label: 'Electricista', categoryId: 'construccion' },\n  { id: 'fontanero', label: 'Fontanero', categoryId: 'construccion' },\n  { id: 'carpintero', label: 'Carpintero', categoryId: 'construccion' },\n  // Petróleo y Gas\n  { id: 'operador', label: 'Operador de planta', categoryId: 'petroleo' },\n  { id: 'soldador', label: 'Soldador', categoryId: 'petroleo' },\n  // Hostelería\n  { id: 'chef', label: 'Chef / Cocinero', categoryId: 'hosteleria' },\n  { id: 'camarero', label: 'Camarero', categoryId: 'hosteleria' },\n  { id: 'recepcionista', label: 'Recepcionista', categoryId: 'hosteleria' },\n  // Pesca\n  { id: 'pescador', label: 'Pescador', categoryId: 'pesca' },\n  // Comercio\n  { id: 'vendedor', label: 'Vendedor', categoryId: 'comercio' },\n  { id: 'comerciante', label: 'Comerciante', categoryId: 'comercio' },\n  { id: 'dependiente', label: 'Dependiente', categoryId: 'comercio' },\n  // Doméstico\n  { id: 'empleado_hogar', label: 'Empleado del hogar', categoryId: 'domestico' },\n  { id: 'cuidador', label: 'Cuidador / Acompañante', categoryId: 'domestico' },\n  { id: 'jardinero', label: 'Jardinero', categoryId: 'domestico' },\n  // Educación\n  { id: 'profesor', label: 'Profesor', categoryId: 'educacion' },\n  { id: 'maestro', label: 'Maestro', categoryId: 'educacion' },\n  // Sanidad\n  { id: 'enfermero', label: 'Enfermero', categoryId: 'salud' },\n  { id: 'medico', label: 'Médico', categoryId: 'salud' },\n  { id: 'farmaceutico', label: 'Farmacéutico', categoryId: 'salud' },\n  // Administración\n  { id: 'admin', label: 'Administrativo', categoryId: 'admin' },\n  { id: 'contable', label: 'Contable', categoryId: 'admin' },\n  { id: 'secretario', label: 'Secretario', categoryId: 'admin' },\n  { id: 'gerente', label: 'Gerente', categoryId: 'admin' },\n];\n\n/** Resuelve la categoría de Buscar Work de una profesión (para preseleccionar). */\nexport function workCategoryOf(professionLabel: string | null | undefined): string | null {\n  if (!professionLabel) return null;\n  const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').trim();\n  const target = norm(professionLabel);\n  const found = PROFESSIONS.find((p) => norm(p.label) === target);\n  return found?.categoryId ?? null;\n}\n\n/** Categorías de Work agrupadas para el selector del perfil (label agrupado). */\nexport const PROFESSION_GROUPS: Array<{ categoryId: string; categoryLabel: string; items: ProfessionOption[] }> = [\n  { categoryId: 'transporte', categoryLabel: 'Transporte', items: PROFESSIONS.filter((p) => p.categoryId === 'transporte') },\n  { categoryId: 'construccion', categoryLabel: 'Construcción', items: PROFESSIONS.filter((p) => p.categoryId === 'construccion') },\n  { categoryId: 'petroleo', categoryLabel: 'Petróleo y Gas', items: PROFESSIONS.filter((p) => p.categoryId === 'petroleo') },\n  { categoryId: 'hosteleria', categoryLabel: 'Hostelería', items: PROFESSIONS.filter((p) => p.categoryId === 'hosteleria') },\n  { categoryId: 'pesca', categoryLabel: 'Pesca', items: PROFESSIONS.filter((p) => p.categoryId === 'pesca') },\n  { categoryId: 'comercio', categoryLabel: 'Comercio', items: PROFESSIONS.filter((p) => p.categoryId === 'comercio') },\n  { categoryId: 'domestico', categoryLabel: 'Doméstico', items: PROFESSIONS.filter((p) => p.categoryId === 'domestico') },\n  { categoryId: 'educacion', categoryLabel: 'Educación', items: PROFESSIONS.filter((p) => p.categoryId === 'educacion') },\n  { categoryId: 'salud', categoryLabel: 'Sanidad', items: PROFESSIONS.filter((p) => p.categoryId === 'salud') },\n  { categoryId: 'admin', categoryLabel: 'Administración', items: PROFESSIONS.filter((p) => p.categoryId === 'admin') },\n];\n","/**\n * EMERGENCIA (/emergencia) — flujo crítico: llamar a la policía o a una ambulancia.\n *\n * POR QUÉ EXISTE ESTA PANTALLA: el menú de la pantalla de inicio tenía una entrada «Emergencia»\n * que llevaba a `/emergencia`… **y esa pantalla no existía**. Al tocarla, expo-router mostraba\n * «Unmatched Route / Page could not be found». Lo encontró la auditoría de rutas\n * (`pruebas/auditar-rutas.cjs`), no el ojo: por eso ahora esa auditoría es una prueba.\n *\n * Los teléfonos NO se inventan aquí: son los mismos que ya usa la app en\n * `EmergencyModal` (`constants/data.ts` → `EMERGENCY_CONTACTS`), que el conductor tiene en su\n * pantalla 24/7. Tener dos listas distintas de números de emergencia sería peligroso.\n *\n * Diseño deliberadamente sobrio: números grandes, un toque para llamar, y dos salidas claras.\n * En una emergencia nadie lee párrafos.\n */\nimport React from 'react';\nimport { Linking, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Home, Phone, Siren } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { EMERGENCY_CONTACTS } from '../constants/data';\nimport { ir } from '../constants/rutas';\n\nexport default function EmergenciaScreen() {\n  return (\n    <AuthGate>\n      <EmergenciaContent />\n    </AuthGate>\n  );\n}\n\nfunction EmergenciaContent() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  /** Marca el número. Si el teléfono no puede marcar, se dice en vez de no hacer nada. */\n  const llamar = (numero: string, etiqueta: string) => {\n    Linking.openURL(`tel:${numero}`).catch(() => {\n      // Sin marcador disponible se deja el número a la vista (ya está en pantalla en grande).\n      console.warn('[emergencia] no se pudo abrir el marcador para', numero, etiqueta);\n    });\n  };\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => ir.atras()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.danger, fontWeight: '900', fontSize: 17, flex: 1, marginLeft: espaciado.e10 }}>\n          Emergencia\n        </Text>\n      </View>\n\n      <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 24, gap: espaciado.e12 }}>\n        <View style={[styles.aviso, { backgroundColor: alpha(colors.danger, 0.08), borderColor: alpha(colors.danger, 0.35) }]}>\n          <Siren size={22} color={colors.danger} />\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 18, flex: 1 }}>\n            Toca un número para llamar. Estas llamadas funcionan aunque no tengas datos: solo\n            necesitas cobertura de teléfono.\n          </Text>\n        </View>\n\n        {EMERGENCY_CONTACTS.map((c) => (\n          <Pressable\n            key={c.id}\n            onPress={() => llamar(c.number, c.label)}\n            accessibilityRole=\"button\"\n            accessibilityLabel={`Llamar a ${c.label}, ${c.number}`}\n            style={({ pressed }) => [styles.tarjeta, {\n              backgroundColor: colors.card, borderColor: alpha(colors.danger, 0.35), opacity: pressed ? 0.85 : 1,\n            }]}\n          >\n            <View style={[styles.icono, { backgroundColor: alpha(colors.danger, 0.12) }]}>\n              {c.id === 'policia' ? <Siren size={22} color={colors.danger} /> : <Phone size={22} color={colors.danger} />}\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>{c.label}</Text>\n              {c.note ? (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>{c.note}</Text>\n              ) : null}\n              <Text style={{ color: colors.danger, fontSize: 22, fontWeight: '900', marginTop: espaciado.e4 }}>{c.number}</Text>\n            </View>\n            <View style={{ paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e9, borderRadius: radios.full, backgroundColor: colors.danger }}>\n              <Text style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '900' }}>Llamar</Text>\n            </View>\n          </Pressable>\n        ))}\n\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 16 }}>\n          Si no puedes llamar, escribe por el chat a la persona que tengas más cerca. La app no\n          envía tu ubicación automáticamente en una emergencia: dilo tú cuando contesten.\n        </Text>\n\n        <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e4 }}>\n          <Pressable\n            onPress={() => ir.atras()}\n            accessibilityLabel=\"Volver\"\n            style={[styles.salida, { borderColor: colors.border, backgroundColor: colors.surface }]}\n          >\n            <ArrowLeft size={16} color={colors.textPrimary} />\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Volver</Text>\n          </Pressable>\n          <Pressable\n            onPress={() => ir.inicio(true)}\n            accessibilityLabel=\"Ir al inicio\"\n            style={[styles.salida, { borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.1) }]}\n          >\n            <Home size={16} color={colors.primary} />\n            <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body }}>Ir al inicio</Text>\n          </Pressable>\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  aviso: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderWidth: 1, borderRadius: radios.md, padding: espaciado.e12 },\n  tarjeta: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderWidth: 1, borderRadius: 14, padding: espaciado.e12 },\n  icono: { width: 44, height: 44, borderRadius: 22, alignItems: 'center', justifyContent: 'center' },\n  salida: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e12 },\n});\n","/**\n * FoodCheckoutScreen — Confirmar pedido: pickup|delivery, efectivo|Billing,\n * dirección (si delivery), resumen del carrito editable.\n *\n * Auditorías senior (2026-09-02, revisión técnica):\n *  · Fuente única coherente: restaurantId del param con fallback al store, y\n *    guard explícito ANTES de enviar (URL vs store vs líneas del carrito).\n *  · clearCart() DESPUÉS de navegar (no se pierde el pedido si algo falla) +\n *    bandera `sent` (imposible duplicar el pedido con doble tap).\n *  · Carrito editable en el propio checkout (− / + / 🗑️ por línea, tope 99).\n *  · Errores inline (la dirección se valida bajo el campo, sin Alert que\n *    bloquee); FormField con error/maxLength/autoComplete; nota multiline.\n *  · Tarjeta de contexto del restaurante + cerrado (no bloquea; queda en cola).\n *  · SafeArea + KeyboardAvoidingView + a11y (radios, controles, volver).\n *\n * Auditoría de extremo a extremo (2026-09-12, ver docs/AUDITORIA-COMIDA-RAPIDA.md):\n *  · A1 — los precios se muestran DESDE EL SERVIDOR (`detail.menu`), no desde el\n *    snapshot del carrito, y se avisa con nombre y las dos cifras si el dueño los\n *    cambió. El servidor siempre recalcula al crear el pedido; antes la app\n *    mostraba un total y se cobraba otro.\n *  · Platos ya no disponibles: se detectan ANTES de enviar (el servidor los\n *    rechazaba con un error genérico), se nombran y se bloquea el CTA.\n *  · El desglose ya no dice \"Envío 0 XAF · sin recargo\": el reparto es gratis para\n *    el cliente y las comisiones (plataforma + reparto) las paga el RESTAURANTE.\n *  · 起送价: el importe mínimo de reparto se avisa ANTES de confirmar, con el valor que\n *    manda el servidor POR RESTAURANTE (`minOrderXaf`), y bloquea el CTA solo cuando el\n *    envío es a domicilio — recoger en el local no tiene mínimo. Aplicado el 2026-09-12;\n *    ver backend/server-patch/CHECKOUT-fees-y-minimo.md. El servidor sigue siendo la\n *    autoridad: aquí solo se avisa.\n * Ruta: /food-checkout?restaurantId=\n */\n\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\nimport { Alert, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Banknote, Bike, CreditCard, MapPin, Minus, Plus, Store, Trash2, Wallet } from 'lucide-react-native';\nimport { alpha, espaciado, FormField, MasOpciones, PrimaryButton, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { foodApi, FoodRestaurantDetail } from '../api/food';\nimport { walletApi } from '../api/wallet';\nimport { fijarPin } from '../api/settlement';\nimport { PinSheet } from '@egrouteplan/ui-kit';\nimport { getGqPositionIfAllowed } from '../api/locate';\nimport { foodCartCount, foodCartTotal, useFoodStore } from '../state/food';\nimport { formatXAF } from '../utils/formatHelpers';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { InlineError } from '@egrouteplan/ui-kit';\nimport { mensajeDeError } from '../constants/errores';\nimport { ir } from '../constants/rutas';\n\n// Acento del flujo de servicios (naranja), consistente con el resto del\n// marketplace. (Migración al token del theme = ronda de design system aparte.)\nconst ACCENT = brand.primary; // A1: la acción avanza en azul\nconst MAX_QTY = 99;\n\nexport default function FoodCheckoutScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { restaurantId: paramRid } = useLocalSearchParams<{ restaurantId: string }>();\n  const cart = useFoodStore((s) => s.cart);\n  const storeRestaurantId = useFoodStore((s) => s.restaurantId);\n  // Fuente única de verdad: param con fallback al store (auditoría P0).\n  const rid = paramRid || storeRestaurantId || '';\n\n  const [pickup, setPickup] = useState<'pickup' | 'delivery'>('pickup');\n  const [address, setAddress] = useState('');\n  // Ubicación EXACTA del cliente (opcional), como [lng, lat] igual que `LocCoord` en api/locate.ts.\n  // Es opcional a propósito: pedirla obligatoria dejaría sin pedir a quien no quiera dar su posición.\n  // Con ella, el repartidor navega al punto; sin ella, al menos tiene el texto.\n  const [pin, setPin] = useState<[number, number] | null>(null);\n  const [ubicando, setUbicando] = useState(false);\n  const [addressError, setAddressError] = useState<string | null>(null);\n  const [note, setNote] = useState('');\n  const [method, setMethod] = useState<'cash' | 'billing' | 'likebook_wallet'>('cash');\n  /**\n   * PAGO CON EL MONEDERO (parche 98): el cliente confirma con su PIN y el importe queda EN\n   * GARANTÍA; el restaurante cobra en su monedero al entregar el pedido.\n   */\n  const [pinOpen, setPinOpen] = useState(false);\n  const [pinBusy, setPinBusy] = useState(false);\n  const [pinErr, setPinErr] = useState<string | null>(null);\n  const [needSetPin, setNeedSetPin] = useState(false);\n  const [saldoMonedero, setSaldoMonedero] = useState<number | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [sent, setSent] = useState(false);\n  const [submitError, setSubmitError] = useState<string | null>(null);\n  const [detail, setDetail] = useState<FoodRestaurantDetail | null>(null);\n  const busyRef = useRef(false);\n\n  // Líneas del carrito de ESTE restaurante (nunca se envía otro pedido).\n  const lines = useMemo(() => (rid ? cart.filter((c) => c.restaurantId === rid) : []), [cart, rid]);\n  const count = useMemo(() => foodCartCount(lines), [lines]);\n\n  // ── PRECIOS DEL SERVIDOR, no los del carrito (A1 de la auditoría) ──────────────\n  // El carrito guarda el precio del momento en que se añadió (snapshot local en\n  // AsyncStorage, y puede sobrevivir días). Si el dueño cambió el precio después, el\n  // cliente veía un total y se le cobraba otro: el servidor SIEMPRE recalcula desde la\n  // BD al crear el pedido (nunca acepta precios del cliente), así que la app tiene que\n  // mostrar lo que el servidor va a cobrar, no lo que el carrito recuerda.\n  //\n  // No hace falta una petición extra: `detail.menu` ya viene en la misma llamada que el\n  // contexto del restaurante. Mientras `detail` no llegue (o si falla, que no es\n  // crítico) se usa el precio del carrito, que es lo que se mostraba antes.\n  const serverPrices = useMemo(() => {\n    const m = new Map<string, number>();\n    for (const it of detail?.menu ?? []) m.set(it.id, it.priceXaf);\n    return m;\n  }, [detail]);\n\n  const pricedLines = useMemo(\n    () => lines.map((c) => {\n      const p = serverPrices.get(c.itemId);\n      return typeof p === 'number' ? { ...c, priceXaf: p } : c;\n    }),\n    [lines, serverPrices],\n  );\n\n  const total = useMemo(() => foodCartTotal(pricedLines), [pricedLines]);\n\n  // Qué cambió respecto al carrito, con nombre y las dos cifras: un aviso genérico\n  // («los precios han cambiado») no le dice al cliente qué plato ni cuánto.\n  const priceChanges = useMemo(() => {\n    const out: Array<{ name: string; antes: number; ahora: number }> = [];\n    for (const c of lines) {\n      const p = serverPrices.get(c.itemId);\n      if (typeof p === 'number' && p !== c.priceXaf) out.push({ name: c.name, antes: c.priceXaf, ahora: p });\n    }\n    return out;\n  }, [lines, serverPrices]);\n\n  // Platos del carrito que el restaurante YA NO sirve (desactivado o borrado). El\n  // servidor los rechaza al enviar con un error genérico; mejor decirlo antes y con el\n  // nombre del plato. Solo se calcula cuando `detail` ya cargó, para no marcar como\n  // «no disponible» algo que simplemente no ha llegado todavía por la red.\n  const missing = useMemo(\n    () => (detail === null ? [] : lines.filter((c) => !serverPrices.has(c.itemId))),\n    [detail, lines, serverPrices],\n  );\n\n  // 起送价: importe mínimo para pedir a DOMICILIO, POR RESTAURANTE (lo manda el servidor en\n  // `minOrderXaf`; no se escribe a mano aquí, que es justo la desincronización que se está arreglando).\n  // Y solo cuenta para reparto: recoger en el local no tiene mínimo. Esa distinción la garantiza el\n  // servidor, así que la app la respeta en vez de inventarse su propia regla.\n  const minimoReparto = typeof detail?.minOrderXaf === 'number' && detail.minOrderXaf > 0 ? detail.minOrderXaf : null;\n  const bloqueadoPorMinimo = pickup === 'delivery' && minimoReparto !== null && total < minimoReparto;\n\n  // Contexto del restaurante (público): nombre, ciudad, dirección, horario.\n  useEffect(() => {\n    if (!rid) return;\n    let cancelled = false;\n    foodApi.restaurant(rid)\n      .then((d) => { if (!cancelled) setDetail(d); })\n      .catch(() => undefined); // contexto no crítico\n    return () => { cancelled = true; };\n  }, [rid]);\n\n  // Estado de pantalla cuando no hay líneas confirmables.\n  const empty: { emoji: string; title: string; sub: string } | null = useMemo(() => {\n    if (lines.length > 0) return null;\n    if (!rid) return { emoji: '🍽️', title: 'Pedido incompleto', sub: 'Falta el restaurante. Vuelve al menú y vuelve a confirmar.' };\n    if (cart.length > 0) return { emoji: '🛒', title: 'Carrito de otro restaurante', sub: 'Tu carrito tiene ítems de otro restaurante. Vuelve al menú correcto.' };\n    return { emoji: '🛒', title: 'Tu carrito está vacío', sub: 'Añade platos desde el menú del restaurante y vuelve a confirmar.' };\n  }, [lines.length, rid, cart.length]);\n\n  const store = useFoodStore;\n\n  const confirm = async (paymentToken?: string) => {\n    if (!rid || lines.length === 0 || busyRef.current || sent) return;\n    // Monedero: primero el PIN (el dinero se retiene antes de crear el pedido).\n    if (method === 'likebook_wallet' && !paymentToken) {\n      setPinErr(null); setNeedSetPin(false); setPinOpen(true);\n      return;\n    }\n    // No enviar un pedido que el servidor va a rechazar por platos inexistentes: el\n    // error volvería genérico y el cliente no sabría qué plato quitar. Se bloquea aquí\n    // con el nombre, que es la información útil.\n    if (missing.length > 0) {\n      setSubmitError(`Quita del pedido ${missing.length === 1 ? 'el plato que ya no está disponible' : 'los platos que ya no están disponibles'}: ${missing.map((m) => m.name).join(', ')}.`);\n      return;\n    }\n    // Guard de coherencia (URL vs store) antes de enviar — auditoría P0.\n    if (storeRestaurantId && storeRestaurantId !== rid) {\n      Alert.alert('Error', 'Este pedido no corresponde al restaurante que tienes abierto.');\n      return;\n    }\n    if (cart.some((c) => c.restaurantId && c.restaurantId !== rid)) {\n      Alert.alert('Error', 'Hay ítems de otro restaurante en el carrito.');\n      return;\n    }\n    // Validación inline (sin Alert bloqueante) para la dirección.\n    if (pickup === 'delivery' && !address.trim()) {\n      setAddressError('Indica la dirección de entrega.');\n      return;\n    }\n    busyRef.current = true;\n    setBusy(true);\n    setSubmitError(null);\n    try {\n      const r = await foodApi.createOrder({\n        restaurantId: rid,\n        items: lines.map((c) => ({ itemId: c.itemId, qty: c.qty })),\n        paymentMethod: method,\n        pickupType: pickup,\n        deliveryAddress: pickup === 'delivery' ? address.trim() : undefined,\n        // El pin viaja solo si es a domicilio y el cliente lo dio: `LocCoord` es [lng, lat] y la API\n        // espera lat/lng por separado (el servidor valida las dos y que caigan dentro del país).\n        deliveryLat: pickup === 'delivery' && pin ? pin[1] : undefined,\n        deliveryLng: pickup === 'delivery' && pin ? pin[0] : undefined,\n        note: note.trim() || undefined,\n      }, paymentToken);\n      setSent(true); // el pedido existe: no permitir reenviar aunque falle la navegación\n      if (r.billingOrderId) {\n        router.replace({ pathname: '/billing-checkout', params: { orderId: r.billingOrderId } } as any);\n      } else {\n        router.replace('/food-orders' as any);\n      }\n      store.getState().clearCart(); // DESPUÉS de navegar (auditoría P0)\n    } catch (e) {\n      const code = (e as { code?: string })?.code;\n      // PIN incorrecto o aún sin PIN: la hoja lo explica y permite crearlo en el mismo paso.\n      if (method === 'likebook_wallet' && (code === 'PIN_INVALID' || code === 'PIN_LOCKED' || code === 'PAYMENT_TOKEN_INVALID')) {\n        if (!needSetPin) {\n          setNeedSetPin(true);\n          setPinErr('Si es tu primer pago: escribe tu contraseña y elige tu PIN de 6 dígitos.');\n        } else {\n          setPinErr(e instanceof Error ? e.message : 'No se pudo confirmar el pago');\n        }\n        setPinOpen(true);\n      } else {\n        setSubmitError(mensajeDeError(e, 'No se pudo enviar el pedido. Revisa tu conexión e inténtalo de nuevo.'));\n      }\n    } finally {\n      busyRef.current = false;\n      setBusy(false);\n    }\n  };\n\n  /** PIN confirmado → token del importe exacto → pedido. */\n  const pagarConMonedero = async (pin: string, password?: string) => {\n    if (pinBusy) return;\n    setPinBusy(true); setPinErr(null);\n    try {\n      if (needSetPin) await fijarPin(pin, password);\n      const token = await walletApi.paymentToken(pin, 'ESCROW_LOCK', total);\n      setPinOpen(false);\n      await confirm(token);\n    } catch (e) {\n      setPinErr(e instanceof Error ? e.message : 'No se pudo confirmar el pago');\n    } finally {\n      setPinBusy(false);\n    }\n  };\n\n  // Saldo del monedero al elegir esa forma de pago: saber si llega ANTES de intentarlo.\n  useEffect(() => {\n    if (method !== 'likebook_wallet') { setSaldoMonedero(null); return; }\n    let vivo = true;\n    void walletApi.getWallet()\n      .then((w) => { if (vivo) setSaldoMonedero(Number(w.balanceAvailable ?? 0)); })\n      .catch(() => { if (vivo) setSaldoMonedero(null); });\n    return () => { vivo = false; };\n  }, [method]);\n\n  const s = styles(colors);\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Cabecera del kit desde el 24/09/2026. */}\n      <ScreenHeader titulo=\"Confirmar pedido\" alVolver={() => ir.atras()} />\n\n      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n        <ScrollView\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 + insets.bottom }}\n          showsVerticalScrollIndicator={false}\n          keyboardShouldPersistTaps=\"handled\"\n        >\n          {empty ? (\n            <View style={s_center.wrap}>\n              <Text style={{ fontSize: 40, marginBottom: espaciado.e10 }}>{empty.emoji}</Text>\n              <Text style={[s_center.title, { color: colors.textPrimary }]}>{empty.title}</Text>\n              <Text style={[s_center.sub, { color: colors.textSecondary }]}>{empty.sub}</Text>\n              <Pressable onPress={() => ir.atras()} accessibilityRole=\"button\" style={s_center.btnPrimary}>\n                <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Volver</Text>\n              </Pressable>\n            </View>\n          ) : (\n            <>\n              {/* Contexto del restaurante */}\n              {detail && (\n                <View style={[s.restCard, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                  <Text style={{ fontSize: 14.5, fontWeight: '800', color: colors.textPrimary }}>{detail.businessName}</Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e2 }}>\n                    {detail.cuisineLabel ?? 'Restaurante'} · {detail.city}\n                  </Text>\n                  {detail.hours ? <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e2 }}>🕐 {detail.hours}</Text> : null}\n                  {detail.address ? (\n                    <Text numberOfLines={2} style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e2 }}>📍 {detail.address}</Text>\n                  ) : null}\n                  {detail.isOpen === false && (\n                    <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.danger, marginTop: espaciado.e4 }}>\n                      Cerrado ahora · tu pedido quedará en cola y lo confirmarán cuando abra.\n                    </Text>\n                  )}\n                </View>\n              )}\n\n              {/* Resumen editable. Se pinta con `pricedLines`, no con `lines`: la línea\n                  muestra el precio que el servidor va a cobrar. */}\n              <Text style={s.label}>Tu pedido · {count} ítem{count === 1 ? '' : 's'}</Text>\n\n              {missing.length > 0 && (\n                <View style={[s.warnBox, { backgroundColor: alpha(colors.danger, 0.08), borderColor: alpha(colors.danger, 0.3) }]}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.danger }}>\n                    {missing.length === 1 ? 'Un plato ya no está disponible' : `${missing.length} platos ya no están disponibles`}\n                  </Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e3, lineHeight: 15 }}>\n                    {missing.map((m) => m.name).join(', ')} · quítalo{missing.length === 1 ? '' : 's'} del pedido para poder confirmar.\n                  </Text>\n                </View>\n              )}\n\n              {priceChanges.length > 0 && (\n                <View style={[s.warnBox, { backgroundColor: alpha(brand.warning, 0.1), borderColor: alpha(brand.warning, 0.35) }]}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: brand.warningText }}>\n                    El restaurante cambió algún precio\n                  </Text>\n                  {priceChanges.map((c) => (\n                    <Text key={c.name} style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e2, lineHeight: 15 }}>\n                      {c.name}: {formatXAF(c.antes)} → <Text style={{ fontWeight: '800', color: brand.warningText }}>{formatXAF(c.ahora)}</Text>\n                    </Text>\n                  ))}\n                  <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e3 }}>\n                    Los importes de abajo ya están actualizados.\n                  </Text>\n                </View>\n              )}\n\n              {/* 起送价: el mínimo se avisa ANTES de confirmar. Antes el cliente elegía reparto,\n                  pulsaba «Confirmar» y se enteraba del mínimo al final del flujo, cuando ya había\n                  decidido. Solo aparece con reparto y con cifra del servidor. */}\n              {bloqueadoPorMinimo && minimoReparto !== null && (\n                <View style={[s.warnBox, { backgroundColor: alpha(colors.danger, 0.08), borderColor: alpha(colors.danger, 0.3) }]}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.danger }}>\n                    Para reparto el pedido mínimo es {formatXAF(minimoReparto)}\n                  </Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e3, lineHeight: 15 }}>\n                    Llevas {formatXAF(total)}. Añade algo más o cambia a recoger en el local.\n                  </Text>\n                </View>\n              )}\n\n              {pricedLines.map((c) => (\n                <CartLineRow\n                  key={c.itemId}\n                  name={c.name}\n                  price={c.priceXaf}\n                  qty={c.qty}\n                  lineTotal={c.priceXaf * c.qty}\n                  onDec={() => store.getState().setQty(c.itemId, c.qty - 1)}\n                  onInc={() => store.getState().setQty(c.itemId, c.qty + 1)}\n                  onRemove={() => store.getState().removeFromCart(c.itemId)}\n                />\n              ))}\n\n              {/* Desglose de costos */}\n              <View style={s.breakdown}>\n                <View style={s.brRow}>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Subtotal</Text>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>{formatXAF(total)}</Text>\n                </View>\n                <View style={s.brRow}>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Envío</Text>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.primary }}>Gratis</Text>\n                </View>\n                <View style={[s.brRow, { marginTop: espaciado.e4 }]}>\n                  <Text style={{ fontSize: 15, fontWeight: '800', color: colors.textPrimary }}>Total</Text>\n                  <Text style={{ fontSize: tipografia.title, fontWeight: '900', color: ACCENT }}>{formatXAF(total)}</Text>\n                </View>\n                {/* Honestidad sobre las comisiones: existen y las paga el restaurante. Se dice\n                    aquí porque el dueño decidió que la comisión se muestre a ambos, y el\n                    desglose con cifras llega en la pantalla del pedido (food-orders). El importe\n                    exacto no se puede calcular en la app: la configuración es POR RESTAURANTE\n                    (`wallet.food_commission_config`) y `mapRestaurant` no la devuelve — ver el\n                    parche `CHECKOUT-fees-y-minimo.md`. Hasta que se exponga, se explica sin cifras\n                    en vez de inventar un cálculo que podría no coincidir con el del servidor. */}\n                <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e4, lineHeight: 14 }}>\n                  El reparto es gratis para ti. Las comisiones de la plataforma y del reparto las\n                  paga el restaurante: van incluidas en estos precios, no se te suman.\n                </Text>\n              </View>\n\n              {/* Recogida o reparto */}\n              <Text style={s.label}>Entrega</Text>\n              <Pressable onPress={() => setPickup('pickup')} accessibilityRole=\"radio\" accessibilityState={{ checked: pickup === 'pickup' }}\n                accessibilityLabel=\"Recoger en el local\"\n                style={[s.modeCard, { borderColor: pickup === 'pickup' ? ACCENT : colors.border, borderWidth: pickup === 'pickup' ? 2 : 1 }]}>\n                <Store size={18} color={ACCENT} />\n                <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>Recoger en el local</Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Pasa a recoger tu pedido.</Text>\n                </View>\n              </Pressable>\n              <Pressable onPress={() => setPickup('delivery')} accessibilityRole=\"radio\" accessibilityState={{ checked: pickup === 'delivery' }}\n                accessibilityLabel=\"A domicilio\"\n                style={[s.modeCard, { borderColor: pickup === 'delivery' ? ACCENT : colors.border, borderWidth: pickup === 'delivery' ? 2 : 1, marginTop: espaciado.e8 }]}>\n                <Bike size={18} color={ACCENT} />\n                <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>A domicilio</Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Reparto a tu dirección.</Text>\n                </View>\n              </Pressable>\n\n              {pickup === 'delivery' && (\n                <>\n                  <Text style={s.label}>Dirección de entrega *</Text>\n                  <FormField\n                    value={address}\n                    onChangeText={(t) => { setAddress(t); if (addressError) setAddressError(null); }}\n                    placeholder=\"Ej: Zona Industrial, Malabo II\"\n                    error={addressError ?? undefined}\n                    maxLength={300}\n                    autoComplete=\"street-address\"\n                  />\n\n                  {/* ── UBICACIÓN EXACTA (opcional) ─────────────────────────────────\n                      «Aeropuerto» no se puede navegar: el repartidor necesita un punto. Este botón\n                      toma la posición del cliente y la manda CON el pedido. Es opcional —quien no\n                      quiera dar su posición sigue pidiendo con la dirección escrita— pero cuando\n                      está, el repartidor abre el mapa en el punto exacto. */}\n                  <Pressable\n                    onPress={async () => {\n                      setUbicando(true);\n                      try {\n                        const c = await getGqPositionIfAllowed(6000);\n                        if (!c) {\n                          Alert.alert('Ubicación', 'No pudimos obtener tu ubicación. Puedes pedir igualmente con la dirección escrita.');\n                          return;\n                        }\n                        setPin(c);\n                      } finally { setUbicando(false); }\n                    }}\n                    disabled={ubicando}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Añadir mi ubicación exacta para el reparto\"\n                    style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e8, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, borderRadius: 10, borderWidth: 1, borderColor: pin ? alpha(colors.success, 0.5) : colors.border, backgroundColor: pin ? alpha(colors.success, 0.08) : 'transparent' }}\n                  >\n                    <MapPin size={15} color={pin ? colors.success : colors.textPrimary} />\n                    <Text style={{ flex: 1, fontSize: tipografia.body, fontWeight: '700', color: pin ? colors.success : colors.textPrimary }}>\n                      {ubicando ? 'Buscando tu ubicación…' : pin ? '✓ Ubicación exacta añadida al pedido' : 'Añadir mi ubicación exacta (ayuda al repartidor a llegar)'}\n                    </Text>\n                    {pin ? (\n                      <Pressable onPress={() => setPin(null)} accessibilityRole=\"button\" accessibilityLabel=\"Quitar la ubicación exacta\" hitSlop={8}>\n                        <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Quitar</Text>\n                      </Pressable>\n                    ) : null}\n                  </Pressable>\n                  {pin ? (\n                    <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e4 }}>\n                      Se envía solo con este pedido y el repartidor lo usa para llegar.\n                    </Text>\n                  ) : null}\n                </>\n              )}\n              {/*\n                Plegado (Fase 2 · punto 25): la nota es lo ÚNICO accesorio de esta pantalla. La\n                dirección y el método de pago se quedan a la vista — sin ellos no hay pedido —.\n                La etiqueta «Nota (opcional)» desaparece porque el enlace ya dice qué se añade.\n              */}\n              <MasOpciones\n                abrir=\"Añadir una nota para el restaurante\"\n                cerrar=\"Ocultar la nota\"\n                abiertoInicial={note.trim() !== ''}\n              >\n                <TextInput\n                  value={note}\n                  onChangeText={setNote}\n                  placeholder=\"Ej: sin cebolla, llamar al llegar…\"\n                  placeholderTextColor={colors.textSecondary}\n                  multiline\n                  maxLength={500}\n                  style={[s.area, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n                />\n              </MasOpciones>\n\n              {/* Método de pago */}\n              <Text style={s.label}>Método de pago</Text>\n              <Pressable onPress={() => setMethod('cash')} accessibilityRole=\"radio\" accessibilityState={{ checked: method === 'cash' }}\n                accessibilityLabel=\"Efectivo al recoger o recibir\"\n                style={[s.modeCard, { borderColor: method === 'cash' ? ACCENT : colors.border, borderWidth: method === 'cash' ? 2 : 1 }]}>\n                <Banknote size={18} color={ACCENT} />\n                <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>Efectivo al recoger/recibir</Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Paga al recoger o recibir · EG no retiene el dinero.</Text>\n                </View>\n              </Pressable>\n              <Pressable onPress={() => setMethod('billing')} accessibilityRole=\"radio\" accessibilityState={{ checked: method === 'billing' }}\n                accessibilityLabel=\"Pago Billing por transferencia\"\n                style={[s.modeCard, { borderColor: method === 'billing' ? ACCENT : colors.border, borderWidth: method === 'billing' ? 2 : 1, marginTop: espaciado.e8 }]}>\n                <CreditCard size={18} color={ACCENT} />\n                <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>Pago Billing (transferencia)</Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>Orden de pago con comprobante · aprobación 2–24 h.</Text>\n                </View>\n              </Pressable>\n              {/* PAGO CON EL MONEDERO (parche 98): retiene el importe y el restaurante cobra al entregar. */}\n              <Pressable onPress={() => setMethod('likebook_wallet')} accessibilityRole=\"radio\" accessibilityState={{ checked: method === 'likebook_wallet' }}\n                accessibilityLabel=\"Pagar con el monedero\"\n                style={[s.modeCard, { borderColor: method === 'likebook_wallet' ? ACCENT : colors.border, borderWidth: method === 'likebook_wallet' ? 2 : 1, marginTop: espaciado.e8 }]}>\n                <Wallet size={18} color={ACCENT} />\n                <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>Monedero</Text>\n                  <Text style={{ fontSize: tipografia.body, color: colors.textSecondary }}>\n                    Confirmas con tu PIN y el importe queda en garantía hasta que recibas el pedido.\n                  </Text>\n                  {method === 'likebook_wallet' && saldoMonedero !== null ? (\n                    <Text style={{ fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e3, color: saldoMonedero >= total ? brand.success : brand.dangerPressed }}>\n                      Tienes {formatXAF(saldoMonedero)}{saldoMonedero >= total ? '' : ' · no llega'}\n                    </Text>\n                  ) : null}\n                </View>\n              </Pressable>\n              {method === 'billing' && (\n                <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e6, lineHeight: 15 }}>\n                  Tras confirmar crearás una orden de pago y subirás el comprobante. El restaurante prepara tu pedido\n                  cuando el pago esté aprobado (revisión 2–24 h).\n                </Text>\n              )}\n\n              {/* Error persistente */}\n              {submitError ? (\n                <View style={{ marginBottom: espaciado.e12 }}>\n                  {/* Error EN LA PANTALLA, no encima: el usuario no pierde lo que estaba haciendo. */}\n                  <InlineError mensaje={submitError} />\n                </View>\n              ) : null}\n\n              {/* CTA con TOTAL visible antes de confirmar */}\n              <View style={{ marginTop: espaciado.e20 }}>\n                <PrimaryButton\n                  title={busy ? 'Enviando pedido…' : `Confirmar pedido · ${formatXAF(total)}`}\n                  /* Sin envolver: el botón pasa el EVENTO como primer argumento y se colaría\n                     como token de pago. Con monedero, la hoja del PIN pide el token. */\n                  onPress={() => void confirm()}\n                  disabled={busy || sent || lines.length === 0 || missing.length > 0 || bloqueadoPorMinimo}\n                />\n              </View>\n            </>\n          )}\n        </ScrollView>\n      </KeyboardAvoidingView>\n\n      <PinSheet\n        visible={pinOpen}\n        title={`Pagar ${formatXAF(total)} con el monedero`}\n        subtitle={needSetPin\n          ? 'Primer pago: escribe tu contraseña y elige un PIN de 6 dígitos.'\n          : 'El importe queda en garantía hasta que recibas el pedido.'}\n        busy={pinBusy}\n        error={pinErr}\n        needPassword={needSetPin}\n        confirmLabel={needSetPin ? 'Guardar PIN y pagar' : 'Confirmar pago'}\n        onClose={() => setPinOpen(false)}\n        onConfirm={(pin, pwd) => void pagarConMonedero(pin, pwd)}\n      />\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\nfunction CartLineRow({ name, price, qty, lineTotal, onDec, onInc, onRemove }: {\n  name: string; price: number; qty: number; lineTotal: number;\n  onDec: () => void; onInc: () => void; onRemove: () => void;\n}) {\n  const { colors } = useTheme();\n  const atMax = qty >= MAX_QTY;\n  return (\n    <View style={[s_line.card, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n      <View style={{ flex: 1 }}>\n        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e8 }}>\n          <Text numberOfLines={2} style={{ flex: 1, fontSize: tipografia.body, color: colors.textPrimary }}>{name}</Text>\n          <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>{formatXAF(lineTotal)}</Text>\n        </View>\n        <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: 1 }}>{formatXAF(price)} c/u</Text>\n        <View style={s_line.controls}>\n          <Pressable onPress={onRemove} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Quitar ${name} del pedido`}\n            style={[s_line.iconBtn, { backgroundColor: alpha(colors.danger, 0.1) }]}>\n            <Trash2 size={14} color={colors.danger} />\n          </Pressable>\n          <Pressable onPress={onDec} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Reducir cantidad de ${name}`}\n            style={[s_line.stepBtn, { backgroundColor: colors.border }]}>\n            <Minus size={13} color={colors.textPrimary} strokeWidth={3} />\n          </Pressable>\n          <Text style={[s_line.qty, { color: colors.textPrimary }]}>{qty}</Text>\n          <Pressable onPress={onInc} disabled={atMax} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Aumentar cantidad de ${name}`}\n            style={[s_line.stepBtn, { backgroundColor: ACCENT, opacity: atMax ? 0.4 : 1 }]}>\n            <Plus size={13} color={brand.white} strokeWidth={3} />\n          </Pressable>\n        </View>\n      </View>\n    </View>\n  );\n}\n\nconst s_line = StyleSheet.create({\n  card: { borderRadius: radios.md, borderWidth: 1, padding: espaciado.e10, marginBottom: espaciado.e6 },\n  controls: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e8 },\n  iconBtn: { width: 28, height: 28, borderRadius: radios.sm, alignItems: 'center', justifyContent: 'center' },\n  stepBtn: { width: 28, height: 28, borderRadius: radios.sm, alignItems: 'center', justifyContent: 'center' },\n  qty: { fontSize: tipografia.body, fontWeight: '800', minWidth: 16, textAlign: 'center' },\n});\n\nconst s_center = StyleSheet.create({\n  wrap: { alignItems: 'center', paddingTop: 56, paddingHorizontal: espaciado.e28 },\n  title: { fontSize: 15, fontWeight: '800', textAlign: 'center' },\n  sub: { fontSize: tipografia.body, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 },\n  btnPrimary: { marginTop: espaciado.e18, backgroundColor: brand.secondary, paddingHorizontal: espaciado.e28, paddingVertical: espaciado.e11, borderRadius: 22 },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  label: { fontSize: tipografia.body, fontWeight: '700', color: c.textPrimary, marginTop: espaciado.e14, marginBottom: espaciado.e6 },\n  restCard: { borderRadius: radios.md, borderWidth: 1, padding: espaciado.e12, marginBottom: espaciado.e4 },\n  breakdown: { backgroundColor: c.surface, borderRadius: radios.md, borderWidth: 1, borderColor: c.border, padding: espaciado.e12, marginTop: espaciado.e10 },\n  brRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: espaciado.e2 },\n  modeCard: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, padding: espaciado.e14, backgroundColor: c.surface },\n  warnBox: { borderRadius: 10, borderWidth: 1, padding: espaciado.e10, marginBottom: espaciado.e10 },\n  area: { minHeight: 64, borderRadius: 14, borderWidth: 1, padding: espaciado.e12, fontSize: tipografia.body, textAlignVertical: 'top' },\n  errorBox: { borderRadius: 10, padding: espaciado.e10, marginTop: espaciado.e14 },\n});\n","/**\n * Cliente del servicio Comida Rápida (pedidos a restaurantes) — backend unificado.\n * Base ABSOLUTA: /api/food/*. Patrón Ecomerse: restaurantes con requisitos\n * (KYC + datos negocio + aprobación admin), menú moderado, pedidos cash|billing\n * (pickup|delivery), reviews y reportes.\n */\n\nimport { http, httpRequest } from './httpClient';\n\nimport { API_HOST } from './config';\nexport const FOOD_API = `${API_HOST}/api`;\nconst f = (p: string) => `${FOOD_API}${p}`;\n\nexport interface FoodCuisine { id: string; code: string; label: string; icon: string | null; }\n\n/**\n * Nivel de picante de un plato (migración 041). Espejo del CHECK\n * `food_menu_items_spice_check`. `null` = el dueño no lo declaró → no se muestra.\n */\nexport type SpiceLevel = 'none' | 'mild' | 'medium' | 'hot' | 'extra_hot';\n\n/** Etiquetas en español para UI (orden = de menos a más picante). */\nexport const SPICE_LABEL: Record<SpiceLevel, string> = {\n  none: 'Sin picante',\n  mild: 'Poco picante',\n  medium: 'Picante medio',\n  hot: 'Picante',\n  extra_hot: 'Muy picante',\n};\n\n/** Icono por nivel (null no tiene: el campo no se declara). */\nexport const SPICE_ICON: Record<SpiceLevel, string> = {\n  none: '🌿',\n  mild: '🌶️',\n  medium: '🌶️🌶️',\n  hot: '🌶️🌶️🌶️',\n  extra_hot: '🔥',\n};\n\n/** Límites de validación (espejo de la migración 041 y del DTO del backend). */\nexport const PREP_MINUTES_MAX = 240;\nexport const SIDES_MAX = 20;\nexport const INGREDIENTS_MAX = 1000;\nexport const PORTION_SIZE_MAX = 40;\n\n/** Campos opcionales del detalle de plato (041). Todos pueden venir null. */\nexport interface FoodItemDetails {\n  /** Lista libre de ingredientes, ej: \"pollo, arroz, salsa de cacahuete\". */\n  ingredients: string | null;\n  spiceLevel: SpiceLevel | null;\n  /** Tamaño/ración libre, ej: \"2 piezas\", \"400 g\", \"Grande\". */\n  portionSize: string | null;\n  drinkIncluded: boolean;\n  /** Acompañantes, ej: [\"arroz\", \"plátano frito\"]. */\n  sides: string[];\n  /** Minutos de preparación; null = no publicado (no se muestra ETA). */\n  prepMinutes: number | null;\n}\n\nexport interface FoodRestaurant {\n  id: string; businessName: string; cuisineId: string | null; cuisineLabel: string | null; cuisineIcon: string | null;\n  description: string | null; city: string; address: string | null; phoneContact: string | null;\n  photoKey: string | null; photoUrl: string | null; isOpen: boolean | null;\n  hours: string | null; deliveryKm: number;\n  status: string; rejectionReason: string | null; ratingAvg: number; ratingCount: number;\n  approvedAt: string | null; createdAt: string;\n  /** 起送价: importe mínimo para pedir a DOMICILIO en este restaurante. Recoger en el local no tiene\n   *  mínimo. Es un valor POR RESTAURANTE que se cambia sin desplegar código, así que NO se escribe a\n   *  mano aquí: lo dice el servidor. `undefined` si el servidor todavía no lo devuelve (parche\n   *  `CHECKOUT-fees-y-minimo.md` pendiente): la app no avisa, pero el servidor sigue rechazando con su\n   *  mensaje, así que no se puede pedir por debajo. */\n  minOrderXaf?: number | null;\n}\n\nexport interface FoodMenuItem extends FoodItemDetails {\n  id: string; restaurantId: string; name: string; description: string | null;\n  category: 'bebida' | 'plato' | 'postre'; priceXaf: number; photos: string[];\n  available: boolean; status: string; rejectionReason: string | null; createdAt: string;\n}\n\nexport interface FoodRestaurantDetail extends FoodRestaurant { menu: FoodMenuItem[]; }\n\n/** El desglose del dinero de un pedido (se calcula y se congela al crear el pedido).\n *  Va en `null` en los pedidos anteriores a esta función: la app debe distinguir «no hay desglose»\n *  de «el desglose es cero», por eso no se rellena con 0. */\nexport interface OrderFees {\n  platformFeeXaf: number;\n  riderFeeXaf: number;\n  totalFeeXaf: number;\n  restaurantNetXaf: number;\n}\n\n/** La contabilidad semanal del repartidor. `aPagarXaf` = comisiones − efectivo, **nunca negativo**;\n *  lo que sobra queda como `deudaArrastradaXaf` para la semana siguiente. */\nexport interface ContabilidadRepartidor {\n  semana: { desde: string };\n  entregas: number;\n  comisionesXaf: number;\n  efectivoCobradoXaf: number;\n  aPagarXaf: number;\n  deudaArrastradaXaf: number;\n  movimientos: Array<{\n    id: string; orderId: string; totalXaf: number; comisionXaf: number;\n    efectivoXaf: number; pagadoConBilling: boolean; entregadoEn: string;\n  }>;\n}\n\nexport interface FoodRestaurantsPage {\n  items: FoodRestaurant[];\n  total: number;\n  page: number;\n  limit: number;\n  hasMore: boolean;\n}\n\nexport interface FoodOwnerMe {\n  kycOk: boolean; kycMessage: string | null;\n  restaurant: FoodRestaurant | null; menu: FoodMenuItem[];\n}\n\nexport interface FoodOrder {\n  id: string; userId: string; restaurantId: string; restaurantName: string | null; restaurantPhone: string | null;\n  /** Snapshot al crear el pedido. `prepMinutes` es aditivo (041): los pedidos\n   *  anteriores no la llevan → `undefined`, nunca romper en null. */\n  items: Array<{ itemId: string; name: string; price: number; qty: number; prepMinutes?: number | null }>;\n  totalXaf: number; paymentMethod: string; billingOrderId: string | null;\n  status: string; pickupType: string; deliveryAddress: string | null; note: string | null;\n  billingStatus: string | null; reviewed: boolean;\n  riderId: string | null; deliveryStatus: string | null;\n  /** ETA de cocina del pedido = el plato más lento (041). null = sin estimación. */\n  estPrepMinutes: number | null;\n  /** El desglose del dinero, congelado al crear el pedido. `null` en los pedidos anteriores: no es\n   *  «cero comisión», es «este pedido no tiene desglose» — y la app no debe inventarse un 0. */\n  platformFeeXaf: number | null;\n  riderFeeXaf: number | null;\n  restaurantNetXaf: number | null;\n  /** Si el local estaba cerrado al pedir, la hora a la que debe entregarse (pedido programado). */\n  scheduledFor: string | null;\n  /** ── UBICACIÓN DE ENTREGA Y PUNTO DE ENCUENTRO ─────────────────────────────────\n   *  `deliveryLat/Lng`: el pin que da el CLIENTE al pedir a domicilio. La dirección de texto sigue\n   *  siendo la base, pero «Aeropuerto» no se puede navegar; el pin sí.\n   *  `meetingNote/Lat/Lng/At`: lo que anota el REPARTIDOR al llegar («entrada por la puerta lateral,\n   *  junto a la farmacia»). Es la respuesta al hotel, las viviendas sociales o el portal sin número:\n   *  sitios donde el nombre del lugar no basta para encontrarse. Lo ven las dos partes.\n   *  Todos son `null` en pedidos anteriores o si nadie los usó. */\n  deliveryLat: number | null; deliveryLng: number | null;\n  meetingNote: string | null; meetingLat: number | null; meetingLng: number | null; meetingAt: string | null;\n  deliveredAt: string | null; createdAt: string;\n}\n\nexport interface FoodOrdersPage {\n  items: FoodOrder[];\n  total: number;\n  page: number;\n  limit: number;\n  hasMore: boolean;\n}\n\nexport interface FoodRider {\n  id: string; fullName: string; vehicleType: string; zone: string | null;\n  phoneContact: string | null; status: string; rejectionReason: string | null;\n  ratingAvg: number; deliveriesCount: number; approvedAt: string | null; createdAt: string;\n}\n\nexport interface FoodDelivery {\n  id: string; orderId: string; riderId: string; trackingCode: string; status: string;\n  assignedAt: string | null; pickedUpAt: string | null; deliveredAt: string | null;\n  items: Array<{ itemId: string; name: string; price: number; qty: number }>;\n  totalXaf: number; restaurantName: string | null; restaurantAddress: string | null;\n  restaurantPhone: string | null; clientPhone: string | null;\n  deliveryAddress: string | null; note: string | null;\n  /** El pin del cliente, para el botón «Cómo llegar». Si falta, la app cae al texto de la dirección\n   *  (peor, pero mejor que nada). `meetingNote` es lo que el propio repartidor anotó, para no\n   *  perderlo al recargar. */\n  deliveryLat?: number | null; deliveryLng?: number | null;\n  meetingNote?: string | null; meetingLat?: number | null; meetingLng?: number | null; meetingAt?: string | null;\n  /** 'cash' | 'billing'. Necesario para que el repartidor sepa si debe cobrar en la\n   *  puerta. El servidor aún no lo devuelve (parche C5 pendiente en\n   *  backend/server-patch/C5-rider-payment-method.md): hasta que se despliegue llega\n   *  `undefined`, y la app muestra el aviso neutro. Nunca se asume 'cash', porque\n   *  asumir es justo el error que este campo viene a evitar. */\n  paymentMethod?: string | null;\n}\n\nexport interface FoodRiderMe {\n  kycOk: boolean; kycMessage: string | null;\n  rider: FoodRider | null; deliveries: FoodDelivery[];\n}\n\nexport const foodApi = {\n  flags: () => http.get<{ f1: boolean; cash: boolean; billing: boolean; escrow: boolean }>(f('/food/flags'), false),\n  restaurants: (q: Record<string, string> = {}) => {\n    const qs = new URLSearchParams(q).toString();\n    return http.get<FoodRestaurantsPage>(f(`/food/restaurants${qs ? '?' + qs : ''}`), false);\n  },\n  restaurant: (id: string) => http.get<FoodRestaurantDetail>(f(`/food/restaurants/${id}`), false),\n  cuisines: () => http.get<FoodCuisine[]>(f('/food/cuisines'), false),\n  reportRestaurant: (id: string, reason: string, note?: string) =>\n    http.post<{ message: string }>(f(`/food/restaurants/${id}/report`), { reason, note }, true),\n  ownerMe: () => http.get<FoodOwnerMe>(f('/food/owner/me'), true),\n  uploadPhoto: (form: FormData) =>\n    httpRequest<{ url: string }>(f('/food/photo'), { method: 'POST', auth: true, form }),\n  upsertRestaurant: (body: Record<string, unknown>) =>\n    http.post<{ message: string; status: string; restaurantId?: string }>(f('/food/restaurants'), body, true),\n  myMenu: () => http.get<FoodMenuItem[]>(f('/food/menu/mine'), true),\n  createMenuItem: (body: Record<string, unknown>) =>\n    http.post<{ message: string; itemId: string; status: string }>(f('/food/menu'), body, true),\n  updateMenuItem: (id: string, body: Record<string, unknown>) =>\n    http.put<{ message: string }>(f(`/food/menu/${id}`), body, true),\n  setItemAvailable: (id: string, available: boolean) =>\n    http.put<{ message: string }>(f(`/food/menu/${id}/available`), { available }, true),\n  /** La FOTO de un plato se pone o se cambia cuando haga falta: el servidor lo permite en\n   *  cualquier estado y, si SOLO cambia la foto, el plato NO vuelve a revisión ni pierde su\n   *  estado. Es lo único que se puede tocar fuera de la moderación, porque no cambia lo que se\n   *  vende: cambia cómo se ve. */\n  setItemPhoto: (id: string, photos: string[]) =>\n    http.put<{ message: string }>(f(`/food/menu/${id}`), { photos }, true),\n  deleteMenuItem: (id: string) =>\n    httpRequest<{ message: string }>(f(`/food/menu/${id}`), { method: 'DELETE', auth: true }),\n  /**\n   * Crear pedido. Con pago por MONEDERO (parche 98) el servidor exige el token de pago\n   * (PIN, scope ESCROW_LOCK, importe EXACTO) en `X-Payment-Token`: el importe queda en\n   * garantía y el restaurante cobra en su monedero al entregar. El token es de un solo uso.\n   */\n  createOrder: (body: { restaurantId: string; items: Array<{ itemId: string; qty: number }>; paymentMethod?: 'cash' | 'billing' | 'likebook_wallet'; pickupType?: 'pickup' | 'delivery'; deliveryAddress?: string; note?: string; scheduledFor?: string | null; deliveryLat?: number | null; deliveryLng?: number | null }, paymentToken?: string) =>\n    httpRequest<{ message: string; order: FoodOrder; billingOrderId: string | null; fees?: OrderFees }>(f('/food/orders'), {\n      method: 'POST',\n      body,\n      auth: true,\n      ...(paymentToken ? { headers: { 'X-Payment-Token': paymentToken } } : {}),\n    }),\n  myOrders: (as: 'user' | 'owner' = 'user', q: Record<string, string> = {}) => {\n    const qs = new URLSearchParams({ as, ...q }).toString();\n    return http.get<FoodOrdersPage>(f(`/food/orders?${qs}`), true);\n  },\n  updateStatus: (id: string, status: string, as: 'user' | 'owner') =>\n    http.put<{ message: string }>(f(`/food/orders/${id}/status`), { status, as }, true),\n  review: (id: string, rating: number, comment?: string) =>\n    http.post<{ message: string }>(f(`/food/orders/${id}/review`), { rating, comment }, true),\n  riderMe: () => http.get<FoodRiderMe>(f('/food/rider/me'), true),\n  upsertRider: (body: Record<string, unknown>) =>\n    http.post<{ message: string; status: string; riderId?: string }>(f('/food/rider'), body, true),\n  activeRiders: () => http.get<FoodRider[]>(f('/food/riders/active'), true),\n  assignRider: (id: string, riderId: string) =>\n    http.put<{ message: string }>(f(`/food/orders/${id}/rider`), { riderId }, true),\n  updateDelivery: (id: string, status: string) =>\n    http.put<{ message: string }>(f(`/food/orders/${id}/delivery/status`), { status }, true),\n  /** El REPARTIDOR asignado anota el punto de encuentro al llegar. `lat`/`lng` son su ubicación en ese\n   *  momento (opcionales: sin GPS el texto sigue sirviendo). El servidor solo lo acepta si la entrega\n   *  es suya y no está cerrada, y avisa al cliente por SMS. */\n  setMeetingPoint: (id: string, body: { note: string; lat?: number | null; lng?: number | null }) =>\n    http.put<{ ok: boolean; meetingNote: string; meetingLat: number | null; meetingLng: number | null }>(\n      f(`/food/orders/${id}/delivery/meeting`), body, true),\n\n  // ── EL DINERO DEL REPARTIDOR ─────────────────────────────────────────────────\n  /** Su contabilidad de la semana: entregas, comisiones, efectivo cobrado y qué le corresponde.\n   *  La regla del dueño la aplica el servidor: `aPagarXaf` nunca es negativo y lo que sobra queda\n   *  como `deudaArrastradaXaf`. */\n  riderContabilidad: (desde?: string) =>\n    http.get<ContabilidadRepartidor>(f(`/food/rider/contabilidad${desde ? `?desde=${desde}` : ''}`), true),\n  /** Anota el efectivo que ha cobrado en la puerta de una entrega. Es lo ÚNICO que escribe el\n   *  repartidor: su comisión la calcula el servidor con el desglose congelado del pedido. */\n  riderAnotarCobro: (orderId: string, cashCollectedXaf: number) =>\n    http.post<{ message: string }>(f('/food/rider/cobro'), { orderId, cashCollectedXaf }, true),\n};\n","/**\n * Store global de Comida Rápida (Zustand v5) — carrito del menú.\n *\n * Auditoría senior (2026-09-02):\n *  · CADA línea lleva su `restaurantId` (un pedido = UN restaurante). La\n *    validación compara restaurante con restaurante, nunca ids de ítems.\n *  · `switchRestaurant(id)` limpia + fija tras confirmar el descarte; la\n *    pantalla decide con diálogo (nunca se borra el carrito sin avisar).\n *  · `addToCart` se niega a mezclar restaurantes (defensa dura para\n *    deep-links / estados raros).\n *  · `setQty` valida enteros ≥ 0 y capa en 99 (el backend capa en 100).\n *  · Persistencia con AsyncStorage (zustand/middleware): el carrito sobrevive\n *    al cierre de la app (entrega a domicilio = pedido en curso real).\n */\n\nimport { create } from 'zustand';\nimport { persist, createJSONStorage } from 'zustand/middleware';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\n\nexport interface FoodCartLine {\n  itemId: string;\n  /** Restaurante al que pertenece esta línea (auditoría: validación real). */\n  restaurantId: string;\n  name: string;\n  priceXaf: number;\n  qty: number;\n  category: string;\n}\n\nconst MAX_QTY = 99;\n\ninterface FoodState {\n  restaurantId: string;\n  cart: FoodCartLine[];\n  /** Fija el restaurante en contexto (sin tocar el carrito). */\n  setRestaurant: (id: string) => void;\n  /** Cambia de restaurante DESCARTANDO el carrito (tras confirmación UX). */\n  switchRestaurant: (id: string) => void;\n  addToCart: (line: Omit<FoodCartLine, 'qty'>) => void;\n  setQty: (itemId: string, qty: number) => void;\n  removeFromCart: (itemId: string) => void;\n  clearCart: () => void;\n}\n\nexport const useFoodStore = create<FoodState>()(\n  persist(\n    (set) => ({\n      restaurantId: '',\n      cart: [],\n\n      setRestaurant: (id) => set({ restaurantId: id }),\n\n      switchRestaurant: (id) => set({ restaurantId: id, cart: [] }),\n\n      addToCart: (line) =>\n        set((s) => {\n          // Un pedido = un restaurante: si el carrito ya tiene ítems de OTRO\n          // restaurante, no mezclar (la UI confirma antes con switchRestaurant;\n          // esto cubre deep-links y rehidrataciones raras).\n          if (s.cart.length > 0 && s.cart[0].restaurantId !== line.restaurantId) return s;\n          const existing = s.cart.find((c) => c.itemId === line.itemId);\n          if (existing) {\n            return {\n              cart: s.cart.map((c) =>\n                c.itemId === line.itemId ? { ...c, qty: Math.min(c.qty + 1, MAX_QTY) } : c),\n            };\n          }\n          return { cart: [...s.cart, { ...line, qty: 1 }], restaurantId: line.restaurantId };\n        }),\n\n      setQty: (itemId, qty) =>\n        set((s) => {\n          if (!Number.isInteger(qty) || qty < 0) return s; // validación defensiva\n          if (qty === 0) return { cart: s.cart.filter((c) => c.itemId !== itemId) };\n          return {\n            cart: s.cart.map((c) => (c.itemId === itemId ? { ...c, qty: Math.min(qty, MAX_QTY) } : c)),\n          };\n        }),\n\n      removeFromCart: (itemId) =>\n        set((s) => ({ cart: s.cart.filter((c) => c.itemId !== itemId) })),\n\n      clearCart: () => set({ cart: [], restaurantId: '' }),\n    }),\n    {\n      name: 'eg-food-cart',\n      storage: createJSONStorage(() => AsyncStorage),\n      version: 1,\n      // Migración defensiva: las líneas viejas sin restaurantId se etiquetan\n      // con el restaurante persistido (o '' y la UI decidirá).\n      migrate: (persisted) => {\n        const p = (persisted ?? {}) as Partial<FoodState> | null;\n        const lines = Array.isArray(p?.cart) ? p.cart : [];\n        return {\n          restaurantId: typeof p?.restaurantId === 'string' ? p.restaurantId : '',\n          cart: lines.map((c) => ({\n            itemId: String(c.itemId ?? ''),\n            restaurantId: typeof c.restaurantId === 'string' ? c.restaurantId : (p?.restaurantId ?? ''),\n            name: String(c.name ?? ''),\n            priceXaf: Number(c.priceXaf ?? 0),\n            qty: Number(c.qty ?? 1),\n            category: String(c.category ?? 'plato'),\n          })),\n        };\n      },\n      partialize: (s) => ({ restaurantId: s.restaurantId, cart: s.cart }),\n    },\n  ),\n);\n\n/** Total del carrito en XAF (entero). Selector puro: úsalo con useMemo. */\nexport function foodCartTotal(cart: FoodCartLine[]): number {\n  return cart.reduce((acc, c) => acc + c.priceXaf * c.qty, 0);\n}\n\n/** Nº de ítems (suma de cantidades). Selector puro: úsalo con useMemo. */\nexport function foodCartCount(cart: FoodCartLine[]): number {\n  return cart.reduce((acc, c) => acc + c.qty, 0);\n}\n","/**\n * FoodMenuScreen — Menú del restaurante con carrito (Zustand persistente).\n *\n * Auditoría senior (2026-09-02):\n *  · Carrito por restaurante: cada línea lleva su restaurantId; al entrar a un\n *    restaurante con carrito de OTRO, se pregunta (diálogo) — nunca se borra\n *    sin avisar ni se mezclan restaurantes.\n *  · Carga con skeleton + error con Reintentar (nunca pantalla vacía por red).\n *  · Empty state cuando el restaurante aún no tiene ítems.\n *  · Header con Abierto/Cerrado (servidor, hora de Malabo); cerrado NO bloquea:\n *    \"el restaurante confirmará tu pedido cuando abra\" (decisión de producto).\n *  · a11y (back, +/−, CTA con total), SafeArea superior e inferior, tope de 99\n *    por ítem (backend capa en 100), selectores puros con useMemo.\n * Ruta: /food-menu?id=\n */\n\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Minus, Plus, Star } from 'lucide-react-native';\nimport { alpha, brand, EmptyState, espaciado, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { foodApi, FoodMenuItem, FoodRestaurantDetail, SPICE_LABEL, SPICE_ICON } from '../api/food';\nimport { foodCartCount, foodCartTotal, FoodCartLine, useFoodStore } from '../state/food';\nimport { itemDetailSummary } from '../utils/foodItemDetails';\nimport { formatXAF } from '../utils/formatHelpers';\n\nconst CAT_ORDER = ['plato', 'bebida', 'postre'] as const;\nconst CAT_LABEL: Record<string, string> = { plato: 'Platos', bebida: 'Bebidas', postre: 'Postres' };\n// Acento del flujo de servicios (naranja), consistente con la home de Comida y\n// Ecomerse. Nota DS: migración a token del theme (secondary #FF7D00) sería un\n// repintado global del marketplace — pendiente como ronda de design system.\nconst ACCENT = brand.primary; // A1: la acción avanza en azul\n\nexport default function FoodMenuScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { id } = useLocalSearchParams<{ id: string }>();\n  const [detail, setDetail] = useState<FoodRestaurantDetail | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [reloadKey, setReloadKey] = useState(0);\n  const cart = useFoodStore((s) => s.cart);\n\n  // ── Entrada: si el carrito es de OTRO restaurante, confirmar el descarte.\n  // Se lee el estado con getState() (sin dependencias → sin bucles) y el Alert\n  // no es cancelable en Android (no se puede quedar en un limbo).\n  useEffect(() => {\n    if (!id) return;\n    const st = useFoodStore.getState();\n    if (st.restaurantId && st.restaurantId !== id && st.cart.length > 0) {\n      Alert.alert(\n        '¿Nuevo pedido?',\n        'Ya tienes ítems de otro restaurante en el carrito. Para pedir aquí hay que descartarlos.',\n        [\n          { text: 'Volver', style: 'cancel', onPress: () => router.back() },\n          { text: 'Descartar y pedir aquí', style: 'destructive', onPress: () => useFoodStore.getState().switchRestaurant(id) },\n        ],\n        { cancelable: false },\n      );\n    } else {\n      st.setRestaurant(id);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [id]);\n\n  // ── Carga del detalle (skeleton / error / Reintentar). cancelled evita\n  // setState de una petición obsoleta (cambio de id o desmontaje).\n  useEffect(() => {\n    if (!id) return;\n    let cancelled = false;\n    setLoading(true);\n    setError(null);\n    setDetail(null);\n    foodApi.restaurant(id)\n      .then((d) => { if (!cancelled) setDetail(d); })\n      .catch(() => { if (!cancelled) setError('No pudimos cargar el menú. Revisa tu conexión e inténtalo de nuevo.'); })\n      .finally(() => { if (!cancelled) setLoading(false); });\n    return () => { cancelled = true; };\n  }, [id, reloadKey]);\n\n  const retry = useCallback(() => setReloadKey((k) => k + 1), []);\n\n  // Líneas del carrito de ESTE restaurante (defensa ante estados raros).\n  const lines = useMemo<FoodCartLine[]>(\n    () => (id ? cart.filter((c) => c.restaurantId === id) : []),\n    [cart, id],\n  );\n  const qtyMap = useMemo(() => new Map(lines.map((c) => [c.itemId, c.qty])), [lines]);\n  const count = useMemo(() => foodCartCount(lines), [lines]);\n  const total = useMemo(() => foodCartTotal(lines), [lines]);\n  const isOpen = detail?.isOpen ?? null;\n\n  const add = (m: FoodMenuItem) => {\n    if (!id) return;\n    useFoodStore.getState().addToCart({\n      itemId: m.id, restaurantId: id, name: m.name, priceXaf: m.priceXaf, category: m.category,\n    });\n  };\n\n  const s = styles(colors);\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Cabecera del kit desde el 24/09/2026. `lineasTitulo={2}` porque el título es el NOMBRE DEL\n          COMERCIO (`detail?.businessName`), que no tiene tope de longitud conocido. */}\n      <ScreenHeader\n        titulo={detail?.businessName ?? 'Menú'}\n        alVolver={() => router.back()}\n        lineasTitulo={2}\n      />\n\n      <ScrollView\n        contentContainerStyle={[s.content, { paddingBottom: 96 + insets.bottom }]}\n        showsVerticalScrollIndicator={false}\n      >\n        {loading ? (\n          <MenuSkeleton colors={colors} />\n        ) : error ? (\n          <View style={s_center.wrap}>\n            <Text style={{ fontSize: 38, marginBottom: espaciado.e8 }}>📡</Text>\n            <Text style={[s_center.title, { color: colors.textPrimary }]}>No pudimos cargar el menú</Text>\n            <Text style={[s_center.sub, { color: colors.textSecondary }]}>{error}</Text>\n            <Pressable onPress={retry} accessibilityRole=\"button\" style={s_center.btnPrimary}>\n              <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n            </Pressable>\n          </View>\n        ) : detail ? (\n          <>\n            {/* Cabecera del restaurante */}\n            <RestaurantHeader detail={detail} />\n\n            {isOpen === false && (\n              <View style={[s.closedNote, { backgroundColor: alpha(colors.danger, 0.07), borderColor: alpha(colors.danger, 0.25) }]}>\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', lineHeight: 16 }}>\n                  Cerrado ahora · puedes dejar tu pedido y el restaurante lo confirmará cuando abra.\n                </Text>\n              </View>\n            )}\n\n            {detail.menu.length === 0 ? (\n              /* Es una ESPERA: la carta la publica el restaurante. Se dice qué la llena y no\n                 se inventa un botón (regla de la tanda 2 del informe). */\n              <EmptyState\n                icono={<Text style={{ fontSize: 40 }}>🍽️</Text>}\n                titulo=\"Todavía no hay ítems en el menú\"\n                texto=\"Los platos publicados y aprobados por el restaurante aparecerán aquí, con su precio.\"\n              />\n            ) : (\n              CAT_ORDER.map((cat) => {\n                const items = detail.menu.filter((m) => m.category === cat);\n                if (items.length === 0) return null;\n                return (\n                  <View key={cat} style={{ marginBottom: espaciado.e18 }}>\n                    <Text style={s.catTitle}>{CAT_LABEL[cat]}</Text>\n                    {items.map((m) => (\n                      <MenuItemRow key={m.id} item={m} qty={qtyMap.get(m.id) ?? 0}\n                        onAdd={() => add(m)}\n                        onDec={() => useFoodStore.getState().setQty(m.id, (qtyMap.get(m.id) ?? 0) - 1)}\n                        onInc={() => useFoodStore.getState().setQty(m.id, (qtyMap.get(m.id) ?? 0) + 1)}\n                      />\n                    ))}\n                  </View>\n                );\n              })\n            )}\n          </>\n        ) : null}\n      </ScrollView>\n\n      {/* Barra sticky de pedido (solo ítems de este restaurante) */}\n      {count > 0 && (\n        <View style={[s.bottomBar, { backgroundColor: colors.card, borderTopColor: colors.border, paddingBottom: espaciado.e10 + insets.bottom }]}>\n          <Pressable\n            onPress={() => router.push({ pathname: '/food-checkout', params: { restaurantId: id } } as any)}\n            accessibilityRole=\"button\"\n            accessibilityLabel={`Ver pedido: ${count} ítems, total ${formatXAF(total)}`}\n            style={s.cta}\n          >\n            <Text style={s.ctaText}>Ver pedido · {count} ítem{count === 1 ? '' : 's'} · {formatXAF(total)}</Text>\n          </Pressable>\n        </View>\n      )}\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\nfunction RestaurantHeader({ detail }: { detail: FoodRestaurantDetail }) {\n  const { colors } = useTheme();\n  const showRating = detail.ratingCount > 0 && Number.isFinite(detail.ratingAvg);\n  const km = Number.isFinite(detail.deliveryKm) && detail.deliveryKm > 0 ? detail.deliveryKm : 0;\n  const open = detail.isOpen ?? null;\n  return (\n    <View style={{ marginBottom: espaciado.e14 }}>\n      <Text style={[s_h.name, { color: colors.textPrimary }]}>{detail.businessName}</Text>\n      <Text style={[s_h.sub, { color: colors.textSecondary }]}>\n        {detail.cuisineLabel ?? 'Restaurante'} · {detail.city}\n      </Text>\n      <View style={s_h.metaRow}>\n        {open !== null ? (\n          <View style={[s_h.badge, { backgroundColor: open ? alpha(colors.success, 0.14) : alpha(colors.danger, 0.12) }]}>\n            <View style={[s_h.dot, { backgroundColor: open ? colors.success : colors.danger }]} />\n            <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: open ? colors.success : colors.danger }}>\n              {open ? 'Abierto' : 'Cerrado'}\n            </Text>\n          </View>\n        ) : null}\n        <Text style={[s_h.sub, { color: colors.textSecondary, flexShrink: 1 }]}>\n          {detail.hours ? `🕐 ${detail.hours}` : 'Horario no publicado'}\n        </Text>\n      </View>\n      {showRating && (\n        <View style={s_h.metaRow}>\n          <Star size={12} color={colors.secondary} fill={colors.secondary} />\n          <Text style={[s_h.sub, { color: colors.textSecondary }]}>\n            {detail.ratingAvg.toFixed(1)} · {detail.ratingCount} valoración{detail.ratingCount === 1 ? '' : 'es'}\n          </Text>\n        </View>\n      )}\n      {detail.address ? (\n        <Text numberOfLines={2} style={[s_h.sub, { color: colors.textSecondary, marginTop: espaciado.e2 }]}>📍 {detail.address}</Text>\n      ) : null}\n      {km > 0 ? (\n        <Text style={[s_h.sub, { color: ACCENT, fontWeight: '700', marginTop: espaciado.e2 }]}>🛵 Reparto hasta {km} km</Text>\n      ) : null}\n    </View>\n  );\n}\n\nfunction MenuItemRow({ item, qty, onAdd, onDec, onInc }: {\n  item: FoodMenuItem; qty: number; onAdd: () => void; onDec: () => void; onInc: () => void;\n}) {\n  const { colors } = useTheme();\n  const photo = item.photos?.[0] && /^https?:\\/\\//i.test(item.photos[0]) ? item.photos[0] : null;\n  const atMax = qty >= 99;\n  // Detalle del plato (041): ingredientes, picante, ración, acompañantes.\n  // Todo condicional — un plato sin declarar nada se ve igual que antes.\n  const detailSummary = itemDetailSummary(item);\n  return (\n    <View style={[s_row.card, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n      {photo ? (\n        <Image source={{ uri: photo }} style={s_row.img} contentFit=\"cover\" transition={200} />\n      ) : (\n        /* Sin foto: NO se pone un dibujo de comida. Un dibujo ocupa el sitio de la foto y disimula\n           que falta —el cliente cree que está viendo el plato y no está viendo nada—. Se deja un\n           hueco limpio con la categoría escrita: es lo que hay, dicho claro. */\n        <View style={[s_row.img, s_row.imgFallback]}>\n          <Text style={{ fontSize: 10, fontWeight: '700', color: colors.textSecondary, textAlign: 'center' }}>\n            {item.category === 'plato' ? 'Plato' : item.category === 'bebida' ? 'Bebida' : 'Postre'}\n          </Text>\n        </View>\n      )}\n      <View style={s_row.body}>\n        <Text numberOfLines={1} style={[s_row.name, { color: colors.textPrimary }]}>{item.name}</Text>\n        {item.description ? (\n          <Text numberOfLines={2} style={[s_row.desc, { color: colors.textSecondary }]}>{item.description}</Text>\n        ) : null}\n\n        {/* Ingredientes */}\n        {item.ingredients ? (\n          <Text numberOfLines={1} style={[s_row.detailLine, { color: colors.textSecondary }]}>\n            🧂 {item.ingredients}\n          </Text>\n        ) : null}\n        {/* Acompañantes */}\n        {item.sides && item.sides.length > 0 ? (\n          <Text numberOfLines={1} style={[s_row.detailLine, { color: colors.textSecondary }]}>\n            🍚 {item.sides.join(', ')}\n          </Text>\n        ) : null}\n\n        {/* Chips: picante · ración · resumen (bebida/prep) */}\n        {(item.spiceLevel || item.portionSize || detailSummary) ? (\n          <View style={s_row.chips}>\n            {item.spiceLevel ? (\n              <View style={[s_row.miniChip, { backgroundColor: alpha(ACCENT, 0.1) }]}>\n                <Text style={s_row.miniChipText}>{SPICE_ICON[item.spiceLevel]} {SPICE_LABEL[item.spiceLevel]}</Text>\n              </View>\n            ) : null}\n            {item.portionSize ? (\n              <View style={[s_row.miniChip, { backgroundColor: alpha(colors.primary, 0.08) }]}>\n                <Text style={[s_row.miniChipText, { color: colors.primary }]}>📏 {item.portionSize}</Text>\n              </View>\n            ) : null}\n            {detailSummary ? (\n              <View style={[s_row.miniChip, { backgroundColor: colors.border }]}>\n                <Text style={[s_row.miniChipText, { color: colors.textPrimary }]}>{detailSummary}</Text>\n              </View>\n            ) : null}\n          </View>\n        ) : null}\n\n        <Text style={s_row.price}>{formatXAF(item.priceXaf)}</Text>\n      </View>\n      {qty === 0 ? (\n        <Pressable onPress={onAdd} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Añadir ${item.name}`}\n          style={s_row.addBtn}>\n          <Plus size={16} color={brand.white} strokeWidth={3} />\n        </Pressable>\n      ) : (\n        <View style={s_row.stepper}>\n          <Pressable onPress={onDec} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Quitar uno de ${item.name}`}\n            style={[s_row.stepBtn, { backgroundColor: colors.border }]}>\n            <Minus size={14} color={colors.textPrimary} strokeWidth={3} />\n          </Pressable>\n          <Text style={[s_row.qty, { color: colors.textPrimary }]}>{qty}</Text>\n          <Pressable onPress={onInc} disabled={atMax} hitSlop={6} accessibilityRole=\"button\"\n            accessibilityLabel={`Añadir más ${item.name}`}\n            style={[s_row.stepBtn, { backgroundColor: ACCENT, opacity: atMax ? 0.4 : 1 }]}>\n            <Plus size={14} color={brand.white} strokeWidth={3} />\n          </Pressable>\n        </View>\n      )}\n    </View>\n  );\n}\n\nfunction MenuSkeleton({ colors }: { colors: ReturnType<typeof useTheme>['colors'] }) {\n  return (\n    <View>\n      <View style={{ marginBottom: espaciado.e16, gap: espaciado.e7 }}>\n        <View style={{ height: 18, borderRadius: 4, backgroundColor: colors.border, width: '55%' }} />\n        <View style={{ height: 11, borderRadius: 4, backgroundColor: colors.border, width: '38%' }} />\n        <View style={{ height: 11, borderRadius: 4, backgroundColor: colors.border, width: '48%' }} />\n      </View>\n      <View style={{ height: 13, borderRadius: 4, backgroundColor: colors.border, width: 90, marginBottom: espaciado.e10 }} />\n      {[0, 1, 2].map((i) => (\n        <View key={i} style={[s_sk.row, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n          <View style={{ width: 52, height: 52, borderRadius: 10, backgroundColor: colors.border }} />\n          <View style={{ flex: 1, marginLeft: espaciado.e10, gap: espaciado.e6 }}>\n            <View style={{ height: 11, borderRadius: 4, backgroundColor: colors.border, width: '70%' }} />\n            <View style={{ height: 10, borderRadius: 4, backgroundColor: colors.border, width: '45%' }} />\n          </View>\n          <View style={{ width: 30, height: 30, borderRadius: 9, backgroundColor: colors.border }} />\n        </View>\n      ))}\n    </View>\n  );\n}\n\nconst s_h = StyleSheet.create({\n  name: { fontSize: 19, fontWeight: '900' },\n  sub: { fontSize: tipografia.caption, marginTop: espaciado.e2 },\n  metaRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e5, flexWrap: 'wrap' },\n  badge: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, borderRadius: 10, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  dot: { width: 6, height: 6, borderRadius: 3 },\n});\n\nconst s_row = StyleSheet.create({\n  card: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, padding: espaciado.e10, marginBottom: espaciado.e8, borderWidth: 1 },\n  // 64 en vez de 52: la foto de un plato es lo primero que mira el cliente («¿esto tiene buena\n  // pinta?»). A 52 px no se distinguía el plato; a 64 se ve, y sigue cabiendo en la fila.\n  img: { width: 64, height: 64, borderRadius: 10 },\n  imgFallback: { backgroundColor: 'rgba(255,107,53,0.08)', alignItems: 'center', justifyContent: 'center' },\n  body: { flex: 1, marginLeft: espaciado.e10, marginRight: espaciado.e8 },\n  name: { fontSize: tipografia.body, fontWeight: '700' },\n  desc: { fontSize: tipografia.micro, marginTop: 1, lineHeight: 14 },\n  price: { fontSize: tipografia.body, fontWeight: '900', color: ACCENT, marginTop: espaciado.e2 },\n  addBtn: { backgroundColor: ACCENT, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, borderRadius: 10 },\n  stepper: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 },\n  stepBtn: { width: 30, height: 30, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\n  qty: { fontSize: tipografia.body, fontWeight: '800', minWidth: 18, textAlign: 'center' },\n  // ── Detalle del plato (041) ──\n  // Nota: `card` usa alignItems:'center' a propósito. Con detalles la tarjeta\n  // crece a 3-5 líneas y la foto y el stepper quedan centrados en vertical, que\n  // es lo que ya pasa hoy con la descripción larga. No se cambia para no mover\n  // el aspecto de los platos que no declaran ningún detalle.\n  detailLine: { fontSize: 10.5, marginTop: espaciado.e2, lineHeight: 14 },\n  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e5, marginTop: espaciado.e4 },\n  miniChip: { borderRadius: radios.sm, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3 },\n  miniChipText: { fontSize: 10, fontWeight: '700', color: ACCENT },\n});\n\nconst s_sk = StyleSheet.create({\n  row: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, padding: espaciado.e10, marginBottom: espaciado.e8, borderWidth: 1 },\n});\n\nconst s_center = StyleSheet.create({\n  wrap: { alignItems: 'center', paddingTop: 48, paddingHorizontal: espaciado.e28 },\n  title: { fontSize: 15, fontWeight: '800', textAlign: 'center' },\n  sub: { fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 },\n  btnPrimary: { marginTop: espaciado.e18, backgroundColor: ACCENT, paddingHorizontal: espaciado.e24, paddingVertical: espaciado.e11, borderRadius: 22 },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  content: { padding: espaciado.e16 },\n  catTitle: { fontSize: tipografia.body, fontWeight: '800', color: c.textPrimary, marginBottom: espaciado.e8 },\n  closedNote: { borderRadius: 10, borderWidth: 1, padding: espaciado.e10, marginBottom: espaciado.e12 },\n  bottomBar: { position: 'absolute', left: 0, right: 0, bottom: 0, paddingHorizontal: espaciado.e16, paddingTop: espaciado.e10, borderTopWidth: 1 },\n  cta: { backgroundColor: ACCENT, borderRadius: radios.md, paddingVertical: espaciado.e14, alignItems: 'center' },\n  ctaText: { color: brand.white, fontSize: 15, fontWeight: '900' },\n});\n","/**\n * Detalle de plato (migración 041) — parseo, validación y formato.\n *\n * Espejo del backend `food.dto.ts` (parche 041-A): los mismos límites, para que\n * lo que la pantalla acepta sea exactamente lo que el servidor acepta. Si el\n * dueño escribe algo que aquí pasa pero el servidor rechaza, el usuario pierde\n * el formulario entero — por eso ambos ficheros se mantienen sincronizados.\n *\n * Ingredientes y acompañantes son texto libre en la UI (el dueño no debe\n * aprender sintaxis), pero se normalizan a estructura antes de enviar:\n *   · ingredients → string única (BD es text), separada por comas\n *   · sides       → string[] (BD es jsonb), cada acompañante por separado\n */\n\nimport { INGREDIENTS_MAX, PORTION_SIZE_MAX, PREP_MINUTES_MAX, SIDES_MAX, type SpiceLevel } from '../api/food';\n\n/** Separadores aceptados al escribir ingredientes/acompañantes. */\nconst SEPARATORS = /[,;·\\n]/;\n\n/** Quita vacíos, trim y duplicados preservando el orden de aparición. */\nfunction normalizeList(raw: string): string[] {\n  const seen = new Set<string>();\n  const out: string[] = [];\n  for (const part of raw.split(SEPARATORS)) {\n    const v = part.trim().replace(/\\s+/g, ' ');\n    if (!v) continue;\n    const key = v.toLowerCase();\n    if (seen.has(key)) continue; // \"arroz, ARROZ\" → un solo acompañante\n    seen.add(key);\n    out.push(v);\n  }\n  return out;\n}\n\n// --- Ingredientes -----------------------------------------------------------\n\n/** Texto libre → string normalizada para guardar (BD: text). '' si vacío. */\nexport function parseIngredients(raw: string): string {\n  return normalizeList(raw).join(', ');\n}\n\n/** String de BD → texto para el campo (ya viene normalizada, solo trim). */\nexport function ingredientsToField(v: string | null | undefined): string {\n  return (v ?? '').trim();\n}\n\n/** Mensaje de error si excede el máximo; null si es válido (o vacío). */\nexport function ingredientsError(v: string): string | null {\n  return parseIngredients(v).length > INGREDIENTS_MAX\n    ? `Demasiado largo: máximo ${INGREDIENTS_MAX} caracteres.`\n    : null;\n}\n\n// --- Acompañantes -----------------------------------------------------------\n\n/** Texto libre → array para guardar (BD: jsonb). */\nexport function parseSides(raw: string): string[] {\n  return normalizeList(raw).slice(0, SIDES_MAX);\n}\n\n/** Array de BD → texto para el campo. */\nexport function sidesToField(v: string[] | null | undefined): string {\n  return Array.isArray(v) ? v.join(', ') : '';\n}\n\n/** Mensaje de error si hay demasiados o alguno es muy largo; null si válido. */\nexport function sidesError(v: string): string | null {\n  const list = parseSides(v);\n  if (list.length > SIDES_MAX) return `Máximo ${SIDES_MAX} acompañantes.`;\n  if (list.some((s) => s.length > 60)) return 'Cada acompañante, máximo 60 caracteres.';\n  return null;\n}\n\n// --- Tamaño / ración --------------------------------------------------------\n\nexport function portionSizeError(v: string): string | null {\n  return v.trim().length > PORTION_SIZE_MAX\n    ? `Máximo ${PORTION_SIZE_MAX} caracteres.`\n    : null;\n}\n\n// --- Tiempo de preparación --------------------------------------------------\n\n/** Texto del campo → entero de minutos, o null si vacío/no numérico. */\nexport function parsePrepMinutes(raw: string): number | null {\n  const t = raw.trim();\n  if (!t) return null;\n  const n = Number(t);\n  if (!Number.isFinite(n)) return null;\n  return Math.floor(n);\n}\n\n/** Mensaje de error; null si válido o vacío (campo opcional). */\nexport function prepMinutesError(raw: string): string | null {\n  const t = raw.trim();\n  if (!t) return null;\n  const n = parsePrepMinutes(t);\n  if (n === null) return 'Pon un número entero de minutos.';\n  if (n < 1) return 'Mínimo 1 minuto.';\n  if (n > PREP_MINUTES_MAX) return `Máximo ${PREP_MINUTES_MAX} minutos.`;\n  return null;\n}\n\n// --- Picante ----------------------------------------------------------------\n\n/** Orden de menor a mayor picante (para los chips del formulario). */\nexport const SPICE_ORDER: SpiceLevel[] = ['none', 'mild', 'medium', 'hot', 'extra_hot'];\n\n/** True si el valor es un nivel de picante conocido (defensa ante datos viejos). */\nexport function isSpiceLevel(v: unknown): v is SpiceLevel {\n  return typeof v === 'string' && (SPICE_ORDER as string[]).includes(v);\n}\n\n// --- Formateo para ficha ----------------------------------------------------\n\n/** Resumen de una línea para la tarjeta del menú; null si no hay nada que mostrar.\n *  ⚠ NO incluye `portionSize`: la tarjeta ya lo pinta como chip propio (📏), y\n *  meterlo aquí lo mostraría dos veces. Solo bebida incluida y tiempo de cocina. */\nexport function itemDetailSummary(item: {\n  drinkIncluded?: boolean;\n  prepMinutes?: number | null;\n}): string | null {\n  const parts: string[] = [];\n  if (item.drinkIncluded) parts.push('bebida incluida');\n  if (typeof item.prepMinutes === 'number' && item.prepMinutes > 0) {\n    parts.push(`~${item.prepMinutes} min`);\n  }\n  return parts.length > 0 ? parts.join(' · ') : null;\n}\n","/**\n * FoodOrdersScreen — Mis pedidos (cliente u dueño) con timeline de estados\n * (placed→confirmed→preparing→ready→delivered), filtros por estado y\n * valoración tras entrega.\n *\n * Auditorías senior (2026-09-02):\n *  · Valoración con MODAL de 5 estrellas cross-platform (Alert.prompt era iOS).\n *  · Asignar repartidor en MODAL de lista (Alert con >3 botones rompe Android).\n *  · LISTA PAGINADA server-side (?page&limit&state, {items,total,hasMore}) con\n *    infinite scroll, footer propio (cargando/error/fin) y chips de filtro:\n *    Todos / En curso / Entregados / Cancelados (filtro en el servidor para que\n *    la paginación sea correcta).\n *  · Máquina de estados del cliente extraída a constantes (OWNER_FLOW/\n *    USER_FLOW) — un solo lugar, sincronizada con el backend.\n *  · Timeline con labels bajo cada punto y rol progressbar; cancelado = banner\n *    (sin stepper falso).\n *  · Carga skeleton / error+Reintentar / pull-to-refresh; vacíos por rol con\n *    CTA; fecha y hora completas del pedido; keys estables; a11y en acciones.\n * Ruta: /food-orders?as=user|owner\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, FlatList, Modal, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Star } from 'lucide-react-native';\nimport { alpha, espaciado, GhostButton, radios, ScreenHeader, Sheet, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { foodApi, FoodOrder, FoodOrdersPage, FoodRider } from '../api/food';\nimport { formatDateTime, formatXAF } from '../utils/formatHelpers';\nimport { abrirMapa } from '../utils/maps';\nimport { brand } from '@egrouteplan/ui-kit';\n\ntype Role = 'user' | 'owner';\ntype StateFilter = '' | 'open' | 'delivered' | 'cancelled';\n\nconst ACCENT = brand.primary; // A1: la acción avanza en azul\nconst PAGE_SIZE = 20;\nconst STATUS: Record<string, { label: string; color: string }> = {\n  placed: { label: 'Recibido', color: brand.warning },\n  confirmed: { label: 'Confirmado', color: brand.info },\n  preparing: { label: 'Preparando', color: brand.info },\n  ready: { label: 'Listo', color: brand.success },\n  delivered: { label: 'Entregado', color: brand.success },\n  cancelled: { label: 'Cancelado', color: brand.neutral },\n};\nconst FLOW = ['placed', 'confirmed', 'preparing', 'ready', 'delivered'] as const;\n// Máquina de estados del cliente (única fuente; espejo del backend).\nconst OWNER_NEXT: Record<string, string | null> = {  placed: 'confirmed', confirmed: 'preparing', preparing: 'ready', ready: 'delivered', delivered: null, cancelled: null,\n};\nconst USER_NEXT: Record<string, string | null> = {\n  ready: 'delivered', delivered: null, cancelled: null,\n};\n\n/**\n * ¿Se puede cancelar este pedido, con este rol, en este estado?\n *\n * Es ESPEJO de la tabla del servidor (`updateOrderStatus`, reglas del Lote 1), y está aquí para no\n * ofrecer un botón que el servidor va a rechazar. Si algún día cambian las reglas, cambian en el\n * servidor y aquí: las dos listas tienen que decir lo mismo.\n *   · el CLIENTE, mientras no haya empezado la cocina;\n *   · el DUEÑO, en cualquier estado no entregado (es quien sabe si puede servir el pedido).\n */\nconst CANCELABLE_BY_OWNER = ['placed', 'confirmed', 'preparing', 'ready'];\nconst CANCELABLE_BY_USER = ['placed', 'confirmed'];\nconst puedeCancelar = (isOwner: boolean, status: string) =>\n  (isOwner ? CANCELABLE_BY_OWNER : CANCELABLE_BY_USER).includes(status);\nconst STATE_CHIPS: Array<{ key: StateFilter; label: string }> = [\n  { key: '', label: 'Todos' },\n  { key: 'open', label: 'En curso' },\n  { key: 'delivered', label: 'Entregados' },\n  { key: 'cancelled', label: 'Cancelados' },\n];\nconst SKELETONS = [0, 1, 2];\n\nexport default function FoodOrdersScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { as } = useLocalSearchParams<{ as?: string }>();\n  const role: Role = as === 'owner' ? 'owner' : 'user';\n  const isOwner = role === 'owner';\n\n  const [orders, setOrders] = useState<FoodOrder[]>([]);\n  const [total, setTotal] = useState(0);\n  const [page, setPage] = useState(1);\n  const [pageSize, setPageSize] = useState(PAGE_SIZE);\n  const [hasMore, setHasMore] = useState(false);\n  const [stateFilter, setStateFilter] = useState<StateFilter>('');\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [loadMoreError, setLoadMoreError] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [busyOrderId, setBusyOrderId] = useState<string | null>(null);\n  const [reviewOrder, setReviewOrder] = useState<FoodOrder | null>(null);\n  const [assignOrder, setAssignOrder] = useState<FoodOrder | null>(null);\n  const [riders, setRiders] = useState<FoodRider[]>([]);\n  const [ridersLoading, setRidersLoading] = useState(false);\n  const reqId = useRef(0);\n  const busyRef = useRef(false);\n  // ── AVISO DE PEDIDO NUEVO AL DUEÑO (A3) ───────────────────────────────────────\n  // Hasta hoy el dueño solo se enteraba si abría la pantalla o tiraba del dedo para refrescar: con\n  // la app en segundo plano, un pedido entraba y nadie lo veía. En comida rápida eso es el cuello de\n  // botella de todo el flujo.\n  //  · Se consulta cada 30 s MIENTRAS LA PANTALLA ESTÁ ABIERTA (no en segundo plano: eso exige\n  //    notificaciones push, que son otro trabajo).\n  //  · Se guardan los ids ya vistos y se avisa SOLO de los que aparecen nuevos. Si no, cada consulta\n  //    avisaría de los mismos pedidos y el aviso dejaría de significar nada.\n  //  · El aviso **no** lo damos al abrir la pantalla por primera vez: los pedidos que ya estaban no\n  //    son «nuevos», y avisar de ellos convertiría esto en ruido.\n  const idsVistos = useRef<Set<string> | null>(null);\n  const [pedidosNuevos, setPedidosNuevos] = useState(0);\n\n  const buildQs = useCallback((pg: number): Record<string, string> => {\n    const qs: Record<string, string> = { as: role, page: String(pg), limit: String(PAGE_SIZE) };\n    if (stateFilter) qs.state = stateFilter;\n    return qs;\n  }, [role, stateFilter]);\n\n  const apply = useCallback((r: FoodOrdersPage) => {\n    setOrders(r.items);\n    setTotal(r.total);\n    setPage(r.page);\n    setPageSize(r.limit);\n    setHasMore(r.hasMore);\n    setLoadMoreError(false);\n  }, []);\n\n  /** Primera página (montaje / cambio de filtro): sin datos stale. */\n  const loadFirst = useCallback(async () => {\n    const id = ++reqId.current;\n    setLoading(true);\n    setError(null);\n    setOrders([]);\n    setLoadMoreError(false);\n    try {\n      const r = await foodApi.myOrders(role, buildQs(1));\n      if (id !== reqId.current) return;\n      apply(r);\n    } catch {\n      if (id !== reqId.current) return;\n      setError('No pudimos cargar los pedidos. Revisa tu conexión e inténtalo de nuevo.');\n      setOrders([]);\n      setTotal(0);\n      setHasMore(false);\n    } finally {\n      if (id === reqId.current) setLoading(false);\n    }\n  }, [buildQs, role, apply]);\n\n  /** Pull-to-refresh: conserva la lista visible. */\n  const refresh = useCallback(async () => {\n    const id = reqId.current;\n    setRefreshing(true);\n    try {\n      const r = await foodApi.myOrders(role, buildQs(1));\n      if (id !== reqId.current) return;\n      apply(r);\n      setError(null);\n    } catch {\n      // refresco fallido: se conserva la lista\n    } finally {\n      if (id === reqId.current) setRefreshing(false);\n    }\n  }, [buildQs, role, apply]);\n\n  /** Infinite scroll: página siguiente al final. */\n  const loadMore = useCallback(async () => {\n    if (loading || refreshing || loadingMore || !hasMore) return;\n    const id = reqId.current;\n    const next = page + 1;\n    setLoadingMore(true);\n    setLoadMoreError(false);\n    try {\n      const r = await foodApi.myOrders(role, buildQs(next));\n      if (id !== reqId.current) return;\n      setOrders((prev) => [...prev, ...r.items]);\n      setTotal(r.total);\n      setPage(r.page);\n      setPageSize(r.limit);\n      setHasMore(r.hasMore);\n    } catch {\n      if (id !== reqId.current) return;\n      setLoadMoreError(true);\n    } finally {\n      if (id === reqId.current) setLoadingMore(false);\n    }\n  }, [loading, refreshing, loadingMore, hasMore, page, buildQs, role]);\n\n  useEffect(() => { loadFirst(); }, [loadFirst]);\n\n  // ── El aviso de pedido nuevo (A3), en marcha ─────────────────────────────────\n  useEffect(() => {\n    // Solo para el DUEÑO: al cliente no le llegan pedidos, le salen (y avisarle de «pedidos nuevos»\n    // sería avisarle de los suyos propios).\n    if (role !== 'owner') return;\n    let parado = false;\n    const mirar = async () => {\n      try {\n        const r = await foodApi.myOrders('owner', { page: '1', limit: String(PAGE_SIZE), ...(stateFilter ? { state: stateFilter } : {}) });\n        if (parado) return;\n        const ids = new Set((r.items ?? []).map((o) => o.id));\n        if (idsVistos.current) {\n          const nuevos = [...ids].filter((id) => !idsVistos.current!.has(id));\n          if (nuevos.length > 0) {\n            setPedidosNuevos((n) => n + nuevos.length);\n            // Se avisa con el nombre del restaurante y el importe: lo que el dueño necesita para\n            // decidir si corre a la cocina, no un «tienes un pedido» genérico.\n            const primero = (r.items ?? []).find((o) => nuevos.includes(o.id));\n            Alert.alert(\n              nuevos.length === 1 ? '🛎 Pedido nuevo' : `🛎 ${nuevos.length} pedidos nuevos`,\n              primero ? `${primero.restaurantName ?? 'Tu restaurante'} · ${formatXAF(primero.totalXaf)}\\n${(primero.items ?? []).map((i) => `${i.qty} × ${i.name}`).join(', ')}` : '',\n              [{ text: 'Ver ahora', onPress: () => { setPedidosNuevos(0); void loadFirst(); } }, { text: 'Luego', style: 'cancel' }],\n            );\n          }\n        }\n        idsVistos.current = ids;\n      } catch { /* sin conexión: se reintenta en la siguiente vuelta, sin molestar */ }\n    };\n    void mirar();                                   // la primera vuelta solo aprende qué hay\n    const t = setInterval(mirar, 30_000);\n    return () => { parado = true; clearInterval(t); };\n  }, [role, stateFilter, loadFirst]);\n\n  /** Ejecuta una transición tras confirmación del usuario. */\n  const act = (o: FoodOrder, nextStatus: string) => {\n    if (busyRef.current) return;\n    const label = STATUS[nextStatus]?.label ?? nextStatus;\n    Alert.alert('Confirmar acción', `¿Marcar el pedido como \"${label}\"?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: 'Sí, continuar', onPress: () => doAct(o.id, nextStatus) },\n    ]);\n  };\n\n  /**\n   * Cancelar/rechazar, con confirmación y avisando de lo que NO se deshace.\n   *\n   * El mensaje es distinto según quién cancela, porque la consecuencia es distinta: al cliente hay\n   * que decirle que el pedido no se hará; al dueño, que el cliente se quedará sin él. Y si el pedido\n   * venía pagado por Billing, se avisa de que la factura queda abierta para que el admin la rechace\n   * — es un fleco conocido (toca el módulo de pagos) y es mejor decirlo que callarlo.\n   */\n  const cancelar = (o: FoodOrder) => {\n    if (busyRef.current) return;\n    const conBilling = o.paymentMethod === 'billing';\n    const esDueno = role === 'owner';\n    Alert.alert(\n      esDueno ? 'Rechazar pedido' : 'Cancelar pedido',\n      (esDueno\n        ? 'El cliente se quedará sin este pedido. Se le avisará.'\n        : 'El restaurante dejará de prepararlo. Si ya había empezado, habla con él.')\n      + (conBilling ? '\\n\\nEl pago era por Billing: la factura queda abierta y administración tendrá que rechazarla.' : ''),\n      [\n        { text: 'No cancelar', style: 'cancel' },\n        { text: esDueno ? 'Sí, rechazar' : 'Sí, cancelar', style: 'destructive', onPress: () => doAct(o.id, 'cancelled') },\n      ],\n    );\n  };\n\n  const doAct = async (id: string, nextStatus: string) => {    if (busyRef.current) return;\n    busyRef.current = true;\n    setBusyOrderId(id);\n    try {\n      await foodApi.updateStatus(id, nextStatus, role);\n      await refresh();\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo actualizar el pedido');\n    } finally {\n      busyRef.current = false;\n      setBusyOrderId(null);\n    }\n  };\n\n  const openAssign = async (o: FoodOrder) => {\n    setAssignOrder(o);\n    setRidersLoading(true);\n    setRiders([]);\n    try {\n      setRiders(await foodApi.activeRiders());\n    } catch { /* empty state */ }\n    finally { setRidersLoading(false); }\n  };\n\n  const assignRider = async (rider: FoodRider) => {\n    if (!assignOrder || busyRef.current) return;\n    busyRef.current = true;\n    setBusyOrderId(assignOrder.id);\n    try {\n      const res = await foodApi.assignRider(assignOrder.id, rider.id);\n      setAssignOrder(null);\n      Alert.alert('Repartidor asignado', res.message);\n      await refresh();\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo asignar el repartidor');\n    } finally {\n      busyRef.current = false;\n      setBusyOrderId(null);\n    }\n  };\n\n  const listData: FoodOrder[] = useMemo(() => {\n    if (loading && !orders.length) return SKELETONS.map((i) => ({ id: `__sk_${i}` } as FoodOrder));\n    return orders;\n  }, [loading, orders]);\n  const isSkeleton = (id: string) => id.startsWith('__sk_');\n\n  const s = styles(colors);\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Header — del kit desde el 24/09/2026 (piloto de la unificación de las 21 cabeceras).\n          Las dos claves locales `header`/`headerTitle` se retiran: son 5 literales menos en la\n          guardia y, sobre todo, ya no hay 21 copias de la misma fila que mantener a la vez. */}\n      <ScreenHeader\n        titulo={isOwner ? 'Pedidos recibidos' : 'Mis pedidos'}\n        alVolver={() => router.back()}\n      />\n\n      <FlatList\n        data={listData}\n        keyExtractor={(item) => item.id}\n        contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e32 + insets.bottom }}\n        refreshing={refreshing}\n        onRefresh={refresh}\n        onEndReached={loadMore}\n        onEndReachedThreshold={0.4}\n        keyboardShouldPersistTaps=\"handled\"\n        ListHeaderComponent={\n          <View>\n            {/* Filtros por estado (server-side: la paginación sigue siendo correcta) */}\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, paddingVertical: espaciado.e12, flexWrap: 'wrap' }}>\n              {STATE_CHIPS.map((c) => (\n                <Chip key={c.key || 'all'} label={c.label} active={stateFilter === c.key}\n                  onPress={() => setStateFilter(stateFilter === c.key ? '' : c.key)} />\n              ))}\n            </View>\n            {!error && (\n              <Text style={s.resultsLabel}>\n                {loading ? 'Cargando…' : `${total} pedido${total === 1 ? '' : 's'}`}\n              </Text>\n            )}\n          </View>\n        }\n        ListEmptyComponent={\n          error ? (\n            <View style={s_center.wrap}>\n              <Text style={{ fontSize: 38, marginBottom: espaciado.e8 }}>📡</Text>\n              <Text style={[s_center.title, { color: colors.textPrimary }]}>Algo salió mal</Text>\n              <Text style={[s_center.sub, { color: colors.textSecondary }]}>{error}</Text>\n              <Pressable onPress={loadFirst} accessibilityRole=\"button\" style={s_center.btnPrimary}>\n                <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n              </Pressable>\n            </View>\n          ) : loading ? null : stateFilter !== '' ? (\n            <View style={s_center.wrap}>\n              <Text style={{ fontSize: 40, marginBottom: espaciado.e10 }}>📭</Text>\n              <Text style={[s_center.title, { color: colors.textPrimary }]}>Sin pedidos en este estado</Text>\n              <Text style={[s_center.sub, { color: colors.textSecondary }]}>Prueba con otro filtro.</Text>\n              <Pressable onPress={() => setStateFilter('')} accessibilityRole=\"button\" style={s_center.btnGhost}>\n                <Text style={{ color: ACCENT, fontWeight: '800', fontSize: tipografia.body }}>Ver todos</Text>\n              </Pressable>\n            </View>\n          ) : (\n            <View style={s_center.wrap}>\n              <Text style={{ fontSize: 40, marginBottom: espaciado.e10 }}>{isOwner ? '🍽️' : '🛒'}</Text>\n              <Text style={[s_center.title, { color: colors.textPrimary }]}>\n                {isOwner ? 'Aún no recibes pedidos' : 'Todavía no has pedido'}\n              </Text>\n              <Text style={[s_center.sub, { color: colors.textSecondary }]}>\n                {isOwner\n                  ? 'Cuando alguien pida en tu restaurante aparecerá aquí.'\n                  : 'Elige un restaurante y pide para recoger o recibir en casa.'}\n              </Text>\n              <Pressable\n                onPress={() => router.push((isOwner ? '/food-owner' : '/food') as any)}\n                accessibilityRole=\"button\"\n                style={s_center.btnPrimary}\n              >\n                <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>\n                  {isOwner ? 'Ir a mi restaurante' : 'Ver restaurantes'}\n                </Text>\n              </Pressable>\n            </View>\n          )\n        }\n        ListFooterComponent={\n          loadingMore ? (\n            <View style={s.footerNote}><ActivityIndicator size=\"small\" color={colors.primary} /></View>\n          ) : loadMoreError ? (\n            <Pressable onPress={loadMore} style={s.footerNote} accessibilityRole=\"button\">\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700' }}>No se pudieron cargar más pedidos · Reintentar</Text>\n            </Pressable>\n          ) : !hasMore && total > pageSize ? (\n            <View style={s.footerNote}><Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Fin de los pedidos</Text></View>\n          ) : null\n        }\n        renderItem={({ item }) =>\n          isSkeleton(item.id) ? (\n            <OrdersSkeleton key={item.id} colors={colors} />\n          ) : (\n            <OrderCard\n              key={item.id}\n              order={item}\n              role={role}\n              busy={busyOrderId === item.id}\n              onAct={(next) => act(item, next)}\n              onCancel={() => cancelar(item)}\n              onAssign={() => openAssign(item)}\n              onReview={() => setReviewOrder(item)}\n            />\n          )\n        }\n      />\n\n      {/* Modal de valoración (5 estrellas, Android + iOS) */}\n      {reviewOrder && (\n        <ReviewModal\n          key={reviewOrder.id}\n          order={reviewOrder}\n          onClose={() => setReviewOrder(null)}\n          onDone={async (rating) => {\n            try {\n              const r = await foodApi.review(reviewOrder.id, rating);\n              setReviewOrder(null);\n              Alert.alert('Valoración', r.message);\n              await refresh();\n            } catch (e) {\n              Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo valorar el pedido');\n            }\n          }}\n        />\n      )}\n\n      {/* Modal de asignación de repartidor (lista, seguro en Android) */}\n      {assignOrder && (\n        /*\n          Era un `<Modal>` a mano que repetía lo del `Sheet` (fondo, cierre al tocar fuera, foco\n          atrapado) y además no anunciaba el título como cabecera. El contenido es el mismo.\n        */\n        <Sheet\n          visible\n          position=\"bottom\"\n          title=\"Asignar repartidor\"\n          subtitle={`${assignOrder.restaurantName} · ${formatXAF(assignOrder.totalXaf)} · a domicilio`}\n          onClose={() => setAssignOrder(null)}\n        >\n          {/* La lista lleva su propio marginBottom: se envuelve para que el gap del Sheet no lo doble. */}\n          <View>\n        {ridersLoading ? (\n          <ActivityIndicator style={{ paddingVertical: espaciado.e24 }} color={colors.primary} />\n        ) : riders.length === 0 ? (\n          <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, paddingVertical: espaciado.e18, textAlign: 'center' }}>\n            No hay repartidores activos todavía. Aprueba uno desde el panel de administración.\n          </Text>\n        ) : (\n          riders.map((r) => (\n            <Pressable\n              key={r.id}\n              onPress={() => assignRider(r)}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Asignar a ${r.fullName}`}\n              style={[s.riderRow, { backgroundColor: colors.surface, borderColor: colors.border }]}\n            >\n              <View style={{ flex: 1 }}>\n                <Text style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>{r.fullName}</Text>\n                <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>\n                  {r.vehicleType === 'moto' ? '🛵 Moto' : r.vehicleType === 'bici' ? '🚲 Bici' : '🚗 Coche'}\n                  {r.zone ? ` · ${r.zone}` : ''} · {r.deliveriesCount} entregas\n                </Text>\n              </View>\n              <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>Asignar →</Text>\n            </Pressable>\n          ))\n        )}\n\n          </View>\n          <Pressable onPress={() => setAssignOrder(null)} accessibilityRole=\"button\" style={{ alignSelf: 'center', paddingVertical: espaciado.e10 }}>\n            <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.body }}>Cancelar</Text>\n          </Pressable>\n        </Sheet>\n      )}\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\nfunction Chip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityLabel={label} accessibilityState={{ selected: active }}\n      style={[s_chip.base, { backgroundColor: active ? ACCENT : colors.surface, borderColor: active ? ACCENT : colors.border }]}>\n      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: active ? brand.white : colors.textPrimary }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nfunction OrderCard({ order: o, role, busy, onAct, onAssign, onReview, onCancel }: {\n  order: FoodOrder; role: Role; busy: boolean;\n  onAct: (nextStatus: string) => void; onAssign: () => void; onReview: () => void; onCancel: () => void;\n}) {\n  const { colors } = useTheme();\n  const isOwner = role === 'owner';\n  const st = STATUS[o.status] ?? { label: o.status, color: colors.textSecondary };\n  const cancelled = o.status === 'cancelled';\n  const idx = cancelled ? -1 : FLOW.indexOf(o.status as (typeof FLOW)[number]);\n  const billingPending = o.paymentMethod === 'billing' && o.billingStatus !== 'approved';\n  const nextAction = (isOwner ? OWNER_NEXT : USER_NEXT)[o.status] ?? null;\n  // Con Billing sin aprobar el dueño NO puede confirmar (gate backend + UI).\n  const showConfirm = !(isOwner && nextAction === 'confirmed' && billingPending);\n  return (\n    <View style={[s_card.card, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n      {/* Cabecera: restaurante + estado + fecha/hora */}\n      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e8 }}>\n        <Text numberOfLines={1} style={{ flex: 1, fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>{o.restaurantName}</Text>\n        <View style={{ backgroundColor: alpha(st.color, 0.12), paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: radios.sm }}>\n          <Text style={{ fontSize: tipografia.micro, fontWeight: '800', color: st.color }}>{st.label}</Text>\n        </View>\n      </View>\n      <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e2 }}>{formatDateTime(o.createdAt)}</Text>\n\n      {/* Líneas */}\n      {o.items.map((it, i) => (\n        <Text key={`${o.id}-${it.itemId}-${i}`} style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e2 }}>{it.qty} × {it.name}</Text>\n      ))}\n      <Text style={{ fontSize: tipografia.body, fontWeight: '900', color: ACCENT, marginTop: espaciado.e4 }}>\n        {formatXAF(o.totalXaf)} · {o.pickupType === 'delivery' ? 'a domicilio' : 'recoger'} · {o.paymentMethod === 'cash' ? 'efectivo' : 'Billing'}\n      </Text>\n\n      {/* Pago Billing */}\n      {billingPending && (\n        <Text style={{ fontSize: tipografia.micro, fontWeight: '700', color: brand.warning, marginTop: espaciado.e4 }}>\n          ⏳ Comprobante de pago pendiente (2–24 h){isOwner ? ' · se confirma al aprobarse' : ''}\n        </Text>\n      )}\n      {o.paymentMethod === 'billing' && o.billingStatus === 'approved' && (\n        <Text style={{ fontSize: tipografia.micro, fontWeight: '700', color: brand.success, marginTop: espaciado.e4 }}>✓ Pago Billing aprobado</Text>\n      )}\n\n      {/* ── PEDIDO PROGRAMADO ────────────────────────────────────────────────────\n          Se pidió con el local cerrado: se entregará a la hora que abre. Sin esto, el cliente ve un\n          pedido «en curso» que nadie está cocinando y el dueño cree que llega tarde. */}\n      {o.scheduledFor ? (\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e6, backgroundColor: alpha('#6366F1', 0.12), borderRadius: radios.sm, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e5 }}>\n          <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: '#6366F1' }}>\n            🕐 Programado para {formatDateTime(o.scheduledFor)}\n          </Text>\n        </View>\n      ) : null}\n\n      {/* ── EL DESGLOSE DEL DINERO (dueño Y cliente) ─────────────────────────────\n          Decisión del dueño (2026-09-12): «la comisión se muestra a ambos».\n          Las dos comisiones van en líneas SEPARADAS a propósito: es lo que hace Meituan y lo que\n          evita que el comerciante crea que «le quitan el 20%» cuando la mitad es el reparto.\n\n          Pero el MISMO número significa cosas distintas según quién lo lea, y por eso el texto\n          cambia: las comisiones salen del restaurante (restaurantNet = bruto − comisiones, ver\n          food-fees.ts), NO del cliente — el cliente paga el bruto. Mostrar «− 800 XAF» a un\n          cliente sin aclararlo le haría creer que se le cobran 800 de más. De ahí que para el\n          cliente las cifras vayan sin signo menos y con la explicación debajo.\n\n          El neto del restaurante («Te queda») sigue siendo SOLO del dueño: es su margen comercial,\n          no hay razón para que un cliente lo vea, y la decisión fue sobre la comisión. */}\n      {o.platformFeeXaf !== null && o.riderFeeXaf !== null ? (\n        <View style={{ marginTop: espaciado.e8, borderTopWidth: 1, borderTopColor: colors.border, paddingTop: espaciado.e6 }}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>Comisión de la plataforma</Text>\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>\n              {isOwner ? '− ' : ''}{formatXAF(o.platformFeeXaf)}\n            </Text>\n          </View>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>Comisión del reparto</Text>\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>\n              {isOwner ? '− ' : ''}{formatXAF(o.riderFeeXaf)}\n            </Text>\n          </View>\n          {isOwner ? (\n            <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: espaciado.e3 }}>\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textPrimary }}>Te queda</Text>\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '900', color: brand.success }}>\n                {o.restaurantNetXaf !== null ? formatXAF(o.restaurantNetXaf) : '—'}\n              </Text>\n            </View>\n          ) : (\n            <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e4, lineHeight: 14 }}>\n              Estas comisiones las paga el restaurante, no tú: ya van incluidas en el precio que pagaste.\n            </Text>\n          )}\n        </View>\n      ) : null}\n\n      {/* Dirección y nota (el dueño reparte sin ciegas) */}\n      {o.pickupType === 'delivery' && o.deliveryAddress ? (\n        <Text numberOfLines={2} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e4 }}>📍 {o.deliveryAddress}</Text>\n      ) : null}\n      {o.note ? (\n        <Text numberOfLines={2} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>📝 {o.note}</Text>\n      ) : null}\n\n      {/* ── PUNTO DE ENCUENTRO ────────────────────────────────────────────────────\n          Lo anota el REPARTIDOR al llegar y aquí lo ve el CLIENTE: es la respuesta al hotel, las\n          viviendas sociales o el portal sin número, donde la dirección no basta para encontrarse.\n          Se muestra en cuanto existe, sin tocar nada: el repartidor ya avisó por SMS también. */}\n      {o.meetingNote ? (\n        <View style={{ marginTop: espaciado.e6, borderRadius: 10, borderWidth: 1, padding: espaciado.e10, borderColor: alpha(colors.success, 0.45), backgroundColor: alpha(colors.success, 0.10) }}>\n          <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.success }}>🤝 El repartidor te espera aquí</Text>\n          <Text style={{ fontSize: tipografia.caption, color: colors.textPrimary, marginTop: espaciado.e3, lineHeight: 16 }}>{o.meetingNote}</Text>\n          {typeof o.meetingLat === 'number' && typeof o.meetingLng === 'number' ? (\n            <Pressable\n              onPress={() => abrirMapa(o.meetingLat as number, o.meetingLng as number, o.meetingNote ?? null)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Ver el punto de encuentro en el mapa\"\n              style={{ marginTop: espaciado.e6, alignSelf: 'flex-start' }}\n            >\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>Ver en el mapa</Text>\n            </Pressable>\n          ) : null}\n        </View>\n      ) : null}\n\n      {/* Timeline (o estado cerrado) */}\n      {cancelled ? (\n        <View style={[s_card.cancelledBox, { backgroundColor: alpha(brand.neutral, 0.1) }]}>\n          <Text style={{ color: brand.neutral, fontSize: tipografia.caption, fontWeight: '800' }}>Pedido cerrado · cancelado</Text>\n        </View>\n      ) : (\n        <View\n          accessibilityRole=\"progressbar\"\n          accessibilityLabel={`Pedido en \"${st.label}\", paso ${Math.max(idx, 0) + 1} de ${FLOW.length}`}\n          style={{ marginTop: espaciado.e10 }}\n        >\n          <View style={{ flexDirection: 'row', alignItems: 'center' }}>\n            {FLOW.map((stName, i) => {\n              const done = i <= idx;\n              return (\n                <View key={stName} style={{ flex: 1, alignItems: 'center' }}>\n                  <View style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: done ? ACCENT : colors.border }} />\n                  {i < FLOW.length - 1 && <View style={{ height: 2, flex: 1, backgroundColor: i < idx ? ACCENT : colors.border, marginHorizontal: -10 }} />}\n                </View>\n              );\n            })}\n          </View>\n          <View style={{ flexDirection: 'row', marginTop: espaciado.e4 }}>\n            {FLOW.map((stName) => {\n              const pos = FLOW.indexOf(stName);\n              return (\n                <Text key={stName} numberOfLines={1}\n                  style={{ flex: 1, textAlign: 'center', fontSize: 8, fontWeight: pos <= idx ? '800' : '600', color: pos <= idx ? ACCENT : colors.textSecondary }}>\n                  {STATUS[stName].label}\n                </Text>\n              );\n            })}\n          </View>\n        </View>\n      )}\n\n      {/* ETA de cocina (041): solo en pedidos en curso y si algún plato declaró\n          su tiempo. `estPrepMinutes` es el plato MÁS LENTO; los pedidos creados\n          antes de la migración vienen null y no muestran nada. */}\n      {!cancelled && o.status !== 'delivered' && typeof o.estPrepMinutes === 'number' && o.estPrepMinutes > 0 && (\n        <View style={[s_card.etaBox, { backgroundColor: alpha(ACCENT, 0.08), borderColor: alpha(ACCENT, 0.25) }]}>\n          <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>\n            ⏱️ Tiempo de cocina estimado: ~{o.estPrepMinutes} min\n          </Text>\n          <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e2 }}>\n            {o.status === 'placed'\n              ? 'Se cuenta desde que el restaurante confirme tu pedido.'\n              : 'A contar desde que el restaurante empieza a preparar.'}\n          </Text>\n        </View>\n      )}\n\n      {/* Acciones */}\n      {busy ? (\n        <View style={{ alignItems: 'center', paddingVertical: espaciado.e12 }}>\n          <ActivityIndicator size=\"small\" color={colors.primary} />\n        </View>\n      ) : (\n        <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12, flexWrap: 'wrap' }}>\n          {isOwner && o.pickupType === 'delivery' && !o.riderId && ['placed', 'confirmed'].includes(o.status) && (\n            <GhostButton title=\"Asignar repartidor\" accessibilityLabel=\"Asignar repartidor a este pedido\"\n              accessibilityHint=\"Abre la lista de repartidores disponibles\" onPress={onAssign} />\n          )}\n          {nextAction && showConfirm && (\n            <GhostButton\n              title={nextAction === 'delivered' ? 'Marcar entregado' : `Avanzar a \"${STATUS[nextAction].label}\"`}\n              accessibilityLabel={`Marcar pedido como ${STATUS[nextAction].label}`}\n              onPress={() => onAct(nextAction)}\n            />\n          )}\n          {!isOwner && o.status === 'ready' && (\n            <GhostButton title=\"He recibido mi pedido\" accessibilityLabel=\"Marcar pedido como recibido\" onPress={() => onAct('delivered')} />\n          )}\n          {!isOwner && o.status === 'delivered' && !o.reviewed && (\n            <GhostButton title=\"Valorar\" accessibilityLabel=\"Valorar este pedido\" onPress={onReview} />\n          )}\n          {!isOwner && o.status === 'delivered' && o.reviewed && (\n            <Text style={{ color: brand.success, fontSize: tipografia.caption, fontWeight: '700', alignSelf: 'center' }}>✓ Valoración enviada</Text>\n          )}\n          {/* ── RECHAZAR / CANCELAR ─────────────────────────────────────────────────\n              Es la salida que faltaba en todo el flujo: hasta hoy `cancelled` era inalcanzable y un\n              restaurante con un pedido que no puede servir (local cerrado, plato agotado) se quedaba\n              con él para siempre. Las reglas las decide el SERVIDOR y son distintas por rol:\n                · el cliente cancela mientras no haya empezado la cocina (placed | confirmed);\n                · el dueño cancela en cualquier estado no entregado (incluido preparing).\n              La app solo ofrece el botón donde el servidor lo va a aceptar: prometer un botón que\n              responde 400 es peor que no tenerlo. */}\n          {puedeCancelar(isOwner, o.status) ? (\n            <GhostButton\n              title={isOwner ? 'Rechazar pedido' : 'Cancelar pedido'}\n              accessibilityLabel={isOwner ? 'Rechazar este pedido' : 'Cancelar este pedido'}\n              accessibilityHint=\"Se pide confirmación antes de cancelarlo\"\n              onPress={onCancel}\n            />\n          ) : null}\n        </View>\n      )}\n    </View>\n  );\n}\n\nfunction ReviewModal({ order, onClose, onDone }: {\n  order: FoodOrder; onClose: () => void; onDone: (rating: number) => Promise<void>;\n}) {\n  const { colors } = useTheme();\n  const [rating, setRating] = useState(0);\n  const [busy, setBusy] = useState(false);\n  const busyRef = useRef(false);\n\n  const submit = async () => {\n    if (rating < 1 || rating > 5 || busyRef.current) return;\n    busyRef.current = true;\n    setBusy(true);\n    await onDone(rating);\n    busyRef.current = false;\n    setBusy(false);\n  };\n\n  return (\n    /*\n      Valorar tu pedido. Era un `<Modal>` a mano que repetía lo del `Sheet` (fondo, cierre al\n      tocar fuera, foco atrapado) y no anunciaba el título como cabecera. El nombre del\n      restaurante pasa al subtítulo.\n    */\n    <Sheet\n      visible\n      position=\"center\"\n      busy={busy}\n      title=\"Valorar tu pedido\"\n      subtitle={order.restaurantName ?? undefined}\n      onClose={onClose}\n    >\n      <View style={{ flexDirection: 'row', justifyContent: 'center', gap: espaciado.e6 }}>\n        {[1, 2, 3, 4, 5].map((n) => (\n          <Pressable key={n} onPress={() => setRating(n)} hitSlop={4}\n            accessibilityRole=\"button\" accessibilityLabel={`${n} de 5 estrellas`}\n            accessibilityState={{ selected: rating >= n }}>\n            <Star size={32} color={n <= rating ? brand.warning : colors.border} fill={n <= rating ? brand.warning : 'transparent'} />\n          </Pressable>\n        ))}\n      </View>\n      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary, textAlign: 'center', marginTop: espaciado.e10, minHeight: 18 }}>\n        {rating === 0 ? 'Toca las estrellas para puntuar' : `${rating} de 5`}\n      </Text>\n      <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e16 }}>\n        <Pressable onPress={onClose} disabled={busy} accessibilityRole=\"button\"\n          style={[s_rm.btnGhost, { borderColor: colors.border }]}>\n          <Text style={{ color: colors.textSecondary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\n        </Pressable>\n        <Pressable onPress={submit} disabled={busy || rating === 0} accessibilityRole=\"button\"\n          style={[s_rm.btnPrimary, { opacity: busy || rating === 0 ? 0.5 : 1 }]}>\n          {busy\n            ? <ActivityIndicator size=\"small\" color={brand.white} />\n            : <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Enviar valoración</Text>}\n        </Pressable>\n\n          </View>\n    </Sheet>\n  );\n}\n\nfunction OrdersSkeleton({ colors }: { colors: ReturnType<typeof useTheme>['colors'] }) {\n  return (\n    <View style={[s_sk.card, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n      <View style={{ height: 13, borderRadius: 4, backgroundColor: colors.border, width: '55%' }} />\n      <View style={{ height: 10, borderRadius: 4, backgroundColor: colors.border, width: '30%', marginTop: espaciado.e8 }} />\n      <View style={{ height: 10, borderRadius: 4, backgroundColor: colors.border, width: '75%', marginTop: espaciado.e6 }} />\n      <View style={{ height: 13, borderRadius: 4, backgroundColor: colors.border, width: '40%', marginTop: espaciado.e10 }} />\n    </View>\n  );\n}\n\nconst s_chip = StyleSheet.create({\n  base: { paddingHorizontal: espaciado.e13, paddingVertical: espaciado.e7, borderRadius: radios.lg, borderWidth: 1 },\n});\n\nconst s_card = StyleSheet.create({\n  card: { borderRadius: 14, padding: espaciado.e14, marginBottom: espaciado.e12, borderWidth: 1 },\n  cancelledBox: { borderRadius: 10, padding: espaciado.e8, marginTop: espaciado.e10, alignItems: 'center' },\n  etaBox: { borderRadius: 10, borderWidth: 1, padding: espaciado.e9, marginTop: espaciado.e10 },\n});\n\nconst s_rm = StyleSheet.create({\n  btnGhost: { flex: 1, borderRadius: radios.md, borderWidth: 1, paddingVertical: espaciado.e12, alignItems: 'center' },\n  btnPrimary: { flex: 1, borderRadius: radios.md, backgroundColor: ACCENT, paddingVertical: espaciado.e12, alignItems: 'center' },\n});\n\nconst s_sk = StyleSheet.create({\n  card: { borderRadius: 14, borderWidth: 1, padding: espaciado.e14, marginBottom: espaciado.e12 },\n});\n\nconst s_center = StyleSheet.create({\n  wrap: { alignItems: 'center', paddingTop: 48, paddingHorizontal: espaciado.e28 },\n  title: { fontSize: 15, fontWeight: '800', textAlign: 'center' },\n  sub: { fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 },\n  btnPrimary: { marginTop: espaciado.e18, backgroundColor: ACCENT, paddingHorizontal: espaciado.e24, paddingVertical: espaciado.e11, borderRadius: 22 },\n  btnGhost: { marginTop: espaciado.e18, paddingHorizontal: espaciado.e24, paddingVertical: espaciado.e11, borderRadius: 22, borderWidth: 1, borderColor: ACCENT },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  resultsLabel: { fontSize: tipografia.caption, fontWeight: '700', color: c.textSecondary, marginBottom: espaciado.e10 },\n  footerNote: { paddingVertical: espaciado.e16, alignItems: 'center' },\n  modalWrap: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' },\n  modalCard: { borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: espaciado.e18, maxHeight: '75%' },\n  modalTitle: { fontSize: tipografia.subtitle, fontWeight: '900', marginBottom: espaciado.e4 },\n  riderRow: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, borderWidth: 1, padding: espaciado.e12, marginBottom: espaciado.e8 },\n});\n","/**\n * Llevar a alguien a un punto en el mapa, desde cualquier pantalla.\n *\n * ── POR QUÉ EXISTE ──────────────────────────────────────────────────────────────\n * La dirección de entrega es TEXTO LIBRE y en la base hay cosas como «Aeropuerto». Con eso, ni el\n * repartidor puede navegar ni el cliente puede enseñar dónde está. Con coordenadas se abre la app de\n * mapas EN EL PUNTO (`geo:` en Android, `maps:` en iOS); sin ellas se busca el texto, que es peor\n * («Aeropuerto» puede devolver media ciudad) pero sigue siendo mejor que nada.\n *\n * Si no hay ninguna app que atienda el esquema nativo, se cae al navegador con el mismo destino: en un\n * móvil recién instalado eso es lo normal, y un botón que no hace nada es peor que un enlace.\n */\nimport { Alert, Linking, Platform } from 'react-native';\n\nexport function abrirMapa(lat: number | null, lng: number | null, direccion: string | null) {\n  const texto = (direccion ?? '').trim();\n  const hayPin = typeof lat === 'number' && typeof lng === 'number' && Number.isFinite(lat) && Number.isFinite(lng);\n  const web = hayPin\n    ? `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`\n    : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(texto)}`;\n  if (!hayPin && !texto) {\n    Alert.alert('Ubicación', 'Este pedido no tiene ni dirección ni ubicación a la que llevar.');\n    return;\n  }\n  const nativo = hayPin\n    ? (Platform.OS === 'ios'\n      ? `maps:0,0?q=${lat},${lng}`\n      : `geo:${lat},${lng}?q=${lat},${lng}${texto ? `(${encodeURIComponent(texto)})` : ''}`)\n    : null;\n  if (!nativo) { Linking.openURL(web).catch(() => Alert.alert('Mapa', 'No se pudo abrir el mapa.')); return; }\n  Linking.openURL(nativo).catch(() => {\n    Linking.openURL(web).catch(() => Alert.alert('Mapa', 'No hay ninguna app de mapas instalada.'));\n  });\n}\n","/**\n * FoodOwnerScreen — Mi restaurante: requisitos (KYC + datos + aprobación admin),\n * alta/edición con FOTO real (multipart → MinIO food-photos), añadir ítems al\n * menú (moderación), gestión de \"Mi menú\" (ocultar/mostrar activos y eliminar).\n *\n * Auditorías senior (2026-09-02):\n *  · Carga skeleton / error + Reintentar (nunca requisitos ✗ falsos por red).\n *  · Foto: picker + upload multipart (máx 8 MB) con preview y quitar.\n *  · Ciudad de las 24 de GQ (modal); teléfono validado +240 y normalizado;\n *    horario validado EN BLUR (no doble cálculo por tecla); precio entero > 0\n *    con preview formatXAF en vivo.\n *  · busy por dominio (perfil / publicar / por ítem del menú) + busyRef.\n *  · Confirmación al editar un restaurante activo y antes de eliminar ítems.\n *  · KYC incompleto → ReqRow tocable con CTA a /driver-onboarding.\n *  · Guard de cambios sin guardar (back del header y back de Android).\n *  · KeyboardAvoidingView + SafeArea + a11y.\n * Ruta: /food-owner\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, BackHandler, Image as RNImage, KeyboardAvoidingView, Modal, Platform,\n  Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport * as ImagePicker from 'expo-image-picker';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { BadgeCheck, Camera, Eye, EyeOff, Plus, Trash2, X, XCircle } from 'lucide-react-native';\nimport { alpha, altura, espaciado, FormField, PrimaryButton, radios, ScreenHeader, Sheet, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { foodApi, FoodMenuItem, FoodOwnerMe, SPICE_LABEL, SPICE_ICON, SIDES_MAX, type SpiceLevel } from '../api/food';\nimport { formatXAF } from '../utils/formatHelpers';\nimport { foodHoursError } from '../utils/foodHours';\nimport {\n  SPICE_ORDER, ingredientsError, parseIngredients, sidesError, parseSides,\n  portionSizeError, prepMinutesError, parsePrepMinutes,\n} from '../utils/foodItemDetails';\nimport { looksLikeGqPhone, toGqMsisdn } from '../utils/phone';\nimport { CITIES } from '../constants/data';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst ACCENT = brand.primary; // A1: la acción avanza en azul\nconst MAX_PHOTO_MB = 8;\nconst CATS: Array<{ key: 'plato' | 'bebida' | 'postre'; label: string }> = [\n  { key: 'plato', label: '🍛 Plato' }, { key: 'bebida', label: '🥤 Bebida' }, { key: 'postre', label: '🍰 Postre' },\n];\n\nexport default function FoodOwnerScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [me, setMe] = useState<FoodOwnerMe | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const [name, setName] = useState('');\n  const [city, setCity] = useState('');\n  const [cityModal, setCityModal] = useState(false);\n  const [address, setAddress] = useState('');\n  const [phone, setPhone] = useState('');\n  const [phoneErr, setPhoneErr] = useState<string | null>(null);\n  const [hours, setHours] = useState('');\n  const [hoursErr, setHoursErr] = useState<string | null>(null);\n  const [desc, setDesc] = useState('');\n  const [photoUrl, setPhotoUrl] = useState<string | null>(null);\n  const [photoBusy, setPhotoBusy] = useState(false);\n  const [busyBiz, setBusyBiz] = useState(false);\n  const busyBizRef = useRef(false);\n\n  const [iName, setIName] = useState('');\n  const [iPrice, setIPrice] = useState('');\n  const [iPriceErr, setIPriceErr] = useState<string | null>(null);\n  const [iCat, setICat] = useState<'plato' | 'bebida' | 'postre'>('plato');\n  const [busyPub, setBusyPub] = useState(false);\n  const busyPubRef = useRef(false);\n\n  // ── Detalle del plato (migración 041). Todo OPCIONAL: el dueño puede publicar\n  //    solo nombre + precio, exactamente como antes. Se agrupa bajo un\n  //    desplegable \"Detalles (opcional)\" para no alargar el formulario base.\n  //    Errores en blur (no por tecla), igual que hace el horario arriba.\n  const [showDetails, setShowDetails] = useState(false);\n  const [iIngredients, setIIngredients] = useState('');\n  const [iIngredientsErr, setIIngredientsErr] = useState<string | null>(null);\n  const [iSpice, setISpice] = useState<SpiceLevel | null>(null);\n  const [iPortion, setIPortion] = useState('');\n  const [iPortionErr, setIPortionErr] = useState<string | null>(null);\n  const [iDrink, setIDrink] = useState(false);\n  const [iSides, setISides] = useState('');\n  const [iSidesErr, setISidesErr] = useState<string | null>(null);\n  const [iPrep, setIPrep] = useState('');\n  const [iPrepErr, setIPrepErr] = useState<string | null>(null);\n\n  // ── Foto del plato: se sube UNA VEZ y se queda ────────────────────────────────\n  // Cómo lo hacen las plataformas de comida (美团外卖): foto REAL del plato —JPG o PNG, por debajo\n  // de 2 MB, cuadrada y bien iluminada—; nada de dibujos, collages, marcas de agua ni fotos de\n  // banco. Y, sobre todo: la foto vive EN el plato. Se sube una vez, se guarda con él y se reutiliza\n  // siempre (menú del cliente, carrito, pedidos). Cambiar el nombre, el precio o los ingredientes\n  // NO la borra, y nadie tiene que volver a subirla cada día.\n  const [iPhoto, setIPhoto] = useState<string | null>(null);\n  const [iPhotoBusy, setIPhotoBusy] = useState(false);\n\n  const resetItemForm = useCallback(() => {\n    setIName(''); setIPrice(''); setIPriceErr(null);\n    setIIngredients(''); setIIngredientsErr(null);\n    setISpice(null); setIPortion(''); setIPortionErr(null);\n    setIDrink(false); setISides(''); setISidesErr(null);\n    setIPrep(''); setIPrepErr(null);\n    setIPhoto(null); setIPhotoBusy(false);\n    setShowDetails(false);\n  }, []);\n\n  const [busyMenuId, setBusyMenuId] = useState<string | null>(null);\n  const busyMenuRef = useRef(false);\n\n  // Snapshot de lo guardado → guard de cambios sin guardar.\n  const [saved, setSaved] = useState<{ name: string; city: string; address: string; phone: string; hours: string; desc: string; photoUrl: string | null } | null>(null);\n\n  const load = useCallback(async (mode: 'initial' | 'quiet' = 'initial') => {\n    if (mode === 'initial') { setLoading(true); setError(null); }\n    try {\n      const m = await foodApi.ownerMe();\n      setMe(m);\n      if (m.restaurant) {\n        const snap = {\n          name: m.restaurant.businessName,\n          city: m.restaurant.city,\n          address: m.restaurant.address ?? '',\n          phone: m.restaurant.phoneContact ?? '',\n          hours: m.restaurant.hours ?? '',\n          desc: m.restaurant.description ?? '',\n          photoUrl: m.restaurant.photoUrl ?? m.restaurant.photoKey ?? null,\n        };\n        setName(snap.name); setCity(snap.city); setAddress(snap.address); setPhone(snap.phone);\n        setHours(snap.hours); setDesc(snap.desc); setPhotoUrl(snap.photoUrl);\n        setHoursErr(null); setPhoneErr(null);\n        setSaved(snap);\n      }\n      setError(null);\n    } catch {\n      if (mode === 'initial') setError('No pudimos cargar tu restaurante. Revisa tu conexión e inténtalo de nuevo.');\n    } finally {\n      if (mode === 'initial') setLoading(false);\n    }\n  }, []);\n\n  // ── CARGA AL ABRIR (faltaba y dejaba la pantalla muerta) ─────────────────────\n  // Sin esta línea `loading` se queda en `true`, `me` en `null` y la pantalla se queda PARA\n  // SIEMPRE en `OwnerSkeleton` (que no pinta texto: por eso el volcado de pantalla solo traía la\n  // cabecera). Se veía en el móvil, no en `tsc`. Sus pantallas hermanas sí lo tienen\n  // (`food-rider.tsx`: `useEffect(() => { load(); }, [load])`).\n  useEffect(() => { void load('initial'); }, [load]);\n\n  const dirty = useMemo(() => {\n    if (!saved) return false;\n    return name !== saved.name || city !== saved.city || address !== saved.address || phone !== saved.phone\n      || hours !== saved.hours || desc !== saved.desc || (photoUrl ?? null) !== saved.photoUrl;\n  }, [saved, name, city, address, phone, hours, desc, photoUrl]);\n\n  const confirmLeave = useCallback(() => {\n    Alert.alert('Descartar cambios', 'Tienes cambios sin guardar en tu restaurante. ¿Descartarlos?', [\n      { text: 'Seguir editando', style: 'cancel' },\n      { text: 'Descartar', style: 'destructive', onPress: () => router.back() },\n    ]);\n  }, [router]);\n\n  // Back físico de Android mientras hay cambios sin guardar.\n  useEffect(() => {\n    if (!dirty) return;\n    const sub = BackHandler.addEventListener('hardwareBackPress', () => { confirmLeave(); return true; });\n    return () => sub.remove();\n  }, [dirty, confirmLeave]);\n\n  const rest = me?.restaurant;\n  const pricePreview = useMemo(() => {\n    const n = Number(iPrice);\n    return iPrice.trim() !== '' && Number.isFinite(n) && n > 0 ? formatXAF(Math.floor(n)) : null;\n  }, [iPrice]);\n\n  const pickPhoto = async () => {\n    try {\n      const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();\n      if (!perm.granted) { Alert.alert('Permiso de fotos', 'Necesitamos acceso a tu galería para la foto del restaurante.'); return; }\n      const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7 });\n      if (res.canceled || !res.assets?.[0]) return;\n      const asset = res.assets[0];\n      if ((asset.fileSize ?? 0) > MAX_PHOTO_MB * 1024 * 1024) {\n        Alert.alert('Foto demasiado pesada', `Usa una imagen de menos de ${MAX_PHOTO_MB} MB.`);\n        return;\n      }\n      const type = asset.mimeType ?? 'image/jpeg';\n      if (!type.startsWith('image/')) { Alert.alert('Archivo no válido', 'Selecciona una imagen.'); return; }\n      setPhotoBusy(true);\n      try {\n        const form = new FormData();\n        form.append('photo', { uri: asset.uri, name: 'foto.jpg', type } as unknown as Blob);\n        const r = await foodApi.uploadPhoto(form);\n        setPhotoUrl(r.url);\n      } catch (e) {\n        Alert.alert('Subir foto', e instanceof Error ? e.message : 'No se pudo subir la imagen. Inténtalo de nuevo.');\n      } finally {\n        setPhotoBusy(false);\n      }\n    } catch { /* picker cancelado por el sistema */ }\n  };\n\n  // ── Subir la foto de un PLATO ─────────────────────────────────────────────────\n  // Cámara o galería. La cámara está primero porque la foto del plato recién hecho es la que de\n  // verdad se parece al plato, y en un menú eso es justo lo que decide al cliente.\n  const subirFotoPlato = async (origen: 'camara' | 'galeria'): Promise<string | null> => {\n    try {\n      if (origen === 'camara') {\n        const perm = await ImagePicker.requestCameraPermissionsAsync();\n        if (!perm.granted) { Alert.alert('Permiso de cámara', 'Necesitamos la cámara para hacer la foto del plato.'); return null; }\n      } else {\n        const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();\n        if (!perm.granted) { Alert.alert('Permiso de fotos', 'Necesitamos acceso a tu galería para elegir la foto del plato.'); return null; }\n      }\n      const res = origen === 'camara'\n        ? await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.7 })\n        : await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7 });\n      if (res.canceled || !res.assets?.[0]) return null;\n      const asset = res.assets[0];\n      if ((asset.fileSize ?? 0) > MAX_PHOTO_MB * 1024 * 1024) {\n        Alert.alert('Foto demasiado pesada', `Usa una imagen de menos de ${MAX_PHOTO_MB} MB.`);\n        return null;\n      }\n      const type = asset.mimeType ?? 'image/jpeg';\n      if (!type.startsWith('image/')) { Alert.alert('Archivo no válido', 'Selecciona una imagen.'); return null; }\n      const form = new FormData();\n      form.append('photo', { uri: asset.uri, name: 'plato.jpg', type } as unknown as Blob);\n      const r = await foodApi.uploadPhoto(form);\n      return r.url;\n    } catch (e) {\n      Alert.alert('Subir foto', e instanceof Error ? e.message : 'No se pudo subir la imagen. Inténtalo de nuevo.');\n      return null;\n    }\n  };\n\n  /** Pregunta de dónde sacar la foto, la sube y devuelve su URL (o null si se cancela). */\n  const elegirFotoPlato = (): Promise<string | null> => new Promise((resolve) => {\n    const hacer = async (origen: 'camara' | 'galeria') => {\n      setIPhotoBusy(true);\n      try { resolve(await subirFotoPlato(origen)); } finally { setIPhotoBusy(false); }\n    };\n    Alert.alert(\n      'Foto del plato',\n      'Los clientes eligen por la foto: que se vea el plato de verdad, con buena luz y fondo limpio, y sin texto ni marcas de agua.',\n      [\n        { text: 'Hacer foto', onPress: () => { void hacer('camara'); } },\n        { text: 'Elegir de la galería', onPress: () => { void hacer('galeria'); } },\n        { text: 'Cancelar', style: 'cancel', onPress: () => resolve(null) },\n      ],\n    );\n  });\n\n  /** Pone o cambia la foto de un plato YA publicado. NO lo devuelve a revisión: el servidor deja\n   *  tocar la foto en cualquier estado precisamente para que hacer la foto no cueste ventas. */\n  const ponerFotoAItem = async (m: FoodMenuItem) => {\n    if (busyMenuRef.current) return;\n    const url = await elegirFotoPlato();\n    if (!url) return;\n    busyMenuRef.current = true;\n    setBusyMenuId(m.id);\n    try {\n      await foodApi.setItemPhoto(m.id, [url]);\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Foto del plato', e instanceof Error ? e.message : 'No se pudo guardar la foto.');\n    } finally {\n      busyMenuRef.current = false;\n      setBusyMenuId(null);\n    }\n  };\n\n  const validate = (): string | null => {\n    if (name.trim().length < 2) return 'Pon el nombre del restaurante (mín. 2 letras).';\n    if (!city) return 'Elige la ciudad del restaurante.';\n    const p = phone.trim();\n    if (p && !looksLikeGqPhone(p)) { setPhoneErr('Pon un teléfono de Guinea Ecuatorial (+240…).'); return 'Revisa el teléfono.'; }\n    setPhoneErr(null);\n    return null;\n  };\n\n  const doSave = async () => {\n    if (busyBizRef.current) return;\n    const invalid = validate();\n    if (invalid) { Alert.alert('Faltan datos', invalid); return; }\n    busyBizRef.current = true;\n    setBusyBiz(true);\n    try {\n      const p = phone.trim();\n      const r = await foodApi.upsertRestaurant({\n        businessName: name.trim(),\n        city,\n        address: address.trim() || null,\n        phoneContact: p ? (toGqMsisdn(p) ?? p) : null,\n        hours: hours.trim() || null,\n        description: desc.trim() || null,\n        photoKey: photoUrl ?? null,\n      });\n      Alert.alert(rest ? 'Restaurante actualizado' : 'Solicitud enviada', r.message);\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo guardar');\n    } finally {\n      busyBizRef.current = false;\n      setBusyBiz(false);\n    }\n  };\n\n  const save = () => {\n    if (rest?.status === 'active') {\n      Alert.alert('Actualizar restaurante', 'Los cambios se ven de inmediato en la app (la foto y el horario cambian para tus clientes).', [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Actualizar', onPress: doSave },\n      ]);\n    } else {\n      doSave();\n    }\n  };\n\n  const addItem = async () => {\n    if (busyPubRef.current) return;\n    if (iName.trim().length < 2) { Alert.alert('Faltan datos', 'Pon el nombre del plato (mín. 2 letras).'); return; }\n    const n = Number(iPrice);\n    if (!Number.isFinite(n) || !Number.isInteger(n) || n <= 0) {\n      setIPriceErr('Pon un precio válido (número entero mayor que 0).');\n      return;\n    }\n    if (n > 10_000_000) { setIPriceErr('Precio máximo: 10.000.000 XAF.'); return; }\n    setIPriceErr(null);\n\n    // ── Validar los detalles opcionales ANTES de enviar. Son opcionales (vacío\n    //    = no se declara), pero si el dueño escribió algo, tiene que ser válido.\n    //    Un error aquí abriría el desplegable para que el usuario vea el campo.\n    const ingErr = ingredientsError(iIngredients);\n    const porErr = portionSizeError(iPortion);\n    const sidErr = sidesError(iSides);\n    const prepErr = prepMinutesError(iPrep);\n    setIIngredientsErr(ingErr); setIPortionErr(porErr); setISidesErr(sidErr); setIPrepErr(prepErr);\n    if (ingErr || porErr || sidErr || prepErr) {\n      setShowDetails(true);\n      Alert.alert('Revisa los detalles', ingErr ?? porErr ?? sidErr ?? prepErr ?? '');\n      return;\n    }\n\n    // Solo se envía lo declarado: un campo vacío va como null (backend lo guarda\n    // NULL) o se omite, nunca como string vacía. Así un plato sin detalles queda\n    // exactamente igual que antes de la migración.\n    const sidesArr = parseSides(iSides);\n    const prep = parsePrepMinutes(iPrep);\n    const details: Record<string, unknown> = {};\n    const ing = parseIngredients(iIngredients);\n    if (ing) details.ingredients = ing;\n    if (iSpice) details.spiceLevel = iSpice;\n    const por = iPortion.trim();\n    if (por) details.portionSize = por;\n    if (iDrink) details.drinkIncluded = true;\n    if (sidesArr.length > 0) details.sides = sidesArr;\n    if (prep !== null) details.prepMinutes = prep;\n\n    busyPubRef.current = true;\n    setBusyPub(true);\n    try {\n      const r = await foodApi.createMenuItem({\n        name: iName.trim(), priceXaf: n, category: iCat, ...details,\n        // La foto va con el plato desde el primer momento: si se subió, se guarda con él.\n        ...(iPhoto ? { photos: [iPhoto] } : {}),\n      });\n      Alert.alert('Ítem enviado', r.message);\n      resetItemForm();\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo publicar');\n    } finally {\n      busyPubRef.current = false;\n      setBusyPub(false);\n    }\n  };\n\n  const toggleItem = async (m: FoodMenuItem) => {\n    if (busyMenuRef.current) return;\n    busyMenuRef.current = true;\n    setBusyMenuId(m.id);\n    try {\n      const r = await foodApi.setItemAvailable(m.id, !m.available);\n      Alert.alert('Menú', r.message);\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo cambiar');\n    } finally {\n      busyMenuRef.current = false;\n      setBusyMenuId(null);\n    }\n  };\n\n  const removeItem = (m: FoodMenuItem) => {\n    Alert.alert('Eliminar del menú', `¿Quitar \"${m.name}\"? Esta acción no se puede deshacer.`, [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: 'Eliminar', style: 'destructive', onPress: async () => {\n        if (busyMenuRef.current) return;\n        busyMenuRef.current = true;\n        setBusyMenuId(m.id);\n        try {\n          const r = await foodApi.deleteMenuItem(m.id);\n          Alert.alert('Menú', r.message);\n          await load('quiet');\n        } catch (e) {\n          Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo eliminar');\n        } finally {\n          busyMenuRef.current = false;\n          setBusyMenuId(null);\n        }\n      } },\n    ]);\n  };\n\n  const s = styles(colors);\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Cabecera del kit desde el 24/09/2026. El volver PREGUNTA antes de salir si hay cambios\n          sin guardar (`dirty ? confirmLeave() : router.back()`): por eso el kit recibe la función\n          en vez de navegar él. Las dos acciones de la derecha van en `accion`. */}\n      <ScreenHeader\n        titulo=\"Mi restaurante\"\n        alVolver={() => (dirty ? confirmLeave() : router.back())}\n        accion={\n          <>\n            <Tactil onPress={() => router.push('/food-rider' as any)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Pantalla de repartidor\">\n              <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>Repartir</Text>\n            </Tactil>\n            <Tactil onPress={() => router.push('/food-orders?as=owner' as any)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Pedidos recibidos\">\n              <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>Pedidos</Text>\n            </Tactil>\n          </>\n        }\n      />\n\n      {loading && !me ? (\n        <OwnerSkeleton colors={colors} />\n      ) : error ? (\n        <View style={s_center.wrap}>\n          <Text style={{ fontSize: 38, marginBottom: espaciado.e8 }}>📡</Text>\n          <Text style={[s_center.title, { color: colors.textPrimary }]}>Algo salió mal</Text>\n          <Text style={[s_center.sub, { color: colors.textSecondary }]}>{error}</Text>\n          <Pressable onPress={() => load('initial')} accessibilityRole=\"button\" style={s_center.btnPrimary}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n          <ScrollView\n            contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e32 + insets.bottom }}\n            showsVerticalScrollIndicator={false}\n            keyboardShouldPersistTaps=\"handled\"\n          >\n            {/* Requisitos */}\n            <View style={[s.reqBox, { backgroundColor: alpha(colors.primary, 0.06) }]}>\n              <Text style={[s.sectionTitle, { color: colors.textPrimary, marginBottom: espaciado.e6 }]}>Requisitos para operar</Text>\n              <ReqRow ok={me?.kycOk ?? false} label=\"Identidad verificada (KYC)\"\n                hint={me?.kycOk ? undefined : (me?.kycMessage ?? 'Toca para completar tu verificación')}\n                onPress={!me?.kycOk ? () => router.push('/driver-onboarding' as any) : undefined} />\n              <ReqRow ok={!!name.trim() && !!city} label=\"Datos del negocio (nombre + ciudad)\" />\n              <ReqRow ok={rest?.status === 'active'} label=\"Aprobación del administrador\"\n                hint={rest ? (rest.status === 'pending' ? 'En revisión (2–24 h)' : rest.status === 'rejected' ? 'Rechazado' : 'Activo') : undefined} />\n            </View>\n\n            {/* Formulario */}\n            <Text style={s.sectionTitle}>Tu restaurante</Text>\n\n            {/* Foto */}\n            <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e12 }}>\n              {photoUrl && /^https?:\\/\\//i.test(photoUrl) ? (\n                <Image source={{ uri: photoUrl }} style={s.photo} contentFit=\"cover\" transition={200} />\n              ) : (\n                <View style={[s.photo, s.photoFallback]}>\n                  <Text style={{ fontSize: 30 }}>🍽️</Text>\n                </View>\n              )}\n              <View style={{ marginLeft: espaciado.e12, flex: 1 }}>\n                <Pressable onPress={pickPhoto} disabled={photoBusy} accessibilityRole=\"button\"\n                  accessibilityLabel=\"Elegir foto del restaurante\"\n                  style={[s.photoBtn, { borderColor: ACCENT }]}>\n                  {photoBusy\n                    ? <ActivityIndicator size=\"small\" color={ACCENT} />\n                    : <Text style={{ color: ACCENT, fontWeight: '800', fontSize: tipografia.body }}>📷 {photoUrl ? 'Cambiar foto' : 'Añadir foto'}</Text>}\n                </Pressable>\n                {photoUrl ? (\n                  <Pressable onPress={() => setPhotoUrl(null)} accessibilityRole=\"button\" accessibilityLabel=\"Quitar foto\"\n                    style={{ marginTop: espaciado.e6, alignSelf: 'flex-start' }}>\n                    <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>Quitar foto</Text>\n                  </Pressable>\n                ) : (\n                  <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e6 }}>Máx 8 MB · se ve en la lista de restaurantes</Text>\n                )}\n              </View>\n            </View>\n\n            <FormField value={name} onChangeText={setName} placeholder=\"Nombre del restaurante *\" maxLength={120} />\n            <View style={{ marginTop: espaciado.e10 }} />\n\n            {/* Ciudad */}\n            <Pressable onPress={() => setCityModal(true)} accessibilityRole=\"button\"\n              accessibilityLabel={city ? `Ciudad: ${city}` : 'Elegir ciudad (obligatoria)'}\n              style={[s.cityBox, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n              <Text style={{ fontSize: tipografia.body, fontWeight: '600', color: city ? colors.textPrimary : colors.textSecondary }}>\n                {city ? `📍 ${city}` : 'Ciudad * (elige una)'}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>▾</Text>\n            </Pressable>\n            <View style={{ marginTop: espaciado.e10 }} />\n\n            <FormField value={address} onChangeText={setAddress} placeholder=\"Dirección\" maxLength={200} />\n            <View style={{ marginTop: espaciado.e10 }} />\n            <FormField\n              value={phone}\n              onChangeText={(t) => { setPhone(t); if (phoneErr) setPhoneErr(null); }}\n              placeholder=\"Teléfono / WhatsApp (+240…)\"\n              keyboardType=\"phone-pad\"\n              maxLength={20}\n              error={phoneErr ?? undefined}\n            />\n            <View style={{ marginTop: espaciado.e10 }} />\n            <FormField\n              value={hours}\n              onChangeText={(t) => { setHours(t); if (hoursErr) setHoursErr(null); }}\n              onBlur={() => setHoursErr(hours.trim() ? foodHoursError(hours) : null)}\n              placeholder=\"Horario (ej: 10:00–22:00)\"\n              maxLength={120}\n              error={hoursErr ?? undefined}\n            />\n            {!hoursErr && hours.trim() ? (\n              <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e4, marginLeft: espaciado.e2 }}>\n                Ej: 09:00-13:00, 16:00-20:00 · 24h · todo el día · cerrado\n              </Text>\n            ) : null}\n            <View style={{ marginTop: espaciado.e10 }} />\n            <TextInput\n              multiline\n              maxLength={2000}\n              style={[s.area, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n              placeholder=\"Descripción…\"\n              placeholderTextColor={colors.textSecondary}\n              value={desc}\n              onChangeText={setDesc}\n            />\n            <View style={{ marginTop: espaciado.e12 }}>\n              <PrimaryButton\n                title={busyBiz ? 'Guardando…' : (rest ? 'Actualizar restaurante' : 'Solicitar alta')}\n                onPress={save}\n                disabled={busyBiz || photoBusy}\n              />\n            </View>\n\n            {rest?.status === 'rejected' && rest.rejectionReason ? (\n              <View style={[s.rejectedBox, { backgroundColor: alpha(colors.danger, 0.08) }]}>\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>Motivo: {rest.rejectionReason}</Text>\n              </View>\n            ) : null}\n\n            {/* Añadir al menú (solo activo) */}\n            {rest?.status === 'active' && (\n              <>\n                <Text style={[s.sectionTitle, { marginTop: espaciado.e22 }]}>Añadir al menú</Text>\n                <FormField value={iName} onChangeText={setIName} placeholder=\"Nombre del plato * (ej: Pollo asado)\" maxLength={120} />\n                <View style={{ marginTop: espaciado.e10 }} />\n                <FormField\n                  value={iPrice}\n                  onChangeText={(t) => { setIPrice(t); if (iPriceErr) setIPriceErr(null); }}\n                  placeholder=\"Precio XAF *\"\n                  keyboardType=\"numeric\"\n                  error={iPriceErr ?? undefined}\n                />\n                {pricePreview ? (\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT, marginTop: espaciado.e4, marginLeft: espaciado.e2 }}>{pricePreview}</Text>\n                ) : null}\n                <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e10 }}>\n                  {CATS.map((c) => (\n                    <Pressable key={c.key} onPress={() => setICat(c.key)} accessibilityRole=\"radio\"\n                      accessibilityState={{ checked: iCat === c.key }}\n                      style={{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderRadius: radios.lg, backgroundColor: iCat === c.key ? colors.primary : colors.surface }}>\n                      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: iCat === c.key ? brand.white : colors.textPrimary }}>{c.label}</Text>\n                    </Pressable>\n                  ))}\n                </View>\n\n                {/* ── Foto del plato ──────────────────────────────────────────\n                    Una foto REAL, no un dibujo: es lo primero que mira el cliente. Se sube una\n                    vez y se queda guardada con el plato (ver comentario del estado). Por eso\n                    aquí, cuando ya hay foto, lo que se ofrece es «Cambiar» y «Quitar», nunca\n                    volver a subirla. */}\n                <Text style={[s.fieldLabel, { marginTop: espaciado.e16 }]}>Foto del plato</Text>\n                {iPhoto ? (\n                  <View style={{ flexDirection: 'row', alignItems: 'center' }}>\n                    <RNImage source={{ uri: iPhoto }} style={s.photo} />\n                    <View style={{ flex: 1, marginLeft: espaciado.e12 }}>\n                      <Text style={s.fieldHint}>\n                        Guardada con el plato: no hace falta volver a subirla.\n                      </Text>\n                      <View style={{ flexDirection: 'row', gap: espaciado.e16, marginTop: espaciado.e8 }}>\n                        <Pressable onPress={() => { void elegirFotoPlato().then((u) => { if (u) setIPhoto(u); }); }}\n                          hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Cambiar la foto del plato\">\n                          <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>Cambiar</Text>\n                        </Pressable>\n                        <Pressable onPress={() => setIPhoto(null)} hitSlop={8}\n                          accessibilityRole=\"button\" accessibilityLabel=\"Quitar la foto del plato\">\n                          <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.danger }}>Quitar</Text>\n                        </Pressable>\n                      </View>\n                    </View>\n                  </View>\n                ) : (\n                  <Pressable\n                    onPress={() => { void elegirFotoPlato().then((u) => { if (u) setIPhoto(u); }); }}\n                    disabled={iPhotoBusy}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Añadir foto del plato\"\n                    style={[s.photoBtn, { borderColor: alpha(ACCENT, 0.4), backgroundColor: alpha(ACCENT, 0.05) }]}\n                  >\n                    {iPhotoBusy ? (\n                      <ActivityIndicator size=\"small\" color={ACCENT} />\n                    ) : (\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n                        <Camera size={16} color={ACCENT} />\n                        <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>Hacer o elegir una foto</Text>\n                      </View>\n                    )}\n                  </Pressable>\n                )}\n                {!iPhoto && !iPhotoBusy ? (\n                  <Text style={s.fieldHint}>\n                    Opcional, pero es lo que más vende. Foto real del plato: sin dibujos ni marcas de agua.\n                  </Text>\n                ) : null}\n\n                {/* ── Detalles del plato (041) ────────────────────────────────\n                    Desplegable: por defecto CERRADO para que publicar un plato\n                    siga siendo tan rápido como antes (nombre + precio + tipo).\n                    Todo lo de dentro es opcional; si no se declara, la ficha del\n                    cliente simplemente no lo muestra. */}\n                <Pressable\n                  onPress={() => setShowDetails((v) => !v)}\n                  accessibilityRole=\"button\"\n                  accessibilityState={{ expanded: showDetails }}\n                  accessibilityLabel=\"Detalles del plato, opcional\"\n                  style={[s.detailsHead, { backgroundColor: alpha(ACCENT, 0.06), borderColor: alpha(ACCENT, 0.25) }]}\n                >\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>\n                    Detalles del plato (opcional)\n                  </Text>\n                  <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: ACCENT }}>{showDetails ? '−' : '+'}</Text>\n                </Pressable>\n\n                {showDetails && (\n                  <View style={s.detailsBody}>\n                    {/* Ingredientes */}\n                    <Text style={s.fieldLabel}>Ingredientes</Text>\n                    <TextInput\n                      multiline\n                      maxLength={1000}\n                      value={iIngredients}\n                      onChangeText={(t) => { setIIngredients(t); if (iIngredientsErr) setIIngredientsErr(null); }}\n                      onBlur={() => setIIngredientsErr(ingredientsError(iIngredients))}\n                      placeholder=\"Pollo, arroz, salsa de cacahuete…\"\n                      placeholderTextColor={colors.textSecondary}\n                      style={[s.area, { minHeight: 56, backgroundColor: colors.surface, borderColor: iIngredientsErr ? colors.danger : colors.border, color: colors.textPrimary }]}\n                      accessibilityLabel=\"Ingredientes del plato\"\n                    />\n                    {iIngredientsErr ? <Text style={s.fieldErr}>{iIngredientsErr}</Text> : null}\n\n                    {/* Picante */}\n                    <Text style={[s.fieldLabel, { marginTop: espaciado.e12 }]}>Nivel de picante</Text>\n                    <View style={s.chipRow}>\n                      {SPICE_ORDER.map((lvl) => {\n                        const active = iSpice === lvl;\n                        return (\n                          <Pressable\n                            key={lvl}\n                            onPress={() => setISpice(active ? null : lvl)}\n                            accessibilityRole=\"radio\"\n                            accessibilityState={{ checked: active }}\n                            accessibilityLabel={SPICE_LABEL[lvl]}\n                            style={[s.chip, { borderColor: active ? ACCENT : colors.border, backgroundColor: active ? alpha(ACCENT, 0.1) : colors.surface }]}\n                          >\n                            <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: active ? ACCENT : colors.textPrimary }}>\n                              {SPICE_ICON[lvl]} {SPICE_LABEL[lvl]}\n                            </Text>\n                          </Pressable>\n                        );\n                      })}\n                    </View>\n                    <Text style={s.fieldHint}>Toca el nivel activo otra vez para quitarlo.</Text>\n\n                    {/* Tamaño / ración */}\n                    <Text style={[s.fieldLabel, { marginTop: espaciado.e12 }]}>Tamaño o ración</Text>\n                    <FormField\n                      value={iPortion}\n                      onChangeText={(t) => { setIPortion(t); if (iPortionErr) setIPortionErr(null); }}\n                      onBlur={() => setIPortionErr(portionSizeError(iPortion))}\n                      placeholder=\"Ej: 2 piezas, 400 g, Grande\"\n                      maxLength={40}\n                      error={iPortionErr ?? undefined}\n                      accessibilityLabel=\"Tamaño o ración del plato\"\n                    />\n\n                    {/* Bebida incluida */}\n                    <Pressable\n                      onPress={() => setIDrink((v) => !v)}\n                      accessibilityRole=\"switch\"\n                      accessibilityState={{ checked: iDrink }}\n                      accessibilityLabel=\"Bebida incluida\"\n                      style={[s.switchRow, { borderColor: colors.border }]}\n                    >\n                      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>🥤 Incluye bebida</Text>\n                      <View style={[s.switchTrack, { backgroundColor: iDrink ? ACCENT : colors.border }]}>\n                        <View style={[s.switchKnob, { transform: [{ translateX: iDrink ? 18 : 0 }] }]} />\n                      </View>\n                    </Pressable>\n\n                    {/* Acompañantes */}\n                    <Text style={[s.fieldLabel, { marginTop: espaciado.e12 }]}>Acompañantes</Text>\n                    <TextInput\n                      multiline\n                      maxLength={1200}\n                      value={iSides}\n                      onChangeText={(t) => { setISides(t); if (iSidesErr) setISidesErr(null); }}\n                      onBlur={() => setISidesErr(sidesError(iSides))}\n                      placeholder=\"Arroz, plátano frito, ensalada…\"\n                      placeholderTextColor={colors.textSecondary}\n                      style={[s.area, { minHeight: 56, backgroundColor: colors.surface, borderColor: iSidesErr ? colors.danger : colors.border, color: colors.textPrimary }]}\n                      accessibilityLabel=\"Acompañantes del plato\"\n                    />\n                    {iSidesErr\n                      ? <Text style={s.fieldErr}>{iSidesErr}</Text>\n                      : <Text style={s.fieldHint}>Separados por coma. Máximo {SIDES_MAX}.</Text>}\n\n                    {/* Tiempo de preparación */}\n                    <Text style={[s.fieldLabel, { marginTop: espaciado.e12 }]}>Tiempo de preparación (minutos)</Text>\n                    <FormField\n                      value={iPrep}\n                      onChangeText={(t) => { setIPrep(t.replace(/[^0-9]/g, '')); if (iPrepErr) setIPrepErr(null); }}\n                      onBlur={() => setIPrepErr(prepMinutesError(iPrep))}\n                      placeholder=\"Ej: 20\"\n                      keyboardType=\"numeric\"\n                      maxLength={3}\n                      error={iPrepErr ?? undefined}\n                      accessibilityLabel=\"Tiempo de preparación en minutos\"\n                    />\n                    {!iPrepErr && iPrep.trim() ? (\n                      <Text style={s.fieldHint}>\n                        El cliente verá «~{parsePrepMinutes(iPrep)} min» en el menú. En un pedido con\n                        varios platos se muestra el más lento.\n                      </Text>\n                    ) : null}\n                  </View>\n                )}\n\n                <View style={{ marginTop: espaciado.e12 }}>\n                  <PrimaryButton title={busyPub ? 'Enviando…' : 'Publicar (pasa a revisión admin)'} onPress={addItem} disabled={busyPub} />\n                </View>\n                {me?.menu.length === 0 && (\n                  <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e10, textAlign: 'center' }}>\n                    Tu menú está vacío: publica el primer plato aquí arriba ☝️\n                  </Text>\n                )}\n              </>\n            )}\n\n            {/* Mi menú (gestión) */}\n            {me && me.menu.length > 0 && (\n              <>\n                <Text style={[s.sectionTitle, { marginTop: espaciado.e22 }]}>Mi menú ({me.menu.length})</Text>\n                {me.menu.map((m) => (\n                  <MenuRow\n                    key={m.id}\n                    item={m}\n                    busy={busyMenuId === m.id}\n                    onToggle={m.status === 'active' ? () => toggleItem(m) : undefined}\n                    onPhoto={() => { void ponerFotoAItem(m); }}\n                    onRemove={() => removeItem(m)}\n                  />\n                ))}\n              </>\n            )}\n          </ScrollView>\n        </KeyboardAvoidingView>\n      )}\n\n      {/*\n        Selector de ciudad. Era un `<Modal>` a mano con su cabecera y su «X»; el `Sheet` trae el\n        fondo, el cierre al tocar fuera, el botón de atrás y el título anunciado como cabecera.\n      */}\n      <Sheet\n        visible={cityModal}\n        position=\"bottom\"\n        title=\"Elige la ciudad\"\n        onClose={() => setCityModal(false)}\n      >\n        <ScrollView style={{ maxHeight: 420 }} showsVerticalScrollIndicator={false}>\n          {CITIES.map((c) => (\n            <Pressable key={c.id}\n              onPress={() => { setCity(c.name); setCityModal(false); }}\n              accessibilityRole=\"button\"\n              style={[s.cityItem, { borderBottomColor: colors.border }]}>\n              <Text style={{ fontSize: tipografia.body, fontWeight: city === c.name ? '800' : '600', color: city === c.name ? ACCENT : colors.textPrimary }}>{c.name}</Text>\n              {c.region ? <Text style={{ fontSize: 10.5, color: colors.textSecondary }}>{c.region}</Text> : null}\n            </Pressable>\n          ))}\n        </ScrollView>\n\n      </Sheet>\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\nfunction MenuRow({ item, busy, onToggle, onPhoto, onRemove }: {\n  item: FoodMenuItem; busy: boolean;\n  onToggle?: () => void; onPhoto: () => void; onRemove: () => void;\n}) {\n  const { colors } = useTheme();\n  const photo = item.photos?.[0] && /^https?:\\/\\//i.test(item.photos[0]) ? item.photos[0] : null;\n  const statusColor = item.status === 'active' ? brand.success : item.status === 'rejected' ? colors.danger : colors.secondary;\n  const statusText = item.status === 'active' ? (item.available ? '✓ Activo' : 'Oculto') : item.status === 'rejected' ? '✗ Rechazado' : 'En revisión';\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: colors.surface, borderRadius: 10, padding: espaciado.e10, marginBottom: espaciado.e6, borderWidth: 1, borderColor: colors.border }}>\n      {photo ? (\n        <RNImage source={{ uri: photo }} style={{ width: 40, height: 40, borderRadius: radios.sm }} />\n      ) : (\n        /* Sin foto: NO se pone un dibujo de plato. Un dibujo ocupa el sitio de la foto y hace\n           creer que el plato «ya tiene imagen», cuando lo que pasa es que le FALTA. Se ve una\n           cámara y, al lado del precio, «falta foto»: así el dueño sabe qué le queda por hacer. */\n        <Pressable onPress={onPhoto} hitSlop={6} accessibilityRole=\"button\"\n          accessibilityLabel={`Añadir foto a ${item.name}`}\n          style={{ width: 40, height: 40, borderRadius: radios.sm, backgroundColor: alpha(colors.secondary, 0.12), alignItems: 'center', justifyContent: 'center' }}>\n          <Camera size={16} color={colors.textSecondary} />\n        </Pressable>\n      )}\n      <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n        <Text numberOfLines={1} style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>{item.name}</Text>\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n          <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>{formatXAF(item.priceXaf)}</Text>\n          <Text style={{ fontSize: 10.5, fontWeight: '700', color: statusColor }}>{statusText}</Text>\n          {!photo ? <Text style={{ fontSize: 10.5, fontWeight: '700', color: brand.warning }}>· falta foto</Text> : null}\n        </View>\n      </View>\n      {busy ? (\n        <ActivityIndicator size=\"small\" color={colors.primary} />\n      ) : (\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n          {onToggle ? (\n            <Pressable onPress={onToggle} hitSlop={6} accessibilityRole=\"button\"\n              accessibilityLabel={item.available ? `Ocultar ${item.name} del menú` : `Mostrar ${item.name} en el menú`}\n              style={[s_row.iconBtn, { backgroundColor: alpha(colors.primary, 0.1) }]}>\n              {item.available ? <EyeOff size={15} color={colors.primary} /> : <Eye size={15} color={colors.primary} />}\n            </Pressable>\n          ) : null}\n          <Pressable onPress={onRemove} hitSlop={6} accessibilityRole=\"button\" accessibilityLabel={`Eliminar ${item.name}`}\n            style={[s_row.iconBtn, { backgroundColor: alpha(colors.danger, 0.1) }]}>\n            <Trash2 size={15} color={colors.danger} />\n          </Pressable>\n        </View>\n      )}\n    </View>\n  );\n}\n\nfunction ReqRow({ ok, label, hint, onPress }: { ok: boolean; label: string; hint?: string; onPress?: () => void }) {\n  const { colors } = useTheme();\n  const row = (\n    <View style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e5 }}>\n      {ok ? <BadgeCheck size={16} color={brand.success} /> : <XCircle size={16} color=\"#CBD5E1\" />}\n      <View style={{ flex: 1, marginLeft: espaciado.e8 }}>\n        <Text style={{ fontSize: tipografia.caption, fontWeight: '600', color: ok ? colors.textPrimary : colors.textSecondary }}>{label}</Text>\n        {hint ? <Text style={{ fontSize: 10.5, color: onPress ? colors.primary : colors.textSecondary }}>{hint}</Text> : null}\n      </View>\n      {onPress ? <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>→</Text> : null}\n    </View>\n  );\n  return onPress ? (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityLabel={`${label}. ${hint ?? ''}`} style={{ paddingVertical: espaciado.e2 }}>\n      {row}\n    </Pressable>\n  ) : row;\n}\n\nfunction OwnerSkeleton({ colors }: { colors: ReturnType<typeof useTheme>['colors'] }) {\n  return (\n    <View style={{ padding: espaciado.e16, gap: espaciado.e10 }}>\n      {[0, 1, 2, 3].map((i) => (\n        <View key={i} style={{ height: 44, borderRadius: radios.md, backgroundColor: colors.border, width: i % 2 === 0 ? '100%' : '80%' }} />\n      ))}\n    </View>\n  );\n}\n\nconst s_row = StyleSheet.create({\n  iconBtn: { width: 30, height: 30, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\n});\n\nconst s_center = StyleSheet.create({\n  wrap: { alignItems: 'center', paddingTop: 56, paddingHorizontal: espaciado.e28 },\n  title: { fontSize: 15, fontWeight: '800', textAlign: 'center' },\n  sub: { fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 },\n  btnPrimary: { marginTop: espaciado.e18, backgroundColor: ACCENT, paddingHorizontal: espaciado.e24, paddingVertical: espaciado.e11, borderRadius: 22 },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  reqBox: { borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e14 },\n  sectionTitle: { fontSize: tipografia.body, fontWeight: '800', marginBottom: espaciado.e10 },\n  photo: { width: 84, height: 84, borderRadius: 14 },\n  photoFallback: { backgroundColor: alpha(ACCENT, 0.08), alignItems: 'center', justifyContent: 'center' },\n  photoBtn: { borderWidth: 1.5, borderRadius: radios.md, paddingVertical: espaciado.e10, alignItems: 'center' },\n  cityBox: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', borderRadius: 14, borderWidth: 1.5, paddingHorizontal: espaciado.e14, height: altura.campo },\n  area: { minHeight: 70, borderRadius: 14, borderWidth: 1, padding: espaciado.e12, fontSize: tipografia.body, textAlignVertical: 'top' },\n  rejectedBox: { borderRadius: 10, padding: espaciado.e10, marginTop: espaciado.e12 },\n  cityItem: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e20, paddingVertical: espaciado.e13, borderBottomWidth: 1 },\n  // ── Detalles del plato (041) ──\n  detailsHead: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e11, marginTop: espaciado.e12 },\n  detailsBody: { borderRadius: radios.md, borderWidth: 1, borderColor: c.border, padding: espaciado.e12, marginTop: espaciado.e8, backgroundColor: c.background },\n  fieldLabel: { fontSize: tipografia.caption, fontWeight: '700', color: c.textSecondary, marginBottom: espaciado.e6, marginLeft: espaciado.e2 },\n  fieldHint: { fontSize: 10.5, color: c.textSecondary, marginTop: espaciado.e5, marginLeft: espaciado.e2, lineHeight: 15 },\n  fieldErr: { fontSize: tipografia.micro, fontWeight: '700', color: c.danger, marginTop: espaciado.e5, marginLeft: espaciado.e2 },\n  chipRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e7 },\n  chip: { borderWidth: 1, borderRadius: radios.lg, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e7 },\n  switchRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e11, marginTop: espaciado.e12 },\n  switchTrack: { width: 42, height: 24, borderRadius: radios.md, padding: espaciado.e3, justifyContent: 'center' },\n  switchKnob: { width: 18, height: 18, borderRadius: 9, backgroundColor: brand.white },\n});\n","/**\n * Validación de horarios de apertura de restaurantes (espejo del backend\n * food.dto.ts). El badge \"Abierto/Cerrado\" lo calcula el servidor con la hora\n * de Malabo; para que siempre funcione, el dueño solo puede guardar formatos\n * estructurados:\n *   · turnos \"HH:MM-HH:MM\" (guiones -, –, —), varios separados por coma o \"/\"\n *   · tokens: 24/7, 24h, 24 horas, todo el día, abierto 24h, siempre abierto,\n *     cerrado, closed\n */\n\nconst HOURS_TOKEN = /^(24\\s*\\/\\s*7|24h|24\\s*horas|todo\\s*el\\s*d[ií]a|abierto\\s*24(\\s*h(oras)?)?|siempre\\s*abierto|cerrado|closed)$/i;\nconst HOURS_PAIR = /^(\\d{1,2}:\\d{2})\\s*[-–—]\\s*(\\d{1,2}:\\d{2})$/;\n\nfunction hoursPartOk(t: string): boolean {\n  const m = t.trim().match(/^(\\d{1,2}):(\\d{2})$/);\n  if (!m) return false;\n  const h = Number(m[1]);\n  const min = Number(m[2]);\n  if (min > 59) return false;\n  if (h > 24) return false;\n  if (h === 24 && min !== 0) return false;\n  return true;\n}\n\n/** Devuelve true si el texto es un horario estructurado válido. */\nexport function foodHoursValid(v: string): boolean {\n  const t = v.trim();\n  if (!t) return false;\n  if (HOURS_TOKEN.test(t)) return true;\n  const turns = t.split(/[,/]/).map((p) => p.trim()).filter(Boolean);\n  if (turns.length === 0) return false;\n  return turns.every((turn) => {\n    const m = turn.match(HOURS_PAIR);\n    return !!m && hoursPartOk(m[1]) && hoursPartOk(m[2]);\n  });\n}\n\nexport const FOOD_HOURS_HINT =\n  'Formato: 10:00-22:00 (turnos separados por coma, ej: 09:00-13:00, 16:00-20:00), 24h, todo el día o cerrado.';\n\n/** Mensaje de error si el horario no es válido; null si es válido (o vacío). */\nexport function foodHoursError(v: string): string | null {\n  const t = v.trim();\n  if (!t) return null;\n  return foodHoursValid(t) ? null : FOOD_HOURS_HINT;\n}\n","/**\n * FoodRiderScreen — Perfil y entregas del repartidor (Comida Rápida).\n * Requisitos (KYC + datos + aprobación admin), alta/edición, \"Mis entregas\"\n * con avanzar estado (picked_up → in_transit → delivered).\n *\n * Auditoría senior (2026-09-02):\n *  · Contactos operativos del rider asignado: teléfono del restaurante y del\n *    cliente (acceso por rol, solo sus entregas) con botón de llamada.\n *  · Estados de entrega SIEMPRE en español; flujo en constante (RIDER_NEXT).\n *  · Confirmación antes de avanzar + busy por entrega + busyRef.\n *  · Recarga al volver a la pantalla (focus) + pull-to-refresh.\n *  · Contador \"X entregas completadas\" (sin inventar montos; modelo de pago al\n *    rider queda pendiente de su ronda de monetización).\n *  · Carga skeleton / error + Reintentar; vacíos diferenciados; KYC CTA.\n *  · KeyboardAvoidingView + SafeArea + a11y.\n * Ruta: /food-rider\n */\n\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, KeyboardAvoidingView, Linking, Platform, Pressable,\n  RefreshControl, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { BadgeCheck, MapPin, Navigation, Phone, XCircle } from 'lucide-react-native';\nimport { alpha, espaciado, FormField, PrimaryButton, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { foodApi, FoodDelivery, FoodRiderMe, ContabilidadRepartidor } from '../api/food';\nimport { getGqPositionIfAllowed } from '../api/locate';\nimport { formatXAF } from '../utils/formatHelpers';\nimport { abrirMapa } from '../utils/maps';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst ACCENT = brand.primary; // A1: la acción avanza en azul\nconst STATUS_LABEL: Record<string, string> = { pending: 'En revisión', active: 'Activo', rejected: 'Rechazado' };\nconst VEHICLE_LABEL: Record<string, string> = { moto: '🛵 Moto', bici: '🚲 Bici', coche: '🚗 Coche' };\nconst DELIVERY_LABEL: Record<string, string> = {\n  assigned: 'Asignada', picked_up: 'Recogido', in_transit: 'En camino', delivered: 'Entregado',\n};\n// Flujo del rider (única fuente; espejo del backend).\nconst RIDER_NEXT: Record<string, { next: string | null; btn: string; confirm: string }> = {\n  assigned: { next: 'picked_up', btn: '📦 Recogí el pedido', confirm: 'Confirma que ya recogiste el pedido en el restaurante.' },\n  picked_up: { next: 'in_transit', btn: '🛵 En camino', confirm: 'Marca el pedido como en camino hacia el cliente.' },\n  in_transit: { next: 'delivered', btn: '✅ Entregado', confirm: 'Confirma que entregaste el pedido al cliente.' },\n  delivered: { next: null, btn: '', confirm: '' },\n};\n\n/**\n * Llevar al repartidor al punto de entrega. Vive en `utils/maps.ts` porque la pantalla del cliente\n * necesita exactamente lo mismo para enseñar el punto de encuentro: dos copias serían dos sitios donde\n * arreglar el mismo fallo.\n */\n\nexport default function FoodRiderScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [me, setMe] = useState<FoodRiderMe | null>(null);\n  const [name, setName] = useState('');\n  const [vehicle, setVehicle] = useState<'moto' | 'bici' | 'coche'>('moto');\n  const [zone, setZone] = useState('');\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [busySave, setBusySave] = useState(false);\n  const [busyDeliveryId, setBusyDeliveryId] = useState<string | null>(null);\n  // ── El dinero del repartidor ──────────────────────────────────────────────────\n  // `contab` es su semana (entregas, comisiones, efectivo y lo que se le pagará). `cobroDe` guarda\n  // en qué entrega está escribiendo el efectivo, porque el importe se anota EN LÍNEA (en Android no\n  // existe `Alert.prompt`, y con un diálogo de texto el repartidor se quedaría sin poder anotarlo).\n  const [contab, setContab] = useState<ContabilidadRepartidor | null>(null);\n  const [cobroDe, setCobroDe] = useState<string | null>(null);\n  const [cobroTexto, setCobroTexto] = useState('');\n  // ── DÓNDE ENTREGAR Y DÓNDE SE ENCUENTRAN ─────────────────────────────────────\n  // El repartidor necesita dos cosas que la dirección de texto no da: llegar (mapa) y encontrarse con\n  // el cliente en sitios que no son una dirección — un hotel, viviendas sociales, un portal sin número.\n  // `puntoDe` guarda en qué entrega está escribiendo el punto de encuentro; el resto va EN LÍNEA por la\n  // misma razón que el efectivo: en Android no hay diálogo con campo de texto.\n  const [puntoDe, setPuntoDe] = useState<string | null>(null);\n  const [puntoTexto, setPuntoTexto] = useState('');\n  const [puntoCoords, setPuntoCoords] = useState<[number, number] | null>(null);   // [lng, lat]\n  const [puntoUbicando, setPuntoUbicando] = useState(false);\n  const busySaveRef = useRef(false);\n  const busyAdvanceRef = useRef(false);\n\n  const load = useCallback(async (mode: 'initial' | 'refresh' | 'quiet' = 'initial') => {\n    if (mode === 'initial') { setLoading(true); setError(null); }\n    if (mode === 'refresh') setRefreshing(true);\n    try {\n      const m = await foodApi.riderMe();\n      setMe(m);\n      if (m.rider) {\n        setName(m.rider.fullName);\n        setVehicle(m.rider.vehicleType as 'moto' | 'bici' | 'coche');\n        setZone(m.rider.zone ?? '');\n      }\n      setError(null);\n      // La contabilidad de la semana va aparte y NUNCA puede tumbar la pantalla: si falla, el\n      // repartidor sigue viendo sus entregas y solo se queda sin el bloque del dinero. (Un fallo de\n      // la parte nueva no puede dejar sin trabajo a quien tiene que repartir.)\n      try {\n        if (m.rider?.status === 'active') setContab(await foodApi.riderContabilidad());\n      } catch { /* sin contabilidad, pero con entregas */ }\n    } catch {\n      if (mode === 'initial') setError('No pudimos cargar tu perfil. Revisa tu conexión e inténtalo de nuevo.');\n    } finally {\n      if (mode === 'initial') setLoading(false);\n      if (mode === 'refresh') setRefreshing(false);\n    }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  // Al volver a la pantalla se refrescan las entregas (pueden asignarte una).\n  useFocusEffect(\n    useCallback(() => { if (me) { load('quiet'); } /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [load]),\n  );\n\n  const save = async () => {\n    if (busySaveRef.current) return;\n    if (name.trim().length < 2) { Alert.alert('Faltan datos', 'Pon tu nombre completo (mín. 2 letras).'); return; }\n    busySaveRef.current = true;\n    setBusySave(true);\n    try {\n      const r = await foodApi.upsertRider({ fullName: name.trim(), vehicleType: vehicle, zone: zone.trim() || undefined });\n      Alert.alert('Solicitud enviada', r.message);\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo guardar');\n    } finally {\n      busySaveRef.current = false;\n      setBusySave(false);\n    }\n  };\n\n  const requestAdvance = (d: FoodDelivery) => {\n    if (busyAdvanceRef.current) return;\n    const meta = RIDER_NEXT[d.status];\n    if (!meta?.next) return;\n    Alert.alert(meta.btn.replace(/^[^\\s]+\\s/, ''), meta.confirm, [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: 'Sí, continuar', onPress: () => advance(d.orderId, meta.next!) },\n    ]);\n  };\n\n  const advance = async (orderId: string, nextStatus: string) => {\n    if (busyAdvanceRef.current) return;\n    busyAdvanceRef.current = true;\n    setBusyDeliveryId(orderId);\n    try {\n      const r = await foodApi.updateDelivery(orderId, nextStatus);\n      Alert.alert('Entrega', r.message);\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo actualizar la entrega');\n    } finally {\n      busyAdvanceRef.current = false;\n      setBusyDeliveryId(null);\n    }\n  };\n\n  /**\n   * ANOTAR EL EFECTIVO COBRADO en la puerta.\n   *\n   * Es lo único que escribe el repartidor: su comisión la calcula el servidor con el desglose\n   * congelado del pedido, así que no puede cambiarse el sueldo desde la app.\n   *\n   * OJO con el detalle que se ve al escribir esto: `Alert.prompt` **solo existe en iOS**, y esta app\n   * es Android. Un cuadro de diálogo con campo de texto habría dejado al repartidor sin poder anotar\n   * nada en el móvil de verdad, sin ningún error visible. Por eso el importe se escribe en un campo\n   * EN LÍNEA, dentro de la propia entrega.\n   */\n  const guardarCobro = async (orderId: string) => {\n    if (busyAdvanceRef.current) return;\n    const n = Math.max(0, Math.round(Number(cobroTexto.replace(/[^0-9]/g, '')) || 0));\n    busyAdvanceRef.current = true;\n    setBusyDeliveryId(orderId);\n    try {\n      const r = await foodApi.riderAnotarCobro(orderId, n);\n      Alert.alert('Anotado', r.message);\n      setCobroDe(null);\n      setCobroTexto('');\n      await load('quiet');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo anotar el cobro');\n    } finally {\n      busyAdvanceRef.current = false;\n      setBusyDeliveryId(null);\n    }\n  };\n\n  const call = (phone: string | null, who: string) => {\n    const d = (phone ?? '').replace(/\\D/g, '');\n    if (!d) return;\n    Linking.openURL(`tel:${d}`).catch(() => Alert.alert('Llamar', `No se pudo abrir el teléfono para ${who}. Inténtalo de nuevo.`));\n  };\n\n  /** Tomar la ubicación del repartidor para el punto de encuentro. `LocCoord` es [lng, lat]. */\n  const ubicarmeParaPunto = async () => {\n    setPuntoUbicando(true);\n    try {\n      const c = await getGqPositionIfAllowed(6000);\n      if (!c) {\n        Alert.alert('Ubicación', 'No se pudo obtener tu ubicación. Puedes escribir el punto de encuentro sin ella.');\n        return;\n      }\n      setPuntoCoords(c);\n    } finally { setPuntoUbicando(false); }\n  };\n\n  /**\n   * ANOTAR EL PUNTO DE ENCUENTRO.\n   *\n   * La dirección del cliente puede ser un hotel, viviendas sociales o un portal sin número: el nombre\n   * del sitio no basta para encontrarse. El repartidor escribe dónde está («entrada por la puerta\n   * lateral, junto a la farmacia») y, si tiene GPS, deja su posición. El cliente lo ve en su pedido y\n   * recibe un SMS, para que no dependa de estar mirando la app.\n   */\n  const guardarPunto = async (orderId: string) => {\n    if (busyAdvanceRef.current) return;\n    const nota = puntoTexto.trim();\n    if (nota.length < 3) {\n      Alert.alert('Punto de encuentro', 'Escribe dónde os encontráis (mínimo 3 caracteres).');\n      return;\n    }\n    busyAdvanceRef.current = true;\n    setBusyDeliveryId(orderId);\n    try {\n      await foodApi.setMeetingPoint(orderId, {\n        note: nota,\n        lat: puntoCoords ? puntoCoords[1] : null,\n        lng: puntoCoords ? puntoCoords[0] : null,\n      });\n      setPuntoDe(null);\n      setPuntoTexto('');\n      setPuntoCoords(null);\n      await load('quiet');\n      Alert.alert('Avisado', 'El cliente ya ve dónde os encontráis.');\n    } catch (e) {\n      Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo anotar el punto de encuentro');\n    } finally {\n      busyAdvanceRef.current = false;\n      setBusyDeliveryId(null);\n    }\n  };\n\n  const s = styles(colors);\n  const rider = me?.rider;\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Cabecera del kit desde el 24/09/2026. */}\n      <ScreenHeader titulo=\"Repartidor\" alVolver={() => router.back()} />\n\n      {loading && !me ? (\n        <View style={{ padding: espaciado.e16, gap: espaciado.e10 }}>\n          {[0, 1, 2, 3].map((i) => (\n            <View key={i} style={{ height: 44, borderRadius: radios.md, backgroundColor: colors.border, width: i % 2 === 0 ? '100%' : '78%' }} />\n          ))}\n        </View>\n      ) : error ? (\n        <View style={s_center.wrap}>\n          <Text style={{ fontSize: 38, marginBottom: espaciado.e8 }}>📡</Text>\n          <Text style={[s_center.title, { color: colors.textPrimary }]}>Algo salió mal</Text>\n          <Text style={[s_center.sub, { color: colors.textSecondary }]}>{error}</Text>\n          <Pressable onPress={() => load('initial')} accessibilityRole=\"button\" style={s_center.btnPrimary}>\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n          <ScrollView\n            contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e32 + insets.bottom }}\n            showsVerticalScrollIndicator={false}\n            keyboardShouldPersistTaps=\"handled\"\n            refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => load('refresh')} tintColor={colors.primary} />}\n          >\n            {/* Requisitos */}\n            <View style={[s.reqBox, { backgroundColor: alpha(colors.primary, 0.06) }]}>\n              <Text style={[s.sectionTitle, { color: colors.textPrimary, marginBottom: espaciado.e6 }]}>Requisitos para repartir</Text>\n              <ReqRow ok={me?.kycOk ?? false} label=\"Identidad verificada (KYC)\"\n                hint={me?.kycOk ? undefined : (me?.kycMessage ?? 'Toca para completar tu verificación')}\n                onPress={!me?.kycOk ? () => router.push('/driver-onboarding' as any) : undefined} />\n              <ReqRow ok={name.trim().length >= 2} label=\"Datos del repartidor (nombre + vehículo)\" />\n              <ReqRow ok={rider?.status === 'active'} label=\"Aprobación del administrador\"\n                hint={rider ? (rider.status === 'pending' ? 'En revisión (2–24 h)' : rider.status === 'rejected' ? 'Rechazado' : 'Activo') : undefined} />\n            </View>\n\n            {/* ── TU SEMANA: lo que llevas ganado y lo que llevas cobrado ─────────────\n                Sin sueldo base, esto es TODO su ingreso, así que tiene que verlo sin preguntar:\n                entregas, comisiones, efectivo que lleva en la mano y lo que se le pagará el próximo\n                día de liquidación. Y si debe más de lo que ganó, se dice EN ROJO: es su deuda, no un\n                error del sistema, y ocultarla sería lo peor que podríamos hacer. */}\n            {rider?.status === 'active' && contab ? (\n              <View style={{ marginTop: espaciado.e16 }}>\n                <Text style={s.sectionTitle}>Tu semana</Text>\n                <View style={[s.reqBox, { backgroundColor: colors.surface, borderWidth: 1, borderColor: colors.border }]}>\n                  <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>\n                    <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>Entregas</Text>\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textPrimary }}>{contab.entregas}</Text>\n                  </View>\n                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: espaciado.e4 }}>\n                    <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>Tus comisiones</Text>\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: brand.success }}>{formatXAF(contab.comisionesXaf)}</Text>\n                  </View>\n                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: espaciado.e4 }}>\n                    <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>Efectivo que llevas</Text>\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textPrimary }}>{formatXAF(contab.efectivoCobradoXaf)}</Text>\n                  </View>\n                  <View style={{ height: 1, backgroundColor: colors.border, marginVertical: espaciado.e8 }} />\n                  <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>\n                    <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>Se te pagará</Text>\n                    <Text style={{ fontSize: tipografia.body, fontWeight: '900', color: brand.success }}>{formatXAF(contab.aPagarXaf)}</Text>\n                  </View>\n                  {contab.deudaArrastradaXaf > 0 ? (\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.danger, marginTop: espaciado.e6 }}>\n                      ⚠ Debes {formatXAF(contab.deudaArrastradaXaf)} de efectivo: se descontará la semana que viene.\n                    </Text>\n                  ) : null}\n                  <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e6 }}>\n                    Se paga cada semana, el efectivo que cobras en la puerta se descuenta de lo que ganas.\n                  </Text>\n                </View>\n              </View>\n            ) : null}\n\n            {/* Perfil */}\n            <Text style={s.sectionTitle}>Tu perfil</Text>\n            <FormField value={name} onChangeText={setName} placeholder=\"Nombre completo *\" maxLength={120} />\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e10 }}>\n              {(['moto', 'bici', 'coche'] as const).map((v) => (\n                <Pressable key={v} onPress={() => setVehicle(v)} accessibilityRole=\"radio\"\n                  accessibilityState={{ checked: vehicle === v }}\n                  style={{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderRadius: radios.lg, backgroundColor: vehicle === v ? colors.primary : colors.surface }}>\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: vehicle === v ? brand.white : colors.textPrimary }}>{VEHICLE_LABEL[v]}</Text>\n                </Pressable>\n              ))}\n            </View>\n            <View style={{ marginTop: espaciado.e10 }} />\n            <FormField value={zone} onChangeText={setZone} placeholder=\"Zona de reparto (Malabo, Bata…)\" maxLength={60} />\n            <View style={{ marginTop: espaciado.e12 }}>\n              <PrimaryButton\n                title={busySave ? 'Guardando…' : (rider ? 'Actualizar perfil' : 'Solicitar alta como repartidor')}\n                onPress={save}\n                disabled={busySave}\n              />\n            </View>\n\n            {rider?.status === 'rejected' && rider.rejectionReason ? (\n              <View style={[s.rejectedBox, { backgroundColor: alpha(colors.danger, 0.08) }]}>\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>Motivo: {rider.rejectionReason}</Text>\n              </View>\n            ) : null}\n\n            {rider?.status === 'pending' ? (\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e14 }}>\n                Tu solicitud está en revisión. Cuando el administrador la apruebe podrás recibir entregas.\n              </Text>\n            ) : null}\n\n            {/* Mis entregas */}\n            {rider?.status === 'active' && (\n              <>\n                <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: espaciado.e22, marginBottom: espaciado.e10 }}>\n                  <Text style={[s.sectionTitle, { marginBottom: 0 }]}>Mis entregas ({me?.deliveries.length ?? 0})</Text>\n                  {rider.deliveriesCount > 0 ? (\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textSecondary }}>\n                      {rider.deliveriesCount} entregas completadas\n                    </Text>\n                  ) : null}\n                </View>\n                {me && me.deliveries.length === 0 ? (\n                  <View style={s_center.wrapSoft}>\n                    <Text style={{ fontSize: 32, marginBottom: espaciado.e6 }}>🛵</Text>\n                    <Text style={[s_center.sub, { color: colors.textSecondary }]}>\n                      Sin entregas asignadas todavía. Cuando un restaurante te asigne un pedido aparecerá aquí con el\n                      tracking y los datos de recogida y entrega.\n                    </Text>\n                  </View>\n                ) : (\n                  me?.deliveries.map((d) => {\n                    const meta = RIDER_NEXT[d.status];\n                    const stLabel = DELIVERY_LABEL[d.status] ?? d.status;\n                    const busy = busyDeliveryId === d.orderId;\n                    return (\n                      <View key={d.id} style={[s.delCard, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e8 }}>\n                          <Text numberOfLines={1} style={{ flex: 1, fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary }}>{d.restaurantName}</Text>\n                          <View style={{ backgroundColor: alpha(ACCENT, 0.12), paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e2, borderRadius: 7 }}>\n                            <Text style={{ fontSize: 10.5, fontWeight: '800', color: ACCENT }}>{stLabel}</Text>\n                          </View>\n                        </View>\n                        <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e2 }}>Tracking {d.trackingCode}</Text>\n                        {d.items.map((it, i) => (\n                          <Text key={`${d.id}-${it.itemId}-${i}`} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>{it.qty} × {it.name}</Text>\n                        ))}\n                        <Text style={{ fontSize: tipografia.caption, fontWeight: '900', color: ACCENT, marginTop: espaciado.e2 }}>{formatXAF(d.totalXaf)}</Text>\n\n                        {/* ── ¿HAY QUE COBRAR EN LA PUERTA? (C5) ────────────────────────────\n                            El repartidor necesita saberlo ANTES de llegar, no al anotar. Sin esto\n                            el servidor sí bloquea la anotación en un pedido Billing, pero el bloqueo\n                            salta después de que el cliente ya soltó el dinero: cobrar dos veces no\n                            queda registrado en ningún sitio. Por eso se pinta aquí arriba.\n                            Si el servidor aún no devuelve el método (parche pendiente), se muestra\n                            el aviso neutro: NO se asume \"cobrar\", porque asumir es el error que se\n                            viene a evitar. */}\n                        {d.paymentMethod === 'cash' ? (\n                          <View style={[s.payBadge, { backgroundColor: alpha(ACCENT, 0.14), borderColor: alpha(ACCENT, 0.4) }]}>\n                            <Text style={{ fontSize: tipografia.caption, fontWeight: '900', color: ACCENT }}>\n                              💵 COBRAR {formatXAF(d.totalXaf)} en la puerta\n                            </Text>\n                          </View>\n                        ) : d.paymentMethod === 'billing' ? (\n                          <View style={[s.payBadge, { backgroundColor: alpha(colors.success, 0.14), borderColor: alpha(colors.success, 0.4) }]}>\n                            <Text style={{ fontSize: tipografia.caption, fontWeight: '900', color: colors.success }}>\n                              ✓ Ya pagado — NO cobrar nada\n                            </Text>\n                          </View>\n                        ) : (\n                          <View style={[s.payBadge, { backgroundColor: alpha(brand.warning, 0.14), borderColor: alpha(brand.warning, 0.4) }]}>\n                            <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: brand.warningText }}>\n                              ⚠️ No consta cómo se paga: pregunta al restaurante antes de cobrar\n                            </Text>\n                          </View>\n                        )}\n                        {d.restaurantAddress ? (\n                          <Text numberOfLines={2} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e3 }}>🏪 Recoger en: {d.restaurantAddress}</Text>\n                        ) : null}\n                        {d.deliveryAddress ? (\n                          <Text numberOfLines={2} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>📍 Entregar en: {d.deliveryAddress}</Text>\n                        ) : null}\n\n                        {/* ── CÓMO LLEGAR ─────────────────────────────────────────────────\n                            La dirección de texto sola no lleva a ningún sitio: «Aeropuerto» no es\n                            navegable. Con el pin del cliente, el botón abre el mapa EN EL PUNTO; sin\n                            pin, cae a buscar el texto (peor, pero mejor que nada). Se ofrece también\n                            antes de salir, no solo al llegar. */}\n                        {d.status !== 'delivered' && (d.deliveryLat != null || d.deliveryAddress) ? (\n                          <Pressable\n                            onPress={() => abrirMapa(d.deliveryLat ?? null, d.deliveryLng ?? null, d.deliveryAddress ?? null)}\n                            accessibilityRole=\"button\"\n                            accessibilityLabel={`Cómo llegar a la entrega${d.deliveryLat != null ? ' (con ubicación exacta)' : ' (por la dirección escrita)'}`}\n                            style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e8, alignSelf: 'flex-start', paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderRadius: 10, borderWidth: 1, borderColor: alpha(ACCENT, 0.5), backgroundColor: alpha(ACCENT, 0.10) }}\n                          >\n                            <Navigation size={14} color={ACCENT} />\n                            <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: ACCENT }}>\n                              Cómo llegar{d.deliveryLat != null ? '' : ' (dirección escrita)'}\n                            </Text>\n                          </Pressable>\n                        ) : null}\n\n                        {/* ── PUNTO DE ENCUENTRO ──────────────────────────────────────────\n                            Para cuando la dirección no basta: hotel, viviendas sociales, portal sin\n                            número. El repartidor dice dónde está y el cliente lo ve al momento. */}\n                        {d.status !== 'delivered' ? (\n                          d.meetingNote ? (\n                            <View style={{ marginTop: espaciado.e8, borderRadius: 10, borderWidth: 1, padding: espaciado.e10, borderColor: alpha(colors.success, 0.4), backgroundColor: alpha(colors.success, 0.08) }}>\n                              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.success }}>🤝 Punto de encuentro avisado</Text>\n                              <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2, lineHeight: 15 }}>{d.meetingNote}</Text>\n                              <Pressable\n                                onPress={() => { setPuntoDe(d.orderId); setPuntoTexto(d.meetingNote ?? ''); setPuntoCoords(null); }}\n                                accessibilityRole=\"button\"\n                                accessibilityLabel=\"Cambiar el punto de encuentro\"\n                                style={{ marginTop: espaciado.e6, alignSelf: 'flex-start' }}\n                              >\n                                <Text style={{ fontSize: tipografia.micro, fontWeight: '700', color: ACCENT }}>Cambiar</Text>\n                              </Pressable>\n                            </View>\n                          ) : puntoDe === d.orderId ? (\n                            <View style={{ marginTop: espaciado.e10 }}>\n                              <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary, marginBottom: espaciado.e4 }}>\n                                ¿Dónde os encontráis? (hotel, portal, entrada…)\n                              </Text>\n                              <TextInput\n                                value={puntoTexto}\n                                onChangeText={setPuntoTexto}\n                                placeholder=\"Ej: entrada por la puerta lateral, junto a la farmacia\"\n                                placeholderTextColor={colors.textSecondary}\n                                maxLength={200}\n                                accessibilityLabel=\"Punto de encuentro\"\n                                style={{ minHeight: 44, borderRadius: 10, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderColor: colors.border, color: colors.textPrimary, backgroundColor: colors.background }}\n                              />\n                              <View style={{ flexDirection: 'row', gap: espaciado.e8, alignItems: 'center', marginTop: espaciado.e8, flexWrap: 'wrap' }}>\n                                <Pressable\n                                  onPress={ubicarmeParaPunto}\n                                  disabled={puntoUbicando}\n                                  accessibilityRole=\"button\"\n                                  accessibilityLabel=\"Usar mi ubicación para el punto de encuentro\"\n                                  style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderRadius: 10, borderWidth: 1, borderColor: colors.border }}\n                                >\n                                  <MapPin size={13} color={colors.textPrimary} />\n                                  <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>\n                                    {puntoUbicando ? 'Buscando…' : puntoCoords ? '✓ Ubicación añadida' : 'Usar mi ubicación'}\n                                  </Text>\n                                </Pressable>\n                                <Pressable\n                                  onPress={() => guardarPunto(d.orderId)}\n                                  disabled={busyDeliveryId === d.orderId}\n                                  accessibilityRole=\"button\"\n                                  accessibilityLabel=\"Avisar al cliente del punto de encuentro\"\n                                  style={{ paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, borderRadius: 10, backgroundColor: ACCENT }}\n                                >\n                                  <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: brand.white }}>\n                                    {busyDeliveryId === d.orderId ? 'Avisando…' : 'Avisar al cliente'}\n                                  </Text>\n                                </Pressable>\n                                <Pressable\n                                  onPress={() => { setPuntoDe(null); setPuntoTexto(''); setPuntoCoords(null); }}\n                                  accessibilityRole=\"button\"\n                                  accessibilityLabel=\"Cancelar el punto de encuentro\"\n                                  style={{ paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e8 }}\n                                >\n                                  <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary }}>Cancelar</Text>\n                                </Pressable>\n                              </View>\n                              <Text style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e4 }}>\n                                El cliente lo verá en su pedido y recibirá un SMS: no hace falta que llames.\n                              </Text>\n                            </View>\n                          ) : (\n                            <Pressable\n                              onPress={() => { setPuntoDe(d.orderId); setPuntoTexto(''); setPuntoCoords(null); }}\n                              accessibilityRole=\"button\"\n                              accessibilityLabel=\"Indicar el punto de encuentro al cliente\"\n                              style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e8, alignSelf: 'flex-start', paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, borderRadius: 10, borderWidth: 1, borderColor: colors.border }}\n                            >\n                              <MapPin size={14} color={colors.textPrimary} />\n                              <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>Punto de encuentro</Text>\n                            </Pressable>\n                          )\n                        ) : null}\n\n                        {d.note ? (\n                          <Text numberOfLines={2} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>📝 {d.note}</Text>\n                        ) : null}\n\n                        {/* Contactos operativos (solo el rider asignado) */}\n                        <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n                          <CallBtn phone={d.restaurantPhone} label=\"Llamar al restaurante\" />\n                          <CallBtn phone={d.clientPhone} label=\"Llamar al cliente\" />\n                        </View>\n\n                        {/* ── LO QUE COBRÉ EN LA PUERTA ────────────────────────────────────\n                            Solo en entregas ya cerradas: es cuando de verdad se ha cobrado. El campo\n                            va EN LÍNEA (no en un diálogo) porque `Alert.prompt` es solo de iOS y\n                            esta app es Android: con un diálogo, el repartidor no podría anotar nada\n                            y su liquidación saldría descuadrada sin que nadie supiera por qué. */}\n                        {d.status === 'delivered' ? (\n                          cobroDe === d.orderId ? (\n                            <View style={{ marginTop: espaciado.e10 }}>\n                              <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary, marginBottom: espaciado.e4 }}>\n                                ¿Cuánto cobraste en la puerta? (el pedido era de {formatXAF(d.totalXaf)}; si ya estaba pagado, pon 0)\n                              </Text>\n                              <View style={{ flexDirection: 'row', gap: espaciado.e8, alignItems: 'center' }}>\n                                <TextInput\n                                  value={cobroTexto}\n                                  onChangeText={setCobroTexto}\n                                  keyboardType=\"number-pad\"\n                                  placeholder=\"0\"\n                                  placeholderTextColor={colors.textSecondary}\n                                  accessibilityLabel=\"Efectivo cobrado en esta entrega\"\n                                  style={{ flex: 1, height: 44, borderRadius: 10, borderWidth: 1, paddingHorizontal: espaciado.e12, borderColor: colors.border, color: colors.textPrimary, backgroundColor: colors.background }}\n                                />\n                                <Pressable onPress={() => guardarCobro(d.orderId)} disabled={busy}\n                                  accessibilityRole=\"button\" accessibilityLabel=\"Guardar el efectivo cobrado\"\n                                  style={[s.advBtn, { backgroundColor: ACCENT, marginTop: 0, paddingHorizontal: espaciado.e16 }]}>\n                                  {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Guardar</Text>}\n                                </Pressable>\n                                <Pressable onPress={() => { setCobroDe(null); setCobroTexto(''); }}\n                                  accessibilityRole=\"button\" accessibilityLabel=\"Cancelar la anotación\"\n                                  style={{ paddingHorizontal: espaciado.e6 }}>\n                                  <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.caption }}>Cancelar</Text>\n                                </Pressable>\n                              </View>\n                            </View>\n                          ) : (\n                            <Pressable\n                              onPress={() => {\n                                setCobroDe(d.orderId);\n                                // Pre-rellenar con el total SOLO si el pedido era contra entrega.\n                                // En un pedido Billing ya está pagado y lo correcto es 0: dejar el\n                                // total por defecto empuja a cobrar dos veces. Y si el servidor aún\n                                // no dice el método (parche C5 pendiente), se deja VACÍO para que el\n                                // repartidor escriba el importe a sabiendas en vez de confirmar un\n                                // número que ya venía puesto.\n                                setCobroTexto(\n                                  d.paymentMethod === 'cash' ? String(Math.round(Number(d.totalXaf) || 0))\n                                  : d.paymentMethod === 'billing' ? '0'\n                                  : '',\n                                );\n                              }}\n                              accessibilityRole=\"button\"\n                              accessibilityLabel=\"Anotar el efectivo que cobré en esta entrega\"\n                              style={{ marginTop: espaciado.e8, alignSelf: 'flex-start' }}\n                            >\n                              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.primary }}>\n                                💵 Anotar lo que cobré\n                              </Text>\n                            </Pressable>\n                          )\n                        ) : null}\n\n                        {meta?.next ? (\n                          busy ? (\n                            <ActivityIndicator style={{ marginTop: espaciado.e10 }} size=\"small\" color={colors.primary} />\n                          ) : (\n                            <Pressable\n                              onPress={() => requestAdvance(d)}\n                              accessibilityRole=\"button\"\n                              accessibilityLabel={meta.btn.replace(/^[^\\s]+\\s/, '')}\n                              style={[s.advBtn, { backgroundColor: ACCENT }]}\n                            >\n                              <Text style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '800' }}>{meta.btn}</Text>\n                            </Pressable>\n                          )\n                        ) : null}\n                      </View>\n                    );\n                  })\n                )}\n              </>\n            )}\n          </ScrollView>\n        </KeyboardAvoidingView>\n      )}\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\nfunction CallBtn({ phone, label }: { phone: string | null; label: string }) {\n  const { colors } = useTheme();\n  const digits = (phone ?? '').replace(/\\D/g, '');\n  if (!digits) return <View />;\n  return (\n    <Pressable\n      onPress={() => Linking.openURL(`tel:${digits}`).catch(() => undefined)}\n      accessibilityRole=\"button\"\n      accessibilityLabel={label}\n      style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e5, borderWidth: 1, borderColor: colors.primary, borderRadius: 9, paddingVertical: espaciado.e8 }}\n    >\n      <Phone size={13} color={colors.primary} />\n      <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nfunction ReqRow({ ok, label, hint, onPress }: { ok: boolean; label: string; hint?: string; onPress?: () => void }) {\n  const { colors } = useTheme();\n  const row = (\n    <View style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e5 }}>\n      {ok ? <BadgeCheck size={16} color={brand.success} /> : <XCircle size={16} color=\"#CBD5E1\" />}\n      <View style={{ flex: 1, marginLeft: espaciado.e8 }}>\n        <Text style={{ fontSize: tipografia.caption, fontWeight: '600', color: ok ? colors.textPrimary : colors.textSecondary }}>{label}</Text>\n        {hint ? <Text style={{ fontSize: 10.5, color: onPress ? colors.primary : colors.textSecondary }}>{hint}</Text> : null}\n      </View>\n      {onPress ? <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>→</Text> : null}\n    </View>\n  );\n  return onPress ? (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityLabel={`${label}. ${hint ?? ''}`} style={{ paddingVertical: espaciado.e2 }}>\n      {row}\n    </Pressable>\n  ) : row;\n}\n\nconst s_center = StyleSheet.create({\n  wrap: { alignItems: 'center', paddingTop: 56, paddingHorizontal: espaciado.e28 },\n  wrapSoft: { alignItems: 'center', paddingTop: espaciado.e24, paddingHorizontal: espaciado.e20 },\n  title: { fontSize: 15, fontWeight: '800', textAlign: 'center' },\n  sub: { fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e6, lineHeight: 18 },\n  btnPrimary: { marginTop: espaciado.e18, backgroundColor: ACCENT, paddingHorizontal: espaciado.e24, paddingVertical: espaciado.e11, borderRadius: 22 },\n});\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  reqBox: { borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e14 },\n  sectionTitle: { fontSize: tipografia.body, fontWeight: '800', marginBottom: espaciado.e10 },\n  rejectedBox: { borderRadius: 10, padding: espaciado.e10, marginTop: espaciado.e12 },\n  delCard: { borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e10, borderWidth: 1 },\n  advBtn: { marginTop: espaciado.e10, borderRadius: 10, paddingVertical: espaciado.e11, alignItems: 'center' },\n  // Distintivo de «cobrar en la puerta» (C5): se ve antes de llegar, no al anotar.\n  payBadge: { borderRadius: 9, borderWidth: 1, paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e6, marginTop: espaciado.e6, alignSelf: 'flex-start' },\n});\n","/**\n * FoodScreen — Home de Comida Rápida: restaurantes activos con búsqueda\n * server-side (debounce), filtros por cocina y ciudad (Malabo/Bata), tarjeta\n * con foto, abierto/cerrado calculado en el servidor (hora de Malabo), rating\n * y radio de reparto.\n * v3 (paginación): catálogo paginado en el servidor (?page&limit, total y\n * hasMore) con infinite scroll, footer con estados propios (cargando más /\n * error con Reintentar / fin de resultados), skeleton inicial y pull-to-refresh\n * que conserva la lista. Ruta: /food\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { ActivityIndicator, FlatList, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Bike, Search, Utensils } from 'lucide-react-native';\nimport { alpha, EmptyState, espaciado, radios, ScreenHeader, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { foodApi, FoodCuisine, FoodRestaurant, FoodRestaurantsPage } from '../api/food';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst FOOD_CITIES = ['Malabo', 'Bata'];\nconst PAGE_SIZE = 20;\nconst SKELETONS = [0, 1, 2, 3];\n\nexport default function FoodScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [restaurants, setRestaurants] = useState<FoodRestaurant[]>([]);\n  const [cuisines, setCuisines] = useState<FoodCuisine[]>([]);\n  const [q, setQ] = useState('');\n  const [cuisine, setCuisine] = useState('');\n  const [city, setCity] = useState('');\n  const [total, setTotal] = useState(0);\n  const [page, setPage] = useState(1);\n  const [pageSize, setPageSize] = useState(PAGE_SIZE);\n  const [hasMore, setHasMore] = useState(false);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [loadMoreError, setLoadMoreError] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  // Evita aplicar respuestas obsoletas si el usuario cambia filtros mientras\n  // una petición (primera página o más) está en vuelo.\n  const reqId = useRef(0);\n\n  // Las cocinas no cambian con los filtros: se cargan una sola vez.\n  useEffect(() => {\n    let alive = true;\n    foodApi.cuisines().then((c) => { if (alive) setCuisines(c); }).catch(() => undefined);\n    return () => { alive = false; };\n  }, []);\n\n  const buildQs = useCallback((pg: number): Record<string, string> => {\n    const qs: Record<string, string> = { page: String(pg), limit: String(PAGE_SIZE) };\n    if (cuisine) qs.cuisine = cuisine;\n    if (city) qs.city = city;\n    const t = q.trim();\n    if (t) qs.q = t;\n    return qs;\n  }, [cuisine, city, q]);\n\n  /** Primera página (filtros/búsqueda): vacía la lista para nunca mostrar\n   *  datos stale; skeleton mientras carga. */\n  const loadFirst = useCallback(async () => {\n    const id = ++reqId.current;\n    setLoading(true);\n    setError(null);\n    setRestaurants([]);\n    setLoadMoreError(false);\n    try {\n      const r = await foodApi.restaurants(buildQs(1));\n      if (id !== reqId.current) return;\n      apply(r);\n    } catch {\n      if (id !== reqId.current) return;\n      setError('No pudimos cargar los restaurantes. Revisa tu conexión e inténtalo de nuevo.');\n      setRestaurants([]);\n      setTotal(0);\n      setHasMore(false);\n    } finally {\n      if (id === reqId.current) setLoading(false);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [buildQs]);\n\n  const apply = (r: FoodRestaurantsPage) => {\n    setRestaurants(r.items);\n    setTotal(r.total);\n    setPage(r.page);\n    setPageSize(r.limit);\n    setHasMore(r.hasMore);\n    setLoadMoreError(false);\n  };\n\n  /** Pull-to-refresh: conserva la lista visible mientras refresca. */\n  const refresh = useCallback(async () => {\n    const id = reqId.current;\n    setRefreshing(true);\n    try {\n      const r = await foodApi.restaurants(buildQs(1));\n      if (id !== reqId.current) return;\n      apply(r);\n      setError(null);\n    } catch {\n      // Pull-to-refresh fallido: se conserva la lista ya cargada.\n    } finally {\n      if (id === reqId.current) setRefreshing(false);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [buildQs]);\n\n  /** Infinite scroll: añade la siguiente página al final de la lista. */\n  const loadMore = useCallback(async () => {\n    if (loading || refreshing || loadingMore || !hasMore) return;\n    const id = reqId.current;\n    const next = page + 1;\n    setLoadingMore(true);\n    setLoadMoreError(false);\n    try {\n      const r = await foodApi.restaurants(buildQs(next));\n      if (id !== reqId.current) return;\n      setRestaurants((prev) => [...prev, ...r.items]);\n      setTotal(r.total);\n      setPage(r.page);\n      setPageSize(r.limit);\n      setHasMore(r.hasMore);\n    } catch {\n      if (id !== reqId.current) return;\n      setLoadMoreError(true);\n    } finally {\n      if (id === reqId.current) setLoadingMore(false);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [loading, refreshing, loadingMore, hasMore, page, buildQs]);\n\n  // Búsqueda y filtros con debounce de 300 ms.\n  useEffect(() => {\n    const t = setTimeout(() => { loadFirst(); }, 300);\n    return () => clearTimeout(t);\n  }, [loadFirst]);\n\n  const hasFilters = !!cuisine || !!city || !!q.trim();\n\n  const listData: FoodRestaurant[] = useMemo(() => {\n    if (loading && !restaurants.length) return SKELETONS.map((i) => ({ id: `__sk_${i}` } as FoodRestaurant));\n    return restaurants;\n  }, [loading, restaurants]);\n\n  const isSkeleton = (id: string) => id.startsWith('__sk_');\n  const showEndNote = !hasMore && !loadingMore && total > pageSize;\n\n  const s = styles(colors);\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Cabecera del kit desde el 24/09/2026. Las dos acciones van en `accion`. */}\n      <ScreenHeader\n        titulo=\"Comida Rápida\"\n        alVolver={() => router.back()}\n        accion={\n          <>\n            <Tactil onPress={() => router.push('/food-rider' as any)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Ser repartidor\">\n              <Bike size={20} color={colors.primary} />\n            </Tactil>\n            <Tactil onPress={() => router.push('/food-owner' as any)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Mi restaurante\">\n              <Utensils size={20} color={colors.primary} />\n            </Tactil>\n          </>\n        }\n      />\n\n      <FlatList\n        data={listData}\n        keyExtractor={(item) => item.id}\n        contentContainerStyle={s.listContent}\n        keyboardShouldPersistTaps=\"handled\"\n        refreshing={refreshing}\n        onRefresh={refresh}\n        onEndReached={loadMore}\n        onEndReachedThreshold={0.4}\n        ListHeaderComponent={\n          <View>\n            {/* Búsqueda server-side */}\n            <View style={s.searchBox}>\n              <Search size={16} color={colors.textSecondary} />\n              <TextInput\n                value={q}\n                onChangeText={setQ}\n                placeholder=\"Buscar restaurante, plato o ciudad…\"\n                placeholderTextColor={colors.textSecondary}\n                accessibilityLabel=\"Buscar restaurantes\"\n                returnKeyType=\"search\"\n                autoCorrect={false}\n                style={s.searchInput}\n              />\n            </View>\n\n            {/* Ciudad */}\n            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8, paddingRight: espaciado.e16 }}>\n              <Chip label=\"📍 Todas\" active={city === ''} onPress={() => setCity('')} />\n              {FOOD_CITIES.map((c) => (\n                <Chip key={c} label={c} active={city === c} onPress={() => setCity(city === c ? '' : c)} />\n              ))}\n            </ScrollView>\n\n            {/* Cocina */}\n            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginTop: espaciado.e8 }} contentContainerStyle={{ gap: espaciado.e8, paddingRight: espaciado.e16 }}>\n              <Chip label=\"✨ Todas\" active={cuisine === ''} onPress={() => setCuisine('')} />\n              {cuisines.map((c) => (\n                <Chip key={c.id} label={c.label} icon={c.icon} active={cuisine === c.id}\n                  onPress={() => setCuisine(cuisine === c.id ? '' : c.id)} />\n              ))}\n            </ScrollView>\n\n            {!error && (\n              <Text style={s.resultsLabel}>\n                {loading ? 'Cargando…' : `${total} restaurante${total === 1 ? '' : 's'} · pide y recoge o recibe en casa`}\n              </Text>\n            )}\n          </View>\n        }\n        ListEmptyComponent={\n          error ? (\n            <EmptyState\n              icono={<Text style={{ fontSize: 40 }}>📡</Text>}\n              titulo=\"Algo salió mal\"\n              texto={error}\n              accionLabel=\"Reintentar\"\n              onAccion={loadFirst}\n              accionPrimaria\n            />\n          ) : loading ? null : (\n            <EmptyState\n              icono={<Text style={{ fontSize: 40 }}>🍽️</Text>}\n              titulo={hasFilters ? 'Sin resultados con estos filtros' : 'Todavía no hay restaurantes'}\n              texto={hasFilters\n                ? 'Prueba a quitar filtros o buscar en otra ciudad.'\n                : 'Sé el primero en tu zona: identidad verificada y aprobación del administrador.'}\n              accionLabel={hasFilters ? 'Quitar filtros' : 'Registra tu restaurante'}\n              accionPrimaria={!hasFilters}\n              onAccion={hasFilters\n                ? () => { setCuisine(''); setCity(''); setQ(''); }\n                : () => router.push('/food-owner' as any)}\n            />\n          )\n        }\n        ListFooterComponent={\n          loadingMore ? (\n            <View style={s.footerNote}><ActivityIndicator size=\"small\" color={colors.primary} /></View>\n          ) : loadMoreError ? (\n            <Pressable onPress={loadMore} style={s.footerNote} accessibilityRole=\"button\">\n              <Text style={[s.footerText, { color: colors.primary }]}>No se pudieron cargar más restaurantes · Reintentar</Text>\n            </Pressable>\n          ) : showEndNote ? (\n            <View style={s.footerNote}><Text style={[s.footerText, { color: colors.textSecondary }]}>Ya están todos · fin de resultados</Text></View>\n          ) : null\n        }\n        renderItem={({ item }) =>\n          isSkeleton(item.id) ? (\n            <RestaurantSkeleton key={item.id} colors={colors} />\n          ) : (\n            <RestaurantCard\n              key={item.id}\n              item={item}\n              onPress={() => router.push({ pathname: '/food-menu', params: { id: item.id } } as any)}\n            />\n          )\n        }\n      />\n    </View>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Componentes\n// ---------------------------------------------------------------------------\n\nfunction Chip({ label, icon, active, onPress }: { label: string; icon?: string | null; active: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityLabel={label} accessibilityState={{ selected: active }}\n      style={[s_chip.base, { backgroundColor: active ? colors.primary : colors.surface, borderColor: active ? colors.primary : colors.border }]}>\n      {icon ? <Text style={{ fontSize: tipografia.body }}>{icon}</Text> : null}\n      <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: active ? brand.white : colors.textPrimary }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nfunction RestaurantCard({ item, onPress }: { item: FoodRestaurant; onPress: () => void }) {\n  const { colors } = useTheme();\n  // Guard de URL: solo se renderiza la foto si el servidor devolvió una URL\n  // http(s) real (photoUrl); nunca una key de objeto suelta.\n  const photo = item.photoUrl && /^https?:\\/\\//i.test(item.photoUrl) ? item.photoUrl : null;\n  const showRating = item.ratingCount > 0 && Number.isFinite(item.ratingAvg);\n  const km = Number.isFinite(item.deliveryKm) && item.deliveryKm > 0 ? item.deliveryKm : 0;\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\"\n      accessibilityLabel={`${item.businessName}, ${item.cuisineLabel ?? 'restaurante'} en ${item.city}${item.isOpen !== null ? (item.isOpen ? ', abierto' : ', cerrado') : ''}`}\n      style={[s_card.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n      {photo ? (\n        <Image source={{ uri: photo }} style={s_card.img} contentFit=\"cover\" transition={200} />\n      ) : (\n        <View style={[s_card.img, s_card.imgFallback]}>\n          <Text style={{ fontSize: 34 }}>{item.cuisineIcon ?? '🍽️'}</Text>\n        </View>\n      )}\n      <View style={s_card.body}>\n        <View style={s_card.titleRow}>\n          <Text numberOfLines={1} style={[s_card.name, { color: colors.textPrimary }]}>{item.businessName}</Text>\n          {showRating && (\n            <Text style={[s_card.rating, { color: colors.secondary }]}>★ {item.ratingAvg.toFixed(1)}</Text>\n          )}\n        </View>\n        {/* Fila badges estilo Meituan: estado + cocina */}\n        <View style={[s_card.badgeRow, { marginTop: espaciado.e4 }]}>\n          {item.isOpen !== null && (\n            <View style={[s_card.chip, { backgroundColor: item.isOpen ? 'rgba(16,185,129,0.12)' : 'rgba(239,68,68,0.1)' }]}>\n              <View style={[s_card.dot, { backgroundColor: item.isOpen ? brand.success : brand.danger }]} />\n              <Text style={[s_card.chipText, { color: item.isOpen ? brand.success : brand.danger }]}>\n                {item.isOpen ? 'Abierto' : 'Cerrado'}\n              </Text>\n            </View>\n          )}\n          {item.cuisineLabel && (\n            <View style={[s_card.chip, { backgroundColor: alpha(colors.secondary, 0.1) }]}>\n              <Text style={[s_card.chipText, { color: colors.secondary }]} numberOfLines={1}>{item.cuisineLabel}</Text>\n            </View>\n          )}\n        </View>\n        {/* Línea de ciudad + meta de entrega (patrón Meituan) */}\n        <Text numberOfLines={1} style={[s_card.sub, { color: colors.textSecondary, marginTop: espaciado.e4 }]}>\n          📍 {item.city}{item.address ? ` · ${item.address}` : ''}\n        </Text>\n        <View style={s_card.metaRow}>\n          <Text numberOfLines={1} style={[s_card.meta, { color: brand.secondary }]}>\n            {km > 0 ? `🛵 Reparto hasta ${km} km` : (item.hours ? `🕐 ${item.hours}` : 'Pide y recoge')}\n          </Text>\n          {showRating && (\n            <Text style={{ fontSize: 10.5, color: colors.textSecondary, fontWeight: '600' }}>\n              {item.ratingCount} valoraciones\n            </Text>\n          )}\n        </View>\n      </View>\n    </Pressable>\n  );\n}\n\nfunction RestaurantSkeleton({ colors }: { colors: ReturnType<typeof useTheme>['colors'] }) {\n  return (\n    <View style={[s_sk.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n      <View style={{ width: 90, height: 90, backgroundColor: colors.border }} />\n      <View style={{ flex: 1, padding: espaciado.e12, gap: espaciado.e8 }}>\n        <View style={{ height: 12, borderRadius: 4, backgroundColor: colors.border, width: '72%' }} />\n        <View style={{ height: 10, borderRadius: 4, backgroundColor: colors.border, width: '46%' }} />\n        <View style={{ height: 10, borderRadius: 4, backgroundColor: colors.border, width: '60%' }} />\n      </View>\n    </View>\n  );\n}\n\n\nconst s_chip = StyleSheet.create({\n  base: { paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, borderRadius: 18, flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, borderWidth: 1 },\n});\n\nconst s_card = StyleSheet.create({\n  card: { flexDirection: 'row', borderRadius: radios.lg, overflow: 'hidden', borderWidth: 1, marginBottom: espaciado.e10 },\n  img: { width: 104, height: 104 },\n  imgFallback: { backgroundColor: 'rgba(255,107,53,0.08)', alignItems: 'center', justifyContent: 'center' },\n  body: { flex: 1, padding: espaciado.e12 },\n  titleRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e8 },\n  name: { fontSize: 15.5, fontWeight: '800', flex: 1 },\n  rating: { fontSize: tipografia.body, fontWeight: '900' },\n  badgeRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 },\n  chip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, borderRadius: radios.sm, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3, maxWidth: '60%' },\n  dot: { width: 6, height: 6, borderRadius: 3 },\n  chipText: { fontSize: 10.5, fontWeight: '800', flexShrink: 1 },\n  sub: { fontSize: tipografia.micro, fontWeight: '600' },\n  metaRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e8, marginTop: espaciado.e6 },\n  meta: { fontSize: tipografia.caption, fontWeight: '800', flexShrink: 1 },\n});\n\nconst s_sk = StyleSheet.create({\n  card: { flexDirection: 'row', borderRadius: 14, overflow: 'hidden', borderWidth: 1, marginBottom: espaciado.e10 },\n});\n\n\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  root: { flex: 1, backgroundColor: c.background },\n  searchBox: { flexDirection: 'row', alignItems: 'center', marginTop: espaciado.e12, backgroundColor: c.surface, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, borderWidth: 1, borderColor: c.border },\n  searchInput: { flex: 1, color: c.textPrimary, fontSize: tipografia.body, marginLeft: espaciado.e8 },\n  resultsLabel: { fontSize: tipografia.caption, fontWeight: '700', color: c.textSecondary, marginTop: espaciado.e14, marginBottom: espaciado.e10 },\n  listContent: { paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e32 },\n  footerNote: { paddingVertical: espaciado.e16, alignItems: 'center' },\n  footerText: { fontSize: tipografia.caption, fontWeight: '700' },\n});\n","/**\n * HomeScreen — EG Route Plan.\n * Composición: MapBackground (100%) + LocationBadge + MapTools +\n * BottomSheet deslizable (SearchHeader / ServiceGrid / PromoCarousel) +\n * FloatingFooter + LocationModal + EmergencyModal.\n *\n * Auditoría bottom-sheet v5 (2026-09-02):\n *  · collapse() (no snapToIndex, deprecado/inestable) + Keyboard.dismiss.\n *  · enableDynamicSizing={false} (snap points fijos en %) y\n *    enablePanDownToClose={false}: el sheet NUNCA se cierra del todo (el mapa\n *    queda siempre visible arriba). Por eso tampoco hay backdrop de\n *    tap-to-close: cerrar el sheet dejaría el footer sin recuperación y\n *    atenuaría el mapa en el estado colapsado (trampa de UX, no aplica aquí).\n *  · keyboardBehavior=\"interactive\" + blur restore (el teclado no tapa).\n *  · paddingBottom con safe-area inferior real (insets), no constante mágica.\n *  · COLLAPSED derivado del snap point ('36%') para no desincronizar footer.\n *  · La búsqueda aterriza en un SERVICIO real si el texto lo nombra (comida,\n *    mercado, taxi, alquiler…); si no, va a Llamar Taxi. Nunca a un stub.\n *  · Tarjeta de tarifa con la ciudad elegida (no \"Malabo\" fijo).\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { Keyboard, StyleSheet, View, useWindowDimensions } from 'react-native';\nimport BottomSheet, { BottomSheetScrollView } from '@gorhom/bottom-sheet';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { BlurView } from 'expo-blur';\nimport { useTheme } from '../theme/ThemeContext';\nimport MapBackground from '../components/MapBackground';\nimport { EgMarkers, EgCamera, type EgMapViewHandle } from '../packages/map';\nimport SocialHomeHeader, { homeBannerHeight } from '../components/SocialHomeHeader';\nimport LocationModal from '../components/LocationModal';\nimport MapTools from '../components/MapTools';\nimport SearchHeader from '../components/SearchHeader';\nimport ServiceGrid from '../components/ServiceGrid';\nimport PromoCarousel from '../components/PromoCarousel';\nimport FareQuoteCard from '../components/FareQuoteCard';\nimport FloatingFooter, { DOCK_BODY_H, type FooterTab } from '../components/FloatingFooter';\nimport EmergencyModal from '../components/EmergencyModal';\nimport { CITIES, SERVICES, type City } from '../constants/data';\nimport { CITY_CENTERS, CITY_ZOOM, MALABO_CENTER } from '../constants/geo';\nimport { takeGeoPick } from '../state/geoPick';\nimport { getCurrentGqPosition, nearestCityName as nearestCityOf } from '../api/locate';\nimport { reverseGeocode, pickReverseLabel } from '../api/geocode';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { elevation, espaciado } from '@egrouteplan/ui-kit';\n\n// Única fuente de verdad de los snap points.\nconst SNAP = ['36%', '64%', '92%'] as const;\n/** El dock inferior ocupa su franja: la BottomSheet se apoya encima (no se solapan). */\nconst dockBottomInset = (insetsBottom: number) => DOCK_BODY_H + insetsBottom + 6;\n\n\nexport default function HomeScreen() {\n  const { colors, isDark } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { height: winH } = useWindowDimensions();\n  const mapRef = useRef<EgMapViewHandle>(null);\n  const sheetRef = useRef<BottomSheet>(null);\n\n  const snapPoints = useMemo(() => [...SNAP], []);\n  const [sheetIndex, setSheetIndex] = useState(0);\n  const [city, setCity] = useState<City>(CITIES[0]); // Malabo por defecto\n  const [locationOpen, setLocationOpen] = useState(false);\n  const [emergencyOpen, setEmergencyOpen] = useState(false);\n  const [tab, setTab] = useState<FooterTab>('inicio');\n  // Punto seleccionado en el mapa (pin naranja): lo pones al tocar el mapa o\n  // al elegir ciudad; la cámara vuela a él.\n  const [picked, setPicked] = useState<[number, number] | null>(null);\n  // ORIGEN real (ubicación de partida) por ciudad: dirección conocida dentro\n  // de la ciudad, no el nombre genérico de la ciudad (estilo DiDi: el origen\n  // se refleja con su PIN en el mapa).\n  const originFor = useCallback((c: City): { coord: [number, number]; label: string } => {\n    if (c.id === 'malabo') return { coord: [8.7761, 3.7542], label: 'Av. de la Independencia, Malabo' };\n    if (c.id === 'bata') return { coord: [9.7652, 1.8625], label: 'Av. de las Naciones Unidas, Bata' };\n    const coord = CITY_CENTERS[c.id] ?? MALABO_CENTER;\n    return { coord, label: `Centro de ${c.name}` };\n  }, []);\n  const [origin, setOrigin] = useState<{ coord: [number, number]; label: string }>(() => originFor(CITIES[0]));\n\n  const flyTo = useCallback((coord: [number, number], zoom: number, ms = 600) => {\n    setPicked(coord);\n    mapRef.current?.setCamera({ centerCoordinate: coord, zoomLevel: zoom, durationMs: ms });\n  }, []);\n\n  /** Tocar un punto del mapa = elegir DESTINO y pedir taxi (DiDi): marca el\n   *  punto, resuelve su nombre real y entra en /taxi con ese destino, donde\n   *  se dibuja la ruta desde la ubicación actual de la tarjeta. */\n  const handleMapPress = useCallback(async (coord: [number, number]) => {\n    flyTo(coord, 15, 350);\n    let label = 'Destino en el mapa';\n    try {\n      const res = await reverseGeocode(coord[0], coord[1]);\n      const n = pickReverseLabel(res);\n      if (n) label = n;\n    } catch { /* seguimos con la etiqueta genérica */ }\n    router.push({\n      pathname: '/taxi',\n      params: {\n        city: city.name,\n        dLat: coord[1].toFixed(6),\n        dLng: coord[0].toFixed(6),\n        dLabel: label,\n      },\n    } as never);\n  }, [flyTo, router, city]);\n\n  /** Elegir ciudad en el modal → origen = dirección real + cámara vuela. */\n  const selectCity = useCallback((c: City) => {\n    setCity(c);\n    const o = originFor(c);\n    setOrigin(o);\n    setPicked(null);\n    mapRef.current?.setCamera({ centerCoordinate: o.coord, zoomLevel: 14, durationMs: 500 });\n  }, [originFor]);\n\n  /** Ubicarme ahora: GPS real fresco si el dispositivo está en GQ; si no\n   *  (sin permiso o fuera del país), vuelve al origen de la ciudad activa. */\n  const recenter = useCallback(async () => {\n    setPicked(null);\n    const gps = await getCurrentGqPosition();\n    if (!gps) {\n      mapRef.current?.setCamera({ centerCoordinate: origin.coord, zoomLevel: 14, durationMs: 500 });\n      return;\n    }\n    let label = '';\n    try {\n      const res = await reverseGeocode(gps[0], gps[1]);\n      label = pickReverseLabel(res) ?? '';\n    } catch { /* sin nombre: usamos ciudad */ }\n    const cn = nearestCityOf(gps);\n    const cityMatch = CITIES.find((x) => x.name === cn);\n    setOrigin({ coord: gps, label: label || `Mi ubicación · ${cn || city?.name || 'Malabo'}` });\n    if (cityMatch) setCity(cityMatch);\n    // Punto EXACTO en el que estás ahora, no la dirección por defecto.\n    mapRef.current?.setCamera({ centerCoordinate: gps, zoomLevel: 16, durationMs: 400 });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [origin]);\n\n  // La cámara inicial la fija MapBackground vía `initialCamera` (origen real de\n  // Malabo en el primer arranque): evita el race montaje ↔ WebView aún no\n  // ready, que hacía abrir la Home en la vista isla en arranque en frío.\n\n  // Al volver del buscador con un ORIGEN nuevo (modo=origen), aplicarlo como\n  // punto de partida real (comportamiento DiDi: eliges dirección y vuelves).\n  useFocusEffect(\n    useCallback(() => {\n      const gp = takeGeoPick();\n      if (!gp || gp.mode !== 'origen' || !gp.coord) return;\n      if (gp.coord[0] === 0 && gp.coord[1] === 0) return; // elección de ciudad, sin coordenada\n      const label = gp.label && gp.label.trim() ? gp.label.trim() : 'Mi ubicación';\n      setOrigin({ coord: [gp.coord[0], gp.coord[1]], label });\n      setPicked(null);\n      mapRef.current?.setCamera({ centerCoordinate: [gp.coord[0], gp.coord[1]], zoomLevel: 15, durationMs: 500 });\n    }, []),\n  );\n\n  const handleNavigate = useCallback(\n    (next: FooterTab) => {\n      setTab(next);\n      // Lazy Auth: Monedero y Perfil navegan directamente; el AuthGate de\n      // cada pantalla muestra el Glass Pane + modal lazy si hace falta.\n      if (next === 'lifebook') irSeguro.libre('/lifebook');\n      if (next === 'mensajes') irSeguro.libre('/lifebook-messages');\n      if (next === 'taxi') router.push({ pathname: '/taxi', params: { city: city.name } } as any);\n      if (next === 'monedero') router.push('/monedero' as any);\n      if (next === 'perfil') router.push('/profile' as any);\n      if (next === 'inicio') {\n        // v5: collapse() (snapToIndex está deprecado/inestable).\n        sheetRef.current?.collapse();\n        Keyboard.dismiss();\n      }\n    },\n    [router, city],\n  );\n\n  const handleSheetChange = useCallback((index: number) => {\n    setSheetIndex(index);\n    if (index === 0) Keyboard.dismiss(); // teclado no tapa el mapa al colapsar\n  }, []);\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background }]}>\n      {/* 1. Mapa a pantalla completa; pin origen = pill DiDi con la dirección real.\n          Abre centrado en el origen real (no en la vista isla). */}\n      <MapBackground\n        ref={mapRef}\n        onMapPress={handleMapPress}\n        pin={picked}\n        initialCamera={{ centerCoordinate: origin.coord, zoomLevel: 14 }}\n      >\n        <EgCamera centerCoordinate={origin.coord} zoomLevel={14} animationMode=\"moveTo\" />\n        <EgMarkers\n          markers={[\n            { id: 'origin', coordinate: origin.coord, kind: 'origin' as const, label: origin.label },\n          ]}\n        />\n      </MapBackground>\n\n      {/* 2. Cabecera: capa perfil SIEMPRE + capa publicidad superpuesta */}\n      <SocialHomeHeader cityName={city.name} onPressCity={() => setLocationOpen(true)} />\n      {/* Botones flotantes (Emergencia · Ubicarme · Escanear) SIEMPRE bajo el banner */}\n      <MapTools\n        onRecenter={recenter}\n        recenterLabel=\"Ubicarme ahora\"\n        topOffset={homeBannerHeight(winH) + 8}\n        onEmergency={() => setEmergencyOpen(true)}\n      />\n\n      {/* 3. Panel deslizable (se apoya sobre el dock; el mapa queda visible).\n          Fondo GLASS (BlurView) para que el mapa se vea a través. */}\n      <BottomSheet\n        ref={sheetRef}\n        index={0}\n        snapPoints={snapPoints}\n        bottomInset={dockBottomInset(insets.bottom)}\n        onChange={handleSheetChange}\n        backgroundComponent={SheetGlassBackground}\n        handleIndicatorStyle={{ backgroundColor: isDark ? 'rgba(255,255,255,0.35)' : 'rgba(0,0,0,0.18)', width: 44 }}\n        style={styles.sheet}\n        enableDynamicSizing={false}\n        enablePanDownToClose={false}\n        keyboardBehavior=\"interactive\"\n        keyboardBlurBehavior=\"restore\"\n      >\n        <BottomSheetScrollView\n          contentContainerStyle={[styles.sheetContent, { paddingBottom: espaciado.e24 + insets.bottom }]}\n          showsVerticalScrollIndicator={false}\n          keyboardShouldPersistTaps=\"handled\"\n          keyboardDismissMode=\"on-drag\"\n        >\n          <SearchHeader\n            city={origin.label}\n            cityName={city.name}\n            onPressCity={() => irSeguro.libre('/buscar', { city: city.name, mode: 'origen' })}\n            glass\n          />\n          <ServiceGrid onEmergencyPress={() => setEmergencyOpen(true)} glass />\n          <FareQuoteCard distanceKm={3.5} city={city.name} />\n          <PromoCarousel />\n        </BottomSheetScrollView>\n      </BottomSheet>\n\n      {/* 4. Dock de navegación inferior SIEMPRE visible (mapa + hoja por encima) */}\n      <FloatingFooter\n        active={tab}\n        onNavigate={handleNavigate}\n        onEmergency={() => setEmergencyOpen(true)}\n        showUnreadBadge\n      />\n\n      {/* 5. Modales */}\n      <LocationModal\n        visible={locationOpen}\n        currentCityId={city.id}\n        onClose={() => setLocationOpen(false)}\n        onSelect={selectCity}\n      />\n      <EmergencyModal visible={emergencyOpen} onClose={() => setEmergencyOpen(false)} />\n    </View>\n  );\n}\n\n/** Fondo de la BottomSheet con cristal esmerilado (BlurView) para que el mapa\n *  se vea a través. @gorhom/bottom-sheet pasa `style` con posición/altura. */\nfunction SheetGlassBackground({ style }: { style?: any }) {\n  const { isDark } = useTheme();\n  return (\n    <View style={[{ flex: 1, borderRadius: 20, overflow: 'hidden' }, style]}>\n      <BlurView\n        style={StyleSheet.absoluteFill}\n        intensity={36}\n        tint={isDark ? 'dark' : 'light'}\n      />\n      {/* Tinte suave de marca para legibilidad */}\n      <View\n        style={[\n          StyleSheet.absoluteFill,\n          { backgroundColor: isDark ? 'rgba(23,23,26,0.35)' : 'rgba(255,255,255,0.30)' },\n        ]}\n        pointerEvents=\"none\"\n      />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  sheet: {\n    ...elevation.lg,\n  },\n  sheetContent: {\n    paddingHorizontal: espaciado.e20,\n    paddingTop: espaciado.e6,\n  },\n});\n\n\n","// bottom sheet\nexport { default } from './components/bottomSheet';\n\n// bottom sheet modal\nexport { default as BottomSheetModal } from './components/bottomSheetModal';\nexport { default as BottomSheetModalProvider } from './components/bottomSheetModalProvider';\n\n//#region hooks\nexport { useBottomSheet } from './hooks/useBottomSheet';\nexport { useBottomSheetModal } from './hooks/useBottomSheetModal';\nexport { useBottomSheetSpringConfigs } from './hooks/useBottomSheetSpringConfigs';\nexport { useBottomSheetTimingConfigs } from './hooks/useBottomSheetTimingConfigs';\nexport { useBottomSheetInternal } from './hooks/useBottomSheetInternal';\nexpor