ties/logger';\n","import { memo, useCallback, useEffect, useMemo, useRef } from 'react';\nimport { nanoid } from 'nanoid/non-secure';\nimport { usePortal } from '../../hooks/usePortal';\nimport type { PortalProps } from './types';\n\nconst PortalComponent = ({\n  name: _providedName,\n  hostName,\n  handleOnMount: _providedHandleOnMount,\n  handleOnUnmount: _providedHandleOnUnmount,\n  handleOnUpdate: _providedHandleOnUpdate,\n  children,\n}: PortalProps) => {\n  //#region hooks\n  const { addPortal: addUpdatePortal, removePortal } = usePortal(hostName);\n  //#endregion\n\n  //#region variables\n  const name = useMemo(() => _providedName || nanoid(), [_providedName]);\n  //#endregion\n\n  //#region refs\n  const handleOnMountRef = useRef<Function>();\n  const handleOnUnmountRef = useRef<Function>();\n  const handleOnUpdateRef = useRef<Function>();\n  //#endregion\n\n  //#region callbacks\n  const handleOnMount = useCallback(() => {\n    if (_providedHandleOnMount) {\n      _providedHandleOnMount(() => addUpdatePortal(name, children));\n    } else {\n      addUpdatePortal(name, children);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [_providedHandleOnMount, addUpdatePortal]);\n  handleOnMountRef.current = handleOnMount;\n\n  const handleOnUnmount = useCallback(() => {\n    if (_providedHandleOnUnmount) {\n      _providedHandleOnUnmount(() => removePortal(name));\n    } else {\n      removePortal(name);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [_providedHandleOnUnmount, removePortal]);\n  handleOnUnmountRef.current = handleOnUnmount;\n\n  const handleOnUpdate = useCallback(() => {\n    if (_providedHandleOnUpdate) {\n      _providedHandleOnUpdate(() => addUpdatePortal(name, children));\n    } else {\n      addUpdatePortal(name, children);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [_providedHandleOnUpdate, addUpdatePortal, children]);\n  handleOnUpdateRef.current = handleOnUpdate;\n  //#endregion\n\n  //#region effects\n  useEffect(() => {\n    handleOnMountRef.current?.();\n    return () => {\n      handleOnUnmountRef.current?.();\n\n      // remove callbacks refs\n      handleOnMountRef.current = undefined;\n      handleOnUnmountRef.current = undefined;\n      handleOnUpdateRef.current = undefined;\n    };\n  }, []);\n  useEffect(() => {\n    handleOnUpdateRef.current?.();\n  }, [children]);\n  //#endregion\n\n  return null;\n};\n\nexport const Portal = memo(PortalComponent);\nPortal.displayName = 'Portal';\n","import { ReactNode, useCallback, useContext } from 'react';\nimport { ACTIONS } from '../state/constants';\nimport { PortalDispatchContext } from '../contexts/portal';\n\nexport const usePortal = (hostName: string = 'root') => {\n  const dispatch = useContext(PortalDispatchContext);\n\n  if (dispatch === null) {\n    throw new Error(\n      \"'PortalDispatchContext' cannot be null, please add 'PortalProvider' to the root component.\"\n    );\n  }\n\n  //#region methods\n  const registerHost = useCallback(() => {\n    dispatch({\n      type: ACTIONS.REGISTER_HOST,\n      hostName: hostName,\n    });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const deregisterHost = useCallback(() => {\n    dispatch({\n      type: ACTIONS.DEREGISTER_HOST,\n      hostName: hostName,\n    });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const addUpdatePortal = useCallback((name: string, node: ReactNode) => {\n    dispatch({\n      type: ACTIONS.ADD_UPDATE_PORTAL,\n      hostName,\n      portalName: name,\n      node,\n    });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const removePortal = useCallback((name: string) => {\n    dispatch({\n      type: ACTIONS.REMOVE_PORTAL,\n      hostName,\n      portalName: name,\n    });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n  //#endregion\n\n  return {\n    registerHost,\n    deregisterHost,\n    addPortal: addUpdatePortal,\n    updatePortal: addUpdatePortal,\n    removePortal,\n  };\n};\n","enum ACTIONS {\n  REGISTER_HOST,\n  DEREGISTER_HOST,\n  ADD_UPDATE_PORTAL,\n  REMOVE_PORTAL,\n}\n\nconst INITIAL_STATE = {};\n\nexport { ACTIONS, INITIAL_STATE };\n","import { createContext } from 'react';\nimport type { ActionTypes } from '../state/types';\nimport type { PortalType } from '../types';\n\nexport const PortalStateContext = createContext<Record<\n  string,\n  Array<PortalType>\n> | null>(null);\nexport const PortalDispatchContext =\n  createContext<React.Dispatch<ActionTypes> | null>(null);\n","import React, { memo, useEffect } from 'react';\nimport { usePortalState } from '../../hooks/usePortalState';\nimport { usePortal } from '../../hooks/usePortal';\nimport type { PortalHostProps } from './types';\n\nconst PortalHostComponent = ({ name }: PortalHostProps) => {\n  //#region hooks\n  const state = usePortalState(name);\n  const { registerHost, deregisterHost } = usePortal(name);\n  //#endregion\n\n  //#region effects\n  useEffect(() => {\n    registerHost();\n    return () => {\n      deregisterHost();\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n  //#endregion\n\n  //#region render\n  return <>{state.map(item => item.node)}</>;\n  //#endregion\n};\n\nexport const PortalHost = memo(PortalHostComponent);\nPortalHost.displayName = 'PortalHost';\n","import { useContext } from 'react';\nimport { PortalStateContext } from '../contexts/portal';\n\nexport const usePortalState = (hostName: string) => {\n  const state = useContext(PortalStateContext);\n\n  if (state === null) {\n    throw new Error(\n      \"'PortalStateContext' cannot be null, please add 'PortalProvider' to the root component.\"\n    );\n  }\n\n  return state[hostName] || [];\n};\n","import React, { memo, useReducer } from 'react';\nimport { PortalHost } from '../portalHost/PortalHost';\nimport {\n  PortalDispatchContext,\n  PortalStateContext,\n} from '../../contexts/portal';\nimport { INITIAL_STATE } from '../../state/constants';\nimport { reducer } from '../../state/reducer';\nimport type { PortalProviderProps } from './types';\n\nconst PortalProviderComponent = ({\n  rootHostName = 'root',\n  shouldAddRootHost = true,\n  children,\n}: PortalProviderProps) => {\n  const [state, dispatch] = useReducer(reducer, INITIAL_STATE);\n  return (\n    <PortalDispatchContext.Provider value={dispatch}>\n      <PortalStateContext.Provider value={state}>\n        {children}\n        {shouldAddRootHost && <PortalHost name={rootHostName} />}\n      </PortalStateContext.Provider>\n    </PortalDispatchContext.Provider>\n  );\n};\n\nexport const PortalProvider = memo(PortalProviderComponent);\nPortalProvider.displayName = 'PortalProvider';\n","import { ACTIONS } from './constants';\nimport { print } from '../utilities/logger';\nimport type { PortalType } from '../types';\nimport type {\n  ActionTypes,\n  AddUpdatePortalAction,\n  RemovePortalAction,\n} from './types';\n\nconst registerHost = (\n  state: Record<string, Array<PortalType>>,\n  hostName: string\n) => {\n  if (!(hostName in state)) {\n    state[hostName] = [];\n  }\n  return state;\n};\n\nconst deregisterHost = (\n  state: Record<string, Array<PortalType>>,\n  hostName: string\n) => {\n  delete state[hostName];\n  return state;\n};\n\nconst addUpdatePortal = (\n  state: Record<string, Array<PortalType>>,\n  hostName: string,\n  portalName: string,\n  node: any\n) => {\n  if (!(hostName in state)) {\n    state = registerHost(state, hostName);\n  }\n\n  /**\n   * updated portal, if it was already added.\n   */\n  const index = state[hostName].findIndex(item => item.name === portalName);\n  if (index !== -1) {\n    state[hostName][index].node = node;\n  } else {\n    state[hostName].push({\n      name: portalName,\n      node,\n    });\n  }\n  return state;\n};\n\nconst removePortal = (\n  state: Record<string, Array<PortalType>>,\n  hostName: string,\n  portalName: string\n) => {\n  if (!(hostName in state)) {\n    print({\n      component: reducer.name,\n      method: removePortal.name,\n      params: `Failed to remove portal '${portalName}', '${hostName}' was not registered!`,\n    });\n    return state;\n  }\n\n  const index = state[hostName].findIndex(item => item.name === portalName);\n  if (index !== -1) state[hostName].splice(index, 1);\n  return state;\n};\n\nexport const reducer = (\n  state: Record<string, Array<PortalType>>,\n  action: ActionTypes\n) => {\n  const { type } = action;\n  let clonedState = { ...state };\n  switch (type) {\n    case ACTIONS.REGISTER_HOST:\n      return registerHost(clonedState, action.hostName);\n    case ACTIONS.DEREGISTER_HOST:\n      return deregisterHost(clonedState, action.hostName);\n    case ACTIONS.ADD_UPDATE_PORTAL:\n      return addUpdatePortal(\n        clonedState,\n        action.hostName,\n        (action as AddUpdatePortalAction).portalName,\n        (action as AddUpdatePortalAction).node\n      );\n    case ACTIONS.REMOVE_PORTAL:\n      return removePortal(\n        clonedState,\n        action.hostName,\n        (action as RemovePortalAction).portalName\n      );\n    default:\n      return state;\n  }\n};\n","interface PrintOptions {\n  component?: string;\n  method?: string;\n  params?: Record<string, any> | string | number | boolean;\n}\n\ntype Print = (options: PrintOptions) => void;\n\nlet isLoggingEnabled = false;\n\n// __DEV__ global is by default not defined in React Native Web builds\nconst isDev = Boolean(typeof __DEV__ !== 'undefined' && __DEV__);\n\nconst enableLogging = () => {\n  if (!isDev) {\n    console.warn('[Portal] could not enable logging on production!');\n    return;\n  }\n  isLoggingEnabled = true;\n};\n\nlet print: Print = () => {};\n\nif (isDev) {\n  print = ({ component, method, params }) => {\n    if (!isLoggingEnabled) {\n      return;\n    }\n    let message = '';\n\n    if (typeof params === 'object') {\n      message = Object.keys(params)\n        .map(key => `${key}:${params[key]}`)\n        .join(' ');\n    } else {\n      message = `${params ?? ''}`;\n    }\n    console.log(\n      `[Portal::${[component, method].filter(Boolean).join('::')}]`,\n      message\n    );\n  };\n}\n\nObject.freeze(print);\n\nexport { print, enableLogging };\n","let current = 0;\n\nexport const id = () => {\n  current = (current + 1) % Number.MAX_SAFE_INTEGER;\n  return current;\n};\n","const DEFAULT_STACK_BEHAVIOR = 'switch';\nconst DEFAULT_ENABLE_DISMISS_ON_CLOSE = true;\n\nenum MODAL_STATUS {\n  INITIAL,\n  PRESENTED,\n  CLOSED,\n  MINIMIZED,\n  MINIMIZING,\n  ANIMATING,\n  DISMISSING,\n  DISMISSED,\n}\n\nexport {\n  DEFAULT_ENABLE_DISMISS_ON_CLOSE,\n  DEFAULT_STACK_BEHAVIOR,\n  MODAL_STATUS,\n};\n","export { default } from './BottomSheetModalProvider';\n","import { PortalProvider } from '@gorhom/portal';\nimport React, { useCallback, useMemo, useRef } from 'react';\nimport { useSharedValue } from 'react-native-reanimated';\nimport {\n  INITIAL_CONTAINER_LAYOUT,\n  MODAL_STACK_BEHAVIOR,\n} from '../../constants';\nimport {\n  BottomSheetModalInternalProvider,\n  BottomSheetModalProvider,\n} from '../../contexts';\nimport type { ContainerLayoutState } from '../../types';\nimport { id } from '../../utilities/id';\nimport { BottomSheetHostingContainer } from '../bottomSheetHostingContainer';\nimport type {\n  BottomSheetModalPrivateMethods,\n  BottomSheetModalStackBehavior,\n} from '../bottomSheetModal';\nimport { MODAL_STATUS } from '../bottomSheetModal/constants';\nimport type {\n  BottomSheetModalProviderProps,\n  BottomSheetModalRef,\n} from './types';\n\nconst BottomSheetModalProviderWrapper = ({\n  children,\n}: BottomSheetModalProviderProps) => {\n  //#region layout variables\n  const animatedContainerLayoutState = useSharedValue<ContainerLayoutState>(\n    INITIAL_CONTAINER_LAYOUT\n  );\n  //#endregion\n\n  //#region variables\n  const hostName = useMemo(() => `bottom-sheet-portal-${id()}`, []);\n  const sheetsQueueRef = useRef<BottomSheetModalRef[]>([]);\n  //#endregion\n\n  //#region private methods\n  const handleMountSheet = useCallback(\n    (\n      key: string,\n      ref: React.RefObject<BottomSheetModalPrivateMethods>,\n      stackBehavior: BottomSheetModalStackBehavior\n    ) => {\n      const _sheetsQueue = sheetsQueueRef.current.slice();\n      const sheetIndex = _sheetsQueue.findIndex(item => item.key === key);\n      const sheetOnTop = sheetIndex === _sheetsQueue.length - 1;\n\n      /**\n       * Exit the method, if sheet is already presented\n       * and at the top.\n       */\n      if (sheetIndex !== -1 && sheetOnTop) {\n        return;\n      }\n\n      /**\n       * Minimize the current sheet if:\n       * - it exists.\n       * - it is not unmounting.\n       * - stack behavior is 'replace'.\n       */\n\n      /**\n       * Handle switch or replace stack behaviors, if:\n       * - a modal is currently presented.\n       * - it is not unmounting\n       */\n      const currentMountedSheet = _sheetsQueue[_sheetsQueue.length - 1];\n      const currentMountedSheetStatus =\n        currentMountedSheet?.ref.current?.status.current;\n      const currentMountedSheetWillUnmount =\n        currentMountedSheetStatus !== undefined &&\n        currentMountedSheetStatus === MODAL_STATUS.DISMISSING;\n\n      if (currentMountedSheet && !currentMountedSheetWillUnmount) {\n        if (stackBehavior === MODAL_STACK_BEHAVIOR.replace) {\n          currentMountedSheet.ref?.current?.dismiss();\n        } else if (stackBehavior === MODAL_STACK_BEHAVIOR.switch) {\n          currentMountedSheet.ref?.current?.minimize();\n        }\n      }\n\n      /**\n       * Restore and remove incoming sheet from the queue, if it was registered.\n       */\n      if (sheetIndex !== -1) {\n        _sheetsQueue.splice(sheetIndex, 1);\n        ref?.current?.restore();\n      }\n\n      _sheetsQueue.push({\n        key,\n        ref,\n      });\n      sheetsQueueRef.current = _sheetsQueue;\n    },\n    []\n  );\n  const handleUnmountSheet = useCallback((key: string) => {\n    const _sheetsQueue = sheetsQueueRef.current.slice();\n    const sheetIndex = _sheetsQueue.findIndex(item => item.key === key);\n    const sheetOnTop = sheetIndex === _sheetsQueue.length - 1;\n\n    /**\n     * Here we remove the unmounted sheet and update\n     * the sheets queue.\n     */\n    if (sheetIndex !== -1) {\n      _sheetsQueue.splice(sheetIndex, 1);\n      sheetsQueueRef.current = _sheetsQueue;\n    }\n\n    /**\n     * Here we try to restore previous sheet position if unmounted\n     * sheet was on top. This is needed when user dismiss\n     * the modal by panning down.\n     */\n    const hasMinimizedSheet = sheetsQueueRef.current.length > 0;\n    const minimizedSheet =\n      sheetsQueueRef.current[sheetsQueueRef.current.length - 1];\n    const minimizedSheetStatus = minimizedSheet?.ref.current?.status.current;\n    const minimizedSheetWillUnmount =\n      minimizedSheetStatus !== undefined &&\n      minimizedSheetStatus === MODAL_STATUS.DISMISSING;\n\n    if (\n      sheetOnTop &&\n      hasMinimizedSheet &&\n      minimizedSheet &&\n      !minimizedSheetWillUnmount\n    ) {\n      sheetsQueueRef.current[\n        sheetsQueueRef.current.length - 1\n      ].ref?.current?.restore();\n    }\n  }, []);\n  const handleWillUnmountSheet = useCallback((key: string) => {\n    const _sheetsQueue = sheetsQueueRef.current.slice();\n    const sheetIndex = _sheetsQueue.findIndex(item => item.key === key);\n    const sheetOnTop = sheetIndex === _sheetsQueue.length - 1;\n\n    /**\n     * Here we try to restore previous sheet position,\n     * This is needed when user dismiss the modal by fire the dismiss action.\n     */\n    const hasMinimizedSheet = _sheetsQueue.length > 1;\n    if (sheetOnTop && hasMinimizedSheet) {\n      _sheetsQueue[_sheetsQueue.length - 2].ref?.current?.restore();\n    }\n\n    sheetsQueueRef.current = _sheetsQueue;\n  }, []);\n  //#endregion\n\n  //#region public methods\n  const handleDismiss = useCallback((key?: string) => {\n    const sheetToBeDismissed = key\n      ? sheetsQueueRef.current.find(item => item.key === key)\n      : sheetsQueueRef.current[sheetsQueueRef.current.length - 1];\n    if (sheetToBeDismissed) {\n      sheetToBeDismissed.ref?.current?.dismiss();\n      return true;\n    }\n    return false;\n  }, []);\n  const handleDismissAll = useCallback(() => {\n    sheetsQueueRef.current.forEach(item => {\n      item.ref?.current?.dismiss();\n    });\n  }, []);\n  //#endregion\n\n  //#region context variables\n  const externalContextVariables = useMemo(\n    () => ({\n      dismiss: handleDismiss,\n      dismissAll: handleDismissAll,\n    }),\n    [handleDismiss, handleDismissAll]\n  );\n  const internalContextVariables = useMemo(\n    () => ({\n      hostName,\n      containerLayoutState: animatedContainerLayoutState,\n      mountSheet: handleMountSheet,\n      unmountSheet: handleUnmountSheet,\n      willUnmountSheet: handleWillUnmountSheet,\n    }),\n    [\n      hostName,\n      animatedContainerLayoutState,\n      handleMountSheet,\n      handleUnmountSheet,\n      handleWillUnmountSheet,\n    ]\n  );\n  //#endregion\n\n  //#region renders\n  return (\n    <BottomSheetModalProvider value={externalContextVariables}>\n      <BottomSheetModalInternalProvider value={internalContextVariables}>\n        <BottomSheetHostingContainer\n          containerLayoutState={animatedContainerLayoutState}\n        />\n        <PortalProvider rootHostName={hostName}>{children}</PortalProvider>\n      </BottomSheetModalInternalProvider>\n    </BottomSheetModalProvider>\n  );\n  //#endregion\n};\n\nexport default BottomSheetModalProviderWrapper;\n","import type { WithSpringConfig } from 'react-native-reanimated';\n\n/**\n * Generate spring animation configs.\n * @param configs overridable configs.\n */\nexport const useBottomSheetSpringConfigs = (\n  configs: Omit<WithSpringConfig, 'velocity'>\n) => {\n  return configs;\n};\n","import { useMemo } from 'react';\nimport type { EasingFunction } from 'react-native';\nimport type {\n  EasingFunctionFactory,\n  ReduceMotion,\n} from 'react-native-reanimated';\nimport { ANIMATION_DURATION, ANIMATION_EASING } from '../constants';\n\n/**\n * this is needed to avoid TS4023\n * https://github.com/microsoft/TypeScript/issues/5711\n */\ninterface TimingConfig {\n  duration?: number;\n  easing?: EasingFunction | EasingFunctionFactory;\n  reduceMotion?: ReduceMotion;\n}\n\n/**\n * Generate timing animation configs.\n * @default\n * - easing: Easing.out(Easing.exp)\n * - duration: 250\n * @param configs overridable configs.\n */\nexport const useBottomSheetTimingConfigs = (configs: TimingConfig) => {\n  return useMemo(() => {\n    const _configs: TimingConfig = {\n      easing: configs.easing || ANIMATION_EASING,\n      duration: configs.duration || ANIMATION_DURATION,\n      reduceMotion: configs.reduceMotion,\n    };\n\n    return _configs;\n  }, [configs.duration, configs.easing, configs.reduceMotion]);\n};\n","import { type ReactElement, useCallback } from 'react';\nimport {\n  type BottomSheetScrollableProps,\n  BottomSheetScrollView,\n} from '../components/bottomSheetScrollable';\n\ntype BottomSheetScrollableCreatorConfigs = {} & BottomSheetScrollableProps;\n\n/**\n * A custom hook that creates a scrollable component for third-party libraries\n * like `LegendList` or `FlashList` to integrate the interaction and scrolling\n * behaviors with th BottomSheet component.\n *\n * @param configs - Configuration options for the scrollable creator.\n * @param configs.focusHook - This needed when bottom sheet used with multiple scrollables to allow bottom sheet\n * detect the current scrollable ref, especially when used with `React Navigation`.\n * You will need to provide `useFocusEffect` from `@react-navigation/native`.\n * @param configs.scrollEventsHandlersHook - Custom hook to provide scroll events handler, which will allow advance and\n * customize handling for scrollables.\n * @param configs.enableFooterMarginAdjustment - Adjust the scrollable bottom margin to avoid the animated footer.\n *\n * @example\n * ```tsx\n * const BottomSheetLegendListScrollable = useBottomSheetScrollableCreator();\n *\n * // Usage in JSX\n * <LegendList\n *  renderScrollComponent={BottomSheetLegendListScrollable}\n * />\n * ```\n */\n// biome-ignore lint/suspicious/noExplicitAny: out of my control\nexport function useBottomSheetScrollableCreator<T = any>({\n  focusHook,\n  scrollEventsHandlersHook,\n  enableFooterMarginAdjustment,\n}: BottomSheetScrollableCreatorConfigs = {}): (\n  props: T,\n  ref?: never\n) => ReactElement<T> {\n  return useCallback(\n    function useBottomSheetScrollableCreator(\n      // @ts-expect-error\n      { data: _, ...props }: T,\n      ref?: never\n    ): ReactElement<T> {\n      return (\n        // @ts-expect-error\n        <BottomSheetScrollView\n          ref={ref}\n          {...props}\n          focusHook={focusHook}\n          scrollEventsHandlersHook={scrollEventsHandlersHook}\n          enableFooterMarginAdjustment={enableFooterMarginAdjustment}\n        />\n      );\n    },\n    [focusHook, scrollEventsHandlersHook, enableFooterMarginAdjustment]\n  );\n}\n","export { default as BottomSheetFlashList } from './BottomSheetFlashList';\nexport { default as BottomSheetFlatList } from './BottomSheetFlatList';\nexport { default as BottomSheetScrollView } from './BottomSheetScrollView';\nexport { default as BottomSheetSectionList } from './BottomSheetSectionList';\nexport { default as BottomSheetVirtualizedList } from './BottomSheetVirtualizedList';\nexport { createBottomSheetScrollableComponent } from './createBottomSheetScrollableComponent';\n\nexport type {\n  BottomSheetFlatListMethods,\n  BottomSheetScrollableProps,\n  BottomSheetScrollViewMethods,\n  BottomSheetSectionListMethods,\n  BottomSheetVirtualizedListMethods,\n} from './types';\n","import React, { forwardRef, memo, type Ref, useMemo } from 'react';\nimport type { FlatListProps, ScrollViewProps } from 'react-native';\nimport type { AnimatedProps } from 'react-native-reanimated';\nimport BottomSheetScrollView from './BottomSheetScrollView';\nimport type {\n  BottomSheetScrollableProps,\n  BottomSheetScrollViewMethods,\n} from './types';\n\n/**\n * Minimal subset of FlashListProps needed for BottomSheetFlashList.\n * Defined locally to avoid requiring @shopify/flash-list as a dependency,\n * since the runtime import is optional (try/catch require).\n */\ninterface FlashListProps<T> extends FlatListProps<T> {\n  estimatedItemSize?: number;\n}\n\nlet FlashList: {\n  FlashList: React.FC;\n};\n// since FlashList is not a dependency for the library\n// we try to import it using metro optional import\ntry {\n  FlashList = require('@shopify/flash-list') as never;\n} catch (_) {}\n\nexport type BottomSheetFlashListProps<T> = Omit<\n  AnimatedProps<FlashListProps<T>>,\n  'decelerationRate' | 'onScroll' | 'scrollEventThrottle'\n> &\n  BottomSheetScrollableProps & {\n    ref?: Ref<React.FC>;\n  };\n\nconst BottomSheetFlashListComponent = forwardRef<\n  React.FC,\n  // biome-ignore lint/suspicious/noExplicitAny: to be addressed\n  BottomSheetFlashListProps<any>\n>((props, ref) => {\n  //#region props\n  const {\n    focusHook,\n    scrollEventsHandlersHook,\n    enableFooterMarginAdjustment,\n    ...rest\n    // biome-ignore lint: to be addressed!\n  }: any = props;\n  //#endregion\n\n  useMemo(() => {\n    if (!FlashList) {\n      throw 'You need to install FlashList first, `yarn install @shopify/flash-list`';\n    }\n\n    console.warn(\n      'BottomSheetFlashList is deprecated, please use useBottomSheetScrollableCreator instead.'\n    );\n  }, []);\n\n  //#region render\n  const renderScrollComponent = useMemo(\n    () =>\n      forwardRef<BottomSheetScrollViewMethods, ScrollViewProps>(\n        // @ts-expect-error\n        ({ data, ...props }, ref) => {\n          return (\n            // @ts-expect-error\n            <BottomSheetScrollView\n              ref={ref}\n              {...props}\n              focusHook={focusHook}\n              scrollEventsHandlersHook={scrollEventsHandlersHook}\n              enableFooterMarginAdjustment={enableFooterMarginAdjustment}\n            />\n          );\n        }\n      ),\n    [focusHook, scrollEventsHandlersHook, enableFooterMarginAdjustment]\n  );\n  return (\n    <FlashList.FlashList\n      ref={ref}\n      renderScrollComponent={renderScrollComponent}\n      {...rest}\n    />\n  );\n  //#endregion\n});\n\nexport const BottomSheetFlashList = memo(BottomSheetFlashListComponent);\n\nexport default BottomSheetFlashList as <T>(\n  props: BottomSheetFlashListProps<T>\n) => ReturnType<typeof BottomSheetFlashList>;\n","import { memo } from 'react';\nimport {\n  ScrollView as RNScrollView,\n  type ScrollViewProps as RNScrollViewProps,\n} from 'react-native';\nimport Animated from 'react-native-reanimated';\nimport { SCROLLABLE_TYPE } from '../../constants';\nimport { createBottomSheetScrollableComponent } from './createBottomSheetScrollableComponent';\nimport type {\n  BottomSheetScrollViewMethods,\n  BottomSheetScrollViewProps,\n} from './types';\n\nconst AnimatedScrollView =\n  Animated.createAnimatedComponent<RNScrollViewProps>(RNScrollView);\n\nconst BottomSheetScrollViewComponent = createBottomSheetScrollableComponent<\n  BottomSheetScrollViewMethods,\n  BottomSheetScrollViewProps\n>(SCROLLABLE_TYPE.SCROLLVIEW, AnimatedScrollView);\n\nconst BottomSheetScrollView = memo(BottomSheetScrollViewComponent);\nBottomSheetScrollView.displayName = 'BottomSheetScrollView';\n\nexport default BottomSheetScrollView as (\n  props: BottomSheetScrollViewProps\n) => ReturnType<typeof BottomSheetScrollView>;\n","import React, {\n  forwardRef,\n  useContext,\n  useImperativeHandle,\n  useMemo,\n} from 'react';\nimport { Gesture } from 'react-native-gesture-handler';\nimport { useAnimatedProps } from 'react-native-reanimated';\nimport {\n  SCROLLABLE_DECELERATION_RATE_MAPPER,\n  SCROLLABLE_STATUS,\n  type SCROLLABLE_TYPE,\n} from '../../constants';\nimport { BottomSheetDraggableContext } from '../../contexts/gesture';\nimport {\n  useBottomSheetContentContainerStyle,\n  useBottomSheetInternal,\n  useScrollableSetter,\n  useScrollHandler,\n  useStableCallback,\n} from '../../hooks';\nimport { ScrollableContainer } from './ScrollableContainer';\nimport { useBottomSheetContentSizeSetter } from './useBottomSheetContentSizeSetter';\n\nexport function createBottomSheetScrollableComponent<T, P>(\n  type: SCROLLABLE_TYPE,\n  // biome-ignore lint: to be addressed!\n  ScrollableComponent: any\n) {\n  return forwardRef<T, P>((props, ref) => {\n    //#region props\n    const {\n      // hooks\n      focusHook,\n      scrollEventsHandlersHook,\n      // props\n      enableFooterMarginAdjustment = false,\n      overScrollMode = 'never',\n      keyboardDismissMode = 'interactive',\n      showsVerticalScrollIndicator = true,\n      contentContainerStyle: _providedContentContainerStyle,\n      refreshing,\n      onRefresh,\n      progressViewOffset,\n      refreshControl,\n      // events\n      onScroll,\n      onScrollBeginDrag,\n      onScrollEndDrag,\n      onContentSizeChange,\n      ...rest\n      // biome-ignore lint: to be addressed!\n    }: any = props;\n    //#endregion\n\n    //#region hooks\n    const draggableGesture = useContext(BottomSheetDraggableContext);\n    const { scrollableRef, scrollableContentOffsetY, scrollHandler } =\n      useScrollHandler(\n        scrollEventsHandlersHook,\n        onScroll,\n        onScrollBeginDrag,\n        onScrollEndDrag\n      );\n    const {\n      animatedScrollableStatus: animatedScrollableState,\n      enableContentPanningGesture,\n    } = useBottomSheetInternal();\n    const { setContentSize } = useBottomSheetContentSizeSetter();\n    //#endregion\n\n    if (!draggableGesture && enableContentPanningGesture) {\n      throw \"'Scrollable' cannot be used out of the BottomSheet!\";\n    }\n\n    //#region variables\n    const scrollableAnimatedProps = useAnimatedProps(\n      () => ({\n        decelerationRate:\n          SCROLLABLE_DECELERATION_RATE_MAPPER[animatedScrollableState.value],\n        showsVerticalScrollIndicator: showsVerticalScrollIndicator\n          ? animatedScrollableState.value === SCROLLABLE_STATUS.UNLOCKED\n          : showsVerticalScrollIndicator,\n      }),\n      [animatedScrollableState, showsVerticalScrollIndicator]\n    );\n\n    const scrollableGesture = useMemo(\n      () =>\n        draggableGesture\n          ? Gesture.Native()\n              // @ts-expect-error\n              .simultaneousWithExternalGesture(draggableGesture)\n              .shouldCancelWhenOutside(false)\n          : undefined,\n      [draggableGesture]\n    );\n    //#endregion\n\n    //#region callbacks\n    const handleContentSizeChange = useStableCallback(\n      (contentWidth: number, contentHeight: number) => {\n        setContentSize(contentHeight);\n        if (onContentSizeChange) {\n          onContentSizeChange(contentWidth, contentHeight);\n        }\n      }\n    );\n    //#endregion\n\n    //#region styles\n    const contentContainerStyle = useBottomSheetContentContainerStyle(\n      enableFooterMarginAdjustment,\n      _providedContentContainerStyle\n    );\n    //#endregion\n\n    //#region effects\n    // @ts-expect-error\n    useImperativeHandle(ref, () => scrollableRef.current);\n    useScrollableSetter(\n      scrollableRef,\n      type,\n      scrollableContentOffsetY,\n      onRefresh !== undefined,\n      focusHook\n    );\n    //#endregion\n\n    //#region render\n    return (\n      <ScrollableContainer\n        ref={scrollableRef}\n        nativeGesture={scrollableGesture}\n        animatedProps={scrollableAnimatedProps}\n        overScrollMode={overScrollMode}\n        keyboardDismissMode={keyboardDismissMode}\n        refreshing={refreshing}\n        scrollEventThrottle={16}\n        progressView