sRingAvatar from './status/StatusRingAvatar';\nimport StatusChip from './status/StatusChip';\nimport StatusDetailModal from './status/StatusDetailModal';\nimport { brand, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\n/** Altura del banner (25 % de la pantalla, acotada). */\nconst BANNER_H_RATIO = 0.25;\nconst BANNER_H_MIN = 150;\nconst BANNER_H_MAX = 300;\n/** Zona extra bajo el banner donde flota el botón de ciudad (sobre el mapa). */\nconst CITY_ZONE_H = 52;\n\nexport const homeBannerHeight = (winH: number) =>\n  Math.round(Math.min(Math.max(winH * BANNER_H_RATIO, BANNER_H_MIN), BANNER_H_MAX));\nexport const homeHeaderHeight = (winH: number, insetsTop: number) => insetsTop + homeBannerHeight(winH) + CITY_ZONE_H;\n\nexport default function SocialHomeHeader({\n  cityName,\n  onPressCity,\n}: {\n  cityName: string;\n  onPressCity: () => void;\n}) {\n  const { colors, isDark } = useTheme();\n  const insets = useSafeAreaInsets();\n  const { height: winH } = useWindowDimensions();\n  const router = useRouter();\n  const { isAuthenticated } = useSession();\n\n  const [coverUrl, setCoverUrl] = useState<string | null>(null);\n  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);\n  const [displayName, setDisplayName] = useState<string | null>(null);\n  const [role, setRole] = useState<'PASSENGER' | 'DRIVER' | 'ADMIN' | null>(null);\n  const [nameColor, setNameColor] = useState<string | null>(null);\n  const { status: myStatus, loading: statusLoading, refresh: refreshStatus, localExpire } = useStatusStore();\n  const [detailOpen, setDetailOpen] = useState(false);\n\n  const [ad, setAd] = useState<HomeAd | null>(null);\n  const [isAdVisible, setIsAdVisible] = useState(true);\n  const countedRef = useRef<string | null>(null);\n\n  const loadProfile = useCallback(() => {\n    if (!isAuthenticated) return;\n    let alive = true;\n    authApi.me()\n      .then((p) => {\n        if (!alive) return;\n        setCoverUrl(p.coverUrl ?? null);\n        setAvatarUrl(p.avatarUrl ?? null);\n        setDisplayName(p.fullName ?? null);\n        setRole(p.role);\n        setNameColor(p.nameColor && /^#[0-9A-Fa-f]{6}$/.test(p.nameColor) ? p.nameColor : null);\n      })\n      .catch(() => {});\n    return () => { alive = false; };\n  }, [isAuthenticated]);\n\n  useEffect(() => loadProfile(), [loadProfile]);\n\n  // Refresca el estado al volver la Home al frente y cuando arranca la sesión.\n  useEffect(() => { if (isAuthenticated) refreshStatus(); }, [isAuthenticated, refreshStatus]);\n\n  useEffect(() => {\n    let alive = true;\n    setIsAdVisible(true);\n    adsApi.homeBanner(cityName)\n      .then((b) => { if (alive) setAd(b); })\n      .catch(() => { if (alive) setAd(null); });\n    return () => { alive = false; };\n  }, [cityName]);\n\n  useEffect(() => {\n    if (!isAdVisible || !ad || countedRef.current === ad.id) return;\n    countedRef.current = ad.id;\n    adsApi.impression(ad.id).catch(() => {});\n  }, [ad, isAdVisible]);\n\n  const openAd = () => {\n    if (!ad) { onPressCity(); return; }\n    adsApi.click(ad.id).catch(() => {});\n    if (ad.externalUrl) Linking.openURL(ad.externalUrl).catch(() => {});\n    else if (ad.targetRoute) router.push(ad.targetRoute as never);\n  };\n\n  const isDriver = role === 'DRIVER';\n  const hasSessionIdentity = isAuthenticated && (avatarUrl || displayName);\n  const profileCover = coverUrl ? absUrl(coverUrl) : null;\n  const fadeTo = isDark ? '#0B1220' : '#E7EDF4';\n  const bannerH = homeBannerHeight(winH);\n  const showAd = !!ad && isAdVisible;\n  const nameTint = nameColor ?? (isDriver ? brand.white : brand.white);\n\n  return (\n    <View style={[styles.wrap, { height: insets.top + bannerH + CITY_ZONE_H }]} pointerEvents=\"box-none\">\n      {/* ============ CAPA PERFIL (siempre) ============ */}\n      <View style={[styles.bannerArea, { top: insets.top, height: bannerH }]} pointerEvents=\"none\">\n        {profileCover ? (\n          <ImageBackground source={{ uri: profileCover }} style={StyleSheet.absoluteFill} imageStyle={styles.coverImg} />\n        ) : (\n          <View style={[StyleSheet.absoluteFill, styles.coverFallback]}>\n            <Svg height=\"100%\" width=\"100%\">\n              <Defs>\n                <SvgLinearGradient id=\"profBg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n                  <Stop offset=\"0\" stopColor={isDark ? '#16202E' : '#DFEAF2'} />\n                  <Stop offset=\"1\" stopColor={isDark ? '#0F1620' : '#F6EEDC'} />\n                </SvgLinearGradient>\n              </Defs>\n              <Rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill=\"url(#profBg)\" />\n            </Svg>\n          </View>\n        )}\n        <View style={StyleSheet.absoluteFill} pointerEvents=\"none\">\n          <Svg height=\"100%\" width=\"100%\">\n            <Defs>\n              <SvgLinearGradient id=\"profFade\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                <Stop offset=\"0.6\" stopColor={fadeTo} stopOpacity=\"0\" />\n                <Stop offset=\"1\" stopColor={fadeTo} stopOpacity=\"0.85\" />\n              </SvgLinearGradient>\n            </Defs>\n            <Rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill=\"url(#profFade)\" />\n          </Svg>\n        </View>\n      </View>\n\n      {/* Identidad (SIEMPRE). SIN sombra degradada; nombre con color elegido.\n          El avatar lleva el ANILLO del estado activo (v3). */}\n      {hasSessionIdentity && (\n        <View style={[styles.identity, { top: insets.top + 10, left: 10 }]} pointerEvents=\"box-none\">\n          <StatusRingAvatar\n            avatarUrl={avatarUrl}\n            name={displayName}\n            status={myStatus}\n            size={40}\n            ringWidth={3}\n            onPress={() => router.push('/profile' as never)}\n          />\n          <View style={{ flexShrink: 1 }}>\n            <Text style={[styles.driverName, { color: nameTint }]} numberOfLines={1}>{displayName ?? 'Conductor'}</Text>\n            {isDriver ? (\n              <View style={styles.onlineRow}>\n                <View style={styles.onlineDot} />\n                <Text style={[styles.onlineTxt, { color: nameTint }]}>En línea</Text>\n              </View>\n            ) : null}\n            {/* Estado 24h v3: chip sobrio bajo el nombre si hay estado activo.\n                Tocar → detalle (Finalizar/Compartir). */}\n            {myStatus && !statusLoading ? (\n              <StatusChip\n                compact\n                status={myStatus}\n                foreground={brand.white}\n                onPress={() => setDetailOpen(true)}\n                onExpired={() => { refreshStatus(); }}\n              />\n            ) : null}\n          </View>\n        </View>\n      )}\n\n      {/* ============ CAPA PUBLICIDAD (superpuesta) ============ */}\n      {showAd && (\n        <Pressable\n          onPress={openAd}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Publicidad: ${ad.title}`}\n          style={[styles.bannerArea, { top: insets.top, height: bannerH }]}\n        >\n          <ImageBackground\n            source={{ uri: ad.imageUrl ? absUrl(ad.imageUrl) : profileCover ?? DEFAULT_AD_IMG }}\n            style={StyleSheet.absoluteFill}\n            imageStyle={styles.coverImg}\n          />\n          <View style={StyleSheet.absoluteFill} pointerEvents=\"none\">\n            <Svg height=\"100%\" width=\"100%\">\n              <Defs>\n                <SvgLinearGradient id=\"adFade\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <Stop offset=\"0.5\" stopColor={fadeTo} stopOpacity=\"0\" />\n                  <Stop offset=\"1\" stopColor={fadeTo} stopOpacity=\"0.85\" />\n                </SvgLinearGradient>\n              </Defs>\n              <Rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill=\"url(#adFade)\" />\n            </Svg>\n          </View>\n          <View style={styles.adCopy} pointerEvents=\"none\">\n            <Text style={styles.adTitle} numberOfLines={1}>{ad.emoji ? `${ad.emoji} ` : ''}{ad.title}</Text>\n            {ad.subtitle ? <Text style={styles.adSub} numberOfLines={1}>{ad.subtitle}</Text> : null}\n          </View>\n          {/* Etiqueta Publicidad + X SIEMPRE sobre el anuncio (no ocultos) */}\n          <View style={styles.adTag} pointerEvents=\"none\">\n            <Text style={styles.adTagTxt}>Publicidad</Text>\n          </View>\n          <Pressable\n            onPress={() => setIsAdVisible(false)}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Ocultar anuncio\"\n            hitSlop={10}\n            style={({ pressed }) => [styles.closeBtn, { opacity: pressed ? 0.7 : 1 }]}\n          >\n            <X size={13} color={brand.white} />\n          </Pressable>\n        </Pressable>\n      )}\n\n      {/* Botón de CIUDAD: degradado OSCURO + letra AZUL, flotando sobre el mapa */}\n      <Pressable\n        onPress={onPressCity}\n        accessibilityRole=\"button\"\n        accessibilityLabel={`Ubicación actual: ${cityName}`}\n        accessibilityHint=\"Toca para cambiar de ciudad\"\n        style={({ pressed }) => [styles.cityBtn, { top: insets.top + bannerH + 10, opacity: pressed ? 0.85 : 1 }]}\n      >\n        <MapPin size={13} color={brand.primary} />\n        <Text style={styles.cityTxt} numberOfLines={1}>{cityName || 'Seleccionar ciudad'}</Text>\n        <ChevronDown size={13} color={brand.primary} />\n      </Pressable>\n\n      {/* Detalle del ESTADO 24h (v3): abierto desde el chip bajo el nombre. */}\n      {myStatus && (\n        <StatusDetailModal\n          visible={detailOpen}\n          status={myStatus}\n          isMine\n          onClose={() => setDetailOpen(false)}\n          onEnded={() => localExpire()}\n        />\n      )}\n    </View>\n  );\n}\n\nconst DEFAULT_AD_IMG = 'https://hk.egrouteplan.com/wallet/assets/ads/taxi-malabo.jpg';\n\nconst styles = StyleSheet.create({\n  wrap: { position: 'absolute', left: 0, right: 0, top: 0, zIndex: 25 },\n  bannerArea: { position: 'absolute', left: 0, right: 0, overflow: 'hidden' },\n  coverImg: { resizeMode: 'cover' },\n  coverFallback: { overflow: 'hidden' },\n  identity: { position: 'absolute', flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, zIndex: 30 },\n  avatar: {\n    width: 40, height: 40, borderRadius: 20, overflow: 'hidden',\n    alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(0,0,0,0.30)',\n    borderWidth: 2, borderColor: 'rgba(255,255,255,0.9)',\n  },\n  avatarImg: { width: '100%', height: '100%' },\n  driverName: { fontSize: tipografia.body, fontWeight: '900', maxWidth: 180 },\n  onlineRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginTop: 1 },\n  onlineDot: { width: 7, height: 7, borderRadius: 4, backgroundColor: brand.success, borderWidth: 1, borderColor: 'rgba(255,255,255,0.7)' },\n  onlineTxt: { fontSize: 10.5, fontWeight: '900' },\n  adCopy: { position: 'absolute', left: 14, right: 60, bottom: 10 },\n  adTitle: {\n    color: brand.white, fontSize: 15, fontWeight: '900',\n    textShadowColor: 'rgba(0,0,0,0.55)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 4,\n  },\n  adSub: {\n    color: 'rgba(255,255,255,0.95)', fontSize: tipografia.caption, fontWeight: '700', marginTop: 1,\n    textShadowColor: 'rgba(0,0,0,0.55)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 3,\n  },\n  adTag: {\n    position: 'absolute', top: 10, right: 40,\n    backgroundColor: 'rgba(0,0,0,0.62)', borderRadius: 6,\n    paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e3,\n  },\n  adTagTxt: { color: brand.white, fontSize: 9, fontWeight: '900', letterSpacing: 0.4 },\n  closeBtn: {\n    position: 'absolute', top: 8, right: 10,\n    width: 22, height: 22, borderRadius: 11,\n    backgroundColor: 'rgba(0,0,0,0.55)', alignItems: 'center', justifyContent: 'center',\n    borderWidth: 1, borderColor: 'rgba(255,255,255,0.35)', zIndex: 50,\n  },\n  cityBtn: {\n    position: 'absolute', left: 14, flexDirection: 'row', alignItems: 'center', gap: espaciado.e5,\n    borderRadius: radios.full,\n    // Degradado OSCURO + letra AZUL (estilo previo del pill de ciudad).\n    backgroundColor: 'rgba(10,16,24,0.78)',\n    borderWidth: 1, borderColor: 'rgba(79,168,255,0.5)',\n    paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e6,\n    zIndex: 30,\n    elevation: 3,\n  },\n  cityTxt: { fontSize: tipografia.caption, fontWeight: '900', color: brand.primary, maxWidth: 180 },\n});\n","/**\n * Cliente de publicidad del Home — GET /api/ads/ público + contadores + banner.\n * Los anuncios se gestionan desde el web-dashboard admin.\n * NOTA: este servicio vive bajo /api (sin /wallet/api/v1), como work.\n */\n\nimport { http } from './httpClient';\nimport { API_HOST } from './config';\n\nexport const ADS_API = `${API_HOST}/api`;\nconst a = (p: string) => `${ADS_API}${p}`;\n\nexport interface HomeAd {\n  id: string;\n  kind: string;\n  serviceKey: string | null;\n  targetRoute: string | null;\n  title: string;\n  subtitle: string | null;\n  emoji: string | null;\n  color: string;\n  imageUrl: string | null;\n  externalUrl?: string | null;\n  cities?: string[];\n  /** Descuento porcentual aplicable (p. ej. 20 = -20 % en taxi). */\n  discountPct?: number;\n  sort: number;\n  active: boolean;\n  startsAt?: string | null;\n  endsAt?: string | null;\n  impressions: number;\n  clicks: number;\n}\n\nexport const adsApi = {\n  /** Listado público (Home). Opcional: filtra por ciudad. */\n  list: (city?: string) => http.get<HomeAd[]>(a(`/ads/${city ? `?city=${encodeURIComponent(city)}` : ''}`), false),\n\n  /** Banner superior de la Home (un anuncio por ciudad/horario). */\n  homeBanner: (city?: string) =>\n    http.get<HomeAd | null>(a(`/ads/home-banner${city ? `?city=${encodeURIComponent(city)}` : ''}`), false),\n\n  impression: (id: string) => http.post<{ ok: boolean }>(a(`/ads/${id}/impression`), {}, false),\n  click: (id: string) => http.post<{ ok: boolean }>(a(`/ads/${id}/click`), {}, false),\n};\n","/**\n * StatusRingAvatar — avatar con ANILLO de estado 24h.\n * Si el usuario tiene estado activo, el avatar se rodea de un halo de\n * `ringWidth` px con el degradado del fondo del preset (WeChat pinta el borde\n * con el color del estado). Sin estado → borde blanco liso (sin anillo).\n * Reutilizable en Perfil (88), Home (40) y Detalle (44).\n */\n\nimport React from 'react';\nimport { Image, Pressable, StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport Svg, { Defs, LinearGradient as SvgLinearGradient, Rect, Stop } from 'react-native-svg';\nimport { absUrl } from '../../api/config';\nimport { statusBgColors } from '../../constants/status';\nimport type { UserStatus } from '../../api/status';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport default function StatusRingAvatar({\n  avatarUrl,\n  name,\n  status,\n  size = 88,\n  ringWidth = 4,\n  onPress,\n  ringStyle,\n  defaultRingColor,\n}: {\n  avatarUrl?: string | null;\n  name?: string | null;\n  status?: UserStatus | null;\n  size?: number;\n  ringWidth?: number;\n  onPress?: () => void;\n  ringStyle?: StyleProp<ViewStyle>;\n  /** Color del anillo/borde cuando NO hay estado (blanco por defecto). */\n  defaultRingColor?: string;\n}) {\n  const [c1, c2] = statusBgColors(status?.preset.bg);\n  const radius = size / 2;\n  const src = avatarUrl ? absUrl(avatarUrl) : null;\n  const inner = src\n    ? <Image source={{ uri: src }} style={styles.img} />\n    : (\n      <View style={[styles.fallback, { backgroundColor: 'rgba(0,0,0,0.30)' }]}>\n        <Text style={[styles.initial, { fontSize: size * 0.4 }]}>\n          {(name ?? 'U').trim().charAt(0).toUpperCase()}\n        </Text>\n      </View>\n    );\n\n  const avatarBody = status ? (\n    <View style={{ width: size + ringWidth * 2, height: size + ringWidth * 2, borderRadius: radius + ringWidth, overflow: 'hidden', borderWidth: 0 }}>\n      {/* Halo degradado: se pinta como fondo del contenedor y el avatar va dentro\n          con un margen = ringWidth → efecto de anillo. */}\n      <Svg height=\"100%\" width=\"100%\" style={StyleSheet.absoluteFill}>\n        <Defs>\n          <SvgLinearGradient id={`ring-${status.id}`} x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n            <Stop offset=\"0\" stopColor={c1} />\n            <Stop offset=\"1\" stopColor={c2} />\n          </SvgLinearGradient>\n        </Defs>\n        <Rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill={`url(#ring-${status.id})`} />\n      </Svg>\n      <View style={{ position: 'absolute', top: ringWidth, left: ringWidth, width: size, height: size, borderRadius: radius, overflow: 'hidden', backgroundColor: brand.white }}>\n        {inner}\n      </View>\n    </View>\n  ) : (\n    <View style={{ width: size, height: size, borderRadius: radius, overflow: 'hidden', borderWidth: 2, borderColor: defaultRingColor ?? 'rgba(255,255,255,0.95)' }}>\n      {inner}\n    </View>\n  );\n\n  if (!onPress) return avatarBody;\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={status ? `Avatar de ${name ?? 'usuario'} con estado: ${status.preset.emoji} ${status.text || status.preset.label}` : `Avatar de ${name ?? 'usuario'}`}\n      style={({ pressed }) => [ringStyle, { opacity: pressed ? 0.85 : 1 }]}\n    >\n      {avatarBody}\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  img: { width: '100%', height: '100%' },\n  fallback: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  initial: { color: brand.white, fontWeight: '900' },\n});\n","/**\n * ESTADO 24H (v3) — constantes y utilidades de la UI.\n * El catálogo real de presets viene del servidor (/status/presets); aquí viven\n * los DEGRADADOS (bg → colores) y utilidades de formato/copy.\n */\n\n/** Máximo de caracteres de la línea del estado (alineado con el backend). */\nexport const STATUS_TEXT_MAX = 40;\n\n/** Degradados del estado: clave → [color inicio, color fin]. */\nexport const STATUS_BGS: Record<string, [string, string]> = {\n  ocean: ['#1E6FD9', '#3AA0FF'],\n  sky: ['#1291D6', '#7FD4FF'],\n  sunset: ['#F2613F', '#FFB25E'],\n  mint: ['#0FA98C', '#5FE0BD'],\n  grape: ['#7B4BE0', '#C08BFF'],\n  berry: ['#E0397B', '#FF8FB2'],\n  gold: ['#D99E2B', '#FFE08A'],\n  night: ['#2B3A55', '#5A6F94'],\n};\n\n/** Resuelve una clave de fondo a colores (default ocean). */\nexport function statusBgColors(bg?: string | null): [string, string] {\n  if (bg && STATUS_BGS[bg]) return STATUS_BGS[bg];\n  return STATUS_BGS.ocean;\n}\n\n/** Opciones de visibilidad (UI español → valor API). */\nexport const VISIBILITY_OPTIONS: Array<{\n  value: 'public' | 'followers' | 'private';\n  label: string;\n  hint: string;\n}> = [\n  { value: 'public', label: 'Todos', hint: 'Lo ve cualquiera' },\n  { value: 'followers', label: 'Seguidores', hint: 'Solo quien te sigue' },\n  { value: 'private', label: 'Solo yo', hint: 'Solo tú lo verás' },\n];\n\n/** Copia de visibilidad legible. */\nexport const VISIBILITY_LABEL: Record<string, string> = {\n  public: 'Público',\n  followers: 'Seguidores',\n  private: 'Solo yo',\n};\n\n/** Formato completo del tiempo restante. */\nexport function formatRemaining(ms: number): string {\n  if (ms <= 0) return 'expirado';\n  const h = Math.floor(ms / 3_600_000);\n  const m = Math.floor((ms % 3_600_000) / 60_000);\n  if (h >= 24) return '24 h';\n  if (h >= 1) return `${h} h${m > 0 ? ` ${m} min` : ''}`;\n  if (m >= 1) return `quedan ${m} min`;\n  return 'quedan minutos';\n}\n\n/** Etiqueta corta para chips. */\nexport function remainingShort(ms: number): string {\n  if (ms <= 0) return '0 h';\n  const h = Math.floor(ms / 3_600_000);\n  const m = Math.floor((ms % 3_600_000) / 60_000);\n  if (h >= 1) return `${h} h`;\n  return `${Math.max(1, m)} min`;\n}\n\n/** Razones de reporte (UI español → valor API). */\nexport const REPORT_REASONS: Array<{ value: string; label: string }> = [\n  { value: 'spam', label: 'Spam' },\n  { value: 'fraud', label: 'Fraude' },\n  { value: 'sexual', label: 'Contenido sexual' },\n  { value: 'violence', label: 'Violencia' },\n  { value: 'impersonation', label: 'Suplantación' },\n  { value: 'personal_info', label: 'Información personal' },\n  { value: 'false_emergency', label: 'Emergencia falsa' },\n  { value: 'illegal', label: 'Contenido ilegal' },\n];\n","/**\n * StatusChip — píldora del ESTADO 24H (v3, sobria).\n * Muestra: punto/anillo de color del preset + emoji + línea corta + reloj con\n * el tiempo restante (countdown con reloj de servidor). Fondo neutro ligero\n * con borde; el color del preset solo como acento (NO tarjetas de degradado\n * gigantes).\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { Clock } from 'lucide-react-native';\nimport { useTheme } from '../../theme/ThemeContext';\nimport { statusBgColors, remainingShort } from '../../constants/status';\nimport { useServerClock, formatRemainingMs } from '../../hooks/useServerClock';\nimport type { UserStatus } from '../../api/status';\nimport { brand, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\nexport default function StatusChip({\n  status,\n  onPress,\n  compact,\n  foreground,\n  onExpired,\n}: {\n  status: UserStatus;\n  onPress?: () => void;\n  /** compact: versión minúscula (Home / listas). */\n  compact?: boolean;\n  /** Color del texto cuando el chip va sobre una portada/imagen. */\n  foreground?: string;\n  /** Se llama cuando el countdown llega a 0 (el padre decide ocultar). */\n  onExpired?: () => void;\n}) {\n  const { colors } = useTheme();\n  const nowS = useServerClock(30_000); // tick cada 30 s con reloj del servidor\n  const expiresMs = status.expiresAt ? new Date(status.expiresAt).getTime() : 0;\n  const remainingMs = expiresMs ? Math.max(0, expiresMs - (nowS)) : 0;\n\n  React.useEffect(() => {\n    if (remainingMs <= 0 && expiresMs && onExpired) {\n      const t = setTimeout(onExpired, 400);\n      return () => clearTimeout(t);\n    }\n  }, [remainingMs, expiresMs, onExpired]);\n\n  const [c1, c2] = statusBgColors(status.preset.bg);\n  const label = status.text || status.preset.label || 'Estado';\n  const remaining = status.remainingSeconds != null && status.remainingSeconds <= 0\n    ? '—'\n    : remainingShort(remainingMs);\n\n  const chip = (\n    <View\n      style={[\n        styles.chip,\n        compact && styles.chipCompact,\n        { backgroundColor: compact ? 'rgba(255,255,255,0.16)' : colors.surface, borderColor: 'rgba(255,255,255,0.28)' },\n      ]}\n    >\n      <View style={[styles.dot, { backgroundColor: c1 }]} />\n      <Text style={[styles.emoji, compact && styles.emojiCompact]}>{status.preset.emoji}</Text>\n      <Text style={[styles.text, compact && styles.textCompact, { color: foreground ?? (compact ? brand.white : colors.textPrimary) }]} numberOfLines={1}>\n        {label}\n      </Text>\n      <View style={styles.timeRow}>\n        <Clock size={compact ? 9 : 10} color={foreground ?? (compact ? 'rgba(255,255,255,0.9)' : colors.textSecondary)} />\n        <Text style={[styles.time, compact && styles.timeCompact, { color: foreground ?? (compact ? 'rgba(255,255,255,0.95)' : colors.textSecondary) }]}>\n          {remaining}\n        </Text>\n      </View>\n    </View>\n  );\n\n  if (!onPress) return chip;\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`Estado: ${status.preset.emoji} ${label}. Quedan ${formatRemainingMs(remainingMs)}. Toca para ver`}\n      style={({ pressed }) => ({ alignSelf: 'flex-start', opacity: pressed ? 0.85 : 1 })}\n    >\n      {chip}\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  chip: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e5,\n    alignSelf: 'flex-start',\n    borderRadius: radios.full,\n    borderWidth: 1,\n    paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5,\n    marginTop: espaciado.e4,\n  },\n  chipCompact: { paddingHorizontal: espaciado.e8, paddingVertical: 2.5, marginTop: espaciado.e2 },\n  dot: { width: 7, height: 7, borderRadius: 4 },\n  emoji: { fontSize: tipografia.body },\n  emojiCompact: { fontSize: 10 },\n  text: { fontSize: tipografia.caption, fontWeight: '800', maxWidth: 180 },\n  textCompact: { fontSize: 10.5, maxWidth: 140 },\n  timeRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginLeft: espaciado.e2 },\n  time: { fontSize: 10, fontWeight: '700' },\n  timeCompact: { fontSize: 8.5 },\n});\n","/**\r\n * StatusDetailModal — detalle del ESTADO 24H (vista \"story\", rediseño 2026-09-09).\r\n *\r\n * Al tocar el estado se abre una vista INMERSIVA a pantalla casi completa:\r\n *  · La FOTO ocupa ~60% del alto de la pantalla (o el fondo del preset con el\r\n *    emoji gigante si el estado no lleva foto).\r\n *  · El EMOJI + la LÍNEA se superponen sobre la parte baja de la foto (con\r\n *    degradado oscuro para legibilidad).\r\n *  · Si hay VARIAS fotos: swipe horizontal + puntos indicadores (1/4).\r\n *  · Tocar la foto → visor 100% (foto completa, sin recortes) con cerrar.\r\n *  · Zona inferior: autor (avatar+nombre+tiempo), ubicación, enlace a servicio\r\n *    y acciones: Finalizar (propio) / Compartir / Reportar (ajeno).\r\n */\r\n\r\nimport React, { useEffect, useRef, useState } from 'react';\r\nimport {\r\n  ActivityIndicator, Alert, Dimensions, Image, Modal, Pressable, ScrollView,\r\n  Share, StyleSheet, Text, View, type NativeScrollEvent, type NativeSyntheticEvent,\r\n} from 'react-native';\r\nimport { useRouter } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { Clock, Flag, MapPin, Share2, X, ZoomIn } from 'lucide-react-native';\r\nimport { espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport type { MeProfile } from '../../api/auth';\r\nimport type { UserStatus, StatusMediaItem } from '../../api/status';\r\nimport { absUrl } from '../../api/config';\r\nimport StatusRingAvatar from './StatusRingAvatar';\r\nimport { statusBgColors } from '../../constants/status';\r\nimport { useStatusStore } from '../../state/statusStore';\r\nimport { useServerClock, formatRemainingMs } from '../../hooks/useServerClock';\r\nimport { REPORT_REASONS } from '../../constants/status';\r\nimport Svg, { Defs, LinearGradient as SvgLinearGradient, Rect, Stop } from 'react-native-svg';\r\nimport { ir as irSeguro } from '../../constants/rutas';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\nconst { height: WIN_H, width: WIN_W } = Dimensions.get('window');\r\nconst HERO_H = Math.round(WIN_H * 0.60);\r\n\r\nexport default function StatusDetailModal({\r\n  visible,\r\n  status,\r\n  author,\r\n  isMine,\r\n  onClose,\r\n  onEnded,\r\n}: {\r\n  visible: boolean;\r\n  status: UserStatus;\r\n  author?: Pick<MeProfile, 'id' | 'fullName' | 'avatarUrl' | 'role' | 'nameColor'> | null;\r\n  isMine?: boolean;\r\n  onClose: () => void;\r\n  onEnded?: () => void;\r\n}) {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const { report, end } = useStatusStore();\r\n  const [busy, setBusy] = useState(false);\r\n  const [reportOpen, setReportOpen] = useState(false);\r\n  const [photoIdx, setPhotoIdx] = useState(0);\r\n  const [lightbox, setLightbox] = useState(false);\r\n  const endedRef = useRef(false);\r\n  const nowS = useServerClock(30_000);\r\n  const expiresMs = status.expiresAt ? new Date(status.expiresAt).getTime() : 0;\r\n  const remainingMs = expiresMs ? Math.max(0, expiresMs - nowS) : 0;\r\n  const [c1, c2] = statusBgColors(status.preset.bg);\r\n  const mine = isMine ?? !author;\r\n\r\n  const gallery: StatusMediaItem[] = status.gallery?.length ? status.gallery : (status.media ? [status.media] : []);\r\n  const hasPhotos = gallery.length > 0;\r\n  const line = status.text || status.preset.label || '';\r\n\r\n  useEffect(() => {\r\n    if (visible) { setReportOpen(false); endedRef.current = false; setBusy(false); setPhotoIdx(0); }\r\n  }, [visible]);\r\n\r\n  useEffect(() => {\r\n    if (visible && remainingMs <= 0 && expiresMs && !endedRef.current) {\r\n      const t = setTimeout(() => { endedRef.current = true; onClose(); }, 400);\r\n      return () => clearTimeout(t);\r\n    }\r\n  }, [remainingMs, expiresMs, visible, onClose]);\r\n\r\n  const onScroll = (e: NativeSyntheticEvent<NativeScrollEvent>) => {\r\n    const idx = Math.round(e.nativeEvent.contentOffset.x / WIN_W);\r\n    if (idx >= 0 && idx !== photoIdx) setPhotoIdx(idx);\r\n  };\r\n\r\n  const doReport = async (reason: string) => {\r\n    if (busy) return;\r\n    setBusy(true);\r\n    try {\r\n      const okR = await report(status.id, reason);\r\n      Alert.alert('Gracias', okR ? 'Hemos recibido tu reporte.' : 'No se pudo enviar el reporte.');\r\n      setReportOpen(false);\r\n    } catch (e) {\r\n      Alert.alert('Reporte', e instanceof Error ? e.message : 'No se pudo enviar el reporte.');\r\n    } finally { setBusy(false); }\r\n  };\r\n\r\n  const doEnd = () => {\r\n    Alert.alert('Finalizar estado', '¿Quitar tu estado? Desaparecerá para todos.', [\r\n      { text: 'Cancelar', style: 'cancel' },\r\n      {\r\n        text: 'Finalizar', style: 'destructive',\r\n        onPress: async () => {\r\n          setBusy(true);\r\n          try {\r\n            await end();\r\n            onEnded?.();\r\n            onClose();\r\n          } catch (e) {\r\n            Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo finalizar');\r\n          } finally { setBusy(false); }\r\n        },\r\n      },\r\n    ]);\r\n  };\r\n\r\n  const share = () => {\r\n    const label = `${status.preset.emoji} ${line}`;\r\n    Share.share({ message: `Mi estado en EG Route Plan: ${label} · dura 24 h` }).catch(() => {});\r\n  };\r\n\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={styles.root}>\r\n        {/* ===== HERO: foto ~60% o fondo del preset ===== */}\r\n        <View style={[styles.hero, { height: HERO_H }]}>\r\n          {hasPhotos ? (\r\n            <ScrollView\r\n              horizontal\r\n              pagingEnabled\r\n              showsHorizontalScrollIndicator={false}\r\n              onScroll={onScroll}\r\n              scrollEventThrottle={32}\r\n              style={styles.heroScroll}\r\n            >\r\n              {gallery.map((m, i) => (\r\n                <Pressable\r\n                  key={m.id}\r\n                  onPress={() => setLightbox(true)}\r\n                  accessibilityRole=\"button\"\r\n                  accessibilityLabel={`Ver foto ${i + 1} a pantalla completa`}\r\n                  style={{ width: WIN_W, height: HERO_H }}\r\n                >\r\n                  <Image source={{ uri: absUrl(m.url) }} style={StyleSheet.absoluteFill} resizeMode=\"cover\" />\r\n                </Pressable>\r\n              ))}\r\n            </ScrollView>\r\n          ) : (\r\n            <Svg height=\"100%\" width=\"100%\" style={StyleSheet.absoluteFill}>\r\n              <Defs>\r\n                <SvgLinearGradient id={`hero-${status.id}`} x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\r\n                  <Stop offset=\"0\" stopColor={c1} />\r\n                  <Stop offset=\"1\" stopColor={c2} />\r\n                </SvgLinearGradient>\r\n              </Defs>\r\n              <Rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill={`url(#hero-${status.id})`} />\r\n            </Svg>\r\n          )}\r\n\r\n          {/* Degradado inferior del hero (legibilidad del texto superpuesto) */}\r\n          <View pointerEvents=\"none\" style={styles.heroFade}>\r\n            <Svg height=\"100%\" width=\"100%\">\r\n              <Defs>\r\n                <SvgLinearGradient id=\"heroFade\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\r\n                  <Stop offset=\"0.45\" stopColor=\"#000000\" stopOpacity=\"0\" />\r\n                  <Stop offset=\"1\" stopColor=\"#000000\" stopOpacity=\"0.72\" />\r\n                </SvgLinearGradient>\r\n              </Defs>\r\n              <Rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill=\"url(#heroFade)\" />\r\n            </Svg>\r\n          </View>\r\n\r\n          {/* Cabecera flotante del hero */}\r\n          <View style={[styles.heroHeader, { top: insets.top + 8 }]}>\r\n            <StatusRingAvatar\r\n              avatarUrl={author?.avatarUrl ?? null}\r\n              name={author?.fullName}\r\n              status={status}\r\n              size={38}\r\n              ringWidth={3}\r\n            />\r\n            <View style={{ flex: 1, marginLeft: espaciado.e8 }}>\r\n              <Text style={styles.heroName} numberOfLines={1}>{author?.fullName ?? 'Mi estado'}</Text>\r\n              {remainingMs > 0 && (\r\n                <View style={styles.timeRow}>\r\n                  <Clock size={10} color=\"rgba(255,255,255,0.9)\" />\r\n                  <Text style={styles.timeTxt}>quedan {formatRemainingMs(remainingMs)}</Text>\r\n                </View>\r\n              )}\r\n            </View>\r\n            <Pressable onPress={onClose} hitSlop={12} accessibilityLabel=\"Cerrar\" style={styles.iconBtn}>\r\n              <X size={22} color={brand.white} />\r\n            </Pressable>\r\n          </View>\r\n\r\n          {/* Texto + emoji SUPERPUESTO en la parte baja del hero */}\r\n          {line ? (\r\n            <View style={[styles.overlayText, { bottom: hasPhotos ? 34 : 24 }]} pointerEvents=\"none\">\r\n              {!hasPhotos ? <Text style={styles.overlayEmoji}>{status.preset.emoji}</Text> : null}\r\n              <Text style={styles.overlayLine} numberOfLines={3}>{line}</Text>\r\n            </View>\r\n          ) : null}\r\n\r\n          {/* Puntos de galería */}\r\n          {hasPhotos && gallery.length > 1 ? (\r\n            <View style={styles.dots}>\r\n              {gallery.map((m, i) => (\r\n                <View key={m.id} style={[styles.dot, { opacity: i === photoIdx ? 1 : 0.45, backgroundColor: i === photoIdx ? brand.white : brand.white }]} />\r\n              ))}\r\n            </View>\r\n          ) : null}\r\n        </View>\r\n\r\n        {/* ===== ZONA INFERIOR (autor, ubicación, enlace, acciones) ===== */}\r\n        <View style={[styles.footer, { paddingBottom: insets.bottom + 16, backgroundColor: colors.background }]}>\r\n          <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ flexGrow: 1 }}>\r\n            {status.locationText ? (\r\n              <View style={styles.locRow}>\r\n                <MapPin size={13} color={colors.textSecondary} />\r\n                <Text style={[styles.locTxt, { color: colors.textSecondary }]}>{status.locationText}</Text>\r\n              </View>\r\n            ) : null}\r\n\r\n            {hasPhotos && (\r\n              <Pressable onPress={() => setLightbox(true)} accessibilityRole=\"button\" accessibilityLabel=\"Ver foto a pantalla completa\" style={styles.zoomHintRow}>\r\n                <ZoomIn size={13} color={colors.textSecondary} />\r\n                <Text style={[styles.zoomHint, { color: colors.textSecondary }]}>\r\n                  Toca la foto para verla en grande\r\n                </Text>\r\n              </Pressable>\r\n            )}\r\n\r\n            {status.link && <ServiceLink status={status} colors={colors} onOpen={() => onClose()} />}\r\n\r\n            <View style={styles.actions}>\r\n              <Pressable onPress={share} accessibilityRole=\"button\" style={[styles.action, { backgroundColor: colors.surface }]}>\r\n                <Share2 size={17} color={colors.textSecondary} />\r\n                <Text style={[styles.actionTxt, { color: colors.textSecondary }]}>Compartir</Text>\r\n              </Pressable>\r\n              {mine ? (\r\n                <Pressable onPress={doEnd} disabled={busy} accessibilityRole=\"button\" style={[styles.action, { backgroundColor: 'rgba(245,63,63,0.10)' }]}>\r\n                  {busy ? <ActivityIndicator color={brand.danger} size=\"small\" /> : <Text style={[styles.actionTxt, { color: brand.danger }]}>Finalizar</Text>}\r\n                </Pressable>\r\n              ) : (\r\n                <Pressable onPress={() => setReportOpen(true)} accessibilityRole=\"button\" style={[styles.action, { backgroundColor: 'rgba(245,63,63,0.10)' }]}>\r\n                  <Flag size={17} color={brand.danger} />\r\n                  <Text style={[styles.actionTxt, { color: brand.danger }]}>Reportar</Text>\r\n                </Pressable>\r\n              )}\r\n            </View>\r\n\r\n            {reportOpen && (\r\n              <View style={[styles.reportBox, { backgroundColor: colors.surface }]}>\r\n                <Text style={[styles.reportTitle, { color: colors.textPrimary }]}>¿Por qué reportas este estado?</Text>\r\n                {REPORT_REASONS.map((r) => (\r\n                  <Pressable key={r.value} onPress={() => doReport(r.value)} disabled={busy} accessibilityRole=\"button\" style={({ pressed }) => [styles.reportRow, { borderBottomColor: colors.border, opacity: pressed ? 0.6 : 1 }]}>\r\n                    <Text style={[styles.reportRowTxt, { color: colors.textPrimary }]}>{r.label}</Text>\r\n                  </Pressable>\r\n                ))}\r\n                <Pressable onPress={() => setReportOpen(false)} accessibilityRole=\"button\" style={{ paddingVertical: espaciado.e10 }}>\r\n                  <Text style={[styles.reportCancel, { color: colors.textSecondary }]}>Cancelar</Text>\r\n                </Pressable>\r\n              </View>\r\n            )}\r\n          </ScrollView>\r\n        </View>\r\n      </View>\r\n\r\n      {/* ===== VISOR 100% (lightbox) ===== */}\r\n      <FullScreenViewer\r\n        visible={lightbox && hasPhotos}\r\n        photos={gallery}\r\n        startIndex={photoIdx}\r\n        onClose={() => setLightbox(false)}\r\n      />\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Enlace a servicio (fila discreta). */\r\nfunction ServiceLink({ status, colors, onOpen }: { status: UserStatus; colors: any; onOpen: () => void }) {\r\n  const router = useRouter();\r\n  const ROUTES: Record<string, string> = {\r\n    taxi: '/taxi', intercity: '/intercity', food: '/food',\r\n    ecomerse: '/ecomerse', rental: '/alquiler', work: '/work',\r\n  };\r\n  const labelMap: Record<string, string> = {\r\n    taxi: 'Llamar taxi', intercity: 'Ciudad a Ciudad', food: 'Ver restaurante',\r\n    ecomerse: 'Ver tienda', rental: 'Ver anuncio', work: 'Ver oferta',\r\n  };\r\n  if (!status.link || !ROUTES[status.link.type]) return null;\r\n  const link = status.link;\r\n  const route = ROUTES[link.type];\r\n  return (\r\n    <Pressable\r\n      onPress={() => { onOpen(); irSeguro.libre(String(route ?? '')); }}\r\n      accessibilityRole=\"button\"\r\n      style={({ pressed }) => [styles.serviceBtn, { backgroundColor: 'rgba(0,132,255,0.08)', opacity: pressed ? 0.8 : 1 }]}\r\n    >\r\n      <Text style={{ color: brand.primary, fontSize: tipografia.body, fontWeight: '900' }}>\r\n        {labelMap[link.type] ?? 'Ver servicio'} →\r\n      </Text>\r\n    </Pressable>\r\n  );\r\n}\r\n\r\n/**\r\n * FullScreenViewer — visor de la foto a pantalla completa (100%, sin recortes),\r\n * con swipe horizontal entre fotos y botón cerrar (estilo WhatsApp).\r\n */\r\nfunction FullScreenViewer({ visible, photos, startIndex, onClose }: {\r\n  visible: boolean;\r\n  photos: StatusMediaItem[];\r\n  startIndex: number;\r\n  onClose: () => void;\r\n}) {\r\n  const insets = useSafeAreaInsets();\r\n  const scrollRef = useRef<ScrollView>(null);\r\n  const [idx, setIdx] = useState(startIndex);\r\n\r\n  useEffect(() => {\r\n    if (visible) {\r\n      setIdx(startIndex);\r\n      setTimeout(() => scrollRef.current?.scrollTo({ x: startIndex * WIN_W, animated: false }), 30);\r\n    }\r\n  }, [visible, startIndex]);\r\n\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={styles.lightbox}>\r\n        <Pressable onPress={onClose} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar visor\" style={[styles.lightboxClose, { top: insets.top + 10 }]}>\r\n          <X size={24} color={brand.white} />\r\n        </Pressable>\r\n        {photos.length > 1 && (\r\n          <View style={[styles.lightboxCounter, { top: insets.top + 16 }]}>\r\n            <Text style={styles.lightboxCounterTxt}>{idx + 1}/{photos.length}</Text>\r\n          </View>\r\n        )}\r\n        <ScrollView\r\n          ref={scrollRef}\r\n          horizontal\r\n          pagingEnabled\r\n          showsHorizontalScrollIndicator={false}\r\n          onScroll={(e) => setIdx(Math.round(e.nativeEvent.contentOffset.x / WIN_W))}\r\n          scrollEventThrottle={32}\r\n        >\r\n          {photos.map((p) => (\r\n            <View key={p.id} style={{ width: WIN_W, height: WIN_H }}>\r\n              <FitFullImage uri={absUrl(p.url)} />\r\n            </View>\r\n          ))}\r\n        </ScrollView>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Imagen a pantalla completa: contain (nunca se recorta). */\r\nfunction FitFullImage({ uri }: { uri: string }) {\r\n  const [natural, setNatural] = useState<{ w: number; h: number } | null>(null);\r\n  useEffect(() => {\r\n    let alive = true;\r\n    Image.getSize(uri, (w, h) => { if (alive && w > 0 && h > 0) setNatural({ w, h }); }, () => { if (alive) setNatural({ w: 4, h: 3 }); });\r\n    return () => { alive = false; };\r\n  }, [uri]);\r\n  return (\r\n    <View style={{ width: WIN_W, height: WIN_H }}>\r\n      {natural ? (\r\n        <Image source={{ uri }} style={StyleSheet.absoluteFill} resizeMode=\"contain\" />\r\n      ) : (\r\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><ActivityIndicator color={brand.white} /></View>\r\n      )}\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1, backgroundColor: '#000000' },\r\n  hero: { width: '100%', overflow: 'hidden' },\r\n  heroScroll: { flexGrow: 0 },\r\n  heroFade: { ...StyleSheet.absoluteFillObject },\r\n  heroHeader: {\r\n    position: 'absolute', left: 14, right: 14,\r\n    flexDirection: 'row', alignItems: 'center',\r\n  },\r\n  heroName: { color: brand.white, fontSize: 15, fontWeight: '900', textShadowColor: 'rgba(0,0,0,0.6)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 4 },\r\n  timeRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginTop: 1 },\r\n  timeTxt: { color: 'rgba(255,255,255,0.95)', fontSize: tipografia.micro, fontWeight: '700', textShadowColor: 'rgba(0,0,0,0.6)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 3 },\r\n  iconBtn: { width: 36, height: 36, borderRadius: 18, backgroundColor: 'rgba(0,0,0,0.35)', alignItems: 'center', justifyContent: 'center', borderWidth: 1, borderColor: 'rgba(255,255,255,0.35)' },\r\n  overlayText: { position: 'absolute', left: 18, right: 18 },\r\n  overlayEmoji: { fontSize: 46, textShadowColor: 'rgba(0,0,0,0.5)', textShadowOffset: { width: 0, height: 2 }, textShadowRadius: 6 },\r\n  overlayLine: {\r\n    color: brand.white, fontSize: 22, fontWeight: '900', lineHeight: 29,\r\n    textShadowColor: 'rgba(0,0,0,0.7)', textShadowOffset: { width: 0, height: 2 }, textShadowRadius: 6,\r\n  },\r\n  dots: { position: 'absolute', bottom: 10, alignSelf: 'center', flexDirection: 'row', gap: espaciado.e6 },\r\n  dot: { width: 7, height: 7, borderRadius: 4 },\r\n  footer: { flex: 1, paddingHorizontal: espaciado.e18, paddingTop: espaciado.e14 },\r\n  locRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, marginBottom: espaciado.e8 },\r\n  locTxt: { fontSize: tipografia.caption, fontWeight: '600' },\r\n  zoomHintRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginBottom: espaciado.e12 },\r\n  zoomHint: { fontSize: tipografia.caption, fontWeight: '600', fontStyle: 'italic' },\r\n  serviceBtn: { borderRadius: 14, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e14, marginBottom: espaciado.e12, alignItems: 'center' },\r\n  actions: { flexDirection: 'row', gap: espaciado.e10 },\r\n  action: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, borderRadius: 14, paddingVertical: espaciado.e12 },\r\n  actionTxt: { fontSize: tipografia.body, fontWeight: '800' },\r\n  reportBox: { borderRadius: 14, padding: espaciado.e12, marginTop: espaciado.e14 },\r\n  reportTitle: { fontSize: tipografia.body, fontWeight: '900', marginBottom: espaciado.e4 },\r\n  reportRow: { paddingVertical: espaciado.e11, borderBottomWidth: 1 },\r\n  reportRowTxt: { fontSize: tipografia.body, fontWeight: '600' },\r\n  reportCancel: { fontSize: tipografia.body, fontWeight: '700', textAlign: 'center', marginTop: espaciado.e4 },\r\n  lightbox: { flex: 1, backgroundColor: '#000000' },\r\n  lightboxClose: { position: 'absolute', right: 16, zIndex: 10, width: 40, height: 40, borderRadius: 20, backgroundColor: 'rgba(255,255,255,0.18)', alignItems: 'center', justifyContent: 'center' },\r\n  lightboxCounter: { position: 'absolute', left: 18, zIndex: 10, backgroundColor: 'rgba(0,0,0,0.5)', borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e4 },\r\n  lightboxCounterTxt: { color: brand.white, fontSize: tipografia.caption, fontWeight: '900' },\r\n});\r\n","/**\n * LocationModal — selector de ciudad (bottom card) con las ciudades de\n * Guinea Ecuatorial, agrupadas por provincia y con SCROLL (auditoría:\n * 24 filas sin scroll quedaban fuera de pantalla en móviles pequeños).\n * Controlado por la Home (visible / onClose / onSelect).\n *\n * Correcciones (auditoría 2026-09-02):\n *  · ScrollView + secciones por provincia (regresión del borrador evitada).\n *  · Fila como radio con accessibilityState.selected + hint (provincia).\n *  · hitSlop/ripple/testID; paddingBottom con insets (home indicator iOS).\n *  · Sin importantForAccessibility=\"no-hide-descendants\" en el backdrop:\n *    eso ocultaría TODA la tarjeta a los lectores (la tarjeta es su hija).\n */\n\nimport React, { useMemo } from 'react';\nimport { espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\nimport { Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { MapPin, X, Check } from 'lucide-react-native';\nimport { CITIES, type City } from '../constants/data';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\n\nexport default function LocationModal({\n  visible,\n  currentCityId,\n  onClose,\n  onSelect,\n}: {\n  visible: boolean;\n  currentCityId: string;\n  onClose: () => void;\n  onSelect: (city: City) => void;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n\n  // CITIES ya vienen agrupadas por provincia: secciones con su orden.\n  const sections = useMemo(() => {\n    const out: Array<{ region: string; cities: City[] }> = [];\n    for (const city of CITIES) {\n      const last = out[out.length - 1];\n      if (last && last.region === city.region) last.cities.push(city);\n      else out.push({ region: city.region, cities: [city] });\n    }\n    return out;\n  }, []);\n\n  if (sections.length === 0) {\n    return (\n      <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\n        <View style={[styles.backdrop, { backgroundColor: colors.overlay }]}>\n          <View style={[styles.card, { backgroundColor: colors.card, paddingBottom: insets.bottom + 24 }]}>\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Elige tu ciudad</Text>\n            <Text style={{ color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e20 }}>No hay ciudades disponibles.</Text>\n          </View>\n        </View>\n      </Modal>\n    );\n  }\n\n  return (\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} accessibilityViewIsModal>\n        <Pressable\n          style={[styles.card, { backgroundColor: colors.card, paddingBottom: insets.bottom + 24 }]}\n          onPress={(e) => e.stopPropagation()}\n          accessibilityRole=\"none\"\n        >\n          <View style={styles.header}>\n            <Text style={[styles.title, { color: colors.textPrimary }]} accessibilityRole=\"header\">\n              Elige tu ciudad\n            </Text>\n            <Pressable\n              onPress={onClose}\n              hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Cerrar\"\n              accessibilityHint=\"Cierra el selector de ciudad\"\n              testID=\"location-modal-close\"\n              style={({ pressed }) => ({ opacity: pressed ? 0.6 : 1 })}\n            >\n              <X size={20} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n\n          <ScrollView style={{ maxHeight: '72%' }} showsVerticalScrollIndicator={false}>\n            {sections.map((sec) => (\n              <View key={sec.region}>\n                <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>{sec.region}</Text>\n                {sec.cities.map((city) => {\n                  const active = city.id === currentCityId;\n                  return (\n                    <Pressable\n                      key={city.id}\n                      onPress={() => { onSelect(city); onClose(); }}\n                      testID={`location-modal-city-${city.id}`}\n                      accessibilityRole=\"radio\"\n                      accessibilityLabel={city.name}\n                      accessibilityHint={`Provincia ${sec.region}. Toca para seleccionar`}\n                      accessibilityState={{ selected: active }}\n                      android_ripple={{ color: alpha(colors.primary, 0.1), borderless: false, foreground: true }}\n                      style={({ pressed }) => [\n                        styles.row,\n                        { backgroundColor: pressed ? alpha(colors.primary, 0.06) : active ? alpha(colors.primary, 0.04) : 'transparent' },\n                      ]}\n                    >\n                      <View style={[styles.pinWrap, { backgroundColor: active ? alpha(colors.primary, 0.15) : alpha(colors.primary, 0.08) }]}>\n                        <MapPin size={16} color={active ? colors.primary : colors.textSecondary} />\n                      </View>\n                      <View style={styles.rowText}>\n                        <Text style={[styles.cityName, { color: active ? colors.primary : colors.textPrimary, fontWeight: active ? '800' : '700' }]}>\n                          {city.name}\n                        </Text>\n                      </View>\n                      {active && <Check size={18} color={colors.primary} />}\n                    </Pressable>\n                  );\n                })}\n              </View>\n            ))}\n          </ScrollView>\n        </Pressable>\n      </Pressable>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { flex: 1, justifyContent: 'flex-end' },\n  card: {\n    borderTopLeftRadius: 24,\n    borderTopRightRadius: 24,\n    paddingHorizontal: espaciado.e20,\n    paddingTop: espaciado.e18,\n    maxHeight: '85%',\n  },\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: espaciado.e10 },\n  title: { fontSize: 17, fontWeight: '800' },\n  sectionHeader: { fontSize: tipografia.micro, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.4, marginTop: espaciado.e10, marginBottom: espaciado.e2, marginLeft: espaciado.e8 },\n  row: { flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e11, paddingHorizontal: espaciado.e8, borderRadius: 14, marginBottom: espaciado.e4 },\n  pinWrap: { width: 34, height: 34, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  rowText: { flex: 1, marginLeft: espaciado.e12 },\n  cityName: { fontSize: 15 },\n});\n","/**\n * MapTools — botones flotantes superiores-derecha sobre el mapa:\n *   · Recentrar en la ciudad activa (label honesto vía `recenterLabel`).\n *   · Escáner / traducción de documentos.\n *\n * Correcciones (auditoría 2026-09-02):\n *  · `recenterLabel` propagable (la Home dice \"Centrar en {ciudad}\" — sin GPS\n *    no hay \"mi ubicación\").\n *  · accessibilityHint separado; hitSlop 44px mínimo; ripple nativo Android.\n *  · Sombras solo iOS / elevation solo Android. Sin accessibilityElementsHidden\n *    (eso ocultaría los botones de los lectores).\n */\n\nimport React from 'react';\nimport { Platform, Pressable, StyleSheet, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useRouter } from 'expo-router';\nimport { LocateFixed, ScanLine, Cross } from 'lucide-react-native';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand, espaciado } from '@egrouteplan/ui-kit';\n\nexport default function MapTools({ onRecenter, recenterLabel = 'Centrar en mi ubicación', topOffset = 10, onEmergency }: {\n  onRecenter: () => void;\n  recenterLabel?: string;\n  /** Desplazamiento desde la safe-area (la Home social lo baja bajo la portada). */\n  topOffset?: number;\n  /** Abre el modal de emergencia (botón flotante con cruz médica, sobre el mapa). */\n  onEmergency?: () => void;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  return (\n    <View style={[styles.stack, { top: insets.top + topOffset }]} pointerEvents=\"box-none\">\n      {onEmergency && (\n        <ToolButton\n          label=\"Emergencia\"\n          hint=\"Llama a Policía, Hospital o emergencias\"\n          onPress={onEmergency}\n          colors={colors}\n          danger\n          icon={<Cross size={22} color={brand.white} strokeWidth={2.6} />}\n          testID=\"map-tools-emergency\"\n        />\n      )}\n      <ToolButton\n        label={recenterLabel}\n        hint=\"Te centra en tu posición GPS real dentro de Guinea Ecuatorial (o en la ciudad activa)\"\n        onPress={onRecenter}\n        colors={colors}\n        icon={<LocateFixed size={20} color={colors.primary} />}\n        testID=\"map-tools-recenter\"\n      />\n      <ToolButton\n        label=\"Escanear documento\"\n        hint=\"Abre el escáner para traducir documentos\"\n        onPress={() => router.push('/scanner' as any)}\n        colors={colors}\n        icon={<ScanLine size={20} color={colors.primary} />}\n        testID=\"map-tools-scanner\"\n      />\n    </View>\n  );\n}\n\nfunction ToolButton({ label, hint, onPress, colors, danger, icon, testID }: {\n  label: string;\n  hint: string;\n  onPress: () => void;\n  colors: ReturnType<typeof useTheme>['colors'];\n  danger?: boolean;\n  icon: React.ReactNode;\n  testID?: string;\n}) {\n  return (\n    <Pressable\n      onPress={onPress}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={label}\n      accessibilityHint={hint}\n      hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}\n      android_ripple={{ color: 'rgba(0,132,255,0.12)', borderless: true, foreground: true, radius: 22 }}\n      style={({ pressed }) => [\n        styles.button,\n        {\n          backgroundColor: danger ? colors.danger : colors.card,\n          borderColor: danger ? alpha(colors.danger, 0.4) : colors.border,\n          opacity: pressed ? 0.85 : 1,\n          transform: [{ scale: pressed ? 0.94 : 1 }],\n        },\n      ]}\n    >\n      {icon}\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  stack: { position: 'absolute', right: 16, zIndex: 20, gap: espaciado.e10 },\n  button: {\n    width: 48,\n    height: 48,\n    borderRadius: 14,\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderWidth: StyleSheet.hairlineWidth,\n    ...Platform.select({\n      ios: { shadowColor: '#17171A', shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.12, shadowRadius: 10 },\n      android: { elevation: 4 },\n    }),\n  },\n});\n","/**\n * SearchHeader — panel de búsqueda tipo DiDi (rediseño 2026-09-04).\n * Patrón capturado en ref-didi-home.png / ref-didi-search.png:\n *   · Fila 1 (origen): punto azul + \"{ciudad} · Ubicación actual\" clicable\n *     (abre el selector de ciudad) con chevron.\n *   · Campo destino GIGANTE \"¿A dónde vas?\": NO es un TextInput estático —\n *     es un botón que abre la pantalla de búsqueda /buscar (DiDi: el tap va a\n *     una pantalla de búsqueda con autofoco, atajos y sugerencias).\n * Accesibilidad: cada elemento con rol/etiqueta propios.\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { MapPin, ChevronDown, Search, Mic } from 'lucide-react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand, elevation, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\nexport default function SearchHeader({\n  city,\n  cityName,\n  onPressCity,\n  glass = false,\n}: {\n  city: string;\n  cityName?: string;\n  onPressCity: () => void;\n  /** Modo glassmorphism: tarjeta \"¿A dónde vas?\" translúcida (Home social). */\n  glass?: boolean;\n}) {\n  const { colors, isDark } = useTheme();\n  const router = useRouter();\n\n  const glassBg = isDark ? 'rgba(35,35,41,0.55)' : 'rgba(255,255,255,0.62)';\n  const glassBorder = isDark ? 'rgba(255,255,255,0.20)' : 'rgba(255,255,255,0.85)';\n  const glassSurface = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.5)';\n\n  return (\n    <View>\n      {/* Fila origen — punto verde (origen real dentro de la ciudad), clicable */}\n      <Pressable\n        onPress={onPressCity}\n        accessibilityRole=\"button\"\n        accessibilityLabel={`Ubicación actual ${city}, cambiar`}\n        style={({ pressed }) => [styles.locationRow, { opacity: pressed ? 0.7 : 1 }]}\n      >\n        <View style={[styles.originDot, { backgroundColor: brand.success }]} />\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.locationText, { color: colors.textPrimary }]} numberOfLines={1}>\n            {city}\n          </Text>\n          <Text style={[styles.cityName, { color: colors.textSecondary }]}>\n            {cityName ? `En ${cityName} · toca para cambiar de ciudad` : 'Ubicación actual'}\n          </Text>\n        </View>\n        <ChevronDown size={15} color={colors.textSecondary} />\n      </Pressable>\n\n      {/* Campo destino — botón que abre /buscar (patrón DiDi / glass) */}\n      <Pressable\n        onPress={() => router.push({ pathname: '/buscar', params: { city: cityName ?? city } } as never)}\n        accessibilityRole=\"button\"\n        accessibilityLabel=\"¿A dónde vas?\"\n        accessibilityHint=\"Abre la búsqueda de destino\"\n        style={({ pressed }) => [\n          styles.destBox,\n          glass\n            ? { backgroundColor: glassBg, borderColor: glassBorder, opacity: pressed ? 0.8 : 1 }\n            : { backgroundColor: colors.card, borderColor: colors.border, opacity: pressed ? 0.85 : 1 },\n        ]}\n      >\n        <View style={[styles.searchIconWrap, glass ? { backgroundColor: glassSurface } : { backgroundColor: alpha(colors.primary, 0.1) }]}>\n          <Search size={18} color={colors.primary} />\n        </View>\n        <Text style={[styles.destText, { color: colors.textPrimary }]}>¿A dónde vas?</Text>\n        <View style={[styles.micWrap, glass ? { backgroundColor: glassSurface } : { backgroundColor: colors.surface }]}>\n          <Mic size={15} color={colors.textSecondary} />\n        </View>\n      </Pressable>\n    </View>\n  );\n}\n\n// alpha local (evita import circular si constants/colors cambia): misma impl.\nfunction alpha(hex: string, opacity: number): string {\n  const h = hex.replace('#', '');\n  const r = parseInt(h.slice(0, 2), 16);\n  const g = parseInt(h.slice(2, 4), 16);\n  const b = parseInt(h.slice(4, 6), 16);\n  return `rgba(${r}, ${g}, ${b}, ${opacity})`;\n}\n\nconst styles = StyleSheet.create({\n  locationRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e2 },\n  originDot: { width: 11, height: 11, borderRadius: 6 },\n  locationText: { fontSize: 15, fontWeight: '800', letterSpacing: 0.1 },\n  cityName: { fontSize: tipografia.caption, fontWeight: '600', marginTop: 1 },\n  destBox: {\n    marginTop: espaciado.e12,\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e10,\n    borderWidth: StyleSheet.hairlineWidth,\n    borderRadius: 18,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e8,\n    ...elevation.sm,\n  },\n  searchIconWrap: { width: 34, height: 34, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  destText: { flex: 1, fontSize: tipografia.subtitle, fontWeight: '700', paddingVertical: espaciado.e4 },\n  micWrap: { width: 28, height: 28, borderRadius: 14, alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * ServiceGrid — cuadrícula de acceso jerárquica estilo DiDi (Fase 2, 2026-09-04).\n * Patrón capturado en ref-didi-home.png / didi-home*.xml:\n *   · PRIMARIOS (fila 1, círculos grandes): Taxi, Ciudad a Ciudad,\n *     Ser Conductor, Reservar Coche.\n *   · SECUNDARIOS (fila 2): Comida Rápida, Mercado, Buscar Alquiler,\n *     Buscar Work.\n *   · MÁS SERVICIOS (bloque inferior, chips): Mudanza, Enviar Paquete,\n *     Life Book (próximamente) + Emergencia (acento rojo).\n * Conserva el RoleGate: servicios con perfiles preguntan el rol al tocar\n * (work/alquiler/food/ecomerse); toque largo reabre el selector.\n * comingSoon: celda deshabilitada \"Próximamente\". Emergencia: abre el modal.\n */\n\nimport React, { useMemo, useState } from 'react';\nimport { espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\nimport { Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { SERVICES, type ServiceItem } from '../constants/data';\nimport { roleOptionsFor, isRoleService, type RoleOption } from '../constants/roles';\nimport { getSavedRole, saveRole } from '../state/rolePrefs';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\nimport { ir as irSeguro } from '../constants/rutas';\n\nconst PRIMARY_IDS = ['taxi', 'intercity', 'conductor', 'reservar'];\n/**\n * Fila 2 — cuatro plazas al 25 %, y estaban llenas: `['food','ecomerse','alquiler','work']`.\n *\n * Cambio del 20-sep-2026 (zona del comerciante, decisión aprobada): entra **`tienda`** pegada a\n * `ecomerse` —Mercado · Mi tienda, las dos caras del mismo mercado— y sale `work`. **`work` no\n * desaparece**: cae solo a «Más servicios» porque `more` (abajo) se calcula restando primarios y\n * secundarios. Es un cambio de una línea y el comerciante entra en su zona en un toque, sin pasar\n * por el modal de rol ni por menús secundarios.\n */\nconst SECONDARY_IDS = ['ecomerse', 'tienda', 'food', 'alquiler'];\n\nexport default function ServiceGrid({ onEmergencyPress, glass = false }: {\n  onEmergencyPress: () => void;\n  /** Modo glassmorphism (Home social): círculos translúcidos sobre el mapa. */\n  glass?: boolean;\n}) {\n  const { colors, isDark } = useTheme();\n  const router = useRouter();\n  const [choosing, setChoosing] = useState<{ service: ServiceItem; options: RoleOption[] } | null>(null);\n\n  const { primary, secondary, more } = useMemo(() => {\n    const byId = new Map(SERVICES.map((s) => [s.id, s]));\n    const pick = (ids: string[]) => ids.map((id) => byId.get(id)).filter((x): x is ServiceItem => !!x);\n    const rest = SERVICES.filter((s) => !PRIMARY_IDS.includes(s.id) && !SECONDARY_IDS.includes(s.id) && s.id !== 'lifebook');\n    return { primary: pick(PRIMARY_IDS), secondary: pick(SECONDARY_IDS), more: rest };\n  }, []);\n\n  /**\n   * NAVEGACIÓN SEGURA (zona del INICIO).\n   *\n   * Estas tres salidas llevan la ruta escrita en la lista de servicios (`constants/data.ts`). Si\n   * esa entrada apunta a una pantalla que ya no existe, antes la pulsación no hacía NADA (o\n   * expo-router enseñaba «Unmatched Route» en inglés) — y así se coló `/emergencia`, que no\n   * existía: lo encontró la auditoría (`npm run rutas`). Ahora pasa por el ayudante, que valida\n   * la ruta y, si no existe, lo explica con salida al inicio.\n   */\n  const irA = (ruta: string) => irSeguro.libre(String(ruta ?? ''));\n\n  const openForService = async (service: ServiceItem) => {\n    const options = roleOptionsFor(service.id);\n    if (options.length <= 1) {\n      if (options.length === 1) irA(options[0].route);\n      return;\n    }\n    const saved = await getSavedRole(service.id);\n    const target = options.find((o) => o.id === saved);\n    if (target) irA(target.route);\n    else setChoosing({ service, options });\n  };\n\n  const handlePress = (item: ServiceItem) => {\n    if (item.comingSoon) return;\n    if (item.tone === 'emergency') { onEmergencyPress(); return; }\n    if (isRoleService(item.id)) { void openForService(item); return; }\n    irA(item.route);\n  };\n\n  const pickRole = (option: RoleOption) => {\n    if (!choosing) return;\n    const service = choosing.service;\n    setChoosing(null);\n    void saveRole(service.id, option.id);\n    router.push(option.route as never);\n  };\n\n  /** Celda circular tipo DiDi (icono en círculo + etiqueta). */\n  const renderCell = (item: ServiceItem, compact = false) => {\n    const isEmergency = item.tone === 'emergency';\n    const disabled = !!item.comingSoon;\n    const gate = !disabled && isRoleService(item.id);\n    const tint = isEmergency ? colors.danger : disabled ? colors.textSecondary : colors.secondary;\n    const Icon = item.icon;\n    const size = compact ? 46 : 58;\n    // Glass: círculo blanco semitransparente con borde claro (se ve el fondo).\n    const circleGlass = {\n      backgroundColor: isDark ? 'rgba(35,35,41,0.5)' : 'rgba(255,255,255,0.55)',\n      borderColor: isDark ? 'rgba(255,255,255,0.18)' : 'rgba(255,255,255,0.85)',\n    };\n    return (\n      <Pressable\n        key={item.id}\n        onPress={() => handlePress(item)}\n        onLongPress={() => { if (gate) void openForService(item); }}\n        delayLongPress={450}\n        disabled={disabled}\n        accessibilityRole={disabled ? undefined : 'button'}\n        accessibilityLabel={disabled ? `${item.label}, próximamente` : `${item.label}${gate ? '. Mantén pulsado para cambiar de perfil' : ''}`}\n        accessibilityState={disabled ? { disabled: true } : undefined}\n        style={({ pressed }) => [\n          styles.cell,\n          { width: compact ? 80 : '25%', opacity: disabled ? 0.5 : pressed ? 0.6 : 1 },\n        ]}\n      >\n        <View\n          style={[\n            styles.circle,\n            {\n              width: size, height: size, borderRadius: size / 2,\n              ...(glass\n                ? circleGlass\n                : {\n                    backgroundColor: isEmergency\n                      ? alpha(colors.danger, 0.1)\n                      : alpha(tint, disabled ? 0.06 : 0.12),\n                    borderColor: alpha(tint, 0.25),\n                  }),\n            },\n          ]}\n        >\n          <Icon size={compact ? 20 : 26} color={tint} strokeWidth={2.1} />\n        </View>\n        <Text\n          style={[styles.label, { color: isEmergency ? colors.danger : disabled ? colors.textSecondary : colors.textPrimary }]}\n          numberOfLines={2}\n        >\n          {item.label}\n        </Text>\n        {disabled ? <Text style={styles.comingSoon}>Próximamente</Text> : null}\n      </Pressable>\n    );\n  };\n\n  return (\n    <>\n      {/* Fila 1 — primarios */}\n      <View style={styles.row}>{primary.map((item) => renderCell(item))}</View>\n\n      {/* Fila 2 — secundarios */}\n      <View style={[styles.row, styles.rowGapTop]}>{secondary.map((item) => renderCell(item))}</View>\n\n      {/* Más servicios + emergencia (chips) */}\n      <View style={[\n        styles.moreBlock,\n        glass\n          ? { backgroundColor: isDark ? 'rgba(35,35,41,0.45)' : 'rgba(255,255,255,0.55)', borderColor: isDark ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.8)' }\n          : { backgroundColor: colors.surface, borderColor: colors.border },\n      ]}>\n        <Text style={[styles.moreTitle, { color: colors.textSecondary }]}>Más servicios</Text>\n        <ScrollView\n          horizontal\n          showsHorizontalScrollIndicator={false}\n          contentContainerStyle={{ gap: espaciado.e10, paddingVertical: espaciado.e2 }}\n        >\n          {more.map((item) => {\n            const isEmergency = item.tone === 'emergency';\n            const disabled = !!item.comingSoon;\n            const tint = isEmergency ? colors.danger : disabled ? colors.textSecondary : colors.primary;\n            const Icon = item.icon;\n            return (\n              <Pressable\n                key={item.id}\n                onPress={() => handlePress(item)}\n                disabled={disabled}\n                accessibilityRole={disabled ? undefined : 'button'}\n                accessibilityLabel={disabled ? `${item.label}, próximamente` : item.label}\n                accessibilityState={disabled ? { disabled: true } : undefined}\n                style={({ pressed }) => [\n                  styles.chip,\n                  {\n                    backgroundColor: isEmergency\n                      ? alpha(colors.danger, glass ? 0.16 : 0.08)\n                      : glass ? (isDark ? 'rgba(35,35,41,0.45)' : 'rgba(255,255,255,0.55)') : colors.card,\n                    borderColor: isEmergency ? alpha(colors.danger, 0.3) : colors.border,\n                    opacity: disabled ? 0.5 : pressed ? 0.7 : 1,\n                  },\n                ]}\n              >\n                <Icon size={16} color={tint} strokeWidth={2.2} />\n                <Text style={[styles.chipLabel, { color: isEmergency ? colors.danger : disabled ? colors.textSecondary : colors.textPrimary }]}>\n                  {item.label}\n                </Text>\n              </Pressable>\n            );\n          })}\n        </ScrollView>\n      </View>\n\n      {/* Selector de perfil (RoleGate) */}\n      <Modal visible={choosing !== null} transparent animationType=\"fade\" onRequestClose={() => setChoosing(null)}>\n        <View style={styles.backdrop}>\n          <View style={[styles.sheet, { backgroundColor: colors.card }]}>\n            <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>\n              {choosing?.service.label} — ¿en qué perfil entras?\n            </Text>\n            <Text style={[styles.sheetHint, { color: colors.textSecondary }]}>Lo recordaremos en este dispositivo. Mantén pulsado el icono para cambiarlo.</Text>\n            {choosing?.options.map((opt) => (\n              <Pressable\n                key={opt.id}\n                onPress={() => pickRole(opt)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={opt.label}\n                style={({ pressed }) => [styles.roleRow, { backgroundColor: colors.surface, borderColor: colors.border, opacity: pressed ? 0.85 : 1 }]}\n              >\n                <Text style={styles.roleEmoji}>{opt.emoji}</Text>\n                <View style={{ flex: 1 }}>\n                  <Text style={[styles.roleLabel, { color: colors.textPrimary }]}>{opt.label}</Text>\n                  <Text style={[styles.roleHint, { color: colors.textSecondary }]}>{opt.hint}</Text>\n                </View>\n              </Pressable>\n            ))}\n            <Pressable onPress={() => setChoosing(null)} accessibilityRole=\"button\" accessibilityLabel=\"Cancelar\" style={{ paddingVertical: espaciado.e12 }}>\n              <Text style={{ textAlign: 'center', color: colors.textSecondary, fontWeight: '700' }}>Cancelar</Text>\n            </Pressable>\n          </View>\n        </View>\n      </Modal>\n    </>\n  );\n}\n\nconst styles = StyleSheet.create({\n  row: { marginTop: espaciado.e14, flexDirection: 'row', rowGap: 16 },\n  rowGapTop: { marginTop: espaciado.e6 },\n  cell: { alignItems: 'center', gap: espaciado.e5 },\n  circle: {\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderWidth: StyleSheet.hairlineWidth,\n  },\n  label: { fontSize: tipografia.micro, fontWeight: '800', textAlign: 'center', lineHeight: 13, paddingHorizontal: espaciado.e2 },\n  comingSoon: { fontSize: 7.5, fontWeight: '800', color: '#86909C', letterSpacing: 0.2, textTransform: 'uppercase' },\n  moreBlock: {\n    marginTop: espaciado.e16,\n    borderRadius: radios.lg,\n    borderWidth: StyleSheet.hairlineWidth,\n    paddingVertical: espaciado.e10,\n    paddingLeft: espaciado.e12,\n  },\n  moreTitle: { fontSize: tipografia.micro, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: espaciado.e8 },\n  chip: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e6,\n    borderWidth: StyleSheet.hairlineWidth,\n    borderRadius: radios.full,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e8,\n  },\n  chipLabel: { fontSize: tipografia.caption, fontWeight: '700' },\n  backdrop: { flex: 1, backgroundColor: 'rgba(10,15,31,0.55)', justifyContent: 'flex-end' },\n  sheet: { borderTopLeftRadius: 22, borderTopRightRadius: 22, padding: espaciado.e20, paddingBottom: espaciado.e28 },\n  sheetTitle: { fontSize: 17, fontWeight: '900', textAlign: 'center', marginBottom: espaciado.e4 },\n  sheetHint: { fontSize: tipografia.caption, textAlign: 'center', marginBottom: espaciado.e14, lineHeight: 17 },\n  roleRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderWidth: 1, borderRadius: 14, padding: espaciado.e14, marginBottom: espaciado.e10 },\n  roleEmoji: { fontSize: tipografia.display },\n  roleLabel: { fontSize: 14.5, fontWeight: '800' },\n  roleHint: { fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 15 },\n});\n","/**\n * Roles de entrada por servicio (RoleGate).\n * Al entrar desde el Home en un servicio con perfiles, el usuario elige el suyo\n * y se recuerda en el dispositivo. Excepciones: taxi (directo) e intercity\n * (solo pasajero; el conductor entra por \"Ser Conductor\").\n *\n * MERCADO SALIÓ DE AQUÍ (zona del comerciante, 20-sep-2026). Antes «Mercado» preguntaba\n * «¿Comprar o Vender?» y la venta era un **desvío dentro del módulo del comprador**: el comerciante\n * entraba por la misma puerta que quien compra y su zona no existía como tal. Ahora el Mercado abre\n * directo `/ecomerse` (un toque menos para lo que hace casi todo el mundo) y **vender tiene su\n * propia puerta en el Inicio**: la celda «Mi tienda» → `/tienda`, que es un modo aparte con barra\n * propia. Es la misma separación que hacen Lilishop y Mall4j: la zona del vendedor se separa **en\n * la arquitectura**, no con permisos dentro de una pantalla compartida.\n */\n\nexport interface RoleOption {\n  id: string;\n  label: string;\n  hint: string;\n  emoji: string;\n  route: string;\n}\n\nexport const ROLE_SERVICES: Record<string, RoleOption[]> = {\n  work: [\n    { id: 'seeker', label: 'Buscar empleo', hint: 'Veo ofertas, me postulo y contacto reclutadores', emoji: '💼', route: '/work' },\n    { id: 'recruiter', label: 'Publicar empleo (reclutador)', hint: 'Gestiono vacantes y candidatos', emoji: '🏢', route: '/work-publish' },\n  ],\n  alquiler: [\n    { id: 'search', label: 'Buscar alquiler', hint: 'Exploro viviendas y locales disponibles', emoji: '🏠', route: '/alquiler' },\n    { id: 'landlord', label: 'Publicar alquiler (arrendador)', hint: 'Publico y gestiono mis anuncios', emoji: '🗝️', route: '/alquiler-publicar' },\n  ],\n  food: [\n    { id: 'customer', label: 'Pedir comida', hint: 'Veo restaurantes y hago pedidos', emoji: '🍔', route: '/food' },\n    { id: 'owner', label: 'Mi restaurante', hint: 'Gestiono carta y pedidos de mi local', emoji: '👨‍🍳', route: '/food-owner' },\n    { id: 'rider', label: 'Soy repartidor', hint: 'Acepto entregas y marco su estado', emoji: '🛵', route: '/food-rider' },\n  ],\n};\n\nexport const roleOptionsFor = (serviceId: string): RoleOption[] => ROLE_SERVICES[serviceId] ?? [];\nexport const isRoleService = (serviceId: string) => !!ROLE_SERVICES[serviceId];\n","/**\n * Preferencia de perfil por servicio (RoleGate): se recuerda en el dispositivo\n * con AsyncStorage para que la próxima entrada vaya directa.\n */\n\nimport AsyncStorage from '@react-native-async-storage/async-storage';\n\nconst keyOf = (serviceId: string) => `eg-role:${serviceId}`;\n\nexport async function getSavedRole(serviceId: string): Promise<string | null> {\n  try {\n    return await AsyncStorage.getItem(keyOf(serviceId));\n  } catch {\n    return null;\n  }\n}\n\nexport async function saveRole(serviceId: string, roleId: string): Promise<void> {\n  try {\n    await AsyncStorage.setItem(keyOf(serviceId), roleId);\n  } catch { /* sin persistencia: el flujo sigue */ }\n}\n","/**\n * PromoCarousel — anuncios del Home (monetizables) servidos por el backend\n * (GET /api/ads/). Tarjeta deslizable con tintes por anuncio; al tocar registra\n * un clic y navega al servicio (ruta interna del anuncio). Se registra una\n * impresión por carga de la lista. Sin anuncios activos → no ocupa espacio.\n */\n\nimport React, { useEffect, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Dimensions, FlatList, Pressable, StyleSheet, Text, View,\n  type NativeScrollEvent, type NativeSyntheticEvent,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { ChevronRight } from 'lucide-react-native';\nimport { adsApi, type HomeAd } from '../api/ads';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\nimport { brand, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\nconst { width: SCREEN_W } = Dimensions.get('window');\nconst H_PADDING = 20;\nconst CARD_W = SCREEN_W - H_PADDING * 2 - 14;\nconst GAP = 12;\n\nexport default function PromoCarousel() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const [ads, setAds] = useState<HomeAd[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [active, setActive] = useState(0);\n  const listRef = useRef<FlatList<HomeAd>>(null);\n  const countedRef = useRef(false);\n\n  useEffect(() => {\n    let alive = true;\n    adsApi\n      .list()\n      .then((list) => {\n        if (!alive) return;\n        // Solo tarjetas de servicio en el carrusel; los banners grandes de la\n        // portada (kind banner/image) se muestran arriba, no aquí.\n        const arr = Array.isArray(list)\n          ? list.filter((a) => a.kind !== 'banner' && a.kind !== 'image')\n          : [];\n        setAds(arr);\n        if (arr.length > 0 && !countedRef.current) {\n          countedRef.current = true;\n          // Impresión aproximada: una por carga de la Home.\n          arr.forEach((a) => adsApi.impression(a.id).catch(() => {}));\n        }\n      })\n      .catch(() => {})\n      .finally(() => alive && setLoading(false));\n    return () => { alive = false; };\n  }, []);\n\n  const open = (ad: HomeAd) => {\n    adsApi.click(ad.id).catch(() => {});\n    if (ad.targetRoute) router.push(ad.targetRoute as never);\n  };\n\n  const onScroll = (e: NativeSyntheticEvent<NativeScrollEvent>) => {\n    const idx = Math.round(e.nativeEvent.contentOffset.x / (CARD_W + GAP));\n    if (idx !== active) setActive(idx);\n  };\n\n  if (!loading && ads.length === 0) return null;\n\n  return (\n    <View style={styles.wrap}>\n      {loading ? (\n        <View style={{ height: 84, alignItems: 'center', justifyContent: 'center' }}>\n          <ActivityIndicator color={colors.primary} size=\"small\" />\n        </View>\n      ) : (\n        <>\n          <FlatList\n            ref={listRef}\n            data={ads}\n            keyExtractor={(a) => a.id}\n            horizontal\n            showsHorizontalScrollIndicator={false}\n            snapToInterval={CARD_W + GAP}\n            decelerationRate=\"fast\"\n            disableIntervalMomentum\n            onMomentumScrollEnd={onScroll}\n            contentContainerStyle={{ paddingRight: H_PADDING }}\n            ItemSeparatorComponent={() => <View style={{ width: GAP }} />}\n            renderItem={({ item }) => {\n              const color = /^#[0-9A-Fa-f]{6}$/.test(item.color ?? '') ? item.color : colors.primary;\n              return (\n                <Pressable\n                  onPress={() => open(item)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`Oferta: ${item.title}`}\n                  style={({ pressed }) => [\n                    styles.card,\n                    {\n                      width: CARD_W,\n                      backgroundColor: alpha(color, 0.12),\n                      borderColor: alpha(color, 0.35),\n                      transform: [{ scale: pressed ? 0.98 : 1 }],\n                    },\n                  ]}\n                >\n                  <Text style={styles.emoji}>{item.emoji ?? '✨'}</Text>\n                  <View style={styles.cardBody}>\n                    <Text style={[styles.cardTitle, { color: colors.textPrimary }]} numberOfLines={1}>\n                      {item.title}\n                    </Text>\n                    {item.subtitle ? (\n                      <Text style={[styles.cardSubtitle, { color: colors.textSecondary }]} numberOfLines={1}>\n                        {item.subtitle}\n                      </Text>\n                    ) : null}\n                    <View style={[styles.ctaChip, { backgroundColor: color }]}>\n                      <Text style={styles.ctaText}>Abrir</Text>\n                      <ChevronRight size={13} color={brand.white} strokeWidth={2.6} />\n                    </View>\n                  </View>\n                </Pressable>\n              );\n            }}\n          />\n          <View style={styles.dots}>\n            {ads.map((a, i) => (\n              <View\n                key={a.id}\n                style={[\n                  styles.dot,\n                  i === active\n                    ? { backgroundColor: colors.primary, width: 18 }\n                    : { backgroundColor: alpha(colors.primary, 0.3) },\n                ]}\n              />\n            ))}\n          </View>\n        </>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  wrap: { marginTop: espaciado.e20 },\n  card: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    borderRadius: 18,\n    borderWidth: 1,\n    padding: espaciado.e14,\n    minHeight: 92,\n  },\n  emoji: { fontSize: 34, marginRight: espaciado.e12 },\n  cardBody: { flex: 1 },\n  cardTitle: { fontSize: 14.5, fontWeight: '800' },\n  cardSubtitle: { fontSize: tipografia.caption, marginTop: espaciado.e2 },\n  ctaChip: {\n    marginTop: espaciado.e8,\n    alignSelf: 'flex-start',\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e2,\n    paddingHorizontal: espaciado.e10,\n    paddingVertical: espaciado.e5,\n    borderRadius: radios.full,\n  },\n  ctaText: { color: brand.white, fontSize: tipografia.micro, fontWeight: '800' },\n  dots: { flexDirection: 'row', justifyContent: 'center', gap: espaciado.e5, marginTop: espaciado.e12 },\n  dot: { height: 6, width: 6, borderRadius: 3 },\n});\n","/**\n * FareQuoteCard — tarifa en vivo desde la API de movilidad.\n * Muestra la cotización TAXI (banda de negociación) para la distancia dada.\n * Tinte naranja secundario (servicios). Falla en silencio si la API no\n * responde (la Home sigue funcionando offline con los datos estáticos).\n */\n\nimport React, { useEffect, useState } from 'react';\nimport { espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\nimport { ActivityIndicator, StyleSheet, Text, View } from 'react-native';\nimport { CarTaxiFront, BadgeInfo } from 'lucide-react-native';\nimport { mobilityApi, fmtXaf, type FareQuote } from '../api/mobility';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\n\nexport default function FareQuoteCard({ distanceKm = 3.5, city = 'Malabo' }: { distanceKm?: number; city?: string }) {\n  const { colors } = useTheme();\n  const [quote, setQuote] = useState<FareQuote | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    let alive = true;\n    mobilityApi\n      .fareQuote({ serviceType: 'TAXI', zoneType: 'inside', vehicleType: 'car', distanceKm })\n      .then((q) => { if (alive) setQuote(q); })\n      .catch(() => { /* fallback silencioso: la tarjeta no se muestra */ })\n      .finally(() => { if (alive) setLoading(false); });\n    return () => { alive = false; };\n  }, [distanceKm]);\n\n  if (loading) {\n    return (\n      <View style={[styles.card, { backgroundColor: alpha(colors.secondary, 0.08), borderColor: alpha(colors.secondary, 0.25) }]}>\n        <ActivityIndicator color={colors.secondary} size=\"small\" />\n        <Text style={[styles.loadingText, { color: colors.textSecondary }]}>Tarifa en vivo…</Text>\n      </View>\n    );\n  }\n  if (!quote) return null;\n\n  return (\n    <View style={[styles.card, { backgroundColor: alpha(colors.secondary, 0.08), borderColor: alpha(colors.secondary, 0.25) }]}>\n      <View style={[styles.iconWrap, { backgroundColor: alpha(colors.secondary, 0.15) }]}>\n        <CarTaxiFront size={18} color={colors.secondary} />\n      </View>\n      <View style={styles.body}>\n        <Text style={[styles.title, { color: colors.textPrimary }]}>\n          Taxi en {city} · ~{distanceKm} km\n        </Text>\n        <Text style={[styles.subtitle, { color: colors.textSecondary }]}>\n          base {fmtXaf(quote.breakdown.baseFare)} + {fmtXaf(quote.breakdown.perKmRate)}/km · orientativo\n        </Text>\n      </View>\n      <View style={styles.priceBlock}>\n        <Text style={[styles.price, { color: colors.secondary }]}>{fmtXaf(quote.quote)} XAF</Text>\n        <View style={styles.bandRow}>\n          <BadgeInfo size={11} color={colors.textSecondary} />\n          <Text style={[styles.band, { color: colors.textSecondary }]}>\n            negociable {fmtXaf(quote.band.min)}–{fmtXaf(quote.band.max)}\n          </Text>\n        </View>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  card: {\n    marginTop: espaciado.e16,\n    flexDirection: 'row',\n    alignItems: 'center',\n    borderWidth: 1,\n    borderRadius: radios.lg,\n    padding: espaciado.e12,\n    gap: espaciado.e10,\n  },\n  iconWrap: { width: 38, height: 38, borderRadius: 13, alignItems: 'center', justifyContent: 'center' },\n  body: { flex: 1 },\n  title: { fontSize: tipografia.body, fontWeight: '800' },\n  subtitle: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n  priceBlock: { alignItems: 'flex-end' },\n  price: { fontSize: 15, fontWeight: '800' },\n  bandRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginTop: espaciado.e2 },\n  band: { fontSize: 9.5, fontWeight: '600' },\n  loadingText: { fontSize: tipografia.caption, fontWeight: '600', marginLeft: espaciado.e8 },\n});\n","/**\n * Cliente API de movilidad — EG Route Plan.\n * Consume el módulo mobility del backend unificado (schema mobility).\n * Endpoints públicos (auth=false): zonas, servicios, tarifas. El mapa y el\n * grid los consumen en modo invitado (sin token) → fricción cero en lectura.\n * Usa httpClient (sesión inyectada + refresco 401 silencioso para rutas privadas).\n */\n\nimport { http } from './httpClient';\n\nexport interface Zone {\n  id: string;\n  name: string;\n  zoneType: 'inside' | 'outside';\n  centerLat: number;\n  centerLng: number;\n  radiusKm: number;\n}\n\nexport interface FareQuote {\n  serviceType: string;\n  zoneType: string;\n  vehicleType: string | null;\n  currency: 'XAF';\n  quote: number;\n  band: { min: number; max: number };\n  breakdown: {\n    baseFare: number;\n    perKmRate: number;\n    minimumFare: number;\n    distanceKm: number;\n    formula: string;\n  };\n}\n\nexport interface ServiceCatalogEntry {\n  id: string;\n  serviceType: string | null;\n  label: string;\n  icon: string;\n  eta: string;\n}\n\nexport const mobilityApi = {\n  zones: () => http.get<{ zones: Zone[] }>('/mobility/zones', false).then((r) => r.zones),\n\n  services: () =>\n    http.get<{ services: ServiceCatalogEntry[] }>('/mobility/services', false).then((r) => r.services),\n\n  fareQuote: (params: {\n    serviceType: 'TAXI' | 'RESERVA_COCHE' | 'PAQUETE' | 'MUDANZA' | 'ALQUILER';\n    zoneType: 'inside' | 'outside';\n    vehicleType?: 'motorcycle' | 'car' | 'van' | 'truck';\n    distanceKm?: number;\n  }): Promise<FareQuote> => {\n    const qs = new URLSearchParams({\n      serviceType: params.serviceType,\n      zoneType: params.zoneType,\n      ...(params.vehicleType ? { vehicleType: params.vehicleType } : {}),\n      ...(params.distanceKm !== undefined ? { distanceKm: String(params.distanceKm) } : {}),\n    });\n    return http.get<FareQuote>(`/mobility/fares/quote?${qs.toString()}`, false);\n  },\n};\n\n/** Formateo XAF sin decimales con separador de miles. */\nexport const fmtXaf = (n: number) => n.toLocaleString('es-GQ');\n","/**\n * DockFooter — barra de navegación inferior FIJA (dock) de la pantalla de\n * inicio: Inicio, Life Book, Llamar Taxi, Monedero y Perfil.\n * (2026-09-09: se quitó la pestaña Emergencia del dock; la emergencia ahora es\n * un botón flotante sobre el MAPA con cruz médica — decisión del dueño.)\n * (2026-09-10: Life Book entra en el dock como pestaña central del producto —\n * la \"plaza digital\" NO es una app aparte: vive en la app principal.)\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Home, CarTaxiFront, MessageCircle, User, Users, type LucideIcon } from 'lucide-react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useUnreadChat } from '../hooks/useUnreadChat';\nimport { brand, elevation, espaciado } from '@egrouteplan/ui-kit';\n\nexport type FooterTab = 'inicio' | 'lifebook' | 'taxi' | 'mensajes' | 'monedero' | 'perfil' | 'emergencia';\n\n/** Altura fija del dock sin safe-area (la usa la Home como bottomInset). */\nexport const DOCK_BODY_H = 62;\n\n// Orden del dock (decisión del dueño 2026-09-10): Life Book PRIMERO (es donde\n// entra la app al abrirse), Inicio EXACTO en el centro, Mensajes en la cuarta\n// plaza y Monedero fuera (vive en \"Más servicios\" de la Home).\nconst TABS: Array<{ id: FooterTab; label: string; icon: LucideIcon }> = [\n  { id: 'lifebook', label: 'Life Book', icon: Users },\n  { id: 'taxi', label: 'Llamar Taxi', icon: CarTaxiFront },\n  { id: 'inicio', label: 'Inicio', icon: Home },\n  { id: 'mensajes', label: 'Mensajes', icon: MessageCircle },\n  { id: 'perfil', label: 'Perfil', icon: User },\n];\n\nexport default function DockFooter({\n  active,\n  onNavigate,\n  onEmergency,\n  showUnreadBadge = false,\n}: {\n  active?: FooterTab;\n  onNavigate: (tab: FooterTab) => void;\n  /** Conservado por compatibilidad; la emergencia ya no vive en el dock. */\n  onEmergency?: () => void;\n  /**\n   * B8 (2026-09-12): mostrar el contador de mensajes sin leer sobre la pestaña\n   * «Mensajes» del dock.\n   *\n   * **Por defecto `false` a propósito.** Este componente lo pintan 7 pantallas\n   * (`index`, `lifebook`, `lifebook-explore`, `lifebook-messages`,\n   * `lifebook-orders`, `lifebook-store`, `profile`); activarlo por defecto\n   * montaría el hook —y con él un sondeo de red cada 15 s— en las siete a la\n   * vez. Lo enciende quien lo necesita, y el hook ya deduplica: aunque varias\n   * pantallas estén montadas, solo hay UN temporizador vivo (ver\n   * `hooks/useUnreadChat.ts`).\n   *\n   * No se activa en `lifebook-messages.tsx`: estando ya dentro de los mensajes,\n   * un badge sobre la pestaña activa no aporta nada.\n   */\n  showUnreadBadge?: boolean;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  // Se llama SIEMPRE (las reglas de los hooks no permiten llamarlo dentro de un\n  // `if`), pero el hook solo arranca el sondeo si hay suscriptores — y al no\n  // querer el badge, el valor simplemente no se usa.\n  const { unread } = useUnreadChat();\n  const badge = showUnreadBadge ? unread : 0;\n\n  return (\n    <View\n      style={[\n        styles.dock,\n        {\n          backgroundColor: colors.card,\n          borderTopColor: colors.border,\n          paddingBottom: insets.bottom,\n          height: DOCK_BODY_H + insets.bottom,\n        },\n      ]}\n    >\n      {TABS.map((tab) => {\n        const isActive = active === tab.id;\n        const tint = isActive ? colors.primary : colors.textSecondary;\n        const Icon = tab.icon;\n        const esMensajes = tab.id === 'mensajes';\n        const n = esMensajes ? badge : 0;\n        return (\n          <Pressable\n            key={tab.id}\n            onPress={() => onNavigate(tab.id)}\n            accessibilityRole=\"button\"\n            accessibilityState={{ selected: isActive }}\n            accessibilityLabel={n > 0 ? `${tab.label}, ${n} sin leer` : tab.label}\n            style={({ pressed }) => [\n              styles.item,\n              { opacity: pressed ? 0.6 : 1 },\n            ]}\n          >\n            <View>\n              <Icon size={21} color={tint} strokeWidth={isActive ? 2.3 : 2} />\n              {n > 0 && (\n                <View style={styles.badge}>\n                  <Text style={styles.badgeText}>{n > 9 ? '9+' : n}</Text>\n                </View>\n              )}\n            </View>\n            <Text\n              style={[styles.label, { color: tint }, isActive && styles.labelStrong]}\n              numberOfLines={1}\n            >\n              {tab.label}\n            </Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  dock: {\n    position: 'absolute',\n    left: 0,\n    right: 0,\n    bottom: 0,\n    zIndex: 40,\n    flexDirection: 'row',\n    alignItems: 'stretch',\n    borderTopWidth: 1,\n    \n    ...elevation.lg,\n  },\n  item: {\n    flex: 1,\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: espaciado.e2,\n    paddingVertical: espaciado.e6,\n  },\n  label: { fontSize: 10, fontWeight: '700' },\n  labelStrong: { fontWeight: '900' },\n  /* Badge de no leídos (B8). Mismos colores que el badge de la barra superior de\n     `lifebook.tsx`, para que el contador se vea igual arriba y abajo: rojo XHS y\n     borde blanco que lo separa del icono. */\n  badge: {\n    position: 'absolute',\n    top: -4,\n    right: -8,\n    backgroundColor: brand.like,\n    borderRadius: 9,\n    minWidth: 16,\n    height: 16,\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderWidth: 1.5,\n    borderColor: brand.white,\n    paddingHorizontal: espaciado.e3,\n  },\n  badgeText: { color: brand.white, fontSize: 9, fontWeight: '900' },\n});\n","/**\n * useUnreadChat — contador de mensajes sin leer, COMPARTIDO entre pantallas.\n *\n * Por qué existe (2026-09-12, B8): el sondeo de no leídos vivía dentro de\n * `lifebook.tsx` (~línea 270). Al querer mostrar el aviso también en el dock\n * inferior —que se pinta en 7 pantallas distintas— ese diseño obligaba a\n * duplicar el `setInterval` en cada una: siete peticiones cada 15 s al mismo\n * endpoint, y siete fuentes de verdad que podían desincronizarse.\n *\n * La solución es caché a nivel de MÓDULO, no de componente: todas las pantallas\n * leen la misma cifra y solo hay un temporizador vivo mientras haya al menos un\n * suscriptor. El estado se comparte por `useSyncExternalStore` para que un cambio\n * re-renderice a todos los suscriptores a la vez.\n *\n * Regla de la casa respetada: si la petición falla, se conserva el valor anterior\n * en vez de ponerlo a 0 — un fallo de red no debe hacer creer que no hay mensajes.\n */\n\nimport { useCallback, useEffect, useSyncExternalStore } from 'react';\nimport { lifebookChatApi } from '../api/lifebook';\n\n/** Intervalo del sondeo. El que ya usaba `lifebook.tsx`; se mantiene. */\nconst POLL_MS = 15_000;\n\nlet unread = 0;\nlet cargando = false;\nlet timer: ReturnType<typeof setInterval> | null = null;\nlet suscriptores = 0;\nconst oyentes = new Set<() => void>();\n\nfunction emitir() {\n  oyentes.forEach((fn) => fn());\n}\n\n/** Una sola petición en vuelo aunque varias pantallas la pidan a la vez. */\nasync function refrescar(): Promise<void> {\n  if (cargando) return;\n  cargando = true;\n  try {\n    const r = await lifebookChatApi.unread();\n    const n = Number(r?.unread ?? 0);\n    if (Number.isFinite(n) && n >= 0 && n !== unread) {\n      unread = n;\n      emitir();\n    }\n  } catch {\n    // Silencioso a propósito: el dock no debe parpadear por un fallo de red, y\n    // conservar el último valor conocido es mejor que mostrar 0 (falso negativo).\n  } finally {\n    cargando = false;\n  }\n}\n\nfunction suscribir(onChange: () => void): () => void {\n  oyentes.add(onChange);\n  suscriptores += 1;\n  // El primer suscriptor arranca el sondeo; se refresca ya para no esperar 15 s.\n  if (suscriptores === 1) {\n    void refrescar();\n    if (!timer) timer = setInterval(() => { void refrescar(); }, POLL_MS);\n  }\n  return () => {\n    oyentes.delete(onChange);\n    suscriptores -= 1;\n    // Sin pantallas que lo muestren, se para el temporizador: no tiene sentido\n    // sondear en segundo plano si nadie va a pintar el badge.\n    if (suscriptores <= 0 && timer) {\n      clearInterval(timer);\n      timer = null;\n    }\n  };\n}\n\nfunction leer(): number {\n  return unread;\n}\n\n/**\n * Devuelve el número de mensajes sin leer, actualizado cada 15 s mientras la\n * pantalla esté montada.\n *\n * `forzar` re-consulta fuera de ciclo: se usa al SALIR de un chat (leer mensajes\n * debe quitar el badge sin esperar al siguiente tick) y al volver a la app.\n */\nexport function useUnreadChat(): { unread: number; forzar: () => void } {\n  const valor = useSyncExternalStore(suscribir, leer, leer);\n  const forzar = useCallback(() => { void refrescar(); }, []);\n\n  // Al recuperar el foco (volver de un chat, desbloquear el móvil) se refresca.\n  // `visibilitychange` cubre el caso de la app en segundo plano en web; en\n  // nativo el re-mount del hook ya dispara el primer `refrescar()` vía suscribir.\n  useEffect(() => {\n    if (typeof document === 'undefined') return;\n    const onVisible = () => { if (document.visibilityState === 'visible') void refrescar(); };\n    document.addEventListener('visibilitychange', onVisible);\n    return () => document.removeEventListener('visibilitychange', onVisible);\n  }, []);\n\n  return { unread: valor, forzar };\n}\n","/**\n * IntercityPlanesScreen — Planes Ciudad a Ciudad (conductor) v2.\n * Auditoría aplicada:\n *  · Copy \"Planes para conductores\" (catálogo real: Gratis 4/mes · Pro ilimitado 5.000/mes).\n *  · useFocusEffect (recarga al volver del checkout), cargas/errores separados con\n *    Reintentar y RefreshControl.\n *  · Plan Gratis SIN checkout (lo gestiona soporte); Pro → billing-checkout real.\n *  · Tarjeta = View (solo el botón actúa; resaltado = plan actual), sin `selected`.\n *  · Barra de uso mensual (Decisión A) con alerta al 100% y CTA directo a Pro.\n *  · Confirmación al bajar a Gratis con aviso de viajes usados; processingPlan por botón,\n *    busyRef, tokens de color, SafeArea y a11y completa.\n * Ruta: /intercity-planes\n */\n\nimport React, { useCallback, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Check, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, radios, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { billingApi, type BillingPlan } from '../api/billing';\nimport { intercityApi, type IcPlan } from '../api/intercity';\nimport { formatXAF } from '../utils/formatHelpers';\n\nconst FEATURE_LABELS: Array<{ key: string; label: string }> = [\n  { key: 'monthlyTrips', label: 'Viajes por mes' },\n  { key: 'priorityInSearch', label: 'Prioridad en la búsqueda' },\n  { key: 'proBadge', label: 'Badge Pro' },\n  { key: 'multiVehicle', label: 'Multi-vehículo' },\n  { key: 'maxDaysAhead', label: 'Antelación máxima' },\n];\n\nconst PLAN_ORDER = ['intercity_driver_basic', 'intercity_driver_pro'];\n\nexport default function IntercityPlanesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const busyRef = useRef(false);\n\n  const [plans, setPlans] = useState<BillingPlan[]>([]);\n  const [myPlan, setMyPlan] = useState<IcPlan | null>(null);\n  const [plansLoading, setPlansLoading] = useState(true);\n  const [myPlanLoading, setMyPlanLoading] = useState(true);\n  const [plansError, setPlansError] = useState<string | null>(null);\n  const [myPlanError, setMyPlanError] = useState<string | null>(null);\n  const [processingPlan, setProcessingPlan] = useState<string | null>(null);\n\n  const loadPlans = useCallback(async () => {\n    setPlansLoading(true);\n    setPlansError(null);\n    try { setPlans(await billingApi.plans('intercity')); }\n    catch (e) { setPlansError(e instanceof Error ? e.message : 'No se pudieron cargar los planes'); }\n    finally { setPlansLoading(false); }\n  }, []);\n\n  const loadMyPlan = useCallback(async () => {\n    setMyPlanLoading(true);\n    setMyPlanError(null);\n    try { setMyPlan(await intercityApi.myPlan()); }\n    catch (e) { setMyPlanError(e instanceof Error ? e.message : 'No se pudo cargar tu plan'); }\n    finally { setMyPlanLoading(false); }\n  }, []);\n\n  useFocusEffect(\n    useCallback(() => {\n      void loadPlans();\n      void loadMyPlan();\n    }, [loadPlans, loadMyPlan]),\n  );\n\n  const currentCode = myPlan?.planCode ?? 'intercity_driver_basic';\n  const used = myPlan?.monthlyUsed ?? 0;\n  const limit = myPlan?.monthlyTrips ?? 0;\n  const unlimited = myPlan != null && limit === -1;\n  const atLimit = !unlimited && limit > 0 && used >= limit;\n  const ordered = PLAN_ORDER\n    .map((c) => plans.find((p) => p.code === c))\n    .filter((p): p is BillingPlan => Boolean(p));\n\n  const goCheckout = async (plan: BillingPlan) => {\n    if (busyRef.current) return;\n    busyRef.current = true;\n    setProcessingPlan(plan.code);\n    try {\n      router.push({ pathname: '/billing-checkout', params: { planId: plan.id, module: 'intercity', targetType: 'user' } } as never);\n    } finally {\n      busyRef.current = false;\n      setProcessingPlan(null);\n    }\n  };\n\n  const proPlan = plans.find((p) => p.code === 'intercity_driver_pro');\n\n  const handleSelectPlan = (plan: BillingPlan) => {\n    if (plan.code === currentCode) { Alert.alert('Plan actual', 'Ya tienes este plan activo.'); return; }\n    if (plan.code === 'intercity_driver_basic') {\n      Alert.alert(\n        'Cambiar al plan Gratis',\n        unlimited\n          ? 'Perderás los viajes ilimitados de tu plan actual. El cambio a Gratis lo gestiona el administrador: escríbenos desde soporte y lo aplicaremos.'\n          : `Tienes ${used}/${limit} viajes usados este mes. El cambio a Gratis lo gestiona el administrador: escríbenos desde soporte y lo aplicaremos.`,\n        [{ text: 'Entendido' }],\n      );\n      return;\n    }\n    void goCheckout(plan);\n  };\n\n  const renderFeature = (plan: BillingPlan, key: string) => {\n    const features = plan.features as unknown as Record<string, unknown>;\n    const v = features[key];\n    const label = FEATURE_LABELS.find((f) => f.key === key)?.label ?? key;\n    if (key === 'monthlyTrips') {\n      return (\n        <View style={s.featureRow} key={key}>\n          <Text style={s.featureLabel}>{label}</Text>\n          <Text style={s.featureValue}>{Number(v) === -1 ? 'Ilimitados' : String(v)}</Text>\n        </View>\n      );\n    }\n    if (key === 'maxDaysAhead') {\n      return (\n        <View style={s.featureRow} key={key}>\n          <Text style={s.featureLabel}>{label}</Text>\n          <Text style={s.featureValue}>{Number(v) ? `${v} días` : '—'}</Text>\n        </View>\n      );\n    }\n    if (typeof v === 'boolean') {\n      return (\n        <View style={s.featureRow} key={key}>\n          <Text style={s.featureLabel}>{label}</Text>\n          <View accessible={false}>\n            {v ? <Check size={16} color={colors.success} strokeWidth={3} /> : <X size={16} color={colors.textSecondary} strokeWidth={3} />}\n          </View>\n        </View>\n      );\n    }\n    return null;\n  };\n\n  const s = styles(colors);\n  const pct = !unlimited && limit > 0 ? Math.min(100, Math.round((used / limit) * 100)) : 0;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera del kit desde el 24/09/2026 (unificación de las 21 cabeceras). */}\n      <ScreenHeader\n        titulo=\"Planes Ciudad a Ciudad\"\n        alVolver={() => router.back()}\n      />\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 40 }}\n        showsVerticalScrollIndicator={false}\n        refreshControl={<RefreshControl refreshing={plansLoading || myPlanLoading} onRefresh={() => { void loadPlans(); void loadMyPlan(); }} tintColor={colors.primary} colors={[colors.primary]} />}\n      >\n        <Text style={s.title}>Planes para conductores</Text>\n        <Text style={s.subtitle}>\n          Publica gratis 4 viajes al mes. Con Pro publicas viajes ilimitados, apareces antes en la búsqueda y luces el badge. El pasajero te paga en efectivo; aquí pagas por publicar.\n        </Text>\n\n        {plansError && (\n          <View style={{ marginBottom: espaciado.e10, backgroundColor: alpha(colors.danger, 0.06), padding: espaciado.e10, borderRadius: 10 }}>\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption }}>{plansError}</Text>\n            <Pressable onPress={() => void loadPlans()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar cargar planes\" hitSlop={6}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>Reintentar planes</Text>\n            </Pressable>\n          </View>\n        )}\n        {myPlanError && (\n          <View style={{ marginBottom: espaciado.e10, backgroundColor: alpha(colors.danger, 0.06), padding: espaciado.e10, borderRadius: 10 }}>\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption }}>{myPlanError}</Text>\n            <Pressable onPress={() => void loadMyPlan()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar cargar mi plan\" hitSlop={6}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>Reintentar mi plan</Text>\n            </Pressable>\n          </View>\n        )}\n\n        {myPlan && (\n          <View style={{ backgroundColor: alpha(colors.primary, 0.07), borderRadius: 14, padding: espaciado.e12, marginBottom: espaciado.e14 }}>\n            <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>\n              Tu plan: {myPlan.planName} · {unlimited ? 'viajes ilimitados' : `${used}/${limit} viajes este mes`}\n            </Text>\n            {myPlan.expiresAt && (\n              <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>\n                Vence: {new Date(myPlan.expiresAt).toLocaleDateString('es')}\n              </Text>\n            )}\n\n            {/* Barra de uso mensual (Decisión A) */}\n            {!unlimited && limit > 0 && (\n              <View style={{ marginTop: espaciado.e10 }}>\n                <View style={{ height: 6, borderRadius: 3, backgroundColor: alpha(colors.border, 0.6), overflow: 'hidden' }}>\n                  <View style={{ width: `${pct}%`, height: 6, borderRadius: 3, backgroundColor: atLimit ? colors.danger : colors.primary }} />\n                </View>\n                {atLimit && proPlan && (\n                  <Pressable\n                    onPress={() => void goCheckout(proPlan)}\n                    accessibilityRole=\"button\" accessibilityLabel=\"Mejorar a Pro\"\n                    style={({ pressed }) => [{ marginTop: espaciado.e10, backgroundColor: colors.primary, borderRadius: 10, paddingVertical: espaciado.e10, alignItems: 'center', opacity: pressed ? 0.85 : 1 }]}\n                  >\n                    <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Límite alcanzado · Pasar a viajes ilimitados</Text>\n                  </Pressable>\n                )}\n              </View>\n            )}\n          </View>\n        )}\n\n        {plansLoading && ordered.length === 0 && (\n          <View style={{ alignItems: 'center', marginVertical: espaciado.e30 }}>\n            <ActivityIndicator color={colors.primary} />\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e8 }}>Cargando planes…</Text>\n          </View>\n        )}\n        {!plansLoading && ordered.length === 0 && !plansError && (\n          <Text style={{ textAlign: 'center', color: colors.textSecondary, marginTop: espaciado.e30 }}>No hay planes disponibles en este momento.</Text>\n        )}\n\n        {ordered.map((plan) => {\n          const isCurrent = plan.code === currentCode;\n          const isPro = plan.code === 'intercity_driver_pro';\n          const isProcessing = processingPlan === plan.code;\n          const isPaid = plan.priceXaf > 0;\n          return (\n            <View key={plan.code} style={[s.planCard, { borderColor: isCurrent ? colors.primary : colors.border }, isCurrent && { backgroundColor: alpha(colors.primary, 0.05) }]}>\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: espaciado.e14 }}>\n                <View style={{ flex: 1, paddingRight: espaciado.e8 }}>\n                  <Text style={[s.planName, { color: isPro ? colors.secondary : colors.primary }]}>{plan.name}</Text>\n                  {isCurrent && (\n                    <View style={[s.currentBadge, { backgroundColor: isPro ? colors.secondary : colors.primary }]}>\n                      <Text style={s.currentBadgeText}>Plan actual</Text>\n                    </View>\n                  )}\n                </View>\n                <View style={{ alignItems: 'flex-end' }}>\n                  <Text style={s.price}>{plan.priceXaf === 0 ? 'Gratis' : formatXAF(plan.priceXaf)}</Text>\n                  {plan.interval === 'monthly' && <Text style={s.period}>/mes</Text>}\n                </View>\n              </View>\n\n              <View style={{ marginBottom: espaciado.e14 }}>\n                {FEATURE_LABELS.map((f) => renderFeature(plan, f.key))}\n              </View>\n\n              <Pressable\n                onPress={() => handleSelectPlan(plan)}\n                disabled={processingPlan !== null || isCurrent}\n                accessibilityRole=\"button\"\n                accessibilityLabel={isCurrent ? `Plan actual: ${plan.name}` : plan.priceXaf === 0 ? 'Cambiar al plan Gratis' : `Elegir el plan ${plan.name}`}\n                accessibilityState={{ disabled: processingPlan !== null || isCurrent, selected: isCurrent }}\n                style={({ pressed }) => [\n                  s.selectButton,\n                  { backgroundColor: isCurrent ? colors.border : isPro ? colors.secondary : colors.primary, opacity: processingPlan !== null ? 0.6 : pressed ? 0.85 : 1 },\n                ]}\n              >\n                {isProcessing ? (\n                  <ActivityIndicator color={brand.white} />\n                ) : (\n                  <Text style={[s.selectButtonText, isCurrent && { color: colors.textSecondary }]}>\n                    {isCurrent ? 'Plan activo' : !isPaid ? 'Cambiar a Gratis' : 'Elegir este plan'}\n                  </Text>\n                )}\n              </Pressable>\n            </View>\n          );\n        })}\n\n        <View style={[s.paymentNote, { borderColor: colors.border }]}>\n          <Text style={s.paymentNoteTitle}>Cómo funciona</Text>\n          <Text style={s.paymentNoteText}>\n            1. Elige el plan y confirma la compra.{'\\n'}\n            2. Paga por transferencia o Mobile Money y sube el comprobante.{'\\n'}\n            3. El administrador aprueba y tu plan se activa (2–24 h).{'\\n'}\n            {'\\n'}\n            ¿Bajar a Gratis? Escríbenos desde soporte y lo gestionamos por ti.\n          </Text>\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  title: { fontSize: 22, fontWeight: '800', color: c.textPrimary, marginBottom: espaciado.e6 },\n  subtitle: { fontSize: tipografia.body, color: c.textSecondary, lineHeight: 19, marginBottom: espaciado.e18 },\n  planCard: { backgroundColor: c.card, borderRadius: radios.lg, padding: espaciado.e18, marginBottom: espaciado.e16, borderWidth: 1 },\n  planName: { fontSize: 18, fontWeight: '700' },\n  currentBadge: { paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: 6, marginTop: espaciado.e6, alignSelf: 'flex-start' },\n  currentBadgeText: { color: brand.white, fontSize: tipografia.micro, fontWeight: '600' },\n  price: { fontSize: tipografia.title, fontWeight: '800', color: c.textPrimary },\n  period: { fontSize: tipografia.body, color: c.textSecondary },\n  featureRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: espaciado.e6, borderBottomWidth: 1, borderBottomColor: c.border },\n  featureLabel: { fontSize: tipografia.body, color: c.textSecondary, flex: 1 },\n  featureValue: { fontSize: tipografia.body, fontWeight: '600', color: c.textPrimary },\n  selectButton: { borderRadius: 10, paddingVertical: espaciado.e14, alignItems: 'center' },\n  selectButtonText: { color: brand.white, fontSize: 15, fontWeight: '700' },\n  paymentNote: { backgroundColor: c.card, borderRadius: radios.md, padding: espaciado.e16, marginTop: espaciado.e8, borderWidth: 1 },\n  paymentNoteTitle: { fontSize: 15, fontWeight: '700', color: c.textPrimary, marginBottom: espaciado.e8 },\n  paymentNoteText: { fontSize: tipografia.body, color: c.textSecondary, lineHeight: 22 },\n});\n","/**\n * IntercityPublishScreen — Ciudad a Ciudad (conductor) v2.\n * Auditoría aplicada:\n *  · Gate de perfil de conductor (driverApi.status → aprobado) con mensaje y CTA.\n *  · Límite del plan PROACTIVO (monthlyUsed >= monthlyTrips → botón deshabilitado).\n *  · resetForm tras publicar; duplicate limpia fotos/editId; openEdit resetea editF.\n *  · saveEdit valida hora HH:MM y precios; cobro usa b.totalPrice (tarifa real).\n *  · Fotos por GALERÍA con compresión (quality 0.35) + límite ~700 KB/foto (máx 4);\n *    el backend sigue guardando base64 (multipart real queda anotado como futuro).\n *  · Errores limpiados en transiciones; busyRef anti doble-tap; polling pausado en form.\n *  · SafeArea, Chip con a11y, keyboardShouldPersistTaps, aviso de días fuera del\n *    horizonte de 14 días.\n * Ruta: /intercity-publish\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { Alert, Image, KeyboardAvoidingView, Platform, SectionList, ScrollView, StyleSheet, Text, View, Pressable } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport * as ImagePicker from 'expo-image-picker';\nimport { ArrowLeft, Truck, Plus, RefreshCw, ImageIcon, Siren, Crown, X } from 'lucide-react-native';\nimport { alpha, brand, EmptyState, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport EmergencyModal from '../components/EmergencyModal';\nimport { useSession } from '../state/session';\nimport { driverApi } from '../api/driver';\nimport { intercityApi, type IcLocation, type IcTrip, type IcPlan, IC_VEHICLE_TYPES, IC_VEHICLE_LABELS } from '../api/intercity';\n\ntype Mode = 'list' | 'form';\n\nconst DAY_ORDER = ['L', 'M', 'X', 'J', 'V', 'S', 'D'] as const;\nconst DAY_INDEX: Record<string, number> = { L: 1, M: 2, X: 3, J: 4, V: 5, S: 6, D: 0 };\nconst DAY_A11Y: Record<string, string> = { L: 'Lunes', M: 'Martes', X: 'Miércoles', J: 'Jueves', V: 'Viernes', S: 'Sábado', D: 'Domingo' };\nconst HORIZON_DAYS = 14;\nconst MAX_PHOTOS = 4;\nconst MAX_PHOTO_B64_KB = 700;\nconst TRIP_STATUS_LABELS: Record<string, string> = {\n  scheduled: 'Programado', in_transit: 'En ruta', completed: 'Completado', cancelled: 'Cancelado',\n};\n\nconst ymd = (d: Date): string =>\n  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;\n\nconst nextDayDates = (labels: string[]): string[] => {\n  const today = new Date(); today.setHours(0, 0, 0, 0);\n  const out: string[] = [];\n  for (const l of labels) {\n    const d = new Date(today);\n    let offset = (DAY_INDEX[l] - d.getDay() + 7) % 7;\n    if (offset === 0) offset = 7;\n    d.setDate(d.getDate() + offset);\n    if (d.getTime() - today.getTime() <= HORIZON_DAYS * 86400000) out.push(ymd(d));\n  }\n  return out.sort();\n};\nconst droppedDayLabels = (labels: string[], found: number): string[] => {\n  const today = new Date(); today.setHours(0, 0, 0, 0);\n  const dropped: string[] = [];\n  for (const l of labels) {\n    const d = new Date(today);\n    let offset = (DAY_INDEX[l] - d.getDay() + 7) % 7;\n    if (offset === 0) offset = 7;\n    d.setDate(d.getDate() + offset);\n    if (d.getTime() - today.getTime() > HORIZON_DAYS * 86400000) dropped.push(DAY_A11Y[l]);\n  }\n  return dropped;\n};\nconst b64SizeKB = (s: string | null | undefined) => {\n  const b = String(s ?? '').split(',')[1] || s || '';\n  return Math.round((b.length * 3) / 4 / 1024);\n};\n\nconst emptyForm = {\n  oProv: '', oDist: '', dProv: '', dDist: '', date: '', time: '', seats: 4, price: '',\n  rentalPrice: '', vehicleType: 'car', plate: '', model: '', carPhotos: [] as string[], days: [] as string[],\n};\n\nexport default function IntercityPublishScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const busyRef = useRef(false);\n\n  const [mode, setMode] = useState<Mode>('list');\n  const [locs, setLocs] = useState<IcLocation[]>([]);\n  const [trips, setTrips] = useState<IcTrip[]>([]);\n  const [plan, setPlan] = useState<IcPlan | null>(null);\n  const [driverOk, setDriverOk] = useState<boolean | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [emergencyOpen, setEmergencyOpen] = useState(false);\n\n  // Formulario\n  const [f, setF] = useState({ ...emptyForm });\n  const [editId, setEditId] = useState<string | null>(null);\n  const [editF, setEditF] = useState({ price: '', seats: '', rentalPrice: '', vehiclePlate: '', vehicleModel: '', time: '' });\n\n  const load = useCallback(async () => {\n    if (!isAuthenticated) { setDriverOk(false); return; }\n    if (busyRef.current) return;\n    setBusy(true); setError(null);\n    try {\n      const [l, mt] = await Promise.all([intercityApi.locations(), intercityApi.myTrips()]);\n      setLocs(l);\n      setTrips(mt);\n      intercityApi.myPlan().then(setPlan).catch(() => {});\n      const st = await driverApi.status();\n      const d = st.driver;\n      const ok = !!d && (st.status === 'approved' || d.status === 'approved' || d.status === 'active');\n      setDriverOk(ok);\n      if (ok) {\n        setF((prev) => ({\n          ...prev,\n          plate: prev.plate || d.vehicle_plate || '',\n          model: prev.model || d.vehicle_model || '',\n          vehicleType: d.vehicle_type && (IC_VEHICLE_TYPES as readonly string[]).includes(d.vehicle_type) ? d.vehicle_type : prev.vehicleType,\n        }));\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Error de red');\n    } finally {\n      setBusy(false);\n    }\n  }, [isAuthenticated]);\n\n  useEffect(() => { void load(); }, [load]);\n\n  // Polling pausado en form (evita pisar la edición) y con mounted guard.\n  const mountedRef = useRef(true);\n  useEffect(() => () => { mountedRef.current = false; }, []);\n  useEffect(() => {\n    if (!isAuthenticated) return;\n    const iv = setInterval(() => {\n      if (mode !== 'list' || !mountedRef.current) return;\n      intercityApi.myTrips().then((t) => mountedRef.current && setTrips(t)).catch(() => {});\n    }, 15000);\n    return () => clearInterval(iv);\n  }, [isAuthenticated, mode]);\n\n  const pendingFares = trips.reduce((n, t) => n + (t.bookings?.filter((b) => b.fareStatus === 'proposed').length ?? 0), 0);\n  const atPlanLimit = plan != null && plan.monthlyTrips !== -1 && plan.monthlyUsed >= plan.monthlyTrips;\n\n  const provinces = useMemo(() => [...new Set(locs.map((l) => l.province))], [locs]);\n  const oDists = useMemo(() => locs.filter((l) => l.province === f.oProv), [locs, f.oProv]);\n  const dDists = useMemo(() => locs.filter((l) => l.province === f.dProv), [locs, f.dProv]);\n\n  const groups = useMemo(() => {\n    const m = new Map<string, IcTrip[]>();\n    for (const t of trips) {\n      const k = `${t.route?.originDistrict ?? '?'} → ${t.route?.destinationDistrict ?? '?'}`;\n      if (!m.has(k)) m.set(k, []);\n      m.get(k)!.push(t);\n    }\n    return [...m.entries()];\n  }, [trips]);\n\n  const switchMode = (m: Mode) => { setError(null); setMode(m); };\n\n  const resetForm = () => setF({ ...emptyForm, plate: f.plate, model: f.model, vehicleType: f.vehicleType });\n\n  const pickPhoto = async () => {\n    if (f.carPhotos.length >= MAX_PHOTOS) { Alert.alert('Límite de fotos', `Máximo ${MAX_PHOTOS} fotos por viaje.`); return; }\n    const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: 'images', quality: 0.35, base64: true });\n    if (res.canceled || !res.assets?.[0]) return;\n    const b64 = res.assets[0].base64 ?? null;\n    if (!b64) { Alert.alert('Imagen', 'No se pudo leer la imagen. Prueba con otra.'); return; }\n    const sizeKB = b64SizeKB(b64);\n    if (sizeKB > MAX_PHOTO_B64_KB) {\n      Alert.alert('Foto demasiado pesada', `Pesa ~${sizeKB} KB (máx. ${MAX_PHOTO_B64_KB} KB). Prueba con otra o edítala antes.`);\n      return;\n    }\n    setF((prev) => ({ ...prev, carPhotos: [...prev.carPhotos, `data:image/jpeg;base64,${b64}`] }));\n  };\n\n  const publish = async () => {\n    if (!f.oDist || !f.dDist) { setError('Elige origen y destino'); return; }\n    if (f.oProv === f.dProv && f.oDist === f.dDist) { setError('Origen y destino deben ser distintos'); return; }\n    const priceNum = Number(f.price);\n    if (!(priceNum > 0)) { setError('Precio por asiento inválido'); return; }\n    if (!/^([01]\\d|2[0-3]):[0-5]\\d$/.test(f.time)) { setError('Hora en formato HH:MM (ej. 08:00)'); return; }\n    if (atPlanLimit) { setError('Alcanzaste el límite de tu plan mensual. Mejora tu plan para publicar más viajes.'); return; }\n    let dep: { departureDays?: string[]; departureTimeOfDay?: string; departureTime?: string } = {};\n    if (f.days.length > 0) {\n      const dates = nextDayDates(f.days);\n      if (dates.length === 0) { setError('Las fechas quedan fuera del horizonte (14 días). Elige otros días.'); return; }\n      dep = { departureDays: dates, departureTimeOfDay: f.time };\n    } else {\n      if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(f.date)) { setError('Fecha en formato AAAA-MM-DD (ej. 2026-09-01)'); return; }\n      const dt = new Date(`${f.date}T${f.time}:00`);\n      if (Number.isNaN(dt.getTime())) { setError('Fecha u hora inválidas'); return; }\n      if (dt.getTime() <= Date.now()) { setError('La salida debe ser futura'); return; }\n      dep = { departureTime: dt.toISOString() };\n    }\n    setBusy(true); setError(null);\n    busyRef.current = true;\n    try {\n      await intercityApi.publish({\n        origin: { province: f.oProv, district: f.oDist, zone: oDists.find((d) => d.district === f.oDist)?.zone ?? '' },\n        destination: { province: f.dProv, district: f.dDist, zone: dDists.find((d) => d.district === f.dDist)?.zone ?? '' },\n        ...dep,\n        seats: f.seats, price: priceNum,\n        vehiclePlate: f.plate.trim() || undefined, vehicleModel: f.model.trim() || undefined,\n        vehicleType: f.vehicleType,\n        rentalPrice: f.rentalPrice.trim() ? Number(f.rentalPrice.trim()) : undefined,\n        photos: f.carPhotos,\n      });\n      resetForm();\n      switchMode('list');\n      await load();\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo publicar');\n    } finally {\n      busyRef.current = false;\n      setBusy(false);\n    }\n  };\n\n  const openEdit = (t: IcTrip) => {\n    setError(null);\n    setEditId(t.id);\n    setEditF({\n      price: String(Number(t.price)),\n      seats: String(t.totalSeats),\n      rentalPrice: t.rentalPrice != null ? String(Number(t.rentalPrice)) : '',\n      vehiclePlate: t.vehiclePlate ?? '',\n      vehicleModel: t.vehicleModel ?? '',\n      time: new Date(t.departureTime).toLocaleTimeString('es', { hour: '2-digit', minute: '2-digit' }),\n    });\n  };\n\n  const saveEdit = async (t: IcTrip) => {\n    if (busyRef.current) return;\n    if (!/^([01]\\d|2[0-3]):[0-5]\\d$/.test(editF.time.trim())) { setError('Hora en formato HH:MM'); return; }\n    if (Number(editF.price) <= 0 || Number(editF.seats) < 1) { setError('Precio y asientos deben ser positivos'); return; }\n    const hasAccepted = (t.bookings ?? []).some((b) => b.fareStatus === 'accepted' || b.paymentStatus === 'paid');\n    if (hasAccepted && (Number(editF.price) !== Number(t.price) || Number(editF.seats) !== t.totalSeats)) {\n      setError('No puedes cambiar precio o asientos con reservas aceptadas o pagadas');\n      return;\n    }\n    const body: Record<string, unknown> = {};\n    if (Number(editF.price) !== Number(t.price)) body.price = Number(editF.price);\n    if (Number(editF.seats) !== t.totalSeats) body.seats = Number(editF.seats);\n    if (editF.rentalPrice.trim()) body.rentalPrice = Number(editF.rentalPrice);\n    else if (t.rentalPrice != null) body.rentalPrice = null;\n    if (editF.vehiclePlate.trim() !== (t.vehiclePlate ?? '')) body.vehiclePlate = editF.vehiclePlate.trim() || null;\n    if (editF.vehicleModel.trim() !== (t.vehicleModel ?? '')) body.vehicleModel = editF.vehicleModel.trim() || null;\n    const cur = new Date(t.departureTime).toLocaleTimeString('es', { hour: '2-digit', minute: '2-digit' });\n    if (editF.time.trim() !== cur) {\n      const d = new Date(t.departureTime);\n      const [hh, mm] = editF.time.trim().split(':');\n      d.setHours(Number(hh), Number(mm), 0, 0);\n      body.departureTime = d.toISOString();\n    }\n    await act(() => intercityApi.updateTrip(t.id, body));\n    setEditId(null);\n    setEditF({ price: '', seats: '', rentalPrice: '', vehiclePlate: '', vehicleModel: '', time: '' });\n  };\n\n  const duplicate = (t: IcTrip) => {\n    setError(null);\n    setEditId(null);\n    setF({\n      ...emptyForm,\n      oProv: t.route?.originProvince ?? '', oDist: t.route?.originDistrict ?? '',\n      dProv: t.route?.destinationProvince ?? '', dDist: t.route?.destinationDistrict ?? '',\n      price: String(Number(t.price)), seats: t.totalSeats,\n      rentalPrice: t.rentalPrice != null ? String(Number(t.rentalPrice)) : '',\n      plate: t.vehiclePlate ?? '', model: t.vehicleModel ?? '',\n      vehicleType: t.vehicleType ?? 'car',\n      time: new Date(t.departureTime).toLocaleTimeString('es', { hour: '2-digit', minute: '2-digit' }),\n    });\n    switchMode('form');\n  };\n\n  const act = async (fn: () => Promise<unknown>) => {\n    if (busyRef.current) return;\n    busyRef.current = true;\n    setBusy(true); setError(null);\n    try { await fn(); await load(); } catch (e) { setError(e instanceof Error ? e.message : 'Error'); } finally {\n      busyRef.current = false;\n      setBusy(false);\n    }\n  };\n\n  const confirmAction = (title: string, msg: string, destructive: boolean, fn: () => Promise<unknown>) =>\n    Alert.alert(title, msg, [\n      { text: 'Mantener', style: 'cancel' },\n      { text: destructive ? title : 'Confirmar', style: destructive ? 'destructive' : 'default', onPress: () => void act(fn) },\n    ]);\n\n  const s = styles(colors);\n  const priceColor = colors.secondary ?? brand.secondary;\n\n  const set = <K extends keyof typeof emptyForm>(k: K, v: (typeof emptyForm)[K]) => {\n    setF((prev) => ({ ...prev, [k]: v }));\n    setError(null);\n  };\n\n  /*\n    Banner del plan + error: comunes a los DOS modos. Antes vivían una sola vez dentro del\n    ScrollView; ahora el modo «lista» tiene su propio contenedor virtualizado, así que se\n    escriben una vez aquí y se usan en los dos.\n  */\n  const cabeceraModos = (\n    <>\n      {plan && (\n        <Pressable\n          onPress={() => router.push('/intercity-planes' as never)}\n          accessibilityRole=\"button\" accessibilityLabel=\"Ver planes\"\n          style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', backgroundColor: alpha(colors.primary, 0.08), borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e14, opacity: pressed ? 0.85 : 1 }]}\n        >\n          <Crown size={18} color={colors.primary} />\n          <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n            <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.textPrimary }}>\n              {`${plan.planName} · ${plan.monthlyTrips === -1 ? 'viajes ilimitados' : `${plan.monthlyUsed}/${plan.monthlyTrips} viajes este mes`}`}\n            </Text>\n            <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: 1 }}>\n              {atPlanLimit ? 'Alcanzaste tu límite mensual: mejora tu plan para seguir publicando.' : 'Toca para ver tus planes.'}\n            </Text>\n          </View>\n          <Text style={{ fontSize: tipografia.caption, fontWeight: '700', color: colors.primary }}>Mejorar plan ›</Text>\n        </Pressable>\n      )}\n\n      {error && <Text style={s.err}>{error}</Text>}\n    </>\n  );\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      <View style={s.topBar}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.title}>Publicar viaje</Text>\n        <View style={{ flexDirection: 'row', gap: espaciado.e14 }}>\n          <Pressable onPress={() => setEmergencyOpen(true)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Emergencia\">\n            <Siren size={20} color={colors.danger} />\n          </Pressable>\n          {driverOk === true && (\n            <Pressable onPress={() => switchMode(mode === 'list' ? 'form' : 'list')} hitSlop={12} accessibilityRole=\"button\"\n              accessibilityLabel={mode === 'list' ? 'Publicar viaje' : 'Ver mis viajes'}>\n              {mode === 'list' ? <Plus size={22} color={colors.primary} /> : <RefreshCw size={22} color={colors.primary} />}\n            </Pressable>\n          )}\n        </View>\n      </View>\n\n      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined} keyboardVerticalOffset={8}>\n      {!isAuthenticated || driverOk === false ? (\n        /*\n          Los dos avisos de entrada van PRIMERO, como antes de virtualizar: sin cuenta o sin alta\n          de conductor no hay ni lista ni formulario que enseñar.\n        */\n        <ScrollView contentContainerStyle={[s.content, { paddingBottom: insets.bottom + 24 }]} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n          {!isAuthenticated ? (\n            <View style={s.block}>\n              <Text style={s.big}>Necesitas una cuenta de conductor</Text>\n              <Text style={s.body}>Inicia sesión con tu cuenta de conductor verificado para publicar viajes de ciudad a ciudad.</Text>\n              <PrimaryButton title=\"Iniciar sesión\" onPress={() => router.push('/auth' as never)} />\n            </View>\n          ) : (\n            <View style={s.block}>\n              <Text style={s.big}>No tienes perfil de conductor aprobado</Text>\n              <Text style={s.body}>Completa tu alta como conductor (documentos + aprobación) antes de publicar viajes interurbanos.</Text>\n              <PrimaryButton title=\"Alta de conductor\" onPress={() => router.push('/driver-onboarding' as never)} />\n            </View>\n          )}\n        </ScrollView>\n      ) : mode === 'list' ? (\n        /*\n          LISTA VIRTUALIZADA (auditoría de diseño, D-04/D-21): la séptima y más delicada de las\n          siete. El viaje es la FILA y la reserva es CONTENIDO de la fila (una reserva no se puede\n          tocar sin tocar su viaje: aceptar tarifa, cobrar, cancelar); la ruta es la SECCIÓN.\n          El modo «formulario» sigue en su ScrollView: anidar listas virtualizadas la desactiva.\n        */\n        <SectionList\n          sections={groups.map(([titulo, data]) => ({ titulo, data })).filter((s) => s.data.length > 0)}\n          keyExtractor={(t) => t.id}\n          contentContainerStyle={[s.content, { gap: espaciado.e12, paddingBottom: insets.bottom + 24 }]}\n          showsVerticalScrollIndicator={false}\n          keyboardShouldPersistTaps=\"handled\"\n          stickySectionHeadersEnabled={false}\n          initialNumToRender={8}\n          windowSize={7}\n          removeClippedSubviews\n          renderSectionHeader={({ section }) => (\n            <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>\n              {section.titulo} · {section.data.length} viaje{section.data.length === 1 ? '' : 's'}\n            </Text>\n          )}\n          renderItem={({ item: t }) => (\n            <View key={t.id} style={[s.card, { borderColor: colors.border }]}>\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>\n                    {new Date(t.departureTime).toLocaleDateString('es', { weekday: 'short', day: 'numeric', month: 'short' })} · {new Date(t.departureTime).toLocaleTimeString('es', { hour: '2-digit', minute: '2-digit' })}\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.caption }}>\n                    {t.availableSeats}/{t.totalSeats} asientos · {TRIP_STATUS_LABELS[t.status] ?? t.status}\n                  </Text>\n                </View>\n                <Text style={{ color: priceColor, fontWeight: '900', fontSize: tipografia.subtitle }}>{Number(t.price).toLocaleString('es')} XAF</Text>\n              </View>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                {IC_VEHICLE_LABELS[t.vehicleType ?? 'car']} {t.vehicleModel ?? ''}{t.vehiclePlate ? ` · ${t.vehiclePlate}` : ''}{t.rentalPrice != null ? ` · alquiler ${Number(t.rentalPrice).toLocaleString('es')} XAF` : ''}\n              </Text>\n              {(t.bookings ?? []).map((b) => (\n                <View key={b.id} style={[s.bookingRow, { backgroundColor: alpha(colors.border, 0.25) }]}>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>\n                      {b.passenger?.firstName} {b.passenger?.lastName} · {b.seatCount} asiento(s)\n                    </Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                      {b.payOn === 'destination' ? '🎫 Por encargo · el viajero paga al final del viaje' : b.fareStatus === 'proposed' ? '💬 tarifa propuesta' : b.paymentStatus === 'paid' ? '✅ pagado' : '💵 pendiente de pago'}\n                    </Text>\n                    {b.payOn === 'destination' && b.buyerName && (\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>\n                        Comprado por {b.buyerName} · viajero: {b.passenger?.firstName} {b.passenger?.lastName}\n                      </Text>\n                    )}\n                  </View>\n                  {b.fareStatus === 'proposed' && (\n                    <View style={{ flexDirection: 'row', gap: espaciado.e6 }}>\n                      <Pressable onPress={() => void act(() => intercityApi.decideFare(b.id, 'accept'))} accessibilityRole=\"button\" accessibilityLabel=\"Aceptar tarifa\"\n                        style={[s.miniBtn, { backgroundColor: colors.success }]}>\n                        <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.caption }}>Aceptar</Text>\n                      </Pressable>\n                      <Pressable onPress={() => void act(() => intercityApi.decideFare(b.id, 'decline'))} accessibilityRole=\"button\" accessibilityLabel=\"Rechazar tarifa\"\n                        style={[s.miniBtn, { backgroundColor: colors.danger }]}>\n                        <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.caption }}>Rechazar</Text>\n                      </Pressable>\n                    </View>\n                  )}\n                  {b.fareStatus === 'accepted' && b.paymentStatus !== 'paid' && (\n                    <Pressable\n                      onPress={() => Alert.alert('Confirmar cobro',\n                        `${b.passenger?.firstName ?? 'Viajero'} · ${b.seatCount} asiento(s) · ${Number(b.totalPrice ?? b.seatCount * Number(t.price)).toLocaleString('es')} XAF. ¿Confirmas que pagó?`, [\n                          { text: 'Aún no', style: 'cancel' },\n                          { text: 'Sí, pagó', style: 'default', onPress: () => void act(() => intercityApi.markPaid(b.id)) },\n                        ])}\n                      accessibilityRole=\"button\" accessibilityLabel=\"Confirmar cobro\"\n                      style={[s.miniBtn, { backgroundColor: colors.primary }]}>\n                      <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.caption }}>{b.payOn === 'destination' ? 'Cobrar (final)' : 'Cobrar'}</Text>\n                    </Pressable>\n                  )}\n                </View>\n              ))}\n              {editId === t.id && (\n                <View style={{ gap: espaciado.e8, marginTop: espaciado.e4 }}>\n                  <FormField label=\"Precio por asiento (XAF)\" value={editF.price} onChangeText={(v) => setEditF((p) => ({ ...p, price: v }))} keyboardType=\"numeric\" />\n                  <FormField label=\"Asientos totales\" value={editF.seats} onChangeText={(v) => setEditF((p) => ({ ...p, seats: v }))} keyboardType=\"numeric\" />\n                  <FormField label=\"Alquiler vehículo (XAF; vacío = quitar)\" value={editF.rentalPrice} onChangeText={(v) => setEditF((p) => ({ ...p, rentalPrice: v }))} keyboardType=\"numeric\" />\n                  <FormField label=\"Hora (HH:MM)\" value={editF.time} onChangeText={(v) => setEditF((p) => ({ ...p, time: v }))} />\n                  <FormField label=\"Matrícula\" value={editF.vehiclePlate} onChangeText={(v) => setEditF((p) => ({ ...p, vehiclePlate: v }))} />\n                  <FormField label=\"Modelo\" value={editF.vehicleModel} onChangeText={(v) => setEditF((p) => ({ ...p, vehicleModel: v }))} />\n                  <PrimaryButton title=\"Guardar cambios\" onPress={() => void saveEdit(t)} loading={busy} />\n                  <GhostButton title=\"Cancelar\" onPress={() => { setEditId(null); setError(null); }} />\n                </View>\n              )}\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e6 }}>\n                {t.status === 'scheduled' && (\n                  <>\n                    <GhostButton title=\"En ruta\" onPress={() => confirmAction('Iniciar ruta', 'Los pasajeros recibirán el aviso de salida. ¿Continuar?', false, () => intercityApi.tripStatus(t.id, 'in_transit'))} />\n                    <GhostButton title=\"Editar\" onPress={() => openEdit(t)} />\n                    <GhostButton title=\"Duplicar\" onPress={() => duplicate(t)} />\n                    <GhostButton title=\"Cancelar\" onPress={() => confirmAction('Cancelar viaje', `¿Seguro que cancelas el viaje a ${t.route?.destinationDistrict ?? 'destino'}? Las reservas se anularán.`, true, () => intercityApi.cancelTrip(t.id))} />\n                  </>\n                )}\n                {t.status === 'in_transit' && (\n                  <GhostButton title=\"Completar\" onPress={() => confirmAction('Completar viaje', 'El viaje quedará cerrado. ¿Continuar?', false, () => intercityApi.tripStatus(t.id, 'completed'))} />\n                )}\n              </View>\n            </View>\n          )}\n          ListHeaderComponent={\n            /* El `View` con gap, no un fragmento: el gap del contenedor separa celdas, y la\n               cabecera es UNA celda. Con un fragmento, todo lo de dentro quedaba pegado. */\n            <View style={s.block}>\n              {cabeceraModos}\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n                <Text style={s.big}>Mis viajes</Text>\n                <Pressable onPress={() => void load()} hitSlop={10} accessibilityRole=\"button\" accessibilityLabel=\"Actualizar mis viajes\">\n                  <RefreshCw size={18} color={colors.primary} />\n                </Pressable>\n              </View>\n              {pendingFares > 0 && (\n                <View style={{ backgroundColor: alpha(colors.secondary, 0.12), borderRadius: radios.md, padding: espaciado.e10 }}>\n                  <Text style={{ color: colors.secondary, fontWeight: '900', fontSize: tipografia.body }}>🔔 {pendingFares} tarifa(s) propuesta(s) pendiente(s) de tu respuesta</Text>\n                </View>\n              )}\n            </View>\n          }\n          ListEmptyComponent={\n            /*\n              Vacío con salida (D-17). El aviso viejo mandaba «pulsa + para crear uno», pero el botón\n              + solo se dibuja con perfil de conductor aprobado: el vacío no puede mandar a pulsar\n              algo que puede no estar ahí. Mejor decir qué lo llena.\n            */\n            <EmptyState\n              compacto\n              icono={<Text style={{ fontSize: tipografia.subtitle }}>🚐</Text>}\n              titulo=\"Aún no has publicado viajes\"\n              texto=\"Cuando publiques uno aparecerá aquí, con sus asientos libres, su estado y las reservas que reciba.\"\n            />\n          }\n        />\n      ) : (\n        <ScrollView contentContainerStyle={[s.content, { paddingBottom: insets.bottom + 24 }]} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n              {cabeceraModos}\n\n              {mode === 'form' && (\n                <View style={s.block}>\n                  <Truck size={36} color={colors.primary} />\n                  <Text style={s.big}>Publicar viaje</Text>\n                  <Text style={s.body}>Provincia → distrito → zona jurídica. Precio por asiento lo pones tú.</Text>\n\n                  <Text style={s.label}>ORIGEN</Text>\n                  <View style={s.chipRow}>{provinces.map((p) => <Chip key={p} label={p} active={p === f.oProv} onPress={() => { setF((pr) => ({ ...pr, oProv: p, oDist: '' })); setError(null); }} />)}</View>\n                  {f.oProv !== '' && <View style={s.chipRow}>{oDists.map((d) => <Chip key={d.district} label={d.district} active={d.district === f.oDist} onPress={() => { setF((pr) => ({ ...pr, oDist: d.district })); setError(null); }} />)}</View>}\n\n                  <Text style={s.label}>DESTINO</Text>\n                  <View style={s.chipRow}>{provinces.map((p) => <Chip key={p} label={p} active={p === f.dProv} onPress={() => { setF((pr) => ({ ...pr, dProv: p, dDist: '' })); setError(null); }} />)}</View>\n                  {f.dProv !== '' && <View style={s.chipRow}>{dDists.map((d) => <Chip key={d.district} label={d.district} active={d.district === f.dDist} onPress={() => { setF((pr) => ({ ...pr, dDist: d.district })); setError(null); }} />)}</View>}\n\n                  <Text style={s.label}>Días de la semana (opcional — publica cada día elegido)</Text>\n                  <View style={s.chipRow}>\n                    {DAY_ORDER.map((l) => <Chip key={l} label={l} active={f.days.includes(l)} a11y={DAY_A11Y[l]} onPress={() => set('days', f.days.includes(l) ? f.days.filter((x) => x !== l) : [...f.days, l])} />)}\n                  </View>\n                  <FormField label=\"Hora de salida (HH:MM)\" placeholder=\"08:00\" value={f.time} onChangeText={(v) => set('time', v)} />\n                  {f.days.length === 0 && <FormField label=\"Fecha de salida (AAAA-MM-DD)\" placeholder=\"2026-09-01\" value={f.date} onChangeText={(v) => set('date', v)} />}\n                  {f.days.length > 0 && (\n                    <>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                        Se publicará en: {nextDayDates(f.days).join(' · ') || '—'} a las {f.time || '—'}.\n                      </Text>\n                      {droppedDayLabels(f.days, nextDayDates(f.days).length).length > 0 && (\n                        <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>\n                          ⚠️ Fuera del horizonte (14 días): {droppedDayLabels(f.days, 0).join(', ')}\n                        </Text>\n                      )}\n                    </>\n                  )}\n\n                  <Text style={s.label}>Asientos</Text>\n                  <View style={s.chipRow}>{[2, 3, 4, 6, 8, 10, 12, 18].map((n) => <Chip key={String(n)} label={String(n)} active={n === f.seats} onPress={() => set('seats', n)} />)}</View>\n\n                  <FormField label=\"Precio por asiento (XAF)\" placeholder=\"5000\" value={f.price} onChangeText={(v) => set('price', v)} keyboardType=\"numeric\" />\n                  <Text style={s.label}>Tipo de vehículo</Text>\n                  <View style={s.chipRow}>{IC_VEHICLE_TYPES.map((t) => <Chip key={t} label={IC_VEHICLE_LABELS[t]} active={f.vehicleType === t} onPress={() => set('vehicleType', t)} />)}</View>\n                  <FormField label=\"Alquiler del vehículo completo (XAF, opcional)\" placeholder=\"25000\" value={f.rentalPrice} onChangeText={(v) => set('rentalPrice', v)} keyboardType=\"numeric\" />\n                  <FormField label=\"Matrícula del vehículo\" placeholder=\"GQ-000-00\" value={f.plate} onChangeText={(v) => set('plate', v)} />\n                  <FormField label=\"Modelo del vehículo\" placeholder=\"Toyota Hiace\" value={f.model} onChangeText={(v) => set('model', v)} />\n\n                  <Text style={s.label}>Fotos del vehículo (opcional, máx. {MAX_PHOTOS})</Text>\n                  <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10 }}>\n                    {f.carPhotos.map((p, i) => (\n                      <View key={i} style={{ position: 'relative' }}>\n                        <Image source={{ uri: p }} style={{ width: 64, height: 64, borderRadius: 10, backgroundColor: colors.border }} />\n                        <Pressable onPress={() => setF((pr) => ({ ...pr, carPhotos: pr.carPhotos.filter((_, j) => j !== i) }))}\n                          accessibilityRole=\"button\" accessibilityLabel=\"Quitar foto\"\n                          style={{ position: 'absolute', top: -6, right: -6, backgroundColor: colors.danger, borderRadius: 10, width: 18, height: 18, alignItems: 'center', justifyContent: 'center' }}>\n                          <X size={11} color={brand.white} />\n                        </Pressable>\n                      </View>\n                    ))}\n                  </View>\n                  {f.carPhotos.length < MAX_PHOTOS && (\n                    <Pressable onPress={() => void pickPhoto()} accessibilityRole=\"button\" accessibilityLabel=\"Añadir foto del coche\"\n                      style={[s.photoAdd, { borderColor: colors.border }]}>\n                      <ImageIcon size={18} color={colors.primary} />\n                      <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body }}>Añadir foto del coche ({f.carPhotos.length}/{MAX_PHOTOS})</Text>\n                    </Pressable>\n                  )}\n                  <Text style={{ fontSize: 10.5, color: colors.textSecondary }}>Se comprimen al elegirlas. Máx. ~{MAX_PHOTO_B64_KB} KB por foto.</Text>\n\n                  {error && <Text style={s.err}>{error}</Text>}\n                  {Number(f.price) > 0 && (\n                    <View style={{ backgroundColor: alpha(colors.primary, 0.08), borderRadius: radios.md, padding: espaciado.e12 }}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>\n                        {f.oDist && f.dDist ? `${f.oDist} → ${f.dDist}` : 'Tu ruta'} · {f.seats} asientos × {Number(f.price).toLocaleString('es')} XAF\n                      </Text>\n                      <Text style={{ color: priceColor, fontWeight: '900', fontSize: 17, marginTop: espaciado.e2 }}>\n                        = {(f.seats * Number(f.price)).toLocaleString('es')} XAF por viaje\n                        {f.days.length > 0 ? ` · × ${f.days.length} día${f.days.length === 1 ? '' : 's'}/semana` : ''}\n                      </Text>\n                    </View>\n                  )}\n                  {atPlanLimit ? (\n                    <PrimaryButton title=\"Límite de plan alcanzado\" disabled onPress={() => {}} />\n                  ) : (\n                    <PrimaryButton title={busy ? 'Publicando…' : 'Publicar viaje'} onPress={() => void publish()} loading={busy} />\n                  )}\n                  <GhostButton title=\"Ver mis viajes\" onPress={() => switchMode('list')} />\n                </View>\n              )}\n        </ScrollView>\n      )}\n      </KeyboardAvoidingView>\n\n      <EmergencyModal visible={emergencyOpen} onClose={() => setEmergencyOpen(false)} />\n    </View>\n  );\n}\n\nfunction Chip({ label, active, onPress, a11y }: { label: string; active: boolean; onPress: () => void; a11y?: string }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable onPress={onPress} accessibilityRole=\"button\" accessibilityState={{ selected: active }} accessibilityLabel={a11y ?? label}\n      style={({ pressed }) => [styles(colors).chip, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? alpha(colors.primary, 0.08) : colors.card, opacity: pressed ? 0.85 : 1 }]}>\n      <Text style={{ color: active ? colors.primary : colors.textPrimary, fontWeight: '700', fontSize: tipografia.caption }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e6 },\n    title: { fontSize: 18, fontWeight: '800', color: c.textPrimary },\n    content: { padding: espaciado.e20, gap: espaciado.e16 },\n    block: { gap: espaciado.e12 },\n    big: { fontSize: tipografia.title, fontWeight: '900', color: c.textPrimary, textAlign: 'center' },\n    body: { fontSize: tipografia.body, lineHeight: 20, color: c.textSecondary, textAlign: 'center', fontWeight: '600' },\n    label: { fontSize: tipografia.caption, fontWeight: '800', color: c.textSecondary, marginTop: espaciado.e4 },\n    chipRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n    chip: { borderRadius: radios.md, borderWidth: 1.5, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8 },\n    card: { borderWidth: 1.5, borderRadius: 14, padding: espaciado.e12, gap: espaciado.e6 },\n    bookingRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderRadius: 10, padding: espaciado.e8 },\n    miniBtn: { borderRadius: radios.sm, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9 },\n    photoAdd: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, borderWidth: 1.5, borderStyle: 'dashed', borderRadius: radios.md, paddingVertical: espaciado.e12 },\n    err: { color: c.danger, fontSize: tipografia.body, fontWeight: '700' },\n  });\n","/**\n * IntercityScreen — Ciudad a Ciudad (pasajero) v2.\n * Auditoría aplicada:\n *  · Total de alquiler (charter) correcto: rentalPrice una sola vez.\n *  · Idempotency-Key FRESCA por intento de reserva (adiós clave fija por sesión).\n *  · Error único limpio en cada transición de paso/acción.\n *  · Menores exigen nombre + teléfono de tutor (guardianName → backend).\n *  · Teléfonos normalizados y validados en formato GQ (+240/9 dígitos).\n *  · Compra por encargo EXPLÍCITA (\"Compro para mí / para otra persona\") con\n *    teléfono del comprador y del viajero separados.\n *  · Chip extraído con a11y, SafeArea, keyboardShouldPersistTaps, LazyImage,\n *    busyRef y navegación desde el ticket.\n * Ruta: /intercity\n */\n\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\nimport { FlatList, Linking, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowLeft, Route as RouteIcon, Ticket, CheckCircle2, ChevronRight, Crown, BadgeCheck,\n} from 'lucide-react-native';\nimport { alpha, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useSession } from '../state/session';\nimport { intercityApi, type IcBooking, type IcLocation, type IcTrip, IC_VEHICLE_TYPES, IC_VEHICLE_LABELS } from '../api/intercity';\nimport { LazyImage } from '../components/rental/LazyImage';\nimport { brand } from '@egrouteplan/ui-kit';\n\ntype Step = 'search' | 'trips' | 'passenger' | 'confirm' | 'ticket';\n\nconst NATIONALITIES = ['Ecuatoguineano', 'Extranjero'];\nconst DOC_TYPES = ['DIP', 'Pasaporte'];\nconst NEEDS: Array<[string, string]> = [['none', 'Ninguna'], ['pregnant', 'Embarazada'], ['disabled', 'Movilidad reducida'], ['sick', 'Enfermedad']];\n\nconst digits = (s: string) => String(s ?? '').replace(/\\D/g, '');\n/** Normaliza un teléfono GQ: 9 dígitos → +240…; con prefijo 240 → +240…; si no es GQ devuelve null. */\nconst gqPhone = (raw: string): string | null => {\n  const d = digits(raw);\n  if (d.length === 9) return `+240${d}`;\n  if (d.length === 12 && d.startsWith('240')) return `+${d}`;\n  return null;\n};\nconst absUrl = (p: string) => (p.startsWith('http') ? p : `https://hk.egrouteplan.com${p}`);\n\nexport default function IntercityScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { phone: sessionPhone } = useSession();\n  const busyRef = useRef(false);\n\n  const [step, setStep] = useState<Step>('search');\n  const [locs, setLocs] = useState<IcLocation[]>([]);\n  const [trips, setTrips] = useState<IcTrip[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  // Búsqueda\n  const [originProv, setOriginProv] = useState('');\n  const [originDist, setOriginDist] = useState('');\n  const [destProv, setDestProv] = useState('');\n  const [destDist, setDestDist] = useState('');\n  const [vehicleFilter, setVehicleFilter] = useState('');\n\n  // Viaje\n  const [trip, setTrip] = useState<IcTrip | null>(null);\n  const [seats, setSeats] = useState(1);\n\n  // Pasajero\n  const [forOther, setForOther] = useState(false); // compra por encargo (explícito)\n  const [buyerPhone, setBuyerPhone] = useState(sessionPhone ?? '');\n  const [firstName, setFirstName] = useState('');\n  const [lastName, setLastName] = useState('');\n  const [phone, setPhone] = useState(sessionPhone ?? '');\n  const [nationality, setNationality] = useState(NATIONALITIES[0]);\n  const [docType, setDocType] = useState(DOC_TYPES[0]);\n  const [docNumber, setDocNumber] = useState('');\n  const [minorCount, setMinorCount] = useState(0);\n  const [guardianName, setGuardianName] = useState('');\n  const [guardianPhone, setGuardianPhone] = useState('');\n  const [specialNeeds, setSpecialNeeds] = useState('none');\n  const [pickupType, setPickupType] = useState<'home' | 'agency'>('home');\n  const [pickupAddress, setPickupAddress] = useState('');\n  const [passengerFare, setPassengerFare] = useState('');\n  const [rental, setRental] = useState(false);\n  const [payOn, setPayOn] = useState<'boarding' | 'destination'>('boarding');\n\n  const [booking, setBooking] = useState<{ ticketQrCode: string; message: string; fareStatus: string; booking?: IcBooking } | null>(null);\n\n  useEffect(() => {\n    intercityApi.locations().then(setLocs).catch((e) => setError(e instanceof Error ? e.message : 'Error de red'));\n  }, []);\n\n  const provinces = useMemo(() => [...new Set(locs.map((l) => l.province))], [locs]);\n  const originDists = useMemo(() => locs.filter((l) => l.province === originProv), [locs, originProv]);\n  const destDists = useMemo(() => locs.filter((l) => l.province === destProv), [locs, destProv]);\n  const originZone = originDists.find((l) => l.district === originDist)?.zone ?? '';\n  const destZone = destDists.find((l) => l.district === destDist)?.zone ?? '';\n  const travelerPhone = gqPhone(phone);\n  const sessionGQ = sessionPhone ? gqPhone(sessionPhone) : null;\n  const isCommission = forOther || (sessionGQ != null && travelerPhone != null && travelerPhone !== sessionGQ);\n\n  const go = (s: Step) => { setError(null); setStep(s); };\n  const goBack = () => {\n    setError(null);\n    if (step === 'search') router.back();\n    else if (step === 'trips') setStep('search');\n    else if (step === 'passenger') setStep('trips');\n    else if (step === 'confirm') setStep('passenger');\n    else setStep('search'); // ticket → reinicia búsqueda limpia\n  };\n\n  const search = async () => {\n    if (!originProv || !destProv) { setError('Elige la provincia de origen y de destino'); return; }\n    setLoading(true); setError(null);\n    try {\n      const q: Record<string, string> = { originProvince: originProv, destinationProvince: destProv };\n      if (originDist) q.originDistrict = originDist;\n      if (destDist) q.destinationDistrict = destDist;\n      const rs = await intercityApi.routes(q);\n      if (rs.length === 0) { setError('No hay rutas para esa combinación todavía'); return; }\n      const allTrips = (await Promise.all(rs.map((r) => intercityApi.trips(r.id, undefined, vehicleFilter || undefined)))).flat();\n      const unique = [...new Map(allTrips.map((t) => [t.id, t])).values()]\n        .sort((a, b) => new Date(a.departureTime).getTime() - new Date(b.departureTime).getTime());\n      setTrips(unique);\n      setTrip(null);\n      go('trips');\n    } catch (e) { setError(e instanceof Error ? e.message : 'Error de red'); }\n    finally { setLoading(false); }\n  };\n\n  const pickTrip = (t: IcTrip) => {\n    setTrip(t);\n    setSeats(1);\n    setRental(false);\n    setPassengerFare('');\n    go('passenger');\n  };\n\n  const confirm = async () => {\n    if (!trip || busyRef.current) return;\n    if (!firstName.trim() || !lastName.trim()) { setError('Completa nombre y apellidos'); return; }\n    if (!travelerPhone) { setError('Teléfono del viajero no válido: usa +240 o 9 dígitos'); return; }\n    if (forOther && !gqPhone(buyerPhone)) { setError('Tu teléfono (comprador) no es válido: usa +240 o 9 dígitos'); return; }\n    if (!docNumber.trim()) { setError('Indica el número de documento'); return; }\n    if (minorCount > 0) {\n      if (!guardianName.trim()) { setError('Indica el nombre del tutor del menor'); return; }\n      if (!gqPhone(guardianPhone)) { setError('Teléfono del tutor no válido: usa +240 o 9 dígitos'); return; }\n    }\n    if (pickupType === 'home' && !pickupAddress.trim()) { setError('Indica tu dirección de recogida a casa'); return; }\n    if (rental && !trip.rentalPrice) { setError('Este viaje no ofrece alquiler del vehículo'); return; }\n    const fare = rental ? null : (passengerFare.trim() ? Number(passengerFare.trim()) : null);\n    if (fare != null && !(fare > 0)) { setError('Tarifa propuesta inválida'); return; }\n\n    setBusyRef(true);\n    setError(null);\n    // Idempotency-Key FRESCA por intento (no reutilizar una fallida con otro viaje).\n    const idemKey = `ic-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;\n    try {\n      const res = await intercityApi.book({\n        tripId: trip.id,\n        seatCount: rental ? trip.totalSeats : seats,\n        passenger: {\n          firstName: firstName.trim(), lastName: lastName.trim(),\n          phone: travelerPhone,\n          nationalityType: nationality === 'Extranjero' ? 'foreign' : 'national',\n          documentType: docType, documentNumber: docNumber.trim(),\n          isMinor: minorCount > 0, minorCount,\n          guardianId: minorCount > 0 ? gqPhone(guardianPhone) ?? undefined : undefined,\n          guardianName: minorCount > 0 ? guardianName.trim() : undefined,\n          specialNeeds,\n        },\n        pickupType,\n        pickupAddress: pickupType === 'home' ? pickupAddress.trim() : undefined,\n        passengerFare: fare ?? undefined,\n        rental,\n        payOn,\n      }, idemKey);\n      setBooking(res);\n      go('ticket');\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo reservar');\n    } finally {\n      setBusyRef(false);\n    }\n  };\n\n  const setBusyRef = (v: boolean) => { busyRef.current = v; };\n  const totalSeatsUsed = rental ? trip?.totalSeats ?? 1 : seats;\n  const unitPrice = rental ? Number(trip?.rentalPrice ?? 0) : Number(passengerFare.trim() || trip?.price || 0);\n  const total = rental ? unitPrice : unitPrice * totalSeatsUsed;\n\n  const s = styles(colors);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      <View style={s.topBar}>\n        <Pressable onPress={goBack} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.title}>Ciudad a Ciudad</Text>\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e14 }}>\n          <Pressable onPress={() => router.push('/intercity-planes' as never)} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Planes\">\n            <Crown size={20} color={colors.primary} />\n          </Pressable>\n        </View>\n      </View>\n\n      {step !== 'trips' ? (\n      <ScrollView contentContainerStyle={[s.content, { paddingBottom: insets.bottom + 24 }]} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n        {step === 'search' && (\n          <View style={s.block}>\n            <View style={{ alignItems: 'center', gap: espaciado.e4 }}>\n              <RouteIcon size={40} color={colors.primary} />\n              <Text style={s.big}>¿A dónde vas?</Text>\n              <Text style={s.body}>Elige provincia y distrito de salida y de llegada.</Text>\n            </View>\n\n            <Text style={s.label}>ORIGEN</Text>\n            <View style={s.chipRow}>{provinces.map((p) => <Chip key={p} label={p} active={p === originProv} onPress={() => { setOriginProv(p); setOriginDist(''); setError(null); }} />)}</View>\n            {originProv !== '' && <View style={s.chipRow}>{originDists.map((d) => <Chip key={d.district} label={d.district} active={d.district === originDist} onPress={() => { setOriginDist(d.district); setError(null); }} />)}</View>}\n            {originZone && <Text style={s.zone}>Zona jurídica: {originZone}</Text>}\n\n            <Text style={s.label}>DESTINO</Text>\n            <View style={s.chipRow}>{provinces.map((p) => <Chip key={p} label={p} active={p === destProv} onPress={() => { setDestProv(p); setDestDist(''); setError(null); }} />)}</View>\n            {destProv !== '' && <View style={s.chipRow}>{destDists.map((d) => <Chip key={d.district} label={d.district} active={d.district === destDist} onPress={() => { setDestDist(d.district); setError(null); }} />)}</View>}\n            {destZone && <Text style={s.zone}>Zona jurídica: {destZone}</Text>}\n\n            <Text style={s.label}>TIPO DE VEHÍCULO (opcional)</Text>\n            <View style={s.chipRow}>\n              <Chip label=\"Todos\" active={vehicleFilter === ''} onPress={() => setVehicleFilter('')} />\n              {IC_VEHICLE_TYPES.map((t) => <Chip key={t} label={IC_VEHICLE_LABELS[t]} active={vehicleFilter === t} onPress={() => setVehicleFilter(t)} />)}\n            </View>\n\n            {error && <Text style={s.err}>{error}</Text>}\n            <PrimaryButton title={loading ? 'Buscando…' : 'Buscar viajes'} onPress={search} loading={loading} />\n          </View>\n        )}\n        {step === 'passenger' && trip && (\n          <View style={s.block}>\n            <Text style={s.big}>Tus datos</Text>\n            <Text style={s.body}>Vehículo con {trip.availableSeats} asientos libres · {Number(trip.price).toLocaleString('es')} XAF por asiento.</Text>\n\n            <Text style={s.label}>¿PARA QUIÉN ES LA RESERVA?</Text>\n            <View style={s.chipRow}>\n              <Chip label=\"Para mí\" active={!forOther} onPress={() => { setForOther(false); setBuyerPhone(sessionPhone ?? ''); setError(null); }} />\n              <Chip label=\"Para otra persona\" active={forOther} onPress={() => { setForOther(true); setError(null); }} />\n            </View>\n            {forOther && <FormField label=\"Tu teléfono (comprador)\" placeholder=\"+240…\" value={buyerPhone} onChangeText={setBuyerPhone} keyboardType=\"phone-pad\" />}\n\n            <Text style={s.label}>TIPO DE RESERVA</Text>\n            <View style={s.chipRow}>\n              <Chip label={`Asiento · ${Number(trip.price).toLocaleString('es')} XAF`} active={!rental} onPress={() => { setRental(false); setError(null); }} />\n              {trip.rentalPrice != null && <Chip label={`🚐 Vehículo completo · ${Number(trip.rentalPrice).toLocaleString('es')} XAF`} active={rental} onPress={() => { setRental(true); setError(null); }} />}\n            </View>\n            {!rental && (\n              <View style={s.chipRow}>\n                <Text style={s.labelInline}>Asientos: </Text>\n                {[1, 2, 3, 4, 5, 6].filter((n) => n <= trip.availableSeats).map((n) => <Chip key={String(n)} label={String(n)} active={n === seats} onPress={() => setSeats(n)} />)}\n              </View>\n            )}\n\n            <FormField label=\"Nombre\" placeholder=\"Juan\" value={firstName} onChangeText={setFirstName} />\n            <FormField label=\"Apellidos\" placeholder=\"Ondó\" value={lastName} onChangeText={setLastName} />\n            <FormField label={forOther ? 'Teléfono del viajero' : 'Tu teléfono'} placeholder=\"+240…\" value={phone} onChangeText={setPhone} keyboardType=\"phone-pad\" />\n            {forOther && <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, fontWeight: '600' }}>El comprador pagará el billete; el viajero viaja con los datos indicados.</Text>}\n\n            <Text style={s.label}>Nacionalidad</Text>\n            <View style={s.chipRow}>{NATIONALITIES.map((n) => <Chip key={n} label={n} active={n === nationality} onPress={() => setNationality(n)} />)}</View>\n            <Text style={s.label}>Documento</Text>\n            <View style={s.chipRow}>{DOC_TYPES.map((d) => <Chip key={d} label={d} active={d === docType} onPress={() => setDocType(d)} />)}</View>\n            <FormField label=\"Número de documento\" placeholder=\"GE-000000\" value={docNumber} onChangeText={setDocNumber} />\n\n            <Text style={s.label}>Menores de edad incluidos</Text>\n            <View style={s.chipRow}>{[0, 1, 2, 3, 4, 5].map((n) => <Chip key={String(n)} label={String(n)} active={minorCount === n} onPress={() => { setMinorCount(n); setError(null); }} />)}</View>\n            {minorCount > 0 && (\n              <>\n                <FormField label=\"Nombre del tutor *\" placeholder=\"Ej: María Nguema\" value={guardianName} onChangeText={setGuardianName} />\n                <FormField label=\"Teléfono del tutor *\" placeholder=\"+240…\" value={guardianPhone} onChangeText={setGuardianPhone} keyboardType=\"phone-pad\" />\n              </>\n            )}\n\n            <Text style={s.label}>Necesidades especiales</Text>\n            <View style={s.chipRow}>{NEEDS.map(([v, l]) => <Chip key={v} label={l} active={specialNeeds === v} onPress={() => setSpecialNeeds(v)} />)}</View>\n\n            <Text style={s.label}>RECOGIDA — puerta a puerta recomendada</Text>\n            <View style={s.chipRow}>\n              <Chip label=\"🏠 Recogida a casa\" active={pickupType === 'home'} onPress={() => setPickupType('home')} />\n              <Chip label=\"🚏 En agencia\" active={pickupType === 'agency'} onPress={() => { setPickupType('agency'); setError(null); }} />\n            </View>\n            {pickupType === 'home' ? (\n              <FormField label=\"Dirección de recogida\" placeholder=\"Barrio, calle, nº…\" value={pickupAddress} onChangeText={setPickupAddress} />\n            ) : (\n              <View style={[s.warnBox, { backgroundColor: alpha(colors.danger, 0.08) }]}>\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', lineHeight: 17 }}>\n                  ⚠️ La agencia cobra un importe por recibirte allí. La recogida a casa no tiene coste extra.\n                </Text>\n              </View>\n            )}\n\n            <Text style={s.label}>PAGO</Text>\n            <View style={s.chipRow}>\n              <Chip label=\"💵 Al abordar\" active={payOn === 'boarding'} onPress={() => setPayOn('boarding')} />\n              <Chip label=\"🏁 Al llegar al destino\" active={payOn === 'destination'} onPress={() => setPayOn('destination')} />\n            </View>\n            {isCommission && payOn === 'boarding' && (\n              <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                ⚠️ Compra por encargo: si el viajero no eres tú, lo normal es que pague al llegar al destino.\n              </Text>\n            )}\n\n            {!rental && (\n              <>\n                <Text style={s.label}>¿Quieres proponer una tarifa? (opcional)</Text>\n                <FormField label=\"Tarifa por asiento (XAF)\" placeholder={String(trip.price)} value={passengerFare} onChangeText={setPassengerFare} keyboardType=\"numeric\" />\n                {passengerFare.trim() && <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>El conductor revisará tu propuesta antes de confirmar.</Text>}\n              </>\n            )}\n\n            {error && <Text style={s.err}>{error}</Text>}\n            <PrimaryButton title=\"Continuar\" onPress={() => go('confirm')} />\n          </View>\n        )}\n\n        {step === 'confirm' && trip && (\n          <View style={s.block}>\n            <Text style={s.big}>Confirmar reserva</Text>\n            <View style={[s.summary, { borderColor: colors.border }]}>\n              <Row label=\"Ruta\" value={`${trip.route?.originDistrict ?? ''} → ${trip.route?.destinationDistrict ?? ''}`} />\n              <Row label=\"Salida\" value={new Date(trip.departureTime).toLocaleString('es')} />\n              <Row label=\"Tipo\" value={rental ? `🚐 Vehículo completo (${trip.totalSeats} plazas)` : `${seats} asiento(s)`} />\n              <Row label=\"Precio\" value={rental ? `${Number(trip.rentalPrice).toLocaleString('es')} XAF (total)` : `${unitPrice.toLocaleString('es')} XAF/asiento`} />\n              <Row label=\"Total\" value={`${total.toLocaleString('es')} XAF`} bold />\n              <Row label=\"Recogida\" value={pickupType === 'home' ? `A casa · ${pickupAddress}` : 'En agencia'} />\n              {minorCount > 0 && <Row label=\"Menores\" value={`${minorCount} · tutor ${guardianName.trim() || '—'}`} />}\n              {!rental && passengerFare.trim() && <Row label=\"Tarifa propuesta\" value=\"Pendiente de aceptación\" />}\n            </View>\n            {!rental && passengerFare.trim() && (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', textAlign: 'center' }}>\n                Si el conductor acepta tu tarifa, el total será {total.toLocaleString('es')} XAF. Si la rechaza, se liberan tus asientos.\n              </Text>\n            )}\n            {error && <Text style={s.err}>{error}</Text>}\n            <PrimaryButton title=\"Confirmar reserva\" onPress={() => void confirm()} loading={busyRef.current} disabled={busyRef.current} />\n            <GhostButton title=\"Volver\" onPress={() => go('passenger')} />\n          </View>\n        )}\n\n        {step === 'ticket' && booking && (\n          <View style={[s.block, { alignItems: 'center' }]}>\n            <CheckCircle2 size={52} color={colors.success} />\n            <Text style={s.big}>{booking.fareStatus === 'proposed' ? 'Tarifa enviada al conductor' : '¡Reserva confirmada!'}</Text>\n            <Text style={s.body}>{booking.message}</Text>\n            <View style={[s.ticketBox, { borderColor: colors.primary }]}>\n              <Ticket size={26} color={colors.primary} />\n              <Text style={{ color: colors.textPrimary, fontSize: 26, fontWeight: '900', letterSpacing: 2 }}>{booking.booking?.shortCode ?? booking.ticketQrCode}</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>{booking.ticketQrCode} · muestra este código al conductor</Text>\n            </View>\n            {phone.trim() && (\n              <Pressable\n                onPress={() => {\n                  const msg = `🧾 Ticket EG Route Plan\\nCódigo: ${booking.booking?.shortCode ?? booking.ticketQrCode} (${booking.ticketQrCode})\\n${trip?.route?.originDistrict ?? ''} → ${trip?.route?.destinationDistrict ?? ''}\\n${trip ? new Date(trip.departureTime).toLocaleString('es') : ''}\\n${rental ? 'Vehículo completo' : `${totalSeatsUsed} asiento(s)`}`;\n                  Linking.openURL(`https://wa.me/${digits(phone)}?text=${encodeURIComponent(msg)}`).catch(() => {});\n                }}\n                accessibilityRole=\"button\" accessibilityLabel=\"Enviar ticket por WhatsApp\"\n                style={({ pressed }) => [{ backgroundColor: brand.whatsapp, borderRadius: radios.md, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e20, opacity: pressed ? 0.85 : 1 }]}\n              >\n                <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body, textAlign: 'center' }}>Enviar por WhatsApp</Text>\n              </Pressable>\n            )}\n            {booking.booking?.payOn === 'destination' && (\n              <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body }}>💵 Pago: al llegar al destino</Text>\n            )}\n            {booking.booking?.buyerPhone && phone.trim() && booking.booking.buyerPhone !== gqPhone(phone) && (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', textAlign: 'center' }}>\n                🎫 Comprado por {booking.booking.buyerName || booking.booking.buyerPhone} para {firstName.trim()} {lastName.trim()}\n              </Text>\n            )}\n            {booking.fareStatus === 'proposed' && (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', textAlign: 'center' }}>\n                Tus asientos quedan reservados hasta que el conductor acepte o rechace tu tarifa.\n              </Text>\n            )}\n            <PrimaryButton title=\"Listo\" onPress={() => router.replace('/')} />\n            <GhostButton title=\"Ver mis tickets\" onPress={() => router.push('/my-tickets' as never)} />\n          </View>\n        )}\n      </ScrollView>\n      ) : (\n        /*\n          LISTA VIRTUALIZADA (auditoría de diseño, D-04/D-21): antes era un .map() y todos los\n          viajes quedaban montados. Aquí el paso de resultados ES la lista; los pasos de\n          formulario siguen en el ScrollView, porque anidar listas virtualizadas la desactiva.\n        */\n        <FlatList\n          data={trips}\n          keyExtractor={(t) => t.id}\n          contentContainerStyle={[s.content, { gap: espaciado.e12, paddingBottom: insets.bottom + 24 }]}\n          showsVerticalScrollIndicator={false}\n          keyboardShouldPersistTaps=\"handled\"\n          initialNumToRender={10}\n          windowSize={7}\n          removeClippedSubviews\n          ListHeaderComponent={\n            /*\n            Un `View` con el hueco del contenedor, y no un fragmento: el `gap` de\n            `contentContainerStyle` separa CELDAS, y `ListHeaderComponent` es UNA celda. Con un\n            fragmento, todo lo de aquí dentro quedaba pegado (era gap: espaciado.e12 antes de virtualizar).\n            */\n            <View style={s.block}>\n              <Text style={s.big}>{trip?.route ? `${trip.route.originDistrict ?? ''} → ${trip.route.destinationDistrict ?? ''}` : 'Viajes disponibles'}</Text>\n              <Text style={s.body}>Salida por hora local. Paga en efectivo al abordar (o al llegar).</Text>\n            </View>\n          }\n          ListEmptyComponent={\n            <Text style={{ color: colors.textSecondary, fontWeight: '700', textAlign: 'center' }}>No hay viajes publicados para esta ruta todavía.</Text>\n          }\n          renderItem={({ item: t }) => (\n            <Pressable key={t.id} onPress={() => pickTrip(t)} accessibilityRole=\"button\"\n              accessibilityLabel={`Viaje ${new Date(t.departureTime).toLocaleString('es')}, ${t.availableSeats} asientos libres`}\n              style={({ pressed }) => [s.tripCard, { borderColor: colors.border, opacity: pressed ? 0.85 : 1 }]}>\n              {t.photos && t.photos.length > 0 ? (\n                <LazyImage source={{ uri: absUrl(t.photos[0]) }} style={s.avatar} />\n              ) : t.publisherPhoto ? (\n                <LazyImage source={{ uri: absUrl(t.publisherPhoto) }} style={s.avatar} />\n              ) : (\n                <View style={[s.avatar, { backgroundColor: alpha(colors.primary, 0.15) }]}><RouteIcon size={20} color={colors.primary} /></View>\n              )}\n              <View style={{ flex: 1, gap: espaciado.e3 }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>\n                  {new Date(t.departureTime).toLocaleTimeString('es', { hour: '2-digit', minute: '2-digit' })}\n                  <Text style={{ color: colors.textSecondary, fontWeight: '600', fontSize: tipografia.caption }}>\n                    {'  '}{new Date(t.departureTime).toLocaleDateString('es', { day: 'numeric', month: 'short' })}\n                  </Text>\n                </Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                  {IC_VEHICLE_LABELS[t.vehicleType ?? 'car'] ?? t.vehicleType}{t.vehicleModel ? ` · ${t.vehicleModel}` : ''}{t.vehiclePlate ? ` · ${t.vehiclePlate}` : ''} · {t.publisherName ?? 'Conductor'}\n                </Text>\n                {t.publisherBadge ? (\n                  <View style={{ flexDirection: 'row', alignItems: 'center', alignSelf: 'flex-start', backgroundColor: alpha(colors.primary, 0.12), paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3, borderRadius: radios.sm, marginTop: espaciado.e4 }}>\n                    <BadgeCheck size={12} color={colors.primary} />\n                    <Text style={{ color: colors.primary, fontSize: 10, fontWeight: '800', marginLeft: espaciado.e4 }}>{t.publisherBadge}</Text>\n                  </View>\n                ) : null}\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                  {t.availableSeats} asientos libres · {Number(t.price).toLocaleString('es')} XAF\n                </Text>\n                {t.rentalPrice != null && (\n                  <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>🚐 Alquiler completo: {Number(t.rentalPrice).toLocaleString('es')} XAF</Text>\n                )}\n              </View>\n              <ChevronRight size={20} color={colors.primary} />\n            </Pressable>\n          )}\n        />\n      )}\n    </View>\n  );\n}\n\nfunction Row({ label, value, bold }: { label: string; value: string; bold?: boolean }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flexDirection: 'row', justifyContent: 'space-between', paddingVertical: espaciado.e4, gap: espaciado.e12 }}>\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, fontWeight: '600' }}>{label}</Text>\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: bold ? '900' : '700', flexShrink: 1, textAlign: 'right' }}>{value}</Text>\n    </View>\n  );\n}\n\nfunction Chip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityState={{ selected: active }}\n      accessibilityLabel={label}\n      style={({ pressed }) => [styles(colors).chip, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? alpha(colors.primary, 0.08) : colors.card, opacity: pressed ? 0.85 : 1 }]}\n    >\n      <Text style={{ color: active ? colors.primary : colors.textPrimary, fontWeight: '700', fontSize: tipografia.caption }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e6 },\n  title: { fontSize: 18, fontWeight: '800', color: c.textPrimary },\n  content: { padding: espaciado.e20, gap: espaciado.e16 },\n  block: { gap: espaciado.e12 },\n  big: { fontSize: tipografia.title, fontWeight: '900', color: c.textPrimary, textAlign: 'center' },\n  body: { fontSize: tipografia.body, lineHeight: 20, color: c.textSecondary, textAlign: 'center', fontWeight: '600' },\n  label: { fontSize: tipografia.caption, fontWeight: '800', color: c.textSecondary, marginTop: espaciado.e4 },\n  labelInline: { fontSize: tipografia.caption, fontWeight: '800', color: c.textSecondary, marginTop: espaciado.e4, alignSelf: 'center' },\n  zone: { fontSize: tipografia.caption, fontWeight: '700', color: c.primary },\n  chipRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  chip: { borderRadius: radios.md, borderWidth: 1.5, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8 },\n  tripCard: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderWidth: 1.5, borderRadius: 14, padding: espaciado.e14 },\n  avatar: { width: 44, height: 44, borderRadius: 22, overflow: 'hidden', backgroundColor: c.surface },\n  warnBox: { borderRadius: radios.md, padding: espaciado.e12 },\n  summary: { borderRadius: radios.lg, borderWidth: 1.5, padding: espaciado.e14 },\n  ticketBox: { alignItems: 'center', gap: espaciado.e8, borderWidth: 2, borderRadius: 18, padding: espaciado.e22, width: '100%', borderStyle: 'dashed' },\n  err: { color: c.danger, fontSize: tipografia.body, fontWeight: '700' },\n});\n","/**\r\n * KYC — Paso 2: captura de documento (frontal / reverso).\r\n * Recibe por params: submissionId, docType, sides (csv).\r\n * Sube cada cara directamente a MinIO vía URL prefirmada y notifica al backend.\r\n */\r\n\r\nimport React, { useEffect, useMemo, useState } from 'react';\r\nimport { StyleSheet, Text, View } from 'react-native';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { CameraCapture, espaciado, KycStatusBanner, PrimaryButton, StepHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { kycApi, base64ToBytes, hashBytes } from '../../api/kyc';\r\nimport { ApiError } from '../../api/auth';\r\nimport { KYC_STATUS_TO_STEP } from '@egrouteplan/contracts';\r\n\r\nconst MIME = 'image/jpeg';\r\n\r\nexport default function KycCaptureScreen() {\r\n  const { colors } = useTheme();\r\n  const insets = useSafeAreaInsets();\r\n  const router = useRouter();\r\n  const params = useLocalSearchParams<{ submissionId: string; docType: string; sides: string }>();\r\n\r\n  const submissionId = params.submissionId;\r\n  const docType = params.docType;\r\n  const sides = useMemo(() => params.sides.split(',').filter(Boolean), [params.sides]);\r\n\r\n  const [stepIndex, setStepIndex] = useState(0);\r\n  const [side, setSide] = useState(sides[0] ?? 'front');\r\n  const [busy, setBusy] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n  const [doneSides, setDoneSides] = useState<string[]>([]);\r\n\r\n  useEffect(() => {\r\n    setSide(sides[stepIndex] ?? sides[sides.length - 1]);\r\n  }, [stepIndex, sides]);\r\n\r\n  const instruction =\r\n    side === 'front' ? 'Centra el anverso dentro del marco'\r\n    : side === 'back' ? 'Ahora la parte de atrás'\r\n    : 'Centra el documento';\r\n\r\n  const handleCapture = async (photo: { uri: string; base64?: string }) => {\r\n    if (!photo.base64 || busy) return;\r\n    setBusy(true);\r\n    setError(null);\r\n\r\n    try {\r\n      const bytes = base64ToBytes(photo.base64);\r\n      const sha256 = hashBytes(bytes);\r\n\r\n      const presign = await kycApi.presign(submissionId, {\r\n        docType: docType as any,\r\n        side: side as any,\r\n        mime: MIME,\r\n        bytes: bytes.length,\r\n        sha256,\r\n      });\r\n\r\n      await kycApi.uploadToPresignedUrl(presign.uploadUrl, bytes, MIME, presign.headers);\r\n\r\n      await kycApi.completeDocument(submissionId, {\r\n        storageKey: presign.storageKey,\r\n        sha256,\r\n        docType: docType as any,\r\n        side: side as any,\r\n        mime: MIME,\r\n        bytes: bytes.length,\r\n      });\r\n\r\n      const nextDone = [...doneSides, side];\r\n      setDoneSides(nextDone);\r\n\r\n      if (nextDone.length >= sides.length) {\r\n        // Todas las piezas subidas; pasamos a estado para esperar OCR → LIVENESS_REQUIRED.\r\n        router.replace({ pathname: '/kyc/status', params: { submissionId } });\r\n      } else {\r\n        setStepIndex((i) => i + 1);\r\n      }\r\n    } catch (e) {\r\n      setError(e instanceof ApiError ? e.message : 'Error al procesar la foto');\r\n    } finally {\r\n      setBusy(false);\r\n    }\r\n  };\r\n\r\n  const stepInfo = KYC_STATUS_TO_STEP.OCR_PENDING;\r\n\r\n  return (\r\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top + 12 }]}>\r\n      <View style={styles.header}>\r\n        <StepHeader\r\n          step={stepInfo.index}\r\n          total={stepInfo.total}\r\n          title={`Foto del documento (${doneSides.length + 1}/${sides.length})`}\r\n          subtitle={instruction}\r\n        />\r\n      </View>\r\n\r\n      {error ? (\r\n        <View style={styles.banner}>\r\n          <KycStatusBanner tone=\"error\" title=\"No se pudo guardar la foto\" message={error} />\r\n        </View>\r\n      ) : null}\r\n\r\n      <View style={styles.camera}>\r\n        <CameraCapture variant=\"document\" instruction={instruction} onCapture={handleCapture} />\r\n      </View>\r\n\r\n      <View style={styles.footer}>\r\n        <Text style={[styles.legal, { color: colors.textSecondary }]}>\r\n          La imagen se cifra antes de salir de tu dispositivo.\r\n        </Text>\r\n        {busy && (\r\n          <PrimaryButton title=\"Subiendo…\" onPress={() => {}} loading disabled />\r\n        )}\r\n      </View>\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1, paddingHorizontal: espaciado.e20, paddingTop: espaciado.e12, paddingBottom: espaciado.e24 },\r\n  header: { marginBottom: espaciado.e12 },\r\n  banner: { marginBottom: espaciado.e12 },\r\n  camera: { flex: 1, borderRadius: 24, overflow: 'hidden' },\r\n  footer: { marginTop: espaciado.e16, gap: espaciado.e10 },\r\n  legal: { fontSize: tipografia.micro, textAlign: 'center', fontWeight: '600' },\r\n});\r\n","/**\n * Cliente KYC — app React Native.\n * Consume /v1/mobility/kyc/* siguiendo el contrato de @egrouteplan/contracts\n * y el flujo probado en kyc-gate-e2e.mjs.\n * Usa httpClient (sesión inyectada + refresco 401 silencioso).\n */\n\nimport { http, ApiError } from './httpClient';\nimport {\n  type StartSubmissionRequest,\n  type StartSubmissionResponse,\n  type PresignDocRequest,\n  type PresignDocResponse,\n  type CompleteDocRequest,\n  type LivenessChallenge,\n  type BiometryVerifyRequest,\n  type BiometryResult,\n  type KycStatus,\n  KYC_TERMINAL_STATUSES,\n} from '@egrouteplan/contracts';\nimport { sha256 } from 'js-sha256';\n\nexport type { KycStatus };\nexport { ApiError, KYC_TERMINAL_STATUSES };\n\nexport interface SubmissionState {\n  submissionId: string;\n  status: KycStatus;\n  riskScore: number | null;\n  riskFlags: string[];\n  faceMatchScore: number | null;\n  livenessScore: number | null;\n  decision: StartSubmissionResponse['decision'];\n}\n\n/** Decodifica base64 (de la cámara) a bytes crudos para subir y hashear. */\nexport function base64ToBytes(base64: string): Uint8Array {\n  const binary = atob(base64);\n  const bytes = new Uint8Array(binary.length);\n  for (let i = 0; i < binary.length; i++) {\n    bytes[i] = binary.charCodeAt(i);\n  }\n  return bytes;\n}\n\n/** SHA-256 en hex de un Uint8Array (bytes de la imagen). */\nexport function hashBytes(bytes: Uint8Array): string {\n  return sha256.update(bytes).hex();\n}\n\nexport const kycApi = {\n  /** Última submission del usuario (null si nunca inició KYC). */\n  current: () => http.get<SubmissionState | null>('/mobility/kyc/submissions/me', true),\n\n  /** Inicia una nueva submission (idempotente por idempotencyKey). */\n  start: (body: StartSubmissionRequest) =>\n    http.post<StartSubmissionResponse & { replay?: boolean }>('/mobility/kyc/submissions', body, true),\n\n  /** Estado completo de una submission. */\n  get: (id: string) => http.get<SubmissionState>(`/mobility/kyc/submissions/${id}`, true),\n\n  /** Obtiene URL prefirmada para subir una pieza documental directamente a MinIO. */\n  presign: (submissionId: string, body: PresignDocRequest) =>\n    http.post<PresignDocResponse>(`/mobility/kyc/submissions/${submissionId}/documents/presign`, body, true),\n\n  /** Sube bytes a la URL prefirmada (PUT directo al storage). */\n  uploadToPresignedUrl: async (uploadUrl: string, bytes: Uint8Array, mime: string, extraHeaders: Record<string, string>) => {\n    const res = await fetch(uploadUrl, {\n      method: 'PUT',\n      headers: {\n        'Content-Type': mime,\n        'Content-Length': String(bytes.length),\n        ...extraHeaders,\n      },\n      body: new Blob([bytes], { type: mime }) as any,\n    });\n    if (!res.ok) {\n      const text = await res.text().catch(() => `HTTP ${res.status}`);\n      throw new ApiError('UPLOAD_FAILED', `No se pudo subir el archivo: ${text.slice(0, 120)}`);\n    }\n  },\n\n  /** Notifica al backend que la pieza ya está en storage y encola OCR. */\n  completeDocument: (submissionId: string, body: CompleteDocRequest) =>\n    http.post<{ documentId: string; ocrStatus: string }>(\n      `/mobility/kyc/submissions/${submissionId}/documents/complete`,\n      body,\n      true,\n    ),\n\n  /** Crea un desafío de liveness firmado. */\n  createChallenge: (submissionId: string) =>\n    http.post<LivenessChallenge>(`/mobility/kyc/submissions/${submissionId}/biometrics/challenge`, undefined, true),\n\n  /** Envía frames para verificación de liveness y encadena scoring/AML. */\n  verifyBiometry: (submissionId: string, body: BiometryVerifyRequest) =>\n    http.post<BiometryResult>(`/mobility/kyc/submissions/${submissionId}/biometrics/verify`, body, true),\n};\n","export * from './kyc';\n// Parte 42-a: la máquina de estados de una reserva (estados, acciones, quién puede y\n// qué exige cada una). Es lo único de este paquete que se usa fuera de KYC, y por eso\n// se exporta: un contrato que no se puede importar es un comentario largo.\nexport * from './reservation-flow';\n","/**\n * CONTRATOS KYC — única fuente de verdad compartida (app RN ↔ backend).\n * Cualquier cambio aquí es breaking-change contractual: versionar con cuidado.\n */\n\n// ---------------------------------------------------------------------------\n// FSM — estados y transiciones válidas (Pilar 2)\n// ---------------------------------------------------------------------------\n\nexport const KYC_STATUSES = [\n  'INITIATED', 'OCR_PENDING', 'OCR_FAILED',\n  'LIVENESS_REQUIRED', 'LIVENESS_FAILED',\n  'AML_CHECK', 'MANUAL_REVIEW',\n  'APPROVED_L1', 'APPROVED_L2', 'REJECTED', 'EXPIRED',\n] as const;\nexport type KycStatus = (typeof KYC_STATUSES)[number];\n\nexport const KYC_TERMINAL_STATUSES: readonly KycStatus[] = ['APPROVED_L1', 'APPROVED_L2', 'REJECTED', 'EXPIRED'];\n\n/** Mapa de transiciones permitidas (el backend lo valida; la app lo usa para el StepHeader). */\nexport const KYC_TRANSITIONS: Readonly<Record<KycStatus, readonly KycStatus[]>> = {\n  INITIATED: ['OCR_PENDING'],\n  OCR_PENDING: ['LIVENESS_REQUIRED', 'OCR_FAILED'],\n  OCR_FAILED: ['OCR_PENDING', 'REJECTED'],\n  LIVENESS_REQUIRED: ['AML_CHECK', 'LIVENESS_FAILED', 'MANUAL_REVIEW'],\n  LIVENESS_FAILED: ['LIVENESS_REQUIRED', 'MANUAL_REVIEW', 'REJECTED'],\n  AML_CHECK: ['APPROVED_L1', 'APPROVED_L2', 'MANUAL_REVIEW', 'REJECTED'],\n  MANUAL_REVIEW: ['APPROVED_L1', 'APPROVED_L2', 'REJECTED'],\n  APPROVED_L1: ['EXPIRED'],\n  APPROVED_L2: ['EXPIRED'],\n  REJECTED: [],\n  EXPIRED: ['INITIATED'],\n} as const;\n\nexport function canTransition(from: KycStatus, to: KycStatus): boolean {\n  return KYC_TRANSITIONS[from].includes(to);\n}\n\n// ---------------------------------------------------------------------------\n// Documentos y vía documental (árbol de decisión server-driven — Pilar 3)\n// ---------------------------------------------------------------------------\n\nexport const KYC_DOC_TYPES = ['DIP', 'PASSPORT', 'RESIDENCE_CARD', 'SCHOOL_ID', 'TUTOR_DIP'] as const;\nexport type KycDocType = (typeof KYC_DOC_TYPES)[number];\n\nexport const KYC_DOC_SIDES = ['front', 'back', 'selfie', 'photo_id'] as const;\nexport type KycDocSide = (typeof KYC_DOC_SIDES)[number];\n\nexport type KycNationalityPath = 'NATIONAL_ADULT' | 'FOREIGN_ADULT' | 'MINOR' | 'NOT_ELIGIBLE';\n\nexport interface KycDocOption {\n  docType: KycDocType;\n  sides: KycDocSide[];\n  title: string;        // ≤ 5 palabras para DocumentChoiceTree\n  subtitle: string;     // 1 línea\n}\n\nexport interface KycDecisionResult {\n  path: KycNationalityPath;\n  isMinor: boolean;\n  targetLevel: 1 | 2;\n  options: KycDocOption[];\n  requiresTutor: boolean;\n  requiresLiveness: boolean;\n}\n\n// ---------------------------------------------------------------------------\n// API DTOs\n// ---------------------------------------------------------------------------\n\nexport interface StartSubmissionRequest {\n  fullName: string;\n  birthDate: string;   // ISO date\n  nationality: string; // ISO-3166 alpha-2\n  idempotencyKey: string;\n}\n\nexport interface StartSubmissionResponse {\n  submissionId: string;\n  status: KycStatus;\n  decision: KycDecisionResult;\n}\n\nexport interface PresignDocRequest {\n  docType: KycDocType;\n  side: KycDocSide;\n  mime: 'image/jpeg' | 'image/png' | 'image/webp';\n  bytes: number;\n  sha256: string;\n}\n\nexport interface PresignDocResponse {\n  uploadUrl: string;\n  headers: Record<string, string>;\n  storageKey: string;\n  expiresIn: number; // segundos\n}\n\nexport interface CompleteDocRequest {\n  storageKey: string;\n  sha256: string;\n  docType: KycDocType;\n  side: KycDocSide;\n  mime: 'image/jpeg' | 'image/png' | 'image/webp';\n  bytes: number;\n}\n\nexport const LIVENESS_METHODS = ['BLINK', 'TURN', 'READ_DIGITS'] as const;\nexport type LivenessMethod = (typeof LIVENESS_METHODS)[number];\n\nexport interface LivenessChallenge {\n  challengeId: string;\n  method: LivenessMethod;\n  actions: string[];     // p. ej. ['BLINK_X2', 'TURN_LEFT'] o dígitos ['4','8','1','9']\n  expiresIn: number;     // 90 s\n  sessionSignature: string; // HMAC anti camera-injection\n}\n\nexport interface BiometryVerifyRequest {\n  challengeId: string;\n  sessionSignature: string; // HMAC anti-replay entregado con el challenge\n  framesSha256: string[];\n  captureTimestamps: number[]; // monótonos del dispositivo\n  deviceSignal?: DeviceSignalPayload;\n}\n\nexport interface BiometryResult {\n  livenessScore: number;\n  faceMatchScore: number;\n  antiSpoofFlags: string[];\n  nextStatus: KycStatus;\n}\n\n// ---------------------------------------------------------------------------\n// Riesgo y AML (Pilar 4)\n// ---------------------------------------------------------------------------\n\nexport interface DeviceSignalPayload {\n  deviceId: string;\n  platform: 'ios' | 'android';\n  osVersion: string;\n  model: string;\n  gpsLat?: number;\n  gpsLng?: number;\n  isRooted?: boolean;\n  isEmulator?: boolean;\n}\n\nexport const RISK_FLAGS = [\n  'EMULATOR', 'ROOTED', 'MULTI_ACCOUNT_DEVICE', 'GEO_MISMATCH',\n  'FACE_MATCH_LOW', 'VIRTUAL_CAMERA_SUSPECT', 'PEP_HIT', 'SANCTIONS_HIT',\n] as const;\nexport type RiskFlag = (typeof RISK_FLAGS)[number];\n\nexport interface RiskDecision {\n  riskScore: number;              // 0–100\n  flags: RiskFlag[];\n  walletDailyLimit: number;       // XAF\n  withdrawalAllowed: boolean;\n  forcedManualReview: boolean;\n}\n\n/** Matriz de riesgo → límites del monedero (contrato Fase C). */\nexport function riskToWalletLimits(riskScore: number): Omit<RiskDecision, 'flags'> {\n  if (riskScore >= 80) return { walletDailyLimit: 0, withdrawalAllowed: false, forcedManualReview: true, riskScore };\n  if (riskScore >= 60) return { walletDailyLimit: 20_000, withdrawalAllowed: false, forcedManualReview: true, riskScore };\n  if (riskScore >= 30) return { walletDailyLimit: 50_000, withdrawalAllowed: false, forcedManualReview: false, riskScore };\n  return { walletDailyLimit: 100_000, withdrawalAllowed: true, forcedManualReview: false, riskScore };\n}\n\n// ---------------------------------------------------------------------------\n// Eventos SSE (StepHeader en tiempo real — Pilar 2.4)\n// ---------------------------------------------------------------------------\n\nexport interface KycStatusEvent {\n  type: 'status' | 'document.ocr' | 'biometry.score' | 'aml.score' | 'review.note';\n  submissionId: string;\n  from?: KycStatus;\n  to?: KycStatus;\n  stepIndex: number;      // 1-based para el StepHeader del ui-kit\n  stepTotal: number;\n  label: string;          // texto humano ≤ 6 palabras\n  at: string;             // ISO timestamp\n}\n\n/** Mapeo estado → índice de paso visual para la app. */\nexport const KYC_STATUS_TO_STEP: Readonly<Record<KycStatus, { index: number; total: number; label: string }>> = {\n  INITIATED: { index: 1, total: 5, label: 'Datos personales' },\n  OCR_PENDING: { index: 2, total: 5, label: 'Leyendo documento' },\n  OCR_FAILED: { index: 2, total: 5, label: 'Documento ilegible' },\n  LIVENESS_REQUIRED: { index: 3, total: 5, label: 'Prueba de vida' },\n  LIVENESS_FAILED: { index: 3, total: 5, label: 'Prueba fallida' },\n  AML_CHECK: { index: 4, total: 5, label: 'Verificación de seguridad' },\n  MANUAL_REVIEW: { index: 4, total: 5, label: 'Revisión en curso' },\n  APPROVED_L1: { index: 5, total: 5, label: 'Verificado' },\n  APPROVED_L2: { index: 5, total: 5, label: 'Verificado' },\n  REJECTED: { index: 5, total: 5, label: 'No verificado' },\n  EXPIRED: { index: 5, total: 5, label: 'Documento vencido' },\n} as const;\n\n// ---------------------------------------------------------------------------\n// Webhooks (Pilar 2.3)\n// ---------------------------------------------------------------------------\n\nexport interface WebhookAck {\n  received: boolean;\n  deduped?: boolean;\n}\n\nexport interface ProviderOcrWebhookPayload {\n  externalId: string;\n  submissionId: string;\n  docType: KycDocType;\n  side: KycDocSide;\n  ok: boolean;\n  confidence?: number;\n  fields?: Record<string, string>;\n  error?: string;\n}\n","/**\n * reservation-flow — LA MÁQUINA DE ESTADOS DE UNA RESERVA, en un solo sitio.\n *\n * Lo que corrige del bloque que se escribió antes:\n *   · **Faltaba `hold`**, que es el estado en el que NACE toda reserva con pago parcial\n *     (la habitación retenida mientras se paga la señal): sin él, la pantalla no ofrecía\n *     ninguna acción justo cuando el usuario más las necesita.\n *   · Las etiquetas estaban indexadas por ESTADO cuando el nombre decía «acción»: ahora\n *     son acciones (`confirm`, `checkin`, `cancel`…) con su estado de destino.\n *   · Faltaba **quién** puede cada acción (el huésped solo cancela) y **qué exige**\n *     (motivo obligatorio al cancelar, depósito confirmado antes del check-in): sin eso\n *     la interfaz ofrece botones que el servidor rechaza con 409.\n *   · `Record<string, …>` no da tipos: ahora es `Record<ReservationStatus, …>`, así que\n *     una errata la caza el compilador.\n *\n * Sigue siendo una copia del servidor (el servidor es la fuente): vive aquí para que la\n * app no cablee literales en las pantallas y para poder probarla sin base de datos.\n */\n\n/** Los SIETE estados reales (los mismos que la tabla `lifebook.reservations`). */\nexport const RESERVATION_STATUSES = [\n  'hold', 'pending', 'confirmed', 'checked_in', 'checked_out', 'cancelled', 'no_show',\n] as const;\nexport type ReservationStatus = (typeof RESERVATION_STATUSES)[number];\n\n/** Estados de pago (el dinero va SEPARADO del estado de la reserva). */\nexport const PAYMENT_STATUSES = [\n  'pending', 'proof_submitted', 'deposit_paid', 'paid', 'refunded', 'failed',\n] as const;\nexport type PaymentStatus = (typeof PAYMENT_STATUSES)[number];\n\n/** Las acciones que una persona puede ejecutar. */\nexport const RESERVATION_ACTIONS = ['confirm', 'checkin', 'checkout', 'cancel', 'noshow'] as const;\nexport type ReservationAction = (typeof RESERVATION_ACTIONS)[number];\n\nexport interface ReservationActionSpec {\n  /** Estado al que lleva la acción. */\n  to: ReservationStatus;\n  /** Etiqueta para el botón, desde el punto de vista de quien la ejecuta. */\n  label: string;\n  /** Quién puede: el hotel, el huésped, o los dos. */\n  who: Array<'hotel' | 'guest'>;\n  /** ¿Exige motivo escrito? (queda registrado en la reserva) */\n  reasonRequired?: boolean;\n  /** ¿Exige que la señal esté cobrada? */\n  requiresDepositPaid?: boolean;\n}\n\n/** Acciones por estado de origen. Un estado terminal no tiene ninguna (`[]`). */\nexport const RESERVATION_TRANSITIONS: Readonly<Record<ReservationStatus, ReservationAction[]>> = {\n  // Retenida sin pagar: lo urgente es cobrar la señal (botón aparte) o soltarla.\n  hold: ['cancel'],\n  // Señal cobrada, sin confirmar por el hotel: lo natural es confirmar la reserva.\n  pending: ['confirm', 'cancel'],\n  confirmed: ['checkin', 'noshow', 'cancel'],\n  checked_in: ['checkout', 'cancel'],\n  checked_out: [],\n  cancelled: [],\n  no_show: [],\n};\n\n/** La ficha de cada acción (etiqueta, quién y qué exige). */\nexport const RESERVATION_ACTIONS_SPEC: Readonly<Record<ReservationAction, ReservationActionSpec>> = {\n  confirm: { to: 'confirmed', label: 'Confirmar reserva', who: ['hotel'], requiresDepositPaid: true },\n  checkin: { to: 'checked_in', label: 'Registrar entrada', who: ['hotel'], requiresDepositPaid: true },\n  checkout: { to: 'checked_out', label: 'Registrar salida', who: ['hotel'] },\n  cancel: { to: 'cancelled', label: 'Cancelar reserva', who: ['hotel', 'guest'], reasonRequired: true },\n  noshow: { to: 'no_show', label: 'No se presentó', who: ['hotel'], reasonRequired: true },\n};\n\n/**\n * Etiquetas de estado en lenguaje humano, con el matiz del DINERO incluido (una\n * reserva «pending» no es solo «pendiente»: es «señal pagada, por confirmar»).\n */\nexport const RESERVATION_STATUS_LABELS: Readonly<Record<ReservationStatus, string>> = {\n  hold: 'Sin pagar (retenida)',\n  pending: 'Señal pagada · por confirmar',\n  confirmed: 'Confirmada',\n  checked_in: 'Huésped dentro',\n  checked_out: 'Finalizada',\n  cancelled: 'Cancelada',\n  no_show: 'No se presentó',\n};\n\n/** Estados que OCUPAN inventario (una retención vencida ya no). */\nexport const OCCUPYING_STATUSES: readonly ReservationStatus[] =\n  ['hold', 'pending', 'confirmed', 'checked_in'];\n\n/**\n * ¿Sigue ocupando la habitación? Una retención con la cuenta atrás agotada ya NO,\n * aunque el barrido del servidor todavía no la haya cancelado.\n */\nexport function isReservationLive(\n  status: ReservationStatus | string,\n  holdExpiresAt?: string | null,\n  now: number = Date.now(),\n): boolean {\n  if (!OCCUPYING_STATUSES.includes(status as ReservationStatus)) return false;\n  if (status === 'hold' && holdExpiresAt) return new Date(holdExpiresAt).getTime() > now;\n  return true;\n}\n\n/**\n * Acciones que puede hacer un actor ahora mismo sobre una reserva.\n *\n * `who`: 'hotel' | 'guest' | 'admin'. La administración las tiene todas.\n * `depositPaid`: para no ofrecer un check-in que el servidor va a rechazar.\n */\nexport function availableActions(\n  status: ReservationStatus | string,\n  opts: { who: 'hotel' | 'guest' | 'admin'; depositPaid?: boolean; viva?: boolean } ,\n): ReservationAction[] {\n  const acciones = RESERVATION_TRANSITIONS[status as ReservationStatus] ?? [];\n  const viva = opts.viva ?? isReservationLive(status as ReservationStatus);\n  return acciones.filter((a) => {\n    const spec = RESERVATION_ACTIONS_SPEC[a];\n    if (opts.who !== 'admin' && !spec.who.includes(opts.who)) return false;\n    // Una retención vencida solo se puede «soltar» (cancelar/no presentar).\n    if (!viva && a !== 'cancel') return false;\n    // Confirmar y entrar exigen que la señal esté cobrada (si hay señal).\n    if (spec.requiresDepositPaid && opts.depositPaid === false && status === 'confirmed') {\n      return a !== 'checkin';\n    }\n    return true;\n  });\n}\n","/**\n * [js-sha256]{@link https://github.com/emn178/js-sha256}\n *\n * @version 0.11.1\n * @author Chen, Yi-Cyuan [emn178@gmail.com]\n * @copyright Chen, Yi-Cyuan 2014-2025\n * @license MIT\n */\n/*jslint bitwise: true */\n(function () {\n  'use strict';\n\n  var ERROR = 'input is invalid type';\n  var WINDOW = typeof window === 'object';\n  var root = WINDOW ? window : {};\n  if (root.JS_SHA256_NO_WINDOW) {\n    WINDOW = false;\n  }\n  var WEB_WORKER = !WINDOW && typeof self === 'object';\n  var NODE_JS = !root.JS_SHA256_NO_NODE_JS && typeof process === 'object' && process.versions && process.versions.node && process.type != 'renderer';\n  if (NODE_JS) {\n    root = global;\n  } else if (WEB_WORKER) {\n    root = self;\n  }\n  var COMMON_JS = !root.JS_SHA256_NO_COMMON_JS && typeof module === 'object' && module.exports;\n  var AMD = typeof define === 'function' && define.amd;\n  var ARRAY_BUFFER = !root.JS_SHA256_NO_ARRAY_BUFFER && typeof ArrayBuffer !== 'undefined';\n  var HEX_CHARS = '0123456789abcdef'.split('');\n  var EXTRA = [-2147483648, 8388608, 32768, 128];\n  var SHIFT = [24, 16, 8, 0];\n  var K = [\n    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,\n    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,\n    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,\n    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,\n    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,\n    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,\n    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,\n    0x748f82ee