heme } from '@egrouteplan/ui-kit';\r\nimport { useSession } from '../../state/session';\r\nimport { kycApi, type SubmissionState } from '../../api/kyc';\r\nimport { ApiError } from '../../api/auth';\r\nimport { KYC_STATUS_TO_STEP } from '@egrouteplan/contracts';\r\n\r\nconst ISO_DATE_RE = /^\\d{4}-\\d{2}-\\d{2}$/;\r\nconst NATION_RE = /^[A-Za-z]{2}$/;\r\n\r\nfunction isDocStatus(s: string) {\r\n  return ['INITIATED', 'OCR_PENDING', 'OCR_FAILED'].includes(s);\r\n}\r\n\r\nexport default function KycStartScreen() {\r\n  const { colors } = useTheme();\r\n  const insets = useSafeAreaInsets();\r\n  const router = useRouter();\r\n  const { isUnlocked } = useSession();\r\n\r\n  const [loading, setLoading] = useState(true);\r\n  const [existing, setExisting] = useState<SubmissionState | null>(null);\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  const [fullName, setFullName] = useState('');\r\n  const [birthDate, setBirthDate] = useState('');\r\n  const [nationality, setNationality] = useState('GQ');\r\n  const [busy, setBusy] = useState(false);\r\n\r\n  useEffect(() => {\r\n    if (!isUnlocked) return;\r\n    kycApi\r\n      .current()\r\n      .then((sub) => {\r\n        setExisting(sub);\r\n        if (sub) {\r\n          if (sub.status === 'APPROVED_L2') {\r\n            // Ya verificado: nada que hacer aquí.\r\n          } else if (isDocStatus(sub.status)) {\r\n            const opt = sub.decision.options[0];\r\n            router.replace({\r\n              pathname: '/kyc/capture',\r\n              params: { submissionId: sub.submissionId, docType: opt.docType, sides: opt.sides.join(',') },\r\n            });\r\n          } else if (sub.status === 'LIVENESS_REQUIRED') {\r\n            router.replace({ pathname: '/kyc/liveness', params: { submissionId: sub.submissionId } });\r\n          } else {\r\n            router.replace({ pathname: '/kyc/status', params: { submissionId: sub.submissionId } });\r\n          }\r\n        }\r\n      })\r\n      .catch((e) => setError(e instanceof ApiError ? e.message : 'Error al consultar tu verificación'))\r\n      .finally(() => setLoading(false));\r\n  }, [isUnlocked]);\r\n\r\n  const canSubmit =\r\n    fullName.trim().length >= 3 && ISO_DATE_RE.test(birthDate) && NATION_RE.test(nationality);\r\n\r\n  const handleStart = async () => {\r\n    if (!isUnlocked || !canSubmit || busy) return;\r\n    setBusy(true);\r\n    setError(null);\r\n    try {\r\n      const idempotencyKey = `${Date.now()}-${Math.random().toString(36).slice(2)}`;\r\n      const res = await kycApi.start({\r\n        fullName: fullName.trim(),\r\n        birthDate,\r\n        nationality: nationality.toUpperCase(),\r\n        idempotencyKey,\r\n      });\r\n      const opt = res.decision.options[0];\r\n      router.replace({\r\n        pathname: '/kyc/capture',\r\n        params: { submissionId: res.submissionId, docType: opt.docType, sides: opt.sides.join(',') },\r\n      });\r\n    } catch (e) {\r\n      setError(e instanceof ApiError ? e.message : 'No se pudo iniciar la verificación');\r\n      setBusy(false);\r\n    }\r\n  };\r\n\r\n  if (loading || !isUnlocked) {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\r\n        <Text style={{ color: colors.textSecondary }}>Consultando estado…</Text>\r\n      </View>\r\n    );\r\n  }\r\n\r\n  if (existing?.status === 'APPROVED_L2') {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24 }]}>\r\n        <KycStatusBanner\r\n          tone=\"success\"\r\n          title=\"Identidad verificada\"\r\n          message=\"Ya puedes usar tu monedero de forma segura.\"\r\n          actionLabel=\"Ir al monedero\"\r\n          onAction={() => router.replace('/monedero')}\r\n        />\r\n      </View>\r\n    );\r\n  }\r\n\r\n  const stepInfo = KYC_STATUS_TO_STEP.INITIATED;\r\n\r\n  return (\r\n    <KeyboardAvoidingView\r\n      style={[styles.root, { backgroundColor: colors.background }]}\r\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\r\n    >\r\n      <ScrollView contentContainerStyle={[styles.scroll, { paddingTop: insets.top + 16 }]} keyboardShouldPersistTaps=\"handled\">\r\n        <StepHeader\r\n          step={stepInfo.index}\r\n          total={stepInfo.total}\r\n          title=\"Verifica tu identidad\"\r\n          subtitle=\"Necesitamos unos datos básicos para cumplir con la normativa y activar tu monedero.\"\r\n        />\r\n\r\n        {error ? (\r\n          <View style={styles.field}>\r\n            <KycStatusBanner tone=\"error\" title=\"Algo salió mal\" message={error} />\r\n          </View>\r\n        ) : null}\r\n\r\n        <View style={styles.field}>\r\n          <FormField\r\n            label=\"Nombre completo\"\r\n            placeholder=\"María Nsue Obiang\"\r\n            value={fullName}\r\n            onChangeText={setFullName}\r\n            autoCapitalize=\"words\"\r\n            autoComplete=\"name\"\r\n          />\r\n        </View>\r\n\r\n        <View style={styles.field}>\r\n          <FormField\r\n            label=\"Fecha de nacimiento\"\r\n            placeholder=\"AAAA-MM-DD\"\r\n            value={birthDate}\r\n            onChangeText={(t) => setBirthDate(t.replace(/[^0-9\\-]/g, '').slice(0, 10))}\r\n            keyboardType=\"numbers-and-punctuation\"\r\n            error={birthDate.length > 0 && !ISO_DATE_RE.test(birthDate) ? 'Formato: AAAA-MM-DD' : undefined}\r\n          />\r\n        </View>\r\n\r\n        <View style={styles.field}>\r\n          <FormField\r\n            label=\"Nacionalidad\"\r\n            placeholder=\"GQ\"\r\n            value={nationality}\r\n            onChangeText={(t) => setNationality(t.slice(0, 2).toUpperCase())}\r\n            autoCapitalize=\"characters\"\r\n            error={nationality.length === 2 && !NATION_RE.test(nationality) ? 'Código de 2 letras' : undefined}\r\n          />\r\n          <Text style={[styles.hint, { color: colors.textSecondary }]}>Código ISO de 2 letras (p. ej. GQ, CM, ES)</Text>\r\n        </View>\r\n\r\n        <View style={styles.button}>\r\n          <PrimaryButton title={busy ? 'Iniciando…' : 'Continuar'} onPress={handleStart} disabled={!canSubmit || busy} loading={busy} />\r\n        </View>\r\n      </ScrollView>\r\n    </KeyboardAvoidingView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1 },\r\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 },\r\n  scroll: { flexGrow: 1, paddingHorizontal: espaciado.e24, paddingTop: espaciado.e16, paddingBottom: 40 },\r\n  field: { marginTop: espaciado.e14 },\r\n  hint: { fontSize: tipografia.micro, marginTop: espaciado.e6, fontWeight: '600' },\r\n  button: { marginTop: espaciado.e32 },\r\n});\r\n","/**\r\n * KYC — Paso 3: prueba de vida (liveness).\r\n * Obtiene un desafío del servidor, captura 2 selfies consecutivos y los verifica.\r\n */\r\n\r\nimport React, { useEffect, useState } from 'react';\r\nimport { StyleSheet, Text, View } from 'react-native';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { CameraCapture, espaciado, KycStatusBanner, LivenessChallengeView, StepHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { kycApi, base64ToBytes, hashBytes } from '../../api/kyc';\r\nimport { ApiError } from '../../api/auth';\r\nimport { KYC_STATUS_TO_STEP } from '@egrouteplan/contracts';\r\n\r\nconst FRAMES_NEEDED = 2;\r\n\r\nexport default function KycLivenessScreen() {\r\n  const { colors } = useTheme();\r\n  const insets = useSafeAreaInsets();\r\n  const router = useRouter();\r\n  const { submissionId } = useLocalSearchParams<{ submissionId: string }>();\r\n\r\n  const [challenge, setChallenge] = useState<Awaited<ReturnType<typeof kycApi.createChallenge>> | null>(null);\r\n  const [frames, setFrames] = useState<{ sha256: string; ts: number }[]>([]);\r\n  const [busy, setBusy] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  useEffect(() => {\r\n    kycApi\r\n      .createChallenge(submissionId)\r\n      .then(setChallenge)\r\n      .catch((e) => setError(e instanceof ApiError ? e.message : 'Error al crear el desafío'));\r\n  }, [submissionId]);\r\n\r\n  const handleCapture = async (photo: { uri: string; base64?: string }) => {\r\n    if (!photo.base64 || !challenge || busy) return;\r\n\r\n    const bytes = base64ToBytes(photo.base64);\r\n    const sha256 = hashBytes(bytes);\r\n    const nextFrames = [...frames, { sha256, ts: Date.now() }];\r\n    setFrames(nextFrames);\r\n\r\n    if (nextFrames.length >= FRAMES_NEEDED) {\r\n      setBusy(true);\r\n      setError(null);\r\n      try {\r\n        await kycApi.verifyBiometry(submissionId, {\r\n          challengeId: challenge.challengeId,\r\n          sessionSignature: challenge.sessionSignature,\r\n          framesSha256: nextFrames.map((f) => f.sha256),\r\n          captureTimestamps: nextFrames.map((f) => f.ts),\r\n        });\r\n        router.replace({ pathname: '/kyc/status', params: { submissionId } });\r\n      } catch (e) {\r\n        setError(e instanceof ApiError ? e.message : 'Error al verificar la prueba de vida');\r\n        setBusy(false);\r\n      }\r\n    }\r\n  };\r\n\r\n  const stepInfo = KYC_STATUS_TO_STEP.LIVENESS_REQUIRED;\r\n  const progress = Math.min(frames.length / FRAMES_NEEDED, 1);\r\n\r\n  return (\r\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top + 12 }]}>\r\n      <View style={styles.header}>\r\n        <StepHeader\r\n          step={stepInfo.index}\r\n          total={stepInfo.total}\r\n          title=\"Prueba de vida\"\r\n          subtitle=\"Sigue la instrucción y captura 2 fotos seguidas dentro del óvalo.\"\r\n        />\r\n      </View>\r\n\r\n      {challenge ? (\r\n        <LivenessChallengeView\r\n          method={challenge.method as any}\r\n          actions={challenge.actions}\r\n          capturing={frames.length > 0 && frames.length < FRAMES_NEEDED}\r\n          progress={progress}\r\n          done={frames.length >= FRAMES_NEEDED}\r\n        />\r\n      ) : null}\r\n\r\n      {error ? (\r\n        <View style={styles.banner}>\r\n          <KycStatusBanner tone=\"error\" title=\"Prueba no válida\" message={error} />\r\n        </View>\r\n      ) : null}\r\n\r\n      <View style={styles.camera}>\r\n        {busy ? (\r\n          <View style={[styles.processing, { backgroundColor: colors.surface }]}>\r\n            <Text style={[styles.processingText, { color: colors.textPrimary }]}>Verificando…</Text>\r\n          </View>\r\n        ) : (\r\n          <CameraCapture\r\n            variant=\"selfie\"\r\n            instruction={`Foto ${frames.length + 1} de ${FRAMES_NEEDED}`}\r\n            onCapture={handleCapture}\r\n          />\r\n        )}\r\n      </View>\r\n\r\n      <View style={styles.footer}>\r\n        <Text style={[styles.hint, { color: colors.textSecondary }]}>\r\n          {frames.length === 0\r\n            ? 'Toca el botón cuando estés listo.'\r\n            : frames.length < FRAMES_NEEDED\r\n              ? 'Toca de nuevo para la segunda foto.'\r\n              : 'Enviando verificación…'}\r\n        </Text>\r\n      </View>\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1, paddingHorizontal: espaciado.e20, paddingTop: espaciado.e12, paddingBottom: espaciado.e24 },\r\n  header: { marginBottom: espaciado.e12 },\r\n  banner: { marginVertical: espaciado.e12 },\r\n  camera: { flex: 1, borderRadius: 24, overflow: 'hidden' },\r\n  processing: { flex: 1, alignItems: 'center', justifyContent: 'center' },\r\n  processingText: { fontSize: tipografia.subtitle, fontWeight: '800' },\r\n  footer: { marginTop: espaciado.e16 },\r\n  hint: { fontSize: tipografia.caption, textAlign: 'center', fontWeight: '600' },\r\n});\r\n","/**\r\n * KYC — Paso 4: estado de la verificación con polling.\r\n * Desde aquí se puede reintentar documentos, ir a liveness o volver al monedero.\r\n */\r\n\r\nimport React, { useEffect, useState } from 'react';\r\nimport { StyleSheet, Text, View } from 'react-native';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { SOPORTE, whatsappSoporte } from '../../constants/soporte';\r\nimport { espaciado, GhostButton, KycStatusBanner, PrimaryButton, StepHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { kycApi, type SubmissionState, KYC_TERMINAL_STATUSES } from '../../api/kyc';\r\nimport { ApiError } from '../../api/auth';\r\nimport { KYC_STATUS_TO_STEP } from '@egrouteplan/contracts';\r\n\r\nconst POLL_MS = 1500;\r\n\r\nexport default function KycStatusScreen() {\r\n  const { colors } = useTheme();\r\n  const insets = useSafeAreaInsets();\r\n  const router = useRouter();\r\n  const { submissionId } = useLocalSearchParams<{ submissionId: string }>();\r\n\r\n  const [state, setState] = useState<SubmissionState | null>(null);\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  useEffect(() => {\r\n    let alive = true;\r\n    /** El temporizador se guarda aquí para poder PARARLO cuando el KYC ya es terminal. */\r\n    let id: ReturnType<typeof setInterval> | null = null;\r\n\r\n    const tick = async () => {\r\n      try {\r\n        const s = await kycApi.get(submissionId);\r\n        if (!alive) return;\r\n        setState(s);\r\n        setError(null);\r\n        /**\r\n         * SI EL KYC YA ES TERMINAL, NO SE VUELVE A PREGUNTAR (auditoría de diseño, D-54).\r\n         * Antes este sondeo seguía cada 1,5 s PARA SIEMPRE, también con el KYC aprobado: batería,\r\n         * datos y peticiones al servidor sin ninguna razón. `isTerminal` existía y solo se usaba\r\n         * para pintar.\r\n         */\r\n        if (KYC_TERMINAL_STATUSES.includes(s.status as never)) {\r\n          if (id) { clearInterval(id); id = null; }\r\n        }\r\n      } catch (e) {\r\n        if (!alive) return;\r\n        setError(e instanceof ApiError ? e.message : 'Error al consultar estado');\r\n      }\r\n    };\r\n\r\n    tick();\r\n    id = setInterval(tick, POLL_MS);\r\n    return () => {\r\n      alive = false;\r\n      if (id) clearInterval(id);\r\n    };\r\n  }, [submissionId]);\r\n\r\n  if (error && !state) {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24 }]}>\r\n        <KycStatusBanner tone=\"error\" title=\"Error de conexión\" message={error} />\r\n      </View>\r\n    );\r\n  }\r\n\r\n  if (!state) {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\r\n        <Text style={{ color: colors.textSecondary }}>Consultando estado…</Text>\r\n      </View>\r\n    );\r\n  }\r\n\r\n  const stepInfo = KYC_STATUS_TO_STEP[state.status] ?? KYC_STATUS_TO_STEP.AML_CHECK;\r\n  const isTerminal = KYC_TERMINAL_STATUSES.includes(state.status as any);\r\n\r\n  return (\r\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top + 16 }]}>\r\n      <View style={styles.header}>\r\n        <StepHeader\r\n          step={stepInfo.index}\r\n          total={stepInfo.total}\r\n          title={stepInfo.label}\r\n          subtitle=\"Estamos validando tu información. Esto suele tardar unos segundos.\"\r\n          state={state.status === 'MANUAL_REVIEW' ? 'review' : state.status === 'REJECTED' ? 'error' : 'normal'}\r\n        />\r\n      </View>\r\n\r\n      <View style={styles.body}>\r\n        {state.status === 'APPROVED_L2' && (\r\n          <KycStatusBanner\r\n            tone=\"success\"\r\n            title=\"¡Identidad verificada!\"\r\n            message=\"Ya tienes acceso completo a tu monedero.\"\r\n            actionLabel=\"Ir al monedero\"\r\n            onAction={() => router.replace('/monedero')}\r\n          />\r\n        )}\r\n\r\n        {state.status === 'MANUAL_REVIEW' && (\r\n          <KycStatusBanner\r\n            tone=\"review\"\r\n            title=\"Revisión en curso\"\r\n            message=\"Un agente revisará tu caso en 24–48 h. Mientras tanto, la app sigue funcionando pero el monedero está en solo lectura.\"\r\n          />\r\n        )}\r\n\r\n        {state.status === 'REJECTED' && (\r\n          <KycStatusBanner\r\n            tone=\"error\"\r\n            title=\"No se pudo verificar\"\r\n            message={`Si crees que es un error, escríbenos: ${SOPORTE.email} · WhatsApp ${SOPORTE.telefono}`}\r\n            actionLabel=\"Escribir al soporte\"\r\n            onAction={() => { void whatsappSoporte('Hola, creo que hay un error en mi verificación de identidad.'); }}\r\n          />\r\n        )}\r\n\r\n        {state.status === 'LIVENESS_REQUIRED' && (\r\n          <>\r\n            <Text style={[styles.text, { color: colors.textPrimary }]}>\r\n              Documento validado. Ahora necesitamos la prueba de vida.\r\n            </Text>\r\n            <PrimaryButton\r\n              title=\"Hacer prueba de vida\"\r\n              onPress={() => router.replace({ pathname: '/kyc/liveness', params: { submissionId } })}\r\n            />\r\n          </>\r\n        )}\r\n\r\n        {state.status === 'OCR_FAILED' && (\r\n          <>\r\n            <KycStatusBanner\r\n              tone=\"review\"\r\n              title=\"Documento ilegible\"\r\n              message=\"Repite la foto con buena luz y sin reflejos.\"\r\n            />\r\n            <PrimaryButton\r\n              title=\"Repetir fotos\"\r\n              onPress={() =>\r\n                router.replace({\r\n                  pathname: '/kyc/capture',\r\n                  params: {\r\n                    submissionId,\r\n                    docType: state.decision.options[0].docType,\r\n                    sides: state.decision.options[0].sides.join(','),\r\n                  },\r\n                })\r\n              }\r\n            />\r\n          </>\r\n        )}\r\n\r\n        {!isTerminal && state.status !== 'LIVENESS_REQUIRED' && state.status !== 'OCR_FAILED' && (\r\n          <Text style={[styles.text, { color: colors.textSecondary }]}>\r\n            Validando {state.status === 'OCR_PENDING' ? 'el documento' : 'la prueba de vida'}…\r\n          </Text>\r\n        )}\r\n      </View>\r\n\r\n      <View style={styles.footer}>\r\n        <GhostButton title=\"Cancelar y volver\" onPress={() => router.replace('/')} />\r\n      </View>\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1, paddingHorizontal: espaciado.e24, paddingTop: espaciado.e16, paddingBottom: espaciado.e32 },\r\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 },\r\n  header: { marginBottom: espaciado.e24 },\r\n  body: { flex: 1, gap: espaciado.e16 },\r\n  text: { fontSize: tipografia.body, fontWeight: '600', textAlign: 'center' },\r\n  footer: { marginTop: espaciado.e20 },\r\n});\r\n","/**\n * LandlordProfileScreen — perfil público del arrendador (kit rental).\n * Carga por landlordId desde el API (GET /rental/landlords/:id) con fallback\n * al objeto pasado por params (JSON). Muestra la LandlordCard en modo detail\n * con contacto (Llamar/WhatsApp directos) + sus anuncios activos.\n * Ruta: /landlord-profile?landlordId=… (o ?landlord=JSON)\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { espaciado, ScreenHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { LandlordCard, type LandlordCardData } from '../components/rental/LandlordCard';\nimport { rentalApi, type RentalProperty } from '../api/rental';\nimport { PropertyCard } from '../components/rental/PropertyCard';\n\nexport default function LandlordProfileScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const params = useLocalSearchParams<{ landlord?: string; landlordId?: string }>();\n\n  const [landlord, setLandlord] = useState<LandlordCardData | null>(null);\n  const [properties, setProperties] = useState<RentalProperty[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const fallback = React.useMemo<LandlordCardData | null>(() => {\n    try {\n      return params.landlord ? (JSON.parse(params.landlord) as LandlordCardData) : null;\n    } catch {\n      return null;\n    }\n  }, [params.landlord]);\n\n  const load = useCallback(async () => {\n    try {\n      if (params.landlordId) {\n        const r = await rentalApi.landlordById(params.landlordId);\n        setLandlord(r.landlord);\n        setProperties(r.properties ?? []);\n      } else if (fallback) {\n        setLandlord(fallback);\n        const list = await rentalApi.properties().catch(() => [] as RentalProperty[]);\n        if (fallback.id) setProperties(list.filter((p) => p.landlord.id === fallback.id));\n      } else {\n        setError('Arrendador no encontrado');\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cargar el perfil');\n    } finally {\n      setLoading(false);\n    }\n  }, [params.landlordId, fallback]);\n\n  useEffect(() => { load(); }, [load]);\n\n  const s = styles(colors);\n  if (loading) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n  if (!landlord) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 }}>\n        <Text style={{ color: colors.danger, fontWeight: '700' }}>{error ?? 'Arrendador no encontrado'}</Text>\n        <Pressable onPress={() => router.back()} style={{ marginTop: espaciado.e12 }}><Text style={{ color: colors.primary, fontWeight: '700' }}>Volver</Text></Pressable>\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      {/* Cabecera del kit desde el 24/09/2026. Esta era la ÚNICA de las 20 cuyo botón de volver no\n          llevaba `accessibilityRole` ni etiqueta: al pasar al kit gana las dos. */}\n      <ScreenHeader\n        titulo=\"Perfil del anunciante\"\n        alVolver={() => router.back()}\n      />\n\n      <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingTop: insets.top + 16, paddingBottom: insets.bottom + 40 }} showsVerticalScrollIndicator={false}>\n        <LandlordCard\n          landlord={landlord}\n          variant=\"detail\"\n          showViewProfile={false}\n          showContactActions={true}\n        />\n\n        {/* Anuncios del arrendador */}\n        {properties.length > 0 && (\n          <View style={{ marginTop: espaciado.e20 }}>\n            <Text style={s.sectionTitle}>Anuncios de {landlord.name}</Text>\n            {properties.map((p) => (\n              <PropertyCard key={p.id} property={p} onPress={() => router.push({ pathname: '/alquiler-detalle', params: { id: p.id } } as any)} onViewLandlord={(l) => router.push({ pathname: '/landlord-profile', params: { landlordId: l.id ?? '' } } as any)} />\n            ))}\n          </View>\n        )}\n\n        {/* Nota de respuesta */}\n        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, textAlign: 'center', marginTop: espaciado.e12 }}>\n          {landlord.responseTimeHours != null ? `Tiempo medio de respuesta: ${landlord.responseTimeHours < 1 ? 'menos de 1 h' : `~${Math.round(landlord.responseTimeHours)} h`}` : ''}\n        </Text>\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  sectionTitle: { fontSize: tipografia.subtitle, fontWeight: '700', color: c.textPrimary, marginBottom: espaciado.e10 },\n});\n","/**\n * app/lifebook-ai.tsx — EL ASISTENTE DE IA (tanda M).\n *\n * DÓNDE VIVE Y POR QUÉ. El dueño quería el agente «en el hueco reservado de la barra de Life Book»\n * (el que dejó libre el avatar del dueño cuando se mudó a Mensajes). Desde ahí se abre este chat.\n *\n * QUÉ HACE: recomienda cosas REALES del catálogo (las tarjetas que enseña son productos y tiendas de\n * verdad, con su precio de verdad: se pueden abrir) y explica cómo se usa la app. Lo que no sabe lo\n * dice — si una búsqueda no devuelve nada, contesta que no hay nada.\n *\n * LO QUE NO HACE, A PROPÓSITO: no inventa precios, existencias ni plazos; no pide datos personales;\n * no compra nada por su cuenta. Y no hay que explicarlo en la pantalla: se ve en las respuestas.\n */\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, KeyboardAvoidingView, Linking, Modal, Platform, Pressable, Share, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport * as Clipboard from 'expo-clipboard';\nimport { ExpoSpeechRecognitionModule, useSpeechRecognitionEvent } from 'expo-speech-recognition';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Check, CheckSquare, Clock, Copy, Heart, Mic, MoreHorizontal, Plus, Send, Sparkles, Store, ThumbsUp, X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { pickImageFromCamera, pickImageFromLibrary, uriToBase64 } from '../core/pickImage';\nimport { absUrl } from '../api/config';\nimport { commerceApi, type LbProductCard } from '../api/commerce';\nimport { aiApi, type LbAiMensaje, type LbAiResumen, type LbAiTarjeta } from '../api/lifebookAi';\nimport { lbXaf } from '../constants/lifebook';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport default function LifebookAiScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\n/** Lo que se puede preguntar de entrada (solo cuando la conversación está vacía). */\nconst SUGERENCIAS = [\n  '¿Qué zapatillas hay?',\n  'Busca un móvil barato',\n  '¿Cómo publico algo para vender?',\n  '¿Cómo funciona el aviso de stock?',\n];\n\n/**\n * Qué se le dice a la persona cuando el dictado falla. En castellano llano: el código del error del\n * reconocedor no le sirve de nada a quien está hablando con el asistente.\n */\nfunction mensajeDeDictado(codigo: string): string {\n  switch (codigo) {\n    case 'not-allowed':\n    case 'service-not-allowed':\n      return 'Sin permiso del micrófono: puedes escribir tu pregunta.';\n    case 'no-speech':\n    case 'speech-timeout':\n      return 'No te he oído. Prueba otra vez.';\n    case 'network':\n      return 'El dictado necesita conexión y ahora mismo no la hay.';\n    case 'language-not-supported':\n      return 'Este móvil no sabe dictar en español: puedes escribir tu pregunta.';\n    case 'busy':\n      return 'El micrófono está ocupado: espera un segundo y vuelve a probar.';\n    default:\n      return 'No se pudo dictar. Puedes escribir tu pregunta.';\n  }\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const listaRef = useRef<FlatList<LbAiMensaje>>(null);\n\n  const [mensajes, setMensajes] = useState<LbAiMensaje[]>([]);\n  const [convId, setConvId] = useState<string | null>(null);\n  const [texto, setTexto] = useState('');\n  const [cargando, setCargando] = useState(true);\n  const [enviando, setEnviando] = useState(false);\n  const [noConfigurado, setNoConfigurado] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [quedan, setQuedan] = useState<number | null>(null);\n  /** Tanda N: el historial (mis conversaciones) se ve en la misma pantalla, sin otra ruta. */\n  const [modo, setModo] = useState<'chat' | 'historial' | 'consejo' | 'editar'>('chat');\n  /** Tanda N: el mensaje que se está editando (solo se pueden editar los míos). */\n  const [editandoId, setEditandoId] = useState<string | null>(null);\n  const [historico, setHistorico] = useState<LbAiResumen[]>([]);\n  const [copiado, setCopiado] = useState<string | null>(null);\n  /** Tanda N: modo selección para compartir varios mensajes a la vez. */\n  const [seleccion, setSeleccion] = useState<string[]>([]);\n  const enSeleccion = seleccion.length > 0;\n  const [aviso, setAviso] = useState<string | null>(null);\n\n  const cargar = useCallback(async () => {\n    setCargando(true);\n    try {\n      const [estado, conv] = await Promise.all([\n        aiApi.estado().catch(() => null),\n        aiApi.conversacion().catch(() => ({ conversation: null, messages: [] })),\n      ]);\n      setNoConfigurado(estado ? !estado.configured : false);\n      setQuedan(estado?.leftToday ?? null);\n      setConvId(conv.conversation?.id ?? null);\n      setMensajes(conv.messages ?? []);\n    } finally {\n      setCargando(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const enviar = useCallback(async (que?: string, extra?: { imageUrl?: string | null; productId?: string | null }) => {\n    const pregunta = (que ?? texto).trim();\n    if ((!pregunta && !extra?.imageUrl && !extra?.productId) || enviando) return;\n    setEnviando(true);\n    setError(null);\n    setTexto('');\n    // La pregunta se pinta ya, sin esperar al servidor: así el chat no parece congelado.\n    const provisional: LbAiMensaje = {\n      id: `local-${Date.now()}`, role: 'user', text: pregunta, cards: [], createdAt: new Date().toISOString(),\n    };\n    setMensajes((prev) => [...prev, provisional]);\n    try {\n      const r = await aiApi.preguntar(pregunta, convId, extra);\n      setConvId(r.conversationId);\n      setQuedan(r.leftToday);\n      /**\n       * Se RECARGA la conversación en vez de pintar la respuesta a mano: así los mensajes llevan su\n       * id de verdad, que es lo que hace falta para «me gusta» y para copiar con garantías.\n       */\n      const conv = await aiApi.conversacion(r.conversationId).catch(() => null);\n      if (conv?.messages?.length) setMensajes(conv.messages);\n      else {\n        setMensajes((prev) => [...prev, {\n          id: `r-${Date.now()}`, role: 'assistant', text: r.reply.text, cards: r.reply.cards ?? [], createdAt: new Date().toISOString(),\n        }]);\n      }\n      setTimeout(() => listaRef.current?.scrollToEnd({ animated: true }), 80);\n    } catch (e) {\n      const m = e instanceof Error ? e.message : 'No se pudo preguntar';\n      setError(m);\n      if (/configurad|clave/i.test(m)) setNoConfigurado(true);\n    } finally {\n      setEnviando(false);\n    }\n  }, [texto, enviando, convId]);\n\n  /* ── DICTAR: la voz se convierte en texto EN EL MÓVIL ────────────────────────────────────────\n   *\n   * POR QUÉ ASÍ: la API de DeepSeek no acepta audio, así que se dicta con el reconocimiento de voz\n   * de Android (en español) y Cucucul recibe TEXTO, igual que si se hubiera escrito. El texto cae en\n   * el campo de escribir y se envía con el botón de siempre: no se envía solo, porque mandar media\n   * frase a medio dictar es justo lo que no quiere nadie.\n   *\n   * EN ESTA VÍA NO SE GUARDA EL AUDIO: no hay burbuja de audio, sólo texto.\n   *\n   * SI NO SE PUEDE (permiso denegado, móvil sin reconocedor, sin red), se dice y se sigue pudiendo\n   * escribir: nunca un botón muerto.\n   */\n  const [escuchando, setEscuchando] = useState(false);\n  /** Lo que ya estaba escrito antes de empezar: el dictado se AÑADE a eso, no lo borra. */\n  const baseDictado = useRef('');\n\n  useSpeechRecognitionEvent('result', (e) => {\n    const trozo = (e.results?.[0]?.transcript ?? '').trim();\n    if (!trozo) return;\n    const unido = baseDictado.current ? `${baseDictado.current} ${trozo}` : trozo;\n    setTexto(unido);\n    // Un resultado final ya no se reemplaza: pasa a ser la base del trozo siguiente del dictado.\n    if (e.isFinal) baseDictado.current = unido;\n  });\n\n  useSpeechRecognitionEvent('error', (e) => {\n    setEscuchando(false);\n    // Parar a propósito no es un fallo: no se le enseña nada a la persona.\n    if (e.error === 'aborted') return;\n    setError(mensajeDeDictado(e.error));\n  });\n\n  useSpeechRecognitionEvent('end', () => setEscuchando(false));\n\n  /** Al salir de la pantalla se apaga el micrófono: si no, seguiría escuchando por detrás. */\n  useEffect(() => () => {\n    try { ExpoSpeechRecognitionModule.abort(); } catch { /* no estaba escuchando: nada que hacer */ }\n  }, []);\n\n  const dictar = useCallback(async () => {\n    if (escuchando) { ExpoSpeechRecognitionModule.stop(); return; }\n    try {\n      if (!ExpoSpeechRecognitionModule.isRecognitionAvailable()) {\n        setError('Este móvil no sabe dictar: puedes escribir tu pregunta.');\n        return;\n      }\n      const permiso = await ExpoSpeechRecognitionModule.getPermissionsAsync();\n      const concedido = permiso.granted\n        || (await ExpoSpeechRecognitionModule.requestPermissionsAsync()).granted;\n      if (!concedido) {\n        Alert.alert(\n          'Micrófono',\n          'Para dictar hace falta el micrófono. Puedes escribir tu pregunta igual.',\n          [\n            { text: 'Escribir', style: 'cancel' },\n            { text: 'Ajustes', onPress: () => { void Linking.openSettings(); } },\n          ],\n        );\n        return;\n      }\n      setError(null);\n      baseDictado.current = texto.trim();\n      ExpoSpeechRecognitionModule.start({\n        lang: 'es-ES',\n        interimResults: true,\n        continuous: true,\n        addsPunctuation: true,\n        androidIntentOptions: { EXTRA_LANGUAGE_MODEL: 'free_form' },\n      });\n      setEscuchando(true);\n    } catch {\n      setEscuchando(false);\n      setError('No se pudo empezar a dictar. Puedes escribir tu pregunta.');\n    }\n  }, [escuchando, texto]);\n\n  const nueva = useCallback(async () => {\n    try {\n      const c = await aiApi.nueva();\n      setConvId(c.conversation?.id ?? null);\n      setMensajes([]);\n      setError(null);\n      setModo('chat');\n    } catch { /* si falla, se sigue en la conversación actual */ }\n  }, []);\n\n  /** Tanda N: copiar una respuesta (al portapapeles, con un aviso breve). */\n  const copiar = async (m: LbAiMensaje) => {\n    try {\n      await Clipboard.setStringAsync(m.text);\n      setCopiado(m.id);\n      setTimeout(() => setCopiado((c) => (c === m.id ? null : c)), 1600);\n    } catch { setError('No se pudo copiar'); }\n  };\n\n  /** Tanda N: «me gusta» a una respuesta del asistente (señal privada). */\n  const gustar = async (m: LbAiMensaje) => {\n    const antes = !!m.liked;\n    setMensajes((prev) => prev.map((x) => (x.id === m.id ? { ...x, liked: !antes } : x)));\n    try {\n      const r = await aiApi.meGusta(m.id, !antes);\n      setMensajes((prev) => prev.map((x) => (x.id === m.id ? { ...x, liked: r.liked } : x)));\n    } catch {\n      // Si no se pudo guardar, se quita la marca: no se enseña un «me gusta» que no existe.\n      setMensajes((prev) => prev.map((x) => (x.id === m.id ? { ...x, liked: antes } : x)));\n      setError('No se pudo guardar tu me gusta');\n    }\n  };\n\n  /**\n   * Tanda N: mandar un consejo para mejorar a Cucucul.\n   *\n   * OJO: aquí NO se usa `Alert.prompt`, porque **no existe en Android** (es solo de iOS) y el botón\n   * habría quedado muerto en el móvil de verdad. En su lugar se cambia la barra de escribir por una\n   * de consejo: el texto se escribe igual, pero se envía como consejo.\n   */\n  const enviarConsejo = async (texto: string) => {\n    const limpio = texto.trim();\n    if (limpio.length < 3) return;\n    try {\n      await aiApi.consejo(limpio, 'mejora');\n      setModo('chat');\n      setTexto('');\n      setAviso('Gracias: tu consejo queda apuntado.');\n      setTimeout(() => setAviso(null), 2500);\n    } catch {\n      setAviso('No se pudo enviar tu consejo.');\n      setTimeout(() => setAviso(null), 2500);\n    }\n  };\n\n  /** Tanda N: abrir el historial y volver a una conversación. */\n  const abrirHistorial = useCallback(async () => {\n    setModo('historial');\n    try {\n      const r = await aiApi.conversaciones();\n      setHistorico(r.conversations ?? []);\n    } catch { setHistorico([]); }\n  }, []);\n\n  const abrirConversacion = useCallback(async (id: string) => {\n    try {\n      const c = await aiApi.conversacion(id);\n      setConvId(id);\n      setMensajes(c.messages ?? []);\n      setModo('chat');\n    } catch { setError('No se pudo abrir esa conversación'); }\n  }, []);\n\n  /**\n   * Tanda N: acciones sobre MIS mensajes (mantener pulsado).\n   *\n   * `Alert.alert` con botones SÍ funciona en Android (lo que no existe es `Alert.prompt`), así que el\n   * menú es una alerta normal: Editar, Eliminar o Cancelar.\n   */\n  const menuMensaje = (m: LbAiMensaje) => {\n    if (m.role !== 'user') return;\n    Alert.alert('Tu mensaje', m.text.slice(0, 90), [\n      {\n        text: 'Editar',\n        onPress: () => { setEditandoId(m.id); setTexto(m.text); setModo('editar'); },\n      },\n      {\n        text: 'Eliminar',\n        style: 'destructive',\n        onPress: async () => {\n          const antes = mensajes;\n          setMensajes((prev) => prev.filter((x) => x.id !== m.id));\n          try { await aiApi.borrarMensaje(m.id); }\n          catch { setMensajes(antes); setError('No se pudo eliminar el mensaje'); }\n        },\n      },\n      { text: 'Cancelar', style: 'cancel' },\n    ]);\n  };\n\n  /** Guardar la edición de un mensaje mío. */\n  const guardarEdicion = async (nuevo: string) => {\n    const limpio = nuevo.trim();\n    if (!limpio || !editandoId) { setModo('chat'); setEditandoId(null); setTexto(''); return; }\n    const antes = mensajes;\n    setMensajes((prev) => prev.map((x) => (x.id === editandoId ? { ...x, text: limpio } : x)));\n    setModo('chat');\n    setTexto('');\n    try { await aiApi.editarMensaje(editandoId, limpio); }\n    catch { setMensajes(antes); setError('No se pudo editar el mensaje'); }\n    finally { setEditandoId(null); }\n  };\n\n  /** Tanda N: adjuntar (foto o un producto guardado). */\n  const [guardados, setGuardados] = useState<LbProductCard[]>([]);\n  const [eligiendo, setEligiendo] = useState(false);\n\n  const mandarFoto = async (deCamara: boolean) => {\n    try {\n      const img = deCamara ? await pickImageFromCamera() : await pickImageFromLibrary();\n      if (!img?.uri) return;\n      const b64 = await uriToBase64(img.uri);\n      if (!b64) { setError('No se pudo leer la foto'); return; }\n      await enviar('Mira esta foto', { imageUrl: `data:image/jpeg;base64,${b64}` });\n    } catch {\n      setError('No se pudo usar la foto');\n    }\n  };\n\n  const abrirAdjuntar = () => {\n    Alert.alert('Adjuntar', undefined, [\n      { text: 'Hacer foto', onPress: () => { void mandarFoto(true); } },\n      { text: 'Elegir de la galería', onPress: () => { void mandarFoto(false); } },\n      {\n        text: 'Un producto que me gusta',\n        onPress: async () => {\n          try {\n            const r = await commerceApi.mySaved();\n            const lista = r.items ?? [];\n            if (!lista.length) { setError('Todavía no has guardado ningún producto.'); return; }\n            setGuardados(lista);\n            setEligiendo(true);\n          } catch { setError('No se pudieron cargar tus productos guardados'); }\n        },\n      },\n      { text: 'Cancelar', style: 'cancel' },\n    ]);\n  };\n\n  /** Tanda N: marcar o desmarcar un mensaje para compartir varios a la vez. */\n  const alternar = (id: string) => setSeleccion((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));\n\n  /** Compartir lo seleccionado con la hoja del sistema (como texto legible). */\n  const compartir = async () => {\n    const textos = mensajes\n      .filter((m) => seleccion.includes(m.id))\n      .map((m) => `${m.role === 'user' ? 'Yo' : 'Cucucul'}: ${m.text}${m.cards?.length ? `\\n(adjunto: ${m.cards.map((x) => x.titulo).join(', ')})` : ''}`);\n    if (!textos.length) { setSeleccion([]); return; }\n    try {\n      await Share.share({ message: textos.join('\\n\\n') });\n    } catch { setError('No se pudo compartir'); }\n    setSeleccion([]);\n  };\n  const abrir = (t: LbAiTarjeta) => {\n    if (t.tipo === 'producto') { irSeguro.libre('/lifebook-product/[id]', { id: t.id }); return; }\n    irSeguro.libre('/lifebook-shop/[id]', { id: t.id });\n  };\n\n  const Burbuja = ({ m }: { m: LbAiMensaje }) => {\n    const mio = m.role === 'user';\n    return (\n      <View style={{ alignItems: mio ? 'flex-end' : 'flex-start', marginBottom: espaciado.e10 }}>\n        <Pressable\n          onPress={() => { if (enSeleccion) alternar(m.id); }}\n          onLongPress={() => menuMensaje(m)}\n          delayLongPress={300}\n          accessibilityLabel={mio ? 'Tu mensaje: mantén pulsado para editar o eliminar' : 'Respuesta de Cucucul'}\n          style={[\n          styles.burbuja,\n          mio\n            ? { backgroundColor: colors.primary, borderBottomRightRadius: 6 }\n            : { backgroundColor: colors.surface, borderBottomLeftRadius: 6, borderWidth: StyleSheet.hairlineWidth, borderColor: alpha(colors.border, 0.8) },\n        ]}>\n          <Text style={{ color: mio ? brand.white : colors.textPrimary, fontSize: tipografia.body, lineHeight: 19 }}>{m.text}</Text>\n        </Pressable>\n        {m.cards?.length ? (          <View style={{ marginTop: espaciado.e8, gap: espaciado.e8, alignSelf: 'stretch' }}>\n            {m.cards.map((t) => (\n              <Pressable\n                key={`${t.tipo}:${t.id}`}\n                onPress={() => abrir(t)}\n                accessibilityLabel={`Abrir ${t.titulo}`}\n                style={[styles.tarjeta, { backgroundColor: colors.surface, borderColor: alpha(colors.border, 0.8) }]}\n              >\n                {t.fotoUrl ? (\n                  <Image source={absUrl(t.fotoUrl)} style={t.tipo === 'foto' ? styles.fotoGrande : styles.foto} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                ) : (\n                  <View style={[styles.foto, { backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }]}>\n                    <Store size={18} color={colors.primary} />\n                  </View>\n                )}\n                <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                  <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{t.titulo}</Text>\n                  <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                    {[t.subtitulo, t.ciudad].filter(Boolean).join(' · ')}\n                  </Text>\n                  {t.precioXaf !== null && t.precioXaf !== undefined ? (\n                    <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e3 }}>{lbXaf(t.precioXaf)}</Text>\n                  ) : null}\n                </View>\n              </Pressable>\n            ))}\n          </View>\n        ) : null}\n\n        {/* Tanda N — lo que se puede hacer con una RESPUESTA: copiarla y darle me gusta. */}\n        {!mio ? (\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e14, marginTop: espaciado.e6, marginLeft: espaciado.e4 }}>\n            <Pressable onPress={() => { void copiar(m); }} accessibilityLabel=\"Copiar la respuesta\" hitSlop={8}\n              style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\n              {copiado === m.id\n                ? <><Check size={14} color={colors.success} /><Text style={{ color: colors.success, fontSize: tipografia.caption, fontWeight: '700' }}>Copiado</Text></>\n                : <><Copy size={14} color={colors.textSecondary} /><Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>Copiar</Text></>}\n            </Pressable>\n            <Pressable onPress={() => { void gustar(m); }} accessibilityLabel={m.liked ? 'Quitar me gusta' : 'Me gusta'}\n              accessibilityState={{ selected: !!m.liked }} hitSlop={8}\n              style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\n              <Heart size={14} color={m.liked ? brand.like : colors.textSecondary} fill={m.liked ? brand.like : 'none'} />\n              <Text style={{ color: m.liked ? brand.like : colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                {m.liked ? 'Te gustó' : 'Me gusta'}\n              </Text>\n            </Pressable>\n          </View>\n        ) : null}\n      </View>\n    );\n  };\n\n  return (\n    <KeyboardAvoidingView style={{ flex: 1, backgroundColor: colors.background }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n      {/* ── Cabecera ── */}\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <X size={20} color={colors.textPrimary} />\n        </Pressable>\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e7, flex: 1, marginLeft: espaciado.e10 }}>\n          <Sparkles size={17} color={colors.primary} />\n          <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>Cucucul</Text>\n        </View>\n        {quedan !== null ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginRight: espaciado.e12 }}>{quedan} hoy</Text>\n        ) : null}\n        {/* Historial y consejos: dos accesos pequeños, sin ruido. */}\n        {/* Tanda N: un solo menú para lo secundario (consejos y selección). Antes eran dos iconos más\n            y la cabecera se quedaba sin sitio: «Nueva conversación» quedaba apretado contra el borde. */}\n        <Pressable\n          onPress={() => Alert.alert('Más', undefined, [\n            { text: 'Dar un consejo', onPress: () => setModo(modo === 'consejo' ? 'chat' : 'consejo') },\n            {\n              text: 'Seleccionar mensajes',\n              onPress: () => { if (enSeleccion) setSeleccion([]); else setSeleccion([mensajes[mensajes.length - 1]?.id ?? '']); },\n            },\n            { text: 'Cancelar', style: 'cancel' },\n          ])}\n          hitSlop={10}\n          accessibilityLabel=\"Más opciones\"\n          style={{ marginRight: espaciado.e12 }}\n        >\n          <MoreHorizontal size={20} color={modo === 'consejo' ? colors.primary : colors.textPrimary} />\n        </Pressable>        <Pressable onPress={() => { void abrirHistorial(); }} hitSlop={10} accessibilityLabel=\"Historial de conversaciones\" style={{ marginRight: espaciado.e14 }}>\n          <Clock size={19} color={colors.textPrimary} />\n        </Pressable>\n\n        {/* ABRIR OTRA LÍNEA DE CONVERSACIÓN (lo pidió el dueño): con etiqueta, no un icono suelto.\n            La conversación anterior NO se pierde: queda en el historial (🕐). */}\n        <Pressable\n          onPress={() => { void nueva(); }}\n          hitSlop={10}\n          accessibilityLabel=\"Abrir otra conversación\"\n          style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, borderWidth: 1, borderColor: colors.primary, borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5 }}\n        >\n          <Plus size={15} color={colors.primary} />\n          <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '900' }}>Nueva</Text>\n        </Pressable>\n      </View>\n\n      {cargando ? (\n        <View style={styles.centro}><ActivityIndicator color={colors.primary} /></View>\n      ) : modo === 'historial' ? (\n        /* ── Tanda N: EL HISTORIAL (mis conversaciones, la última primero) ── */\n        <FlatList\n          data={historico}\n          keyExtractor={(c) => c.id}\n          contentContainerStyle={{ padding: espaciado.e14, flexGrow: 1 }}\n          ListEmptyComponent={<Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', marginTop: espaciado.e30 }}>Todavía no hay conversaciones.</Text>}\n          renderItem={({ item }) => (\n            <Pressable\n              onPress={() => { void abrirConversacion(item.id); }}\n              accessibilityLabel={`Abrir ${item.title}`}\n              style={[styles.tarjeta, { backgroundColor: colors.surface, borderColor: alpha(colors.border, 0.8), marginBottom: espaciado.e8 }]}\n            >\n              <View style={{ flex: 1 }}>\n                <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{item.title}</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>\n                  {item.messages} mensaje{item.messages === 1 ? '' : 's'} · {String(item.updatedAt).slice(0, 10)}\n                </Text>\n              </View>\n              <Pressable\n                onPress={async () => {\n                  try { await aiApi.borrarConversacion(item.id); setHistorico((h) => h.filter((x) => x.id !== item.id)); }\n                  catch { setError('No se pudo borrar la conversación'); }\n                }}\n                hitSlop={10}\n                accessibilityLabel={`Borrar ${item.title}`}\n                style={{ padding: espaciado.e8 }}\n              >\n                <X size={16} color={colors.danger} />\n              </Pressable>\n            </Pressable>\n          )}\n        />\n      ) : (\n        <FlatList\n          ref={listaRef}\n          data={mensajes}\n          keyExtractor={(m) => m.id}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: espaciado.e20, flexGrow: 1 }}\n          renderItem={({ item }) => <Burbuja m={item} />}\n          ListEmptyComponent={(\n            <View style={{ flex: 1, justifyContent: 'center' }}>\n              {noConfigurado ? (\n                <View style={[styles.aviso, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.3) }]}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 19, fontWeight: '700' }}>\n                    El asistente todavía no está encendido: falta la clave del servicio de IA en el servidor.\n                  </Text>\n                </View>\n              ) : (\n                <>\n                  <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}>\n                    ¿Qué buscas?\n                  </Text>\n                  <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, justifyContent: 'center', marginTop: espaciado.e14 }}>\n                    {SUGERENCIAS.map((s) => (\n                      <Pressable\n                        key={s}\n                        onPress={() => { void enviar(s); }}\n                        accessibilityLabel={s}\n                        style={[styles.sugerencia, { borderColor: alpha(colors.primary, 0.5), backgroundColor: alpha(colors.primary, 0.06) }]}\n                      >\n                        <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700' }}>{s}</Text>\n                      </Pressable>\n                    ))}\n                  </View>\n                </>\n              )}\n            </View>\n          )}\n        />\n      )}\n\n      {error ? (\n        <Text style={{ color: colors.danger, fontSize: tipografia.caption, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e6 }}>{error}</Text>\n      ) : null}\n\n      {/* Tanda N: barra de SELECCIÓN (solo cuando hay algo marcado). */}\n      {enSeleccion ? (\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e8 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', flex: 1 }}>\n            {seleccion.length} seleccionado{seleccion.length === 1 ? '' : 's'}\n          </Text>\n          <Pressable onPress={() => { void compartir(); }} accessibilityLabel=\"Compartir lo seleccionado\"\n            style={{ backgroundColor: colors.primary, borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e9 }}>\n            <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>Compartir</Text>\n          </Pressable>\n          <Pressable onPress={() => setSeleccion([])} accessibilityLabel=\"Cancelar la selección\">\n            <Text style={{ color: colors.textSecondary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\n          </Pressable>\n        </View>\n      ) : null}\n      {/* ── Escribir (o el consejo: la misma barra, otro destino) ── */}\n      {aviso ? (\n        <Text style={{ color: colors.success, fontSize: tipografia.caption, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e4 }}>{aviso}</Text>\n      ) : null}\n      {modo === 'consejo' ? (\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e4 }}>\n          Tu consejo para Cucucul\n        </Text>\n      ) : null}\n      <View style={[styles.barra, { paddingBottom: insets.bottom + 8, borderTopColor: alpha(colors.border, 0.6), backgroundColor: colors.background }]}>\n        {/* Tanda N: adjuntar foto o un producto que te gusta. */}\n        <Pressable\n          onPress={abrirAdjuntar}\n          disabled={enviando}\n          accessibilityLabel=\"Adjuntar una foto o un producto\"\n          style={[styles.adjuntar, { borderColor: alpha(colors.primary, 0.5), backgroundColor: alpha(colors.primary, 0.06) }]}\n        >\n          <Plus size={18} color={colors.primary} />\n        </Pressable>\n        <TextInput\n          value={texto}\n          onChangeText={(t) => {\n            setTexto(t);\n            // Si se escribe a mano mientras se dicta, el dictado sigue a partir de lo escrito.\n            if (escuchando) baseDictado.current = t.trim();\n          }}\n          placeholder={escuchando ? 'Te escucho' : modo === 'consejo' ? 'Qué debería hacer mejor' : 'Escribe aquí'}\n          placeholderTextColor={colors.textSecondary}\n          multiline\n          style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n        />\n        {/* DICTAR: un toque empieza, otro para. El texto se escribe solo en el campo de arriba. */}\n        <Pressable\n          onPress={() => { void dictar(); }}\n          disabled={enviando}\n          accessibilityLabel={escuchando ? 'Parar de dictar' : 'Dictar con la voz'}\n          accessibilityState={{ selected: escuchando }}\n          style={[styles.micro, escuchando\n            ? { backgroundColor: colors.danger, borderColor: colors.danger }\n            : { borderColor: alpha(colors.primary, 0.5), backgroundColor: alpha(colors.primary, 0.06) }]}\n        >\n          <Mic size={18} color={escuchando ? brand.white : colors.primary} />\n        </Pressable>\n        <Pressable\n          onPress={() => {\n            /**\n             * Si se manda mientras se dicta, se CORTA el dictado en seco (`abort`, no `stop`): con\n             * `stop` llegaría un resultado final un instante después y volvería a escribir en el\n             * campo ya enviado. Con `abort` no hay resultado tardío, y lo que se manda es justo lo\n             * que se está viendo escrito.\n             */\n            if (escuchando) { ExpoSpeechRecognitionModule.abort(); baseDictado.current = ''; }\n            if (modo === 'consejo') { void enviarConsejo(texto); return; }\n            if (modo === 'editar') { void guardarEdicion(texto); return; }\n            void enviar();\n          }}\n          disabled={enviando || !texto.trim()}\n          accessibilityLabel={modo === 'consejo' ? 'Enviar el consejo' : modo === 'editar' ? 'Guardar el cambio' : 'Enviar'}\n          style={[styles.enviar, { backgroundColor: enviando || !texto.trim() ? alpha(colors.primary, 0.4) : colors.primary }]}\n        >\n          {enviando ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Send size={17} color={brand.white} />}\n        </Pressable>\n      </View>\n      {/* Tanda N: elegir UN producto de los que te gustan y mandarlo como tarjeta embebida. */}\n      <Modal visible={eligiendo} transparent animationType=\"slide\" onRequestClose={() => setEligiendo(false)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' }} onPress={() => setEligiendo(false)}>\n          <Pressable style={{ backgroundColor: colors.background, borderTopLeftRadius: 18, borderTopRightRadius: 18, padding: espaciado.e16, paddingBottom: insets.bottom + 16 }} onPress={() => { /* dentro no cierra */ }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15, marginBottom: espaciado.e10 }}>Productos que te gustan</Text>\n            <FlatList\n              data={guardados}\n              keyExtractor={(p) => p.id}\n              style={{ maxHeight: 380 }}\n              renderItem={({ item }) => (\n                <Pressable\n                  onPress={() => { setEligiendo(false); void enviar('Mira este producto', { productId: item.id }); }}\n                  accessibilityLabel={`Enviar ${item.title}`}\n                  style={[styles.tarjeta, { backgroundColor: colors.surface, borderColor: alpha(colors.border, 0.8), marginBottom: espaciado.e8 }]}\n                >\n                  {item.coverUrl ? (\n                    <Image source={absUrl(item.coverUrl)} style={styles.foto} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                  ) : (\n                    <View style={[styles.foto, { backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }]}>\n                      <Store size={18} color={colors.primary} />\n                    </View>\n                  )}\n                  <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                    <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{item.title}</Text>\n                    {item.priceXaf !== null && item.priceXaf !== undefined ? (\n                      <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e3 }}>{lbXaf(item.priceXaf)}</Text>\n                    ) : null}\n                  </View>\n                </Pressable>\n              )}\n            />\n          </Pressable>\n        </Pressable>\n      </Modal>\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  burbuja: { maxWidth: '86%', borderRadius: radios.lg, paddingHorizontal: espaciado.e13, paddingVertical: espaciado.e10 },\n  tarjeta: {\n    flexDirection: 'row', alignItems: 'center', borderWidth: StyleSheet.hairlineWidth,\n    borderRadius: 14, padding: espaciado.e9,\n  },\n  foto: { width: 54, height: 54, borderRadius: 10 },\n  aviso: { borderWidth: 1, borderRadius: 14, padding: espaciado.e14 },\n  sugerencia: { borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e13, paddingVertical: espaciado.e9 },\n  input: {\n    flex: 1, maxHeight: 110, borderWidth: 1, borderRadius: radios.md,\n    paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9, fontSize: tipografia.body,\n  },\n  barra: {\n    flexDirection: 'row', alignItems: 'flex-end', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingTop: espaciado.e8,\n    borderTopWidth: StyleSheet.hairlineWidth,\n  },\n  enviar: { width: 44, height: 44, borderRadius: 22, alignItems: 'center', justifyContent: 'center' },\n  /** El botón de adjuntar: al lado de la barra de escribir. */\n  adjuntar: { width: 44, height: 44, borderRadius: 22, borderWidth: 1, alignItems: 'center', justifyContent: 'center' },\n  /** El micro (dictado): mismo tamaño que los otros dos botones de la barra. */\n  micro: { width: 44, height: 44, borderRadius: 22, borderWidth: 1, alignItems: 'center', justifyContent: 'center' },\n  /** La foto que manda la persona: se ve grande, que es lo suyo. */\n  fotoGrande: { width: 190, height: 190, borderRadius: radios.md },\n});\n","import { UnavailabilityError, Platform } from 'expo-modules-core';\nimport { ClipboardPasteButton } from './ClipboardPasteButton';\nimport ExpoClipboard from './ExpoClipboard';\nconst onClipboardEventName = 'onClipboardChanged';\n/**\n * Gets the content of the user's clipboard. Calling this method on web will prompt\n * the user to grant your app permission to \"see text and images copied to the clipboard.\"\n *\n * @param options Options for the clipboard content to be retrieved.\n * @returns A promise that resolves to the content of the clipboard.\n */\nexport async function getStringAsync(options = {}) {\n    if (!ExpoClipboard.getStringAsync) {\n        throw new UnavailabilityError('Clipboard', 'getStringAsync');\n    }\n    return await ExpoClipboard.getStringAsync(options);\n}\n/**\n * Sets the content of the user's clipboard.\n *\n * @param text The string to save to the clipboard.\n * @param options Options for the clipboard content to be set.\n * @returns On web, this returns a promise that fulfills to a boolean value indicating whether or not\n * the string was saved to the user's clipboard. On iOS and Android, the promise always resolves to `true`.\n */\nexport async function setStringAsync(text, options = {}) {\n    if (!ExpoClipboard.setStringAsync) {\n        throw new UnavailabilityError('Clipboard', 'setStringAsync');\n    }\n    return ExpoClipboard.setStringAsync(text, options);\n}\n/**\n * Sets the content of the user's clipboard.\n * @deprecated Use [`setStringAsync()`](#setstringasynctext-options) instead.\n *\n * @returns On web, this returns a boolean value indicating whether or not the string was saved to\n * the user's clipboard. On iOS and Android, nothing is returned.\n */\nexport function setString(text) {\n    if (Platform.OS === 'web') {\n        // on web, we need to return legacy method,\n        // because of different return type\n        return ExpoClipboard.setString(text);\n    }\n    else {\n        setStringAsync(text);\n    }\n}\n/**\n * Returns whether the clipboard has text content. Returns true for both plain text and rich text (e.g. HTML).\n *\n * On web, this requires the user to grant your app permission to _\"see text and images copied to the clipboard\"_.\n *\n * @returns A promise that fulfills to `true` if clipboard has text content, resolves to `false` otherwise.\n */\nexport function hasStringAsync() {\n    if (!ExpoClipboard.hasStringAsync) {\n        throw new UnavailabilityError('Clipboard', 'hasStringAsync');\n    }\n    return ExpoClipboard.hasStringAsync();\n}\n/**\n * Gets the URL from the user's clipboard.\n *\n * @returns A promise that fulfills to the URL in the clipboard.\n * @platform ios\n */\nexport async function getUrlAsync() {\n    if (!ExpoClipboard.getUrlAsync) {\n        throw new UnavailabilityError('Clipboard', 'getUrlAsync');\n    }\n    return await ExpoClipboard.getUrlAsync();\n}\n/**\n * Sets a URL in the user's clipboard.\n *\n * This function behaves the same as [`setStringAsync()`](#setstringasynctext-options), except that\n * it sets the clipboard content type to be a URL. It lets your app or other apps know that the\n * clipboard contains a URL and behave accordingly.\n *\n * @param url The URL to save to the clipboard.\n * @platform ios\n */\nexport async function setUrlAsync(url) {\n    if (!ExpoClipboard.setUrlAsync) {\n        throw new UnavailabilityError('Clipboard', 'setUrlAsync');\n    }\n    return ExpoClipboard.setUrlAsync(url);\n}\n/**\n * Returns whether the clipboard has a URL content.\n *\n * @returns A promise that fulfills to `true` if clipboard has URL content, resolves to `false` otherwise.\n * @platform ios\n */\nexport async function hasUrlAsync() {\n    if (!ExpoClipboard.hasUrlAsync) {\n        throw new UnavailabilityError('Clipboard', 'hasUrlAsync');\n    }\n    return await ExpoClipboard.hasUrlAsync();\n}\n/**\n * Gets the image from the user's clipboard and returns it in the specified\n * format. Calling this method on web will prompt the user to grant your app\n * permission to \"see text and images copied to the clipboard.\"\n *\n * @param options A `GetImageOptions` object to specify the desired format of the image.\n * @returns If there was an image in the clipboard, the promise resolves to\n * a [`ClipboardImage`](#clipboardimage) object containing the base64 string and metadata of the image.\n * Otherwise, it resolves to `null`.\n *\n * @example\n * ```tsx\n * const img = await Clipboard.getImageAsync({ format: 'png' });\n * // ...\n * <Image source={{ uri: img?.data }} style={{ width: 200, height: 200 }} />\n * ```\n */\nexport async function getImageAsync(options) {\n    if (!ExpoClipboard.getImageAsync) {\n        throw new UnavailabilityError('Clipboard', 'getImageAsync');\n    }\n    return await ExpoClipboard.getImageAsync(options);\n}\n/**\n * Sets an image in the user's clipboard.\n *\n * @param base64Image Image encoded as a base64 string, without MIME type.\n *\n * @example\n * ```tsx\n * const result = await ImagePicker.launchImageLibraryAsync({\n *   mediaTypes: ImagePicker.MediaTypeOptions.Images,\n *   base64: true,\n * });\n * await Clipboard.setImageAsync(result.base64);\n * ```\n */\nexport async function setImageAsync(base64Image) {\n    if (!ExpoClipboard.setImageAsync) {\n        throw new UnavailabilityError('Clipboard', 'setImageAsync');\n    }\n    return ExpoClipboard.setImageAsync(base64Image);\n}\n/**\n * Returns whether the clipboard has an image content.\n *\n * On web, this requires the user to grant your app permission to _\"see text and images copied to the clipboard\"_.\n *\n * @returns A promise that fulfills to `true` if clipboard has image content, resolves to `false` otherwise.\n */\nexport async function hasImageAsync() {\n    if (!ExpoClipboard.hasImageAsync) {\n        throw new UnavailabilityError('Clipboard', 'hasImageAsync');\n    }\n    return ExpoClipboard.hasImageAsync();\n}\n/**\n * Adds a listener that will fire whenever the content of the user's clipboard changes. This method\n * is a no-op on Web.\n *\n * @param listener Callback to execute when listener is triggered. The callback is provided a\n * single argument that is an object containing information about clipboard contents.\n *\n * @example\n * ```typescript\n * Clipboard.addClipboardListener(({ contentTypes }: ClipboardEvent) => {\n *   if (contentTypes.includes(Clipboard.ContentType.PLAIN_TEXT)) {\n *     Clipboard.getStringAsync().then(content => {\n *       alert('Copy pasta! Here\\'s the string that was copied: ' + content)\n *     });\n *   } else if (contentTypes.includes(Clipboard.ContentType.IMAGE)) {\n *     alert('Yay! Clipboard contains 