lean;\n  fileSystemLocation: string;\n  httpServerLocation: string;\n  width?: number;\n  height?: number;\n  scales: Array<number>;\n  hash: string;\n  name: string;\n  type: string;\n};\n\nconst svgDataUriPattern = /^(data:image\\/svg\\+xml;utf8,)(.*)/;\n\n// Based on that function: https://github.com/necolas/react-native-web/blob/54c14d64dabd175e8055e1dc92e9196c821f9b7d/packages/react-native-web/src/exports/Image/index.js#L118-L156\nexport function resolveAssetUri(\n  source?: RNImageProps['source'] | string | number\n): Partial<ImageResolvedAssetSource> | null {\n  let src: Partial<ImageResolvedAssetSource> = {};\n  if (typeof source === 'number') {\n    // get the URI from the packager\n    const asset: PackagerAsset | null = getAssetByID(source);\n    if (asset == null) {\n      throw new Error(\n        `Image: asset with ID \"${source}\" could not be found. Please check the image source or packager.`\n      );\n    }\n    src = {\n      width: asset.width,\n      height: asset.height,\n      scale: asset.scales[0],\n    };\n    if (asset.scales.length > 1) {\n      const preferredScale = PixelRatio.get();\n      // Get the scale which is closest to the preferred scale\n      src.scale = asset.scales.reduce((prev, curr) =>\n        Math.abs(curr - preferredScale) < Math.abs(prev - preferredScale)\n          ? curr\n          : prev\n      );\n    }\n    const scaleSuffix = src.scale !== 1 ? `@${src.scale}x` : '';\n    src.uri = asset\n      ? `${asset.httpServerLocation}/${asset.name}${scaleSuffix}.${asset.type}`\n      : '';\n  } else if (typeof source === 'string') {\n    src.uri = source;\n  } else if (\n    source &&\n    !Array.isArray(source) &&\n    typeof source.uri === 'string'\n  ) {\n    src.uri = source.uri;\n  }\n\n  if (src.uri) {\n    const match = src?.uri?.match(svgDataUriPattern);\n    // inline SVG markup may contain characters (e.g., #, \") that need to be escaped\n    if (match) {\n      const [, prefix, svg] = match;\n      const encodedSvg = encodeURIComponent(svg);\n      src.uri = `${prefix}${encodedSvg}`;\n      return src;\n    }\n  }\n  return src;\n}\n","export function isString (variable) {\n  return typeof variable === 'string'\n}\n\nexport function isUrlString (variable) {\n  return isString(variable) && variable.startsWith('http')\n}\n","/**\n * LocationPickerSheet — Parte 24 (G2): compartir una UBICACIÓN en el chat.\n *\n * Dos caminos, como pidió el diseño:\n *  · **Mi ubicación** → GPS (`expo-location`) + el geocoder inverso real del\n *    mirror para poner el nombre de la calle o del lugar.\n *  · **Buscar sitio** → el mismo buscador de calles/avenidas/POIs que usa\n *    «Crear ruta» (`api/geocode.ts`), con resultados reales de Malabo y Bata.\n *\n * Devuelve `{ label, lat, lng }` y el chat lo envía como `kind='location'`\n * (el servidor valida el rango de las coordenadas y exige la etiqueta).\n */\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Crosshair, MapPin, Radio, Search, X } from 'lucide-react-native';\nimport * as Location from 'expo-location';\nimport { geocode, pickReverseLabel, reverseGeocode, type GeoPlace } from '../../api/geocode';\nimport { LB_PLACE_KIND_LABEL } from '../../constants/lifebook';\nimport { formaHoja } from './ui/Sheet';\n\nexport interface LbPickedLocation {\n  label: string;\n  lat: number;\n  lng: number;\n}\n\ninterface Props {\n  visible: boolean;\n  onClose: () => void;\n  /** Envía la ubicación al chat (el padre la manda como mensaje `location`). */\n  onSubmit: (loc: LbPickedLocation) => void;\n  /** Compartir mi ubicación en vivo durante la ruta (Fase G4: aún no existe). */\n  isGroup?: boolean;\n  /** Título de la hoja (la quedada la reutiliza con otro texto). */\n  title?: string;\n  /** Texto del botón de GPS. */\n  myLocationLabel?: string;\n  /** Parte 28 (G4): compartir la ubicación EN VIVO durante la ruta. */\n  onLive?: () => void;\n}\n\nexport function LocationPickerSheet({ visible, onClose, onSubmit, title, myLocationLabel, onLive }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [query, setQuery] = useState('');\n  const [results, setResults] = useState<GeoPlace[] | null>(null);\n  const [searching, setSearching] = useState(false);\n  const [locating, setLocating] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const seq = useRef(0);\n\n  useEffect(() => {\n    if (!visible) { setQuery(''); setResults(null); setError(null); }\n  }, [visible]);\n\n  /* ── Buscador real (geocoder del mirror, igual que en Crear ruta) ── */\n  const runSearch = useCallback(async (term: string) => {\n    const t = term.trim();\n    if (t.length < 2) { setResults(null); setSearching(false); return; }\n    const mine = ++seq.current;\n    setSearching(true);\n    try {\n      const res = await geocode(t);\n      if (mine === seq.current) setResults(res);\n    } finally {\n      if (mine === seq.current) setSearching(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    if (!visible) return;\n    const t = setTimeout(() => { runSearch(query); }, 350);\n    return () => clearTimeout(t);\n  }, [query, runSearch, visible]);\n\n  /** Mi ubicación: GPS + nombre real del punto (calle o lugar más cercano). */\n  const useMyLocation = async () => {\n    setError(null);\n    setLocating(true);\n    try {\n      const perm = await Location.requestForegroundPermissionsAsync();\n      if (perm.status !== 'granted') {\n        setError('Necesito permiso de ubicación para compartir dónde estás.');\n        return;\n      }\n      const pos = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });\n      const lat = Number(pos.coords.latitude);\n      const lng = Number(pos.coords.longitude);\n      if (!Number.isFinite(lat) || !Number.isFinite(lng)) {\n        setError('No pude leer tu posición. Prueba a buscar el sitio por su nombre.');\n        return;\n      }\n      const rev = await reverseGeocode(lng, lat).catch(() => []);\n      const name = pickReverseLabel(rev) ?? rev[0]?.name ?? null;\n      const label = name ? `Mi ubicación · ${name}` : `Mi ubicación (${lat.toFixed(4)}, ${lng.toFixed(4)})`;\n      onSubmit({ label, lat, lng });\n    } catch {\n      setError('No pude obtener tu ubicación. Busca el sitio por su nombre.');\n    } finally {\n      setLocating(false);\n    }\n  };\n\n  const pick = (p: GeoPlace) => {\n    const label = String(p.name ?? '').trim() || 'Ubicación compartida';\n    onSubmit({ label, lat: Number(p.lat), lng: Number(p.lon) });\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1 }}>\n            {title ?? 'Compartir ubicación'}\n          </Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        <Pressable\n          onPress={useMyLocation}\n          disabled={locating}\n          accessibilityLabel=\"Compartir mi ubicación actual\"\n          style={({ pressed }) => [styles.myLoc, {\n            backgroundColor: alpha(colors.primary, 0.10),\n            borderColor: alpha(colors.primary, 0.28),\n            opacity: pressed || locating ? 0.75 : 1,\n          }]}\n        >\n          {locating\n            ? <ActivityIndicator size=\"small\" color={colors.primary} />\n            : <Crosshair size={20} color={colors.primary} />}\n          <View style={{ flex: 1 }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>\n              {locating ? 'Buscando tu posición…' : (myLocationLabel ?? 'Mi ubicación actual')}\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              Con el nombre real de la calle o del lugar.\n            </Text>\n          </View>\n        </Pressable>\n\n        {/* Parte 28 (G4): ubicación en vivo durante la ruta */}\n        {onLive ? (\n          <Pressable\n            onPress={onLive}\n            accessibilityLabel=\"Compartir mi ubicación en vivo durante la ruta\"\n            style={({ pressed }) => [styles.myLoc, {\n              backgroundColor: alpha(colors.secondary, 0.10),\n              borderColor: alpha(colors.secondary, 0.28),\n              opacity: pressed ? 0.75 : 1,\n            }]}\n          >\n            <Radio size={20} color={colors.secondary} />\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Ubicación en vivo</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                Se actualiza sola durante la ruta; la puedes parar cuando quieras.\n              </Text>\n            </View>\n          </Pressable>\n        ) : null}\n\n        <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\n          <Search size={16} color={colors.textSecondary} />\n          <TextInput\n            value={query}\n            onChangeText={setQuery}\n            placeholder=\"Buscar calle, avenida o sitio…\"\n            placeholderTextColor={colors.textSecondary}\n            style={{ flex: 1, marginLeft: espaciado.e8, color: colors.textPrimary, fontSize: tipografia.body }}\n            accessibilityLabel=\"Buscar un sitio\"\n          />\n          {searching ? <ActivityIndicator size=\"small\" color={colors.primary} /> : null}\n        </View>\n\n        {error ? (\n          <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>{error}</Text>\n        ) : null}\n\n        {results === null && query.trim().length < 2 ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingVertical: espaciado.e16 }}>\n            Escribe al menos 2 letras: busca calles, avenidas y sitios reales de Malabo y Bata.\n          </Text>\n        ) : null}\n\n        {results !== null && results.length === 0 && !searching ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', paddingVertical: espaciado.e18 }}>\n            No hay sitios que coincidan. Prueba con el nombre de la calle.\n          </Text>\n        ) : null}\n\n        {(results ?? []).length > 0 ? (\n          <ScrollView style={{ maxHeight: 320 }} keyboardShouldPersistTaps=\"handled\">\n            {(results ?? []).map((r, i) => (\n              <Pressable\n                key={`${r.name}-${i}`}\n                onPress={() => pick(r)}\n                accessibilityLabel={`Compartir ${r.name}`}\n                style={({ pressed }) => [styles.row, {\n                  borderBottomColor: alpha(colors.border, 0.5),\n                  opacity: pressed ? 0.7 : 1,\n                }]}\n              >\n                <MapPin size={18} color={colors.primary} />\n                <View style={{ flex: 1 }}>\n                  <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: '700', fontSize: tipografia.body }}>{r.name}</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                    {LB_PLACE_KIND_LABEL[r.kind] ?? 'Lugar'} · {r.lat.toFixed(4)}, {r.lon.toFixed(4)}\n                  </Text>\n                </View>\n              </Pressable>\n            ))}\n          </ScrollView>\n        ) : null}\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e12 },\n  myLoc: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginBottom: espaciado.e12,\n  },\n  searchBox: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: 42 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e11, borderBottomWidth: StyleSheet.hairlineWidth },\n});\n","/**\n * VoteSheet — Parte 24 (G2): crear una VOTACIÓN en el chat.\n *\n * Pregunta (hasta 120 caracteres) y de 2 a 6 opciones. Los límites son los\n * mismos que valida el servidor (`VOTE_QUESTION_REQUIRED`,\n * `VOTE_OPTIONS_INVALID`), así que el aviso sale en línea sin ir y volver.\n * El mensaje se envía como `kind='vote'` y los votos van a\n * `lifebook.message_votes` (uno por persona: volver a votar cambia el voto).\n */\nimport React, { useEffect, useState } from 'react';\nimport { Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Plus, Trash2, Vote, X } from 'lucide-react-native';\nimport { formaHoja } from './ui/Sheet';\n\nconst QUESTION_MAX = 120;\nconst OPTION_MAX = 40;\nconst OPTIONS_MIN = 2;\nconst OPTIONS_MAX = 6;\n\ninterface Props {\n  visible: boolean;\n  onClose: () => void;\n  /** Crea la votación (el padre la envía como mensaje `vote`). */\n  onSubmit: (v: { question: string; options: string[] }) => void;\n}\n\nexport function VoteSheet({ visible, onClose, onSubmit }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [question, setQuestion] = useState('');\n  const [options, setOptions] = useState<string[]>(['', '']);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (visible) { setQuestion(''); setOptions(['', '']); setError(null); }\n  }, [visible]);\n\n  const filled = options.map((o) => o.trim()).filter((o) => !!o);\n  const canSend = question.trim().length > 0 && filled.length >= OPTIONS_MIN;\n\n  const setOption = (i: number, v: string) => {\n    setOptions((prev) => prev.map((o, idx) => (idx === i ? v : o)));\n    setError(null);\n  };\n  const addOption = () => {\n    if (options.length >= OPTIONS_MAX) return;\n    setOptions((prev) => [...prev, '']);\n  };\n  const removeOption = (i: number) => {\n    if (options.length <= OPTIONS_MIN) return;\n    setOptions((prev) => prev.filter((_, idx) => idx !== i));\n  };\n\n  const submit = () => {\n    if (!question.trim()) { setError('Escribe la pregunta de la votación.'); return; }\n    if (filled.length < OPTIONS_MIN) { setError(`La votación necesita al menos ${OPTIONS_MIN} opciones.`); return; }\n    onSubmit({ question: question.trim().slice(0, QUESTION_MAX), options: filled.slice(0, OPTIONS_MAX) });\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          <Vote size={18} color={colors.primary} />\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1, marginLeft: espaciado.e8 }}>\n            Crear votación\n          </Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        <TextInput\n          value={question}\n          onChangeText={(v) => { setQuestion(v); setError(null); }}\n          placeholder=\"¿Qué quieres preguntar?\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={QUESTION_MAX}\n          multiline\n          accessibilityLabel=\"Pregunta de la votación\"\n          style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, minHeight: 46 }]}\n        />\n        <Text style={{ color: colors.textSecondary, fontSize: 10.5, textAlign: 'right', marginTop: espaciado.e4 }}>\n          {question.length}/{QUESTION_MAX}\n        </Text>\n\n        <ScrollView style={{ maxHeight: 280 }} keyboardShouldPersistTaps=\"handled\">\n          {options.map((o, i) => (\n            <View key={`opt-${i}`} style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n              <TextInput\n                value={o}\n                onChangeText={(v) => setOption(i, v.slice(0, OPTION_MAX))}\n                placeholder={`Opción ${i + 1}`}\n                placeholderTextColor={colors.textSecondary}\n                maxLength={OPTION_MAX}\n                accessibilityLabel={`Opción ${i + 1}`}\n                style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, flex: 1 }]}\n              />\n              {options.length > OPTIONS_MIN ? (\n                <Pressable onPress={() => removeOption(i)} hitSlop={8} accessibilityLabel={`Quitar la opción ${i + 1}`}>\n                  <Trash2 size={18} color={colors.textSecondary} />\n                </Pressable>\n              ) : null}\n            </View>\n          ))}\n        </ScrollView>\n\n        {options.length < OPTIONS_MAX ? (\n          <Pressable\n            onPress={addOption}\n            accessibilityLabel=\"Añadir opción\"\n            style={({ pressed }) => [styles.addRow, { borderColor: alpha(colors.border, 0.9), opacity: pressed ? 0.7 : 1 }]}\n          >\n            <Plus size={16} color={colors.primary} />\n            <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body, marginLeft: espaciado.e6 }}>\n              Añadir opción ({options.length}/{OPTIONS_MAX})\n            </Text>\n          </Pressable>\n        ) : (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>\n            Máximo {OPTIONS_MAX} opciones.\n          </Text>\n        )}\n\n        {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>{error}</Text> : null}\n\n        <Pressable\n          onPress={submit}\n          disabled={!canSend}\n          accessibilityLabel=\"Publicar la votación\"\n          style={({ pressed }) => [styles.cta, {\n            backgroundColor: canSend ? colors.primary : alpha(colors.primary, 0.35),\n            opacity: pressed ? 0.85 : 1,\n          }]}\n        >\n          <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Publicar votación</Text>\n        </Pressable>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e12 },\n  input: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  addRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', borderWidth: 1, borderStyle: 'dashed', borderRadius: radios.md, paddingVertical: espaciado.e10, marginTop: espaciado.e12 },\n  cta: { marginTop: espaciado.e16, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e14 },\n});\n","/**\n * ChainSheet — Parte 25 (G2-b): crear una CADENA en el chat.\n *\n * Una cadena es una lista a la que la gente se APUNTA (relevo, compra conjunta,\n * turnos, recogida de algo…). Se puede poner un tope de plazas: cuando está\n * llena, el servidor responde `CHAIN_FULL` y la app lo dice en línea.\n * El mensaje se envía como `kind='chain'`; los apuntados van a\n * `lifebook.message_joins` (uno por persona).\n */\nimport React, { useEffect, useState } from 'react';\nimport { Modal, Pressable, StyleSheet, Switch, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Link2, X } from 'lucide-react-native';\nimport { formaHoja } from './ui/Sheet';\n\nconst TITLE_MAX = 80;\nconst NOTE_MAX = 200;\nconst SLOTS_MIN = 2;\nconst SLOTS_MAX = 200;\n\ninterface Props {\n  visible: boolean;\n  onClose: () => void;\n  /** Crea la cadena (el padre la envía como mensaje `chain`). */\n  onSubmit: (c: { title: string; note?: string; slots?: number }) => void;\n}\n\nexport function ChainSheet({ visible, onClose, onSubmit }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [title, setTitle] = useState('');\n  const [note, setNote] = useState('');\n  const [limited, setLimited] = useState(false);\n  const [slots, setSlots] = useState('10');\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (visible) { setTitle(''); setNote(''); setLimited(false); setSlots('10'); setError(null); }\n  }, [visible]);\n\n  const slotsNum = Number(slots.replace(/[^0-9]/g, ''));\n  const slotsOk = !limited || (Number.isInteger(slotsNum) && slotsNum >= SLOTS_MIN && slotsNum <= SLOTS_MAX);\n  const canSend = title.trim().length > 0 && slotsOk;\n\n  const submit = () => {\n    if (!title.trim()) { setError('Ponle un título a la cadena.'); return; }\n    if (!slotsOk) { setError(`El tope de plazas debe estar entre ${SLOTS_MIN} y ${SLOTS_MAX}.`); return; }\n    onSubmit({\n      title: title.trim().slice(0, TITLE_MAX),\n      note: note.trim() ? note.trim().slice(0, NOTE_MAX) : undefined,\n      slots: limited ? slotsNum : undefined,\n    });\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          <Link2 size={18} color={colors.primary} />\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1, marginLeft: espaciado.e8 }}>\n            Crear cadena\n          </Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        <TextInput\n          value={title}\n          onChangeText={(v) => { setTitle(v); setError(null); }}\n          placeholder=\"¿Para qué es la cadena? (p. ej. Compra de arroz)\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={TITLE_MAX}\n          accessibilityLabel=\"Título de la cadena\"\n          style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n        />\n        <Text style={{ color: colors.textSecondary, fontSize: 10.5, textAlign: 'right', marginTop: espaciado.e4 }}>\n          {title.length}/{TITLE_MAX}\n        </Text>\n\n        <TextInput\n          value={note}\n          onChangeText={setNote}\n          placeholder=\"Detalles (opcional)\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={NOTE_MAX}\n          multiline\n          accessibilityLabel=\"Detalles de la cadena\"\n          style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, minHeight: 60, marginTop: espaciado.e8 }]}\n        />\n\n        <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: espaciado.e12, gap: espaciado.e10 }}>\n          <View style={{ flex: 1 }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Tope de plazas</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              Con tope, la cadena se cierra al llenarse. Sin tope, entran todos.\n            </Text>\n          </View>\n          <Switch value={limited} onValueChange={setLimited} />\n        </View>\n\n        {limited ? (\n          <TextInput\n            value={slots}\n            onChangeText={setSlots}\n            keyboardType=\"number-pad\"\n            maxLength={3}\n            accessibilityLabel=\"Número de plazas\"\n            style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, marginTop: espaciado.e10, width: 110 }]}\n          />\n        ) : null}\n\n        {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>{error}</Text> : null}\n\n        <Pressable\n          onPress={submit}\n          disabled={!canSend}\n          accessibilityLabel=\"Publicar la cadena\"\n          style={({ pressed }) => [styles.cta, {\n            backgroundColor: canSend ? colors.primary : alpha(colors.primary, 0.35),\n            opacity: pressed ? 0.85 : 1,\n          }]}\n        >\n          <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Publicar cadena</Text>\n        </Pressable>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e12 },\n  input: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  cta: { marginTop: espaciado.e16, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e14 },\n});\n","/**\n * CheckinSheet — Parte 25 (G2-b): elige CUÁNDO es la QUEDADA.\n *\n * El lugar ya viene elegido: el chat abre primero `LocationPickerSheet` (mi\n * ubicación por GPS o el buscador real de calles y sitios) y, al elegir el\n * punto, abre esta hoja para la hora. Se hace en dos pasos y con una sola hoja\n * visible a la vez a propósito: dos modales anidados se comportan mal en Android.\n *\n * Atajos (en 1 hora · en 2 horas · esta tarde 18:00 · mañana 09:00) u hora\n * escrita a mano. El mensaje se envía como `kind='checkin'` con `at` en ISO y el\n * servidor lo etiqueta en hora de Malabo («hoy 18:30»); los que van se apuntan\n * con `POST /chat/messages/:id/join`.\n */\nimport React, { useEffect, useState } from 'react';\nimport { Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { CalendarCheck, Clock, X } from 'lucide-react-native';\nimport type { LbPickedLocation } from './LocationPickerSheet';\nimport { formaHoja } from './ui/Sheet';\n\nexport interface LbCheckinDraft {\n  label: string;\n  lat: number;\n  lng: number;\n  at: string;\n}\n\ninterface Props {\n  visible: boolean;\n  /** Lugar ya elegido (paso anterior). */\n  place: LbPickedLocation | null;\n  onClose: () => void;\n  /** Crea la quedada (el padre la envía como mensaje `checkin`). */\n  onSubmit: (c: LbCheckinDraft) => void;\n}\n\n/** Fecha a N horas (y minutos) de ahora. */\nfunction atOffset(hours: number, minutes = 0): Date {\n  return new Date(Date.now() + hours * 3600 * 1000 + minutes * 60 * 1000);\n}\n\n/** \"HH:MM\" → la próxima vez que sean esas horas (hoy o mañana si ya pasó). */\nfunction atClock(hhmm: string): Date | null {\n  const m = /^(\\d{1,2})\\s*[:.h]?\\s*(\\d{2})?$/.exec(hhmm.trim());\n  if (!m) return null;\n  const h = Number(m[1]);\n  const min = Number(m[2] ?? '0');\n  if (!Number.isInteger(h) || h > 23 || !Number.isInteger(min) || min > 59) return null;\n  const d = new Date();\n  d.setHours(h, min, 0, 0);\n  if (d.getTime() <= Date.now()) d.setDate(d.getDate() + 1);\n  return d;\n}\n\nexport function CheckinSheet({ visible, place, onClose, onSubmit }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [custom, setCustom] = useState('');\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (visible) { setCustom(''); setError(null); }\n  }, [visible]);\n\n  const opciones = [\n    { label: 'En 1 hora', at: atOffset(1), icon: '⏱️' },\n    { label: 'En 2 horas', at: atOffset(2), icon: '⏱️' },\n    { label: 'Esta tarde', at: atClock('18:00') },\n    { label: 'Mañana por la mañana', at: atClock('09:00') },\n  ].filter((o) => !!o.at) as { label: string; at: Date; icon?: string }[];\n\n  const crear = (at: Date) => {\n    if (!place) { setError('Falta el lugar de la quedada.'); return; }\n    onSubmit({ label: place.label, lat: place.lat, lng: place.lng, at: at.toISOString() });\n  };\n\n  const usarHoraEscrita = () => {\n    const d = atClock(custom);\n    if (!d) { setError('Escribe la hora así: 18:30.'); return; }\n    crear(d);\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          <CalendarCheck size={18} color={colors.primary} />\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1, marginLeft: espaciado.e8 }}>\n            ¿Cuándo es la quedada?\n          </Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        <View style={[styles.placeRow, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.28) }]}>\n          <Text style={{ fontSize: 18 }}>📍</Text>\n          <View style={{ flex: 1 }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>\n              {place?.label ?? 'Sin lugar'}\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              {place ? `${place.lat.toFixed(4)}, ${place.lng.toFixed(4)}` : 'Vuelve a empezar la quedada.'}\n            </Text>\n          </View>\n        </View>\n\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e14 }}>\n          <Clock size={15} color={colors.textSecondary} />\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }}>HORA</Text>\n        </View>\n\n        <ScrollView style={{ maxHeight: 260 }} keyboardShouldPersistTaps=\"handled\">\n          {opciones.map((o) => (\n            <Pressable\n              key={o.label}\n              onPress={() => crear(o.at)}\n              accessibilityLabel={`Quedada ${o.label}`}\n              style={({ pressed }) => [styles.opt, { backgroundColor: colors.surface, opacity: pressed ? 0.75 : 1 }]}\n            >\n              <Text style={{ fontSize: tipografia.subtitle }}>{o.icon ?? '📅'}</Text>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700', flex: 1 }}>\n                {o.at.toLocaleString('es-GQ', { weekday: 'short', hour: '2-digit', minute: '2-digit' })}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{o.label}</Text>\n            </Pressable>\n          ))}\n\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n            <TextInput\n              value={custom}\n              onChangeText={(v) => { setCustom(v); setError(null); }}\n              placeholder=\"Otra hora: 18:30\"\n              placeholderTextColor={colors.textSecondary}\n              keyboardType=\"numbers-and-punctuation\"\n              maxLength={5}\n              accessibilityLabel=\"Escribir la hora de la quedada\"\n              style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, flex: 1 }]}\n            />\n            <Pressable\n              onPress={usarHoraEscrita}\n              accessibilityLabel=\"Crear la quedada con esa hora\"\n              style={({ pressed }) => [styles.smallCta, { backgroundColor: alpha(colors.primary, 0.14), opacity: pressed ? 0.8 : 1 }]}\n            >\n              <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>Usar</Text>\n            </Pressable>\n          </View>\n        </ScrollView>\n\n        {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>{error}</Text> : null}\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e10 }}>\n          En el mensaje, quien quiera ir pulsa «Voy» (tú también cuentas).\n        </Text>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e12 },\n  placeRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderWidth: 1, borderRadius: 14, padding: espaciado.e12 },\n  opt: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e12, marginTop: espaciado.e8 },\n  input: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  smallCta: { borderRadius: radios.md, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e11 },\n});\n","/**\n * AdSheet — Parte 26 (G2-c): publicar un ANUNCIO en el grupo.\n *\n * Decisión del dueño: **15 anuncios por persona y día** (el servidor lo aplica\n * y responde `AD_LIMIT_REACHED`). La hoja enseña cuántos quedan hoy.\n * El anuncio puede llevar título, texto, precio, foto y un enlace a un servicio\n * (los enlaces con requisito de rol los valida el servidor).\n */\nimport React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, Image, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ImagePlus, Megaphone, X } from 'lucide-react-native';\nimport * as ImagePicker from 'expo-image-picker';\nimport { messagesApi } from '../../api/messages';\nimport { lifebookMediaApi } from '../../api/lifebook';\nimport { authApi } from '../../api/auth';\nimport { formaHoja } from './ui/Sheet';\n\nconst TITLE_MAX = 60;\nconst TEXT_MAX = 300;\n\n/** Enlaces de servicio que se pueden adjuntar (el servidor valida el rol). */\nconst LINKS: { type: string; label: string }[] = [\n  { type: 'lifebook', label: 'Mi perfil de Life Book' },\n  { type: 'ecomerse', label: 'Mi tienda' },\n  { type: 'food', label: 'Mi restaurante' },\n  { type: 'work', label: 'Mi oferta de trabajo' },\n  { type: 'rental', label: 'Mi alquiler' },\n  { type: 'taxi', label: 'Taxi' },\n];\n\nexport interface LbAdDraft {\n  title: string;\n  text: string;\n  priceXaf?: number;\n  mediaUrl?: string;\n  linkType?: string;\n  /** Id del destino del enlace (mi perfil, mi tienda…). */\n  linkId?: string;\n}\n\ninterface Props {\n  visible: boolean;\n  onClose: () => void;\n  /** Publica el anuncio (el padre lo envía como mensaje `ad`). */\n  onSubmit: (a: LbAdDraft) => void;\n}\n\nexport function AdSheet({ visible, onClose, onSubmit }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [title, setTitle] = useState('');\n  const [text, setText] = useState('');\n  const [price, setPrice] = useState('');\n  const [photo, setPhoto] = useState<string | null>(null);\n  const [uploading, setUploading] = useState(false);\n  const [linkType, setLinkType] = useState<string | null>(null);\n  /** Mi id: es lo que necesita el enlace «Mi perfil» para abrir algo de verdad. */\n  const [myId, setMyId] = useState<string | null>(null);\n  const [left, setLeft] = useState<number | null>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (!visible) return;\n    setTitle(''); setText(''); setPrice(''); setPhoto(null); setLinkType(null); setError(null);\n    // Cuántos anuncios me quedan hoy (el límite es del servidor).\n    messagesApi.adsLeft()\n      .then((r) => setLeft(Number(r.left)))\n      .catch(() => setLeft(null));\n    // Mi id (para enlazar mi perfil: `/lifebook-store` sin id no abriría nada).\n    authApi.me().then((m) => setMyId(m?.id ?? null)).catch(() => setMyId(null));\n  }, [visible]);\n\n  const priceNum = Number(price.replace(/[^0-9]/g, ''));\n  const canSend = (title.trim().length > 0 || text.trim().length > 0) && !uploading && left !== 0;\n\n  const pickPhoto = async () => {\n    try {\n      const perm = await ImagePicker.getMediaLibraryPermissionsAsync().catch(() => null);\n      if (perm && perm.granted === false) await ImagePicker.requestMediaLibraryPermissionsAsync().catch(() => null);\n      const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.8, selectionLimit: 1 });\n      if (res.canceled || !res.assets?.[0]) return;\n      const asset = res.assets[0];\n      setUploading(true);\n      const up = await lifebookMediaApi.uploadFile('image', {\n        uri: asset.uri,\n        name: asset.fileName ?? `anuncio-${Date.now()}.jpg`,\n        mimeType: asset.mimeType ?? 'image/jpeg',\n      });\n      setPhoto(up.url);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo subir la foto.');\n    } finally { setUploading(false); }\n  };\n\n  const submit = () => {\n    if (!title.trim() && !text.trim()) { setError('Escribe el anuncio.'); return; }\n    // El enlace «Mi perfil» necesita mi id: sin él la pantalla de destino no\n    // tiene nada que abrir (era el fallo de «el enlace no se abre»).\n    const linkId = linkType === 'lifebook' ? (myId ?? undefined) : undefined;\n    if (linkType === 'lifebook' && !linkId) {\n      setError('No pude leer tu perfil para el enlace. Prueba otra vez o quita el enlace.');\n      return;\n    }\n    onSubmit({\n      title: title.trim().slice(0, TITLE_MAX),\n      text: text.trim().slice(0, TEXT_MAX),\n      priceXaf: priceNum > 0 ? priceNum : undefined,\n      mediaUrl: photo ?? undefined,\n      linkType: linkType ?? undefined,\n      linkId,\n    });\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          <Megaphone size={18} color={colors.primary} />\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1, marginLeft: espaciado.e8 }}>\n            Anuncio del grupo\n          </Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e8 }}>\n          {left === null\n            ? 'Máximo 15 anuncios por persona y día.'\n            : left === 0\n              ? 'Ya has publicado tus 15 anuncios de hoy. Vuelve mañana.'\n              : `Te quedan ${left} anuncio${left === 1 ? '' : 's'} hoy (máximo 15 al día).`}\n        </Text>\n\n        <ScrollView style={{ maxHeight: 420 }} keyboardShouldPersistTaps=\"handled\">\n          <TextInput\n            value={title}\n            onChangeText={(v) => { setTitle(v); setError(null); }}\n            placeholder=\"Título (p. ej. Clases de refuerzo)\"\n            placeholderTextColor={colors.textSecondary}\n            maxLength={TITLE_MAX}\n            accessibilityLabel=\"Título del anuncio\"\n            style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n          />\n          <TextInput\n            value={text}\n            onChangeText={(v) => { setText(v); setError(null); }}\n            placeholder=\"¿Qué quieres anunciar? Precio, horario, dónde…\"\n            placeholderTextColor={colors.textSecondary}\n            maxLength={TEXT_MAX}\n            multiline\n            accessibilityLabel=\"Texto del anuncio\"\n            style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, minHeight: 80, marginTop: espaciado.e8 }]}\n          />\n          <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8, alignItems: 'center' }}>\n            <TextInput\n              value={price}\n              onChangeText={setPrice}\n              placeholder=\"Precio (XAF)\"\n              placeholderTextColor={colors.textSecondary}\n              keyboardType=\"number-pad\"\n              maxLength={9}\n              accessibilityLabel=\"Precio del anuncio\"\n              style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, flex: 1 }]}\n            />\n            <Pressable\n              onPress={pickPhoto}\n              disabled={uploading}\n              accessibilityLabel={photo ? 'Cambiar la foto del anuncio' : 'Añadir una foto al anuncio'}\n              style={({ pressed }) => [styles.photoBtn, {\n                backgroundColor: colors.surface, opacity: pressed || uploading ? 0.75 : 1,\n              }]}\n            >\n              {uploading\n                ? <ActivityIndicator size=\"small\" color={colors.primary} />\n                : photo\n                  ? <Image source={{ uri: photo }} style={styles.thumb} />\n                  : <><ImagePlus size={16} color={colors.primary} /><Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800', marginLeft: espaciado.e6 }}>Foto</Text></>}\n            </Pressable>\n          </View>\n\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, fontWeight: '800' }}>ENLAZAR UN SERVICIO (OPCIONAL)</Text>\n          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, marginTop: espaciado.e6 }}>\n            {LINKS.map((l) => {\n              const active = linkType === l.type;\n              return (\n                <Pressable\n                  key={l.type}\n                  onPress={() => setLinkType(active ? null : l.type)}\n                  accessibilityLabel={`Enlazar ${l.label}`}\n                  style={[styles.chip, {\n                    backgroundColor: active ? alpha(colors.primary, 0.14) : colors.surface,\n                    borderColor: active ? colors.primary : 'transparent',\n                  }]}\n                >\n                  <Text style={{ color: active ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{l.label}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n        </ScrollView>\n\n        {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>{error}</Text> : null}\n\n        <Pressable\n          onPress={submit}\n          disabled={!canSend}\n          accessibilityLabel=\"Publicar el anuncio\"\n          style={({ pressed }) => [styles.cta, {\n            backgroundColor: canSend ? colors.primary : alpha(colors.primary, 0.35),\n            opacity: pressed ? 0.85 : 1,\n          }]}\n        >\n          <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Publicar anuncio</Text>\n        </Pressable>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e8 },\n  input: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  photoBtn: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'center',\n    borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: 42, minWidth: 78,\n  },\n  thumb: { width: 34, height: 34, borderRadius: radios.sm },\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6, borderWidth: 1 },\n  cta: { marginTop: espaciado.e16, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e14 },\n});\n","/**\n * ChallengePlazaSheet — Parte 26 (G2-c): la PLAZA DE RETOS.\n *\n * Retos de la comunidad: cualquiera crea uno (objetivo + cuándo termina + premio\n * opcional), la gente se apunta y el detalle muestra el **ranking por orden de\n * inscripción**. Sirve para lo mismo en un grupo que en un 1 a 1, así que se\n * abre desde el panel «+» del chat con la acción «Plaza de retos».\n *\n * Pasos: `list` (retos abiertos, filtro por ciudad y por «los míos») ·\n * `create` (título, descripción, ciudad, premio y fecha de fin) ·\n * `detail` (ranking, apuntarse/borrarse y cerrar si es mío).\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, Alert, Modal, Pressable, ScrollView, StyleSheet, Switch, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, ScrollText, Trophy, X } from 'lucide-react-native';\nimport { lifebookChallengesApi, type LbChallenge } from '../../api/lifebook';\nimport { LB_CITIES } from '../../constants/lifebook';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { formaHoja } from './ui/Sheet';\n\nconst TITLE_MAX = 80;\nconst BODY_MAX = 400;\nconst PRIZE_MAX = 120;\nconst NOTE_MAX = 200;\n\ntype Step = 'list' | 'create' | 'detail';\n/** Atajos de fecha de fin (días desde hoy). */\nconst ENDS = [\n  { days: 1, label: 'Mañana' },\n  { days: 7, label: 'En una semana' },\n  { days: 30, label: 'En un mes' },\n];\n\ninterface Props {\n  visible: boolean;\n  onClose: () => void;\n  /** Ciudad del usuario (filtro por defecto de la lista). */\n  city?: string | null;\n}\n\nexport function ChallengePlazaSheet({ visible, onClose, city }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [step, setStep] = useState<Step>('list');\n  const [loading, setLoading] = useState(false);\n  const [list, setList] = useState<LbChallenge[]>([]);\n  const [onlyMine, setOnlyMine] = useState(false);\n  const [filterCity, setFilterCity] = useState<string | null>(city ?? null);\n  const [detail, setDetail] = useState<LbChallenge | null>(null);\n  const [busy, setBusy] = useState(false);\n  // Crear\n  const [title, setTitle] = useState('');\n  const [body, setBody] = useState('');\n  const [prize, setPrize] = useState('');\n  const [newCity, setNewCity] = useState<string | null>(city ?? null);\n  const [endsDays, setEndsDays] = useState<number | null>(7);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    try {\n      const res = await lifebookChallengesApi.list({ state: 'open', city: filterCity ?? undefined, mine: onlyMine, limit: 30 });\n      setList(res.challenges ?? []);\n    } catch (e) {\n      Alert.alert('Plaza de retos', e instanceof Error ? e.message : 'No se pudieron cargar los retos.');\n      setList([]);\n    } finally { setLoading(false); }\n  }, [filterCity, onlyMine]);\n\n  useEffect(() => {\n    if (!visible) return;\n    setStep('list'); setDetail(null); setOnlyMine(false);\n    setTitle(''); setBody(''); setPrize(''); setEndsDays(7); setNewCity(city ?? null);\n  }, [visible, city]);\n\n  useEffect(() => { if (visible && step === 'list') void load(); }, [visible, step, load]);\n\n  const abrirDetalle = async (id: string) => {\n    setBusy(true);\n    try {\n      setDetail(await lifebookChallengesApi.detail(id));\n      setStep('detail');\n    } catch (e) {\n      Alert.alert('Reto', e instanceof Error ? e.message : 'No se pudo abrir el reto.');\n    } finally { setBusy(false); }\n  };\n\n  const apuntarme = async (c: LbChallenge, note?: string) => {\n    setBusy(true);\n    try {\n      const updated = c.joinedByMe\n        ? await lifebookChallengesApi.leave(c.id)\n        : await lifebookChallengesApi.join(c.id, note);\n      setDetail(updated);\n      setList((prev) => prev.map((x) => (x.id === updated.id ? updated : x)));\n    } catch (e) {\n      Alert.alert('Reto', e instanceof Error ? e.message : 'No se pudo completar la acción.');\n    } finally { setBusy(false); }\n  };\n\n  const crear = async () => {\n    if (title.trim().length < 3) { Alert.alert('Reto', 'Ponle un título al reto (3 letras o más).'); return; }\n    setBusy(true);\n    try {\n      const endsAt = endsDays ? new Date(Date.now() + endsDays * 24 * 3600 * 1000).toISOString() : undefined;\n      const created = await lifebookChallengesApi.create({\n        title: title.trim().slice(0, TITLE_MAX),\n        body: body.trim().slice(0, BODY_MAX) || undefined,\n        city: newCity ?? undefined,\n        prize: prize.trim().slice(0, PRIZE_MAX) || undefined,\n        endsAt,\n      });\n      setList((prev) => [created, ...prev]);\n      setDetail(created);\n      setStep('detail');\n    } catch (e) {\n      Alert.alert('Reto', e instanceof Error ? e.message : 'No se pudo crear el reto.');\n    } finally { setBusy(false); }\n  };\n\n  const cerrarReto = (c: LbChallenge) => {\n    Alert.alert('Cerrar el reto', 'Dejará de admitir participantes.', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Cerrar',\n        style: 'destructive',\n        onPress: async () => {\n          setBusy(true);\n          try {\n            const updated = await lifebookChallengesApi.close(c.id);\n            setDetail(updated);\n            setList((prev) => prev.filter((x) => x.id !== updated.id));\n          } catch (e) {\n            Alert.alert('Reto', e instanceof Error ? e.message : 'No se pudo cerrar el reto.');\n          } finally { setBusy(false); }\n        },\n      },\n    ]);\n  };\n\n  const fin = (c: LbChallenge) => (c.endsAt\n    ? new Date(c.endsAt).toLocaleDateString('es-GQ', { day: '2-digit', month: 'short' })\n    : 'sin fecha de fin');\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          {step !== 'list' ? (\n            <Pressable onPress={() => setStep(step === 'detail' ? 'list' : 'list')} hitSlop={8} accessibilityLabel=\"Volver a la lista\">\n              <ArrowLeft size={18} color={colors.textPrimary} />\n            </Pressable>\n          ) : (\n            <ScrollText size={18} color={colors.primary} />\n          )}\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1, marginLeft: espaciado.e8 }}>\n            {step === 'create' ? 'Crear un reto' : step === 'detail' ? 'Reto' : 'Plaza de retos'}\n          </Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        {step === 'list' ? (\n          <>\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Solo mis retos</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Los que yo he creado.</Text>\n              </View>\n              <Switch value={onlyMine} onValueChange={setOnlyMine} />\n            </View>\n\n            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e6, paddingVertical: espaciado.e10 }}>\n              <Pressable onPress={() => setFilterCity(null)} accessibilityLabel=\"Todas las ciudades\"\n                style={[styles.chip, { backgroundColor: filterCity === null ? alpha(colors.primary, 0.14) : colors.surface, borderColor: filterCity === null ? colors.primary : 'transparent' }]}>\n                <Text style={{ color: filterCity === null ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>Todas</Text>\n              </Pressable>\n              {LB_CITIES.map((c) => (\n                <Pressable key={c} onPress={() => setFilterCity(c)} accessibilityLabel={`Retos en ${c}`}\n                  style={[styles.chip, { backgroundColor: filterCity === c ? alpha(colors.primary, 0.14) : colors.surface, borderColor: filterCity === c ? colors.primary : 'transparent' }]}>\n                  <Text style={{ color: filterCity === c ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{c}</Text>\n                </Pressable>\n              ))}\n            </ScrollView>\n\n            <Pressable onPress={() => setStep('create')} accessibilityLabel=\"Crear un reto\"\n              style={[styles.cta, { backgroundColor: alpha(colors.primary, 0.12), marginTop: 0 }]}>\n              <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>＋  Crear un reto</Text>\n            </Pressable>\n\n            {loading ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e24 }} />\n            ) : list.length === 0 ? (\n              <Text style={{ color: colors.textSecondary, textAlign: 'center', paddingVertical: espaciado.e24, fontSize: tipografia.body }}>\n                Todavía no hay retos abiertos{filterCity ? ` en ${filterCity}` : ''}. ¡Crea el primero!\n              </Text>\n            ) : (\n              <ScrollView style={{ maxHeight: 380 }} keyboardShouldPersistTaps=\"handled\">\n                {list.map((c) => (\n                  <Pressable key={c.id} onPress={() => abrirDetalle(c.id)} accessibilityLabel={`Ver el reto ${c.title}`}\n                    style={({ pressed }) => [styles.card, { backgroundColor: colors.surface, opacity: pressed ? 0.8 : 1 }]}>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n                      <Trophy size={14} color={brand.secondary} />\n                      <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body, flex: 1 }} numberOfLines={2}>{c.title}</Text>\n                    </View>\n                    {c.body ? (\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }} numberOfLines={2}>{c.body}</Text>\n                    ) : null}\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e6 }}>\n                      {c.entries} participante{c.entries === 1 ? '' : 's'} · {c.city ?? 'sin ciudad'} · hasta {fin(c)}\n                      {c.prize ? ` · 🏆 ${c.prize}` : ''}\n                    </Text>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n                      <Pressable onPress={() => apuntarme(c)} accessibilityLabel={c.joinedByMe ? `Borrar me del reto ${c.title}` : `Apuntarme al reto ${c.title}`}\n                        style={[styles.smallBtn, { backgroundColor: c.joinedByMe ? alpha(colors.primary, 0.12) : colors.primary }]}>\n                        <Text style={{ color: c.joinedByMe ? colors.primary : brand.white, fontWeight: '900', fontSize: tipografia.caption }}>\n                          {c.joinedByMe ? '✓ Apuntado' : 'Apuntarme'}\n                        </Text>\n                      </Pressable>\n                      {c.mine ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>Es tuyo</Text> : null}\n                    </View>\n                  </Pressable>\n                ))}\n              </ScrollView>\n            )}\n          </>\n        ) : step === 'create' ? (\n          <ScrollView style={{ maxHeight: 460 }} keyboardShouldPersistTaps=\"handled\">\n            <TextInput\n              value={title} onChangeText={setTitle} maxLength={TITLE_MAX}\n              placeholder=\"Título (p. ej. Reto 10 km)\"\n              placeholderTextColor={colors.textSecondary}\n              accessibilityLabel=\"Título del reto\"\n              style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n            />\n            <TextInput\n              value={body} onChangeText={setBody} maxLength={BODY_MAX} multiline\n              placeholder=\"¿En qué consiste? Reglas, hora, punto de encuentro…\"\n              placeholderTextColor={colors.textSecondary}\n              accessibilityLabel=\"Descripción del reto\"\n              style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, minHeight: 84, marginTop: espaciado.e8 }]}\n            />\n            <TextInput\n              value={prize} onChangeText={setPrize} maxLength={PRIZE_MAX}\n              placeholder=\"Premio (opcional)\"\n              placeholderTextColor={colors.textSecondary}\n              accessibilityLabel=\"Premio del reto\"\n              style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, marginTop: espaciado.e8 }]}\n            />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, fontWeight: '800' }}>CIUDAD</Text>\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, marginTop: espaciado.e6 }}>\n              {LB_CITIES.map((c) => (\n                <Pressable key={c} onPress={() => setNewCity(newCity === c ? null : c)} accessibilityLabel={`Ciudad ${c}`}\n                  style={[styles.chip, { backgroundColor: newCity === c ? alpha(colors.primary, 0.14) : colors.surface, borderColor: newCity === c ? colors.primary : 'transparent' }]}>\n                  <Text style={{ color: newCity === c ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{c}</Text>\n                </Pressable>\n              ))}\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, fontWeight: '800' }}>TERMINA</Text>\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, marginTop: espaciado.e6 }}>\n              {ENDS.map((e) => (\n                <Pressable key={e.label} onPress={() => setEndsDays(e.days)} accessibilityLabel={`Termina ${e.label}`}\n                  style={[styles.chip, { backgroundColor: endsDays === e.days ? alpha(colors.primary, 0.14) : colors.surface, borderColor: endsDays === e.days ? colors.primary : 'transparent' }]}>\n                  <Text style={{ color: endsDays === e.days ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{e.label}</Text>\n                </Pressable>\n              ))}\n              <Pressable onPress={() => setEndsDays(null)} accessibilityLabel=\"Sin fecha de fin\"\n                style={[styles.chip, { backgroundColor: endsDays === null ? alpha(colors.primary, 0.14) : colors.surface, borderColor: endsDays === null ? colors.primary : 'transparent' }]}>\n                <Text style={{ color: endsDays === null ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>Sin fecha</Text>\n              </Pressable>\n            </View>\n            <Pressable onPress={crear} disabled={busy} accessibilityLabel=\"Publicar el reto\"\n              style={[styles.cta, { backgroundColor: colors.primary }]}>\n              {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : (\n                <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Publicar reto</Text>\n              )}\n            </Pressable>\n          </ScrollView>\n        ) : detail ? (\n          <ScrollView style={{ maxHeight: 460 }} keyboardShouldPersistTaps=\"handled\">\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>{detail.title}</Text>\n            {detail.body ? (\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, marginTop: espaciado.e6, lineHeight: 19 }}>{detail.body}</Text>\n            ) : null}\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>\n              {detail.city ?? 'sin ciudad'} · hasta {fin(detail)}\n              {detail.prize ? ` · 🏆 ${detail.prize}` : ''} · {detail.state === 'open' ? 'abierto' : 'cerrado'}\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }}>\n              Lo creó {detail.author.fullName ?? 'alguien'}\n            </Text>\n\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e14, fontWeight: '800' }}>\n              RANKING · {detail.entries} PARTICIPANTE{detail.entries === 1 ? '' : 'S'}\n            </Text>\n            {(detail.members ?? []).length === 0 ? (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, paddingVertical: espaciado.e10 }}>\n                Nadie se ha apuntado todavía.\n              </Text>\n            ) : (\n              (detail.members ?? []).map((m, i) => (\n                <View key={m.id} style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e8 }}>\n                  <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body, width: 22 }}>{i + 1}º</Text>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }} numberOfLines={1}>\n                      {m.fullName ?? 'Usuario'}\n                    </Text>\n                    {m.note ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }} numberOfLines={2}>{m.note}</Text> : null}\n                  </View>\n                </View>\n              ))\n            )}\n\n            {detail.state === 'open' ? (\n              <Pressable onPress={() => apuntarme(detail)} disabled={busy} accessibilityLabel={detail.joinedByMe ? 'Borrar me del reto' : 'Apuntarme al reto'}\n                style={[styles.cta, { backgroundColor: detail.joinedByMe ? alpha(colors.primary, 0.12) : colors.primary }]}>\n                <Text style={{ color: detail.joinedByMe ? colors.primary : brand.white, fontWeight: '900', fontSize: 15 }}>\n                  {detail.joinedByMe ? '✓ Apuntado · borrarme' : 'Apuntarme'}\n                </Text>\n              </Pressable>\n            ) : (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, textAlign: 'center' }}>\n                Este reto está cerrado: ya no admite participantes.\n              </Text>\n            )}\n            {detail.mine && detail.state === 'open' ? (\n              <Pressable onPress={() => cerrarReto(detail)} disabled={busy} accessibilityLabel=\"Cerrar el reto\"\n                style={[styles.cta, { backgroundColor: alpha(colors.danger, 0.12) }]}>\n                <Text style={{ color: colors.danger, fontWeight: '900', fontSize: tipografia.body }}>Cerrar el reto</Text>\n              </Pressable>\n            ) : null}\n          </ScrollView>\n        ) : null}\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e10 },\n  input: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6, borderWidth: 1 },\n  card: { borderRadius: 14, padding: espaciado.e12, marginTop: espaciado.e10 },\n  smallBtn: { borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8 },\n  cta: { marginTop: espaciado.e14, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e13 },\n});\n","/**\r\n * app/lifebook-checkout.tsx — FINALIZAR PEDIDO (Parte 36).\r\n *\r\n * Construido sobre la pantalla que envió el dueño, con los arreglos necesarios:\r\n *   · la lista de pagos sale del catálogo (`LB_PAY_METHODS`), con `transfer` y\r\n *     `deposit` incluidos y sin los que no existen (era el fallo que dejaba al\r\n *     comprador SIN poder pagar);\r\n *   · **clave de idempotencia estable por compra** (se genera una vez y se\r\n *     reutiliza: un doble toque o un reintento no crean dos pedidos);\r\n *   · los chips son `Chip` (Pressable) con los tokens reales del tema;\r\n *   · `lbXaf()`, `absUrl()`, `<AuthGate>`, área segura y validación de dirección.\r\n */\r\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\r\nimport { ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\r\nimport { Image } from 'expo-image';\r\nimport * as Crypto from 'expo-crypto';\r\nimport { useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { alpha, espaciado, GhostButton, PrimaryButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { ArrowLeft, Banknote, Building2, MapPin, Package, Store, Truck, Wallet } from 'lucide-react-native';\r\nimport { AuthGate } from '../core/AuthGate';\r\nimport { absUrl } from '../api/config';\r\nimport { commerceApi, commerceOrdersApi, cuponesApi, descuentoDeCupon, type LbCupon, type LbProduct } from '../api/commerce';\r\nimport { walletApi } from '../api/wallet';\r\nimport { fijarPin } from '../api/settlement';\r\nimport { PinSheet } from '@egrouteplan/ui-kit';\r\nimport { SelectorDeCupon } from '../components/lifebook/SelectorDeCupon';\r\nimport { LB_CITIES, lbXaf } from '../constants/lifebook';\r\nimport { LB_PAY_METHODS, LB_PAY_STATUS_LABEL, lbPayLabel, lbTransportLabel } from '../constants/commerce';\r\nimport { Chip, ChipRow } from '../components/lifebook/Chip';\r\nimport { Notice } from '../components/lifebook/publish/PublishParts';\r\nimport { ir as irSeguro } from '../constants/rutas';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\nconst PAY_ICON: Record<string, React.ReactNode> = {\r\n  cash_on_delivery: <Banknote size={15} color={brand.success} />,\r\n  likebook_wallet: <Wallet size={15} color=\"#86909C\" />,\r\n  billing: <Building2 size={15} color={brand.primary} />,\r\n};\r\n\r\nexport default function LifeBookCheckoutScreen() {\r\n  return (\r\n    <AuthGate>\r\n      <CheckoutContent />\r\n    </AuthGate>\r\n  );\r\n}\r\n\r\nfunction CheckoutContent() {\r\n  const { productId, variantId, quantity: qtyParam, conversationId: convParam } = useLocalSearchParams<{ productId: string; variantId?: string; quantity?: string; conversationId?: string }>();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const { colors } = useTheme();\r\n\r\n  const quantity = Math.max(1, Math.min(99, Number(qtyParam ?? '1') || 1));\r\n  const [product, setProduct] = useState<LbProduct | null>(null);\r\n  const [loading, setLoading] = useState(true);\r\n  const [deliveryMode, setDeliveryMode] = useState('pickup');\r\n  const [paymentMethod, setPaymentMethod] = useState<string | null>(null);\r\n  /**\r\n   * PAGO CON EL MONEDERO (parche 97): el comprador confirma con su PIN y el dinero queda\r\n   * EN GARANTÍA hasta que reciba el pedido; entonces el vendedor cobra en SU monedero.\r\n   * El token de pago se pide al servidor justo antes de crear el pedido, con el importe\r\n   * exacto del total (si el total cambia, el token deja de valer: es a propósito).\r\n   */\r\n  const [pinOpen, setPinOpen] = useState(false);\r\n  const [pinBusy, setPinBusy] = useState(false);\r\n  const [pinErr, setPinErr] = useState<string | null>(null);\r\n  const [needSetPin, setNeedSetPin] = useState(false);\r\n  const [saldoMonedero, setSaldoMonedero] = useState<number | null>(null);\r\n  const [city, setCity] = useState('Malabo');\r\n  const [zone, setZone] = useState('');\r\n  const [reference, setReference] = useState('');\r\n  const [note, setNote] = useState('');\r\n  const [submitting, setSubmitting] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n  const mounted = useRef(true);\r\n  /** Una sola clave por compra: se reutiliza si el usuario reintenta. */\r\n  const idemKey = useRef<string>(Crypto.randomUUID());\r\n\r\n  /** Las formas de pago que de verdad se pueden elegir (el servidor manda el estado). */\r\n  const metodosActivos = useMemo(\r\n    () => (product?.paymentMethods ?? []).filter((m) => m.status === 'active'),\r\n    [product],\r\n  );\r\n\r\n  /** \r\n   * EL CUERPO EN BLANCO: CAUSA RAÍZ Y ARREGLO (15/09/2026).\r\n   *\r\n   * El pie llevaba el PrimaryButton del kit dentro de una FILA. Ese botón trae width: '100%'\r\n   * (pensado para ir a lo ancho de una columna): en la fila se comía TODO el ancho, la columna de\r\n   * totales quedaba a ~0 px, sus textos se partían letra por letra hasta ~2.133 px de alto, el pie\r\n   * pasaba a medir 2.110 px y el cuerpo (flex: 1) se quedaba con 0 → cuerpo en blanco.\r\n   * Medido: 2 textos en el árbol con el fallo, 24 después; pie a y=2.078-2.186 y no a 244.\r\n   * El botón va ahora en su propia caja de ancho fijo (ver el pie).\r\n   */\r\n\r\n  useEffect(() => {\r\n    mounted.current = true;\r\n    (async () => {\r\n      try {\r\n        const { product: p } = await commerceApi.product(String(productId));\r\n        if (!mounted.current) return;\r\n        setProduct(p);\r\n        setCity(p.originCity ?? p.shop.city ?? 'Malabo');\r\n        /**\r\n         * NADA de marcar una forma de pago sola… salvo que solo haya UNA.\r\n         *\r\n         * Antes se marcaba siempre la primera activa, y esa lista llega **ordenada alfabéticamente**\r\n         * («billing» la primera): todos los pedidos salían pagados por un método que nadie había\r\n         * elegido — lo reportó el dueño («a la hora de comprar no seleccionas el método de pago»).\r\n         * Si solo hay una forma de cobro no hay nada que elegir (obligar a tocar sería un paso tonto),\r\n         * pero con dos o más **elige quien compra**.\r\n         */\r\n        const activos = (p.paymentMethods ?? []).filter((m) => m.status === 'active');\r\n        if (activos.length === 1) setPaymentMethod(activos[0].method);\r\n      } catch (e) {\r\n        if (mounted.current) setError(e instanceof Error ? e.message : 'No se pudo cargar la publicación');\r\n      } finally {\r\n        if (mounted.current) setLoading(false);\r\n      }\r\n    })();\r\n    return () => { mounted.current = false; };\r\n  }, [productId]);\r\n\r\n  const variant = useMemo(\r\n    () => product?.variants.find((v) => v.id === variantId) ?? null,\r\n    [product, variantId],\r\n  );\r\n  const unitPrice = variant?.priceXaf ?? product?.priceXaf ?? 0;\r\n  const subtotal = unitPrice * quantity;\r\n\r\n  /** Modos de entrega reales de la tienda (+ recogida siempre). */\r\n  const deliveryOptions = useMemo(() => {\r\n    const modos = product?.shippingPolicy?.transportModes ?? [];\r\n    return ['pickup', ...modos.filter((m) => m !== 'pickup')];\r\n  }, [product]);\r\n\r\n  const policy = product?.shippingPolicy ?? null;\r\n  const envioAConsultar = deliveryMode !== 'pickup' && (!policy || policy.costMode === 'on_request');\r\n  const deliveryCost = deliveryMode === 'pickup' ? 0 : policy?.costMode === 'fixed' ? policy.baseCostXaf : 0;\r\n\r\n  /* ── TANDA Q: EL CUPÓN ───────────────────────────────────────────────────────────────────────\r\n   *\r\n   * Se piden MIS cupones al abrir la caja (no al pulsar pagar): el descuento tiene que verse ANTES\r\n   * de confirmar. Los de otras tiendas no se enseñan aquí: un cupón solo vale en su tienda.\r\n   * El descuento que se cobra lo decide el servidor; esto es solo el espejo para la pantalla.\r\n   */\r\n  const [cupones, setCupones] = useState<LbCupon[]>([]);\r\n  const [cuponElegido, setCuponElegido] = useState<string | null>(null);\r\n\r\n  useEffect(() => {\r\n    let vivo = true;\r\n    (async () => {\r\n      try {\r\n        const r = await cuponesApi.mios();\r\n        if (vivo) setCupones(r.items ?? []);\r\n      } catch { if (vivo) setCupones([]); }\r\n    })();\r\n    return () => { vivo = false; };\r\n  }, []);\r\n\r\n  const cuponesDeLaTienda = useMemo(\r\n    () => cupones.filter((c) => !c.shopId || c.shopId === product?.shop.id),\r\n    [cupones, product],\r\n  );\r\n  const cuponObj = useMemo(\r\n    () => cuponesDeLaTienda.find((c) => c.code === cuponElegido) ?? null,\r\n    [cuponesDeLaTienda, cuponElegido],\r\n  );\r\n  const descuento = descuentoDeCupon(cuponObj, subtotal);\r\n  const total = Math.max(0, subtotal + deliveryCost - descuento);\r\n\r\n  /** Recoger un cupón por su código y, si vale aquí, dejarlo aplicado. */\r\n  const recogerCupon = useCallback(async (code: string): Promise<string | null> => {\r\n    try {\r\n      await cuponesApi.recoger(code);\r\n      const r = await cuponesApi.mios();\r\n      const lista = r.items ?? [];\r\n      setCupones(lista);\r\n      const nuevo = lista.find((c) => c.code.toUpperCase() === code.toUpperCase());\r\n      if (nuevo && (!nuevo.shopId || nuevo.shopId === product?.shop.id)) setCuponElegido(nuevo.code);\r\n      return null;\r\n    } catch (e) {\r\n      return e instanceof Error ? e.message : 'No se pudo usar ese código';\r\n    }\r\n  }, [product]);\r\n\r\n  const confirmar = useCallback(async (paymentToken?: string) => {\r\n    if (!product || submitting) return;\r\n    /**\r\n     * Si falta algo, se DICE en el pie, junto al botón.\r\n     *\r\n     * Antes el aviso salía en un recuadro ARRIBA del todo —fuera de la pantalla cuando estás en el\r\n     * pie—, así que el botón parecía no hacer nada: es lo que reportó el dueño («el botón confirmar\r\n     * pagar no reacciona»).\r\n     */\r\n    if (!paymentMethod) {\r\n      setError(metodosActivos.length\r\n        ? 'Elige cómo pagas para poder confirmar'\r\n        : 'Esta tienda no tiene ninguna forma de pago activa');\r\n      return;\r\n    }\r\n    if (deliveryMode !== 'pickup' && (!city.trim() || (!zone.trim() && !reference.trim()))) {\r\n      setError('Para el reparto indica ciudad y barrio, o un punto de referencia');\r\n      return;\r\n    }\r\n    // Monedero: se pide el PIN antes de tocar nada (el dinero se retiene en la garantía).\r\n    if (paymentMethod === 'likebook_wallet' && !paymentToken) {\r\n      setPinErr(null); setNeedSetPin(false); setPinOpen(true);\r\n      return;\r\n    }\r\n    setSubmitting(true);\r\n    setError(null);\r\n    try {\r\n      const { order } = await commerceOrdersApi.create({\r\n        items: [{ productId: product.id, variantId: variant?.id ?? null, quantity }],\r\n        deliveryMode,\r\n        deliveryAddress: deliveryMode === 'pickup' ? {} : { city: city.trim(), zone: zone.trim(), reference: reference.trim() },\r\n        paymentMethod: paymentMethod as never,\r\n        note: note.trim() || undefined,\r\n        /* TANDA Q: el cupón elegido. Solo viaja el CÓDIGO: el descuento lo calcula el servidor. */\r\n        ...(cuponElegido ? { couponCode: cuponElegido } : {}),\r\n        /* MERCADO (tanda E): la compra nació en un chat → el pedido se publica allí como tarjeta.\r\n           Si el chat es un GRUPO, además con el aviso social. El servidor comprueba que de verdad\r\n           sea una conversación suya: aquí solo se transporta el identificador. */\r\n        ...(convParam ? { conversationId: String(convParam) } : {}),\r\n      }, idemKey.current, paymentToken);\r\n      irSeguro.libre('/lifebook-order/[id]', { id: order.id }, true);\r\n    } catch (e) {\r\n      const code = (e as { code?: string })?.code;\r\n      // PIN incorrecto o aún sin PIN: la hoja del PIN explica y permite crearlo.\r\n      if (paymentMethod === 'likebook_wallet' && (code === 'PIN_INVALID' || code === 'PIN_LOCKED' || code === 'PAYMENT_TOKEN_INVALID')) {\r\n        if (!needSetPin) {\r\n          setNeedSetPin(true);\r\n          setPinErr('Si es tu primer pago: escribe tu contraseña y elige tu PIN de 6 dígitos.');\r\n        } else {\r\n          setPinErr(e instanceof Error ? e.message : 'No se pudo confirmar el pago');\r\n        }\r\n        setPinOpen(true);\r\n      } else {\r\n        setError(e instanceof Error ? e.message : 'No se pudo crear el pedido');\r\n      }\r\n    } finally {\r\n      setSubmitting(false);\r\n    }\r\n  }, [product, variant, quantity, deliveryMode, paymentMethod, city, zone, reference, note, submitting, router, metodosActivos, cuponElegido, needSetPin]);\r\n\r\n  // Saldo del monedero al elegir pagar con él: saber si llega ANTES de intentarlo.\r\n  useEffect(() => {\r\n    if (paymentMethod !== 'likebook_wallet') { setSaldoMonedero(null); return; }\r\n    let vivo = true;\r\n    void walletApi.getWallet()\r\n      .then((w) => { if (vivo) setSaldoMonedero(Number(w.balanceAvailable ?? 0)); })\r\n      .catch(() => { if (vivo) setSaldoMonedero(null); });\r\n    return () => { vivo = false; };\r\n  }, [paymentMethod]);\r\n\r\n  /** PIN confirmado → token de pago del importe exacto → pedido. */  const pagarConMonedero = useCallback(async (pin: string, password?: string) => {\r\n    if (pinBusy) return;\r\n    setPinBusy(true); setPinErr(null);\r\n    try {\r\n      if (needSetPin) await fijarPin(pin, password);\r\n      const token = await walletApi.paymentToken(pin, 'ESCROW_LOCK', total);\r\n      setPinOpen(false);\r\n      await confirmar(token);\r\n    } catch (e) {\r\n      setPinErr(e instanceof Error ? e.message : 'No se pudo confirmar el pago');\r\n    } finally {\r\n      setPinBusy(false);\r\n    }\r\n  }, [pinBusy, needSetPin, total, confirmar]);\r\n\r\n  if (loading) {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\r\n        <ActivityIndicator color={colors.primary} />\r\n      </View>\r\n    );\r\n  }\r\n  if (!product) {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24, gap: espaciado.e12 }]}>\r\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', textAlign: 'center' }}>{error ?? 'No se pudo cargar'}</Text>\r\n        <GhostButton title=\"Volver\" onPress={() => irSeguro.atras()} />\r\n      </View>\r\n    );\r\n  }\r\n\r\n  const input = [styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }];\r\n\r\n  return (\r\n    /*\r\n      OJO, ESTO NO ES UN CAMBIO DE ESTILO: es un arreglo.\r\n\r\n      Antes aquí había un `KeyboardAvoidingView` (con `behavior` indefinido en Android, o sea, un\r\n      envoltorio que no hacía nada) y dentro un `ScrollView`. En el móvil el cuerpo salía **VACÍO**:\r\n      la cabecera y el pie sí, y todo lo del medio no —ni el artículo, ni «¿Cómo pagas?», ni las\r\n      formas de pago, ni el cupón—. Comprobado con el volcado de la pantalla y midiendo los píxeles:\r\n      esa zona era un color plano. Quitando el envoltorio, el mismo `ScrollView` con el mismo\r\n      contenido se pinta entero. Por eso ahora es un `View` normal.\r\n    */\r\n    <View\r\n      style={{ flex: 1, backgroundColor: colors.background }}\r\n    >\r\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\r\n        <Pressable onPress={() => irSeguro.atras()} hitSlop={10} accessibilityLabel=\"Volver\">\r\n          <ArrowLeft size={20} color={colors.textPrimary} />\r\n        </Pressable>\r\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10 }}>Finalizar pedido</Text>\r\n      </View>\r\n\r\n      {/*\r\n        EL CUERPO ES UN `View`, NO UN `ScrollView`. Y no es capricho: en el móvil, con un `ScrollView`\r\n        aquí, el cuerpo salía **VACÍO** (ni el artículo, ni «¿Cómo pagas?», ni las formas de pago, ni el\r\n        cupón: esa zona era un color plano, medido en los píxeles de la pantalla y en el volcado de la\r\n        interfaz). Comprobado aislándolo: un texto de prueba *dentro* del `ScrollView` tampoco salía, y\r\n        el mismo texto *fuera* sí. Con un `View` se pinta todo. Ver `TANDA-R`.\r\n      */}\r\n      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingTop: espaciado.e16, paddingBottom: espaciado.e24 }} keyboardShouldPersistTaps=\"handled\">\r\n        {error ? <Notice tone=\"error\">{error}</Notice> : null}\r\n\r\n        {/* Artículo */}\r\n        <View style={[styles.card, { borderColor: alpha(colors.border, 0.6), backgroundColor: colors.card }]}>\r\n          {product.media[0] ? (\r\n            <Image source={absUrl(product.media[0].url)} style={styles.thumb} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\r\n          ) : (\r\n            <View style={[styles.thumb, { backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }]}>\r\n              <Package size={20} color={alpha(colors.primary, 0.6)} />\r\n            </View>\r\n          )}\r\n          <View style={{ flex: 1 }}>\r\n            <Text numberOfLines={2} style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>{product.title}</Text>\r\n            {variant ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>Opción: {variant.name}</Text> : null}\r\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>Cantidad: {quantity}</Text>\r\n          </View>\r\n          <Text style={{ color: colors.primary, fontWeight: '900' }}>{lbXaf(subtotal)}</Text>\r\n        </View>\r\n\r\n        {/* Entrega */}\r\n        <Text style={[styles.section, { color: colors.textPrimary }]}>¿Cómo lo recibes?</Text>\r\n        <ChipRow>\r\n          {deliveryOptions.map((m) => (\r\n            <Chip\r\n              key={m}\r\n              label={m === 'pickup' ? 'Recoger en tienda' : lbTransportLabel(m)}\r\n              active={deliveryMode === m}\r\n              onPress={() => setDeliveryMode(m)}\r\n            />\r\n          ))}\r\n        </ChipRow>\r\n\r\n        {deliveryMode !== 'pickup' ? (\r\n          <View style={{ gap: espaciado.e8, marginTop: espaciado.e10 }}>\r\n            <Text style={[styles.label, { color: colors.textSecondary }]}>Ciudad</Text>\r\n            <ChipRow>\r\n              {LB_CITIES.map((c) => (\r\n                <Chip key={c} label={c} active={city === c} onPress={() => setCity(c)} compact />\r\n              ))}\r\n            </ChipRow>\r\n            <TextInput value={zone} onChangeText={setZone} placeholder=\"Barrio o zona (Ej: Ela Nguema)\"\r\n              placeholderTextColor={colors.textSecondary} maxLength={60} style={input} />\r\n            <TextInput value={reference} onChangeText={setReference} placeholder=\"Punto de referencia (Ej: portón azul, junto al mercado)\"\r\n              placeholderTextColor={colors.textSecondary} maxLength={200} style={input} />\r\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\r\n              <MapPin size={15} color={colors.primary} />\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, flex: 1 }}>\r\n                El pin del mapa y el teléfono se comparten con la tienda por el chat.\r\n              </Text>\r\n            </View>\r\n          </View>\r\n        ) : (\r\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e10 }}>\r\n            <Store size={15} color={colors.primary} />\r\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>\r\n              Recoges en {product.shop.name}{product.shop.barrio ? ` · ${product.shop.barrio}` : ''}\r\n            </Text>\r\n          </View>\r\n        )}\r\n\r\n        {/* Pago */}\r\n        <Text style={[styles.section, { color: colors.textPrimary }]}>¿Cómo pagas?</Text>\r\n        <View style={{ gap: espaciado.e8 }}>\r\n          {(product.paymentMethods ?? []).map((pm) => {\r\n            const meta = LB_PAY_METHODS.find((p) => p.id === pm.method);\r\n            const selectable = pm.status === 'active';\r\n            const active = paymentMethod === pm.method && selectable;\r\n            return (\r\n              <View key={pm.method} style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\r\n                <Chip\r\n                  label={meta?.label ?? lbPayLabel(pm.method)}\r\n                  icon={PAY_ICON[pm.method]}\r\n                  active={active}\r\n                  disabled={!selectable}\r\n                  onPress={() => setPaymentMethod(pm.method)}\r\n                />\r\n                {!selectable ? (\r\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>\r\n                    {LB_PAY_STATUS_LABEL[pm.status] ?? pm.status}\r\n                  </Text>\r\n                ) : null}\r\n              </View>\r\n            );\r\n          })}\r\n          {metodosActivos.length === 0 ? (\r\n            <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '700', lineHeight: 17 }}>\r\n              Esta tienda no tiene formas de pago activas: todavía no se puede pedir.\r\n            </Text>\r\n          ) : (\r\n            <Text style={{\r\n              color: paymentMethod ? colors.textSecondary : colors.danger,\r\n              fontSize: tipografia.body,\r\n              lineHeight: 17,\r\n              fontWeight: paymentMethod ? '400' : '700',\r\n            }}>\r\n              {!paymentMethod\r\n                ? 'Falta elegir cómo pagas.'\r\n                : paymentMethod === 'cash_on_delivery'\r\n                  ? 'Pagas en efectivo al recibir: la tienda te pedirá el código de entrega.'\r\n                  : paymentMethod === 'transfer' || paymentMethod === 'billing'\r\n                    ? 'Te enviaremos las instrucciones y subirás el comprobante; la tienda lo confirma y prepara el pedido.'\r\n                    : 'El pago se acuerda con la tienda.'}\r\n            </Text>\r\n          )}\r\n        </View>\r\n\r\n        {/* Cupón (tanda Q): aquí es donde se aplica y donde se ve el descuento antes de pagar. */}\r\n        <Text style={[styles.section, { color: colors.textPrimary }]}>Cupón</Text>\r\n        <SelectorDeCupon\r\n          cupones={cuponesDeLaTienda}\r\n          subtotalXaf={subtotal}\r\n          elegido={cuponElegido}\r\n          onElegir={setCuponElegido}\r\n          onRecoger={recogerCupon}\r\n        />\r\n\r\n        {/* Nota */}\r\n        <Text style={[styles.section, { color: colors.textPrimary }]}>Nota para la tienda (opcional)</Text>\r\n        <TextInput\r\n          value={note}\r\n          onChangeText={setNote}\r\n          placeholder=\"Ej.: llamar al llegar\"\r\n          placeholderTextColor={colors.textSecondary}\r\n          maxLength={300}\r\n          multiline\r\n          style={[input, styles.area]}\r\n        />\r\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e6 }}>\r\n          No pongas teléfonos ni enlaces: el contacto va por el chat de Life Book.\r\n        </Text>\r\n      </ScrollView>\r\n      {/* Totales y confirmar */}\r\n      <View\r\n        style={{\r\n        borderTopWidth: StyleSheet.hairlineWidth,\r\n        borderTopColor: alpha(colors.border, 0.6),\r\n        backgroundColor: colors.background,\r\n        paddingBottom: insets.bottom + 10,\r\n      }}>\r\n        {/*\r\n          EL MOTIVO, EN EL PIE. El recuadro de arriba se queda fuera de la pantalla cuando estás aquí\r\n          abajo, así que el botón parecía no hacer nada: es el fallo que reportó el dueño.\r\n        */}\r\n        {error ? (\r\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '700', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e9 }}>\r\n            {error}\r\n          </Text>\r\n        ) : null}\r\n        <View style={[styles.footer, { borderTopWidth: 0, paddingBottom: 0 }]}>\r\n          <View style={{ flex: 1 }}>\r\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>\r\n              Entrega: {envioAConsultar ? 'a acordar con la tienda' : lbXaf(deliveryCost)}\r\n            </Text>\r\n            {descuento > 0 ? (\r\n              <Text style={{ color: colors.success, fontSize: tipografia.body, fontWeight: '800' }}>\r\n                Cupón {cuponElegido}: −{lbXaf(descuento)}\r\n              </Text>\r\n            ) : null}\r\n            {/* Se ve ANTES de confirmar con qué se paga: era justo lo que faltaba. */}\r\n            <Text style={{\r\n              color: paymentMethod ? colors.textSecondary : colors.danger,\r\n              fontSize: tipografia.body,\r\n              fontWeight: paymentMethod ? '400' : '800',\r\n            }}>\r\n              {paymentMethod ? `Pagas: ${lbPayLabel(paymentMethod)}` : 'Elige cómo pagas'}\r\n            </Text>\r\n            <Text style={{ color: colors.textPrimary, fontSize: 19, fontWeight: '900' }}>Total: {lbXaf(total)}</Text>\r\n            {paymentMethod === 'likebook_wallet' && saldoMonedero !== null ? (\r\n              <Text style={{ color: saldoMonedero >= total ? brand.success : brand.dangerPressed, fontSize: tipografia.body, fontWeight: '700' }}>\r\n                Monedero: {lbXaf(saldoMonedero)}{saldoMonedero >= total ? '' : ' · no llega'}\r\n              </Text>\r\n            ) : null}\r\n          </View>\r\n          {/*\r\n            El botón NUNCA está muerto: si falta elegir, lo dice él mismo; solo se apaga cuando no\r\n            hay nada que elegir (la tienda no tiene ninguna forma de cobro).\r\n\r\n            ── Y VA EN SU PROPIA CAJA: ES EL ARREGLO DEL CUERPO EN BLANCO (15/09/2026) ──────────────\r\n            `PrimaryButton` del kit trae `width: '100%'` (línea 102 de\r\n            `node_modules/@egrouteplan/ui-kit/src/primitives/PrimaryButton.tsx`), pensado para ir a lo\r\n            ancho de una COLUMNA. Aquí está dentro de una FILA junto a la columna de totales: ese\r\n            100% se queda con TODO el ancho (botón de 984 px medidos), la columna se aplasta a ~0 px,\r\n            sus textos se parten letra por letra y crecen hasta ~2.133 px de alto → el pie pasa a\r\n            medir 2.110 px → el cuerpo (`flex: 1`) se queda con 0 px **y la pantalla sale en blanco**\r\n            (cabecera y pie sí, el medio no). Lo mismo rompía `lifebook-order/[id]`.\r\n            Con una caja de ancho fijo, el 100% es el de la caja y la columna respira.\r\n          */}\r\n          <View style={{ width: 176 }}>\r\n            <PrimaryButton\r\n              title={metodosActivos.length === 0 ? 'Sin forma de pago' : paymentMethod ? 'Confirmar pedido' : 'Elige cómo pagas'}\r\n              disabled={metodosActivos.length === 0}\r\n              loading={submitting}\r\n              /* Sin envolver: el botón pasa el EVENTO como primer argumento y se colaría\r\n                 como token de pago. Con monedero, la hoja del PIN pide el token. */\r\n              onPress={() => void confirmar()}\r\n            />\r\n          </View>\r\n        </View>\r\n      </View>\r\n\r\n      <PinSheet\r\n        visible={pinOpen}\r\n        title={`Pagar ${lbXaf(total)} con el monedero`}\r\n        subtitle={needSetPin\r\n          ? 'Primer pago: escribe tu contraseña y elige un PIN de 6 dígitos.'\r\n          : 'El dinero queda en garantía hasta que recibas el pedido.'}\r\n        busy={pinBusy}\r\n        error={pinErr}\r\n        needPassword={needSetPin}\r\n        confirmLabel={needSetPin ? 'Guardar PIN y pagar' : 'Confirmar pago'}\r\n        onClose={() => setPinOpen(false)}\r\n        onConfirm={(pin, pwd) => void pagarConMonedero(pin, pwd)}\r\n      />\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\r\n  header: {\r\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\r\n    borderBottomWidth: StyleSheet.hairlineWidth,\r\n  },\r\n  card: { flexDirection: 'row', gap: espaciado.e12, alignItems: 'center', borderWidth: StyleSheet.hairlineWidth, borderRadius: 14, padding: espaciado.e12 },\r\n  thumb: { width: 64, height: 64, borderRadius: 10 },\r\n  /** Las secciones van juntas: el cuerpo no se desplaza, así que el hueco cuenta. */\r\n  section: { fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e13, marginBottom: espaciado.e8 },\r\n  label: { fontSize: tipografia.body, fontWeight: '700' },\r\n  input: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\r\n  area: { minHeight: 70, textAlignVertical: 'top' },\r\n  footer: {\r\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\r\n    paddingHorizontal: espaciado.e16, paddingTop: espaciado.e10, borderTopWidth: StyleSheet.hairlineWidth,\r\n  },\r\n});\r\n","/**\n * components/lifebook/publish/PublishParts.tsx — piezas compartidas del asistente.\n * (Paso, campos y ayudas que usan todos los pasos.)\n */\nimport React from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport type { LbCategory, LbServiceType } from '../../../api/commerce';\n\n/**\n * ¿A QUÉ RAMA PERTENECE LA CATEGORÍA ELEGIDA?\n *\n * El catálogo del servidor viene en dos niveles: ramas («Ropa y calzado», «Electrónica», «Alimentos»)\n * y sus hijas («Calzado», «Teléfonos y tablets»…). El asistente buscaba **la primera rama del tipo**\n * y solo miraba SUS hijas: para un producto físico eso dejaba al comerciante en las hijas de la\n * primera rama (Abacería) y **no podía elegir «Ropa mujer» ni «Calzado»** —medido en el Poco F5—,\n * así que tampoco le salían los ejes sugeridos (talla, color). Esta función busca la rama que de\n * verdad contiene la categoría elegida, y sirve igual para los detalles y para las opciones.\n */\nexport function raizYCategoria(\n  categories: LbCategory[],\n  serviceType: LbServiceType,\n  categoryId: string | null,\n): { raices: LbCategory[]; raiz: LbCategory | null; sub: LbCategory | undefined } {\n  const raices = (categories ?? []).filter((c) => c.serviceType === serviceType);\n  if (categoryId) {\n    for (const r of raices) {\n      if (r.id === categoryId) return { raices, raiz: r, sub: undefined };\n      const sub = (r.children ?? []).find((h) => h.id === categoryId);\n      if (sub) return { raices, raiz: r, sub };\n    }\n  }\n  return { raices, raiz: raices[0] ?? null, sub: undefined };\n}\n\n/** Bloque de un paso: título, ayuda y contenido. */\nexport function StepBlock({ title, hint, children }: { title?: string; hint?: string; children: React.ReactNode }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ marginBottom: espaciado.e16 }}>\n      {title ? (\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', marginBottom: espaciado.e7 }}>{title}</Text>\n      ) : null}\n      {hint ? (\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e8 }}>{hint}</Text>\n      ) : null}\n      {children}\n    </View>\n  );\n}\n\n/** Aviso (error o información) con el color del tema. */\nexport function Notice({ tone = 'info', children }: { tone?: 'info' | 'error' | 'ok'; children: React.ReactNode }) {\n  const { colors } = useTheme();\n  const bg = tone === 'error' ? alpha(colors.danger, 0.1) : tone === 'ok' ? alpha(colors.success, 0.12) : alpha(colors.primary, 0.08);\n  const border = tone === 'error' ? colors.danger : tone === 'ok' ? colors.success : alpha(colors.primary, 0.3);\n  return (\n    <View style={[styles.notice, { backgroundColor: bg, borderColor: border }]}>\n      <Text style={{ color: tone === 'error' ? colors.danger : colors.textPrimary, fontSize: tipografia.caption, lineHeight: 18 }}>\n        {children}\n      </Text>\n    </View>\n  );\n}\n\n/** Filas clave/valor (resumen y vista previa). */\nexport function SummaryRow({ label, value }: { label: string; value: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.row}>\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{label}</Text>\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', flex: 1, textAlign: 'right' }} numberOfLines={2}>\n        {value}\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  notice: { borderWidth: 1, borderRadius: radios.md, padding: espaciado.e11, marginBottom: espaciado.e14 },\n  row: { flexDirection: 'row', justifyContent: 'space-between', gap: espaciado.e12, paddingVertical: espaciado.e6 },\n});\n","/**\r\n * Life Book — PUBLICAR NOTA (/lifebook-compose).\r\n * Nota: descripción 1-500 + título opcional ≤60 + 0-4 fotos + hasta 5 temas\r\n * (catálogo + hashtags libres) + tono + ubicación (ciudad default perfil,\r\n * barrio opcional) + visibilidad. Al publicar vuelve al feed (se recarga).\r\n * DISEÑO-UX-LIFEBOOK-PUBLICAR §3.1.\r\n */\r\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\r\nimport {\r\n  ActivityIndicator, Alert, Image, KeyboardAvoidingView, Platform, Pressable, ScrollView,\r\n  StyleSheet, Text, TextInput, View,\r\n} from 'react-native';\r\nimport { useRouter } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { ArrowLeft, Globe, ImagePlus, Lock, MapPin, Package, Send, Users, X } from 'lucide-react-native';\r\nimport { AuthGate } from '../core/AuthGate';\r\nimport { authApi } from '../api/auth';\r\nimport { lifebookApi, lifebookSettingsApi } from '../api/lifebook';\r\nimport { productosEnNotaApi } from '../api/lifebookProductos';\r\nimport { pickImagesFromLibrary, type PickedImage } from '../core/pickImage';\r\n/* TANDA C: la hoja de productos es COMPARTIDA con el flujo de vídeo (antes vivía copiada aquí). */\r\nimport { SelectorDeProductos } from '../components/lifebook/SelectorDeProductos';\r\n/* TANDA I: el buscador de sitios real (geocoder) que ya usan las rutas y las quedadas. */\r\nimport { LocationPickerSheet } from '../components/lifebook/LocationPickerSheet';\r\nimport {\r\n  LB_CITIES, LB_NOTE_BODY_MAX, LB_NOTE_MEDIA_MAX, LB_NOTE_TOPICS_MAX,\r\n  LB_NOTE_TITLE_MAX, LB_TAG_MAX_LEN, LB_TONE_OPTIONS, LB_TOPIC_CATALOG,\r\n  LB_VISIBILITY_OPTIONS, type LbVisibility,\r\n} from '../constants/lifebook';\r\n\r\nexport default function LifeBookComposeScreen() {\r\n  return (\r\n    <AuthGate>\r\n      <ComposeContent />\r\n    </AuthGate>\r\n  );\r\n}\r\n\r\nfunction ComposeContent() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n\r\n  const [city, setCity] = useState('Malabo');\r\n  const [barrio, setBarrio] = useState('');\r\n  const [title, setTitle] = useState('');\r\n  const [body, setBody] = useState('');\r\n  const [topics, setTopics] = useState<string[]>([]);\r\n  const [freeTag, setFreeTag] = useState('');\r\n  const [tone, setTone] = useState<string | null>(null);\r\n  const [visibility, setVisibility] = useState<LbVisibility>('public');\r\n  const visTouched = useRef(false);\r\n  const [photos, setPhotos] = useState<PickedImage[]>([]);\r\n  const [picking, setPicking] = useState(false);\r\n  const [sending, setSending] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  /* ── TANDA C: productos DENTRO de la nota ────────────────────────────────────────\r\n     El producto no vive solo en el catálogo: se engancha al contenido («mi rutina de la\r\n     mañana» y debajo la crema que usa). Solo se pueden enganchar productos de MI tienda (lo\r\n     valida el servidor); aquí solo se eligen. La HOJA que los elige es compartida\r\n     (`components/lifebook/SelectorDeProductos.tsx`): la misma que usa el flujo de vídeo. */\r\n  const [productos, setProductos] = useState<string[]>([]);\r\n  const [prodOpen, setProdOpen] = useState(false);\r\n  /** TANDA I: el sitio exacto de la nota (POI) y su buscador. */\r\n  const [sitio, setSitio] = useState<{ name: string; lat: number; lng: number } | null>(null);\r\n  const [sitioOpen, setSitioOpen] = useState(false);\r\n\r\n  useEffect(() => {\r\n    authApi.me().then((m) => { if (m?.city && (LB_CITIES as readonly string[]).includes(m.city)) setCity(m.city); }).catch(() => {});\r\n    // Ajustes: visibilidad por defecto al publicar (solo si el usuario no la cambió).\r\n    lifebookSettingsApi.get().then((s) => {\r\n      if (!visTouched.current && s?.publish?.defaultVisibility) setVisibility(s.publish.defaultVisibility);\r\n    }).catch(() => {});\r\n  }, []);\r\n\r\n  const canSend = useMemo(() => body.trim().length >= 1 && body.trim().length <= LB_NOTE_BODY_MAX && !sending, [body, sending]);\r\n\r\n  /**\r\n   * Abre la hoja de productos. La carga de «mis productos» la hace la propia hoja (compartida con\r\n   * el flujo de vídeo), para que no haya dos listas que puedan comportarse distinto.\r\n   */\r\n  const abrirProductos = () => setProdOpen(true);\r\n\r\n  const toggleTopic = (t: string) => {\r\n    setTopics((prev) => {\r\n      if (prev.includes(t)) return prev.filter((x) => x !== t);\r\n      if (prev.length >= LB_NOTE_TOPICS_MAX) return prev;\r\n      return [...prev, t];\r\n    });\r\n  };\r\n\r\n  const addFreeTag = () => {\r\n    let tag = freeTag.trim().replace(/\\s+/g, '_');\r\n    if (tag.startsWith('#')) tag = tag.slice(1);\r\n    tag = tag.toLowerCase();\r\n    if (!tag || tag.length > LB_TAG_MAX_LEN) return;\r\n    setTopics((prev) => {\r\n      if (prev.some((t) => t.toLowerCase() === tag) || prev.length >= LB_NOTE_TOPICS_MAX) return prev;\r\n      return [...prev, tag];\r\n    });\r\n    setFreeTag('');\r\n  };\r\n\r\n  const addPhotos = async () => {\r\n    if (picking || photos.length >= LB_NOTE_MEDIA_MAX) return;\r\n    setPicking(true);\r\n    try {\r\n      const picked = await pickImagesFromLibrary(LB_NOTE_MEDIA_MAX - photos.length);\r\n      setPhotos((prev) => [...prev, ...picked].slice(0, LB_NOTE_MEDIA_MAX));\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : 'No se pudo abrir la galería');\r\n    } finally { setPicking(false); }\r\n  };\r\n\r\n  /** Proporción (ancho/alto) de la 1ª foto para el 3:4 del feed. */\r\n  const coverRatioOf = (uri: string) => new Promise<number | null>((resolve) => {\r\n    try {\r\n      Image.getSize(uri, (w, h) => resolve(h > 0 ? w / h : null), () => resolve(null));\r\n    } catch { resolve(null); }\r\n  });\r\n\r\n  const publish = async () => {\r\n    if (!canSend) return;\r\n    setSending(true);\r\n    setError(null);\r\n    try {\r\n      const ratio = photos.length ? await coverRatioOf(photos[0].uri) : null;\r\n      await productosEnNotaApi.publicarNota({\r\n        body: body.trim(),\r\n        ...(title.trim() ? { title: title.trim().slice(0, LB_NOTE_TITLE_MAX) } : {}),\r\n        ...(photos.length ? { media: photos.map((p) => p.dataUrl) } : {}),\r\n        ...(ratio ? { coverRatio: ratio } : {}),\r\n        city,\r\n        ...(barrio.trim() ? { barrio: barrio.trim().slice(0, 90) } : {}),\r\n        ...(topics.length ? { topics } : {}),\r\n        ...(tone ? { tone } : {}),\r\n        // TANDA C: los productos van DENTRO de la nota (se pintan bajo el texto).\r\n        ...(productos.length ? { productIds: productos } : {}),\r\n        // TANDA I: el sitio exacto (POI), si se eligió uno.\r\n        ...(sitio ? { placeName: sitio.name, placeLat: sitio.lat, placeLng: sitio.lng } : {}),\r\n        visibility,\r\n      });\r\n      router.back();\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : 'No se pudo publicar. Inténtalo de nuevo.');\r\n      setSending(false);\r\n    }\r\n  };\r\n\r\n  return (\r\n    <KeyboardAvoidingView style={{ flex: 1, backgroundColor: colors.background }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\r\n      <View style={{ flex: 1, backgroundColor: colors.background }}>\r\n        {/* Barra */}\r\n        <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\r\n          <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}>\r\n            <ArrowLeft size={22} color={colors.textPrimary} />\r\n          </Pressable>\r\n          <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Publicar nota</Text>\r\n          <Pressable onPress={publish} disabled={!canSend} style={[styles.publishBtn, { backgroundColor: canSend ? colors.primary : alpha(colors.textSecondary, 0.25) }]}>\r\n            {sending ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>Publicar</Text>}\r\n          </Pressable>\r\n        </View>\r\n\r\n        <ScrollView keyboardShouldPersistTaps=\"handled\" showsVerticalScrollIndicator={false} contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }}>\r\n          {error ? (\r\n            <View style={[styles.errorBox, { backgroundColor: alpha(colors.danger, 0.09), borderColor: alpha(colors.danger, 0.4) }]}>\r\n              <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>{error}</Text>\r\n            </View>\r\n          ) : null}\r\n\r\n          {/* Descripción */}\r\n          <Text style={styles.label}>DESCRIPCIÓN *</Text>\r\n          <TextInput\r\n            value={body}\r\n            onChangeText={setBody}\r\n            multiline\r\n            placeholder=\"Comparte algo con tu ciudad: tu día, una noticia, una tradición…\"\r\n            placeholderTextColor={colors.textSecondary}\r\n            maxLength={LB_NOTE_BODY_MAX}\r\n            style={[styles.textArea, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\r\n          />\r\n          <Text style={[styles.counter, { color: colors.textSecondary }]}>{body.length}/{LB_NOTE_BODY_MAX}</Text>\r\n\r\n          {/* Título opcional */}\r\n          <Text style={styles.label}>TÍTULO (opcional)</Text>\r\n          <TextInput\r\n            value={title}\r\n            onChangeText={setTitle}\r\n            placeholder=\"Un título corto para tu nota\"\r\n            placeholderTextColor={colors.textSecondary}\r\n            maxLength={LB_NOTE_TITLE_MAX}\r\n            style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\r\n          />\r\n          <Text style={[styles.counter, { color: colors.textSecondary }]}>{title.length}/{LB_NOTE_TITLE_MAX}</Text>\r\n\r\n          {/* Fotos */}\r\n          <Text style={styles.label}>FOTOS ({photos.length}/{LB_NOTE_MEDIA_MAX})</Text>\r\n          <View style={styles.photoRow}>\r\n            {photos.map((p, i) => (\r\n              <View key={p.uri + i}>\r\n                <Image source={{ uri: p.uri }} style={styles.photo} />\r\n                <Pressable\r\n                  onPress={() => setPhotos((prev) => prev.filter((_, idx) => idx !== i))}\r\n                  style={[styles.photoX, { backgroundColor: 'rgba(0,0,0,0.6)' }]}\r\n                  accessibilityLabel=\"Quitar foto\"\r\n                >\r\n                  <X size={13} color={brand.white} />\r\n                </Pressable>\r\n                {i === 0 && photos.length > 1 ? (\r\n                  <Text style={styles.coverBadge}>1ª</Text>\r\n                ) : null}\r\n              </View>\r\n            ))}\r\n            {photos.length < LB_NOTE_MEDIA_MAX ? (\r\n              <Pressable onPress={addPhotos} style={[styles.addPhoto, { backgroundColor: colors.surface, borderColor: colors.border }]}>\r\n                {picking ? <ActivityIndicator color={colors.primary} /> : <ImagePlus size={22} color={colors.primary} />}\r\n                <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Añadir</Text>\r\n              </Pressable>\r\n            ) : null}\r\n          </View>\r\n\r\n          {/* TANDA C — productos que van DENTRO de la nota. Se eligen de MI tienda; el\r\n              servidor comprueba que son míos y que están activos. */}\r\n          <Pressable\r\n            onPress={() => { void abrirProductos(); }}\r\n            accessibilityLabel=\"Elegir productos para esta nota\"\r\n            style={[styles.chip, {\r\n              marginTop: espaciado.e14, alignSelf: 'flex-start', flexDirection: 'row', alignItems: 'center', gap: espaciado.e6,\r\n              backgroundColor: productos.length ? alpha(colors.primary, 0.14) : colors.surface,\r\n              borderColor: productos.length ? alpha(colors.primary, 0.55) : colors.border,\r\n            }]}\r\n          >\r\n            <Package size={14} color={productos.length ? colors.primary : colors.textSecondary} />\r\n            <Text style={{ color: productos.length ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\r\n              {productos.length\r\n                ? `${productos.length} producto${productos.length === 1 ? '' : 's'} en esta nota`\r\n                : 'Productos en esta nota (opcional)'}\r\n            </Text>\r\n          </Pressable>\r\n\r\n          {/* TANDA I — EL SITIO DE LA NOTA (POI). Es lo que permite que la nota salga en «cerca de\r\n              mí» (附近 / 3 km) y en «toda la ciudad» con su distancia. Se elige con el mismo\r\n              buscador de sitios que usan las rutas y las quedadas (`LocationPickerSheet`), que\r\n              busca de verdad (geocoder) y ofrece «mi ubicación». */}\r\n          <Pressable\r\n            onPress={() => setSitioOpen(true)}\r\n            accessibilityLabel=\"Elegir el sitio de la nota\"\r\n            style={[styles.chip, {\r\n              marginTop: espaciado.e10, alignSelf: 'flex-start', flexDirection: 'row', alignItems: 'center', gap: espaciado.e6,\r\n              backgroundColor: sitio ? alpha(colors.primary, 0.14) : colors.surface,\r\n              borderColor: sitio ? alpha(colors.primary, 0.55) : colors.border,\r\n            }]}\r\n          >\r\n            <MapPin size={14} color={sitio ? colors.primary : colors.textSecondary} />\r\n            <Text numberOfLines={1} style={{ color: sitio ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800', maxWidth: 240 }}>\r\n              {sitio ? `📍 ${sitio.name}` : '¿Dónde es? (opcional)'}\r\n            </Text>\r\n            {sitio ? (\r\n              <Pressable onPress={() => setSitio(null)} hitSlop={8} accessibilityLabel=\"Quitar el sitio\">\r\n                <X size={13} color={colors.primary} />\r\n              </Pressable>\r\n            ) : null}\r\n          </Pressable>\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e5, lineHeight: 15 }}>\r\n            Con un sitio exacto, tu nota aparece en «Ciudad» con su distancia (y en «cerca de mí»).\r\n          </Text>\r\n\r\n          {/* Temas */}\r\n          <Text style={styles.label}>TEMAS ({topics.length}/{LB_NOTE_TOPICS_MAX})</Text>\r\n          <View style={styles.chipsWrap}>\r\n            {LB_TOPIC_CATALOG.map((t) => {\r\n              const on = topics.includes(t);\r\n              return (\r\n                <Pressable\r\n                  key={t}\r\n                  onPress={() => toggleTopic(t)}\r\n                  style={[styles.chip, { backgroundColor: on ? alpha(colors.primary, 0.14) : colors.surface, borderColor: on ? alpha(colors.primary, 0.55) : colors.border }]}\r\n                >\r\n                  <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{t}</Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </View>\r\n          <View style={styles.tagRow}>\r\n            <TextInput\r\n              value={freeTag}\r\n              onChangeText={setFreeTag}\r\n              onSubmitEditing={addFreeTag}\r\n              placeholder=\"# hashtag libre (p. ej. #Malabo)\"\r\n              placeholderTextColor={colors.textSecondary}\r\n              returnKeyType=\"done\"\r\n              style={[styles.input, { flex: 1, backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\r\n            />\r\n            <Pressable onPress={addFreeTag} style={[styles.addTag, { backgroundColor: colors.surface, borderColor: colors.border }]} disabled={!freeTag.trim()}>\r\n              <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.title }}>＋</Text>\r\n            </Pressable>\r\n          </View>\r\n          {topics.length > 0 && (\r\n            <View style={styles.chipsWrap}>\r\n              {topics.map((t) => (\r\n                <Pressable key={t} onPress={() => toggleTopic(t)} style={[styles.chip, { backgroundColor: alpha(colors.secondary, 0.12), borderColor: alpha(colors.secondary, 0.5) }]}>\r\n                  <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '800' }}>#{t} ✕</Text>\r\n                </Pressable>\r\n              ))}\r\n            </View>\r\n          )}\r\n\r\n          {/* Tono */}\r\n          <Text style={styles.label}>TONO</Text>\r\n          <View style={styles.chipsWrap}>\r\n            {LB_TONE_OPTIONS.map((o) => {\r\n              const on = tone === o.value;\r\n              return (\r\n                <Pressable\r\n                  key={o.value}\r\n                  onPress={() => setTone(on ? null : o.value)}\r\n                  style={[styles.chip, { backgroundColor: on ? alpha(colors.secondary, 0.14) : colors.surface, borderColor: on ? alpha(colors.secondary, 0.6) : colors.border }]}\r\n                >\r\n                  <Text style={{ color: on ? colors.secondary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{o.label}</Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </View>\r\n\r\n          {/* Ubicación */}\r\n          <Text style={styles.label}>CIUDAD *</Text>\r\n          <View style={styles.chipsWrap}>\r\n            {LB_CITIES.map((c) => {\r\n              const on = city === c;\r\n              return (\r\n                <Pressable\r\n                  key={c}\r\n                  onPress={() => setCity(c)}\r\n                  style={[styles.chip, { backgroundColor: on ? alpha(colors.primary, 0.14) : colors.surface, borderColor: on ? alpha(colors.primary, 0.55) : colors.border }]}\r\n                >\r\n                  <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{c}</Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </View>\r\n          <Text style={styles.label}>BARRIO (opcional)</Text>\r\n          <TextInput\r\n            value={barrio}\r\n            onChangeText={setBarrio}\r\n            placeholder=\"p. ej. Semu, Ela Nguema…\"\r\n            placeholderTextColor={colors.textSecondary}\r\n            maxLength={90}\r\n            style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\r\n          />\r\n\r\n          {/* Visibilidad */}\r\n          <Text style={styles.label}>VISIBILIDAD</Text>\r\n          <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\r\n            {LB_VISIBILITY_OPTIONS.map((o) => {\r\n              const on = visibility === o.value;\r\n              const Icon = o.value === 'public' ? Globe : o.value === 'followers' ? Users : Lock;\r\n              return (\r\n                <Pressable\r\n                  key={o.value}\r\n                  onPress={() => { visTouched.current = true; setVisibility(o.value); }}\r\n                  style={[styles.visBtn, { backgroundColor: on ? alpha(colors.primary, 0.12) : colors.surface, borderColor: on ? alpha(colors.primary, 0.55) : colors.border }]}\r\n                >\r\n                  <Icon size={15} color={on ? colors.primary : colors.textSecondary} />\r\n                  <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{o.label}</Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </View>\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>\r\n            {LB_VISIBILITY_OPTIONS.find((o) => o.value === visibility)?.hint}\r\n          </Text>\r\n\r\n          {/* Publicar */}\r\n          <Pressable onPress={publish} disabled={!canSend} style={[styles.bigPublish, { backgroundColor: canSend ? colors.primary : alpha(colors.textSecondary, 0.25), marginBottom: espaciado.e8 }]}>\r\n            {sending ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Send size={18} color={brand.white} />}\r\n            <Text style={{ color: brand.white, fontSize: tipografia.subtitle, fontWeight: '900' }}>Publicar nota</Text>\r\n          </Pressable>\r\n        </ScrollView>\r\n      </View>\r\n\r\n      {/* ── TANDA C: selector de productos para esta nota (hoja COMPARTIDA con el flujo de vídeo) ── */}\r\n      {/* TANDA I: buscador de sitios para el POI de la nota. */}\r\n      <LocationPickerSheet\r\n        visible={sitioOpen}\r\n        onClose={() => setSitioOpen(false)}\r\n        title=\"¿Dónde es esta nota?\"\r\n        onSubmit={(loc) => { setSitio({ name: loc.label, lat: loc.lat, lng: loc.lng }); setSitioOpen(false); }}\r\n      />\r\n\r\n      <SelectorDeProductos\r\n        visible={prodOpen}\r\n        onClose={() => setProdOpen(false)}\r\n        seleccion={productos}\r\n        onCambiar={setProductos}\r\n        titulo=\"Productos en esta nota\"\r\n        ayuda=\"Se verán DENTRO de la nota, debajo del texto, en el orden en que los elijas.\"\r\n      />\r\n    </KeyboardAvoidingView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\r\n  topTitle: { fontSize: tipografia.subtitle, fontWeight: '900', flex: 1 },\r\n  publishBtn: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, minWidth: 74, alignItems: 'center' },\r\n  label: { fontSize: tipografia.caption, fontWeight: '900', color: '#86909C', letterSpacing: 0.8, marginTop: espaciado.e16, marginBottom: espaciado.e6 },\r\n  textArea: { borderRadius: 14, borderWidth: 1, padding: espaciado.e12, fontSize: 15, minHeight: 110, textAlignVertical: 'top' },\r\n  input: { borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9, fontSize: tipografia.body },\r\n  counter: { fontSize: 10.5, textAlign: 'right', marginTop: espaciado.e3 },\r\n  photoRow: { flexDirection: 'row', gap: espaciado.e8, flexWrap: 'wrap' },\r\n  photo: { width: 74, height: 74, borderRadius: radios.md, backgroundColor: '#EEE' },\r\n  photoX: { position: 'absolute', top: -6, right: -6, borderRadius: 10, width: 20, height: 20, alignItems: 'center', justifyContent: 'center' },\r\n  coverBadge: { position: 'absolute', bottom: 4, left: 4, backgroundColor: 'rgba(0,0,0,0.6)', color: brand.white, fontSize: 9, fontWeight: '900', borderRadius: 6, overflow: 'hidden', paddingHorizontal: espaciado.e5, paddingVertical: 1 },\r\n  addPhoto: { width: 74, height: 74, borderRadius: radios.md, borderWidth: 1, borderStyle: 'dashed', alignItems: 'center', justifyContent: 'center', gap: espaciado.e2 },\r\n  chipsWrap: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e7 },\r\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e6, borderWidth: 1, borderColor: 'transparent' },\r\n  tagRow: { flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 },\r\n  addTag: { borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e13, justifyContent: 'center' },\r\n  visBtn: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, borderRadius: radios.md, paddingVertical: espaciado.e10, borderWidth: 1 },\r\n  bigPublish: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, borderRadius: radios.full, paddingVertical: espaciado.e14, marginTop: espaciado.e22 },\r\n  errorBox: { borderRadius: radios.md, borderWidth: 1, padding: espaciado.e10, marginBottom: espaciado.e4 },\r\n});\r\n\r\n\r\n","/**\n * SelectorDeProductos — «productos dentro del contenido» (Mercado · tanda C).\n *\n * Una nota o un vídeo pueden llevar productos enganchados: se ven **debajo del texto** en las notas\n * y como **sticker sobre el reproductor** en los vídeos. Esta hoja es la que los elige, y es la\n * MISMA en las dos pantallas: antes vivía copiada dentro del compositor de notas, y el flujo de\n * **publicar vídeo** no la tenía (un vídeo solo podía llevar productos por API).\n *\n * Reglas que la hoja hace cumplir (y dice en voz alta):\n *  · Solo productos **de mi tienda** (lo valida también el servidor: uno ajeno se ignora).\n *  · El **orden** en que se eligen es el orden en que se ven: por eso van numerados.\n *  · Tope de productos (`max`): al pasarse, se avisa en vez de aceptarlo en silencio.\n */\nimport React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, Alert, Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Package, X } from 'lucide-react-native';\nimport { absUrl } from '../../api/config';\nimport { productosEnNotaApi, MAX_PRODUCTOS_POR_NOTA } from '../../api/lifebookProductos';\nimport type { LbProductCard } from '../../api/commerce';\n\nexport function SelectorDeProductos({ visible, onClose, seleccion, onCambiar, titulo, ayuda, max = MAX_PRODUCTOS_POR_NOTA }: {\n  visible: boolean;\n  onClose: () => void;\n  /** Ids elegidos, EN ORDEN. */\n  seleccion: string[];\n  /** Nuevo orden/lista al tocar un producto. */\n  onCambiar: (ids: string[]) => void;\n  /** «Productos en esta nota» · «Productos en este vídeo». */\n  titulo: string;\n  /** Dónde y cómo se verán (una línea de ayuda, distinta en cada pantalla). */\n  ayuda: string;\n  max?: number;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [misProds, setMisProds] = useState<LbProductCard[] | null>(null);\n\n  useEffect(() => {\n    if (!visible) return;\n    let vivo = true;\n    setMisProds(null);\n    productosEnNotaApi.misProductos()\n      .then((r) => { if (vivo) setMisProds((r.items ?? []).filter((p) => (p as { status?: string }).status === 'active')); })\n      .catch(() => { if (vivo) setMisProds([]); });\n    return () => { vivo = false; };\n  }, [visible]);\n\n  const alternar = (id: string) => {\n    if (seleccion.includes(id)) {\n      onCambiar(seleccion.filter((x) => x !== id));\n      return;\n    }\n    if (seleccion.length >= max) {\n      Alert.alert(`Ya hay ${max}`, 'Más productos saturan la lectura: deja los que de verdad salen.');\n      return;\n    }\n    onCambiar([...seleccion, id]);\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' }} onPress={onClose} />\n      <View style={{ backgroundColor: colors.card, borderTopLeftRadius: 18, borderTopRightRadius: 18, padding: espaciado.e16, paddingBottom: insets.bottom + 16, maxHeight: '80%' }}>\n        <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e4 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900', flex: 1 }}>{titulo}</Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>\n          {ayuda} (máximo {max}). Solo puedes enganchar productos de tu propia tienda.\n        </Text>\n\n        {misProds === null ? (\n          <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e26 }} />\n        ) : misProds.length === 0 ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingVertical: espaciado.e22 }}>\n            No tienes productos activos. Publica uno en tu tienda y podrás enseñarlo dentro de tus publicaciones.\n          </Text>\n        ) : (\n          <ScrollView contentContainerStyle={{ gap: espaciado.e8 }} style={{ maxHeight: 400 }}>\n            {misProds.map((p) => {\n              const puesto = seleccion.indexOf(p.id);\n              const on = puesto >= 0;\n              return (\n                <Pressable\n                  key={p.id}\n                  onPress={() => alternar(p.id)}\n                  accessibilityRole=\"checkbox\"\n                  accessibilityState={{ checked: on }}\n                  accessibilityLabel={`Producto ${p.title}`}\n                  style={{\n                    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, padding: espaciado.e8, borderRadius: radios.md, borderWidth: 1,\n                    borderColor: on ? colors.primary : alpha(colors.border, 0.6),\n                    backgroundColor: on ? alpha(colors.primary, 0.08) : colors.surface,\n                  }}\n                >\n                  {p.coverUrl ? (\n                    <Image source={{ uri: absUrl(p.coverUrl) }} style={styles.mini} />\n                  ) : (\n                    <View style={[styles.mini, { alignItems: 'center', justifyContent: 'center', backgroundColor: alpha(colors.primary, 0.08) }]}>\n                      <Package size={18} color={alpha(colors.primary, 0.6)} />\n                    </View>\n                  )}\n                  <View style={{ flex: 1 }}>\n                    <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{p.title}</Text>\n                    <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                      {p.priceXaf === null ? 'Precio a consultar' : `${p.priceXaf} XAF`}\n                    </Text>\n                  </View>\n                  {on ? (\n                    <View style={{ width: 26, height: 26, borderRadius: 13, backgroundColor: colors.primary, alignItems: 'center', justifyContent: 'center' }}>\n                      <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>{puesto + 1}</Text>\n                    </View>\n                  ) : (\n                    <Text style={{ color: colors.textSecondary, fontSize: 18, fontWeight: '900' }}>+</Text>\n                  )}\n                </Pressable>\n              );\n            })}\n          </ScrollView>\n        )}\n\n        <Pressable\n          onPress={onClose}\n          accessibilityLabel=\"Listo\"\n          style={[styles.listo, { backgroundColor: colors.primary }]}\n        >\n          <Text style={{ color: brand.white, fontSize: 15, fontWeight: '900' }}>\n            {seleccion.length ? `Listo (${seleccion.length})` : 'Listo'}\n          </Text>\n        </Pressable>\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  mini: { width: 44, height: 44, borderRadius: 10 },\n  listo: { borderRadius: 14, paddingVertical: espaciado.e13, alignItems: 'center', justifyContent: 'center', marginTop: espaciado.e12 },\n});\n","﻿/**\n * app/lifebook-dinero.tsx — EL DINERO DE MI TIENDA (panel del comerciante).\n *\n * ── POR QUÉ EXISTE (decisión del dueño, 18/09/2026) ─────────────────────────────\n * «Sin esto el vendedor no sabe si gana dinero dentro de la app»: hasta ahora la tienda cobraba en mano\n * y no tenía dónde mirar cuánto había vendido, cuánto se queda la plataforma y cuánto le falta por\n * cobrar. El servidor ya lo sabe (`GET /lifebook/commerce/money/balance`, con la comisión congelada por\n * pedido y el libro de doble partida detrás); esta pantalla es la puerta.\n *\n * ── LO QUE ENSEÑA, Y POR QUÉ ASÍ ────────────────────────────────────────────────\n *   · **Facturado** (lo que han pagado los compradores por sus productos, sin el reparto).\n *   · **Comisión** de la plataforma (8 % con mínimo de 500 XAF y tope del 40 %: lo decide el servidor).\n *   · **A pagar a la tienda** (facturado − comisión).\n *   · **Pendiente de cobrar**: lo que ya se le puede pagar.\n *   · **En espera**: lo de pedidos entregados hace menos de 7 días, porque el comprador todavía puede\n *     reclamar. Se dice con esas palabras para que nadie piense que se lo han quedado.\n *   · Las **liquidaciones** que ya se le hicieron (cuándo, cuánto y por cuántos pedidos).\n *\n * Los números los calcula el SERVIDOR: aquí no se suma ni se redondea nada, para que la pantalla y el\n * libro de cuentas no puedan decir cosas distintas.\n */\nimport React, { useCallback, useRef, useState } from 'react';\nimport { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AlertCircle, ArrowLeft, Info, Wallet } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { commerceOrdersApi, type LbSaldoTienda } from '../api/commerce';\nimport { lbXaf } from '../constants/lifebook';\n\nexport default function LifeBookDineroScreen() {\n  return (\n    <AuthGate>\n      <DineroContent />\n    </AuthGate>\n  );\n}\n\nfunction DineroContent() {\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n  const [saldo, setSaldo] = useState<LbSaldoTienda | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [cargando, setCargando] = useState(false);\n  const mounted = useRef(true);\n\n  const cargar = useCallback(async (shopId?: string) => {\n    setCargando(true);\n    try {\n      const r = await commerceOrdersApi.saldo(shopId);\n      if (mounted.current) { setSaldo(r); setError(null); }\n    } catch (e) {\n      if (mounted.current) setError(e instanceof Error ? e.message : 'No se pudo cargar el dinero de la tienda');\n    } finally {\n      if (mounted.current) setCargando(false);\n    }\n  }, []);\n\n  useFocusEffect(useCallback(() => {\n    mounted.current = true;\n    cargar();\n    return () => { mounted.current = false; };\n  }, [cargar]));\n\n  if (error && !saldo) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24, gap: espaciado.e12 }]}>\n        <AlertCircle size={34} color={colors.danger} />\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', textAlign: 'center' }}>{error}</Text>\n        <GhostButton title=\"Volver\" onPress={() => router.back()} />\n      </View>\n    );\n  }\n  if (!saldo) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  const fila = (etiqueta: string, valor: string, destacado = false) => (\n    <View key={etiqueta} style={[styles.fila, { borderBottomColor: alpha(colors.border, 0.4) }]}>\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, flex: 1 }}>{etiqueta}</Text>\n      <Text style={{ color: destacado ? colors.primary : colors.textPrimary, fontSize: destacado ? 16 : 14, fontWeight: '800' }}>\n        {valor}\n      </Text>\n    </View>\n  );\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10, flex: 1 }} numberOfLines={1}>\n          El dinero de mi tienda\n        </Text>\n        <Wallet size={18} color={colors.primary} />\n      </View>\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e28 }}\n        refreshControl={<RefreshControl refreshing={cargando} onRefresh={() => cargar(saldo.shop.id)} tintColor={colors.primary} />}\n      >\n        <Text style={{ color: colors.textPrimary, fontSize: 18, fontWeight: '900' }}>{saldo.shop.name}</Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n          {saldo.pedidos === 1 ? '1 pedido entregado' : `${saldo.pedidos} pedidos entregados`}\n        </Text>\n\n        {/* Si la cuenta tiene más de una tienda, se puede cambiar sin salir. */}\n        {saldo.tiendas.length > 1 ? (\n          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e12 }}>\n            {saldo.tiendas.map((t) => (\n              <Pressable\n                key={t.id}\n                onPress={() => cargar(t.id)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Ver el dinero de ${t.name}`}\n                style={[styles.chip, {\n                  borderColor: t.id === saldo.shop.id ? colors.primary : alpha(colors.border, 0.9),\n                  backgroundColor: t.id === saldo.shop.id ? alpha(colors.primary, 0.12) : 'transparent',\n                }]}\n              >\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{t.name}</Text>\n              </Pressable>\n            ))}\n          </View>\n        ) : null}\n\n        {/* Lo que hay que cobrar, en grande: es lo que el vendedor viene a ver. */}\n        <View style={[styles.tarjeta, { borderColor: alpha(colors.border, 0.6), marginTop: espaciado.e14 }]}>\n          {fila('Pendiente de cobrar', lbXaf(saldo.pendienteXaf), true)}\n          {fila('En espera (7 días para reclamar)', lbXaf(saldo.enEsperaXaf))}\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingTop: espaciado.e12 }}>\n            <Info size={14} color={colors.textSecondary} />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, flex: 1 }}>\n              El dinero de un pedido entregado hace menos de 7 días espera a que el comprador ya no pueda\n              reclamar. No se ha perdido: se paga después.\n            </Text>\n          </View>\n        </View>\n\n        <Text style={[styles.seccion, { color: colors.textPrimary }]}>Lo que has vendido</Text>\n        <View style={[styles.tarjeta, { borderColor: alpha(colors.border, 0.6) }]}>\n          {fila('Facturado (productos)', lbXaf(saldo.facturadoXaf))}\n          {fila('Comisión de la plataforma', saldo.comisionXaf > 0 ? `−${lbXaf(saldo.comisionXaf)}` : lbXaf(0))}\n          {fila('A pagar a tu tienda', lbXaf(saldo.aPagarTotalXaf), true)}\n        </View>\n\n        <Text style={[styles.seccion, { color: colors.textPrimary }]}>Liquidaciones</Text>\n        {saldo.liquidaciones.length === 0 ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n            Todavía no se te ha liquidado nada. Cuando venza la ventana de reclamación, lo pendiente\n            aparecerá aquí con su fecha.\n          </Text>\n        ) : (\n          <View style={[styles.tarjeta, { borderColor: alpha(colors.border, 0.6) }]}>\n            {saldo.liquidaciones.map((l) => (\n              <View key={l.id} style={[styles.fila, { borderBottomColor: alpha(colors.border, 0.4) }]}>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>{lbXaf(l.importeXaf)}</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>\n                    {new Date(l.pagadoAt).toLocaleDateString()} · {l.pedidos === 1 ? '1 pedido' : `${l.pedidos} pedidos`}\n                    {l.nota ? ` · ${l.nota}` : ''}\n                  </Text>\n                </View>\n                <Text style={{ color: colors.success, fontSize: tipografia.caption, fontWeight: '800' }}>Pagada</Text>\n              </View>\n            ))}\n          </View>\n        )}\n\n        <View style={{ marginTop: espaciado.e18 }}>\n          <GhostButton title=\"Ver mis pedidos\" onPress={() => router.push('/lifebook-orders' as never)} />\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  tarjeta: { borderWidth: StyleSheet.hairlineWidth, borderRadius: 14, padding: espaciado.e14 },\n  fila: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingVertical: espaciado.e9, borderBottomWidth: StyleSheet.hairlineWidth, gap: espaciado.e10,\n  },\n  seccion: { fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e20, marginBottom: espaciado.e8 },\n  chip: { borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\n});\n","/**\n * Life Book — EXPLORAR (/lifebook-explore)\n *\n * Grid de descubrimiento con datos REALES (no mock):\n *  - Buscador (abre la pantalla de búsqueda con tendencias y sugerencias).\n *  - Filtros: tipo de publicación (hoja) + ciudad (chips).\n *  - Canales en una fila horizontal (los 13 del feed).\n *  - Masonry de 2 columnas con `PostCard` v2, pull-to-refresh y paginación.\n *\n * API: GET /lifebook/posts/feed?channel=&city=&type=&cursor=&limit=\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useWindowDimensions } from 'react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { RefreshCw, Search, SlidersHorizontal, X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { Alert } from 'react-native';\nimport {\n  lifebookActionsApi, lifebookApi,\n  LB_CARD_DEFAULT_RATIO, toPostCard,\n  type LbPostBase, type LbPostCard,\n} from '../api/lifebook';\nimport { LB_CHANNELS, LB_CITIES } from '../constants/lifebook';\nimport { PostCard } from '../components/lifebook/PostCard';\nimport { ReportSheet } from '../components/lifebook/ReportSheet';\nimport { formaHoja } from '../components/lifebook/ui/Sheet';\nimport DockFooter, { DOCK_BODY_H, type FooterTab } from '../components/FloatingFooter';\nimport { useAppDock } from '../core/useAppDock';\n\n/** Filtros de tipo reales del feed (`type`). */\nconst TYPE_FILTERS = [\n  { id: '', label: 'Todo' },\n  { id: 'note', label: 'Notas' },\n  { id: 'video', label: 'Vídeos' },\n  { id: 'podcast', label: 'Podcasts' },\n  { id: 'serie', label: 'Series' },\n  { id: 'sale', label: 'Ventas' },\n  { id: 'service', label: 'Servicios' },\n  { id: 'debate', label: 'Debates' },\n] as const;\n\nexport default function LifeBookExploreScreen() {\n  return (\n    <AuthGate>\n      <ExploreContent />\n    </AuthGate>\n  );\n}\n\nfunction ExploreContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { width: screenW } = useWindowDimensions();\n  const navigate = useAppDock('lifebook');\n\n  const GAP = 8;\n  const PADDING = 12;\n  const colWidth = Math.floor((screenW - PADDING * 2 - GAP) / 2);\n\n  const [query, setQuery] = useState('');\n  const [channel, setChannel] = useState('for_you');\n  const [city, setCity] = useState<string | null>(null);\n  const [type, setType] = useState<string>('');\n  const [filtersOpen, setFiltersOpen] = useState(false);\n  const [posts, setPosts] = useState<LbPostCard[]>([]);\n  const [cursor, setCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [reportTarget, setReportTarget] = useState<LbPostCard | null>(null);\n\n  const busy = useRef(false);\n  const mounted = useRef(true);\n\n  useEffect(() => {\n    mounted.current = true;\n    return () => { mounted.current = false; };\n  }, []);\n\n  /* ── Carga real desde el feed ── */\n  const load = useCallback(async (mode: 'initial' | 'refresh' = 'initial') => {\n    if (busy.current) return;\n    busy.current = true;\n    if (mode === 'initial') setLoading(true); else setRefreshing(true);\n    setError(null);\n    try {\n      const page = await lifebookApi.feed(channel, {\n        city: city ?? undefined,\n        type: type || undefined,\n        limit: 20,\n      });\n      if (!mounted.current) return;\n      setPosts((page.posts ?? []).map(toPostCard));\n      setCursor(page.nextCursor ?? null);\n    } catch (e) {\n      if (mounted.current) setError(e instanceof Error ? e.message : 'No se pudo cargar');\n    } finally {\n      busy.current = false;\n      if (mounted.current) { setLoading(false); setRefreshing(false); }\n    }\n  }, [channel, city, type]);\n\n  useEffect(() => { load('initial'); }, [load]);\n\n  const loadMore = useCallback(async () => {\n    if (!cursor || loadingMore || busy.current) return;\n    setLoadingMore(true);\n    try {\n      const page = await lifebookApi.feed(channel, { city: city ?? undefined, type: type || undefined, cursor, limit: 20 });\n      if (!mounted.current) return;\n      setPosts((prev) => {\n        const seen = new Set(prev.map((p) => p.id));\n        return [...prev, ...(page.posts ?? []).map(toPostCard).filter((p) => !seen.has(p.id))];\n      });\n      setCursor(page.nextCursor ?? null);\n    } catch { /* silencioso */ }\n    finally { if (mounted.current) setLoadingMore(false); }\n  }, [channel, city, type, cursor, loadingMore]);\n\n  /* ── Filtro de texto en cliente sobre lo ya cargado ── */\n  const visible = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    if (!q) return posts;\n    return posts.filter((p) => `${p.title} ${p.body ?? ''} ${p.topicLabel ?? ''} ${p.author?.name ?? ''}`\n      .toLowerCase().includes(q));\n  }, [posts, query]);\n\n  /* ── Masonry (mismo reparto por altura que el feed) ── */\n  const { leftCol, rightCol } = useMemo(() => {\n    const left: LbPostCard[] = [];\n    const right: LbPostCard[] = [];\n    let hL = 0;\n    let hR = 0;\n    for (const p of visible) {\n      const h = colWidth / (p.media?.aspectRatio ?? LB_CARD_DEFAULT_RATIO) + 78;\n      if (hL <= hR) { left.push(p); hL += h; } else { right.push(p); hR += h; }\n    }\n    return { leftCol: left, rightCol: right };\n  }, [visible, colWidth]);\n\n  const onDockNavigate = (t: FooterTab) => navigate(t);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Header: buscar + filtros */}\n      <View style={styles.header}>\n        <Pressable\n          onPress={() => router.push('/lifebook-search' as never)}\n          style={[styles.searchBox, { backgroundColor: colors.surface }]}\n          accessibilityRole=\"search\"\n          accessibilityLabel=\"Buscar en Life Book\"\n        >\n          <Search size={16} color={colors.textSecondary} />\n          <Text style={{ flex: 1, marginLeft: espaciado.e6, color: colors.textSecondary, fontSize: tipografia.body }}>\n            {query || 'Buscar comida, taxi, debates…'}\n          </Text>\n        </Pressable>\n        <Pressable\n          style={styles.filterBtn}\n          hitSlop={8}\n          onPress={() => setFiltersOpen(true)}\n          accessibilityLabel=\"Filtros\"\n        >\n          <SlidersHorizontal size={18} color={type ? colors.primary : colors.textPrimary} />\n        </Pressable>\n      </View>\n\n      {/* Canales */}\n      <ScrollView\n        horizontal\n        showsHorizontalScrollIndicator={false}\n        style={{ maxHeight: 44, flexGrow: 0 }}\n        contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e8 }}\n      >\n        {LB_CHANNELS.map((c) => {\n          const active = channel === c.id;\n          const Icon = c.icon;\n          return (\n            <Pressable\n              key={c.id}\n              onPress={() => setChannel(c.id)}\n              accessibilityRole=\"tab\"\n              accessibilityState={{ selected: active }}\n              style={[styles.chipChannel, { backgroundColor: active ? c.color : colors.surface }]}\n            >\n              <Icon size={13} color={active ? brand.white : colors.textSecondary} />\n              <Text style={{ color: active ? brand.white : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '600', marginLeft: espaciado.e4 }}>\n                {c.label}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </ScrollView>\n\n      {/* Ciudades */}\n      <ScrollView\n        horizontal\n        showsHorizontalScrollIndicator={false}\n        style={{ maxHeight: 38, flexGrow: 0 }}\n        contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e6, marginTop: espaciado.e6, alignItems: 'center' }}\n      >\n        <Pressable\n          onPress={() => setCity(null)}\n          style={[styles.chipCity, { backgroundColor: city === null ? colors.primary : colors.surface }]}\n        >\n          <Text style={{ color: city === null ? brand.white : colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>Todas</Text>\n        </Pressable>\n        {LB_CITIES.map((c) => {\n          const active = city === c;\n          return (\n            <Pressable\n              key={c}\n              onPress={() => setCity(active ? null : c)}\n              style={[styles.chipCity, { backgroundColor: active ? colors.primary : colors.surface }]}\n            >\n              <Text style={{ color: active ? brand.white : colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>{c}</Text>\n            </Pressable>\n          );\n        })}\n      </ScrollView>\n\n      {/* Filtro activo */}\n      {type ? (\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, paddingHorizontal: espaciado.e12, marginTop: espaciado.e8 }}>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n            Filtro: {TYPE_FILTERS.find((f) => f.id === type)?.label}\n          </Text>\n          <Pressable onPress={() => setType('')} hitSlop={8} accessibilityLabel=\"Quitar filtro\">\n            <X size={13} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n      ) : null}\n\n      {/* Grid */}\n      {loading ? (\n        <View style={styles.center}><ActivityIndicator color={colors.primary} /></View>\n      ) : error ? (\n        <View style={styles.center}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '700', textAlign: 'center', paddingHorizontal: espaciado.e30 }}>{error}</Text>\n          <Pressable onPress={() => load('initial')} style={[styles.retry, { backgroundColor: colors.surface }]}>\n            <RefreshCw size={15} color={colors.primary} />\n            <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <FlatList\n          data={[{ left: leftCol, right: rightCol }]}\n          keyExtractor={() => 'explore'}\n          renderItem={({ item }) => (\n            <View style={styles.masonryRow}>\n              <View style={styles.masonryCol}>\n                {item.left.map((p) => (\n                  <PostCard\n                    key={p.id}\n                    post={p}\n                    width={colWidth}\n                    onPress={(id) => router.push({ pathname: '/lifebook-post/[id]', params: { id } })}\n                    onMore={setReportTarget}\n                  />\n                ))}\n              </View>\n              <View style={styles.masonryCol}>\n                {item.right.map((p) => (\n                  <PostCard\n                    key={p.id}\n                    post={p}\n                    width={colWidth}\n                    onPress={(id) => router.push({ pathname: '/lifebook-post/[id]', params: { id } })}\n                    onMore={setReportTarget}\n                  />\n                ))}\n              </View>\n            </View>\n          )}\n          contentContainerStyle={{ padding: PADDING, paddingBottom: DOCK_BODY_H + insets.bottom + 16, flexGrow: 1 }}\n          showsVerticalScrollIndicator={false}\n          onEndReached={loadMore}\n          onEndReachedThreshold={0.5}\n          refreshing={refreshing}\n          onRefresh={() => load('refresh')}\n          ListEmptyComponent={\n            <View style={{ alignItems: 'center', marginTop: 60 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n                {query.trim()\n                  ? `Nada coincide con “${query.trim()}”.`\n                  : 'Aún no hay publicaciones en este canal'}\n              </Text>\n            </View>\n          }\n          ListFooterComponent={loadingMore ? <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e14 }} /> : null}\n        />\n      )}\n\n      {/* Hoja de filtros (tipo de publicación) */}\n      <Modal visible={filtersOpen} transparent animationType=\"slide\" onRequestClose={() => setFiltersOpen(false)} statusBarTranslucent>\n        <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={() => setFiltersOpen(false)} />\n        <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 18 }]}>\n          <View style={styles.sheetHeader}>\n            <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1 }}>Filtrar por tipo</Text>\n            <Pressable onPress={() => setFiltersOpen(false)} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\n          </View>\n          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 }}>\n            {TYPE_FILTERS.map((f) => {\n              const active = type === f.id;\n              return (\n                <Pressable\n                  key={f.id || 'all'}\n                  onPress={() => { setType(f.id); setFiltersOpen(false); }}\n                  style={[styles.typeChip, { backgroundColor: active ? colors.primary : alpha(colors.textSecondary, 0.08) }]}\n                >\n                  <Text style={{ color: active ? brand.white : colors.textPrimary, fontSize: tipografia.body, fontWeight: active ? '800' : '600' }}>{f.label}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n        </View>\n      </Modal>\n\n      <DockFooter active=\"lifebook\" onNavigate={onDockNavigate} showUnreadBadge />\n\n      <ReportSheet\n        post={reportTarget}\n        onClose={() => setReportTarget(null)}\n        onReport={async (postId, reason) => {\n          try {\n            await lifebookActionsApi.report(postId, 'post', reason);\n            Alert.alert('Gracias', 'Tu reporte fue enviado. El equipo lo revisará.');\n          } catch (e) {\n            Alert.alert('Reportar', e instanceof Error ? e.message : 'No se pudo enviar el reporte.');\n          }\n        }}\n        onBlocked={() => load('initial')}\n      />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, gap: espaciado.e8 },\n  searchBox: { flex: 1, flexDirection: 'row', alignItems: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e12, height: 38 },\n  filterBtn: { width: 38, height: 38, alignItems: 'center', justifyContent: 'center' },\n  chipChannel: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e12, height: 32 },\n  chipCity: { borderRadius: radios.full, paddingHorizontal: espaciado.e12, height: 28, alignItems: 'center', justifyContent: 'center' },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e12, paddingBottom: 60 },\n  retry: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e7, borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e9 },\n  masonryRow: { flexDirection: 'row', gap: espaciado.e8 },\n  masonryCol: { flex: 1, gap: espaciado.e8 },\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  sheetHeader: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e14 },\n  typeChip: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e9 },\n});\n","/**\r\n * PostCard — Tarjeta de feed estilo Xiaohongshu (v2)\r\n * Imagen dominante (3:4 o proporción real) + chip de categoría + título\r\n * (2 líneas) + ubicación/tema + autor + social (**solo ♥**, que se puede tocar).\r\n *\r\n * Consume `LbPostCard` (api/lifebook.ts): la forma derivada de `LbPostBase`\r\n * con `toPostCard()` → `media` es UN objeto de portada, el autor ya trae\r\n * `name` y el social viene en campos planos.\r\n *\r\n * Zonas de la imagen: categoría arriba-izquierda · ⋯ arriba-derecha ·\r\n * ▶ centro · precio abajo-izquierda · contador 1/N abajo-derecha.\r\n *\r\n * Vista previa (decidido con el dueño): **solo el corazón** — se quitaron los\r\n * iconos de comentario y guardar, porque esos viven dentro de la publicación.\r\n * El corazón se puede tocar aquí mismo y, como en Instagram/Xiaohongshu, un\r\n * **doble toque** en cualquier parte de la tarjeta da me gusta.\r\n */\r\nimport React, { memo, useEffect, useRef, useState } from 'react';\r\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\r\nimport { Image } from 'expo-image';\r\nimport { Gesture, GestureDetector } from 'react-native-gesture-handler';\r\nimport { runOnJS } from 'react-native-reanimated';\r\nimport { Heart, MoreHorizontal, Play } from 'lucide-react-native';\r\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { LB_CARD_DEFAULT_RATIO, type LbPostCard } from '../../api/lifebook';\r\nimport { lbXaf } from '../../constants/lifebook';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\ninterface Props {\r\n  post: LbPostCard;\r\n  width: number;\r\n  onPress: (id: string) => void;\r\n  onMore?: (post: LbPostCard) => void;\r\n  /**\r\n   * Me gusta desde la propia tarjeta (como Instagram/Xiaohongshu): se puede\r\n   * tocar el corazón o **hacer doble toque** en la publicación.\r\n   */\r\n  onLike?: (post: LbPostCard, liked: boolean) => void;\r\n}\r\n\r\n/**\r\n * Parte 31 (navegación fluida): memo — la tarjeta solo se vuelve a pintar si su\r\n * publicación (o el ancho) cambia de verdad. Con el feed recargando en\r\n * silencio, volver de un detalle ya no vuelve a montar las 20 tarjetas.\r\n */\r\nexport const PostCard = memo(function PostCard({ post, width, onPress, onMore, onLike }: Props) {\r\n  const { colors } = useTheme();\r\n  const [liked, setLiked] = useState(!!post.likedByMe);\r\n  const [likes, setLikes] = useState(post.likesCount ?? 0);\r\n  const [heartPop, setHeartPop] = useState(false);\r\n  const popTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\r\n\r\n  // El estado real puede llegar después (feed recargado o detalle).\r\n  useEffect(() => { setLiked(!!post.likedByMe); }, [post.likedByMe]);\r\n  useEffect(() => { setLikes(post.likesCount ?? 0); }, [post.likesCount]);\r\n  useEffect(() => () => { if (popTimer.current) clearTimeout(popTimer.current); }, []);\r\n\r\n  const applyLike = (next: boolean) => {\r\n    setLiked(next);\r\n    setLikes((n) => Math.max(0, n + (next ? 1 : -1)));\r\n    onLike?.(post, next);\r\n  };\r\n\r\n  const toggleLike = () => applyLike(!liked);\r\n\r\n  /** Doble toque → me gusta (con el corazón grande, como en Xiaohongshu). */\r\n  const doubleTapLike = () => {\r\n    if (!liked) applyLike(true);\r\n    setHeartPop(true);\r\n    if (popTimer.current) clearTimeout(popTimer.current);\r\n    popTimer.current = setTimeout(() => setHeartPop(false), 650);\r\n  };\r\n\r\n  const ratio = post.media?.aspectRatio ?? LB_CARD_DEFAULT_RATIO;\r\n  const imgH = Math.round(width / Math.max(ratio, 0.5));\r\n\r\n  const imageUrl = post.media?.thumbnailUrl ?? post.media?.url;\r\n  const body = post.body ?? '';\r\n  const blockText = body || post.title;\r\n  const footerText = post.media ? post.title : body && post.title !== body ? post.title : '';\r\n\r\n  // OJO: `??` no se puede mezclar con `||` sin paréntesis (error de sintaxis).\r\n  const isVideo = post.hasVideo ?? (post.type === 'video' || post.type === 'serie');\r\n  const photoCount = Number(post.mediaCount ?? 0) || 0;\r\n\r\n  /* Doble toque = me gusta; toque simple = abrir la publicación.\r\n     Se usa `Gesture.Exclusive` para no abrir el detalle al hacer doble toque.\r\n     Las funciones que corren en JS se declaran aquí fuera: `runOnJS` necesita\r\n     funciones del hilo de JS, no flechas creadas dentro del worklet. */\r\n  const openPost = () => onPress(post.id);\r\n  const doubleTap = Gesture.Tap().numberOfTaps(2).maxDuration(260).onEnd(() => { runOnJS(doubleTapLike)(); });\r\n  const singleTap = Gesture.Tap().numberOfTaps(1).onEnd(() => { runOnJS(openPost)(); });\r\n  const taps = Gesture.Exclusive(doubleTap, singleTap);\r\n\r\n  return (\r\n    <>\r\n    <Pressable\r\n      onPress={() => onPress(post.id)}\r\n      style={({ pressed }) => [\r\n        styles.card,\r\n        { backgroundColor: colors.card, opacity: pressed ? 0.85 : 1 },\r\n      ]}\r\n      accessibilityRole=\"button\"\r\n      accessibilityLabel={post.title || 'Publicación'}\r\n    >\r\n      {/* ── Imagen / Video ── */}\r\n      {/* ── Imagen / Video: aquí el DOBLE TOQUE da me gusta (el corazón de abajo es un toque normal) ── */}\r\n      <GestureDetector gesture={taps}>\r\n      <View style={{ position: 'relative' }}>\r\n        {imageUrl ? (\r\n          /* expo-image (Parte 31): caché en memoria+disco y recyclingKey. Antes\r\n             con <Image> de React Native cada vuelta a la pantalla obligaba a\r\n             volver a descargar/decodificar la portada → destello blanco. */\r\n          <Image\r\n            source={imageUrl}\r\n            style={{ width, height: imgH, borderRadius: radios.sm, backgroundColor: colors.surface }}\r\n            contentFit=\"cover\"\r\n            cachePolicy=\"memory-disk\"\r\n            recyclingKey={post.id}\r\n            transition={0}\r\n          />\r\n        ) : (\r\n          <View\r\n            style={[styles.noMedia, { width, height: imgH, backgroundColor: alpha(colors.primary, 0.07) }]}\r\n          >\r\n            <Text numberOfLines={6} style={[styles.noMediaText, { color: colors.textPrimary }]}>\r\n              {blockText}\r\n            </Text>\r\n          </View>\r\n        )}\r\n\r\n        {/* Chip de categoría — arriba izquierda */}\r\n        {post.category ? (\r\n          <View style={[styles.chip, styles.chipTL]}>\r\n            <Text style={styles.chipText}>{post.category}</Text>\r\n          </View>\r\n        ) : null}\r\n\r\n        {/* Indicador de video — centro (evita chocar con precio/categoría) */}\r\n        {isVideo && imageUrl ? (\r\n          <View style={styles.playBadge}>\r\n            <Play size={12} color={brand.white} fill={brand.white} />\r\n          </View>\r\n        ) : null}\r\n\r\n        {/* Precio — abajo izquierda */}\r\n        {post.priceXaf !== undefined ? (\r\n          <View style={[styles.chip, styles.pricePill]}>\r\n            <Text style={styles.chipText}>{lbXaf(post.priceXaf)}</Text>\r\n          </View>\r\n        ) : null}\r\n\r\n        {/* Contador 1/N — abajo derecha */}\r\n        {photoCount > 1 ? (\r\n          <View style={[styles.chip, styles.countChip]}>\r\n            <Text style={styles.chipText}>1/{photoCount}</Text>\r\n          </View>\r\n        ) : null}\r\n\r\n        {/* Botón más — arriba derecha */}\r\n        {onMore ? (\r\n          <Pressable\r\n            onPress={(e) => { e.stopPropagation(); onMore(post); }}\r\n            hitSlop={10}\r\n            style={styles.moreBtn}\r\n            accessibilityLabel=\"Más opciones\"\r\n          >\r\n            <MoreHorizontal size={16} color={brand.white} />\r\n          </Pressable>\r\n        ) : null}\r\n      </View>\r\n      </GestureDetector>\r\n      {/* ── Título ── */}\r\n      {footerText ? (\r\n        <Text numberOfLines={2} style={[styles.title, { color: colors.textPrimary, marginTop: espaciado.e6 }]}>\r\n          {footerText}\r\n        </Text>\r\n      ) : null}\r\n\r\n      {/* ── Ubicación / tema (contexto local) ── */}\r\n      {post.locationLabel || post.topicLabel ? (\r\n        <Text numberOfLines={1} style={[styles.meta, { color: colors.textSecondary }]}>\r\n          {[post.locationLabel, post.topicLabel ? `#${post.topicLabel}` : null]\r\n            .filter(Boolean)\r\n            .join(' · ')}\r\n        </Text>\r\n      ) : null}\r\n\r\n      {/* ── Autor + social ── */}\r\n      <View style={styles.footer}>\r\n        <View style={styles.authorRow}>\r\n          {post.author?.avatarUrl ? (\r\n            <Image\r\n              source={post.author.avatarUrl}\r\n              style={styles.avatar}\r\n              contentFit=\"cover\"\r\n              cachePolicy=\"memory-disk\"\r\n              recyclingKey={`av-${post.author?.id ?? post.author?.name ?? 'x'}`}\r\n              transition={0}\r\n            />\r\n          ) : (\r\n            <View style={[styles.avatar, styles.avatarFallback, { backgroundColor: alpha(colors.primary, 0.15) }]}>\r\n              <Text style={{ fontSize: 9, fontWeight: '800', color: colors.primary }}>\r\n                {(post.author?.name ?? '?').trim().charAt(0).toUpperCase() || '?'}\r\n              </Text>\r\n            </View>\r\n          )}\r\n          <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '500', flex: 1 }}>\r\n            {post.author?.name ?? 'Usuario'}\r\n          </Text>\r\n        </View>\r\n\r\n        {/* Solo me gusta: se toca aquí mismo para dar/quitar me gusta.\r\n            (Comentario y guardar viven dentro de la publicación.) */}\r\n        <Pressable\r\n          onPress={(e) => { e.stopPropagation(); toggleLike(); }}\r\n          hitSlop={8}\r\n          accessibilityRole=\"button\"\r\n          accessibilityLabel={`Me gusta${likes ? `, ${likes}` : ''}`}\r\n          accessibilityState={{ selected: liked }}\r\n          style={styles.socialBtn}\r\n        >\r\n          <Heart size={15} color={liked ? brand.like : colors.textSecondary} fill={liked ? brand.like : 'none'} />\r\n          <Text style={[styles.socialN, liked ? { color: brand.like } : null]}>{formatCount(likes)}</Text>\r\n        </Pressable>\r\n      </View>\r\n\r\n      {/* Corazón grande del doble toque (como Instagram/Xiaohongshu) */}\r\n      {heartPop ? (\r\n        <View pointerEvents=\"none\" style={styles.heartPop}>\r\n          <Heart size={76} color={brand.like} fill={brand.like} />\r\n        </View>\r\n      ) : null}\r\n    </Pressable>\r\n    </>\r\n  );\r\n});\r\n\r\nfunction formatCount(n: number): string {\r\n  if (n >= 1_000) return `${(n / 1000).toFixed(1)}k`;\r\n  return String(n);\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  card: { borderRadius: 10, overflow: 'hidden', paddingBottom: espaciado.e8 },\r\n  noMedia: { borderRadius: radios.sm, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e10 },\r\n  noMediaText: { fontSize: tipografia.caption, fontWeight: '700', lineHeight: 17, textAlign: 'center' },\r\n  title: { fontSize: tipografia.body, fontWeight: '600', lineHeight: 18, paddingHorizontal: espaciado.e6 },\r\n  meta: { fontSize: tipografia.micro, fontWeight: '500', paddingHorizontal: espaciado.e6, marginTop: espaciado.e2 },\r\n  footer: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e6, marginTop: espaciado.e6 },\r\n  authorRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, flex: 1, marginRight: espaciado.e6 },\r\n  avatar: { width: 18, height: 18, borderRadius: 9 },\r\n  avatarFallback: { alignItems: 'center', justifyContent: 'center' },\r\n  socialRow: { flexDirection: 'row', alignItems: 'center' },\r\n  socialBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, paddingHorizontal: espaciado.e4, paddingVertical: espaciado.e2 },\r\n  heartPop: { position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, alignItems: 'center', justifyContent: 'center' },\r\n  socialN: { color: '#8A8F99', fontSize: tipografia.micro, fontWeight: '600', marginLeft: espaciado.e3 },\r\n  chip: { position: 'absolute', backgroundColor: 'rgba(0,0,0,0.5)', borderRadius: radios.full, paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e2 },\r\n  chipText: { color: brand.white, fontSize: 10.5, fontWeight: '800' },\r\n  chipTL: { top: 6, left: 6 },\r\n  pricePill: { bottom: 8, left: 8 },\r\n  countChip: { bottom: 8, right: 8 },\r\n  playBadge: {\r\n    position: 'absolute', top: '50%', left: '50%', marginTop: -14, marginLeft: -14,\r\n    width: 28, height: 28, borderRadius: 14, backgroundColor: 'rgba(0,0,0,0.5)',\r\n    alignItems: 'center', justifyContent: 'center',\r\n  },\r\n  moreBtn: {\r\n    position: 'absolute', top: 6, right: 6, backgroundColor: 'rgba(0,0,0,0.35)',\r\n    borderRadius: radios.md, width: 24, height: 24, alignItems: 'center', justifyContent: 'center',\r\n  },\r\n});\r\n","/**\n * ReportSheet — hoja de REPORTAR contenido de Life Book.\n *\n * API (forma del mock del dueño): `post` + `onClose` + `onReport`.\n * Los motivos son los **11 códigos oficiales** que valida el backend\n * (constants/lifebook.ts → `LB_REPORT_REASONS`): enviar una etiqueta en\n * español daría 400 REASON_INVALID.\n * Incluye BLOQUEAR al autor (llamada real a `/users/:id/block`).\n */\nimport React, { useState } from 'react';\nimport { ActivityIndicator, Alert, Modal, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Flag, ShieldAlert, UserX, X } from 'lucide-react-native';\nimport { LB_REPORT_REASONS } from '../../constants/lifebook';\nimport { lifebookBlocksApi, type LbPostCard } from '../../api/lifebook';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { formaHoja, formaTirador } from './ui/Sheet';\n\ninterface Props {\n  /** Publicación objetivo; `null` cierra la hoja. */\n  post: LbPostCard | null;\n  onClose: () => void;\n  /** `reason` es el código oficial (p. ej. 'spam'). */\n  onReport?: (postId: string, reason: string) => void | Promise<void>;\n  /** Se llama tras bloquear correctamente (para refrescar listas). */\n  onBlocked?: (authorId: string) => void;\n}\n\nexport function ReportSheet({ post, onClose, onReport, onBlocked }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [busy, setBusy] = useState(false);\n\n  const pick = async (reason: string) => {\n    if (busy || !post) return;\n    setBusy(true);\n    try {\n      await onReport?.(post.id, reason);\n      onClose();\n    } finally { setBusy(false); }\n  };\n\n  const block = async () => {\n    const authorId = post?.author?.id;\n    if (!authorId || busy) return;\n    setBusy(true);\n    try {\n      await lifebookBlocksApi.block(authorId);\n      onClose();\n      Alert.alert('Bloqueado', 'Ya no verás su contenido ni podrá escribirte.');\n      onBlocked?.(authorId);\n    } catch (e) {\n      Alert.alert('Bloquear', e instanceof Error ? e.message : 'No se pudo bloquear.');\n    } finally { setBusy(false); }\n  };\n\n  return (\n    <Modal visible={!!post} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 18 }]}>\n        <View style={[styles.handle, { backgroundColor: alpha(colors.textPrimary, 0.2) }]} />\n        <View style={styles.header}>\n          <Flag size={18} color={colors.textPrimary} />\n          <Text style={[styles.title, { color: colors.textPrimary }]}>Reportar publicación</Text>\n          <Pressable onPress={onClose} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\n        </View>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e8, paddingHorizontal: espaciado.e2 }}>\n          ¿Por qué quieres reportar esto? Lo revisará el equipo de moderación.\n        </Text>\n        {busy && <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e6 }} />}\n\n        {LB_REPORT_REASONS.map((r) => (\n          <Pressable\n            key={r.value}\n            onPress={() => pick(r.value)}\n            disabled={busy}\n            accessibilityRole=\"button\"\n            style={({ pressed }) => [styles.row, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n          >\n            <ShieldAlert size={16} color={colors.textSecondary} />\n            <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '600' }}>{r.label}</Text>\n          </Pressable>\n        ))}\n\n        {post?.author?.id ? (\n          <Pressable\n            onPress={block}\n            disabled={busy}\n            accessibilityRole=\"button\"\n            style={({ pressed }) => [styles.blockBtn, { backgroundColor: pressed ? alpha(brand.like, 0.16) : alpha(brand.like, 0.1) }]}\n          >\n            <UserX size={16} color={brand.like} />\n            <Text style={{ color: brand.like, fontWeight: '800', fontSize: tipografia.body }}>\n              Bloquear a {post.author.name}\n            </Text>\n          </Pressable>\n        ) : null}\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  handle: { ...formaTirador },\n  header: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginBottom: espaciado.e4 },\n  title: { fontSize: 17, fontWeight: '900', flex: 1 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: 'rgba(128,128,140,0.15)' },\n  blockBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, borderRadius: radios.md, padding: espaciado.e14, marginTop: espaciado.e12 },\n});\n","/**\n * useAppDock — navegación ÚNICA del dock inferior para toda la app.\n * Evita handlers duplicados (perfil no tenía 'lifebook' ni 'mensajes') y\n * garantiza que desde cualquier pantalla con dock se pueda saltar a Life Book.\n *\n * ── Parte 31 (navegación fluida) ────────────────────────────────────────────\n * El dock es una navegación de PESTAÑAS, no una pila. Antes cada toque hacía\n * `router.push`, así que:\n *   · el Stack crecía sin límite (cada pestaña quedaba montada debajo, con su\n *     lista, sus imágenes y sus sondeos de red);\n *   · cada cambio arrastraba la animación de empuje de la pila (300 ms) y el\n *     montaje de una pantalla nueva → parpadeo y sensación de lentitud.\n * Ahora todos los destinos usan `router.replace`: se sustituye la pantalla\n * actual (pila acotada, memoria estable) y, con `animation: 'none'` en\n * `app/_layout.tsx` para las pestañas, el cambio es instantáneo.\n * Volver a la pestaña en la que ya estamos es un no-op.\n */\nimport { useRouter } from 'expo-router';\nimport type { FooterTab } from '../components/FloatingFooter';\nimport { ir as irSeguro } from '../constants/rutas';\n\nexport function useAppDock(active?: FooterTab) {\n  const router = useRouter();\n  return (t: FooterTab, city?: string) => {\n    if (t === active) return; // ya estamos en esa pestaña\n    switch (t) {\n      case 'lifebook':\n        irSeguro.libre('/lifebook', undefined, true);\n        return;\n      case 'inicio':\n        irSeguro.libre('/', undefined, true);\n        return;\n      case 'taxi':\n        router.replace((city ? { pathname: '/taxi', params: { city } } : '/taxi') as never);\n        return;\n      case 'mensajes':\n        irSeguro.libre('/lifebook-messages', undefined, true);\n        return;\n      case 'perfil':\n        irSeguro.libre('/profile', undefined, true);\n        return;\n      case 'monedero':\n        irSeguro.libre('/monedero', undefined, true);\n        return;\n      default:\n        return;\n    }\n  };\n}\n","/**\n * Life Book — CREAR RUTA/GRUPO (flujo del dueño, 2026-09-10)\n * Ruta: `/lifebook-group-create`\n *\n * Es el diseño que envió el dueño (`RouteGroupFlow`) pasado a la app, con la\n * paleta oficial (azul #0084FF / naranja #FF7D00) en vez del rojo del boceto.\n * Pasos:\n *   1. `form`    → nombre (24) + descripción (160) + tipo + punto de encuentro\n *                  + condición de ingreso + «mostrar en mi perfil».\n *   2. `type`    → 9 tipos de ruta (se guardan como `category`).\n *   3. `place`   → buscador REAL de sitios (geocoder de OSM del mirror HK) o\n *                  «no mostrar ubicación».\n *   4. `people`  → a quién invitas al crearlo (seguidores + sugeridos).\n *   5. `join`    → sin requisito · aprobación del organizador · pregunta.\n *   6. `success` → ruta creada: ir al grupo, invitar a más, volver.\n *\n * Diferencias conscientes con el boceto (explicadas al dueño):\n *   · El paso `people` va ANTES de crear porque el servidor exige al menos un\n *     miembro además de ti (`GROUP_MEMBERS_REQUIRED`).\n *   · «Código de ruta», «QR», «compartir enlace» y «ubicación en vivo» no\n *     existen todavía en el servidor: no se pintan botones que no hacen nada.\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Image, KeyboardAvoidingView, Platform, Pressable, ScrollView,\n  StyleSheet, Switch, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Check, MapPin, Search, X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { geocode, type GeoPlace } from '../api/geocode';\nimport { messagesApi, type LbGroupMeta } from '../api/messages';\nimport { lifebookInboxApi, type LbFollowerItem, type LbSuggestedUser } from '../api/lifebook';\n\nconst NAME_MAX = 24;\nconst DESC_MAX = 160;\nconst MAX_MEMBERS = 199; // + tú = 200\n\n/** Tipos de ruta del diseño (se guardan en `category`). */\nconst ROUTE_TYPES = [\n  { id: 'ciclismo', icon: '🚴', label: 'Ciclismo', subtitle: 'Rutas en bicicleta' },\n  { id: 'senderismo', icon: '🥾', label: 'Senderismo', subtitle: 'Caminatas y montaña' },\n  { id: 'auto', icon: '🚗', label: 'Ruta en auto', subtitle: 'Viajes por carretera' },\n  { id: 'moto', icon: '🏍️', label: 'Ruta en moto', subtitle: 'Rodadas y viajes' },\n  { id: 'running', icon: '🏃', label: 'Running', subtitle: 'Entrenamientos grupales' },\n  { id: 'camping', icon: '⛺', label: 'Camping', subtitle: 'Salidas con pernocta' },\n  { id: 'foto', icon: '📷', label: 'Fotografía', subtitle: 'Rutas para tomar fotos' },\n  { id: 'urbano', icon: '🏙️', label: 'Ciudad', subtitle: 'Paseos urbanos' },\n  { id: 'gastronomia', icon: '🍜', label: 'Gastronomía', subtitle: 'Rutas de comida' },\n];\n\nconst JOIN_MODES = [\n  { id: 'open', icon: '🔓', title: 'Sin requisito', subtitle: 'Cualquier persona puede unirse.' },\n  { id: 'approval', icon: '🧐', title: 'Aprobación del organizador', subtitle: 'El organizador revisa cada solicitud.' },\n  { id: 'question', icon: '❓', title: 'Pregunta de ingreso', subtitle: 'Quien responda bien puede entrar automáticamente.' },\n];\n\n/** Etiquetas cortas del geocoder (el `kind` de OSM). */\nconst KIND_LABEL: Record<string, string> = {\n  road: 'Vía', residential: 'Calle', primary: 'Avenida', secondary: 'Avenida',\n  tertiary: 'Calle', motorway: 'Autovía', trunk: 'Carretera', unclassified: 'Camino',\n  service: 'Acceso', living_street: 'Calle', pedestrian: 'Zona peatonal', path: 'Sendero',\n  steps: 'Escaleras', village: 'Poblado', town: 'Localidad', city: 'Ciudad',\n  suburb: 'Barrio', neighbourhood: 'Barrio', peak: 'Cumbre', park: 'Parque',\n  school: 'Colegio', hospital: 'Hospital', restaurant: 'Restaurante', cafe: 'Cafetería',\n  fuel: 'Gasolinera', marketplace: 'Mercado', bus_station: 'Estación de bus',\n  beach: 'Playa', hotel: 'Hotel', bank: 'Banco', pharmacy: 'Farmacia', church: 'Iglesia',\n};\n\ntype Step = 'form' | 'type' | 'place' | 'people' | 'join' | 'success';\ntype Person = { id: string; name: string; avatarUrl?: string | null; note?: string };\n\nexport default function LifeBookGroupCreate() {\n  return (\n    <AuthGate>\n      <GroupCreateContent />\n    </AuthGate>\n  );\n}\n\nfunction GroupCreateContent() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  const [step, setStep] = useState<Step>('form');\n  const [name, setName] = useState('');\n  const [description, setDescription] = useState('');\n  const [typeId, setTypeId] = useState<string | null>(null);\n  const [showInProfile, setShowInProfile] = useState(true);\n  const [errText, setErrText] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  // Punto de encuentro\n  const [place, setPlace] = useState<{ name: string; kind: string; lon: number; lat: number } | null>(null);\n  const [hidePlace, setHidePlace] = useState(false);\n  const [placeQuery, setPlaceQuery] = useState('');\n  const [placeResults, setPlaceResults] = useState<GeoPlace[] | null>(null);\n  const [searching, setSearching] = useState(false);\n  const searchSeq = useRef(0);\n\n  // Condición de ingreso\n  const [joinMode, setJoinMode] = useState<'open' | 'approval' | 'question'>('open');\n  const [joinQuestion, setJoinQuestion] = useState('');\n  const [joinAnswer, setJoinAnswer] = useState('');\n\n  // Personas\n  const [followers, setFollowers] = useState<Person[]>([]);\n  const [suggested, setSuggested] = useState<Person[]>([]);\n  const [peopleLoading, setPeopleLoading] = useState(true);\n  const [picked, setPicked] = useState<string[]>([]);\n  const [peopleQuery, setPeopleQuery] = useState('');\n\n  const [created, setCreated] = useState<{ id: string; title: string; membersCount: number } | null>(null);\n\n  const selectedType = useMemo(() => ROUTE_TYPES.find((t) => t.id === typeId) ?? null, [typeId]);\n  const selectedJoin = useMemo(() => JOIN_MODES.find((j) => j.id === joinMode) ?? JOIN_MODES[0], [joinMode]);\n\n  /* ── Personas (seguidores + sugeridos), como en la hoja anterior ── */\n  useEffect(() => {\n    let alive = true;\n    (async () => {\n      try {\n        const [f, s] = await Promise.all([\n          lifebookInboxApi.followers().catch(() => [] as LbFollowerItem[]),\n          lifebookInboxApi.suggested().catch(() => [] as LbSuggestedUser[]),\n        ]);\n        if (!alive) return;\n        const seen = new Set<string>();\n        const toPerson = (x: any, note?: string): Person | null => {\n          const id = String(x?.id ?? '');\n          if (!id || seen.has(id)) return null;\n          seen.add(id);\n          return { id, name: String(x.fullName ?? x.name ?? 'Usuario').trim(), avatarUrl: x.avatarUrl ?? null, note };\n        };\n        setFollowers(f.map((x) => toPerson(x, 'Te sigue')).filter(Boolean) as Person[]);\n        setSuggested(s.map((x) => toPerson(x, x.reason ?? x.city)).filter(Boolean) as Person[]);\n      } finally {\n        if (alive) setPeopleLoading(false);\n      }\n    })();\n    return () => { alive = false; };\n  }, []);\n\n  const pickedPeople = useMemo(() => {\n    const all = [...followers, ...suggested];\n    return picked.map((id) => all.find((p) => p.id === id)).filter(Boolean) as Person[];\n  }, [picked, followers, suggested]);\n\n  const filterList = (list: Person[]) => {\n    const q = peopleQuery.trim().toLowerCase();\n    return q ? list.filter((p) => p.name.toLowerCase().includes(q) || (p.note ?? '').toLowerCase().includes(q)) : list;\n  };\n  const visibleFollowers = filterList(followers);\n  const visibleSuggested = filterList(suggested);\n\n  /* ── Buscador de sitios (geocoder real del mirror) ── */\n  const runSearch = useCallback(async (q: string) => {\n    const term = q.trim();\n    const seq = ++searchSeq.current;\n    if (term.length < 2) { setPlaceResults(null); setSearching(false); return; }\n    setSearching(true);\n    try {\n      const res = await geocode(term);\n      if (seq === searchSeq.current) setPlaceResults(res);\n    } finally {\n      if (seq === searchSeq.current) setSearching(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    const t = setTimeout(() => { runSearch(placeQuery); }, 350);\n    return () => clearTimeout(t);\n  }, [placeQuery, runSearch]);\n\n  const canCreate = name.trim().length >= 3 && description.trim().length > 0 && !!typeId && picked.length > 0 && !busy;\n\n  const togglePerson = (id: string) => {\n    setErrText(null);\n    setPicked((prev) => {\n      if (prev.includes(id)) return prev.filter((x) => x !== id);\n      if (prev.length >= MAX_MEMBERS) return prev;\n      return [...prev, id];\n    });\n  };\n\n  const submit = async () => {\n    if (!canCreate) {\n      setErrText(\n        name.trim().length < 3 ? 'El nombre necesita al menos 3 letras.'\n          : !description.trim() ? 'Escribe una descripción.'\n            : !typeId ? 'Elige el tipo de ruta.'\n              : 'Invita al menos a una persona.',\n      );\n      return;\n    }\n    setBusy(true); setErrText(null);\n    const meta: LbGroupMeta = {\n      description: description.trim(),\n      category: typeId ?? undefined,\n      visibility: showInProfile ? 'public' : 'private',\n      placeName: hidePlace ? undefined : place?.name,\n      placeAddress: hidePlace || !place ? undefined : (KIND_LABEL[place.kind] ?? 'Lugar'),\n      placeLon: hidePlace ? undefined : place?.lon,\n      placeLat: hidePlace ? undefined : place?.lat,\n      hidePlace,\n      joinMode,\n      joinQuestion: joinMode === 'question' ? joinQuestion.trim() : undefined,\n      joinAnswer: joinMode === 'question' ? joinAnswer.trim() : undefined,\n    };\n    try {\n      const g = await messagesApi.createGroup(name.trim(), picked, meta);\n      setCreated({ id: g.id, title: g.title, membersCount: g.membersCount ?? picked.length + 1 });\n      setStep('success');\n    } catch (e: any) {\n      const code = e?.code;\n      if (code === 'GROUP_TITLE_REQUIRED') setErrText('El nombre necesita al menos 3 letras.');\n      else if (code === 'GROUP_MEMBERS_REQUIRED') setErrText('Elige al menos a una persona.');\n      else if (code === 'GROUP_META_INVALID') setErrText(e?.message ?? 'Revisa la condición de ingreso.');\n      else setErrText(e?.message ?? 'No se pudo crear la ruta.');\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const goToGroup = (openMembers = false) => {\n    if (!created) return;\n    router.replace({\n      pathname: '/lifebook-chat/[id]',\n      params: { id: created.id, name: created.title, isGroup: '1', ...(openMembers ? { members: '1' } : {}) },\n    } as never);\n  };\n\n  const titles: Record<Step, string> = {\n    form: 'Crear ruta', type: 'Tipo de ruta', place: 'Punto de encuentro',\n    people: 'Invitar compañeros', join: 'Condición de ingreso', success: 'Ruta creada',\n  };\n\n  const back = () => {\n    if (step === 'form') { router.back(); return; }\n    if (step === 'success') { router.back(); return; }\n    if (step === 'type' || step === 'join') { setStep('form'); return; }\n    if (step === 'place') { setStep('form'); return; }\n    setStep('form');\n  };\n\n  return (\n    <KeyboardAvoidingView\n      style={{ flex: 1, backgroundColor: colors.background }}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      {/* Cabecera */}\n      <View style={[styles.header, { paddingTop: insets.top + 8, backgroundColor: colors.card, borderBottomColor: alpha(colors.border, 0.6) }]}>\n        <Pressable onPress={back} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900', flex: 1 }}>{titles[step]}</Text>\n        {step !== 'success' ? (\n          <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        ) : null}\n      </View>\n\n      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 120 }} keyboardShouldPersistTaps=\"handled\">\n        {/* ── 1. Formulario ── */}\n        {step === 'form' ? (\n          <View style={{ gap: espaciado.e16 }}>\n            <Field label=\"Nombre de la ruta\" required hint={`${name.length}/${NAME_MAX}`} colors={colors}>\n              <TextInput\n                value={name}\n                onChangeText={(t) => { setName(t); setErrText(null); }}\n                maxLength={NAME_MAX}\n                placeholder=\"Ej: Ruta del mirador\"\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n              />\n            </Field>\n\n            <Field label=\"Descripción\" required hint={`${description.length}/${DESC_MAX}`} colors={colors}>\n              <TextInput\n                value={description}\n                onChangeText={setDescription}\n                maxLength={DESC_MAX}\n                multiline\n                placeholder=\"Describe el objetivo, nivel, horario y recomendaciones.\"\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, styles.textarea, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n              />\n            </Field>\n\n            <Card colors={colors}>\n              <PickRow\n                label=\"Tipo de ruta\"\n                value={selectedType ? `${selectedType.icon} ${selectedType.label}` : 'Sin seleccionar'}\n                onPress={() => setStep('type')}\n                colors={colors}\n              />\n              <PickRow\n                label=\"Punto de encuentro\"\n                value={hidePlace ? 'No mostrar ubicación' : (place?.name ?? 'Sin seleccionar')}\n                onPress={() => setStep('place')}\n                colors={colors}\n              />\n              <PickRow\n                label=\"Condición de ingreso\"\n                value={`${selectedJoin.icon} ${selectedJoin.title}`}\n                onPress={() => setStep('join')}\n                colors={colors}\n                last\n              />\n            </Card>\n\n            <Card colors={colors} row>\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '700', fontSize: tipografia.body }}>Mostrar en mi perfil</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>La ruta será visible en tu página personal.</Text>\n              </View>\n              <Switch value={showInProfile} onValueChange={setShowInProfile} />\n            </Card>\n\n            <Pressable onPress={() => setStep('people')} style={[styles.primaryBtn, { backgroundColor: colors.primary }]} accessibilityLabel=\"Continuar\">\n              <Text style={styles.primaryText}>Continuar</Text>\n            </Pressable>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n              Para mantener la comunidad segura, respeta las normas de convivencia.\n            </Text>\n          </View>\n        ) : null}\n\n        {/* ── 2. Tipo de ruta ── */}\n        {step === 'type' ? (\n          <View style={{ gap: espaciado.e10 }}>\n            {ROUTE_TYPES.map((t) => (\n              <OptionRow\n                key={t.id}\n                icon={t.icon}\n                title={t.label}\n                subtitle={t.subtitle}\n                selected={typeId === t.id}\n                onPress={() => setTypeId(t.id)}\n                colors={colors}\n              />\n            ))}\n          </View>\n        ) : null}\n\n        {/* ── 3. Punto de encuentro ── */}\n        {step === 'place' ? (\n          <View style={{ gap: espaciado.e12 }}>\n            <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\n              <Search size={16} color={colors.textSecondary} />\n              <TextInput\n                value={placeQuery}\n                onChangeText={setPlaceQuery}\n                placeholder=\"Buscar calle, avenida o sitio…\"\n                placeholderTextColor={colors.textSecondary}\n                style={{ flex: 1, marginLeft: espaciado.e8, color: colors.textPrimary, fontSize: tipografia.body }}\n              />\n              {searching ? <ActivityIndicator size=\"small\" color={colors.primary} /> : null}\n            </View>\n\n            <Pressable\n              onPress={() => { setHidePlace(true); setPlace(null); setStep('form'); }}\n              style={[styles.option, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.card }]}\n              accessibilityLabel=\"No mostrar ubicación\"\n            >\n              <Text style={{ fontSize: tipografia.title }}>🙈</Text>\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '700', fontSize: tipografia.body }}>No mostrar ubicación</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Solo los miembros verán el punto.</Text>\n              </View>\n            </Pressable>\n\n            {placeQuery.trim().length >= 2 && placeResults !== null && placeResults.length === 0 && !searching ? (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', paddingVertical: espaciado.e18 }}>\n                No hay sitios que coincidan. Prueba con el nombre de la calle.\n              </Text>\n            ) : null}\n\n            {placeResults === null && placeQuery.trim().length < 2 ? (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingVertical: espaciado.e14 }}>\n                Escribe al menos 2 letras. Busca calles, avenidas y sitios reales de Malabo y Bata.\n              </Text>\n            ) : null}\n\n            {(placeResults ?? []).map((r, i) => (\n              <Pressable\n                key={`${r.name}-${i}`}\n                onPress={() => { setPlace(r); setHidePlace(false); setStep('form'); }}\n                style={[styles.option, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.card }]}\n                accessibilityLabel={`Elegir ${r.name}`}\n              >\n                <MapPin size={18} color={colors.primary} />\n                <View style={{ flex: 1 }}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '700', fontSize: tipografia.body }} numberOfLines={1}>{r.name}</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                    {KIND_LABEL[r.kind] ?? 'Lugar'} · {r.lat.toFixed(4)}, {r.lon.toFixed(4)}\n                  </Text>\n                </View>\n              </Pressable>\n            ))}\n          </View>\n        ) : null}\n\n        {/* ── 4. Invitar compañeros ── */}\n        {step === 'people' ? (\n          <View style={{ gap: espaciado.e10 }}>\n            {pickedPeople.length > 0 ? (\n              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e6 }}>\n                {pickedPeople.map((p) => (\n                  <View key={p.id} style={[styles.chip, { backgroundColor: colors.surface }]}>\n                    {p.avatarUrl ? (\n                      <Image source={{ uri: p.avatarUrl }} style={styles.chipAvatar} />\n                    ) : (\n                      <View style={[styles.chipAvatar, { backgroundColor: alpha(colors.primary, 0.15) }]} />\n                    )}\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '600' }} numberOfLines={1}>\n                      {p.name.split(' ')[0]}\n                    </Text>\n                    <Pressable onPress={() => togglePerson(p.id)} hitSlop={6} accessibilityLabel={`Quitar a ${p.name}`}>\n                      <X size={12} color={colors.textSecondary} />\n                    </Pressable>\n                  </View>\n                ))}\n              </ScrollView>\n            ) : null}\n\n            <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\n              <Search size={16} color={colors.textSecondary} />\n              <TextInput\n                value={peopleQuery}\n                onChangeText={setPeopleQuery}\n                placeholder=\"Buscar persona…\"\n                placeholderTextColor={colors.textSecondary}\n                style={{ flex: 1, marginLeft: espaciado.e8, color: colors.textPrimary, fontSize: tipografia.body }}\n              />\n            </View>\n\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              {picked.length} invitado{picked.length === 1 ? '' : 's'} · máximo {MAX_MEMBERS} personas además de ti\n            </Text>\n\n            {peopleLoading ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e20 }} />\n            ) : followers.length === 0 && suggested.length === 0 ? (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', paddingVertical: espaciado.e20 }}>\n                No hay personas a las que invitar por ahora.\n              </Text>\n            ) : (\n              <>\n                {visibleFollowers.length > 0 ? <SectionTitle text=\"Seguidores\" colors={colors} /> : null}\n                {visibleFollowers.map((p) => (\n                  <SelectablePerson key={p.id} p={p} on={picked.includes(p.id)} onPress={() => togglePerson(p.id)} colors={colors} />\n                ))}\n                {visibleSuggested.length > 0 ? <SectionTitle text=\"Sugeridos\" colors={colors} /> : null}\n                {visibleSuggested.map((p) => (\n                  <SelectablePerson key={p.id} p={p} on={picked.includes(p.id)} onPress={() => togglePerson(p.id)} colors={colors} />\n                ))}\n              </>\n            )}\n          </View>\n        ) : null}\n\n        {/* ── 5. Condición de ingreso ── */}\n        {step === 'join' ? (\n          <View style={{ gap: espaciado.e10 }}>\n            {JOIN_MODES.map((j) => (\n              <OptionRow\n                key={j.id}\n                icon={j.icon}\n                title={j.title}\n                subtitle={j.subtitle}\n                selected={joinMode === j.id}\n                onPress={() => setJoinMode(j.id as typeof joinMode)}\n                colors={colors}\n              />\n            ))}\n\n            {joinMode === 'question' ? (\n              <Card colors={colors}>\n                <Field label=\"Pregunta\" required colors={colors}>\n                  <TextInput\n                    value={joinQuestion}\n                    onChangeText={setJoinQuestion}\n                    maxLength={160}\n                    placeholder=\"Ej: ¿Tienes experiencia en rutas de más de 20 km?\"\n                    placeholderTextColor={colors.textSecondary}\n                    style={[styles.input, { backgroundColor: colors.background, color: colors.textPrimary }]}\n                  />\n                </Field>\n                <Field label=\"Respuesta correcta\" required colors={colors}>\n                  <TextInput\n                    value={joinAnswer}\n                    onChangeText={setJoinAnswer}\n                    maxLength={80}\n                    placeholder=\"Ej: sí\"\n                    placeholderTextColor={colors.textSecondary}\n                    style={[styles.input, { backgroundColor: colors.background, color: colors.textPrimary }]}\n                  />\n                </Field>\n              </Card>\n            ) : null}\n          </View>\n        ) : null}\n\n        {/* ── 6. Creada ── */}\n        {step === 'success' && created ? (\n          <View style={{ alignItems: 'center', paddingTop: espaciado.e24, gap: espaciado.e14 }}>\n            <View style={[styles.successCircle, { backgroundColor: alpha(colors.success, 0.15) }]}>\n              <Text style={{ fontSize: 34 }}>✅</Text>\n            </View>\n            <Text style={{ color: colors.textPrimary, fontSize: 24, fontWeight: '900', textAlign: 'center' }}>¡Ruta creada!</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', lineHeight: 20 }}>\n              {created.title} · {created.membersCount} miembro{created.membersCount === 1 ? '' : 's'}\n              {selectedType ? ` · ${selectedType.icon} ${selectedType.label}` : ''}\n              {place && !hidePlace ? `\\n📍 ${place.name}` : hidePlace ? '\\n📍 Punto de encuentro oculto' : ''}\n            </Text>\n            <Pressable onPress={() => goToGroup(false)} style={[styles.primaryBtn, { backgroundColor: colors.primary, alignSelf: 'stretch' }]}>\n              <Text style={styles.primaryText}>Ir al grupo</Text>\n            </Pressable>\n            <Pressable onPress={() => goToGroup(true)} style={[styles.secondaryBtn, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 14.5 }}>Invitar a más personas</Text>\n            </Pressable>\n            <Pressable onPress={() => router.back()} style={{ paddingVertical: espaciado.e8 }} accessibilityLabel=\"Volver a Mensajes\">\n              <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.body }}>Volver a Mensajes</Text>\n            </Pressable>\n          </View>\n        ) : null}\n      </ScrollView>\n\n      {/* Pie con el botón del paso */}\n      {step === 'type' || step === 'join' || step === 'people' ? (\n        <View style={[styles.footer, { paddingBottom: insets.bottom + 12, backgroundColor: colors.card, borderTopColor: alpha(colors.border, 0.6) }]}>\n          {errText ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginBottom: espaciado.e8 }}>{errText}</Text> : null}\n          {step === 'people' ? (\n            <Pressable\n              onPress={submit}\n              disabled={busy}\n              style={[styles.primaryBtn, { backgroundColor: canCreate ? colors.primary : alpha(colors.primary, 0.35) }]}\n              accessibilityLabel=\"Crear ruta\"\n            >\n              {busy\n                ? <ActivityIndicator size=\"small\" color={brand.white} />\n                : <Text style={styles.primaryText}>Crear ruta{picked.length ? ` (${picked.length + 1})` : ''}</Text>}\n            </Pressable>\n          ) : (\n            <Pressable\n              onPress={() => {\n                if (step === 'join' && joinMode === 'question' && (!joinQuestion.trim() || !joinAnswer.trim())) {\n                  setErrText('Escribe la pregunta y la respuesta.');\n                  return;\n                }\n                setErrText(null);\n                setStep('form');\n              }}\n              style={[styles.primaryBtn, { backgroundColor: colors.primary }]}\n              accessibilityLabel=\"Guardar\"\n            >\n              <Text style={styles.primaryText}>Guardar</Text>\n            </Pressable>\n          )}\n        </View>\n      ) : null}\n    </KeyboardAvoidingView>\n  );\n}\n\n/* ── Piezas ── */\n\nfunction Card({ children, colors, row }: { children: React.ReactNode; colors: any; row?: boolean }) {\n  return (\n    <View style={{\n      borderRadius: 18, borderWidth: 1, borderColor: alpha(colors.border, 0.7), backgroundColor: colors.card,\n      padding: espaciado.e14, gap: row ? 12 : 10, flexDirection: row ? 'row' : 'column', alignItems: row ? 'center' : 'stretch',\n    }}>\n      {children}\n    </View>\n  );\n}\n\nfunction Field({ label, required, hint, children, colors }: {\n  label: string; required?: boolean; hint?: string; children: React.ReactNode; colors: any;\n}) {\n  return (\n    <View style={{ gap: espaciado.e6 }}>\n      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>\n          {label}{required ? <Text style={{ color: colors.danger }}> *</Text> : null}\n        </Text>\n        {hint ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{hint}</Text> : null}\n      </View>\n      {children}\n    </View>\n  );\n}\n\nfunction PickRow({ label, value, onPress, colors, last }: {\n  label: string; value: string; onPress: () => void; colors: any; last?: boolean;\n}) {\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityLabel={label}\n      style={{\n        flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e10,\n        borderBottomWidth: last ? 0 : StyleSheet.hairlineWidth, borderBottomColor: alpha(colors.border, 0.6),\n      }}\n    >\n      <View style={{ flex: 1 }}>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{label}</Text>\n        <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '700', marginTop: 1 }} numberOfLines={1}>{value}</Text>\n      </View>\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.subtitle }}>›</Text>\n    </Pressable>\n  );\n}\n\nfunction OptionRow({ icon, title, subtitle, selected, onPress, colors }: {\n  icon: string; title: string; subtitle: string; selected: boolean; onPress: () => void; colors: any;\n}) {\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityLabel={title}\n      accessibilityState={{ selected }}\n      style={{\n        flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, padding: espaciado.e14, borderRadius: 18, borderWidth: 1.5,\n        borderColor: selected ? colors.primary : alpha(colors.border, 0.7),\n        backgroundColor: selected ? alpha(colors.primary, 0.08) : colors.card,\n      }}\n    >\n      <Text style={{ fontSize: 22 }}>{icon}</Text>\n      <View style={{ flex: 1 }}>\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 14.5 }}>{title}</Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{subtitle}</Text>\n      </View>\n      <View style={{\n        width: 20, height: 20, borderRadius: 10, borderWidth: 1.5,\n        borderColor: selected ? colors.primary : alpha(colors.border, 1),\n        backgroundColor: selected ? colors.primary : 'transparent',\n        alignItems: 'center', justifyContent: 'center',\n      }}>\n        {selected ? <Check size={12} color={brand.white} /> : null}\n      </View>\n    </Pressable>\n  );\n}\n\nfunction SectionTitle({ text, colors }: { text: string; colors: any }) {\n  return (\n    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800', letterSpacing: 0.5, marginTop: espaciado.e8 }}>\n      {text.toUpperCase()}\n    </Text>\n  );\n}\n\nfunction SelectablePerson({ p, on, onPress, colors }: { p: Person; on: boolean; onPress: () => void; colors: any }) {\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityLabel={p.name}\n      accessibilityState={{ selected: on }}\n      style={{\n        flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e9,\n        borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: alpha(colors.border, 0.5),\n      }}\n    >\n      {p.avatarUrl ? (\n        <Image source={{ uri: p.avatarUrl }} style={styles.avatar} />\n      ) : (\n        <View style={[styles.avatar, styles.center, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n          <Text style={{ color: colors.primary, fontWeight: '900' }}>{p.name.charAt(0).toUpperCase()}</Text>\n        </View>\n      )}\n      <View style={{ flex: 1 }}>\n        <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: '700', fontSize: tipografia.body }}>{p.name}</Text>\n        {p.note ? <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{p.note}</Text> : null}\n      </View>\n      <View style={{\n        width: 22, height: 22, borderRadius: 11, borderWidth: 1.5,\n        borderColor: on ? colors.primary : alpha(colors.border, 1),\n        backgroundColor: on ? colors.primary : 'transparent',\n        alignItems: 'center', justifyContent: 'center',\n      }}>\n        {on ? <Check size={13} color={brand.white} /> : null}\n      </View>\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  input: { borderRadius: 14, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e11, fontSize: 14.5 },\n  textarea: { minHeight: 110, textAlignVertical: 'top' },\n  searchBox: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e14, height: 40 },\n  option: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, padding: espaciado.e14, borderRadius: radios.lg, borderWidth: 1 },\n  chip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4 },\n  chipAvatar: { width: 18, height: 18, borderRadius: 9 },\n  avatar: { width: 40, height: 40, borderRadius: 20 },\n  center: { alignItems: 'center', justifyContent: 'center' },\n  primaryBtn: { borderRadius: radios.full, paddingVertical: espaciado.e14, alignItems: 'center' },\n  primaryText: { color: brand.white, fontWeight: '900', fontSize: 14.5 },\n  secondaryBtn: { borderRadius: radios.full, paddingVertical: espaciado.e13, alignItems: 'center', borderWidth: 1, alignSelf: 'stretch' },\n  footer: { paddingHorizontal: espaciado.e16, paddingTop: espaciado.e10, borderTopWidth: StyleSheet.hairlineWidth },\n  successCircle: { width: 84, height: 84, borderRadius: 42, alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * LifeBookGroupsScreen — Parte 27 (Fase G3): DESCUBRIR GRUPOS.\n *\n * Listado de los grupos **públicos** con buscador y filtros de ciudad y\n * categoría. Cada tarjeta dice quiénes son, dónde y cómo se entra (libre, con\n * aprobación o respondiendo una pregunta) y lleva a la FICHA\n * (`GroupCardSheet`), donde uno se une, pide entrar o responde la pregunta.\n *\n * Entrada: el icono «Descubrir grupos» de la cabecera de Mensajes.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, Image, Modal, Pressable, RefreshControl, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Check, Compass, Lock, QrCode, Search, ShieldQuestion, Users, X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookGroupsApi, type LbGroupCard } from '../api/lifebook';\nimport { LB_CITIES } from '../constants/lifebook';\nimport { GroupCardSheet } from '../components/lifebook/GroupCardSheet';\nimport { formaHoja } from '../components/lifebook/ui/Sheet';\nimport { ir as irSeguro } from '../constants/rutas';\n\n/** Categorías de grupo (las mismas que usa crear ruta). */\nconst CATEGORIES: { id: string; label: string }[] = [\n  { id: 'senderismo', label: 'Senderismo' },\n  { id: 'ciclismo', label: 'Ciclismo' },\n  { id: 'auto', label: 'Ruta en auto' },\n  { id: 'moto', label: 'Ruta en moto' },\n  { id: 'running', label: 'Running' },\n  { id: 'camping', label: 'Camping' },\n  { id: 'foto', label: 'Fotografía' },\n  { id: 'urbano', label: 'Ciudad' },\n  { id: 'gastronomia', label: 'Gastronomía' },\n];\n\nexport default function LifeBookGroupsScreen() {\n  return (\n    <AuthGate>\n      <GroupsContent />\n    </AuthGate>\n  );\n}\n\nfunction GroupsContent() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  /* P3: se puede llegar con un CÓDIGO (enlace de grupo fijado en un perfil). */\n  const params = useLocalSearchParams<{ code?: string }>();\n  const [query, setQuery] = useState('');\n  const [city, setCity] = useState<string | null>(null);\n  const [category, setCategory] = useState<string | null>(null);\n  const [groups, setGroups] = useState<LbGroupCard[]>([]);\n  const [cursor, setCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [card, setCard] = useState<LbGroupCard | null>(null);\n  const [cardOpen, setCardOpen] = useState(false);\n  /**\n   * El código por el que se ha abierto la ficha, si se ha abierto con uno. Se guarda para\n   * pasárselo a la ficha: al unirse, el servidor gasta una entrada del enlace (y respeta\n   * su tope). Abrir la ficha desde la lista de Descubrir NO trae código: ahí no se gasta.\n   */\n  const [cardCode, setCardCode] = useState<string | null>(null);\n  /* Parte 28 (G4): entrar con el CÓDIGO de ruta (sin buscador). */\n  const [codeOpen, setCodeOpen] = useState(false);\n  const [code, setCode] = useState('');\n  const [codeBusy, setCodeBusy] = useState(false);\n  const [codeError, setCodeError] = useState<string | null>(null);\n\n  /** Resuelve el código y abre la ficha del grupo (y ahí te unes). */\n  const abrirCodigo = async (crudo: string, avisar = false) => {\n    const limpio = crudo.trim();\n    if (limpio.length < 4) {\n      setCodeError('Escribe el código completo (6 caracteres).');\n      if (avisar) Alert.alert('Enlace de grupo', 'Ese enlace no trae un código válido.');\n      return;\n    }\n    setCodeBusy(true);\n    setCodeError(null);\n    try {\n      const g = await lifebookGroupsApi.byCode(limpio);\n      setCard(g);\n      setCardCode(limpio.toUpperCase());\n      setCodeOpen(false);\n      setCode('');\n      setCardOpen(true);\n    } catch (e) {\n      const msg = e instanceof Error ? e.message : 'No encontré ese código.';\n      setCodeError(msg);\n      // Si el código viene de un ENLACE (no escrito a mano) la hoja del código está\n      // cerrada: sin este aviso el usuario no vería nada y parecería que no pasó nada.\n      if (avisar) Alert.alert('Enlace de grupo', msg);\n    } finally { setCodeBusy(false); }\n  };\n\n  /** Botón «Abrir» de la hoja del código. */\n  const abrirPorCodigo = () => abrirCodigo(code);\n\n  // P3: si llego con `?code=XXXX` (enlace de grupo del perfil), abro la ficha sin\n  // obligar a copiar el código a mano. Un código CADUCADO lo dice el servidor y aquí\n  // sale en un aviso.\n  const codeParam = params.code;\n  useEffect(() => {\n    if (!codeParam) return;\n    setCode(codeParam);\n    void abrirCodigo(codeParam, true);\n    // Solo cuando cambia el código que llega por la ruta.\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [codeParam]);\n\n  const load = useCallback(async (opts: { append?: boolean; cursor?: string | null } = {}) => {\n    try {\n      const res = await lifebookGroupsApi.list({\n        q: query.trim() || undefined,\n        city: city ?? undefined,\n        category: category ?? undefined,\n        cursor: opts.append ? (opts.cursor ?? undefined) : undefined,\n        limit: 20,\n      });\n      setGroups((prev) => (opts.append ? [...prev, ...(res.groups ?? [])] : (res.groups ?? [])));\n      setCursor(res.nextCursor ?? null);\n    } catch {\n      if (!opts.append) setGroups([]);\n      setCursor(null);\n    } finally {\n      setLoading(false);\n      setRefreshing(false);\n      setLoadingMore(false);\n    }\n  }, [query, city, category]);\n\n  // Búsqueda con retardo (350 ms) y recarga al cambiar los filtros.\n  useEffect(() => {\n    setLoading(true);\n    const t = setTimeout(() => { void load(); }, 350);\n    return () => clearTimeout(t);\n  }, [load]);\n\n  const abrirFicha = async (id: string) => {\n    try {\n      setCard(await lifebookGroupsApi.card(id));\n      // Desde la lista de Descubrir no hay código: entrar por aquí no gasta entradas.\n      setCardCode(null);\n      setCardOpen(true);\n    } catch (e) {\n      // Grupo privado/oculto o borrado entre la lista y el toque: se avisa y se\n      // quita de la lista (el listado solo trae públicos).\n      setGroups((prev) => prev.filter((g) => g.id !== id));\n      Alert.alert('Grupo', e instanceof Error ? e.message : 'No se pudo abrir el grupo.');\n    }\n  };\n\n  const vacio = useMemo(() => !loading && groups.length === 0, [loading, groups.length]);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera */}\n      <View style={[styles.header, { backgroundColor: colors.card, borderBottomColor: alpha(colors.border, 0.6) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={8} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900' }}>Descubrir grupos</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Rutas y comunidades abiertas cerca de ti</Text>\n        </View>\n        {/* Parte 28 (G4): entrar con el código que te hayan pasado */}\n        <Pressable onPress={() => { setCodeOpen(true); setCodeError(null); }} hitSlop={8} accessibilityLabel=\"Tengo un código de ruta\"\n          style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, backgroundColor: alpha(colors.primary, 0.12), borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6 }}>\n          <QrCode size={14} color={colors.primary} />\n          <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Código</Text>\n        </Pressable>\n      </View>\n\n      {/* Buscador */}\n      <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\n        <Search size={16} color={colors.textSecondary} />\n        <TextInput\n          value={query}\n          onChangeText={setQuery}\n          placeholder=\"Buscar grupos por nombre o descripción…\"\n          placeholderTextColor={colors.textSecondary}\n          style={{ flex: 1, marginLeft: espaciado.e8, color: colors.textPrimary, fontSize: tipografia.body }}\n          accessibilityLabel=\"Buscar grupos\"\n        />\n        {query.length > 0 ? (\n          <Pressable onPress={() => setQuery('')} hitSlop={8} accessibilityLabel=\"Borrar la búsqueda\">\n            <X size={16} color={colors.textSecondary} />\n          </Pressable>\n        ) : null}\n      </View>\n\n      {/* Filtros */}\n      <FlatList\n        horizontal\n        style={styles.chipRow}\n        showsHorizontalScrollIndicator={false}\n        data={[{ id: '__all__', label: 'Todas' }, ...LB_CITIES.map((c) => ({ id: c, label: c }))]}\n        keyExtractor={(x) => x.id}\n        contentContainerStyle={{ gap: espaciado.e6, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}\n        renderItem={({ item }) => {\n          const active = item.id === '__all__' ? city === null : city === item.id;\n          return (\n            <Pressable\n              onPress={() => setCity(item.id === '__all__' ? null : item.id)}\n              accessibilityLabel={`Ciudad ${item.label}`}\n              style={[styles.chip, { backgroundColor: active ? alpha(colors.primary, 0.14) : colors.surface, borderColor: active ? colors.primary : 'transparent' }]}\n            >\n              <Text style={{ color: active ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{item.label}</Text>\n            </Pressable>\n          );\n        }}\n      />\n      <FlatList\n        horizontal\n        style={styles.chipRow}\n        showsHorizontalScrollIndicator={false}\n        data={[{ id: '__all__', label: 'Todo' }, ...CATEGORIES]}\n        keyExtractor={(x) => x.id}\n        contentContainerStyle={{ gap: espaciado.e6, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}\n        renderItem={({ item }) => {\n          const active = item.id === '__all__' ? category === null : category === item.id;\n          return (\n            <Pressable\n              onPress={() => setCategory(item.id === '__all__' ? null : item.id)}\n              accessibilityLabel={`Categoría ${item.label}`}\n              style={[styles.chip, { backgroundColor: active ? alpha(colors.secondary, 0.14) : colors.surface, borderColor: active ? colors.secondary : 'transparent' }]}\n            >\n              <Text style={{ color: active ? colors.secondary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{item.label}</Text>\n            </Pressable>\n          );\n        }}\n      />\n\n      {/* Lista */}\n      {loading ? (\n        <ActivityIndicator color={colors.primary} style={{ marginTop: 40 }} />\n      ) : (\n        <FlatList\n          data={groups}\n          keyExtractor={(g) => g.id}\n          contentContainerStyle={{ padding: espaciado.e14, gap: espaciado.e10, paddingBottom: insets.bottom + 24 }}\n          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => { setRefreshing(true); void load(); }} tintColor={colors.primary} />}\n          onEndReachedThreshold={0.4}\n          onEndReached={() => {\n            if (!cursor || loadingMore) return;\n            setLoadingMore(true);\n            void load({ append: true, cursor });\n          }}\n          ListEmptyComponent={\n            vacio ? (\n              <View style={{ alignItems: 'center', marginTop: 50, gap: espaciado.e6 }}>\n                <Compass size={26} color={colors.textSecondary} />\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n                  No hay grupos públicos con esos filtros.{'\\n'}Puedes crear el tuyo desde Mensajes → «Crear grupo».\n                </Text>\n              </View>\n            ) : null\n          }\n          ListFooterComponent={loadingMore ? <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e12 }} /> : null}\n          renderItem={({ item }) => (\n            <Pressable\n              onPress={() => abrirFicha(item.id)}\n              accessibilityLabel={`Grupo ${item.title}, ${item.membersCount} miembros`}\n              style={({ pressed }) => [styles.groupRow, { backgroundColor: colors.card, opacity: pressed ? 0.85 : 1 }]}\n            >\n              {item.photoUrl ? (\n                <Image source={{ uri: absUrl(item.photoUrl) }} style={styles.groupPhoto} />\n              ) : (\n                <View style={[styles.groupPhoto, styles.center, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n                  <Text style={{ color: colors.primary, fontWeight: '900', fontSize: 18 }}>\n                    {(item.title || '?').trim().charAt(0).toUpperCase()}\n                  </Text>\n                </View>\n              )}\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 14.5 }} numberOfLines={1}>{item.title}</Text>\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e3 }}>\n                  <Users size={12} color={colors.textSecondary} />\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{item.membersCount}</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }} numberOfLines={1}>\n                    · {[item.city, item.category].filter(Boolean).join(' · ') || 'sin ubicación'}\n                  </Text>\n                </View>\n                {item.description ? (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }} numberOfLines={2}>{item.description}</Text>\n                ) : null}\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e6 }}>\n                  {item.myRole ? (\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\n                      <Check size={12} color={colors.primary} />\n                      <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                        {item.myRole === 'owner' ? 'Eres el organizador' : 'Ya estás dentro'}\n                      </Text>\n                    </View>\n                  ) : item.requestState === 'pending' ? (\n                    <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '800' }}>Solicitud enviada</Text>\n                  ) : (\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\n                      {item.joinMode === 'open'\n                        ? <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Entrada libre</Text>\n                        : item.joinMode === 'approval'\n                          ? <><Lock size={12} color={colors.secondary} /><Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '800' }}>Pide entrar</Text></>\n                          : <><ShieldQuestion size={12} color={colors.secondary} /><Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '800' }}>Responde para entrar</Text></>}\n                    </View>\n                  )}\n                </View>\n              </View>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.title }}>›</Text>\n            </Pressable>\n          )}\n        />\n      )}\n\n      <GroupCardSheet\n        visible={cardOpen}\n        group={card}\n        /* El código por el que se ha llegado, si se ha llegado por uno: al unirse se manda\n           y eso es lo que gasta una entrada del enlace y hace respetar su tope. */\n        code={cardCode ?? undefined}\n        onClose={() => { setCardOpen(false); setCardCode(null); }}\n        onChanged={() => void load()}\n        onJoined={(id) => {\n          const g = groups.find((x) => x.id === id);\n          irSeguro.libre('/lifebook-chat/[id]', { id, name: g?.title ?? card?.title ?? 'Grupo', isGroup: '1' });\n        }}\n      />\n\n      {/* Parte 28 (G4): entrar con el código de ruta */}\n      <Modal visible={codeOpen} transparent animationType=\"slide\" onRequestClose={() => setCodeOpen(false)} statusBarTranslucent>\n        <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={() => setCodeOpen(false)} />\n        <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e10 }}>\n            <QrCode size={18} color={colors.primary} />\n            <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1, marginLeft: espaciado.e8 }}>\n              Tengo un código de ruta\n            </Text>\n            <Pressable onPress={() => setCodeOpen(false)} hitSlop={10} accessibilityLabel=\"Cerrar\">\n              <X size={20} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e8 }}>\n            Escribe los 6 caracteres que te han pasado (o escanea su QR desde la cámara).\n          </Text>\n          <TextInput\n            value={code}\n            onChangeText={(v) => { setCode(v.toUpperCase()); setCodeError(null); }}\n            placeholder=\"ABC123\"\n            placeholderTextColor={colors.textSecondary}\n            autoCapitalize=\"characters\"\n            maxLength={8}\n            accessibilityLabel=\"Código del grupo\"\n            style={[styles.codeInput, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n          />\n          {codeError ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>{codeError}</Text> : null}\n          <Pressable onPress={abrirPorCodigo} disabled={codeBusy} accessibilityLabel=\"Abrir el grupo con ese código\"\n            style={[styles.cta, { backgroundColor: colors.primary }]}>\n            {codeBusy ? <ActivityIndicator size=\"small\" color={brand.white} /> : (\n              <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Abrir el grupo</Text>\n            )}\n          </Pressable>\n        </View>\n      </Modal>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth },\n  searchBox: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: 42, marginHorizontal: espaciado.e14, marginTop: espaciado.e10 },\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderWidth: 1, flexShrink: 0 },\n  // Fijar la fila: sin alto propio, el FlatList horizontal se comprime y el texto sale recortado\n  // contra la fila contigua (medido en el móvil: 17 px de alto en ciudades vs 23 en categorías).\n  chipRow: { flexGrow: 0, flexShrink: 0, marginVertical: espaciado.e5 },\n  groupRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderRadius: radios.lg, padding: espaciado.e12 },\n  groupPhoto: { width: 54, height: 54, borderRadius: 14 },\n  center: { alignItems: 'center', justifyContent: 'center' },\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  codeInput: {\n    borderRadius: 14, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e12, fontSize: 22, fontWeight: '900',\n    letterSpacing: 6, textAlign: 'center',\n  },\n  cta: { marginTop: espaciado.e14, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e14 },\n});\n","/**\n * GroupCardSheet — Parte 27 (Fase G3): la FICHA de un grupo antes de entrar.\n *\n * Enseña lo que hace falta para decidir (foto, nombre, ciudad/categoría,\n * descripción, tema, cuántos son, quiénes están y el organizador) y el botón\n * para unirse, que se comporta según la condición de ingreso:\n *  · `open`     → «Unirse» entra al momento.\n *  · `approval` → deja una **solicitud** («Solicitud enviada · esperando»).\n *  · `question` → pide la respuesta a la pregunta del organizador.\n * Si ya soy miembro, el botón abre el chat.\n */\nimport React, { useState } from 'react';\nimport { ActivityIndicator, Image, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Check, Clock, LogIn, ShieldQuestion, Users, X } from 'lucide-react-native';\nimport { absUrl } from '../../api/config';\nimport { lifebookGroupsApi, type LbGroupCard } from '../../api/lifebook';\nimport type { LbGroupCardConEnlace } from '../../api/lifebookGrupos';\nimport { gruposEnlacesApi } from '../../api/lifebookGrupos';\nimport { formaHoja } from './ui/Sheet';\n\ninterface Props {\n  visible: boolean;\n  group: LbGroupCard | null;\n  onClose: () => void;\n  /** Me he unido (o ya era miembro) → abrir el chat. */\n  onJoined: (groupId: string) => void;\n  /** La solicitud cambió (para refrescar la lista). */\n  onChanged?: () => void;\n  /**\n   * El CÓDIGO del enlace por el que se ha llegado aquí, si se ha llegado por uno (el del\n   * perfil, el QR, o uno que te hayan pasado). Se manda al unirse para que el servidor\n   * gaste una de las entradas del enlace y respete su tope. Si se entra desde la lista de\n   * Descubrir grupos, no hay código y no se gasta nada.\n   */\n  code?: string;\n}\n\nexport function GroupCardSheet({ visible, group, onClose, onJoined, onChanged, code }: Props) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [answer, setAnswer] = useState('');\n  const [note, setNote] = useState('');\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [pedido, setPedido] = useState(false);\n\n  React.useEffect(() => {\n    if (!visible) return;\n    setAnswer(''); setNote(''); setError(null); setPedido(false);\n  }, [visible, group?.id]);\n\n  if (!group) return null;\n\n  const soyMiembro = !!group.myRole;\n  const pendiente = pedido || group.requestState === 'pending';\n  const rechazado = group.requestState === 'rejected';\n\n  /**\n   * Lo que se sabe del ENLACE por el que se ha llegado (`invite` viene del servidor solo\n   * cuando se ha resuelto un código). Con el enlace GASTADO no se deja entrar desde aquí:\n   * el servidor lo rechazaría igual (400) y, si la app lo intentara sin el código, estaría\n   * saltándose a la espalda del dueño el tope que él puso.\n   */\n  const invitacion = (group as LbGroupCardConEnlace).invite;\n  const enlaceAgotado = !!code && !!invitacion && invitacion.usesLeft === 0;\n\n  const unirse = async (withAnswer: boolean) => {\n    setError(null);\n    setBusy(true);\n    try {\n      const extra = withAnswer ? { answer: answer.trim() || undefined, note: note.trim() || undefined } : {};\n      // `gruposEnlacesApi.unirse` es la misma ruta que `lifebookGroupsApi.join`, pero\n      // admite el `code` (el tipo de `api/lifebook.ts` no, y ese fichero no se toca).\n      const res = code\n        ? await gruposEnlacesApi.unirse(group.id, { ...extra, code })\n        : await lifebookGroupsApi.join(group.id, extra);\n      if (res.joined) { onJoined(group.id); onClose(); return; }\n      setPedido(true);\n      onChanged?.();\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo completar la solicitud.');\n    } finally { setBusy(false); }\n  };\n\n  const cancelar = async () => {\n    setBusy(true);\n    try {\n      await lifebookGroupsApi.cancelJoin(group.id);\n      setPedido(false);\n      onChanged?.();\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cancelar.');\n    } finally { setBusy(false); }\n  };\n\n  const etiquetaIngreso = group.joinMode === 'open'\n    ? 'Entrada libre'\n    : group.joinMode === 'approval' ? 'Con aprobación del organizador' : 'Pregunta de ingreso';\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.header}>\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1 }}>Ficha del grupo</Text>\n          <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n            <X size={20} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n\n        <ScrollView style={{ maxHeight: 460 }} keyboardShouldPersistTaps=\"handled\">\n          <View style={{ flexDirection: 'row', gap: espaciado.e12, alignItems: 'center' }}>\n            {group.photoUrl ? (\n              <Image source={{ uri: absUrl(group.photoUrl) }} style={styles.photo} />\n            ) : (\n              <View style={[styles.photo, styles.center, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n                <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.title }}>\n                  {(group.title || '?').trim().charAt(0).toUpperCase()}\n                </Text>\n              </View>\n            )}\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle }} numberOfLines={2}>{group.title}</Text>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e4 }}>\n                <Users size={13} color={colors.textSecondary} />\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{group.membersCount} miembros</Text>\n              </View>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                {[group.city, group.barrio, group.category].filter(Boolean).join(' · ') || 'Sin ubicación'}\n              </Text>\n            </View>\n          </View>\n\n          {group.topic ? (\n            <View style={[styles.chipRow, { backgroundColor: alpha(colors.primary, 0.08), marginTop: espaciado.e12 }]}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>📌 {group.topic}</Text>\n            </View>\n          ) : null}\n\n          {group.description ? (\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 19, marginTop: espaciado.e12 }}>{group.description}</Text>\n          ) : null}\n\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e12 }}>\n            {group.joinMode === 'open'\n              ? <LogIn size={14} color={colors.textSecondary} />\n              : group.joinMode === 'approval' ? <Clock size={14} color={colors.textSecondary} /> : <ShieldQuestion size={14} color={colors.textSecondary} />}\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{etiquetaIngreso}</Text>\n          </View>\n\n          {/* Entradas del enlace: solo se sabe cuando se ha llegado CON un código. Si el\n              enlace tiene tope se dice cuántas quedan; si no tiene, no se dice nada (no\n              hay nada que contar). */}\n          {invitacion && invitacion.usesLeft !== null ? (\n            <Text style={{ color: invitacion.usesLeft === 0 ? colors.danger : colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>\n              {invitacion.usesLeft === 0\n                ? 'Este enlace ya no admite a más gente'\n                : `Quedan ${invitacion.usesLeft} entrada${invitacion.usesLeft === 1 ? '' : 's'} por este enlace`}\n              {invitacion.expiresAt ? ` · caduca el ${new Date(invitacion.expiresAt).toLocaleDateString()}` : ''}\n            </Text>\n          ) : null}\n\n          {group.placeName ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>📍 Punto de encuentro: {group.placeName}</Text>\n          ) : null}\n\n          {group.ownerName ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>👑 Organiza {group.ownerName}</Text>\n          ) : null}\n\n          {(group.members ?? []).length > 0 ? (\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, marginTop: espaciado.e12 }}>\n              {(group.members ?? []).map((m) => (\n                <View key={m.id} style={[styles.memberChip, { backgroundColor: colors.surface }]}>\n                  {m.avatarUrl ? (\n                    <Image source={{ uri: absUrl(m.avatarUrl) }} style={styles.memberAvatar} />\n                  ) : (\n                    <View style={[styles.memberAvatar, { backgroundColor: alpha(colors.primary, 0.18) }]} />\n                  )}\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }} numberOfLines={1}>\n                    {(m.fullName ?? 'Usuario').split(' ')[0]}{m.role === 'owner' ? ' 👑' : ''}\n                  </Text>\n                </View>\n              ))}\n            </View>\n          ) : null}\n\n          {/* Pregunta de ingreso */}\n          {!soyMiembro && group.joinMode === 'question' && group.joinQuestion && !pendiente ? (\n            <View style={{ marginTop: espaciado.e14 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }}>PREGUNTA DEL ORGANIZADOR</Text>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, marginTop: espaciado.e4 }}>{group.joinQuestion}</Text>\n              <TextInput\n                value={answer}\n                onChangeText={(v) => { setAnswer(v); setError(null); }}\n                placeholder=\"Tu respuesta\"\n                placeholderTextColor={colors.textSecondary}\n                maxLength={200}\n                accessibilityLabel=\"Respuesta a la pregunta de ingreso\"\n                style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, marginTop: espaciado.e8 }]}\n              />\n            </View>\n          ) : null}\n\n          {!soyMiembro && pendiente ? (\n            <View style={[styles.stateBox, { backgroundColor: alpha(colors.secondary, 0.10), borderColor: alpha(colors.secondary, 0.3) }]}>\n              <Clock size={16} color={colors.secondary} />\n              <View style={{ flex: 1 }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Solicitud enviada</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                  El organizador la revisará y te avisará cuando te acepte.\n                </Text>\n              </View>\n            </View>\n          ) : null}\n\n          {!soyMiembro && rechazado && !pendiente ? (\n            <View style={[styles.stateBox, { backgroundColor: alpha(colors.danger, 0.08), borderColor: alpha(colors.danger, 0.3) }]}>\n              <X size={16} color={colors.danger} />\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, flex: 1 }}>\n                El organizador no aceptó tu solicitud. Puedes volver a intentarlo.\n              </Text>\n            </View>\n          ) : null}\n\n          {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>{error}</Text> : null}\n        </ScrollView>\n\n        {/* Botón según el estado */}\n        {soyMiembro ? (\n          <Pressable\n            onPress={() => { onJoined(group.id); onClose(); }}\n            accessibilityLabel={`Abrir el chat de ${group.title}`}\n            style={[styles.cta, { backgroundColor: colors.primary }]}\n          >\n            <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Abrir el chat</Text>\n          </Pressable>\n        ) : enlaceAgotado && !pendiente ? (\n          /* El enlace ya ha dado todas las entradas que el dueño permitió. Se dice claro y\n             no se deja entrar desde aquí: es lo mismo que hace el servidor. */\n          <View\n            accessibilityLabel=\"Este enlace ya no admite a más gente\"\n            style={[styles.cta, { backgroundColor: alpha(colors.textSecondary, 0.12) }]}\n          >\n            <Text style={{ color: colors.textSecondary, fontWeight: '900', fontSize: tipografia.body, textAlign: 'center' }}>\n              Este enlace ya no admite a más gente\n            </Text>\n          </View>\n        ) : pendiente ? (\n          <Pressable onPress={cancelar} disabled={busy} accessibilityLabel=\"Cancelar mi solicitud\"\n            style={[styles.cta, { backgroundColor: alpha(colors.textSecondary, 0.12) }]}>\n            {busy ? <ActivityIndicator size=\"small\" color={colors.textSecondary} /> : (\n              <Text style={{ color: colors.textSecondary, fontWeight: '900', fontSize: tipografia.body }}>Cancelar la solicitud</Text>\n            )}\n          </Pressable>\n        ) : group.joinMode === 'question' && group.joinQuestion ? (\n          <Pressable onPress={() => unirse(true)} disabled={busy} accessibilityLabel=\"Enviar mi respuesta y unirme\"\n            style={[styles.cta, { backgroundColor: colors.primary }]}>\n            {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : (\n              <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>Enviar respuesta y unirme</Text>\n            )}\n          </Pressable>\n        ) : (\n          <Pressable onPress={() => unirse(false)} disabled={busy} accessibilityLabel={`Unirme a ${group.title}`}\n            style={[styles.cta, { backgroundColor: colors.primary }]}>\n            {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : (\n              <Text style={{ color: brand.white, fontWeight: '900', fontSize: 15 }}>\n                {group.joinMode === 'approval' ? 'Pedir entrar' : 'Unirme'}\n              </Text>\n            )}\n          </Pressable>\n        )}\n      </View>\n    </Modal>\n  );\n}\n\n/** Marca de «ya dentro» reutilizable (la usa la lista de descubrimiento). */\nexport function JoinedBadge({ colors, label }: { colors: any; label: string }) {\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\n      <Check size={13} color={colors.primary} />\n      <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>{label}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheet: { ...formaHoja },\n  header: { flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e10 },\n  photo: { width: 56, height: 56, borderRadius: 14 },\n  center: { alignItems: 'center', justifyContent: 'center' },\n  chipRow: { borderRadius: 10, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e8 },\n  input: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  memberChip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4 },\n  memberAvatar: { width: 18, height: 18, borderRadius: 9 },\n  stateBox: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderWidth: 1, borderRadius: radios.md, padding: espaciado.e10, marginTop: espaciado.e12 },\n  cta: { marginTop: espaciado.e14, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e14 },\n});\n","/**\n * app/lifebook-guardados.tsx — MIS GUARDADOS (favoritos), FUERA DEL PERFIL.\n *\n * ── POR QUÉ EXISTE (encargo del dueño) ──────────────────────────────────────────\n * Los guardados vivían **solo** en la pestaña «Colección» del perfil propio: para ver lo que te había\n * gustado había que entrar en tu perfil. Esta pantalla los saca de ahí y se abre desde el **catálogo**\n * (el corazón de la cabecera), que es donde uno está mirando productos cuando quiere volver a uno.\n *\n * ── QUÉ HACE ────────────────────────────────────────────────────────────────────\n *   · Lista lo guardado con su precio y su estado (nuevo/usado), sin fotos: los datos que se usan aquí\n *     son los que el servidor manda a esta pantalla (`mySaved`), y no se inventa ninguno.\n *   · **Gestionar** = quitar de guardados ahí mismo (el mismo corazón que los puso) y abrir el producto.\n *   · Si no hay nada, lo dice y explica cómo se guarda («el corazón de un producto»).\n */\nimport React, { useCallback, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, EmptyState, espaciado, GhostButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AlertCircle, ArrowLeft, Heart } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { commerceApi, type LbProductCard } from '../api/commerce';\nimport { lbXaf } from '../constants/lifebook';\n\nexport default function LifeBookGuardadosScreen() {\n  return (\n    <AuthGate>\n      <GuardadosContent />\n    </AuthGate>\n  );\n}\n\nfunction GuardadosContent() {\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n  const [items, setItems] = useState<LbProductCard[] | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [cargando, setCargando] = useState(false);\n  const [quitando, setQuitando] = useState<string | null>(null);\n  const mounted = useRef(true);\n\n  const cargar = useCallback(async () => {\n    setCargando(true);\n    try {\n      const r = await commerceApi.mySaved();\n      if (mounted.current) { setItems(r.items ?? []); setError(null); }\n    } catch (e) {\n      if (mounted.current) setError(e instanceof Error ? e.message : 'No se pudieron cargar tus guardados');\n    } finally {\n      if (mounted.current) setCargando(false);\n    }\n  }, []);\n\n  useFocusEffect(useCallback(() => {\n    mounted.current = true;\n    cargar();\n    return () => { mounted.current = false; };\n  }, [cargar]));\n\n  /** Quitar de guardados: el mismo «corazón» que los puso, desde aquí. */\n  const quitar = async (id: string) => {\n    if (quitando) return;\n    setQuitando(id);\n    try {\n      await commerceApi.toggleSave(id);\n      if (mounted.current) setItems((prev) => (prev ?? []).filter((p) => p.id !== id));\n    } catch (e) {\n      Alert.alert('Guardados', e instanceof Error ? e.message : 'No se pudo quitar de guardados');\n    } finally {\n      if (mounted.current) setQuitando(null);\n    }\n  };\n\n  if (error && !items) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24, gap: espaciado.e12 }]}>\n        <AlertCircle size={34} color={colors.danger} />\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', textAlign: 'center' }}>{error}</Text>\n        <GhostButton title=\"Volver\" onPress={() => router.back()} />\n      </View>\n    );\n  }\n  if (!items) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10, flex: 1 }} numberOfLines={1}>\n          Mis guardados\n        </Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n          {items.length === 1 ? '1 producto' : `${items.length} productos`}\n        </Text>\n      </View>\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e28 }}\n        refreshControl={<RefreshControl refreshing={cargando} onRefresh={cargar} tintColor={colors.primary} />}\n      >\n        {items.length === 0 ? (\n          /* Ya tenía título, explicación y salida: solo se pasa al kit (no se toca la copia). */\n          <EmptyState\n            icono={<Heart size={34} color={colors.textSecondary} />}\n            titulo=\"Todavía no has guardado nada\"\n            texto=\"Lo que guardes con el corazón de un producto aparece aquí, sin tener que entrar en tu perfil.\"\n            accionLabel=\"Ver el catálogo\"\n            onAccion={() => router.push('/lifebook-catalog' as never)}\n          />\n        ) : (\n          items.map((p) => (\n            <View key={p.id} style={[styles.tarjeta, { borderColor: alpha(colors.border, 0.6) }]}>\n              <Pressable\n                onPress={() => router.push({ pathname: '/lifebook-product/[id]', params: { id: p.id } } as never)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Abrir ${p.title}`}\n                style={{ flex: 1 }}\n              >\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }} numberOfLines={2}>\n                  {p.title}\n                </Text>\n                {p.shortDescription ? (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }} numberOfLines={2}>\n                    {p.shortDescription}\n                  </Text>\n                ) : null}\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e6 }}>\n                  {p.priceXaf === null ? 'Precio a consultar' : lbXaf(p.priceXaf)}\n                  {p.oldPriceXaf && p.priceXaf && p.oldPriceXaf > p.priceXaf ? (\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                      {'  '}antes {lbXaf(p.oldPriceXaf)}\n                    </Text>\n                  ) : null}\n                </Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                  {p.condition === 'used' ? 'Usado' : 'Nuevo'}\n                  {p.stockMode === 'exact' ? '' : ' · a pedir'}\n                </Text>\n              </Pressable>\n              <Pressable\n                onPress={() => quitar(p.id)}\n                hitSlop={8}\n                disabled={quitando === p.id}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Quitar ${p.title} de guardados`}\n                style={[styles.quitar, { borderColor: alpha(colors.border, 0.9) }]}\n              >\n                <Heart size={16} color={colors.primary} />\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                  {quitando === p.id ? 'Quitando…' : 'Quitar'}\n                </Text>\n              </Pressable>\n            </View>\n          ))\n        )}\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  tarjeta: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderWidth: StyleSheet.hairlineWidth,\n    borderRadius: 14, padding: espaciado.e14, marginBottom: espaciado.e10,\n  },\n  quitar: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, borderWidth: 1, borderRadius: 10,\n    paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e8,\n  },\n});\n","/**\n * lifebook-hotel-calendario — PRECIOS POR NOCHE, ESTANCIA MÍNIMA Y CIERRE DE FECHAS.\n *\n * Es la tercera pantalla que le faltaba al hotelero: el servidor sabía guardar excepciones\n * de calendario desde la Parte 42 (`PUT my/room-types/:id/calendar`) y el cliente tenía el\n * método escrito… pero **ninguna pantalla lo llamaba**. Sin esto, el hotelero no puede subir\n * el precio de una noche ni cerrar una semana.\n *\n * DOS DECISIONES QUE NO SON OBVIAS:\n *\n * 1. **No se reutiliza `CalendarPicker`.** Ese calendario es el del HUÉSPED, y a propósito\n *    deja sin tocar los días cerrados y los llenos (así el huésped no llega al 409). Para el\n *    hotelero es justo lo contrario: tiene que poder seleccionar un rango **cerrado** para\n *    volver a abrirlo, y un día lleno para ponerle temporada alta. Aquí todos los días desde\n *    hoy son seleccionables, y el estado (cerrado / con precio propio / lleno) solo se pinta.\n *\n * 2. **El rango es de NOCHES, no de días de calendario.** El servidor aplica la excepción a\n *    las noches del rango, ambas incluidas. Si el hotelero toca el 5 y el 8, son las noches\n *    del 5, 6 y 7 (la del 8 es la salida). Se dice con todas las letras en la pantalla.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Switch, Text, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { hotelApi, type CalendarDay, type HotelRoom } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport {\n  DOW_SHORT, addDaysIso, dowMondayFirst, isWeekendNight, longDate, monthGrid,\n  monthLabel, nightsBetween, parseIso, shiftMonth, todayIso, xaf,\n} from '../utils/datetime';\n\n/** 92 noches es el tope que acepta el servidor de una vez. */\nconst MAX_NOCHE = 92;\n/** Días que se piden al servidor para pintar (su ficha pública da 60). */\nconst VENTANA = 92;\n\nconst DIAS_SEMANA = [\n  { dow: 1, label: 'Lun' }, { dow: 2, label: 'Mar' }, { dow: 3, label: 'Mié' },\n  { dow: 4, label: 'Jue' }, { dow: 5, label: 'Vie' }, { dow: 6, label: 'Sáb' },\n  { dow: 0, label: 'Dom' },\n];\n\nexport default function CalendarioScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const p = useLocalSearchParams<{ id?: string; nombre?: string }>();\n  const roomId = String(p.id ?? '');\n\n  const [room, setRoom] = useState<HotelRoom | null>(null);\n  const [dias, setDias] = useState<CalendarDay[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [noVisible, setNoVisible] = useState(false);\n  const [guardando, setGuardando] = useState(false);\n  const [aviso, setAviso] = useState<string | null>(null);\n\n  const hoy = todayIso();\n  const [desde, setDesde] = useState(hoy);\n  const [hasta, setHasta] = useState(addDaysIso(hoy, 2));\n  const [precio, setPrecio] = useState('');\n  const [minNoches, setMinNoches] = useState('');\n  const [cerrar, setCerrar] = useState(false);\n  const [semana, setSemana] = useState<number[]>([]);\n  const [nota, setNota] = useState('');\n\n  const [mes, setMes] = useState(() => {\n    const d = parseIso(hoy);\n    return { year: d.getUTCFullYear(), month0: d.getUTCMonth() };\n  });\n\n  const cargar = useCallback(async () => {\n    setCargando(true);\n    setError(null);\n    setNoVisible(false);\n    try {\n      const out = await hotelApi.myRooms();\n      const r = (out.rooms ?? []).find((x) => x.id === roomId) ?? null;\n      setRoom(r);\n      try {\n        const cal = await hotelApi.calendar(roomId, hoy, addDaysIso(hoy, VENTANA - 1), 1);\n        setDias(cal.days ?? []);\n      } catch (e) {\n        // El calendario PÚBLICO exige que la habitación esté publicada y aprobada. Una\n        // habitación recién creada está en revisión, así que aquí no hay rejilla que pintar\n        // — pero SÍ se pueden poner precios (esa ruta comprueba solo que sea tuya).\n        if (e instanceof ApiError && (e.code === 'ROOM_NOT_FOUND' || e.code === 'RESERVATION_NOT_FOUND')) {\n          setNoVisible(true);\n          setDias([]);\n        } else {\n          throw e;\n        }\n      }\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar el calendario.');\n    } finally {\n      setCargando(false);\n    }\n  }, [roomId, hoy]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const porFecha = useMemo(() => {\n    const m = new Map<string, CalendarDay>();\n    for (const d of dias) m.set(d.date, d);\n    return m;\n  }, [dias]);\n\n  const noches = useMemo(() => {\n    if (!desde || !hasta || hasta < desde) return 0;\n    return nightsBetween(desde, addDaysIso(hasta, 1));\n  }, [desde, hasta]);\n\n  const base = room?.basePriceXaf ?? 0;\n\n  /** Cuántas noches del rango tienen algo puesto (precio propio o cerrado). */\n  const afectadas = useMemo(\n    () => dias.filter((d) => d.date >= desde && d.date <= hasta\n      && (d.closed || Number(d.priceXaf) !== Number(d.basePriceXaf))).length,\n    [dias, desde, hasta],\n  );\n\n  const tocarDia = (iso: string) => {\n    setAviso(null);\n    // Primer toque (o toque anterior al inicio): empieza un rango nuevo.\n    if (!desde || (desde && hasta) || iso < desde) {\n      setDesde(iso);\n      setHasta('');\n      return;\n    }\n    if (iso === desde) { setHasta(iso); return; }\n    if (nightsBetween(desde, addDaysIso(iso, 1)) > MAX_NOCHE) {\n      Alert.alert('Rango demasiado largo', `De una vez se pueden tocar como máximo ${MAX_NOCHE} noches.`);\n      return;\n    }\n    setHasta(iso);\n  };\n\n  const guardar = async (accion: 'set' | 'clear') => {\n    if (!desde || !hasta) { Alert.alert('Elige el rango', 'Toca el primer y el último día del rango.'); return; }\n    if (hasta < desde) { Alert.alert('Rango al revés', 'El último día no puede ser anterior al primero.'); return; }\n    if (noches > MAX_NOCHE) { Alert.alert('Rango demasiado largo', `Como máximo ${MAX_NOCHE} noches de una vez.`); return; }\n\n    const precioNum = precio.trim() ? Number(precio.replace(/[^\\d]/g, '')) : null;\n    const minNum = minNoches.trim() ? Number(minNoches.replace(/[^\\d]/g, '')) : null;\n    if (accion === 'set') {\n      if (precioNum !== null && (precioNum < 1 || precioNum > 100_000_000)) { Alert.alert('Precio no válido', 'El precio tiene que ser mayor que 0.'); return; }\n      if (minNum !== null && (minNum < 1 || minNum > 90)) { Alert.alert('Estancia mínima no válida', 'Tiene que estar entre 1 y 90 noches.'); return; }\n      if (precioNum === null && minNum === null && !cerrar) {\n        Alert.alert('Nada que guardar', 'Indica un precio, una estancia mínima o marca «cerrar estas fechas».');\n        return;\n      }\n    }\n\n    setGuardando(true);\n    setAviso(null);\n    try {\n      const out = await hotelApi.saveCalendar(roomId, {\n        action: accion,\n        from: desde,\n        to: hasta,\n        ...(accion === 'set'\n          ? {\n              priceXaf: precioNum, minNights: minNum, isClosed: cerrar,\n              note: nota.trim() || undefined,\n              ...(semana.length ? { weekdays: semana } : {}),\n            }\n          : {}),\n      });\n      const hecho = accion === 'set'\n        ? `Se aplicó a ${out.saved ?? noches} noche(s).`\n        : `Se quitó lo puesto en ${out.cleared ?? noches} noche(s).`;\n      setAviso(`${hecho}${out.warning ? `\\n⚠️ ${out.warning}` : ''}`);\n      await cargar();\n    } catch (e) {\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo guardar.');\n    } finally {\n      setGuardando(false);\n    }\n  };\n\n  const celdas = useMemo(() => monthGrid(mes.year, mes.month0), [mes.year, mes.month0]);\n  const mesDeHoy = parseIso(hoy);\n  const puedeAtras = mes.year > mesDeHoy.getUTCFullYear()\n    || (mes.year === mesDeHoy.getUTCFullYear() && mes.month0 > mesDeHoy.getUTCMonth());\n\n  if (cargando) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.cabecera, { paddingTop: insets.top + 8, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" hitSlop={10} style={styles.volver}>\n          <Text style={{ color: colors.textPrimary, fontSize: 30, lineHeight: 32 }}>‹</Text>\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900' }}>Precios y fechas</Text>\n          {/* El nombre de la habitación es del hotelero: dos líneas, sin recortar a media palabra. */}\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }} numberOfLines={2}>\n            {room?.name ?? String(p.nombre ?? 'Habitación')} · {xaf(base)} por noche\n          </Text>\n        </View>\n      </View>\n\n      {error ? (\n        <View style={{ padding: espaciado.e16 }}>\n          <Text style={{ color: colors.textSecondary, marginBottom: espaciado.e12 }}>{error}</Text>\n          <GhostButton title=\"Reintentar\" onPress={() => void cargar()} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }} keyboardShouldPersistTaps=\"handled\">\n          {aviso ? (\n            <View style={[styles.aviso, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.25) }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 19 }}>{aviso}</Text>\n            </View>\n          ) : null}\n\n          {noVisible ? (\n            <View style={[styles.aviso, { backgroundColor: alpha(colors.secondary, 0.09), borderColor: alpha(colors.secondary, 0.3) }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 19 }}>\n                Esta habitación todavía no está publicada (está en revisión), así que aún no se puede ver su\n                calendario día a día. **Sí puedes dejar puestos sus precios y cerrar fechas**: se aplicarán en\n                cuanto la aprueben.\n              </Text>\n            </View>\n          ) : null}\n\n          {/* ── Rango de noches ── */}\n          <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginBottom: espaciado.e3 }}>\n            1. Elige las noches\n          </Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>\n            Toca el primer día y el último. Son noches: del 5 al 8 son las noches del 5, el 6 y el 7\n            (la del 8 es la salida del huésped).\n          </Text>\n\n          <View style={[styles.rango, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700' }}>DESDE</Text>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>{desde ? longDate(desde) : '—'}</Text>\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700' }}>HASTA</Text>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>{hasta ? longDate(hasta) : '—'}</Text>\n            </View>\n            <View style={{ alignItems: 'flex-end' }}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900' }}>{noches} noche(s)</Text>\n              {afectadas ? (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>{afectadas} ya modificada(s)</Text>\n              ) : null}\n            </View>\n          </View>\n\n          {/* ── Rejilla: TODOS los días desde hoy son seleccionables ── */}\n          <View style={[styles.mes, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <View style={styles.mesCabecera}>\n              <Pressable\n                onPress={() => setMes(shiftMonth(mes.year, mes.month0, -1))}\n                disabled={!puedeAtras}\n                hitSlop={8}\n                style={{ opacity: puedeAtras ? 1 : 0.3 }}\n                accessibilityLabel=\"Mes anterior\"\n              >\n                <Text style={{ color: colors.textPrimary, fontSize: 22 }}>‹</Text>\n              </Pressable>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>\n                {monthLabel(mes.year, mes.month0)}\n              </Text>\n              <Pressable onPress={() => setMes(shiftMonth(mes.year, mes.month0, 1))} hitSlop={8} accessibilityLabel=\"Mes siguiente\">\n                <Text style={{ color: colors.textPrimary, fontSize: 22 }}>›</Text>\n              </Pressable>\n            </View>\n\n            <View style={styles.fila}>\n              {DOW_SHORT.map((d, i) => (\n                <Text key={`${d}-${i}`} style={[styles.dow, { color: colors.textSecondary }]}>{d}</Text>\n              ))}\n            </View>\n\n            {Array.from({ length: Math.ceil(celdas.length / 7) }, (_, f) => (\n              <View key={f} style={styles.fila}>\n                {celdas.slice(f * 7, f * 7 + 7).map((c) => {\n                  const d = porFecha.get(c.iso);\n                  const pasado = c.iso < hoy;\n                  const enRango = !!desde && !!hasta && c.iso >= desde && c.iso <= hasta;\n                  const esInicio = c.iso === desde;\n                  const esFin = c.iso === hasta;\n                  const cerrado = !!d?.closed;\n                  const precioPropio = !!d && Number(d.priceXaf) !== Number(d.basePriceXaf);\n                  const lleno = !!d && Number(d.freeUnits ?? 1) <= 0;\n                  const finde = isWeekendNight(c.iso);\n                  const color = esInicio || esFin ? colors.primary\n                    : enRango ? alpha(colors.primary, 0.18)\n                      : cerrado ? alpha(colors.danger, 0.12)\n                        : 'transparent';\n                  return (\n                    <Pressable\n                      key={c.iso}\n                      onPress={() => tocarDia(c.iso)}\n                      disabled={pasado || !c.inMonth}\n                      accessibilityLabel={`${c.day} de ${monthLabel(mes.year, mes.month0)}`}\n                      style={[styles.celda, { backgroundColor: color, opacity: c.inMonth && !pasado ? 1 : 0.25 }]}\n                    >\n                      <Text style={{\n                        color: esInicio || esFin ? brand.white : colors.textPrimary,\n                        fontSize: tipografia.caption, fontWeight: finde ? '900' : '700',\n                      }}>\n                        {c.day}\n                      </Text>\n                      {/* Adornos de estado: solo informan, no bloquean el toque. */}\n                      <View style={{ flexDirection: 'row', gap: espaciado.e2, marginTop: 1 }}>\n                        {cerrado ? <View style={[styles.punto, { backgroundColor: colors.danger }]} /> : null}\n                        {precioPropio && !cerrado ? <View style={[styles.punto, { backgroundColor: colors.secondary }]} /> : null}\n                        {lleno && !cerrado ? <View style={[styles.punto, { backgroundColor: colors.textSecondary }]} /> : null}\n                      </View>\n                    </Pressable>\n                  );\n                })}\n              </View>\n            ))}\n\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e6 }}>\n              ⬤ rojo = cerrado · ⬤ naranja = precio propio · ⬤ gris = sin habitaciones libres\n            </Text>\n          </View>\n\n          <View style={{ marginTop: espaciado.e10, flexDirection: 'row', gap: espaciado.e8 }}>\n            <View style={{ flex: 1 }}>\n              <GhostButton title=\"Hoy\" onPress={() => { setDesde(hoy); setHasta(addDaysIso(hoy, 2)); }} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <GhostButton title=\"Este mes entero\" onPress={() => { setDesde(hoy); setHasta(addDaysIso(hoy, 29)); }} />\n            </View>\n          </View>\n\n          {/* ── Qué aplicar ── */}\n          <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginTop: espaciado.e22, marginBottom: espaciado.e3 }}>\n            2. Qué aplicar a esas noches\n          </Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>\n            Precio de temporada, estancia mínima o cerrar. Si dejas un campo vacío, se mantiene lo que ya hubiera.\n          </Text>\n\n          <FormField\n            label={`Precio de esas noches en XAF (normal: ${xaf(base)})`}\n            value={precio} onChangeText={setPrecio} keyboardType=\"number-pad\" placeholder={String(base || 25000)}\n          />\n          <View style={{ height: 10 }} />\n          <FormField\n            label=\"Estancia mínima en esas noches\" value={minNoches} onChangeText={setMinNoches}\n            keyboardType=\"number-pad\" placeholder=\"Sin cambiar\"\n          />\n          <View style={{ height: 10 }} />\n          <FormField\n            label=\"Nota para ti (opcional)\" value={nota} onChangeText={setNota}\n            placeholder=\"Temporada alta, fiestas…\" maxLength={120}\n          />\n\n          <View style={[styles.linea, { borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700', flex: 1, paddingRight: espaciado.e12 }}>\n              Cerrar estas fechas\n            </Text>\n            <Switch value={cerrar} onValueChange={setCerrar} trackColor={{ true: alpha(colors.danger, 0.5) }} />\n          </View>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }}>\n            Cerrar = no se puede reservar. Las reservas que ya existan en esas noches **no** se cancelan.\n          </Text>\n\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e16, marginBottom: espaciado.e6 }}>\n            Solo algunos días de la semana (opcional)\n          </Text>\n          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n            {DIAS_SEMANA.map((d) => {\n              const on = semana.includes(d.dow);\n              return (\n                <Pressable\n                  key={d.dow}\n                  onPress={() => setSemana((prev) => (on ? prev.filter((x) => x !== d.dow) : [...prev, d.dow]))}\n                  style={[styles.chip, { backgroundColor: on ? alpha(colors.primary, 0.14) : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                >\n                  <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                    {on ? '✓ ' : ''}{d.label}\n                  </Text>\n                </Pressable>\n              );\n            })}\n          </View>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>\n            Sin marcar ninguno, se aplica a todos los días del rango.\n          </Text>\n\n          <View style={{ marginTop: espaciado.e18 }}>\n            <PrimaryButton\n              title={cerrar ? 'Cerrar esas fechas' : 'Guardar precios y fechas'}\n              onPress={() => void guardar('set')}\n              loading={guardando}\n            />\n          </View>\n          <View style={{ marginTop: espaciado.e10 }}>\n            <GhostButton\n              title=\"Quitar lo puesto en esas noches\"\n              onPress={() => {\n                Alert.alert(\n                  'Quitar excepciones',\n                  'Esas noches vuelven al precio y a las condiciones del tipo de habitación.',\n                  [{ text: 'Cancelar', style: 'cancel' }, { text: 'Quitar', onPress: () => void guardar('clear') }],\n                );\n              }}\n              disabled={guardando}\n            />\n          </View>\n\n          {/* ── Cómo queda ── */}\n          {dias.length ? (\n            <>\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginTop: espaciado.e24, marginBottom: espaciado.e8 }}>\n                Cómo queda el próximo mes y medio\n              </Text>\n              {dias.filter((d) => d.closed || Number(d.priceXaf) !== Number(d.basePriceXaf)).slice(0, 40).map((d) => (\n                <View key={d.date} style={[styles.linea, { borderColor: colors.border }]}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700', flex: 1 }}>\n                    {longDate(d.date)}\n                  </Text>\n                  <Text style={{ color: d.closed ? colors.danger : colors.secondary, fontSize: tipografia.body, fontWeight: '900' }}>\n                    {d.closed ? 'Cerrado' : xaf(d.priceXaf)}\n                  </Text>\n                </View>\n              ))}\n              {!dias.some((d) => d.closed || Number(d.priceXaf) !== Number(d.basePriceXaf)) ? (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                  Todas las noches están al precio normal ({xaf(base)}) y abiertas.\n                </Text>\n              ) : null}\n            </>\n          ) : null}\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e4,\n    paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  volver: { width: 40, height: 34, alignItems: 'center', justifyContent: 'center' },\n  aviso: { borderWidth: 1, borderRadius: radios.md, padding: espaciado.e11, marginBottom: espaciado.e14 },\n  rango: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginBottom: espaciado.e12,\n  },\n  mes: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e10 },\n  mesCabecera: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e4, marginBottom: espaciado.e6 },\n  fila: { flexDirection: 'row' },\n  dow: { flex: 1, textAlign: 'center', fontSize: tipografia.micro, fontWeight: '800', marginBottom: espaciado.e2 },\n  celda: { flex: 1, aspectRatio: 1, alignItems: 'center', justifyContent: 'center', borderRadius: 10, margin: 1 },\n  punto: { width: 4, height: 4, borderRadius: 2 },\n  chip: { borderWidth: 1.5, borderRadius: radios.full, paddingHorizontal: espaciado.e13, minHeight: 44, justifyContent: 'center' },\n  linea: {\n    flexDirection: 'row', alignItems: 'center',\n    borderTopWidth: StyleSheet.hairlineWidth, paddingVertical: espaciado.e9,\n  },\n});\n","/**\r\n * PanelGate — LA PUERTA DEL ÁREA DE GESTIÓN: pide la cerradura del dispositivo.\r\n *\r\n * ── POR QUÉ EXISTE (y por qué NO basta con esconder el botón) ─────────────────\r\n *\r\n * El dueño preguntó si tener el panel de los negocios en el perfil es un riesgo de seguridad.\r\n * La respuesta honesta es que **la ubicación en la interfaz no es la frontera de seguridad**:\r\n * esconder la fila no protege nada, porque las rutas se alcanzan igual desde dentro de la app\r\n * (`/lifebook-merchant`, `/lifebook-hotel-panel`…). Lo que protege de verdad son tres cosas:\r\n *\r\n *  1. **El token.** Sin sesión, `AuthGate` manda al onboarding y el servidor responde 401.\r\n *  2. **La autorización en el servidor, por acción.** El negocio lo resuelve el SERVIDOR desde\r\n *     la sesión (`/my/*`), no desde un identificador de la URL: no hay id que adivinar. Y las\r\n *     rutas que sí llevan el id de la tienda están detrás de `ShopOwnerGuard`, que responde\r\n *     **404** a quien no es el dueño (probado en el E2E: «otro usuario pidiendo el panel con el\r\n *     shopId de A → 404 SHOP_NOT_FOUND»). Por eso el identificador de cuenta que la app pasa al\r\n *     hook de negocios **no autoriza nada**: solo sirve para saber cuándo volver a preguntar.\r\n *  3. **El dispositivo.** Y aquí está el hueco de verdad: el panel muestra **dinero, reservas y\r\n *     teléfonos de clientes**, y cualquier persona con el móvil desbloqueado entra sin más.\r\n *\r\n * La app ya traía la pieza para el punto 3 —`core/biometric.ts` y `unlockBiometric()` en la\r\n * sesión— y **no la usaba nadie**: estaba construida y sin conectar. Esto la conecta donde\r\n * importa (el área de gestión), en vez de pedir la huella al abrir la app entera, que molesta\r\n * al que solo viene a mirar el muro.\r\n *\r\n * ── Decisiones que no son obvias ─────────────────────────────────────────────\r\n *\r\n * · **Un desbloqueo por sesión con caducidad (5 min), no uno por pantalla.** Si pidiera la\r\n *   huella en cada navegación, el comerciante acabaría buscando cómo desactivarlo — y una\r\n *   cerradura que se desactiva no protege nada.\r\n * · **Sin cerradura configurada, NO se bloquea.** Si el móvil no tiene huella ni PIN, se deja\r\n *   pasar y se dice una vez. Bloquear a quien no puede desbloquear es dejarle fuera de su\r\n *   propio negocio.\r\n * · **La puerta no decide permisos.** No mira si eres el dueño: eso lo decide el servidor en\r\n *   cada petición. Esto solo evita que un tercero con el móvil en la mano vea el negocio.\r\n */\r\nimport React, { useCallback, useEffect, useState } from 'react';\r\nimport { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';\r\nimport { Lock } from 'lucide-react-native';\r\nimport { alpha, espaciado, PrimaryButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { biometricAvailable, biometricVerify } from './biometric';\r\nimport { useSession } from '../state/session';\r\n\r\n/** Hasta cuándo está abierta el área de gestión (una vez desbloqueada). */\r\nlet abiertoHasta = 0;\r\n/** 5 minutos: suficiente para trabajar seguido, corto para un móvil prestado. */\r\nconst VALIDEZ_MS = 5 * 60 * 1000;\r\n\r\n/** Vuelve a cerrar la puerta (para un cierre de sesión explícito). */\r\nexport function cerrarPanelGate(): void {\r\n  abiertoHasta = 0;\r\n}\r\n\r\ntype Estado = 'comprobando' | 'abierto' | 'cerrado' | 'sin-cerradura';\r\n\r\nexport function PanelGate({ children }: { children: React.ReactNode }) {\r\n  const { colors } = useTheme();\r\n  const { hydrated, isUnlocked } = useSession();\r\n  const [estado, setEstado] = useState<Estado>('comprobando');\r\n  const [fallo, setFallo] = useState<string | null>(null);\r\n\r\n  useEffect(() => {\r\n    let vivo = true;\r\n    void (async () => {\r\n      if (!hydrated) return;\r\n      // Sin sesión no hay nada que proteger aquí: `AuthGate` ya se encarga.\r\n      if (!isUnlocked) { if (vivo) setEstado('abierto'); return; }\r\n      if (Date.now() < abiertoHasta) { if (vivo) setEstado('abierto'); return; }\r\n\r\n      const disp = await biometricAvailable();\r\n      if (!vivo) return;\r\n      if (!disp.available || !disp.enrolled) {\r\n        // No hay cerradura en el móvil: no se puede pedir lo imposible.\r\n        abiertoHasta = Date.now() + VALIDEZ_MS;\r\n        setEstado('sin-cerradura');\r\n        return;\r\n      }\r\n      setEstado('cerrado');\r\n    })();\r\n    return () => { vivo = false; };\r\n  }, [hydrated, isUnlocked]);\r\n\r\n  const desbloquear = useCallback(async () => {\r\n    setFallo(null);\r\n    const ok = await biometricVerify('Entrar en la gestión de tu negocio');\r\n    if (ok) {\r\n      abiertoHasta = Date.now() + VALIDEZ_MS;\r\n      setEstado('abierto');\r\n    } else {\r\n      setFallo('No se pudo comprobar tu identidad. Inténtalo otra vez.');\r\n    }\r\n  }, []);\r\n\r\n  if (estado === 'comprobando') {\r\n    return (\r\n      <View style={[styles.centro, { backgroundColor: colors.background }]}>\r\n        <ActivityIndicator color={colors.primary} />\r\n      </View>\r\n    );\r\n  }\r\n\r\n  if (estado === 'cerrado') {\r\n    return (\r\n      <View style={[styles.centro, { backgroundColor: colors.background }]}>\r\n        <View style={[styles.candado, { backgroundColor: alpha(colors.primary, 0.1) }]}>\r\n          <Lock size={26} color={colors.primary} />\r\n        </View>\r\n        <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', marginTop: espaciado.e14 }}>\r\n          Gestión de tu negocio\r\n        </Text>\r\n        <Text style={{\r\n          color: colors.textSecondary, fontSize: tipografia.body, lineHeight: 19,\r\n          textAlign: 'center', marginTop: espaciado.e7, paddingHorizontal: 34,\r\n        }}>\r\n          Aquí están tu dinero, tus reservas y los datos de tus clientes. Confirma que eres tú\r\n          para entrar.\r\n        </Text>\r\n        {fallo ? (\r\n          <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e10 }}>\r\n            {fallo}\r\n          </Text>\r\n        ) : null}\r\n        <View style={{ marginTop: espaciado.e18, minWidth: 230 }}>\r\n          <PrimaryButton title=\"Desbloquear\" onPress={() => void desbloquear()} />\r\n        </View>\r\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, textAlign: 'center', paddingHorizontal: 40 }}>\r\n          Se pide una vez cada 5 minutos, no en cada pantalla.\r\n        </Text>\r\n      </View>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <>\r\n      {estado === 'sin-cerradura' ? (\r\n        // Se dice UNA vez por sesión y no se repite: es un aviso, no un error.\r\n        <View style={{\r\n          backgroundColor: alpha(colors.secondary, 0.1),\r\n          borderBottomWidth: StyleSheet.hairlineWidth,\r\n          borderBottomColor: alpha(colors.secondary, 0.3),\r\n          paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7,\r\n        }}>\r\n          <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700' }}>\r\n            Este móvil no tiene huella ni PIN configurados: la gestión entra sin cerradura.\r\n          </Text>\r\n        </View>\r\n      ) : null}\r\n      {children}\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 },\r\n  candado: { width: 60, height: 60, borderRadius: 30, alignItems: 'center', justifyContent: 'center' },\r\n});\r\n","/**\n * biometric — wrapper sobre expo-local-authentication.\n * Biometría LOCAL (FaceID/huella): NO enrola nada en el servidor.\n * Se usa como cerradura del refresh_token que ya está en SecureStore:\n * el usuario demuestra identidad del dispositivo y, si pasa, la app\n * canjea el refresh por un access token nuevo (ver SessionProvider).\n */\n\nimport * as LocalAuthentication from 'expo-local-authentication';\n\nexport interface BiometricAvailability {\n  available: boolean;\n  enrolled: boolean;\n}\n\nexport async function biometricAvailable(): Promise<BiometricAvailability> {\n  const [available, enrolled] = await Promise.all([\n    LocalAuthentication.hasHardwareAsync(),\n    LocalAuthentication.isEnrolledAsync(),\n  ]);\n  return { available: !!available, enrolled: !!enrolled };\n}\n\n/** Pide biometría. Devuelve true si el usuario se autenticó. */\nexport async function biometricVerify(reason: string): Promise<boolean> {\n  try {\n    const res = await LocalAuthentication.authenticateAsync({\n      promptMessage: reason,\n      fallbackLabel: 'Usar PIN',\n      cancelLabel: 'Cancelar',\n    });\n    return !!res.success;\n  } catch {\n    return false;\n  }\n}\n","import { UnavailabilityError } from 'expo-modules-core';\nimport invariant from 'invariant';\nimport ExpoLocalAuthentication from './ExpoLocalAuthentication';\nimport { AuthenticationType, SecurityLevel, } from './LocalAuthentication.types';\nexport { AuthenticationType, SecurityLevel, };\n// @needsAudit\n/**\n * Determine whether a face or fingerprint scanner is available on the device.\n * @return Returns a promise which fulfils with a `boolean` value indicating whether a face or\n * fingerprint scanner is available on this device.\n */\nexport async function hasHardwareAsync() {\n    if (!ExpoLocalAuthentication.hasHardwareAsync) {\n        throw new UnavailabilityError('expo-local-authentication', 'hasHardwareAsync');\n    }\n    return await ExpoLocalAuthentication.hasHardwareAsync();\n}\n// @needsAudit\n/**\n * Determine what kinds of authentications are available on the device.\n * @return Returns a promise which fulfils to an array containing [`AuthenticationType`s](#authenticationtype).\n *\n * Devices can support multiple authentication methods - i.e. `[1,2]` means the device supports both\n * fingerprint and facial recognition. If none are supported, this method returns an empty array.\n */\nexport async function supportedAuthenticationTypesAsync() {\n    if (!ExpoLocalAuthentication.supportedAuthenticationTypesAsync) {\n        throw new UnavailabilityError('expo-local-authentication', 'supportedAuthenticationTypesAsync');\n    }\n    return await ExpoLocalAuthentication.supportedAuthenticationTypesAsync();\n}\n// @needsAudit\n/**\n * Determine whether the device has saved fingerprints or facial data to use for authentication.\n * @return Returns a promise which fulfils to `boolean` value indicating whether the device has\n * saved fingerprints or facial data for authentication.\n */\nexport async function isEnrolledAsync() {\n    if (!ExpoLocalAuthentication.isEnrolledAsync) {\n        throw new UnavailabilityError('expo-local-authentication', 'isEnrolledAsync');\n    }\n    return await ExpoLocalAuthentication.isEnrolledAsync();\n}\n// @needsAudit\n/**\n * Determine what kind of authentication is enrolled on the device.\n * @return Returns a promise which fulfils with [`SecurityLevel`](#securitylevel).\n * > **Note:** On Android devices prior to M, `SECRET` can be returned if only the SIM lock has been\n * enrolled, which is not the method that [`authenticateAsync`](#localauthenticationauthenticateasyncoptions)\n * prompts.\n */\nexport async function getEnrolledLevelAsync() {\n    if (!ExpoLocalAuthentication.getEnrolledLevelAsync) {\n        throw new UnavailabilityError('expo-local-authentication', 'getEnrolledLevelAsync');\n    }\n    return await ExpoLocalAuthentication.getEnrolledLevelAsync();\n}\n// @needsAudit\n/**\n * Attempts to authenticate via Fingerprint/TouchID (or FaceID if available on the device).\n * > **Note:** Apple requires apps which use FaceID to provide a description of why they use this API.\n * If you try to use FaceID on an iPhone with FaceID without providing `infoPlist.NSFaceIDUsageDescription`\n * in `app.json`, the module will authenticate using device passcode. For more information about\n * usage descriptions on iOS, see [permissions guide](/guides/permissions/#ios).\n * @param options\n * @return Returns a promise which fulfils with [`LocalAuthenticationResult`](#localauthenticationresult).\n */\nexport async function authenticateAsync(options = {}) {\n    if (!ExpoLocalAuthentication.authenticateAsync) {\n        throw new UnavailabilityError('expo-local-authentication', 'authenticateAsync');\n    }\n    if (options.hasOwnProperty('promptMessage')) {\n        invariant(typeof options.promptMessage === 'string' && options.promptMessage.length, 'LocalAuthentication.authenticateAsync : `options.promptMessage` must be a non-empty string.');\n    }\n    const promptMessage = options.promptMessage || 'Authenticate';\n    const cancelLabel = options.cancelLabel || 'Cancel';\n    const result = await ExpoLocalAuthentication.authenticateAsync({\n        ...options,\n        promptMessage,\n        cancelLabel,\n    });\n    return result;\n}\n// @needsAudit\n/**\n * Cancels authentication flow.\n * @platform android\n */\nexport async function cancelAuthenticate() {\n    if (!ExpoLocalAuthentication.cancelAuthenticate) {\n        throw new UnavailabilityError('expo-local-authentication', 'cancelAuthenticate');\n    }\n    await ExpoLocalAuthentication.cancelAuthenticate();\n}\n//# sourceMappingURL=LocalAuthentication.js.map","import { requireNativeModule } from 'expo-modules-core';\nexport default requireNativeModule('ExpoLocalAuthentication');\n//# sourceMappingURL=ExpoLocalAuthentication.js.map","import { Platform } from 'expo-modules-core';\n// @needsAudit\nexport var AuthenticationType;\n(function (AuthenticationType) {\n    /**\n     * Indicates fingerprint support.\n     */\n    AuthenticationType[AuthenticationType[\"FINGERPRINT\"] = 1] = \"FINGERPRINT\";\n    /**\n     * Indicates facial recognition support.\n     */\n    AuthenticationType[AuthenticationType[\"FACIAL_RECOGNITION\"] = 2] = \"FACIAL_RECOGNITION\";\n    /**\n     * Indicates iris recognition support.\n     * @platform android\n     */\n    AuthenticationType[AuthenticationType[\"IRIS\"] = 3] = \"IRIS\";\n})(AuthenticationType || (AuthenticationType = {}));\n// @needsAudit\nexport var SecurityLevel;\n(function (SecurityLevel) {\n    /**\n     * Indicates no enrolled authentication.\n     */\n    SecurityLevel[SecurityLevel[\"NONE\"] = 0] = \"NONE\";\n    /**\n     * Indicates non-biometric authentication (e.g. PIN, Pattern).\n     */\n    SecurityLevel[SecurityLevel[\"SECRET\"] = 1] = \"SECRET\";\n    /**\n     * Indicates biometric authentication.\n     * @deprecated please use `BIOMETRIC_STRONG` or `BIOMETRIC_WEAK` instead.\n     * @hidden\n     */\n    SecurityLevel[SecurityLevel[\"BIOMETRIC\"] = Platform.OS === 'android'\n        ? SecurityLevel.BIOMETRIC_WEAK\n        : SecurityLevel.BIOMETRIC_STRONG] = \"BIOMETRIC\";\n    /**\n     * Indicates weak biometric authentication. For example, a 2D image-based face unlock.\n     * > There are currently no weak biometric authentication options on iOS.\n     */\n    SecurityLevel[SecurityLevel[\"BIOMETRIC_WEAK\"] = 2] = \"BIOMETRIC_WEAK\";\n    /**\n     * Indicates strong biometric authentication. For example, a fingerprint scan or 3D face unlock.\n     */\n    SecurityLevel[SecurityLevel[\"BIOMETRIC_STRONG\"] = 3] = \"BIOMETRIC_STRONG\";\n})(SecurityLevel || (SecurityLevel = {}));\nObject.defineProperty(SecurityLevel, 'BIOMETRIC', {\n    get() {\n        const additionalMessage = Platform.OS === 'android'\n            ? '. `SecurityLevel.BIOMETRIC` is currently an alias for `SecurityLevel.BIOMETRIC_WEAK` on Android, which might lead to unexpected behaviour.'\n            : '';\n        console.warn('`SecurityLevel.BIOMETRIC` has been deprecated. Use `SecurityLevel.BIOMETRIC_WEAK` or `SecurityLevel.BIOMETRIC_STRONG` instead' +\n            additionalMessage);\n        return Platform.OS === 'android'\n            ? SecurityLevel.BIOMETRIC_WEAK\n            : SecurityLevel.BIOMETRIC_STRONG;\n    },\n});\n//# sourceMappingURL=LocalAuthentication.types.js.map","/**\n * hotel — cliente API del MÓDULO HOTELERO (Parte 42 del servidor).\n *\n * Rutas (bajo `/wallet/api/v1/lifebook/commerce/hotel`):\n *   PÚBLICAS   search · hotel · rooms · calendar · room\n *   HUÉSPED    reserve (Idempotency-Key obligatoria) · mine · reservation ·\n *              proof · action · confirmDeposit\n *   HOTELERO   myHotel · saveHotel · myRooms · createRoom · updateRoom ·\n *              saveCalendar · dayBook\n *\n * Reglas que el servidor impone y que este cliente respeta:\n *   · **El dinero no viaja**: el total, la señal y el restante los calcula el\n *     servidor. Aquí solo se envían fechas, habitaciones, huéspedes y el % de señal.\n *   · **Idempotency-Key obligatoria al reservar**: un doble toque no crea dos\n *     reservas. La clave es ESTABLE por intento (`reserveKey`), no nueva en cada\n *     pulsación — si se genera nueva en cada toque, la idempotencia no protege.\n */\nimport { http, httpRequest } from './httpClient';\n\n// ───────────────────────────── tipos ────────────────────────────────────────\nexport interface HotelSummary {\n  id: string;\n  name: string;\n  city: string | null;\n  barrio: string | null;\n  region: string | null;\n  logoUrl: string | null;\n  coverUrl: string | null;\n  rating: number;\n  ratingCount: number;\n  addressReference: string | null;\n  lat: number | null;\n  lng: number | null;\n  verificationLevel?: string;\n  isVerified?: boolean;\n}\n\nexport interface HotelProfile extends HotelSummary {\n  shopId: string;\n  propertyKind: string | null;\n  stars: number | null;\n  checkinFrom: string;\n  checkinUntil: string;\n  checkoutUntil: string;\n  receptionOpen24h: boolean;\n  amenities: string[];\n  houseRules: string | null;\n  cancellationPolicy: string | null;\n  /** Cómo se entra y dónde está la recepción. Lo escribe el hotelero y lo lee el huésped al llegar\n   *  (es lo que sale junto al botón «Cómo llegar» y al taxi desde el aeropuerto). */\n  arrivalNote: string | null;\n  taxesIncluded: boolean;\n  description: string | null;\n  isActive?: boolean;\n  isHotel?: boolean;\n  paymentMethods?: (string | { method: string; status: string; note?: string | null })[];\n  roomCount?: number;\n}\n\nexport interface HotelFx {\n  /** País del que reserva (el que se mandó en `?country=`), o `null` si no se reconoce. */\n  country: string | null;\n  countryLabel: string | null;\n  currency: string;\n  currencyLabel: string;\n  symbol: string;\n  /** XAF que vale 1 unidad de esa moneda (ej.: 655,957 para el euro, paridad fija del franco CFA). */\n  xafPerUnit: number;\n  decimals: number;\n  updatedAt: string;\n  note: string | null;\n  /** La moneda del huésped ES la del cobro (XAF): entonces no hay «≈» que enseñar. */\n  esMonedaDelCobro: boolean;\n}\n\n/** Dónde está el hotel y cómo se entra. Lo que el huésped necesita al llegar. */\nexport interface HotelArrival {\n  note: string | null;\n  lat: number | null;\n  lng: number | null;\n  addressReference: string | null;\n  city: string | null;\n}\n\n/** El aeropuerto de la ciudad, con los precios de taxi de referencia de la zona. */\nexport interface HotelAirport {\n  label: string;\n  city: string | null;\n  lat: number;\n  lng: number;\n  priceFromXaf: number | null;\n  priceToXaf: number | null;\n}\n\nexport interface HotelRoom {\n  id: string;\n  shopId: string;\n  productId: string | null;\n  name: string;\n  description: string | null;\n  capacity: number;\n  beds: { kind: string; count: number }[];\n  sizeM2: number | null;\n  totalUnits: number;\n  basePriceXaf: number;\n  weekendPriceXaf: number | null;\n  cleaningFeeXaf: number;\n  taxesXaf: number;\n  minNights: number;\n  maxNights: number;\n  depositPercent: number;\n  holdMinutes: number;\n  confirmationHours: number;\n  cancellationHours: number;\n  images: { url: string }[];\n  amenities: string[];\n  isActive: boolean;\n  productStatus?: string;\n  /** El precio de esta habitación en la moneda del huésped (`?country=ES` → euros). Lo calcula el\n   *  SERVIDOR: la app no convierte nada por su cuenta, porque dos reglas de conversión acaban\n   *  diciendo cosas distintas. `null`/`undefined` = no se sabe el país o no hay tipo de cambio para\n   *  él, y entonces NO se pinta nada (nunca un 0 ni una cifra inventada). */\n  pricePerNightLocal?: number | null;\n  // Solo en la búsqueda con fechas:\n  freeUnits?: number | null;\n  avgPricePerNightXaf?: number | null;\n  subtotalXaf?: number;\n  cleaningFeeTotalXaf?: number;\n  totalXaf?: number;\n  depositPercentQuoted?: number;\n  depositXaf?: number;\n  remainingXaf?: number;\n  nights?: number;\n  /** Con fechas: el hotel tiene cerrada alguna de esas noches. */\n  closedForDates?: boolean;\n  /** Con fechas: la estancia mínima de esas fechas es mayor que las noches pedidas. */\n  minNightsForDates?: number;\n}\n\nexport interface HotelSearchResult {\n  hotels: {\n    hotel: HotelSummary;\n    fromPricePerNightXaf: number;\n    /** Con fechas: ese hotel no tiene hueco en TODO el rango pedido. */\n    soldOut?: boolean;\n    rooms: HotelRoom[];\n  }[];\n  city: string | null;\n  checkIn: string | null;\n  checkOut: string | null;\n  nights: number;\n  guests: number;\n  units: number;\n  /**\n   * Paginación.\n   *\n   * 🔧 Lo que se encontró al comprobar la respuesta EN CRUDO contra el servidor (y que corrige una\n   * conclusión previa equivocada): el servidor devuelve **las cuatro cosas** —`page`, `pageSize`,\n   * `hasMore` y `nextCursor`— **salvo cuando no hay ningún hotel candidato**, que hace un\n   * `return` temprano y **se deja fuera `page`, `pageSize` y `hasMore`**:\n   *\n   *   /hotels?city=Malabo            → {…, page:1, pageSize:12, hasMore:false, nextCursor:null}\n   *   /hotels?city=Malabo&page=2&…   → {hotels:[], city, checkIn, checkOut, nights, guests, units, nextCursor}\n   *                                                                          ↑ sin paginación\n   *\n   * Por eso van como OPCIONALES: leerlos como si siempre estuvieran haría que `hasMore` fuese\n   * `undefined` (falso, y el botón se esconde — funciona de casualidad, no por contrato).\n   * Quien los use debe tratar «ausente» como «no hay más».\n   */\n  page?: number;\n  pageSize?: number;\n  /** ¿Queda otra página? Ausente = no hay más. */\n  hasMore?: boolean;\n  nextCursor?: string | null;\n}\n\nexport interface CalendarDay {\n  date: string;\n  priceXaf: number;\n  basePriceXaf: number;\n  weekend: boolean;\n  closed: boolean;\n  note: string | null;\n  minNights: number;\n  totalUnits: number;\n  usedUnits: number;\n  freeUnits: number;\n  isToday: boolean;\n  available: boolean;\n}\n\nexport interface RoomCalendar {\n  roomTypeId: string;\n  name: string;\n  totalUnits: number;\n  from: string;\n  to: string;\n  units: number;\n  days: CalendarDay[];\n  summary: { free: number; closed: number; full: number };\n}\n\nexport type ReservationStatus =\n  | 'hold' | 'pending' | 'confirmed' | 'checked_in' | 'checked_out' | 'cancelled' | 'no_show';\nexport type PaymentStatus = 'pending' | 'proof_submitted' | 'deposit_paid' | 'paid' | 'refunded' | 'failed';\n\nexport interface Reservation {\n  id: string;\n  code: string;\n  status: ReservationStatus;\n  /** ¿Sigue ocupando inventario? (una retención vencida ya no). */\n  viva: boolean;\n  /** Identificador del huésped: solo lo recibe el propio huésped (o la administración). */\n  guestId?: string | null;\n  /** ¿Puede cancelarse ahora? Lo decide el servidor (estado + ventana de cancelación). */\n  canCancel?: boolean;\n  cancellationHours?: number;\n  role: 'guest' | 'hotel' | 'admin';\n  checkIn: string;\n  checkOut: string;\n  nights: number;\n  units: number;\n  guests: number;\n  roomName: string;\n  roomTypeId: string | null;\n  pricePerNightXaf: number;\n  subtotalXaf: number;\n  cleaningFeeXaf: number;\n  taxesXaf: number;\n  totalXaf: number;\n  depositPercent: number;\n  depositXaf: number;\n  remainingXaf: number;\n  paymentMethod: string;\n  paymentStatus: PaymentStatus;\n  holdExpiresAt: string | null;\n  freeCancellationUntil: string | null;\n  hotel: HotelSummary | null;\n  guest: { id: string; name: string; phone: string | null; email: string | null };\n  note: string | null;\n  cancelReason: string | null;\n  createdAt: string;\n  updatedAt: string;\n  depositPaidAt: string | null;\n  /** Quién confirmó el cobro de la señal (dueño del hotel o admin). */\n  depositConfirmedBy?: string | null;\n  /** Referencia con la que se confirmó (nº de transferencia, «visto en cuenta»…). */\n  depositProof?: string | null;\n  paidAt: string | null;\n  checkedInAt: string | null;\n  checkedOutAt: string | null;\n  cancelledAt: string | null;\n  checkinFrom?: string | null;\n  checkoutUntil?: string | null;\n  /** Precio noche a noche (solo en la respuesta de la creación). */\n  nightlyPrices?: { date: string; priceXaf: number }[];\n}\n\nexport interface DayBook {\n  date: string;\n  staying: Reservation[];\n  arrivals: Reservation[];\n  departures: Reservation[];\n  occupancy: { roomTypeId: string; name: string; totalUnits: number; occupied: number; free: number }[];\n}\n\n/** Resumen del día del panel del hotelero (Parte 42-a). */\nexport interface HotelDashboard {\n  shop: { id: string; name: string; isActive: boolean };\n  date: string;\n  arrivalsToday: number;\n  departuresToday: number;\n  insideNow: number;\n  upcoming: number;\n  /** Señal pagada y sin confirmar por el hotel. */\n  pendingConfirm: number;\n  /** Retenidas SIN pagar: se liberan solas, hay que vigilarlas. */\n  unpaidHolds: number;\n  /** Reservas con señal pendiente de cobro. */\n  depositDue: number;\n  occupancy: { roomTypeId: string; name: string; totalUnits: number; occupied: number; free: number }[];\n}\n\nexport interface CreateReservationInput {\n  roomTypeId: string;\n  checkIn: string;\n  checkOut: string;\n  units?: number;\n  guests?: number;\n  guestName: string;\n  guestPhone: string;\n  guestEmail?: string;\n  paymentMethod: string;\n  /** 0 = pagar todo al llegar. El servidor nunca sube del % del hotel. */\n  depositPercent?: number;\n  note?: string;\n}\n\n// ─────────────────────── clave de idempotencia estable ──────────────────────\n/**\n * Clave **estable por intento de reserva**: si el usuario toca dos veces\n * «Confirmar», las dos peticiones llevan la MISMA clave y el servidor devuelve la\n * misma reserva. Se renueva solo cuando cambia lo que se reserva (fechas,\n * habitación, huéspedes), que es cuando de verdad es otra reserva.\n */\nconst claveActual = { firma: '', key: '' };\nexport function reserveKey(firma: string): string {\n  if (claveActual.firma !== firma || !claveActual.key) {\n    claveActual.firma = firma;\n    claveActual.key = `hotel-${firma}-${Math.random().toString(36).slice(2, 10)}-${Date.now().toString(36)}`;\n  }\n  return claveActual.key;\n}\n/** Fuerza una clave nueva (después de reservar con éxito, o al cancelar el flujo). */\nexport function resetReserveKey(): void {\n  claveActual.firma = '';\n  claveActual.key = '';\n}\n\n// ───────────────────────────── API ──────────────────────────────────────────\nconst BASE = '/lifebook/commerce/hotel';\n\nexport const hotelApi = {\n  // ── público ──\n  search(q: {\n    city?: string; checkIn?: string; checkOut?: string; guests?: number;\n    units?: number; minPrice?: number; maxPrice?: number; limit?: number;\n    /** Página (1-based). Se añadió para poder paginar: antes no se mandaba y solo había una. */\n    page?: number;\n  }) {\n    const p = new URLSearchParams();\n    if (q.city) p.set('city', q.city);\n    if (q.checkIn) p.set('checkIn', q.checkIn);\n    if (q.checkOut) p.set('checkOut', q.checkOut);\n    if (q.guests) p.set('guests', String(q.guests));\n    if (q.units) p.set('units', String(q.units));\n    if (q.minPrice !== undefined) p.set('minPrice', String(q.minPrice));\n    if (q.maxPrice !== undefined) p.set('maxPrice', String(q.maxPrice));\n    if (q.page && q.page > 1) p.set('page', String(q.page));\n    p.set('limit', String(q.limit ?? 20));\n    return http.get<HotelSearchResult>(`${BASE}/hotels?${p.toString()}`, false);\n  },\n\n  /**\n   * Ficha del hotel. `country` (ISO-2, ej. 'ES') hace que el servidor añada `fx` y el precio de cada\n   * habitación en la moneda de ese país (`pricePerNightLocal`). El precio REAL sigue siendo el XAF: es\n   * lo que se cobra, en efectivo, al llegar.\n   */\n  hotel(shopId: string, country?: string | null) {\n    const qs = country ? `?country=${encodeURIComponent(country)}` : '';\n    return http.get<{\n      hotel: HotelProfile; rooms: HotelRoom[];\n      fx: HotelFx | null; arrival: HotelArrival | null; airport: HotelAirport | null;\n    }>(`${BASE}/hotels/${shopId}${qs}`, false);\n  },\n\n  /**\n   * Tipos de cambio de referencia (público) y la moneda que toca para un país.\n   * ⚠️ Va declarada antes que `hotels/:id` en el servidor: si no, «fx» entraría por el `:id`.\n   */\n  fx(country?: string | null) {\n    const qs = country ? `?country=${encodeURIComponent(country)}` : '';\n    return http.get<{\n      monedaDelCobro: string;\n      pais: HotelFx | null;\n      monedas: Array<{ currency: string; label: string; symbol: string; xafPerUnit: number; decimals: number; updatedAt: string; note: string | null }>;\n      /** Los países que se pueden elegir, con su moneda. Se listan PAÍSES porque la conversión es por\n       *  país: si la app dedujera el país a partir de la moneda, estaría duplicando la tabla del\n       *  servidor y las dos acabarían diciendo cosas distintas. */\n      paises: Array<{ code: string; label: string; currency: string; symbol: string }>;\n      aviso: string;\n    }>(`${BASE}/hotels/fx${qs}`, false);\n  },\n\n  roomsOf(shopId: string) {\n    return http.get<{ hotel: { id: string; name: string }; rooms: HotelRoom[] }>(`${BASE}/hotels/${shopId}/rooms`, false);\n  },\n\n  room(roomTypeId: string) {\n    return http.get<{ room: HotelRoom & { hotel: HotelSummary; paymentMethods: string[] } }>(\n      `${BASE}/rooms/${roomTypeId}`, false,\n    );\n  },\n\n  /** Disponibilidad + precio por noche (una fila por noche). */\n  calendar(roomTypeId: string, from: string, to: string, units = 1) {\n    return http.get<RoomCalendar>(\n      `${BASE}/rooms/${roomTypeId}/calendar?from=${from}&to=${to}&units=${units}`, false,\n    );\n  },\n\n  // ── huésped ──\n  /**\n   * Reservar. `Idempotency-Key` OBLIGATORIA (el servidor responde 400 sin ella):\n   * aquí se pasa la clave estable del intento.\n   */\n  reserve(input: CreateReservationInput, idempotencyKey: string) {\n    return httpRequest<{ reservation: Reservation; nightlyPrices?: { date: string; priceXaf: number }[] }>(\n      `${BASE}/reservations`,\n      { method: 'POST', body: input, headers: { 'Idempotency-Key': idempotencyKey } },\n    );\n  },\n\n  mine(side: 'guest' | 'hotel' = 'guest') {\n    return http.get<{ side: string; reservations: Reservation[] }>(`${BASE}/reservations/mine?side=${side}`);\n  },\n\n  reservation(id: string) {\n    return http.get<{ reservation: Reservation }>(`${BASE}/reservations/${id}`);\n  },\n\n  /** El huésped envía la referencia de la transferencia. */\n  proof(id: string, proof: string) {\n    return http.post<{ reservation: Reservation }>(`${BASE}/reservations/${id}/proof`, { proof });\n  },\n\n  // ── panel del hotelero (Parte 42-a) ──\n  /** Resumen del día en hora de Malabo, con retenciones y ocupación por tipo. */\n  dashboard() {\n    return http.get<HotelDashboard>(`${BASE}/my/hotel/dashboard`);\n  },\n\n  /** Reservas del hotel, lo urgente primero (retenidas → por confirmar → por fecha). */\n  shopReservations(q: { status?: string; from?: string; to?: string; limit?: number } = {}) {\n    const p = new URLSearchParams();\n    if (q.status) p.set('status', q.status);\n    if (q.from) p.set('from', q.from);\n    if (q.to) p.set('to', q.to);\n    p.set('limit', String(q.limit ?? 60));\n    return http.get<{ shop: { id: string; name: string }; count: number; reservations: Reservation[] }>(\n      `${BASE}/my/hotel/reservations?${p.toString()}`,\n    );\n  },\n\n  /** Detalle con el teléfono del huésped (para recibirlo). */\n  shopReservation(id: string) {\n    return httpRequest<{ reservation: Reservation & { guestPhone: string | null; guestEmail: string | null } }>(\n      `${BASE}/my/hotel/reservations/${id}`,\n    );\n  },\n\n  /**\n   * Cambiar el estado de una reserva con `{ status, reason }` (la ruta del dueño) o\n   * `{ action, reason }` (la que ya estaba desplegada): las dos van al mismo sitio.\n   */\n  setReservationStatus(id: string, status: string, reason?: string) {\n    return httpRequest<{ reservation: Reservation }>(`${BASE}/my/hotel/reservations/${id}/status`, {\n      method: 'PATCH',\n      body: { status, ...(reason ? { reason } : {}) },\n    });\n  },\n\n  /** Cancelar (huésped u hotel) — el motivo es obligatorio en el servidor. */\n  cancel(id: string, reason: string) {\n    return httpRequest<{ reservation: Reservation }>(`${BASE}/reservations/${id}/action`, {\n      method: 'PATCH', body: { action: 'cancel', reason },\n    });\n  },\n\n  /** El hotel confirma el cobro de la señal (o la administración). */\n  confirmDeposit(id: string, proof?: string) {\n    return http.post<{ reservation: Reservation }>(`${BASE}/reservations/${id}/confirm-deposit`, { proof });\n  },\n\n  // ── panel del hotelero ──\n  myHotel() {\n    return http.get<{ hotel: HotelProfile | null; rooms: HotelRoom[] }>(`${BASE}/my/hotel`);\n  },\n\n  saveHotel(dto: Record<string, unknown>) {\n    return http.put<{ hotel: HotelProfile }>(`${BASE}/my/hotel`, dto);\n  },\n\n  myRooms() {\n    return http.get<{ rooms: HotelRoom[] }>(`${BASE}/my/room-types`);\n  },\n\n  createRoom(dto: Record<string, unknown>) {\n    return http.post<{ room: HotelRoom }>(`${BASE}/my/room-types`, dto);\n  },\n\n  updateRoom(id: string, dto: Record<string, unknown>) {\n    return http.put<{ room: HotelRoom }>(`${BASE}/my/room-types/${id}`, dto);\n  },\n\n  /** Calendario del hotelero: cerrar fechas, precio de temporada, mínimo de noches. */\n  saveCalendar(id: string, dto: {\n    action?: 'set' | 'clear'; from: string; to: string;\n    priceXaf?: number | null; minNights?: number | null; isClosed?: boolean;\n    weekdays?: number[]; note?: string;\n  }) {\n    return http.put<{ saved?: number; cleared?: number; warning?: string | null }>(\n      `${BASE}/my/room-types/${id}/calendar`, dto,\n    );\n  },\n\n  dayBook(shopId: string, date?: string) {\n    return http.get<DayBook>(`${BASE}/my/day-book?shopId=${shopId}${date ? `&date=${date}` : ''}`);\n  },\n};\n\n/** Estados de reserva en lenguaje humano (los usa la app y el panel). */\nexport const RESERVA_ETIQUETA: Record<ReservationStatus, string> = {\n  hold: 'Sin pagar (retenida)',\n  pending: 'Señal pagada · por confirmar',\n  confirmed: 'Confirmada',\n  checked_in: 'Dentro',\n  checked_out: 'Salida hecha',\n  cancelled: 'Cancelada',\n  no_show: 'No se presentó',\n};\n\nexport const PAGO_ETIQUETA: Record<PaymentStatus, string> = {\n  pending: 'Sin cobrar',\n  proof_submitted: 'Comprobante enviado',\n  deposit_paid: 'Señal cobrada',\n  paid: 'Pagado',\n  refunded: 'Devuelto',\n  failed: 'Falló',\n};\n\nexport const METODO_ETIQUETA: Record<string, string> = {\n  transfer: 'Transferencia',\n  deposit: 'Señal',\n  in_store: 'En recepción',\n  billing: 'Facturación',\n  cash_on_delivery: 'Contra entrega',\n  likebook_wallet: 'Monedero',\n};\n","/**\n * lifebook-hotel-detalle — FICHA de un alojamiento + sus habitaciones y calendario.\n *\n * Enseña lo que decide la compra, sin rodeos: fotos, normas de llegada, servicios,\n * y por cada tipo de habitación **el calendario con el precio de cada noche**, la\n * disponibilidad real, la estancia mínima y **cuánto se paga ahora (señal) y cuánto\n * al llegar**. Elegir fechas aquí lleva directo a reservar con esos días puestos.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, altura, brand, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Car, Navigation } from 'lucide-react-native';\nimport { CalendarPicker, type CalendarDay } from '../components/CalendarPicker';\nimport { PhotoGallery } from '../components/PhotoGallery';\nimport { hotelApi, type HotelProfile, type HotelRoom, type HotelFx, type HotelArrival, type HotelAirport } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { absUrl } from '../api/config';\nimport { nightsBetween, shortDate, todayIso, xaf } from '../utils/datetime';\nimport { abrirMapa } from '../utils/maps';\nimport { formatearMoneda, getPaisParaPrecios, setPaisElegido } from '../utils/region';\n\nconst MAX_NOCHES = 92;\n/** Acento del marketplace (naranja), como en el resto del flujo de servicios. */\nconst ACCENT = brand.primary; // A1: la acción avanza en azul\n\n/** Etiquetas legibles de los servicios (las claves las define el servidor). */\nconst SERVICIOS: Record<string, string> = {\n  wifi: 'Wi-Fi', desayuno: 'Desayuno', aire: 'Aire acondicionado', piscina: 'Piscina',\n  parking: 'Aparcamiento', restaurante: 'Restaurante', bar: 'Bar', gimnasio: 'Gimnasio',\n  recepcion_24h: 'Recepción 24 h', agua_caliente: 'Agua caliente', generador: 'Generador',\n  lavanderia: 'Lavandería', tv: 'TV', terraza: 'Terraza', ascensor: 'Ascensor',\n  admite_mascotas: 'Admite mascotas', adaptado: 'Adaptado', cocina: 'Cocina',\n  nevera: 'Nevera', caja_fuerte: 'Caja fuerte', seguridad: 'Seguridad',\n};\n\nconst TIPOS: Record<string, string> = {\n  hotel: 'Hotel', hostal: 'Hostal', guest_house: 'Casa de huéspedes',\n  apartahotel: 'Apartahotel', resort: 'Resort', motel: 'Motel',\n};\n\nexport default function HotelDetalleScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const p = useLocalSearchParams<{\n    id: string; checkIn?: string; checkOut?: string; guests?: string; units?: string;\n  }>();\n  const shopId = String(p.id ?? '');\n\n  const [hotel, setHotel] = useState<HotelProfile | null>(null);\n  const [rooms, setRooms] = useState<HotelRoom[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  // ── LA MONEDA DEL HUÉSPED ────────────────────────────────────────────────────\n  // El precio real es en XAF y el cobro es en efectivo, pero quien reserva desde fuera necesita ver\n  // cuánto es en su moneda. `pais` sale de la configuración regional del móvil (o de lo que elija el\n  // huésped a mano) y el SERVIDOR hace la conversión: aquí no se calcula nada.\n  const [pais, setPais] = useState<string | null>(null);\n  const [fx, setFx] = useState<HotelFx | null>(null);\n  const [paises, setPaises] = useState<Array<{ code: string; label: string; currency: string; symbol: string }>>([]);\n  const [elegirMoneda, setElegirMoneda] = useState(false);\n  const [arrival, setArrival] = useState<HotelArrival | null>(null);\n  const [airport, setAirport] = useState<HotelAirport | null>(null);\n\n  const [huespedes] = useState(Number(p.guests ?? 2));\n  const [habitaciones] = useState(Number(p.units ?? 1));\n  const [checkIn, setCheckIn] = useState<string | null>(p.checkIn ?? null);\n  const [checkOut, setCheckOut] = useState<string | null>(p.checkOut ?? null);\n\n  // Habitación con el calendario abierto (una cada vez: no se pintan N calendarios).\n  const [abierta, setAbierta] = useState<string | null>(null);\n  const [dias, setDias] = useState<CalendarDay[]>([]);\n  const [cargandoCal, setCargandoCal] = useState(false);\n\n  const cargar = useCallback(async () => {\n    setCargando(true);\n    setError(null);\n    try {\n      const out = await hotelApi.hotel(shopId, pais);\n      setHotel(out.hotel);\n      setRooms(out.rooms ?? []);\n      setFx(out.fx ?? null);\n      setArrival(out.arrival ?? null);\n      setAirport(out.airport ?? null);\n      if (!abierta && out.rooms?.length) setAbierta(out.rooms[0].id);\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar el alojamiento.');\n    } finally {\n      setCargando(false);\n    }\n  }, [shopId, abierta, pais]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  // El país, una sola vez al abrir: lo elegido a mano manda sobre lo que diga el sistema.\n  useEffect(() => {\n    let vivo = true;\n    void getPaisParaPrecios().then((p) => { if (vivo && p) setPais(p); });\n    return () => { vivo = false; };\n  }, []);\n\n  // La lista de países (público): solo se pide cuando el huésped abre el selector, para no gastar una\n  // petición en cada visita a la ficha.\n  useEffect(() => {\n    if (!elegirMoneda || paises.length) return;\n    void hotelApi.fx(pais).then((r) => setPaises(r.paises ?? [])).catch(() => undefined);\n  }, [elegirMoneda, paises.length, pais]);\n\n  // Calendario de la habitación abierta (92 días de una vez: una sola consulta).\n  useEffect(() => {\n    if (!abierta) { setDias([]); return; }\n    let vivo = true;\n    setCargandoCal(true);\n    hotelApi\n      .calendar(abierta, todayIso(), addDays(todayIso(), MAX_NOCHES), habitaciones)\n      .then((c) => { if (vivo) setDias(c.days ?? []); })\n      .catch(() => { if (vivo) setDias([]); })\n      .finally(() => { if (vivo) setCargandoCal(false); });\n    return () => { vivo = false; };\n  }, [abierta, habitaciones]);\n\n  const noches = checkIn && checkOut ? nightsBetween(checkIn, checkOut) : 0;\n  const roomAbierta = rooms.find((r) => r.id === abierta) ?? null;\n\n  const cuenta = (() => {\n    if (!roomAbierta || !noches) return null;\n    const precios = dias\n      .filter((d) => checkIn && checkOut && d.date >= checkIn && d.date < checkOut)\n      .map((d) => d.priceXaf);\n    if (precios.length !== noches) return null;\n    const subtotal = precios.reduce((a, b) => a + b, 0) * habitaciones;\n    const limpieza = roomAbierta.cleaningFeeXaf * habitaciones;\n    const tasas = roomAbierta.taxesXaf * habitaciones;\n    const total = subtotal + limpieza + tasas;\n    const senal = Math.round((total * roomAbierta.depositPercent) / 100);\n    return { subtotal, limpieza, tasas, total, senal, resto: total - senal, media: Math.round(subtotal / noches / habitaciones) };\n  })();\n\n  const irAReservar = (room: HotelRoom) => {\n    router.push({\n      pathname: '/lifebook-hotel-reservar',\n      params: {\n        roomTypeId: room.id,\n        shopId,\n        shopName: hotel?.name ?? '',\n        ...(checkIn ? { checkIn } : {}),\n        ...(checkOut ? { checkOut } : {}),\n        guests: String(huespedes),\n        units: String(habitaciones),\n      },\n    } as never);\n  };\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={styles.volver}>\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        {/* El nombre del alojamiento lo escribe el hotelero: dos líneas antes que recortarlo. */}\n        <Text style={[styles.titulo, { color: colors.textPrimary }]} numberOfLines={2}>\n          {hotel?.name ?? 'Alojamiento'}\n        </Text>\n      </View>\n\n      {cargando ? (\n        <View style={styles.centro}><ActivityIndicator color={colors.primary} /></View>\n      ) : error ? (\n        <View style={[styles.error, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>{error}</Text>\n          <Pressable onPress={() => void cargar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n            <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ paddingBottom: insets.bottom + 30, gap: espaciado.e14 }}>\n          {/* ── Galería del alojamiento (fotos reales subidas por el hotelero) ── */}\n          <PhotoGallery\n            photos={[\n              absUrl(hotel?.coverUrl),\n              ...rooms.flatMap((r) => (r.images ?? []).map((i) => absUrl((i as { url?: string })?.url))),\n            ].filter((u): u is string => !!u)}\n            height={230}\n            emptyLabel=\"Este alojamiento todavía no tiene fotos\"\n            emptyIcon=\"🏨\"\n            overlay={\n              <Pressable\n                onPress={() => router.back()}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Volver\"\n                hitSlop={12}\n                style={[styles.volverFlotante, { top: insets.top + 8 }]}\n              >\n                <Text style={styles.volverFlotanteTxt}>‹</Text>\n              </Pressable>\n            }\n          />\n\n          <View style={{ paddingHorizontal: espaciado.e14, gap: espaciado.e14 }}>\n          {/* ── Datos del alojamiento ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.nombre, { color: colors.textPrimary }]}>{hotel?.name}</Text>\n            <Text style={[styles.sub, { color: colors.textSecondary }]}>\n              {[TIPOS[hotel?.propertyKind ?? ''] ?? null, hotel?.stars ? `${hotel.stars}★` : null,\n                hotel?.barrio, hotel?.city].filter(Boolean).join(' · ')}\n            </Text>\n            {/* Horario de llegada: es la primera pregunta del huésped al reservar. */}\n            <Text style={[styles.dato, { color: colors.textPrimary }]}>\n              🕐 Entrada de {hotel?.checkinFrom} a {hotel?.checkinUntil} · salida hasta {hotel?.checkoutUntil}\n              {hotel?.receptionOpen24h ? ' · recepción 24 h' : ''}\n            </Text>\n            {hotel?.addressReference ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>📍 {hotel.addressReference}</Text>\n            ) : null}\n\n            {/* ── CÓMO LLEGAR ────────────────────────────────────────────────────────\n                Una referencia («frente al mar») no lleva a ningún sitio. Con las coordenadas del\n                hotel, el botón abre el mapa EN EL PUNTO; sin ellas, cae a buscar el texto. */}\n            {arrival && (arrival.lat !== null || arrival.addressReference) ? (\n              <Pressable\n                onPress={() => abrirMapa(arrival.lat, arrival.lng, arrival.addressReference ?? hotel?.name ?? null)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Cómo llegar a ${hotel?.name ?? 'el alojamiento'}`}\n                style={[styles.botonLinea, { borderColor: colors.border, backgroundColor: colors.surface }]}\n              >\n                <Navigation size={14} color={colors.secondary} />\n                <Text style={[styles.botonLineaTxt, { color: colors.textPrimary }]}>\n                  Cómo llegar{arrival.lat !== null ? '' : ' (por la referencia escrita)'}\n                </Text>\n              </Pressable>\n            ) : null}\n\n            {/* ── AL LLEGAR ──────────────────────────────────────────────────────────\n                Lo que el huésped necesita cuando baja del taxi: dónde se entra y dónde está la\n                recepción. Lo escribe el hotel en su panel (si no lo ha escrito, no se inventa). */}\n            {arrival?.note ? (\n              <View style={[styles.aviso, { borderColor: alpha(colors.success, 0.45), backgroundColor: alpha(colors.success, 0.10) }]}>\n                <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.success }}>🔑 Al llegar</Text>\n                <Text style={{ fontSize: tipografia.caption, color: colors.textPrimary, marginTop: espaciado.e3, lineHeight: 16 }}>{arrival.note}</Text>\n              </View>\n            ) : null}\n\n            {/* ── TAXI DESDE EL AEROPUERTO ───────────────────────────────────────────\n                Llegar al aeropuerto y poder ir al hotel sin escribir una sola dirección: el origen\n                (el aeropuerto de la ciudad) y el destino (el hotel) van puestos. El precio de\n                referencia de la zona se enseña ANTES de pedirlo, para que no haya sorpresas. */}\n            {airport ? (\n              <View style={[styles.aviso, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textPrimary }}>🛫 ¿Llegas al aeropuerto?</Text>\n                <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e3, lineHeight: 15 }}>\n                  Pide un taxi {airport.label} → {hotel?.name}\n                  {airport.priceFromXaf !== null && airport.priceToXaf !== null\n                    ? ` · desde ${xaf(airport.priceFromXaf)} hasta ${xaf(airport.priceToXaf)}`\n                    : ''}\n                </Text>\n                <Pressable\n                  onPress={() => router.push({\n                    pathname: '/taxi',\n                    params: {\n                      city: airport.city ?? hotel?.city ?? '',\n                      oLat: String(airport.lat), oLng: String(airport.lng), oLabel: airport.label,\n                      dLat: String(arrival?.lat ?? ''), dLng: String(arrival?.lng ?? ''),\n                      dLabel: hotel?.name ?? '',\n                    },\n                  } as never)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Pedir un taxi desde el aeropuerto hasta el hotel\"\n                  style={[styles.botonLinea, { borderColor: alpha(ACCENT, 0.5), backgroundColor: alpha(ACCENT, 0.10) }]}\n                >\n                  <Car size={14} color={ACCENT} />\n                  <Text style={[styles.botonLineaTxt, { color: ACCENT }]}>Pedir taxi al hotel</Text>\n                </Pressable>\n              </View>\n            ) : null}\n            {hotel?.description ? (\n              <Text style={[styles.dato, { color: colors.textPrimary }]}>{hotel.description}</Text>\n            ) : null}\n\n            {(hotel?.amenities ?? []).length ? (\n              <View style={styles.servicios}>\n                {(hotel?.amenities ?? []).map((a) => (\n                  <View key={a} style={[styles.servicio, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                    <Text style={[styles.servicioTxt, { color: colors.textPrimary }]}>\n                      {SERVICIOS[a] ?? a.replace(/_/g, ' ')}\n                    </Text>\n                  </View>\n                ))}\n              </View>\n            ) : null}\n\n            {(hotel?.paymentMethods ?? []).length ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                Formas de pago:{' '}\n                {(hotel?.paymentMethods ?? [])\n                  .map((m) => (typeof m === 'string' ? m : m.method))\n                  .map((m) => ({ transfer: 'transferencia', in_store: 'en recepción', billing: 'facturación',\n                    deposit: 'señal', cash_on_delivery: 'contra entrega', likebook_wallet: 'monedero' }[m] ?? m))\n                  .join(' · ')}\n              </Text>\n            ) : null}\n            {hotel?.houseRules ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>Normas: {hotel.houseRules}</Text>\n            ) : null}\n            {hotel?.cancellationPolicy ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>Cancelación: {hotel.cancellationPolicy}</Text>\n            ) : null}\n          </View>\n\n          {/* ── Habitaciones ── */}\n          <Text style={[styles.seccion, { color: colors.textPrimary }]}>\n            Habitaciones ({rooms.length})\n          </Text>\n\n          {/* ── CON QUÉ MONEDA ESTÁ VIENDO LOS PRECIOS ────────────────────────────────\n              El precio real, y el que se cobra, es en XAF (en efectivo, al llegar al hotel). Esto\n              solo cambia CÓMO SE ENSEÑA, para que quien reserva desde fuera sepa cuánto es. Se dice\n              con todas las letras, con la fecha del cambio y sin llamarlo «precio»: es una referencia. */}\n          <View style={{ gap: espaciado.e6 }}>\n            <Pressable\n              onPress={() => setElegirMoneda((v) => !v)}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Elegir el país para ver los precios en su moneda\"\n              style={[styles.botonLinea, { borderColor: colors.border, backgroundColor: colors.surface, alignSelf: 'flex-start' }]}\n            >\n              <Text style={[styles.botonLineaTxt, { color: colors.textPrimary }]}>\n                {fx && !fx.esMonedaDelCobro\n                  ? `${fx.countryLabel ?? fx.currency} · ${fx.symbol}`\n                  : '💱 Ver los precios en otra moneda'}\n              </Text>\n            </Pressable>\n            {fx && !fx.esMonedaDelCobro ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                Equivalencia orientativa al cambio del {fx.updatedAt ? shortDate(String(fx.updatedAt).slice(0, 10)) : '—'}.\n                El pago es en XAF (francos), en efectivo al llegar.\n              </Text>\n            ) : null}\n            {elegirMoneda ? (\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                {paises.length === 0 ? (\n                  <Text style={[styles.sub, { color: colors.textSecondary }]}>Cargando países…</Text>\n                ) : (\n                  paises.map((p) => (\n                    <Pressable\n                      key={p.code}\n                      onPress={() => { setElegirMoneda(false); setPais(p.code); void setPaisElegido(p.code); }}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={`Ver los precios desde ${p.label} (${p.currency})`}\n                      style={[styles.botonLinea, {\n                        borderColor: pais === p.code ? colors.secondary : colors.border,\n                        backgroundColor: pais === p.code ? alpha(colors.secondary, 0.12) : colors.surface,\n                      }]}\n                    >\n                      <Text style={[styles.botonLineaTxt, { color: colors.textPrimary }]}>{p.label} · {p.currency}</Text>\n                    </Pressable>\n                  ))\n                )}\n              </View>\n            ) : null}\n          </View>\n\n          {rooms.length === 0 ? (\n            <Text style={[styles.sub, { color: colors.textSecondary }]}>\n              Este alojamiento todavía no tiene habitaciones publicadas.\n            </Text>\n          ) : null}\n\n          {rooms.map((r) => {\n            const esAbierta = r.id === abierta;\n            return (\n              <View key={r.id} style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                <Pressable\n                  onPress={() => setAbierta(esAbierta ? null : r.id)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`${r.name}: ${esAbierta ? 'ocultar' : 'ver'} calendario`}\n                  accessibilityState={{ expanded: esAbierta }}\n                >\n                  <View style={styles.filaHab}>\n                    <View style={{ flex: 1 }}>\n                      <Text style={[styles.habNombre, { color: colors.textPrimary }]}>{r.name}</Text>\n                      <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                        {r.capacity} huésped(es)\n                        {r.beds?.length ? ` · ${r.beds.map((b) => `${b.count} ${b.kind}`).join(', ')}` : ''}\n                        {r.sizeM2 ? ` · ${r.sizeM2} m²` : ''}\n                        {r.totalUnits > 1 ? ` · ${r.totalUnits} iguales` : ''}\n                      </Text>\n                      <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                        Estancia mínima {r.minNights} noche(s)\n                        {r.depositPercent > 0 ? ` · señal del ${r.depositPercent}%` : ' · sin señal (pago al llegar)'}\n                        {r.cancellationHours ? ` · cancelación gratis hasta ${r.cancellationHours} h antes` : ''}\n                      </Text>\n                    </View>\n                    <View style={{ alignItems: 'flex-end' }}>\n                      <Text style={[styles.precio, { color: colors.secondary }]}>{xaf(r.basePriceXaf)}</Text>\n                      {/* ── EL PRECIO EN LA MONEDA DEL HUÉSPED ────────────────────────\n                          El precio real es el XAF (es lo que se cobra, en efectivo, al llegar). El\n                          equivalente se enseña para que un huésped de fuera sepa cuánto es: lo calcula\n                          el servidor. Si el país usa XAF, `esMonedaDelCobro` lo dice y NO se repite la\n                          misma cifra con un «≈». */}\n                      {typeof r.pricePerNightLocal === 'number' && fx && !fx.esMonedaDelCobro ? (\n                        <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                          ≈ {formatearMoneda(r.pricePerNightLocal, fx.currency, fx.decimals)}\n                        </Text>\n                      ) : null}\n                      <Text style={[styles.sub, { color: colors.textSecondary }]}>por noche</Text>\n                    </View>\n                  </View>\n                </Pressable>\n\n                {esAbierta ? (\n                  <View style={{ marginTop: espaciado.e10, gap: espaciado.e10 }}>\n                    <CalendarPicker\n                      days={dias}\n                      checkIn={checkIn}\n                      checkOut={checkOut}\n                      onChange={(a, b) => { setCheckIn(a); setCheckOut(b); }}\n                      units={habitaciones}\n                      minNights={r.minNights}\n                      maxNights={Math.min(MAX_NOCHES, r.maxNights)}\n                      loading={cargandoCal}\n                    />\n\n                    {/* ── La cuenta, con el pago parcial bien visible ── */}\n                    {cuenta ? (\n                      <View style={[styles.cuenta, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                        <Fila etiqueta={`${noches} noche(s)${habitaciones > 1 ? ` × ${habitaciones} habitaciones` : ''}`} valor={xaf(cuenta.subtotal)} />\n                        <Fila etiqueta={`Precio medio por noche`} valor={xaf(cuenta.media)} tenue />\n                        {cuenta.limpieza ? <Fila etiqueta=\"Limpieza\" valor={xaf(cuenta.limpieza)} /> : null}\n                        {cuenta.tasas ? <Fila etiqueta=\"Tasas\" valor={xaf(cuenta.tasas)} /> : null}\n                        <View style={[styles.separador, { backgroundColor: colors.border }]} />\n                        <Fila etiqueta=\"Total de la estancia\" valor={xaf(cuenta.total)} fuerte />\n                        {cuenta.senal > 0 ? (\n                          <>\n                            <Fila\n                              etiqueta={`Se pagará AHORA (señal ${r.depositPercent}%)`}\n                              valor={xaf(cuenta.senal)}\n                              color={colors.primary}\n                              fuerte\n                            />\n                            <Fila etiqueta=\"Y al llegar al hotel\" valor={xaf(cuenta.resto)} color={colors.secondary} fuerte />\n                            <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                              La habitación queda retenida {r.holdMinutes} min mientras se paga la señal.\n                            </Text>\n                          </>\n                        ) : (\n                          <Fila etiqueta=\"Se paga todo al llegar\" valor={xaf(cuenta.total)} color={colors.secondary} fuerte />\n                        )}\n                      </View>\n                    ) : (\n                      <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                        Elige entrada y salida en el calendario para ver el total y la señal.\n                      </Text>\n                    )}\n\n                    <Pressable\n                      onPress={() => irAReservar(r)}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={`Reservar ${r.name}`}\n                      style={[styles.cta, { backgroundColor: colors.primary }]}\n                    >\n                      <Text style={styles.ctaTxt}>\n                        {noches ? `Reservar · ${cuenta ? xaf(cuenta.total) : `${noches} noche(s)`}` : 'Elegir fechas y reservar'}\n                      </Text>\n                    </Pressable>\n                  </View>\n                ) : null}\n              </View>\n            );\n          })}\n\n          {checkIn && checkOut ? (\n            <Text style={[styles.sub, { color: colors.textSecondary }]}>\n              Fechas elegidas: {shortDate(checkIn, true)} → {shortDate(checkOut, true)} · {noches} noche(s)\n            </Text>\n          ) : null}\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nfunction Fila({\n  etiqueta, valor, tenue, fuerte, color,\n}: { etiqueta: string; valor: string; tenue?: boolean; fuerte?: boolean; color?: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.filaCuenta}>\n      <Text style={[styles.cuentaEtq, { color: tenue ? colors.textSecondary : colors.textPrimary, fontWeight: fuerte ? '700' : '500' }]}>\n        {etiqueta}\n      </Text>\n      <Text style={[styles.cuentaVal, { color: color ?? colors.textPrimary, fontWeight: fuerte ? '800' : '600' }]}>\n        {valor}\n      </Text>\n    </View>\n  );\n}\n\nfunction addDays(iso: string, days: number): string {\n  const d = new Date(`${iso}T00:00:00Z`);\n  d.setUTCDate(d.getUTCDate() + days);\n  return d.toISOString().slice(0, 10);\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  barra: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1 },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  // Botón de volver flotante sobre la galería (la barra superior se ve, pero en la\n  // ficha el pulgar está abajo: conviene tenerlo también aquí).\n  volverFlotante: {\n    position: 'absolute', left: 12, width: 36, height: 36, borderRadius: 18,\n    backgroundColor: 'rgba(0,0,0,0.45)', alignItems: 'center', justifyContent: 'center',\n  },\n  volverFlotanteTxt: { color: brand.white, fontSize: 24, fontWeight: '700', lineHeight: 26 },\n  titulo: { fontSize: 16.5, fontWeight: '800', flex: 1 },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  error: { margin: espaciado.e14, borderWidth: 1, borderRadius: 14, padding: espaciado.e12, gap: espaciado.e6 },\n  enlace: { fontSize: tipografia.caption, fontWeight: '700' },\n  bloque: { borderWidth: 1, borderRadius: 18, padding: espaciado.e12, gap: espaciado.e4 },\n  nombre: { fontSize: 18, fontWeight: '800' },\n  sub: { fontSize: tipografia.caption },\n  dato: { fontSize: tipografia.body, marginTop: espaciado.e4 },\n  servicios: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, marginTop: espaciado.e8 },\n  servicio: { borderWidth: 1, borderRadius: 20, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e4 },\n  servicioTxt: { fontSize: tipografia.caption },\n  seccion: { fontSize: 15, fontWeight: '800' },\n  /** Botón de línea (Cómo llegar, taxi, elegir moneda): el mismo aspecto en los tres sitios. */\n  botonLinea: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, marginTop: espaciado.e6 },\n  botonLineaTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  /** Aviso con borde (Al llegar / taxi): información que el huésped necesita, sin gritar. */\n  aviso: { borderWidth: 1, borderRadius: 10, padding: espaciado.e10, marginTop: espaciado.e8 },\n  filaHab: { flexDirection: 'row', gap: espaciado.e10, alignItems: 'flex-start' },\n  habNombre: { fontSize: 14.5, fontWeight: '800' },\n  precio: { fontSize: 15, fontWeight: '800' },\n  cuenta: { borderWidth: 1, borderRadius: 14, padding: espaciado.e10, gap: espaciado.e3 },\n  filaCuenta: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e10 },\n  cuentaEtq: { fontSize: tipografia.caption, flex: 1 },\n  cuentaVal: { fontSize: tipografia.body },\n  separador: { height: 1, marginVertical: espaciado.e5 },\n  cta: { height: altura.campo, borderRadius: 14, alignItems: 'center', justifyContent: 'center' },\n  ctaTxt: { color: brand.white, fontSize: 15, fontWeight: '800' },\n});\n","/**\n * CalendarPicker — EL CALENDARIO de las reservas (hotel, y reutilizable).\n *\n * Qué resuelve (era la mitad que faltaba del módulo): el buscador pedía escribir\n * las fechas a mano (`2026-07-01`) y la ficha enseñaba una fila de cuadros con el\n * día del mes, sin mes, sin semana, sin precio y sin poder elegir. Aquí hay un\n * calendario de verdad:\n *\n *   · **Mes navegable** (con botones y con el gesto de deslizar), sin salir del\n *     rango que el servidor acepta (92 días) y sin poder ir al pasado.\n *   · **Precio por noche** dentro de cada día (lo devuelve la disponibilidad) y\n *     **estado claro**: libre · fin de semana · cerrado · lleno · pasado.\n *   · **Selección de entrada y salida** con un toque: el primer toque fija la\n *     entrada, el segundo la salida (si es anterior, se reinicia la entrada).\n *   · **Días cerrados y llenos NO son seleccionables**, y una salida que cruce una\n *     noche cerrada/llena tampoco se acepta: así el usuario no llega al 409.\n *   · **Estancia mínima** avisada por noche (`minNights`) y en el resumen.\n *\n * Sin dependencias nuevas: la rejilla la calcula `utils/datetime`.\n */\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport {\n  DOW_SHORT, addDaysIso, dowMondayFirst, isWeekendNight, longDate, monthGrid,\n  monthIndex, monthLabel, nightsBetween, nightsList, parseIso, shiftMonth, todayIso, xaf,\n} from '../utils/datetime';\n\n/** Un día del calendario tal y como lo devuelve el servidor. */\nexport interface CalendarDay {\n  date: string;\n  priceXaf: number;\n  basePriceXaf?: number;\n  weekend?: boolean;\n  closed?: boolean;\n  note?: string | null;\n  minNights?: number;\n  totalUnits?: number;\n  usedUnits?: number;\n  freeUnits?: number;\n  available?: boolean;\n}\n\nexport interface CalendarPickerProps {\n  /** Días con precio y disponibilidad (una fila por noche). */\n  days: CalendarDay[];\n  /** Entrada elegida (`YYYY-MM-DD`). */\n  checkIn: string | null;\n  /** Salida elegida (`YYYY-MM-DD`). */\n  checkOut: string | null;\n  /** Se llama con (entrada, salida): la salida puede ser `null` a medio elegir. */\n  onChange: (checkIn: string | null, checkOut: string | null) => void;\n  /**\n   * Modo «solo llegada»: un toque fija el DÍA DE LLEGADA y el padre calcula la salida\n   * (con `nightsCount`). Es la forma de pedir «llego el 21 y me quedo 3 noches» sin\n   * tener que acertar con dos toques.\n   */\n  arrivalOnly?: boolean;\n  /** Noches de la estancia cuando se usa `arrivalOnly` (para pintar el rango). */\n  nightsCount?: number;\n  /** Habitaciones que se quieren reservar (para exigir disponibilidad suficiente). */\n  units?: number;\n  /** Estancia mínima del tipo de habitación (por si una noche no la trae). */\n  minNights?: number;\n  /** Noches máximas que se pueden elegir de una vez. */\n  maxNights?: number;\n  /** Mes inicial (`YYYY-MM`) — por defecto, el del primer día con datos. */\n  initialMonth?: string;\n  /** Cargando el rango del mes (spinner discreto en la cabecera). */\n  loading?: boolean;\n  /** Se pide un mes nuevo al navegar (el servidor devuelve 92 días de una vez). */\n  onMonthChange?: (from: string, to: string) => void;\n  /** Texto bajo el calendario (por defecto, el resumen de noches y total). */\n  footer?: React.ReactNode;\n}\n\nexport function CalendarPicker({\n  days,\n  checkIn,\n  checkOut,\n  onChange,\n  arrivalOnly = false,\n  nightsCount,\n  units = 1,\n  minNights = 1,\n  maxNights = 30,\n  initialMonth,\n  loading = false,\n  onMonthChange,\n  footer,\n}: CalendarPickerProps) {\n  const { colors } = useTheme();\n  const hoy = todayIso();\n\n  // Índice por fecha: el calendario consulta O(1) por celda (sin recorrer el array).\n  const porFecha = useMemo(() => {\n    const m = new Map<string, CalendarDay>();\n    for (const d of days) m.set(d.date, d);\n    return m;\n  }, [days]);\n\n  const primerDia = days[0]?.date ?? hoy;\n  const [mes, setMes] = useState(() => {\n    const base = initialMonth ? `${initialMonth}-01` : (checkIn ?? primerDia);\n    const d = parseIso(base);\n    return { year: d.getUTCFullYear(), month0: d.getUTCMonth() };\n  });\n\n  // El mes visible sigue a la selección cuando cambia desde fuera (p. ej. al abrir\n  // el calendario con fechas ya elegidas).\n  const seleccionPrevia = useRef<string | null>(null);\n  useEffect(() => {\n    if (!checkIn || seleccionPrevia.current === checkIn) return;\n    seleccionPrevia.current = checkIn;\n    const d = parseIso(checkIn);\n    setMes({ year: d.getUTCFullYear(), month0: d.getUTCMonth() });\n  }, [checkIn]);\n\n  // Al cambiar de mes se pide el rango si el padre lo necesita (92 días de golpe).\n  useEffect(() => {\n    if (!onMonthChange) return;\n    const desde = `${mes.year}-${String(mes.month0 + 1).padStart(2, '0')}-01`;\n    onMonthChange(desde, addDaysIso(desde, 91));\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [mes.year, mes.month0]);\n\n  const celdas = useMemo(() => monthGrid(mes.year, mes.month0), [mes.year, mes.month0]);\n  const mesActual = monthIndex(parseIso(hoy).getUTCFullYear(), parseIso(hoy).getUTCMonth());\n  const mesVisible = monthIndex(mes.year, mes.month0);\n  const puedeAtras = mesVisible > mesActual;\n  const puedeAlante = mesVisible - mesActual < 3; // 92 días ≈ 3 meses\n\n  /** ¿El día se puede tocar? (libre, con plazas, ni pasado ni cerrado) */\n  const seleccionable = (d: CalendarDay | undefined, iso: string): boolean => {\n    if (iso < hoy) return false;\n    if (!d) return false;\n    if (d.closed) return false;\n    if (d.available === false) return false;\n    if (units > 1 && Number(d.freeUnits ?? 0) < units) return false;\n    return true;\n  };\n\n  /**\n   * Un toque fija entrada o salida. Si la salida elegida cruza una noche que no\n   * está libre (o se pasa del máximo), se avisa con el estado y NO se acepta: el\n   * servidor lo rechazaría con 409 y es mejor no llegar ahí.\n   */\n  const tocar = (iso: string) => {\n    const d = porFecha.get(iso);\n    if (!seleccionable(d, iso)) return;\n    // Modo «solo llegada»: un toque = día de llegada. La salida la pone el padre con las\n    // noches pedidas, así que aquí no se espera un segundo toque (que era justo lo que\n    // hacía imposible entender cómo elegir «3 noches»).\n    if (arrivalOnly) {\n      onChange(iso, null);\n      return;\n    }\n    if (!checkIn || (checkIn && checkOut)) {\n      onChange(iso, null);\n      return;\n    }\n    if (iso <= checkIn) {\n      onChange(iso, null); // toca antes o el mismo día: empieza de nuevo\n      return;\n    }\n    const noches = nightsBetween(checkIn, iso);\n    if (noches > maxNights) return;\n    const problema = nightsList(checkIn, iso).find((n) => !seleccionable(porFecha.get(n), n));\n    if (problema) return;\n    const minExigida = Math.max(minNights, ...nightsList(checkIn, iso).map((n) => Number(porFecha.get(n)?.minNights ?? 0)));\n    if (noches < minExigida) return;\n    onChange(checkIn, iso);\n  };\n\n  /**\n   * Rango VISUAL de la estancia. En modo «solo llegada» la salida todavía no la conoce\n   * este componente (la calcula el padre con las noches pedidas), así que se pinta el\n   * rango a partir de `nightsCount`: así el usuario VE las noches que está eligiendo.\n   */\n  const hastaVisual = useMemo(() => {\n    if (checkOut) return checkOut;\n    if (arrivalOnly && checkIn && nightsCount) return addDaysIso(checkIn, nightsCount);\n    return null;\n  }, [checkOut, arrivalOnly, checkIn, nightsCount]);\n\n  // ── Resumen (noches, precio medio y lo que se paga ahora) ──\n  const resumen = useMemo(() => {\n    if (!checkIn || !hastaVisual) return null;\n    const noches = nightsList(checkIn, hastaVisual);\n    if (!noches.length) return null;\n    const precios = noches.map((n) => Number(porFecha.get(n)?.priceXaf ?? 0));\n    if (precios.some((p) => !p)) return null;\n    const subtotal = precios.reduce((a, b) => a + b, 0) * units;\n    return {\n      noches: noches.length,\n      nochesIso: noches,\n      subtotal,\n      media: Math.round(precios.reduce((a, b) => a + b, 0) / precios.length),\n      finesDeSemana: noches.filter(isWeekendNight).length,\n      salida: hastaVisual,\n    };\n  }, [checkIn, hastaVisual, porFecha, units]);\n\n  return (\n    <View style={[styles.wrap, { borderColor: colors.border, backgroundColor: colors.card }]}>\n      {/* ── Cabecera: mes y navegación ── */}\n      <View style={styles.head}>\n        <Pressable\n          onPress={() => puedeAtras && setMes(shiftMonth(mes.year, mes.month0, -1))}\n          disabled={!puedeAtras}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Mes anterior\"\n          accessibilityState={{ disabled: !puedeAtras }}\n          style={({ pressed }) => [styles.nav, { borderColor: colors.border, opacity: puedeAtras ? (pressed ? 0.6 : 1) : 0.3 }]}\n        >\n          <Text style={[styles.navTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <View style={styles.headMid}>\n          <Text style={[styles.mes, { color: colors.textPrimary }]}>{monthLabel(mes.year, mes.month0)}</Text>\n          {loading ? <Text style={[styles.cargando, { color: colors.textSecondary }]}>cargando…</Text> : null}\n        </View>\n        <Pressable\n          onPress={() => puedeAlante && setMes(shiftMonth(mes.year, mes.month0, 1))}\n          disabled={!puedeAlante}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Mes siguiente\"\n          accessibilityState={{ disabled: !puedeAlante }}\n          style={({ pressed }) => [styles.nav, { borderColor: colors.border, opacity: puedeAlante ? (pressed ? 0.6 : 1) : 0.3 }]}\n        >\n          <Text style={[styles.navTxt, { color: colors.textPrimary }]}>›</Text>\n        </Pressable>\n      </View>\n\n      {/* ── Días de la semana (lunes primero) ── */}\n      <View style={styles.dowRow}>\n        {DOW_SHORT.map((d, i) => (\n          <Text key={`${d}${i}`} style={[styles.dow, { color: colors.textSecondary }]}>{d}</Text>\n        ))}\n      </View>\n\n      {/* ── La rejilla: 6 semanas × 7 días ── */}\n      <View style={styles.grid}>\n        {celdas.map((c) => {\n          const d = porFecha.get(c.iso);\n          const pasado = c.iso < hoy;\n          const esEntrada = c.iso === checkIn;\n          // La «salida» que se pinta es la visual (en modo llegada se calcula con las\n          // noches pedidas), para que se vea el rango completo desde el primer toque.\n          const esSalida = !!hastaVisual && c.iso === hastaVisual;\n          const dentro = !!checkIn && !!hastaVisual && c.iso > checkIn && c.iso < hastaVisual;\n          const ok = seleccionable(d, c.iso);\n          const cerrado = !!d?.closed;\n          const lleno = !cerrado && d?.available === false;\n          const finde = isWeekendNight(c.iso);\n          const conDatos = !!d;\n\n          // Colores por estado: la leyenda de abajo explica cada uno.\n          const fondo = esEntrada || esSalida\n            ? colors.primary\n            : dentro\n              ? alpha(colors.primary, 0.14)\n              : 'transparent';\n          const texto = esEntrada || esSalida\n            ? brand.white\n            : !c.inMonth || pasado\n              ? colors.textSecondary\n              : cerrado || lleno || !ok\n                ? colors.textSecondary\n                : colors.textPrimary;\n\n          return (\n            <Pressable\n              key={c.iso}\n              onPress={() => tocar(c.iso)}\n              disabled={!ok}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`${longDate(c.iso)}${conDatos ? `, ${xaf(d?.priceXaf)}` : ''}${cerrado ? ', cerrado' : lleno ? ', sin disponibilidad' : ''}`}\n              accessibilityState={{ disabled: !ok, selected: esEntrada || esSalida }}\n              style={({ pressed }) => [\n                styles.cell,\n                { backgroundColor: fondo, opacity: pressed ? 0.7 : 1 },\n                c.iso === hoy && !esEntrada && !esSalida ? { borderColor: colors.primary, borderWidth: 1 } : null,\n              ]}\n            >\n              <Text style={[styles.dia, { color: texto, opacity: c.inMonth ? 1 : 0.4 }]}>{c.day}</Text>\n              {conDatos && c.inMonth && !pasado ? (\n                cerrado ? (\n                  <Text style={[styles.precio, { color: colors.textSecondary }]}>cerrado</Text>\n                ) : lleno ? (\n                  <Text style={[styles.precio, { color: colors.danger }]}>lleno</Text>\n                ) : (\n                  <Text style={[styles.precio, { color: finde ? colors.secondary : colors.textSecondary }]}>\n                    {Math.round(Number(d?.priceXaf ?? 0) / 1000)}k\n                  </Text>\n                )\n              ) : null}\n              {conDatos && c.inMonth && !pasado && ok && Number(d?.minNights ?? 1) > 1 ? (\n                <Text style={[styles.min, { color: colors.textSecondary }]}>mín {d?.minNights}</Text>\n              ) : null}\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {/* ── Leyenda: qué significa cada color ── */}\n      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.leyenda}>\n        <Leyenda color={colors.primary} texto=\"tu selección\" colors={colors} />\n        <Leyenda color={colors.secondary} texto=\"fin de semana\" colors={colors} />\n        <Leyenda color={colors.textSecondary} texto=\"cerrado / pasado\" colors={colors} />\n        <Leyenda color={colors.danger} texto=\"sin plazas\" colors={colors} />\n        <Leyenda color={colors.border} texto=\"mín N = estancia mínima\" colors={colors} />\n      </ScrollView>\n\n      {/* ── Resumen de la selección ── */}\n      {resumen ? (\n        <View style={[styles.resumen, { borderTopColor: colors.border }]}>\n          <Text style={[styles.resumenTxt, { color: colors.textPrimary }]}>\n            {longDate(checkIn as string)} → {longDate(resumen.salida)}\n          </Text>\n          <Text style={[styles.resumenSub, { color: colors.textSecondary }]}>\n            {resumen.noches} noche{resumen.noches === 1 ? '' : 's'}\n            {units > 1 ? ` · ${units} habitaciones` : ''}\n            {' · '}{xaf(resumen.media)} por noche\n            {resumen.finesDeSemana ? ` · ${resumen.finesDeSemana} de fin de semana` : ''}\n          </Text>\n          <Text style={[styles.total, { color: colors.textPrimary }]}>\n            Estancia: {xaf(resumen.subtotal)}\n          </Text>\n        </View>\n      ) : (\n        <View style={[styles.resumen, { borderTopColor: colors.border }]}>\n          <Text style={[styles.resumenSub, { color: colors.textSecondary }]}>\n            {arrivalOnly\n              ? 'Toca el día de LLEGADA (los días los eliges con el contador de arriba)'\n              : checkIn ? 'Ahora toca el día de SALIDA' : 'Toca el día de ENTRADA'}\n          </Text>\n        </View>\n      )}\n\n      {footer}\n    </View>\n  );\n}\n\nfunction Leyenda({ color, texto, colors }: { color: string; texto: string; colors: { textSecondary: string } }) {\n  return (\n    <View style={styles.leyendaItem}>\n      <View style={[styles.punto, { backgroundColor: color }]} />\n      <Text style={[styles.leyendaTxt, { color: colors.textSecondary }]}>{texto}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  wrap: { borderWidth: 1, borderRadius: 18, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e10 },\n  head: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e4 },\n  headMid: { flex: 1, alignItems: 'center' },\n  nav: { width: 38, height: 38, borderRadius: radios.md, borderWidth: 1, alignItems: 'center', justifyContent: 'center' },\n  navTxt: { fontSize: 22, fontWeight: '800', lineHeight: 24 },\n  mes: { fontSize: tipografia.subtitle, fontWeight: '800', textTransform: 'capitalize' },\n  cargando: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n  dowRow: { flexDirection: 'row', marginTop: espaciado.e10, marginBottom: espaciado.e4 },\n  dow: { flex: 1, textAlign: 'center', fontSize: tipografia.caption, fontWeight: '700' },\n  grid: { flexDirection: 'row', flexWrap: 'wrap' },\n  cell: {\n    width: `${100 / 7}%`, minHeight: 56, borderRadius: radios.md, paddingVertical: espaciado.e4,\n    alignItems: 'center', justifyContent: 'flex-start', borderWidth: 0,\n  },\n  dia: { fontSize: tipografia.body, fontWeight: '700' },\n  precio: { fontSize: 9.5, fontWeight: '600', marginTop: 1 },\n  min: { fontSize: 8.5, marginTop: 0 },\n  leyenda: { gap: espaciado.e12, paddingVertical: espaciado.e8, paddingHorizontal: espaciado.e2, alignItems: 'center' },\n  leyendaItem: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5 },\n  punto: { width: 9, height: 9, borderRadius: 5 },\n  leyendaTxt: { fontSize: 10.5 },\n  resumen: { borderTopWidth: 1, paddingTop: espaciado.e10, paddingHorizontal: espaciado.e4, gap: espaciado.e2 },\n  resumenTxt: { fontSize: tipografia.body, fontWeight: '700' },\n  resumenSub: { fontSize: tipografia.caption },\n  total: { fontSize: 14.5, fontWeight: '800', marginTop: espaciado.e2 },\n});\n","/**\n * PhotoGallery — GALERÍA DE FOTOS con puntos, reutilizable.\n *\n * Se extrae del patrón que ya usa el módulo de alquiler (`alquiler-detalle.tsx`: scroll\n * horizontal con `pagingEnabled`, `onMomentumScrollEnd` y puntos indicadores) para no\n * tener dos galerías distintas en la app. La usan la ficha del hotel y la de la\n * habitación, y las filas de resultados usan la misma imagen (`LazyImage` + `absUrl`).\n *\n * Detalles que importan en el móvil:\n *   · `absUrl` en cada foto: el backend puede devolver rutas internas (`/wallet/...`).\n *   · Puntos con `accessibilityElementsHidden` (un lector de pantalla no necesita «1 de 4»\n *     repetido por cada foto; el contenedor ya lleva la etiqueta).\n *   · Sin fotos: un hueco con el icono y «Sin fotos todavía», nunca un cuadrado roto.\n */\nimport React, { useCallback, useRef, useState } from 'react';\nimport {\n  LayoutChangeEvent, NativeScrollEvent, NativeSyntheticEvent, Pressable, ScrollView, StyleSheet, Text, View, useWindowDimensions,\n} from 'react-native';\nimport { alpha, brand, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../api/config';\nimport { LazyImage } from './rental/LazyImage';\n\nexport function GalleryDots({ total, activeIndex }: { total: number; activeIndex: number }) {\n  const { colors } = useTheme();\n  if (total <= 1) return null;\n  return (\n    <View style={styles.dots} accessibilityElementsHidden>\n      {Array.from({ length: total }).map((_, i) => (\n        <View\n          key={i}\n          style={[\n            styles.dot,\n            { backgroundColor: i === activeIndex ? brand.white : alpha(brand.white, 0.45) },\n            i === activeIndex ? styles.dotActive : null,\n          ]}\n        />\n      ))}\n    </View>\n  );\n}\n\nexport interface PhotoGalleryProps {\n  /** URLs de las fotos (se les aplica `absUrl`). */\n  photos: (string | null | undefined)[];\n  /** Alto del carrete (por defecto, un 16:10 del ancho). */\n  height?: number;\n  /** Texto cuando no hay fotos. */\n  emptyLabel?: string;\n  /** Icono/emoji para el hueco vacío (por defecto, un emoji de cama). */\n  emptyIcon?: string;\n  /** Contenido superpuesto (botón de volver, insignias, contador…). */\n  overlay?: React.ReactNode;\n  /** Ancho de una página si no se quiere el ancho de la ventana. */\n  width?: number;\n  /** Radio de las esquinas (0 = a sangre). */\n  radius?: number;\n}\n\nexport function PhotoGallery({\n  photos,\n  height,\n  emptyLabel = 'Sin fotos todavía',\n  emptyIcon = '🛏️',\n  overlay,\n  width,\n  radius = 0,\n}: PhotoGalleryProps) {\n  const { colors } = useTheme();\n  const ventana = useWindowDimensions();\n  const [ancho, setAncho] = useState(width ?? ventana.width);\n  const [activa, setActiva] = useState(0);\n  const scroller = useRef<ScrollView>(null);\n\n  const urls = (photos ?? []).map((p) => absUrl(p ?? '')).filter((u) => !!u);\n  const alto = height ?? Math.round((width ?? ventana.width) * 0.62);\n\n  const onLayout = useCallback((e: LayoutChangeEvent) => {\n    const w = e.nativeEvent.layout.width;\n    if (w > 0 && w !== ancho) {\n      setAncho(w);\n      setActiva(0);\n      scroller.current?.scrollTo({ x: 0, animated: false });\n    }\n  }, [ancho]);\n\n  const onScrollEnd = useCallback((e: NativeSyntheticEvent<NativeScrollEvent>) => {\n    const w = e.nativeEvent.layoutMeasurement.width || ancho;\n    const i = Math.round(e.nativeEvent.contentOffset.x / Math.max(1, w));\n    setActiva(Math.max(0, Math.min(i, urls.length - 1)));\n  }, [ancho, urls.length]);\n\n  return (\n    <View style={[{ height: alto, position: 'relative' }, radius ? { borderRadius: radius, overflow: 'hidden' } : null]} onLayout={onLayout}>\n      <ScrollView\n        ref={scroller}\n        horizontal\n        pagingEnabled\n        showsHorizontalScrollIndicator={false}\n        onMomentumScrollEnd={onScrollEnd}\n        accessibilityLabel=\"Galería de fotos\"\n      >\n        {urls.length === 0 ? (\n          <View style={[{ width: ancho, height: alto, backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center' }]}>\n            <Text style={{ fontSize: 36 }}>{emptyIcon}</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>{emptyLabel}</Text>\n          </View>\n        ) : (\n          urls.map((u, i) => (\n            <LazyImage key={`${u}-${i}`} source={{ uri: u }} style={{ width: ancho, height: alto }} />\n          ))\n        )}\n      </ScrollView>\n\n      <GalleryDots total={urls.length} activeIndex={activa} />\n\n      {urls.length > 1 ? (\n        <View style={[styles.contador, { backgroundColor: alpha('#000000', 0.55) }]}>\n          <Text style={styles.contadorTxt}>{activa + 1}/{urls.length}</Text>\n        </View>\n      ) : null}\n\n      {overlay}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  dots: { position: 'absolute', bottom: 12, alignSelf: 'center', flexDirection: 'row', gap: espaciado.e6 },\n  dot: { width: 7, height: 7, borderRadius: 4 },\n  dotActive: { width: 18 },\n  contador: { position: 'absolute', top: 12, right: 12, borderRadius: 10, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 },\n  contadorTxt: { color: brand.white, fontSize: tipografia.micro, fontWeight: '700' },\n});\n","/**\n * ¿Desde qué país está reservando el huésped?\n *\n * El precio real del hotel es en XAF (francos) y el pago es en efectivo, pero un huésped que reserva\n * desde España, China o Estados Unidos necesita ver cuánto es en SU moneda para decidir. El servidor\n * hace la conversión; aquí solo se averigua el país.\n *\n * ── POR QUÉ CON TANTO CUIDADO ──────────────────────────────────────────────────\n * No hay `expo-localization` instalado, así que se intenta por `Intl`. En Hermes puede no existir o\n * venir sin datos de región, y un `Intl` que revienta en el arranque dejaría la pantalla del hotel en\n * blanco: por eso todo va en `try` y, si no se puede saber, se devuelve `null` (y la pantalla ofrece\n * elegir la moneda a mano). **Nunca se adivina un país**: enseñar euros a quien paga en francos sería\n * peor que no enseñar nada.\n */\nimport AsyncStorage from '@react-native-async-storage/async-storage';\n\nconst CLAVE = 'eg.fx.country';\n\n/**\n * País del dispositivo ('ES', 'GQ', 'CN'…) o `null` si no se puede saber.\n * Se mira la configuración regional del sistema (`es-ES` → ES); el idioma solo (`es`) NO sirve: dice\n * el idioma, no el país, y confundirlos mandaría a media África a ver precios en euros.\n */\nexport function getRegionCode(): string | null {\n  try {\n    const intl = typeof Intl !== 'undefined' ? Intl : null;\n    const loc = intl?.DateTimeFormat?.().resolvedOptions?.().locale ?? null;\n    const m = /[-_]([A-Za-z]{2})\\b/.exec(String(loc ?? ''));\n    return m ? m[1].toUpperCase() : null;\n  } catch {\n    return null;\n  }\n}\n\n/** País elegido a mano por el huésped (manda sobre el del sistema). */\nexport async function getPaisElegido(): Promise<string | null> {\n  try {\n    const v = await AsyncStorage.getItem(CLAVE);\n    return v && /^[A-Z]{2}$/.test(v) ? v : null;\n  } catch { return null; }\n}\n\nexport async function setPaisElegido(code: string | null): Promise<void> {\n  try {\n    if (code && /^[A-Z]{2}$/.test(code)) await AsyncStorage.setItem(CLAVE, code);\n    else await AsyncStorage.removeItem(CLAVE);\n  } catch { /* si no se puede guardar, la elección vale para esta pantalla */ }\n}\n\n/** El que se debe usar: el elegido a mano o, si no hay, el del sistema. */\nexport async function getPaisParaPrecios(): Promise<string | null> {\n  return (await getPaisElegido()) ?? getRegionCode();\n}\n\n/**\n * Formatea una cantidad en la moneda del huésped. Se usa `Intl.NumberFormat` si está disponible (pone\n * los separadores de SU país) y, si no, un formateo simple: nunca se deja sin pintar por un detalle de\n * formato.\n */\nexport function formatearMoneda(importe: number, currency: string, decimals: number): string {\n  try {\n    const intl = typeof Intl !== 'undefined' ? Intl : null;\n    if (intl?.NumberFormat) {\n      return new intl.NumberFormat(undefined, {\n        style: 'currency', currency, minimumFractionDigits: decimals, maximumFractionDigits: decimals,\n      }).format(importe);\n    }\n  } catch { /* moneda desconocida para Intl o Hermes sin datos */ }\n  return `${importe.toFixed(decimals)} ${currency}`;\n}\n","/**\n * lifebook-hotel-fechas — ELEGIR LAS FECHAS DE LA ESTANCIA, a pantalla completa.\n *\n * Por qué existe esta pantalla (y no el calendario dentro del buscador):\n *   Metido en el buscador, entre la ciudad, los modos, las cajas de fecha, el contador\n *   de noches, la rejilla, la leyenda y los huéspedes, el calendario quedaba tan abajo\n *   que **las últimas filas caían por debajo de la barra de navegación del móvil** y no\n *   se podían tocar: se veían los días pero no se podía elegir la llegada. Medido en el\n *   dispositivo: las celdas terminaban en y≈2260 sobre una pantalla de 2374.\n *\n * Aquí el calendario tiene la pantalla entera, así que todos los días son alcanzables, y\n * el resumen (noches y fechas) va fijo abajo con un botón «Usar estas fechas» que devuelve\n * la selección al buscador.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, altura, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { CalendarPicker, type CalendarDay } from '../components/CalendarPicker';\nimport { hotelApi, type HotelSearchResult } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { addDaysIso, nightsBetween, shortDate, todayIso } from '../utils/datetime';\n\nconst MAX_NOCHES = 92;\n\nexport default function HotelFechasScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const p = useLocalSearchParams<{\n    city?: string; checkIn?: string; checkOut?: string; guests?: string; units?: string; modo?: string;\n  }>();\n\n  const hoy = todayIso();\n  const huespedes = Number(p.guests ?? 2);\n  const habitaciones = Number(p.units ?? 1);\n\n  const [modo, setModo] = useState<'noches' | 'rango'>(p.modo === 'rango' ? 'rango' : 'noches');\n  const [checkIn, setCheckIn] = useState<string | null>(p.checkIn ?? null);\n  const [checkOut, setCheckOut] = useState<string | null>(p.checkOut ?? null);\n  const [nochesPedidas, setNochesPedidas] = useState(\n    p.checkIn && p.checkOut ? Math.max(1, nightsBetween(p.checkIn, p.checkOut)) : 1,\n  );\n\n  const [datos, setDatos] = useState<HotelSearchResult | null>(null);\n  const [dias, setDias] = useState<CalendarDay[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  // Habitación de referencia para los precios del calendario: la más barata del destino.\n  // (Sin fechas elegidas NO se exige disponibilidad: pedirla antes de elegir los días era\n  // el bug que dejaba todos los días deshabilitados.)\n  const habitacionRef = useMemo(() => {\n    const lista = datos?.hotels ?? [];\n    for (const h of lista) {\n      const apta = h.rooms.find((r) => Number(r.freeUnits ?? 0) >= habitaciones) ?? h.rooms[0];\n      if (apta) return apta;\n    }\n    return null;\n  }, [datos, habitaciones]);\n\n  const cargar = useCallback(async () => {\n    setCargando(true);\n    setError(null);\n    try {\n      const out = await hotelApi.search({\n        city: p.city || undefined,\n        guests: huespedes,\n        units: habitaciones,\n        limit: 20,\n      });\n      setDatos(out);\n      const ref = (out.hotels ?? []).flatMap((h) => h.rooms ?? [])[0];\n      if (ref) {\n        // OJO con el rango: el servidor acepta **92 noches** y responde\n      // `RANGE_TOO_LONG` si se pasa. El rango `[hoy, hoy + 91]` son 92 días justos;\n      // `hoy + 92` serían 93 y la pantalla se quedaba con «Como máximo 92 días» y sin\n      // calendario (fallo real detectado en el móvil).\n      const c = await hotelApi.calendar(ref.id, hoy, addDaysIso(hoy, MAX_NOCHES - 1), habitaciones);\n        setDias(c.days ?? []);\n      }\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudieron cargar los precios del calendario.');\n    } finally {\n      setCargando(false);\n    }\n  }, [p.city, huespedes, habitaciones, hoy]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const minNoches = useMemo(() => {\n    const base = Number(habitacionRef?.minNights ?? 1);\n    const desde = checkIn ?? hoy;\n    const hasta = addDaysIso(desde, Math.max(nochesPedidas, 1));\n    const delRango = dias\n      .filter((d) => d.date >= desde && d.date < hasta)\n      .reduce((max, d) => Math.max(max, Number(d.minNights ?? 1)), 1);\n    return Math.max(base, delRango);\n  }, [habitacionRef?.minNights, dias, checkIn, nochesPedidas, hoy]);\n\n  const fijarLlegada = (iso: string) => {\n    setCheckIn(iso);\n    setCheckOut(addDaysIso(iso, Math.max(nochesPedidas, minNoches)));\n  };\n\n  const ajustarNoches = (delta: number) => {\n    const siguiente = Math.min(MAX_NOCHES, Math.max(minNoches, nochesPedidas + delta));\n    setNochesPedidas(siguiente);\n    if (checkIn) setCheckOut(addDaysIso(checkIn, siguiente));\n  };\n\n  const noches = checkIn && checkOut ? nightsBetween(checkIn, checkOut) : 0;\n  const listo = !!checkIn && !!checkOut && noches > 0;\n\n  /** Devuelve las fechas al buscador (que las lee de los parámetros al volver). */\n  const confirmar = () => {\n    router.replace({\n      pathname: '/lifebook-hotel',\n      params: {\n        ...(p.city ? { city: p.city } : {}),\n        ...(checkIn ? { checkIn } : {}),\n        ...(checkOut ? { checkOut } : {}),\n        guests: String(huespedes),\n        units: String(habitaciones),\n      },\n    } as never);\n  };\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={styles.volver}>\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.titulo, { color: colors.textPrimary }]}>Fechas de la estancia</Text>\n          <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={1}>\n            {p.city ? `${p.city} · ` : ''}{huespedes} huésped(es){habitaciones > 1 ? ` · ${habitaciones} habitaciones` : ''}\n          </Text>\n        </View>\n      </View>\n\n      {cargando ? (\n        <View style={styles.centro}>\n          <ActivityIndicator color={colors.primary} />\n          <Text style={[styles.sub, { color: colors.textSecondary }]}>Cargando precios…</Text>\n        </View>\n      ) : error ? (\n        <View style={[styles.aviso, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>{error}</Text>\n          <Pressable onPress={() => void cargar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n            <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 130, gap: espaciado.e12 }}>\n          {/* ── Forma de elegir: llegada + días, o entrada y salida ── */}\n          <View style={styles.modos}>\n            {(['noches', 'rango'] as const).map((m) => {\n              const activo = modo === m;\n              return (\n                <Pressable\n                  key={m}\n                  onPress={() => setModo(m)}\n                  accessibilityRole=\"radio\"\n                  accessibilityState={{ selected: activo }}\n                  accessibilityLabel={m === 'noches' ? 'Elegir llegada y número de días' : 'Elegir entrada y salida'}\n                  style={[styles.modoBtn, {\n                    borderColor: activo ? colors.primary : colors.border,\n                    backgroundColor: activo ? alpha(colors.primary, 0.08) : colors.surface,\n                  }]}\n                >\n                  <Text style={[styles.modoTxt, { color: activo ? colors.primary : colors.textSecondary }]}>\n                    {m === 'noches' ? 'Llegada + días' : 'Entrada y salida'}\n                  </Text>\n                </Pressable>\n              );\n            })}\n          </View>\n\n          {/* ── Días: contador que calcula la salida ── */}\n          <View style={[styles.diasFila, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <View style={{ flex: 1 }}>\n              <Text style={[styles.diasEtq, { color: colors.textPrimary }]}>\n                {nochesPedidas === 1 ? '1 noche' : `${nochesPedidas} noches`}\n              </Text>\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                {checkIn\n                  ? `${shortDate(checkIn, true)} → ${shortDate(addDaysIso(checkIn, nochesPedidas), true)}`\n                  : 'Elige el día de llegada abajo'}\n              </Text>\n            </View>\n            <View style={styles.diasBtns}>\n              <Pressable\n                onPress={() => ajustarNoches(-1)}\n                disabled={nochesPedidas <= minNoches}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Quitar una noche\"\n                accessibilityState={{ disabled: nochesPedidas <= minNoches }}\n                style={[styles.diasBtn, {\n                  borderColor: colors.border, backgroundColor: colors.surface,\n                  opacity: nochesPedidas <= minNoches ? 0.35 : 1,\n                }]}\n              >\n                <Text style={[styles.diasBtnTxt, { color: colors.textPrimary }]}>−</Text>\n              </Pressable>\n              <Text style={[styles.diasVal, { color: colors.textPrimary }]}>{nochesPedidas}</Text>\n              <Pressable\n                onPress={() => ajustarNoches(1)}\n                disabled={nochesPedidas >= MAX_NOCHES}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Añadir una noche\"\n                accessibilityState={{ disabled: nochesPedidas >= MAX_NOCHES }}\n                style={[styles.diasBtn, {\n                  borderColor: colors.border, backgroundColor: colors.surface,\n                  opacity: nochesPedidas >= MAX_NOCHES ? 0.35 : 1,\n                }]}\n              >\n                <Text style={[styles.diasBtnTxt, { color: colors.textPrimary }]}>+</Text>\n              </Pressable>\n            </View>\n          </View>\n\n          {minNoches > 1 ? (\n            <Text style={[styles.sub, { color: colors.textSecondary }]}>\n              Estas fechas piden un mínimo de {minNoches} noches.\n            </Text>\n          ) : null}\n\n          {/* ── El calendario, con la pantalla para él solo ── */}\n          <CalendarPicker\n            days={dias}\n            checkIn={checkIn}\n            checkOut={checkOut}\n            arrivalOnly={modo === 'noches'}\n            nightsCount={modo === 'noches' ? nochesPedidas : undefined}\n            onChange={(a, b) => {\n              if (modo === 'noches') {\n                if (a) fijarLlegada(a);\n                return;\n              }\n              setCheckIn(a);\n              setCheckOut(b);\n            }}\n            units={habitaciones}\n            minNights={minNoches}\n            maxNights={MAX_NOCHES}\n          />\n\n          <Text style={[styles.sub, { color: colors.textSecondary }]}>\n            {habitacionRef\n              ? `Precios reales de «${habitacionRef.name}». Cada hotel puede tener su propio calendario.`\n              : 'Elige un destino con alojamiento para ver precios.'}\n          </Text>\n        </ScrollView>\n      )}\n\n      {/* ── Barra fija: resumen y confirmación (el botón nunca hay que buscarlo) ── */}\n      <View style={[styles.pie, { paddingBottom: insets.bottom + 10, borderTopColor: colors.border, backgroundColor: colors.card }]}>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.pieEtq, { color: colors.textSecondary }]}>\n            {listo ? `${noches} noche(s)` : 'Elige las fechas'}\n          </Text>\n          <Text style={[styles.pieTotal, { color: colors.textPrimary }]}>\n            {listo && checkIn && checkOut ? `${shortDate(checkIn)} → ${shortDate(checkOut, true)}` : '—'}\n          </Text>\n        </View>\n        <Pressable\n          onPress={confirmar}\n          disabled={!listo}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Confirmar las fechas\"\n          accessibilityState={{ disabled: !listo }}\n          style={[styles.confirmar, { backgroundColor: listo ? colors.primary : colors.border }]}\n        >\n          <Text style={styles.confirmarTxt}>Usar estas fechas</Text>\n        </Pressable>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  barra: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1 },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  titulo: { fontSize: 16.5, fontWeight: '800' },\n  sub: { fontSize: tipografia.caption },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e8 },\n  aviso: { margin: espaciado.e14, borderWidth: 1, borderRadius: 14, padding: espaciado.e12, gap: espaciado.e6 },\n  enlace: { fontSize: tipografia.caption, fontWeight: '700' },\n  modos: { flexDirection: 'row', gap: espaciado.e8 },\n  modoBtn: { flex: 1, borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e9, alignItems: 'center' },\n  modoTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  diasFila: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderWidth: 1, borderRadius: 14, padding: espaciado.e12 },\n  diasEtq: { fontSize: 14.5, fontWeight: '800' },\n  diasBtns: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 },\n  diasBtn: { width: 38, height: 38, borderWidth: 1, borderRadius: 11, alignItems: 'center', justifyContent: 'center' },\n  diasBtnTxt: { fontSize: tipografia.title, fontWeight: '800', lineHeight: 22 },\n  diasVal: { fontSize: 17, fontWeight: '800', minWidth: 26, textAlign: 'center' },\n  pie: {\n    position: 'absolute', left: 0, right: 0, bottom: 0, borderTopWidth: 1,\n    paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10, flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n  },\n  pieEtq: { fontSize: tipografia.caption },\n  pieTotal: { fontSize: 15, fontWeight: '800' },\n  confirmar: { minWidth: 170, height: altura.campo, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e14 },\n  confirmarTxt: { color: brand.white, fontSize: 15, fontWeight: '800' },\n});\n","/**\n * lifebook-hotel-gestion — LA PARTE DE GESTIÓN DEL PANEL DEL HOTELERO.\n *\n * ── DECISIÓN DE PRODUCTO: el panel del comerciante son DOS PARTES ──────────────\n *\n * El dueño lo decidió así el 2026-09-12, y vale igual para el hotel y para el\n * restaurante que viene detrás. La regla que separa una parte de la otra:\n *\n *   · **HOY**      → lo que CADUCA: personas esperando en recepción, dinero por cobrar,\n *                    mensajes sin responder. Si tiene hora límite, va aquí.\n *                    (`lifebook-hotel-panel`)\n *   · **GESTIÓN**  → lo que SE CONFIGURA: precios, fotos, textos, horarios, catálogo.\n *                    Si se toca de vez en cuando, va aquí. (esta pantalla)\n *\n * Por qué separarlas: Meituan tiene dos apps (cliente y hotelero/PMS) porque el trabajo del\n * comerciante es de dos naturalezas distintas —atender y configurar—, y mezclarlas en una\n * sola pantalla hace que lo urgente se pierda entre lo que puede esperar. Aquí se mantiene\n * una sola app (con pocos comercios es lo eficiente) pero **dos partes claras**, cada una con\n * su entrada.\n *\n * Y lo que hace útil esta pantalla no es la lista de enlaces: es que **dice lo que falta**.\n * Un hotelero que no ve «tienes 3 habitaciones sin fotos» no lo arregla nunca, y una\n * habitación sin fotos casi no se reserva (documento de diseño Meituan §J.3: mínimo 3 fotos\n * reales; §C.2: la foto es lo que decide el clic en la lista).\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport {\n  ArrowLeft, BedDouble, CalendarDays, ChevronRight, ClipboardList, Settings, Store, TriangleAlert,\n} from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { hotelApi, type HotelProfile, type HotelRoom } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { xaf } from '../utils/datetime';\n\nexport default function GestionHotelScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\n/** Un pendiente: qué falta, dónde se arregla y qué se pierde si no se hace. */\ninterface Pendiente {\n  clave: string;\n  texto: string;\n  porque: string;\n  ir: () => void;\n}\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  const [hotel, setHotel] = useState<HotelProfile | null>(null);\n  const [rooms, setRooms] = useState<HotelRoom[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setCargando(true);\n    try {\n      const out = await hotelApi.myHotel();\n      setHotel(out.hotel);\n      setRooms(out.rooms ?? []);\n      setError(null);\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar la gestión.');\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const publicadas = rooms.filter((r) => r.isActive && r.productStatus === 'active').length;\n  const sinFotos = rooms.filter((r) => (r.images?.length ?? 0) < 3);\n  const sinDescripcion = rooms.filter((r) => !(r.description ?? '').trim());\n  const sinSuperficie = rooms.filter((r) => !r.sizeM2);\n\n  /** Lo que falta, ordenado por lo que más cuesta en reservas perdidas. */\n  const pendientes = useMemo((): Pendiente[] => {\n    const lista: Pendiente[] = [];\n    if (!rooms.length) {\n      lista.push({\n        clave: 'sin-habitaciones', texto: 'Todavía no has creado ninguna habitación',\n        porque: 'Sin habitaciones no hay nada que reservar.',\n        ir: () => router.push('/lifebook-hotel-habitacion' as never),\n      });\n    }\n    if (sinFotos.length) {\n      lista.push({\n        clave: 'fotos', texto: `${sinFotos.length} habitación(es) con menos de 3 fotos`,\n        porque: 'La foto es lo que decide el clic en la lista de resultados.',\n        ir: () => router.push('/lifebook-hotel-habitaciones' as never),\n      });\n    }\n    if (sinDescripcion.length) {\n      lista.push({\n        clave: 'desc', texto: `${sinDescripcion.length} habitación(es) sin descripción`,\n        porque: 'El huésped decide con lo que le cuentes.',\n        ir: () => router.push('/lifebook-hotel-habitaciones' as never),\n      });\n    }\n    if (sinSuperficie.length) {\n      lista.push({\n        clave: 'm2', texto: `${sinSuperficie.length} habitación(es) sin superficie`,\n        porque: 'Es dato obligatorio de la ficha y el huésped lo compara.',\n        ir: () => router.push('/lifebook-hotel-habitaciones' as never),\n      });\n    }\n    if (!hotel?.stars) {\n      lista.push({\n        clave: 'estrellas', texto: 'La ficha no tiene categoría (estrellas)',\n        porque: 'Es lo primero que filtra el huésped al buscar.',\n        ir: () => router.push('/lifebook-hotel-perfil' as never),\n      });\n    }\n    if (!(hotel?.amenities?.length)) {\n      lista.push({\n        clave: 'servicios', texto: 'No has declarado ningún servicio del hotel',\n        porque: 'Wi-Fi, desayuno o aparcamiento son motivos de elección.',\n        ir: () => router.push('/lifebook-hotel-perfil' as never),\n      });\n    }\n    if (!hotel?.houseRules) {\n      lista.push({\n        clave: 'normas', texto: 'Sin normas de la casa',\n        porque: 'Unas normas claras evitan discusiones en recepción.',\n        ir: () => router.push('/lifebook-hotel-perfil' as never),\n      });\n    }\n    if (!hotel?.cancellationPolicy) {\n      lista.push({\n        clave: 'cancelacion', texto: 'Sin política de cancelación escrita',\n        porque: 'Es lo que más rebaja la duda antes de pagar.',\n        ir: () => router.push('/lifebook-hotel-perfil' as never),\n      });\n    }\n    return lista;\n  }, [rooms.length, sinFotos.length, sinDescripcion.length, sinSuperficie.length, hotel?.stars,\n      hotel?.amenities?.length, hotel?.houseRules, hotel?.cancellationPolicy, router]);\n\n  if (cargando) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.cabecera, { paddingTop: insets.top + 8, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" hitSlop={12} style={styles.volver}>\n          <ArrowLeft size={21} color={colors.textPrimary} />\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900' }}>Gestión</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }} numberOfLines={2}>\n            {hotel?.name ?? 'Tu alojamiento'} · lo que se configura, no lo del día\n          </Text>\n        </View>\n      </View>\n\n      {error ? (\n        <View style={{ padding: espaciado.e16 }}>\n          <Text style={{ color: colors.textSecondary, marginBottom: espaciado.e12 }}>{error}</Text>\n          <GhostButton title=\"Reintentar\" onPress={() => void cargar()} />\n        </View>\n      ) : (\n        <ScrollView\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }}\n          refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => { setRefrescando(true); void cargar(true); }} tintColor={colors.primary} />}\n        >\n          {/* Resumen: lo primero, cuánto hay y cuánto está listo. */}\n          <View style={[styles.resumen, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: 15.5, fontWeight: '900' }}>\n              {rooms.length} tipo(s) de habitación\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4, lineHeight: 18 }}>\n              {publicadas} se puede(n) reservar ya\n              {rooms.length - publicadas > 0 ? ` · ${rooms.length - publicadas} todavía no` : ''}\n              {rooms.length ? ` · desde ${xaf(Math.min(...rooms.map((r) => r.basePriceXaf)))} por noche` : ''}\n            </Text>\n          </View>\n\n          {/* ── LO QUE FALTA ── la razón de ser de esta pantalla */}\n          {pendientes.length ? (\n            <View style={{ marginTop: espaciado.e18 }}>\n              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e8 }}>\n                <TriangleAlert size={16} color={colors.secondary} />\n                <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginLeft: espaciado.e7 }}>\n                  Te falta por completar ({pendientes.length})\n                </Text>\n              </View>\n              {pendientes.map((p) => (\n                <Pressable\n                  key={p.clave}\n                  onPress={p.ir}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`${p.texto}. ${p.porque}`}\n                  style={[styles.pendiente, { borderColor: alpha(colors.secondary, 0.35), backgroundColor: alpha(colors.secondary, 0.06) }]}\n                >\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{p.texto}</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3, lineHeight: 17 }}>\n                      {p.porque}\n                    </Text>\n                  </View>\n                  <ChevronRight size={18} color={colors.secondary} />\n                </Pressable>\n              ))}\n            </View>\n          ) : (\n            <View style={[styles.resumen, { borderColor: alpha(colors.success, 0.35), backgroundColor: alpha(colors.success, 0.07), marginTop: espaciado.e18 }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n                ✓ Tu ficha está completa\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>\n                Habitaciones con fotos, descripción y datos; hotel con categoría, servicios y normas.\n              </Text>\n            </View>\n          )}\n\n          {/* ── A DÓNDE SE VA DESDE AQUÍ ── */}\n          <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginTop: espaciado.e22, marginBottom: espaciado.e8 }}>\n            Configurar\n          </Text>\n\n          <Fila\n            icono={<BedDouble size={18} color={colors.primary} />}\n            titulo=\"Habitaciones\"\n            detalle={rooms.length\n              ? `${rooms.length} tipo(s) · ${publicadas} a la venta · fotos, camas, precios y señal`\n              : 'Crea la primera: nombre, camas, precio y fotos'}\n            onPress={() => router.push('/lifebook-hotel-habitaciones' as never)}\n          />\n          <Fila\n            icono={<CalendarDays size={18} color={colors.primary} />}\n            titulo=\"Precios y fechas\"\n            detalle=\"Precio de temporada, estancia mínima y cerrar fechas, por habitación\"\n            onPress={() => router.push('/lifebook-hotel-habitaciones' as never)}\n          />\n          <Fila\n            icono={<ClipboardList size={18} color={colors.primary} />}\n            titulo=\"Ficha del hotel\"\n            detalle=\"Categoría, horario de entrada y salida, servicios, normas y formas de pago\"\n            onPress={() => router.push('/lifebook-hotel-perfil' as never)}\n          />\n          <Fila\n            icono={<Store size={18} color={colors.primary} />}\n            titulo=\"Ajustes de la tienda\"\n            detalle=\"Nombre, dirección, logo y portada (son de la tienda, no del alojamiento)\"\n            onPress={() => router.push('/lifebook-merchant-settings' as never)}\n          />\n          <Fila\n            icono={<Settings size={18} color={colors.primary} />}\n            titulo=\"Mis publicaciones\"\n            detalle=\"Todo lo que tienes en el catálogo de Life Book, con su estado\"\n            onPress={() => router.push('/lifebook-merchant-products' as never)}\n          />\n\n          {/* Puente a la otra parte: no son dos apps, son dos partes de lo mismo. */}\n          <View style={{ marginTop: espaciado.e22 }}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e8 }}>\n              Lo del día —llegadas, salidas, cobros y reservas— está en la otra parte, «Hoy».\n            </Text>\n            <GhostButton title=\"Ir a «Hoy» (recepción)\" onPress={() => router.push('/lifebook-hotel-panel' as never)} />\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\n/** Fila de acceso: icono, título, detalle y flecha. Objetivo táctil de 56 px. */\nfunction Fila({ icono, titulo, detalle, onPress }: {\n  icono: React.ReactNode; titulo: string; detalle: string; onPress: () => void;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`${titulo}. ${detalle}`}\n      style={[styles.fila, { borderColor: colors.border, backgroundColor: colors.card }]}\n    >\n      <View style={[styles.filaIcono, { backgroundColor: alpha(colors.primary, 0.12) }]}>{icono}</View>\n      <View style={{ flex: 1 }}>\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{titulo}</Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 17 }}>{detalle}</Text>\n      </View>\n      <ChevronRight size={18} color={colors.textSecondary} />\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e6,\n    paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  volver: { width: 44, height: 44, alignItems: 'center', justifyContent: 'center' },\n  resumen: { borderWidth: 1, borderRadius: 14, padding: espaciado.e13 },\n  pendiente: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    borderWidth: 1, borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e8, minHeight: 56,\n  },\n  fila: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e11,\n    borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginBottom: espaciado.e8, minHeight: 56,\n  },\n  filaIcono: { width: 34, height: 34, borderRadius: 11, alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * lifebook-hotel-habitacion — ALTA Y EDICIÓN DE UN TIPO DE HABITACIÓN (con fotos).\n *\n * Es la pantalla que faltaba para que el hotelero no dependa de nadie: el servidor sabía\n * crear y editar tipos de habitación desde la Parte 42, pero **ninguna pantalla lo llamaba**.\n *\n * Decisiones que no son obvias y por qué:\n *\n *   · **Las fotos van por el camino de la Parte 41** (`uploadImageReal`), no por el subidor\n *     antiguo de la app. El antiguo guarda en `covers/…` y no registra la subida en\n *     `media_uploads`, así que el servidor del hotel la rechaza con `IMAGE_INVALID`: la\n *     habitación no se podría guardar con fotos. Comprobado contra el servidor.\n *   · **Los números se escriben como texto y se convierten al guardar.** Si se convierten al\n *     escribir, un campo a medio borrar se vuelve `NaN` y el servidor recibe basura.\n *   · **Se avisa de la moderación**: una habitación nace `pending` y **no se puede reservar**\n *     hasta que la administración la apruebe. Si eso no se dice, el hotelero cree que ya\n *     está a la venta y no entiende por qué no le llegan reservas.\n *   · **Al editar se manda solo lo que cambia** (`updateRoom` es parcial) y, si se tocan las\n *     fotos, la lista COMPLETA: el servidor reemplaza, no mezcla.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Switch, Text, View,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { hotelApi, type HotelRoom } from '../api/hotel';\nimport { uploadImageReal } from '../api/mediaReal';\nimport { ApiError } from '../api/httpClient';\nimport { pickImagesFromLibrary } from '../core/pickImage';\nimport { xaf } from '../utils/datetime';\n\n/** Los servicios que el servidor acepta (mismos identificadores, en castellano). */\nconst SERVICIOS: { id: string; label: string }[] = [\n  { id: 'wifi', label: 'Wi-Fi' }, { id: 'aire', label: 'Aire acondicionado' },\n  { id: 'tv', label: 'Televisión' }, { id: 'nevera', label: 'Nevera' },\n  { id: 'agua_caliente', label: 'Agua caliente' }, { id: 'desayuno', label: 'Desayuno' },\n  { id: 'cocina', label: 'Cocina' }, { id: 'terraza', label: 'Terraza' },\n  { id: 'caja_fuerte', label: 'Caja fuerte' }, { id: 'adaptado', label: 'Adaptado' },\n];\n\nconst TIPOS_CAMA = ['individual', 'doble', 'matrimonial', 'queen', 'king', 'litera', 'sofa_cama'];\nconst ETIQUETA_CAMA: Record<string, string> = {\n  individual: 'Individual', doble: 'Doble', matrimonial: 'Matrimonial',\n  queen: 'Queen', king: 'King', litera: 'Litera', sofa_cama: 'Sofá cama',\n};\n\nconst MAX_FOTOS = 12;\n\nexport default function HabitacionScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const p = useLocalSearchParams<{ id?: string }>();\n  const editando = !!p.id;\n\n  const [cargando, setCargando] = useState(editando);\n  const [error, setError] = useState<string | null>(null);\n  const [guardando, setGuardando] = useState(false);\n  const [subiendo, setSubiendo] = useState(false);\n\n  // Campos de texto (los números también: se convierten al guardar)\n  const [name, setName] = useState('');\n  const [description, setDescription] = useState('');\n  const [capacity, setCapacity] = useState('2');\n  const [totalUnits, setTotalUnits] = useState('1');\n  const [sizeM2, setSizeM2] = useState('');\n  const [basePriceXaf, setBasePriceXaf] = useState('');\n  const [weekendPriceXaf, setWeekendPriceXaf] = useState('');\n  const [cleaningFeeXaf, setCleaningFeeXaf] = useState('0');\n  const [taxesXaf, setTaxesXaf] = useState('0');\n  const [minNights, setMinNights] = useState('1');\n  const [maxNights, setMaxNights] = useState('30');\n  const [depositPercent, setDepositPercent] = useState('30');\n  const [holdMinutes, setHoldMinutes] = useState('20');\n  const [confirmationHours, setConfirmationHours] = useState('24');\n  const [cancellationHours, setCancellationHours] = useState('48');\n  const [isActive, setIsActive] = useState(true);\n  const [beds, setBeds] = useState<{ kind: string; count: number }[]>([{ kind: 'doble', count: 1 }]);\n  const [amenities, setAmenities] = useState<string[]>([]);\n  const [fotos, setFotos] = useState<string[]>([]);\n\n  const cargar = useCallback(async () => {\n    if (!editando) return;\n    setCargando(true);\n    try {\n      // Se lee de `my/room-types` (no de la ficha pública): así una habitación todavía\n      // en revisión o apagada también se puede editar, que es justo cuando hace falta.\n      const out = await hotelApi.myRooms();\n      const r: HotelRoom | undefined = (out.rooms ?? []).find((x) => x.id === p.id);\n      if (!r) { setError('Esa habitación no está entre las tuyas.'); return; }\n      setName(r.name);\n      setDescription(r.description ?? '');\n      setCapacity(String(r.capacity));\n      setTotalUnits(String(r.totalUnits));\n      setSizeM2(r.sizeM2 ? String(r.sizeM2) : '');\n      setBasePriceXaf(String(r.basePriceXaf));\n      setWeekendPriceXaf(r.weekendPriceXaf ? String(r.weekendPriceXaf) : '');\n      setCleaningFeeXaf(String(r.cleaningFeeXaf ?? 0));\n      setTaxesXaf(String(r.taxesXaf ?? 0));\n      setMinNights(String(r.minNights));\n      setMaxNights(String(r.maxNights));\n      setDepositPercent(String(r.depositPercent));\n      setHoldMinutes(String(r.holdMinutes));\n      setConfirmationHours(String(r.confirmationHours));\n      setCancellationHours(String(r.cancellationHours));\n      setIsActive(!!r.isActive);\n      setBeds(r.beds?.length ? r.beds : [{ kind: 'doble', count: 1 }]);\n      setAmenities(r.amenities ?? []);\n      setFotos((r.images ?? []).map((im) => im.url).filter(Boolean));\n      setError(null);\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar la habitación.');\n    } finally {\n      setCargando(false);\n    }\n  }, [editando, p.id]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const anadirFotos = async () => {\n    if (subiendo) return;\n    const hueco = MAX_FOTOS - fotos.length;\n    if (hueco <= 0) { Alert.alert('Fotos', `El máximo es ${MAX_FOTOS} fotos por habitación.`); return; }\n    try {\n      const elegidas = await pickImagesFromLibrary(hueco);\n      if (!elegidas.length) return;\n      setSubiendo(true);\n      const subidas: string[] = [];\n      for (const img of elegidas) {\n        // Una a una: si una falla, las demás quedan subidas y se dice cuál falló.\n        try {\n          subidas.push(await uploadImageReal({ uri: img.uri, mimeType: 'image/jpeg' }));\n        } catch (e) {\n          Alert.alert('No se pudo subir una foto', e instanceof ApiError ? e.message : 'Inténtalo otra vez.');\n        }\n      }\n      if (subidas.length) setFotos((prev) => [...prev, ...subidas].slice(0, MAX_FOTOS));\n    } catch (e) {\n      Alert.alert('Fotos', e instanceof Error ? e.message : 'No se pudieron elegir las fotos');\n    } finally {\n      setSubiendo(false);\n    }\n  };\n\n  const quitarFoto = (url: string) => setFotos((prev) => prev.filter((u) => u !== url));\n\n  const num = (v: string): number | null => {\n    const n = Number(String(v).replace(/[^\\d.-]/g, ''));\n    return Number.isFinite(n) ? n : null;\n  };\n\n  /** Comprobaciones en el cliente, con el mismo límite que el servidor. */\n  const problema = useMemo((): string | null => {\n    const n = name.trim();\n    if (n.length < 3) return 'El nombre necesita al menos 3 letras.';\n    /*\n      Regla de cumplimiento de la plataforma (documento de diseño, §J.3): está prohibido que el\n      nombre del tipo de habitación lleve publicidad, teléfonos o enlaces. Se comprueba aquí\n      para que el hotelero no publique algo que le van a rechazar en la revisión.\n      Ojo con el patrón: pide 8 dígitos seguidos (o separados por espacios/guiones) para NO\n      confundirse con un número de habitación («Habitación doble 094203» es válido).\n    */\n    if (/https?:\\/\\/|www\\.|\\.com\\b|@\\w+\\./i.test(n)) return 'El nombre no puede llevar enlaces ni correos.';\n    if (/\\+?\\d[\\d\\s.-]{6,}\\d/.test(n)) return 'El nombre no puede llevar un teléfono: la plataforma lo rechaza (va en la ficha del hotel).';\n    const cap = num(capacity); if (cap === null || cap < 1 || cap > 30) return 'La capacidad tiene que ser entre 1 y 30 personas.';\n    const u = num(totalUnits); if (u === null || u < 1 || u > 200) return 'Tiene que haber al menos 1 habitación de este tipo (máximo 200).';\n    const base = num(basePriceXaf); if (base === null || base < 1) return 'Indica el precio por noche en XAF.';\n    const wd = weekendPriceXaf.trim() ? num(weekendPriceXaf) : null;\n    if (weekendPriceXaf.trim() && (wd === null || wd < 1)) return 'El precio de fin de semana no es válido (o déjalo vacío).';\n    const mn = num(minNights); if (mn === null || mn < 1 || mn > 90) return 'La estancia mínima tiene que ser entre 1 y 90 noches.';\n    const mx = num(maxNights); if (mx === null || mx < 1 || mx > 365) return 'La estancia máxima tiene que ser entre 1 y 365 noches.';\n    if (mx < mn) return 'La estancia máxima no puede ser menor que la mínima.';\n    const dep = num(depositPercent); if (dep === null || dep < 0 || dep > 100) return 'La señal tiene que estar entre 0 y 100 %.';\n    const hold = num(holdMinutes); if (hold === null || hold < 5 || hold > 120) return 'La retención tiene que ser entre 5 y 120 minutos.';\n    const conf = num(confirmationHours); if (conf === null || conf < 1 || conf > 168) return 'Las horas para confirmar tienen que ser entre 1 y 168.';\n    const canc = num(cancellationHours); if (canc === null || canc < 0 || canc > 720) return 'Las horas de cancelación gratis tienen que ser entre 0 y 720.';\n    if (!beds.length || beds.some((b) => !b.kind || b.count < 1 || b.count > 20)) return 'Cada línea de camas necesita un tipo y entre 1 y 20.';\n    const limp = num(cleaningFeeXaf); if (limp === null || limp < 0) return 'La limpieza no puede ser negativa.';\n    const tax = num(taxesXaf); if (tax === null || tax < 0) return 'Las tasas no pueden ser negativas.';\n    if (sizeM2.trim()) { const s = num(sizeM2); if (s === null || s < 4 || s > 2000) return 'La superficie tiene que ser entre 4 y 2000 m².'; }\n    return null;\n  }, [name, capacity, totalUnits, basePriceXaf, weekendPriceXaf, minNights, maxNights,\n      depositPercent, holdMinutes, confirmationHours, cancellationHours, beds, cleaningFeeXaf, taxesXaf, sizeM2]);\n\n  const guardar = async () => {\n    const fallo = problema;\n    if (fallo) { Alert.alert('Revisa los datos', fallo); return; }\n    setGuardando(true);\n    try {\n      const dto: Record<string, unknown> = {\n        name: name.trim(),\n        description: description.trim() || undefined,\n        capacity: num(capacity), totalUnits: num(totalUnits),\n        sizeM2: sizeM2.trim() ? num(sizeM2) : null,\n        basePriceXaf: num(basePriceXaf),\n        weekendPriceXaf: weekendPriceXaf.trim() ? num(weekendPriceXaf) : null,\n        cleaningFeeXaf: num(cleaningFeeXaf), taxesXaf: num(taxesXaf),\n        minNights: num(minNights), maxNights: num(maxNights),\n        depositPercent: num(depositPercent), holdMinutes: num(holdMinutes),\n        confirmationHours: num(confirmationHours), cancellationHours: num(cancellationHours),\n        isActive,\n        beds: beds.map((b) => ({ kind: b.kind, count: b.count })),\n        amenities,\n        images: fotos,\n      };\n      if (editando) {\n        await hotelApi.updateRoom(String(p.id), dto);\n        Alert.alert('Guardado', 'Los cambios ya están en la ficha.', [\n          { text: 'Vale', onPress: () => router.back() },\n        ]);\n      } else {\n        const out = await hotelApi.createRoom(dto);\n        const pendiente = out.room?.productStatus !== 'active';\n        Alert.alert(\n          'Habitación creada',\n          pendiente\n            ? 'Queda **en revisión**: la administración tiene que aprobarla antes de que se pueda reservar. Mientras tanto puedes preparar sus precios y cerrar fechas.'\n            : 'Ya está publicada.',\n          [{ text: 'Vale', onPress: () => router.back() }],\n        );\n      }\n    } catch (e) {\n      Alert.alert('No se pudo guardar', e instanceof ApiError ? e.message : 'Inténtalo otra vez.');\n    } finally {\n      setGuardando(false);\n    }\n  };\n\n  if (cargando) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.cabecera, { paddingTop: insets.top + 8, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" hitSlop={10} style={styles.volver}>\n          <Text style={{ color: colors.textPrimary, fontSize: 30, lineHeight: 32 }}>‹</Text>\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1 }}>\n          {editando ? 'Editar habitación' : 'Nueva habitación'}\n        </Text>\n      </View>\n\n      {error ? (\n        <View style={{ padding: espaciado.e16 }}>\n          <Text style={{ color: colors.textSecondary, marginBottom: espaciado.e12 }}>{error}</Text>\n          <GhostButton title=\"Volver\" onPress={() => router.back()} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }} keyboardShouldPersistTaps=\"handled\">\n\n          <Bloque titulo=\"Lo que se vende\" hint=\"El nombre y lo que cabe. Es lo que verá el huésped en la lista.\">\n            <FormField label=\"Nombre\" value={name} onChangeText={setName} placeholder=\"Doble con aire\" maxLength={120} />\n            <Contador actual={name.length} max={120} />\n            <View style={{ height: 10 }} />\n            <FormField\n              label=\"Descripción (opcional)\" value={description} onChangeText={setDescription}\n              placeholder=\"Dos camas, aire acondicionado, vistas al mar…\" maxLength={2000} multiline\n            />\n            {/* El servidor guarda 2000 caracteres y el resto lo tira sin avisar. */}\n            <Contador actual={description.length} max={2000} />\n            <View style={{ height: 10 }} />\n            <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Capacidad (personas)\" value={capacity} onChangeText={setCapacity} keyboardType=\"number-pad\" placeholder=\"2\" />\n              </View>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Superficie (m²)\" value={sizeM2} onChangeText={setSizeM2} keyboardType=\"number-pad\" placeholder=\"18\" />\n              </View>\n            </View>\n          </Bloque>\n\n          <Bloque titulo=\"Camas\" hint=\"Se pueden combinar: una doble y una litera, por ejemplo.\">\n            {beds.map((b, i) => (\n              <View key={`${b.kind}-${i}`} style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginBottom: espaciado.e8 }}>\n                <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flex: 1 }}>\n                  <View style={{ flexDirection: 'row', gap: espaciado.e6 }}>\n                    {TIPOS_CAMA.map((t) => {\n                      const on = b.kind === t;\n                      return (\n                        <Pressable\n                          key={t}\n                          onPress={() => setBeds((prev) => prev.map((x, j) => (j === i ? { ...x, kind: t } : x)))}\n                          style={[styles.chip, { backgroundColor: on ? colors.primary : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                        >\n                          <Text style={{ color: on ? brand.white : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                            {ETIQUETA_CAMA[t] ?? t}\n                          </Text>\n                        </Pressable>\n                      );\n                    })}\n                  </View>\n                </ScrollView>\n                <Pressable\n                  onPress={() => setBeds((prev) => prev.map((x, j) => (j === i ? { ...x, count: Math.max(1, x.count - 1) } : x)))}\n                  style={[styles.paso, { borderColor: colors.border }]}\n                ><Text style={{ color: colors.textPrimary, fontSize: 18, fontWeight: '900' }}>−</Text></Pressable>\n                <Text style={{ color: colors.textPrimary, fontWeight: '900', minWidth: 16, textAlign: 'center' }}>{b.count}</Text>\n                <Pressable\n                  onPress={() => setBeds((prev) => prev.map((x, j) => (j === i ? { ...x, count: Math.min(20, x.count + 1) } : x)))}\n                  style={[styles.paso, { borderColor: colors.border }]}\n                ><Text style={{ color: colors.textPrimary, fontSize: 18, fontWeight: '900' }}>+</Text></Pressable>\n                {beds.length > 1 ? (\n                  <Pressable onPress={() => setBeds((prev) => prev.filter((_, j) => j !== i))} hitSlop={8} accessibilityLabel=\"Quitar esta línea de camas\">\n                    <X size={18} color={colors.textSecondary} />\n                  </Pressable>\n                ) : null}\n              </View>\n            ))}\n            <GhostButton title=\"Añadir otra cama\" onPress={() => setBeds((prev) => [...prev, { kind: 'individual', count: 1 }])} />\n          </Bloque>\n\n          <Bloque titulo=\"Precio y dinero\" hint=\"El precio por noche es por habitación, no por persona. La señal la paga el huésped al reservar.\">\n            <FormField label=\"Precio por noche (XAF)\" value={basePriceXaf} onChangeText={setBasePriceXaf} keyboardType=\"number-pad\" placeholder=\"25000\" />\n            <View style={{ height: 10 }} />\n            <FormField\n              label=\"Precio de fin de semana (opcional)\" value={weekendPriceXaf} onChangeText={setWeekendPriceXaf}\n              keyboardType=\"number-pad\" placeholder=\"Se usa los viernes y sábados\"\n            />\n            <View style={{ height: 10 }} />\n            <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Limpieza (XAF)\" value={cleaningFeeXaf} onChangeText={setCleaningFeeXaf} keyboardType=\"number-pad\" />\n              </View>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Tasas (XAF)\" value={taxesXaf} onChangeText={setTaxesXaf} keyboardType=\"number-pad\" />\n              </View>\n            </View>\n            <View style={{ height: 10 }} />\n            <FormField\n              label=\"Señal (%)\" value={depositPercent} onChangeText={setDepositPercent} keyboardType=\"number-pad\"\n              placeholder=\"30\"\n            />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e5, marginLeft: espaciado.e4 }}>\n              Es la parte que se paga al reservar. Con 0, la reserva se paga entera al llegar.\n            </Text>\n          </Bloque>\n\n          <Bloque titulo=\"Estancia y plazos\" hint=\"Cuántas noches como mínimo, y cuánto tiempo se guarda una reserva sin pagar.\">\n            <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Mínimo de noches\" value={minNights} onChangeText={setMinNights} keyboardType=\"number-pad\" />\n              </View>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Máximo de noches\" value={maxNights} onChangeText={setMaxNights} keyboardType=\"number-pad\" />\n              </View>\n            </View>\n            <View style={{ height: 10 }} />\n            <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Retención (min)\" value={holdMinutes} onChangeText={setHoldMinutes} keyboardType=\"number-pad\" />\n              </View>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Horas para confirmar\" value={confirmationHours} onChangeText={setConfirmationHours} keyboardType=\"number-pad\" />\n              </View>\n            </View>\n            <View style={{ height: 10 }} />\n            <FormField\n              label=\"Horas de cancelación gratis\" value={cancellationHours} onChangeText={setCancellationHours}\n              keyboardType=\"number-pad\"\n            />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e5, marginLeft: espaciado.e4 }}>\n              Hasta cuántas horas antes de la entrada el huésped puede cancelar sin coste. Lo calcula el servidor.\n            </Text>\n          </Bloque>\n\n          <Bloque titulo=\"Fotos\" hint=\"La primera es la portada. Una habitación sin fotos no se elige.\">\n            {/*\n              La plataforma pide un MÍNIMO DE 3 FOTOS REALES para dar de alta un tipo de\n              habitación desde la app (documento de diseño, §J.3), y en la lista de resultados la\n              foto es lo que decide el clic (§C.2). No se bloquea el guardado —hay habitaciones\n              ya creadas con menos— pero se dice claramente cuántas faltan.\n            */}\n            {fotos.length < 3 ? (\n              <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '800', marginBottom: espaciado.e10, lineHeight: 18 }}>\n                ⚠ {fotos.length === 0\n                  ? 'Sin fotos: una habitación sin fotos casi no se reserva.'\n                  : `Con ${fotos.length} foto(s) se nota la falta: lo recomendado son 3 o más.`}\n                {' '}Mejor la fachada o la habitación entera, con luz.\n              </Text>\n            ) : (\n              <Text style={{ color: colors.success, fontSize: tipografia.caption, fontWeight: '800', marginBottom: espaciado.e10 }}>\n                ✓ {fotos.length} fotos: la primera es la que se ve en la lista de resultados.\n              </Text>\n            )}\n            {fotos.length ? (\n              <View style={styles.rejilla}>\n                {fotos.map((url, i) => (\n                  <View key={url} style={styles.miniatura}>\n                    <Image source={{ uri: url }} style={styles.foto} contentFit=\"cover\" transition={0} />\n                    {i === 0 ? (\n                      <View style={[styles.portada, { backgroundColor: colors.primary }]}>\n                        <Text style={{ color: brand.white, fontSize: 9, fontWeight: '900' }}>PORTADA</Text>\n                      </View>\n                    ) : null}\n                    <Pressable onPress={() => quitarFoto(url)} style={styles.quitarFoto} accessibilityLabel=\"Quitar esta foto\" hitSlop={10}>\n                      <X size={15} color={brand.white} />\n                    </Pressable>\n                  </View>\n                ))}\n              </View>\n            ) : null}\n            <GhostButton\n              title={subiendo ? 'Subiendo…' : `Añadir fotos (${fotos.length}/${MAX_FOTOS})`}\n              onPress={() => void anadirFotos()}\n              disabled={subiendo}\n            />\n          </Bloque>\n\n          <Bloque titulo=\"Servicios de la habitación\" hint=\"Opcional. Marca lo que tiene de verdad.\">\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 }}>\n              {SERVICIOS.map((s) => {\n                const on = amenities.includes(s.id);\n                return (\n                  <Pressable\n                    key={s.id}\n                    onPress={() => setAmenities((prev) => (on ? prev.filter((x) => x !== s.id) : [...prev, s.id]))}\n                    style={[styles.chip, { backgroundColor: on ? alpha(colors.primary, 0.12) : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                  >\n                    <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                      {on ? '✓ ' : ''}{s.label}\n                    </Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n          </Bloque>\n\n          <Bloque titulo=\"Disponibilidad\" hint=\"Apagada = fuera del catálogo. Las reservas que ya tengas siguen en pie.\">\n            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700', flex: 1, paddingRight: espaciado.e12 }}>\n                {isActive ? 'A la venta' : 'Apagada'}\n              </Text>\n              <Switch value={isActive} onValueChange={setIsActive} trackColor={{ true: alpha(colors.primary, 0.5) }} />\n            </View>\n          </Bloque>\n\n          <View style={[styles.resumen, { backgroundColor: alpha(colors.primary, 0.07), borderColor: alpha(colors.primary, 0.22) }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n              {name.trim() || 'Sin nombre'} · {xaf(num(basePriceXaf) ?? 0)} por noche\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4, lineHeight: 17 }}>\n              {num(totalUnits) ?? 1} habitación(es) de este tipo · mínimo {num(minNights) ?? 1} noche(s) ·\n              {' '}señal del {num(depositPercent) ?? 0}% · {fotos.length} foto(s)\n            </Text>\n          </View>\n\n          {problema ? (\n            <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e10 }}>⚠️ {problema}</Text>\n          ) : null}\n\n          <View style={{ marginTop: espaciado.e14 }}>\n            <PrimaryButton\n              title={editando ? 'Guardar los cambios' : 'Crear la habitación'}\n              onPress={() => void guardar()}\n              loading={guardando}\n              disabled={!!problema || subiendo}\n            />\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nfunction Bloque({ titulo, hint, children }: { titulo: string; hint?: string; children: React.ReactNode }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ marginBottom: espaciado.e20 }}>\n      <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginBottom: espaciado.e3 }}>{titulo}</Text>\n      {hint ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>{hint}</Text> : <View style={{ height: 7 }} />}\n      {children}\n    </View>\n  );\n}\n\n/**\n * Contador de caracteres.\n *\n * El servidor RECORTA en silencio: `clean(dto.name, 120)` y `clean(dto.description, 2000)`\n * guardan lo que cabe y tiran el resto. Sin contador, el hotelero escribe de más, la app lo\n * manda, el servidor guarda la mitad y **nadie se lo dice**. Se avisa a partir de 40\n * caracteres restantes, no solo al llegar al tope.\n */\nfunction Contador({ actual, max }: { actual: number; max: number }) {\n  const { colors } = useTheme();\n  const quedan = max - actual;\n  return (\n    <Text\n      style={{\n        color: quedan <= 40 ? colors.secondary : colors.textSecondary,\n        fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6, marginLeft: espaciado.e4,\n      }}\n      accessibilityLiveRegion=\"polite\"\n    >\n      {quedan <= 40 ? `Te quedan ${quedan} caracteres` : `${actual} de ${max}`}\n    </Text>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e4,\n    paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  volver: { width: 40, height: 34, alignItems: 'center', justifyContent: 'center' },\n  chip: { borderWidth: 1.5, borderRadius: radios.full, paddingHorizontal: espaciado.e13, minHeight: 44, justifyContent: 'center' },\n  paso: { width: 44, height: 44, borderRadius: 22, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center' },\n  rejilla: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginBottom: espaciado.e10 },\n  miniatura: { width: 96, height: 96, borderRadius: radios.md, overflow: 'hidden' },\n  foto: { width: '100%', height: '100%' },\n  portada: { position: 'absolute', left: 0, bottom: 0, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e3, borderTopRightRadius: 8 },\n  // Círculo visible pequeño + `hitSlop` para llegar a los 44 px de objetivo táctil sin\n  // comerse la foto: el círculo de antes (22 px) se fallaba con el dedo.\n  quitarFoto: {\n    position: 'absolute', right: 4, top: 4, width: 28, height: 28, borderRadius: 14,\n    backgroundColor: 'rgba(0,0,0,0.6)', alignItems: 'center', justifyContent: 'center',\n  },\n  resumen: { borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginTop: espaciado.e4 },\n});\n","/**\n * mediaReal — SUBIDA DE ARCHIVOS DE LA PARTE 41 (la que exige el módulo hotelero).\n *\n * POR QUÉ HACE FALTA ESTE FICHERO, y no sirve el subidor que ya había:\n *\n * En la app había dos caminos de subida y **ninguno de los dos vale para una habitación**:\n *\n *   1. `lifebookMediaApi.uploadFile` → `POST /lifebook/media/upload` (Parte 4). Guarda en\n *      MinIO con clave `covers/<uuid>.jpg` y devuelve `…/storage/<bucket>/covers/…`.\n *      **No escribe ninguna fila en `lifebook.media_uploads`.** El módulo de hotel valida\n *      cada foto contra esa tabla y además exige que la URL contenga `/lifebook-media/`:\n *      con la URL de la Parte 4 responde `IMAGE_INVALID` y **la habitación no se puede\n *      guardar con fotos**. (Se puede comprobar: la tabla tiene 5 filas y ninguna es de\n *      una habitación — las fotos del hotel de demostración se metieron por SQL a mano.)\n *\n *   2. `StepMedia` (publicar un producto) usa ese mismo endpoint, así que el comercio\n *      tampoco pasa por la verificación real.\n *\n * El camino correcto es el de la Parte 41, en tres pasos, y es el único que deja la fila\n * en `media_uploads` con `status='ready'` y la URL con la forma que el hotel acepta:\n *\n *   1. `POST …/commerce/media/upload-url` → firma una **POST policy** (el tope de tamaño lo\n *      impone el almacenamiento, no el cliente) y **reserva la clave** en la base antes de\n *      firmar, para poder cobrar cuota real y borrar huérfanos.\n *   2. `POST <uploadUrl>` con multipart: primero los campos firmados y **el archivo al\n *      final** (el almacenamiento exige que el campo del archivo sea el último).\n *   3. `POST …/commerce/media/complete` → verifica que el objeto existe, que pesa lo\n *      declarado y que es del tipo declarado; marca la fila `ready` y devuelve la **URL\n *      pública** definitiva. Esa URL es la que se guarda en la habitación.\n *\n * La URL resultante es `https://…/lifebook-media/products/<usuario>/<uuid>.jpg`, que es\n * exactamente lo que el servidor del hotel espera.\n */\nimport { getInfoAsync } from 'expo-file-system';\nimport { API_BASE } from './config';\nimport { ApiError, httpRequest } from './httpClient';\n\nconst MEDIA = '/lifebook/commerce/media';\n\nexport interface SignUploadInput {\n  /** `product` = material de catálogo (público). La carpeta de la clave sale de aquí. */\n  purpose: 'product' | 'post' | 'docs';\n  kind: 'image' | 'video' | 'audio' | 'file';\n  mimeType: string;\n  fileSizeBytes: number;\n  durationKind?: 'short' | 'long';\n  durationSec?: number;\n}\n\nexport interface SignUploadResult {\n  uploadUrl: string;\n  /** Campos que hay que reenviar TAL CUAL en el multipart. */\n  fields: Record<string, string>;\n  key: string;\n  bucket: string;\n  visibility: 'public' | 'private';\n  publicUrl: string | null;\n  maxBytes: number;\n  maxSec: number | null;\n  /** Cómo subir: POST multipart con `fields` + el archivo. */\n  method: 'POST';\n  /** Nombre del campo del archivo (hoy siempre `file`). */\n  fileField: string;\n  expiresIn: number;\n  restantesHoy: number;\n}\n\nexport interface CompleteUploadResult {\n  key: string;\n  bucket: string;\n  visibility: 'public' | 'private';\n  url: string;\n  signedUrl: string | null;\n  posterUrl: string | null;\n  bytes: number;\n  contentType: string;\n  durationSec: number | null;\n  verified: boolean;\n}\n\nexport const mediaRealApi = {\n  signUpload: (input: SignUploadInput) =>\n    httpRequest<SignUploadResult>(`${MEDIA}/upload-url`, { method: 'POST', body: input }),\n\n  complete: (key: string) =>\n    httpRequest<CompleteUploadResult>(`${MEDIA}/complete`, { method: 'POST', body: { key } }),\n\n  /** Cuota y material pendiente (útil para avisar antes de que el servidor corte). */\n  quota: () => httpRequest<Record<string, unknown>>(`${MEDIA}/quota`, { method: 'GET' }),\n};\n\nconst MB = 1024 * 1024;\n\n/** Tamaño real del archivo local. La firma lo EXIGE: sin él no hay URL de subida. */\nasync function tamanoDe(uri: string): Promise<number> {\n  try {\n    const info = await getInfoAsync(uri);\n    const size = (info as { exists?: boolean; size?: number }).exists === false\n      ? undefined\n      : (info as { size?: number }).size;\n    if (typeof size === 'number' && size > 0) return size;\n  } catch {\n    // Cae al respaldo de abajo.\n  }\n  // Respaldo: leer el archivo y medirlo (funciona con `content://` donde getInfo no da tamaño).\n  const blob = await (await fetch(uri)).blob();\n  return blob.size;\n}\n\n/**\n * Sube una imagen local por el camino de la Parte 41 y devuelve su **URL pública**,\n * que es la que se puede guardar en un tipo de habitación.\n *\n * Lanza `ApiError` con el código del servidor cuando algo no cuadra (`MEDIA_TOO_LARGE`,\n * `MEDIA_QUOTA_DAY`, `UPLOAD_MISSING`…), para poder enseñárselo al hotelero tal cual.\n */\nexport async function uploadImageReal(local: {\n  uri: string;\n  fileName?: string | null;\n  mimeType?: string | null;\n}): Promise<string> {\n  const mime = (local.mimeType ?? 'image/jpeg').toLowerCase();\n  const size = await tamanoDe(local.uri);\n  if (!size) throw new ApiError('MEDIA_SIZE_REQUIRED', 'No se pudo leer el tamaño de la foto');\n\n  // 1) Firma. El servidor decide si cabe en su cuota ANTES de entregar la URL.\n  const firma = await mediaRealApi.signUpload({\n    purpose: 'product', kind: 'image', mimeType: mime, fileSizeBytes: size,\n  });\n\n  // Comprobación en el cliente para no subir en balde algo que se va a rechazar.\n  if (Number(firma.maxBytes) > 0 && size > Number(firma.maxBytes)) {\n    throw new ApiError('MEDIA_TOO_LARGE',\n      `La foto pesa ${(size / MB).toFixed(1)} MB y el máximo es ${Math.round(Number(firma.maxBytes) / MB)} MB`);\n  }\n\n  // 2) Subida al almacenamiento. Los campos firmados primero y el ARCHIVO AL FINAL:\n  //    el almacenamiento rechaza la subida si el campo del archivo no es el último.\n  const form = new FormData();\n  for (const [k, v] of Object.entries(firma.fields ?? {})) form.append(k, String(v));\n  form.append(firma.fileField || 'file', {\n    uri: local.uri,\n    name: local.fileName || `habitacion-${Date.now()}.jpg`,\n    type: mime,\n  } as unknown as Blob);\n\n  const res = await fetch(firma.uploadUrl, { method: 'POST', body: form });\n  if (!res.ok) {\n    const cuerpo = await res.text().catch(() => '');\n    // El almacenamiento responde XML con el motivo (<Code>EntityTooLarge</Code>…).\n    const code = /<Code>([^<]+)<\\/Code>/.exec(cuerpo)?.[1] ?? `HTTP_${res.status}`;\n    throw new ApiError('UPLOAD_FAILED', `No se pudo subir la foto (${code})`);\n  }\n\n  // 3) Cierre: verifica tamaño y tipo reales y devuelve la URL definitiva.\n  const cerrado = await mediaRealApi.complete(firma.key);\n  const url = cerrado?.url || firma.publicUrl || '';\n  if (!url) throw new ApiError('UPLOAD_FAILED', 'La foto se subió pero el servidor no devolvió su dirección');\n  return url;\n}\n\n/** Base absoluta, por si hace falta montar una URL a mano. */\nexport const MEDIA_API_BASE = `${API_BASE}${MEDIA}`;\n","/**\n * lifebook-hotel-habitaciones — LAS HABITACIONES DEL HOTEL (panel del hotelero).\n *\n * Era el hueco más grande: el servidor sabía crear y editar tipos de habitación desde la\n * Parte 42 y `api/hotel.ts` tenía los métodos escritos… pero **ninguna pantalla los\n * llamaba**. El hotelero no podía dar de alta una habitación desde la app: solo la API.\n *\n * ── REVISIÓN DE UX/UI (lo que estaba mal y por qué se cambió) ─────────────────\n *\n * 1. **La tarjeta ESCONDÍA lo que escribe el hotelero.** El nombre se recortaba a 2 líneas\n *    y la **descripción no se enseñaba en absoluto**. Es su propio texto: si no se ve, el\n *    dueño no sabe qué ha escrito ni si quedó bien. Ahora la descripción se ve, y si es\n *    larga se abre con «Ver más» — la guía es clara: el texto de cuerpo se ajusta y se\n *    envuelve; si hay que recortar, se recorta con puntos suspensivos y SIEMPRE se da una\n *    forma de verlo entero (WCAG 1.4.10, reflujo).\n * 2. **Tres botones en una tarjeta es una barra de herramientas, no una tarjeta.** La regla\n *    es UNA acción principal y como mucho dos secundarias. Ahora: tocar la tarjeta = editar\n *    (principal), y quedan dos secundarias discretas — calendario y el interruptor de «a la\n *    venta». Además se ahorra muchísimo alto: los tres botones a ancho completo ocupaban\n *    más que el propio contenido.\n * 3. **Faltaba el ancla visual.** Había un contador de fotos («📷 3 foto(s)») pero no la\n *    foto. La jerarquía de una tarjeta empieza por el ancla visual. Ahora se ve la portada.\n * 4. **Cinco tamaños de letra en una tarjeta.** Se reduce a dos (15,5 para lo importante,\n *    12,5 para el resto): menos ruido y se lee más rápido.\n * 5. **Objetivos táctiles por debajo de 44 px.** Un chip de 33 px se falla con el dedo.\n * 6. **Cargaba con un spinner genérico.** Ahora carga con esqueletos con la forma de la\n *    tarjeta, que no hacen saltar el contenido al llegar.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Switch, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, CalendarDays, Plus } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { hotelApi, type HotelRoom } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { LazyImage } from '../components/rental/LazyImage';\nimport { xaf } from '../utils/datetime';\n\nexport default function HabitacionesScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\n/** Estado de la publicación, en lenguaje del hotelero y CORTO (compite por el ancho). */\nfunction estadoDe(r: HotelRoom, colors: { success: string; secondary: string; textSecondary: string }) {\n  if (!r.isActive) return { txt: 'Apagada', color: colors.textSecondary };\n  if (r.productStatus === 'active') return { txt: 'Publicada', color: colors.success };\n  if (r.productStatus === 'pending') return { txt: 'En revisión', color: colors.secondary };\n  if (r.productStatus === 'rejected') return { txt: 'Rechazada', color: colors.textSecondary };\n  return { txt: 'Oculta', color: colors.textSecondary };\n}\n\n/** «2 personas · 1 doble + 1 individual · 18 m²» — una línea, sin recortar. */\nfunction resumenHabitacion(r: HotelRoom): string {\n  const partes = [`${r.capacity} persona(s)`];\n  if (r.beds?.length) partes.push(r.beds.map((b) => `${b.count} ${b.kind}`).join(' + '));\n  if (r.sizeM2) partes.push(`${r.sizeM2} m²`);\n  return partes.join(' · ');\n}\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  const [rooms, setRooms] = useState<HotelRoom[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [aviso, setAviso] = useState<string | null>(null);\n  const [ocupado, setOcupado] = useState<string | null>(null);\n  /** Descripciones desplegadas: el texto del dueño no se esconde sin salida. */\n  const [abiertas, setAbiertas] = useState<Record<string, boolean>>({});\n  /**\n   * Filtro con contadores.\n   *\n   * Un hotelero acumula habitaciones apagadas o viejas, y la lista se convierte en un muro\n   * donde lo que importa (lo que está a la venta) se pierde entre lo demás. Por defecto se\n   * enseña **lo que está a la venta** y el resto queda a un toque — con el número a la vista\n   * para que se sepa que existe.\n   */\n  const [filtro, setFiltro] = useState<'venta' | 'todas'>('venta');\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setCargando(true);\n    try {\n      const out = await hotelApi.myRooms();\n      setRooms(out.rooms ?? []);\n      setError(null);\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudieron cargar tus habitaciones. Revisa tu conexión.');\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const alternar = async (r: HotelRoom) => {\n    setOcupado(r.id);\n    setAviso(null);\n    try {\n      const out = await hotelApi.updateRoom(r.id, { isActive: !r.isActive });\n      setRooms((prev) => prev.map((x) => (x.id === r.id ? { ...x, ...out.room } : x)));\n      setAviso(!r.isActive\n        ? `«${r.name}» vuelve a estar a la venta.`\n        : `«${r.name}» queda apagada: sale del catálogo y deja de poder reservarse. Las reservas que ya tienes siguen en pie.`);\n    } catch (e) {\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo cambiar el estado.');\n    } finally {\n      setOcupado(null);\n    }\n  };\n\n  const confirmarAlternar = (r: HotelRoom) => {\n    if (r.isActive) {\n      Alert.alert(\n        'Apagar esta habitación',\n        'Dejará de aparecer en el catálogo de Life Book y nadie podrá reservarla.\\n\\nLas reservas que ya tienes NO se cancelan.',\n        [{ text: 'Cancelar', style: 'cancel' }, { text: 'Apagar', onPress: () => void alternar(r) }],\n      );\n      return;\n    }\n    void alternar(r);\n  };\n\n  const totalUnidades = rooms.reduce((a, r) => a + (r.isActive ? r.totalUnits : 0), 0);\n  const publicadas = rooms.filter((r) => r.isActive && r.productStatus === 'active').length;\n\n  /**\n   * Orden: de precio MÁS BAJO a más alto.\n   * En Meituan, el calendario de precios lista los tipos así, y es lo que espera quien\n   * compara de un vistazo (documento §J.3). Antes salían en orden de creación, que no dice nada.\n   * Salvo en el panel: primero lo que está a la venta, luego el resto.\n   */\n  const visibles = rooms\n    .filter((r) => (filtro === 'venta' ? r.isActive : true))\n    .slice()\n    .sort((a, b) => Number(b.isActive) - Number(a.isActive) || a.basePriceXaf - b.basePriceXaf);\n\n  const apagadas = rooms.length - publicadas;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.cabecera, { paddingTop: insets.top + 8, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" hitSlop={12} style={styles.volver}>\n          <ArrowLeft size={21} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1 }}>Habitaciones</Text>\n        <Pressable\n          onPress={() => router.push('/lifebook-hotel-habitacion' as never)}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Añadir una habitación\"\n          hitSlop={12}\n          style={[styles.anadir, { backgroundColor: alpha(colors.primary, 0.12) }]}\n        >\n          <Plus size={20} color={colors.primary} />\n        </Pressable>\n      </View>\n\n      {cargando ? (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16 }} scrollEnabled={false}>\n          {[0, 1, 2].map((i) => <EsqueletoTarjeta key={i} />)}\n        </ScrollView>\n      ) : error ? (\n        <View style={styles.centro}>\n          <Text style={{ color: colors.textSecondary, textAlign: 'center', marginBottom: espaciado.e14 }}>{error}</Text>\n          <GhostButton title=\"Reintentar\" onPress={() => void cargar()} />\n        </View>\n      ) : (\n        <ScrollView\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 28 }}\n          refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => { setRefrescando(true); void cargar(true); }} tintColor={colors.primary} />}\n        >\n          {aviso ? (\n            <View style={[styles.aviso, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.25) }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 19 }}>{aviso}</Text>\n            </View>\n          ) : null}\n\n          {rooms.length ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e10 }}>\n              {rooms.length} tipo(s) · {totalUnidades} habitación(es) a la venta · {publicadas} publicada(s)\n            </Text>\n          ) : null}\n\n          {/*\n            Filtro con contadores. Un hotelero acumula habitaciones apagadas o viejas y la lista\n            se vuelve un muro donde lo que importa se pierde. Por defecto, lo que está a la\n            venta; el resto a un toque, con el número a la vista para saber que existe.\n          */}\n          {rooms.length > 1 ? (\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, marginBottom: espaciado.e12 }}>\n              <ChipFiltro\n                activo={filtro === 'venta'}\n                texto={`A la venta (${rooms.filter((r) => r.isActive).length})`}\n                onPress={() => setFiltro('venta')}\n              />\n              <ChipFiltro\n                activo={filtro === 'todas'}\n                texto={`Todas (${rooms.length})${apagadas ? ` · ${apagadas} apagada(s)` : ''}`}\n                onPress={() => setFiltro('todas')}\n              />\n            </View>\n          ) : null}\n\n          {visibles.map((r) => {\n            const est = estadoDe(r, colors);\n            const foto = r.images?.[0]?.url ?? null;\n            const descripcion = (r.description ?? '').trim();\n            const abierta = !!abiertas[r.id];\n            return (\n              <Pressable\n                key={r.id}\n                onPress={() => router.push({ pathname: '/lifebook-hotel-habitacion', params: { id: r.id } } as never)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Editar ${r.name}`}\n                style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}\n              >\n                {/* Ancla visual + lo esencial, en una sola franja que se lee de un vistazo. */}\n                <View style={{ flexDirection: 'row' }}>\n                  <View style={[styles.portada, { borderColor: colors.border }]}>\n                    <LazyImage source={{ uri: foto }} style={styles.portadaImg} />\n                  </View>\n                  <View style={{ flex: 1, paddingLeft: espaciado.e12 }}>\n                    {/*\n                      El nombre ocupa TODO el ancho (dos líneas) y el estado baja a la línea\n                      del precio. Antes iban en la misma fila y el chip «Se puede reservar» se\n                      comía la mitad del nombre: el dato del dueño perdía contra una etiqueta.\n                    */}\n                    <Text style={{ color: colors.textPrimary, fontSize: 15.5, fontWeight: '900' }} numberOfLines={2}>\n                      {r.name}\n                    </Text>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: espaciado.e6 }}>\n                      <Text style={{ color: colors.textPrimary, fontSize: 15.5, fontWeight: '900' }}>\n                        {xaf(r.basePriceXaf)}\n                        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}> por noche</Text>\n                      </Text>\n                      <View style={[styles.etiqueta, { backgroundColor: alpha(est.color, 0.12) }]}>\n                        <Text style={{ color: est.color, fontSize: tipografia.micro, fontWeight: '900' }}>{est.txt}</Text>\n                      </View>\n                    </View>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>{resumenHabitacion(r)}</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                      {r.totalUnits} habitación(es) · mínimo {r.minNights} noche(s) · señal {r.depositPercent}%\n                    </Text>\n                  </View>\n                </View>\n\n                {/* LO QUE ESCRIBIÓ EL DUEÑO: se ve, y si es largo se abre. Nunca se esconde del todo. */}\n                {descripcion ? (\n                  <View style={[styles.descripcion, { borderTopColor: colors.border }]}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, lineHeight: 18 }} numberOfLines={abierta ? undefined : 2}>\n                      {descripcion}\n                    </Text>\n                    {descripcion.length > 90 ? (\n                      <Pressable\n                        onPress={() => setAbiertas((prev) => ({ ...prev, [r.id]: !abierta }))}\n                        hitSlop={10}\n                        accessibilityRole=\"button\"\n                        accessibilityLabel={abierta ? 'Ver menos' : 'Ver la descripción completa'}\n                        style={styles.verMas}\n                      >\n                        <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                          {abierta ? 'Ver menos' : 'Ver más'}\n                        </Text>\n                      </Pressable>\n                    ) : null}\n                  </View>\n                ) : (\n                  <View style={[styles.descripcion, { borderTopColor: colors.border }]}>\n                    <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                      Sin descripción: el huésped decide con lo que le cuentes (toca para escribirla)\n                    </Text>\n                  </View>\n                )}\n\n                {r.productStatus === 'pending' && r.isActive ? (\n                  <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e8, lineHeight: 18 }}>\n                    ⏳ En revisión: la administración tiene que aprobarla antes de que se pueda reservar. Mientras\n                    tanto puedes ponerle precios y cerrar fechas.\n                  </Text>\n                ) : null}\n\n                {/*\n                  ── LISTA DE COMPROBACIÓN DE LA FICHA ──\n                  Viene de la regla de cumplimiento de Meituan para los tipos de habitación\n                  (§J.3 del documento de diseño): un tipo con menos de **3 fotos reales**, sin\n                  cama o sin superficie declaradas no debería publicarse así. Y sus palancas de\n                  conversión (§C.2) son justo la foto, el nombre, la cama+superficie y las\n                  condiciones exactas.\n                  Solo se comprueba lo que el sistema SABE de verdad (no se inventan campos que\n                  no existen). **No bloquea** —son habitaciones que ya se pueden reservar—: avisa.\n                */}\n                {(() => {\n                  const nFotos = r.images?.length ?? 0;\n                  const faltan = [\n                    nFotos < 3 ? `${nFotos}/3 fotos` : null,\n                    !r.beds?.length ? 'sin cama' : null,\n                    !r.sizeM2 ? 'sin superficie' : null,\n                    !descripcion ? 'sin descripción' : null,\n                  ].filter(Boolean) as string[];\n                  return (\n                    <View style={[styles.comprobacion, { borderTopColor: colors.border }]}>\n                      <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e7 }}>\n                        <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '900', letterSpacing: 0.5 }}>\n                          FICHA\n                        </Text>\n                        <Text style={{\n                          color: faltan.length ? colors.secondary : colors.success,\n                          fontSize: tipografia.caption, fontWeight: '900', marginLeft: 'auto',\n                        }}>\n                          {faltan.length ? `Falta: ${faltan.join(' · ')}` : 'Completa'}\n                        </Text>\n                      </View>\n                      <View style={{ flexDirection: 'row', gap: espaciado.e6, flexWrap: 'wrap' }}>\n                        <Sello ok={nFotos >= 3} texto={`${nFotos} foto(s)`} colors={colors} />\n                        <Sello ok={!!r.beds?.length} texto={r.beds?.length ? `${r.beds.reduce((a, b) => a + b.count, 0)} cama(s)` : 'sin cama'} colors={colors} />\n                        <Sello ok={!!r.sizeM2} texto={r.sizeM2 ? `${r.sizeM2} m²` : 'sin m²'} colors={colors} />\n                        <Sello ok texto={`cancelación ${r.cancellationHours} h`} colors={colors} />\n                        <Sello ok texto={`señal ${r.depositPercent}%`} colors={colors} />\n                      </View>\n                    </View>\n                  );\n                })()}\n\n                {/* UNA acción secundaria clara + el interruptor. La principal es tocar la tarjeta. */}\n                <View style={[styles.pie, { borderTopColor: colors.border }]}>\n                  <Pressable\n                    onPress={() => router.push({ pathname: '/lifebook-hotel-calendario', params: { id: r.id, nombre: r.name } } as never)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`Precios y fechas de ${r.name}`}\n                    hitSlop={8}\n                    style={[styles.pieBtn, { borderColor: colors.border }]}\n                  >\n                    <CalendarDays size={16} color={colors.primary} />\n                    <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Precios y fechas</Text>\n                  </Pressable>\n\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginLeft: 'auto' }}>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                      {ocupado === r.id ? 'Cambiando…' : r.isActive ? 'A la venta' : 'Apagada'}\n                    </Text>\n                    <Switch\n                      value={!!r.isActive}\n                      onValueChange={() => confirmarAlternar(r)}\n                      disabled={ocupado === r.id}\n                      trackColor={{ true: alpha(colors.success, 0.5) }}\n                      accessibilityLabel={r.isActive ? `Apagar ${r.name}` : `Poner a la venta ${r.name}`}\n                    />\n                  </View>\n                </View>\n              </Pressable>\n            );\n          })}\n\n          {!rooms.length ? (\n            <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: 15.5, fontWeight: '900' }}>Todavía no tienes habitaciones</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 18, marginTop: espaciado.e6 }}>\n                Un «tipo de habitación» es lo que se vende: por ejemplo «Doble con aire», con su precio por noche,\n                cuántas tienes de ese tipo y su estancia mínima. De cada tipo se reservan unidades sueltas, así que\n                dos reservas de la misma noche caben si te quedan habitaciones libres — y no caben si no.\n              </Text>\n              <View style={{ marginTop: espaciado.e14 }}>\n                <PrimaryButton title=\"Crear la primera habitación\" onPress={() => router.push('/lifebook-hotel-habitacion' as never)} />\n              </View>\n            </View>\n          ) : null}\n\n          {rooms.length ? (\n            <View style={{ marginTop: espaciado.e6 }}>\n              <GhostButton title=\"Ficha del hotel\" onPress={() => router.push('/lifebook-hotel-perfil' as never)} />\n            </View>\n          ) : null}\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\n/**\n * Un sello de la lista de comprobación de la ficha.\n * `ok` = cumple; si no, se pinta en naranja (aviso, nunca rojo: no es un error, es un «te\n * falta esto»). Los sellos informativos (cancelación, señal) van siempre en gris.\n */\nfunction Sello({ ok, texto, colors }: {\n  ok: boolean;\n  texto: string;\n  colors: { success: string; secondary: string; textSecondary: string };\n}) {\n  const color = ok ? colors.textSecondary : colors.secondary;\n  return (\n    <View style={{\n      borderWidth: 1, borderColor: color, borderRadius: radios.full,\n      paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3,\n    }}>\n      <Text style={{ color, fontSize: tipografia.micro, fontWeight: '800' }}>\n        {ok ? '' : '⚠ '}{texto}\n      </Text>\n    </View>\n  );\n}\n\n/** Esqueleto con la FORMA de la tarjeta (no un spinner suelto): el contenido no salta al llegar. */\n/** Chip de filtro: 44 px de alto para que se acierte con el dedo, y con el número dentro. */\nfunction ChipFiltro({ activo, texto, onPress }: { activo: boolean; texto: string; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityState={{ selected: activo }}\n      accessibilityLabel={texto}\n      style={{\n        minHeight: 44, justifyContent: 'center',\n        borderWidth: 1.5, borderRadius: radios.full, paddingHorizontal: espaciado.e14,\n        borderColor: activo ? colors.primary : colors.border,\n        backgroundColor: activo ? alpha(colors.primary, 0.12) : colors.surface,\n      }}\n    >\n      <Text style={{ color: activo ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n        {texto}\n      </Text>\n    </Pressable>\n  );\n}\n\nfunction EsqueletoTarjeta() {\n  const { colors } = useTheme();\n  const gris = alpha(colors.textSecondary, 0.14);\n  return (\n    <View style={[styles.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n      <View style={{ flexDirection: 'row' }}>\n        <View style={[styles.portada, { backgroundColor: gris, borderColor: colors.border }]} />\n        <View style={{ flex: 1, paddingLeft: espaciado.e12, gap: espaciado.e8 }}>\n          <View style={{ height: 14, width: '70%', borderRadius: 6, backgroundColor: gris }} />\n          <View style={{ height: 11, width: '50%', borderRadius: 6, backgroundColor: gris }} />\n          <View style={{ height: 14, width: '35%', borderRadius: 6, backgroundColor: gris }} />\n        </View>\n      </View>\n      <View style={{ height: 11, width: '90%', borderRadius: 6, backgroundColor: gris, marginTop: espaciado.e14 }} />\n      <View style={{ height: 11, width: '60%', borderRadius: 6, backgroundColor: gris, marginTop: espaciado.e8 }} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e6,\n    paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  volver: { width: 44, height: 44, alignItems: 'center', justifyContent: 'center' },\n  anadir: { width: 44, height: 44, borderRadius: 22, alignItems: 'center', justifyContent: 'center' },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 },\n  aviso: { borderWidth: 1, borderRadius: radios.md, padding: espaciado.e11, marginBottom: espaciado.e12 },\n  tarjeta: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e14, marginBottom: espaciado.e12 },\n  portada: { width: 76, height: 76, borderRadius: radios.md, borderWidth: StyleSheet.hairlineWidth, overflow: 'hidden' },\n  portadaImg: { width: '100%', height: '100%' },\n  etiqueta: { borderRadius: radios.full, paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e4, marginLeft: 'auto' },\n  descripcion: { borderTopWidth: StyleSheet.hairlineWidth, marginTop: espaciado.e12, paddingTop: espaciado.e10 },\n  comprobacion: { borderTopWidth: StyleSheet.hairlineWidth, marginTop: espaciado.e12, paddingTop: espaciado.e10 },\n  verMas: { minHeight: 44, justifyContent: 'center' },\n  pie: {\n    borderTopWidth: StyleSheet.hairlineWidth, marginTop: espaciado.e12, paddingTop: espaciado.e8,\n    flexDirection: 'row', alignItems: 'center',\n  },\n  pieBtn: {\n    minHeight: 44, borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12,\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e7,\n  },\n});\n","/**\n * lifebook-hotel-panel — EL PANEL DEL HOTEL (el «hotel-merchant» del boceto).\n *\n * Ruta plana (`/lifebook-hotel-panel`): un grupo `(hotel-merchant)` no aparece en la URL,\n * así que su `index.tsx` habría quedado en `/` y chocado con la portada de la app.\n *\n * Y la decisión de fondo: **el hotel sale de la SESIÓN, no de la URL**. La versión del\n * boceto pedía `shopId` (con un UUID en ceros de marcador) contra rutas que no existían;\n * aquí se llama a `/my/hotel/*`, que el servidor resuelve por el token. No hay id que\n * adivinar ni que comprobar: la puerta es la propia consulta (y `ShopOwnerGuard` queda\n * como segunda capa en las rutas que sí llevan la tienda en la URL).\n *\n * Lo que la pantalla corrige respecto al boceto:\n *   · los botones son los del kit (`title`, no `label`) y solo aparecen los que la\n *     máquina de estados permite **para quien mira** (el huésped solo cancela);\n *   · cancelar y «no se presentó» **piden el motivo** (el servidor lo exige y queda\n *     registrado);\n *   · se ven las **retenidas sin pagar** con su cuenta atrás, que son las urgentes;\n *   · el dinero del día está separado: señal cobrada, pendiente de cobrar y «por\n *     confirmar», en vez de un solo número;\n *   · cada error se enseña y se puede reintentar (ni un `catch {}`).\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Platform, Pressable, RefreshControl, SectionList, StyleSheet, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ChevronRight, Settings } from 'lucide-react-native';\nimport { alpha, altura, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { hotelApi, PAGO_ETIQUETA, type HotelDashboard, type Reservation } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport {\n  availableActions, isReservationLive, RESERVATION_ACTIONS_SPEC, RESERVATION_STATUS_LABELS,\n  type ReservationAction, type ReservationStatus,\n} from '@egrouteplan/contracts';\nimport { countdown, longDate, shortDate, todayIso, xaf } from '../utils/datetime';\n\nconst POLL_MS = 20_000;\n\nexport default function HotelPanelScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  const [dash, setDash] = useState<HotelDashboard | null>(null);\n  const [reservas, setReservas] = useState<Reservation[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [aviso, setAviso] = useState<string | null>(null);\n  const [ocupado, setOcupado] = useState<string | null>(null); // id de la reserva en curso\n  const vivo = useRef(true);\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setCargando(true);\n    try {\n      const [d, l] = await Promise.all([hotelApi.dashboard(), hotelApi.shopReservations()]);\n      if (!vivo.current) return;\n      setDash(d);\n      setReservas(l.reservations ?? []);\n      setError(null);\n    } catch (e) {\n      if (!vivo.current) return;\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar el panel. Revisa tu conexión.');\n    } finally {\n      if (vivo.current) { setCargando(false); setRefrescando(false); }\n    }\n  }, []);\n\n  useEffect(() => {\n    vivo.current = true;\n    void cargar();\n    const t = setInterval(() => void cargar(true), POLL_MS);\n    return () => { vivo.current = false; clearInterval(t); };\n  }, [cargar]);\n\n  const hoy = todayIso();\n  const { urgentes, enCurso, futuras, historial } = useMemo(() => {\n    const vivas = reservas.filter((r) => isReservationLive(r.status, r.holdExpiresAt));\n    return {\n      // Lo primero: retenidas sin pagar y por confirmar.\n      urgentes: vivas.filter((r) => r.status === 'hold' || r.status === 'pending'),\n      enCurso: vivas.filter((r) => ['confirmed', 'checked_in'].includes(r.status) && r.checkIn <= hoy && r.checkOut > hoy),\n      futuras: vivas.filter((r) => ['confirmed'].includes(r.status) && r.checkIn > hoy),\n      historial: reservas.filter((r) => !isReservationLive(r.status, r.holdExpiresAt)),\n    };\n  }, [reservas, hoy]);\n\n  const accion = async (id: string, fn: () => Promise<unknown>, exito: string) => {\n    setOcupado(id);\n    setAviso(null);\n    try {\n      await fn();\n      setAviso(exito);\n      await cargar(true);\n    } catch (e) {\n      // El error del servidor SÍ se enseña: puede ser «quedan 0 habitaciones», «la\n      // reserva cambió» o «la entrada es el día X», y todas son útiles.\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo completar la acción.');\n    } finally {\n      setOcupado(null);\n    }\n  };\n\n  /** Cancelar y no-presentado exigen motivo (el servidor lo comprueba también). */\n  const pedirMotivo = (r: Reservation, a: ReservationAction) => {\n    const etiqueta = RESERVATION_ACTIONS_SPEC[a].label;\n    const enviar = (motivo: string) =>\n      void accion(r.id, () => hotelApi.setReservationStatus(r.id, RESERVATION_ACTIONS_SPEC[a].to, motivo.trim()), `«${etiqueta}» hecho en ${r.code}.`);\n    if (Platform.OS === 'web') {\n      const m = typeof window !== 'undefined' ? window.prompt(`Motivo para ${etiqueta.toLowerCase()} (${r.code})`) : null;\n      if (m && m.trim().length >= 3) enviar(m);\n      return;\n    }\n    if (a === 'cancel' && Platform.OS === 'ios' && Alert.prompt) {\n      Alert.prompt(`Cancelar ${r.code}`, 'Motivo (queda registrado en la reserva)', (m?: string) => {\n        if (m && m.trim().length >= 3) enviar(m);\n      }, 'plain-text');\n      return;\n    }\n    // Android/web sin campo de texto: se deja claro qué se va a registrar.\n    Alert.alert(\n      `${etiqueta} · ${r.code}`,\n      a === 'cancel'\n        ? 'Se cancelará la reserva y quedará registrado el motivo «Cancelada por el hotel». ¿Seguir?'\n        : `Se marcará como no presentado y quedará registrado «El huésped no se presentó». ¿Seguir?`,\n      [\n        { text: 'No', style: 'cancel' },\n        {\n          text: 'Sí',\n          style: a === 'cancel' ? 'destructive' : 'default',\n          onPress: () => enviar(a === 'cancel' ? 'Cancelada por el hotel' : 'El huésped no se presentó'),\n        },\n      ],\n    );\n  };\n\n  const hacer = (r: Reservation, a: ReservationAction) => {\n    const spec = RESERVATION_ACTIONS_SPEC[a];\n    if (spec.reasonRequired) return pedirMotivo(r, a);\n    void accion(r.id, () => hotelApi.setReservationStatus(r.id, spec.to), `«${spec.label}» hecho en ${r.code}.`);\n  };\n\n  const confirmarSenal = (r: Reservation) =>\n    void accion(r.id, () => hotelApi.confirmDeposit(r.id, 'Confirmado en recepción'), `Señal de ${r.code} confirmada.`);\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={styles.volver}>\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          {/* El nombre del hotel es del dueño: dos líneas, no una recortada a media palabra. */}\n          <Text style={[styles.titulo, { color: colors.textPrimary }]} numberOfLines={2}>\n            {dash?.shop.name ?? 'Mi hotel'}\n          </Text>\n          <Text style={[styles.sub, { color: colors.textSecondary }]}>\n            {dash ? `Hoy, ${longDate(dash.date)}` : 'Panel del alojamiento'}\n          </Text>\n        </View>\n        <Pressable\n          onPress={() => router.push('/lifebook-hotel-reservas?side=hotel' as never)}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Ver todas las reservas\"\n          style={[styles.cambiar, { borderColor: colors.border }]}\n        >\n          <Text style={[styles.cambiarTxt, { color: colors.primary }]}>Todas</Text>\n        </Pressable>\n      </View>\n\n      {cargando ? (\n        <View style={styles.centro}><ActivityIndicator color={colors.primary} /></View>\n      ) : error && !dash ? (\n        <View style={[styles.aviso, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>{error}</Text>\n          <Pressable onPress={() => void cargar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n            <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        /*\n          LISTA VIRTUALIZADA POR SECCIONES (auditoría de diseño, D-04/D-21): antes era un\n          ScrollView con un bloque «Grupo» por sección y cada bloque con su .map(), así que\n          TODAS las reservas quedaban montadas. Aquí la sección es el grupo y la fila es la\n          reserva. `stickySectionHeadersEnabled` en false a propósito: los títulos nunca\n          fueron pegajosos. El hueco lo pone el `gap: espaciado.e12` del contenedor.\n        */\n        <SectionList\n          /*\n            Las secciones vacías se filtran a propósito: VirtualizedSectionList cuenta DOS\n            celdas por sección aunque no tenga filas (cabecera y pie, ver\n            @react-native/virtualized-lists/Lists/VirtualizedSectionList.js L178-180), así que\n            sin filtrar saldría un «En curso (0)» que antes NO se veía: el viejo componente\n            `Grupo` hacía `return null` cuando la lista venía vacía.\n          */\n          sections={[\n            { titulo: 'Requiere tu atención', data: urgentes },\n            { titulo: 'En casa hoy', data: enCurso },\n            { titulo: 'Próximas llegadas', data: futuras },\n            { titulo: 'Historial', data: historial.slice(0, 20) },\n          ].filter((s) => s.data.length > 0)}\n          keyExtractor={(r) => r.id}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 30, gap: espaciado.e12 }}\n          stickySectionHeadersEnabled={false}\n          refreshControl={\n            <RefreshControl refreshing={refrescando} onRefresh={() => { setRefrescando(true); void cargar(true); }} tintColor={colors.primary} />\n          }\n          renderSectionHeader={({ section }) => (\n            <Text style={[styles.seccion, { color: colors.textPrimary }]}>{section.titulo} ({section.data.length})</Text>\n          )}\n          renderItem={({ item: r }) => (\n            <Tarjeta key={r.id} r={r} ocupado={ocupado === r.id} onAccion={hacer} onSenal={confirmarSenal} />\n          )}\n          ListHeaderComponent={\n            /*\n            Un `View` con el hueco del contenedor, y no un fragmento: el `gap` de\n            `contentContainerStyle` separa CELDAS, y `ListHeaderComponent` es UNA celda. Con un\n            fragmento, todo lo de aquí dentro quedaba pegado (era gap: espaciado.e12 antes de virtualizar).\n            */\n            <View style={{ gap: espaciado.e12 }}>\n          {aviso ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>{aviso}</Text>\n            </View>\n          ) : null}\n\n          {/*\n            ── UNA SOLA PUERTA A LA OTRA PARTE ──\n            El panel del comerciante son DOS partes (decisión del dueño, 2026-09-12):\n            **Hoy** (esta: lo que caduca — personas esperando y dinero por cobrar) y\n            **Gestión** (precios, fotos, textos, catálogo). Mezclarlas hace que lo urgente se\n            pierda entre lo que puede esperar, así que aquí no hay atajos sueltos: hay UNA\n            puerta clara. La primera versión puso tres tarjetas de acceso y era una barra de\n            herramientas dentro de la pantalla del día.\n          */}\n          <Pressable\n            onPress={() => router.push('/lifebook-hotel-gestion' as never)}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Gestión: ficha del hotel, habitaciones y precios\"\n            style={[styles.puente, { borderColor: colors.border, backgroundColor: colors.card }]}\n          >\n            <View style={[styles.puenteIcono, { backgroundColor: alpha(colors.primary, 0.12) }]}>\n              <Settings size={17} color={colors.primary} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>Gestión</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                Ficha del hotel, habitaciones, precios y fechas\n              </Text>\n            </View>\n            <ChevronRight size={18} color={colors.textSecondary} />\n          </Pressable>\n\n          {/* ── El día: lo urgente primero, y el dinero separado ── */}\n          {dash ? (\n            <View style={styles.grid}>\n              <Stat titulo=\"Llegadas hoy\" valor={String(dash.arrivalsToday)} />\n              <Stat titulo=\"Salidas hoy\" valor={String(dash.departuresToday)} />\n              <Stat titulo=\"Dentro ahora\" valor={String(dash.insideNow)} />\n              <Stat titulo=\"Próximas\" valor={String(dash.upcoming)} />\n              <Stat titulo=\"Por confirmar\" valor={String(dash.pendingConfirm)} tono=\"aviso\" />\n              <Stat titulo=\"Sin pagar (retenidas)\" valor={String(dash.unpaidHolds)} tono=\"alerta\" />\n            </View>\n          ) : null}\n\n          {dash?.occupancy?.length ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>OCUPACIÓN DE HOY</Text>\n              {dash.occupancy.map((o) => (\n                <View key={o.roomTypeId} style={styles.linea}>\n                  {/*\n                    El nombre del tipo de habitación lo escribió el hotelero en SU panel: aquí\n                    (que es su pantalla) recortarlo a una línea era quitándole su propio dato.\n                    El número de ocupadas se queda alineado a la derecha en la misma fila.\n                  */}\n                  <Text style={[styles.lineaEtq, { color: colors.textPrimary }]} numberOfLines={2}>{o.name}</Text>\n                  <Text style={[styles.lineaVal, { color: o.free === 0 ? colors.danger : colors.success }]}>\n                    {o.occupied}/{o.totalUnits} ocupadas · {o.free} libres\n                  </Text>\n                </View>\n              ))}\n              {dash.depositDue > 0 ? (\n                <Text style={[styles.avisoTxt, { color: colors.secondary }]}>\n                  {dash.depositDue} reserva(s) con señal pendiente de cobro\n                </Text>\n              ) : null}\n            </View>\n          ) : null}\n\n            </View>\n          }\n          ListEmptyComponent={\n            !error ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>Tu hotel todavía no tiene reservas.</Text>\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                Aparecerán aquí en cuanto un huésped reserve una de tus habitaciones.\n              </Text>\n            </View>\n            ) : null}\n        />\n      )}\n    </View>\n  );\n}\n\nfunction Tarjeta({\n  r, ocupado, onAccion, onSenal,\n}: {\n  r: Reservation;\n  ocupado: boolean;\n  onAccion: (r: Reservation, a: ReservationAction) => void;\n  onSenal: (r: Reservation) => void;\n}) {\n  const { colors } = useTheme();\n  const estado = RESERVATION_STATUS_LABELS[r.status as ReservationStatus] ?? r.status;\n  const viva = isReservationLive(r.status, r.holdExpiresAt);\n  const acciones = availableActions(r.status, { who: 'hotel', viva });\n\n  const colorEstado = r.status === 'hold'\n    ? colors.danger\n    : r.status === 'pending'\n      ? colors.secondary\n      : r.status === 'cancelled' || r.status === 'no_show'\n        ? colors.textSecondary\n        : r.status === 'checked_out'\n          ? colors.success\n          : colors.primary;\n\n  const senalPendiente = ['hold', 'pending'].includes(r.status) && r.depositXaf > 0\n    && !['deposit_paid', 'paid'].includes(r.paymentStatus);\n\n  return (\n    <View style={[styles.card, { borderColor: colors.border, backgroundColor: colors.card }]}>\n      <View style={styles.linea}>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.codigo, { color: colors.textPrimary }]}>{r.code}</Text>\n          {/* El nombre del huésped y el de la habitación los escribió alguien: dos líneas. */}\n          <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={2}>\n            {r.guest?.name ?? 'Huésped'} · {r.roomName} · {r.units} hab. · {r.guests} huésp.\n          </Text>\n        </View>\n        <View style={[styles.badge, { borderColor: colorEstado, backgroundColor: alpha(colorEstado, 0.12) }]}>\n          <Text style={[styles.badgeTxt, { color: colorEstado }]}>{estado}</Text>\n        </View>\n      </View>\n\n      <Text style={[styles.dato, { color: colors.textPrimary }]}>\n        {shortDate(r.checkIn, true)} → {shortDate(r.checkOut, true)} · {r.nights} noche(s)\n      </Text>\n\n      <View style={[styles.dinero, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n        <View style={styles.linea}>\n          <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Total</Text>\n          <Text style={[styles.lineaVal, { color: colors.textPrimary, fontWeight: '800' }]}>{xaf(r.totalXaf)}</Text>\n        </View>\n        {r.depositXaf > 0 ? (\n          <>\n            <View style={styles.linea}>\n              <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Señal ({r.depositPercent} %)</Text>\n              <Text style={[styles.lineaVal, { color: colors.primary, fontWeight: '800' }]}>{xaf(r.depositXaf)}</Text>\n            </View>\n            <View style={styles.linea}>\n              <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Al llegar</Text>\n              <Text style={[styles.lineaVal, { color: colors.secondary, fontWeight: '800' }]}>{xaf(r.remainingXaf)}</Text>\n            </View>\n          </>\n        ) : (\n          <View style={styles.linea}>\n            <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Se paga al llegar</Text>\n            <Text style={[styles.lineaVal, { color: colors.secondary, fontWeight: '800' }]}>{xaf(r.totalXaf)}</Text>\n          </View>\n        )}\n        <View style={styles.linea}>\n          <Text style={[styles.lineaEtq, { color: colors.textSecondary }]}>Dinero</Text>\n          <Text style={[styles.lineaVal, { color: colors.textSecondary }]}>\n            {PAGO_ETIQUETA[r.paymentStatus] ?? r.paymentStatus}\n            {r.depositProof ? ` · ${r.depositProof}` : ''}\n          </Text>\n        </View>\n      </View>\n\n      {r.status === 'hold' && r.holdExpiresAt ? (\n        <Text style={[styles.avisoTxt, { color: colors.danger }]}>\n          ⏳ Retenida {countdown(r.holdExpiresAt)} sin pagar la señal. Si no se paga, se libera sola.\n        </Text>\n      ) : null}\n      {r.freeCancellationUntil && viva ? (\n        <Text style={[styles.avisoTxt, { color: colors.textSecondary }]}>\n          Cancelación gratuita hasta el {longDate(r.freeCancellationUntil.slice(0, 10))}.\n        </Text>\n      ) : null}\n      {r.cancelReason ? (\n        <Text style={[styles.avisoTxt, { color: colors.textSecondary }]}>Motivo: {r.cancelReason}</Text>\n      ) : null}\n\n      {senalPendiente ? (\n        <Pressable\n          onPress={() => onSenal(r)}\n          disabled={ocupado}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Confirmar la señal de ${r.code}`}\n          accessibilityState={{ disabled: ocupado, busy: ocupado }}\n          style={[styles.boton, { backgroundColor: ocupado ? alpha(colors.success, 0.5) : colors.success }]}\n        >\n          {ocupado ? <ActivityIndicator color={brand.white} /> : (\n            <Text style={styles.botonTxt}>Confirmar señal recibida ({xaf(r.depositXaf)})</Text>\n          )}\n        </Pressable>\n      ) : null}\n\n      {acciones.length ? (\n        <View style={styles.acciones}>\n          {acciones.map((a) => {\n            const spec = RESERVATION_ACTIONS_SPEC[a];\n            const destructivo = a === 'cancel' || a === 'noshow';\n            return (\n              <Pressable\n                key={a}\n                onPress={() => onAccion(r, a)}\n                disabled={ocupado}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`${spec.label} · ${r.code}`}\n                accessibilityState={{ disabled: ocupado }}\n                style={[\n                  styles.accion,\n                  destructivo\n                    ? { borderColor: colors.border, backgroundColor: 'transparent' }\n                    : { borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.08) },\n                  ocupado ? { opacity: 0.5 } : null,\n                ]}\n              >\n                <Text style={[styles.accionTxt, { color: destructivo ? colors.danger : colors.primary }]}>\n                  {spec.label}\n                </Text>\n              </Pressable>\n            );\n          })}\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\nfunction Stat({ titulo, valor, tono }: { titulo: string; valor: string; tono?: 'aviso' | 'alerta' }) {\n  const { colors } = useTheme();\n  const color = tono === 'alerta' ? colors.danger : tono === 'aviso' ? colors.secondary : colors.textPrimary;\n  return (\n    <View style={[styles.stat, { borderColor: colors.border, backgroundColor: colors.card }]}>\n      <Text style={[styles.statEtq, { color: colors.textSecondary }]} numberOfLines={2}>{titulo}</Text>\n      <Text style={[styles.statVal, { color }]}>{valor}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  barra: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1 },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  titulo: { fontSize: 16.5, fontWeight: '800' },\n  sub: { fontSize: tipografia.caption },\n  cambiar: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e7 },\n  cambiarTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  aviso: { margin: espaciado.e14, borderWidth: 1, borderRadius: 14, padding: espaciado.e12, gap: espaciado.e6 },\n  enlace: { fontSize: tipografia.caption, fontWeight: '700' },\n  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10 },\n  stat: { width: '47.5%', borderWidth: 1, borderRadius: 14, padding: espaciado.e12 },\n  statEtq: { fontSize: tipografia.caption },\n  statVal: { fontSize: 24, fontWeight: '800', marginTop: espaciado.e2 },\n  bloque: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e4 },\n  /** Puerta única a la parte de Gestión. 56 px de alto: objetivo táctil cómodo. */\n  puente: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e11,\n    borderWidth: 1, borderRadius: 14, padding: espaciado.e12, minHeight: 56,\n  },\n  puenteIcono: { width: 32, height: 32, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },\n  etiqueta: { fontSize: 10.5, fontWeight: '800', letterSpacing: 0.6 },\n  seccion: { fontSize: 14.5, fontWeight: '800' },\n  card: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e4 },\n  codigo: { fontSize: 15.5, fontWeight: '800', letterSpacing: 0.5 },\n  dato: { fontSize: tipografia.body, marginTop: espaciado.e2 },\n  linea: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e10 },\n  lineaEtq: { fontSize: tipografia.caption, flex: 1 },\n  lineaVal: { fontSize: tipografia.body },\n  badge: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 },\n  badgeTxt: { fontSize: 10.5, fontWeight: '800' },\n  dinero: { borderWidth: 1, borderRadius: radios.md, padding: espaciado.e9, marginTop: espaciado.e6, gap: espaciado.e2 },\n  avisoTxt: { fontSize: tipografia.caption, marginTop: espaciado.e6, fontWeight: '600' },\n  boton: { height: altura.punto, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center', marginTop: espaciado.e8 },\n  botonTxt: { color: brand.white, fontSize: tipografia.body, fontWeight: '800' },\n  acciones: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e10 },\n  accion: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: 40, alignItems: 'center', justifyContent: 'center' },\n  accionTxt: { fontSize: tipografia.body, fontWeight: '800' },\n});\n","/**\n * lifebook-hotel-perfil — LA FICHA DEL HOTEL (panel del hotelero).\n *\n * Segunda de las pantallas que faltaban: el servidor sabía guardar la ficha desde la\n * Parte 42 (`PUT my/hotel`) y el cliente tenía el método escrito… pero **ninguna pantalla lo\n * llamaba**. Sin esto, el hotelero no puede poner sus estrellas, su horario de entrada o sus\n * normas: el huésped ve un alojamiento a medio describir.\n *\n * Dos cosas que se han MEDIDO y condicionan la pantalla:\n *\n * 1. **Quitar una forma de pago no funciona desde aquí.** Probado contra el servidor: se pidió\n *    dejar solo «transferencia» y las demás siguieron activas. Guardar la ficha solo puede\n *    ACTIVAR formas de pago, no desactivarlas. Por eso la pantalla lo dice con todas las\n *    letras y manda a los ajustes de la tienda, que es donde sí se quitan.\n *\n * 2. **Un hotel no acepta cualquier forma de pago de la tienda.** El servidor solo admite\n *    cinco (`transfer`, `deposit`, `in_store`, `billing`, `likebook_wallet`) y rechaza el\n *    resto con `PAYMENT_METHOD_INVALID`. La tienda de pruebas tenía «efectivo contra\n *    entrega» activo, que un hotel no puede ofrecer: aquí solo se enseñan las cinco válidas\n *    — y si la tienda tiene otras, se avisa sin ofrecerlas.\n *\n * El nombre, la ciudad y el logo NO se tocan aquí: son de la tienda y se editan en sus\n * ajustes. Duplicarlos sería tener dos sitios que escriben lo mismo.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Switch, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { hotelApi, type HotelProfile } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\n\nconst TIPOS: { id: string; label: string }[] = [\n  { id: 'hotel', label: 'Hotel' },\n  { id: 'hostal', label: 'Hostal' },\n  { id: 'guest_house', label: 'Casa de huéspedes' },\n  { id: 'apartahotel', label: 'Apartahotel' },\n  { id: 'resort', label: 'Resort' },\n  { id: 'motel', label: 'Motel' },\n];\n\nconst SERVICIOS: { id: string; label: string }[] = [\n  { id: 'wifi', label: 'Wi-Fi' }, { id: 'desayuno', label: 'Desayuno' },\n  { id: 'aire', label: 'Aire acondicionado' }, { id: 'piscina', label: 'Piscina' },\n  { id: 'parking', label: 'Aparcamiento' }, { id: 'restaurante', label: 'Restaurante' },\n  { id: 'bar', label: 'Bar' }, { id: 'gimnasio', label: 'Gimnasio' },\n  { id: 'recepcion_24h', label: 'Recepción 24 h' }, { id: 'agua_caliente', label: 'Agua caliente' },\n  { id: 'generador', label: 'Generador eléctrico' }, { id: 'lavanderia', label: 'Lavandería' },\n  { id: 'tv', label: 'Televisión' }, { id: 'terraza', label: 'Terraza' },\n  { id: 'ascensor', label: 'Ascensor' }, { id: 'admite_mascotas', label: 'Admite mascotas' },\n  { id: 'adaptado', label: 'Adaptado' }, { id: 'cocina', label: 'Cocina' },\n  { id: 'nevera', label: 'Nevera' }, { id: 'caja_fuerte', label: 'Caja fuerte' },\n  { id: 'seguridad', label: 'Vigilancia' },\n];\n\n/** Las ÚNICAS que el servidor acepta en un hotel (las demás dan PAYMENT_METHOD_INVALID). */\nconst PAGOS: { id: string; label: string; hint: string }[] = [\n  { id: 'transfer', label: 'Transferencia / Orange Money', hint: 'El huésped envía la referencia y tú confirmas el cobro' },\n  { id: 'deposit', label: 'Señal o anticipo', hint: 'Reserva con una parte y el resto al llegar' },\n  { id: 'in_store', label: 'Pago en recepción', hint: 'Se cobra al recibir al huésped' },\n  { id: 'billing', label: 'Billing', hint: 'Comprobante aprobado por la plataforma' },\n  { id: 'likebook_wallet', label: 'Monedero', hint: 'La señal se retiene en el monedero y el hotel la cobra al entrar' },\n];\n\nconst HORA = /^([01]\\d|2[0-3]):[0-5]\\d$/;\n\nexport default function PerfilHotelScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  const [hotel, setHotel] = useState<HotelProfile | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [guardando, setGuardando] = useState(false);\n  const [aviso, setAviso] = useState<string | null>(null);\n\n  const [tipo, setTipo] = useState('hotel');\n  const [estrellas, setEstrellas] = useState<number | null>(null);\n  const [entradaDesde, setEntradaDesde] = useState('14:00');\n  const [entradaHasta, setEntradaHasta] = useState('22:00');\n  const [salidaHasta, setSalidaHasta] = useState('12:00');\n  const [recepcion24, setRecepcion24] = useState(false);\n  const [impuestos, setImpuestos] = useState(true);\n  const [servicios, setServicios] = useState<string[]>([]);\n  const [normas, setNormas] = useState('');\n  // Cómo se entra y dónde está la recepción: lo que el huésped lee al llegar. Se escribe una vez.\n  const [llegada, setLlegada] = useState('');\n  const [cancelacion, setCancelacion] = useState('');\n  const [pagos, setPagos] = useState<string[]>([]);\n\n  const cargar = useCallback(async () => {\n    setCargando(true);\n    try {\n      const out = await hotelApi.myHotel();\n      const h = out.hotel;\n      if (!h) { setError('Todavía no tienes tienda. Créala en «Mi tienda» antes de configurar el alojamiento.'); return; }\n      setHotel(h);\n      setTipo(h.propertyKind ?? 'hotel');\n      setEstrellas(h.stars ?? null);\n      setEntradaDesde(h.checkinFrom || '14:00');\n      setEntradaHasta(h.checkinUntil || '22:00');\n      setSalidaHasta(h.checkoutUntil || '12:00');\n      setRecepcion24(!!h.receptionOpen24h);\n      setImpuestos(h.taxesIncluded !== false);\n      setServicios(h.amenities ?? []);\n      setNormas(h.houseRules ?? '');\n      setLlegada(h.arrivalNote ?? '');\n      setCancelacion(h.cancellationPolicy ?? '');\n      if (!h.isHotel) setAviso('Al guardar, tu tienda pasa a ser un alojamiento y aparecerá en el buscador de hotel.');\n      setError(null);\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar la ficha del hotel.');\n    } finally {\n      setCargando(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  /** Las que constan como activas en la tienda (llegan con su estado). */\n  const activosEnTienda = useMemo(() => {\n    const raw = hotel?.paymentMethods ?? [];\n    return raw\n      .map((m) => (typeof m === 'string' ? { method: m, status: 'active' } : m))\n      .filter((m) => m.status === 'active')\n      .map((m) => String(m.method));\n  }, [hotel]);\n\n  // Se marca como elegidas las que ya están activas Y son válidas para un hotel.\n  useEffect(() => {\n    setPagos(activosEnTienda.filter((m) => PAGOS.some((x) => x.id === m)));\n  }, [activosEnTienda]);\n\n  const otrosDeLaTienda = activosEnTienda.filter((m) => !PAGOS.some((x) => x.id === m));\n\n  const problema = useMemo((): string | null => {\n    if (!HORA.test(entradaDesde)) return 'La hora de entrada desde tiene que ser HH:MM (por ejemplo 14:00).';\n    if (!HORA.test(entradaHasta)) return 'La hora de entrada hasta tiene que ser HH:MM.';\n    if (!HORA.test(salidaHasta)) return 'La hora de salida tiene que ser HH:MM.';\n    if (entradaHasta <= entradaDesde) return 'La entrada «hasta» tiene que ser posterior a la entrada «desde».';\n    if (!pagos.length) return 'Elige al menos una forma de pago.';\n    return null;\n  }, [entradaDesde, entradaHasta, salidaHasta, pagos]);\n\n  const guardar = async () => {\n    if (problema) { Alert.alert('Revisa los datos', problema); return; }\n    setGuardando(true);\n    setAviso(null);\n    try {\n      const out = await hotelApi.saveHotel({\n        propertyKind: tipo,\n        ...(estrellas ? { stars: estrellas } : {}),\n        checkinFrom: entradaDesde, checkinUntil: entradaHasta, checkoutUntil: salidaHasta,\n        receptionOpen24h: recepcion24,\n        taxesIncluded: impuestos,\n        amenities: servicios,\n        houseRules: normas.trim() || undefined,\n        arrivalNote: llegada.trim() || undefined,\n        cancellationPolicy: cancelacion.trim() || undefined,\n        paymentMethods: pagos,\n      });\n      setHotel(out.hotel);\n      setAviso('Ficha guardada. El huésped ya ve estos datos al buscar y al reservar.');\n    } catch (e) {\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo guardar la ficha.');\n    } finally {\n      setGuardando(false);\n    }\n  };\n\n  if (cargando) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.cabecera, { paddingTop: insets.top + 8, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" hitSlop={10} style={styles.volver}>\n          <Text style={{ color: colors.textPrimary, fontSize: 30, lineHeight: 32 }}>‹</Text>\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', flex: 1 }}>Ficha del hotel</Text>\n      </View>\n\n      {error ? (\n        <View style={{ padding: espaciado.e16 }}>\n          <Text style={{ color: colors.textSecondary, marginBottom: espaciado.e12 }}>{error}</Text>\n          <GhostButton title=\"Reintentar\" onPress={() => void cargar()} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }} keyboardShouldPersistTaps=\"handled\">\n          {aviso ? (\n            <View style={[styles.aviso, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.25) }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 19 }}>{aviso}</Text>\n            </View>\n          ) : null}\n\n          {/* Lo que viene de la tienda */}\n          <View style={[styles.caja, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '900' }}>{hotel?.name ?? 'Tu alojamiento'}</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>\n              {[hotel?.barrio, hotel?.city, hotel?.region].filter(Boolean).join(' · ') || 'Sin dirección'}\n              {hotel?.isVerified ? ' · ✅ Tienda verificada' : ''}\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6, lineHeight: 17 }}>\n              El nombre, la dirección, el logo y la portada son de tu tienda: se cambian en «Ajustes de la tienda».\n            </Text>\n            <View style={{ marginTop: espaciado.e10 }}>\n              <GhostButton title=\"Ajustes de la tienda\" onPress={() => router.push('/lifebook-merchant-settings' as never)} />\n            </View>\n          </View>\n\n          <Bloque titulo=\"Tipo de alojamiento\" hint=\"Ayuda al huésped a saber qué esperar.\">\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 }}>\n              {TIPOS.map((t) => {\n                const on = tipo === t.id;\n                return (\n                  <Pressable\n                    key={t.id} onPress={() => setTipo(t.id)}\n                    style={[styles.chip, { backgroundColor: on ? colors.primary : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                  >\n                    <Text style={{ color: on ? brand.white : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{t.label}</Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n          </Bloque>\n\n          <Bloque titulo=\"Categoría\" hint=\"De 1 a 5 estrellas. Si no la tienes, déjalo sin marcar: no es obligatorio.\">\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n              {[1, 2, 3, 4, 5].map((n) => {\n                const on = estrellas === n;\n                return (\n                  <Pressable\n                    key={n} onPress={() => setEstrellas(on ? null : n)}\n                    accessibilityLabel={`${n} estrella(s)`}\n                    style={[styles.estrella, { borderColor: on ? colors.secondary : colors.border, backgroundColor: on ? alpha(colors.secondary, 0.12) : colors.surface }]}\n                  >\n                    <Text style={{ color: on ? colors.secondary : colors.textSecondary, fontSize: 15, fontWeight: '900' }}>{n}★</Text>\n                  </Pressable>\n                );\n              })}\n              {estrellas ? (\n                <Pressable\n                  onPress={() => setEstrellas(null)}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Quitar la categoría\"\n                  style={{ minHeight: 44, justifyContent: 'center', paddingHorizontal: espaciado.e6 }}\n                >\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>Quitar</Text>\n                </Pressable>\n              ) : null}\n            </View>\n          </Bloque>\n\n          <Bloque titulo=\"Horario de entrada y salida\" hint=\"Es lo primero que mira el huésped el día que llega.\">\n            <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Entrada desde\" value={entradaDesde} onChangeText={setEntradaDesde} placeholder=\"14:00\" maxLength={5} keyboardType=\"numbers-and-punctuation\" />\n              </View>\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Entrada hasta\" value={entradaHasta} onChangeText={setEntradaHasta} placeholder=\"22:00\" maxLength={5} keyboardType=\"numbers-and-punctuation\" />\n              </View>\n            </View>\n            <View style={{ height: 10 }} />\n            <FormField label=\"Salida hasta\" value={salidaHasta} onChangeText={setSalidaHasta} placeholder=\"12:00\" maxLength={5} keyboardType=\"numbers-and-punctuation\" />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e5, marginLeft: espaciado.e4 }}>\n              Formato de 24 horas: 14:00, no 2 PM.\n            </Text>\n            {/* Los dos interruptores van JUNTOS en una caja: sueltos parecían dos cosas\n                distintas y sin relación con el horario que tienen encima. */}\n            <View style={[styles.grupo, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <View style={styles.linea}>\n                <View style={{ flex: 1, paddingRight: espaciado.e12 }}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n                    Recepción abierta 24 horas\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                    Si está apagado, el huésped sabe que hay horas sin nadie en recepción.\n                  </Text>\n                </View>\n                <Switch value={recepcion24} onValueChange={setRecepcion24} trackColor={{ true: alpha(colors.primary, 0.5) }} />\n              </View>\n              <View style={[styles.linea, { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border }]}>\n                <View style={{ flex: 1, paddingRight: espaciado.e12 }}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n                    Los precios ya incluyen impuestos\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                    Evita sorpresas en el mostrador al hacer la cuenta.\n                  </Text>\n                </View>\n                <Switch value={impuestos} onValueChange={setImpuestos} trackColor={{ true: alpha(colors.primary, 0.5) }} />\n              </View>\n            </View>\n          </Bloque>\n\n          <Bloque titulo=\"Servicios del alojamiento\" hint=\"Marca solo lo que hay de verdad en el hotel.\">\n            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 }}>\n              {SERVICIOS.map((s) => {\n                const on = servicios.includes(s.id);\n                return (\n                  <Pressable\n                    key={s.id}\n                    onPress={() => setServicios((prev) => (on ? prev.filter((x) => x !== s.id) : [...prev, s.id]))}\n                    style={[styles.chip, { backgroundColor: on ? alpha(colors.primary, 0.12) : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                  >\n                    <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                      {on ? '✓ ' : ''}{s.label}\n                    </Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n          </Bloque>\n\n          <Bloque titulo=\"Al llegar\" hint=\"Cómo se entra y dónde está la recepción. Lo lee el huésped cuando baja del taxi, que es justo cuando más perdido está.\">\n            <FormField\n              value={llegada} onChangeText={setLlegada} multiline maxLength={600}\n              placeholder=\"Entrada por la puerta lateral, junto al parking. Recepción en el 2.º piso: si llegas de noche, timbre a la derecha.\"\n            />\n            <Contador actual={llegada.length} max={600} />\n            <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e4 }}>\n              Se enseña en la ficha del hotel, con el botón «Cómo llegar» y el taxi desde el aeropuerto.\n            </Text>\n          </Bloque>\n\n          <Bloque titulo=\"Normas de la casa\" hint=\"Se enseñan al reservar. Unas normas claras evitan discusiones en recepción.\">\n            <FormField\n              value={normas} onChangeText={setNormas} multiline maxLength={600}\n              placeholder=\"No fumar en las habitaciones. Silencio a partir de las 23:00. No se admiten visitas sin registrar.\"\n            />\n            <Contador actual={normas.length} max={600} />\n          </Bloque>\n\n          <Bloque titulo=\"Política de cancelación\" hint=\"Además del plazo en horas de cada habitación, aquí va lo que quieras dejar claro.\">\n            <FormField\n              value={cancelacion} onChangeText={setCancelacion} multiline maxLength={600}\n              placeholder=\"Cancelación gratuita hasta 48 h antes. Después, la señal no se devuelve.\"\n            />\n            <Contador actual={cancelacion.length} max={600} />\n          </Bloque>\n\n          <Bloque titulo=\"Formas de pago\" hint=\"Las que aceptas al reservar. Elige al menos una.\">\n            {PAGOS.map((m) => {\n              const on = pagos.includes(m.id);\n              return (\n                <Pressable\n                  key={m.id}\n                  onPress={() => setPagos((prev) => (on ? prev.filter((x) => x !== m.id) : [...prev, m.id]))}\n                  style={[styles.pago, { backgroundColor: on ? alpha(colors.primary, 0.08) : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                >\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n                      {on ? '✓ ' : ''}{m.label}\n                    </Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 16 }}>{m.hint}</Text>\n                  </View>\n                </Pressable>\n              );\n            })}\n\n            {otrosDeLaTienda.length ? (\n              <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e8, lineHeight: 17 }}>\n                ⚠️ Tu tienda tiene activa(s) {otrosDeLaTienda.join(', ')}, que un alojamiento no puede ofrecer.\n                No se enseñan al huésped.\n              </Text>\n            ) : null}\n\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8, lineHeight: 17 }}>\n              Aquí solo se pueden AÑADIR formas de pago. Para quitar una, entra en «Ajustes de la tienda»:\n              en la ficha del hotel, desmarcar no la desactiva (comprobado contra el servidor).\n            </Text>\n          </Bloque>\n\n          <View style={{ marginTop: espaciado.e8 }}>\n            <PrimaryButton title=\"Guardar la ficha\" onPress={() => void guardar()} loading={guardando} disabled={!!problema} />\n          </View>\n          {problema ? (\n            <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e10 }}>⚠️ {problema}</Text>\n          ) : null}\n\n          <View style={{ marginTop: espaciado.e16 }}>\n            <GhostButton title=\"Mis habitaciones\" onPress={() => router.push('/lifebook-hotel-habitaciones' as never)} />\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\n/**\n * Contador de caracteres.\n *\n * Existe por un motivo concreto: el servidor RECORTA en silencio estos campos a 600 caracteres\n * (`this.clean(dto.houseRules, 600)`). Sin contador, el hotelero escribe ochocientos caracteres,\n * la app los manda, el servidor guarda seiscientos y **el dueño no sabe que ha perdido texto**.\n * Mismo problema con el nombre (120) y la descripción (2000).\n */\nfunction Contador({ actual, max }: { actual: number; max: number }) {\n  const { colors } = useTheme();\n  const quedan = max - actual;\n  return (\n    <Text\n      style={{\n        color: quedan <= 40 ? colors.secondary : colors.textSecondary,\n        fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6, marginLeft: espaciado.e4,\n      }}\n      accessibilityLiveRegion=\"polite\"\n    >\n      {quedan <= 40 ? `Te quedan ${quedan} caracteres` : `${actual} de ${max}`}\n    </Text>\n  );\n}\n\nfunction Bloque({ titulo, hint, children }: { titulo: string; hint?: string; children: React.ReactNode }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ marginTop: espaciado.e22 }}>\n      <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginBottom: espaciado.e3 }}>{titulo}</Text>\n      {hint ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>{hint}</Text> : <View style={{ height: 7 }} />}\n      {children}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e4,\n    paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  volver: { width: 40, height: 34, alignItems: 'center', justifyContent: 'center' },\n  aviso: { borderWidth: 1, borderRadius: radios.md, padding: espaciado.e11, marginBottom: espaciado.e4 },\n  caja: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e14 },\n  // Objetivos táctiles de 44 px como mínimo (un chip de 33 px se falla con el dedo).\n  chip: { borderWidth: 1.5, borderRadius: radios.full, paddingHorizontal: espaciado.e13, minHeight: 44, justifyContent: 'center' },\n  estrella: {\n    borderWidth: 1.5, borderRadius: radios.md, minHeight: 44, minWidth: 54,\n    alignItems: 'center', justifyContent: 'center',\n  },\n  linea: {\n    flexDirection: 'row', alignItems: 'center',\n    paddingVertical: espaciado.e11,\n  },\n  grupo: { borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e12, marginTop: espaciado.e12 },\n  pago: { borderWidth: 1.5, borderRadius: radios.md, padding: espaciado.e11, marginBottom: espaciado.e8, flexDirection: 'row', alignItems: 'center' },\n});\n","/**\n * lifebook-hotel-reserva — DETALLE DE UNA RESERVA (vista del huésped).\n *\n * Es la pantalla que el bloque recibido llamaba `(hotel)/reservation/[id].tsx`, hecha con\n * las reglas de la casa y contra las rutas que existen:\n *\n *   · **Ruta plana** (`/lifebook-hotel-reserva?id=…`): un grupo `(hotel)` no aparece en la\n *     URL y habría dejado la pantalla en `/reservation/+id`.\n *   · **Los datos reales del servidor**: `GET …/reservations/:id` (con la puerta de\n *     huésped/hotel/admin) — no `my-reservations`, que no existe.\n *   · **Cancelar pide MOTIVO** (`PATCH …/reservations/:id/action` con `{action, reason}`) y\n *     el servidor borra las noches ocupadas: la habitación vuelve al calendario. Antes el\n *     bloque cancelaba sin motivo y **dejaba la habitación bloqueada**.\n *   · **No hay «pagar el resto»**: el resto se cobra en recepción al hacer el check-out, y\n *     la señal la confirma **el hotel** (con rastro de quién y con qué). Un botón que\n *     marcara «pagado» desde la app del huésped sería regalarse la habitación.\n *   · **El pago parcial se explica**: señal ahora (con cuenta atrás de la retención) y\n *     resto al llegar, con el desglose y el **campo para pegar la referencia** de la\n *     transferencia (que es como se paga de verdad aquí).\n *   · **El mapa es el del proyecto** (`MapBackground`: MapLibre auto-hospedado con pin,\n *     carga y «Reintentar»), no un WebView contra CDNs ajenos.\n *   · La línea de tiempo **incluye la retención** (`hold`), que era el estado que faltaba\n *     y dejaba la barra sin ningún punto encendido.\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Platform, Pressable, RefreshControl, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, altura, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport MapBackground from '../components/MapBackground';\nimport { PhotoGallery } from '../components/PhotoGallery';\nimport { hotelApi, METODO_ETIQUETA, PAGO_ETIQUETA, type Reservation } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { absUrl } from '../api/config';\nimport {\n  RESERVATION_STATUS_LABELS, type ReservationStatus,\n} from '@egrouteplan/contracts';\nimport { countdown, longDate, shortDate, xaf } from '../utils/datetime';\n\nconst POLL_MS = 20_000;\n\n/** Pasos de la estancia. `hold` es el primero: la reserva retenida sin pagar la señal. */\nconst PASOS: { clave: string; etiqueta: string }[] = [\n  { clave: 'hold', etiqueta: 'Retenida' },\n  { clave: 'pending', etiqueta: 'Señal pagada' },\n  { clave: 'confirmed', etiqueta: 'Confirmada' },\n  { clave: 'checked_in', etiqueta: 'Dentro' },\n  { clave: 'checked_out', etiqueta: 'Salida' },\n];\n\nexport default function HotelReservaDetalleScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const { id } = useLocalSearchParams<{ id: string }>();\n  const reservaId = String(id ?? '');\n\n  const [r, setR] = useState<Reservation | null>(null);\n  const [fotos, setFotos] = useState<string[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [aviso, setAviso] = useState<string | null>(null);\n  const [actuando, setActuando] = useState(false);\n  const [referencia, setReferencia] = useState('');\n  const [verMapa, setVerMapa] = useState(false);\n  const vivo = useRef(true);\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!reservaId) { setError('Falta el identificador de la reserva'); setCargando(false); return; }\n    if (!silencioso) setCargando(true);\n    try {\n      const out = await hotelApi.reservation(reservaId);\n      if (!vivo.current) return;\n      setR(out.reservation);\n      setError(null);\n    } catch (e) {\n      if (!vivo.current) return;\n      // El error se ENSEÑA (nada de «Cargando…» eterno por un fallo de red o de permisos).\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar la reserva.');\n    } finally {\n      if (vivo.current) { setCargando(false); setRefrescando(false); }\n    }\n  }, [reservaId]);\n\n  useEffect(() => {\n    vivo.current = true;\n    void cargar();\n    const t = setInterval(() => void cargar(true), POLL_MS);\n    return () => { vivo.current = false; clearInterval(t); };\n  }, [cargar]);\n\n  // Fotos reales de la habitación reservada (las sube el hotelero; el servidor las valida).\n  useEffect(() => {\n    const roomId = r?.roomTypeId;\n    if (!roomId) { setFotos([]); return; }\n    let v = true;\n    hotelApi.room(roomId)\n      .then(({ room }) => {\n        if (!v) return;\n        const urls = ((room.images ?? []) as { url?: string }[])\n          .map((i) => absUrl(i?.url))\n          .filter((u): u is string => !!u);\n        setFotos(urls);\n      })\n      .catch(() => { if (v) setFotos([]); });\n    return () => { v = false; };\n  }, [r?.roomTypeId]);\n\n  const estado = (r?.status ?? 'pending') as ReservationStatus;\n  const cancelada = estado === 'cancelled' || estado === 'no_show';\n  const viva = r ? (r.viva ?? false) : false;\n  const indicePaso = useMemo(() => PASOS.findIndex((p) => p.clave === estado), [estado]);\n\n  const puedeEnviarReferencia = !!r && r.role === 'guest' && r.paymentMethod === 'transfer'\n    && r.paymentStatus === 'pending' && viva;\n  const puedeCancelar = !!r && viva && !['checked_out', 'cancelled', 'no_show'].includes(estado);\n\n  const enviarReferencia = async () => {\n    if (!r || referencia.trim().length < 4) return;\n    setActuando(true);\n    setAviso(null);\n    try {\n      const out = await hotelApi.proof(r.id, referencia.trim());\n      setR(out.reservation);\n      setAviso('Referencia enviada. El hotel la comprobará y confirmará tu señal.');\n    } catch (e) {\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo enviar la referencia.');\n    } finally {\n      setActuando(false);\n    }\n  };\n\n  const cancelar = (motivo: string) => {\n    if (!r) return;\n    void (async () => {\n      setActuando(true);\n      setAviso(null);\n      try {\n        const out = await hotelApi.cancel(r.id, motivo);\n        setR(out.reservation);\n        setAviso('Reserva cancelada. La habitación vuelve a quedar libre.');\n        await cargar(true);\n      } catch (e) {\n        setAviso(e instanceof ApiError ? e.message : 'No se pudo cancelar la reserva.');\n      } finally {\n        setActuando(false);\n      }\n    })();\n  };\n\n  const pedirMotivo = () => {\n    if (Platform.OS === 'web') {\n      const m = typeof window !== 'undefined' ? window.prompt('Motivo de la cancelación (queda registrado)') : null;\n      if (m && m.trim().length >= 3) cancelar(m.trim());\n      return;\n    }\n    if (Platform.OS === 'ios' && Alert.prompt) {\n      Alert.prompt('Cancelar la reserva', 'Motivo (queda registrado en la reserva)', (m?: string) => {\n        if (m && m.trim().length >= 3) cancelar(m.trim());\n      }, 'plain-text');\n      return;\n    }\n    Alert.alert(\n      'Cancelar la reserva',\n      'Se cancelará y quedará registrado el motivo «Cancelada por el huésped». ¿Seguir?',\n      [\n        { text: 'No', style: 'cancel' },\n        { text: 'Sí, cancelar', style: 'destructive', onPress: () => cancelar('Cancelada por el huésped') },\n      ],\n    );\n  };\n\n  // ── Cargando / error (con salida siempre) ──\n  if (cargando && !r) {\n    return (\n      <View style={[styles.centro, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n        <Text style={[styles.sub, { color: colors.textSecondary }]}>Cargando la reserva…</Text>\n      </View>\n    );\n  }\n  if (!r) {\n    return (\n      <View style={[styles.centro, { backgroundColor: colors.background, padding: espaciado.e20 }]}>\n        <Text style={[styles.errorTxt, { color: colors.danger }]}>{error ?? 'Reserva no encontrada'}</Text>\n        <Pressable onPress={() => void cargar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n          <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n        </Pressable>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <Text style={[styles.enlace, { color: colors.textSecondary }]}>Volver</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  const hotel = r.hotel;\n  const puedeMapa = !!hotel?.lat && !!hotel?.lng;\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      <ScrollView\n        contentContainerStyle={{ paddingBottom: insets.bottom + 30 }}\n        refreshControl={\n          <RefreshControl refreshing={refrescando} onRefresh={() => { setRefrescando(true); void cargar(true); }} tintColor={colors.primary} />\n        }\n      >\n        {/* Fotos reales de la habitación */}\n        <PhotoGallery\n          photos={fotos}\n          height={220}\n          emptyLabel=\"La habitación no tiene fotos todavía\"\n          overlay={\n            <Pressable\n              onPress={() => router.back()}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Volver\"\n              hitSlop={12}\n              style={[styles.volverFlotante, { top: insets.top + 8 }]}\n            >\n              <Text style={styles.volverFlotanteTxt}>‹</Text>\n            </Pressable>\n          }\n        />\n\n        <View style={{ padding: espaciado.e14, gap: espaciado.e12 }}>\n          {/* ── Estado y línea de tiempo (con la retención incluida) ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.codigo, { color: colors.textPrimary }]}>{r.code}</Text>\n            <Text style={[styles.estado, { color: cancelada ? colors.danger : colors.primary }]}>\n              {RESERVATION_STATUS_LABELS[estado] ?? r.status}\n            </Text>\n\n            {!cancelada ? (\n              <View style={styles.pasos}>\n                {PASOS.map((p, i) => {\n                  const hecho = indicePaso >= 0 && i <= indicePaso;\n                  return (\n                    <View key={p.clave} style={styles.paso}>\n                      <View style={[styles.punto, { backgroundColor: hecho ? colors.primary : colors.border }]} />\n                      <Text style={[styles.pasoEtq, { color: hecho ? colors.textPrimary : colors.textSecondary }]}>\n                        {p.etiqueta}\n                      </Text>\n                      {i < PASOS.length - 1 ? (\n                        <View style={[styles.linea, { backgroundColor: i < indicePaso ? colors.primary : colors.border }]} />\n                      ) : null}\n                    </View>\n                  );\n                })}\n              </View>\n            ) : null}\n\n            {estado === 'hold' && r.holdExpiresAt ? (\n              <Text style={[styles.avisoTxt, { color: colors.danger }]}>\n                ⏳ Retenida {countdown(r.holdExpiresAt)} para pagar la señal ({xaf(r.depositXaf)}).\n                Si no se paga, la habitación se libera sola.\n              </Text>\n            ) : null}\n          </View>\n\n          {/* ── El hotel ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.nombre, { color: colors.textPrimary }]}>{hotel?.name ?? 'Alojamiento'}</Text>\n            <Text style={[styles.sub, { color: colors.textSecondary }]}>\n              {[hotel?.barrio, hotel?.city].filter(Boolean).join(' · ') || 'Guinea Ecuatorial'}\n            </Text>\n            {hotel?.addressReference ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>📍 {hotel.addressReference}</Text>\n            ) : null}\n            <View style={styles.botones}>\n              {puedeMapa ? (\n                <Pressable\n                  onPress={() => setVerMapa(true)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Ver el hotel en el mapa\"\n                  style={[styles.botonSec, { borderColor: colors.border, backgroundColor: colors.surface }]}\n                >\n                  <Text style={[styles.botonSecTxt, { color: colors.primary }]}>Ver en el mapa</Text>\n                </Pressable>\n              ) : null}\n              {r.guestId ? (\n                <Pressable\n                  onPress={() => router.push('/lifebook-messages' as never)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Chatear con el hotel\"\n                  style={[styles.botonSec, { borderColor: colors.border, backgroundColor: colors.surface }]}\n                >\n                  <Text style={[styles.botonSecTxt, { color: colors.primary }]}>Chatear con el hotel</Text>\n                </Pressable>\n              ) : null}\n            </View>\n          </View>\n\n          {/* ── Estancia ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>ESTANCIA</Text>\n            <Linea etiqueta=\"Habitación\" valor={r.roomName} />\n            <Linea etiqueta=\"Entrada\" valor={`${shortDate(r.checkIn, true)}${r.checkinFrom ? ` · desde ${r.checkinFrom}` : ''}`} />\n            <Linea etiqueta=\"Salida\" valor={`${shortDate(r.checkOut, true)}${r.checkoutUntil ? ` · hasta ${r.checkoutUntil}` : ''}`} />\n            <Linea etiqueta=\"Noches\" valor={String(r.nights)} />\n            <Linea etiqueta=\"Huéspedes\" valor={`${r.guests}${r.units > 1 ? ` · ${r.units} habitaciones` : ''}`} />\n            {r.freeCancellationUntil && viva ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                Cancelación gratuita hasta el {longDate(r.freeCancellationUntil.slice(0, 10))}.\n              </Text>\n            ) : null}\n          </View>\n\n          {/* ── Pago (desglose y estado del dinero, separado del estado de la reserva) ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>PAGO</Text>\n            <Linea etiqueta={`${r.nights} noche(s)${r.units > 1 ? ` × ${r.units}` : ''}`} valor={xaf(r.subtotalXaf)} />\n            {r.cleaningFeeXaf ? <Linea etiqueta=\"Limpieza\" valor={xaf(r.cleaningFeeXaf)} /> : null}\n            {r.taxesXaf ? <Linea etiqueta=\"Tasas\" valor={xaf(r.taxesXaf)} /> : null}\n            <Linea etiqueta=\"Total\" valor={xaf(r.totalXaf)} fuerte />\n            {r.depositXaf > 0 ? (\n              <>\n                <Linea etiqueta={`Señal (${r.depositPercent} %)`} valor={xaf(r.depositXaf)} color={colors.primary} fuerte />\n                <Linea etiqueta=\"Al llegar al hotel\" valor={xaf(r.remainingXaf)} color={colors.secondary} fuerte />\n              </>\n            ) : (\n              <Linea etiqueta=\"Se paga al llegar\" valor={xaf(r.totalXaf)} color={colors.secondary} fuerte />\n            )}\n            <Linea etiqueta=\"Forma de pago\" valor={METODO_ETIQUETA[r.paymentMethod] ?? r.paymentMethod} tenue />\n            <Linea etiqueta=\"Estado del pago\" valor={PAGO_ETIQUETA[r.paymentStatus] ?? r.paymentStatus} tenue />\n\n            {/* La referencia de la transferencia: así se paga la señal de verdad */}\n            {puedeEnviarReferencia ? (\n              <View style={{ gap: espaciado.e8, marginTop: espaciado.e8 }}>\n                <TextInput\n                  value={referencia}\n                  onChangeText={setReferencia}\n                  placeholder=\"Nº de operación de tu transferencia\"\n                  placeholderTextColor={colors.textSecondary}\n                  style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n                  accessibilityLabel=\"Referencia de la transferencia\"\n                />\n                <Pressable\n                  onPress={() => void enviarReferencia()}\n                  disabled={actuando || referencia.trim().length < 4}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Enviar la referencia\"\n                  accessibilityState={{ disabled: actuando || referencia.trim().length < 4 }}\n                  style={[styles.boton, {\n                    backgroundColor: referencia.trim().length < 4 ? colors.border : colors.primary,\n                  }]}\n                >\n                  {actuando ? <ActivityIndicator color={brand.white} /> : <Text style={styles.botonTxt}>Enviar referencia</Text>}\n                </Pressable>\n                <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                  El hotel comprueba la transferencia y confirma tu reserva. El resto ({xaf(r.remainingXaf)}) se\n                  paga en recepción.\n                </Text>\n              </View>\n            ) : null}\n          </View>\n\n          {/* ── Cancelación ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>CANCELACIÓN</Text>\n            {r.cancelReason ? (\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>Motivo registrado: {r.cancelReason}</Text>\n            ) : null}\n            {puedeCancelar ? (\n              <>\n                <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                  {r.freeCancellationUntil\n                    ? `Cancelación gratuita hasta el ${longDate(r.freeCancellationUntil.slice(0, 10))}.`\n                    : 'Consulta las condiciones del hotel antes de cancelar.'}\n                </Text>\n                <Pressable\n                  onPress={pedirMotivo}\n                  disabled={actuando}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Cancelar la reserva\"\n                  accessibilityState={{ disabled: actuando }}\n                  style={[styles.botonFantasma, { borderColor: colors.danger, opacity: actuando ? 0.5 : 1 }]}\n                >\n                  <Text style={[styles.botonFantasmaTxt, { color: colors.danger }]}>\n                    {actuando ? 'Cancelando…' : 'Cancelar la reserva'}\n                  </Text>\n                </Pressable>\n              </>\n            ) : (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                {cancelada ? 'Esta reserva ya está cerrada.' : 'Esta reserva ya no se puede cancelar desde la app.'}\n              </Text>\n            )}\n          </View>\n\n          {aviso ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>{aviso}</Text>\n            </View>\n          ) : null}\n          {error ? (\n            <Text style={[styles.errorTxt, { color: colors.danger }]}>{error}</Text>\n          ) : null}\n        </View>\n      </ScrollView>\n\n      {/* ── Mapa del hotel: el del proyecto (auto-hospedado), no un CDN ajeno ── */}\n      {verMapa && puedeMapa ? (\n        <View style={[StyleSheet.absoluteFill, { backgroundColor: colors.background }]}>\n          {/* `pin` es [longitud, latitud] y `initialCamera` centra el mapa ahí mismo. */}\n          <MapBackground\n            pin={[Number(hotel?.lng), Number(hotel?.lat)]}\n            initialCamera={{ centerCoordinate: [Number(hotel?.lng), Number(hotel?.lat)], zoomLevel: 15 }}\n          >\n            <View />\n          </MapBackground>\n          <Pressable\n            onPress={() => setVerMapa(false)}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Cerrar el mapa\"\n            style={[styles.cerrarMapa, { top: insets.top + 10, borderColor: colors.border }]}\n          >\n            <Text style={[styles.cerrarMapaTxt, { color: colors.textPrimary }]}>✕ Cerrar</Text>\n          </Pressable>\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\nfunction Linea({\n  etiqueta, valor, fuerte, tenue, color,\n}: { etiqueta: string; valor: string; fuerte?: boolean; tenue?: boolean; color?: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.linea}>\n      <Text style={[styles.lineaEtq, { color: tenue ? colors.textSecondary : colors.textPrimary, fontWeight: fuerte ? '700' : '500' }]}>\n        {etiqueta}\n      </Text>\n      <Text style={[styles.lineaVal, { color: color ?? colors.textPrimary, fontWeight: fuerte ? '800' : '600' }]}>\n        {valor}\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e10 },\n  sub: { fontSize: tipografia.caption, marginTop: espaciado.e4 },\n  errorTxt: { fontSize: tipografia.body, fontWeight: '700', textAlign: 'center' },\n  enlace: { fontSize: tipografia.body, fontWeight: '700', marginTop: espaciado.e6 },\n  bloque: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e3 },\n  etiqueta: { fontSize: 10.5, fontWeight: '800', letterSpacing: 0.6 },\n  codigo: { fontSize: 18, fontWeight: '800', letterSpacing: 0.6 },\n  estado: { fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e2 },\n  nombre: { fontSize: tipografia.subtitle, fontWeight: '800' },\n  pasos: { flexDirection: 'row', alignItems: 'center', marginTop: espaciado.e12 },\n  paso: { flexDirection: 'row', alignItems: 'center', flex: 1 },\n  punto: { width: 12, height: 12, borderRadius: 6 },\n  pasoEtq: { fontSize: 9.5, marginLeft: espaciado.e4, fontWeight: '600' },\n  linea: { flex: 1, height: 3, marginHorizontal: espaciado.e4 },\n  lineaEtq: { fontSize: tipografia.caption, flex: 1 },\n  lineaVal: { fontSize: tipografia.body },\n  avisoTxt: { fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e8 },\n  botones: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e8 },\n  botonSec: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8 },\n  botonSecTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  boton: { height: altura.control, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  botonTxt: { color: brand.white, fontSize: tipografia.body, fontWeight: '800' },\n  botonFantasma: { borderWidth: 1, borderRadius: radios.md, height: altura.control, alignItems: 'center', justifyContent: 'center', marginTop: espaciado.e8 },\n  botonFantasmaTxt: { fontSize: tipografia.body, fontWeight: '800' },\n  input: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: altura.control, fontSize: tipografia.body },\n  volverFlotante: {\n    position: 'absolute', left: 12, width: 36, height: 36, borderRadius: 18,\n    backgroundColor: 'rgba(0,0,0,0.45)', alignItems: 'center', justifyContent: 'center',\n  },\n  volverFlotanteTxt: { color: brand.white, fontSize: 24, fontWeight: '700', lineHeight: 26 },\n  cerrarMapa: { position: 'absolute', left: 14, borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, backgroundColor: brand.white },\n  cerrarMapaTxt: { fontSize: tipografia.body, fontWeight: '800' },\n});\n","/**\n * lifebook-hotel-reservar — CONFIRMAR la reserva con PAGO PARCIAL.\n *\n * Lo que corrige del boceto evaluado (tres fallos de lógica que costaban dinero):\n *   1. **El botón NO se activa sin disponibilidad**: se comprueba la disponibilidad\n *      de TODO el rango y con el número de habitaciones pedido (antes, con 1 libre\n *      y 3 pedidas seguía activo y el usuario se comía un 409).\n *   2. **La clave de idempotencia es ESTABLE por intento** (`reserveKey`): un doble\n *      toque no crea dos reservas (antes se generaba nueva en cada pulsación, así\n *      que la idempotencia no protegía de nada).\n *   3. **Los métodos de pago son los que acepta el hotel** (antes había una lista\n *      fija y el usuario elegía uno que el servidor rechazaba).\n *\n * Además: los importes los calcula SIEMPRE el servidor (aquí se enseña el desglose\n * del mismo modo que lo calcula él), la señal se puede bajar hasta 0 (pagar todo al\n * llegar) y tras reservar se muestra el CÓDIGO y la cuenta atrás de la retención.\n */\nimport React, { useCallback, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, altura, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { CalendarPicker, type CalendarDay } from '../components/CalendarPicker';\nimport {\n  hotelApi, reserveKey, resetReserveKey, METODO_ETIQUETA, type Reservation,\n} from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { absUrl } from '../api/config';\nimport { authApi } from '../api/auth';\nimport { PhotoGallery } from '../components/PhotoGallery';\nimport { useSession } from '../state/session';\nimport { addDaysIso, countdown, longDate, nightsBetween, todayIso, xaf } from '../utils/datetime';\n\nconst MAX_NOCHES = 92;\n\nexport default function HotelReservarScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const { phone: telefonoSesion } = useSession();\n  const p = useLocalSearchParams<{\n    roomTypeId: string; shopId?: string; shopName?: string;\n    checkIn?: string; checkOut?: string; guests?: string; units?: string;\n  }>();\n  const roomTypeId = String(p.roomTypeId ?? '');\n\n  const [checkIn, setCheckIn] = useState<string | null>(p.checkIn ?? null);\n  const [checkOut, setCheckOut] = useState<string | null>(p.checkOut ?? null);\n  const [huespedes, setHuespedes] = useState(Number(p.guests ?? 2));\n  const [habitaciones, setHabitaciones] = useState(Number(p.units ?? 1));\n\n  // La sesión no guarda el nombre: el huésped lo escribe (es quien se aloja, y\n  // puede reservar para otra persona). El teléfono sí se rellena de su cuenta.\n  const [nombre, setNombre] = useState('');\n  const [telefono, setTelefono] = useState(telefonoSesion ?? '');\n  const [email, setEmail] = useState('');\n  const [nota, setNota] = useState('');\n\n  React.useEffect(() => {\n    if (telefonoSesion && !telefono) setTelefono(telefonoSesion);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [telefonoSesion]);\n\n  /**\n   * Prellenado del perfil: nombre y teléfono de la cuenta. El usuario puede cambiarlos\n   * (se reserva muchas veces para otra persona), pero no tiene que escribirlos otra vez.\n   */\n  React.useEffect(() => {\n    let vivo = true;\n    authApi.me()\n      .then((perfil) => {\n        if (!vivo) return;\n        setNombre((n) => n || (perfil?.fullName ?? ''));\n        setTelefono((t) => t || (perfil?.phone ?? ''));\n        // El perfil no guarda correo (solo nombre, teléfono y datos de KYC): se deja vacío.\n      })\n      .catch(() => { /* sin perfil, se escribe a mano */ });\n    return () => { vivo = false; };\n  }, []);\n\n  const [metodo, setMetodo] = useState<string>('transfer');\n  const [pct, setPct] = useState<number | null>(null); // null = el del hotel\n\n  const [dias, setDias] = useState<CalendarDay[]>([]);\n  const [cargandoCal, setCargandoCal] = useState(true);\n  const [room, setRoom] = useState<{\n    name: string; minNights: number; maxNights: number; depositPercent: number;\n    holdMinutes: number; capacity: number; totalUnits: number; cleaningFeeXaf: number;\n    taxesXaf: number; basePriceXaf: number;\n    /** Fotos reales de la habitación (las sube el hotelero). */\n    images: string[];\n    /** Horario de llegada y normas del hotel: lo que el huésped necesita al reservar. */\n    checkinFrom: string | null; checkinUntil: string | null; checkoutUntil: string | null;\n    houseRules: string | null; cancellationPolicy: string | null;\n  } | null>(null);\n  const [metodos, setMetodos] = useState<string[]>([]);\n  const [nombreHotel, setNombreHotel] = useState(p.shopName ?? '');\n\n  const [enviando, setEnviando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [hecha, setHecha] = useState<Reservation | null>(null);\n  const [referencia, setReferencia] = useState('');\n  const [aviso, setAviso] = useState<string | null>(null);\n\n  // ── Carga de la habitación (precio, normas y formas de pago del hotel) ──\n  const cargar = useCallback(async () => {\n    setCargandoCal(true);\n    setError(null);\n    try {\n      const { room: r } = await hotelApi.room(roomTypeId);\n      setRoom({\n        name: r.name, minNights: r.minNights, maxNights: r.maxNights,\n        depositPercent: r.depositPercent, holdMinutes: r.holdMinutes, capacity: r.capacity,\n        totalUnits: r.totalUnits, cleaningFeeXaf: r.cleaningFeeXaf, taxesXaf: r.taxesXaf,\n        basePriceXaf: r.basePriceXaf,\n        images: ((r.images ?? []) as { url?: string }[]).map((i) => absUrl(i?.url)).filter((u): u is string => !!u),\n        checkinFrom: null, checkinUntil: null, checkoutUntil: null,\n        houseRules: null, cancellationPolicy: null,\n      });\n      setMetodos((r.paymentMethods ?? []).length ? r.paymentMethods : ['transfer', 'in_store']);\n      setMetodo((r.paymentMethods ?? []).includes('transfer') ? 'transfer' : (r.paymentMethods?.[0] ?? 'in_store'));\n      if (r.hotel?.name) setNombreHotel(r.hotel.name);\n      // Horario de llegada y normas del hotel: la ficha de la habitación no los trae,\n      // así que se piden a la ficha del alojamiento (una petición más, y con esto el\n      // huésped sabe a qué hora puede llegar ANTES de pagar la señal).\n      if (r.hotel?.id) {\n        try {\n          const h = await hotelApi.hotel(r.hotel.id);\n          setRoom((prev) => prev ? {\n            ...prev,\n            checkinFrom: h.hotel?.checkinFrom ?? null,\n            checkinUntil: h.hotel?.checkinUntil ?? null,\n            checkoutUntil: h.hotel?.checkoutUntil ?? null,\n            houseRules: h.hotel?.houseRules ?? null,\n            cancellationPolicy: h.hotel?.cancellationPolicy ?? null,\n          } : prev);\n        } catch { /* sin horario no se bloquea la reserva */ }\n      }\n      const cal = await hotelApi.calendar(roomTypeId, todayIso(), addDaysIso(todayIso(), MAX_NOCHES - 1), habitaciones);\n      setDias(cal.days ?? []);\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudo cargar la habitación.');\n    } finally {\n      setCargandoCal(false);\n    }\n  }, [roomTypeId, habitaciones]);\n\n  React.useEffect(() => { void cargar(); }, [cargar]);\n\n  // ── Disponibilidad del rango elegido, con el número de habitaciones pedido ──\n  const disponibilidad = useMemo(() => {\n    if (!checkIn || !checkOut) return { ok: false, motivo: 'Elige las fechas en el calendario' as string | null };\n    const noches = dias.filter((d) => d.date >= checkIn && d.date < checkOut);\n    const esperadas = nightsBetween(checkIn, checkOut);\n    if (noches.length !== esperadas || !noches.length) {\n      return { ok: false, motivo: 'Esas fechas están fuera del calendario disponible' };\n    }\n    const cerrada = noches.find((d) => d.closed);\n    if (cerrada) return { ok: false, motivo: `El hotel tiene cerrada la noche del ${cerrada.date}` };\n    const llena = noches.find((d) => Number(d.freeUnits) < habitaciones);\n    if (llena) {\n      return {\n        ok: false,\n        motivo: Number(llena.freeUnits) === 0\n          ? `Ya no queda hueco la noche del ${llena.date}`\n          : `Esa noche solo quedan ${llena.freeUnits} habitación(es) y pides ${habitaciones}`,\n      };\n    }\n    const min = Math.max(Number(room?.minNights ?? 1), ...noches.map((d) => Number(d.minNights ?? 1)));\n    if (esperadas < min) return { ok: false, motivo: `Esas fechas piden un mínimo de ${min} noche(s)` };\n    if (room && esperadas > room.maxNights) {\n      return { ok: false, motivo: `Como máximo ${room.maxNights} noche(s) por reserva` };\n    }\n    if (room && huespedes > room.capacity * habitaciones) {\n      return {\n        ok: false,\n        motivo: `En ${habitaciones} habitación(es) de ese tipo caben ${room.capacity * habitaciones} persona(s)`,\n      };\n    }\n    return { ok: true, motivo: null as string | null };\n  }, [checkIn, checkOut, dias, habitaciones, room, huespedes]);\n\n  // ── Cuenta (la calcula el servidor; aquí se reproduce igual para enseñarla) ──\n  const cuenta = useMemo(() => {\n    if (!checkIn || !checkOut || !room || !disponibilidad.ok) return null;\n    const noches = dias.filter((d) => d.date >= checkIn && d.date < checkOut).map((d) => d.priceXaf);\n    const nochesCount = nightsBetween(checkIn, checkOut);\n    const precioReferencia = Math.max(...noches); // el servidor usa el mayor (snapshot prudente)\n    const subtotal = precioReferencia * nochesCount * habitaciones;\n    const limpieza = room.cleaningFeeXaf * habitaciones;\n    const tasas = room.taxesXaf * habitaciones;\n    const total = subtotal + limpieza + tasas;\n    const pctFinal = Math.min(pct ?? room.depositPercent, room.depositPercent);\n    const senal = Math.round((total * pctFinal) / 100);\n    return {\n      noches: nochesCount, precioReferencia, media: Math.round(precioReferencia),\n      subtotal, limpieza, tasas, total, pct: pctFinal, senal, resto: total - senal,\n    };\n  }, [checkIn, checkOut, dias, room, habitaciones, pct, disponibilidad.ok]);\n\n  const firma = `${roomTypeId}|${checkIn ?? ''}|${checkOut ?? ''}|${habitaciones}|${huespedes}|${metodo}|${cuenta?.pct ?? ''}`;\n\n  const puedeConfirmar =\n    disponibilidad.ok && !!cuenta && nombre.trim().length >= 3 && telefono.replace(/\\D/g, '').length >= 6 && !enviando;\n\n  // ── Reservar ──\n  const reservar = async () => {\n    if (!puedeConfirmar || !cuenta || !checkIn || !checkOut) return;\n    setEnviando(true);\n    setError(null);\n    try {\n      const out = await hotelApi.reserve(\n        {\n          roomTypeId,\n          checkIn,\n          checkOut,\n          units: habitaciones,\n          guests: huespedes,\n          guestName: nombre.trim(),\n          guestPhone: telefono.trim(),\n          ...(email.trim() ? { guestEmail: email.trim() } : {}),\n          paymentMethod: metodo,\n          depositPercent: cuenta.pct,\n          ...(nota.trim() ? { note: nota.trim() } : {}),\n        },\n        reserveKey(firma),\n      );\n      resetReserveKey(); // la siguiente reserva es otra: clave nueva\n      setHecha(out.reservation);\n      await cargar(); // el calendario refleja las noches que se acaban de ocupar\n    } catch (e) {\n      setError(\n        e instanceof ApiError\n          ? e.code === 'ROOM_SOLD_OUT'\n            ? 'Alguien acaba de coger esas noches. Prueba otras fechas o pide otra habitación.'\n            : e.message\n          : 'No se pudo reservar. Revisa tu conexión.',\n      );\n    } finally {\n      setEnviando(false);\n    }\n  };\n\n  // ── Enviar la referencia de la transferencia ──\n  const enviarReferencia = async () => {\n    if (!hecha || referencia.trim().length < 4) return;\n    setAviso(null);\n    try {\n      const out = await hotelApi.proof(hecha.id, referencia.trim());\n      setHecha(out.reservation);\n      setAviso('Referencia enviada: el hotel la comprobará y confirmará tu señal.');\n    } catch (e) {\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo enviar la referencia.');\n    }\n  };\n\n  // ═══════════════════════ pantalla de reserva hecha ════════════════════════\n  if (hecha) {\n    const sinSenal = hecha.depositXaf <= 0;\n    return (\n      <View style={[styles.screen, { backgroundColor: colors.background, paddingTop: insets.top + 8 }]}>\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30, gap: espaciado.e12 }}>\n          <Text style={[styles.ok, { color: colors.success }]}>Reserva hecha</Text>\n          <Text style={[styles.codigo, { color: colors.textPrimary }]}>{hecha.code}</Text>\n          <Text style={[styles.sub, { color: colors.textSecondary }]}>\n            {nombreHotel || hecha.hotel?.name} · {hecha.roomName}\n          </Text>\n          <Text style={[styles.dato, { color: colors.textPrimary }]}>\n            {longDate(hecha.checkIn)} → {longDate(hecha.checkOut)} · {hecha.nights} noche(s)\n            {hecha.units > 1 ? ` · ${hecha.units} habitaciones` : ''}\n          </Text>\n\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Linea etiqueta=\"Total de la estancia\" valor={xaf(hecha.totalXaf)} fuerte />\n            {sinSenal ? (\n              <Linea etiqueta=\"Se paga al llegar al hotel\" valor={xaf(hecha.totalXaf)} color={colors.secondary} fuerte />\n            ) : (\n              <>\n                <Linea\n                  etiqueta={`Señal a pagar AHORA (${hecha.depositPercent}%)`}\n                  valor={xaf(hecha.depositXaf)}\n                  color={colors.primary}\n                  fuerte\n                />\n                <Linea etiqueta=\"Y al llegar al hotel\" valor={xaf(hecha.remainingXaf)} color={colors.secondary} fuerte />\n              </>\n            )}\n            <Linea etiqueta=\"Forma de pago\" valor={METODO_ETIQUETA[hecha.paymentMethod] ?? hecha.paymentMethod} />\n            <Linea\n              etiqueta=\"Estado\"\n              valor={hecha.paymentStatus === 'proof_submitted' ? 'Comprobante enviado' : hecha.status === 'hold' ? 'Retenida sin pagar' : hecha.status}\n            />\n            {hecha.holdExpiresAt && hecha.status === 'hold' ? (\n              <Text style={[styles.retencion, { color: colors.danger }]}>\n                ⏳ La habitación está retenida {countdown(hecha.holdExpiresAt)}. Si no se paga la señal,\n                se libera sola (no se te cobra nada).\n              </Text>\n            ) : null}\n          </View>\n\n          {!sinSenal && hecha.paymentStatus === 'pending' ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>\n                PAGA LA SEÑAL POR TRANSFERENCIA O EN RECEPCIÓN\n              </Text>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>\n                Haz la transferencia de {xaf(hecha.depositXaf)} con el código {hecha.code} como\n                referencia y pega aquí el número de operación. El hotel lo comprueba y confirma tu\n                reserva.\n              </Text>\n              <TextInput\n                value={referencia}\n                onChangeText={setReferencia}\n                placeholder=\"Nº de operación / referencia de la transferencia\"\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n                accessibilityLabel=\"Referencia de la transferencia\"\n              />\n              <Pressable\n                onPress={() => void enviarReferencia()}\n                disabled={referencia.trim().length < 4}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Enviar referencia\"\n                accessibilityState={{ disabled: referencia.trim().length < 4 }}\n                style={[styles.cta, {\n                  backgroundColor: referencia.trim().length < 4 ? colors.border : colors.primary,\n                }]}\n              >\n                <Text style={styles.ctaTxt}>Enviar referencia</Text>\n              </Pressable>\n              {aviso ? <Text style={[styles.sub, { color: colors.textSecondary }]}>{aviso}</Text> : null}\n            </View>\n          ) : null}\n\n          <Pressable\n            onPress={() => router.replace('/lifebook-hotel-reservas' as never)}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Ver mis reservas\"\n            style={[styles.cta, { backgroundColor: colors.primary }]}\n          >\n            <Text style={styles.ctaTxt}>Ver mis reservas</Text>\n          </Pressable>\n        </ScrollView>\n      </View>\n    );\n  }\n\n  // ═══════════════════════ formulario de reserva ════════════════════════════\n  return (\n    <KeyboardAvoidingView\n      style={[styles.screen, { backgroundColor: colors.background }]}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={styles.volver}>\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          {/* El nombre de la habitación lo escribe el hotelero: no se recorta a media palabra. */}\n          <Text style={[styles.titulo, { color: colors.textPrimary }]} numberOfLines={2}>\n            {room?.name ?? 'Habitación'}\n          </Text>\n          <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={1}>\n            {nombreHotel || 'Alojamiento'}\n          </Text>\n        </View>\n      </View>\n\n      {cargandoCal && !room ? (\n        <View style={styles.centro}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        <ScrollView contentContainerStyle={{ paddingBottom: insets.bottom + 120, gap: espaciado.e12 }} keyboardShouldPersistTaps=\"handled\">\n          {/* ── La habitación, con sus fotos reales ── */}\n          <PhotoGallery\n            photos={room?.images ?? []}\n            height={210}\n            emptyLabel=\"Esta habitación todavía no tiene fotos\"\n            overlay={\n              <Pressable\n                onPress={() => router.back()}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Volver\"\n                hitSlop={12}\n                style={[styles.volverFlotante, { top: insets.top + 8 }]}\n              >\n                <Text style={styles.volverFlotanteTxt}>‹</Text>\n              </Pressable>\n            }\n          />\n\n          <View style={{ paddingHorizontal: espaciado.e14, gap: espaciado.e12 }}>\n          {/* ── Horario de llegada y normas: lo que se pregunta al reservar ── */}\n          {room?.checkinFrom ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>CÓMO LLEGAR</Text>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>\n                🕐 Entrada de {room.checkinFrom} a {room.checkinUntil ?? '—'} · salida hasta {room.checkoutUntil ?? '—'}\n              </Text>\n              {room.cancellationPolicy ? (\n                <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                  Cancelación: {room.cancellationPolicy}\n                </Text>\n              ) : null}\n              {room.houseRules ? (\n                <Text style={[styles.sub, { color: colors.textSecondary }]}>Normas: {room.houseRules}</Text>\n              ) : null}\n            </View>\n          ) : null}\n\n          {/* ── 1. Fechas ── */}\n          <CalendarPicker\n            days={dias}\n            checkIn={checkIn}\n            checkOut={checkOut}\n            onChange={(a, b) => { setCheckIn(a); setCheckOut(b); }}\n            units={habitaciones}\n            minNights={room?.minNights ?? 1}\n            maxNights={Math.min(MAX_NOCHES, room?.maxNights ?? 30)}\n            loading={cargandoCal}\n            footer={\n              disponibilidad.motivo ? (\n                <Text style={[styles.aviso, { color: colors.danger }]}>{disponibilidad.motivo}</Text>\n              ) : cuenta ? (\n                <Text style={[styles.aviso, { color: colors.success }]}>\n                  ✓ Disponible: {cuenta.noches} noche(s) · {xaf(cuenta.media)} por noche\n                </Text>\n              ) : null\n            }\n          />\n\n          {/* ── 2. Habitaciones y huéspedes ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>HABITACIONES Y HUÉSPEDES</Text>\n            <Paso etiqueta=\"Habitaciones\" valor={habitaciones} min={1} max={Math.min(10, room?.totalUnits ?? 1)}\n              onCambio={setHabitaciones} />\n            <Paso etiqueta=\"Huéspedes\" valor={huespedes} min={1} max={Math.max(1, (room?.capacity ?? 2) * habitaciones)}\n              onCambio={setHuespedes} />\n            {room ? (\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                Quedan {room.totalUnits} habitación(es) de este tipo en total.\n              </Text>\n            ) : null}\n          </View>\n\n          {/* ── 3. Quién se aloja ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>QUIÉN SE ALOJA</Text>\n            <Campo etiqueta=\"Nombre y apellidos\" valor={nombre} onCambio={setNombre} placeholder=\"Como en tu documento\" />\n            <Campo etiqueta=\"Teléfono\" valor={telefono} onCambio={setTelefono} placeholder=\"+240 555 000 000\" keyboardType=\"phone-pad\" />\n            <Campo etiqueta=\"Correo (opcional)\" valor={email} onCambio={setEmail} placeholder=\"para el comprobante\" keyboardType=\"email-address\" />\n            <Campo etiqueta=\"Petición al hotel (opcional)\" valor={nota} onCambio={setNota} placeholder=\"Llegada tarde, cuna…\" />\n          </View>\n\n          {/* ── 4. Pago: método del hotel y señal ── */}\n          <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n            <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>CÓMO SE PAGA</Text>\n            <View style={styles.metodos}>\n              {metodos.map((m) => {\n                const activo = m === metodo;\n                return (\n                  <Pressable\n                    key={m}\n                    onPress={() => setMetodo(m)}\n                    accessibilityRole=\"button\"\n                    accessibilityState={{ selected: activo }}\n                    accessibilityLabel={METODO_ETIQUETA[m] ?? m}\n                    style={[styles.chip, {\n                      borderColor: activo ? colors.primary : colors.border,\n                      backgroundColor: activo ? alpha(colors.primary, 0.1) : colors.surface,\n                    }]}\n                  >\n                    <Text style={[styles.chipTxt, { color: activo ? colors.primary : colors.textSecondary }]}>\n                      {METODO_ETIQUETA[m] ?? m}\n                    </Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n\n            {room && room.depositPercent > 0 ? (\n              <>\n                <Text style={[styles.sub, { color: colors.textSecondary, marginTop: espaciado.e6 }]}>\n                  Señal: elige cuánto pagas ahora (el hotel pide hasta el {room.depositPercent} %).\n                  El resto, al llegar.\n                </Text>\n                <View style={styles.metodos}>\n                  {[room.depositPercent, Math.max(10, Math.round(room.depositPercent / 2)), 0].map((opcion) => {\n                    const activo = (pct ?? room.depositPercent) === opcion;\n                    return (\n                      <Pressable\n                        key={opcion}\n                        onPress={() => setPct(opcion)}\n                        accessibilityRole=\"button\"\n                        accessibilityState={{ selected: activo }}\n                        accessibilityLabel={opcion === 0 ? 'Sin señal, pagar todo al llegar' : `Señal del ${opcion} por ciento`}\n                        style={[styles.chip, {\n                          borderColor: activo ? colors.primary : colors.border,\n                          backgroundColor: activo ? alpha(colors.primary, 0.1) : colors.surface,\n                        }]}\n                      >\n                        <Text style={[styles.chipTxt, { color: activo ? colors.primary : colors.textSecondary }]}>\n                          {opcion === 0 ? 'Sin señal (todo al llegar)' : `${opcion} % ahora`}\n                        </Text>\n                      </Pressable>\n                    );\n                  })}\n                </View>\n              </>\n            ) : (\n              <Text style={[styles.sub, { color: colors.textSecondary, marginTop: espaciado.e6 }]}>\n                Este tipo de habitación se paga al llegar (sin señal).\n              </Text>\n            )}\n          </View>\n\n          {/* ── 5. Cuenta ── */}\n          {cuenta ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>CUENTA</Text>\n              <Linea etiqueta={`${cuenta.noches} noche(s) × ${habitaciones} habitación(es)`} valor={xaf(cuenta.subtotal)} />\n              <Linea etiqueta=\"Precio por noche\" valor={xaf(cuenta.precioReferencia)} tenue />\n              {cuenta.limpieza ? <Linea etiqueta=\"Limpieza\" valor={xaf(cuenta.limpieza)} /> : null}\n              {cuenta.tasas ? <Linea etiqueta=\"Tasas\" valor={xaf(cuenta.tasas)} /> : null}\n              <View style={[styles.separador, { backgroundColor: colors.border }]} />\n              <Linea etiqueta=\"Total de la estancia\" valor={xaf(cuenta.total)} fuerte />\n              {cuenta.senal > 0 ? (\n                <>\n                  <Linea etiqueta={`Pagas AHORA (señal ${cuenta.pct} %)`} valor={xaf(cuenta.senal)} color={colors.primary} fuerte />\n                  <Linea etiqueta=\"Pagas al llegar\" valor={xaf(cuenta.resto)} color={colors.secondary} fuerte />\n                </>\n              ) : (\n                <Linea etiqueta=\"Pagas todo al llegar\" valor={xaf(cuenta.total)} color={colors.secondary} fuerte />\n              )}\n              {cuenta.senal > 0 && room ? (\n                <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                  Al confirmar, la habitación queda retenida {room.holdMinutes} minutos mientras pagas la\n                  señal. Si no se paga, se libera sola.\n                </Text>\n              ) : null}\n            </View>\n          ) : null}\n\n          {error ? (\n            <View style={[styles.error, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n              <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>{error}</Text>\n            </View>\n          ) : null}\n          </View>\n        </ScrollView>\n      )}\n\n      {/* ── CTA fija: nunca activa si no hay disponibilidad ── */}\n      <View style={[styles.pie, { paddingBottom: insets.bottom + 10, borderTopColor: colors.border, backgroundColor: colors.card }]}>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.pieEtq, { color: colors.textSecondary }]}>\n            {cuenta ? (cuenta.senal > 0 ? `Ahora ${xaf(cuenta.senal)} · al llegar ${xaf(cuenta.resto)}` : 'Se paga al llegar') : 'Elige las fechas'}\n          </Text>\n          <Text style={[styles.pieTotal, { color: colors.textPrimary }]}>\n            {cuenta ? xaf(cuenta.total) : '—'}\n          </Text>\n        </View>\n        <Pressable\n          onPress={() => void reservar()}\n          disabled={!puedeConfirmar}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Confirmar reserva\"\n          accessibilityState={{ disabled: !puedeConfirmar, busy: enviando }}\n          style={[styles.confirmar, { backgroundColor: puedeConfirmar ? colors.primary : colors.border }]}\n        >\n          {enviando ? <ActivityIndicator color={brand.white} /> : <Text style={styles.ctaTxt}>Confirmar reserva</Text>}\n        </Pressable>\n      </View>\n    </KeyboardAvoidingView>\n  );\n}\n\n// ─────────────────────────── piezas ─────────────────────────────────────────\n\nfunction Linea({\n  etiqueta, valor, tenue, fuerte, color,\n}: { etiqueta: string; valor: string; tenue?: boolean; fuerte?: boolean; color?: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={styles.linea}>\n      <Text style={[styles.lineaEtq, { color: tenue ? colors.textSecondary : colors.textPrimary, fontWeight: fuerte ? '700' : '500' }]}>\n        {etiqueta}\n      </Text>\n      <Text style={[styles.lineaVal, { color: color ?? colors.textPrimary, fontWeight: fuerte ? '800' : '600' }]}>\n        {valor}\n      </Text>\n    </View>\n  );\n}\n\nfunction Paso({\n  etiqueta, valor, min, max, onCambio,\n}: { etiqueta: string; valor: number; min: number; max: number; onCambio: (v: number) => void }) {\n  const { colors } = useTheme();\n  const boton = (t: string, d: number, off: boolean) => (\n    <Pressable\n      onPress={() => !off && onCambio(Math.min(max, Math.max(min, valor + d)))}\n      disabled={off}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`${d > 0 ? 'Añadir' : 'Quitar'} ${etiqueta}`}\n      accessibilityState={{ disabled: off }}\n      style={[styles.pasoBtn, { borderColor: colors.border, backgroundColor: colors.surface, opacity: off ? 0.35 : 1 }]}\n    >\n      <Text style={[styles.pasoBtnTxt, { color: colors.textPrimary }]}>{t}</Text>\n    </Pressable>\n  );\n  return (\n    <View style={styles.linea}>\n      <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>{etiqueta}</Text>\n      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\n        {boton('−', -1, valor <= min)}\n        <Text style={[styles.pasoVal, { color: colors.textPrimary }]}>{valor}</Text>\n        {boton('+', 1, valor >= max)}\n      </View>\n    </View>\n  );\n}\n\nfunction Campo({\n  etiqueta, valor, onCambio, placeholder, keyboardType,\n}: {\n  etiqueta: string; valor: string; onCambio: (v: string) => void; placeholder?: string;\n  keyboardType?: 'default' | 'phone-pad' | 'email-address';\n}) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ marginTop: espaciado.e8 }}>\n      <Text style={[styles.sub, { color: colors.textSecondary }]}>{etiqueta}</Text>\n      <TextInput\n        value={valor}\n        onChangeText={onCambio}\n        placeholder={placeholder}\n        placeholderTextColor={colors.textSecondary}\n        keyboardType={keyboardType ?? 'default'}\n        style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n        accessibilityLabel={etiqueta}\n      />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  volverFlotante: {\n    position: 'absolute', left: 12, width: 36, height: 36, borderRadius: 18,\n    backgroundColor: 'rgba(0,0,0,0.45)', alignItems: 'center', justifyContent: 'center',\n  },\n  volverFlotanteTxt: { color: brand.white, fontSize: 24, fontWeight: '700', lineHeight: 26 },\n  barra: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1 },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  titulo: { fontSize: 16.5, fontWeight: '800' },\n  sub: { fontSize: tipografia.caption },\n  dato: { fontSize: tipografia.body, fontWeight: '600' },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  bloque: { borderWidth: 1, borderRadius: 18, padding: espaciado.e12, gap: espaciado.e3 },\n  etiqueta: { fontSize: 10.5, fontWeight: '800', letterSpacing: 0.6 },\n  linea: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e10, marginTop: espaciado.e6 },\n  lineaEtq: { fontSize: tipografia.caption, flex: 1 },\n  lineaVal: { fontSize: tipografia.body },\n  separador: { height: 1, marginVertical: espaciado.e7 },\n  input: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: altura.control, fontSize: 14.5, marginTop: espaciado.e4 },\n  metodos: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e8 },\n  chip: { borderWidth: 1, borderRadius: 20, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\n  chipTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  pasoBtn: { width: 34, height: 34, borderWidth: 1, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },\n  pasoBtnTxt: { fontSize: 18, fontWeight: '800', lineHeight: 20 },\n  pasoVal: { fontSize: 15, fontWeight: '800', minWidth: 22, textAlign: 'center' },\n  aviso: { fontSize: tipografia.caption, marginTop: espaciado.e8, fontWeight: '600' },\n  error: { borderWidth: 1, borderRadius: 14, padding: espaciado.e12 },\n  pie: {\n    position: 'absolute', left: 0, right: 0, bottom: 0, borderTopWidth: 1,\n    paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10, flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n  },\n  pieEtq: { fontSize: tipografia.micro },\n  pieTotal: { fontSize: tipografia.subtitle, fontWeight: '800' },\n  confirmar: { minWidth: 170, height: altura.campo, borderRadius: 14, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e14 },\n  cta: { height: altura.campo, borderRadius: 14, alignItems: 'center', justifyContent: 'center', marginTop: espaciado.e6 },\n  ctaTxt: { color: brand.white, fontSize: 15, fontWeight: '800' },\n  ok: { fontSize: tipografia.title, fontWeight: '800', marginTop: espaciado.e8 },\n  codigo: { fontSize: 26, fontWeight: '800', letterSpacing: 1 },\n  retencion: { fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6 },\n});\n","/**\n * lifebook-hotel-reservas — MIS RESERVAS (huésped) y, si eres hotelero, las de tu\n * hotel en el mismo sitio (`side=hotel`).\n *\n * Enseña lo que hace falta para no perderse: el **código** de la reserva, el estado\n * de la habitación y el **estado del dinero por separado** (sin cobrar · comprobante\n * enviado · señal cobrada · pagado · devuelto), la **cuenta atrás de la retención**\n * cuando aún no se ha pagado la señal, y las acciones que puede hacer cada parte:\n * enviar la referencia de la transferencia, cancelar **con motivo**, y —el hotel—\n * confirmar el cobro de la señal.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Platform, Pressable, RefreshControl, SectionList, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, altura, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport {\n  hotelApi, PAGO_ETIQUETA, RESERVA_ETIQUETA, METODO_ETIQUETA, type Reservation,\n} from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { countdown, longDate, shortDate, xaf } from '../utils/datetime';\n\nexport default function HotelReservasScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const p = useLocalSearchParams<{ side?: string }>();\n\n  const [lado, setLado] = useState<'guest' | 'hotel'>(p.side === 'hotel' ? 'hotel' : 'guest');\n  const [reservas, setReservas] = useState<Reservation[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [aviso, setAviso] = useState<string | null>(null);\n\n  // Comprobación de permisos: el hotelero solo ve su pestaña si tiene hotel.\n  const [esHotelero, setEsHotelero] = useState(false);\n  const [shopId, setShopId] = useState<string | null>(null);\n  const [ocupacionHoy, setOcupacionHoy] = useState<\n    { roomTypeId: string; name: string; totalUnits: number; occupied: number; free: number }[]\n  >([]);\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setCargando(true);\n    setError(null);\n    try {\n      const out = await hotelApi.mine(lado);\n      setReservas(out.reservations ?? []);\n      if (lado === 'hotel') {\n        try {\n          const mio = await hotelApi.myHotel();\n          setEsHotelero(!!mio.hotel);\n          setShopId(mio.hotel?.shopId ?? null);\n          if (mio.hotel?.shopId) {\n            const libro = await hotelApi.dayBook(mio.hotel.shopId);\n            setOcupacionHoy(libro.occupancy ?? []);\n          }\n        } catch { /* sin hotel: la pestaña de hotel queda vacía, no es un error */ }\n      } else {\n        try {\n          const mio = await hotelApi.myHotel();\n          setEsHotelero(!!mio.hotel);\n        } catch { setEsHotelero(false); }\n      }\n    } catch (e) {\n      setError(e instanceof ApiError ? e.message : 'No se pudieron cargar tus reservas.');\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n    }\n  }, [lado]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  // La retención se agota: se refresca el contador cada 30 s para que la cuenta\n  // atrás no se quede congelada.\n  const [, setTick] = useState(0);\n  useEffect(() => {\n    const id = setInterval(() => setTick((t) => t + 1), 30_000);\n    return () => clearInterval(id);\n  }, []);\n\n  const hoy = new Date(Date.now() + 3600e3).toISOString().slice(0, 10);\n  const enCurso = useMemo(\n    () => reservas.filter((r) => r.viva && r.checkIn <= hoy && r.checkOut > hoy),\n    [reservas, hoy],\n  );\n  const futuras = useMemo(\n    () => reservas.filter((r) => r.viva && r.checkIn > hoy),\n    [reservas, hoy],\n  );\n  const pasadas = useMemo(\n    () => reservas.filter((r) => !r.viva || r.checkOut <= hoy),\n    [reservas, hoy],\n  );\n\n  const accion = async (fn: () => Promise<{ reservation: Reservation }>, exito: string) => {\n    setAviso(null);\n    try {\n      await fn();\n      setAviso(exito);\n      await cargar(true);\n    } catch (e) {\n      setAviso(e instanceof ApiError ? e.message : 'No se pudo completar la acción.');\n    }\n  };\n\n  const cancelar = (r: Reservation) => {\n    if (Platform.OS === 'web') {\n      const motivo = window.prompt('Motivo de la cancelación (queda registrado)') ?? '';\n      if (motivo.trim().length < 3) return;\n      void accion(() => hotelApi.cancel(r.id, motivo.trim()), 'Reserva cancelada.');\n      return;\n    }\n    // En móvil se pide el motivo con el diálogo nativo (con campo de texto).\n    Alert.prompt?.(\n      'Cancelar reserva',\n      `Motivo para ${r.code} (queda registrado en la reserva)`,\n      (motivo?: string) => {\n        if (!motivo || motivo.trim().length < 3) return;\n        void accion(() => hotelApi.cancel(r.id, motivo.trim()), 'Reserva cancelada.');\n      },\n      'plain-text',\n    );\n    if (!Alert.prompt) {\n      // Android no tiene Alert.prompt: se cancela con un motivo por defecto editable\n      // en la pantalla de detalle (aquí se deja claro qué se registra).\n      Alert.alert(\n        'Cancelar reserva',\n        `Se cancelará ${r.code} y quedará registrado el motivo «Cancelada por el huésped». ¿Seguir?`,\n        [\n          { text: 'No', style: 'cancel' },\n          { text: 'Sí, cancelar', style: 'destructive', onPress: () => void accion(() => hotelApi.cancel(r.id, 'Cancelada por el huésped'), 'Reserva cancelada.') },\n        ],\n      );\n    }\n  };\n\n  const confirmarSenal = (r: Reservation) =>\n    void accion(() => hotelApi.confirmDeposit(r.id, 'Confirmado en recepción'), 'Señal confirmada: la reserva queda pendiente de tu confirmación final.');\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={styles.volver}>\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <Text style={[styles.titulo, { color: colors.textPrimary }]}>Reservas de hotel</Text>\n      </View>\n\n      {/* ── Pestañas: viajero / hotel ── */}\n      <View style={[styles.tabs, { borderBottomColor: colors.border }]}>\n        {(['guest', 'hotel'] as const).map((s) => {\n          const activo = lado === s;\n          return (\n            <Pressable\n              key={s}\n              onPress={() => setLado(s)}\n              accessibilityRole=\"tab\"\n              accessibilityState={{ selected: activo }}\n              accessibilityLabel={s === 'guest' ? 'Mis estancias' : 'Reservas de mi hotel'}\n              style={[styles.tab, { borderBottomColor: activo ? colors.primary : 'transparent' }]}\n            >\n              <Text style={[styles.tabTxt, { color: activo ? colors.primary : colors.textSecondary }]}>\n                {s === 'guest' ? 'Mis estancias' : 'Mi hotel'}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {cargando ? (\n        <View style={styles.centro}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        /*\n          LISTA VIRTUALIZADA POR SECCIONES (auditoría de diseño, D-04/D-21): antes era un\n          ScrollView con un bloque «Grupo» por sección y cada bloque con su .map(), así que\n          TODAS las reservas quedaban montadas. Aquí la sección es el grupo y la fila es la\n          reserva. `stickySectionHeadersEnabled` en false a propósito: los títulos nunca\n          fueron pegajosos. El hueco lo pone el `gap: espaciado.e12` del contenedor.\n        */\n        <SectionList\n          /*\n            Las secciones vacías se filtran a propósito: VirtualizedSectionList cuenta DOS\n            celdas por sección aunque no tenga filas (cabecera y pie, ver\n            @react-native/virtualized-lists/Lists/VirtualizedSectionList.js L178-180), así que\n            sin filtrar saldría un «En curso (0)» que antes NO se veía: el viejo componente\n            `Grupo` hacía `return null` cuando la lista venía vacía.\n          */\n          sections={[\n            { titulo: 'En curso', data: enCurso },\n            { titulo: 'Próximas', data: futuras },\n            { titulo: 'Historial', data: pasadas },\n          ].filter((s) => s.data.length > 0)}\n          keyExtractor={(r) => r.id}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 30, gap: espaciado.e12 }}\n          stickySectionHeadersEnabled={false}\n          refreshControl={\n            <RefreshControl refreshing={refrescando} onRefresh={() => { setRefrescando(true); void cargar(true); }} tintColor={colors.primary} />\n          }\n          renderSectionHeader={({ section }) => (\n            <Text style={[styles.seccion, { color: colors.textPrimary }]}>{section.titulo} ({section.data.length})</Text>\n          )}\n          renderItem={({ item: r }) => (\n            <Tarjeta\n              r={r}\n              lado={lado}\n              onCancelar={cancelar}\n              onConfirmarSenal={confirmarSenal}\n              onAbrir={(x) => router.push({ pathname: '/lifebook-hotel-reserva', params: { id: x.id } } as never)}\n            />\n          )}\n          ListHeaderComponent={\n            /*\n            Un `View` con el hueco del contenedor, y no un fragmento: el `gap` de\n            `contentContainerStyle` separa CELDAS, y `ListHeaderComponent` es UNA celda. Con un\n            fragmento, todo lo de aquí dentro quedaba pegado (era gap: espaciado.e12 antes de virtualizar).\n            */\n            <View style={{ gap: espaciado.e12 }}>\n          {aviso ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>{aviso}</Text>\n            </View>\n          ) : null}\n          {error ? (\n            <View style={[styles.bloque, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n              <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>{error}</Text>\n              <Pressable onPress={() => void cargar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n                <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n              </Pressable>\n            </View>\n          ) : null}\n\n          {/* ── Panel del hotelero: ocupación de hoy ── */}\n          {lado === 'hotel' && esHotelero && ocupacionHoy.length ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>OCUPACIÓN DE HOY</Text>\n              {ocupacionHoy.map((o) => (\n                <View key={o.roomTypeId} style={styles.linea}>\n                  <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>{o.name}</Text>\n                  <Text style={[styles.lineaVal, { color: o.occupied >= o.totalUnits ? colors.danger : colors.success }]}>\n                    {o.occupied}/{o.totalUnits} ocupadas · {o.free} libres\n                  </Text>\n                </View>\n              ))}\n            </View>\n          ) : null}\n\n          {lado === 'hotel' && !esHotelero ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>\n                Aquí aparecerán las reservas de tu hotel cuando publiques sus habitaciones.\n              </Text>\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                El hospedaje se configura desde la tienda de Life Book (ficha del alojamiento,\n                habitaciones, precios y calendario).\n              </Text>\n            </View>\n          ) : null}\n\n          {reservas.length === 0 && !error ? (\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.sub, { color: colors.textPrimary }]}>\n                {lado === 'guest' ? 'Todavía no has reservado ninguna estancia.' : 'Tu hotel no tiene reservas todavía.'}\n              </Text>\n              {lado === 'guest' ? (\n                <Pressable onPress={() => router.replace('/lifebook-hotel' as never)} accessibilityRole=\"button\" accessibilityLabel=\"Buscar alojamiento\">\n                  <Text style={[styles.enlace, { color: colors.primary }]}>Buscar alojamiento</Text>\n                </Pressable>\n              ) : null}\n            </View>\n          ) : null}\n\n            </View>\n          }\n        />\n      )}\n    </View>\n  );\n}\n\nfunction Tarjeta({\n  r, lado, onCancelar, onConfirmarSenal, onAbrir,\n}: {\n  r: Reservation;\n  lado: 'guest' | 'hotel';\n  onCancelar: (r: Reservation) => void;\n  onConfirmarSenal: (r: Reservation) => void;\n  onAbrir: (r: Reservation) => void;\n}) {\n  const { colors } = useTheme();\n  const [ref, setRef] = useState('');\n  const [enviando, setEnviando] = useState(false);\n  const [msg, setMsg] = useState<string | null>(null);\n\n  const colorEstado = r.status === 'cancelled' || r.status === 'no_show'\n    ? colors.textSecondary\n    : r.status === 'checked_out'\n      ? colors.success\n      : r.status === 'hold'\n        ? colors.danger\n        : colors.primary;\n\n  const puedeEnviarRef = r.role === 'guest' && r.paymentMethod === 'transfer'\n    && r.paymentStatus === 'pending' && r.status === 'hold';\n  const puedeConfirmarSenal = r.role === 'hotel' && ['hold', 'pending'].includes(r.status)\n    && r.paymentStatus !== 'deposit_paid' && r.depositXaf > 0;\n  const puedeCancelar = r.viva && !['checked_out', 'cancelled', 'no_show'].includes(r.status);\n\n  const enviar = async () => {\n    if (ref.trim().length < 4) return;\n    setEnviando(true);\n    setMsg(null);\n    try {\n      await hotelApi.proof(r.id, ref.trim());\n      setMsg('Referencia enviada. El hotel la comprobará.');\n    } catch (e) {\n      setMsg(e instanceof ApiError ? e.message : 'No se pudo enviar.');\n    } finally {\n      setEnviando(false);\n    }\n  };\n\n  return (\n    <View style={[styles.card, { borderColor: colors.border, backgroundColor: colors.card }]}>\n      {/* Tocar la cabecera abre el DETALLE de la reserva (estado, habitación con fotos,\n          pago, referencia y cancelación en una sola pantalla). */}\n      <Pressable\n        onPress={() => onAbrir(r)}\n        accessibilityRole=\"button\"\n        accessibilityLabel={`Ver el detalle de la reserva ${r.code}`}\n      >\n      <View style={styles.linea}>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.codigo, { color: colors.textPrimary }]}>{r.code}</Text>\n          {/* Nombre del huésped / del hotel y de la habitación: son textos de personas, no etiquetas. */}\n          <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={2}>\n            {lado === 'hotel' ? `${r.guest?.name ?? 'Huésped'}${r.guest?.phone ? ` · ${r.guest.phone}` : ''}` : (r.hotel?.name ?? 'Hotel')}\n            {' · '}{r.roomName}\n          </Text>\n        </View>\n        <View style={[styles.badge, { backgroundColor: alpha(colorEstado, 0.12), borderColor: colorEstado }]}>\n          <Text style={[styles.badgeTxt, { color: colorEstado }]}>{RESERVA_ETIQUETA[r.status] ?? r.status}</Text>\n        </View>\n      </View>\n\n      <Text style={[styles.dato, { color: colors.textPrimary }]}>\n        {shortDate(r.checkIn, true)} → {shortDate(r.checkOut, true)} · {r.nights} noche(s)\n        {r.units > 1 ? ` · ${r.units} habitaciones` : ''} · {r.guests} huésped(es)\n      </Text>\n      </Pressable>\n\n      <View style={[styles.dinero, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n        <View style={styles.linea}>\n          <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Total</Text>\n          <Text style={[styles.lineaVal, { color: colors.textPrimary, fontWeight: '800' }]}>{xaf(r.totalXaf)}</Text>\n        </View>\n        {r.depositXaf > 0 ? (\n          <>\n            <View style={styles.linea}>\n              <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Señal ({r.depositPercent} %)</Text>\n              <Text style={[styles.lineaVal, { color: colors.primary, fontWeight: '800' }]}>{xaf(r.depositXaf)}</Text>\n            </View>\n            <View style={styles.linea}>\n              <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Al llegar</Text>\n              <Text style={[styles.lineaVal, { color: colors.secondary, fontWeight: '800' }]}>{xaf(r.remainingXaf)}</Text>\n            </View>\n          </>\n        ) : (\n          <View style={styles.linea}>\n            <Text style={[styles.lineaEtq, { color: colors.textPrimary }]}>Se paga al llegar</Text>\n            <Text style={[styles.lineaVal, { color: colors.secondary, fontWeight: '800' }]}>{xaf(r.totalXaf)}</Text>\n          </View>\n        )}\n        <View style={styles.linea}>\n          <Text style={[styles.lineaEtq, { color: colors.textSecondary }]}>Dinero</Text>\n          <Text style={[styles.lineaVal, { color: colors.textSecondary }]}>\n            {PAGO_ETIQUETA[r.paymentStatus] ?? r.paymentStatus} · {METODO_ETIQUETA[r.paymentMethod] ?? r.paymentMethod}\n          </Text>\n        </View>\n      </View>\n\n      {r.status === 'hold' && r.holdExpiresAt ? (\n        <Text style={[styles.aviso, { color: colors.danger }]}>\n          ⏳ Retenida {countdown(r.holdExpiresAt)} para pagar la señal ({xaf(r.depositXaf)}).\n          Si no se paga, la habitación se libera sola.\n        </Text>\n      ) : null}\n      {r.freeCancellationUntil && r.viva ? (\n        <Text style={[styles.aviso, { color: colors.textSecondary }]}>\n          Cancelación gratuita hasta el {longDate(r.freeCancellationUntil.slice(0, 10))}.\n        </Text>\n      ) : null}\n      {r.cancelReason ? (\n        <Text style={[styles.aviso, { color: colors.textSecondary }]}>Motivo: {r.cancelReason}</Text>\n      ) : null}\n\n      {puedeEnviarRef ? (\n        <View style={{ gap: espaciado.e6, marginTop: espaciado.e8 }}>\n          <TextInput\n            value={ref}\n            onChangeText={setRef}\n            placeholder=\"Nº de operación de tu transferencia\"\n            placeholderTextColor={colors.textSecondary}\n            style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n            accessibilityLabel=\"Referencia de la transferencia\"\n          />\n          <Pressable\n            onPress={() => void enviar()}\n            disabled={enviando || ref.trim().length < 4}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Enviar referencia\"\n            accessibilityState={{ disabled: enviando || ref.trim().length < 4 }}\n            style={[styles.boton, { backgroundColor: ref.trim().length < 4 ? colors.border : colors.primary }]}\n          >\n            {enviando ? <ActivityIndicator color={brand.white} /> : <Text style={styles.botonTxt}>Enviar referencia</Text>}\n          </Pressable>\n        </View>\n      ) : null}\n\n      {puedeConfirmarSenal ? (\n        <Pressable\n          onPress={() => onConfirmarSenal(r)}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Confirmar la señal de ${r.code}`}\n          style={[styles.boton, { backgroundColor: colors.success, marginTop: espaciado.e8 }]}\n        >\n          <Text style={styles.botonTxt}>Confirmar señal recibida ({xaf(r.depositXaf)})</Text>\n        </Pressable>\n      ) : null}\n\n      {puedeCancelar ? (\n        <Pressable\n          onPress={() => onCancelar(r)}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Cancelar ${r.code}`}\n          style={[styles.botonFantasma, { borderColor: colors.border }]}\n        >\n          <Text style={[styles.botonFantasmaTxt, { color: colors.danger }]}>Cancelar reserva</Text>\n        </Pressable>\n      ) : null}\n\n      {msg ? <Text style={[styles.aviso, { color: colors.textSecondary }]}>{msg}</Text> : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  barra: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1 },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  titulo: { fontSize: 16.5, fontWeight: '800', flex: 1 },\n  tabs: { flexDirection: 'row', borderBottomWidth: 1 },\n  tab: { flex: 1, alignItems: 'center', paddingVertical: espaciado.e12, borderBottomWidth: 2 },\n  tabTxt: { fontSize: tipografia.body, fontWeight: '700' },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  bloque: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e4 },\n  etiqueta: { fontSize: 10.5, fontWeight: '800', letterSpacing: 0.6 },\n  seccion: { fontSize: 14.5, fontWeight: '800' },\n  card: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e4 },\n  codigo: { fontSize: 15.5, fontWeight: '800', letterSpacing: 0.5 },\n  sub: { fontSize: tipografia.caption },\n  dato: { fontSize: tipografia.body, marginTop: espaciado.e2 },\n  linea: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: espaciado.e10 },\n  lineaEtq: { fontSize: tipografia.caption, flex: 1 },\n  lineaVal: { fontSize: tipografia.body },\n  badge: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 },\n  badgeTxt: { fontSize: 10.5, fontWeight: '800' },\n  dinero: { borderWidth: 1, borderRadius: radios.md, padding: espaciado.e9, marginTop: espaciado.e6, gap: espaciado.e2 },\n  aviso: { fontSize: tipografia.caption, marginTop: espaciado.e6, fontWeight: '600' },\n  input: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: altura.punto, fontSize: tipografia.body },\n  boton: { height: altura.punto, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  botonTxt: { color: brand.white, fontSize: tipografia.body, fontWeight: '800' },\n  botonFantasma: { borderWidth: 1, borderRadius: radios.md, height: altura.punto, alignItems: 'center', justifyContent: 'center', marginTop: espaciado.e8 },\n  botonFantasmaTxt: { fontSize: tipografia.body, fontWeight: '800' },\n  enlace: { fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 },\n});\n","/**\n * lifebook-hotel-resultados — LA LISTA DE RESULTADOS de una búsqueda de alojamiento.\n *\n * Es la pantalla que en el boceto se llamaba `/(hotel)/results`. Se ha hecho así:\n *   · **Ruta plana con prefijo** (`/lifebook-hotel-resultados`), como el resto de Life\n *     Book: un grupo `(hotel)` no aparece en la URL, así que la pantalla habría quedado\n *     en `/results` — nombre genérico en la raíz de una app que ya tiene `/buscar` y\n *     `/lifebook-search` — y con `typedRoutes` la ruta inventada no compila.\n *   · **La misma tarjeta** que el buscador (`HotelResultCard`): una sola forma de pintar\n *     un resultado, no dos.\n *   · **Con errores y carga de verdad**: si la red falla se dice y se puede reintentar\n *     (nada de `catch {}` dejando la lista vacía como si no hubiera hoteles).\n *   · Recibe los filtros por parámetros y los reenvía a la API tal cual: el servidor es\n *     quien decide disponibilidad y precios.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Pressable, RefreshControl, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { HotelResultCard } from '../components/HotelResultCard';\nimport { hotelApi, type HotelRoom, type HotelSearchResult } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { nightsBetween, xaf } from '../utils/datetime';\n\nexport default function HotelResultadosScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const p = useLocalSearchParams<{\n    city?: string; checkIn?: string; checkOut?: string; guests?: string; units?: string;\n  }>();\n\n  const [ciudad, setCiudad] = useState(p.city ?? '');\n  const [huespedes] = useState(Number(p.guests ?? 2));\n  const [habitaciones] = useState(Number(p.units ?? 1));\n  const [datos, setDatos] = useState<HotelSearchResult | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  /**\n   * ── FILTRO DE PRECIO (hueco P0 nº1 del análisis Meituan) ──────────────────────\n   * Meituan documenta el precio como **filtro de primer nivel**, no como un extra, y la API ya lo\n   * admitía (`minPrice`/`maxPrice`, comprobado: `maxPrice=1` devuelve 0 hoteles). Solo faltaba la\n   * interfaz.\n   *\n   * Se separan los valores que se ESCRIBEN de los APLICADOS a propósito: si se buscara a cada\n   * tecla, escribir «25000» lanzaría cinco búsquedas y el usuario vería la lista parpadear.\n   *\n   * Y una cosa que NO se pone porque el servidor no la admite: **la ordenación**. `sort=price_asc`\n   * responde **400** (no está en el DTO de la búsqueda). Un control que devuelve 400 es peor que no\n   * tenerlo; queda anotado como pendiente de servidor.\n   */\n  const [filtroAbierto, setFiltroAbierto] = useState(false);\n  const [minTexto, setMinTexto] = useState('');\n  const [maxTexto, setMaxTexto] = useState('');\n  const [aplicado, setAplicado] = useState<{ min?: number; max?: number; error?: string }>({});\n\n  /** Lo que cuesta cada página. 20 como antes; el servidor lo llama `pageSize`. */\n  const POR_PAGINA = 20;\n  const [pagina, setPagina] = useState(1);\n  const [masCargando, setMasCargando] = useState(false);\n\n  const checkIn = p.checkIn ?? undefined;\n  const checkOut = p.checkOut ?? undefined;\n  const noches = checkIn && checkOut ? nightsBetween(checkIn, checkOut) : 0;\n\n  const cargar = useCallback(async (silencioso = false, pag = 1) => {\n    if (!silencioso) setCargando(true);\n    setError(null);\n    try {\n      const out = await hotelApi.search({\n        city: ciudad || undefined,\n        checkIn,\n        checkOut,\n        guests: huespedes,\n        units: habitaciones,\n        minPrice: aplicado.min,\n        maxPrice: aplicado.max,\n        page: pag,\n        limit: POR_PAGINA,\n      });\n      // Al paginar se ACUMULA; al buscar de nuevo se reemplaza. Si no, «Ver más» borraría lo\n      // que el usuario ya estaba mirando.\n      setDatos((prev) => (pag > 1 && prev ? { ...out, hotels: [...prev.hotels, ...(out.hotels ?? [])] } : out));\n      setPagina(pag);\n    } catch (e) {\n      // El error se ENSEÑA: un fallo de red no puede parecer «no hay hoteles».\n      setError(e instanceof ApiError ? e.message : 'No se pudo buscar. Revisa tu conexión.');\n      if (pag === 1) setDatos(null);\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n      setMasCargando(false);\n    }\n  }, [ciudad, checkIn, checkOut, huespedes, habitaciones, aplicado]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  /** Aplica el precio escrito. Se comprueba aquí para no mandar basura al servidor. */\n  const aplicarFiltro = () => {\n    const num = (t: string) => {\n      const n = Number(String(t).replace(/[^\\d]/g, ''));\n      return String(t).trim() && Number.isFinite(n) && n > 0 ? n : undefined;\n    };\n    const min = num(minTexto);\n    const max = num(maxTexto);\n    if (min !== undefined && max !== undefined && max < min) {\n      setAplicado((a) => ({ ...a, error: 'El máximo no puede ser menor que el mínimo.' }));\n      return;\n    }\n    setAplicado({ min, max });\n    setFiltroAbierto(false);\n  };\n\n  const quitarFiltro = () => {\n    setMinTexto('');\n    setMaxTexto('');\n    setAplicado({});\n  };\n\n  const hayFiltro = aplicado.min !== undefined || aplicado.max !== undefined;\n\n  const abrirHabitacion = (room: HotelRoom, shopId: string, shopName: string) => {\n    router.push({\n      pathname: '/lifebook-hotel-reservar',\n      params: {\n        roomTypeId: room.id,\n        shopId,\n        shopName,\n        ...(checkIn ? { checkIn } : {}),\n        ...(checkOut ? { checkOut } : {}),\n        guests: String(huespedes),\n        units: String(habitaciones),\n      },\n    } as never);\n  };\n\n  const hoteles = datos?.hotels ?? [];\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" style={styles.volver}>\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.titulo, { color: colors.textPrimary }]} numberOfLines={1}>\n            {ciudad ? `Alojamiento en ${ciudad}` : 'Alojamiento'}\n          </Text>\n          <Text style={[styles.sub, { color: colors.textSecondary }]} numberOfLines={1}>\n            {checkIn && checkOut\n              ? `${checkIn} → ${checkOut} · ${noches} noche(s) · ${huespedes} huésped(es)${habitaciones > 1 ? ` · ${habitaciones} habitaciones` : ''}`\n              : 'Sin fechas: elige días para ver precios y disponibilidad'}\n          </Text>\n        </View>\n        <Pressable\n          onPress={() => router.push('/lifebook-hotel' as never)}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Cambiar la búsqueda\"\n          style={[styles.cambiar, { borderColor: colors.border }]}\n        >\n          <Text style={[styles.cambiarTxt, { color: colors.primary }]}>Cambiar</Text>\n        </Pressable>\n      </View>\n\n      {/*\n        ── BARRA DE FILTROS ──\n        El precio es filtro de PRIMER NIVEL en Meituan, así que va en una barra siempre visible y\n        no escondido en un menú. Cuando hay filtro puesto, se ve cuál: un filtro activo que no se\n        enseña hace que el usuario crea que «no hay hoteles» en vez de «no hay con ese precio».\n      */}\n      <View style={[styles.filtros, { borderBottomColor: colors.border }]}>\n        <Pressable\n          onPress={() => setFiltroAbierto((v) => !v)}\n          accessibilityRole=\"button\"\n          accessibilityLabel={hayFiltro ? 'Cambiar el filtro de precio' : 'Filtrar por precio'}\n          accessibilityState={{ expanded: filtroAbierto }}\n          style={[styles.chip, {\n            borderColor: hayFiltro ? colors.primary : colors.border,\n            backgroundColor: hayFiltro ? alpha(colors.primary, 0.12) : colors.surface,\n          }]}\n        >\n          <Text style={{ color: hayFiltro ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n            {hayFiltro\n              ? `Precio: ${aplicado.min !== undefined ? xaf(aplicado.min) : '0'} – ${aplicado.max !== undefined ? xaf(aplicado.max) : 'sin tope'}`\n              : '💰 Precio'}\n          </Text>\n        </Pressable>\n\n        {hayFiltro ? (\n          <Pressable\n            onPress={quitarFiltro}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Quitar el filtro de precio\"\n            style={[styles.chip, { borderColor: colors.border, backgroundColor: colors.surface }]}\n          >\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }}>Quitar</Text>\n          </Pressable>\n        ) : null}\n\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginLeft: 'auto' }}>por noche</Text>\n      </View>\n\n      {filtroAbierto ? (\n        <View style={[styles.panelFiltro, { borderBottomColor: colors.border, backgroundColor: colors.card }]}>\n          <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n            <View style={{ flex: 1 }}>\n              <FormField\n                label=\"Precio mínimo (XAF)\" value={minTexto} onChangeText={setMinTexto}\n                keyboardType=\"number-pad\" placeholder=\"Sin mínimo\"\n              />\n            </View>\n            <View style={{ flex: 1 }}>\n              <FormField\n                label=\"Precio máximo (XAF)\" value={maxTexto} onChangeText={setMaxTexto}\n                keyboardType=\"number-pad\" placeholder=\"Sin tope\"\n              />\n            </View>\n          </View>\n          {aplicado.error ? (\n            <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e8 }}>\n              ⚠ {aplicado.error}\n            </Text>\n          ) : null}\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 16, marginTop: espaciado.e8 }}>\n            Es el precio por noche. Deja un campo vacío para no poner tope por ese lado.\n          </Text>\n          {/*\n            Nota para quien venga: aquí NO hay control de ordenación porque el servidor no la\n            admite (`sort=price_asc` → 400, no está en el DTO de la búsqueda). Un control que\n            devuelve 400 es peor que no tenerlo. Queda pendiente de servidor.\n          */}\n          <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12 }}>\n            <View style={{ flex: 1 }}>\n              <PrimaryButton title=\"Buscar con este precio\" onPress={aplicarFiltro} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <GhostButton title=\"Limpiar\" onPress={quitarFiltro} />\n            </View>\n          </View>\n        </View>\n      ) : null}\n\n      {cargando ? (\n        <View style={styles.centro}>\n          <ActivityIndicator color={colors.primary} />\n          <Text style={[styles.sub, { color: colors.textSecondary }]}>Buscando disponibilidad…</Text>\n        </View>\n      ) : error ? (\n        <View style={[styles.aviso, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>{error}</Text>\n          <Pressable onPress={() => void cargar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n            <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <FlatList\n          data={hoteles}\n          keyExtractor={(item) => item.hotel.id}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 24, gap: espaciado.e12 }}\n          refreshControl={\n            <RefreshControl\n              refreshing={refrescando}\n              onRefresh={() => { setRefrescando(true); void cargar(true); }}\n              tintColor={colors.primary}\n            />\n          }\n          ListHeaderComponent={\n            hoteles.length ? (\n              <Text style={[styles.sub, { color: colors.textSecondary, marginBottom: espaciado.e4 }]}>\n                {hoteles.length} alojamiento(s)\n                {hoteles.some((h) => h.soldOut) ? ' · los marcados «sin disponibilidad» no tienen hueco en esas fechas' : ''}\n              </Text>\n            ) : null\n          }\n          ListFooterComponent={\n            /*\n              Paginación. `hasMore` puede venir AUSENTE (el servidor hace un `return` temprano sin\n              los campos de paginación cuando no hay hoteles), así que se trata «ausente» como «no\n              hay más»: un botón «Ver más» que no trae nada es peor que no tenerlo.\n            */\n            datos?.hasMore && hoteles.length ? (\n              <View style={{ marginTop: espaciado.e8 }}>\n                <GhostButton\n                  title={masCargando ? 'Buscando más…' : 'Ver más alojamientos'}\n                  onPress={() => { setMasCargando(true); void cargar(true, pagina + 1); }}\n                  disabled={masCargando}\n                />\n              </View>\n            ) : null\n          }\n          ListEmptyComponent={\n            <View style={[styles.vacio, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={[styles.vacioTitulo, { color: colors.textPrimary }]}>\n                No hay alojamiento con esos datos\n              </Text>\n              <Text style={[styles.sub, { color: colors.textSecondary }]}>\n                Prueba otras fechas, otra ciudad o menos habitaciones. Los hoteles sin hueco sí\n                aparecen marcados como «sin disponibilidad», así que puedes ajustar el rango.\n              </Text>\n              <Pressable onPress={() => router.push('/lifebook-hotel' as never)} accessibilityRole=\"button\" accessibilityLabel=\"Cambiar la búsqueda\">\n                <Text style={[styles.enlace, { color: colors.primary }]}>Cambiar la búsqueda</Text>\n              </Pressable>\n            </View>\n          }\n          renderItem={({ item }) => (\n            <HotelResultCard\n              datos={item}\n              habitaciones={habitaciones}\n              listo={!!(checkIn && checkOut)}\n              onAbrir={() => router.push({\n                pathname: '/lifebook-hotel-detalle',\n                params: {\n                  id: item.hotel.id,\n                  ...(checkIn ? { checkIn } : {}),\n                  ...(checkOut ? { checkOut } : {}),\n                  guests: String(huespedes),\n                  units: String(habitaciones),\n                },\n              } as never)}\n              onReservar={(room) => abrirHabitacion(room, item.hotel.id, item.hotel.name)}\n            />\n          )}\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  barra: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1 },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  titulo: { fontSize: 16.5, fontWeight: '800' },\n  sub: { fontSize: tipografia.caption },\n  cambiar: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e7 },\n  cambiarTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  centro: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e8 },\n  aviso: { margin: espaciado.e14, borderWidth: 1, borderRadius: 14, padding: espaciado.e12, gap: espaciado.e6 },\n  enlace: { fontSize: tipografia.caption, fontWeight: '700' },\n  vacio: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e14, gap: espaciado.e6 },\n  vacioTitulo: { fontSize: 14.5, fontWeight: '800' },\n  // Barra de filtros y panel: el precio es filtro de primer nivel, va siempre a la vista.\n  filtros: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e9, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  // 44 px de alto mínimo: un chip de 33 px se falla con el dedo.\n  chip: { borderWidth: 1.5, borderRadius: radios.full, paddingHorizontal: espaciado.e13, minHeight: 44, justifyContent: 'center' },\n  panelFiltro: { paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e14, borderBottomWidth: StyleSheet.hairlineWidth },\n});\n","/**\n * HotelResultCard — LA TARJETA DE UN ALOJAMIENTO EN LOS RESULTADOS.\n *\n * Vive aparte porque la usan DOS pantallas: el buscador (`/lifebook-hotel`, que lleva\n * el calendario y los filtros) y los resultados (`/lifebook-hotel-resultados`). Antes\n * cada pantalla habría tenido su propia tarjeta, y ya sabemos cómo acaba eso: dos\n * formas de lo mismo que se desincronizan.\n *\n * Lo que enseña, y por qué:\n *   · por habitación, **el TOTAL de la estancia** y el reparto **«ahora + al llegar»**\n *     (es la mitad del producto: el pago parcial);\n *   · cuántas quedan libres para ESAS fechas y el número de habitaciones pedido — y si\n *     no hay hueco lo dice («lleno»), en vez de desaparecer;\n *   · la estancia mínima, que es la causa número uno de un rechazo al reservar;\n *   · los importes llegan SIEMPRE calculados del servidor (aquí no se hace aritmética\n *     de dinero, solo se pinta).\n */\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { alpha, brand, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport type { HotelRoom, HotelSearchResult } from '../api/hotel';\nimport { xaf } from '../utils/datetime';\nimport { LazyImage } from './rental/LazyImage';\nimport { absUrl } from '../api/config';\n\n/** Primera foto disponible de una habitación o del hotel (el servidor valida al publicar). */\nfunction fotoDe(room?: HotelRoom | null): string | null {\n  const imgs = (room?.images ?? []) as { url?: string }[];\n  const url = imgs.map((i) => i?.url).find((u) => !!u);\n  return url ? absUrl(url) : null;\n}\n\nexport function HotelResultCard({\n  datos,\n  habitaciones,\n  listo,\n  onAbrir,\n  onReservar,\n}: {\n  datos: HotelSearchResult['hotels'][number];\n  /** Habitaciones que quiere el huésped (para exigir disponibilidad suficiente). */\n  habitaciones: number;\n  /** ¿Ya hay fechas elegidas? Sin ellas se enseña el precio por noche, no el total. */\n  listo: boolean;\n  onAbrir: () => void;\n  onReservar: (room: HotelRoom) => void;\n}) {\n  const { colors } = useTheme();\n  const { hotel, rooms, fromPricePerNightXaf, soldOut } = datos;\n  const mejores = rooms.slice(0, 3);\n  // Portada del hotel si la tiene; si no, la primera foto de su habitación más barata.\n  const portada = absUrl(hotel.coverUrl) || fotoDe(mejores[0]);\n\n  return (\n    <View style={[styles.tarjeta, { borderColor: colors.border, backgroundColor: colors.card }]}>\n      <Pressable onPress={onAbrir} accessibilityRole=\"button\" accessibilityLabel={`Ver ${hotel.name}`}>\n        <View style={styles.tarjetaCab}>\n          {/* Foto del alojamiento: es lo que hace que la fila se reconozca de un vistazo. */}\n          <View style={[styles.portada, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n            {portada ? (\n              <LazyImage source={{ uri: portada }} style={styles.portadaImg} />\n            ) : (\n              <Text style={{ fontSize: 22 }}>🏨</Text>\n            )}\n          </View>\n          <View style={{ flex: 1 }}>\n            {/*\n              El nombre del alojamiento y de la habitación son texto que escribe el hotelero.\n              Estaban recortados a UNA línea, que es lo que hace que «Habitación doble con\n              vistas al mar» se quede en «Habitación doble con…» y el huésped no sepa qué\n              elige. Se permiten dos líneas: sigue siendo una lista ordenada y se ve el nombre.\n            */}\n            <Text style={[styles.tarjetaTitulo, { color: colors.textPrimary }]} numberOfLines={2}>\n              {hotel.name} {hotel.isVerified ? '✓' : ''}\n            </Text>\n            <Text style={[styles.tarjetaSub, { color: colors.textSecondary }]} numberOfLines={1}>\n              {[hotel.barrio, hotel.city].filter(Boolean).join(' · ') || 'Guinea Ecuatorial'}\n              {hotel.rating ? ` · ★ ${Number(hotel.rating).toFixed(1)} (${hotel.ratingCount})` : ''}\n            </Text>\n          </View>\n          <View style={{ alignItems: 'flex-end' }}>\n            <Text style={[styles.precio, { color: soldOut ? colors.textSecondary : colors.secondary }]}>\n              {xaf(fromPricePerNightXaf)}\n            </Text>\n            <Text style={[styles.precioSub, { color: colors.textSecondary }]}>\n              {soldOut ? 'sin disponibilidad' : 'por noche · desde'}\n            </Text>\n          </View>\n        </View>\n      </Pressable>\n\n      <View style={{ gap: espaciado.e8, marginTop: espaciado.e10 }}>\n        {mejores.map((r) => {\n          // Con fechas, la disponibilidad es la del servidor para TODO el rango y para\n          // las habitaciones pedidas; sin fechas no se puede afirmar nada.\n          const libre = (r.freeUnits ?? 0) >= habitaciones;\n          const total = r.totalXaf ?? 0;\n          const cerrado = r.closedForDates === true;\n          const foto = fotoDe(r);\n          return (\n            <View key={r.id} style={[styles.habitacion, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              {/* Foto REAL de esa habitación (la sube el hotelero y el servidor la valida). */}\n              <View style={[styles.habFoto, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                {foto ? <LazyImage source={{ uri: foto }} style={styles.habFotoImg} /> : <Text style={{ fontSize: 18 }}>🛏️</Text>}\n              </View>\n              <View style={{ flex: 1 }}>\n                {/* Dos líneas para el nombre de la habitación: es texto del hotelero. */}\n                <Text style={[styles.habNombre, { color: colors.textPrimary }]} numberOfLines={2}>{r.name}</Text>\n                <Text style={[styles.habDatos, { color: colors.textSecondary }]} numberOfLines={2}>\n                  {r.capacity} huésped(es)\n                  {r.beds?.length ? ` · ${r.beds.map((b) => `${b.count} ${b.kind}`).join(', ')}` : ''}\n                  {r.minNights > 1 ? ` · mín ${r.minNights} noches` : ''}\n                  {r.depositPercent > 0 ? ` · señal ${r.depositPercent}%` : ' · sin señal'}\n                </Text>\n                {listo && total > 0 ? (\n                  <Text style={[styles.habTotal, { color: colors.textPrimary }]}>\n                    {xaf(total)} en total\n                    <Text style={{ color: colors.textSecondary }}>\n                      {`  ·  ahora ${xaf(r.depositXaf)} + ${xaf(r.remainingXaf)} al llegar`}\n                    </Text>\n                  </Text>\n                ) : null}\n                {cerrado ? (\n                  <Text style={[styles.habAviso, { color: colors.textSecondary }]}>\n                    El hotel tiene cerrada alguna de esas noches\n                  </Text>\n                ) : null}\n              </View>\n              <View style={{ alignItems: 'flex-end', gap: espaciado.e4 }}>\n                {listo ? (\n                  <Text style={[styles.habLibre, { color: libre ? colors.success : colors.textSecondary }]}>\n                    {libre\n                      ? `${r.freeUnits} libre(s)`\n                      : Number(r.freeUnits) === 0\n                        ? 'lleno'\n                        : `solo ${r.freeUnits}`}\n                  </Text>\n                ) : (\n                  <Text style={[styles.habLibre, { color: colors.textSecondary }]}>{xaf(r.basePriceXaf)}/noche</Text>\n                )}\n                <Pressable\n                  onPress={() => onReservar(r)}\n                  disabled={listo && !libre}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`Reservar ${r.name}`}\n                  accessibilityState={{ disabled: listo && !libre }}\n                  style={[styles.reservarBtn, {\n                    backgroundColor: listo && !libre ? alpha(colors.textSecondary, 0.25) : colors.primary,\n                  }]}\n                >\n                  <Text style={styles.reservarTxt}>{listo ? 'Reservar' : 'Ver fechas'}</Text>\n                </Pressable>\n              </View>\n            </View>\n          );\n        })}\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  tarjeta: { borderWidth: 1, borderRadius: 18, padding: espaciado.e12 },\n  tarjetaCab: { flexDirection: 'row', gap: espaciado.e10, alignItems: 'center' },\n  // Foto del alojamiento en la fila (92×92, redondeada, con hueco gris si no hay).\n  portada: { width: 92, height: 92, borderRadius: 14, borderWidth: 1, overflow: 'hidden', alignItems: 'center', justifyContent: 'center' },\n  portadaImg: { width: '100%', height: '100%' },\n  tarjetaTitulo: { fontSize: 15.5, fontWeight: '800' },\n  tarjetaSub: { fontSize: tipografia.caption, marginTop: espaciado.e2 },\n  precio: { fontSize: 15, fontWeight: '800' },\n  precioSub: { fontSize: 10.5 },\n  habitacion: { borderWidth: 1, borderRadius: 14, padding: espaciado.e10, flexDirection: 'row', gap: espaciado.e10, alignItems: 'center' },\n  // Foto de la habitación en su fila (56×56): «fotos reales de las habitaciones».\n  habFoto: { width: 56, height: 56, borderRadius: 10, borderWidth: 1, overflow: 'hidden', alignItems: 'center', justifyContent: 'center' },\n  habFotoImg: { width: '100%', height: '100%' },\n  habNombre: { fontSize: tipografia.body, fontWeight: '800' },\n  habDatos: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n  habTotal: { fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 },\n  habAviso: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n  habLibre: { fontSize: tipografia.micro, fontWeight: '700' },\n  reservarBtn: { borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\n  reservarTxt: { color: brand.white, fontSize: tipografia.caption, fontWeight: '800' },\n});\n","/**\n * lifebook-hotel — BUSCAR ALOJAMIENTO y reservar (módulo hotelero, Parte 42).\n *\n * Lo que corrige respecto al boceto que se evaluó:\n *   · **Las fechas se ELIGEN, no se teclean**: calendario de verdad (mes navegable,\n *     precio por noche, días cerrados/llenos no seleccionables y estancia mínima).\n *   · **No hay pasos previos obligatorios**: fechas y huéspedes primero (es lo que\n *     decide el precio), y solo después la habitación. Nada de teclear `2026-07-01`.\n *   · Ruta PLANA con prefijo (`/lifebook-hotel*`), como el resto de Life Book: no\n *     se inventa un grupo `(hotel)` que colisionaría con `/search` y `/results`.\n *   · Área segura reservada (barra propia con `useSafeAreaInsets`), errores visibles\n *     con «Reintentar» (nunca un spinner mudo) y estado de carga por bloque.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Pressable, RefreshControl, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, altura, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { CalendarPicker, type CalendarDay } from '../components/CalendarPicker';\nimport { HotelResultCard } from '../components/HotelResultCard';\nimport { hotelApi, type HotelRoom, type HotelSearchResult } from '../api/hotel';\nimport { ApiError } from '../api/httpClient';\nimport { addDaysIso, nightsBetween, shortDate, todayIso, xaf } from '../utils/datetime';\n\nconst CIUDADES = ['Malabo', 'Bata', 'Mongomo', 'Ebebiyín', 'Oyala', 'Annobón'];\n/** El servidor acepta hasta 92 noches por reserva (tope de calendario). */\nconst MAX_NOCHES = 92;\n\nexport default function LifebookHotelScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  // Se puede llegar con fechas ya elegidas (desde una ficha o desde «mis reservas»).\n  const params = useLocalSearchParams<{ roomTypeId?: string; checkIn?: string; checkOut?: string; city?: string }>();\n\n  const hoy = todayIso();\n  const [ciudad, setCiudad] = useState<string>(params.city ?? '');\n  const [checkIn, setCheckIn] = useState<string | null>(params.checkIn ?? null);\n  const [checkOut, setCheckOut] = useState<string | null>(params.checkOut ?? null);\n  const [huespedes, setHuespedes] = useState(2);\n  const [habitaciones, setHabitaciones] = useState(1);\n  const [modo, setModo] = useState<'noches' | 'rango'>('noches');\n  const [nochesPedidas, setNochesPedidas] = useState(1);\n\n  /**\n   * Al volver de la pantalla de fechas (`/lifebook-hotel-fechas`), los parámetros traen\n   * la selección: se sincroniza al recuperar el foco para que el buscador muestre las\n   * fechas elegidas sin recargar nada a mano.\n   */\n  useFocusEffect(\n    useCallback(() => {\n      if (params.checkIn) setCheckIn(params.checkIn);\n      if (params.checkOut) setCheckOut(params.checkOut);\n    }, [params.checkIn, params.checkOut]),\n  );\n\n  const [datos, setDatos] = useState<HotelSearchResult | null>(null);\n  const [cargando, setCargando] = useState(false);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  // Disponibilidad de la habitación de referencia: da el PRECIO POR NOCHE del\n  // calendario antes de elegir hotel (es lo que hace útil el calendario).\n  // Los precios del calendario se cargan en la pantalla de fechas\n  // (`/lifebook-hotel-fechas`), que es donde vive el calendario.\n\n  const buscar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setCargando(true);\n    setError(null);\n    try {\n      const out = await hotelApi.search({\n        city: ciudad || undefined,\n        checkIn: checkIn ?? undefined,\n        checkOut: checkOut ?? undefined,\n        guests: huespedes,\n        units: habitaciones,\n        limit: 20,\n      });\n      setDatos(out);\n    } catch (e) {\n      const msg = e instanceof ApiError ? e.message : 'No se pudo buscar. Revisa tu conexión.';\n      setError(msg);\n      setDatos(null);\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n    }\n  }, [ciudad, checkIn, checkOut, huespedes, habitaciones]);\n\n  // Primera búsqueda al entrar (y cuando cambian fechas/habitaciones: el precio\n  // depende de ellas, así que no se deja el resultado viejo en pantalla).\n  useEffect(() => { void buscar(); }, [buscar]);\n\n  // Precio por noche del calendario: se pide la disponibilidad de la habitación más\n  // barata de los resultados (una sola petición para los 92 días).\n  //\n  // ⚠️ ANTES ESTO ESTABA ROTO: se exigía `(r.freeUnits ?? 1) >= habitaciones`, y sin\n  const noches = checkIn && checkOut ? nightsBetween(checkIn, checkOut) : 0;\n  const listo = !!checkIn && !!checkOut && noches > 0;\n\n  /**\n   * Contador de días del buscador: solo mueve la SALIDA a partir de la llegada ya elegida\n   * (los mínimos por fecha los aplica la pantalla de fechas, que es la que tiene el\n   * calendario delante).\n   */\n  const ajustarNoches = useCallback((delta: number) => {\n    setNochesPedidas((prev) => {\n      const siguiente = Math.min(MAX_NOCHES, Math.max(1, prev + delta));\n      if (checkIn) setCheckOut(addDaysIso(checkIn, siguiente));\n      return siguiente;\n    });\n  }, [checkIn]);\n\n  // Si las fechas cambian por fuera (al volver de la pantalla de fechas), el contador se\n  // sincroniza con lo elegido.\n  useEffect(() => {\n    if (checkIn && checkOut) {\n      const n = nightsBetween(checkIn, checkOut);\n      if (n > 0 && n !== nochesPedidas) setNochesPedidas(n);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [checkIn, checkOut]);\n\n  const abrirHotel = (shopId: string) => {\n    router.push({\n      pathname: '/lifebook-hotel-detalle',\n      params: {\n        id: shopId,\n        ...(checkIn ? { checkIn } : {}),\n        ...(checkOut ? { checkOut } : {}),\n        guests: String(huespedes),\n        units: String(habitaciones),\n      },\n    } as never);\n  };\n\n  const abrirHabitacion = (room: HotelRoom, shopId: string, shopName: string) => {\n    router.push({\n      pathname: '/lifebook-hotel-reservar',\n      params: {\n        roomTypeId: room.id,\n        shopId,\n        shopName,\n        ...(checkIn ? { checkIn } : {}),\n        ...(checkOut ? { checkOut } : {}),\n        guests: String(huespedes),\n        units: String(habitaciones),\n      },\n    } as never);\n  };\n\n  return (\n    <View style={[styles.screen, { backgroundColor: colors.background }]}>\n      {/* ── Barra propia (el Stack va sin cabecera nativa) ── */}\n      <View style={[styles.barra, { paddingTop: insets.top + 6, borderBottomColor: colors.border }]}>\n        <Pressable\n          onPress={() => router.back()}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Volver\"\n          style={styles.volver}\n        >\n          <Text style={[styles.volverTxt, { color: colors.textPrimary }]}>‹</Text>\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          <Text style={[styles.titulo, { color: colors.textPrimary }]}>Alojamiento</Text>\n          <Text style={[styles.sub, { color: colors.textSecondary }]}>\n            Reserva por noches · señal y pago al llegar\n          </Text>\n        </View>\n        <Pressable\n          onPress={() => router.push('/lifebook-hotel-reservas' as never)}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Mis reservas\"\n          style={[styles.misReservas, { borderColor: colors.border }]}\n        >\n          <Text style={[styles.misReservasTxt, { color: colors.primary }]}>Mis reservas</Text>\n        </Pressable>\n        {/*\n          AQUÍ ESTABA EL BOTÓN «MI HOTEL» (el panel del hotelero) Y SE HA QUITADO.\n          Esta pantalla es la del HUÉSPED: quien busca alojamiento. Meter aquí la puerta del\n          comerciante mezclaba los dos papeles —el que reserva y el que recibe— en el mismo\n          sitio, y el hotelero no tenía un acceso PROPIO, lo encontraba de casualidad dentro\n          del buscador. Su acceso vive ahora en su cuenta: Perfil → «Tu comercio».\n        */}\n      </View>\n\n      <FlatList\n        data={datos?.hotels ?? []}\n        keyExtractor={(item) => item.hotel.id}\n        contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 28, gap: espaciado.e12 }}\n        refreshControl={\n          <RefreshControl\n            refreshing={refrescando}\n            onRefresh={() => { setRefrescando(true); void buscar(true); }}\n            tintColor={colors.primary}\n          />\n        }\n        ListHeaderComponent={\n          <View style={{ gap: espaciado.e12 }}>\n            {/* ── Dónde ── */}\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>DÓNDE</Text>\n              <TextInput\n                value={ciudad}\n                onChangeText={setCiudad}\n                placeholder=\"Ciudad (Malabo, Bata…)\"\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n                accessibilityLabel=\"Ciudad\"\n                returnKeyType=\"search\"\n                onSubmitEditing={() => void buscar()}\n              />\n              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8, paddingTop: espaciado.e8 }}>\n                <Chip activo={ciudad === ''} texto=\"Todas\" onPress={() => setCiudad('')} />\n                {CIUDADES.map((c) => (\n                  <Chip key={c} activo={ciudad === c} texto={c} onPress={() => setCiudad(c)} />\n                ))}\n              </ScrollView>\n            </View>\n\n            {/* ── Cuándo: resumen + puerta a la pantalla de fechas ── */}\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <View style={styles.filaCabecera}>\n                <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>CUÁNDO</Text>\n              </View>\n\n              <View style={styles.fechas}>\n                <View style={[styles.fechaCaja, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                  <Text style={[styles.fechaEtq, { color: colors.textSecondary }]}>Entrada</Text>\n                  <Text style={[styles.fechaVal, { color: colors.textPrimary }]}>\n                    {checkIn ? shortDate(checkIn, true) : '—'}\n                  </Text>\n                </View>\n                <View style={[styles.fechaCaja, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                  <Text style={[styles.fechaEtq, { color: colors.textSecondary }]}>Salida</Text>\n                  <Text style={[styles.fechaVal, { color: colors.textPrimary }]}>\n                    {checkOut ? shortDate(checkOut, true) : '—'}\n                  </Text>\n                </View>\n              </View>\n\n              {/* El contador de DÍAS: antes la estancia solo se podía fijar con dos toques\n                  en el calendario y no había forma de decir «3 noches» de una vez. */}\n              <View style={styles.diasFila}>\n                <Text style={[styles.diasEtq, { color: colors.textPrimary }]}>\n                  {nochesPedidas === 1 ? '1 noche' : `${nochesPedidas} noches`}\n                  <Text style={{ color: colors.textSecondary }}>\n                    {checkIn ? ` · ${shortDate(checkIn)} → ${shortDate(addDaysIso(checkIn, nochesPedidas))}` : ''}\n                  </Text>\n                </Text>\n                <View style={styles.diasBtns}>\n                  <Pressable\n                    onPress={() => ajustarNoches(-1)}\n                    disabled={nochesPedidas <= 1}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Quitar una noche\"\n                    accessibilityState={{ disabled: nochesPedidas <= 1 }}\n                    style={[styles.diasBtn, {\n                      borderColor: colors.border, backgroundColor: colors.surface,\n                      opacity: nochesPedidas <= 1 ? 0.35 : 1,\n                    }]}\n                  >\n                    <Text style={[styles.diasBtnTxt, { color: colors.textPrimary }]}>−</Text>\n                  </Pressable>\n                  <Text style={[styles.diasVal, { color: colors.textPrimary }]}>{nochesPedidas}</Text>\n                  <Pressable\n                    onPress={() => ajustarNoches(1)}\n                    disabled={nochesPedidas >= MAX_NOCHES}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Añadir una noche\"\n                    accessibilityState={{ disabled: nochesPedidas >= MAX_NOCHES }}\n                    style={[styles.diasBtn, {\n                      borderColor: colors.border, backgroundColor: colors.surface,\n                      opacity: nochesPedidas >= MAX_NOCHES ? 0.35 : 1,\n                    }]}\n                  >\n                    <Text style={[styles.diasBtnTxt, { color: colors.textPrimary }]}>+</Text>\n                  </Pressable>\n                </View>\n              </View>\n              {!checkIn ? (\n                <Text style={[styles.aviso, { color: colors.textSecondary }]}>\n                  Elige el día de llegada en el calendario (abajo).\n                </Text>\n              ) : null}\n\n              {/* El calendario YA NO se mete aquí: con el contador de días y todo lo de\n                  arriba, la rejilla caía por debajo de la barra del sistema y **los días\n                  no se podían tocar** (medido: celdas hasta y≈2260). Ahora se elige en su\n                  propia pantalla, con el calendario a pantalla completa. */}\n              <Pressable\n                onPress={() => router.push({\n                  pathname: '/lifebook-hotel-fechas',\n                  params: {\n                    ...(ciudad ? { city: ciudad } : {}),\n                    ...(checkIn ? { checkIn } : {}),\n                    ...(checkOut ? { checkOut } : {}),\n                    guests: String(huespedes),\n                    units: String(habitaciones),\n                    modo,\n                  },\n                } as never)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={checkIn && checkOut\n                  ? `Cambiar las fechas. Ahora: ${shortDate(checkIn, true)} a ${shortDate(checkOut, true)}`\n                  : 'Elegir las fechas de la estancia'}\n                style={[styles.elegirFechas, { borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.06) }]}\n              >\n                <Text style={[styles.elegirFechasTxt, { color: colors.primary }]}>\n                  {checkIn && checkOut\n                    ? `Cambiar fechas · ${shortDate(checkIn, true)} → ${shortDate(checkOut, true)}`\n                    : 'Elegir las fechas y los días'}\n                </Text>\n              </Pressable>\n            </View>\n\n            {/* ── Quién viaja ── */}\n            <View style={[styles.bloque, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={[styles.etiqueta, { color: colors.textSecondary }]}>QUIÉN Y CUÁNTAS HABITACIONES</Text>\n              <Contador\n                etiqueta=\"Huéspedes\" valor={huespedes} min={1} max={20}\n                onCambio={setHuespedes}\n              />\n              <Contador\n                etiqueta=\"Habitaciones\" valor={habitaciones} min={1} max={10}\n                onCambio={setHabitaciones}\n              />\n            </View>\n\n            {/* ── Estado de la búsqueda ── */}\n            {cargando ? (\n              <View style={styles.centro}>\n                <ActivityIndicator color={colors.primary} />\n                <Text style={[styles.aviso, { color: colors.textSecondary }]}>Buscando disponibilidad…</Text>\n              </View>\n            ) : error ? (\n              <View style={[styles.error, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06) }]}>\n                <Text style={[styles.errorTxt, { color: colors.danger }]}>{error}</Text>\n                <Pressable onPress={() => void buscar()} accessibilityRole=\"button\" accessibilityLabel=\"Reintentar\">\n                  <Text style={[styles.enlace, { color: colors.primary }]}>Reintentar</Text>\n                </Pressable>\n              </View>\n            ) : listo && (datos?.hotels.length ?? 0) === 0 ? (\n              <View style={[styles.error, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                <Text style={[styles.aviso, { color: colors.textPrimary }]}>\n                  No hay alojamiento disponible con esos datos.\n                </Text>\n                <Text style={[styles.aviso, { color: colors.textSecondary }]}>\n                  Prueba otras fechas, otra ciudad o menos habitaciones. Los hoteles sin hueco sí\n                  aparecen marcados como «sin disponibilidad», así que puedes ajustar el rango.\n                </Text>\n              </View>\n            ) : (\n              <View style={{ gap: espaciado.e8 }}>\n                <Text style={[styles.aviso, { color: colors.textSecondary }]}>\n                  {datos?.hotels.length\n                    ? listo\n                      ? `${datos.hotels.length} alojamiento(s) para ${noches} noche(s) · ${huespedes} huésped(es)`\n                      : `${datos.hotels.length} alojamiento(s) en ${datos.city || 'Guinea Ecuatorial'} · elige fechas para ver el precio`\n                    : 'Elige fechas y pulsa buscar.'}\n                </Text>\n                {(datos?.hotels.length ?? 0) > 0 ? (\n                  <Pressable\n                    onPress={() => router.push({\n                      pathname: '/lifebook-hotel-resultados',\n                      params: {\n                        ...(ciudad ? { city: ciudad } : {}),\n                        ...(checkIn ? { checkIn } : {}),\n                        ...(checkOut ? { checkOut } : {}),\n                        guests: String(huespedes),\n                        units: String(habitaciones),\n                      },\n                    } as never)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Ver todos los resultados\"\n                    style={[styles.verTodos, { borderColor: colors.primary }]}\n                  >\n                    <Text style={[styles.verTodosTxt, { color: colors.primary }]}>\n                      Ver la lista de resultados\n                    </Text>\n                  </Pressable>\n                ) : null}\n              </View>\n            )}\n          </View>\n        }\n        ListEmptyComponent={null}\n        renderItem={({ item }) => (\n          <HotelResultCard\n            datos={item}\n            habitaciones={habitaciones}\n            listo={listo}\n            onAbrir={() => abrirHotel(item.hotel.id)}\n            onReservar={(room) => abrirHabitacion(room, item.hotel.id, item.hotel.name)}\n          />\n        )}\n      />\n    </View>\n  );\n}\n\n// ─────────────────────────── piezas de la pantalla ──────────────────────────\n\nfunction Chip({ activo, texto, onPress }: { activo: boolean; texto: string; onPress: () => void }) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityState={{ selected: activo }}\n      accessibilityLabel={texto}\n      style={[styles.chip, {\n        borderColor: activo ? colors.primary : colors.border,\n        backgroundColor: activo ? alpha(colors.primary, 0.1) : colors.surface,\n      }]}\n    >\n      <Text style={[styles.chipTxt, { color: activo ? colors.primary : colors.textSecondary }]}>{texto}</Text>\n    </Pressable>\n  );\n}\n\nfunction Contador({\n  etiqueta, valor, min, max, onCambio,\n}: { etiqueta: string; valor: number; min: number; max: number; onCambio: (v: number) => void }) {\n  const { colors } = useTheme();\n  const boton = (texto: string, delta: number, deshabilitado: boolean) => (\n    <Pressable\n      onPress={() => !deshabilitado && onCambio(Math.min(max, Math.max(min, valor + delta)))}\n      disabled={deshabilitado}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`${delta > 0 ? 'Añadir' : 'Quitar'} ${etiqueta}`}\n      accessibilityState={{ disabled: deshabilitado }}\n      style={[styles.contBtn, {\n        borderColor: colors.border, opacity: deshabilitado ? 0.35 : 1, backgroundColor: colors.surface,\n      }]}\n    >\n      <Text style={[styles.contBtnTxt, { color: colors.textPrimary }]}>{texto}</Text>\n    </Pressable>\n  );\n  return (\n    <View style={styles.contFila}>\n      <Text style={[styles.contEtq, { color: colors.textPrimary }]}>{etiqueta}</Text>\n      <View style={styles.contAcciones}>\n        {boton('−', -1, valor <= min)}\n        <Text style={[styles.contVal, { color: colors.textPrimary }]}>{valor}</Text>\n        {boton('+', 1, valor >= max)}\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1 },\n  // Selector de modo (llegada + días · entrada y salida) y contador de noches.\n  modoBtn: { flex: 1, borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e8, alignItems: 'center' },\n  modoTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  elegirFechas: { marginTop: espaciado.e10, borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e11, alignItems: 'center' },\n  elegirFechasTxt: { fontSize: tipografia.body, fontWeight: '800' },\n  diasFila: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    gap: espaciado.e10, marginTop: espaciado.e10,\n  },\n  diasEtq: { fontSize: tipografia.body, fontWeight: '700', flex: 1 },\n  diasBtns: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 },\n  diasBtn: { width: 36, height: 36, borderWidth: 1, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },\n  diasBtnTxt: { fontSize: 19, fontWeight: '800', lineHeight: 21 },\n  diasVal: { fontSize: tipografia.subtitle, fontWeight: '800', minWidth: 24, textAlign: 'center' },\n  barra: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: 1,\n  },\n  volver: { width: 34, height: 34, alignItems: 'center', justifyContent: 'center' },\n  volverTxt: { fontSize: 26, fontWeight: '700', lineHeight: 28 },\n  titulo: { fontSize: 17, fontWeight: '800' },\n  sub: { fontSize: tipografia.caption },\n  misReservas: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e7 },\n  misReservasTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  verTodos: { borderWidth: 1, borderRadius: radios.md, paddingVertical: espaciado.e9, alignItems: 'center' },\n  verTodosTxt: { fontSize: tipografia.body, fontWeight: '800' },\n  bloque: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, gap: espaciado.e2 },\n  filaCabecera: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },\n  etiqueta: { fontSize: 10.5, fontWeight: '800', letterSpacing: 0.6 },\n  enlace: { fontSize: tipografia.caption, fontWeight: '700' },\n  input: { borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: altura.punto, fontSize: 14.5, marginTop: espaciado.e6 },\n  fechas: { flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 },\n  fechaCaja: { flex: 1, borderWidth: 1, borderRadius: radios.md, padding: espaciado.e9 },\n  fechaEtq: { fontSize: 10.5, fontWeight: '600' },\n  fechaVal: { fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e2 },\n  chip: { borderWidth: 1, borderRadius: 20, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6 },\n  chipTxt: { fontSize: tipografia.caption, fontWeight: '600' },\n  contFila: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: espaciado.e8 },\n  contEtq: { fontSize: tipografia.body, fontWeight: '600' },\n  contAcciones: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 },\n  contBtn: { width: 34, height: 34, borderWidth: 1, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },\n  contBtnTxt: { fontSize: 18, fontWeight: '800', lineHeight: 20 },\n  contVal: { fontSize: 15, fontWeight: '800', minWidth: 22, textAlign: 'center' },\n  centro: { alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e18 },\n  aviso: { fontSize: tipografia.caption },\n  error: { borderWidth: 1, borderRadius: 14, padding: espaciado.e12, gap: espaciado.e6 },\n  errorTxt: { fontSize: tipografia.body, fontWeight: '600' },\n  tarjeta: { borderWidth: 1, borderRadius: 18, padding: espaciado.e12 },\n  tarjetaCab: { flexDirection: 'row', gap: espaciado.e10 },\n  tarjetaTitulo: { fontSize: 15.5, fontWeight: '800' },\n  tarjetaSub: { fontSize: tipografia.caption, marginTop: espaciado.e2 },\n  precio: { fontSize: 15, fontWeight: '800' },\n  precioSub: { fontSize: 10.5 },\n  habitacion: { borderWidth: 1, borderRadius: 14, padding: espaciado.e10, flexDirection: 'row', gap: espaciado.e10, alignItems: 'center' },\n  habNombre: { fontSize: tipografia.body, fontWeight: '800' },\n  habDatos: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n  habTotal: { fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 },\n  habLibre: { fontSize: tipografia.micro, fontWeight: '700' },\n  reservarBtn: { borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\n  reservarTxt: { color: brand.white, fontSize: tipografia.caption, fontWeight: '800' },\n});\n","/**\n * Bandeja · COMENTARIOS Y @ (/lifebook-inbox-comments).\n * Comentarios de otras personas en tus publicaciones + menciones (@Nombre).\n * Al abrir Menciones se marcan como leídas.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Image, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, EmptyState, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, AtSign, MessageSquare } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookInboxApi, type LbCommentReceived, type LbMentionReceived } from '../api/lifebook';\nimport { lbTimeAgo } from '../constants/lifebook';\n\nexport default function InboxCommentsScreen() {\n  return (\n    <AuthGate>\n      <CommentsContent />\n    </AuthGate>\n  );\n}\n\nfunction CommentsContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [tab, setTab] = useState<'comments' | 'mentions'>('comments');\n  const [comments, setComments] = useState<LbCommentReceived[] | null>(null);\n  const [mentions, setMentions] = useState<LbMentionReceived[] | null>(null);\n\n  const load = useCallback(async () => {\n    try {\n      const [c, m] = await Promise.all([lifebookInboxApi.comments(), lifebookInboxApi.mentions()]);\n      setComments(c); setMentions(m);\n    } catch { setComments([]); setMentions([]); }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n  // Parte 16: abrir la bandeja marca comentarios y menciones como leídos.\n  useEffect(() => { lifebookInboxApi.markRead('comments').catch(() => {}); }, [tab]);\n\n  const Row = ({ actor, body, at, postId, thumb, label }: {\n    actor: { id: string; fullName: string | null; avatarUrl: string | null };\n    body: string; at: string; postId?: string | null; thumb?: { url: string } | null; label: string;\n  }) => (\n    <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n      <Pressable style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}\n        onPress={() => router.push({ pathname: '/lifebook-user', params: { id: actor.id } } as never)}>\n        {absUrl(actor.avatarUrl) ? (\n          <Image source={{ uri: absUrl(actor.avatarUrl) }} style={[styles.avatar, { backgroundColor: colors.surface }]} />\n        ) : (\n          <View style={[styles.avatar, { backgroundColor: alpha(colors.primary, 0.15), alignItems: 'center', justifyContent: 'center' }]}>\n            <Text style={{ color: colors.primary, fontSize: 18, fontWeight: '900' }}>{(actor.fullName ?? '?').charAt(0).toUpperCase()}</Text>\n          </View>\n        )}\n        <View style={{ flex: 1 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '800' }} numberOfLines={1}>{actor.fullName ?? 'Usuario'}</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>{label} · {lbTimeAgo(at)}</Text>\n        </View>\n      </Pressable>\n\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, marginTop: espaciado.e8, lineHeight: 19 }}>{body}</Text>\n\n      {postId && (\n        <Pressable onPress={() => router.push({ pathname: '/lifebook-post/[id]', params: { id: postId } } as never)}\n          style={[styles.postRow, { backgroundColor: colors.surface }]}>\n          {thumb ? (\n            <Image source={{ uri: absUrl(thumb.url) }} style={[styles.thumb, { backgroundColor: colors.card }]} />\n          ) : (\n            <View style={[styles.thumb, { backgroundColor: colors.card, alignItems: 'center', justifyContent: 'center' }]}>\n              <Text style={{ fontSize: tipografia.body }}>📝</Text>\n            </View>\n          )}\n          <Text style={{ flex: 1, color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Ver la publicación</Text>\n        </Pressable>\n      )}\n    </View>\n  );\n\n  const loading = tab === 'comments' ? comments === null : mentions === null;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Comentarios y @</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <View style={{ flexDirection: 'row', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}>\n        {([['comments', 'Comentarios'], ['mentions', 'Menciones @']] as Array<['comments' | 'mentions', string]>).map(([k, label]) => {\n          const on = tab === k;\n          return (\n            <Pressable key={k} onPress={() => setTab(k)} accessibilityRole=\"tab\" accessibilityState={{ selected: on }}\n              style={[styles.tabPill, { backgroundColor: on ? colors.primary : colors.surface, borderColor: on ? colors.primary : colors.border }]}>\n              <Text style={{ color: on ? brand.white : colors.textSecondary, fontSize: tipografia.body, fontWeight: on ? '900' : '700' }}>{label}</Text>\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {loading ? (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><ActivityIndicator color={colors.primary} /></View>\n      ) : tab === 'comments' ? (\n        <FlatList\n          data={comments ?? []}\n          keyExtractor={(c) => c.id}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 20, flexGrow: 1 }}\n          ItemSeparatorComponent={() => <View style={{ height: 8 }} />}\n          ListEmptyComponent={\n            <EmptyState\n              icono={<MessageSquare size={38} color={alpha(colors.primary, 0.45)} />}\n              titulo=\"Todavía no hay comentarios\"\n              texto=\"Los comentarios de otras personas en tus publicaciones aparecerán aquí, con la opción de responder por mensaje.\"\n            />\n          }\n          renderItem={({ item }) => (\n            <Row actor={item.user} body={item.body} at={item.at} postId={item.post.id} thumb={item.post.thumb} label='comentó tu publicación' />\n          )}\n        />\n      ) : (\n        <FlatList\n          data={mentions ?? []}\n          keyExtractor={(m) => m.id}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 20, flexGrow: 1 }}\n          ItemSeparatorComponent={() => <View style={{ height: 8 }} />}\n          ListEmptyComponent={\n            <EmptyState\n              icono={<AtSign size={38} color={alpha(colors.primary, 0.45)} />}\n              titulo=\"Sin menciones\"\n              texto=\"Cuando alguien te mencione con @ en un comentario o en una publicación, lo verás aquí.\"\n            />\n          }\n          renderItem={({ item }) => (\n            <Row actor={item.user} body={item.snippet ?? ''} at={item.at} postId={item.post?.id} thumb={item.post?.thumb} label='te mencionó' />\n          )}\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: 16.5, fontWeight: '900', flex: 1 },\n  tabPill: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, borderWidth: 1 },\n  card: { borderRadius: 14, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e12 },\n  avatar: { width: 42, height: 42, borderRadius: 21 },\n  postRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e9, borderRadius: 10, padding: espaciado.e8, marginTop: espaciado.e10 },\n  thumb: { width: 38, height: 38, borderRadius: radios.sm },\n});\n","/**\n * Bandeja · NUEVOS SEGUIDORES + RECOMENDACIONES (/lifebook-inbox-followers).\n * Arriba: quién te ha seguido (con \"Seguir de vuelta\").\n * Abajo: recomendaciones de la plataforma (regla simple y con motivo visible).\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Image, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Check, UserPlus, Users } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookApi, lifebookInboxApi, type LbFollowerItem, type LbSuggestedUser } from '../api/lifebook';\nimport { lbTimeAgo } from '../constants/lifebook';\n\nexport default function InboxFollowersScreen() {\n  return (\n    <AuthGate>\n      <FollowersContent />\n    </AuthGate>\n  );\n}\n\nfunction FollowersContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [followers, setFollowers] = useState<LbFollowerItem[] | null>(null);\n  const [suggested, setSuggested] = useState<LbSuggestedUser[] | null>(null);\n  const [busy, setBusy] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    try {\n      const [f, s] = await Promise.all([lifebookInboxApi.followers(), lifebookInboxApi.suggested()]);\n      setFollowers(f); setSuggested(s);\n      // Parte 16: abrir la bandeja la marca como leída.\n      lifebookInboxApi.markRead('followers').catch(() => {});\n    } catch { setFollowers([]); setSuggested([]); }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const followBack = async (u: LbFollowerItem) => {\n    setBusy(u.id);\n    const was = u.followedBack;\n    setFollowers((prev) => (prev ?? []).map((x) => (x.id === u.id ? { ...x, followedBack: !was } : x)));\n    try { await (was ? lifebookApi.unfollow(u.id) : lifebookApi.follow(u.id)); }\n    catch { setFollowers((prev) => (prev ?? []).map((x) => (x.id === u.id ? { ...x, followedBack: was } : x))); }\n    finally { setBusy(null); }\n  };\n\n  const followSuggested = async (u: LbSuggestedUser) => {\n    setBusy(u.id);\n    try {\n      await lifebookApi.follow(u.id);\n      setSuggested((prev) => (prev ?? []).filter((x) => x.id !== u.id));\n    } catch { /* sigue en la lista */ }\n    finally { setBusy(null); }\n  };\n\n  const Avatar = ({ url, name, size = 46 }: { url?: string | null; name?: string | null; size?: number }) => (\n    absUrl(url) ? (\n      <Image source={{ uri: absUrl(url) }} style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: colors.surface }} />\n    ) : (\n      <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: alpha(colors.primary, 0.15), alignItems: 'center', justifyContent: 'center' }}>\n        <Text style={{ color: colors.primary, fontSize: size * 0.42, fontWeight: '900' }}>{(name ?? '?').charAt(0).toUpperCase()}</Text>\n      </View>\n    )\n  );\n\n  const loading = followers === null || suggested === null;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Nuevos seguidores</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      {loading ? (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        <FlatList\n          data={[\n            { kind: 'h' as const, title: 'Te han seguido' },\n            ...(followers ?? []).map((f) => ({ kind: 'f' as const, f })),\n            ...(((followers ?? []).length === 0) ? [{ kind: 'he' as const }] : []),\n            { kind: 'h' as const, title: 'Recomendados para ti' },\n            ...(suggested ?? []).map((s) => ({ kind: 's' as const, s })),\n            ...(((suggested ?? []).length === 0) ? [{ kind: 'se' as const }] : []),\n          ]}\n          keyExtractor={(row, i) => row.kind === 'f' ? `f-${row.f.id}` : row.kind === 's' ? `s-${row.s.id}` : `${row.kind}-${i}`}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 20 }}\n          renderItem={({ item: row }) => {\n            if (row.kind === 'h') {\n              return <Text style={[styles.sectionTitle, { color: colors.textSecondary }]}>{row.title.toUpperCase()}</Text>;\n            }\n            if (row.kind === 'he') {\n              return <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e6, lineHeight: 18 }}>Todavía no tienes seguidores nuevos.</Text>;\n            }\n            if (row.kind === 'se') {\n              return <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 18 }}>No hay recomendaciones ahora mismo.</Text>;\n            }\n            if (row.kind === 'f') {\n              const u = row.f;\n              return (\n                <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                  <Pressable style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, flex: 1 }}\n                    onPress={() => router.push({ pathname: '/lifebook-user', params: { id: u.id } } as never)}>\n                    <Avatar url={u.avatarUrl} name={u.fullName} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '800' }} numberOfLines={1}>{u.fullName ?? 'Usuario'}</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                        {u.city ? `${u.city} · ` : ''}{u.posts} publicacion{u.posts === 1 ? '' : 'es'} · {lbTimeAgo(u.at)}\n                      </Text>\n                    </View>\n                  </Pressable>\n                  <Pressable onPress={() => followBack(u)} disabled={busy === u.id}\n                    style={[styles.followBtn, { backgroundColor: u.followedBack ? colors.surface : colors.primary, borderColor: u.followedBack ? colors.border : colors.primary }]}>\n                    {busy === u.id ? <ActivityIndicator size=\"small\" color={u.followedBack ? colors.textPrimary : brand.white} /> : (\n                      <>\n                        {u.followedBack ? <Check size={13} color={colors.textPrimary} /> : <UserPlus size={13} color={brand.white} />}\n                        <Text style={{ color: u.followedBack ? colors.textPrimary : brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>\n                          {u.followedBack ? 'Siguiendo' : 'Seguir'}\n                        </Text>\n                      </>\n                    )}\n                  </Pressable>\n                </View>\n              );\n            }\n            const s = row.s;\n            return (\n              <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                <Pressable style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, flex: 1 }}\n                  onPress={() => router.push({ pathname: '/lifebook-user', params: { id: s.id } } as never)}>\n                  <Avatar url={s.avatarUrl} name={s.fullName} />\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '800' }} numberOfLines={1}>{s.fullName ?? 'Usuario'}</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }} numberOfLines={1}>{s.reason}</Text>\n                  </View>\n                </Pressable>\n                <Pressable onPress={() => followSuggested(s)} disabled={busy === s.id} style={[styles.followBtn, { backgroundColor: colors.primary, borderColor: colors.primary }]}>\n                  {busy === s.id ? <ActivityIndicator size=\"small\" color={brand.white} /> : (\n                    <>\n                      <UserPlus size={13} color={brand.white} />\n                      <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>Seguir</Text>\n                    </>\n                  )}\n                </Pressable>\n              </View>\n            );\n          }}\n          ListEmptyComponent={\n            <View style={{ alignItems: 'center', paddingTop: 60, gap: espaciado.e8 }}>\n              <Users size={36} color={alpha(colors.primary, 0.45)} />\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>Sin novedades de seguidores</Text>\n            </View>\n          }\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: 16.5, fontWeight: '900', flex: 1 },\n  sectionTitle: { fontSize: tipografia.micro, fontWeight: '900', letterSpacing: 0.6, marginTop: espaciado.e6, marginBottom: espaciado.e8 },\n  card: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderRadius: 14, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e12, marginBottom: espaciado.e8 },\n  followBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, borderWidth: 1 },\n});\n","/**\n * Bandeja · ME GUSTAS Y GUARDADOS (/lifebook-inbox-likes).\n * Quién dio me gusta / guardó tus publicaciones, con opción de AGRADECER por\n * mensaje (abre el chat con el texto ya escrito).\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Image, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, EmptyState, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Heart, Send, ThumbsUp } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookChatApi, lifebookInboxApi, type LbLikeReceived, type LbSaveReceived } from '../api/lifebook';\nimport { lbTimeAgo } from '../constants/lifebook';\n\nexport default function InboxLikesScreen() {\n  return (\n    <AuthGate>\n      <LikesContent />\n    </AuthGate>\n  );\n}\n\nconst THANKS_TEXT = '¡Gracias por tu me gusta! 😊';\n\nfunction LikesContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [tab, setTab] = useState<'likes' | 'saves'>('likes');\n  const [likes, setLikes] = useState<LbLikeReceived[] | null>(null);\n  const [saves, setSaves] = useState<LbSaveReceived[] | null>(null);\n  const [busy, setBusy] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    try {\n      const [l, s] = await Promise.all([lifebookInboxApi.likes(), lifebookInboxApi.saves()]);\n      setLikes(l); setSaves(s);\n      // Parte 16: abrir la bandeja la marca como leída (los iconos se limpian).\n      lifebookInboxApi.markRead('likes').catch(() => {});\n    } catch { setLikes([]); setSaves([]); }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const thank = async (userId: string) => {\n    setBusy(userId);\n    try {\n      const conv = await lifebookChatApi.open(userId);\n      router.push({ pathname: '/lifebook-chat/[id]', params: { id: conv.id, name: conv.other?.fullName ?? 'Chat', peerId: conv.other?.id, draft: THANKS_TEXT } } as never);\n    } catch { /* sin chat */ }\n    finally { setBusy(null); }\n  };\n\n  const rows = tab === 'likes' ? (likes ?? []) : (saves ?? []);\n  const loading = tab === 'likes' ? likes === null : saves === null;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Me gustas y guardados</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <View style={{ flexDirection: 'row', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}>\n        {([['likes', 'Me gustas'], ['saves', 'Guardados']] as Array<['likes' | 'saves', string]>).map(([k, label]) => {\n          const on = tab === k;\n          return (\n            <Pressable key={k} onPress={() => setTab(k)} accessibilityRole=\"tab\" accessibilityState={{ selected: on }}\n              style={[styles.tabPill, { backgroundColor: on ? colors.primary : colors.surface, borderColor: on ? colors.primary : colors.border }]}>\n              <Text style={{ color: on ? brand.white : colors.textSecondary, fontSize: tipografia.body, fontWeight: on ? '900' : '700' }}>{label}</Text>\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {loading ? (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        <FlatList\n          data={rows as Array<LbLikeReceived | LbSaveReceived>}\n          keyExtractor={(r) => `${tab}-${r.user.id}-${r.post.id}-${r.at}`}\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 20, flexGrow: 1 }}\n          ListEmptyComponent={\n            <EmptyState\n              icono={<Heart size={38} color={alpha(colors.primary, 0.45)} />}\n              titulo={tab === 'likes' ? 'Todavía no tienes me gusta' : 'Todavía no has guardado publicaciones'}\n              texto={tab === 'likes'\n                ? 'Cuando alguien reaccione a tus publicaciones lo verás aquí, y podrás agradecerle por mensaje.'\n                : 'Lo que guardes aparecerá aquí, solo para ti.'}\n            />\n          }\n          ItemSeparatorComponent={() => <View style={{ height: 8 }} />}\n          renderItem={({ item }) => (\n            <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\n                {absUrl(item.user.avatarUrl) ? (\n                  <Image source={{ uri: absUrl(item.user.avatarUrl) }} style={[styles.avatar, { backgroundColor: colors.surface }]} />\n                ) : (\n                  <View style={[styles.avatar, { backgroundColor: alpha(colors.primary, 0.15), alignItems: 'center', justifyContent: 'center' }]}>\n                    <Text style={{ color: colors.primary, fontSize: 18, fontWeight: '900' }}>{(item.user.fullName ?? '?').charAt(0).toUpperCase()}</Text>\n                  </View>\n                )}\n                <View style={{ flex: 1 }}>\n                  <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '800' }} numberOfLines={1}>\n                    {item.user.fullName ?? 'Usuario'}\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                    {tab === 'likes' ? 'le dio me gusta a tu publicación' : 'guardó tu publicación'} · {lbTimeAgo(item.at)}\n                  </Text>\n                </View>\n              </View>\n\n              <Pressable onPress={() => router.push({ pathname: '/lifebook-post/[id]', params: { id: item.post.id } } as never)}\n                style={[styles.postRow, { backgroundColor: colors.surface }]}>\n                {item.post.thumb ? (\n                  <Image source={{ uri: absUrl(item.post.thumb.url) }} style={[styles.thumb, { backgroundColor: colors.card }]} />\n                ) : (\n                  <View style={[styles.thumb, { backgroundColor: colors.card, alignItems: 'center', justifyContent: 'center' }]}>\n                    <Text style={{ fontSize: 15 }}>📝</Text>\n                  </View>\n                )}\n                <Text style={{ flex: 1, color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '600' }} numberOfLines={2}>\n                  {item.post.preview || 'Ver publicación'}\n                </Text>\n              </Pressable>\n\n              {tab === 'likes' && (\n                <Pressable onPress={() => thank(item.user.id)} disabled={busy === item.user.id}\n                  style={[styles.actBtn, { backgroundColor: alpha(colors.primary, 0.1) }]}>\n                  {busy === item.user.id ? <ActivityIndicator size=\"small\" color={colors.primary} /> : (\n                    <>\n                      <ThumbsUp size={13} color={colors.primary} />\n                      <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '900' }}>Agradecer por mensaje</Text>\n                      <Send size={12} color={colors.primary} />\n                    </>\n                  )}\n                </Pressable>\n              )}\n            </View>\n          )}\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: 16.5, fontWeight: '900', flex: 1 },\n  tabPill: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, borderWidth: 1 },\n  card: { borderRadius: 14, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e12 },\n  avatar: { width: 42, height: 42, borderRadius: 21 },\n  postRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e9, borderRadius: 10, padding: espaciado.e8, marginTop: espaciado.e10 },\n  thumb: { width: 40, height: 40, borderRadius: radios.sm },\n  actBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, borderRadius: radios.full, paddingVertical: espaciado.e8, marginTop: espaciado.e10 },\n});\n","/**\n * Life Book — BANDEJA unificada (/lifebook-inbox?tab=likes|followers|comments)\n * Pantalla: LifeBookInbox (estilo Xiaohongshu + datos REALES de la Fase A).\n *\n *  - Pestañas: Me gusta · Guardados / Seguidores / Comentarios y @.\n *  - Tarjetas: avatar del actor con distintivo de tipo, acción, texto del\n *    comentario/mención, hora, miniatura de tu publicación y \"Seguir de vuelta\"\n *    (llamada real) en seguidores.\n *  - Me gusta: botón \"Agradecer\" que abre el chat con el mensaje ya escrito.\n *  - Comentarios: marca las menciones como leídas al abrir.\n *  - Enlace al detalle de cada bandeja (recomendados, menciones leídas, etc.).\n */\nimport React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, FlatList, Image, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, EmptyState, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, AtSign, ChevronRight, Heart, UserPlus } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { messagesApi, type LbInboxItem, type LbInboxType } from '../api/messages';\nimport { lifebookApi, lifebookInboxApi } from '../api/lifebook';\nimport { lbTimeAgo } from '../constants/lifebook';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst TABS: { id: LbInboxType; label: string }[] = [\n  { id: 'likes', label: 'Me gusta · Guardados' },\n  { id: 'followers', label: 'Seguidores' },\n  { id: 'comments', label: 'Comentarios y @' },\n];\n\n/** Pantalla de detalle de cada bandeja (donde viven recomendados y menciones). */\nconst DETAIL_ROUTE: Record<LbInboxType, string> = {\n  likes: '/lifebook-inbox-likes',\n  followers: '/lifebook-inbox-followers',\n  comments: '/lifebook-inbox-comments',\n};\n\nexport default function LifeBookInbox() {\n  return (\n    <AuthGate>\n      <InboxContent />\n    </AuthGate>\n  );\n}\n\nfunction InboxContent() {\n  const { tab } = useLocalSearchParams<{ tab?: string }>();\n  const initial: LbInboxType = (tab === 'followers' || tab === 'comments') ? tab : 'likes';\n\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const [active, setActive] = useState<LbInboxType>(initial);\n  const [items, setItems] = useState<LbInboxItem[] | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busyId, setBusyId] = useState<string | null>(null);\n\n  const load = useCallback(async (kind: LbInboxType) => {\n    try {\n      const page = await messagesApi.inbox([kind]);\n      setItems(page.items);\n      setError(null);\n      // Parte 16: abrir la bandeja la marca como leída (los iconos de Mensajes se limpian).\n      lifebookInboxApi.markRead(kind).catch(() => {});\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cargar la bandeja');\n    }\n  }, []);\n\n  /**\n   * Parte 31 (navegación fluida): al volver a la bandeja NO se vacía la lista.\n   * Antes `setItems(null)` borraba todo y mostraba el spinner a pantalla\n   * completa en cada foco → parpadeo. Ahora se recarga en segundo plano y la\n   * lista (o el spinner, solo la primera vez) se mantiene hasta tener datos.\n   */\n  useFocusEffect(useCallback(() => { load(active); }, [active, load]));\n\n  const followBack = async (userId: string, itemId: string) => {\n    if (!userId || busyId) return;\n    setBusyId(itemId);\n    try {\n      await lifebookApi.follow(userId);\n      setItems((prev) => (prev ?? []).map((i) => (i.id === itemId ? { ...i, followedBack: true } : i)));\n    } catch { /* silencioso */ }\n    finally { setBusyId(null); }\n  };\n\n  const thank = async (userId: string) => {\n    if (!userId) return;\n    try {\n      const conv = await messagesApi.open(userId);\n      router.push({\n        pathname: '/lifebook-chat/[id]',\n        params: { id: conv.id, name: conv.peer.name ?? 'Chat', peerId: conv.peer.id, draft: '¡Gracias por tu me gusta! 😊' },\n      });\n    } catch { /* silencioso */ }\n  };\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera */}\n      <View style={styles.header}>\n        <Pressable onPress={() => router.back()} hitSlop={8} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 17, flex: 1, marginLeft: espaciado.e10 }}>\n          Notificaciones\n        </Text>\n        <Pressable\n          onPress={() => router.push(DETAIL_ROUTE[active] as never)}\n          hitSlop={8}\n          accessibilityLabel=\"Ver detalle de la bandeja\"\n        >\n          <ChevronRight size={20} color={colors.textSecondary} />\n        </Pressable>\n      </View>\n\n      {/* Pestañas */}\n      <View style={styles.tabRow}>\n        {TABS.map((t) => {\n          const isActive = active === t.id;\n          return (\n            <Pressable\n              key={t.id}\n              onPress={() => setActive(t.id)}\n              accessibilityRole=\"tab\"\n              accessibilityState={{ selected: isActive }}\n              style={[styles.tab, { backgroundColor: isActive ? colors.primary : colors.surface }]}\n            >\n              <Text numberOfLines={1} style={{ color: isActive ? brand.white : colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                {t.label}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {/* Lista */}\n      {items === null && !error ? (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>\n          <ActivityIndicator color={colors.primary} />\n        </View>\n      ) : error ? (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e12, padding: espaciado.e24 }}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '700', textAlign: 'center' }}>{error}</Text>\n          <Pressable onPress={() => load(active)} style={{ backgroundColor: colors.surface, borderRadius: radios.full, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e9 }}>\n            <Text style={{ color: colors.primary, fontWeight: '800' }}>Reintentar</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <FlatList\n          data={items ?? []}\n          keyExtractor={(i) => i.id}\n          contentContainerStyle={{ padding: espaciado.e14, gap: espaciado.e10, flexGrow: 1 }}\n          refreshing={false}\n          onRefresh={() => load(active)}\n          renderItem={({ item }) => (\n            <InboxCard\n              item={item}\n              colors={colors}\n              busy={busyId === item.id}\n              onOpen={() => {\n                if (item.targetPostId) router.push({ pathname: '/lifebook-post/[id]', params: { id: item.targetPostId } });\n                else if (item.actor.id) router.push({ pathname: '/lifebook-user', params: { id: item.actor.id } } as never);\n              }}\n              onFollow={() => followBack(item.actor.id, item.id)}\n              onThank={() => thank(item.actor.id)}\n            />\n          )}\n          ListEmptyComponent={\n            /*\n              Vacío con salida (D-17). Este era el PEOR ejemplo del informe: «Nada por aquí\n              todavía» no dice qué es esto, ni por qué está vacío, ni qué hacer. El margen de\n              arriba se conserva (36 + los 34 del propio componente ≈ los 70 de antes).\n            */\n            <View style={{ marginTop: 36 }}>\n              <EmptyState\n                icono={active === 'likes'\n                  ? <Heart size={40} color={colors.textSecondary} />\n                  : active === 'followers'\n                    ? <UserPlus size={40} color={colors.textSecondary} />\n                    : <AtSign size={40} color={colors.textSecondary} />}\n                titulo={active === 'likes'\n                  ? 'Todavía no tienes me gusta ni guardados'\n                  : active === 'followers'\n                    ? 'Todavía no tienes seguidores nuevos'\n                    : 'Todavía no te han mencionado'}\n                texto={active === 'likes'\n                  ? 'Cuando alguien reaccione a una publicación tuya o guarde algo tuyo, aparecerá aquí y podrás agradecerle por mensaje.'\n                  : active === 'followers'\n                    ? 'Aquí verás a quien empiece a seguirte, y podrás seguirle tú también.'\n                    : 'Cuando alguien te mencione con @ en un comentario, lo verás aquí.'}\n                accionLabel={active === 'likes' ? 'Crear una publicación' : undefined}\n                onAccion={active === 'likes' ? () => router.push('/lifebook-compose' as never) : undefined}\n              />\n            </View>\n          }\n        />\n      )}\n    </View>\n  );\n}\n\n/* ── Tarjeta de notificación ── */\nfunction InboxCard({ item, colors, busy, onOpen, onFollow, onThank }: {\n  item: LbInboxItem; colors: any; busy?: boolean;\n  onOpen: () => void; onFollow: () => void; onThank: () => void;\n}) {\n  const icon = item.kind === 'likes'\n    ? <Heart size={13} color={brand.white} fill={brand.white} />\n    : item.kind === 'followers'\n      ? <UserPlus size={13} color={brand.white} />\n      : <AtSign size={13} color={brand.white} />;\n  const iconBg = item.kind === 'likes' ? brand.like : item.kind === 'followers' ? brand.primary : brand.secondary;\n\n  return (\n    <Pressable\n      onPress={onOpen}\n      style={({ pressed }) => [styles.card, { backgroundColor: colors.card, opacity: pressed ? 0.92 : 1 }]}\n    >\n      <View>\n        {item.actor.avatarUrl ? (\n          <Image source={{ uri: item.actor.avatarUrl }} style={styles.avatar} />\n        ) : (\n          <View style={[styles.avatar, styles.avatarFallback, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n            <Text style={{ color: colors.primary, fontWeight: '800' }}>\n              {(item.actor.name ?? '?').trim().charAt(0).toUpperCase()}\n            </Text>\n          </View>\n        )}\n        <View style={[styles.kindBadge, { backgroundColor: iconBg }]}>{icon}</View>\n      </View>\n\n      <View style={{ flex: 1 }}>\n        <Text style={{ fontSize: tipografia.body, lineHeight: 18 }}>\n          <Text style={{ color: colors.textPrimary, fontWeight: '700' }}>{item.actor.name ?? 'Usuario'}</Text>\n          <Text style={{ color: colors.textSecondary }}> {item.action}</Text>\n        </Text>\n\n        {item.text ? (\n          <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.body, marginTop: espaciado.e3 }}>{item.text}</Text>\n        ) : null}\n\n        {item.targetTitle ? (\n          <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>\n            📄 {item.targetTitle}\n          </Text>\n        ) : null}\n\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e3 }}>{lbTimeAgo(item.createdAt)}</Text>\n\n        <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8, flexWrap: 'wrap' }}>\n          {item.kind === 'followers' && !item.followedBack ? (\n            <Pressable\n              onPress={onFollow}\n              disabled={busy}\n              style={[styles.actionBtn, { backgroundColor: colors.primary }]}\n            >\n              {busy\n                ? <ActivityIndicator size=\"small\" color={brand.white} />\n                : <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '700' }}>Seguir de vuelta</Text>}\n            </Pressable>\n          ) : null}\n          {item.kind === 'likes' ? (\n            <Pressable onPress={onThank} style={[styles.actionBtn, { backgroundColor: alpha(colors.primary, 0.1) }]}>\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Agradecer por mensaje</Text>\n            </Pressable>\n          ) : null}\n        </View>\n      </View>\n\n      {item.targetCover ? (\n        <Image source={{ uri: item.targetCover }} style={styles.targetThumb} />\n      ) : null}\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 },\n  tabRow: { flexDirection: 'row', gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8 },\n  tab: { borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, flex: 1, alignItems: 'center' },\n  card: { flexDirection: 'row', gap: espaciado.e10, borderRadius: 14, padding: espaciado.e12 },\n  avatar: { width: 42, height: 42, borderRadius: 21 },\n  avatarFallback: { alignItems: 'center', justifyContent: 'center' },\n  kindBadge: {\n    position: 'absolute', bottom: -2, right: -2,\n    width: 20, height: 20, borderRadius: 10,\n    alignItems: 'center', justifyContent: 'center',\n    borderWidth: 2, borderColor: brand.white,\n  },\n  actionBtn: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, minWidth: 96, alignItems: 'center' },\n  targetThumb: { width: 44, height: 44, borderRadius: radios.sm },\n});\n","/**\n * Life Book — PUBLICAR MEDIA (/lifebook-media?kind=video|podcast|serie|episode[&serieId=]).\n * Campos por tipo (PUBLICAR §3.2-3.4, módulos 1-3 del diseño audiovisual):\n *  · video: título + descripción + archivo de vídeo + portada opcional\n *  · podcast: título + descripción + AUDIO (≤60 MB) + portada OBLIGATORIA + duración\n *  · serie: título + descripción + portada opcional (los episodios se añaden después)\n *  · episode: archivo de vídeo + título/descripción (a una serie existente, número automático)\n *\n * ── DOS CAMINOS DE SUBIDA, A PROPÓSITO (Parte 50) ──────────────────────────────\n *  · IMAGEN y AUDIO → `POST /lifebook/media/upload` (multipart contra el API, como siempre).\n *    Son pequeños (≤10 / ≤60 MB) y ese camino ya va fino.\n *  · VÍDEO → URL FIRMADA (./api/lifebookMediaReal): el archivo va **directo del móvil al\n *    almacenamiento**, sin atravesar el proceso del API, y con progreso real. Es lo que\n *    hace posible un vídeo de 50 minutos: por el camino viejo, ~900 MB cruzando el API sin\n *    saber por dónde va. Además el servidor VERIFICA el archivo al cerrar (ffprobe) y saca\n *    el póster.\n *\n * El perfil del vídeo (corto ≤1 min / largo ≤50 min) es una elección EXPLÍCITA del que\n * publica: el corto es el que hace que el feed cargue al instante y no se toca.\n */\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Image, KeyboardAvoidingView, Platform, Pressable,\n  ScrollView, StyleSheet, Switch, Text, TextInput, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport * as ImagePicker from 'expo-image-picker';\nimport * as DocumentPicker from 'expo-document-picker';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Clapperboard, ImagePlus, Mic, ShoppingBag, Upload, Video } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { authApi } from '../api/auth';\nimport { lifebookMediaApi } from '../api/lifebook';\n/* TANDA C (bis): los productos del vídeo van por aquí (el `createVideo` de `api/lifebook.ts` no\n   acepta `productIds`, y ese fichero no se toca) y con la MISMA hoja que el compositor de notas. */\nimport { productosEnNotaApi } from '../api/lifebookProductos';\nimport { SelectorDeProductos } from '../components/lifebook/SelectorDeProductos';\nimport { limpiarSubida, subirArchivoFirmado, type LbProgreso } from '../api/lifebookMediaReal';\nimport { pickImagesFromLibrary } from '../core/pickImage';\n// B2: elegir la portada desde un fotograma del propio vídeo. Antes solo podía venir\n// de la galería o del servidor, que saca SIEMPRE el fotograma del segundo 1\n// (`extractPoster`, lb41-media.service.ts:405) — un vídeo que arranca en negro o con\n// una transición se publicaba así y no había forma de cambiarlo desde la app.\nimport { VideoCoverSheet } from '../components/lifebook/VideoCoverSheet';\nimport {\n  LB_CITIES, LB_NOTE_BODY_MAX, LB_NOTE_TITLE_MAX, LB_VIDEO_PERFILES, MEDIA_KIND_ACCEPT,\n  fmtDur, lbPeso, lbTiempoSubida, type LbVideoPerfilId,\n} from '../constants/lifebook';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport default function LifeBookMediaComposeScreen() {\n  return (\n    <AuthGate>\n      <MediaComposeContent />\n    </AuthGate>\n  );\n}\n\ntype Mode = 'video' | 'podcast' | 'serie' | 'episode';\n\nconst MODE_META: Record<Mode, { title: string; icon: typeof Video; color: string }> = {\n  video: { title: 'Publicar video corto', icon: Video, color: '#7C3AED' },\n  podcast: { title: 'Publicar podcast', icon: Mic, color: '#E0439A' },\n  serie: { title: 'Crear serie', icon: Clapperboard, color: brand.secondary },\n  episode: { title: 'Añadir episodio', icon: Clapperboard, color: brand.secondary },\n};\n\nfunction MediaComposeContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const params = useLocalSearchParams<{ kind?: string; serieId?: string; serieTitle?: string }>();\n  const kind = (MODE_META[params.kind as Mode] ? params.kind as Mode : 'video');\n  const meta = MODE_META[kind];\n  const serieId = params.serieId;\n\n  const [city, setCity] = useState('Malabo');\n  const [title, setTitle] = useState('');\n  const [body, setBody] = useState('');\n  const [file, setFile] = useState<{ uri: string; name: string; mime: string; durSec: number; sizeBytes: number } | null>(null);\n  const [cover, setCover] = useState<{ dataUrl: string; uri: string } | null>(null);\n  /** B2: hoja abierta para elegir la portada desde un fotograma del vídeo. */\n  const [coverSheetOpen, setCoverSheetOpen] = useState(false);\n  const [durManual, setDurManual] = useState('');\n  const [allowComments, setAllowComments] = useState(true);\n  const [allowDownload, setAllowDownload] = useState(false);\n  /**\n   * TANDA C (bis) — PRODUCTOS DENTRO DEL VÍDEO.\n   *\n   * Los productos se enganchan al vídeo igual que a una nota: se ven como **sticker sobre el\n   * reproductor**. Hasta ahora el flujo de publicar vídeo no tenía selector (solo se podía por API),\n   * así que el sticker existía pero nadie podía ponerle producto desde el móvil.\n   */\n  const [productos, setProductos] = useState<string[]>([]);\n  const [prodOpen, setProdOpen] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  // ── Vídeo: perfil (corto/largo) y progreso de la subida firmada ──────────────\n  const [perfilId, setPerfilId] = useState<LbVideoPerfilId>('short');\n  const [progreso, setProgreso] = useState<LbProgreso | null>(null);\n  const [fase, setFase] = useState<'subiendo' | 'verificando' | 'publicando' | null>(null);\n  // La clave subida se guarda para poder borrarla si el paso siguiente falla: si no, un\n  // vídeo de 900 MB se queda ocupando disco hasta el barrido de huérfanos.\n  const claveSubida = useRef<string | null>(null);\n\n  const perfil = LB_VIDEO_PERFILES[perfilId];\n  const esVideo = kind === 'video' || kind === 'episode';\n\n  useEffect(() => {\n    authApi.me().then((m) => { if (m?.city && (LB_CITIES as readonly string[]).includes(m.city)) setCity(m.city); }).catch(() => {});\n  }, []);\n\n  const needsFile = kind === 'video' || kind === 'podcast' || kind === 'episode';\n  const needsCover = kind === 'podcast';\n  const titleRequired = kind === 'video' || kind === 'serie';\n\n  /**\n   * Elige el vídeo y lo MIDE contra el perfil activo.\n   *\n   * Ojo con lo que se puede saber aquí y lo que no: `asset.duration` y `asset.fileSize` los\n   * da el sistema al elegir, y con un vídeo grande a veces vienen a 0. Por eso NO se rechaza\n   * por un dato que falta: se deja pasar y el rechazo real lo hace el servidor al cerrar\n   * (ffprobe mide el archivo de verdad). Aquí solo se avisa de lo que sí se sabe.\n   */\n  const pickVideoFile = async () => {\n    const perm = await ImagePicker.getMediaLibraryPermissionsAsync().catch(() => null);\n    if (perm && !perm.granted && perm.canAskAgain) {\n      const asked = await ImagePicker.requestMediaLibraryPermissionsAsync().catch(() => null);\n      if (!asked?.granted) { Alert.alert('Permiso necesario', 'Necesitamos acceder a tus vídeos para publicar.'); return; }\n    }\n    const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['videos'], quality: 1, selectionLimit: 1 });\n    if (res.canceled || !res.assets?.[0]) return;\n    const asset = res.assets[0];\n    const mime = asset.mimeType ?? 'video/mp4';\n    const sizeBytes = Number(asset.fileSize ?? 0) || 0;\n    const durSec = Math.max(0, Math.round((asset.duration ?? 0) / 1000)) || 0;\n\n    // Si dura más que el perfil corto, NO se rechaza: se propone el largo. Es lo que el\n    // usuario acaba de pedir (un vídeo de 50 minutos) y rechazarlo en seco sería absurdo.\n    if (durSec > LB_VIDEO_PERFILES.short.maxSec && perfilId === 'short') {\n      setPerfilId('long');\n      setError(null);\n    }\n    const activo = durSec > LB_VIDEO_PERFILES.short.maxSec ? LB_VIDEO_PERFILES.long : perfil;\n\n    if (durSec > activo.maxSec) {\n      Alert.alert(\n        'Vídeo demasiado largo',\n        `Dura ${fmtDur(durSec)} y el máximo del vídeo largo son ${Math.round(activo.maxSec / 60)} minutos (${Math.round(activo.maxSec)} s).`,\n      );\n      return;\n    }\n    if (sizeBytes > activo.maxMb * 1024 * 1024) {\n      Alert.alert(\n        'Vídeo muy pesado',\n        `Pesa ${lbPeso(sizeBytes)} y el máximo es ${activo.maxMb} MB. Baja la calidad al grabar (720p) o recórtalo.`,\n      );\n      return;\n    }\n    // El caso que de verdad duele: 15 minutos de vídeo en 4K pueden ser varios GB. Avisar\n    // ANTES de empezar es la diferencia entre publicar y quedarse sin tarifa de datos.\n    if (sizeBytes > 250 * 1024 * 1024) {\n      // El tiempo CALCULADO, no un «puede tardar»: 250 MB a la velocidad de referencia son\n      // ~20 minutos, y saberlo ANTES es lo único que permite decidir si seguir o esperar al wifi.\n      Alert.alert(\n        'Vídeo grande',\n        `${lbPeso(sizeBytes)}${durSec ? ` · ${fmtDur(durSec)}` : ''}\\n`\n        + `Subida estimada con datos móviles: ${lbTiempoSubida(sizeBytes)}.\\n\\n`\n        + 'Puede consumir buena parte de tu tarifa. Con wifi va mucho mejor.\\n\\n'\n        + 'El máximo de la plataforma es 50 minutos.',\n        [{ text: 'Seguir', style: 'default' }],\n      );\n    }\n    setFile({ uri: asset.uri, name: `video-${Date.now()}.mp4`, mime, durSec: Math.max(1, durSec || 1), sizeBytes });\n    setError(null);\n  };\n\n  const pickAudioFile = async () => {\n    const res = await DocumentPicker.getDocumentAsync({ type: ['audio/*'], copyToCacheDirectory: true, multiple: false });\n    if (res.canceled || !res.assets?.[0]) return;\n    const a = res.assets[0];\n    const mime = a.mimeType ?? 'audio/mpeg';\n    const mb = (a.size ?? 0) / (1024 * 1024);\n    if (mb > MEDIA_KIND_ACCEPT.audio.maxMb) {\n      Alert.alert('Audio muy pesado', `Máximo ${MEDIA_KIND_ACCEPT.audio.maxMb} MB.`);\n      return;\n    }\n    setFile({ uri: a.uri, name: a.name || `audio-${Date.now()}.mp3`, mime, durSec: 0, sizeBytes: Number(a.size ?? 0) || 0 });\n    setError(null);\n  };\n\n  const pickCover = async () => {\n    try {\n      const picked = await pickImagesFromLibrary(1);\n      if (picked[0]) setCover(picked[0]);\n    } catch (e) {\n      Alert.alert('Portada', e instanceof Error ? e.message : 'No se pudo elegir la imagen.');\n    }\n  };\n\n  const canSend = useMemo(() => {\n    if (busy) return false;\n    if (titleRequired && title.trim().length < 3) return false;\n    if (needsFile && !file) return false;\n    if (needsCover && !cover) return false;\n    if (kind === 'podcast') {\n      const mins = Number(durManual);\n      if (!Number.isFinite(mins) || mins < 1 || mins > 60) return false;\n    }\n    // Vídeo: manda el PERFIL elegido. En corto sigue siendo 1 minuto; en largo, 50.\n    // Un vídeo corto (≤60 s) se puede publicar en cualquiera de los dos perfiles: el\n    // perfil es del contenido, no del archivo.\n    if (esVideo && file && file.durSec > perfil.maxSec) return false;\n    if (esVideo && file && file.sizeBytes > perfil.maxMb * 1024 * 1024) return false;\n    return true;\n  }, [busy, titleRequired, title, needsFile, file, needsCover, cover, kind, durManual, esVideo, perfil]);\n\n  const durationSec = () => {\n    if (kind === 'podcast') return Math.round(Number(durManual) * 60);\n    return file?.durSec || 60;\n  };\n\n  const submit = async () => {\n    if (!canSend || !file && needsFile) return;\n    setBusy(true);\n    setError(null);\n    setProgreso(null);\n    try {\n      let mediaUrl: string | null = null;\n      let coverUrl: string | null = null;\n      // Póster que genera el servidor al cerrar la subida (saca un fotograma del vídeo). Si\n      // no se aprovecha, la portada se queda vacía y el detalle NO pinta el bloque de media:\n      // `mediaUrls` sale [] y el vídeo se ve \"solo como texto\".\n      let posterSubida: string | null = null;\n      // Duración REAL del archivo verificada por el servidor: es la que se publica (el dato\n      // que traía el selector puede venir a 0 en vídeos grandes).\n      let durVerificada: number | null = null;\n\n      if (needsFile && file) {\n        if (esVideo) {\n          // ── VÍDEO: URL firmada, directo del móvil al almacenamiento, con progreso ──\n          setFase('subiendo');\n          const subido = await subirArchivoFirmado(\n            { uri: file.uri, name: file.name, mimeType: file.mime, sizeBytes: file.sizeBytes || undefined },\n            {\n              purpose: 'post',\n              kind: 'video',\n              durationKind: perfilId,\n              durationSec: file.durSec || undefined,\n              onProgreso: setProgreso,\n              onBillete: (t) => { claveSubida.current = t.key; },\n              // El tope bueno es el que devuelve el servidor (y el que impone MinIO): si\n              // `.env` cambia, la app se entera sola en vez de mentir con un número fijo.\n              comprobarAntes: (t) => {\n                const bytes = file.sizeBytes || 0;\n                if (bytes > t.maxBytes) {\n                  throw new Error(`El vídeo pesa ${lbPeso(bytes)} y el máximo ahora mismo es ${Math.round(t.maxBytes / (1024 * 1024))} MB.`);\n                }\n                if (file.durSec && t.maxSec && file.durSec > t.maxSec) {\n                  throw new Error(`El vídeo dura ${fmtDur(file.durSec)} y el máximo ahora mismo es ${Math.round(t.maxSec / 60)} minutos.`);\n                }\n              },\n            },\n          );\n          setFase('verificando');\n          mediaUrl = subido.url;\n          durVerificada = subido.durationSec;\n          posterSubida = subido.posterUrl;\n          if (!subido.url) throw new Error('El vídeo se subió pero no se pudo obtener su dirección.');\n        } else {\n          // ── AUDIO: el camino de siempre (≤60 MB, ya va fino) ──\n          setFase('subiendo');\n          const up = await lifebookMediaApi.uploadFile('audio', { uri: file.uri, name: file.name, mimeType: file.mime });\n          mediaUrl = up.url;\n        }\n      }\n      if (cover) {\n        const up = await lifebookMediaApi.uploadFile('image', { uri: cover.uri, name: `cover-${Date.now()}.jpg`, mimeType: 'image/jpeg' });\n        coverUrl = up.url;\n      }\n      // La portada que elige el usuario manda; si no eligió ninguna (el caso del vídeo, que no\n      // pide portada), se aprovecha el póster que devolvió el servidor al cerrar la subida.\n      coverUrl = coverUrl ?? posterSubida;\n      setFase('publicando');\n      const durFinal = durVerificada && durVerificada > 0 ? durVerificada : durationSec();\n      if (kind === 'video') {\n        const post = await productosEnNotaApi.publicarVideo({\n          title: title.trim(), body: body.trim() || undefined, city,\n          videoUrl: mediaUrl!, coverUrl: coverUrl ?? undefined,\n          durationSec: durFinal, allowComments, allowDownload,\n          // Los productos viajan DENTRO del vídeo: se pintan como sticker sobre el reproductor.\n          ...(productos.length ? { productIds: productos } : {}),\n        });\n        router.replace({ pathname: '/lifebook-post/[id]', params: { id: post.id } } as never);\n      } else if (kind === 'podcast') {\n        const post = await lifebookMediaApi.createPodcast({\n          title: title.trim() || undefined, body: body.trim() || undefined, city,\n          audioUrl: mediaUrl!, coverUrl: coverUrl!, durationSec: durFinal, allowComments, allowDownload,\n        });\n        router.replace({ pathname: '/lifebook-post/[id]', params: { id: post.id } } as never);\n      } else if (kind === 'serie') {\n        const post = await lifebookMediaApi.createSerie({ title: title.trim(), body: body.trim() || undefined, city, coverUrl: coverUrl ?? undefined });\n        router.replace({ pathname: '/lifebook-post/[id]', params: { id: post.id } } as never);\n      } else if (kind === 'episode' && serieId) {\n        await lifebookMediaApi.addEpisode(serieId, {\n          title: title.trim() || undefined, body: body.trim() || undefined,\n          videoUrl: mediaUrl!, durationSec: durFinal, allowDownload,\n        });\n        router.back();\n      } else {\n        throw new Error('Faltan datos de la serie');\n      }\n      // Publicado: el archivo ya tiene post, no hay nada que limpiar.\n      claveSubida.current = null;\n    } catch (e) {\n      // Si el archivo YA estaba subido y lo que falló fue publicar, se borra: un vídeo de\n      // 900 MB no puede quedarse ocupando disco por un fallo de un segundo.\n      await limpiarSubida(claveSubida.current);\n      claveSubida.current = null;\n      setError(e instanceof Error ? e.message : 'No se pudo publicar. Inténtalo de nuevo.');\n      setBusy(false);\n      setFase(null);\n      setProgreso(null);\n    }\n  };\n\n  const showDur = kind === 'video' || kind === 'episode';\n  const fileLabel = kind === 'podcast' ? 'Archivo de audio' : 'Archivo de vídeo';\n  const fileHint = kind === 'podcast'\n    ? 'mp3 · m4a · aac… (máx 60 MB · 60 min)'\n    : esVideo\n      ? `mp4 · mov · webm (${perfilId === 'long' ? 'máx 1200 MB · 50 min' : 'máx 120 MB · 1 min'})`\n      : 'mp4 · mov · webm';\n  const pesoSubida = file?.sizeBytes ?? 0;\n\n  return (\n    <KeyboardAvoidingView style={{ flex: 1, backgroundColor: colors.background }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n      <View style={{ flex: 1, backgroundColor: colors.background }}>\n        {/* Barra */}\n        <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n          <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}>\n            <ArrowLeft size={22} color={colors.textPrimary} />\n          </Pressable>\n          <Text style={[styles.topTitle, { color: colors.textPrimary }]}>{meta.title}</Text>\n          <Pressable onPress={submit} disabled={!canSend} style={[styles.publishBtn, { backgroundColor: canSend ? meta.color : alpha(colors.textSecondary, 0.25) }]}>\n            {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>Publicar</Text>}\n          </Pressable>\n        </View>\n\n        <ScrollView keyboardShouldPersistTaps=\"handled\" showsVerticalScrollIndicator={false} contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }}>\n          {error ? (\n            <View style={[styles.errorBox, { backgroundColor: alpha(colors.danger, 0.09), borderColor: alpha(colors.danger, 0.4) }]}>\n              <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>{error}</Text>\n            </View>\n          ) : null}\n\n          {/* Archivo principal */}\n          {needsFile && (\n            <>\n              {/* Perfil del vídeo: es una DECISIÓN, no un detalle. El corto es el del feed\n                  (carga al instante); el largo es hasta 50 minutos. */}\n              {esVideo && (\n                <>\n                  <Text style={styles.label}>TIPO DE VÍDEO</Text>\n                  <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n                    {(['short', 'long'] as LbVideoPerfilId[]).map((id) => {\n                      const p = LB_VIDEO_PERFILES[id];\n                      const on = perfilId === id;\n                      return (\n                        <Pressable\n                          key={id}\n                          onPress={() => {\n                            setPerfilId(id);\n                            // Si el archivo elegido no cabe en el perfil nuevo, se suelta:\n                            // dejarlo puesto y con el botón muerto no explica nada.\n                            if (file && (file.durSec > p.maxSec || file.sizeBytes > p.maxMb * 1024 * 1024)) setFile(null);\n                            setError(null);\n                          }}\n                          style={[styles.perfilCard, {\n                            backgroundColor: on ? alpha(meta.color, 0.10) : colors.surface,\n                            borderColor: on ? alpha(meta.color, 0.65) : colors.border,\n                          }]}\n                        >\n                          <Text style={{ color: on ? meta.color : colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>{p.label}</Text>\n                          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>{p.hint}</Text>\n                          <Text style={{ color: colors.textSecondary, fontSize: 10.5, marginTop: espaciado.e2 }}>{p.desc}</Text>\n                        </Pressable>\n                      );\n                    })}\n                  </View>\n                  {perfilId === 'long' && (\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e6, lineHeight: 15 }}>\n                      Un vídeo de 50 minutos ocupa mucho. Intenta grabar en 720p: se ve bien y pesa\n                      la mitad.{pesoSubida > 0\n                        ? ` Este pesa ${lbPeso(pesoSubida)}: con datos móviles son ${lbTiempoSubida(pesoSubida)} de subida.`\n                        : ' La subida se hace directa al almacenamiento, pero en datos móviles puede tardar y gastar bastante.'}\n                    </Text>\n                  )}\n                </>\n              )}\n\n              <Text style={styles.label}>{fileLabel} *</Text>\n              <Pressable\n                onPress={busy ? undefined : (kind === 'podcast' ? pickAudioFile : pickVideoFile)}\n                style={[styles.dropZone, { backgroundColor: colors.surface, borderColor: file ? alpha(colors.success, 0.6) : colors.border }]}\n              >\n                {file ? (\n                  <View style={{ alignItems: 'center', gap: espaciado.e6 }}>\n                    <Text style={{ fontSize: 34 }}>{kind === 'podcast' ? '🎙️' : '🎬'}</Text>\n                    <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }} numberOfLines={1}>\n                      {file.name}\n                    </Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                      {fmtDur(file.durSec)}{pesoSubida ? ` · ${lbPeso(pesoSubida)}` : ''} · listo para publicar\n                    </Text>\n                    {!busy && (\n                      <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800', marginTop: espaciado.e2 }}>Toca para cambiar</Text>\n                    )}\n                  </View>\n                ) : (\n                  <View style={{ alignItems: 'center', gap: espaciado.e6 }}>\n                    {kind === 'podcast' ? <Mic size={30} color={meta.color} /> : <Video size={30} color={meta.color} />}\n                    <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>{fileLabel}</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>{fileHint}</Text>\n                  </View>\n                )}\n              </Pressable>\n\n              {/* Progreso REAL de la subida: sin esto, 900 MB son una pantalla congelada. */}\n              {busy && progreso && fase === 'subiendo' && progreso.total > 0 && (\n                <View style={{ marginTop: espaciado.e8 }}>\n                  <View style={[styles.progTrack, { backgroundColor: colors.border }]}>\n                    <View style={[styles.progFill, { width: `${Math.round(progreso.fraccion * 100)}%`, backgroundColor: meta.color }]} />\n                  </View>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e4 }}>\n                    {lbPeso(progreso.enviados)} de {lbPeso(progreso.total)} · {Math.round(progreso.fraccion * 100)} %\n                    {progreso.mbps > 0.05 ? ` · ${progreso.mbps.toFixed(1).replace('.', ',')} MB/s` : ''}\n                    {progreso.restanteSec !== null ? ` · faltan ~${fmtDur(progreso.restanteSec)}` : ''}\n                  </Text>\n                </View>\n              )}\n\n              {esVideo && file && file.durSec > perfil.maxSec && (\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>\n                  ⚠️ El vídeo dura {fmtDur(file.durSec)} y {perfil.label.toLowerCase()} llega a {fmtDur(perfil.maxSec)}.\n                  {perfilId === 'short' ? ' Cámbialo a vídeo largo.' : ''}\n                </Text>\n              )}\n              {esVideo && file && file.durSec <= perfil.maxSec && file.sizeBytes > perfil.maxMb * 1024 * 1024 && (\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e4 }}>\n                  ⚠️ Pesa {lbPeso(file.sizeBytes)} y el máximo es {perfil.maxMb} MB.\n                </Text>\n              )}\n            </>\n          )}\n\n          {/* Podcast: duración manual en minutos */}\n          {kind === 'podcast' && (\n            <>\n              <Text style={styles.label}>DURACIÓN (minutos) *</Text>\n              <TextInput\n                value={durManual}\n                onChangeText={(t) => setDurManual(t.replace(/[^0-9]/g, '').slice(0, 2))}\n                keyboardType=\"number-pad\"\n                placeholder=\"p. ej. 28\"\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\n              />\n            </>\n          )}\n\n          {/* Portada */}\n          {(kind === 'video' || kind === 'serie' || kind === 'podcast') && (\n            <>\n              <Text style={styles.label}>\n                PORTADA ({kind === 'podcast' ? 'OBLIGATORIA 1:1' : 'recomendada'})\n              </Text>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\n                {cover ? (\n                  <View>\n                    <Image source={{ uri: cover.uri }} style={styles.coverPreview} />\n                    <Pressable onPress={() => setCover(null)} style={[styles.photoX, { backgroundColor: 'rgba(0,0,0,0.6)' }]} accessibilityLabel=\"Quitar portada\">\n                      <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.micro }}>✕</Text>\n                    </Pressable>\n                  </View>\n                ) : null}\n                <Pressable onPress={pickCover} style={[styles.coverAdd, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                  <ImagePlus size={22} color={colors.primary} />\n                  <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>{cover ? 'Cambiar' : 'Añadir portada'}</Text>\n                </Pressable>\n                {/* B2: portada desde un fotograma del vídeo. Solo con vídeo ya elegido y\n                    solo en 'video': 'serie' no tiene archivo todavía y 'podcast' es audio,\n                    y de un audio no hay fotograma que sacar. `Video` ya estaba importado. */}\n                {kind === 'video' && file ? (\n                  <Pressable\n                    onPress={() => setCoverSheetOpen(true)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Elegir la portada desde un fotograma del vídeo\"\n                    style={[styles.coverAdd, { backgroundColor: colors.surface, borderColor: colors.border }]}\n                  >\n                    <Video size={22} color={colors.primary} />\n                    <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Del vídeo</Text>\n                  </Pressable>\n                ) : null}\n              </View>\n            </>\n          )}\n\n          {/* Título */}\n          {(kind === 'video' || kind === 'serie' || kind === 'episode') && (\n            <>\n              <Text style={styles.label}>TÍTULO {titleRequired ? '*' : '(opcional)'}</Text>\n              <TextInput\n                value={title}\n                onChangeText={setTitle}\n                maxLength={LB_NOTE_TITLE_MAX}\n                placeholder={kind === 'serie' ? 'Nombre de la serie' : kind === 'episode' ? 'Título del episodio' : 'Título del video'}\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\n              />\n            </>\n          )}\n\n          {/* Descripción */}\n          <Text style={styles.label}>DESCRIPCIÓN {kind === 'podcast' || kind === 'episode' ? '(opcional)' : '(opcional)'}</Text>\n          <TextInput\n            value={body}\n            onChangeText={setBody}\n            multiline\n            placeholder=\"Cuéntanos de qué va…\"\n            placeholderTextColor={colors.textSecondary}\n            maxLength={LB_NOTE_BODY_MAX}\n            style={[styles.textArea, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\n          />\n\n          {/* Ciudad (no en episode: pertenece a la serie) */}\n          {kind !== 'episode' && (\n            <>\n              <Text style={styles.label}>CIUDAD *</Text>\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e7 }}>\n                {LB_CITIES.map((c) => {\n                  const on = city === c;\n                  return (\n                    <Pressable key={c} onPress={() => setCity(c)} style={[styles.chip, { backgroundColor: on ? alpha(colors.primary, 0.14) : colors.surface, borderColor: on ? alpha(colors.primary, 0.55) : colors.border }]}>\n                      <Text style={{ color: on ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{c}</Text>\n                    </Pressable>\n                  );\n                })}\n              </View>\n            </>\n          )}\n\n          {/* TANDA C (bis) — productos DENTRO del vídeo. Solo para VÍDEO: es el único tipo cuya\n              publicación acepta `productIds` (se ven como sticker sobre el reproductor). En\n              podcast/serie/episodio no se ofrece, en vez de ofrecerlo y perderlo por el camino. */}\n          {kind === 'video' ? (\n            <>\n              <Text style={styles.label}>PRODUCTOS DEL VÍDEO (opcional)</Text>\n              <Pressable\n                onPress={() => setProdOpen(true)}\n                accessibilityLabel=\"Elegir productos para este vídeo\"\n                style={{\n                  flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderRadius: radios.md,\n                  borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e11,\n                  backgroundColor: productos.length ? alpha(colors.primary, 0.14) : colors.surface,\n                  borderColor: productos.length ? alpha(colors.primary, 0.55) : colors.border,\n                }}\n              >\n                <ShoppingBag size={14} color={productos.length ? colors.primary : colors.textSecondary} />\n                <Text style={{ color: productos.length ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                  {productos.length\n                    ? `${productos.length} producto${productos.length === 1 ? '' : 's'} en este vídeo`\n                    : 'Enseñar un producto en el vídeo (opcional)'}\n                </Text>\n              </Pressable>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e6, lineHeight: 15 }}>\n                Sale como una pegatina encima del vídeo, con su precio. Solo productos de tu tienda.\n              </Text>\n            </>\n          ) : null}\n\n          {/* Permisos */}\n          {kind !== 'serie' && (\n            <View style={{ marginTop: espaciado.e18 }}>\n              <View style={styles.switchRow}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>Permitir comentarios</Text>\n                <Switch value={allowComments} onValueChange={setAllowComments} trackColor={{ true: colors.primary }} />\n              </View>\n              <View style={styles.switchRow}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>Permitir descarga</Text>\n                <Switch value={allowDownload} onValueChange={setAllowDownload} trackColor={{ true: colors.primary }} />\n              </View>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\n                {allowDownload ? 'Cualquiera podrá descargar el archivo.' : 'Solo se podrá escuchar/ver en streaming.'}\n              </Text>\n            </View>\n          )}\n\n          <Pressable onPress={submit} disabled={!canSend} style={[styles.bigPublish, { backgroundColor: canSend ? meta.color : alpha(colors.textSecondary, 0.25) }]}>\n            {busy ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Upload size={18} color={brand.white} />}\n            <Text style={{ color: brand.white, fontSize: tipografia.subtitle, fontWeight: '900' }}>\n              {fase === 'subiendo'\n                ? (progreso && progreso.total > 0\n                  ? `Subiendo… ${Math.round(progreso.fraccion * 100)} %`\n                  : 'Subiendo…')\n                : fase === 'verificando' ? 'Comprobando el archivo…'\n                  : fase === 'publicando' ? 'Publicando…'\n                    : meta.title}\n            </Text>\n          </Pressable>\n        </ScrollView>\n      </View>\n\n      {/* B2: elegir portada desde un fotograma del vídeo.\n          Al confirmar, el fotograma ya es un ARCHIVO LOCAL (`{ uri, dataUrl }`, la misma\n          forma que devuelve la galería) y entra en el mismo estado `cover`. Así la subida\n          no cambia: sigue siendo `uploadFile('image', { uri: cover.uri, … })` y hay UNA\n          sola vía de portada, no dos. Sin esto habría que tocar también `submit`. */}\n      {/* TANDA C (bis): la MISMA hoja de productos que usa el compositor de notas\n          (`components/lifebook/SelectorDeProductos.tsx`). Así las dos pantallas se comportan\n          igual: mismo orden numerado, mismo tope y mismas reglas. */}\n      <SelectorDeProductos\n        visible={prodOpen}\n        onClose={() => setProdOpen(false)}\n        seleccion={productos}\n        onCambiar={setProductos}\n        titulo=\"Productos en este vídeo\"\n        ayuda=\"Se verán como sticker ENCIMA del vídeo, en el orden en que los elijas.\"\n      />\n\n      <VideoCoverSheet\n        visible={coverSheetOpen && kind === 'video' && !!file}\n        videoUri={file?.uri ?? ''}\n        durSec={file?.durSec ?? 0}\n        onClose={() => setCoverSheetOpen(false)}\n        onPick={(c) => { setCover(c); setError(null); }}\n      />\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: tipografia.subtitle, fontWeight: '900', flex: 1 },\n  publishBtn: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, minWidth: 76, alignItems: 'center' },\n  label: { fontSize: tipografia.caption, fontWeight: '900', color: '#86909C', letterSpacing: 0.8, marginTop: espaciado.e16, marginBottom: espaciado.e6 },\n  dropZone: { borderRadius: radios.lg, borderWidth: 1.5, borderStyle: 'dashed', paddingVertical: espaciado.e26, paddingHorizontal: espaciado.e16, alignItems: 'center' },\n  coverPreview: { width: 84, height: 84, borderRadius: 14, backgroundColor: '#EEE' },\n  photoX: { position: 'absolute', top: -6, right: -6, width: 20, height: 20, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },\n  coverAdd: { borderRadius: 14, borderWidth: 1, borderStyle: 'dashed', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, alignItems: 'center', gap: espaciado.e4 },\n  input: { borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9, fontSize: tipografia.body },\n  textArea: { borderRadius: radios.md, borderWidth: 1, padding: espaciado.e12, fontSize: tipografia.body, minHeight: 84, textAlignVertical: 'top' },\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e6, borderWidth: 1, borderColor: 'transparent' },\n  switchRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: espaciado.e6 },\n  bigPublish: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8, borderRadius: radios.full, paddingVertical: espaciado.e14, marginTop: espaciado.e22 },\n  errorBox: { borderRadius: radios.md, borderWidth: 1, padding: espaciado.e10, marginBottom: espaciado.e4 },\n  perfilCard: { flex: 1, borderRadius: 14, borderWidth: 1.5, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10 },\n  progTrack: { height: 6, borderRadius: radios.full, overflow: 'hidden' },\n  progFill: { height: 6, borderRadius: radios.full },\n});\n","/**\n * Life Book · SUBIDA REAL DE MEDIA (Parte 50) — cliente de la subida FIRMADA.\n *\n * Rutas (bajo `/wallet/api/v1`, que es el base de `httpClient`):\n *   POST   /lifebook/commerce/media/upload-url   → billete de subida (URL firmada + tope)\n *   POST   /lifebook/commerce/media/complete     → cierra y VERIFICA el archivo real\n *   POST   /lifebook/commerce/media/sign-read    → lectura firmada (documentos privados)\n *   GET    /lifebook/commerce/media/quota        → cuota de 24 h y material pendiente\n *   DELETE /lifebook/commerce/media?key=…        → borra una subida propia\n *\n * ── POR QUÉ EXISTE ESTE CAMINO ────────────────────────────────────────────────\n * El endpoint viejo (`POST /lifebook/media/upload`, multipart contra el API) hace que\n * el archivo pase por Node: la petición entra por nginx, se copia en memoria/temporal y\n * desde ahí va a MinIO. Con un vídeo de 50 minutos eso son ~900 MB atravesando el proceso\n * del API… y sin forma de saber por dónde va (ni de reanudar). Aquí el archivo va **directo\n * del móvil al almacenamiento** con una URL firmada, y el API solo firma y luego verifica.\n *\n * ── LO QUE ESTE MÓDULO **NO** HACE (a propósito) ──────────────────────────────\n *   · No decide topes: los devuelve el servidor (`maxBytes` / `maxSec`) y además los\n *     impone MinIO en la política de la URL firmada. Aquí solo se avisa antes.\n *   · No confía en lo que declara el cliente: `complete` re-lee el archivo con ffprobe y\n *     responde la duración/tamaño reales. Si el archivo no está donde se dijo, falla.\n *   · No manda el token JWT a MinIO: la URL firmada es autosuficiente.\n */\nimport { http, httpRequest } from './httpClient';\nimport { mimeToExt } from '../constants/lifebook';\n\n/** Uso de la subida: decide el bucket y la visibilidad en el servidor. */\nexport type LbMediaPurpose = 'post' | 'product' | 'docs';\n/** Perfil de duración del vídeo (espejo del backend: 60 s vs 3000 s). */\nexport type LbDurationKind = 'short' | 'long';\n\n/** Billete de subida tal cual lo devuelve `upload-url`. */\nexport interface LbTicketSubida {\n  /** URL del POST firmado (MinIO, directo desde el móvil). */\n  uploadUrl: string;\n  /** Campos del formulario que hay que enviar TAL CUAL, antes del archivo. */\n  fields: Record<string, string>;\n  /** Clave del objeto reservada ya en la base (sirve para cerrar y para borrar). */\n  key: string;\n  bucket: string;\n  visibility: 'public' | 'private';\n  /** URL pública definitiva (null si el bucket es privado). */\n  publicUrl: string | null;\n  /** Tope de bytes que impone el almacenamiento para ESTA subida. */\n  maxBytes: number;\n  /** Tope de segundos (solo vídeo/audio); null si no aplica. */\n  maxSec: number | null;\n  durationKind: LbDurationKind;\n  expiresIn: number;\n  method: 'POST';\n  fileField: string;\n  restantesHoy: number;\n}\n\n/** Respuesta de `complete`: el archivo ya verificado de verdad. */\nexport interface LbMediaVerificada {\n  key: string;\n  bucket: string;\n  visibility: 'public' | 'private';\n  url: string;\n  signedUrl: string | null;\n  posterUrl: string | null;\n  bytes: number;\n  contentType: string;\n  durationSec: number | null;\n  codec: string | null;\n  width: number | null;\n  height: number | null;\n  verified: true;\n}\n\n/** Cuota y material pendiente. */\nexport interface LbCuotaMedia {\n  usadasHoy: number;\n  maxHoy: number;\n  pendienteBytes: number;\n  maxPendienteBytes: number;\n  totalBytes: number;\n  huerfanos: number;\n  buckets: { media: string; docs: string };\n}\n\nexport interface LbEntradaSubida {\n  purpose?: LbMediaPurpose;\n  kind: 'image' | 'video' | 'audio' | 'file';\n  /** Solo vídeo: 'short' (≤60 s) o 'long' (≤3000 s). */\n  durationKind?: LbDurationKind;\n  mimeType: string;\n  fileSizeBytes?: number;\n  durationSec?: number;\n}\n\n/** Progreso de la subida, en unidades que se pueden pintar sin calcular nada. */\nexport interface LbProgreso {\n  enviados: number;\n  total: number;\n  /** 0…1 (cuando el total no se conoce, se queda en 0). */\n  fraccion: number;\n  /** MB/s medidos desde el arranque de ESTA subida. */\n  mbps: number;\n  /** Segundos que faltan según la velocidad media; null si aún no se puede estimar. */\n  restanteSec: number | null;\n}\n\nexport const lifebookMediaRealApi = {\n  /** Pide el billete de subida (reserva la clave y devuelve la URL firmada). */\n  billete: (input: LbEntradaSubida) =>\n    httpRequest<LbTicketSubida>('/lifebook/commerce/media/upload-url', { method: 'POST', body: input }),\n\n  /** Cierra la subida: el servidor verifica tamaño, tipo, duración y saca el póster. */\n  cerrar: (key: string, durationSec?: number) =>\n    httpRequest<LbMediaVerificada>('/lifebook/commerce/media/complete', {\n      method: 'POST',\n      body: durationSec === undefined ? { key } : { key, durationSec },\n    }),\n\n  /** Cuota de las últimas 24 h + bytes pendientes de publicar. */\n  cuota: () => http.get<LbCuotaMedia>('/lifebook/commerce/media/quota'),\n\n  /** Lectura firmada (documentos privados). */\n  lecturaFirmada: (key: string) =>\n    httpRequest<{ key: string; signedUrl: string; expiresIn: number }>('/lifebook/commerce/media/sign-read', {\n      method: 'POST',\n      body: { key },\n    }),\n\n  /** Borra una subida propia (y su póster). */\n  borrar: (key: string) =>\n    httpRequest<{ deleted: boolean; key: string }>(`/lifebook/commerce/media?key=${encodeURIComponent(key)}`, {\n      method: 'DELETE',\n    }),\n};\n\n/**\n * Sube el archivo por la URL firmada, con PROGRESO, y lo cierra (`complete`).\n *\n * El orden del formulario NO es cosmético: MinIO exige que el campo del archivo vaya\n * **el último** (todo lo que va detrás se ignora y la firma deja de cuadrar).\n */\nexport async function subirArchivoFirmado(\n  archivo: { uri: string; name: string; mimeType: string; sizeBytes?: number },\n  opts: {\n    purpose?: LbMediaPurpose;\n    kind?: 'image' | 'video' | 'audio' | 'file';\n    durationKind?: LbDurationKind;\n    durationSec?: number;\n    onProgreso?: (p: LbProgreso) => void;\n    onBillete?: (t: LbTicketSubida) => void;\n    /** 0 = sin límite (una subida de 900 MB por red lenta tarda lo que tarde). */\n    timeoutMs?: number;\n    /** Verificación local ANTES de gastar datos: lanza Error con mensaje claro. */\n    comprobarAntes?: (t: LbTicketSubida) => void;\n  } = {},\n): Promise<LbMediaVerificada> {\n  const kind = opts.kind ?? 'video';\n  const mimeType = archivo.mimeType || (kind === 'video' ? 'video/mp4' : 'application/octet-stream');\n  const fileSizeBytes = Number(archivo.sizeBytes ?? 0) || undefined;\n\n  const billete = await lifebookMediaRealApi.billete({\n    purpose: opts.purpose ?? 'post',\n    kind,\n    ...(kind === 'video' ? { durationKind: opts.durationKind ?? 'short' } : {}),\n    mimeType,\n    ...(fileSizeBytes ? { fileSizeBytes } : {}),\n    ...(opts.durationSec ? { durationSec: Math.round(opts.durationSec) } : {}),\n  });\n  opts.onBillete?.(billete);\n  opts.comprobarAntes?.(billete);\n\n  const total = fileSizeBytes ?? 0;\n  const inicio = Date.now();\n  await enviarAlAlmacen(billete, archivo, total, inicio, opts.onProgreso, opts.timeoutMs);\n\n  // Solo ahora se cierra: si la verificación falla, el objeto queda 'pending' con dueño\n  // y fecha (lo barre `purge-orphans`), no publicado a medias.\n  return lifebookMediaRealApi.cerrar(billete.key, opts.durationSec);\n}\n\n/** El POST multipart contra la URL firmada, con `upload.onprogress`. */\nfunction enviarAlAlmacen(\n  billete: LbTicketSubida,\n  archivo: { uri: string; name: string; mimeType: string },\n  totalDeclarado: number,\n  inicio: number,\n  onProgreso?: (p: LbProgreso) => void,\n  timeoutMs = 0,\n): Promise<void> {\n  return new Promise<void>((resolve, reject) => {\n    const form = new FormData();\n    // 1) Todos los campos de la política, en el orden que los devolvió el servidor.\n    Object.entries(billete.fields).forEach(([k, v]) => form.append(k, String(v)));\n    // 2) El archivo, SIEMPRE el último.\n    form.append(billete.fileField || 'file', {\n      uri: archivo.uri,\n      name: archivo.name || `subida.${mimeToExt(archivo.mimeType)}`,\n      type: archivo.mimeType,\n    } as unknown as Blob);\n    // 3) El Content-Type del formulario lo pone el runtime con su boundary: si se fija a\n    //    mano (como en el camino multipart del API) la política `eq $Content-Type` de\n    //    MinIO compara contra el VALOR del campo, no contra la cabecera.\n\n    const xhr = new XMLHttpRequest();\n    xhr.open(billete.method || 'POST', billete.uploadUrl, true);\n    if (timeoutMs > 0) xhr.timeout = timeoutMs;\n\n    xhr.upload.onprogress = (e: ProgressEvent) => {\n      if (!onProgreso) return;\n      const total = e.lengthComputable ? e.total : totalDeclarado;\n      const seg = Math.max(0.15, (Date.now() - inicio) / 1000);\n      const mbps = e.loaded / (1024 * 1024) / seg;\n      onProgreso({\n        enviados: e.loaded,\n        total,\n        fraccion: total > 0 ? Math.min(1, e.loaded / total) : 0,\n        mbps: Number(mbps.toFixed(2)),\n        restanteSec: mbps > 0.05 && total > e.loaded ? Math.round((total - e.loaded) / (1024 * 1024) / mbps) : null,\n      });\n    };\n\n    xhr.onload = () => {\n      // MinIO responde 204 sin cuerpo al aceptar un POST de formulario.\n      if (xhr.status >= 200 && xhr.status < 300) return resolve();\n      const cuerpo = String(xhr.responseText ?? '').slice(0, 300);\n      reject(new Error(\n        xhr.status === 403\n          ? 'El almacenamiento rechazó la subida (la URL firmada caducó o el peso supera el tope). Vuelve a intentarlo.'\n          : `La subida falló (HTTP ${xhr.status}). ${cuerpo}`.trim(),\n      ));\n    };\n    xhr.onerror = () => reject(new Error('Se cortó la conexión durante la subida. Comprueba tu red y vuelve a intentarlo.'));\n    xhr.ontimeout = () => reject(new Error('La subida tardó demasiado y se canceló. Prueba con una red más rápida.'));\n    xhr.onabort = () => reject(new Error('Subida cancelada.'));\n\n    try {\n      xhr.send(form as unknown as Document);\n    } catch (e) {\n      reject(e instanceof Error ? e : new Error('No se pudo iniciar la subida.'));\n    }\n  });\n}\n\n/**\n * Borra un objeto que quedó subido pero sin publicar (best-effort).\n *\n * Se usa cuando algo falla DESPUÉS de subir (p. ej. crear el post): mejor liberar el\n * espacio ahora que dejar 900 MB colgando hasta el barrido de huérfanos.\n */\nexport async function limpiarSubida(key: string | null | undefined): Promise<void> {\n  if (!key) return;\n  try { await lifebookMediaRealApi.borrar(key); } catch { /* best-effort */ }\n}\n","/**\n * VideoCoverSheet — elegir la portada de un vídeo desde uno de sus fotogramas (B2).\n *\n * ── POR QUÉ ───────────────────────────────────────────────────────────────────\n * Antes la portada solo podía venir de la galería o del servidor, que saca SIEMPRE\n * el fotograma del segundo 1. Un vídeo que arranca en negro se publicaba así. Esta\n * hoja ofrece una tira de fotogramas repartidos por el vídeo y se elige uno.\n *\n * ── LÍMITES HONESTOS, no disimulados ──────────────────────────────────────────\n * · Los fotogramas se sacan del archivo LOCAL, antes de subirlo. Si el usuario\n *   cambia de vídeo hay que volver a extraerlos (esta hoja lo hace al abrirse).\n * · Extraer fotogramas cuesta unos segundos en un móvil y puede fallar (codec no\n *   admitido, archivo corrupto). Por eso hay estado de carga, error con mensaje en\n *   español, y el error NO bloquea: se puede cerrar y usar la galería.\n * · No es un scrubber frame-a-frame. Son N fotogramas repartidos (por defecto 6).\n *   Un scrubber exigiría precargar el vídeo entero en memoria; con vídeos de hasta\n *   50 min eso no es viable en un móvil.\n *\n * ── CONVENCIONES DEL PROYECTO ─────────────────────────────────────────────────\n * expo-image para imágenes de contenido (caché memoria+disco), colores desde\n * useTheme(), textos en español directamente (no hay i18n), a11y en los botones.\n */\n\nimport React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Clapperboard, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { extraerFrames, type VideoFrame } from '../../core/videoFrames';\nimport { fmtDur } from '../../constants/lifebook';\n\nexport function VideoCoverSheet({\n  visible,\n  videoUri,\n  durSec,\n  onClose,\n  onPick,\n}: {\n  visible: boolean;\n  /** URI local del vídeo (la que dio el picker). */\n  videoUri: string;\n  /** Duración en segundos, para repartir los fotogramas. */\n  durSec: number;\n  onClose: () => void;\n  /** Devuelve el fotograma elegido como `{ uri, dataUrl }`, la forma que ya usa\n   *  el estado `cover` de la pantalla de publicar. */\n  onPick: (cover: { uri: string; dataUrl: string }) => void;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [frames, setFrames] = useState<VideoFrame[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [selected, setSelected] = useState<number | null>(null);\n\n  // Extraer al abrir. Se cancela con `cancelado` porque extraer fotogramas tarda\n  // varios segundos y el usuario puede cerrar la hoja o cambiar de vídeo antes:\n  // sin esto se llamaría a `setFrames` sobre una hoja ya desmontada, o se\n  // pintarían los fotogramas del VÍDEO ANTERIOR al reabrir.\n  //\n  // La bandera vive en el propio efecto (no en un `useCallback` aparte): un `let`\n  // dentro de una función asíncrona no puede cambiar mientras espera, así que una\n  // cancelación declarada ahí no cancelaría nada. Aquí `cancelado` lo fija el\n  // cleanup del efecto, que sí corre al desmontar o al cambiar de vídeo.\n  useEffect(() => {\n    if (!visible || !videoUri) return;\n    let cancelado = false;\n    // Reset al abrir: si se cambió de vídeo, los fotogramas viejos no valen.\n    setLoading(true);\n    setError(null);\n    setFrames([]);\n    setSelected(null);\n    void (async () => {\n      try {\n        const f = await extraerFrames(videoUri, durSec, 6);\n        if (cancelado) return;\n        setFrames(f);\n        setSelected(f.length > 0 ? 0 : null);\n      } catch (e) {\n        if (cancelado) return;\n        setError(e instanceof Error ? e.message : 'No se pudieron extraer los fotogramas.');\n      } finally {\n        if (!cancelado) setLoading(false);\n      }\n    })();\n    return () => { cancelado = true; };\n  }, [visible, videoUri, durSec]);\n\n  const confirmar = () => {\n    if (selected === null) return;\n    const f = frames[selected];\n    if (!f) return;\n    onPick({ uri: f.uri, dataUrl: f.dataUrl });\n    onClose();\n  };\n\n  return (\n    <Modal visible={visible} animationType=\"slide\" transparent onRequestClose={onClose}>\n      <Pressable style={s.backdrop} onPress={onClose} accessibilityViewIsModal>\n        <Pressable\n          style={[s.card, { backgroundColor: colors.card, paddingBottom: espaciado.e16 + insets.bottom }]}\n          onPress={() => undefined}\n        >\n          <View style={s.head}>\n            <Clapperboard size={18} color={colors.primary} />\n            <Text style={[s.title, { color: colors.textPrimary }]}>Portada del vídeo</Text>\n            <Pressable onPress={onClose} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar\">\n              <X size={20} color={colors.textPrimary} />\n            </Pressable>\n          </View>\n\n          {loading ? (\n            <View style={s.center}>\n              <ActivityIndicator color={colors.primary} />\n              <Text style={[s.hint, { color: colors.textSecondary, marginTop: espaciado.e10 }]}>\n                Extrayendo fotogramas del vídeo…\n              </Text>\n            </View>\n          ) : error ? (\n            <View style={[s.errorBox, { backgroundColor: alpha(colors.danger, 0.08), borderColor: alpha(colors.danger, 0.25) }]}>\n              <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', lineHeight: 18 }}>{error}</Text>\n            </View>\n          ) : frames.length === 0 ? (\n            <View style={s.center}>\n              <Text style={[s.hint, { color: colors.textSecondary }]}>Sin fotogramas disponibles.</Text>\n            </View>\n          ) : (\n            <>\n              <Text style={[s.hint, { color: colors.textSecondary, marginBottom: espaciado.e10 }]}>\n                Toca el fotograma que quieres como portada. {frames.length} momentos del vídeo.\n              </Text>\n              <ScrollView\n                horizontal\n                showsHorizontalScrollIndicator={false}\n                contentContainerStyle={{ gap: espaciado.e8, paddingRight: espaciado.e8 }}\n              >\n                {frames.map((f, i) => {\n                  const activo = selected === i;\n                  return (\n                    <Pressable\n                      key={`${f.requestedSec}-${i}`}\n                      onPress={() => setSelected(i)}\n                      accessibilityRole=\"button\"\n                      accessibilityState={{ selected: activo }}\n                      accessibilityLabel={`Fotograma del segundo ${fmtDur(Math.round(f.timeSec))}${activo ? ', seleccionado' : ''}`}\n                      style={[\n                        s.thumbWrap,\n                        { borderColor: activo ? colors.primary : 'transparent', borderWidth: activo ? 3 : 0 },\n                      ]}\n                    >\n                      <Image\n                        source={{ uri: f.dataUrl }}\n                        style={s.thumb}\n                        contentFit=\"cover\"\n                        cachePolicy=\"memory-disk\"\n                        transition={120}\n                      />\n                      <View style={s.thumbTime}>\n                        <Text style={s.thumbTimeText}>{fmtDur(Math.round(f.timeSec))}</Text>\n                      </View>\n                    </Pressable>\n                  );\n                })}\n              </ScrollView>\n\n              {/* Vista grande del elegido: permite ver de verdad qué se publica. */}\n              {selected !== null && frames[selected] ? (\n                <View style={{ alignItems: 'center', marginTop: espaciado.e14 }}>\n                  <Image\n                    source={{ uri: frames[selected].dataUrl }}\n                    style={[s.preview, { borderColor: colors.border }]}\n                    contentFit=\"contain\"\n                    cachePolicy=\"memory-disk\"\n                  />\n                </View>\n              ) : null}\n\n              <Pressable\n                onPress={confirmar}\n                disabled={selected === null}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Usar este fotograma como portada\"\n                style={[s.confirm, { backgroundColor: colors.primary, opacity: selected === null ? 0.4 : 1 }]}\n              >\n                <Text style={s.confirmText}>Usar esta portada</Text>\n              </Pressable>\n            </>\n          )}\n        </Pressable>\n      </Pressable>\n    </Modal>\n  );\n}\n\nconst s = StyleSheet.create({\n  backdrop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'flex-end' },\n  card: { borderTopLeftRadius: 20, borderTopRightRadius: 20, paddingHorizontal: espaciado.e16, paddingTop: espaciado.e16 },\n  head: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginBottom: espaciado.e12 },\n  title: { flex: 1, fontSize: tipografia.subtitle, fontWeight: '800' },\n  center: { alignItems: 'center', paddingVertical: 34 },\n  hint: { fontSize: tipografia.caption, lineHeight: 16 },\n  errorBox: { borderRadius: 10, borderWidth: 1, padding: espaciado.e10, marginBottom: espaciado.e8 },\n  thumbWrap: { borderRadius: 10, overflow: 'hidden' },\n  thumb: { width: 96, height: 128, backgroundColor: 'rgba(0,0,0,0.08)' },\n  thumbTime: {\n    position: 'absolute', left: 4, bottom: 4, borderRadius: 6,\n    backgroundColor: 'rgba(0,0,0,0.62)', paddingHorizontal: espaciado.e5, paddingVertical: 1,\n  },\n  thumbTimeText: { color: brand.white, fontSize: 10, fontWeight: '800' },\n  preview: { width: 170, height: 226, borderRadius: radios.md, borderWidth: 1, backgroundColor: '#000000' },\n  confirm: { borderRadius: radios.md, paddingVertical: espaciado.e13, alignItems: 'center', marginTop: espaciado.e16 },\n  confirmText: { color: brand.white, fontSize: 14.5, fontWeight: '900' },\n});\n\nexport default VideoCoverSheet;\n","/**\n * videoFrames — extraer fotogramas de un vídeo LOCAL para usarlos como portada (B2).\n *\n * ── POR QUÉ EXISTE ────────────────────────────────────────────────────────────\n * Publicar un vídeo dejaba la portada en manos del servidor: `extractPoster` saca\n * SIEMPRE el fotograma del segundo 1 (`lb41-media.service.ts:405`). Un vídeo que\n * empieza en negro, con una transición o con un plano movido se publica con esa\n * portada, y la portada es lo que decide si alguien entra. Esto deja elegir.\n *\n * ── LA CADENA, VERIFICADA CONTRA LOS .d.ts DE LA VERSIÓN INSTALADA ─────────────\n * 1. `VideoPlayer.generateThumbnailsAsync(times, opts)` → `VideoThumbnail[]`\n *    (expo-video 2.2.2, android+ios). Cada thumbnail es un `SharedRef<'image'>`:\n *    referencia nativa, SIN `uri`. Se puede pintar con expo-image pero NO se puede\n *    subir tal cual — por eso hace falta el paso 2.\n * 2. `ImageManipulator.manipulate(sharedRef)` acepta `string | SharedRef<'image'>`\n *    → `ImageManipulatorContext` → `renderAsync()` → `ImageRef` → `saveAsync()`\n *    → `{ uri, base64 }`. Ahí ya hay ARCHIVO, que es lo que se sube.\n *\n * ⚠️ `useImageManipulator` NO sirve aquí: usa `useReleasingSharedObject`, o sea es\n * un HOOK de React, y esto se llama desde un handler asíncrono. Se usa el módulo\n * nativo (`ImageManipulator.manipulate`) directamente, que es lo que el hook\n * envuelve por dentro.\n *\n * ── MEMORIA NATIVA ────────────────────────────────────────────────────────────\n * Player, contextos, ImageRefs y thumbnails son objetos nativos con `release()`.\n * Se liberan TODOS en `finally`: un bitmap de vídeo sin liberar por fotograma es la\n * forma más rápida de quedarse sin memoria en un móvil. `release()` se envuelve en\n * try/catch porque lanzar sobre un objeto ya liberado provoca un error que taparía\n * el original.\n *\n * ── DEGRADA, NO BLOQUEA ───────────────────────────────────────────────────────\n * `generateThumbnailsAsync` necesita que el asset esté cargado en el player. Si el\n * dispositivo no puede (codec, archivo corrupto, permiso), esto lanza un Error con\n * mensaje en español y la pantalla sigue permitiendo elegir portada desde galería.\n * No poder sacar frames nunca debe impedir publicar.\n */\n\nimport { ImageManipulator, SaveFormat } from 'expo-image-manipulator';\nimport type { ImageManipulatorContext, ImageRef } from 'expo-image-manipulator';\nimport { createVideoPlayer, type VideoPlayer } from 'expo-video';\n\n/**\n * Tope de espera a que el player cargue el asset.\n *\n * Con el perfil largo de la Parte 50 (hasta 50 min / 1,2 GB) la carga puede tardar\n * en un móvil. Se espera, pero NO indefinidamente: sin tope, un vídeo que nunca\n * carga dejaría la hoja colgada en «Extrayendo fotogramas…» para siempre. Al vencer\n * el tope se intenta igualmente y, si falla, se informa con la galería como\n * alternativa — que es la vía que ya existía y siempre funciona.\n */\nconst READY_TIMEOUT_MS = 20_000;\n\n/**\n * Espera a que el player tenga el asset listo para reproducir.\n *\n * `generateThumbnailsAsync` está documentado como «Generates thumbnails from the\n * **currently played** asset», o sea trabaja sobre lo que el player ya cargó.\n * Llamarlo justo tras `createVideoPlayer` —sin esperar— es una carrera: en un vídeo\n * pequeño puede colar, en uno grande falla. Este espera elimina la carrera.\n *\n * También termina si el estado pasa a `error` (codec no admitido, archivo corrupto):\n * esperar ahí sería inútil y dejaría el tope completo de espera.\n */\nasync function esperarListo(player: VideoPlayer): Promise<void> {\n  if (player.status === 'readyToPlay') return;\n  await new Promise<void>((resolve) => {\n    let hecho = false;\n    let sub: { remove: () => void } | null = null;\n    let to: ReturnType<typeof setTimeout> | null = null;\n    const terminar = () => {\n      if (hecho) return;\n      hecho = true;\n      if (sub) { try { sub.remove(); } catch { /* ya quitado */ } }\n      if (to) clearTimeout(to);\n      resolve();\n    };\n    sub = player.addListener('statusChange', ((e: { status: string }) => {\n      if (e.status === 'readyToPlay' || e.status === 'error') terminar();\n    }) as never);\n    to = setTimeout(terminar, READY_TIMEOUT_MS);\n  });\n}\n\n/** Un fotograma ya convertido en archivo subible. */\nexport interface VideoFrame {\n  /** Segundo real del fotograma (en iOS puede diferir del pedido: es `actualTime`). */\n  timeSec: number;\n  /** Segundo que se pidió. */\n  requestedSec: number;\n  /** Archivo en caché — es lo que se sube. */\n  uri: string;\n  /** `data:image/jpeg;base64,…` para la previsualización inmediata. */\n  dataUrl: string;\n  width: number;\n  height: number;\n}\n\n/** Ancho máximo del fotograma. La portada se ve pequeña; 720 px sobra y pesa poco. */\nconst MAX_W = 720;\n/** Compresión JPEG (0–1, siendo 1 sin comprimir). */\nconst COMPRESS = 0.72;\n/** Tope de fotogramas: más no ayuda a elegir y cada uno cuesta memoria nativa. */\nexport const MAX_FRAMES = 12;\n\n/**\n * Tiempos a muestrear, repartidos por el vídeo.\n *\n * Se evita t=0 a propósito: es el fotograma que ya saca el servidor y suele ser el\n * peor (fundido de entrada, negro). Se evita también el último instante (fundido de\n * salida). Por eso se muestrea en el CENTRO de cada tramo: con 6 fotogramas y 60 s,\n * se piden los segundos 5, 15, 25, 35, 45 y 55.\n */\nfunction tiemposDe(durSec: number, count: number): number[] {\n  const dur = Number(durSec);\n  if (!Number.isFinite(dur) || dur <= 0) return [];\n  const n = Math.max(1, Math.min(MAX_FRAMES, Math.floor(count)));\n  const tramo = dur / n;\n  const out: number[] = [];\n  for (let i = 0; i < n; i += 1) {\n    // Centro del tramo, acotado para que no se salga del vídeo.\n    const t = tramo * (i + 0.5);\n    out.push(Math.max(0.1, Math.min(dur - 0.1, t)));\n  }\n  // Sin duplicados (en vídeos muy cortos varios tramos caen en el mismo segundo).\n  return [...new Set(out.map((t) => Math.round(t * 10) / 10))];\n}\n\n/**\n * Extrae hasta `count` fotogramas del vídeo local `uri` y los devuelve como\n * archivos listos para subir.\n *\n * @param uri      ruta local del vídeo (la que dio el picker, aún sin subir).\n * @param durSec   duración en segundos. Con 0/NaN no se puede repartir → lanza.\n * @param count    cuántos fotogramas pedir (tope {@link MAX_FRAMES}).\n */\nexport async function extraerFrames(uri: string, durSec: number, count = 6): Promise<VideoFrame[]> {\n  if (!uri) throw new Error('Falta el vídeo del que sacar la portada.');\n  const tiempos = tiemposDe(durSec, count);\n  if (tiempos.length === 0) {\n    throw new Error('No se pudo leer la duración del vídeo, así que no se pueden ofrecer fotogramas. Elige la portada desde la galería.');\n  }\n\n  // Player SIN vista: `createVideoPlayer` es la vía no-hook y sirve para trabajar\n  // con el asset en segundo plano.\n  let player: ReturnType<typeof createVideoPlayer> | null = null;\n  const liberables: Array<{ release: () => void }> = [];\n  const liberar = (o: unknown) => {\n    const r = o as { release?: () => void } | null;\n    if (r && typeof r.release === 'function') {\n      try { r.release(); } catch { /* ya liberado: no debe tapar el error real */ }\n    }\n  };\n\n  try {\n    player = createVideoPlayer(uri);\n    liberables.push(player as unknown as { release: () => void });\n\n    // Esperar a que el asset esté cargado ANTES de pedir fotogramas: sin esto es\n    // una carrera (ver `esperarListo`). Con un tope, para no colgar la hoja.\n    await esperarListo(player);\n\n    // Pausa defensiva: `generateThumbnailsAsync` trabaja sobre el asset cargado, no\n    // necesita que se reproduzca. Un player sin VideoView normalmente no arranca\n    // solo, pero si lo hiciera, reproduciría en segundo plano — y con vídeos de\n    // hasta 1,2 GB (perfil largo, Parte 50) eso es tarifa de datos y batería. Pausar\n    // es barato y no hace daño si ya estaba pausado.\n    try { if (player.playing) player.pause(); } catch { /* estado en transición */ }\n\n    let thumbs;\n    try {\n      thumbs = await player.generateThumbnailsAsync(tiempos, { maxWidth: MAX_W });\n    } catch {\n      throw new Error('No se pudieron leer los fotogramas de este vídeo (codec o archivo no admitido). Puedes elegir la portada desde la galería.');\n    }\n    if (!thumbs || thumbs.length === 0) {\n      throw new Error('El vídeo no devolvió ningún fotograma. Puedes elegir la portada desde la galería.');\n    }\n\n    const frames: VideoFrame[] = [];\n    for (let i = 0; i < thumbs.length; i += 1) {\n      const th = thumbs[i];\n      liberables.push(th as unknown as { release: () => void });\n\n      // SharedRef<'image'> → archivo. Si un fotograma falla, se salta: con 5 de 6\n      // la función sigue siendo útil, y abortar todo por uno es peor.\n      let ctx: ImageManipulatorContext | null = null;\n      let ref: ImageRef | null = null;\n      try {\n        ctx = ImageManipulator.manipulate(th);\n        liberables.push(ctx);\n        ref = await ctx.renderAsync();\n        liberables.push(ref);\n        const saved = await ref.saveAsync({ base64: true, compress: COMPRESS, format: SaveFormat.JPEG });\n        if (!saved?.uri || !saved.base64) continue;\n        frames.push({\n          // `a