o-modules-core';\nimport { Platform } from 'react-native';\nconst defaultViewName = Platform.OS === 'android' ? 'SurfaceVideoView' : 'VideoView';\nexport default requireNativeViewManager('ExpoVideo', defaultViewName);\nexport const NativeTextureVideoView = Platform.OS === 'android' ? requireNativeViewManager('ExpoVideo', 'TextureVideoView') : null;\n//# sourceMappingURL=NativeVideoView.js.map","import { useReleasingSharedObject } from 'expo-modules-core';\nimport NativeVideoModule from './NativeVideoModule';\nimport resolveAssetSource from './resolveAssetSource';\n// TODO: Temporary solution until we develop a way of overriding prototypes that won't break the lazy loading of the module.\nconst replace = NativeVideoModule.VideoPlayer.prototype.replace;\nNativeVideoModule.VideoPlayer.prototype.replace = function (source, disableWarning = false) {\n    if (!disableWarning) {\n        console.warn('On iOS `VideoPlayer.replace` loads the asset data synchronously on the main thread, which can lead to UI freezes and will be deprecated in a future release. Switch to `replaceAsync` for better user experience.');\n    }\n    return replace.call(this, parseSource(source));\n};\nconst replaceAsync = NativeVideoModule.VideoPlayer.prototype.replaceAsync;\nNativeVideoModule.VideoPlayer.prototype.replaceAsync = function (source) {\n    return replaceAsync.call(this, parseSource(source));\n};\n/**\n * Creates a direct instance of `VideoPlayer` that doesn't release automatically.\n *\n * > **info** For most use cases you should use the [`useVideoPlayer`](#usevideoplayer) hook instead. See the [Using the VideoPlayer Directly](#using-the-videoplayer-directly) section for more details.\n * @param source\n */\nexport function createVideoPlayer(source) {\n    return new NativeVideoModule.VideoPlayer(parseSource(source));\n}\n/**\n * Creates a `VideoPlayer`, which will be automatically cleaned up when the component is unmounted.\n * @param source - A video source that is used to initialize the player.\n * @param setup - A function that allows setting up the player. It will run after the player is created.\n */\nexport function useVideoPlayer(source, setup) {\n    const parsedSource = parseSource(source);\n    return useReleasingSharedObject(() => {\n        const player = new NativeVideoModule.VideoPlayer(parsedSource);\n        setup?.(player);\n        return player;\n    }, [JSON.stringify(parsedSource)]);\n}\nfunction parseSource(source) {\n    if (typeof source === 'number') {\n        // TODO(@kitten): This seems to not handle the `null` case. Is this correct?\n        return { uri: resolveAssetSource(source).uri };\n    }\n    else if (typeof source === 'string') {\n        return { uri: source };\n    }\n    if (typeof source?.assetId === 'number' && !source.uri) {\n        // TODO(@kitten): This seems to not handle the `null` case. Is this correct?\n        return { ...source, uri: resolveAssetSource(source.assetId).uri };\n    }\n    return source;\n}\n//# sourceMappingURL=VideoPlayer.js.map","import resolveAssetSource from 'react-native/Libraries/Image/resolveAssetSource';\nexport default resolveAssetSource;\n//# sourceMappingURL=resolveAssetSource.js.map","import NativeVideoModule from './NativeVideoModule';\nexport default NativeVideoModule.VideoThumbnail;\n//# sourceMappingURL=VideoThumbnail.js.map","export {};\n//# sourceMappingURL=VideoPlayer.types.js.map","﻿/**\n * lifebook-merchant-gestion — LA PARTE DE GESTIÓN DEL MERCADO (tienda de productos).\n *\n * ── PASO 2 DEL ESTÁNDAR (`ESTANDAR-ENTORNOS-DE-CONTROL.md` §5) ────────────────\n * El hotel ya está partido en dos: **HOY** (lo que caduca: gente esperando, dinero por cobrar) y\n * **GESTIÓN** (lo que se configura: catálogo, precios, fotos). El mercado estaba a medias: todo\n * mezclado en `lifebook-merchant`, que enseña a la vez las alertas del día y el catálogo.\n * Esta pantalla es su parte de GESTIÓN, con la MISMA forma que la del hotel, para que las dos se\n * reconozcan. Si cada vertical inventara su estructura, el estándar no serviría de nada.\n *\n * Y lo que la hace útil no es la lista de enlaces —eso ya existía en el panel— sino que **dice lo\n * que falta**, con datos reales del servidor: publicaciones sin aprobar, rechazadas, sin\n * existencias y en borrador. Un dueño que no ve «5 sin existencias» no lo arregla, y esos cinco\n * no se pueden comprar.\n *\n * No hace peticiones nuevas: `dashboard()` ya devuelve todo esto (`products`, `alerts`, `shop`).\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, radios, tipografia, useScreenGuard, useTheme } from '@egrouteplan/ui-kit';\nimport {\n  ArrowLeft, ChevronRight, Package, Settings, ShoppingBag, Store, TriangleAlert,\n} from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { commerceMerchantApi, type LbMerchantDashboard } from '../api/commerce';\nimport { ir as irSeguro } from '../constants/rutas';\n\nexport default function MerchantGestionScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><Contenido /></PanelGate>\n    </AuthGate>\n  );\n}\n\n/** Un pendiente: qué falta, por qué importa y a dónde se va a arreglarlo. */\ninterface Pendiente { clave: string; texto: string; porque: string; ruta: string; }\n\nfunction Contenido() {\n  useScreenGuard();\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  const [dash, setDash] = useState<LbMerchantDashboard | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setCargando(true);\n    try {\n      setDash(await commerceMerchantApi.dashboard());\n      setError(null);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cargar la gestión.');\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  const p = dash?.products;\n  const tienda = dash?.shop;\n\n  /**\n   * Lo que falta, por orden de lo que más cuesta en ventas perdidas.\n   * El orden importa: «sin existencias» es dinero que no se puede cobrar hoy; «en borrador» es\n   * algo que el dueño dejó a medias y quizá ya no quiere.\n   */\n  const pendientes: Pendiente[] = [];\n  if (p) {\n    if (p.outOfStock > 0) {\n      pendientes.push({\n        clave: 'agotado', texto: `${p.outOfStock} publicación(es) sin existencias`,\n        porque: 'No se pueden comprar: reponer o pausar.',\n        ruta: '/lifebook-merchant-products?f=agotado',\n      });\n    }\n    if (p.pending > 0) {\n      pendientes.push({\n        clave: 'revision', texto: `${p.pending} esperando aprobación`,\n        porque: 'La administración tiene que aprobarlas antes de que se vendan.',\n        ruta: '/lifebook-merchant-products?f=pending',\n      });\n    }\n    if (p.rejected > 0) {\n      pendientes.push({\n        clave: 'rechazadas', texto: `${p.rejected} rechazada(s)`,\n        porque: 'Mira el motivo, corrígelas y vuelve a enviarlas.',\n        ruta: '/lifebook-merchant-products?f=rejected',\n      });\n    }\n    if (p.draft > 0) {\n      pendientes.push({\n        clave: 'borradores', texto: `${p.draft} en borrador`,\n        porque: 'Están a medias: no las ve nadie hasta que las envíes a revisión.',\n        // `?f=draft`, no «borrador»: la pantalla compara contra sus valores válidos y, si no\n        // coincide, se queda en «Todos» EN SILENCIO. Un enlace que lleva a la lista entera\n        // parece funcionar y no filtra nada.\n        ruta: '/lifebook-merchant-products?f=draft',\n      });\n    }\n  }\n\n  if (cargando) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.cabecera, { paddingTop: insets.top + 8, borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} accessibilityRole=\"button\" accessibilityLabel=\"Volver\" hitSlop={12} style={styles.volver}>\n          <ArrowLeft size={21} color={colors.textPrimary} />\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>Gestión</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }} numberOfLines={2}>\n            {tienda?.name ?? 'Tu tienda'} · lo que se configura, no lo del día\n          </Text>\n        </View>\n      </View>\n\n      {error ? (\n        <View style={{ padding: espaciado.e16 }}>\n          <Text style={{ color: colors.textSecondary, marginBottom: espaciado.e12 }}>{error}</Text>\n          <GhostButton title=\"Reintentar\" onPress={() => void cargar()} />\n        </View>\n      ) : (\n        <ScrollView\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 30 }}\n          refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => { setRefrescando(true); void cargar(true); }} tintColor={colors.primary} />}\n        >\n          {!tienda ? (\n            <View style={[styles.resumen, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>Todavía no tienes tienda</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e5, lineHeight: 18 }}>\n                Abre tu negocio para publicar productos y recibir pedidos. Aparecerá en el catálogo\n                de Life Book y desde aquí llevarás su gestión.\n              </Text>\n              <View style={{ marginTop: espaciado.e12 }}>\n                <GhostButton title=\"Abrir mi negocio\" onPress={() => irSeguro.libre('/lifebook-sell')} />\n              </View>\n            </View>\n          ) : (\n            <>\n              {/* Resumen del catálogo */}\n              <View style={[styles.resumen, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>\n                  {p?.total ?? 0} publicación(es)\n                </Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4, lineHeight: 18 }}>\n                  {p?.active ?? 0} a la venta\n                  {p && p.hidden > 0 ? ` · ${p.hidden} oculta(s)` : ''}\n                  {p && p.soldOut > 0 ? ` · ${p.soldOut} agotada(s)` : ''}\n                  {dash?.orders ? ` · ${dash.orders.total} pedido(s) en total` : ''}\n                </Text>\n              </View>\n\n              {/* LO QUE FALTA: la razón de ser de esta pantalla */}\n              {pendientes.length ? (\n                <View style={{ marginTop: espaciado.e18 }}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e8 }}>\n                    <TriangleAlert size={16} color={colors.secondary} />\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', marginLeft: espaciado.e7 }}>\n                      Te falta por completar ({pendientes.length})\n                    </Text>\n                  </View>\n                  {pendientes.map((x) => (\n                    <Pressable\n                      key={x.clave}\n                      onPress={() => {\n                  /* La ruta trae su filtro dentro («/…?f=agotado»): el ayudante seguro necesita la ruta y\n                     los parámetros POR SEPARADO. Con el «?» dentro del texto, la navegación se rechaza y\n                     el usuario acaba en «No pudimos abrir esa pantalla» (lo reportó el dueño). */\n                  const [ruta, query] = String(x.ruta ?? '').split('?');\n                  const params: Record<string, string> = {};\n                  for (const par of (query ?? '').split('&')) {\n                    const [k, v] = par.split('=');\n                    if (k) params[k] = decodeURIComponent(v ?? '');\n                  }\n                  irSeguro.libre(ruta, Object.keys(params).length ? params : undefined);\n                }}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={`${x.texto}. ${x.porque}`}\n                      style={[styles.pendiente, { borderColor: alpha(colors.secondary, 0.35), backgroundColor: alpha(colors.secondary, 0.06) }]}\n                    >\n                      <View style={{ flex: 1 }}>\n                        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{x.texto}</Text>\n                        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3, lineHeight: 17 }}>{x.porque}</Text>\n                      </View>\n                      <ChevronRight size={18} color={colors.secondary} />\n                    </Pressable>\n                  ))}\n                </View>\n              ) : (\n                <View style={[styles.resumen, { borderColor: alpha(colors.success, 0.35), backgroundColor: alpha(colors.success, 0.07), marginTop: espaciado.e18 }]}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n                    ✓ Tu catálogo está al día\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>\n                    Sin publicaciones rechazadas, sin borradores a medias y con existencias.\n                  </Text>\n                </View>\n              )}\n            </>\n          )}\n\n          {/* A dónde se va desde aquí */}\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e22, marginBottom: espaciado.e8 }}>\n            Configurar\n          </Text>\n\n          <Fila\n            icono={<Package size={18} color={colors.primary} />}\n            titulo=\"Publicaciones\"\n            detalle={p ? `${p.total} en total · precio, existencias y opciones de cada una` : 'Tu catálogo en Life Book'}\n            onPress={() => irSeguro.libre('/lifebook-merchant-products')}\n          />\n          <Fila\n            icono={<ShoppingBag size={18} color={colors.primary} />}\n            titulo=\"Sin existencias\"\n            detalle={p?.outOfStock ? `${p.outOfStock} publicación(es) que no se pueden comprar ahora` : 'Ninguna agotada ahora mismo'}\n            onPress={() => irSeguro.libre('/lifebook-merchant-products', { f: 'agotado' })}\n          />\n          <Fila\n            icono={<TriangleAlert size={18} color={colors.primary} />}\n            titulo=\"Esperando aprobación\"\n            detalle={p?.pending ? `${p.pending} en revisión por la administración` : 'Nada pendiente de aprobar'}\n            onPress={() => irSeguro.libre('/lifebook-merchant-products?f=pending')}\n          />\n          <Fila\n            icono={<Store size={18} color={colors.primary} />}\n            titulo=\"Ajustes de la tienda\"\n            detalle=\"Nombre, dirección, logo, portada, formas de pago y envío\"\n            onPress={() => irSeguro.libre('/lifebook-merchant-settings')}\n          />\n          <Fila\n            icono={<Settings size={18} color={colors.primary} />}\n            titulo=\"Publicar algo nuevo\"\n            detalle=\"Producto, comida, servicio o alquiler: aparece en Life Book al enviarlo\"\n            onPress={() => irSeguro.libre('/lifebook-sell')}\n          />\n\n          <View style={{ marginTop: espaciado.e22 }}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e8 }}>\n              Lo del día —pedidos nuevos, preparación, cobros y mensajes— está en la otra parte, «Hoy».\n            </Text>\n            <GhostButton title=\"Ir a «Hoy» (pedidos)\" onPress={() => irSeguro.libre('/lifebook-merchant')} />\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\n/** Fila de acceso: icono, título, detalle y flecha. 56 px de objetivo táctil. */\nfunction Fila({ icono, titulo, detalle, onPress }: {\n  icono: React.ReactNode; titulo: string; detalle: string; onPress: () => void;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`${titulo}. ${detalle}`}\n      style={[styles.fila, { borderColor: colors.border, backgroundColor: colors.card }]}\n    >\n      <View style={[styles.filaIcono, { backgroundColor: alpha(colors.primary, 0.12) }]}>{icono}</View>\n      <View style={{ flex: 1 }}>\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{titulo}</Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 17 }}>{detalle}</Text>\n      </View>\n      <ChevronRight size={18} color={colors.textSecondary} />\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e6,\n    paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  volver: { width: 44, height: 44, alignItems: 'center', justifyContent: 'center' },\n  resumen: { borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e13 },\n  pendiente: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    borderWidth: 1, borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e8, minHeight: 56,\n  },\n  fila: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e11,\n    borderWidth: 1, borderRadius: radios.lg, padding: espaciado.e12, marginBottom: espaciado.e8, minHeight: 56,\n  },\n  filaIcono: { width: 34, height: 34, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * app/lifebook-merchant-products.tsx — MIS PUBLICACIONES · PANEL (Parte 39).\n *\n * Lista TODO lo que vende la tienda (cualquier estado) con las acciones que el\n * SERVIDOR acepta desde cada estado:\n *   · «Enviar a revisión» (publish) es la única forma de publicar algo nuevo,\n *     rechazado o en borrador — el vendedor no puede autoaprobarse;\n *   · **Editar precio y existencias** sin salir de aquí: es la edición RÁPIDA\n *     (PATCH /merchant/products/:id/quick) que **no devuelve el producto a\n *     moderación**, para que ajustar el stock o el precio no retire la venta\n *     del catálogo;\n *   · cualquier otro cambio (título, fotos, descripción) va por el asistente\n *     completo, que sí vuelve a pasar por revisión.\n */\nimport React, { useCallback, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, KeyboardAvoidingView, Modal, Platform, Pressable, RefreshControl,\n  ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Eye, Package, Pencil, Plus, Star, Trash2, X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { absUrl } from '../api/config';\nimport { authApi } from '../api/auth';\nimport { tiendaApi } from '../api/lifebookTienda';\nimport {\n  commerceApi, commerceMerchantApi, type LbMyProductCard, type LbProductStatus, type LbStockMode,\n} from '../api/commerce';\nimport { lbServiceIcon, lbServiceLabel, lbStockModeLabel, LB_PRODUCT_ACTIONS, LB_PRODUCT_STATUS, LB_QUICK_EDITABLE, LB_STOCK_MODES, LB_TONE_COLOR } from '../constants/commerce';\nimport { lbXaf } from '../constants/lifebook';\nimport { Chip, ChipRow } from '../components/lifebook/Chip';\nimport { Notice } from '../components/lifebook/publish/PublishParts';\nimport { ir as irSeguro } from '../constants/rutas';\n\ntype Filtro = 'todos' | LbProductStatus | 'agotado';\n\nconst FILTROS: { id: Filtro; label: string }[] = [\n  { id: 'todos', label: 'Todo' },\n  { id: 'active', label: 'Publicado' },\n  { id: 'pending', label: 'En revisión' },\n  { id: 'agotado', label: 'Sin existencias' },\n  { id: 'sold_out', label: 'Agotado' },\n  { id: 'draft', label: 'Borrador' },\n  { id: 'hidden', label: 'Oculto' },\n  { id: 'rejected', label: 'Rechazado' },\n];\n\nconst esAgotado = (p: LbMyProductCard) =>\n  p.status === 'active' && (p.stockMode === 'exact' || p.stockMode === 'approximate') && p.stockQuantity <= 0;\n\nexport default function MerchantProductsScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><ProductsContent /></PanelGate>\n    </AuthGate>\n  );\n}\n\nfunction ProductsContent() {\n  useScreenGuard();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n  const params = useLocalSearchParams<{ f?: string }>();\n\n  const [items, setItems] = useState<LbMyProductCard[] | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [filtro, setFiltro] = useState<Filtro>(\n    FILTROS.some((f) => f.id === params.f) ? (params.f as Filtro) : 'todos',\n  );\n  const [busyId, setBusyId] = useState<string | null>(null);\n  const [editando, setEditando] = useState<LbMyProductCard | null>(null);\n  const [refrescando, setRefrescando] = useState(false);\n\n  const load = useCallback(async (silencioso = false) => {\n    if (!silencioso) setRefrescando(true);\n    try {\n      const { items: lista } = await commerceApi.myProducts();\n      setItems(lista ?? []);\n      setError(null);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudieron cargar tus publicaciones');\n      setItems([]);\n    } finally {\n      setRefrescando(false);\n    }\n  }, []);\n\n  useFocusEffect(useCallback(() => { load(); }, [load]));\n\n  const visibles = useMemo(() => {\n    const lista = items ?? [];\n    if (filtro === 'todos') return lista;\n    if (filtro === 'agotado') return lista.filter(esAgotado);\n    return lista.filter((p) => p.status === filtro);\n  }, [items, filtro]);\n\n  /* ── TANDA A: los DESTACADOS de la tarjeta de mi tienda en el perfil ──────────────\n     Máximo 3 y EN ORDEN (el primero se ve primero). El servidor valida que son míos y\n     activos; aquí solo se elige. Se guarda de una vez, al pulsar «Guardar». */\n  const [destacadosOpen, setDestacadosOpen] = useState(false);\n  const [miId, setMiId] = useState<string | null>(null);\n  const [destacados, setDestacados] = useState<string[]>([]);\n  const [guardandoDest, setGuardandoDest] = useState(false);\n\n  const abrirDestacados = useCallback(async () => {\n    setDestacadosOpen(true);\n    try {\n      const me = await authApi.me();\n      setMiId(me.id);\n      const t = await tiendaApi.tarjeta(me.id);\n      setDestacados((t.featured ?? []).map((f) => f.id));\n    } catch {\n      // Sin tienda (o sin conexión) el selector se queda vacío; guardar avisará.\n      setDestacados([]);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const alternarDestacado = (id: string) => {\n    setDestacados((prev) => {\n      if (prev.includes(id)) return prev.filter((x) => x !== id);\n      if (prev.length >= 3) {\n        Alert.alert('Ya hay 3', 'Quita uno para poder destacar otro.');\n        return prev;\n      }\n      return [...prev, id];\n    });\n  };\n\n  const guardarDestacados = async () => {\n    if (!miId) { Alert.alert('Destacados', 'No se pudo leer tu perfil.'); return; }\n    setGuardandoDest(true);\n    try {\n      const t = await tiendaApi.destacar(destacados);\n      setDestacados((t.featured ?? []).map((f) => f.id));\n      setDestacadosOpen(false);\n      Alert.alert('Destacados guardados',\n        destacados.length\n          ? 'Ya se ven en la tarjeta de tu tienda, en el perfil, en el orden que elegiste.'\n          : 'La tarjeta de tu tienda ya no enseña productos, solo el nombre y la puntuación.');\n    } catch (e) {\n      Alert.alert('Destacados', e instanceof Error ? e.message : 'No se pudieron guardar');\n    } finally { setGuardandoDest(false); }\n  };\n\n  /** Acción de estado: el servidor decide si aplica desde el estado actual. */\n  const cambiarEstado = (p: LbMyProductCard, action: string, label: string) => {\n    Alert.alert(label, `¿${label} «${p.title}»?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: label,\n        onPress: async () => {\n          setBusyId(p.id);\n          try {\n            const { status } = await commerceApi.setProductStatus(p.id, action as never);\n            setItems((prev) => (prev ?? []).map((x) => (x.id === p.id ? { ...x, status, rejectionReason: null } : x)));\n          } catch (e) {\n            Alert.alert('Publicación', e instanceof Error ? e.message : 'No se pudo cambiar el estado');\n          } finally { setBusyId(null); }\n        },\n      },\n    ]);\n  };\n\n  const borrar = (p: LbMyProductCard) => {\n    Alert.alert('Eliminar', `¿Eliminar «${p.title}»? No se puede deshacer.`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Eliminar', style: 'destructive',\n        onPress: async () => {\n          setBusyId(p.id);\n          try {\n            await commerceApi.deleteProduct(p.id);\n            setItems((prev) => (prev ?? []).filter((x) => x.id !== p.id));\n          } catch (e) {\n            Alert.alert('Publicación', e instanceof Error ? e.message : 'No se pudo eliminar');\n          } finally { setBusyId(null); }\n        },\n      },\n    ]);\n  };\n\n  /** Guarda la edición rápida y refleja el resultado sin recargar todo. */\n  const guardarRapido = async (p: LbMyProductCard, precio: string, stockMode: LbStockMode, stock: string) => {\n    setBusyId(p.id);\n    try {\n      const input: { priceXaf?: number | null; stockMode?: LbStockMode; stockQuantity?: number } = { stockMode };\n      if (p.priceMode !== 'on_request' && precio.trim() !== '') input.priceXaf = Number(precio.replace(/\\D/g, ''));\n      if (stockMode === 'exact' || stockMode === 'approximate') input.stockQuantity = Number(stock.replace(/\\D/g, '') || 0);\n      const r = await commerceMerchantApi.quickEdit(p.id, input);\n      setItems((prev) => (prev ?? []).map((x) => (x.id === p.id\n        ? { ...x, priceXaf: r.priceXaf, stockMode: r.stockMode, stockQuantity: r.stockQuantity, status: r.status }\n        : x)));\n      setEditando(null);\n    } catch (e) {\n      Alert.alert('Edición rápida', e instanceof Error ? e.message : 'No se pudo guardar');\n    } finally { setBusyId(null); }\n  };\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10, flex: 1 }}>\n          Mis publicaciones\n        </Text>\n        <Pressable onPress={() => irSeguro.libre('/lifebook-sell')} hitSlop={10} accessibilityLabel=\"Publicar algo nuevo\">\n          <Plus size={21} color={colors.primary} />\n        </Pressable>\n      </View>\n\n      <View style={{ paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10 }}>\n        {/* TANDA A — los 3 DESTACADOS que salen en la tarjeta de mi tienda en el perfil.\n            El comerciante decide qué se ve primero (es su escaparate), así que el selector\n            vive aquí, junto a sus publicaciones, y no escondido en los ajustes. */}\n        <Pressable\n          onPress={() => { void abrirDestacados(); }}\n          accessibilityLabel=\"Elegir los productos destacados de mi perfil\"\n          style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e8 }}\n        >\n          <Star size={16} color={brand.warning} fill={brand.warning} />\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>\n            Destacados en mi perfil\n          </Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n            {destacados.length}/3\n          </Text>\n        </Pressable>\n        <ScrollView horizontal showsHorizontalScrollIndicator={false}>\n          <ChipRow>\n            {FILTROS.map((f) => (\n              <Chip key={f.id} label={f.label} active={filtro === f.id} onPress={() => setFiltro(f.id)} />\n            ))}\n          </ChipRow>\n        </ScrollView>\n      </View>\n\n      {items === null ? (\n        <View style={[styles.center, { flex: 1 }]}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        <ScrollView\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: insets.bottom + 24, flexGrow: 1 }}\n          refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => load()} tintColor={colors.primary} />}\n        >\n          {error ? <Notice tone=\"error\">{error}</Notice> : null}\n\n          {visibles.length === 0 ? (\n            <View style={{ alignItems: 'center', paddingTop: 60, gap: espaciado.e8 }}>\n              <Package size={42} color={alpha(colors.primary, 0.45)} />\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>\n                {filtro === 'todos' ? 'Todavía no vendes nada' : 'Nada en este estado'}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingHorizontal: 40 }}>\n                Publica un producto, comida o servicio: pasa por revisión y, al aprobarse, aparece en el catálogo.\n              </Text>\n              <View style={{ marginTop: espaciado.e8, minWidth: 220 }}>\n                <PrimaryButton title=\"Publicar algo nuevo\" onPress={() => irSeguro.libre('/lifebook-sell')} />\n              </View>\n            </View>\n          ) : (\n            visibles.map((p) => {\n              const meta = LB_PRODUCT_STATUS[p.status];\n              const tone = LB_TONE_COLOR[meta.tone];\n              const acciones = LB_PRODUCT_ACTIONS[p.status] ?? [];\n              const rapida = LB_QUICK_EDITABLE.includes(p.status);\n              return (\n                <View key={p.id} style={[styles.card, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                  <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n                    {p.coverUrl ? (\n                      <Image source={absUrl(p.coverUrl)} style={styles.thumb} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                    ) : (\n                      <View style={[styles.thumb, { backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }]}>\n                        <Package size={18} color={alpha(colors.primary, 0.6)} />\n                      </View>\n                    )}\n                    <View style={{ flex: 1 }}>\n                      <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{p.title}</Text>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                        {lbServiceIcon(p.serviceType)} {lbServiceLabel(p.serviceType)} · {p.variants > 0 ? `${p.variants} opciones · ` : ''}\n                        {p.stockMode === 'exact' || p.stockMode === 'approximate'\n                          ? `${p.stockQuantity} disp.${esAgotado(p) ? ' (agotado)' : ''}`\n                          : lbStockModeLabel(p.stockMode)}\n                      </Text>\n                      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e3 }}>\n                        {p.priceMode === 'on_request' || p.priceXaf === null ? 'A consultar' : lbXaf(p.priceXaf)}\n                      </Text>\n                    </View>\n                    <View style={{ alignItems: 'flex-end', gap: espaciado.e6 }}>\n                      <View style={{ backgroundColor: alpha(tone, 0.13), borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 }}>\n                        <Text style={{ color: tone, fontSize: tipografia.micro, fontWeight: '900' }}>{meta.label}</Text>\n                      </View>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>👁 {p.viewsCount} · ❤ {p.savesCount}</Text>\n                      {/* TANDA H: cuánta gente está esperando que vuelva a haber stock. Es el dato\n                          que dice si merece la pena reponer. Solo sale si hay alguien esperando. */}\n                      {Number(p.waitingCount ?? 0) > 0 ? (\n                        <Text style={{ color: brand.warning, fontSize: tipografia.micro, fontWeight: '900' }}>\n                          🔔 {p.waitingCount} esperan stock\n                        </Text>\n                      ) : null}\n                    </View>\n                  </View>\n\n                  {p.status === 'rejected' && p.rejectionReason ? (\n                    <View style={{ marginTop: espaciado.e8 }}>\n                      <Notice tone=\"error\">{p.rejectionReason}</Notice>\n                    </View>\n                  ) : null}\n                  {meta.hint && p.status !== 'active' ? (\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e6 }}>{meta.hint}</Text>\n                  ) : null}\n\n                  <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e10 }}>\n                    {acciones.map((a) => (\n                      <Chip\n                        key={a.action}\n                        label={a.label}\n                        active={!!a.primary}\n                        disabled={busyId === p.id}\n                        onPress={() => cambiarEstado(p, a.action, a.label)}\n                      />\n                    ))}\n                    {rapida ? (\n                      <Chip label=\"Precio y stock\" icon={<Pencil size={12} color={colors.primary} />} disabled={busyId === p.id} onPress={() => setEditando(p)} />\n                    ) : null}\n                    <Chip label=\"Editar todo\" disabled={busyId === p.id} onPress={() => irSeguro.libre('/lifebook-sell', { editId: p.id })} />\n                    <Chip label=\"Ver ficha\" icon={<Eye size={12} color={colors.textSecondary} />} onPress={() => irSeguro.libre('/lifebook-product/[id]', { id: p.id })} />\n                    <Chip label=\"Eliminar\" icon={<Trash2 size={12} color={colors.danger} />} disabled={busyId === p.id} onPress={() => borrar(p)} />\n                    {busyId === p.id ? <ActivityIndicator size=\"small\" color={colors.primary} /> : null}\n                  </View>\n                </View>\n              );\n            })\n          )}\n        </ScrollView>\n      )}\n\n      {editando ? (\n        <EdicionRapida\n          producto={editando}\n          guardando={busyId === editando.id}\n          onCerrar={() => setEditando(null)}\n          onGuardar={guardarRapido}\n        />\n      ) : null}\n\n      {/* ── TANDA A: elegir los 3 destacados (el orden es el que se ve) ── */}\n      {destacadosOpen ? (\n        <Modal visible transparent animationType=\"slide\" onRequestClose={() => setDestacadosOpen(false)} statusBarTranslucent>\n          <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' }} onPress={() => setDestacadosOpen(false)} />\n          <View style={{ backgroundColor: colors.card, borderTopLeftRadius: radios.lg, borderTopRightRadius: radios.lg, padding: espaciado.e16, paddingBottom: insets.bottom + 16, maxHeight: '82%' }}>\n            <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e4 }}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900', flex: 1 }}>\n                Destacados en mi perfil\n              </Text>\n              <Pressable onPress={() => setDestacadosOpen(false)} hitSlop={10} accessibilityLabel=\"Cerrar\">\n                <X size={20} color={colors.textSecondary} />\n              </Pressable>\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>\n              Hasta 3. El número es el ORDEN en que se verán en la tarjeta de tu tienda (el 1\n              primero). Si no destacas ninguno, la tarjeta solo enseña el nombre y la puntuación.\n            </Text>\n\n            <ScrollView style={{ maxHeight: 420 }} contentContainerStyle={{ gap: espaciado.e8 }}>\n              {(items ?? [])\n                .filter((p) => p.status === 'active')\n                .map((p) => {\n                  const puesto = destacados.indexOf(p.id);\n                  const activo = puesto >= 0;\n                  return (\n                    <Pressable\n                      key={p.id}\n                      onPress={() => alternarDestacado(p.id)}\n                      accessibilityRole=\"checkbox\"\n                      accessibilityState={{ checked: activo }}\n                      accessibilityLabel={`Destacar ${p.title}`}\n                      style={{\n                        flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, padding: espaciado.e8,\n                        borderRadius: radios.md, borderWidth: 1,\n                        borderColor: activo ? colors.primary : alpha(colors.border, 0.6),\n                        backgroundColor: activo ? alpha(colors.primary, 0.08) : colors.surface,\n                      }}\n                    >\n                      <View style={{ width: 44, height: 44, borderRadius: radios.md, overflow: 'hidden', backgroundColor: alpha(colors.primary, 0.08) }}>\n                        {p.coverUrl ? (\n                          <Image source={absUrl(p.coverUrl)} style={{ width: '100%', height: '100%' }} contentFit=\"cover\" transition={0} />\n                        ) : (\n                          <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>\n                            <Package size={18} color={alpha(colors.primary, 0.5)} />\n                          </View>\n                        )}\n                      </View>\n                      <View style={{ flex: 1 }}>\n                        <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{p.title}</Text>\n                        <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                          {p.priceXaf === null ? 'Precio a consultar' : lbXaf(p.priceXaf)}\n                        </Text>\n                      </View>\n                      {activo ? (\n                        <View style={{ width: 26, height: 26, borderRadius: radios.full, backgroundColor: colors.primary, alignItems: 'center', justifyContent: 'center' }}>\n                          <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>{puesto + 1}</Text>\n                        </View>\n                      ) : (\n                        <Text style={{ color: colors.textSecondary, fontSize: tipografia.subtitle, fontWeight: '900' }}>+</Text>\n                      )}\n                    </Pressable>\n                  );\n                })}\n              {(items ?? []).filter((p) => p.status === 'active').length === 0 ? (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingVertical: espaciado.e20 }}>\n                  No tienes publicaciones activas todavía. Cuando las tengas, podrás elegir cuáles\n                  se ven primero en tu perfil.\n                </Text>\n              ) : null}\n            </ScrollView>\n\n            <View style={{ marginTop: espaciado.e12 }}>\n              <PrimaryButton\n                title={guardandoDest ? 'Guardando…' : 'Guardar destacados'}\n                onPress={() => { if (!guardandoDest) void guardarDestacados(); }}\n              />\n            </View>\n          </View>\n        </Modal>\n      ) : null}\n    </View>\n  );\n}\n\n// ───────────────────── edición rápida (precio y existencias) ──────────────────\n\nfunction EdicionRapida({\n  producto, guardando, onCerrar, onGuardar,\n}: {\n  producto: LbMyProductCard;\n  guardando: boolean;\n  onCerrar: () => void;\n  onGuardar: (p: LbMyProductCard, precio: string, stockMode: LbStockMode, stock: string) => void;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [precio, setPrecio] = useState(producto.priceXaf !== null ? String(producto.priceXaf) : '');\n  const [stockMode, setStockMode] = useState<LbStockMode>(producto.stockMode);\n  const [stock, setStock] = useState(String(producto.stockQuantity ?? 0));\n  const conCantidad = stockMode === 'exact' || stockMode === 'approximate';\n\n  return (\n    <Modal transparent animationType=\"fade\" visible onRequestClose={onCerrar}>\n      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.overlay}>\n        <Pressable style={StyleSheet.absoluteFill} onPress={onCerrar} accessibilityLabel=\"Cerrar\" />\n        <View style={[styles.sheet, { backgroundColor: colors.background, borderColor: colors.border, paddingBottom: insets.bottom + 16 }]}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>Precio y existencias</Text>\n          <Text numberOfLines={2} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>{producto.title}</Text>\n\n          <View style={{ marginTop: espaciado.e14 }}>\n            <Notice>\n              Esto es un ajuste del día a día: <Text style={{ fontWeight: '900' }}>no pasa por revisión</Text> y la\n              publicación sigue igual de visible. Para cambiar el título, las fotos o la descripción, usa «Editar todo».\n            </Notice>\n          </View>\n\n          {producto.priceMode !== 'on_request' ? (\n            <>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e6 }}>Precio (XAF)</Text>\n              <TextInput\n                value={precio}\n                onChangeText={(v) => setPrecio(v.replace(/\\D/g, '').slice(0, 9))}\n                keyboardType=\"number-pad\"\n                placeholder=\"0\"\n                placeholderTextColor={colors.textSecondary}\n                style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n              />\n            </>\n          ) : (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Esta publicación es «a consultar»: no lleva precio.</Text>\n          )}\n\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e14, marginBottom: espaciado.e6 }}>Existencias</Text>\n          <ChipRow>\n            {LB_STOCK_MODES.map((m) => (\n              <Chip key={m.id} label={m.label} active={stockMode === m.id} onPress={() => setStockMode(m.id)} />\n            ))}\n          </ChipRow>\n\n          {conCantidad ? (\n            <TextInput\n              value={stock}\n              onChangeText={(v) => setStock(v.replace(/\\D/g, '').slice(0, 6))}\n              keyboardType=\"number-pad\"\n              placeholder=\"0\"\n              placeholderTextColor={colors.textSecondary}\n              style={[styles.input, { marginTop: espaciado.e10, color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n            />\n          ) : null}\n\n          <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e18 }}>\n            <View style={{ flex: 1 }}>\n              <GhostButton title=\"Cancelar\" onPress={onCerrar} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <PrimaryButton\n                title=\"Guardar\"\n                loading={guardando}\n                onPress={() => onGuardar(producto, precio, stockMode, stock)}\n              />\n            </View>\n          </View>\n        </View>\n      </KeyboardAvoidingView>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  card: { borderWidth: StyleSheet.hairlineWidth, borderRadius: radios.lg, padding: espaciado.e12, marginBottom: espaciado.e10 },\n  thumb: { width: 62, height: 62, borderRadius: radios.md },\n  overlay: { flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(0,0,0,0.45)' },\n  sheet: { borderTopWidth: StyleSheet.hairlineWidth, borderTopLeftRadius: radios.lg, borderTopRightRadius: radios.lg, padding: espaciado.e18 },\n  input: {\n    borderWidth: StyleSheet.hairlineWidth, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9,\n    fontSize: tipografia.body, fontWeight: '700',\n  },\n});\n","/**\n * LA TARJETA DE LA TIENDA EN EL PERFIL (tanda A del plan aprobado).\n *\n * Qué resuelve: cuando alguien entra al perfil de una cuenta con tienda, entre la bio y los\n * botones aparece un escaparate rápido con el nombre COMERCIAL de la tienda, su puntuación\n * (solo si tiene reseñas) y hasta 3 productos destacados elegidos a mano por el comerciante,\n * con el precio encima de la foto. Tocar uno NO abre la ficha del producto: abre la tienda\n * posicionada en ese producto (es un atajo, no un destino final).\n *\n * Vive en su propio fichero, como `lifebookGrupos.ts` y `lifebookWatch.ts`, para no tocar\n * `api/lifebook.ts` (que el dueño pidió no tocar) ni `api/commerce.ts`.\n */\nimport { http, httpRequest } from './httpClient';\nimport type { LbPriceMode, LbProductCard } from './commerce';\n\n/** Datos de la tienda para la cabecera de la tarjeta. */\nexport interface LbTiendaDelPerfil {\n  id: string;\n  ownerId: string;\n  /** El nombre COMERCIAL, que no es el nombre del usuario. */\n  name: string;\n  logoUrl: string | null;\n  coverUrl: string | null;\n  description: string | null;\n  city: string | null;\n  isVerified: boolean;\n  rating: number;\n  /**\n   * OJO: es el campo que decide si se enseñan estrellas. Sin reseñas (`ratingCount === 0`)\n   * NO se pinta puntuación — la especificación lo prohíbe expresamente («no pone 0 estrellas\n   * ni un placeholder»). El servidor manda `rating` de todas formas porque una tienda puede\n   * tener media histórica; quien decide es este contador.\n   */\n  ratingCount: number;\n  followersCount: number;\n}\n\n/** Un producto destacado (lo justo para la miniatura con el precio encima). */\nexport interface LbDestacado {\n  id: string;\n  title: string;\n  shortDescription: string | null;\n  /** Igual que en la ficha y el catálogo: `fixed` (precio), `from` (desde) o `on_request`. */\n  priceMode: LbPriceMode;\n  priceXaf: number | null;\n  oldPriceXaf: number | null;\n  currency: string;\n  coverUrl: string | null;\n  salesCount: number;\n  rating: number;\n  ratingCount: number;\n  /** 1, 2 o 3: el orden que eligió el comerciante. */\n  position: number;\n}\n\nexport interface LbTarjetaDeTienda {\n  /** `null` si esa persona no tiene tienda activa: entonces NO hay tarjeta ni hueco. */\n  shop: LbTiendaDelPerfil | null;\n  featured: LbDestacado[];\n}\n\nexport const tiendaApi = {\n  /** La tarjeta completa en UNA petición. Es pública (se mira el perfil de cualquiera). */\n  tarjeta: (userId: string) =>\n    http.get<LbTarjetaDeTienda>(`/lifebook/commerce/users/${userId}/shop-card`),\n\n  /**\n   * Las categorías que ESA tienda usa de verdad, con cuántos productos hay en cada una.\n   * Se piden a la tienda y no a la plataforma: las 193 categorías generales no sirven para\n   * una fila de chips (y un chip que lleva a una rejilla vacía es una trampa).\n   * «Todo» NO viene de aquí: lo pone la pantalla con `total`.\n   */\n  categorias: (shopId: string) =>\n    http.get<{ total: number; categories: { id: string; name: string; icon: string | null; count: number }[] }>(\n      `/lifebook/commerce/shops/${shopId}/categories`,\n    ),\n\n  /** Los productos de la tienda, filtrados por categoría y paginados. */\n  productos: (shopId: string, opts: { categoryId?: string | null; cursor?: string | null; limit?: number } = {}) => {\n    const q: string[] = [`limit=${opts.limit ?? 30}`];\n    if (opts.categoryId) q.push(`categoryId=${opts.categoryId}`);\n    if (opts.cursor) q.push(`cursor=${encodeURIComponent(opts.cursor)}`);\n    return http.get<{ items: LbProductCard[]; nextCursor: string | null; total: number }>(\n      `/lifebook/commerce/shops/${shopId}/products?${q.join('&')}`,\n    );\n  },\n\n  /**\n   * «Colección»: los productos que YO he guardado. Solo tiene sentido en el perfil propio\n   * (en el de otro haría falta decidir si sus guardados son públicos, y eso es una decisión\n   * de privacidad, no de diseño: por eso el tab solo sale en mi perfil).\n   */\n  guardados: () => http.get<{ items: LbProductCard[] }>('/lifebook/commerce/my/saved'),\n\n  /**\n   * Elegir los destacados (solo el dueño; la tienda sale de la sesión, no del cuerpo).\n   * Los ids van EN ORDEN: el primero se ve primero. Máximo 3; lo que no venga, se apaga.\n   */\n  destacar: (productIds: string[]) =>\n    httpRequest<LbTarjetaDeTienda>('/lifebook/commerce/my/shop/featured', {\n      method: 'PUT',\n      body: { productIds },\n    }),\n};\n","/**\n * app/lifebook-merchant-settings.tsx — AJUSTES DE LA TIENDA · PANEL (Parte 39).\n *\n * Edita la ficha pública y la operativa: nombre, descripción, dónde está, cómo\n * cobra y cómo entrega. Todo con `PATCH /lifebook/commerce/my/shop` (la tienda\n * sale del token: aquí no se manda ningún `shopId`).\n *\n * Detalle importante ya resuelto en el servidor: la **política de envío se edita\n * en su sitio**, así que los productos ya publicados **no se quedan sin\n * entrega** al guardar (antes se borraba y se volvía a crear, y el producto\n * perdía su política por `ON DELETE SET NULL`).\n */\nimport React, { useCallback, useMemo, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, FormField, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Store } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { absUrl } from '../api/config';\nimport { commerceApi, type LbPayMethod, type LbShop } from '../api/commerce';\nimport { Chip, ChipRow } from '../components/lifebook/Chip';\nimport { Notice, StepBlock } from '../components/lifebook/publish/PublishParts';\nimport { LB_CITIES } from '../constants/lifebook';\nimport { LB_COST_MODES, LB_COVERAGE, LB_PAY_METHODS, LB_REGIONS, LB_TRANSPORT, LB_VERIFICATION } from '../constants/commerce';\nimport { ir as irSeguro } from '../constants/rutas';\n\ntype Region = 'insular' | 'continental' | 'other';\ntype CostMode = 'fixed' | 'calculated' | 'on_request';\n\nexport default function MerchantSettingsScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><SettingsContent /></PanelGate>\n    </AuthGate>\n  );\n}\n\nfunction SettingsContent() {\n  useScreenGuard();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const [shop, setShop] = useState<LbShop | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const [guardando, setGuardando] = useState(false);\n  const [guardado, setGuardado] = useState(false);\n  const [refrescando, setRefrescando] = useState(false);\n\n  // Campos editables\n  const [name, setName] = useState('');\n  const [description, setDescription] = useState('');\n  const [city, setCity] = useState('Malabo');\n  const [barrio, setBarrio] = useState('');\n  const [region, setRegion] = useState<Region>('insular');\n  const [referencia, setReferencia] = useState('');\n  const [logoUrl, setLogoUrl] = useState('');\n  const [coverUrl, setCoverUrl] = useState('');\n  const [pays, setPays] = useState<LbPayMethod[]>([]);\n  // Envío\n  const [envioNombre, setEnvioNombre] = useState('Mismo día');\n  const [cobertura, setCobertura] = useState<string[]>(['same_city']);\n  const [transportes, setTransportes] = useState<string[]>(['local_courier', 'taxi_moto', 'pickup']);\n  const [tiempo, setTiempo] = useState('2-4 h');\n  const [costMode, setCostMode] = useState<CostMode>('fixed');\n  const [coste, setCoste] = useState('');\n  const [porKm, setPorKm] = useState('');\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setRefrescando(true);\n    try {\n      const { shop: s } = await commerceApi.myShop();\n      setShop(s);\n      if (s) {\n        setName(s.name);\n        setDescription(s.description ?? '');\n        setCity(s.city ?? 'Malabo');\n        setBarrio(s.barrio ?? '');\n        setRegion((s.region as Region) ?? 'insular');\n        setReferencia(s.addressReference ?? '');\n        setLogoUrl(s.logoUrl ?? '');\n        setCoverUrl(s.coverUrl ?? '');\n        setPays(s.paymentMethods.map((m) => m.method));\n        const p = s.shippingPolicies[0];\n        if (p) {\n          setEnvioNombre(p.name);\n          setCobertura(p.coverage ?? []);\n          setTransportes(p.transportModes ?? []);\n          setTiempo(p.estimatedTime ?? '');\n          setCostMode(p.costMode);\n          setCoste(p.baseCostXaf ? String(p.baseCostXaf) : '');\n          setPorKm(p.perKmXaf ? String(p.perKmXaf) : '');\n        }\n      }\n    } catch (e) {\n      Alert.alert('Tienda', e instanceof Error ? e.message : 'No se pudo cargar la tienda');\n    } finally {\n      setCargando(false);\n      setRefrescando(false);\n    }\n  }, []);\n\n  useFocusEffect(useCallback(() => { cargar(); }, [cargar]));\n\n  const alternar = (lista: string[], set: (v: string[]) => void, id: string) => {\n    set(lista.includes(id) ? lista.filter((x) => x !== id) : [...lista, id]);\n  };\n\n  const guardar = async () => {\n    if (name.trim().length < 2) {\n      Alert.alert('Tienda', 'El nombre necesita al menos 2 letras');\n      return;\n    }\n    if (pays.length === 0) {\n      Alert.alert('Pagos', 'Deja al menos una forma de cobro: si no, nadie podrá pagarte.');\n      return;\n    }\n    setGuardando(true);\n    setGuardado(false);\n    try {\n      const { shop: s } = await commerceApi.updateShop({\n        name: name.trim(),\n        description: description.trim() || undefined,\n        city: city.trim() || undefined,\n        barrio: barrio.trim() || undefined,\n        region,\n        addressReference: referencia.trim() || undefined,\n        logoUrl: logoUrl.trim() || null,\n        coverUrl: coverUrl.trim() || null,\n        paymentMethods: pays,\n        shippingPolicy: {\n          name: envioNombre.trim() || 'Entrega',\n          coverage: cobertura,\n          transportModes: transportes,\n          estimatedTime: tiempo.trim() || undefined,\n          costMode,\n          baseCostXaf: Number(coste.replace(/\\D/g, '')) || 0,\n          ...(costMode === 'calculated' ? { perKmXaf: Number(porKm.replace(/\\D/g, '')) || 0 } : {}),\n        },\n      });\n      setShop(s);\n      setGuardado(true);\n    } catch (e) {\n      Alert.alert('Tienda', e instanceof Error ? e.message : 'No se pudo guardar');\n    } finally {\n      setGuardando(false);\n    }\n  };\n\n  const pagosOrdenados = useMemo(() => LB_PAY_METHODS, []);\n\n  if (cargando) {\n    return (\n      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.background }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  if (!shop) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background }}>\n        <Cabecera onBack={() => router.back()} colors={colors} insets={insets} />\n        <View style={{ alignItems: 'center', paddingTop: 70, gap: espaciado.e10 }}>\n          <Store size={42} color={alpha(colors.primary, 0.45)} />\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>Todavía no tienes tienda</Text>\n          <View style={{ minWidth: 220, marginTop: espaciado.e8 }}>\n            <PrimaryButton title=\"Abrir mi tienda\" onPress={() => irSeguro.libre('/lifebook-sell', undefined, true)} />\n          </View>\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <Cabecera onBack={() => router.back()} colors={colors} insets={insets} />\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 26 }}\n        refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => cargar()} tintColor={colors.primary} />}\n      >\n        {guardado ? <Notice tone=\"ok\">Cambios guardados. Los productos ya publicados mantienen su entrega y su estado.</Notice> : null}\n\n        {/* Vista previa de la cabecera pública */}\n        <View style={[styles.preview, { borderColor: colors.border }]}>\n          {coverUrl ? (\n            <Image source={absUrl(coverUrl)} style={styles.cover} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n          ) : (\n            <View style={[styles.cover, { backgroundColor: alpha(colors.primary, 0.12) }]} />\n          )}\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, marginTop: -22, paddingHorizontal: espaciado.e12 }}>\n            {logoUrl ? (\n              <Image source={absUrl(logoUrl)} style={[styles.logo, { borderColor: colors.background }]} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n            ) : (\n              <View style={[styles.logo, { borderColor: colors.background, backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center' }]}>\n                <Store size={20} color={colors.primary} />\n              </View>\n            )}\n            <View style={{ flex: 1 }}>\n              <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>{name || 'Mi tienda'}</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                {LB_VERIFICATION[shop.verificationLevel]?.icon} {LB_VERIFICATION[shop.verificationLevel]?.label}\n                {' · '}{shop.activeProducts ?? 0} publicados\n              </Text>\n            </View>\n          </View>\n        </View>\n\n        <StepBlock title=\"Nombre de la tienda *\">\n          <FormField label=\"\" value={name} onChangeText={setName} maxLength={80} placeholder=\"Ej.: Moda Paraíso\" />\n        </StepBlock>\n\n        <StepBlock title=\"¿Qué vendes o qué servicio das?\" hint=\"Aparece en tu ficha pública. Sin teléfonos ni enlaces.\">\n          <FormField label=\"\" value={description} onChangeText={setDescription} maxLength={600} multiline placeholder=\"Ej.: ropa, teléfonos y arreglos de fontanería\" />\n        </StepBlock>\n\n        <StepBlock title=\"Ciudad\">\n          <ChipRow>\n            {LB_CITIES.slice(0, 6).map((c) => (\n              <Chip key={c} label={c} active={city === c} onPress={() => setCity(c)} compact />\n            ))}\n          </ChipRow>\n          <View style={{ marginTop: espaciado.e8 }}>\n            <FormField label=\"\" value={city} onChangeText={setCity} maxLength={60} placeholder=\"Otra ciudad\" />\n          </View>\n        </StepBlock>\n\n        <StepBlock title=\"Barrio o zona\">\n          <FormField label=\"\" value={barrio} onChangeText={setBarrio} maxLength={60} placeholder=\"Ej.: Paraíso\" />\n        </StepBlock>\n\n        <StepBlock title=\"Región\">\n          <ChipRow>\n            {LB_REGIONS.map((r) => (\n              <Chip key={r.id} label={r.label} active={region === r.id} onPress={() => setRegion(r.id)} compact />\n            ))}\n          </ChipRow>\n        </StepBlock>\n\n        <StepBlock title=\"Referencia para llegar\" hint=\"Lo que dirías a un repartidor: «frente a la farmacia, portón verde».\">\n          <FormField label=\"\" value={referencia} onChangeText={setReferencia} maxLength={200} placeholder=\"Detrás del mercado central\" />\n        </StepBlock>\n\n        <StepBlock title=\"Logotipo y portada\" hint=\"Se pega la dirección de la imagen (la misma que usas en tus publicaciones).\">\n          <FormField label=\"\" value={logoUrl} onChangeText={setLogoUrl} autoCapitalize=\"none\" placeholder=\"https://…/logo.jpg\" />\n          <View style={{ height: 8 }} />\n          <FormField label=\"\" value={coverUrl} onChangeText={setCoverUrl} autoCapitalize=\"none\" placeholder=\"https://…/portada.jpg\" />\n        </StepBlock>\n\n        <StepBlock title=\"Formas de cobro *\" hint=\"Solo se muestra al comprador lo que marques aquí. El estado de cada método lo pone la plataforma.\">\n          <ChipRow>\n            {pagosOrdenados.map((m) => (\n              <Chip\n                key={m.id}\n                label={m.label}\n                active={pays.includes(m.id)}\n                onPress={() => alternar(pays as unknown as string[], (v) => setPays(v as LbPayMethod[]), m.id)}\n                compact\n              />\n            ))}\n          </ChipRow>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e8 }}>\n            Contra entrega es la única que cobra con código de 4 dígitos al recibir.\n          </Text>\n        </StepBlock>\n\n        <StepBlock title=\"Entrega\" hint=\"Se edita en su sitio: los productos ya publicados no se quedan sin entrega.\">\n          <FormField label=\"Nombre de la tarifa\" value={envioNombre} onChangeText={setEnvioNombre} maxLength={60} placeholder=\"Mismo día\" />\n\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, marginBottom: espaciado.e6 }}>Cobertura</Text>\n          <ChipRow>\n            {LB_COVERAGE.map((c) => (\n              <Chip key={c.id} label={c.label} active={cobertura.includes(c.id)} onPress={() => alternar(cobertura, setCobertura, c.id)} compact />\n            ))}\n          </ChipRow>\n\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, marginBottom: espaciado.e6 }}>Cómo se transporta</Text>\n          <ChipRow>\n            {LB_TRANSPORT.map((t) => (\n              <Chip key={t.id} label={t.label} active={transportes.includes(t.id)} onPress={() => alternar(transportes, setTransportes, t.id)} compact />\n            ))}\n          </ChipRow>\n\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12, marginBottom: espaciado.e6 }}>Coste de la entrega</Text>\n          <ChipRow>\n            {LB_COST_MODES.map((m) => (\n              <Chip key={m.id} label={m.label} active={costMode === m.id} onPress={() => setCostMode(m.id)} compact />\n            ))}\n          </ChipRow>\n\n          <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e10 }}>\n            <View style={{ flex: 1 }}>\n              <FormField label=\"Coste base (XAF)\" value={coste} onChangeText={(v) => setCoste(v.replace(/\\D/g, ''))} keyboardType=\"number-pad\" placeholder=\"1500\" />\n            </View>\n            {costMode === 'calculated' ? (\n              <View style={{ flex: 1 }}>\n                <FormField label=\"Por km (XAF)\" value={porKm} onChangeText={(v) => setPorKm(v.replace(/\\D/g, ''))} keyboardType=\"number-pad\" placeholder=\"300\" />\n              </View>\n            ) : null}\n          </View>\n\n          <View style={{ marginTop: espaciado.e10 }}>\n            <FormField label=\"Tiempo estimado\" value={tiempo} onChangeText={setTiempo} maxLength={40} placeholder=\"2-4 h\" />\n          </View>\n        </StepBlock>\n\n        <PrimaryButton title=\"Guardar cambios\" loading={guardando} onPress={guardar} />\n\n        <Pressable\n          onPress={() => irSeguro.libre('/lifebook-merchant-products')}\n          style={{ marginTop: espaciado.e18, alignItems: 'center' }}\n        >\n          <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Ir a mis publicaciones →</Text>\n        </Pressable>\n      </ScrollView>\n    </View>\n  );\n}\n\nfunction Cabecera({ onBack, colors, insets }: { onBack: () => void; colors: any; insets: { top: number } }) {\n  return (\n    <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n      <Pressable onPress={onBack} hitSlop={10} accessibilityLabel=\"Volver\">\n        <ArrowLeft size={20} color={colors.textPrimary} />\n      </Pressable>\n      <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10, flex: 1 }}>\n        Ajustes de la tienda\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  preview: { borderWidth: StyleSheet.hairlineWidth, borderRadius: radios.lg, overflow: 'hidden', marginBottom: espaciado.e18 },\n  cover: { width: '100%', height: 96 },\n  logo: { width: 52, height: 52, borderRadius: radios.lg, borderWidth: 3 },\n});\n","/**\n * app/lifebook-merchant.tsx — MI TIENDA · PANEL DEL COMERCIANTE (Parte 39).\n *\n * Resumen real del negocio, calculado en el SERVICIO (no en la app):\n *   · el «hoy» es el de **Malabo**, no UTC;\n *   · «Cobrado hoy» es dinero **entregado y cobrado**; lo que está pendiente de\n *     contra entrega se muestra aparte («Por cobrar»), para no confundir\n *     facturación con caja;\n *   · la tienda sale del **token**: esta pantalla no manda ningún `shopId`.\n *\n * Se refresca sola cada 20 s mientras está en pantalla (no hay push todavía) y\n * al volver a ella. Las secciones que aún no existen (opiniones, cobros en\n * línea) se anuncian como «próximamente» en vez de inventar datos.\n */\nimport React, { useCallback, useRef, useState } from 'react';\nimport { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useScreenGuard } from '@egrouteplan/ui-kit';\nimport {\n  ArrowLeft, BarChart3, BedDouble, Bookmark, ChevronRight, MessageCircle, Package, Settings,\n  ShoppingBag, Star, Store, TriangleAlert,\n} from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { PanelGate } from '../core/PanelGate';\nimport { absUrl } from '../api/config';\nimport { commerceMerchantApi, type LbMerchantDashboard } from '../api/commerce';\nimport { hotelApi } from '../api/hotel';\nimport { lbXaf } from '../constants/lifebook';\nimport { LB_VERIFICATION } from '../constants/commerce';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport default function MerchantScreen() {\n  return (\n    <AuthGate>\n      <PanelGate><MerchantContent /></PanelGate>\n    </AuthGate>\n  );\n}\n\n/** Cada cuánto se refresca el resumen mientras la pantalla está visible. */\nconst REFRESCO_MS = 20_000;\n\nfunction MerchantContent() {\n  useScreenGuard();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const [data, setData] = useState<LbMerchantDashboard | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [refrescando, setRefrescando] = useState(false);\n  const vivo = useRef(true);\n\n  /**\n   * ¿Esta tienda es un ALOJAMIENTO?\n   *\n   * El resumen del comerciante no lo dice, así que se pregunta al módulo de hotel (una\n   * petición más, y solo para decidir si se enseña el acceso). Es el puente que faltaba:\n   * el hotelero tiene su recepción, sus habitaciones y su calendario en OTRO panel, y hasta\n   * ahora la única forma de llegar era el botón «Mi hotel» del buscador — dentro de «Mi\n   * tienda» no había ninguna pista. Si el módulo responde con error, la pantalla sigue\n   * funcionando sin el acceso.\n   */\n  const [hotel, setHotel] = useState<{ isHotel: boolean; rooms: number; publicadas: number } | null>(null);\n\n  const load = useCallback(async (silencioso = false) => {\n    if (!silencioso) setRefrescando(true);\n    try {\n      const res = await commerceMerchantApi.dashboard();\n      if (vivo.current) { setData(res); setError(null); }\n    } catch (e) {\n      if (vivo.current) setError(e instanceof Error ? e.message : 'No se pudo cargar el resumen');\n    } finally {\n      if (vivo.current) setRefrescando(false);\n    }\n    try {\n      const h = await hotelApi.myHotel();\n      if (vivo.current) {\n        const rooms = h.rooms ?? [];\n        setHotel({\n          isHotel: h.hotel?.isHotel === true,\n          rooms: rooms.length,\n          publicadas: rooms.filter((r) => r.isActive && r.productStatus === 'active').length,\n        });\n      }\n    } catch {\n      if (vivo.current) setHotel(null);\n    }\n  }, []);\n\n  // Refresco al volver a la pantalla + sondeo suave (interino hasta que haya push).\n  useFocusEffect(useCallback(() => {\n    vivo.current = true;\n    load();\n    const t = setInterval(() => load(true), REFRESCO_MS);\n    return () => { vivo.current = false; clearInterval(t); };\n  }, [load]));\n\n  /** NAVEGACIÓN SEGURA: las rutas de este panel vienen de una lista, así que se validan antes\n   *  de ir. Antes navegaba a ciegas (`irSeguro.libre(String(ruta ?? ''))`): si la ruta llegaba vacía o\n   *  mal escrita, la pulsación no hacía NADA y el usuario lo veía como un botón roto. */\n  // Con parámetros: el filtro va APARTE de la ruta ({ f: 'pending' }), nunca dentro del texto ('…?f=pending'),\n  // porque el ayudante seguro rechaza la ruta con «?» dentro y el botón acaba en «No pudimos abrir esa pantalla».\n  const ir = (ruta: string, params?: Record<string, unknown>) => irSeguro.libre(ruta, params);\n\n  if (!data && !error) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  const shop = data?.shop ?? null;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10, flex: 1 }}>\n          Mi tienda\n        </Text>\n        {shop ? (\n          <Pressable onPress={() => ir('/lifebook-merchant-settings')} hitSlop={10} accessibilityLabel=\"Ajustes de la tienda\">\n            <Settings size={19} color={colors.textPrimary} />\n          </Pressable>\n        ) : null}\n      </View>\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + 28 }}\n        refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => load()} tintColor={colors.primary} />}\n      >\n        {error ? (\n          <View style={[styles.card, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.06), marginBottom: espaciado.e14 }]}>\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption }}>{error}</Text>\n          </View>\n        ) : null}\n\n        {/*\n          EL PUENTE AL PANEL DEL HOTEL.\n          Un alojamiento tiene DOS paneles: este (escaparate, publicaciones y pedidos) y el\n          del hotel (recepción, reservas, habitaciones, precios). Son cosas distintas y el\n          hotelero tiene que poder llegar a los dos desde donde está. Antes solo se llegaba\n          por el botón «Mi hotel» del buscador de hotel.\n        */}\n        {/*\n          ── UNA SOLA PUERTA A LA OTRA PARTE ──\n          El panel del comerciante son DOS partes (decisión del dueño, 2026-09-12): **Hoy**\n          (esta: lo que caduca — pedidos por atender, cobros y mensajes) y **Gestión**\n          (publicaciones, existencias, precios y ajustes). Mezclarlas hace que lo urgente se\n          pierda entre lo que puede esperar, así que aquí no hay atajos sueltos: hay UNA puerta\n          clara. Es la misma forma que el panel del hotel, para que las dos se reconozcan.\n        */}\n        {shop ? (\n          <Pressable\n            onPress={() => ir('/lifebook-merchant-gestion')}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Gestión: publicaciones, existencias y ajustes de la tienda\"\n            style={[styles.card, {\n              flexDirection: 'row', alignItems: 'center', gap: espaciado.e11,\n              borderColor: colors.border, backgroundColor: colors.card, marginBottom: espaciado.e14, minHeight: 56,\n            }]}\n          >\n            <View style={[styles.iconoSeccion, { backgroundColor: alpha(colors.primary, 0.12) }]}>\n              <Settings size={17} color={colors.primary} />\n            </View>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>Gestión</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                Publicaciones, existencias, precios y ajustes de la tienda\n              </Text>\n            </View>\n            <ChevronRight size={18} color={colors.textSecondary} />\n          </Pressable>\n        ) : null}\n\n        {shop && hotel?.isHotel ? (\n          <View style={[styles.card, { borderColor: alpha(colors.primary, 0.35), backgroundColor: alpha(colors.primary, 0.06), marginBottom: espaciado.e14 }]}>\n            {/*\n              Las DOS PARTES del panel del comerciante (decisión del dueño, 2026-09-12).\n              No son dos apps: es el mismo trabajo con dos naturalezas distintas, y mezclarlas\n              hace que lo urgente se pierda entre lo que puede esperar.\n                · HOY      → lo que caduca: gente esperando y dinero por cobrar.\n                · GESTIÓN  → lo que se configura: precios, fotos, textos, catálogo.\n              Aquí, en la puerta, se ofrecen las dos por igual para que el hotelero sepa que\n              existen y no tenga que adivinar dónde está cada cosa.\n            */}\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e9 }}>\n              <View style={[styles.iconoSeccion, { backgroundColor: alpha(colors.primary, 0.16) }]}>\n                <BedDouble size={17} color={colors.primary} />\n              </View>\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', flex: 1 }}>\n                Tu alojamiento\n              </Text>\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e7, lineHeight: 18 }}>\n              {hotel.rooms\n                ? `${hotel.rooms} tipo(s) de habitación · ${hotel.publicadas} se puede(n) reservar ya`\n                : 'Todavía no has creado ninguna habitación'}\n            </Text>\n\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12 }}>\n              <View style={{ flex: 1 }}>\n                <PrimaryButton title=\"Hoy\" onPress={() => ir('/lifebook-hotel-panel')} />\n              </View>\n              <View style={{ flex: 1 }}>\n                <GhostButton title=\"Gestión\" onPress={() => ir('/lifebook-hotel-gestion')} />\n              </View>\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8, lineHeight: 16 }}>\n              «Hoy»: llegadas, salidas, cobros y reservas. «Gestión»: ficha, habitaciones y precios.\n            </Text>\n          </View>\n        ) : null}\n\n        {/* Sin tienda: el panel no existe todavía, se ofrece abrirla. */}\n        {!shop ? (\n          <View style={{ alignItems: 'center', paddingTop: 60, gap: espaciado.e10 }}>\n            <Store size={44} color={alpha(colors.primary, 0.45)} />\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>Todavía no tienes tienda</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingHorizontal: espaciado.e30 }}>\n              Abre tu tienda para vender productos, comida o servicios y gestionar tus pedidos desde aquí.\n            </Text>\n            <View style={{ marginTop: espaciado.e8, minWidth: 220 }}>\n              <PrimaryButton title=\"Abrir mi tienda\" onPress={() => ir('/lifebook-sell')} />\n            </View>\n          </View>\n        ) : (\n          <>\n            {/* ── Ficha de la tienda ── */}\n            <View style={[styles.card, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }}>\n                {shop.logoUrl ? (\n                  <Image source={absUrl(shop.logoUrl)} style={styles.logo} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                ) : (\n                  <View style={[styles.logo, { backgroundColor: alpha(colors.primary, 0.12), alignItems: 'center', justifyContent: 'center' }]}>\n                    <Store size={22} color={colors.primary} />\n                  </View>\n                )}\n                <View style={{ flex: 1 }}>\n                  <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900' }}>{shop.name}</Text>\n                  <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                    {LB_VERIFICATION[shop.verificationLevel]?.icon} {LB_VERIFICATION[shop.verificationLevel]?.label}\n                    {shop.city ? ` · ${shop.city}${shop.barrio ? ` (${shop.barrio})` : ''}` : ''}\n                  </Text>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, marginTop: espaciado.e4 }}>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3 }}>\n                      <Star size={12} color={brand.secondary} />\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                        {shop.ratingCount > 0 ? `${shop.rating.toFixed(1)} (${shop.ratingCount})` : 'Sin valoraciones'}\n                      </Text>\n                    </View>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3 }}>\n                      <Bookmark size={12} color={colors.textSecondary} />\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{shop.followersCount} seguidores</Text>\n                    </View>\n                  </View>\n                </View>\n                {!shop.isActive ? (\n                  <View style={{ backgroundColor: alpha(colors.danger, 0.12), borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 }}>\n                    <Text style={{ color: colors.danger, fontSize: tipografia.micro, fontWeight: '900' }}>PAUSADA</Text>\n                  </View>\n                ) : null}\n              </View>\n              <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n                <View style={{ flex: 1 }}>\n                  <GhostButton title=\"Ver como cliente\" onPress={() => ir(`/lifebook-shop/${shop.id}`)} />\n                </View>\n                <View style={{ flex: 1 }}>\n                  <GhostButton title=\"Ajustes\" onPress={() => ir('/lifebook-merchant-settings')} />\n                </View>\n              </View>\n            </View>\n\n            {/* ── Avisos: solo lo que requiere una acción hoy ── */}\n            {data?.alerts ? (\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginBottom: espaciado.e6 }}>\n                {data.alerts.newOrders > 0 ? (\n                  <Aviso icon={<ShoppingBag size={13} color={brand.white} />} color={colors.primary}\n                    texto={`${data.alerts.newOrders} pedido${data.alerts.newOrders === 1 ? '' : 's'} nuevo${data.alerts.newOrders === 1 ? '' : 's'}`}\n                    onPress={() => ir('/lifebook-orders', { side: 'seller' })} />\n                ) : null}\n                {data.alerts.pendingProducts > 0 ? (\n                  <Aviso icon={<Package size={13} color={brand.white} />} color={brand.secondary}\n                    texto={`${data.alerts.pendingProducts} en revisión`}\n                    onPress={() => ir('/lifebook-merchant-products', { f: 'pending' })} />\n                ) : null}\n                {data.alerts.outOfStock > 0 ? (\n                  <Aviso icon={<TriangleAlert size={13} color={brand.white} />} color={brand.danger}\n                    texto={`${data.alerts.outOfStock} sin existencias`}\n                    onPress={() => ir('/lifebook-merchant-products', { f: 'agotado' })} />\n                ) : null}\n                {data.alerts.unreadMessages > 0 ? (\n                  <Aviso icon={<MessageCircle size={13} color={brand.white} />} color={brand.success}\n                    texto={`${data.alerts.unreadMessages} sin leer`}\n                    onPress={() => ir('/lifebook-messages')} />\n                ) : null}\n              </View>\n            ) : null}\n\n            {/* ── Caja del día (hora de Malabo) ── */}\n            <Seccion titulo=\"Caja\" icono={<BarChart3 size={15} color={colors.textPrimary} />}>\n              <View style={[styles.card, { borderColor: colors.border }]}>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Cobrado hoy</Text>\n                <Text style={{ color: colors.success, fontSize: tipografia.display, fontWeight: '900', marginTop: espaciado.e2 }}>\n                  {lbXaf(data?.money?.paidTodayXaf ?? 0)}\n                </Text>\n                <View style={{ flexDirection: 'row', gap: espaciado.e16, marginTop: espaciado.e12 }}>\n                  <Mini label=\"Este mes\" valor={lbXaf(data?.money?.paidMonthXaf ?? 0)} />\n                  <Mini label=\"Por cobrar\" valor={lbXaf(data?.money?.pendingCodXaf ?? 0)} />\n                </View>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e10, lineHeight: 15 }}>\n                  Solo cuenta lo entregado y cobrado. «Por cobrar» es lo pendiente de contra entrega.\n                  Día del servidor: {data?.serverDay ?? '—'} (hora de Malabo{data?.serverTime ? `, ${data.serverTime}` : ''}).\n                </Text>\n              </View>\n            </Seccion>\n\n            {/* ── Pedidos ── */}\n            <Seccion titulo=\"Pedidos\" icono={<ShoppingBag size={15} color={colors.textPrimary} />}>\n              <View style={[styles.card, { borderColor: colors.border }]}>\n                <View style={styles.fila}>\n                  <Mini label=\"Hoy\" valor={String(data?.orders?.today ?? 0)} />\n                  <Mini label=\"En curso\" valor={String(data?.orders?.active ?? 0)} />\n                  <Mini label=\"Entregados\" valor={String(data?.orders?.delivered ?? 0)} />\n                  <Mini label=\"Cancelados\" valor={String(data?.orders?.cancelled ?? 0)} />\n                </View>\n                <View style={{ marginTop: espaciado.e12 }}>\n                  <GhostButton title=\"Ver pedidos de la tienda\" onPress={() => ir('/lifebook-orders', { side: 'seller' })} />\n                </View>\n                {/*\n                  EL DINERO DE MI TIENDA (decisión del dueño, 18/09/2026): «sin esto el vendedor no sabe\n                  si gana dinero dentro de la app». Lo que ha vendido, la comisión, lo que le queda por\n                  cobrar y lo que espera a que venza la ventana de reclamación.\n                */}\n                <View style={{ marginTop: espaciado.e10 }}>\n                  <PrimaryButton title=\"El dinero de mi tienda\" onPress={() => ir('/lifebook-dinero')} />\n                </View>\n              </View>\n            </Seccion>\n\n            {/* ── Catálogo ── */}\n            <Seccion titulo=\"Catálogo\" icono={<Package size={15} color={colors.textPrimary} />}>\n              <View style={[styles.card, { borderColor: colors.border }]}>\n                <View style={styles.fila}>\n                  <Mini label=\"Publicados\" valor={String(data?.products?.active ?? 0)} />\n                  <Mini label=\"En revisión\" valor={String(data?.products?.pending ?? 0)} />\n                  <Mini label=\"Agotados\" valor={String(data?.products?.soldOut ?? 0)} />\n                  <Mini label=\"Borradores\" valor={String(data?.products?.draft ?? 0)} />\n                </View>\n                <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n                  <View style={{ flex: 1 }}>\n                    <GhostButton title=\"Gestionar\" onPress={() => ir('/lifebook-merchant-products')} />\n                  </View>\n                  <View style={{ flex: 1 }}>\n                    <PrimaryButton title=\"Publicar\" onPress={() => ir('/lifebook-sell')} />\n                  </View>\n                </View>\n              </View>\n            </Seccion>\n\n            {/* ── Lo que aún no existe (dicho claro) ── */}\n            <Seccion titulo=\"Próximamente\" icono={<Star size={15} color={colors.textPrimary} />}>\n              <View style={[styles.card, { borderColor: colors.border }]}>\n                <Futuro titulo=\"Opiniones de clientes\" detalle=\"Cuando un pedido se entrega se podrá valorar la tienda y el producto.\" />\n                <Futuro titulo=\"Cobros en línea\" detalle=\"Transferencia con comprobante y monedero Life Book, sin efectivo.\" />\n                <Futuro titulo=\"Promociones\" detalle=\"Descuentos y ofertas destacadas dentro del catálogo.\" />\n              </View>\n            </Seccion>\n\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, textAlign: 'center', marginTop: espaciado.e8 }}>\n              Los datos son de tu tienda y se cargan con tu sesión · se actualiza cada {REFRESCO_MS / 1000} s\n            </Text>\n          </>\n        )}\n      </ScrollView>\n    </View>\n  );\n}\n\n// ─────────────────────────────── piezas locales ──────────────────────────────\n\nfunction Seccion({ titulo, icono, children }: { titulo: string; icono: React.ReactNode; children: React.ReactNode }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ marginTop: espaciado.e16 }}>\n      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginBottom: espaciado.e8 }}>\n        {icono}\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>{titulo}</Text>\n      </View>\n      {children}\n    </View>\n  );\n}\n\nfunction Mini({ label, valor }: { label: string; valor: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flex: 1 }}>\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }} numberOfLines={1}>{label}</Text>\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', marginTop: 1 }} numberOfLines={1}>{valor}</Text>\n    </View>\n  );\n}\n\nfunction Aviso({ icon, color, texto, onPress }: { icon: React.ReactNode; color: string; texto: string; onPress: () => void }) {\n  return (\n    <Pressable onPress={onPress} style={[styles.aviso, { backgroundColor: color }]}>\n      {icon}\n      <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>{texto}</Text>\n      <ChevronRight size={13} color={brand.white} />\n    </Pressable>\n  );\n}\n\nfunction Futuro({ titulo, detalle }: { titulo: string; detalle: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: espaciado.e8, paddingVertical: espaciado.e6 }}>\n      <View style={{ backgroundColor: alpha(colors.textSecondary, 0.15), borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e2, marginTop: 1 }}>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '900' }}>PRÓXIMAMENTE</Text>\n      </View>\n      <View style={{ flex: 1 }}>\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{titulo}</Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 16 }}>{detalle}</Text>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  card: { borderWidth: StyleSheet.hairlineWidth, borderRadius: radios.lg, padding: espaciado.e14 },\n  iconoSeccion: { width: 30, height: 30, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  logo: { width: 52, height: 52, borderRadius: radios.md },\n  fila: { flexDirection: 'row', gap: espaciado.e10 },\n  aviso: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, borderRadius: radios.full, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e6 },\n});\n","/**\n * LifeBookMessageSearchScreen — Parte 30 (Fase 05): BÚSQUEDA GLOBAL DE MENSAJES.\n *\n * Busca en TODOS mis chats a la vez (1 a 1 y grupos donde estoy), con filtros por\n * tipo (fotos, archivos, notas y ventas, ubicación, votaciones, avisos…) y\n * paginación. Cada resultado dice en qué chat está y al tocarlo se abre ese chat.\n *\n * Respeta lo que borré de mi historial, el «compartir historial» del grupo y los\n * bloqueos (lo aplica el servidor).\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Image, Pressable, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Image as ImageIcon, MapPin, Megaphone, Paperclip, Search, Vote, X } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookChatApi } from '../api/lifebook';\nimport { lbTimeAgo } from '../constants/lifebook';\n\n/** Filtros de tipo (los `kind` reales del servidor). */\nconst FILTERS: { id: string | null; label: string }[] = [\n  { id: null, label: 'Todo' },\n  { id: 'image', label: 'Fotos' },\n  { id: 'file', label: 'Archivos' },\n  { id: 'post', label: 'Notas y ventas' },\n  { id: 'location', label: 'Ubicación' },\n  { id: 'vote', label: 'Votaciones' },\n  { id: 'checkin', label: 'Quedadas' },\n  { id: 'system', label: 'Avisos' },\n];\n\ntype Hit = Awaited<ReturnType<typeof lifebookChatApi.searchAllMessages>>['messages'][number];\n\nexport default function LifeBookMessageSearchScreen() {\n  return (\n    <AuthGate>\n      <MessageSearchContent />\n    </AuthGate>\n  );\n}\n\nfunction MessageSearchContent() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const [q, setQ] = useState('');\n  const [kind, setKind] = useState<string | null>(null);\n  const [hits, setHits] = useState<Hit[]>([]);\n  const [cursor, setCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [buscado, setBuscado] = useState(false);\n  const seq = useRef(0);\n\n  const buscar = useCallback(async (texto: string, tipo: string | null, opts: { append?: boolean; cursor?: string | null } = {}) => {\n    const mine = ++seq.current;\n    if (opts.append) setLoadingMore(true); else setLoading(true);\n    try {\n      const res = await lifebookChatApi.searchAllMessages({\n        q: texto.trim() || undefined,\n        kind: tipo ?? undefined,\n        before: opts.append ? (opts.cursor ?? undefined) : undefined,\n        limit: 30,\n      });\n      if (mine !== seq.current) return;\n      setHits((prev) => (opts.append ? [...prev, ...(res.messages ?? [])] : (res.messages ?? [])));\n      setCursor(res.nextCursor ?? null);\n      setBuscado(true);\n    } catch {\n      if (mine === seq.current && !opts.append) setHits([]);\n    } finally {\n      if (mine === seq.current) { setLoading(false); setLoadingMore(false); }\n    }\n  }, []);\n\n  // Con texto: retardo de 350 ms. Con solo un filtro: inmediato.\n  useEffect(() => {\n    const t = setTimeout(() => { void buscar(q, kind); }, q.trim() ? 350 : 0);\n    return () => clearTimeout(t);\n  }, [q, kind, buscar]);\n\n  const vacio = useMemo(() => buscado && !loading && hits.length === 0, [buscado, loading, hits.length]);\n\n  /** Icono y texto de cada tipo de mensaje. */\n  const resumen = (m: Hit) => {\n    switch (m.kind) {\n      case 'image': return { icon: <ImageIcon size={13} color={colors.primary} />, text: 'Foto' };\n      case 'file': return { icon: <Paperclip size={13} color={colors.primary} />, text: m.fileRef?.name ?? 'Archivo' };\n      case 'post': return { icon: <Text style={{ fontSize: tipografia.caption }}>📄</Text>, text: m.postRef?.title ?? 'Nota compartida' };\n      case 'sale': return { icon: <Text style={{ fontSize: tipografia.caption }}>🏷️</Text>, text: m.postRef?.title ?? 'Venta' };\n      case 'location': return { icon: <MapPin size={13} color={colors.primary} />, text: m.locationRef?.label ?? 'Ubicación' };\n      case 'vote': return { icon: <Vote size={13} color={colors.primary} />, text: m.voteRef?.question ?? 'Votación' };\n      case 'checkin': return { icon: <Text style={{ fontSize: tipografia.caption }}>📅</Text>, text: m.checkinRef?.when ?? 'Quedada' };\n      case 'chain': return { icon: <Text style={{ fontSize: tipografia.caption }}>🔗</Text>, text: m.chainRef?.title ?? 'Cadena' };\n      case 'ad': return { icon: <Megaphone size={13} color={colors.primary} />, text: m.adRef?.title ?? m.adRef?.text ?? 'Anuncio' };\n      default: return { icon: <Text style={{ fontSize: tipografia.caption }}>💬</Text>, text: m.body || 'Mensaje' };\n    }\n  };\n\n  const abrirChat = (m: Hit) => {\n    router.push({\n      pathname: '/lifebook-chat/[id]',\n      params: { id: m.conversation.id, name: m.conversation.title, isGroup: m.conversation.kind === 'group' ? '1' : '0' },\n    } as never);\n  };\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\n      {/* Cabecera con el buscador */}\n      <View style={[styles.header, { backgroundColor: colors.card, borderBottomColor: alpha(colors.border, 0.6) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={8} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\n          <Search size={16} color={colors.textSecondary} />\n          <TextInput\n            value={q}\n            onChangeText={setQ}\n            placeholder=\"Buscar en todos mis chats…\"\n            placeholderTextColor={colors.textSecondary}\n            autoFocus\n            style={{ flex: 1, marginLeft: espaciado.e8, color: colors.textPrimary, fontSize: tipografia.body }}\n            accessibilityLabel=\"Buscar mensajes en todos mis chats\"\n          />\n          {q.length > 0 ? (\n            <Pressable onPress={() => setQ('')} hitSlop={8} accessibilityLabel=\"Borrar la búsqueda\">\n              <X size={16} color={colors.textSecondary} />\n            </Pressable>\n          ) : null}\n        </View>\n      </View>\n\n      {/* Filtros por tipo */}\n      <FlatList\n        horizontal\n        showsHorizontalScrollIndicator={false}\n        data={FILTERS}\n        keyExtractor={(f) => f.id ?? 'todo'}\n        contentContainerStyle={{ gap: espaciado.e6, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}\n        renderItem={({ item }) => {\n          const activo = kind === item.id;\n          return (\n            <Pressable\n              onPress={() => setKind(item.id)}\n              accessibilityLabel={`Filtrar por ${item.label}`}\n              style={[styles.chip, {\n                backgroundColor: activo ? alpha(colors.primary, 0.14) : colors.surface,\n                borderColor: activo ? colors.primary : 'transparent',\n              }]}\n            >\n              <Text style={{ color: activo ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{item.label}</Text>\n            </Pressable>\n          );\n        }}\n      />\n\n      {loading ? (\n        <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e30 }} />\n      ) : (\n        <FlatList\n          data={hits}\n          keyExtractor={(m) => m.id}\n          contentContainerStyle={{ padding: espaciado.e14, gap: espaciado.e8, paddingBottom: insets.bottom + 24 }}\n          onEndReachedThreshold={0.4}\n          onEndReached={() => {\n            if (!cursor || loadingMore) return;\n            setLoadingMore(true);\n            void buscar(q, kind, { append: true, cursor });\n          }}\n          ListEmptyComponent={\n            vacio ? (\n              <View style={{ alignItems: 'center', marginTop: 40, gap: espaciado.e6 }}>\n                <Search size={24} color={colors.textSecondary} />\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n                  {q.trim() ? `Nada que coincida con «${q.trim()}» en tus chats.` : 'Escribe algo para buscar (o elige un filtro).'}\n                </Text>\n              </View>\n            ) : null\n          }\n          ListFooterComponent={loadingMore ? <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e12 }} /> : null}\n          renderItem={({ item }) => {\n            const r = resumen(item);\n            return (\n              <Pressable\n                onPress={() => abrirChat(item)}\n                accessibilityLabel={`${item.conversation.title}: ${r.text}`}\n                style={({ pressed }) => [styles.hit, { backgroundColor: colors.card, opacity: pressed ? 0.85 : 1 }]}\n              >\n                {item.conversation.photoUrl ? (\n                  <Image source={{ uri: absUrl(item.conversation.photoUrl) }} style={styles.hitAvatar} />\n                ) : (\n                  <View style={[styles.hitAvatar, styles.center, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n                    <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>\n                      {(item.conversation.title || '?').trim().charAt(0).toUpperCase()}\n                    </Text>\n                  </View>\n                )}\n                <View style={{ flex: 1 }}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n                    <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body, flex: 1 }} numberOfLines={1}>\n                      {item.conversation.title}\n                    </Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>{lbTimeAgo(item.createdAt)}</Text>\n                  </View>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, marginTop: espaciado.e3 }}>\n                    {r.icon}\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, flex: 1 }} numberOfLines={2}>{r.text}</Text>\n                  </View>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e3 }}>\n                    {item.mine ? 'Tú' : (item.sender?.fullName ?? 'Alguien')} · {item.conversation.kind === 'group' ? 'grupo' : 'chat'}\n                  </Text>\n                </View>\n              </Pressable>\n            );\n          }}\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  header: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth },\n  searchBox: { flex: 1, flexDirection: 'row', alignItems: 'center', borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: 42 },\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderWidth: 1 },\n  hit: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderRadius: 14, padding: espaciado.e12 },\n  hitAvatar: { width: 40, height: 40, borderRadius: radios.md },\n  center: { alignItems: 'center', justifyContent: 'center' },\n});\n","/**\r\n * Life Book — MENSAJES (/lifebook-messages)\r\n *\r\n * Estilo Xiaohongshu con datos REALES (Fase A sobre `api/messages.ts`):\r\n *  - Cabecera: título + buscar personas (abre la búsqueda).\r\n *  - 3 atajos de bandeja con contador (me gustas/guardados · seguidores ·\r\n *    comentarios y @) → pantallas existentes de bandeja.\r\n *  - Filtro Todos / No leídos.\r\n *  - Filas de conversación: avatar, nombre, hora (`lbTimeAgo`), última línea,\r\n *    \"Escribiendo…\" y contexto de publicación **cuando el servidor los envíe**\r\n *    (Fase B: hoy llegan vacíos), badge de no leídos.\r\n *  - Pull-to-refresh, estados de carga/error/vacío y refresco al enfocar.\r\n */\r\nimport React, { useCallback, useMemo, useState } from 'react';\r\nimport { ActivityIndicator, Alert, FlatList, Image, Pressable, StyleSheet, Text, View } from 'react-native';\r\nimport { useRouter, useFocusEffect } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { AtSign, Compass, Heart, MessageCircle, MessagesSquare, ScanLine, ScrollText, Search, UserPlus } from 'lucide-react-native';\r\nimport { AuthGate } from '../core/AuthGate';\r\nimport { messagesApi, toConversationCard, type LbConversation, type LbConversationCard } from '../api/messages';\r\nimport type { LbInboxCounts } from '../api/lifebook';\r\nimport { authApi } from '../api/auth';\r\nimport { absUrl } from '../api/config';\r\nimport { destinoMiPerfilLifeBook } from '../core/miPerfil';\r\nimport { DOCK_BODY_H } from '../components/FloatingFooter';\r\nimport DockFooter from '../components/FloatingFooter';\r\nimport { useAppDock } from '../core/useAppDock';\r\nimport {\r\n  AddFriendSheet, ScanSheet, SearchChatsSheet,\r\n} from '../components/lifebook/messaging-sheets';\r\nimport { ir as irSeguro } from '../constants/rutas';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\nexport default function LifeBookMessages() {\r\n  return (\r\n    <AuthGate>\r\n      <MessagesContent />\r\n    </AuthGate>\r\n  );\r\n}\r\n\r\nfunction MessagesContent() {\r\n  const { colors } = useTheme();\r\n  const insets = useSafeAreaInsets();\r\n  const router = useRouter();\r\n  const navigate = useAppDock('mensajes');\r\n\r\n  const [convs, setConvs] = useState<LbConversation[] | null>(null);\r\n  const [counts, setCounts] = useState<LbInboxCounts | null>(null);\r\n  const [refreshing, setRefreshing] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n  /**\r\n   * Filtro de la lista. Además de leído/no leído, separa **Chats** (1 a 1) de\r\n   * **Grupos**: es lo que pidió el dueño («organizar los mensajes en chat y grupos») y\r\n   * es lo que hace Xiaohongshu, que lleva el chat privado y los grupos por un lado y\r\n   * los avisos (me gusta, comentarios…) por otro. El dato ya venía del backend\r\n   * (`isGroup` en la tarjeta), así que separarlos no cuesta nada.\r\n   */\r\n  /**\r\n   * Quién eres, para el AVATAR de esta pantalla. El dueño pidió moverlo aquí desde la\r\n   * barra de Life Book, junto a los iconos de Me gusta, Seguidores y Comentarios.\r\n   * `null` mientras no se sabe: el botón se pinta igual, con la inicial, así que la\r\n   * puerta al perfil existe siempre aunque el servidor no conteste.\r\n   */\r\n  const [yo, setYo] = useState<{ id: string | null; avatarUrl: string | null; fullName: string | null } | null>(null);\r\n  const [filter, setFilter] = useState<'all' | 'unread' | 'chats' | 'groups'>('all');\r\n  const [sheet, setSheet] = useState<null | 'search' | 'group' | 'friend' | 'scan'>(null);\r\n\r\n  const load = useCallback(async () => {\r\n    try {\r\n      const page = await messagesApi.conversations();\r\n      setConvs(page.conversations);\r\n      setError(null);\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : 'No se pudieron cargar los mensajes');\r\n    }\r\n  }, []);\r\n\r\n  useFocusEffect(useCallback(() => {\r\n    load();\r\n    messagesApi.inboxCounts().then(setCounts).catch(() => {});\r\n    // El avatar del dueño: la misma llamada que ya se hacía en otras pantallas.\r\n    authApi.me().then((m) => setYo({\r\n      id: m?.id ?? null, avatarUrl: m?.avatarUrl ?? null, fullName: m?.fullName ?? null,\r\n    })).catch(() => {});\r\n  }, [load]));\r\n\r\n  const cards: LbConversationCard[] = useMemo(\r\n    () => (convs ?? []).map(toConversationCard).filter((c) => (\r\n      filter === 'unread' ? c.unreadCount > 0\r\n        : filter === 'chats' ? !c.isGroup\r\n          : filter === 'groups' ? c.isGroup\r\n            : true\r\n    )),\r\n    [convs, filter],\r\n  );\r\n\r\n  /* `totalUnread` se calculaba solo para el «N sin leer» de la cabecera, que se ha\r\n     quitado (el contador vive en la pestaña del dock). Se borra para no dejar código\r\n     muerto ni un recuento que nadie mira. */\r\n\r\n  return (\r\n    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: insets.top }}>\r\n      {/* Cabecera */}\r\n      <View style={styles.header}>\r\n        {/* El título «Mensajes» y su «N sin leer» YA NO ESTÁN, y es a propósito:\r\n            · el título solo gastaba altura en un móvil y la pantalla ya está\r\n              identificada por su pestaña del dock («Mensajes», con su contador);\r\n            · el «N sin leer» no significaba nada sin el título encima, así que se\r\n              va con él. El contador de no leídos sigue en la pestaña del dock, que\r\n              es donde de verdad hace falta.\r\n            La cabecera se queda con las ACCIONES (buscar, crear grupo, descubrir\r\n            grupos, añadir amigo, escanear), que es lo único que hacía falta aquí. */}\r\n        <Pressable\r\n          hitSlop={8}\r\n          accessibilityLabel=\"Buscar en mis mensajes, contactos y grupos\"\r\n          /* ESTABA MAL: apuntaba a `/lifebook-search`, la BÚSQUEDA GENERAL de Life\r\n             Book. Para eso ya está la lupa de la pantalla principal. Aquí lo que se\r\n             busca es DENTRO de los mensajes: mis chats (1 a 1) y mis grupos, con sus\r\n             fotos, archivos, notas… Esa pantalla ya existía\r\n             (`lifebook-message-search`), solo había que apuntar a ella. */\r\n          onPress={() => irSeguro.libre('/lifebook-message-search')}\r\n        >\r\n          <Search size={20} color={colors.textPrimary} />\r\n        </Pressable>\r\n        <Pressable hitSlop={8} accessibilityLabel=\"Crear grupo\" onPress={() => irSeguro.libre('/lifebook-group-create')}>\r\n          <MessagesSquare size={20} color={colors.textPrimary} />\r\n        </Pressable>\r\n        {/* Parte 27 (G3): descubrir grupos públicos y unirse */}\r\n        <Pressable hitSlop={8} accessibilityLabel=\"Descubrir grupos\" onPress={() => irSeguro.libre('/lifebook-groups')}>\r\n          <Compass size={20} color={colors.primary} />\r\n        </Pressable>\r\n        <Pressable hitSlop={8} accessibilityLabel=\"Añadir amigo\" onPress={() => setSheet('friend')}>\r\n          <UserPlus size={20} color={colors.textPrimary} />\r\n        </Pressable>\r\n        <Pressable hitSlop={8} accessibilityLabel=\"Escanear\" onPress={() => setSheet('scan')}>\r\n          <ScanLine size={20} color={colors.textPrimary} />\r\n        </Pressable>\r\n      </View>\r\n\r\n      {/* ── 3 bandejas (estilo Xiaohongshu) ── */}\r\n      <View style={styles.inboxRow}>\r\n        {/* ── TU PERFIL ──\r\n            El dueño pidió mover el avatar desde la barra de Life Book a esta pantalla,\r\n            JUNTO a los iconos de Me gusta, Seguidores y Comentarios, que es donde está\r\n            de verdad todo lo tuyo. Lleva al perfil PÚBLICO con el mismo destino que la\r\n            fila del ☰ y que el dock (`core/miPerfil`), para que no puedan separarse. */}\r\n        <Pressable\r\n          onPress={async () => {\r\n            /* El id se pide EN EL MOMENTO si no está: medido, el botón se pintaba pero\r\n               el toque no hacía nada porque `destinoMiPerfilLifeBook` devuelve `null`\r\n               sin id (a propósito, para no navegar a un perfil vacío). Un botón que no\r\n               hace nada es peor que no tenerlo, así que aquí se resuelve solo. */\r\n            let id = yo?.id ?? null;\r\n            if (!id) {\r\n              try { const m = await authApi.me(); id = m?.id ?? null; } catch { /* sin id no se navega */ }\r\n            }\r\n            const destino = destinoMiPerfilLifeBook(id);\r\n            /* Si no se pudo resolver el id (sesión a medias), antes NO pasaba nada: el botón\r\n               parecía roto. Ahora se valida y, si no hay destino, se explica. */\r\n            irSeguro.destino(destino, 'No se pudo leer tu perfil de Life Book.');\r\n          }}\r\n          hitSlop={6}\r\n          accessibilityRole=\"button\"\r\n          accessibilityLabel=\"Mi perfil de Life Book\"\r\n          style={styles.inboxShortcut}\r\n        >\r\n          {yo?.avatarUrl ? (\r\n            <Image\r\n              source={{ uri: absUrl(yo.avatarUrl) }}\r\n              /* 48 y no 34: es el MISMO tamaño que los iconos de al lado\r\n                 (`styles.inboxIcon` = 48×48), que es lo que se pidió. Medido: con 34\r\n                 se veía pequeño al lado de los otros tres. */\r\n              style={{ width: 48, height: 48, borderRadius: 24 }}\r\n            />\r\n          ) : (\r\n            <View style={{\r\n              width: 48, height: 48, borderRadius: 24,\r\n              backgroundColor: colors.surface,\r\n              alignItems: 'center', justifyContent: 'center',\r\n            }}>\r\n              <Text style={{ color: colors.primary, fontSize: 19, fontWeight: '900' }}>\r\n                {(yo?.fullName?.trim()?.charAt(0) ?? '?').toUpperCase()}\r\n              </Text>\r\n            </View>\r\n          )}\r\n          <Text style={styles.inboxLabel}>Mi perfil</Text>\r\n        </Pressable>\r\n\r\n        <InboxShortcut\r\n          icon={<Heart size={20} color={brand.white} fill={brand.white} />}\r\n          bg={brand.like}\r\n          label=\"Me gusta\"\r\n          badge={(counts?.likes ?? 0) + (counts?.saves ?? 0)}\r\n          onPress={() => irSeguro.libre('/lifebook-inbox', { tab: 'likes' })}\r\n        />\r\n        <InboxShortcut\r\n          icon={<UserPlus size={20} color={brand.white} />}\r\n          bg={brand.primary}\r\n          label=\"Seguidores\"\r\n          badge={counts?.followers ?? 0}\r\n          onPress={() => irSeguro.libre('/lifebook-inbox', { tab: 'followers' })}\r\n        />\r\n        <InboxShortcut\r\n          icon={<AtSign size={20} color={brand.white} />}\r\n          bg={brand.secondary}\r\n          label=\"Comentarios\"\r\n          badge={(counts?.comments ?? 0) + (counts?.mentions ?? 0)}\r\n          onPress={() => irSeguro.libre('/lifebook-inbox', { tab: 'comments' })}\r\n        />\r\n      </View>\r\n\r\n      {/* Filtro */}\r\n      <View style={styles.filterRow}>\r\n        {(['all', 'unread', 'chats', 'groups'] as const).map((f) => (\r\n          <Pressable\r\n            key={f}\r\n            onPress={() => setFilter(f)}\r\n            accessibilityRole=\"tab\"\r\n            accessibilityState={{ selected: filter === f }}\r\n            style={[styles.filterChip, { backgroundColor: filter === f ? colors.primary : colors.surface }]}\r\n          >\r\n            <Text style={{ color: filter === f ? brand.white : colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\r\n              {f === 'all' ? 'Todos' : f === 'unread' ? 'No leídos' : f === 'chats' ? 'Chats' : 'Grupos'}\r\n            </Text>\r\n          </Pressable>\r\n        ))}\r\n      </View>\r\n\r\n      {/* Lista */}\r\n      {convs === null && !error ? (\r\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>\r\n          <ActivityIndicator color={colors.primary} />\r\n        </View>\r\n      ) : error && !convs ? (\r\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e12, padding: espaciado.e24 }}>\r\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '700', textAlign: 'center' }}>{error}</Text>\r\n          <Pressable onPress={load} style={{ backgroundColor: colors.surface, borderRadius: radios.full, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e9 }}>\r\n            <Text style={{ color: colors.primary, fontWeight: '800' }}>Reintentar</Text>\r\n          </Pressable>\r\n        </View>\r\n      ) : (\r\n        <FlatList\r\n          data={cards}\r\n          keyExtractor={(i) => i.id}\r\n          contentContainerStyle={{ paddingBottom: DOCK_BODY_H + insets.bottom + 20, flexGrow: 1 }}\r\n          refreshing={refreshing}\r\n          onRefresh={async () => { setRefreshing(true); await load(); setRefreshing(false); }}\r\n          ItemSeparatorComponent={() => <View style={{ height: StyleSheet.hairlineWidth, backgroundColor: colors.border, marginLeft: 76 }} />}\r\n          renderItem={({ item }) => {\r\n            const peerId = convs?.find((c) => c.id === item.id)?.peer.id ?? null;\r\n            return (\r\n              <ConversationRow\r\n                card={item}\r\n                colors={colors}\r\n                onPress={() => irSeguro.libre('/lifebook-chat/[id]', { id: item.id, name: item.name, peerId: peerId ?? undefined })}\r\n                /* Solo en chats 1 a 1: en un grupo no hay «el perfil» de nadie. */\r\n                onPressAvatar={!item.isGroup && peerId ? () => irSeguro.libre('/lifebook-user', { id: peerId }) : undefined}\r\n              />\r\n            );\r\n          }}\r\n          ListEmptyComponent={\r\n            <View style={{ alignItems: 'center', justifyContent: 'center', paddingTop: 70, gap: espaciado.e8 }}>\r\n              <MessageCircle size={40} color={alpha(colors.primary, 0.45)} />\r\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>\r\n                {filter === 'unread' ? 'No tienes mensajes sin leer.'\r\n              : filter === 'chats' ? 'No tienes conversaciones de uno a uno.'\r\n                : filter === 'groups' ? 'No estás en ningún grupo todavía.'\r\n                  : 'Aún no tienes conversaciones'}\r\n              </Text>\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingHorizontal: 40, lineHeight: 18 }}>\r\n                Entra en un perfil o una publicación y toca \"Mensaje\" para empezar a hablar.\r\n              </Text>\r\n            </View>\r\n          }\r\n        />\r\n      )}\r\n\r\n      <DockFooter active=\"mensajes\" onNavigate={navigate} />\r\n\r\n      {/* ── Hojas de la cabecera ── */}\r\n      <SearchChatsSheet\r\n        visible={sheet === 'search'}\r\n        onClose={() => setSheet(null)}\r\n        convos={convs ?? []}\r\n        onPick={(id) => {\r\n          setSheet(null);\r\n          const c = (convs ?? []).find((x) => x.id === id);\r\n          irSeguro.libre('/lifebook-chat/[id]', { id, name: c?.title ?? c?.peer.name ?? '', peerId: c?.peer.id });\r\n        }}\r\n      />\r\n      {/* Crear grupo: pantalla completa `/lifebook-group-create` (flujo nuevo) */}\r\n      <AddFriendSheet\r\n        visible={sheet === 'friend'}\r\n        onClose={() => setSheet(null)}\r\n        onOpenChat={async (userId, name) => {\r\n          try {\r\n            const conv = await messagesApi.open(userId);\r\n            await load();\r\n            irSeguro.libre('/lifebook-chat/[id]', { id: conv.id, name, peerId: userId });\r\n          } catch (e) {\r\n            Alert.alert('Mensaje', e instanceof Error ? e.message : 'No se pudo abrir el chat.');\r\n          }\r\n        }}\r\n      />\r\n      <ScanSheet\r\n        visible={sheet === 'scan'}\r\n        onClose={() => setSheet(null)}\r\n        onDocument={() => irSeguro.libre('/scanner')}\r\n        onQr={() => irSeguro.libre('/lifebook-scan')}\r\n      />\r\n    </View>\r\n  );\r\n}\r\n\r\n// ── Atajo de bandeja ──────────────────────────────────────────\r\nfunction InboxShortcut({ icon, bg, label, badge, onPress }: {\r\n  icon: React.ReactNode; bg: string; label: string; badge: number; onPress: () => void;\r\n}) {\r\n  return (\r\n    <Pressable onPress={onPress} style={styles.inboxShortcut} hitSlop={6} accessibilityLabel={`${label}${badge > 0 ? `, ${badge}` : ''}`}>\r\n      <View style={[styles.inboxIcon, { backgroundColor: bg }]}>\r\n        {icon}\r\n        {badge > 0 ? (\r\n          <View style={styles.inboxBadge}>\r\n            <Text style={{ color: brand.white, fontSize: 9, fontWeight: '900' }}>{badge > 9 ? '9+' : badge}</Text>\r\n          </View>\r\n        ) : null}\r\n      </View>\r\n      <Text style={styles.inboxLabel} numberOfLines={1}>{label}</Text>\r\n    </Pressable>\r\n  );\r\n}\r\n\r\n// ── Fila de conversación ──────────────────────────────────────\r\nfunction ConversationRow({ card, colors, onPress, onPressAvatar }: {\r\n  card: LbConversationCard; colors: any; onPress: () => void;\r\n  /** Tocar el AVATAR lleva al perfil de esa persona (no al chat). En un grupo no\r\n   *  hay un perfil al que ir, así que se queda sin acción. */\r\n  onPressAvatar?: () => void;\r\n}) {\r\n  const isUnread = card.unreadCount > 0;\r\n  const avatar = card.avatarUrl ? (\r\n    <Image source={{ uri: card.avatarUrl }} style={styles.convoAvatar} />\r\n  ) : (\r\n    <View style={[styles.convoAvatar, styles.avatarFallback, { backgroundColor: alpha(colors.primary, 0.15) }]}>\r\n      <Text style={{ color: colors.primary, fontWeight: '800', fontSize: 15 }}>\r\n        {card.name.trim().charAt(0).toUpperCase()}\r\n      </Text>\r\n    </View>\r\n  );\r\n  return (\r\n    <Pressable\r\n      onPress={onPress}\r\n      style={({ pressed }) => [styles.convoRow, { backgroundColor: pressed ? alpha(colors.primary, 0.05) : 'transparent' }]}\r\n    >\r\n      {/* El avatar SE TOCA: lleva al perfil de la persona. Antes toda la fila abría el\r\n          chat y no había forma de ver quién es desde aquí, que es justo lo que se pidió. */}\r\n      {onPressAvatar ? (\r\n        <Pressable\r\n          onPress={onPressAvatar}\r\n          hitSlop={6}\r\n          accessibilityLabel={`Ver el perfil de ${card.name}`}\r\n        >\r\n          {avatar}\r\n        </Pressable>\r\n      ) : avatar}\r\n\r\n      <View style={{ flex: 1 }}>\r\n        <View style={{ flexDirection: 'row', alignItems: 'center' }}>\r\n          <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: isUnread ? '800' : '600', fontSize: tipografia.body, flex: 1 }}>\r\n            {card.name}\r\n          </Text>\r\n          {card.isGroup ? (\r\n            <View style={[styles.groupChip, { backgroundColor: alpha(colors.primary, 0.12) }]}>\r\n              <Text style={{ color: colors.primary, fontSize: 10, fontWeight: '700' }}>\r\n                👥 {card.memberCount ?? 0}\r\n              </Text>\r\n            </View>\r\n          ) : null}\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginLeft: espaciado.e6 }}>{card.timeLabel}</Text>\r\n        </View>\r\n\r\n        <Text\r\n          numberOfLines={1}\r\n          style={{\r\n            color: isUnread ? colors.textPrimary : colors.textSecondary,\r\n            fontWeight: isUnread ? '600' : '400',\r\n            fontSize: tipografia.body,\r\n            marginTop: espaciado.e2,\r\n          }}\r\n        >\r\n          {card.lastMessage || '…'}\r\n        </Text>\r\n\r\n        {/* Fase B: contexto de la publicación que originó el chat */}\r\n        {card.relatedPostTitle ? (\r\n          <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\r\n            📦 {card.relatedPostTitle}\r\n          </Text>\r\n        ) : null}\r\n      </View>\r\n\r\n      {isUnread ? (\r\n        <View style={styles.unreadBadge}>\r\n          <Text style={{ color: brand.white, fontSize: 10, fontWeight: '800' }}>\r\n            {card.unreadCount > 99 ? '99+' : card.unreadCount}\r\n          </Text>\r\n        </View>\r\n      ) : null}\r\n    </Pressable>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  header: {\r\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e16,\r\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12,\r\n  },\r\n  title: { fontSize: tipografia.title, fontWeight: '800' },\r\n  groupChip: {\r\n    paddingHorizontal: espaciado.e6, paddingVertical: 1, borderRadius: radios.sm, marginLeft: espaciado.e6,\r\n  },\r\n  inboxRow: {\r\n    flexDirection: 'row', justifyContent: 'space-around',\r\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12,\r\n  },\r\n  inboxShortcut: { alignItems: 'center', gap: espaciado.e4 },\r\n  inboxIcon: {\r\n    width: 48, height: 48, borderRadius: 24,\r\n    alignItems: 'center', justifyContent: 'center',\r\n  },\r\n  inboxBadge: {\r\n    position: 'absolute', top: -3, right: -4, backgroundColor: brand.danger,\r\n    borderRadius: 9, minWidth: 18, height: 18, paddingHorizontal: espaciado.e3,\r\n    alignItems: 'center', justifyContent: 'center', borderWidth: 1.5, borderColor: brand.white,\r\n  },\r\n  inboxLabel: { fontSize: tipografia.micro, fontWeight: '600', color: '#8A8F99' },\r\n  filterRow: { flexDirection: 'row', gap: espaciado.e8, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e10 },\r\n  filterChip: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e6 },\r\n  convoRow: {\r\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\r\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12,\r\n  },\r\n  convoAvatar: { width: 50, height: 50, borderRadius: 25 },\r\n  avatarFallback: { alignItems: 'center', justifyContent: 'center' },\r\n  unreadBadge: {\r\n    backgroundColor: brand.like, borderRadius: radios.full,\r\n    minWidth: 18, height: 18, alignItems: 'center', justifyContent: 'center',\r\n    paddingHorizontal: espaciado.e5,\r\n  },\r\n});\r\n","/**\n * miPerfil — DÓNDE ESTÁ «MI PERFIL DE LIFE BOOK», en un solo sitio.\n *\n * ── Por qué existe este fichero tan pequeño ─────────────────────────────────\n * El acceso a lo tuyo sale en DOS sitios: la **barra superior de Life Book** (el avatar) y el\n * **menú lateral ☰** (la fila «Mi perfil de Life Book»). El estándar que este proyecto ya aplica\n * a los negocios (`ESTANDAR-ENTORNOS-DE-CONTROL.md`, implementado en `core/useMisNegocios.ts`)\n * dice, con estas palabras, por qué eso no puede resolverse por separado:\n *\n *   «Si cada pantalla lo detectara por su cuenta, en dos semanas una conocería el restaurante y\n *    la otra no.»\n *\n * Aquí pasa lo mismo con el DESTINO: si cada puerta montara su ruta a mano, el día que se cambie\n * el perfil de sitio una llevaría al nuevo y la otra al viejo, y nadie se enteraría hasta que un\n * usuario lo reportara. Una función, dos llamadas.\n *\n * ── Qué perfil es, y por qué no `/profile` ──────────────────────────────────\n * El **público** (`/lifebook-user`), no el de cuenta (`/profile`). Es lo que decidió el dueño y\n * es lo que hace 小红书: tu perfil es **el que ven los demás**, y esa pantalla ya sabe cuándo eres\n * tú — el servidor calcula `relation.isSelf` (`api/lifebook.ts:315`) y cambia sola a «Tu perfil»,\n * «Editar perfil» en vez de «Seguir», y lápiz en vez de ⋯.\n *\n * Además, medido en el código: **el perfil público es el único sitio donde se ven las\n * verificaciones** (Conductor · Tienda · Restaurante · Contratante · Anfitrión,\n * `lifebook-user.tsx:34-39`). El perfil de cuenta NO las pinta, y las tarjetas del feed tampoco.\n * O sea que el «perfil de Life Book» —el que enseña de qué está verificado alguien— sólo puede\n * ser ése.\n */\nexport function destinoMiPerfilLifeBook(id?: string | null) {\n  // Sin id no hay perfil al que ir. Se devuelve null a propósito en vez de una ruta a medias:\n  // quien lo use decide si esconde el botón o espera, pero nunca navega a un perfil vacío.\n  return id ? ({ pathname: '/lifebook-user', params: { id } } as const) : null;\n}\n","/**\r\n * messaging-sheets — hojas de la cabecera de Mensajes:\r\n *   · SearchChatsSheet  → buscar entre tus conversaciones (real, en cliente)\r\n *   · AddFriendSheet    → personas (recomendados + seguidores) con Seguir y\r\n *                         Mensaje, ambos REALES\r\n *   · CreateGroupSheet  → vive en `./CreateGroupSheet` (se reexporta aquí para\r\n *                         no romper los imports antiguos)\r\n *   · ScanSheet         → escanear documento (/scanner, real) o QR de amigo\r\n *                         (pendiente: lector + búsqueda por EG-ID)\r\n */\r\nimport React, { useCallback, useEffect, useState } from 'react';\r\nimport {\r\n  ActivityIndicator, Image, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\r\n} from 'react-native';\r\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { Check, FileScan, QrCode, Search, UserPlus } from 'lucide-react-native';\r\nimport { lifebookApi, lifebookInboxApi, type LbFollowerItem, type LbSuggestedUser } from '../../api/lifebook';\r\nimport { messagesApi, type LbConversation, type LbConversationCard, toConversationCard } from '../../api/messages';\r\nimport { lbTimeAgo } from '../../constants/lifebook';\r\nimport { Sheet, SheetHeader } from './ui/Sheet';\r\nimport { PersonRow } from './PersonRow';\r\nimport { formaHoja, formaTirador } from './ui/Sheet';\r\n\r\nexport { CreateGroupSheet } from './CreateGroupSheet';\r\n\r\n/* ── 1. Buscar entre mis chats ── */\r\n\r\nexport function SearchChatsSheet({ visible, onClose, convos, onPick }: {\r\n  visible: boolean; onClose: () => void; convos: LbConversation[]; onPick: (id: string) => void;\r\n}) {\r\n  const { colors } = useTheme();\r\n  const [q, setQ] = useState('');\r\n  const [rows, setRows] = useState<LbConversationCard[]>([]);\r\n\r\n  useEffect(() => {\r\n    const term = q.trim().toLowerCase();\r\n    const cards = convos.map(toConversationCard);\r\n    setRows(term\r\n      ? cards.filter((c) => `${c.name} ${c.lastMessage}`.toLowerCase().includes(term))\r\n      : cards);\r\n  }, [q, convos]);\r\n\r\n  return (\r\n    <Sheet visible={visible} onClose={onClose}>\r\n      <SheetHeader title=\"Buscar chat\" onClose={onClose} />\r\n      <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\r\n        <Search size={16} color={colors.textSecondary} />\r\n        <TextInput\r\n          value={q}\r\n          onChangeText={setQ}\r\n          placeholder=\"Nombre o mensaje…\"\r\n          placeholderTextColor={colors.textSecondary}\r\n          style={{ flex: 1, marginLeft: espaciado.e6, color: colors.textPrimary, fontSize: tipografia.body }}\r\n          autoFocus\r\n        />\r\n      </View>\r\n      <ScrollView style={{ maxHeight: 340 }} keyboardShouldPersistTaps=\"handled\">\r\n        {rows.length === 0 ? (\r\n          <Text style={{ color: colors.textSecondary, textAlign: 'center', paddingVertical: espaciado.e20, fontSize: tipografia.body }}>\r\n            {convos.length === 0 ? 'Todavía no tienes conversaciones.' : 'Nada coincide.'}\r\n          </Text>\r\n        ) : rows.map((c) => (\r\n          <Pressable key={c.id} onPress={() => onPick(c.id)} style={({ pressed }) => [{ opacity: pressed ? 0.7 : 1 }]}>\r\n            <PersonRow\r\n              name={c.name}\r\n              avatarUrl={c.avatarUrl}\r\n              subtitle={`${c.lastMessage} · ${c.timeLabel}`}\r\n              actions={c.unreadCount > 0\r\n                ? <View style={[styles.badge, { backgroundColor: colors.danger }]}><Text style={styles.badgeText}>{c.unreadCount > 9 ? '9+' : c.unreadCount}</Text></View>\r\n                : null}\r\n            />\r\n          </Pressable>\r\n        ))}\r\n      </ScrollView>\r\n    </Sheet>\r\n  );\r\n}\r\n\r\n/* ── 2. Añadir amigo (seguir / escribir) ── */\r\n\r\nexport function AddFriendSheet({ visible, onClose, onOpenChat }: {\r\n  visible: boolean; onClose: () => void; onOpenChat: (userId: string, name: string) => void;\r\n}) {\r\n  const { colors } = useTheme();\r\n  const [people, setPeople] = useState<Array<{ id: string; name: string; avatarUrl?: string | null; note?: string; following?: boolean }> | null>(null);\r\n  const [busyId, setBusyId] = useState<string | null>(null);\r\n\r\n  const load = useCallback(async () => {\r\n    try {\r\n      const [suggested, followers] = await Promise.all([\r\n        lifebookInboxApi.suggested().catch(() => [] as LbSuggestedUser[]),\r\n        lifebookInboxApi.followers().catch(() => [] as LbFollowerItem[]),\r\n      ]);\r\n      const seen = new Set<string>();\r\n      const list: Array<{ id: string; name: string; avatarUrl?: string | null; note?: string; following?: boolean }> = [];\r\n      for (const f of followers) {\r\n        if (!f.id || seen.has(f.id)) continue;\r\n        seen.add(f.id);\r\n        list.push({ id: f.id, name: f.fullName?.trim() || 'Usuario', avatarUrl: f.avatarUrl, note: `Te sigue · ${lbTimeAgo(f.at)}`, following: !!f.followedBack });\r\n      }\r\n      for (const s of suggested) {\r\n        if (!s.id || seen.has(s.id)) continue;\r\n        seen.add(s.id);\r\n        list.push({ id: s.id, name: s.fullName?.trim() || 'Usuario', avatarUrl: s.avatarUrl, note: s.reason });\r\n      }\r\n      setPeople(list);\r\n    } catch { setPeople([]); }\r\n  }, []);\r\n\r\n  useEffect(() => { if (visible) { setPeople(null); load(); } }, [visible, load]);\r\n\r\n  const follow = async (userId: string, i: number) => {\r\n    setBusyId(userId);\r\n    try {\r\n      await lifebookApi.follow(userId);\r\n      setPeople((prev) => (prev ?? []).map((p, idx) => (idx === i ? { ...p, following: true, note: 'Siguiendo' } : p)));\r\n    } catch { /* silencioso */ }\r\n    finally { setBusyId(null); }\r\n  };\r\n\r\n  return (\r\n    <Sheet visible={visible} onClose={onClose}>\r\n      <SheetHeader title=\"Añadir amigo\" onClose={onClose} />\r\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e10 }}>\r\n        Personas que te siguen o que publican cerca de ti. Puedes seguirlas o escribirles.\r\n      </Text>\r\n      {people === null ? (\r\n        <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e20 }} />\r\n      ) : people.length === 0 ? (\r\n        <Text style={{ color: colors.textSecondary, textAlign: 'center', paddingVertical: espaciado.e20, fontSize: tipografia.body }}>\r\n          No hay recomendaciones por ahora.\r\n        </Text>\r\n      ) : (\r\n        <ScrollView style={{ maxHeight: 360 }} keyboardShouldPersistTaps=\"handled\">\r\n          {people.map((p, i) => (\r\n            <PersonRow\r\n              key={p.id}\r\n              name={p.name}\r\n              avatarUrl={p.avatarUrl}\r\n              subtitle={p.note}\r\n              actions={\r\n                <>\r\n                  {!p.following ? (\r\n                    <Pressable\r\n                      onPress={() => follow(p.id, i)}\r\n                      disabled={busyId === p.id}\r\n                      style={[styles.smallBtn, { backgroundColor: colors.primary }]}\r\n                    >\r\n                      {busyId === p.id\r\n                        ? <ActivityIndicator size=\"small\" color={brand.white} />\r\n                        : <><UserPlus size={13} color={brand.white} /><Text style={styles.smallBtnText}>Seguir</Text></>}\r\n                    </Pressable>\r\n                  ) : (\r\n                    <View style={[styles.smallBtn, { backgroundColor: alpha(colors.primary, 0.12) }]}>\r\n                      <Check size={13} color={colors.primary} />\r\n                      <Text style={[styles.smallBtnText, { color: colors.primary }]}>Siguiendo</Text>\r\n                    </View>\r\n                  )}\r\n                  <Pressable\r\n                    onPress={() => { onClose(); onOpenChat(p.id, p.name); }}\r\n                    style={[styles.smallBtn, { backgroundColor: colors.surface, borderWidth: 1, borderColor: colors.border }]}\r\n                  >\r\n                    <Text style={[styles.smallBtnText, { color: colors.textPrimary }]}>Mensaje</Text>\r\n                  </Pressable>\r\n                </>\r\n              }\r\n            />\r\n          ))}\r\n        </ScrollView>\r\n      )}\r\n    </Sheet>\r\n  );\r\n}\r\n\r\n\r\n/* ── 4. Escanear ── */\r\n\r\nexport function ScanSheet({ visible, onClose, onDocument, onQr }: {\r\n  visible: boolean; onClose: () => void; onDocument: () => void; onQr: () => void;\r\n}) {\r\n  const { colors } = useTheme();\r\n  return (\r\n    <Sheet visible={visible} onClose={onClose}>\r\n      <SheetHeader title=\"Escanear\" onClose={onClose} />\r\n      <Pressable onPress={() => { onClose(); onDocument(); }} style={[styles.optionRow, { backgroundColor: colors.surface }]}>\r\n        <FileScan size={18} color={colors.primary} />\r\n        <View style={{ flex: 1 }}>\r\n          <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Escanear documento</Text>\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Traducir un documento al español</Text>\r\n        </View>\r\n      </Pressable>\r\n      <Pressable onPress={() => { onClose(); onQr(); }} style={[styles.optionRow, { backgroundColor: colors.surface }]}>\r\n        <QrCode size={18} color={colors.textSecondary} />\r\n        <View style={{ flex: 1 }}>\r\n          <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Escanear QR de un amigo</Text>\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Necesita lector de QR y búsqueda por EG-ID (pendiente)</Text>\r\n        </View>\r\n      </Pressable>\r\n    </Sheet>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  backdrop: { ...StyleSheet.absoluteFillObject },\r\n  sheet: { ...formaHoja },\r\n  handle: { ...formaTirador },\r\n  sheetHeader: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginBottom: espaciado.e10 },\r\n  center: { alignItems: 'center', justifyContent: 'center' },\r\n  searchBox: { flexDirection: 'row', alignItems: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e12, height: 38, marginBottom: espaciado.e10 },\r\n  personRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth },\r\n  personAvatar: { width: 40, height: 40, borderRadius: 20 },\r\n  badge: { borderRadius: radios.full, minWidth: 18, height: 18, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e5 },\r\n  badgeText: { color: brand.white, fontSize: 10, fontWeight: '800' },\r\n  smallBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, minWidth: 78, justifyContent: 'center' },\r\n  smallBtnText: { color: brand.white, fontSize: tipografia.caption, fontWeight: '800' },\r\n  check: { width: 24, height: 24, borderRadius: radios.md, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center' },\r\n  notice: { borderRadius: radios.md, padding: espaciado.e10, marginBottom: espaciado.e10 },\r\n  titleInput: { borderRadius: radios.md, paddingHorizontal: espaciado.e12, height: 44, fontSize: 14.5, marginBottom: espaciado.e8 },\r\n  primaryBtn: { borderRadius: radios.full, paddingVertical: espaciado.e13, alignItems: 'center', marginTop: espaciado.e12 },\r\n  optionRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderRadius: 14, padding: espaciado.e14, marginBottom: espaciado.e8 },\r\n});\r\n","/**\n * PersonRow — fila de persona reutilizable (avatar o inicial, nombre,\n * subtítulo y acciones a la derecha). La usan las hojas de Mensajes, la\n * creación de grupos y la gestión de miembros.\n */\nimport React from 'react';\nimport { Image, StyleSheet, Text, View } from 'react-native';\nimport { alpha, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\n\nexport function PersonRow({ name, avatarUrl, subtitle, actions }: {\n  name: string; avatarUrl?: string | null; subtitle?: string; actions: React.ReactNode;\n}) {\n  const { colors } = useTheme();\n  return (\n    <View style={[styles.personRow, { borderBottomColor: alpha(colors.border, 0.5) }]}>\n      {avatarUrl ? (\n        <Image source={{ uri: avatarUrl }} style={styles.personAvatar} />\n      ) : (\n        <View style={[styles.personAvatar, styles.center, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n          <Text style={{ color: colors.primary, fontWeight: '900' }}>{name.trim().charAt(0).toUpperCase() || '?'}</Text>\n        </View>\n      )}\n      <View style={{ flex: 1 }}>\n        <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: '700', fontSize: tipografia.body }}>{name}</Text>\n        {subtitle ? <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{subtitle}</Text> : null}\n      </View>\n      <View style={{ flexDirection: 'row', gap: espaciado.e6 }}>{actions}</View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  personRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth },\n  personAvatar: { width: 40, height: 40, borderRadius: 20 },\n  center: { alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * CreateGroupSheet — hoja de crear grupo (versión ANTERIOR del dueño).\n *\n * ⚠️ SUSTITUIDA (2026-09-10): el flujo nuevo vive en la pantalla\n * `app/lifebook-group-create.tsx` (nombre → descripción → tipo de ruta →\n * punto de encuentro con buscador real → invitar → condición de ingreso →\n * creada). El icono «Crear grupo» de Mensajes abre esa pantalla.\n * Este archivo se conserva por si se quiere volver a la hoja; ya no se usa.\n *\n * Código del dueño aplicado tal cual. Lo que se ajustó para que compile aquí:\n *   · `Sheet`/`SheetHeader` importan de `./ui/Sheet` y `PersonRow` de\n *     `./PersonRow`.\n *   · `LbFollowerItem`/`LbSuggestedUser` entran como `import type`.\n *   · `e.code` funciona porque el cliente HTTP lanza `ApiError` con `code`.\n */\nimport React, { useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Image, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { Check, Search, Users, X } from 'lucide-react-native';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Sheet, SheetHeader } from './ui/Sheet';\nimport { PersonRow } from './PersonRow';\nimport { lifebookInboxApi, type LbFollowerItem, type LbSuggestedUser } from '../../api/lifebook';\nimport { LB_CITIES } from '../../constants/lifebook';\nimport type { LbGroupMeta } from '../../api/messages';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst MAX_MEMBERS = 199; // + tú = 200\n\nconst CATEGORIES = [\n  { id: 'food', label: 'Comida' }, { id: 'taxi', label: 'Taxi' },\n  { id: 'sales', label: 'Ventas' }, { id: 'culture', label: 'Cultura' },\n  { id: 'work', label: 'Trabajo' }, { id: 'rental', label: 'Alquiler' },\n  { id: 'sports', label: 'Deportes' }, { id: 'music', label: 'Música' },\n];\n\ninterface Person { id: string; name: string; avatarUrl?: string | null; note?: string }\n\ninterface Props {\n  visible: boolean;\n  onClose: () => void;\n  onCreate?: (title: string, members: string[], meta?: LbGroupMeta) => Promise<void> | void;\n}\n\nexport function CreateGroupSheet({ visible, onClose, onCreate }: Props) {\n  const { colors } = useTheme();\n\n  const [followers, setFollowers] = useState<Person[]>([]);\n  const [suggested, setSuggested] = useState<Person[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [picked, setPicked] = useState<string[]>([]);\n  const [title, setTitle] = useState('');\n  const [query, setQuery] = useState('');\n  const [busy, setBusy] = useState(false);\n  const [errText, setErrText] = useState<string | null>(null);\n\n  // ── Meta opcional (fase Xiaohongshu) ──\n  const [city, setCity] = useState<string | null>(null);\n  const [category, setCategory] = useState<string | null>(null);\n  const [visibility, setVisibility] = useState<LbGroupMeta['visibility']>('private');\n\n  useEffect(() => {\n    if (!visible) return;\n    setPicked([]); setTitle(''); setQuery(''); setErrText(null);\n    setCity(null); setCategory(null); setVisibility('private');\n    setFollowers([]); setSuggested([]); setLoading(true);\n\n    (async () => {\n      try {\n        const [f, s] = await Promise.all([\n          lifebookInboxApi.followers().catch(() => [] as LbFollowerItem[]),\n          lifebookInboxApi.suggested().catch(() => [] as LbSuggestedUser[]),\n        ]);\n        const seen = new Set<string>();\n        const toPerson = (x: any, note?: string): Person | null => {\n          const id = String(x.id ?? '');\n          if (!id || seen.has(id)) return null;\n          seen.add(id);\n          return { id, name: (x.fullName ?? x.name ?? 'Usuario').trim(), avatarUrl: x.avatarUrl, note };\n        };\n        setFollowers(f.map((x) => toPerson(x, 'Te sigue')).filter(Boolean) as Person[]);\n        setSuggested(s.map((x) => toPerson(x, x.reason ?? x.city)).filter(Boolean) as Person[]);\n      } catch {\n        setFollowers([]); setSuggested([]);\n      } finally { setLoading(false); }\n    })();\n  }, [visible]);\n\n  // ── Personas seleccionadas (para chips + avatar) ──\n  const pickedPeople = useMemo(() => {\n    const all = [...followers, ...suggested];\n    return picked\n      .map((id) => all.find((p) => p.id === id))\n      .filter(Boolean) as Person[];\n  }, [picked, followers, suggested]);\n\n  const filterList = (list: Person[]) =>\n    query.trim()\n      ? list.filter((p) =>\n          p.name.toLowerCase().includes(query.toLowerCase()) ||\n          (p.note ?? '').toLowerCase().includes(query.toLowerCase()))\n      : list;\n\n  const visibleFollowers = filterList(followers);\n  const visibleSuggested = filterList(suggested);\n\n  const toggle = (id: string) => {\n    setErrText(null);\n    setPicked((prev) => {\n      if (prev.includes(id)) return prev.filter((x) => x !== id);\n      if (prev.length >= MAX_MEMBERS) return prev;\n      return [...prev, id];\n    });\n  };\n\n  // Título sugerido si está vacío\n  const suggestedTitle = useMemo(() => {\n    if (pickedPeople.length === 0) return '';\n    const first = pickedPeople[0].name.split(' ')[0];\n    const cat = CATEGORIES.find((c) => c.id === category)?.label;\n    const parts = [cat, city].filter(Boolean).join(' · ');\n    return parts\n      ? `${parts} de ${first}`\n      : `Grupo de ${first} y ${pickedPeople.length} más`;\n  }, [pickedPeople, category, city]);\n\n  const canCreate = title.trim().length >= 3 && picked.length > 0 && !busy;\n\n  const submit = async () => {\n    if (!canCreate || !onCreate) return;\n    setBusy(true); setErrText(null);\n    try {\n      await onCreate(title.trim(), picked, {\n        city: city ?? undefined,\n        category: category ?? undefined,\n        visibility,\n      });\n      // el padre cierra el sheet en éxito\n    } catch (e: any) {\n      const code = e?.code ?? e?.response?.data?.code;\n      if (code === 'GROUP_TITLE_REQUIRED') setErrText('El nombre necesita al menos 3 letras.');\n      else if (code === 'GROUP_MEMBERS_REQUIRED') setErrText('Elige al menos a una persona.');\n      else setErrText(e?.message ?? 'No se pudo crear el grupo.');\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  return (\n    <Sheet visible={visible} onClose={onClose}>\n      <SheetHeader title=\"Crear grupo\" onClose={onClose} />\n\n      {/* ── Identidad del grupo (avatar + nombre) ── */}\n      <View style={styles.identity}>\n        <GroupAvatar people={pickedPeople} colors={colors} />\n        <View style={{ flex: 1 }}>\n          <TextInput\n            value={title} onChangeText={(t) => { setTitle(t); setErrText(null); }}\n            maxLength={90}\n            placeholder={suggestedTitle || 'Nombre del grupo (3–90 letras)'}\n            placeholderTextColor={colors.textSecondary}\n            style={[styles.titleInput, { backgroundColor: colors.surface, color: colors.textPrimary }]}\n          />\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\n            {picked.length + 1} / 200 miembros · {visibility === 'public' ? 'Grupo público' : 'Grupo privado'}\n          </Text>\n        </View>\n      </View>\n\n      {/* ── Chips de seleccionados ── */}\n      {pickedPeople.length > 0 && (\n        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: espaciado.e8 }}>\n          {pickedPeople.map((p) => (\n            <View key={p.id} style={[styles.chip, { backgroundColor: colors.surface }]}>\n              {p.avatarUrl ? (\n                <Image source={{ uri: p.avatarUrl }} style={styles.chipAvatar} />\n              ) : (\n                <View style={[styles.chipAvatar, { backgroundColor: alpha(colors.primary, 0.15) }]} />\n              )}\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '600' }} numberOfLines={1}>\n                {p.name.split(' ')[0]}\n              </Text>\n              <Pressable onPress={() => toggle(p.id)} hitSlop={6}>\n                <X size={12} color={colors.textSecondary} />\n              </Pressable>\n            </View>\n          ))}\n        </ScrollView>\n      )}\n\n      {/* ── Buscador ── */}\n      <View style={[styles.searchBox, { backgroundColor: colors.surface }]}>\n        <Search size={14} color={colors.textSecondary} />\n        <TextInput\n          value={query} onChangeText={setQuery}\n          placeholder=\"Buscar persona…\" placeholderTextColor={colors.textSecondary}\n          style={{ flex: 1, marginLeft: espaciado.e6, color: colors.textPrimary, fontSize: tipografia.body }}\n        />\n      </View>\n\n      {/* ── Contexto local (EG ROUTE PLAN) ── */}\n      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginTop: espaciado.e8 }}>\n        <View style={{ flexDirection: 'row', gap: espaciado.e6 }}>\n          {LB_CITIES.map((c) => {\n            const on = city === c;\n            return (\n              <Pressable key={c} onPress={() => setCity(on ? null : c)}\n                style={[styles.optChip, { backgroundColor: on ? colors.primary : colors.surface }]}>\n                <Text style={{ color: on ? brand.white : colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>{c}</Text>\n              </Pressable>\n            );\n          })}\n        </View>\n      </ScrollView>\n      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginTop: espaciado.e6 }}>\n        <View style={{ flexDirection: 'row', gap: espaciado.e6 }}>\n          {CATEGORIES.map((c) => {\n            const on = category === c.id;\n            return (\n              <Pressable key={c.id} onPress={() => setCategory(on ? null : c.id)}\n                style={[styles.optChip, { backgroundColor: on ? '#8B5CF6' : colors.surface }]}>\n                <Text style={{ color: on ? brand.white : colors.textSecondary, fontSize: tipografia.micro, fontWeight: '600' }}>{c.label}</Text>\n              </Pressable>\n            );\n          })}\n        </View>\n      </ScrollView>\n\n      {/* ── Lista de personas ── */}\n      {loading ? (\n        <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e24 }} />\n      ) : followers.length === 0 && suggested.length === 0 ? (\n        <Text style={{ color: colors.textSecondary, textAlign: 'center', paddingVertical: espaciado.e24, fontSize: tipografia.body }}>\n          No hay personas para invitar por ahora.\n        </Text>\n      ) : (\n        <ScrollView style={{ maxHeight: 260, marginTop: espaciado.e10 }} keyboardShouldPersistTaps=\"handled\">\n          {visibleFollowers.length > 0 && (\n            <Text style={[styles.sectionTitle, { color: colors.textSecondary }]}>Seguidores</Text>\n          )}\n          {visibleFollowers.map((p) => (\n            <SelectablePerson key={p.id} p={p} on={picked.includes(p.id)} onPress={() => toggle(p.id)} colors={colors} />\n          ))}\n          {visibleSuggested.length > 0 && (\n            <Text style={[styles.sectionTitle, { color: colors.textSecondary }]}>Sugeridos</Text>\n          )}\n          {visibleSuggested.map((p) => (\n            <SelectablePerson key={p.id} p={p} on={picked.includes(p.id)} onPress={() => toggle(p.id)} colors={colors} />\n          ))}\n        </ScrollView>\n      )}\n\n      {/* ── Error inline ── */}\n      {errText ? <Text style={{ color: brand.like, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>{errText}</Text> : null}\n\n      {/* ── Botón crear ── */}\n      <Pressable disabled={!canCreate} onPress={submit}\n        style={[styles.primaryBtn, { backgroundColor: canCreate ? colors.primary : alpha(colors.primary, 0.3) }]}>\n        {busy ? (\n          <ActivityIndicator size=\"small\" color={brand.white} />\n        ) : (\n          <Text style={{ color: brand.white, fontWeight: '900', fontSize: 14.5 }}>\n            Crear grupo{picked.length ? ` (${picked.length + 1})` : ''}\n          </Text>\n        )}\n      </Pressable>\n    </Sheet>\n  );\n}\n\n/* ── Avatar de grupo (collage local; la subida real se enchufa luego) ── */\nfunction GroupAvatar({ people, colors }: { people: Person[]; colors: any }) {\n  const show = people.slice(0, 4);\n  return (\n    <View style={[styles.groupAvatar, { backgroundColor: colors.surface }]}>\n      {show.length === 0 ? (\n        <Users size={22} color={colors.textSecondary} />\n      ) : (\n        <View style={styles.collage}>\n          {show.map((p) =>\n            p.avatarUrl ? (\n              <Image key={p.id} source={{ uri: p.avatarUrl }} style={styles.collageImg} />\n            ) : (\n              <View key={p.id} style={[styles.collageImg, { backgroundColor: alpha(colors.primary, 0.2) }]} />\n            ),\n          )}\n        </View>\n      )}\n    </View>\n  );\n}\n\n/* ── Fila seleccionable ── */\nfunction SelectablePerson({ p, on, onPress, colors }: {\n  p: Person; on: boolean; onPress: () => void; colors: any;\n}) {\n  return (\n    <Pressable onPress={onPress} style={({ pressed }) => ({ opacity: pressed ? 0.7 : 1 })}>\n      <PersonRow\n        name={p.name} avatarUrl={p.avatarUrl} subtitle={p.note}\n        actions={\n          <View style={[styles.check, {\n            borderColor: on ? colors.primary : colors.border,\n            backgroundColor: on ? colors.primary : 'transparent',\n          }]}>\n            {on ? <Check size={13} color={brand.white} /> : null}\n          </View>\n        }\n      />\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  identity: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, marginBottom: espaciado.e10 },\n  groupAvatar: {\n    width: 56, height: 56, borderRadius: radios.lg,\n    alignItems: 'center', justifyContent: 'center', overflow: 'hidden',\n  },\n  collage: { flexDirection: 'row', flexWrap: 'wrap', width: 48, justifyContent: 'center' },\n  collageImg: { width: 22, height: 22, borderRadius: 6, margin: 1 },\n  titleInput: { borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9, fontSize: tipografia.body, fontWeight: '700' },\n  chip: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e5,\n    borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4, marginRight: espaciado.e6,\n  },\n  chipAvatar: { width: 18, height: 18, borderRadius: 9 },\n  searchBox: {\n    flexDirection: 'row', alignItems: 'center', borderRadius: radios.full,\n    paddingHorizontal: espaciado.e12, height: 36, marginTop: espaciado.e8,\n  },\n  optChip: { borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6 },\n  sectionTitle: { fontSize: tipografia.micro, fontWeight: '800', textTransform: 'uppercase', marginTop: espaciado.e10, marginBottom: espaciado.e4, letterSpacing: 0.5 },\n  check: {\n    width: 20, height: 20, borderRadius: 10, borderWidth: 1.5,\n    alignItems: 'center', justifyContent: 'center',\n  },\n  primaryBtn: { borderRadius: radios.full, paddingVertical: espaciado.e13, alignItems: 'center', marginTop: espaciado.e12 },\n});\n","/**\n * app/lifebook-order/[id].tsx — DETALLE DEL PEDIDO (Parte 36).\n *\n * Construido sobre la pantalla del dueño, con los arreglos:\n *   · la cabecera depende del ESTADO (antes decía «Pedido realizado» con visto\n *     bueno verde incluso en un pedido cancelado);\n *   · barra de progreso con los estados reales;\n *   · el código de entrega solo lo ve el comprador (el servidor no se lo manda\n *     al vendedor) y se explica para qué sirve;\n *   · acciones por rol (vendedor: aceptar → preparar → enviar → entregar con\n *     código; comprador: cancelar o reclamar);\n *   · `lbXaf()`, `absUrl()`, `<AuthGate>`, área segura y refresco al enfocar.\n */\nimport React, { useCallback, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport * as ImagePicker from 'expo-image-picker';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AlertCircle, ArrowLeft, Camera, CheckCircle2, MessageCircle, Package, Truck } from 'lucide-react-native';\nimport { AuthGate } from '../../core/AuthGate';\nimport { absUrl } from '../../api/config';\nimport { lifebookMediaApi } from '../../api/lifebook';\nimport { messagesApi } from '../../api/messages';\nimport { commerceOrdersApi, type LbOrder } from '../../api/commerce';\nimport {\n  LB_COMMERCE_BUYER_ACTIONS, LB_ORDER_ACTION_LABEL, LB_ORDER_ACTION_LABEL_EXTRA, LB_ORDER_FLOW,\n  LB_ORDER_META, LB_SELLER_ORDER_ACTIONS, lbXaf,\n} from '../../constants/lifebook';\nimport { lbPayLabel, lbTransportLabel } from '../../constants/commerce';\nimport { Chip, ChipRow } from '../../components/lifebook/Chip';\nimport { Notice, SummaryRow } from '../../components/lifebook/publish/PublishParts';\n\nexport default function LifeBookOrderScreen() {\n  return (\n    <AuthGate>\n      <OrderContent />\n    </AuthGate>\n  );\n}\n\nfunction OrderContent() {\n  const { id } = useLocalSearchParams<{ id: string }>();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const [order, setOrder] = useState<LbOrder | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [code, setCode] = useState('');\n  const [notaCobro, setNotaCobro] = useState('');\n  const [justificante, setJustificante] = useState<string | null>(null);\n  const [subiendo, setSubiendo] = useState(false);\n  /**\n   * El justificante se mira DENTRO de la app, no en el navegador.\n   *\n   * Lo reportó el dueño: al pulsar «Ver el justificante» se abría una página de fuera que solo enseñaba\n   * el XML del almacenamiento (porque el enlace que usé en la prueba apuntaba a un fichero que no\n   * existía). Dos arreglos: (1) se enseña aquí dentro, con la foto; y (2) si el enlace no carga, se dice\n   * con palabras en vez de dejar al usuario en una página de error.\n   */\n  const [verJustificante, setVerJustificante] = useState(false);\n  const [justificanteFalla, setJustificanteFalla] = useState(false);\n  /** TANDA T (T.7): la valoración del pedido, que escribe el comprador una sola vez. */\n  const [estrellas, setEstrellas] = useState(0);\n  const [comentario, setComentario] = useState('');\n  /** TANDA T (T.7b): el motivo de la reclamación (obligatorio, mínimo 10 letras). */\n  const [motivoReclamo, setMotivoReclamo] = useState('');\n  /** El coste del reparto que la tienda escribe para cerrarlo (llega como texto del campo). */\n  const [costeReparto, setCosteReparto] = useState('');\n  const mounted = useRef(true);\n\n  const load = useCallback(async () => {\n    try {\n      const { order: o } = await commerceOrdersApi.detail(String(id));\n      if (mounted.current) { setOrder(o); setError(null); }\n    } catch (e) {\n      if (mounted.current) setError(e instanceof Error ? e.message : 'No se pudo cargar el pedido');\n    }\n  }, [id]);\n\n  // Se recarga al volver a la pantalla: el estado cambia en el servidor.\n  useFocusEffect(useCallback(() => {\n    mounted.current = true;\n    load();\n    return () => { mounted.current = false; };\n  }, [load]));\n\n  const accion = async (action: string) => {\n    if (!order || busy) return;\n    setBusy(action);\n    try {\n      const { order: o } = await commerceOrdersApi.action(order.id, action as never);\n      setOrder(o);\n    } catch (e) {\n      Alert.alert('Pedido', e instanceof Error ? e.message : 'No se pudo hacer la acción');\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  const confirmarCodigo = async () => {\n    if (!order || busy) return;\n    setBusy('code');\n    try {\n      const { order: o } = await commerceOrdersApi.confirmCode(order.id, code.trim());\n      setOrder(o);\n      setCode('');\n      Alert.alert('Entregado', 'Pedido entregado y cobrado.');\n    } catch (e) {\n      Alert.alert('Código de entrega', e instanceof Error ? e.message : 'El código no coincide');\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  /**\n   * EL JUSTIFICANTE DEL COBRO (TANDA R, R.5b).\n   *\n   * Se elige la foto y se sube YA, para no meter la imagen dentro de la petición del cobro. Si falla,\n   * se dice y no se pierde nada: el cobro se puede marcar sin justificante (puede no haber recibo).\n   */\n  const adjuntarJustificante = async () => {\n    try {\n      const perm = await ImagePicker.getMediaLibraryPermissionsAsync().catch(() => null);\n      if (perm && perm.granted === false) await ImagePicker.requestMediaLibraryPermissionsAsync().catch(() => null);\n      const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7, selectionLimit: 1 });\n      if (res.canceled || !res.assets?.[0]) return;\n      const asset = res.assets[0];\n      setSubiendo(true);\n      const up = await lifebookMediaApi.uploadFile('image', {\n        uri: asset.uri,\n        name: asset.fileName ?? `justificante-${Date.now()}.jpg`,\n        mimeType: asset.mimeType ?? 'image/jpeg',\n      });\n      setJustificante(up.url);\n    } catch (e) {\n      Alert.alert('Justificante', e instanceof Error ? e.message : 'No se pudo subir la foto');\n    } finally {\n      setSubiendo(false);\n    }\n  };\n\n  /**\n   * MARCAR COBRADO: para lo que se paga POR FUERA de la app (transferencia, facturación, depósito).\n   *\n   * Contra entrega y pago en tienda se cierran solos al entregar. Lo demás se quedaba «pendiente» para\n   * siempre: el vendedor no veía esa caja. El servidor guarda quién lo marca y cuándo, y avisa al\n   * comprador en el chat.\n   */\n  /**\n   * CERRAR EL COSTE DEL REPARTO (decisión del dueño: el envío tiene que entrar en el total).\n   *\n   * Cuando el envío está «a acordar» o «según la distancia», el pedido nace con reparto 0: ese dinero se\n   * movía por fuera y sin rastro. La tienda lo cierra ANTES de entregar, entra en el total y, al\n   * entregar, el libro de cuentas lo anota como `a_pagar_reparto`. El importe lo pone la tienda: el\n   * servidor no inventa tarifas.\n   */\n  const cerrarReparto = async () => {\n    if (!order || busy) return;\n    const valor = Number(String(costeReparto).replace(/[^0-9]/g, ''));\n    if (!Number.isFinite(valor) || valor <= 0) return;\n    setBusy('reparto');\n    try {\n      const { order: o } = await commerceOrdersApi.cerrarReparto(order.id, valor);\n      setOrder(o);\n      setCosteReparto('');\n      Alert.alert('Reparto cerrado', `El total del pedido queda en ${lbXaf(o.totalXaf)}.`);\n    } catch (e) {\n      Alert.alert('Reparto', e instanceof Error ? e.message : 'No se pudo cerrar el coste del reparto');\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  const marcarCobrado = async () => {\n    if (!order || busy) return;\n    setBusy('cobro');\n    try {\n      const { order: o } = await commerceOrdersApi.marcarCobrado(order.id, {\n        proofUrl: justificante,\n        note: notaCobro.trim() || null,\n      });\n      setOrder(o);\n      setNotaCobro('');\n      setJustificante(null);\n      Alert.alert('Cobrado', 'El pedido queda marcado como cobrado y el comprador recibe el aviso.');\n    } catch (e) {\n      Alert.alert('Cobro', e instanceof Error ? e.message : 'No se pudo marcar el cobro');\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  /**\n   * VALORAR EL PEDIDO (TANDA T, T.7).\n   *\n   * Una sola vez: lo impone el servidor con un índice único (`REVIEW_ALREADY_DONE` si se repite). La\n   * nota mueve la de la tienda y la de los productos del pedido, como media ponderada con los votos que\n   * ya había — por eso no se puede «cambiar de opinión» reenviando: sería falsear la media.\n   */\n  const enviarValoracion = async () => {\n    if (!order || busy || estrellas === 0) return;\n    setBusy('valorar');\n    try {\n      const { order: o } = await commerceOrdersApi.valorar(order.id, {\n        rating: estrellas,\n        comment: comentario.trim() || null,\n      });\n      setOrder(o);\n      setComentario('');\n      Alert.alert('Gracias', 'Tu valoración ya cuenta para la tienda y para el producto.');\n    } catch (e) {\n      Alert.alert('Valoración', e instanceof Error ? e.message : 'No se pudo enviar la valoración');\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  /**\n   * RECLAMAR EL PEDIDO (TANDA T, T.7b).\n   *\n   * El motivo es obligatorio en el servidor (mínimo 10 letras): una reclamación sin motivo no se puede\n   * atender, y el motivo es lo único que la tienda va a leer. Viaja en el aviso del chat.\n   */\n  const reclamar = async () => {\n    if (!order || busy || motivoReclamo.trim().length < 10) return;\n    setBusy('reclamar');\n    try {\n      const { order: o } = await commerceOrdersApi.action(order.id, 'dispute', motivoReclamo.trim());\n      setOrder(o);\n      setMotivoReclamo('');\n      Alert.alert('Reclamación abierta', 'La tienda recibe tu motivo en el chat del pedido.');\n    } catch (e) {\n      Alert.alert('Reclamación', e instanceof Error ? e.message : 'No se pudo abrir la reclamación');\n    } finally {\n      setBusy(null);\n    }\n  };\n\n  const hablar = async () => {\n    if (!order) return;\n    const otro = order.role === 'seller' ? order.buyer?.id : order.shop?.ownerId;\n    if (!otro) return;\n    /**\n     * ANTES DE ABRIR EL CHAT se deja ahí la TARJETA de ESTE pedido.\n     *\n     * Lo reportó el dueño: al pulsar «escribir a la tienda» no salía la tarjeta de la compra, así que\n     * el comerciante no sabía de qué pedido le hablaban (en una conversación con varias compras, o en\n     * un pedido anterior a la tarjeta). Si esto falla, se abre el chat igual: escribir importa más que\n     * la tarjeta.\n     */\n    const convId = await commerceOrdersApi.publicarTarjeta(order.id)\n      .then((r) => r?.conversationId ?? null)\n      .catch(() => null);\n    try {\n      const conv = convId ? { id: convId } : await messagesApi.open(otro);\n      router.push({\n        pathname: '/lifebook-chat/[id]',\n        params: {\n          id: conv.id,\n          name: order?.role === 'seller' ? (order?.buyer?.name ?? 'Comprador') : (order?.shop?.name ?? 'Tienda'),\n          peerId: otro,\n          draft: `Hola, sobre el pedido ${order?.code}…`,\n        },\n      } as never);\n    } catch { /* silencioso */ }\n  };\n\n  if (error && !order) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24, gap: espaciado.e12 }]}>\n        <AlertCircle size={34} color={colors.danger} />\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', textAlign: 'center' }}>{error}</Text>\n        <GhostButton title=\"Volver\" onPress={() => router.back()} />\n      </View>\n    );\n  }\n  if (!order) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  const meta = LB_ORDER_META[order.status] ?? { label: order.status, color: colors.textSecondary };\n  const esComprador = order.role === 'buyer';\n  const acciones = esComprador\n    ? (LB_COMMERCE_BUYER_ACTIONS[order.status] ?? [])\n    : (LB_SELLER_ORDER_ACTIONS[order.status] ?? []);\n  /**\n   * TANDA T (T.7b): la reclamación SALE de los chips y tiene su propia caja, porque necesita el motivo.\n   * Un chip que abre una reclamación sin explicar nada es lo que había antes.\n   */\n  const puedeReclamar = esComprador && acciones.includes('dispute');\n  const accionesSueltas = acciones.filter((a) => a !== 'dispute');\n  /**\n   * DECISIÓN DEL DUEÑO (18/09/2026): para **transferencia y facturación** el justificante es\n   * OBLIGATORIO. El servidor ya rechaza el cobro sin comprobante (`PAYMENT_PROOF_REQUIRED`); aquí el\n   * botón no deja ni intentarlo y dice qué falta, en vez de dejar pulsar y contestar con un aviso.\n   * Contra entrega y pago en tienda no se pide: el dinero se ve en mano.\n   */\n  const necesitaComprobante = order.paymentMethod === 'transfer' || order.paymentMethod === 'billing';\n  const pasoActual = LB_ORDER_FLOW.findIndex((f) => f.status === order.status);\n  const cancelado = order.status === 'cancelled' || order.status === 'declined';\n  const enDisputa = order.status === 'disputed';\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, marginLeft: espaciado.e10, flex: 1 }} numberOfLines={1}>\n          Pedido {order.code}\n        </Text>\n        <Text style={{ color: meta.color, fontWeight: '900', fontSize: tipografia.caption }}>{meta.label}</Text>\n      </View>\n\n      <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e24 }}>\n        {/* Cabecera según el ESTADO (no siempre «éxito») */}\n        <View style={{ alignItems: 'center', paddingVertical: espaciado.e6, gap: espaciado.e6 }}>\n          {cancelado ? <AlertCircle size={40} color={colors.danger} />\n            : enDisputa ? <AlertCircle size={40} color={colors.secondary} />\n              : order.status === 'delivered' ? <CheckCircle2 size={40} color={colors.success} />\n                : <Truck size={40} color={colors.primary} />}\n          <Text style={{ color: colors.textPrimary, fontSize: 18, fontWeight: '900' }}>\n            {cancelado ? 'Pedido cancelado' : enDisputa ? 'Pedido en reclamación'\n              : order.status === 'delivered' ? 'Pedido entregado' : 'Tu pedido está en marcha'}\n          </Text>\n          {esComprador ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Compra en {order.shop?.name ?? 'la tienda'}</Text>\n          ) : (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Compra de {order.buyer?.name ?? 'un cliente'}</Text>\n          )}\n        </View>\n\n        {/* Barra de progreso */}\n        {!cancelado && !enDisputa ? (\n          <View style={styles.flow}>\n            {LB_ORDER_FLOW.map((f, i) => {\n              const activo = pasoActual >= i;\n              return (\n                <View key={f.status} style={{ flex: 1, alignItems: 'center', gap: espaciado.e5 }}>\n                  <View style={[styles.dot, { backgroundColor: activo ? colors.primary : alpha(colors.border, 0.8) }]} />\n                  <Text numberOfLines={2} style={{ color: activo ? colors.textPrimary : colors.textSecondary, fontSize: 9.5, fontWeight: '700', textAlign: 'center' }}>\n                    {f.label}\n                  </Text>\n                </View>\n              );\n            })}\n          </View>\n        ) : null}\n\n        {/* Código de entrega: SOLO el comprador lo recibe */}\n        {esComprador && order.deliveryCode ? (\n          <View style={[styles.codeBox, { borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.06) }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, textAlign: 'center' }}>\n              Lee este código a quien te entregue y paga en efectivo:\n            </Text>\n            <Text style={{ color: colors.primary, fontSize: 34, fontWeight: '900', letterSpacing: 8 }}>{order.deliveryCode}</Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, textAlign: 'center' }}>\n              La tienda lo confirma y el pedido queda entregado y cobrado.\n            </Text>\n          </View>\n        ) : null}\n\n        {/* Vendedor: confirmar el código que le da el comprador */}\n        {!esComprador && order.paymentMethod === 'cash_on_delivery' && order.status !== 'delivered' && !cancelado ? (\n          <View style={[styles.codeBox, { borderColor: alpha(colors.border, 0.9) }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', textAlign: 'center' }}>\n              Cobro en efectivo: pide al comprador su código de 4 dígitos\n            </Text>\n            <TextInput\n              value={code}\n              onChangeText={(v) => setCode(v.replace(/\\D/g, '').slice(0, 4))}\n              keyboardType=\"number-pad\"\n              placeholder=\"0000\"\n              placeholderTextColor={colors.textSecondary}\n              style={[styles.codeInput, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n            />\n            <PrimaryButton title=\"Confirmar entrega y cobro\" loading={busy === 'code'} disabled={code.length !== 4} onPress={confirmarCodigo} />\n          </View>\n        ) : null}\n\n        {order.note ? <Notice>{order.note}</Notice> : null}\n\n        {/* Artículos */}\n        <Text style={[styles.section, { color: colors.textPrimary }]}>Artículos</Text>\n        <View style={[styles.card, { borderColor: alpha(colors.border, 0.6) }]}>\n          {order.items.map((it) => (\n            <View key={it.id} style={styles.itemRow}>\n              {it.mediaUrl ? (\n                <Image source={absUrl(it.mediaUrl)} style={styles.thumb} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n              ) : (\n                <View style={[styles.thumb, { backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }]}>\n                  <Package size={18} color={alpha(colors.primary, 0.6)} />\n                </View>\n              )}\n              <View style={{ flex: 1 }}>\n                <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{it.titleSnapshot}</Text>\n                {it.variantSnapshot ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{it.variantSnapshot}</Text> : null}\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{it.quantity} × {lbXaf(it.unitPriceXaf)}</Text>\n              </View>\n              <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.caption }}>{lbXaf(it.lineTotalXaf)}</Text>\n            </View>\n          ))}\n          <SummaryRow label=\"Subtotal\" value={lbXaf(order.subtotalXaf)} />\n          <SummaryRow label={`Entrega (${lbTransportLabel(order.deliveryMode)})`} value={order.deliveryCostXaf > 0 ? lbXaf(order.deliveryCostXaf) : 'A acordar'} />\n          {/* TANDA Q: el cupón, con su código. Se ve de dónde sale el total. */}\n          {order.discountXaf > 0 ? (\n            <SummaryRow label={`Cupón${order.couponCode ? ` ${order.couponCode}` : ''}`} value={`−${lbXaf(order.discountXaf)}`} />\n          ) : null}\n          <SummaryRow label=\"Total\" value={lbXaf(order.totalXaf)} />\n          <SummaryRow label=\"Pago\" value={lbPayLabel(order.paymentMethod)} />\n          {/* TANDA R (R.5b): el cobro, en la misma ficha que el resto del dinero (una línea, no tres). */}\n          {order.paymentStatus === 'paid' ? (\n            <SummaryRow label=\"Cobrado\" value={order.paidAt ? new Date(order.paidAt).toLocaleDateString() : 'sí'} />\n          ) : null}\n        </View>\n\n        {/* Con qué se dio por cobrado: la referencia de la tienda y el justificante. Lo ven las dos partes. */}\n        {order.paymentStatus === 'paid' && order.paymentNote ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>Cobro: {order.paymentNote}</Text>\n        ) : null}\n        {order.paymentStatus === 'paid' && order.paymentProofUrl ? (\n          <Pressable\n            onPress={() => { setJustificanteFalla(false); setVerJustificante(true); }}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Ver el justificante del cobro\"\n          >\n            <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6 }}>Ver el justificante</Text>\n          </Pressable>\n        ) : null}\n\n        {/* TANDA T (T.7b): la reclamación y su motivo, para que lo vean los dos. */}\n        {order.disputeReason ? (\n          <View style={{ marginTop: espaciado.e8 }}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              {esComprador ? 'Tu reclamación' : 'Reclamación del comprador'}\n            </Text>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption }}>«{order.disputeReason}»</Text>\n          </View>\n        ) : null}\n\n        {/* TANDA T (T.7): la valoración, si ya está escrita. La ven el comprador y la tienda. */}\n        {order.review ? (\n          <View style={{ marginTop: espaciado.e8 }}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              {esComprador ? 'Tu valoración' : 'Valoración del comprador'}:{' '}\n              <Text style={{ color: brand.warning, fontSize: tipografia.body }}>\n                {'★'.repeat(order.review.rating)}{'☆'.repeat(5 - order.review.rating)}\n              </Text>\n            </Text>\n            {order.review.comment ? (\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>«{order.review.comment}»</Text>\n            ) : null}\n          </View>\n        ) : null}\n\n        {/* Entrega */}\n        {order.deliveryMode !== 'pickup' && (order.deliveryAddress?.zone || order.deliveryAddress?.reference) ? (\n          <>\n            <Text style={[styles.section, { color: colors.textPrimary }]}>Entrega</Text>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption }}>\n              {[order.deliveryAddress?.city, order.deliveryAddress?.zone, order.deliveryAddress?.reference].filter(Boolean).join(' · ')}\n            </Text>\n          </>\n        ) : (\n          <>\n            <Text style={[styles.section, { color: colors.textPrimary }]}>Recogida</Text>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption }}>\n              En la tienda {order.shop?.name ? `«${order.shop.name}»` : ''} · acuerda la hora por el chat\n            </Text>\n          </>\n        )}\n\n        {/* Acciones */}\n        {accionesSueltas.length > 0 ? (\n          <>\n            <Text style={[styles.section, { color: colors.textPrimary }]}>{esComprador ? '¿Qué quieres hacer?' : 'Gestiona el pedido'}</Text>\n            <ChipRow>\n              {accionesSueltas.map((a) => (\n                <Chip\n                  key={a}\n                  label={LB_ORDER_ACTION_LABEL[a] ?? LB_ORDER_ACTION_LABEL_EXTRA[a] ?? a}\n                  onPress={() => accion(a)}\n                  disabled={!!busy}\n                />\n              ))}\n            </ChipRow>\n          </>\n        ) : null}\n\n        {/*\n          TANDA T (T.7b) — RECLAMAR, CON MOTIVO.\n          Antes era un chip que cambiaba el estado sin guardar por qué: la tienda veía «en reclamación» y\n          no sabía qué contestar. El servidor exige ahora al menos 10 letras, así que el botón se apaga\n          hasta que se escriban (y dice por qué).\n        */}\n        {puedeReclamar ? (\n          <View style={[styles.codeBox, { borderColor: alpha(colors.border, 0.9), alignItems: 'stretch', marginTop: espaciado.e16 }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800', textAlign: 'center' }}>\n              ¿Algo ha ido mal?\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n              Cuéntanoslo y la tienda lo recibe en el chat. Una reclamación sin motivo no se puede atender.\n            </Text>\n            <TextInput\n              value={motivoReclamo}\n              onChangeText={setMotivoReclamo}\n              placeholder=\"Qué ha pasado (mínimo 10 letras)\"\n              placeholderTextColor={colors.textSecondary}\n              multiline\n              style={[styles.notaInput, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface, minHeight: 58 }]}\n            />\n            <PrimaryButton\n              title={motivoReclamo.trim().length < 10 ? `Escribe el motivo (${motivoReclamo.trim().length}/10)` : 'Reclamar el pedido'}\n              loading={busy === 'reclamar'}\n              disabled={!!busy || motivoReclamo.trim().length < 10}\n              onPress={reclamar}\n            />\n          </View>\n        ) : null}\n\n        {/*\n          DECISIÓN DEL DUEÑO — CERRAR EL COSTE DEL REPARTO ANTES DE ENTREGAR.\n          Si la tienda tiene el envío «a acordar» o «según la distancia», el pedido nace con reparto 0:\n          ese dinero se movía por fuera y sin rastro. Aquí lo cierra, entra en el total y el libro de\n          cuentas lo anota como `a_pagar_reparto`. Solo la tienda, y no si el pedido ya está cobrado,\n          entregado, cancelado o en reclamación (lo impone el servidor).\n        */}\n        {!esComprador && !cancelado && !enDisputa && order.status !== 'delivered'\n          && order.deliveryMode !== 'pickup' && order.paymentStatus !== 'paid' ? (\n          <View style={[styles.codeBox, { borderColor: alpha(colors.border, 0.9), alignItems: 'stretch', marginTop: espaciado.e16 }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800', textAlign: 'center' }}>\n              El reparto ({lbTransportLabel(order.deliveryMode)})\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n              {order.deliveryCostXaf > 0\n                ? `Ahora el comprador paga ${lbXaf(order.deliveryCostXaf)} de reparto. Puedes cambiarlo antes de entregar.`\n                : 'Todavía no está cerrado: el comprador paga el pedido sin el reparto. Ciérralo antes de entregar.'}\n            </Text>\n            <TextInput\n              value={costeReparto}\n              onChangeText={(v) => setCosteReparto(v.replace(/\\D/g, '').slice(0, 6))}\n              keyboardType=\"number-pad\"\n              placeholder={order.deliveryCostXaf > 0 ? String(order.deliveryCostXaf) : 'Coste del reparto en XAF'}\n              placeholderTextColor={colors.textSecondary}\n              style={[styles.notaInput, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n            />\n            <PrimaryButton\n              title={Number(costeReparto) > 0 ? `Cerrar el reparto en ${lbXaf(Number(costeReparto))}` : 'Escribe el coste del reparto'}\n              loading={busy === 'reparto'}\n              disabled={!!busy || !(Number(costeReparto) > 0)}\n              onPress={cerrarReparto}\n            />\n          </View>\n        ) : null}\n\n        {/*\n          TANDA R (R.5b) — LA TIENDA MARCA COBRADO LO QUE SE PAGA POR FUERA.\n          Una transferencia, una facturación o un depósito no pasan por la app: antes se quedaban\n          «pendiente» para siempre y esa caja no se veía en ningún sitio. Aquí se cierra, con el\n          justificante y la referencia, y queda con quién lo marcó y cuándo.\n          VA DESPUÉS DE LAS ACCIONES a propósito: aceptar/preparar/entregar son lo principal y no se\n          pueden quedar debajo del pliegue por una caja secundaria.\n        */}\n        {!esComprador && !cancelado && !enDisputa && order.paymentStatus !== 'paid' ? (\n          <View style={[styles.codeBox, { borderColor: alpha(colors.border, 0.9), alignItems: 'stretch', marginTop: espaciado.e16 }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800', textAlign: 'center' }}>\n              ¿Ya te han pagado? ({lbPayLabel(order.paymentMethod)})\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n              Si el dinero ha entrado por fuera de la app, márcalo aquí. El comprador recibe el aviso y\n              los dos podéis ver con qué se dio por cobrado.\n            </Text>\n            <TextInput\n              value={notaCobro}\n              onChangeText={setNotaCobro}\n              placeholder=\"Referencia del cobro (ej.: transferencia BGFI 99123)\"\n              placeholderTextColor={colors.textSecondary}\n              style={[styles.notaInput, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n            />\n            <Pressable\n              onPress={adjuntarJustificante}\n              disabled={subiendo || !!busy}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Adjuntar el justificante del cobro\"\n              style={[styles.adjunto, { borderColor: alpha(colors.border, 0.9) }]}\n            >\n              <Camera size={16} color={colors.textPrimary} />\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', flex: 1 }} numberOfLines={1}>\n                {subiendo ? 'Subiendo la foto…'\n                  : justificante ? 'Comprobante adjunto ✓'\n                    : necesitaComprobante ? 'Adjuntar el comprobante (obligatorio)'\n                      : 'Adjuntar justificante (opcional)'}\n              </Text>\n            </Pressable>\n            <PrimaryButton\n              title={necesitaComprobante && !justificante ? 'Hace falta el comprobante' : 'Marcar cobrado'}\n              loading={busy === 'cobro'}\n              disabled={!!busy || subiendo || (necesitaComprobante && !justificante)}\n              onPress={marcarCobrado}\n            />\n          </View>\n        ) : null}\n\n        {/*\n          TANDA T (T.7) — VALORAR EL PEDIDO.\n          Solo el comprador, solo si está ENTREGADO y solo una vez (lo impone el servidor). La nota mueve\n          la de la tienda y la del producto: `rating` y `rating_count` existían desde siempre y no los\n          escribía nadie.\n        */}\n        {esComprador && order.status === 'delivered' && !order.review ? (\n          <View style={[styles.codeBox, { borderColor: alpha(colors.border, 0.9), alignItems: 'stretch', marginTop: espaciado.e16 }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800', textAlign: 'center' }}>\n              ¿Cómo fue la compra?\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n              Tu nota cuenta para la tienda y para el producto. Solo se puede valorar una vez.\n            </Text>\n            <View style={{ flexDirection: 'row', justifyContent: 'center', gap: espaciado.e4, marginVertical: espaciado.e2 }}>\n              {[1, 2, 3, 4, 5].map((n) => (\n                <Pressable\n                  key={n}\n                  onPress={() => setEstrellas(n)}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`Valorar con ${n} de 5`}\n                  style={styles.estrella}\n                >\n                  <Text style={{ fontSize: 30, color: n <= estrellas ? brand.warning : colors.textSecondary }}>\n                    {n <= estrellas ? '★' : '☆'}\n                  </Text>\n                </Pressable>\n              ))}\n            </View>\n            <TextInput\n              value={comentario}\n              onChangeText={setComentario}\n              placeholder=\"¿Quieres contar algo? (opcional)\"\n              placeholderTextColor={colors.textSecondary}\n              multiline\n              style={[styles.notaInput, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface, minHeight: 58 }]}\n            />\n            <PrimaryButton\n              title=\"Enviar valoración\"\n              loading={busy === 'valorar'}\n              disabled={!!busy || estrellas === 0}\n              onPress={enviarValoracion}\n            />\n          </View>\n        ) : null}\n\n        <View style={{ marginTop: espaciado.e18 }}>\n          <GhostButton title={esComprador ? 'Escribir a la tienda' : 'Escribir al comprador'} onPress={hablar} />\n        </View>\n      </ScrollView>\n\n      {/*\n        EL JUSTIFICANTE, AQUÍ DENTRO (TANDA S).\n        Antes se abría el navegador con el enlace y, si el enlace no existía, el usuario acababa en una\n        página que solo enseñaba el XML del almacenamiento. Ahora se ve la foto en la app y, si no carga,\n        se dice con palabras.\n      */}\n      <Modal visible={verJustificante} transparent animationType=\"fade\" onRequestClose={() => setVerJustificante(false)}>\n        <View style={styles.modalFondo}>\n          <Pressable style={StyleSheet.absoluteFill} onPress={() => setVerJustificante(false)} accessibilityLabel=\"Cerrar el justificante\" />\n          <Text style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '800' }}>Justificante del cobro</Text>\n          {order.paymentProofUrl ? (\n            justificanteFalla ? (\n              <Text style={{ color: brand.white, fontSize: tipografia.body, textAlign: 'center', paddingHorizontal: espaciado.e24 }}>\n                No se pudo cargar el justificante.{'\\n'}La tienda lo tiene en su teléfono.\n              </Text>\n            ) : (\n              <Image\n                source={absUrl(order.paymentProofUrl)}\n                style={styles.justificante}\n                contentFit=\"contain\"\n                transition={120}\n                onError={() => setJustificanteFalla(true)}\n              />\n            )\n          ) : null}\n          <Pressable onPress={() => setVerJustificante(false)} style={styles.cerrarModal} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar\">\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Cerrar</Text>\n          </Pressable>\n        </View>\n      </Modal>\n\n      <View style={[styles.footer, { paddingBottom: insets.bottom + 10, borderTopColor: alpha(colors.border, 0.5), backgroundColor: colors.background }]}>\n        <View style={{ flex: 1 }}>\n          <GhostButton title=\"Mis pedidos\" onPress={() => router.replace('/lifebook-orders' as never)} />\n        </View>\n        <View style={{ flex: 1 }}>\n          <PrimaryButton title=\"Ver la tienda\" onPress={() => order.shop && router.push({ pathname: '/lifebook-shop/[id]', params: { id: order.shop.id } } as never)} />\n        </View>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  flow: { flexDirection: 'row', marginTop: espaciado.e14, marginBottom: espaciado.e6 },\n  dot: { width: 10, height: 10, borderRadius: 5 },\n  codeBox: { borderWidth: 1.5, borderRadius: 14, padding: espaciado.e14, marginTop: espaciado.e10, gap: espaciado.e8, alignItems: 'center' },\n  codeInput: {\n    borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8,\n    fontSize: 22, fontWeight: '900', letterSpacing: 8, textAlign: 'center', width: 140,\n  },\n  /** TANDA R (R.5b): la referencia del cobro y el botón del justificante. */\n  notaInput: {\n    borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9, fontSize: tipografia.body,\n  },\n  adjunto: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderWidth: 1, borderRadius: 10,\n    paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10,\n  },\n  /** TANDA T (T.7): una estrella de la valoración (se toca para puntuar). */\n  estrella: { paddingHorizontal: espaciado.e3 },\n  /** El visor del justificante (TANDA S): oscuro, la foto entera y un botón para cerrar. */\n  modalFondo: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e12, padding: espaciado.e20, backgroundColor: 'rgba(0,0,0,0.92)' },\n  justificante: { width: '100%', height: '74%', borderRadius: radios.md },\n  cerrarModal: {\n    borderWidth: 1, borderColor: 'rgba(255,255,255,0.45)', borderRadius: 10,\n    paddingHorizontal: espaciado.e20, paddingVertical: espaciado.e10,\n  },\n  section: { fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e20, marginBottom: espaciado.e8 },\n  card: { borderWidth: StyleSheet.hairlineWidth, borderRadius: 14, padding: espaciado.e12 },\n  itemRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, marginBottom: espaciado.e10 },\n  thumb: { width: 48, height: 48, borderRadius: radios.sm },\n  footer: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10, borderTopWidth: StyleSheet.hairlineWidth,\n  },\n});\n","/**\n * Life Book — PEDIDOS (/lifebook-orders?side=buyer|seller).\n * Pestañas Compras/Ventas con estado, precio, contraparte y acciones\n * (vendedor: aceptar/rechazar → enviar → entregar; comprador: cancelar/disputar),\n * más \"Ver anuncio\" y \"Hablar\" con la contraparte.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, Image, Pressable, StyleSheet, Text, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, EmptyState, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, MessageCircle, PackageOpen, ShoppingBag, Store } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookOrdersApi, lifebookChatApi, type LbOrder } from '../api/lifebook';\nimport { commerceOrdersApi, type LbOrderCard } from '../api/commerce';\nimport { LB_ORDER_META, LB_ORDER_ACTIONS, LB_ORDER_BUYER_ACTIONS, LB_ORDER_ACTION_LABEL, lbXaf } from '../constants/lifebook';\nimport FloatingFooter, { DOCK_BODY_H } from '../components/FloatingFooter';\nimport { useAppDock } from '../core/useAppDock';\nimport { ir as irSeguro } from '../constants/rutas';\n\nexport default function OrdersScreen() {\n  return (\n    <AuthGate>\n      <OrdersContent />\n    </AuthGate>\n  );\n}\n\nfunction OrdersContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const p = useLocalSearchParams<{ side?: string }>();\n  const [side, setSide] = useState<'buyer' | 'seller'>(p.side === 'seller' ? 'seller' : 'buyer');\n  const [orders, setOrders] = useState<LbOrder[] | null>(null);\n  // Parte 36: pedidos del COMERCIO (carrito/tienda) — van arriba de la lista.\n  const [comercio, setComercio] = useState<LbOrderCard[]>([]);\n  const [busyId, setBusyId] = useState<string | null>(null);\n  const dock = useAppDock();\n\n  const load = useCallback(async () => {\n    try { setOrders(await lifebookOrdersApi.mine(side)); }\n    catch { setOrders([]); }\n    try {\n      const page = await commerceOrdersApi.mine(side);\n      setComercio(page.orders ?? []);\n    } catch { setComercio([]); }\n  }, [side]);\n  useEffect(() => { load(); }, [load]);\n\n  const act = async (order: LbOrder, action: string) => {\n    setBusyId(order.id);\n    try {\n      await lifebookOrdersApi.action(order.id, action);\n      await load();\n    } catch (e) {\n      Alert.alert('Pedidos', e instanceof Error ? e.message : 'No se pudo cambiar el estado.');\n    } finally { setBusyId(null); }\n  };\n\n  const talk = async (order: LbOrder) => {\n    try {\n      const otherId = side === 'buyer' ? order.seller.id : order.buyer.id;\n      const otherName = side === 'buyer' ? order.seller.fullName : order.buyer.fullName;\n      const conv = await lifebookChatApi.open(otherId);\n      irSeguro.libre('/lifebook-chat/[id]', { id: conv.id, name: otherName ?? 'Chat' });\n    } catch { Alert.alert('Mensajes', 'No se pudo abrir la conversación.'); }\n  };\n\n  const allowed = (order: LbOrder) => side === 'seller' ? (LB_ORDER_ACTIONS[order.status] ?? []) : (LB_ORDER_BUYER_ACTIONS[order.status] ?? []);\n  const otherOf = (o: LbOrder) => (side === 'buyer' ? o.seller : o.buyer);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Pedidos</Text>\n        {/* Parte 39: desde Ventas se entra directo al panel de la tienda. */}\n        {side === 'seller' ? (\n          <Pressable\n            onPress={() => irSeguro.libre('/lifebook-merchant')}\n            hitSlop={8}\n            accessibilityLabel=\"Panel de mi tienda\"\n            style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, backgroundColor: alpha(colors.primary, 0.12), borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5 }}\n          >\n            <Store size={13} color={colors.primary} />\n            <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '900' }}>Mi tienda</Text>\n          </Pressable>\n        ) : null}\n        <View style={{ flexDirection: 'row', backgroundColor: colors.surface, borderRadius: radios.full, padding: espaciado.e3 }}>\n          {(['buyer', 'seller'] as const).map((s) => (\n            <Pressable key={s} onPress={() => setSide(s)} style={[styles.seg, { backgroundColor: side === s ? colors.primary : 'transparent' }]}>\n              <Text style={{ color: side === s ? brand.white : colors.textSecondary, fontWeight: '900', fontSize: tipografia.caption }}>{s === 'buyer' ? 'Compras' : 'Ventas'}</Text>\n            </Pressable>\n          ))}\n        </View>\n      </View>\n\n      {orders === null ? (\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        <FlatList\n          data={orders}\n          keyExtractor={(o) => o.id}\n          ListHeaderComponent={\n            comercio.length ? (\n              <View style={{ paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e6 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e10, marginBottom: espaciado.e8 }}>\n                  Pedidos de tienda\n                </Text>\n                {comercio.map((o) => {\n                  const meta = LB_ORDER_META[o.status] ?? { label: o.status, color: colors.textSecondary };\n                  return (\n                    <Pressable\n                      key={o.id}\n                      onPress={() => irSeguro.libre('/lifebook-order/[id]', { id: o.id })}\n                      accessibilityLabel={`Pedido ${o.code}`}\n                      style={[styles.commerceCard, { borderColor: colors.border, backgroundColor: colors.surface }]}\n                    >\n                      {o.mediaUrl ? (\n                        <Image source={{ uri: absUrl(o.mediaUrl) }} style={styles.commerceThumb} />\n                      ) : (\n                        <View style={[styles.commerceThumb, { backgroundColor: colors.card }]} />\n                      )}\n                      <View style={{ flex: 1 }}>\n                        <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                          {o.code} · {o.title}\n                        </Text>\n                        <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                          {side === 'buyer' ? (o.shop?.name ?? 'Tienda') : (o.buyer?.name ?? 'Cliente')}\n                          {' · '}{o.itemsCount} artículo{o.itemsCount === 1 ? '' : 's'}\n                        </Text>\n                        <Text style={{ color: meta.color, fontSize: tipografia.caption, fontWeight: '900', marginTop: espaciado.e3 }}>{meta.label}</Text>\n                      </View>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>{lbXaf(o.totalXaf)}</Text>\n                    </Pressable>\n                  );\n                })}\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e14, marginBottom: espaciado.e6 }}>\n                  Pedidos de publicaciones\n                </Text>\n              </View>\n            ) : null\n          }\n          contentContainerStyle={{ padding: espaciado.e14, paddingBottom: DOCK_BODY_H + insets.bottom + 20, flexGrow: 1 }}\n          refreshing={false}\n          onRefresh={load}\n          ListEmptyComponent={\n            <EmptyState\n              icono={<PackageOpen size={42} color={alpha(colors.primary, 0.45)} />}\n              titulo={side === 'buyer' ? 'Aún no has comprado nada' : 'Aún no tienes ventas'}\n              texto={side === 'buyer'\n                ? 'Cuando pidas un producto del feed aparecerá aquí, con su estado y lo que puedes hacer.'\n                : 'Cuando alguien pida tu producto aparecerá aquí, con su estado y lo que puedes hacer.'}\n            />\n          }\n          ItemSeparatorComponent={() => <View style={{ height: 10 }} />}\n          renderItem={({ item }) => {\n            const meta = LB_ORDER_META[item.status] ?? { label: item.status, color: colors.textSecondary };\n            const other = otherOf(item);\n            const actions = allowed(item);\n            return (\n              <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\n                  {item.media?.[0] ? (\n                    <Pressable onPress={() => irSeguro.libre('/lifebook-post/[id]', { id: item.postId })}>\n                      <Image source={{ uri: absUrl(item.media[0].url) }} style={[styles.thumb, { backgroundColor: colors.surface }]} />\n                    </Pressable>\n                  ) : (\n                    <View style={[styles.thumb, { backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center' }]}>\n                      <ShoppingBag size={20} color={colors.textSecondary} />\n                    </View>\n                  )}\n                  <View style={{ flex: 1 }}>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: espaciado.e6 }}>\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '800' }}>{item.orderNo}</Text>\n                      <View style={{ backgroundColor: alpha(meta.color, 0.13), borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 }}>\n                        <Text style={{ color: meta.color, fontSize: 10.5, fontWeight: '900' }}>{meta.label}</Text>\n                      </View>\n                    </View>\n                    <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '900', marginTop: espaciado.e3 }}>\n                      {item.title ?? 'Producto'}\n                    </Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                      {lbXaf(item.priceXaf)}{item.negotiable ? ' · negociable' : ''} · con {other.fullName ?? 'usuario'}\n                    </Text>\n                  </View>\n                </View>\n                {item.message ? (\n                  <Text numberOfLines={2} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8, backgroundColor: colors.surface, borderRadius: 10, padding: espaciado.e8 }}>\n                    💬 “{item.message}”\n                  </Text>\n                ) : null}\n                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e10 }}>\n                  {actions.map((a) => (\n                    <Pressable key={a} onPress={() => act(item, a)} disabled={busyId === item.id} style={[styles.actBtn, { backgroundColor: colors.primary }]}>\n                      {busyId === item.id\n                        ? <ActivityIndicator size=\"small\" color={brand.white} />\n                        : <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>{LB_ORDER_ACTION_LABEL[a] ?? a}</Text>}\n                    </Pressable>\n                  ))}\n                  <Pressable onPress={() => irSeguro.libre('/lifebook-post/[id]', { id: item.postId })} style={[styles.actBtn, { backgroundColor: colors.surface, borderColor: colors.border, borderWidth: 1 }]}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>Ver anuncio</Text>\n                  </Pressable>\n                  <Pressable onPress={() => talk(item)} style={[styles.actBtn, { backgroundColor: colors.surface, borderColor: colors.border, borderWidth: 1 }]}>\n                    <MessageCircle size={13} color={colors.textPrimary} />\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>Hablar</Text>\n                  </Pressable>\n                </View>\n              </View>\n            );\n          }}\n        />\n      )}\n\n      <FloatingFooter onNavigate={dock} showUnreadBadge />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  commerceCard: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    borderWidth: StyleSheet.hairlineWidth, borderRadius: radios.md, padding: espaciado.e10, marginBottom: espaciado.e8,\n  },\n  commerceThumb: { width: 44, height: 44, borderRadius: radios.sm },\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: 19, fontWeight: '900', flex: 1 },\n  seg: { borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e6 },\n  card: { borderRadius: radios.lg, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e12 },\n  thumb: { width: 62, height: 62, borderRadius: radios.md },\n  actBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, borderRadius: radios.full, paddingHorizontal: espaciado.e13, paddingVertical: espaciado.e7 },\n});\n\n","/**\n * Life Book — REPRODUCTOR DE AUDIO (/lifebook-player).\n *\n * **En este fichero ya sólo vive el AUDIO** (`expo-audio`: ±15 s, velocidad, progreso).\n * DISEÑO-UX-LIFEBOOK-AUDIOVISUAL módulos 1-2.\n *\n * ── EL REPRODUCTOR DE VÍDEO SE RETIRÓ (2026-09-13) ──────────────────────────\n * Historia completa, porque explica por qué ya no está:\n *\n * 1. Empezó usando `nativeControls` de `expo-video`. Al probarlo, el dueño pidió que los\n *    botones del CENTRO desaparecieran (el retroceso/avance de ExoPlayer y su ±5 s/±15 s\n *    por defecto): quería SOLO play/pausa. `nativeControls` es todo o nada, así que hubo\n *    que pintar controles propios.\n * 2. En la segunda pasada pidió fuera también los ±15 s propios («sólo debe quedar la de\n *    play»). Se quitaron, y tenía razón de diseño: con la barra de progreso justo debajo,\n *    que se arrastra con el dedo, dos botones de salto son un tercer camino para lo mismo.\n * 3. Y en la tercera pidió lo que resolvía el problema de raíz: **«sólo debe existir un\n *    estado de ver vídeos, el inmersivo; este otro estado debe desaparecer»**.\n *\n * La razón de fondo es la que hacía inevitable el paso 3: con dos pantallas de vídeo, cada\n * arreglo había que hacerlo DOS veces (los ±15 s se quitaron de las dos), el mismo vídeo se\n * comportaba distinto según por dónde entraras, y había dos listas de gestos que mantener de\n * acuerdo. El vídeo vive en `app/lifebook-videos.tsx`, y punto.\n *\n * Si alguien llega aquí con `kind=video` —un enlace viejo, una notificación, una pantalla sin\n * actualizar— se le redirige al feed inmersivo. La redirección está en el componente de abajo.\n *\n * ── LÍMITES MEDIDOS DEL AUDIO, no supuestos ─────────────────────────────────\n * · `useAudioPlayerStatus` sí existe en `expo-audio` (a diferencia del vídeo, que no tiene\n *   `useVideoPlayerStatus`) y es de donde salen `currentTime`, `duration` y `playing`.\n * · `player.seekTo()` en `expo-audio` devuelve una promesa: se le pone `.catch(() => {})`\n *   porque un salto fuera de rango no debe tumbar la pantalla.\n */\nimport React, { useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Pause, Play, Rewind, FastForward } from 'lucide-react-native';\nimport { useVideoPlayer, VideoView } from 'expo-video';\nimport { setAudioModeAsync, useAudioPlayer, useAudioPlayerStatus } from 'expo-audio';\nimport { absUrl } from '../api/config';\nimport { fmtDur } from '../constants/lifebook';\n\nexport default function LifeBookPlayerScreen() {\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const p = useLocalSearchParams<{ kind?: string; src?: string; title?: string; cover?: string }>();\n  // TRES casos, no dos. `episode` es el ÚNICO vídeo que se reproduce en esta pantalla:\n  // un episodio de serie no vive en el feed (ver el comentario de `EpisodePlayerView`).\n  const kind: 'audio' | 'episode' | 'video' =\n    p.kind === 'audio' ? 'audio' : p.kind === 'episode' ? 'episode' : 'video';\n  const src = absUrl(p.src ?? '');\n  const title = p.title ? decodeURIComponent(p.title) : 'Reproduciendo';\n  const cover = absUrl(p.cover ?? '');\n\n  /* SÓLO QUEDA EL AUDIO Y EL EPISODIO. Un vídeo de PUBLICACIÓN tiene UN ÚNICO estado de\n     reproducción: el feed inmersivo (`/lifebook-videos`). Si alguien llega aquí con\n     `kind=video` —un enlace viejo, una notificación, una pantalla sin actualizar— se le\n     manda allí, en vez de mantener viva una segunda pantalla para el MISMO contenido, con\n     sus propios controles, sus propios gestos y sus propios fallos que arreglar por\n     duplicado (los ±15 s hubo que quitarlos de las dos).\n     El useEffect va ANTES del return: los hooks no pueden ser condicionales. */\n  const esVideoDePost = kind === 'video';\n  useEffect(() => {\n    if (esVideoDePost) router.replace('/lifebook-videos' as never);\n  }, [esVideoDePost, router]);\n  if (esVideoDePost) return null;\n\n  if (kind === 'episode') {\n    return <EpisodePlayerView src={src} title={title} insets={insets} onClose={() => router.back()} />;\n  }\n\n  return <AudioPlayerView src={src} title={title} cover={cover} insets={insets} onClose={() => router.back()} />;\n}\n\nfunction CloseBar({ onClose, title, dark }: { onClose: () => void; title: string; dark: boolean }) {\n  const insets = useSafeAreaInsets();\n  const tint = dark ? brand.white : undefined;\n  return (\n    <View style={[styles.closeBar, { paddingTop: insets.top + 8 }]}>\n      <Pressable onPress={onClose} hitSlop={12} style={styles.closeBtn} accessibilityLabel=\"Cerrar reproductor\">\n        <ArrowLeft size={22} color={tint ?? '#1D2129'} />\n      </Pressable>\n      <Text numberOfLines={1} style={[styles.closeTitle, { color: tint ?? '#1D2129' }]}>{title}</Text>\n      <View style={{ width: 36 }} />\n    </View>\n  );\n}\n\n/* ── EL REPRODUCTOR DE VÍDEO YA NO EXISTE (2026-09-13) ────────────────────────\n   Aquí vivía `VideoPlayerView`: controles propios (play/pausa, barra arrastrable,\n   tiempos) porque `expo-video` no deja elegir qué botones pinta con `nativeControls`.\n   Se retiró entero, con sus listeners, su `seekTo` por `currentTime` y sus estilos,\n   cuando el dueño pidió que hubiera UN ÚNICO estado de ver vídeo: el feed inmersivo.\n\n   Lo que se gana, que es la razón y no una preferencia: con dos pantallas de vídeo\n   cada arreglo había que hacerlo DOS veces (los ±15 s hubo que quitarlos de las dos),\n   y el mismo vídeo se comportaba distinto según por dónde entraras. Un solo estado,\n   un solo juego de gestos, un solo sitio donde arreglar las cosas.\n\n   El AUDIO conserva su reproductor (abajo) porque no tiene feed inmersivo: un podcast\n   no se desliza, se escucha. */\nconst SPEEDS = [1, 1.25, 1.5, 2];\n\n/* ══════════════════════════════════════════════════════════════════════════════\n   REPRODUCTOR DE EPISODIO DE SERIE\n   ══════════════════════════════════════════════════════════════════════════════\n   POR QUÉ ESTE SÍ SE QUEDA, después de quitar el reproductor de vídeo normal.\n\n   Un EPISODIO DE SERIE **no es una publicación**: vive en `lifebook.series_episodes`,\n   con `video_url` en su propia columna, y el feed inmersivo (`/lifebook-videos`) sólo\n   sabe de publicaciones (pide `/lifebook/posts/feed` y filtra por `payload.videoUrl`).\n   O sea que un episodio **no puede** pintarse en el feed.\n\n   Y hay episodios de verdad: consultado el servidor el 13-sep-2026, **12 series con\n   36 episodios, todos con vídeo**. Quitar esta pantalla sin darles salida habría dejado\n   36 vídeos imposibles de ver.\n\n   La alternativa que se valoró y se descartó: meter el episodio en el feed como una\n   «publicación sintética». Se descartó porque obliga a que el camino MÁS USADO de la app\n   (el feed) lleve condiciones para elementos que no son publicaciones —sin me gusta, sin\n   comentarios, sin guardar, sin autor—, y eso es meter complejidad en el sitio más caliente\n   para satisfacer una preferencia de interfaz. Aquí, en cambio, está aislado.\n\n   Lo que SÍ se cumplió de lo pedido: para los vídeos de publicación **sólo hay un estado**.\n   Desde el feed ya no se puede llegar aquí (el icono «Ver a pantalla completa» se quitó) y\n   `/lifebook-player?kind=video` redirige al feed. Esta pantalla sólo atiende episodios.\n\n   Controles: play/pausa + barra arrastrable + tiempos. **Sin ±15 s**, por la misma razón\n   que en el resto (con la barra debajo, dos botones de salto son un tercer camino para lo\n   mismo). */\nfunction EpisodePlayerView({ src, title, insets, onClose }: { src: string; title: string; insets: { bottom: number }; onClose: () => void }) {\n  const { colors } = useTheme();\n  const player = useVideoPlayer(src || null, (p) => {\n    p.loop = false;\n    // 0.25 s (por defecto 0.5): la barra se mueve fluida sin renders cada 50 ms.\n    p.timeUpdateEventInterval = 0.25;\n  });\n\n  const [playing, setPlaying] = useState(false);\n  const [cur, setCur] = useState(0);\n  const [dur, setDur] = useState(0);\n  const [ready, setReady] = useState(false);\n  const [error, setError] = useState(false);\n  /** Mientras el dedo arrastra la barra no se le pelea el valor. */\n  const [seeking, setSeeking] = useState<number | null>(null);\n  /** Ancho real de la barra (`onLayout`): sin esto no se puede convertir la posición del\n   *  dedo en segundos, y usar el ancho de pantalla se descuadraría con el padding. */\n  const [trackW, setTrackW] = useState(0);\n  const mounted = useRef(true);\n  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);\n\n  /* Los listeners se sueltan al desmontar: `addListener` devuelve una suscripción y, si no\n     se libera, el reproductor sigue emitiendo hacia un componente muerto. */\n  useEffect(() => {\n    if (!src) return;\n    const subs = [\n      player.addListener('playingChange', (e) => { if (mounted.current) setPlaying(!!e.isPlaying); }),\n      player.addListener('timeUpdate', (e) => { if (mounted.current) setCur(e.currentTime); }),\n      player.addListener('sourceLoad', (e) => {\n        if (!mounted.current) return;\n        setDur(Number.isFinite(e.duration) ? e.duration : 0);\n        setReady(true);\n      }),\n      player.addListener('statusChange', (e) => {\n        if (!mounted.current) return;\n        // Los valores reales del enum son 'idle' | 'loading' | 'readyToPlay' | 'error'.\n        setError(e.status === 'error');\n      }),\n    ];\n    return () => { subs.forEach((s) => s.remove()); };\n  }, [player, src]);\n\n  if (!src) {\n    return (\n      <View style={[styles.videoRoot, { alignItems: 'center', justifyContent: 'center' }]}>\n        <Text style={{ color: brand.white, fontWeight: '800' }}>Este episodio no tiene vídeo</Text>\n      </View>\n    );\n  }\n\n  const shown = seeking ?? cur;\n  const pct = dur > 0 ? Math.min(100, (shown / dur) * 100) : 0;\n  /** `expo-video` 2.2.3 no tiene `seekTo()`: se salta escribiendo `currentTime`\n   *  (VideoPlayer.types.d.ts:44-48). */\n  const seekTo = (t: number) => {\n    const next = Math.max(0, Math.min(dur || t, t));\n    player.currentTime = next;\n    setCur(next);\n  };\n  const playPause = () => {\n    if (playing) { player.pause(); setError(false); } else { player.play(); setError(false); }\n  };\n  /** Convierte la posición del dedo en segundos usando el ancho REAL de la barra. */\n  const timeAt = (x: number): number => {\n    const usable = Math.max(1, (trackW || 0) - TRACK_MARGIN * 2);\n    const ratio = Math.min(1, Math.max(0, (x - TRACK_MARGIN) / usable));\n    return ratio * (dur || 0);\n  };\n\n  return (\n    <View style={[styles.videoRoot, { backgroundColor: '#000000' }]}>\n      <CloseBar onClose={onClose} title={title} dark />\n\n      {/* `contain`: el episodio entero, sin recortar. Aquí no hay feed que llenar, así que\n          prima ver el contenido completo. */}\n      <View style={styles.videoBox}>\n        <VideoView\n          player={player}\n          style={styles.video}\n          contentFit=\"contain\"\n          nativeControls={false}\n          allowsFullscreen={false}\n        />\n        {/* Único botón del centro: play/pausa. Se oculta mientras reproduce para no tapar. */}\n        <Pressable\n          onPress={playPause}\n          hitSlop={16}\n          style={styles.centerPlay}\n          accessibilityRole=\"button\"\n          accessibilityLabel={playing ? 'Pausar' : 'Reproducir'}\n        >\n          {!playing ? (\n            <View style={styles.centerPlayBg}>\n              <Play size={34} color={brand.white} fill={brand.white} style={{ marginLeft: espaciado.e4 }} />\n            </View>\n          ) : null}\n        </Pressable>\n        {!ready && !error ? <ActivityIndicator color={brand.white} style={StyleSheet.absoluteFill} /> : null}\n      </View>\n\n      {/* Play/pausa. SOLO play: los ±15 s se quitaron (ver la cabecera). */}\n      <View style={styles.ctlRow}>\n        <Pressable onPress={playPause} hitSlop={10} style={[styles.playBtn, { backgroundColor: colors.primary }]}\n          accessibilityRole=\"button\" accessibilityLabel={playing ? 'Pausar' : 'Reproducir'}>\n          {playing ? <Pause size={22} color={brand.white} fill={brand.white} /> : <Play size={22} color={brand.white} fill={brand.white} style={{ marginLeft: espaciado.e3 }} />}\n        </Pressable>\n      </View>\n\n      {/* Barra: se arrastra con el dedo; al soltar se aplica el salto. */}\n      <View\n        style={styles.track}\n        onLayout={(e) => setTrackW(e.nativeEvent.layout.width)}\n        onStartShouldSetResponder={() => true}\n        onMoveShouldSetResponder={() => true}\n        onResponderGrant={(e) => { setSeeking(timeAt(e.nativeEvent.locationX)); }}\n        onResponderMove={(e) => { setSeeking(timeAt(e.nativeEvent.locationX)); }}\n        onResponderRelease={() => { if (seeking != null) seekTo(seeking); setSeeking(null); }}\n        onResponderTerminate={() => { setSeeking(null); }}\n        accessibilityRole=\"adjustable\"\n        accessibilityLabel=\"Progreso del episodio\"\n      >\n        <View style={[styles.trackBg, { backgroundColor: 'rgba(255,255,255,0.28)' }]}>\n          <View style={[styles.trackFill, { backgroundColor: colors.primary, width: `${pct}%` }]} />\n        </View>\n        <View style={[\n          styles.knob,\n          { left: TRACK_MARGIN + (Math.max(1, (trackW || 0) - TRACK_MARGIN * 2) * pct) / 100, backgroundColor: colors.primary },\n        ]} />\n      </View>\n\n      <View style={styles.timeRow}>\n        <Text style={styles.timeTxt}>{fmtDur(shown)}</Text>\n        <Text style={styles.timeTxt}>{fmtDur(dur)}</Text>\n      </View>\n\n      {error ? <Text style={styles.errTxt}>No se pudo reproducir este episodio. Reintenta.</Text> : null}\n\n      <View style={{ height: insets.bottom }} />\n    </View>\n  );\n}\n\n/** Margen horizontal de `styles.track` (paddingHorizontal). Debe coincidir. */\nconst TRACK_MARGIN = 20;\n\nfunction AudioPlayerView({ src, title, cover, insets, onClose }: {\n  src: string; title: string; cover: string; insets: { bottom: number }; onClose: () => void;\n}) {\n  const { colors } = useTheme();\n  const player = useAudioPlayer({ uri: src });\n  const status = useAudioPlayerStatus(player);\n  const [speedIdx, setSpeedIdx] = useState(0);\n  const [error, setError] = useState(false);\n\n  useEffect(() => {\n    setAudioModeAsync({ playsInSilentMode: true }).catch(() => {});\n    player.seekTo(0).catch(() => {});\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const cur = Number(status?.currentTime ?? 0);\n  const dur = Number(status?.duration ?? 0);\n  const playing = !!status?.playing;\n  const pct = dur > 0 ? Math.min(100, (cur / dur) * 100) : 0;\n  const seek = (delta: number) => player.seekTo(Math.max(0, Math.min(dur || cur + delta, cur + delta))).catch(() => {});\n\n  const playPause = () => {\n    if (!playing) {\n      player.play();\n      setError(false);\n    } else player.pause();\n  };\n\n  return (\n    <View style={[styles.audioRoot, { backgroundColor: colors.background }]}>\n      <CloseBar onClose={onClose} title={title} dark={false} />\n      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e26 }}>\n        {cover ? (\n          <View style={[styles.coverFrame, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n            <Image source={cover} style={styles.cover} contentFit=\"cover\" cachePolicy=\"memory-disk\" />\n          </View>\n        ) : (\n          <View style={[styles.coverFrame, { backgroundColor: alpha(colors.primary, 0.12), borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }]}>\n            <Text style={{ fontSize: 60 }}>🎙️</Text>\n          </View>\n        )}\n        <Text style={[styles.audioTitle, { color: colors.textPrimary }]} numberOfLines={2}>{title}</Text>\n\n        {/* Progreso */}\n        <View style={styles.progressTrack}>\n          <View style={[styles.progressFill, { backgroundColor: colors.primary, width: `${pct}%` }]} />\n        </View>\n        <View style={{ flexDirection: 'row', justifyContent: 'space-between', width: '100%' }}>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>{fmtDur(cur)}</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>{fmtDur(dur || 0)}</Text>\n        </View>\n\n        {/* Controles */}\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e26, marginTop: espaciado.e14 }}>\n          <Pressable onPress={() => seek(-15)} hitSlop={10} accessibilityLabel=\"Retroceder 15 segundos\">\n            <Rewind size={28} color={colors.textPrimary} />\n          </Pressable>\n          <Pressable onPress={playPause} accessibilityLabel={playing ? 'Pausar' : 'Reproducir'} style={[styles.playBig, { backgroundColor: colors.primary }]}>\n            {playing ? <Pause size={30} color={brand.white} fill={brand.white} /> : <Play size={30} color={brand.white} fill={brand.white} style={{ marginLeft: espaciado.e3 }} />}\n          </Pressable>\n          <Pressable onPress={() => seek(15)} hitSlop={10} accessibilityLabel=\"Avanzar 15 segundos\">\n            <FastForward size={28} color={colors.textPrimary} />\n          </Pressable>\n        </View>\n\n        <Pressable\n          onPress={() => { const next = (speedIdx + 1) % SPEEDS.length; setSpeedIdx(next); player.setPlaybackRate(SPEEDS[next]); }}\n          style={[styles.speedBtn, { backgroundColor: colors.surface, borderColor: colors.border }]}\n          accessibilityLabel=\"Velocidad\"\n        >\n          <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>{SPEEDS[speedIdx]}x</Text>\n        </Pressable>\n\n        {error && (\n          <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e10 }}>No se pudo reproducir. Reintenta.</Text>\n        )}\n        {!status?.isLoaded && (\n          <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e14 }} />\n        )}\n      </View>\n      <View style={{ height: insets.bottom + 10 }} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  /* Estilos del EPISODIO (el reproductor de vídeo de publicación ya no existe; éstos son\n     los del único reproductor de vídeo que queda). */\n  videoRoot: { flex: 1, backgroundColor: '#000000' },\n  videoBox: { flex: 1, justifyContent: 'center', backgroundColor: '#000000', paddingTop: 46 },\n  video: { width: '100%', height: '100%' },\n  centerPlay: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', zIndex: 3 },\n  centerPlayBg: {\n    width: 74, height: 74, borderRadius: 37, alignItems: 'center', justifyContent: 'center',\n    backgroundColor: 'rgba(0,0,0,0.55)', borderWidth: 2, borderColor: 'rgba(255,255,255,0.85)',\n  },\n  ctlRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e26, paddingVertical: espaciado.e8 },\n  playBtn: { width: 46, height: 46, borderRadius: 23, alignItems: 'center', justifyContent: 'center' },\n  track: { height: 26, justifyContent: 'center', paddingHorizontal: TRACK_MARGIN },\n  trackBg: { height: 4, borderRadius: 2, overflow: 'hidden' },\n  trackFill: { height: 4, borderRadius: 2 },\n  knob: { position: 'absolute', width: 14, height: 14, borderRadius: 7, marginLeft: -7 },\n  timeRow: { flexDirection: 'row', justifyContent: 'space-between', paddingHorizontal: TRACK_MARGIN, paddingBottom: espaciado.e6 },\n  timeTxt: { color: 'rgba(255,255,255,0.8)', fontSize: tipografia.caption, fontWeight: '700' },\n  errTxt: { color: brand.danger, fontSize: tipografia.caption, fontWeight: '700', textAlign: 'center', paddingHorizontal: espaciado.e24, paddingBottom: espaciado.e8 },\n\n  // Estilos del AUDIO.\n  audioRoot: { flex: 1 },\n  closeBar: {\n    position: 'absolute', top: 0, left: 0, right: 0, zIndex: 10,\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e14,\n  },\n  closeBtn: { width: 38, height: 38, borderRadius: 19, backgroundColor: 'rgba(0,0,0,0.35)', alignItems: 'center', justifyContent: 'center' },\n  closeTitle: { flex: 1, textAlign: 'center', fontSize: tipografia.body, fontWeight: '800', marginHorizontal: espaciado.e10 },\n  coverFrame: { width: 220, height: 220, borderRadius: 18, borderWidth: 1, overflow: 'hidden' },\n  cover: { width: '100%', height: '100%' },\n  audioTitle: { fontSize: 17, fontWeight: '800', textAlign: 'center', marginTop: espaciado.e16, marginBottom: espaciado.e18 },\n  progressTrack: { width: '100%', height: 5, borderRadius: 3, backgroundColor: 'rgba(0,0,0,0.12)', overflow: 'hidden' },\n  progressFill: { height: 5, borderRadius: 3 },\n  playBig: { width: 62, height: 62, borderRadius: 31, alignItems: 'center', justifyContent: 'center' },\n  speedBtn: { marginTop: espaciado.e20, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8, borderRadius: radios.lg, borderWidth: 1 },\n});\n","/**\r\n * Life Book — DETALLE DE PUBLICACIÓN (ruta dinámica `/lifebook-post/:id`)\r\n * Pantalla: LifeBookPostDetailScreen\r\n *\r\n * Estructura estilo Xiaohongshu:\r\n *  - Cabecera fija: volver · autor (→ perfil) · Seguir · ⋯.\r\n *  - Imagen/vídeo grande arriba (scroll horizontal + contador + visor a pantalla\r\n *    completa al tocar).\r\n *  - Título, descripción, tags (#tema → búsqueda) y ubicación + fecha.\r\n *  - Botón de servicio si la publicación enlaza un servicio real (taxi/comida/\r\n *    tienda/alquiler/trabajo).\r\n *  - Paneles por tipo: venta (comprar/contraoferta), servicio, debate y serie\r\n *    (episodios + añadir episodio).\r\n *  - Comentarios.\r\n *  - Barra inferior fija: input de comentario + me gusta + guardar + compartir.\r\n *  - \"Descubrir más\": publicaciones relacionadas al final.\r\n *\r\n * API: GET /lifebook/posts/:id · GET /lifebook/posts/:id/related ·\r\n *      POST /lifebook/posts/:id/like|comment|bookmark · POST /lifebook/users/:id/follow\r\n */\r\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\r\nimport {\r\n  ActivityIndicator, Alert, Dimensions, FlatList, Image, KeyboardAvoidingView, Modal,\r\n  Platform, Pressable, ScrollView, Share, StyleSheet, Text, TextInput, View,\r\n} from 'react-native';\r\n// Parte 32: expo-image (caché memoria+disco) para la tira de fotos — sin\r\n// destello blanco al abrir/cerrar el visor ni al volver de él.\r\nimport { Image as ExpoImage } from 'expo-image';\r\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport {\r\n  ArrowLeft, Bookmark, Briefcase, Car, ChevronRight, Heart, Home, MapPin,\r\n  MoreHorizontal, Package, Play, Plus, Send, Share2, ShoppingBag, ShoppingCart, Store, Utensils, X,\r\n} from 'lucide-react-native';\r\nimport { AuthGate } from '../../core/AuthGate';\r\nimport { absUrl } from '../../api/config';\r\nimport { authApi } from '../../api/auth';\r\nimport {\r\n  lifebookActionsApi, lifebookApi, lifebookMediaApi,\r\n  LB_CARD_DEFAULT_RATIO, toPostCard,\r\n  type LbCommentItem, type LbEpisode, type LbPostCard, type LbPostDetail,\r\n} from '../../api/lifebook';\r\nimport { lifebookPostOpsApi } from '../../api/lifebookPostOps';\r\nimport { PostCard } from '../../components/lifebook/PostCard';\r\nimport { ReportSheet } from '../../components/lifebook/ReportSheet';\r\nimport { fmtDur, lbTimeAgo, lbTypeLabel, lbXaf } from '../../constants/lifebook';\r\nimport { lbPriceLabel } from '../../constants/commerce';\r\nimport { productosEnNotaApi, type LbProductoEnNota } from '../../api/lifebookProductos';\r\nimport { ZoomableImage, type ZoomableImageHandle } from '../../components/lifebook/ZoomableImage';\r\nimport { ViewerZoomControls } from '../../components/lifebook/ViewerControls';\r\nimport { CommentRow, CommentsSheet } from '../../components/lifebook/CommentsSheet';\r\nimport { OrderSheet } from '../../components/lifebook/OrderSheet';\r\nimport { formaHoja } from '../../components/lifebook/ui/Sheet';\r\nimport { ir as irSeguro } from '../../constants/rutas';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\nconst { width: SCREEN_W, height: SCREEN_H } = Dimensions.get('window');\r\nconst COLUMN_GAP = 8;\r\nconst SIDE_PADDING = 10;\r\nconst COLUMN_W = (SCREEN_W - SIDE_PADDING * 2 - COLUMN_GAP) / 2;\r\n\r\n/**\r\n * Carrusel del detalle: caja fija **3:4** (vertical, estilo Xiaohongshu).\r\n * Todas las fotos ocupan lo mismo y se recortan con `cover`, así el detalle no\r\n * baila de alto según la proporción de cada imagen.\r\n */\r\nconst DETAIL_MEDIA_H = Math.round((SCREEN_W * 4) / 3);\r\n\r\nconst TYPE_TINT: Record<string, string> = {\r\n  note: '#6B7280', sale: '#E0439A', service: brand.primary, debate: brand.secondary,\r\n  video: '#7C3AED', podcast: '#E0439A', serie: brand.secondary,\r\n};\r\nconst CONDITION_LABEL: Record<string, string> = {\r\n  nuevo: 'Nuevo', como_nuevo: 'Como nuevo', usado: 'Usado', piezas: 'Por piezas',\r\n};\r\nconst UNIT_LABEL: Record<string, string> = {\r\n  por_hora: 'por hora', por_servicio: 'por servicio', negociable: 'negociable',\r\n};\r\nconst CONTACT_LABEL: Record<string, string> = {\r\n  inapp: 'Por la app', phone: 'Por teléfono', whatsapp: 'Por WhatsApp',\r\n};\r\nconst STATE_LABEL: Record<string, string> = {\r\n  open: 'Abierto', discussing: 'En discusión', proposals: 'Recogiendo propuestas',\r\n  community_resolved: 'Resuelto por la comunidad', attention: 'En espera de atención', closed: 'Cerrado',\r\n};\r\n/** Servicios reales enlazables (mismo mapa que usa el Estado 24h + alias shop/delivery). */\r\nconst SERVICE_ROUTES: Record<string, { route: string; label: string; color: string; icon: typeof Car }> = {\r\n  taxi: { route: '/taxi', label: 'Llamar Taxi', color: brand.secondary, icon: Car },\r\n  food: { route: '/food', label: 'Pedir comida', color: '#E0439A', icon: Utensils },\r\n  ecomerse: { route: '/ecomerse', label: 'Ver tienda', color: brand.primary, icon: ShoppingBag },\r\n  shop: { route: '/ecomerse', label: 'Ver tienda', color: brand.primary, icon: ShoppingBag },\r\n  work: { route: '/work', label: 'Ver oferta', color: '#7C3AED', icon: Briefcase },\r\n  rental: { route: '/alquiler', label: 'Ver alquiler', color: '#00A870', icon: Home },\r\n  paquete: { route: '/service/paquete', label: 'Enviar paquete', color: '#00A870', icon: Package },\r\n  delivery: { route: '/service/paquete', label: 'Enviar paquete', color: '#00A870', icon: Package },\r\n  lifebook: { route: '/lifebook-store', label: 'Ver su tienda', color: brand.primary, icon: Store },\r\n};\r\n\r\nexport default function LifeBookPostDetailScreen() {\r\n  return (\r\n    <AuthGate>\r\n      <PostContent />\r\n    </AuthGate>\r\n  );\r\n}\r\n\r\nfunction Avatar({ url, name, size = 40 }: { url?: string | null; name?: string | null; size?: number }) {\r\n  const { colors } = useTheme();\r\n  const src = absUrl(url);\r\n  if (src) return <Image source={{ uri: src }} style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: colors.surface }} />;\r\n  return (\r\n    <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: alpha(colors.primary, 0.15), alignItems: 'center', justifyContent: 'center' }}>\r\n      <Text style={{ color: colors.primary, fontSize: size * 0.5, fontWeight: '900' }}>{(name ?? '?').charAt(0).toUpperCase()}</Text>\r\n    </View>\r\n  );\r\n}\r\n\r\nfunction Chip({ text, color, bg }: { text: string; color: string; bg: string }) {\r\n  return (\r\n    <View style={{ backgroundColor: bg, borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e4 }}>\r\n      <Text style={{ color, fontSize: tipografia.caption, fontWeight: '800' }}>{text}</Text>\r\n    </View>\r\n  );\r\n}\r\n\r\n/** Botón de la barra inferior (diseño del dueño): icono + contador opcional. */\r\nfunction DetailActionButton({ icon, count, active, activeColor, colors, onPress, label }: {\r\n  icon: React.ReactNode;\r\n  count?: number;\r\n  active?: boolean;\r\n  activeColor?: string;\r\n  colors: any;\r\n  onPress: () => void;\r\n  label: string;\r\n}) {\r\n  return (\r\n    <Pressable\r\n      onPress={onPress}\r\n      accessibilityRole=\"button\"\r\n      accessibilityLabel={count ? `${label}, ${count}` : label}\r\n      style={{ alignItems: 'center', justifyContent: 'center', minWidth: 38, paddingVertical: espaciado.e2 }}\r\n    >\r\n      {icon}\r\n      {typeof count === 'number' && count > 0 ? (\r\n        <Text style={{\r\n          marginTop: espaciado.e2, fontSize: 10.5, fontWeight: '900',\r\n          color: active ? activeColor : colors.textSecondary,\r\n        }}>\r\n          {count > 999 ? '999+' : count}\r\n        </Text>\r\n      ) : null}\r\n    </Pressable>\r\n  );\r\n}\r\n\r\nfunction PostContent() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const { id } = useLocalSearchParams<{ id: string }>();\r\n\r\n  /* ── Estado ── */\r\n  const [post, setPost] = useState<LbPostDetail | null>(null);\r\n  const [loading, setLoading] = useState(true);\r\n  const [notFound, setNotFound] = useState(false);\r\n  const [comments, setComments] = useState<LbCommentItem[]>([]);\r\n  /** Total real de comentarios (lo manda el servidor en `total`). */\r\n  const [commentsTotal, setCommentsTotal] = useState(0);\r\n  /** Hoja de comentarios (la caja de texto vive ahí, no en la barra). */\r\n  const [commentsOpen, setCommentsOpen] = useState(false);\r\n  const [busyLike, setBusyLike] = useState(false);\r\n  const [imgIdx, setImgIdx] = useState(0);\r\n  const [episodes, setEpisodes] = useState<LbEpisode[] | null>(null);\r\n  const [meId, setMeId] = useState<string | null>(null);\r\n  const [following, setFollowing] = useState(false);\r\n  const [busyFollow, setBusyFollow] = useState(false);\r\n  /** Hoja de compra (la compra vive en la barra inferior). */\r\n  const [orderOpen, setOrderOpen] = useState(false);\r\n  const [menuOpen, setMenuOpen] = useState(false);\r\n  /** `true` mientras el servidor borra el post y sus archivos. */\r\n  const [borrando, setBorrando] = useState(false);\r\n  const [viewerOpen, setViewerOpen] = useState(false);\r\n  const [viewerIdx, setViewerIdx] = useState(0);\r\n  /** `true` mientras la foto del visor está ampliada (bloquea el pase). */\r\n  const [viewerZoomed, setViewerZoomed] = useState(false);\r\n  const [reportOpen, setReportOpen] = useState(false);\r\n  const [moreRelated, setMoreRelated] = useState<LbPostCard | null>(null);\r\n  const [related, setRelated] = useState<LbPostCard[]>([]);\r\n  /**\r\n   * TANDA C — los productos enganchados a la nota. Se piden aparte (una petición más al abrir\r\n   * la nota, y ninguna si no hay) para no tocar el tipo `LbPost` de `api/lifebook.ts`, que no\r\n   * se puede modificar.\r\n   *\r\n   * OJO CON EL SITIO: estos hooks van AQUÍ ARRIBA, con los demás, y NO junto al texto que\r\n   * pintan. La primera versión los puso más abajo (junto a `topics`) y eso rompía la pantalla\r\n   * entera: «Rendered more hooks than during the previous render», porque más abajo hay\r\n   * `return` tempranos (cargando / no encontrada) que se saltan los hooks en unos renderizados\r\n   * y en otros no. React exige el mismo orden SIEMPRE.\r\n   */\r\n  const [productos, setProductos] = useState<LbProductoEnNota[]>([]);\r\n  useEffect(() => {\r\n    const pid = id;\r\n    if (!pid) return;\r\n    let vivo = true;\r\n    productosEnNotaApi.deNota(String(pid))\r\n      .then((r) => { if (vivo) setProductos(r.products ?? []); })\r\n      .catch(() => { if (vivo) setProductos([]); });\r\n    return () => { vivo = false; };\r\n  }, [id]);\r\n\r\n  const mounted = useRef(true);\r\n  /* Parte 32: refs del visor de fotos — la lista (para que la pinza le gane el\r\n     toque al pase de páginas) y el mando de zoom de cada página. */\r\n  const viewerListRef = useRef<FlatList<string>>(null);\r\n  const zoomHandles = useRef<Record<number, ZoomableImageHandle | null>>({});\r\n\r\n  /* ── Carga ── */\r\n  const load = useCallback(async () => {\r\n    if (!id) return;\r\n    try {\r\n      const { post: p } = await lifebookApi.postDetail(id);\r\n      if (!p) { setNotFound(true); return; }\r\n      setPost(p);\r\n      setNotFound(false);\r\n      // Vista previa: los 3 comentarios MÁS NUEVOS + el total real.\r\n      // (El servidor los manda del más antiguo al más nuevo, así que se\r\n      //  invierte la página y se toman los 3 primeros.)\r\n      const page = await lifebookApi.postComments(id, { limit: 50 })\r\n        .catch(() => ({ comments: [] as LbCommentItem[], total: 0, nextCursor: null }));\r\n      setComments([...(page.comments ?? [])].reverse().slice(0, 3));\r\n      setCommentsTotal(Number(page.total ?? (page.comments ?? []).length));\r\n      lifebookApi.relatedPosts(id, 6)\r\n        .then((page) => { if (mounted.current) setRelated((page.posts ?? []).map(toPostCard)); })\r\n        .catch(() => {});\r\n      if (p.type === 'serie') {\r\n        const eps = await lifebookMediaApi.serieEpisodes(id).catch(() => [] as LbEpisode[]);\r\n        setEpisodes(eps);\r\n      }\r\n      // Parte 11: el propio servidor indica si sigo al autor.\r\n      setFollowing(!!p.author?.followedByMe);\r\n    } catch { setNotFound(true); }\r\n    finally { if (mounted.current) setLoading(false); }\r\n  }, [id]);\r\n\r\n  useEffect(() => {\r\n    mounted.current = true;\r\n    return () => { mounted.current = false; };\r\n  }, []);\r\n\r\n  useFocusEffect(useCallback(() => { load(); }, [load]));\r\n  useEffect(() => { authApi.me().then((m) => setMeId(m?.id ?? null)).catch(() => {}); }, []);\r\n\r\n  /* ── Acciones ── */\r\n  const toggleLike = async () => {\r\n    if (!post || busyLike) return;\r\n    setBusyLike(true);\r\n    const wasLiked = !!post.stats?.likedByMe;\r\n    const stats = post.stats ?? {};\r\n    setPost({ ...post, stats: { ...stats, likedByMe: !wasLiked, likes: Math.max(0, (stats.likes ?? 0) + (wasLiked ? -1 : 1)) } });\r\n    try { await lifebookActionsApi.toggleLike(post.id, wasLiked); }\r\n    catch {\r\n      setPost((cur) => (cur ? { ...cur, stats: { ...(cur.stats ?? {}), likedByMe: wasLiked, likes: Math.max(0, (cur.stats?.likes ?? 0)) } } : cur));\r\n    }\r\n    finally { setBusyLike(false); }\r\n  };\r\n\r\n  const toggleSave = async () => {\r\n    if (!post) return;\r\n    const was = !!post.stats?.bookmarkedByMe;\r\n    setPost({ ...post, stats: { ...(post.stats ?? {}), bookmarkedByMe: !was } });\r\n    try { await lifebookActionsApi.toggleSave(post.id, was); }\r\n    catch { setPost((cur) => (cur ? { ...cur, stats: { ...(cur.stats ?? {}), bookmarkedByMe: was } } : cur)); }\r\n  };\r\n\r\n  const toggleFollow = async () => {\r\n    if (!post?.author?.id || busyFollow) return;\r\n    setBusyFollow(true);\r\n    const was = following;\r\n    setFollowing(!was);\r\n    try { await lifebookActionsApi.toggleFollow(post.author.id, !was); }\r\n    catch { setFollowing(was); }\r\n    finally { setBusyFollow(false); }\r\n  };\r\n\r\n  /** Refresca la vista previa (y el total) tras comentar en la hoja. */\r\n  const refreshComments = useCallback(async () => {\r\n    if (!id) return;\r\n    const page = await lifebookApi.postComments(id, { limit: 50 })\r\n      .catch(() => ({ comments: [] as LbCommentItem[], total: 0, nextCursor: null }));\r\n    setComments([...(page.comments ?? [])].reverse().slice(0, 3));\r\n    setCommentsTotal(Number(page.total ?? (page.comments ?? []).length));\r\n  }, [id]);\r\n\r\n  const toggleComments = async () => {\r\n    if (!post) return;\r\n    try {\r\n      await lifebookActionsApi.commentsState(post.id, !post.allowComments);\r\n      setMenuOpen(false);\r\n      await load();\r\n    } catch (e) {\r\n      Alert.alert('Comentarios', e instanceof Error ? e.message : 'No se pudo cambiar la opción.');\r\n    }\r\n  };\r\n\r\n  /**\r\n   * Borra la publicación (autor o ADMIN, lo decide el servidor).\r\n   *\r\n   * El aviso dice lo que de verdad se pierde: no hay papelera, y con el post se van sus\r\n   * comentarios **y sus archivos del almacén** — en un vídeo largo son cientos de MB. Un\r\n   * «¿seguro?» a secas no informa de eso.\r\n   */\r\n  const borrarPost = () => {\r\n    if (!post || borrando) return;\r\n    setMenuOpen(false);\r\n    const queEs = post.type === 'video' || post.type === 'episode'\r\n      ? 'este vídeo'\r\n      : post.type === 'podcast'\r\n        ? 'este podcast'\r\n        : post.type === 'serie'\r\n          ? 'esta serie'\r\n          : 'esta publicación';\r\n    Alert.alert(\r\n      'Eliminar publicación',\r\n      `Se borrará ${queEs}, con sus comentarios y sus archivos. No se puede deshacer.`,\r\n      [\r\n        { text: 'Cancelar', style: 'cancel' },\r\n        {\r\n          text: 'Eliminar',\r\n          style: 'destructive',\r\n          onPress: async () => {\r\n            setBorrando(true);\r\n            try {\r\n              await lifebookPostOpsApi.borrarPost(post.id);\r\n              // Ya no existe: quedarse aquí mostrándolo sería mentir. Si hay historial se\r\n              // vuelve por donde se vino (el feed recarga al recuperar el foco); si no\r\n              // (enlace profundo), se va al feed, que es lo único que sigue en pie.\r\n              if (router.canGoBack()) router.back();\r\n              else irSeguro.libre('/lifebook-videos', undefined, true);\r\n            } catch (e) {\r\n              setBorrando(false);\r\n              Alert.alert('Eliminar', e instanceof Error ? e.message : 'No se pudo eliminar la publicación.');\r\n            }\r\n          },\r\n        },\r\n      ],\r\n    );\r\n  };\r\n\r\n  /** Parte 14: me gusta en un comentario (optimista). */\r\n  const toggleCommentLike = async (commentId: string) => {\r\n    const target = comments.find((c) => c.id === commentId);\r\n    if (!target) return;\r\n    const was = !!target.likedByMe;\r\n    const next = comments.map((c) => (c.id === commentId\r\n      ? { ...c, likedByMe: !was, likes: Math.max(0, (c.likes ?? 0) + (was ? -1 : 1)) }\r\n      : c));\r\n    setComments(next);\r\n    try { await lifebookApi.toggleCommentLike(commentId, was); }\r\n    catch { setComments(comments); }\r\n  };\r\n\r\n  const sharePost = () => {\r\n    Share.share({ message: `${post?.title ?? post?.body ?? 'Publicación'} — Life Book · EG Route Plan` }).catch(() => {});\r\n  };\r\n\r\n  /* ── Masonry de relacionadas (mismo reparto que el feed) ── */\r\n  const { leftCol, rightCol } = useMemo(() => {\r\n    const left: LbPostCard[] = [];\r\n    const right: LbPostCard[] = [];\r\n    let hL = 0;\r\n    let hR = 0;\r\n    for (const p of related) {\r\n      const imgH = COLUMN_W / (p.media?.aspectRatio ?? LB_CARD_DEFAULT_RATIO);\r\n      const totalH = imgH + 60;\r\n      if (hL <= hR) { left.push(p); hL += totalH; } else { right.push(p); hR += totalH; }\r\n    }\r\n    return { leftCol: left, rightCol: right };\r\n  }, [related]);\r\n\r\n  /* ── Estados de carga / error ── */\r\n  if (loading && !post) {\r\n    return (\r\n      <View style={[styles.root, styles.center, { backgroundColor: colors.background }]}>\r\n        <ActivityIndicator color={colors.primary} />\r\n      </View>\r\n    );\r\n  }\r\n  if (notFound || !post) {\r\n    return (\r\n      <View style={[styles.root, { backgroundColor: colors.background }]}>\r\n        <View style={[styles.header, { paddingTop: insets.top + 4, borderBottomColor: alpha(colors.border, 0.4) }]}>\r\n          <Pressable onPress={() => router.back()} hitSlop={12} style={{ padding: espaciado.e4 }} accessibilityLabel=\"Volver\">\r\n            <ArrowLeft size={22} color={colors.textPrimary} />\r\n          </Pressable>\r\n          <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', flex: 1 }}>Publicación</Text>\r\n        </View>\r\n        <View style={[styles.center, { flex: 1, padding: espaciado.e30, gap: espaciado.e8 }]}>\r\n          <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 15 }}>No se encontró esta publicación</Text>\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\r\n            Puede que se haya eliminado o que su visibilidad no te lo permita.\r\n          </Text>\r\n        </View>\r\n      </View>\r\n    );\r\n  }\r\n\r\n  const tint = TYPE_TINT[post.type] ?? '#6B7280';\r\n  const pl = post.payload ?? {};\r\n  const price = (pl.priceXaf as number | undefined) ?? undefined;\r\n  const isSale = post.type === 'sale';\r\n  const isService = post.type === 'service';\r\n  const isDebate = post.type === 'debate';\r\n  const isMine = !!meId && meId === post.author?.id;\r\n  const topics = (post.topics ?? []) as string[];\r\n  /** Título y texto de la caja de comentarios (diseño del dueño). */\r\n  const commentSectionTitle = 'Comentarios';\r\n  const commentPlaceholder = isDebate\r\n    ? 'Aporta al debate…'\r\n    : post.type === 'sale'\r\n      ? 'Pregunta por este artículo...'\r\n      : 'Añade un comentario...';\r\n  // Portada: fotos de la galería o la portada de vídeo/podcast/serie.\r\n  const coverUrl = typeof pl.coverUrl === 'string' ? absUrl(pl.coverUrl) : '';\r\n  const gallery = (post.media ?? []).map((m) => absUrl(m.url));\r\n  const mediaUrls = gallery.length ? gallery : (coverUrl ? [coverUrl] : []);\r\n  /**\r\n   * Parte 32: abre el visor en la foto tocada y **precarga** todas las fotos en\r\n   * la caché de disco de expo-image, así el visor aparece sin destello blanco.\r\n   */\r\n  const openViewer = (url: string) => {\r\n    setViewerIdx(Math.max(0, mediaUrls.indexOf(url)));\r\n    setViewerOpen(true);\r\n    ExpoImage.prefetch(mediaUrls, { cachePolicy: 'memory-disk' }).catch(() => {});\r\n    ExpoImage.prefetch(url, { cachePolicy: 'memory-disk' }).catch(() => {});\r\n  };\r\n  // El carrusel del detalle usa caja fija 3:4 (`DETAIL_MEDIA_H`), así que ya no\r\n  // se calcula la altura a partir de `coverRatio` (eso sigue en la tarjeta).\r\n  const linkType = post.serviceLink ? String(post.serviceLink.type) : '';\r\n  const linkCfg = SERVICE_ROUTES[linkType];\r\n  // La ruta la resuelve el servidor (serviceLink.route); el mapa local es el respaldo.\r\n  const linkRoute = post.serviceLink?.route ?? linkCfg?.route ?? null;\r\n  const linkLabel = linkCfg?.label ?? 'Ver servicio';\r\n  const linkColor = linkCfg?.color ?? colors.primary;\r\n  const isPlaying = post.type === 'video' || post.type === 'serie';\r\n\r\n  return (\r\n    <KeyboardAvoidingView\r\n      style={[styles.root, { backgroundColor: colors.background }]}\r\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\r\n    >\r\n      {/* ═══════ CABECERA FIJA: autor + seguir + ⋯ ═══════ */}\r\n      <View style={[styles.header, { paddingTop: insets.top + 4, borderBottomColor: alpha(colors.border, 0.4) }]}>\r\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ padding: espaciado.e4 }} accessibilityLabel=\"Volver\">\r\n          <ArrowLeft size={22} color={colors.textPrimary} />\r\n        </Pressable>\r\n\r\n        <Pressable\r\n          style={styles.headerAuthor}\r\n          onPress={() => irSeguro.libre('/lifebook-user', { id: post.author?.id ?? '' })}\r\n          accessibilityRole=\"button\"\r\n        >\r\n          <Avatar url={post.author?.avatarUrl} name={post.author?.fullName} size={30} />\r\n          <Text numberOfLines={1} style={{ color: post.author?.nameColor || colors.textPrimary, fontSize: tipografia.body, fontWeight: '700', flex: 1 }}>\r\n            {post.author?.fullName ?? 'Usuario'}\r\n          </Text>\r\n        </Pressable>\r\n\r\n        {!isMine && (\r\n          <Pressable\r\n            onPress={toggleFollow}\r\n            accessibilityRole=\"button\"\r\n            accessibilityState={{ selected: following }}\r\n            style={[styles.followBtn, { backgroundColor: following ? alpha(colors.textSecondary, 0.08) : colors.primary }]}\r\n          >\r\n            <Text style={{ color: following ? colors.textSecondary : brand.white, fontSize: tipografia.caption, fontWeight: '800' }}>\r\n              {following ? 'Siguiendo' : 'Seguir'}\r\n            </Text>\r\n          </Pressable>\r\n        )}\r\n\r\n        <Pressable onPress={() => setMenuOpen(true)} hitSlop={8} style={{ padding: espaciado.e4, marginLeft: espaciado.e6 }} accessibilityLabel=\"Más opciones\">\r\n          <MoreHorizontal size={20} color={colors.textSecondary} />\r\n        </Pressable>\r\n      </View>\r\n\r\n      {/* ═══════ CONTENIDO ═══════ */}\r\n      <ScrollView\r\n        style={{ flex: 1 }}\r\n        contentContainerStyle={{ paddingBottom: 108 + insets.bottom }}\r\n        showsVerticalScrollIndicator={false}\r\n      >\r\n        {/* Carrusel 3:4 (scroll horizontal + contador + puntos → visor) */}\r\n        {mediaUrls.length > 0 ? (\r\n          <View style={{ backgroundColor: colors.surface }}>\r\n            <ScrollView\r\n              horizontal\r\n              pagingEnabled\r\n              showsHorizontalScrollIndicator={false}\r\n              onMomentumScrollEnd={(e) => setImgIdx(Math.round(e.nativeEvent.contentOffset.x / Math.max(1, e.nativeEvent.layoutMeasurement.width)))}\r\n            >\r\n              {mediaUrls.map((u) => (\r\n                <Pressable\r\n                  key={u}\r\n                  onPress={() => {\r\n                    // AUDIO (podcast) → su reproductor. VÍDEO → el feed inmersivo,\r\n                    // empezando por esta publicación: es el ÚNICO estado de ver vídeo\r\n                    // (el reproductor de vídeo se retiró; ver `app/lifebook-player.tsx`).\r\n                    // Sólo se entra al feed si hay una URL de vídeo REAL: un post de tipo\r\n                    // serie o vídeo sin URL dejaría el feed sin nada que mostrar.\r\n                    const vurl = String(pl.videoUrl ?? '').trim();\r\n                  if (post.type === 'podcast') {\r\n                    router.push({\r\n                      pathname: '/lifebook-player',\r\n                      params: {\r\n                        kind: 'audio',\r\n                        src: String(pl.audioUrl ?? ''),\r\n                        title: String(post.title ?? lbTypeLabel(post.type)),\r\n                        cover: coverUrl,\r\n                      },\r\n                    } as never);\r\n                  } else if (vurl) {\r\n                    router.push({\r\n                      pathname: '/lifebook-videos',\r\n                      params: { startId: post.id },\r\n                    } as never);\r\n                  } else {\r\n                    openViewer(u);\r\n                  }\r\n                }}\r\n                  accessibilityLabel={isPlaying ? 'Reproducir' : 'Ver foto a pantalla completa'}\r\n                >\r\n                  <ExpoImage\r\n                    source={u}\r\n                    style={{ width: SCREEN_W, height: DETAIL_MEDIA_H, backgroundColor: colors.surface }}\r\n                    contentFit=\"cover\"\r\n                    cachePolicy=\"memory-disk\"\r\n                    recyclingKey={u}\r\n                    transition={0}\r\n                  />\r\n                </Pressable>\r\n              ))}\r\n            </ScrollView>\r\n\r\n            {isPlaying && (\r\n              <View style={styles.playOverlay} pointerEvents=\"none\">\r\n                <View style={styles.playCircle}>\r\n                  <Play size={28} color={brand.white} fill={brand.white} style={{ marginLeft: espaciado.e3 }} />\r\n                </View>\r\n              </View>\r\n            )}\r\n\r\n            {mediaUrls.length > 1 && (\r\n              <>\r\n                <View style={[styles.countBadge, { backgroundColor: 'rgba(0,0,0,0.55)' }]}>\r\n                  <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>{imgIdx + 1}/{mediaUrls.length}</Text>\r\n                </View>\r\n                <View style={styles.dots}>\r\n                  {mediaUrls.map((_, i) => (\r\n                    <View key={i} style={[styles.dot, { backgroundColor: i === imgIdx ? brand.white : 'rgba(255,255,255,0.5)' }]} />\r\n                  ))}\r\n                </View>\r\n              </>\r\n            )}\r\n          </View>\r\n        ) : (\r\n          <View style={[styles.hero, { backgroundColor: alpha(tint, 0.12) }]}>\r\n            <Text style={[styles.heroType, { color: tint }]}>{lbTypeLabel(post.type)}</Text>\r\n            {price !== undefined && <Text style={[styles.heroPrice, { color: tint }]}>{lbXaf(price)}</Text>}\r\n          </View>\r\n        )}\r\n\r\n        <View style={{ paddingHorizontal: espaciado.e16, paddingTop: espaciado.e14 }}>\r\n          {/* Título + descripción */}\r\n          {post.title ? <Text style={[styles.postTitle, { color: colors.textPrimary }]}>{post.title}</Text> : null}\r\n          {post.body ? <Text style={[styles.postBody, { color: colors.textPrimary }]}>{post.body}</Text> : null}\r\n\r\n          {/* TANDA C — LOS PRODUCTOS DENTRO DE LA NOTA. Van justo aquí: debajo del texto y\r\n              ANTES de los hashtags, que es donde los pone Xiaohongshu. Si la nota no tiene\r\n              productos, no se pinta nada (ni hueco). */}\r\n          {productos.length > 0 ? (\r\n            <View style={{ marginTop: espaciado.e12, gap: espaciado.e8 }}>\r\n              {productos.map((p) => (\r\n                <Pressable\r\n                  key={p.id}\r\n                  onPress={() => irSeguro.libre('/lifebook-product/[id]', { id: p.id })}\r\n                  accessibilityLabel={`Ver el producto ${p.title}`}\r\n                  style={{\r\n                    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, padding: espaciado.e8,\r\n                    borderRadius: radios.md, borderWidth: 1,\r\n                    borderColor: alpha(colors.primary, 0.35),\r\n                    backgroundColor: alpha(colors.primary, 0.06),\r\n                  }}\r\n                >\r\n                  {p.coverUrl ? (\r\n                    <Image source={{ uri: absUrl(p.coverUrl) }} style={{ width: 46, height: 46, borderRadius: 10 }} />\r\n                  ) : (\r\n                    <View style={{ width: 46, height: 46, borderRadius: 10, alignItems: 'center', justifyContent: 'center', backgroundColor: alpha(colors.primary, 0.12) }}>\r\n                      <Package size={18} color={colors.primary} />\r\n                    </View>\r\n                  )}\r\n                  <View style={{ flex: 1 }}>\r\n                    <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{p.title}</Text>\r\n                    <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900', marginTop: 1 }}>\r\n                      {lbPriceLabel(p.priceXaf, p.priceMode, lbXaf)}\r\n                    </Text>\r\n                  </View>\r\n                  <View style={{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, borderRadius: radios.full, backgroundColor: colors.primary }}>\r\n                    <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>Ver</Text>\r\n                  </View>\r\n                </Pressable>\r\n              ))}\r\n            </View>\r\n          ) : null}\r\n\r\n          {/* Tags (temas) → búsqueda */}\r\n          {(topics.length > 0 || post.tone) && (\r\n            <View style={styles.chipRow}>\r\n              {post.tone ? <Chip text={post.tone} color={colors.textPrimary} bg={colors.surface} /> : null}\r\n              {topics.map((t) => (\r\n                <Pressable\r\n                  key={t}\r\n                  onPress={() => irSeguro.libre('/lifebook-search', { q: t })}\r\n                  accessibilityRole=\"link\"\r\n                >\r\n                  <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '600' }}>#{t}</Text>\r\n                </Pressable>\r\n              ))}\r\n            </View>\r\n          )}\r\n\r\n          {/* Ubicación + fecha */}\r\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, marginTop: espaciado.e12, flexWrap: 'wrap' }}>\r\n            {post.city ? (\r\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\r\n                <MapPin size={13} color={colors.textSecondary} />\r\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\r\n                  {post.barrio ? `${post.barrio}, ` : ''}{post.city}\r\n                </Text>\r\n              </View>\r\n            ) : null}\r\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{lbTimeAgo(post.createdAt)}</Text>\r\n          </View>\r\n\r\n          {/* Botón de servicio enlazado */}\r\n          {linkRoute ? (\r\n            <Pressable\r\n              onPress={() => {\r\n                // `lifebook` enlaza un PERFIL: la tienda (`/lifebook-store`) exige\r\n                // `sellerId`, así que sin id se abría vacía. Se va al perfil.\r\n                if (post.serviceLink?.type === 'lifebook' && post.serviceLink?.id) {\r\n                  irSeguro.libre('/lifebook-user', { id: String(post.serviceLink.id) });\r\n                  return;\r\n                }\r\n                /* La ruta del servicio sale de una tabla; se valida por si esa entrada apunta a\r\n                   una pantalla que ya no existe (fue justo el caso de `/emergencia`). */\r\n                irSeguro.libre(String(linkRoute));\r\n              }}\r\n              accessibilityRole=\"button\"\r\n              style={[styles.serviceBtn, { backgroundColor: linkColor }]}\r\n            >\r\n              {linkCfg ? <linkCfg.icon size={16} color={brand.white} /> : <Store size={16} color={brand.white} />}\r\n              <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>{linkLabel}</Text>\r\n              <ChevronRight size={14} color=\"rgba(255,255,255,0.7)\" />\r\n            </Pressable>\r\n          ) : null}\r\n\r\n          {/* Venta */}\r\n          {isSale && (\r\n            <View style={[styles.panel, { backgroundColor: colors.surface, borderColor: colors.border }]}>\r\n              <Text style={[styles.panelTitle, { color: colors.textPrimary }]}>\r\n                Precio: {price !== undefined ? lbXaf(price) : 'A convenir'}\r\n              </Text>\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>\r\n                {(CONDITION_LABEL[String(pl.condition ?? '')] ?? pl.condition ?? '')}{pl.negotiable ? ' · negociable' : ''}{pl.category ? ` · ${pl.category}` : ''}\r\n              </Text>\r\n              {(pl.delivery as string[] | undefined)?.length ? (\r\n                <Text style={styles.panelLine}>Entrega: {(pl.delivery as string[]).join(' · ')}</Text>\r\n              ) : null}\r\n              {(pl.paymentMethods as string[] | undefined)?.length ? (\r\n                <Text style={styles.panelLine}>Pago: {(pl.paymentMethods as string[]).join(' · ')}</Text>\r\n              ) : null}\r\n              <Text style={styles.panelLine}>Contacto: {CONTACT_LABEL[String(pl.contactMode ?? '')] ?? pl.contactMode}</Text>\r\n            </View>\r\n          )}\r\n\r\n          {/* Servicio */}\r\n          {isService && (\r\n            <View style={[styles.panel, { backgroundColor: colors.surface, borderColor: colors.border }]}>\r\n              <Text style={[styles.panelTitle, { color: colors.textPrimary }]}>\r\n                {pl.serviceType ? String(pl.serviceType) : 'Servicio'}\r\n                {price !== undefined ? ` · ${lbXaf(price)}` : ''}{pl.unit ? ` ${UNIT_LABEL[String(pl.unit)] ?? pl.unit}` : ''}\r\n              </Text>\r\n              {(pl.availability as string[] | undefined)?.length ? (\r\n                <Text style={styles.panelLine}>Disponible: {(pl.availability as string[]).join(' · ')}</Text>\r\n              ) : null}\r\n              <Text style={styles.panelLine}>Contacto: {CONTACT_LABEL[String(pl.contactMode ?? '')] ?? pl.contactMode}</Text>\r\n            </View>\r\n          )}\r\n\r\n          {/* Debate */}\r\n          {isDebate && post.debate && (\r\n            <View style={[styles.panel, { borderColor: alpha(tint, 0.4) }]}>\r\n              <View style={{ flexDirection: 'row', gap: espaciado.e8, flexWrap: 'wrap' }}>\r\n                <Chip text={String(post.debate.category ?? '')} color={tint} bg={alpha(tint, 0.12)} />\r\n                <Chip text={STATE_LABEL[post.debate.state] ?? post.debate.state} color={brand.white} bg={tint} />\r\n              </View>\r\n              {post.debate.problem ? <Text style={[styles.panelTitle, { color: colors.textPrimary, marginTop: espaciado.e8 }]}>El problema</Text> : null}\r\n              {post.debate.problem ? <Text style={styles.panelLine}>{post.debate.problem}</Text> : null}\r\n              {post.debate.context ? <Text style={styles.panelLine}>{post.debate.context}</Text> : null}\r\n              {post.debate.initialProposal ? <Text style={styles.panelLine}>Propuesta inicial: {post.debate.initialProposal}</Text> : null}\r\n              {post.debate.resolvedSummary ? (\r\n                <>\r\n                  <Text style={[styles.panelTitle, { color: colors.success, marginTop: espaciado.e6 }]}>✓ Cómo se resolvió</Text>\r\n                  <Text style={styles.panelLine}>{post.debate.resolvedSummary}</Text>\r\n                </>\r\n              ) : null}\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e8 }}>\r\n                {post.debate.allowProposals ? 'Acepta propuestas de solución' : 'No acepta propuestas'}\r\n                {post.debate.allowVotes ? ' · con votos de la comunidad' : ''}\r\n              </Text>\r\n              {/* Parte 14: agregado real de los votos de las propuestas */}\r\n              {(post.debate.votesYes !== undefined || post.debate.votesNo !== undefined) && (\r\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, flexWrap: 'wrap', marginTop: espaciado.e10 }}>\r\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\r\n                    Comunidad: {post.debate.votesYes ?? 0} a favor · {post.debate.votesNo ?? 0} en contra\r\n                  </Text>\r\n                  {post.debate.myVote ? (\r\n                    <Chip\r\n                      text={post.debate.myVote === 'yes' ? 'Tu voto: sí' : 'Tu voto: no'}\r\n                      color={brand.white}\r\n                      bg={tint}\r\n                    />\r\n                  ) : null}\r\n                </View>\r\n              )}\r\n            </View>\r\n          )}\r\n\r\n          {/* Serie: episodios */}\r\n          {post.type === 'serie' && (\r\n            <View style={{ marginTop: espaciado.e16 }}>\r\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, flexWrap: 'wrap' }}>\r\n                <Text style={[styles.sectionTitle, { marginTop: 0, marginBottom: 0, color: colors.textPrimary }]}>Episodios</Text>\r\n                {post.serie ? (\r\n                  <Chip\r\n                    text={post.serie.episodesCount > 0 ? `📺 ${post.serie.episodesCount} eps · ${post.serie.seasons} temp.` : 'Sin episodios aún'}\r\n                    color={colors.textPrimary}\r\n                    bg={colors.surface}\r\n                  />\r\n                ) : null}\r\n                {isMine && (\r\n                  <Pressable\r\n                    onPress={() => irSeguro.libre('/lifebook-media', { kind: 'episode', serieId: post.id, serieTitle: String(post.title ?? '') })}\r\n                    style={[styles.epAddBtn, { backgroundColor: alpha(TYPE_TINT.serie, 0.14) }]}\r\n                    accessibilityLabel=\"Añadir episodio\"\r\n                  >\r\n                    <Plus size={14} color={TYPE_TINT.serie} />\r\n                    <Text style={{ color: TYPE_TINT.serie, fontSize: tipografia.caption, fontWeight: '900' }}>Añadir episodio</Text>\r\n                  </Pressable>\r\n                )}\r\n              </View>\r\n              {episodes === null ? (\r\n                <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e14 }} />\r\n              ) : episodes.length === 0 ? (\r\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e8, lineHeight: 19 }}>\r\n                  {isMine ? 'Tu serie aún no tiene episodios. Añade el primero.' : 'Esta serie aún no tiene episodios publicados.'}\r\n                </Text>\r\n              ) : (\r\n                episodes.map((ep) => (\r\n                  <Pressable\r\n                    key={ep.id}\r\n                    onPress={() => router.push({\r\n                      // `kind: 'episode'`: un episodio de serie NO es una publicación, así\r\n                      // que no puede ir al feed inmersivo (ver `EpisodePlayerView`).\r\n                      pathname: '/lifebook-player',\r\n                      params: { kind: 'episode', src: ep.videoUrl, title: `${ep.label} — ${ep.title ?? post.title ?? 'Episodio'}` },\r\n                    } as never)}\r\n                    style={({ pressed }) => [styles.epRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : colors.surface, borderColor: colors.border }]}\r\n                  >\r\n                    <View style={[styles.epThumb, { backgroundColor: alpha(TYPE_TINT.serie, 0.16) }]}>\r\n                      <Text style={{ fontSize: tipografia.subtitle }}>🎬</Text>\r\n                    </View>\r\n                    <View style={{ flex: 1 }}>\r\n                      <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>\r\n                        {ep.label}{ep.title ? ` — ${ep.title}` : ''}\r\n                      </Text>\r\n                      {ep.body ? <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>{ep.body}</Text> : null}\r\n                    </View>\r\n                    {ep.durationSec != null && (\r\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700' }}>{fmtDur(ep.durationSec)}</Text>\r\n                    )}\r\n                    <Play size={15} color={colors.primary} fill={colors.primary} style={{ marginLeft: espaciado.e6 }} />\r\n                  </Pressable>\r\n                ))\r\n              )}\r\n            </View>\r\n          )}\r\n\r\n\r\n          {/* Stats */}\r\n          <View style={[styles.statsRow, { borderBottomColor: alpha(colors.border, 0.4) }]}>\r\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\r\n              {formatCount(post.stats?.likes ?? 0)} Me gusta · {formatCount(post.stats?.comments ?? 0)} Comentarios\r\n            </Text>\r\n          </View>\r\n\r\n          {/* ═══════ COMENTARIOS (vista previa → hoja) ═══════ */}\r\n          <View style={{ marginTop: espaciado.e18 }}>\r\n            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\r\n              <Text style={{ fontSize: tipografia.subtitle, fontWeight: '900', color: colors.textPrimary }}>{commentSectionTitle}</Text>\r\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textSecondary }}>\r\n                {formatCount(commentsTotal || (post.stats?.comments ?? 0))}\r\n              </Text>\r\n            </View>\r\n\r\n            {!post.allowComments ? (\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', paddingVertical: espaciado.e18 }}>\r\n                Los comentarios están desactivados\r\n              </Text>\r\n            ) : comments.length === 0 ? (\r\n              <Pressable\r\n                onPress={() => setCommentsOpen(true)}\r\n                accessibilityLabel=\"Sé el primero en comentar\"\r\n                style={{\r\n                  marginTop: espaciado.e10, borderRadius: radios.lg, borderWidth: 1, borderColor: colors.border,\r\n                  backgroundColor: colors.surface, paddingVertical: espaciado.e16, alignItems: 'center',\r\n                }}\r\n              >\r\n                <Text style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textSecondary }}>Sé el primero en comentar</Text>\r\n              </Pressable>\r\n            ) : (\r\n              <View style={{ marginTop: espaciado.e4 }}>\r\n                {comments.slice(0, 3).map((c) => (\r\n                  <CommentRow\r\n                    key={c.id}\r\n                    c={c}\r\n                    tint={tint}\r\n                    colors={colors}\r\n                    onLike={() => toggleCommentLike(c.id)}\r\n                    onReply={() => setCommentsOpen(true)}\r\n                  />\r\n                ))}\r\n              </View>\r\n            )}\r\n\r\n            {(commentsTotal || (post.stats?.comments ?? 0)) > 3 ? (\r\n              <Pressable\r\n                onPress={() => setCommentsOpen(true)}\r\n                accessibilityLabel={`Ver los ${commentsTotal} comentarios`}\r\n                style={{ marginTop: espaciado.e8, paddingVertical: espaciado.e10, alignItems: 'center' }}\r\n              >\r\n                <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>\r\n                  Ver los {formatCount(commentsTotal || (post.stats?.comments ?? 0))} comentarios\r\n                </Text>\r\n              </Pressable>\r\n            ) : null}\r\n          </View>\r\n\r\n          {/* ═══════ DESCUBRIR MÁS (relacionadas) ═══════ */}\r\n          {related.length > 0 && (\r\n            <View style={{ marginTop: espaciado.e24 }}>\r\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '800', marginBottom: espaciado.e12 }}>\r\n                Descubrir más\r\n              </Text>\r\n              <View style={styles.masonryRow}>\r\n                <View style={styles.masonryCol}>\r\n                  {leftCol.map((p) => (\r\n                    <PostCard\r\n                      key={p.id}\r\n                      post={p}\r\n                      width={COLUMN_W}\r\n                      onPress={(pid) => router.push({ pathname: '/lifebook-post/[id]', params: { id: pid } })}\r\n                      onMore={setMoreRelated}\r\n                    />\r\n                  ))}\r\n                </View>\r\n                <View style={styles.masonryCol}>\r\n                  {rightCol.map((p) => (\r\n                    <PostCard\r\n                      key={p.id}\r\n                      post={p}\r\n                      width={COLUMN_W}\r\n                      onPress={(pid) => router.push({ pathname: '/lifebook-post/[id]', params: { id: pid } })}\r\n                      onMore={setMoreRelated}\r\n                    />\r\n                  ))}\r\n                </View>\r\n              </View>\r\n            </View>\r\n          )}\r\n        </View>\r\n      </ScrollView>\r\n\r\n      {/* ═══════ BARRA INFERIOR FIJA (diseño del dueño) ═══════ */}\r\n      <View\r\n        style={{\r\n          position: 'absolute', left: 0, right: 0, bottom: 0,\r\n          backgroundColor: alpha(colors.surface, 0.98),\r\n          borderTopWidth: StyleSheet.hairlineWidth,\r\n          borderTopColor: colors.border,\r\n          paddingBottom: insets.bottom,\r\n        }}\r\n      >\r\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8 }}>\r\n          {/* La caja es una pastilla: el texto se escribe en la hoja de comentarios */}\r\n          <Pressable\r\n            onPress={() => setCommentsOpen(true)}\r\n            accessibilityLabel={post.allowComments ? commentPlaceholder : 'Comentarios desactivados'}\r\n            style={{\r\n              flex: 1, height: 38, borderRadius: radios.full,\r\n              backgroundColor: alpha(colors.textPrimary, 0.07),\r\n              paddingHorizontal: espaciado.e14, justifyContent: 'center',\r\n            }}\r\n          >\r\n            <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.body, fontWeight: '700' }}>\r\n              {post.allowComments ? commentPlaceholder : 'Comentarios desactivados'}\r\n            </Text>\r\n          </Pressable>\r\n\r\n          {/* La compra vive aquí (solo artículos de otros) */}\r\n          {!isMine && post.type === 'sale' ? (\r\n            <Pressable\r\n              onPress={() => setOrderOpen(true)}\r\n              accessibilityLabel=\"Comprar\"\r\n              style={{\r\n                height: 38, borderRadius: radios.full, backgroundColor: colors.primary,\r\n                flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, paddingHorizontal: espaciado.e14,\r\n              }}\r\n            >\r\n              <ShoppingCart size={16} color={brand.white} />\r\n              <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>Comprar</Text>\r\n            </Pressable>\r\n          ) : null}\r\n\r\n          <DetailActionButton\r\n            label=\"Me gusta\"\r\n            onPress={toggleLike}\r\n            active={!!post.stats?.likedByMe}\r\n            activeColor={brand.like}\r\n            colors={colors}\r\n            count={post.stats?.likes ?? 0}\r\n            icon={\r\n              <Heart\r\n                size={22}\r\n                color={post.stats?.likedByMe ? brand.like : colors.textPrimary}\r\n                fill={post.stats?.likedByMe ? brand.like : 'transparent'}\r\n              />\r\n            }\r\n          />\r\n\r\n          <DetailActionButton\r\n            label=\"Guardar\"\r\n            onPress={toggleSave}\r\n            active={!!post.stats?.bookmarkedByMe}\r\n            activeColor=\"#FFB800\"\r\n            colors={colors}\r\n            count={post.savedCount ?? post.stats?.bookmarks ?? 0}\r\n            icon={\r\n              /* Mismo icono y color que la tarjeta del feed y el perfil. */\r\n              <Bookmark\r\n                size={22}\r\n                color={post.stats?.bookmarkedByMe ? '#FFB800' : colors.textPrimary}\r\n                fill={post.stats?.bookmarkedByMe ? '#FFB800' : 'none'}\r\n              />\r\n            }\r\n          />\r\n\r\n          <DetailActionButton\r\n            label=\"Compartir\"\r\n            onPress={sharePost}\r\n            colors={colors}\r\n            icon={<Share2 size={22} color={colors.textPrimary} />}\r\n          />\r\n        </View>\r\n      </View>\r\n\r\n      {/* ═══════ Hoja de comentarios ═══════ */}\r\n      <CommentsSheet\r\n        visible={commentsOpen}\r\n        onClose={() => setCommentsOpen(false)}\r\n        postId={post.id}\r\n        tint={tint}\r\n        allowComments={post.allowComments}\r\n        meId={meId}\r\n        title={commentSectionTitle}\r\n        placeholder={commentPlaceholder}\r\n        onCountChange={(n) => { setCommentsTotal(n); setPost((cur) => (cur ? { ...cur, stats: { ...(cur.stats ?? {}), comments: n } } : cur)); }}\r\n        onSent={refreshComments}\r\n        /*\r\n          La publicación NO se tapa entera: con el 80 % de antes, la hoja se comía\r\n          casi toda la pantalla y lo único que quedaba a la vista era el borde de\r\n          arriba. Con 62 % se sigue viendo el autor y la foto mientras se leen los\r\n          comentarios, que es lo que hacen Xiaohongshu y TikTok (redimensionar, no\r\n          tapar). Ver docs/COMENTARIOS-QUE-NO-TAPEN-EL-CONTENIDO.md.\r\n        */\r\n        maxHeightPct={62}\r\n      />\r\n\r\n      {/* ═══════ Hoja de compra ═══════ */}\r\n      <OrderSheet\r\n        visible={orderOpen}\r\n        onClose={() => setOrderOpen(false)}\r\n        postId={post.id}\r\n        priceXaf={Number(pl.priceXaf ?? 0) || 0}\r\n        negotiable={!!pl.negotiable}\r\n        onCreated={(orderNo) => {\r\n          setOrderOpen(false);\r\n          Alert.alert('Pedido creado', `Tu pedido ${orderNo} se envió al vendedor.`);\r\n          irSeguro.libre('/lifebook-orders', undefined, true);\r\n        }}\r\n      />\r\n\r\n      {/* ═══════ Menú ⋯ ═══════ */}\r\n      <Modal visible={menuOpen} transparent animationType=\"fade\" onRequestClose={() => setMenuOpen(false)} statusBarTranslucent>\r\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.4)' }} onPress={() => setMenuOpen(false)} />\r\n        <View style={[styles.menuSheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\r\n          {isMine ? (\r\n            <>\r\n              <Pressable\r\n                onPress={toggleComments}\r\n                style={({ pressed }) => [styles.menuRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\r\n              >\r\n                <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '700' }}>\r\n                  {post.allowComments ? 'Desactivar comentarios' : 'Activar comentarios'}\r\n                </Text>\r\n              </Pressable>\r\n              <Pressable\r\n                onPress={borrarPost}\r\n                disabled={borrando}\r\n                style={({ pressed }) => [\r\n                  styles.menuRow,\r\n                  { backgroundColor: pressed ? alpha(colors.danger, 0.05) : 'transparent', opacity: borrando ? 0.5 : 1 },\r\n                ]}\r\n              >\r\n                <Text style={{ color: colors.danger, fontSize: 15, fontWeight: '800' }}>\r\n                  {borrando ? 'Eliminando…' : 'Eliminar publicación'}\r\n                </Text>\r\n              </Pressable>\r\n            </>\r\n          ) : (\r\n            <Pressable\r\n              onPress={() => { setMenuOpen(false); setReportOpen(true); }}\r\n              style={({ pressed }) => [styles.menuRow, { backgroundColor: pressed ? alpha(colors.danger, 0.05) : 'transparent' }]}\r\n            >\r\n              <Text style={{ color: colors.danger, fontSize: 15, fontWeight: '800' }}>Reportar publicación</Text>\r\n            </Pressable>\r\n          )}\r\n          <Pressable onPress={() => setMenuOpen(false)} style={{ paddingVertical: espaciado.e10 }}>\r\n            <Text style={{ textAlign: 'center', color: colors.textSecondary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\r\n          </Pressable>\r\n        </View>\r\n      </Modal>\r\n\r\n      {/* ═══════ Visor completo: zoom por pinza/doble toque + pase de foto ═══════\r\n          Parte 32: entra SIN animación (el fundido sobre negro era parte del\r\n          parpadeo), las fotos van con caché de disco (expo-image) y la pinza\r\n          bloquea el pase de páginas para que el zoom funcione de verdad. */}\r\n      <Modal\r\n        visible={viewerOpen}\r\n        transparent\r\n        animationType=\"none\"\r\n        onRequestClose={() => setViewerOpen(false)}\r\n        statusBarTranslucent\r\n      >\r\n        <View style={{ flex: 1, backgroundColor: '#000000' }}>\r\n          <FlatList\r\n            ref={viewerListRef}\r\n            data={mediaUrls}\r\n            horizontal\r\n            pagingEnabled\r\n            /* Con la foto ampliada el arrastre mueve la imagen, no cambia de foto. */\r\n            scrollEnabled={!viewerZoomed}\r\n            initialScrollIndex={viewerIdx}\r\n            getItemLayout={(_, i) => ({ length: SCREEN_W, offset: SCREEN_W * i, index: i })}\r\n            keyExtractor={(u) => u}\r\n            showsHorizontalScrollIndicator={false}\r\n            onMomentumScrollEnd={(e) => setViewerIdx(Math.round(e.nativeEvent.contentOffset.x / SCREEN_W))}\r\n            renderItem={({ item, index }) => (\r\n              <ZoomableImage\r\n                ref={(h) => { zoomHandles.current[index] = h; }}\r\n                uri={item}\r\n                width={SCREEN_W}\r\n                height={SCREEN_H}\r\n                resetKey={`${index}-${viewerIdx}`}\r\n                blockScrollRef={viewerListRef}\r\n                onZoomChange={index === viewerIdx ? setViewerZoomed : undefined}\r\n                onSingleTap={() => setViewerOpen(false)}\r\n              />\r\n            )}\r\n          />\r\n          <Pressable\r\n            onPress={() => setViewerOpen(false)}\r\n            style={{ position: 'absolute', top: insets.top + 10, right: 16, width: 36, height: 36, borderRadius: 18, backgroundColor: 'rgba(255,255,255,0.16)', alignItems: 'center', justifyContent: 'center' }}\r\n            accessibilityLabel=\"Cerrar\"\r\n          >\r\n            <X size={20} color={brand.white} />\r\n          </Pressable>\r\n\r\n          {/* Controles de zoom (Parte 32): funcionan aunque el gesto no salga. */}\r\n          <ViewerZoomControls\r\n            bottom={insets.bottom + 18}\r\n            onZoomOut={() => zoomHandles.current[viewerIdx]?.zoomOut()}\r\n            onFit={() => zoomHandles.current[viewerIdx]?.fit()}\r\n            onZoomIn={() => zoomHandles.current[viewerIdx]?.zoomIn()}\r\n          />\r\n\r\n          {mediaUrls.length > 1 ? (\r\n            <View style={{ position: 'absolute', bottom: insets.bottom + 18, alignSelf: 'center', backgroundColor: 'rgba(255,255,255,0.16)', borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e5 }}>\r\n              <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.caption }}>{viewerIdx + 1}/{mediaUrls.length}</Text>\r\n            </View>\r\n          ) : null}\r\n          <Text style={{ position: 'absolute', bottom: insets.bottom + 18, right: 18, color: 'rgba(255,255,255,0.75)', fontSize: tipografia.caption, fontWeight: '700' }}>\r\n            {viewerZoomed ? 'Doble toque: encajar' : 'Pellizca para ampliar'}\r\n          </Text>\r\n        </View>\r\n      </Modal>\r\n\r\n      {/* ═══════ Reportar (⋯ del detalle y de las tarjetas) ═══════ */}\r\n      <ReportSheet\r\n        post={moreRelated ?? (reportOpen ? toPostCard(post) : null)}\r\n        onClose={() => { setReportOpen(false); setMoreRelated(null); }}\r\n        onReport={async (postId, reason) => {\r\n          try {\r\n            await lifebookActionsApi.report(postId, 'post', reason);\r\n            Alert.alert('Gracias', 'Tu reporte fue enviado. El equipo lo revisará.');\r\n          } catch (e) {\r\n            Alert.alert('Reportar', e instanceof Error ? e.message : 'No se pudo enviar el reporte.');\r\n          }\r\n        }}\r\n        onBlocked={() => router.back()}\r\n      />\r\n    </KeyboardAvoidingView>\r\n  );\r\n}\r\n\r\nfunction formatCount(n: number): string {\r\n  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;\r\n  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;\r\n  return String(n);\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1 },\r\n  center: { alignItems: 'center', justifyContent: 'center' },\r\n  header: {\r\n    flexDirection: 'row',\r\n    alignItems: 'center',\r\n    paddingHorizontal: espaciado.e12,\r\n    paddingBottom: espaciado.e10,\r\n    borderBottomWidth: StyleSheet.hairlineWidth,\r\n    gap: espaciado.e8,\r\n  },\r\n  headerAuthor: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, flex: 1 },\r\n  followBtn: { borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e7 },\r\n  hero: { height: 120, alignItems: 'center', justifyContent: 'center', gap: espaciado.e4 },\r\n  heroType: { fontSize: tipografia.title, fontWeight: '900', letterSpacing: 2 },\r\n  heroPrice: { fontSize: 17, fontWeight: '900' },\r\n  playOverlay: {\r\n    ...StyleSheet.absoluteFillObject,\r\n    alignItems: 'center',\r\n    justifyContent: 'center',\r\n    backgroundColor: 'rgba(0,0,0,0.2)',\r\n  },\r\n  playCircle: {\r\n    width: 64,\r\n    height: 64,\r\n    borderRadius: 32,\r\n    backgroundColor: 'rgba(0,0,0,0.5)',\r\n    alignItems: 'center',\r\n    justifyContent: 'center',\r\n  },\r\n  dots: { position: 'absolute', bottom: 8, alignSelf: 'center', flexDirection: 'row', gap: espaciado.e5 },\r\n  countBadge: { position: 'absolute', top: 10, right: 12, borderRadius: radios.full, paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e4 },\r\n  dot: { width: 6, height: 6, borderRadius: 3 },\r\n  postTitle: { fontSize: 18, fontWeight: '900', lineHeight: 23 },\r\n  postBody: { fontSize: 15.5, lineHeight: 22.5, marginTop: espaciado.e8 },\r\n  chipRow: { flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: espaciado.e7, marginTop: espaciado.e12 },\r\n  serviceBtn: {\r\n    flexDirection: 'row',\r\n    alignItems: 'center',\r\n    gap: espaciado.e8,\r\n    borderRadius: radios.md,\r\n    paddingHorizontal: espaciado.e16,\r\n    paddingVertical: espaciado.e12,\r\n    marginTop: espaciado.e14,\r\n  },\r\n  panel: { borderRadius: 14, borderWidth: 1, padding: espaciado.e12, marginTop: espaciado.e14 },\r\n  panelTitle: { fontSize: 15, fontWeight: '900' },\r\n  panelLine: { color: '#5B6470', fontSize: tipografia.body, marginTop: espaciado.e4, lineHeight: 18 },\r\n  statsRow: { marginTop: espaciado.e14, paddingBottom: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth },\r\n  sectionTitle: { fontSize: 14.5, fontWeight: '900', marginTop: espaciado.e20, marginBottom: espaciado.e8 },\r\n  epAddBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5, marginLeft: 'auto' },\r\n  epRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderRadius: radios.md, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e10, marginTop: espaciado.e8 },\r\n  epThumb: { width: 40, height: 40, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\r\n  masonryRow: { flexDirection: 'row', gap: COLUMN_GAP },\r\n  masonryCol: { flex: 1, gap: COLUMN_GAP },\r\n  menuSheet: { ...formaHoja },\r\n  menuRow: { borderRadius: radios.md, paddingVertical: espaciado.e13, paddingHorizontal: espaciado.e12 },\r\n});\r\n","/**\n * Operaciones del AUTOR sobre su propia publicación.\n *\n * Vive en su propio fichero a propósito: `api/lifebook.ts` lo está tocando otro agente a la\n * vez y esto no tiene por qué esperar a nadie. La pantalla solo importa\n * `lifebookPostOpsApi`, así que el día que se junten se puede mover allí sin tocar la vista.\n */\nimport { httpRequest } from './httpClient';\n\n/**\n * Respuesta de `DELETE /lifebook/posts/:id`.\n *\n * El servidor borra también los archivos del almacén del post, así que un vídeo de 900 MB\n * libera el disco de verdad. El cuerpo exacto no se tipa campo a campo a propósito: la\n * pantalla solo necesita saber que la promesa resolvió (si el borrado falla, `httpRequest`\n * lanza y el post sigue ahí).\n */\nexport interface LbPostBorrado {\n  ok?: boolean;\n  [k: string]: unknown;\n}\n\nexport const lifebookPostOpsApi = {\n  /**\n   * Borra una publicación propia (o cualquiera, si eres ADMIN). Es irreversible: no hay\n   * papelera ni «deshacer», y con ella se van sus comentarios y sus archivos.\n   */\n  borrarPost: (id: string) => httpRequest<LbPostBorrado>(`/lifebook/posts/${id}`, { method: 'DELETE' }),\n};\n","/**\n * CommentsSheet — hoja inferior de comentarios del detalle (03 + Parte 23).\n *\n * Diseño del dueño (`CommentRow` + hoja con asa, título, lista y caja de texto)\n * conectado a los datos REALES del servidor:\n *   · `GET  /posts/:id/comments?limit=&cursor=` → `{ comments, nextCursor, total }`\n *     (paginado; cada comentario dice `repliesCount`)\n *   · `POST /posts/:id/comments { text, parentId }` → comentario creado\n *   · `GET  /comments/:id/replies` → respuestas, cada una con `replyToName`\n *   · `PATCH/DELETE /comments/:id` → editar y borrar (solo el autor)\n *   · `POST/DELETE /comments/:id/like` → me gusta del comentario (optimista)\n *\n * Qué se arregló respecto a la primera versión (avisos del dueño):\n *   · «Responder» ahora **se sabe a qué comentario responde**: se envía\n *     `parentId`, la respuesta se pinta indentada y con «→ @Nombre», y el\n *     comentario padre enseña «Ver N respuestas».\n *   · Se puede **editar** y **eliminar** el propio comentario.\n *   · Tocar el **avatar o el nombre** abre el perfil de esa persona.\n */\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, Image, KeyboardAvoidingView, Modal, Platform,\n  Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Heart, MessageCircle, Pencil, Plus, Send, Trash2, X } from 'lucide-react-native';\nimport { absUrl } from '../../api/config';\nimport { lifebookApi, lifebookActionsApi, type LbCommentItem, type LbPostBase } from '../../api/lifebook';\nimport {\n  comentariosConAdjuntoApi, type LbComentarioConAdjunto,\n} from '../../api/lifebookComentarios';\nimport type { HomeAd } from '../../api/ads';\nimport { ETIQUETA_PUBLICACION, PublicacionTarjeta } from './PublicacionTarjeta';\nimport { TarjetaAnuncio } from './TarjetaAnuncio';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst PAGE = 30;\n\nexport interface CommentsSheetProps {\n  visible: boolean;\n  onClose: () => void;\n  postId: string;\n  /** Color del tipo de publicación (avatares sin foto). */\n  tint: string;\n  allowComments: boolean;\n  meId?: string | null;\n  title?: string;\n  placeholder: string;\n  onCountChange?: (total: number) => void;\n  onSent?: () => void;\n  /**\n   * Opacidad del velo que tapa el fondo. Por defecto 0.45, que es lo correcto cuando\n   * debajo hay una pantalla normal (el detalle de la publicación): oscurece para que la\n   * hoja se lea y para que se note que hay algo detrás.\n   *\n   * El feed inmersivo pasa **0**: ahí debajo hay un VÍDEO REPRODUCIÉNDOSE, y taparlo con\n   * un velo es justo lo contrario de lo que se quiere. En 小红书/TikTok el vídeo se queda\n   * a plena luz mientras se leen los comentarios.\n   */\n  dimBackdrop?: number;\n  /**\n   * Altura máxima de la hoja (porcentaje de la pantalla). Por defecto 80, que en el\n   * detalle está bien porque no hay nada que preservar debajo.\n   *\n   * El feed inmersivo pasa un valor menor para DEJAR SITIO AL VÍDEO: si la hoja puede\n   * crecer hasta el 80 %, con muchos comentarios tapa el vídeo entero y el usuario deja de\n   * estar viendo un vídeo para estar viendo una lista. Es lo que se corrigió.\n   */\n  maxHeightPct?: number;\n}\n\nfunction commentTimeAgo(value?: string | null) {\n  if (!value) return '';\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) return '';\n  const mins = Math.max(0, Math.floor((Date.now() - date.getTime()) / 60000));\n  if (mins < 1) return 'ahora';\n  if (mins < 60) return `${mins} min`;\n  const hours = Math.floor(mins / 60);\n  if (hours < 24) return `${hours} h`;\n  const days = Math.floor(hours / 24);\n  if (days < 7) return `${days} d`;\n  return date.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });\n}\n\n/** Fila de comentario o respuesta (con cita del padre y acciones del autor). */\nexport function CommentRow({ c, tint, colors, meId, onLike, onReply, onEdit, onDelete, isReply }: {\n  c: LbCommentItem;\n  tint: string;\n  colors: any;\n  meId?: string | null;\n  onLike: () => void;\n  onReply: () => void;\n  onEdit?: () => void;\n  onDelete?: () => void;\n  /** Las respuestas van indentadas y algo más pequeñas. */\n  isReply?: boolean;\n}) {\n  const router = useRouter();\n  const name = c.author?.fullName?.trim() || 'Usuario';\n  const avatar = c.author?.avatarUrl ? absUrl(c.author.avatarUrl) : '';\n  const initial = name.slice(0, 1).toUpperCase() || 'U';\n  const likes = c.likes ?? 0;\n  const mine = !!meId && c.author?.id === meId;\n  const size = isReply ? 28 : 34;\n\n  const openProfile = () => {\n    if (c.author?.id) router.push({ pathname: '/lifebook-user', params: { id: c.author.id } } as never);\n  };\n\n  return (\n    <View style={{ flexDirection: 'row', gap: espaciado.e10, paddingVertical: isReply ? 7 : 10, paddingLeft: isReply ? 26 : 0 }}>\n      <Pressable onPress={openProfile} accessibilityLabel={`Perfil de ${name}`} hitSlop={6}>\n        {avatar ? (\n          <Image source={{ uri: avatar }} style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: alpha(colors.textPrimary, 0.08) }} />\n        ) : (\n          <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: alpha(tint, 0.16), alignItems: 'center', justifyContent: 'center' }}>\n            <Text style={{ color: tint, fontWeight: '900', fontSize: isReply ? 12 : 13 }}>{initial}</Text>\n          </View>\n        )}\n      </Pressable>\n\n      <View style={{ flex: 1 }}>\n        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, flex: 1 }}>\n            <Pressable onPress={openProfile} hitSlop={6}>\n              <Text numberOfLines={1} style={{ fontSize: isReply ? 12 : 12.5, fontWeight: '800', color: colors.textSecondary }}>{name}</Text>\n            </Pressable>\n            {mine ? (\n              <View style={{ backgroundColor: alpha(colors.primary, 0.12), borderRadius: radios.full, paddingHorizontal: espaciado.e6, paddingVertical: 1 }}>\n                <Text style={{ color: colors.primary, fontSize: 9.5, fontWeight: '900' }}>TÚ</Text>\n              </View>\n            ) : null}\n          </View>\n          <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>\n            {commentTimeAgo(c.createdAt)}{c.editedAt ? ' · editado' : ''}\n          </Text>\n        </View>\n\n        {/* A quién responde: sin esto no se sabía de qué comentario era la respuesta */}\n        {isReply && c.replyToName ? (\n          <Text style={{ fontSize: tipografia.caption, color: colors.primary, marginTop: espaciado.e2, fontWeight: '700' }}>\n            → {c.replyToName}\n          </Text>\n        ) : null}\n\n        <Text style={{ fontSize: isReply ? 13.5 : 14, lineHeight: isReply ? 19 : 20, color: colors.textPrimary, marginTop: espaciado.e3 }}>\n          {c.body}\n        </Text>\n\n        {/*\n          Publicación que el comentario lleva DENTRO (una nota, un vídeo, una venta…).\n          Solo se pinta si el servidor la mandó: cuando quien mira no puede ver la\n          publicación adjunta, `ref` llega `null` a propósito (no se filtra ni el título),\n          y cuando el original se borra, `ref` también vuelve a `null` — así nunca queda\n          un enlace roto ni una tarjeta que lleva a ningún sitio.\n        */}\n        {(c as LbComentarioConAdjunto).ref ? (\n          <PublicacionTarjeta data={(c as LbComentarioConAdjunto).ref!} tint={tint} colors={colors} compacta={isReply} />\n        ) : null}\n\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e14, marginTop: espaciado.e6 }}>\n          <Pressable onPress={onReply} hitSlop={8} accessibilityLabel={`Responder a ${name}`}>\n            <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textSecondary }}>Responder</Text>\n          </Pressable>\n          {mine && onEdit ? (\n            <Pressable onPress={onEdit} hitSlop={8} accessibilityLabel=\"Editar mi comentario\" style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3 }}>\n              <Pencil size={11} color={colors.textSecondary} />\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.textSecondary }}>Editar</Text>\n            </Pressable>\n          ) : null}\n          {mine && onDelete ? (\n            <Pressable onPress={onDelete} hitSlop={8} accessibilityLabel=\"Eliminar mi comentario\" style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3 }}>\n              <Trash2 size={11} color={colors.danger} />\n              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: colors.danger }}>Eliminar</Text>\n            </Pressable>\n          ) : null}\n        </View>\n      </View>\n\n      <Pressable\n        onPress={onLike}\n        hitSlop={8}\n        accessibilityLabel={`Me gusta del comentario${likes ? `, ${likes}` : ''}`}\n        style={{ alignItems: 'center', justifyContent: 'flex-start', paddingTop: espaciado.e4, minWidth: 28 }}\n      >\n        <Heart size={16} color={c.likedByMe ? brand.like : colors.textSecondary} fill={c.likedByMe ? brand.like : 'transparent'} />\n        {likes > 0 ? (\n          <Text style={{ marginTop: espaciado.e3, fontSize: 10.5, fontWeight: '800', color: colors.textSecondary }}>{likes}</Text>\n        ) : null}\n      </Pressable>\n    </View>\n  );\n}\n\nexport function CommentsSheet({\n  visible, onClose, postId, tint, allowComments, meId, title = 'Comentarios',\n  placeholder, onCountChange, onSent,\n  // Valores por defecto = el comportamiento de siempre (el detalle no cambia nada).\n  dimBackdrop = 0.45, maxHeightPct = 80,\n}: CommentsSheetProps) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n\n  const [comments, setComments] = useState<LbCommentItem[]>([]);\n  const [replies, setReplies] = useState<Record<string, LbCommentItem[]>>({});\n  const [openReplies, setOpenReplies] = useState<Record<string, boolean>>({});\n  const [total, setTotal] = useState(0);\n  const [cursor, setCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [draft, setDraft] = useState('');\n  const [sending, setSending] = useState(false);\n  const [notice, setNotice] = useState('');\n  /**\n   * Comentario al que estoy respondiendo. Como en YouTube, la caja de respuesta\n   * aparece **debajo de ese comentario** (no al final) y la respuesta se envía\n   * con `parentId`, así que queda colgando del comentario correcto.\n   */\n  const [replyTo, setReplyTo] = useState<{ id: string; name: string } | null>(null);\n  const [replyDraft, setReplyDraft] = useState('');\n  /** Comentario que estoy editando. */\n  const [editing, setEditing] = useState<{ id: string; text: string } | null>(null);\n  const listRef = useRef<FlatList<LbCommentItem>>(null);\n\n  /**\n   * Publicación que se va a adjuntar al comentario que se está escribiendo.\n   *\n   * Guarda solo `id` y `title`: la tarjeta de verdad la devuelve el servidor al crear el\n   * comentario (con su tipo, su miniatura y **su autor**). Así no hay dos formas de armar\n   * una tarjeta ni se inventa nada en el cliente.\n   */\n  const [adjunto, setAdjunto] = useState<{ id: string; title: string | null } | null>(null);\n  const [pickerOpen, setPickerOpen] = useState(false);\n  const [misPosts, setMisPosts] = useState<LbPostBase[] | null>(null);\n\n  /**\n   * Publicidad dentro de los comentarios (lo de WeChat). La manda el servidor en la\n   * primera página y `null` cuando no toca (autor de la publicación, comentarios\n   * cerrados, hilo de menos de 3 comentarios, o sin anuncio para su ciudad). No es un\n   * comentario: no cuenta en el total ni se mezcla con la lista.\n   */\n  const [ad, setAd] = useState<HomeAd | null>(null);\n\n  /** Abre el selector de MIS publicaciones (se cargan una vez y se recuerdan). */\n  const abrirSelector = useCallback(async () => {\n    if (!meId) return;\n    setPickerOpen(true);\n    if (misPosts) return;\n    try {\n      const page = await lifebookApi.userPosts(meId, { limit: 20 });\n      setMisPosts(page.posts ?? []);\n    } catch {\n      setMisPosts([]);\n    }\n  }, [meId, misPosts]);\n\n  /** Chip «Adjuntando: …» con su aspa. Lo usan las DOS cajas (comentario y respuesta). */\n  const chipAdjunto = () => (adjunto ? (\n    <View style={{\n      flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginBottom: espaciado.e7,\n      backgroundColor: alpha(colors.primary, 0.10), borderRadius: radios.md, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e6,\n    }}>\n      <Text numberOfLines={1} style={{ flex: 1, fontSize: tipografia.caption, fontWeight: '800', color: colors.primary }}>\n        Adjuntando: {adjunto.title?.trim() || 'publicación'}\n      </Text>\n      <Pressable onPress={() => setAdjunto(null)} hitSlop={8} accessibilityLabel=\"Quitar la publicación adjunta\">\n        <X size={13} color={colors.primary} />\n      </Pressable>\n    </View>\n  ) : null);\n\n  const cb = useRef({ onCountChange, onSent });\n  cb.current = { onCountChange, onSent };\n\n  const alertText = (t: string) => { setNotice(t); setTimeout(() => setNotice(''), 2600); };\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    try {\n      // Se pide con el envoltorio propio (no con `lifebookApi.postComments`) porque la\n      // respuesta trae además `ad`: la publicidad dentro de los comentarios, que el\n      // servidor decide (nunca en la primera visita del autor, nunca con los\n      // comentarios cerrados, nunca en hilos cortos) y que llega solo en la 1ª página.\n      const page = await comentariosConAdjuntoApi.pagina(postId, { limit: PAGE });\n      setComments([...(page.comments ?? [])].reverse());   // más nuevos arriba\n      setCursor(page.nextCursor ?? null);\n      setAd(page.ad ?? null);\n      const n = Number(page.total ?? (page.comments ?? []).length);\n      setTotal(n);\n      cb.current.onCountChange?.(n);\n    } catch {\n      setComments([]);\n    } finally { setLoading(false); }\n  }, [postId]);\n\n  useEffect(() => {\n    if (visible) {\n      setDraft(''); setReplyTo(null); setEditing(null); setReplies({}); setOpenReplies({});\n      setAd(null);\n      load();\n    }\n  }, [visible, load]);\n\n  const loadMore = async () => {\n    if (!cursor || loadingMore) return;\n    setLoadingMore(true);\n    try {\n      const page = await comentariosConAdjuntoApi.pagina(postId, { limit: PAGE, cursor });\n      setComments((prev) => [...prev, ...[...(page.comments ?? [])].reverse()]);\n      setCursor(page.nextCursor ?? null);\n    } catch { /* se reintenta al volver a bajar */ }\n    finally { setLoadingMore(false); }\n  };\n\n  const toggleReplies = async (id: string) => {\n    const isOpen = !!openReplies[id];\n    setOpenReplies((prev) => ({ ...prev, [id]: !isOpen }));\n    if (isOpen || replies[id]) return;\n    try {\n      const res = await lifebookApi.commentReplies(id);\n      setReplies((prev) => ({ ...prev, [id]: res.replies ?? [] }));\n    } catch { /* silencioso */ }\n  };\n\n  const toggleCommentLike = async (id: string, list: 'root' | 'reply', parentId?: string) => {\n    const source = list === 'root' ? comments : (replies[parentId ?? ''] ?? []);\n    const target = source.find((c) => c.id === id);\n    const was = !!target?.likedByMe;\n    const patch = (arr: LbCommentItem[]) => arr.map((c) => (c.id === id\n      ? { ...c, likedByMe: !was, likes: Math.max(0, (c.likes ?? 0) + (was ? -1 : 1)) }\n      : c));\n    if (list === 'root') setComments(patch);\n    else setReplies((prev) => ({ ...prev, [parentId ?? '']: patch(prev[parentId ?? ''] ?? []) }));\n    try { await lifebookApi.toggleCommentLike(id, !was); }\n    catch {\n      const undo = (arr: LbCommentItem[]) => arr.map((c) => (c.id === id\n        ? { ...c, likedByMe: was, likes: Math.max(0, (c.likes ?? 0) + (was ? 1 : -1)) }\n        : c));\n      if (list === 'root') setComments(undo);\n      else setReplies((prev) => ({ ...prev, [parentId ?? '']: undo(prev[parentId ?? ''] ?? []) }));\n    }\n  };\n\n  const submit = async () => {\n    const text = editing ? editing.text.trim() : draft.trim();\n    if (!text || sending) return;\n    setSending(true);\n    try {\n      if (editing) {\n        const res = await lifebookApi.editComment(editing.id, text);\n        setComments((prev) => prev.map((c) => (c.id === editing.id ? { ...c, body: text, editedAt: res.editedAt } : c)));\n        setReplies((prev) => Object.fromEntries(Object.entries(prev).map(([k, arr]) => [\n          k, arr.map((c) => (c.id === editing.id ? { ...c, body: text, editedAt: res.editedAt } : c)),\n        ])) as Record<string, LbCommentItem[]>);\n        setEditing(null);\n      } else {\n        // El mismo endpoint con o sin adjunto: con adjunto se manda `attachPostId`.\n        // El texto sigue siendo obligatorio aunque se adjunte (si el original se borra,\n        // el comentario se sigue leyendo entero).\n        const nuevo = adjunto\n          ? await comentariosConAdjuntoApi.addComment(postId, text, undefined, adjunto.id)\n          : await lifebookActionsApi.addComment(postId, text);\n        setComments((prev) => [nuevo, ...prev]);\n        setTotal((n) => {\n          cb.current.onCountChange?.(n + 1);\n          return n + 1;\n        });\n        setDraft('');\n        setAdjunto(null);\n        cb.current.onSent?.();\n      }\n    } catch (e) {\n      alertText(e instanceof Error ? e.message : 'No se pudo guardar el comentario.');\n    } finally { setSending(false); }\n  };\n\n  /**\n   * Envía una RESPUESTA al comentario que se está respondiendo. El texto va con\n   * el prefijo `@nombre` (como YouTube), que es lo que el servidor guarda como\n   * mención; y con `parentId` queda colgando de ese comentario.\n   */\n  const submitReply = async () => {\n    const target = replyTo;\n    const text = replyDraft.trim();\n    if (!target || !text || sending) return;\n    setSending(true);\n    try {\n      const cuerpo = `@${target.name} ${text}`;\n      const nuevo = adjunto\n        ? await comentariosConAdjuntoApi.addComment(postId, cuerpo, target.id, adjunto.id)\n        : await lifebookActionsApi.addComment(postId, cuerpo, target.id);\n      setReplies((prev) => ({ ...prev, [target.id]: [...(prev[target.id] ?? []), { ...nuevo, replyToName: target.name }] }));\n      setOpenReplies((prev) => ({ ...prev, [target.id]: true }));\n      setComments((prev) => prev.map((c) => (c.id === target.id ? { ...c, repliesCount: (c.repliesCount ?? 0) + 1 } : c)));\n      setTotal((n) => {\n        cb.current.onCountChange?.(n + 1);\n        return n + 1;\n      });\n      setReplyDraft('');\n      setReplyTo(null);\n      setAdjunto(null);\n      cb.current.onSent?.();\n    } catch (e) {\n      alertText(e instanceof Error ? e.message : 'No se pudo enviar la respuesta.');\n    } finally { setSending(false); }\n  };\n\n  const confirmDelete = (c: LbCommentItem) => {\n    Alert.alert('Eliminar comentario', 'Se borrará tu comentario y sus respuestas.', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Eliminar', style: 'destructive',\n        onPress: async () => {\n          try {\n            const res = await lifebookApi.deleteComment(c.id);\n            setComments((prev) => prev.filter((x) => x.id !== c.id));\n            setTotal((n) => {\n              const next = Math.max(0, res.commentsLeft ?? n - 1);\n              cb.current.onCountChange?.(next);\n              return next;\n            });\n            setReplies((prev) => {\n              const copy = { ...prev };\n              delete copy[c.id];\n              return copy;\n            });\n            cb.current.onSent?.();\n          } catch (e) {\n            alertText(e instanceof Error ? e.message : 'No se pudo eliminar.');\n          }\n        },\n      },\n    ]);\n  };\n\n  const renderComment = (item: LbCommentItem) => {\n    const isEditing = editing?.id === item.id;\n    return (\n      <View>\n        {isEditing ? (\n          <View style={{ paddingVertical: espaciado.e10 }}>\n            <TextInput\n              value={editing.text}\n              onChangeText={(t) => setEditing({ id: item.id, text: t })}\n              multiline\n              maxLength={1000}\n              autoFocus\n              style={{\n                color: colors.textPrimary, fontSize: tipografia.body, minHeight: 40,\n                backgroundColor: alpha(colors.textPrimary, 0.06), borderRadius: radios.md, padding: espaciado.e10,\n              }}\n            />\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n              <Pressable onPress={() => setEditing(null)} style={{ flex: 1, alignItems: 'center', paddingVertical: espaciado.e8 }}>\n                <Text style={{ color: colors.textSecondary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\n              </Pressable>\n              <Pressable\n                onPress={submit}\n                accessibilityLabel=\"Guardar cambios del comentario\"\n                style={{ flex: 1.4, alignItems: 'center', paddingVertical: espaciado.e8, backgroundColor: colors.primary, borderRadius: radios.full }}\n              >\n                <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>Guardar</Text>\n              </Pressable>\n            </View>\n          </View>\n        ) : (\n          <CommentRow\n            c={item}\n            tint={tint}\n            colors={colors}\n            meId={meId}\n            onLike={() => toggleCommentLike(item.id, 'root')}\n            onReply={() => { setReplyTo({ id: item.id, name: item.author?.fullName ?? 'Usuario' }); setReplyDraft(''); }}\n            onEdit={() => setEditing({ id: item.id, text: item.body })}\n            onDelete={() => confirmDelete(item)}\n          />\n        )}\n\n        {/* Caja de respuesta EN LÍNEA, justo debajo del comentario (como YouTube) */}\n        {replyTo?.id === item.id ? (\n          <View style={{\n            marginLeft: 44, marginBottom: espaciado.e10, paddingLeft: espaciado.e10,\n            borderLeftWidth: 2, borderLeftColor: alpha(colors.primary, 0.35),\n          }}>\n            {/* A quién se responde: AQUÍ, en su propia línea.\n                Antes el `@nombre` iba DENTRO de la fila del campo, y con un nombre largo\n                («Administrador EG Route Plan», 28 caracteres) se comía el ancho: al campo\n                le quedaban ~50 dp, así que **lo que se escribía no se veía** y el botón de\n                enviar quedaba apretujado contra el borde. El dueño lo describió tal cual.\n                `numberOfLines={1}` para que un nombre larguísimo recorte en vez de empujar\n                el campo fuera de la pantalla. */}\n            <Text numberOfLines={1} style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800', marginBottom: espaciado.e6 }}>\n              Respondiendo a @{replyTo.name}\n            </Text>\n            {chipAdjunto()}\n            <View style={{\n              flexDirection: 'row', alignItems: 'flex-end', gap: espaciado.e8,\n              backgroundColor: alpha(colors.textPrimary, 0.06), borderRadius: 20,\n              paddingLeft: espaciado.e6, paddingRight: espaciado.e6, paddingVertical: espaciado.e5,\n            }}>\n              {meId ? (\n                <Pressable\n                  onPress={abrirSelector}\n                  disabled={sending}\n                  hitSlop={6}\n                  accessibilityLabel=\"Adjuntar una publicación a mi respuesta\"\n                  style={{\n                    width: 32, height: 32, borderRadius: radios.lg,\n                    backgroundColor: adjunto ? alpha(colors.primary, 0.18) : alpha(colors.textPrimary, 0.08),\n                    alignItems: 'center', justifyContent: 'center',\n                  }}\n                >\n                  <Plus size={16} color={adjunto ? colors.primary : colors.textSecondary} />\n                </Pressable>\n              ) : null}\n              <TextInput\n                value={replyDraft}\n                onChangeText={setReplyDraft}\n                placeholder=\"Añade una respuesta…\"\n                placeholderTextColor={colors.textSecondary}\n                multiline\n                maxLength={1000}\n                autoFocus\n                style={{ flex: 1, maxHeight: 90, minHeight: 34, color: colors.textPrimary, fontSize: tipografia.body, paddingVertical: espaciado.e6 }}\n              />\n              {/* 36 en vez de 32: el botón de enviar es la acción de esta caja y estaba\n                  escondido. Es lo único que empuja la fila, y el campo se queda con todo\n                  el resto del ancho. */}\n              <Pressable\n                onPress={submitReply}\n                disabled={!replyDraft.trim() || sending}\n                accessibilityLabel=\"Enviar respuesta\"\n                style={{\n                  width: 36, height: 36, borderRadius: 18,\n                  backgroundColor: replyDraft.trim() ? colors.primary : alpha(colors.textPrimary, 0.12),\n                  alignItems: 'center', justifyContent: 'center',\n                }}\n              >\n                {sending ? <ActivityIndicator size=\"small\" color={brand.white} /> : <Send size={16} color={replyDraft.trim() ? brand.white : colors.textSecondary} />}\n              </Pressable>\n            </View>\n            <Pressable onPress={() => { setReplyTo(null); setReplyDraft(''); }} style={{ paddingVertical: espaciado.e6 }} accessibilityLabel=\"Cancelar respuesta\">\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }}>Cancelar</Text>\n            </Pressable>\n          </View>\n        ) : null}\n\n        {(item.repliesCount ?? 0) > 0 ? (\n          <Pressable onPress={() => toggleReplies(item.id)} style={{ paddingLeft: 44, paddingBottom: espaciado.e8 }} accessibilityLabel=\"Ver respuestas\">\n            <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>\n              {openReplies[item.id] ? 'Ocultar respuestas' : `Ver ${item.repliesCount} respuesta${item.repliesCount === 1 ? '' : 's'}`}\n            </Text>\n          </Pressable>\n        ) : null}\n\n        {openReplies[item.id] ? (\n          <View style={{\n            marginLeft: 17, paddingLeft: espaciado.e14,\n            borderLeftWidth: 2, borderLeftColor: alpha(colors.textPrimary, 0.10),\n          }}>\n            {(replies[item.id] ?? []).length === 0 ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e8 }} />\n            ) : (\n              (replies[item.id] ?? []).map((r) => (\n                <View key={r.id}>\n                  <CommentRow\n                    c={r}\n                    tint={tint}\n                    colors={colors}\n                    meId={meId}\n                    isReply\n                    onLike={() => toggleCommentLike(r.id, 'reply', item.id)}\n                    onReply={() => { setReplyTo({ id: item.id, name: r.author?.fullName ?? 'Usuario' }); setReplyDraft(''); }}\n                    onEdit={() => setEditing({ id: r.id, text: r.body })}\n                    onDelete={() => confirmDelete(r)}\n                  />\n                  {replyTo?.id === item.id && replyTo.name === (r.author?.fullName ?? 'Usuario') ? (\n                    <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800', paddingLeft: 38, paddingBottom: espaciado.e6 }}>\n                      Escribiendo la respuesta arriba ↑\n                    </Text>\n                  ) : null}\n                </View>\n              ))\n            )}\n          </View>\n        ) : null}\n      </View>\n    );\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <KeyboardAvoidingView style={{ flex: 1, justifyContent: 'flex-end' }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n        {/* El velo sigue ocupando toda la pantalla para poder cerrar tocando fuera, pero\n            su OPACIDAD es configurable: en 0 es invisible y no tapa el vídeo de debajo. */}\n        <Pressable style={{ ...StyleSheet.absoluteFillObject, backgroundColor: `rgba(0,0,0,${dimBackdrop})` }} onPress={onClose} />\n\n        <View style={{\n          backgroundColor: colors.surface,\n          borderTopLeftRadius: 26,\n          borderTopRightRadius: 26,\n          maxHeight: `${maxHeightPct}%`,\n          paddingBottom: insets.bottom + 8,\n        }}>\n          <View style={{ height: 4, width: 44, borderRadius: radios.full, backgroundColor: alpha(colors.textPrimary, 0.14), alignSelf: 'center', marginTop: espaciado.e10 }} />\n\n          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e10 }}>\n            <Text style={{ fontSize: 15, fontWeight: '900', color: colors.textPrimary }}>{title} · {total}</Text>\n            <Pressable\n              onPress={onClose}\n              hitSlop={10}\n              accessibilityLabel=\"Cerrar comentarios\"\n              style={{ width: 32, height: 32, borderRadius: radios.lg, backgroundColor: alpha(colors.textPrimary, 0.07), alignItems: 'center', justifyContent: 'center' }}\n            >\n              <X size={18} color={colors.textPrimary} />\n            </Pressable>\n          </View>\n\n          {loading ? (\n            <ActivityIndicator color={colors.primary} style={{ marginVertical: 34 }} />\n          ) : (\n            <FlatList\n              ref={listRef}\n              data={comments}\n              keyExtractor={(item) => item.id}\n              keyboardShouldPersistTaps=\"handled\"\n              style={{ flexGrow: 0, flexShrink: 1 }}\n              contentContainerStyle={{ paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8 }}\n              onEndReached={loadMore}\n              onEndReachedThreshold={0.4}\n              ListEmptyComponent={\n                <View style={{ paddingVertical: 34, alignItems: 'center' }}>\n                  <MessageCircle size={28} color={colors.textSecondary} />\n                  <Text style={{ marginTop: espaciado.e10, color: colors.textSecondary, fontWeight: '800' }}>\n                    {allowComments ? 'Todavía no hay comentarios' : 'Los comentarios están desactivados'}\n                  </Text>\n                  <Text style={{ marginTop: espaciado.e4, color: alpha(colors.textSecondary, 0.8), fontSize: tipografia.caption, textAlign: 'center' }}>\n                    {allowComments\n                      ? 'Escribe el primero para abrir la conversación.'\n                      : 'El autor desactivó los comentarios de esta publicación.'}\n                  </Text>\n                </View>\n              }\n              ListFooterComponent={loadingMore ? <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e12 }} /> : null}\n              renderItem={({ item, index }) => (\n                <>\n                  {renderComment(item)}\n                  {/*\n                    Publicidad DENTRO de los comentarios (lo de WeChat): después del\n                    TERCER comentario, nunca antes — primero se lee la conversación — y\n                    solo si el servidor la mandó. Se pinta con su etiqueta «PUBLICIDAD»,\n                    que no es opcional: sin ella el anuncio se lee como el comentario de\n                    alguien.\n                  */}\n                  {ad && index === 2 ? <TarjetaAnuncio ad={ad} tint={tint} colors={colors} /> : null}\n                </>\n              )}\n            />\n          )}\n\n          {notice ? (\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e6 }}>{notice}</Text>\n          ) : null}\n\n          {/*\n            El compositor de comentario NUEVO se oculta mientras se está RESPONDIENDO.\n\n            ANTES NO SE OCULTABA, y además decía «Responde a {name} en su comentario ↑»\n            mientras su botón de enviar llama SIEMPRE a `submit`, que crea un comentario de\n            PRIMER NIVEL (sin `parentId`). O sea que la caja avisaba de una cosa y hacía\n            otra: quien escribía ahí creyendo que respondía publicaba un comentario suelto,\n            que es exactamente el fallo que reportó el dueño.\n\n            El sitio para responder es la caja EN LÍNEA del comentario (más abajo en\n            `renderComment`), que sí manda `parentId` y sale con el foco puesto al pulsar\n            «Responder». Es el mismo criterio que ya se usaba al EDITAR, que también oculta\n            este compositor: **un solo sitio donde escribir a la vez**.\n          */}\n          {allowComments && !editing && !replyTo ? (\n            <View style={{ borderTopWidth: 1, borderTopColor: colors.border, paddingHorizontal: espaciado.e12, paddingTop: espaciado.e10, paddingBottom: espaciado.e6 }}>\n              {chipAdjunto()}\n              <View style={{\n                flexDirection: 'row', alignItems: 'flex-end', gap: espaciado.e8,\n                backgroundColor: alpha(colors.textPrimary, 0.07), borderRadius: 24,\n                paddingLeft: espaciado.e6, paddingRight: espaciado.e6, paddingVertical: espaciado.e6,\n              }}>\n                {/* Adjuntar una publicación: el «+» va a la izquierda del campo, como el\n                    botón de adjuntar de un chat. Solo aparece si sabemos quién eres\n                    (sin `meId` no hay «mis publicaciones» que ofrecer). */}\n                {meId ? (\n                  <Pressable\n                    onPress={abrirSelector}\n                    disabled={sending}\n                    hitSlop={6}\n                    accessibilityLabel=\"Adjuntar una publicación a mi comentario\"\n                    style={{\n                      width: 34, height: 34, borderRadius: 17,\n                      backgroundColor: adjunto ? alpha(colors.primary, 0.18) : alpha(colors.textPrimary, 0.08),\n                      alignItems: 'center', justifyContent: 'center',\n                    }}\n                  >\n                    <Plus size={17} color={adjunto ? colors.primary : colors.textSecondary} />\n                  </Pressable>\n                ) : null}\n                <TextInput\n                  value={draft}\n                  onChangeText={setDraft}\n                  placeholder={placeholder}\n                  placeholderTextColor={colors.textSecondary}\n                  multiline\n                  maxLength={1000}\n                  style={{ flex: 1, maxHeight: 100, minHeight: 34, color: colors.textPrimary, fontSize: tipografia.body, paddingVertical: espaciado.e6 }}\n                />\n                <Pressable\n                  onPress={submit}\n                  disabled={!draft.trim() || sending}\n                  accessibilityLabel=\"Enviar comentario\"\n                  style={{\n                    width: 34, height: 34, borderRadius: 17,\n                    backgroundColor: draft.trim() ? colors.primary : alpha(colors.textPrimary, 0.12),\n                    alignItems: 'center', justifyContent: 'center',\n                  }}\n                >\n                  {sending\n                    ? <ActivityIndicator size=\"small\" color={brand.white} />\n                    : <Send size={16} color={draft.trim() ? brand.white : colors.textSecondary} />}\n                </Pressable>\n              </View>\n            </View>\n          ) : !allowComments ? (\n            <View style={{ borderTopWidth: 1, borderTopColor: colors.border, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, alignItems: 'center' }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Los comentarios están desactivados</Text>\n            </View>\n          ) : null}\n        </View>\n      </KeyboardAvoidingView>\n\n      {/*\n        Selector de MIS publicaciones para adjuntar. Va DENTRO de este mismo modal (una\n        capa absoluta, no otro modal anidado): en Android los modales anidados se pelean\n        por el foco del teclado, y aquí ya hay un teclado abierto detrás.\n        Se listan solo mis publicaciones, por la misma ruta que usa el chat para compartir\n        una nota (`/lifebook/users/:id/posts`), así no hay dos maneras de listar lo mío.\n      */}\n      {pickerOpen ? (\n        /*\n          `zIndex` + `elevation` NO son decorativos: sin ellos, en Android el compositor\n          de la hoja (que va después en el árbol y con elevación) se pintaba POR ENCIMA de\n          la parte baja de este selector, y las últimas filas de la lista no se podían\n          tocar — se comía el toque. Se comprobó midiendo: pulsar la última fila no\n          seleccionaba nada y pulsar una del medio sí.\n        */\n        <View style={[StyleSheet.absoluteFillObject, { zIndex: 20, elevation: 20 }]}>\n          <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' }} onPress={() => setPickerOpen(false)} />\n          <View style={{\n            position: 'absolute', left: 0, right: 0, bottom: 0,\n            backgroundColor: colors.surface,\n            borderTopLeftRadius: 22, borderTopRightRadius: 22,\n            maxHeight: '62%', paddingBottom: insets.bottom + 10,\n          }}>\n            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e14, paddingBottom: espaciado.e6 }}>\n              <Text style={{ fontSize: 15, fontWeight: '900', color: colors.textPrimary }}>Adjuntar una publicación</Text>\n              <Pressable onPress={() => setPickerOpen(false)} hitSlop={10} accessibilityLabel=\"Cerrar el selector\">\n                <X size={18} color={colors.textSecondary} />\n              </Pressable>\n            </View>\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e8 }}>\n              Se adjunta como referencia: si la borras, tu comentario se queda tal cual.\n            </Text>\n\n            {misPosts === null ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e26 }} />\n            ) : misPosts.length === 0 ? (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e22 }}>\n                Todavía no has publicado nada.\n              </Text>\n            ) : (\n              <ScrollView style={{ paddingHorizontal: espaciado.e12 }}>\n                {misPosts.map((p) => {\n                  const elegida = adjunto?.id === p.id;\n                  return (\n                    <Pressable\n                      key={p.id}\n                      onPress={() => {\n                        setAdjunto({ id: p.id, title: p.title ?? null });\n                        setPickerOpen(false);\n                      }}\n                      accessibilityLabel={`Adjuntar ${p.title ?? 'publicación'}`}\n                      style={{\n                        flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n                        paddingVertical: espaciado.e11, paddingHorizontal: espaciado.e10, borderRadius: radios.md,\n                        backgroundColor: elegida ? alpha(colors.primary, 0.12) : 'transparent',\n                      }}\n                    >\n                      <View style={{ width: 34, height: 34, borderRadius: 9, backgroundColor: alpha(tint, 0.16), alignItems: 'center', justifyContent: 'center' }}>\n                        <Text style={{ fontSize: 15 }}>\n                          {p.type === 'video' ? '🎬' : p.type === 'sale' ? '🏷️' : p.type === 'podcast' ? '🎙️' : p.type === 'serie' ? '📺' : '📝'}\n                        </Text>\n                      </View>\n                      <View style={{ flex: 1 }}>\n                        <Text numberOfLines={1} style={{ fontSize: tipografia.body, fontWeight: '700', color: colors.textPrimary }}>\n                          {p.title?.trim() || '(sin título)'}\n                        </Text>\n                        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: 1 }}>\n                          {ETIQUETA_PUBLICACION[p.type] ?? 'Publicación'}{elegida ? ' · adjunta' : ''}\n                        </Text>\n                      </View>\n                    </Pressable>\n                  );\n                })}\n              </ScrollView>\n            )}\n          </View>\n        </View>\n      ) : null}\n    </Modal>\n  );\n}\n","/**\n * Comentarios con PUBLICACIÓN ADJUNTA (una nota, un vídeo, una venta…).\n *\n * Vive en su propio fichero por lo mismo que `api/lifebookPostOps.ts`: `api/lifebook.ts`\n * está en la lista de ficheros que el dueño pidió no tocar, y todo esto es ADITIVO (nada\n * de lo que ya hay cambia). La hoja de comentarios solo importa\n * `comentariosConAdjuntoApi`, así que el día que se junten se puede mover allí sin tocar\n * la pantalla.\n *\n * Cómo funciona en el servidor: el comentario guarda una REFERENCIA a la publicación\n * (nunca una copia) y el servidor devuelve la tarjeta ya resuelta en `ref`.\n *   · Si quien mira NO puede ver la publicación adjunta, `ref` llega `null` a propósito:\n *     ni siquiera viaja el título, para no filtrar nada.\n *   · Si borran la publicación adjunta, el comentario SOBREVIVE como texto y `ref` vuelve\n *     a ser `null` (nada de enlaces rotos).\n *   · Solo se puede adjuntar lo que uno puede ver, y nunca la publicación que se está\n *     comentando (el servidor contesta 400 `CANNOT_ATTACH_SELF`).\n *   · El texto sigue siendo obligatorio aunque se adjunte.\n */\nimport { http } from './httpClient';\nimport type { LbCommentItem, LbPostBase } from './lifebook';\nimport type { HomeAd } from './ads';\n\n/** Miniatura de una publicación (misma forma que en el resto del API). */\nexport interface LbAdjuntoMiniatura {\n  id: string | null;\n  url: string;\n}\n\n/** La tarjeta de la publicación que lleva dentro un comentario. */\nexport interface LbAdjuntoRef {\n  id: string;\n  /** note · video · sale · service · serie · podcast · debate … */\n  type: string;\n  title: string | null;\n  /** Extracto corto para pintar. */\n  preview: string;\n  thumb: LbAdjuntoMiniatura | null;\n  /** Solo en las ventas. */\n  priceXaf?: number;\n  /**\n   * De quién es lo adjunto. Sin esto una cita no se puede rastrear (es lo que WeChat\n   * consideró imprescindible al mejorar su «引用»), y además se puede estar adjuntando\n   * algo de otra persona: hay que poder verlo.\n   */\n  author: { id: string; fullName: string | null; avatarUrl: string | null };\n}\n\n/**\n * Comentario con la tarjeta del adjunto. Es `LbCommentItem` más un campo: si no hay\n * adjunto (o no se puede ver), `ref` es `null`.\n */\nexport type LbComentarioConAdjunto = LbCommentItem & { ref?: LbAdjuntoRef | null };\n\n/**\n * Una página de comentarios tal como la devuelve el servidor ahora mismo.\n *\n * `ad` es la **publicidad dentro de los comentarios** (lo de WeChat): el servidor\n * decide si toca y cuál (nunca para el autor, nunca con los comentarios cerrados,\n * nunca en un hilo de menos de 3 comentarios, y segmentada por la ciudad de quien\n * mira). Va en un campo APARTE a propósito: el anuncio **no** es un comentario, así\n * que no cuenta en `total` ni se mezcla con la lista.\n */\nexport interface LbPaginaComentarios {\n  comments: LbComentarioConAdjunto[];\n  nextCursor: string | null;\n  total: number;\n  ad: HomeAd | null;\n}\n\nexport const comentariosConAdjuntoApi = {\n  /**\n   * La página de comentarios **con el adjunto y el anuncio**. Es la misma ruta que\n   * `lifebookApi.postComments` (que no se toca), pero con el tipo completo.\n   */\n  pagina: (postId: string, opts: { limit?: number; cursor?: string } = {}) =>\n    http.get<LbPaginaComentarios>(\n      `/lifebook/posts/${postId}/comments?limit=${opts.limit ?? 30}${opts.cursor ? `&cursor=${encodeURIComponent(opts.cursor)}` : ''}`,\n    ),\n\n  /**\n   * Comenta (o responde) adjuntando una publicación. El texto sigue siendo obligatorio:\n   * así, si algún día borran lo adjunto, el comentario se lee entero.\n   */\n  addComment: (postId: string, text: string, parentId?: string, attachPostId?: string) =>\n    http.post<LbComentarioConAdjunto>(`/lifebook/posts/${postId}/comments`, {\n      text,\n      ...(parentId ? { parentId } : {}),\n      ...(attachPostId ? { attachPostId } : {}),\n    }),\n\n  /**\n   * MIS publicaciones, para el selector del compositor. Es la misma ruta que usa el chat\n   * para compartir una nota, así que no hay dos maneras de listar lo mío.\n   */\n  misPublicaciones: (userId: string, limit = 20) =>\n    http.get<{ posts?: LbPostBase[] }>(`/lifebook/users/${userId}/posts?limit=${limit}`),\n};\n","/**\n * PublicacionTarjeta — la tarjeta de una publicación que va DENTRO de un comentario.\n *\n * Se pinta cuando alguien adjunta una publicación al comentar (una nota, un vídeo, una\n * venta, un podcast…). Es una REFERENCIA a la publicación, no una copia: si el original\n * desaparece, el servidor manda `ref: null` y esta tarjeta simplemente no se pinta, así\n * que nunca queda un enlace roto.\n *\n * POR QUÉ ES UN COMPONENTE APARTE: la publicidad dentro de los comentarios (lo de WeChat)\n * necesita exactamente esta misma tarjeta con una etiqueta «Publicidad» encima. Con la\n * tarjeta en un solo sitio, el día que se haga la publicidad no hay que diseñarla dos veces.\n *\n * Enseña **de quién es** lo adjunto además del título: es lo que WeChat consideró\n * imprescindible al mejorar su «引用» (que una cita se pueda rastrear). El chat, hoy, solo\n * manda título y miniatura.\n */\nimport React from 'react';\nimport { Image, Pressable, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { alpha, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../../api/config';\nimport type { LbAdjuntoRef } from '../../api/lifebookComentarios';\n\n/** Cómo se llama cada tipo de publicación en pantalla (lo usa también el selector). */\nexport const ETIQUETA_PUBLICACION: Record<string, string> = {\n  note: 'Nota',\n  video: 'Vídeo',\n  sale: 'Venta',\n  service: 'Servicio',\n  serie: 'Serie',\n  podcast: 'Podcast',\n  debate: 'Debate',\n  episode: 'Episodio',\n};\n\n/** Un dibujo para cuando la publicación no tiene foto (nunca un hueco vacío). */\nconst DIBUJO: Record<string, string> = {\n  note: '📝',\n  video: '🎬',\n  sale: '🏷️',\n  service: '🛠️',\n  serie: '📺',\n  podcast: '🎙️',\n  debate: '💬',\n  episode: '🎞️',\n};\n\nexport function PublicacionTarjeta({ data, tint, colors, compacta = false }: {\n  data: LbAdjuntoRef;\n  /** Color del tipo de publicación, para los fondos suaves. */\n  tint: string;\n  colors: any;\n  /** Dentro de una respuesta va algo más pequeña. */\n  compacta?: boolean;\n}) {\n  const router = useRouter();\n  const titulo = data.title?.trim() || ETIQUETA_PUBLICACION[data.type] || 'Publicación';\n  const deQuien = data.author?.fullName?.trim() || 'Usuario';\n  const alto = compacta ? 46 : 54;\n\n  /**\n   * Abre la publicación adjunta. Los vídeos se abren en el feed inmersivo (es donde se\n   * ven de verdad, y admite `startId` para arrancar en ese vídeo); lo demás, en su\n   * pantalla de detalle.\n   */\n  const abrir = () => {\n    if (data.type === 'video') {\n      router.push({ pathname: '/lifebook-videos', params: { startId: data.id } } as never);\n      return;\n    }\n    router.push({ pathname: '/lifebook-post/[id]', params: { id: data.id } } as never);\n  };\n\n  const miniatura = data.thumb?.url ? absUrl(data.thumb.url) : '';\n\n  return (\n    <Pressable\n      onPress={abrir}\n      accessibilityLabel={`Abrir ${ETIQUETA_PUBLICACION[data.type] ?? 'publicación'}: ${titulo}, de ${deQuien}`}\n      style={{\n        flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n        marginTop: espaciado.e6, padding: espaciado.e7, borderRadius: radios.md,\n        backgroundColor: alpha(colors.textPrimary, 0.05),\n        borderWidth: 1, borderColor: alpha(colors.textPrimary, 0.08),\n      }}\n    >\n      {miniatura ? (\n        <Image source={{ uri: miniatura }} style={{ width: alto, height: alto, borderRadius: 9, backgroundColor: alpha(colors.textPrimary, 0.08) }} />\n      ) : (\n        <View style={{ width: alto, height: alto, borderRadius: 9, backgroundColor: alpha(tint, 0.16), alignItems: 'center', justifyContent: 'center' }}>\n          <Text style={{ fontSize: compacta ? 17 : 20 }}>{DIBUJO[data.type] ?? '📄'}</Text>\n        </View>\n      )}\n\n      <View style={{ flex: 1 }}>\n        <Text numberOfLines={2} style={{ fontSize: compacta ? 12.5 : 13, fontWeight: '800', color: colors.textPrimary, lineHeight: compacta ? 17 : 18 }}>\n          {titulo}\n        </Text>\n        <Text numberOfLines={1} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>\n          {ETIQUETA_PUBLICACION[data.type] ?? 'Publicación'} · de {deQuien}\n          {data.priceXaf ? ` · ${data.priceXaf.toLocaleString('fr-FR')} XAF` : ''}\n        </Text>\n      </View>\n    </Pressable>\n  );\n}\n","/**\r\n * TarjetaAnuncio — la publicidad que va DENTRO de la zona de comentarios.\r\n *\r\n * Es lo que hace WeChat: un hueco publicitario entre los comentarios, **con su\r\n * etiqueta**. Los datos vienen de `wallet.ads` (el mismo sistema que el banner del\r\n * Home), así que el anuncio ya trae título, subtítulo, emoji o imagen, color, a\r\n * dónde lleva y sus contadores.\r\n *\r\n * Reglas que la app NO tiene que decidir (las decide el servidor): cuándo hay\r\n * anuncio, para quién y de qué ciudad. Si el servidor no manda anuncio, esta\r\n * tarjeta no se pinta y no queda hueco.\r\n *\r\n * Y aquí se cuentan las dos cosas que el anunciante paga:\r\n *   · **impresión** al pintarse (una sola vez por anuncio y pantalla),\r\n *   · **clic** al tocarlo, antes de navegar.\r\n * Los dos endpoints ya existían (`POST /ads/:id/impression` y `/click`) y son los\r\n * mismos que usa el banner del Home, así que no hay dos maneras de contar.\r\n */\r\nimport React, { useEffect } from 'react';\r\nimport { Image, Linking, Pressable, Text, View } from 'react-native';\r\nimport { useRouter } from 'expo-router';\r\nimport { alpha, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\r\nimport { adsApi, type HomeAd } from '../../api/ads';\r\nimport { absUrl } from '../../api/config';\r\nimport { ir as irSeguro } from '../../constants/rutas';\r\n\r\n/** Rutas de la app a las que un anuncio puede llevar. */\r\nconst RUTAS_CONOCIDAS = ['/taxi', '/food', '/alquiler', '/intercity', '/lifebook', '/mercado', '/trabajo'];\r\n\r\n/**\r\n * Anuncios cuya impresión YA se contó en esta sesión.\r\n *\r\n * Va a nivel de MÓDULO y no en un `useRef` del componente a propósito: comprobado en\r\n * el móvil, la tarjeta se vuelve a montar cuando la fila que la contiene se repinta\r\n * (la lista de comentarios), y con el `ref` la impresión se contaba DOS veces. El\r\n * anunciante paga por impresión: contarla dos veces es engañarle.\r\n */\r\nconst impresionesContadas = new Set<string>();\r\n\r\nexport function TarjetaAnuncio({ ad, tint, colors }: { ad: HomeAd; tint: string; colors: any }) {\r\n  const router = useRouter();\r\n\r\n  useEffect(() => {\r\n    if (impresionesContadas.has(ad.id)) return;\r\n    impresionesContadas.add(ad.id);\r\n    adsApi.impression(ad.id).catch(() => {\r\n      // Si falla, se permite reintentar en el próximo montaje (mejor eso que perderla).\r\n      impresionesContadas.delete(ad.id);\r\n    });\r\n  }, [ad.id]);\r\n\r\n  const abrir = () => {\r\n    // El clic se cuenta ANTES de navegar: si el usuario sale de la app, el POST ya\r\n    // salió (no se espera la respuesta para no retrasar el toque).\r\n    adsApi.click(ad.id).catch(() => {});\r\n    const externo = ad.externalUrl?.trim();\r\n    if (externo) { Linking.openURL(externo).catch(() => {}); return; }\r\n    const ruta = ad.targetRoute?.trim();\r\n    if (ruta && RUTAS_CONOCIDAS.includes(ruta)) {\r\n      /* NAVEGACIÓN SEGURA: el enlace lo escribe el anunciante. Se valida contra el mapa de\r\n         rutas, así que una ruta que ya no exista lleva a la pantalla que lo explica en vez de\r\n         dejar la pulsación sin efecto. */\r\n      irSeguro.libre(ruta);\r\n      return;\r\n    }\r\n    // Sin destino utilizable no se navega a ningún sitio: mejor quedarse que abrir\r\n    // una pantalla en blanco.\r\n  };\r\n\r\n  const imagen = ad.imageUrl ? absUrl(ad.imageUrl) : '';\r\n\r\n  return (\r\n    <View style={{ marginTop: espaciado.e8 }}>\r\n      {/* La etiqueta NO es opcional: sin ella el anuncio se lee como un comentario\r\n          de alguien, y eso es engañar a quien lee. */}\r\n      <Text style={{ fontSize: 10, fontWeight: '900', letterSpacing: 0.6, color: colors.textSecondary, marginBottom: espaciado.e4 }}>\r\n        PUBLICIDAD\r\n      </Text>\r\n      <Pressable\r\n        onPress={abrir}\r\n        accessibilityLabel={`Publicidad: ${ad.title}. ${ad.subtitle ?? ''}`}\r\n        style={{\r\n          flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\r\n          padding: espaciado.e9, borderRadius: radios.md,\r\n          backgroundColor: alpha(ad.color?.startsWith('#') ? ad.color : tint, 0.10),\r\n          borderWidth: 1, borderColor: alpha(colors.textPrimary, 0.08),\r\n        }}\r\n      >\r\n        {imagen ? (\r\n          <Image source={{ uri: imagen }} style={{ width: 46, height: 46, borderRadius: 9, backgroundColor: alpha(colors.textPrimary, 0.08) }} />\r\n        ) : (\r\n          <View style={{ width: 46, height: 46, borderRadius: 9, backgroundColor: alpha(colors.textPrimary, 0.06), alignItems: 'center', justifyContent: 'center' }}>\r\n            <Text style={{ fontSize: tipografia.title }}>{ad.emoji ?? '📣'}</Text>\r\n          </View>\r\n        )}\r\n        <View style={{ flex: 1 }}>\r\n          <Text numberOfLines={2} style={{ fontSize: tipografia.body, fontWeight: '800', color: colors.textPrimary, lineHeight: 17 }}>\r\n            {ad.title}\r\n          </Text>\r\n          {ad.subtitle ? (\r\n            <Text numberOfLines={1} style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e2 }}>\r\n              {ad.subtitle}{ad.discountPct ? ` · -${ad.discountPct} %` : ''}\r\n            </Text>\r\n          ) : null}\r\n        </View>\r\n      </Pressable>\r\n    </View>\r\n  );\r\n}\r\n","/**\n * OrderSheet — hoja de compra (03). El dueño decidió que **la compra vive en la\n * barra inferior**, así que el panel «Confirmar pedido» pasa de estar en el\n * cuerpo (donde quedaba fuera de la vista al pulsar abajo) a una hoja inferior.\n *\n * Datos reales:\n *   · `POST /lifebook/posts/:id/order { message?, priceXaf? }` → pedido creado\n *     (solo se manda `priceXaf` si el precio es negociable)\n *   · el precio y si es negociable salen de `post.payload`\n *   · al crearse, el detalle lleva a `/lifebook-orders`\n */\nimport React, { useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, KeyboardAvoidingView, Modal, Platform, Pressable,\n  StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ShoppingCart, X } from 'lucide-react-native';\nimport { lbXaf } from '../../constants/lifebook';\nimport { lifebookOrdersApi } from '../../api/lifebook';\n\nexport function OrderSheet({ visible, onClose, postId, priceXaf, negotiable, onCreated }: {\n  visible: boolean;\n  onClose: () => void;\n  postId: string;\n  priceXaf: number;\n  negotiable: boolean;\n  /** Recibe el nº de pedido y el id para navegar a Pedidos. */\n  onCreated: (orderNo: string, orderId: string) => void;\n}) {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const [msg, setMsg] = useState('');\n  const [price, setPrice] = useState(String(priceXaf || ''));\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState('');\n\n  useEffect(() => {\n    if (visible) { setMsg(''); setPrice(String(priceXaf || '')); setErr(''); }\n  }, [visible, priceXaf]);\n\n  const confirm = async () => {\n    if (busy) return;\n    setBusy(true); setErr('');\n    try {\n      const off = Number(price);\n      const res = await lifebookOrdersApi.create(postId, {\n        message: msg.trim() || undefined,\n        ...(negotiable && Number.isFinite(off) && off > 0 ? { priceXaf: Math.round(off) } : {}),\n      });\n      onCreated(res.orderNo, res.id ?? '');\n    } catch (e) {\n      setErr(e instanceof Error ? e.message : 'No se pudo crear el pedido.');\n    } finally { setBusy(false); }\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <KeyboardAvoidingView style={{ flex: 1, justifyContent: 'flex-end' }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n        <Pressable style={{ ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(0,0,0,0.45)' }} onPress={onClose} />\n\n        <View style={{ backgroundColor: colors.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, paddingBottom: insets.bottom + 14 }}>\n          <View style={{ height: 4, width: 44, borderRadius: radios.full, backgroundColor: alpha(colors.textPrimary, 0.14), alignSelf: 'center', marginTop: espaciado.e10 }} />\n\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e6 }}>\n            <ShoppingCart size={18} color={colors.primary} />\n            <Text style={{ fontSize: 15.5, fontWeight: '900', color: colors.textPrimary, flex: 1 }}>Confirmar pedido</Text>\n            <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar pedido\"\n              style={{ width: 32, height: 32, borderRadius: radios.lg, backgroundColor: alpha(colors.textPrimary, 0.07), alignItems: 'center', justifyContent: 'center' }}>\n              <X size={18} color={colors.textPrimary} />\n            </Pressable>\n          </View>\n\n          <View style={{ paddingHorizontal: espaciado.e16, paddingTop: espaciado.e6 }}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n              Vas a pedir este artículo por <Text style={{ color: colors.primary, fontWeight: '900' }}>{lbXaf(priceXaf)}</Text>\n              {negotiable ? ' · el precio es negociable' : ''}\n            </Text>\n\n            {negotiable ? (\n              <>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12 }}>TU OFERTA (XAF)</Text>\n                <TextInput\n                  value={price}\n                  onChangeText={(t) => setPrice(t.replace(/[^0-9]/g, '').slice(0, 9))}\n                  keyboardType=\"number-pad\"\n                  placeholder=\"Precio en XAF\"\n                  placeholderTextColor={colors.textSecondary}\n                  style={[styles.input, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\n                />\n              </>\n            ) : null}\n\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e12 }}>MENSAJE PARA EL VENDEDOR (opcional)</Text>\n            <TextInput\n              value={msg}\n              onChangeText={setMsg}\n              multiline\n              maxLength={300}\n              placeholder=\"p. ej. ¿Lo puedes entregar en Semu esta tarde?\"\n              placeholderTextColor={colors.textSecondary}\n              style={[styles.input, styles.area, { backgroundColor: colors.surface, color: colors.textPrimary, borderColor: colors.border }]}\n            />\n\n            {err ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>{err}</Text> : null}\n\n            <Pressable\n              onPress={confirm}\n              disabled={busy}\n              accessibilityLabel=\"Enviar pedido\"\n              style={{ borderRadius: radios.full, paddingVertical: espaciado.e14, alignItems: 'center', backgroundColor: busy ? alpha(colors.primary, 0.5) : colors.primary, marginTop: espaciado.e14 }}\n            >\n              {busy\n                ? <ActivityIndicator size=\"small\" color={brand.white} />\n                : <Text style={{ color: brand.white, fontWeight: '900', fontSize: 14.5 }}>Enviar pedido</Text>}\n            </Pressable>\n          </View>\n        </View>\n      </KeyboardAvoidingView>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  input: { borderRadius: 14, borderWidth: 1, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10, fontSize: 14.5, marginTop: espaciado.e6 },\n  area: { minHeight: 70, textAlignVertical: 'top' },\n});\n","/**\n * app/lifebook-product/[id].tsx — FICHA de producto o servicio (Parte 33).\n *\n * Adaptada de la maqueta del dueño a la app real:\n *   · tokens del tema correctos (textPrimary/textSecondary/surface/border…)\n *   · `PrimaryButton/GhostButton` con `title` (no `label`), `Pressable` (no TouchableOpacity)\n *   · `lbXaf()` para el dinero y `absUrl()` para las fotos\n *   · galería con el visor de zoom de la Parte 32 y `expo-image` con caché\n *   · acción principal según el tipo (Comprar · Pedir · Solicitar · Reservar…)\n *\n * La compra real (pedido, entrega y pago) llega en la siguiente parte: hoy el\n * botón abre el CHAT con la tienda y un mensaje ya escrito, que es lo que ya\n * funciona de verdad y no un botón muerto.\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Dimensions, FlatList, Modal, Pressable, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport {\n  Banknote, Building2, CheckCircle2, Clock, Eye, Heart, MapPin, MessageCircle, Package, ShoppingCart,\n  Plane, ShieldCheck, Ship, Store, Truck, Wallet, X,\n} from 'lucide-react-native';\nimport { AuthGate } from '../../core/AuthGate';\nimport { absUrl } from '../../api/config';\nimport { messagesApi } from '../../api/messages';\nimport { commerceApi, avisoStockApi, type LbProduct, type LbProductVariant } from '../../api/commerce';\nimport { carritoApi } from '../../api/lifebookCarrito';\nimport { lbXaf } from '../../constants/lifebook';\nimport {\n  LB_PAY_STATUS_LABEL, LB_PRODUCT_STATUS, lbCoverageLabel, lbPayLabel,\n  lbPriceLabel, lbRegionLabel, lbServiceAction, lbServiceLabel, lbTransportLabel,\n} from '../../constants/commerce';\nimport { ZoomableImage, type ZoomableImageHandle } from '../../components/lifebook/ZoomableImage';\nimport { ViewerZoomControls } from '../../components/lifebook/ViewerControls';\nimport SelectorDeVariante, { type Eleccion } from '../../components/lifebook/SelectorDeVariante';\nimport { ir as irSeguro } from '../../constants/rutas';\nimport { productosEnNotaApi } from '../../api/lifebookProductos';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst { width: SCREEN_W, height: SCREEN_H } = Dimensions.get('window');\nconst HERO_H = Math.round(SCREEN_W * 1.1);\n\nexport default function LifeBookProductScreen() {\n  return (\n    <AuthGate>\n      <ProductContent />\n    </AuthGate>\n  );\n}\n\nfunction ProductContent() {\n  const { id } = useLocalSearchParams<{ id: string }>();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const [product, setProduct] = useState<LbProduct | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [variant, setVariant] = useState<LbProductVariant | null>(null);\n  /** TANDA K/L: el selector «elegir antes de comprar» (lo abren Comprar y Añadir al carrito).\n   *  Se guarda **de qué botón se abrió** para poner esa acción como principal dentro del panel. */\n  const [selectorModo, setSelectorModo] = useState<'carrito' | 'comprar' | null>(null);\n  const [imgIdx, setImgIdx] = useState(0);\n  const [viewerOpen, setViewerOpen] = useState(false);\n  const [viewerZoomed, setViewerZoomed] = useState(false);\n  const [saved, setSaved] = useState(false);\n  const [busySave, setBusySave] = useState(false);\n  const [busyChat, setBusyChat] = useState(false);\n  const [following, setFollowing] = useState(false);\n  const [busyFollow, setBusyFollow] = useState(false);\n  /* TANDA D — carrito: cuántas cosas llevo (para el globito) y si estoy añadiendo esta. */\n  const [carritoCount, setCarritoCount] = useState(0);\n  const [busyCarrito, setBusyCarrito] = useState(false);\n  /** Tanda G: pidiendo (o quitando) el aviso de reposición. */\n  const [busyAviso, setBusyAviso] = useState(false);\n\n  const viewerListRef = useRef<FlatList<string>>(null);\n  const zoomHandles = useRef<Record<number, ZoomableImageHandle | null>>({});\n  const mounted = useRef(true);\n\n  /* TANDA D: cuántas cosas llevo en el carrito (para el globito del icono). */\n  useEffect(() => {\n    let vivo = true;\n    carritoApi.ver()\n      .then((c) => { if (vivo) setCarritoCount(Number(c?.count ?? 0)); })\n      .catch(() => { /* sin carrito, sin globito */ });\n    return () => { vivo = false; };\n  }, []);\n\n  const load = useCallback(async () => {\n    if (!id) return;\n    try {\n      const { product: p } = await commerceApi.product(String(id));\n      if (!mounted.current) return;\n      setProduct(p);\n      setSaved(!!p.savedByMe);\n      /**\n       * TANDA K — NADA DE ELEGIR POR EL COMPRADOR.\n       *\n       * Antes esto ponía `setVariant(p.variants?.[0])`: la primera opción de la lista quedaba\n       * marcada sola y «Comprar» compraba ESA, que es lo que el dueño rechazó («el paso de pulsar\n       * comprar ya no será directo: primero se elige la talla, el color…»). Ahora solo se marca\n       * cuando no hay nada que elegir: si el producto tiene ejes, el comprador los elige en el\n       * selector (y si solo hay una combinación, el selector la marca porque no hay decisión).\n       */\n      setVariant((p.options ?? []).length ? null : (p.variants?.[0] ?? null));\n      setError(null);\n      /**\n       * MERCADO (tanda F) — EL HISTORIAL DE PRODUCTOS.\n       *\n       * Abrir la ficha apunta el «visto» con una llamada PROPIA y con sesión. Antes se apuntaba\n       * dentro de la lectura de la ficha, que es pública: si el token acababa de caducar, esa\n       * petición salía sin identidad (200 anónimo) y la visita se perdía en silencio —medido en el\n       * teléfono, con la tabla `product_views` vacía después de abrir el producto—. Así, un 401\n       * dispara el refresco y el reintento del cliente. Nunca rompe la pantalla: si falla, se calla.\n       */\n      void commerceApi.registrarVista(p.id).catch(() => { /* el historial no puede romper la ficha */ });\n    } catch (e) {\n      if (mounted.current) setError(e instanceof Error ? e.message : 'No se pudo cargar la publicación');\n    } finally {\n      if (mounted.current) setLoading(false);\n    }\n  }, [id]);\n\n  useEffect(() => {\n    mounted.current = true;\n    load();\n    return () => { mounted.current = false; };\n  }, [load]);\n\n  const photos = useMemo(\n    () => (product?.media ?? []).filter((m) => m.type !== 'video').map((m) => absUrl(m.url)),\n    [product],\n  );\n\n  const openViewer = (url: string) => {\n    setImgIdx(Math.max(0, photos.indexOf(url)));\n    setViewerOpen(true);\n    Image.prefetch(photos, { cachePolicy: 'memory-disk' }).catch(() => {});\n  };\n\n  const toggleSave = async () => {\n    if (!product || busySave) return;\n    setBusySave(true);\n    const before = saved;\n    setSaved(!before);\n    try {\n      const res = await commerceApi.toggleSave(product.id);\n      setSaved(res.saved);\n    } catch {\n      setSaved(before);\n    } finally {\n      setBusySave(false);\n    }\n  };\n\n  const toggleFollow = async () => {\n    if (!product || busyFollow) return;\n    setBusyFollow(true);\n    const before = following;\n    setFollowing(!before);\n    try {\n      const res = await commerceApi.toggleFollow(product.shop.id);\n      setFollowing(res.following);\n    } catch {\n      setFollowing(before);\n    } finally {\n      setBusyFollow(false);\n    }\n  };\n\n  /**\n   * «CONVERSAR» — EFECTO EMBEBIDO (guía del dueño, regla 3: «el producto viaja con el usuario»).\n   *\n   * Antes esto abría el chat con un BORRADOR DE TEXTO («Hola, me interesa «X»… ¿Sigue\n   * disponible?»): el cliente tenía que enviarlo y el comerciante adivinaba de qué producto le\n   * hablaban. Ahora la conversación se abre con la **TARJETA ESTRUCTURADA** del producto como\n   * primer mensaje, con la **variante** ya elegida y marcada como CONSULTA (el chat pinta la\n   * línea gris «… está consultando sobre este producto»). Así el producto no se pierde de vista y\n   * nadie tiene que describir nada.\n   */\n  const startChat = async () => {\n    if (!product || busyChat) return;\n    const ownerId = product.shop.ownerId;\n    if (!ownerId) return;\n    setBusyChat(true);\n    try {\n      const conv = await messagesApi.open(ownerId);\n      // La tarjeta va PRIMERO (es el motivo del mensaje). Si falla, se entra igual al chat:\n      // dejar al cliente sin conversación sería peor que quedarse sin la tarjeta.\n      try {\n        await productosEnNotaApi.enviarAlChat(conv.id, product.id, {\n          variantLabel: variant?.name ?? null,\n          asking: true,\n        });\n      } catch { /* el chat se abre igual */ }\n      router.push({\n        pathname: '/lifebook-chat/[id]',\n        params: { id: conv.id, name: conv.peer.name ?? product.shop.name, peerId: ownerId },\n      } as never);\n    } catch {\n      // Si no se puede abrir la conversación, se DICE (antes se quedaba mudo y parecía roto).\n      irSeguro.explicar('No se pudo abrir el chat con la tienda.', `/lifebook-product/${product.id}`);\n    } finally {\n      setBusyChat(false);\n    }\n  };\n\n  if (loading) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  if (error || !product) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24, gap: espaciado.e12 }]}>\n        <Text style={{ color: colors.textPrimary, fontWeight: '800', textAlign: 'center' }}>{error ?? 'Publicación no encontrada'}</Text>\n        <GhostButton title=\"Volver\" onPress={() => router.back()} />\n      </View>\n    );\n  }\n\n  const p = product;\n  const stockLimit = p.stockMode === 'exact'\n    ? (variant ? variant.stockQuantity : p.stockQuantity)\n    : null;\n  const agotado = p.status === 'sold_out' || (stockLimit !== null && stockLimit <= 0);\n  const estado = LB_PRODUCT_STATUS[p.status];\n  /**\n   * Parte 36: si hay precio y stock, la acción principal es PEDIR (checkout real\n   * con pedido, entrega y pago). Si es «a consultar», está agotado o es mío, se\n   * mantiene el chat con la tienda.\n   */\n  const puedeComprar = !p.isMine && !agotado && p.priceMode !== 'on_request' && p.stockMode !== 'on_request';\n\n  /**\n   * TANDA K: lo que se ha elegido, en una línea, con la FOTO del color elegido. El servidor copia\n   * la foto del color a la combinación (`fotoDeCombinacion`), así que aquí solo hay que enseñarla.\n   */\n  const resumenEleccion = variant\n    ? ((p.options ?? []).length\n      ? (p.options ?? [])\n        .filter((g) => variant.attributes?.[g.code])\n        .map((g) => `${g.label}: ${variant.attributes?.[g.code]}`)\n        .join(' · ')\n      : variant.name)\n    : '';\n  const fotoElegida = variant?.imageUrl ? absUrl(variant.imageUrl) : null;\n\n  /**\n   * El PRECIO QUE SE ENSEÑA. Medido en el Poco F5 con la «Camiseta de prueba»: al elegir «Azul · M»\n   * el selector decía 13.500 XAF pero la ficha seguía poniendo 12.000. Si la combinación elegida\n   * tiene su propio precio, el precio de la ficha es ESE (es lo que se va a pagar).\n   */\n  const precioMostrado = variant?.priceXaf ?? p.priceXaf;\n\n  /**\n   * UN SOLO CAMINO PARA HABLAR CON LA TIENDA (petición del dueño), y una salida útil cuando está\n   * agotado:\n   *\n   *   · producto con precio y stock → «Comprar» (caja) + icono de mensaje ✓\n   *   · servicio / «a consultar»    → «Solicitar»/«Consultar», que ES el chat → sin icono\n   *   · agotado                     → **«Avísame cuando llegue»**: apunta la espera y la tienda\n   *     avisa por el chat al reponer (tanda G). Sigue habiendo icono de mensaje para preguntar\n   *   · es mi publicación           → «Es tu publicación» y sin icono (no me escribo a mí mismo)\n   */\n  const ctaEsElChat = !p.isMine && !agotado && !puedeComprar;\n  const mostrarIconoChat = !p.isMine && !ctaEsElChat;\n  /**\n   * Textos del CTA. **Cortos a propósito**: medido en el Poco F5, «Te avisamos cuando llegue» no\n   * cabía en la píldora (146 dp de hueco para un texto de ~175 dp) y la letra salía cortada. El\n   * botón mide lo que mide (los iconos de la izquierda no se tocan), así que el texto se adapta.\n   */\n  const etiquetaCta = p.isMine\n    ? 'Es tu publicación'\n    : agotado\n      ? (p.watching ? 'Te avisamos ✓' : 'Avísame si llega')\n      : lbServiceAction(p.serviceType);\n  /** Agotado SÍ se puede pulsar: es pedir el aviso (o quitarlo). */\n  const ctaActivo = !p.isMine;\n\n  /**\n   * MERCADO (tanda G) — «AVÍSAME CUANDO LLEGUE».\n   *\n   * Pide el aviso (o lo quita, si ya estaba pedido) y lo dice en pantalla con el mensaje del\n   * servidor. Se pide **por la variante elegida**: quien espera la «Talla 42» no quiere que le\n   * avisen por la «Talla 40». Y si resulta que ya se puede comprar, el servidor lo dice y no apunta\n   * nada: no se promete un aviso de algo que ya está.\n   */\n  const alternarAviso = async () => {\n    if (!product || busyAviso) return;\n    setBusyAviso(true);\n    try {\n      if (product.watching) {\n        const r = await avisoStockApi.dejarDeVigilar(product.id);\n        setProduct((prev) => (prev ? { ...prev, watching: r.watching } : prev));\n        Alert.alert('Aviso quitado', 'Ya no te avisamos de este producto.');\n      } else {\n        const r = await avisoStockApi.vigilar(product.id, variant?.id ?? null);\n        setProduct((prev) => (prev ? { ...prev, watching: r.watching } : prev));\n        Alert.alert(r.watching ? 'Te avisamos' : 'Ya está disponible', r.mensaje ?? '');\n      }\n    } catch (e) {\n      Alert.alert('Aviso de reposición', e instanceof Error ? e.message : 'No se pudo completar');\n    } finally {\n      setBusyAviso(false);\n    }\n  };\n\n  /**\n   * TANDA K — AÑADIR AL CARRITO LO ELEGIDO.\n   *\n   * Antes esta función no recibía nada: añadía `variant` (que era la primera de la lista, puesta\n   * sola al cargar) y cantidad 1. Ahora recibe lo que el comprador eligió en el selector —\n   * combinación y cantidad—, que es lo que de verdad quería.\n   */\n  const anadirAlCarrito = async (e: Eleccion) => {\n    if (busyCarrito || !product) return;\n    setBusyCarrito(true);\n    try {\n      const c = await carritoApi.anadir(product.id, { variantId: e.variant?.id ?? null, quantity: e.cantidad });\n      setCarritoCount(Number(c?.count ?? 0));\n      setVariant(e.variant);\n      setSelectorModo(null);\n      Alert.alert('Añadido al carrito', `«${product.title}»${e.variant ? ` (${e.variant.name})` : ''} ya está en tu carrito.`);\n    } catch (err) {\n      Alert.alert('Carrito', err instanceof Error ? err.message : 'No se pudo añadir al carrito');\n    } finally { setBusyCarrito(false); }\n  };\n\n  /** TANDA K: ir a la caja con lo elegido (combinación y cantidad), no con la primera opción. */\n  const comprarLoElegido = (e: Eleccion) => {\n    if (!product) return;\n    setVariant(e.variant);\n    setSelectorModo(null);\n    router.push({\n      pathname: '/lifebook-checkout',\n      params: { productId: product.id, ...(e.variant?.id ? { variantId: e.variant.id } : {}), quantity: String(e.cantidad) },\n    } as never);\n  };\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      {/* ── Cabecera ── */}\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <X size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 15, flex: 1, marginLeft: espaciado.e10 }}>\n          {lbServiceLabel(p.serviceType)}\n        </Text>\n        <Pressable onPress={toggleSave} hitSlop={10} accessibilityLabel={saved ? 'Quitar de guardados' : 'Guardar'}>\n          <Heart size={20} color={saved ? brand.like : colors.textPrimary} fill={saved ? brand.like : 'none'} />\n        </Pressable>\n      </View>\n\n      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingBottom: insets.bottom + 96 }}>\n        {/* ── Galería ── */}\n        {photos.length > 0 ? (\n          <View>\n            <FlatList\n              data={photos}\n              horizontal\n              pagingEnabled\n              showsHorizontalScrollIndicator={false}\n              keyExtractor={(u) => u}\n              onMomentumScrollEnd={(e) => setImgIdx(Math.round(e.nativeEvent.contentOffset.x / SCREEN_W))}\n              renderItem={({ item }) => (\n                <Pressable onPress={() => openViewer(item)} accessibilityLabel=\"Ver la foto a pantalla completa\">\n                  <Image\n                    source={item}\n                    style={{ width: SCREEN_W, height: HERO_H, backgroundColor: colors.surface }}\n                    contentFit=\"cover\"\n                    cachePolicy=\"memory-disk\"\n                    recyclingKey={item}\n                    transition={0}\n                  />\n                </Pressable>\n              )}\n            />\n            {photos.length > 1 ? (\n              <View style={[styles.counter, { backgroundColor: alpha('#000000', 0.55) }]}>\n                <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>{imgIdx + 1}/{photos.length}</Text>\n              </View>\n            ) : null}\n          </View>\n        ) : (\n          <View style={[styles.heroEmpty, { backgroundColor: alpha(colors.primary, 0.1) }]}>\n            <Text style={{ fontSize: 40 }}>📦</Text>\n          </View>\n        )}\n\n        <View style={{ padding: espaciado.e16 }}>\n          {/* ── Aviso para el dueño (moderación) ── */}\n          {p.isMine && estado ? (\n            <View style={[styles.notice, { backgroundColor: alpha(estado.tone === 'ok' ? colors.success : colors.primary, 0.1) }]}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.caption }}>\n                {estado.label} · {estado.hint}\n              </Text>\n              {p.status === 'rejected' && p.rejectionReason ? (\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, marginTop: espaciado.e3 }}>{p.rejectionReason}</Text>\n              ) : null}\n            </View>\n          ) : null}\n\n          {/* TANDA H — «N personas esperan esto»: solo lo ve el DUEÑO, y solo si hay alguien\n              esperando. Es el dato que dice si merece la pena reponer existencias (y al reponer se\n              les avisa por el chat automáticamente). */}\n          {p.isMine && Number(p.waitingCount ?? 0) > 0 ? (\n            <View style={[styles.notice, { backgroundColor: alpha(brand.secondary, 0.12) }]}>\n              <Text style={{ color: brand.warning, fontWeight: '900', fontSize: tipografia.caption }}>\n                🔔 {p.waitingCount} {p.waitingCount === 1 ? 'persona espera' : 'personas esperan'} este producto\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e3, lineHeight: 16 }}>\n                Al reponer existencias se les avisa solos por el chat con la tienda.\n              </Text>\n            </View>\n          ) : null}\n\n          {/* ── Precio y título ── */}\n          <View style={styles.priceRow}>\n            <Text style={[styles.price, { color: agotado ? colors.textSecondary : colors.primary }]}>\n              {agotado ? 'Agotado' : lbPriceLabel(precioMostrado, p.priceMode, lbXaf)}\n            </Text>\n            {p.oldPriceXaf ? (\n              <Text style={[styles.oldPrice, { color: colors.textSecondary }]}>{lbXaf(p.oldPriceXaf)}</Text>\n            ) : null}\n          </View>\n\n          <Text style={[styles.title, { color: colors.textPrimary }]}>{p.title}</Text>\n          {p.shortDescription ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e4 }}>{p.shortDescription}</Text>\n          ) : null}\n\n          {/* ── Insignias de confianza ── */}\n          <View style={styles.badges}>\n            {p.shop.isVerified ? (\n              <Badge colors={colors} icon={<ShieldCheck size={13} color={colors.success} />} text=\"Tienda verificada\" />\n            ) : (\n              <Badge colors={colors} icon={<Store size={13} color={colors.textSecondary} />} text=\"Tienda nueva\" />\n            )}\n            {p.shipsInternational ? <Badge colors={colors} icon={<Plane size={13} color={colors.primary} />} text=\"Envío internacional\" /> : null}\n            {p.stockMode === 'exact' && p.stockQuantity > 0 && !variant ? (\n              <Badge colors={colors} icon={<Package size={13} color={colors.textSecondary} />} text={`Quedan ${p.stockQuantity}`} />\n            ) : null}\n            {p.stockMode === 'on_request' ? <Badge colors={colors} icon={<Clock size={13} color={colors.textSecondary} />} text=\"Bajo pedido\" /> : null}\n            <Badge colors={colors} icon={<Eye size={13} color={colors.textSecondary} />} text={`${p.viewsCount} vistas`} />\n          </View>\n\n          {/*\n            «AÑADIR AL CARRITO» VIVE AQUÍ, NO EN LA BARRA DE ABAJO.\n\n            Antes estaba en la barra, justo al lado del icono del carrito: dos botones de carrito\n            pegados. El dueño lo dijo claro —«esta interfaz ya había un botón de carrito con ícono,\n            no es necesario volver a agregar otro»—. La barra se queda con **un solo** control de\n            carrito (el icono, que abre el carrito y lleva el globito con cuántas cosas hay) y la\n            acción de añadir se pone donde se elige: debajo del precio y las opciones, sin competir\n            con el CTA azul.\n\n            TANDA K: este botón **ya no añade directo** (añadía la primera opción de la lista, sin\n            preguntar). Abre el selector, que es el mismo que abre «Comprar»: un solo sitio donde se\n            decide talla, color y cantidad.\n          */}\n          {!p.isMine && puedeComprar ? (\n            <>\n              {p.variants.length > 0 ? (\n                <Pressable\n                  onPress={() => setSelectorModo('comprar')}\n                  accessibilityLabel=\"Elegir talla, color y cantidad\"\n                  style={[styles.elegirRow, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.surface }]}\n                >\n                  {fotoElegida ? (\n                    <Image source={fotoElegida} style={styles.elegirFoto} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                  ) : (\n                    <View style={[styles.elegirFoto, { backgroundColor: alpha(colors.primary, 0.12), alignItems: 'center', justifyContent: 'center' }]}>\n                      <Package size={16} color={colors.primary} />\n                    </View>\n                  )}\n                  <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                    <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                      {resumenEleccion || 'Elegir talla y color'}\n                    </Text>\n                  </View>\n                  <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.caption }}>\n                    {resumenEleccion ? 'Cambiar' : 'Elegir'}\n                  </Text>\n                </Pressable>\n              ) : null}\n              <Pressable\n                onPress={() => setSelectorModo('carrito')}\n                disabled={busyCarrito}\n                accessibilityLabel=\"Añadir al carrito\"\n                style={[styles.anadirBtn, { borderColor: colors.primary }]}\n              >\n                {busyCarrito ? (\n                  <ActivityIndicator size=\"small\" color={colors.primary} />\n                ) : (\n                  <>\n                    <ShoppingCart size={15} color={colors.primary} />\n                    <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900' }}>Añadir al carrito</Text>\n                  </>\n                )}\n              </Pressable>\n            </>\n          ) : null}\n\n          {/* ── Descripción ── */}\n          {p.longDescription ? (\n            <Section colors={colors} title=\"Descripción\">\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 20 }}>{p.longDescription}</Text>\n            </Section>\n          ) : null}\n\n          {/* ── Detalles (atributos) ── */}\n          {p.attributes.length > 0 ? (\n            <Section colors={colors} title=\"Detalles\">\n              {p.attributes.map((a) => (\n                <View key={a.key} style={[styles.attrRow, { borderBottomColor: alpha(colors.border, 0.6) }]}>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{a.key}</Text>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '600' }}>{a.value}</Text>\n                </View>\n              ))}\n            </Section>\n          ) : null}\n\n          {/* ── Entrega ── */}\n          {p.shippingPolicy ? (\n            <Section colors={colors} title=\"Entrega\">\n              <InfoLine colors={colors} icon={<Truck size={16} color={colors.primary} />}\n                text={`Desde ${p.shippingPolicy.originCity ?? p.originCity ?? '—'}${p.shippingPolicy.originBarrio ? ` · ${p.shippingPolicy.originBarrio}` : ''}`} />\n              {p.shippingPolicy.coverage.length > 0 ? (\n                <InfoLine colors={colors} icon={<MapPin size={16} color={colors.primary} />}\n                  text={p.shippingPolicy.coverage.map(lbCoverageLabel).join(' · ')} />\n              ) : null}\n              {p.shippingPolicy.transportModes.length > 0 ? (\n                <InfoLine colors={colors} icon={<Ship size={16} color={colors.primary} />}\n                  text={p.shippingPolicy.transportModes.map(lbTransportLabel).join(' · ')} />\n              ) : null}\n              <View style={styles.chips}>\n                {p.shippingPolicy.costMode === 'on_request' ? (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Coste de envío a consultar con la tienda</Text>\n                ) : (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                    Envío desde {lbXaf(p.shippingPolicy.baseCostXaf)}\n                    {p.shippingPolicy.perKmXaf ? ` + ${lbXaf(p.shippingPolicy.perKmXaf)}/km` : ''}\n                    {p.shippingPolicy.estimatedTime ? ` · ${p.shippingPolicy.estimatedTime}` : ''}\n                  </Text>\n                )}\n              </View>\n            </Section>\n          ) : null}\n\n          {/* ── Pagos aceptados ── */}\n          {p.paymentMethods.length > 0 ? (\n            <Section colors={colors} title=\"Pagos aceptados\">\n              {p.paymentMethods.map((pm) => (\n                <InfoLine\n                  key={pm.method}\n                  colors={colors}\n                  icon={pm.method === 'cash_on_delivery'\n                    ? <Banknote size={16} color={colors.success} />\n                    : pm.method === 'likebook_wallet'\n                      ? <Wallet size={16} color={colors.textSecondary} />\n                      : <Building2 size={16} color={colors.primary} />}\n                  text={`${lbPayLabel(pm.method)}${pm.status !== 'active' ? ` · ${LB_PAY_STATUS_LABEL[pm.status] ?? ''}` : ''}`}\n                />\n              ))}\n            </Section>\n          ) : null}\n\n          {/* ── Tienda ── */}\n          <View style={[styles.shopCard, { borderColor: alpha(colors.border, 0.7), backgroundColor: colors.surface }]}>\n            {p.shop.logoUrl ? (\n              <Image source={absUrl(p.shop.logoUrl)} style={styles.shopLogo} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n            ) : (\n              <View style={[styles.shopLogo, { backgroundColor: alpha(colors.primary, 0.12), alignItems: 'center', justifyContent: 'center' }]}>\n                <Store size={20} color={colors.primary} />\n              </View>\n            )}\n            <View style={{ flex: 1, marginHorizontal: espaciado.e10 }}>\n              <Text numberOfLines={1} style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>{p.shop.name}</Text>\n              <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                {[p.shop.city, lbRegionLabel(p.shop.region), p.shop.ratingCount > 0 ? `★ ${p.shop.rating.toFixed(1)} (${p.shop.ratingCount})` : null]\n                  .filter(Boolean).join(' · ')}\n              </Text>\n            </View>\n            <Pressable\n              onPress={toggleFollow}\n              accessibilityLabel={following ? 'Dejar de seguir la tienda' : 'Seguir la tienda'}\n              style={[styles.followBtn, { borderColor: colors.primary, backgroundColor: following ? colors.primary : 'transparent' }]}\n            >\n              <Text style={{ color: following ? brand.white : colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>\n                {following ? 'Siguiendo' : 'Seguir'}\n              </Text>\n            </Pressable>\n          </View>\n          <Pressable\n            onPress={() => irSeguro.libre('/lifebook-shop/[id]', { id: p.shop.id })}\n            accessibilityLabel=\"Ver la tienda\"\n            style={{ marginTop: espaciado.e10, alignItems: 'center' }}\n          >\n            <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>Ver todos los productos de la tienda →</Text>\n          </Pressable>\n\n          {/* ── Mis acciones (dueño) ── */}\n          {p.isMine ? (\n            <View style={{ marginTop: espaciado.e18, gap: espaciado.e8 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>\n                {p.salesCount} ventas · {p.savesCount} guardados · {p.ratingCount} valoraciones\n              </Text>\n              <View style={{ flexDirection: 'row', gap: espaciado.e8, flexWrap: 'wrap' }}>\n                <GhostButton title=\"Editar\" onPress={() => irSeguro.libre('/lifebook-sell', { editId: p.id })} />\n                {/* Parte 39: el día a día (precio y existencias) se ajusta en el panel\n                    sin devolver la publicación a revisión. */}\n                <GhostButton title=\"Precio y stock\" onPress={() => irSeguro.libre('/lifebook-merchant-products')} />\n                <GhostButton title={p.status === 'hidden' ? 'Publicar' : 'Ocultar'} onPress={async () => {\n                  try {\n                    await commerceApi.setProductStatus(p.id, p.status === 'hidden' ? 'activate' : 'hide');\n                    await load();\n                  } catch { /* silencioso */ }\n                }} />\n                <GhostButton title=\"Borrar\" onPress={async () => {\n                  try {\n                    await commerceApi.deleteProduct(p.id);\n                    router.back();\n                  } catch { /* silencioso */ }\n                }} />\n              </View>\n            </View>\n          ) : null}\n        </View>\n      </ScrollView>\n\n      {/* ── Barra inferior fija ── */}\n      <View style={[styles.bottomBar, { backgroundColor: colors.background, borderTopColor: alpha(colors.border, 0.7), paddingBottom: insets.bottom + 10 }]}>\n        <Pressable onPress={toggleSave} accessibilityLabel=\"Guardar\" style={[styles.iconBtn, { borderColor: colors.border }]}>\n          <Heart size={18} color={saved ? brand.like : colors.textPrimary} fill={saved ? brand.like : 'none'} />\n        </Pressable>\n        {/* UN SOLO CAMINO PARA HABLAR CON LA TIENDA: el icono solo sale si el botón principal no\n            es ya el chat (ver `mostrarIconoChat`). Tener los dos repetía la misma acción. */}\n        {mostrarIconoChat ? (\n          <Pressable onPress={startChat} accessibilityLabel=\"Escribir a la tienda\" style={[styles.iconBtn, { borderColor: colors.border }]}>\n            <MessageCircle size={18} color={colors.textPrimary} />\n          </Pressable>\n        ) : null}\n        {/* TANDA D: el carrito, con el globito de cuántas cosas llevas. */}\n        <Pressable\n          onPress={() => irSeguro.libre('/lifebook-carrito')}\n          accessibilityLabel={`Mi carrito${carritoCount ? `, ${carritoCount} producto${carritoCount === 1 ? '' : 's'}` : ''}`}\n          style={[styles.iconBtn, { borderColor: colors.border }]}\n        >\n          <ShoppingCart size={18} color={colors.textPrimary} />\n          {carritoCount > 0 ? (\n            <View style={[styles.cartBadge, { backgroundColor: colors.primary }]}>\n              <Text style={{ color: brand.white, fontSize: 9.5, fontWeight: '900' }}>{carritoCount > 99 ? '99+' : carritoCount}</Text>\n            </View>\n          ) : null}\n        </Pressable>\n        <View style={{ flex: 1 }}>\n          {/*\n            EL CTA DE LA BARRA, DEL ALTO DE LA BARRA.\n\n            Antes era un `PrimaryButton` (alto FIJO de 52 dp) dentro de una barra de botones de\n            44 dp: medido en el Poco F5, salía de 170 × 52 dp al lado de tres círculos de 44 dp\n            —el dueño lo vio «mal ajustado y muy grande»—. El botón grande tiene sentido a lo ancho\n            de la pantalla (caja, hojas); en una barra de acciones, no.\n\n            Y el texto dice lo que de verdad hace: para un servicio «a consultar» **abre el chat con\n            la tienda** (y por eso el icono de mensaje desaparece cuando este botón ya es el chat).\n            Antes, cuando el producto estaba agotado, aquí ponía «Avísame cuando llegue» y hacía\n            exactamente lo mismo que el icono de al lado: dos botones para lo mismo.\n          */}\n          <Pressable\n            onPress={() => {\n              // 🔒 ALOJAMIENTO: no se compra, se RESERVA por noches.\n              //\n              // El botón ya decía «Reservar», pero llevaba a `/lifebook-checkout` — la caja de\n              // un producto: cantidad, entrega, forma de pago. Una habitación entraba por ahí\n              // sin fechas, sin noches y sin comprobar disponibilidad, y el pedido se aceptaba\n              // de verdad (probado: pedido LB-260911-0001 sobre una habitación). Además el\n              // dinero acababa en el flujo de PEDIDOS en vez del de RESERVAS, saltándose\n              // `reservation_nights`, que es la única verdad contra la sobreventa.\n              //\n              // Se entra por la ficha del hotel, que es donde se eligen fechas y huéspedes y\n              // donde el servidor comprueba inventario, estancia mínima, capacidad y cierre de\n              // fechas. El servidor ya rechaza el atajo (`SERVICE_NOT_ORDERABLE`); esto evita\n              // que el usuario llegue hasta ahí.\n              if (p.serviceType === 'hotel_room') {\n                irSeguro.libre('/lifebook-hotel-detalle', { id: p.shopId });\n                return;\n              }\n              // AGOTADO: el botón pide el aviso de reposición (o lo quita). No lleva a la caja\n              // —no hay nada que comprar— y no es un botón muerto.\n              if (agotado) { void alternarAviso(); return; }\n              if (!puedeComprar) { startChat(); return; }\n              /**\n               * TANDA K — «COMPRAR» YA NO COMPRA DIRECTO.\n               *\n               * Antes esto entraba en la caja con `variant`, que era la PRIMERA opción de la lista\n               * puesta sola al cargar: se compraba la talla 42 sin que nadie la eligiera. Ahora\n               * abre el selector (talla, color, cantidad) y desde ahí se va a la caja con lo\n               * elegido.\n               */\n              setSelectorModo('comprar');\n            }}\n            disabled={!ctaActivo || busyChat}\n            accessibilityLabel={etiquetaCta === 'Avísame si llega' ? 'Avísame cuando llegue' : etiquetaCta}\n            accessibilityState={{ disabled: !ctaActivo }}\n            style={[\n              styles.ctaBtn,\n              { backgroundColor: ctaActivo ? colors.primary : alpha(colors.primary, 0.35) },\n            ]}\n          >\n            {busyChat ? (\n              <ActivityIndicator size=\"small\" color={brand.white} />\n            ) : (\n              /* `flexShrink: 1` + `numberOfLines`: si el texto no cupiera, se recorta CON puntos\n                 suspensivos en vez de salirse de la píldora y quedar cortado por el borde. */\n              <Text numberOfLines={1} style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '900', flexShrink: 1, textAlign: 'center' }}>\n                {etiquetaCta}\n              </Text>\n            )}\n          </Pressable>\n        </View>\n      </View>\n\n      {/*\n        TANDA K — EL SELECTOR, FUERA DEL ALOJAMIENTO.\n\n        Una habitación no se compra: se RESERVA por noches y huéspedes, y eso se elige en la ficha\n        del hotel (que es donde el servidor comprueba inventario, estancia mínima y capacidad). Por\n        eso el selector no se abre para `hotel_room`: su botón sigue llevando a la ficha del hotel.\n      */}\n      {!p.isMine && p.serviceType !== 'hotel_room' ? (\n        <SelectorDeVariante\n          visible={selectorModo !== null}\n          product={p}\n          modoInicial={selectorModo ?? 'comprar'}\n          /** Si ya se había elegido una combinación, al reabrir se mantiene (no vuelve a cero). */\n          seleccionInicial={variant}\n          busy={busyCarrito ? 'carrito' : null}\n          onClose={() => setSelectorModo(null)}\n          onCarrito={(e) => { void anadirAlCarrito(e); }}\n          onComprar={comprarLoElegido}\n        />\n      ) : null}\n\n      {/* ── Visor de fotos (zoom de la Parte 32) ── */}\n      <Modal visible={viewerOpen} transparent animationType=\"none\" onRequestClose={() => setViewerOpen(false)} statusBarTranslucent>\n        <View style={{ flex: 1, backgroundColor: '#000000' }}>\n          <FlatList\n            ref={viewerListRef}\n            data={photos}\n            horizontal\n            pagingEnabled\n            scrollEnabled={!viewerZoomed}\n            initialScrollIndex={Math.max(0, imgIdx)}\n            getItemLayout={(_, i) => ({ length: SCREEN_W, offset: SCREEN_W * i, index: i })}\n            keyExtractor={(u) => u}\n            showsHorizontalScrollIndicator={false}\n            onMomentumScrollEnd={(e) => setImgIdx(Math.round(e.nativeEvent.contentOffset.x / SCREEN_W))}\n            renderItem={({ item, index }) => (\n              <ZoomableImage\n                ref={(h) => { zoomHandles.current[index] = h; }}\n                uri={item}\n                width={SCREEN_W}\n                height={SCREEN_H}\n                resetKey={`${index}-${imgIdx}`}\n                blockScrollRef={viewerListRef}\n                onZoomChange={index === imgIdx ? setViewerZoomed : undefined}\n                onSingleTap={() => setViewerOpen(false)}\n              />\n            )}\n          />\n          <ViewerZoomControls\n            bottom={insets.bottom + 18}\n            onZoomOut={() => zoomHandles.current[imgIdx]?.zoomOut()}\n            onFit={() => zoomHandles.current[imgIdx]?.fit()}\n            onZoomIn={() => zoomHandles.current[imgIdx]?.zoomIn()}\n          />\n          <Pressable\n            onPress={() => setViewerOpen(false)}\n            accessibilityLabel=\"Cerrar foto\"\n            style={[styles.viewerClose, { top: insets.top + 10 }]}\n          >\n            <X size={20} color={brand.white} />\n          </Pressable>\n        </View>\n      </Modal>\n    </View>\n  );\n}\n\n// ── piezas pequeñas reutilizadas dentro de la ficha ──────────────────────────\nfunction Badge({ colors, icon, text }: { colors: any; icon: React.ReactNode; text: string }) {\n  return (\n    <View style={[styles.badge, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.surface }]}>\n      {icon}\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.micro, fontWeight: '700', marginLeft: espaciado.e4 }}>{text}</Text>\n    </View>\n  );\n}\n\nfunction Section({ colors, title, children }: { colors: any; title: string; children: React.ReactNode }) {\n  return (\n    <View style={{ marginTop: espaciado.e20 }}>\n      <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '800', marginBottom: espaciado.e8 }}>{title}</Text>\n      {children}\n    </View>\n  );\n}\n\nfunction InfoLine({ colors, icon, text }: { colors: any; icon: React.ReactNode; text: string }) {\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e7 }}>\n      {icon}\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, marginLeft: espaciado.e8, flex: 1 }}>{text}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  heroEmpty: { width: SCREEN_W, height: HERO_H * 0.6, alignItems: 'center', justifyContent: 'center' },\n  counter: { position: 'absolute', bottom: 10, right: 12, borderRadius: radios.full, paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e3 },\n  priceRow: { flexDirection: 'row', alignItems: 'flex-end', gap: espaciado.e10 },\n  price: { fontSize: 24, fontWeight: '900' },\n  oldPrice: { fontSize: tipografia.body, textDecorationLine: 'line-through', marginBottom: espaciado.e3 },\n  title: { fontSize: 18.5, fontWeight: '800', marginTop: espaciado.e6, lineHeight: 24 },\n  badges: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, marginTop: espaciado.e12 },\n  badge: {\n    flexDirection: 'row', alignItems: 'center', borderWidth: StyleSheet.hairlineWidth,\n    borderRadius: radios.full, paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e5,\n  },\n  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  chip: { flexDirection: 'row', alignItems: 'center', borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9 },\n  attrRow: {\n    flexDirection: 'row', justifyContent: 'space-between', paddingVertical: espaciado.e7,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  notice: { borderRadius: radios.md, padding: espaciado.e10, marginBottom: espaciado.e12 },\n  shopCard: { flexDirection: 'row', alignItems: 'center', borderWidth: StyleSheet.hairlineWidth, borderRadius: 14, padding: espaciado.e12, marginTop: espaciado.e22 },\n  shopLogo: { width: 44, height: 44, borderRadius: 22 },\n  followBtn: { borderWidth: 1.5, borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7 },\n  bottomBar: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10, borderTopWidth: StyleSheet.hairlineWidth,\n  },\n  iconBtn: {\n    width: 44, height: 44, borderRadius: 22, borderWidth: StyleSheet.hairlineWidth,\n    alignItems: 'center', justifyContent: 'center',\n  },\n  /**\n   * «Añadir al carrito» (secundario, contorneado): va en la zona del precio y las opciones, no en\n   * la barra inferior, donde el carrito ya tiene su icono. Alto 40 dp y ancho el del texto.\n   */\n  anadirBtn: {\n    alignSelf: 'flex-start', flexDirection: 'row', alignItems: 'center', gap: espaciado.e7,\n    height: 40, borderRadius: radios.full, borderWidth: 1.5, paddingHorizontal: espaciado.e14, marginTop: espaciado.e12,\n  },\n  /** TANDA K: la fila que enseña lo elegido (con la foto del color) y abre el selector. */\n  elegirRow: {\n    flexDirection: 'row', alignItems: 'center', borderWidth: 1, borderRadius: radios.md,\n    padding: espaciado.e9, marginTop: espaciado.e12,\n  },\n  elegirFoto: { width: 40, height: 40, borderRadius: 9 },\n  /**\n   * El CTA de la barra inferior: MISMO alto que los botones redondos (44 dp) y forma de píldora,\n   * para que la fila se vea de una pieza. Ocupa el ancho que sobra (`flex: 1`) y el texto se\n   * recorta con puntos suspensivos antes que romper la fila.\n   */\n  ctaBtn: {\n    flex: 1, height: 44, borderRadius: radios.full, paddingHorizontal: espaciado.e12,\n    alignItems: 'center', justifyContent: 'center',\n  },\n  /* TANDA D: el globito con cuántas cosas llevas en el carrito. */\n  cartBadge: {\n    position: 'absolute', top: -2, right: -2, minWidth: 17, height: 17, borderRadius: 9,\n    alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e3,\n  },\n  viewerClose: {\n    position: 'absolute', right: 16, width: 36, height: 36, borderRadius: 18,\n    backgroundColor: 'rgba(255,255,255,0.16)', alignItems: 'center', justifyContent: 'center',\n  },\n});\n","/**\n * components/lifebook/SelectorDeVariante.tsx — «ELEGIR ANTES DE COMPRAR» (tandas K y L).\n *\n * EL PROBLEMA QUE CIERRA. Hasta la tanda K, pulsar «Comprar» o «Añadir al carrito» compraba DIRECTO\n * con la primera variante de la lista (`p.variants?.[0]`): nadie elegía talla ni color, y la ficha\n * solo podía enseñar la PALABRA «Talla 42». El dueño lo pidió así: «el paso de pulsar comprar o\n * agregar en el carrito ya no será directo, deberá primero seleccionar la talla, el color si es ropa\n * y así sucesivamente con otros productos, mostrando claramente el color de la prenda: no vale sólo\n * poner color, debe verse el producto de la foto real de este color».\n *\n * LO QUE HACE (según la especificación del panel):\n *   · Cabecera: miniatura de la combinación elegida (cambia sola), precio de ESA combinación —o el\n *     RANGO si hay precios distintos y aún no se ha elegido—, precio anterior tachado si hay\n *     descuento, y el stock («quedan pocas unidades» cuando es poco).\n *   · Un bloque por eje: colores con SU FOTO, tallas como botones, y cualquier otro eje (memoria,\n *     formato, tono…) con sus valores.\n *   · EL AGOTADO ES POR COMBINACIÓN, no por eje: «Blanco · M» puede estar agotada con «Blanco · L»\n *     disponible. Cada vez que se toca algo se recalculan todas las opciones; un color con TODAS sus\n *     tallas agotadas sale apagado entero.\n *   · Cantidad con el tope real de esa combinación (no un 99 inventado).\n *   · «¿No sabes tu talla?» → el asistente de medidas (tanda L) DENTRO del mismo panel.\n *   · Cierre con la X, tocando fuera o deslizando hacia abajo.\n *\n * LO QUE NO ES (a propósito): si un valor está agotado **no se puede seleccionar** (se ve apagado y\n * tachado). Para que eso no deje al comprador sin salida, al tocar un valor agotado se ofrece\n * **«avísame cuando llegue ESA combinación»** —que es lo que hace Taobao («缺货中，提醒掌柜补货»)—,\n * sin seleccionarla: el servidor apunta la espera por variante desde la tanda G.\n */\nimport React, { useEffect, useMemo, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, Modal, PanResponder, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { Minus, Plus, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../../api/config';\nimport { avisoStockApi, commerceApi, type LbOptionGroup, type LbProduct, type LbProductVariant, type LbSizeChart } from '../../api/commerce';\nimport { lbXaf } from '../../constants/lifebook';\nimport AsistenteDeTalla from './AsistenteDeTalla';\n\nexport interface Eleccion {\n  variant: LbProductVariant | null;\n  cantidad: number;\n}\n\n/** De qué botón se abrió: el panel pone ese como principal (el otro queda al lado). */\nexport type ModoSelector = 'carrito' | 'comprar';\n\nexport default function SelectorDeVariante({\n  visible, product, modoInicial = 'comprar', seleccionInicial, busy, onClose, onCarrito, onComprar,\n}: {\n  visible: boolean;\n  product: LbProduct;\n  modoInicial?: ModoSelector;\n  /** Lo que ya se había elegido en la ficha (si se vuelve a abrir, se mantiene). */\n  seleccionInicial?: LbProductVariant | null;\n  /** Mientras se añade o se abre la caja: los botones se apagan, no se duplican pedidos. */\n  busy?: ModoSelector | null;\n  onClose: () => void;\n  onCarrito: (e: Eleccion) => void;\n  onComprar: (e: Eleccion) => void;\n}) {\n  const { colors } = useTheme();\n  const grupos = useMemo(\n    () => (product.options ?? []).filter((g) => (g.values ?? []).length > 0),\n    [product.options],\n  );\n  const variantes = useMemo(() => (product.variants ?? []).filter((v) => v.id), [product.variants]);\n  const grupoTalla = useMemo(() => grupos.find((g) => g.kind === 'size') ?? null, [grupos]);\n\n  /** Lo elegido, por código de eje: `{ color: 'Rojo', talla: 'M' }`. */\n  const [sel, setSel] = useState<Record<string, string>>({});\n  const [cant, setCant] = useState(1);\n  /** Dentro del panel: elegir, o el asistente de talla (que NO es una pantalla nueva). */\n  const [modo, setModo] = useState<'elegir' | 'talla'>('elegir');\n  /** Las tablas del producto: sirven para saber si se puede ofrecer el asistente. */\n  const [tablas, setTablas] = useState<LbSizeChart[]>([]);\n  /** Valor agotado que se ha tocado (para ofrecer el aviso, sin seleccionarlo). */\n  const [avisoPara, setAvisoPara] = useState<{ code: string; label: string; value: string } | null>(null);\n  const [busyAviso, setBusyAviso] = useState(false);\n\n  /**\n   * Al abrir: NADA se elige por el comprador. Dos excepciones honestas: si la ficha ya tenía una\n   * combinación elegida se mantiene, y si el producto tiene una única combinación se marca (no hay\n   * nada que decidir). Elegir «la primera» por su cuenta es justo lo que había antes.\n   */\n  useEffect(() => {\n    if (!visible) return;\n    setCant(1);\n    setModo('elegir');\n    setAvisoPara(null);\n    const deLaFicha = seleccionInicial?.id && variantes.some((v) => v.id === seleccionInicial.id) ? seleccionInicial : null;\n    const unica = variantes.length === 1 ? variantes[0] : null;\n    const base = deLaFicha ?? unica;\n    setSel(base\n      ? Object.fromEntries(grupos.map((g) => [g.code, String(base.attributes?.[g.code] ?? '')]).filter(([, v]) => v))\n      : {});\n    if ((product.options ?? []).some((g) => g.kind === 'size')) {\n      commerceApi.sizeChart(product.id)\n        .then((r) => setTablas(r.charts ?? []))\n        .catch(() => setTablas([]));\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [visible, product.id]);\n\n  const conStock = (v: LbProductVariant | undefined): boolean => {\n    if (!v) return false;\n    if (product.stockMode !== 'exact') return true;\n    return Number(v.stockQuantity ?? 0) > 0;\n  };\n\n  const varianteDe = (eleccion: Record<string, string>): LbProductVariant | null => {\n    if (!grupos.length) return variantes[0] ?? null;\n    return variantes.find((v) => grupos.every((g) => (\n      String(v.attributes?.[g.code] ?? '').trim().toLowerCase() === String(eleccion[g.code] ?? '').trim().toLowerCase()\n    ))) ?? null;\n  };\n\n  /**\n   * ¿EXISTE la combinación con ese valor? (aunque esté agotada) y ¿tiene stock AHORA?\n   *\n   * Se miran SOLO los ejes ya elegidos, como en Taobao: al tocar «Blanco», las tallas se recalculan\n   * y las que no tengan stock para blanco se apagan; al cambiar a «Rojo» se liberan otras.\n   */\n  const combosCon = (code: string, value: string) => {\n    const cand = { ...sel, [code]: value };\n    const codigos = grupos.map((g) => g.code).filter((c) => cand[c]);\n    return variantes.filter((v) => codigos.every((c) => (\n      String(v.attributes?.[c] ?? '').trim().toLowerCase() === String(cand[c]).trim().toLowerCase()\n    )));\n  };\n  const existeCombo = (code: string, value: string) => !variantes.length || combosCon(code, value).length > 0;\n  const disponible = (code: string, value: string) => !variantes.length || combosCon(code, value).some(conStock);\n\n  const faltan = grupos.filter((g) => !sel[g.code]).map((g) => g.label);\n  const eleccionCompleta = faltan.length === 0;\n  const elegida = eleccionCompleta ? varianteDe(sel) : null;\n  /** La combinación elegida existe pero ahora mismo no tiene stock. */\n  const agotada = eleccionCompleta && !!elegida && !conStock(elegida);\n\n  /**\n   * El precio: el de la combinación elegida; si hay precios distintos entre combinaciones y aún no\n   * se ha elegido nada, el RANGO (como pide la especificación); si no, el del producto.\n   */\n  const precios = useMemo(() => {\n    const lista = variantes.map((v) => (v.priceXaf ?? product.priceXaf)).filter((n): n is number => typeof n === 'number' && n > 0);\n    return [...new Set(lista)].sort((a, b) => a - b);\n  }, [variantes, product.priceXaf]);\n  const precioElegido = elegida?.priceXaf ?? null;\n  const precioTexto = precioElegido !== null\n    ? lbXaf(precioElegido)\n    : (!eleccionCompleta && precios.length > 1)\n      ? `${lbXaf(precios[0])} – ${lbXaf(precios[precios.length - 1])}`\n      : (product.priceXaf !== null && product.priceXaf !== undefined ? lbXaf(product.priceXaf) : 'A consultar');\n  /** El precio anterior SOLO si de verdad es mayor que el que se enseña (si no, sería mentira). */\n  const precioAntiguo = useMemo(() => {\n    const viejo = product.oldPriceXaf ?? null;\n    if (!viejo) return null;\n    const actual = precioElegido ?? (precios.length ? precios[0] : product.priceXaf) ?? 0;\n    return viejo > actual ? viejo : null;\n  }, [product.oldPriceXaf, precioElegido, precios, product.priceXaf]);\n\n  const tope = product.stockMode === 'exact'\n    ? Math.max(0, elegida ? Number(elegida.stockQuantity ?? 0) : Number(product.stockQuantity ?? 0))\n    : 99;\n  const pocoStock = product.stockMode === 'exact' && tope > 0 && tope < 10;\n  const stockTexto = agotada\n    ? 'Agotada en esa combinación'\n    : product.stockMode === 'on_request'\n      ? 'Bajo pedido'\n      : product.stockMode !== 'exact'\n        ? 'Disponible'\n        : tope > 0\n          ? (pocoStock ? `Quedan pocas unidades (${tope})` : `Stock: ${tope}`)\n          : 'Sin stock';\n\n  /** La foto que se enseña: la de la combinación elegida; si no, la del color elegido; si no, la 1ª. */\n  const foto = useMemo(() => {\n    if (elegida?.imageUrl) return absUrl(elegida.imageUrl);\n    for (const g of grupos) {\n      if (g.kind !== 'color') continue;\n      const v = (g.values ?? []).find((x) => x.value === sel[g.code]);\n      if (v?.imageUrl) return absUrl(v.imageUrl);\n    }\n    const primera = (product.media ?? []).find((m) => m.type !== 'video');\n    return primera ? absUrl(primera.url) : null;\n  }, [elegida, grupos, sel, product.media]);\n\n  const resumen = grupos.filter((g) => sel[g.code]).map((g) => `${g.label}: ${sel[g.code]}`).join(' · ');\n  const puedeConfirmar = !busy && (!grupos.length || (eleccionCompleta && !agotada)) && tope > 0;\n\n  /** ¿Se puede ofrecer el asistente? Solo si hay un eje de tallas Y la tienda tiene tabla para él. */\n  const tablaDelGrupo = useMemo(() => {\n    const tipo = grupoTalla?.chartKind ?? null;\n    if (!tipo) return null;\n    return tablas.find((c) => c.kind === tipo) ?? null;\n  }, [tablas, grupoTalla]);\n\n  /**\n   * AVISO DE REPOSICIÓN DE UNA COMBINACIÓN AGOTADA.\n   *\n   * El valor agotado NO se selecciona (la especificación lo pide así), pero tampoco se queda en un\n   * callejón: al tocarlo se ofrece avisar cuando vuelva ESA combinación. El servidor ya lo apunta por\n   * variante, así que quien espera la «Blanco · M» recibe el aviso de esa y no de otra talla.\n   */\n  const pedirAviso = async (code: string, value: string) => {\n    if (busyAviso) return;\n    const objetivo = varianteDe({ ...sel, [code]: value });\n    if (!objetivo?.id) return;\n    setBusyAviso(true);\n    try {\n      const r = await avisoStockApi.vigilar(product.id, objetivo.id);\n      Alert.alert(\n        r.watching ? 'Te avisamos' : 'Ya está disponible',\n        r.mensaje ?? (r.watching\n          ? `Te avisaremos por el chat cuando vuelva la «${objetivo.name}».`\n          : 'Parece que ya se puede comprar.'),\n      );\n      setAvisoPara(null);\n    } catch (e) {\n      Alert.alert('Aviso de reposición', e instanceof Error ? e.message : 'No se pudo completar');\n    } finally {\n      setBusyAviso(false);\n    }\n  };\n\n  /**\n   * CIERRE DESLIZANDO HACIA ABAJO (además de la X y de tocar fuera).\n   *\n   * El `Modal` de React Native no trae «arrastrar para cerrar», así que se pone un tirador arriba con\n   * su propio `PanResponder`: deslizar hacia abajo más de 70 dp cierra. Va SOLO en el tirador para no\n   * pelearse con el scroll de las opciones.\n   */\n  const dragY = useRef(0);\n  const pan = useMemo(() => PanResponder.create({\n    onMoveShouldSetPanResponder: (_e, g) => Math.abs(g.dy) > 6 && Math.abs(g.dy) > Math.abs(g.dx),\n    onPanResponderMove: (_e, g) => { dragY.current = Math.max(0, g.dy); },\n    onPanResponderRelease: (_e, g) => {\n      if (g.dy > 70) onClose();\n      dragY.current = 0;\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }), [onClose]);\n\n  /** Un bloque de eje (color con foto, o valores como botones). */\n  const Eje = ({ g }: { g: LbOptionGroup }) => (\n    <View style={{ marginTop: espaciado.e14 }}>\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', marginBottom: espaciado.e7 }}>\n        {g.label}{sel[g.code] ? <Text style={{ color: colors.textSecondary, fontWeight: '600' }}>{`  ${sel[g.code]}`}</Text> : null}\n      </Text>\n      <View style={styles.valores}>\n        {(g.values ?? []).map((v) => {\n          const activo = sel[g.code] === v.value;\n          const existe = existeCombo(g.code, v.value);\n          const libre = existe && disponible(g.code, v.value);\n          /**\n           * AGOTADO = existe la combinación pero no hay stock. NO se puede seleccionar (se ve apagado\n           * y tachado), pero sí tocar para pedir el aviso de reposición.\n           */\n          const agotadoAqui = existe && !libre;\n          const etiqueta = `${g.label} ${v.value}${!existe ? ' (no disponible)' : agotadoAqui ? ' (agotado)' : ''}`;\n          const onPress = () => {\n            if (libre) { setSel((p) => ({ ...p, [g.code]: v.value })); setAvisoPara(null); return; }\n            if (agotadoAqui) setAvisoPara({ code: g.code, label: g.label, value: v.value });\n          };\n          if (g.kind === 'color') {\n            return (\n              <Pressable\n                key={v.value}\n                onPress={onPress}\n                accessibilityLabel={etiqueta}\n                accessibilityState={{ selected: activo, disabled: !libre }}\n                style={[styles.colorCaja, {\n                  borderColor: activo ? colors.primary : alpha(colors.border, 0.9),\n                  borderWidth: activo ? 2 : 1,\n                  backgroundColor: activo ? alpha(colors.primary, 0.08) : 'transparent',\n                  opacity: libre ? 1 : 0.45,\n                }]}\n              >\n                {/* LA FOTO REAL del producto en ese color: no un cuadradito de color. */}\n                {v.imageUrl ? (\n                  <Image source={absUrl(v.imageUrl)} style={styles.colorImg} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                ) : (\n                  <View style={[styles.colorImg, { backgroundColor: alpha(colors.border, 0.4), alignItems: 'center', justifyContent: 'center' }]}>\n                    <Text style={{ fontSize: 9.5, color: colors.textSecondary }}>sin foto</Text>\n                  </View>\n                )}\n                <Text numberOfLines={1} style={{ color: activo ? colors.primary : colors.textPrimary, fontSize: tipografia.micro, fontWeight: '700', marginTop: espaciado.e4, maxWidth: 68, textAlign: 'center' }}>\n                  {v.value}\n                </Text>\n                {agotadoAqui ? <Text style={{ color: colors.danger, fontSize: 9.5, fontWeight: '800' }}>agotado</Text> : null}\n              </Pressable>\n            );\n          }\n          return (\n            <Pressable\n              key={v.value}\n              onPress={onPress}\n              accessibilityLabel={etiqueta}\n              accessibilityState={{ selected: activo, disabled: !libre }}\n              style={[styles.chip, {\n                borderColor: activo ? colors.primary : alpha(colors.border, 0.9),\n                backgroundColor: activo ? alpha(colors.primary, 0.1) : 'transparent',\n                opacity: libre ? 1 : 0.45,\n              }]}\n            >\n              <Text style={{\n                color: activo ? colors.primary : colors.textPrimary,\n                fontSize: tipografia.caption, fontWeight: '700',\n                textDecorationLine: libre ? 'none' : 'line-through',\n              }}>\n                {v.value}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </View>\n\n      {/* El enlace del asistente, solo si la tienda tiene tabla para ese tipo de prenda. */}\n      {g.code === grupoTalla?.code && tablaDelGrupo ? (\n        <Pressable onPress={() => setModo('talla')} accessibilityLabel=\"No sé mi talla\" style={{ marginTop: espaciado.e8 }}>\n          <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>¿No sabes tu talla?</Text>\n        </Pressable>\n      ) : null}\n\n      {/* «Avísame cuando llegue» de la combinación agotada que se ha tocado. */}\n      {avisoPara?.code === g.code ? (\n        <View style={[styles.aviso, { borderColor: alpha(colors.primary, 0.5), backgroundColor: alpha(colors.primary, 0.06) }]}>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, flex: 1 }}>\n            «{avisoPara.value}» agotada. ¿Te avisamos?\n          </Text>\n          <Pressable onPress={() => { void pedirAviso(avisoPara.code, avisoPara.value); }} disabled={busyAviso} accessibilityLabel=\"Sí, avisadme\">\n            {busyAviso ? <ActivityIndicator size=\"small\" color={colors.primary} /> : (\n              <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '900' }}>Avisadme</Text>\n            )}\n          </Pressable>\n          <Pressable onPress={() => setAvisoPara(null)} hitSlop={8} accessibilityLabel=\"No, gracias\">\n            <X size={14} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n      ) : null}\n    </View>\n  );\n\n  const principal: ModoSelector = modoInicial;\n  const secundario: ModoSelector = modoInicial === 'carrito' ? 'comprar' : 'carrito';\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={styles.backdrop} onPress={onClose} accessibilityLabel=\"Cerrar el selector\">\n        <Pressable style={[styles.sheet, { backgroundColor: colors.background }]} onPress={() => { /* dentro no se cierra */ }}>\n          {/* Tirador: deslizar hacia abajo cierra (el Modal de RN no lo trae). */}\n          <View {...pan.panHandlers} style={styles.tiradorZona} accessibilityLabel=\"Desliza hacia abajo para cerrar\">\n            <View style={[styles.tirador, { backgroundColor: alpha(colors.textSecondary, 0.4) }]} />\n          </View>\n\n          {/* ── Cabecera: la foto de lo elegido, su precio y su stock ── */}\n          <View style={{ flexDirection: 'row', alignItems: 'flex-start' }}>\n            {foto ? (\n              <Image source={foto} style={[styles.foto, { borderColor: alpha(colors.border, 0.8) }]} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n            ) : (\n              <View style={[styles.foto, { borderColor: alpha(colors.border, 0.8), backgroundColor: alpha(colors.primary, 0.1), alignItems: 'center', justifyContent: 'center' }]}>\n                <Text style={{ fontSize: 26 }}>📦</Text>\n              </View>\n            )}\n            <View style={{ flex: 1, marginLeft: espaciado.e12 }}>\n              <View style={{ flexDirection: 'row', alignItems: 'flex-end', gap: espaciado.e8 }}>\n                <Text numberOfLines={1} style={{ color: colors.primary, fontSize: 19, fontWeight: '900', flexShrink: 1 }}>\n                  {precioTexto}\n                </Text>\n                {precioAntiguo ? (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textDecorationLine: 'line-through', marginBottom: espaciado.e2 }}>\n                    {lbXaf(precioAntiguo)}\n                  </Text>\n                ) : null}\n              </View>\n              <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.caption, marginTop: espaciado.e3, lineHeight: 17 }}>\n                {resumen}\n              </Text>\n              <Text style={{ color: agotada ? colors.danger : colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }}>\n                {stockTexto}\n              </Text>\n            </View>\n            <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n              <X size={19} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n\n          {modo === 'talla' && grupoTalla ? (\n            <View style={{ marginTop: espaciado.e10 }}>\n              <Pressable onPress={() => setModo('elegir')} accessibilityLabel=\"Volver a las opciones\" style={{ marginBottom: espaciado.e8 }}>\n                <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>← Volver a las opciones</Text>\n              </Pressable>\n              <AsistenteDeTalla\n                product={product}\n                grupo={grupoTalla}\n                tablas={tablas}\n                onUsarTalla={(talla) => {\n                  setSel((p) => ({ ...p, [grupoTalla.code]: talla }));\n                  setModo('elegir');\n                }}\n              />\n            </View>\n          ) : (\n            <>\n              <ScrollView style={{ maxHeight: 380 }} showsVerticalScrollIndicator={false}>\n                {grupos.map((g) => <Eje key={g.code} g={g} />)}\n\n                {/* ── Cantidad, con el tope real ── */}\n                <View style={{ marginTop: espaciado.e16, flexDirection: 'row', alignItems: 'center' }}>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>Cantidad</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\n                      {product.stockMode === 'exact' ? `Máx. ${tope || 0}` : ''}\n                    </Text>\n                  </View>\n                  <View style={[styles.stepper, { borderColor: alpha(colors.border, 0.9) }]}>\n                    <Pressable\n                      onPress={() => setCant((c) => Math.max(1, c - 1))}\n                      disabled={cant <= 1}\n                      accessibilityLabel=\"Quitar una unidad\"\n                      style={styles.stepBtn}\n                    >\n                      <Minus size={16} color={cant <= 1 ? alpha(colors.textSecondary, 0.5) : colors.textPrimary} />\n                    </Pressable>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', minWidth: 30, textAlign: 'center' }}>{cant}</Text>\n                    <Pressable\n                      onPress={() => setCant((c) => Math.min(tope || 1, c + 1))}\n                      disabled={cant >= (tope || 1)}\n                      accessibilityLabel=\"Añadir una unidad\"\n                      style={styles.stepBtn}\n                    >\n                      <Plus size={16} color={cant >= (tope || 1) ? alpha(colors.textSecondary, 0.5) : colors.textPrimary} />\n                    </Pressable>\n                  </View>\n                </View>\n\n                {faltan.length ? (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e10 }}>\n                    Elige: {faltan.join(' · ')}\n                  </Text>\n                ) : null}\n              </ScrollView>\n\n              {/* ── Los botones: el de la acción con la que se abrió, en grande ── */}\n              <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e14 }}>\n                <Pressable\n                  onPress={() => (secundario === 'carrito'\n                    ? onCarrito({ variant: elegida, cantidad: cant })\n                    : onComprar({ variant: elegida, cantidad: cant }))}\n                  disabled={!puedeConfirmar}\n                  accessibilityLabel={secundario === 'carrito' ? 'Añadir al carrito' : 'Comprar now'}\n                  style={[styles.secBtn, { borderColor: colors.primary, opacity: puedeConfirmar ? 1 : 0.45 }]}\n                >\n                  {busy === secundario ? (\n                    <ActivityIndicator size=\"small\" color={colors.primary} />\n                  ) : (\n                    <Text numberOfLines={1} style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900' }}>\n                      {secundario === 'carrito' ? 'Al carrito' : 'Comprar now'}\n                    </Text>\n                  )}\n                </Pressable>\n                <Pressable\n                  onPress={() => (principal === 'carrito'\n                    ? onCarrito({ variant: elegida, cantidad: cant })\n                    : onComprar({ variant: elegida, cantidad: cant }))}\n                  disabled={!puedeConfirmar}\n                  accessibilityLabel={principal === 'carrito' ? 'Añadir al carrito' : 'Comprar now'}\n                  style={[styles.priBtn, { backgroundColor: puedeConfirmar ? colors.primary : alpha(colors.primary, 0.4) }]}\n                >\n                  {busy === principal ? (\n                    <ActivityIndicator size=\"small\" color={brand.white} />\n                  ) : (\n                    <Text numberOfLines={1} style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '900' }}>\n                      {principal === 'carrito' ? 'Añadir al carrito' : 'Comprar now'}\n                    </Text>\n                  )}\n                </Pressable>\n              </View>\n            </>\n          )}\n        </Pressable>\n      </Pressable>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' },\n  sheet: { borderTopLeftRadius: 20, borderTopRightRadius: 20, paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e24 },\n  tiradorZona: { paddingVertical: espaciado.e8, alignItems: 'center' },\n  tirador: { width: 44, height: 4, borderRadius: 2 },\n  foto: { width: 92, height: 92, borderRadius: radios.md, borderWidth: 1, overflow: 'hidden' },\n  valores: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e9 },\n  colorCaja: { alignItems: 'center', borderRadius: radios.md, padding: espaciado.e5 },\n  colorImg: { width: 58, height: 58, borderRadius: 9 },\n  chip: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e13, minHeight: 44, minWidth: 46, alignItems: 'center', justifyContent: 'center' },\n  stepper: { flexDirection: 'row', alignItems: 'center', borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e4, minHeight: 44 },\n  stepBtn: { width: 40, height: 40, alignItems: 'center', justifyContent: 'center' },\n  aviso: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderWidth: 1, borderRadius: 10, padding: espaciado.e9, marginTop: espaciado.e8 },\n  secBtn: { flex: 1, height: 46, borderRadius: radios.md, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e8 },\n  priBtn: { flex: 1.4, height: 46, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e10 },\n});\n","/**\n * components/lifebook/AsistenteDeTalla.tsx — «¿NO SABES TU TALLA?» (tanda L).\n *\n * QUÉ RESUELVE. El comerciante ya puede escribir su tabla de tallas (tanda J) y el comprador ya\n * elige talla y color (tanda K), pero **nadie usaba la tabla**: para saber la talla había que\n * adivinar. Aquí se comparan TUS medidas con la tabla DE ESE PRODUCTO y se dice la talla, POR QUÉ y\n * con qué ajuste. Es exactamente lo que hace el servidor (`POST products/:id/size-suggestion`).\n *\n * TRES REGLAS QUE NO SE ROMPEN:\n *   1. **No se inventa nada.** Si esa tienda no ha configurado tabla (o no hay para ese sexo y ese\n *      tipo de prenda), se dice y se acabó: no hay talla «aproximada».\n *   2. **Las medidas no salen de la cuenta.** Solo se guardan si tú lo pides, y la tienda nunca las\n *      ve: lo único que viaja en el pedido es la talla elegida.\n *   3. **La talla la eliges tú.** La recomendación es una sugerencia con su razón; «Usar esta talla»\n *      la marca, pero puedes poner otra.\n *\n * Las medidas de ropa y las del pie son **independientes** (como pidió el dueño): tener unas no\n * obliga a tener las otras.\n */\nimport React, { useEffect, useMemo, useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { commerceApi, tallasApi, type LbMeasurements, type LbOptionGroup, type LbProduct, type LbSizeChart, type LbSizeKind, type LbSizeSuggestion } from '../../api/commerce';\nimport { NUMEROS_CALZADO, cmDeNumero, numeroDeCm } from '../../constants/tallas';\nimport { Chip, ChipRow } from './Chip';\nimport RuletaVertical, { rango } from './RuletaVertical';\n\n/** La medida que DECIDE la talla en cada tipo de prenda (la misma tabla que usa el servidor). */\nconst PRINCIPAL: Record<LbSizeKind, keyof Medidas> = {\n  top: 'altura', dress: 'altura', bottom: 'peso', shoes: 'pieLargo', accessory: 'altura', other: 'altura',\n};\n\n/**\n * LAS MEDIDAS QUE SE PIDEN — UN JUEGO ÚNICO (tandas L-bis y L-ter).\n *\n * El dueño lo dejó claro en dos pasos: «elimina las medidas de pecho, cintura, cadera» y «altura, peso\n * y el número de calzado van juntos, el guardado será juntos». Así que se piden **tres cosas y\n * siempre las tres**, se guardan de una vez y se leen de una vez: da igual si estás mirando una\n * camiseta o unas zapatillas, tus medidas son tuyas y son las mismas.\n *\n * El número de calzado se guarda en centímetros (el servidor y las tablas de las tiendas van en cm):\n * la equivalencia está en `constants/tallas.ts` y es la misma que usa el comerciante al publicar.\n *\n * El pecho, la cintura y la cadera siguen existiendo pero **empiezan en `null`** y no se piden: hay\n * tiendas cuya tabla mide así y entonces se ofrecen como opcionales. Si se mandaran con un valor por\n * defecto, el servidor los tomaría como si el cliente los hubiera dicho y la talla saldría de un\n * número inventado.\n */\ninterface Medidas {\n  pecho: number | null; cintura: number | null; cadera: number | null;\n  altura: number; peso: number;\n  pieLargo: number;\n}\n\nconst DE_FABRICA: Medidas = { pecho: null, cintura: null, cadera: null, altura: 168, peso: 65, pieLargo: 26 };\n\nconst nombreTipo = (k: LbSizeKind): string => ({\n  top: 'parte de arriba', bottom: 'parte de abajo', dress: 'vestido', shoes: 'calzado', accessory: 'accesorio', other: 'prenda',\n}[k]);\n\nexport default function AsistenteDeTalla({\n  product, grupo, tablas: tablasDelPanel, onUsarTalla,\n}: {\n  product: LbProduct;\n  /** El eje de tallas del producto (trae contra qué tabla se compara). */\n  grupo: LbOptionGroup;\n  /** Las tablas que ya cargó el panel; si no vienen, se piden aquí. */\n  tablas?: LbSizeChart[];\n  onUsarTalla: (talla: string) => void;\n}) {\n  const { colors } = useTheme();\n  const tipo = (grupo.chartKind ?? 'top') as LbSizeKind;\n  const esCalzado = tipo === 'shoes';\n\n  const [tablas, setTablas] = useState<LbSizeChart[] | null>(tablasDelPanel ?? null);\n  const [genero, setGenero] = useState<'women' | 'men'>('women');\n  const [medidas, setMedidas] = useState<Medidas>(DE_FABRICA);\n  const [deGuardadas, setDeGuardadas] = useState(false);\n  const [resultado, setResultado] = useState<LbSizeSuggestion | null>(null);\n  const [calculando, setCalculando] = useState(false);\n  const [guardando, setGuardando] = useState(false);\n  const [guardadas, setGuardadas] = useState(false);\n  /** Las medidas opcionales (pecho/cintura/cadera) están escondidas salvo que hagan falta. */\n  const [verOpcionales, setVerOpcionales] = useState(false);\n  /**\n   * Mientras se desliza una ruleta, el scroll del panel se apaga: si no, en Android los dos scrolls\n   * verticales se pelean y la medida no cambia (el fallo que se vio en el móvil).\n   */\n  const [arrastrando, setArrastrando] = useState(false);\n\n  /** Las tablas del producto y mis medidas guardadas, en una sola carga. */\n  useEffect(() => {\n    let vivo = true;\n    (async () => {\n      // Las tablas se piden solo si el panel no las tenía ya (evita dos veces la misma llamada).\n      const [chart, mias] = await Promise.all([\n        tablasDelPanel ? Promise.resolve({ charts: tablasDelPanel }) : commerceApi.sizeChart(product.id).catch(() => ({ charts: [] as LbSizeChart[] })),\n        tallasApi.misMedidas().catch(() => ({ body: null, feet: null })),\n      ]);\n      if (!vivo) return;\n      setTablas(chart.charts ?? []);\n      /**\n       * UN JUEGO ÚNICO: se lee la fila unificada (el servidor devuelve el mismo juego en `body` y en\n       * `feet` desde el parche 69; `feet` queda como respaldo de datos antiguos).\n       */\n      const guardada: LbMeasurements | null = mias.body ?? mias.feet;\n      if (guardada) {\n        setDeGuardadas(true);\n        if (guardada.gender) setGenero(guardada.gender);\n        setMedidas((m) => ({\n          pecho: guardada.chestCm ?? m.pecho,\n          cintura: guardada.waistCm ?? m.cintura,\n          cadera: guardada.hipCm ?? m.cadera,\n          altura: guardada.heightCm ?? m.altura,\n          peso: guardada.weightKg ?? m.peso,\n          pieLargo: guardada.footLengthCm ?? m.pieLargo,\n        }));\n        if (guardada.chestCm || guardada.waistCm || guardada.hipCm) setVerOpcionales(true);\n      }\n    })();\n    return () => { vivo = false; };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [product.id, tablasDelPanel]);\n\n  /**\n   * ¿Hay tabla para ESTE tipo y ESTE sexo? Se mira antes de enseñar las ruletas: si no la hay, no se\n   * piden medidas para nada (y se dice por qué no se puede recomendar).\n   */\n  const tabla = useMemo(() => {\n    const lista = tablas ?? [];\n    return lista.find((c) => c.kind === tipo && c.gender === genero)\n      ?? lista.find((c) => c.kind === tipo && c.gender === 'unisex')\n      ?? null;\n  }, [tablas, tipo, genero]);\n\n  const principal = PRINCIPAL[tipo];\n  const valorPrincipal = medidas[principal];\n\n  const verMiTalla = async () => {\n    setCalculando(true);\n    setResultado(null);\n    try {\n      const r = await tallasApi.sugerir(product.id, {\n        kind: tipo,\n        gender: genero,\n        heightCm: medidas.altura,\n        weightKg: medidas.peso,\n        /**\n         * El número de calzado va SIEMPRE, aunque la prenda no sea calzado: las medidas son un juego\n         * único y así el servidor tiene todo lo que sabe de ti. Para una camiseta simplemente no lo\n         * usa (su tabla no lo declara).\n         */\n        footLengthCm: medidas.pieLargo,\n        // Los opcionales, solo si el cliente los ha dado de verdad: `undefined` = «no lo sé».\n        ...(medidas.pecho !== null ? { chestCm: medidas.pecho } : {}),\n        ...(medidas.cintura !== null ? { waistCm: medidas.cintura } : {}),\n        ...(medidas.cadera !== null ? { hipCm: medidas.cadera } : {}),\n      });\n      setResultado(r);\n      /**\n       * Si la tabla de la tienda mide por pecho/cintura/cadera (hay tiendas que publican así), el\n       * servidor lo dice; entonces se enseñan esas medidas como opcionales en vez de dejar al\n       * cliente en un «nos falta tu pecho» sin salida.\n       */\n      if (/nos falta tu (pecho|cintura|cadera)/i.test(r.reason)) setVerOpcionales(true);\n    } catch (e) {\n      Alert.alert('No se pudo calcular', e instanceof Error ? e.message : 'Inténtalo otra vez');\n    } finally {\n      setCalculando(false);\n    }\n  };\n\n  const guardar = async () => {\n    setGuardando(true);\n    try {\n      /**\n       * UN SOLO GUARDADO (petición del dueño): altura, peso y número de calzado van juntos. Se manda\n       * sin categoría, así que el servidor lo guarda como un juego único.\n       */\n      await tallasApi.guardarMedidas({\n        gender: genero,\n        heightCm: medidas.altura,\n        weightKg: medidas.peso,\n        footLengthCm: medidas.pieLargo,\n        ...(medidas.pecho !== null ? { chestCm: medidas.pecho } : {}),\n        ...(medidas.cintura !== null ? { waistCm: medidas.cintura } : {}),\n        ...(medidas.cadera !== null ? { hipCm: medidas.cadera } : {}),\n      });\n      setGuardadas(true);\n      setDeGuardadas(true);\n      Alert.alert('Guardadas', 'Tus medidas se guardan juntas (altura, peso y número de calzado). La próxima vez las usamos sin preguntarte. Solo las ves tú: la tienda nunca las recibe.');\n    } catch (e) {\n      Alert.alert('No se pudieron guardar', e instanceof Error ? e.message : 'Inténtalo otra vez');\n    } finally {\n      setGuardando(false);\n    }\n  };\n\n  const borrar = () => {\n    Alert.alert('Borrar mis medidas', 'Se borran tus medidas (altura, peso y número de calzado). Dejarás de tenerlas guardadas.', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Borrar',\n        style: 'destructive',\n        onPress: async () => {\n          try {\n            await tallasApi.borrarMedidas();\n            setDeGuardadas(false);\n            setGuardadas(false);\n            setResultado(null);\n          } catch (e) {\n            Alert.alert('No se pudieron borrar', e instanceof Error ? e.message : 'Inténtalo otra vez');\n          }\n        },\n      },\n    ]);\n  };\n\n  /** ¿La talla recomendada está entre las tallas que vende el producto? */\n  const tallaEnElProducto = (talla: string): string | null => {\n    const v = (grupo.values ?? []).find((x) => x.value.trim().toLowerCase() === talla.trim().toLowerCase());\n    return v ? v.value : null;\n  };\n\n  if (tablas === null) {\n    return (\n      <View style={{ paddingVertical: espaciado.e26, alignItems: 'center' }}>\n        <ActivityIndicator color={colors.primary} />\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>Mirando la tabla de esta tienda…</Text>\n      </View>\n    );\n  }\n\n  if (!tabla) {\n    return (\n      <View>\n        <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginBottom: espaciado.e6 }}>\n          Esta tienda todavía no tiene tabla de tallas\n        </Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 18 }}>\n          No hay tabla de {nombreTipo(tipo)} {tablas.length ? 'para esas medidas' : 'configurada para este producto'}, así que\n          no podemos recomendarte una talla: inventárnosla sería peor que no decir nada. Puedes preguntarle a la tienda\n          por el chat, o guiarte por las tallas que tiene el producto.\n        </Text>\n      </View>\n    );\n  }\n\n  /**\n   * Se sacan a constantes ANTES del JSX a propósito: dentro de una función de `onPress`, TypeScript\n   * ya no conserva el estrechamiento de `resultado.size` (es una propiedad de estado) y se quejaba\n   * de `string | null`. Con una constante el valor queda fijado y legible.\n   */\n  const tallaRecomendada: string | null = resultado?.size ?? null;\n  const tallaEnEsteProducto: string | null = tallaRecomendada ? tallaEnElProducto(tallaRecomendada) : null;\n\n  return (\n    <View>\n      {/**\n       * LAS RULETAS CON SCROLL, PERO **LOS BOTONES SIEMPRE A LA VISTA**.\n       *\n       * Antes todo el asistente iba dentro del mismo scroll y «Ver mi talla» y «Guardar mis medidas»\n       * quedaban por debajo del borde: el dueño lo dijo tal cual —«entre los tres no hay un botón\n       * guardar, ni ajustar»—. Un botón al que hay que bajar deslizando, con ruletas dentro que\n       * también se deslizan, en la práctica no existe. Así que el pie va FIJO, fuera del scroll.\n       */}\n      <ScrollView showsVerticalScrollIndicator={false} style={{ maxHeight: 250 }} nestedScrollEnabled scrollEnabled={!arrastrando}>\n        <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900', marginBottom: espaciado.e10 }}>Tu talla</Text>\n\n        {/* Sexo: las tablas son distintas, y si la de la tienda es unisex vale para los dos. */}\n        <ChipRow>\n          <Chip compact label=\"Mujer\" active={genero === 'women'} onPress={() => { setGenero('women'); setResultado(null); }} />\n          <Chip compact label=\"Hombre\" active={genero === 'men'} onPress={() => { setGenero('men'); setResultado(null); }} />\n        </ChipRow>\n\n        <View style={styles.ruletas}>\n          <RuletaVertical onArrastre={setArrastrando} etiqueta=\"Altura\" sufijo=\"cm\" valores={rango(130, 220)}\n            valor={medidas.altura} onChange={(v) => { setMedidas((m) => ({ ...m, altura: v })); setResultado(null); }} />\n          <RuletaVertical onArrastre={setArrastrando} etiqueta=\"Peso\" sufijo=\"kg\" valores={rango(30, 180)}\n            valor={medidas.peso} onChange={(v) => { setMedidas((m) => ({ ...m, peso: v })); setResultado(null); }} />\n          <RuletaVertical onArrastre={setArrastrando} etiqueta=\"Calzado\" valores={NUMEROS_CALZADO}\n            valor={numeroDeCm(medidas.pieLargo)}\n            onChange={(v) => { setMedidas((m) => ({ ...m, pieLargo: cmDeNumero(v) })); setResultado(null); }} />\n          {verOpcionales ? (\n            <>\n              <RuletaVertical onArrastre={setArrastrando} etiqueta=\"Pecho\" sufijo=\"cm\" valores={rango(60, 150)}\n                valor={medidas.pecho ?? 92} onChange={(v) => { setMedidas((m) => ({ ...m, pecho: v })); setResultado(null); }} />\n              <RuletaVertical onArrastre={setArrastrando} etiqueta=\"Cintura\" sufijo=\"cm\" valores={rango(50, 140)}\n                valor={medidas.cintura ?? 78} onChange={(v) => { setMedidas((m) => ({ ...m, cintura: v })); setResultado(null); }} />\n              <RuletaVertical onArrastre={setArrastrando} etiqueta=\"Cadera\" sufijo=\"cm\" valores={rango(60, 150)}\n                valor={medidas.cadera ?? 96} onChange={(v) => { setMedidas((m) => ({ ...m, cadera: v })); setResultado(null); }} />\n            </>\n          ) : null}\n        </View>\n\n        {!verOpcionales ? (\n          <Pressable onPress={() => setVerOpcionales(true)} accessibilityLabel=\"Añadir pecho, cintura o cadera\" style={{ marginTop: espaciado.e8 }}>\n            <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>+ Pecho · Cintura · Cadera</Text>\n          </Pressable>\n        ) : null}\n      </ScrollView>\n\n      {/**\n       * PIE FIJO: el resultado y los dos botones, sin scroll de por medio.\n       *   · «Ajustar mi talla» → calcula la recomendación con la tabla de la tienda.\n       *   · «Guardar mis medidas» → guarda altura, peso y número juntos.\n       */}\n      {resultado ? (\n        <View style={[styles.tarjeta, {\n          borderColor: resultado.size ? colors.success : colors.danger,\n          backgroundColor: alpha(resultado.size ? colors.success : colors.danger, 0.08),\n        }]}>\n          {tallaRecomendada ? (\n            <>\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>\n                Tu talla: {tallaRecomendada}{resultado?.fit ? ` · ajuste ${resultado.fit}` : ''}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginTop: espaciado.e4 }}>{resultado?.reason}</Text>\n              {tallaEnEsteProducto ? (\n                <Pressable\n                  onPress={() => onUsarTalla(tallaEnEsteProducto)}\n                  accessibilityLabel={`Usar la talla ${tallaRecomendada}`}\n                  style={[styles.usar, { backgroundColor: colors.primary }]}\n                >\n                  <Text style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '900' }}>Usar esta talla</Text>\n                </Pressable>\n              ) : (\n                <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '800', marginTop: espaciado.e8 }}>\n                  La tabla recomienda la {tallaRecomendada}, pero este producto no la tiene entre sus tallas. Elige la más cercana.\n                </Text>\n              )}\n            </>\n          ) : (\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, lineHeight: 18, fontWeight: '700' }}>{resultado?.reason}</Text>\n          )}\n        </View>\n      ) : null}\n\n      <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e10 }}>\n        <Pressable\n          onPress={() => { if (!calculando) void verMiTalla(); }}\n          disabled={calculando}\n          accessibilityLabel=\"Ajustar mi talla\"\n          style={[styles.botonPie, { flex: 1.3, backgroundColor: calculando ? alpha(colors.primary, 0.5) : colors.primary }]}\n        >\n          {calculando\n            ? <ActivityIndicator size=\"small\" color={brand.white} />\n            : <Text style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '900' }}>Ajustar mi talla</Text>}\n        </Pressable>\n        <Pressable\n          onPress={() => { if (!guardando && !guardadas) void guardar(); }}\n          disabled={guardando || guardadas}\n          accessibilityLabel=\"Guardar mis medidas\"\n          style={[styles.botonPie, { flex: 1, borderWidth: 1.5, borderColor: colors.primary }]}\n        >\n          {guardando\n            ? <ActivityIndicator size=\"small\" color={colors.primary} />\n            : (\n              <Text numberOfLines={1} style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900' }}>\n                {guardadas ? 'Guardadas ✓' : 'Guardar medidas'}\n              </Text>\n            )}\n        </Pressable>\n      </View>\n\n      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'flex-end', marginTop: espaciado.e6, gap: espaciado.e10 }}>\n        {deGuardadas ? (\n          <Pressable onPress={borrar} accessibilityLabel=\"Borrar mis medidas\">\n            <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '800' }}>Borrar mis medidas</Text>\n          </Pressable>\n        ) : null}\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  ruletas: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10, marginTop: espaciado.e12, marginBottom: espaciado.e4 },\n  tarjeta: { borderWidth: 1.5, borderRadius: radios.md, padding: espaciado.e11, marginTop: espaciado.e12 },\n  usar: { marginTop: espaciado.e10, height: 40, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },\n  /** Los botones del pie fijo: la misma altura que los del panel, para que la fila cuadre. */\n  botonPie: { height: 46, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e10 },\n});\n","/**\n * components/lifebook/RuletaVertical.tsx — la RULETA de una medida (tanda L).\n *\n * POR QUÉ UNA RULETA Y NO UN CAMPO DE TEXTO. El dueño lo pidió así («ruletas verticales») y es lo\n * que usan las apps de comercio para medidas: elegir «168 cm» deslizando es más rápido y menos\n * propenso a errores que teclear tres números en un móvil. Además, al ser una lista cerrada, es\n * **imposible** mandar un pecho de 900 cm: el servidor lo rechazaría, y aquí ni se puede elegir.\n *\n * ── EL FALLO QUE HUBO QUE ARREGLAR (medido en el Poco F5) ─────────────────────────────────────\n * La primera versión NO DEJABA ELEGIR: la ruleta es un `ScrollView` vertical metido dentro del\n * `ScrollView` del asistente, y en Android **el de fuera se come el gesto**, así que el de dentro no\n * se movía nunca y la medida no cambiaba. Tres arreglos, para que no vuelva a pasar:\n *   1. `nestedScrollEnabled` en los dos scrolls: es lo que permite que un scroll vertical anidado\n *      funcione en Android.\n *   2. **Tocar un valor lo elige** (y la ruleta se centra en él). Con el dedo o sin él, siempre hay\n *      una forma de seleccionar que no depende de acertar con el gesto.\n *   3. El centrado inicial se hace cuando la ruleta ya tiene tamaño (`onLayout`), no con un\n *      temporizador que podía dispararse antes de que hubiera nada que desplazar.\n */\nimport React, { useEffect, useRef } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\n\nconst ALTO_FILA = 40;\nconst FILAS_VISIBLES = 5;\nconst ALTO = ALTO_FILA * FILAS_VISIBLES;\n\nexport default function RuletaVertical({\n  etiqueta, sufijo, valores, valor, onChange, ancho = 96, onArrastre,\n}: {\n  etiqueta: string;\n  sufijo?: string;\n  valores: number[];\n  valor: number;\n  onChange: (v: number) => void;\n  ancho?: number;\n  /** Avisa al padre de si se está deslizando la ruleta (para no mover el panel a la vez). */\n  onArrastre?: (activo: boolean) => void;\n}) {\n  const { colors } = useTheme();\n  const ref = useRef<ScrollView>(null);\n  const listo = useRef(false);\n\n  /** Centra la ruleta en el valor elegido (al abrir con medidas guardadas, y si cambia desde fuera). */\n  const centrar = (animado: boolean) => {\n    const i = Math.max(0, valores.indexOf(valor));\n    ref.current?.scrollTo({ y: i * ALTO_FILA, animated: animado });\n  };\n  useEffect(() => {\n    if (listo.current) centrar(true);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [valor]);\n\n  const fijar = (y: number) => {\n    const i = Math.min(valores.length - 1, Math.max(0, Math.round(y / ALTO_FILA)));\n    const v = valores[i];\n    if (v !== undefined && v !== valor) onChange(v);\n  };\n\n  return (\n    <View style={{ width: ancho, alignItems: 'center' }}>\n      <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700', marginBottom: espaciado.e4, textAlign: 'center' }}>\n        {etiqueta}\n      </Text>\n      <View style={[styles.caja, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.surface }]}>\n        {/* La banda de la fila que cuenta (la del centro). */}\n        <View\n          pointerEvents=\"none\"\n          style={[styles.banda, { top: ALTO_FILA * 2, borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.08) }]}\n        />\n        <ScrollView\n          ref={ref}\n          showsVerticalScrollIndicator={false}\n          snapToInterval={ALTO_FILA}\n          decelerationRate=\"fast\"\n          /* Android: sin esto, el scroll de fuera se come el gesto y la ruleta no se mueve. */\n          nestedScrollEnabled\n          onLayout={() => { if (!listo.current) { listo.current = true; centrar(false); } }}\n          onTouchStart={() => onArrastre?.(true)}\n          onTouchEnd={() => onArrastre?.(false)}\n          onTouchCancel={() => onArrastre?.(false)}\n          onScrollBeginDrag={() => onArrastre?.(true)}\n          onMomentumScrollEnd={(e) => { fijar(e.nativeEvent.contentOffset.y); onArrastre?.(false); }}\n          onScrollEndDrag={(e) => { fijar(e.nativeEvent.contentOffset.y); onArrastre?.(false); }}\n          contentContainerStyle={{ paddingVertical: ALTO_FILA * 2 }}\n        >\n          {valores.map((v, i) => {\n            const activo = v === valor;\n            return (\n              <Pressable\n                key={v}\n                /* Tocar un valor lo elige: siempre hay una forma de seleccionar sin depender del gesto. */\n                onPress={() => { onChange(v); ref.current?.scrollTo({ y: i * ALTO_FILA, animated: true }); }}\n                accessibilityLabel={`${etiqueta} ${v}${sufijo ? ` ${sufijo}` : ''}`}\n                accessibilityState={{ selected: activo }}\n                style={{ height: ALTO_FILA, alignItems: 'center', justifyContent: 'center' }}\n              >\n                <Text style={{\n                  color: activo ? colors.primary : colors.textSecondary,\n                  fontSize: activo ? 16 : 14,\n                  fontWeight: activo ? '900' : '600',\n                }}>\n                  {v}{sufijo ? ` ${sufijo}` : ''}\n                </Text>\n              </Pressable>\n            );\n          })}\n        </ScrollView>\n      </View>\n    </View>\n  );\n}\n\n/** Los valores de una medida, del mínimo al máximo (valores redondos, como los de una cinta métrica). */\nexport function rango(min: number, max: number, paso = 1): number[] {\n  const out: number[] = [];\n  for (let v = min; v <= max; v += paso) out.push(v);\n  return out;\n}\n\nconst styles = StyleSheet.create({\n  caja: { width: '100%', height: ALTO, borderWidth: 1, borderRadius: radios.md, overflow: 'hidden' },\n  banda: {\n    position: 'absolute', left: 0, right: 0, height: ALTO_FILA,\n    borderTopWidth: 1, borderBottomWidth: 1, zIndex: 1,\n  },\n});\n","/**\n * Life Book — ESCANEAR (/lifebook-scan)\n *\n * Marco de escaneo de QR. Hoy es la PANTALLA (diseño), sin cámara activa:\n * leer un QR de amigo/grupo necesita `expo-camera` + búsqueda por EG-ID en el\n * servidor (pendiente). El escáner de DOCUMENTOS real está en `/scanner`.\n */\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { ArrowLeft, ScanLine } from 'lucide-react-native';\nimport { brand, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useRouter } from 'expo-router';\n\nexport default function LifeBookScan() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n\n  return (\n    <View style={{ flex: 1, backgroundColor: '#000000', paddingTop: insets.top }}>\n      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}>\n        <Pressable onPress={() => router.back()} hitSlop={8} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={brand.white} />\n        </Pressable>\n        <Text style={{ color: brand.white, fontWeight: '800', marginLeft: espaciado.e10, fontSize: tipografia.subtitle }}>Escanear</Text>\n      </View>\n\n      {/* Aquí se integrará expo-camera / lector de QR */}\n      <View style={styles.frame}>\n        <View style={styles.box} />\n        <ScanLine size={34} color={brand.white} style={{ position: 'absolute' }} />\n      </View>\n\n      <Text style={{ color: 'rgba(255,255,255,0.7)', textAlign: 'center', fontSize: tipografia.caption, marginTop: espaciado.e16, lineHeight: 18 }}>\n        Apunta al código QR para añadir amigos,{'\\n'}unirte a grupos o abrir publicaciones\n      </Text>\n\n      <Text style={{ color: 'rgba(255,255,255,0.45)', textAlign: 'center', fontSize: tipografia.micro, marginTop: espaciado.e10, marginBottom: insets.bottom + 24 }}>\n        Lector pendiente: necesita cámara y búsqueda por EG-ID en el servidor.\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  frame: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  box: {\n    width: 220, height: 220, borderRadius: 18,\n    borderWidth: 2, borderColor: 'rgba(255,255,255,0.6)',\n    borderStyle: 'dashed',\n  },\n});\n","/**\n * Life Book — BÚSQUEDA (estilo Xiaohongshu)\n *\n * Estructura:\n *  - Barra de búsqueda con auto-focus y botón cancelar.\n *  - Sin texto: historial + tendencias reales + categorías sugeridas.\n *  - Con texto: resultados en masonry (misma tarjeta y reparto que el feed).\n *  - Sugerencias en tiempo real (debounce 350 ms).\n *\n * API (Parte 9, desplegada en HK):\n *   GET /lifebook/search?q=…&type=…&city=…&cursor=…\n *   GET /lifebook/search/trends?city=…\n *   GET /lifebook/search/suggest?q=…\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator,\n  Alert,\n  Dimensions,\n  FlatList,\n  Keyboard,\n  Pressable,\n  ScrollView,\n  StyleSheet,\n  Text,\n  TextInput,\n  View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { alpha, EmptyState, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport {\n  Clock,\n  Flame,\n  Hash,\n  MapPin,\n  Search,\n  TrendingUp,\n  User as UserIcon,\n  X,\n} from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport {\n  lifebookActionsApi,\n  lifebookApi,\n  LB_CARD_DEFAULT_RATIO,\n  toPostCard,\n  type LbPostCard,\n  type LbSuggestion,\n  type LbTrend,\n} from '../api/lifebook';\nimport { authApi } from '../api/auth';\nimport { PostCard } from '../components/lifebook/PostCard';\nimport { ReportSheet } from '../components/lifebook/ReportSheet';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst { width: SCREEN_W } = Dimensions.get('window');\nconst COLUMN_GAP = 8;\nconst SIDE_PADDING = 10;\nconst COLUMN_W = (SCREEN_W - SIDE_PADDING * 2 - COLUMN_GAP) / 2;\nconst HISTORY_KEY = 'lb_search_history';\n\n/* Filtros de tipo de contenido (tipos de publicación + canales temáticos) */\nconst SEARCH_FILTERS = [\n  { id: 'all', label: 'Todo' },\n  { id: 'note', label: 'Notas' },\n  { id: 'video', label: 'Videos' },\n  { id: 'sale', label: 'Ventas' },\n  { id: 'debate', label: 'Debates' },\n  { id: 'food', label: 'Comida' },\n  { id: 'taxi', label: 'Taxi' },\n] as const;\n\n/* Categorías sugeridas cuando aún no hay texto */\nconst DISCOVER_TAGS = ['Comida local', 'Malabo', 'Bata', 'Música', 'Trabajo', 'Alquiler', 'Taxi', 'Moda', 'Fútbol', 'Emprendimiento'];\n\nexport default function LifeBookSearchScreen() {\n  return (\n    <AuthGate>\n      <LifeBookSearchContent />\n    </AuthGate>\n  );\n}\n\nfunction LifeBookSearchContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  // Permite abrir la búsqueda ya con un término (p. ej. desde un #tema del detalle).\n  const { q: qParam } = useLocalSearchParams<{ q?: string }>();\n\n  const inputRef = useRef<TextInput>(null);\n  const debounceRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);\n  const appliedQ = useRef<string | null>(null);\n\n  /* ── Estado ── */\n  const [query, setQuery] = useState('');\n  const [filter, setFilter] = useState<string>('all');\n  const [city, setCity] = useState('Malabo');\n  const [history, setHistory] = useState<string[]>([]);\n  const [trends, setTrends] = useState<LbTrend[]>([]);\n  const [suggestions, setSuggestions] = useState<LbSuggestion[]>([]);\n  const [results, setResults] = useState<LbPostCard[]>([]);\n  const [nextCursor, setNextCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [hasSearched, setHasSearched] = useState(false);\n  const [showSuggestions, setShowSuggestions] = useState(false);\n  const [morePost, setMorePost] = useState<LbPostCard | null>(null);\n\n  const busy = useRef(false);\n  const mounted = useRef(true);\n\n  /* ── Historial (persistencia local) ── */\n  const loadHistory = useCallback(async () => {\n    try {\n      const stored = await AsyncStorage.getItem(HISTORY_KEY);\n      if (stored && mounted.current) setHistory(JSON.parse(stored));\n    } catch { /* silencioso */ }\n  }, []);\n\n  const saveToHistory = useCallback((term: string, current: string[]) => {\n    const t = term.trim();\n    if (!t) return;\n    const next = [t, ...current.filter((h) => h !== t)].slice(0, 15);\n    setHistory(next);\n    AsyncStorage.setItem(HISTORY_KEY, JSON.stringify(next)).catch(() => {});\n  }, []);\n\n  const clearHistory = useCallback(() => {\n    setHistory([]);\n    AsyncStorage.removeItem(HISTORY_KEY).catch(() => {});\n  }, []);\n\n  /* ── Tendencias reales del servidor (30 días) ── */\n  const loadTrends = useCallback(async (cty: string) => {\n    try {\n      const data = await lifebookApi.searchTrends({ city: cty });\n      if (mounted.current) setTrends(data?.trends ?? []);\n    } catch { /* silencioso */ }\n  }, []);\n\n  /* ── Auto-focus + ciudad del usuario ── */\n  useEffect(() => {\n    mounted.current = true;\n    const t = setTimeout(() => inputRef.current?.focus(), 300);\n    loadHistory();\n    authApi.me()\n      .then((m) => { if (m?.city && mounted.current) setCity(m.city); })\n      .catch(() => {});\n    return () => {\n      mounted.current = false;\n      clearTimeout(t);\n      if (debounceRef.current) clearTimeout(debounceRef.current);\n    };\n  }, [loadHistory]);\n\n  useEffect(() => { loadTrends(city); }, [city, loadTrends]);\n\n  /* ── Sugerencias en tiempo real (debounce 350 ms) ── */\n  const fetchSuggestions = useCallback(async (q: string) => {\n    if (q.trim().length < 2) {\n      setSuggestions([]);\n      setShowSuggestions(false);\n      return;\n    }\n    try {\n      const data = await lifebookApi.searchSuggest(q);\n      if (mounted.current) {\n        setSuggestions(data?.suggestions ?? []);\n        setShowSuggestions(true);\n      }\n    } catch { /* silencioso */ }\n  }, []);\n\n  const onQueryChange = (text: string) => {\n    setQuery(text);\n    setShowSuggestions(true);\n    if (debounceRef.current) clearTimeout(debounceRef.current);\n    debounceRef.current = setTimeout(() => fetchSuggestions(text), 350);\n  };\n\n  /* ── Búsqueda principal ── */\n  const doSearch = useCallback(\n    async (q: string, reset = true, filterOverride?: string) => {\n      const term = q.trim();\n      if (!term || busy.current) return;\n      const activeFilter = filterOverride ?? filter;\n      busy.current = true;\n      setShowSuggestions(false);\n      Keyboard.dismiss();\n      saveToHistory(term, history);\n\n      if (reset) {\n        setLoading(true);\n        setHasSearched(true);\n      } else {\n        setLoadingMore(true);\n      }\n\n      try {\n        const page = await lifebookApi.search(term, {\n          type: activeFilter === 'all' ? undefined : activeFilter,\n          city,\n          cursor: reset ? undefined : nextCursor ?? undefined,\n          limit: 20,\n        });\n        if (!mounted.current) return;\n        const cards = (page.posts ?? []).map(toPostCard);\n        if (reset) {\n          setResults(cards);\n        } else {\n          setResults((prev) => {\n            const seen = new Set(prev.map((p) => p.id));\n            return [...prev, ...cards.filter((p) => !seen.has(p.id))];\n          });\n        }\n        setNextCursor(page.nextCursor ?? null);\n      } catch (e) {\n        if (mounted.current) {\n          Alert.alert('Buscar', e instanceof Error ? e.message : 'No se pudo buscar.');\n        }\n      } finally {\n        busy.current = false;\n        if (mounted.current) {\n          setLoading(false);\n          setLoadingMore(false);\n        }\n      }\n    },\n    [filter, nextCursor, city, history, saveToHistory],\n  );\n\n  const onFilterChange = (f: string) => {\n    setFilter(f);\n    // El filtro nuevo se pasa explícito: setFilter aún no se ha aplicado.\n    if (query.trim()) doSearch(query, true, f);\n  };\n\n  /* ── Término inicial recibido por parámetro (#tema del detalle) ── */\n  useEffect(() => {\n    const term = (qParam ?? '').trim();\n    if (!term || appliedQ.current === term) return;\n    appliedQ.current = term;\n    setQuery(term);\n    // Se busca en el momento (sin temporizador: un re-render lo cancelaría).\n    doSearch(term);\n  }, [qParam, doSearch]);\n\n  const onPickTerm = (term: string) => {\n    setQuery(term);\n    doSearch(term);\n  };\n\n  /* ── Masonry: mismo reparto por altura que el feed ── */\n  const { leftCol, rightCol } = useMemo(() => {\n    const left: LbPostCard[] = [];\n    const right: LbPostCard[] = [];\n    let hL = 0;\n    let hR = 0;\n    for (const p of results) {\n      const imgH = COLUMN_W / (p.media?.aspectRatio ?? LB_CARD_DEFAULT_RATIO);\n      const totalH = imgH + 60;\n      if (hL <= hR) { left.push(p); hL += totalH; } else { right.push(p); hR += totalH; }\n    }\n    return { leftCol: left, rightCol: right };\n  }, [results]);\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      {/* ═══════ BARRA DE BÚSQUEDA ═══════ */}\n      <View style={[styles.searchBar, { borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ padding: espaciado.e4 }} accessibilityLabel=\"Cerrar búsqueda\">\n          <X size={20} color={colors.textSecondary} />\n        </Pressable>\n\n        <View style={[styles.inputWrap, { backgroundColor: alpha(colors.textSecondary, 0.07) }]}>\n          <Search size={15} color={colors.textSecondary} />\n          <TextInput\n            ref={inputRef}\n            value={query}\n            onChangeText={onQueryChange}\n            onSubmitEditing={() => doSearch(query)}\n            placeholder=\"Buscar personas, temas, productos…\"\n            placeholderTextColor={colors.textSecondary}\n            returnKeyType=\"search\"\n            style={[styles.input, { color: colors.textPrimary }]}\n            autoFocus\n            clearButtonMode=\"never\"\n          />\n          {query.length > 0 && (\n            <Pressable\n              onPress={() => { setQuery(''); setResults([]); setHasSearched(false); setSuggestions([]); }}\n              hitSlop={8}\n              accessibilityLabel=\"Borrar texto\"\n            >\n              <X size={15} color={colors.textSecondary} />\n            </Pressable>\n          )}\n        </View>\n\n        <Pressable onPress={() => doSearch(query)} hitSlop={8} accessibilityRole=\"button\">\n          <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>\n            Buscar\n          </Text>\n        </Pressable>\n      </View>\n\n      {/* ═══════ SUGERENCIAS ═══════ */}\n      {showSuggestions && suggestions.length > 0 && !hasSearched && (\n        <View style={[styles.suggestList, { backgroundColor: colors.background }]}>\n          {suggestions.map((s, i) => (\n            <Pressable\n              key={`${s.text}-${i}`}\n              onPress={() => onPickTerm(s.text)}\n              style={({ pressed }) => ({\n                flexDirection: 'row',\n                alignItems: 'center',\n                gap: espaciado.e10,\n                paddingVertical: espaciado.e12,\n                paddingHorizontal: espaciado.e16,\n                backgroundColor: pressed ? alpha(colors.textSecondary, 0.05) : 'transparent',\n              })}\n            >\n              {s.type === 'tag' ? (\n                <Hash size={15} color={colors.primary} />\n              ) : s.type === 'user' ? (\n                <UserIcon size={15} color={colors.textSecondary} />\n              ) : (\n                <Search size={15} color={colors.textSecondary} />\n              )}\n              <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, flex: 1 }} numberOfLines={1}>{s.text}</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>\n                {s.type === 'tag' ? 'tema' : s.type === 'user' ? 'persona' : 'buscar'}\n              </Text>\n            </Pressable>\n          ))}\n        </View>\n      )}\n\n      {/* ═══════ RESULTADOS ═══════ */}\n      {hasSearched ? (\n        <View style={{ flex: 1 }}>\n          {/* Filtros */}\n          <FlatList\n            horizontal\n            showsHorizontalScrollIndicator={false}\n            data={SEARCH_FILTERS}\n            keyExtractor={(f) => f.id}\n            style={{ flexGrow: 0 }}\n            contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e6, paddingVertical: espaciado.e8 }}\n            renderItem={({ item }) => {\n              const active = item.id === filter;\n              return (\n                <Pressable\n                  onPress={() => onFilterChange(item.id)}\n                  accessibilityRole=\"tab\"\n                  accessibilityState={{ selected: active }}\n                  style={[\n                    styles.filterChip,\n                    { backgroundColor: active ? colors.primary : alpha(colors.textSecondary, 0.06) },\n                  ]}\n                >\n                  <Text\n                    style={{\n                      color: active ? brand.white : colors.textPrimary,\n                      fontSize: tipografia.caption,\n                      fontWeight: active ? '800' : '600',\n                    }}\n                  >\n                    {item.label}\n                  </Text>\n                </Pressable>\n              );\n            }}\n          />\n\n          {loading ? (\n            <View style={styles.center}>\n              <ActivityIndicator color={colors.primary} />\n            </View>\n          ) : results.length === 0 ? (\n            /* Vacío del kit. Es una búsqueda sin resultados: se dice qué se buscó y qué hacer. */\n            <EmptyState\n              compacto\n              icono={<Search size={36} color={colors.textSecondary} />}\n              titulo=\"Sin resultados\"\n              texto={`No encontramos contenido para \"${query}\". Intenta con otra palabra.`}\n            />\n          ) : (\n            <FlatList\n              data={[{ left: leftCol, right: rightCol }]}\n              keyExtractor={() => 'search-masonry'}\n              renderItem={({ item }) => (\n                <View style={styles.masonryRow}>\n                  <View style={styles.masonryCol}>\n                    {item.left.map((post) => (\n                      <PostCard\n                        key={post.id}\n                        post={post}\n                        width={COLUMN_W}\n                        onPress={(id) => router.push({ pathname: '/lifebook-post/[id]', params: { id } })}\n                        onMore={setMorePost}\n                      />\n                    ))}\n                  </View>\n                  <View style={styles.masonryCol}>\n                    {item.right.map((post) => (\n                      <PostCard\n                        key={post.id}\n                        post={post}\n                        width={COLUMN_W}\n                        onPress={(id) => router.push({ pathname: '/lifebook-post/[id]', params: { id } })}\n                        onMore={setMorePost}\n                      />\n                    ))}\n                  </View>\n                </View>\n              )}\n              contentContainerStyle={{ paddingBottom: insets.bottom + 40, flexGrow: 1 }}\n              showsVerticalScrollIndicator={false}\n              onEndReached={() => { if (nextCursor && !loadingMore) doSearch(query, false); }}\n              onEndReachedThreshold={0.5}\n              ListFooterComponent={\n                loadingMore ? <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e16 }} /> : null\n              }\n            />\n          )}\n        </View>\n      ) : (\n        /* ═══════ PANTALLA VACÍA: Historial + Tendencias + Descubre ═══════\n           `keyboardShouldPersistTaps=\"always\"`: con el teclado abierto (el\n           buscador tiene auto-focus), el primer toque debe llegar a los botones\n           —historial, tendencias, tags y «Explorar todo»— en vez de solo\n           cerrar el teclado. */\n        <ScrollView\n          style={{ flex: 1 }}\n          contentContainerStyle={{ paddingBottom: insets.bottom + 30 }}\n          showsVerticalScrollIndicator={false}\n          keyboardShouldPersistTaps=\"always\"\n        >\n          {/* Historial */}\n          {history.length > 0 && (\n            <View style={styles.section}>\n              <View style={styles.sectionHeader}>\n                <Text style={[styles.sectionTitle, { color: colors.textPrimary }]}>Recientes</Text>\n                <Pressable onPress={clearHistory} hitSlop={8}>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>Limpiar</Text>\n                </Pressable>\n              </View>\n              <View style={styles.tagsWrap}>\n                {history.map((h) => (\n                  <Pressable\n                    key={h}\n                    onPress={() => onPickTerm(h)}\n                    style={[styles.historyTag, { backgroundColor: alpha(colors.textSecondary, 0.06) }]}\n                  >\n                    <Clock size={12} color={colors.textSecondary} />\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption }}>{h}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            </View>\n          )}\n\n          {/* Tendencias */}\n          <View style={styles.section}>\n            <View style={styles.sectionHeader}>\n              <Flame size={16} color={brand.like} />\n              <Text style={[styles.sectionTitle, { color: colors.textPrimary }]}>\n                Tendencias en {city}\n              </Text>\n            </View>\n            {trends.length === 0 ? (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, paddingHorizontal: espaciado.e2 }}>\n                Todavía no hay tendencias en tu ciudad.\n              </Text>\n            ) : (\n              trends.map((t, i) => (\n                <Pressable\n                  key={`${t.tag}-${i}`}\n                  onPress={() => onPickTerm(t.tag)}\n                  style={({ pressed }) => ({\n                    flexDirection: 'row',\n                    alignItems: 'center',\n                    gap: espaciado.e10,\n                    paddingVertical: espaciado.e11,\n                    opacity: pressed ? 0.7 : 1,\n                  })}\n                >\n                  <Text\n                    style={{\n                      fontSize: 15,\n                      fontWeight: '900',\n                      color: i < 3 ? brand.like : colors.textSecondary,\n                      width: 20,\n                      textAlign: 'center',\n                    }}\n                  >\n                    {i + 1}\n                  </Text>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '600', flex: 1 }} numberOfLines={1}>\n                    {t.tag}\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>\n                    {formatCount(t.count)}\n                  </Text>\n                  {t.hot ? <Flame size={13} color={brand.secondary} /> : null}\n                </Pressable>\n              ))\n            )}\n          </View>\n\n          {/* Categorías sugeridas + entrada a Explorar */}\n          <View style={styles.section}>\n            <View style={styles.sectionHeader}>\n              <TrendingUp size={16} color={colors.primary} />\n              <Text style={[styles.sectionTitle, { color: colors.textPrimary }]}>Descubre</Text>\n              <Pressable onPress={() => irSeguro.libre('/lifebook-explore')} hitSlop={8} accessibilityRole=\"link\">\n                <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800' }}>Explorar todo →</Text>\n              </Pressable>\n            </View>\n            <View style={styles.tagsWrap}>\n              {DISCOVER_TAGS.map((tag) => (\n                <Pressable\n                  key={tag}\n                  onPress={() => onPickTerm(tag)}\n                  style={[styles.discoverTag, { backgroundColor: alpha(colors.primary, 0.06) }]}\n                >\n                  <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '600' }}>{tag}</Text>\n                </Pressable>\n              ))}\n            </View>\n          </View>\n\n          <View style={styles.section}>\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n              <MapPin size={13} color={colors.textSecondary} />\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                Buscando en {city} · se muestran solo publicaciones públicas\n              </Text>\n            </View>\n          </View>\n        </ScrollView>\n      )}\n\n      {/* ═══════ MODAL: Reportar (⋯ de tarjeta) ═══════ */}\n      <ReportSheet\n        post={morePost}\n        onClose={() => setMorePost(null)}\n        onReport={async (postId, reason) => {\n          try {\n            await lifebookActionsApi.report(postId, 'post', reason);\n            Alert.alert('Gracias', 'Tu reporte fue enviado. El equipo lo revisará.');\n          } catch (e) {\n            Alert.alert('Reportar', e instanceof Error ? e.message : 'No se pudo enviar el reporte.');\n          }\n        }}\n        onBlocked={() => { if (query.trim()) doSearch(query, true); }}\n      />\n    </View>\n  );\n}\n\nfunction formatCount(n: number): string {\n  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;\n  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;\n  return String(n);\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  searchBar: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e8,\n    paddingHorizontal: espaciado.e12,\n    paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  inputWrap: {\n    flex: 1,\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e8,\n    borderRadius: 20,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e8,\n  },\n  input: { flex: 1, fontSize: tipografia.body, paddingVertical: 0 },\n  suggestList: {\n    position: 'absolute',\n    top: 56,\n    left: 0,\n    right: 0,\n    bottom: 0,\n    zIndex: 10,\n    elevation: 10,\n  },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', paddingBottom: 60 },\n  filterChip: {\n    borderRadius: radios.full,\n    paddingHorizontal: espaciado.e14,\n    paddingVertical: espaciado.e7,\n  },\n  masonryRow: {\n    flexDirection: 'row',\n    paddingHorizontal: SIDE_PADDING,\n    gap: COLUMN_GAP,\n    paddingTop: espaciado.e4,\n  },\n  masonryCol: { flex: 1, gap: COLUMN_GAP },\n  section: { paddingHorizontal: espaciado.e16, marginTop: espaciado.e20 },\n  sectionHeader: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    gap: espaciado.e6,\n    marginBottom: espaciado.e10,\n  },\n  sectionTitle: { fontSize: tipografia.subtitle, fontWeight: '800' },\n  tagsWrap: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  historyTag: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: espaciado.e5,\n    borderRadius: radios.full,\n    paddingHorizontal: espaciado.e12,\n    paddingVertical: espaciado.e7,\n  },\n  discoverTag: {\n    borderRadius: radios.full,\n    paddingHorizontal: espaciado.e14,\n    paddingVertical: espaciado.e8,\n  },\n});\n","/**\n * app/lifebook-sell.tsx — ASISTENTE DE PUBLICACIÓN (Parte 34).\n *\n * Sustituye al formulario largo por el asistente por pasos que propuso el dueño,\n * con su estructura (una pantalla + un componente por paso), su vista previa y su\n * estado en zustand — y con los arreglos detectados en la evaluación:\n *   · paso 0 «abrir mi tienda» (sin tienda no se puede publicar);\n *   · paso de categoría (antes no se recogía en ningún sitio);\n *   · precio a consultar y precio anterior vacío que ya no rompen la publicación;\n *   · entrega y pagos guardados de verdad (antes se perdían en estado local);\n *   · clave de idempotencia ESTABLE por intento (un doble toque no duplica).\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, espaciado, GhostButton, PrimaryButton, StepHeader, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Store } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { commerceApi, type LbCategory, type LbShop } from '../api/commerce';\nimport { chartsFromApi, chartsToPayload, formToPayload, groupsFromApi, stepsFor, usePublishStore, validateStep } from '../state/commercePublish';\nimport StepShop from '../components/lifebook/publish/StepShop';\nimport StepType from '../components/lifebook/publish/StepType';\nimport StepMedia from '../components/lifebook/publish/StepMedia';\nimport StepDetails from '../components/lifebook/publish/StepDetails';\nimport StepExtras from '../components/lifebook/publish/StepExtras';\nimport StepPreview from '../components/lifebook/publish/StepPreview';\nimport { Notice } from '../components/lifebook/publish/PublishParts';\nimport { ir as irSeguro } from '../constants/rutas';\n\nconst STEP_LABEL: Record<string, string> = {\n  shop: 'Tu tienda',\n  type: 'Tipo y categoría',\n  media: 'Fotos y vídeo',\n  details: 'Datos y precio',\n  extras: 'Detalles, opciones y entrega',\n  preview: 'Vista previa',\n};\n\nexport default function LifeBookSellScreen() {\n  return (\n    <AuthGate>\n      <SellContent />\n    </AuthGate>\n  );\n}\n\nfunction SellContent() {\n  const { editId } = useLocalSearchParams<{ editId?: string }>();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const form = usePublishStore((s) => s.form);\n  const step = usePublishStore((s) => s.step);\n  const hasShop = usePublishStore((s) => s.hasShop);\n  const shopName = usePublishStore((s) => s.shopName);\n  const submitting = usePublishStore((s) => s.submitting);\n  const error = usePublishStore((s) => s.error);\n  const setStep = usePublishStore((s) => s.setStep);\n  const setHasShop = usePublishStore((s) => s.setHasShop);\n  const replaceForm = usePublishStore((s) => s.replaceForm);\n  const setError = usePublishStore((s) => s.setError);\n  const setSubmitting = usePublishStore((s) => s.setSubmitting);\n  const ensureIdemKey = usePublishStore((s) => s.ensureIdemKey);\n  const clearIdemKey = usePublishStore((s) => s.clearIdemKey);\n\n  const [loading, setLoading] = useState(true);\n  const [categories, setCategories] = useState<LbCategory[]>([]);\n  const [shop, setShop] = useState<LbShop | null>(null);\n  const mounted = useRef(true);\n\n  /** Carga inicial: categorías + mi tienda (+ producto si estoy editando). */\n  useEffect(() => {\n    mounted.current = true;\n    (async () => {\n      try {\n        const [cats, mine] = await Promise.all([\n          commerceApi.categories().catch(() => ({ categories: [] as LbCategory[] })),\n          commerceApi.myShop().catch(() => ({ shop: null })),\n        ]);\n        if (!mounted.current) return;\n        setCategories(cats.categories ?? []);\n        setShop(mine.shop);\n        setHasShop(!!mine.shop, mine.shop?.name ?? null);\n\n        if (editId) {\n          const { product } = await commerceApi.product(String(editId));\n          if (!mounted.current) return;\n          // TANDA J/K: las tablas de tallas viven en su propia ruta (se guardan aparte) y los ejes\n          // de opciones vienen con la ficha. Si la lectura de la tabla falla, la pantalla sigue:\n          // solo se pierde poder editarla, no el resto del formulario.\n          const tablas = await commerceApi.sizeChart(String(editId)).catch(() => ({ charts: [] }));\n          if (!mounted.current) return;\n          replaceForm({\n            serviceType: product.serviceType,\n            categoryId: product.categoryId,\n            title: product.title,\n            shortDescription: product.shortDescription ?? '',\n            longDescription: product.longDescription ?? '',\n            priceMode: product.priceMode,\n            price: product.priceXaf !== null ? String(product.priceXaf) : '',\n            oldPrice: product.oldPriceXaf !== null ? String(product.oldPriceXaf) : '',\n            stockMode: product.stockMode,\n            stockQuantity: String(product.stockQuantity ?? 0),\n            condition: product.condition,\n            city: product.originCity ?? mine.shop?.city ?? 'Malabo',\n            barrio: product.originBarrio ?? '',\n            tags: (product.tags ?? []).join(', '),\n            coverage: product.shippingPolicy?.coverage ?? ['same_city'],\n            transports: product.shippingPolicy?.transportModes ?? ['local_courier', 'pickup'],\n            deliveryCost: product.shippingPolicy?.baseCostXaf ? String(product.shippingPolicy.baseCostXaf) : '',\n            media: (product.media ?? []).map((m) => ({ url: m.url, type: (m.type === 'video' ? 'video' : 'image') as 'image' | 'video' })),\n            variants: (product.variants ?? []).map((v) => ({\n              name: v.name,\n              priceXaf: v.priceXaf !== null && v.priceXaf !== undefined ? String(v.priceXaf) : '',\n              stockQuantity: String(v.stockQuantity ?? ''),\n              attributes: Object.fromEntries(\n                Object.entries(v.attributes ?? {}).map(([k, val]) => [k, String(val)]),\n              ),\n            })),\n            optionGroups: groupsFromApi(product.options),\n            sizeCharts: chartsFromApi(tablas.charts),\n            attributes: product.attributes ?? [],\n          });\n        }\n      } finally {\n        if (mounted.current) setLoading(false);\n      }\n    })();\n    return () => { mounted.current = false; };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [editId]);\n\n  const pasos = useMemo(() => stepsFor(form.serviceType, hasShop || !!editId), [form.serviceType, hasShop, editId]);\n  const idx = Math.max(0, pasos.indexOf(step));\n  const esUltimo = idx === pasos.length - 1;\n\n  const avanzar = useCallback(() => {\n    const problema = validateStep(step, form);\n    if (problema) { setError(problema); return; }\n    const siguiente = pasos[Math.min(idx + 1, pasos.length - 1)];\n    if (siguiente) setStep(siguiente);\n  }, [step, form, pasos, idx, setStep, setError]);\n\n  const atras = useCallback(() => {\n    if (idx === 0) { router.back(); return; }\n    const anterior = pasos[Math.max(idx - 1, 0)];\n    if (anterior) setStep(anterior);\n  }, [idx, pasos, router, setStep]);\n\n  /** Guarda la entrega en la tienda (es de la tienda, no del producto) y publica. */\n  const publicar = useCallback(async () => {\n    const problema = validateStep('details', form);\n    if (problema) { setError(problema); setStep('details'); return; }\n    setSubmitting(true);\n    setError(null);\n    try {\n      const coste = Number(form.deliveryCost.replace(/\\D/g, '')) || 0;\n      let shippingPolicyId: string | null = null;\n      if (shop) {\n        const { shop: actualizada } = await commerceApi.updateShop({\n          shippingPolicy: {\n            name: 'Entrega de la tienda',\n            coverage: form.coverage.length ? form.coverage : ['same_city'],\n            transportModes: form.transports.length ? form.transports : ['pickup'],\n            costMode: coste > 0 ? 'fixed' : 'on_request',\n            baseCostXaf: coste,\n            estimatedTime: '2-4 h',\n            shipsInternational: form.coverage.includes('international'),\n            internationalNote: form.coverage.includes('international') ? 'Coste del envío internacional a consultar con la tienda' : undefined,\n          },\n        });\n        shippingPolicyId = actualizada.shippingPolicies?.[0]?.id ?? null;\n      }\n\n      const payload = { ...formToPayload(form), shippingPolicyId };\n      /**\n       * TANDA J/K — LAS TABLAS DE TALLAS.\n       *\n       * Van por su propia ruta (`PUT products/:id/size-chart`) porque necesitan el id del producto,\n       * que solo existe después de publicar. Si fallan, se DICE: publicar sin la tabla que el\n       * comerciante acaba de escribir sería perder su trabajo en silencio (y el asistente de talla\n       * recomendaría con datos que no están).\n       */\n      const tablas = chartsToPayload(form.sizeCharts);\n      const guardarTablas = async (productId: string) => {\n        if (!tablas.length) return true;\n        try {\n          await commerceApi.setSizeChart(productId, tablas);\n          return true;\n        } catch (e) {\n          Alert.alert(\n            'Tabla de tallas',\n            `La publicación se guardó, pero la tabla de tallas no: ${e instanceof Error ? e.message : 'error de red'}. Vuelve a entrar en «Editar» y guárdala otra vez.`,\n          );\n          return false;\n        }\n      };\n      if (editId) {\n        await commerceApi.updateProduct(String(editId), payload as never);\n        await guardarTablas(String(editId));\n        Alert.alert('Guardado', 'Tu publicación vuelve a revisión antes de mostrarse.');\n        irSeguro.libre('/lifebook-product/[id]', { id: String(editId) }, true);\n      } else {\n        const clave = ensureIdemKey();\n        const { product } = await commerceApi.createProduct(payload as never, clave);\n        clearIdemKey();\n        await guardarTablas(product.id);\n        irSeguro.libre('/lifebook-product/[id]', { id: product.id }, true);\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo publicar. Inténtalo de nuevo.');\n    } finally {\n      setSubmitting(false);\n    }\n  }, [form, shop, editId, ensureIdemKey, clearIdemKey, router, setError, setStep, setSubmitting]);\n\n  if (loading) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <KeyboardAvoidingView\n      style={{ flex: 1, backgroundColor: colors.background }}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      {/* Cabecera propia: el Stack raíz va sin cabecera nativa */}\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={atras} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle, flex: 1, marginLeft: espaciado.e10 }}>\n          {editId ? 'Editar publicación' : 'Publicar en mi tienda'}\n        </Text>\n        {shopName ? (\n          <Pressable\n            onPress={() => irSeguro.libre('/lifebook-merchant')}\n            hitSlop={8}\n            accessibilityLabel=\"Ir al panel de mi tienda\"\n            style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}\n          >\n            <Store size={13} color={colors.primary} />\n            <Text numberOfLines={1} style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '800', maxWidth: 120 }}>{shopName}</Text>\n          </Pressable>\n        ) : null}\n      </View>\n\n      <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e24 }} keyboardShouldPersistTaps=\"handled\">\n        <StepHeader\n          step={idx + 1}\n          total={pasos.length}\n          title={STEP_LABEL[step] ?? 'Publicar'}\n          subtitle={step === 'preview' ? 'Revisa antes de publicar: entrará en moderación.' : undefined}\n        />\n\n        <View style={{ height: 14 }} />\n\n        {error ? <Notice tone=\"error\">{error}</Notice> : null}\n\n        {step === 'shop' ? (\n          <StepShop onCreated={(name) => { setHasShop(true, name); setStep('type'); }} />\n        ) : null}\n        {step === 'type' ? <StepType categories={categories} /> : null}\n        {step === 'media' ? <StepMedia /> : null}\n        {step === 'details' ? <StepDetails /> : null}\n        {step === 'extras' ? <StepExtras categories={categories} /> : null}\n        {step === 'preview' ? <StepPreview categories={categories} shop={shop} /> : null}\n      </ScrollView>\n\n      {/* Pie: atrás / continuar / publicar */}\n      <View style={[styles.footer, { paddingBottom: insets.bottom + 10, borderTopColor: alpha(colors.border, 0.5), backgroundColor: colors.background }]}>\n        <GhostButton title={idx === 0 ? 'Cancelar' : 'Atrás'} onPress={atras} />\n        <View style={{ flex: 1 }}>\n          {esUltimo ? (\n            <PrimaryButton\n              title={editId ? 'Guardar cambios' : 'Publicar'}\n              loading={submitting}\n              onPress={publicar}\n            />\n          ) : (\n            <PrimaryButton title=\"Continuar\" onPress={avanzar} />\n          )}\n        </View>\n      </View>\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  footer: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10, borderTopWidth: StyleSheet.hairlineWidth,\n  },\n});\n","/**\n * state/commercePublish.ts — estado del ASISTENTE de publicación (Parte 34 · tanda K).\n *\n * Integra la idea del dueño (zustand + asistente por pasos) con las correcciones\n * detectadas al evaluar su código, para no arrastrar errores:\n *   · fábrica de estado inicial (antes `reset()` compartía el objeto y los arrays)\n *   · fotos por `url` (antes por `position`, que se duplicaba y borraba de más);\n *     la posición la asigna el servidor por el orden del array\n *   · variantes y detalles **sin duplicados** (el servidor rechaza repetidos con 400)\n *   · **clave de idempotencia estable** por intento (antes llevaba `Date.now()` y no\n *     protegía de un doble toque: cada envío parecía nuevo)\n *   · pasos **según el tipo** de publicación y validación por paso\n *\n * TANDA K — «ELEGIR ANTES DE COMPRAR». Lo que se añade aquí es el modelo que faltaba: los EJES de\n * elección (Color con la foto real de cada color, Talla, Almacenamiento, Formato…) y sus\n * COMBINACIONES con precio y stock. Sin ejes, la ficha solo podía enseñar el `name` de la variante\n * («Talla 42») y los botones Comprar/Añadir al carrito compraban directo con la primera. Las\n * combinaciones **no se escriben a mano**: se generan del producto cartesiano de los ejes (como en\n * Taobao o Shopify) y el comerciante solo pone precio y stock, conservando lo que ya había escrito.\n */\nimport * as Crypto from 'expo-crypto';\nimport { create } from 'zustand';\nimport type {\n  LbCondition, LbOptionGroup, LbServiceType, LbSizeChart, LbSizeGender, LbSizeKind, LbSizeRow,\n} from '../api/commerce';\n/**\n * Los topes, la firma y el cartesiano viven en `utils/combinaciones.ts` (compartidos con el editor\n * del Mercado) y se re-exportan más abajo para que ningún punto de llamada cambie. Ver el porqué,\n * entero, donde estaban escritos.\n */\nimport { COMBOS_MAX, GRUPOS_MAX, combinacionesDe, firmaDe } from '../utils/combinaciones';\n\nexport type PublishStep = 'shop' | 'type' | 'media' | 'details' | 'extras' | 'preview';\n\nexport interface PublishMedia { url: string; type: 'image' | 'video' }\nexport interface PublishVariant {\n  name: string;\n  priceXaf: string;\n  stockQuantity: string;\n  /** La combinación: `{ color: 'Rojo', talla: 'M' }`. Es lo que ata la variante a los ejes. */\n  attributes: Record<string, string>;\n}\nexport interface PublishAttribute { key: string; value: string }\n\n/** Un valor de un eje. En los ejes de color, `imageUrl` es la foto REAL del producto en ese color. */\nexport interface PublishOptionValue { value: string; imageUrl: string }\nexport interface PublishOptionGroup {\n  code: string;\n  label: string;\n  kind: 'color' | 'size' | 'text';\n  /** Solo en los ejes de talla: contra qué tabla se recomienda. */\n  chartKind?: LbSizeKind | null;\n  values: PublishOptionValue[];\n}\n\n/** Una talla de la tabla, con los campos tal y como se escriben (texto; el servidor valida). */\nexport type PublishSizeRow = { sizeLabel: string } & Record<string, string | undefined>;\nexport interface PublishSizeChartDraft {\n  gender: LbSizeGender;\n  kind: LbSizeKind;\n  notes: string;\n  rows: PublishSizeRow[];\n}\n\nexport interface PublishForm {\n  serviceType: LbServiceType;\n  categoryId: string | null;\n  title: string;\n  shortDescription: string;\n  longDescription: string;\n  priceMode: 'fixed' | 'from' | 'on_request';\n  price: string;\n  oldPrice: string;\n  stockMode: 'exact' | 'approximate' | 'on_request' | 'unlimited';\n  stockQuantity: string;\n  condition: LbCondition;\n  city: string;\n  barrio: string;\n  tags: string;\n  /** Entrega: política de la tienda que se creará/actualizará al publicar. */\n  delivers: boolean;\n  deliveryCost: string;\n  coverage: string[];\n  transports: string[];\n  media: PublishMedia[];\n  variants: PublishVariant[];\n  /** Tanda K: los ejes de elección y las tablas de tallas que configura el comerciante. */\n  optionGroups: PublishOptionGroup[];\n  sizeCharts: PublishSizeChartDraft[];\n  attributes: PublishAttribute[];\n}\n\n/** Estado inicial SIEMPRE nuevo (evita compartir arrays entre borradores). */\nexport const createEmptyForm = (serviceType: LbServiceType = 'physical', city = 'Malabo'): PublishForm => ({\n  serviceType,\n  categoryId: null,\n  title: '',\n  shortDescription: '',\n  longDescription: '',\n  priceMode: 'fixed',\n  price: '',\n  oldPrice: '',\n  stockMode: 'exact',\n  stockQuantity: '1',\n  condition: 'new',\n  city,\n  barrio: '',\n  tags: '',\n  delivers: true,\n  deliveryCost: '',\n  coverage: ['same_city'],\n  transports: ['local_courier', 'pickup'],\n  media: [],\n  variants: [],\n  optionGroups: [],\n  sizeCharts: [],\n  attributes: [],\n});\n\n/** Los pasos dependen del tipo: a un oficio no se le piden variantes. */\nexport function stepsFor(serviceType: LbServiceType, hasShop: boolean): PublishStep[] {\n  const base: PublishStep[] = hasShop ? [] : ['shop'];\n  base.push('type', 'media', 'details');\n  if (serviceType === 'physical' || serviceType === 'food') base.push('extras');\n  else base.push('extras'); // extras = detalles + entrega, aplica a todos\n  base.push('preview');\n  return base;\n}\n\nconst money = (v: string): number => Number(String(v).replace(/[^\\d]/g, '')) || 0;\n\n/**\n * LOS TOPES, LA FIRMA Y EL CARTESIANO SE MUDARON A `utils/combinaciones.ts` (21-sep-2026).\n *\n * Aquí estaban escritos una sola vez, y esa era su virtud: no había dos versiones. El problema\n * apareció con la pantalla de combinaciones del **Mercado**, que necesita exactamente lo mismo —los\n * topes del servidor y el producto cartesiano— y no puede sacarlo de este fichero sin arrastrar el\n * asistente de Life Book entero. Copiarlos allí habría creado la segunda versión, que es justo de\n * donde salen las divergencias silenciosas.\n *\n * Se **importan** (para seguir usándolos aquí dentro) y se **re-exportan** (para que\n * `OptionGroupsEditor` y esta tienda sigan importando de donde importaban, sin tocar ni un punto de\n * llamada). Es el mismo movimiento que hizo el servidor al extraer `services/opciones-producto.ts`.\n */\nexport { COMBOS_MAX, GRUPOS_MAX, combinacionesDe, firmaDe };\n\nexport const formToPayload = (f: PublishForm) => {\n  const grupos = f.optionGroups.filter((g) => g.values.length > 0);\n  return {\n    serviceType: f.serviceType,\n    categoryId: f.categoryId,\n    title: f.title.trim(),\n    shortDescription: f.shortDescription.trim() || null,\n    longDescription: f.longDescription.trim() || null,\n    priceMode: f.priceMode,\n    priceXaf: f.priceMode === 'on_request' ? null : money(f.price),\n    // 0 o vacío = sin descuento (el servidor también lo tolera desde la Parte 34)\n    oldPriceXaf: money(f.oldPrice) > 0 ? money(f.oldPrice) : null,\n    stockMode: f.stockMode,\n    stockQuantity: f.stockMode === 'exact' || f.stockMode === 'approximate' ? money(f.stockQuantity) : 0,\n    condition: f.condition,\n    originCity: f.city,\n    originBarrio: f.barrio.trim() || undefined,\n    shipsInternational: f.coverage.includes('international'),\n    media: f.media.map((m) => ({ url: m.url, type: m.type })),\n    tags: f.tags.split(',').map((t) => t.trim()).filter(Boolean).slice(0, 6),\n    /**\n     * Tanda K: los ejes con la foto de cada color. Se mandan SIEMPRE (aunque vayan vacíos) para que\n     * quitar un eje al editar se guarde de verdad.\n     */\n    options: f.optionGroups.map((g) => ({\n      code: g.code,\n      label: g.label,\n      kind: g.kind,\n      chartKind: g.kind === 'size' ? (g.chartKind ?? null) : null,\n      values: g.values.map((v) => ({\n        value: v.value,\n        // La foto la exige el servidor en los ejes de color; en los demás es opcional.\n        imageUrl: v.imageUrl || null,\n      })),\n    })),\n    variants: f.variants\n      .filter((v) => v.name.trim())\n      .map((v) => ({\n        name: v.name.trim(),\n        priceXaf: money(v.priceXaf) > 0 ? money(v.priceXaf) : null,\n        // Sin dato ≠ 0: el stock vacío se hereda del producto en vez de marcar «agotada»\n        stockQuantity: v.stockQuantity.trim() === '' ? money(f.stockQuantity) : money(v.stockQuantity),\n        ...(grupos.length ? { attributes: v.attributes } : {}),\n      })),\n    attributes: f.attributes.filter((a) => a.key.trim() && a.value.trim()),\n  };\n};\n\n/** Las tablas de tallas tal y como las espera el servidor (los vacíos van como null). */\nexport const chartsToPayload = (charts: PublishSizeChartDraft[]): LbSizeChart[] => charts\n  .filter((c) => c.rows.some((r) => r.sizeLabel?.trim()))\n  .map((c) => ({\n    gender: c.gender,\n    kind: c.kind,\n    notes: c.notes.trim() || null,\n    rows: c.rows\n      .filter((r) => r.sizeLabel?.trim())\n      .map((r): LbSizeRow => {\n        const n = (v?: string): number | null => {\n          const t = String(v ?? '').replace(/[^\\d]/g, '');\n          return t === '' ? null : Number(t);\n        };\n        return {\n          sizeLabel: r.sizeLabel.trim().slice(0, 20),\n          chestMinCm: n(r.chestMinCm), chestMaxCm: n(r.chestMaxCm),\n          waistMinCm: n(r.waistMinCm), waistMaxCm: n(r.waistMaxCm),\n          hipMinCm: n(r.hipMinCm), hipMaxCm: n(r.hipMaxCm),\n          heightMinCm: n(r.heightMinCm), heightMaxCm: n(r.heightMaxCm),\n          weightMinKg: n(r.weightMinKg), weightMaxKg: n(r.weightMaxKg),\n          footLengthMinCm: n(r.footLengthMinCm), footLengthMaxCm: n(r.footLengthMaxCm),\n          footWidthMinCm: n(r.footWidthMinCm), footWidthMaxCm: n(r.footWidthMaxCm),\n        };\n      }),\n  }));\n\n/** Los ejes que llegan del servidor, al borrador de la app. */\nexport const groupsFromApi = (options: LbOptionGroup[] | undefined): PublishOptionGroup[] =>\n  (options ?? []).map((g) => ({\n    code: g.code,\n    label: g.label,\n    kind: g.kind,\n    chartKind: g.chartKind ?? null,\n    values: (g.values ?? []).map((v) => ({ value: v.value, imageUrl: v.imageUrl ?? '' })),\n  }));\n\n/** Las tablas que llegan del servidor, al borrador de la app. */\nexport const chartsFromApi = (charts: LbSizeChart[] | undefined): PublishSizeChartDraft[] =>\n  (charts ?? []).map((c) => ({\n    gender: c.gender,\n    kind: c.kind,\n    notes: c.notes ?? '',\n    rows: (c.rows ?? []).map((r) => ({\n      sizeLabel: r.sizeLabel,\n      chestMinCm: r.chestMinCm != null ? String(r.chestMinCm) : '',\n      chestMaxCm: r.chestMaxCm != null ? String(r.chestMaxCm) : '',\n      waistMinCm: r.waistMinCm != null ? String(r.waistMinCm) : '',\n      waistMaxCm: r.waistMaxCm != null ? String(r.waistMaxCm) : '',\n      hipMinCm: r.hipMinCm != null ? String(r.hipMinCm) : '',\n      hipMaxCm: r.hipMaxCm != null ? String(r.hipMaxCm) : '',\n      heightMinCm: r.heightMinCm != null ? String(r.heightMinCm) : '',\n      heightMaxCm: r.heightMaxCm != null ? String(r.heightMaxCm) : '',\n      weightMinKg: r.weightMinKg != null ? String(r.weightMinKg) : '',\n      weightMaxKg: r.weightMaxKg != null ? String(r.weightMaxKg) : '',\n      footLengthMinCm: r.footLengthMinCm != null ? String(r.footLengthMinCm) : '',\n      footLengthMaxCm: r.footLengthMaxCm != null ? String(r.footLengthMaxCm) : '',\n      footWidthMinCm: r.footWidthMinCm != null ? String(r.footWidthMinCm) : '',\n      footWidthMaxCm: r.footWidthMaxCm != null ? String(r.footWidthMaxCm) : '',\n    })),\n  }));\n\n/** Validación por paso con mensajes claros (lo que el usuario ve). */\nexport function validateStep(step: PublishStep, f: PublishForm): string | null {\n  switch (step) {\n    case 'type':\n      if (!f.serviceType) return 'Elige qué tipo de publicación quieres crear';\n      return null;\n    case 'media':\n      // La foto solo es obligatoria en las ventas físicas\n      if (f.serviceType === 'physical' && f.media.length === 0) return 'Añade al menos una foto de lo que vendes';\n      return null;\n    case 'details': {\n      if (f.title.trim().length < 3) return 'El título necesita al menos 3 letras';\n      if (f.priceMode !== 'on_request' && money(f.price) <= 0) return 'Indica el precio o marca «A consultar»';\n      if (money(f.oldPrice) > 0 && money(f.oldPrice) <= money(f.price)) return 'El precio anterior debe ser mayor que el actual';\n      if (f.stockMode === 'exact' && money(f.stockQuantity) < 1) return 'Indica cuántas unidades tienes (o cambia la disponibilidad)';\n      const duplicado = f.variants.some((v, i) => v.name.trim() && f.variants.findIndex((x) => x.name.trim().toLowerCase() === v.name.trim().toLowerCase()) !== i);\n      if (duplicado) return 'Hay dos opciones con el mismo nombre';\n      const claveRepetida = f.attributes.some((a, i) => a.key.trim() && f.attributes.findIndex((x) => x.key.trim().toLowerCase() === a.key.trim().toLowerCase()) !== i);\n      if (claveRepetida) return 'Hay dos detalles con el mismo nombre';\n      // Tanda K: los ejes. Es lo que impide publicar un color sin su foto real o una combinación\n      // agotada que nadie puede comprar.\n      const grupos = f.optionGroups.filter((g) => g.values.length > 0);\n      if (f.optionGroups.some((g) => g.values.length === 0)) return 'Hay un eje de opciones sin ningún valor: ponle valores o quítalo';\n      if (grupos.length) {\n        const sinFoto = grupos.find((g) => g.kind === 'color' && g.values.some((v) => !v.imageUrl));\n        if (sinFoto) {\n          const cual = sinFoto.values.find((v) => !v.imageUrl)?.value ?? '';\n          return `El color «${cual}» necesita su foto real del producto en ese color: no vale solo el nombre`;\n        }\n        const combos = combinacionesDe(grupos);\n        if (combos.length > COMBOS_MAX) return `Con esos valores salen ${combos.length} combinaciones y el máximo es ${COMBOS_MAX}: quita algún color o alguna talla`;\n        if (f.variants.length !== combos.length) return 'Pulsa «Generar combinaciones» para poner el precio y el stock de cada combinación';\n        if (f.variants.some((v) => !v.attributes || Object.keys(v.attributes).length === 0)) return 'Cada combinación necesita sus valores (pulsa «Generar combinaciones»)';\n      }\n      return null;\n    }\n    default:\n      return null;\n  }\n}\n\ninterface PublishState {\n  form: PublishForm;\n  step: PublishStep;\n  hasShop: boolean;\n  shopName: string | null;\n  idemKey: string | null;\n  submitting: boolean;\n  error: string | null;\n  setForm: (patch: Partial<PublishForm>) => void;\n  /** Reemplaza el formulario (edición): acepta un parcial y rellena el resto. */\n  replaceForm: (patch: Partial<PublishForm>) => void;\n  setStep: (step: PublishStep) => void;\n  setHasShop: (has: boolean, name?: string | null) => void;\n  addMedia: (item: PublishMedia) => void;\n  removeMedia: (url: string) => void;\n  addVariant: (v: PublishVariant) => string | null;\n  removeVariant: (index: number) => void;\n  setVariant: (index: number, patch: Partial<PublishVariant>) => void;\n  /** Añade un eje (con sus valores sugeridos, sin foto: la foto la elige el comerciante). */\n  addOptionGroup: (g: PublishOptionGroup) => string | null;\n  removeOptionGroup: (code: string) => void;\n  setOptionGroup: (code: string, patch: Partial<Omit<PublishOptionGroup, 'code' | 'values'>>) => void;\n  addOptionValue: (code: string, value: string) => string | null;\n  removeOptionValue: (code: string, value: string) => void;\n  /** La foto REAL de un color: se elige entre las fotos que el comerciante ya subió. */\n  setOptionValuePhoto: (code: string, value: string, imageUrl: string) => void;\n  /** Genera las combinaciones del producto cartesiano conservando precios y stock ya escritos. */\n  generarCombinaciones: () => string | null;\n  setSizeChart: (chart: PublishSizeChartDraft) => void;\n  removeSizeChart: (gender: LbSizeGender, kind: LbSizeKind) => void;\n  setAttribute: (key: string, value: string) => void;\n  removeAttribute: (key: string) => void;\n  ensureIdemKey: () => string;\n  clearIdemKey: () => void;\n  setSubmitting: (v: boolean) => void;\n  setError: (e: string | null) => void;\n  reset: () => void;\n}\n\nexport const usePublishStore = create<PublishState>((set, get) => ({\n  form: createEmptyForm(),\n  step: 'type',\n  hasShop: false,\n  shopName: null,\n  idemKey: null,\n  submitting: false,\n  error: null,\n\n  setForm: (patch) => set((s) => ({ form: { ...s.form, ...patch }, error: null })),\n  replaceForm: (patch) => set({ form: { ...createEmptyForm(), ...patch }, error: null }),\n  setStep: (step) => set({ step, error: null }),\n  setHasShop: (hasShop, shopName = null) => set({ hasShop, shopName }),\n\n  addMedia: (item) => set((s) => (\n    s.form.media.some((m) => m.url === item.url)\n      ? s\n      : { form: { ...s.form, media: [...s.form.media, item].slice(0, 10) }, error: null }\n  )),\n  removeMedia: (url) => set((s) => ({ form: { ...s.form, media: s.form.media.filter((m) => m.url !== url) } })),\n\n  /** Devuelve el motivo si no se añade (nombre vacío o repetido). */\n  addVariant: (v) => {\n    const name = v.name.trim();\n    if (!name) return 'La opción necesita un nombre';\n    const cur = get().form.variants;\n    if (cur.some((x) => x.name.trim().toLowerCase() === name.toLowerCase())) return 'Ya tienes una opción con ese nombre';\n    if (cur.length >= COMBOS_MAX) return `Como máximo ${COMBOS_MAX} opciones`;\n    set((s) => ({ form: { ...s.form, variants: [...s.form.variants, { ...v, name }] }, error: null }));\n    return null;\n  },\n  removeVariant: (index) => set((s) => ({ form: { ...s.form, variants: s.form.variants.filter((_, i) => i !== index) } })),\n  setVariant: (index, patch) => set((s) => ({\n    form: {\n      ...s.form,\n      variants: s.form.variants.map((v, i) => (i === index ? { ...v, ...patch } : v)),\n    },\n  })),\n\n  // ── Tanda K: los ejes de elección ────────────────────────────────────────\n  addOptionGroup: (g) => {\n    const code = g.code.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_').slice(0, 30);\n    if (code.length < 2) return 'El eje necesita un nombre corto (por ejemplo «color» o «talla»)';\n    const cur = get().form.optionGroups;\n    if (cur.some((x) => x.code === code)) return `Ya tienes el eje «${g.label}»`;\n    if (cur.length >= GRUPOS_MAX) return `Como máximo ${GRUPOS_MAX} ejes (por ejemplo Color y Talla)`;\n    if (!g.values.length) return 'El eje necesita al menos un valor';\n    set((s) => ({\n      form: { ...s.form, optionGroups: [...s.form.optionGroups, { ...g, code, values: [...g.values] }] },\n      error: null,\n    }));\n    return null;\n  },\n  removeOptionGroup: (code) => set((s) => {\n    const grupos = s.form.optionGroups.filter((g) => g.code !== code);\n    return {\n      form: {\n        ...s.form,\n        optionGroups: grupos,\n        /**\n         * Las combinaciones que dependían de ese eje ya no valen: se les quita el valor de ese eje\n         * (y si no queda ningún eje, se quedan sin combinación, que es lo correcto: vuelven a ser\n         * opciones sueltas). Sin esto, el servidor rechazaría la publicación por mandar un eje que\n         * ya no existe.\n         */\n        variants: s.form.variants.map((v) => {\n          const attrs = { ...v.attributes };\n          delete attrs[code];\n          return { ...v, attributes: grupos.length ? attrs : {} };\n        }),\n      },\n    };\n  }),\n  setOptionGroup: (code, patch) => set((s) => ({\n    form: {\n      ...s.form,\n      optionGroups: s.form.optionGroups.map((g) => (g.code === code ? { ...g, ...patch } : g)),\n    },\n    error: null,\n  })),\n  addOptionValue: (code, value) => {\n    const v = value.trim().slice(0, 40);\n    if (!v) return 'El valor necesita un nombre';\n    const grupo = get().form.optionGroups.find((g) => g.code === code);\n    if (!grupo) return 'Ese eje no existe';\n    if (grupo.values.some((x) => x.value.toLowerCase() === v.toLowerCase())) return `«${v}» ya está en ${grupo.label}`;\n    if (grupo.values.length >= 30) return 'Como máximo 30 valores por eje';\n    set((s) => ({\n      form: {\n        ...s.form,\n        optionGroups: s.form.optionGroups.map((g) => (\n          g.code === code ? { ...g, values: [...g.values, { value: v, imageUrl: '' }] } : g\n        )),\n      },\n      error: null,\n    }));\n    return null;\n  },\n  removeOptionValue: (code, value) => set((s) => ({\n    form: {\n      ...s.form,\n      optionGroups: s.form.optionGroups.map((g) => (\n        g.code === code ? { ...g, values: g.values.filter((x) => x.value !== value) } : g\n      )),\n    },\n  })),\n  setOptionValuePhoto: (code, value, imageUrl) => set((s) => ({\n    form: {\n      ...s.form,\n      optionGroups: s.form.optionGroups.map((g) => (\n        g.code === code\n          ? { ...g, values: g.values.map((x) => (x.value === value ? { ...x, imageUrl } : x)) }\n          : g\n      )),\n    },\n    error: null,\n  })),\n\n  /**\n   * Genera las combinaciones del producto cartesiano.\n   *\n   * **Conserva** el precio y el stock de las combinaciones que ya existían (misma firma) para no\n   * borrar el trabajo del comerciante cada vez que añade un color o una talla.\n   */\n  generarCombinaciones: () => {\n    const grupos = get().form.optionGroups.filter((g) => g.values.length > 0);\n    if (!grupos.length) return 'Primero añade un eje con sus valores (por ejemplo Color o Talla)';\n    const combos = combinacionesDe(grupos);\n    if (combos.length > COMBOS_MAX) return `Con esos valores salen ${combos.length} combinaciones y el máximo es ${COMBOS_MAX}`;\n    const antes = get().form.variants;\n    const porFirma = new Map(antes.filter((v) => v.attributes && Object.keys(v.attributes).length).map((v) => [firmaDe(grupos, v.attributes), v]));\n    const productStock = get().form.stockQuantity;\n    set((s) => ({\n      form: {\n        ...s.form,\n        variants: combos.map((c) => {\n          const previo = porFirma.get(firmaDe(grupos, c.attrs));\n          return {\n            name: c.nombre,\n            priceXaf: previo?.priceXaf ?? '',\n            stockQuantity: previo?.stockQuantity ?? productStock,\n            attributes: c.attrs,\n          };\n        }),\n      },\n      error: null,\n    }));\n    return null;\n  },\n\n  // ── Tanda J: las tablas de tallas ────────────────────────────────────────\n  setSizeChart: (chart) => set((s) => ({\n    form: {\n      ...s.form,\n      sizeCharts: [\n        ...s.form.sizeCharts.filter((c) => !(c.gender === chart.gender && c.kind === chart.kind)),\n        chart,\n      ],\n    },\n    error: null,\n  })),\n  removeSizeChart: (gender, kind) => set((s) => ({\n    form: { ...s.form, sizeCharts: s.form.sizeCharts.filter((c) => !(c.gender === gender && c.kind === kind)) },\n  })),\n\n  /** Alta o edición de un detalle por clave (evita claves repetidas). */\n  setAttribute: (key, value) => {\n    const k = key.trim();\n    const v = value.trim();\n    if (!k) return;\n    set((s) => {\n      const others = s.form.attributes.filter((a) => a.key.trim().toLowerCase() !== k.toLowerCase());\n      const list = v ? [...others, { key: k, value: v }] : others;\n      return { form: { ...s.form, attributes: list }, error: null };\n    });\n  },\n  removeAttribute: (key) => set((s) => ({\n    form: { ...s.form, attributes: s.form.attributes.filter((a) => a.key !== key) },\n  })),\n\n  /** Clave de idempotencia ESTABLE por intento: se crea una vez y se reutiliza. */\n  ensureIdemKey: () => {\n    const cur = get().idemKey;\n    if (cur) return cur;\n    const key = Crypto.randomUUID();\n    set({ idemKey: key });\n    return key;\n  },\n  clearIdemKey: () => set({ idemKey: null }),\n  setSubmitting: (submitting) => set({ submitting }),\n  setError: (error) => set({ error }),\n  reset: () => set({ form: createEmptyForm(), step: 'type', idemKey: null, submitting: false, error: null }),\n}));\n","/**\n * utils/combinaciones.ts — LAS REGLAS DE LOS EJES Y LAS COMBINACIONES, UNA SOLA VEZ (app).\n *\n * POR QUÉ EXISTE. En el servidor, estas reglas viven en un módulo único\n * (`src/services/opciones-producto.ts`) para que los dos mercados —Mercado y Life Book— **no puedan\n * rechazar cosas distintas**: un color sin su foto real, un eje repetido, una combinación que no\n * existe. En la app pasaba lo contrario: los topes y el producto cartesiano estaban escritos **solo**\n * dentro de `state/commercePublish.ts`, que es el estado del asistente de Life Book. La pantalla de\n * combinaciones del Mercado habría tenido que copiarlos, y a la segunda copia los dos mercados\n * empiezan a divergir: uno deja 60 combinaciones y el otro 50, y el comerciante lee un error que no\n * entiende sobre algo que la interfaz le dejó escribir.\n *\n * QUÉ SE COMPARTE, y por qué precisamente esto:\n *   · los **TOPES**, que son los mismos que aplica el servidor (3 ejes, 30 valores, 60 combinaciones);\n *   · el **CÓDIGO** de un eje —el eje viaja al servidor como `code`, no como su etiqueta—;\n *   · la **FIRMA** de una combinación: su identidad (los valores de los ejes en su orden, en\n *     minúsculas). Es lo que permite regenerar la matriz sin borrar lo que el comerciante ya escribió;\n *   · el **PRODUCTO CARTESIANO**: las combinaciones se generan, no se teclean;\n *   · el **RESUMEN**: precio mínimo y máximo, existencias totales y el aviso de rango disparado.\n *\n * QUÉ NO SE COMPARTE, a propósito:\n *   · el **payload**. Cada mercado tiene su forma: Life Book manda `chartKind` y sus tablas de tallas;\n *     el Mercado no las tiene y no se le inventan. Unificarlo obligaría a un tipo con campos\n *     opcionales que significan cosas distintas en cada sitio.\n *   · el **estado**. Life Book lleva un borrador en zustand con seis pasos; el Mercado edita un\n *     anuncio que ya existe y le basta con el estado del componente. Meter el del Mercado en el store\n *     de Life Book sería tocar un mercado que funciona para no ganar nada.\n *\n * `state/commercePublish.ts` **delega aquí** estas funciones (que antes eran la única copia) y las\n * re-exporta, de modo que sus dos consumidores —`OptionGroupsEditor` y la propia tienda— no cambian\n * ni una línea. Es el mismo movimiento que hizo el servidor cuando extrajo su módulo compartido.\n */\n\n/**\n * Los topes, los MISMOS que el servidor (`OPCIONES_GRUPOS_MAX` / `OPCIONES_VALORES_MAX` /\n * `COMBINACIONES_MAX`). Si aquí hubiera otro número, la app dejaría rellenar algo que el servidor\n * rechaza — y el comerciante se enteraría al guardar, con el trabajo ya hecho.\n */\nexport const GRUPOS_MAX = 3;\nexport const VALORES_MAX = 30;\nexport const COMBOS_MAX = 60;\n\n/**\n * A partir de este factor, el rango de precios de un mismo anuncio deja de ser una gama y pasa a ser\n * un problema: el comprador ve el precio barato en la lista y al entrar se encuentra el caro.\n *\n * NO es una regla del servidor y por eso aquí es un **aviso**, no un candado: hay anuncios\n * legítimos con un rango grande (un producto con funda y sin funda). La referencia de la que sale\n * —un «hogar» de marketplace— usa 2–3× y recomienda partir el anuncio en dos si hace falta más.\n */\nexport const FACTOR_RANGO_AMPLIO = 3;\n\n/** Lo mínimo que hay que saber de un eje para operar con él. Sirve para los dos mercados. */\nexport interface GrupoConValores {\n  code: string;\n  values: { value: string }[];\n}\n\n/**\n * El código de un eje a partir de su nombre: «Talla (calzado)» → `talla_calzado`.\n *\n * El servidor vuelve a calcularlo (y es él quien manda), así que esto no es una validación: es para\n * que lo que se ve y lo que se guarda sean lo mismo. Sin esto, el comerciante escribiría «Talla\n * (calzado)» y el servidor guardaría `talla_calzado_`, y las combinaciones —que se atan por el\n * código— hablarían de un eje cuyo nombre no aparece por ningún lado de la pantalla.\n */\nexport const aCodigo = (label: string): string => label.trim().toLowerCase()\n  .normalize('NFD').replace(/[\\u0300-\\u036f]/g, '')\n  .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 30);\n\n/**\n * La FIRMA de una combinación: los valores de los ejes **en su orden**, en minúsculas.\n *\n * Es la identidad de una fila, y de ella depende que regenerar la matriz **conserve** el precio y el\n * stock ya escritos. ADVERTENCIA HEREDADA del servidor (que se apoya en lo mismo): como la identidad\n * es el TEXTO del valor, **renombrar** un valor rompería el emparejamiento y esa fila se iría con su\n * stock. Hoy no puede pasar porque un valor solo se **añade** o se **quita**, y quitar avisa de lo\n * que se lleva (ver `EditorDeCombinaciones`).\n */\nexport const firmaDe = (grupos: GrupoConValores[], attrs: Record<string, string> | undefined | null): string =>\n  grupos.map((g) => String(attrs?.[g.code] ?? '').trim().toLowerCase()).join('|');\n\n/**\n * El PRODUCTO CARTESIANO de los ejes: «Rojo × S», «Rojo × M», «Azul × S»…\n *\n * Es como lo hacen los marketplaces grandes: el comerciante **no escribe las combinaciones**, solo\n * pone su precio y su stock. Escribirlas a mano es donde se cuelan las que no existen —una talla XL\n * en un color que no se fabrica— y las que faltan.\n *\n * Genérico sobre `T` para que sirva a las dos formas de eje (la del Mercado y la de Life Book) sin\n * obligar a ninguna a convertirse en la otra.\n */\nexport function combinacionesDe<T extends GrupoConValores>(grupos: T[]): { attrs: Record<string, string>; nombre: string }[] {\n  const utiles = grupos.filter((g) => g.values.length > 0);\n  if (!utiles.length) return [];\n  let acc: { attrs: Record<string, string>; nombre: string }[] = [{ attrs: {}, nombre: '' }];\n  for (const g of utiles) {\n    const siguiente: { attrs: Record<string, string>; nombre: string }[] = [];\n    for (const base of acc) {\n      for (const v of g.values) {\n        siguiente.push({\n          attrs: { ...base.attrs, [g.code]: v.value },\n          nombre: base.nombre ? `${base.nombre} · ${v.value}` : v.value,\n        });\n      }\n    }\n    acc = siguiente;\n  }\n  return acc;\n}\n\n/**\n * Un número escrito a mano en un campo de texto, o `null` si no hay ninguno.\n *\n * `''` NO es 0 y la diferencia importa: un precio vacío **hereda el del anuncio**, mientras que un\n * 0 sería un precio de cero XAF. Confundirlos es la clase de atajo que convierte «no lo he puesto\n * todavía» en «lo regalo».\n */\nexport const numeroDe = (texto: string | null | undefined): number | null => {\n  const limpio = String(texto ?? '').replace(/[^\\d]/g, '');\n  return limpio ? Number(limpio) : null;\n};\n\n/** Una combinación tal y como se está ESCRIBIENDO en el editor: precio y stock son texto. */\nexport interface BorradorVariante {\n  name: string;\n  priceXaf: string;\n  stockQuantity: string;\n  attributes: Record<string, string>;\n}\n\nexport interface ResumenCombinaciones {\n  n: number;\n  /** El precio más bajo y el más alto que puede llegar a pagar el comprador (vacío = el del anuncio). */\n  precioMin: number | null;\n  precioMax: number | null;\n  /** La suma de las existencias escritas: es el `stock` que el servidor espejará en el anuncio. */\n  stockTotal: number;\n  /** Cuántas combinaciones se quedan sin unidades: se verán en la ficha como «agotado». */\n  agotadas: number;\n  /** `precioMax > precioMin × FACTOR_RANGO_AMPLIO`: el rango se avisa, no se bloquea. */\n  rangoAmplio: boolean;\n}\n\n/**\n * El resumen que el editor enseña EN VIVO mientras se escribe.\n *\n * Existe porque hay dos cosas que no se ven en una lista de filas: **el rango de precios** (cada fila\n * se mira sola) y **el total de existencias** (que en el Mercado es, además, el número que acabará\n * teniendo el anuncio — el anuncio se vende por combinaciones, así que su stock es la suma). Sin este\n * bloque, repartir 20 unidades en dos filas de 20 se guardaría como 40 sin que nadie lo dijera.\n */\nexport function resumenDe(variantes: BorradorVariante[], precioAnuncio: number | null): ResumenCombinaciones {\n  const precios = variantes\n    .map((v) => numeroDe(v.priceXaf) ?? precioAnuncio)\n    .filter((n): n is number => n !== null && n > 0);\n  const stockTotal = variantes.reduce((suma, v) => suma + (numeroDe(v.stockQuantity) ?? 0), 0);\n  const precioMin = precios.length ? Math.min(...precios) : null;\n  const precioMax = precios.length ? Math.max(...precios) : null;\n  return {\n    n: variantes.length,\n    precioMin,\n    precioMax,\n    stockTotal,\n    agotadas: variantes.filter((v) => (numeroDe(v.stockQuantity) ?? 0) <= 0).length,\n    rangoAmplio: !!(precioMin && precioMax && precioMin > 0 && precioMax > precioMin * FACTOR_RANGO_AMPLIO),\n  };\n}\n","/**\n * publish/StepShop.tsx — paso 0: ABRIR MI TIENDA (Parte 34).\n *\n * Es el paso que faltaba en el asistente del dueño: sin tienda no se puede\n * publicar (el servidor responde SHOP_REQUIRED). Gratis y sin burocracia: nombre,\n * dónde estás, cómo cobras y si entregas.\n */\nimport React, { useState } from 'react';\nimport { Alert, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { alpha, espaciado, PrimaryButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { commerceApi } from '../../../api/commerce';\nimport { LB_CITIES } from '../../../constants/lifebook';\nimport { LB_PAY_METHODS, LB_REGIONS } from '../../../constants/commerce';\nimport { usePublishStore } from '../../../state/commercePublish';\nimport { Chip, ChipRow } from '../Chip';\nimport { Notice, StepBlock } from './PublishParts';\n\nexport default function StepShop({ onCreated }: { onCreated: (name: string) => void }) {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const setForm = usePublishStore((s) => s.setForm);\n  const [name, setName] = useState('');\n  const [description, setDescription] = useState('');\n  const [city, setCity] = useState<string>(form.city || 'Malabo');\n  const [barrio, setBarrio] = useState('');\n  const [region, setRegion] = useState<'insular' | 'continental' | 'other'>('insular');\n  const [pays, setPays] = useState<string[]>(['cash_on_delivery', 'transfer']);\n  const [delivers, setDelivers] = useState(true);\n  const [cost, setCost] = useState('');\n  const [busy, setBusy] = useState(false);\n\n  const crear = async () => {\n    if (name.trim().length < 2) {\n      Alert.alert('Tienda', 'Ponle un nombre a tu tienda (mín. 2 letras)');\n      return;\n    }\n    setBusy(true);\n    try {\n      const { shop } = await commerceApi.createShop({\n        name: name.trim(),\n        description: description.trim() || undefined,\n        city,\n        barrio: barrio.trim() || undefined,\n        region,\n        paymentMethods: pays as never,\n        shippingPolicy: delivers\n          ? {\n              name: 'Mismo día',\n              coverage: ['same_city'],\n              transportModes: ['local_courier', 'taxi_moto', 'pickup'],\n              costMode: Number(cost.replace(/\\D/g, '')) > 0 ? 'fixed' : 'on_request',\n              baseCostXaf: Number(cost.replace(/\\D/g, '')) || 0,\n              estimatedTime: '2-4 h',\n            }\n          : null,\n      });\n      // La ciudad/barrio de la tienda son el origen por defecto de lo que publique.\n      setForm({ city, barrio: barrio.trim() });\n      onCreated(shop.name);\n    } catch (e) {\n      Alert.alert('Tienda', e instanceof Error ? e.message : 'No se pudo abrir la tienda');\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  return (\n    <View>\n      <Notice>\n        <Text style={{ fontWeight: '900' }}>Tu tienda es gratis.</Text> Elige un nombre, dónde estás y cómo cobras.\n        Podrás verificarla más adelante para conseguir la insignia y más confianza.\n      </Notice>\n\n      <StepBlock title=\"Nombre de la tienda *\">\n        <TextInput\n          value={name}\n          onChangeText={setName}\n          placeholder=\"Ej.: Moda Paraíso\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={80}\n          style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"¿Qué vendes o qué servicio das?\">\n        <TextInput\n          value={description}\n          onChangeText={setDescription}\n          placeholder=\"Ej.: ropa, teléfonos y arreglos de fontanería\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={600}\n          multiline\n          style={[styles.input, styles.area, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"Ciudad\">\n        <ChipRow>\n          {LB_CITIES.map((c) => (\n            <Chip key={c} label={c} active={city === c} onPress={() => setCity(c)} />\n          ))}\n        </ChipRow>\n      </StepBlock>\n\n      <StepBlock title=\"Barrio o referencia\">\n        <TextInput\n          value={barrio}\n          onChangeText={setBarrio}\n          placeholder=\"Ej.: Paraíso, junto al mercado\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={60}\n          style={[styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"Región\">\n        <ChipRow>\n          {LB_REGIONS.map((r) => (\n            <Chip key={r.id} label={r.label} active={region === r.id} onPress={() => setRegion(r.id)} />\n          ))}\n        </ChipRow>\n      </StepBlock>\n\n      <StepBlock title=\"¿Cómo quieres cobrar?\" hint=\"El estado real de cada método lo confirma la plataforma.\">\n        <ChipRow>\n          {LB_PAY_METHODS.filter((m) => m.id !== 'likebook_wallet').map((m) => (\n            <Chip\n              key={m.id}\n              label={m.label}\n              active={pays.includes(m.id)}\n              onPress={() => setPays((prev) => (prev.includes(m.id) ? prev.filter((x) => x !== m.id) : [...prev, m.id]))}\n            />\n          ))}\n        </ChipRow>\n      </StepBlock>\n\n      <StepBlock title=\"Entrega a domicilio\">\n        <ChipRow>\n          <Chip label=\"Sí, hago entregas\" active={delivers} onPress={() => setDelivers(true)} />\n          <Chip label=\"Solo recogida en tienda\" active={!delivers} onPress={() => setDelivers(false)} />\n        </ChipRow>\n        {delivers ? (\n          <TextInput\n            value={cost}\n            onChangeText={setCost}\n            keyboardType=\"number-pad\"\n            placeholder=\"Coste de entrega en XAF (0 = a consultar)\"\n            placeholderTextColor={colors.textSecondary}\n            style={[styles.input, { marginTop: espaciado.e8, color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }]}\n          />\n        ) : null}\n      </StepBlock>\n\n      <PrimaryButton title=\"Abrir mi tienda\" loading={busy} onPress={crear} />\n      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e8 }}>\n        Podrás cambiar todo esto después desde «Mi tienda».\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  input: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  area: { minHeight: 80, textAlignVertical: 'top' },\n});\n","/**\n * publish/StepType.tsx — paso 1: TIPO y CATEGORÍA (Parte 34 · tanda K).\n *\n * · Los tipos y sus etiquetas salen del catálogo compartido (`LB_SERVICE_TYPES`),\n *   no de una lista escrita a mano: una sola fuente con el catálogo y la ficha.\n * · Incluye la **categoría** (que el asistente del dueño no recogía en ningún\n *   paso y sin la cual el producto no sale en los filtros ni puede sugerir los\n *   atributos de su categoría).\n *\n * TANDA K — LA CATEGORÍA SE ELIGE EN DOS NIVELES.\n *\n * Antes esto pintaba **las hijas de la primera rama del tipo** y nada más: medido en el Poco F5, un\n * producto físico solo dejaba elegir entre las hijas de «Abacería» (Arroz y granos, Aceite…), así que\n * «Ropa mujer», «Calzado» o «Teléfonos y tablets» eran **inalcanzables**… y sin esa categoría el\n * comerciante tampoco veía los ejes sugeridos (talla, color, almacenamiento). Ahora se elige primero\n * la rama y después la subcategoría (y una rama sin hijas se puede elegir ella misma).\n */\nimport React, { useState } from 'react';\nimport { Text, View } from 'react-native';\nimport { espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { LB_SERVICE_TYPES } from '../../../constants/commerce';\nimport { usePublishStore } from '../../../state/commercePublish';\nimport type { LbCategory } from '../../../api/commerce';\nimport { Chip, ChipRow } from '../Chip';\nimport { Notice, StepBlock, raizYCategoria } from './PublishParts';\n\nexport default function StepType({ categories }: { categories: LbCategory[] }) {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const setForm = usePublishStore((s) => s.setForm);\n  /** La rama que se está mirando (por defecto, la de la categoría ya elegida). */\n  const [ramaId, setRamaId] = useState<string | null>(null);\n\n  const { raices, raiz, sub } = raizYCategoria(categories, form.serviceType, form.categoryId);\n  const rama = raices.find((r) => r.id === ramaId) ?? raiz;\n  const hijas = rama?.children ?? [];\n  const tipo = LB_SERVICE_TYPES.find((t) => t.id === form.serviceType);\n\n  return (\n    <View>\n      <StepBlock title=\"¿Qué quieres publicar?\" hint=\"Los campos del formulario se adaptan al tipo que elijas.\">\n        <ChipRow>\n          {LB_SERVICE_TYPES.map((t) => (\n            <Chip\n              key={t.id}\n              label={`${t.icon} ${t.label}`}\n              active={form.serviceType === t.id}\n              onPress={() => { setForm({ serviceType: t.id, categoryId: null }); setRamaId(null); }}\n            />\n          ))}\n        </ChipRow>\n        {tipo ? (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>{tipo.hint}</Text>\n        ) : null}\n      </StepBlock>\n\n      {raices.length > 0 ? (\n        <StepBlock\n          title=\"Categoría\"\n          hint=\"Sirve para que te encuentren en los filtros y para sugerirte los detalles y las opciones típicas de lo que vendes (tallas, colores…).\"\n        >\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e6 }}>\n            1 · ¿De qué es?\n          </Text>\n          <ChipRow>\n            {raices.map((r) => (\n              <Chip\n                key={r.id}\n                label={`${r.icon ?? ''} ${r.name}`.trim()}\n                active={rama?.id === r.id}\n                onPress={() => {\n                  setRamaId(r.id);\n                  // Una rama sin subcategorías se puede elegir ella misma.\n                  setForm({ categoryId: (r.children ?? []).length ? null : r.id });\n                }}\n              />\n            ))}\n          </ChipRow>\n\n          {hijas.length > 0 ? (\n            <View style={{ marginTop: espaciado.e12 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e6 }}>\n                2 · ¿Cuál? {rama ? `(${rama.name})` : ''}\n              </Text>\n              <ChipRow>\n                {hijas.map((c) => (\n                  <Chip\n                    key={c.id}\n                    label={`${c.icon ?? ''} ${c.name}`.trim()}\n                    active={form.categoryId === c.id}\n                    onPress={() => setForm({ categoryId: form.categoryId === c.id ? null : c.id })}\n                  />\n                ))}\n              </ChipRow>\n              {sub ? (\n                <Text style={{ color: colors.success, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6 }}>\n                  Elegida: {sub.name}\n                </Text>\n              ) : null}\n            </View>\n          ) : null}\n        </StepBlock>\n      ) : null}\n\n      {!form.categoryId && hijas.length > 0 ? (\n        <Notice>Sin categoría tu publicación no aparecerá al filtrar por categoría. Se recomienda elegir una.</Notice>\n      ) : null}\n    </View>\n  );\n}\n","/**\n * publish/StepMedia.tsx — paso FOTOS (Parte 34).\n *\n * Integra la idea del dueño con las correcciones detectadas:\n *   · usa el pipeline **multipart que ya funciona** (`lifebookMediaApi.uploadFile`,\n *     con permisos y compresión del wrapper `core/pickImage`), no una subida\n *     firmada que aún no existe;\n *   · los archivos se identifican por **url** (antes por `position`, que se\n *     duplicaba y hacía que quitar una borrara dos);\n *   · la vista previa usa la **imagen local** recién elegida, sin volver a bajarla;\n *   · error visible si algo falla (antes había un `catch` vacío).\n */\nimport React, { useState } from 'react';\nimport { ActivityIndicator, Alert, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { Camera, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { lifebookMediaApi } from '../../../api/lifebook';\nimport { pickImagesFromLibrary } from '../../../core/pickImage';\nimport { usePublishStore } from '../../../state/commercePublish';\nimport { Notice, StepBlock } from './PublishParts';\n\nconst MAX = 10;\n\nexport default function StepMedia() {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const addMedia = usePublishStore((s) => s.addMedia);\n  const removeMedia = usePublishStore((s) => s.removeMedia);\n  const [uploading, setUploading] = useState(false);\n  const [locals, setLocals] = useState<Record<string, string>>({});\n\n  const pick = async () => {\n    if (uploading || form.media.length >= MAX) return;\n    try {\n      const picked = await pickImagesFromLibrary(MAX - form.media.length);\n      if (!picked.length) return;\n      setUploading(true);\n      for (const img of picked) {\n        const up = await lifebookMediaApi.uploadFile('image', {\n          uri: img.uri,\n          name: `comercio-${Date.now()}.jpg`,\n          mimeType: 'image/jpeg',\n        });\n        if (up?.url) {\n          addMedia({ url: up.url, type: 'image' });\n          setLocals((prev) => ({ ...prev, [up.url]: img.uri }));\n        }\n      }\n    } catch (e) {\n      Alert.alert('Fotos', e instanceof Error ? e.message : 'No se pudieron subir las fotos');\n    } finally {\n      setUploading(false);\n    }\n  };\n\n  const obligatoria = form.serviceType === 'physical';\n\n  return (\n    <View>\n      <StepBlock\n        title={`Fotos y vídeo (${form.media.length}/${MAX})`}\n        hint={obligatoria\n          ? 'La primera foto será la portada. En una venta hace falta al menos una.'\n          : 'Opcional en servicios, alojamientos, alquileres y ofertas de trabajo, pero ayuda a que te elijan.'}\n      >\n        <View style={styles.grid}>\n          {form.media.map((m) => (\n            <View key={m.url} style={styles.thumb}>\n              <Image\n                source={locals[m.url] ?? m.url}\n                style={StyleSheet.absoluteFill}\n                contentFit=\"cover\"\n                cachePolicy=\"memory-disk\"\n                transition={0}\n              />\n              <Pressable\n                onPress={() => removeMedia(m.url)}\n                accessibilityLabel=\"Quitar foto\"\n                hitSlop={8}\n                style={styles.del}\n              >\n                <X size={13} color={brand.white} />\n              </Pressable>\n            </View>\n          ))}\n          {form.media.length < MAX ? (\n            <Pressable\n              onPress={pick}\n              accessibilityLabel=\"Añadir fotos\"\n              style={[styles.add, { borderColor: alpha(colors.border, 0.9), backgroundColor: colors.surface }]}\n            >\n              {uploading ? <ActivityIndicator color={colors.primary} /> : <Camera size={22} color={colors.primary} />}\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e5, textAlign: 'center' }}>\n                {uploading ? 'Subiendo…' : 'Añadir'}\n              </Text>\n            </Pressable>\n          ) : null}\n        </View>\n      </StepBlock>\n\n      {form.media.length > 0 ? (\n        <GhostButton title=\"Añadir más fotos\" onPress={pick} disabled={uploading} />\n      ) : null}\n\n      {!obligatoria && form.media.length === 0 ? (\n        <Notice>Puedes continuar sin fotos, pero las publicaciones con foto reciben muchas más consultas.</Notice>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  thumb: { width: 92, height: 92, borderRadius: radios.md, overflow: 'hidden', backgroundColor: '#eee' },\n  del: {\n    position: 'absolute', top: 5, right: 5, width: 22, height: 22, borderRadius: 11,\n    backgroundColor: 'rgba(0,0,0,0.6)', alignItems: 'center', justifyContent: 'center',\n  },\n  add: {\n    width: 92, height: 92, borderRadius: radios.md, borderWidth: 1.5, borderStyle: 'dashed',\n    alignItems: 'center', justifyContent: 'center',\n  },\n});\n","/**\n * publish/StepDetails.tsx — paso 3: DATOS (Parte 34).\n *\n * Corrige los dos fallos que bloqueaban la publicación en el asistente original:\n *   · **«precio a consultar»** con `priceMode` (antes exigía precio > 0 y no había\n *     forma de marcar esta opción, imprescindible para oficios);\n *   · **precio anterior vacío** ya no se envía como 0 (eso provocaba\n *     OLD_PRICE_INVALID al publicar sin descuento).\n * Los importes se guardan como texto y se convierten al enviar: nada de `|| 0`.\n */\nimport React from 'react';\nimport { StyleSheet, Text, TextInput, View } from 'react-native';\nimport { alpha, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { LB_CITIES } from '../../../constants/lifebook';\nimport { LB_CONDITIONS, LB_PRICE_MODES, LB_STOCK_MODES } from '../../../constants/commerce';\nimport { usePublishStore } from '../../../state/commercePublish';\nimport { Chip, ChipRow } from '../Chip';\nimport { StepBlock } from './PublishParts';\n\nexport default function StepDetails() {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const setForm = usePublishStore((s) => s.setForm);\n\n  const input = [styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }];\n\n  return (\n    <View>\n      <StepBlock title=\"Título *\">\n        <TextInput\n          value={form.title}\n          onChangeText={(v) => setForm({ title: v })}\n          placeholder={form.serviceType === 'local_service' ? 'Ej.: Fontanero para fugas y grifos' : 'Ej.: Zapatillas deportivas talla 42'}\n          placeholderTextColor={colors.textSecondary}\n          maxLength={140}\n          style={input}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"Resumen corto\" hint=\"Una línea que se ve en la tarjeta del catálogo.\">\n        <TextInput\n          value={form.shortDescription}\n          onChangeText={(v) => setForm({ shortDescription: v })}\n          placeholder=\"Ej.: Nuevas, talla 42, envío en el día\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={200}\n          style={input}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"Descripción\">\n        <TextInput\n          value={form.longDescription}\n          onChangeText={(v) => setForm({ longDescription: v })}\n          placeholder=\"Detalles, medidas, condiciones, qué incluye…\"\n          placeholderTextColor={colors.textSecondary}\n          multiline\n          maxLength={4000}\n          style={[input, styles.area]}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"Precio\">\n        <ChipRow>\n          {LB_PRICE_MODES.map((m) => (\n            <Chip key={m.id} label={m.label} active={form.priceMode === m.id} onPress={() => setForm({ priceMode: m.id })} />\n          ))}\n        </ChipRow>\n        {form.priceMode !== 'on_request' ? (\n          <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n            <TextInput\n              value={form.price}\n              onChangeText={(v) => setForm({ price: v.replace(/[^\\d]/g, '') })}\n              keyboardType=\"number-pad\"\n              placeholder=\"Precio en XAF\"\n              placeholderTextColor={colors.textSecondary}\n              style={[input, { flex: 1 }]}\n            />\n            <TextInput\n              value={form.oldPrice}\n              onChangeText={(v) => setForm({ oldPrice: v.replace(/[^\\d]/g, '') })}\n              keyboardType=\"number-pad\"\n              placeholder=\"Antes (opcional)\"\n              placeholderTextColor={colors.textSecondary}\n              style={[input, { flex: 1 }]}\n            />\n          </View>\n        ) : (\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e8 }}>\n            El cliente te escribe y le das presupuesto. Ideal para oficios, mudanzas o alquileres.\n          </Text>\n        )}\n      </StepBlock>\n\n      <StepBlock title=\"Disponibilidad\">\n        <ChipRow>\n          {LB_STOCK_MODES.map((s) => (\n            <Chip key={s.id} label={s.label} active={form.stockMode === s.id} onPress={() => setForm({ stockMode: s.id })} />\n          ))}\n        </ChipRow>\n        {form.stockMode === 'exact' || form.stockMode === 'approximate' ? (\n          <TextInput\n            value={form.stockQuantity}\n            onChangeText={(v) => setForm({ stockQuantity: v.replace(/[^\\d]/g, '') })}\n            keyboardType=\"number-pad\"\n            placeholder=\"¿Cuántas unidades tienes?\"\n            placeholderTextColor={colors.textSecondary}\n            style={[input, { marginTop: espaciado.e8 }]}\n          />\n        ) : null}\n      </StepBlock>\n\n      <StepBlock title=\"Estado\">\n        <ChipRow>\n          {LB_CONDITIONS.map((c) => (\n            <Chip key={c.id} label={c.label} active={form.condition === c.id} onPress={() => setForm({ condition: c.id })} />\n          ))}\n        </ChipRow>\n      </StepBlock>\n\n      <StepBlock title=\"Ciudad\">\n        <ChipRow>\n          {LB_CITIES.map((c) => (\n            <Chip key={c} label={c} active={form.city === c} onPress={() => setForm({ city: c })} compact />\n          ))}\n        </ChipRow>\n        <TextInput\n          value={form.barrio}\n          onChangeText={(v) => setForm({ barrio: v })}\n          placeholder=\"Barrio o referencia (opcional)\"\n          placeholderTextColor={colors.textSecondary}\n          maxLength={60}\n          style={[input, { marginTop: espaciado.e8 }]}\n        />\n      </StepBlock>\n\n      <StepBlock title=\"Etiquetas\" hint=\"Separadas por comas. Ayudan a que te encuentren al buscar.\">\n        <TextInput\n          value={form.tags}\n          onChangeText={(v) => setForm({ tags: v })}\n          placeholder=\"Ej.: zapatillas, deporte, oferta\"\n          placeholderTextColor={colors.textSecondary}\n          style={input}\n        />\n      </StepBlock>\n\n      <View style={[styles.priceHint, { backgroundColor: alpha(colors.primary, 0.07) }]}>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n          Consejo: no pongas teléfonos ni enlaces en la descripción — el contacto va por el chat de Life Book.\n        </Text>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  input: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body },\n  area: { minHeight: 96, textAlignVertical: 'top' },\n  priceHint: { borderRadius: 10, padding: espaciado.e10 },\n});\n","/**\n * publish/StepExtras.tsx — paso 4: DETALLES, OPCIONES y ENTREGA (Parte 34).\n *\n * Integra las dos buenas ideas del asistente del dueño (atributos sugeridos por\n * categoría y variantes) con los arreglos necesarios:\n *   · los detalles salen de **la categoría que sirve el servidor**\n *     (`defaultAttributes`), no de una lista fija por tipo que solo cubría 6 casos;\n *   · **no se pueden repetir** claves ni nombres de opción (el servidor responde\n *     400 si se repiten: antes se podía llegar al final y fallar al publicar);\n *   · el stock vacío **hereda el del producto** en vez de guardar 0, que marcaba\n *     todas las opciones como «agotadas»;\n *   · el envío (cobertura y medios) **sí se guarda** — antes se perdía en estado\n *     local y la ficha salía sin entrega.\n */\nimport React, { useMemo, useState } from 'react';\nimport { Pressable, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { Plus } from 'lucide-react-native';\nimport { alpha, espaciado, GhostButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { LB_COVERAGE, LB_TRANSPORT } from '../../../constants/commerce';\nimport { usePublishStore } from '../../../state/commercePublish';\nimport type { LbCategory, LbOptionSuggestion, LbSizeKind } from '../../../api/commerce';\nimport { Chip, ChipRow } from '../Chip';\nimport { Notice, StepBlock, raizYCategoria } from './PublishParts';\nimport OptionGroupsEditor from './OptionGroupsEditor';\nimport SizeChartEditor from './SizeChartEditor';\n\nexport default function StepExtras({ categories }: { categories: LbCategory[] }) {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const setForm = usePublishStore((s) => s.setForm);\n  const setAttribute = usePublishStore((s) => s.setAttribute);\n  const removeAttribute = usePublishStore((s) => s.removeAttribute);\n\n  const [nuevoDetalle, setNuevoDetalle] = useState({ key: '', value: '' });\n\n  /**\n   * TANDA K: los ejes de opciones y sus tablas de tallas. Se ofrecen en **todo tipo de producto**\n   * (una comida tiene raciones, un servicio tiene duración, una electrónica tiene almacenamiento),\n   * salvo en las ofertas de empleo, que no se compran. El alojamiento no pasa por aquí: se da de\n   * alta en el panel del hotel y se reserva por fechas y huéspedes.\n   */\n  const conOpciones = form.serviceType !== 'job';\n  const tiposDeTalla = useMemo(\n    () => [...new Set(form.optionGroups.filter((g) => g.kind === 'size').map((g) => (g.chartKind ?? 'top') as LbSizeKind))],\n    [form.optionGroups],\n  );\n  const input = [styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }];\n\n  /** Atributos que sugiere la categoría elegida (con los del padre como respaldo). */\n  const sugeridos = useMemo(() => {\n    const { raiz: root, sub } = raizYCategoria(categories, form.serviceType, form.categoryId);\n    const lista = (sub?.defaultAttributes?.length ? sub.defaultAttributes : root?.defaultAttributes) ?? [];\n    return lista;\n  }, [categories, form.serviceType, form.categoryId]);\n\n  const valorDe = (key: string) => form.attributes.find((a) => a.key.toLowerCase() === key.toLowerCase())?.value ?? '';\n\n  /**\n   * Los EJES que sugiere la categoría (tanda K): ropa propone Talla + Color; calzado, tallas de\n   * zapato; teléfonos, almacenamiento + color; comida, formato… Igual que los detalles, salen de la\n   * categoría que sirve el servidor, no de una lista fija en la app.\n   */\n  const sugeridosOpciones = useMemo((): LbOptionSuggestion[] => {\n    const { raiz: root, sub } = raizYCategoria(categories, form.serviceType, form.categoryId);\n    const lista = (sub?.defaultOptions?.length ? sub.defaultOptions : root?.defaultOptions) ?? [];\n    return lista;\n  }, [categories, form.serviceType, form.categoryId]);\n\n  return (\n    <View>\n      {/* ── Detalles que sugiere la categoría ── */}\n      <StepBlock\n        title=\"Detalles\"\n        hint={sugeridos.length\n          ? 'Rellena los que apliquen: ayudan al comprador a decidir. Los que dejes vacíos no se publican.'\n          : 'Añade los detalles que quieras (marca, medidas, garantía…).'}\n      >\n        {sugeridos.map((a) => (\n          <View key={a.key} style={{ marginBottom: espaciado.e8 }}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e4 }}>\n              {a.label ?? a.key}{a.type === 'select' && a.options?.length ? ` (${a.options.join(' / ')})` : ''}\n            </Text>\n            <TextInput\n              value={valorDe(a.key)}\n              onChangeText={(v) => setAttribute(a.label ?? a.key, v)}\n              placeholder=\"—\"\n              placeholderTextColor={colors.textSecondary}\n              style={input}\n            />\n          </View>\n        ))}\n\n        {/* Detalle libre */}\n        <View style={{ flexDirection: 'row', gap: espaciado.e8, alignItems: 'center', marginTop: espaciado.e4 }}>\n          <TextInput\n            value={nuevoDetalle.key}\n            onChangeText={(v) => setNuevoDetalle((p) => ({ ...p, key: v }))}\n            placeholder=\"Otro detalle\"\n            placeholderTextColor={colors.textSecondary}\n            style={[input, { flex: 1 }]}\n          />\n          <TextInput\n            value={nuevoDetalle.value}\n            onChangeText={(v) => setNuevoDetalle((p) => ({ ...p, value: v }))}\n            placeholder=\"Valor\"\n            placeholderTextColor={colors.textSecondary}\n            style={[input, { flex: 1 }]}\n          />\n          <Pressable\n            onPress={() => {\n              if (!nuevoDetalle.key.trim() || !nuevoDetalle.value.trim()) return;\n              setAttribute(nuevoDetalle.key, nuevoDetalle.value);\n              setNuevoDetalle({ key: '', value: '' });\n            }}\n            accessibilityLabel=\"Añadir detalle\"\n            style={[styles.addBtn, { borderColor: colors.primary }]}\n          >\n            <Plus size={17} color={colors.primary} />\n          </Pressable>\n        </View>\n      </StepBlock>\n\n      {/* ── Opciones (tanda K): los ejes que el comprador elige antes de comprar ──\n          Antes esto era una lista de nombres sueltos («Talla 42») con precio y stock, y así\n          llegaba a la ficha: la app solo podía enseñar la PALABRA y compraba directo con la\n          primera. Ahora se configuran ejes (Color con la foto real de cada color, Talla con su\n          tabla, Almacenamiento, Formato…) y las combinaciones con su precio y su stock. */}\n      {conOpciones ? (\n        <>\n          <OptionGroupsEditor sugeridos={sugeridosOpciones} />\n          {tiposDeTalla.length ? <SizeChartEditor kinds={tiposDeTalla} /> : null}\n        </>\n      ) : null}\n\n      {/* ── Entrega ── */}\n      <StepBlock title=\"Entrega\" hint=\"Hasta dónde llevas lo que publicas.\">\n        <ChipRow>\n          {LB_COVERAGE.map((c) => (\n            <Chip\n              key={c.id}\n              label={c.label}\n              active={form.coverage.includes(c.id)}\n              onPress={() => setForm({\n                coverage: form.coverage.includes(c.id) ? form.coverage.filter((x) => x !== c.id) : [...form.coverage, c.id],\n              })}\n            />\n          ))}\n        </ChipRow>\n      </StepBlock>\n\n      <StepBlock title=\"¿Cómo lo entregas?\">\n        <ChipRow>\n          {LB_TRANSPORT.map((t) => (\n            <Chip\n              key={t.id}\n              label={t.label}\n              active={form.transports.includes(t.id)}\n              onPress={() => setForm({\n                transports: form.transports.includes(t.id) ? form.transports.filter((x) => x !== t.id) : [...form.transports, t.id],\n              })}\n            />\n          ))}\n        </ChipRow>\n      </StepBlock>\n\n      {form.coverage.includes('international') ? (\n        <Notice>Cobrarás el envío internacional a consultar: la plataforma aún no calcula tarifas fuera del país.</Notice>\n      ) : null}\n\n      <StepBlock title=\"Coste del envío en tu ciudad (XAF)\">\n        <TextInput\n          value={form.deliveryCost}\n          onChangeText={(v) => setForm({ deliveryCost: v.replace(/[^\\d]/g, '') })}\n          keyboardType=\"number-pad\"\n          placeholder=\"0 = a consultar con la tienda\"\n          placeholderTextColor={colors.textSecondary}\n          style={input}\n        />\n      </StepBlock>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  input: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e9, fontSize: tipografia.body },\n  addBtn: {\n    width: 40, height: 40, borderRadius: 10, borderWidth: 1.5,\n    alignItems: 'center', justifyContent: 'center',\n  },\n});\n","/**\n * components/lifebook/publish/OptionGroupsEditor.tsx — LOS EJES DE ELECCIÓN (tanda K).\n *\n * POR QUÉ EXISTE. Hasta esta tanda, «Opciones» del publicador era una lista de nombres sueltos\n * («Talla 42», «Talla 40») con su precio y su stock, y así llegaba a la ficha: la app solo podía\n * enseñar la PALABRA «Talla 42» y los botones Comprar/Añadir al carrito compraban directo con la\n * primera de la lista. El dueño lo dijo con todas las letras: «no vale sólo poner color, debe verse\n * el producto de la foto real de este color».\n *\n * CÓMO ESTÁ PENSADO (lo mismo que hacen Taobao y Shopify, en pequeño):\n *   · el comerciante define EJES («Color», «Talla», «Almacenamiento», «Formato»…). La categoría ya\n *     sugiere los suyos, así que casi siempre es tocar un chip;\n *   · cada eje tiene VALORES. En un eje de color **cada valor lleva su foto**, elegida entre las\n *     fotos que el comerciante ya subió: el servidor no admite un color sin foto ni una foto que\n *     no sea de ese producto;\n *   · las COMBINACIONES (Rojo · M, Rojo · L…) **se generan solas** del producto cartesiano y el\n *     comerciante solo pone precio y stock. Al volver a generar, se conserva lo que ya había escrito.\n */\nimport React, { useMemo, useState } from 'react';\nimport { Alert, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { Plus, X } from 'lucide-react-native';\nimport { alpha, espaciado, GhostButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../../../api/config';\nimport type { LbOptionSuggestion, LbSizeKind } from '../../../api/commerce';\nimport {\n  COMBOS_MAX, GRUPOS_MAX, combinacionesDe, usePublishStore,\n} from '../../../state/commercePublish';\nimport { Chip, ChipRow } from '../Chip';\nimport { Notice, StepBlock } from './PublishParts';\n\nconst TIPOS: { id: 'color' | 'size' | 'text'; label: string; ayuda: string }[] = [\n  { id: 'color', label: 'Color', ayuda: 'cada color con su FOTO real' },\n  { id: 'size', label: 'Talla', ayuda: 'con su tabla de medidas' },\n  { id: 'text', label: 'Otro', ayuda: 'almacenamiento, formato, tono…' },\n];\n\nconst TABLAS: { id: LbSizeKind; label: string }[] = [\n  { id: 'top', label: 'Arriba' },\n  { id: 'bottom', label: 'Abajo' },\n  { id: 'dress', label: 'Vestido' },\n  { id: 'shoes', label: 'Calzado' },\n  { id: 'accessory', label: 'Accesorio' },\n  { id: 'other', label: 'Otro' },\n];\n\n/** El código del eje a partir del nombre: «Talla (calzado)» → `talla_calzado`. */\nconst aCodigo = (label: string) => label.trim().toLowerCase()\n  .normalize('NFD').replace(/[\\u0300-\\u036f]/g, '')\n  .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 30);\n\nexport default function OptionGroupsEditor({ sugeridos }: { sugeridos: LbOptionSuggestion[] }) {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const addOptionGroup = usePublishStore((s) => s.addOptionGroup);\n  const removeOptionGroup = usePublishStore((s) => s.removeOptionGroup);\n  const setOptionGroup = usePublishStore((s) => s.setOptionGroup);\n  const addOptionValue = usePublishStore((s) => s.addOptionValue);\n  const removeOptionValue = usePublishStore((s) => s.removeOptionValue);\n  const setOptionValuePhoto = usePublishStore((s) => s.setOptionValuePhoto);\n  const generarCombinaciones = usePublishStore((s) => s.generarCombinaciones);\n  const setVariant = usePublishStore((s) => s.setVariant);\n  const removeVariant = usePublishStore((s) => s.removeVariant);\n\n  const [nuevo, setNuevo] = useState({ label: '', kind: 'text' as 'color' | 'size' | 'text', chartKind: 'top' as LbSizeKind });\n  const [valor, setValor] = useState<Record<string, string>>({});\n  /** Qué valor de color está eligiendo foto (la foto sale de las que ya subió). */\n  const [eligiendoFoto, setEligiendoFoto] = useState<{ code: string; value: string } | null>(null);\n\n  const fotos = useMemo(() => form.media.filter((m) => m.type !== 'video').map((m) => m.url), [form.media]);\n  const grupos = form.optionGroups;\n  const combosPosibles = useMemo(() => combinacionesDe(grupos.filter((g) => g.values.length > 0)).length, [grupos]);\n  const input = [styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }];\n\n  const yaEsta = (code: string) => grupos.some((g) => g.code === code);\n\n  return (\n    <StepBlock\n      title=\"Opciones\"\n      hint=\"Talla, color, almacenamiento… Cada combinación con su precio y su stock.\"\n    >\n      {/* ── Lo que sugiere la categoría ── */}\n      {sugeridos.length ? (\n        <View style={{ marginBottom: espaciado.e10 }}>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e6 }}>\n            Sugeridos por la categoría (toca para añadir)\n          </Text>\n          <ChipRow>\n            {sugeridos.map((s) => {\n              const code = s.code || aCodigo(s.label);\n              const puesto = yaEsta(code);\n              return (\n                <Chip\n                  key={code}\n                  label={puesto ? `${s.label} ✓` : `+ ${s.label}`}\n                  active={puesto}\n                  disabled={puesto || grupos.length >= GRUPOS_MAX}\n                  onPress={() => {\n                    const err = addOptionGroup({\n                      code,\n                      label: s.label,\n                      kind: s.kind,\n                      chartKind: s.kind === 'size' ? (s.chartKind ?? 'top') : null,\n                      /**\n                       * Los valores sugeridos vienen como TEXTO (`[\"XS\",\"S\"]`): leer `v.value` de\n                       * una cadena daba `undefined` y se publicaba la palabra «undefined» como\n                       * talla. Aquí se acepta texto u objeto, sin suponer.\n                       */\n                      values: (s.values ?? []).map((v) => ({\n                        value: typeof v === 'string' ? v : String(v.value ?? ''),\n                        imageUrl: typeof v === 'string' ? '' : (v.imageUrl ?? ''),\n                      })),\n                    });\n                    if (err) Alert.alert('Opciones', err);\n                  }}\n                />\n              );\n            })}\n          </ChipRow>\n        </View>\n      ) : null}\n\n      {/* ── Los ejes que hay ── */}\n      {grupos.map((g) => (\n        <View key={g.code} style={[styles.card, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.surface }]}>\n          <View style={{ flexDirection: 'row', alignItems: 'center' }}>\n            <View style={{ flex: 1 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>{g.label}</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                {g.kind === 'color' ? 'Color · cada uno con su foto' : g.kind === 'size' ? 'Talla · con su tabla de medidas' : 'Valores'}\n                {' · '}{g.values.length} {g.values.length === 1 ? 'valor' : 'valores'}\n              </Text>\n            </View>\n            <Pressable\n              onPress={() => removeOptionGroup(g.code)}\n              accessibilityLabel={`Quitar el eje ${g.label}`}\n              hitSlop={10}\n              style={styles.delBtn}\n            >\n              <X size={15} color={colors.danger} />\n            </Pressable>\n          </View>\n\n          {/* Tipo de tabla si es un eje de tallas (para el asistente «¿no sabes tu talla?») */}\n          {g.kind === 'size' ? (\n            <View style={{ marginTop: espaciado.e8 }}>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e5 }}>\n                ¿Qué parte de la prenda mide esta tabla?\n              </Text>\n              <ChipRow>\n                {TABLAS.map((t) => (\n                  <Chip\n                    key={t.id}\n                    compact\n                    label={t.label}\n                    active={(g.chartKind ?? 'top') === t.id}\n                    onPress={() => setOptionGroup(g.code, { chartKind: t.id })}\n                  />\n                ))}\n              </ChipRow>\n            </View>\n          ) : null}\n\n          {/* ── Los valores ── */}\n          <View style={{ marginTop: espaciado.e10 }}>\n            {g.kind === 'color' ? (\n              <View style={styles.colores}>\n                {g.values.map((v) => (\n                  <View key={v.value} style={styles.colorItem}>\n                    <Pressable\n                      onPress={() => setEligiendoFoto({ code: g.code, value: v.value })}\n                      accessibilityLabel={`Foto del color ${v.value}`}\n                      style={[styles.colorFoto, { borderColor: v.imageUrl ? colors.success : colors.danger, backgroundColor: colors.background }]}\n                    >\n                      {v.imageUrl ? (\n                        <Image source={absUrl(v.imageUrl)} style={styles.colorImg} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                      ) : (\n                        <Text style={{ color: colors.danger, fontSize: 9.5, fontWeight: '800', textAlign: 'center' }}>FALTA{'\\n'}FOTO</Text>\n                      )}\n                    </Pressable>\n                    <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.micro, fontWeight: '700', maxWidth: 62, textAlign: 'center' }}>{v.value}</Text>\n                    <Pressable onPress={() => removeOptionValue(g.code, v.value)} accessibilityLabel={`Quitar ${v.value}`} hitSlop={8}>\n                      <Text style={{ color: colors.danger, fontSize: tipografia.micro, fontWeight: '800' }}>quitar</Text>\n                    </Pressable>\n                  </View>\n                ))}\n              </View>\n            ) : (\n              <ChipRow>\n                {g.values.map((v) => (\n                  <Chip key={v.value} compact label={`${v.value} ✕`} onPress={() => removeOptionValue(g.code, v.value)} />\n                ))}\n              </ChipRow>\n            )}\n\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, alignItems: 'center', marginTop: espaciado.e8 }}>\n              <TextInput\n                value={valor[g.code] ?? ''}\n                onChangeText={(t) => setValor((p) => ({ ...p, [g.code]: t }))}\n                placeholder={g.kind === 'color' ? 'Ej.: Rojo' : g.kind === 'size' ? 'Ej.: M' : 'Ej.: 128 GB'}\n                placeholderTextColor={colors.textSecondary}\n                style={[input, { flex: 1 }]}\n              />\n              <Pressable\n                onPress={() => {\n                  const err = addOptionValue(g.code, valor[g.code] ?? '');\n                  if (err) { Alert.alert('Opciones', err); return; }\n                  setValor((p) => ({ ...p, [g.code]: '' }));\n                }}\n                accessibilityLabel={`Añadir valor a ${g.label}`}\n                style={[styles.addBtn, { borderColor: colors.primary }]}\n              >\n                <Plus size={17} color={colors.primary} />\n              </Pressable>\n            </View>\n            {g.kind === 'color' && g.values.some((v) => !v.imageUrl) ? (\n              <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6 }}>\n                Falta la foto real de ese color.\n              </Text>\n            ) : null}\n          </View>\n        </View>\n      ))}\n\n      {/* ── Añadir un eje que no venía sugerido ── */}\n      {grupos.length < GRUPOS_MAX ? (\n        <View style={{ marginTop: espaciado.e4 }}>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginBottom: espaciado.e5 }}>\n            Otro eje (máximo {GRUPOS_MAX})\n          </Text>\n          <View style={{ flexDirection: 'row', gap: espaciado.e8, alignItems: 'center' }}>\n            <TextInput\n              value={nuevo.label}\n              onChangeText={(t) => setNuevo((p) => ({ ...p, label: t }))}\n              placeholder=\"Ej.: Almacenamiento, Formato, Tono\"\n              placeholderTextColor={colors.textSecondary}\n              style={[input, { flex: 1 }]}\n            />\n            <Pressable\n              onPress={() => {\n                if (!nuevo.label.trim()) { Alert.alert('Opciones', 'Ponle un nombre al eje'); return; }\n                const err = addOptionGroup({\n                  code: aCodigo(nuevo.label),\n                  label: nuevo.label.trim(),\n                  kind: nuevo.kind,\n                  chartKind: nuevo.kind === 'size' ? nuevo.chartKind : null,\n                  // Sin valores no se puede guardar: se crea con uno vacío para que se vea dónde\n                  // escribirlos (y el chip de «Añadir» está debajo).\n                  values: [{ value: '—', imageUrl: '' }],\n                });\n                if (err) { Alert.alert('Opciones', err); return; }\n                setNuevo({ label: '', kind: 'text', chartKind: 'top' });\n              }}\n              accessibilityLabel=\"Añadir eje\"\n              style={[styles.addBtn, { borderColor: colors.primary }]}\n            >\n              <Plus size={17} color={colors.primary} />\n            </Pressable>\n          </View>\n          <View style={{ marginTop: espaciado.e6 }}>\n            <ChipRow>\n              {TIPOS.map((t) => (\n                <Chip key={t.id} compact label={t.label} active={nuevo.kind === t.id} onPress={() => setNuevo((p) => ({ ...p, kind: t.id }))} />\n              ))}\n            </ChipRow>\n          </View>\n        </View>\n      ) : null}\n\n      {/* ── Las combinaciones ── */}\n      {grupos.length ? (\n        <View style={{ marginTop: espaciado.e14 }}>\n          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: espaciado.e6 }}>\n            <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', flex: 1 }}>\n              Combinaciones {combosPosibles ? `(${combosPosibles})` : ''}\n            </Text>\n          </View>\n          {combosPosibles > COMBOS_MAX ? (\n            <Notice tone=\"error\">\n              Con esos valores salen {combosPosibles} combinaciones y el máximo es {COMBOS_MAX}: quita algún color o alguna talla.\n            </Notice>\n          ) : null}\n          <GhostButton\n            title={form.variants.length ? 'Volver a generar (conserva precios)' : 'Generar combinaciones'}\n            onPress={() => {\n              const err = generarCombinaciones();\n              if (err) Alert.alert('Combinaciones', err);\n            }}\n          />\n          {form.variants.map((v, i) => (\n            <View key={`${v.name}-${i}`} style={[styles.combo, { borderColor: alpha(colors.border, 0.7) }]}>\n              <Text numberOfLines={1} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', flex: 1.2 }}>{v.name}</Text>\n              <TextInput\n                value={v.priceXaf}\n                onChangeText={(t) => setVariant(i, { priceXaf: t.replace(/[^\\d]/g, '') })}\n                keyboardType=\"number-pad\"\n                placeholder={form.price ? String(Number(form.price.replace(/\\D/g, ''))) : 'Precio'}\n                placeholderTextColor={colors.textSecondary}\n                style={[input, styles.comboInput]}\n              />\n              <TextInput\n                value={v.stockQuantity}\n                onChangeText={(t) => setVariant(i, { stockQuantity: t.replace(/[^\\d]/g, '') })}\n                keyboardType=\"number-pad\"\n                placeholder=\"Stock\"\n                placeholderTextColor={colors.textSecondary}\n                style={[input, styles.comboInput]}\n              />\n              <Pressable onPress={() => removeVariant(i)} accessibilityLabel={`Quitar ${v.name}`} hitSlop={8} style={styles.delBtn}>\n                <X size={14} color={colors.danger} />\n              </Pressable>\n            </View>\n          ))}\n          {form.variants.length ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>\n              Precio o stock vacíos = los del producto.\n            </Text>\n          ) : null}\n        </View>\n      ) : null}\n\n      {/* ── Elegir la foto real de un color ── */}\n      <Modal visible={!!eligiendoFoto} transparent animationType=\"fade\" onRequestClose={() => setEligiendoFoto(null)}>\n        <Pressable style={styles.backdrop} onPress={() => setEligiendoFoto(null)}>\n          <Pressable style={[styles.sheet, { backgroundColor: colors.background }]} onPress={() => { /* no cerrar */ }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body, marginBottom: espaciado.e4 }}>\n              Foto real del color «{eligiendoFoto?.value}»\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, lineHeight: 17, marginBottom: espaciado.e10 }}>\n              Elige, entre las fotos que ya subiste, la que enseña el producto en ese color. Es la que verá el comprador al elegirlo.\n            </Text>\n            <ScrollView style={{ maxHeight: 360 }}>\n              <View style={styles.grid}>\n                {fotos.map((url) => (\n                  <Pressable\n                    key={url}\n                    onPress={() => {\n                      if (eligiendoFoto) setOptionValuePhoto(eligiendoFoto.code, eligiendoFoto.value, url);\n                      setEligiendoFoto(null);\n                    }}\n                    accessibilityLabel=\"Usar esta foto\"\n                    style={[styles.gridItem, { borderColor: alpha(colors.border, 0.8) }]}\n                  >\n                    <Image source={absUrl(url)} style={{ width: '100%', height: '100%' }} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                  </Pressable>\n                ))}\n              </View>\n            </ScrollView>\n            {fotos.length === 0 ? (\n              <Notice tone=\"error\">Todavía no has subido fotos: vuelve al paso «Fotos» y súbelas (una por color, como mínimo).</Notice>\n            ) : null}\n            <GhostButton title=\"Cancelar\" onPress={() => setEligiendoFoto(null)} />\n          </Pressable>\n        </Pressable>\n      </Modal>\n    </StepBlock>\n  );\n}\n\nconst styles = StyleSheet.create({\n  input: { borderWidth: 1, borderRadius: 10, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e8, fontSize: tipografia.caption },\n  card: { borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginBottom: espaciado.e10 },\n  colores: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10 },\n  colorItem: { alignItems: 'center', gap: espaciado.e3 },\n  colorFoto: { width: 62, height: 62, borderRadius: radios.md, borderWidth: 2, overflow: 'hidden', alignItems: 'center', justifyContent: 'center' },\n  colorImg: { width: '100%', height: '100%' },\n  addBtn: { width: 40, height: 40, borderRadius: 10, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center' },\n  delBtn: { width: 30, height: 30, borderRadius: 15, alignItems: 'center', justifyContent: 'center' },\n  combo: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e7, borderBottomWidth: StyleSheet.hairlineWidth, paddingVertical: espaciado.e7 },\n  comboInput: { width: 78 },\n  backdrop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)', justifyContent: 'flex-end' },\n  sheet: { borderTopLeftRadius: 18, borderTopRightRadius: 18, padding: espaciado.e16, paddingBottom: espaciado.e26 },\n  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  gridItem: { width: 96, height: 96, borderRadius: radios.md, borderWidth: 1, overflow: 'hidden' },\n});\n","/**\n * components/lifebook/publish/SizeChartEditor.tsx — LA TABLA DE TALLAS DEL PRODUCTO (tanda J/K).\n *\n * QUÉ RESUELVE. El servidor ya sabía guardar tablas de tallas (por sexo y tipo, con RANGOS en\n * cm/kg) desde la tanda J, pero **no había forma de escribirlas desde la app**: se configuraban por\n * API. Y sin tabla configurada, el asistente de talla no puede recomendar nada —la regla del dueño\n * es comparar contra la tabla DE ESE PRODUCTO—, así que lo único honesto era no recomendar.\n *\n * CÓMO ESTÁ PENSADO (lo que hacen las tiendas de verdad):\n *   · una tabla por SEXO (mujer · hombre · unisex) y por TIPO (arriba · abajo · vestido · calzado ·\n *     accesorio): un producto puede tener la de mujer y la de hombre a la vez;\n *   · cada talla con sus RANGOS (mín–máx), porque una talla M no es un número exacto: es un\n *     intervalo;\n *   · solo se piden las medidas que esa prenda usa de verdad (arriba → pecho; abajo → cintura y\n *     cadera; calzado → largo y ancho del pie); el resto están detrás de «más medidas»;\n *   · «Rellenar tallas típicas» trae los valores de partida de las tablas estándar, y **se dice que\n *     son orientativos**: los revisa el comerciante y los ajusta a su prenda. Si no coinciden, el\n *     asistente recomendaría mal, así que es él quien manda.\n */\nimport React, { useMemo, useState } from 'react';\nimport { Alert, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { alpha, espaciado, GhostButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport type { LbSizeGender, LbSizeKind } from '../../../api/commerce';\nimport { TALLAS_CALZADO } from '../../../constants/tallas';\nimport { usePublishStore, type PublishSizeChartDraft, type PublishSizeRow } from '../../../state/commercePublish';\nimport { Chip, ChipRow } from '../Chip';\nimport { Notice } from './PublishParts';\n\nconst SEXOS: { id: LbSizeGender; label: string }[] = [\n  { id: 'women', label: 'Mujer' },\n  { id: 'men', label: 'Hombre' },\n  { id: 'unisex', label: 'Unisex' },\n];\n\nconst TIPOS: { id: LbSizeKind; label: string }[] = [\n  { id: 'top', label: 'Arriba' },\n  { id: 'bottom', label: 'Abajo' },\n  { id: 'dress', label: 'Vestido' },\n  { id: 'shoes', label: 'Calzado' },\n  { id: 'accessory', label: 'Accesorio' },\n  { id: 'other', label: 'Otro' },\n];\n\n/** Las medidas que pide cada tipo de prenda (el resto van detrás de «más medidas»). */\nconst CAMPOS: Record<LbSizeKind, { key: string; label: string }[]> = {\n  top: [{ key: 'chest', label: 'Pecho' }, { key: 'height', label: 'Altura' }, { key: 'weight', label: 'Peso' }],\n  bottom: [{ key: 'waist', label: 'Cintura' }, { key: 'hip', label: 'Cadera' }, { key: 'height', label: 'Altura' }],\n  dress: [{ key: 'chest', label: 'Pecho' }, { key: 'waist', label: 'Cintura' }, { key: 'hip', label: 'Cadera' }],\n  shoes: [{ key: 'footLength', label: 'Largo del pie' }, { key: 'footWidth', label: 'Ancho del pie' }],\n  accessory: [{ key: 'chest', label: 'Pecho' }, { key: 'waist', label: 'Cintura' }],\n  other: [{ key: 'chest', label: 'Pecho' }, { key: 'waist', label: 'Cintura' }, { key: 'height', label: 'Altura' }],\n};\n\nconst EXTRA: { key: string; label: string }[] = [\n  { key: 'chest', label: 'Pecho' }, { key: 'waist', label: 'Cintura' }, { key: 'hip', label: 'Cadera' },\n  { key: 'height', label: 'Altura' }, { key: 'weight', label: 'Peso' },\n  { key: 'footLength', label: 'Largo del pie' }, { key: 'footWidth', label: 'Ancho del pie' },\n];\n\n/** La unidad de cada medida, para no escribir «pecho 94» sin decir de qué. */\nconst UNIDAD: Record<string, string> = {\n  chest: 'cm', waist: 'cm', hip: 'cm', height: 'cm', weight: 'kg', footLength: 'cm', footWidth: 'cm',\n};\n\nconst fila = (sizeLabel: string, v: Record<string, number | undefined> = {}): PublishSizeRow => ({\n  sizeLabel,\n  ...Object.fromEntries(EXTRA.flatMap((c) => [\n    [`${c.key}Min${UNIDAD[c.key] === 'kg' ? 'Kg' : 'Cm'}`, v[`${c.key}Min`] !== undefined ? String(v[`${c.key}Min`]) : ''],\n    [`${c.key}Max${UNIDAD[c.key] === 'kg' ? 'Kg' : 'Cm'}`, v[`${c.key}Max`] !== undefined ? String(v[`${c.key}Max`]) : ''],\n  ])),\n});\n\n/**\n * VALORES DE PARTIDA de las tablas estándar (pecho/cintura/cadera en cm, altura en cm, peso en kg y\n * numeración europea de calzado). Son ORIENTATIVOS: el comerciante los revisa y los ajusta a su\n * prenda. Se dice en pantalla, porque una tabla que no coincide con la prenda hace que el asistente\n * recomiende una talla equivocada.\n *\n * OJO (tanda L-bis): al asistente se le piden **altura y peso** (el dueño quitó pecho, cintura y\n * cadera porque casi nadie los sabe). Por eso las tablas típicas traen TAMBIÉN altura y peso: si una\n * tabla solo tuviera pecho, el comprador que da su altura y su peso no podría recibir recomendación.\n * Las columnas de pecho/cintura/cadera siguen ahí para quien las publique.\n */\nconst MUJER_ARRIBA: [string, number, number, number, number][] = [\n  ['XS', 76, 82, 58, 64], ['S', 82, 88, 64, 70], ['M', 88, 94, 70, 76],\n  ['L', 94, 100, 76, 82], ['XL', 100, 107, 82, 90], ['XXL', 107, 114, 90, 98],\n];\nconst HOMBRE_ARRIBA: [string, number, number, number, number][] = [\n  ['S', 86, 94, 71, 79], ['M', 94, 102, 79, 87], ['L', 102, 110, 87, 95],\n  ['XL', 110, 118, 95, 104], ['XXL', 118, 126, 104, 113],\n];\n/** Altura y peso por talla (mujer / hombre). Es lo que el comprador puede dar sin cinta de medir. */\nconst ALTURA_PESO_MUJER: [string, number, number, number, number][] = [\n  ['XS', 150, 158, 42, 50], ['S', 155, 163, 48, 56], ['M', 160, 168, 54, 64],\n  ['L', 165, 173, 62, 72], ['XL', 168, 178, 70, 82], ['XXL', 170, 180, 80, 92],\n];\nconst ALTURA_PESO_HOMBRE: [string, number, number, number, number][] = [\n  ['S', 165, 172, 58, 68], ['M', 170, 178, 66, 78], ['L', 175, 183, 76, 88],\n  ['XL', 180, 188, 86, 100], ['XXL', 183, 193, 98, 112],\n];\n/** Numeración europea → largo del pie en cm (la MISMA equivalencia que usa el asistente del comprador,\n *  para que el número 42 no valga 26 cm en un sitio y 27 en otro). */\nconst ZAPATOS: [string, number][] = TALLAS_CALZADO.map((t) => [String(t.numero), t.cm]);\n\nfunction tipicas(gender: LbSizeGender, kind: LbSizeKind): PublishSizeRow[] {\n  if (kind === 'shoes') return ZAPATOS.map(([label, cm]) => fila(label, { footLengthMin: cm, footLengthMax: cm + 1, footWidthMin: 9, footWidthMax: 10 }));\n  const alturaPeso = gender === 'men' ? ALTURA_PESO_HOMBRE : ALTURA_PESO_MUJER;\n  const conAlturaPeso = (label: string, extra: Record<string, number | undefined>) => {\n    const ap = alturaPeso.find(([l]) => l === label);\n    return fila(label, {\n      ...extra,\n      // Altura y peso SIEMPRE: son las medidas que el comprador puede dar sin cinta de medir.\n      ...(ap ? { heightMin: ap[1], heightMax: ap[2], weightMin: ap[3], weightMax: ap[4] } : {}),\n    });\n  };\n  if (kind === 'bottom') {\n    return MUJER_ARRIBA.map(([label, , chest, waistMin, waistMax]) => conAlturaPeso(label, {\n      waistMin, waistMax, hipMin: chest + 4, hipMax: chest + 10,\n    }));\n  }\n  const tabla = gender === 'men' ? HOMBRE_ARRIBA : MUJER_ARRIBA;\n  return tabla.map(([label, min, max, wMin, wMax]) => conAlturaPeso(label, {\n    chestMin: min, chestMax: max,\n    ...(kind === 'dress' ? { waistMin: wMin, waistMax: wMax, hipMin: min + 4, hipMax: min + 10 } : {}),\n  }));\n}\n\nexport default function SizeChartEditor({ kinds }: { kinds: LbSizeKind[] }) {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n  const setSizeChart = usePublishStore((s) => s.setSizeChart);\n  const removeSizeChart = usePublishStore((s) => s.removeSizeChart);\n  const [abierto, setAbierto] = useState<LbSizeKind | null>(kinds[0] ?? null);\n  const [sexo, setSexo] = useState<Record<string, LbSizeGender>>({});\n  const [masMedidas, setMasMedidas] = useState(false);\n  const input = [styles.input, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }];\n\n  /** Las tablas que ya hay, por `sexo:tipo`. */\n  const porClave = useMemo(() => {\n    const m = new Map<string, PublishSizeChartDraft>();\n    form.sizeCharts.forEach((c) => m.set(`${c.gender}:${c.kind}`, c));\n    return m;\n  }, [form.sizeCharts]);\n\n  const lista = kinds.length ? [...new Set(kinds)] : ['top' as LbSizeKind];\n\n  const guardar = (kind: LbSizeKind, gender: LbSizeGender, rows: PublishSizeRow[], notes = '') =>\n    setSizeChart({ gender, kind, notes, rows });\n\n  return (\n    <View style={{ marginTop: espaciado.e4 }}>\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800', marginBottom: espaciado.e6 }}>\n        Tabla de tallas\n      </Text>\n\n      <ChipRow>\n        {lista.map((k) => (\n          <Chip\n            key={k}\n            label={`${TIPOS.find((t) => t.id === k)?.label ?? k}${porClave.has(`women:${k}`) || porClave.has(`men:${k}`) || porClave.has(`unisex:${k}`) ? ' ✓' : ''}`}\n            active={abierto === k}\n            onPress={() => setAbierto(abierto === k ? null : k)}\n          />\n        ))}\n      </ChipRow>\n\n      {abierto ? (\n        <View style={[styles.card, { borderColor: alpha(colors.border, 0.8), backgroundColor: colors.surface }]}>\n          <ChipRow>\n            {SEXOS.map((s) => (\n              <Chip\n                key={s.id}\n                compact\n                label={s.label}\n                active={(sexo[abierto] ?? 'women') === s.id}\n                onPress={() => setSexo((p) => ({ ...p, [abierto]: s.id }))}\n              />\n            ))}\n          </ChipRow>\n\n          {(() => {\n            const gender = sexo[abierto] ?? 'women';\n            const chart = porClave.get(`${gender}:${abierto}`);\n            const rows = chart?.rows ?? [];\n            const campos = masMedidas ? EXTRA : CAMPOS[abierto];\n            return (\n              <View style={{ marginTop: espaciado.e10 }}>\n                {rows.length === 0 ? (\n                  <>\n                    <Notice>\n                      No hay tabla de {SEXOS.find((s) => s.id === gender)?.label.toLowerCase()} · {TIPOS.find((t) => t.id === abierto)?.label.toLowerCase()} para este producto.\n                    </Notice>\n                    <View style={{ flexDirection: 'row', gap: espaciado.e8, flexWrap: 'wrap' }}>\n                      <GhostButton title=\"Rellenar tallas típicas\" onPress={() => guardar(abierto, gender, tipicas(gender, abierto))} />\n                      <GhostButton title=\"Empezar vacía\" onPress={() => guardar(abierto, gender, [fila('')])} />\n                    </View>\n                  </>\n                ) : (\n                  <>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '700', marginBottom: espaciado.e6 }}>\n                      {rows.length} {rows.length === 1 ? 'talla' : 'tallas'} · medidas en cm{abierto === 'top' || abierto === 'bottom' || abierto === 'dress' ? ' y kg' : ''}\n                    </Text>\n                    {rows.map((r, i) => (\n                      <View key={`${r.sizeLabel}-${i}`} style={[styles.fila, { borderBottomColor: alpha(colors.border, 0.6) }]}>\n                        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n                          <TextInput\n                            value={r.sizeLabel}\n                            onChangeText={(t) => guardar(abierto, gender, rows.map((x, j) => (j === i ? { ...x, sizeLabel: t } : x)), chart?.notes)}\n                            placeholder=\"Talla\"\n                            placeholderTextColor={colors.textSecondary}\n                            style={[input, { width: 74, fontWeight: '800' }]}\n                          />\n                          <Pressable\n                            onPress={() => {\n                              const quedan = rows.filter((_, j) => j !== i);\n                              if (!quedan.length) { removeSizeChart(gender, abierto); return; }\n                              guardar(abierto, gender, quedan, chart?.notes);\n                            }}\n                            accessibilityLabel={`Quitar la talla ${r.sizeLabel}`}\n                            hitSlop={8}\n                          >\n                            <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '800' }}>quitar</Text>\n                          </Pressable>\n                        </View>\n                        {campos.map((c) => {\n                          const suf = UNIDAD[c.key] === 'kg' ? 'Kg' : 'Cm';\n                          const kMin = `${c.key}Min${suf}`;\n                          const kMax = `${c.key}Max${suf}`;\n                          return (\n                            <View key={c.key} style={styles.medida}>\n                              <Text style={{ color: colors.textSecondary, fontSize: 10.5, width: 78 }} numberOfLines={1}>\n                                {c.label} ({UNIDAD[c.key]})\n                              </Text>\n                              <TextInput\n                                value={r[kMin] ?? ''}\n                                onChangeText={(t) => guardar(abierto, gender, rows.map((x, j) => (j === i ? { ...x, [kMin]: t.replace(/[^\\d]/g, '') } : x)), chart?.notes)}\n                                keyboardType=\"number-pad\"\n                                placeholder=\"mín\"\n                                placeholderTextColor={colors.textSecondary}\n                                style={[input, styles.mini]}\n                              />\n                              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>–</Text>\n                              <TextInput\n                                value={r[kMax] ?? ''}\n                                onChangeText={(t) => guardar(abierto, gender, rows.map((x, j) => (j === i ? { ...x, [kMax]: t.replace(/[^\\d]/g, '') } : x)), chart?.notes)}\n                                keyboardType=\"number-pad\"\n                                placeholder=\"máx\"\n                                placeholderTextColor={colors.textSecondary}\n                                style={[input, styles.mini]}\n                              />\n                            </View>\n                          );\n                        })}\n                      </View>\n                    ))}\n                    <View style={{ flexDirection: 'row', gap: espaciado.e8, flexWrap: 'wrap', marginTop: espaciado.e8 }}>\n                      <GhostButton title=\"Añadir talla\" onPress={() => guardar(abierto, gender, [...rows, fila('')], chart?.notes)} />\n                      <GhostButton\n                        title={masMedidas ? 'Menos medidas' : 'Más medidas'}\n                        onPress={() => setMasMedidas((v) => !v)}\n                      />\n                      <GhostButton\n                        title=\"Borrar tabla\"\n                        onPress={() => Alert.alert('Borrar la tabla', 'La tabla de tallas de este producto se borra. El asistente dejará de recomendar talla hasta que la vuelvas a poner.', [\n                          { text: 'Cancelar', style: 'cancel' },\n                          { text: 'Borrar', style: 'destructive', onPress: () => removeSizeChart(gender, abierto) },\n                        ])}\n                      />\n                    </View>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e8, lineHeight: 16 }}>\n                      Valores orientativos: revísalos con tu prenda.\n                    </Text>\n                  </>\n                )}\n              </View>\n            );\n          })()}\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  input: { borderWidth: 1, borderRadius: 9, paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e7, fontSize: tipografia.caption },\n  mini: { width: 58 },\n  card: { borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginTop: espaciado.e10 },\n  fila: { borderBottomWidth: StyleSheet.hairlineWidth, paddingVertical: espaciado.e8 },\n  medida: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e5 },\n});\n","/**\n * publish/StepPreview.tsx — paso final: VISTA PREVIA (Parte 34).\n *\n * Idea del dueño que se adopta tal cual (ver antes de publicar) con los arreglos:\n *   · el precio se muestra con `lbXaf()` (toda la app usa XAF) y **no** el de la\n *     primera opción como si fuera el del producto;\n *   · nada de `toLocaleString` suelto ni de tokens inexistentes.\n * El envío real lo hace la pantalla anfitriona (con clave de idempotencia estable).\n */\nimport React from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { alpha, espaciado, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../../../api/config';\nimport { lbXaf } from '../../../constants/lifebook';\nimport { LB_CONDITIONS, LB_PAY_STATUS_LABEL, lbCoverageLabel, lbPayLabel, lbPriceLabel, lbServiceLabel, lbTransportLabel } from '../../../constants/commerce';\nimport { usePublishStore } from '../../../state/commercePublish';\nimport type { LbCategory, LbShop } from '../../../api/commerce';\nimport { Notice, StepBlock, SummaryRow } from './PublishParts';\n\nexport default function StepPreview({ categories, shop }: { categories: LbCategory[]; shop: LbShop | null }) {\n  const { colors } = useTheme();\n  const form = usePublishStore((s) => s.form);\n\n  const root = categories.find((c) => c.serviceType === form.serviceType);\n  const sub = root?.children?.find((c) => c.id === form.categoryId);\n  const condicion = LB_CONDITIONS.find((c) => c.id === form.condition)?.label ?? form.condition;\n\n  return (\n    <View>\n      {/* Mini ficha */}\n      <View style={[styles.card, { backgroundColor: colors.card, borderColor: alpha(colors.border, 0.6) }]}>\n        {form.media[0] ? (\n          <Image\n            source={absUrl(form.media[0].url)}\n            style={styles.cover}\n            contentFit=\"cover\"\n            cachePolicy=\"memory-disk\"\n            transition={0}\n          />\n        ) : (\n          <View style={[styles.cover, styles.coverEmpty, { backgroundColor: alpha(colors.primary, 0.08) }]}>\n            <Text style={{ fontSize: 30 }}>📦</Text>\n          </View>\n        )}\n        <View style={{ padding: espaciado.e12 }}>\n          <Text style={{ color: colors.primary, fontSize: 19, fontWeight: '900' }}>\n            {lbPriceLabel(form.priceMode === 'on_request' ? null : Number(form.price.replace(/\\D/g, '')), form.priceMode, lbXaf)}\n          </Text>\n          <Text style={{ color: colors.textPrimary, fontSize: 15.5, fontWeight: '800', marginTop: espaciado.e4 }} numberOfLines={3}>\n            {form.title || '(sin título)'}\n          </Text>\n          {form.shortDescription ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }} numberOfLines={2}>\n              {form.shortDescription}\n            </Text>\n          ) : null}\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e6 }}>\n            {[lbServiceLabel(form.serviceType), sub?.name, form.city, form.barrio].filter(Boolean).join(' · ')}\n          </Text>\n        </View>\n      </View>\n\n      <StepBlock title=\"Resumen\">\n        <SummaryRow label=\"Tipo\" value={lbServiceLabel(form.serviceType)} />\n        <SummaryRow label=\"Categoría\" value={sub?.name ?? (root ? `${root.name} (sin subcategoría)` : '—')} />\n        <SummaryRow label=\"Precio\" value={form.priceMode === 'on_request' ? 'A consultar' : lbXaf(Number(form.price.replace(/\\D/g, '')) || 0)} />\n        <SummaryRow label=\"Antes\" value={Number(form.oldPrice.replace(/\\D/g, '')) > 0 ? lbXaf(Number(form.oldPrice.replace(/\\D/g, ''))) : 'Sin descuento'} />\n        <SummaryRow label=\"Estado\" value={condicion} />\n        <SummaryRow\n          label=\"Disponibilidad\"\n          value={form.stockMode === 'unlimited' ? 'Sin límite'\n            : form.stockMode === 'on_request' ? 'Bajo pedido'\n              : `${form.stockQuantity || 0} unidades (${form.stockMode === 'exact' ? 'exactas' : 'aproximadas'})`}\n        />\n        <SummaryRow label=\"Fotos\" value={`${form.media.length}`} />\n        <SummaryRow label=\"Opciones\" value={form.variants.length ? form.variants.map((v) => v.name).join(', ') : 'Ninguna'} />\n        <SummaryRow label=\"Detalles\" value={form.attributes.length ? `${form.attributes.length} rellenados` : 'Ninguno'} />\n        <SummaryRow label=\"Entrega\" value={form.coverage.map(lbCoverageLabel).join(' · ') || 'Sin indicar'} />\n        <SummaryRow label=\"Medios\" value={form.transports.map(lbTransportLabel).join(' · ') || 'Sin indicar'} />\n        <SummaryRow label=\"Coste de envío\" value={Number(form.deliveryCost.replace(/\\D/g, '')) > 0 ? lbXaf(Number(form.deliveryCost.replace(/\\D/g, ''))) : 'A consultar'} />\n      </StepBlock>\n\n      {shop ? (\n        <StepBlock title=\"Pagos que acepta tu tienda\" hint=\"Se configuran una vez y valen para todo lo que publiques.\">\n          {shop.paymentMethods.map((pm) => (\n            <SummaryRow\n              key={pm.method}\n              label={lbPayLabel(pm.method)}\n              value={pm.status === 'active' ? 'Disponible' : (LB_PAY_STATUS_LABEL[pm.status] ?? pm.status)}\n            />\n          ))}\n        </StepBlock>\n      ) : null}\n\n      <Notice tone=\"ok\">\n        Al publicar, tu publicación entra <Text style={{ fontWeight: '900' }}>en revisión</Text>. El equipo la aprueba y\n        entonces aparece en el catálogo; recibirás el aviso en Mensajes.\n      </Notice>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  card: { borderWidth: StyleSheet.hairlineWidth, borderRadius: 14, overflow: 'hidden', marginBottom: espaciado.e16 },\n  cover: { width: '100%', height: 190 },\n  coverEmpty: { alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * app/lifebook-shop/[id].tsx — TIENDA de un vendedor (Parte 33).\n *\n * Pestañas simples: Productos · Servicios · Información (con valoración,\n * seguidores, entrega y métodos de pago reales). El botón principal cambia\n * según lo que venda la tienda, como pide la hoja de ruta.\n */\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { ActivityIndicator, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, brand, espaciado, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport {\n  ArrowLeft, MapPin, MessageCircle, Package, ShieldCheck, Store, Truck, Wrench,\n} from 'lucide-react-native';\nimport { AuthGate } from '../../core/AuthGate';\nimport { absUrl } from '../../api/config';\nimport { messagesApi } from '../../api/messages';\nimport { commerceApi, type LbProductCard, type LbShop } from '../../api/commerce';\nimport { lbXaf } from '../../constants/lifebook';\nimport {\n  LB_PAY_STATUS_LABEL, LB_VERIFICATION, lbCoverageLabel, lbPayLabel,\n  lbPriceLabel, lbRegionLabel, lbTransportLabel,\n} from '../../constants/commerce';\nimport { ir as irSeguro } from '../../constants/rutas';\n\ntype Tab = 'products' | 'services' | 'info';\n\nexport default function LifeBookShopScreen() {\n  return (\n    <AuthGate>\n      <ShopContent />\n    </AuthGate>\n  );\n}\n\nfunction ShopContent() {\n  const { id, product } = useLocalSearchParams<{ id: string; product?: string }>();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const [shop, setShop] = useState<LbShop | null>(null);\n  const [items, setItems] = useState<LbProductCard[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [tab, setTab] = useState<Tab>('products');\n  const [following, setFollowing] = useState(false);\n  /** ¿Es mi propia tienda? (para ofrecer «Administrar» en vez de «Seguir»). */\n  const [esMia, setEsMia] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const mounted = useRef(true);\n  /**\n   * TANDA A — POSICIONADO EN UN PRODUCTO. Cuando se llega desde la tarjeta del perfil\n   * (`?product=<id>`), la tienda no se abre por arriba: baja hasta ese producto y lo deja\n   * marcado, porque es un ATAJO (el visitante ya ha elegido qué mirar), no un destino final.\n   */\n  const listaRef = useRef<FlatList<LbProductCard>>(null);\n  const [resaltado, setResaltado] = useState<string | null>(null);\n  const [yaPosicionado, setYaPosicionado] = useState(false);\n  /** Evita pedir dos veces el mismo producto que no venía en la página cargada. */\n  const trayendoRef = useRef<string | null>(null);\n\n  const load = useCallback(async () => {\n    if (!id) return;\n    try {\n      const [{ shop: s }, page] = await Promise.all([\n        commerceApi.shop(String(id)),\n        commerceApi.shopProducts(String(id), { limit: 30 }),\n      ]);\n      if (!mounted.current) return;\n      setShop(s);\n      setFollowing(!!s.followedByMe);\n      setItems((page as { items: LbProductCard[] }).items ?? []);\n      // Sesión opcional: sin sesión (o sin tienda) simplemente no es mía.\n      commerceApi.myShop()\n        .then(({ shop: mia }) => { if (mounted.current) setEsMia(!!mia && mia.id === s.id); })\n        .catch(() => { if (mounted.current) setEsMia(false); });\n    } catch {\n      /* la ficha avisa con el estado vacío */\n    } finally {\n      if (mounted.current) setLoading(false);\n    }\n  }, [id]);\n\n  useEffect(() => {\n    mounted.current = true;\n    load();\n    return () => { mounted.current = false; };\n  }, [load]);\n\n  const productos = useMemo(() => items.filter((p) => p.serviceType === 'physical' || p.serviceType === 'food'), [items]);\n  const servicios = useMemo(() => items.filter((p) => p.serviceType !== 'physical' && p.serviceType !== 'food'), [items]);\n  const visibles = tab === 'services' ? servicios : productos;\n\n  /**\n   * TANDA A — bajar hasta el producto por el que se ha entrado. Se hace UNA vez, cuando la\n   * lista ya tiene datos. Si el producto no está en la pestaña que se está viendo (p. ej. es\n   * un servicio y se ve «Productos»), se cambia de pestaña para que aparezca: si no, el\n   * atajo llevaría a una pantalla donde el producto no está.\n   */\n  useEffect(() => {\n    if (!product || yaPosicionado || !items.length) return;\n    const enProductos = productos.findIndex((p) => p.id === product);\n    const enServicios = servicios.findIndex((p) => p.id === product);\n    if (enProductos < 0 && enServicios < 0) {\n      /**\n       * NO ESTÁ EN LO CARGADO. Esta tienda tiene 58 productos y la pantalla pide 30, así que\n       * un producto antiguo puede no venir en la primera página: el atajo desde el perfil\n       * fallaba en silencio (medido con el producto MÁS ANTIGUO: la tienda se abría arriba y\n       * sin marcar nada). Se pide ESE producto y se trae a la vista, marcado, en vez de dejar\n       * al visitante buscándolo a mano.\n       */\n      if (trayendoRef.current === product) return;\n      trayendoRef.current = product;\n      commerceApi.product(String(product))\n        .then((res) => {\n          /* OJO con la forma: la ficha NO viene suelta, viene envuelta (`{ product: … }`).\n             Leerla mal fue un fallo real de esta función: comparaba `res.shopId`, que es\n             `undefined`, y el atajo no traía nada. */\n          const envuelto = res as unknown as { product?: LbProductCard };\n          const p = envuelto.product ?? (res as unknown as LbProductCard | null);\n          if (!p || String((p as { shopId?: string }).shopId) !== String(id)) return;\n          // La ficha trae `media` pero no `coverUrl` (lo comprobé contra el API): se usa la\n          // primera foto para que la miniatura no salga vacía.\n          const fila = {\n            ...p,\n            coverUrl: (p as { coverUrl?: string | null }).coverUrl\n              ?? (Array.isArray(p.media) ? p.media[0]?.url ?? null : null),\n          } as LbProductCard;\n          setItems((prev) => (prev.some((x) => x.id === fila.id) ? prev : [fila, ...prev]));\n        })\n        .catch(() => { /* si no se puede traer, la tienda se queda como está */ });\n      return;\n    }\n    const destino = enProductos >= 0 ? 'products' : 'services';\n    if (tab !== destino) { setTab(destino as Tab); return; }\n    const idx = enProductos >= 0 ? enProductos : enServicios;\n    setResaltado(String(product));\n    setYaPosicionado(true);\n    // Se espera un pelo a que la lista pinte la fila; si el índice aún no está medido,\n    // FlatList avisa por `onScrollToIndexFailed` y allí se corrige.\n    const t = setTimeout(() => {\n      listaRef.current?.scrollToIndex({ index: idx, animated: true, viewPosition: 0.25 });\n    }, 350);\n    return () => clearTimeout(t);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [product, items, productos, servicios, tab, yaPosicionado]);\n\n  const toggleFollow = async () => {\n    if (!shop || busy) return;\n    setBusy(true);\n    const before = following;\n    setFollowing(!before);\n    try {\n      const res = await commerceApi.toggleFollow(shop.id);\n      setFollowing(res.following);\n    } catch {\n      setFollowing(before);\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const contactar = async () => {\n    if (!shop?.owner) return;\n    setBusy(true);\n    try {\n      const conv = await messagesApi.open(shop.owner.id);\n      router.push({\n        pathname: '/lifebook-chat/[id]',\n        params: { id: conv.id, name: conv.peer.name ?? shop.name, peerId: shop.owner.id, draft: `Hola, vi tu tienda «${shop.name}» y quería preguntar…` },\n      } as never);\n    } catch {\n      /* silencioso */\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  if (loading) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  if (!shop) {\n    return (\n      <View style={[styles.center, { backgroundColor: colors.background, padding: espaciado.e24, gap: espaciado.e12 }]}>\n        <Store size={40} color={alpha(colors.primary, 0.4)} />\n        <Text style={{ color: colors.textPrimary, fontWeight: '800' }}>Esta tienda no está disponible</Text>\n        <GhostButton title=\"Volver\" onPress={() => router.back()} />\n      </View>\n    );\n  }\n\n  const nivel = LB_VERIFICATION[shop.verificationLevel] ?? LB_VERIFICATION.basic;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <FlatList\n        ref={listaRef}\n        data={tab === 'info' ? [] : visibles}\n        keyExtractor={(p) => p.id}\n        numColumns={2}\n        columnWrapperStyle={{ gap: espaciado.e10, paddingHorizontal: espaciado.e14 }}\n        contentContainerStyle={{ paddingBottom: insets.bottom + 100, gap: espaciado.e12 }}\n        showsVerticalScrollIndicator={false}\n        /* Si el índice aún no está medido (fila alta, recién pintada), FlatList avisa: se\n           corrige bajando a ojo, para que el atajo nunca deje al visitante arriba del todo. */\n        onScrollToIndexFailed={(info) => {\n          setTimeout(() => {\n            listaRef.current?.scrollToOffset({ offset: Math.max(0, info.averageItemLength * info.index), animated: true });\n          }, 250);\n        }}\n        ListHeaderComponent={\n          <View>\n            {/* ── Portada y cabecera ── */}\n            <View style={[styles.cover, { backgroundColor: colors.surface }]}>\n              {shop.coverUrl ? (\n                <Image source={absUrl(shop.coverUrl)} style={StyleSheet.absoluteFill} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n              ) : null}\n              <View style={[StyleSheet.absoluteFill, { backgroundColor: 'rgba(0,0,0,0.35)' }]} />\n              <Pressable\n                onPress={() => router.back()}\n                hitSlop={10}\n                accessibilityLabel=\"Volver\"\n                style={[styles.backBtn, { top: insets.top + 10 }]}\n              >\n                <ArrowLeft size={20} color={brand.white} />\n              </Pressable>\n            </View>\n\n            <View style={{ paddingHorizontal: espaciado.e16, marginTop: -34 }}>\n              <View style={[styles.logoWrap, { borderColor: colors.background, backgroundColor: colors.surface }]}>\n                {shop.logoUrl ? (\n                  <Image source={absUrl(shop.logoUrl)} style={styles.logo} contentFit=\"cover\" cachePolicy=\"memory-disk\" transition={0} />\n                ) : (\n                  <View style={[styles.logo, { alignItems: 'center', justifyContent: 'center' }]}>\n                    <Store size={26} color={colors.primary} />\n                  </View>\n                )}\n              </View>\n\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e10 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: 18, fontWeight: '900', flex: 1 }} numberOfLines={1}>\n                  {shop.name}\n                </Text>\n                {shop.isVerified ? <ShieldCheck size={16} color={colors.success} /> : null}\n              </View>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e2 }}>\n                {nivel.icon} {nivel.label}\n                {shop.ecomerse ? ' · Tienda Ecomerse' : ''}\n              </Text>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, marginTop: espaciado.e6, flexWrap: 'wrap' }}>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                  {[shop.city, shop.barrio, lbRegionLabel(shop.region)].filter(Boolean).join(' · ')}\n                </Text>\n                {shop.ratingCount > 0 ? (\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>★ {shop.rating.toFixed(1)} ({shop.ratingCount})</Text>\n                ) : null}\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{shop.stats?.followers ?? shop.followersCount} seguidores</Text>\n              </View>\n              {shop.description ? (\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, marginTop: espaciado.e8, lineHeight: 19 }}>{shop.description}</Text>\n              ) : null}\n\n              {/* ── Acciones ── */}\n              <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n                {esMia ? (\n                  // Parte 39: si la tienda es tuya, lo que quieres es administrarla.\n                  <View style={{ flex: 1 }}>\n                    <PrimaryButton title=\"Administrar mi tienda\" onPress={() => irSeguro.libre('/lifebook-merchant')} />\n                  </View>\n                ) : (\n                  <View style={{ flex: 1 }}>\n                    <PrimaryButton\n                      title={shop.followedByMe || following ? 'Siguiendo' : 'Seguir tienda'}\n                      loading={busy}\n                      onPress={toggleFollow}\n                    />\n                  </View>\n                )}\n                <View style={{ flex: 1 }}>\n                  <GhostButton title=\"Chat\" onPress={contactar} />\n                </View>\n              </View>\n\n              {/* ── Pestañas ── */}\n              <View style={[styles.tabs, { borderBottomColor: alpha(colors.border, 0.6) }]}>\n                {([\n                  { id: 'products' as Tab, label: `Productos${productos.length ? ` (${productos.length})` : ''}` },\n                  { id: 'services' as Tab, label: `Servicios${servicios.length ? ` (${servicios.length})` : ''}` },\n                  { id: 'info' as Tab, label: 'Información' },\n                ]).map((t) => {\n                  const active = tab === t.id;\n                  return (\n                    <Pressable key={t.id} onPress={() => setTab(t.id)} accessibilityRole=\"tab\" accessibilityState={{ selected: active }} style={styles.tab}>\n                      <Text style={{ color: active ? colors.textPrimary : colors.textSecondary, fontWeight: active ? '900' : '600', fontSize: tipografia.body }}>\n                        {t.label}\n                      </Text>\n                      {active ? <View style={[styles.tabLine, { backgroundColor: colors.primary }]} /> : null}\n                    </Pressable>\n                  );\n                })}\n              </View>\n            </View>\n\n            {/* ── Información ── */}\n            {tab === 'info' ? (\n              <View style={{ paddingHorizontal: espaciado.e16, paddingTop: espaciado.e14 }}>\n                {shop.addressReference ? (\n                  <InfoRow colors={colors} icon={<MapPin size={16} color={colors.primary} />} text={shop.addressReference} />\n                ) : null}\n                {shop.shippingPolicies.map((sp) => (\n                  <InfoRow\n                    key={sp.id}\n                    colors={colors}\n                    icon={<Truck size={16} color={colors.primary} />}\n                    text={`${sp.name} · ${sp.coverage.map(lbCoverageLabel).join(' / ') || 'sin cobertura indicada'}${\n                      sp.transportModes.length ? ` · ${sp.transportModes.map(lbTransportLabel).join(', ')}` : ''\n                    }${sp.costMode === 'on_request' ? ' · coste a consultar' : ` · desde ${lbXaf(sp.baseCostXaf)}`}`}\n                  />\n                ))}\n                <View style={{ marginTop: espaciado.e8 }}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body, marginBottom: espaciado.e6 }}>Pagos aceptados</Text>\n                  {shop.paymentMethods.map((pm) => (\n                    <Text key={pm.method} style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e3 }}>\n                      · {lbPayLabel(pm.method)}{pm.status !== 'active' ? ` (${LB_PAY_STATUS_LABEL[pm.status] ?? pm.status})` : ''}\n                    </Text>\n                  ))}\n                </View>\n                <Pressable\n                  onPress={() => shop.owner && irSeguro.libre('/lifebook-user', { id: shop.owner.id })}\n                  accessibilityLabel=\"Ver el perfil del vendedor\"\n                  style={{ marginTop: espaciado.e16 }}\n                >\n                  <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.caption }}>Ver el perfil de {shop.owner?.name ?? 'el vendedor'} →</Text>\n                </Pressable>\n              </View>\n            ) : null}\n          </View>\n        }\n        ListEmptyComponent={\n          tab === 'info' ? null : (\n            <View style={{ alignItems: 'center', paddingTop: 40, gap: espaciado.e8 }}>\n              {tab === 'services' ? <Wrench size={34} color={alpha(colors.primary, 0.4)} /> : <Package size={34} color={alpha(colors.primary, 0.4)} />}\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n                {tab === 'services' ? 'Esta tienda aún no ofrece servicios.' : 'Esta tienda aún no tiene productos publicados.'}\n              </Text>\n            </View>\n          )\n        }\n        renderItem={({ item }) => (\n          <Pressable\n            onPress={() => irSeguro.libre('/lifebook-product/[id]', { id: item.id })}\n            accessibilityLabel={item.title}\n            style={[styles.card, {\n              backgroundColor: colors.card,\n              // TANDA A: si se ha llegado por un atajo a este producto, se marca para que el\n              // visitante vea DE CUÁL venía sin tener que adivinarlo.\n              borderColor: resaltado === item.id ? colors.primary : alpha(colors.border, 0.5),\n              borderWidth: resaltado === item.id ? 2 : 1,\n            }]}\n          >\n            {item.coverUrl ? (\n              <Image\n                source={absUrl(item.coverUrl)}\n                style={styles.cardImg}\n                contentFit=\"cover\"\n                cachePolicy=\"memory-disk\"\n                recyclingKey={item.id}\n                transition={0}\n              />\n            ) : (\n              <View style={[styles.cardImg, { backgroundColor: alpha(colors.primary, 0.08), alignItems: 'center', justifyContent: 'center' }]}>\n                <Package size={22} color={alpha(colors.primary, 0.5)} />\n              </View>\n            )}\n            <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6 }}>\n              {item.title}\n            </Text>\n            {/* Marca visible del atajo: si se ha entrado desde la tarjeta del perfil, el\n                visitante ve CUÁL de todos los productos era el que tocó. Sin esto solo había\n                un borde de color, que no se puede ni leer con un lector de pantalla (y que yo\n                tampoco podía comprobar en el teléfono). */}\n            {resaltado === item.id ? (\n              <Text style={{ color: colors.primary, fontSize: 10.5, fontWeight: '900', marginTop: espaciado.e2 }}>\n                📍 Es el que tocaste\n              </Text>\n            ) : null}\n            <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e3 }}>\n              {lbPriceLabel(item.priceXaf, item.priceMode, lbXaf)}\n            </Text>\n            <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\n              {[item.originCity, item.shipsInternational ? 'envía al extranjero' : null].filter(Boolean).join(' · ')}\n            </Text>\n            {/* «X vendidos»: el dato ya venía (`salesCount`) y no se pintaba. Solo si hay\n                ventas: un «0 vendidos» en la rejilla de la tienda ahuyenta. */}\n            {item.salesCount > 0 ? (\n              <Text style={{ color: colors.textSecondary, fontSize: 10.5, fontWeight: '700', marginTop: 1 }}>\n                {item.salesCount} vendido{item.salesCount === 1 ? '' : 's'}\n              </Text>\n            ) : null}\n          </Pressable>\n        )}\n      />\n    </View>\n  );\n}\n\nfunction InfoRow({ colors, icon, text }: { colors: any; icon: React.ReactNode; text: string }) {\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'flex-start', marginBottom: espaciado.e8 }}>\n      {icon}\n      <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, marginLeft: espaciado.e8, flex: 1, lineHeight: 18 }}>{text}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  cover: { height: 150, overflow: 'hidden' },\n  backBtn: {\n    position: 'absolute', left: 14, width: 34, height: 34, borderRadius: 17,\n    backgroundColor: 'rgba(0,0,0,0.35)', alignItems: 'center', justifyContent: 'center',\n  },\n  logoWrap: { width: 74, height: 74, borderRadius: 37, borderWidth: 3, overflow: 'hidden' },\n  logo: { width: '100%', height: '100%', borderRadius: 37 },\n  tabs: { flexDirection: 'row', gap: espaciado.e18, borderBottomWidth: StyleSheet.hairlineWidth, marginTop: espaciado.e16 },\n  tab: { paddingBottom: espaciado.e8, alignItems: 'center' },\n  tabLine: { height: 2.5, width: 26, borderRadius: 2, marginTop: espaciado.e5 },\n  card: { flex: 1, borderRadius: radios.md, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e8, maxWidth: '50%' },\n  cardImg: { width: '100%', height: 120, borderRadius: radios.sm },\n});\n","/**\n * Life Book — TIENDA de un vendedor (/lifebook-store?sellerId=…).\n * Cabecera del vendedor (avatar, bio, ciudad, ★, badge Ecomerse), botones\n * Seguir / Contactar / Ver en Ecomerse, y sus productos en venta (grid 2 col).\n */\nimport React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, FlatList, Image, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useWindowDimensions } from 'react-native';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, BadgeCheck, MapPin, MessageCircle, Star, Store } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookStoreApi, lifebookChatApi, toPostCard, type LbPostBase, type LbStorePage } from '../api/lifebook';\nimport { PostCard } from '../components/lifebook/PostCard';\nimport FloatingFooter, { DOCK_BODY_H } from '../components/FloatingFooter';\nimport { useAppDock } from '../core/useAppDock';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport default function StoreScreen() {\n  return (\n    <AuthGate>\n      <StoreContent />\n    </AuthGate>\n  );\n}\n\nfunction StoreContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { width } = useWindowDimensions();\n  const { sellerId } = useLocalSearchParams<{ sellerId?: string }>();\n  const GAP = 12;\n  const cellW = (width - GAP * 3) / 2;\n  const [page, setPage] = useState<LbStorePage | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busyFollow, setBusyFollow] = useState(false);\n  const dock = useAppDock();\n\n  useEffect(() => {\n    if (!sellerId) { setError('Falta el vendedor'); return; }\n    lifebookStoreApi.page(sellerId).then(setPage).catch(() => setError('No se pudo cargar la tienda'));\n  }, [sellerId]);\n\n  const toggleFollow = async () => {\n    if (!page || busyFollow || page.store.relation.isSelf) return;\n    setBusyFollow(true);\n    const was = page.store.relation.isFollowing;\n    setPage({ ...page, store: { ...page.store, relation: { ...page.store.relation, isFollowing: !was } } });\n    try {\n      const { lifebookApi } = await import('../api/lifebook');\n      await (was ? lifebookApi.unfollow(page.store.id) : lifebookApi.follow(page.store.id));\n    } catch {\n      setPage({ ...page, store: { ...page.store, relation: { ...page.store.relation, isFollowing: was } } });\n    } finally { setBusyFollow(false); }\n  };\n\n  const contact = async () => {\n    if (!page) return;\n    try {\n      const conv = await lifebookChatApi.open(page.store.id);\n      irSeguro.libre('/lifebook-chat/[id]', { id: conv.id, name: page.store.fullName ?? 'Tienda' });\n    } catch { /* sin chat */ }\n  };\n\n  if (error || !sellerId) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background }}>\n        <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n          <Pressable onPress={() => router.back()} hitSlop={12}><ArrowLeft size={22} color={colors.textPrimary} /></Pressable>\n          <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Tienda</Text>\n        </View>\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 }}>\n          <Text style={{ color: colors.textPrimary, fontWeight: '800' }}>{error ?? 'Tienda'}</Text>\n        </View>\n      </View>\n    );\n  }\n  if (!page) {\n    return <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.background }}><ActivityIndicator color={colors.primary} /></View>;\n  }\n\n  const s = page.store;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}><ArrowLeft size={22} color={colors.textPrimary} /></Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Tienda</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <FlatList\n        data={page.sales}\n        keyExtractor={(p: LbPostBase) => p.id}\n        numColumns={2}\n        columnWrapperStyle={{ paddingHorizontal: GAP, gap: GAP }}\n        contentContainerStyle={{ paddingTop: espaciado.e4, paddingBottom: DOCK_BODY_H + insets.bottom + 24, flexGrow: 1, gap: GAP }}\n        ListHeaderComponent={\n          <View style={{ padding: espaciado.e16, paddingBottom: espaciado.e6 }}>\n            <View style={{ flexDirection: 'row', gap: espaciado.e12, alignItems: 'center' }}>\n              {absUrl(s.avatarUrl) ? (\n                <Image source={{ uri: absUrl(s.avatarUrl) }} style={[styles.logo, { backgroundColor: colors.surface }]} />\n              ) : (\n                <View style={[styles.logo, { backgroundColor: alpha(colors.secondary, 0.15), alignItems: 'center', justifyContent: 'center' }]}>\n                  <Text style={{ color: colors.secondary, fontSize: tipografia.display, fontWeight: '900' }}>{(s.fullName ?? '?').charAt(0).toUpperCase()}</Text>\n                </View>\n              )}\n              <View style={{ flex: 1 }}>\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5 }}>\n                  <Text style={{ color: colors.textPrimary, fontSize: 18, fontWeight: '900', flexShrink: 1 }}>{s.fullName ?? 'Tienda'}</Text>\n                  <BadgeCheck size={17} color={brand.primary} fill={brand.primary} stroke={brand.white} strokeWidth={2.5} />\n                </View>\n                {s.city ? (\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginTop: espaciado.e2 }}>\n                    <MapPin size={11} color={colors.textSecondary} />\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{s.city}{s.country ? ` · ${s.country}` : ''}</Text>\n                  </View>\n                ) : null}\n                {s.ratingAvg != null && s.ratingAvg > 0 && (\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginTop: espaciado.e2 }}>\n                    <Star size={12} color={brand.warning} fill={brand.warning} />\n                    <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.caption }}>{s.ratingAvg.toFixed(1)}</Text>\n                  </View>\n                )}\n              </View>\n            </View>\n\n            {s.bio ? <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e10, lineHeight: 19 }}>{s.bio}</Text> : null}\n\n            {s.ecomerse && (\n              <View style={[styles.ecomerseChip, { backgroundColor: alpha(colors.secondary, 0.12) }]}>\n                <Store size={13} color={colors.secondary} />\n                <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '900' }}>Tienda Ecomerse verificada · productos en el Mercado</Text>\n              </View>\n            )}\n\n            <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12 }}>\n              {!s.relation.isSelf && (\n                <Pressable onPress={toggleFollow} style={[styles.btn, { flex: 1, backgroundColor: s.relation.isFollowing ? colors.surface : colors.primary, borderColor: s.relation.isFollowing ? colors.border : colors.primary, borderWidth: 1 }]}>\n                  {busyFollow ? <ActivityIndicator size=\"small\" color={s.relation.isFollowing ? colors.textPrimary : brand.white} /> : (\n                    <Text style={{ color: s.relation.isFollowing ? colors.textPrimary : brand.white, fontWeight: '900', fontSize: tipografia.body }}>\n                      {s.relation.isFollowing ? 'Siguiendo ✓' : '+ Seguir'}\n                    </Text>\n                  )}\n                </Pressable>\n              )}\n              <Pressable onPress={contact} style={[styles.btn, { flex: 1, backgroundColor: colors.surface, borderColor: colors.border, borderWidth: 1 }]}>\n                <MessageCircle size={15} color={colors.textPrimary} />\n                <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>Contactar</Text>\n              </Pressable>\n            </View>\n\n            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: espaciado.e18 }}>\n              <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>Productos</Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>{page.sales.length} en venta</Text>\n            </View>\n          </View>\n        }\n        ListEmptyComponent={\n          <View style={{ alignItems: 'center', paddingTop: espaciado.e30, gap: espaciado.e4 }}>\n            <Text style={{ color: colors.textPrimary, fontWeight: '800' }}>Esta tienda aún no tiene productos activos.</Text>\n          </View>\n        }\n        renderItem={({ item }) => (\n          <PostCard post={toPostCard(item)} width={cellW} onPress={(id) => irSeguro.libre('/lifebook-post/[id]', { id })} />\n        )}\n      />\n\n      <FloatingFooter onNavigate={dock} showUnreadBadge />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: 19, fontWeight: '900', flex: 1 },\n  logo: { width: 68, height: 68, borderRadius: radios.lg },\n  ecomerseChip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, marginTop: espaciado.e12, alignSelf: 'flex-start' },\n  btn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6, borderRadius: radios.full, paddingVertical: espaciado.e11 },\n});\n\n","/**\n * Life Book — PERFIL PÚBLICO (/lifebook-user?id=…).\n * Cabecera (portada + identidad), contadores, badges de rol verificado,\n * bio/enlaces, Seguir/Dejando de seguir (o Editar perfil si es propio) y\n * pestañas de contenido (Notas · Ventas · Todo) en grid de 2 columnas.\n * DISEÑO-UX-LIFEBOOK-PERFIL.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, FlatList, Image, Linking, Modal, Pressable, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport Svg, { Defs, LinearGradient as SvgLinearGradient, Rect, Stop } from 'react-native-svg';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport {\n  ArrowLeft, BadgeCheck, Bookmark, Building2, CarTaxiFront, ChevronRight, Heart, Home, MoreHorizontal,\n  MapPin, Package, PenSquare, Search, Star, Store, Utensils, Users,\n} from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { absUrl } from '../api/config';\nimport { lifebookApi, lifebookBlocksApi, lifebookChatApi, toPostCard, type LbGroupCard, type LbPostBase, type LbProfile } from '../api/lifebook';\nimport { gruposEnlacesApi } from '../api/lifebookGrupos';\nimport type { LbGroupCardConEnlace } from '../api/lifebookGrupos';\nimport { tiendaApi, type LbTarjetaDeTienda } from '../api/lifebookTienda';\nimport type { LbProductCard } from '../api/commerce';\nimport { lbXaf } from '../constants/lifebook';\nimport { lbPriceLabel } from '../constants/commerce';\nimport { PostCard } from '../components/lifebook/PostCard';\nimport { formaHoja } from '../components/lifebook/ui/Sheet';\nimport StatusRingAvatar from '../components/status/StatusRingAvatar';\nimport StatusDetailModal from '../components/status/StatusDetailModal';\nimport { statusApi, type UserStatus } from '../api/status';\nimport { useStatusStore } from '../state/statusStore';\nimport { useWindowDimensions } from 'react-native';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { brand } from '@egrouteplan/ui-kit';\n\nexport default function LifeBookUserScreen() {\n  return (\n    <AuthGate>\n      <UserContent />\n    </AuthGate>\n  );\n}\n\nconst VERIFIED_CHIPS: Array<{ key: keyof LbProfile['verified']; label: string; icon: typeof Store; color: string }> = [\n  { key: 'driver', label: 'Conductor', icon: CarTaxiFront, color: brand.primary },\n  { key: 'seller', label: 'Tienda', icon: Store, color: '#E0439A' },\n  { key: 'food', label: 'Restaurante', icon: Utensils, color: brand.secondary },\n  { key: 'work', label: 'Contratante', icon: Building2, color: '#8B5CF6' },\n  { key: 'rental', label: 'Anfitrión', icon: Home, color: brand.success },\n];\n\nfunction UserContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { width } = useWindowDimensions();\n  const GAP = 12;\n  const cellW = (width - GAP * 3) / 2;\n  const { id } = useLocalSearchParams<{ id?: string }>();\n\n  const [profile, setProfile] = useState<LbProfile | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [tab, setTab] = useState('note');\n  const [posts, setPosts] = useState<LbPostBase[]>([]);\n  const [nextCursor, setNextCursor] = useState<string | null>(null);\n  const [loadingPosts, setLoadingPosts] = useState(false);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [busyFollow, setBusyFollow] = useState(false);\n  const [userMenuOpen, setUserMenuOpen] = useState(false);\n  /**\n   * ── EL ESTADO 24 H DE ESTA PERSONA ─────────────────────────────────────────\n   *\n   * Antes **no se veía aquí, y eso convertía el estado en un diario privado**: el editor, el\n   * anillo, la píldora y el modal de historia existían y se pintaban en `/profile`, `/status`,\n   * `/edit-profile` y la cabecera de inicio… **siempre con `myStatus`**, o sea sólo para su\n   * autor. La persona que publicaba un estado no lo enseñaba a nadie: sus seguidores no tenían\n   * ningún sitio donde verlo.\n   *\n   * Lo tenía todo hecho menos el último cable: el servidor ya expone\n   * `GET /mobility/status/users/:userId` («estado visible de un usuario», con la visibilidad ya\n   * filtrada) y el cliente ya tenía `statusApi.userStatus()`. **Nadie lo llamaba.**\n   *\n   * Se usan DOS fuentes a propósito:\n   *  · Si el perfil es el TUYO → el store (`myStatus`), que es el que se actualiza solo al\n   *    publicar o finalizar desde esta misma pantalla.\n   *  · Si es el de otra persona → `statusApi.userStatus()`, que respeta la visibilidad.\n   */\n  const { status: miEstado } = useStatusStore();\n  const [estadoAjeno, setEstadoAjeno] = useState<UserStatus | null>(null);\n  /** `true` mientras el detalle del estado está abierto. */\n  const [estadoOpen, setEstadoOpen] = useState(false);\n  const [blocked, setBlocked] = useState(false);\n\n  const loadProfile = useCallback(async () => {\n    if (!id) { setError('Falta el usuario'); return; }\n    try {\n      setProfile(await lifebookApi.profile(id));\n      lifebookBlocksApi.mine().then((list) => setBlocked(list.some((x) => x.id === id))).catch(() => {});\n    }\n    catch { setError('Usuario no encontrado'); }\n  }, [id]);\n\n  const loadPosts = useCallback(async (type: string, userId: string) => {\n    setLoadingPosts(true);\n    try {\n      const page = await lifebookApi.userPosts(userId, { type: type || undefined, limit: 20 });\n      setPosts(page.posts ?? []);\n      setNextCursor(page.nextCursor ?? null);\n    } catch { /* perfil sin contenido no bloquea */ }\n    finally { setLoadingPosts(false); }\n  }, []);\n\n  useEffect(() => { loadProfile(); }, [loadProfile]);\n  useEffect(() => { if (profile) { setPosts([]); setNextCursor(null); loadPosts(tab, profile.id); } }, [tab, profile, loadPosts]);\n\n  /* El estado 24 h de la persona cuyo perfil se está viendo. Si el perfil es el mío, no se pide:\n     ya está en el store (y así se refresca solo al publicarlo o finalizarlo desde aquí). */\n  useEffect(() => {\n    const esMio = profile?.relation?.isSelf === true;\n    if (!profile?.id || esMio) { setEstadoAjeno(null); return; }\n    let vivo = true;\n    statusApi.userStatus(profile.id)\n      .then((r) => { if (vivo) setEstadoAjeno(r?.status ?? null); })\n      // Si el estado falla, no puede tumbar el perfil: simplemente no hay anillo.\n      .catch(() => { if (vivo) setEstadoAjeno(null); });\n    return () => { vivo = false; };\n  }, [profile?.id, profile?.relation?.isSelf]);\n\n  /**\n   * P3 — ENLACES DE GRUPO. Un enlace de tipo `group` no es una dirección: su valor es el\n   * CÓDIGO del grupo. Para enseñarlo como tarjeta (foto, nombre y cuánta gente hay) hay\n   * que pedir la ficha con ese código, y si el código ya CADUCÓ el servidor lo dice: aquí\n   * se pinta «ya no sirve» en vez de una tarjeta que engañe.\n   *\n   * OJO: esto va ANTES de los `return` tempranos (perfil cargando / error) a propósito.\n   * Los hooks de React tienen que ejecutarse siempre en el mismo orden, y más abajo hay\n   * returns que cortan el render.\n   */\n  const enlacesGrupo = (Array.isArray(profile?.links) ? profile?.links ?? [] : [])\n    .filter(Boolean)\n    .map((l) => (typeof l === 'string' ? { label: l, value: l } : l) as { kind?: string; label?: string; value?: string; pinned?: boolean })\n    .filter((l) => l.kind === 'group' && !!l.value)\n    .map((l) => ({ code: String(l.value).trim().toUpperCase(), label: String(l.label ?? 'Grupo'), pinned: l.pinned === true }));\n  const codigosGrupo = enlacesGrupo.map((g) => g.code).join(',');\n  /**\n   * Cada enlace de grupo, con lo que se ha podido averiguar: `card` (vivo), o `null` con el\n   * MOTIVO por el que no se pudo leer.\n   *\n   * Antes cualquier fallo pintaba «Este enlace ya no sirve», y eso es mentira cuando el\n   * fallo es un corte de red: el enlace estaba bien (comprobado contra el API: respondía\n   * 200) y el perfil lo daba por muerto. Ahora se distingue por el código del error.\n   */\n  const [fichas, setFichas] = useState<Record<string, { card: LbGroupCardConEnlace | null; motivo: string }>>({});\n  /** Sube al tocar un enlace que no se pudo comprobar: vuelve a intentarlo. */\n  const [reintento, setReintento] = useState(0);\n  useEffect(() => {\n    if (!codigosGrupo) return;\n    let vivo = true;\n    void (async () => {\n      for (const g of enlacesGrupo) {\n        try {\n          const f = await gruposEnlacesApi.porCodigo(g.code);\n          if (vivo) setFichas((prev) => (prev[g.code] !== undefined ? prev : { ...prev, [g.code]: { card: f, motivo: '' } }));\n        } catch (e) {\n          const code = String((e as { code?: string })?.code ?? '');\n          const motivo = code === 'INVITE_CODE_INVALID'\n            ? 'Este enlace ya no sirve (ha caducado)'\n            : code === 'INVITE_CODE_NOT_FOUND' || code === 'HTTP_404'\n              ? 'Este enlace ya no existe'\n              // El grupo es privado y quien mira no es miembro: reintentar no arregla nada,\n              // así que NO se ofrece reintento (comprobado contra el API: 403 con el mensaje\n              // «Este grupo es privado: solo se entra por invitación»).\n              : code === 'GROUP_FORBIDDEN' || code === 'HTTP_403'\n                ? 'Grupo privado: hace falta invitación'\n                // Ni caducado, ni borrado, ni privado: no se pudo preguntar (red). Se dice tal\n                // cual y se deja tocar para reintentar, en vez de acusar al enlace de muerto.\n                : 'No se pudo comprobar el enlace · toca para reintentar';\n          if (vivo) setFichas((prev) => (prev[g.code] !== undefined ? prev : { ...prev, [g.code]: { card: null, motivo } }));\n        }\n      }\n    })();\n    return () => { vivo = false; };\n    // Solo cuando cambian los códigos del perfil (o cuando el usuario pide reintentar).\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [codigosGrupo, reintento]);\n\n  /**\n   * TANDA A — LA TARJETA DE LA TIENDA (lo que el perfil enseña entre la bio y los botones).\n   *\n   * Se pide al servidor en UNA petición (`/lifebook/commerce/users/:id/shop-card`) porque\n   * trae de golpe el nombre comercial, el logo, la puntuación y hasta 3 destacados. Si la\n   * persona no tiene tienda, el servidor responde `shop: null` y aquí simplemente no se\n   * pinta NADA: la especificación pide que no quede hueco vacío.\n   *\n   * Va antes de los `return` tempranos por lo mismo que el bloque de grupos: los hooks de\n   * React tienen que ejecutarse siempre en el mismo orden.\n   */\n  const [tienda, setTienda] = useState<LbTarjetaDeTienda | null>(null);\n  useEffect(() => {\n    const uid = profile?.id;\n    if (!uid) return;\n    let vivo = true;\n    tiendaApi.tarjeta(uid)\n      .then((t) => { if (vivo) setTienda(t); })\n      .catch(() => { if (vivo) setTienda(null); });\n    return () => { vivo = false; };\n  }, [profile?.id]);\n\n  /**\n   * TANDA B — EL TAB «PRODUCTOS» DEL PERFIL.\n   *\n   * Lo que pide la especificación: dentro del perfil de una cuenta con tienda, un tab de\n   * productos con una fila de CATEGORÍAS arriba («Todo» primero y seleccionada) y una rejilla\n   * de dos columnas con imagen, nombre (1-2 líneas), precio en color de acento, descripción\n   * corta en gris y «X vendidos» cuando lo hay. Sin puntuación del producto, sin stock y sin\n   * envío: solo lo justo para decidir si se toca o se sigue bajando.\n   *\n   * Se cargan solo cuando se abre el tab (no al abrir el perfil): abrir un perfil no debe\n   * costar la descarga de todo el catálogo de la tienda.\n   */\n  const [prodTienda, setProdTienda] = useState<LbProductCard[]>([]);\n  const [catsTienda, setCatsTienda] = useState<{ id: string; name: string; count: number }[]>([]);\n  const [totalTienda, setTotalTienda] = useState(0);\n  const [catSel, setCatSel] = useState<string | null>(null);   // null = «Todo»\n  const [cargandoProd, setCargandoProd] = useState(false);\n  const [masProd, setMasProd] = useState(false);\n  const [cursorProd, setCursorProd] = useState<string | null>(null);\n  /** «Colección»: mis guardados (solo en mi propio perfil). */\n  const [guardados, setGuardados] = useState<LbProductCard[]>([]);\n  const [cargandoGuardados, setCargandoGuardados] = useState(false);\n\n  const shopId = tienda?.shop?.id ?? null;\n\n  useEffect(() => {\n    if (tab !== 'productos' || !shopId) return;\n    let vivo = true;\n    setCargandoProd(true);\n    (async () => {\n      try {\n        const [cats, pagina] = await Promise.all([\n          tiendaApi.categorias(shopId),\n          tiendaApi.productos(shopId, { categoryId: catSel, limit: 30 }),\n        ]);\n        if (!vivo) return;\n        setCatsTienda(cats.categories ?? []);\n        setTotalTienda(Number(cats.total ?? 0));\n        setProdTienda(pagina.items ?? []);\n        setCursorProd(pagina.nextCursor ?? null);\n      } catch {\n        if (vivo) { setProdTienda([]); setCursorProd(null); }\n      } finally {\n        if (vivo) setCargandoProd(false);\n      }\n    })();\n    return () => { vivo = false; };\n  }, [tab, shopId, catSel]);\n\n  useEffect(() => {\n    if (tab !== 'coleccion' || guardados.length) return;\n    let vivo = true;\n    setCargandoGuardados(true);\n    tiendaApi.guardados()\n      .then((r) => { if (vivo) setGuardados(r.items ?? []); })\n      .catch(() => { if (vivo) setGuardados([]); })\n      .finally(() => { if (vivo) setCargandoGuardados(false); });\n    return () => { vivo = false; };\n  }, [tab, guardados.length]);\n\n  /** «Ver más» de la rejilla de productos (la tienda corta en 30 por página). */\n  const verMasProductos = async () => {\n    if (!shopId || !cursorProd || masProd) return;\n    setMasProd(true);\n    try {\n      const p = await tiendaApi.productos(shopId, { categoryId: catSel, cursor: cursorProd, limit: 30 });\n      setProdTienda((prev) => {\n        const vistos = new Set(prev.map((x) => x.id));\n        return [...prev, ...(p.items ?? []).filter((x) => !vistos.has(x.id))];\n      });\n      setCursorProd(p.nextCursor ?? null);\n    } catch { /* se queda como está */ }\n    finally { setMasProd(false); }\n  };\n\n  const loadMore = async () => {    if (!nextCursor || loadingMore || !profile) return;\n    setLoadingMore(true);\n    try {\n      const page = await lifebookApi.userPosts(profile.id, { type: tab || undefined, cursor: nextCursor, limit: 20 });\n      setPosts((prev) => {\n        const seen = new Set(prev.map((p) => p.id));\n        return [...prev, ...(page.posts ?? []).filter((p) => !seen.has(p.id))];\n      });\n      setNextCursor(page.nextCursor ?? null);\n    } catch { /* silencioso */ }\n    finally { setLoadingMore(false); }\n  };\n\n  const toggleFollow = async () => {\n    if (!profile || busyFollow) return;\n    setBusyFollow(true);\n    const was = profile.relation.isFollowing;\n    setProfile({\n      ...profile,\n      relation: { ...profile.relation, isFollowing: !was },\n      stats: { ...profile.stats, followers: Math.max(0, profile.stats.followers + (was ? -1 : 1)) },\n    });\n    try { await (was ? lifebookApi.unfollow(profile.id) : lifebookApi.follow(profile.id)); }\n    catch {\n      setProfile((p) => p && {\n        ...p,\n        relation: { ...p.relation, isFollowing: was },\n        stats: { ...p.stats, followers: p.stats.followers },\n      });\n    }\n    finally { setBusyFollow(false); }\n  };\n\n  const askToggleBlock = () => {\n    if (!profile) return;\n    Alert.alert(\n      blocked ? 'Desbloquear a este usuario' : 'Bloquear a este usuario',\n      blocked ? 'Volverás a ver su contenido y podrá escribirte.' : 'No verás su contenido ni podrá escribirte. Puedes desbloquearlo cuando quieras desde Ajustes.',\n      [\n        { text: 'Cancelar', style: 'cancel' } as never,\n        {\n          text: blocked ? 'Desbloquear' : 'Bloquear',\n          style: blocked ? 'default' : 'destructive',\n          onPress: async () => {\n            try {\n              if (blocked) await lifebookBlocksApi.unblock(profile.id);\n              else await lifebookBlocksApi.block(profile.id);\n              setBlocked(!blocked);\n              setUserMenuOpen(false);\n            } catch (e) {\n              Alert.alert('Bloquear', e instanceof Error ? e.message : 'No se pudo completar.');\n            }\n          },\n        } as never,\n      ],\n    );\n  };\n\n  const openChat = async () => {\n    if (!profile) return;\n    try {\n      const conv = await lifebookChatApi.open(profile.id);\n      irSeguro.libre('/lifebook-chat/[id]', { id: conv.id, name: profile.fullName ?? 'Chat', peerId: profile.id });\n    } catch { Alert.alert('Mensajes', 'No se pudo abrir la conversación.'); }\n  };\n\n  if (error || !id) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.background }}>\n        <View style={[styles.topBar, { borderBottomColor: colors.border, paddingTop: insets.top + 6 }]}>\n          <Pressable onPress={() => router.back()} hitSlop={12} style={{ paddingVertical: espaciado.e4 }}><ArrowLeft size={22} color={colors.textPrimary} /></Pressable>\n          <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Perfil</Text>\n          <View style={{ width: 22 }} />\n        </View>\n        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: espaciado.e30, gap: espaciado.e6 }}>\n          <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 15 }}>{error ?? 'Perfil'}</Text>\n        </View>\n      </View>\n    );\n  }\n  if (!profile) {\n    return (\n      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.background }}>\n        <ActivityIndicator color={colors.primary} />\n      </View>\n    );\n  }\n\n  const rel = profile.relation;\n  const coverSrc = absUrl(profile.coverPhotoUrl);\n  /** El estado 24 h que se pinta: el MÍO desde el store, el de otra persona desde el endpoint. */\n  const estado = rel.isSelf ? miEstado : estadoAjeno;\n\n  /**\n   * El autor, traducido a la forma que pide el modal de estado (la de `MeProfile`).\n   *\n   * Hay que traducirlo porque **los dos endpoints devuelven tipos distintos para la misma\n   * persona**: `LbProfile` (perfil público) tiene `fullName: string | null` y `role: string | null`,\n   * mientras que `MeProfile` (sesión) los exige no nulos y con el rol acotado a tres valores. Se\n   * hace explícito y sin `as any`: si la traducción no cuadra, el compilador lo dice.\n   */\n  const rolAutor: 'PASSENGER' | 'DRIVER' | 'ADMIN' =\n    profile.role === 'DRIVER' || profile.role === 'ADMIN' ? profile.role : 'PASSENGER';\n  const autorEstado = {\n    id: profile.id,\n    fullName: profile.fullName ?? '',\n    avatarUrl: profile.avatarUrl,\n    role: rolAutor,\n    nameColor: profile.nameColor ?? undefined,\n  };\n  const verifiedList = VERIFIED_CHIPS.filter((v) => profile.verified[v.key]);\n  /**\n   * Un enlace FIJADO por su dueño. Se enseña primero y marcado con 📌.\n   */\n  const esFijado = (l: unknown) => !!(l && typeof l === 'object' && (l as { pinned?: boolean }).pinned === true);\n  /**\n   * Los enlaces, con los FIJADOS primero. Es lo que se pidió para el perfil público:\n   * que cada cual pueda fijar un enlace (por ejemplo el de su grupo) y que quien entra\n   * lo vea arriba, sin tener que buscarlo. El resto de enlaces se quedan igual.\n   */\n  const links = (Array.isArray(profile.links) ? profile.links.filter(Boolean) : [])\n    .slice()\n    .sort((a, b) => Number(esFijado(b)) - Number(esFijado(a)));\n  /* Los enlaces de GRUPO no se pintan como chips (su valor es un código, no una\n     dirección): van en su propia tarjeta, más abajo. */\n  const linksChip = links.filter((l) => (typeof l === 'string' ? true : (l as { kind?: string }).kind !== 'group'));\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      {/* Barra flotante */}\n      <View style={[styles.topBarFloat, { paddingTop: insets.top + 6 }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={[styles.roundIcon, { backgroundColor: 'rgba(0,0,0,0.35)' }]}>\n          <ArrowLeft size={21} color={brand.white} />\n        </Pressable>\n        <View style={{ flex: 1 }} />\n        {rel.isSelf && (\n          <Pressable onPress={() => router.push('/edit-profile')} style={[styles.roundIcon, { backgroundColor: 'rgba(0,0,0,0.35)' }]}>\n            <PenSquare size={18} color={brand.white} />\n          </Pressable>\n        )}\n        {!rel.isSelf && (\n          <Pressable onPress={() => setUserMenuOpen(true)} style={[styles.roundIcon, { backgroundColor: 'rgba(0,0,0,0.35)' }]} accessibilityLabel='Más opciones'>\n            <MoreHorizontal size={20} color={brand.white} />\n          </Pressable>\n        )}\n      </View>\n\n      <FlatList\n        /* TANDA B: la misma rejilla de dos columnas sirve para las publicaciones y para los\n           productos de la tienda; solo cambia de dónde salen los datos y cómo se pinta cada\n           celda. Así el tab «Productos» se ve EXACTAMENTE como el feed (que es lo que pide la\n           especificación: «el mismo layout waterfall del feed principal»). */\n        data={tab === 'productos' ? (prodTienda as unknown as LbPostBase[]) : tab === 'coleccion' ? (guardados as unknown as LbPostBase[]) : posts}\n        keyExtractor={(p) => p.id}\n        numColumns={2}\n        columnWrapperStyle={{ paddingHorizontal: GAP, gap: GAP }}\n        contentContainerStyle={{ paddingBottom: insets.bottom + 30, flexGrow: 1, gap: GAP }}\n        ListHeaderComponent={\n          <View>\n            {/* Portada + identidad */}\n            <View style={{ height: 208 }}>\n              {coverSrc ? (\n                <Image source={{ uri: coverSrc }} style={StyleSheet.absoluteFill} resizeMode=\"cover\" />\n              ) : (\n                <Svg style={StyleSheet.absoluteFill}>\n                  <Defs>\n                    <SvgLinearGradient id=\"lbCover\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n                      <Stop offset=\"0\" stopColor={brand.primary} />\n                      <Stop offset=\"0.55\" stopColor={brand.primary} />\n                      <Stop offset=\"1\" stopColor={brand.info} />\n                    </SvgLinearGradient>\n                  </Defs>\n                  <Rect width=\"100%\" height=\"100%\" fill=\"url(#lbCover)\" />\n                </Svg>\n              )}\n              <Svg style={StyleSheet.absoluteFill}>\n                <Defs>\n                  <SvgLinearGradient id=\"lbScrim\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                    <Stop offset=\"0\" stopColor=\"transparent\" />\n                    <Stop offset=\"1\" stopColor=\"rgba(0,0,0,0.62)\" />\n                  </SvgLinearGradient>\n                </Defs>\n                <Rect width=\"100%\" height=\"100%\" fill=\"url(#lbScrim)\" />\n              </Svg>\n            </View>\n\n            {/* Identidad superpuesta */}\n            <View style={[styles.identity, { paddingHorizontal: espaciado.e16, marginTop: -46 }]}>\n              {/* El avatar pasa a ser `StatusRingAvatar`: trae el ANILLO del estado 24 h y, si no\n                  hay foto, la inicial — que es justo lo que este bloque hacía a mano. Tamaño 80\n                  + 3 de anillo = 86, exactamente el avatar que había, así que el hueco no cambia.\n                  El toque sólo hace algo si HAY estado: sin estado no se abre nada, y así el\n                  avatar sigue siendo un avatar y no un botón que no lleva a ninguna parte. */}\n              <StatusRingAvatar\n                avatarUrl={profile.avatarUrl}\n                name={profile.fullName}\n                status={estado}\n                size={80}\n                ringWidth={3}\n                defaultRingColor={colors.background}\n                onPress={estado ? () => setEstadoOpen(true) : undefined}\n              />\n              <View style={{ flex: 1, paddingTop: espaciado.e4 }}>\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5 }}>\n                  <Text numberOfLines={2} style={[styles.fullName, { color: profile.nameColor || colors.textPrimary }]}>\n                    {profile.fullName ?? 'Usuario'}\n                  </Text>\n                  {verifiedList.length > 0 && <BadgeCheck size={18} color={brand.primary} fill={brand.primary} stroke={brand.white} strokeWidth={2.5} />}\n                </View>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>\n                  {[profile.profession, profile.school].filter(Boolean).join(' · ') || (rel.isSelf ? 'Tu perfil' : 'Miembro de Life Book')}\n                </Text>\n                {profile.city ? (\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginTop: espaciado.e2 }}>\n                    <MapPin size={11} color={colors.textSecondary} />\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                      {[profile.country, profile.city].filter(Boolean).join(' · ')}\n                    </Text>\n                  </View>\n                ) : null}\n                {verifiedList.length > 0 && (\n                  <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e5, marginTop: espaciado.e6 }}>\n                    {verifiedList.map((v) => {\n                      const Icon = v.icon;\n                      return (\n                        <View key={v.key} style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, backgroundColor: alpha(v.color, 0.12), borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 }}>\n                          <Icon size={11} color={v.color} />\n                          <Text style={{ color: v.color, fontSize: 10.5, fontWeight: '900' }}>{v.label} ✓</Text>\n                        </View>\n                      );\n                    })}\n                  </View>\n                )}\n              </View>\n            </View>\n\n            {/* Stats */}\n            <View style={[styles.statsRow, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              {[\n                { n: profile.stats.posts, l: 'Publicaciones', Icon: Bookmark },\n                { n: profile.stats.followers, l: 'Seguidores', Icon: Users },\n                { n: profile.stats.following, l: 'Seguidos', Icon: Users },\n                { n: profile.stats.likes, l: 'Me gusta', Icon: Heart },\n              ].map((s, i) => {\n                const Icon = s.Icon;\n                return (\n                  <View key={s.l} style={[styles.stat, i > 0 && { borderLeftWidth: StyleSheet.hairlineWidth, borderLeftColor: colors.border }]}>\n                    <Text style={{ color: colors.textPrimary, fontSize: 16.5, fontWeight: '900' }}>{s.n}</Text>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3, marginTop: 1 }}>\n                      <Icon size={10.5} color={colors.textSecondary} />\n                      <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: 9.5, fontWeight: '700' }}>{s.l}</Text>\n                    </View>\n                  </View>\n                );\n              })}\n            </View>\n\n            {/* Bio — SE HA SUBIDO aquí arriba (antes iba DEBAJO de los botones) para que la\n                tarjeta de la tienda quede donde pide la especificación: entre la bio y los\n                botones de seguir/mensaje. Tal como estaba, ese hueco no existía. */}\n            {profile.bio ? (\n              <View style={{ paddingHorizontal: espaciado.e16, marginTop: espaciado.e12 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, lineHeight: 20 }}>{profile.bio}</Text>\n              </View>\n            ) : null}\n\n            {/* TANDA A — TARJETA DE LA TIENDA. Es un atajo, no un destino: tocar la cabecera\n                abre la tienda; tocar una miniatura abre la tienda POSICIONADA en ese\n                producto (no la ficha del producto). */}\n            {tienda?.shop ? (\n              <View style={{ paddingHorizontal: espaciado.e16, marginTop: espaciado.e12 }}>\n                <View style={[styles.tiendaCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n                  <Pressable\n                    onPress={() => irSeguro.libre('/lifebook-shop/[id]', { id: tienda.shop!.id })}\n                    accessibilityLabel={`Abrir la tienda ${tienda.shop.name}`}\n                    style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}\n                  >\n                    {tienda.shop.logoUrl ? (\n                      <Image source={{ uri: absUrl(tienda.shop.logoUrl) }} style={styles.tiendaLogo} />\n                    ) : (\n                      <View style={[styles.tiendaLogo, { backgroundColor: alpha(colors.primary, 0.12), alignItems: 'center', justifyContent: 'center' }]}>\n                        <Store size={16} color={colors.primary} />\n                      </View>\n                    )}\n                    <Text numberOfLines={1} style={{ flex: 1, color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>\n                      {tienda.shop.name}\n                    </Text>\n                    {/* ★ SOLO si hay reseñas. Sin ninguna NO se pinta puntuación: ni «0\n                        estrellas» ni un hueco. Por eso se mira `ratingCount`, no `rating`\n                        (hoy hay 116 productos con `rating` y 0 reseñas). */}\n                    {tienda.shop.ratingCount > 0 ? (\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e3 }}>\n                        <Star size={13} color={brand.warning} fill={brand.warning} />\n                        <Text style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                          {tienda.shop.rating.toFixed(1)}\n                        </Text>\n                      </View>\n                    ) : null}\n                    <ChevronRight size={16} color={colors.textSecondary} />\n                  </Pressable>\n\n                  {tienda.featured.length > 0 ? (\n                    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8, paddingTop: espaciado.e10 }}>\n                      {tienda.featured.map((f) => (\n                        <Pressable\n                          key={f.id}\n                          onPress={() => irSeguro.libre('/lifebook-shop/[id]', { id: tienda.shop!.id, product: f.id })}\n                          accessibilityLabel={`${f.title}: verlo en la tienda`}\n                          style={{ width: 96 }}\n                        >\n                          <View style={styles.tiendaThumb}>\n                            {f.coverUrl ? (\n                              <Image source={{ uri: absUrl(f.coverUrl) }} style={StyleSheet.absoluteFill} resizeMode=\"cover\" />\n                            ) : (\n                              <View style={[StyleSheet.absoluteFill, { backgroundColor: alpha(colors.primary, 0.08), alignItems: 'center', justifyContent: 'center' }]}>\n                                <Package size={18} color={alpha(colors.primary, 0.5)} />\n                              </View>\n                            )}\n                            {/* El precio ENCIMA de la foto sobre un badge oscuro\n                                semitransparente, para que se lea sobre cualquier imagen. */}\n                            <View style={styles.tiendaPrecio}>\n                              <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>\n                                {lbPriceLabel(f.priceXaf, f.priceMode, lbXaf)}\n                              </Text>\n                            </View>\n                          </View>\n                          <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: 10.5, marginTop: espaciado.e4 }}>\n                            {f.title}\n                          </Text>\n                        </Pressable>\n                      ))}\n                    </ScrollView>\n                  ) : null}\n                </View>\n              </View>\n            ) : null}\n\n            {/* Acciones */}\n            <View style={{ paddingHorizontal: espaciado.e16, marginTop: espaciado.e12 }}>\n              {rel.isSelf ? (\n                <>\n                  <Pressable onPress={() => router.push('/edit-profile')} style={[styles.mainBtn, { backgroundColor: colors.surface, borderColor: colors.border }]}>\n                    <PenSquare size={16} color={colors.textPrimary} />\n                    <Text style={{ color: colors.textPrimary, fontSize: 14.5, fontWeight: '900' }}>Editar perfil</Text>\n                  </Pressable>\n                  <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n                    <Pressable onPress={() => irSeguro.libre('/lifebook-orders')} style={[styles.mainBtn, { flex: 1, backgroundColor: colors.surface, borderColor: colors.border }]}>\n                      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>📦 Pedidos</Text>\n                    </Pressable>\n                    <Pressable onPress={() => irSeguro.libre('/lifebook-messages')} style={[styles.mainBtn, { flex: 1, backgroundColor: colors.surface, borderColor: colors.border }]}>\n                      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>💬 Mensajes</Text>\n                    </Pressable>\n                  </View>\n                  {/* MERCADO (tanda F): los otros dos accesos rápidos del comprador que YA existen.\n                      «Carrito» estaba solo dentro de la ficha de un producto y el historial no tenía\n                      puerta. NO hay botón de «Cupones»: desde la tanda Q los cupones se recogen y se\n                      aplican EN LA CAJA (con su código), así que una pantalla aparte todavía no\n                      tiene nada que enseñar; un botón que no lleva a nada es una trampa. */}\n                  <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n                    <Pressable onPress={() => irSeguro.libre('/lifebook-carrito')} style={[styles.mainBtn, { flex: 1, backgroundColor: colors.surface, borderColor: colors.border }]}>\n                      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>🛒 Carrito</Text>\n                    </Pressable>\n                    <Pressable onPress={() => irSeguro.libre('/lifebook-vistos')} style={[styles.mainBtn, { flex: 1, backgroundColor: colors.surface, borderColor: colors.border }]}>\n                      <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>🕘 Vistos</Text>\n                    </Pressable>\n                  </View>\n                </>\n              ) : (\n                <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n                  <Pressable onPress={toggleFollow} style={[styles.mainBtn, { flex: 1.4, backgroundColor: rel.isFollowing ? colors.surface : colors.primary, borderColor: rel.isFollowing ? colors.border : colors.primary }]}>\n                    {busyFollow ? <ActivityIndicator size=\"small\" color={rel.isFollowing ? colors.textPrimary : brand.white} /> : (\n                      <>\n                        <Heart size={15} color={rel.isFollowing ? colors.textPrimary : brand.white} fill={rel.isFollowing ? 'transparent' : brand.white} />\n                        <Text style={{ color: rel.isFollowing ? colors.textPrimary : brand.white, fontSize: 14.5, fontWeight: '900' }}>\n                          {rel.isFollowing ? 'Siguiendo' : 'Seguir'}\n                        </Text>\n                      </>\n                    )}\n                  </Pressable>\n                  <Pressable onPress={openChat} style={[styles.mainBtn, { flex: 1, backgroundColor: colors.surface, borderColor: colors.border }]}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>💬 Mensaje</Text>\n                  </Pressable>\n                </View>\n              )}\n              {!rel.isSelf && profile.verified.seller && (\n                <Pressable\n                  onPress={() => irSeguro.libre('/lifebook-store', { sellerId: profile.id })}\n                  style={[styles.mainBtn, { marginTop: espaciado.e8, backgroundColor: alpha(colors.secondary, 0.1), borderColor: alpha(colors.secondary, 0.4) }]}\n                >\n                  <Text style={{ color: colors.secondary, fontSize: tipografia.body, fontWeight: '900' }}>🛍 Ver tienda</Text>\n                </Pressable>\n              )}\n            </View>\n\n            {profile.ratingAvg != null && profile.ratingAvg > 0 ? (\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, paddingHorizontal: espaciado.e16, marginTop: espaciado.e8 }}>\n                <Star size={13} color={brand.warning} fill={brand.warning} />\n                <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>{profile.ratingAvg.toFixed(1)}</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>valoración</Text>\n              </View>\n            ) : null}\n            {/* P3 — ENLACES DE GRUPO: tarjeta con la foto y el nombre del grupo. Se toca y\n                lleva a la ficha del grupo (donde ya se une uno, se pide entrar o se\n                responde la pregunta), reutilizando la pantalla de Descubrir grupos con el\n                código puesto: así no hay dos maneras distintas de entrar a un grupo. */}\n            {enlacesGrupo.length > 0 && (\n              <View style={{ paddingHorizontal: espaciado.e16, marginTop: espaciado.e10, gap: espaciado.e8 }}>\n                {enlacesGrupo.map((g) => {\n                  const ficha = fichas[g.code];\n                  const cargando = ficha === undefined;\n                  const card = ficha?.card ?? null;\n                  const vivo = !!card;\n                  const sePuedeReintentar = !cargando && !vivo && /reintentar/i.test(ficha?.motivo ?? '');\n                  return (\n                    <Pressable\n                      key={g.code}\n                      disabled={!vivo && !sePuedeReintentar}\n                      onPress={() => {\n                        // Si solo falló la comprobación, el toque REINTENTA (no navega).\n                        if (!vivo) {\n                          setFichas((prev) => { const c = { ...prev }; delete c[g.code]; return c; });\n                          setReintento((n) => n + 1);\n                          return;\n                        }\n                        irSeguro.libre('/lifebook-groups', { code: g.code });\n                      }}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={vivo ? `Abrir el grupo ${card?.title ?? g.label}` : (ficha?.motivo || 'Enlace de grupo')}\n                      style={({ pressed }) => [{\n                        flexDirection: 'row' as const, alignItems: 'center' as const, gap: espaciado.e10,\n                        backgroundColor: colors.surface, borderRadius: 14, padding: espaciado.e10,\n                        opacity: pressed ? 0.8 : 1,\n                        /* Fijado: se distingue igual que los chips fijados. */\n                        ...(g.pinned ? { borderWidth: 1, borderColor: colors.primary } : {}),\n                      }]}\n                    >\n                      {card?.photoUrl ? (\n                        <Image source={{ uri: absUrl(card.photoUrl) }} style={{ width: 44, height: 44, borderRadius: radios.md }} />\n                      ) : (\n                        <View style={{ width: 44, height: 44, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center', backgroundColor: alpha(colors.primary, 0.12) }}>\n                          <Users size={22} color={colors.primary} />\n                        </View>\n                      )}\n                      <View style={{ flex: 1 }}>\n                        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }} numberOfLines={1}>\n                          {g.pinned ? '📌 ' : ''}{card?.title ?? g.label}\n                        </Text>\n                        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }} numberOfLines={1}>\n                          {cargando\n                            ? 'Comprobando el enlace…'\n                            : vivo\n                              /* El MODO DE ENTRADA importa antes de tocar: si hay que pedir\n                                 permiso o responder una pregunta, el visitante debe saberlo\n                                 aquí y no después de pulsar. El dato ya venía en la ficha\n                                 (`joinMode`) y la etiqueta ya estaba escrita en\n                                 `GroupCardSheet`: solo no se pintaba. */\n                              ? `${card!.membersCount} ${card!.membersCount === 1 ? 'miembro' : 'miembros'} · ${\n                                  card!.joinMode === 'open' ? 'entrada libre'\n                                    : card!.joinMode === 'approval' ? 'con aprobación'\n                                      : 'con pregunta'\n                                }`\n                              : (ficha?.motivo ?? 'Este enlace ya no sirve (ha caducado)')}\n                        </Text>\n                      </View>\n                    </Pressable>\n                  );\n                })}\n              </View>\n            )}\n            {linksChip.length > 0 && (\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6, paddingHorizontal: espaciado.e16, marginTop: espaciado.e10 }}>\n                {linksChip.map((l, i) => {\n                  /* ESTABA ROTO: el editor de perfil guarda `{kind,label,value}` y aquí se\n                     leía `l.url`, que no existe nunca → el enlace salía VACÍO y, además,\n                     el chip era un `View` sin `Pressable`, así que no se podía tocar. O\n                     sea: en el perfil público los enlaces eran decorativos. Se aceptan\n                     las dos formas (`value` y `url`) y si es una dirección se abre. */\n                  const o = (typeof l === 'string' ? { label: l, value: l } : l) as { kind?: string; label?: string; value?: string; url?: string };\n                  const label = String(o?.label ?? o?.value ?? o?.url ?? '');\n                  const destino = String(o?.value ?? o?.url ?? '');\n                  /* Se aceptan los tres casos que hay de verdad:\n                     · una dirección web (http/https),\n                     · un `mailto:`/`tel:` ya escrito así,\n                     · y un CORREO SUELTO — que es justo el ÚNICO enlace que existe hoy\n                       en la base (`{\"kind\":\"email\",\"label\":\"EgRoutePlan\",\n                       \"value\":\"egrouteplan@gmail.com\"}`), y que con la comprobación\n                       anterior se quedaba sin poder abrir. */\n                  const href = /^(https?:\\/\\/|mailto:|tel:)/i.test(destino)\n                    ? destino\n                    : (/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(destino) ? `mailto:${destino}` : '');\n                  const abrible = !!href;\n                  const chip = (\n                    <View style={{\n                      backgroundColor: colors.surface, borderRadius: radios.full, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5,\n                      /* Los fijados se distinguen del resto: borde del color de marca. */\n                      ...(esFijado(o) ? { borderWidth: 1, borderColor: colors.primary } : {}),\n                    }}>\n                      <Text style={{ color: colors.primary, fontSize: tipografia.caption, fontWeight: '700' }} numberOfLines={1}>\n                        {esFijado(o) ? '📌 ' : ''}{label}{abrible ? ' ↗' : ''}\n                      </Text>\n                    </View>\n                  );\n                  return abrible ? (\n                    <Pressable\n                      key={i}\n                      onPress={() => { Linking.openURL(href).catch(() => {}); }}\n                      accessibilityRole=\"link\"\n                      accessibilityLabel={`Abrir ${label}`}\n                    >\n                      {chip}\n                    </Pressable>\n                  ) : (\n                    <View key={i}>{chip}</View>\n                  );\n                })}\n              </View>\n            )}\n\n            {/* Pestañas. TANDA B: en una cuenta con tienda se añade «Productos» justo después\n                de «Notas» (y «Colección» —mis guardados— solo en MI perfil), que es lo que\n                pide la especificación. Se CONSERVAN las pestañas que ya existían (Videos,\n                Podcasts, Series, Ventas) porque esta app tiene contenido que Xiaohongshu no\n                tiene: quitarlas escondería publicaciones que hoy se pueden ver. A la derecha\n                del todo, la lupa. */}\n            <View style={{ borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.border, flexDirection: 'row', alignItems: 'center' }}>\n              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }} style={{ flex: 1 }}>\n                {[\n                  { id: 'note', label: 'Notas' },\n                  ...(shopId ? [{ id: 'productos', label: 'Productos' }] : []),\n                  { id: 'video', label: 'Videos' },\n                  { id: 'podcast', label: 'Podcasts' },\n                  { id: 'serie', label: 'Series' },\n                  { id: 'sale', label: 'Ventas' },\n                  ...(rel.isSelf ? [{ id: 'coleccion', label: 'Colección' }] : []),\n                  { id: '', label: 'Todo' },\n                ].map((t) => {\n                  const on = tab === t.id;\n                  return (\n                    <Pressable\n                      key={t.label}\n                      onPress={() => setTab(t.id)}\n                      accessibilityRole=\"tab\"\n                      accessibilityState={{ selected: on }}\n                      style={[styles.tabPill, { backgroundColor: on ? colors.primary : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                    >\n                      <Text style={{ color: on ? brand.white : colors.textSecondary, fontSize: tipografia.body, fontWeight: on ? '900' : '700' }}>{t.label}</Text>\n                    </Pressable>\n                  );\n                })}\n              </ScrollView>\n              <Pressable\n                onPress={() => router.push({ pathname: '/lifebook-catalog', params: shopId ? { shopId } : {} } as never)}\n                hitSlop={10}\n                accessibilityLabel=\"Buscar productos\"\n                style={{ paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10 }}\n              >\n                <Search size={18} color={colors.textSecondary} />\n              </Pressable>\n            </View>\n\n            {/* TANDA B — fila de CATEGORÍAS del tab «Productos»: «Todo» primero y seleccionada\n                por defecto, y solo las categorías que esta tienda usa de verdad. */}\n            {tab === 'productos' && catsTienda.length > 0 ? (\n              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8, paddingHorizontal: espaciado.e14, paddingTop: espaciado.e10 }}>\n                {[{ id: null as string | null, label: `Todo${totalTienda ? ` (${totalTienda})` : ''}` },\n                  ...catsTienda.map((c) => ({ id: c.id as string | null, label: `${c.name} (${c.count})` }))].map((c) => {\n                  const on = catSel === c.id;\n                  return (\n                    <Pressable\n                      key={c.label}\n                      onPress={() => setCatSel(c.id)}\n                      accessibilityRole=\"tab\"\n                      accessibilityState={{ selected: on }}\n                      accessibilityLabel={`Categoría ${c.label}`}\n                      style={[styles.tabPill, { backgroundColor: on ? alpha(colors.primary, 0.15) : colors.surface, borderColor: on ? colors.primary : colors.border }]}\n                    >\n                      <Text style={{ color: on ? colors.primary : colors.textSecondary, fontSize: tipografia.caption, fontWeight: on ? '900' : '700' }}>{c.label}</Text>\n                    </Pressable>\n                  );\n                })}\n              </ScrollView>\n            ) : null}\n            {loadingPosts && posts.length === 0 ? (\n              <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e30 }} />\n            ) : null}\n          </View>\n        }\n        renderItem={({ item }) =>\n          tab === 'productos' || tab === 'coleccion' ? (\n            <TarjetaProducto\n              producto={item as unknown as LbProductCard}\n              colors={colors}\n              ancho={cellW}\n              onPress={() => irSeguro.libre('/lifebook-product/[id]', { id: item.id })}\n            />\n          ) : (\n            <PostCard post={toPostCard(item)} width={cellW} onPress={(pid) => router.push({ pathname: '/lifebook-post/[id]', params: { id: pid } })} />\n          )\n        }\n        onEndReached={tab === 'productos' ? verMasProductos : loadMore}\n        onEndReachedThreshold={0.4}\n        ListEmptyComponent={\n          !loadingPosts && posts.length === 0 ? (\n            <View style={{ alignItems: 'center', paddingTop: 44, gap: espaciado.e6 }}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: 15 }}>\n                {tab === 'productos' ? 'Sin productos' : tab === 'coleccion' ? 'Sin guardados' : tab === 'note' ? 'Sin notas' : tab === 'video' ? 'Sin videos' : tab === 'podcast' ? 'Sin podcasts' : tab === 'serie' ? 'Sin series' : tab === 'sale' ? 'Sin ventas' : 'Sin publicaciones'}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', paddingHorizontal: espaciado.e30 }}>\n                {tab === 'productos' ? 'Esta tienda no tiene productos en esta categoría.' : tab === 'coleccion' ? 'Guarda productos con el marcador y aparecerán aquí.' : rel.isSelf ? 'Publica algo para que tu ciudad te vea.' : 'Este perfil todavía no ha publicado aquí.'}\n              </Text>\n            </View>\n          ) : null\n        }\n        ListFooterComponent={\n          (tab === 'productos' && cursorProd) || masProd ? (\n            <Pressable\n              onPress={() => void verMasProductos()}\n              disabled={masProd}\n              accessibilityLabel=\"Ver más productos\"\n              style={{ alignItems: 'center', paddingVertical: espaciado.e16 }}\n            >\n              {masProd\n                ? <ActivityIndicator color={colors.primary} />\n                : <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>Ver más productos</Text>}\n            </Pressable>\n          ) : loadingMore ? <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e16 }} /> : <View style={{ height: 8 }} />\n        }\n      />\n\n      {/* Menú ⋯ del perfil ajeno */}\n      <Modal visible={userMenuOpen} transparent animationType=\"fade\" onRequestClose={() => setUserMenuOpen(false)} statusBarTranslucent>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.4)' }} onPress={() => setUserMenuOpen(false)} />\n        <View style={[styles.userMenuSheet, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n          <Pressable\n            onPress={askToggleBlock}\n            style={({ pressed }) => [styles.userMenuRow, { backgroundColor: pressed ? alpha(colors.danger, 0.05) : 'transparent' }]}\n          >\n            <Text style={{ color: blocked ? colors.primary : colors.danger, fontSize: 15, fontWeight: '800' }}>\n              {blocked ? 'Desbloquear usuario' : 'Bloquear usuario'}\n            </Text>\n          </Pressable>\n          <Pressable\n            onPress={() => { setUserMenuOpen(false); irSeguro.libre('/lifebook-blocks'); }}\n            style={({ pressed }) => [styles.userMenuRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n          >\n            <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '700' }}>Usuarios bloqueados</Text>\n          </Pressable>\n          <Pressable onPress={() => setUserMenuOpen(false)} style={{ paddingVertical: espaciado.e10 }}>\n            <Text style={{ textAlign: 'center', color: colors.textSecondary, fontWeight: '800', fontSize: tipografia.body }}>Cancelar</Text>\n          </Pressable>\n        </View>\n      </Modal>\n\n      {/* ── ESTADO 24 H EN GRANDE ───────────────────────────────────────────────────\n          Es la MISMA vista de historia que ya usaba el dueño desde su perfil, sin duplicar nada.\n\n          `isMine` se pasa EXPLÍCITAMENTE y no se deja al aire: dentro del componente hay\n          `const mine = isMine ?? !author`, o sea que si no se le dice nada, **asume que el estado\n          es tuyo** y te ofrece «finalizar». En el perfil de otra persona eso sería darle a un\n          visitante el botón de terminar el estado ajeno. Con `isMine={rel.isSelf}` y el `author`\n          del perfil, cada uno ve lo que le toca: el dueño finaliza, el visitante reporta. */}\n      {estado ? (\n        <StatusDetailModal\n          visible={estadoOpen}\n          status={estado}\n          author={autorEstado}\n          isMine={rel.isSelf}\n          onClose={() => setEstadoOpen(false)}\n          onEnded={() => { setEstadoAjeno(null); setEstadoOpen(false); }}\n        />\n      ) : null}\n    </View>\n  );\n}\n\n/**\n * TANDA B — la celda de la rejilla de productos del perfil.\n *\n * Lo que pide la especificación, ni una cosa más: imagen, nombre (1-2 líneas, cortado con\n * puntos suspensivos), precio en el color de acento, descripción corta en gris y «X vendidos»\n * cuando lo hay. **No** se pinta la puntuación del producto, ni el stock, ni el envío: solo lo\n * justo para decidir si se toca o se sigue bajando. La descripción corta la escribe el\n * comerciante al publicar (`products.short_description`), así que no hay que recortarla.\n */\nfunction TarjetaProducto({ producto, colors, ancho, onPress }: {\n  producto: LbProductCard;\n  colors: { primary: string; card: string; border: string; textPrimary: string; textSecondary: string };\n  ancho: number;\n  onPress: () => void;\n}) {\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityLabel={producto.title}\n      style={{ width: ancho, backgroundColor: colors.card, borderRadius: 14, borderWidth: 1, borderColor: alpha(colors.border, 0.5), padding: espaciado.e8 }}\n    >\n      {producto.coverUrl ? (\n        <Image source={{ uri: absUrl(producto.coverUrl) }} style={styles.prodImg} resizeMode=\"cover\" />\n      ) : (\n        <View style={[styles.prodImg, { alignItems: 'center', justifyContent: 'center' }]}>\n          <Package size={20} color={alpha(colors.primary, 0.5)} />\n        </View>\n      )}\n      <Text numberOfLines={2} style={{ color: colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e6 }}>\n        {producto.title}\n      </Text>\n      <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900', marginTop: espaciado.e3 }}>\n        {lbPriceLabel(producto.priceXaf, producto.priceMode, lbXaf)}\n      </Text>\n      {producto.shortDescription ? (\n        <Text numberOfLines={1} style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: espaciado.e2 }}>\n          {producto.shortDescription}\n        </Text>\n      ) : null}\n      {producto.salesCount > 0 ? (\n        <Text style={{ color: colors.textSecondary, fontSize: 10.5, fontWeight: '700', marginTop: espaciado.e2 }}>\n          {producto.salesCount} vendido{producto.salesCount === 1 ? '' : 's'}\n        </Text>\n      ) : null}\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  /* ── Tanda B: la celda de producto de la rejilla ──────────────────────────────── */\n  prodImg: { width: '100%', aspectRatio: 1, borderRadius: radios.md, backgroundColor: 'rgba(0,0,0,0.04)' },\n\n  /* ── Tanda A: la tarjeta de la tienda ─────────────────────────────────────────── */\n  tiendaCard: { borderWidth: 1, borderRadius: 14, padding: espaciado.e10 },\n  tiendaLogo: { width: 30, height: 30, borderRadius: radios.sm },\n  /* Miniatura CASI cuadrada (la especificación pide «cuadradas o casi»). 96×96 para que\n     quepan tres y se vea que hay más desplazando. */\n  tiendaThumb: {\n    width: 96, height: 96, borderRadius: 10, overflow: 'hidden',\n    backgroundColor: 'rgba(0,0,0,0.04)',\n  },\n  /* El precio va ENCIMA de la foto, en la esquina inferior, con fondo oscuro\n     semitransparente para que se lea sobre una foto clara o oscura. */\n  tiendaPrecio: {\n    position: 'absolute', left: 0, right: 0, bottom: 0,\n    backgroundColor: 'rgba(0,0,0,0.55)', paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e3,\n    alignItems: 'center',\n  },\n\n  topBar: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingBottom: espaciado.e8, borderBottomWidth: StyleSheet.hairlineWidth },\n  topTitle: { fontSize: tipografia.subtitle, fontWeight: '900', flex: 1 },\n  topBarFloat: { position: 'absolute', top: 0, left: 0, right: 0, zIndex: 5, flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e12 },\n  roundIcon: { width: 36, height: 36, borderRadius: 18, alignItems: 'center', justifyContent: 'center' },\n  identity: { flexDirection: 'row', gap: espaciado.e12 },\n  avatar: { width: 86, height: 86, borderRadius: 43, borderWidth: 3 },\n  avatarFallback: { alignItems: 'center', justifyContent: 'center' },\n  fullName: { fontSize: tipografia.title, fontWeight: '900', flexShrink: 1 },\n  statsRow: { flexDirection: 'row', marginHorizontal: espaciado.e16, marginTop: espaciado.e12, borderRadius: 14, borderWidth: StyleSheet.hairlineWidth, paddingVertical: espaciado.e10 },\n  stat: { flex: 1, alignItems: 'center' },\n  mainBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e7, borderRadius: radios.full, paddingVertical: espaciado.e11, borderWidth: 1, borderColor: 'transparent' },\n  tabs: { flexDirection: 'row', marginTop: espaciado.e14, borderBottomWidth: StyleSheet.hairlineWidth },\n  tab: { flex: 1, alignItems: 'center', paddingVertical: espaciado.e10 },\n  tabPill: { borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7, borderWidth: 1, borderColor: 'transparent' },\n  userMenuSheet: { ...formaHoja },\n  userMenuRow: { borderRadius: radios.md, paddingVertical: espaciado.e13, paddingHorizontal: espaciado.e12 },\n});\n\n\n\n","/**\n * LifeBookVideosScreen — FEED INMERSIVO DE VÍDEO (B1).\n *\n * Deslizar arriba/abajo pasa de un vídeo al siguiente SIN salir a otra pantalla:\n * una página por vídeo, autoplay del que está visible y pausa del resto, silencio\n * al entrar con botón para activar el sonido, doble toque = me gusta, y el\n * siguiente vídeo ya montado (precarga) para que el pase no espere.\n *\n * ── POR QUÉ ASÍ, Y NO DE OTRA FORMA ─────────────────────────────────────────\n * · FlatList con `pagingEnabled` + `getItemLayout` de altura fija. En el proyecto\n *   NO hay `react-native-pager-view` ni `@shopify/flash-list`, y añadirlos por esto\n *   no compensa: con una página = una pantalla, `getItemLayout` da paginado exacto,\n *   `initialScrollIndex` gratis y precarga controlada con `windowSize`.\n * · El feed masonry de `lifebook.tsx` NO se toca. Es un FlatList con UN solo item\n *   que contiene las dos columnas (`data={[{ left, right }]}`), así que un vídeo a\n *   pantalla completa no cabe ahí dentro ni se puede paginar. Esta pantalla es\n *   aparte a propósito — es la opción A+B que decidió el dueño: canal de vídeo\n *   propio, y al tocar una tarjeta de vídeo del masonry se entra aquí.\n * · **ÉSTE ES EL ÚNICO ESTADO DE VER VÍDEO.** `/lifebook-player` ya sólo reproduce\n *   audio: su reproductor de vídeo se retiró (ver [P9] y la cabecera de ese fichero).\n *   Cuando esta pantalla pierde el foco (se abre el detalle), el vídeo se pausa y al\n *   volver se reanuda el visible: la lista no se desmonta ni se recarga.\n *\n * ── DECISIONES DE LA RONDA DE PRUEBAS EN EL APARATO (2026-09-13) ────────────\n * El dueño probó el build y pidió cambios concretos. Cada uno está marcado abajo\n * con [P#] para que se pueda rastrear por qué el código es así:\n *\n * [P2] `contentFit` pasa de `cover` a `contain`. Con `cover` un vídeo vertical se\n *      recortaba para llenar la pantalla y \"no se alcanzaba a ver bien\". `contain`\n *      muestra el vídeo ENTERO (con bandas negras arriba/abajo si hace falta) y el\n *      zoom que falte se lo da el usuario con la pinza ([P5]).\n * [P4] BUG GRAVE corregido: al pausar se veía la PORTADA en vez del fotograma del\n *      vídeo. La capa de portada se ocultaba con `opacity: isActive && !paused ? 0 : 1`,\n *      o sea que estaba atada al estado de pausa. Ahora se rige por\n *      `onFirstFrameRender`: la portada tapa solo hasta que hay fotograma real, y\n *      desde entonces no vuelve a aparecer. Pausar ya no la trae de vuelta.\n * [P5] ❌ QUITADO en la segunda ronda con el aparato (2026-09-13). Se añadió la pinza\n *      para hacer zoom con los dedos y el dueño la rechazó: en un vídeo a pantalla\n *      completa el zoom solo sirve para DEJAR DE VER el vídeo, y el resultado era\n *      «demasiado zoom, no se alcanza a ver bien».\n *      Lo que NO se toca: el doble toque sigue siendo ME GUSTA y el toque simple\n *      pausa/reanuda. El zoom era el único gesto que sobraba.\n * [P6] Compartir y Guardar en la columna de acciones, junto a me gusta y comentarios.\n *      Guardar usa el endpoint que YA existe (`toggleSave`), no se inventa nada.\n * [P8] Fila «Búsquedas relacionadas» como en 小红书: chips con los temas de la publicación que\n *      llevan al buscador. Se construye con `topics`/`tags`, que YA vienen en el\n *      post — cero peticiones extra.\n *      ⚠️ El GRUPO del autor que pedía el dueño NO se puede pintar: `LbAuthor`\n *      (api/lifebook.ts:15-25) trae id, nombre, avatar, rol y seguidoPorMí, pero\n *      NO trae grupo, y no hay endpoint de «grupos de un usuario». Hace falta\n *      backend. No se inventa un campo que el servidor no manda.\n * [P9] ❌ QUITADO. El icono «Ver a pantalla completa» abría `/lifebook-player`. El dueño\n *      pidió que hubiera UN ÚNICO estado de ver vídeo —éste— y el reproductor de vídeo se\n *      retiró entero (ver la cabecera de `app/lifebook-player.tsx`). Un toque sobre un\n *      vídeo LARGO, que antes llevaba allí, ahora lo reproduce AQUÍ.\n * [P10] LA FRANJA NEGRA, FUERA. El móvil es 2,20:1 y un vídeo 9:16 deja dos bandas negras\n *      del 19 % con `contain`. Ahora se LLENA la pantalla cuando el recorte que cuesta es\n *      asumible (≤25 %) y, cuando no (un vídeo horizontal), se enseña entero sobre un fondo\n *      DESENFOCADO del propio vídeo, nunca sobre negro. Se decide con el tamaño real del\n *      vídeo (`player.videoTrack.size`). Ver `RECORTE_MAX` y el comentario en `VideoPage`.\n * [P11] UN GESTO = UN VÍDEO. `disableIntervalMomentum` + `decelerationRate=\"fast\"`: un\n *      deslizamiento rápido ya no encadena dos o tres vídeos.\n * [P12] LOS COMENTARIOS NO TAPAN EL VÍDEO. Se abre la misma hoja del detalle, pero con el\n *      velo a 0 (aquí debajo hay un vídeo reproduciéndose, no una pantalla que oscurecer) y\n *      con la altura acotada al 55 % para que el vídeo conserve casi media pantalla.\n *\n * ── NOMENCLATURA: NADA DE CHINO EN LO QUE SE LEE ────────────────────────────\n * Los diseños de referencia son de 小红书 (Xiaohongshu) y TikTok, y en los comentarios se\n * citan por su nombre: eso ayuda a entender de dónde sale cada cosa y se queda así.\n * Lo que NO se queda en chino es **nada que el usuario pueda leer**, ni etiquetas visibles ni\n * `accessibilityLabel`: la app está en español y un lector de pantalla leería caracteres que\n * el usuario no sabe leer. Se coló «相关搜索» copiado del diseño; ahora es «Búsquedas\n * relacionadas». La misma revisión encontró las pestañas en chino de\n * `app/ecomerse-favorites.tsx`, que también se tradujeron.\n *\n * ── LÍMITES MEDIDOS, no supuestos ───────────────────────────────────────────\n * · `expo-video` 2.2.3 **no exporta `useVideoPlayerStatus`**: el estado de\n *   reproducción se gestiona aquí con estado propio (somos nosotros quienes\n *   llamamos a `play()`/`pause()`), sin suscribirse a eventos. Menos superficie y\n *   sin API inventada.\n * · No hay `seekTo()` en esta versión: se salta asignando `player.currentTime`\n *   (documentado en VideoPlayer.types.d.ts:44-48). No se usa aquí, pero queda\n *   anotado para quien añada barra de progreso.\n * · `expo-haptics` **no está instalado**, así que el doble toque NO vibra. Añadir\n *   la dependencia por una vibración no merece la pena sin decidirlo aparte.\n *\n * Ruta: /lifebook-videos?startId=&channel=&city=\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Pressable, Share, StyleSheet, Text, View,\n  useWindowDimensions, type ViewToken, type ViewabilityConfig,\n} from 'react-native';\nimport { Image } from 'expo-image';\nimport { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { Gesture, GestureDetector } from 'react-native-gesture-handler';\n// [P5] `runOnJS` se queda: los TAPES son gestos y corren en la UI thread, así que\n// avisar a la JS thread de «doble toque = me gusta» sigue pasando por aquí. Lo que se\n// fue con el zoom son `Animated`, `useSharedValue`, `useAnimatedStyle` y `withTiming`.\nimport { runOnJS } from 'react-native-reanimated';\nimport { useVideoPlayer, VideoView } from 'expo-video';\nimport {\n  ArrowLeft, Bookmark, Heart, MessageCircle, Share2, ShoppingBag, Volume2, VolumeX,\n} from 'lucide-react-native';\nimport { alpha, EmptyState, espaciado, InlineError, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../api/config';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { authApi } from '../api/auth';\nimport { productosEnNotaApi, type LbProductoEnNota } from '../api/lifebookProductos';\nimport { lbXaf } from '../constants/lifebook';\nimport {\n  lifebookActionsApi, lifebookApi,\n  type LbFeedPage, type LbPostBase,\n} from '../api/lifebook';\nimport { CommentsSheet } from '../components/lifebook/CommentsSheet';\nimport { SeguirViendo } from '../components/lifebook/SeguirViendo';\nimport { watchApi, type LbSeguirViendo } from '../api/lifebookWatch';\nimport { fmtDur } from '../constants/lifebook';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst LIKE_RED = brand.like;\nconst PAGE = 40;\n\n/**\n * Cuánto se acepta RECORTAR del vídeo con tal de llenar la pantalla (0,25 = 25 %).\n *\n * Es la bisagra entre «llenar» y «encajar» (ver el comentario largo en `VideoPage`). Por\n * encima de esto el recorte se nota y se pierde contenido de verdad, así que se prefiere\n * encajar el vídeo entero sobre un fondo desenfocado antes que comerse un cuarto de la imagen.\n */\nconst RECORTE_MAX = 0.25;\n\n/**\n * Degradado inferior de legibilidad, SIN dependencias.\n *\n * Antes esto era un rectángulo PLANO: `rgba(0,0,0,0.42)` de 250 px de alto, con un borde\n * superior recto. Sobre un vídeo que ya no llena la pantalla con bandas negras, ese borde se\n * ve como lo que es —una capa pegada encima— y el dueño lo reportó tal cual: «esta capa que\n * cubre la parte inferior del vídeo de color negro transparente».\n *\n * No se añade `expo-linear-gradient` por esto: el proyecto evita dependencias nuevas cuando\n * se puede resolver con lo que ya hay, y aquí basta con apilar franjas de opacidad creciente.\n * A la vista es un degradado continuo; por dentro son 10 `View`.\n */\nconst SCRIM_BANDS = 10;\nfunction BottomScrim({ height, max }: { height: number; max: number }) {\n  const bands = [];\n  for (let i = 0; i < SCRIM_BANDS; i++) {\n    // De casi transparente arriba al máximo abajo: sin borde, sin escalón visible.\n    const a = (max * (i + 1)) / SCRIM_BANDS;\n    bands.push(\n      <View\n        key={i}\n        style={{ height: height / SCRIM_BANDS, backgroundColor: `rgba(0,0,0,${a.toFixed(3)})` }}\n      />,\n    );\n  }\n  return (\n    <View\n      style={{ position: 'absolute', left: 0, right: 0, bottom: 0, zIndex: 2 }}\n      pointerEvents=\"none\"\n    >\n      {bands}\n    </View>\n  );\n}\n\n/**\n * A partir de aquí, un vídeo es LARGO (Parte 50) y el feed cambia de trato.\n *\n * El feed inmersivo está pensado para clips: autoplay del visible, en bucle, y el vídeo\n * siguiente con un desliz. Un vídeo de 50 minutos ahí dentro es lo peor de los dos mundos:\n *   · Autoplay + bucle = se descarga entero (cientos de MB) mientras el usuario mira, y al\n *     terminar vuelve a empezar como si fuera un clip.\n *   · Sin barra de progreso no hay forma de saber por dónde va ni de saltar.\n * Así que el largo NO se reproduce solo: se ve su portada con la duración y un botón, y al\n * tocarlo se abre el reproductor de verdad, que sí tiene controles. El umbral es el mismo\n * del backend (`video_short` = 60 s), para que \"corto\" signifique lo mismo en todas partes.\n */\nconst LARGO_DESDE_SEC = 60;\n\n/** `payload.videoUrl` resuelto. El feed guarda los posts CRUDOS (`LbPostBase`),\n *  así que el vídeo está disponible aunque `toPostCard()` no lo exponga en la\n *  tarjeta. Devuelve '' si la publicación no tiene vídeo reproducible. */\nfunction videoUrlOf(p: LbPostBase): string {\n  const v = (p.payload ?? {}) as Record<string, unknown>;\n  const raw = typeof v.videoUrl === 'string' ? v.videoUrl.trim() : '';\n  return raw ? absUrl(raw) : '';\n}\n\nfunction coverOf(p: LbPostBase): string {\n  const v = (p.payload ?? {}) as Record<string, unknown>;\n  const c = typeof v.coverUrl === 'string' && v.coverUrl.trim() ? v.coverUrl.trim() : '';\n  if (c) return absUrl(c);\n  const first = p.media?.[0]?.url;\n  return first ? absUrl(first) : '';\n}\n\n/**\n * [P8] Temas de la publicación para la fila «Búsquedas relacionadas». El servidor los manda como\n * `topics` y además como alias `tags` (Parte 11), así que se mira en los dos. Se\n * quitan vacíos y duplicados y se recorta a 6: más de seis chips no caben en una\n * fila y obligan a envolver, que en un vídeo a pantalla completa estorba.\n */\nfunction topicsOf(p: LbPostBase): string[] {\n  const raw = [...(p.topics ?? []), ...(p.tags ?? [])];\n  const out: string[] = [];\n  for (const t of raw) {\n    const s = String(t ?? '').trim();\n    if (s && !out.includes(s)) out.push(s);\n    if (out.length >= 6) break;\n  }\n  return out;\n}\n\nexport default function LifeBookVideosScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { height: H } = useWindowDimensions();\n  const { startId, channel, city } = useLocalSearchParams<{\n    startId?: string; channel?: string; city?: string;\n  }>();\n\n  const [posts, setPosts] = useState<LbPostBase[]>([]);\n  const [cursor, setCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [loadingMore, setLoadingMore] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  /** Índice del vídeo visible = el único que reproduce. */\n  const [active, setActive] = useState(0);\n  /**\n   * TANDA C — LOS PRODUCTOS QUE VAN DENTRO DE CADA VÍDEO.\n   *\n   * Se piden solo para el vídeo que se está viendo (una petición al cambiar de vídeo, y ninguna\n   * si el vídeo no lleva productos): pedirlos para toda la lista sería una petición por vídeo.\n   * Se guardan por id para no volver a pedirlos al subir y bajar.\n   */\n  const [prodsVideo, setProdsVideo] = useState<Record<string, LbProductoEnNota[]>>({});\n  useEffect(() => {\n    const p = posts[active];\n    if (!p || prodsVideo[p.id]) return;\n    let vivo = true;\n    productosEnNotaApi.deNota(p.id)\n      .then((r) => { if (vivo) setProdsVideo((prev) => ({ ...prev, [p.id]: r.products ?? [] })); })\n      .catch(() => { if (vivo) setProdsVideo((prev) => ({ ...prev, [p.id]: [] })); });\n    return () => { vivo = false; };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [active, posts]);\n  /** Silencio por defecto al entrar (como 小红书): el sonido se activa a mano. */\n  const [muted, setMuted] = useState(true);\n  /** Pausa forzada por el usuario con un toque; se reinicia al cambiar de vídeo. */\n  const [pausedId, setPausedId] = useState<string | null>(null);\n  /** La pantalla perdió el foco (se abrió el detalle): pausar todo. */\n  const [focused, setFocused] = useState(true);\n  /** Usuario actual: lo necesita la hoja de comentarios para marcar los míos. */\n  const [meId, setMeId] = useState<string | null>(null);\n  /**\n   * Comentarios EN SITIO, sin salir del feed.\n   *\n   * Antes el botón de comentarios hacía `router.push('/lifebook-post/[id]')`: te sacaba del\n   * feed a otra pantalla y, al perder el foco, el vídeo se PAUSABA (`useFocusEffect` de\n   * abajo). O sea que leer los comentarios paraba el vídeo y te sacaba del inmersivo, que es\n   * justo lo contrario de lo que hace 小红书/TikTok y de lo que se pidió.\n   *\n   * Ahora se pinta la MISMA `CommentsSheet` (el componente que ya usa el detalle, sin\n   * tocarlo) encima del vídeo, y el vídeo SIGUE REPRODUCIÉNDOSE debajo.\n   *\n   * `allowComments` NO viene en el feed: está en `LbPostDetail`, no en `LbPostBase`. Por eso\n   * se abre con `true` y se corrige con el detalle en cuanto llega; suponerlo sin más\n   * enseñaría la caja de escribir en una publicación que tiene los comentarios cerrados.\n   */\n  const [comments, setComments] = useState<{ id: string; allowComments: boolean } | null>(null);\n  /**\n   * «Seguir viendo»: los vídeos que dejé a medias. Se carga al entrar y se enseña\n   * SOLO en el primer vídeo (ver `SeguirViendo`): el feed es inmersivo y una fila fija\n   * encima estorba en cuanto se desliza.\n   */\n  const [seguir, setSeguir] = useState<LbSeguirViendo[]>([]);\n\n  const listRef = useRef<FlatList<LbPostBase>>(null);\n  const busy = useRef(false);\n  const mounted = useRef(true);\n  const didInitialScroll = useRef(false);\n\n  useEffect(() => {\n    mounted.current = true;\n    return () => { mounted.current = false; };\n  }, []);\n\n  /* ── Carga ────────────────────────────────────────────────────────────────\n     Se pide `type: 'video'` al servidor (el parámetro existe y ya lo usa\n     `lifebook-explore.tsx`). Aun así se FILTRA en cliente por `videoUrl` real: un\n     post de tipo vídeo sin URL reproducible pintaría un rectángulo negro, y eso es\n     peor que no mostrarlo. */\n  const load = useCallback(async (mode: 'initial' | 'more') => {\n    if (busy.current) return;\n    busy.current = true;\n    if (mode === 'initial') { setLoading(true); setError(null); } else setLoadingMore(true);\n    try {\n      const page: LbFeedPage = await lifebookApi.feed(channel || 'for_you', {\n        city: city || undefined,\n        type: 'video',\n        cursor: mode === 'more' ? (cursor ?? undefined) : undefined,\n        limit: PAGE,\n      });\n      if (!mounted.current) return;\n      const withVideo = (page.posts ?? []).filter((p) => videoUrlOf(p) !== '');\n      setPosts((prev) => (mode === 'more' ? [...prev, ...withVideo] : withVideo));\n      setCursor(page.nextCursor ?? null);\n    } catch (e) {\n      if (!mounted.current) return;\n      setError(e instanceof Error ? e.message : 'No se pudieron cargar los vídeos.');\n    } finally {\n      busy.current = false;\n      if (mounted.current) { setLoading(false); setLoadingMore(false); }\n    }\n  }, [channel, city, cursor]);\n\n  useEffect(() => { void load('initial'); }, [channel, city]); // eslint-disable-line react-hooks/exhaustive-deps\n\n  /* ── Entrada B: empezar por el vídeo que se tocó en el masonry ─────────────\n     `initialScrollIndex` necesita el índice en el primer render, y aún no hay\n     datos. Se resuelve tras la primera carga con `scrollToIndex` sin animar. Si el\n     vídeo no viene en la primera página (puede pasar si el feed del masonry estaba\n     paginado), la lista se queda arriba: se avisa con el comentario de abajo en vez\n     de fingir que siempre funciona. */\n  useEffect(() => {\n    if (loading || didInitialScroll.current || posts.length === 0) return;\n    if (!startId) { didInitialScroll.current = true; return; }\n    const i = posts.findIndex((p) => p.id === startId);\n    didInitialScroll.current = true;\n    if (i > 0) {\n      // En el siguiente frame: la lista ya tiene `getItemLayout` y medida la altura.\n      requestAnimationFrame(() => {\n        listRef.current?.scrollToIndex({ index: i, animated: false });\n        setActive(i);\n      });\n    }\n  }, [loading, posts, startId]);\n\n  /* ── Foco: al abrir el detalle o el reproductor, PAUSAR ────────────────────\n     Sin esto el audio seguiría sonando encima de la otra pantalla, que es el fallo\n     más visible de un feed de vídeo. Al volver, se reanuda solo el visible. */\n  useFocusEffect(useCallback(() => {\n    setFocused(true);\n    return () => setFocused(false);\n  }, []));\n\n  const viewability = useRef<ViewabilityConfig>({\n    // Con `pagingEnabled` el vídeo asentado ocupa el 100 %; 60 % evita que el\n    // vecino cuente como visible a mitad de un deslizamiento.\n    viewAreaCoveragePercentThreshold: 60,\n  }).current;\n\n  // Callback ESTABLE por referencia: si se recrea en cada render, FlatList avisa y\n  // deja de notificar. De ahí el useRef con la lógica dentro.\n  const onViewable = useRef(({ viewableItems }: { viewableItems: ViewToken[]; changed: ViewToken[] }) => {\n    const first = viewableItems[0];\n    if (first?.index != null) {\n      setActive(first.index);\n      /* Al cambiar de vídeo se quita la pausa manual: el siguiente empieza reproduciendo…\n         SALVO si es LARGO. Un vídeo de 50 minutos no puede autoreproducirse (descargaría\n         cientos de MB sin que nadie lo haya pedido): arranca en pausa y el toque es el\n         permiso. Antes esto se conseguía con un `!esLargo` en el efecto de reproducción,\n         pero eso dejaba los largos sin forma de arrancarse; ahora es un estado. */\n      const item = first.item as LbPostBase | undefined;\n      const dur = Number((item?.payload as Record<string, unknown> | undefined)?.durationSec);\n      setPausedId(Number.isFinite(dur) && dur > LARGO_DESDE_SEC ? (item?.id ?? null) : null);\n    }\n  }).current;\n\n  /* ── ALTO REAL DE LA PÁGINA (medido, no supuesto) ───────────────────────────\n     `pagingEnabled` pagina por el alto del VIEWPORT de la lista. Si la página mide otra\n     cosa, cada página queda desalineada y **se ve un trozo de la de al lado** — que es\n     exactamente lo que se reportó.\n\n     Se usaba `useWindowDimensions().height`, y en Android esa altura NO es el hueco donde\n     vive la lista: puede incluir barras del sistema. La única altura que vale es la que la\n     propia lista reporta en `onLayout`, así que se mide y se usa ESA para las tres cosas\n     que tienen que coincidir: el alto de cada página, el `getItemLayout` y el paginado. */\n  const [pageH, setPageH] = useState(0);\n  const altoPagina = pageH > 0 ? pageH : H;\n\n  const getItemLayout = useCallback(\n    (_: ArrayLike<LbPostBase> | null | undefined, index: number) => ({\n      length: altoPagina, offset: altoPagina * index, index,\n    }),\n    [altoPagina],\n  );\n\n  /* ── Me gusta: optimista y con marcha atrás si el servidor falla ────────────\n     El mismo contrato que usa el feed (`lifebookActionsApi.toggleLike(id, liked)`),\n     para que el corazón no quede desincronizado entre las dos pantallas. */\n  const toggleLike = useCallback((id: string, liked: boolean) => {\n    setPosts((list) => list.map((p) => {\n      if (p.id !== id) return p;\n      const stats = p.stats ?? ({} as LbPostBase['stats']);\n      return {\n        ...p,\n        stats: { ...stats, likedByMe: liked, likes: Math.max(0, (stats.likes ?? 0) + (liked ? 1 : -1)) },\n      };\n    }));\n    lifebookActionsApi.toggleLike(id, liked).catch(() => {\n      setPosts((list) => list.map((p) => {\n        if (p.id !== id) return p;\n        const stats = p.stats ?? ({} as LbPostBase['stats']);\n        return {\n          ...p,\n          stats: { ...stats, likedByMe: !liked, likes: Math.max(0, (stats.likes ?? 0) + (liked ? -1 : 1)) },\n        };\n      }));\n    });\n  }, []);\n\n  /* ── [P6] Guardar: mismo patrón optimista que el like ───────────────────────\n     El endpoint ya existe (`toggleSave(postId, saved)` → `POST /posts/:id/save`).\n     Se actualiza `savedByMe` y `savedCount` en el post crudo para que el icono y\n     el contador no se desincronicen al deslizar y volver. */\n  const toggleSave = useCallback((id: string, saved: boolean) => {\n    setPosts((list) => list.map((p) => (p.id === id ? { ...p, savedByMe: saved } : p)));\n    lifebookActionsApi.toggleSave(id, saved).catch(() => {\n      setPosts((list) => list.map((p) => (p.id === id ? { ...p, savedByMe: !saved } : p)));\n    });\n  }, []);\n\n  /* ── Comentarios EN SITIO (sin salir del feed) ──────────────────────────────\n     Ver la nota de `comments` arriba. Lo importante de estas funciones: la hoja se abre YA\n     —sin esperar a la red, que por VPN puede tardar— y solo después se corrige\n     `allowComments` con lo que diga el detalle, que es donde vive ese dato. */\n  const openComments = useCallback((p: LbPostBase) => {\n    // `payload.allowComments` SÍ viaja en el feed. Comprobado contra el servidor: las claves\n    // del payload de un vídeo son `coverUrl, videoUrl, durationSec, allowComments,\n    // allowDownload`. Leyéndolo de ahí, en el caso normal NO hace falta ninguna petición y\n    // la hoja abre con el dato bueno desde el primer render (nada de enseñar la caja de\n    // escribir para luego quitarla).\n    const pl = (p.payload ?? {}) as Record<string, unknown>;\n    const conocido = typeof pl.allowComments === 'boolean' ? pl.allowComments : null;\n    setComments({ id: p.id, allowComments: conocido ?? true });\n    if (conocido !== null) return;\n    // Respaldo para publicaciones antiguas sin el campo: se pregunta al detalle y se corrige\n    // al llegar. La hoja ya está abierta, así que nadie espera por un booleano.\n    lifebookApi.post(p.id).then((d) => {\n      setComments((cur) => (cur && cur.id === p.id ? { id: p.id, allowComments: !!d.allowComments } : cur));\n    }).catch(() => {\n      /* Si el detalle falla, la lista de comentarios se carga dentro de la propia hoja. */\n    });\n  }, []);\n\n  /** La hoja avisa del total REAL; el contador de la columna derecha se actualiza con él. */\n  const onCommentsCount = useCallback((id: string, total: number) => {\n    setPosts((list) => list.map((p) => (\n      p.id === id ? { ...p, stats: { ...(p.stats ?? ({} as LbPostBase['stats'])), comments: total } } : p\n    )));\n  }, []);\n\n  // El usuario actual, para que la hoja marque los comentarios míos como míos.\n  useEffect(() => { authApi.me().then((m) => setMeId(m?.id ?? null)).catch(() => {}); }, []);\n\n  /** Los vídeos a medias, para la fila «Seguir viendo». Si falla, no se enseña nada. */\n  useEffect(() => {\n    watchApi.seguirViendo(12).then((l) => setSeguir(Array.isArray(l) ? l : [])).catch(() => {});\n  }, []);\n\n  /**\n   * Abre un vídeo de «seguir viendo». Si ya está en el feed se salta a él —y se\n   * reanuda solo, porque el progreso se lee al cargar la fuente—; si no está en la\n   * lista cargada, se abre el feed en ese vídeo con `startId`.\n   */\n  const abrirSeguir = useCallback((id: string) => {\n    const i = posts.findIndex((p) => p.id === id);\n    if (i >= 0) { listRef.current?.scrollToIndex({ index: i, animated: true }); return; }\n    irSeguro.libre('/lifebook-videos', { startId: id });\n  }, [posts, router]);\n\n  const renderItem = useCallback(({ item, index }: { item: LbPostBase; index: number }) => (\n    <VideoPage\n      post={item}\n      height={altoPagina}\n      isActive={index === active && focused}\n      muted={muted}\n      insets={{ top: insets.top, bottom: insets.bottom }}\n      onTogglePause={() => setPausedId((cur) => (cur === item.id ? null : item.id))}\n      paused={pausedId === item.id}\n      onLike={(liked) => toggleLike(item.id, liked)}\n      onSave={(saved) => toggleSave(item.id, saved)}\n      onSearchTopic={(topic) => router.push({\n        pathname: '/lifebook-search', params: { q: topic },\n      } as never)}\n      onOpenComments={() => openComments(item)}\n      onOpenDetail={() => irSeguro.libre('/lifebook-post/[id]', { id: item.id })}\n      /* Cuando los comentarios de ESTE vídeo están abiertos, el vídeo se ENCOGE\n         arriba en vez de quedarse debajo de la hoja. Es lo que hacen TikTok y\n         Xiaohongshu: el contenido no se tapa, se redimensiona. */\n      /* TANDA C: los productos que van DENTRO del vídeo (el sticker) se piden solo para el que\n         se está viendo: pedirlos para todos sería una petición por vídeo de la lista. */\n      productos={index === active ? (prodsVideo[item.id] ?? []) : []}\n      onOpenProduct={(pid) => irSeguro.libre('/lifebook-product/[id]', { id: pid })}\n      conComentarios={comments?.id === item.id}\n    />\n  ), [altoPagina, active, focused, muted, insets.top, insets.bottom, pausedId, toggleLike, toggleSave, router, openComments, comments, prodsVideo]);\n\n  const keyExtractor = useCallback((p: LbPostBase) => p.id, []);\n\n  return (\n    <View style={[s.root, { backgroundColor: '#000000' }]}>\n      {loading && posts.length === 0 ? (\n        <View style={s.center}>\n          <ActivityIndicator color={brand.white} />\n        </View>\n      ) : error && posts.length === 0 ? (\n        /*\n          La pantalla es NEGRA a propósito y el kit pinta con el tema: `sobreOscuro` evita texto\n          oscuro sobre negro. De paso, el error se anuncia al lector de pantalla y vibra.\n        */\n        <View style={s.center}>\n          <InlineError\n            sobreOscuro\n            mensaje={`No se pudieron cargar los vídeos. ${error}`}\n            onReintentar={() => { didInitialScroll.current = true; void load('initial'); }}\n          />\n        </View>\n      ) : posts.length === 0 ? (\n        <View style={s.center}>\n          <EmptyState\n            sobreOscuro\n            icono={<Text style={{ fontSize: 40 }}>🎬</Text>}\n            titulo=\"Todavía no hay vídeos aquí\"\n            texto=\"Cuando alguien publique un vídeo en este canal aparecerá en este feed.\"\n          />\n        </View>\n      ) : (\n        <FlatList\n          ref={listRef}\n          data={posts}\n          renderItem={renderItem}\n          keyExtractor={keyExtractor}\n          getItemLayout={getItemLayout}\n          pagingEnabled\n          /* El alto del hueco REAL donde vive la lista. Es la medida que hace que\n             `pagingEnabled` y el alto de página coincidan: sin ella, cada página queda\n             desalineada y se ve un trozo de la de al lado (ver `altoPagina`). */\n          style={{ flex: 1 }}\n          onLayout={(e) => {\n            const h = Math.round(e.nativeEvent.layout.height);\n            // Mismo objeto si no cambia: `onLayout` puede dispararse varias veces y no\n            // queremos un render por cada vez.\n            setPageH((cur) => (cur === h ? cur : h));\n          }}\n          /* ── PASO DE UN VÍDEO AL SIGUIENTE ───────────────────────────────────\n             Aquí se probaron `disableIntervalMomentum` y `decelerationRate=\"fast\"`,\n             razonando que un gesto rápido podía encadenar dos páginas. **Fue un error y\n             el dueño lo detectó probándolo**: el feed pasó a «resistirse» (el gesto se\n             frena en seco) y a dejar ver el vídeo de al lado, porque la lista se quedaba\n             en una posición intermedia en vez de encajar en la página.\n             `disableIntervalMomentum` hace exactamente eso: obliga a parar en el índice\n             siguiente ignorando la velocidad del dedo. Quitado.\n             Se deja `pagingEnabled` a secas, que es lo que ya funcionaba y lo que hace\n             que cada página encaje limpiamente. */\n          showsVerticalScrollIndicator={false}\n          viewabilityConfig={viewability}\n          onViewableItemsChanged={onViewable}\n          initialNumToRender={1}\n          maxToRenderPerBatch={1}\n          // 3 pantallas montadas: la visible y la de arriba/abajo. Es lo que da la\n          // precarga del siguiente sin tener decenas de reproductores vivos.\n          windowSize={3}\n          onEndReached={() => { if (cursor && !loadingMore) void load('more'); }}\n          onEndReachedThreshold={0.5}\n        />\n      )}\n\n      {/* Cabecera flotante: volver + sonido. Va encima del vídeo, no ocupa sitio. */}\n      <View style={[s.topBar, { paddingTop: insets.top + 8 }]} pointerEvents=\"box-none\">\n        <Pressable onPress={() => router.back()} hitSlop={12} style={s.iconBtn}\n          accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={brand.white} />\n        </Pressable>\n        <Pressable onPress={() => setMuted((m) => !m)} hitSlop={12} style={s.iconBtn}\n          accessibilityRole=\"button\"\n          accessibilityLabel={muted ? 'Activar el sonido' : 'Silenciar'}\n          accessibilityState={{ checked: !muted }}>\n          {muted ? <VolumeX size={20} color={brand.white} /> : <Volume2 size={20} color={brand.white} />}\n        </Pressable>\n      </View>\n\n      {/* ── SEGUIR VIENDO ────────────────────────────────────────────────────────\n          Va DEBAJO de la cabecera flotante (que es de una sola línea) para no tapar\n          los botones de volver y sonido, y solo en el primer vídeo: al primer\n          deslizamiento desaparece y el feed vuelve a ser inmersivo. */}\n      {active === 0 && seguir.length > 0 ? (\n        <SeguirViendo\n          items={seguir}\n          colors={colors}\n          top={insets.top + 58}\n          onOpen={abrirSeguir}\n          onQuitar={(id) => {\n            setSeguir((l) => l.filter((x) => x.id !== id));\n            watchApi.borrar(id).catch(() => { /* si falla, vuelve en la próxima entrada */ });\n          }}\n        />\n      ) : null}\n\n      {loadingMore && (\n        <View style={[s.moreBox, { paddingBottom: insets.bottom + 10 }]} pointerEvents=\"none\">\n          <ActivityIndicator color={brand.white} />\n        </View>\n      )}\n\n      {/* ── COMENTARIOS ENCIMA DEL VÍDEO, SIN TAPARLO ────────────────────────────\n          Es la MISMA `CommentsSheet` que usa el detalle, sin duplicar nada: ya es un\n          `Modal` transparente con la hoja abajo, que es la forma que hace falta.\n          Dos ajustes que sólo tienen sentido AQUÍ y por eso son props opcionales (el\n          detalle sigue con sus valores de siempre):\n\n          · `dimBackdrop={0}` — el velo oscuro que en el detalle ayuda a leer, aquí TAPA\n            el vídeo. Debajo hay un vídeo reproduciéndose: en 小红书/TikTok se lee con el\n            vídeo a plena luz. El velo sigue ocupando la pantalla (para cerrar tocando\n            fuera) pero es invisible.\n          · `maxHeightPct={55}` — con el 80 % de antes, unos cuantos comentarios tapaban\n            el vídeo ENTERO y el usuario dejaba de ver un vídeo para ver una lista. Con\n            55 % el vídeo conserva casi la mitad de la pantalla siempre.\n\n          El vídeo sigue reproduciéndose porque NO se navega: se queda el foco, así que el\n          `useFocusEffect` de arriba no lo pausa. Para que se VEA detrás del `Modal`, el\n          `VideoView` tiene que ser `textureView` (ver el comentario allí). */}\n      <CommentsSheet\n        visible={!!comments}\n        onClose={() => setComments(null)}\n        postId={comments?.id ?? ''}\n        tint={colors.primary}\n        allowComments={comments?.allowComments ?? true}\n        meId={meId}\n        title=\"Comentarios\"\n        placeholder=\"Añade un comentario...\"\n        dimBackdrop={0}\n        maxHeightPct={55}\n        onCountChange={(total) => { if (comments) onCommentsCount(comments.id, total); }}\n      />\n    </View>\n  );\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Una página = un vídeo\n// ─────────────────────────────────────────────────────────────────────────────\n\nfunction VideoPage({ post, height, isActive, muted, paused, onTogglePause, onLike, onSave, onSearchTopic, onOpenComments, onOpenDetail, onOpenProduct, productos = [], insets, conComentarios = false }: {\n  post: LbPostBase; height: number; isActive: boolean; muted: boolean; paused: boolean;\n  /** Si los comentarios de ESTE vídeo están abiertos: el vídeo se encoge arriba. */\n  conComentarios?: boolean;\n  onTogglePause: () => void; onLike: (liked: boolean) => void; onSave: (saved: boolean) => void;\n  onSearchTopic: (topic: string) => void;\n  onOpenComments: () => void;\n  onOpenDetail: () => void;\n  /** TANDA C: abrir el producto del sticker (lleva a su ficha, donde se compra). */\n  onOpenProduct: (productId: string) => void;\n  /** TANDA C: productos enganchados a este vídeo (se pintan como sticker). */\n  productos?: LbProductoEnNota[];\n  insets: { top: number; bottom: number };\n}) {\n  const { colors } = useTheme();\n  const src = useMemo(() => videoUrlOf(post), [post]);\n  const cover = useMemo(() => coverOf(post), [post]);\n  const topics = useMemo(() => topicsOf(post), [post]);\n  /* TANDA C: si el sticker del producto está desplegado (cerrado solo enseña el precio). */\n  const [stickerAbierto, setStickerAbierto] = useState(false);\n\n  /** Duración declarada al publicar (la que verificó el servidor con ffprobe). */\n  const dur = Number((post.payload as Record<string, unknown>)?.durationSec);\n  const durOk = Number.isFinite(dur) && dur > 0;\n  const esLargo = durOk && dur > LARGO_DESDE_SEC;\n\n  const [liked, setLiked] = useState(!!post.stats?.likedByMe);\n  const [likes, setLikes] = useState(post.stats?.likes ?? 0);\n  const [saved, setSaved] = useState(!!post.savedByMe);\n  const [heartPop, setHeartPop] = useState(false);\n  /**\n   * [P4] La portada solo tapa HASTA que hay fotograma real. Antes se ataba al estado\n   * de pausa y al pausar volvía a aparecer encima del vídeo — el bug grave que\n   * reportó el dueño. `onFirstFrameRender` de `VideoView` es justo el evento para\n   * esto (lo dice su propia doc: \"hide any cover images that conceal the initial\n   * loading of the player\").\n   */\n  const [firstFrame, setFirstFrame] = useState(false);\n  const popTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n  // El estado real puede llegar después (recarga silenciosa del feed).\n  useEffect(() => { setLiked(!!post.stats?.likedByMe); }, [post.stats?.likedByMe]);\n  useEffect(() => { setLikes(post.stats?.likes ?? 0); }, [post.stats?.likes]);\n  useEffect(() => { setSaved(!!post.savedByMe); }, [post.savedByMe]);\n  // Cambiar de fuente vuelve a necesitar portada: sin esto, al reciclar la celda\n  // (FlatList reutiliza componentes) se vería el vídeo anterior un instante.\n  useEffect(() => { setFirstFrame(false); }, [src]);\n  useEffect(() => () => { if (popTimer.current) clearTimeout(popTimer.current); }, []);\n\n  const player = useVideoPlayer(src || null, (p) => {\n    // En bucle, como en todo feed inmersivo: al terminar, vuelve a empezar en vez de\n    // quedarse en un fotograma negro. (`/lifebook-player` usa loop=false, que allí\n    // sí tiene sentido: es reproducción de detalle.)\n    // Los LARGOS no: repetir 50 minutos no es un feed, es un error.\n    p.loop = !esLargo;\n    p.muted = muted;\n    // 0.25 s en vez de los 0.5 por defecto: la línea de tiempo se mueve fluida sin\n    // disparar un render cada 50 ms.\n    p.timeUpdateEventInterval = 0.25;\n  });\n\n  /* ── LÍNEA DE TIEMPO (lo que se perdió al quitar el reproductor a pantalla completa) ──\n     El reproductor externo tenía barra de progreso y tiempos; al retirarlo, **el vídeo se\n     quedó sin ninguna referencia de por dónde va**. En un clip de 12 s da igual, pero en un\n     vídeo de 50 minutos no saber si vas por el minuto 3 o por el 40 es lo que hace que la\n     gente no vea vídeos largos.\n\n     Se recupera DENTRO del único estado de vídeo que hay, con la forma que usan 小红书 y\n     TikTok en el feed: una línea fina pegada al borde inferior, que se rellena. */\n  /* Se llaman `tl*` (timeline) y NO `cur`/`dur` a propósito: en esta función `dur` ya\n     existe y es la duración DECLARADA en el post (`payload.durationSec`, la que decide si\n     el vídeo es corto o largo). La de aquí es la que mide el reproductor al cargar. */\n  const [tlCur, setTlCur] = useState(0);\n  const [tlDur, setTlDur] = useState(0);\n  /** Mientras se mantiene pulsado: la barra se ve y se arrastra. */\n  const [scrubbing, setScrubbing] = useState(false);\n  /** Posición que marca el dedo mientras se arrastra (null = manda la reproducción). */\n  const [tlSeek, setTlSeek] = useState<number | null>(null);\n  /** Espejo en ref para que `scrubEnd` sea idempotente: `onEnd` y `onFinalize` pueden\n   *  llegar los dos, y reanudar dos veces (o reanudar sin haber arrastrado) se nota. */\n  const scrubbingRef = useRef(false);\n  const mountedRef = useRef(true);\n  useEffect(() => { mountedRef.current = true; return () => { mountedRef.current = false; }; }, []);\n\n  /* ── SEGUIR VIENDO (progreso de reproducción) ────────────────────────────────\n     El tiempo y la duración se copian también a REFS: al desmontar la pantalla hay\n     que guardar lo último que se vio, y justo entonces el estado del componente ya no\n     es de fiar. Y reanudar es UNA vez por vídeo: si no, cada repintado pelearía con\n     quien está mirando. */\n  const tiempoRef = useRef(0);\n  const durRef = useRef(0);\n  const reanudadoRef = useRef(false);\n\n  useEffect(() => {\n    if (!src) return;\n    const subs = [\n      player.addListener('timeUpdate', (e) => {\n        tiempoRef.current = e.currentTime;      // para poder guardarlo al desmontar\n        if (mountedRef.current) setTlCur(e.currentTime);\n      }),\n      player.addListener('sourceLoad', (e) => {\n        const dur = Number.isFinite(e.duration) ? e.duration : 0;\n        durRef.current = dur;\n        if (mountedRef.current) setTlDur(dur);\n      }),\n    ];\n    return () => { subs.forEach((s) => s.remove()); };\n  }, [player, src]);\n\n  /* Autoplay SOLO del visible, y pausa del resto. Es el corazón de B1: sin esto,\n     todos los vídeos montados reproducirían a la vez (audio solapado y datos).\n\n     OJO con `esLargo`: aquí NO se usa. Antes la condición era `isActive && !paused &&\n     !esLargo`, y eso tenía un fallo que apareció al quitar el reproductor externo: un vídeo\n     LARGO no se autoreproducía (bien) pero el toque TAMPOCO podía arrancarlo nunca (mal),\n     porque el toque sólo quitaba la pausa y el candado del largo seguía puesto. Ahora la\n     pausa inicial de un largo es un ESTADO (`pausedId`, ver `onViewable`) y el toque la\n     quita: el largo sigue sin autoreproducirse, pero se reproduce cuando el usuario lo pide. */\n  useEffect(() => {\n    if (!src) return;\n    if (isActive && !paused) {\n      player.play();\n    } else {\n      player.pause();\n    }\n  }, [isActive, paused, player, src]);\n\n  // El silencio es global (un botón en la cabecera), así que se sincroniza aquí.\n  useEffect(() => { player.muted = muted; }, [muted, player]);\n\n  /* El BUCLE también se sincroniza aquí, y no sólo al crear el reproductor.\n     Estaba puesto únicamente dentro del `setup` de `useVideoPlayer`, y medido en el aparato\n     eso NO basta: se entraba al feed, el clip se reproducía y **al llegar al final se\n     quedaba clavado en el último fotograma** en vez de repetir — que es justo lo que un feed\n     inmersivo no puede hacer (el vídeo siguiente no llega solo, y la pantalla se ve muerta).\n     Dejarlo como efecto, igual que el silencio, hace que el valor se aplique cuando el\n     reproductor ya está listo y no sólo en su construcción. */\n  useEffect(() => { player.loop = !esLargo; }, [player, esLargo]);\n\n  /* ── SEGUIR VIENDO: reanudar y guardar ──────────────────────────────────────\n     Hasta esta ronda no había NINGUNA forma de reanudar un vídeo (no existía ni el\n     dato: se buscó `progress|position|resume` en la app y lo único que salía era el\n     progreso de SUBIDA). Esto es lo que hace que «seguir viendo» sea de verdad. */\n\n  /**\n   * REANUDAR: al pasar a ser el vídeo activo y con la fuente YA cargada —antes de eso\n   * el reproductor no admite saltar y `currentTime` se ignora—, se salta a donde lo\n   * dejó. Solo si de verdad iba por la mitad: ni recién empezado (5 s) ni casi\n   * acabado (90 %), el mismo criterio que usa el servidor para la lista.\n   */\n  useEffect(() => {\n    if (!isActive || !src || reanudadoRef.current || tlDur <= 0) return;\n    reanudadoRef.current = true;\n    watchApi.leer(post.id).then((p) => {\n      const pos = Number(p?.positionSec ?? 0);\n      const total = Number(p?.durationSec ?? 0) || tlDur;\n      if (!mountedRef.current) return;\n      if (pos >= 5 && (!total || pos < total * 0.9)) {\n        tiempoRef.current = pos;\n        player.currentTime = pos;\n      }\n    }).catch(() => { /* sin progreso, se empieza del principio */ });\n  }, [isActive, src, tlDur, post.id, player]);\n\n  /** Guarda dónde va. Lee de los refs porque también se llama al desmontar. */\n  const guardarAhora = useCallback(() => {\n    const t = Math.floor(tiempoRef.current);\n    if (!post?.id || t < 1) return;\n    watchApi.guardar(post.id, t, Math.floor(durRef.current)).catch(() => { /* no se le cuenta al usuario */ });\n  }, [post?.id]);\n\n  /* Tres momentos y ni uno más, para no machacar el servidor: cada 15 s mientras se\n     reproduce, al dejar de ser el vídeo activo, y al salir de la pantalla. */\n  useEffect(() => {\n    if (!isActive) return;\n    const id = setInterval(() => { if (!paused) guardarAhora(); }, 15000);\n    return () => clearInterval(id);\n  }, [isActive, paused, guardarAhora]);\n\n  useEffect(() => { if (!isActive) guardarAhora(); }, [isActive, guardarAhora]);\n  useEffect(() => () => { guardarAhora(); }, [guardarAhora]);\n\n  /* ── ¿LLENAR O ENCAJAR? — fuera la franja negra ──────────────────────────────\n     El móvil es 1080x2374 = 2,20:1, bastante más alto que un vídeo 9:16 (1,78:1). Con\n     `contain` un 9:16 deja DOS FRANJAS NEGRAS de ~227 px (el 19 % de la pantalla), y es\n     exactamente lo que se reportó como «una franja negra que dificulta la vista».\n\n     Lo que hacen las plataformas de vídeo vertical: LLENAR cuando el contenido es\n     vertical —que es el caso normal, y el recorte que cuesta es pequeño— y, para lo que\n     no encaja (un vídeo horizontal en una pantalla altísima), enseñarlo ENTERO sobre un\n     FONDO DESENFOCADO del propio vídeo en vez de sobre negro.\n\n     Se decide con el tamaño REAL del vídeo, que `expo-video` publica en\n     `player.videoTrack.size` (no hay que pedírselo a nadie ni adivinarlo). Se mide lo que\n     costaría llenar: si recortar se lleva más del 25 % del vídeo, se encaja.\n       · 9:16 en esta pantalla → cuesta 19 % → se LLENA (es lo que hace TikTok)\n       · 16:9 en esta pantalla → costaría 74 % → se ENCAJA sobre fondo desenfocado */\n  const { width: vpW, height: vpH } = useWindowDimensions();\n  const [tamVideo, setTamVideo] = useState<{ w: number; h: number } | null>(null);\n\n  useEffect(() => {\n    if (!src) { setTamVideo(null); return; }\n    const leer = () => {\n      const s = player.videoTrack?.size;\n      if (!s || s.width <= 0 || s.height <= 0) return;\n      /* Devolver EL MISMO objeto cuando el tamaño no cambia es lo que evita un render por\n         cada evento. `statusChange` se dispara muchas veces (carga, buffer, listo…), y\n         crear un `{...}` nuevo cada vez hacía re-renderizar la página constantemente: eso\n         se nota como tirones al pasar de un vídeo a otro. React se salta el render si el\n         estado es idéntico por referencia. */\n      setTamVideo((cur) => (cur && cur.w === s.width && cur.h === s.height ? cur : { w: s.width, h: s.height }));\n    };\n    leer();\n    // Se lee en los dos eventos porque el track puede no estar listo todavía en\n    // `sourceLoad` según el contenedor; `statusChange` cubre el caso de que llegue tarde.\n    const subs = [\n      player.addListener('sourceLoad', leer),\n      player.addListener('statusChange', leer),\n    ];\n    return () => { subs.forEach((s) => s.remove()); };\n  }, [player, src]);\n\n  /** Fracción del vídeo que se perdería al llenar la pantalla (0…1), o null si aún no se sabe. */\n  const recorteAlLlenar = useMemo(() => {\n    if (!tamVideo || vpW <= 0 || vpH <= 0) return null;\n    const escala = Math.max(vpW / tamVideo.w, vpH / tamVideo.h);\n    const rw = tamVideo.w * escala;\n    const rh = tamVideo.h * escala;\n    return 1 - Math.min(vpW / rw, vpH / rh);\n  }, [tamVideo, vpW, vpH]);\n\n  // Sin tamaño todavía se LLENA: es preferible un recorte momentáneo a una franja negra\n  // en cuanto entra el vídeo.\n  const llenar = recorteAlLlenar == null || recorteAlLlenar <= RECORTE_MAX;\n\n  /* ── [P5] QUITADO: aquí vivía el zoom con los dedos (pinza + arrastre) ────────\n     Se fue entero en la segunda ronda con el aparato: el dueño pidió que el vídeo NO\n     se pueda ampliar con los dedos. Se eliminan los seis shared values, el estado\n     `zoomed`, los dos reconocedores (`Gesture.Pinch` y `Gesture.Pan`) y el\n     `useAnimatedStyle` que los aplicaba.\n\n     Efecto secundario bueno: al no haber `transform` sobre el vídeo, desaparece\n     `surfaceType=\"textureView\"`, que existía SOLO para que la pinza se viera. El\n     `surfaceView` por defecto gasta menos batería.\n\n     Quedan los TAPES, que no se tocan: doble = me gusta, simple = pausa/reanudar. */\n\n  const applyLike = (next: boolean) => {\n    setLiked(next);\n    setLikes((n) => Math.max(0, n + (next ? 1 : -1)));\n    onLike(next);\n  };\n\n  /** Doble toque = me gusta + corazón grande. Mismo patrón y mismos tiempos que\n   *  `PostCard.tsx` (260 ms de ventana, 650 ms de corazón), para que el gesto se\n   *  sienta igual en el masonry y aquí. No vibra: `expo-haptics` no está instalado. */\n  const doubleTapLike = () => {\n    if (!liked) applyLike(true);\n    setHeartPop(true);\n    if (popTimer.current) clearTimeout(popTimer.current);\n    popTimer.current = setTimeout(() => setHeartPop(false), 650);\n  };\n  // Un toque: pausa/reanuda, SIEMPRE. Antes un vídeo LARGO abría el reproductor a pantalla\n  // completa; ahora que ese reproductor ya no existe, el toque arranca el vídeo AQUÍ. El\n  // largo sigue SIN autoreproducirse (para no descargar cientos de MB sin permiso), así que\n  // el toque es exactamente el permiso que faltaba.\n  const singleTap = () => onTogglePause();\n\n  /* ── Mantener pulsado: barrita visible + arrastrar para avanzar ──────────────\n     El gesto lo lanza `scrub` (ver `composed`), que sólo se activa con el dedo quieto\n     280 ms. Estas tres funciones son el lado JS. */\n  const scrubStart = () => {\n    scrubbingRef.current = true;\n    setScrubbing(true);\n    setTlSeek(tlCur);\n    // Se pausa para que lo que se ve sea el fotograma del punto al que apuntas, y para que\n    // el vídeo no siga avanzando mientras el dedo decide. Al soltar se reanuda si tocaba.\n    player.pause();\n  };\n  const scrubMove = (x: number) => {\n    if (tlDur <= 0 || vpW <= 0) return;\n    const ratio = Math.max(0, Math.min(1, x / vpW));\n    const t = ratio * tlDur;\n    // `expo-video` 2.2.3 no tiene `seekTo()`: se salta escribiendo `currentTime`.\n    player.currentTime = t;\n    setTlSeek(t);\n  };\n  const scrubEnd = () => {\n    // Idempotente: `onEnd` y `onFinalize` pueden llegar los dos.\n    if (!scrubbingRef.current) return;\n    scrubbingRef.current = false;\n    setScrubbing(false);\n    setTlSeek(null);\n    // Se reanuda sólo si este vídeo es el visible y no estaba pausado a propósito.\n    if (isActive && !paused) player.play();\n  };\n\n  /* [P6] Compartir. `Share` es de React Native (ya se usa en `lifebook-post/[id].tsx`\n     y en alquiler/trabajo), así que no hace falta dependencia nueva. En Android solo\n     se admite `message`+`title` (la `url` es de iOS), de ahí el enlace dentro del\n     texto — es lo mismo que hace el detalle de la publicación. */\n  const share = () => {\n    const t = post.title?.trim() || post.body?.trim() || 'Vídeo';\n    Share.share({ message: `${t} — Life Book · EG Route Plan` }).catch(() => {});\n  };\n\n  const taps = Gesture.Exclusive(\n    Gesture.Tap().numberOfTaps(2).maxDuration(260).onEnd(() => { runOnJS(doubleTapLike)(); }),\n    Gesture.Tap().numberOfTaps(1).onEnd(() => { runOnJS(singleTap)(); }),\n  );\n\n  /* ── BARRITA DE TIEMPO AL MANTENER PULSADO (como TikTok/Douyin) ───────────────\n     `activateAfterLongPress(280)` es la pieza que lo hace posible sin arriesgar el pase de\n     vídeo: el gesto **no puede activarse hasta que el dedo lleva 280 ms quieto**. Un toque\n     rápido no lo activa, y un deslizamiento normal tampoco —el dedo se mueve antes de los\n     280 ms y el requisito deja de cumplirse—, así que la lista se queda con su gesto de\n     siempre.\n\n     Y va en `Gesture.Race` con los toques: gana el primero que se active y el otro se\n     cancela. Con un toque rápido gana el toque (no hay pausa doble al soltar); con un\n     mantenido gana el arrastre, y al soltar NO se dispara además un toque que pausara el\n     vídeo. `Exclusive` no valdría: ahí el primero de la lista tiene prioridad y los toques\n     esperarían a que el mantenido falle, o sea que pausar tardaría 280 ms en responder. */\n  const scrub = Gesture.Pan()\n    .activateAfterLongPress(280)\n    .onStart(() => { runOnJS(scrubStart)(); })\n    .onUpdate((e) => { runOnJS(scrubMove)(e.x); })\n    .onEnd(() => { runOnJS(scrubEnd)(); })\n    // `onFinalize` cubre también la cancelación (el sistema se queda el gesto, una llamada\n    // entrante…): sin él, la barra se quedaría pegada en pantalla.\n    .onFinalize(() => { runOnJS(scrubEnd)(); });\n\n  const composed = Gesture.Race(scrub, taps);\n\n  const authorName = post.author?.fullName?.trim() || post.author?.name?.trim() || 'Usuario';\n  const title = post.title?.trim() || post.body?.trim() || '';\n\n  /** 0…100 para la barra. Mientras se arrastra manda el dedo, no la reproducción. */\n  const tlPct = tlDur > 0 ? Math.min(100, ((tlSeek ?? tlCur) / tlDur) * 100) : 0;\n\n  /**\n   * [P8] Términos de la fila «Búsquedas relacionadas», como la barra de 小红书.\n   *\n   * El fallo que apareció EN EL APARATO: casi ningún vídeo publicado hasta hoy lleva\n   * temas (`topics`/`tags` vienen vacíos), así que la fila **no se pintaba nunca** y\n   * desde fuera parecía que la función no existía. Eso no es un detalle de estilo: una\n   * función que no se ve es una función que no está.\n   *\n   * Ahora, si no hay temas, se cae a lo que el post SÍ trae — ciudad, autor y las\n   * primeras palabras del título — de forma que la fila sale siempre. El título es\n   * obligatorio al publicar vídeo, así que el último recurso nunca falta.\n   */\n  const relTerms = useMemo(() => {\n    const out: string[] = [];\n    const push = (raw: unknown) => {\n      const v = String(raw ?? '').trim().replace(/\\s+/g, ' ').slice(0, 24);\n      if (v && !out.includes(v) && out.length < 6) out.push(v);\n    };\n    for (const t of topics) push(t);\n    if (out.length === 0) {\n      push(post.city);\n      push(post.author?.fullName ?? post.author?.name);\n      push(title.split(/\\s+/).slice(0, 3).join(' '));\n    }\n    return out;\n  }, [topics, post.city, post.author?.fullName, post.author?.name, title]);\n\n  return (\n    <View style={{ height, width: '100%', backgroundColor: '#000000' }}>\n      <GestureDetector gesture={composed}>\n        <View style={conComentarios\n          ? {\n              // CON LOS COMENTARIOS ABIERTOS el vídeo NO se queda debajo de la hoja: se\n              // encoge y se va arriba. El 42 % es lo que deja libre la hoja del feed\n              // (`maxHeightPct={55}`) con un poco de aire, y así el vídeo se sigue viendo\n              // ENTERO mientras se leen los comentarios. Es lo que hacen TikTok y\n              // Xiaohongshu (ver docs/COMENTARIOS-QUE-NO-TAPEN-EL-CONTENIDO.md): el\n              // contenido se redimensiona, no se tapa.\n              //\n              // El alto de la PÁGINA no cambia a propósito: si cambiara, el feed (que está\n              // paginado por alto de página) saltaría de vídeo al abrir los comentarios.\n              position: 'absolute', left: 0, right: 0, top: 0,\n              height: Math.round(height * 0.42),\n              overflow: 'hidden',\n            }\n          : StyleSheet.absoluteFill}>\n          {src ? (\n            <>\n              {/* FONDO, solo cuando el vídeo NO llena la pantalla. Es el propio póster\n                  desenfocado y ampliado, así que las bandas dejan de ser NEGRAS y pasan a\n                  ser una continuación difusa del vídeo. Es lo que hacen YouTube y Reels\n                  con el contenido que no es vertical: nunca una franja negra.\n                  No se pinta cuando sí se llena: ahí no hay banda que tapar y ahorramos\n                  una capa de imagen por página. */}\n              {(!llenar || conComentarios) && cover ? (\n                <Image\n                  source={cover}\n                  style={StyleSheet.absoluteFill}\n                  contentFit=\"cover\"\n                  blurRadius={28}\n                  cachePolicy=\"memory-disk\"\n                />\n              ) : null}\n\n              <VideoView\n                player={player}\n                style={StyleSheet.absoluteFill}\n                // LLENAR o ENCAJAR, decidido con el tamaño real del vídeo: ver el\n                // comentario largo de `recorteAlLlenar`. En corto: si parece a la pantalla\n                // se llena (fuera franja negra); si no, se enseña entero sobre el fondo\n                // desenfocado de arriba.\n                // Encogido SIEMPRE `contain`: en una caja más pequeña, recortar (cover)\n                // cortaría media imagen. Así se ve el fotograma entero, con el fondo\n                // desenfocado alrededor.\n                contentFit={conComentarios ? 'contain' : (llenar ? 'cover' : 'contain')}\n                // `textureView` por un motivo de verdad: la hoja de comentarios es un\n                // `Modal` (otra ventana) y el `surfaceView` por defecto no compone con nada\n                // que lo tape — el vídeo se vería como un agujero NEGRO detrás de los\n                // comentarios. La doc de expo-video lo dice con estas palabras:\n                // `textureView` es para «overlapping video views». Cuesta más batería, y es\n                // el precio de poder leer los comentarios con el vídeo corriendo debajo.\n                surfaceType=\"textureView\"\n                // Sin controles nativos: tap = pausa/reanudar. No hay más estado de vídeo\n                // que este (el reproductor a pantalla completa se retiró).\n                nativeControls={false}\n                allowsFullscreen={false}\n                // [P4] Es lo que arregla el bug de la portada al pausar.\n                onFirstFrameRender={() => setFirstFrame(true)}\n              />\n            </>\n          ) : cover ? (\n            <Image source={cover} style={StyleSheet.absoluteFill} contentFit=\"cover\" cachePolicy=\"memory-disk\" />\n          ) : null}\n\n          {/* [P4] Portada encima SOLO hasta que hay fotograma real. Ya no depende de\n              `paused`, que era lo que la hacía reaparecer al pausar. */}\n          {src && cover && !firstFrame ? (\n            <Image\n              source={cover}\n              style={StyleSheet.absoluteFill}\n              contentFit={conComentarios ? 'contain' : 'cover'}\n              cachePolicy=\"memory-disk\"\n              transition={200}\n              pointerEvents=\"none\"\n            />\n          ) : null}\n\n          {/* Pausa: indicador central, como en TikTok. Es el ÚNICO botón en el centro\n              del vídeo ([P1]: fuera los ±5 s y ±15 s, que vivían en el reproductor). */}\n          {paused && isActive && !esLargo ? (\n            <View style={s.pauseDot} pointerEvents=\"none\">\n              <Text style={{ fontSize: 26, color: brand.white }}>▶</Text>\n            </View>\n          ) : null}\n\n          {/* VÍDEO LARGO: no se reproduce solo, para no descargar cientos de MB sin\n              permiso. Se ve su portada con la duración y un ▶, y el toque lo reproduce\n              AQUÍ MISMO (el reproductor externo ya no existe). */}\n          {esLargo ? (\n            <View style={s.largoBox} pointerEvents=\"none\">\n              <View style={s.largoPlay}>\n                <Text style={{ fontSize: 30, color: brand.white, marginLeft: espaciado.e4 }}>▶</Text>\n              </View>\n              <Text style={s.largoTxt}>\n                Vídeo de {fmtDur(dur)}{'\\n'}\n                <Text style={s.largoSub}>Toca para reproducirlo</Text>\n              </Text>\n            </View>\n          ) : null}\n\n          {/* Corazón del doble toque */}\n          {heartPop ? (\n            <View style={s.heartPop} pointerEvents=\"none\">\n              <Heart size={92} color={LIKE_RED} fill={LIKE_RED} />\n            </View>\n          ) : null}\n        </View>\n      </GestureDetector>\n\n      {/* ── BARRITA DE TIEMPO: aparece al MANTENER PULSADO, como TikTok/Douyin ──────\n          Al retirar el reproductor a pantalla completa, el vídeo se quedó sin ninguna\n          referencia de por dónde va, y en un vídeo de 50 minutos eso es lo que hace que la\n          gente no los vea. Investido cómo lo hacen ellas (ver\n          `docs/LINEA-DE-TIEMPO-INVESTIGACION.md`): **TikTok, Douyin y Xiaohongshu NO llevan\n          barra permanente en el feed** — en TikTok/Douyin aparece al mantener pulsado y ahí\n          se arrastra para avanzar; en Xiaohongshu mantener pulsado abre la velocidad. La\n          permanente es YouTube Shorts, y no es lo que se pidió.\n\n          Así que: el feed se queda limpio, y la barra sale al mantener pulsado, con el\n          tiempo a la vista para saber a dónde vas. Al soltar se oculta y el vídeo sigue.\n\n          Detalles que no son decoración:\n          · Se pinta SÓLO en la página visible (`isActive`): si se pintara en todas, se\n            asomaría también en el trozo de la de al lado.\n          · No es interactiva por sí misma; el dedo lo lee el gesto `scrub`, que es quien\n            hace el trabajo. Un elemento táctil pegado al borde inferior es justo lo que hay\n            que evitar: ahí abajo el sistema se queda los deslizamientos. */}\n      {isActive && scrubbing && tlDur > 0 ? (\n        <>\n          <View style={s.tlTime} pointerEvents=\"none\">\n            <Text style={s.tlTimeTxt}>{fmtDur(tlSeek ?? tlCur)} / {fmtDur(tlDur)}</Text>\n          </View>\n          <View style={s.tlLine} pointerEvents=\"none\">\n            <View style={[s.tlFill, { width: `${tlPct}%` }]} />\n          </View>\n        </>\n      ) : null}\n\n      {/* Degradado inferior para que el texto se lea sobre el vídeo. Se genera por franjas\n          (ver `BottomScrim`): antes era un rectángulo PLANO con un borde recto que se veía\n          como una capa negra pegada encima del vídeo. */}\n      <BottomScrim height={250 + insets.bottom} max={0.62} />\n\n      {/* Columna de acciones (derecha), como en 小红书/TikTok.\n          [P6] ahora con compartir y guardar además de like y comentarios. */}\n      <View style={[s.actions, { bottom: insets.bottom + 96 }]} pointerEvents=\"box-none\">\n        <Pressable onPress={() => applyLike(!liked)} hitSlop={10} style={s.actBtn}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Me gusta${likes ? `, ${likes}` : ''}`}\n          accessibilityState={{ selected: liked }}>\n          <Heart size={27} color={liked ? LIKE_RED : brand.white} fill={liked ? LIKE_RED : 'none'} />\n          <Text style={s.actN}>{fmtCount(likes)}</Text>\n        </Pressable>\n\n        {/* Comentarios: abre la hoja ENCIMA del vídeo, sin salir del feed.\n            Antes hacía `onOpenDetail` (navegaba a `/lifebook-post/[id]`), y al perder el\n            foco esta pantalla PAUSABA todos los vídeos: leer los comentarios paraba el\n            vídeo y te sacaba del inmersivo. Ahora el vídeo sigue sonando debajo. */}\n        <Pressable onPress={onOpenComments} hitSlop={10} style={s.actBtn}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Comentarios${post.stats?.comments ? `, ${post.stats.comments}` : ''}`}>\n          <MessageCircle size={26} color={brand.white} />\n          <Text style={s.actN}>{fmtCount(post.stats?.comments ?? 0)}</Text>\n        </Pressable>\n\n        {/* [P6] Guardar: el endpoint ya existe (`toggleSave`). Rellenado cuando está\n            guardado, igual que el corazón. */}\n        <Pressable onPress={() => { const next = !saved; setSaved(next); onSave(next); }}\n          hitSlop={10} style={s.actBtn}\n          accessibilityRole=\"button\"\n          accessibilityLabel={saved ? 'Quitar de guardados' : 'Guardar'}\n          accessibilityState={{ selected: saved }}>\n          <Bookmark size={25} color={brand.white} fill={saved ? brand.white : 'none'} />\n        </Pressable>\n\n        {/* [P6] Compartir. Sin contador: el servidor no da \"veces compartido\". */}\n        <Pressable onPress={share} hitSlop={10} style={s.actBtn}\n          accessibilityRole=\"button\" accessibilityLabel=\"Compartir\">\n          <Share2 size={25} color={brand.white} />\n        </Pressable>\n\n        {/* ❌ AQUÍ ESTABA «Ver a pantalla completa» (icono `Maximize` → `/lifebook-player`).\n            Se quitó junto con el reproductor: **sólo hay UN estado de ver vídeo, éste.**\n            Dos pantallas para lo mismo obligaban a mantener dos juegos de controles, dos\n            listas de gestos y dos sitios donde arreglar cada fallo, y el dueño lo pidió\n            explícitamente («sólo debe existir un estado de ver vídeos, el inmersivo»).\n            Si algún día hace falta verlo más grande, es ESTA pantalla la que crece. */}\n      </View>\n\n      {/* Texto inferior: autor, título, duración y [P8] la fila de «Búsquedas relacionadas». */}\n      <View style={[s.info, { paddingBottom: insets.bottom + 14 }]} pointerEvents=\"box-none\">\n        {/* TANDA C — EL STICKER DEL PRODUCTO, encima del vídeo y abajo a la izquierda, como en\n            Xiaohongshu. Cerrado enseña la miniatura y el precio; al tocarlo se abre y aparece\n            el nombre y el botón de compra. Es un atajo dentro del vídeo, no un anuncio que tape\n            la imagen: solo sale si el vídeo TIENE productos.\n\n            ⚠️ VA EN EL FLUJO, **ENCIMA DEL NOMBRE DE LA TIENDA**, NO FLOTANDO.\n            Antes estaba en `position: absolute` con `bottom: insets.bottom + 130` dentro de este\n            mismo bloque. Pero este bloque se ancla abajo y CRECE hacia arriba según lo que lleve\n            (título de una o dos líneas + chips de «Búsquedas relacionadas»…) y se mide en píxeles,\n            no en «huecos»: con un vídeo con título y tres chips, esos 130 dp caían justo **encima\n            del nombre del autor** y lo tapaban (lo vio el dueño: «tapa el nombre de la tienda»).\n            Medido en el Poco F5: el sticker y el nombre acababan los dos en y≈1944.\n\n            En el flujo no puede pasar: el bloque está anclado abajo, así que este sticker se pinta\n            siempre por encima del nombre, y al abrirse crece hacia arriba sin mover el texto. */}\n        {productos.length > 0 ? (\n          <View style={{ alignSelf: 'flex-start', marginBottom: espaciado.e10, maxWidth: '100%', zIndex: 6 }}>\n            {stickerAbierto ? (\n              <View style={{ backgroundColor: 'rgba(0,0,0,0.72)', borderRadius: 14, padding: espaciado.e10, width: 216 }}>\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n                  {productos[0].coverUrl ? (\n                    <Image source={{ uri: productos[0].coverUrl }} style={{ width: 42, height: 42, borderRadius: 9 }} />\n                  ) : (\n                    <View style={{ width: 42, height: 42, borderRadius: 9, alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(255,255,255,0.15)' }}>\n                      <ShoppingBag size={18} color={brand.white} />\n                    </View>\n                  )}\n                  <View style={{ flex: 1 }}>\n                    <Text numberOfLines={2} style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '800' }}>{productos[0].title}</Text>\n                    <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900', marginTop: espaciado.e2 }}>\n                      {productos[0].priceXaf === null ? 'A consultar' : lbXaf(productos[0].priceXaf)}\n                    </Text>\n                  </View>\n                </View>\n                {productos.length > 1 ? (\n                  <Text style={{ color: 'rgba(255,255,255,0.75)', fontSize: 10.5, marginTop: espaciado.e6 }}>\n                    y {productos.length - 1} producto{productos.length - 1 === 1 ? '' : 's'} más en esta publicación\n                  </Text>\n                ) : null}\n                <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 }}>\n                  <Pressable\n                    onPress={() => onOpenProduct(productos[0].id)}\n                    accessibilityLabel={`Comprar ${productos[0].title}`}\n                    style={{ flex: 1, backgroundColor: brand.like, borderRadius: radios.full, paddingVertical: espaciado.e7, alignItems: 'center' }}\n                  >\n                    <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>Comprar</Text>\n                  </Pressable>\n                  <Pressable\n                    onPress={() => setStickerAbierto(false)}\n                    accessibilityLabel=\"Cerrar el producto\"\n                    style={{ paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 }}\n                  >\n                    <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '800' }}>Cerrar</Text>\n                  </Pressable>\n                </View>\n              </View>\n            ) : (\n              <Pressable\n                onPress={() => setStickerAbierto(true)}\n                accessibilityLabel={`Producto del vídeo: ${productos[0].title}`}\n                style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e7, backgroundColor: 'rgba(0,0,0,0.6)', borderRadius: radios.full, paddingLeft: espaciado.e4, paddingRight: espaciado.e12, paddingVertical: espaciado.e4 }}\n              >\n                {productos[0].coverUrl ? (\n                  <Image source={{ uri: productos[0].coverUrl }} style={{ width: 28, height: 28, borderRadius: 14 }} />\n                ) : (\n                  <View style={{ width: 28, height: 28, borderRadius: 14, alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(255,255,255,0.15)' }}>\n                    <ShoppingBag size={14} color={brand.white} />\n                  </View>\n                )}\n                <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '900' }}>\n                  {productos[0].priceXaf === null ? 'Ver producto' : lbXaf(productos[0].priceXaf)}\n                </Text>\n                {productos.length > 1 ? (\n                  <Text style={{ color: 'rgba(255,255,255,0.8)', fontSize: 10.5, fontWeight: '800' }}>+{productos.length - 1}</Text>\n                ) : null}\n              </Pressable>\n            )}\n          </View>\n        ) : null}\n\n        {/* El nombre del autor (la tienda, si vende) y la duración. Va DESPUÉS del sticker: este\n            bloque se ancla abajo, así que el orden del JSX es el orden de abajo hacia arriba. */}\n        <View style={s.authorRow}>\n          {post.author?.avatarUrl ? (\n            <Image source={absUrl(post.author.avatarUrl)} style={s.avatar} contentFit=\"cover\" cachePolicy=\"memory-disk\" />\n          ) : (\n            <View style={[s.avatar, { backgroundColor: alpha(colors.primary, 0.5) }]}>\n              <Text style={{ fontSize: tipografia.micro, fontWeight: '800', color: brand.white }}>\n                {authorName.trim().charAt(0).toUpperCase() || '?'}\n              </Text>\n            </View>\n          )}\n          <Text numberOfLines={1} style={s.author}>{authorName}</Text>\n          {durOk ? (\n            <View style={s.durChip}><Text style={s.durText}>{fmtDur(dur)}</Text></View>\n          ) : null}\n        </View>\n\n        {/* El título abre el detalle completo. Era la entrada que tenía el botón de\n            comentarios; ahora que ese abre la hoja en sitio, el detalle se alcanza por aquí\n            y no se pierde ninguna entrada: sigue estando a un toque. */}\n        {title ? (\n          <Pressable onPress={onOpenDetail} hitSlop={6} accessibilityRole=\"button\"\n            accessibilityLabel={`Abrir publicación: ${title}`}>\n            <Text numberOfLines={2} style={s.title}>{title}</Text>\n          </Pressable>\n        ) : null}\n\n        {/* [P8] «Búsquedas relacionadas» — como la barra de 小红书. Chips con los temas de la\n            publicación; tocar uno abre el buscador con ese término.\n            Sale SIEMPRE: si el post no trae temas se usan ciudad, autor y título\n            (ver `relTerms`). Antes se ocultaba cuando no había temas y, como casi\n            ningún vídeo lleva, en la práctica no se veía nunca.\n            ⚠️ El GRUPO del autor NO está: `LbAuthor` no trae grupo y no hay\n            endpoint de grupos por usuario. Hace falta backend (ver cabecera). */}\n        {relTerms.length > 0 ? (\n          <View style={s.relBox}>\n            <Text style={s.relLabel}>Búsquedas relacionadas</Text>\n            <View style={s.relRow}>\n              {relTerms.map((t) => (\n                <Pressable key={t} onPress={() => onSearchTopic(t)} hitSlop={4} style={s.relChip}\n                  accessibilityRole=\"button\" accessibilityLabel={`Buscar ${t}`}>\n                  <Text numberOfLines={1} style={s.relChipText}>{t}</Text>\n                </Pressable>\n              ))}\n            </View>\n          </View>\n        ) : null}\n      </View>\n    </View>\n  );\n}\n\nfunction fmtCount(n: number): string {\n  if (n >= 1_000) return `${(n / 1000).toFixed(1)}k`;\n  return String(n);\n}\n\nconst s = StyleSheet.create({\n  root: { flex: 1 },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e32, backgroundColor: '#000000' },\n  topBar: {\n    position: 'absolute', top: 0, left: 0, right: 0, zIndex: 5,\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e14,\n  },\n  iconBtn: { width: 38, height: 38, borderRadius: 19, backgroundColor: 'rgba(0,0,0,0.35)', alignItems: 'center', justifyContent: 'center' },\n  moreBox: { position: 'absolute', left: 0, right: 0, bottom: 0, alignItems: 'center', zIndex: 4 },\n  /* Barrita de tiempo: sólo sale al mantener pulsado, así que puede tener el aspecto de\n     «modo arrastre» — algo más gruesa y más blanca que una línea de adorno. Pista al 35 %\n     para que se intuya el recorrido, relleno blanco casi opaco. Pegada al borde inferior\n     (`bottom: 0`), como en TikTok/Douyin. */\n  tlLine: {\n    position: 'absolute', left: 0, right: 0, bottom: 0, height: 3, zIndex: 6,\n    backgroundColor: 'rgba(255,255,255,0.35)',\n  },\n  tlFill: { height: 3, backgroundColor: 'rgba(255,255,255,0.95)' },\n  /* El tiempo mientras se arrastra. Va por encima de la barra, con pastilla oscura para que\n     se lea sobre cualquier vídeo. `bottom: 12` lo deja separado de la línea. */\n  tlTime: {\n    position: 'absolute', left: 0, right: 0, bottom: 12, zIndex: 6, alignItems: 'center',\n  },\n  tlTimeTxt: {\n    color: brand.white, fontSize: tipografia.caption, fontWeight: '800',\n    backgroundColor: 'rgba(0,0,0,0.55)', overflow: 'hidden',\n    paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e4, borderRadius: 10,\n  },\n  // El degradado inferior ya no es un estilo: se genera por franjas en `BottomScrim`.\n  actions: { position: 'absolute', right: 10, zIndex: 3, alignItems: 'center', gap: espaciado.e16 },\n  actBtn: { alignItems: 'center' },\n  actN: { color: brand.white, fontSize: tipografia.micro, fontWeight: '800', marginTop: espaciado.e3 },\n  info: { position: 'absolute', left: 14, right: 74, bottom: 0, zIndex: 3 },\n  authorRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e7 },\n  avatar: { width: 26, height: 26, borderRadius: 13, alignItems: 'center', justifyContent: 'center' },\n  author: { color: brand.white, fontSize: tipografia.body, fontWeight: '800', flexShrink: 1 },\n  durChip: { backgroundColor: 'rgba(0,0,0,0.45)', borderRadius: radios.sm, paddingHorizontal: espaciado.e6, paddingVertical: espaciado.e2 },\n  durText: { color: brand.white, fontSize: 10.5, fontWeight: '800' },\n  title: { color: 'rgba(255,255,255,0.94)', fontSize: tipografia.body, lineHeight: 18, marginTop: espaciado.e6 },\n  // [P8] fila «Búsquedas relacionadas»\n  relBox: { marginTop: espaciado.e9 },\n  relLabel: { color: 'rgba(255,255,255,0.62)', fontSize: 10.5, fontWeight: '800', marginBottom: espaciado.e6 },\n  relRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 },\n  relChip: {\n    backgroundColor: 'rgba(255,255,255,0.16)', borderRadius: radios.md,\n    paddingHorizontal: espaciado.e9, paddingVertical: espaciado.e4, maxWidth: 190,\n  },\n  relChipText: { color: brand.white, fontSize: tipografia.caption, fontWeight: '700' },\n  pauseDot: {\n    ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', zIndex: 3,\n  },\n  largoBox: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', zIndex: 3, gap: espaciado.e12 },\n  largoPlay: {\n    width: 70, height: 70, borderRadius: 35, alignItems: 'center', justifyContent: 'center',\n    backgroundColor: 'rgba(0,0,0,0.55)', borderWidth: 2, borderColor: 'rgba(255,255,255,0.85)',\n  },\n  largoTxt: { color: brand.white, fontSize: tipografia.body, fontWeight: '900', textAlign: 'center', lineHeight: 19 },\n  largoSub: { color: 'rgba(255,255,255,0.8)', fontSize: tipografia.caption, fontWeight: '700' },\n  heartPop: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', zIndex: 4 },\n});\n","/**\n * SeguirViendo — la fila de «seguir viendo» encima del feed de vídeos.\n *\n * Qué es: los vídeos que dejaste a medias, con una barrita que dice por dónde ibas.\n * Sale del trabajo de esta ronda: hasta ahora no había NINGUNA forma de reanudar un\n * vídeo (comprobado: no existía ni el dato).\n *\n * POR QUÉ SOLO EN EL PRIMER VÍDEO: el feed es inmersivo y una fila fija encima\n * estorba en cuanto se desliza. Se enseña al entrar (donde sirve: «¿sigo con lo de\n * ayer?») y desaparece al primer deslizamiento. Es el compromiso que respeta las dos\n * cosas.\n *\n * Se coloca justo DEBAJO de la cabecera flotante del feed (que es de una sola línea\n * con volver y sonido), no encima: si no, taparía los botones.\n */\nimport React from 'react';\nimport { FlatList, Image, Pressable, Text, View } from 'react-native';\nimport { X } from 'lucide-react-native';\nimport { absUrl } from '../../api/config';\nimport type { LbSeguirViendo } from '../../api/lifebookWatch';\nimport { brand, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\nexport function SeguirViendo({ items, colors, top, onOpen, onQuitar }: {\n  items: LbSeguirViendo[];\n  colors: any;\n  /** Altura a la que empieza (debajo de la cabecera). */\n  top: number;\n  onOpen: (id: string) => void;\n  onQuitar: (id: string) => void;\n}) {\n  if (items.length === 0) return null;\n\n  return (\n    <View style={{ position: 'absolute', left: 0, right: 0, top }} pointerEvents=\"box-none\">\n      <Text style={{\n        color: brand.white, fontSize: tipografia.caption, fontWeight: '900', letterSpacing: 0.4,\n        paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e6,\n        textShadowColor: 'rgba(0,0,0,0.6)', textShadowRadius: 4,\n      }}>\n        Seguir viendo\n      </Text>\n      <FlatList\n        horizontal\n        data={items}\n        keyExtractor={(x) => x.id}\n        showsHorizontalScrollIndicator={false}\n        contentContainerStyle={{ paddingHorizontal: espaciado.e14, gap: espaciado.e10 }}\n        renderItem={({ item }) => (\n          <Pressable\n            onPress={() => onOpen(item.id)}\n            accessibilityLabel={`Seguir viendo ${item.title ?? 'vídeo'}, por el ${item.percent} %`}\n            style={{\n              width: 136, borderRadius: radios.md, overflow: 'hidden',\n              backgroundColor: 'rgba(0,0,0,0.55)',\n            }}\n          >\n            <View style={{ height: 76, backgroundColor: 'rgba(255,255,255,0.06)' }}>\n              {item.thumb?.url ? (\n                <Image source={{ uri: absUrl(item.thumb.url) }} style={{ width: '100%', height: '100%' }} resizeMode=\"cover\" />\n              ) : (\n                <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>\n                  <Text style={{ fontSize: 22 }}>🎬</Text>\n                </View>\n              )}\n              {/* Barrita: por dónde ibas, de un vistazo. */}\n              <View style={{ position: 'absolute', left: 0, right: 0, bottom: 0, height: 3, backgroundColor: 'rgba(255,255,255,0.25)' }}>\n                <View style={{ width: `${Math.min(100, Math.max(0, item.percent))}%`, height: 3, backgroundColor: colors?.primary ?? brand.like }} />\n              </View>\n              <Pressable\n                onPress={() => onQuitar(item.id)}\n                hitSlop={10}\n                accessibilityLabel=\"Quitar de seguir viendo\"\n                style={{\n                  position: 'absolute', top: 4, right: 4,\n                  width: 22, height: 22, borderRadius: 11,\n                  backgroundColor: 'rgba(0,0,0,0.55)', alignItems: 'center', justifyContent: 'center',\n                }}\n              >\n                <X size={12} color={brand.white} />\n              </Pressable>\n            </View>\n            <Text numberOfLines={2} style={{ color: brand.white, fontSize: tipografia.micro, fontWeight: '700', padding: espaciado.e7, paddingTop: espaciado.e6 }}>\n              {item.title?.trim() || 'Vídeo'}\n            </Text>\n          </Pressable>\n        )}\n      />\n    </View>\n  );\n}\n","/**\n * «Seguir viendo»: por dónde ibas en cada vídeo.\n *\n * Vive en su propio fichero, como `lifebookPostOps.ts` y `lifebookComentarios.ts`, para\n * no tocar `api/lifebook.ts` (que el dueño pidió no tocar) y porque esto es ADITIVO.\n *\n * Antes NO existía nada de esto: comprobado buscando `progress|position|resume` en la\n * app, lo único que aparecía era el progreso de SUBIDA. Con 62 vídeos, 12 series y 36\n * episodios, salir de un vídeo significaba empezar de cero.\n *\n * El servidor deduce lo que está visto: por debajo de 5 s no cuenta como empezado y a\n * partir del 90 % cuenta como terminado (y sale de la lista). No hay que mandarle nada\n * de eso: lo decide él para que no haya dos criterios distintos.\n */\nimport { http, httpRequest } from './httpClient';\n\nexport interface LbProgreso {\n  positionSec: number;\n  durationSec: number;\n  /** `null` si no hay nada guardado. */\n  updatedAt: string | null;\n}\n\n/** Una tarjeta de «seguir viendo»: el vídeo + por dónde ibas. */\nexport interface LbSeguirViendo {\n  id: string;\n  type: string;\n  title: string | null;\n  preview: string;\n  thumb: { id: string | null; url: string } | null;\n  author: { id: string; fullName: string | null; avatarUrl: string | null };\n  positionSec: number;\n  durationSec: number;\n  /** 0-100, para la barrita de la tarjeta. */\n  percent: number;\n  updatedAt: string | null;\n}\n\nexport const watchApi = {\n  /** Guarda por dónde vas. Idempotente; el servidor acota los valores. */\n  guardar: (postId: string, positionSec: number, durationSec: number) =>\n    http.post<{ ok: boolean; positionSec: number; durationSec: number }>(\n      `/lifebook/watch/${postId}`, { positionSec, durationSec },\n    ),\n\n  /** Por dónde ibas (para reanudar). Ceros si no hay nada guardado. */\n  leer: (postId: string) => http.get<LbProgreso>(`/lifebook/watch/${postId}`),\n\n  /** Quita un vídeo de «seguir viendo» a mano. */\n  borrar: (postId: string) =>\n    httpRequest<{ ok: boolean }>(`/lifebook/watch/${postId}`, { method: 'DELETE' }),\n\n  /** Los vídeos que dejaste a medias, del más reciente al más antiguo. */\n  seguirViendo: (limit = 12) =>\n    http.get<LbSeguirViendo[]>(`/lifebook/me/continue-watching?limit=${limit}`),\n};\n","/**\n * app/lifebook-vistos.tsx — HISTORIAL DE PRODUCTOS («vistos hace poco») · Mercado, tanda F.\n *\n * QUÉ ES\n * Uno de los cinco accesos rápidos que pide la especificación del Mercado: «Historial de\n * productos». Hasta ahora solo existía un contador público por producto (`views_count`), que no\n * sirve para volver a algo que miraste: no dice QUÉ miraste ni CUÁNDO.\n *\n * LO QUE DICE EN VOZ ALTA (en vez de disimularlo)\n *  · La rejilla es **la misma del catálogo** (`ProductoCard`), no una copia con otro aspecto.\n *  · Un producto que ya **no está a la venta no se esconde**: sale apagado y con «Ya no está a la\n *    venta», porque borrarlo del historial de alguien sin avisar es peor que decirlo.\n *  · «Solo lo ves tú»: el historial no es público ni se le enseña a la tienda.\n *  · Se puede **borrar** (es el rastro de la persona, no de la plataforma).\n */\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { alpha, EmptyState, espaciado, InlineError, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { ArrowLeft, Clock } from 'lucide-react-native';\nimport { AuthGate } from '../core/AuthGate';\nimport { commerceApi, type LbViewedProduct } from '../api/commerce';\nimport { ProductoCard } from '../components/lifebook/ProductoCard';\nimport { ir as irSeguro } from '../constants/rutas';\nimport { shortDate } from '../utils/datetime';\n\n/** «Visto hace un momento» · «Visto ayer» · «Visto el 12 sep»: legible, sin ceros raros. */\nfunction cuandoLoVio(iso: string): string {\n  const ms = Date.now() - new Date(iso).getTime();\n  if (!Number.isFinite(ms) || ms < 0) return 'Visto hace poco';\n  const horas = ms / 3600000;\n  if (horas < 1) return 'Visto hace un momento';\n  if (horas < 24) return `Visto hace ${Math.floor(horas)} h`;\n  const dias = Math.floor(horas / 24);\n  if (dias === 1) return 'Visto ayer';\n  if (dias < 7) return `Visto hace ${dias} días`;\n  return `Visto el ${shortDate(iso)}`;\n}\n\nexport default function LifeBookVistosScreen() {\n  return (\n    <AuthGate>\n      <VistosContent />\n    </AuthGate>\n  );\n}\n\nfunction VistosContent() {\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const [items, setItems] = useState<LbViewedProduct[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [borrando, setBorrando] = useState(false);\n  const vivo = useRef(true);\n\n  const cargar = useCallback(async (modo: 'inicial' | 'refresco' = 'inicial') => {\n    if (modo === 'refresco') setRefrescando(true);\n    try {\n      const res = await commerceApi.misVistos(60);\n      if (!vivo.current) return;\n      setItems(res.items ?? []);\n      setError(null);\n    } catch (e) {\n      if (vivo.current) setError(e instanceof Error ? e.message : 'No se pudo cargar el historial');\n    } finally {\n      if (vivo.current) { setLoading(false); setRefrescando(false); }\n    }\n  }, []);\n\n  useEffect(() => {\n    vivo.current = true;\n    void cargar();\n    return () => { vivo.current = false; };\n  }, [cargar]);\n\n  const borrar = useCallback(() => {\n    Alert.alert(\n      'Borrar el historial',\n      'Se quitará de esta lista todo lo que has mirado. No se borra nada de las tiendas ni de tus pedidos.',\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        {\n          text: 'Borrar',\n          style: 'destructive',\n          onPress: () => {\n            setBorrando(true);\n            commerceApi.borrarVistos()\n              .then(() => { if (vivo.current) setItems([]); })\n              .catch((e) => Alert.alert('No se pudo borrar', e instanceof Error ? e.message : 'Inténtalo otra vez.'))\n              .finally(() => { if (vivo.current) setBorrando(false); });\n          },\n        },\n      ],\n    );\n  }, []);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={[styles.header, { paddingTop: insets.top + 6, borderBottomColor: alpha(colors.border, 0.5) }]}>\n        <Pressable onPress={() => irSeguro.atras()} hitSlop={10} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={20} color={colors.textPrimary} />\n        </Pressable>\n        <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n          <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.subtitle }}>Historial de productos</Text>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro }}>Solo lo ves tú</Text>\n        </View>\n        {items.length && !loading ? (\n          <Pressable onPress={borrar} hitSlop={8} disabled={borrando} accessibilityLabel=\"Borrar el historial\">\n            {borrando\n              ? <ActivityIndicator size=\"small\" color={colors.textSecondary} />\n              : <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }}>Borrar</Text>}\n          </Pressable>\n        ) : null}\n      </View>\n\n      {loading ? (\n        <View style={styles.center}><ActivityIndicator color={colors.primary} /></View>\n      ) : (\n        <FlatList\n          data={items}\n          keyExtractor={(p) => p.id}\n          numColumns={2}\n          columnWrapperStyle={{ gap: espaciado.e10, paddingHorizontal: espaciado.e14 }}\n          contentContainerStyle={{ paddingTop: espaciado.e12, paddingBottom: insets.bottom + 30, gap: espaciado.e12, flexGrow: 1 }}\n          showsVerticalScrollIndicator={false}\n          refreshing={refrescando}\n          onRefresh={() => void cargar('refresco')}\n          ListHeaderComponent={items.length ? (\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, paddingHorizontal: espaciado.e14 }}>\n              {items.length} producto{items.length === 1 ? '' : 's'} · lo último que miraste, primero\n            </Text>\n          ) : null}\n          ListEmptyComponent={\n            /*\n              Aquí había UN bloque haciendo DOS trabajos: si fallaba la carga decía «No se pudo\n              cargar» y ofrecía «Ver el catálogo» — la acción equivocada, porque el catálogo no\n              arregla que la petición haya fallado y el usuario se quedaba sin reintentar. Ahora\n              el error va con `InlineError` (se anuncia, vibra y ofrece reintento) y el vacío con\n              `EmptyState`.\n            */\n            error ? (\n              <View style={{ paddingTop: 40, paddingHorizontal: espaciado.e14 }}>\n                <InlineError mensaje={error} onReintentar={() => void cargar()} />\n              </View>\n            ) : (\n              <EmptyState\n                icono={<Clock size={38} color={alpha(colors.primary, 0.35)} />}\n                titulo=\"Todavía no has mirado nada\"\n                texto=\"Cuando abras la ficha de un producto aparecerá aquí, para volver a él sin buscarlo otra vez.\"\n                accionLabel=\"Ver el catálogo\"\n                onAccion={() => irSeguro.libre('/lifebook-catalog')}\n              />\n            )\n          }\n          renderItem={({ item }) => (\n            <ProductoCard\n              item={item}\n              apagado={!item.available}\n              /* La misma regla que el catálogo: una HABITACIÓN no se abre como producto (se reserva\n                 por noches desde la ficha del hotel); el resto abre su ficha. */\n              onPress={() => irSeguro.libre(\n                item.serviceType === 'hotel_room' ? '/lifebook-hotel-detalle' : '/lifebook-product/[id]',\n                { id: item.serviceType === 'hotel_room' ? item.shop.id : item.id },\n              )}\n              pie={\n                <View style={{ marginTop: espaciado.e4 }}>\n                  <Text style={{ color: colors.textSecondary, fontSize: 10 }}>\n                    {cuandoLoVio(item.viewedAt)}\n                    {item.times > 1 ? ` · ${item.times} veces` : ''}\n                  </Text>\n                  {!item.available ? (\n                    <Text style={{ color: colors.danger, fontSize: 10, fontWeight: '800' }}>Ya no está a la venta</Text>\n                  ) : null}\n                </View>\n              }\n            />\n          )}\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  header: {\n    flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e10,\n    borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n});\n","/**\r\n * Life Book — INICIO (feed por canales) · Estilo Xiaohongshu\r\n *\r\n * Barra superior: búsqueda + ciudad + mensajes.\r\n * Canales: tabs de texto con indicador inferior (sin pills de color).\r\n * Feed: masonry 2 columnas con tarjetas de altura variable.\r\n * FAB \"+\" compacto (esquina inferior derecha, sobre el dock).\r\n * Skeleton loading, pull-to-refresh, paginación por cursor.\r\n *\r\n * API: /lifebook/posts/feed?channel=…&city=…&cursor=…\r\n */\r\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\r\nimport {\r\n  ActivityIndicator,\r\n  Alert,\r\n  Dimensions,\r\n  FlatList,\r\n  Modal,\r\n  Pressable,\r\n  ScrollView,\r\n  StyleSheet,\r\n  Text,\r\n  View,\r\n} from 'react-native';\r\nimport { useRouter, useFocusEffect } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { alpha, elevation, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport {\r\n  ChevronDown,\r\n  Clapperboard,\r\n  MapPin,\r\n  Mic,\r\n  Package,\r\n  PenSquare,\r\n  Play,\r\n  Plus,\r\n  RefreshCw,\r\n  Search,\r\n  ShoppingBag,\r\n  Sparkles,\r\n  Video,\r\n} from 'lucide-react-native';\r\nimport { AuthGate } from '../core/AuthGate';\r\nimport {\r\n  lifebookActionsApi,\r\n  lifebookApi,\r\n  LB_CARD_DEFAULT_RATIO,\r\n  toPostCard,\r\n  type LbFeedPage,\r\n  type LbPostBase,\r\n  type LbPostCard,\r\n} from '../api/lifebook';\r\nimport { authApi } from '../api/auth';\r\nimport { Gesture, GestureDetector } from 'react-native-gesture-handler';\r\nimport { runOnJS } from 'react-native-reanimated';\r\nimport { LB_CHANNELS, LB_CHIPS_BY_TAB, LB_CITIES, LB_TABS } from '../constants/lifebook';\r\nimport { PostCard } from '../components/lifebook/PostCard';\r\n/* TANDA I: el buscador de sitios + mapa real (el mismo de las rutas y las quedadas). */\r\nimport { LocationPickerSheet } from '../components/lifebook/LocationPickerSheet';\r\n/* TANDA I — la ciudad con DISTANCIA: chips 附近 / 3 km / 全城, posición propia y el sitio de cada\r\n   nota en la tarjeta. Va en su propio módulo para no tocar `api/lifebook.ts`. */\r\nimport { ciudadApi, tarjetaConSitio, LB_DISTANCIAS, centroDe } from '../api/lifebookCiudad';\r\nimport * as Location from 'expo-location';\r\nimport FloatingFooter, {\r\n  DOCK_BODY_H,\r\n  type FooterTab,\r\n} from '../components/FloatingFooter';\r\nimport { useAppDock } from '../core/useAppDock';\r\nimport { ReportSheet } from '../components/lifebook/ReportSheet';\r\nimport { AvatarsSeguidos } from '../components/lifebook/AvatarsSeguidos';\r\nimport { seguidosApi, type LbSeguido } from '../api/lifebookSeguidos';\r\nimport { ir as irSeguro } from '../constants/rutas';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\n/* ──────────────────────────────────────────────\r\n   Constantes de layout\r\n────────────────────────────────────────────── */\r\nconst { width: SCREEN_W } = Dimensions.get('window');\r\nconst COLUMN_GAP = 8;\r\nconst SIDE_PADDING = 10;\r\nconst COLUMN_W = (SCREEN_W - SIDE_PADDING * 2 - COLUMN_GAP) / 2;\r\n\r\n/* ──────────────────────────────────────────────\r\n   Copy de estados vacíos\r\n────────────────────────────────────────────── */\r\nconst EMPTY_COPY: Record<string, string> = {\r\n  for_you: 'Descubre contenido de tu comunidad.\\n¡Sé el primero en publicar!',\r\n  following:\r\n    'Aún no hay publicaciones de tus seguidos.\\nSigue a personas desde su perfil para verlas aquí.',\r\n  nearby:\r\n    'Todavía no hay publicaciones cerca de ti.\\n¡Sé el primero en compartir algo!',\r\n  debates:\r\n    'Todavía no hay debates en esta ciudad.\\nInicia uno sobre un problema del barrio.',\r\n  sales: 'No hay ventas por aquí todavía.\\nPublica la primera.',\r\n  food: 'No hay publicaciones de comida todavía.',\r\n  taxi: 'No hay avisos de transporte todavía.',\r\n  work: 'No hay ofertas de trabajo publicadas todavía.',\r\n  rental: 'No hay anuncios de alquiler todavía.',\r\n  culture: 'No hay publicaciones de cultura todavía.',\r\n  music: 'No hay publicaciones de música todavía.',\r\n  sports: 'No hay publicaciones de deportes todavía.',\r\n};\r\n\r\n/* ──────────────────────────────────────────────\r\n   Skeleton card (shimmer placeholder)\r\n────────────────────────────────────────────── */\r\nfunction SkeletonCard({ width }: { width: number }) {\r\n  const { colors } = useTheme();\r\n  const h = 140 + Math.round(Math.random() * 80);\r\n  return (\r\n    <View style={{ width, marginBottom: COLUMN_GAP }}>\r\n      <View\r\n        style={{\r\n          width,\r\n          height: h,\r\n          borderRadius: radios.sm,\r\n          backgroundColor: alpha(colors.textSecondary, 0.08),\r\n        }}\r\n      />\r\n      <View\r\n        style={{\r\n          marginTop: espaciado.e6,\r\n          height: 12,\r\n          width: '80%',\r\n          borderRadius: 4,\r\n          backgroundColor: alpha(colors.textSecondary, 0.08),\r\n        }}\r\n      />\r\n      <View\r\n        style={{\r\n          marginTop: espaciado.e6,\r\n          height: 10,\r\n          width: '50%',\r\n          borderRadius: 4,\r\n          backgroundColor: alpha(colors.textSecondary, 0.06),\r\n        }}\r\n      />\r\n    </View>\r\n  );\r\n}\r\n\r\nfunction SkeletonGrid() {\r\n  return (\r\n    <View\r\n      style={{\r\n        flexDirection: 'row',\r\n        paddingHorizontal: SIDE_PADDING,\r\n        gap: COLUMN_GAP,\r\n        paddingTop: espaciado.e8,\r\n      }}\r\n    >\r\n      <View style={{ flex: 1, gap: COLUMN_GAP }}>\r\n        {Array.from({ length: 4 }).map((_, i) => (\r\n          <SkeletonCard key={`l${i}`} width={COLUMN_W} />\r\n        ))}\r\n      </View>\r\n      <View style={{ flex: 1, gap: COLUMN_GAP }}>\r\n        {Array.from({ length: 4 }).map((_, i) => (\r\n          <SkeletonCard key={`r${i}`} width={COLUMN_W} />\r\n        ))}\r\n      </View>\r\n    </View>\r\n  );\r\n}\r\n\r\n/* ──────────────────────────────────────────────\r\n   Entrada principal\r\n────────────────────────────────────────────── */\r\n/**\r\n * Parte 31: ¿el feed recargado es el mismo que ya está en pantalla?\r\n * Se comparan solo los campos que se ven (id, me gusta, comentarios, guardados\r\n * y el estado \"me gusta\"). Si nada cambió, se conserva la referencia anterior\r\n * para que las tarjetas memoizadas no se vuelvan a renderizar ni parpadeen.\r\n */\r\nfunction sameFeed(a: LbPostBase[], b: LbPostBase[]): boolean {\r\n  if (a === b) return true;\r\n  if (a.length !== b.length) return false;\r\n  for (let i = 0; i < a.length; i += 1) {\r\n    const p = a[i];\r\n    const q = b[i];\r\n    if (!q || p.id !== q.id) return false;\r\n    const sp = p.stats ?? ({} as LbPostBase['stats']);\r\n    const sq = q.stats ?? ({} as LbPostBase['stats']);\r\n    if (\r\n      (sp.likes ?? 0) !== (sq.likes ?? 0) ||\r\n      (sp.comments ?? 0) !== (sq.comments ?? 0) ||\r\n      (sp.bookmarks ?? 0) !== (sq.bookmarks ?? 0) ||\r\n      !!sp.likedByMe !== !!sq.likedByMe\r\n    ) {\r\n      return false;\r\n    }\r\n  }\r\n  return true;\r\n}\r\n\r\nexport default function LifeBookScreen() {\r\n  return (\r\n    <AuthGate>\r\n      <LifeBookContent />\r\n    </AuthGate>\r\n  );\r\n}\r\n\r\n/* ──────────────────────────────────────────────\r\n   Componente principal\r\n────────────────────────────────────────────── */\r\nfunction LifeBookContent() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n\r\n  /* ── Estado ── */\r\n  /**\r\n   * ── SECCIÓN y CHIP ─────────────────────────────────────────────────────────\r\n   * La SECCIÓN son las tres pestañas de arriba (Seguidos · Descubrir · Ciudad) y el\r\n   * CHIP es el filtro de dentro de esa sección. Cada sección tiene los suyos (ver\r\n   * `LB_CHIPS_BY_TAB`), que es lo que pidió el dueño: «cuando estás en Seguidos los\r\n   * que muestran abajo serán distintos de los que hayan en Descubrir o ciudad».\r\n   *\r\n   * Y no es solo el dibujo: el chip **filtra dentro de la sección**. «Comercio» en\r\n   * Seguidos es el comercio DE LA GENTE QUE SIGO; «Comida» en Ciudad, la de mi ciudad.\r\n   * Para eso se amplió el backend en esta misma ronda.\r\n   *\r\n   * `channelId` ya NO es estado: se DERIVA del chip activo, para que no haya dos\r\n   * fuentes de verdad que se puedan separar.\r\n   */\r\n  const [tab, setTab] = useState('for_you');\r\n  const [chipIdx, setChipIdx] = useState(0);\r\n  const chipsDeTab = LB_CHIPS_BY_TAB[tab] ?? [];\r\n  const chip = chipsDeTab[Math.min(chipIdx, Math.max(0, chipsDeTab.length - 1))] ?? null;\r\n  /** Lo que se le pide al servidor. */\r\n  const channelId = chip?.channel ?? tab;\r\n  /** Filtro por tipo del chip (Comercio → 'sale', Vídeos → 'video'). */\r\n  const tipo = chip?.type ?? null;\r\n  /**\r\n   * Solo los chips de CIUDAD mandan la ciudad. Los temas de Descubrir se quedan\r\n   * globales: si se les mandara, Cultura pasaría de 10 publicaciones a 2 (se probó y\r\n   * era una regresión).\r\n   */\r\n  /**\r\n   * Canales que SÍ usan la ciudad en el servidor (los demás la ignoran, y los temas\r\n   * de Descubrir deben quedarse globales).\r\n   */\r\n  const CANALES_CON_CIUDAD = new Set(['nearby', 'today', 'debates', 'sales']);\r\n  const conCiudad = !!chip?.conCiudad || CANALES_CON_CIUDAD.has(channelId);\r\n  const conCiudadRef = useRef(true);\r\n  useEffect(() => { conCiudadRef.current = conCiudad; }, [conCiudad]);\r\n  /**\r\n   * El tipo se lee por REF dentro de `load`, para no tener que cambiar su firma ni las\r\n   * cuatro llamadas que ya lo usan (foco, reintentar, refrescar, desbloquear).\r\n   */\r\n  const tipoRef = useRef<string | null>(null);\r\n  useEffect(() => { tipoRef.current = tipo; }, [tipo]);\r\n  /** Abre una sección: se queda en su primer chip (que es «Todo»/«Recomendado»). */\r\n  const abrirTab = useCallback((id: string) => { setTab(id); setChipIdx(0); }, []);\r\n  const [city, setCity] = useState('Malabo');  /* El contador de no leídos y el avatar del dueño YA NO SE USAN AQUÍ: el icono de\r\n     Mensajes salió de esta barra (vive en el dock, que tiene su propio contador a\r\n     través del hook compartido) y el avatar se mudó a la pantalla de mensajes. Se\r\n     quitaron también el hook y el estado para no dejar un sondeo cada 15 s sin nadie\r\n     que lo mire ni código muerto. */\r\n  /**\r\n   * TANDA I — MI POSICIÓN Y LA DISTANCIA DEL FEED DE CIUDAD.\r\n   *\r\n   * Por defecto «3 km» (el radio que la especificación dice que el algoritmo privilegia). Si no hay\r\n   * permiso de ubicación se avisa y se enseña toda la ciudad: un feed vacío sin explicación es peor\r\n   * que decir que falta un permiso.\r\n   */\r\n  const [distIdx, setDistIdx] = useState(1); // 0 = Cerca · 1 = 3 km · 2 = Toda la ciudad\r\n  const [miPos, setMiPos] = useState<{ lat: number; lng: number } | null>(null);\r\n  const distRef = useRef<number | null>(LB_DISTANCIAS[1].radiusKm);\r\n  const posRef = useRef<{ lat: number; lng: number } | null>(null);\r\n  useEffect(() => {\r\n    distRef.current = LB_DISTANCIAS[Math.min(distIdx, LB_DISTANCIAS.length - 1)]?.radiusKm ?? null;\r\n  }, [distIdx]);\r\n  useEffect(() => { posRef.current = miPos; }, [miPos]);\r\n\r\n\r\n  /**\r\n   * Pide la ubicación (una vez) y la guarda. La RECARGA la dispara el `useFocusEffect` de abajo:\r\n   * `miPos` y `distIdx` entran en su clave, así que el feed se recarga solo (y no hay que\r\n   * llamar a `load` desde aquí, que se declara más abajo).\r\n   */\r\n  const pedirUbicacion = useCallback(async (): Promise<{ lat: number; lng: number } | null> => {\r\n    try {\r\n      const perm = await Location.requestForegroundPermissionsAsync();\r\n      if (perm.status !== 'granted') { setMiPos(null); return null; }\r\n      const pos = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });\r\n      const p = { lat: pos.coords.latitude, lng: pos.coords.longitude };\r\n      setMiPos(p);\r\n      posRef.current = p;\r\n      return p;\r\n    } catch {\r\n      setMiPos(null);\r\n      return null;\r\n    }\r\n  }, []);\r\n\r\n  /** Cambiar de distancia: si hace falta la posición, se pide entonces (no al abrir la app). */\r\n  const elegirDistancia = useCallback(async (idx: number) => {\r\n    const d = LB_DISTANCIAS[idx];\r\n    distRef.current = d?.radiusKm ?? null;\r\n    if (d?.radiusKm !== null && d?.radiusKm !== undefined && !posRef.current) await pedirUbicacion();\r\n    setDistIdx(idx);\r\n  }, [pedirUbicacion]);\r\n\r\n  const [cityOpen, setCityOpen] = useState(false);\r\n  /** TANDA I: posición elegida A MANO (mapa o buscador) para explorar otra zona sin estar ahí. */\r\n  const [posManual, setPosManual] = useState<{ lat: number; lng: number } | null>(null);\r\n  const [mapaCiudadOpen, setMapaCiudadOpen] = useState(false);\r\n  const [publishOpen, setPublishOpen] = useState(false);\r\n  const [morePost, setMorePost] = useState<LbPostCard | null>(null);\r\n  const [meCity, setMeCity] = useState<string | null>(null);\r\n\r\n  /**\r\n   * LA POSICIÓN CON LA QUE SE MIDE: la mía, **o el centro de la ciudad** si he cambiado de ciudad a\r\n   * mano (regla de la especificación: «la distancia se calcula desde la posición actual del usuario\r\n   * o desde el centro de la ciudad si cambió de ciudad manualmente»). Sin esto, mirar Malabo desde\r\n   * otro sitio pondría «11.000 km» en cada tarjeta: es verdad, pero no sirve para decidir.\r\n   */\r\n  const posEfectiva = useMemo(\r\n    () => (posManual ?? (meCity && city && city.toLowerCase() !== meCity.toLowerCase() ? centroDe(city) : miPos)),\r\n    [meCity, city, miPos],\r\n  );\r\n  const posEfectivaRef = useRef<{ lat: number; lng: number } | null>(null);\r\n  useEffect(() => { posEfectivaRef.current = posEfectiva; }, [posEfectiva]);\r\n  /**\r\n   * La gente a la que sigo, para la fila de avatares de la pestaña «Seguidos».\r\n   * Se carga una vez al entrar: es una lista corta y no cambia sola.\r\n   */\r\n  const [seguidos, setSeguidos] = useState<LbSeguido[]>([]);\r\n\r\n  const [posts, setPosts] = useState<LbPostBase[]>([]);\r\n  const [nextCursor, setNextCursor] = useState<string | null>(null);\r\n  const [loading, setLoading] = useState(true);\r\n  const [refreshing, setRefreshing] = useState(false);\r\n  const [loadingMore, setLoadingMore] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  const busy = useRef(false);\r\n  const mounted = useRef(true);\r\n  /**\r\n   * Parte 31 (navegación fluida): canal+ciudad de la última carga correcta.\r\n   * Al VOLVER de un detalle (publicación, chat, perfil) la clave coincide y la\r\n   * recarga se hace en silencio: el feed se queda en pantalla en vez de\r\n   * desaparecer detrás del esqueleto de carga (ese era el parpadeo).\r\n   */\r\n  const loadedKey = useRef<string | null>(null);\r\n\r\n  /**\r\n   * B1 · Los posts CRUDOS, en un ref, para que `openPost` sepa si lo que se tocó\r\n   * es un vídeo y mandarlo al feed inmersivo en vez del detalle.\r\n   *\r\n   * En un ref y no en estado a propósito: `openPost` es un callback ESTABLE por\r\n   * diseño (Parte 31, navegación fluida) y las tarjetas están memoizadas. Añadir\r\n   * `posts` a sus dependencias las volvería a pintar en cada recarga silenciosa,\r\n   * que es justo el parpadeo que esa parte arregló.\r\n   */\r\n  const postsRef = useRef<LbPostBase[]>([]);\r\n  useEffect(() => { postsRef.current = posts; }, [posts]);\r\n\r\n  /** Canal y ciudad actuales, también en ref y por el mismo motivo: que\r\n   *  `openPost` pueda leerlos sin volverlos dependencias suyas. */\r\n  const ctxRef = useRef({ channelId: 'for_you', city: 'Malabo' });\r\n  useEffect(() => { ctxRef.current = { channelId, city }; }, [channelId, city]);\r\n\r\n  /* ── Tarjetas (LbPostCard) y masonry: 2 columnas por altura ── */\r\n  const cards = useMemo(() => posts.map(tarjetaConSitio), [posts]);\r\n\r\n  const { leftCol, rightCol } = useMemo(() => {\r\n    const left: LbPostCard[] = [];\r\n    const right: LbPostCard[] = [];\r\n    let hL = 0;\r\n    let hR = 0;\r\n    for (const p of cards) {\r\n      // Estimación de altura: imagen (ratio real) + texto + footer\r\n      const imgH = COLUMN_W / (p.media?.aspectRatio ?? LB_CARD_DEFAULT_RATIO);\r\n      const totalH = imgH + 60;\r\n      if (hL <= hR) {\r\n        left.push(p);\r\n        hL += totalH;\r\n      } else {\r\n        right.push(p);\r\n        hR += totalH;\r\n      }\r\n    }\r\n    return { leftCol: left, rightCol: right };\r\n  }, [cards]);\r\n\r\n  /* ── Efectos ── */\r\n  useEffect(() => {\r\n    mounted.current = true;\r\n    authApi\r\n      .me()\r\n      .then((m) => {\r\n        if (!mounted.current) return;\r\n        if (m?.city) {\r\n          setMeCity(m.city);\r\n          setCity(m.city);\r\n        }\r\n        /* El id y el avatar que se sacaban de aquí eran para el avatar de la barra\r\n           superior, que ahora vive en la pantalla de mensajes (junto a los contadores).\r\n           Esta llamada sigue haciendo falta por la CIUDAD: no se pide nada de más. */\r\n      })\r\n      .catch(() => {});\r\n    return () => {\r\n      mounted.current = false;\r\n    };\r\n  }, []);\r\n\r\n  /* A quién sigo: alimenta la fila de avatares de la pestaña «Seguidos». Una sola vez\r\n     al entrar; si falla, la fila no se pinta y el feed sigue funcionando. */\r\n  useEffect(() => {\r\n    seguidosApi.lista(20).then((l) => setSeguidos(Array.isArray(l) ? l : [])).catch(() => {});\r\n  }, []);\r\n\r\n  /* ── Carga de datos ── */\r\n  const load = useCallback(\r\n    async (\r\n      chan: string,\r\n      cty: string,\r\n      mode: 'initial' | 'refresh' | 'silent' = 'initial',\r\n    ) => {\r\n      if (busy.current) return;\r\n      busy.current = true;\r\n      // 'silent': recarga en segundo plano SIN spinner ni esqueleto — la lista\r\n      // que ya está en pantalla se mantiene (Parte 31: sin parpadeos).\r\n      if (mode === 'initial') setLoading(true);\r\n      else if (mode === 'refresh') setRefreshing(true);\r\n      setError(null);\r\n      try {\r\n        const page: LbFeedPage = await ciudadApi.feed(chan, {\r\n          /* La ciudad solo se manda cuando el chip la usa. Mandarla siempre fue lo que\r\n             encogió los temas de Descubrir a una sola ciudad (Cultura: 10 → 2). */\r\n          ...(conCiudadRef.current ? { city: cty } : {}),\r\n          limit: 20,\r\n          /* El tipo del chip activo, si lo tiene (Comercio → 'sale'). Va por ref para\r\n             no cambiar la firma de `load` ni sus cuatro llamadas. */\r\n          ...(tipoRef.current ? { type: tipoRef.current } : {}),\r\n          /* TANDA I: en Ciudad, mi posición y el radio del chip (附近 / 3 km / 全城). Fuera de\r\n             Ciudad no se manda nada de esto: los demás canales no filtran por distancia. */\r\n          ...(chan === 'nearby' && posEfectivaRef.current ? { lat: posEfectivaRef.current.lat, lng: posEfectivaRef.current.lng } : {}),\r\n          ...(chan === 'nearby' ? { radiusKm: distRef.current } : {}),\r\n        });\r\n        if (!mounted.current) return;\r\n        const incoming = page.posts ?? [];\r\n        loadedKey.current = `${chan}|${cty}|${tipoRef.current ?? ''}`;\r\n        // En silencio solo se reemplaza la lista si algo cambió de verdad:\r\n        // si no, se conserva la MISMA referencia y las tarjetas (memo) no se\r\n        // vuelven a renderizar → cero parpadeo al volver de un detalle.\r\n        if (mode === 'silent') {\r\n          setPosts((prev) => (sameFeed(prev, incoming) ? prev : incoming));\r\n        } else {\r\n          setPosts(incoming);\r\n        }\r\n        setNextCursor(page.nextCursor ?? null);\r\n      } catch (e) {\r\n        if (!mounted.current) return;\r\n        setError(\r\n          e instanceof Error ? e.message : 'No se pudo cargar el feed',\r\n        );\r\n      } finally {\r\n        busy.current = false;\r\n        if (mounted.current) {\r\n          setLoading(false);\r\n          setRefreshing(false);\r\n        }\r\n      }\r\n    },\r\n    [],\r\n  );\r\n\r\n  useFocusEffect(\r\n    useCallback(() => {\r\n      // Primera vez (o canal/ciudad nuevos) → esqueleto. Al volver de un\r\n      // detalle → recarga silenciosa, el feed no se desmonta.\r\n      // OJO: la clave incluye el CHIP, no solo el canal. Sin esto, cambiar de chip\r\n      // dentro de la misma sección no recargaría: Ciudad·Recomendado y\r\n      // Ciudad·Comercio son el MISMO canal (`nearby`) con distinto filtro.\r\n      const key = `${channelId}|${city}|${tipo ?? ''}`;\r\n      load(channelId, city, loadedKey.current === key ? 'silent' : 'initial');\r\n    }, [channelId, city, tipo, distIdx, load]),\r\n  );\r\n\r\n  const loadMore = useCallback(async () => {\r\n    if (!nextCursor || loadingMore || busy.current || loading) return;\r\n    setLoadingMore(true);\r\n    try {\r\n      const page = await ciudadApi.feed(channelId, {\r\n        ...(conCiudadRef.current ? { city } : {}),\r\n        cursor: nextCursor,\r\n        limit: 20,\r\n        ...(tipoRef.current ? { type: tipoRef.current } : {}),\r\n        ...(channelId === 'nearby' && posEfectivaRef.current ? { lat: posEfectivaRef.current.lat, lng: posEfectivaRef.current.lng } : {}),\r\n        ...(channelId === 'nearby' ? { radiusKm: distRef.current } : {}),\r\n      });\r\n      if (!mounted.current) return;\r\n      setPosts((prev) => {\r\n        const seen = new Set(prev.map((p) => p.id));\r\n        return [...prev, ...(page.posts ?? []).filter((p) => !seen.has(p.id))];\r\n      });\r\n      setNextCursor(page.nextCursor ?? null);\r\n    } catch {\r\n      /* silencioso en paginación */\r\n    } finally {\r\n      if (mounted.current) setLoadingMore(false);\r\n    }\r\n  }, [channelId, city, nextCursor, loadingMore, loading]);\r\n\r\n  const channel =\r\n    LB_CHANNELS.find((c) => c.id === channelId) ?? LB_CHANNELS[0];\r\n\r\n  /**\r\n   * Las TRES pestañas de arriba. Los chips van en su propia fila (`chipsDeTab`),\r\n   * debajo, y son distintos en cada sección — ver `LB_CHIPS_BY_TAB`.\r\n   */\r\n  const tabsVisibles = useMemo(\r\n    () => LB_TABS.map((id) => LB_CHANNELS.find((c) => c.id === id)).filter((c): c is (typeof LB_CHANNELS)[number] => !!c),\r\n    [],\r\n  );\r\n\r\n  /**\r\n   * Me gusta desde la tarjeta del feed (corazón o doble toque). Se pinta al\r\n   * momento y, si el servidor falla, se deshace.\r\n   */\r\n  const likeFromCard = useCallback((card: LbPostCard, liked: boolean) => {\r\n    const patch = (list: LbPostBase[]) => list.map((p) => {\r\n      if (p.id !== card.id) return p;\r\n      const stats = p.stats ?? ({} as LbPostBase['stats']);\r\n      const likes = Math.max(0, (stats.likes ?? 0) + (liked ? 1 : -1));\r\n      return { ...p, stats: { ...stats, likedByMe: liked, likes } };\r\n    });\r\n    setPosts(patch);\r\n    lifebookActionsApi.toggleLike(card.id, liked).catch(() => {\r\n      setPosts((list) => list.map((p) => {\r\n        if (p.id !== card.id) return p;\r\n        const stats = p.stats ?? ({} as LbPostBase['stats']);\r\n        return {\r\n          ...p,\r\n          stats: { ...stats, likedByMe: !liked, likes: Math.max(0, (stats.likes ?? 0) + (liked ? -1 : 1)) },\r\n        };\r\n      }));\r\n    });\r\n  }, []);\r\n\r\n  /**\r\n   * Parte 31: callback estable para abrir una publicación. Al ser estable, las\r\n   * tarjetas memoizadas (PostCard) no se vuelven a renderizar cuando la\r\n   * pantalla cambia por cualquier otro motivo.\r\n   *\r\n   * B1 (2026-09-12): si la publicación es un VÍDEO reproducible, se abre el feed\r\n   * inmersivo (`/lifebook-videos`) empezando por ese vídeo — es la entrada B de la\r\n   * decisión del dueño (A+B). Todo lo demás sigue yendo al detalle.\r\n   *\r\n   * Se comprueba la URL real en el payload, no el `type`: un post marcado como\r\n   * vídeo sin URL pintaría una pantalla negra, y `/lifebook-videos` filtra igual\r\n   * (su `videoUrlOf`), así que entrar con un id sin vídeo dejaría la lista vacía.\r\n   */\r\n  const openPost = useCallback(\r\n    (id: string) => {\r\n      const raw = postsRef.current.find((p) => p.id === id);\r\n      const payload = (raw?.payload ?? {}) as Record<string, unknown>;\r\n      const vurl = typeof payload.videoUrl === 'string' ? payload.videoUrl.trim() : '';\r\n      if (raw && vurl) {\r\n        router.push({\r\n          pathname: '/lifebook-videos',\r\n          // De un ref: meter `channelId`/`city` en las dependencias haría el\r\n          // callback inestable y repintaría las tarjetas memoizadas al cambiar de\r\n          // canal — justo lo que la Parte 31 evitó.\r\n          params: { startId: id, channel: ctxRef.current.channelId, city: ctxRef.current.city },\r\n        } as never);\r\n        return;\r\n      }\r\n      irSeguro.libre('/lifebook-post/[id]', { id });\r\n    },\r\n    [router],\r\n  );\r\n\r\n  /** Deslizar en el feed cambia de canal (Para ti → Siguiendo → Cerca…). */\r\n  const goChannel = useCallback((dir: 1 | -1) => {\r\n    const ids = LB_TABS;\r\n    const i = ids.indexOf(channelId);\r\n    const next = ids[Math.min(ids.length - 1, Math.max(0, i + dir))];\r\n    if (next && next !== tab) abrirTab(next);\r\n  }, [tab, abrirTab]);\r\n\r\n  const swipeChannels = useMemo(() => Gesture.Pan()\r\n    .activeOffsetX([-24, 24])\r\n    .failOffsetY([-18, 18])\r\n    .onEnd((e) => {\r\n      if (e.translationX <= -60) runOnJS(goChannel)(1);\r\n      else if (e.translationX >= 60) runOnJS(goChannel)(-1);\r\n    }), [goChannel]);\r\n\r\n  /* ── Dock ── */\r\n  const dockNav = useAppDock('lifebook');\r\n  const onDockNavigate = (t: FooterTab) => dockNav(t, city);\r\n\r\n  /* ── Opciones de publicación ── */\r\n  const PUBLISH_OPTIONS = useMemo(\r\n    () => [\r\n      {\r\n        label: 'Nota',\r\n        desc: 'Texto y fotos de tu día a día',\r\n        icon: PenSquare,\r\n        color: brand.like,\r\n        route: '/lifebook-compose' as const,\r\n        params: {},\r\n      },\r\n      // Parte 33: publicar en la tienda (producto o servicio) desde el panel «+».\r\n      {\r\n        label: 'Vender',\r\n        desc: 'Producto con precio, entrega y pago',\r\n        icon: ShoppingBag,\r\n        color: brand.success,\r\n        route: '/lifebook-sell' as const,\r\n        params: { type: 'sale' },\r\n      },\r\n      {\r\n        label: 'Ofrecer servicio',\r\n        desc: 'Oficios, clases, reparaciones…',\r\n        icon: Package,\r\n        color: brand.info,\r\n        route: '/lifebook-sell' as const,\r\n        params: { type: 'service' },\r\n      },\r\n      {\r\n        label: 'Video corto',\r\n        desc: 'Hasta 1 min · talento, humor, tutoriales',\r\n        icon: Video,\r\n        color: '#7C3AED',\r\n        route: '/lifebook-media' as const,\r\n        params: { kind: 'video' },\r\n      },\r\n      {\r\n        label: 'Podcast',\r\n        desc: 'Audio con portada · charlas y cultura',\r\n        icon: Mic,\r\n        color: '#E0439A',\r\n        route: '/lifebook-media' as const,\r\n        params: { kind: 'podcast' },\r\n      },\r\n      {\r\n        label: 'Serie',\r\n        desc: 'Episodios por temporadas · comedia, drama…',\r\n        icon: Clapperboard,\r\n        color: brand.secondary,\r\n        route: '/lifebook-media' as const,\r\n        params: { kind: 'serie' },\r\n      },\r\n    ],\r\n    [],\r\n  );\r\n\r\n  /* ────────────────────────────────────────────\r\n     RENDER\r\n  ──────────────────────────────────────────── */\r\n  return (\r\n    <View style={[styles.root, { backgroundColor: colors.background }]}>\r\n      {/* ═══════════ BARRA SUPERIOR ═══════════ */}\r\n      <View\r\n        style={[\r\n          styles.topBar,\r\n          {\r\n            paddingTop: insets.top + 4,\r\n            borderBottomColor: alpha(colors.border, 0.6),\r\n          },\r\n        ]}\r\n      >\r\n        {/* La barra de arriba se queda con lo mínimo (lo pidió el dueño):\r\n            · FUERA «Volver»: Life Book es una pestaña del dock, y volver desde una\r\n              pestaña no significa nada.\r\n            · FUERA el selector de ciudad: la ciudad pasa a ser una PESTAÑA\r\n              («Ciudad»), que es donde tiene sentido cambiarla y ver lo de cada una.\r\n            · FUERA el icono de Mensajes: ya está en el dock, y ahí lleva el contador\r\n              de no leídos (no se pierde el aviso).\r\n            · FUERA el avatar: se muda a la pantalla de mensajes, junto a los\r\n              contadores de me gusta, seguidores y comentarios. El perfil sigue\r\n              teniendo puerta en el dock, así que no se pierde ninguna.\r\n            Queda la BÚSQUEDA, que es lo único que no está en otro sitio. */}\r\n\r\n        {/* TANDA M — EL ASISTENTE DE IA, A LA IZQUIERDA (lo pidió el dueño: «el icono está mal\r\n            posicionado, debe irse a la izquierda»). Va antes del espaciador, que es lo que empuja el\r\n            resto a la derecha: así es lo PRIMERO de la barra, siempre a mano. Abre un chat que\r\n            recomienda productos REALES del catálogo. */}\r\n        <Pressable\r\n          onPress={() => irSeguro.libre('/lifebook-ai')}\r\n          hitSlop={8}\r\n          accessibilityRole=\"button\"\r\n          accessibilityLabel=\"Asistente\"\r\n          style={[styles.msgBtn, { marginRight: espaciado.e8 }]}\r\n        >\r\n          <Sparkles size={20} color={colors.primary} />\r\n        </Pressable>\r\n\r\n        <View style={styles.topBarSpacer} />\r\n\r\n        {/* La entrada al feed inmersivo de vídeo YA NO VIVE AQUÍ.\r\n            Estaba como icono en esta barra y el dueño pidió moverla junto al botón de\r\n            publicar (abajo, a la derecha), con un ▶ en vez del icono de vídeo: la barra\r\n            superior queda para lo que es navegación (ciudad, buscar, mensajes) y el\r\n            vídeo pasa a estar donde está la acción de publicar. Ver el FAB de abajo. */}\r\n\r\n        {/* B4 · Buscar como ICONO, no como barra ancha.\r\n            Antes había aquí un campo falso (\"Buscar en Life Book\") que ocupaba\r\n            todo el ancho disponible y solo servía para navegar a\r\n            /lifebook-search — donde está el campo de verdad. O sea: la barra\r\n            duplicaba visualmente algo que ya existe en su pantalla, y dejaba la\r\n            ciudad y los mensajes apretados en los bordes.\r\n            El icono de cámara que llevaba dentro era DECORATIVO: no tenía\r\n            onPress propio (toda la barra navegaba al buscador), y el escaneo\r\n            real ya es accesible desde /lifebook-messages (`onQr`), así que no se\r\n            pierde ninguna función al quitarlo. */}\r\n        <Pressable\r\n          onPress={() => irSeguro.libre('/lifebook-search')}\r\n          hitSlop={8}\r\n          accessibilityRole=\"search\"\r\n          accessibilityLabel=\"Buscar en Life Book\"\r\n          style={styles.msgBtn}\r\n        >\r\n          <Search size={20} color={colors.textPrimary} />\r\n        </Pressable>\r\n\r\n        {/* Aquí estaba el asistente de IA: el dueño lo quiere a la IZQUIERDA de la barra, así que\r\n            vive antes del espaciador. */}\r\n\r\n        {/* Aquí estaban el icono de Mensajes y el avatar del dueño, y los dos se han\r\n            ido a propósito: Mensajes ya vive en el dock (con su contador) y el avatar\r\n            se muda a la pantalla de mensajes, junto a los contadores de me gusta,\r\n            seguidores y comentarios. El perfil conserva su puerta en el dock. */}\r\n      </View>\r\n\r\n      {/* ═══════════ CANALES (tabs estilo XHS) ═══════════ */}      <View style={[styles.channelsWrap, { borderBottomColor: alpha(colors.border, 0.5) }]}>\r\n        <FlatList\r\n          horizontal\r\n          showsHorizontalScrollIndicator={false}\r\n          data={tabsVisibles}\r\n          keyExtractor={(c) => c.id}\r\n          contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e4 }}\r\n          renderItem={({ item }) => {\r\n            const active = item.id === channelId;\r\n            return (\r\n              <Pressable\r\n                onPress={() => abrirTab(item.id)}\r\n                accessibilityRole=\"tab\"\r\n                accessibilityState={{ selected: active }}\r\n                style={styles.channelTab}\r\n              >\r\n                <Text\r\n                  style={[\r\n                    styles.channelText,\r\n                    {\r\n                      color: active ? colors.textPrimary : colors.textSecondary,\r\n                      fontWeight: active ? '800' : '500',\r\n                      fontSize: active ? 14.5 : 13.5,\r\n                    },\r\n                  ]}\r\n                >\r\n                  {item.label}\r\n                </Text>\r\n                {/* Indicador inferior */}\r\n                {active && (\r\n                  <View\r\n                    style={[\r\n                      styles.channelIndicator,\r\n                      { backgroundColor: colors.primary },\r\n                    ]}\r\n                  />\r\n                )}\r\n              </Pressable>\r\n            );\r\n          }}\r\n        />\r\n      </View>\r\n\r\n      {/* SELECTOR DE CIUDAD — dentro de Ciudad, que es donde el dueño dijo que tiene sentido\r\n          cambiarla. La hoja de ciudades ya existía, pero NADA la abría: era código muerto y por eso\r\n          no había forma de mirar el contenido de otra ciudad. */}\r\n      {tab === 'nearby' ? (\r\n        <Pressable\r\n          onPress={() => setCityOpen(true)}\r\n          accessibilityLabel={\"Ciudad: \" + city + \". Cambiar de ciudad\"}\r\n          style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, paddingHorizontal: espaciado.e14, paddingTop: espaciado.e9 }}\r\n        >\r\n          <MapPin size={15} color={colors.primary} />\r\n          <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900' }}>{city}</Text>\r\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700' }}>▾ cambiar</Text>\r\n        </Pressable>\r\n      ) : null}\r\n      {/* ═══ CHIPS DE DISTANCIA (solo en la sección CIUDAD · 同城) ═══\r\n          La especificación pide tres distancias: 附近 (lo que se puede ir andando), 3 km (el\r\n          barrio) y 全城 (toda la ciudad, sin filtro). Filtran de verdad: el servidor calcula la\r\n          distancia real desde mi posición y deja fuera lo que no tiene sitio (no se promete una\r\n          distancia que no se sabe). Si no hay permiso de ubicación se dice, en vez de dejar el\r\n          feed vacío sin explicación. */}\r\n      {tab === 'nearby' ? (\r\n        <View style={{ borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: alpha(colors.border, 0.5) }}>\r\n          <FlatList\r\n            horizontal\r\n            showsHorizontalScrollIndicator={false}\r\n            data={LB_DISTANCIAS}\r\n            keyExtractor={(d) => d.id}\r\n            contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e8, paddingVertical: espaciado.e8 }}\r\n            renderItem={({ item, index }) => {\r\n              const activo = index === distIdx;\r\n              return (\r\n                <Pressable\r\n                  onPress={() => { void elegirDistancia(index); }}\r\n                  accessibilityRole=\"button\"\r\n                  accessibilityState={{ selected: activo }}\r\n                  accessibilityLabel={`${item.label} · ${item.hint}`}\r\n                  style={{\r\n                    paddingHorizontal: espaciado.e13, paddingVertical: espaciado.e7, borderRadius: radios.full, borderWidth: 1,\r\n                    borderColor: activo ? colors.primary : alpha(colors.border, 0.7),\r\n                    backgroundColor: activo ? alpha(colors.primary, 0.14) : 'transparent',\r\n                  }}\r\n                >\r\n                  <Text style={{ fontSize: tipografia.caption, fontWeight: activo ? '900' : '600', color: activo ? colors.primary : colors.textSecondary }}>\r\n                    {item.label}\r\n                  </Text>\r\n                </Pressable>\r\n              );\r\n            }}\r\n          />\r\n          {!miPos && distIdx !== LB_DISTANCIAS.length - 1 ? (\r\n            <Pressable onPress={() => { void pedirUbicacion(); }} accessibilityLabel=\"Activar la ubicación\" style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e8 }}>\r\n              <Text style={{ color: brand.warning, fontSize: tipografia.caption, fontWeight: '800' }}>📍 Activar la ubicación</Text>\r\n            </Pressable>\r\n          ) : null}\r\n        </View>\r\n      ) : null}\r\n\r\n      {/* ═══ CHIPS DE LA SECCIÓN ═══\r\n          La segunda fila: cada sección tiene los suyos (es lo que pidió el dueño) y\r\n          filtran DENTRO de ella, no son decorativos: «Comercio» en Seguidos es el\r\n          comercio de la gente que sigo, y en Ciudad el de mi ciudad. */}\r\n      <View style={{ borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: alpha(colors.border, 0.5) }}>\r\n        <FlatList\r\n          horizontal\r\n          showsHorizontalScrollIndicator={false}\r\n          data={chipsDeTab}\r\n          keyExtractor={(c) => `${tab}-${c.channel}-${c.type ?? 'todo'}`}\r\n          contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e8, paddingVertical: espaciado.e9 }}\r\n          renderItem={({ item, index }) => {\r\n            const activo = index === chipIdx;\r\n            return (\r\n              <Pressable\r\n                onPress={() => setChipIdx(index)}\r\n                accessibilityRole=\"button\"\r\n                accessibilityState={{ selected: activo }}\r\n                style={{\r\n                  paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e6, borderRadius: radios.full,\r\n                  backgroundColor: activo ? alpha(colors.primary, 0.14) : alpha(colors.textPrimary, 0.06),\r\n                }}\r\n              >\r\n                <Text\r\n                  style={{\r\n                    fontSize: tipografia.caption,\r\n                    fontWeight: activo ? '800' : '600',\r\n                    color: activo ? colors.primary : colors.textSecondary,\r\n                  }}\r\n                >\r\n                  {item.label}\r\n                </Text>\r\n              </Pressable>\r\n            );\r\n          }}\r\n        />\r\n      </View>\r\n\r\n      {/* ═══ A QUIEN SIGUES (solo en la pestaña «Seguidos», con el chip «Todo») ═══\r\n          Es el módulo de Xiaohongshu que pidió el dueño: en 关注, arriba, los avatares\r\n          de la gente que sigues. Se pinta SOLO ahí: en Descubrir o Ciudad no significa\r\n          nada. Sin anillo de «novedad» a propósito (haría falta estado por usuario y autor\r\n          que no existe); va ordenada por quién publicó más recientemente, que sí se puede\r\n          calcular.\r\n\r\n          OJO — DEFECTO ARREGLADO: la condición era `channelId === 'following'`, y ese canal\r\n          lo comparten TODOS los chips de la sección (Todo, Comercio, Vídeos, Debates: ver\r\n          `LB_CHIPS_BY_TAB`). Así que al filtrar por «Comercio» seguía saliendo el carrusel\r\n          de avatares, que ahí no pinta nada (el dueño lo vio: «has agregado el carrusel de\r\n          A QUIÉN SIGUES en comercio, no deben estar ahí»). Ahora exige además el chip\r\n          «Todo» (`chipIdx === 0`): es la portada de la sección, no un filtro. */}\r\n      {channelId === 'following' && chipIdx === 0 ? (\r\n        <AvatarsSeguidos\r\n          gente={seguidos}\r\n          colors={colors}\r\n          onOpen={(id) => irSeguro.libre('/lifebook-user', { id })}\r\n        />\r\n      ) : null}\r\n\r\n      {/* ═══════════ FEED ═══════════ */}\r\n      {loading ? (\r\n        <ScrollView showsVerticalScrollIndicator={false}>\r\n          <SkeletonGrid />\r\n        </ScrollView>\r\n      ) : error ? (\r\n        <View style={styles.center}>\r\n          <Text\r\n            style={{\r\n              color: colors.danger,\r\n              fontSize: tipografia.body,\r\n              fontWeight: '700',\r\n              textAlign: 'center',\r\n              paddingHorizontal: espaciado.e30,\r\n              marginBottom: espaciado.e14,\r\n            }}\r\n          >\r\n            {error}\r\n          </Text>\r\n          <Pressable\r\n            onPress={() => load(channelId, city, 'initial')}\r\n            style={[styles.retryBtn, { backgroundColor: colors.primary }]}\r\n          >\r\n            <RefreshCw size={14} color={brand.white} />\r\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>\r\n              Reintentar\r\n            </Text>\r\n          </Pressable>\r\n        </View>\r\n      ) : posts.length === 0 ? (\r\n        /* ── Estado vacío ── */\r\n        <View style={styles.center}>\r\n          <channel.icon size={44} color={alpha(channel.color, 0.4)} />\r\n          <Text\r\n            style={[\r\n              styles.emptyTitle,\r\n              { color: colors.textPrimary, marginTop: espaciado.e12 },\r\n            ]}\r\n          >\r\n            Sin publicaciones\r\n          </Text>\r\n          <Text\r\n            style={[\r\n              styles.emptyText,\r\n              { color: colors.textSecondary, marginTop: espaciado.e6 },\r\n            ]}\r\n          >\r\n            {EMPTY_COPY[channelId] ?? 'Todavía no hay publicaciones aquí.'}\r\n          </Text>\r\n        </View>\r\n      ) : (\r\n        /* ── Feed masonry (desliza en horizontal para cambiar de canal) ── */\r\n        <GestureDetector gesture={swipeChannels}>\r\n        <FlatList\r\n          data={[{ left: leftCol, right: rightCol }]}\r\n          keyExtractor={() => 'masonry'}\r\n          renderItem={({ item }) => (\r\n            <View style={styles.masonryRow}>\r\n              {/* Columna izquierda */}\r\n              <View style={styles.masonryCol}>\r\n                {item.left.map((post) => (\r\n                  <PostCard\r\n                    key={post.id}\r\n                    post={post}\r\n                    width={COLUMN_W}\r\n                    onPress={openPost}\r\n                    onMore={setMorePost}\r\n                    onLike={likeFromCard}\r\n                  />\r\n                ))}\r\n              </View>\r\n              {/* Columna derecha */}\r\n              <View style={styles.masonryCol}>\r\n                {item.right.map((post) => (\r\n                  <PostCard\r\n                    key={post.id}\r\n                    post={post}\r\n                    width={COLUMN_W}\r\n                    onPress={openPost}\r\n                    onMore={setMorePost}\r\n                    onLike={likeFromCard}\r\n                  />\r\n                ))}\r\n              </View>\r\n            </View>\r\n          )}\r\n          contentContainerStyle={{\r\n            paddingBottom: DOCK_BODY_H + insets.bottom + 80,\r\n            flexGrow: 1,\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          onEndReached={loadMore}\r\n          onEndReachedThreshold={0.5}\r\n          refreshing={refreshing}\r\n          onRefresh={() => load(channelId, city, 'refresh')}\r\n          ListFooterComponent={\r\n            loadingMore ? (\r\n              <ActivityIndicator\r\n                color={colors.primary}\r\n                style={{ marginVertical: espaciado.e16 }}\r\n              />\r\n            ) : posts.length > 0 && !nextCursor ? (\r\n              <Text\r\n                style={{\r\n                  textAlign: 'center',\r\n                  color: colors.textSecondary,\r\n                  fontSize: tipografia.caption,\r\n                  marginVertical: espaciado.e14,\r\n                }}\r\n              >\r\n                Ya estás al día ✨\r\n              </Text>\r\n            ) : null\r\n          }\r\n        />\r\n        </GestureDetector>\r\n      )}\r\n\r\n      {/* ═══════════ FABs: ▶ vídeos + publicar ═══════════\r\n          Los dos van en la MISMA columna y anclados juntos, no cada uno con su\r\n          `bottom` calculado a mano: así el ▶ queda siempre «justo encima» del de\r\n          publicar (que es lo que se pidió) y no se descuadran si el dock cambia de\r\n          alto. El orden visual es ▶ arriba, + abajo.\r\n          El ▶ es la MISMA navegación que hacía el icono que estaba en la barra\r\n          superior: abre /lifebook-videos por el canal y la ciudad que se están\r\n          mirando. Fondo oscuro y no `colors.primary`: el de publicar es LA acción de\r\n          la pantalla y dos botones del mismo color competirían por la mirada. */}\r\n      <View style={[styles.fabCol, { bottom: DOCK_BODY_H + insets.bottom + 16 }]}>\r\n        <Pressable\r\n          onPress={() => router.push({\r\n            pathname: '/lifebook-videos',\r\n            params: { channel: channelId, city },\r\n          } as never)}\r\n          accessibilityRole=\"button\"\r\n          accessibilityLabel=\"Vídeos en pantalla completa\"\r\n          style={[styles.fab, { backgroundColor: colors.textPrimary }]}\r\n        >\r\n          <Play size={22} color={brand.white} fill={brand.white} strokeWidth={1.5} style={{ marginLeft: espaciado.e3 }} />\r\n        </Pressable>\r\n\r\n        <Pressable\r\n          onPress={() => setPublishOpen(true)}\r\n          accessibilityRole=\"button\"\r\n          accessibilityLabel=\"Publicar contenido\"\r\n          style={[styles.fab, { backgroundColor: colors.primary }]}\r\n        >\r\n          <Plus size={24} color={brand.white} strokeWidth={2.5} />\r\n        </Pressable>\r\n      </View>\r\n\r\n      {/* ═══════════ DOCK ═══════════ */}\r\n      <FloatingFooter active=\"lifebook\" onNavigate={onDockNavigate} showUnreadBadge />\r\n\r\n      {/* ═══════════ MODAL: Reportar ═══════════ */}\r\n      <ReportSheet\r\n        post={morePost}\r\n        onClose={() => setMorePost(null)}\r\n        onReport={async (postId, reason) => {\r\n          try {\r\n            await lifebookActionsApi.report(postId, 'post', reason);\r\n            Alert.alert('Gracias', 'Tu reporte fue enviado. El equipo lo revisará.');\r\n          } catch (e) {\r\n            Alert.alert('Reportar', e instanceof Error ? e.message : 'No se pudo enviar el reporte.');\r\n          }\r\n        }}\r\n        onBlocked={() => load(channelId, city, 'initial')}\r\n      />\r\n\r\n      {/* ═══════════ MODAL: Publicar ═══════════ */}\r\n      <Modal\r\n        visible={publishOpen}\r\n        transparent\r\n        animationType=\"slide\"\r\n        onRequestClose={() => setPublishOpen(false)}\r\n      >\r\n        <Pressable\r\n          style={styles.backdrop}\r\n          onPress={() => setPublishOpen(false)}\r\n        >\r\n          <Pressable\r\n            style={[\r\n              styles.pubSheet,\r\n              {\r\n                backgroundColor: colors.card,\r\n                paddingBottom: insets.bottom + 20,\r\n              },\r\n            ]}\r\n            onPress={(e) => e.stopPropagation()}\r\n          >\r\n            {/* Handle */}\r\n            <View\r\n              style={[\r\n                styles.sheetHandle,\r\n                { backgroundColor: alpha(colors.textSecondary, 0.2) },\r\n              ]}\r\n            />\r\n            <Text\r\n              style={[\r\n                styles.pubSheetTitle,\r\n                { color: colors.textPrimary },\r\n              ]}\r\n            >\r\n              ¿Qué quieres publicar?\r\n            </Text>\r\n\r\n            {PUBLISH_OPTIONS.map((o) => {\r\n              const Icon = o.icon;\r\n              return (\r\n                <Pressable\r\n                  key={o.label}\r\n                  onPress={() => {\r\n                    setPublishOpen(false);\r\n                    router.push({\r\n                      pathname: o.route,\r\n                      params: o.params,\r\n                    } as never);\r\n                  }}\r\n                  style={({ pressed }) => [\r\n                    styles.pubRow,\r\n                    {\r\n                      backgroundColor: pressed\r\n                        ? alpha(o.color, 0.06)\r\n                        : alpha(colors.textSecondary, 0.04),\r\n                    },\r\n                  ]}\r\n                  accessibilityRole=\"button\"\r\n                >\r\n                  <View\r\n                    style={[\r\n                      styles.pubIcon,\r\n                      { backgroundColor: alpha(o.color, 0.12) },\r\n                    ]}\r\n                  >\r\n                    <Icon size={22} color={o.color} />\r\n                  </View>\r\n                  <View style={{ flex: 1 }}>\r\n                    <Text\r\n                      style={{\r\n                        color: colors.textPrimary,\r\n                        fontSize: 15,\r\n                        fontWeight: '800',\r\n                      }}\r\n                    >\r\n                      {o.label}\r\n                    </Text>\r\n                    <Text\r\n                      style={{\r\n                        color: colors.textSecondary,\r\n                        fontSize: tipografia.caption,\r\n                        marginTop: 1,\r\n                      }}\r\n                    >\r\n                      {o.desc}\r\n                    </Text>\r\n                  </View>\r\n                  <ChevronDown\r\n                    size={16}\r\n                    color={colors.textSecondary}\r\n                    style={{ transform: [{ rotate: '-90deg' }] }}\r\n                  />\r\n                </Pressable>\r\n              );\r\n            })}\r\n\r\n            <Pressable\r\n              onPress={() => setPublishOpen(false)}\r\n              style={{ paddingVertical: espaciado.e12, marginTop: espaciado.e4 }}\r\n            >\r\n              <Text\r\n                style={{\r\n                  textAlign: 'center',\r\n                  color: colors.textSecondary,\r\n                  fontWeight: '700',\r\n                  fontSize: tipografia.body,\r\n                }}\r\n              >\r\n                Cancelar\r\n              </Text>\r\n            </Pressable>\r\n          </Pressable>\r\n        </Pressable>\r\n      </Modal>\r\n\r\n      {/* ═══════════ MODAL: Selector de ciudad ═══════════ */}\r\n      <Modal\r\n        visible={cityOpen}\r\n        transparent\r\n        animationType=\"fade\"\r\n        onRequestClose={() => setCityOpen(false)}\r\n      >\r\n        <Pressable\r\n          style={styles.backdrop}\r\n          onPress={() => setCityOpen(false)}\r\n        >\r\n          <Pressable\r\n            style={[\r\n              styles.sheet,\r\n              {\r\n                backgroundColor: colors.card,\r\n                paddingBottom: insets.bottom + 18,\r\n              },\r\n            ]}\r\n            onPress={(e) => e.stopPropagation()}\r\n          >\r\n            <View\r\n              style={[\r\n                styles.sheetHandle,\r\n                { backgroundColor: alpha(colors.textSecondary, 0.2) },\r\n              ]}\r\n            />\r\n            <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>\r\n              Elige ciudad\r\n            </Text>\r\n            <Text\r\n              style={[styles.sheetHint, { color: colors.textSecondary }]}\r\n            >\r\n              Afecta a los canales de tu zona (Cerca, ventas, debates…)\r\n            </Text>\r\n\r\n            {/* OJO: con 20 ciudades la lista NO cabía en la hoja y no había forma de llegar a las\r\n                de abajo (reportado desde el teléfono). Se desplaza y tiene un tope de alto. */}\r\n            <ScrollView style={{ maxHeight: 420 }} showsVerticalScrollIndicator={false}>\r\n            {LB_CITIES.map((c) => {\r\n              const active = c === city;\r\n              return (\r\n                <Pressable\r\n                  key={c}\r\n                  onPress={() => {\r\n                    setCity(c);\r\n                    setCityOpen(false);\r\n                  }}\r\n                  style={[\r\n                    styles.cityOption,\r\n                    {\r\n                      backgroundColor: active\r\n                        ? alpha(colors.primary, 0.08)\r\n                        : 'transparent',\r\n                    },\r\n                  ]}\r\n                >\r\n                  <MapPin\r\n                    size={16}\r\n                    color={active ? colors.primary : colors.textSecondary}\r\n                  />\r\n                  <Text\r\n                    style={{\r\n                      color: active\r\n                        ? colors.primary\r\n                        : colors.textPrimary,\r\n                      fontSize: 15,\r\n                      fontWeight: active ? '800' : '600',\r\n                    }}\r\n                  >\r\n                    {c}\r\n                  </Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n            </ScrollView>\r\n\r\n            {/* ELEGIR LIBREMENTE: el mapa y el buscador de sitios que ya existen. Sirve para\r\n                explorar otra zona sin estar ahí (y para las ciudades que no van a estar nunca en\r\n                una lista corta). Al elegir un sitio, se toma su ciudad si el geocoder la da; si no,\r\n                se usa el propio sitio como referencia de la distancia. */}\r\n            <Pressable\r\n              onPress={() => { setCityOpen(false); setMapaCiudadOpen(true); }}\r\n              accessibilityLabel=\"Elegir en el mapa o buscar un sitio\"\r\n              style={{ marginTop: espaciado.e12, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e7 }}\r\n            >\r\n              <MapPin size={15} color={colors.primary} />\r\n              <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '900' }}>\r\n                🗺️ Elegir en el mapa o buscar\r\n              </Text>\r\n            </Pressable>\r\n\r\n            {meCity && meCity !== city && (\r\n              <Pressable\r\n                onPress={() => {\r\n                  setCity(meCity);\r\n                  setCityOpen(false);\r\n                }}\r\n                style={{ marginTop: espaciado.e6 }}\r\n              >\r\n                <Text\r\n                  style={{\r\n                    color: colors.primary,\r\n                    fontSize: tipografia.caption,\r\n                    textAlign: 'center',\r\n                    fontWeight: '600',\r\n                  }}\r\n                >\r\n                  Usar mi ciudad: {meCity}\r\n                </Text>\r\n              </Pressable>\r\n            )}\r\n          </Pressable>\r\n        </Pressable>\r\n      </Modal>\r\n      {/* TANDA I — ELEGIR CIUDAD O ZONA LIBREMENTE: el buscador de sitios y el mapa que ya existen\r\n          (los mismos de «Crear ruta» y las quedadas). Del resultado se saca la ciudad\r\n          («Sitio, Ciudad, País»); si no se puede, el punto elegido se usa como referencia para\r\n          medir distancias. Así se explora cualquier zona sin estar físicamente ahí. */}\r\n      <LocationPickerSheet\r\n        visible={mapaCiudadOpen}\r\n        onClose={() => setMapaCiudadOpen(false)}\r\n        title=\"¿Qué zona quieres explorar?\"\r\n        onSubmit={(loc) => {\r\n          const partes = String(loc.label ?? '').split(',').map((s) => s.trim()).filter(Boolean);\r\n          /* La ciudad se busca ENTRE LAS QUE CONOCEMOS: el geocoder devuelve cosas como\r\n             «EGTC - Tienda Semu, Malabo, Guinea Ecuatorial», y quedarse con una posición fija del\r\n             texto ponía el nombre de la TIENDA como si fuera la ciudad (pasó). */\r\n          const ciudad = partes.find((x) => (LB_CITIES as readonly string[]).some((c2) => c2.toLowerCase() === x.toLowerCase()))\r\n            ?? (partes.length >= 2 ? partes[partes.length - 2] : (partes[0] ?? ''));\r\n          if (ciudad) setCity(ciudad);\r\n          setPosManual({ lat: loc.lat, lng: loc.lng });\r\n          setMapaCiudadOpen(false);\r\n        }}\r\n      />\r\n    </View>\r\n  );\r\n}\r\n\r\n/* ──────────────────────────────────────────────\r\n   ESTILOS\r\n────────────────────────────────────────────── */\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1 },\r\n\r\n  /* ── Barra superior ── */\r\n  topBar: {\r\n    flexDirection: 'row',\r\n    alignItems: 'center',\r\n    paddingHorizontal: espaciado.e10,\r\n    paddingBottom: espaciado.e8,\r\n    gap: espaciado.e8,\r\n    borderBottomWidth: StyleSheet.hairlineWidth,\r\n  },\r\n  /**\r\n   * Separador flexible de la barra superior: deja la búsqueda a la derecha.\r\n   *\r\n   * (Antes empujaba también los mensajes y dejaba la ciudad a la izquierda; los dos\r\n   * se han quitado de la barra — ver el comentario de la cabecera — así que este\r\n   * estilo se queda solo con la búsqueda.)\r\n   */\r\n  topBarSpacer: { flex: 1 },\r\n  msgBtn: { padding: espaciado.e4 },\r\n\r\n  /* ── Canales ── */\r\n  channelsWrap: {\r\n    borderBottomWidth: StyleSheet.hairlineWidth,\r\n  },\r\n  channelTab: {\r\n    paddingHorizontal: espaciado.e10,\r\n    paddingVertical: espaciado.e10,\r\n    alignItems: 'center',\r\n  },\r\n  channelText: {\r\n    fontSize: tipografia.body,\r\n  },\r\n  channelIndicator: {\r\n    marginTop: espaciado.e4,\r\n    width: 20,\r\n    height: 2.5,\r\n    borderRadius: 2,\r\n  },\r\n\r\n  /* ── Feed masonry ── */\r\n  masonryRow: {\r\n    flexDirection: 'row',\r\n    paddingHorizontal: SIDE_PADDING,\r\n    gap: COLUMN_GAP,\r\n    paddingTop: espaciado.e8,\r\n  },\r\n  masonryCol: {\r\n    flex: 1,\r\n    gap: COLUMN_GAP,\r\n  },\r\n\r\n  /* ── Estados ── */\r\n  center: {\r\n    flex: 1,\r\n    alignItems: 'center',\r\n    justifyContent: 'center',\r\n    paddingBottom: 60,\r\n  },\r\n  retryBtn: {\r\n    flexDirection: 'row',\r\n    alignItems: 'center',\r\n    gap: espaciado.e7,\r\n    borderRadius: radios.full,\r\n    paddingHorizontal: espaciado.e18,\r\n    paddingVertical: espaciado.e10,\r\n  },\r\n  emptyTitle: { fontSize: tipografia.subtitle, fontWeight: '800' },\r\n  emptyText: {\r\n    fontSize: tipografia.body,\r\n    textAlign: 'center',\r\n    lineHeight: 19,\r\n    paddingHorizontal: 40,\r\n  },\r\n\r\n  /* ── FABs ──\r\n     `fabCol` es quien se ancla (posición y `bottom`, que va en línea porque depende\r\n     de los insets). Cada `fab` solo pone su tamaño, su forma y su sombra. */\r\n  fabCol: {\r\n    position: 'absolute',\r\n    right: 16,\r\n    alignItems: 'center',\r\n    gap: espaciado.e10,\r\n  },\r\n  fab: {\r\n    width: 52,\r\n    height: 52,\r\n    borderRadius: 26,\r\n    alignItems: 'center',\r\n    justifyContent: 'center',\r\n    ...elevation.md,\r\n  },\r\n\r\n  /* ── Modales ── */\r\n  backdrop: {\r\n    flex: 1,\r\n    backgroundColor: 'rgba(0,0,0,0.45)',\r\n    justifyContent: 'flex-end',\r\n  },\r\n  sheet: {\r\n    borderTopLeftRadius: 20,\r\n    borderTopRightRadius: 20,\r\n    padding: espaciado.e18,\r\n  },\r\n  sheetHandle: {\r\n    width: 36,\r\n    height: 4,\r\n    borderRadius: 2,\r\n    alignSelf: 'center',\r\n    marginBottom: espaciado.e14,\r\n  },\r\n  sheetTitle: { fontSize: 17, fontWeight: '900' },\r\n  sheetHint: { fontSize: tipografia.caption, marginTop: espaciado.e3, marginBottom: espaciado.e10 },\r\n  cityOption: {\r\n    flexDirection: 'row',\r\n    alignItems: 'center',\r\n    gap: espaciado.e10,\r\n    paddingVertical: espaciado.e12,\r\n    paddingHorizontal: espaciado.e12,\r\n    borderRadius: radios.md,\r\n  },\r\n  pubSheet: {\r\n    borderTopLeftRadius: 22,\r\n    borderTopRightRadius: 22,\r\n    padding: espaciado.e18,\r\n  },\r\n  pubSheetTitle: {\r\n    fontSize: 17,\r\n    fontWeight: '900',\r\n    marginBottom: espaciado.e14,\r\n    textAlign: 'center',\r\n  },\r\n  pubRow: {\r\n    flexDirection: 'row',\r\n    alignItems: 'center',\r\n    gap: espaciado.e12,\r\n    borderRadius: 14,\r\n    padding: espaciado.e13,\r\n    marginBottom: espaciado.e8,\r\n  },\r\n  pubIcon: {\r\n    width: 46,\r\n    height: 46,\r\n    borderRadius: 23,\r\n    alignItems: 'center',\r\n    justifyContent: 'center',\r\n  },\r\n});\r\n","/**\n * LA CIUDAD (同城) — feed por distancia.\n *\n * Lo que resuelve: el feed de la sección Ciudad puede pedir «lo que tengo cerca» (附近), «a un\n * paseo» (3 km) o **toda la ciudad** (全城), y cada tarjeta dice a qué distancia está y cuál es su\n * **sitio exacto** (POI).\n *\n * Vive en su propio fichero, como los demás módulos de estas tandas, para no tocar\n * `api/lifebook.ts` (que el dueño pidió no tocar). Se reutilizan sus TIPOS y su `toPostCard`, que\n * es lo que hace que la tarjeta siga siendo la misma de siempre.\n *\n * Servidor (tanda I): `channel=nearby` acepta `lat`, `lng`, `radiusKm`, `sort` y `since`; las notas\n * SIN sitio quedan fuera cuando se pide un radio (no se promete una distancia que no se sabe).\n */\nimport { http } from './httpClient';\nimport { toPostCard, type LbFeedPage, type LbPostBase, type LbPostCard } from './lifebook';\n\n/** Los tres chips de distancia de la especificación. `radiusKm: null` = 全城 (toda la ciudad). */\nexport const LB_DISTANCIAS: { id: 'cerca' | '3km' | 'ciudad'; label: string; radiusKm: number | null; hint: string }[] = [\n  { id: 'cerca', label: 'Cerca', radiusKm: 1, hint: 'Lo que puedes ir andando desde donde estás' },\n  { id: '3km', label: '3 km', radiusKm: 3, hint: 'Tu barrio: lo que se hace en bici o en 10 minutos' },\n  { id: 'ciudad', label: 'Toda la ciudad', radiusKm: null, hint: 'Todo lo de tu ciudad, sin filtro de distancia' },\n];\n\n/** Un post del feed con lo que añade la tanda I. */\nexport type LbPostConSitio = LbPostBase & {\n  /** El lugar exacto de la nota («Cafetería X»). `null` si la nota no tiene sitio. */\n  placeName?: string | null;\n  /** A qué distancia está de mí, en km (redondeado a 100 m). `null` si no se pidió con posición. */\n  distanceKm?: number | null;\n};\n\nexport interface LbFeedCiudadOpts {\n  city?: string; type?: string; cursor?: string; limit?: number;\n  /** Mi posición (para calcular la distancia). Sin ella, no hay distancia que enseñar. */\n  lat?: number | null; lng?: number | null;\n  /** El radio: 1 (附近), 3, o `null` para TODA la ciudad. */\n  radiusKm?: number | null;\n  /** `distance` (más cerca primero) · `hot` (más popular) · por defecto, lo más nuevo. */\n  sort?: 'distance' | 'hot' | null;\n  /** `1h` · `24h` · `7d` · `30d`. */\n  since?: string | null;\n}\n\nexport const ciudadApi = {\n  /**\n   * El feed de la ciudad. Es la MISMA ruta que `lifebookApi.feed`, con los parámetros nuevos.\n   * `radiusKm` solo se manda si hay posición: un radio sin posición no significa nada.\n   */\n  feed: (channel: string, o: LbFeedCiudadOpts = {}) => {\n    const conRadio = o.radiusKm !== null && o.radiusKm !== undefined && o.lat !== null && o.lat !== undefined && o.lng !== null && o.lng !== undefined;\n    const qs = [\n      `channel=${encodeURIComponent(channel)}`,\n      o.city ? `city=${encodeURIComponent(o.city)}` : '',\n      o.type ? `type=${encodeURIComponent(o.type)}` : '',\n      o.cursor ? `cursor=${encodeURIComponent(o.cursor)}` : '',\n      o.limit ? `limit=${o.limit}` : '',\n      o.lat !== null && o.lat !== undefined ? `lat=${o.lat}` : '',\n      o.lng !== null && o.lng !== undefined ? `lng=${o.lng}` : '',\n      conRadio ? `radiusKm=${o.radiusKm}` : '',\n      o.sort ? `sort=${o.sort}` : '',\n      o.since ? `since=${o.since}` : '',\n    ].filter(Boolean).join('&');\n    return http.get<LbFeedPage>(`/lifebook/posts/feed?${qs}`);\n  },\n};\n\n/** «400 m» · «3,2 km» · «15 km»: legible y sin decimales de más. */\nexport function etiquetaKm(km: number): string {\n  if (!Number.isFinite(km) || km < 0) return '';\n  if (km < 1) return `${Math.max(50, Math.round((km * 1000) / 50) * 50)} m`;\n  if (km < 10) return `${km.toFixed(1).replace('.', ',')} km`;\n  return `${Math.round(km)} km`;\n}\n\n/**\n * EL CENTRO DE CADA CIUDAD.\n *\n * La especificación lo dice: la distancia se mide desde **mi posición**… o **desde el centro de la\n * ciudad cuando he cambiado de ciudad a mano**. Sin esto, mirar Malabo desde otro sitio daría\n * «11.000 km» en cada tarjeta, que es verdad pero no sirve para nada: lo que quieres saber es a qué\n * distancia está de la ciudad que estás explorando.\n */\nexport const LB_CITY_CENTERS: Record<string, { lat: number; lng: number }> = {\n  malabo: { lat: 3.7504, lng: 8.7371 },\n  bata: { lat: 1.8639, lng: 9.7658 },\n  ebebiyin: { lat: 2.1511, lng: 11.3353 },\n  mongomo: { lat: 1.6267, lng: 11.3136 },\n  luba: { lat: 3.4567, lng: 8.5550 },\n};\n\n/** El centro de la ciudad, si lo conocemos (se comparan sin acentos ni mayúsculas). */\nexport function centroDe(ciudad: string | null | undefined): { lat: number; lng: number } | null {\n  const k = String(ciudad ?? '').trim().toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, '');\n  return LB_CITY_CENTERS[k] ?? null;\n}\n\n/**\n * La tarjeta de siempre, pero con el SITIO de la nota y su distancia.\n *\n * Se reutiliza `toPostCard` (el mismo que usa el resto de la app) y solo se reemplaza la línea de\n * ubicación: «Cafetería X · 3,2 km» en vez de «Malabo · Ela Nguema». Así la tarjeta no cambia de\n * aspecto ni hay un segundo diseño que mantener.\n */\nexport function tarjetaConSitio(post: LbPostBase): LbPostCard {\n  const card = toPostCard(post);\n  const p = post as LbPostConSitio;\n  const sitio = typeof p.placeName === 'string' && p.placeName.trim() ? p.placeName.trim() : null;\n  const km = typeof p.distanceKm === 'number' && Number.isFinite(p.distanceKm) ? p.distanceKm : null;\n  if (!sitio && km === null) return card;\n  const partes = [sitio ?? card.locationLabel, km !== null ? etiquetaKm(km) : null].filter(Boolean);\n  return { ...card, locationLabel: partes.join(' · ') };\n}\n","/**\n * AvatarsSeguidos — la fila de avatares de la gente que sigues, arriba del feed.\n *\n * Es lo que pidió el dueño para la pestaña «Seguidos», mirando el módulo de Xiaohongshu\n * (ver `docs/ORGANIZACION-LIFEBOOK-XIAOHONGSHU.md`): en 关注 aparecen los avatares de\n * las personas que sigues, y al tocar una se va a lo suyo.\n *\n * QUÉ NO TIENE, Y POR QUÉ: el **anillo rojo de «tiene novedad»**. En Xiaohongshu ese\n * anillo marca quién ha publicado algo que no has visto, y para eso hace falta estado\n * por (usuario, autor) que NO existe en ninguna tabla nuestra. Prefiero una fila sin\n * anillo y decirlo, que un anillo que mienta. Lo que sí hay es el ORDEN por actividad\n * (quien publicó hace poco, primero), que se puede calcular de verdad.\n */\nimport React from 'react';\nimport { FlatList, Image, Pressable, Text, View } from 'react-native';\nimport { alpha, espaciado, tipografia } from '@egrouteplan/ui-kit';\nimport { absUrl } from '../../api/config';\nimport type { LbSeguido } from '../../api/lifebookSeguidos';\n\nexport function AvatarsSeguidos({ gente, colors, onOpen }: {\n  gente: LbSeguido[];\n  colors: any;\n  onOpen: (id: string) => void;\n}) {\n  if (gente.length === 0) return null;\n\n  return (\n    <View style={{ paddingTop: espaciado.e8, paddingBottom: espaciado.e6 }}>\n      <Text style={{\n        fontSize: tipografia.micro, fontWeight: '900', letterSpacing: 0.4,\n        color: colors.textSecondary, paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e6,\n      }}>\n        A QUIEN SIGUES\n      </Text>\n      <FlatList\n        horizontal\n        data={gente}\n        keyExtractor={(x) => x.id}\n        showsHorizontalScrollIndicator={false}\n        contentContainerStyle={{ paddingHorizontal: espaciado.e12, gap: espaciado.e14 }}\n        renderItem={({ item }) => {\n          const nombre = item.fullName?.trim() || 'Usuario';\n          const inicial = nombre.slice(0, 1).toUpperCase() || 'U';\n          const foto = item.avatarUrl ? absUrl(item.avatarUrl) : '';\n          return (\n            <Pressable\n              onPress={() => onOpen(item.id)}\n              accessibilityLabel={`Ver el perfil de ${nombre}`}\n              style={{ alignItems: 'center', width: 62 }}\n            >\n              {foto ? (\n                <Image\n                  source={{ uri: foto }}\n                  style={{\n                    width: 54, height: 54, borderRadius: 27,\n                    backgroundColor: alpha(colors.textPrimary, 0.08),\n                  }}\n                />\n              ) : (\n                <View style={{\n                  width: 54, height: 54, borderRadius: 27,\n                  backgroundColor: alpha(colors.primary, 0.16),\n                  alignItems: 'center', justifyContent: 'center',\n                }}>\n                  <Text style={{ color: colors.primary, fontWeight: '900', fontSize: 19 }}>{inicial}</Text>\n                </View>\n              )}\n              <Text\n                numberOfLines={1}\n                style={{ fontSize: 10.5, color: colors.textSecondary, marginTop: espaciado.e5, maxWidth: 62, textAlign: 'center' }}\n              >\n                {nombre.split(' ')[0]}\n              </Text>\n            </Pressable>\n          );\n        }}\n      />\n    </View>\n  );\n}\n","/**\n * A quién sigo — para la fila de avatares de la pestaña «Seguidos».\n *\n * Vive en su propio fichero, como `lifebookPostOps.ts`, `lifebookComentarios.ts` y\n * `lifebookWatch.ts`, para no tocar `api/lifebook.ts` (que el dueño pidió no tocar) y\n * porque es aditivo. La hoja/pantalla solo importa `seguidosApi`.\n *\n * EL ENDPOINT ES NUEVO: no existía ninguno para listar a quién sigues. Lo que había\n * era `me/new-followers`, que es «quién me sigue A MÍ» — lo contrario. Se añadió en el\n * backend en esta misma ronda.\n */\nimport { http } from './httpClient';\n\n/** Una persona a la que sigues, con lo mínimo para pintar su avatar. */\nexport interface LbSeguido {\n  id: string;\n  fullName: string | null;\n  avatarUrl: string | null;\n  city: string | null;\n  /**\n   * Cuándo publicó por última vez. Se usa para ORDENAR (quien publicó hace poco,\n   * primero). `null` = nunca, o solo cosas no públicas.\n   *\n   * NO es un aviso de «tiene novedad»: eso exigiría estado por (usuario, autor) que no\n   * existe en la base, así que no se promete lo que no se puede cumplir.\n   */\n  lastPostAt: string | null;\n}\n\nexport const seguidosApi = {\n  /** A quién sigo, ordenado por actividad más reciente. */\n  lista: (limit = 20) => http.get<LbSeguido[]>(`/lifebook/me/following?limit=${limit}`),\n};\n","/**\n * MonederoMovimientosScreen — historial completo del monedero (/monedero-movimientos).\n * Paginación por cursor del servidor y filtro por tipo de movimiento.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, FlatList, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport { espaciado, radios, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { walletApi, type WalletTx } from '../api/wallet';\nimport { fmtXaf, txLabel, TxStatusChip } from './monedero';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { EmptyState } from '@egrouteplan/ui-kit';\nimport { Volver } from '../components/Volver';\n\nconst FILTROS: Array<{ id: string; label: string }> = [\n  { id: '', label: 'Todos' },\n  { id: 'DEPOSIT', label: 'Recargas' },\n  { id: 'WITHDRAWAL', label: 'Retiradas' },\n  { id: 'ESCROW_LOCK', label: 'Pagos' },\n  { id: 'ESCROW_RELEASE', label: 'Cobros' },\n  { id: 'ESCROW_REFUND', label: 'Reembolsos' },\n  { id: 'FEE', label: 'Comisiones' },\n];\n\nexport default function MonederoMovimientosScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [filtro, setFiltro] = useState('');\n  const [items, setItems] = useState<WalletTx[]>([]);\n  const [nextCursor, setNextCursor] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [cargandoMas, setCargandoMas] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const cargar = useCallback(async (tipo: string) => {\n    setLoading(true);\n    try {\n      const r = await walletApi.listTransactions(undefined, tipo || undefined, 25);\n      setItems(r.items ?? []);\n      setNextCursor(r.nextCursor ?? null);\n      setError(null);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudieron cargar los movimientos');\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(filtro); }, [filtro, cargar]);\n\n  const cargarMas = async () => {\n    if (!nextCursor || cargandoMas) return;\n    setCargandoMas(true);\n    try {\n      const r = await walletApi.listTransactions(nextCursor, filtro || undefined, 25);\n      setItems((prev) => [...prev, ...(r.items ?? [])]);\n      setNextCursor(r.nextCursor ?? null);\n    } catch {\n      // silencioso: el botón sigue disponible para reintentar\n    } finally {\n      setCargandoMas(false);\n    }\n  };\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      <View style={[styles.header, { borderBottomColor: colors.border }]}>\n        <Volver />\n        <Text style={[styles.headerTitle, { color: colors.textPrimary }]}>Movimientos</Text>\n        <View style={{ width: 24 }} />\n      </View>\n\n      <View style={{ paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12 }}>\n        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8 }}>\n          {FILTROS.map((f) => (\n            <Tactil\n              key={f.id}\n              onPress={() => setFiltro(f.id)}\n              style={[styles.filtro, { backgroundColor: filtro === f.id ? colors.primary : colors.card, borderColor: colors.border }]}\n              accessibilityRole=\"button\"\n            >\n              <Text style={{ color: filtro === f.id ? brand.white : colors.textSecondary, fontSize: tipografia.body, fontWeight: '800' }}>{f.label}</Text>\n            </Tactil>\n          ))}\n        </ScrollView>\n      </View>\n\n      {loading ? (\n        <View style={styles.center}><ActivityIndicator color={colors.primary} /></View>\n      ) : error ? (\n        <View style={styles.center}>\n          <Text style={{ color: colors.textSecondary, textAlign: 'center', paddingHorizontal: espaciado.e28 }}>{error}</Text>\n          <Tactil onPress={() => void cargar(filtro)} style={[styles.retryBtn, { backgroundColor: colors.primary }]} accessibilityRole=\"button\">\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Tactil>\n        </View>\n      ) : (\n        /*\n          LISTA VIRTUALIZADA (auditoría de diseño, D-04): antes era un ScrollView con .map(), que\n          pinta y mantiene TODAS las filas. Con cientos de movimientos eso atasca justo la pantalla\n          donde el usuario comprueba que su dinero está bien.\n        */\n        <FlatList\n          data={items}\n          keyExtractor={(t) => t.id}\n          style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border, margin: espaciado.e16, flexGrow: 0 }]}\n          contentContainerStyle={{ paddingVertical: espaciado.e4 }}\n          // Recicla lo que sale de pantalla y no monte todo de golpe.\n          initialNumToRender={12}\n          windowSize={7}\n          removeClippedSubviews\n          renderItem={({ item: t }) => {\n            const { label, sign } = txLabel(t);\n            return (\n              <View style={[styles.txRow, { borderBottomColor: colors.border }]}>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>{label}</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e2 }}>\n                    {new Date(t.createdAt).toLocaleString('es-GQ', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })}\n                  </Text>\n                </View>\n                <View style={{ alignItems: 'flex-end', gap: espaciado.e4 }}>\n                  <Text style={{ color: sign === '+' ? brand.successPressed : colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>\n                    {sign}{fmtXaf(Math.abs(Number(t.amount)))}\n                  </Text>\n                  <TxStatusChip status={t.status} />\n                </View>\n              </View>\n            );\n          }}\n          ListEmptyComponent={\n            <EmptyState\n              compacto\n              titulo=\"Todavía no hay movimientos de este tipo\"\n              texto=\"Cuando recargues, pagues o recibas un reembolso, aparecerán aquí con su fecha.\"\n              accionLabel=\"Recargar con un agente\"\n              onAccion={() => router.push('/monedero-recargar')}\n            />\n          }\n          ListFooterComponent={\n            nextCursor ? (\n              <Tactil onPress={() => void cargarMas()} style={[styles.masBtn, { borderColor: colors.border }]} accessibilityRole=\"button\">\n                {cargandoMas\n                  ? <ActivityIndicator color={colors.primary} size=\"small\" />\n                  : <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Cargar más</Text>}\n              </Tactil>\n            ) : null\n          }\n        />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  header: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  headerTitle: { fontSize: tipografia.subtitle, fontWeight: '900' },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e12 },\n  retryBtn: { borderRadius: radios.full, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e10 },\n  filtro: { borderRadius: radios.full, borderWidth: 1, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e7 },\n  card: { borderRadius: 18, borderWidth: 1, padding: espaciado.e16 },\n  txRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth },\n  masBtn: { borderRadius: 14, borderWidth: 1, paddingVertical: espaciado.e12, alignItems: 'center', marginTop: espaciado.e14 },\n});\n","/**\n * MonederoScreen — monedero NATIVO (/monedero). P2, 17/09.\n *\n * Sustituye al WebView de la maqueta (datos falsos: «María», tarjeta de agente\n * MBO-0042 fija, teléfono de ayuda chino). Todo aquí es REAL: saldo, cupo de\n * hoy y últimos movimientos vienen de la API del monedero (hk), y las acciones\n * Recargar/Retirar abren los flujos nativos con agente de efectivo (OTP).\n *\n * Estructura pensada para rails: hoy «Agente de efectivo» es el único rail de\n * entrada/salida; Muni Dinero entrará como segundo rail sin rehacer pantallas.\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowDownToLine, ArrowLeft, ArrowUpFromLine, ChevronRight, KeyRound, ShieldCheck, Wallet,\n} from 'lucide-react-native';\nimport { EmptyState, espaciado, radios, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { walletApi, type WalletBalance, type WalletTx } from '../api/wallet';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { Volver } from '../components/Volver';\n\nexport default function MonederoScreen() {\n  return (\n    <AuthGate>\n      <MonederoContent />\n    </AuthGate>\n  );\n}\n\n/** Etiqueta legible por tipo de movimiento (signo según si entra o sale). */\nexport const TX_LABEL: Record<string, { label: string; sign: '+' | '−' }> = {\n  DEPOSIT: { label: 'Recarga con agente', sign: '+' },\n  WITHDRAWAL: { label: 'Retirada de efectivo', sign: '−' },\n  ESCROW_LOCK: { label: 'Pago en garantía', sign: '−' },\n  ESCROW_RELEASE: { label: 'Cobro liberado', sign: '+' },\n  ESCROW_REFUND: { label: 'Reembolso de garantía', sign: '+' },\n  FEE: { label: 'Comisión', sign: '−' },\n  TRANSFER_IN: { label: 'Transferencia recibida', sign: '+' },\n  TRANSFER_OUT: { label: 'Transferencia enviada', sign: '−' },\n};\n\nexport const fmtXaf = (n: number) => `${Math.round(n).toLocaleString('es-GQ')} XAF`;\n\nexport function txLabel(t: WalletTx): { label: string; sign: '+' | '−' } {\n  const base = TX_LABEL[t.type] ?? { label: t.type, sign: '+' as const };\n  // El servidor manda `direction` (IN/OUT): si viene, manda sobre el mapa por tipo\n  // (un ESCROW_RELEASE es IN para quien cobra y no existe OUT del otro lado, etc.).\n  if (t.direction) return { label: base.label, sign: t.direction === 'IN' ? '+' : '−' };\n  return base;\n}\n\nexport function TxStatusChip({ status }: { status: string }) {\n  const map: Record<string, { bg: string; fg: string; label: string }> = {\n    COMPLETED: { bg: '#E9F7EF', fg: brand.successPressed, label: 'Completado' },\n    PENDING: { bg: '#FFF4E5', fg: brand.secondaryPressed, label: 'Pendiente' },\n    FAILED: { bg: '#FDECEC', fg: brand.dangerPressed, label: 'Fallido' },\n    CANCELLED: { bg: '#FDECEC', fg: brand.dangerPressed, label: 'Cancelado' },\n  };\n  const s = map[status] ?? { bg: '#EEF1F4', fg: '#5B6470', label: status };\n  return (\n    <View style={[chipStyles.chip, { backgroundColor: s.bg }]}>\n      <Text style={[chipStyles.txt, { color: s.fg }]}>{s.label}</Text>\n    </View>\n  );\n}\nconst chipStyles = StyleSheet.create({\n  chip: { borderRadius: radios.full, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e3 },\n  txt: { fontSize: 10, fontWeight: '900' },\n});\n\nfunction MonederoContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [balance, setBalance] = useState<WalletBalance | null>(null);\n  const [txs, setTxs] = useState<WalletTx[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [refreshing, setRefreshing] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const cargar = useCallback(async (silencioso = false) => {\n    if (!silencioso) setLoading(true);\n    try {\n      const [b, t] = await Promise.all([walletApi.getWallet(), walletApi.listTransactions(undefined, undefined, 8)]);\n      setBalance(b);\n      setTxs(t.items ?? []);\n      setError(null);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cargar el monedero');\n    } finally {\n      setLoading(false);\n      setRefreshing(false);\n    }\n  }, []);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      <View style={[styles.header, { borderBottomColor: colors.border }]}>\n        <Volver />\n        <Text style={[styles.headerTitle, { color: colors.textPrimary }]}>Monedero</Text>\n        <View style={{ width: 24 }} />\n      </View>\n\n      {loading && !balance ? (\n        <View style={styles.center}><ActivityIndicator color={colors.primary} /></View>\n      ) : error && !balance ? (\n        <View style={styles.center}>\n          <Text style={{ color: colors.textSecondary, textAlign: 'center', paddingHorizontal: espaciado.e28 }}>{error}</Text>\n          <Tactil onPress={() => void cargar()} style={[styles.retryBtn, { backgroundColor: colors.primary }]} accessibilityRole=\"button\">\n            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>Reintentar</Text>\n          </Tactil>\n        </View>\n      ) : (\n        <ScrollView\n          contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }}\n          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => { setRefreshing(true); void cargar(true); }} tintColor={colors.primary} />}\n        >\n          {/* Saldo */}\n          <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }}>\n              <Wallet size={16} color={colors.primary} />\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, fontWeight: '700' }}>Saldo disponible</Text>\n            </View>\n            <Text style={{ color: colors.textPrimary, fontSize: 34, fontWeight: '900', marginTop: espaciado.e6 }}>\n              {fmtXaf(Number(balance?.balanceAvailable ?? 0))}\n            </Text>\n            {Number(balance?.balanceEscrow ?? 0) > 0 && (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e4 }}>\n                En garantía: {fmtXaf(Number(balance?.balanceEscrow ?? 0))}\n              </Text>\n            )}\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, marginTop: espaciado.e8 }}>\n              <ShieldCheck size={12} color={colors.textSecondary} />\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>\n                Hoy puedes recargar {fmtXaf(Number(balance?.today?.depositRemaining ?? balance?.dailyLimit ?? 0))} · retirar {fmtXaf(Number(balance?.today?.withdrawalRemaining ?? balance?.dailyLimit ?? 0))}\n              </Text>\n            </View>\n          </View>\n\n          {/* Acciones — rail de efectivo (Muni Dinero llegará como segundo rail) */}\n          <View style={{ flexDirection: 'row', gap: espaciado.e12, marginTop: espaciado.e14 }}>\n            <Tactil\n              style={[styles.action, { backgroundColor: colors.primary }]}\n              onPress={() => router.push('/monedero-recargar')}\n              accessibilityRole=\"button\"\n            >\n              <ArrowDownToLine size={20} color={brand.white} />\n              <Text style={styles.actionTxt}>Recargar</Text>\n              <Text style={styles.actionHint}>con agente</Text>\n            </Tactil>\n            <Tactil\n              style={[styles.action, { backgroundColor: colors.card, borderColor: colors.border, borderWidth: 1 }]}\n              onPress={() => router.push('/monedero-retirar')}\n              accessibilityRole=\"button\"\n            >\n              <ArrowUpFromLine size={20} color={colors.primary} />\n              <Text style={[styles.actionTxt, { color: colors.textPrimary }]}>Retirar</Text>\n              <Text style={[styles.actionHint, { color: colors.textSecondary }]}>efectivo</Text>\n            </Tactil>\n          </View>\n\n          {/* Cambiar PIN */}\n          <Tactil\n            style={[styles.rowItem, { backgroundColor: colors.card, borderColor: colors.border }]}\n            onPress={() => router.push('/monedero-pin')}\n            accessibilityRole=\"button\"\n          >\n            <KeyRound size={16} color={colors.textSecondary} />\n            <Text style={{ flex: 1, color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700', marginLeft: espaciado.e10 }}>PIN del monedero</Text>\n            <ChevronRight size={16} color={colors.textSecondary} />\n          </Tactil>\n\n          {/* Últimos movimientos */}\n          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: espaciado.e20, marginBottom: espaciado.e8 }}>\n            <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>Últimos movimientos</Text>\n            <Tactil onPress={() => router.push('/monedero-movimientos')} accessibilityRole=\"button\">\n              <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Ver todos</Text>\n            </Tactil>\n          </View>\n          <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border, paddingVertical: espaciado.e4 }]}>\n            {txs.length === 0 ? (\n              /* Vacío con salida (D-17): qué es, por qué está vacío y qué hacer ahora. */\n              <EmptyState\n                compacto\n                titulo=\"Todavía no hay movimientos\"\n                texto=\"Aquí se apunta cada recarga, retirada y pago que hagas con el monedero.\"\n                accionLabel=\"Recargar con un agente\"\n                onAccion={() => router.push('/monedero-recargar' as never)}\n              />\n            ) : txs.map((t) => {\n              const { label, sign } = txLabel(t);\n              return (\n                <View key={t.id} style={[styles.txRow, { borderBottomColor: colors.border }]}>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>{label}</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e2 }}>\n                      {new Date(t.createdAt).toLocaleString('es-GQ', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })}\n                    </Text>\n                  </View>\n                  <View style={{ alignItems: 'flex-end', gap: espaciado.e4 }}>\n                    <Text style={{ color: sign === '+' ? brand.successPressed : colors.textPrimary, fontSize: tipografia.body, fontWeight: '900' }}>\n                      {sign}{fmtXaf(Math.abs(Number(t.amount)))}\n                    </Text>\n                    <TxStatusChip status={t.status} />\n                  </View>\n                </View>\n              );\n            })}\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  header: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  headerTitle: { fontSize: tipografia.subtitle, fontWeight: '900' },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e12 },\n  retryBtn: { borderRadius: radios.full, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e10 },\n  card: { borderRadius: 18, borderWidth: 1, padding: espaciado.e16 },\n  action: { flex: 1, borderRadius: 18, paddingVertical: espaciado.e16, alignItems: 'center', gap: espaciado.e4 },\n  actionTxt: { color: brand.white, fontSize: 14.5, fontWeight: '900' },\n  actionHint: { color: 'rgba(255,255,255,0.75)', fontSize: 10.5, fontWeight: '600' },\n  rowItem: {\n    flexDirection: 'row', alignItems: 'center', borderRadius: 14, borderWidth: 1,\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e13, marginTop: espaciado.e14,\n  },\n  txRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth },\n});\n","/**\n * Volver — el botón de atrás de la app, SEGURO POR DEFECTO.\n *\n * POR QUÉ EXISTE (auditoría de diseño, D-38 y prueba del dueño en el aparato):\n *   1. **No siempre volvía.** Había **152 llamadas a `router.back()` en 98 archivos** y solo 6 usos\n *      del ayudante que sí sabe salir. `router.back()` no hace NADA cuando la pantalla no tiene\n *      historial: si llegaste por un enlace, por una notificación o tras un `replace`, el botón\n *      parece roto. Aquí, si no se puede volver, se va al inicio: siempre pasa algo.\n *   2. **No siempre se veía.** El botón es lo primero que el usuario busca; aquí se dibuja con un\n *      área táctil de 44 pt, etiqueta para lectores de pantalla y sin depender de que la cabecera\n *      esté dentro del contenido que se desplaza.\n *\n * Uso:  <Volver />                     → vuelve o va al inicio\n *       <Volver onPress={…} />         → cuando la pantalla necesita hacer algo más (cerrar un modal)\n *       <Volver color={colors.white} /> → sobre fondos oscuros o fotos (un token, nunca un literal)\n */\nimport React from 'react';\nimport { Pressable, StyleSheet } from 'react-native';\nimport { ArrowLeft } from 'lucide-react-native';\nimport { useTheme } from '@egrouteplan/ui-kit';\nimport { ir } from '../constants/rutas';\n\nexport function Volver({\n  onPress,\n  color,\n  accessibilityLabel = 'Volver',\n  size = 22,\n}: {\n  onPress?: () => void;\n  color?: string;\n  accessibilityLabel?: string;\n  size?: number;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress ?? (() => ir.atras())}\n      // 44 pt de área táctil aunque el icono sea pequeño: el dedo no apunta.\n      hitSlop={12}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel}\n      style={({ pressed }) => [styles.btn, { opacity: pressed ? 0.55 : 1 }]}\n    >\n      <ArrowLeft size={size} color={color ?? colors.textPrimary} />\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  btn: { width: 44, height: 44, alignItems: 'center', justifyContent: 'center' },\n});\n","/**\n * MonederoPinScreen — alta/cambio del PIN del monedero (/monedero-pin).\n * El PIN es lo único que autoriza dinero (pagos, recargas, retiradas); para\n * fijarlo o cambiarlo se pide la contraseña de la cuenta (verificación real en\n * el servidor, auth unificada).\n */\nimport React, { useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, KeyRound } from 'lucide-react-native';\nimport { espaciado, InlineError, PrimaryButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { fijarPin } from '../api/settlement';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { ir } from '../constants/rutas';\n\nexport default function MonederoPinScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [pwd, setPwd] = useState('');\n  const [pin, setPin] = useState('');\n  const [pin2, setPin2] = useState('');\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState<string | null>(null);\n  const [ok, setOk] = useState(false);\n\n  const listo = pwd.length >= 4 && pin.length === 6 && pin2.length === 6;\n\n  const guardar = async () => {\n    if (busy || !listo) return;\n    if (pin !== pin2) { setErr('Los dos PIN no coinciden.'); return; }\n    setBusy(true); setErr(null);\n    try {\n      await fijarPin(pin, pwd);\n      setOk(true);\n    } catch (e) {\n      setErr(e instanceof Error ? e.message : 'No se pudo guardar el PIN');\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      <View style={[styles.header, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => ir.atras()} hitSlop={12} accessibilityRole=\"button\" accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.headerTitle, { color: colors.textPrimary }]}>PIN del monedero</Text>\n        <View style={{ width: 24 }} />\n      </View>\n\n      {ok ? (\n        <View style={styles.doneWrap}>\n          <View style={[styles.okIcon, { backgroundColor: colors.surface }]}>\n            <KeyRound size={26} color={colors.primary} />\n          </View>\n          <Text style={{ color: colors.textPrimary, fontSize: tipografia.subtitle, fontWeight: '900', textAlign: 'center' }}>\n            PIN guardado\n          </Text>\n          <PrimaryButton title=\"Volver al monedero\" onPress={() => ir.atras()} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }} keyboardShouldPersistTaps=\"handled\">\n          <Text style={[styles.label, { color: colors.textSecondary }]}>Contraseña de tu cuenta</Text>\n          <TextInput\n            style={[styles.input, { backgroundColor: colors.card, borderColor: colors.border, color: colors.textPrimary }]}\n            placeholder=\"La misma con la que entras en la app\"\n            placeholderTextColor={colors.textSecondary}\n            value={pwd}\n            onChangeText={setPwd}\n            secureTextEntry\n            autoCorrect={false}\n            editable={!busy}\n            accessibilityLabel=\"Contraseña de tu cuenta\"\n          />\n          <Text style={[styles.label, { color: colors.textSecondary, marginTop: espaciado.e18 }]}>PIN nuevo (6 dígitos)</Text>\n          <TextInput\n            style={[styles.pinInput, { backgroundColor: colors.card, borderColor: colors.border, color: colors.textPrimary }]}\n            placeholder=\"••••••\"\n            placeholderTextColor={colors.textSecondary}\n            value={pin}\n            onChangeText={(t) => setPin(t.replace(/\\D/g, '').slice(0, 6))}\n            secureTextEntry\n            keyboardType=\"number-pad\"\n            maxLength={6}\n            editable={!busy}\n            accessibilityLabel=\"PIN nuevo, 6 dígitos\"\n          />\n          <Text style={[styles.label, { color: colors.textSecondary, marginTop: espaciado.e14 }]}>Repite el PIN</Text>\n          <TextInput\n            style={[styles.pinInput, { backgroundColor: colors.card, borderColor: colors.border, color: colors.textPrimary }]}\n            placeholder=\"••••••\"\n            placeholderTextColor={colors.textSecondary}\n            value={pin2}\n            onChangeText={(t) => setPin2(t.replace(/\\D/g, '').slice(0, 6))}\n            secureTextEntry\n            keyboardType=\"number-pad\"\n            maxLength={6}\n            editable={!busy}\n            accessibilityLabel=\"Repite el PIN nuevo\"\n          />\n          {err ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={err} /></View> : null}\n          <View style={{ marginTop: espaciado.e24 }}>\n            {busy\n              ? <ActivityIndicator color={colors.primary} />\n              : <PrimaryButton title=\"Guardar PIN\" onPress={() => void guardar()} disabled={!listo} />}\n          </View>\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  header: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  headerTitle: { fontSize: tipografia.subtitle, fontWeight: '900' },\n  label: { fontSize: tipografia.caption, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.4, marginBottom: espaciado.e8 },\n  input: { borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e11, fontSize: tipografia.body },\n  pinInput: {\n    borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e11,\n    fontSize: 22, letterSpacing: 8, textAlign: 'center',\n  },\n  doneWrap: { flex: 1, padding: espaciado.e20, justifyContent: 'center', gap: espaciado.e16 },\n  okIcon: { width: 60, height: 60, borderRadius: 20, alignItems: 'center', justifyContent: 'center', alignSelf: 'center' },\n});\n","/**\n * MonederoRecargarScreen — recarga en efectivo con agente (/monedero-recargar).\n *\n * Flujo real del backend: importe → agente → PIN → POST /wallet/deposits →\n * la operación queda PENDIENTE con un OTP: el usuario entrega el efectivo y\n * enseña el código al agente; el saldo se acredita cuando el agente confirma.\n * (La maqueta WebView pedía teclear el UUID del agente a mano — aquí se elige\n * de la lista real de GET /wallet/agents, parche 95.)\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Bike, Check } from 'lucide-react-native';\nimport { EmptyState, espaciado, PrimaryButton, radios, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { whatsappSoporte } from '../constants/soporte';\nimport { AuthGate } from '../core/AuthGate';\nimport { PinSheet } from '@egrouteplan/ui-kit';\nimport { walletApi, type WalletAgent, type WalletBalance } from '../api/wallet';\nimport { fijarPin } from '../api/settlement';\nimport { fmtXaf } from './monedero';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { InlineError } from '@egrouteplan/ui-kit';\nimport { mensajeDeError } from '../constants/errores';\nimport { Volver } from '../components/Volver';\nimport { ir } from '../constants/rutas';\n\nexport default function MonederoRecargarScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n\n  const [agents, setAgents] = useState<WalletAgent[] | null>(null);\n  const [balance, setBalance] = useState<WalletBalance | null>(null);\n  const [importe, setImporte] = useState('');\n  const [agenteId, setAgenteId] = useState<string | null>(null);\n  const [pinOpen, setPinOpen] = useState(false);\n  const [pinBusy, setPinBusy] = useState(false);\n  const [pinErr, setPinErr] = useState<string | null>(null);\n  const [needSetPin, setNeedSetPin] = useState(false);\n  const [otp, setOtp] = useState<string | null>(null);\n  const [formErr, setFormErr] = useState<string | null>(null);\n  /** El monedero exige identidad verificada: si el servidor la pide, hay que poder ir a hacerla. */\n  const [kycFalta, setKycFalta] = useState(false);\n\n  useEffect(() => {\n    (async () => {\n      try {\n        const [a, b] = await Promise.all([walletApi.listAgents(), walletApi.getWallet()]);\n        setAgents(a.items ?? []);\n        setBalance(b);\n      } catch {\n        setAgents([]);\n      }\n    })();\n  }, []);\n\n  const cantidad = parseInt(importe, 10) || 0;\n  const restante = Number(balance?.today?.depositRemaining ?? balance?.dailyLimit ?? 0);\n  const valido = cantidad >= 100 && cantidad <= restante && !!agenteId;\n\n  const confirmar = async (pin: string, password?: string) => {\n    if (pinBusy) return;\n    setPinBusy(true); setPinErr(null);\n    try {\n      if (needSetPin) { await fijarPin(pin, password); }\n      const token = await walletApi.paymentToken(pin, 'DEPOSIT', cantidad);\n      const op = await walletApi.requestDeposit(cantidad, agenteId!, token);\n      setOtp(op.otp ? String(op.otp) : '······');\n      setPinOpen(false);\n    } catch (e) {\n      const msg = mensajeDeError(e, 'No se pudo iniciar la recarga');\n      if ((e as { code?: string })?.code === 'KYC_REQUIRED') {\n        // Sin identidad verificada no hay dinero: mensaje directo, sin cambiar a alta de PIN.\n        setPinOpen(false);\n        setFormErr(msg);\n        setKycFalta(true);\n        return;\n      }\n      if (!needSetPin) {\n        setNeedSetPin(true);\n        setPinErr('Si es tu primera vez: escribe tu contraseña y elige tu PIN de 6 dígitos.');\n      } else {\n        setPinErr(msg);\n      }\n    } finally {\n      setPinBusy(false);\n    }\n  };\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      <View style={[styles.header, { borderBottomColor: colors.border }]}>\n        <Volver />\n        <Text style={[styles.headerTitle, { color: colors.textPrimary }]}>Recargar</Text>\n        <View style={{ width: 24 }} />\n      </View>\n\n      {otp ? (\n        /* Operación creada: enseñar el OTP al agente */\n        <View style={styles.doneWrap}>\n          <View style={[styles.otpCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n              Enseña este código al agente junto con el efectivo:\n            </Text>\n            <Text style={{ color: colors.primary, fontSize: 40, fontWeight: '900', letterSpacing: 10, textAlign: 'center', marginVertical: espaciado.e14 }}>\n              {otp}\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center', lineHeight: 17 }}>\n              Tu saldo se acredita cuando el agente confirme.{'\\n'}El código caduca en 30 minutos.\n            </Text>\n          </View>\n          <PrimaryButton title=\"Entendido\" onPress={() => ir.atras()} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }}>\n          <Text style={[styles.label, { color: colors.textSecondary }]}>Importe</Text>\n          <View style={[styles.amountBox, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <TextInput\n              style={{ flex: 1, color: colors.textPrimary, fontSize: tipografia.display, fontWeight: '900' }}\n              placeholder=\"0\"\n              placeholderTextColor={colors.textSecondary}\n              value={importe}\n              onChangeText={(t) => setImporte(t.replace(/\\D/g, '').slice(0, 7))}\n              keyboardType=\"number-pad\"\n            />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, fontWeight: '800' }}>XAF</Text>\n          </View>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e6 }}>\n            Hoy puedes recargar hasta {fmtXaf(restante)}.\n          </Text>\n\n          <Text style={[styles.label, { color: colors.textSecondary, marginTop: espaciado.e20 }]}>Agente de efectivo</Text>\n          {agents === null ? (\n            <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e12 }} />\n          ) : agents.length === 0 ? (\n            /*\n              Sin agente de efectivo no hay forma de ENTREGAR el dinero: un texto que solo informa\n              deja al usuario bloqueado en una pantalla de dinero. La salida real es soporte.\n            */\n            <EmptyState\n              compacto\n              titulo=\"No hay ningún agente de efectivo disponible\"\n              texto=\"Los agentes aparecen aquí en cuanto se conectan. Sin agente no se puede entregar tu efectivo.\"\n              accionLabel=\"Escribir a soporte\"\n              onAccion={() => { void whatsappSoporte('Hola, quiero recargar el monedero y no veo agentes de efectivo disponibles.'); }}\n            />\n          ) : agents.map((a) => (\n            <Tactil\n              key={a.id}\n              onPress={() => setAgenteId(a.id)}\n              style={[styles.agentRow, {\n                backgroundColor: colors.card,\n                borderColor: agenteId === a.id ? colors.primary : colors.border,\n                borderWidth: agenteId === a.id ? 2 : 1,\n              }]}\n              accessibilityLabel={`Agente ${a.name}, ${a.code}, zona ${a.zone}`}\n              accessibilityState={{ selected: agenteId === a.id }}\n              accessibilityRole=\"button\"\n            >\n              <View style={[styles.agentIcon, { backgroundColor: colors.surface }]}>\n                <Bike size={18} color={colors.primary} />\n              </View>\n              <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{a.name}</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>{a.code} · {a.zone}</Text>\n              </View>\n              {agenteId === a.id && <Check size={18} color={colors.primary} />}\n            </Tactil>\n          ))}\n\n          {formErr ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={formErr} /></View> : null}\n          {/*\n            AUDITORÍA DE DISEÑO (D-33): el monedero exige identidad verificada y el aviso solo\n            pintaba texto. El usuario elegía importe, agente y PIN para descubrir al final que no\n            podía seguir, y no había ninguna salida. Aquí está la puerta.\n          */}\n          {kycFalta && (\n            <Tactil\n              onPress={() => router.push('/kyc')}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Verificar mi identidad\"\n              style={{ marginTop: espaciado.e10, alignSelf: 'flex-start' }}\n            >\n              <Text style={[styles.label, { color: colors.primary, textTransform: 'none', letterSpacing: 0 }]}>Verificar mi identidad →</Text>\n            </Tactil>\n          )}\n\n          <View style={{ marginTop: espaciado.e24 }}>\n            <PrimaryButton\n              title={cantidad > 0 ? `Recargar ${fmtXaf(cantidad)}` : 'Recargar'}\n              onPress={() => {\n                if (!valido) {\n                  setFormErr(cantidad < 100 ? 'El importe mínimo es 100 XAF.' : !agenteId ? 'Elige un agente.' : 'Supera tu límite de hoy.');\n                  return;\n                }\n                setFormErr(null); setPinErr(null); setNeedSetPin(false); setPinOpen(true);\n              }}\n            />\n          </View>\n        </ScrollView>\n      )}\n\n      <PinSheet\n        visible={pinOpen}\n        title={`Recargar ${fmtXaf(cantidad)}`}\n        subtitle={needSetPin\n          ? 'Primer uso: escribe tu contraseña y elige un PIN de 6 dígitos.'\n          : 'Introduce tu PIN del monedero.'}\n        busy={pinBusy}\n        error={pinErr}\n        needPassword={needSetPin}\n        confirmLabel={needSetPin ? 'Guardar PIN y recargar' : 'Confirmar recarga'}\n        onClose={() => setPinOpen(false)}\n        onConfirm={(pin, pwd) => void confirmar(pin, pwd)}\n      />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  header: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  headerTitle: { fontSize: tipografia.subtitle, fontWeight: '900' },\n  label: { fontSize: tipografia.body, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.4 },\n  amountBox: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderRadius: radios.lg, borderWidth: 1,\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, marginTop: espaciado.e8,\n  },\n  agentRow: {\n    flexDirection: 'row', alignItems: 'center', borderRadius: radios.lg,\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e12, marginTop: espaciado.e8,\n  },\n  agentIcon: { width: 38, height: 38, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  doneWrap: { flex: 1, padding: espaciado.e20, justifyContent: 'center', gap: espaciado.e18 },\n  otpCard: { borderRadius: 20, borderWidth: 1, padding: espaciado.e22 },\n});\n","/**\n * MonederoRetirarScreen — retirada en efectivo con agente (/monedero-retirar).\n *\n * Flujo real: importe → agente → justificación AML (obligatoria, mín. 10\n * caracteres, exigida por el servidor) → PIN → POST /wallet/withdrawals →\n * hold atómico (importe + comisión pasan a garantía) y OTP: el usuario recibe\n * el efectivo del agente y le da el código; si se cancela, el hold se devuelve.\n */\nimport React, { useEffect, useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Bike, Check } from 'lucide-react-native';\nimport { EmptyState, espaciado, PrimaryButton, radios, Tactil, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { whatsappSoporte } from '../constants/soporte';\nimport { AuthGate } from '../core/AuthGate';\nimport { PinSheet } from '@egrouteplan/ui-kit';\nimport { walletApi, type WalletAgent, type WalletBalance } from '../api/wallet';\nimport { fijarPin } from '../api/settlement';\nimport { fmtXaf } from './monedero';\nimport { brand } from '@egrouteplan/ui-kit';\nimport { InlineError } from '@egrouteplan/ui-kit';\nimport { mensajeDeError } from '../constants/errores';\nimport { Volver } from '../components/Volver';\nimport { ir } from '../constants/rutas';\n\nexport default function MonederoRetirarScreen() {\n  return (\n    <AuthGate>\n      <Contenido />\n    </AuthGate>\n  );\n}\n\nfunction Contenido() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n\n  const [agents, setAgents] = useState<WalletAgent[] | null>(null);\n  const [balance, setBalance] = useState<WalletBalance | null>(null);\n  const [importe, setImporte] = useState('');\n  const [agenteId, setAgenteId] = useState<string | null>(null);\n  const [justificacion, setJustificacion] = useState('');\n  const [pinOpen, setPinOpen] = useState(false);\n  const [pinBusy, setPinBusy] = useState(false);\n  const [pinErr, setPinErr] = useState<string | null>(null);\n  const [needSetPin, setNeedSetPin] = useState(false);\n  const [otp, setOtp] = useState<string | null>(null);\n  const [fee, setFee] = useState<number | null>(null);\n  const [formErr, setFormErr] = useState<string | null>(null);\n  /** El monedero exige identidad verificada: si el servidor la pide, hay que poder ir a hacerla. */\n  const [kycFalta, setKycFalta] = useState(false);\n\n  useEffect(() => {\n    (async () => {\n      try {\n        const [a, b] = await Promise.all([walletApi.listAgents(), walletApi.getWallet()]);\n        setAgents(a.items ?? []);\n        setBalance(b);\n      } catch {\n        setAgents([]);\n      }\n    })();\n  }, []);\n\n  const cantidad = parseInt(importe, 10) || 0;\n  const disponible = Number(balance?.balanceAvailable ?? 0);\n  const restanteHoy = Number(balance?.today?.withdrawalRemaining ?? balance?.dailyLimit ?? 0);\n  const tope = Math.min(disponible, restanteHoy);\n  const justOk = justificacion.trim().length >= 10;\n  const valido = cantidad >= 100 && cantidad <= tope && !!agenteId && justOk;\n\n  const confirmar = async (pin: string, password?: string) => {\n    if (pinBusy) return;\n    setPinBusy(true); setPinErr(null);\n    try {\n      if (needSetPin) { await fijarPin(pin, password); }\n      const token = await walletApi.paymentToken(pin, 'WITHDRAWAL', cantidad);\n      const op = await walletApi.requestWithdrawal(cantidad, agenteId!, justificacion.trim(), token);\n      setOtp(op.otp ? String(op.otp) : '······');\n      setFee(typeof op.fee === 'number' ? op.fee : null);\n      setPinOpen(false);\n    } catch (e) {\n      const msg = mensajeDeError(e, 'No se pudo iniciar la retirada');\n      if ((e as { code?: string })?.code === 'KYC_REQUIRED') {\n        // Sin identidad verificada no hay dinero: mensaje directo, sin cambiar a alta de PIN.\n        setPinOpen(false);\n        setFormErr(msg);\n        setKycFalta(true);\n        return;\n      }\n      if (!needSetPin) {\n        setNeedSetPin(true);\n        setPinErr('Si es tu primera vez: escribe tu contraseña y elige tu PIN de 6 dígitos.');\n      } else {\n        setPinErr(msg);\n      }\n    } finally {\n      setPinBusy(false);\n    }\n  };\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top }]}>\n      <View style={[styles.header, { borderBottomColor: colors.border }]}>\n        <Volver />\n        <Text style={[styles.headerTitle, { color: colors.textPrimary }]}>Retirar</Text>\n        <View style={{ width: 24 }} />\n      </View>\n\n      {otp ? (\n        <View style={styles.doneWrap}>\n          <View style={[styles.otpCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n              Da este código al agente SOLO cuando te entregue el efectivo:\n            </Text>\n            <Text style={{ color: colors.primary, fontSize: 40, fontWeight: '900', letterSpacing: 10, textAlign: 'center', marginVertical: espaciado.e14 }}>\n              {otp}\n            </Text>\n            {fee !== null && fee > 0 && (\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, textAlign: 'center' }}>\n                Comisión de retirada: {fmtXaf(fee)}.\n              </Text>\n            )}\n          </View>\n          <PrimaryButton title=\"Entendido\" onPress={() => ir.atras()} />\n        </View>\n      ) : (\n        <ScrollView contentContainerStyle={{ padding: espaciado.e16, paddingBottom: 40 }} keyboardShouldPersistTaps=\"handled\">\n          <Text style={[styles.label, { color: colors.textSecondary }]}>Importe</Text>\n          <View style={[styles.amountBox, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <TextInput\n              style={{ flex: 1, color: colors.textPrimary, fontSize: tipografia.display, fontWeight: '900' }}\n              placeholder=\"0\"\n              placeholderTextColor={colors.textSecondary}\n              value={importe}\n              onChangeText={(t) => setImporte(t.replace(/\\D/g, '').slice(0, 7))}\n              keyboardType=\"number-pad\"\n            />\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, fontWeight: '800' }}>XAF</Text>\n          </View>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.body, marginTop: espaciado.e6 }}>\n            Disponible: {fmtXaf(disponible)} · hoy puedes retirar hasta {fmtXaf(restanteHoy)}.\n          </Text>\n\n          <Text style={[styles.label, { color: colors.textSecondary, marginTop: espaciado.e20 }]}>Agente de efectivo</Text>\n          {agents === null ? (\n            <ActivityIndicator color={colors.primary} style={{ marginTop: espaciado.e12 }} />\n          ) : agents.length === 0 ? (\n            /*\n              Sin agente de efectivo no hay forma de RECOGER el dinero: un texto que solo informa\n              deja al usuario bloqueado en una pantalla de dinero. La salida real es soporte.\n            */\n            <EmptyState\n              compacto\n              titulo=\"No hay ningún agente de efectivo disponible\"\n              texto=\"Los agentes aparecen aquí en cuanto se conectan. Sin agente no se puede recoger tu efectivo.\"\n              accionLabel=\"Escribir a soporte\"\n              onAccion={() => { void whatsappSoporte('Hola, quiero retirar del monedero y no veo agentes de efectivo disponibles.'); }}\n            />\n          ) : agents.map((a) => (\n            <Tactil\n              key={a.id}\n              onPress={() => setAgenteId(a.id)}\n              style={[styles.agentRow, {\n                backgroundColor: colors.card,\n                borderColor: agenteId === a.id ? colors.primary : colors.border,\n                borderWidth: agenteId === a.id ? 2 : 1,\n              }]}\n              accessibilityLabel={`Agente ${a.name}, ${a.code}, zona ${a.zone}`}\n              accessibilityState={{ selected: agenteId === a.id }}\n              accessibilityRole=\"button\"\n            >\n              <View style={[styles.agentIcon, { backgroundColor: colors.surface }]}>\n                <Bike size={18} color={colors.primary} />\n              </View>\n              <View style={{ flex: 1, marginLeft: espaciado.e10 }}>\n                <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{a.name}</Text>\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.body }}>{a.code} · {a.zone}</Text>\n              </View>\n              {agenteId === a.id && <Check size={18} color={colors.primary} />}\n            </Tactil>\n          ))}\n\n          <Text style={[styles.label, { color: colors.textSecondary, marginTop: espaciado.e20 }]}>Motivo de la retirada</Text>\n          <TextInput\n            style={[styles.input, { backgroundColor: colors.card, borderColor: colors.border, color: colors.textPrimary }]}\n            placeholder=\"Ej.: gastos de la semana\"\n            placeholderTextColor={colors.textSecondary}\n            value={justificacion}\n            onChangeText={setJustificacion}\n            maxLength={140}\n          />\n\n          {formErr ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={formErr} /></View> : null}\n          {/*\n            AUDITORÍA DE DISEÑO (D-33): el monedero exige identidad verificada y el aviso solo\n            pintaba texto. El usuario elegía importe, agente y PIN para descubrir al final que no\n            podía seguir, y no había ninguna salida. Aquí está la puerta.\n          */}\n          {kycFalta && (\n            <Tactil\n              onPress={() => router.push('/kyc')}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Verificar mi identidad\"\n              style={{ marginTop: espaciado.e10, alignSelf: 'flex-start' }}\n            >\n              <Text style={[styles.label, { color: colors.primary, textTransform: 'none', letterSpacing: 0 }]}>Verificar mi identidad →</Text>\n            </Tactil>\n          )}\n\n          <View style={{ marginTop: espaciado.e24 }}>\n            <PrimaryButton\n              title={cantidad > 0 ? `Retirar ${fmtXaf(cantidad)}` : 'Retirar'}\n              onPress={() => {\n                if (!valido) {\n                  setFormErr(\n                    cantidad < 100 ? 'El importe mínimo es 100 XAF.'\n                      : cantidad > tope ? 'Supera tu saldo disponible o tu límite de hoy.'\n                      : !agenteId ? 'Elige un agente.'\n                      : 'Escribe el motivo de la retirada (mín. 10 caracteres).',\n                  );\n                  return;\n                }\n                setFormErr(null); setPinErr(null); setNeedSetPin(false); setPinOpen(true);\n              }}\n            />\n          </View>\n        </ScrollView>\n      )}\n\n      <PinSheet\n        visible={pinOpen}\n        title={`Retirar ${fmtXaf(cantidad)}`}\n        subtitle={needSetPin\n          ? 'Primer uso: escribe tu contraseña y elige un PIN de 6 dígitos.'\n          : 'Introduce tu PIN del monedero.'}\n        busy={pinBusy}\n        error={pinErr}\n        needPassword={needSetPin}\n        confirmLabel={needSetPin ? 'Guardar PIN y retirar' : 'Confirmar retirada'}\n        onClose={() => setPinOpen(false)}\n        onConfirm={(pin, pwd) => void confirmar(pin, pwd)}\n      />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  header: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  headerTitle: { fontSize: tipografia.subtitle, fontWeight: '900' },\n  label: { fontSize: tipografia.body, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.4 },\n  amountBox: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderRadius: radios.lg, borderWidth: 1,\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, marginTop: espaciado.e8,\n  },\n  agentRow: {\n    flexDirection: 'row', alignItems: 'center', borderRadius: radios.lg,\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e12, marginTop: espaciado.e8,\n  },\n  agentIcon: { width: 38, height: 38, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n  input: { borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e11, fontSize: tipografia.body, marginTop: espaciado.e8 },\n  doneWrap: { flex: 1, padding: espaciado.e20, justifyContent: 'center', gap: espaciado.e18 },\n  otpCard: { borderRadius: 20, borderWidth: 1, padding: espaciado.e22 },\n});\n","/**\n * MyTicketsScreen — Mis tickets (Ciudad a Ciudad).\n * Tickets donde soy COMPRADOR (buyer) o VIAJERO (teléfono del perfil).\n * Cada tarjeta expande el QR del ticket. Ruta: /my-tickets\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { FlatList, Linking, StyleSheet, Text, View, Pressable } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useRouter } from 'expo-router';\nimport { ArrowLeft, Ticket, ChevronDown, ChevronUp } from 'lucide-react-native';\nimport { alpha, EmptyState, espaciado, GhostButton, InlineError, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { useSession } from '../state/session';\nimport { intercityApi, IcTicket } from '../api/intercity';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst stateLabel = (s: string) =>\n  s === 'confirmed' ? 'Confirmado' : s === 'proposed' ? 'Tarifa propuesta' : s === 'cancelled' ? 'Cancelado' : s;\n\nexport default function MyTicketsScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const { phone } = useSession();\n\n  const [tickets, setTickets] = useState<IcTicket[]>([]);\n  const [openId, setOpenId] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    setLoading(true); setError(null);\n    try {\n      setTickets(await intercityApi.myBookings());\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Error de red');\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => { load(); }, [load]);\n\n  const shareWhatsApp = (t: IcTicket) => {\n    const msg = `🧾 Ticket EG Route Plan\\n${t.trip?.route?.originDistrict ?? ''} → ${t.trip?.route?.destinationDistrict ?? ''}\\n${t.trip ? new Date(t.trip.departureTime).toLocaleString('es') : ''}\\n${t.seatCount} asiento(s) · ${Number(t.totalPrice).toLocaleString('es')} XAF\\nCódigo: ${t.shortCode ?? t.ticketQrCode}`;\n    Linking.openURL(`https://wa.me/${t.passenger?.phone?.replace(/\\D/g, '')}?text=${encodeURIComponent(msg)}`).catch(() => {});\n  };\n\n  const s = styles(colors);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.background }}>\n      <View style={s.topBar}>\n        <Pressable onPress={() => router.back()} hitSlop={12}>\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={s.title}>Mis tickets</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      {/*\n        LISTA VIRTUALIZADA (auditoría de diseño, D-04/D-21): antes era un ScrollView con .map(),\n        que pinta y mantiene TODOS los tickets en memoria. Con muchos viajes reservados, la pantalla\n        se atasca justo cuando el usuario busca su código para enseñárselo al conductor.\n      */}\n      <FlatList\n        data={tickets}\n        keyExtractor={(t) => t.id}\n        contentContainerStyle={[s.content, { paddingTop: insets.top + 20, paddingBottom: insets.bottom + 20 }]}\n        initialNumToRender={10}\n        windowSize={7}\n        removeClippedSubviews\n        ListHeaderComponent={\n          /*\n          Un `View` con el hueco del contenedor, y no un fragmento: el `gap` de\n          `contentContainerStyle` separa CELDAS, y `ListHeaderComponent` es UNA celda. Con un\n          fragmento, todo lo de aquí dentro quedaba pegado (era gap: espaciado.e12 antes de virtualizar).\n          */\n          <View style={{ gap: espaciado.e12 }}>\n            {error ? <View style={{ marginTop: espaciado.e10 }}><InlineError mensaje={error} /></View> : null}\n            {loading && <Text style={{ color: colors.textSecondary, fontWeight: '700', textAlign: 'center' }}>Cargando…</Text>}\n          </View>\n        }\n        ListEmptyComponent={\n          !loading ? (\n            <EmptyState\n              icono={<Ticket size={40} color={colors.textSecondary} />}\n              titulo=\"Todavía no tienes tickets\"\n              texto=\"Cuando reserves un asiento en Ciudad a Ciudad, tu ticket aparecerá aquí con su código para enseñárselo al conductor.\"\n              accionLabel=\"Buscar viajes\"\n              onAccion={() => router.push('/intercity' as any)}\n            />\n          ) : null\n        }\n        renderItem={({ item: t }) => {\n          const open = openId === t.id;\n          const cancelled = t.status === 'cancelled';\n          const isBuyer = t.buyerPhone && phone && t.buyerPhone === phone;\n          return (\n            <Pressable onPress={() => setOpenId(open ? null : t.id)} style={[s.card, { borderColor: cancelled ? colors.border : colors.primary, opacity: cancelled ? 0.6 : 1 }]}>\n              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15 }}>\n                  {t.trip?.route?.originDistrict ?? ''} → {t.trip?.route?.destinationDistrict ?? ''}\n                </Text>\n                {open ? <ChevronUp size={18} color={colors.primary} /> : <ChevronDown size={18} color={colors.primary} />}\n              </View>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                {t.trip ? new Date(t.trip.departureTime).toLocaleString('es') : ''} · {t.seatCount} asiento(s) · {Number(t.totalPrice).toLocaleString('es')} XAF\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                {stateLabel(t.status)}\n                {t.payOn === 'destination' ? ' · 💵 paga al llegar al destino' : t.paymentStatus === 'paid' ? ' · ✅ pagado' : ' · 💵 al abordar'}\n                {t.fareStatus === 'proposed' ? ' · 💬 tarifa propuesta' : ''}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>\n                🎫 Viajero: {t.passenger?.firstName} {t.passenger?.lastName} · {isBuyer ? 'comprado por ti' : `comprado por ${t.buyerName || 'otra persona'}`}\n              </Text>\n\n              {open && (\n                <View style={[s.qrBox, { borderColor: colors.primary }]}>\n                  <Ticket size={22} color={colors.primary} />\n                  <Text style={{ color: colors.textPrimary, fontSize: 24, fontWeight: '900', letterSpacing: 2 }}>{t.shortCode ?? t.ticketQrCode}</Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', textAlign: 'center' }}>\n                    {t.ticketQrCode} · muestra este código al conductor{t.payOn === 'destination' ? '; el viajero paga al llegar al destino' : ''}\n                  </Text>\n                  {t.passenger?.phone && (\n                    <Pressable onPress={() => shareWhatsApp(t)} style={[s.waBtn, { backgroundColor: brand.whatsapp }]}>\n                      <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.caption }}>Enviar por WhatsApp</Text>\n                    </Pressable>\n                  )}\n                </View>\n              )}\n            </Pressable>\n          );\n        }}\n      />\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e6 },\n    title: { fontSize: 18, fontWeight: '800', color: c.textPrimary },\n    content: { padding: espaciado.e20, gap: espaciado.e12 },\n    card: { borderRadius: radios.lg, borderWidth: 1.5, padding: espaciado.e14, gap: espaciado.e5 },\n    qrBox: { alignItems: 'center', gap: espaciado.e6, borderWidth: 2, borderStyle: 'dashed', borderRadius: 14, padding: espaciado.e16, marginTop: espaciado.e8 },\n    waBtn: { borderRadius: 10, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, marginTop: espaciado.e4 },\n  });\n","/**\r\n * ProfileScreen — PERFIL estilo Xiaohongshu (EG Route Plan).\r\n *\r\n * Estructura (rediseño aprobado 2026-09-09 + feedback):\r\n *  · Portada full-width edge-to-edge que CRECE hasta incluir el título\r\n *    \"Life Book\"; dentro de la portada (bajo las stats): bio breve, enlaces y\r\n *    correos del usuario (chips), y al pie el título Life Book.\r\n *  · ✎ Editar perfil (arriba-izquierda) → /edit-profile; ☰ debajo transparente.\r\n *  · Identidad dentro de la portada: avatar tocable (→ modal cambiar foto),\r\n *    nombre + píldora PROFESIÓN tocable (→ selector del catálogo Work), EG\r\n *    Route Plan ID + QR, ubicación tocable (→ selector internacional).\r\n *  · Stats: Seguidores · Seguidos · Me gusta · ★ Valoración (al final).\r\n *  · Sin barra inferior de perfil; solo dock global. Ajustes y modo conductor\r\n *    viven en el drawer ☰. Sin teléfonos en la UI.\r\n */\r\n\r\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\r\nimport {\r\n  ActivityIndicator, Alert, Image, Linking, Modal, Pressable,\r\n  ScrollView, StyleSheet, Text, View, useWindowDimensions,\r\n} from 'react-native';\r\nimport { useFocusEffect, useRouter } from 'expo-router';\r\n// Parte 31: expo-image (caché memoria+disco) para la portada — evita el\r\n// destello blanco que hacía <ImageBackground> al volver a la pestaña.\r\nimport { Image as ExpoImage } from 'expo-image';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport QRCode from 'react-native-qrcode-svg';\r\nimport { pickImageFromCamera, pickImageFromLibrary } from '../core/pickImage';\r\nimport {\r\n  BedDouble, Briefcase, CarTaxiFront, ChevronRight, Globe, Heart, ImageIcon, Link2, Mail,\r\n  MapPin, Menu, Pencil, Phone, Plus, QrCode, Settings, ShieldCheck, Sparkles, Star, Store, UserPlus, Users,\r\n  UtensilsCrossed, X,\r\n} from 'lucide-react-native';\r\nimport { alpha, espaciado, FormField, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { AuthGate } from '../core/AuthGate';\r\nimport { authApi, type MeProfile } from '../api/auth';\r\nimport { hotelApi } from '../api/hotel';\r\nimport { commerceApi } from '../api/commerce';\r\nimport { foodApi } from '../api/food';\r\nimport { workApi } from '../api/work';\r\nimport { taxiApi } from '../api/taxi';\r\nimport { useMisNegocios, type VerticalNegocio } from '../core/useMisNegocios';\r\nimport { absUrl } from '../api/config';\r\nimport EditProfileModal from '../components/EditProfileModal';\r\nimport ServicesDrawer from '../components/ServicesDrawer';\r\nimport FloatingFooter, { DOCK_BODY_H, type FooterTab } from '../components/FloatingFooter';\r\nimport { useAppDock } from '../core/useAppDock';\r\nimport { lifebookApi, toPostCard, type LbPostBase, type LbProfile } from '../api/lifebook';\r\nimport { PostCard } from '../components/lifebook/PostCard';\r\nimport EmergencyModal from '../components/EmergencyModal';\r\nimport StatusRingAvatar from '../components/status/StatusRingAvatar';\r\nimport StatusChip from '../components/status/StatusChip';\r\nimport StatusEditorModal from '../components/status/StatusEditorModal';\r\nimport StatusDetailModal from '../components/status/StatusDetailModal';\r\nimport { useStatusStore } from '../state/statusStore';\r\nimport { COUNTRIES, GQ_CITIES } from '../constants/countries';\r\nimport { PROFESSIONS } from '../constants/professions';\r\nimport { ir as irSeguro } from '../constants/rutas';\r\nimport { brand } from '@egrouteplan/ui-kit';\r\n\r\n/** Portada por defecto: atardecer de la playa de Ureka (foto libre CC BY-SA 4.0). */\r\nconst COVER_BG = 'https://hk.egrouteplan.com/wallet/assets/profile-bg-ureka.jpg';\r\n\r\ntype LB_TAB = 'todo' | 'fotos' | 'ventas' | 'gustos';\r\n\r\nexport default function ProfileScreen() {\r\n  return (\r\n    <AuthGate>\r\n      <ProfileContent />\r\n    </AuthGate>\r\n  );\r\n}\r\n\r\n/**\r\n * Parte 31: caché en memoria del perfil (ver `ProfileContent`). Vive a nivel de\r\n * módulo para sobrevivir al desmontaje de la pantalla al cambiar de pestaña.\r\n */\r\nlet profileCache: MeProfile | null = null;\r\n\r\nfunction ProfileContent() {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const { height: winH, width: winW } = useWindowDimensions();\r\n  /**\r\n   * Parte 31 (navegación fluida): el perfil se guarda en una caché en memoria.\r\n   * Antes, cada entrada a la pestaña Perfil montaba la pantalla de cero y\r\n   * mostraba un spinner a pantalla completa (parpadeo). Ahora se pinta al\r\n   * instante con lo último conocido y se refresca en segundo plano.\r\n   */\r\n  const [profile, setProfileState] = useState<MeProfile | null>(profileCache);\r\n  const setProfile = useCallback((p: MeProfile | null) => {\r\n    profileCache = p;\r\n    setProfileState(p);\r\n  }, []);\r\n  const [loading, setLoading] = useState(!profileCache);\r\n  const [activeTrip, setActiveTrip] = useState<Record<string, any> | null>(null);\r\n  const [activeLoading, setActiveLoading] = useState(true);\r\n  const [drawerOpen, setDrawerOpen] = useState(false);\r\n  const [editOpen, setEditOpen] = useState(false);\r\n  const [photoOpen, setPhotoOpen] = useState(false);\r\n  const [emergencyOpen, setEmergencyOpen] = useState(false);\r\n  const [qrOpen, setQrOpen] = useState(false);\r\n  const [locOpen, setLocOpen] = useState(false);\r\n  const [profOpen, setProfOpen] = useState(false);\r\n  const [statusOpen, setStatusOpen] = useState(false);\r\n  const [statusDetailOpen, setStatusDetailOpen] = useState(false);\r\n  const { status: myStatus, loading: statusLoading, refresh: refreshStatus, localExpire } = useStatusStore();\r\n  const [emptyStat, setEmptyStat] = useState<string | null>(null);\r\n  const [lbTab, setLbTab] = useState<LB_TAB>('todo');\r\n  const scrollRef = useRef<ScrollView>(null);\r\n  // Datos REALES de Life Book (perfil unificado: estilo propio + datos del backend).\r\n  const [lbProfile, setLbProfile] = useState<LbProfile | null>(null);\r\n  const [lbPosts, setLbPosts] = useState<LbPostBase[]>([]);\r\n  const [lbLoadingPosts, setLbLoadingPosts] = useState(false);\r\n\r\n  const refresh = useCallback(() => authApi.me().then(setProfile).catch(() => {}), [setProfile]);\r\n\r\n  useEffect(() => { refresh().finally(() => setLoading(false)); }, [refresh]);\r\n\r\n  /**\r\n   * ══ TUS NEGOCIOS ══ el acceso PROPIO del comerciante.\r\n   *\r\n   * La detección vive en `core/useMisNegocios` porque sale en DOS sitios: aquí y en el menú\r\n   * lateral (☰). Si cada pantalla la hiciera por su cuenta, en dos semanas una conocería el\r\n   * restaurante y la otra no. El estándar completo: `ESTANDAR-ENTORNOS-DE-CONTROL.md`.\r\n   */\r\n  const { negocios } = useMisNegocios(profile?.id);\r\n\r\n  // Perfil público real (estadísticas, verificación) + publicaciones por pestaña.\r\n  useEffect(() => {\r\n    const id = profile?.id;\r\n    if (!id) return;\r\n    lifebookApi.profile(id).then(setLbProfile).catch(() => setLbProfile(null));\r\n  }, [profile?.id]);\r\n\r\n  useEffect(() => {\r\n    const id = profile?.id;\r\n    if (!id) return;\r\n    // Parte 16: la pestaña «Guardados» son MIS publicaciones guardadas.\r\n    if (lbTab === 'gustos') {\r\n      setLbLoadingPosts(true);\r\n      lifebookApi.mySaves({ limit: 30 })\r\n        .then((page) => setLbPosts(page.posts ?? []))\r\n        .catch(() => setLbPosts([]))\r\n        .finally(() => setLbLoadingPosts(false));\r\n      return;\r\n    }\r\n    const type = lbTab === 'fotos' ? 'note' : lbTab === 'ventas' ? 'sale' : undefined;\r\n    setLbLoadingPosts(true);\r\n    lifebookApi.userPosts(id, { type, limit: 30 })\r\n      .then((page) => setLbPosts(page.posts ?? []))\r\n      .catch(() => setLbPosts([]))\r\n      .finally(() => setLbLoadingPosts(false));\r\n  }, [profile?.id, lbTab]);\r\n\r\n  // Viaje en curso (persistencia del dueño): tarjeta para volver a /taxi.\r\n  useFocusEffect(\r\n    useCallback(() => {\r\n      let alive = true;\r\n      setActiveLoading(true);\r\n      taxiApi.activeTrip()\r\n        .then((t) => { if (alive) setActiveTrip(t); })\r\n        .catch(() => { if (alive) setActiveTrip(null); })\r\n        .finally(() => { if (alive) setActiveLoading(false); });\r\n      return () => { alive = false; };\r\n    }, []),\r\n  );\r\n\r\n  const dockNav = useAppDock('perfil');\r\n  const handleNavigate = useCallback((next: FooterTab) => {\r\n    // Perfil: si ya estamos, subimos arriba; el resto, navegación ÚNICA del dock.\r\n    if (next === 'perfil') { scrollRef.current?.scrollTo({ y: 0, animated: true }); return; }\r\n    dockNav(next);\r\n  }, [dockNav]);\r\n\r\n  if (loading) {\r\n    return (\r\n      <View style={[styles.center, { backgroundColor: colors.background }]}>\r\n        <ActivityIndicator color={colors.primary} />\r\n      </View>\r\n    );\r\n  }\r\n\r\n  const initial = (profile?.fullName ?? 'U').trim().charAt(0).toUpperCase() || 'U';\r\n  const displayName = profile?.fullName ?? (profile?.role === 'DRIVER' ? 'Conductor' : 'Usuario');\r\n  const roleLabel = profile?.role === 'DRIVER' ? 'Conductor' : profile?.role === 'ADMIN' ? 'Administrador' : 'Pasajero';\r\n  const avatarSrc = profile?.avatarUrl ? absUrl(profile.avatarUrl) : null;\r\n  const coverSrc = profile?.coverUrl ? absUrl(profile.coverUrl) : COVER_BG;\r\n  const egId = profile ? `EG-${(profile.id.replace(/-/g, '').slice(0, 8)).toUpperCase()}` : 'EG-……';\r\n  // Ubicación: país · ciudad (default GQ)\r\n  const locLabel = [profile?.country ?? 'Guinea Ecuatorial', profile?.city].filter(Boolean).join(' · ');\r\n  // Profesión mostrada = profile.profession si existe; si el rol es DRIVER y no\r\n  // hay profesión, sugerimos 'Conductor' en la píldora pero se guarda aparte.\r\n  const professionLabel = profile?.profession || (profile?.role === 'DRIVER' ? 'Conductor' : roleLabel);\r\n\r\n  const showEmptyStat = (which: string) => {\r\n    if (which === 'seguidores') setEmptyStat('Aún no tienes seguidores · Cuando la comunidad crezca, lo verás aquí.');\r\n    else if (which === 'seguidos') setEmptyStat('Aún no sigues a nadie · Explora perfiles para empezar.');\r\n    else setEmptyStat('Aún no tienes me gusta · Los me gusta de tus publicaciones aparecerán aquí.');\r\n  };\r\n\r\n  const bottomPad = DOCK_BODY_H + insets.bottom + 24;\r\n  // Rejilla 2 columnas (mismo ritmo que el feed de Life Book).\r\n  const gridCellW = (winW - 32 - 10) / 2;\r\n  const coverH = Math.round(Math.min(Math.max(winH * 0.62, 420), 640));\r\n  const coverStyle = [styles.cover, { height: coverH }];\r\n\r\n  return (\r\n    <View style={[styles.root, { backgroundColor: colors.background }]}>\r\n      <ScrollView\r\n        ref={scrollRef}\r\n        style={styles.scroll}\r\n        contentContainerStyle={{ paddingBottom: bottomPad }}\r\n        showsVerticalScrollIndicator={false}\r\n      >\r\n        {/* ============ PORTADA edge-to-edge, crece hasta el título Life Book ============ */}\r\n        <View style={coverStyle}>\r\n          <ExpoImage\r\n            source={coverSrc}\r\n            style={StyleSheet.absoluteFill}\r\n            contentFit=\"cover\"\r\n            cachePolicy=\"memory-disk\"\r\n            transition={0}\r\n          />\r\n          <View style={styles.coverScrim} pointerEvents=\"none\" />\r\n          <View style={styles.coverScrimBottom} pointerEvents=\"none\" />\r\n\r\n          {/* Acciones IZQUIERDA: ✎ (arriba) + ☰ (debajo transparente) */}\r\n          <View style={[styles.coverActions, { top: insets.top + 8 }]}>\r\n            <Pressable\r\n              onPress={() => irSeguro.libre('/edit-profile')}\r\n              accessibilityRole=\"button\"\r\n              accessibilityLabel=\"Editar perfil\"\r\n              style={({ pressed }) => [styles.editCapsule, { opacity: pressed ? 0.8 : 1 }]}\r\n            >\r\n              <Pencil size={14} color={brand.white} />\r\n              <Text style={styles.editCapsuleTxt}>Editar perfil</Text>\r\n            </Pressable>\r\n            <Pressable\r\n              onPress={() => setDrawerOpen(true)}\r\n              accessibilityRole=\"button\"\r\n              accessibilityLabel=\"Menú de servicios\"\r\n              style={({ pressed }) => [styles.menuGhostBtn, { opacity: pressed ? 0.6 : 1 }]}\r\n            >\r\n              <Menu size={20} color={brand.white} />\r\n            </Pressable>\r\n          </View>\r\n\r\n          {/* Identidad dentro de la portada */}\r\n          <View style={[styles.identityBlock, { paddingTop: insets.top + 84 }]}>\r\n            <View style={styles.identityTopRow}>\r\n              <StatusRingAvatar\r\n                avatarUrl={profile?.avatarUrl ?? null}\r\n                name={displayName}\r\n                status={myStatus}\r\n                size={88}\r\n                ringWidth={4}\r\n                onPress={() => setPhotoOpen(true)}\r\n              />\r\n              <View style={{ flex: 1 }}>\r\n                <View style={styles.nameRow}>\r\n                  <Text\r\n                    style={[\r\n                      styles.name,\r\n                      profile?.nameColor\r\n                        ? { color: profile.nameColor, textShadowColor: 'transparent' }\r\n                        : null,\r\n                    ]}\r\n                    numberOfLines={1}\r\n                  >\r\n                    {displayName}\r\n                  </Text>\r\n                </View>\r\n                {/* Profesión: se muestra en la fila de correos (primer chip) */}\r\n                <Pressable onPress={() => setQrOpen(true)} accessibilityRole=\"button\" accessibilityLabel=\"Ver mi código QR\" style={styles.egIdRow}>\r\n                  <Text style={styles.egId} numberOfLines={1}>{egId}</Text>\r\n                  <View style={styles.qrMini}><QrCode size={14} color={brand.white} /></View>\r\n                </Pressable>\r\n                {/* Ubicación tocable → selector internacional */}\r\n                <Pressable onPress={() => setLocOpen(true)} accessibilityRole=\"button\" accessibilityLabel=\"Cambiar ubicación\" style={styles.locRow}>\r\n                  <MapPin size={12} color=\"rgba(255,255,255,0.92)\" />\r\n                  <Text style={styles.locTxt} numberOfLines={1}>{locLabel}</Text>\r\n                  <ChevronRight size={12} color=\"rgba(255,255,255,0.85)\" />\r\n                </Pressable>\r\n                {/* Estado 24h v3: chip con tiempo si hay estado → Detalle;\r\n                    si no, botón \"+ Agregar estado 24h\" → Editor. */}\r\n                {myStatus && !statusLoading ? (\r\n                  <StatusChip\r\n                    status={myStatus}\r\n                    foreground={brand.white}\r\n                    onPress={() => setStatusDetailOpen(true)}\r\n                    onExpired={() => refreshStatus()}\r\n                  />\r\n                ) : (\r\n                  <Pressable\r\n                    onPress={() => setStatusOpen(true)}\r\n                    accessibilityRole=\"button\"\r\n                    accessibilityLabel=\"Agregar estado 24h\"\r\n                    style={({ pressed }) => [styles.addStatusBtn, { borderColor: 'rgba(255,255,255,0.65)', opacity: pressed ? 0.75 : 1 }]}\r\n                  >\r\n                    <Plus size={11} color=\"rgba(255,255,255,0.95)\" />\r\n                    <Text style={styles.addStatusTxt}>Agregar estado 24h</Text>\r\n                  </Pressable>\r\n                )}\r\n              </View>\r\n            </View>\r\n\r\n            {/* Stats REALES (Life Book): Seguidores · Seguidos · Me gusta · ★ */}\r\n            <View style={styles.statsRow}>\r\n              <View style={styles.statItem}><Text style={styles.statValue}>{lbProfile?.stats.followers ?? 0}</Text><Text style={styles.statLabel}>Seguidores</Text></View>\r\n              <View style={styles.statItem}><Text style={styles.statValue}>{lbProfile?.stats.following ?? 0}</Text><Text style={styles.statLabel}>Seguidos</Text></View>\r\n              <View style={styles.statItem}><Text style={styles.statValue}>{lbProfile?.stats.likes ?? 0}</Text><Text style={styles.statLabel}>Me gusta</Text></View>\r\n              <View style={styles.statItem}>\r\n                <View style={styles.ratingValueRow}><Star size={14} color={brand.warning} fill={brand.warning} /><Text style={styles.statValue}>{(profile?.ratingAvg ?? 5).toFixed(1)}</Text></View>\r\n                <Text style={styles.statLabel}>Valoración</Text>\r\n              </View>\r\n            </View>\r\n\r\n            {/* Bio breve dentro de la portada */}\r\n            {profile?.bio ? (\r\n              <Text style={styles.bioTxt} numberOfLines={3}>{profile.bio}</Text>\r\n            ) : null}\r\n\r\n            {/* ENLACES Y CORREOS dentro de la portada (se editan en /edit-profile).\r\n                La OCUPACIÓN va como PRIMER chip, delante del correo. */}\r\n            <View style={styles.linksArea}>\r\n              {/* Ocupación (profesión) — delante del correo */}\r\n              <Pressable\r\n                onPress={() => setProfOpen(true)}\r\n                accessibilityRole=\"button\"\r\n                accessibilityLabel=\"Cambiar profesión\"\r\n                style={({ pressed }) => [styles.linkChip, styles.occupChip, { opacity: pressed ? 0.75 : 1 }]}\r\n              >\r\n                <Briefcase size={12} color={brand.warning} />\r\n                <Text style={styles.linkChipTxt} numberOfLines={1}>{professionLabel}</Text>\r\n              </Pressable>\r\n              {(profile?.links?.length ?? 0) > 0 ? (\r\n                profile!.links!.map((l, i) => {\r\n                  const Icon = l.kind === 'email' ? Mail : l.kind === 'phone' ? Phone : l.kind === 'social' ? Globe : Link2;\r\n                  const target = l.kind === 'email' ? `mailto:${l.value}` : l.kind === 'phone' ? `tel:${l.value}` : l.value;\r\n                  return (\r\n                    <Pressable\r\n                      key={`${l.label}-${i}`}\r\n                      onPress={() => Linking.openURL(target).catch(() => {})}\r\n                      accessibilityRole=\"link\"\r\n                      style={({ pressed }) => [styles.linkChip, { opacity: pressed ? 0.75 : 1 }]}\r\n                    >\r\n                      <Icon size={12} color={brand.white} />\r\n                      <Text style={styles.linkChipTxt} numberOfLines={1}>{l.label || l.value}</Text>\r\n                    </Pressable>\r\n                  );\r\n                })\r\n              ) : null}\r\n            </View>\r\n\r\n            {/* (Sin título \"Life Book\": innecesario dentro del propio módulo) */}\r\n          </View>\r\n        </View>\r\n\r\n        {/* ============ CONTENIDO (con márgenes) ============ */}\r\n        <View style={styles.body}>\r\n          {/* Viaje en curso (solo pasajero) */}\r\n          {!activeLoading && activeTrip && profile?.role !== 'DRIVER' && (\r\n            <Pressable\r\n              onPress={() => router.push('/taxi' as any)}\r\n              accessibilityRole=\"button\"\r\n              accessibilityLabel=\"Volver a mi viaje en curso\"\r\n              style={({ pressed }) => [tripCard.card, { backgroundColor: colors.card, borderColor: brand.secondary, opacity: pressed ? 0.7 : 1 }]}\r\n            >\r\n              <View style={[tripCard.iconBox, { backgroundColor: alpha(brand.secondary, 0.12) }]}>\r\n                <CarTaxiFront size={20} color={brand.secondary} />\r\n              </View>\r\n              <View style={{ flex: 1 }}>\r\n                <Text style={{ color: brand.secondary, fontSize: 10.5, fontWeight: '900', letterSpacing: 0.3 }}>{activeTripLabel(String(activeTrip.status))}</Text>\r\n                <Text style={[tripCard.title, { color: colors.textPrimary }]}>Mi viaje en curso</Text>\r\n                <Text style={[tripCard.sub, { color: colors.textSecondary }]} numberOfLines={1}>\r\n                  {String(activeTrip.pickup_address ?? 'Punto de recogida')} → {String(activeTrip.dropoff_address ?? 'Destino')}\r\n                </Text>\r\n              </View>\r\n              <ChevronRight size={18} color={colors.textSecondary} />\r\n            </Pressable>\r\n          )}\r\n\r\n          {/*\r\n            ══ TUS NEGOCIOS ══\r\n            Un negocio por fila, cada uno con su entorno de control. Aparece SIEMPRE que la\r\n            cuenta tenga negocio —no solo con el perfil vacío— y va en la cuenta, no dentro de\r\n            una pantalla de consumidor. Detalle del estándar: ESTANDAR-ENTORNOS-DE-CONTROL.md\r\n          */}\r\n          {negocios && negocios.length ? (\r\n            <View style={{ marginBottom: espaciado.e16 }}>\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '900', letterSpacing: 0.5, marginBottom: espaciado.e7, marginLeft: espaciado.e2 }}>\r\n                {negocios.length > 1 ? `TUS NEGOCIOS (${negocios.length})` : 'TU NEGOCIO'}\r\n              </Text>\r\n\r\n              {negocios.map((n) => (\r\n                <FilaNegocio\r\n                  key={n.clave}\r\n                  icono={iconoDeVertical(n.vertical, colors.primary)}\r\n                  titulo={n.titulo}\r\n                  detalle={n.detalle}\r\n                  nota={n.nota}\r\n                  onPress={() => irSeguro.libre(String(n.ruta ?? ''))}\r\n                />\r\n              ))}\r\n\r\n              <FilaNegocio\r\n                icono={<Plus size={18} color={colors.primary} />}\r\n                titulo=\"Abrir otro negocio\"\r\n                detalle=\"Publica un producto, comida, servicio o alquiler en Life Book\"\r\n                onPress={() => irSeguro.libre('/lifebook-sell')}\r\n              />\r\n            </View>\r\n          ) : null}\r\n\r\n          {/* MODERACIÓN (solo ADMIN). Primera pantalla de administración de la app: hasta ahora los\r\n              moderadores trabajaban directamente contra la base de datos. Va aquí, junto a «Tus\r\n              negocios», porque es una herramienta de trabajo y no una opción de usuario; y solo se\r\n              pinta si el rol es ADMIN (`profile.role`, el mismo dato que usa el saludo de arriba).\r\n              Ojo: la pintarla solo aquí NO es la seguridad — la comprueba el servidor con\r\n              `@Roles('ADMIN')`; esto es solo no enseñar una puerta que no se puede abrir. */}\r\n          {profile?.role === 'ADMIN' ? (\r\n            <View style={{ marginBottom: espaciado.e16 }}>\r\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, fontWeight: '900', letterSpacing: 0.5, marginBottom: espaciado.e7, marginLeft: espaciado.e2 }}>\r\n                MODERACIÓN\r\n              </Text>\r\n              <FilaNegocio\r\n                icono={<ShieldCheck size={18} color={colors.primary} />}\r\n                titulo=\"Documentación de vendedores\"\r\n                detalle=\"Revisa las facturas y certificados que suben los vendedores del Mercado\"\r\n                onPress={() => irSeguro.libre('/ecomerse-docs')}\r\n              />\r\n            </View>\r\n          ) : null}\r\n\r\n          {/* Pestañas de Life Book (fuera de la portada) */}\r\n          <View style={[styles.tabsRow, { borderBottomColor: colors.border }]}>\r\n            {([['todo', 'Todo'], ['fotos', 'Fotos'], ['ventas', 'Ventas'], ['gustos', 'Guardados']] as Array<[LB_TAB, string]>).map(([k, label]) => {\r\n              const active = lbTab === k;\r\n              return (\r\n                <Pressable key={k} onPress={() => setLbTab(k)} accessibilityRole=\"tab\" accessibilityState={{ selected: active }} style={styles.tabItem}>\r\n                  <Text style={[styles.tabTxt, { color: active ? colors.textPrimary : colors.textSecondary, fontWeight: active ? '900' : '600' }]}>{label}</Text>\r\n                  {active && <View style={[styles.tabUnderline, { backgroundColor: colors.primary }]} />}\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </View>\r\n\r\n          {/* Rejilla REAL de publicaciones (perfil unificado) */}\r\n          {lbLoadingPosts ? (\r\n            <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e24 }} />\r\n          ) : lbPosts.length > 0 ? (\r\n            <View style={styles.lbGrid}>\r\n              {lbPosts.map((p) => (\r\n                <PostCard\r\n                  key={p.id}\r\n                  post={toPostCard(p)}\r\n                  width={gridCellW}\r\n                  onPress={(id) => irSeguro.libre('/lifebook-post/[id]', { id })}\r\n                />\r\n              ))}\r\n            </View>\r\n          ) : (\r\n            <View style={[styles.lbEmpty, { backgroundColor: colors.card, borderColor: colors.border }]}>\r\n              <View style={[styles.lbEmptyIcon, { backgroundColor: alpha(colors.primary, 0.08) }]}><ImageIcon size={26} color={colors.primary} /></View>\r\n              <Text style={[styles.lbEmptyTitle, { color: colors.textPrimary }]}>\r\n                {lbTab === 'gustos' ? 'Aquí verás lo que guardes' : lbTab === 'ventas' ? 'Aún no tienes ventas' : 'Aún no has publicado nada'}\r\n              </Text>\r\n              <Text style={[styles.lbEmptyBody, { color: colors.textSecondary }]}>\r\n                {lbTab === 'gustos'\r\n                  ? 'Toca el marcador de cualquier publicación y aparecerá aquí.'\r\n                  : 'Comparte tu día, tus ventas o tu trabajo. Tu historia empieza aquí.'}\r\n              </Text>\r\n              <View style={styles.lbActions}>\r\n                <ChipBtn label=\"Publicar\" onPress={() => irSeguro.libre('/lifebook-compose')} />\r\n                {/* Parte 33: «Vender» ya no es un placeholder muerto — abre el\r\n                    publicador de comercio (tienda + producto o servicio). */}\r\n                <ChipBtn label=\"Vender\" onPress={() => irSeguro.libre('/lifebook-sell')} />\r\n                {/* Aquí estaba el chip «Mi tienda», y se ha quitado: solo se pintaba en este\r\n                    estado vacío (al comerciante con publicaciones le desaparecía) y ahora el\r\n                    acceso al comercio es el bloque «Tu comercio» de arriba, que está siempre. */}\r\n              </View>\r\n            </View>\r\n          )}\r\n\r\n          <Text style={[styles.version, { color: colors.textSecondary }]}>EG Route Plan · v1.0.0</Text>\r\n        </View>\r\n      </ScrollView>\r\n\r\n      {/* Dock global */}\r\n      <FloatingFooter active=\"perfil\" onNavigate={handleNavigate} onEmergency={() => setEmergencyOpen(true)} showUnreadBadge />\r\n\r\n      {/* Drawer ☰ */}\r\n      <ServicesDrawer\r\n        visible={drawerOpen}\r\n        onClose={() => setDrawerOpen(false)}\r\n        userName={displayName}\r\n        userAvatar={profile?.avatarUrl ?? null}\r\n        roleLabel={roleLabel}\r\n        role={profile?.role}\r\n        cuenta={profile?.id ?? null}\r\n        onEmergency={() => { setDrawerOpen(false); setEmergencyOpen(true); }}\r\n      />\r\n\r\n      {profile && <EditProfileModal visible={editOpen} profile={profile} onClose={() => setEditOpen(false)} onSaved={(p) => { setProfile(p); setEditOpen(false); }} />}\r\n\r\n      {profile && <PhotoModal visible={photoOpen} profile={profile} onClose={() => setPhotoOpen(false)} onSaved={(p) => { setProfile(p); setPhotoOpen(false); }} />}\r\n\r\n      {profile && <QrModal visible={qrOpen} egId={egId} onClose={() => setQrOpen(false)} onShare={() => setQrOpen(false)} />}\r\n\r\n      {/* Editor del ESTADO 24h (v3) */}\r\n      <StatusEditorModal\r\n        visible={statusOpen}\r\n        onClose={() => setStatusOpen(false)}\r\n        onSaved={() => { refreshStatus(); }}\r\n      />\r\n\r\n      {/* Detalle del ESTADO 24h (v3) — mi propio estado */}\r\n      {myStatus && (\r\n        <StatusDetailModal\r\n          visible={statusDetailOpen}\r\n          status={myStatus}\r\n          isMine\r\n          author={profile ? { id: profile.id, fullName: displayName, avatarUrl: profile.avatarUrl ?? null, role: profile.role, nameColor: profile.nameColor ?? '' } : null}\r\n          onClose={() => setStatusDetailOpen(false)}\r\n          onEnded={() => localExpire()}\r\n        />\r\n      )}\r\n\r\n      {/* Selector de ubicación internacional */}\r\n      {profile && (\r\n        <LocationModal\r\n          visible={locOpen}\r\n          profile={profile}\r\n          onClose={() => setLocOpen(false)}\r\n          onSaved={(p) => { setProfile(p); setLocOpen(false); }}\r\n        />\r\n      )}\r\n\r\n      {/* Selector de profesión (catálogo Buscar Work) */}\r\n      {profile && (\r\n        <ProfessionModal\r\n          visible={profOpen}\r\n          profile={profile}\r\n          onClose={() => setProfOpen(false)}\r\n          onSaved={(p) => { setProfile(p); setProfOpen(false); }}\r\n        />\r\n      )}\r\n\r\n      <EmptyStateModal visible={emptyStat !== null} text={emptyStat ?? ''} onClose={() => setEmptyStat(null)} />\r\n      <EmergencyModal visible={emergencyOpen} onClose={() => setEmergencyOpen(false)} />\r\n    </View>\r\n  );\r\n}\r\n\r\n/** Chip de acción genérico. */\r\n/**\r\n * El icono de cada vertical.\r\n *\r\n * No lo devuelve el hook a propósito (`core/useMisNegocios` es un `.ts`, sin JSX): devuelve el\r\n * `vertical` y cada pantalla lo pinta. Así el hook no depende del kit de UI y se puede usar\r\n * desde cualquier sitio.\r\n */\r\nexport function iconoDeVertical(vertical: VerticalNegocio, color: string): React.ReactNode {\r\n  switch (vertical) {\r\n    case 'hotel': return <BedDouble size={18} color={color} />;\r\n    case 'restaurante': return <UtensilsCrossed size={18} color={color} />;\r\n    case 'trabajo': return <Briefcase size={18} color={color} />;\r\n    case 'mercado':\r\n    default: return <Store size={18} color={color} />;\r\n  }\r\n}\r\n\r\n/**\r\n * Fila de «Tus negocios»: icono, título, detalle, aviso opcional y flecha.\r\n * 56 px de alto y `accessibilityLabel` con el texto completo, para que se pueda llegar con\r\n * lector de pantalla sin ambigüedad.\r\n *\r\n * `nota` existe para poder decir la verdad a medias: un negocio cuyo entorno de control ya\r\n * funciona pero que **todavía no está publicado en Life Book** lo dice, en vez de aparentar\r\n * que ya está integrado.\r\n */\r\nfunction FilaNegocio({ icono, titulo, detalle, nota, onPress }: {\r\n  icono: React.ReactNode; titulo: string; detalle: string; nota?: string; onPress: () => void;\r\n}) {\r\n  const { colors } = useTheme();\r\n  return (\r\n    <Pressable\r\n      onPress={onPress}\r\n      accessibilityRole=\"button\"\r\n      accessibilityLabel={`${titulo}. ${detalle}${nota ? ` ${nota}` : ''}`}\r\n      style={({ pressed }) => [{\r\n        flexDirection: 'row' as const, alignItems: 'center' as const, gap: espaciado.e11,\r\n        borderWidth: 1, borderRadius: 14, padding: espaciado.e12, marginBottom: espaciado.e8, minHeight: 56,\r\n        borderColor: colors.border, backgroundColor: colors.card,\r\n        opacity: pressed ? 0.8 : 1,\r\n      }]}\r\n    >\r\n      <View style={{ width: 34, height: 34, borderRadius: 11, alignItems: 'center', justifyContent: 'center', backgroundColor: alpha(colors.primary, 0.12) }}>\r\n        {icono}\r\n      </View>\r\n      <View style={{ flex: 1 }}>\r\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{titulo}</Text>\r\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2, lineHeight: 17 }}>{detalle}</Text>\r\n        {nota ? (\r\n          <Text style={{ color: colors.secondary, fontSize: tipografia.caption, fontWeight: '700', marginTop: espaciado.e3, lineHeight: 16 }}>\r\n            {nota}\r\n          </Text>\r\n        ) : null}\r\n      </View>\r\n      <ChevronRight size={18} color={colors.textSecondary} />\r\n    </Pressable>\r\n  );\r\n}\r\n\r\nfunction ChipBtn({ label, onPress }: { label: string; onPress: () => void }) {\r\n  const { colors } = useTheme();\r\n  return (\r\n    <Pressable onPress={onPress} accessibilityRole=\"button\" style={({ pressed }) => [chipStyles.chip, { backgroundColor: colors.surface, borderColor: colors.border, opacity: pressed ? 0.7 : 1 }]}>\r\n      <Text style={[chipStyles.label, { color: colors.textPrimary }]}>{label}</Text>\r\n    </Pressable>\r\n  );\r\n}\r\n\r\nconst chipStyles = StyleSheet.create({\r\n  chip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\r\n  label: { fontSize: tipografia.caption, fontWeight: '700' },\r\n});\r\n\r\n/** Modal \"Cambiar foto de perfil\": SOLO cambia la foto. Usa core/pickImage\r\n *  (galería/cámara sin base64 inline → con spinner \"Procesando…\"). */\r\nfunction PhotoModal({ visible, profile, onClose, onSaved }: { visible: boolean; profile: MeProfile; onClose: () => void; onSaved: (p: MeProfile) => void }) {\r\n  const { colors } = useTheme();\r\n  const [busy, setBusy] = useState(false);\r\n  const [picking, setPicking] = useState<'library' | 'camera' | null>(null);\r\n  const [error, setError] = useState<string | null>(null);\r\n  const [newPhoto, setNewPhoto] = useState<string | null>(null);\r\n\r\n  useEffect(() => { if (visible) { setNewPhoto(null); setError(null); setPicking(null); } }, [visible]);\r\n  const preview = newPhoto ?? (profile.avatarUrl ? absUrl(profile.avatarUrl) : null);\r\n\r\n  const pick = async (fromCamera: boolean) => {\r\n    setError(null);\r\n    setPicking(fromCamera ? 'camera' : 'library');\r\n    try {\r\n      const img = fromCamera ? await pickImageFromCamera() : await pickImageFromLibrary();\r\n      if (img) setNewPhoto(img.dataUrl);\r\n    } catch (e) {\r\n      setError(e instanceof Error ? e.message : fromCamera ? 'No se pudo abrir la cámara' : 'No se pudo abrir la galería');\r\n    } finally {\r\n      setPicking(null);\r\n    }\r\n  };\r\n\r\n  const save = async () => {\r\n    if (!newPhoto) { onClose(); return; }\r\n    setBusy(true); setError(null);\r\n    try { const next = await authApi.updateMe({ avatar: newPhoto }); onSaved(next); }\r\n    catch (e) { setError(e instanceof Error ? e.message : 'No se pudo guardar la foto'); }\r\n    finally { setBusy(false); }\r\n  };\r\n\r\n  const initial = (profile.fullName ?? 'U').trim().charAt(0).toUpperCase() || 'U';\r\n  const pickDisabled = busy || picking !== null;\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={[styles.sheetRoot, { backgroundColor: colors.overlay }]}>\r\n        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} />\r\n        <View style={[styles.sheetCard, { backgroundColor: colors.card }]}>\r\n          <View style={styles.sheetHeader}>\r\n            <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>Cambiar foto de perfil</Text>\r\n            <Pressable onPress={onClose} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\r\n          </View>\r\n          <View style={{ alignItems: 'center', marginVertical: espaciado.e12 }}>\r\n            <View style={[styles.photoLg, { backgroundColor: alpha(colors.primary, 0.12) }]}>\r\n              {preview ? <Image source={{ uri: preview }} style={styles.photoLgImg} /> : <Text style={[styles.photoLgTxt, { color: colors.primary }]}>{initial}</Text>}\r\n            </View>\r\n          </View>\r\n          <View style={{ flexDirection: 'row', gap: espaciado.e10 }}>\r\n            <Pressable\r\n              onPress={() => pick(true)}\r\n              disabled={pickDisabled}\r\n              accessibilityRole=\"button\"\r\n              accessibilityLabel=\"Tomar foto con la cámara\"\r\n              style={[styles.pickBtn, { backgroundColor: colors.surface, borderColor: colors.border, opacity: busy || (picking !== null && picking !== 'camera') ? 0.45 : 1 }]}\r\n            >\r\n              {picking === 'camera'\r\n                ? <View style={styles.pickBusy}><ActivityIndicator color={colors.primary} size=\"small\" /><Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Procesando…</Text></View>\r\n                : <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>📷 Cámara</Text>}\r\n            </Pressable>\r\n            <Pressable\r\n              onPress={() => pick(false)}\r\n              disabled={pickDisabled}\r\n              accessibilityRole=\"button\"\r\n              accessibilityLabel=\"Elegir desde la galería\"\r\n              style={[styles.pickBtn, { backgroundColor: colors.surface, borderColor: colors.border, opacity: busy || (picking !== null && picking !== 'library') ? 0.45 : 1 }]}\r\n            >\r\n              {picking === 'library'\r\n                ? <View style={styles.pickBusy}><ActivityIndicator color={colors.primary} size=\"small\" /><Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Procesando…</Text></View>\r\n                : <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>🖼️ Galería</Text>}\r\n            </Pressable>\r\n          </View>\r\n          {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700', textAlign: 'center' }}>{error}</Text> : null}\r\n          <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e6 }}>\r\n            <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={onClose} disabled={busy} /></View>\r\n            <View style={{ flex: 1.4 }}><PrimaryButton title={busy ? 'Guardando…' : 'Guardar foto'} onPress={save} loading={busy} disabled={!newPhoto} /></View>\r\n          </View>\r\n        </View>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Modal QR del EG Route Plan ID. */\r\nfunction QrModal({ visible, egId, onClose }: { visible: boolean; egId: string; onClose: () => void; onShare: () => void }) {\r\n  const { colors } = useTheme();\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={[styles.backdrop, { backgroundColor: colors.overlay, alignItems: 'center', justifyContent: 'center' }]}>\r\n        <View style={[styles.qrCard, { backgroundColor: colors.card }]}>\r\n          <View style={styles.sheetHeader}>\r\n            <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>Mi código QR</Text>\r\n            <Pressable onPress={onClose} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\r\n          </View>\r\n          <Text style={[styles.qrSub, { color: colors.textSecondary }]}>Escanea para seguirme en EG Route Plan</Text>\r\n          <View style={styles.qrBox}><QRCode value={egId} size={168} color=\"#10202E\" backgroundColor={brand.white} /></View>\r\n          <Text style={[styles.qrId, { color: colors.textPrimary }]}>{egId}</Text>\r\n          <Text style={[styles.qrHint, { color: colors.textSecondary }]}>Tu EG Route Plan ID es único y no se puede cambiar.</Text>\r\n        </View>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Modal estado vacío simple. */\r\nfunction EmptyStateModal({ visible, text, onClose }: { visible: boolean; text: string; onClose: () => void }) {\r\n  const { colors } = useTheme();\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={[styles.backdrop, { backgroundColor: colors.overlay, alignItems: 'center', justifyContent: 'center' }]}>\r\n        <View style={[styles.emptyCard, { backgroundColor: colors.card }]}>\r\n          <View style={[styles.emptyIcon, { backgroundColor: alpha(colors.primary, 0.08) }]}><Store size={30} color={colors.primary} /></View>\r\n          <Text style={[styles.emptyTitle, { color: colors.textPrimary }]}>{text.split(' · ')[0]}</Text>\r\n          <Text style={[styles.emptyBody, { color: colors.textSecondary }]}>{text.split(' · ').slice(1).join(' · ')}</Text>\r\n          <Pressable onPress={onClose} style={({ pressed }) => [styles.emptyOk, { backgroundColor: colors.primary, opacity: pressed ? 0.85 : 1 }]}>\r\n            <Text style={styles.emptyOkTxt}>Entendido</Text>\r\n          </Pressable>\r\n        </View>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Selector de ubicación INTERNACIONAL: país (ISO) → ciudad (GQ chips o libre). */\r\nfunction LocationModal({ visible, profile, onClose, onSaved }: { visible: boolean; profile: MeProfile; onClose: () => void; onSaved: (p: MeProfile) => void }) {\r\n  const { colors } = useTheme();\r\n  const [country, setCountry] = useState(profile.countryCode ?? 'GQ');\r\n  const [city, setCity] = useState(profile.city ?? '');\r\n  const [q, setQ] = useState('');\r\n  const [busy, setBusy] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n\r\n  useEffect(() => {\r\n    if (visible) {\r\n      setCountry(profile.countryCode ?? 'GQ');\r\n      setCity(profile.city ?? '');\r\n      setQ('');\r\n      setError(null);\r\n    }\r\n  }, [visible, profile]);\r\n\r\n  const sel = COUNTRIES.find((c) => c.code === country) ?? COUNTRIES[0];\r\n  const filtered = COUNTRIES.filter((c) => !q || c.name.toLowerCase().includes(q.toLowerCase()) || c.code.toLowerCase().includes(q.toLowerCase()));\r\n  const isGQ = country === 'GQ';\r\n\r\n  const save = async () => {\r\n    setBusy(true); setError(null);\r\n    try {\r\n      const next = await authApi.updateMe({ country: sel.name, countryCode: sel.code, city: city.trim() || undefined });\r\n      onSaved(next);\r\n    } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo guardar la ubicación'); }\r\n    finally { setBusy(false); }\r\n  };\r\n\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={[styles.sheetRoot, { backgroundColor: colors.overlay }]}>\r\n        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} />\r\n        <View style={[styles.sheetCardTall, { backgroundColor: colors.card }]}>\r\n          <View style={styles.sheetHeader}>\r\n            <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>Ubicación</Text>\r\n            <Pressable onPress={onClose} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\r\n          </View>\r\n          <FormField label=\"Buscar país (nombre o abreviatura)\" placeholder=\"Guinea Ecuatorial (GQ)…\" value={q} onChangeText={setQ} />\r\n          <ScrollView style={{ maxHeight: 240 }} showsVerticalScrollIndicator={false}>\r\n            {filtered.map((c) => {\r\n              const active = c.code === country;\r\n              return (\r\n                <Pressable key={c.code} onPress={() => { setCountry(c.code); if (c.code !== 'GQ') setCity(''); }} style={({ pressed }) => [styles.pickRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}>\r\n                  <Text style={[styles.pickRowTxt, { color: active ? colors.primary : colors.textPrimary, fontWeight: active ? '900' : '600' }]}>{c.name}</Text>\r\n                  <Text style={[styles.pickRowCode, { color: colors.textSecondary }]}>{c.code}</Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </ScrollView>\r\n          {isGQ ? (\r\n            <View style={styles.cityChips}>\r\n              <Text style={[styles.pickLabel, { color: colors.textSecondary }]}>Ciudad</Text>\r\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e7 }}>\r\n                {GQ_CITIES.map((c) => {\r\n                  const active = city === c;\r\n                  return (\r\n                    <Pressable key={c} onPress={() => setCity(active ? '' : c)} style={[styles.cityChip, { backgroundColor: active ? alpha(colors.primary, 0.14) : colors.surface, borderColor: active ? colors.primary : colors.border }]}>\r\n                      <Text style={{ color: active ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '700' }}>{c}</Text>\r\n                    </Pressable>\r\n                  );\r\n                })}\r\n              </View>\r\n            </View>\r\n          ) : (\r\n            <FormField label=\"Ciudad\" placeholder=\"Escribe tu ciudad…\" value={city} onChangeText={setCity} />\r\n          )}\r\n          {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>{error}</Text> : null}\r\n          <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e8 }}>\r\n            <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={onClose} disabled={busy} /></View>\r\n            <View style={{ flex: 1.4 }}><PrimaryButton title={busy ? 'Guardando…' : 'Guardar ubicación'} onPress={save} loading={busy} /></View>\r\n          </View>\r\n        </View>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Selector de profesión: catálogo de Buscar Work (PROFESSIONS). */\r\nfunction ProfessionModal({ visible, profile, onClose, onSaved }: { visible: boolean; profile: MeProfile; onClose: () => void; onSaved: (p: MeProfile) => void }) {\r\n  const { colors } = useTheme();\r\n  const [sel, setSel] = useState(profile.profession ?? '');\r\n  const [busy, setBusy] = useState(false);\r\n  const [error, setError] = useState<string | null>(null);\r\n  const [custom, setCustom] = useState('');\r\n\r\n  useEffect(() => { if (visible) { setSel(profile.profession ?? ''); setCustom(''); setError(null); } }, [visible, profile]);\r\n\r\n  const save = async (prof: string) => {\r\n    setBusy(true); setError(null);\r\n    try { const next = await authApi.updateMe({ profession: prof || undefined }); onSaved(next); }\r\n    catch (e) { setError(e instanceof Error ? e.message : 'No se pudo guardar la profesión'); }\r\n    finally { setBusy(false); }\r\n  };\r\n\r\n  const active = (label: string) => sel === label;\r\n\r\n  return (\r\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={[styles.sheetRoot, { backgroundColor: colors.overlay }]}>\r\n        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} />\r\n        <View style={[styles.sheetCardTall, { backgroundColor: colors.card }]}>\r\n          <View style={styles.sheetHeader}>\r\n            <View>\r\n              <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>Profesión</Text>\r\n              <Text style={[styles.sheetSub, { color: colors.textSecondary }]}>Sincronizada con Buscar Work</Text>\r\n            </View>\r\n            <Pressable onPress={onClose} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\r\n          </View>\r\n          <ScrollView style={{ flexShrink: 1 }} showsVerticalScrollIndicator={false}>\r\n            {PROFESSIONS.map((p) => {\r\n              const isActive = active(p.label);\r\n              return (\r\n                <Pressable key={p.id} onPress={() => setSel(isActive ? '' : p.label)} style={({ pressed }) => [styles.pickRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}>\r\n                  <Briefcase size={17} color={isActive ? colors.primary : colors.textSecondary} />\r\n                  <Text style={[styles.pickRowTxt, { color: isActive ? colors.primary : colors.textPrimary, fontWeight: isActive ? '900' : '600' }]}>{p.label}</Text>\r\n                </Pressable>\r\n              );\r\n            })}\r\n          </ScrollView>\r\n          <FormField label=\"Otra profesión…\" placeholder=\"Escribe tu profesión\" value={custom} onChangeText={setCustom} />\r\n          {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>{error}</Text> : null}\r\n          <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e6 }}>\r\n            <View style={{ flex: 1 }}><GhostButton title=\"Cancelar\" onPress={onClose} disabled={busy} /></View>\r\n            <View style={{ flex: 1.4 }}>\r\n              <PrimaryButton title={busy ? 'Guardando…' : 'Guardar profesión'} onPress={() => save(custom.trim() || sel)} loading={busy} disabled={!custom.trim() && !sel} />\r\n            </View>\r\n          </View>\r\n        </View>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Etiqueta humana del estado de un viaje activo. */\r\nfunction activeTripLabel(status: string): string {\r\n  if (status === 'requested') return 'BUSCANDO CONDUCTOR';\r\n  if (status === 'in_progress') return 'VIAJE EN MARCHA';\r\n  return 'CONDUCTOR EN CAMINO';\r\n}\r\n\r\nconst tripCard = StyleSheet.create({\r\n  card: { borderRadius: 18, borderWidth: 1.5, padding: espaciado.e14, flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, marginTop: espaciado.e14 },\r\n  iconBox: { width: 40, height: 40, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\r\n  title: { fontSize: 14.5, fontWeight: '900', marginTop: 1 },\r\n  sub: { fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e2 },\r\n});\r\n\r\nconst styles = StyleSheet.create({\r\n  root: { flex: 1 },\r\n  scroll: { flex: 1 },\r\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\r\n\r\n  cover: { width: '100%', justifyContent: 'flex-end', overflow: 'hidden' },\r\n  coverImg: { resizeMode: 'cover' },\r\n  coverScrim: { ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(8,14,24,0.22)' },\r\n  coverScrimBottom: { position: 'absolute', left: 0, right: 0, bottom: 0, height: '72%', backgroundColor: 'rgba(8,14,24,0.50)' },\r\n  coverActions: { position: 'absolute', left: 12, alignItems: 'flex-start', gap: espaciado.e8, zIndex: 6 },\r\n  editCapsule: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, paddingHorizontal: espaciado.e10, paddingVertical: espaciado.e5, borderRadius: radios.full, backgroundColor: 'rgba(0,0,0,0.35)' },\r\n  editCapsuleTxt: { color: brand.white, fontSize: tipografia.caption, fontWeight: '800' },\r\n  menuGhostBtn: { width: 30, height: 30, alignItems: 'center', justifyContent: 'center' },\r\n\r\n  identityBlock: { paddingHorizontal: espaciado.e16, paddingBottom: espaciado.e16 },\r\n  identityTopRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 },\r\n  avatar: { width: 76, height: 76, borderRadius: 38, borderWidth: 3, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },\r\n  avatarImg: { width: '100%', height: '100%' },\r\n  avatarText: { fontSize: 30, fontWeight: '900', color: brand.white, textShadowColor: 'rgba(0,0,0,0.4)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 3 },\r\n  nameRow: { flexDirection: 'row', alignItems: 'center' },\r\n  name: { fontSize: 21, fontWeight: '900', color: brand.white, flexShrink: 1, textShadowColor: 'rgba(0,0,0,0.5)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 4 },\r\n  egIdRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e3 },\r\n  egId: { color: 'rgba(255,255,255,0.95)', fontSize: 10.5, fontWeight: '800', letterSpacing: 0.3 },\r\n  qrMini: { width: 20, height: 20, borderRadius: 6, alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(255,255,255,0.18)' },\r\n  locRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginTop: espaciado.e2 },\r\n  locTxt: { color: 'rgba(255,255,255,0.92)', fontSize: tipografia.micro, fontWeight: '600' },\r\n  addStatusBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, alignSelf: 'flex-start', borderRadius: radios.full, borderWidth: 1, paddingHorizontal: espaciado.e9, paddingVertical: 3.5, marginTop: espaciado.e6, backgroundColor: 'rgba(0,0,0,0.25)' },\r\n  addStatusTxt: { color: 'rgba(255,255,255,0.95)', fontSize: 10.5, fontWeight: '800' },\r\n\r\n  statsRow: { flexDirection: 'row', gap: espaciado.e16, marginTop: espaciado.e10 },\r\n  statItem: { alignItems: 'center', minWidth: 62 },\r\n  statValue: { color: brand.white, fontSize: 15, fontWeight: '900' },\r\n  statLabel: { color: 'rgba(255,255,255,0.85)', fontSize: 9.5, fontWeight: '700', marginTop: 1 },\r\n  ratingValueRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 },\r\n\r\n  bioTxt: { color: 'rgba(255,255,255,0.92)', fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e6, lineHeight: 16 },\r\n\r\n  linksArea: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e5, marginTop: espaciado.e8 },\r\n  linkChip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, backgroundColor: 'rgba(255,255,255,0.18)', borderRadius: radios.full, borderWidth: 1, borderColor: 'rgba(255,255,255,0.35)', paddingHorizontal: espaciado.e8, paddingVertical: 3.5, maxWidth: '92%' },\r\n  linkChipTxt: { color: brand.white, fontSize: 10.5, fontWeight: '700', maxWidth: 130 },\r\n  // Chip de OCUPACIÓN: va el primero en la fila de correos/enlaces (delante).\r\n  occupChip: { backgroundColor: 'rgba(255,209,102,0.22)' },\r\n\r\n  lbTitleWrap: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: espaciado.e18 },\r\n  lbTitleCover: { fontSize: 26, fontWeight: '900', color: brand.white, letterSpacing: 0.3, textShadowColor: 'rgba(0,0,0,0.6)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 5 },\r\n  publishCoverBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e5, backgroundColor: 'rgba(255,255,255,0.24)', borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderWidth: 1, borderColor: 'rgba(255,255,255,0.55)' },\r\n  publishCoverTxt: { color: brand.white, fontSize: tipografia.caption, fontWeight: '900' },\r\n\r\n  body: { paddingHorizontal: espaciado.e18 },\r\n  tabsRow: { flexDirection: 'row', gap: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth, marginTop: espaciado.e4 },\r\n  tabItem: { paddingVertical: espaciado.e8 },\r\n  tabTxt: { fontSize: tipografia.body },\r\n  tabUnderline: { position: 'absolute', bottom: 0, left: 0, right: 0, height: 2.5, borderRadius: 2 },\r\n\r\n  lbEmpty: { borderRadius: radios.lg, borderWidth: StyleSheet.hairlineWidth, padding: espaciado.e16, marginTop: espaciado.e12, alignItems: 'center' },\r\n  lbEmptyIcon: { width: 52, height: 52, borderRadius: 26, alignItems: 'center', justifyContent: 'center', marginBottom: espaciado.e8 },\r\n  lbEmptyTitle: { fontSize: tipografia.body, fontWeight: '900', textAlign: 'center' },\r\n  lbEmptyBody: { fontSize: tipografia.caption, fontWeight: '600', textAlign: 'center', marginTop: espaciado.e4, lineHeight: 16 },\r\n  lbActions: { flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e8 },\r\n  version: { textAlign: 'center', fontSize: tipografia.micro, marginTop: espaciado.e16, fontWeight: '600' },\r\n\r\n  // Modales bottom-sheet\r\n  backdrop: { ...StyleSheet.absoluteFillObject },\r\n  sheetRoot: { flex: 1, justifyContent: 'flex-end' },\r\n  sheetCard: { borderTopLeftRadius: 24, borderTopRightRadius: 24, padding: espaciado.e20, paddingBottom: 34, gap: espaciado.e12 },\r\n  sheetCardTall: { borderTopLeftRadius: 24, borderTopRightRadius: 24, padding: espaciado.e18, paddingBottom: 34, maxHeight: '88%' },\r\n  sheetHeader: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },\r\n  sheetTitle: { fontSize: 17, fontWeight: '900' },\r\n  sheetSub: { fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e2 },\r\n  pickRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e11, paddingHorizontal: espaciado.e4, borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: 'rgba(0,0,0,0.06)' },\r\n  pickRowTxt: { flex: 1, fontSize: tipografia.body, fontWeight: '600' },\r\n  pickRowCode: { fontSize: tipografia.micro, fontWeight: '800' },\r\n  pickLabel: { fontSize: tipografia.caption, fontWeight: '800', marginTop: espaciado.e4 },\r\n  cityChips: { gap: espaciado.e6 },\r\n  cityChip: { borderRadius: radios.full, borderWidth: 1.2, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e6 },\r\n\r\n  lbGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10, marginTop: espaciado.e12 },\r\n  qrCard: { width: '86%', maxWidth: 340, borderRadius: 22, padding: espaciado.e18, alignItems: 'center' },\r\n  qrSub: { fontSize: tipografia.caption, fontWeight: '600', marginTop: espaciado.e2, alignSelf: 'flex-start' },\r\n  qrBox: { backgroundColor: brand.white, padding: espaciado.e12, borderRadius: 14, marginTop: espaciado.e14 },\r\n  qrId: { fontSize: 15, fontWeight: '900', marginTop: espaciado.e12, letterSpacing: 0.5 },\r\n  qrHint: { fontSize: tipografia.micro, fontWeight: '600', marginTop: espaciado.e6, textAlign: 'center' },\r\n  emptyCard: { width: '84%', maxWidth: 330, borderRadius: 22, padding: espaciado.e22, alignItems: 'center' },\r\n  emptyIcon: { width: 64, height: 64, borderRadius: 32, alignItems: 'center', justifyContent: 'center', marginBottom: espaciado.e10 },\r\n  emptyTitle: { fontSize: tipografia.subtitle, fontWeight: '900', textAlign: 'center' },\r\n  emptyBody: { fontSize: tipografia.body, fontWeight: '600', textAlign: 'center', marginTop: espaciado.e6, lineHeight: 19 },\r\n  emptyOk: { marginTop: espaciado.e16, borderRadius: radios.full, paddingHorizontal: espaciado.e26, paddingVertical: espaciado.e10 },\r\n  emptyOkTxt: { color: brand.white, fontWeight: '900', fontSize: tipografia.body },\r\n  photoLg: { width: 110, height: 110, borderRadius: 55, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },\r\n  photoLgImg: { width: '100%', height: '100%' },\r\n  photoLgTxt: { fontSize: 40, fontWeight: '900' },\r\n  pickBtn: { flex: 1, borderRadius: 14, borderWidth: 1, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e12, minHeight: 44 },\r\n  pickBusy: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 },\r\n});\r\n\r\n\r\n","/**\n * useMisNegocios — ¿QUÉ NEGOCIOS TIENE ESTA CUENTA?\n *\n * Una sola fuente de verdad para el acceso del comerciante, que sale en DOS sitios (el bloque\n * «Tus negocios» del perfil y el menú lateral ☰). Si cada pantalla lo detectara por su cuenta,\n * en dos semanas una conocería el restaurante y la otra no.\n *\n * ── El estándar que aplica (`ESTANDAR-ENTORNOS-DE-CONTROL.md`) ────────────────\n * En Life Book se **publica** y se **descubre**; la gestión robusta vive en el **entorno de\n * control** de cada negocio; y el acceso a ese entorno es **del comerciante**, no del\n * consumidor. Una cuenta puede tener **varios negocios de verticales distintos** —medido: la\n * cuenta de pruebas tiene un hotel, un restaurante y es repartidor—, así que esto devuelve una\n * **lista**, no un booleano.\n *\n * ── Decisiones que no son obvias ─────────────────────────────────────────────\n * · **Las cuatro detecciones van en `Promise.allSettled`**: que el módulo de comida no\n *   conteste no puede dejar sin acceso al hotel. Cada fallo se traduce en «no tiene ese\n *   negocio», nunca en una pantalla rota.\n * · **`nota`** existe para poder decir la verdad a medias: un negocio cuyo entorno ya funciona\n *   pero que todavía no está publicado en Life Book lo dice, en vez de aparentar que está\n *   integrado. Hoy es el caso del restaurante y del trabajo.\n * · **El icono no se devuelve desde aquí** (esto es un `.ts`, no un `.tsx`): se devuelve el\n *   `vertical` y cada pantalla lo pinta con su icono. Así el hook no depende del kit de UI.\n */\nimport { useEffect, useRef, useState } from 'react';\nimport { hotelApi } from '../api/hotel';\nimport { commerceApi } from '../api/commerce';\nimport { foodApi } from '../api/food';\nimport { workApi } from '../api/work';\n\n/** Los verticales que existen hoy. `(string & {})` deja pasar otros sin romper el tipado. */\nexport type VerticalNegocio = 'hotel' | 'restaurante' | 'mercado' | 'trabajo';\n\nexport interface MiNegocio {\n  /** Identificador estable para listas y para `key`. */\n  clave: string;\n  vertical: VerticalNegocio;\n  /** Qué es el entorno de control (lo que se va a abrir). */\n  titulo: string;\n  /** Una línea con lo que hay dentro, con datos reales. */\n  detalle: string;\n  /** Aviso honesto opcional (p. ej. «todavía no está publicado en Life Book»). */\n  nota?: string;\n  /** A dónde lleva. */\n  ruta: string;\n}\n\n/**\n * Devuelve la lista de negocios de la cuenta. `null` mientras carga; `[]` si no tiene ninguno.\n *\n * Se recarga cuando cambia `cuenta` (el id del usuario): al cambiar de sesión, los negocios son\n * otros.\n */\nexport function useMisNegocios(cuenta?: string | null): { negocios: MiNegocio[] | null; cargando: boolean } {\n  const [negocios, setNegocios] = useState<MiNegocio[] | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const vivo = useRef(true);\n\n  useEffect(() => {\n    vivo.current = true;\n    setCargando(true);\n    void (async () => {\n      const [hotel, tienda, comida, ofertas] = await Promise.allSettled([\n        hotelApi.myHotel(),\n        commerceApi.myShop(),\n        foodApi.ownerMe(),\n        workApi.myJobs(),\n      ]);\n      if (!vivo.current) return;\n\n      const lista: MiNegocio[] = [];\n\n      // ── Alojamiento ──\n      // UNA fila por negocio, no una por parte: el estándar dice «un negocio por fila, cada uno\n      // con su entorno», y la puerta a «Gestión» vive DENTRO de «Hoy». Sacar aquí las dos partes\n      // haría que la lista creciera con las partes de cada negocio en vez de con los negocios —\n      // con cuatro verticales serían ocho filas, y con ocho serían dieciséis.\n      const esHotel = hotel.status === 'fulfilled' && hotel.value?.hotel?.isHotel === true;\n      if (esHotel && hotel.status === 'fulfilled') {\n        const tipos = (hotel.value.rooms ?? []).length;\n        lista.push({\n          clave: 'hotel',\n          vertical: 'hotel',\n          titulo: 'Panel del hotel',\n          detalle: tipos\n            ? `Recepción y reservas de hoy · ${tipos} tipo(s) de habitación`\n            : 'Recepción y reservas · todavía sin habitaciones',\n          ruta: '/lifebook-hotel-panel',\n        });\n      }\n\n      // ── Restaurante ──\n      // La nota decía «Todavía no está publicado en Life Book: la migración está en curso». Eso\n      // era verdad mientras el módulo de comida estaba a medias, pero ya NO: está desplegado\n      // (migración 041 aplicada, servidor reiniciado, 17/17 comprobaciones) y los clientes SÍ\n      // llegan a él desde el ☰ de Life Book («Comida Rápida» → `/food`). Dejar aquella frase era\n      // decirle al dueño que su negocio no funciona cuando sí funciona. Lo que de verdad le sirve\n      // saber es DÓNDE lo encuentra el cliente.\n      if (comida.status === 'fulfilled' && comida.value?.restaurant) {\n        lista.push({\n          clave: 'restaurante',\n          vertical: 'restaurante',\n          titulo: 'Panel del restaurante',\n          detalle: `${comida.value.restaurant.businessName} · cocina, menú y pedidos`,\n          nota: 'Los clientes lo encuentran en Life Book, en «Comida Rápida».',\n          ruta: '/food-owner',\n        });\n      }\n\n      // ── Mercado (tienda de productos): ya vive en Life Book ──\n      if (tienda.status === 'fulfilled' && tienda.value?.shop) {\n        lista.push({\n          clave: 'mercado',\n          vertical: 'mercado',\n          titulo: esHotel ? 'Mi escaparate' : 'Mi tienda',\n          detalle: `${tienda.value.shop.name} · pedidos, publicaciones y existencias`,\n          ruta: '/lifebook-merchant',\n        });\n      }\n\n      // ── Trabajo: su entorno son ahora dos pantallas propias (Hoy y Gestión) ──\n      if (ofertas.status === 'fulfilled' && (ofertas.value ?? []).length) {\n        const jobs = ofertas.value ?? [];\n        const activas = jobs.filter((j) => j.status !== 'closed');\n        const sinResponder = activas.reduce(\n          (n, j) => n + (j.applicants ?? []).filter(\n            (a: { status: string }) => a.status !== 'selected' && a.status !== 'rejected').length,\n          0,\n        );\n        lista.push({\n          clave: 'trabajo',\n          vertical: 'trabajo',\n          titulo: 'Mis ofertas de trabajo',\n          detalle: `${activas.length} activa(s) · ${sinResponder} candidatura(s) sin responder`,\n          nota: 'Vive fuera de Life Book: las ofertas se gestionan en su propio entorno.',\n          ruta: '/work-panel',\n        });\n      }\n\n      setNegocios(lista);\n      setCargando(false);\n    })();\n    return () => { vivo.current = false; };\n  }, [cuenta]);\n\n  return { negocios, cargando };\n}\n","/**\n * Cliente del servicio Buscar Work (bolsa de empleo) — backend unificado.\n * Base ABSOLUTA: vive en /api/work/* (como intercity).\n * Forma normalizada que consume filterJobs/sortJobs del kit.\n */\n\nimport { http } from './httpClient';\n\nimport { API_HOST } from './config';\nexport const WORK_API = `${API_HOST}/api`;\nconst w = (p: string) => `${WORK_API}${p}`;\n\nexport interface WorkRecruiter { name: string | null; role: string | null; avatarColor: string | null; phone: string | null; }\nexport interface WorkJob {\n  id: string; title: string; company: string; companyLogo?: string | null; companyColor: string;\n  companyVerified: boolean; applicantsCount: number;\n  city: string; cityId: string; location?: string | null; zone?: string | null;\n  coordinates: { latitude: number | null; longitude: number | null };\n  salaryMin: number; salaryMax: number; salary: string;\n  contractType: string; contractLabel: string; category: string; experienceRequired: number;\n  benefits: string[]; responsibilities: string[]; requirements: string[];\n  description: string; isNew: boolean; isUrgent: boolean;\n  isFeatured: boolean; featuredUntil?: string | null;\n  distance?: string | null; publishedAt: string; expiresAt?: string | null; status: string;\n  bookmarked: boolean; applied: boolean; recruiter: WorkRecruiter;\n  similar?: WorkJob[];\n  applicants?: Array<{ id: string; fullName?: string | null; phone?: string | null; documentType?: string | null; documentNumber?: string | null; note?: string | null; status: string; createdAt: string }>;\n}\nexport interface WorkCatalog { categories: Array<{ id: string; label: string }>; cities: Array<{ id: string; label: string }>; contractTypes: Record<string, string>; }\n\nexport interface WorkPlan {\n  planCode: string; planName: string; offerLimit: number; activeJobs: number; expiresAt: string | null;\n}\n\nexport interface WorkFilters {\n  categories?: string[]; cities?: string[]; contractTypes?: string[]; benefits?: string[];\n  salaryMin?: number; salaryMax?: number; experience?: number; distance?: number;\n  verifiedOnly?: boolean; urgentOnly?: boolean; q?: string;\n}\n\nexport const workApi = {\n  catalog: () => http.get<WorkCatalog>(w('/work/catalog'), false),\n  jobs: (f: WorkFilters = {}) => {\n    const p: Record<string, string> = {};\n    if (f.categories?.length) p.categories = f.categories.join(',');\n    if (f.cities?.length) p.cities = f.cities.join(',');\n    if (f.contractTypes?.length) p.contractTypes = f.contractTypes.join(',');\n    if (f.benefits?.length) p.benefits = f.benefits.join(',');\n    if (f.salaryMin != null) p.salaryMin = String(f.salaryMin);\n    if (f.salaryMax != null) p.salaryMax = String(f.salaryMax);\n    if (f.experience != null) p.experience = String(f.experience);\n    if (f.verifiedOnly) p.verifiedOnly = 'true';\n    if (f.urgentOnly) p.urgentOnly = 'true';\n    if (f.q) p.q = f.q;\n    const qs = new URLSearchParams(p).toString();\n    return http.get<WorkJob[]>(w(`/work/jobs${qs ? '?' + qs : ''}`), true);\n  },\n  job: (id: string) => http.get<WorkJob>(w(`/work/jobs/${id}`), true),\n  similar: (id: string) => http.get<WorkJob[]>(w(`/work/jobs/${id}/similar`), true),\n  myJobs: () => http.get<WorkJob[]>(w('/work/my-jobs'), true),\n  myPlan: () => http.get<WorkPlan>(w('/work/me/plan'), true),\n  create: (body: Record<string, unknown>) => http.post<{ message: string; job: WorkJob }>(w('/work/jobs'), body, true),\n  update: (id: string, body: Record<string, unknown>) => http.put<{ message: string }>(w(`/work/jobs/${id}`), body, true),\n  close: (id: string) => http.put<{ message: string }>(w(`/work/jobs/${id}/close`), {}, true),\n  duplicate: (id: string) => http.post<{ message: string; job: WorkJob }>(w(`/work/jobs/${id}/duplicate`), {}, true),\n  bookmark: (id: string) => http.post<{ message: string; bookmarked: boolean }>(w(`/work/jobs/${id}/bookmark`), {}, true),\n  apply: (id: string, note?: string) => http.post<{ message: string }>(w(`/work/jobs/${id}/apply`), { note }, true),\n  selectApplicant: (appId: string, status: 'selected' | 'rejected') =>\n    http.put<{ message: string }>(w(`/work/applications/${appId}/status`), { status }, true),\n  report: (id: string, reason?: string, note?: string) =>\n    http.post<{ message: string }>(w(`/work/jobs/${id}/report`), { reason, note }, true),\n};\n","/**\n * EditProfileModal — editor de perfil (nombre + foto de avatar con guardado\n * real PATCH /auth/me). Reutilizable desde Perfil y Editar perfil.\n * 2026-09-09: la galería/cámara usan core/pickImage (sin base64 inline; el\n * botón muestra \"Procesando…\" con spinner mientras se lee la imagen).\n */\n\nimport React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, Image, KeyboardAvoidingView, Modal, Platform, Pressable, StyleSheet, Text, View } from 'react-native';\nimport { X } from 'lucide-react-native';\nimport { alpha, espaciado, FormField, GhostButton, PrimaryButton, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { authApi, type MeProfile } from '../api/auth';\nimport { absUrl } from '../api/config';\nimport { pickImageFromCamera, pickImageFromLibrary } from '../core/pickImage';\n\ntype Picking = 'library' | 'camera' | null;\n\nexport default function EditProfileModal({ visible, profile, onClose, onSaved }: {\n  visible: boolean;\n  profile: MeProfile;\n  onClose: () => void;\n  onSaved: (p: MeProfile) => void;\n}) {\n  const { colors } = useTheme();\n  const [name, setName] = useState(profile.fullName ?? '');\n  const [avatar, setAvatar] = useState<string | null>(null); // nueva foto (dataURL)\n  const [busy, setBusy] = useState(false);\n  const [picking, setPicking] = useState<Picking>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  // Cada vez que se abre con un perfil distinto, sincroniza el formulario.\n  useEffect(() => {\n    if (visible) {\n      setName(profile.fullName ?? '');\n      setAvatar(null);\n      setError(null);\n      setPicking(null);\n    }\n  }, [visible, profile]);\n\n  const pickFromLibrary = async () => {\n    setError(null);\n    setPicking('library');\n    try {\n      const img = await pickImageFromLibrary();\n      if (img) { setAvatar(img.dataUrl); }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo abrir la galería');\n    } finally {\n      setPicking(null);\n    }\n  };\n\n  const pickFromCamera = async () => {\n    setError(null);\n    setPicking('camera');\n    try {\n      const img = await pickImageFromCamera();\n      if (img) { setAvatar(img.dataUrl); }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo abrir la cámara');\n    } finally {\n      setPicking(null);\n    }\n  };\n\n  const save = async () => {\n    const trimmed = name.trim();\n    if (trimmed.length < 3) { setError('El nombre debe tener al menos 3 caracteres'); return; }\n    setBusy(true); setError(null);\n    try {\n      const next = await authApi.updateMe({ fullName: trimmed, ...(avatar ? { avatar } : {}) });\n      onSaved(next);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo guardar. Inténtalo de nuevo');\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const preview = avatar ?? (profile.avatarUrl ? absUrl(profile.avatarUrl) : null);\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <KeyboardAvoidingView style={styles.modalRoot} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n        <Pressable style={styles.modalBackdrop} onPress={onClose} />\n        <View style={[styles.modalCard, { backgroundColor: colors.card }]}>\n          <View style={styles.modalHeader}>\n            <Text style={[styles.modalTitle, { color: colors.textPrimary }]}>Editar perfil</Text>\n            <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar\">\n              <X size={20} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n\n          {/* Avatar: foto actual o inicial */}\n          <View style={styles.avatarEditRow}>\n            <View style={[styles.avatarLg, { backgroundColor: alpha(colors.primary, 0.15) }]}>\n              {preview ? (\n                <Image source={{ uri: preview }} style={styles.avatarLgImg} />\n              ) : (\n                <Text style={[styles.avatarLgText, { color: colors.primary }]}>\n                  {(profile.fullName ?? 'U').trim().charAt(0).toUpperCase() || 'U'}\n                </Text>\n              )}\n            </View>\n            <View style={{ flex: 1, gap: espaciado.e8 }}>\n              <Pressable\n                onPress={pickFromCamera}\n                disabled={busy || picking !== null}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Tomar foto con la cámara\"\n                style={[styles.pickBtn, { backgroundColor: colors.surface, borderColor: colors.border, opacity: busy || (picking !== null && picking !== 'camera') ? 0.45 : 1 }]}\n              >\n                {picking === 'camera'\n                  ? <View style={styles.pickBusy}><ActivityIndicator color={colors.primary} size=\"small\" /><Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Procesando…</Text></View>\n                  : <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>📷 Tomar foto</Text>}\n              </Pressable>\n              <Pressable\n                onPress={pickFromLibrary}\n                disabled={busy || picking !== null}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Elegir desde la galería\"\n                style={[styles.pickBtn, { backgroundColor: colors.surface, borderColor: colors.border, opacity: busy || (picking !== null && picking !== 'library') ? 0.45 : 1 }]}\n              >\n                {picking === 'library'\n                  ? <View style={styles.pickBusy}><ActivityIndicator color={colors.primary} size=\"small\" /><Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>Procesando…</Text></View>\n                  : <Text style={{ color: colors.primary, fontSize: tipografia.body, fontWeight: '800' }}>🖼️ Desde galería</Text>}\n              </Pressable>\n            </View>\n          </View>\n          <Text style={[styles.avatarHint, { color: colors.textSecondary }]}>\n            {avatar ? 'Foto nueva elegida. Guarda para aplicarla.' : 'Tu foto se mostrará en tu perfil.'}\n          </Text>\n\n          <FormField\n            label=\"Nombre\"\n            placeholder=\"Tu nombre completo\"\n            value={name}\n            onChangeText={setName}\n            maxLength={120}\n            editable={!busy}\n          />\n\n          {error ? <Text style={{ color: colors.danger, fontSize: tipografia.caption, fontWeight: '700' }}>{error}</Text> : null}\n\n          <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e4 }}>\n            <View style={{ flex: 1 }}>\n              <GhostButton title=\"Cancelar\" onPress={onClose} disabled={busy} />\n            </View>\n            <View style={{ flex: 1.4 }}>\n              <PrimaryButton title={busy ? 'Guardando…' : 'Guardar cambios'} onPress={save} loading={busy} />\n            </View>\n          </View>\n        </View>\n      </KeyboardAvoidingView>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  modalRoot: { flex: 1, justifyContent: 'flex-end' },\n  modalBackdrop: { ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(0,0,0,0.45)' },\n  modalCard: { borderTopLeftRadius: 24, borderTopRightRadius: 24, padding: espaciado.e20, paddingBottom: espaciado.e30, gap: espaciado.e14 },\n  modalHeader: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },\n  modalTitle: { fontSize: 17, fontWeight: '900' },\n  avatarEditRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e14 },\n  avatarLg: { width: 82, height: 82, borderRadius: 41, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },\n  avatarLgImg: { width: '100%', height: '100%' },\n  avatarLgText: { fontSize: 32, fontWeight: '900' },\n  avatarHint: { fontSize: tipografia.caption, fontWeight: '600' },\n  pickBtn: { borderRadius: 14, borderWidth: 1, alignItems: 'center', justifyContent: 'center', paddingVertical: espaciado.e12, minHeight: 44 },\n  pickBusy: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 },\n});\n","/**\r\n * ServicesDrawer — panel lateral derecho (estilo Xiaohongshu) con los servicios\r\n * y herramientas de EG Route Plan. Se abre desde el ☰ del Perfil.\r\n *\r\n * Secciones: Servicios · Comercio y creador · Cuenta y actividad · Soporte.\r\n * \"Ajustes\" va FIJO al pie y abre la página independiente /settings.\r\n * Los ítems sin backend todavía muestran badge \"Próximamente\" (Alert honesto).\r\n */\r\n\r\nimport React, { useEffect, useRef, useState } from 'react';\r\nimport {\r\n  Alert, Animated, Image, Modal, Pressable, ScrollView, StyleSheet, Text, View,\r\n} from 'react-native';\r\nimport { useRouter } from 'expo-router';\r\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\r\nimport { ChevronRight, X, type LucideIcon } from 'lucide-react-native';\r\nimport {\r\n  BadgeCheck, BedDouble, Briefcase, CalendarDays, CarTaxiFront, Clapperboard, Clock, Download,\r\n  FileQuestion, Handshake, Headset, HelpCircle, History, KeyRound, LayoutGrid, Package, Route,\r\n  ScanLine, Settings, ShoppingBag, ShoppingCart, Siren, Sparkles, StickyNote, Store,\r\n  Ticket, UserCog, UserPlus, UserRound, Utensils, UtensilsCrossed, Wallet, Wrench,\r\n} from 'lucide-react-native';\r\nimport { alpha, elevation, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\r\nimport { absUrl } from '../api/config';\r\nimport { useMisNegocios, type VerticalNegocio } from '../core/useMisNegocios';\r\nimport { useSoyAgente } from '../core/useSoyAgente';\r\nimport { destinoMiPerfilLifeBook } from '../core/miPerfil';\r\nimport { ir as irSeguro } from '../constants/rutas';\r\n\r\n/**\r\n * Icono de cada vertical en el menú.\r\n *\r\n * El hook devuelve el `vertical`, no el icono (es un `.ts`, sin JSX): cada pantalla lo pinta.\r\n * Aquí no se usa el helper del perfil a propósito — el perfil no es un sitio del que un\r\n * componente del kit deba depender.\r\n */\r\nfunction iconoDeVerticalDrawer(v: VerticalNegocio): LucideIcon {\r\n  switch (v) {\r\n    case 'hotel': return requireIcon('BedDouble');\r\n    case 'restaurante': return requireIcon('UtensilsCrossed');\r\n    case 'trabajo': return requireIcon('Briefcase');\r\n    case 'mercado':\r\n    default: return requireIcon('Store');\r\n  }\r\n}\r\n\r\ntype Item = { icon: LucideIcon; label: string; route?: string; soon?: boolean; action?: () => void };\r\n\r\ninterface ServicesDrawerProps {\r\n  visible: boolean;\r\n  onClose: () => void;\r\n  /** Nombre y avatar del usuario (cabecera compacta). */\r\n  userName: string;\r\n  userAvatar?: string | null;\r\n  roleLabel: string;\r\n  role?: 'PASSENGER' | 'DRIVER' | 'ADMIN';\r\n  onEmergency: () => void;\r\n  /**\r\n   * Identificador de la cuenta: con él se averigua QUÉ NEGOCIOS tiene (`useMisNegocios`).\r\n   * Sin él, el bloque «Tus negocios» simplemente no aparece — el menú sigue funcionando.\r\n   */\r\n  cuenta?: string | null;\r\n}\r\n\r\nconst DRAWER_W = 318;\r\n\r\nexport default function ServicesDrawer({ visible, onClose, userName, userAvatar, roleLabel, role, onEmergency, cuenta }: ServicesDrawerProps) {\r\n  const { colors } = useTheme();\r\n  const router = useRouter();\r\n  const insets = useSafeAreaInsets();\r\n  const [mounted, setMounted] = useState(visible);\r\n  /** Divulgación progresiva del grupo «Servicios» (auditoría de diseño, Fase 1). */\r\n  const [verTodos, setVerTodos] = useState(false);\r\n  const anim = useRef(new Animated.Value(visible ? 1 : 0)).current;\r\n\r\n  /**\r\n   * ══ TUS NEGOCIOS ══  (el hook va AQUÍ, arriba, y no más abajo)\r\n   *\r\n   * 🔴 Esto ya se rompió una vez: la primera versión lo llamaba DESPUÉS de\r\n   * `if (!mounted) return null`. Al no estar montado el hook no se ejecutaba, y al montarse el\r\n   * menú se ejecutaba uno más que en el render anterior → React aborta con\r\n   * **«Rendered more hooks than during the previous render»** y la app se cae al abrir el menú.\r\n   * Lo cazó el CrashShield en el aparato.\r\n   *\r\n   * Regla que se deduce: **ningún hook después de un `return` temprano.** Los hooks primero,\r\n   * siempre, y las salidas después.\r\n   *\r\n   * La detección vive en `core/useMisNegocios` — la MISMA que usa el bloque del perfil, para\r\n   * que las dos no se separen. El estándar: `ESTANDAR-ENTORNOS-DE-CONTROL.md`.\r\n   */\r\n  const { negocios } = useMisNegocios(cuenta);\r\n  const tieneNegocio = (negocios?.length ?? 0) > 0;\r\n  // ¿Agente de caja? Se pregunta al servidor (el token de la app nunca trae rol\r\n  // AGENT). El hook va AQUÍ arriba, con los demás: ningún hook después de un\r\n  // `return` temprano — regla que ya costó una caída de la app (ver nota de abajo).\r\n  const { agente, pendiente } = useSoyAgente(cuenta);\r\n\r\n  useEffect(() => {\r\n    if (visible) {\r\n      setMounted(true);\r\n      Animated.timing(anim, { toValue: 1, duration: 220, useNativeDriver: true }).start();\r\n    } else {\r\n      Animated.timing(anim, { toValue: 0, duration: 180, useNativeDriver: true }).start(({ finished }) => {\r\n        if (finished) setMounted(false);\r\n      });\r\n    }\r\n  }, [visible, anim]);\r\n\r\n  if (!mounted) return null;\r\n\r\n  const translateX = anim.interpolate({ inputRange: [0, 1], outputRange: [DRAWER_W + 40, 0] });\r\n  const opacity = anim.interpolate({ inputRange: [0, 1], outputRange: [0, 1] });\r\n\r\n  const go = (route?: string) => {\r\n    onClose();\r\n    if (route) router.push(route as any);\r\n  };\r\n  const soon = () => Alert.alert('Próximamente', 'Esta función llegará en una próxima actualización.');\r\n\r\n  /** Grupo «Tus negocios», arriba del todo del menú (los hooks ya se llamaron más arriba). */\r\n  const renderNegocios = () => {\r\n    if (!negocios?.length) return null;\r\n    return (\r\n      <View key=\"negocios\">\r\n        <Text style={[styles.groupTitle, { color: colors.secondary }]}>\r\n          {negocios.length > 2 ? `TUS NEGOCIOS (${negocios.length})` : 'TU NEGOCIO'}\r\n        </Text>\r\n        <View style={[styles.groupCard, { backgroundColor: colors.card, borderColor: alpha(colors.secondary, 0.35), borderWidth: 1 }]}>\r\n          {negocios.map((n, i) => {\r\n            const Icon = iconoDeVerticalDrawer(n.vertical);\r\n            return (\r\n              <Pressable\r\n                key={n.clave}\r\n                onPress={() => go(n.ruta)}\r\n                style={({ pressed }) => [\r\n                  styles.row,\r\n                  { minHeight: 56, backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' },\r\n                  i > 0 && { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border },\r\n                ]}\r\n                accessibilityRole=\"button\"\r\n                accessibilityLabel={`${n.titulo}. ${n.detalle}${n.nota ? ` ${n.nota}` : ''}`}\r\n              >\r\n                <View style={[styles.rowIcon, { backgroundColor: alpha(colors.secondary, 0.12) }]}>\r\n                  <Icon size={18} color={colors.secondary} />\r\n                </View>\r\n                <View style={{ flex: 1 }}>\r\n                  <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }} numberOfLines={2}>\r\n                    {n.titulo}\r\n                  </Text>\r\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }} numberOfLines={2}>\r\n                    {n.detalle}\r\n                  </Text>\r\n                  {n.nota ? (\r\n                    <Text style={{ color: colors.secondary, fontSize: tipografia.micro, fontWeight: '700', marginTop: espaciado.e2 }} numberOfLines={2}>\r\n                      {n.nota}\r\n                    </Text>\r\n                  ) : null}\r\n                </View>\r\n                <ChevronRight size={16} color={colors.textSecondary} />\r\n              </Pressable>\r\n            );\r\n          })}\r\n        </View>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const S1: Item[] = [\r\n    { icon: requireIcon('Ticket'), label: 'Mis tickets', route: '/my-tickets' },\r\n    { icon: requireIcon('StickyNote'), label: 'Mi estado 24h', route: '/status' },\r\n    { icon: requireIcon('Briefcase'), label: 'Buscar Work', route: '/work' },\r\n    { icon: requireIcon('ShoppingBag'), label: 'Ecomerse', route: '/ecomerse' },\r\n    { icon: requireIcon('Utensils'), label: 'Comida Rápida', route: '/food' },\r\n    { icon: requireIcon('Route'), label: 'Ciudad a Ciudad', route: '/intercity' },\r\n    { icon: requireIcon('CarTaxiFront'), label: 'Llamar Taxi', route: '/taxi' },\r\n    { icon: requireIcon('History'), label: 'Historial taxi', route: '/trips-history' },\r\n    { icon: requireIcon('KeyRound'), label: 'Alquiler', route: '/alquiler' },\r\n    { icon: requireIcon('Wallet'), label: 'Monedero', route: '/monedero' },\r\n  ];\r\n  // Conductor: acceso directo a su modo conductor / perfil (no se pierde al\r\n  // quitar los servicios del cuerpo del perfil).\r\n  if (role === 'DRIVER') {\r\n    S1.push({ icon: requireIcon('CarTaxiFront'), label: 'Centro de conductor', route: '/conductor' });\r\n    S1.push({ icon: requireIcon('UserCog'), label: 'Perfil conductor', route: '/driver-profile' });\r\n  }\r\n  /**\r\n   * AGENTE DE CAJA: la fila aparece SOLO si el servidor dice que esta cuenta tiene\r\n   * perfil de agente ACTIVE (`GET /v1/agent/me`, parche 96). El rol del token no\r\n   * sirve para decidirlo: los JWT de la app son DRIVER/PASSENGER/ADMIN y nunca\r\n   * traen AGENT. El texto lleva el trabajo pendiente, para no abrir a ciegas.\r\n   */\r\n  if (agente) {\r\n    const trabajo = pendiente\r\n      ? (pendiente.cashIn ?? 0) + (pendiente.cashOut ?? 0) + (pendiente.pickups ?? 0) + (pendiente.deliveries ?? 0)\r\n      : 0;\r\n    S1.push({\r\n      icon: requireIcon('Wallet'),\r\n      label: trabajo > 0 ? `Panel de agente (${trabajo})` : 'Panel de agente',\r\n      route: '/agente',\r\n    });\r\n  }\r\n\r\n  /**\r\n   * DIVULGACIÓN PROGRESIVA (auditoría de diseño, Fase 1 · punto 1.13).\r\n   *\r\n   * El grupo «Servicios» llegaba a trece filas y los cuatro servicios que la gente usa a diario\r\n   * (taxi, comida, monedero, mercado) estaban repartidos por el medio: había que recorrer la lista\r\n   * entera para llegar a lo de todos los días. Ahora esos cuatro van siempre a la vista y el resto\r\n   * espera detrás de un botón que dice cuántos quedan.\r\n   *\r\n   * Las filas de ROL (centro de conductor, perfil conductor, panel de agente) NO se esconden\r\n   * nunca: quien las tiene las tiene por su trabajo, no por curiosidad, y esconderlas sería\r\n   * quitarle a un conductor su herramienta para reducir una lista.\r\n   */\r\n  const SIEMPRE_VISIBLES = new Set(['/taxi', '/food', '/monedero', '/ecomerse', '/conductor', '/driver-profile', '/agente']);\r\n  // Una fila sin `route` (acción en línea) no se esconde nunca: no sabemos si es de las de diario.\r\n  const visibles = verTodos ? S1 : S1.filter((i) => !i.route || SIEMPRE_VISIBLES.has(i.route));\r\n  const ocultos = S1.filter((i) => !!i.route && !SIEMPRE_VISIBLES.has(i.route));\r\n\r\n  /**\r\n   * «Mi perfil de Life Book» va EN SU PROPIO GRUPO, EL PRIMERO DEL MENÚ.\r\n   *\r\n   * Estaba enterrado y se midió en el aparato: primero hay que pasar «TUS NEGOCIOS (4)» —cuatro\r\n   * filas con su nota— y los diez servicios del grupo «Servicios», porque el orden de render es\r\n   * negocios → servicios → comercio. O sea **dos desplazamientos** para llegar a una puerta que\r\n   * el dueño pedía precisamente porque no se encontraba. Una puerta que no se ve no es una puerta.\r\n   *\r\n   * Abre el perfil PÚBLICO —el que ven los demás— con EL MISMO destino que el avatar de la barra\r\n   * de Life Book: las dos salen de `core/miPerfil`, para que no puedan separarse.\r\n   * Se llama «de Life Book» a propósito: la pestaña «Perfil» del dock lleva al perfil de CUENTA\r\n   * (`/profile`, identidad + negocios), y dos cosas distintas no pueden llamarse igual.\r\n   *\r\n   * El grupo se titula «TU CUENTA» y no repite el nombre de la fila para no quedar redundante.\r\n   */\r\n  const S0: Item[] = [\r\n    {\r\n      icon: requireIcon('UserRound'),\r\n      label: 'Mi perfil de Life Book',\r\n      action: () => {\r\n        onClose();\r\n        const destino = destinoMiPerfilLifeBook(cuenta);\r\n        /* NAVEGACIÓN SEGURA: si no se puede resolver el destino (sesión a medias), antes la\r\n           pulsación no hacía nada. Ahora se explica en vez de dejar el botón mudo. */\r\n        irSeguro.destino(destino, 'No se pudo leer tu perfil de Life Book.');\r\n      },\r\n    },\r\n  ];\r\n\r\n  const S2: Item[] = [\r\n    // «Abrir tienda» apuntaba a `/ecomerse-seller`, que es la pantalla VIEJA de comercio: el\r\n    // publicador real de Life Book es `/lifebook-sell` (producto, comida, servicio o alquiler).\r\n    // Y los seis «Próximamente» que había aquí ya no lo son: publicar, ver publicaciones y ver\r\n    // pedidos EXISTEN. Dejarlos como «Próximamente» era mentir al usuario sobre su propia app.\r\n    { icon: requireIcon('Store'), label: tieneNegocio ? 'Publicar en Life Book' : 'Abrir mi negocio', route: '/lifebook-sell' },\r\n    { icon: requireIcon('Package'), label: 'Mis publicaciones', route: '/lifebook-merchant-products' },\r\n    // La pantalla del CATÁLOGO (rejilla de dos columnas con precio, categorías con «Todo»\r\n    // primero, ciudad, orden y buscador) estaba entera y funcionando… y **no había ni un\r\n    // sitio en toda la app que la abriera**: era inalcanzable. Esta es su puerta.\r\n    // Se usa `LayoutGrid` y no `ShoppingBag` porque esa ya es la de «Ecomerse»: dos\r\n    // entradas distintas con el mismo icono se confunden.\r\n    { icon: requireIcon('LayoutGrid'), label: 'Catálogo de productos', route: '/lifebook-catalog' },\r\n    { icon: requireIcon('ShoppingCart'), label: 'Mis pedidos', route: '/lifebook-orders' },\r\n    { icon: requireIcon('Clapperboard'), label: 'Centro de creador', soon: true },\r\n    { icon: requireIcon('Handshake'), label: 'Colaboraciones', soon: true },\r\n  ];\r\n  const S3: Item[] = [\r\n    { icon: requireIcon('UserPlus'), label: 'Agregar amigo', soon: true },\r\n    { icon: requireIcon('StickyNote'), label: 'Mis borradores', soon: true },\r\n    { icon: requireIcon('CalendarDays'), label: 'Mis actividades', soon: true },\r\n    { icon: requireIcon('Clock'), label: 'Historial de visitas', soon: true },\r\n    { icon: requireIcon('Download'), label: 'Mis descargas', soon: true },\r\n    { icon: requireIcon('ScanLine'), label: 'Escanear', route: '/scanner' },\r\n  ];\r\n  const S4: Item[] = [\r\n    { icon: requireIcon('HelpCircle'), label: 'Ayuda y soporte', soon: true },\r\n    { icon: requireIcon('FileQuestion'), label: 'Preguntas frecuentes', soon: true },\r\n    { icon: requireIcon('Headset'), label: 'Contactar soporte', soon: true },\r\n  ];\r\n\r\n  const avatarSrc = userAvatar ? absUrl(userAvatar) : null;\r\n\r\n  const renderGroup = (title: string, items: Item[], dangerLast?: boolean) => (\r\n    <View key={title}>\r\n      <Text style={[styles.groupTitle, { color: colors.textSecondary }]}>{title}</Text>\r\n      <View style={[styles.groupCard, { backgroundColor: colors.card }]}>\r\n        {items.map((it, i) => {\r\n          const Icon = it.icon;\r\n          const last = dangerLast && i === items.length - 1;\r\n          return (\r\n            <Pressable\r\n              key={it.label}\r\n              onPress={it.action ?? (it.soon ? soon : () => go(it.route))}\r\n              style={({ pressed }) => [\r\n                styles.row,\r\n                { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' },\r\n                i > 0 && { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border },\r\n              ]}\r\n            >\r\n              <View style={[styles.rowIcon, { backgroundColor: last ? alpha(colors.danger, 0.1) : alpha(colors.primary, 0.08) }]}>\r\n                <Icon size={18} color={last ? colors.danger : colors.primary} />\r\n              </View>\r\n              <Text style={[styles.rowLabel, { color: last ? colors.danger : colors.textPrimary }]} numberOfLines={1}>\r\n                {it.label}\r\n              </Text>\r\n              {it.soon ? (\r\n                <Text style={[styles.soonBadge, { color: colors.secondary, backgroundColor: alpha(colors.secondary, 0.12) }]}>Próximamente</Text>\r\n              ) : (\r\n                <ChevronRight size={16} color={colors.textSecondary} />\r\n              )}\r\n            </Pressable>\r\n          );\r\n        })}\r\n      </View>\r\n    </View>\r\n  );\r\n\r\n  return (\r\n    <Modal visible={mounted} transparent animationType=\"none\" onRequestClose={onClose} statusBarTranslucent>\r\n      <View style={styles.overlay}>\r\n        {/* Backdrop atenuado: toque fuera cierra */}\r\n        <Animated.View style={[styles.backdrop, { backgroundColor: colors.overlay, opacity }]}>\r\n          <Pressable style={{ flex: 1 }} onPress={onClose} accessibilityLabel=\"Cerrar menú\" />\r\n        </Animated.View>\r\n\r\n        {/* Panel lateral derecho */}\r\n        <Animated.View style={[styles.panel, { transform: [{ translateX }], backgroundColor: colors.background, paddingTop: insets.top + 8 }]}>\r\n          {/* Cabecera compacta */}\r\n          <View style={[styles.header, { borderBottomColor: colors.border }]}>\r\n            <View style={[styles.headerAvatar, { backgroundColor: alpha(colors.primary, 0.14) }]}>\r\n              {avatarSrc ? (\r\n                <Image source={{ uri: avatarSrc }} style={styles.headerAvatarImg} />\r\n              ) : (\r\n                <Text style={[styles.headerAvatarTxt, { color: colors.primary }]}>\r\n                  {(userName || 'U').charAt(0).toUpperCase()}\r\n                </Text>\r\n              )}\r\n            </View>\r\n            <View style={{ flex: 1 }}>\r\n              <Text style={[styles.headerName, { color: colors.textPrimary }]} numberOfLines={1}>{userName}</Text>\r\n              <Text style={[styles.headerRole, { color: colors.textSecondary }]}>{roleLabel} · EG Route Plan</Text>\r\n            </View>\r\n            <Pressable onPress={onClose} hitSlop={10} accessibilityLabel=\"Cerrar menú\" style={styles.closeBtn}>\r\n              <X size={20} color={colors.textSecondary} />\r\n            </Pressable>\r\n          </View>\r\n\r\n          <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingBottom: espaciado.e12 }}>\r\n            {/* TU CUENTA, primero: la puerta a tu perfil de Life Book tiene que verse sin\r\n                desplazar. Antes iba en «Cuenta y actividad», dos desplazamientos más abajo. */}\r\n            {renderGroup('Tu cuenta', S0)}\r\n            {/* Los negocios del comerciante, ARRIBA: es lo que viene a hacer aquí. */}\r\n            {renderNegocios()}\r\n            {renderGroup('Servicios', visibles)}\r\n            {ocultos.length > 0 ? (\r\n              <Pressable\r\n                onPress={() => setVerTodos((v) => !v)}\r\n                accessibilityRole=\"button\"\r\n                accessibilityState={{ expanded: verTodos }}\r\n                accessibilityLabel={verTodos ? 'Ver menos servicios' : `Ver todos los servicios, ${ocultos.length} más`}\r\n                hitSlop={6}\r\n                style={({ pressed }) => [styles.verTodos, { opacity: pressed ? 0.6 : 1 }]}\r\n              >\r\n                <Text style={[styles.rowLabel, { color: colors.primary, textAlign: 'center' }]}>\r\n                  {verTodos ? 'Ver menos' : `Ver todos los servicios · ${ocultos.length}`}\r\n                </Text>\r\n              </Pressable>\r\n            ) : null}\r\n            {renderGroup('Comercio y creador', S2)}\r\n            {renderGroup('Cuenta y actividad', S3)}\r\n            {renderGroup('Soporte', S4)}\r\n            {/* Emergencia: fila roja separada (semántica estricta) */}\r\n            <Pressable\r\n              onPress={() => { onClose(); onEmergency(); }}\r\n              style={({ pressed }) => [styles.emergencyRow, { backgroundColor: pressed ? alpha(colors.danger, 0.12) : alpha(colors.danger, 0.07) }]}\r\n            >\r\n              <View style={[styles.rowIcon, { backgroundColor: alpha(colors.danger, 0.14) }]}>\r\n                {(() => { const Icon = requireIcon('Siren'); return <Icon size={18} color={colors.danger} />; })()}\r\n              </View>\r\n              <Text style={[styles.rowLabel, { color: colors.danger }]}>Emergencia</Text>\r\n              <ChevronRight size={16} color={colors.danger} />\r\n            </Pressable>\r\n          </ScrollView>\r\n\r\n          {/* Ajustes FIJO al pie → página independiente */}\r\n          <View style={[styles.footer, { borderTopColor: colors.border, paddingBottom: insets.bottom + 10 }]}>\r\n            <Pressable\r\n              onPress={() => go('/settings')}\r\n              style={({ pressed }) => [styles.settingsBtn, { backgroundColor: pressed ? alpha(colors.primary, 0.1) : colors.surface }]}\r\n            >\r\n              {(() => { const Icon = requireIcon('Settings'); return <Icon size={18} color={colors.textPrimary} />; })()}\r\n              <Text style={[styles.settingsTxt, { color: colors.textPrimary }]}>Ajustes</Text>\r\n              <ChevronRight size={16} color={colors.textSecondary} />\r\n            </Pressable>\r\n          </View>\r\n        </Animated.View>\r\n      </View>\r\n    </Modal>\r\n  );\r\n}\r\n\r\n/** Icons lucide importados estáticamente (Metro). */\r\nconst ICON_MAP: Record<string, LucideIcon> = {\r\n  Ticket, Briefcase, ShoppingBag, Utensils, Route, CarTaxiFront, History, KeyRound,\r\n  Wallet, Store, Clapperboard, BadgeCheck, Handshake, Package, Wrench, Sparkles,\r\n  UserPlus, UserRound, StickyNote, CalendarDays, Clock, Download, ShoppingCart,\r\n  ScanLine, HelpCircle, FileQuestion, Headset, Settings, Siren, UserCog, LayoutGrid,\r\n  // Verticales de «Tus negocios» (los añade core/useMisNegocios devolviendo el vertical).\r\n  BedDouble, UtensilsCrossed,\r\n};\r\nfunction requireIcon(name: string): LucideIcon {\r\n  return ICON_MAP[name];\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  overlay: { flex: 1, flexDirection: 'row' },\r\n  backdrop: { ...StyleSheet.absoluteFillObject },\r\n  panel: {\r\n    width: DRAWER_W, maxWidth: '88%', height: '100%', marginLeft: 'auto',\r\n    ...elevation.lg,\r\n  },\r\n  header: {\r\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\r\n    paddingHorizontal: espaciado.e14, paddingBottom: espaciado.e12, borderBottomWidth: StyleSheet.hairlineWidth,\r\n  },\r\n  headerAvatar: { width: 40, height: 40, borderRadius: 20, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },\r\n  headerAvatarImg: { width: '100%', height: '100%' },\r\n  headerAvatarTxt: { fontSize: 17, fontWeight: '900' },\r\n  headerName: { fontSize: 14.5, fontWeight: '800' },\r\n  headerRole: { fontSize: tipografia.micro, fontWeight: '600', marginTop: 1 },\r\n  closeBtn: { padding: espaciado.e4 },\r\n  groupTitle: { fontSize: tipografia.micro, fontWeight: '800', textTransform: 'uppercase', letterSpacing: 0.5, marginTop: espaciado.e14, marginBottom: espaciado.e6, paddingHorizontal: espaciado.e16 },\r\n  groupCard: { borderRadius: 14, overflow: 'hidden', marginHorizontal: espaciado.e10 },\r\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e11 },\r\n  rowIcon: { width: 30, height: 30, borderRadius: radios.sm, alignItems: 'center', justifyContent: 'center' },\r\n  rowLabel: { flex: 1, fontSize: tipografia.body, fontWeight: '700' },\r\n  /** Enlace de «ver todos los servicios» (divulgación progresiva del grupo Servicios). */\r\n  verTodos: { marginHorizontal: espaciado.e10, marginTop: espaciado.e6, paddingVertical: espaciado.e8, alignItems: 'center' },\r\n  soonBadge: { fontSize: 9.5, fontWeight: '800', paddingHorizontal: espaciado.e7, paddingVertical: espaciado.e2, borderRadius: 6, overflow: 'hidden' },\r\n  emergencyRow: {\r\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\r\n    marginHorizontal: espaciado.e10, marginTop: espaciado.e12, borderRadius: 14,\r\n    paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e11,\r\n  },\r\n  footer: { borderTopWidth: StyleSheet.hairlineWidth, paddingHorizontal: espaciado.e10, paddingTop: espaciado.e10 },\r\n  settingsBtn: {\r\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\r\n    borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e12,\r\n  },\r\n  settingsTxt: { flex: 1, fontSize: tipografia.body, fontWeight: '800' },\r\n});\r\n","/**\n * useSoyAgente — ¿ESTA CUENTA ES AGENTE DE CAJA? (una sola fuente de verdad)\n *\n * Igual que `useMisNegocios` para los comerciantes, esto decide el acceso al\n * panel del agente y sale en DOS sitios (el cajón de servicios ☰ y el perfil). Si\n * cada pantalla lo detectara por su cuenta, en dos semanas una lo sabría y la otra\n * no.\n *\n * Decisiones que no son obvias:\n *  · **Se pregunta al SERVIDOR, no al token**: el JWT de la app lleva roles de\n *    movilidad (DRIVER/PASSENGER/ADMIN) y NUNCA trae AGENT — el rol de agente de\n *    caja solo lo emite el login PIN del monedero. El backend resuelve el perfil\n *    por userId (`GET /v1/agent/me`, parche 96).\n *  · **Un fallo se traduce en «no es agente»**, nunca en una pantalla rota: si el\n *    servicio no contesta, el panel simplemente no aparece.\n *  · Devuelve también la CARGA pendiente, para que la fila del menú pueda decir\n *    cuánto trabajo hay esperando sin abrir nada.\n */\nimport { useEffect, useRef, useState } from 'react';\nimport { agentApi, type AgenteDeCaja, type CargaDeAgente } from '../api/agent';\n\nexport function useSoyAgente(cuenta?: string | null): {\n  agente: AgenteDeCaja | null;\n  pendiente: CargaDeAgente | null;\n  cargando: boolean;\n} {\n  const [agente, setAgente] = useState<AgenteDeCaja | null>(null);\n  const [pendiente, setPendiente] = useState<CargaDeAgente | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const vivo = useRef(true);\n\n  useEffect(() => {\n    vivo.current = true;\n    setCargando(true);\n    void (async () => {\n      try {\n        const r = await agentApi.me();\n        if (!vivo.current) return;\n        const activo = r?.agent && String(r.agent.status) === 'ACTIVE' ? r.agent : null;\n        setAgente(activo);\n        setPendiente(activo ? r.pending ?? null : null);\n      } catch {\n        if (vivo.current) { setAgente(null); setPendiente(null); }\n      } finally {\n        if (vivo.current) setCargando(false);\n      }\n    })();\n    return () => { vivo.current = false; };\n  }, [cuenta]);\n\n  return { agente, pendiente, cargando };\n}\n","/**\n * StatusEditorModal — publicar / cambiar / quitar el ESTADO 24H.\n * Contenido: selector de preset (emoji+etiqueta, filtrado por roles\n * verificados del usuario) → línea corta (máx 40) → imagen opcional (pickImage\n * con compresión ligera) → visibilidad (Todos/Seguidores/Solo yo) → enlace a\n * servicio (solo roles verificados) → Publicar / Quitar.\n * Nota fija: \"Visible durante 24 horas\".\n */\n\nimport React, { useEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator, Alert, Image, KeyboardAvoidingView, Modal, Platform, Pressable,\n  ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';import { Check, Clock, ImagePlus, Link2, Lock, Globe, Users, Trash2, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport type { UserStatus } from '../../api/status';\nimport { STATUS_TEXT_MAX, VISIBILITY_OPTIONS } from '../../constants/status';\nimport { statusBgColors } from '../../constants/status';\nimport { useStatusStore } from '../../state/statusStore';\nimport { pickImagesFromLibrary } from '../../core/pickImage';\nimport type { StatusPreset } from '../../api/status';\n\nconst LINK_LABEL: Record<string, string> = {\n  taxi: '🚕 Taxi',\n  intercity: '🛣️ Ciudad a Ciudad',\n  food: '🍽️ Mi restaurante',\n  ecomerse: '🛒 Mi tienda',\n  rental: '🏠 Mi anuncio',\n  work: '💼 Mi oferta',\n  lifebook: '📖 Life Book',\n};\n\nexport default function StatusEditorModal({\n  visible,\n  onClose,\n  onSaved,\n}: {\n  visible: boolean;\n  onClose: () => void;\n  onSaved?: (st: UserStatus) => void;\n}) {\n  const { colors } = useTheme();\n  const { presets, capabilities, status: currentStatus, publish, end, draft, saveDraft, clearDraft } = useStatusStore();\n\n  const [presetCode, setPresetCode] = useState('feeling_good');\n  const [text, setText] = useState('');\n  const [visibility, setVisibility] = useState<'public' | 'followers' | 'private'>('public');\n  const [linkType, setLinkType] = useState<string | null>(null);\n  const [photos, setPhotos] = useState<string[]>([]);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  // Al abrir: restaura borrador (si lo hay) o el estado ACTUAL (si existe) o\n  // valores por defecto. Las fotos del borrador se restauran; las del estado\n  // actual publicado no se reenvían (solo si el usuario elige otras).\n  useEffect(() => {\n    if (!visible) return;\n    setError(null); setBusy(false);\n    if (draft) {\n      setPresetCode(draft.presetCode);\n      setText(draft.text);\n      setVisibility(draft.visibility);\n      setPhotos(draft.mediaBase64s ?? []);\n      setLinkType(null);\n    } else if (currentStatus) {\n      setPresetCode(currentStatus.preset.code);\n      setText(currentStatus.text);\n      setVisibility(currentStatus.visibility);\n      setPhotos([]);\n      setLinkType(currentStatus.link?.type ?? null);\n    } else {\n      setText('');\n      setVisibility('public');\n      setPhotos([]);\n      setLinkType(null);\n    }\n  }, [visible, draft, currentStatus]);\n\n  // Presets permitidos según roles verificados del usuario.\n  const allowed = useMemo(() => {\n    const v = capabilities?.verified ?? [];\n    const base = capabilities?.role ?? 'PASSENGER';\n    const myRoles = [base, ...v];\n    return presets.filter((p) => {\n      const roles = p.roles ?? [];\n      if (!roles.length) return true;\n      return roles.some((r) => myRoles.includes(r) || r === 'PASSENGER');\n    });\n  }, [presets, capabilities]);\n\n  const preset = presets.find((p) => p.code === presetCode);\n  const [c1] = statusBgColors(preset?.bg ?? 'ocean');\n\n  /** Resuelve plantillas del preset ({ciudad}) con la ciudad del usuario. */\n  const labelFor = (p: StatusPreset) => {\n    const city = capabilities?.city ?? 'Malabo';\n    return String(p.label).replace(/\\{ciudad\\}/g, city).replace(/\\{zona\\}/g, city).replace(/\\{barrio\\}/g, city);\n  };\n\n  const MAX_PHOTOS = 4;\n  const pickImages = async () => {\n    try {\n      const remaining = MAX_PHOTOS - photos.length;\n      if (remaining <= 0) { Alert.alert('Límite', `Puedes añadir hasta ${MAX_PHOTOS} fotos.`); return; }\n      const imgs = await pickImagesFromLibrary(remaining);\n      const valid = imgs.filter((img) => img.dataUrl.length <= 4_000_000);\n      if (valid.length !== imgs.length) Alert.alert('Imagen grande', 'Alguna foto superaba ~3 MB y se omitió.');\n      setPhotos((prev) => [...prev, ...valid.map((i) => i.dataUrl)].slice(0, MAX_PHOTOS));\n    } catch {\n      Alert.alert('Error', 'No se pudo leer la imagen.');\n    }\n  };\n  const removePhoto = (idx: number) => setPhotos((prev) => prev.filter((_, i) => i !== idx));\n\n  const saveDraftNow = (pc = presetCode, tx = text, vis = visibility) => {\n    saveDraft({ presetCode: pc, text: tx, visibility: vis, mediaBase64s: photos }).catch(() => {});\n  };\n\n  const doPublish = async () => {\n    if (busy) return;\n    if (!presetCode) { setError('Elige un estado.'); return; }\n    setBusy(true); setError(null);\n    try {\n      const st = await publish({\n        presetCode,\n        text: text.trim().slice(0, STATUS_TEXT_MAX) || undefined,\n        media: photos.length ? photos : undefined,\n        visibility,\n        linkType: linkType ?? undefined,\n      });\n      await clearDraft();\n      onSaved?.(st);\n      onClose();\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo guardar el estado');\n      saveDraftNow();\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const doEnd = async () => {\n    if (busy) return;\n    Alert.alert('Quitar estado', '¿Quitar tu estado? Desaparecerá para todos.', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Quitar', style: 'destructive',\n        onPress: async () => {\n          setBusy(true); setError(null);\n          try {\n            await end();\n            await clearDraft();\n            onClose();\n          } catch (e) {\n            setError(e instanceof Error ? e.message : 'No se pudo quitar el estado');\n          } finally { setBusy(false); }\n        },\n      },\n    ]);\n  };\n\n  const showDraftPrompt = () => {\n    if (!draft) return;\n    Alert.alert('Borrador', 'Tienes un borrador sin publicar. ¿Continuar?', [\n      { text: 'Descartar', style: 'destructive', onPress: () => { clearDraft().catch(() => {}); setText(''); setPhotos([]); } },\n      { text: 'Continuar', style: 'default' },\n    ]);\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"slide\" onRequestClose={onClose} statusBarTranslucent>\n      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={[styles.backdrop, { backgroundColor: colors.overlay }]}>\n        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} />\n        <View style={[styles.card, { backgroundColor: colors.card, borderTopColor: colors.border }]}>\n          <View style={styles.header}>\n            <Text style={[styles.title, { color: colors.textPrimary }]}>Mi estado 24h</Text>\n            <Pressable onPress={onClose} hitSlop={12} accessibilityLabel=\"Cerrar\" style={styles.close}>\n              <X size={20} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n          <View style={styles.noteRow}>\n            <Clock size={13} color={colors.textSecondary} />\n            <Text style={[styles.note, { color: colors.textSecondary }]}>Visible durante 24 horas</Text>\n          </View>\n\n          <ScrollView showsVerticalScrollIndicator={false} keyboardShouldPersistTaps=\"handled\">\n            {/* Vista previa: con fotos → primera imagen COMPLETA (proporción\n                real) con la línea; sin fotos → emoji + línea. */}\n            {preset && (\n              <View style={[styles.previewWrap, { borderColor: alpha(c1, 0.4) }]}>\n                {photos[0] ? (\n                  <PreviewPhoto uri={photos[0]} />\n                ) : null}\n                <View style={[styles.preview, { backgroundColor: alpha(c1, 0.10) }]}>\n                  {!photos.length ? <Text style={styles.previewEmoji}>{preset.emoji}</Text> : null}\n                  <Text style={[styles.previewText, { color: colors.textPrimary }]} numberOfLines={2}>\n                    {text.trim() || labelFor(preset)}\n                  </Text>\n                  {photos.length ? (\n                    <Text style={[styles.previewBadge, { color: colors.textSecondary }]}>📷 {photos.length} foto{photos.length > 1 ? 's' : ''} se verá completa</Text>\n                  ) : null}\n                </View>\n              </View>\n            )}\n\n            {/* Selector de presets */}\n            <Text style={[styles.section, { color: colors.textSecondary }]}>QUÉ ESTÁS HACIENDO</Text>\n            <View style={styles.grid}>\n              {allowed.map((p) => {\n                const active = p.code === presetCode;\n                const [a, b] = statusBgColors(p.bg);\n                return (\n                  <Pressable\n                    key={p.code}\n                    onPress={() => { setPresetCode(p.code); saveDraftNow(p.code, text, visibility); }}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ checked: active }}\n                    accessibilityLabel={`${p.emoji} ${labelFor(p)}`}\n                    style={[styles.presetCell, { borderColor: active ? colors.primary : colors.border, backgroundColor: colors.surface }]}\n                  >\n                    <View style={[styles.presetEmojiWrap, { backgroundColor: active ? alpha(a, 0.16) : 'transparent' }]}>\n                      <Text style={styles.presetEmoji}>{p.emoji}</Text>\n                    </View>\n                    <Text style={[styles.presetLabel, { color: active ? colors.primary : colors.textPrimary }]} numberOfLines={2}>{labelFor(p)}</Text>\n                    {active && <Check size={12} color={colors.primary} style={styles.presetCheck} />}\n                  </Pressable>\n                );\n              })}\n            </View>\n            {allowed.length === 0 && (\n              <Text style={[styles.emptyHint, { color: colors.textSecondary }]}>No hay estados disponibles para tu perfil.</Text>\n            )}\n\n            {/* Línea corta */}\n            <Text style={[styles.section, { color: colors.textSecondary }]}>FRASE (OPCIONAL)</Text>\n            <TextInput\n              value={text}\n              onChangeText={(t) => { setText(t); saveDraftNow(presetCode, t, visibility); }}\n              maxLength={STATUS_TEXT_MAX}\n              placeholder=\"¿Qué estás haciendo?\"\n              placeholderTextColor={colors.textSecondary}\n              style={[styles.input, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n            />\n            <Text style={[styles.counter, { color: colors.textSecondary }]}>{text.length}/{STATUS_TEXT_MAX}</Text>\n\n            {/* Fotos opcionales (galería hasta 4) */}\n            <Text style={[styles.section, { color: colors.textSecondary }]}>FOTOS (HASTA {MAX_PHOTOS}, OPCIONAL)</Text>\n            <View style={styles.photoGrid}>\n              {photos.map((p, idx) => (\n                <View key={`${idx}-${p.slice(0, 12)}`} style={styles.photoCell}>\n                  <Image source={{ uri: p }} style={styles.imgThumb} />\n                  <Pressable onPress={() => removePhoto(idx)} accessibilityRole=\"button\" accessibilityLabel={`Quitar foto ${idx + 1}`} style={styles.removeImg}>\n                    <X size={13} color={brand.white} />\n                  </Pressable>\n                  {idx === 0 ? <Text style={styles.firstBadge}>1ª</Text> : null}\n                </View>\n              ))}\n              {photos.length < MAX_PHOTOS ? (\n                <Pressable onPress={pickImages} accessibilityRole=\"button\" accessibilityLabel=\"Añadir fotos\" style={[styles.addImg, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n                  <ImagePlus size={16} color={colors.textSecondary} />\n                  <Text style={[styles.addImgTxt, { color: colors.textSecondary }]}>Añadir {photos.length ? 'más' : 'fotos'}</Text>\n                </Pressable>\n              ) : null}\n            </View>\n\n            {/* Visibilidad */}\n            <Text style={[styles.section, { color: colors.textSecondary }]}>QUIÉN LO VE</Text>\n            <View style={styles.visWrap}>\n              {VISIBILITY_OPTIONS.map((o: { value: 'public' | 'followers' | 'private'; label: string; hint: string }) => {\n                const active = visibility === o.value;\n                const Icon = o.value === 'public' ? Globe : o.value === 'followers' ? Users : Lock;\n                return (\n                  <Pressable\n                    key={o.value}\n                    onPress={() => { setVisibility(o.value); saveDraftNow(presetCode, text, o.value); }}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ checked: active }}\n                    style={[styles.visRow, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? alpha(colors.primary, 0.07) : colors.surface }]}\n                  >\n                    <Icon size={16} color={active ? colors.primary : colors.textSecondary} />\n                    <View style={{ flex: 1 }}>\n                      <Text style={[styles.visLabel, { color: active ? colors.primary : colors.textPrimary }]}>{o.label}</Text>\n                      <Text style={[styles.visHint, { color: colors.textSecondary }]}>{o.hint}</Text>\n                    </View>\n                    {active && <Check size={14} color={colors.primary} />}\n                  </Pressable>\n                );\n              })}\n            </View>\n\n            {/* Enlace a servicio (roles verificados) */}\n            {capabilities && (capabilities.verified.length > 0 || capabilities.role === 'DRIVER') && (\n              <>\n                <Text style={[styles.section, { color: colors.textSecondary }]}>ENLAZAR SERVICIO (OPCIONAL)</Text>\n                <View style={styles.linkRow}>\n                  <Pressable onPress={() => setLinkType(null)} accessibilityRole=\"radio\" accessibilityState={{ checked: !linkType }} style={[styles.linkChip, { borderColor: !linkType ? colors.primary : colors.border, backgroundColor: !linkType ? alpha(colors.primary, 0.07) : colors.surface }]}>\n                    <Text style={[styles.linkTxt, { color: !linkType ? colors.primary : colors.textPrimary }]}>Sin enlace</Text>\n                  </Pressable>\n                  {capabilities.role === 'DRIVER' && (\n                    <Pressable onPress={() => setLinkType('taxi')} accessibilityRole=\"radio\" accessibilityState={{ checked: linkType === 'taxi' }} style={[styles.linkChip, { borderColor: linkType === 'taxi' ? colors.primary : colors.border, backgroundColor: linkType === 'taxi' ? alpha(colors.primary, 0.07) : colors.surface }]}>\n                      <Link2 size={13} color={linkType === 'taxi' ? colors.primary : colors.textSecondary} />\n                      <Text style={[styles.linkTxt, { color: linkType === 'taxi' ? colors.primary : colors.textPrimary }]}>🚕 Taxi</Text>\n                    </Pressable>\n                  )}\n                  {capabilities.verified.includes('SELLER') && (\n                    <Pressable onPress={() => setLinkType('ecomerse')} accessibilityRole=\"radio\" accessibilityState={{ checked: linkType === 'ecomerse' }} style={[styles.linkChip, { borderColor: linkType === 'ecomerse' ? colors.primary : colors.border, backgroundColor: linkType === 'ecomerse' ? alpha(colors.primary, 0.07) : colors.surface }]}>\n                      <Text style={[styles.linkTxt, { color: linkType === 'ecomerse' ? colors.primary : colors.textPrimary }]}>🛒 Mi tienda</Text>\n                    </Pressable>\n                  )}\n                  {capabilities.verified.includes('FOOD_OWNER') && (\n                    <Pressable onPress={() => setLinkType('food')} accessibilityRole=\"radio\" accessibilityState={{ checked: linkType === 'food' }} style={[styles.linkChip, { borderColor: linkType === 'food' ? colors.primary : colors.border, backgroundColor: linkType === 'food' ? alpha(colors.primary, 0.07) : colors.surface }]}>\n                      <Text style={[styles.linkTxt, { color: linkType === 'food' ? colors.primary : colors.textPrimary }]}>🍽️ Restaurante</Text>\n                    </Pressable>\n                  )}\n                  {capabilities.verified.includes('LANDLORD') && (\n                    <Pressable onPress={() => setLinkType('rental')} accessibilityRole=\"radio\" accessibilityState={{ checked: linkType === 'rental' }} style={[styles.linkChip, { borderColor: linkType === 'rental' ? colors.primary : colors.border, backgroundColor: linkType === 'rental' ? alpha(colors.primary, 0.07) : colors.surface }]}>\n                      <Text style={[styles.linkTxt, { color: linkType === 'rental' ? colors.primary : colors.textPrimary }]}>🏠 Alquiler</Text>\n                    </Pressable>\n                  )}\n                  {capabilities.verified.includes('RECRUITER') && (\n                    <Pressable onPress={() => setLinkType('work')} accessibilityRole=\"radio\" accessibilityState={{ checked: linkType === 'work' }} style={[styles.linkChip, { borderColor: linkType === 'work' ? colors.primary : colors.border, backgroundColor: linkType === 'work' ? alpha(colors.primary, 0.07) : colors.surface }]}>\n                      <Text style={[styles.linkTxt, { color: linkType === 'work' ? colors.primary : colors.textPrimary }]}>💼 Oferta</Text>\n                    </Pressable>\n                  )}\n                </View>\n                <Text style={[styles.linkHint, { color: colors.textSecondary }]}>\n                  {linkType ? `Quien lo vea podrá abrir ${LINK_LABEL[linkType] ?? 'el servicio'}.` : 'Tu estado puede abrir un servicio (solo roles verificados).'}\n                </Text>\n              </>\n            )}\n\n            {error && <Text style={[styles.error, { color: colors.danger }]}>{error}</Text>}\n\n            <Pressable\n              onPress={doPublish}\n              disabled={busy}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Publicar estado\"\n              style={({ pressed }) => [styles.saveBtn, { backgroundColor: colors.primary, opacity: busy || pressed ? 0.8 : 1 }]}\n            >\n              {busy ? <ActivityIndicator color={brand.white} size=\"small\" /> : <Text style={styles.saveTxt}>Publicar estado</Text>}\n            </Pressable>\n            <Pressable\n              onPress={doEnd}\n              disabled={busy}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Quitar estado\"\n              style={({ pressed }) => [styles.endBtn, { borderColor: colors.border, opacity: busy || pressed ? 0.7 : 1 }]}\n            >\n              <Trash2 size={14} color={colors.danger} />\n              <Text style={[styles.endTxt, { color: colors.danger }]}>Quitar mi estado actual</Text>\n            </Pressable>\n            <View style={{ height: 24 }} />\n          </ScrollView>\n        </View>\n      </KeyboardAvoidingView>\n    </Modal>\n  );\n}\n\n/**\n * PreviewPhoto — foto local del editor a tamaño REAL (sin recortar):\n * mide la proporción con Image.getSize y ajusta la altura al ancho.\n * Máx 420 px; si la imagen es muy alta se usa \"contain\" (nunca se recorta).\n */\nfunction PreviewPhoto({ uri }: { uri: string }) {\n  const [natural, setNatural] = useState<{ w: number; h: number } | null>(null);\n  const [boxW, setBoxW] = useState(0);\n  useEffect(() => {\n    let alive = true;\n    Image.getSize(\n      uri,\n      (w, h) => { if (alive && w > 0 && h > 0) setNatural({ w, h }); },\n      () => { if (alive) setNatural({ w: 4, h: 3 }); }, // fallback 4:3\n    );\n    return () => { alive = false; };\n  }, [uri]);\n  const MAX_H = 420;\n  let height = natural && boxW > 0 ? Math.max(100, Math.round(boxW * (natural.h / natural.w))) : 220;\n  const clamped = height > MAX_H;\n  if (clamped) height = MAX_H;\n  return (\n    <View\n      onLayout={(e) => { const w = e.nativeEvent.layout.width; if (w > 0) setBoxW(w); }}\n      style={[styles.previewPhotoBox, { height }]}\n    >\n      {natural ? (\n        <Image source={{ uri }} style={StyleSheet.absoluteFill} resizeMode={clamped ? 'contain' : 'cover'} />\n      ) : (\n        <View style={styles.previewPhotoLoading}><ActivityIndicator color=\"#8E8E93\" size=\"small\" /></View>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { flex: 1, justifyContent: 'flex-end' },\n  card: {\n    borderTopLeftRadius: 26, borderTopRightRadius: 26,\n    paddingHorizontal: espaciado.e18, paddingTop: espaciado.e14, paddingBottom: espaciado.e10,\n    maxHeight: '94%', borderTopWidth: 1,\n  },\n  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },\n  title: { fontSize: 19, fontWeight: '900' },\n  close: { width: 34, height: 34, borderRadius: 17, alignItems: 'center', justifyContent: 'center' },\n  noteRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginTop: espaciado.e2, marginBottom: espaciado.e10 },\n  note: { fontSize: tipografia.caption, fontWeight: '600' },\n  previewWrap: { borderRadius: 18, borderWidth: 1, overflow: 'hidden', marginBottom: espaciado.e10 },\n  preview: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n    padding: espaciado.e12, minHeight: 54,\n  },\n  previewPhotoBox: { width: '100%', overflow: 'hidden', backgroundColor: 'rgba(0,0,0,0.06)' },\n  previewPhotoLoading: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  previewEmoji: { fontSize: 26 },\n  previewBadge: { fontSize: 10.5, fontWeight: '700', marginLeft: 'auto' },\n  previewText: { flex: 1, fontSize: 15, fontWeight: '800' },\n  section: { fontSize: 10.5, fontWeight: '900', letterSpacing: 1, marginTop: espaciado.e14, marginBottom: espaciado.e8 },\n  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  presetCell: {\n    width: '31%', borderRadius: 14, borderWidth: 1.5, padding: espaciado.e8, alignItems: 'center',\n  },\n  presetEmojiWrap: { width: 44, height: 44, borderRadius: 14, alignItems: 'center', justifyContent: 'center' },\n  presetEmoji: { fontSize: 24 },\n  presetLabel: { fontSize: 10.5, fontWeight: '800', textAlign: 'center', marginTop: espaciado.e4 },\n  presetCheck: { position: 'absolute', top: 6, right: 6 },\n  emptyHint: { fontSize: tipografia.caption, fontStyle: 'italic' },\n  input: { borderWidth: 1, borderRadius: 14, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e10, fontSize: 15, fontWeight: '600' },\n  counter: { alignSelf: 'flex-end', fontSize: 10.5, marginTop: espaciado.e3 },\n  addImg: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, justifyContent: 'center',\n    borderWidth: 1, borderRadius: 14, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e12,\n  },\n  addImgTxt: { fontSize: tipografia.caption, fontWeight: '700' },\n  photoGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e10 },\n  photoCell: { position: 'relative' },\n  imgThumb: { width: 88, height: 88, borderRadius: 14 },\n  firstBadge: {\n    position: 'absolute', left: 6, bottom: 6, backgroundColor: 'rgba(0,0,0,0.6)',\n    color: brand.white, fontSize: 9, fontWeight: '900', borderRadius: 6,\n    paddingHorizontal: espaciado.e5, paddingVertical: 1, overflow: 'hidden',\n  },\n  removeImg: {\n    position: 'absolute', top: 4, right: 4,\n    width: 22, height: 22, borderRadius: 11,\n    backgroundColor: 'rgba(0,0,0,0.6)', alignItems: 'center', justifyContent: 'center',\n  },\n  visWrap: { gap: espaciado.e8 },\n  visRow: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10,\n    borderWidth: 1, borderRadius: 14, padding: espaciado.e11,\n  },\n  visLabel: { fontSize: tipografia.body, fontWeight: '800' },\n  visHint: { fontSize: tipografia.micro, marginTop: 1 },\n  linkRow: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  linkChip: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e5,\n    borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e7,\n  },\n  linkTxt: { fontSize: tipografia.caption, fontWeight: '800' },\n  linkHint: { fontSize: tipografia.micro, marginTop: espaciado.e6, fontStyle: 'italic' },\n  error: { fontSize: tipografia.caption, marginTop: espaciado.e10, fontWeight: '700' },\n  saveBtn: { borderRadius: radios.lg, paddingVertical: espaciado.e14, alignItems: 'center', justifyContent: 'center', marginTop: espaciado.e16 },\n  saveTxt: { color: brand.white, fontSize: 15.5, fontWeight: '900' },\n  endBtn: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e6,\n    borderRadius: radios.lg, borderWidth: 1, paddingVertical: espaciado.e11, marginTop: espaciado.e10,\n  },\n  endTxt: { fontSize: tipografia.body, fontWeight: '800' },\n});\n","/**\n * Stub de detalle de oferta promocional (navegación simulada).\n * Recibe /promo/bebidas, /promo/trabajos, /promo/alquileres.\n */\n\nimport React from 'react';\nimport { espaciado, tipografia } from '@egrouteplan/ui-kit';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport { PROMOS } from '../../constants/data';\nimport { alpha } from '../../constants/colors';\nimport { useTheme } from '../../theme/ThemeContext';\n\nexport default function PromoDetailStub() {\n  const { id } = useLocalSearchParams<{ id: string }>();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const promo = PROMOS.find((p) => p.id === id);\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top + 10 }]}>\n      <Pressable onPress={() => router.back()} style={styles.back} accessibilityLabel=\"Volver\">\n        <ArrowLeft size={22} color={colors.textPrimary} />\n      </Pressable>\n\n      <View style={[styles.hero, { backgroundColor: alpha(colors.secondary, 0.12), borderColor: alpha(colors.secondary, 0.35) }]}>\n        <Text style={styles.emoji}>{promo?.emoji ?? '🎁'}</Text>\n        <Text style={[styles.title, { color: colors.textPrimary }]}>{promo?.title ?? `Oferta ${id}`}</Text>\n        <Text style={[styles.subtitle, { color: colors.textSecondary }]}>{promo?.subtitle}</Text>\n      </View>\n\n      <Text style={[styles.note, { color: colors.textSecondary }]}>\n        Vista de oferta en construcción: aquí irá el detalle completo con\n        comercios asociados, condiciones y canje.\n      </Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1, paddingHorizontal: espaciado.e20 },\n  back: { width: 40, height: 40, justifyContent: 'center' },\n  hero: { marginTop: espaciado.e12, borderRadius: 20, borderWidth: 1, padding: espaciado.e22, alignItems: 'center' },\n  emoji: { fontSize: 46 },\n  title: { fontSize: tipografia.title, fontWeight: '800', marginTop: espaciado.e10, textAlign: 'center' },\n  subtitle: { fontSize: tipografia.body, marginTop: espaciado.e6, textAlign: 'center' },\n  note: { fontSize: tipografia.caption, lineHeight: 18, marginTop: espaciado.e18, textAlign: 'center' },\n});\n","/**\n * ReservaAnticipadaScreen — Reserva anticipada de vehículo (hasta +3 días).\n * FASE 3 rediseño DiDi (2026-09-04): flujo POR PASOS, una sola cosa por\n * pantalla (queja del dueño: la versión anterior saturaba origen+destino+\n * calendario de mes entero+precio+vehículo en un único scroll, con partes no\n * visibles). Ahora:\n *   Paso 1 · RUTA      (origen → destino)\n *   Paso 2 · COCHE Y HORARIO (día como chips Hoy/Mañana/+3 · hora · vehículo)\n *   Paso 3 · CONFIRMAR (resumen limpio: ruta, fecha, vehículo, precio +\n *                       presupuesto opcional y notas plegados)\n * Barra de progreso (3 puntos) arriba · CTA inferior único por paso.\n * Ruta Expo Router: /reserva\n *\n * Reglas conservadas: el día solo permite hoy..hoy+3; presupuesto opcional; Confirmar exige\n * origen+destino+día (vehículo con default eco).\n *\n * PRECIO (Fase 0 de la auditoría de diseño, D-35): esta pantalla presentaba como «precio estimado\n * por algoritmo» una cifra calculada a partir de la LONGITUD DEL TEXTO escrito en origen y\n * destino, bajo un icono «Seguro». Se retiró: un precio que no depende de la ruta no es un precio.\n * Ahora, o lo propone el usuario (presupuesto) o lo acuerda el conductor.\n */\n\nimport React, { useMemo, useState } from 'react';\nimport {\n  FlatList, KeyboardAvoidingView, Platform, Pressable, ScrollView,\n  StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useRouter } from 'expo-router';\nimport {\n  ArrowLeft, Bus, CalendarDays, Car, CarFront, CheckCircle2, Clock, MessageSquare,\n  Navigation, ShieldCheck, ChevronLeft, ChevronRight,\n} from 'lucide-react-native';\nimport { brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { reservaApi } from '../api/reserva';\nimport { useSession } from '../state/session';\n\n// ----------------------------- utilidades fecha -----------------------------\nconst startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\nconst fmt = (d: Date) => d.toISOString().slice(0, 10);\nconst weekdayShort = (d: Date) => d.toLocaleDateString('es', { weekday: 'short' });\nconst dayNum = (d: Date) => d.getDate();\nconst monthShort = (d: Date) => d.toLocaleDateString('es', { month: 'short' });\n\n// ------------------------------ datos de catálogo ---------------------------\nconst VEHICLES = [\n  { id: 'eco', name: 'Económico', desc: 'Cómodo y accesible', icon: CarFront },\n  { id: 'confort', name: 'Confort', desc: 'Mayor espacio', icon: Car },\n  { id: 'grande', name: 'Vehículo grande', desc: 'Ideal para grupos', icon: Bus },\n] as const;\n\nconst HOURS = Array.from({ length: 24 }, (_, i) => String(i).padStart(2, '0'));\nconst MINUTES = ['00', '15', '30', '45'];\n\n/** Estimación automática: 2000 XAF base + 200 XAF/km (service_fares RESERVA_COCHE). */\n/* (retirado en la Fase 0) `estimate(km)` inventaba un precio a partir de la longitud del texto. */\n\n/** Chips de día: Hoy, Mañana, y los siguientes (máx hoy+3). */\nfunction dayChipLabel(d: Date, today: Date): string {\n  const diff = Math.round((startOfDay(d).getTime() - startOfDay(today).getTime()) / 86400000);\n  if (diff === 0) return 'Hoy';\n  if (diff === 1) return 'Mañana';\n  return `${weekdayShort(d)} ${dayNum(d)}`;\n}\n\ntype Step = 1 | 2 | 3;\nconst STEPS: Step[] = [1, 2, 3];\n\nexport default function ReservaAnticipadaScreen() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const { isAuthenticated } = useSession();\n\n  const [step, setStep] = useState<Step>(1);\n  const [origin, setOrigin] = useState('');\n  const [dest, setDest] = useState('');\n\n  const [date, setDate] = useState<Date | null>(null);\n  const [timeH, setTimeH] = useState('09');\n  const [timeM, setTimeM] = useState('00');\n\n  const [budget, setBudget] = useState('');\n  const [vehicle, setVehicle] = useState<string>('eco');\n  const [notes, setNotes] = useState('');\n  const [submitting, setSubmitting] = useState(false);\n  const [booking, setBooking] = useState<{ id: string; scheduledAt: string; price: string } | null>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  const today = useMemo(() => startOfDay(new Date()), []);\n  const maxDay = useMemo(() => addDays(today, 3), [today]);\n  const dayOptions = useMemo(\n    () => [today, addDays(today, 1), addDays(today, 2), addDays(today, 3)],\n    [today],\n  );\n\n  const handleOriginChange = (t: string) => setOrigin(t);\n  const handleDestChange = (t: string) => setDest(t);\n\n  /** El precio NO se calcula aquí: es el presupuesto del usuario o se acuerda con el conductor. */\n  const budgetNum = budget ? Number(budget) : null;\n  const price = budgetNum ?? 0;\n\n  const routeReady = origin.trim().length > 0 && dest.trim().length > 0;\n  const scheduleReady = date !== null;\n  const canConfirm = routeReady && scheduleReady;\n\n  const vehicleName = VEHICLES.find((v) => v.id === vehicle)?.name ?? 'Económico';\n  const whenLabel = date\n    ? `${weekdayShort(date)} · ${dayNum(date)} ${monthShort(date)} · ${timeH}:${timeM}`\n    : 'Selecciona día y hora';\n\n  const onConfirm = async () => {\n    if (!canConfirm || submitting) return;\n    if (!isAuthenticated) { router.push('/auth'); return; }\n    setSubmitting(true);\n    setError(null);\n    try {\n      const scheduledAt = date ? `${fmt(date)}T${timeH}:${timeM}:00` : '';\n      const res = await reservaApi.reserve({\n        origin: origin.trim(),\n        dest: dest.trim(),\n        scheduledAt,\n        durationMin: 60,\n        budget: budgetNum ?? undefined,\n        vehicleType: vehicle,\n        notes: notes.trim() || undefined,\n      });\n      setBooking({ id: res.id, scheduledAt, price: String(res.estimated_price ?? price) });\n    } catch (e) {\n      const msg = e instanceof Error ? e.message : 'No se pudo crear la reserva';\n      setError(msg);\n    } finally {\n      setSubmitting(false);\n    }\n  };\n\n  // Navegación entre pasos (back contextual).\n  const goBack = () => {\n    if (step > 1) setStep((step - 1) as Step);\n    else router.back();\n  };\n\n  const s = styles(colors);\n\n  // ------------------------- PANTALLA CONFIRMADA ----------------------------\n  if (booking) {\n    return (\n      <View style={[s.root, { alignItems: 'center', justifyContent: 'center', padding: espaciado.e24 }]}>\n        <View style={[s.card, { alignItems: 'center', borderColor: colors.success, paddingVertical: espaciado.e28, width: '100%' }]}>\n          <CheckCircle2 size={52} color={colors.success} />\n          <Text style={{ fontSize: tipografia.title, fontWeight: '800', color: colors.textPrimary, marginTop: espaciado.e12 }}>Reserva confirmada</Text>\n          <Text style={{ fontSize: 15, color: colors.textSecondary, marginTop: espaciado.e8, textAlign: 'center' }}>{origin} → {dest}</Text>\n          <Text style={{ fontSize: tipografia.body, color: colors.textSecondary, marginTop: espaciado.e4 }}>{whenLabel}</Text>\n          <Text style={{ fontSize: 26, fontWeight: '800', color: colors.textPrimary, marginTop: espaciado.e14 }}>\n            {Number(booking.price).toLocaleString('es')} XAF\n          </Text>\n          <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e4 }}>Ref: {booking.id.slice(0, 8)}</Text>\n          <Pressable onPress={() => router.back()} style={[s.confirmBtn, { marginTop: espaciado.e20, paddingHorizontal: 48 }]}>\n            <Text style={s.confirmText}>Hecho</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <KeyboardAvoidingView style={[s.root, { backgroundColor: colors.background }]} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n      {/* BARRA SUPERIOR: back + título + seguridad */}\n      <View style={s.topBar}>\n        <Pressable onPress={goBack} hitSlop={12} style={s.iconBtn} accessibilityRole=\"button\" accessibilityLabel={step > 1 ? 'Paso anterior' : 'Volver'}>\n          {step > 1 ? <ChevronLeft size={22} color={colors.textPrimary} /> : <ArrowLeft size={22} color={colors.textPrimary} />}\n        </Pressable>\n        <View style={{ alignItems: 'center' }}>\n          <Text style={s.title}>Reservar viaje</Text>\n          {/* Progreso por pasos */}\n          <View style={s.stepsRow}>\n            {STEPS.map((n) => (\n              <View key={n} style={[s.stepDot, { backgroundColor: n <= step ? colors.primary : colors.border }]} />\n            ))}\n          </View>\n        </View>\n        <View style={[s.iconBtn, { alignItems: 'flex-end' }]}>\n          <ShieldCheck size={16} color={colors.success} />\n          <Text style={s.securityText}>Seguro</Text>\n        </View>\n      </View>\n\n      {error && (\n        <View style={[s.card, { marginHorizontal: espaciado.e16, borderColor: colors.danger }]}>\n          <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '600' }}>⚠️ {error}</Text>\n        </View>\n      )}\n\n      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ paddingTop: insets.top + 8, paddingBottom: insets.bottom + 120 }} keyboardShouldPersistTaps=\"handled\">\n        {/* ============================ PASO 1 · RUTA ============================ */}\n        {step === 1 && (\n          <View>\n            <Text style={s.stepTitle}>¿A dónde vas?</Text>\n            <View style={s.card}>\n              <View style={s.routeRow}>\n                <View style={s.routeRail}>\n                  <View style={[s.routeDot, { backgroundColor: colors.primary }]} />\n                  <View style={s.routeLine} />\n                  <View style={[s.routeDot, { backgroundColor: colors.secondary }]} />\n                </View>\n                <View style={{ flex: 1 }}>\n                  <View style={s.fieldRow}>\n                    <Navigation size={16} color={colors.primary} />\n                    <TextInput\n                      style={s.input}\n                      placeholder=\"Salida (ubicación actual…)\"\n                      placeholderTextColor={colors.textSecondary}\n                      value={origin}\n                      onChangeText={handleOriginChange}\n                    />\n                  </View>\n                  <View style={s.divider} />\n                  <View style={s.fieldRow}>\n                    <TextInput\n                      style={s.input}\n                      placeholder=\"Destino\"\n                      placeholderTextColor={colors.textSecondary}\n                      value={dest}\n                      onChangeText={handleDestChange}\n                    />\n                  </View>\n                </View>\n              </View>\n            </View>\n            <Text style={s.hint}>Reservas hasta 3 días después de hoy · Guinea Ecuatorial</Text>\n          </View>\n        )}\n\n        {/* ==================== PASO 2 · COCHE Y HORARIO ==================== */}\n        {step === 2 && (\n          <View>\n            <Text style={s.stepTitle}>Día y hora de recogida</Text>\n            {/* Día como chips (Hoy / Mañana / …+3) — patrón DiDi, sin calendario masivo */}\n            <View style={s.chipRow}>\n              {dayOptions.map((d) => {\n                const active = !!date && fmt(d) === fmt(date);\n                const label = dayChipLabel(d, today);\n                return (\n                  <Pressable\n                    key={fmt(d)}\n                    onPress={() => setDate(d)}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ selected: active }}\n                    style={[s.dayChip, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? alpha(colors.primary, 0.08) : colors.card }]}\n                  >\n                    <Text style={[s.dayChipText, { color: active ? colors.primary : colors.textPrimary }]}>{label}</Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n\n            {/* Hora (24 h) y minutos */}\n            <View style={[s.card, { marginTop: espaciado.e14 }]}>\n              <View style={s.sectionHeader}>\n                <Clock size={16} color={colors.primary} />\n                <Text style={s.sectionTitle}>Hora de recogida</Text>\n              </View>\n              <View style={{ flexDirection: 'row', gap: espaciado.e12 }}>\n                <View style={{ flex: 1 }}>\n                  <Text style={s.miniLabel}>Hora</Text>\n                  <FlatList\n                    horizontal\n                    data={HOURS}\n                    keyExtractor={(h) => h}\n                    showsHorizontalScrollIndicator={false}\n                    renderItem={({ item }) => (\n                      <Pressable onPress={() => setTimeH(item)} style={[s.chip, timeH === item && { backgroundColor: colors.primary, borderColor: colors.primary }]}>\n                        <Text style={[s.chipText, timeH === item && { color: brand.white }]}>{item}</Text>\n                      </Pressable>\n                    )}\n                  />\n                </View>\n                <View style={{ flex: 1 }}>\n                  <Text style={s.miniLabel}>Minuto</Text>\n                  <FlatList\n                    horizontal\n                    data={MINUTES}\n                    keyExtractor={(m) => m}\n                    showsHorizontalScrollIndicator={false}\n                    renderItem={({ item }) => (\n                      <Pressable onPress={() => setTimeM(item)} style={[s.chip, timeM === item && { backgroundColor: colors.primary, borderColor: colors.primary }]}>\n                        <Text style={[s.chipText, timeM === item && { color: brand.white }]}>{item}</Text>\n                      </Pressable>\n                    )}\n                  />\n                </View>\n              </View>\n              <Text style={s.pickSummary}>{whenLabel}</Text>\n            </View>\n\n            {/* Tipo de vehículo */}\n            <Text style={[s.sectionTitle, { marginTop: espaciado.e20, marginBottom: espaciado.e10 }]}>Tipo de vehículo</Text>\n            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e10, paddingHorizontal: espaciado.e16 }}>\n              {VEHICLES.map((v) => {\n                const Icon = v.icon;\n                const active = vehicle === v.id;\n                return (\n                  <Pressable\n                    key={v.id}\n                    onPress={() => setVehicle(v.id)}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ selected: active }}\n                    style={[s.vehicleCard, active && { borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.06) }]}\n                  >\n                    <Icon size={26} color={active ? colors.primary : colors.textSecondary} />\n                    <Text style={[s.vehicleName, { color: colors.textPrimary }]}>{v.name}</Text>\n                    <Text style={s.vehicleDesc}>{v.desc}</Text>\n                  </Pressable>\n                );\n              })}\n            </ScrollView>\n          </View>\n        )}\n\n        {/* ======================== PASO 3 · CONFIRMAR ======================== */}\n        {step === 3 && (\n          <View style={{ paddingHorizontal: espaciado.e16 }}>\n            <Text style={s.stepTitle}>Confirma tu reserva</Text>\n\n            {/* Resumen ruta */}\n            <View style={s.card}>\n              <View style={s.routeRow}>\n                <View style={s.routeRail}>\n                  <View style={[s.routeDot, { backgroundColor: colors.primary }]} />\n                  <View style={s.routeLine} />\n                  <View style={[s.routeDot, { backgroundColor: colors.secondary }]} />\n                </View>\n                <View style={{ flex: 1 }}>\n                  <Text style={s.sumLine}>{origin || 'Origen'}</Text>\n                  <Text style={[s.sumLine, { marginTop: espaciado.e6 }]}>{dest || 'Destino'}</Text>\n                </View>\n              </View>\n            </View>\n\n            {/* Resumen horario + vehículo */}\n            <View style={s.card}>\n              <Row icon={<CalendarDays size={15} color={colors.textSecondary} />} text={whenLabel} />\n              <Row icon={<Car size={15} color={colors.textSecondary} />} text={vehicleName} />\n            </View>\n\n            {/* Precio: el del usuario o «a convenir». NO se inventa. */}\n            <View style={s.card}>\n              <Text style={s.label}>{price > 0 ? 'Tu presupuesto' : 'Precio'}</Text>\n              <Text style={s.priceBig} accessibilityLabel={price > 0 ? `${price} francos CFA` : 'A convenir con el conductor'}>\n                {price > 0 ? `${price.toLocaleString('es')} XAF` : 'A convenir'}\n              </Text>\n              <Text style={s.miniLabel}>El conductor confirma el precio al aceptar. La app no lo estima.</Text>\n            </View>\n\n            {/* Presupuesto deseado (opcional) */}\n            <View style={s.card}>\n              <Text style={s.label}>Mi presupuesto deseado (opcional)</Text>\n              <View style={[s.budgetRow, budgetNum !== null && { borderColor: colors.secondary }]}>\n                <TextInput\n                  style={[s.budgetInput, budgetNum !== null && { color: colors.secondary }]}\n                  placeholder=\"Escribe tu presupuesto\"\n                  placeholderTextColor={colors.textSecondary}\n                  keyboardType=\"number-pad\"\n                  value={budget}\n                  onChangeText={setBudget}\n                />\n                <Text style={[s.currencyTag, budgetNum !== null && { color: colors.secondary }]}>XAF</Text>\n              </View>\n            </View>\n\n            {/* Notas (opcional) */}\n            <View style={s.card}>\n              <View style={s.sectionHeader}>\n                <MessageSquare size={15} color={colors.textSecondary} />\n                <Text style={s.sectionTitle}>Notas para el conductor (opcional)</Text>\n              </View>\n              <TextInput\n                style={[s.input, { borderTopWidth: 1, borderTopColor: colors.border, paddingTop: espaciado.e10 }]}\n                placeholder=\"llevar maletas, punto exacto de parada…\"\n                placeholderTextColor={colors.textSecondary}\n                value={notes}\n                onChangeText={setNotes}\n              />\n            </View>\n          </View>\n        )}\n      </ScrollView>\n\n      {/* CTA inferior único por paso */}\n      <View style={s.footer}>\n        {step === 1 && (\n          <Pressable\n            disabled={!routeReady}\n            onPress={() => setStep(2)}\n            style={[s.confirmBtn, !routeReady && { backgroundColor: colors.textSecondary, opacity: 0.5 }]}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Continuar\"\n          >\n            <Text style={s.confirmText}>Continuar</Text>\n            <Text style={[s.confirmSub, { color: 'rgba(255,255,255,0.85)' }]}>Elige día y vehículo</Text>\n          </Pressable>\n        )}\n        {step === 2 && (\n          <Pressable\n            disabled={!scheduleReady}\n            onPress={() => setStep(3)}\n            style={[s.confirmBtn, !scheduleReady && { backgroundColor: colors.textSecondary, opacity: 0.5 }]}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Continuar\"\n          >\n            <Text style={s.confirmText}>Continuar</Text>\n            <Text style={[s.confirmSub, { color: 'rgba(255,255,255,0.85)' }]}>Revisa el precio</Text>\n          </Pressable>\n        )}\n        {step === 3 && (\n          <Pressable\n            disabled={!canConfirm || submitting}\n            onPress={onConfirm}\n            style={[s.confirmBtn, (!canConfirm || submitting) && { backgroundColor: colors.textSecondary, opacity: 0.5 }]}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Confirmar reserva\"\n          >\n            <Text style={s.confirmText}>{submitting ? 'Procesando…' : price > 0 ? `Confirmar · ${price.toLocaleString('es')} XAF` : 'Confirmar reserva'}</Text>\n            <Text style={[s.confirmSub, { color: 'rgba(255,255,255,0.85)' }]}>Tu ruta con seguridad</Text>\n          </Pressable>\n        )}\n      </View>\n    </KeyboardAvoidingView>\n  );\n}\n\nfunction Row({ icon, text }: { icon: React.ReactNode; text: string }) {\n  const { colors } = useTheme();\n  return (\n    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e6 }}>\n      {icon}\n      <Text style={{ flex: 1, fontSize: tipografia.body, color: colors.textPrimary, fontWeight: '600' }}>{text}</Text>\n    </View>\n  );\n}\n\nfunction alpha(hex: string, opacity: number): string {\n  const h = hex.replace('#', '');\n  const r = parseInt(h.slice(0, 2), 16);\n  const g = parseInt(h.slice(2, 4), 16);\n  const b = parseInt(h.slice(4, 6), 16);\n  return `rgba(${r}, ${g}, ${b}, ${opacity})`;\n}\n\n// ------------------------------- estilos ------------------------------------\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    root: { flex: 1 },\n    topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingTop: espaciado.e14, paddingBottom: espaciado.e6 },\n    iconBtn: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, minWidth: 64 },\n    title: { fontSize: 17, fontWeight: '800', color: c.textPrimary },\n    stepsRow: { flexDirection: 'row', gap: espaciado.e5, marginTop: espaciado.e4 },\n    stepDot: { width: 18, height: 4, borderRadius: 2 },\n    securityText: { fontSize: 10, color: c.success, fontWeight: '700' },\n\n    stepTitle: { fontSize: tipografia.title, fontWeight: '800', color: c.textPrimary, marginHorizontal: espaciado.e16, marginTop: espaciado.e8, marginBottom: espaciado.e12 },\n    card: { backgroundColor: c.card, borderRadius: radios.lg, padding: espaciado.e14, marginHorizontal: espaciado.e16, marginBottom: espaciado.e12, borderWidth: 1, borderColor: c.border, shadowColor: c.shadow, shadowOpacity: 0.05, shadowRadius: 8, shadowOffset: { width: 0, height: 3 }, elevation: 1 },\n    routeRow: { flexDirection: 'row', gap: espaciado.e12 },\n    routeRail: { alignItems: 'center', width: 10 },\n    routeDot: { width: 10, height: 10, borderRadius: 5 },\n    routeLine: { width: 2, flex: 1, backgroundColor: c.border, marginVertical: espaciado.e2 },\n    fieldRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e10 },\n    input: { flex: 1, fontSize: 15, color: c.textPrimary, padding: 0 },\n    divider: { height: 1, backgroundColor: c.border },\n    sumLine: { fontSize: 15, fontWeight: '700', color: c.textPrimary },\n\n    chipRow: { flexDirection: 'row', gap: espaciado.e8, paddingHorizontal: espaciado.e16 },\n    dayChip: { flex: 1, alignItems: 'center', borderWidth: 1.5, borderRadius: radios.md, paddingVertical: espaciado.e12 },\n    dayChipText: { fontSize: tipografia.body, fontWeight: '800' },\n\n    sectionHeader: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e6, marginBottom: espaciado.e8 },\n    sectionTitle: { fontSize: tipografia.body, fontWeight: '700', color: c.textPrimary },\n    label: { fontSize: tipografia.caption, fontWeight: '700', color: c.textSecondary, marginBottom: espaciado.e6 },\n\n    chip: { paddingHorizontal: espaciado.e11, paddingVertical: espaciado.e8, borderRadius: radios.full, borderWidth: 1, borderColor: c.border, marginRight: espaciado.e6, backgroundColor: c.background },\n    chipText: { fontSize: tipografia.body, color: c.textPrimary, fontWeight: '700' },\n    miniLabel: { fontSize: tipografia.micro, color: c.textSecondary, marginBottom: espaciado.e4 },\n    pickSummary: { fontSize: tipografia.body, fontWeight: '800', color: c.primary, marginTop: espaciado.e12 },\n\n    vehicleCard: { width: 124, padding: espaciado.e14, borderRadius: radios.lg, borderWidth: 1.5, borderColor: c.border, backgroundColor: c.card, alignItems: 'center', gap: espaciado.e6 },\n    vehicleName: { fontSize: tipografia.body, fontWeight: '800', textAlign: 'center' },\n    vehicleDesc: { fontSize: tipografia.micro, color: c.textSecondary, textAlign: 'center' },\n\n    priceBig: { fontSize: tipografia.display, fontWeight: '800', color: c.textPrimary },\n    budgetRow: { flexDirection: 'row', alignItems: 'center', borderWidth: 1, borderColor: c.border, borderRadius: radios.md, paddingHorizontal: espaciado.e12, marginTop: espaciado.e6 },\n    budgetInput: { flex: 1, fontSize: 15, color: c.textPrimary, paddingVertical: espaciado.e10 },\n    currencyTag: { fontSize: tipografia.body, fontWeight: '800', color: c.textSecondary },\n\n    hint: { textAlign: 'center', fontSize: tipografia.caption, color: c.textSecondary, marginTop: espaciado.e10, paddingHorizontal: espaciado.e24, lineHeight: 16 },\n\n    footer: { position: 'absolute', left: 16, right: 16, bottom: 24 },\n    confirmBtn: { backgroundColor: c.primary, borderRadius: radios.full, paddingVertical: 15, alignItems: 'center' },\n    confirmText: { fontSize: 16.5, fontWeight: '800', color: brand.white },\n    confirmSub: { fontSize: tipografia.micro, marginTop: espaciado.e2 },\n  });\n","/**\n * Cliente de reserva anticipada de vehículo (backend unificado NestJS).\n * Endpoint: /mobility/trips/reserve (vía httpClient con sesión de la app).\n */\n\nimport { http, ApiError } from './httpClient';\n\nexport { ApiError };\n\nexport interface ReservePayload {\n  userId?: string;\n  origin?: string;\n  dest?: string;\n  pickupLat?: number;\n  pickupLng?: number;\n  dropoffLat?: number;\n  dropoffLng?: number;\n  scheduledAt: string;\n  durationMin?: number;\n  estimatedPrice?: number;\n  budget?: number;\n  vehicleType?: string;\n  notes?: string;\n}\n\nexport interface Reservation {\n  id: string;\n  scheduled_at: string;\n  status: string;\n  estimated_price: number | string;\n}\n\nexport const reservaApi = {\n  reserve: (body: ReservePayload) =>\n    http.post<Reservation>('/mobility/trips/reserve', body),\n};\n","/**\n * Stub del escáner/traductor de documentos a español (botón MapTools).\n * La producción usará expo-camera + OCR; aquí queda el punto de entrada.\n */\n\nimport React from 'react';\nimport { espaciado, tipografia } from '@egrouteplan/ui-kit';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, ScanLine } from 'lucide-react-native';\nimport { alpha } from '../constants/colors';\nimport { useTheme } from '../theme/ThemeContext';\n\nexport default function ScannerStub() {\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top + 10 }]}>\n      <Pressable onPress={() => router.back()} style={styles.back} accessibilityLabel=\"Volver\">\n        <ArrowLeft size={22} color={colors.textPrimary} />\n      </Pressable>\n      <View style={[styles.frame, { borderColor: colors.primary, backgroundColor: alpha(colors.primary, 0.06) }]}>\n        <ScanLine size={44} color={colors.primary} />\n        <Text style={[styles.title, { color: colors.textPrimary }]}>Escáner de documentos</Text>\n        <Text style={[styles.note, { color: colors.textSecondary }]}>\n          Apunta la cámara al documento para traducirlo a español.\n          (Implementación con expo-camera + OCR en la siguiente iteración.)\n        </Text>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1, paddingHorizontal: espaciado.e20 },\n  back: { width: 40, height: 40, justifyContent: 'center' },\n  frame: { marginTop: espaciado.e24, borderRadius: 24, borderWidth: 1.5, borderStyle: 'dashed', padding: espaciado.e30, alignItems: 'center' },\n  title: { fontSize: 18, fontWeight: '800', marginTop: espaciado.e14 },\n  note: { fontSize: tipografia.caption, lineHeight: 18, marginTop: espaciado.e8, textAlign: 'center' },\n});\n","/**\n * Stub de detalle de servicio (navegación simulada).\n * Recibe /service/taxi, /service/paquete, /service/buscar?q=…, etc.\n * Listo para conectar con el backend mobility (schema mobility).\n */\n\nimport React from 'react';\nimport { espaciado, tipografia } from '@egrouteplan/ui-kit';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft } from 'lucide-react-native';\nimport { SERVICES } from '../../constants/data';\nimport { useTheme } from '../../theme/ThemeContext';\n\nexport default function ServiceDetailStub() {\n  const { id, q } = useLocalSearchParams<{ id: string; q?: string }>();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { colors } = useTheme();\n\n  const service = SERVICES.find((s) => s.id === id);\n  const title = service?.label ?? (id === 'buscar' ? 'Buscar destino' : `Servicio ${id}`);\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background, paddingTop: insets.top + 10 }]}>\n      <Pressable onPress={() => router.back()} style={styles.back} accessibilityLabel=\"Volver\">\n        <ArrowLeft size={22} color={colors.textPrimary} />\n      </Pressable>\n      <Text style={[styles.title, { color: colors.textPrimary }]}>{title}</Text>\n      {!!q && (\n        <Text style={[styles.query, { color: colors.textSecondary }]}>Destino: “{q}”</Text>\n      )}\n      <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n        <Text style={[styles.cardText, { color: colors.textSecondary }]}>\n          Vista de detalle en construcción. Aquí irá el flujo de “{title}”\n          conectado al backend de movilidad (schema mobility, tabla service_orders).\n        </Text>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1, paddingHorizontal: espaciado.e20 },\n  back: { width: 40, height: 40, justifyContent: 'center' },\n  title: { fontSize: 24, fontWeight: '800', marginTop: espaciado.e8 },\n  query: { fontSize: tipografia.body, marginTop: espaciado.e4 },\n  card: { marginTop: espaciado.e20, borderRadius: 18, borderWidth: 1, padding: espaciado.e18 },\n  cardText: { fontSize: tipografia.body, lineHeight: 19 },\n});\n","/**\n * SettingsScreen — página independiente de AJUSTES (/settings).\n * Se abre desde la barra del Perfil o el drawer ☰. NUNCA lista de ajustes\n * inline en el perfil. Grupos: Apariencia · Idioma · Documentos (según rol,\n * → /documents) · Soporte · Sesión.\n */\n\nimport React, { useEffect, useState } from 'react';\nimport {\n  Alert, Modal, Pressable, ScrollView, StyleSheet, Switch, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { SOPORTE, escribirASoporte, whatsappSoporte, llamarASoporte } from '../constants/soporte';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowLeft, Ban, Bell, Check, ChevronRight, Clock, Eye, FileWarning, Flag, Globe, Headset,\n  HelpCircle, Languages, LogOut, Mail, MapPin, Moon, Phone, Siren, Type, X,\n} from 'lucide-react-native';\nimport { alpha, brand, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { Volver } from '../components/Volver';\nimport { AuthGate } from '../core/AuthGate';\nimport { useSession } from '../state/session';\nimport { authApi, type MeProfile } from '../api/auth';\nimport { lifebookSettingsApi, type LbSettings } from '../api/lifebook';\nimport { LB_CITIES, LB_NOTIF_ROWS, LB_PRIVACY_KEYS, LB_VIS_LABEL } from '../constants/lifebook';\nimport EmergencyModal from '../components/EmergencyModal';\nimport { formaHoja } from '../components/lifebook/ui/Sheet';\n\nexport default function SettingsScreen() {\n  return (\n    <AuthGate>\n      <SettingsContent />\n    </AuthGate>\n  );\n}\n\nconst LANG_OPTIONS = [\n  { code: 'es-GQ', label: 'Español (Guinea Ecuatorial)' },\n  { code: 'fr', label: 'Francés' },\n  { code: 'pt', label: 'Portugués' },\n  { code: 'fang', label: 'Fang' },\n  { code: 'bubi', label: 'Bubi' },\n];\n\nfunction SettingsContent() {\n  const { colors, isDark, setMode } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { logout } = useSession();\n  const [profile, setProfile] = useState<MeProfile | null>(null);\n  const [langOpen, setLangOpen] = useState(false);\n  const [lang, setLang] = useState('es-GQ');\n  const [fontOpen, setFontOpen] = useState(false);\n  const [fontSize, setFontSize] = useState('Normal');\n  const [notifOpen, setNotifOpen] = useState(false);\n  const [notif, setNotif] = useState('Activadas');\n  const [emergencyOpen, setEmergencyOpen] = useState(false);\n  const [confirmLogout, setConfirmLogout] = useState(false);\n  const [lb, setLb] = useState<LbSettings | null>(null);\n  const [lbPick, setLbPick] = useState<null | { title: string; group: 'privacy' | 'publish'; key: string; options: Array<{ label: string; value: string }>; current: string }>(null);\n  const [cityOpen, setCityOpen] = useState(false);\n\n  useEffect(() => {\n    authApi.me().then(setProfile).catch(() => {});\n    lifebookSettingsApi.get().then(setLb).catch(() => {});\n  }, []);\n\n  const lbSave = (group: 'privacy' | 'publish' | 'notifications' | 'content', patch: Record<string, unknown>) => {\n    setLb((prev) => {\n      if (!prev) return prev;\n      const curGroup = (prev as unknown as Record<string, Record<string, unknown>>)[group] ?? {};\n      return { ...prev, [group]: { ...curGroup, ...patch } } as LbSettings;\n    });\n    lifebookSettingsApi.patch({ [group]: patch } as never).catch(() => {\n      Alert.alert('Ajustes de Life Book', 'No se pudo guardar. Inténtalo de nuevo.');\n      lifebookSettingsApi.get().then(setLb).catch(() => {});\n    });\n  };\n\n  const openPrivacyPick = (key: string, label: string, nobody: boolean) => {\n    const values = key === 'location' || key === 'email'\n      ? ['public', 'followers', 'nobody']\n      : key === 'messages'\n        ? ['public', 'followers', 'private', 'nobody']\n        : ['public', 'followers', 'private'];\n    const current = (lb?.privacy as Record<string, string> | undefined)?.[key] ?? 'public';\n    setLbPick({\n      title: label, group: 'privacy', key,\n      options: values.filter((v) => v !== 'nobody' || nobody).map((v) => ({ label: LB_VIS_LABEL[v] ?? v, value: v })),\n      current,\n    });\n  };\n\n  const roleLabel = profile?.role === 'DRIVER' ? 'Conductor' : profile?.role === 'ADMIN' ? 'Administrador' : 'Pasajero';\n\n  const doLogout = async () => {\n    await logout();\n    router.replace('/');\n  };\n\n  const selectSheet = (title: string, options: string[], current: string, onPick: (o: string) => void, onClose: () => void, allowAll = true, visible = false) => (\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\n      <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={onClose} />\n      <View style={[styles.sheetCard, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n        <View style={styles.sheetHeader}>\n          <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>{title}</Text>\n          <Pressable onPress={onClose} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\n        </View>\n        {options.map((o) => {\n          const active = o === current;\n          return (\n            <Pressable\n              key={o}\n              onPress={() => { onPick(o); onClose(); }}\n              disabled={!allowAll && !active}\n              style={({ pressed }) => [styles.sheetRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n            >\n              <Text style={[styles.sheetRowTxt, { color: active ? colors.primary : colors.textPrimary }]}>{o}</Text>\n              {active ? <Check size={18} color={colors.primary} /> : (!allowAll ? <Text style={{ color: colors.textSecondary, fontSize: 10, fontWeight: '700' }}>Próximamente</Text> : null)}\n            </Pressable>\n          );\n        })}\n      </View>\n    </Modal>\n  );\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background }]}>\n      {/* Cabecera */}\n      <View style={[styles.topBar, { borderBottomColor: colors.border }]}>\n        <Volver />\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Ajustes</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <ScrollView contentContainerStyle={[styles.content, { paddingBottom: insets.bottom + 24 }]} showsVerticalScrollIndicator={false}>\n        {/* APARIENCIA */}\n        <Text style={styles.groupTitle}>Apariencia</Text>\n        <View style={[styles.group, { backgroundColor: colors.card }]}>\n          <Row\n            icon={Moon}\n            label=\"Tema oscuro\"\n            right={<Switch value={isDark} onValueChange={(v) => setMode(v ? 'dark' : 'light')} trackColor={{ true: colors.primary }} accessibilityLabel=\"Tema oscuro\" />}\n            hint={isDark ? 'Activado' : 'Desactivado'}\n          />\n          <Row icon={Type} label=\"Tamaño de texto\" hint={fontSize} onPress={() => setFontOpen(true)} />\n          <Row icon={Bell} label=\"Notificaciones visuales\" hint={notif} onPress={() => setNotifOpen(true)} last />\n        </View>\n\n        {/* IDIOMA */}\n        <Text style={styles.groupTitle}>Idioma</Text>\n        <View style={[styles.group, { backgroundColor: colors.card }]}>\n          <Row icon={Languages} label=\"Idioma\" hint={LANG_OPTIONS.find((l) => l.code === lang)?.label} onPress={() => setLangOpen(true)} last />\n        </View>\n\n        {/* DOCUMENTOS según rol → /documents */}\n        <Text style={styles.groupTitle}>{`Documentos · ${roleLabel}`}</Text>\n        <View style={[styles.group, { backgroundColor: colors.card }]}>\n          <Row\n            icon={FileWarning}\n            label=\"Mis documentos\"\n            hint={profile ? `${roleLabel} · estados y vencimientos` : ''}\n            onPress={() => router.push('/documents' as any)}\n            last\n          />\n        </View>\n\n        {/* ESTADO 24H → /status */}\n        <Text style={styles.groupTitle}>Estado 24h</Text>\n        <View style={[styles.group, { backgroundColor: colors.card }]}>\n          <Row\n            icon={Clock}\n            label=\"Mi estado 24h\"\n            hint=\"Publicar, cambiar y ajustes\"\n            onPress={() => router.push('/status' as any)}\n            last\n          />\n        </View>\n\n        {/* LIFE BOOK — ajustes del módulo */}\n        {lb && (\n          <>\n            <Text style={styles.groupTitle}>Life Book · Privacidad</Text>\n            <View style={[styles.group, { backgroundColor: colors.card }]}>\n              {LB_PRIVACY_KEYS.map((p, i) => {\n                const val = (lb.privacy as Record<string, string>)[p.key] ?? 'public';\n                return (\n                  <Row\n                    key={p.key}\n                    icon={Eye}\n                    label={p.label}\n                    hint={LB_VIS_LABEL[val] ?? val}\n                    onPress={() => openPrivacyPick(p.key, p.label, p.nobody)}\n                    last={i === LB_PRIVACY_KEYS.length - 1}\n                  />\n                );\n              })}\n            </View>\n            <Text style={styles.groupTitle}>Life Book · Notificaciones</Text>\n            <View style={[styles.group, { backgroundColor: colors.card }]}>\n              {LB_NOTIF_ROWS.map((n, i) => {\n                const on = !!((lb.notifications as Record<string, boolean>)[n.key]);\n                return (\n                  <Row\n                    key={n.key}\n                    icon={Bell}\n                    label={n.label}\n                    hint={on ? 'Activado' : 'Apagado'}\n                    last={i === LB_NOTIF_ROWS.length - 1}\n                    right={<Switch value={on} onValueChange={(v) => lbSave('notifications', { [n.key]: v })} trackColor={{ true: colors.primary }} accessibilityLabel={n.label} />}\n                  />\n                );\n              })}\n            </View>\n            <Text style={styles.groupTitle}>Life Book · Contenido</Text>\n            <View style={[styles.group, { backgroundColor: colors.card }]}>\n              <Row\n                icon={Eye}\n                label=\"Filtro de contenido sensible\"\n                hint={lb.content.sensitiveFilter ? 'Activado' : 'Apagado'}\n                right={<Switch value={lb.content.sensitiveFilter} onValueChange={(v) => lbSave('content', { sensitiveFilter: v })} trackColor={{ true: colors.primary }} accessibilityLabel=\"Filtro de contenido sensible\" />}\n              />\n              <Row\n                icon={MapPin}\n                label=\"Ciudades preferidas\"\n                hint={lb.content.cities?.join(' · ') || 'Ninguna'}\n                onPress={() => setCityOpen(true)}\n              />\n              <Row\n                icon={Eye}\n                label=\"Visibilidad por defecto al publicar\"\n                hint={LB_VIS_LABEL[lb.publish.defaultVisibility] ?? lb.publish.defaultVisibility}\n                onPress={() => setLbPick({\n                  title: 'Visibilidad por defecto al publicar', group: 'publish', key: 'defaultVisibility',\n                  options: ['public', 'followers', 'private'].map((v) => ({ label: LB_VIS_LABEL[v] ?? v, value: v })),\n                  current: lb.publish.defaultVisibility,\n                })}\n              />\n              <Row\n                icon={Ban}\n                label=\"Usuarios bloqueados\"\n                hint=\"Ver y administrar\"\n                onPress={() => router.push('/lifebook-blocks' as never)}\n                last\n              />\n            </View>\n          </>\n        )}\n\n        {/* SOPORTE */}\n        <Text style={styles.groupTitle}>Soporte</Text>\n        <View style={[styles.group, { backgroundColor: colors.card }]}>\n          {/*\n            SOPORTE REAL (auditoría de diseño, D-37). Aquí había cuatro filas que respondían\n            «Próximamente» mientras tres pantallas de dinero decían «contacta soporte». Se\n            sustituyen por los tres canales que existen de verdad y el reporte de problemas.\n          */}\n          <Row icon={Headset} label=\"Ayuda por WhatsApp\" hint={SOPORTE.telefono} onPress={() => { void whatsappSoporte('Hola, necesito ayuda con EG Route Plan.'); }} />\n          <Row icon={Mail} label=\"Escribir un correo\" hint={SOPORTE.email} onPress={() => { void escribirASoporte('Ayuda con EG Route Plan'); }} />\n          <Row icon={Phone} label=\"Llamar al soporte\" hint={SOPORTE.telefono} onPress={() => { void llamarASoporte(); }} />\n          <Row icon={Flag} label=\"Reportar un problema\" onPress={() => { void escribirASoporte('Problema en la app', 'Cuéntanos qué pasó (qué hacías, qué esperabas y qué salió):\\n\\n'); }} last />\n        </View>\n        <Pressable\n          onPress={() => setEmergencyOpen(true)}\n          style={({ pressed }) => [styles.emergency, { backgroundColor: pressed ? alpha(colors.danger, 0.14) : alpha(colors.danger, 0.08) }]}\n        >\n          <Siren size={19} color={colors.danger} />\n          <Text style={{ color: colors.danger, fontWeight: '800', fontSize: tipografia.body }}>Emergencia</Text>\n        </Pressable>\n\n        {/* SESIÓN */}\n        <View style={[styles.group, { marginTop: espaciado.e16, backgroundColor: colors.card }]}>\n          <Row icon={LogOut} label=\"Cerrar sesión\" danger centered onPress={() => setConfirmLogout(true)} last />\n        </View>\n\n        <Text style={[styles.version, { color: colors.textSecondary }]}>EG Route Plan · v1.0.0</Text>\n      </ScrollView>\n\n      {/* Confirmación de cierre de sesión */}\n      <Modal visible={confirmLogout} transparent animationType=\"fade\" onRequestClose={() => setConfirmLogout(false)} statusBarTranslucent>\n        <View style={[styles.backdrop, { backgroundColor: colors.overlay, justifyContent: 'center', alignItems: 'center' }]}>\n          <View style={[styles.confirmCard, { backgroundColor: colors.card }]}>\n            <Text style={[styles.confirmTitle, { color: colors.textPrimary }]}>¿Cerrar sesión?</Text>\n            <Text style={[styles.confirmBody, { color: colors.textSecondary }]}>Podrás volver a entrar con tu teléfono y contraseña cuando quieras.</Text>\n            <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e16 }}>\n              <Pressable onPress={() => setConfirmLogout(false)} style={[styles.confirmBtn, { backgroundColor: colors.surface }]}>\n                <Text style={{ color: colors.textPrimary, fontWeight: '800' }}>Cancelar</Text>\n              </Pressable>\n              <Pressable onPress={doLogout} style={[styles.confirmBtn, { backgroundColor: colors.danger }]}>\n                <Text style={{ color: brand.white, fontWeight: '800' }}>Cerrar sesión</Text>\n              </Pressable>\n            </View>\n          </View>\n        </View>\n      </Modal>\n\n      {selectSheet('Idioma', LANG_OPTIONS.map((l) => l.label), LANG_OPTIONS.find((l) => l.code === lang)?.label ?? 'es-GQ', (o) => {\n        const found = LANG_OPTIONS.find((l) => l.label === o);\n        if (found && found.code !== 'es-GQ') { Alert.alert('Próximamente', 'Las traducciones a otros idiomas llegarán en una próxima actualización. Por ahora la app está en español.'); return; }\n        setLang(found?.code ?? 'es-GQ');\n      }, () => setLangOpen(false), false, langOpen)}\n      {selectSheet('Tamaño de texto', ['Pequeño', 'Normal', 'Grande', 'Muy grande'], fontSize, (o) => {\n        if (o !== 'Normal') { Alert.alert('Próximamente', 'El cambio global de tamaño de letra llegará en una próxima actualización.'); return; }\n        setFontSize(o);\n      }, () => setFontOpen(false), false, fontOpen)}\n      {selectSheet('Notificaciones visuales', ['Activadas', 'Solo importantes', 'Desactivadas'], notif, (o) => {\n        setNotif(o);\n        Alert.alert('Guardado', `Notificaciones: ${o}.`);\n      }, () => setNotifOpen(false), true, notifOpen)}\n\n      {/* Selector de privacidad de Life Book */}\n      {lbPick && (\n        <Modal visible transparent animationType=\"fade\" onRequestClose={() => setLbPick(null)} statusBarTranslucent>\n          <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={() => setLbPick(null)} />\n          <View style={[styles.sheetCard, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n            <View style={styles.sheetHeader}>\n              <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>{lbPick.title}</Text>\n              <Pressable onPress={() => setLbPick(null)} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e6 }}>Elige quién puede…</Text>\n            {lbPick.options.map((o) => {\n              const active = o.value === lbPick.current;\n              return (\n                <Pressable\n                  key={o.value}\n                  onPress={() => {\n                    lbSave(lbPick.group, { [lbPick.key]: o.value });\n                    setLbPick(null);\n                  }}\n                  style={({ pressed }) => [styles.sheetRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n                >\n                  <Text style={[styles.sheetRowTxt, { color: active ? colors.primary : colors.textPrimary }]}>{o.label}</Text>\n                  {active ? <Check size={18} color={colors.primary} /> : null}\n                </Pressable>\n              );\n            })}\n          </View>\n        </Modal>\n      )}\n\n      {/* Ciudades preferidas (multi) */}\n      <Modal visible={cityOpen} transparent animationType=\"fade\" onRequestClose={() => setCityOpen(false)} statusBarTranslucent>\n        <Pressable style={[styles.backdrop, { backgroundColor: colors.overlay }]} onPress={() => setCityOpen(false)} />\n        <View style={[styles.sheetCard, { backgroundColor: colors.card, paddingBottom: insets.bottom + 16 }]}>\n          <View style={styles.sheetHeader}>\n            <Text style={[styles.sheetTitle, { color: colors.textPrimary }]}>Ciudades preferidas</Text>\n            <Pressable onPress={() => setCityOpen(false)} hitSlop={10}><X size={20} color={colors.textSecondary} /></Pressable>\n          </View>\n          <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginBottom: espaciado.e6 }}>Verás primero el contenido de estas ciudades</Text>\n          {LB_CITIES.map((c) => {\n            const active = (lb?.content.cities ?? []).includes(c);\n            return (\n              <Pressable\n                key={c}\n                onPress={() => {\n                  const cities = active\n                    ? (lb?.content.cities ?? []).filter((x) => x !== c)\n                    : [...(lb?.content.cities ?? []).filter((x) => x !== c), c];\n                  lbSave('content', { cities });\n                }}\n                style={({ pressed }) => [styles.sheetRow, { backgroundColor: pressed ? alpha(colors.primary, 0.06) : 'transparent' }]}\n              >\n                <Text style={[styles.sheetRowTxt, { color: active ? colors.primary : colors.textPrimary }]}>{c}</Text>\n                {active ? <Check size={18} color={colors.primary} /> : null}\n              </Pressable>\n            );\n          })}\n          <Pressable onPress={() => setCityOpen(false)} style={{ marginTop: espaciado.e8, alignSelf: 'center' }}>\n            <Text style={{ color: colors.primary, fontWeight: '900', fontSize: tipografia.body }}>Listo</Text>\n          </Pressable>\n        </View>\n      </Modal>\n\n      <EmergencyModal visible={emergencyOpen} onClose={() => setEmergencyOpen(false)} />\n    </View>\n  );\n}\n\n/** Fila estándar de ajustes (icono + label + hint/control). */\nfunction Row({ icon: Icon, label, hint, danger, centered, onPress, right, last }: {\n  icon: any; label: string; hint?: string; danger?: boolean; centered?: boolean;\n  onPress?: () => void; right?: React.ReactNode; last?: boolean;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      disabled={!onPress}\n      style={({ pressed }) => [\n        styles.row,\n        centered && { justifyContent: 'center' },\n        { backgroundColor: pressed ? alpha(colors.border, 0.25) : 'transparent' },\n        !last && { borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.border },\n      ]}\n    >\n      {!centered && (\n        <View style={[styles.rowIcon, { backgroundColor: danger ? alpha(colors.danger, 0.1) : alpha(colors.primary, 0.08) }]}>\n          <Icon size={18} color={danger ? colors.danger : colors.primary} />\n        </View>\n      )}\n      <Text style={[styles.rowLabel, { color: danger ? colors.danger : colors.textPrimary }]}>{label}</Text>\n      {!centered && hint ? <Text style={styles.rowHint} numberOfLines={1}>{hint}</Text> : null}\n      {!centered && (right ?? <ChevronRight size={16} color={colors.textSecondary} />)}\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  topBar: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingTop: espaciado.e12, paddingBottom: espaciado.e10, borderBottomWidth: StyleSheet.hairlineWidth,\n  },\n  topTitle: { fontSize: 17, fontWeight: '900' },\n  content: { padding: espaciado.e16, gap: espaciado.e6 },\n  groupTitle: { fontSize: tipografia.micro, fontWeight: '800', color: '#8E8E93', textTransform: 'uppercase', letterSpacing: 0.5, marginTop: espaciado.e8, marginBottom: espaciado.e2 },\n  group: { borderRadius: radios.lg, overflow: 'hidden' },\n  row: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e12 },\n  rowIcon: { width: 32, height: 32, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\n  rowLabel: { flex: 1, fontSize: tipografia.body, fontWeight: '700' },\n  rowHint: { fontSize: tipografia.caption, fontWeight: '600', color: '#8E8E93', maxWidth: '52%' },\n  emergency: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: espaciado.e8,\n    borderRadius: 14, paddingVertical: espaciado.e13, marginTop: espaciado.e10,\n  },\n  version: { textAlign: 'center', fontSize: tipografia.micro, marginTop: espaciado.e16, fontWeight: '600' },\n  backdrop: { ...StyleSheet.absoluteFillObject },\n  sheetCard: { ...formaHoja },\n  sheetHeader: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: espaciado.e8 },\n  sheetTitle: { fontSize: tipografia.subtitle, fontWeight: '900' },\n  sheetRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: espaciado.e13 },\n  sheetRowTxt: { fontSize: 14.5, fontWeight: '700' },\n  confirmCard: { width: '84%', maxWidth: 340, borderRadius: 20, padding: espaciado.e20 },\n  confirmTitle: { fontSize: 17, fontWeight: '900', textAlign: 'center' },\n  confirmBody: { fontSize: tipografia.body, fontWeight: '600', textAlign: 'center', marginTop: espaciado.e8, lineHeight: 19 },\n  confirmBtn: { flex: 1, alignItems: 'center', justifyContent: 'center', borderRadius: radios.md, paddingVertical: espaciado.e12 },\n});\n","/**\n * StatusScreen — \"Mi estado 24h\" (/status).\n * Pantalla única para: ver/abrir el estado actual, publicar/cambiar/quitar\n * (editor), y AJUSTES del estado (visibilidad por defecto, reacciones,\n * búsqueda, tienda, notificaciones). Accesible desde el ☰, /edit-profile\n * y Ajustes → \"Estado 24h\".\n */\n\nimport React, { useState } from 'react';\nimport {\n  ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, Text, View,\n} from 'react-native';\nimport { useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport {\n  ArrowLeft, Bell, Clock, Eye, Globe, Heart, Lock, Plus, Search, Store, Users,\n} from 'lucide-react-native';\nimport { alpha, espaciado, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport { AuthGate } from '../core/AuthGate';\nimport { useStatusStore } from '../state/statusStore';\nimport StatusRingAvatar from '../components/status/StatusRingAvatar';\nimport StatusChip from '../components/status/StatusChip';\nimport StatusEditorModal from '../components/status/StatusEditorModal';\nimport StatusDetailModal from '../components/status/StatusDetailModal';\nimport { VISIBILITY_OPTIONS } from '../constants/status';\nimport { useSession } from '../state/session';\nimport { authApi, type MeProfile } from '../api/auth';\nimport { useEffect } from 'react';\n\nexport default function StatusScreen() {\n  return (\n    <AuthGate>\n      <StatusContent />\n    </AuthGate>\n  );\n}\n\nfunction StatusContent() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { isAuthenticated } = useSession();\n  const {\n    status, prefs, loading, error, refresh,\n    updatePrefs, localExpire, publish, end, saveDraft, clearDraft, draft,\n  } = useStatusStore();\n  const [editorOpen, setEditorOpen] = useState(false);\n  const [detailOpen, setDetailOpen] = useState(false);\n  const [profile, setProfile] = useState<MeProfile | null>(null);\n\n  useEffect(() => { if (isAuthenticated) { refresh(); authApi.me().then(setProfile).catch(() => {}); } }, [isAuthenticated, refresh]);\n  useEffect(() => { if (draft) setEditorOpen(true); }, [draft]);\n\n  return (\n    <View style={[styles.root, { backgroundColor: colors.background }]}>\n      <View style={[styles.topBar, { borderBottomColor: colors.border }]}>\n        <Pressable onPress={() => router.back()} hitSlop={12} accessibilityLabel=\"Volver\">\n          <ArrowLeft size={22} color={colors.textPrimary} />\n        </Pressable>\n        <Text style={[styles.topTitle, { color: colors.textPrimary }]}>Mi estado 24h</Text>\n        <View style={{ width: 22 }} />\n      </View>\n\n      <ScrollView contentContainerStyle={{ paddingBottom: insets.bottom + 28 }} showsVerticalScrollIndicator={false}>\n        {loading && !status ? (\n          <View style={styles.center}><ActivityIndicator color={colors.primary} /></View>\n        ) : error && !status ? (\n          <View style={styles.center}>\n            <Text style={{ color: colors.danger, fontSize: tipografia.body, fontWeight: '700' }}>No se pudo cargar tu estado.</Text>\n            <Pressable onPress={refresh} style={[styles.retry, { backgroundColor: colors.surface }]}>\n              <Text style={{ color: colors.primary, fontWeight: '800' }}>Reintentar</Text>\n            </Pressable>\n          </View>\n        ) : (\n          <>\n            {/* Estado actual */}\n            <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              <Text style={styles.groupTitle}>ESTADO ACTUAL</Text>\n              {status ? (\n                <>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }}>\n                    <StatusRingAvatar\n                      avatarUrl={profile?.avatarUrl ?? null}\n                      name={profile?.fullName}\n                      status={status}\n                      size={52}\n                      ringWidth={3}\n                    />\n                    <View style={{ flex: 1 }}>\n                      <StatusChip status={status} onPress={() => setDetailOpen(true)} onExpired={refresh} />\n                      <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e4 }}>\n                        Expira automáticamente en 24 h · visibilidad: {status.visibility === 'public' ? 'Todos' : status.visibility === 'followers' ? 'Seguidores' : 'Solo yo'}\n                      </Text>\n                    </View>\n                  </View>\n                  <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e14 }}>\n                    <Pressable onPress={() => setEditorOpen(true)} style={[styles.actionBtn, { backgroundColor: colors.surface }]}>\n                      <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>Cambiar estado</Text>\n                    </Pressable>\n                    <Pressable onPress={() => { end().then(() => localExpire()).catch(() => {}); }} style={[styles.actionBtn, { backgroundColor: alpha(colors.danger, 0.08) }]}>\n                      <Text style={{ color: colors.danger, fontWeight: '800', fontSize: tipografia.body }}>Finalizar</Text>\n                    </Pressable>\n                  </View>\n                </>\n              ) : (\n                <Pressable onPress={() => setEditorOpen(true)} style={[styles.addStatus, { backgroundColor: alpha(colors.primary, 0.08), borderColor: alpha(colors.primary, 0.4) }]}>\n                  <View style={[styles.addIcon, { backgroundColor: alpha(colors.primary, 0.16) }]}>\n                    <Plus size={20} color={colors.primary} />\n                  </View>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ color: colors.textPrimary, fontSize: 15, fontWeight: '900' }}>Agregar estado 24h</Text>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: 1 }}>Comparte qué estás haciendo · dura 24 horas</Text>\n                  </View>\n                </Pressable>\n              )}\n            </View>\n\n            {/* Ajustes de estado */}\n            <Text style={styles.groupTitle}>AJUSTES DE ESTADO</Text>\n            <View style={[styles.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              {/* Visibilidad por defecto */}\n              <Text style={[styles.subLabel, { color: colors.textSecondary }]}>VISIBILIDAD POR DEFECTO</Text>\n              <View style={styles.visRowWrap}>\n                {VISIBILITY_OPTIONS.map((o) => {\n                  const active = prefs?.defaultVisibility === o.value;\n                  const Icon = o.value === 'public' ? Globe : o.value === 'followers' ? Users : Lock;\n                  return (\n                    <Pressable\n                      key={o.value}\n                      onPress={() => updatePrefs({ defaultVisibility: o.value }).catch(() => {})}\n                      accessibilityRole=\"radio\"\n                      accessibilityState={{ checked: active }}\n                      style={[styles.visChip, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? alpha(colors.primary, 0.08) : colors.surface }]}\n                    >\n                      <Icon size={13} color={active ? colors.primary : colors.textSecondary} />\n                      <Text style={{ color: active ? colors.primary : colors.textPrimary, fontSize: tipografia.caption, fontWeight: '800' }}>{o.label}</Text>\n                    </Pressable>\n                  );\n                })}\n              </View>\n\n              <PrefRow icon={Search} label=\"Mostrar en búsqueda\" hint=\"Aparecer al buscar personas/negocios\" value={prefs?.showInSearch !== false} onChange={(v) => updatePrefs({ showInSearch: v }).catch(() => {})} colors={colors} />\n              <PrefRow icon={Store} label=\"Mostrar en mi tienda\" hint=\"Solo si eres vendedor o restaurante\" value={prefs?.showInStore !== false} onChange={(v) => updatePrefs({ showInStore: v }).catch(() => {})} colors={colors} />\n              <PrefRow icon={Heart} label=\"Permitir reacciones\" hint=\"Que otros reaccionen a tu estado\" value={prefs?.allowReactions !== false} onChange={(v) => updatePrefs({ allowReactions: v }).catch(() => {})} colors={colors} />\n              <PrefRow icon={Bell} label=\"Notificaciones de estado\" hint=\"Avisos al expirar o reaccionar\" value={prefs?.notifications !== false} onChange={(v) => updatePrefs({ notifications: v }).catch(() => {})} colors={colors} last />\n            </View>\n\n            <View style={[styles.infoBox, { backgroundColor: colors.surface }]}>\n              <Clock size={14} color={colors.textSecondary} />\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, flex: 1 }}>\n                Tu estado desaparece solo a las 24 horas. Puedes finalizarlo antes cuando quieras.\n              </Text>\n            </View>\n          </>\n        )}\n      </ScrollView>\n\n      <StatusEditorModal visible={editorOpen} onClose={() => setEditorOpen(false)} onSaved={() => refresh()} />\n      {status && (\n        <StatusDetailModal visible={detailOpen} status={status} isMine onClose={() => setDetailOpen(false)} onEnded={() => { localExpire(); }} />\n      )}\n    </View>\n  );\n}\n\nfunction PrefRow({\n  icon: Icon, label, hint, value, onChange, colors, last,\n}: {\n  icon: any; label: string; hint: string; value: boolean; onChange: (v: boolean) => void;\n  colors: any; last?: boolean;\n}) {\n  return (\n    <View style={[styles.prefRow, { borderBottomWidth: last ? 0 : 1, borderBottomColor: colors.border }]}>\n      <View style={[styles.prefIcon, { backgroundColor: alpha(colors.primary, 0.08) }]}>\n        <Icon size={15} color={colors.primary} />\n      </View>\n      <View style={{ flex: 1 }}>\n        <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{label}</Text>\n        <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, marginTop: 1 }}>{hint}</Text>\n      </View>\n      <Switch value={value} onValueChange={onChange} trackColor={{ true: colors.primary }} accessibilityLabel={label} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1 },\n  topBar: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12, borderBottomWidth: 1,\n  },\n  topTitle: { fontSize: 17, fontWeight: '900' },\n  center: { alignItems: 'center', paddingVertical: 60, gap: espaciado.e14 },\n  retry: { borderRadius: radios.md, paddingHorizontal: espaciado.e22, paddingVertical: espaciado.e10 },\n  card: { marginHorizontal: espaciado.e16, borderRadius: 18, borderWidth: 1, padding: espaciado.e14 },\n  groupTitle: {\n    fontSize: tipografia.micro, fontWeight: '900', letterSpacing: 1, color: '#8E8E93',\n    textTransform: 'uppercase', marginTop: espaciado.e18, marginBottom: espaciado.e6, marginHorizontal: espaciado.e18,\n  },\n  actionBtn: { flex: 1, alignItems: 'center', borderRadius: radios.md, paddingVertical: espaciado.e11 },\n  addStatus: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n    borderRadius: radios.lg, borderWidth: 1.5, padding: espaciado.e14,\n  },\n  addIcon: { width: 42, height: 42, borderRadius: 14, alignItems: 'center', justifyContent: 'center' },\n  subLabel: { fontSize: 10, fontWeight: '900', letterSpacing: 0.8, marginBottom: espaciado.e8 },\n  visRowWrap: { flexDirection: 'row', gap: espaciado.e8, marginBottom: espaciado.e14 },\n  visChip: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e6,\n    borderWidth: 1, borderRadius: radios.full, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8,\n  },\n  prefRow: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, paddingVertical: espaciado.e10,\n  },\n  prefIcon: { width: 32, height: 32, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },\n  infoBox: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, margin: espaciado.e16, borderRadius: 14, padding: espaciado.e12 },\n});\n","// egrouteplan-app/app/taxi.tsx\n/**\n * TaxiScreen — pedir taxi (DiDi-like) con modalidades, doble precio y MAPA.\n * Backend: /wallet/api/v1/mobility (modes + trips). Ruta OSRM real.\n *\n * Auditoría senior (2026-09-02, v3):\n *  · ORIGEN real: GPS (expo-location) con permiso → tu posición; denegado →\n *    ciudad de la Home (?city=) o Malabo, SIEMPRE con banner visible.\n *  · Destino: tocar el mapa (debounce + AbortController en la ruta OSRM);\n *    escribir dirección = guía hasta tocar el mapa (sin geocoder propio aún).\n *  · Errores visibles: ruta OSRM y modalidades con Reintentar; precio con\n *    error inline (500–9.999 XAF) además del bloqueo del botón.\n *  · Mapa = MapBackground (carga/error/Reintentar internos + fallback Expo Go)\n *    con marcadores y polyline DENTRO (hijos del EgMapView).\n *  · useTripLogic (polling + reset + cleanup) y AbortController limpian en\n *    unmount. SafeArea, a11y (back, radios), FlatList con getItemLayout.\n * Ruta: /taxi?city=Malabo\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  ActivityIndicator, Animated, Easing, Image, KeyboardAvoidingView, Linking, Modal,\n  Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View,\n} from 'react-native';\nimport { useLocalSearchParams, useRouter, useFocusEffect } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport * as Location from 'expo-location';\nimport {\n  ArrowLeft, ArrowUpDown, Bus, CarFront, MapPin, Navigation, Pencil, RefreshCw, Star, Tag, Users, User, X,\n} from 'lucide-react-native';\nimport { elevation, espaciado, GhostButton, PrimaryButton, radios, tipografia, useTheme } from '@egrouteplan/ui-kit';\nimport MapBackground from '../components/MapBackground';\nimport { EgMarkers, EgRoutePolyline, type Coord, type EgMapViewHandle } from '../packages/map';\nimport { taxiApi, type TaxiMode } from '../api/taxi';\nimport { adsApi } from '../api/ads';\nimport { reverseGeocode, pickReverseLabel } from '../api/geocode';\nimport { getCurrentGqPosition } from '../api/locate';\nimport { isNightGq } from '../api/nightMode';\nimport { useDriverLiveTrack } from '../components/DriverLiveMap';\nimport { useSession } from '../state/session';\nimport { takeGeoPick } from '../state/geoPick';\nimport { CITIES } from '../constants/data';\nimport { CITY_CENTERS } from '../constants/geo';\nimport { settlementApi, SettlementView, tokenDeViaje, fijarPin } from '../api/settlement';\n\nimport { OSRM_BASE, absUrl } from '../api/config';\nimport { brand } from '@egrouteplan/ui-kit';\n\nconst OSRM = OSRM_BASE;\n\n/** alpha local (misma impl que constants/colors) para tintes de fila. */\nfunction alphaC(hex: string, opacity: number): string {\n  const h = hex.replace('#', '');\n  const r = parseInt(h.slice(0, 2), 16);\n  const g = parseInt(h.slice(2, 4), 16);\n  const b = parseInt(h.slice(4, 6), 16);\n  return `rgba(${r}, ${g}, ${b}, ${opacity})`;\n}\n\n/** PIN de confirmación: últimos 4 dígitos del teléfono del pasajero. */\nfunction pinLast4(p?: string | null): string {\n  const d = (p || '').replace(/\\D/g, '');\n  return d.length >= 4 ? d.slice(-4) : d.padStart(4, '0');\n}\n\nconst MODE_ICON: Record<string, React.ReactNode> = {\n  recomendado: <Star size={22} color={brand.primary} />,\n  compartido: <Users size={22} color={brand.secondary} />,\n  no_compartido: <User size={22} color={brand.success} />,\n  especial: <Tag size={22} color={brand.primary} />,\n  minibus: <Bus size={22} color={brand.secondary} />,\n};\n\nconst STATUS_UI: Record<string, { t: string; c: string }> = {\n  requested: { t: 'Buscando conductor…', c: brand.secondary },\n  accepted: { t: 'Conductor en camino', c: brand.success },\n  cancelled: { t: 'Viaje cancelado', c: brand.danger },\n  completed: { t: 'Viaje finalizado', c: brand.success },\n};\n\n/** Motivos de rechazo/cancelación del viaje (DiDi). */\nconst REJECT_REASONS = [\n  'Tarda demasiado en llegar',\n  'El precio no me convence',\n  'El coche no coincide',\n  'Cambié de planes',\n  'Otro motivo',\n];\n\n/** Ciudad (por nombre) más cercana a unas coordenadas, para etiquetas/tarifas. */\nfunction nearestCityName(coord: Coord): string {\n  let best = '';\n  let bestD = Infinity;\n  for (const [id, c] of Object.entries(CITY_CENTERS)) {\n    const d = (c[0] - coord[0]) ** 2 + (c[1] - coord[1]) ** 2;\n    if (d < bestD) { bestD = d; best = id; }\n  }\n  return CITIES.find((c) => c.id === best)?.name ?? '';\n}\n\n/** Debounce de invocación: devuelve una función que solo se ejecuta tras `delay` ms de silencio. */\nfunction useDebouncedCall<A extends unknown[]>(fn: (...args: A) => void, delay: number): (...args: A) => void {\n  const fnRef = useRef(fn);\n  fnRef.current = fn;\n  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);\n  return useCallback((...args: A) => {\n    if (timerRef.current) clearTimeout(timerRef.current);\n    timerRef.current = setTimeout(() => fnRef.current(...args), delay);\n  }, [delay]);\n}\n\n/** Lógica del viaje: estado, polling (3 s) y reset con cleanup en unmount. */\nfunction useTripLogic() {\n  const [status, setStatus] = useState<'idle' | 'requested' | 'accepted' | 'cancelled' | 'completed'>('idle');\n  const [tripId, setTripId] = useState<string | null>(null);\n  const [trip, setTrip] = useState<Record<string, any> | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);\n\n  const stopPolling = useCallback(() => {\n    if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }\n  }, []);\n\n  const resetTrip = useCallback(() => {\n    stopPolling();\n    setStatus('idle'); setTripId(null); setTrip(null); setError(null);\n  }, [stopPolling]);\n\n  const startPolling = useCallback((id: string) => {\n    stopPolling();\n    pollRef.current = setInterval(async () => {\n      try {\n        const t = await taxiApi.getTrip(id);\n        setTrip(t);\n        if (t.status === 'accepted' || t.status === 'cancelled') {\n          setStatus(t.status);\n          stopPolling();\n        }\n      } catch { /* reintenta en el siguiente tick */ }\n    }, 3000);\n  }, [stopPolling]);\n\n  useEffect(() => stopPolling, [stopPolling]);\n\n  return { status, setStatus, tripId, setTripId, trip, setTrip, error, setError, busy, setBusy, resetTrip, startPolling };\n}\n\n/** Radar \"Buscando taxi\" (DiDi): 3 anillos que se expanden + icono de coche.\n *  Animated nativo (sin Lottie, decisión 2026-09-08). */\nfunction SearchRadar({ color }: { color: string }) {\n  const a1 = useRef(new Animated.Value(0)).current;\n  const a2 = useRef(new Animated.Value(0)).current;\n  const a3 = useRef(new Animated.Value(0)).current;\n  useEffect(() => {\n    const loop = (a: Animated.Value, delay: number) =>\n      Animated.loop(Animated.sequence([\n        Animated.delay(delay),\n        Animated.timing(a, { toValue: 1, duration: 1900, easing: Easing.out(Easing.quad), useNativeDriver: true }),\n        Animated.timing(a, { toValue: 0, duration: 0, useNativeDriver: true }),\n      ]));\n    loop(a1, 0).start();\n    loop(a2, 630).start();\n    loop(a3, 1260).start();\n    return () => { a1.stopAnimation(); a2.stopAnimation(); a3.stopAnimation(); };\n  }, [a1, a2, a3]);\n  const ring = (a: Animated.Value) => ({\n    opacity: a.interpolate({ inputRange: [0, 0.85, 1], outputRange: [0.5, 0.06, 0] }),\n    transform: [{ scale: a.interpolate({ inputRange: [0, 1], outputRange: [0.55, 2.6] }) }],\n  });\n  return (\n    <View style={{ width: 120, height: 120, alignItems: 'center', justifyContent: 'center' }}>\n      {[a1, a2, a3].map((a, i) => (\n        <Animated.View\n          key={i}\n          pointerEvents=\"none\"\n          style={[{ position: 'absolute', width: 120, height: 120, borderRadius: 60, borderWidth: 2, borderColor: color }, ring(a)]}\n        />\n      ))}\n      <View style={{ width: 56, height: 56, borderRadius: 28, backgroundColor: color, alignItems: 'center', justifyContent: 'center', elevation: 6 }}>\n        <CarFront size={28} color={brand.white} />\n      </View>\n    </View>\n  );\n}\n\nexport default function TaxiScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { city: cityParam, dLat, dLng, dLabel, oLat, oLng, oLabel } = useLocalSearchParams<{\n    city?: string; dLat?: string; dLng?: string; dLabel?: string;\n    /** Origen pre-fijado (p. ej. el aeropuerto, desde la ficha del hotel): así el huésped que acaba de\n     *  aterrizar no tiene que escribir ninguna dirección para ir a su alojamiento. */\n    oLat?: string; oLng?: string; oLabel?: string;\n  }>();\n  const { isAuthenticated, phone } = useSession();\n  const mapRef = useRef<EgMapViewHandle>(null);\n  const abortRef = useRef<AbortController | null>(null);\n\n  const [origin, setOrigin] = useState<Coord | null>(null);\n  const [originLabel, setOriginLabel] = useState('Localizando…');\n  const [locBanner, setLocBanner] = useState<string | null>(null);\n  const [modes, setModes] = useState<TaxiMode[]>([]);\n  const [modesLoading, setModesLoading] = useState(true);\n  const [modesError, setModesError] = useState<string | null>(null);\n  const [modeId, setModeId] = useState('recomendado');\n  const [destCoord, setDestCoord] = useState<Coord | null>(null);\n  const [destText, setDestText] = useState('');\n  const [routeCoords, setRouteCoords] = useState<Coord[]>([]);\n  const [distanceKm, setDistanceKm] = useState(0);\n  const [routeError, setRouteError] = useState<string | null>(null);\n  const [userPrice, setUserPrice] = useState('');\n  // Promo de taxi activa (campaña publicitaria con descuento, p. ej. -20 %).\n  const [promo, setPromo] = useState<{ pct: number; title: string } | null>(null);\n  // Selector de pasajeros (DiDi: 1–6). El total de modos COMPARTIDOS se calcula\n  // POR ASIENTO × pasajeros; los privados son por coche (no cambia).\n  const [passengers, setPassengers] = useState(1);\n  // ETA de la ruta (OSRM → minutos) para la tarjeta del pin destino.\n  const [etaMin, setEtaMin] = useState<number | null>(null);\n  // Flujo de rechazo/cancelación del viaje (DiDi Fase 2).\n  const [cancelOpen, setCancelOpen] = useState(false);        // modal de motivos\n  const [cancelBusy, setCancelBusy] = useState(false);\n  // P1b: editar modalidad/presupuesto DURANTE la búsqueda (re-lanzar sin volver\n  // a idle). searchEdit = selector abierto; relaunching = llamada en curso.\n  const [searchEdit, setSearchEdit] = useState(false);\n  const [relaunching, setRelaunching] = useState(false);\n  // P1e: rating del conductor al completar el viaje (1–5 + comentario opcional).\n  const [ratingOpen, setRatingOpen] = useState(false);\n  const [ratingScore, setRatingScore] = useState(5);\n  const [ratingComment, setRatingComment] = useState('');\n  const [ratingBusy, setRatingBusy] = useState(false);\n  const ratedTripRef = useRef<string | null>(null);\n  const rejectBusyRef = useRef(false);\n  // Qué fija un toque en el mapa: 'destino' (por defecto) o 'origen' (cambiar\n  // el punto de partida con un solo clic, como DiDi permite ajustar la salida).\n  const [moveTarget, setMoveTarget] = useState<'origen' | 'destino'>('destino');\n  // Secuencia para no aplicar respuestas reverse-geocoder obsoletas (carreras).\n  const revSeq = useRef(0);\n  // Viaje ACTIVO reanudado desde el servidor: mientras exista, el GPS de arranque\n  // y los cambios de origen/destino quedan BLOQUEADOS (decisión del dueño:\n  // tras confirmar no se puede editar el trayecto).\n  const lockedTripRef = useRef<string | null>(null);\n\n  const { status, setStatus, tripId, setTripId, trip, setTrip, error, setError, busy, setBusy, resetTrip, startPolling } = useTripLogic();\n\n  // ── Seguimiento EN VIVO del conductor (estilo DiDi) ──────────────────────\n  // Polling GET /trips/:id cada 2,5 s mientras haya conductor asignado; el\n  // coche se anima DENTRO de la página del mapa (rAF + ease-in-out 2 s,\n  // geo-lerp). Rumbo por GPS si viene, si no entre 2 últimas posiciones.\n  // >10 s sin fix → `lost` (banner + marcador gris). completed/cancelled →\n  // el hook para el polling solo y notifica onEnded. Se le pasa tripId solo\n  // en 'accepted' para no sondear en idle/requested (ya lo hace startPolling).\n  const live = useDriverLiveTrack({\n    tripId: status === 'accepted' ? tripId : null,\n    mapRef,\n    onEnded: (s) => {\n      if (s === 'completed') {\n        setStatus('completed');\n        // P1e: ofrecer valorar al conductor al terminar (una vez por viaje).\n        if (tripId && ratedTripRef.current !== tripId) {\n          ratedTripRef.current = tripId;\n          setRatingScore(5); setRatingComment('');\n          setRatingOpen(true);\n        }\n      } else if (s === 'cancelled') setStatus('cancelled');\n    },\n  });\n\n  // ── FASES DEL VIAJE EN VIVO (P3/P4, 2026-09-08) ──────────────────────────\n  // El pasajero vive en 'accepted' tanto de camino a recogerle como ya en\n  // ruta. El estado CRUDO del servidor (live.status) distingue:\n  //   · 'accepted'     → APPROACH: conductor viene a recogerte (tarjeta completa).\n  //   · 'in_progress'  → EN MARCHA: te recogió y va al destino (tarjeta mínima\n  //                      transparente; la pantalla es la ruta con el coche).\n  const enMarcha = live.status === 'in_progress';\n  // P1-c: 'arrived' = el conductor avisó de llegada (la app CIERRA o espera el\n  // auto-cierre a los 10 min). No es 'in_progress': la tarjeta es distinta.\n  const arrived = live.status === 'arrived';\n  const approach = status === 'accepted' && !enMarcha && !arrived;\n\n  // ── Paleta Amap en viaje activo (PASAJERO) ───────────────────────────────\n  // Mismo mapa verde/calles oscuras que el conductor (navMode passenger),\n  // con pan libre y pitch 0. Fuera del viaje activo → mapa claro de búsqueda.\n  const isLivePhase = status === 'requested' || status === 'accepted';\n  useEffect(() => {\n    mapRef.current?.setNavMode?.(isLivePhase ? 'passenger' : 'normal');\n  }, [isLivePhase]);\n\n  // Modo NOCHE del mapa por horario de Guinea Ecuatorial (UTC+1): al montar y\n  // cada minuto (cruzar 19:00/06:00 cambia la paleta en vivo, sin recargar).\n  useEffect(() => {\n    let nightNow = isNightGq();\n    mapRef.current?.setNight?.(nightNow);\n    const t = setInterval(() => {\n      const n = isNightGq();\n      if (n !== nightNow) { nightNow = n; mapRef.current?.setNight?.(n); }\n    }, 60000);\n    return () => clearInterval(t);\n  }, []);\n\n  // ── Aproximación del conductor + fitBounds coche↔pasajero ────────────────\n  const pickup = origin; // recogida = posición del pasajero\n  const lastApproachRef = useRef<{ at: number; lng: number; lat: number } | null>(null);\n  const lastFitRef = useRef<{ lng: number; lat: number; dKm: number } | null>(null);\n  const prevLiveStatusRef = useRef<string | null>(null);\n  useEffect(() => {\n    const fx = live.fix;\n    const st = live.status;\n    const prevSt = prevLiveStatusRef.current;\n    prevLiveStatusRef.current = st;\n    // La RUTA REAL por calles conductor→recogida (DiDi: el pasajero ve por qué\n    // calles viene el coche) y el atenuado del azul solo aplican mientras el\n    // conductor va de camino ('accepted' = \"Conductor en camino\").\n    const onWay = st === 'accepted';\n    mapRef.current?.setRouteDim?.(onWay);\n    if (!fx || !pickup || status !== 'accepted' || !onWay) {\n      if (!onWay) mapRef.current?.setApproach?.([]);\n      return;\n    }\n    // Ruta REAL conductor → recogida (OSRM) con throttle ~5 s / avance real.\n    const la = lastApproachRef.current;\n    const dMove = la\n      ? Math.abs(fx.lng - la.lng) * 95 + Math.abs(fx.lat - la.lat) * 111\n      : 999;\n    if (!la || (Date.now() - la.at > 5000 && dMove > 0.04)) {\n      lastApproachRef.current = { at: Date.now(), lng: fx.lng, lat: fx.lat };\n      (async () => {\n        try {\n          const res = await fetch(`${OSRM}/driving/${fx.lng},${fx.lat};${pickup[0]},${pickup[1]}?overview=full&geometries=geojson`);\n          const data = await res.json();\n          const coords = (data?.routes?.[0]?.geometry?.coordinates ?? []) as Coord[];\n          if (coords.length >= 2) mapRef.current?.setApproach?.(coords);\n        } catch { /* sin ruta: no se dibuja nada */ }\n      })();\n    }\n    // fitBounds: al llegar el PRIMER fix del conductor (transición hacia\n    // 'accepted') o cuando el coche avanza mucho y saldría de pantalla\n    // (distancia coche→pasajero crece > ~35 % respecto al último encuadre).\n    const havKm = (a: Coord, b: Coord) => {\n      const R = 6371, toR = Math.PI / 180;\n      const dLa = (b[1] - a[1]) * toR, dLo = (b[0] - a[0]) * toR;\n      const s = Math.sin(dLa / 2) ** 2 + Math.cos(a[1] * toR) * Math.cos(b[1] * toR) * Math.sin(dLo / 2) ** 2;\n      return 2 * R * Math.asin(Math.sqrt(s));\n    };\n    const dKm = havKm([fx.lng, fx.lat], pickup as Coord);\n    const lf = lastFitRef.current;\n    const entering = prevSt !== 'accepted' && st === 'accepted';\n    const growing = lf && dKm > lf.dKm * 1.35 + 0.08;\n    if (entering || growing) {\n      lastFitRef.current = { lng: fx.lng, lat: fx.lat, dKm };\n      // Encuadra los DOS puntos: conductor (pos. actual) y pasajero (recogida).\n      mapRef.current?.fitBounds([[fx.lng, fx.lat], pickup as unknown as Coord], { bottomFrac: 0.3 });\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [live.fix?.lng, live.fix?.lat, live.status, status]);\n\n  // ── Origen: GPS real (solo si está DENTRO de Guinea Ecuatorial). Si el\n  // dispositivo está fuera (o sin permiso), usamos una DIRECCIÓN REAL de la\n  // ciudad activa (p. ej. una avenida de Malabo) para que OSRM (cobertura GQ)\n  // pueda calcular rutas reales dentro de la ciudad. Si se REANUDA un viaje en\n  // curso (lockedTripRef) el origen es el del viaje: el GPS nunca lo pisa. ──\n  useEffect(() => {\n    let alive = true;\n    const useCityOrigin = (fbName?: string) => {\n      const fb = fbName\n        ? CITIES.find((ci) => ci.name.trim().toLowerCase() === fbName.trim().toLowerCase())\n        : undefined;\n      if (fb?.id === 'malabo') {\n        // Punto real en el centro de Malabo (Avenida de la Independencia).\n        setOrigin([8.7761, 3.7542]);\n        setOriginLabel('Mi ubicación · Av. de la Independencia');\n      } else if (fb?.id === 'bata') {\n        setOrigin([9.7652, 1.8625]);\n        setOriginLabel('Mi ubicación · Av. de las Naciones Unidas');\n      } else if (fb && CITY_CENTERS[fb.id]) {\n        setOrigin(CITY_CENTERS[fb.id]);\n        setOriginLabel(`Mi ubicación · ${fb.name}`);\n      } else {\n        setOrigin([8.7761, 3.7542]);\n        setOriginLabel('Mi ubicación · Av. de la Independencia');\n      }\n      setLocBanner('Ubicación aproximada en ' + (fb?.name ?? 'Malabo') + '. Toca \"Desde\" para cambiarla.');\n    };\n    (async () => {\n      try {\n        const perm = await Location.requestForegroundPermissionsAsync();\n        if (perm.status === 'granted' && alive) {\n          const p = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });\n          if (p && alive) {\n            const c: Coord = [p.coords.longitude, p.coords.latitude];\n            // Bounding box de Guinea Ecuatorial (aprox., incluye islas).\n            const insideGQ = c[0] >= 5.0 && c[0] <= 11.6 && c[1] >= -1.7 && c[1] <= 4.2;\n            if (lockedTripRef.current) return; // viaje reanudado: respetar su origen\n            // ── Y SI EL ORIGEN VENÍA PUESTO, EL GPS NO LO PISA ──────────────────────\n            // El caso del huésped que llega al aeropuerto: la ficha del hotel abre el taxi con la\n            // SALIDA ya puesta (el aeropuerto). Si el GPS la sobrescribe con «dónde estás ahora», el\n            // botón deja de servir para lo único que existe: pedir el taxi desde el aeropuerto al\n            // hotel sin escribir nada. Se comprueba con la referencia, no con el texto.\n            if (geoOrigenRef.current) return;\n            if (insideGQ) {\n              setOrigin(c);\n              setOriginLabel(`Mi ubicación · ${nearestCityName(c)}`);\n              return;\n            }\n            // Fuera de GQ (p. ej. el dueño probando desde China): usar ciudad.\n            if (alive) useCityOrigin(cityParam);\n            return;\n          }\n        }\n      } catch { /* GPS falla → fallback */ }\n      if (alive && !lockedTripRef.current) useCityOrigin(cityParam);\n    })();\n    return () => { alive = false; };\n  }, [cityParam]);\n\n  const fareCity = useMemo(() => {\n    if (origin) {\n      const n = nearestCityName(origin);\n      if (n) return n;\n    }\n    if (cityParam) return String(cityParam);\n    return 'Malabo';\n  }, [origin, cityParam]);\n\n  // Promo de taxi activa (banner publicitario con serviceKey=taxi y descuento)\n  // para la ciudad actual. Se aplica al precio al confirmar.\n  useEffect(() => {\n    let alive = true;\n    setPromo(null);\n    if (!fareCity) return;\n    adsApi.homeBanner(fareCity)\n      .then((b) => {\n        if (!alive) return;\n        const pct = Number(b?.discountPct ?? 0);\n        if (b?.serviceKey === 'taxi' && pct > 0 && pct <= 90) {\n          setPromo({ pct, title: b.title });\n        }\n      })\n      .catch(() => {});\n    return () => { alive = false; };\n  }, [fareCity]);\n\n  // Cámara con la que ABRE el mapa (MapBackground la aplica en cuanto el\n  // WebView está ready): dirección real de la ciudad activa. Antes se abría en\n  // la vista isla (z8) y el usuario veía mar hasta elegir destino.\n  const initCam = useMemo(() => {\n    const fb = cityParam\n      ? CITIES.find((ci) => ci.name.trim().toLowerCase() === String(cityParam).trim().toLowerCase())\n      : undefined;\n    if (fb?.id === 'malabo') return { centerCoordinate: [8.7761, 3.7542] as Coord, zoomLevel: 13.6 };\n    if (fb?.id === 'bata') return { centerCoordinate: [9.7652, 1.8625] as Coord, zoomLevel: 13.6 };\n    if (fb && CITY_CENTERS[fb.id]) return { centerCoordinate: CITY_CENTERS[fb.id], zoomLevel: 12.5 };\n    return { centerCoordinate: [8.7761, 3.7542] as Coord, zoomLevel: 13.6 };\n  }, [cityParam]);\n\n  // ── Ruta OSRM real, con cancelación de peticiones pendientes.\n  const fetchRoute = useCallback(async (to: Coord, opts?: { fit?: boolean }) => {\n    if (!origin) return;\n    if (abortRef.current) abortRef.current.abort();\n    const ctrl = new AbortController();\n    abortRef.current = ctrl;\n    setRouteError(null);\n    setRouteCoords([]);\n    setDistanceKm(0);\n    try {\n      const res = await fetch(\n        `${OSRM}/driving/${origin[0]},${origin[1]};${to[0]},${to[1]}?overview=full&geometries=geojson`,\n        { signal: ctrl.signal },\n      );\n      if (!res.ok) { setRouteError('No se pudo calcular la ruta (servicio OSRM).'); return; }\n      const data = await res.json();\n      const route = data?.routes?.[0];\n      if (!route || !route.geometry?.coordinates?.length) { setRouteError('No se encontró ruta hasta ese punto.'); return; }\n      const coords: Coord[] = route.geometry.coordinates;\n      setRouteCoords(coords);\n      setDistanceKm(Math.round((route.distance / 1000) * 10) / 10);\n      setEtaMin(Math.max(1, Math.round((route.duration ?? 0) / 60)));\n      if (coords.length >= 2 && opts?.fit !== false) {\n        try { mapRef.current?.fitBounds([coords[0], coords[coords.length - 1]], { bottomFrac: 0.42 }); } catch { /* noop */ }\n      }\n    } catch (e) {\n      if ((e as Error).name !== 'AbortError') {\n        setRouteError('No se pudo calcular la ruta. Revisa tu conexión.');\n      }\n    }\n  }, [origin]);\n\n  // Debounce de llamadas: taps rápidos seguidos no disparan rutas OSRM en cascada.\n  const debouncedFetchRoute = useDebouncedCall(fetchRoute, 300);\n\n  // ── REANUDAR VIAJE ACTIVO (decisión del dueño: persistencia) ──────────────\n  // Al abrir la pantalla (o volver a ella) con sesión y SIN flujo local en\n  // curso, preguntamos por el viaje activo del pasajero\n  // (GET /mobility/trips/active). Si existe (requested/accepted/in_progress)\n  // se restaura todo (origen, destino, estado, polling, ruta/cámara) para que\n  // el usuario continúe donde lo dejó aunque la app se hubiera cerrado.\n  const applyResume = useCallback((t: Record<string, any>) => {\n    const st = String(t.status ?? '');\n    if (!['requested', 'accepted', 'in_progress'].includes(st)) return;\n    const plng = Number(t.pickup_lng), plat = Number(t.pickup_lat);\n    const dlng = Number(t.dropoff_lng), dlat = Number(t.dropoff_lat);\n    if (!Number.isFinite(plng) || !Number.isFinite(plat) || !Number.isFinite(dlng) || !Number.isFinite(dlat)) return;\n    lockedTripRef.current = String(t.id);\n    setTripId(String(t.id));\n    setTrip(t);\n    // El pasajero vive en 'accepted' tanto \"conductor en camino\" como \"viaje en\n    // marcha\": el seguimiento en vivo distingue por el status crudo del server.\n    const mapped: 'requested' | 'accepted' = st === 'requested' ? 'requested' : 'accepted';\n    setStatus(mapped);\n    setOrigin([plng, plat]);\n    setOriginLabel(String(t.pickup_address ?? 'Punto de recogida'));\n    setDestCoord([dlng, dlat]);\n    setDestText(String(t.dropoff_address ?? 'Destino'));\n    setUserPrice('');\n    setPassengers(1);\n    setLocBanner(null);\n    setRouteCoords([]); setDistanceKm(0); setEtaMin(null); setRouteError(null);\n    if (st === 'requested') startPolling(String(t.id));\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [startPolling]);\n\n  // Consulta única por foco: solo cuando no hay flujo local activo.\n  useFocusEffect(\n    useCallback(() => {\n      if (!isAuthenticated || status !== 'idle' || !!tripId) return;\n      let alive = true;\n      taxiApi.activeTrip()\n        .then((t) => { if (alive && t) applyResume(t); })\n        .catch(() => { /* sin red o sin sesión: se reintenta al volver a la pestaña */ });\n      return () => { alive = false; };\n    }, [isAuthenticated, status, tripId, applyResume]),\n  );\n\n  // Tras reanudar: dibujar la ruta origen→destino del viaje recuperado y\n  // encuadrar la cámara (solo si aún no hay ruta dibujada en pantalla).\n  useEffect(() => {\n    if (!tripId || status === 'idle' || !origin || !destCoord) return;\n    if (routeCoords.length >= 2 || routeError) return;\n    debouncedFetchRoute(destCoord);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tripId, status]);\n\n  // Al terminar/cancelar el viaje se libera el bloqueo de edición (el GPS de\n  // una próxima sesión podrá volver a fijar el origen con normalidad).\n  useEffect(() => {\n    if (status === 'cancelled' || status === 'completed') lockedTripRef.current = null;\n  }, [status]);\n\n  // ── Destino pre-fijado desde el buscador (geocoder: dLat/dLng/dLabel).\n  const geoDest: Coord | null = useMemo(() => {\n    const lat = Number(dLat);\n    const lng = Number(dLng);\n    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;\n    return [lng, lat];\n  }, [dLat, dLng]);\n\n  // Destino pre-fijado desde la URL (Home → /taxi?dLat&dLng&dLabel). Se aplica\n  // UNA vez por par de coordenadas: si después el usuario cambia el ORIGEN (⇅,\n  // toque, GPS…) no debe volver a pisar el destino elegido. Nunca pisa un\n  // viaje reanudado o ya solicitado.\n  const geoAppliedRef = useRef('');\n  useEffect(() => {\n    if (lockedTripRef.current || status !== 'idle') return;\n    if (!geoDest || !origin) return;\n    const key = `${geoDest[0].toFixed(6)},${geoDest[1].toFixed(6)}`;\n    if (geoAppliedRef.current === key) return;\n    geoAppliedRef.current = key;\n    setDestCoord(geoDest);\n    setDestText(String(dLabel ?? `Punto en el mapa (${geoDest[1].toFixed(4)}, ${geoDest[0].toFixed(4)})`));\n    setUserPrice('');\n    debouncedFetchRoute(geoDest);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [geoDest && geoDest[0], geoDest && geoDest[1], origin]);\n\n  // ── Origen pre-fijado (oLat/oLng/oLabel): el aeropuerto desde la ficha del hotel.\n  const geoOrigin: Coord | null = useMemo(() => {\n    const lat = Number(oLat);\n    const lng = Number(oLng);\n    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;\n    return [lng, lat];\n  }, [oLat, oLng]);\n\n  // Se aplica UNA vez por par de coordenadas y solo si el viaje está en reposo: es la SALIDA del\n  // huésped que llega al aeropuerto, y no puede pisar un viaje en curso ni su GPS si ya se movió.\n  const geoOrigenRef = useRef('');\n  useEffect(() => {\n    if (lockedTripRef.current || status !== 'idle') return;\n    if (!geoOrigin) return;\n    const key = `${geoOrigin[0].toFixed(6)},${geoOrigin[1].toFixed(6)}`;\n    if (geoOrigenRef.current === key) return;\n    geoOrigenRef.current = key;\n    setOrigin(geoOrigin);\n    setOriginLabel(String(oLabel ?? `Salida (${geoOrigin[1].toFixed(4)}, ${geoOrigin[0].toFixed(4)})`));\n    // Con el origen ya fijado, la ruta se recalcula si además hay destino (el caso del hotel).\n    if (destCoord) debouncedFetchRoute(destCoord);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [geoOrigin && geoOrigin[0], geoOrigin && geoOrigin[1], destCoord]);\n\n  // ── Aplica la selección devuelta por el Buscador (origen/destino/atajos). ──\n  useFocusEffect(\n    useCallback(() => {\n      const pick = takeGeoPick();\n      if (!pick || pick.coord[0] === 0) return;\n      // Viaje reanudado o en curso: la selección del buscador no puede pisarlo.\n      if (lockedTripRef.current || status !== 'idle') return;\n      const c: Coord = [pick.coord[0], pick.coord[1]];\n      if (pick.mode === 'origen') {\n        setOrigin(c);\n        setOriginLabel(pick.label);\n        setDestCoord(null); setDestText(''); setRouteCoords([]); setDistanceKm(0);\n        mapRef.current?.setCamera({ centerCoordinate: c, zoomLevel: 14, durationMs: 400 });\n      } else {\n        setDestCoord(c);\n        setDestText(pick.label);\n        setUserPrice('');\n        mapRef.current?.setCamera({ centerCoordinate: c, zoomLevel: 15, durationMs: 400 });\n        debouncedFetchRoute(c);\n      }\n      // eslint-disable-next-line react-hooks/exhaustive-deps\n    }, [origin]),\n  );\n\n  const onMapPress = useCallback(\n    (coord: Coord, meta?: { drag?: boolean; kind?: string }) => {\n      // Tras confirmar (requested/accepted/…) el trayecto queda BLOQUEADO:\n      // no se permite mover origen/destino ni recalcular rutas.\n      if (status !== 'idle') return;\n      const seq = ++revSeq.current;\n      // Un ARRASTRE del pin trae su kind (origin/destination); un toque usa el\n      // modo elegido (moveTarget). Ambos actualizan el punto con un solo gesto.\n      const asOrigin = meta?.kind === 'origin' || (meta?.kind !== 'destination' && moveTarget === 'origen');\n\n      const nameFor = (coordTo: Coord) => {\n        reverseGeocode(coordTo[0], coordTo[1])\n          .then((res) => {\n            if (seq !== revSeq.current) return;\n            const name = pickReverseLabel(res);\n            if (!name) return; // conserva el texto actual si no hay resultado\n            if (asOrigin) setOriginLabel(name);\n            else setDestText(name);\n          })\n          .catch(() => {});\n      };\n\n      if (asOrigin) {\n        setOrigin(coord);\n        setOriginLabel('Punto de partida…');\n        // Vuelve a modo destino para el siguiente toque (DiDi: ajustas y sigues).\n        setMoveTarget('destino');\n        if (!meta?.drag) mapRef.current?.setCamera({ centerCoordinate: coord, zoomLevel: 15, durationMs: 400 });\n        nameFor(coord);\n        if (destCoord) debouncedFetchRoute(destCoord, { fit: !meta?.drag });\n      } else {\n        setDestCoord(coord);\n        setDestText('Destino en el mapa…');\n        setUserPrice('');\n        if (!meta?.drag) mapRef.current?.setCamera({ centerCoordinate: coord, zoomLevel: 15, durationMs: 400 });\n        nameFor(coord);\n        debouncedFetchRoute(coord, { fit: !meta?.drag });\n      }\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [debouncedFetchRoute, destCoord, moveTarget],\n  );\n\n  /** Botón \"ubicarme\": GPS real fresco si el dispositivo está en GQ (punto\n   *  EXACTO donde estás), y si no hay GPS real, centra el origen de ciudad. */\n  const handleLocate = useCallback(async () => {\n    const gps = await getCurrentGqPosition();\n    // Viaje solicitado/en curso: SOLO centrar el mapa, jamás tocar la ruta.\n    if (status !== 'idle') {\n      const c = gps ?? origin;\n      if (c) mapRef.current?.setCamera({ centerCoordinate: c, zoomLevel: gps ? 16 : 14, durationMs: 400 });\n      return;\n    }\n    if (gps) {\n      const seq = ++revSeq.current;\n      setOrigin(gps);\n      setOriginLabel('Mi ubicación…');\n      setLocBanner(null);\n      mapRef.current?.setCamera({ centerCoordinate: gps, zoomLevel: 16, durationMs: 400 });\n      reverseGeocode(gps[0], gps[1])\n        .then((res) => {\n          if (seq !== revSeq.current) return;\n          const n = pickReverseLabel(res);\n          setOriginLabel(n ? `Mi ubicación · ${n}` : `Mi ubicación · ${nearestCityName(gps)}`);\n        })\n        .catch(() => { setOriginLabel(`Mi ubicación · ${nearestCityName(gps)}`); });\n      if (destCoord) debouncedFetchRoute(destCoord, { fit: false });\n    } else {\n      if (origin) mapRef.current?.setCamera({ centerCoordinate: origin, zoomLevel: 14, durationMs: 500 });\n      setLocBanner((prev) => prev ?? 'Sin GPS real: usando la dirección de la ciudad. Toca Desde para cambiarla.');\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [origin, destCoord, debouncedFetchRoute, status]);\n\n  /** Intercambiar origen ↔ destino (icono ⇅ entre los dos puntos, como DiDi):\n   *  el destino pasa a ser la salida y viceversa; se recalcula la ruta. */\n  const handleSwap = useCallback(() => {\n    if (!origin || !destCoord) return;\n    const o = origin;\n    const oLabel = originLabel.trim() || 'Mi ubicación';\n    const dLabel = destText.trim() || 'Destino';\n    // Intercambiamos estados…\n    setOrigin(destCoord);\n    setOriginLabel(dLabel);\n    setDestCoord(o);\n    setDestText(oLabel);\n    setUserPrice('');\n    // …y esperamos al render para que fetchRoute use el NUEVO origen (la\n    // ruta se recalcula desde el destino anterior hacia el origen anterior).\n    setTimeout(() => {\n      debouncedFetchRoute(o, { fit: true });\n    }, 150);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [origin, destCoord, originLabel, destText, debouncedFetchRoute]);\n\n  const onDestText = useCallback((t: string) => {\n    setDestText(t);\n    if (destCoord) { setDestCoord(null); setRouteCoords([]); setDistanceKm(0); setRouteError(null); }\n  }, [destCoord]);\n\n  // ── Modalidades según distancia y ciudad detectada.\n  useEffect(() => {\n    let alive = true;\n    setModesLoading(true);\n    setModesError(null);\n    taxiApi.modes(fareCity, distanceKm)\n      .then((d) => { if (alive) setModes(d?.modes ?? []); })\n      .catch(() => { if (alive) setModesError('No se pudieron cargar las modalidades.'); })\n      .finally(() => { if (alive) setModesLoading(false); });\n    return () => { alive = false; };\n  }, [fareCity, distanceKm]);\n\n  const retryModes = useCallback(() => {\n    setModesLoading(true);\n    setModesError(null);\n    taxiApi.modes(fareCity, distanceKm)\n      .then((d) => setModes(d?.modes ?? []))\n      .catch(() => setModesError('No se pudieron cargar las modalidades.'))\n      .finally(() => setModesLoading(false));\n  }, [fareCity, distanceKm]);\n\n  const mode = useMemo(() => modes.find((m) => m.id === modeId) ?? modes[0], [modes, modeId]);\n  const algoPrice = mode?.price ?? null;\n  // Asientos según modalidad (compartido/minibus) para recalcular por pasajeros.\n  const poolCap = modeId === 'minibus' ? 6 : modeId === 'compartido' ? 3 : 0;\n  const isPool = poolCap > 0;\n  const pax = Math.max(1, Math.min(6, Math.round(passengers || 1)));\n  const usedPax = isPool ? Math.min(pax, poolCap) : pax;\n  // Total sugerido: pool = precio (por asiento) × pasajeros; privado = precio.\n  const suggestedTotal = mode && algoPrice != null\n    ? Math.round(algoPrice * (isPool ? usedPax : 1))\n    : null;\n  // Tarjeta flotante del PIN de DESTINO: \"Llegada X min · X.X km\" (DiDi) — si\n  // aún no hay ruta calculada, muestra la dirección mientras se escribe.\n  const destPinLabel = useMemo(() => {\n    if (!destCoord) return undefined;\n    if (etaMin != null && distanceKm > 0) {\n      return `Llegada: ${etaMin} min · ${distanceKm.toLocaleString('es')} km`;\n    }\n    return destText.trim() || 'Destino';\n  }, [destCoord, etaMin, distanceKm, destText]);\n\n  // ── PRESUPUESTO POR OPCIONES (sin escribir): Malabo 500–10.000 XAF; Bata y\n  // otras ciudades 300–10.000 XAF. El pasajero ELIGE su presupuesto de una\n  // lista fija (decisión del dueño 2026-09-08: evitar ambigüedades). ──\n  const budgetMin = (fareCity || '').trim().toLowerCase() === 'malabo' ? 500 : 300;\n  const budgetMax = 10000;\n  const budgetOptions = useMemo(() => {\n    const steps = [300, 400, 500, 600, 700, 800, 900, 1000, 1200, 1500, 2000, 2500, 3000, 4000, 5000, 6000, 7500, 9000, 10000];\n    return steps.filter((v) => v >= budgetMin && v <= budgetMax);\n  }, [budgetMin]);\n  const up = Number(userPrice);\n  const userPriceOk = userPrice !== '' && !Number.isNaN(up) && up >= budgetMin && up <= budgetMax;\n  const typedWithoutTap = destText.trim() !== '' && !destCoord;\n  const canConfirm = !!origin && !!destCoord && !!mode && userPriceOk && !routeError && status === 'idle' && !typedWithoutTap;\n\n  // Promo publicitaria: el descuento se aplica sobre el presupuesto confirmado.\n  const promoApplied = promo && userPriceOk;\n  const finalPrice = promoApplied ? Math.max(budgetMin, Math.round(up * (100 - promo.pct) / 100)) : up;\n  const promoNote = promoApplied ? `Promo ${promo.title}: ${up.toLocaleString('es')} → ${finalPrice.toLocaleString('es')} XAF (-${promo.pct} %)` : null;\n\n  // ── P1-c LIQUIDACIÓN: propuesta de precio → confirmación PIN → llegada ─────\n  // El conductor acepta y PROPONE precio; el pasajero lo confirma con PIN (el\n  // fare queda BLOQUEADO en el monedero con la comisión congelada por ciudad).\n  // Cancelar: gratis en los primeros 5 min tras aceptar; después, cuota de\n  // absentismo. Llegada del conductor: cierre manual o automático a los 10 min.\n  // El viaje en efectivo solo se REGISTRA (cero dinero en el ledger).\n  const [sv, setSv] = useState<SettlementView | null>(null);\n  const [svBusy, setSvBusy] = useState(false);\n  const [pinOpen, setPinOpen] = useState(false);\n  const [pinValue, setPinValue] = useState('');\n  const [pwdValue, setPwdValue] = useState('');\n  const [needSetPin, setNeedSetPin] = useState(false);\n  const [payErr, setPayErr] = useState<string | null>(null);\n  const [payBusy, setPayBusy] = useState(false);\n  const [dispOpen, setDispOpen] = useState(false);\n  const [dispReason, setDispReason] = useState('');\n  const [dispBusy, setDispBusy] = useState(false);\n  const refreshSv = useCallback(async () => {\n    if (!tripId) { setSv(null); return; }\n    try { setSv(await settlementApi.view(tripId)); } catch { setSv(null); }\n  }, [tripId]);\n  useEffect(() => { void refreshSv(); }, [refreshSv, live.status, status]);\n  const abrirPago = () => { setPayErr(null); setPinValue(''); setNeedSetPin(false); setPinOpen(true); };\n  const confirmarPago = async () => {\n    if (payBusy || !tripId) return;\n    setPayBusy(true); setPayErr(null);\n    try {\n      const fare = Number(sv?.fare ?? 0);\n      if (needSetPin) { await fijarPin(pinValue, pwdValue || undefined); }\n      const token = await tokenDeViaje(pinValue, fare, tripId);\n      await settlementApi.lock(tripId, token, sv?.city ?? null);\n      setPinOpen(false); setPwdValue('');\n      await refreshSv();\n    } catch (e) {\n      const err = e as { code?: string; message?: string };\n      if (!needSetPin) {\n        setNeedSetPin(true);\n        setPayErr('¿Primer pago? Escribe tu contraseña y elige tu PIN de 6 dígitos.');\n      } else {\n        setPayErr(err?.message ?? 'No se pudo confirmar el pago');\n      }\n    } finally { setPayBusy(false); }\n  };\n  const pagarEfectivo = async () => {\n    if (!tripId) return;\n    try { await settlementApi.chooseCash(tripId); await refreshSv(); }\n    catch (e) { setError(e instanceof Error ? e.message : 'No se pudo registrar el efectivo'); }\n  };\n  const cerrarViaje = async () => {\n    if (!tripId || svBusy) return;\n    setSvBusy(true);\n    try { await settlementApi.settle(tripId); await refreshSv(); }\n    catch (e) { setError(e instanceof Error ? e.message : 'No se pudo cerrar el viaje'); }\n    finally { setSvBusy(false); }\n  };\n  const disputar = async () => {\n    if (!tripId || dispBusy || dispReason.trim().length < 10) return;\n    setDispBusy(true);\n    try {\n      await settlementApi.dispute(tripId, dispReason.trim());\n      setDispOpen(false); setDispReason('');\n      await refreshSv();\n      setError('Disputa abierta: el soporte revisará el viaje y, si procede, te devolverá el importe.');\n    } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo abrir la disputa'); }\n    finally { setDispBusy(false); }\n  };\n\n  const confirmar = async () => {\n    if (!canConfirm || busy || !origin || !destCoord) return;\n    if (!isAuthenticated) { router.push('/auth' as any); return; }\n    setBusy(true); setError(null);\n    try {\n      const t = await taxiApi.createTrip({\n        pickupLat: origin[1], pickupLng: origin[0], pickupAddress: originLabel,\n        dropoffLat: destCoord[1], dropoffLng: destCoord[0], dropoffAddress: destText.trim() || 'Punto en el mapa',\n        zoneType: 'inside', requestedPrice: finalPrice, algorithmPrice: suggestedTotal ?? algoPrice ?? undefined,\n        modality: modeId, isPool: isPool,\n        // Compartido: hasta 3 asientos (DiDi \"coche compartido\"); mini bus: 6.\n        maxPoolSeats: isPool ? usedPax : 1,\n        passengers: usedPax,\n        city: fareCity ?? undefined,   // P1-c: la comisión del viaje es por ciudad\n      });\n      setTripId(t.id);\n      setStatus('requested');\n      startPolling(t.id);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo pedir el taxi');\n    } finally { setBusy(false); }\n  };\n\n  // ── P1b DiDi: durante la BÚSQUEDA el pasajero puede re-elegir modalidad,\n  // presupuesto o nº de personas. La solicitud actual se CANCELA y se relanza\n  // automáticamente con los nuevos parámetros (sin volver al paso 1). ────────\n  const relaunch = useCallback(async (patch?: { modeId?: string; price?: string; passengers?: number }) => {\n    if (!origin || !destCoord || relaunching || busy) return;\n    const nextMode = patch?.modeId ?? modeId;\n    const nextCap = nextMode === 'minibus' ? 6 : nextMode === 'compartido' ? 3 : 0;\n    const nextPool = nextCap > 0;\n    const nextPax = Math.max(1, Math.min(6, Math.round(patch?.passengers ?? (passengers || 1))));\n    const nextUsed = nextPool ? Math.min(nextPax, nextCap) : nextPax;\n    const nextPrice = patch?.price ?? userPrice;\n    const nextUp = Number(nextPrice);\n    if (nextPrice === '' || Number.isNaN(nextUp) || nextUp < budgetMin || nextUp > budgetMax) return;\n    const nextModeObj = modes.find((m) => m.id === nextMode) ?? null;\n    setRelaunching(true); setError(null);\n    try {\n      // 1) Cancelar la solicitud actual si existe.\n      if (tripId) await taxiApi.cancelTrip(tripId).catch(() => {});\n      // 2) Relanzar con los nuevos parámetros.\n      const t2 = await taxiApi.createTrip({\n        pickupLat: origin[1], pickupLng: origin[0], pickupAddress: originLabel,\n        dropoffLat: destCoord[1], dropoffLng: destCoord[0], dropoffAddress: destText.trim() || 'Punto en el mapa',\n        zoneType: 'inside', requestedPrice: nextUp,\n        algorithmPrice: nextModeObj?.price ?? undefined,\n        modality: nextMode, isPool: nextPool,\n        maxPoolSeats: nextPool ? nextUsed : 1,\n        passengers: nextUsed,\n        city: fareCity ?? undefined,   // P1-c\n      });\n      setModeId(nextMode);\n      setUserPrice(String(nextUp));\n      if (patch?.passengers) setPassengers(patch.passengers);\n      setTripId(t2.id);\n      setStatus('requested');\n      startPolling(t2.id);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo re-lanzar la solicitud');\n    } finally {\n      setRelaunching(false);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [origin, destCoord, modeId, modes, userPrice, passengers, budgetMin, budgetMax, tripId, relaunching, busy]);\n\n  const handleResetTrip = useCallback(() => {\n    resetTrip();\n    setDestCoord(null); setDestText(''); setRouteCoords([]); setDistanceKm(0); setEtaMin(null); setRouteError(null);\n    setPassengers(1);\n  }, [resetTrip]);\n\n  // ── CANCELACIÓN DEL PASAJERO (DiDi) ───────────────────────────────────────\n  // Al elegir el MOTIVO en el modal, el viaje se cancela DE INMEDIATO (sin\n  // pantalla intermedia). Si el servidor lo rechaza porque el viaje YA terminó\n  // en otra sesión (completed/cancelled/inexistente), también salimos del\n  // estado \"en curso\" local (evita pantallas fantasma). Si está EN MARCHA\n  // (in_progress, conductor ya te recogió) no se cancela y se avisa.\n  const cancelWithReason = useCallback(async (reason?: string) => {\n    if (rejectBusyRef.current) return;\n    rejectBusyRef.current = true;\n    setCancelBusy(true);\n    let cancelled = false;\n    let cuotaMsg: string | null = null;   // P1-c: mensaje con cuota/reembolso cuando hay lock\n    try {\n      if (tripId) {\n        try {\n          if (sv?.money?.locked) {\n            // P1-c: fare bloqueado → la cancelación va por LIQUIDACIÓN: dentro\n            // de la ventana (5 min) vuelve todo; después paga el conductor la\n            // cuota de absentismo y el resto vuelve a tu monedero.\n            const r = await settlementApi.cancel(tripId, reason);\n            cancelled = true;\n            cuotaMsg = Number(r.fee_to_driver) > 0\n              ? `Viaje cancelado: ${Number(r.fee_to_driver).toLocaleString('es')} XAF de cuota y ${Number(r.refunded).toLocaleString('es')} XAF devueltos.`\n              : 'Viaje cancelado: el importe bloqueado volvió entero a tu monedero.';\n          } else {\n            await taxiApi.cancelTrip(tripId, reason);\n            cancelled = true;\n          }\n        } catch (e) {\n          const code = (e as { code?: string })?.code ?? '';\n          if (code === 'SETTLEMENT_REQUIRED') {\n            // El viaje se bloqueó entre medias (otra sesión pagó): reintenta por liquidación.\n            const r = await settlementApi.cancel(tripId, reason);\n            cancelled = true;\n            cuotaMsg = Number(r.fee_to_driver) > 0\n              ? `Viaje cancelado: ${Number(r.fee_to_driver).toLocaleString('es')} XAF de cuota y ${Number(r.refunded).toLocaleString('es')} XAF devueltos.`\n              : 'Viaje cancelado: el importe bloqueado volvió entero a tu monedero.';\n          } else if (code === 'TRIP_NOT_FOUND') {\n            // El viaje ya no existe: nada que cancelar → salir igualmente.\n            cancelled = true;\n          } else if (code === 'TRIP_NOT_CANCELLABLE') {\n            // Comprobar el estado REAL en el servidor antes de decidir.\n            const t = await taxiApi.getTrip(tripId).catch(() => null);\n            const real = String(t?.status ?? '');\n            if (real === 'completed' || real === 'cancelled' || real === '') {\n              // Ya terminó (p. ej. en otra sesión): salir del estado local.\n              cancelled = true;\n            } else {\n              // Sigue activo (in_progress: te recogieron) → no se puede cancelar.\n              throw e;\n            }\n          } else {\n            throw e;\n          }\n        }\n      } else {\n        cancelled = true; // sin viaje en curso local: solo limpiar estado\n      }\n      if (cancelled) {\n        resetTrip();\n        lockedTripRef.current = null; // liberar el bloqueo de edición\n        setError(cuotaMsg ?? 'Viaje cancelado. Puedes pedir otro taxi.');\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No se pudo cancelar el viaje');\n    } finally {\n      rejectBusyRef.current = false;\n      setCancelBusy(false);\n      setCancelOpen(false);\n    }\n  }, [tripId, resetTrip, sv]);\n\n  // Cleanup de peticiones OSRM al desmontar.\n  useEffect(() => () => { if (abortRef.current) abortRef.current.abort(); }, []);\n\n  // Etiqueta de estado: en marcha (in_progress) el chip dice \"Viaje en marcha\".\n  const st = enMarcha ? { t: 'Viaje en marcha', c: brand.primary } : arrived ? { t: 'Has llegado al destino', c: brand.warning } : STATUS_UI[status];\n  const s = styles(colors);\n\n  return (\n    <View style={[s.root, { paddingTop: insets.top }]}>\n      {/* Mapa a pantalla completa (DiDi): panel de tarifas se superpone SIN encoger */}\n      <MapBackground ref={mapRef} style={StyleSheet.absoluteFill} onMapPress={onMapPress} initialCamera={initCam}>\n        <EgMarkers\n          markers={[\n            ...(origin ? [{ id: 'o', coordinate: origin, kind: 'origin' as const, label: originLabel, draggable: status === 'idle' }] : []),\n            ...(destCoord ? [{ id: 'd', coordinate: destCoord, kind: 'destination' as const, label: destPinLabel, draggable: status === 'idle' }] : []),\n            // El coche del conductor se anima por SEPARADO (useDriverLiveTrack →\n            // setCarLive en la página del mapa), no como pin estático de EgMarkers.\n          ]}\n        />\n        {routeCoords.length >= 2 && <EgRoutePolyline coordinates={routeCoords} />}\n      </MapBackground>\n\n      {/* Tarjeta flotante origen → destino (estilo DiDi, sobre el mapa).\n          P2 (2026-09-08): SOLO en idle (pedir taxi). Con viaje en curso\n          (requested/accepted/in_progress) NO se muestra: no se puede cambiar\n          origen ni destino ni el \"modal de poner destino\". */}\n      {status === 'idle' && (\n      <View style={[s.topCard, { top: insets.top + 4, backgroundColor: colors.card, borderColor: colors.border }]}>\n        <View style={s.topCardHeader}>\n          <Pressable\n            onPress={() => router.back()}\n            hitSlop={10}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Volver\"\n            style={s.backBtn}\n          >\n            <ArrowLeft size={20} color={colors.textPrimary} />\n          </Pressable>\n          <View style={{ flex: 1 }}>\n            <View style={s.topCardRow}>\n              <View style={s.stopIconBox}><View style={[s.stopDot, { backgroundColor: brand.success }]} /></View>\n              <Pressable\n                style={{ flex: 1 }}\n                disabled={status !== 'idle'}\n                onPress={() => router.push({ pathname: '/buscar', params: { city: cityParam ?? fareCity, mode: 'origen' } } as never)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={status === 'idle' ? 'Cambiar origen' : 'Origen'}\n              >\n                <Text style={[s.stopValue, { color: status === 'idle' ? colors.textPrimary : colors.textSecondary }]} numberOfLines={1}>{originLabel}</Text>\n              </Pressable>\n              {/* Cambiar la salida con UN TOQUE en el mapa (como el destino) */}\n              {status === 'idle' ? (\n                <Pressable\n                  onPress={() => setMoveTarget((p) => (p === 'origen' ? 'destino' : 'origen'))}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Mover el punto de partida tocando el mapa\"\n                  accessibilityState={{ selected: moveTarget === 'origen' }}\n                  style={[s.mapPickBtn, { backgroundColor: moveTarget === 'origen' ? alphaC(brand.success, 0.16) : 'transparent', borderColor: moveTarget === 'origen' ? brand.success : colors.border }]}\n                >\n                  <Pencil size={14} color={moveTarget === 'origen' ? brand.success : colors.textSecondary} />\n                </Pressable>\n              ) : null}\n            </View>\n            {/* Entre las dos filas: línea vertical + botón ⇅ para INTERCAMBIAR\n                origen ↔ destino (misma columna que los puntos, estilo DiDi). */}\n            <View style={s.connectorGap}>\n              <View style={s.connectorCol}>\n                <View style={[s.connectorVLine, { backgroundColor: colors.border }]} />\n                <Pressable\n                  onPress={handleSwap}\n                  disabled={!destCoord || status !== 'idle'}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Intercambiar origen y destino\"\n                  accessibilityHint=\"El punto de partida y el destino se cambian entre sí y se recalcula la ruta\"\n                  style={[\n                    s.swapBtn,\n                    {\n                      backgroundColor: colors.card,\n                      borderColor: destCoord && status === 'idle' ? colors.primary : colors.border,\n                      opacity: destCoord && status === 'idle' ? 1 : 0.35,\n                    },\n                  ]}\n                >\n                  <ArrowUpDown size={13} color={colors.primary} />\n                </Pressable>\n              </View>\n            </View>\n            <View style={s.topCardRow}>\n              <View style={s.stopIconBox}><View style={[s.stopDot, { backgroundColor: brand.danger }]} /></View>\n              <Pressable\n                style={{ flex: 1 }}\n                disabled={status !== 'idle'}\n                onPress={() => router.push({ pathname: '/buscar', params: { city: cityParam ?? fareCity, mode: 'destino' } } as never)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={status === 'idle' ? 'Cambiar destino' : 'Destino'}\n              >\n                <Text style={[s.stopValueDest, { color: destCoord ? colors.textPrimary : colors.textSecondary }]} numberOfLines={1}>\n                  {destText.trim() || '¿A dónde vas?'}\n                </Text>\n              </Pressable>\n              {destCoord && status === 'idle' ? (\n                <Pressable onPress={handleResetTrip} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Borrar destino\">\n                  <X size={16} color={colors.textSecondary} />\n                </Pressable>\n              ) : null}\n            </View>\n          </View>\n        </View>\n      </View>\n      )}\n\n      {/* Aviso flotante mientras se elige mover el punto de partida */}\n      {status === 'idle' && moveTarget === 'origen' && (\n        <View pointerEvents=\"none\" style={[s.mapHint, { top: insets.top + 126, backgroundColor: 'rgba(0,178,106,0.95)' }]}>\n          <Text style={{ color: brand.white, fontSize: tipografia.caption, fontWeight: '800' }}>🟢 Toca el mapa para cambiar la salida</Text>\n        </View>\n      )}\n\n      {/* Botón flotante de origen: ubicarme por GPS real (o centrar en origen) */}\n      <View style={[s.mapFabRow]}>\n        <Pressable onPress={handleLocate} style={[s.mapFab, { backgroundColor: colors.card, borderColor: colors.border }]} accessibilityRole=\"button\" accessibilityLabel=\"Ubicarme en mi posición actual\">\n          <Navigation size={17} color={colors.primary} />\n        </Pressable>\n      </View>\n\n      {/* Panel inferior superpuesto (no empuja el mapa). P3/P4: en marcha el\n          panel es TRANSPARENTE (sin fondo ni maxHeight) para que el mapa y la\n          ruta dominen; el resto de fases usa su fondo habitual. */}\n      <KeyboardAvoidingView\n        behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n        style={enMarcha\n          ? { position: 'absolute', left: 0, right: 0, bottom: 0, paddingTop: espaciado.e2 }\n          : [s.panel, { backgroundColor: colors.background }]}\n        pointerEvents={enMarcha ? 'box-none' : 'auto'}\n      >\n        {(moveTarget === 'origen' || !destCoord) && !enMarcha && (\n          <View style={[s.askDestBanner, { backgroundColor: moveTarget === 'origen' ? brand.success : colors.overlay }]}>\n            <Text style={{ color: brand.white, fontSize: tipografia.body, fontWeight: '700' }}>\n              {moveTarget === 'origen' ? '🟢 Mueve la SALIDA: toca el mapa' : '👆 Toca el mapa para fijar el destino'}\n            </Text>\n          </View>\n        )}\n        <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps=\"handled\" showsVerticalScrollIndicator={false} scrollEnabled={!enMarcha}>\n          {error && (\n            <View style={[s.banner, { backgroundColor: colors.danger + '14' }]}>\n              <Text style={{ color: colors.danger, fontWeight: '700', fontSize: tipografia.body }}>{error}</Text>\n            </View>\n          )}\n          {locBanner && (\n            <View style={[s.banner, { backgroundColor: colors.surface }]}>\n              <MapPin size={14} color={colors.textSecondary} />\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginLeft: espaciado.e6, fontWeight: '600' }}>{locBanner}</Text>\n            </View>\n          )}\n          {/* FASE 2 DiDi: \"Buscando taxi\" con radar animado (nativo). */}\n          {status === 'requested' && (\n            <View style={{ alignItems: 'center', gap: espaciado.e8, paddingVertical: espaciado.e6 }}>\n              <SearchRadar color={brand.secondary} />\n              <Text style={{ color: brand.secondary, fontWeight: '800', fontSize: 15 }}>\n                {relaunching ? 'Re-lanzando solicitud…' : 'Buscando taxi…'}\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n                {tripId ? `Solicitud ${tripId.slice(0, 8).toUpperCase()}` : 'Enviando solicitud a los conductores cercanos'}\n              </Text>\n\n              {/* P1b: mientras busca, el pasajero puede CAMBIAR modalidad/presupuesto\n                  (la solicitud se cancela y se relanza sola). */}\n              {!searchEdit ? (\n                <Pressable\n                  onPress={() => setSearchEdit(true)}\n                  disabled={relaunching}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Cambiar modalidad, presupuesto o pasajeros mientras buscas\"\n                  style={[s.cancelLink, { borderColor: colors.primary + '66' }]}\n                >\n                  <Text style={{ color: colors.primary, fontWeight: '800', fontSize: tipografia.body }}>\n                    {relaunching ? 'Re-lanzando…' : '⇄ Cambiar modalidad / presupuesto'}\n                  </Text>\n                </Pressable>\n              ) : (\n                <View style={[s.card, { backgroundColor: colors.card, borderColor: colors.border, width: '100%', gap: espaciado.e10 }]}>\n                  <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\n                    <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: tipografia.body }}>\n                      Ajusta tu solicitud\n                    </Text>\n                    <Pressable onPress={() => setSearchEdit(false)} hitSlop={8} accessibilityRole=\"button\" accessibilityLabel=\"Cerrar ajustes\">\n                      <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.caption }}>Listo ✕</Text>\n                    </Pressable>\n                  </View>\n                  <Text style={{ fontSize: 10.5, color: colors.textSecondary, fontWeight: '600' }}>\n                    Se cancela esta búsqueda y se lanza una nueva con tus cambios.\n                  </Text>\n                  {relaunching ? (\n                    <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e10 }} />\n                  ) : (\n                    <>\n                      {modes.length > 0 && (\n                        <View style={{ gap: espaciado.e6 }}>\n                          {modes.map((item) => {\n                            const active = modeId === item.id;\n                            const cap = item.id === 'minibus' ? 6 : item.id === 'compartido' ? 3 : 0;\n                            const total = item.price != null\n                              ? Math.round(item.price * (cap > 0 ? Math.min(pax, cap) : 1))\n                              : null;\n                            return (\n                              <Pressable\n                                key={item.id}\n                                onPress={() => void relaunch({ modeId: item.id })}\n                                accessibilityRole=\"radio\"\n                                accessibilityState={{ checked: active }}\n                                accessibilityLabel={`${item.label}, ${total?.toLocaleString('es') ?? ''} XAF`}\n                                style={[s.modeRow, { backgroundColor: active ? alphaC(colors.primary, 0.07) : colors.surface, borderColor: active ? colors.primary : colors.border, borderWidth: active ? 1.5 : 1 }]}\n                              >\n                                <View style={{ flex: 1 }}>\n                                  <Text style={[s.modeName, { color: colors.textPrimary, fontSize: tipografia.body }]}>{item.label}</Text>\n                                  <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }}>\n                                    ⏱ {item.etaMin} min{cap > 0 ? ` · hasta ${cap} plazas` : ''}\n                                  </Text>\n                                </View>\n                                <View style={{ alignItems: 'flex-end' }}>\n                                  <Text style={{ color: brand.secondary, fontSize: tipografia.body, fontWeight: '800' }}>\n                                    {total != null ? `${total.toLocaleString('es')} XAF` : '—'}\n                                  </Text>\n                                  <Text style={{ fontSize: 10, color: active ? colors.primary : colors.textSecondary, fontWeight: '800' }}>\n                                    {active ? '✓ Solicitando' : 'Elegir'}\n                                  </Text>\n                                </View>\n                              </Pressable>\n                            );\n                          })}\n                        </View>\n                      )}\n                      {/* Presupuesto re-elegible */}\n                      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>\n                        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, fontWeight: '700' }}>Presupuesto</Text>\n                        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, fontWeight: '700' }}>{userPrice ? `${up.toLocaleString('es')} XAF` : '—'}</Text>\n                      </View>\n                      <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e6 }}>\n                        {budgetOptions.slice(0, 8).map((v) => {\n                          const active = Number(userPrice) === v;\n                          return (\n                            <Pressable\n                              key={v}\n                              onPress={() => void relaunch({ price: String(v) })}\n                              style={[s.budgetChip, { borderColor: active ? brand.secondary : colors.border, backgroundColor: active ? alphaC(brand.secondary, 0.12) : colors.surface }]}\n                            >\n                              <Text style={{ fontSize: tipografia.caption, fontWeight: '800', color: active ? brand.secondary : colors.textPrimary }}>\n                                {v.toLocaleString('es')}\n                              </Text>\n                            </Pressable>\n                          );\n                        })}\n                      </View>\n                    </>\n                  )}\n                </View>\n              )}\n\n              <Pressable\n                onPress={() => setCancelOpen(true)}\n                disabled={cancelBusy}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Cancelar búsqueda\"\n                style={[s.cancelLink, { borderColor: colors.border }]}\n              >\n                <Text style={{ color: colors.textSecondary, fontWeight: '700', fontSize: tipografia.body }}>Cancelar búsqueda</Text>\n              </Pressable>\n            </View>\n          )}\n\n          {st && status !== 'requested' && (\n            <View style={[s.statusChip, { backgroundColor: st.c + '14' }]}>\n              <Text style={{ color: st.c, fontWeight: '700', fontSize: tipografia.body }}>\n                {st.t}{trip?.final_price != null ? ` · ${Number(trip.final_price).toLocaleString('es')} XAF` : ''}\n              </Text>\n            </View>\n          )}\n          {/* Señal perdida: >10 s sin un fix nuevo del conductor (coche en gris). */}\n          {live.lost && status === 'accepted' && (\n            <View style={[s.banner, { backgroundColor: '#F53F3F14' }]} accessibilityLiveRegion=\"polite\">\n              <RefreshCw size={14} color={brand.danger} />\n              <Text style={{ color: brand.danger, fontSize: tipografia.caption, marginLeft: espaciado.e6, fontWeight: '700' }}>\n                Señal perdida — esperando al GPS del conductor…\n              </Text>\n            </View>\n          )}\n\n          {/* ── FASE APPROACH (conductor viene a recogerte) ──────────────────\n              Tarjeta COMPLETA del conductor: foto, nombre, MATRÍCULA destacada,\n              valoración/viajes, coche, precio, PIN y acciones. */}\n          {approach && (\n            <View style={[s.card, { backgroundColor: '#27AE600F', borderColor: '#27AE6033', gap: espaciado.e10 }]}>\n              <Text style={{ color: brand.success, fontWeight: '900', fontSize: 15, textAlign: 'center' }}>🚕 Conductor en camino</Text>\n              {(() => {\n                const t = (trip ?? {}) as Record<string, any>;\n                const name = String(t.driver_name ?? 'Conductor');\n                // El backend expone el vehículo con prefijo driver_* (alias).\n                const plate = String(t.driver_plate ?? t.vehicle_plate ?? '');\n                const model = String(t.driver_model ?? t.vehicle_model ?? '');\n                // P1a: color y foto REAL del coche (los añade el backend).\n                const color = String(t.driver_vehicle_color ?? '').trim();\n                const carPhoto = typeof t.driver_vehicle_photo === 'string' && t.driver_vehicle_photo && !t.driver_vehicle_photo.startsWith('captured://') ? absUrl(t.driver_vehicle_photo) : null;\n                const carTxt = [model, plate].filter(Boolean).join(' · ');\n                const photo = typeof t.driver_photo === 'string' && t.driver_photo && !t.driver_photo.startsWith('captured://') ? absUrl(t.driver_photo) : null;\n                const wa = typeof t.driver_phone === 'string' && t.driver_phone.trim() ? t.driver_phone.replace(/\\D/g, '') : null;\n                const tel = wa ? `tel:${wa}` : null;\n                // P1c: valoración y experiencia del conductor.\n                const rating = Number(t.driver_rating);\n                const ratingOk = Number.isFinite(rating) && rating > 0;\n                const trips = Number(t.driver_trips);\n                const tripsOk = Number.isFinite(trips) && trips > 0;\n                const dotColor: Record<string, string> = {\n                  blanco: '#F2F2F2', negro: '#26282C', gris: '#9AA0A6', plata: '#C9CFD6',\n                  rojo: brand.danger, azul: brand.primary, verde: brand.success, amarillo: brand.warning,\n                  naranja: brand.warning, marrón: '#8B5A2B',\n                };\n                return (\n                  <>\n                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }}>\n                      {photo ? (\n                        <Image source={{ uri: photo }} style={s.avatar} />\n                      ) : (\n                        <View style={[s.avatar, { backgroundColor: '#27AE6033' }]}>\n                          <Text style={{ color: brand.success, fontWeight: '900', fontSize: tipografia.title }}>{(name || 'C').charAt(0).toUpperCase()}</Text>\n                        </View>\n                      )}\n                      <View style={{ flex: 1 }}>\n                        <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e6 }}>\n                          <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.subtitle }} numberOfLines={1}>{name}</Text>\n                          {(ratingOk || tripsOk) && (\n                            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e2 }}>\n                              <Star size={12} color={brand.warning} fill={brand.warning} />\n                              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                                {ratingOk ? rating.toFixed(1) : '—'}\n                                {tripsOk ? ` · ${trips} viaje${trips === 1 ? '' : 's'}` : ''}\n                              </Text>\n                            </View>\n                          )}\n                        </View>\n                        {carPhoto ? (\n                          <>\n                            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginTop: espaciado.e2 }}>\n                              <Image source={{ uri: carPhoto }} style={s.carThumb} resizeMode=\"cover\" />\n                              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600', flex: 1 }} numberOfLines={1}>\n                                {carTxt || 'Coche asignado'}\n                              </Text>\n                            </View>\n                            {color && (\n                              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginTop: espaciado.e2 }}>\n                                <View style={[s.colorSwatch, { backgroundColor: dotColor[color.toLowerCase()] ?? '#ccc' }]} />\n                                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>{color}</Text>\n                              </View>\n                            )}\n                          </>\n                        ) : (\n                          <>\n                            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }} numberOfLines={1}>{carTxt || 'Coche asignado'}</Text>\n                            {color && (\n                              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, marginTop: espaciado.e2 }}>\n                                <View style={[s.colorSwatch, { backgroundColor: dotColor[color.toLowerCase()] ?? '#ccc' }]} />\n                                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '600' }}>{color}</Text>\n                              </View>\n                            )}\n                          </>\n                        )}\n                      </View>\n                      <View style={{ alignItems: 'flex-end' }}>\n                        <Text style={{ color: brand.secondary, fontWeight: '900', fontSize: tipografia.subtitle }}>\n                          {t.final_price != null ? `${Number(t.final_price).toLocaleString('es')} XAF` : '—'}\n                        </Text>\n                        <Text style={{ color: colors.textSecondary, fontSize: 10.5 }}>Precio acordado</Text>\n                      </View>\n                    </View>\n                    {/* Matrícula DESTACADA (P1): placa visible de un vistazo */}\n                    {plate ? (\n                      <View style={s.plateBox}>\n                        <Text style={s.plateTxt}>{plate.toUpperCase()}</Text>\n                      </View>\n                    ) : null}\n                    <Text style={{ fontSize: tipografia.body, color: colors.textPrimary, fontWeight: '600', textAlign: 'center' }}>\n                      El conductor te pedirá este PIN para empezar el viaje:\n                    </Text>\n                    <Text style={{ fontSize: 30, fontWeight: '900', letterSpacing: 6, color: brand.success, textAlign: 'center' }}>\n                      {pinLast4(phone)}\n                    </Text>\n                    {(wa || tel) && (\n                      <View style={{ flexDirection: 'row', gap: espaciado.e8 }}>\n                        {tel ? (\n                          <Pressable\n                            onPress={() => Linking.openURL(tel).catch(() => setError('No se pudo abrir el teléfono.'))}\n                            accessibilityRole=\"button\"\n                            accessibilityLabel=\"Llamar al conductor\"\n                            style={[s.waBtn, { flex: 1, backgroundColor: brand.success }]}\n                          >\n                            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>📞 Llamar</Text>\n                          </Pressable>\n                        ) : null}\n                        {wa ? (\n                          <Pressable\n                            onPress={() => {\n                              const msg = encodeURIComponent('Hola, soy tu pasajero de EG Route Plan. ¿Vienes de camino?');\n                              Linking.openURL(`https://wa.me/${wa}?text=${msg}`).catch(() =>\n                                setError('No se pudo abrir WhatsApp. Instálalo o escribe por teléfono.'));\n                            }}\n                            accessibilityRole=\"button\"\n                            accessibilityLabel=\"Contactar por WhatsApp\"\n                            style={[s.waBtn, { flex: 2, backgroundColor: brand.whatsapp }]}\n                          >\n                            <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>WhatsApp</Text>\n                          </Pressable>\n                        ) : null}\n                      </View>\n                    )}\n                  </>\n                );\n              })()}\n              {/* ── P1-c LIQUIDACIÓN: confirmar el precio propuesto con PIN ─────\n                  El bloque deja de ser palabra de honor: el fare sale de tu\n                  monedero SOLO si lo confirmas con PIN, y al cerrar cobra el\n                  conductor el NETO (la comisión se la queda la plataforma). */}\n              {sv && sv.state === 'proposed' && Number(sv.fare) > 0 && (\n                <View style={{ gap: espaciado.e8 }}>\n                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                      Comisión EG ({sv.city ?? fareCity}) · al conductor {Number(sv.net).toLocaleString('es')} XAF\n                    </Text>\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '800' }}>{Number(sv.fee).toLocaleString('es')} XAF</Text>\n                  </View>\n                  <PrimaryButton\n                    title={`Confirmar precio y pagar · ${Number(sv.fare).toLocaleString('es')} XAF`}\n                    onPress={abrirPago}\n                  />\n                  <Pressable\n                    onPress={pagarEfectivo}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel=\"Pagar en efectivo al conductor\"\n                    style={{ paddingVertical: espaciado.e4, alignItems: 'center' }}\n                  >\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, fontWeight: '700', textDecorationLine: 'underline' }}>\n                      Prefiero pagar en efectivo al llegar\n                    </Text>\n                  </Pressable>\n                </View>\n              )}\n              {sv?.money.locked && !sv.money.released && (\n                <View style={{ padding: espaciado.e10, borderRadius: radios.md, borderWidth: 1, borderColor: '#27AE6055', backgroundColor: '#27AE6010' }}>\n                  <Text style={{ color: brand.success, fontWeight: '900', fontSize: tipografia.body }}>\n                    💳 {Number(sv.fare).toLocaleString('es')} XAF bloqueados con tu PIN\n                  </Text>\n                  <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, marginTop: espaciado.e2 }}>\n                    {(() => {\n                      const until = sv.timers.free_cancel_until ? new Date(sv.timers.free_cancel_until).getTime() : 0;\n                      const mins = Math.max(0, Math.round((until - Date.now()) / 60000));\n                      return mins > 0\n                        ? `Tienes ${mins} min para cancelarlo sin coste; después, cuota de absentismo.`\n                        : 'Fuera de la ventana gratis: cancelarlo deja al conductor la cuota de absentismo.';\n                    })()}\n                  </Text>\n                </View>\n              )}\n              {sv?.state === 'cash' && (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n                  Viaje en efectivo: paga al conductor al terminar. Queda registrado sin cargo en tu monedero.\n                </Text>\n              )}\n              <Pressable\n                onPress={() => setCancelOpen(true)}\n                disabled={cancelBusy}\n                accessibilityRole=\"button\"\n                accessibilityLabel=\"Rechazar o cancelar el viaje\"\n                style={[s.cancelLink, { borderColor: '#F53F3F55' }]}\n              >\n                <Text style={{ color: brand.danger, fontWeight: '700', fontSize: tipografia.body }}>Rechazar / Cancelar viaje</Text>\n              </Pressable>\n            </View>\n          )}\n\n          {/* ── FASE LLEGADA (P1-c): el conductor avisó; el pasajero cierra o ──\n              el servidor auto-cierra a los 10 min. Sin confirmación no hay\n              payout; con disputa, el admin puede devolver el viaje entero. */}\n          {arrived && (\n            <View style={[s.card, { backgroundColor: '#F6B1000F', borderColor: '#F6B10033', gap: espaciado.e10 }]}>\n              <Text style={{ color: colors.textPrimary, fontWeight: '900', fontSize: 15, textAlign: 'center' }}>\n                🏁 El conductor dice que habéis llegado\n              </Text>\n              <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n                ¿Te ha dejado ya? Confirma y el conductor cobra su parte del importe bloqueado.\n              </Text>\n              <PrimaryButton title={svBusy ? 'Cerrando…' : 'Confirmar llegada y cerrar'} onPress={cerrarViaje} disabled={svBusy} loading={svBusy} />\n              {sv?.timers.auto_close_at && (\n                <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center' }}>\n                  Sin tu confirmación se cerrará solo en{' '}\n                  {Math.max(0, Math.round((new Date(sv.timers.auto_close_at).getTime() - Date.now()) / 60000))} min.\n                  {' '}¿Ha habido un problema?{' '}\n                  <Text onPress={() => setDispOpen(true)} style={{ color: brand.primary, fontWeight: '800' }}>Disputar</Text>\n                </Text>\n              )}\n            </View>\n          )}\n\n          {/* ── FASE EN MARCHA (conductor te recogió, viaje in_progress) ──────\n              El mapa es el protagonista (ruta + coche animado). Tarjeta MINIMA\n              transparente: nombre del conductor, perfil y contacto. Sin PIN,\n              sin cancelar ni editar. */}\n          {enMarcha && (\n            <View pointerEvents=\"box-none\" style={{ paddingVertical: espaciado.e4 }}>\n              <View style={[s.card, { backgroundColor: 'rgba(15,20,28,0.45)', borderColor: 'rgba(255,255,255,0.18)', gap: espaciado.e6, alignItems: 'center' }]}>\n                <Text style={{ color: brand.white, fontWeight: '900', fontSize: tipografia.body }}>🚗 Viaje en marcha</Text>\n                {(() => {\n                  const t = (trip ?? {}) as Record<string, any>;\n                  const name = String(t.driver_name ?? 'Conductor');\n                  const plate = String(t.driver_plate ?? t.vehicle_plate ?? '');\n                  const model = String(t.driver_model ?? t.vehicle_model ?? '');\n                  const photo = typeof t.driver_photo === 'string' && t.driver_photo && !t.driver_photo.startsWith('captured://') ? absUrl(t.driver_photo) : null;\n                  const wa = typeof t.driver_phone === 'string' && t.driver_phone.trim() ? t.driver_phone.replace(/\\D/g, '') : null;\n                  const tel = wa ? `tel:${wa}` : null;\n                  return (\n                    <>\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e10 }}>\n                        {photo ? (\n                          <Image source={{ uri: photo }} style={{ width: 40, height: 40, borderRadius: 20 }} />\n                        ) : (\n                          <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: 'rgba(255,255,255,0.18)', alignItems: 'center', justifyContent: 'center' }}>\n                            <Text style={{ color: brand.white, fontWeight: '900', fontSize: 18 }}>{(name || 'C').charAt(0).toUpperCase()}</Text>\n                          </View>\n                        )}\n                        <View style={{ flex: 1 }}>\n                          <Text style={{ color: brand.white, fontWeight: '800', fontSize: 15 }} numberOfLines={1}>{name}</Text>\n                          <Text style={{ color: 'rgba(255,255,255,0.75)', fontSize: tipografia.caption, fontWeight: '600' }}>\n                            {[model, plate].filter(Boolean).join(' · ') || 'Conductor'}\n                          </Text>\n                        </View>\n                      </View>\n                      {(wa || tel) ? (\n                        <View style={{ flexDirection: 'row', gap: espaciado.e8, alignSelf: 'stretch' }}>\n                          {tel ? (\n                            <Pressable\n                              onPress={() => Linking.openURL(tel).catch(() => setError('No se pudo abrir el teléfono.'))}\n                              accessibilityRole=\"button\"\n                              accessibilityLabel=\"Llamar al conductor\"\n                              style={[s.waBtn, { flex: 1, backgroundColor: 'rgba(255,255,255,0.9)' }]}\n                            >\n                              <Text style={{ color: '#0F141C', fontWeight: '800', fontSize: tipografia.body }}>📞 Llamar</Text>\n                            </Pressable>\n                          ) : null}\n                          {wa ? (\n                            <Pressable\n                              onPress={() => {\n                                const msg = encodeURIComponent('Hola, soy tu pasajero de EG Route Plan. ¿Vamos bien?');\n                                Linking.openURL(`https://wa.me/${wa}?text=${msg}`).catch(() => setError('No se pudo abrir WhatsApp.'));\n                              }}\n                              accessibilityRole=\"button\"\n                              accessibilityLabel=\"Contactar por WhatsApp\"\n                              style={[s.waBtn, { flex: 2, backgroundColor: brand.whatsapp }]}\n                            >\n                              <Text style={{ color: brand.white, fontWeight: '800', fontSize: tipografia.body }}>WhatsApp</Text>\n                            </Pressable>\n                          ) : null}\n                        </View>\n                      ) : null}\n                    </>\n                  );\n                })()}\n              </View>\n            </View>\n          )}\n\n          {status === 'idle' && distanceKm > 0 && (\n            <View style={[s.summaryRow, { backgroundColor: colors.surface }]}>\n              <View style={{ flex: 1 }}>\n                <Text style={[s.summaryOrigin, { color: colors.textPrimary }]} numberOfLines={1}>🟢 {originLabel}</Text>\n                <Text style={[s.summaryDest, { color: colors.textPrimary }]} numberOfLines={1}>🟠 {destText || 'Destino'}</Text>\n              </View>\n              <Text style={[s.summaryKm, { color: colors.textSecondary }]}>\n                {etaMin != null ? `${etaMin} min` : '—'} · {distanceKm} km\n              </Text>\n            </View>\n          )}\n          {status === 'idle' && routeError && (\n            <View style={{ flexDirection: 'row', alignItems: 'center' }}>\n              <RefreshCw size={14} color={colors.danger} />\n              <Text style={{ fontSize: tipografia.caption, color: colors.danger, marginLeft: espaciado.e4, flex: 1 }}>{routeError}</Text>\n            </View>\n          )}\n\n          {status === 'idle' && (\n          <>\n          <Text style={s.sectionTitle}>Modalidad de viaje</Text>\n          {modesLoading ? (\n            <ActivityIndicator style={{ marginVertical: espaciado.e12 }} color={colors.primary} />\n          ) : modesError ? (\n            <View style={[s.card, { backgroundColor: colors.danger + '08' }]}>\n              <Text style={{ fontSize: tipografia.caption, color: colors.danger }}>{modesError}</Text>\n              <GhostButton title=\"Reintentar\" onPress={retryModes} />\n            </View>\n          ) : modes.length === 0 ? (\n            <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginVertical: espaciado.e8 }}>\n              Sin modalidades para esta distancia todavía.\n            </Text>\n          ) : (\n            // Lista vertical estilo DiDi: fila por modalidad con precio a la derecha\n            // (ref. flow2.xml / flow3.xml de DiDi: 一口价 + descuento + selección).\n            <View style={{ gap: espaciado.e8 }}>\n              {modes.map((item) => {\n                const active = modeId === item.id;\n                const Icon = MODE_ICON[item.id] ?? <CarFront size={20} color={colors.textSecondary} />;\n                const cap = item.id === 'minibus' ? 6 : item.id === 'compartido' ? 3 : 0;\n                const rowPax = cap > 0 ? Math.min(pax, cap) : pax;\n                const rowTotal = item.price != null ? Math.round(item.price * (cap > 0 ? rowPax : 1)) : null;\n                return (\n                  <Pressable\n                    key={item.id}\n                    onPress={() => { setModeId(item.id); if (cap > 0 && passengers > cap) setPassengers(cap); }}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ checked: active }}\n                    accessibilityLabel={`${item.label}, ${rowTotal?.toLocaleString('es') ?? ''} XAF, ${item.etaMin} min`}\n                    testID={`taxi-mode-${item.id}`}\n                    style={({ pressed }) => [\n                      s.modeRow,\n                      {\n                        backgroundColor: colors.card,\n                        borderColor: active ? colors.primary : colors.border,\n                        borderWidth: active ? 1.5 : 1,\n                        opacity: pressed ? 0.85 : 1,\n                      },\n                    ]}\n                  >\n                    <View style={[s.modeIconWrap, { backgroundColor: active ? alphaC(colors.primary, 0.12) : colors.surface }]}>\n                      {Icon}\n                    </View>\n                    <View style={{ flex: 1 }}>\n                      <Text style={[s.modeName, { color: colors.textPrimary }]}>{item.label}</Text>\n                      <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: 1 }}>\n                        ⏱ {item.etaMin} min{cap > 0 ? ` · hasta ${cap} plazas` : ''}\n                      </Text>\n                    </View>\n                    <View style={{ alignItems: 'flex-end' }}>\n                      <Text style={[s.modePrice, { color: brand.secondary }]}>\n                        {rowTotal != null ? `${rowTotal.toLocaleString('es')} XAF` : '—'}\n                      </Text>\n                      <Text style={{ fontSize: 10, color: active ? colors.primary : colors.textSecondary, fontWeight: '700' }}>\n                        {active ? '✓ Seleccionado' : 'Elegir'}\n                      </Text>\n                    </View>\n                  </Pressable>\n                );\n              })}\n            </View>\n          )}\n\n          {/* Selector de PASAJEROS (DiDi, 1–6): cambia el total de compartidos */}\n          {destCoord && (\n            <View style={[s.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n              <Text style={s.sectionTitle}>Pasajeros</Text>\n              <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e2 }}>\n                {isPool\n                  ? `Precio por asiento × ${usedPax} · máx. ${poolCap} en ${mode?.label ?? 'esta modalidad'}`\n                  : `Carrera privada · precio por coche${pax > 1 ? ` (${pax} pasajeros)` : ''}`}\n              </Text>\n              <View style={s.paxRow}>\n                {[1, 2, 3, 4, 5, 6].map((n) => {\n                  const over = isPool && n > poolCap;\n                  const active = n === usedPax;\n                  return (\n                    <Pressable\n                      key={n}\n                      onPress={() => setPassengers(n)}\n                      disabled={over}\n                      accessibilityRole=\"radio\"\n                      accessibilityState={{ checked: active, disabled: over }}\n                      accessibilityLabel={`${n} pasajero${n > 1 ? 's' : ''}${over ? ` (máximo ${poolCap} en ${mode?.label})` : ''}`}\n                      style={[s.paxChip, {\n                        backgroundColor: active ? alphaC(colors.primary, 0.14) : colors.surface,\n                        borderColor: active ? colors.primary : colors.border,\n                        opacity: over ? 0.3 : 1,\n                      }]}\n                    >\n                      <Text style={[s.paxNum, { color: active ? colors.primary : colors.textPrimary }]}>{n}</Text>\n                      <Text style={{ fontSize: 9, color: active ? colors.primary : colors.textSecondary, fontWeight: '700' }}>\n                        {n === 1 ? 'persona' : 'personas'}\n                      </Text>\n                    </Pressable>\n                  );\n                })}\n              </View>\n            </View>\n          )}\n\n          <View style={[s.card, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={s.label}>Tu presupuesto (elige uno) · {budgetMin}–{budgetMax.toLocaleString('es')} XAF · {fareCity}</Text>\n            <View style={s.budgetWrap}>\n              {budgetOptions.map((v) => {\n                const active = Number(userPrice) === v;\n                return (\n                  <Pressable\n                    key={v}\n                    onPress={() => setUserPrice(String(v))}\n                    accessibilityRole=\"radio\"\n                    accessibilityState={{ checked: active }}\n                    accessibilityLabel={`${v.toLocaleString('es')} XAF`}\n                    style={[s.budgetChip, {\n                      backgroundColor: active ? alphaC(brand.secondary, 0.14) : colors.surface,\n                      borderColor: active ? brand.secondary : colors.border,\n                    }]}\n                  >\n                    <Text style={[s.budgetTxt, { color: active ? brand.secondary : colors.textPrimary }]}>\n                      {v.toLocaleString('es')} XAF\n                    </Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n            {userPrice !== '' && !userPriceOk && (\n              <Text style={{ fontSize: tipografia.micro, color: colors.danger, marginTop: espaciado.e4 }}>\n                El presupuesto debe estar entre {budgetMin} y {budgetMax.toLocaleString('es')} XAF\n              </Text>\n            )}\n            <View style={{ flexDirection: 'row', gap: espaciado.e10, marginTop: espaciado.e12 }}>\n              <View style={[s.priceBox, { backgroundColor: colors.surface }]}>\n                <Text style={{ fontSize: 17, fontWeight: '800', color: colors.textPrimary }}>\n                  {suggestedTotal != null ? `${suggestedTotal.toLocaleString('es')} XAF` : '—'}\n                </Text>\n                <Text style={{ fontSize: 10, color: colors.textSecondary }}>\n                  Precio {mode?.label}{isPool ? ` × ${usedPax}` : ''}\n                </Text>\n                <Text style={{ fontSize: 10, color: colors.primary, fontWeight: '700' }}>{distanceKm || '—'} km · {etaMin != null ? `${etaMin} min` : '—'}</Text>\n              </View>\n              <View style={[s.priceBox, { backgroundColor: colors.surface }]}>\n                <Text style={{ fontSize: 17, fontWeight: '800', color: userPriceOk ? brand.secondary : colors.textSecondary }}>\n                  {userPriceOk ? `${up.toLocaleString('es')} XAF` : '—'}\n                </Text>\n                <Text style={{ fontSize: 10, color: colors.textSecondary }}>Tu presupuesto</Text>\n                <Text style={{ fontSize: 10, color: colors.textSecondary }}>{budgetMin}–{budgetMax.toLocaleString('es')} XAF</Text>\n              </View>\n            </View>\n          </View>\n          </>\n          )}\n\n          {(status === 'cancelled' || status === 'completed') && (\n            <View style={[s.card, { backgroundColor: colors.card, borderColor: colors.border, alignItems: 'center' }]}>\n              <Text style={{ fontSize: tipografia.subtitle, fontWeight: '800', color: colors.textPrimary }}>{st?.t}</Text>\n              {tripId && <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e4 }}>Ref: {tripId.slice(0, 8)}</Text>}\n              {/* P1-c: resumen de la liquidación + puerta de disputa (7 días). */}\n              {sv && (sv.state === 'settled' || sv.state === 'disputed') && sv.kind === 'WALLET' && (\n                <View style={{ alignSelf: 'stretch', gap: espaciado.e4, padding: espaciado.e10, borderRadius: 10, backgroundColor: colors.surface, borderWidth: 1, borderColor: colors.border, marginTop: espaciado.e6 }}>\n                  <Text style={{ color: colors.textPrimary, fontWeight: '800', fontSize: tipografia.body }}>\n                    {sv.state === 'disputed' ? '⚖️ Viaje en disputa (en revisión)' : 'Liquidación del viaje'}\n                  </Text>\n                  {sv.money.released && (\n                    <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption }}>\n                      Tarifa {Number(sv.fare).toLocaleString('es')} · comisión {Number(sv.fee).toLocaleString('es')} · al conductor {Number(sv.net).toLocaleString('es')} XAF\n                    </Text>\n                  )}\n                  {sv.state === 'settled' && (\n                    <Text onPress={() => setDispOpen(true)} style={{ color: brand.primary, fontSize: tipografia.caption, fontWeight: '800' }}>\n                      ¿Problemas con el viaje? Disputar (hasta 7 días)\n                    </Text>\n                  )}\n                </View>\n              )}\n              {status === 'completed' && (\n                <GhostButton\n                  title=\"Puntuar mi viaje\"\n                  onPress={() => { setRatingScore(5); setRatingComment(''); setRatingOpen(true); }}\n                />\n              )}\n              <GhostButton title=\"Ir al inicio\" onPress={() => router.replace('/' as never)} />\n            </View>\n          )}\n        </ScrollView>\n\n        {status === 'idle' && (\n          <View style={[s.footer, { borderTopColor: colors.border }]}>\n            {promoNote && (\n              <Text style={{ textAlign: 'center', fontSize: tipografia.caption, color: colors.success, fontWeight: '800', marginBottom: espaciado.e6 }}>\n                {promoNote}\n              </Text>\n            )}\n            <PrimaryButton\n              title={busy ? 'Enviando…' : userPriceOk ? `Confirmar taxi · ${finalPrice.toLocaleString('es')} XAF` : 'Confirmar taxi'}\n              onPress={confirmar}\n              disabled={!canConfirm || busy}\n              loading={busy}\n            />\n            {!destCoord && destText.trim() !== '' && (\n              <Text style={{ textAlign: 'center', fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e6 }}>\n                Toca el mapa para fijar el destino y poder confirmar.\n              </Text>\n            )}\n            {!userPriceOk && (\n              <Text style={{ textAlign: 'center', fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e6 }}>\n                Elige tu presupuesto ({budgetMin}–{budgetMax.toLocaleString('es')} XAF en {fareCity}) para confirmar.\n              </Text>\n            )}\n            {!isAuthenticated && (\n              <Text style={{ textAlign: 'center', fontSize: tipografia.micro, color: colors.textSecondary, marginTop: espaciado.e6 }}>\n                Al confirmar crearás tu cuenta.\n              </Text>\n            )}\n          </View>\n        )}\n      </KeyboardAvoidingView>\n\n      {/* Modal de motivos de cancelación (DiDi): elegir motivo = CANCELAR el\n          viaje de inmediato y volver al panel de pedir taxi. */}\n      <Modal visible={cancelOpen} transparent animationType=\"fade\" onRequestClose={() => { if (!cancelBusy) setCancelOpen(false); }}>\n        <View style={s.modalOverlay}>\n          <View style={[s.modalCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}>\n              ¿Por qué cancelas el viaje?\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e4 }}>\n              {cancelBusy ? 'Cancelando el viaje…' : 'Tu conductor será liberado y podrá atender a otros pasajeros.'}\n            </Text>\n            {cancelBusy ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e18 }} />\n            ) : (\n              <View style={{ gap: espaciado.e8, marginTop: espaciado.e14 }}>\n                {REJECT_REASONS.map((r) => (\n                  <Pressable\n                    key={r}\n                    onPress={() => cancelWithReason(r)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`Cancelar el viaje · Motivo: ${r}`}\n                    style={[s.reasonRow, { backgroundColor: colors.surface, borderColor: colors.border }]}\n                  >\n                    <Text style={{ color: colors.textPrimary, fontSize: tipografia.body, fontWeight: '700' }}>{r}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            )}\n            <GhostButton title=\"Volver\" onPress={() => setCancelOpen(false)} disabled={cancelBusy} />\n          </View>\n        </View>\n      </Modal>\n\n      {/* P1e: valorar al conductor al terminar el viaje (1–5 estrellas). */}\n      <Modal visible={ratingOpen} transparent animationType=\"fade\" onRequestClose={() => { if (!ratingBusy) setRatingOpen(false); }}>\n        <View style={s.modalOverlay}>\n          <View style={[s.modalCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}>\n              ¿Cómo fue tu viaje?\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e4 }}>\n              Valora a tu conductor (también le sirve de referencia a otros pasajeros).\n            </Text>\n            <View style={{ flexDirection: 'row', justifyContent: 'center', gap: espaciado.e10, marginTop: espaciado.e16 }}>\n              {[1, 2, 3, 4, 5].map((n) => (\n                <Pressable\n                  key={n}\n                  onPress={() => setRatingScore(n)}\n                  disabled={ratingBusy}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`${n} de 5 estrellas`}\n                  hitSlop={6}\n                >\n                  <Star size={34} color={n <= ratingScore ? brand.warning : colors.border} fill={n <= ratingScore ? brand.warning : 'transparent'} />\n                </Pressable>\n              ))}\n            </View>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.micro, textAlign: 'center', marginTop: espaciado.e6, fontWeight: '700' }}>\n              {ratingScore >= 4 ? '¡Excelente! 🎉' : ratingScore === 3 ? 'Bien, gracias 😊' : 'Gracias por tu honestidad 🙏'}\n            </Text>\n            <TextInput\n              style={[s.ratingInput, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n              placeholder=\"Comentario opcional…\"\n              placeholderTextColor={colors.textSecondary}\n              value={ratingComment}\n              onChangeText={setRatingComment}\n              editable={!ratingBusy}\n              maxLength={280}\n            />\n            <View style={{ gap: espaciado.e10, marginTop: espaciado.e12 }}>\n              <PrimaryButton\n                title={ratingBusy ? 'Enviando…' : 'Enviar valoración'}\n                onPress={async () => {\n                  if (!tripId || ratingBusy) return;\n                  setRatingBusy(true);\n                  try {\n                    await taxiApi.rateTrip(tripId, ratingScore, ratingComment.trim() || undefined);\n                    // P5: al puntuar → volver al Home.\n                    setRatingOpen(false);\n                    router.replace('/' as never);\n                  } catch (e) {\n                    setError(e instanceof Error ? e.message : 'No se pudo enviar la valoración');\n                    setRatingOpen(false);\n                  } finally { setRatingBusy(false); }\n                }}\n                disabled={ratingBusy}\n                loading={ratingBusy}\n              />\n              <GhostButton\n                title=\"Ahora no\"\n                onPress={() => { setRatingOpen(false); router.replace('/' as never); }}\n                disabled={ratingBusy}\n              />\n            </View>\n          </View>\n        </View>\n      </Modal>\n\n      {/* P1-c: teclado PIN para confirmar el fare (token TRIP + lock en escrow).\n          Si el usuario aún no tiene PIN de 6 dígitos, el primer fallo abre el\n          alta: contraseña de la cuenta + PIN nuevo (un solo paso). */}\n      <Modal visible={pinOpen} transparent animationType=\"fade\" onRequestClose={() => { if (!payBusy) setPinOpen(false); }}>\n        <View style={s.modalOverlay}>\n          <View style={[s.modalCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}>\n              Confirmar {Number(sv?.fare ?? 0).toLocaleString('es')} XAF\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e4 }}>\n              {needSetPin\n                ? 'Primer pago: escribe tu contraseña y elige un PIN de 6 dígitos.'\n                : 'Introduce tu PIN para bloquear el importe en tu monedero.'}\n            </Text>\n            {needSetPin && (\n              <TextInput\n                style={[s.ratingInput, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary, marginTop: espaciado.e12 }]}\n                placeholder=\"Contraseña de tu cuenta\"\n                placeholderTextColor={colors.textSecondary}\n                value={pwdValue}\n                onChangeText={setPwdValue}\n                secureTextEntry\n                autoCorrect={false}\n                editable={!payBusy}\n              />\n            )}\n            <TextInput\n              style={[s.ratingInput, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary, marginTop: needSetPin ? 8 : 12, textAlign: 'center', fontSize: 22, letterSpacing: 8 }]}\n              placeholder=\"••••••\"\n              placeholderTextColor={colors.textSecondary}\n              value={pinValue}\n              onChangeText={(t) => setPinValue(t.replace(/\\D/g, '').slice(0, 6))}\n              secureTextEntry\n              keyboardType=\"number-pad\"\n              maxLength={6}\n              editable={!payBusy}\n              autoFocus\n            />\n            {payErr && (\n              <Text style={{ color: brand.danger, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e8 }}>{payErr}</Text>\n            )}\n            {payBusy ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e18 }} />\n            ) : (\n              <View style={{ gap: espaciado.e10, marginTop: espaciado.e14 }}>\n                <PrimaryButton\n                  title={needSetPin ? 'Guardar PIN y pagar' : 'Pagar ahora'}\n                  onPress={confirmarPago}\n                  disabled={pinValue.length !== 6 || (needSetPin && pwdValue.length < 4)}\n                />\n                <GhostButton title=\"Volver\" onPress={() => setPinOpen(false)} />\n              </View>\n            )}\n          </View>\n        </View>\n      </Modal>\n\n      {/* P1-c: disputa del viaje (ventana de 7 días tras el cierre). */}\n      <Modal visible={dispOpen} transparent animationType=\"fade\" onRequestClose={() => { if (!dispBusy) setDispOpen(false); }}>\n        <View style={s.modalOverlay}>\n          <View style={[s.modalCard, { backgroundColor: colors.card, borderColor: colors.border }]}>\n            <Text style={{ color: colors.textPrimary, fontSize: 17, fontWeight: '900', textAlign: 'center' }}>\n              Disputar este viaje\n            </Text>\n            <Text style={{ color: colors.textSecondary, fontSize: tipografia.caption, textAlign: 'center', marginTop: espaciado.e4 }}>\n              Cuéntanos qué pasó. Mientras el soporte revisa la disputa el dinero no se mueve; si tienes razón, te devolvemos el importe completo.\n            </Text>\n            <TextInput\n              style={[s.ratingInput, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary, marginTop: espaciado.e12, minHeight: 72 }]}\n              placeholder=\"Motivo (mínimo 10 caracteres)…\"\n              placeholderTextColor={colors.textSecondary}\n              value={dispReason}\n              onChangeText={setDispReason}\n              multiline\n              maxLength={280}\n              editable={!dispBusy}\n            />\n            {dispBusy ? (\n              <ActivityIndicator color={colors.primary} style={{ marginVertical: espaciado.e18 }} />\n            ) : (\n              <View style={{ gap: espaciado.e10, marginTop: espaciado.e12 }}>\n                <PrimaryButton title=\"Enviar disputa\" onPress={disputar} disabled={dispReason.trim().length < 10} />\n                <GhostButton title=\"Volver\" onPress={() => setDispOpen(false)} />\n              </View>\n            )}\n          </View>\n        </View>\n      </Modal>\n\n      {busy && <ActivityIndicator color={colors.primary} style={s.loading} />}\n    </View>\n  );\n}\n\nconst styles = (c: ReturnType<typeof useTheme>['colors']) =>\n  StyleSheet.create({\n    root: { flex: 1, backgroundColor: c.background },\n    topBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8 },\n    title: { fontSize: 18, fontWeight: '800', color: c.textPrimary },\n    banner: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', marginHorizontal: espaciado.e16, marginBottom: espaciado.e4, borderRadius: radios.sm, paddingVertical: espaciado.e8, paddingHorizontal: espaciado.e12 },\n    statusChip: { alignSelf: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e8, marginBottom: espaciado.e4 },\n    mapHint: { position: 'absolute', top: 120, alignSelf: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e6 },\n    // Tarjeta flotante origen → destino (DiDi): compacta, sobre el mapa.\n    topCard: {\n      position: 'absolute', top: 4, left: 10, right: 10,\n      borderRadius: 18, borderWidth: 1, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4,\n      ...elevation.md,\n    },\n    topCardHeader: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 },\n    backBtn: { padding: espaciado.e2, marginRight: espaciado.e2 },\n    topCardRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, minHeight: 27 },\n    stopIconBox: { width: 15, alignItems: 'center' },\n    stopDot: { width: 10, height: 10, borderRadius: 5 },\n    connectorRow: { width: 2, height: 8, marginLeft: espaciado.e7, marginVertical: 1, borderRadius: 1 },\n    connectorGap: { height: 26, marginVertical: 0 },\n    connectorCol: { width: 16, height: '100%', alignItems: 'center', justifyContent: 'center', position: 'relative' },\n    connectorVLine: { position: 'absolute', left: 7, top: 0, bottom: 0, width: 2, borderRadius: 1 },\n    swapBtn: { width: 24, height: 24, borderRadius: radios.md, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center', zIndex: 2, elevation: 3 },\n    stopLabel: { fontSize: 9, fontWeight: '700', textTransform: 'uppercase', letterSpacing: 0.4 },\n    stopValue: { fontSize: tipografia.body, fontWeight: '700', marginLeft: espaciado.e2 },\n    stopValueDest: { fontSize: tipografia.body, fontWeight: '800', marginLeft: espaciado.e2 },\n    mapPickBtn: { width: 28, height: 28, borderRadius: 14, borderWidth: 1, alignItems: 'center', justifyContent: 'center', marginLeft: espaciado.e4 },\n    // FAB centrar (abajo-derecha sobre el mapa, visible al colapsar panel)\n    mapFabRow: { position: 'absolute', right: 14, bottom: 84 },\n    mapFab: { borderRadius: 30, borderWidth: 1, padding: espaciado.e11, ...elevation.md },\n    // Panel inferior superpuesto: NO empuja el mapa (DiDi).\n    panel: {\n      position: 'absolute', left: 0, right: 0, bottom: 0,\n      maxHeight: '46%', borderTopLeftRadius: 22, borderTopRightRadius: 22,\n      paddingTop: espaciado.e2,\n      ...elevation.lg,\n    },\n    askDestBanner: { alignSelf: 'center', borderRadius: radios.full, paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e7, marginVertical: espaciado.e6 },\n    summaryRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e10, borderRadius: 14, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e9 },\n    summaryOrigin: { fontSize: tipografia.body, fontWeight: '700' },\n    summaryDest: { fontSize: tipografia.body, fontWeight: '800', marginTop: espaciado.e2 },\n    summaryKm: { fontSize: 15, fontWeight: '800' },\n    content: { padding: espaciado.e16, paddingBottom: espaciado.e14, gap: espaciado.e12 },\n    card: { borderRadius: radios.lg, padding: espaciado.e14, borderWidth: 1 },\n    label: { fontSize: tipografia.caption, fontWeight: '700', color: c.textSecondary },\n    input: { fontSize: 15, padding: 0, marginTop: espaciado.e4 },\n    sectionTitle: { fontSize: 15, fontWeight: '800', color: c.textPrimary, marginTop: espaciado.e2 },\n    modeRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, borderRadius: radios.lg, padding: espaciado.e12 },\n    modeIconWrap: { width: 40, height: 40, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center' },\n    modeName: { fontSize: 15, fontWeight: '800' },\n    modePrice: { fontSize: 17, fontWeight: '800' },\n    avatar: { width: 44, height: 44, borderRadius: 22, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },\n    carThumb: { width: 34, height: 26, borderRadius: 6, overflow: 'hidden', backgroundColor: '#EAEAEA' },\n    colorSwatch: { width: 12, height: 12, borderRadius: 6, borderWidth: 0.6, borderColor: 'rgba(0,0,0,0.2)' },\n    waBtn: { borderRadius: 14, paddingVertical: espaciado.e12, alignItems: 'center', marginTop: espaciado.e2 },\n    cancelLink: { borderRadius: radios.full, borderWidth: 1, paddingVertical: espaciado.e7, paddingHorizontal: espaciado.e18, alignSelf: 'center', marginTop: espaciado.e2 },\n    modalOverlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)', alignItems: 'center', justifyContent: 'center', paddingHorizontal: espaciado.e24 },\n    modalCard: { width: '100%', maxWidth: 420, borderRadius: 20, borderWidth: 1, padding: espaciado.e20 },\n    ratingInput: { borderRadius: radios.md, borderWidth: 1, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e10, fontSize: tipografia.body, marginTop: espaciado.e12, minHeight: 46 },\n    reasonRow: { borderRadius: radios.md, borderWidth: 1, paddingVertical: espaciado.e13, paddingHorizontal: espaciado.e14 },\n    paxRow: { flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e10 },\n    paxChip: { flex: 1, alignItems: 'center', borderRadius: radios.md, borderWidth: 1.5, paddingVertical: espaciado.e8, gap: 1 },\n    paxNum: { fontSize: tipografia.subtitle, fontWeight: '900' },\n    budgetWrap: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e8 },\n    budgetChip: { borderRadius: radios.full, borderWidth: 1.2, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7 },\n    budgetTxt: { fontSize: tipografia.body, fontWeight: '800' },\n    priceRow: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderWidth: 1, borderRadius: radios.md, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8, marginTop: espaciado.e6 },\n    priceBox: { flex: 1, borderRadius: radios.md, padding: espaciado.e10, alignItems: 'center' },\n    // Matrícula DESTACADA del coche (estilo placa, P1).\n    plateBox: { alignSelf: 'center', borderWidth: 1.5, borderColor: '#2B2F36', borderRadius: 6, paddingHorizontal: espaciado.e18, paddingVertical: espaciado.e5, backgroundColor: '#F5F7FA', marginTop: espaciado.e2 },\n    plateTxt: { fontSize: 19, fontWeight: '900', letterSpacing: 2, color: '#14171C' },\n    footer: { padding: espaciado.e14, paddingBottom: espaciado.e18, borderTopWidth: 1 },\n    loading: { position: 'absolute', top: '50%', alignSelf: 'center' },\n  });\n","/**\n * DriverLiveMap — seguimiento EN VIVO del conductor para la pantalla del\n * PASAJERO (estilo DiDi): mapa 2D plano (sin pitch ni rotación) con el coche\n * animado suavemente entre posiciones.\n *\n * ── Arquitectura (decidida y aprobada 2026-09-06) ──────────────────────────\n *  · Polling cada 2,5 s a GET /mobility/trips/:id (el endpoint real que ya\n *    devuelve driver_lat/driver_lng/status/driver_updated_at — equivalente al\n *    /viajes/:id/estado del spec). Lógica en `useDriverLiveTrack` (este fichero).\n *  · La INTERPOLACIÓN corre DENTRO de la página del mapa (map-v2.html →\n *    `setCarLive`): bucle requestAnimationFrame con easing EASE-IN-OUT de 2 s\n *    (coincide con el polling) y GEO-LERP sobre círculo máximo (la Tierra es\n *    redonda: no se suma lat/lng linealmente; equivalente a turf.along sin\n *    dependencia de turf). Si un fix nuevo llega ANTES de terminar la\n *    animación, se ENCADENA desde la posición pintada (cero saltos).\n *    ¿Por qué aquí y no RAF en RN? Porque el marcador vive en el WebView:\n *    interpolar en RN obligaría a cruzar el puente ~60 veces/segundo; con un\n *    solo mensaje por fix (cada 2,5 s) el movimiento es idéntico y fluido.\n *  · Rumbo: `driver_heading` del backend si algún día lo envía; hoy se\n *    calcula entre última y penúltima posición recibidas.\n *  · >10 s sin fix nuevo → `lost` (chip \"⚠️ Señal perdida\") y marcador GRIS.\n *  · status 'completed'/'cancelled' → polling detenido + onEnded + coche limpiado.\n *\n * Uso:\n *  · Integrado en taxi.tsx: `useDriverLiveTrack({ tripId, mapRef, onEnded })`\n *    sobre el mapa que la pantalla ya tiene.\n *  · O standalone: `<DriverLiveMap tripId=\"…\" origin dest routeCoords onEnded />`\n *    (pantalla de rastreo propia con su mapa, pins y chip de señal).\n */\n\nimport React, { useEffect, useRef, useState } from 'react';\nimport { StyleSheet, Text, View, type StyleProp, type ViewStyle } from 'react-native';\nimport MapBackground from './MapBackground';\nimport { EgMarkers, EgRoutePolyline, type Coord, type EgMapViewHandle } from '../packages/map';\nimport { taxiApi } from '../api/taxi';\nimport { brand, espaciado, radios, tipografia } from '@egrouteplan/ui-kit';\n\n// ─── Tipos TypeScript (públicos) ────────────────────────────────────────────\n\n/** Estados finales que detienen el tracking. */\nexport type TripFinalStatus = 'completed' | 'cancelled';\n\n/** Un fix de posición del conductor (coordenadas [lon,lat] del heartbeat). */\nexport interface DriverLiveFix {\n  lng: number;\n  lat: number;\n  /** Rumbo (grados, 0=norte). null → todavía no se pudo calcular. */\n  heading: number | null;\n  /** driver_updated_at del backend (timestamp del heartbeat, si viene). */\n  serverAt: string | null;\n}\n\n/** Estado que expone el hook de tracking. */\nexport interface DriverLiveState {\n  /** status crudo del viaje ('requested'|'accepted'|'in_progress'|…). */\n  status: string | null;\n  /** Último fix válido recibido (null hasta el primero). */\n  fix: DriverLiveFix | null;\n  /** true si no llega ningún fix NUEVO hace > staleMs → \"Señal perdida\". */\n  lost: boolean;\n}\n\nexport interface UseDriverLiveTrackParams {\n  /** Viaje a seguir. null → inactivo (limpia marcador y detiene polling). */\n  tripId: string | null;\n  /** Ref del mapa (EgMapViewHandle) donde vive el coche animado. */\n  mapRef: React.RefObject<EgMapViewHandle | null>;\n  /** Periodo de polling. 2,5 s por spec (la anim de 2 s lo solapa sin hueco). */\n  pollMs?: number;\n  /** Segundos sin fix nuevo para declarar \"Señal perdida\" (spec: 10 s). */\n  staleMs?: number;\n  /** Duración de cada tramo de animación (spec: 2 s). */\n  animMs?: number;\n  /** Zoom al que se ENTRA en modo seguimiento (solo el primer fix). */\n  followZoom?: number;\n  /** Dispara UNA vez al pasar a 'completed' o 'cancelled' (polling ya parado). */\n  onEnded?: (s: TripFinalStatus) => void;\n}\n\n// ─── Utilidades de rumbo (mismas fórmulas que la página del mapa) ───────────\n\n/** Rumbo en grados (0=norte) de la posición a a la b (plano local, <100 m). */\nfunction bearingDeg(a: Coord, b: Coord): number {\n  const r = Math.PI / 180;\n  const dLo = (b[0] - a[0]) * Math.cos(((a[1] + b[1]) / 2) * r);\n  const dLa = b[1] - a[1];\n  return (Math.atan2(dLo, dLa) * 180 / Math.PI + 360) % 360;\n}\n\n// ─── Hook: polling + rumbo + señal perdida + parada (todo el \"cerebro\") ─────\n\nexport function useDriverLiveTrack({\n  tripId, mapRef, pollMs = 2500, staleMs = 10000, animMs = 2000,\n  followZoom = 15.8, onEnded,\n}: UseDriverLiveTrackParams): DriverLiveState {\n  const [state, setState] = useState<DriverLiveState>({ status: null, fix: null, lost: false });\n  // Última y penúltima posición → rumbo (spec 4). Usamos refs para no provocar\n  // renders extra; el estado visible solo cambia cuando hay fix nuevo.\n  const prevFixRef = useRef<DriverLiveFix | null>(null);\n  const lastBeatRef = useRef<number>(0);          // Date.now() del último fix NUEVO visto\n  const serverBeatRef = useRef<string | null>(null); // driver_updated_at visto\n  const onEndedRef = useRef(onEnded);\n  onEndedRef.current = onEnded;\n\n  useEffect(() => {\n    // Reset total al cambiar de viaje o desconectar el tracking.\n    prevFixRef.current = null;\n    lastBeatRef.current = 0;\n    serverBeatRef.current = null;\n    setState({ status: null, fix: null, lost: false });\n    if (!tripId) { mapRef.current?.clearCarLive?.(); return; }\n\n    let alive = true;\n    let ended = false;\n    let timer: ReturnType<typeof setInterval> | null = null;\n\n    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };\n\n    const tick = async () => {\n      if (ended) return;\n      let t: Record<string, any>;\n      try {\n        t = await taxiApi.getTrip(tripId);\n      } catch {\n        // Red caída: NO rompemos nada; `lost` se declara solo por tiempo.\n        setState((s) => ({ ...s, lost: lastBeatRef.current > 0 && Date.now() - lastBeatRef.current > staleMs }));\n        return;\n      }\n      if (!alive || ended) return;\n\n      const st = String(t?.status ?? '');\n      // ── Spec 5b: finalizado/cancelado → DETENER el polling. ──\n      if (st === 'completed' || st === 'cancelled') {\n        ended = true;\n        stop();\n        mapRef.current?.clearCarLive?.();\n        setState((s) => ({ ...s, status: st, lost: false }));\n        onEndedRef.current?.(st);\n        return;\n      }\n\n      const lng = Number(t?.driver_lng);\n      const lat = Number(t?.driver_lat);\n      const serverAt = t?.driver_updated_at ? String(t.driver_updated_at) : null;\n      if (!Number.isFinite(lng) || !Number.isFinite(lat) || st === 'requested') {\n        // Conductor aún sin posición publicada.\n        setState((s) => ({ ...s, status: st || s.status }));\n        return;\n      }\n\n      // ── Fix nuevo: lo detecta un heartbeat nuevo (driver_updated_at) o, si el\n      //    backend no lo trae, una posición distinta. Eso marca la \"última\n      //    actualización\" para el contador de Señal perdida (>10 s → gris). ──\n      const prev = prevFixRef.current;\n      const moved = !prev || Math.abs(prev.lng - lng) + Math.abs(prev.lat - lat) > 1e-7;\n      const newBeat = serverAt ? serverAt !== serverBeatRef.current : moved;\n      if (newBeat) lastBeatRef.current = Date.now();\n      serverBeatRef.current = serverAt;\n\n      // ── Spec 4: rumbo = heading GPS si viene; si no, última↔penúltima. ──\n      let heading: number | null =\n        (t?.driver_heading != null && Number.isFinite(Number(t.driver_heading))) ? Number(t.driver_heading) : null;\n      if (heading == null) {\n        if (prev && moved) heading = bearingDeg([prev.lng, prev.lat], [lng, lat]);\n        else heading = prev?.heading ?? null; // quieto → conserva el último rumbo\n      }\n\n      const fix: DriverLiveFix = { lng, lat, heading, serverAt };\n      prevFixRef.current = fix;\n      const lost = lastBeatRef.current > 0 && Date.now() - lastBeatRef.current > staleMs;\n\n      // ── Spec 3: animación (rAF + ease-in-out 2 s + encadenado) → página. ──\n      // follow SOLO en 'in_progress' (coche en marcha): la cámara lo persigue.\n      // Durante 'accepted' (conductor en camino) NO secuestra el mapa: la\n      // pantalla del pasajero encuadra coche+recogida con fitBounds.\n      mapRef.current?.setCarLive?.({ lng, lat, heading, stale: lost, durationMs: animMs, follow: st === 'in_progress' });\n      setState({ status: st, fix, lost });\n    };\n\n    tick();\n    timer = setInterval(tick, pollMs);\n    return () => { alive = false; stop(); };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tripId]);\n\n  return state;\n}\n\n// ─── Componente funcional completo (mapa + marcador + polling + chip) ───────\n\nexport interface DriverLiveMapProps {\n  /** Viaje a seguir en vivo (null → sin tracking, solo mapa base). */\n  tripId: string | null;\n  /** Pin de origen (recogida). */\n  origin?: Coord | null;\n  /** Pin de destino. */\n  destination?: Coord | null;\n  /** Ruta restante a dibujar (opcional; p. ej. recogida→destino). */\n  routeCoords?: Coord[];\n  /** Cámara con la que abre (hasta que llega el primer fix del coche). */\n  initialCamera?: { centerCoordinate: Coord; zoomLevel?: number };\n  /** Notifica viaje finalizado/cancelado (polling ya detenido por el hook). */\n  onEnded?: (s: TripFinalStatus) => void;\n  style?: StyleProp<ViewStyle>;\n}\n\n/**\n * Pantalla/vista de rastreo del pasajero COMPLETA: mapa 2D plano, pins de\n * origen/destino, ruta opcional, coche animado (hook) y banner \"Señal perdida\".\n */\nexport function DriverLiveMap({\n  tripId, origin, destination, routeCoords, initialCamera, onEnded, style,\n}: DriverLiveMapProps) {\n  const mapRef = useRef<EgMapViewHandle>(null);\n  const live = useDriverLiveTrack({ tripId, mapRef, onEnded });\n\n  return (\n    <View style={[StyleSheet.absoluteFill, style]}>\n      <MapBackground ref={mapRef} initialCamera={initialCamera}>\n        <EgMarkers\n          markers={[\n            ...(origin ? [{ id: 'o', coordinate: origin, kind: 'origin' as const }] : []),\n            ...(destination ? [{ id: 'd', coordinate: destination, kind: 'destination' as const }] : []),\n          ]}\n        />\n        {routeCoords && routeCoords.length >= 2 ? <EgRoutePolyline coordinates={routeCoords} /> : null}\n      </MapBackground>\n\n      {/* Spec 5a: sin actualización >10 s → aviso visible (y el coche se pinta\n          gris desde el hook, vía setCarLive stale=true). */}\n      {live.lost ? (\n        <View style={[styles.lostChip, { backgroundColor: 'rgba(31,41,55,0.92)' }]} accessibilityLiveRegion=\"polite\">\n          <Text style={styles.lostTxt}>⚠️ Señal perdida — esperando al GPS del conductor…</Text>\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  lostChip: {\n    position: 'absolute', top: 86, alignSelf: 'center',\n    paddingHorizontal: espaciado.e14, paddingVertical: espaciado.e8, borderRadius: radios.full,\n  },\n  lostTxt: { color: brand.white, fontSize: tipografia.caption, fontWeight: '700' },\n});\n\nexport default DriverLiveMap;\n","/**\n * Layout de la ZONA DEL COMERCIANTE (`/tienda`).\n *\n * Es un modo dentro de la app: barra propia, cabeceras propias y el comerciante no sale de aquí para\n * moverse entre sus cuatro cosas. El patrón de la casa para modos era una pantalla-hub con tarjetas\n * (Ser Conductor, Mi restaurante); aquí se usa un **grupo de rutas** porque las pestañas tienen que\n * compartir la barra y el estado de cada una sin desmontarse.\n *\n * `animation: 'none'` en el Stack: cambiar de pestaña no es navegar a otro sitio, es cambiar de\n * pestaña —una transición lateral ahí miente sobre la jerarquía.\n */\n\nimport React from 'react';\nimport { StyleSheet, View } from 'react-native';\nimport { Stack } from 'expo-router';\nimport BarraTienda from '../../components/ecomerse/BarraTienda';\n\nexport default function TiendaLayout() {\n  return (\n    <View style={styles.raiz}>\n      <View style={styles.contenido}>\n        <Stack screenOptions={{ headerShown: false, animation: 'none' }} />\n      </View>\n      <BarraTienda />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  raiz: { flex: 1 },\n  contenido: { flex: 1 },\n});\n","/**\n * BarraTienda — barra inferior PROPIA de la zona del comerciante (`/tienda`).\n *\n * POR QUÉ EXISTE\n * Hasta el 20-sep-2026 el comerciante era un **desvío dentro de Mercado**: se entraba por la misma\n * celda que el comprador, pasando por un modal («¿Comprar o Vender?»), y su pantalla era **un solo\n * formulario de 1.110 líneas** con las ventas como enlace de texto en la cabecera. No había zona.\n *\n * La zona es un **modo dentro de la app**, igual que «Ser Conductor» o «Mi restaurante», pero con\n * barra propia: el comerciante no sale de su zona para moverse entre sus cuatro cosas. Es la misma\n * separación que hacen Lilishop (`seller-api` + 店铺管理端) y Mall4j (`mall4cloud-multishop`): la\n * zona del vendedor se separa **en la arquitectura**, no con permisos dentro de una pantalla\n * compartida.\n *\n * CUATRO PESTAÑAS, NO CINCO\n * Pinduoduo tiene cinco porque tiene cinco módulos con datos (商品/订单/营销/我的 + 首页). Aquí hay\n * tres con datos y uno de identidad, y **una pestaña vacía es peor que una pestaña ausente**: eso es\n * exactamente lo que ya limpiamos del Mercado. Las cinco de Pinduoduo se quedan en cuatro:\n * Resumen · Anuncios · Pedidos · Tienda.\n *\n * DETALLE QUE NO ES ADORNO: `accessibilityState={{ selected }}` y `accessibilityRole=\"tab\"`. Una\n * barra que no comunica en qué pestaña está deja al lector de pantalla sin saber dónde está.\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ClipboardList, LayoutDashboard, Package, Store, type LucideIcon } from 'lucide-react-native';\nimport { elevation, espaciado, icono, peso, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { usePathname, useRouter } from 'expo-router';\n\n/** Altura de la barra sin el área segura. La usan las pantallas como relleno inferior. */\nexport const BARRA_TIENDA_H = 62;\n\nexport interface PestanaTienda {\n  id: string;\n  label: string;\n  icon: LucideIcon;\n  ruta: string;\n}\n\n/** Orden decidido: primero lo que hay que hacer, después lo que se administra, y al final la tienda. */\nexport const PESTANAS_TIENDA: PestanaTienda[] = [\n  { id: 'resumen', label: 'Resumen', icon: LayoutDashboard, ruta: '/tienda' },\n  { id: 'anuncios', label: 'Anuncios', icon: Package, ruta: '/tienda/anuncios' },\n  { id: 'pedidos', label: 'Pedidos', icon: ClipboardList, ruta: '/tienda/pedidos' },\n  { id: 'perfil', label: 'Tienda', icon: Store, ruta: '/tienda/perfil' },\n];\n\n/**\n * Pantallas de la zona SIN barra. Publicar es un flujo de captura a pantalla completa (se entra\n * desde Anuncios y se sale con el trabajo hecho o cancelado), no una quinta pestaña: dejarla con\n * barra invitaría a abandonar el formulario a medias sin decirlo.\n *\n * `combinaciones` entra por lo mismo (fase 4): es la edición de un anuncio concreto —sus ejes, sus\n * precios, sus unidades— con su propio botón de guardar. Es hermana de `publicar`, no de las\n * pestañas: si tuviera barra, la mitad de las salidas del editor no guardarían nada.\n */\nconst SIN_BARRA = ['/tienda/publicar', '/tienda/combinaciones'];\n\nexport default function BarraTienda() {\n  const { colors } = useTheme();\n  const insets = useSafeAreaInsets();\n  const router = useRouter();\n  const ruta = usePathname();\n\n  if (SIN_BARRA.includes(ruta)) return null;\n\n  return (\n    <View\n      style={[\n        styles.barra,\n        {\n          backgroundColor: colors.card,\n          borderTopColor: colors.border,\n          paddingBottom: insets.bottom,\n          height: BARRA_TIENDA_H + insets.bottom,\n        },\n      ]}\n    >\n      {PESTANAS_TIENDA.map((p) => {\n        // `/tienda` es prefijo de todas: sin la comparación exacta, Resumen saldría activo siempre.\n        const activa = p.ruta === '/tienda' ? ruta === '/tienda' : ruta.startsWith(p.ruta);\n        const tinte = activa ? colors.primary : colors.textSecondary;\n        const Icon = p.icon;\n        return (\n          <Pressable\n            key={p.id}\n            onPress={() => { if (!activa) router.replace(p.ruta as never); }}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected: activa }}\n            accessibilityLabel={p.label}\n            style={({ pressed }) => [styles.item, { opacity: pressed ? 0.6 : 1 }]}\n          >\n            <Icon size={icono.md} color={tinte} strokeWidth={activa ? trazo.marcado : trazo.fuerte} />\n            <Text style={[styles.label, { color: tinte }, activa && styles.labelActiva]} numberOfLines={1}>\n              {p.label}\n            </Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  barra: {\n    flexDirection: 'row',\n    alignItems: 'stretch',\n    borderTopWidth: trazo.fino,\n    ...elevation.lg,\n  },\n  item: {\n    flex: 1,\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: espaciado.e4 / 2,\n    paddingVertical: espaciado.e8,\n  },\n  label: { fontSize: tipografia.micro, fontWeight: peso.fuerte },\n  labelActiva: { fontWeight: peso.titulo },\n});\n","/**\n * Anuncios — la pestaña donde el comerciante administra lo que vende.\n *\n * ES LA PANTALLA QUE HACE UTILIZABLE LA FASE 1\n * El 20-sep-2026 se desplegaron en el backend los DOS CARRILES (`PATCH seller/products/:id/operations`\n * y `PATCH seller/products/:id/state`). Hasta esta pantalla existían **sin nadie que los llamara**:\n * el cliente de API los declaraba y ninguna pantalla los usaba, así que «pausar» y «retirar» seguían\n * siendo imposibles desde la app. Aquí se cablean.\n *\n * LA REGLA DE LOS DOS CARRILES, EN UNA FRASE\n * *La moderación aprueba el anuncio; el comerciante administra la operación.*\n *   · RÁPIDO (esta pantalla, sin moderación): existencias · plazo · devoluciones · pausar/retirar.\n *   · MODERADO (formulario de publicación): título · fotos · precio · categoría. Ese es el que el\n *     moderador juzgó, y cambiarlo por debajo invalidaría su aprobación — por eso «Corregir» manda a\n *     `publicar?id=…` y vuelve a revisión, como debe.\n *\n * TRES HONESTIDADES QUE SE VEN EN PANTALLA\n *  1. Se pinta el estado que devuelve el SERVIDOR, no el que se pidió. Si pides «a la venta» con 0\n *     existencias, el servidor contesta `sold_out` y la fila lo dice: poner a la venta lo que no se\n *     puede entregar es peor que no venderlo.\n *  2. «Retirado» no es «borrado». El anuncio sigue existiendo (fotos, documentos, historial de ventas)\n *     y se puede deshacer: la retirada del comerciante es una decisión suya, y un toque equivocado\n *     tiene que poder deshacerse.\n *  3. Las visitas y los favoritos son **del anuncio, no de la tienda**, y se muestran por anuncio.\n *     Sumarlos y llamarlo «tráfico de mi tienda» sería inventar un número.\n *\n * CERO CONSULTAS NUEVAS\n * Todo sale de `myProducts()` (que ya devuelve `stock`, `status`, `handlingHours`, `returnsAccepted`,\n * `views` y `favoriteCount`) y de `sellerMe()` para saber si la tienda está aprobada. No hay endpoint\n * de estadísticas del vendedor y no se inventa.\n */\n\nimport React, { useCallback, useMemo, useState } from 'react';\nimport { Pressable, RefreshControl, ScrollView, StyleSheet, Switch, Text, useWindowDimensions, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { Image } from 'expo-image';\nimport {\n  AlertTriangle, ChevronRight, Eye, Heart, ImageOff, Layers, Minus, PackagePlus, Pause, Play, Plus,\n  Settings2, Trash2,\n} from 'lucide-react-native';\nimport {\n  Aviso, EmptyState, GhostButton, InlineError, PrimaryButton, Sheet, alpha, espaciado, icono,\n  altura, peso, radios, tipografia, trazo, useAviso, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseProduct, type EcomerseSellerMe } from '../../api/ecomerse';\nimport { formatXAF } from '../../utils/formatHelpers';\nimport { BARRA_TIENDA_H } from '../../components/ecomerse/BarraTienda';\n\n/** Plazos de preparación que admite el servidor (`handlingHours`). Cerrado a propósito: es una\n *  promesa al comprador, no un número libre. */\nconst PLAZOS = [24, 48, 72] as const;\n\n/**\n * El vocabulario de estados, con el color de cada uno.\n * `paused` y `removed` aparecen aquí porque desde el 20-sep-2026 **existen de verdad**: hasta ese día\n * `paused` era una etiqueta muerta (la app la traducía y ninguna ruta podía escribirla).\n */\nconst ESTADOS: Record<string, { label: string; tono: 'bien' | 'aviso' | 'peligro' | 'neutro' }> = {\n  active: { label: 'A la venta', tono: 'bien' },\n  sold_out: { label: 'Agotado', tono: 'aviso' },\n  paused: { label: 'Pausado', tono: 'neutro' },\n  pending: { label: 'En revisión', tono: 'neutro' },\n  draft: { label: 'Borrador', tono: 'neutro' },\n  rejected: { label: 'Rechazado', tono: 'peligro' },\n  removed: { label: 'Retirado', tono: 'peligro' },\n};\n\n/**\n * Los filtros. Cada uno es un ESTADO ACCIONABLE, no una métrica: el comerciante entra a «Agotados»\n * cuando va a reponer, no a mirar. Un filtro vacío no se pinta (ver `visibles`) — es la misma regla\n * que ya se aplicó al Mercado: una pestaña vacía es peor que una pestaña ausente.\n */\nconst FILTROS: Array<{ id: string; label: string; acepta: (p: EcomerseProduct) => boolean }> = [\n  { id: 'todos', label: 'Todos', acepta: () => true },\n  { id: 'venta', label: 'A la venta', acepta: (p) => p.status === 'active' && p.stock > 0 },\n  { id: 'agotados', label: 'Agotados', acepta: (p) => p.status === 'sold_out' || (p.status === 'active' && p.stock <= 0) },\n  { id: 'pausados', label: 'Pausados', acepta: (p) => p.status === 'paused' },\n  { id: 'revision', label: 'Sin aprobar', acepta: (p) => p.status === 'pending' || p.status === 'draft' },\n  { id: 'rechazados', label: 'Rechazados', acepta: (p) => p.status === 'rejected' },\n  { id: 'retirados', label: 'Retirados', acepta: (p) => p.status === 'removed' },\n];\n\nexport default function TiendaAnuncios() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [aviso, mostrarAviso, ocultarAviso] = useAviso();\n\n  const [me, setMe] = useState<EcomerseSellerMe | null>(null);\n  const [productos, setProductos] = useState<EcomerseProduct[]>([]);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [filtro, setFiltro] = useState('todos');\n  /** Id del anuncio con una operación en vuelo: bloquea SUS botones, no los de los demás. */\n  const [ocupado, setOcupado] = useState<string | null>(null);\n  const [enGestion, setEnGestion] = useState<EcomerseProduct | null>(null);\n\n  /**\n   * EL ALTO DEL CONTENIDO DE LA HOJA, Y POR QUÉ SE CALCULA.\n   *\n   * `Sheet` topa la hoja al **80 % de la pantalla** (`hojaAbajo.maxHeight`), pero el tope es de la\n   * hoja, no de lo de dentro: **no scrollea sola**, y lo que desborda se pierde. Con la sección de\n   * combinaciones (fase 4) el contenido pasó de ese 80 % y lo que quedó fuera fue el tramo final\n   * —«Corregir anuncio» y las devoluciones—, o sea funciones que dejan de existir sin que nada lo\n   * diga. Se mide: sobre 616 dp de pantalla, la hoja dispone de 493 dp y el cromo fijo de arriba\n   * (relleno 20 + título y subtítulo 58 + relleno inferior 22) se come ~100, así que la lista se\n   * queda en `altoPantalla × 0,8 − 110`. El mismo cálculo que usa el selector de variante.\n   */\n  const { height: altoPantalla } = useWindowDimensions();\n  const altoHoja = Math.max(200, Math.round(altoPantalla * 0.8) - 110);\n\n  const cargar = useCallback(async (esRefresco = false) => {\n    if (esRefresco) setRefrescando(true); else setCargando(true);\n    setError(null);\n    try {\n      /* `sellerMe` trae la tienda Y sus anuncios; `myProducts` es la lista que administramos. Se\n         piden las dos porque la primera dice si la tienda está aprobada (y sin aprobación el carril\n         rápido responde 400) y la segunda es la fuente de verdad de la lista. */\n      const [m, p] = await Promise.all([ecomerseApi.sellerMe(), ecomerseApi.myProducts()]);\n      setMe(m);\n      setProductos(p);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar tus anuncios. Revisa la conexión.');\n    } finally {\n      setCargando(false); setRefrescando(false);\n    }\n  }, []);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const s = estilos(colors);\n  const seller = me?.seller;\n  const activa = seller?.status === 'active';\n\n  /**\n   * Aplica lo que devolvió el SERVIDOR sobre la lista local. No se adivina el estado nuevo: se copia\n   * el que el servidor calculó (`sold_out` cuando pediste `active` con stock 0, por ejemplo).\n   */\n  const aplicarServidor = useCallback((\n    id: string,\n    r: { stock: number; status: string; handlingHours?: number; returnsAccepted?: boolean },\n  ) => {\n    setProductos((prev) => prev.map((p) => (p.id === id\n      ? {\n        ...p,\n        stock: r.stock,\n        status: r.status,\n        handlingHours: r.handlingHours ?? p.handlingHours,\n        returnsAccepted: r.returnsAccepted ?? p.returnsAccepted,\n      }\n      : p)));\n    setEnGestion((g) => (g && g.id === id\n      ? { ...g, stock: r.stock, status: r.status, handlingHours: r.handlingHours ?? g.handlingHours, returnsAccepted: r.returnsAccepted ?? g.returnsAccepted }\n      : g));\n  }, []);\n\n  /** Un solo sitio para las llamadas del carril rápido: pone el «en vuelo», avisa y recarga el error. */\n  const llamarRapido = useCallback(async (\n    p: EcomerseProduct,\n    fn: () => Promise<{ message: string; producto: { stock: number; status: string; handlingHours?: number; returnsAccepted?: boolean } }>,\n  ) => {\n    setOcupado(p.id);\n    try {\n      const r = await fn();\n      aplicarServidor(p.id, r.producto);\n      mostrarAviso(r.message, 'exito');\n      return true;\n    } catch (e) {\n      /* El servidor explica qué pasa («Tu negocio está en revisión…», «Este anuncio está retirado…»).\n         Se enseña tal cual: es más útil que un «error» genérico. */\n      mostrarAviso(e instanceof Error ? e.message : 'No se pudo completar el cambio', 'aviso');\n      return false;\n    } finally {\n      setOcupado(null);\n    }\n  }, [aplicarServidor, mostrarAviso]);\n\n  const cambiarStock = useCallback((p: EcomerseProduct, delta: number) => {\n    const nuevo = Math.max(0, p.stock + delta);\n    if (nuevo === p.stock) return;\n    /* Optimista: la cifra cambia al toque porque el servidor puede tardar y reponer existencias es\n       una acción de dedo. Si falla, se vuelve a pedir la lista y se dice por qué. */\n    setProductos((prev) => prev.map((x) => (x.id === p.id ? { ...x, stock: nuevo } : x)));\n    void llamarRapido(p, () => ecomerseApi.updateProductOperations(p.id, { stock: nuevo }))\n      .then((ok) => { if (!ok) void cargar(true); });\n  }, [cargar, llamarRapido]);\n\n  const cambiarEstado = useCallback((p: EcomerseProduct, estado: 'active' | 'paused' | 'removed') => {\n    void llamarRapido(p, () => ecomerseApi.updateProductState(p.id, estado));\n  }, [llamarRapido]);\n\n  const cambiarPlazo = useCallback((p: EcomerseProduct, horas: 24 | 48 | 72) => {\n    void llamarRapido(p, () => ecomerseApi.updateProductOperations(p.id, { handlingHours: horas }));\n  }, [llamarRapido]);\n\n  const cambiarDevoluciones = useCallback((p: EcomerseProduct, valor: boolean) => {\n    void llamarRapido(p, () => ecomerseApi.updateProductOperations(p.id, { returnsAccepted: valor }));\n  }, [llamarRapido]);\n\n  /**\n   * Abrir el editor de ejes y combinaciones (fase 4).\n   *\n   * Se cierra la hoja ANTES de navegar, igual que hace «Corregir anuncio»: si se dejara abierta,\n   * al volver de la pantalla el comerciante se encontraría un diálogo por encima de la lista que él\n   * ya no había pedido.\n   */\n  const abrirCombinaciones = useCallback((p: EcomerseProduct) => {\n    setEnGestion(null);\n    router.push(`/tienda/combinaciones?id=${p.id}` as never);\n  }, [router]);\n\n  /* Cuántos anuncios hay en cada filtro. Se calcula sobre `FILTROS` para que el chip y el recuento\n     no puedan desincronizarse. */\n  const recuentos = useMemo(\n    () => Object.fromEntries(FILTROS.map((f) => [f.id, productos.filter(f.acepta).length])),\n    [productos],\n  );\n  const visibles = useMemo(() => FILTROS.filter((f) => f.id === 'todos' || recuentos[f.id] > 0), [recuentos]);\n  const lista = useMemo(() => {\n    const f = FILTROS.find((x) => x.id === filtro) ?? FILTROS[0];\n    return productos.filter(f.acepta);\n  }, [productos, filtro]);\n\n  /* ── Estados de pantalla ───────────────────────────────────────────────────────────────────── */\n\n  if (cargando) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        <Cabecera titulo=\"Anuncios\" onPublicar={() => router.push('/tienda/publicar' as never)} colors={colors} />\n        <View style={{ padding: espaciado.e16, gap: espaciado.e12 }}>\n          {[0, 1, 2, 3].map((i) => <View key={i} style={[s.hueso, { backgroundColor: colors.border }]} />)}\n        </View>\n      </View>\n    );\n  }\n\n  if (error) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        <Cabecera titulo=\"Anuncios\" onPublicar={() => router.push('/tienda/publicar' as never)} colors={colors} />\n        <View style={{ padding: espaciado.e16 }}>\n          <InlineError mensaje={error} onReintentar={() => cargar()} />\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <View style={[s.raiz, { paddingTop: insets.top }]}>\n      <Cabecera\n        titulo=\"Anuncios\"\n        subtitulo={productos.length === 0 ? undefined : `${productos.length} ${productos.length === 1 ? 'anuncio' : 'anuncios'}`}\n        onPublicar={() => router.push('/tienda/publicar' as never)}\n        colors={colors}\n      />\n\n      <ScrollView\n        contentContainerStyle={{\n          padding: espaciado.e16,\n          /* La barra de la zona vive FUERA del Stack (en `_layout`), así que este relleno es lo único\n             que impide que el último anuncio quede debajo de ella. */\n          paddingBottom: BARRA_TIENDA_H + insets.bottom + espaciado.e24,\n        }}\n        showsVerticalScrollIndicator={false}\n        refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => cargar(true)} />}\n      >\n        {/* Tienda no aprobada: el carril rápido responde 400, así que se dice ANTES de dejar tocar. */}\n        {!activa && (\n          <View style={[s.tarjeta, { backgroundColor: alpha(colors.primary, 0.06), marginBottom: espaciado.e16 }]}>\n            <Text style={s.etiqueta}>{seller ? 'TU TIENDA ESTÁ EN REVISIÓN' : 'AÚN NO TIENES TIENDA'}</Text>\n            <Text style={s.tituloBloque}>\n              {seller ? 'Puedes ver tus anuncios, pero todavía no administrarlos' : 'Da de alta tu negocio para publicar'}\n            </Text>\n            <Text style={s.nota}>\n              {seller\n                ? 'Las existencias, la pausa y la retirada se abren cuando el administrador apruebe tu tienda (24–48 h).'\n                : 'Necesitas la identidad verificada (KYC) y los datos del negocio.'}\n            </Text>\n            <View style={{ marginTop: espaciado.e12 }}>\n              <PrimaryButton\n                title={seller ? 'Ver qué falta' : 'Dar de alta mi negocio'}\n                onPress={() => router.replace('/tienda' as never)}\n              />\n            </View>\n          </View>\n        )}\n\n        {/* Filtros: solo los que tienen algo dentro. */}\n        {productos.length > 0 && (\n          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8, paddingBottom: espaciado.e12 }}>\n            {visibles.map((f) => {\n              const on = filtro === f.id;\n              return (\n                <Pressable\n                  key={f.id}\n                  onPress={() => setFiltro(f.id)}\n                  accessibilityRole=\"button\"\n                  accessibilityState={{ selected: on }}\n                  accessibilityLabel={`${f.label}: ${recuentos[f.id]} ${recuentos[f.id] === 1 ? 'anuncio' : 'anuncios'}`}\n                  style={({ pressed }) => [s.chip, {\n                    backgroundColor: on ? colors.primary : colors.card,\n                    borderColor: on ? colors.primary : colors.border,\n                    opacity: pressed ? 0.7 : 1,\n                  }]}\n                >\n                  <Text style={[s.chipTexto, { color: on ? colors.white : colors.textPrimary }]}>\n                    {f.label} · {recuentos[f.id]}\n                  </Text>\n                </Pressable>\n              );\n            })}\n          </ScrollView>\n        )}\n\n        {/* Vacíos distintos: «no tengo nada» no es lo mismo que «este filtro no tiene nada». */}\n        {productos.length === 0 ? (\n          activa ? (\n            <EmptyState\n              emoji=\"📦\"\n              titulo=\"Todavía no has publicado\"\n              texto=\"Publica tu primer anuncio y aparecerá en el Mercado con el nombre de tu tienda.\"\n              accionLabel=\"Publicar mi primer producto\"\n              accionPrimaria\n              onAccion={() => router.push('/tienda/publicar' as never)}\n            />\n          ) : (\n            <EmptyState\n              emoji=\"📦\"\n              titulo=\"Sin anuncios\"\n              texto=\"Cuando tu tienda esté aprobada podrás publicar y administrar tus anuncios desde aquí.\"\n            />\n          )\n        ) : lista.length === 0 ? (\n          <View style={{ paddingVertical: espaciado.e32, alignItems: 'center', gap: espaciado.e8 }}>\n            <Text style={s.nota}>No hay anuncios en «{FILTROS.find((f) => f.id === filtro)?.label}».</Text>\n            <GhostButton title=\"Ver todos\" onPress={() => setFiltro('todos')} />\n          </View>\n        ) : (\n          lista.map((p) => (\n            <FilaAnuncio\n              key={p.id}\n              producto={p}\n              activa={!!activa}\n              ocupado={ocupado === p.id}\n              onStock={(d) => cambiarStock(p, d)}\n              onGestionar={() => setEnGestion(p)}\n              onCorregir={() => router.push(`/tienda/publicar?id=${p.id}` as never)}\n              onCombinaciones={() => abrirCombinaciones(p)}\n              colors={colors}\n            />\n          ))\n        )}\n\n        {/* Recordatorio del alcance del carril rápido, al pie y solo una vez. */}\n        {productos.length > 0 && activa && (\n          <Text style={[s.nota, { marginTop: espaciado.e16 }]}>\n            Existencias, plazo, devoluciones y combinaciones se cambian aquí y **no** pasan por revisión. Para\n            el título, las fotos o el precio, «Corregir anuncio»: eso sí vuelve al administrador.\n          </Text>\n        )}\n      </ScrollView>\n\n      <Aviso visible={aviso.visible} mensaje={aviso.mensaje} tono={aviso.tono} onOcultar={ocultarAviso} />\n\n      {/* ── Hoja de gestión: el resto del carril rápido, sin salir de la lista ─────────────────── */}\n      <Sheet\n        visible={enGestion !== null}\n        title={enGestion?.title ?? ''}\n        subtitle={enGestion ? ESTADOS[enGestion.status]?.label ?? enGestion.status : undefined}\n        position=\"bottom\"\n        busy={ocupado !== null}\n        onClose={() => setEnGestion(null)}\n      >\n        {enGestion && (\n          /* La lista SCROLLEA, y tiene que hacerlo: `Sheet` no lo hace sola y con la sección de\n             combinaciones el contenido ya pasa del 80 % que topa la hoja. Ver `altoHoja`. */\n          <ScrollView\n            style={{ maxHeight: altoHoja }}\n            showsVerticalScrollIndicator={false}\n            contentContainerStyle={{ gap: espaciado.e16 }}\n          >\n            {/* 1 · Visibilidad */}\n            <View>\n              <Text style={s.etiqueta}>VISIBILIDAD EN EL MERCADO</Text>\n              <Text style={s.nota}>\n                Pausar lo esconde del catálogo sin perder nada; volver a la venta lo devuelve tal cual.\n                Retirar tampoco borra: fotos, documentación y el historial de ventas siguen ahí.\n              </Text>\n              <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12, flexWrap: 'wrap' }}>\n                {enGestion.status !== 'active' && (\n                  <AccionHoja\n                    Icono={Play}\n                    label={enGestion.stock > 0 ? 'Volver a la venta' : 'Poner a la venta'}\n                    onPress={() => cambiarEstado(enGestion, 'active')}\n                    colors={colors}\n                  />\n                )}\n                {enGestion.status !== 'paused' && (\n                  <AccionHoja Icono={Pause} label=\"Pausar\" onPress={() => cambiarEstado(enGestion, 'paused')} colors={colors} />\n                )}\n                {enGestion.status !== 'removed' && (\n                  <AccionHoja Icono={Trash2} label=\"Retirar\" tono={colors.danger} onPress={() => cambiarEstado(enGestion, 'removed')} colors={colors} />\n                )}\n              </View>\n              {enGestion.status === 'active' && enGestion.stock <= 0 && (\n                <Text style={[s.nota, { color: colors.warning }]}>\n                  Está a la venta sin existencias: el catálogo lo enseña como agotado.\n                </Text>\n              )}\n            </View>\n\n            {/* 2 · Existencias — o el porqué de que aquí no se toquen (fase 4) */}\n            {enGestion.status !== 'removed' && ((enGestion.variantCount ?? 0) > 0 ? (\n              /* CON COMBINACIONES, LAS EXISTENCIAS NO SE ESCRIBEN AQUÍ. El servidor lo rechaza —«sus\n                 existencias son la suma de ellas»— porque el anuncio es un ESPEJO de la suma: dejarlo\n                 escribir a mano crearía dos verdades y la tarjeta del Mercado anunciaría unidades que\n                 no existen. Se explica y se lleva al sitio donde sí se cambia. */\n              <View>\n                <Text style={s.etiqueta}>EXISTENCIAS</Text>\n                <Text style={s.nota}>\n                  No se cambian desde aquí: este anuncio se vende por combinaciones\n                  ({enGestion.variantCount}) y su stock es la <Text style={{ fontWeight: peso.titulo, color: colors.textPrimary }}>suma</Text> de\n                  ellas —{enGestion.stock} ahora mismo—. La suma la hace el servidor solo; aquí no se escribe.\n                </Text>\n              </View>\n            ) : (\n              <View>\n                <Text style={s.etiqueta}>EXISTENCIAS</Text>\n                <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12, marginTop: espaciado.e8 }}>\n                  <BotonPaso Icono={Minus} deshabilitado={ocupado !== null || enGestion.stock <= 0} onPress={() => cambiarStock(enGestion, -1)} colors={colors} etiqueta=\"Quitar una unidad\" />\n                  <Text style={s.cifraStock}>{enGestion.stock}</Text>\n                  <BotonPaso Icono={Plus} deshabilitado={ocupado !== null} onPress={() => cambiarStock(enGestion, 1)} colors={colors} etiqueta=\"Añadir una unidad\" />\n                  <Text style={[s.nota, { flex: 1 }]}>\n                    {enGestion.stock === 0 ? 'Con 0 el anuncio queda agotado y sale del catálogo.' : 'Las unidades se descuentan solas al vender.'}\n                  </Text>\n                </View>\n              </View>\n            ))}\n\n            {/* 3 · Las combinaciones (fase 4). Una sola puerta para los dos casos —tenerlas o no\n                tenerlas—: el botón cambia de verbo, no de sitio. */}\n            <View>\n              <Text style={s.etiqueta}>¿EL COMPRADOR TIENE QUE ELEGIR ALGO?</Text>\n              <Text style={s.nota}>\n                {(enGestion.variantCount ?? 0) > 0\n                  ? 'Tallas, colores, capacidad… Cada combinación con su precio y sus unidades. Se cambian sin volver a revisión: reponer una talla es cosa del día a día.'\n                  : 'Si hay tallas, colores o capacidades entre las que elegir, se declaran aquí: el comprador elige antes de comprar y cada combinación lleva su precio y sus unidades. Sin combinaciones, el anuncio se compra entero, con su precio y su stock.'}\n              </Text>\n              <View style={{ marginTop: espaciado.e8 }}>\n                <GhostButton\n                  title={(enGestion.variantCount ?? 0) > 0 ? 'Editar combinaciones' : 'Añadir combinaciones'}\n                  onPress={() => abrirCombinaciones(enGestion)}\n                />\n              </View>\n            </View>\n\n            {/* 4 · Lo que prometes al comprador: viaja CONGELADO en la línea del pedido */}\n            <View>\n              <Text style={s.etiqueta}>PLAZO DE PREPARACIÓN</Text>\n              <Text style={s.nota}>\n                Lo que tardas en entregarlo al repartidor. El comprador lo ve en su pedido tal como estaba\n                el día que compró, aunque después lo cambies.\n              </Text>\n              <View style={{ flexDirection: 'row', gap: espaciado.e8, marginTop: espaciado.e12 }}>\n                {PLAZOS.map((h) => {\n                  const on = enGestion.handlingHours === h;\n                  return (\n                    <Pressable\n                      key={h}\n                      onPress={() => cambiarPlazo(enGestion, h)}\n                      disabled={ocupado !== null}\n                      accessibilityRole=\"button\"\n                      accessibilityState={{ selected: on, disabled: ocupado !== null }}\n                      accessibilityLabel={`Plazo de ${h} horas`}\n                      style={[s.chip, {\n                        backgroundColor: on ? colors.primary : colors.card,\n                        borderColor: on ? colors.primary : colors.border,\n                        opacity: ocupado !== null ? 0.5 : 1,\n                      }]}\n                    >\n                      <Text style={[s.chipTexto, { color: on ? colors.white : colors.textPrimary }]}>{h} h</Text>\n                    </Pressable>\n                  );\n                })}\n              </View>\n            </View>\n\n            <View>\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e12 }}>\n                <View style={{ flex: 1 }}>\n                  <Text style={s.etiqueta}>ACEPTO DEVOLUCIONES</Text>\n                  <Text style={s.nota}>\n                    Es tu oferta, aparte de la garantía de 7 días de la plataforma. Si no la ofreces, se dice\n                    en la ficha.\n                  </Text>\n                </View>\n                <Switch\n                  value={enGestion.returnsAccepted}\n                  onValueChange={(v) => cambiarDevoluciones(enGestion, v)}\n                  disabled={ocupado !== null}\n                  accessibilityLabel=\"Acepto devoluciones\"\n                  trackColor={{ false: colors.border, true: alpha(colors.primary, 0.5) }}\n                  thumbColor={enGestion.returnsAccepted ? colors.primary : colors.card}\n                />\n              </View>\n            </View>\n\n            {/* 5 · El carril moderado, para que no se confunda con lo de arriba */}\n            <View style={{ borderTopWidth: trazo.fino, borderTopColor: colors.border, paddingTop: espaciado.e16 }}>\n              <Text style={s.etiqueta}>CONTENIDO DEL ANUNCIO</Text>\n              <Text style={s.nota}>\n                Título, fotos, precio y categoría pasan por el administrador. Si cambias algo, el anuncio\n                vuelve a revisión.\n              </Text>\n              <View style={{ marginTop: espaciado.e8 }}>\n                <GhostButton title=\"Corregir anuncio (vuelve a revisión)\" onPress={() => {\n                  const id = enGestion.id;\n                  setEnGestion(null);\n                  router.push(`/tienda/publicar?id=${id}` as never);\n                }} />\n              </View>\n            </View>\n          </ScrollView>\n        )}\n      </Sheet>\n    </View>\n  );\n}\n\n/* ── Piezas ───────────────────────────────────────────────────────────────────────────────────── */\n\nfunction Cabecera({ titulo, subtitulo, onPublicar, colors }: {\n  titulo: string; subtitulo?: string; onPublicar: () => void;\n  colors: ReturnType<typeof useTheme>['colors'];\n}) {\n  return (\n    <View style={{\n      flexDirection: 'row', alignItems: 'center', paddingHorizontal: espaciado.e16,\n      paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino, borderBottomColor: colors.border,\n    }}>\n      <View style={{ flex: 1 }}>\n        <Text style={{ fontSize: tipografia.title, fontWeight: peso.titulo, color: colors.textPrimary }}>{titulo}</Text>\n        {subtitulo ? <Text style={{ fontSize: tipografia.caption, color: colors.textSecondary, marginTop: espaciado.e2 }}>{subtitulo}</Text> : null}\n      </View>\n      <Pressable\n        onPress={onPublicar}\n        accessibilityRole=\"button\"\n        accessibilityLabel=\"Publicar un anuncio nuevo\"\n        hitSlop={espaciado.e8}\n        style={({ pressed }) => [{\n          width: 40, height: 40, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center',\n          backgroundColor: colors.primary, opacity: pressed ? 0.7 : 1,\n        }]}\n      >\n        <PackagePlus size={icono.sm} color={colors.white} />\n      </Pressable>\n    </View>\n  );\n}\n\n/** Un renglón de la lista: foto, qué es, cómo está, existencias y la puerta a la hoja. */\nfunction FilaAnuncio({ producto, activa, ocupado, onStock, onGestionar, onCorregir, onCombinaciones, colors }: {\n  producto: EcomerseProduct;\n  activa: boolean;\n  ocupado: boolean;\n  onStock: (delta: number) => void;\n  onGestionar: () => void;\n  onCorregir: () => void;\n  /** Abre el editor de ejes y combinaciones (fase 4). */\n  onCombinaciones: () => void;\n  colors: ReturnType<typeof useTheme>['colors'];\n}) {\n  const s = estilos(colors);\n  const foto = producto.photos?.[0] ?? null;\n  const estado = ESTADOS[producto.status] ?? { label: producto.status, tono: 'neutro' as const };\n  const tono = estado.tono === 'bien' ? colors.success\n    : estado.tono === 'aviso' ? colors.warning\n      : estado.tono === 'peligro' ? colors.danger\n        : colors.textSecondary;\n  const retirado = producto.status === 'removed';\n  /* Los tres estados que el carril rápido NO puede activar (la moderación manda): su salida es\n     «Corregir», no un botón de «activar» que el servidor iba a rechazar. */\n  const sinAprobar = producto.status === 'pending' || producto.status === 'draft' || producto.status === 'rejected';\n  /**\n   * Cuántas combinaciones tiene (fase 4). Lo manda `myProducts` como `variantCount`, así que se sabe\n   * SIN abrir el anuncio —y eso es lo que permite que la fila cambie de forma, en vez de ofrecer un\n   * +1 de existencias que el servidor va a rechazar.\n   */\n  const combinaciones = producto.variantCount ?? 0;\n\n  return (\n    <View style={[s.fila, { borderBottomColor: colors.border }]}>\n      <Pressable\n        onPress={onGestionar}\n        accessibilityRole=\"button\"\n        accessibilityLabel={`${producto.title}. ${estado.label}. ${producto.stock} en existencias. Abre la gestión del anuncio.`}\n        style={({ pressed }) => [{ flex: 1, flexDirection: 'row', gap: espaciado.e12, opacity: pressed ? 0.7 : 1 }]}\n      >\n        {foto ? (\n          <Image source={{ uri: foto }} style={[s.miniatura, { backgroundColor: colors.border }]} contentFit=\"cover\" />\n        ) : (\n          <View style={[s.miniatura, { backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center' }]}>\n            <ImageOff size={icono.sm} color={colors.textSecondary} />\n          </View>\n        )}\n\n        <View style={{ flex: 1, justifyContent: 'center', gap: espaciado.e2 }}>\n          <Text style={s.nombre} numberOfLines={1}>{producto.title}</Text>\n          {/* El importe va DENTRO de una frase → `formatXAF` suelto, no `Precio`: `Precio` devuelve\n              una View y meter una caja dentro de una frase rompe su ajuste de línea\n              (doctrina «figura o frase», FASE-2-PRECIO.md).\n              Con combinaciones se dice CUÁNTAS en vez de las existencias: el stock del anuncio es\n              su suma y no es lo que el comerciante viene a mirar aquí (eso está por talla, en su\n              editor). Sin combinaciones se dice lo de siempre. */}\n          <Text style={s.meta} numberOfLines={1}>\n            {formatXAF(producto.priceXaf)} · {combinaciones > 0\n              ? `${combinaciones} ${combinaciones === 1 ? 'combinación' : 'combinaciones'}`\n              : `${producto.stock} en existencias`}\n          </Text>\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, flexWrap: 'wrap' }}>\n            <Text style={[s.sello, { color: tono }]}>{estado.label}</Text>\n            {/* Visitas y favoritos son DEL ANUNCIO. Se pintan aquí, uno a uno, para no poder sumarlos\n                y llamarlos «tráfico de la tienda». */}\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e2 }}>\n              <Eye size={icono.micro} color={colors.textSecondary} />\n              <Text style={s.meta}>{producto.views ?? 0}</Text>\n            </View>\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e2 }}>\n              <Heart size={icono.micro} color={colors.textSecondary} />\n              <Text style={s.meta}>{producto.favoriteCount ?? 0}</Text>\n            </View>\n            {producto.isFeatured && <Text style={[s.sello, { color: colors.primary }]}>Destacado</Text>}\n          </View>\n        </View>\n      </Pressable>\n\n      {/* Acciones del carril rápido, en la propia fila: reponer es la operación más repetida del día\n          y no merece abrir una hoja. Solo con tienda aprobada y anuncio no retirado. */}\n      {activa && !retirado && (\n        <View style={{ alignItems: 'center', gap: espaciado.e4 }}>\n          {sinAprobar ? (\n            <Pressable\n              onPress={onCorregir}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Corregir ${producto.title}: vuelve a revisión`}\n              style={({ pressed }) => [s.enlace, { opacity: pressed ? 0.6 : 1 }]}\n            >\n              <Text style={[s.sello, { color: colors.primary }]}>Corregir</Text>\n            </Pressable>\n          ) : combinaciones > 0 ? (\n            /* CON COMBINACIONES NO HAY ± DE EXISTENCIAS, y no es una preferencia de diseño: el\n               servidor **rechaza** escribir `stock` en un anuncio que se vende por combinaciones\n               («sus existencias son la suma de ellas. Cambia las de cada combinación»). Dejar los\n               botones ahí sería ofrecer un toque que contesta con un error. En su lugar va la puerta\n               al editor, que es donde eso se cambia de verdad: por talla y por color. */\n            <Pressable\n              onPress={onCombinaciones}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`${producto.title}: ${combinaciones} ${combinaciones === 1 ? 'combinación' : 'combinaciones'}. Abre sus precios y sus unidades.`}\n              style={({ pressed }) => [s.enlace, { opacity: pressed ? 0.6 : 1 }]}\n            >\n              <Layers size={icono.micro} color={colors.primary} />\n              <Text style={[s.sello, { color: colors.primary }]}>Combinaciones</Text>\n            </Pressable>\n          ) : (\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: espaciado.e4 }}>\n              <BotonPaso Icono={Minus} deshabilitado={ocupado || producto.stock <= 0} onPress={() => onStock(-1)} colors={colors} etiqueta={`Quitar una unidad a ${producto.title}`} compacto />\n              <BotonPaso Icono={Plus} deshabilitado={ocupado} onPress={() => onStock(1)} colors={colors} etiqueta={`Añadir una unidad a ${producto.title}`} compacto />\n            </View>\n          )}\n          <Pressable\n            onPress={onGestionar}\n            accessibilityRole=\"button\"\n            accessibilityLabel={`Gestionar ${producto.title}`}\n            style={({ pressed }) => [s.enlace, { opacity: pressed ? 0.6 : 1 }]}\n          >\n            <Settings2 size={icono.micro} color={colors.textSecondary} />\n            <Text style={s.meta}>Gestionar</Text>\n            <ChevronRight size={icono.micro} color={colors.textSecondary} />\n          </Pressable>\n        </View>\n      )}\n\n      {/* Retirado: la salida está en la hoja (volver a la venta). Aquí solo se recuerda que existe. */}\n      {activa && retirado && (\n        <Pressable\n          onPress={onGestionar}\n          accessibilityRole=\"button\"\n          accessibilityLabel={`${producto.title} está retirado. Abre la gestión para volver a ponerlo a la venta.`}\n          style={({ pressed }) => [s.enlace, { opacity: pressed ? 0.6 : 1 }]}\n        >\n          <Text style={[s.sello, { color: colors.primary }]}>Reactivar</Text>\n        </Pressable>\n      )}\n\n      {!activa && producto.status === 'rejected' && producto.rejectionReason ? (\n        <View style={{ maxWidth: 108, alignItems: 'flex-end' }}>\n          <AlertTriangle size={icono.micro} color={colors.danger} />\n          <Text style={[s.meta, { color: colors.danger }]} numberOfLines={3}>{producto.rejectionReason}</Text>\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\n/** Botón de paso (+, −). 44 dp de lado para que quepa el dedo sin abrir nada. */\nfunction BotonPaso({ Icono, onPress, deshabilitado, etiqueta, colors, compacto = false }: {\n  Icono: typeof Plus; onPress: () => void; deshabilitado: boolean; etiqueta: string;\n  colors: ReturnType<typeof useTheme>['colors']; compacto?: boolean;\n}) {\n  const lado = compacto ? altura.punto - espaciado.e12 : altura.punto;\n  return (\n    <Pressable\n      onPress={onPress}\n      disabled={deshabilitado}\n      accessibilityRole=\"button\"\n      accessibilityLabel={etiqueta}\n      accessibilityState={{ disabled: deshabilitado }}\n      hitSlop={compacto ? espaciado.e4 : undefined}\n      style={({ pressed }) => [{\n        width: lado, height: lado, borderRadius: radios.md, alignItems: 'center', justifyContent: 'center',\n        borderWidth: trazo.fino, borderColor: colors.border, backgroundColor: colors.card,\n        opacity: deshabilitado ? 0.35 : pressed ? 0.6 : 1,\n      }]}\n    >\n      <Icono size={compacto ? icono.micro : icono.sm} color={colors.textPrimary} />\n    </Pressable>\n  );\n}\n\n/** Acción de la hoja: icono + etiqueta, en una fila que envuelve si no caben. */\nfunction AccionHoja({ Icono, label, onPress, colors, tono }: {\n  Icono: typeof Play; label: string; onPress: () => void;\n  colors: ReturnType<typeof useTheme>['colors']; tono?: string;\n}) {\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={label}\n      style={({ pressed }) => [{\n        flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n        paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e8,\n        borderRadius: radios.full, borderWidth: trazo.fino, borderColor: colors.border,\n        backgroundColor: colors.card, opacity: pressed ? 0.7 : 1,\n      }]}\n    >\n      <Icono size={icono.sm} color={tono ?? colors.textPrimary} />\n      <Text style={{ fontSize: tipografia.caption, fontWeight: peso.fuerte, color: tono ?? colors.textPrimary }}>{label}</Text>\n    </Pressable>\n  );\n}\n\nconst estilos = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  raiz: { flex: 1, backgroundColor: c.background },\n  hueso: { height: 72, borderRadius: radios.md, opacity: 0.6 },\n  tarjeta: { borderRadius: radios.md, padding: espaciado.e12, borderWidth: trazo.fino, borderColor: c.border },\n  etiqueta: { fontSize: tipografia.micro, fontWeight: peso.fuerte, color: c.textSecondary, letterSpacing: 0.4, marginBottom: espaciado.e4 },\n  tituloBloque: { fontSize: tipografia.body, fontWeight: peso.titulo, color: c.textPrimary, marginBottom: espaciado.e4 },\n  nota: { fontSize: tipografia.micro, color: c.textSecondary, lineHeight: 16, marginTop: espaciado.e2 },\n  chip: { paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e4 + 2, borderRadius: radios.full, borderWidth: trazo.fino },\n  chipTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  fila: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n    paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino,\n  },\n  miniatura: { width: 56, height: 56, borderRadius: radios.md },\n  nombre: { fontSize: tipografia.body, fontWeight: peso.fuerte, color: c.textPrimary },\n  meta: { fontSize: tipografia.micro, color: c.textSecondary },\n  sello: { fontSize: tipografia.micro, fontWeight: peso.titulo },\n  cifraStock: { fontSize: tipografia.subtitle, fontWeight: peso.titulo, color: c.textPrimary, minWidth: 34, textAlign: 'center' },\n  enlace: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e2, paddingVertical: espaciado.e4, paddingHorizontal: espaciado.e4 },\n});\n","/**\n * Combinaciones — el editor de EJES Y COMBINACIONES de un anuncio (Fase 4 · SKU).\n * Ruta: /tienda/combinaciones?id=<productoId>\n *\n * POR QUÉ ES UNA PANTALLA APARTE Y NO UNA SECCIÓN DE «PUBLICAR». Porque son **dos carriles\n * distintos**, y el servidor los separa a propósito: el contenido del anuncio (título, fotos,\n * precio, categoría) pasa por moderación y `POST`/`PUT products` **rechaza** `options` para que nadie\n * crea que las publicó. Las combinaciones van por `PUT seller/products/:id/options`, el carril\n * rápido, y ahí se quedan: reponer una talla es la operación más repetida del día y no puede costar\n * 24–48 h de revisión.\n *\n * Consecuencia que se ve en la pantalla: las combinaciones son un paso **después** de publicar. Por\n * eso esta pantalla se abre desde «Anuncios» (que es donde está lo publicado), no desde el\n * formulario de alta — y por eso «Publicar» enlaza aquí al terminar, en vez de fingir que se\n * configuran allí.\n *\n * ESTÁ FUERA DE LA BARRA DE PESTAÑAS (`BarraTienda.SIN_BARRA`), como «Publicar»: es un flujo de\n * edición con su propio botón de guardar, no una quinta pestaña. Dejarla con barra invitaría a\n * abandonarla a medias sin decirlo.\n *\n * DE DÓNDE SALE TODO: de la ficha pública (`GET products/:id`), que ya devuelve `photos`, `options`\n * y `variants` en la misma respuesta — una sola petición para los cuatro datos que el editor\n * necesita. La segunda petición (`myProducts`) NO es para pintar nada: es para comprobar que el\n * anuncio es de quien lo está editando. Sin esa comprobación, un enlace a un anuncio ajeno dejaría\n * rellenar ejes enteros para reventar en el guardado con un «Producto no encontrado».\n */\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { ArrowLeft } from 'lucide-react-native';\nimport {\n  Aviso, InlineError, alpha, espaciado, peso, radios, tipografia, trazo, useAviso, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseProduct } from '../../api/ecomerse';\nimport { formatXAF } from '../../utils/formatHelpers';\nimport EditorDeCombinaciones, { type ResultadoCombinaciones } from '../../components/ecomerse/EditorDeCombinaciones';\n\nexport default function CombinacionesScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const { id } = useLocalSearchParams<{ id?: string }>();\n\n  const [producto, setProducto] = useState<EcomerseProduct | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [aviso, mostrarAviso, ocultarAviso] = useAviso();\n\n  const cargar = useCallback(async () => {\n    if (!id) { setError('No sabemos de qué anuncio hablamos.'); setCargando(false); return; }\n    setCargando(true);\n    setError(null);\n    try {\n      const [p, mios] = await Promise.all([ecomerseApi.product(id), ecomerseApi.myProducts()]);\n      if (!mios.some((x) => x.id === id)) {\n        setError('Ese anuncio no está entre los tuyos.');\n        setProducto(null);\n        return;\n      }\n      setProducto(p);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar el anuncio. Revisa la conexión.');\n    } finally {\n      setCargando(false);\n    }\n  }, [id]);\n\n  useEffect(() => { void cargar(); }, [cargar]);\n\n  /**\n   * Lo que el servidor devolvió al guardar pisa lo que teníamos: él es quien asigna los `id` de ejes\n   * y combinaciones, y quien calcula el `stock` del anuncio (la suma). El editor NO se vuelve a\n   * montar —su `key` es el id del anuncio—, así que el borrador que el comerciante tiene delante\n   * sigue siendo el suyo y no se le cierra nada.\n   */\n  const alGuardar = (r: ResultadoCombinaciones) => {\n    mostrarAviso(r.message, 'exito');\n    setProducto((p) => (p ? { ...p, options: r.options, variants: r.variants, variantCount: r.variants.length, stock: r.stock } : p));\n  };\n\n  const enRevision = !!producto && ['pending', 'draft', 'rejected'].includes(producto.status);\n  const s = estilos(colors);\n\n  const cabecera = (\n    <View style={s.cabecera}>\n      <Pressable\n        onPress={() => router.back()}\n        hitSlop={espaciado.e12}\n        accessibilityRole=\"button\"\n        accessibilityLabel=\"Volver\"\n      >\n        <ArrowLeft size={22} color={colors.textPrimary} />\n      </Pressable>\n      <View style={{ flex: 1 }}>\n        <Text style={s.tituloCabecera} numberOfLines={1}>Combinaciones</Text>\n        {producto ? <Text style={s.subCabecera} numberOfLines={1}>{producto.title}</Text> : null}\n      </View>\n    </View>\n  );\n\n  if (cargando) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        {cabecera}\n        <View style={{ padding: espaciado.e16, gap: espaciado.e12 }}>\n          {[0, 1, 2].map((i) => <View key={i} style={[s.hueso, { backgroundColor: colors.border }]} />)}\n        </View>\n      </View>\n    );\n  }\n\n  if (error || !producto) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        {cabecera}\n        <View style={{ padding: espaciado.e16 }}>\n          <InlineError\n            mensaje={error ?? 'No pudimos cargar el anuncio.'}\n            onReintentar={id ? () => { void cargar(); } : undefined}\n          />\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <View style={[s.raiz, { paddingTop: insets.top }]}>\n      {cabecera}\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: insets.bottom + espaciado.e32 }}\n        showsVerticalScrollIndicator={false}\n        keyboardShouldPersistTaps=\"handled\"\n      >\n        {/* Dónde está el anuncio ahora: es el dato con el que se lee todo lo de abajo (el precio que\n            hereda una combinación y las unidades que hoy tiene). */}\n        <Text style={s.contexto}>\n          {formatXAF(producto.priceXaf)} · {producto.stock} {producto.stock === 1 ? 'unidad' : 'unidades'}\n          {producto.photos?.length ? ` · ${producto.photos.length} ${producto.photos.length === 1 ? 'foto' : 'fotos'}` : ' · sin fotos'}\n        </Text>\n\n        {/* Un anuncio sin aprobar admite combinaciones: se guardan y están listas cuando se apruebe.\n            Decirlo evita la duda de «¿esto no se puede tocar todavía?». */}\n        {enRevision && (\n          <View style={s.avisoRevision}>\n            <Text style={s.avisoRevisionTexto}>\n              El anuncio está en revisión. Puedes preparar sus combinaciones igual: se guardan aquí y estarán\n              listas en cuanto el administrador lo apruebe.\n            </Text>\n          </View>\n        )}\n\n        <EditorDeCombinaciones\n          /* La clave es el anuncio: cambiar de anuncio vuelve a leer el borrador desde cero. */\n          key={producto.id}\n          productoId={producto.id}\n          precioAnuncio={producto.priceXaf}\n          stockAnuncio={producto.stock}\n          fotos={producto.photos ?? []}\n          inicial={{ options: producto.options, variants: producto.variants }}\n          onGuardado={alGuardar}\n        />\n      </ScrollView>\n\n      <Aviso visible={aviso.visible} mensaje={aviso.mensaje} tono={aviso.tono} onOcultar={ocultarAviso} />\n    </View>\n  );\n}\n\nconst estilos = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  raiz: { flex: 1, backgroundColor: c.background },\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino, borderBottomColor: c.border,\n  },\n  tituloCabecera: { fontSize: tipografia.subtitle, fontWeight: peso.titulo, color: c.textPrimary },\n  subCabecera: { fontSize: tipografia.micro, color: c.textSecondary, marginTop: 1 },\n  hueso: { height: 84, borderRadius: radios.md, opacity: 0.6 },\n  contexto: { fontSize: tipografia.caption, color: c.textSecondary, fontWeight: peso.fuerte },\n  avisoRevision: {\n    marginTop: espaciado.e12, padding: espaciado.e12, borderRadius: radios.md,\n    borderWidth: trazo.fino, borderColor: c.border, backgroundColor: alpha(c.primary, 0.06),\n  },\n  avisoRevisionTexto: { fontSize: tipografia.micro, color: c.textSecondary, lineHeight: 16 },\n});\n","/**\n * components/ecomerse/EditorDeCombinaciones.tsx — LOS EJES DEL ANUNCIO Y SUS COMBINACIONES (Fase 4).\n *\n * EL PROBLEMA QUE CIERRA. Hasta la fase 4 el formulario del comerciante pedía «talla» y «color» como\n * TEXTO LIBRE. Eso servía para la ficha técnica —la tabla que el comprador lee— pero **no para\n * comprar**: el anuncio se vendía entero, con un solo precio y un solo stock, y el comprador no\n * elegía nada. Esta pantalla es donde el comerciante declara QUÉ SE PUEDE ELEGIR: los ejes, sus\n * valores, y una fila por combinación con su precio y sus unidades.\n *\n * DÓNDE VIVE, Y POR QUÉ AHÍ. Guarda por `PUT /ecomerse/seller/products/:id/options`, que es el\n * **carril rápido**: reponer una talla es una operación del día a día y no puede costar 24–48 h de\n * revisión. El contenido del anuncio (título, fotos, precio, categoría) sigue por el carril moderado,\n * y el servidor **rechaza** `options` en el alta a propósito para que nadie crea que las publicó.\n * Consecuencia que el comerciante nota: las combinaciones son un paso **después** de publicar.\n *\n * ES UN PORTE DEL EDITOR DE LIFE BOOK (`components/lifebook/publish/OptionGroupsEditor.tsx`), porque\n * los dos mercados comparten las REGLAS del SKU (módulo `opciones-producto.ts` del servidor) y la\n * forma de los ejes es la misma. Lo que NO se porta, y por qué:\n *\n *   · **Nada de ejes sugeridos por la categoría.** Life Book los tiene porque su categoría los trae.\n *     En el Mercado `GET /ecomerse/categories` devuelve `{id, code, label, icon, subs}`: no hay\n *     catálogo de ejes. En vez de inventar uno por categoría, hay una lista corta y visible —Color,\n *     Talla, Capacidad, Modelo, Medida— y un campo para el eje que no esté. Inventar la lista sería\n *     peor que no tenerla: el comerciante no sabría por qué su categoría no ofrece lo que espera.\n *   · **Nada de tabla de medidas.** Eso son las tallas de Life Book (`SizeChartEditor`); el Mercado no\n *     tiene tablas y no se le añaden.\n *   · **Nada de «avisar cuando llegue».** Ese endpoint es de Life Book. Sin él, quitamos la fila y ya\n *     está: el comprador no ve la combinación, que es más honesto que un botón que no hace nada.\n *   · **Nada de peso por combinación** (`weightG`, que el servidor admite): el Mercado no cobra por\n *     peso —el envío va por zonas y tarifa de agente— así que un campo así sería un dato muerto más.\n *\n * Y CINCO DECISIONES PROPIAS, tres de ellas CORRIGIENDO defectos que se vieron al portar:\n *\n *  1. **Quitar un valor SÍ limpia sus combinaciones.** En Life Book, `removeOptionValue` quita el\n *     valor del eje **sin tocar las filas**: quedan combinaciones que ya no existen, con unidades\n *     dentro, y el servidor las rechaza al guardar. Aquí se van con el valor, y si se llevan\n *     unidades **se dice cuántas antes de hacerlo** (el «botón que borra existencias sin decirlo»).\n *  2. **Una matriz incompleta es legítima.** Life Book exige `variantes.length === combinaciones\n *     posibles`; el servidor NO: valida las combinaciones que van, una a una. Y está bien que sea así,\n *     porque **no ofrecer todas es una decisión real del comerciante** («no fabrico la XL en azul»).\n *     La forma de decirla aquí es **quitar esa fila**, y el comprador ve ese valor como «no\n *     disponible» en vez de «agotado» — que son dos cosas distintas. Life Book lo diría con un flag\n *     `deshabilitado`; el Mercado no tiene ese flag y no se le añade uno al esquema por esto.\n *  3. **El relleno por lotes, aplicando sólo lo que esté escrito.** El precio vacío **hereda** el del\n *     anuncio, así que un precio común parecía salir gratis —se deja vacío y ya—. Pero eso cubre UN\n *     solo valor común, el del anuncio, y el precio que de verdad se repite en las combinaciones casi\n *     nunca es ése: el del anuncio es el «desde», y el real hay que escribirlo. Con 30 filas, 30 veces\n *     el mismo número. De ahí el bloque «Relleno por lotes»: dos campos y un botón, donde **lo que\n *     esté vacío no se toca** (no hay manera de poner un 0 sin querer) y **se avisa antes** de\n *     escribir encima de un valor ya puesto, diciendo cuántas filas pisa. Las EXISTENCIAS entran por\n *     el mismo sitio y ahí el ahorro es mayor, porque no tienen herencia posible: el servidor guarda\n *     un número y vacío significa 0 (no «las del anuncio»). Como el precio sí hereda, el bloque trae\n *     la vuelta atrás —«que todas hereden»—, que sin él sería inalcanzable después de un lote.\n *\n *     Y todo lo que se teclea se encadena con **Intro** sin cerrar el teclado: los valores de un eje\n *     («M» + Intro + «L» + Intro), el lote (precio → unidades) y las filas (precio → unidades → la\n *     siguiente). Añadir doce tallas o rellenar treinta filas no puede costar doce o sesenta viajes\n *     al dedo —el «relleno por lotes» del pliego, aplicado también al teclado—. El último campo de\n *     cada serie sí cierra el teclado, para dejar ver lo que hay debajo.\n *  4. **El resumen en vivo** (precio mín–máx y existencias totales). En el Mercado el stock del\n *     anuncio **es la suma de las combinaciones**, así que repartir 20 unidades en dos filas de 20 se\n *     guarda como 40. Eso no se ve mirando filas de una en una: se ve en un total. Y el rango de\n *     precios se avisa si pasa de 3×, porque el comprador ve el precio barato en la lista y al entrar\n *     se encuentra el caro.\n *  5. **`Sheet` para elegir la foto del color**, no un `<Modal>` a mano: se hereda el fondo, el cierre\n *     al tocar fuera, el botón físico de atrás y el tope de altura. Ojo con ese tope: `Sheet` recorta\n *     al **80 %** de la pantalla y lo que sobra se pierde, así que la rejilla lleva su alto calculado.\n *\n * LO QUE EL SERVIDOR IMPONE Y NO SE PUEDE SALTAR (mejor saberlo aquí que al guardar):\n *   · un eje de **color** exige, por cada valor, **una foto real del anuncio** —no vale un cuadradito\n *     con el color, y no vale una foto de fuera—;\n *   · cada combinación necesita un valor de **cada** eje, y no puede haber dos iguales;\n *   · **3 ejes**, **30 valores** por eje y **60 combinaciones** como máximo.\n */\nimport React, { useMemo, useRef, useState } from 'react';\nimport { Alert, Pressable, ScrollView, StyleSheet, Text, TextInput, useWindowDimensions, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport { Check, Plus, X } from 'lucide-react-native';\nimport {\n  GhostButton, InlineError, PrimaryButton, Sheet, alpha, altura, espaciado, icono, peso, radios, tipografia, trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport {\n  ecomerseApi,\n  type EcomerseOptionGroup,\n  type EcomerseOptionKind,\n  type EcomerseProductVariant,\n} from '../../api/ecomerse';\nimport { formatXAF } from '../../utils/formatHelpers';\nimport {\n  COMBOS_MAX, FACTOR_RANGO_AMPLIO, GRUPOS_MAX, VALORES_MAX,\n  aCodigo, combinacionesDe, firmaDe, numeroDe, resumenDe,\n  type BorradorVariante,\n} from '../../utils/combinaciones';\n\n/* ── Piezas del borrador ─────────────────────────────────────────────────────────────────────── */\n\ninterface ValorBorrador { value: string; imageUrl: string }\ninterface GrupoBorrador {\n  code: string;\n  label: string;\n  kind: EcomerseOptionKind;\n  values: ValorBorrador[];\n}\n\n/**\n * Los ejes que se ofrecen a un toque. Es una lista CORTA a propósito: son los cinco que el Mercado\n * ve de verdad (ropa, calzado, teléfonos, muebles), y el sexto caso —un eje que no esté— se escribe\n * en el campo de abajo con su tipo. No es una lista por categoría porque el Mercado no tiene ese\n * catálogo; ver la cabecera.\n */\nconst EJES: { label: string; kind: EcomerseOptionKind }[] = [\n  { label: 'Color', kind: 'color' },\n  { label: 'Talla', kind: 'size' },\n  { label: 'Capacidad', kind: 'text' },\n  { label: 'Modelo', kind: 'text' },\n  { label: 'Medida', kind: 'text' },\n];\n\nconst TIPOS: { id: EcomerseOptionKind; label: string; ayuda: string }[] = [\n  { id: 'color', label: 'Color', ayuda: 'cada uno con su foto real' },\n  { id: 'size', label: 'Talla', ayuda: 'S · M · L · 42…' },\n  { id: 'text', label: 'Otro', ayuda: 'capacidad, modelo, formato…' },\n];\n\n/** Sólo se comparan valores sin depender de mayúsculas ni de espacios de más. */\nconst norm = (v: unknown): string => String(v ?? '').trim().toLowerCase();\n\n/** Lo que devuelve el servidor → el borrador del editor (precio y stock pasan a TEXTO). */\nconst aBorrador = (options: EcomerseOptionGroup[] | undefined): GrupoBorrador[] =>\n  (options ?? []).map((g) => ({\n    code: g.code,\n    label: g.label || g.code,\n    kind: (g.kind ?? 'text') as EcomerseOptionKind,\n    values: (g.values ?? []).map((v) => ({ value: String(v.value), imageUrl: v.imageUrl ?? '' })),\n  }));\n\nconst aBorradorVariantes = (variants: EcomerseProductVariant[] | undefined): BorradorVariante[] =>\n  (variants ?? []).map((v) => ({\n    name: v.name,\n    priceXaf: v.priceXaf === null || v.priceXaf === undefined ? '' : String(v.priceXaf),\n    stockQuantity: String(v.stockQuantity ?? 0),\n    attributes: Object.fromEntries(Object.entries(v.attributes ?? {}).map(([k, x]) => [k, String(x)])),\n  }));\n\nexport interface ResultadoCombinaciones {\n  message: string;\n  options: EcomerseOptionGroup[];\n  variants: EcomerseProductVariant[];\n  /** El `stock` del anuncio ya espejado por el servidor (la suma de las combinaciones). */\n  stock: number;\n}\n\nexport default function EditorDeCombinaciones({\n  productoId, precioAnuncio, stockAnuncio, fotos, inicial, onGuardado,\n}: {\n  productoId: string;\n  /** El precio del anuncio. Es el que hereda una combinación sin precio propio. */\n  precioAnuncio: number;\n  /** Las existencias del anuncio AHORA. Con combinaciones ya guardadas, es su suma. */\n  stockAnuncio: number;\n  /** Las fotos del anuncio: la única lista de la que puede salir la foto real de un color. */\n  fotos: string[];\n  inicial: { options?: EcomerseOptionGroup[]; variants?: EcomerseProductVariant[] };\n  onGuardado: (r: ResultadoCombinaciones) => void;\n}) {\n  const { colors } = useTheme();\n  const { height: altoPantalla } = useWindowDimensions();\n  const est = estilos(colors);\n\n  /* El borrador. La pantalla monta este componente con `key={productoId}`, así que al cambiar de\n     anuncio se vuelve a leer: no hace falta sincronizar a mano. */\n  const [grupos, setGrupos] = useState<GrupoBorrador[]>(() => aBorrador(inicial.options));\n  const [variantes, setVariantes] = useState<BorradorVariante[]>(() => aBorradorVariantes(inicial.variants));\n  const [nuevo, setNuevo] = useState<{ label: string; kind: EcomerseOptionKind }>({ label: '', kind: 'text' });\n  const [valor, setValor] = useState<Record<string, string>>({});\n  /** Qué valor de color está eligiendo foto. */\n  const [eligiendo, setEligiendo] = useState<{ code: string; value: string } | null>(null);\n  const [guardando, setGuardando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  /** El relleno por lotes: lo que se va a aplicar a TODAS las filas. Vacío = ese campo no se toca. */\n  const [lote, setLote] = useState<{ precio: string; unidades: string }>({ precio: '', unidades: '' });\n  /**\n   * Los campos de cada fila, para encadenar con el Intro: precio → unidades → precio de la siguiente.\n   * Con 30 combinaciones eso es teclear y dar al Intro, en vez de apuntar con el dedo 60 veces.\n   *\n   * OJO, límite conocido: con `keyboardType=\"number-pad\"` la tecla de acción la pone el TECLADO, no la\n   * app. Los teclados que no la ofrecen en el bloque numérico dejan el encadenado sin usar, pero sin\n   * romper nada: se sigue tocando el campo a mano. El relleno por lotes es el camino que no depende\n   * del teclado, y por eso existe.\n   */\n  const refsPrecio = useRef<Array<TextInput | null>>([]);\n  const refsUnidad = useRef<Array<TextInput | null>>([]);\n  /** El campo de unidades del lote: el Intro del precio salta aquí y no cierra el teclado. */\n  const refUnidadesLote = useRef<TextInput | null>(null);\n\n  /** El anuncio YA venía con combinaciones: cambia lo que se propone al generar y qué se puede deshacer. */\n  const yaTenia = (inicial.options ?? []).length > 0;\n  /** Los ejes que cuentan: un eje sin valores no genera combinaciones (y bloquea el guardado). */\n  const utiles = useMemo(() => grupos.filter((g) => g.values.length > 0), [grupos]);\n  const combos = useMemo(() => combinacionesDe(utiles), [utiles]);\n  const resumen = useMemo(() => resumenDe(variantes, precioAnuncio), [variantes, precioAnuncio]);\n  const colorSinFoto = useMemo(\n    () => utiles.find((g) => g.kind === 'color' && g.values.some((v) => !v.imageUrl)) ?? null,\n    [utiles],\n  );\n  /** Combinaciones posibles que no tienen fila: no se venden (el comprador las ve «no disponible»). */\n  const sinFila = Math.max(0, combos.length - variantes.length);\n\n  /**\n   * El semáforo. Es lo que impide guardar algo que el servidor rechazaría, con el motivo escrito en\n   * el mismo sitio donde se arregla. Los tres primeros son reglas del servidor; el cuarto es una\n   * consecuencia de ellas (sin filas no hay nada que vender).\n   */\n  const problema = useMemo((): string | null => {\n    if (!grupos.length) return null;\n    if (grupos.some((g) => !g.values.length)) return 'Hay un eje sin ningún valor: ponle alguno o quítalo.';\n    if (colorSinFoto) {\n      const v = colorSinFoto.values.find((x) => !x.imageUrl);\n      return `El color «${v?.value}» necesita su foto real del producto en ese color: no vale solo el nombre.`;\n    }\n    if (combos.length > COMBOS_MAX) {\n      return `Con esos valores salen ${combos.length} combinaciones y el máximo es ${COMBOS_MAX}: quita algún valor.`;\n    }\n    if (!variantes.length) return 'Pulsa «Generar combinaciones» para poner el precio y las unidades de cada una.';\n    return null;\n  }, [grupos, colorSinFoto, combos.length, variantes.length]);\n\n  /* ── Los ejes ──────────────────────────────────────────────────────────────────────────────── */\n\n  const anadirEje = (label: string, kind: EcomerseOptionKind) => {\n    const code = aCodigo(label);\n    if (code.length < 2) { setError('Ponle un nombre al eje (por ejemplo «Color» o «Talla»).'); return; }\n    if (grupos.some((g) => g.code === code)) { setError(`Ya tienes el eje «${label.trim()}».`); return; }\n    if (grupos.length >= GRUPOS_MAX) { setError(`Como máximo ${GRUPOS_MAX} ejes (por ejemplo Color y Talla).`); return; }\n    setError(null);\n    /* Se crea VACÍO y se dice que le faltan valores. La alternativa —inventarle un valor— es lo que\n       hacía el editor de Life Book con un «—» que acababa publicado como si fuera una talla. */\n    setGrupos((prev) => [...prev, { code, label: label.trim(), kind, values: [] }]);\n  };\n\n  /**\n   * Quita un eje ENTERO. Se lleva sus combinaciones y, si alguna tenía unidades apuntadas, se avisa\n   * ANTES con el número exacto: quitar «Color» de un anuncio con 14 unidades repartidas no puede ser\n   * un toque silencioso.\n   */\n  const quitarEje = (code: string) => {\n    const g = grupos.find((x) => x.code === code);\n    const afectadas = variantes.filter((v) => v.attributes[code] !== undefined);\n    const unidades = afectadas.reduce((suma, v) => suma + (numeroDe(v.stockQuantity) ?? 0), 0);\n    const hacerlo = () => {\n      setGrupos((prev) => prev.filter((x) => x.code !== code));\n      setVariantes((prev) => prev.filter((v) => v.attributes[code] === undefined));\n    };\n    if (unidades > 0) {\n      Alert.alert(\n        `Quitar «${g?.label ?? code}»`,\n        `Se van ${afectadas.length === 1 ? '1 combinación' : `${afectadas.length} combinaciones`} y con ellas ${unidades} ${unidades === 1 ? 'unidad' : 'unidades'} apuntadas. ¿Seguir?`,\n        [{ text: 'Cancelar', style: 'cancel' }, { text: 'Quitar', style: 'destructive', onPress: hacerlo }],\n      );\n      return;\n    }\n    hacerlo();\n  };\n\n  const anadirValor = (code: string, texto: string) => {\n    const v = texto.trim().slice(0, 40);\n    const g = grupos.find((x) => x.code === code);\n    if (!g) return;\n    if (!v) { setError('El valor necesita un nombre.'); return; }\n    if (g.values.some((x) => norm(x.value) === norm(v))) { setError(`«${v}» ya está en ${g.label}.`); return; }\n    if (g.values.length >= VALORES_MAX) { setError(`Como máximo ${VALORES_MAX} valores por eje.`); return; }\n    setError(null);\n    setGrupos((prev) => prev.map((x) => (x.code === code ? { ...x, values: [...x.values, { value: v, imageUrl: '' }] } : x)));\n    setValor((prev) => ({ ...prev, [code]: '' }));\n  };\n\n  /**\n   * Quita un valor de un eje **y sus combinaciones**. Esto es lo que el editor de Life Book NO hace\n   * (`removeOptionValue` deja las filas): quedan combinaciones de un valor que ya no existe, con sus\n   * unidades dentro, y el guardado falla con un ««Rojo» no es un valor de «Color»» que no se puede\n   * arreglar desde la pantalla. Aquí se van con el valor, y se dice cuántas unidades se llevan.\n   */\n  const quitarValor = (code: string, value: string) => {\n    const afectadas = variantes.filter((v) => norm(v.attributes[code]) === norm(value));\n    const unidades = afectadas.reduce((suma, v) => suma + (numeroDe(v.stockQuantity) ?? 0), 0);\n    const hacerlo = () => {\n      setGrupos((prev) => prev.map((x) => (x.code === code ? { ...x, values: x.values.filter((y) => y.value !== value) } : x)));\n      setVariantes((prev) => prev.filter((v) => norm(v.attributes[code]) !== norm(value)));\n    };\n    if (unidades > 0) {\n      Alert.alert(\n        `Quitar «${value}»`,\n        `Se van ${afectadas.length === 1 ? '1 combinación' : `${afectadas.length} combinaciones`} y ${unidades} ${unidades === 1 ? 'unidad' : 'unidades'} apuntadas. ¿Seguir?`,\n        [{ text: 'Cancelar', style: 'cancel' }, { text: 'Quitar', style: 'destructive', onPress: hacerlo }],\n      );\n      return;\n    }\n    hacerlo();\n  };\n\n  const ponerFoto = (code: string, value: string, imageUrl: string) => {\n    setGrupos((prev) => prev.map((g) => (g.code === code\n      ? { ...g, values: g.values.map((v) => (v.value === value ? { ...v, imageUrl } : v)) }\n      : g)));\n    setEligiendo(null);\n  };\n\n  /* ── Las combinaciones ─────────────────────────────────────────────────────────────────────── */\n\n  /**\n   * Genera la matriz del producto cartesiano **conservando** lo ya escrito: una fila que ya existía\n   * (misma firma) mantiene su precio y sus unidades, así que añadir un color al final no borra el\n   * trabajo de media hora.\n   *\n   * Las filas NUEVAS no heredan el stock del anuncio a ciegas: sólo se propone cuando el anuncio no\n   * tenía combinaciones. Si ya las tenía, su `stock` es la SUMA, y repartir esa suma en cada fila\n   * nueva multiplicaría el total sin que nada lo dijera.\n   */\n  const generar = () => {\n    if (!utiles.length) { setError('Primero añade un eje con sus valores (por ejemplo Color o Talla).'); return; }\n    if (combos.length > COMBOS_MAX) { setError(`Con esos valores salen ${combos.length} combinaciones y el máximo es ${COMBOS_MAX}.`); return; }\n    setError(null);\n    const porFirma = new Map(variantes.map((v) => [firmaDe(utiles, v.attributes), v]));\n    setVariantes(combos.map((c) => {\n      const previo = porFirma.get(firmaDe(utiles, c.attrs));\n      return {\n        name: c.nombre,\n        priceXaf: previo?.priceXaf ?? '',\n        stockQuantity: previo?.stockQuantity ?? (yaTenia ? '' : String(stockAnuncio || 0)),\n        attributes: c.attrs,\n      };\n    }));\n  };\n\n  const quitarFila = (i: number) => setVariantes((prev) => prev.filter((_, j) => j !== i));\n\n  /* ── El relleno por lotes ──────────────────────────────────────────────────────────────────── */\n\n  /**\n   * Lo que va a pasar, escrito antes de pulsar. El botón no lleva un «aplicar» a secas porque son tres\n   * acciones distintas según lo que haya en los campos, y adivinar cuál de las tres va a correr es la\n   * clase de sorpresa que este editor evita en todo lo demás.\n   */\n  const etiquetaLote = useMemo(() => {\n    const p = numeroDe(lote.precio);\n    const u = numeroDe(lote.unidades);\n    if (p !== null && u !== null) return `Se pondrán ${formatXAF(p)} y ${u} ${u === 1 ? 'unidad' : 'unidades'} en cada una.`;\n    if (p !== null) return `Se pondrá solo el precio: ${formatXAF(p)} en cada una.`;\n    if (u !== null) return `Se pondrán solo las unidades: ${u} en cada una.`;\n    return 'Escribe un precio, unas unidades, o las dos cosas.';\n  }, [lote]);\n\n  /**\n   * Aplica a TODAS las filas únicamente lo que se haya escrito.\n   *\n   * El «vacío no se toca» es lo que hace que este bloque sea seguro: no hay forma de poner un precio\n   * de cero ni de vaciar existencias por dejar un campo en blanco. Y como sí escribe encima de lo que\n   * ya había —eso es justo lo que se le pide—, cuando pisa un valor distinto **lo dice antes**, con\n   * cuántas filas afecta: es de las cosas que no se deshacen con un «atrás».\n   */\n  const aplicarLote = () => {\n    const p = numeroDe(lote.precio);\n    const u = numeroDe(lote.unidades);\n    if (p === null && u === null) { setError('Escribe un precio o unas unidades para aplicarlos a todas.'); return; }\n    const hacerlo = () => {\n      setVariantes((prev) => prev.map((v) => ({\n        ...v,\n        /* Sólo se pisa el precio si se pidió un precio: `null` aquí significa «no lo toques», que es\n           distinto del `''` de la fila, que significa «hereda el del anuncio». */\n        priceXaf: p === null ? v.priceXaf : String(p),\n        stockQuantity: u === null ? v.stockQuantity : String(u),\n      })));\n      setLote({ precio: '', unidades: '' });\n      setError(null);\n    };\n    const pisadas = variantes.filter((v) => (\n      (p !== null && numeroDe(v.priceXaf) !== null && numeroDe(v.priceXaf) !== p)\n      || (u !== null && numeroDe(v.stockQuantity) !== null && numeroDe(v.stockQuantity) !== u)\n    )).length;\n    if (pisadas) {\n      Alert.alert(\n        'Se escribe encima',\n        `${pisadas === 1 ? '1 combinación ya tiene' : `${pisadas} combinaciones ya tienen`} otro valor en eso que vas a aplicar, y se pierde. ¿Seguir?`,\n        [{ text: 'Cancelar', style: 'cancel' }, { text: 'Aplicar', style: 'destructive', onPress: hacerlo }],\n      );\n      return;\n    }\n    hacerlo();\n  };\n\n  /**\n   * La vuelta atrás del precio en lote: dejarlo otra vez VACÍO en todas para que vuelvan a heredar el\n   * del anuncio.\n   *\n   * Sin esto, la regla «vacío hereda» sería inalcanzable en la práctica: después de aplicar un precio\n   * a 40 filas no habría manera de deshacerlo sin vaciarlas una a una. Sólo aparece si hay algo que\n   * borrar, así que no es un botón más que recordar cuando no hace falta.\n   */\n  const heredarPrecios = () => {\n    const conPrecio = variantes.filter((v) => numeroDe(v.priceXaf) !== null);\n    if (!conPrecio.length) return;\n    Alert.alert(\n      'Que todas hereden el precio',\n      `Se borran los precios escritos en ${conPrecio.length === 1 ? '1 combinación' : `${conPrecio.length} combinaciones`}: todas pasarán a costar lo que el anuncio (${formatXAF(precioAnuncio)}). ¿Seguir?`,\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        { text: 'Borrar', style: 'destructive', onPress: () => setVariantes((prev) => prev.map((v) => ({ ...v, priceXaf: '' }))) },\n      ],\n    );\n  };\n\n  /* ── Guardar ───────────────────────────────────────────────────────────────────────────────── */\n\n  const enviar = async (\n    body: { options: EcomerseOptionGroup[]; variants?: EcomerseProductVariant[] },\n    /**\n     * Lo que hay que hacer DESPUÉS de que el servidor confirme. Se usa para vaciar el borrador cuando\n     * la propia pantalla acaba de quitar todo. Va aquí y no en `quitarTodas` a propósito: si se\n     * vaciara antes y el guardado fallara, el comerciante perdería lo que tenía delante sin haber\n     * cambiado nada — y el servidor seguiría teniendo los ejes viejos.\n     */\n    tras?: () => void,\n  ) => {\n    setGuardando(true);\n    setError(null);\n    try {\n      const r = await ecomerseApi.updateProductOptions(productoId, body);\n      onGuardado(r);\n      tras?.();\n    } catch (e) {\n      /* El servidor explica qué pasa («El color «Rojo» necesita su foto real…», «La combinación\n         «Rojo · M» está repetida»). Se enseña tal cual: es más útil que un «error» genérico. */\n      setError(e instanceof Error ? e.message : 'No se pudieron guardar las combinaciones.');\n    } finally {\n      setGuardando(false);\n    }\n  };\n\n  const guardar = () => {\n    if (problema) { setError(problema); return; }\n    void enviar({\n      options: utiles.map((g) => ({\n        code: g.code,\n        label: g.label,\n        kind: g.kind,\n        values: g.values.map((v) => ({ value: v.value, imageUrl: v.imageUrl || null })),\n      })),\n      variants: variantes.map((v) => ({\n        name: v.name,\n        /* Vacío = `null` = hereda el precio del anuncio. NO se manda 0, que sería un precio de cero. */\n        priceXaf: numeroDe(v.priceXaf),\n        /* El stock SÍ es un número: el servidor no admite «hereda» aquí. Vacío = 0 (agotada). */\n        stockQuantity: numeroDe(v.stockQuantity) ?? 0,\n        attributes: v.attributes,\n      })),\n    });\n  };\n\n  /**\n   * Deshacer las combinaciones: el anuncio vuelve a venderse entero.\n   *\n   * Se avisa de algo que el servidor NO devuelve solo: al quedarse sin combinaciones, el `stock` del\n   * anuncio **deja de espejarse** y se queda con el último valor que tuvo (la suma). O sea que el\n   * anuncio hereda la suma de las combinaciones, y hay que revisarla a mano en «Anuncios». Callarlo\n   * dejaría un anuncio con 12 unidades que nadie apuntó en ningún sitio.\n   */\n  const quitarTodas = () => {\n    Alert.alert(\n      'Quitar las combinaciones',\n      `El anuncio volverá a venderse entero, con un solo precio (${formatXAF(precioAnuncio)}). Se pierden sus ${variantes.length === 1 ? '1 combinación' : `${variantes.length} combinaciones`} y sus precios.\\n\\nOjo: el anuncio se queda con las ${stockAnuncio} unidades que hoy suman las combinaciones. Revísalas después en «Anuncios» — eso ya se cambia desde la lista, sin volver aquí.`,\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        {\n          text: 'Quitar',\n          style: 'destructive',\n          onPress: () => {\n            void enviar({ options: [], variants: [] }, () => {\n              /* El borrador se vacía SÓLO cuando el servidor confirma, y hace falta: la pantalla no\n                 vuelve a montar este editor al guardar (es lo que evita cerrarle el borrador a quien\n                 está a media faena), así que sin esto seguiría enseñando los ejes y las combinaciones\n                 que se acaban de quitar — y el siguiente «Guardar combinaciones» las resucitaría,\n                 deshaciendo en silencio lo que el aviso acababa de dar por hecho. */\n              setGrupos([]);\n              setVariantes([]);\n              setValor({});\n              setNuevo({ label: '', kind: 'text' });\n            });\n          },\n        },\n      ],\n    );\n  };\n\n  /* La rejilla de fotos dentro del `Sheet`: el alto se CALCULA, porque el `Sheet` topa la hoja al\n     80 % de la pantalla y lo que desborda se pierde —incluida la salida—. Se descuenta el cromo fijo\n     (relleno de la hoja, título, nota, y el botón de cancelar) y se deja margen. */\n  const altoRejilla = Math.max(120, Math.round(altoPantalla * 0.8) - 260);\n  const entrada = [est.entrada, { color: colors.textPrimary, borderColor: colors.border, backgroundColor: colors.surface }];\n\n  return (\n    <View>\n      {/* El carril, dicho una vez y arriba: es la primera duda de quien ya publicó. */}\n      <Text style={est.intro}>\n        Aquí se elige QUÉ PUEDE ELEGIR el comprador. Se guarda al momento: reponer una talla no pasa por revisión.\n      </Text>\n\n      {/* ── Estado sin combinaciones: cómo se vende el anuncio AHORA ── */}\n      {!grupos.length && (\n        <View style={[est.tarjeta, { backgroundColor: colors.card, borderColor: colors.border }]}>\n          <Text style={est.etiqueta}>CÓMO SE VENDE HOY</Text>\n          <Text style={est.tituloBloque}>Entero, sin nada que elegir</Text>\n          <Text style={est.nota}>\n            El comprador compra el anuncio tal cual: {formatXAF(precioAnuncio)} y {stockAnuncio}{' '}\n            {stockAnuncio === 1 ? 'unidad' : 'unidades'}. Eso ya está bien para un artículo único\n            —un móvil, un mueble— y no hay que tocar nada.\n          </Text>\n          <Text style={[est.nota, { marginTop: espaciado.e8 }]}>\n            Añade un eje solo si el comprador tiene que <Text style={{ fontWeight: peso.fuerte, color: colors.textPrimary }}>elegir</Text>:\n            una talla, un color, una capacidad.\n          </Text>\n        </View>\n      )}\n\n      {/* ── 1 · Los ejes ── */}\n      <Text style={est.seccion}>1 · Ejes</Text>\n      <Text style={est.nota}>\n        Un eje es lo que se elige («Color», «Talla»); sus valores son las opciones (Rojo, Azul / S, M, L).\n      </Text>\n\n      {/* Sin fotos no hay eje de color posible: el servidor exige una foto REAL del anuncio por color. */}\n      {fotos.length === 0 && (\n        <View style={[est.aviso, { borderColor: colors.warning, backgroundColor: alpha(colors.warning, 0.08) }]}>\n          <Text style={[est.avisoTexto, { color: colors.warning }]}>\n            Este anuncio no tiene fotos, así que no puede tener un eje de <Text style={{ fontWeight: peso.fuerte }}>Color</Text>:\n            cada color necesita la foto real del producto en ese color. Las fotos se cambian en «Corregir anuncio»,\n            que sí vuelve a revisión.\n          </Text>\n        </View>\n      )}\n\n      {grupos.map((g) => (\n        <View key={g.code} style={[est.tarjeta, { borderColor: colors.border, backgroundColor: colors.surface }]}>\n          <View style={est.fila}>\n            <View style={{ flex: 1 }}>\n              <Text style={est.tituloBloque}>{g.label}</Text>\n              <Text style={est.nota}>\n                {g.kind === 'color' ? 'Color · cada uno con su foto' : g.kind === 'size' ? 'Talla' : 'Valores'}\n                {' · '}{g.values.length} {g.values.length === 1 ? 'valor' : 'valores'}\n              </Text>\n            </View>\n            <Pressable\n              onPress={() => quitarEje(g.code)}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Quitar el eje ${g.label}`}\n              hitSlop={espaciado.e8}\n              style={est.botonIcono}\n            >\n              <X size={icono.sm} color={colors.danger} />\n            </Pressable>\n          </View>\n\n          {g.kind === 'color' ? (\n            /* En un eje de color cada valor lleva su FOTO, y se elige entre las del anuncio: el\n               servidor rechaza una foto que no sea suya. */\n            <View style={est.rejillaColores}>\n              {g.values.map((v) => (\n                <View key={v.value} style={est.itemColor}>\n                  <Pressable\n                    onPress={() => setEligiendo({ code: g.code, value: v.value })}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={v.imageUrl ? `Cambiar la foto del color ${v.value}` : `Poner la foto del color ${v.value}`}\n                    style={[est.marcoFoto, { borderColor: v.imageUrl ? colors.success : colors.danger, backgroundColor: colors.background }]}\n                  >\n                    {v.imageUrl ? (\n                      <Image source={{ uri: v.imageUrl }} style={est.fotoColor} contentFit=\"cover\" transition={0} />\n                    ) : (\n                      <Text style={[est.faltaFoto, { color: colors.danger }]}>FALTA{'\\n'}FOTO</Text>\n                    )}\n                  </Pressable>\n                  <Text numberOfLines={1} style={[est.valorColor, { color: colors.textPrimary }]}>{v.value}</Text>\n                  <Pressable onPress={() => quitarValor(g.code, v.value)} accessibilityRole=\"button\" accessibilityLabel={`Quitar ${v.value}`} hitSlop={espaciado.e8}>\n                    <Text style={[est.quitar, { color: colors.danger }]}>quitar</Text>\n                  </Pressable>\n                </View>\n              ))}\n            </View>\n          ) : (\n            <View style={est.chips}>\n              {g.values.map((v) => (\n                <Pressable\n                  key={v.value}\n                  onPress={() => quitarValor(g.code, v.value)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`Quitar el valor ${v.value} de ${g.label}`}\n                  style={[est.chip, { borderColor: colors.border, backgroundColor: colors.card }]}\n                >\n                  <Text style={[est.chipTexto, { color: colors.textPrimary }]}>{v.value}</Text>\n                  <X size={icono.micro} color={colors.textSecondary} />\n                </Pressable>\n              ))}\n            </View>\n          )}\n\n          <View style={est.filaEntrada}>\n            <TextInput\n              value={valor[g.code] ?? ''}\n              onChangeText={(t) => setValor((prev) => ({ ...prev, [g.code]: t }))}\n              placeholder={g.kind === 'color' ? 'Ej.: Rojo' : g.kind === 'size' ? 'Ej.: M' : 'Ej.: 128 GB'}\n              placeholderTextColor={colors.textSecondary}\n              style={[...entrada, { flex: 1 }]}\n              accessibilityLabel={`Nuevo valor para ${g.label}`}\n              /* Intro AÑADE el valor y NO cierra el teclado (`submitBehavior=\"submit\"`): se encadena\n                 «M» + Intro + «L» + Intro sin volver a tocar el campo ni el botón de «+». Con `blur`\n                 —el comportamiento por defecto— cada valor costaría reabrir el teclado. */\n              returnKeyType=\"done\"\n              submitBehavior=\"submit\"\n              onSubmitEditing={() => anadirValor(g.code, valor[g.code] ?? '')}\n            />\n            <Pressable\n              onPress={() => anadirValor(g.code, valor[g.code] ?? '')}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`Añadir un valor a ${g.label}`}\n              style={[est.botonMas, { borderColor: colors.primary }]}\n            >\n              <Plus size={icono.md} color={colors.primary} />\n            </Pressable>\n          </View>\n          {!g.values.length && (\n            <Text style={[est.nota, { color: colors.warning, marginTop: espaciado.e4 }]}>\n              Añade al menos un valor: sin valores, este eje no vale para nada.\n            </Text>\n          )}\n          {g.kind === 'color' && g.values.some((v) => !v.imageUrl) && (\n            <Text style={[est.nota, { color: colors.danger, marginTop: espaciado.e4 }]}>\n              Toca el cuadro para elegir la foto real de ese color.\n            </Text>\n          )}\n        </View>\n      ))}\n\n      {/* Añadir un eje: los cinco de siempre a un toque, y el que no esté, escrito. */}\n      {grupos.length < GRUPOS_MAX && (\n        <View style={[est.tarjeta, { borderColor: colors.border }]}>\n          <Text style={est.etiqueta}>AÑADIR UN EJE</Text>\n          <View style={est.chips}>\n            {EJES.filter((e) => !grupos.some((g) => g.code === aCodigo(e.label))).map((e) => (\n              <Pressable\n                key={e.label}\n                onPress={() => anadirEje(e.label, e.kind)}\n                accessibilityRole=\"button\"\n                accessibilityLabel={`Añadir el eje ${e.label}`}\n                style={[est.chip, { borderColor: colors.primary, backgroundColor: colors.card }]}\n              >\n                <Plus size={icono.micro} color={colors.primary} />\n                <Text style={[est.chipTexto, { color: colors.primary }]}>{e.label}</Text>\n              </Pressable>\n            ))}\n          </View>\n          <View style={[est.filaEntrada, { marginTop: espaciado.e8 }]}>\n            <TextInput\n              value={nuevo.label}\n              onChangeText={(t) => setNuevo((prev) => ({ ...prev, label: t }))}\n              placeholder=\"Otro eje: «Almacenamiento», «Formato»…\"\n              placeholderTextColor={colors.textSecondary}\n              style={[...entrada, { flex: 1 }]}\n              accessibilityLabel=\"Nombre de otro eje\"\n              /* El Intro hace lo mismo que el «+» de al lado, para no tener que apuntar al botón: se\n                 escribe el nombre, se elige el tipo abajo y se remata con el Intro. */\n              returnKeyType=\"done\"\n              submitBehavior=\"submit\"\n              onSubmitEditing={() => { anadirEje(nuevo.label, nuevo.kind); setNuevo((prev) => ({ ...prev, label: '' })); }}\n            />\n            <Pressable\n              onPress={() => { anadirEje(nuevo.label, nuevo.kind); setNuevo((prev) => ({ ...prev, label: '' })); }}\n              accessibilityRole=\"button\"\n              accessibilityLabel=\"Añadir el eje escrito\"\n              style={[est.botonMas, { borderColor: colors.primary }]}\n            >\n              <Plus size={icono.md} color={colors.primary} />\n            </Pressable>\n          </View>\n          <View style={[est.chips, { marginTop: espaciado.e8 }]}>\n            {TIPOS.map((t) => {\n              const on = nuevo.kind === t.id;\n              return (\n                <Pressable\n                  key={t.id}\n                  onPress={() => setNuevo((prev) => ({ ...prev, kind: t.id }))}\n                  accessibilityRole=\"radio\"\n                  accessibilityState={{ checked: on }}\n                  accessibilityLabel={`Tipo: ${t.label}. ${t.ayuda}`}\n                  style={[est.chip, {\n                    borderColor: on ? alpha(colors.primary, 0.5) : colors.border,\n                    backgroundColor: on ? alpha(colors.primary, 0.12) : colors.card,\n                  }]}\n                >\n                  {on ? <Check size={icono.micro} color={colors.primary} /> : null}\n                  <Text style={[est.chipTexto, { color: on ? colors.primary : colors.textSecondary }]}>{t.label}</Text>\n                </Pressable>\n              );\n            })}\n          </View>\n          <Text style={[est.nota, { marginTop: espaciado.e4 }]}>\n            {TIPOS.find((t) => t.id === nuevo.kind)?.ayuda} · máximo {GRUPOS_MAX} ejes.\n          </Text>\n        </View>\n      )}\n\n      {/* ── 2 · Las combinaciones ── */}\n      {grupos.length > 0 && (\n        <>\n          <Text style={est.seccion}>2 · Combinaciones</Text>\n          <Text style={est.nota}>\n            Salen solas del cruce de los ejes: no se escriben. Pones su precio y sus unidades, y el precio\n            vacío hereda el del anuncio ({formatXAF(precioAnuncio)}).\n          </Text>\n\n          <View style={{ marginTop: espaciado.e8 }}>\n            <GhostButton\n              title={variantes.length ? 'Volver a generar (conserva lo escrito)' : 'Generar combinaciones'}\n              onPress={generar}\n            />\n          </View>\n\n          {combos.length > COMBOS_MAX && (\n            <View style={[est.aviso, { borderColor: colors.danger, backgroundColor: alpha(colors.danger, 0.08), marginTop: espaciado.e8 }]}>\n              <Text style={[est.avisoTexto, { color: colors.danger }]}>\n                Con esos valores salen {combos.length} combinaciones y el máximo es {COMBOS_MAX}: quita algún valor.\n              </Text>\n            </View>\n          )}\n\n          {/* Filas que faltan: no se venden. Se dice, no se bloquea — no ofrecer todas es una decisión\n              legítima («no fabrico la XL en azul»), y quitar la fila es como se dice. */}\n          {sinFila > 0 && combos.length <= COMBOS_MAX && (\n            <Text style={[est.nota, { marginTop: espaciado.e8, color: colors.warning }]}>\n              {sinFila === 1 ? '1 combinación posible no tiene fila' : `${sinFila} combinaciones posibles no tienen fila`}:\n              no se venden. Pulsa «Volver a generar» para añadirlas conservando lo escrito.\n            </Text>\n          )}\n\n          {/* ── El relleno por lotes: lo que se repite en todas se escribe UNA vez ── */}\n          {variantes.length > 1 && (\n            <View style={[est.tarjeta, { borderColor: colors.border, backgroundColor: colors.card }]}>\n              <Text style={est.etiqueta}>RELLENO POR LOTES</Text>\n              <Text style={est.nota}>\n                Lo mismo en {variantes.length} filas se escribe una vez aquí. Rellena <Text style={{ fontWeight: peso.fuerte, color: colors.textPrimary }}>solo</Text> lo\n                que quieras igualar: lo que dejes vacío no se toca.\n              </Text>\n              <View style={est.filaEntrada}>\n                <TextInput\n                  value={lote.precio}\n                  onChangeText={(t) => setLote((prev) => ({ ...prev, precio: t.replace(/[^\\d]/g, '') }))}\n                  keyboardType=\"number-pad\"\n                  placeholder={`Precio · ${precioAnuncio}`}\n                  placeholderTextColor={colors.textSecondary}\n                  style={[...entrada, { flex: 1 }]}\n                  accessibilityLabel=\"Precio para todas las combinaciones\"\n                  /* Precio → Intro → unidades, con el teclado abierto; y el Intro de unidades lo cierra\n                     (su `blurAndSubmit` por defecto). Así el lote entero se rellena sin tocar la\n                     pantalla: dos números, dos Intros y el botón. */\n                  returnKeyType=\"next\"\n                  submitBehavior=\"submit\"\n                  onSubmitEditing={() => refUnidadesLote.current?.focus()}\n                />\n                <TextInput\n                  ref={refUnidadesLote}\n                  value={lote.unidades}\n                  onChangeText={(t) => setLote((prev) => ({ ...prev, unidades: t.replace(/[^\\d]/g, '') }))}\n                  keyboardType=\"number-pad\"\n                  placeholder=\"Unidades\"\n                  placeholderTextColor={colors.textSecondary}\n                  style={[...entrada, { flex: 1 }]}\n                  accessibilityLabel=\"Unidades para todas las combinaciones\"\n                  returnKeyType=\"done\"\n                />\n              </View>\n              {/* Se dice lo que va a pasar ANTES de pulsar: son tres acciones distintas según lo que\n                  haya escrito, y adivinar cuál corre es la sorpresa que este editor evita en todo. */}\n              <Text style={[est.nota, { marginTop: espaciado.e4 }]}>{etiquetaLote}</Text>\n              <View style={{ marginTop: espaciado.e8 }}>\n                <GhostButton\n                  title={`Aplicar a las ${variantes.length}`}\n                  onPress={aplicarLote}\n                  disabled={!lote.precio && !lote.unidades}\n                />\n              </View>\n              {/* Sólo si hay algo que borrar: es la vuelta atrás del «vacío hereda», y sin precios\n                  escritos no habría nada que deshacer. */}\n              {variantes.some((v) => numeroDe(v.priceXaf) !== null) && (\n                <Pressable\n                  onPress={heredarPrecios}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Que todas hereden el precio del anuncio\"\n                  hitSlop={espaciado.e8}\n                >\n                  <Text style={[est.enlace, { color: colors.primary }]}>Que todas hereden el precio del anuncio</Text>\n                </Pressable>\n              )}\n            </View>\n          )}\n\n          <View style={{ marginTop: espaciado.e8 }}>\n            {variantes.map((v, i) => (\n              <View key={`${v.name}-${i}`} style={[est.filaCombo, { borderBottomColor: colors.border }]}>\n                <Text numberOfLines={1} style={[est.nombreCombo, { color: colors.textPrimary }]}>{v.name}</Text>\n                <TextInput\n                  ref={(el) => { refsPrecio.current[i] = el; }}\n                  value={v.priceXaf}\n                  onChangeText={(t) => setVariantes((prev) => prev.map((x, j) => (j === i ? { ...x, priceXaf: t.replace(/[^\\d]/g, '') } : x)))}\n                  keyboardType=\"number-pad\"\n                  placeholder={String(precioAnuncio)}\n                  placeholderTextColor={colors.textSecondary}\n                  style={[...entrada, est.entradaCombo]}\n                  accessibilityLabel={`Precio de ${v.name}`}\n                  /* El Intro salta al campo de al lado en vez de cerrar el teclado: la fila se rellena\n                     de un tirón. Con la última fila, Intro suelta el teclado y deja ver el resumen. */\n                  returnKeyType=\"next\"\n                  submitBehavior=\"submit\"\n                  onSubmitEditing={() => refsUnidad.current[i]?.focus()}\n                />\n                <TextInput\n                  ref={(el) => { refsUnidad.current[i] = el; }}\n                  value={v.stockQuantity}\n                  onChangeText={(t) => setVariantes((prev) => prev.map((x, j) => (j === i ? { ...x, stockQuantity: t.replace(/[^\\d]/g, '') } : x)))}\n                  keyboardType=\"number-pad\"\n                  placeholder=\"0\"\n                  placeholderTextColor={colors.textSecondary}\n                  style={[...entrada, est.entradaCombo]}\n                  accessibilityLabel={`Unidades de ${v.name}`}\n                  returnKeyType={i < variantes.length - 1 ? 'next' : 'done'}\n                  submitBehavior={i < variantes.length - 1 ? 'submit' : 'blurAndSubmit'}\n                  onSubmitEditing={() => { if (i < variantes.length - 1) refsPrecio.current[i + 1]?.focus(); }}\n                />\n                <Pressable\n                  onPress={() => quitarFila(i)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel={`Quitar la combinación ${v.name}`}\n                  hitSlop={espaciado.e8}\n                  style={est.botonIcono}\n                >\n                  <X size={icono.sm} color={colors.danger} />\n                </Pressable>\n              </View>\n            ))}\n            {variantes.length > 0 && (\n              <View style={est.cabeceraCombo}>\n                <Text style={[est.nota, { flex: 1 }]}>combinación</Text>\n                <Text style={[est.nota, est.entradaCombo, { textAlign: 'center' }]}>precio</Text>\n                <Text style={[est.nota, est.entradaCombo, { textAlign: 'center' }]}>unidades</Text>\n                <View style={est.botonIcono} />\n              </View>\n            )}\n          </View>\n\n          {/* ── 3 · El resumen: las dos cifras que no se ven mirando filas de una en una ── */}\n          {variantes.length > 0 && (\n            <>\n              <Text style={est.seccion}>3 · Resumen</Text>\n              <View style={[est.tarjeta, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                <Text style={[est.cifra, { color: colors.textPrimary }]}>\n                  {resumen.precioMin === null\n                    ? 'Sin precio'\n                    : resumen.precioMin === resumen.precioMax\n                      ? formatXAF(resumen.precioMin)\n                      : `${formatXAF(resumen.precioMin)} – ${formatXAF(resumen.precioMax!)}`}\n                  <Text style={est.cifraPie}>{'  '}lo que puede pagar el comprador</Text>\n                </Text>\n                <Text style={[est.cifra, { color: colors.textPrimary, marginTop: espaciado.e4 }]}>\n                  {resumen.stockTotal} {resumen.stockTotal === 1 ? 'unidad' : 'unidades'}\n                  <Text style={est.cifraPie}>{'  '}en total, sumando las combinaciones</Text>\n                </Text>\n\n                {/* El stock del anuncio ES esta suma: sin decirlo, repartir 20 en dos filas de 20\n                    se guarda como 40 y nadie se entera. */}\n                <Text style={[est.nota, { marginTop: espaciado.e8 }]}>\n                  El anuncio pasará a mostrar estas {resumen.stockTotal} unidades: con combinaciones, su stock es la suma.\n                </Text>\n\n                {resumen.rangoAmplio && (\n                  <View style={[est.aviso, { borderColor: colors.warning, backgroundColor: alpha(colors.warning, 0.08), marginTop: espaciado.e8 }]}>\n                    <Text style={[est.avisoTexto, { color: colors.warning }]}>\n                      El precio más alto es más de {FACTOR_RANGO_AMPLIO} veces el más bajo. El comprador ve el barato en la lista\n                      y al entrar se encuentra el caro: si la diferencia es tan grande, suelen ser dos anuncios.\n                    </Text>\n                  </View>\n                )}\n                {resumen.agotadas > 0 && (\n                  <Text style={[est.nota, { marginTop: espaciado.e8, color: colors.warning }]}>\n                    {resumen.agotadas === 1 ? '1 combinación se queda sin unidades' : `${resumen.agotadas} combinaciones se quedan sin unidades`}:\n                    el comprador las verá como «agotado». Si no vas a reponerlas, quítales la fila y no aparecerán.\n                  </Text>\n                )}\n              </View>\n            </>\n          )}\n        </>\n      )}\n\n      {error && <View style={{ marginTop: espaciado.e12 }}><InlineError mensaje={error} /></View>}\n\n      {grupos.length > 0 && (\n        <View style={{ marginTop: espaciado.e16 }}>\n          <PrimaryButton\n            title={guardando ? 'Guardando…' : 'Guardar combinaciones'}\n            onPress={guardar}\n            disabled={guardando || !!problema}\n          />\n          {problema && !error && (\n            <Text style={[est.nota, { marginTop: espaciado.e8, textAlign: 'center' }]}>{problema}</Text>\n          )}\n        </View>\n      )}\n\n      {/* Deshacer: sólo si el anuncio YA tenía combinaciones. Sin esto, quitar los ejes no se podría\n          guardar (la lista vacía de ejes no es un «guardar», es otra cosa). */}\n      {yaTenia && (\n        <View style={{ marginTop: espaciado.e12 }}>\n          <GhostButton title=\"Quitar todas las combinaciones\" onPress={quitarTodas} disabled={guardando} />\n        </View>\n      )}\n\n      {/* ── Elegir la foto REAL de un color, entre las fotos del anuncio ── */}\n      <Sheet\n        visible={eligiendo !== null}\n        position=\"bottom\"\n        title=\"Foto real del color\"\n        onClose={() => setEligiendo(null)}\n      >\n        <Text style={est.nota}>\n          «{eligiendo?.value}»: elige, entre las fotos de este anuncio, la que enseña el producto en ese color.\n          Es la que verá el comprador al elegirlo.\n        </Text>\n        {fotos.length ? (\n          <ScrollView style={{ maxHeight: altoRejilla }} showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingVertical: espaciado.e12 }}>\n            <View style={est.rejillaFotos}>\n              {fotos.map((url) => (\n                <Pressable\n                  key={url}\n                  onPress={() => eligiendo && ponerFoto(eligiendo.code, eligiendo.value, url)}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Usar esta foto\"\n                  style={[est.celdaFoto, { borderColor: colors.border, backgroundColor: colors.surface }]}\n                >\n                  <Image source={{ uri: url }} style={est.fotoCelda} contentFit=\"cover\" transition={0} />\n                </Pressable>\n              ))}\n            </View>\n          </ScrollView>\n        ) : (\n          <Text style={[est.nota, { marginTop: espaciado.e12, color: colors.danger }]}>\n            Este anuncio todavía no tiene fotos. Añádelas en «Corregir anuncio» y vuelve aquí.\n          </Text>\n        )}\n        <GhostButton title=\"Cancelar\" onPress={() => setEligiendo(null)} />\n      </Sheet>\n    </View>\n  );\n}\n\nconst estilos = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  intro: { fontSize: tipografia.caption, color: c.textSecondary, lineHeight: 18, marginBottom: espaciado.e12 },\n  seccion: { fontSize: tipografia.body, fontWeight: peso.titulo, color: c.textPrimary, marginTop: espaciado.e24, marginBottom: espaciado.e4 },\n  etiqueta: { fontSize: tipografia.micro, fontWeight: peso.fuerte, color: c.textSecondary, letterSpacing: 0.4, marginBottom: espaciado.e4 },\n  tituloBloque: { fontSize: tipografia.body, fontWeight: peso.titulo, color: c.textPrimary },\n  nota: { fontSize: tipografia.micro, color: c.textSecondary, lineHeight: 16, marginTop: espaciado.e2 },\n  tarjeta: { borderWidth: trazo.fino, borderRadius: radios.lg, padding: espaciado.e12, marginTop: espaciado.e12 },\n  aviso: { borderWidth: trazo.fino, borderRadius: radios.md, padding: espaciado.e8, marginTop: espaciado.e8 },\n  avisoTexto: { fontSize: tipografia.micro, lineHeight: 16 },\n  fila: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 },\n  filaEntrada: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, marginTop: espaciado.e8 },\n  entrada: { borderWidth: trazo.fino, borderRadius: radios.md, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e8, fontSize: tipografia.caption },\n  botonMas: { width: altura.control, height: altura.control, borderRadius: radios.md, borderWidth: trazo.base, alignItems: 'center', justifyContent: 'center' },\n  /* El 44 del kit, no un cuadrado bonito: es un botón de sólo icono y por debajo de eso el dedo falla. */\n  botonIcono: { width: altura.punto, height: altura.punto, alignItems: 'center', justifyContent: 'center' },\n  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8, marginTop: espaciado.e8 },\n  chip: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e4, paddingHorizontal: espaciado.e8, paddingVertical: espaciado.e4 + 2, borderRadius: radios.full, borderWidth: trazo.fino },\n  chipTexto: { fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  rejillaColores: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e12, marginTop: espaciado.e8 },\n  itemColor: { alignItems: 'center', gap: espaciado.e4, width: 68 },\n  marcoFoto: { width: 62, height: 62, borderRadius: radios.md, borderWidth: trazo.fuerte, overflow: 'hidden', alignItems: 'center', justifyContent: 'center' },\n  fotoColor: { width: '100%', height: '100%' },\n  faltaFoto: { fontSize: tipografia.micro, fontWeight: peso.fuerte, textAlign: 'center' },\n  valorColor: { fontSize: tipografia.micro, fontWeight: peso.fuerte, maxWidth: 64, textAlign: 'center' },\n  quitar: { fontSize: tipografia.micro, fontWeight: peso.fuerte },\n  cabeceraCombo: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, paddingTop: espaciado.e4 },\n  filaCombo: { flexDirection: 'row', alignItems: 'center', gap: espaciado.e8, borderBottomWidth: trazo.fino, paddingVertical: espaciado.e8 },\n  nombreCombo: { flex: 1, fontSize: tipografia.caption, fontWeight: peso.fuerte },\n  /* 72 dp: cabe un importe de seis cifras a 12 px. Vivía en 78 cuando el botón de quitar medía 32;\n     con el mínimo tocable de 44 hay que devolverle 6 dp al nombre, que es lo que se lee. */\n  entradaCombo: { width: 72, textAlign: 'center' },\n  cifra: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  cifraPie: { fontSize: tipografia.micro, fontWeight: peso.normal, color: c.textSecondary },\n  /* Acción secundaria de texto, para lo que no merece un botón propio (la vuelta atrás del lote). */\n  enlace: { fontSize: tipografia.caption, fontWeight: peso.fuerte, marginTop: espaciado.e8 },\n  rejillaFotos: { flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 },\n  celdaFoto: { width: 96, height: 96, borderRadius: radios.md, borderWidth: trazo.fino, overflow: 'hidden' },\n  fotoCelda: { width: '100%', height: '100%' },\n});\n","/**\n * Resumen — la portada de la zona del comerciante. La pestaña 首页 de Pinduoduo, en versión honesta.\n *\n * LA PORTADA ES UNA LISTA DE TAREAS, NO UN GRÁFICO\n * Lo primero que ve el comerciante al abrir no es cuánto vendió: es **qué le falta hacer**. Por eso\n * el orden es: KPI (contexto) → contadores accionables → alarmas → rendimiento → bajo stock →\n * accesos rápidos. Y por eso los contadores **llevan a Pedidos ya filtrado**: un contador que no\n * filtra es un número decorativo, que es exactamente lo que el plan manda evitar.\n *\n * SIN BACKEND NUEVO\n * Todo lo que se pinta aquí sale de dos llamadas que ya existían: `sellerMe()` (que trae la tienda y\n * **todos sus anuncios** con `views`, `favoriteCount`, `stock` y `status`) y `orderCounts('seller')`\n * + `myOrders('seller')`. No hay endpoint de estadísticas del vendedor —los `admin/stats` son de la\n * plataforma— y no se inventa uno: el plan descarta una pestaña de gráficos inventados.\n *\n * DOS HONESTIDADES QUE SE VEN EN PANTALLA (y no son letra pequeña):\n *  1. Las visitas y los favoritos son **del anuncio, no de la tienda**: sumar los contadores de los\n *     anuncios y llamarlo «visitas de mi tienda» sería mentir con un número propio.\n *  2. El importe del mes se calcula sobre una página de pedidos, no sobre el histórico entero. Si la\n *     página se llena, se dice en la propia tarjeta.\n */\n\nimport React, { useCallback, useState } from 'react';\nimport { Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport { AlertTriangle, ChevronRight, FileText, PackagePlus, Star, Store, TrendingUp } from 'lucide-react-native';\nimport {\n  EmptyState, InlineError, Precio, alpha, espaciado, icono, peso, radios, tipografia,\n  trazo, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseOrder, type EcomerseSellerMe } from '../../api/ecomerse';\nimport { formatXAF } from '../../utils/formatHelpers';\nimport { FilaRequisito } from '../../components/ecomerse/FilaRequisito';\n\n/** Cuántos pedidos se traen para calcular el KPI del mes. Ver la nota de honestidad de arriba. */\nconst PEDIDOS_KPI = 50;\n/** A partir de estas existencias, el anuncio avisa. Con 1 o 2 unidades no se llega a una semana. */\nconst UMBRAL_BAJO_STOCK = 2;\n\n/**\n * Los cuatro contadores accionables, calcados de 待处理 / 待配送 / 异常包裹 / 已完成 de la app de\n * referencia: cada uno es un ESTADO ACCIONABLE, no una métrica. El `filtro` es el id del chip de la\n * pantalla de Pedidos — van en pareja, y si uno cambia de nombre hay que cambiar el otro.\n */\nconst CONTADORES = [\n  { id: 'pendiente', label: 'Por enviar', estados: ['pending'], tono: 'aviso' },\n  { id: 'camino', label: 'En camino', estados: ['confirmed', 'in_transit'], tono: 'info' },\n  { id: 'disputado', label: 'En disputa', estados: ['disputed'], tono: 'peligro' },\n  { id: 'entregado', label: 'Completados', estados: ['delivered'], tono: 'bien' },\n] as const;\n\nexport default function TiendaResumen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n\n  const [me, setMe] = useState<EcomerseSellerMe | null>(null);\n  const [counts, setCounts] = useState<Record<string, number>>({});\n  const [pedidos, setPedidos] = useState<EcomerseOrder[]>([]);\n  const [totalPedidos, setTotalPedidos] = useState(0);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const cargar = useCallback(async (esRefresco = false) => {\n    if (esRefresco) setRefrescando(true); else setCargando(true);\n    setError(null);\n    try {\n      const m = await ecomerseApi.sellerMe();\n      setMe(m);\n      if (m.seller) {\n        /* Los pedidos y sus contadores solo tienen sentido con tienda dada de alta. */\n        const [c, o] = await Promise.all([\n          ecomerseApi.orderCounts('seller'),\n          ecomerseApi.myOrders('seller', { limit: PEDIDOS_KPI }),\n        ]);\n        setCounts(c.porEstado);\n        setPedidos(o.orders);\n        setTotalPedidos(o.total);\n      } else {\n        setCounts({}); setPedidos([]); setTotalPedidos(0);\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar tu tienda. Revisa la conexión.');\n    } finally {\n      setCargando(false); setRefrescando(false);\n    }\n  }, []);\n\n  /* Al volver a la pestaña: si acabas de publicar o de entregar un pedido, los números de la\n     portada tienen que estar al día. Una portada con datos de hace dos pantallas miente. */\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  const s = estilos(colors);\n  const seller = me?.seller;\n  const productos = me?.products ?? [];\n  const activa = seller?.status === 'active';\n\n  /* ---- Cálculos del mes ---- */\n  const ahora = new Date();\n  const delMes = pedidos.filter((o) => {\n    const f = new Date(o.createdAt);\n    return o.status !== 'cancelled' && f.getFullYear() === ahora.getFullYear() && f.getMonth() === ahora.getMonth();\n  });\n  const importeMes = delMes.reduce((t, o) => t + (o.totalXaf ?? 0), 0);\n  const kpiTruncado = totalPedidos > pedidos.length;\n\n  /* ---- Alarmas: lo que hay que arreglar, contado ---- */\n  const rechazados = productos.filter((p) => p.status === 'rejected');\n  const agotados = productos.filter((p) => p.status === 'sold_out' || (p.status === 'active' && p.stock <= 0));\n  const borradores = productos.filter((p) => p.status === 'draft');\n  const bajoStock = productos.filter((p) => p.status === 'active' && p.stock > 0 && p.stock <= UMBRAL_BAJO_STOCK);\n  const alarmas = [\n    rechazados.length > 0 && {\n      id: 'rechazados', icono: AlertTriangle, tono: colors.danger,\n      texto: `${rechazados.length} ${rechazados.length === 1 ? 'anuncio rechazado' : 'anuncios rechazados'} — corregir`,\n      ruta: '/tienda/anuncios',\n    },\n    agotados.length > 0 && {\n      id: 'agotados', icono: AlertTriangle, tono: colors.warning,\n      texto: `${agotados.length} ${agotados.length === 1 ? 'anuncio agotado' : 'anuncios agotados'} — reponer`,\n      ruta: '/tienda/anuncios',\n    },\n    borradores.length > 0 && {\n      id: 'borradores', icono: FileText, tono: colors.textSecondary,\n      texto: `${borradores.length} sin publicar`,\n      ruta: '/tienda/anuncios',\n    },\n  ].filter(Boolean) as Array<{ id: string; icono: typeof AlertTriangle; tono: string; texto: string; ruta: string }>;\n\n  /* ---- Rendimiento: suma de los contadores de los anuncios ---- */\n  const visitas = productos.reduce((t, p) => t + (p.views ?? 0), 0);\n  const favoritos = productos.reduce((t, p) => t + (p.favoriteCount ?? 0), 0);\n\n  if (cargando) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        <View style={s.cabecera}><Text style={s.titulo}>Mi tienda</Text></View>\n        <View style={{ padding: espaciado.e16, gap: espaciado.e12 }}>\n          {[0, 1, 2].map((i) => <View key={i} style={[s.hueso, { backgroundColor: colors.border }]} />)}\n        </View>\n      </View>\n    );\n  }\n\n  if (error) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        <View style={s.cabecera}><Text style={s.titulo}>Mi tienda</Text></View>\n        <View style={{ padding: espaciado.e16 }}>\n          <InlineError mensaje={error} onReintentar={() => cargar()} />\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <View style={[s.raiz, { paddingTop: insets.top }]}>\n      <View style={s.cabecera}>\n        <View style={{ flex: 1 }}>\n          <Text style={s.titulo}>Mi tienda</Text>\n          <Text style={s.subtitulo} numberOfLines={1}>\n            {seller ? `${seller.businessName} · ${seller.city}` : 'Aún sin tienda'}\n          </Text>\n        </View>\n      </View>\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: espaciado.e32 }}\n        showsVerticalScrollIndicator={false}\n        refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => cargar(true)} />}\n      >\n\n        {/* ─── SIN TIENDA APROBADA: el mapa del onboarding, que es la primera «tarea» de la portada */}\n        {!activa && (\n          <View style={[s.tarjeta, { backgroundColor: alpha(colors.primary, 0.06), marginBottom: espaciado.e16 }]}>\n            <Text style={s.etiqueta}>{seller ? 'TU TIENDA ESTÁ EN REVISIÓN' : 'PARA VENDER NECESITAS'}</Text>\n            <Text style={s.tituloBloque}>\n              {seller ? 'Casi está: falta la aprobación' : 'Tres pasos y empiezas a publicar'}\n            </Text>\n            <View style={{ marginTop: espaciado.e8 }}>\n              <FilaRequisito\n                ok={!!me?.kycOk}\n                label=\"Identidad verificada (KYC)\"\n                hint={me?.kycOk ? undefined : (me?.kycMessage ?? 'Toca para verificar')}\n                onPress={me?.kycOk ? undefined : () => router.push('/driver-onboarding' as never)}\n              />\n              <FilaRequisito\n                ok={!!seller?.businessName && !!seller?.city}\n                label=\"Datos del negocio (nombre + ciudad)\"\n                hint={seller ? undefined : 'Se rellenan en la pestaña «Tienda»'}\n                onPress={seller ? undefined : () => router.replace('/tienda/perfil' as never)}\n              />\n              <FilaRequisito\n                ok={!!activa}\n                label=\"Aprobación del administrador\"\n                hint={seller ? (activa ? undefined : 'Suele tardar 24–48 h') : 'Sin solicitud'}\n              />\n            </View>\n            {seller?.status === 'rejected' && seller.rejectionReason ? (\n              <Text style={[s.nota, { color: colors.danger }]}>Motivo del rechazo: {seller.rejectionReason}</Text>\n            ) : null}\n          </View>\n        )}\n\n        {/* ─── CON TIENDA: el cuadro de mando */}\n        {activa && (\n          <>\n            {/* KPI del mes. El importe ES el sujeto de la línea → `Precio`, no una frase con el\n                número dentro (doctrina «figura o frase», FASE-2-PRECIO.md). */}\n            <View style={[s.tarjeta, { backgroundColor: colors.card, marginBottom: espaciado.e12 }]}>\n              <Text style={s.etiqueta}>VENDIDO ESTE MES</Text>\n              <Precio valor={importeMes} tamano=\"xl\" />\n              <Text style={s.nota}>\n                {delMes.length === 0\n                  ? 'Ninguna venta este mes todavía.'\n                  : `${delMes.length} ${delMes.length === 1 ? 'pedido' : 'pedidos'} · no cuenta los cancelados`}\n              </Text>\n              {kpiTruncado && (\n                <Text style={[s.nota, { color: colors.warning }]}>\n                  Calculado sobre tus últimos {pedidos.length} pedidos de {totalPedidos}.\n                </Text>\n              )}\n            </View>\n\n            {/* Cuatro contadores accionables. Cada uno ABRE Pedidos ya filtrado. */}\n            <View style={s.filaContadores}>\n              {CONTADORES.map((c) => {\n                const n = c.estados.reduce((t, e) => t + (counts[e] ?? 0), 0);\n                const tono = c.tono === 'peligro' ? colors.danger : c.tono === 'bien' ? colors.success : c.tono === 'aviso' ? colors.warning : colors.primary;\n                return (\n                  <Pressable\n                    key={c.id}\n                    onPress={() => router.push(`/tienda/pedidos?filtro=${c.id}` as never)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`${c.label}: ${n} ${n === 1 ? 'pedido' : 'pedidos'}. Abre la lista filtrada.`}\n                    style={({ pressed }) => [s.contador, { borderColor: colors.border, backgroundColor: colors.card, opacity: pressed ? 0.7 : 1 }]}\n                  >\n                    <Text style={[s.cifraContador, { color: n > 0 ? tono : colors.textSecondary }]}>{n}</Text>\n                    <Text style={s.etiquetaContador} numberOfLines={2}>{c.label}</Text>\n                  </Pressable>\n                );\n              })}\n            </View>\n\n            {/* Alarmas: solo si hay algo que arreglar. Un bloque de avisos vacío entrena a ignorarlo. */}\n            {alarmas.length > 0 && (\n              <View style={{ marginTop: espaciado.e16 }}>\n                <Text style={s.tituloBloque}>Necesita tu atención</Text>\n                {alarmas.map((a) => {\n                  const Icon = a.icono;\n                  return (\n                    <Pressable\n                      key={a.id}\n                      onPress={() => router.push(a.ruta as never)}\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={a.texto}\n                      style={({ pressed }) => [s.alarma, { backgroundColor: alpha(a.tono, 0.08), borderColor: alpha(a.tono, 0.25), opacity: pressed ? 0.7 : 1 }]}\n                    >\n                      <Icon size={icono.sm} color={a.tono} />\n                      <Text style={[s.textoAlarma, { color: colors.textPrimary }]} numberOfLines={2}>{a.texto}</Text>\n                      <ChevronRight size={icono.sm} color={colors.textSecondary} />\n                    </Pressable>\n                  );\n                })}\n              </View>\n            )}\n\n            {/* Rendimiento. Con el aviso de qué mide de verdad. */}\n            <View style={{ marginTop: espaciado.e24 }}>\n              <Text style={s.tituloBloque}>Rendimiento</Text>\n              <View style={s.filaContadores}>\n                <View style={[s.contador, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                  <Text style={[s.cifraContador, { color: colors.textPrimary }]}>{visitas}</Text>\n                  <Text style={s.etiquetaContador}>Visitas</Text>\n                </View>\n                <View style={[s.contador, { borderColor: colors.border, backgroundColor: colors.card }]}>\n                  <Text style={[s.cifraContador, { color: colors.textPrimary }]}>{favoritos}</Text>\n                  <Text style={s.etiquetaContador}>Favoritos</Text>\n                </View>\n              </View>\n              <Text style={[s.nota, { marginTop: espaciado.e8 }]}>\n                Suma de tus {productos.length} {productos.length === 1 ? 'anuncio' : 'anuncios'}. Son visitas del\n                anuncio, no de la tienda: el Mercado no cuenta quién entra a la tienda.\n              </Text>\n            </View>\n\n            {/* Bajo stock: la lista de la compra, que es lo que de verdad se mira a diario. */}\n            <View style={{ marginTop: espaciado.e24 }}>\n              <Text style={s.tituloBloque}>Se está acabando</Text>\n              {bajoStock.length === 0 ? (\n                <Text style={s.nota}>Ningún anuncio activo por debajo de {UMBRAL_BAJO_STOCK + 1} unidades.</Text>\n              ) : (\n                bajoStock.slice(0, 4).map((p) => (\n                  <Pressable\n                    key={p.id}\n                    onPress={() => router.push('/tienda/anuncios' as never)}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={`${p.title}: quedan ${p.stock}`}\n                    style={({ pressed }) => [s.filaProducto, { borderBottomColor: colors.border, opacity: pressed ? 0.7 : 1 }]}\n                  >\n                    <View style={{ flex: 1 }}>\n                      <Text style={s.nombreProducto} numberOfLines={1}>{p.title}</Text>\n                      {/* El importe va DENTRO de una frase → `formatXAF` suelto, no `Precio`:\n                          `Precio` devuelve una View y meter una caja en una frase rompe su\n                          ajuste de línea (doctrina «figura o frase»). */}\n                      <Text style={s.nota}>{formatXAF(p.priceXaf)} · quedan {p.stock}</Text>\n                    </View>\n                    <Text style={[s.sello, { color: colors.warning }]}>Reponer</Text>\n                  </Pressable>\n                ))\n              )}\n            </View>\n\n            {/* Accesos rápidos: lo que se hace desde la portada sin bajar de pestaña. */}\n            <View style={{ marginTop: espaciado.e24 }}>\n              <Text style={s.tituloBloque}>Accesos</Text>\n              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: espaciado.e8 }}>\n                <Acceso Icono={PackagePlus} label=\"Publicar\" ruta=\"/tienda/publicar\" onIr={(r) => router.push(r as never)} />\n                <Acceso Icono={Store} label=\"Ver mi tienda\" ruta={seller ? `/ecomerse-tienda?id=${seller.id}` : '/tienda'} onIr={(r) => router.push(r as never)} />\n                <Acceso Icono={FileText} label=\"Documentos\" ruta=\"/ecomerse-docs\" onIr={(r) => router.push(r as never)} />\n                <Acceso Icono={TrendingUp} label=\"Mi plan\" ruta=\"/ecomerse-planes\" onIr={(r) => router.push(r as never)} />\n              </View>\n            </View>\n          </>\n        )}\n\n        {/* ─── CON TIENDA PERO SIN ANUNCIOS: el estado vacío con su CTA, como manda el patrón */}\n        {activa && productos.length === 0 && (\n          <View style={{ marginTop: espaciado.e24 }}>\n            <EmptyState\n              emoji=\"📦\"\n              titulo=\"Todavía no has publicado\"\n              texto=\"Tu tienda ya está aprobada y a la vista. Publica el primer anuncio y aparecerá en el Mercado con tu nombre.\"\n              accionLabel=\"Publicar mi primer producto\"\n              accionPrimaria\n              onAccion={() => router.push('/tienda/publicar' as never)}\n            />\n          </View>\n        )}\n\n        {/* Estrella: recuerda que las valoraciones son públicas. Solo si ya hay alguna. */}\n        {activa && (seller.ratingCount ?? 0) > 0 && (\n          <View style={[s.tarjeta, { backgroundColor: colors.card, marginTop: espaciado.e24, flexDirection: 'row', alignItems: 'center', gap: espaciado.e8 }]}>\n            <Star size={icono.sm} color={colors.warning} />\n            <Text style={s.nota}>\n              {(seller.ratingAvg ?? 0).toFixed(1)} de 5 · {seller.ratingCount} {seller.ratingCount === 1 ? 'valoración' : 'valoraciones'}\n            </Text>\n          </View>\n        )}\n      </ScrollView>\n    </View>\n  );\n}\n\n/** Acceso rápido: icono + etiqueta, en rejilla de dos por fila. */\nfunction Acceso({ Icono, label, ruta, onIr }: {\n  Icono: typeof Store; label: string; ruta: string; onIr: (ruta: string) => void;\n}) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={() => onIr(ruta)}\n      accessibilityRole=\"button\"\n      accessibilityLabel={label}\n      style={({ pressed }) => [{\n        width: '48%', flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n        backgroundColor: colors.card, borderColor: colors.border, borderWidth: trazo.fino,\n        borderRadius: radios.md, padding: espaciado.e12, opacity: pressed ? 0.7 : 1,\n      }]}\n    >\n      <Icono size={icono.sm} color={colors.primary} />\n      <Text style={{ fontSize: tipografia.caption, fontWeight: peso.fuerte, color: colors.textPrimary }} numberOfLines={1}>{label}</Text>\n    </Pressable>\n  );\n}\n\nconst estilos = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  raiz: { flex: 1, backgroundColor: c.background },\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino, borderBottomColor: c.border,\n  },\n  titulo: { fontSize: tipografia.title, fontWeight: peso.titulo, color: c.textPrimary },\n  subtitulo: { fontSize: tipografia.caption, color: c.textSecondary, marginTop: espaciado.e2 },\n  hueso: { height: 90, borderRadius: radios.md, opacity: 0.6 },\n  tarjeta: { borderRadius: radios.md, padding: espaciado.e12, borderWidth: trazo.fino, borderColor: c.border },\n  etiqueta: { fontSize: tipografia.micro, fontWeight: peso.fuerte, color: c.textSecondary, letterSpacing: 0.4, marginBottom: espaciado.e4 },\n  tituloBloque: { fontSize: tipografia.body, fontWeight: peso.titulo, color: c.textPrimary, marginBottom: espaciado.e8 },\n  nota: { fontSize: tipografia.micro, color: c.textSecondary, lineHeight: 16, marginTop: espaciado.e2 },\n  filaContadores: { flexDirection: 'row', gap: espaciado.e8 },\n  contador: {\n    flex: 1, alignItems: 'center', justifyContent: 'center', gap: espaciado.e4 / 2,\n    borderWidth: trazo.fino, borderRadius: radios.md, paddingVertical: espaciado.e12, paddingHorizontal: espaciado.e4,\n  },\n  cifraContador: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n  etiquetaContador: { fontSize: tipografia.micro, color: c.textSecondary, textAlign: 'center' },\n  alarma: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    borderWidth: trazo.fino, borderRadius: radios.md, padding: espaciado.e12, marginBottom: espaciado.e8,\n  },\n  textoAlarma: { flex: 1, fontSize: tipografia.caption, fontWeight: peso.medio, lineHeight: 17 },\n  filaProducto: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e8,\n    paddingVertical: espaciado.e8, borderBottomWidth: trazo.fino,\n  },\n  nombreProducto: { fontSize: tipografia.body, fontWeight: peso.fuerte, color: c.textPrimary },\n  sello: { fontSize: tipografia.micro, fontWeight: peso.titulo },\n});\n","/**\n * FilaRequisito — una casilla del mapa de onboarding del comerciante: «esto ya lo tienes / esto te\n * falta», y cuando falta, es además el botón que lo resuelve.\n *\n * VENÍA DE `ecomerse-seller.tsx` (donde era la función local `ReqRow`) y estaba ENTERRADA en medio\n * del formulario de publicación: el vendedor tenía que bajar por los campos de un anuncio para\n * enterarse de que le faltaba el KYC. El 20-sep-2026, al partir aquella pantalla de 1.110 líneas en\n * la zona del comerciante, el sitio natural de esta fila es la **portada** (`/tienda`): es\n * literalmente «lo que te falta por hacer», que es lo que el plan quiere que vea al abrir.\n *\n * Dos decisiones que no son de estilo:\n *  · El estado va en el ICONO y en el color, no solo en el texto: una casilla sin marcar tiene que\n *    verse de un golpe.\n *  · Si hay algo que hacer, la fila es un botón (`accessibilityRole=\"button\"`). Si no lo hay, no se\n *    deja un botón muerto: se quita el rol y el `onPress`.\n */\n\nimport React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { BadgeCheck, CircleDashed } from 'lucide-react-native';\nimport { espaciado, icono, peso, tipografia, useTheme } from '@egrouteplan/ui-kit';\n\nexport interface FilaRequisitoProps {\n  /** Cumplido (`true`) o pendiente (`false`). */\n  ok: boolean;\n  label: string;\n  /** Qué falta, o dónde se arregla. Se pinta bajo la etiqueta. */\n  hint?: string;\n  /** Si se pasa, la fila entera es un botón. */\n  onPress?: () => void;\n}\n\nexport function FilaRequisito({ ok, label, hint, onPress }: FilaRequisitoProps) {\n  const { colors } = useTheme();\n  return (\n    <Pressable\n      onPress={onPress}\n      disabled={!onPress}\n      accessibilityRole={onPress ? 'button' : undefined}\n      accessibilityLabel={onPress ? `${label}. ${hint ?? 'Pendiente, toca para resolverlo'}` : `${label}. ${ok ? 'Listo' : 'Pendiente'}`}\n      style={styles.fila}\n    >\n      {ok\n        ? <BadgeCheck size={icono.sm} color={colors.success} />\n        : <CircleDashed size={icono.sm} color={colors.textSecondary} />}\n      <View style={styles.textos}>\n        <Text style={[styles.label, { color: ok ? colors.textPrimary : colors.textSecondary }]}>{label}</Text>\n        {hint ? (\n          <Text style={[styles.hint, { color: onPress ? colors.primary : colors.textSecondary }]}>\n            {hint}{onPress ? ' ›' : ''}\n          </Text>\n        ) : null}\n      </View>\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  fila: { flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e4 },\n  textos: { flex: 1, marginLeft: espaciado.e8 },\n  label: { fontSize: tipografia.caption, fontWeight: peso.medio },\n  hint: { fontSize: tipografia.micro, fontWeight: peso.fuerte },\n});\n","/**\n * Pedidos — la pestaña de ventas de la zona del comerciante.\n *\n * NO es una pantalla nueva: es el carril de VENDEDOR de `ecomerse-orders`, que ya estaba construido\n * y probado (actividad y envío embebidos, timeline, disputa dentro de ventana, cobro al entregar).\n * Aquel motor existía entero… detrás de un enlace de texto de 12 px en la cabecera de la pantalla\n * vieja de tienda: estaba construido y no tenía puerta. Este fichero es la puerta.\n *\n * Lo que hace aquí y no allí: fija el rol (no se pregunta en qué papel estás dentro de tu tienda) y\n * oculta el segmento Compras/Ventas. Se pasa por props y no por URL para que la pantalla pueda vivir\n * DENTRO de la zona: con una redirección a `/ecomerse-orders` el comerciante saldría de su barra.\n */\n\nimport React from 'react';\nimport EcomerseOrdersScreen from '../ecomerse-orders';\n\nexport default function TiendaPedidos() {\n  return <EcomerseOrdersScreen rolInicial=\"seller\" ocultarSegmento />;\n}\n","/**\n * Tienda — la pestaña de identidad del comerciante: quién es su negocio y en qué estado está.\n *\n * POR QUÉ ES UNA PESTAÑA Y NO UN FORMULARIO ESCONDIDO\n * Hasta el 20-sep-2026 los datos del negocio vivían dentro del formulario de publicación, en medio de\n * los campos del anuncio: para enterarse de que le faltaba el KYC o de que su tienda estaba en\n * revisión, el vendedor tenía que bajar por el título, el precio y las fotos. Los datos del negocio\n * son **identidad**, no un paso de publicación, y por eso tienen pestaña propia.\n *\n * LAS DOS COSAS QUE PASAN AQUÍ\n *  1. **Alta o actualización del negocio** (`upsertSeller`). Exige KYC aprobado: el botón se explica\n *     cuando falta, en vez de fallar al pulsar.\n *  2. **Estado de la solicitud**: activa, en revisión o rechazada con su motivo. Sin esto, «¿por qué\n *     no me aparece nada en el Mercado?» no tiene respuesta en la app.\n *\n * ⚠ TRAMPA DEL SERVIDOR QUE ESTA PANTALLA ESQUIVA\n * `upsertSeller` escribe la rama del negocio con `d.familyId ?? null`: **si no se envía, se borra la\n * que hubiera**. Por eso la pantalla guarda lo que devuelve `sellerMe()` y lo **reenvía tal cual**\n * aunque el vendedor no toque el selector.\n *\n * Y DESDE EL 21-SEP-2026 EL SELECTOR ESTÁ ABIERTO. Hasta hoy esta pantalla reenviaba la categoría sin\n * dejar cambiarla, y decía por qué: «no se deja elegir categoría todavía porque el conjunto de\n * categorías de tienda no está confirmado; inventarlo sería peor que no ofrecerlo». Ya está\n * confirmado —el árbol de tres niveles, con 18 departamentos y 110 familias—, así que el comerciante\n * elige departamento y familia. DOS niveles y no tres: la tienda describe de qué va el negocio, no\n * publica un artículo suelto, así que la hoja no le corresponde.\n */\n\nimport React, { useCallback, useEffect, useState } from 'react';\nimport { Pressable, RefreshControl, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useFocusEffect, useRouter } from 'expo-router';\nimport {\n  AlertTriangle, ChevronRight, FileText, PackagePlus, Store, TrendingUp,\n} from 'lucide-react-native';\nimport {\n  Aviso, FormField, GhostButton, InlineError, PrimaryButton, Sheet, alpha, brand, espaciado, icono,\n  peso, radios, tipografia, trazo, useAviso, useTheme,\n} from '@egrouteplan/ui-kit';\nimport { ecomerseApi, type EcomerseCategory, type EcomerseSellerMe, type EcomerseShopPlan } from '../../api/ecomerse';\nimport { FilaRequisito } from '../../components/ecomerse/FilaRequisito';\nimport { BARRA_TIENDA_H } from '../../components/ecomerse/BarraTienda';\nimport { CITIES } from '../../constants/data';\n\n/** El estado de la tienda, dicho como se lo diría un humano al comerciante. */\nconst ESTADO_TIENDA: Record<string, { label: string; tono: 'bien' | 'aviso' | 'peligro' | 'neutro' }> = {\n  active: { label: 'Aprobada y visible en el Mercado', tono: 'bien' },\n  pending: { label: 'En revisión del administrador', tono: 'aviso' },\n  rejected: { label: 'Rechazada', tono: 'peligro' },\n  suspended: { label: 'Suspendida', tono: 'peligro' },\n};\n\nexport default function TiendaPerfil() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  const [aviso, mostrarAviso, ocultarAviso] = useAviso();\n\n  const [me, setMe] = useState<EcomerseSellerMe | null>(null);\n  const [plan, setPlan] = useState<EcomerseShopPlan | null>(null);\n  const [cargando, setCargando] = useState(true);\n  const [refrescando, setRefrescando] = useState(false);\n  const [guardando, setGuardando] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [hojaCiudad, setHojaCiudad] = useState(false);\n\n  /* Formulario. Se rellena con lo que ya hay; sin tienda, arranca vacío. */\n  const [nombre, setNombre] = useState('');\n  const [ciudad, setCiudad] = useState('');\n  const [telefono, setTelefono] = useState('');\n  const [descripcion, setDescripcion] = useState('');\n  /** Ver la TRAMPA de arriba: este valor se reenvía sin tocarlo o el servidor lo pone a NULL. */\n  const [categoriaId, setCategoriaId] = useState<string | null>(null);\n  /* EL ÁRBOL DE LA TIENDA: departamento y familia. Dos niveles y NO tres: una tienda no publica un\n     artículo suelto, elige de qué va el negocio, así que la hoja no le corresponde. */\n  const [cats, setCats] = useState<EcomerseCategory[]>([]);\n  const [departamentoId, setDepartamentoId] = useState<string | null>(null);\n  const [familiaId, setFamiliaId] = useState<string | null>(null);\n\n  const cargar = useCallback(async (esRefresco = false) => {\n    if (esRefresco) setRefrescando(true); else setCargando(true);\n    setError(null);\n    try {\n      const m = await ecomerseApi.sellerMe();\n      setMe(m);\n      if (m.seller) {\n        setNombre(m.seller.businessName ?? '');\n        setCiudad(m.seller.city ?? '');\n        setTelefono(m.seller.phoneContact ?? '');\n        setDescripcion(m.seller.description ?? '');\n        setCategoriaId(m.seller.categoryId ?? null);\n        setDepartamentoId(m.seller.departmentId ?? null);\n        setFamiliaId(m.seller.familyId ?? null);\n        /* El plan solo tiene sentido con tienda; si falla, no se tumba la pantalla entera: los datos\n           del negocio son lo importante de esta pestaña. */\n        try { setPlan(await ecomerseApi.shopPlan()); } catch { setPlan(null); }\n      } else {\n        setPlan(null);\n      }\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar los datos de tu tienda.');\n    } finally {\n      setCargando(false); setRefrescando(false);\n    }\n  }, []);\n\n  useFocusEffect(useCallback(() => { void cargar(); }, [cargar]));\n\n  /* El árbol de categorías se pide UNA vez y aparte de `sellerMe`: son unas 630 filas y no cambia\n     porque se refresque la pantalla. Si la llamada falla, la pestaña sigue entera —se puede\n     actualizar el negocio sin el selector— y el vendedor no pierde lo que ya tenía; por eso el\n     `catch` vacío y no un error en pantalla. */\n  useEffect(() => {\n    let vivo = true;\n    ecomerseApi.categories()\n      .then((c) => { if (vivo) setCats(c); })\n      .catch(() => undefined);\n    return () => { vivo = false; };\n  }, []);\n\n  const guardar = useCallback(async () => {\n    if (!nombre.trim() || !ciudad.trim()) {\n      mostrarAviso('El nombre del negocio y la ciudad son obligatorios', 'aviso');\n      return;\n    }\n    setGuardando(true);\n    try {\n      const r = await ecomerseApi.upsertSeller({\n        businessName: nombre.trim(),\n        city: ciudad.trim(),\n        description: descripcion.trim() || null,\n        phoneContact: telefono.trim() || null,\n        /* EL ÁRBOL DEL NEGOCIO. Se mandan departamento y familia. `categoryId` viaja además con el\n           valor de la familia para que una versión anterior de la app —que solo conoce ese nombre—\n           pueda seguir editando el negocio sin borrarle la rama: el servidor escribe `family_id` y,\n           si no llega, cae a `categoryId`. Es el mismo campo por dos nombres, no dos verdades. */\n        departmentId: departamentoId,\n        familyId: familiaId,\n        categoryId: familiaId ?? categoriaId,\n      });\n      mostrarAviso(r.message, r.status === 'active' ? 'exito' : 'neutro');\n      await cargar(true);\n    } catch (e) {\n      mostrarAviso(e instanceof Error ? e.message : 'No se pudieron guardar los datos', 'aviso');\n    } finally {\n      setGuardando(false);\n    }\n  }, [nombre, ciudad, descripcion, telefono, categoriaId, departamentoId, familiaId, cargar, mostrarAviso]);\n\n  const s = estilos(colors);\n  const seller = me?.seller;\n  const estado = seller ? (ESTADO_TIENDA[seller.status] ?? { label: seller.status, tono: 'neutro' as const }) : null;\n  const tonoEstado = estado\n    ? (estado.tono === 'bien' ? colors.success\n      : estado.tono === 'aviso' ? colors.warning\n        : estado.tono === 'peligro' ? colors.danger\n          : colors.textSecondary)\n    : colors.textSecondary;\n  const activa = seller?.status === 'active';\n\n  if (cargando) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        <View style={s.cabecera}><Text style={s.titulo}>Mi tienda</Text></View>\n        <View style={{ padding: espaciado.e16, gap: espaciado.e12 }}>\n          {[0, 1, 2].map((i) => <View key={i} style={[s.hueso, { backgroundColor: colors.border }]} />)}\n        </View>\n      </View>\n    );\n  }\n\n  if (error) {\n    return (\n      <View style={[s.raiz, { paddingTop: insets.top }]}>\n        <View style={s.cabecera}><Text style={s.titulo}>Mi tienda</Text></View>\n        <View style={{ padding: espaciado.e16 }}>\n          <InlineError mensaje={error} onReintentar={() => cargar()} />\n        </View>\n      </View>\n    );\n  }\n\n  return (\n    <View style={[s.raiz, { paddingTop: insets.top }]}>\n      <View style={s.cabecera}>\n        <View style={{ flex: 1 }}>\n          <Text style={s.titulo}>Mi tienda</Text>\n          <Text style={s.subtitulo} numberOfLines={1}>\n            {seller ? `${seller.businessName} · ${seller.city}` : 'Aún sin tienda'}\n          </Text>\n        </View>\n      </View>\n\n      <ScrollView\n        contentContainerStyle={{ padding: espaciado.e16, paddingBottom: BARRA_TIENDA_H + insets.bottom + espaciado.e24 }}\n        showsVerticalScrollIndicator={false}\n        keyboardShouldPersistTaps=\"handled\"\n        refreshControl={<RefreshControl refreshing={refrescando} onRefresh={() => cargar(true)} />}\n      >\n        {/* ── Estado de la solicitud: la respuesta a «¿por qué no vendo nada?» ─────────────────── */}\n        {seller && estado && (\n          <View style={[s.tarjeta, { borderColor: alpha(tonoEstado, 0.35), backgroundColor: alpha(tonoEstado, 0.07), marginBottom: espaciado.e16 }]}>\n            <Text style={[s.etiqueta, { color: tonoEstado }]}>ESTADO DE TU TIENDA</Text>\n            <Text style={s.tituloBloque}>{estado.label}</Text>\n            {seller.status === 'pending' && (\n              <Text style={s.nota}>Suele tardar 24–48 h. Tus anuncios se publican cuando esté aprobada.</Text>\n            )}\n            {seller.status === 'rejected' && seller.rejectionReason ? (\n              <Text style={[s.nota, { color: colors.danger }]}>Motivo: {seller.rejectionReason}</Text>\n            ) : null}\n          </View>\n        )}\n\n        {/* ── Requisitos: el mismo mapa de la portada, aquí en su sitio natural ───────────────── */}\n        <View style={[s.tarjeta, { backgroundColor: alpha(colors.primary, 0.06), marginBottom: espaciado.e16 }]}>\n          <Text style={s.etiqueta}>{activa ? 'REQUISITOS CUMPLIDOS' : 'PARA VENDER NECESITAS'}</Text>\n          <FilaRequisito\n            ok={!!me?.kycOk}\n            label=\"Identidad verificada (KYC)\"\n            hint={me?.kycOk ? undefined : (me?.kycMessage ?? 'Toca para verificar')}\n            onPress={me?.kycOk ? undefined : () => router.push('/driver-onboarding' as never)}\n          />\n          <FilaRequisito\n            ok={!!seller?.businessName && !!seller?.city}\n            label=\"Datos del negocio (nombre + ciudad)\"\n            hint={seller ? undefined : 'Se rellenan aquí abajo'}\n          />\n          <FilaRequisito\n            ok={activa}\n            label=\"Aprobación del administrador\"\n            hint={seller ? (activa ? undefined : 'Suele tardar 24–48 h') : 'Sin solicitud'}\n          />\n        </View>\n\n        {/* ── Datos del negocio ──────────────────────────────────────────────────────────────── */}\n        <Text style={s.tituloBloque}>{seller ? 'Datos del negocio' : 'Alta de vendedor'}</Text>\n        <Text style={s.nota}>\n          El nombre y la ciudad se ven en cada anuncio y en la página de tu tienda. Cámbialos aquí y se\n          actualizan en el Mercado.\n        </Text>\n\n        <View style={{ marginTop: espaciado.e12, gap: espaciado.e12 }}>\n          <FormField value={nombre} onChangeText={setNombre} placeholder=\"Nombre del negocio *\" />\n          <Pressable\n            onPress={() => setHojaCiudad(true)}\n            accessibilityRole=\"button\"\n            accessibilityLabel={ciudad ? `Ciudad: ${ciudad}. Toca para cambiarla` : 'Elegir ciudad'}\n            style={({ pressed }) => [s.selector, {\n              backgroundColor: colors.surface, borderColor: colors.border, opacity: pressed ? 0.7 : 1,\n            }]}\n          >\n            <Text style={[s.textoSelector, { color: ciudad ? colors.textPrimary : colors.textSecondary }]}>\n              {ciudad ? `📍 ${ciudad}` : 'Ciudad * (elige)'}\n            </Text>\n            <Text style={s.nota}>▾</Text>\n          </Pressable>\n          <FormField value={telefono} onChangeText={setTelefono} placeholder=\"Teléfono / WhatsApp (+240…)\" keyboardType=\"phone-pad\" />\n          <TextInput\n            multiline\n            value={descripcion}\n            onChangeText={setDescripcion}\n            placeholder=\"Describe tu negocio…\"\n            placeholderTextColor={colors.textSecondary}\n            style={[s.area, { backgroundColor: colors.surface, borderColor: colors.border, color: colors.textPrimary }]}\n          />\n          {/* LA RAMA DEL NEGOCIO. Dos escalones, no tres. Antes esta pantalla REENVIABA la categoría\n              que hubiera sin dejar cambiarla, y estaba anotado aquí arriba por qué: «no se deja\n              elegir categoría todavía porque el conjunto de categorías de tienda no está\n              confirmado». Ya lo está —18 departamentos · 110 familias—, así que se elige.\n              El selector solo aparece si el árbol llegó: sin él, el negocio se sigue pudiendo\n              actualizar y no se le borra la rama que ya tuviera. */}\n          {cats.length > 0 ? (\n            <View>\n              <Text style={{ fontSize: tipografia.caption, fontWeight: peso.titulo, color: colors.textPrimary, marginBottom: espaciado.e6 }}>¿De qué va tu negocio? *</Text>\n              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8 }}>\n                {cats.map((c) => (\n                  <Pressable\n                    key={c.id}\n                    onPress={() => { setDepartamentoId(departamentoId === c.id ? null : c.id); setFamiliaId(null); }}\n                    accessibilityRole=\"button\"\n                    accessibilityLabel={c.label}\n                    style={{\n                      paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderRadius: radios.lg,\n                      backgroundColor: departamentoId === c.id ? colors.primary : colors.surface,\n                      borderWidth: trazo.fino, borderColor: departamentoId === c.id ? colors.primary : colors.border,\n                      flexDirection: 'row', alignItems: 'center', gap: espaciado.e4,\n                    }}\n                  >\n                    <Text style={{ fontSize: tipografia.body }}>{c.icon ?? ''}</Text>\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: peso.fuerte, color: departamentoId === c.id ? brand.white : colors.textPrimary }}>{c.label}</Text>\n                  </Pressable>\n                ))}\n              </ScrollView>\n              {departamentoId && (() => {\n                const dep = cats.find((c) => c.id === departamentoId);\n                if (!dep || !dep.familias?.length) return null;\n                return (\n                  <>\n                    <Text style={{ fontSize: tipografia.caption, fontWeight: peso.titulo, color: colors.textPrimary, marginTop: espaciado.e10, marginBottom: espaciado.e6 }}>Y en concreto *</Text>\n                    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: espaciado.e8 }}>\n                      {dep.familias.map((f) => (\n                        <Pressable\n                          key={f.id}\n                          onPress={() => setFamiliaId(familiaId === f.id ? null : f.id)}\n                          accessibilityRole=\"button\"\n                          accessibilityLabel={f.label}\n                          style={{\n                            paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e7, borderRadius: radios.lg,\n                            backgroundColor: familiaId === f.id ? colors.primary : colors.surface,\n                            borderWidth: trazo.fino, borderColor: familiaId === f.id ? colors.primary : colors.border,\n                          }}\n                        >\n                          <Text style={{ fontSize: tipografia.caption, fontWeight: peso.fuerte, color: familiaId === f.id ? brand.white : colors.textPrimary }}>{f.label}</Text>\n                        </Pressable>\n                      ))}\n                    </ScrollView>\n                  </>\n                );\n              })()}\n            </View>\n          ) : seller?.categoryLabel ? (\n            <Text style={s.nota}>Rama del negocio: {seller.categoryLabel}</Text>\n          ) : null}\n          <PrimaryButton\n            title={guardando ? 'Guardando…' : (seller ? 'Actualizar negocio' : 'Solicitar alta como vendedor')}\n            onPress={() => void guardar()}\n            disabled={guardando || !me?.kycOk}\n          />\n          {!me?.kycOk && (\n            <Text style={s.nota}>\n              Verifica tu identidad (KYC) para poder dar de alta el negocio. Es el primer paso y solo se hace una vez.\n            </Text>\n          )}\n        </View>\n\n        {/* ── Plan: el techo de anuncios, dicho antes de chocar con él ───────────────────────── */}\n        {activa && plan && (\n          <View style={{ marginTop: espaciado.e24 }}>\n            <Text style={s.tituloBloque}>Tu plan</Text>\n            <Pressable\n              onPress={() => router.push('/ecomerse-planes' as never)}\n              accessibilityRole=\"button\"\n              accessibilityLabel={`${plan.name}: ${plan.used} de ${plan.limit} anuncios usados. Ver planes.`}\n              style={({ pressed }) => [s.acceso, {\n                backgroundColor: colors.card, borderColor: colors.border, opacity: pressed ? 0.7 : 1,\n              }]}\n            >\n              <TrendingUp size={icono.sm} color={colors.primary} />\n              <View style={{ flex: 1 }}>\n                <Text style={s.textoAcceso}>{plan.name}</Text>\n                <Text style={s.nota}>\n                  {plan.used} de {plan.limit} anuncios{plan.expiresAt ? ` · activo hasta ${plan.expiresAt.slice(0, 10)}` : ''}\n                </Text>\n              </View>\n              <ChevronRight size={icono.sm} color={colors.textSecondary} />\n            </Pressable>\n          </View>\n        )}\n\n        {/* ── Accesos ───────────────────────────────────────────────────────────────────────── */}\n        <View style={{ marginTop: espaciado.e24, gap: espaciado.e8 }}>\n          <Text style={s.tituloBloque}>Accesos</Text>\n          <Atajo Icono={PackagePlus} label=\"Publicar un anuncio\" detalle=\"Sube fotos, precio y categoría\" onPress={() => router.push('/tienda/publicar' as never)} colors={colors} />\n          {seller && (\n            <Atajo Icono={Store} label=\"Ver mi tienda como la ve un cliente\" detalle=\"Página pública con tus anuncios\" onPress={() => router.push(`/ecomerse-tienda?id=${seller.id}` as never)} colors={colors} />\n          )}\n          <Atajo Icono={FileText} label=\"Documentos de mis anuncios\" detalle=\"Facturas y certificados en revisión\" onPress={() => router.push('/ecomerse-docs' as never)} colors={colors} />\n        </View>\n\n        {/* La garantía es de la plataforma, no del vendedor: se dice para que nadie prometa lo que no\n            le toca. Es el mismo aviso que la ficha y el checkout. */}\n        {activa && (\n          <Text style={[s.nota, { marginTop: espaciado.e24 }]}>\n            Los {me?.warrantyDays ?? 7} días de garantía los ofrece EG Route Plan, no tú: el comprador los\n            tiene en cualquier caso. Las devoluciones de arriba son tu oferta aparte.\n          </Text>\n        )}\n\n        {seller?.status === 'rejected' && seller.rejectionReason ? (\n          <View style={{ marginTop: espaciado.e16, flexDirection: 'row', gap: espaciado.e8, alignItems: 'flex-start' }}>\n            <AlertTriangle size={icono.sm} color={colors.danger} />\n            <Text style={[s.nota, { flex: 1, color: colors.danger }]}>\n              Corrige los datos y vuelve a solicitar el alta: {seller.rejectionReason}\n            </Text>\n          </View>\n        ) : null}\n      </ScrollView>\n\n      <Aviso visible={aviso.visible} mensaje={aviso.mensaje} tono={aviso.tono} onOcultar={ocultarAviso} />\n\n      {/* Selector de ciudad en hoja: la lista es larga (varias provincias) y no cabe en línea. */}\n      <Sheet visible={hojaCiudad} title=\"Ciudad del negocio\" position=\"bottom\" onClose={() => setHojaCiudad(false)}>\n        <ScrollView style={{ maxHeight: 380 }} showsVerticalScrollIndicator={false}>\n          {CITIES.map((c) => {\n            const on = c.name === ciudad;\n            return (\n              <Pressable\n                key={c.id}\n                onPress={() => { setCiudad(c.name); setHojaCiudad(false); }}\n                accessibilityRole=\"button\"\n                accessibilityState={{ selected: on }}\n                accessibilityLabel={`${c.name}, ${c.region}`}\n                style={({ pressed }) => [s.filaCiudad, { borderBottomColor: colors.border, opacity: pressed ? 0.6 : 1 }]}\n              >\n                <View style={{ flex: 1 }}>\n                  <Text style={[s.textoSelector, { color: colors.textPrimary }]}>{c.name}</Text>\n                  <Text style={s.nota}>{c.region}</Text>\n                </View>\n                {on && <Text style={[s.marca, { color: colors.primary }]}>✓</Text>}\n              </Pressable>\n            );\n          })}\n        </ScrollView>\n        <View style={{ marginTop: espaciado.e8 }}>\n          <GhostButton title=\"Cerrar\" onPress={() => setHojaCiudad(false)} />\n        </View>\n      </Sheet>\n    </View>\n  );\n}\n\n/** Un acceso con título y detalle. La descripción evita el icono sin leyenda. */\nfunction Atajo({ Icono, label, detalle, onPress, colors }: {\n  Icono: typeof Store; label: string; detalle: string; onPress: () => void;\n  colors: ReturnType<typeof useTheme>['colors'];\n}) {\n  return (\n    <Pressable\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`${label}. ${detalle}`}\n      style={({ pressed }) => [{\n        flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n        backgroundColor: colors.card, borderColor: colors.border, borderWidth: trazo.fino,\n        borderRadius: radios.md, padding: espaciado.e12, opacity: pressed ? 0.7 : 1,\n      }]}\n    >\n      <Icono size={icono.sm} color={colors.primary} />\n      <View style={{ flex: 1 }}>\n        <Text style={{ fontSize: tipografia.caption, fontWeight: peso.fuerte, color: colors.textPrimary }} numberOfLines={1}>{label}</Text>\n        <Text style={{ fontSize: tipografia.micro, color: colors.textSecondary }} numberOfLines={1}>{detalle}</Text>\n      </View>\n      <ChevronRight size={icono.sm} color={colors.textSecondary} />\n    </Pressable>\n  );\n}\n\nconst estilos = (c: ReturnType<typeof useTheme>['colors']) => StyleSheet.create({\n  raiz: { flex: 1, backgroundColor: c.background },\n  cabecera: {\n    flexDirection: 'row', alignItems: 'center',\n    paddingHorizontal: espaciado.e16, paddingVertical: espaciado.e12,\n    borderBottomWidth: trazo.fino, borderBottomColor: c.border,\n  },\n  titulo: { fontSize: tipografia.title, fontWeight: peso.titulo, color: c.textPrimary },\n  subtitulo: { fontSize: tipografia.caption, color: c.textSecondary, marginTop: espaciado.e2 },\n  hueso: { height: 84, borderRadius: radios.md, opacity: 0.6 },\n  tarjeta: { borderRadius: radios.md, padding: espaciado.e12, borderWidth: trazo.fino, borderColor: c.border },\n  etiqueta: { fontSize: tipografia.micro, fontWeight: peso.fuerte, color: c.textSecondary, letterSpacing: 0.4, marginBottom: espaciado.e4 },\n  tituloBloque: { fontSize: tipografia.body, fontWeight: peso.titulo, color: c.textPrimary, marginBottom: espaciado.e8 },\n  nota: { fontSize: tipografia.micro, color: c.textSecondary, lineHeight: 16, marginTop: espaciado.e2 },\n  selector: {\n    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',\n    borderRadius: radios.md, borderWidth: trazo.fino, paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e12,\n  },\n  textoSelector: { fontSize: tipografia.body, fontWeight: peso.medio },\n  area: {\n    minHeight: 92, borderRadius: radios.md, borderWidth: trazo.fino,\n    paddingHorizontal: espaciado.e12, paddingVertical: espaciado.e12, fontSize: tipografia.body, textAlignVertical: 'top',\n  },\n  acceso: {\n    flexDirection: 'row', alignItems: 'center', gap: espaciado.e12,\n    borderWidth: trazo.fino, borderRadius: radios.md, padding: espaciado.e12,\n  },\n  textoAcceso: { fontSize: tipografia.caption, fontWeight: peso.fuerte, color: c.textPrimary },\n  filaCiudad: { flexDirection: 'row', alignItems: 'center', paddingVertical: espaciado.e12, borderBottomWidth: trazo.fino },\n  marca: { fontSize: tipografia.subtitle, fontWeight: peso.titulo },\n});\n","/**\n * Publicar — el formulario de alta y corrección de un anuncio, DENTRO de la zona del comerciante.\n *\n * Es el mismo formulario de seis secciones que ya estaba probado (v3 de la auditoría completa:\n * fotos como archivo multipart, cupo de plan, KYC, teléfono de GQ validado, subcategoría y foto\n * obligatorias, vista previa del precio, documentación, plazo y devoluciones). Lo que cambia el\n * 20-sep-2026 es DÓNDE vive y QUÉ YA NO HACE:\n *\n *  · Antes era la pantalla entera de «Mi tienda» (`/ecomerse-seller`, 1.110 líneas): requisitos +\n *    datos del negocio + formulario + lista de productos + banner de plan, todo en una.\n *  · Ahora es **una pantalla de la zona**, fuera de la barra (es un flujo de captura, no una\n *    pestaña). Los datos del negocio y el KYC viven en «Tienda», la lista de anuncios en «Anuncios»,\n *    y el plan también en «Tienda». Aquí solo se publica o se corrige.\n *\n * Entradas: desde «Anuncios» con el FAB, o con `?id=` para corregir un anuncio rechazado\n * (el backend solo admite editar en `draft` o `rejected`: `ecomerse.service.ts:425-426`).\n *\n * NOTA DE NUMERACIÓN: el formulario se llamaba «de seis secciones» contando la 1 como los datos del\n * vendedor. Esa sección ya no está aquí, así que las visibles se renumeran 1→5\n * (1 Producto · 2 Fotos · 3 Documentación · 4 Entrega · 5 Condiciones). Los comentarios `Sección N`\n * del fichero siguen la numeración nueva.\n * Ruta: /tienda/publicar\n */\n\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { Alert, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { Image } from 'expo-image';\nimport * as ImagePicker from 'expo-image-picker';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { ArrowLeft, Camera, X } from 'lucide-react-native';\nimport { alpha, brand, espaciado, FormField, GhostButton, ilustracion, peso, Precio, PrimaryButton, radios, Sheet, tipografia, trazo, useTheme } from '@egrouteplan/ui-kit';\nimport { ecomerseApi, EcomerseCategory, EcomerseProduct, EcomerseSellerMe, EcomerseShopPlan } from '../../api/ecomerse';\nimport { formatXAF } from '../../utils/formatHelpers';\nimport { CITIES } from '../../constants/data';\n\nconst STATUS_LABEL: Record<string, string> = {\n  pending: 'En revisión', active: 'Activo', rejected: 'Rechazado',\n  suspended: 'Suspendida', banned: 'Bloqueada', paused: 'Pausada', draft: 'Borrador', sold_out: 'Agotado',\n};\nconst MAX_PHOTO_MB = 8;\n\n/** Precio con formato local (\"12.500\", \"12 500\", \"12500\") → entero XAF. */\nfunction parsePrice(s: string): number | null {\n  const clean = s.replace(/[^\\d]/g, '');\n  if (!clean) return null;\n  const n = Number(clean);\n  return Number.isFinite(n) && n > 0 && n <= 100_000_000 ? n : null;\n}\n\n/**\n * ESTADO DEL ARTÍCULO — vocabulario fijo, no texto libre.\n *\n * Por qué una lista cerrada: si cada vendedor escribe «usado», «poco uso» o «buen estado», el\n * comprador no puede comparar dos anuncios ni filtrar, y la ficha no puede tener un dato fiable.\n * Cuatro opciones cubren el mercado de segunda mano sin ambigüedad, y `estado` viaja en\n * `attributes` (el backend ya lo acepta: `ecomerse.dto.ts:32`).\n */\nconst ESTADOS = ['Nuevo', 'Como nuevo', 'Buen estado', 'Para piezas'] as const;\ntype EstadoArticulo = (typeof ESTADOS)[number];\n\n/** Mínimo de fotos por anuncio (antes 1). El tope del formulario sigue siendo 6. */\nconst MIN_FOTOS = 3;\n\n/**\n * PLAZO DE PREPARACIÓN (tanda 4 · sección 4). Cuánto tarda el vendedor en entregar el pedido.\n * Es un dato que el comprador necesita para saber cuándo esperar, y que hoy no existía.\n */\nconst PLAZOS = [\n  { horas: 24, label: 'En 24 h' },\n  { horas: 48, label: 'En 48 h' },\n  { horas: 72, label: 'En 72 h' },\n] as const;\n\n/**\n * DOCUMENTACIÓN (tanda 4 · sección 3). Los tres tipos que admite el CHECK de la tabla\n * `wallet.ecomerse_product_docs` — tiene que coincidir con él, o el insert daría un 23514.\n * La factura es la única que tiene sentido comprobar contra el anuncio (importe y fecha);\n * por eso solo esa los pide.\n */\nconst DOCS = [\n  { id: 'factura_compra', label: 'Factura de compra', pideDatos: true },\n  { id: 'certificado_autenticidad', label: 'Certificado de autenticidad', pideDatos: false },\n  { id: 'autorizacion_marca', label: 'Autorización de marca', pideDatos: false },\n] as const;\ntype DocTipo = (typeof DOCS)[number]['id'];\n\n/**\n * FORMAS DE ENTREGA que el vendedor acepta. La logística del Mercado ya existe y se elige en el\n * CHECKOUT (entrega directa del vendedor sin coste, o agente de la plataforma con tarifa por zona\n * — `ecomerse_delivery_zones`: 300 XAF + 50/km en zona céntrica), pero **el vendedor no opinaba**:\n * un anuncio podía acabar en un reparto que quien vende no ofrece. Ahora lo declara al publicar y\n * se guarda en `attributes.entrega`, que es `jsonb`: no hace falta tocar el esquema.\n */\nconst ENTREGAS = [\n  { id: 'seller', label: 'Entrego yo', hint: 'Quedas con el comprador. Sin coste de envío.' },\n  { id: 'agent', label: 'Con agente', hint: 'Un agente de la plataforma recoge y entrega. El comprador paga la tarifa de su zona.' },\n  { id: 'both', label: 'Las dos', hint: 'El comprador elige al pagar.' },\n] as const;\ntype FormaEntrega = (typeof ENTREGAS)[number]['id'];\n\nexport default function PublicarAnuncioScreen() {\n  const { colors } = useTheme();\n  const router = useRouter();\n  const insets = useSafeAreaInsets();\n  /** `?id=` → corregir un anuncio rechazado. Sin `id`, se publica uno nuevo. */\n  const { id: idCorregir } = useLocalSearchParams<{ id?: string }>();\n  const [me, setMe] = useState<EcomerseSellerMe | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  /** Ciudad por defecto del anuncio: la del negocio (los datos del negocio viven en «Tienda»). */\n  const [city, setCity] = useState('');\n  const [busyPub, setBusyPub] = useState(false);\n  const busyRef = useRef(false);\n  const [cityModal, setCityModal] = useState<'prod' | null>(null);\n\n  const [editId, setEditId] = useState<string | null>(null);\n  const [pTitle, setPTitle] = useState('');\n  const [pPrice, setPPrice] = useState('');\n  const [pCity, setPCity] = useState('');\n  const [pDesc, setPDesc] = useState('');\n  const [pStock, setPStock] = useState('1');\n  const [cats, setCats] = useState<EcomerseCategory[]>([]);\n  const [shopPlan, setShopPlan] = useState<EcomerseShopPlan | null>(null);\n  /* LOS TRES NIVELES, un estado cada uno. `pCatId` conserva su nombre porque la pantalla ya lo usaba\n     para «el nivel de arriba», y ese papel lo hace ahora el DEPARTAMENTO. `pFamId` es el nuevo (la\n     FAMILIA) y `pSubId` —el que ya existía— pasa a ser la HOJA, el último nivel y donde de verdad\n     vive un anuncio. Renombrar los tres costaría 40 líneas para el mismo comportamiento; se dejan\n     como están y se dice aquí qué es cada uno. */\n  const [pCatId, setPCatId] = useState('');\n  const [pFamId, setPFamId] = useState('');\n  const [pSubId, setPSubId] = useState('');\n  const [pPhotos, setPPhotos] = useState<string[]>([]);\n  /** Estado del artículo (obligatorio). Se envía como `attributes.estado`. */\n  const [pEstado, setPEstado] = useState<EstadoArticulo | ''>('');\n  /* --- Sección 1: información del producto (atributos que el comprador usa para decidir) --- */\n  const [pMarca, setPMarca] = useState('');\n  const [pModelo, setPModelo] = useState('');\n  const [pSku, setPSku] = useState('');\n  const [pTalla, setPTalla] = useState('');\n  const [pColor, setPColor] = useState('');\n  /** Acepta ofertas por debajo del precio. Antes era `is_negotiable` con `default true` y sin control:\n   *  el vendedor veía «💰 Negociable» en su anuncio sin haberlo elegido nunca. */\n  const [pNegociable, setPNegociable] = useState(true);\n  /* --- Sección 4: configuración logística --- */\n  const [pEntrega, setPEntrega] = useState<FormaEntrega | ''>('');\n  /** Plazo de preparación en horas (24/48/72). Columna `handling_hours` desde la migración 019. */\n  const [pPlazo, setPPlazo] = useState<number>(24);\n  /** Devoluciones que ofrece el VENDEDOR, distinto de la garantía de 7 días de la plataforma. */\n  const [pDevoluciones, setPDevoluciones] = useState(false);\n  /* --- Sección 3: documentación --- */\n  const [pDocTipo, setPDocTipo] = useState<DocTipo | ''>('');\n  const [pDocNumero, setPDocNumero] = useState('');\n  const [pDocImporte, setPDocImporte] = useState('');\n  const [pDocFecha, setPDocFecha] = useState('');\n  const [pDocFoto, setPDocFoto] = useState<string | null>(null);\n  /** Documentos ya guardados del anuncio que se edita (se conservan si no se tocan). */\n  const [pDocs, setPDocs] = useState<{ docType: DocTipo; url: string; docNumber?: string; amountXaf?: number; issuedOn?: string }[]>([]);\n  /* --- Sección 5: términos --- */\n  const [pAceptaTerminos, setPAceptaTerminos] = useState(false);\n  const [preview, setPreview] = useState(false);\n  const [pUploading, setPUploading] = useState(false);\n  const scrollRef = useRef<ScrollView>(null);\n\n  /** Fotos como ARCHIVO (multipart → MinIO), sin base64 en el JSON. */\n  const pickPhotos = async (source: 'camera' | 'library') => {\n    try {\n      const perm = source === 'camera'\n        ? await ImagePicker.requestCameraPermissionsAsync()\n        : await ImagePicker.requestMediaLibraryPermissionsAsync();\n      if (!perm.granted) {\n        Alert.alert('Permiso', source === 'camera' ? 'Necesitamos acceso a la cámara.' : 'Necesitamos acceso a tu galería.');\n        return;\n      }\n      const res = source === 'camera'\n        ? await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.7 })\n        : await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], allowsMultipleSelection: true, selectionLimit: 4, quality: 0.7 });\n      if (res.canceled || !res.assets?.length) return;\n      const toAdd = res.assets.slice(0, 6 - pPhotos.length);\n      setPUploading(true);\n      const urls: string[] = [];\n      for (const a of toAdd) {\n        if ((a.fileSize ?? 0) > MAX_PHOTO_MB * 1024 * 1024) continue;\n        try {\n          const form = new FormData();\n          form.append('photo', { uri: a.uri, name: `foto-${Date.now()}.jpg`, type: a.mimeType ?? 'image/jpeg' } as unknown as Blob);\n          const r = await ecomerseApi.uploadPhoto(form);\n          if (r.url) urls.push(r.url);\n        } catch { /* una foto falló; seguimos con las demás */ }\n      }\n      if (urls.length) {\n        setPPhotos((prev) => [...prev, ...urls].slice(0, 6));\n      } else if (toAdd.length) {\n        Alert.alert('Fotos', 'No se pudieron subir las fotos. Prueba con imágenes de menos de 8 MB.');\n      }\n    } catch { /* picker falló */ }\n    finally { setPUploading(false); }\n  };\n\n  const pickSource = () => {\n    Alert.alert('Añadir fotos', 'Elige el origen:', [\n      { text: 'Cámara', onPress: () => pickPhotos('camera') },\n      { text: 'Galería', onPress: () => pickPhotos('library') },\n      { text: 'Cancelar', style: 'cancel' },\n    ]);\n  };\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const m = await ecomerseApi.sellerMe();\n      setMe(m);\n      if (m.seller) setCity(m.seller.city);\n      const c = await ecomerseApi.categories();\n      setCats(c);\n      ecomerseApi.shopPlan().then(setShopPlan).catch(() => undefined);\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'No pudimos cargar tu tienda. Revisa la conexión.');\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const atQuota = !!shopPlan && shopPlan.limit > 0 && shopPlan.used >= shopPlan.limit;\n\n  /**\n   * Un solo sitio para vaciar el formulario. Antes la limpieza estaba escrita tres veces (al\n   * publicar, al cancelar la edición y en el botón de cancelar) y con nueve campos ya era fácil\n   * olvidarse de uno: ahora hay un único camino y los campos nuevos se añaden aquí.\n   */\n  const limpiarFormulario = useCallback(() => {\n    setEditId(null);\n    setPTitle(''); setPPrice(''); setPDesc(''); setPCatId(''); setPFamId(''); setPSubId('');\n    setPPhotos([]); setPStock('1'); setPEstado('');\n    setPMarca(''); setPModelo(''); setPSku(''); setPTalla(''); setPColor('');\n    setPNegociable(true); setPEntrega(''); setPAceptaTerminos(false); setPreview(false);\n    setPPlazo(24); setPDevoluciones(false);\n    setPDocTipo(''); setPDocNumero(''); setPDocImporte(''); setPDocFecha(''); setPDocFoto(null); setPDocs([]);\n  }, []);\n\n  /**\n   * Documentos que se envían al guardar: los que ya tenía el anuncio más el que se acaba de\n   * adjuntar (sustituyendo al del mismo tipo, porque la tabla tiene UNIQUE (product_id, doc_type)).\n   *\n   * Decisión de diseño: se adjunta de uno en uno y con vista previa, en vez de una lista múltiple.\n   * Con seis fotos y tres documentos en el mismo formulario, una subida múltiple silenciosa es\n   * justo donde se pierde un archivo sin que nadie se entere; aquí el vendedor ve qué va a enviar.\n   */\n  const docsParaEnviar = useMemo(() => {\n    const base = pDocs.filter((d) => d.docType !== pDocTipo || !pDocFoto);\n    if (!pDocTipo || !pDocFoto) return base;\n    const importe = Number(pDocImporte.replace(/[^\\d]/g, ''));\n    return [...base, {\n      docType: pDocTipo,\n      url: pDocFoto,\n      ...(pDocNumero.trim() ? { docNumber: pDocNumero.trim() } : {}),\n      ...(Number.isFinite(importe) && importe > 0 ? { amountXaf: importe } : {}),\n      ...(/^\\d{4}-\\d{2}-\\d{2}$/.test(pDocFecha.trim()) ? { issuedOn: pDocFecha.trim() } : {}),\n    }];\n  }, [pDocs, pDocTipo, pDocFoto, pDocNumero, pDocImporte, pDocFecha]);\n\n  /** Adjunta el documento: se guarda en memoria y se envía al publicar (el anuncio aún no existe si es nuevo). */\n  const adjuntarDoc = async (origen: 'camera' | 'library') => {\n    if (!pDocTipo) { Alert.alert('Tipo de documento', 'Elige primero qué documento vas a adjuntar.'); return; }\n    try {\n      const perm = origen === 'camera'\n        ? await ImagePicker.requestCameraPermissionsAsync()\n        : await ImagePicker.requestMediaLibraryPermissionsAsync();\n      if (!perm.granted) { Alert.alert('Permiso', 'Necesitamos acceso para adjuntar el documento.'); return; }\n      const res = origen === 'camera'\n        ? await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.7 })\n        : await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7 });\n      if (res.canceled || !res.assets?.length) return;\n      const a = res.assets[0];\n      if ((a.fileSize ?? 0) > MAX_PHOTO_MB * 1024 * 1024) {\n        Alert.alert('Documento', `La imagen pasa de ${MAX_PHOTO_MB} MB. Prueba con una foto más ligera.`);\n        return;\n      }\n      /* Se sube YA (igual que las fotos) para que el vendedor vea si falló. Si la subida falla, no\n         se guarda nada: mejor decir «no se pudo» que publicar un anuncio con un documento roto. */\n      setPUploading(true);\n      const form = new FormData();\n      form.append('photo', { uri: a.uri, name: `doc-${Date.now()}.jpg`, type: a.mimeType ?? 'image/jpeg' } as unknown as Blob);\n      const r = await ecomerseApi.uploadPhoto(form);\n      if (!r.url) { Alert.alert('Documento', 'No se pudo subir el documento. Inténtalo de nuevo.'); return; }\n      setPDocFoto(r.url);\n    } catch {\n      Alert.alert('Documento', 'No se pudo adjuntar el documento.');\n    } finally { setPUploading(false); }\n  };\n\n  /** Publica o reenvía la corrección (validación completa + cupo). */\n  const saveProduct = async () => {\n    if (busyRef.current) return;\n    if (atQuota) {\n      Alert.alert('Límite de plan', `Ya tienes ${shopPlan!.used}/${shopPlan!.limit} anuncios activos.`, [\n        { text: 'OK', style: 'cancel' },\n        { text: 'Mejorar plan', onPress: () => router.push('/ecomerse-planes' as any) },\n      ]);\n      return;\n    }\n    const price = parsePrice(pPrice);\n    if (!pTitle.trim() || price == null) {\n      Alert.alert('Faltan datos', 'Título y precio (número válido en XAF) son obligatorios.'); return;\n    }\n    /* LOS TRES ESCALONES. Un anuncio vive en una HOJA (nivel 3), así que se piden departamento y\n       familia siempre, y además la hoja cuando la familia tiene alguna. La excepción no es un\n       descuido: hay familias con 0 hojas —una rama abierta que todavía no se ha desglosado—, y\n       exigir una hoja que no existe dejaría al vendedor sin publicar y sin saber por qué. Se pide\n       lo que hay. */\n    if (!pCatId) { Alert.alert('Falta el departamento', 'Elige el departamento: es el primer bloque del Mercado.'); return; }\n    const dep = cats.find((c) => c.id === pCatId);\n    if (!pFamId) { Alert.alert('Falta la familia', `Elige una familia de «${dep?.label ?? 'el departamento'}».`); return; }\n    const fam = dep?.familias.find((f) => f.id === pFamId);\n    if (fam?.hojas.length && !pSubId) {\n      Alert.alert('Falta la hoja', `Mira dentro de «${fam.label}» y elige dónde encaja tu anuncio.`); return;\n    }\n    if (!pEstado) {\n      Alert.alert('Falta el estado', 'Dinos en qué estado está el artículo: es lo primero que mira quien compra de segunda mano.');\n      return;\n    }\n    /* Sección 1: marca y modelo son los campos que Dewu usa como identidad del producto (su\n       verificación se apoya en el modelo exacto). Aquí no hay verificación, pero sirven para lo\n       mismo que sirven en cualquier marketplace: que el comprador encuentre el artículo buscando\n       «iPhone 11» en vez de fiarse del título que cada vendedor escriba. */\n    if (!pMarca.trim()) { Alert.alert('Falta la marca', 'Escribe la marca del artículo (por ejemplo: Apple, Nike, Samsung).'); return; }\n    if (!pModelo.trim()) { Alert.alert('Falta el modelo', 'Escribe el modelo (por ejemplo: iPhone 11 64 GB). Es lo que usará quien busque.'); return; }\n    if (pPhotos.length < MIN_FOTOS) {\n      Alert.alert(\n        `Faltan fotos (${pPhotos.length}/${MIN_FOTOS})`,\n        'En un mercado de segunda mano la foto es lo único que el comprador tiene para juzgar el estado: sube al menos tres (el producto entero, algún detalle y, si hay, la marca o el desperfecto).');\n      return;\n    }\n    /* Sección 4: el vendedor tiene que decir cómo entrega. Sin esto, un anuncio podía caer en un\n       reparto que quien vende no ofrece. */\n    if (!pEntrega) {\n      Alert.alert('Falta la entrega', 'Dinos cómo entregas el producto: tú mismo, con un agente de la plataforma, o las dos.');\n      return;\n    }\n    /* Sección 5: los términos se aceptan de forma expresa. Sin esto no se publica. */\n    if (!pAceptaTerminos) {\n      Alert.alert('Faltan los términos', 'Marca la casilla de condiciones: incluye lo que cobras, cómo funciona la garantía y qué pasa si hay una reclamación.');\n      return;\n    }\n    busyRef.current = true;\n    setBusyPub(true);\n    try {\n      const body = {\n        title: pTitle.trim(), priceXaf: price, city: pCity.trim() || city,\n        description: pDesc.trim() || undefined,\n        /* El árbol con sus tres nombres. Se mandan los TRES aunque la hoja sea la única que el\n           anuncio necesita: el servidor comprueba que la hoja pertenece a esa familia y que la\n           familia pertenece a ese departamento, y con solo la hoja no tendría con qué compararla. */\n        departmentId: pCatId, familyId: pFamId, leafId: pSubId || undefined,\n        photos: pPhotos, stock: Math.max(1, Math.min(Number(pStock) || 1, 1000)),\n        isNegotiable: pNegociable,\n        /** Sección 4 · logística: plazo y devoluciones (columnas propias desde la migración 019). */\n        handlingHours: pPlazo,\n        returnsAccepted: pDevoluciones,\n        /** Sección 3 · documentación: los ya guardados más el que se acaba de adjuntar, si lo hay. */\n        docs: docsParaEnviar,\n        /**\n         * Todo lo que la ficha necesita para ser útil viaja aquí, en `attributes` (jsonb, ya existe\n         * y admite string/number/boolean: `ecomerse.dto.ts:32`). Se omiten los vacíos para no\n         * ensuciar el JSON con cadenas vacías.\n         */\n        attributes: {\n          estado: pEstado,\n          marca: pMarca.trim(),\n          modelo: pModelo.trim(),\n          ...(pSku.trim() ? { sku: pSku.trim() } : {}),\n          ...(pTalla.trim() ? { talla: pTalla.trim() } : {}),\n          ...(pColor.trim() ? { color: pColor.trim() } : {}),\n          entrega: pEntrega,\n        },\n      };\n      const r = editId\n        ? await ecomerseApi.updateProduct(editId, body)\n        : await ecomerseApi.createProduct(body);\n      /**\n       * UN ANUNCIO NUEVO NO PUEDE LLEVAR COMBINACIONES EN EL ALTA, y no es un olvido del backend: el\n       * servidor **rechaza** `options` en `POST`/`PUT products` para que nadie crea que las publicó\n       * (el contenido pasa por moderación y las combinaciones no: son dos carriles). Así que en vez de\n       * dejar al comerciante sin saberlo, se le ofrece el paso que falta justo cuando lo necesita —\n       * que es ahora, no en un menú que hay que descubrir.\n       */\n      const nuevoId = 'productId' in r ? r.productId : null;\n      if (!editId && nuevoId) {\n        Alert.alert('Producto enviado', r.message, [\n          { text: 'Añadir combinaciones', onPress: () => router.push(`/tienda/combinaciones?id=${nuevoId}` as never) },\n          { text: 'Ahora no', style: 'cancel' },\n        ]);\n      } else {\n        Alert.alert(editId ? 'Corrección enviada' : 'Producto enviado', r.message);\n      }\n      limpiarFormulario();\n      await load();\n    } catch (e) { Alert.alert('Error', e instanceof Error ? e.message : 'No se pudo guardar'); }\n    finally { busyRef.current = false; setBusyPub(false); }\n  };\n\n  const startEdit = (p: EcomerseProduct) => {\n    setEditId(p.id);\n    setPTitle(p.title);\n    setPPrice(String(p.priceXaf));\n    setPCity(p.city || city);\n    setPDesc(p.description ?? '');\n    /* Se prefieren los campos del árbol y se cae a los viejos. Un anuncio publicado antes de este\n       cambio solo trae `categoryId` / `subcategoryId`, y el servidor los sigue rellenando con la\n       familia y la hoja, así que el formulario abre con lo que el anuncio tenía en vez de en blanco. */\n    setPCatId(p.departmentId ?? '');\n    setPFamId(p.familyId ?? p.categoryId ?? '');\n    setPSubId(p.leafId ?? p.subcategoryId ?? '');\n    setPPhotos(p.photos ?? []);\n    setPStock(String(p.stock || 1));\n    // El estado viene de `attributes.estado`. Si el anuncio es antiguo y no lo tiene, se deja\n    // VACÍO a propósito: así al reenviar hay que elegirlo, en vez de inventarle uno.\n    const guardado = p.attributes?.estado;\n    setPEstado(ESTADOS.includes(guardado as EstadoArticulo) ? (guardado as EstadoArticulo) : '');\n    /* Campos nuevos: se leen de `attributes` y de `isNegotiable`. Si el anuncio es antiguo y no los\n       tiene, quedan vacíos y la validación obligará a completarlos al reenviar (no se inventan). */\n    const at = (p.attributes ?? {}) as Record<string, unknown>;\n    const txt = (k: string) => (typeof at[k] === 'string' ? (at[k] as string) : '');\n    setPMarca(txt('marca')); setPModelo(txt('modelo')); setPSku(txt('sku'));\n    setPTalla(txt('talla')); setPColor(txt('color'));\n    setPNegociable(p.isNegotiable !== false);\n    const ent = txt('entrega');\n    setPEntrega(ENTREGAS.some((e) => e.id === ent) ? (ent as FormaEntrega) : '');\n    /* Tanda 4: plazo, devoluciones y documentación ya guardada del anuncio. */\n    setPPlazo(PLAZOS.some((z) => z.horas === p.handlingHours) ? p.handlingHours : 24);\n    setPDevoluciones(p.returnsAccepted === true);\n    setPDocs(\n      (p.docs ?? [])\n        .filter((d) => DOCS.some((x) => x.id === d.docType))\n        .map((d) => ({\n          docType: d.docType as DocTipo, url: d.url,\n          ...(d.docNumber ? { docNumber: d.docNumber } : {}),\n          ...(d.amountXaf !== null && d.amountXaf !== undefined ? { amountXaf: d.amountXaf } : {}),\n          ...(d.issuedOn ? { issuedOn: d.issuedOn } : {}),\n        })),\n    );\n    setPDocTipo(''); setPDocNumero(''); setPDocImporte(''); setPDocFecha(''); setPDocFoto(null);\n    setPAceptaTerminos(false); setPreview(false);\n    scrollRef.current?.scrollTo({ y: 0, animated: true });\n  };\n\n  /**\n   * Corrección de un anuncio rechazado: se llega desde «Anuncios» con `?id=`. Va **después** de\n   * `startEdit` porque lo usa, y espera a tener los productos cargados: si se rellenara antes,\n   * `startEdit` escribiría sobre campos que aún no existen.\n   */\n  const yaRellenado = useRef(false)